                    if (MobUtil.isPlayerLookingTowards(player, minecraft.options.fov().get().floatValue(), wight) && MobUtil.hasVisualLineOfSight(player, wight)){
                        wight.lookTime += 1;

                        if (wight.lookTime >= MathHelper.secondsToTicks(3)){
