@SubscribeEvent
    public static void tickPlayerHazards(TickEvent.PlayerTickEvent event) {
        if (event.side == LogicalSide.CLIENT || event.phase != TickEvent.Phase.END) {
            return;
        }

        Player player = event.player;
        // update the tracker every second, including clearing everything when the config changes.
        if (player.tickCount % 20 != 0) {
            return;
        }

        MedicalConditionTracker tracker = GTCapabilityHelper.getMedicalConditionTracker(player);
        if (tracker == null) {
            return;
        }
        if (!ConfigHolder.INSTANCE.gameplay.hazardsEnabled) {
            for (MedicalCondition medicalCondition : tracker.getMedicalConditions().keySet()) {
                tracker.removeMedicalCondition(medicalCondition);
            }
            return;
        }

        IItemHandler inventory = player.getCapability(ForgeCapabilities.ITEM_HANDLER, null).resolve().orElse(null);
        if (inventory == null) {
            return;
        }

        tracker.tick();

        for (int i = 0; i < inventory.getSlots(); ++i) {
            ItemStack stack = inventory.getStackInSlot(i);
            Either<Material, MaterialEntry> hazardMaterial = HazardProperty.getValidHazardMaterial(stack);
            if (hazardMaterial == null) {
                continue;
            }

            var material = hazardMaterial.map(UnaryOperator.identity(), MaterialEntry::material);

            HazardProperty property = material.getProperty(PropertyKey.HAZARD);
            if (property.hazardTrigger.protectionType().isProtected(player)) {
                // entity has proper safety equipment, so damage it per material every 5 seconds.
                property.hazardTrigger.protectionType().damageEquipment(player, 1);
                // don't progress this material condition if entity is protected
                continue;
            }
            hazardMaterial.ifLeft(m -> tracker.progressRelatedCondition(m, stack.getCount()));
            hazardMaterial.ifRight(m -> tracker.progressRelatedCondition(m, stack.getCount()));
        }
    }

@SubscribeEvent
	public static void onClientTick(TickEvent.ClientTickEvent event)
	{
		Minecraft mc = Minecraft.getMinecraft();

		if (event.phase == TickEvent.Phase.START && mc.world != null && ClientQuestFile.existsWithTeam())
		{
			if (observationTasks == null)
			{
				observationTasks = ClientQuestFile.INSTANCE.collect(ObservationTask.class);
			}

			if (observationTasks.isEmpty())
			{
				return;
			}

			currentlyObserving = null;

			RayMatcher.Data data = RayMatcher.Data.get(mc.world, mc.objectMouseOver);

			for (ObservationTask task : observationTasks)
			{
				if (!task.isComplete(ClientQuestFile.INSTANCE.self) && task.matcher.matches(data) && task.quest.canStartTasks(ClientQuestFile.INSTANCE.self))
				{
					currentlyObserving = task;
					break;
				}
			}

			if (currentlyObserving != null)
			{
				if (!mc.isGamePaused())
				{
					currentlyObservingTime++;
				}

				if (currentlyObservingTime >= currentlyObserving.timer.ticks())
				{
					new MessageSubmitTask(currentlyObserving.id).sendToServer();
					ClientQuestFile.INSTANCE.self.getTaskData(currentlyObserving).addProgress(1L);
					currentlyObserving = null;
					currentlyObservingTime = 0;
				}
			}
			else
			{
				currentlyObservingTime = 0;
			}
		}
	}

@SubscribeEvent
        public static void onClientTick(TickEvent.ClientTickEvent event)
        {
            Player player = Minecraft.getInstance().player;
            if (event.phase == TickEvent.Phase.START && player != null && player.isAlive())
            {
                EntityTempManager.getTemperatureCap(player).ifPresent(icap ->
                {
                    if (!(icap instanceof PlayerTempCap cap)) return;

                    cap.calculateHudVisibility(player);
                    ADVANCED_WORLD_TEMP = cap.showAdvancedWorldTemp();

                    /* World Temp */

                    // Get temperature in actual degrees
                    Temperature.Units units = ConfigSettings.UNITS.get();
                    double worldTemp = cap.getTrait(Temperature.Trait.WORLD);
                    double realTemp = Temperature.convert(worldTemp, Temperature.Units.MC, units, true);
                    // Calculate the blended world temperature for this tick
                    double diff = realTemp - WORLD_TEMP;
                    PREV_WORLD_TEMP = WORLD_TEMP;
                    WORLD_TEMP += Math.abs(diff) <= 1 ? diff : CSMath.maxAbs(diff / ConfigSettings.TEMP_SMOOTHING.get(), 0.25 * CSMath.sign(diff));

                    // Update max/min temps
                    PLAYER_MAX_TEMP = cap.getTrait(Temperature.Trait.BURNING_POINT);
                    PLAYER_MIN_TEMP = cap.getTrait(Temperature.Trait.FREEZING_POINT);

                    /* Body Temp */

                    // Blend body temp (per tick)
                    PREV_BODY_TEMP = BODY_TEMP;
                    BODY_TEMP = BODY_TEMP + (cap.getTrait(Temperature.Trait.BODY) - BODY_TEMP) / 2;

                    // Handle effects for the icon (bobbing, stage, transition)
                    // Get icon bob
                    ICON_BOB = player.tickCount % 3 == 0 && Math.random() < 0.3 ? 1 : 0;

                    // Get the severity of the player's body temperature
                    BODY_TEMP_SEVERITY = getBodySeverity((int) BLEND_BODY_TEMP);

                    // Get the icon to be displayed
                    int neededIcon = ((int) CSMath.clamp(BODY_TEMP_SEVERITY, -4, 4));

                    // Start transition
                    if (BODY_ICON != neededIcon)
                    {   BODY_ICON = neededIcon;
                    }
                });
            }
        }

@SubscribeEvent
    public static void drainCreateBacktank(TickEvent.PlayerTickEvent event)
    {
        Player player = event.player;
        if (!CompatManager.isCreateLoaded()) return;

        ItemStack backTank = player.getItemBySlot(EquipmentSlot.CHEST);
        if (!(backTank.getItem() instanceof BacktankItem)) return;

        double worldTemp = Temperature.get(player, Temperature.Trait.WORLD);
        double minTemp = Temperature.get(player, Temperature.Trait.FREEZING_POINT);
        double maxTemp = Temperature.get(player, Temperature.Trait.BURNING_POINT);

        if (CSMath.betweenExclusive(worldTemp, minTemp, maxTemp)) return;
        if (worldTemp < minTemp && !ConfigSettings.COLD_DRAINS_BACKTANK.get()) return;
        if (worldTemp > maxTemp && !ConfigSettings.HEAT_DRAINS_BACKTANK.get()) return;

        if (USING_BACKTANK && player.level().isClientSide)
        {
            player.getPersistentData().putInt("VisualBacktankAir", Math.round(BacktankUtil.getAllWithAir(player).stream()
                                                                                      .map(BacktankUtil::getAir)
                                                                                      .reduce(0f, Float::sum)) - 1);
        }

        if (player.tickCount % 20 != 0 || event.phase == TickEvent.Phase.START)
        {   return;
        }

        if (!player.isCreative() && !player.isInLava() && backTank.getItem() instanceof BacktankItem)
        {
            // Ensure player is wearing a full set of fire-resistant armor
            List<InsulatorData> drainingInsulators = ConfigHelper.getTaggedConfigsFor(backTank.getItem(), ModInsulatorTags.DRAINS_BACKTANK, ConfigSettings.INSULATING_ARMORS.get());
            if (drainingInsulators.stream().noneMatch(insulator -> insulator.test(player, backTank)))
            {   return;
            }

            if (player.level().isClientSide)
                USING_BACKTANK = true;

            if (CSMath.getIfNotNull(backTank.getTag(), tag -> tag.getInt("Air"), 0) > 0)
            {   // Drain air
                BacktankUtil.consumeAir(player, backTank, 1);
                //Update backtank air status
                if (player.level().isClientSide)
                {
                    player.getPersistentData().putInt("VisualBacktankAir", Math.round(BacktankUtil.getAllWithAir(player).stream()
                                                                                              .map(BacktankUtil::getAir)
                                                                                              .reduce(0f, Float::sum)));
                }
            }
        }
        else if (player.level().isClientSide)
        {   USING_BACKTANK = false;
        }
    }

@SubscribeEvent
    public void onClientTick(TickEvent.ClientTickEvent event) {
        Level world = mc.level;
        Player player = mc.player;

        if (world == null || player == null || TickEvent.Phase.START != event.phase) {
            return;
        }

        updateGuiVisibility();
        ticks++;

        if (ticks % 200 == 0) {
            updateStats();
        }

        if (available && ticks % 20 == 0) {
            if (isSnoozed()) {
                scanner.setStatus(getStatus());
            } else {
                scanner.setStatus(null);
            }
        }

        if (available && ticks % 2 == 0 && !isSnoozed()) {
            int offset = (ticks / 2) % (int) (horizontalSpread * 2 * cooldown);
            if (offset < horizontalSpread * 2) {
                int yawOffset = (int) ((-horizontalSpread + offset) * ScannerBarGui.getDegreesPerUnit());
                if (offset % 2 == 0) {
                    if (verticalSpread > 0) {
                        upHighlight = IntStream.range(0, verticalSpread)
                                .map(i -> i * -5 - 25)
                                .mapToObj(pitch -> getPositions(player, world, pitch, yawOffset))
                                .filter(result -> result.getType() != HitResult.Type.MISS)
                                .map(BlockHitResult::getBlockPos)
                                .findAny()
                                .orElse(null);
                        scanner.highlightUp(offset / 2, upHighlight != null);
                        if (upHighlight != null) {
                            sound.activate();
                        }

                        downHighlight = IntStream.range(0, verticalSpread)
                                .map(i -> i * 5 + 25)
                                .mapToObj(pitch -> getPositions(player, world, pitch, yawOffset))
                                .filter(result -> result.getType() != HitResult.Type.MISS)
                                .map(BlockHitResult::getBlockPos)
                                .findAny()
                                .orElse(null);
                        scanner.highlightDown(offset / 2, downHighlight != null);
                        if (downHighlight != null) {
                            sound.activate();
                        }
                    }
                } else if (offset / 2 < horizontalSpread - 1) {
                    midHighlight = IntStream.range(-1, 2)
                            .map(i -> i * 10)
                            .mapToObj(pitch -> getPositions(player, world, pitch, yawOffset))
                            .filter(result -> result.getType() != HitResult.Type.MISS)
                            .map(BlockHitResult::getBlockPos)
                            .findAny()
                            .orElse(null);

                    scanner.highlightMid(offset / 2, midHighlight != null);
                    if (midHighlight != null) {
                        sound.activate();
                    }

                }
            }
        }
    }

@SubscribeEvent
    public static void applyArmorInsulation(TickEvent.PlayerTickEvent event)
    {
        Player player = event.player;
        if (event.phase == TickEvent.Phase.END && player instanceof ServerPlayer serverPlayer
        && player.tickCount % 20 == 0 && !player.level().isClientSide)
        {
            AtomicInteger fullyInsulatedSlots = new AtomicInteger(0);
            Map<String, Double> armorInsulation = new HashMap<>();

            double worldTemp = Temperature.get(player, Temperature.Trait.WORLD);
            double minTemp = Temperature.get(player, Temperature.Trait.FREEZING_POINT);
            double maxTemp = Temperature.get(player, Temperature.Trait.BURNING_POINT);

            for (ItemStack armorStack : player.getArmorSlots())
            {
                if (armorStack.getItem() instanceof ArmorItem)
                {
                    // Add the armor's built-in insulation value
                    applyBuiltinArmorInsulation(armorInsulation, armorStack, player, worldTemp, minTemp, maxTemp);
                    // Add the armor's insulation value from the Sewing Table
                    applySewnArmorInsulation(armorInsulation, armorStack, player, worldTemp, minTemp, maxTemp, fullyInsulatedSlots);

                    // Add the armor's defense value to the insulation value.
                    double armorAmount = armorStack.getAttributeModifiers(LivingEntity.getEquipmentSlotForItem(armorStack)).entries()
                                         .stream().filter(entry -> entry.getKey().equals(Attributes.ARMOR))
                                         .map(entry -> entry.getValue().getAmount())
                                         .mapToDouble(Double::doubleValue).sum();
                    mapAdd(armorInsulation, "cold_protection", Math.min(armorAmount, 20));
                    mapAdd(armorInsulation, "heat_protection", Math.min(armorAmount, 20));
                }
            }

            // Get insulation from curios
            for (ItemStack curio : CompatManager.Curios.getCurios(player))
            {
                for (InsulatorData insulator : ConfigSettings.INSULATING_CURIOS.get().get(curio.getItem()))
                {
                    if (insulator.test(player, curio))
                    {
                        mapAdd(armorInsulation, "cold_curios", insulator.getCold());
                        mapAdd(armorInsulation, "heat_curios", insulator.getHeat());
                    }
                }
            }

            // Post insulation event
            InsulationTickEvent insulationEvent = new InsulationTickEvent(player, armorInsulation);
            MinecraftForge.EVENT_BUS.post(insulationEvent);
            // Apply final insulation TempModifier
            if (!insulationEvent.isCanceled())
            {
                double cold = insulationEvent.getProperty("cold");
                double heat = insulationEvent.getProperty("heat");

                if (cold > 0 || heat > 0)
                {   Temperature.replaceOrAddModifier(player, new ArmorInsulationTempModifier(cold, heat).tickRate(20).expires(20), Temperature.Trait.RATE, Matcher.SAME_CLASS);
                }
            }

            // Award advancement for full insulation
            if (fullyInsulatedSlots.get() >= 4)
            {
                if (serverPlayer.getServer() != null)
                {
                    Advancement advancement = serverPlayer.getServer().getAdvancements().getAdvancement(new ResourceLocation("cold_sweat:full_insulation"));
                    if (advancement != null)
                    {   serverPlayer.getAdvancements().award(advancement, "requirement");
                    }
                }
            }
        }
    }

@SideOnly(Side.CLIENT)
    @SubscribeEvent
    public void onRenderTickEvent(TickEvent.RenderTickEvent event) {
        ItemStack food = new ItemStack(Items.COOKED_BEEF);
        ItemStack clock = new ItemStack(Items.CLOCK);
        ItemStack compass = new ItemStack(Items.COMPASS);

        int yOffsetString = 18;
        double yOffsetIcon = 16.0;
        String ampm;

        double yBaseIcon;
        int yBaseString;
        if (Config.useGraphicalMeters()) {
            yBaseIcon = 150.0;
            yBaseString = 155;
        } else {
            yBaseIcon = 26.0;
            yBaseString = 32;
        }

        if (event.phase == TickEvent.Phase.END) {
            EntityPlayer player = Minecraft.getMinecraft().thePlayer;
            modules = new ArrayList<String>();
            findInstalledModules(player);
            if (player != null && Minecraft.getMinecraft().isGuiEnabled() && MuseItemUtils.modularItemsEquipped(player).size() > 0 && Minecraft.getMinecraft().currentScreen == null) {
                Minecraft mc = Minecraft.getMinecraft();
                ScaledResolution screen = new ScaledResolution(mc);
                for (int i = 0; i < modules.size(); i++) {
                    if (Objects.equals(modules.get(i), AutoFeederModule.MODULE_AUTO_FEEDER)) {
                        int foodLevel = (int) MuseItemUtils.getFoodLevel(player.getItemStackFromSlot(EntityEquipmentSlot.HEAD));
                        String num = MuseStringUtils.formatNumberShort(foodLevel);
                        if (i == 0) {
                            MuseRenderer.drawString(num, 17, yBaseString);
                            MuseRenderer.drawItemAt(-1.0, yBaseIcon, food);
                        } else {
                            MuseRenderer.drawString(num, 17, yBaseString + (yOffsetString * i));
                            MuseRenderer.drawItemAt(-1.0, yBaseIcon + (yOffsetIcon * i), food);
                        }
                    } else if (Objects.equals(modules.get(i), ClockModule.MODULE_CLOCK)) {
                        long time = player.worldObj.provider.getWorldTime();
                        long hour = ((time % 24000) / 1000);
                        if (Config.use24hClock()) {
                            if (hour < 19) {
                                hour += 6;
                            } else {
                                hour -= 18;
                            }
                            ampm = "h";
                        } else {
                            if (hour < 6) {
                                hour += 6;
                                ampm = " AM";
                            } else if (hour == 6) {
                                hour = 12;
                                ampm = " PM";
                            } else if (hour > 6 && hour < 18) {
                                hour -= 6;
                                ampm = " PM";
                            } else if (hour == 18) {
                                hour = 12;
                                ampm = " AM";
                            } else {
                                hour -= 18;
                                ampm = " AM";
                            }
                        }
                        if (i == 0) {
                            MuseRenderer.drawString(hour + ampm, 17, yBaseString);
                            MuseRenderer.drawItemAt(-1.0, yBaseIcon, clock);
                        } else {
                            MuseRenderer.drawString(hour + ampm, 17, yBaseString + (yOffsetString * i));
                            MuseRenderer.drawItemAt(-1.0, yBaseIcon + (yOffsetIcon * i), clock);
                        }
                    } else if (Objects.equals(modules.get(i), CompassModule.MODULE_COMPASS)) {
                        if (i == 0) {
                            MuseRenderer.drawItemAt(-1.0, yBaseIcon, compass);
                        } else {
                            MuseRenderer.drawItemAt(-1.0, yBaseIcon + (yOffsetIcon * i), compass);
                        }
                    } else if (Objects.equals(modules.get(i), WaterTankModule.MODULE_WATER_TANK)) {
                        drawWaterMeter = true;
                    }
                    else if (Objects.equals(modules.get(i), PlasmaCannonModule.MODULE_PLASMA_CANNON)) {
                        drawPlasmaMeter = true;
                    }
                }
                drawMeters(player, screen);
            }
        }
    }

@SubscribeEvent
    public static void PlayerTick(TickEvent.PlayerTickEvent event){
        Player player = event.player;
        if (event.phase == TickEvent.Phase.END) {
            if (ItemHelper.findHelmet(player, ModItems.DARK_HELMET.get())){
                if (ItemConfig.DarkHelmetDarkness.get()) {
                    if (player.getEffect(MobEffects.DARKNESS) != null) {
                        player.removeEffect(MobEffects.DARKNESS);
                    }
                }
                if (ItemConfig.DarkHelmetBlindness.get()) {
                    if (player.getEffect(MobEffects.BLINDNESS) != null) {
                        player.removeEffect(MobEffects.BLINDNESS);
                    }
                }
            }

            Inventory inventory = player.getInventory();

            List<NonNullList<ItemStack>> compartments = ImmutableList.of(inventory.items, inventory.armor, inventory.offhand);

            for (NonNullList<ItemStack> nonnulllist : compartments) {
                for (int i = 0; i < nonnulllist.size(); ++i) {
                    if (!nonnulllist.get(i).isEmpty()) {
                        ItemStack itemStack = nonnulllist.get(i);
                        Item item = itemStack.getItem();
                        if (!(item instanceof IPersist persist) || !persist.isBroken(itemStack)) {
                            if (itemStack.getItem() instanceof ISoulRepair soulRepair) {
                                soulRepair.repairTick(nonnulllist.get(i), player, inventory.selected == i);
                            } else if (itemStack.getItem() instanceof TieredItem tieredItem && tieredItem.getTier() == ModTiers.DARK){
                                ItemHelper.repairTick(itemStack, player, inventory.selected == i);
                            }
                        }
                    }
                }
            }

            if (ItemHelper.armorSet(player, ModArmorMaterials.DARK)){
                if (player.getFoodData().needsFood()){
                    if (player.tickCount % 40 == 0){
                        player.heal(1.0F);
                    }
                }
            }
        }

        AttributeInstance attackSpeed = player.getAttribute(Attributes.ATTACK_SPEED);
        boolean scythe = player.getMainHandItem().getItem() instanceof DarkScytheItem;

        boolean flag0 = scythe && player.getOffhandItem().isEmpty();
        if (attackSpeed != null){
            if (flag0){
                if (!attackSpeed.hasModifier(TWO_HAND_SCYTHE_SPEED_MOD)){
                    attackSpeed.addPermanentModifier(TWO_HAND_SCYTHE_SPEED_MOD);
                }
            } else {
                if (attackSpeed.hasModifier(TWO_HAND_SCYTHE_SPEED_MOD)){
                    attackSpeed.removeModifier(TWO_HAND_SCYTHE_SPEED_MOD);
                }
            }
        }

        boolean flag = CuriosFinder.hasCurio(player, ModItems.GRAVE_GLOVE.get()) && (scythe || player.getMainHandItem().is(ModTags.Items.GRAVE_GLOVE_BOOST));
        if (attackSpeed != null){
            if (flag){
                if (!attackSpeed.hasModifier(GLOVE_SCYTHE_SPEED_MOD)){
                    attackSpeed.addPermanentModifier(GLOVE_SCYTHE_SPEED_MOD);
                }
            } else {
                if (attackSpeed.hasModifier(GLOVE_SCYTHE_SPEED_MOD)){
                    attackSpeed.removeModifier(GLOVE_SCYTHE_SPEED_MOD);
                }
            }
        }

        boolean hammer = player.getMainHandItem().getItem() instanceof HammerItem;

        boolean flag1 = hammer && player.getOffhandItem().isEmpty();
        if (attackSpeed != null){
            if (flag1){
                if (!attackSpeed.hasModifier(TWO_HAND_HAMMER_SPEED_MOD)){
                    attackSpeed.addPermanentModifier(TWO_HAND_HAMMER_SPEED_MOD);
                }
            } else {
                if (attackSpeed.hasModifier(TWO_HAND_HAMMER_SPEED_MOD)){
                    attackSpeed.removeModifier(TWO_HAND_HAMMER_SPEED_MOD);
                }
            }
        }

        boolean flag2 = CuriosFinder.hasCurio(player, ModItems.THRASH_GLOVE.get()) && (hammer || player.getMainHandItem().is(ModTags.Items.THRASH_GLOVE_BOOST));
        if (attackSpeed != null){
            if (flag2){
                if (!attackSpeed.hasModifier(GLOVE_HAMMER_SPEED_MOD)){
                    attackSpeed.addPermanentModifier(GLOVE_HAMMER_SPEED_MOD);
                }
            } else {
                if (attackSpeed.hasModifier(GLOVE_HAMMER_SPEED_MOD)){
                    attackSpeed.removeModifier(GLOVE_HAMMER_SPEED_MOD);
                }
            }
        }

        boolean staff = player.getOffhandItem().getItem() instanceof DarkStaff && ItemConfig.StaffOffhandBuff.get();

        AttributeInstance attackDamage = player.getAttribute(Attributes.ATTACK_DAMAGE);

        if (attackDamage != null){
            if (staff){
                if (!attackDamage.hasModifier(STAFF_ATTACK_BOOST_MOD)){
                    attackDamage.addPermanentModifier(STAFF_ATTACK_BOOST_MOD);
                }
            } else {
                if (attackDamage.hasModifier(STAFF_ATTACK_BOOST_MOD)){
                    attackDamage.removeModifier(STAFF_ATTACK_BOOST_MOD);
                }
            }
        }
        if (MobUtil.starAmuletActive(player)){
            player.getAbilities().flying &= player.isCreative();
        }
    }

@SubscribeEvent
	public static void onPlayerTickEvent(TickEvent.PlayerTickEvent event){

		if(event.phase == TickEvent.Phase.START){

			EntityPlayer player = event.player;
			World world = player.world;

			for(ItemArtefact artefact : getActiveArtefacts(player)){

				if(artefact == WizardryItems.ring_condensing){

					if(player.ticksExisted % 150 == 0){
						for(ItemStack stack : InventoryUtils.getHotbar(player)){
							// Needs to be both of these interfaces because this ring only recharges wands
							// (or more accurately, chargeable spellcasting items)
							if(stack.getItem() instanceof ISpellCastingItem && stack.getItem() instanceof IManaStoringItem)
								((IManaStoringItem)stack.getItem()).rechargeMana(stack, 1);
						}
					}

				}else if(artefact == WizardryItems.amulet_arcane_defence){

					if(player.ticksExisted % 300 == 0){
						for(ItemStack stack : player.getArmorInventoryList()){
							// IManaStoringItem is sufficient, since anything in the armour slots is probably armour
							if(stack.getItem() instanceof IManaStoringItem)
								((IManaStoringItem)stack.getItem()).rechargeMana(stack, 1);
						}
					}

				}else if(artefact == WizardryItems.amulet_recovery){

					if(player.shouldHeal() && player.getHealth() < player.getMaxHealth()/2
						&& player.ticksExisted % 50 == 0){

						int totalArmourMana = Streams.stream(player.getArmorInventoryList())
								.filter(s -> s.getItem() instanceof IManaStoringItem)
								.mapToInt(s -> ((IManaStoringItem)s.getItem()).getMana(s))
								.sum();

						if(totalArmourMana >= 2){
							player.heal(1);
							// 2 mana per half-heart, randomly distributed
							List<ItemStack> chargedArmour = Streams.stream(player.getArmorInventoryList())
									.filter(s -> s.getItem() instanceof IManaStoringItem)
									.filter(s -> !((IManaStoringItem)s.getItem()).isManaEmpty(s))
									.collect(Collectors.toList());

							if(chargedArmour.size() == 1){
								((IManaStoringItem)chargedArmour.get(0).getItem()).consumeMana(chargedArmour.get(0), 2, player);
							}else{
								Collections.shuffle(chargedArmour);
								((IManaStoringItem)chargedArmour.get(0).getItem()).consumeMana(chargedArmour.get(0), 1, player);
								((IManaStoringItem)chargedArmour.get(1).getItem()).consumeMana(chargedArmour.get(1), 1, player);
							}
						}
					}

				}else if(artefact == WizardryItems.amulet_glide){
					// This should be a chance per fall, so we can't just check fall distance is greater than 3 each tick
					// Based on a stationary start and a gravity acceleration of 0.02 blocks/tick^2, at 3 blocks of fall
					// distance the player should be falling at about 0.35b/t, so 0.5 blocks should be enough of a window
					if(player.fallDistance > 3f && player.fallDistance < 3.5f && player.world.rand.nextFloat() < 0.5f){
						if(!WizardData.get(player).isCasting()) WizardData.get(player).startCastingContinuousSpell(Spells.glide, new SpellModifiers(), 600);
					}else if(player.onGround){
						WizardData data = WizardData.get(player);
						if(data.currentlyCasting() == Spells.glide) data.stopCastingContinuousSpell();
					}

				}else if(artefact == WizardryItems.amulet_auto_shield){

					findMatchingWandAndExecute(player, Spells.shield, wand -> {

						if(wand.getItem() instanceof ItemScroll) return; // Ignore scrolls since they shouldn't work

						List<Entity> projectiles = EntityUtils.getEntitiesWithinRadius(5, player.posX, player.posY, player.posZ, world, Entity.class);
						projectiles.removeIf(e -> !(e instanceof IProjectile));
						Vec3d look = player.getLookVec();
						Vec3d playerPos = player.getPositionVector().add(0, player.height/2, 0);

						for(Entity projectile : projectiles){
							Vec3d vec = playerPos.subtract(projectile.getPositionVector()).normalize();
							double angle = Math.acos(vec.scale(-1).dotProduct(look));
							if(angle > Math.PI * 0.4f) continue; // (Roughly) the angle the shield will protect
							Vec3d velocity = new Vec3d(projectile.motionX, projectile.motionY, projectile.motionZ).normalize();
							double angle1 = Math.acos(vec.dotProduct(velocity));
							if(angle1 < Math.PI * 0.2f){
								SpellModifiers modifiers = new SpellModifiers();
								if(((ISpellCastingItem)wand.getItem()).canCast(wand, Spells.shield, player, EnumHand.MAIN_HAND, 0, modifiers)){
									((ISpellCastingItem)wand.getItem()).cast(wand, Spells.shield, player, EnumHand.MAIN_HAND, 0, modifiers);
								}
								break;
							}
						}
					});

				}else if(artefact == WizardryItems.amulet_frost_warding){

					if(!world.isRemote && player.ticksExisted % 40 == 0){

						List<EntityIceBarrier> barriers = world.getEntitiesWithinAABB(EntityIceBarrier.class, player.getEntityBoundingBox().grow(1.5));

						// Check whether any barriers near the player are facing away from them, meaning the player is behind them
						if(!barriers.isEmpty() && barriers.stream().anyMatch(b -> b.getLookVec().dotProduct(b.getPositionVector().subtract(player.getPositionVector())) > 0)){
							player.addPotionEffect(new PotionEffect(WizardryPotions.ward, 50, 1));
						}

					}

				}else if(artefact == WizardryItems.charm_feeding){
					// Every 5 seconds, feed the player if they are hungry enough
					if(player.ticksExisted % 100 == 0){
						if(player.getFoodStats().getFoodLevel() < 20 - Spells.satiety.getProperty(Satiety.HUNGER_POINTS).intValue()){
							if(findMatchingWandAndCast(player, Spells.satiety)) continue;
						}
						if(player.getFoodStats().getFoodLevel() < 20 - Spells.replenish_hunger.getProperty(ReplenishHunger.HUNGER_POINTS).intValue()){
							findMatchingWandAndCast(player, Spells.replenish_hunger);
						}
					}
				}
			}
		}
	}

@Override
    public void onInitialize() {
        ServerLifecycleEvents.SERVER_STARTING.register(ServerInstanceHolder::setInstance);
        ServerLifecycleEvents.SERVER_STOPPED.register(server -> ServerInstanceHolder.setInstance(() -> null));

        Accessories.init();

        AccessoriesNetworking.init();

        SyncedDataHelperManager.init(AccessoriesNetworking.CHANNEL, playerConsumer -> {
            ResourceLocation beforeDefaultPhase = Accessories.of("before_default_phase");

            ServerLifecycleEvents.SYNC_DATA_PACK_CONTENTS.addPhaseOrdering(beforeDefaultPhase, Event.DEFAULT_PHASE);

            ServerLifecycleEvents.SYNC_DATA_PACK_CONTENTS.register(beforeDefaultPhase, (player, joined) -> playerConsumer.accept(player));
        });

        AccessoriesDataComponents.init();

        AccessoriesMenuTypes.registerMenuType();
        Accessories.registerCriteria();
        CommandGenerators.registerAllArgumentTypes(new ArgumentRegistrationCallback() {
            @Override
            public <A extends ArgumentType<?>, T> RecordArgumentTypeInfo<A, T> register(ResourceLocation location, Class<A> clazz, RecordArgumentTypeInfo<A, T> info) {
                ArgumentTypeRegistry.registerArgumentType(location, clazz, info);

                return info;
            }
        });

        CommandRegistrationCallback.EVENT.register(CommandGenerators::registerAllGenerators);

        UseItemCallback.EVENT.register((player, level, hand) -> {
            //if (level.isClientSide) return InteractionResult.PASS;

            var holder = AccessoriesEventHandler.attemptEquipFromUse(player, hand);

            if (holder instanceof InteractionResult.Success && level.isClientSide()) {
                return InteractionResult.SUCCESS;
            }

            //TODO: CONFIRM IF THIS IS CORRECT!
            if(holder instanceof InteractionResult.Success success) {
                var stack = Objects.requireNonNullElse(success.heldItemTransformedTo(), player.getItemInHand(hand));

                player.setItemInHand(hand, stack);
            }

            return holder;
        });

        UseEntityCallback.EVENT.register((player, level, hand, entity, hitResult) -> AccessoriesEventHandler.attemptEquipOnEntity(player, hand, entity));

        ServerTickEvents.START_WORLD_TICK.register(AccessoriesEventHandler::onWorldTick);

        ServerLifecycleEvents.SYNC_DATA_PACK_CONTENTS.register((player, joined) -> {
            if(!joined) return;

            AccessoriesEventHandler.dataSync(null, player);
        });

        ServerLifecycleEvents.SERVER_STARTED.register(server -> {
            for (EntityType<?> entityType : BuiltInRegistries.ENTITY_TYPE) {
                var lookup = CAPABILITY;

                if(lookup.getProvider(entityType) != null) continue;

                lookup.registerForType((entity, unused) -> {
                    if(!(entity instanceof LivingEntity livingEntity)) return null;

                    var slots = EntitySlotLoader.getEntitySlots(livingEntity);

                    if(slots.isEmpty()) return null;

                    return new AccessoriesCapabilityImpl(livingEntity);
                }, entityType);
            }
        });

        ServerEntityEvents.ENTITY_LOAD.register((entity, world) -> {
            if(!(entity instanceof LivingEntity livingEntity)) return;

            AccessoriesEventHandler.entityLoad(livingEntity, world);
        });

        ExtraEntityTrackingEvents.POST_START_TRACKING.register((trackedEntity, player) -> {
            if(!(trackedEntity instanceof LivingEntity livingEntity)) return;

            AccessoriesEventHandler.onTracking(livingEntity, player);
        });

        ResourceLoader.get(PackType.SERVER_DATA)
            .registerReloader(
                Accessories.DATA_RELOAD_HOOK,
                (ResourceManagerReloadListener) manager -> AccessoriesEventHandler.dataReloadOccurred = true
            );

        DefaultItemComponentEvents.MODIFY.register(context -> {
            AccessoriesEventHandler.setupItems(new AccessoriesEventHandler.AddDataComponentCallback() {
                @Override
                public <T> void addTo(Item item, DataComponentType<T> componentType, T component) {
                    context.modify(item, builder -> builder.set(componentType, component));
                }
            });
        });

        ServerEntityWorldChangeEvents.AFTER_PLAYER_CHANGE_WORLD.register((player, origin, destination) -> {
            AccessoriesNetworking.CHANNEL.serverHandle(player).send(new InvalidateEntityCache(player.getId()));

            AccessoriesEventHandler.onTracking(player, player);
        });

        var afterDefault = Accessories.of("after_default");

        ServerPlayerEvents.AFTER_RESPAWN.addPhaseOrdering(Event.DEFAULT_PHASE, afterDefault);

        ServerPlayerEvents.AFTER_RESPAWN.register(afterDefault, (oldPlayer, newPlayer, alive) -> {
            // Required due to mods possibly causing a desync between server and client as transfer of data attachments may have not occured yet
            // as fabric dose such after respawn which is after entity load event
            SyncEntireContainer.syncToAllTrackingAndSelf(newPlayer);
        });

        Reflection.initialize(AccessoriesGameRules.class);
    }

@SubscribeEvent
    public static void onPlayerTick(TickEvent.PlayerTickEvent event){
        Player player = event.player;
        Level world = player.level;
        ISoulEnergy soulEnergy = SEHelper.getCapability(player);
        if (event.phase == TickEvent.Phase.END) {
            SEHelper.getFocusCoolDown(player).tick(player, world);
            if (player.onGround()){
                if (SEHelper.getTicksInAir(player) > 0) {
                    SEHelper.setTicksInAir(player, 0);
                }
                if (SEHelper.getAirJumps(player) > 0) {
                    SEHelper.setAirJumps(player, 0);
                }
                if (SEHelper.getAirJumpCooldown(player) > 0) {
                    SEHelper.setAirJumpCooldown(player, 0);
                }
            } else {
                SEHelper.setTicksInAir(player, SEHelper.getTicksInAir(player) + 1);
            }
            if (SEHelper.getAirJumpCooldown(player) > 0) {
                SEHelper.setAirJumpCooldown(player, SEHelper.getAirJumpCooldown(player) - 1);
            }
            if (SEHelper.getRestPeriod(player) > 0) {
                SEHelper.decreaseRestPeriod(player, 1);
            }
            if (SEHelper.hasResearch(player, ResearchList.FORBIDDEN)){
                if (!SEHelper.hasResearch(player, ResearchList.BURIED)){
                    SEHelper.addResearch(player, ResearchList.BURIED);
                }
            }
            if (!soulEnergy.getSEActive() && soulEnergy.getSoulEnergy() > 0) {
                if (!world.isClientSide){
                    player.addEffect(new MobEffectInstance(GoetyEffects.SOUL_HUNGER.get(), 60));
                    if (player.tickCount % 5 == 0) {
                        SEHelper.decreaseSESouls(player, 1);
                        SEHelper.sendSEUpdatePacket(player);
                    }
                }
            }
            if (!player.isUsingItem() || !(WandUtil.getSpell(player) instanceof BurrowingSpell)) {
                BurrowingSpell.resetMiningProgress(world, player);
            }
        }
        if (soulEnergy.getArcaBlock() != null){
            if (soulEnergy.getArcaBlockDimension() == world.dimension()) {
                if (!world.isClientSide){
                    ServerLevel serverWorld = (ServerLevel) world;
                    BlockPos blockPos = soulEnergy.getArcaBlock();
                    BlockEntity tileEntity = world.getBlockEntity(blockPos);
                    if (tileEntity instanceof ArcaBlockEntity arcaTile) {
                        if (arcaTile.getPlayer() == player) {
                            RandomSource pRand = world.random;
                            if (pRand.nextInt(12) == 0) {
                                for (int i = 0; i < 3; ++i) {
                                    int j = pRand.nextInt(2) * 2 - 1;
                                    int k = pRand.nextInt(2) * 2 - 1;
                                    double d0 = (double) blockPos.getX() + 0.5D + 0.25D * (double) j;
                                    double d1 = (float) blockPos.getY() + pRand.nextFloat();
                                    double d2 = (double) blockPos.getZ() + 0.5D + 0.25D * (double) k;
                                    double d3 = pRand.nextFloat() * (float) j;
                                    double d4 = ((double) pRand.nextFloat() - 0.5D) * 0.125D;
                                    double d5 = pRand.nextFloat() * (float) k;
                                    serverWorld.sendParticles(ParticleTypes.ENCHANT, d0, d1, d2, 0, d3, d4, d5, 1.0F);
                                }
                            }
                            if (!soulEnergy.getSEActive()) {
                                soulEnergy.setSEActive(true);
                                SEHelper.sendSEUpdatePacket(player);
                            }
                        } else {
                            if (soulEnergy.getSEActive()) {
                                soulEnergy.setSEActive(false);
                                SEHelper.sendSEUpdatePacket(player);
                            }
                        }
                    } else {
                        if (soulEnergy.getSEActive()) {
                            soulEnergy.setSEActive(false);
                            SEHelper.sendSEUpdatePacket(player);
                        }
                    }
                }
            } else if (soulEnergy.getArcaBlockDimension() == null){
                soulEnergy.setArcaBlockDimension(world.dimension());
                SEHelper.sendSEUpdatePacket(player);
            }
        }
        if (world instanceof ServerLevel) {
            if (soulEnergy.getCameraUUID() != null){
                Entity entity = EntityFinder.getEntityByUuiD(soulEnergy.getCameraUUID());
                if (entity == null || !entity.isAlive()
                        || entity.level.dimension() != player.level.dimension()
                        || player.isShiftKeyDown() || player.hurtTime > 0
                        || !player.isAlive()){
                    SEHelper.setCamera(player, null);
                }
            }
            soulEnergy.grudgeList().removeIf(uuid -> {
                Entity entity = EntityFinder.getLivingEntityByUuiD(uuid);
                return (entity instanceof Mob mob && (!mob.isAlive() || mob.isRemoved()));
            });
            soulEnergy.allyList().removeIf(uuid -> {
                Entity entity = EntityFinder.getLivingEntityByUuiD(uuid);
                return (entity instanceof Mob mob && (!mob.isAlive() || mob.isRemoved()));
            });
        }
        if (soulEnergy.getSoulEnergy() < 0){
            soulEnergy.setSoulEnergy(0);
        }
        if (soulEnergy.getGrappling() instanceof VineHook vineHook && vineHook.isAttached()) {
            if (vineHook.isStaff()) {
                player.resetFallDistance();
            }
            Vec3 vec3 = vineHook.position().subtract(player.getEyePosition());
            float f = vineHook.getLength();
            double d = vec3.length();
            if (d > (double)f) {
                double e = d / (double)f * 0.1D;
                player.setDeltaMovement(player.getDeltaMovement().add(vec3.scale(1.0 / d).multiply(e, e * 1.1, e)));
            }
        }
        if (!MobUtil.isSpellCasting(player) && soulEnergy.maxWarding() > 0){
            soulEnergy.setMaxWarding(0);
            soulEnergy.setWarding(0);
        }
    }

@SubscribeEvent
    public static void onPlayerLichdom(TickEvent.PlayerTickEvent event){
        Player player = event.player;
        Level world = player.level;
        if (LichdomHelper.isLich(player)){
            player.getFoodData().setFoodLevel(17);
            player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_REST));
            boolean burn = MobUtil.isInSunlightNoRain(player);

            if (!player.level.isClientSide) {
                if (burn){
                    ItemStack helmet = player.getItemBySlot(EquipmentSlot.HEAD);
                    if (!helmet.isEmpty()) {
                        if (!player.isCreative()) {
                            if (!MobUtil.isFireImmune(player)) {
                                if (MainConfig.LichDamageHelmet.get()) {
                                    if (helmet.isDamageableItem()) {
                                        ItemHelper.hurtAndBreak(helmet, world.random.nextInt(2), player);
                                    }
                                }
                            }
                        }
                        burn = false;
                    }
                    if (burn){
                        if (!MobUtil.isFireImmune(player)){
                            player.setSecondsOnFire(8);
                        }
                    }
                }
            }

            player.getActiveEffects().removeIf(effectInstance -> !EffectsUtil.canAffectLich(effectInstance, world));
            if (player.hasEffect(GoetyEffects.SOUL_HUNGER.get())){
                if (SEHelper.getSoulsAmount(player, MainConfig.MaxSouls.get())){
                    player.removeEffect(GoetyEffects.SOUL_HUNGER.get());
                }
            }
            if (MainConfig.LichSoulHeal.get()) {
                if (!(player.isOnFire() && !MobUtil.isFireImmune(player)) && LichdomHelper.smited(player) <= 0) {
                    if (player.getHealth() < player.getMaxHealth()) {
                        if (player.tickCount % (MathHelper.secondsToTicks(MainConfig.LichHealSeconds.get()) + 1) == 0 && SEHelper.getSoulsAmount(player, MainConfig.LichHealCost.get())) {
                            player.heal(MainConfig.LichHealAmount.get().floatValue());
                            Vec3 vector3d = player.getDeltaMovement();
                            if (!player.level.isClientSide) {
                                ServerLevel serverWorld = (ServerLevel) player.level;
                                serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, player.getRandomX(0.5D), player.getRandomY(), player.getRandomZ(0.5D), 0, vector3d.x * -0.2D, 0.1D, vector3d.z * -0.2D, 0.5F);
                            }
                            SEHelper.decreaseSouls(player, MainConfig.LichHealCost.get());
                        }
                    }
                }
            }
            if (MainConfig.LichVillagerHate.get() && player.tickCount % 20 == 0) {
                for (Villager villager : player.level.getEntitiesOfClass(Villager.class, player.getBoundingBox().inflate(16.0D))) {
                    if (villager.getPlayerReputation(player) > -200 && villager.getPlayerReputation(player) < 100) {
                        villager.getGossips().add(player.getUUID(), GossipType.MAJOR_NEGATIVE, 25);
                    }
                }
                for (IronGolem ironGolem : player.level.getEntitiesOfClass(IronGolem.class, player.getBoundingBox().inflate(16.0D))) {
                    if (!ironGolem.isPlayerCreated() && ironGolem.getTarget() != player && TargetingConditions.forCombat().range(16.0F).test(ironGolem, player)) {
                        ironGolem.setTarget(player);
                    }
                }
            }
            if (LichdomHelper.isInLichMode(player)) {
                if (player.tickCount % 5 == 0) {
                    if (world.isClientSide) {
                        int color = LichdomHelper.lichModeColor(player);
                        if (color > -1) {
                            ColorUtil colorUtil = new ColorUtil(color);
                            world.addParticle(ModParticleTypes.LICH_COLORED.get(), player.getRandomX(0.5D), player.getY(), player.getRandomZ(0.5D), colorUtil.red(), colorUtil.green(), colorUtil.blue());
                        } else {
                            world.addParticle(ModParticleTypes.LICH.get(), player.getRandomX(0.5D), player.getY(), player.getRandomZ(0.5D), 0.0D, 0.0D, 0.0D);
                        }
                    }
                }
                if (MainConfig.LichModeSounds.get()) {
                    if (event.phase == TickEvent.Phase.END) {
                        if (player.isAlive()) {
                            MiscCapHelper.doAmbientSoundTime(player);
                            if (MiscCapHelper.getAmbientSoundTime(player) > player.getRandom().nextInt(1000)) {
                                MiscCapHelper.setAmbientSoundTime(player, -MathHelper.secondsToTicks(4));
                                if (!player.level.isClientSide) {
                                    ModNetwork.sentToTrackingEntityAndPlayer(player, new SPlayFollowSoundPacket(player, ModSounds.LICH_AMBIENT.get(), 1.0F, player.getVoicePitch(), false));
                                }
                            }
                        }
                    }
                }
            }
            if (player.isAlive()){
                if (!player.level.isClientSide) {
                    MobEffectInstance instance = player.getEffect(MobEffects.NIGHT_VISION);
                    if (LichdomHelper.nightVision(player) && MainConfig.LichNightVision.get()) {
                        if (instance == null || instance.getDuration() <= 210) {
                            player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, 300, 0, false, false, false));
                        }
                    } else {
                        if (instance != null) {
                            if (instance.getDuration() <= 300) {
                                player.removeEffect(MobEffects.NIGHT_VISION);
                            }
                        }
                    }
                }
            }
            if (LichdomHelper.smited(player) > 0){
                LichdomHelper.setSmited(player, LichdomHelper.smited(player) - 1);
            }
        } else {
            if (LichdomHelper.isInLichMode(player)) {
                LichdomHelper.setLichMode(player, false);
            }
            if (LichdomHelper.nightVision(player)) {
                LichdomHelper.setNightVision(player, false);
            }
        }

        if (IronLoaded.IRON_SPELLBOOKS.isLoaded()){
            AttributeInstance bloodResist = player.getAttribute(IronAttributes.BLOOD_MAGIC_RESIST);
            if (bloodResist != null){
                if (LichdomHelper.isLich(player)){
                    if (!bloodResist.hasModifier(BLOOD_RESIST_MOD)){
                        bloodResist.addPermanentModifier(BLOOD_RESIST_MOD);
                    }
                } else {
                    if (bloodResist.hasModifier(BLOOD_RESIST_MOD)){
                        bloodResist.removeModifier(BLOOD_RESIST_MOD);
                    }
                }
            }

            AttributeInstance holyResist = player.getAttribute(IronAttributes.HOLY_MAGIC_RESIST);
            if (holyResist != null){
                if (LichdomHelper.isLich(player)){
                    if (!holyResist.hasModifier(HOLY_WEAK_MOD)){
                        holyResist.addPermanentModifier(HOLY_WEAK_MOD);
                    }
                } else {
                    if (holyResist.hasModifier(HOLY_WEAK_MOD)){
                        holyResist.removeModifier(HOLY_WEAK_MOD);
                    }
                }
            }
        }
    }

