private static boolean isPendingLinker(ItemStack stack) {
		EnderLinkPendingCraftData pendingCraft = stack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		return LinkedStorageStackLifecycle.classifyLinker(stack) == EnderLinkerStackState.PENDING_CRAFT && pendingCraft.resolvesToLinkerTarget();
	}

public static EnderLinkPendingCraftPlan fromSerializedName(String serializedName) {
		return Arrays.stream(values()).filter(plan -> plan.serializedName.equals(serializedName)).findFirst()
				.orElseThrow(() -> new IllegalStateException("Unknown pending Ender Linker craft plan " + serializedName));
	}

public static boolean hasBoundPresentation(ItemStack stack) {
		EnderLinkerStackState state = LinkedStorageStackLifecycle.classifyLinker(stack);
		return state == EnderLinkerStackState.TARGET || isPendingLinker(stack, state);
	}

private static boolean isPendingLinker(ItemStack stack, EnderLinkerStackState state) {
		return stack.getItem() instanceof EnderLinkerItem && state == EnderLinkerStackState.PENDING_CRAFT
				&& stack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT).resolvesToLinkerTarget();
	}

