		EnderLinkPendingCraftData craftedPending = craftedStack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		EnderLinkPendingCraftData stackPending = stack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
