private void updateCookingCooldown(Level level) {
		if (getRemainingCookTime(level) + 2 > getCookTimeTotal()) {
			setIsCooking(false);
		} else {
			setCookTimeFinish(level.getGameTime() + Math.min(getRemainingCookTime(level) + 2, getCookTimeTotal()));
		}
	}

private float getProgress(long finishTime, int timeTotal) {
		Level level = Minecraft.getInstance().level;
		if (level == null) {
			return 0;
		}
		return 1 - ((float) Math.max(finishTime - level.getGameTime(), 0) / timeTotal);
	}

private float getPlaybackRemainingProgress() {
			long finishTime = getContainer().getDiscFinishTime();
			int remaining = (int) (finishTime - minecraft.level.getGameTime());

			ItemStack disc = getContainer().getUpgradeWrapper().getDisc();
			return DiscHandlerRegistry.getMusicLengthInTicks(disc, minecraft.level).map(lengthInTicks -> remaining / (float) lengthInTicks).orElse(0f);
		}

private boolean isInCooldown(Level level, @Nullable Entity entity) {
		if (!(entity instanceof Player)) {
			return super.isInCooldown(level);
		}

		return nextTickTime > level.getGameTime();
	}

