protected boolean isSoundReady(Player player) {
    int lastSound = lastSoundTick.getOrDefault(player.getUUID(), 0);
    if (lastSound < player.tickCount) {
      lastSoundTick.put(player.getUUID(), player.tickCount);
      return true;
    }
    return false;
  }

