private void wobble(long gameTime, double angle) {
			lastUpdateTick = gameTime;
			double d0 = angle - rotation;
			d0 = Mth.positiveModulo(d0 + 0.5D, 1.0D) - 0.5D;
			rota += d0 * 0.1D;
			rota *= 0.8D;
			rotation = Mth.positiveModulo(rotation + rota, 1.0D);
		}

