public boolean trySteering(LivingEntity rider) {
        if (rider.getItemInHand(InteractionHand.MAIN_HAND).is(ModItems.WHIP.get())) {
            lastSeenWhipTicks = 0;
        } else {
            lastSeenWhipTicks++;
        }

        return lastSeenWhipTicks < FOLLOW_TIME_WITHOUT_WHIP;
    }

