public static void clearPendingCraftClaim(ServerLevel level, Container inventory) {
		ItemStack linker = getLinker(inventory.getContainerSize(), inventory::getItem);
		EnderLinkPendingCraftData pendingCraft = linker.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null) {
			return;
		}
		if (pendingCraft.claimId() == null || !LinkedStorageGroupsSavedData.get(level).manager().consumeActivePendingCraftClaim(pendingCraft.claimId())) {
			throw new IllegalStateException("Could not clear pending Ender Linker craft claim");
		}
	}

private static ItemStack findTransferredCraftResult(UUID claimId, IItemHandler inventory) {
		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ItemStack stack = inventory.getStackInSlot(slot);
			EnderLinkPendingCraftData pendingCraft = stack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
			if (pendingCraft != null && claimId.equals(pendingCraft.claimId())) {
				return stack;
			}
		}
		return ItemStack.EMPTY;
	}

public static void updateKeepAlive(UUID storageUuid, Level level, Vec3 position, Runnable onNoLongerRunning) {
		ResourceKey<Level> dim = level.dimension();
		if (!worldStorageSoundInfos.containsKey(dim) || !worldStorageSoundInfos.get(dim).containsKey(storageUuid)) {
			onNoLongerRunning.run();
			return;
		}
		if (worldStorageSoundInfos.get(dim).containsKey(storageUuid)) {
			worldStorageSoundInfos.get(dim).get(storageUuid).update(level.getGameTime(), position);
		}
	}

