private void resolveFluidIngredients() {
        for (Pair<FluidIngredient, Integer> pair : pendingIngredients) {
            for (FluidStack fluidStack: pair.getLeft().getStacks()) {
                Fluid fluid = fluidStack.getFluid();
                if (fluid.isSource(fluid.defaultFluidState()) && fluidStack.getAmount() > 0) {
                    registerXPFluid(fluid, pair.getRight());
                }
            }
        }
    }

private void onFluidChange(FluidStack newFluid) {
        // we can update the gui-synced value every tick
        syncedFluidStackGui = newFluid.copy();

        // more careful checking for the desc-synced value
        int delta = Math.abs(syncedFluidStackDesc.getAmount() - newFluid.getAmount());
        if (delta >= threshold || syncedFluidStackDesc.getFluid() != newFluid.getFluid()) {
            deferredSync(ConfigHelper.common().advanced.fluidTankUpdateRate.get());
        }
    }

private boolean doLogistics() {
        ItemStack item = drone.getInv().getStackInSlot(0);
        FluidStack fluid = drone.getFluidTank().getFluid();
        PriorityQueue<LogisticsTask> tasks = getLogisticsManager().getTasks(item.isEmpty() ? fluid : item, true);
        if (!tasks.isEmpty()) {
            curTask = tasks.poll();
            return execute(curTask);
        }
        return false;
    }

