public boolean canPossessTargetEntity(Entity entity) {
        if (entity instanceof Player player) {
            CompoundTag playerData = player.getPersistentData();
            CompoundTag data = playerData.getCompound(Player.PERSISTED_NBT_TAG);
            if (data != null) {
                long timeElapsed = level().getGameTime() - data.getLong(LAST_POSSESSED_TIME_IDENTIFIER);
                return timeElapsed >= AlexsCaves.COMMON_CONFIG.watcherPossessionCooldown.get();
            }
        }
        return true;
    }

private void jumpUnderwater() {
        BlockPos pos = this.getOnPos();
        if(this.level().isWaterAt(pos) && !this.level().isWaterAt(pos.above())){
            this.setPos(this.getX(), this.getY() + 1, this.getZ());
            this.level().setBlockAndUpdate(pos, Blocks.FROSTED_ICE.defaultBlockState());
            this.level().scheduleTick(pos, Blocks.FROSTED_ICE, Mth.nextInt(this.getRandom(), 60, 120));
        }
        double d0 = 0.2F;
        Vec3 vec3 = this.getDeltaMovement();
        this.setDeltaMovement(vec3.x, d0, vec3.z);
    }

