public void deactivateLastVisitedContact(MovementContext context) {
		if (!context.data.contains("lastContact"))
			return;

		BlockPos last = NBTHelper.readBlockPos(context.data, "lastContact");
		context.data.remove("lastContact");
		BlockState blockState = context.world.getBlockState(last);

		if (AllBlocks.REDSTONE_CONTACT.has(blockState))
			context.world.scheduleTick(last, AllBlocks.REDSTONE_CONTACT.get(), 1, TickPriority.NORMAL);
	}

public void serialize(CompoundTag tagIn) {
		CompoundTag tag = new CompoundTag();
		tag.putInt("Offset", offset);
		tag.put("Sources", NBTHelper.writeCompoundList(sources.entries(), e -> {
			CompoundTag c = new CompoundTag();
			c.putInt("Tick", e.getKey());
			c.put("Pos", NbtUtils.writeBlockPos(e.getValue()));
			return c;
		}));
		tagIn.put("SoundQueue", tag);
	}

@Override
	public void onPlace(BlockState pState, Level pLevel, BlockPos pPos, BlockState pOldState, boolean pIsMoving) {
		if (pOldState.getBlock() == this && pState.setValue(HAS_BE, true) == pOldState.setValue(HAS_BE, true))
			return;
		if (pLevel.isClientSide)
			return;
		LevelTickAccess<Block> blockTicks = pLevel.getBlockTicks();
		if (!blockTicks.hasScheduledTick(pPos, this))
			pLevel.scheduleTick(pPos, this, 1);
		updateGirders(pState, pLevel, pPos, blockTicks);
	}

public void addConnection(BezierConnection connection) {
		// don't replace existing connections with different materials
		if (connections.containsKey(connection.getKey()) && connection.equalsSansMaterial(connections.get(connection.getKey())))
			return;
		connections.put(connection.getKey(), connection);
		level.scheduleTick(worldPosition, getBlockState().getBlock(), 1);
		notifyUpdate();

		if (connection.isPrimary())
			manageFakeTracksAlong(connection, false);
	}

protected void read(CompoundTag tag, HolderLookup.Provider registries, boolean clientPacket) {
		if (firstNbtRead) {
			firstNbtRead = false;
			ArrayList<BlockEntityBehaviour> list = new ArrayList<>();
			addBehavioursDeferred(list);
			list.forEach(b -> behaviours.put(b.getType(), b));
			NeoForge.EVENT_BUS.post(new BlockEntityBehaviourEvent(this, behaviours));
		}
		super.loadAdditional(tag, registries);
		forEachBehaviour(tb -> tb.read(tag, registries, clientPacket));
	}

