private Set<String> getAccessoriesSlotTags(Player player) {
		long gameTime = player.level().getGameTime();
		if (lastTagsRefresh + TAGS_REFRESH_COOLDOWN < gameTime) {
			lastTagsRefresh = gameTime;
			containerNames.clear();

			containerNames
					.addAll(AccessoriesCapability.getOptionally(player).map(capability -> capability.getContainers().keySet()).orElse(Collections.emptySet()));
		}
		return containerNames;
	}

@Override
	public void inventoryTick(ItemStack tome, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 10 != 0 || !isEnabled(tome)
				|| getCharge(tome) == getChargeLimit()) {
			return;
		}

		for (AlkahestryChargingRecipe recipe : AlkahestryRecipeRegistry.getChargingRecipes()) {
			consumeAndCharge(tome, 0, player, getChargeLimit() - getCharge(tome), recipe.getChargeToAdd(), 16, recipe.getChargingIngredient());
		}
	}

@Override
	public void inventoryTick(ItemStack catalyst, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 10 != 0) {
			return;
		}

		if (isEnabled(catalyst)) {
			int freeCapacity = Math.max(gunpowderLimit() - getTotalCharge(catalyst), 0) / gunpowderWorth();
			consumeAndCharge(catalyst, 0, player, freeCapacity, 1, 16);
		}
	}

private Optional<BlockPos> getNextBlockToBoneMeal(Level level, HarvestRodCache cache, BlockPos pos, int range) {
		if (cache.isQueueEmpty() || !pos.equals(cache.getStartBlockPos())) {
			fillQueue(cache, pos, range, currentPos -> {
				BlockState blockState = level.getBlockState(currentPos);
				return blockState.getBlock() instanceof BonemealableBlock bonemealableBlock
						&& bonemealableBlock.isValidBonemealTarget(level, currentPos, blockState);
			});
		}

		return cache.getNextBlockInQueue();
	}

