private static long getTimeSinceLastCharge(World world, ItemStack stack) {
        NBTTagCompound tagCompound = stack.getTagCompound();
        if(tagCompound != null) {
            long lastTime = tagCompound.getLong(TAG_CHARGE_TIME);
            long currentTime = world.getTotalWorldTime();
            if (lastTime > currentTime)
                return 0;
            else
                return currentTime - lastTime;
        }
        return Long.MAX_VALUE;
    }

protected boolean shouldEmitParticles() {
        if(lastEscaped == null)
            return false;
        if(lastEscapedTickClient < lastEscapedTickServer) {
            lastEscapedTickClient = lastEscapedTickServer;
            return true;
        }
        long dTime = world.getTotalWorldTime() - lastEscapedTickClient;
        if(dTime < lastEscaped.amount+5)
            return true;
        return false;
    }

