private void updateRotations() {
		float secondsDuration = 1;
		long currentTime = System.currentTimeMillis();
		if (currentTime - lastTargetSetTime <= secondsDuration * 1000) {
			float ratio = (currentTime - lastTargetSetTime) / (secondsDuration * 1000);
			ratio = Easing.EASE_IN_OUT_CUBIC.ease(ratio);
			xAxisRotation = fromXAxisRotation + (targetXAxisRotation - fromXAxisRotation) * ratio;
			yAxisRotation = fromYAxisRotation + (targetYAxisRotation - fromYAxisRotation) * ratio;
		} else {
			xAxisRotation = targetXAxisRotation;
			yAxisRotation = targetYAxisRotation;
		}
	}

public static void finalizeTransferredCraftResult(ServerLevel level, ItemStack transferredStack, IItemHandler storageInventory, Inventory playerInventory) {
		EnderLinkPendingCraftData pendingCraft = transferredStack.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null || pendingCraft.claimId() == null) {
			return;
		}
		ItemStack result = findTransferredCraftResult(pendingCraft.claimId(), storageInventory);
		if (result.isEmpty()) {
			result = findTransferredCraftResult(pendingCraft.claimId(), playerInventory);
		}
		if (!result.isEmpty()) {
			finalizePendingCraftResult(level, result);
		}
	}

static LinkedStorageGroupsSavedData load(CompoundTag tag, HolderLookup.Provider registries) {
		Map<UUID, LinkedStorageGroupRecord> groups = new HashMap<>();
		Map<UUID, ActivePendingCraftClaim> activePendingClaims = new HashMap<>();
		for (Tag value : tag.getList(GROUPS_TAG, Tag.TAG_COMPOUND)) {
			LinkedStorageGroupRecord group = loadGroup((CompoundTag) value);
			groups.put(group.id(), group);
		}
		for (Tag value : tag.getList(ACTIVE_PENDING_CLAIMS_TAG, Tag.TAG_COMPOUND)) {
			ActivePendingCraftClaim claim = loadActivePendingClaim((CompoundTag) value);
			activePendingClaims.put(claim.claimId(), claim);
		}
		return new LinkedStorageGroupsSavedData(groups, activePendingClaims);
	}

