public void elapse(Duration duration) {
		elapsed = elapsed.plus(duration);

		Iterator<Pair<Duration, Runnable>> iterator = queue.iterator();
		while (iterator.hasNext()) {
			Pair<Duration, Runnable> item = iterator.next();
			Duration scheduled = item.first();
			if (elapsed.compareTo(scheduled) >= 0) {
				item.second().run();
				iterator.remove();
			}
		}
	}

private <S extends BaseBlock> BlockState getNewState(DeferredHolder<Block, S> block, BlockState state) {
        BlockState newState = block.get().defaultBlockState();

        if (((NetworkNodeBlock) block.get()).hasConnectedState()) {
            newState = newState.setValue(NetworkNodeBlock.CONNECTED, state.getValue(NetworkNodeBlock.CONNECTED));
        }
        if (block.get().getDirection() != BlockDirection.NONE) {
            newState = newState.setValue(block.get().getDirection().getProperty(),
                state.getValue(block.get().getDirection().getProperty()));
        }

        return newState;
    }

public <S extends BaseBlock> void registerItemsFromBlocks(ColorMap<Block, S> blockMap) {
        DeferredHolder<Block, S> originalBlock = blockMap.get(DEFAULT_COLOR);
        map.put(DEFAULT_COLOR, registerBlockItemFor(originalBlock, DEFAULT_COLOR, originalBlock));
        lateRegistration.add(() -> blockMap.forEach((color, block) -> {
            if (color != DEFAULT_COLOR) {
                map.put(color, registerBlockItemFor(block, color, originalBlock));
            }
        }));
        RSItems.COLORED_ITEM_TAGS.put(
            ItemTags.create(new ResourceLocation(RS.ID, blockMap.get(DEFAULT_COLOR).getId().getPath())),
            this
        );
    }

