public static void handle(SubmitTaskMessage message, NetworkManager.PacketContext context) {
		if (context.getPlayer() instanceof ServerPlayer player) {
			context.queue(() -> {
				ServerQuestFile.INSTANCE.getTeamData(player).ifPresent(data -> {
					if (!data.isLocked()) {
						Task task = data.getFile().getTask(message.taskId);
						if (task != null && data.getFile() instanceof ServerQuestFile sqf && data.canStartTasks(task.getQuest())) {
							sqf.withPlayerContext(player, () -> task.submitTask(data, player));
						}
					}
				});
			});
		}
	}

public static void handle(SyncTranslationMessageToClient message, NetworkManager.PacketContext context) {
        context.queue(() -> {
            ClientQuestFile file = ClientQuestFile.INSTANCE;
            if (file.isValid()) {
                QuestObjectBase object = file.getBase(message.id);
                if (object != null) {
                    message.val.ifLeft(str -> file.getTranslationManager().addTranslation(object, message.locale, message.subKey, str))
                            .ifRight(list -> file.getTranslationManager().addTranslation(object, message.locale, message.subKey, list));
                    object.clearCachedData();
                    file.getQuestScreen().ifPresent(QuestScreen::refreshQuestPanel);
                }
            }
        });
    }

public static void handle(SyncTranslationMessageToServer message, NetworkManager.PacketContext context) {
        context.queue(() -> ServerQuestFile.getInstance().ifPresent(sqf -> {
            if (PermissionsHelper.canPlayerEdit(context)) {
                QuestObjectBase object = sqf.getBase(message.id);
                if (object != null) {
                    try {
                        UpdateTranslation.create(sqf, object, message.locale, message.subKey, message.val)
                                .ifPresent(event -> sqf.getHistoryStack().addAndApply(sqf, event));
                    } catch (IllegalArgumentException ignored) {
                    }
                }
            }
        }));
    }

public GTRecipeJS CWUt(int cwu) {
            if (cwu == 0) {
                throw new RecipeExceptionJS(String.format("CWUt can't be explicitly set to 0, id: %s", id));
            }
            var lastPerTick = perTick;
            perTick = true;
