public static void compositePendingLateLayer() {
        var layer = pendingLateLayer;
        if (layer == null) return;
        pendingLateLayer = null;
        // Nothing else will ever see these pixels, so no other bloom can reach them — ours is the
        // only one they can get. It runs here, once, on the layer both queues finished accumulating.
        int colorTexture = bloomedColorOf(layer, pendingLateBloom);
        // bindWrite(true) also restores the full-frame viewport that the bloom chain left mip-sized
        UISurface.currentTarget().bindWrite(true);
        SceneBlit.compositePremultipliedToBound(colorTexture, layer.getColorTextureId(), false);
        // after the composite, so the stacked distortions bend the layer together with the frame
        var frame = UISurface.currentTarget();
        StackedDistortion.bend(frame, frame.getDepthTextureId());
    }

private static void compositeHaze() {
        var haze = pendingHaze;
        pendingHaze = null;
        if (haze == null) return;
        int framebuffer = GlStateManager.getBoundFramebuffer();
        int viewportX = GlStateManager.Viewport.x();
        int viewportY = GlStateManager.Viewport.y();
        int viewportWidth = GlStateManager.Viewport.width();
        int viewportHeight = GlStateManager.Viewport.height();
        LightPassTimer.start();
        drawHaze(haze, 0);
        LightPassTimer.mark(LightPassTimer.Stage.HAZE);
        restore(framebuffer, viewportX, viewportY, viewportWidth, viewportHeight);
    }

@Override
    public void onPlayerTickActive(EntityPlayer player, ItemStack item) {
        double currentHeat = MuseHeatUtils.getPlayerHeat(player);
        double maxHeat = MuseHeatUtils.getMaxHeat(player);
        if (player.worldObj.getTotalWorldTime() % 20 == 0) {
            if (player.isBurning()) {
                ElectricItemUtils.givePlayerEnergy(player, 4 * ModuleManager.computeModularProperty(item, THERMAL_ENERGY_GENERATION));
            } else if (currentHeat >= 200) {
                ElectricItemUtils.givePlayerEnergy(player, 2 * ModuleManager.computeModularProperty(item, THERMAL_ENERGY_GENERATION));
            } else if ((currentHeat / maxHeat) >= 0.5) {
                ElectricItemUtils.givePlayerEnergy(player, ModuleManager.computeModularProperty(item, THERMAL_ENERGY_GENERATION));
            }
        }
    }

public void removeStalePortalLocations(long worldTime) {
        if (worldTime % 100L == 0L) {
            long i = worldTime - 300L; // TODO: Check. This used to be 600L
            ObjectIterator<PortalPosition> objectiterator = this.destinationCoordinateCache.values().iterator();

            while (objectiterator.hasNext()) {
                PortalPosition portalposition = (PortalPosition)objectiterator.next();

                if (portalposition == null || portalposition.lastUpdateTime < i) {
                    objectiterator.remove();
                }
            }
        }
    }

