private void update(Level level, Player player) {
        // if we're just now rendering the HUD after a pause, reset the pitch/yaw trackers
        if (lastTick == -1 || level.getGameTime() - lastTick > 1 || !level.tickRateManager().runsNormally()) {
            prevRotationYaw = player.getYRot();
            prevRotationPitch = player.getXRot();
        }
        //TODO - 26.3: Can we do this via DeltaTracker#getGameTimeDeltaTicks or DeltaTracker#getRealtimeDeltaTicks?
        lastTick = level.getGameTime();
        float yawDiff = player.yHeadRot - prevRotationYaw;
        float pitchDiff = player.getXRot() - prevRotationPitch;
        float jitter = MekanismConfig.client.hudJitter.get();
        prevRotationYaw += yawDiff / jitter;
        prevRotationPitch += pitchDiff / jitter;
    }

public int scroll(double delta) {
        long time = Minecraft.getInstance().gui.hud.getGuiTicks();
        if (time - lastScrollTime > SharedConstants.TICKS_PER_SECOND) {
            scrollDelta = 0;
        }
        lastScrollTime = time;
        scrollDelta += delta;
        int shift = (int) scrollDelta;
        scrollDelta %= 1;
        if (discrete) {
            shift = Math.clamp(shift, -1, 1);
        }
        return shift;
    }

@Override
        protected void onRootCommit(Integer originalState) {
            // actually drop the stacks
            // process elements of the queue one by one to avoid a CME if dropping the entity triggers more additions to the queue
            BlockPos blockPos = getBlockPos();
            Level level = getLevel();
            if (level != null) {
                while (!entries.isEmpty()) {
                    DroppedItems.DropInfo dropInfo = entries.removeFirst();
                    BlockPos adjustedPos = blockPos.offset(dropInfo.xOffset(), dropInfo.yOffset(), dropInfo.zOffset());
                    InventoryUtils.dropStack(level, adjustedPos, null, dropInfo.resource(), dropInfo.amount(), DROPPER);
                }
            }
        }

public final void validateSaveShares(TRANSMITTER triggerTransmitter, @Nullable TransactionContext transaction) {
        if (world == null) {
            //If the world is null, try falling back to the trigger transmitter's world.
            // Note: This also in theory could be null, so we double-check it is not before grabbing the game time
            world = triggerTransmitter.getLevel();
        }
        if (world != null && world.getGameTime() != lastSaveShareWriteTime) {
            lastSaveShareWriteTime = world.getGameTime();
            try (Transaction subTransaction = Transaction.open(transaction)) {
                updateSaveShares(triggerTransmitter, subTransaction);
                subTransaction.commit();
            }
        }
    }

