        if (delay > 0) return;
        updateFrame(pPartialTicks);
        if (buffer instanceof RenderPassPipeline passBuffer) {
            passBuffer.setupRenderingState(pRenderInfo, pPartialTicks);
            prepareRenderPass(passBuffer);
