private void maybeUpdateFromServer(List<IBlockTrackEntry> applicableTrackEntries) {
        if (te == null) return;

        boolean searching = CommonArmorHandler.getHandlerForPlayer().upgradeUsable(CommonUpgradeHandlers.searchHandler, true);
        boolean focused = isPlayerLookingAtTarget();
        int searchInterval = focused ? SERVER_REQUEST_INTERVAL : SERVER_REQUEST_INTERVAL * 2;

        // periodically refresh focused block from the server (or any block on a longer interval if search is active)
        if ((focused || searching) && world.getGameTime() % searchInterval == posHash % searchInterval) {
            Set<BlockPos> posSet = applicableTrackEntries.stream()
                    .flatMap(entry -> entry.getServerUpdatePositions(te).stream())
                    .collect(Collectors.toSet());
            posSet.forEach(pos -> NetworkHandler.sendToServer(new PacketDescriptionPacketRequest(pos)));
        }
    }

void setPrimaryValve(PressureChamberValveBlockEntity newValve) {
        boolean valveChanging = teValve != newValve
                || newValve == null && valvePos != null
                || newValve != null && valvePos == null;

        valvePos = newValve == null ? null : newValve.getBlockPos();
        if (valveChanging && !nonNullLevel().isClientSide) {
            teValve = newValve;
            // defer updating the blockstate since this can get called during placement, and updating the blockstate
            // then can cause the TE to change, losing the reference to the valve TE
            // https://github.com/TeamPneumatic/pnc-repressurized/issues/1049
            PressureWallStateManager.addDeferredUpdate(this, teValve);
            setChanged();
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (rsController.shouldRun() && (nonNullLevel().getGameTime() % Math.max(getTickRate(), cooldown)) == 0) {
            boolean didWork = false;
            for (SideConfigurator.RelativeFace face : SideConfigurator.RelativeFace.values()) {
                switch (getPushPullMode(face)) {
                    case PUSH -> didWork |= tryPush(getAbsoluteFacing(face, getRotation()));
                    case PULL -> didWork |= tryPull(getAbsoluteFacing(face, getRotation()));
                }
            }
            cooldown = didWork ? 0 : Math.min(cooldown + 4, 20);
        }
    }

@Override
    public int getTintColor(ItemStack stack, int tintIndex) {
        if (tintIndex == 1) {
            ISpawnerCoreStats stats = stack.get(ModDataComponents.SPAWNER_CORE_STATS);
            if (stats != null) {
                if (stats.getUnusedPercentage() == 100) {
                    return 0xFFFFFFFF;
                }
                int t = (int) (ClientUtils.getClientLevel().getGameTime() % 40);
                float b = t < 20 ? Mth.sin(3.1415927f * t / 20f) / 6f : 0;
                return TintColor.HSBtoRGB(71/360f, 1f - stats.getUnusedPercentage() / 100f, 0.83333f + b);
            }
        }
        return 0xFFFFFFFF;
    }

public void breakShield(LivingEntity entity, boolean expired) {
		// Temp shields should break first before permanent ones. Reset time each time a temp shield is busted.
		if (this.temporaryShields > 0) {
			this.temporaryShields--;
			this.resetTimer();
		} else if (this.permanentShields > 0) {
			this.permanentShields--;
		}

		if (entity instanceof ServerPlayer player && !expired) {
			player.awardStat(TFStats.TF_SHIELDS_BROKEN.get());
		}
		entity.level().playSound(null, entity.blockPosition(), expired ? TFSounds.SHIELD_EXPIRE.get() : TFSounds.SHIELD_BREAK.get(), SoundSource.PLAYERS, 1.0F, (entity.getRandom().nextFloat() - entity.getRandom().nextFloat()) * 0.3F + 1.0F);
		entity.setData(TFDataAttachments.FORTIFICATION_SHIELDS, this);
	}

