default void tick(Block block, BlockState state, ServerLevel level, BlockPos pos, RandomSource random, IntegerProperty age) {
        if ((random.nextInt(3) == 0 || this.fewerNeigboursThan(block, level, pos, 4)) && this.slightlyMelt(state, level, pos, age)) {
            BlockPos.MutableBlockPos mutablePos = new BlockPos.MutableBlockPos();

            for (Direction direction : Direction.values()) {
                mutablePos.setWithOffset(pos, direction);
                BlockState blockState = level.getBlockState(mutablePos);
                if (blockState.is(block) && !this.slightlyMelt(blockState, level, mutablePos, age)) {
                    level.scheduleTick(mutablePos, block, Mth.nextInt(random, 20, 40));
                }
            }
        } else {
            level.scheduleTick(pos, block, Mth.nextInt(random, 20, 40));
        }
    }

@Override
    public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
        super.tick(state, level, pos, random);
        if (((this.powered && level.hasNeighborSignal(pos)) || (!this.powered && pos.getY() <= level.getMaxBuildHeight())) && isFree(level.getBlockState(pos.above()))) {
            FloatingBlockEntity floatingBlockEntity = new FloatingBlockEntity(level, (double) pos.getX() + 0.5, pos.getY(), (double) pos.getZ() + 0.5, level.getBlockState(pos));
            if (this.powered) {
                floatingBlockEntity.setNatural(false);
            }
            level.addFreshEntity(floatingBlockEntity);
            level.setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());
            this.floating(floatingBlockEntity);
        } else {
            level.scheduleTick(pos, this, this.getDelayAfterPlace());
        }
    }

@Override
	public void neighborChanged(BlockState state, Level world, BlockPos pos, Block blockIn, BlockPos fromPos, boolean isMoving) {
		if (!world.isClientSide() && state.getValue(TOGGLEABLE)) {
			boolean lit = state.getValue(LIT);

			if (lit != world.hasNeighborSignal(pos)) {
				if (lit) {
					world.scheduleTick(pos, this, 4);
				}
				else {
					world.setBlock(pos, state.cycle(LIT), 2);
				}
			}
		}
	}

@Override
	public BlockState updateShape(BlockState state, Direction direction, BlockState neighbour, LevelAccessor level, BlockPos pos, BlockPos neighbourPos) {
		if (state.getValue(WATERLOGGED)) {
			final Fluid fluid = level instanceof WorldGenRegion ? Fluids.WATER : level.getFluidState(pos).getType();

			level.scheduleTick(pos, fluid, fluid.getTickDelay(level));
		}

		final int dist = getLeafDistance(neighbour);

		if (dist > 1 || state.getValue(DISTANCE) != dist)
			level.scheduleTick(pos, this, 1);

		return state;
	}

