public static void move(int start, int end) {
		ChessBoard board = getBoard();
		for (ChessMove move : board.getLegal(board.getMoves(start))) {
			if (move.end() == end) {
				if (move.type() > 2) {
					get().promotionStart = move.start();
					get().pendingPromotion = move.end();
				} else {
					chess.doMove(move);
				}
				get().started = true;
				break;
			}
		}
	}

