private Time nextTime() {
        ClientLevel level = Minecraft.getInstance().level;
        long dayTime = level.getGameTime() % 24000L;
        if (dayTime <= 1000) {
            return Time.MORN;
        } else if (dayTime <= 6000) {
            return Time.NOON;
        } else if (dayTime <= 12000) {
            return Time.EVENING;
        } else if (dayTime <= 18000) {
            return Time.NIGHT;
        } else {
            return Time.MORN;
        }
    }

