@Override
    public T get() {
        if (timeToLiveNanos != -1) {
            long now = System.nanoTime();
            if (lastAccessNanos == 0 || (timeToLiveNanos >= 0 && now - lastAccessNanos >= timeToLiveNanos)) {
                value = delegate.get();
            }
            lastAccessNanos = now;
            return value;
        }
        if (!initialized) {
            value = delegate.get();
            initialized = true;
        }
        return value;
    }

public void prepareRenderPass(RenderPassPipeline buffer) {
        if (isVisible()) {
            // the emitter's OWN (tile) particles draw through its single effective pass — the override
            // pass when overridden, else the shared config singleton (equal effective passes merge).
            // Sub-particles spawned into this emitter with a DIFFERENT render type (the Trails module's
            // trail / aratrail particles) keep their OWN pass: piping them through the tile pass would
            // silently drop them, since the tile renderer only emits TileParticles.
            var effectivePass = effectiveRenderPass();
            for (var entry : this.particles.entrySet()) {
                var queue = entry.getValue();
                if (queue.isEmpty()) continue;
                var pass = entry.getKey() == config.particleRenderType ? effectivePass : entry.getKey();
                buffer.pipeQueue(pass, queue);
            }
        }
    }

private void renderQueuedPasses() {
        for (var entry : activeGroup.entrySet()) {
            var renderPass = entry.getKey();
            var particleQueue = entry.getValue();
            if (!particleQueue.isEmpty()) {
                renderPass.prepareStatus(this);
                var drewSomething = renderPass.drawParticles(this, particleQueue, camera, partialTicks);
                renderPass.releaseStatus(this);
                if (drewSomething) {
                    // only a pass that wrote pixels can change what a later scene-sampling
                    // material sees; skipping the mark avoids a redundant scene re-copy
                    markSceneSamplerDirty();
                }
            }
        }
    }

public int getStartingLevel() {
		int startingLevelMin = Math.max(1, CreatureManager.getInstance().config.startingLevelMin);
		if(CreatureManager.getInstance().config.startingLevelMax > startingLevelMin) {
			return startingLevelMin + this.getRNG().nextInt(CreatureManager.getInstance().config.startingLevelMax - startingLevelMin);
		}
		if(CreatureManager.getInstance().config.levelPerDay > 0 && CreatureManager.getInstance().config.levelPerDayMax > 0) {
			int day = (int)Math.floor(this.getEntityWorld().getTotalWorldTime() / 23999D);
			double levelGain = Math.min(CreatureManager.getInstance().config.levelPerDay * day, CreatureManager.getInstance().config.levelPerDayMax);
			startingLevelMin += (int)Math.floor(levelGain);
		}
		if(CreatureManager.getInstance().config.levelPerLocalDifficulty > 0) {
			double levelGain = this.getEntityWorld().getDifficultyForLocation(this.getPosition()).getAdditionalDifficulty();
			startingLevelMin += Math.max(0, (int)Math.floor(levelGain - 1.5D));
		}
		return startingLevelMin;
	}

