public static boolean hurtNoInvulnerableTime(Entity target, @Nullable LivingEntity living, DamageSource source, float damage) {
    // store last damage before secondary attack
    float oldLastDamage = living == null ? 0 : living.lastHurt;

    // set hurt resistance time to 0 because we always want to deal damage in traits
    int lastInvulnerableTime = target.invulnerableTime;
    target.invulnerableTime = 0;
    boolean hit = target.hurt(source, damage);
    // reset to the old time so bows work right
    target.invulnerableTime = lastInvulnerableTime;
    // set total received damage, important for AI and stuff
    if (living != null) {
      living.lastHurt += oldLastDamage;
    }
    return hit;
  }

private static boolean brushBlock(Player player, BlockHitResult blockHit, BlockState state, HumanoidArm arm) {
    // only play sound and particle if its a brushable block, reduces noice on AOE
    Level level = player.level();
    if (state.getBlock() instanceof BrushableBlock brushable) {
      brushEffects(player, blockHit, state, arm, brushable.getBrushSound());
      if (level.isClientSide) {
        return true;
      }
    }

    // brush the block
    if (!level.isClientSide) {
      return level.getBlockEntity(blockHit.getBlockPos()) instanceof BrushableBlockEntity brushable && brushable.brush(level.getGameTime(), player, blockHit.getDirection());
    }
    return false;
  }

public FluidDeferredHolders register() {
            // Create the holder instance now so that we can reference it in the factories below.
            var fluid = new FluidDeferredHolders();

            // Register everything.
            fluid.type(fluidTypes.register(name, () -> fluidTypeFactory.apply(fluidTypeProperties)));
            fluid.source(fluids.register("fluid_" + name + "_still", () -> sourceFluidFactory.apply(fluid.createProperties())));
            fluid.flowing(fluids.register("fluid_" + name + "_flowing", () -> flowingFluidFactory.apply(fluid.createProperties())));
            fluid.block(blocks.register(name, () -> blockFactory.apply(fluid.flowing().get(), blockProperties)));

            if (bucketFactory != null) {
                fluid.bucket(items.register(name + "_bucket", () -> bucketFactory.apply(fluid.source().get())));
            }

            return fluid;
        }

public final void tick(ServerLevel level, ConduitNetwork network, int tickOffset) {
        // See if we can tick any conduits in this network
        List<Holder<Conduit<?, ?>>> tickableConduits = network.getTickableConduits(level.getGameTime(), tickOffset);

        // Only tick if we're supposed to.
        if (tickableConduits.isEmpty()) {
            return;
        }

        // Preconditions when we actually tick to save doing comparisons each tick.
        Preconditions.checkArgument(network.conduitType() == conduitType(), "Network is not of correct type");
        Preconditions.checkArgument(network.conduitType().ticker() == this, "Incorrect ticker for network's conduit type");

        // Now tick!
        tickNetwork(level, network, tickableConduits);
    }

@Override
    public void tick() {
        super.tick();
        if (isReachedTarget()) {
            if (entity.getHunger() < entity.getMaxHunger()) {
                entity.feed(FoodMappings.getFoodAmount(targetItem.getItem().getItem(), entity.data().diet()));
                targetItem.getItem().shrink(1);
            }
            recentlyAte = true;
            if (entity.level.getGameTime() > animEndTick) {
                AnimationInfo animationInfo = entity.nextEatingAnimation();
                entity.getAnimationLogic().triggerAnimation(AnimationLogic.IDLE_CTRL, animationInfo, AnimationCategory.EAT);
                animEndTick = (long) (entity.level.getGameTime() + animationInfo.animation.animationLength);
            }
        }
