protected void checkAndPerformAttack(ToyBase target) {
        long currentTime = dino.level.getGameTime();
        if (Util.canReachPrey(dino, target)) {
            if (currentTime > attackEndTick + 20) {
                ServerAnimationInfo animation = dino.startAttack();
                attackDamageTick = (long) (currentTime + animation.actionDelay);
                attackEndTick = (long) (currentTime + animation.animation.animationLength);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
                dino.getNavigation().stop();
            }
            if (attackDamageTick > 0 && currentTime == attackDamageTick) {
                target.hurt(DamageSource.mobAttack(dino), 0);
                attackDamageTick = -1;
            }
        }
    }

private Component getTimerComponent() {
        @SuppressWarnings("DataFlowIssue")
        long remainingTime = taskInstance.getTaskTimeStamp() - Minecraft.getInstance().level.getGameTime();
        if (remainingTime >= 0) {
            remainingTime = remainingTime / 20;
            long hours = remainingTime / 3600;
            long minutes = (remainingTime % 3600) / 60;
            long seconds = remainingTime % 60;
            String time = String.format("%d:%02d:%02d", hours, minutes, seconds);
            ChatFormatting color = remainingTime < taskInstance.getTaskDuration() / 20f * 0.1F
                    ? ChatFormatting.YELLOW : ChatFormatting.WHITE;
            return Component.literal(time).withStyle(color);
        } else {
            return Component.translatable("gui.factionapi.taskmaster.task_failed").withStyle(ChatFormatting.BLACK);
        }
    }

