private static <T extends Entity> DeferredHolder<EntityType<?>, EntityType<T>> create(String id,
            String englishName,
            EntityFactory<T> entityFactory,
            MobCategory classification,
            Consumer<Builder<T>> customizer) {
        ENTITY_ENGLISH_NAMES.put(id, englishName);
        return DR.register(id, () -> {
            Builder<T> builder = Builder.of(entityFactory, classification);
            customizer.accept(builder);
            // Temporarily disable the data fixer check to avoid the annoying "no data fixer registered for ae2:xxx".
            boolean prev = SharedConstants.CHECK_DATA_FIXER_SCHEMA;
            SharedConstants.CHECK_DATA_FIXER_SCHEMA = false;
            EntityType<T> result = builder.build(ResourceKey.create(Registries.ENTITY_TYPE, AppEng.makeId(id)));
            SharedConstants.CHECK_DATA_FIXER_SCHEMA = prev;
            return result;
        });
    }

private static void addPossibleItem(Item item, Queue<ItemStack> queue) {
        if (item == null || item == Items.AIR) {
            return;
        }

        ItemStack sampleStack = item.getDefaultInstance();
        if (sampleStack.isDamageableItem()) {
            int maxDamage = sampleStack.getMaxDamage();
            for (int dmg = 0; dmg < maxDamage; dmg++) {
                ItemStack is = sampleStack.copy();
                is.setDamageValue(dmg);
                queue.add(is);
            }
        } else {
            queue.add(item.getDefaultInstance());
        }
    }

private void tickLevelQueue(@Nullable Level level) {
        var queue = this.upcomingTicks.get(level);

        if (queue != null) {
            currentlyTickingQueue = queue;

            try {
                tickQueue(queue);
            } finally {
                currentlyTickingQueue = null;
            }

            if (queue.isEmpty()) {
                this.upcomingTicks.remove(level);
            }
        }
    }

@Override
    public void onRedstoneLevelMayHaveChanged() {
        if (isInPulseMode()) {
            var hostIsPowered = this.getHost().hasRedstone();
            if (this.lastRedstone != hostIsPowered) {
                this.lastRedstone = hostIsPowered;
                if (this.lastRedstone && !this.pendingPulse) {
                    // Perform the action based on the pulse on the next tick
                    this.pendingPulse = true;
                    getMainNode().ifPresent((grid, node) -> grid.getTickManager().alertDevice(node));
                }
            }
        } else {
            // This handles waking up the bus if the adjacent redstone has changed
            updateRedstoneState();
        }
    }

public static void registerConnectorTEs(DeferredRegister<BlockEntityType<?>> event)
	{
