@Override
        public boolean canUse() {
            if (this.servant.getTarget() != null){
                return false;
            } else if (!(this.servant.getMainHandItem().isEmpty() || this.servant.getMainHandItem().is(Items.BONE_MEAL) || this.servant.getOffhandItem().isEmpty() || this.servant.getOffhandItem().is(Items.BONE_MEAL))){
                return false;
            } else if ((this.lastBonemealingSession == 0L || this.lastBonemealingSession + 160L <= this.servant.level.getGameTime())) {
                if (this.servant.getInventory().countItem(Items.BONE_MEAL) <= 0) {
                    return false;
                } else {
                    this.cropPos = this.pickNextTarget(this.servant.level, this.servant);
                    return this.cropPos.isPresent();
                }
            } else {
                return false;
            }
        }

public void tick() {
            if (this.partner == null){
                this.stop();
            }
            this.illager.getLookControl().setLookAt(this.partner, 10.0F, (float)this.illager.getMaxHeadXRot());
            this.illager.getNavigation().moveTo(this.partner, 0.5F);
            if (this.illager.level.getGameTime() >= this.loveTime && this.illager.distanceToSqr(this.partner) <= 5.0D) {
                if (!this.hasBred) {
                    this.partner.eatAndDigestFood();
                    this.illager.eatAndDigestFood();
                }
                this.breed();
            } else if (this.illager.level.getRandom().nextInt(35) == 0) {
                this.illager.level.broadcastEntityEvent(this.illager, (byte)12);
                this.illager.level.broadcastEntityEvent(this.partner, (byte)12);
            }
        }

@Override
    public InteractionResult useOn(UseOnContext context) {
        Player player = context.getPlayer();
        InteractionHand hand = context.getHand();
        BlockPos blockpos = context.getClickedPos();
        if (player != null && player.isShiftKeyDown()) {
            ItemStack held = player.getItemInHand(hand);
            if (!held.isEmpty() && held.getItem() instanceof IPosHolder) {
                player.swing(hand);
                this.addBlockEntityTags(held, player, player.level().dimension(), blockpos, null);
                player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                player.level.playLocalSound(blockpos.getX(), blockpos.getY(), blockpos.getZ(), SoundEvents.ARROW_HIT_PLAYER, SoundSource.PLAYERS, 1.0F, 0.45F, false);
                return InteractionResult.sidedSuccess(player.level.isClientSide);
            }
        }
        return super.useOn(context);
    }

public static void consume(SSetPlayerOwnerPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            if (ctx.get().getDirection() == NetworkDirection.PLAY_TO_CLIENT) {
                Level level = Goety.PROXY.getLevel();
                if (level instanceof ClientLevel clientWorld) {
                    Entity entity = EntityFinder.getEntityByUuiDGlobal(packet.summoned).isPresent() ? EntityFinder.getEntityByUuiDGlobal(packet.summoned).get() : null;
                    Player playerEntity = Goety.PROXY.getPlayer();
                    if (entity != null && playerEntity != null) {
                        if (entity instanceof IOwned owned) {
                            owned.setTrueOwner(playerEntity);
                        }
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

@Override
    public StructureTemplate.StructureBlockInfo processBlock(LevelReader levelReader, BlockPos pos, BlockPos pos2, StructureTemplate.StructureBlockInfo infoIn1, StructureTemplate.StructureBlockInfo infoIn2, StructurePlaceSettings settings) {
        if(!infoIn2.state().getFluidState().isEmpty()) {
            if(levelReader instanceof WorldGenRegion worldGenRegion && !worldGenRegion.getCenter().equals(new ChunkPos(infoIn2.pos()))) {
                return infoIn2;
            }

            ChunkAccess chunk = levelReader.getChunk(infoIn2.pos());
            int minY = chunk.getMinBuildHeight();
            int maxY = chunk.getMaxBuildHeight();
            int currentY = infoIn2.pos().getY();
            if(currentY >= minY && currentY <= maxY) {
                ((LevelAccessor) levelReader).scheduleTick(infoIn2.pos(), infoIn2.state().getBlock(), 0);
            }
        }
        return infoIn2;
    }

