private void handlePlayerTick(final PlayerTickEvent.Pre ev) {
		if (!active)
			return;

		AoAResource.Instance energy = skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get());
		Player player = getPlayer();

		if (!player.getAbilities().instabuild && !player.isSpectator() && energy.consume(energy.getPerTickRegen() + energyDrainPerTick - costReductionPerLevel * skill.getLevel(true), true)) {
			if (player.level().getGameTime() % 10 == 0)
				activatedActionKey((ServerPlayer)player);
		}
		else {
			active = false;

			markForClientSync();
		}
	}

public void render(float partialTicks, PoseStack matrixStack, MultiBufferSource buffers) {
		VertexConsumer buffer = buffers.getBuffer(RenderHelper.LIGHTNING);
		Matrix4f matrix = matrixStack.last().pose();
		Timestamp timestamp = new Timestamp(Minecraft.getInstance().level.getGameTime(), partialTicks);
		boolean refresh = timestamp.isPassed(refreshTimestamp, (1 / REFRESH_TIME));
		if (refresh) {
			refreshTimestamp = timestamp;
		}

		for (Iterator<BoltEmitter> iter = boltEmitters.iterator(); iter.hasNext();) {
			BoltEmitter emitter = iter.next();
			emitter.renderTick(timestamp, refresh, matrix, buffer);
			if (emitter.shouldRemove(timestamp)) {
				iter.remove();
			}
		}
	}

@Override
	public int getLensColor(ItemStack stack, Level level) {
		int storedColor = getStoredColor(stack);

		if (storedColor == -1) {
			return 0xFFFFFF;
		}

		if (storedColor == 16) {
			if (level == null) {
				return 0xFFFFFF;
			}
			return Mth.hsvToRgb(level.getGameTime() * 2 % 360 / 360F, 1F, 1F);
		}

		return ColorHelper.getColorValue(DyeColor.byId(storedColor));
	}

