@Override
    public boolean placeLiquid(LevelAccessor pLevel, BlockPos pPos, BlockState pState, FluidState pFluidState) {
        if (!pState.getValue(BlockStateProperties.WATERLOGGED) && pFluidState.getType() == Fluids.WATER) {
            boolean flag = pState.getValue(LIT);
            if (flag) {
                if (!pLevel.isClientSide()) {
                    pLevel.playSound(null, pPos, SoundEvents.GENERIC_EXTINGUISH_FIRE, SoundSource.BLOCKS, 1.0F, 1.0F);
                }
            }

            pLevel.setBlock(pPos, pState.setValue(WATERLOGGED, true).setValue(LIT, false), 3);
            pLevel.scheduleTick(pPos, pFluidState.getType(), pFluidState.getType().getTickDelay(pLevel));
            return true;
        } else {
            return false;
        }
    }

@Override
    public void load(CompoundTag pCompound) {
        if (pCompound.contains("unloadedGametime", 99)) {
            var unloadTimestamp = pCompound.getLong("unloadedGametime");
            var delta = level.getGameTime() - unloadTimestamp;
            if (delta > UNLOADED_DESPAWN_LIMIT_SECONDS * 20) {
                this.setRemoved(RemovalReason.DISCARDED);
                IronsSpellbooks.LOGGER.info("Refusing to load {}, elapsed time {} greater than limit {}", this, delta, UNLOADED_DESPAWN_LIMIT_SECONDS * 20);
                return;
            }
        }
        super.load(pCompound);
        if (!level.isClientSide) {
            // re-sync uuid if we are loading from file rather than creating new entity (uuid is loaded in super.load)
            createBossEvent();
        }
    }

@Override
    public void aiStep() {
        if (this.level().getGameTime() % 1024 == 0)
            this.heal(1F);

        // Every 10 ticks, attempt to refresh the owner buff
        if (!this.level().isClientSide() && this.level().getGameTime() % 10 == 0 && this.isTame()) {
            LivingEntity owner = this.getOwner();
            if (owner != null && this.distanceTo(owner) < MAX_BOOST_DISTANCE) {
                // close enough to boost
                for (MobEffectInstance effect : this.getFamiliarEffects())
                    owner.addEffect(effect);
            }
        }

        super.aiStep();
    }

