        if (isWaterLoggable() && state.getValue(BlockStateProperties.WATERLOGGED)) {
            tickAccess.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }

        return super.updateShape(state, level, tickAccess, pos, side, adjPos, adjState, random);
    }

private static float calculateAngle(Level level, ChestState chestState, Direction dir, long lastChange, float partialTicks) {
        float diff = (float) (level.getGameTime() - lastChange) + partialTicks;

        float factor = Mth.lerp(diff / 10F, 0, 1);
        if (chestState == ChestState.CLOSING) {
            factor = 1F - factor;
        }

        factor = 1.0F - factor;
        factor = 1.0F - factor * factor * factor;

        float angle = Mth.clamp(factor * 90F, 0F, 90F);
        if (!DirUtils.isPositive(dir)) {
            angle *= -1F;
        }

        return angle;
    }

private <D> DeferredDataComponentType<D> registerComponentType(
            String name,
            Codec<D> codec,
            StreamCodec<? super RegistryFriendlyByteBuf, D> streamCodec,
            boolean cacheEncoding,
            boolean ignoreSwapAnimation
    ) {
        return registerComponentType(name, builder -> {
            builder.persistent(codec).networkSynchronized(streamCodec);
            if (cacheEncoding) {
                builder.cacheEncoding();
            }
            if (ignoreSwapAnimation) {
                builder.ignoreSwapAnimation();
            }
            return builder;
        });
    }

