public static @Nullable SpellContext tryPropagateBlockSpell(BlockHitResult blockHitResult, Level level, Entity shooter, SpellContext spellContext, SpellResolver resolver) {
        if (!resolver.hasFocus(ItemsRegistry.SHAPERS_FOCUS.get()))
            return null;
        SpellContext context = spellContext.makeChildContext();
        spellContext.setCanceled(true);
        SpellResolver newResolver = resolver.getNewResolver(context);
        if (spellContext.isDelayed()) {
            var currenDelay = spellContext.getDelayedSpellEvent();
            newResolver.hitResult = blockHitResult;
            DelayedSpellEvent delayedSpellEvent = new DelayedSpellEvent(currenDelay.duration, blockHitResult, level, newResolver);
            EventQueue.getServerInstance().addEvent(delayedSpellEvent);
            context.delay(delayedSpellEvent);
        } else {
            newResolver.onResolveEffect(level, blockHitResult);
        }

        return context;
    }

public static void attemptRepair(ItemStack stack, LivingEntity entity) {
        if (entity.level.getGameTime() % 200 != 0 || stack.getDamageValue() <= 0) {
            return;
        }

        double repairLevel = PerkUtil.countForPerk(RepairingPerk.INSTANCE, entity);
        int damage = stack.getDamageValue();
        int repairAmount = Math.min(damage, (int) repairLevel + Config.BASE_ARMOR_REPAIR_RATE.get());
        if (repairAmount <= 0) {
            return;
        }

        var cap = CapabilityRegistry.getMana(entity);
        if (cap != null && cap.getCurrentMana() >= 20) {
            cap.removeMana(20);
            stack.setDamageValue(damage - repairAmount);
        }
    }

public void sendPacket(Level world, HitResult rayTraceResult, @Nullable LivingEntity shooter, SpellContext spellContext, SpellStats spellStats, BlockHitResult blockResult, Entity hitEntity, SpellResolver spellResolver) {
        if (spellContext.getCurrentIndex() >= spellContext.getSpell().size())
            return;
        int duration = GENERIC_INT.get(); // base duration
        int increasedTime = EXTEND_TIME.get() * 20 * spellStats.getBuffCount(AugmentExtendTime.INSTANCE);
        int decreasedTime = DURATION_DOWN_TIME.get() * spellStats.getBuffCount(AugmentDurationDown.INSTANCE);
        duration = duration + increasedTime - decreasedTime;
        if (spellStats.isRandomized()) {
            double randomize = spellStats.getBuffCount(AugmentRandomize.INSTANCE) * RANDOMIZE_CHANCE.get();
            duration = world.random.nextIntBetweenInclusive((int) (duration * (1 - randomize)), (int) (duration * (1 + randomize)));
        }
        var delayEvent = new DelayedSpellEvent(duration, rayTraceResult, world, spellResolver);
        spellContext.delay(delayEvent);

        EventQueue.getServerInstance().addEvent(delayEvent);
        Networking.sendToNearbyClient(world, BlockPos.containing(safelyGetHitPos(rayTraceResult)),
                new PacketClientDelayEffect(duration, shooter, spellContext.getSpell(), spellContext, blockResult, hitEntity));
    }

public BlockState updateShape(BlockState myState, Direction pFacing, BlockState pFacingState, LevelAccessor pLevel, BlockPos myPos, BlockPos pFacingPos) {
        ChestType half = myState.getValue(PART);
        BlockPos requiredNeighborPos = myPos.relative(getNeighbourDirection(half, myState.getValue(FACING)));
        boolean waterlogged = myState.getValue(WATERLOGGED);
        if (waterlogged) {
            pLevel.scheduleTick(myPos, Fluids.WATER, Fluids.WATER.getTickDelay(pLevel));
            pLevel.scheduleTick(requiredNeighborPos, Fluids.WATER, Fluids.WATER.getTickDelay(pLevel));
        }
        BlockState neighborState = pLevel.getBlockState(requiredNeighborPos);
        if (!neighborState.is(this)) {
            var air = (waterlogged ? Blocks.WATER : Blocks.AIR).defaultBlockState();
            //manually set to prevent block from dropping
            pLevel.setBlock(myPos, air, 35);
            pLevel.levelEvent(null, 2001, myPos, Block.getId(air));
            return air;
        }
        return super.updateShape(myState, pFacing, pFacingState, pLevel, myPos, pFacingPos);
    }

@Override
    public void render(PortalFrameBlockEntity pBlockEntity, float pPartialTick, PoseStack poseStack, MultiBufferSource pBufferSource, int pPackedLight, int pPackedOverlay) {
        if (!pBlockEntity.clientIsConnected || pBlockEntity.getBlockState().getValue(PortalFrameBlock.HALF).equals(DoubleBlockHalf.UPPER)) {
            return;
        }
        poseStack.pushPose();
        poseStack.translate(0.5, 0, 0.5);
        var direction = pBlockEntity.getBlockState().getValue(PortalFrameBlock.FACING);
        var n = direction.getNormal();
        Vec3 dir = new Vec3(n.getX(), 0, n.getZ()).scale(-(6.5 / 16f));
        poseStack.translate(dir.x, 0, dir.z);
        if (direction == Direction.EAST || direction == Direction.WEST) {
            poseStack.mulPose(Axis.YP.rotation(Mth.HALF_PI));
        }
        PortalRenderer.PortalType type = pBlockEntity.getBlockState().is(BlockRegistry.POCKET_PORTAL_FRAME) ? PortalRenderer.POCKET_DIMENSION : PortalRenderer.NORMAL;
        PortalRenderer.renderPortal(type, poseStack, pBufferSource, pBlockEntity.getLevel() == null ? 0 : (int) pBlockEntity.getLevel().getGameTime(), pPartialTick, false, pBlockEntity.getColor());
        poseStack.popPose();
    }

@Override
    public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        if (this.getOwner() == pPlayer && itemstack.is(Tags.Items.GEMS_LAPIS)) {
            if (this.level().getGameTime() > this.lastPrismarineTime + PRISMARINE_INTERVAL) {
                int quant = this.hasIesniumUpgrade() ? RandomSource.create().nextInt(4, 12) :
                        this.hasBlacksmithUpgrade() ? RandomSource.create().nextInt(1, 5) : 1;
                this.lastPrismarineTime = this.level().getGameTime();
                itemstack.shrink(1);
                ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.PRISMARINE_SHARD, quant));
            } else if (pPlayer.level().isClientSide()) {
                pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.cthulhu.prismarine_on_cooldown"));
            }
            //even if we don't give a prismarine we return success, otherwise we make the familiar change sitting position
            return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
        }
        return super.mobInteract(pPlayer, pHand);
    }

