@Override
    public CompoundTag writeJobToNBT(CompoundTag compound, Provider provider) {
        if (this.storageControllerPosition != null)
            compound.put("storageControllerPosition", GlobalBlockPos.CODEC.encodeStart(provider.createSerializationContext(NbtOps.INSTANCE), this.storageControllerPosition).getOrThrow());

        if (this.managedMachine != null)
            compound.put("managedMachine", this.managedMachine.serializeNBT(provider));

        if (this.getCurrentDepositOrder() != null)
            compound.put("currentDepositOrder", this.getCurrentDepositOrder().writeToNBT(new CompoundTag(), provider));

        ListTag nbtOrderList = new ListTag();
        for (DepositOrder depositOrder : this.depositOrderQueue) {
            nbtOrderList.add(depositOrder.writeToNBT(new CompoundTag(), provider));
        }
        compound.put("depositOrders", nbtOrderList);
        return super.writeJobToNBT(compound, provider);
    }

private static void addToExistingTabs(BuildCreativeModeTabContentsEvent event) {
        ResourceKey<CreativeModeTab> tabKey = event.getTabKey();
        if (tabKey == CreativeModeTabs.FUNCTIONAL_BLOCKS) {
            CreativeTabDeferredRegister.addToDisplay(event, GeneratorsBlocks.HEAT_GENERATOR, GeneratorsBlocks.SOLAR_GENERATOR,
                  GeneratorsBlocks.ADVANCED_SOLAR_GENERATOR, GeneratorsBlocks.WIND_GENERATOR, GeneratorsBlocks.BIO_GENERATOR, GeneratorsBlocks.GAS_BURNING_GENERATOR);
        } else if (tabKey == CreativeModeTabs.REDSTONE_BLOCKS) {
            for (Holder<Item> item : GeneratorsBlocks.BLOCKS.getSecondaryEntries()) {
                //Note: This should always be a block item
                if (item.value() instanceof BlockItem blockItem && Attribute.has(blockItem.getBlock(), AttributeComparator.class)) {
                    CreativeTabDeferredRegister.addToDisplay(event, item);
                }
            }
        } else if (tabKey == CreativeModeTabs.TOOLS_AND_UTILITIES) {
            CreativeTabDeferredRegister.addToDisplay(GeneratorsFluids.FLUIDS, event);
        } else if (tabKey == CreativeModeTabs.INGREDIENTS) {
            CreativeTabDeferredRegister.addToDisplay(event, GeneratorsItems.HOHLRAUM, GeneratorsItems.SOLAR_PANEL);
        }
    }

@Override
    protected boolean onUpdateServer(ServerLevel level) {
        boolean sendUpdatePacket = super.onUpdateServer(level);
        InventoryFrequency freq = getFreq();
        if (freq != null && freq.isValid() && !freq.isRemoved()) {
            try (Transaction transaction = Transaction.openRoot()) {
                freq.handleEject(level.getGameTime(), transaction);
                HeatTransfer loss = simulate(transaction);
                lastTransferLoss = loss.adjacentTransfer();
                lastEnvironmentLoss = loss.environmentTransfer();
                transaction.commit();
            }
        } else {
            lastTransferLoss = 0;
            lastEnvironmentLoss = 0;
        }
        return sendUpdatePacket;
    }

@Nullable
	private static Connection getCurrentConnection() {
		Minecraft minecraft = Minecraft.getInstance();
		ClientPacketListener packetListener = minecraft.getConnection();
		if (packetListener != null) {
			return packetListener.getConnection();
		} else if (minecraft.pendingConnection != null) {
			// Some events are fired very early in the connection process,
			// so packetListener may not be initialized.
			// Instead, we grab it from pendingConnection (singleplayer) or...
			return minecraft.pendingConnection;
		} else if (minecraft.gui.screen() instanceof ConnectScreen connectScreen) {
			//...the connect screen (multiplayer)
			return connectScreen.connection;
		} else {
			return null;
		}
	}

