		EnergyTransferHandler handler = globalNet.getLocalNet(worldPosition)
				.getHandler(EnergyTransferHandler.ID, EnergyTransferHandler.class);
		double transferred = 0;
		if(handler!=null)
		{
			Object2DoubleMap<Connection> map = handler.getTransferredLastTick();
			transferred = map.getDouble(shuntConnection);
		}
		if(nextPacketIndex >= lastPackets.size())
			lastPackets.add(transferred);
		else
			lastPackets.set(nextPacketIndex, transferred);
		nextPacketIndex = (nextPacketIndex+1)%20;
	}

@Override
	public void tickClient(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		if(!state.active)
			return;
		final IMultiblockLevel level = context.getLevel();
		final Level rawLevel = level.getRawLevel();
		for(final MultiblockProcess<BottlingMachineRecipe, ProcessContextInWorld<BottlingMachineRecipe>> process : state.processor.getQueue())
		{
			Player localPlayer = ImmersiveEngineering.proxy.getClientPlayer();
			if(process.processTick==STANDARD_TRANSPORT_TIME-12)
			{
				final BlockPos soundPos = level.toAbsolute(new BlockPos(1, 1, 1));
				rawLevel.playSound(localPlayer, soundPos, IESounds.bottling.value(), SoundSource.BLOCKS, .125F, 0.8F);
				break;
			}
		}
	}

private boolean updateHarvestState(@Nullable BlockPos newTargetPos, boolean propagate)
	{
		groupLastTickHelper = noisyToolHolder.level().getGameTime();
		if(currentMotorState!=BUSY)
			groupLastTickHelper += harvestTimeoutGrace; //initial start needs grace period before stopping for remote AND local players

		if(Objects.equals(currentTargetPos, newTargetPos))
			return false;

		currentTargetPos = newTargetPos;

		if(newTargetPos!=null)
		{
			if(propagate)
				switchMotorState(true, false, false);
			play(new NoisyToolHarvestSound(newTargetPos));
		}
		return true;
	}

public List<ChassisBlockEntity> collectChassisGroup() {
		Queue<BlockPos> frontier = new LinkedList<>();
		List<ChassisBlockEntity> collected = new ArrayList<>();
		Set<BlockPos> visited = new HashSet<>();
		frontier.add(worldPosition);
		while (!frontier.isEmpty()) {
			BlockPos current = frontier.poll();
			if (visited.contains(current))
				continue;
			visited.add(current);
			BlockEntity blockEntity = level.getBlockEntity(current);
			if (blockEntity instanceof ChassisBlockEntity chassis) {
				collected.add(chassis);
				visited.add(current);
				chassis.addAttachedChasses(frontier, visited);
			}
		}
		return collected;
	}

@Override
	protected void checkTickOnNeighbor(Level worldIn, BlockPos pos, BlockState state) {
		boolean back = state.getValue(POWERED);
		boolean shouldBack = shouldTurnOn(worldIn, pos, state);
		boolean side = state.getValue(POWERED_SIDE);
		boolean shouldSide = isPoweredOnSides(worldIn, pos, state);

		TickPriority tickpriority = TickPriority.HIGH;
		if (this.shouldPrioritize(worldIn, pos, state))
			tickpriority = TickPriority.EXTREMELY_HIGH;
		else if (side || back)
			tickpriority = TickPriority.VERY_HIGH;

		if (worldIn.getBlockTicks()
			.willTickThisTick(pos, this))
			return;
		if (back != shouldBack || side != shouldSide)
			worldIn.scheduleTick(pos, this, this.getDelay(state), tickpriority);
	}

@Override
	public void neighborChanged(BlockState pState, Level pLevel, BlockPos pPos, Block pBlock, BlockPos pFromPos,
		boolean pIsMoving) {
		if (pLevel.isClientSide)
			return;
		boolean powered = pState.getValue(POWERED);
		Optional<SignalBlockEntity> ste = getBlockEntityOptional(pLevel, pPos);
		boolean neighborPowered = false;
		if (ste.isEmpty() || !ste.get().computerBehaviour.hasAttachedComputer()) {
			neighborPowered = pLevel.hasNeighborSignal(pPos);
		}
		if (powered == neighborPowered)
			return;
		if (powered) {
			pLevel.scheduleTick(pPos, this, 4);
		} else {
			pLevel.setBlock(pPos, pState.cycle(POWERED), Block.UPDATE_CLIENTS);
		}
	}

