@Override
		public Optional<JukeboxPlaybackLocation> resolve(MinecraftServer server, UUID groupId) {
			if (lastSeenTick < server.getTickCount() - ENTITY_ANCHOR_GRACE_TICKS) {
				return Optional.empty();
			}
			ServerLevel level = server.getLevel(dimension);
			Entity source = entity.get();
			ILinkedStorageBlockEndpoint endpointHolder = holder.get();
			if (level == null || source == null || !source.isAlive() || source.level() != level || endpointHolder == null
					|| !endpointHolder.isLinkedStorageLinkCandidate()) {
				return Optional.empty();
			}

			LinkedStorageEndpointData endpoint = endpointHolder.getLinkedStorageEndpointData();
			return endpoint != null && endpoint.groupId().equals(groupId) && endpoint.endpointId().equals(endpointId)
					&& LinkedStorageGroupsSavedData.get(level).manager().isPrimaryEndpoint(groupId, endpointId)
							? Optional.of(JukeboxPlaybackLocation.forEntity(source))
							: Optional.empty();
		}

public void render(float partialTicks, PoseStack matrixStack, MultiBufferSource buffers) {
        if (Minecraft.getInstance().level != null) {
            VertexConsumer buffer = buffers.getBuffer(ModRenderType.LIGHTNING);
            Matrix4f matrix = matrixStack.last().pose();
            Timestamp timestamp = new Timestamp(Minecraft.getInstance().level.getGameTime(), partialTicks);
            boolean refresh = timestamp.isPassed(this.refreshTimestamp, (1 / REFRESH_TIME));
            if (refresh) {
                this.refreshTimestamp = timestamp;
            }

            for (Iterator<BoltEmitter> iter = this.boltEmitters.iterator(); iter.hasNext(); ) {
                BoltEmitter emitter = iter.next();
                emitter.renderTick(timestamp, refresh, matrix, buffer);
                if (emitter.shouldRemove(timestamp)) {
                    iter.remove();
                }
            }
        }
    }

private void updateEntities() {
        if (this.level != null) {
            BlockPos blockpos = this.getBlockPos();
            if (this.level.getGameTime() > this.lastRingTimestamp + 60L || this.nearbyEntities == null) {
                this.lastRingTimestamp = this.level.getGameTime();
                AABB aabb = (new AABB(blockpos)).inflate(maxRange);
                this.nearbyEntities = this.level.getEntitiesOfClass(LivingEntity.class, aabb);
            }

            if (!this.level.isClientSide) {
                for (LivingEntity livingentity : this.nearbyEntities) {
                    if (livingentity.isAlive() && !livingentity.isRemoved() && blockpos.closerToCenterThan(livingentity.position(), maxRange)) {
                        livingentity.getBrain().setMemory(MemoryModuleType.HEARD_BELL_TIME, this.level.getGameTime());
                    }
                }
            }
        }

    }

@Override
    public boolean canUse() {
        if (this.servant.getTarget() != null){
            return false;
        } else if (!(this.servant.getMainHandItem().isEmpty() || this.servant.getMainHandItem().is(Items.BONE_MEAL) || this.servant.getOffhandItem().isEmpty() || this.servant.getOffhandItem().is(Items.BONE_MEAL))){
            return false;
        } else if (this.servant.getVillagerData().getProfession() != VillagerProfession.FARMER) {
            return false;
        } else if ((this.lastBonemealingSession == 0L || this.lastBonemealingSession + 160L <= this.servant.level.getGameTime())) {
            if (this.servant.getInventory().countItem(Items.BONE_MEAL) <= 0) {
                return false;
            } else {
                this.cropPos = this.pickNextTarget(this.servant.level, this.servant);
                return this.cropPos.isPresent();
            }
        } else {
            return false;
        }
    }

public static void consume(CDismissServantsPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            ServerPlayer playerEntity = ctx.get().getSender();

            if (playerEntity != null) {
                if (playerEntity.level instanceof ServerLevel serverLevel){
                    for (Entity entity : serverLevel.getAllEntities()){
                        if (entity instanceof IOwned owned && owned instanceof LivingEntity livingEntity && owned.getTrueOwner() == playerEntity){
                            if (owned.isLimitedLife() && !SEHelper.getGroundedEntities(playerEntity).contains(livingEntity) && !SEHelper.getGroundedEntityTypes(playerEntity).contains(entity.getType())) {
                                owned.dismiss();
                                entity.playSound(ModSounds.ROAR_SPELL.get(), 0.5F, 2.0F);
                            }
                        }
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

public static void consume(CTramplerPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            ServerPlayer playerEntity = ctx.get().getSender();

            if (playerEntity != null) {
                Entity entity = playerEntity.level.getEntity(packet.mob);
                if (entity instanceof AllyTrampler trampler) {
                    if (packet.mode == 0) {
                        ++trampler.running;
                    } else if (packet.mode == 1){
                        trampler.setDashing(true);
                    } else if (packet.mode == 2){
                        trampler.setDashing(false);
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

public static void consume(SUpdateBossBar packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Player player = ctx.get().getSender();
            if (ctx.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                player = Goety.PROXY.getPlayer();
            }
            if (player != null) {
                Entity entity = player.level.getEntity(packet.boss);
                if (entity instanceof Mob mob) {
                    if (packet.remove) {
                        Goety.PROXY.removeBossBar(packet.bar, mob);
                    } else {
                        Goety.PROXY.addBossBar(packet.bar, mob);
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

