        }
        else {
            if ((!this.isInWater() || this.hasExtendedNeck) && this.extendNeckProgress < 100) {
                this.extendNeckProgress++;
            } else if ((this.isInWater() || !this.hasExtendedNeck) && this.extendNeckProgress > 0) {
                this.extendNeckProgress--;
            }
        }
    }

private void renderBlockHighlight(PoseStack matrixStack, MultiBufferSource buffer, Level world, BlockPos pos, float partialTicks) {
        BlockState state = world.getBlockState(pos);
        VoxelShape shape = state.getShape(world, pos);
        if (shape.isEmpty()) return;

        float progress = ((world.getGameTime() & 0x1f) + partialTicks) / 32f;
        float cycle = Mth.sin((float) (progress * Math.PI));

        float shrink = (shape == Shapes.block() ? 0.05f : 0f) + cycle / 60f;
        AABB aabb = shape.bounds().deflate(shrink);

        float alpha = blockTracker.getFocusedPos() != null ? (blockTracker.getFocusedPos().equals(pos) ? 0.75f : 0.15f) : 0.5f;

        matrixStack.pushPose();
        matrixStack.translate(-0.5, -0.5, -0.5);
        RenderType type = RenderUtils.renderFrame(matrixStack, buffer, aabb, 1/64f, 0.25f, 0.75f, 0.75f, alpha, FULL_BRIGHT);
        RenderUtils.finishBuffer(buffer, type);
        matrixStack.popPose();
    }

@Override
    public BlockState updateShape(BlockState stateIn, Direction facing, BlockState facingState, LevelAccessor worldIn, BlockPos currentPos, BlockPos facingPos) {
        if (stateIn.hasProperty(WATERLOGGED) && stateIn.getValue(WATERLOGGED)) {
            worldIn.scheduleTick(currentPos, Fluids.WATER, Fluids.WATER.getTickDelay(worldIn));
        }
        if (stateIn.hasProperty(connectionProperty(facing))) {
            BlockEntity ourTE = worldIn.getBlockEntity(currentPos);
            if (ourTE != null && PNCCapabilities.getAirHandler(ourTE, facing).isPresent()) {
                // handle pneumatic connections to neighbouring air handlers
                BlockEntity te = worldIn.getBlockEntity(currentPos.relative(facing));
                boolean b = te != null && PNCCapabilities.getAirHandler(te, facing.getOpposite()).isPresent();
                stateIn = stateIn.setValue(connectionProperty(facing), b);
            } else {
                stateIn = stateIn.setValue(connectionProperty(facing), false);
            }
            return stateIn;
        }
        return super.updateShape(stateIn, facing, facingState, worldIn, currentPos, facingPos);
    }

public void tick() {
        int currentTemp = logic.getTemperatureAsInt();

        if (shouldSyncNow()) {
            // large temperature delta: sync immediately
            this.syncedTemp = currentTemp;
            syncTimer = -1;
        } else if (currentTemp != syncedTemp) {
            // small temperature delta: schedule a sync to happen in 60 ticks, unless one is already scheduled
            if (syncTimer == -1) syncTimer = SYNC_RATE;
            pendingTemp = currentTemp;
        }

        if (syncTimer >= 0) {
            if (--syncTimer == -1) {
                this.syncedTemp = pendingTemp;
            }
        }
    }

@Override
	protected InteractionResult useWithoutItem(BlockState state, Level level, BlockPos pos, Player player, BlockHitResult result) {
		if (!this.doesCoreFunction()) {
			level.setBlockAndUpdate(pos, state.setValue(ACTIVE, false));
			player.sendOverlayMessage(Component.translatable("misc.twilightforest.core_disabled", this.getName()).withStyle(ChatFormatting.RED));
			return InteractionResult.SUCCESS;
		}

		if (!state.getValue(ACTIVE)) {
			level.setBlockAndUpdate(pos, state.setValue(ACTIVE, true));
			level.scheduleTick(pos, this, this.tickRate());
			return InteractionResult.SUCCESS;
		} else if (state.getValue(ACTIVE)) {
			level.setBlockAndUpdate(pos, state.setValue(ACTIVE, false));
			return InteractionResult.SUCCESS;
		}

		return InteractionResult.PASS;
	}

public static void travellersGearAutoRepair(LivingEntity livingEntity) {
		long lastHitTime = livingEntity.getData(TFDataAttachments.LAST_DAMAGE_ARMOR_TIME);
		if (livingEntity.level().getGameTime() - lastHitTime <= 10 * 20)  // 10 seconds
			return;

		for (EquipmentSlot slot : EquipmentSlotGroup.ARMOR.slots()) {
			ItemStack stack = livingEntity.getItemBySlot(slot);

			Float probability = stack.get(TFDataComponents.AUTO_REPAIR_PROBABILITY);
			if (probability == null || !TravellersModifiersManager.isModifierActive(livingEntity, stack, TravellersModifiersManager.AUTO_REPAIR_MODIFIER))
				continue;
			Level level = livingEntity.level();
			double boostedProbability = getAutoRepairChance(probability, level, livingEntity.blockPosition());

			if (boostedProbability > level.getRandom().nextFloat())
				stack.setDamageValue(Math.max(stack.getDamageValue() - 1, 0));

		}
	}

public static void handle(SpawnFallenLeafFromPacket message, IPayloadContext ctx) {
		ctx.enqueueWork(() -> {
			Level level = ctx.player().level();
			Random rand = new Random();
			// I think this is the correct replacement for getColor(...), but there may be a better option I missed
			int color = level.getClientLeafTintColor(message.pos());
			int r = Mth.clamp(((color >> 16) & 0xFF) + rand.nextInt(0x22) - 0x11, 0x00, 0xFF);
			int g = Mth.clamp(((color >> 8) & 0xFF) + rand.nextInt(0x22) - 0x11, 0x00, 0xFF);
			int b = Mth.clamp((color & 0xFF) + rand.nextInt(0x22) - 0x11, 0x00, 0xFF);
			level.addParticle(ColorParticleOption.create(TFParticleType.FALLEN_LEAF.get(), r / 255F, g / 255F, b / 255F),
				message.pos().getX() + level.getRandom().nextFloat(),
				message.pos().getY(),
				message.pos().getZ() + level.getRandom().nextFloat(),
				(level.getRandom().nextFloat() * -0.5F) * message.motion().x(),
				level.getRandom().nextFloat() * 0.5F + 0.25F,
				(level.getRandom().nextFloat() * -0.5F) * message.motion().z()
			);
		});
	}

