@SubscribeEvent
	@SideOnly(Side.CLIENT)
	public static void render(RenderWorldLastEvent event) {
		if (Minecraft.getMinecraft().player == null) return;
		if (Minecraft.getMinecraft().getRenderManager().options == null) return;

		Set<PhaseObject> tmp = new HashSet<>(phaseObjects);

		for (PhaseObject phaseObject : tmp) {
			if (Minecraft.getMinecraft().world.getTotalWorldTime() - phaseObject.lastWorldTick > phaseObject.expiry)
				phaseObjects.remove(phaseObject);

			float time = ClientTickHandler.getTicksInGame() +
					(Minecraft.getMinecraft().isGamePaused() ? 0 : ClientTickHandler.getPartialTicks());
			BufferBuilder bufferBuilder = beginRender();
			render(phaseObject, time, bufferBuilder);
			finishRender(bufferBuilder);
		}
	}

protected void checkAndPerformAttack(LivingEntity target, double sqrDistToTarget) {
		if (sqrDistToTarget <= getAttackReachSqr(target)) {
			if (attackCooldown <= 0) {
				this.attackCooldown = this.attackInterval;
				this.entity.swing(InteractionHand.MAIN_HAND);

				this.attackDamageTick = this.entity.level().getGameTime() + this.preAttackTime;
			}

			if (this.attackDamageTick >= 0 && this.entity.level().getGameTime() >= attackDamageTick) {
				this.entity.doHurtTarget(target);

				this.attackDamageTick = -1;
			}
		}
		else {
			this.attackDamageTick = -1;
		}
	}

@Override
	public void inventoryTick(ItemStack stack, Level world, Entity entity, int itemSlot, boolean isSelected) {
		if (world.getGameTime() % 10 == 0 && entity instanceof LivingEntity livingEntity) {
			float damageScaling = stack.getOrDefault(AoADataComponents.DAMAGE_SCALING, 0f);

			if (isSelected) {
				float currentCalcBuff = getKnockbackMultiplier(entity);

				if (damageScaling != currentCalcBuff) {
					stack.set(AoADataComponents.DAMAGE_SCALING, currentCalcBuff);
					livingEntity.getAttribute(Attributes.ATTACK_KNOCKBACK).addOrUpdateTransientModifier(getKnockbackModifier(stack, damageScaling == 0 ? 1 : damageScaling));
				}
			}
			else if (damageScaling != 0 && livingEntity.getMainHandItem().isEmpty()) {
				livingEntity.getAttribute(Attributes.ATTACK_KNOCKBACK).addOrUpdateTransientModifier(getKnockbackModifier(stack, 1));
				stack.set(AoADataComponents.DAMAGE_SCALING, 0f);
			}
		}
	}

