        if (e.getEntity().level.isClientSide)
            return;
        if (e.getEntity().level.getGameTime() % 100 == 0 && e.getEntity().getServer() != null && e.getEntity() instanceof ServerPlayer serverPlayer) {
            List<Integer> litID = new ArrayList<>();
            for (ServerPlayer player : serverPlayer.getServer().getPlayerList().getPlayers()) {
                NonNullList<ItemStack> list = player.inventory.items;
                for (int i = 0; i < 9; i++) {
                    ItemStack jar = list.get(i);
                    if (jar.getItem() == ItemsRegistry.JAR_OF_LIGHT.asItem()) {
                        litID.add(player.getId());
                        break;
                    }
                }
            }
            Networking.sendToPlayerClient(new PacketSyncLitEntities(litID), serverPlayer);
        }
    }

public static @Nullable SpellContext tryPropagateEntitySpell(EnchantedFallingBlock fallingblockentity, Level level, Entity shooter, SpellContext spellContext, SpellResolver resolver) {
        if (!resolver.hasFocus(ItemsRegistry.SHAPERS_FOCUS.get()))
            return null;
        SpellContext context = spellContext.makeChildContext();
        spellContext.setCanceled(true);
        fallingblockentity.context = context;
        EntityHitResult hitResult = new EntityHitResult(fallingblockentity, fallingblockentity.position);
        SpellResolver newResolver = resolver.getNewResolver(context);
        if (spellContext.isDelayed()) {
            var currenDelay = spellContext.getDelayedSpellEvent();
            newResolver.hitResult = hitResult;
            DelayedSpellEvent delayedSpellEvent = new DelayedSpellEvent(currenDelay.duration, hitResult, level, newResolver);
            EventQueue.getServerInstance().addEvent(delayedSpellEvent);
            context.delay(delayedSpellEvent);
        } else {
            newResolver.onResolveEffect(level, new EntityHitResult(fallingblockentity, fallingblockentity.position));
        }
        return context;
    }

@Override
    public void onRedstonePower(MobJarTile tile) {
        if (!(tile.getLevel() instanceof ServerLevel level) || isPowered(tile) || tile.getExtraDataTag().getLong("lastActive") == level.getGameTime()) {
            return;
        }

        Breeze breeze = this.entityFromJar(tile);
        BreezeWindCharge windCharge = new BreezeWindCharge(breeze, level);
        var pos = tile.getBlockPos().getCenter().add(new Vec3(tile.getBlockState().getValue(MobJar.FACING).step()).scale(0.6));
        var dir = tile.getBlockState().getValue(MobJar.FACING).step();
        windCharge.setPos(pos);
        breeze.playSound(SoundEvents.BREEZE_SHOOT, 1.5F, 1.0F);
        windCharge.shoot(dir.x, dir.y, dir.z, 0.7F, (float) (5 - level.getDifficulty().getId() * 4));
        level.addFreshEntity(windCharge);

        var tag = new CompoundTag();
        tag.putLong("lastActive", level.getGameTime());
        tile.setExtraDataTag(tag);
    }

