public int getTotalPromisedAndRemoveExpired(ItemStack stack, int expiryTime) {
		int promised = 0;
		List<RequestPromise> list = promisesByItem.get(stack.getItem());
		if (list == null)
			return promised;

		for (Iterator<RequestPromise> iterator = list.iterator(); iterator.hasNext();) {
			RequestPromise promise = iterator.next();
			if (!ItemStack.isSameItemSameComponents(promise.promisedStack.stack, stack))
				continue;
			if (expiryTime != -1 && promise.ticksExisted >= expiryTime) {
				iterator.remove();
				onChanged.run();
				continue;
			}

			promised += promise.promisedStack.count;
		}
		return promised;
	}

@Override public boolean canUse() {
            long i = mob.level().getGameTime();
            if(i - lastCanUseCheck < 20L) return false;
            else {
                lastCanUseCheck = i;
                LivingEntity livingentity = mob.getTarget();
                if(livingentity == null) return false;
                else if(!livingentity.isAlive()) return false;
                else if(canPenalize) {
                    if(--ticksUntilNextPathRecalculation <= 0) {
                        path = mob.getNavigation().createPath(UniversalPosition.toBlockPos(livingentity.position().offsetRandom(mob.getRandom(), 3F)), 0);
                        ticksUntilNextPathRecalculation = 4 + mob.getRandom().nextInt(7);
                        return path != null;
                    } else return true;
                } else {
                    path = mob.getNavigation().createPath(UniversalPosition.toBlockPos(livingentity.position().offsetRandom(mob.getRandom(), 3F)), 0);
                    return path != null || mob.distanceToSqr(livingentity) < 25D;
                }
            }
        }

protected void handleGridClick(ModuleHost host, ModuleGrid.GridPos cell, double mouseX, double mouseY, int mouseButton, ClickType type) {
        float x = 0.5F;
        float y = 0.5F;
        ModuleEntity<?> entity = cell.getEntity();
        if (entity != null) {
            int cs = grid.getCellSize();
            int mw = entity.getWidth() * cs;
            int mh = entity.getHeight() * cs;
            int mx = (int) xMin() + (entity.getGridX() * cs);
            int my = (int) xMin() + (entity.getGridY() * cs);
            x = (float) (mouseX - mx) / mw;
            y = (float) (mouseY - my) / mh;
        }
        DraconicNetwork.sendModuleContainerClick(player.player.registryAccess(), cell, x, y, mouseButton, type);
        InstallResult result = grid.cellClicked(host, cell, x, y, mouseButton, type);
        if (result != null && result.resultType != InstallResult.InstallResultType.YES && result.resultType != InstallResult.InstallResultType.OVERRIDE) {
            lastError = result.reason;
            lastErrorTime = 0;
        }
    }

