private void checkValueState(Level world) {
        if (world == null) return;
        long currentWorldTime = world.getGameTime();
        if (currentWorldTime != lastUpdatedWorldTime) {
            long dif = currentWorldTime - lastUpdatedWorldTime;
            if (dif >= values.length || dif < 0) {
                Arrays.fill(values, defaultValue);
                currentIndex = 0;
            } else {
                for (int i = currentIndex + 1; i <= currentIndex + dif; i++) {
                    values[i % values.length] = defaultValue;
                }
                currentIndex += dif;
                if (currentIndex >= values.length)
                    currentIndex = currentIndex % values.length;
            }
            this.lastUpdatedWorldTime = currentWorldTime;
            dirty = true;
        }
    }

public static void handle(PacketTileData message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      ServerPlayer player = (ServerPlayer) ctx.player();
      Level world = player.getCommandSenderWorld();
      BlockEntity tile = world.getBlockEntity(message.pos);
      if (tile instanceof TileBlockEntityCyclic) {
        TileBlockEntityCyclic base = (TileBlockEntityCyclic) tile;
        if (message.autoIncrement) {
          //ignore message.value, do a ++
          int incr = base.getField(message.field) + 1;
          base.setField(message.field, incr);
        }
        else {
          base.setField(message.field, message.value);
        }
        base.setChanged();
      }
    });

  }

public void updateTask() {
        super.updateTask();

        if(this.host.getRNG().nextInt(20) == 0)
            this.host.getEntityWorld().playEvent(1010, new BlockPos(this.entityPosX, this.entityPosY, this.entityPosZ), 0);

        ++this.breakingTime;
        int breaking = (int)((float)this.breakingTime / 240.0F * 10.0F);

        if(breaking != this.lastBreakTime) {
            this.host.getEntityWorld().sendBlockBreakProgress(this.host.getEntityId(), new BlockPos(this.entityPosX, this.entityPosY, this.entityPosZ), breaking);
            this.lastBreakTime = breaking;
        }

        if(this.breakingTime == 240 && this.host.getEntityWorld().getDifficulty() == EnumDifficulty.HARD) {
            this.host.getEntityWorld().setBlockToAir(new BlockPos(this.entityPosX, this.entityPosY, this.entityPosZ));
            this.host.getEntityWorld().playEvent(1012, new BlockPos(this.entityPosX, this.entityPosY, this.entityPosZ), 0);
            this.host.getEntityWorld().playEvent(2001, new BlockPos(this.entityPosX, this.entityPosY, this.entityPosZ), 0);
        }
    }

