		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 5 != 0) {
			return;
		}
		if (isEnabled(voidTear)) {
			if (isEmpty(voidTear)) {
				setEmpty(voidTear); // fixes issue when creative inventory is opened and active tear gets messed up
				return;
			}

			ItemStack contents = getTearContents(voidTear);

			if (!contents.isEmpty()) {
				fillTear(voidTear, player, contents);
			} else {
				setEmpty(voidTear);
			}
		}
	}

private void updateAnimationState(float partialTicks) {
        float openAnimation = 0;
        switch (state) {
            case OPENING -> {
                openAnimation = (float) ((minecraft.level.getGameTime() + partialTicks - startAnimation) / OPEN_ANIMATION_LENGTH);
                if (openAnimation >= 1.0 || getVisibleItemCount() == 0) {
                    openAnimation = 1;
                    state = State.NORMAL;
                }
            }
            case CLOSING -> {
                openAnimation = 1 - (float) ((minecraft.level.getGameTime() + partialTicks - startAnimation) / OPEN_ANIMATION_LENGTH);
                if (openAnimation <= 0 || getVisibleItemCount() == 0) {
                    openAnimation = 0;
                    state = State.CLOSED;
                }
            }
        }
        this.animProgress = openAnimation;
    }

