protected void checkAndPerformAttack(LivingEntity enemy, boolean inRange) {
        long currentTime = mob.level.getGameTime();
        if (inRange) {
            if (currentTime > attackEndTick + 20) {
                ServerAnimationInfo animationInfo = mob.startAttack();
                if (animationInfo.usesAttackBox && enemy instanceof ServerPlayer player) {
                    MessageHandler.SYNC_CHANNEL.sendToPlayers(List.of(player), new S2CActivateAttackBoxesMessage(mob, animationInfo.animation.animationLength));
                    doingHeavyAttack = true;
                } else {
                    attackDamageTick = (long) (currentTime + animationInfo.actionDelay + 5);
                }
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength + 5);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
            }
            if (attackDamageTick > 0 && currentTime == attackDamageTick) {
                mob.attackTarget(enemy);
                attackDamageTick = -1;
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (isReachedTarget()) {
            //Only start if entity has stopped because eating and moving animations cant stack
            if (entity.level.getBlockEntity(targetPos) instanceof FeederBlockEntity feeder && Math.abs(entity.animationSpeed) <= Util.SWING_ANIM_THRESHOLD) {
                feedingTicks++;
                if (entity.getHunger() < entity.getMaxHunger()) {
                    //Prevent overfeeding when goal is not done due to the running animation
                    feeder.feedDinosaur(entity);
                }
                entity.heal(0.1f);
                if (entity.level.getGameTime() > animEndTick) {
                    AnimationInfo animationInfo = entity.nextEatingAnimation();
                    entity.getAnimationLogic().triggerAnimation(AnimationLogic.IDLE_CTRL, animationInfo, AnimationCategory.EAT);
                    animEndTick = (long) (entity.level.getGameTime() + animationInfo.animation.animationLength);
                }
            }
        }
    }

@Override
    public boolean canContinueToUse() {
        if (dino.level.getGameTime() < attackEndTick) {
            //Prevent the goal from ending before the animation is over
            return true;
        }
        ToyBase currentToyTarget = dino.moodSystem.getToyTarget();
        if (currentToyTarget == null) {
            currentToyTarget = target;
        }
        if (currentToyTarget == null || dino.moodSystem.getPlayingCooldown() > 0) {
            return false;
        }
        double d = getFollowDistance();
        if (dino.distanceToSqr(currentToyTarget) > d * d || dino.getCurrentOrder() != OrderType.WANDER) {
            return false;
        }
        dino.moodSystem.setToyTarget(currentToyTarget);
        return true;
    }

@Override
    protected void trySleeping() {
        if (nextTryTick == -1) {
            if (!mob.isFlying() && !mob.isTakingOff()) {
                super.trySleeping();
                return;
            }
            if (mob.aiActivityType() == PrehistoricEntityInfoAI.Activity.BOTH) {
                if (mob.getRandom().nextInt(1200) == 0 && wantsToSleep() && canSleep()) {
                    trySleepingOrLanding();
                }
            } else if (mob.aiActivityType() != PrehistoricEntityInfoAI.Activity.NO_SLEEP) {
                if (mob.getRandom().nextInt(200) == 0 && wantsToSleep() && canSleep()) {
                    trySleepingOrLanding();
                }
            }
        } else if (nextTryTick == mob.level.getGameTime()) {
            trySleepingOrLanding();
        }
    }

public static <T extends IFactionPlayer<T> & ISkillPlayer<T>> void handleUnlockSkillPacket(ServerboundUnlockSkillPacket msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            Player player = context.player();
            Optional<T> factionPlayerOpt = FactionPlayerHandler.get(player).getCurrentSkillPlayer();
            factionPlayerOpt.ifPresent(factionPlayer -> {
                Holder<ISkill<?>> skill = msg.skill();
                if (skill != null) {
                    ISkillHandler<T> skillHandler = factionPlayer.getSkillHandler();
                    ISkillHandler.Result result = skillHandler.canSkillBeEnabled(skill, msg.skillTree());
                    if (result == ISkillHandler.Result.OK) {
                        //noinspection unchecked
                        skillHandler.enableSkill((Holder<ISkill<T>>) (Object) skill, msg.skillTree());

                    } else {
                        LOGGER.warn("Skill {} cannot be activated for {} ({})", skill, player, result);
                    }
                }
            });
        });
    }

