public int getSearchedItemCount() {
        // this gets called every frame from the render methods, so some caching is desirable...
        if (world.getGameTime() - lastCheck >= 20) {
            cachedAmount = 0;
            IOHelper.getInventoryForBlock(world.getBlockEntity(pos)).ifPresent(handler -> {
                int itemCount = 0;
                Item searchedItem = PneumaticArmorItem.getSearchedItem(ClientUtils.getWornArmor(EquipmentSlot.HEAD));
                if (searchedItem != null) {
                    for (int l = 0; l < handler.getSlots(); l++) {
                        if (!handler.getStackInSlot(l).isEmpty()) {
                            itemCount += getSearchedItemCount(handler.getStackInSlot(l), searchedItem);
                        }
                    }
                }
                cachedAmount = itemCount;
            });
            lastCheck = world.getGameTime();
        }
        return cachedAmount;
    }

public JsonObject toJson() {
        JsonObject json = ModRecipeSerializers.AMADRON_OFFERS.get().codec()
                .encode(this, JsonOps.INSTANCE, JsonOps.INSTANCE.mapBuilder())
                .build(new JsonObject())
                .resultOrPartial(s -> Log.error("can't create json: " + s))
                .orElseThrow()
                .getAsJsonObject();

        json.addProperty("offeringPlayerName", offeringPlayerName);
        json.addProperty("offeringPlayerId", offeringPlayerId.toString());
        json.addProperty("inStock", inStock);
        json.addProperty("pendingPayments", pendingPayments);
        if (providingPos != null) {
            json.add("providingPos", GlobalPosHelper.toJson(providingPos));
        }
        if (returningPos != null) {
            json.add("returningPos", GlobalPosHelper.toJson(returningPos));
        }
