@Override
	public ResourceKey<Biome> getBiome(int biomeX, int biomeZ) {
		long key = ChunkPos.pack(biomeX, biomeZ);
		ResourceKey<Biome> cached = cachedSamples.get(key);
		if (cached != null && cached != Biomes.THE_VOID)
			return cached;
		ResourceKey<Biome> computed = transformer.getBiome(biomeX, biomeZ);
		ResourceKey<Biome> existing = cachedSamples.putIfAbsent(key, computed);
		if (existing != null && existing != Biomes.THE_VOID)
			return existing;
		evictionQueue.offer(key);
		if (evictionQueue.size() > maxCache) {
			for (int i = 0, limit = maxCache / 16; i < limit; i++) {
				Long oldest = evictionQueue.poll();
				if (oldest != null)
					cachedSamples.remove(oldest);
			}
		}
		return computed;
	}

@Override
	public void trySpawnHintMonster(Level world, Player player, BlockPos pos) {
		// check if the timer is valid
		long currentTime = world.getGameTime();

		// if someone set the time backwards, fix the spawn timer
		if (currentTime < this.lastSpawnedHintMonsterTime) {
			this.lastSpawnedHintMonsterTime = 0;
		}

		if (currentTime - this.lastSpawnedHintMonsterTime > 1200) {
			// okay, time is good, try several times to spawn one
			for (int i = 0; i < 20; i++) {
				if (didSpawnHintMonster(world, player, pos)) {
					this.lastSpawnedHintMonsterTime = currentTime;
					break;
				}
			}
		}
	}

