private static void purgeExpiredEntries() {
		if (!AoAConfigs.CLIENT.showXpParticles.get()) {
			particlesMap.clear();

			return;
		}

		Iterator<Map.Entry<AoASkill, CopyOnWriteArrayList<XPParticle>>> particleEntries = particlesMap.entrySet().iterator();
		long currentTime = System.currentTimeMillis();
		long expiryTime = currentTime - 1800;

		while (particleEntries.hasNext()) {
			Map.Entry<AoASkill, CopyOnWriteArrayList<XPParticle>> entry = particleEntries.next();

			entry.getValue().removeIf(particle -> particle.creationTime <= expiryTime);

			if (entry.getValue().isEmpty())
				particleEntries.remove();
		}
	}

@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack heldStack = player.getItemInHand(hand);

		if (getCharge(heldStack) <= 0 && InventoryUtil.findItemForConsumption(player, AoAItems.CRYSTALLITE, player.getAbilities().instabuild ? 0 : 1, true)) {
			setCharge(heldStack, level.getGameTime() + 2400);
			heldStack.update(DataComponents.ATTRIBUTE_MODIFIERS, ItemAttributeModifiers.EMPTY, modifiers -> modifiers.withModifierAdded(Attributes.ATTACK_DAMAGE, new AttributeModifier(BASE_ATTACK_DAMAGE_ID, 3 + getTier().getAttackDamageBonus(), AttributeModifier.Operation.ADD_VALUE), EquipmentSlotGroup.MAINHAND));

			if (level instanceof ServerLevel serverLevel) {
				double xOffset = -Mth.sin(player.getYRot() * (float)Math.PI / 140f);
				double zOffset = Mth.cos(player.getYRot() * (float)Math.PI / 140f);

				serverLevel.sendParticles(ParticleTypes.END_ROD, player.getX() + xOffset, player.getY() + player.getBbHeight() * 0.5d, player.getZ() + zOffset, 5, xOffset, 0, zOffset, 0);
			}

			return InteractionResultHolder.success(heldStack);
		}

		return super.use(level, player, hand);
	}

@NotNull
	@Override
	public BlockState updateShape(@NotNull BlockState state, Direction facing, @NotNull BlockState facingState, @NotNull LevelAccessor world, @NotNull BlockPos currentPos, @NotNull BlockPos facingPos) {
		BooleanProperty prop = switch(facing) {
		case UP -> BLOCK_UP;
		case NORTH -> BLOCK_NORTH;
		case SOUTH -> BLOCK_SOUTH;
		case WEST -> BLOCK_WEST;
		case EAST -> BLOCK_EAST;
		default -> BLOCK_DOWN;
		};
		if(state.getValue(WATERLOGGED)) {
			world.scheduleTick(currentPos, Fluids.WATER, Fluids.WATER.getTickDelay(world));
		}
		if(state.getBlock() == facingState.getBlock() && state.getValue(LIGHT) == facingState.getValue(LIGHT) && state.getValue(SOLID) == facingState.getValue(SOLID)) {
			return state.setValue(prop, true);
		} else {
			return state.setValue(prop, false);
		}
	}

protected boolean tick(PipeBlockEntity pipe) {
			long gameTime = pipe.level.getGameTime();
			if(lastTickUpdated != gameTime) {
				lastTickUpdated = gameTime;

				ticksInPipe++;
				timeInWorld++;

				if(ticksInPipe == PipesModule.effectivePipeSpeed / 2 - 1) {
					outgoingFace = getTargetFace(pipe);
				}

				if(outgoingFace == null) {
					valid = false;
					return true;
				}
			}

			return ticksInPipe >= PipesModule.effectivePipeSpeed;
		}

