public static <I extends Block> DeferredBlock<I> register(final String name, final Function<Properties, ? extends I> func, Supplier<Properties> properties,
                                                              boolean generateDefaultBlockItem, Rarity rarity,
                                                              LootTableType lootTableType) {
        DeferredBlock<I> object = BLOCKS.registerBlock(name, func, properties);
        BLOCK_DATA_GEN_SETTINGS.put(Identifier.fromNamespaceAndPath(Occultism.MODID, name), new BlockDataGenSettings(generateDefaultBlockItem, lootTableType));

        if (generateDefaultBlockItem) {
            if (name.contains("natural")) {
                OccultismItems.ITEMS.registerItem(name, p -> new OccultismBlockItem(object.get(), p.overrideDescription(object.get().getDescriptionId())));
            } else {
                if (rarity == Rarity.COMMON) {
                    OccultismItems.ITEMS.registerItem(name, p -> new BlockItem(object.get(), p.useBlockDescriptionPrefix()));
                } else {
                    OccultismItems.ITEMS.registerItem(name, p -> new BlockItem(object.get(), p.useBlockDescriptionPrefix().rarity(rarity).fireResistant()));
                }
            }
        }

        return object;
    }

@Override
            public void onPlayerTickActive(PlayerEntity player, ItemStack itemStack) {
                World world = player.world;
                boolean isRaining, canRain = true;
                if (world.getGameTime() % 20 == 0) {
                    canRain = !(world.getBiome(player.getPosition()).getPrecipitation() == Biome.RainType.NONE);
                }

                isRaining = canRain && (world.isRaining() || world.isThundering());
                boolean sunVisible = world.isDaytime() && !isRaining && world.canBlockSeeSky(player.getPosition().add(0, 1, 0));
                boolean moonVisible = !world.isDaytime() && !isRaining && world.canBlockSeeSky(player.getPosition().add(0, 1, 0));
                if (!world.isRemote && world.getDimensionType().hasSkyLight() && (world.getGameTime() % 80) == 0) {
                    double lightLevelScaled = (world.getLightFor(LightType.SKY, player.getPosition().up()) - world.getSkylightSubtracted())/15D;
                    if (sunVisible) {
                        ElectricItemUtils.givePlayerEnergy(player, (int) (applyPropertyModifiers(MPAConstants.ENERGY_GENERATION_DAY) * lightLevelScaled));
                    } else if (moonVisible) {
                        ElectricItemUtils.givePlayerEnergy(player, (int) (applyPropertyModifiers(MPAConstants.ENERGY_GENERATION_NIGHT) * lightLevelScaled));
                    }
                }
            }

private int getAudibleSubtitlesWidth(Minecraft minecraft, Font font) {
        if (!minecraft.options.showSubtitles().get() || minecraft.gui.hud.subtitleOverlay.audibleSubtitles.isEmpty()) {
            //Subtitles are disabled or none are currently showing, don't bother calculating a width
            return 0;
        }
        if (lastSubtitleGuiTick != minecraft.gui.hud.getGuiTicks()) {
            lastSubtitleGuiTick = minecraft.gui.hud.getGuiTicks();
            int maxWidth = 0;
            for (SubtitleOverlay.Subtitle subtitle : minecraft.gui.hud.subtitleOverlay.audibleSubtitles) {
                //Note: We know all subtitles here are still active, so we can skip checking
                maxWidth = Math.max(maxWidth, font.width(subtitle.getText()));
            }
            //Note: This mirrors vanilla having them as separate pieces for calculating the width instead of just doing font.width("< > ")
            // Presumably this is because Font#width returns Math#ceil, so the below has a chance of being larger than doing it as a single calculation
            maxWidth += font.width("<") + font.width(" ") + font.width(">") + font.width(" ");

            lastSubtitleWidth = maxWidth;
        }
        return lastSubtitleWidth;
    }

public void tickServer(Level level, BlockPos pos) {
        if (level.getGameTime() % 5 == tickOffset) {
            if (securityFrequency != null) {
                updateFrequency(FrequencyTypes.SECURITY, securityFrequency, level);
            }
            nonSecurityFrequencies.forEach(level, updateFrequencyRef);
        }
        if (needsNotify) {
            tile.invalidateCapabilitiesFull();
            WorldUtils.notifyLoadedNeighborsOfTileChange(level, pos);
            needsNotify = false;
        }
        if (needsSave) {
            //Mark the entire tile as dirty as maybe the frequency having changed means we need to update
            // comparators if the comparators are based on data stored in the frequency
            //TODO: Make it so that we only update comparators and stuff if we needed to
            tile.setChanged();
            needsSave = false;
        }
    }

@Override
    public void handleUpdateTag(ValueInput input) {
        super.handleUpdateTag(input);
        //input.child(SerializationConstants.FLUID).ifPresent(fluidTank::deserialize);
        //valveFluid = input.read(SerializationConstants.VALVE, FluidStack.OPTIONAL_CODEC).orElse(FluidStack.EMPTY);
        float scale = input.getFloatOr(SerializationConstants.SCALE, 0);
        if (lightUpdateDelay == 0 && MekanismUtils.scaleChanged(prevScale, scale)) {
            if (prevScale == 0 || scale == 0) {
                //If it was empty and no longer is, or wasn't empty and now is empty we want to recheck the block lighting
                // as the fluid may have changed and have a light value, mark that the client should update the light value
                //Note: If we previously had no fluid, we queue the lighting for the next client tick
                lightUpdateDelay = prevScale == 0 ? 1 : MekanismConfig.general.blockDeactivationDelay.get();
            }
        }
        //TODO - 26.3: Should we only update this when the scale has changed? And/or if we had updated the light level?
        prevScale = scale;

        ValueUtils.readOrEmpty(input, SerializationConstants.FLUID, fluidTank);
        valveJournal.fluid = input.read(SerializationConstants.VALVE, FluidResource.CODEC).orElse(FluidResource.EMPTY);
    }

