private void enqueue(IPathItem pathItem, int queueIndex) {
        visited.add(pathItem);

        int possibleIndex;

        if (pathItem instanceof GridConnection) {
            // Grid connection does not have flags, allow any queue.
            possibleIndex = 0;
        } else if (pathItem.hasFlag(GridFlags.DENSE_CAPACITY)) {
            // Dense queue if possible.
            possibleIndex = 0;
        } else if (pathItem.hasFlag(GridFlags.PREFERRED)) {
            // Cable queue if possible.
            possibleIndex = 1;
        } else {
            possibleIndex = 2;
        }

        int index = Math.max(possibleIndex, queueIndex);
        queues[index].add(pathItem);
    }

@Override
    public boolean wakeDevice(IGridNode node) {
        Objects.requireNonNull(node);

        // Avoid corrupting the tick queue if the node is already ticking at this time
        // The result of its ticking method will take precedence over this call
        if (node == currentlyTicking) {
            return false;
        }

        if (this.sleeping.containsKey(node)) {
            final TickTracker tt = this.sleeping.get(node);
            this.sleeping.remove(node);
            this.awake.put(node, tt);
            this.updateQueuePosition(node, tt);

            return true;
        }

        return false;
    }

private void tryEnqueueProcess(State state, Level level)
	{
		if(state.energy.getEnergyStored() <= 0||state.processor.getQueueSize() >= state.processor.getMaxQueueSize())
			return;
		final FluidStack leftInput = state.tanks.leftInput.getFluid();
		final FluidStack rightInput = state.tanks.rightInput.getFluid();
		if(leftInput.isEmpty()&&rightInput.isEmpty())
			return;
		final ItemStack catalyst = state.inventory.getStackInSlot(SLOT_CATALYST);
		RecipeHolder<RefineryRecipe> recipe = RefineryRecipe.findRecipe(level, leftInput, rightInput, catalyst);
		if(recipe==null)
			return;
		MultiblockProcessInMachine<RefineryRecipe> process = new MultiblockProcessInMachine<>(recipe);
		if(!leftInput.isEmpty()&&!rightInput.isEmpty())
			process.setInputTanks(0, 1);
		else if(!leftInput.isEmpty())
			process.setInputTanks(0);
		else
			process.setInputTanks(1);
		state.processor.addProcessToQueue(process, level, false);
	}

