private void attractEntities(Level level, BlockPos pos, int range) {
        if ((level.getGameTime() + pos.asLong()) % 5 == 0) {
            getEntities(level, pos, range, getFilter());
        }
        Iterator<WeakReference<T>> iterator = entities.iterator();
        while (iterator.hasNext()) {
            WeakReference<T> ref = iterator.next();
            if (ref.get() == null) { // If the entity no longer exists, remove from the list
                iterator.remove();
                continue;
            }
            T entity = ref.get();
            if (entity.isRemoved()) { // If the entity no longer exists, remove from the list
                iterator.remove();
                continue;
            }
            if (AttractionUtil.moveToPos(entity, pos, SPEED, SPEED_4, COLLISION_DISTANCE_SQ)) {
                handleEntity(entity);
            }
        }
    }

public void handleShortTravelRequest(ServerboundRequestShortTravelPacket packet, IPayloadContext context) {
        context.enqueueWork(() -> {
            var player = context.player();
            if(player == null)
                return;

            // For keybind anchor teleports
            ItemStack travelItemStack = TravelHandler.findTravelItem(player);

            // These errors should only ever be triggered if there's some form of desync
            if (travelItemStack.isEmpty()) {
                player.displayClientMessage(EIOCommonLang.ERROR_CANNOT_TELEPORT, true);
                return;
            }

            if(TravelHandler.shortTeleport(player.level(), player, false)){
                TravelHandler.consumeResources(travelItemStack);
                player.getCooldowns().addCooldown(travelItemStack.getItem(), BaseConfig.COMMON.ITEMS.TRAVELLING_BLINK_DISABLED_TIME.get());
            }
        });
    }

public void update() {
        if (this.startTicks == -1) return;
        var level = level();

        //noinspection ConstantValue
        if (level == null) {
            this.startTicks = -1;
            return;
        }
        long gameTime = level.getGameTime();
        if (gameTime < this.startTicks + this.onTicks) {
            this.percentage = (gameTime - this.startTicks) / (float) this.onTicks;
        } else if (gameTime < this.startTicks + this.onTicks + this.mainTicks) {
            this.percentage = 1;
        } else if (gameTime < this.startTicks + this.onTicks + this.mainTicks + this.offTicks) {
            this.percentage = 1f - (gameTime - this.startTicks - this.onTicks - this.mainTicks) / (float) this.offTicks;
        } else {
            this.startTicks = -1;
            this.percentage = 0;
        }
    }

