		}

		// Initialize timer for new items
		if (!ItemNBTHelper.verifyExistance(stack, TAG_LAST_TRIGGER)) {
			ItemNBTHelper.setLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
		}

		MobEffectInstance haste = player.getEffect(MobEffects.DIG_SPEED);
		float check = haste == null ? 0.16666667F : haste.getAmplifier() == 1 ? 0.5F : 0.4F;

		long timeSinceLast = world.getGameTime() - ItemNBTHelper.getLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
		if (timeSinceLast > INTERVAL && player.getMainHandItem() == stack && player.attackAnim == check && !world.isClientSide) {
			ItemNBTHelper.setLong(stack, TAG_LAST_TRIGGER, world.getGameTime());
			summonFallingStar(stack, world, player);
		}
	}

public int add(SoulTicket ticket, int maximum)
	{
		SoulNetworkEvent.Fill event = new SoulNetworkEvent.Fill(this, ticket, maximum);
		if (MinecraftForge.EVENT_BUS.post(event))
			return 0;

		int currEss = getCurrentEssence();

		if (currEss >= event.getMaximum())
			return 0;

		int newEss = Math.min(event.getMaximum(), currEss + event.getTicket().getAmount());
		setCurrentEssence(newEss);

		if (ticketHistory.contains(ticket))
			ticketHistory.remove(ticket); // "Pops" the existing ticket to the top of the queue

		ticketHistory.add(ticket);

		return newEss - currEss;
	}

public Entry getOrCreateTemplate(ServerLevel serverLevel, BlockPos worldPosition, ResourceKey<Level> key) {
            Entry entry = entries.get(key);
            if (entry == null) {
                StructureTemplate template = loadTemplate(serverLevel, worldPosition, key);
                if (template == null) {
                    return null;
                }
                entries.put(key, new Entry(template, false, serverLevel.getGameTime()));
                return entries.get(key);
            }

            if (!entry.dirty && entry.template != null) {
                return entry;
            }
            StructureTemplate template = loadTemplate(serverLevel, worldPosition, key);
            if (template == null) {
                return null;
            }
            entries.put(key, new Entry(template, false, serverLevel.getGameTime()));
            return entries.get(key);
        }

@Override
    public boolean canContinueToUse() {
        if (ticksRunning >= 20 * 15) {
            starbuncle.addGoalDebug(this, new DebugEvent("BedTimeout", "Took too long to find bed"));
            starbuncle.goalState = Starbuncle.StarbuncleGoalState.NONE;
            return false;
        }

        if (bedPos == null || starbuncle.data.bedPos == null)
            return false;

        boolean bedValid = true;
        boolean isOnBed = false;
        // Time defer these checks otherwise we will destroy TPS with blockstate lookups.
        if (starbuncle.level.getGameTime() % 10 == 0) {
            bedValid = isBedValid();
            isOnBed = isOnBed();
        }

        return !unreachable && bedValid && !isOnBed;
    }

protected List<HitResult> raycastForEntitiesAlongPath(Vec3 destination, Vec3 position) {
        AABB range = this.getBoundingBox().expandTowards(destination.subtract(position)).inflate(0.1);
        List<HitResult> hits = new ArrayList<>();
        List<Entity> hitEntities = new ArrayList<>(); // prevents large hitbox entities from registering multiple hits in one tick
        List<? extends Entity> entities = level.getEntities(this, range, this::canHitEntity);
        for (Entity target : entities) {
            if (hitEntities.contains(target)) {
                continue;
            }
            HitResult hit = Utils.checkEntityIntersecting(target, position, destination, getHitDetectionInflation());
            if (hit.getType() != HitResult.Type.MISS) {
                hits.add(hit);
                hitEntities.add(target);
            }
        }

        if (!hits.isEmpty()) {
            hits.sort(Comparator.comparingDouble(o -> o.getLocation().distanceToSqr(position)));
        }
        return hits;
    }

private void handleLoopTracking(Entity entity) {
        var trackerData = loopTrackerLookup.get(entity.getUUID());
        if (trackerData == null) {
            trackerData = new LoopTrackerData(level.getGameTime(), 1);
            loopTrackerLookup.put(entity.getUUID(), trackerData);
        } else {
            IronsSpellbooks.LOGGER.debug("looping");
            if (++trackerData.loopCount > loopMax && level.getGameTime() - trackerData.gameTick <= loopTickWindow) {
                if (Objects.equals(getOwnerUUID(), entity.getUUID())) {
                    entity.hurt(new PortalDamageSource(entity.level().damageSources().genericKill().typeHolder(), entity), Float.MAX_VALUE);
                    if (entity instanceof LivingEntity livingEntity && Float.isNaN(livingEntity.getHealth())) {
                        livingEntity.setHealth(0.0f);
                    }
                }
                discard();
            } else if (level.getGameTime() - trackerData.gameTick > loopTickWindow) {
                //Cleanup old tracking information
                loopTrackerLookup.remove(entity.getUUID());
            }
        }
    }

