public static void handle(CreateQuestAndTaskMessage message, NetworkManager.PacketContext context) {
		context.queue(() -> ServerQuestFile.getInstance().ifPresent(sqf -> {
			if (PermissionsHelper.canPlayerEdit(context) && context.getPlayer() instanceof ServerPlayer sp) {
				Chapter chapter = sqf.getChapter(message.chapterId);
				TaskType taskType = ServerQuestFile.INSTANCE.getTaskType(message.taskTypeId);

				if (chapter != null && taskType != null) {
					var allocator = new BaseQuestFile.UniqueIdAllocator(sqf);

					Quest quest = new Quest(allocator.newId(), chapter).setPosition(message.x, message.y);

					Task task = taskType.createTask(allocator.newId(), quest);
					task.readData(message.nbt, context.registryAccess());
					CompoundTag extra = message.extra.orElse(new CompoundTag());
					sqf.getTranslationManager().processInitialTranslation(extra, task);

					List<CreateOrDeleteRecord> recs = CreateOrDeleteRecord.ofQuestObjects(quest, task);
					sqf.getHistoryStack().addAndApply(sqf, new CreateQuestObjects(recs, sp.getUUID()));
				}
			}
		}));
	}

private boolean canAdvancePumpHead() {
        // position of the pump head, i.e. the position of the lowest mining pipe
        BlockPos headPos = getBlockPos().below(pumpHeadY);

        if (pumpQueue == null || pumpQueue.queue.isEmpty()) {
            Level level;
            if ((level = getLevel()) != null) {
                BlockPos downPos = headPos.below(1);
                var downBlock = level.getBlockState(downPos);

                if (downBlock.isAir()) {
                    this.pumpHeadY++;

                    if (level instanceof ServerLevel serverLevel) {
                        serverLevel.setBlockAndUpdate(downPos, GTBlocks.MINER_PIPE.getDefaultState());
                    }
                    return true;
                }
            }
        }
        return false;
    }

public void renderQueue(VertexConsumer buffer, Collection<IParticle> particles, Camera camera, float partialTicks) {
        if (renderer.getRenderMode() == ParticleRendererSetting.Mode.None) {
            return;
        }
        ModelPass model = null;
        if (renderer.getRenderMode() == ParticleRendererSetting.Mode.Model) {
            notifyDynamicMesh();
            model = modelPass();
        }
        var records = activeRecords;
        if (records != null) {
            records.setVertsPerParticle(model == null ? 4 : 4 * primitiveCount(model.mesh()));
        }
        for (var particle : particles) {
            if (particle instanceof TileParticle tileParticle && tileParticle.getDelay() <= 0) {
                renderParticle(buffer, tileParticle, camera, partialTicks, model);
                if (records != null) {
                    records.write(tileParticle, partialTicks);
                }
            }
        }
    }

@Override
    public boolean shouldExecute() {
    	if(!this.host.isTamed())
    		return false;
    	if(this.host.isSitting())
    		return false;
		if(!this.host.isAssisting())
			return false;
    	if(this.host.getOwner() == null)
    		return false;

        if (!(this.host.getOwner() instanceof EntityLivingBase))
            return false;
        EntityLivingBase owner = (EntityLivingBase)this.host.getOwner();
    	this.target = owner.getLastAttackedEntity();
    	if(this.target == null) {
    		return false;
    	}
    	if(lastAttackTime == owner.getLastAttackedEntityTime())
    		return false;
    	return true;
    }

private boolean addEffectsToEntity(Level level, Entity collidingEntity, LivingEntity livingEntity) {
		if (!potionContents.hasEffects()) {
			return false;
		}
		// apply potion effects when done cooking potion (potion essence and netherwart in and fire below at the minimum)
		if (finishedCooking()) {
			for (MobEffectInstance effect : potionContents.getAllEffects()) {
				MobEffect potion = effect.getEffect().value();
				if (potion.isInstantenous() && level.getGameTime() % 20 != 0) {
					continue;
				}
				MobEffectInstance reducedEffect = new MobEffectInstance(effect.getEffect(), potion.isInstantenous() ? 1 : effect.getDuration() / 20,
						Math.max(0, effect.getAmplifier() - 1));
				livingEntity.addEffect(reducedEffect);
			}
		}

		if (cookTime > 0 && level.getGameTime() % 10 == 0) {
			collidingEntity.hurt(level.damageSources().inFire(), 1.0F);
		}
		return true;
	}

@Nullable
	public IItemHandler getExternalItemHandler(@Nullable Direction direction) {
		if (isBlockConnectionDisallowed(direction)) {
			return null;
		}
		if (externalItemHandler == null) {
			if (!(getBackpackWrapper().getBackpack().getItem() instanceof BackpackItem)) {
				return EmptyItemHandler.INSTANCE;
			}
			externalItemHandler = new CachedFailedInsertInventoryHandler<>(() -> {
				IBackpackWrapper backpackWrapper = getBackpackWrapper();
				if (!triedUnpackingLoot && level != null && !level.isClientSide()) {
					if (backpackWrapper.supportsBackpackContents()) {
						backpackWrapper.fillWithLootAndExtraItems(level, getBlockPos());
					}
					triedUnpackingLoot = true;
				}
				return backpackWrapper.getInventoryForInputOutput();
			}, () -> level != null ? level.getGameTime() : 0);
		}
		return externalItemHandler;
	}

public static void handlePayload(RequestLinkerCraftingDiagnosticsPayload payload, IPayloadContext context) {
		context.enqueueWork(() -> {
			if (!(context.player() instanceof ServerPlayer player) || player.containerMenu.containerId != payload.containerId) {
				return;
			}

			Map<Container, List<Slot>> craftingSlots = new IdentityHashMap<>();
			for (Slot slot : player.containerMenu.slots) {
				if (slot.container instanceof CraftingContainer) {
					craftingSlots.computeIfAbsent(slot.container, ignored -> new ArrayList<>()).add(slot);
				}
			}

			List<SyncLinkerCraftingDiagnosticsPayload.Diagnostic> diagnostics = new ArrayList<>();
			craftingSlots.forEach((container, slots) -> addDiagnostic(player, container, slots, diagnostics));
			if (player.containerMenu instanceof StorageContainerMenuBase<?> storageContainer) {
				storageContainer.getUpgradeContainers().values().stream().filter(ICraftingContainer.class::isInstance).map(ICraftingContainer.class::cast)
						.forEach(container -> addDiagnostic(player, container.getCraftMatrix(), container.getRecipeSlots(), diagnostics));
			}
			PacketDistributor.sendToPlayer(player, new SyncLinkerCraftingDiagnosticsPayload(payload.containerId, diagnostics));
		});
	}

@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		initDirections(level, pos);

		if (coolDownTime > level.getGameTime()) {
			return;
		}

		for (Direction pushDirection : pushDirections) {
			if (runOnItemHandlers(level, pos, pushDirection, this::pushItems, entity)) {
				break;
			}
		}

		for (Direction pullDirection : pullDirections) {
			if (runOnItemHandlers(level, pos, pullDirection, this::pullItems, entity)) {
				break;
			}
		}

		coolDownTime = level.getGameTime() + upgradeItem.getTransferSpeedTicks();
	}

public void tick() {
            if (this.wight.getTarget() == null) {
                super.setTarget((LivingEntity)null);
            }

            if (this.pendingTarget != null) {
                if (--this.aggroTime <= 0) {
                    this.target = this.pendingTarget;
                    this.pendingTarget = null;
                    super.start();
                }
            } else {
                if (this.target != null && !this.wight.isPassenger() && !this.wight.isMeleeAttacking()) {
                    if ((this.target.distanceToSqr(this.wight) > 256.0D || !this.wight.hasLineOfSight(this.target)) && this.teleportTime++ >= this.adjustedTickDelay(MathHelper.secondsToTicks(3.5F)) && this.wight.teleportNearTo(this.target)) {
                        this.teleportTime = 0;
                    }
                }

                super.tick();
            }

        }

public static void consume(SPurifyEffectPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Level level = Goety.PROXY.getLevel();
            if (level instanceof ClientLevel clientWorld) {
                Entity entity = clientWorld.getEntity(packet.mob);
                if (entity instanceof LivingEntity livingEntity) {
                    for (MobEffect mobEffect : ForgeRegistries.MOB_EFFECTS){
                        boolean flag;
                        if (packet.removeDebuff) {
                            flag = !mobEffect.isBeneficial();
                        } else {
                            flag = mobEffect.isBeneficial();
                        }
                        if (flag && !mobEffect.getCurativeItems().isEmpty()){
                            livingEntity.removeEffect(mobEffect);
                        }
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

@Override
	public ToolType type(ToolType type) {
		Objects.requireNonNull(type);
		Identifier id = type.getUid();
		Objects.requireNonNull(id);
		if (pendingMap.containsKey(id)) {
			Jade.LOGGER.warn("Skipped duplicate harvest tool type registration: {}", id);
			return pendingMap.get(id);
		}
		pendingMap.put(id, type);
		CallbackContainer<ToolTierAddedCallback> callbacks = pendingCallbacks.remove(id);
		if (callbacks != null) {
			for (ToolTierAddedCallback callback : callbacks.callbacks()) {
				type.tierAddedCallbacks().add(callback);
			}
		}
		CallbackContainer<Consumer<ToolType>> typeCallbacks = pendingTypeCallbacks.remove(id);
		if (typeCallbacks != null) {
			typeCallbacks.call($ -> $.accept(type));
		}
		return type;
	}

