public void getElectrostaticGrid(Set<BlockPos> grid, Set<ElectrostaticCompressorBlockEntity> compressors, BlockPos pos) {
        Deque<BlockPos> pendingPos = new ArrayDeque<>(Collections.singleton(pos));
        grid.add(pos);
        nonNullLevel().getBlockEntity(pos, ModBlockEntityTypes.ELECTROSTATIC_COMPRESSOR.get())
                .ifPresent(compressors::add);

        while (!pendingPos.isEmpty()) {
            BlockPos checkingPos = pendingPos.pop();
            for (Direction d : DirectionUtil.VALUES) {
                BlockPos newPos = checkingPos.relative(d);
                BlockState state = nonNullLevel().getBlockState(newPos);
                if ((isValidGridBlock(state) || state.getBlock() == ModBlocks.ELECTROSTATIC_COMPRESSOR.get())
                        && grid.size() < MAX_ELECTROSTATIC_GRID_SIZE && grid.add(newPos)) {
                    if (state.getBlock() == ModBlocks.ELECTROSTATIC_COMPRESSOR.get()) {
                        nonNullLevel().getBlockEntity(newPos, ModBlockEntityTypes.ELECTROSTATIC_COMPRESSOR.get())
                                .ifPresent(compressors::add);
                    }
                    pendingPos.push(newPos);
                }
            }
        }
    }

private static boolean handleHealthState(LocalPlayer player, Gui gui, float currentHealth) {
		boolean shouldFlash = gui.healthBlinkTime > (long)gui.tickCount && (gui.healthBlinkTime - (long)gui.tickCount) / 3L % 2L == 1L;

		if (currentHealth < gui.lastHealth && player.invulnerableTime > 0) {
			gui.lastHealthTime = Util.getMillis();
			gui.healthBlinkTime = gui.tickCount + 20;
		}
		else if (currentHealth > gui.lastHealth && player.invulnerableTime > 0) {
			gui.lastHealthTime = Util.getMillis();
			gui.healthBlinkTime = gui.tickCount + 10;
		}

		if (Util.getMillis() - gui.lastHealthTime > 1000L) {
			gui.lastHealth = (int)currentHealth;
			gui.displayHealth = (int)currentHealth;
			gui.lastHealthTime = Util.getMillis();
		}

		gui.lastHealth = (int)currentHealth;

		return shouldFlash;
	}

@Override
	public void receiveMessage(IPayloadContext context) {
        context.enqueueWork(() -> {
            Level level = context.player().level();
            Entity passenger = level.getEntity(this.entity);

            if (passenger == null)
                return;

            Player vehicle = level.getPlayerByUUID(this.player);

            if (vehicle == null)
                return;

            if (this.operation == Operation.MOUNT) {
                passenger.startRiding(vehicle, true);
            }
            else if (this.operation == Operation.DISMOUNT && passenger.getVehicle() == vehicle) {
                passenger.stopRiding();
            }
        });
	}

default void updateScheduledTasks() {
        if (!getImmediateTasks().isEmpty()) {
            var copyTasks = new ArrayList<>(getImmediateTasks());
            getImmediateTasks().clear();
            for (Runnable task : copyTasks) {
                task.run();
            }
        }

        var taskQueue = getScheduledTasks();
        if (taskQueue.isEmpty()) {
            return;
        }
        var currentTime = getSchedulerTime();
        var currentTasks = taskQueue.get(currentTime);
        if (currentTasks != null) {
            for (Runnable task : currentTasks) {
                task.run();
            }
            taskQueue.remove(currentTime);
        }
    }

public void setMimicState(Level level, BlockPos pos, boolean updateNeighbors) {
        MirrorWeaveTile tile = (MirrorWeaveTile) level.getBlockEntity(pos);
        if (level.isClientSide || tile == null || tile.mimicState == null || tile.nextState == null || tile.nextState.equals(tile.mimicState)) {
            return;
        }
        BlockState previousState = tile.mimicState;
        tile.mimicState = tile.nextState;
        level.setBlockAndUpdate(pos, tile.getBlockState().setValue(LIGHT_LEVEL, tile.mimicState.getLightEmission(level, pos)));
        tile.updateBlock();
        int ticks = 1;
        if (!updateNeighbors)
            return;
        for (Direction d : Direction.values()) {
            BlockPos offset = pos.relative(d);
            if (level.getBlockEntity(offset) instanceof MirrorWeaveTile neighbor) {
                if (neighbor.mimicState == previousState) {
                    neighbor.nextState = tile.mimicState;
                    level.scheduleTick(offset, neighbor.getBlockState().getBlock(), ticks++);
                }
            }
        }
    }

