public float getQueueFill(boolean allowStacking)
	{
		if(maxQueueLength <= 0) // I don't think we have an example of this, but sanity checks are good
			return 0;
		if(!allowStacking) // Easy and early return
			return this.getQueueSize()/(float)maxQueueLength;

		// And the messy one where we have to analyze the whole queue
		return getQueue().stream().map(process -> {
			if(process instanceof MultiblockProcessInWorld<? extends MultiblockRecipe> inWorld)
			{
				float f = 0;
				for(ItemStack stack : inWorld.inputItems)
					if(!stack.isEmpty())
						f = stack.getCount()/(float)stack.getMaxStackSize();
				return f/(float)inWorld.inputItems.size();
			}
			else
			{
				return 1f;
			}
		}).reduce(Float::sum).orElse(0f)/(float)maxQueueLength;
	}

public static MixerMenu makeServer(
			MenuType<?> type, int id, Inventory invPlayer, MultiblockMenuContext<State> ctx
	)
	{
		final State state = ctx.mbContext().getState();
		final GetterAndSetter<List<SlotProgress>> progress = GetterAndSetter.getterOnly(() -> {
			final Level level = ctx.mbContext().getLevel().getRawLevel();
			List<SlotProgress> result = new ArrayList<>();
			for(final MultiblockProcess<?, ?> process : state.processor.getQueue())
				if(process instanceof MixingProcess inMachine)
				{
					final float mod = 1-(process.processTick/(float)process.getMaxTicks(level));
					for(final int inputSlot : inMachine.getInputSlots())
						result.add(new SlotProgress(inputSlot, mod));
				}
			return result;
		});
		return new MixerMenu(
				multiblockCtx(type, id, ctx), invPlayer, state.getInventory(), state.energy, progress,
				GetterAndSetter.getterOnly(() -> state.tank.fluids),
				new GetterAndSetter<>(() -> state.outputAll, b -> state.outputAll = b)
		);
	}

@Override
	public void process(IPayloadContext context)
	{
		Player player = context.player();
		context.enqueueWork(() -> {
			AbstractContainerMenu container = player.containerMenu;
			for(Entry<Integer, ItemStack> e : stacksToSet.entrySet())
			{
				int slot = e.getKey();
				if(slot >= 0&&slot < container.slots.size())
				{
					Slot target = container.slots.get(slot);
					if(!(target instanceof ItemHandlerGhost))
					{
						IELogger.error("Player "+player.getDisplayName()+" tried to set the contents of a non-ghost slot."+
								"This is either a bug in IE or an attempt at cheating.");
						return;
					}
					container.setItem(slot, container.getStateId(), e.getValue());
				}
			}
		});
	}

private boolean moveMechanicalPiston(Level world, BlockPos pos, Queue<BlockPos> frontier, Set<BlockPos> visited,
										 BlockState state) throws AssemblyException {
		Direction direction = state.getValue(MechanicalPistonBlock.FACING);
		PistonState pistonState = state.getValue(MechanicalPistonBlock.STATE);
		if (pistonState == PistonState.MOVING)
			return false;

		BlockPos offset = pos.relative(direction.getOpposite());
		if (!visited.contains(offset)) {
			BlockState poleState = world.getBlockState(offset);
			if (AllBlocks.PISTON_EXTENSION_POLE.has(poleState) && poleState.getValue(PistonExtensionPoleBlock.FACING)
				.getAxis() == direction.getAxis())
				frontier.add(offset);
		}

		if (pistonState == PistonState.EXTENDED || MechanicalPistonBlock.isStickyPiston(state)) {
			offset = pos.relative(direction);
			if (!visited.contains(offset))
				frontier.add(offset);
		}

		return true;
	}

