private void delayExhaustion(Player attacker, ItemModularHandheld item, ItemStack itemStack, int duration, int amplifier) {
        int delay = getChargeTime(item, itemStack) + getCooldown(item, itemStack) + item.getEffectLevel(itemStack, ItemEffect.abilityEcho);

        try {
            DelayData data = delayCache.get(attacker.getId(), DelayData::new);
            data.timestamp = attacker.level().getGameTime() + delay;
            data.amplifier += amplifier;
        } catch (ExecutionException e) {
            e.printStackTrace();
        }

        ServerScheduler.schedule(delay + 1, () -> {
            DelayData data = delayCache.getIfPresent(attacker.getId());
            if (attacker.isAlive() && attacker.level() != null && data != null && attacker.level().getGameTime() > data.timestamp) {
                int currentAmp = Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                        .map(MobEffectInstance::getAmplifier)
                        .orElse(-1);
                attacker.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, duration, currentAmp + data.amplifier, false, true));

                delayCache.invalidate(attacker.getId());
            }
        });
    }

public static void render(PoseStack poseStack, float partialTick, Vec3 cameraPos) {
		Minecraft mc = Minecraft.getInstance();
		if (highlightExpireTime < mc.level.getGameTime()) {
			if (!highlightedPositions.isEmpty()) {
				highlightedPositions.clear();
				cachedHighlightedBlocks = null;
			}
			return;
		}
		MultiBufferSource.BufferSource buffer = mc.renderBuffers().bufferSource();

		if (cachedHighlightedBlocks == null) {
			cachedHighlightedBlocks = new HashMap<>();
			highlightedPositions.forEach((color, positionGroups) -> {
				cachedHighlightedBlocks.put(color,
						positionGroups.stream().map(positions -> getHighlightedGroup(mc, positions)).filter(Objects::nonNull).toList());
			});
		}

		cachedHighlightedBlocks.forEach((color, highlightedBlocks) -> {
			highlightedBlocks.forEach(bh -> renderHighlightedBlock(poseStack, partialTick, cameraPos, bh, mc, buffer, color));
		});
	}

public static void issueCraftClaim(Player player, ItemStack result) {
		EnderLinkPendingCraftData pendingCraft = result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		if (pendingCraft == null) {
			return;
		}
		EnderLinkPendingCraftPlan plan = pendingCraft.plan();

		UUID playerId = player.getUUID();
		InFlightClaim inFlightClaim = pendingCraft.claimId() == null ? null : IN_FLIGHT_CLAIMS.get(pendingCraft.claimId());
		if (inFlightClaim != null && inFlightClaim.playerId().equals(playerId) && inFlightClaim.plan() == plan) {
			return;
		}
		UUID latestClaimId = LATEST_IN_FLIGHT_CLAIMS.getOrDefault(playerId, Map.of()).get(plan);
		InFlightClaim latestClaim = latestClaimId == null ? null : IN_FLIGHT_CLAIMS.get(latestClaimId);
		if (latestClaim != null && latestClaim.playerId().equals(playerId) && latestClaim.plan() == plan) {
			result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, new EnderLinkPendingCraftData(pendingCraft.plan(), latestClaimId));
			return;
		}
		UUID claimId = UUID.randomUUID();
		result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, new EnderLinkPendingCraftData(pendingCraft.plan(), claimId));
		IN_FLIGHT_CLAIMS.put(claimId, new InFlightClaim(claimId, playerId, plan));
		LATEST_IN_FLIGHT_CLAIMS.computeIfAbsent(playerId, ignored -> new HashMap<>()).put(plan, claimId);
	}

public boolean shriek(ServerLevel serverLevel, @Nullable Player player, int soulEnergy) {
        BlockPos blockpos = this.getBlockPos();
        BlockState blockstate = this.getBlockState();
        int cost = (soulEnergy / MobsConfig.IllagerAssaultSEThreshold.get()) * MainConfig.ShriekObeliskCost.get();
        if (blockstate.getValue(ShriekObeliskBlock.POWERED)) {
            if (this.cursedCageTile != null) {
                if (this.cursedCageTile.getSouls() >= cost) {
                    if (!blockstate.getValue(ShriekObeliskBlock.SHRIEKING)) {
                        this.cursedCageTile.decreaseSouls(cost);
                        serverLevel.setBlock(blockpos, blockstate.setValue(ShriekObeliskBlock.SHRIEKING, Boolean.TRUE), 2);
                        serverLevel.scheduleTick(blockpos, blockstate.getBlock(), 90);
                        for (int j = 0; j < 10; ++j) {
                            serverLevel.sendParticles(new ShriekParticleOption(j * 5), (double) blockpos.getX() + 0.5D, (double) blockpos.getY() + 1.0D, (double) blockpos.getZ() + 0.5D, 1, 0.0D, 0.0D, 0.0D, 0.5F);
                        }
                        ModNetwork.sendToALL(new SPlayWorldSoundPacket(blockpos.above(), SoundEvents.SCULK_SHRIEKER_SHRIEK, 2.0F, 0.25F));
                        serverLevel.gameEvent(GameEvent.SHRIEK, blockpos, GameEvent.Context.of(player));
                        return true;
                    }
                }
            }
        }
        return false;
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        this.lastHitTime = MathHelper.secondsToTicks(15);

        if (pAmount >= 15){
            this.overwhelmed = MathHelper.secondsToTicks(15);
        }

        if (this.getHealth() <= 10.0F){
            if (pSource.is(DamageTypeTags.IS_EXPLOSION)){
                return false;
            }
        }

        if (!pSource.is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !pSource.is(DamageTypes.THORNS) && pSource.getEntity() instanceof LivingEntity livingentity && livingentity != this) {
            float thorn = 2.0F;
            if (this.level.getDifficulty() == Difficulty.HARD){
                thorn *= 2.0F;
            }
            livingentity.hurt(this.damageSources().thorns(this), thorn);
        }

        return super.hurt(pSource, pAmount);
    }

