@Override
    public boolean canUse() {
        long l = mob.level.getGameTime();
        if (l - lastCanUseCheck < COOLDOWN_BETWEEN_CAN_USE_CHECKS) {
            return false;
        }
        lastCanUseCheck = l;
        if (mob.isFleeing() || mob.getCurrentOrder() == OrderType.STAY) {
            return false;
        }
        LivingEntity target = mob.getTarget();
        if (target == null || !target.isAlive()) {
            return false;
        }
        if (mob.level.getDifficulty() == Difficulty.PEACEFUL && target instanceof Player) {
            return false;
        }
        path = mob.getNavigation().createPath(target, 0);
        if (path != null) {
            return true;
        }
        return isInRange(target);
    }

@Override
    public boolean canUse() {
        long l = dino.level.getGameTime();
        if (l - lastCanUseCheck < COOLDOWN_BETWEEN_CAN_USE_CHECKS) {
            return false;
        }
        lastCanUseCheck = l;
        if (dino.isFleeing() || dino.getTarget() != null || dino.getCurrentOrder() != OrderType.WANDER) {
            return false;
        }
        if (dino.moodSystem.getPlayingCooldown() > 0 || dino.moodSystem.getMood() >= 100) {
            return false;
        }
        target = findPlayTarget();
        if (target == null) {
            return false;
        }
        path = dino.getNavigation().createPath(target, 0);
        if (path != null) {
            return true;
        }
        return Util.canReachPrey(dino, target);
    }

public ActiveAnimationInfo addActiveAnimation(String controller, Animation animation, AnimationCategory category, boolean keepActive) {
        //TODO: Skip if same animation
        if (animation == null) {
            return null;
        }
        ActiveAnimationInfo active = getActiveAnimation(controller).orElse(null);
        if (active == null) {
            return putActiveAnimation(controller, new Builder(animation, entity.level.getGameTime(), category).keepActive(keepActive).build());
        }
        boolean replaceAnim = false;
        if (active.category == category && isAnimationDone(active)) {
            //Loops in the same category can only replace sometimes
            replaceAnim = !active.loop || entity.getRandom().nextFloat() < category.chance();
        } else if (active.category != category) {
            //Can only replace if loop or previous animation done
            replaceAnim = active.loop && (!active.keepActive || additionalLogic.getOrDefault(active, () -> false).getAsBoolean()) || isAnimationDone(active);
        }
        if (replaceAnim) {
            int transitionLength = Math.max(category.transitionLength(), active.category.transitionLength());
            return putActiveAnimation(controller, new Builder(animation, entity.level.getGameTime(), category).transitionLength(transitionLength).keepActive(keepActive).build());
        }
        return null;
    }

private static List<Entry> prune(Map<ResourceKey<ISkillSegment>, Entry> entriesByKey, Set<Entry> unresolvable) {
        Deque<Entry> queue = new ArrayDeque<>(unresolvable);
        Set<Entry> removed = new HashSet<>(unresolvable);

        while (!queue.isEmpty()) {
            for (Entry child : queue.poll().children()) {
                if (removed.add(child)) {
                    queue.add(child);
                }
            }
        }

        if (!removed.isEmpty()) {
            LOGGER.error("Ignoring skill segments that have no reachable parent: {}", removed.stream().map(Entry::toString).collect(Collectors.joining(", ")));
            removed.forEach(entry -> entriesByKey.remove(entry.key()));
            for (Entry entry : entriesByKey.values()) {
                entry.parents().removeAll(removed);
                entry.children().removeAll(removed);
            }
        }

        return List.copyOf(entriesByKey.values());
    }

