private static Set<BlockPos> DFSBlockstates(Level world, Collection<BlockPos> start, int maxBlocks, Predicate<BlockState> isMatch) {
        Queue<BlockPos> searchQueue = new ArrayDeque<>(start);
        HashSet<BlockPos> searched = new HashSet<>(start);
        HashSet<BlockPos> found = new HashSet<>();

        while (!searchQueue.isEmpty() && found.size() < maxBlocks) {
            BlockPos current = searchQueue.remove();
            BlockState state = world.getBlockState(current);
            if (isMatch.test(state)) {
                found.add(current);
                for (BlockPos neighborMutable : BlockPos.betweenClosed(current.offset(1, 1, 1), current.offset(-1, -1, -1))) {
                    if (searched.contains(neighborMutable)) {
                        continue;
                    }

                    BlockPos neighbor = neighborMutable.immutable();
                    searched.add(neighbor);
                    searchQueue.add(neighbor);
                }
            }
        }
        return found;
    }

@Override
    public void registerIngredientAliases(@NotNull IIngredientAliasRegistration registration) {

        // for each school, add an alias for the glyph
        List<SpellSchool> schools = List.of(SpellSchools.ELEMENTAL, SpellSchools.ABJURATION, SpellSchools.CONJURATION, SpellSchools.NECROMANCY, SpellSchools.MANIPULATION, SpellSchools.ELEMENTAL_AIR, SpellSchools.ELEMENTAL_EARTH, SpellSchools.ELEMENTAL_FIRE, SpellSchools.ELEMENTAL_WATER);

        for (SpellSchool school : schools) {
            registration.addAliases(VanillaTypes.ITEM_STACK, GlyphRegistry.getGlyphItemMap().values()
                            .stream()
                            .map(Supplier::get)
                            .filter(glyph -> school.isPartOfSchool(glyph.spellPart))
                            .map(Item::getDefaultInstance)
                            .toList(),
                    school.getTextComponent().getString());
        }

        for (DeferredHolder<Item, ? extends Item> entry : ItemsRegistry.ITEMS.getEntries()) {
            if (entry.get() instanceof AliasProvider aliasProvider) {
                Collection<String> aliases = aliasProvider.getAliases().stream().map(AliasProvider.Alias::toTranslationKey).toList();
                registration.addAliases(VanillaTypes.ITEM_STACK, entry.get().getDefaultInstance(), aliases);
            }
        }
    }

@Override
    public boolean stillValid(Player player) {
        if (this.storageController == null)
            return false;

        Level level = this.storageController.getLevel();
        BlockPos controllerPosition = this.storageController.getBlockPos();

        //close container if block is destroyed
        if (level.getBlockEntity(controllerPosition) != this.storageController)
            return false;

        //send stack updates on a slow tick while interacting
        if (!level.isClientSide() && level.getGameTime() % 40 == 0) {
            Networking.sendTo((ServerPlayer) player, this.storageController.getMessageUpdateStacks());
            Networking.sendTo((ServerPlayer) player,
                    new MessageUpdateLinkedMachines(this.storageController.getLinkedMachines()));
        }

        //prevent player from interacting with the container if the controller is not in range
        return player.distanceToSqr(controllerPosition.getX() + 0.5D, controllerPosition.getY() + 0.5D,
                controllerPosition.getZ() + 0.5D) <= 64.0D;
    }

