@Override
    public final TickRateModulation tickingRequest(IGridNode node, int ticksSinceLastCall) {
        // Sometimes between being woken up and actually doing work, the config/redstone mode may have changed
        // put us back to sleep if that was the case
        if (isSleeping()) {
            return TickRateModulation.SLEEP;
        }

        if (!canDoBusWork()) {
            return TickRateModulation.IDLE;
        }

        // Reset a potential redstone pulse trigger
        this.pendingPulse = false;

        var hasDoneWork = this.doBusWork(node.getGrid());

        // We may be back to sleep (i.e. in pulse mode)
        if (isSleeping()) {
            return TickRateModulation.SLEEP;
        } else {
            return hasDoneWork ? TickRateModulation.FASTER : TickRateModulation.SLOWER;
        }
    }

@SubscribeEvent
	public void onToast(ToastAddEvent event)
	{
		if(event.getToast() instanceof AdvancementToast advToast)
		{
			AdvancementHolder advancement = ((AdvancementToastAccess)advToast).getAdvancement();
			ManualInstance manual = ManualHelper.getManual();
			if(manual.contentsByName.isEmpty()) // we need to load the manual if not already done
				manual.reload();
			List<ManualEntry> entries = manual.contentsByName.values().stream()
					.filter(entry -> entry.getRequiredAdvancement().map(loc -> loc.equals(advancement.id())).orElse(false))
					.toList();
			if(!entries.isEmpty())
			{
				// wrap the toast if it has a title, cancel the original
				Optional<AdvancementToast> wrapped = advancement.value().display().map(
						displayInfo -> displayInfo.getTitle().getString().isEmpty()?null: advToast
				);
				event.setCanceled(true);
				// then enqueue the manual toast
				ClientUtils.mc().getToasts().addToast(new ManualUnlockToast(wrapped, entries));
			}
		}
	}

@Nonnull
		@Override
		public FluidStack drain(int maxDrain, FluidAction doDrain)
		{
			if(maxDrain <= 0)
				return FluidStack.EMPTY;

			Level world = pipe.getLevelNonnull();
			List<DirectionalFluidOutput> outputList = new ArrayList<>(getConnectedFluidHandlers(pipe.getBlockPos(), world));
			BlockPos ccFrom = new BlockPos(pipe.getBlockPos().relative(facing));
			outputList.removeIf(output -> ccFrom.equals(output.pos));

			if(outputList.size() < 1)
				return FluidStack.EMPTY;

			CURRENT_TICK_RANDOM.setSeed(HashCommon.mix(world.getGameTime()));
			int chosen = outputList.size()==1?0: CURRENT_TICK_RANDOM.nextInt(outputList.size());
			DirectionalFluidOutput output = outputList.get(chosen);
			FluidStack available = output.output.drain(maxDrain, FluidAction.SIMULATE);
			BlockEntity drainingBE = SafeChunkUtils.getSafeBE(world, this.pipe.getBlockPos().relative(this.facing));
			int limit = getTransferableAmount(available, drainingBE);
			int actualTake = Math.min(limit, maxDrain);
			return output.output.drain(actualTake, doDrain);
		}

@Override
	public void tickServer()
	{
		if(active)
		{
			if(activeTicks%160==0) // sound refreshes after 8 seconds
				getLevelNonnull().playSound(null, getPosition(), this.sound.sound.value(), SoundSource.BLOCKS, 4, 1);
			if(activeTicks%80==0) // entities update after 4 seconds
			{
				AABB aabb = new AABB(getPosition()).inflate(RADIUS);
				List<LivingEntity> nearbyEntities = getLevelNonnull().getEntitiesOfClass(LivingEntity.class, aabb, entity -> entity.isAlive()&&!entity.isRemoved());
				nearbyEntities.forEach(entity -> {
					// hear the bell
					entity.getBrain().setMemory(MemoryModuleType.HEARD_BELL_TIME, getLevelNonnull().getGameTime());
					// make raiders glow
					if(entity.getType().is(EntityTypeTags.RAIDERS))
						entity.addEffect(new MobEffectInstance(MobEffects.GLOWING, 80));
				});
			}
			activeTicks++;
		}
		else if(activeTicks > 0)
			activeTicks = 0;
	}

@Nonnull
	@Override
	public ItemStack insertItem(int slot, @Nonnull ItemStack stack, boolean simulate)
	{
		stack = stack.copy();
		RecipeHolder<BottlingMachineRecipe> recipe = BottlingMachineRecipe.findRecipe(level.get(), state.tank.getFluid(), stack);
		if(recipe==null&&!Utils.isFluidRelatedItemStack(stack))
			return stack;

		MultiblockProcessInWorld<BottlingMachineRecipe> process;
		int inputAmount = 1;
		if(recipe==null)
			process = new BottlingProcess(stack.copy(), stack.copy(), state);
		else
		{
			ItemStack displayStack = recipe.value().getDisplayStack(stack);
			process = new BottlingProcess(recipe, Utils.createNonNullItemStackListFromItemStack(displayStack), state);
			inputAmount = displayStack.getCount();
		}

		if(processor.addProcessToQueue(process, level.get(), simulate))
			stack.shrink(inputAmount);
		return stack;
	}

@Override
	protected ItemStack insert(ItemStack stack, boolean simulate)
	{
		stack = stack.copy();
		RecipeHolder<R> recipe = getRecipeOnInsert.apply(level.get(), stack);
		if(recipe==null)
			return stack;
		ItemStack displayStack;
		if(!doProcessStacking)
		{
			// if process stacking is not allowed, we need to work with exact input quantities
			displayStack = recipe.value().getDisplayStack(stack);
			displayStack = stack.copyWithCount(displayStack.getCount());
		}
		else
			displayStack = stack.copy();
		if(processor.addProcessToQueue(new MultiblockProcessInWorld<>(
				recipe,
				TRANSFORMATION_POINT,
				Utils.createNonNullItemStackListFromItemStack(displayStack)
		), level.get(), simulate, doProcessStacking))
			stack.shrink(displayStack.getCount());
		return stack;
	}

@Override
	public void process(IPayloadContext context)
	{
		if(context.flow().getReceptionSide()==LogicalSide.SERVER)
			context.enqueueWork(() -> {
				Level world = context.player().level();
				if(world.isAreaLoaded(pos, 1))
				{
					BlockEntity tile = world.getBlockEntity(pos);
					if(tile instanceof IEBaseBlockEntity)
						((IEBaseBlockEntity)tile).receiveMessageFromClient(nbt);
				}
			});
		else
			context.enqueueWork(() -> {
				Level world = ImmersiveEngineering.proxy.getClientWorld();
				if(world!=null) // This can happen if the task is scheduled right before leaving the world
				{
					BlockEntity tile = world.getBlockEntity(pos);
					if(tile instanceof IEBaseBlockEntity)
						((IEBaseBlockEntity)tile).receiveMessageFromServer(nbt);
				}
			});
	}

