					global.getLocalNet(this.from).getConnections(this.from).stream().filter(conn ->
							// filter to connections matching both points
							(conn.getEndA().position().equals(this.from)&&conn.getEndB().position().equals(this.to))
									||(conn.getEndB().position().equals(this.from)&&conn.getEndA().position().equals(this.to))
					).findFirst().ifPresent(
							// add to map
							c -> ModelPowerpack.PLAYER_ATTACHED_TO.put(this.player, c)
					);
				}
			}
		});
	}

public static void tick() {
		ticks++;

		int before = hangingPlayers.size();

		ObjectIterator<Object2IntMap.Entry<UUID>> iterator = hangingPlayers.object2IntEntrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, Integer> entry = iterator.next();
			int newTTL = entry.getValue() - 1;
			if (newTTL <= 0) {
				iterator.remove();
			} else {
				entry.setValue(newTTL);
			}
		}

		int after = hangingPlayers.size();

		if (ticks % 10 != 0 && before == after)
			return;

		sync();

	}

@Override public InteractionResult useOn(UseOnContext context) {
        Level world = context.getLevel();
        BlockPos pos = context.getClickedPos(), pos1;
        if(world.getBlockState(pos).getCollisionShape(world, pos).isEmpty()) pos1 = pos;
        else pos1 = pos.relative(context.getClickedFace());
        Player player = context.getPlayer();
        if(dimensionID == null) dimensionID = MORTUM;
        if(world.dimension() != dimensionID) {
            player.displayClientMessage(LocalizeUtils.clientMessage(AQUA, langKey), true);
            return InteractionResult.FAIL;
        } else if(world.getDifficulty() == PEACEFUL) {
            player.displayClientMessage(LocalizeUtils.clientMessage(AQUA, "boss.peaceful"), true);
            return InteractionResult.FAIL;
        } else if(ent != null && !world.getBlockStates(ent.get().getSpawnAABB(pos.getX() + .5, pos.getY() + 2.14, pos.getZ() + .5).inflate(1)).allMatch(BlockBehaviour.BlockStateBase::isAir)) {
            player.displayClientMessage(LocalizeUtils.clientMessage(AQUA, "boss.space"), true);
            return InteractionResult.FAIL;
        } else {
            ItemStack stack = player.getItemInHand(context.getHand());
            if(!world.isClientSide && ent != null) ent.get().spawn((ServerLevel) world, stack, player, pos1, MOB_SUMMONED, true, false);
            stack.consume(1, player);
            player.getCooldowns().addCooldown(this, 40);
            return InteractionResult.SUCCESS;
        }
    }

@Override
    public boolean mousePressed(MouseButton button) {
        if (button == MouseButton.BACK) {
            closeGui(true);
            return true;
        }

        var now = System.currentTimeMillis();
        if (lastClickTime != 0L && (now - lastClickTime) <= 300L && getDoubleClickTarget().mouseDoubleClicked(button)) {
            lastClickTime = 0L;
            return true;
        }
        lastClickTime = now;

        if (modalPanels.isEmpty()) {
            return super.mousePressed(button);
        } else if (modalPanels.peekFirst().isMouseOver()) {
            return modalPanels.peekFirst().mousePressed(button);
        } else {
            // clicking outside any panel dismisses the top one
            popModalPanel();
            return false;
        }
    }

public void updateEffects() {
        if (!this.depthEnabledParticles.isEmpty()) {
            updateQueue(this.depthEnabledParticles);
        }
        if (!this.depthDisabledParticles.isEmpty()) {
            updateQueue(this.depthDisabledParticles);
        }

        if (!newParticleQueue.isEmpty()) {
            for (GTParticle particle : newParticleQueue) {
                var queue = particle.shouldDisableDepth() ? this.depthDisabledParticles : this.depthEnabledParticles;

                Queue<GTParticle> particles = queue.computeIfAbsent(particle.getRenderSetup(),
                        setup -> new ArrayDeque<>());

                if (particles.size() > 6000) {
                    particles.remove().setExpired();
                }
                particles.add(particle);
            }

            newParticleQueue.clear();
        }
    }

private void updatePumpQueue(@Nullable FluidType fluidType) {
        if (getLevel() == null) return;

        if (pumpQueue != null && !pumpQueue.queue().isEmpty()) {
            return;
        }

        BlockPos headPos = getBlockPos().below(pumpHeadY);

        BlockPos downPos = headPos.below(1);
        var downBlock = getLevel().getBlockState(downPos);

        if (!(downBlock.getBlock() instanceof LiquidBlock)) {
            pumpQueue = null;
            return;
        }

        if (fluidType != null && downBlock.getFluidState().getFluidType() != fluidType) {
            pumpQueue = null;
            return;
        }

        pumpQueue = buildPumpQueue(getLevel(), headPos, downBlock.getFluidState().getFluidType(), queueSize(), true);
    }

public void update() {
        if (autoOutput.getFluidOutputDirection() != null) {
            cache.exportToNearby(autoOutput.getFluidOutputDirection());
        }

        // do not do anything without enough energy supplied
        if (energyContainer.getEnergyStored() < GTValues.V[getTier()] * 2) {
            return;
        }
        // Try to put 5 times as many in the queue as there are pumps in the cycle
        // In practice only EV tier has more than 1 pump per cycle
        // The queue can contain at most the y-levels at the pump head or just the y-level below, so for many oil veins
        // It will not be the ideal size
        boolean advanced = false;
        if (getOffsetTimer() % (getPumpingCycleLength() * 2L) == 0) {
            advanced = canAdvancePumpHead();
        }
        if (!advanced && getOffsetTimer() % getPumpingCycleLength() == 0) {
            pumpCycle();
        }
        if (getOffsetTimer() % (20 * 60) == 0) {
            forbiddenBlocks.clear();
        }
    }

private float clipTime(@Nullable AnimationClip clip) {
        float editor = pinnedClock != null ? pinnedClock : PhotonParticleManager.editorAnimationSeconds();
        float seconds;
        if (editor >= 0f) {
            seconds = editor;
        } else {
            var level = Minecraft.getInstance().level;
            seconds = level == null ? 0f
                    : (level.getGameTime() + Minecraft.getInstance().getTimer()
                    .getGameTimeDeltaPartialTick(false)) / 20f;
        }
        seconds *= speed;
        // an infinite speed makes the modulo NaN, which never equals the last pose's time and so
        // re-deforms the model into nothing, every frame, forever
        if (clip == null || !Float.isFinite(seconds)) return 0f;
        float duration = clip.duration();
        if (duration <= 0f) return 0f;
        if (!loop) {
            return Math.max(0f, Math.min(seconds, duration));
        }
        // floorMod on floats: a negative speed has to wrap forward, not mirror
        float wrapped = seconds % duration;
        return wrapped < 0f ? wrapped + duration : wrapped;
    }

private void prepareIrisAccumulator() {
        assert irisTarget != null;
        int depthTexture = irisTarget.depthTexture();
        if (depthTexture != 0 && (attachedDepthTexture != depthTexture
                || attachedDepthVersion != irisTarget.depthBufferVersion()
                || attachedDepthFramebuffer != DRAW_TARGET.frameBufferId)) {
            DRAW_TARGET.attachDepthBuffer(depthTexture);
            attachedDepthTexture = depthTexture;
            attachedDepthVersion = irisTarget.depthBufferVersion();
            attachedDepthFramebuffer = DRAW_TARGET.frameBufferId;
        }
        DRAW_TARGET.bindWrite(false);
        RenderSystem.viewport(entryViewport.position.x, entryViewport.position.y,
                entryViewport.size.width, entryViewport.size.height);
        // AFTER_PACK keeps one layer for the whole frame (both queues accumulate into it before it
        // is composited), so it must be cleared once per frame, not once per build.
        boolean deferred = irisTarget.compositeMode() == IrisCompositeMode.AFTER_PACK;
        if (!deferred || !lateLayerStarted) {
            GlStateManager._colorMask(true, true, true, true);
            GlStateManager._clearColor(0f, 0f, 0f, 0f);
            GlStateManager._clear(GL11.GL_COLOR_BUFFER_BIT, Minecraft.ON_OSX);
        }
        if (deferred) lateLayerStarted = true;
    }

