@Override
    protected Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        if (!ConfigSettings.ENTITY_CLIMATES.get().containsKey(entity.getType()))
        {   this.expires(0);
            return temp -> temp;
        }
        EntityClimateData climateData = ConfigHelper.getFirstOrNull(ConfigSettings.ENTITY_CLIMATES, entity.getType(), data -> data.test(entity));
        if (climateData != null && climateData.test(entity))
        switch (trait)
        {
            case WORLD ->
            {   double worldTemp = WorldHelper.getRoughTemperatureAt(entity.level(), entity.blockPosition(), 1);
                return temp -> temp + worldTemp;
            }
            case BURNING_POINT ->
            {   return temp -> temp + climateData.getMaxOffset();
            }
            case FREEZING_POINT ->
            {   return temp -> temp + climateData.getMinOffset();
            }
        }
        return temp -> temp;
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            for (var stack : Arrays.asList(player.getMainHandItem(), player.getOffhandItem())) {
                if (!(stack.getItem() instanceof CutGlassBootItem item))
                    continue;

                var entries = item.getFluidEntries(player, stack);

                if (entries.isEmpty())
                    continue;

                item.setSelectedFluidIndex(player, stack, Math.floorMod(item.getSelectedFluidIndex(player, stack) + this.getDelta(), entries.size()));

                var fluid = BuiltInRegistries.FLUID.get(ResourceLocation.parse(item.getSelectedFluid(player, stack).toString()));

                if (fluid == Fluids.EMPTY)
                    continue;

                player.displayClientMessage(Component.literal(fluid.getFluidType().getDescription().getString()), true);
            }
        });
    }

@SuppressWarnings("deprecation")
	private void growCropsNearby(ServerLevel level, BlockPos pos, BlockState state) {
		BlockPos.betweenClosed(pos.offset(-tileRange(), -tileRange(), -tileRange()), pos.offset(tileRange(), tileRange(), tileRange())).forEach(cropPos -> {
			if (!level.hasChunkAt(cropPos)) {
				return;
			}

			BlockPos posDiff = cropPos.subtract(pos);
			int distance = Math.max(Math.abs(posDiff.getX()), Math.max(Math.abs(posDiff.getY()), Math.abs(posDiff.getZ())));
			float chanceToGrow = distance <= fullPotencyRange() ? 1F : (1F - (float) (distance - fullPotencyRange()) / (tileRange() - fullPotencyRange() + 1));

			if (level.random.nextFloat() > chanceToGrow) {
				return;
			}

			BlockState cropState = level.getBlockState(cropPos);
			Block cropBlock = cropState.getBlock();

			if (isAllowedCropBlock(cropBlock) && isGrowable(cropBlock)) {
				tickCropBlock(level, cropPos, cropState, distance);
			}
		});
		level.scheduleTick(pos, state.getBlock(), secondsBetweenGrowthTicks() * 20 / getNumberOfPotencySteps());
	}

public static void render(PoseStack poseStack, float partialTick, Vec3 cameraPos) {
		Minecraft mc = Minecraft.getInstance();
		ClientLevel level = mc.level;
		if (level == null || CAPTURE_EFFECTS.isEmpty()) {
			return;
		}

		EntityRenderDispatcher entityRenderDispatcher = mc.getEntityRenderDispatcher();
		MultiBufferSource.BufferSource buffer = mc.renderBuffers().bufferSource();
		Iterator<CaptureEffect> iterator = CAPTURE_EFFECTS.iterator();
		while (iterator.hasNext()) {
			CaptureEffect effect = iterator.next();
			float progress = Mth.clamp((level.getGameTime() - effect.startTime() + partialTick) / ANIMATION_DURATION_TICKS, 0F, 1F);
			if (progress >= 1F) {
				finishEffect(level, effect);
				iterator.remove();
				continue;
			}

			if (effect.shouldRender()) {
				renderEffect(effect, poseStack, partialTick, cameraPos, entityRenderDispatcher, buffer, progress);
			}
		}
	}

