public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.003D, 0.0D));
            }

            if (this.tickCount % 1000 == 0) {
                if (this.wantsToBreed() && !this.isMale()) {
                    this.breed();
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }
        if (this.tickCount % 120 < 11) {
            if (this.tickCount % 120 == 1) {
                whisker_y = 0.8F - this.random.nextFloat() * 1.6F;
                whisker_z = 0.4F - this.random.nextFloat() * 0.8F;
            }
            this.whisker_offset = new Pair<>(Mth.lerp(0.1F, whisker_offset.getA(), whisker_y), Mth.lerp(0.1F, whisker_offset.getB(), whisker_z));
        }
        super.aiStep();
    }

private void tickOrbiting() {
        // But we might want it to follow the owner if not fired yet.
        if (this.dracula == null && this.draculaUUID != null && this.level() instanceof ServerLevel serverLevel) {
            Entity entity = serverLevel.getEntity(this.draculaUUID);
            if (entity instanceof Dracula d) {
                this.dracula = d;
            }
        }

        // orbit Dracula
        if (this.dracula != null && this.dracula.isAlive()) {
            double angle = (this.level().getGameTime() * 0.1) + (this.indexOffset * (Math.PI * 2 / this.maxCount));
            double x = this.dracula.getX() + Math.cos(angle) * 1.5;
            double z = this.dracula.getZ() + Math.sin(angle) * 1.5;
            double y = this.dracula.getY() + 1.5 + Math.sin(this.level().getGameTime() * 0.05 + this.indexOffset) * 0.5;

            this.setPos(x, y, z);
            this.setYRot((float) (angle * (180 / Math.PI)));
            this.yRotO = this.getYRot();
            this.xRotO = this.getXRot();
        } else if (!this.level().isClientSide()) {
            this.discard();
        }
    }

@Override
    protected void applyImplicitComponents(DataComponentInput componentInput) {
        super.applyImplicitComponents(componentInput);

        if (this instanceof ISerializableTanks st) {
            st.getSerializableTanks().forEach((comp, tank) ->
                    tank.loadFromContent(componentInput.getOrDefault(comp, SimpleFluidContent.EMPTY)));
        }
        if (this instanceof IRedstoneControl<?> rc) {
            RedstoneController.Saved data = componentInput.getOrDefault(ModDataComponents.SAVED_REDSTONE_CONTROLLER, RedstoneController.Saved.DEFAULT);
            rc.getRedstoneController().restore(data);
        }
        if (this instanceof ISideConfigurable sc) {
            Map<String, SideConfigurator.Saved> data = componentInput.getOrDefault(ModDataComponents.SAVED_SIDE_CONFIG, Map.of());
            SideConfigurator.loadSavedData(sc, data);
        }

        componentInput.getOrDefault(ModDataComponents.ITEM_UPGRADES, SavedUpgrades.EMPTY).fillItemHandler(getUpgradeHandler());

        IAirHandlerMachine handler = getLevel().getCapability(PNCCapabilities.AIR_HANDLER_MACHINE, getBlockPos(), getBlockState(), this, null);
        if (handler != null) {
            handler.addPendingAir(componentInput.getOrDefault(ModDataComponents.AIR, 0));
        }
    }

private void findLake(Fluid fluid) {
        Set<BlockPos> result = new HashSet<>();
        Deque<BlockPos> pendingPositions = new ArrayDeque<>();
        BlockPos thisPos = getBlockPos().relative(Direction.DOWN, currentDepth + 1);
        pendingPositions.add(thisPos);
        result.add(thisPos);
        while (!pendingPositions.isEmpty()) {
            BlockPos checkingPos = pendingPositions.pop();
            for (Direction d : DirectionUtil.VALUES) {
                if (d == Direction.DOWN) continue;
                BlockPos newPos = checkingPos.relative(d);
                if (PneumaticCraftUtils.distBetweenSq(newPos, thisPos) <= MAX_PUMP_RANGE_SQUARED
                        && FluidUtils.isSourceFluidBlock(nonNullLevel(), newPos, fluid)
                        && !result.contains(newPos)) {
                    pendingPositions.add(newPos);
                    result.add(newPos);
                }
            }
        }

        pumpingLake = result.stream()
                .sorted((o1, o2) -> (int)o2.distSqr(getBlockPos()) - (int)o1.distSqr(getBlockPos()))
                .collect(Collectors.toCollection(() -> new ArrayDeque<>(result.size())));
    }

