public static void onClientTick(@SuppressWarnings("unused") ClientTickEvent.Post event) {
        if (tasks.isEmpty()) {
            return;
        }

        Level level = Minecraft.getInstance().level;
        if (level == null || level.dimension() != lastDimension) {
            lastDimension = level != null ? level.dimension() : null;
            tasks.clear(); //Clear remaining tasks from the previous level

            if (level == null) {
                return;
            }
        }

        Iterator<ClientTask> it = tasks.iterator();
        while (it.hasNext()) {
            ClientTask task = it.next();
            if (level.getGameTime() >= task.time) {
                task.task.run();
                it.remove();
            }
        }
    }

public static boolean isPlayerNearby(BlockPos pos, ServerLevel level, int range) {
        String key = level.dimension().location().toString();
        if (!levelPlayerCache.containsKey(key))
            levelPlayerCache.put(key, CacheBuilder.newBuilder().maximumSize(1000).build());
        Cache<Long, CacheResult> positionCache = levelPlayerCache.get(key);
        long posLong = pos.asLong();
        CacheResult playerResult = positionCache.getIfPresent(posLong);
        long gameTime = level.getGameTime();

        if (playerResult != null && playerResult.nextCheck > gameTime) {
            return playerResult.isPlayerNearby();
        }

        long nextCheck = gameTime + 500 + level.random.nextInt(20);

        for (Player player : level.players()) {
            if (BlockUtil.distanceFrom(level, player.blockPosition(), pos) < range) {
                positionCache.put(posLong, new CacheResult(true, nextCheck));
                return true;
            }
        }
        positionCache.put(posLong, new CacheResult(false, nextCheck));
        return false;
    }

@Override
    public void tick() {
        super.tick();
        if (level instanceof ServerLevel && level.getGameTime() % 20 == 0 && this.canAcceptSource()) {
            BlockPos potionPos = findNearbyPotion(level, worldPosition);
            if (potionPos != null && level.getBlockEntity(potionPos) instanceof PotionJarTile tile) {
                int source = 75;
                Set<MobEffect> effectTypes = new HashSet<>();
                for (MobEffectInstance e : tile.getData().getAllEffects()) {
                    source += (e.getDuration() / 50);
                    source += e.getAmplifier() * 250;
                    source += 150;
                    effectTypes.add(e.getEffect().value());
                }
                if (effectTypes.size() > 1) {
                    source *= Math.pow(2.1, effectTypes.size());
                }
                if (source > 0 && canAcceptSource(source) || this.getSource() <= 0) {
                    addSource(source);
                    tile.remove(100);
                }
            }
        }
    }

