        if (!((EntityAmphithere) this.mob).canMove()) {
            list = IAFMath.emptyItemEntityList;
            return false;
        }

        // If the target entity already is what we want skip AABB
        if (targetEntitySelector.test(this.targetEntity)) {
            return true;
        }

        if (this.mob.level.getGameTime() % 4 == 0) // only update the list every 4 ticks
            list = this.mob.level.getEntitiesOfClass(ItemEntity.class, this.getTargetableArea(this.getFollowDistance()), this.targetEntitySelector);

        if (list.isEmpty())
            return false;

        list.sort(this.theNearestAttackableTargetSorter);
        this.targetEntity = list.get(0);
        return true;
    }

public void onUnloadLevel(final LevelEvent.Unload ev) {
        var level = ev.getLevel();

        if (level.isClientSide()) {
            return; // for no there is no reason to care about this on the client...
        }

        var toDestroy = new ArrayList<GridNode>();

        this.grids.updateNetworks();
        for (Grid g : this.grids.getNetworks()) {
            for (var n : g.getNodes()) {
                if (n.getLevel() == level) {
                    toDestroy.add((GridNode) n);
                }
            }
        }

        for (var n : toDestroy) {
            n.destroy();
        }

        this.blockEntities.removeLevel(level);
        this.callQueue.remove(level);
    }

