		long now = System.currentTimeMillis();

		if (super.mouseScrolled(mouseX, mouseY, xDelta, yDelta)) {
			lastScrollTime = now;
			return true;
		}

		if (now - lastScrollTime > 500L) {
			if (yDelta < 0 && getCurrentPage() < pageIndices.size() - 1) {
				setCurrentPage(getCurrentPage() + 1);
				refreshWidgets();
				lastScrollTime = now;
				return true;
			} else if (yDelta > 0 && getCurrentPage() > 0) {
				setCurrentPage(getCurrentPage() - 1);
				refreshWidgets();
				lastScrollTime = now;
				return true;
			}
		}

		return false;
	}

private void mineAndInsertItems(NonNullList<ItemStack> blockDrops, ServerLevel world) {
        // If the block's drops can fit in the inventory, move the previously mined position to the block
        // replace the ore block with cobblestone instead of breaking it to prevent mob spawning
        // remove the ore block's position from the mining queue
        var handler = getCachedItemHandler();
        if (GTTransferUtils.addItemsToItemHandler(handler, true, blockDrops)) {
            GTTransferUtils.addItemsToItemHandler(handler, false, blockDrops);
            var pos = blocksToMine.getFirst();
            world.setBlock(pos, findMiningReplacementBlock(world, pos), 3);
            mineX = pos.getX();
            mineZ = pos.getZ();
            mineY = pos.getY();
            syncDataHolder.markClientSyncFieldDirty("mineX");
            syncDataHolder.markClientSyncFieldDirty("mineY");
            syncDataHolder.markClientSyncFieldDirty("mineZ");
            blocksToMine.removeFirst();
            onMineOperation();

            // if the inventory was previously considered full, mark it as not since an item was able to fit
            isInventoryFull = false;
        } else {
            // the ore block was not able to fit, so the inventory is considered full
            isInventoryFull = true;
        }
    }

private static void freezeNearbyWater(LivingEntity entity, Level level, BlockPos pos, int amplifier) {
    if (!entity.onGround()) { return; }
    BlockState frostedIce = Blocks.FROSTED_ICE.defaultBlockState();
    float radius = Math.min(16, 2 + amplifier);
    BlockPos.MutableBlockPos mutablePos = new BlockPos.MutableBlockPos();
    for (BlockPos blockPos : BlockPos.betweenClosed(
        pos.offset(-(int) radius, -1, -(int) radius),
        pos.offset((int) radius, -1, (int) radius)
    )) {
      if (blockPos.closerToCenterThan(entity.position(), radius)) {
        mutablePos.set(blockPos.getX(), blockPos.getY() + 1, blockPos.getZ());
        BlockState above = level.getBlockState(mutablePos);
        if (above.isAir()) {
          BlockState below = level.getBlockState(blockPos);
          boolean isWater = below.is(Blocks.WATER) && below.getValue(LiquidBlock.LEVEL) == 0;
          if (isWater && frostedIce.canSurvive(level, blockPos)
              && level.isUnobstructed(frostedIce, blockPos, CollisionContext.empty())
              && level.mayInteract(entity instanceof Player p ? p : null, blockPos)) {
            level.setBlockAndUpdate(blockPos, frostedIce);
            level.scheduleTick(blockPos, Blocks.FROSTED_ICE, Mth.nextInt(entity.getRandom(), 60, 120));
          }
        }
      }
    }
  }

@Override
    public void onPlayerTickActive(EntityPlayer player, ItemStack item) {
        ItemStack helmet = player.getItemStackFromSlot(EntityEquipmentSlot.HEAD);
        if (helmet != null && helmet.equals(item)) {
            World world = player.worldObj;
            int xCoord = MathHelper.floor_double(player.posX);
            int zCoord = MathHelper.floor_double(player.posZ);
            boolean isRaining, canRain = true;
            if (world.getTotalWorldTime() % 20 == 0) {
                canRain = world.getBiome(player.getPosition()).canRain();
            }
            isRaining = canRain && (world.isRaining() || world.isThundering());
            boolean sunVisible = world.isDaytime() && !isRaining && world.canBlockSeeSky(player.getPosition().add(0,1,0));
            boolean moonVisible = !world.isDaytime() && !isRaining && world.canBlockSeeSky(player.getPosition().add(0,1,0));
            if (!world.isRemote && !world.provider.getHasNoSky() && (world.getTotalWorldTime() % 80) == 0) {
                if (sunVisible) {
                    ElectricItemUtils.givePlayerEnergy(player, ModuleManager.computeModularProperty(item, A_SOLAR_ENERGY_GENERATION_DAY));
                    MuseHeatUtils.heatPlayer(player, ModuleManager.computeModularProperty(item, SOLAR_HEAT_GENERATION_DAY) / 2);
                } else if (moonVisible) {
                    ElectricItemUtils.givePlayerEnergy(player, ModuleManager.computeModularProperty(item, A_SOLAR_ENERGY_GENERATION_NIGHT));
                    MuseHeatUtils.heatPlayer(player, ModuleManager.computeModularProperty(item, SOLAR_HEAT_GENERATION_NIGHT) / 2);
                }
            }
        }
    }

public void tick(Level level, BlockState state, BlockPos pos)
    {
        if (level.getGameTime() % 20 == 0 && !level.isClientSide)
        {
            // Handle signal output / neighbor updates
            double temperature = WorldHelper.getTemperatureAt(level, pos);
            int newSignal = (int) CSMath.blend(0, 15, temperature, ConfigSettings.MIN_TEMP.get(), ConfigSettings.MAX_TEMP.get());

            if (newSignal != signal)
            {
                signal = newSignal;
                ThermolithBlock.updateFacingNeighbors(level, state, pos);
            }

            // Handle turning on/off
            if (signal == 0)
            {   if (state.getValue(ThermolithBlock.POWERED))
                {   level.setBlockAndUpdate(pos, state.setValue(ThermolithBlock.POWERED, false));
                }
            }
            else if (!state.getValue(ThermolithBlock.POWERED))
            {   level.setBlockAndUpdate(pos, state.setValue(ThermolithBlock.POWERED, true));
            }
        }
    }

