public void tick(){
        if (this.level != null && !this.level.isClientSide){
            if (this.checkCage()){
                this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(SculkGrowerBlock.LIT, true), 3);
            } else {
                this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(SculkGrowerBlock.LIT, false), 3);
            }
            this.scanTotalPlants();
            if (this.level.getGameTime() % 5 == 0){
                this.findPlants();
            }
            if (this.growCharges <= 0) {
                if (!this.growablePlantPos.isEmpty() && this.checkCage()) {
                    if (this.takeSouls()) {
                        this.growCharges = MainConfig.SculkGrowerCharge.get();
                    }
                }
            } else {
                this.growPlants();
            }
            if (this.totalPlantPos.isEmpty() || this.decayTimer <= 0){
                this.decayCharges();
            }
        }
    }

public static void consume(SRepositionPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Level level = Goety.PROXY.getLevel();
            if (level instanceof ClientLevel clientWorld) {
                Entity entity = clientWorld.getEntity(packet.mob);
                if (entity != null) {
                    entity.setPos(packet.x, packet.y, packet.z);
                    entity.xo = packet.x;
                    entity.yo = packet.y;
                    entity.zo = packet.z;
                    entity.xOld = packet.x;
                    entity.yOld = packet.y;
                    entity.zOld = packet.z;
                    entity.setDeltaMovement(Vec3.ZERO);
                    if (entity instanceof LocalPlayer) {
                        return;
                    }
                    if (entity instanceof LivingEntity living) {
                        living.lerpTo(packet.x, packet.y, packet.z, entity.getYRot(), entity.getXRot(), 0, false);
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            int i = this.random.nextInt(3000);
            if (i == 13 && !this.isInWater() && this.getTarget() == null && this.isNotMoving() && this.canMove() && this.getAnimation() == NO_ANIMATION) {
                this.setSitting(true);
            }
            if (i == 14 && this.isSitting()) {
                this.setSitting(false);
            }
            this.setAngry(this.getTarget() != null);
        }
        else {
            if (this.getAnimation() == ATTACK_THREATEN) {
                this.setSprinting(this.getAnimationTick() % 18 < 6);
            }
        }
        super.aiStep();
    }

