      dealtDamage = true;
    }
    super.tick();

    // magnet
    if (magnet > 0) {
      MagneticEffect.applyVelocity(level(), position(), magnet - 1, ItemEntity.class, 3, 0.05f, 32);
    }

    // check if any tasks are ready
    if (!tasks.isEmpty() && !tridentItem.isEmpty()) {
      ScheduledProjectileTaskModifierHook.checkSchedule(getTool(), tridentItem, this, null, tasks);
    }
  }

public static Set<BlockPos> getTree(BlockGetter level, BlockPos bottom, Predicate<BlockPos> inRange) {
        ArrayDeque<BlockPos> queue = new ArrayDeque<>();
        HashSet<BlockPos> tree = new HashSet<>();
        HashSet<BlockPos> seen = new HashSet<>();

        queue.add(bottom);

        while (!queue.isEmpty()) {
            BlockPos pos = queue.removeFirst();
            BlockState state = level.getBlockState(pos);

            if (isTree(state) && inRange.test(pos)) {
                tree.add(pos);
                BlockPos.betweenClosedStream(pos.offset(-1, -1, -1), pos.offset(1, 1, 1)).forEach(next -> {
                    if (seen.contains(next))
                        return;

                    var immutable = next.immutable();
                    seen.add(immutable);
                    queue.add(immutable);
                });
            }
        }
        return tree;
    }

private int getBackgroundColor() {
        if (menu.isCompleted(taskInstance)) {
            return ARGB.colorFromFloat(1, 0.4f, 0.4f, 0.4f);
        }

        boolean isUnique = taskInstance.isUnique(menu.getRegistry());
        @SuppressWarnings("DataFlowIssue")
        boolean remainsTime = taskInstance.getTaskTimeStamp() - Minecraft.getInstance().level.getGameTime() > 0;

        if (menu.canCompleteTask(taskInstance)) {
            return isUnique
                    ? ARGB.colorFromFloat(1, 1f, 0.855859375f, 0)  // Gold for unique
                    : ARGB.colorFromFloat(1, 0, 0.9f, 0);          // Green for normal
        } else if (menu.isTaskNotAccepted(taskInstance)) {
            return isUnique
                    ? ARGB.colorFromFloat(1, 0.64f, 0.57f, 0.5f)   // Tan for unique not accepted
                    : 0xFFFFFFFF;                                   // White for normal not accepted
        } else if (!isUnique && !remainsTime) {
            return ARGB.colorFromFloat(1, 1f, 85 / 255f, 85 / 255f); // Red for expired
        } else {
            return isUnique
                    ? ARGB.colorFromFloat(1, 1f, 0.9f, 0.6f)       // Light gold for unique in progress
                    : 0xFFFFFFFF;                                   // White for normal in progress
        }
    }

public static void serverTick(Level level, BlockPos pos, BlockState state, SunscreenBeaconBlockEntity blockEntity) {
        if (level.getGameTime() % 80L == 0L) {
            //Position check is probably not necessary, but not sure
            if (blockEntity.oldPos == null || blockEntity.selector == null || !blockEntity.oldPos.equals(pos)) {
                blockEntity.oldPos = pos;
                final BlockPos center = new BlockPos(pos.getX(), 0, pos.getZ());
                final int distSq = ModConfig.server().sunscreenBeaconRadius.get() * ModConfig.server().sunscreenBeaconRadius.get();
                blockEntity.selector = input -> {
                    if (input == null) return false;
                    BlockPos player = new BlockPos((int) input.getX(), 0, (int) input.getZ());
                    return player.distSqr(center) < distSq;
                };
            }

            List<? extends Player> list = level.players();

            for (Player player : list) {
                if (player.isAlive() && blockEntity.selector.test(player)) {
                    if (VampirePlayer.get(player).getLevel() > 0) {
                        player.addEffect(new MobEffectInstance(ModEffects.SUNSCREEN, 160, 5, true, false));
                    }
                }
            }
        }
    }

