public static void waterWalkingSplashEffect(LivingEntity livingEntity) {
		Long lastTickWaterWalking = livingEntity.getData(TFDataAttachments.LAST_TICK_WATER_WALKING);
		Level level = livingEntity.level();
		Vec3 livingEntityVelocity = livingEntity.getKnownMovement();
		if (lastTickWaterWalking + 1 == level.getGameTime() || livingEntityVelocity.horizontalDistance() < 0.01)
			return;

		livingEntity.setData(TFDataAttachments.LAST_TICK_WATER_WALKING, livingEntity.level().getGameTime());

		ParticlePacket particlePacket = new ParticlePacket();  // we have to create it on client to avoid networking delays
		for (int particleNumber = 0; particleNumber < livingEntity.dimensions.width(); particleNumber++) {
			double dx = (level.getRandom().nextDouble() * 2.0 - 1.0) * (double) livingEntity.dimensions.width() / 2D;
			double dz = (level.getRandom().nextDouble() * 2.0 - 1.0) * (double) livingEntity.dimensions.width() / 2D;
			Vec3 particlePos = new Vec3(livingEntity.getX() + dx, livingEntity.getY() + WATER_WALKING_MAX_SUBMERGED_HEIGHT, livingEntity.getZ() + dz);
			Vec3 particleVelocity = new Vec3(-livingEntityVelocity.x, 0.5, -livingEntityVelocity.z);
			if (level.isClientSide()) {
				level.addParticle(ParticleTypes.SPLASH, particlePos.x(), particlePos.y(), particlePos.z(), particleVelocity.x(), particleVelocity.y(), particleVelocity.z());
			} else {
				particlePacket.queueParticle(ParticleTypes.SPLASH, false, false, particlePos, particleVelocity);
			}
		}

		if (!level.isClientSide())
			PacketDistributor.sendToPlayersTrackingEntity(livingEntity, particlePacket);
	}

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Vec3d position = spell.getTarget(world);
		BlockPos pos = spell.getTargetPos();

		if (position == null || pos == null) return true;

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell);

		double area = spellRing.getAttributeValue(world, AttributeRegistry.AREA, spell);

		if (world.getTotalWorldTime() % 2 == 0)
			world.playSound(null, pos, ModSounds.FIZZING_LOOP, CommonProxy.SoundCategory_WizardryGeneral, RandUtil.nextFloat(0.6f, 1f), RandUtil.nextFloat(0.1f, 4f));
		for (Entity entity : world.getEntitiesWithinAABBExcludingEntity(null, new AxisAlignedBB(new BlockPos(position)).grow(area, area, area))) {
			if (entity instanceof EntityLivingBase) {
				EntityLivingBase living = (EntityLivingBase) entity;
				if (potency >= 3) {
					living.addPotionEffect(new PotionEffect(MobEffects.NAUSEA, 100));
				}
				living.addPotionEffect(new PotionEffect(MobEffects.POISON, 60, (int) (potency / 3)));
			}
		}

		return true;
	}

public static void dimensionTravel(Entity entity, ResourceKey<Level> dimension) {
        if (entity instanceof Player player) {
            if (!player.level().isClientSide()) {
                var aetherPlayer = player.getData(AetherDataAttachments.AETHER_PLAYER);
                if (!AetherConfig.SERVER.spawn_in_aether.get() || !aetherPlayer.canSpawnInAether()) {
                    if (entity.level().getBiome(entity.blockPosition()).is(AetherTags.Biomes.DISPLAY_TRAVEL_TEXT)) {
                        if (entity.level().dimension() == LevelUtil.destinationDimension() && dimension == LevelUtil.returnDimension()) { // We display the Descending GUI text to the player if they're about to return to the Overworld.
                            displayAetherTravel = true;
                            playerLeavingAether = true;
                            PacketDistributor.sendToAllPlayers(new AetherTravelPacket(true));
                            PacketDistributor.sendToAllPlayers(new LeavingAetherPacket(true));
                        } else if (entity.level().dimension() == LevelUtil.returnDimension() && dimension == LevelUtil.destinationDimension()) { // We display the Ascending GUI text to the player if they're about to enter the Aether.
                            displayAetherTravel = true;
                            playerLeavingAether = false;
                            PacketDistributor.sendToAllPlayers(new AetherTravelPacket(true));
                            PacketDistributor.sendToAllPlayers(new LeavingAetherPacket(false));
                        } else { // Don't display any text if not travelling between the Aether and Overworld or vice-versa.
                            displayAetherTravel = false;
                            PacketDistributor.sendToAllPlayers(new AetherTravelPacket(false));
                        }
                    }
                }
            }
        }
    }

@Override
	public void tick() {
		if (!this.hasWorld()) return;  // prevent crash
		World world = this.getWorld();
		if (world.isRemote) return;   // don't bother doing anything on the client side.
    ServerWorld serverWorld = (ServerWorld)world;  // we can now be sure world is a ServerWorld
		if (ticksLeftTillDisappear == INVALID_VALUE) return;  // do nothing until the time is valid
		--ticksLeftTillDisappear;
//		this.markDirty();            // if you update a tileentity variable on the server and this should be communicated to the client,
// 																		you need to markDirty() to force a resend.  In this case, the client doesn't need to know because
                                   // nothing happens on the client until the timer expires
		if (ticksLeftTillDisappear > 0) return;   // not ready yet

		Block [] blockChoices = {Blocks.DIAMOND_BLOCK, Blocks.OBSIDIAN, Blocks.AIR, Blocks.TNT, Blocks.CORNFLOWER, Blocks.OAK_SAPLING, Blocks.WATER};
		Random random = new Random();
		Block chosenBlock = blockChoices[random.nextInt(blockChoices.length)];
	  world.setBlockState(this.pos, chosenBlock.getDefaultState());
		if (chosenBlock == Blocks.TNT) {
			Blocks.TNT.catchFire(Blocks.TNT.getDefaultState().with(TNTBlock.UNSTABLE, true), world, pos, null, null);
			world.removeBlock(pos, false);
		} else if (chosenBlock == Blocks.OAK_SAPLING) {
			SaplingBlock blockSapling = (SaplingBlock)Blocks.OAK_SAPLING;
      blockSapling.placeTree(serverWorld, this.pos, blockSapling.getDefaultState(), random);
		}
	}

@Override
	protected void registerGoals() {
		Goal meleeGoal = new TelegraphedMeleeAttackGoal<>(this).preAttackTime(getPreAttackTime()).attackInterval(getCurrentSwingDuration());
		Goal rangedGoal = new TelegraphedRangedAttackGoal<>(this).attackFrequency(0, 1).moveSpeedMod(0).windUpTime(1);

		goalSelector.addGoal(1, new MultiTypeAttackGoal(currentGoal -> {
				Entity target = getTarget();

				if (target == null)
					return 0;

				if (tickCount - lastAttackTime > 120)
					return distanceToSqr(target) < 16 ? 0 : 1;

				if (distanceToSqr(target) > 100 && !target.isFullyFrozen())
					return 1;

				return getNavigation().createPath(target, 0) == null ? 1 : 0;
			}, meleeGoal, rangedGoal));

		goalSelector.addGoal(7, new WaterAvoidingRandomStrollGoal(this, 1f));
		goalSelector.addGoal(8, new LookAtPlayerGoal(this, Player.class, 12f));
		goalSelector.addGoal(8, new RandomLookAroundGoal(this));
		targetSelector.addGoal(1, new HurtByTargetGoal(this));
	}

private void handleAfterAttacking(LivingDamageEvent.Post ev) {
		if (ev.getNewDamage() > 0 && primedAttack && DamageUtil.isMeleeDamage(ev.getSource()) && !getPlayer().getItemInHand(InteractionHand.OFF_HAND).isEmpty()) {
			this.primedAttack = false;

			if (skill.getPlayerDataManager().getResource(AoAResources.ENERGY.get()).consume(this.energyCost, true)) {
				ServerPlayer player = (ServerPlayer)getPlayer();
				LivingEntity target = ev.getEntity();

				AoAScheduler.schedule(player.getCurrentSwingDuration() - 1, tick -> {
					player.swing(InteractionHand.OFF_HAND, true);

					if (target != null && target.isAlive()) {
						if (player.distanceToSqr(target) < 36 && player.hasLineOfSight(target)) {
							DamageUtil.doScaledKnockback(target, player, 0.3f, 1, 1, 1);
							EntityUtil.applyPotions(target, player, new EffectBuilder(MobEffects.MOVEMENT_SLOWDOWN, this.stunDuration).level(127), new EffectBuilder(MobEffects.DIG_SLOWDOWN, this.stunDuration).level(127));
							activatedActionKey(player);

							if (skill.canGainXp(true))
								PlayerUtil.giveTimeBasedXpToPlayer(player, this.skill.type(), 39,  false);
						}
					}
				});
			}
		}
	}

