@Override
    public void entityInside(@NotNull BlockState state, @NotNull Level worldIn, @NotNull BlockPos pos, @NotNull Entity entityIn) {
        super.entityInside(state, worldIn, pos, entityIn);
        List<Entity> entities = worldIn.getEntitiesOfClass(Entity.class, getShape(state, worldIn, pos, CollisionContext.empty()).bounds().move(pos), EntitySelector.NO_SPECTATORS.and((p_289691_) -> {
            return !p_289691_.isIgnoringBlockTriggers();
        }));
        if (!entities.isEmpty() && worldIn.getBlockEntity(pos) instanceof RuneTile rune) {
            if (rune.spell != null) {
                // Ignore form and its augment, only check effects
                for (AbstractSpellPart part : rune.spell.recipe()) {
                    if (part instanceof AbstractEffect) {
                        // If the effect is not a filter, proceed with rune activation
                        if (part instanceof IFilter filter) {
                            // If one or more filters are detected, all must match to let the rune activate
                            if (!filter.shouldResolveOnEntity(new EntityHitResult(entityIn), worldIn)) {
                                return;
                            }
                        } else break;
                    }
                }
            }
            rune.touchedEntity = entities.getFirst();
            worldIn.scheduleTick(pos, this, 1);
        }
    }

@Override
    public void tick() {
        super.tick();
        if (disabled)
            return;
        if (!level.isClientSide && level.getGameTime() % 20 == 0 && getSource() > 0) {
            List<ISpecialSourceProvider> posList = SourceUtil.canGiveSource(worldPosition, level, 5);
            for (ISpecialSourceProvider provider : posList) {
                if (this.getSource() <= 0)
                    break;

                if (this.getToPos() != null && level.isLoaded(this.getToPos()) && level.getBlockEntity(this.getToPos()) == provider.getSource()) {
                    continue;
                }
                if (this.getFromPos() != null && level.isLoaded(this.getFromPos()) && level.getBlockEntity(this.getFromPos()) == provider.getSource()) {
                    continue;
                }

                if (!(provider.getSource() instanceof RelayTile)) {
                    transferSource(this, provider.getSource());
                    ParticleUtil.spawnFollowProjectile(level, this.worldPosition, provider.getCurrentPos(), this.getColor());
                }
            }
        }
    }

public void makeParticle(ParticleColor centerColor, ParticleColor outerColor, int intensity) {
        Level world = getLevel();
        BlockPos pos = getBlockPos();
        double xzOffset = 0.25;
        boolean isWeakFire = ritual != null && ritual.needsSourceNow();
        double centerYMax = isWeakFire ? 0.1 : 0.2;
        double outerYMax = isWeakFire ? 0.5 : 0.7;
        double ySpeed = isWeakFire ? 0.02f : 0.05f;
        intensity = isWeakFire ? intensity / 2 : intensity;
        for (int i = 0; i < intensity; i++) {
            world.addParticle(
                    GlowParticleData.createData(centerColor.nextColor((int) level.getGameTime() * 10)),
                    pos.getX() + 0.5 + ParticleUtil.inRange(-xzOffset / 2, xzOffset / 2), pos.getY() + 1 + ParticleUtil.inRange(-0.05, centerYMax), pos.getZ() + 0.5 + ParticleUtil.inRange(-xzOffset / 2, xzOffset / 2),
                    0, ParticleUtil.inRange(0.0, ySpeed), 0);
        }
        for (int i = 0; i < intensity; i++) {
            world.addParticle(
                    GlowParticleData.createData(outerColor.nextColor((int) level.getGameTime() * 10)),
                    pos.getX() + 0.5 + ParticleUtil.inRange(-xzOffset, xzOffset), pos.getY() + 1 + ParticleUtil.inRange(0, outerYMax), pos.getZ() + 0.5 + ParticleUtil.inRange(-xzOffset, xzOffset),
                    0, ParticleUtil.inRange(0.0, ySpeed), 0);
        }
        if (relayPos != null && level.getBlockEntity(relayPos) instanceof BrazierRelayTile relayTile) {
            relayTile.makeParticle(centerColor, outerColor, intensity);
        }
    }

public void tick(Level level) {
        if (!(level instanceof ServerLevel serverLevel)) {
            return;
        }
        if (!serverLevel.dimension().equals(PocketDimensionManager.POCKET_DIMENSION)) {
            return;
        }
        if (serverLevel.getGameTime() % 100 == 0) {
            serverLevel.players().forEach(player -> {
                if (!player.isCreative() && !player.isSpectator()) {
                    int pocketX = (int) (player.getX() / PocketDimensionManager.POCKET_SPACING) * PocketDimensionManager.POCKET_SPACING;
                    int pocketZ = (int) (player.getZ() / PocketDimensionManager.POCKET_SPACING) * PocketDimensionManager.POCKET_SPACING;
                    if (player.getX() < pocketX || player.getX() > pocketX + 16
                            || player.getZ() < pocketZ || player.getZ() > pocketZ + 16) {
                        // snap player back into bounds
                        var blockPos = structurePosForPlayer(player);
                        var portalPos = findPortalForStructure(serverLevel, blockPos);
                        player.resetFallDistance();
                        player.stopRiding();
                        player.moveTo(portalPos.getBottomCenter());
                    }
                }
            });
        }
    }

public synchronized void saveSummonerData(ServerLevel serverLevel, Entity summoner) {
        Set<UUID> summons = ownerToSummons.get(summoner.getUUID());
        if (summons == null) {
            return;
        }
        var savedSummons = new ArrayList<CompoundTag>();
        List<Entity> toRemove = new ArrayList<>();
        for (UUID uuid : summons) {
            Entity entity = serverLevel.getEntity(uuid);
            if (entity != null && !entity.isRemoved() && entity.isAddedToLevel()) {
                CompoundTag saveData = new CompoundTag();
                entity.save(saveData);
                int durationRemaining = INSTANCE.getExpirationTick(entity.getUUID()) - serverLevel.getServer().getTickCount();
                saveData.putInt("summon_duration_remaining", durationRemaining);
                savedSummons.add(saveData);
                toRemove.add(entity);
            }
        }
        for (Entity entity : toRemove) {
            entity.setRemoved(Entity.RemovalReason.UNLOADED_WITH_PLAYER);
        }
        IronsDataStorage.INSTANCE.setDirty();
        INSTANCE.offlineSummonersToSavedEntities.put(summoner.getUUID(), savedSummons);
        INSTANCE.stopTrackingSummonerAndSummons(summoner);
    }

public void render(float partialTicks, PoseStack PoseStackIn, MultiBufferSource bufferIn) {
        VertexConsumer buffer = bufferIn.getBuffer(RenderType.lightning());
        Matrix4f matrix = PoseStackIn.last().pose();
        Timestamp timestamp = new Timestamp(minecraft.level.getGameTime(), partialTicks);
        boolean refresh = timestamp.isPassed(refreshTimestamp, (1 / REFRESH_TIME));
        if (refresh) {
            refreshTimestamp = timestamp;
        }
        for (Iterator<Map.Entry<Object, BoltOwnerData>> iter = boltOwners.entrySet().iterator(); iter.hasNext(); ) {
            Map.Entry<Object, BoltOwnerData> entry = iter.next();
            BoltOwnerData data = entry.getValue();
            // tick our bolts based on the refresh rate, removing if they're now finished
            if (refresh) {
                data.bolts.removeIf(bolt -> bolt.tick(timestamp));
            }
            if (data.bolts.isEmpty() && data.lastBolt != null && data.lastBolt.getSpawnFunction().isConsecutive()) {
                data.addBolt(new BoltInstance(data.lastBolt, timestamp), timestamp);
            }
            data.bolts.forEach(bolt -> bolt.render(matrix, buffer, timestamp));

            if (data.bolts.isEmpty() && timestamp.isPassed(data.lastUpdateTimestamp, MAX_OWNER_TRACK_TIME)) {
                iter.remove();
            }
        }
    }

public static boolean onMessage(MessageEntityCamera message, Supplier<NetworkEvent.Context> ctx) {
			ctx.get().enqueueWork(() -> {
				Entity entity = Minecraft.getInstance().level.getEntity(message.entityID);
				if (entity instanceof Player player) {
					if (message.firstperson) {
						if (CMClientConfig.firstPerson) {
							if (player == Minecraft.getInstance().player && Minecraft.getInstance().getCameraEntity() == Minecraft.getInstance().player) {
								Minecraft.getInstance().setCameraEntity(entity);
								Minecraft.getInstance().options.setCameraType(CameraType.FIRST_PERSON);
							}
						}
					}else {
						if (CMClientConfig.thirdPerson) {
							if (player == Minecraft.getInstance().player && Minecraft.getInstance().getCameraEntity() == Minecraft.getInstance().player) {
								Minecraft.getInstance().setCameraEntity(entity);
								Minecraft.getInstance().options.setCameraType(CameraType.THIRD_PERSON_BACK);
							}
						}
					}
				}
			});

			ctx.get().setPacketHandled(true);
			return true;
		}

