        		}
        	});
        	context.setPacketHandled(true);
        }

public boolean canUse() {
		long i = this.booflo.level().getGameTime();
		if (i - this.lastCanUseCheck < 20L) {
			return false;
		} else {
			this.lastCanUseCheck = i;
			Entity target = this.booflo.getBoofloAttackTarget();
			if (target == null) {
				return false;
			} else if (!target.isAlive()) {
				return false;
			} else if (this.booflo.hasAggressiveAttackTarget()) {
				return false;
			} else if (!this.booflo.isBoofed()) {
				return false;
			} else {
				this.path = this.booflo.getNavigation().createPath(target.blockPosition(), 0);
				if (this.path != null) {
					return true;
				} else {
					return this.getAttackReachSqr(target) >= this.booflo.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());
				}
			}
		}
	}

@SubscribeEvent
	public void onLivingDeath(LivingDeathEvent event) {
		if (event.getEntity() instanceof Player && !event.getEntity().level().isClientSide) {
			Player player = (Player) event.getEntity();

			if (SuperpositionHandler.isTheBlessedOne(player)) {
				ItemStack scroll = SuperpositionHandler.getCurioStack(player, this);

				if (scroll != null && !this.hasCooldown(scroll)) {
					event.setCanceled(true);
					player.setHealth(player.getMaxHealth() / 2);

					player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1200, 2));
					player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1200, 1));
					player.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 1200, 0));
					player.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1200, 1));

					this.setCooldown(scroll, deathProtectionCooldown.getValue() * 20);

					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() ->
					new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128,
							player.level().dimension())), new PacketCosmicRevive(player.getId(), 0));
				}
			}
		}
	}

public void tickGustmaker(BlockState state, Level worldIn, BlockPos pos, boolean tickOff) {
        boolean flag = worldIn.hasNeighborSignal(pos) || worldIn.hasNeighborSignal(pos.below()) || worldIn.hasNeighborSignal(pos.above());
        boolean flag1 = state.getValue(TRIGGERED);
        if (flag && !flag1) {
            if(worldIn.isLoaded(pos)){
                Vec3 dispensePosition = getDispensePosition(pos, state.getValue(FACING));
                Vec3 gustDir = Vec3.atLowerCornerOf(state.getValue(FACING).getNormal()).multiply(0.1, 0.1, 0.1);
                EntityGust gust = new EntityGust(worldIn);
                gust.setGustDir((float) gustDir.x, (float) gustDir.y, (float) gustDir.z);
                gust.setPos(dispensePosition.x, dispensePosition.y, dispensePosition.z);
                if(state.getValue(FACING).getAxis() == Direction.Axis.Y){
                    gust.setVertical(true);
                }
                if (!worldIn.isClientSide) {
                    worldIn.addFreshEntity(gust);
                }
            }
            worldIn.setBlock(pos, state.setValue(TRIGGERED, Boolean.valueOf(true)), 2);
            worldIn.scheduleTick(pos, this, 20);
        } else if (flag1) {
            if (tickOff) {
                worldIn.scheduleTick(pos, this, 20);
                worldIn.setBlock(pos, state.setValue(TRIGGERED, Boolean.valueOf(false)), 2);
            }
        }
    }

@Override
        public boolean canUse() {
            if (EntityCrow.this.isPassenger() || EntityCrow.this.aiItemFlag || EntityCrow.this.isVehicle() || EntityCrow.this.isTame()) {
                return false;
            }
            if (!this.mustUpdate) {
                final long worldTime = EntityCrow.this.level().getGameTime() % 10;
                if (worldTime != 0) {
                    if (EntityCrow.this.getNoActionTime() >= 100) {
                        return false;
                    }
                    if (EntityCrow.this.getRandom().nextInt(this.executionChance) != 0) {
                        return false;
                    }
                }
            }
            final List<Entity> list = EntityCrow.this.level().getEntitiesOfClass(Entity.class, this.getTargetableArea(this.getTargetDistance()), this.targetEntitySelector);
            if (list.isEmpty()) {
                return false;
            } else {
                list.sort(this.theNearestAttackableTargetSorter);
                this.targetEntity = list.get(0);
                this.mustUpdate = false;
                return true;
            }
        }

public void calculateCollision(Level world) {

        Vec3 start = this.position();
        Vec3 end = start.add(this.getDeltaMovement());
        BlockHitResult blockResult = this.getBlockHitResult(world, start, end);
        boolean blockCollision = false;
        if (blockResult.getType() != HitResult.Type.MISS) {
            end = blockResult.getLocation();
            BlockPos blockpos = blockResult.getBlockPos();
            BlockState blockstate = world.getBlockState(blockpos);
            if (blockstate.is(Blocks.NETHER_PORTAL)) {
                this.handleInsidePortal(blockpos);
            } else if (blockstate.is(Blocks.END_GATEWAY)) {
                BlockEntity blockentity = this.level.getBlockEntity(blockpos);
                if (blockentity instanceof TheEndGatewayBlockEntity && TheEndGatewayBlockEntity.canEntityTeleport(this)) {
                    TheEndGatewayBlockEntity.teleportEntity(this.level, blockpos, blockstate, this, (TheEndGatewayBlockEntity) blockentity);
                }
            } else {
                blockCollision = true;
            }
        }
        this.hitEntities(this.level, start, end);
        if (blockCollision && !EventHooks.onProjectileImpact(this, blockResult)) {
            this.onHitBlock(blockResult);
        }
    }

public void onEntityCreated(AbstractContraptionEntity entity) {
		this.entity = entity;

		// Create subcontraptions
		for (BlockFace blockFace : pendingSubContraptions) {
			Direction face = blockFace.getFace();
			StabilizedContraption subContraption = new StabilizedContraption(face);
			Level world = entity.level();
			BlockPos pos = blockFace.getPos();
			try {
				if (!subContraption.assemble(world, pos))
					continue;
			} catch (AssemblyException e) {
				continue;
			}
			subContraption.removeBlocksFromWorld(world, BlockPos.ZERO);
			OrientedContraptionEntity movedContraption = OrientedContraptionEntity.create(world, subContraption, face);
			BlockPos anchor = blockFace.getConnectedPos();
			movedContraption.setPos(anchor.getX() + .5f, anchor.getY(), anchor.getZ() + .5f);
			world.addFreshEntity(movedContraption);
			stabilizedSubContraptions.put(movedContraption.getUUID(), new BlockFace(toLocalPos(pos), face));
		}

		storage.initialize();
		invalidateColliders();
	}

@SubscribeEvent
	public static void hauntedBellCreatesPulse(PlayerTickEvent.Post event) {
		Player player = event.getEntity();

		if (player.level().isClientSide())
			return;

		if (player.isSpectator())
			return;
		if (!player.isHolding(AllBlocks.HAUNTED_BELL::isIn))
			return;

		boolean firstPulse = false;

		try {
			IntAttached<Entity> ticker = WARMUP.get(player.getUUID(), () -> IntAttached.with(WARMUP_TICKS, player));
			firstPulse = ticker.getFirst() == 1;
			ticker.decrement();
			if (!ticker.isOrBelowZero())
				return;
		} catch (ExecutionException ignored) {}

		long gameTime = player.level().getGameTime();
		if ((firstPulse || gameTime % RECHARGE_TICKS != 0) && player.level() instanceof ServerLevel serverLevel)
			sendPulse(serverLevel, player.blockPosition(), DISTANCE, false);
	}

@Override
	protected void read(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		state = NBTHelper.readEnum(compound, "State", State.class);
		mode = NBTHelper.readEnum(compound, "Mode", Mode.class);
		timer = compound.getInt("Timer");
		redstoneLocked = compound.getBoolean("Powered");
		if (compound.contains("Owner"))
			owner = compound.getUUID("Owner");

		deferredInventoryList = compound.getList("Inventory", Tag.TAG_COMPOUND);
		overflowItems = NBTHelper.readItemList(compound.getList("Overflow", Tag.TAG_COMPOUND), registries);
		if (compound.contains("HeldItem")) {
			heldItem = ItemStack.parseOptional(registries, compound.getCompound("HeldItem"));
		}
		super.read(compound, registries, clientPacket);

		if (!clientPacket)
			return;
		fistBump = compound.getBoolean("Fistbump");
		reach = compound.getFloat("Reach");
		if (compound.contains("Particle")) {
			ItemStack particleStack = ItemStack.parseOptional(registries, compound.getCompound("Particle"));
			SandPaperItem.spawnParticles(VecHelper.getCenterOf(worldPosition)
				.add(getMovementVector().scale(reach + 1)), particleStack, this.level);
		}
	}

