        @Override
        public IMessage onMessage(final MessageExplosionCharmFX message, final MessageContext ctx) {
            World world = Minecraft.getMinecraft().world;
            Minecraft.getMinecraft().addScheduledTask(() -> {
                for (int k = 0; k < 40; k++) {
                    int lifetime = 12 + random.nextInt(12);
                    double angleA = random.nextDouble() * Math.PI * 2;
                    double angleB = random.nextDouble() * Math.PI * 2;
                    double dist = random.nextDouble() * 1.0 + 0.5;
                    float xOffset = (float) (Math.cos(angleA) * Math.cos(angleB));
                    float yOffset = (float) (Math.sin(angleA) * Math.cos(angleB));
                    float zOffset = (float) Math.sin(angleB);
                    double x = message.posX + xOffset * dist;
                    double y = message.posY + yOffset * dist;
                    double z = message.posZ + zOffset * dist;
                    double vx = (message.absorbX - x) / lifetime;
                    double vy = (message.absorbY - y) / lifetime;
                    double vz = (message.absorbZ - z) / lifetime;
                    ParticleUtil.spawnParticleGlow(world, (float) x, (float) y, (float) z, (float) vx, (float) vy, (float) vz, 255, 64, 16, 2.0f + random.nextFloat() * 2.0f, lifetime);
                    float smokeSpeed = 0.15f;
                    ParticleUtil.spawnParticleSmoke(world, (float)(message.posX + xOffset * dist), (float)(message.posY + yOffset * dist), (float)(message.posZ + zOffset * dist), xOffset * smokeSpeed, yOffset * smokeSpeed, zOffset * smokeSpeed, 30/255f, 30/255f, 30/255f, 160/255f, 4.0f + random.nextFloat() * 20.0f, 20+random.nextInt(20));
                }
            });
            return null;
        }

public BlockState updateShape(BlockState p_154147_, Direction p_154148_, BlockState p_154149_, LevelAccessor p_154150_, BlockPos p_154151_, BlockPos p_154152_) {
        if (p_154147_.getValue(WATERLOGGED)) {
            p_154150_.scheduleTick(p_154151_, Fluids.WATER, Fluids.WATER.getTickDelay(p_154150_));
        }

        if (p_154148_ != Direction.UP && p_154148_ != Direction.DOWN) {
            return p_154147_;
        } else {
            Direction direction = p_154147_.getValue(TIP_DIRECTION);
            if (direction == Direction.DOWN && p_154150_.getBlockTicks().hasScheduledTick(p_154151_, this)) {
                return p_154147_;
            } else if (p_154148_ == direction.getOpposite() && !this.canSurvive(p_154147_, p_154150_, p_154151_)) {
                if (direction == Direction.DOWN) {
                    p_154150_.scheduleTick(p_154151_, this, 2);
                } else {
                    p_154150_.scheduleTick(p_154151_, this, 1);
                }

                return p_154147_;
            } else {
                boolean flag = p_154147_.getValue(THICKNESS) == DripstoneThickness.TIP_MERGE;
                DripstoneThickness dripstonethickness = calculateDripstoneThickness(p_154150_, p_154151_, direction, flag);
                return p_154147_.setValue(THICKNESS, dripstonethickness);
            }
        }
    }

