private void scanOres() {
        if (!(this.player instanceof ServerPlayer serverPlayer)) return;

        Level level = this.player.level();
        int chunkDiameter = this.chunkRadius * 2 - 1;

        if (this.player.tickCount % this.scanInterval == 0 && this.chunkIndex < chunkDiameter * chunkDiameter) {
            int row = this.chunkIndex / chunkDiameter;
            int column = this.chunkIndex % chunkDiameter;

            int ox = column - this.chunkRadius + 1;
            int oz = row - this.chunkRadius + 1;

            LevelChunk chunk = level.getChunk(this.playerChunkPos.x + ox, this.playerChunkPos.z + oz);
            if (mode == ProspectorMode.ORE) {
                ServerCache.instance.prospectAllInChunk(level.dimension(), chunk.getPos(), serverPlayer);
            }

            ProspectingUpdatePacket<T> packet = new ProspectingUpdatePacket<>(this.playerChunkPos.x + ox,
                    this.playerChunkPos.z + oz, mode);
            mode.scan(packet.data, chunk);
            this.syncHandler.notifyUpdate(packet::writePacketData);

            this.chunkIndex++;
        }
    }

public static Set<BlockPos> conditionalBlockPosSearch(BlockPos start, BiPredicate<BlockPos, BlockPos> condition,
                                                          int blockLimit, int iterationLimit) {
        var passed = new LinkedHashSet<BlockPos>();
        var queue = new ObjectArrayFIFOQueue<Tuple<BlockPos, BlockPos>>(16);
        queue.enqueue(new Tuple<>(null, start));

        var iterations = 0;
        while (!queue.isEmpty() && iterations < iterationLimit && passed.size() < blockLimit) {
            var tuple = queue.dequeue();
            var next = tuple.getB();
            if (passed.contains(next)) {
                continue;
            }
            if (condition.test(tuple.getA(), tuple.getB())) {
                passed.add(next);
                getNeighbors(next).forEach(neighbor -> {
                    if (!passed.contains(neighbor)) {
                        queue.enqueue(new Tuple<>(next, neighbor));
                    }
                });
            }
            iterations++;
        }

        return passed;
    }

protected void createWheelParticles(CarWheel wheel, boolean runBetween) {
        Vec3d pos;
        Vec3d opposite;
        if (runBetween) {
            Vec3d vec = wheel.getCurrentWheelPos();
            Vec3d oldVec = wheel.getCurrentWheelPos();

            Vec3d vec1 = wheel.getOppositeWheel().getCurrentWheelPos();
            Vec3d oldVec1 = wheel.getOppositeWheel().getCurrentWheelPos();

            pos = new Vec3d((vec.x + oldVec.x) / 2D, (vec.y + oldVec.y) / 2D, (vec.z + oldVec.z) / 2D);
            opposite = new Vec3d((vec1.x + oldVec1.x) / 2D, (vec1.y + oldVec1.y) / 2D, (vec1.z + oldVec1.z) / 2D);
        } else {
            pos = wheel.getCurrentWheelPos();
            opposite = wheel.getOppositeWheel().getCurrentWheelPos();
        }
        if (this instanceof GyrosphereEntity) {
            return; // Skip rendering tire tracks
        }
