@Override
	public void inventoryTick(ItemStack tear, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % COOLDOWN != 0 || !isEnabled(tear)
				|| isInCooldown(tear, level)) {
			return;
		}

		ItemStack tearStack = getStackFromTear(tear);
		if (tearStack.isEmpty()) {
			resetTear(tear);
			return;
		}

		Optional<Integer> experience = InfernalTearValueHelper.getItemExperience(level, tearStack.getItem());
		if (experience.isEmpty()) {
			resetTear(tear);
			return;
		}

		int countConsumed = InventoryHelper.consumeItemStack(stack -> ItemStack.isSameItemSameComponents(tearStack, stack), player, 4).getCount();
		if (countConsumed > 0) {
			player.giveExperiencePoints(experience.get() * countConsumed);
		} else {
			setCooldown(tear, level, NOTHING_FOUND_COOLDOWN);
		}
	}

private static Optional<Inputs> getInputs(int size, IntFunction<ItemStack> getItem) {
		ItemStack linker = ItemStack.EMPTY;
		ItemStack endpoint = ItemStack.EMPTY;
		int linkerSlot = -1;
		int endpointSlot = -1;
		for (int slot = 0; slot < size; slot++) {
			ItemStack stack = getItem.apply(slot);
			if (stack.isEmpty()) {
				continue;
			}
			if (linker.isEmpty() && isLinker(stack)) {
				linker = stack;
				linkerSlot = slot;
			} else if (endpoint.isEmpty() && isEndpoint(stack)) {
				endpoint = stack;
				endpointSlot = slot;
			} else {
				return Optional.empty();
			}
		}
		if (linker.isEmpty() || endpoint.isEmpty()) {
			return Optional.empty();
		}
		EnderLinkPendingCraftPlan plan = getPlan(linker, endpoint);
		return plan == null ? Optional.empty() : Optional.of(new Inputs(linker, linkerSlot, endpoint, endpointSlot, plan));
	}

public void depositPlayerItems(Player player, InteractionHand hand) {
		if (getLevel() == null) {
			return;
		}
		long gameTime = getLevel().getGameTime();
		boolean doubleClick = gameTime - lastDepositTime < 10;
		lastDepositTime = gameTime;
		if (doubleClick) {
			PlayerMainInvWrapper playerInventory = new PlayerMainInvWrapper(player.getInventory());
			InventoryHelper.iterate(playerInventory, (slot, stack) -> {
				if (canDepositStack(stack)) {
					ItemStack resultStack = insertItem(stack, true, false);
					int countToExtract = stack.getCount() - resultStack.getCount();
					if (countToExtract > 0 && playerInventory.extractItem(slot, countToExtract, true).getCount() == countToExtract) {
						insertItem(playerInventory.extractItem(slot, countToExtract, false), false, false);
					}
				}
			});
			return;
		}

		ItemStack itemInHand = player.getItemInHand(hand);
		if (!itemInHand.isEmpty() && canDepositStack(itemInHand)) {
			player.setItemInHand(hand, insertItem(itemInHand, false, false));
		}
	}

public void recheckOpeners(Entity entity) {
		Level level = entity.level();
		List<Player> playersWithStorageOpen = getPlayersWithContainerOpen(level, entity.blockPosition());
		maxInteractionRange = 0.0;

		for (Player player : playersWithStorageOpen) {
			maxInteractionRange = Math.max(player.entityInteractionRange(), maxInteractionRange);
		}

		int numberOfPlayers = playersWithStorageOpen.size();
		if (openCount != numberOfPlayers) {
			if (numberOfPlayers != 0 && openCount == 0) {
				onOpen();
				level.gameEvent(null, GameEvent.CONTAINER_OPEN, entity.blockPosition());
			} else if (numberOfPlayers == 0) {
				onClose();
				level.gameEvent(null, GameEvent.CONTAINER_CLOSE, entity.blockPosition());
			}

			openCount = numberOfPlayers;
		}

		if (numberOfPlayers > 0) {
			nextOpenRecheck = level.getGameTime() + CHECK_TICK_DELAY;
		}
	}

