public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.isEating()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.01F, 0));
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }

        if (!this.isNoAi() && !this.isBaby()) {
            if (this.ringBufferIndex < 0) {
                for (int i = 0; i < this.ringBuffer.length; ++i) {
                    this.ringBuffer[i][0] = this.getYRot();
                    this.ringBuffer[i][1] = this.getY();
                }
            }
            this.ringBufferIndex++;
            if (this.ringBufferIndex == this.ringBuffer.length) {
                this.ringBufferIndex = 0;
            }
            this.ringBuffer[this.ringBufferIndex][0] = this.yRotO + 0.5F * Mth.wrapDegrees(this.getYRot() - this.yRotO);
            this.ringBuffer[ringBufferIndex][1] = this.getY();
        }
    }

@Override
    public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
        level.scheduleTick(pos, this, getFireTickDelay(level.getRandom()));
        if (!state.canSurvive(level, pos)) {
            level.removeBlock(pos, false);
        }

        int age = state.getValue(AGE);
        int newAge = Math.min(15, age + random.nextInt(3) / 2);
        if (age != newAge) {
            state = state.setValue(AGE, newAge);
            level.setBlock(pos, state, 260);
        }

        if (!this.isValidFireLocation(level, pos)) {
            BlockPos below = pos.below();
            if (!level.getBlockState(below).isFaceSturdy(level, below, Direction.UP) || age > 3) {
                level.removeBlock(pos, false);
            }
            return;
        }

        if (age == 15 && random.nextInt(4) == 0 && !this.canCatchFire(level, pos.below(), Direction.UP)) {
            level.removeBlock(pos, false);
        }
    }

public static <T extends IFactionPlayer<T> & ISkillPlayer<T>> void handleForgetSkillPacket(ServerboundForgetSkillPacket msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            Player player = context.player();
            if (!player.isCreative()) {
                LOGGER.warn("Player {} cannot forget skills, they're not in creative mode", player);
                return;
            }

            Optional<T> factionPlayerOpt = FactionPlayerHandler.get(player).getCurrentSkillPlayer();
            factionPlayerOpt.ifPresent(factionPlayer -> {
                Holder<ISkill<?>> skill = msg.skill();
                ISkillHandler<T> skillHandler = factionPlayer.getSkillHandler();
                List<Holder<? extends ISkill<?>>> cascade = SkillTreeGraphs.get(player.level()).forgetCascade(msg.skillTree(), skill, skillHandler::isSkillEnabled);

                if (cascade.isEmpty()) {
                    LOGGER.warn("Skill {} cannot be forgotten by {} in skill tree {}", skill, player, msg.skillTree());
                    return;
                }

                for (Holder<? extends ISkill<?>> forgotten : cascade) {
                    //noinspection unchecked
                    skillHandler.disableSkill((Holder<ISkill<T>>) forgotten, msg.skillTree());
                }
            });
        });
    }

private void processApplicableRecipes() {
        for (ApplicableRecipe applicableRecipe : applicableRecipes) {
            PressureChamberRecipe recipe = applicableRecipe.recipe;
            float requiredPressure = recipe.getCraftingPressure(itemsInChamber, applicableRecipe.slots);
            boolean pressureOK = requiredPressure <= getPressure() && requiredPressure > 0F
                    || requiredPressure >= getPressure() && requiredPressure < 0F;
            if (Math.abs(requiredPressure) < Math.abs(recipePressure)) {
                recipePressure = requiredPressure;
            }
            if (pressureOK) {
                // let's craft! (although if the output handler is full, we won't...)
                isSufficientPressureInChamber = true;
                if (giveOutput(recipe.craftRecipe(itemsInChamber, applicableRecipe.slots, true), true)
                        && giveOutput(recipe.craftRecipe(itemsInChamber, applicableRecipe.slots, false), false)) {
                    if (nonNullLevel().getGameTime() - lastSoundTick > 5) {
                        nonNullLevel().playSound(null, getBlockPos(), SoundEvents.CHICKEN_EGG, SoundSource.BLOCKS, 0.7f, 0.8f);
                        lastSoundTick = nonNullLevel().getGameTime();
                    }
                }
                // Craft at most one recipe each tick; this is because crafting changes the contents of the
                // chamber, possibly invalidating other applicable recipes.  Modifying the chamber's contents
                // automatically triggers a rescan for applicable recipes on the next tick.
                break;
            }
        }
    }

public static IHackableEntity<?> getHackableForEntity(Entity entity, Player player) {
        HackManager manager = getInstance(player.level());

        // prune the tracked entities map every 60 ticks, removing dead or no-longer-hackable entities
        if (player.level().getGameTime() - 60 > manager.lastEntityPrune) {
            manager.hackableEntities.entrySet().removeIf(
                    entry -> !entry.getKey().isAlive()
                            || !entry.getValue().canHack(entry.getKey(), player) && !isInDisplayCooldown(entry.getValue(), entry.getKey())
            );
            manager.lastEntityPrune = player.level().getGameTime();
        }

        // entities which implement IHackableEntity directly
        if (entity instanceof IHackableEntity<?> h && h.canHack(entity, player))
            return h;

        // entities which have been registered with the hack manager
        IHackableEntity<?> hackable = manager.hackableEntities.get(entity);
        if (hackable == null) {
            hackable = CommonArmorRegistry.getInstance().getHackable(entity, player);
            if (hackable != null) {
                manager.hackableEntities.put(entity, hackable);
            }
        }
        return hackable;
    }

private Set<PressureTubeBlockEntity> computeConnectedTubes(Level level, BlockPos initialPos) {
        Set<PressureTubeBlockEntity> tubes = new HashSet<>();
        Set<BlockPos> traversedPositions = new HashSet<>();
        Deque<BlockPos> pendingPositions = new ArrayDeque<>(List.of(initialPos));

        while (!pendingPositions.isEmpty()) {
            BlockPos pos = pendingPositions.pop();
            BlockState state = level.getBlockState(pos);
            if (state.getBlock() instanceof ITubeNetworkConnector nc) {
                PneumaticCraftUtils.getBlockEntityAt(level, pos, PressureTubeBlockEntity.class).ifPresent(tubes::add);
                for (Direction dir : DirectionUtil.VALUES) {
                    BlockPos pos1 = pos.relative(dir);
                    if (!level.isLoaded(pos1)) continue;
                    BlockState state1 = level.getBlockState(pos1);
                    if (state1.getBlock() instanceof ITubeNetworkConnector nc1
                            && nc1.canConnectToNetwork(level, pos1, dir.getOpposite(), state1)
                            && nc.canConnectToNetwork(level, pos, dir, state)
                            && traversedPositions.add(pos1))
                    {
                        pendingPositions.add(pos1);
                    }
                }
            }
        }
        return tubes;
    }

@Override
    public void addUpgradeTooltip(PNCUpgrade upgrade, List<Component> tooltip) {
        Collection<Item> acceptors = ApplicableUpgradesDB.getInstance().getItemsWhichAccept(upgrade);
        if (!acceptors.isEmpty()) {
            List<Component> tempList = new ArrayList<>(acceptors.size());
            for (Item acceptor : acceptors) {
                if (!UpgradableItemUtils.isUpgradeBlacklisted(acceptor, upgrade.getItemStack())) {
                    tempList.add(Symbols.bullet().append(acceptor.getDescription().copy().withStyle(ChatFormatting.DARK_AQUA)));
                }
            }
            if (tempList.isEmpty()) {
                tooltip.add(xlate("pneumaticcraft.gui.misc.none").withStyle(ChatFormatting.GOLD));
            }
            tempList.sort(Comparator.comparing(Component::getString));
            if (tempList.size() > MAX_UPGRADES_IN_TOOLTIP) {
                int n = (int) ((ClientUtils.getClientLevel().getGameTime() / 8) % acceptors.size());
                List<Component> tempList2 = new ArrayList<>(MAX_UPGRADES_IN_TOOLTIP);
                for (int i = 0; i < MAX_UPGRADES_IN_TOOLTIP; i++) {
                    tempList2.add(tempList.get((n + i) % tempList.size()));
                }
                tooltip.addAll(tempList2);
            } else {
                tooltip.addAll(tempList);
            }
        }
    }

