        public static boolean onMessage(MessageCMMultipart message, Supplier<NetworkEvent.Context> ctx) {
            ctx.get().enqueueWork(new Runnable() {
                @Override
                public void run() {
                    Level world = Minecraft.getInstance().level;
                    if (world == null)
                        return;
                    Entity ent = world.getEntity(message.id);
                    if (ent != null && ent.isMultipartEntity()) {
                        PartEntity<?>[] parts = ent.getParts();
                        if (parts == null)
                            return;
                        int index = 0;
                        for (PartEntity<?> part : parts) {
                            if (part instanceof Cm_Part_Entity<?> tfPart) {
                                tfPart.readData(message.data.get(index));
                                index++;
                            }
                        }
                    }
                }
            });
            ctx.get().setPacketHandled(true);
            return true;
        }

private static void destroy(Level world, BlockPos pos) throws CommandSyntaxException {
        Long2ObjectMap<ChunkAccess> chunkMap = new Long2ObjectOpenHashMap<>();
        if (!isMekanismBlock(world, chunkMap, pos)) {
            //If we didn't hit a mekanism block throw an error that we missed
            throw MISS.create();
        }
        Set<BlockPos> traversed = new HashSet<>();
        Queue<BlockPos> openSet = new ArrayDeque<>();
        openSet.add(pos);
        traversed.add(pos);
        while (!openSet.isEmpty()) {
            BlockPos ptr = openSet.poll();
            if (isMekanismBlock(world, chunkMap, ptr)) {
                if (WorldUtils.getTileEntity(world, chunkMap, ptr) instanceof Clearable clearable) {
                    clearable.clearContent();
                }
                world.setBlock(ptr, world.getFluidState(ptr).createLegacyBlock(), Block.UPDATE_ALL | Block.UPDATE_SUPPRESS_DROPS);
                for (Direction side : EnumUtils.DIRECTIONS) {
                    BlockPos offset = ptr.relative(side);
                    if (traversed.add(offset)) {
                        openSet.add(offset);
                    }
                }
            }
        }
    }

