private void updateQueue(Map<@Nullable IRenderSetup, Queue<GTParticle>> renderQueue) {
        Iterator<Queue<GTParticle>> it = renderQueue.values().iterator();
        while (it.hasNext()) {
            Queue<GTParticle> particlesForSetup = it.next();

            Iterator<GTParticle> particles = particlesForSetup.iterator();
            while (particles.hasNext()) {
                GTParticle particle = particles.next();

                if (particle.isAlive()) {
                    try {
                        particle.onUpdate();
                    } catch (RuntimeException exception) {
                        GTCEu.LOGGER.error("Particle update error: {}", particle, exception);
                        particle.setExpired();
                    }
                    if (particle.isAlive()) continue;
                }

                particles.remove();
            }

            if (particlesForSetup.isEmpty()) {
                it.remove();
            }
        }
    }

public void updateFreshness(SpoilContext spoilContext, boolean createTag) {
        if (!stack.is(originalItem)) return;
        if (!createTag && !initialized || frozen) return;
        if (!spoilContext.isEmpty()) setSpoilContext(spoilContext);
        Level level = SpoilContext.getDefaultLevel();
        if (level != null && createTag && !initialized) {
            setCreationTick(level.getGameTime());
        }
        if (level != null && this.shouldSpoil()) {
            long spoilTicks = this.getSpoilTicks();
            long timeDifference = level.getGameTime() - creationTick - spoilTicks;
            if (timeDifference >= 0) {
                ItemStack newStack = this.spoilResult(getSpoilContext(), GTCEu.isClientThread());
                ((ISpoilableItemStackExtension) (Object) stack).gtceu$setStack(newStack);
                onItemChanged();
                ISpoilableItem newSpoilable = GTCapabilityHelper.getSpoilable(stack);
                if (newSpoilable != null) {
                    newSpoilable.setCreationTick(level.getGameTime() - timeDifference);
                    try {
                        newSpoilable.updateFreshness(spoilContext, false);
                    } catch (StackOverflowError ignored) {
                        // if items spoil in a giant chain or a loop
                    }
                }
            }
        }
    }

public static Set<BlockPos> search(Predicate<BlockPos> value, BlockPos start, int limit) {
        Set<BlockPos> alreadyVisited = new HashSet<>();
        Set<BlockPos> valid = new LinkedHashSet<>();
        int iteration = 0;

        Queue<BlockPos> queue = new ArrayDeque<>();
        queue.add(start);

        BlockPos currentNode;

        while (!queue.isEmpty()) {
            currentNode = queue.remove();

            if (value.test(currentNode)) {
                if (limit < iteration++) {
                    break;
                }
                valid.add(currentNode);
            } else {
                alreadyVisited.add(currentNode);
                queue.addAll(getNeighbors(currentNode));
                queue.removeAll(alreadyVisited);
            }
        }

        return valid;
    }

public static void handle(PacketItemGui message, IPayloadContext context) {
    context.enqueueWork(() -> {
      ServerPlayer player = (ServerPlayer) context.player();
      if (player == null) {
        return;
      }
      if (message.item == ItemRegistry.LUNCHBOX.get()) {
        ItemStack itemFoodMouse = player.containerMenu.getCarried();
        if (itemFoodMouse.isEmpty()) {
          player.openMenu(new ContainerProviderLunchbox(), buf -> buf.writeInt(message.slot));
        }
        else if (itemFoodMouse.getFoodProperties(player) != null) {
          ItemStack lunchbox = player.getInventory().getItem(message.slot);
          ItemLunchbox.insertFoodIntoLunchbox(lunchbox, itemFoodMouse, player);
        }
      }
      else if (message.item == ItemRegistry.STORAGE_BAG.get() && !(player.containerMenu instanceof ContainerStorageBag)) {
        player.openMenu(new StorageBagContainerProvider(message.slot), buf -> buf.writeInt(message.slot));
      }
      else if (message.item == ItemRegistry.CRAFTING_BAG.get() && !(player.containerMenu instanceof CraftingBagContainer)) {
        player.openMenu(new CraftingBagContainerProvider(message.slot), buf -> buf.writeInt(message.slot));
      }
      else if (message.item == ItemRegistry.CRAFTING_STICK.get() && !(player.containerMenu instanceof CraftingStickContainer)) {
        player.openMenu(new CraftingStickContainerProvider(message.slot), buf -> buf.writeInt(message.slot));
      }
    });
  }

public boolean environmentSpawnCheck(World world, BlockPos pos) {
        if(this.creatureInfo.creatureSpawn.worldDayMin > 0) {
            int currentDay = (int) Math.floor(world.getTotalWorldTime() / 24000D);
            LycanitesMobs.printDebug("MobSpawns", "Checking world age, currently on day: " + currentDay + ", must be at least day: " + this.creatureInfo.creatureSpawn.worldDayMin + ".");
            if (currentDay < this.creatureInfo.creatureSpawn.worldDayMin)
                return false;
        }
    	LycanitesMobs.printDebug("MobSpawns", "Checking dimension.");
    	if(!this.isNativeDimension(this.getEntityWorld()))
    		return false;
    	LycanitesMobs.printDebug("MobSpawns", "Block preference.");
        if(this.getBlockPathWeight(pos.getX(), pos.getY(), pos.getZ()) < 0.0F)
        	return false;
    	LycanitesMobs.printDebug("MobSpawns", "Checking for liquid (water, lava, ooze, etc).");
        if(!this.spawnsInWater && this.getEntityWorld().containsAnyLiquid(this.getEntityBoundingBox()))
            return false;
        else if(!this.spawnsOnLand && !this.getEntityWorld().containsAnyLiquid(this.getEntityBoundingBox()))
            return false;
    	LycanitesMobs.printDebug("MobSpawns", "Checking for underground.");
        if(!this.spawnsUnderground && this.isBlockUnderground(pos.getX(), pos.getY() + 1, pos.getZ()))
        	return false;
        LycanitesMobs.printDebug("MobSpawns", "Checking for nearby bosses.");
		if(!this.checkSpawnBoss(world, pos))
			return false;

        return true;
    }

