            for (FireTornado fireTornadoEntity : this.level.getEntitiesOfClass(FireTornado.class, this.getBoundingBox().inflate(64))) {
                fireTornadoEntity.discard();
            }
        }
        super.remove(p_146834_);
    }

@Override
    public boolean canUse() {
        long i = this.attacker.level.getGameTime();
        if (i - this.field_220720_k < 20L) {
            return false;
        } else {
            this.field_220720_k = i;
            LivingEntity livingentity = this.attacker.getTarget();
            if (livingentity == null) {
                return false;
            } else if (!livingentity.isAlive()) {
                return false;
            } else {
                if (canPenalize) {
                    if (--this.delayCounter <= 0) {
                        this.path = this.attacker.getNavigation().createPath(livingentity, 0);
                        this.delayCounter = 4 + this.attacker.getRandom().nextInt(7);
                        return this.path != null;
                    } else {
                        return true;
                    }
                }
                this.path = this.attacker.getNavigation().createPath(livingentity, 0);
                return this.path != null;
            }
        }
    }

public void aiStep() {
        super.aiStep();

        if (!this.level.isClientSide) {
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.003D, 0.0D));
            }
            if (this.tickCount % 1000 == 0) {
                if (this.wantsToBreed() && !this.isMale()) {
                    this.breed();
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }
        else {
            if (Math.abs(this.getYRot() - this.yRotO) > 0.005) {
                this.offset = Mth.rotLerp(0.05F, this.offset, (this.getYRot() - this.yRotO));
            }
            if (this.isInWater() && !this.isOnGround() && this.swimProgress < 20) {
                this.swimProgress++;
            } else if ((!this.isInWater() || this.isOnGround()) && this.swimProgress > 0) {
                this.swimProgress--;
            }
        }
    }

@Override
    public void serverTick() {
        super.serverTick();

        if (canAct(distributeResourcesInterval())) {
            distributeResources();
        }

        // Every 5 ticks, ensure active state is up-to-date.
        // Doing this every 5 ticks instead of every tick should reduce visual flicker.
        if (level != null && level.getGameTime() % 5 == 0) {

            boolean isActive = isActive();
            boolean needBlockStateUpdate = supportsActiveState
                    && getBlockState().getValue(ProgressMachineBlock.POWERED) != isActive;
            boolean needStateUpdate = states.contains(MachineState.ACTIVE) != isActive;

            if (needBlockStateUpdate) {
                level.setBlockAndUpdate(worldPosition,
                        getBlockState().setValue(ProgressMachineBlock.POWERED, isActive));
            }

            if (needStateUpdate) {
                updateMachineState(MachineState.ACTIVE, isActive);
            }
        }
    }

@Override
    public void playAmbientSound() {
        if (isSleeping() || level.isClientSide) {
            return;
        }
        if (isUnderWater()) {
            //Copy of playAmbientSound, but we filter out players that aren't also underwater
            SoundEvent soundEvent = getAmbientSound();
            if (soundEvent != null) {
                float volume = getSoundVolume();
                double radius = volume > 1 ? (double) (16 * volume) : 16;
                var packet = new ClientboundSoundPacket(soundEvent, getSoundSource(), getX(), getY(), getZ(), volume, getVoicePitch());
                for (ServerPlayer player : ((ServerLevel) level).getServer().getPlayerList().getPlayers()) {
                    if (player.isUnderWater() && player.level.dimension() == level.dimension()) {
                        double d = getX() - player.getX();
                        double e = getY() - player.getY();
                        double f = getZ() - player.getZ();
                        if (d * d + e * e + f * f < radius * radius) {
                            player.connection.send(packet);
                        }
                    }
                }
            }
        } else {
            super.playAmbientSound();
        }
    }

