private void handleAmmoRepair(ItemStack stack, Level world, Minigun minigun) {
        if (minigun.getPlayer().containerMenu instanceof MinigunMagazineMenu) {
            return;  // avoid potential item duping or other shenanigans
        }
        int itemLife = minigun.getUpgrades(ModUpgrades.ITEM_LIFE.get());
        if (itemLife > 0) {
            MagazineHandler handler = getMagazine(stack);
            boolean repaired = false;
            float pressure = minigun.getAirCapability().orElseThrow(RuntimeException::new).getPressure();
            if (world.getGameTime() % (200 - itemLife * 35L) == 0) {
                for (int i = 0; i < handler.getSlots() && pressure > 0.25f; i++) {
                    ItemStack ammo = handler.getStackInSlot(i);
                    if (ammo.getItem() instanceof AbstractGunAmmoItem && ammo.getDamageValue() > 0) {
                        ammo.setDamageValue(ammo.getDamageValue() - 1);
                        if (!minigun.getPlayer().isCreative()) {
                            minigun.getAirCapability().ifPresent(h -> h.addAir(-(100 * itemLife)));
                        }
                        pressure = minigun.getAirCapability().orElseThrow(RuntimeException::new).getPressure();
                        repaired = true;
                    }
                }
            }
            if (repaired) {
                handler.save();
            }
        }
    }

private static boolean areBlocksLocked(BlockGetter getter, BlockPos start) {
		int limit = 512;
		Deque<BlockPos> queue = new ArrayDeque<>();
		Set<BlockPos> checked = new HashSet<>();
		queue.offer(start);

		for (int iter = 0; !queue.isEmpty() && iter < limit; iter++) {
			BlockPos cur = queue.pop();
			BlockState state = getter.getBlockState(cur);
			if (state.getBlock() == TFBlocks.LOCKED_VANISHING_BLOCK.get() && state.getValue(LockedVanishingBlock.LOCKED)) {
				return true;
			}

			checked.add(cur);

			if (state.getBlock() instanceof VanishingBlock) {
				for (Direction facing : Direction.values()) {
					BlockPos neighbor = cur.relative(facing);
					if (!checked.contains(neighbor)) {
						queue.offer(neighbor);
					}
				}
			}
		}

		return false;
	}

@SubscribeEvent
	public static void onFlyableFall(PlayerFlyableFallEvent event) {
		EntityLivingBase entity = event.getEntityLiving();
		if (entity == null) return;

		if (!shouldBounce(entity)) return;

		INSTANCE.blocks.removeIf(bouncyBlock -> entity.world.getTotalWorldTime() - bouncyBlock.tickSpawned > bouncyBlock.expiry);

		boolean isClient = entity.getEntityWorld().isRemote;
		if (event.getDistance() > 0.5) {
			entity.fallDistance = 0;

			if (isClient) {
				entity.motionY *= -0.9;
				entity.isAirBorne = true;
				entity.onGround = false;
				double f = 0.95;
				entity.motionX /= f;
				entity.motionZ /= f;
				PacketHandler.NETWORK.sendToServer(new PacketBounce());
			}
			entity.playSound(SoundEvents.ENTITY_SLIME_SQUISH, 1f, 1f);
			BounceHandler.addBounceHandler(entity, entity.motionY);

		}
	}

public static void onMessageReceived(final TargetEffectMessageToClient message, Supplier<NetworkEvent.Context> ctxSupplier) {
    NetworkEvent.Context ctx = ctxSupplier.get();
    LogicalSide sideReceived = ctx.getDirection().getReceptionSide();
    ctx.setPacketHandled(true);

    if (sideReceived != LogicalSide.CLIENT) {
      LOGGER.warn("TargetEffectMessageToClient received on wrong side:" + ctx.getDirection().getReceptionSide());
      return;
    }
    if (!message.isMessageValid()) {
      LOGGER.warn("TargetEffectMessageToClient was invalid" + message.toString());
      return;
    }
    // we know for sure that this handler is only used on the client side, so it is ok to assume
    //  that the ctx handler is a client, and that Minecraft exists.
    // Packets received on the server side must be handled differently!  See MessageHandlerOnServer

    Optional<ClientWorld> clientWorld = LogicalSidedProvider.CLIENTWORLD.get(sideReceived);
    if (!clientWorld.isPresent()) {
      LOGGER.warn("TargetEffectMessageToClient context could not provide a ClientWorld.");
      return;
    }

    // This code creates a new task which will be executed by the client during the next tick
    //  In this case, the task is to call messageHandlerOnClient.processMessage(worldclient, message)
    ctx.enqueueWork(() -> processMessage(clientWorld.get(), message));
  }

public static void onMessageReceived(final AirstrikeMessageToServer message, Supplier<NetworkEvent.Context> ctxSupplier) {
    NetworkEvent.Context ctx = ctxSupplier.get();
    LogicalSide sideReceived = ctx.getDirection().getReceptionSide();
    ctx.setPacketHandled(true);

    if (sideReceived != LogicalSide.SERVER) {
      LOGGER.warn("AirstrikeMessageToServer received on wrong side:" + ctx.getDirection().getReceptionSide());
      return;
    }
    if (!message.isMessageValid()) {
      LOGGER.warn("AirstrikeMessageToServer was invalid" + message.toString());
      return;
    }

    // we know for sure that this handler is only used on the server side, so it is ok to assume
    //  that the ctx handler is a serverhandler, and that ServerPlayerEntity exists
    // Packets received on the client side must be handled differently!  See MessageHandlerOnClient

    final ServerPlayerEntity sendingPlayer = ctx.getSender();
    if (sendingPlayer == null) {
      LOGGER.warn("EntityPlayerMP was null when AirstrikeMessageToServer was received");
    }

    // This code creates a new task which will be executed by the server during the next tick,
    //  In this case, the task is to call messageHandlerOnServer.processMessage(message, sendingPlayer)
    ctx.enqueueWork(() -> processMessage(message, sendingPlayer));
  }

protected void customServerAiStep() {
		super.customServerAiStep();

		if (isUnderWater()) {
			AABB boundingBox = getBoundingBox();
			double width = boundingBox.maxX - boundingBox.minX;
			double depth = boundingBox.maxZ - boundingBox.minZ;
			double height = boundingBox.maxY - boundingBox.minY;
			int particleCount = (int)Math.ceil(3 + (10 * width * depth * height));
			TMEParticlePacket packet = new TMEParticlePacket(particleCount);

			for (int i = 0; i < particleCount; i++) {
				packet.particle(ParticleBuilder.forRandomPosInEntity(EntityTrackingParticleOptions.ambient(AoAParticleTypes.FREEZING_SNOWFLAKE), this)
						.lifespan(Mth.ceil(3 / (this.random.nextFloat() * 0.8f + 0.2f)))
						.scaleMod(0.3f)
						.velocity(RandomUtil.scaledGaussianValue(0.05d), 0, RandomUtil.scaledGaussianValue(0.05d)));
			}

			packet.sendToAllPlayersNearby((ServerLevel)level(), position(), 10);
			remove(RemovalReason.KILLED);
		}

		Entity target = getTarget();

		if (target != null && target.isFullyFrozen())
			lastAttackTime = tickCount;
	}

public static void checkLookingAtEnderOverseer(Player player) {
		Level level = player.level();
		long gameTime = level.getGameTime();
		if (Math.abs(gameTime - lastTickedGameTime) > 5) {
			// don't even bother if there are no loaded Ender Overseer blocks
			return;
		}
		if (!player.canBeSeenByAnyone()) {
			// exclude spectators and dead players
			return;
		}

		ItemStack helm = player.getItemBySlot(EquipmentSlot.HEAD);
		if (!helm.isEmpty() && helm.is(Blocks.CARVED_PUMPKIN.asItem())) {
			return;
		}

		Vec3 from = player.getEyePosition(1);
		Vec3 dir = player.getViewVector(1);
		Vec3 to = from.add(dir.scale(RANGE));
		BlockHitResult hit = level.clip(
				new ClipContext(from, to, ClipContext.Block.VISUAL, ClipContext.Fluid.NONE, player));
		if (hit.getType() == HitResult.Type.BLOCK
				&& level.getBlockEntity(hit.getBlockPos()) instanceof EnderOverseerBlockEntity enderOverseer) {
			enderOverseer.lookedAtGameTime = gameTime;
		}
	}

public void onCreatedFromSpell(Identifier spellId, Spell.Delivery.Cloud cloudData, SpellExecution.ImpactContext context, float time_to_live_seconds, Spell.Modifier.Cloud cloudModifier) {
        this.spellId = spellId;
        this.context = context;
        this.cloudModifier = cloudModifier;

        var spellEntry = getSpellEntry();
        if (spellEntry != null) {
            var spell = spellEntry.value();
            var index = 0;
            var dataList = spell.deliver.clouds;
            if (!dataList.isEmpty()) {
                index = dataList.indexOf(cloudData);
            }
            this.dataIndex = index;
        }
        this.getDataTracker().set(SPELL_ID_TRACKER, this.spellId.toString());
        this.getDataTracker().set(DATA_INDEX_TRACKER, this.dataIndex);
        this.getDataTracker().set(RADIUS_TRACKER, radiusForAge(this.age));

        // Carve the lifetime into spawning / active / despawning, like a summoned entity.
        // `time_to_live_seconds` is the ACTIVE duration; spawn/despawn bracket it.
        this.spawnDuration   = cloudData.spawn_ticks;
        this.despawnDuration = cloudData.despawn_ticks;
        int activeTicks      = (int) (time_to_live_seconds * 20);
        this.timeToLive      = this.spawnDuration + activeTicks + this.despawnDuration;
        this.impactCap = cloudData.impact_cap;
    }

@Override
    public boolean canStart() {
        int time = entity.getLastAttackedTime();
        if (time == lastAttackedTime) return false;
        LivingEntity attacker = entity.getAttacker();
        if (attacker == null) return false;
        this.attacker = attacker;
        LivingEntity owner = entity.getOwner();
        // Relation is resolved from the owner's perspective, so an ownerless summon (owner offline)
        // has no basis to classify its attacker and does not retaliate at all — matching how the
        // other target-selector goals behave without an owner.
        if (owner == null) return false;
        if (!entity.canAttackTarget(attacker, owner)) {
            // Friendly fire: consume the hit so canStart doesn't re-evaluate it every tick.
            lastAttackedTime = time;
            return false;
        }
        if (!canTrack(attacker, TargetPredicate.DEFAULT)) return false;
        LivingEntity currentTarget = entity.getTarget();
        if (currentTarget != null && currentTarget.isAlive()
                && entity.squaredDistanceTo(attacker) >= entity.squaredDistanceTo(currentTarget)) {
            // Attacker isn't closer — consume the hit so canStart doesn't re-fire every tick.
            lastAttackedTime = time;
            return false;
        }
        return true;
    }

@Override
    public void tick() {
        if (isOff)
            return;
        if (level.isClientSide && !isOff && ticksToConsume > 0 && !PotionUtil.isEmpty(lastConsumedPotion) && level.getGameTime() % 8 == 0) {
            level.addParticle(ParticleTypes.SMOKE, getX() + 0.5, getY() + 1, getZ() + 0.5, 0, 0, 0);
            return;
        }

        if (ticksToConsume <= 0 && boundPos != null && level.getGameTime() % 60 == 0) {
            obtainPotion();
        }
        if (ticksToConsume > 0) {
            ticksToConsume--;
            if (level.getGameTime() % (15 * 20) == 0) {
                for (LivingEntity entity : level.getEntitiesOfClass(LivingEntity.class, new AABB(getBlockPos()).inflate(10))) {
                    lastConsumedPotion.forEachEffect(effectinstance -> {
                        if (effectinstance.getEffect().value().isInstantenous()) {
                            effectinstance.getEffect().value().applyInstantenousEffect(null, null, entity, effectinstance.getAmplifier(), 1.0D);
                        } else {
                            entity.addEffect(new MobEffectInstance(effectinstance), null);
                        }
                    });
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (disabled)
            return;
        if (!level.isClientSide && level.getGameTime() % 20 == 0 && getSource() <= getMaxSource()) {
            List<ISpecialSourceProvider> takeList = SourceUtil.canTakeSource(getBlockPos(), level, 5);

            for (ISpecialSourceProvider provider : takeList) {
                if (this.getSource() >= getMaxSource()) {
                    break;
                }
                if (this.getToPos() != null && level.isLoaded(this.getToPos()) && level.getBlockEntity(this.getToPos()) == provider.getSource()) {
                    continue;
                }
                if (this.getFromPos() != null && level.isLoaded(this.getFromPos()) && level.getBlockEntity(this.getFromPos()) == provider.getSource()) {
                    continue;
                }

                int transferred = transferSource(provider.getSource(), this);
                if (transferred > 0) {
                    ParticleUtil.spawnFollowProjectile(level, provider.getCurrentPos(), this.worldPosition, this.getColor());
                }
            }

        }
    }

@Override
    public boolean stillValid(Player player) {
        if (this.storageController == null || this.stableWormhole == null)
            return false;

        Level level = this.stableWormhole.getLevel();
        BlockPos wormholePosition = this.stableWormhole.getBlockPos();

        //close container if wormhole block is destroyed
        if (level.getBlockEntity(wormholePosition) != this.stableWormhole)
            return false;

        //close container if storage controller block is destroyed
        if (BlockEntityUtil.get(level, this.stableWormhole.getLinkedStorageControllerPosition()) != this.storageController)
            return false;

        //send stack updates on a slow tick while interacting
        if (!level.isClientSide() && level.getGameTime() % 40 == 0) {
            Networking.sendTo((ServerPlayer) player, this.storageController.getMessageUpdateStacks());
            Networking.sendTo((ServerPlayer) player,
                    new MessageUpdateLinkedMachines(this.storageController.getLinkedMachines()));
        }

        //prevent player from interacting with the container if the controller is not in range
        return player.distanceToSqr(wormholePosition.getX() + 0.5D, wormholePosition.getY() + 0.5D,
                wormholePosition.getZ() + 0.5D) <= 64.0D;
    }

@Override
    public boolean canUse() {

        //fire on a slow tick based on chance
        long worldTime = this.mob.level().getGameTime() % 10;
        if (this.entity.getNoActionTime() >= 100 && worldTime != 0) {
            return false;
        }
        if (this.executionChance > 0 && this.entity.getRandom().nextInt(this.executionChance) != 0 && worldTime != 0) {
            return false;
        }

        //get work area, but only half height, we don't need full.
        int workAreaSize = this.entity.getWorkAreaSize().getValue();
        AABB targetBox = new AABB(-workAreaSize, -workAreaSize / 2.0, -workAreaSize, workAreaSize,
                workAreaSize / 2.0, workAreaSize).move(this.entity.getWorkAreaCenter());

        List<ItemEntity> list = this.mob.level()
                .getEntitiesOfClass(ItemEntity.class, targetBox, this.targetItemSelector);
        if (list.isEmpty()) {
            return false;
        } else {
            list.sort(this.entitySorter);
            this.targetItem = list.get(0);
            return true;
        }
    }

protected void doTick(ServerLevel level, E entity) {
        Brain<?> brain = entity.getBrain();

        var walkTarget = BrainUtil.getMemory(entity, OccultismMemoryTypes.LAST_CROP_WALK_TARGET.get());
        if (walkTarget == null) {
            this.resetState(brain);
        } else {
            Long unpathableTime = BrainUtil.getMemory(brain, MemoryModuleType.CANT_REACH_WALK_TARGET_SINCE);
            if (unpathableTime == null) {
                this.resetState(brain);
            } else {
                if (this.lastUnpathableTime == 0L) {
                    this.lastUnpathableTime = unpathableTime;
                } else if (this.lastUnpathableTime == unpathableTime) {
                    BrainUtil.clearMemory(brain, OccultismMemoryTypes.WALK_TARGET_UNREACHABLE.get());
                } else if (this.lastUnpathableTime < unpathableTime) {
                    this.lastUnpathableTime = unpathableTime;
                    BrainUtil.setMemory(brain, OccultismMemoryTypes.WALK_TARGET_UNREACHABLE.get(), walkTarget.getTarget().currentBlockPosition().getY() > entity.getEyeY());
                    BrainUtil.clearMemory(brain, OccultismMemoryTypes.LAST_CROP_WALK_TARGET.get());
                    if (Occultism.DEBUG.debugAI) {
                        Networking.sendToTracking(entity, new MessageSelectBlock(walkTarget.getTarget().currentBlockPosition(), 50000, Color.RED));
                    }
                }

            }
        }
    }

