@Override
    public void update() {
        super.update();

        this.currentChangeTicks++;
        if (!this.entity.swinging) {
            this.entity.swing(InteractionHand.MAIN_HAND);
        }
        if (this.entity.level().getGameTime() % 2 == 0) {
            ((ServerLevel) this.entity.level())
                    .sendParticles(ParticleTypes.SMOKE, this.entity.getX(),
                            this.entity.getY() + 0.5, this.entity.getZ(), 3,
                            0.5, 0.0, 0.0,
                            0.0);
        }

        if (this.currentChangeTicks == this.requiredChangeTicks.get()) {
            this.changeWeather();

            LightningBolt lightningboltentity = EntityType.LIGHTNING_BOLT.create(this.entity.level(), EntitySpawnReason.COMMAND);
            lightningboltentity.snapTo(Vec3.atBottomCenterOf(this.entity.blockPosition()));
            lightningboltentity.setVisualOnly(true);

            this.entity.die(this.entity.damageSources().lightningBolt());
            this.entity.remove(RemovalReason.DISCARDED);
        }
    }

@Inject(
		method = "keyPressed",
		at = @At("HEAD"),
		cancellable = true
	)
	private void bindJeiKeyboard(KeyEvent event, CallbackInfoReturnable<Boolean> cir) {
		if (selectedKey instanceof FabricKeyMapping mapping) {
			InputConstants.Key key = InputConstants.getKey(event);
			if (event.isEscape()) {
				key = InputConstants.UNKNOWN;
			}
			FabricKeyModifier modifier = FabricKeyModifier.forKey(event.key());
			var modifiers = FabricKeyModifier.fromMask(event.modifiers());
			if (modifier != null) {
				modifiers.remove(modifier);
			}
			mapping.setKeyAndModifiers(key, modifiers);
			if (modifier != null) {
				// Record a standalone modifier while waiting for a possible shortcut key.
				jei$pendingModifier = key;
				keyBindsList.resetMappingAndUpdateButtons();
			} else {
				jei$finishBinding();
			}
			cir.setReturnValue(true);
		}
	}

