private static void drawBeams(double distance, CorruptedBeam entity, float ticks, float speedModifier, PoseStack pMatrixStack) {
        long gameTime = entity.level.getGameTime();
        double velocity = gameTime * speedModifier;
        float additiveThickness = (entity.getBeamWidth() * 1.75f) * calculateLaserFlickerModifier(gameTime);

        float yRot = -Mth.rotLerp(ticks, entity.yRotO, entity.getYRot());
        float xRot = Mth.rotLerp(ticks, entity.xRotO, entity.getXRot());
        Vec3 offset = Vec3.ZERO;
        Optional<LivingEntity> optionalOwner = entity.getOptionalOwner();
        if (optionalOwner.isPresent()) {
            LivingEntity owner = optionalOwner.get();
            yRot = -Mth.rotLerp(ticks, owner.yRotO, owner.getYRot());
            xRot = Mth.rotLerp(ticks, owner.xRotO, owner.getXRot());
            offset = new Vec3(
                    Mth.lerp(ticks, owner.xo, owner.getX()) - Mth.lerp(ticks, entity.xo, entity.getX()),
                    Mth.lerp(ticks, owner.yo, owner.getY()) - Mth.lerp(ticks, entity.yo, entity.getY()),
                    Mth.lerp(ticks, owner.zo, owner.getZ()) - Mth.lerp(ticks, entity.zo, entity.getZ())
            ).add(entity.getOffsetVector(owner, ticks));
        }

        pMatrixStack.pushPose();
        pMatrixStack.translate(offset.x, offset.y, offset.z);
        pMatrixStack.mulPose(Axis.YP.rotationDegrees(yRot));
        pMatrixStack.mulPose(Axis.XP.rotationDegrees(xRot));
        PoseStack.Pose matrixstack$entry = pMatrixStack.last();
        QUEUE.add(new QueuedBeam(new Matrix4f(matrixstack$entry.pose()), new Matrix3f(matrixstack$entry.normal()), distance, entity.getBeamWidth(), additiveThickness, velocity, ticks));
        pMatrixStack.popPose();
    }

public static void clientTick(Level level, BlockPos pos, BlockState state, SarcophagusBlockEntity blockEntity) {
        boolean occupied = state.getValue(SarcophagusBlock.OCCUPIED);

        if (blockEntity.closingStartTick > 0) {
            --blockEntity.closingStartTick;
        }

        if (occupied != blockEntity.wasOccupied) {
            if (occupied) {
                blockEntity.closingState.start((int) level.getGameTime());
                blockEntity.playSound(ModSounds.STONE_DRAG.get(), level.getRandom().nextFloat() * 0.25F + 0.75F);
                blockEntity.closingStartTick = 20;
                blockEntity.openingState.stop();
                blockEntity.closedState.stop();
            } else {
                blockEntity.closedState.stop();
                blockEntity.openingState.start((int) level.getGameTime());
                blockEntity.playSound(ModSounds.STONE_DRAG.get(), level.getRandom().nextFloat() * 0.25F + 0.75F);
                blockEntity.closingState.stop();
            }
            blockEntity.wasOccupied = occupied;
        }

        if (occupied && blockEntity.closingStartTick <= 0) {
            blockEntity.closingState.stop();
            blockEntity.closedState.start((int) level.getGameTime());
        }
    }

@SuppressWarnings("deprecation")
  @Deprecated
  @Override
  public BlockState updateShape(BlockState state, Direction facing, BlockState facingState, LevelAccessor world, BlockPos pos, BlockPos facingPos) {
    if (state.getValue(WATERLOGGED)) {
      world.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(world));
    }

    // break if now invalid
    Direction direction = state.getValue(FACING);
    if (facing == direction && !state.canSurvive(world, pos)) {
      return Blocks.AIR.defaultBlockState();
    }

    // apply north and east if relevant
    Direction north = getLocalNorth(direction);
    Direction east = getLocalEast(direction);
    if (facing == north) {
      state = state.setValue(NORTH, isConnected(world, direction, facingPos));
    } else if (facing == east) {
      state = state.setValue(EAST, isConnected(world, direction, facingPos));
    }

    // always update northeast and northwest, never gets direct updates
    BlockPos northPos = pos.relative(north);
    return state.setValue(NORTHEAST, isConnected(world, direction, northPos.relative(east)))
                .setValue(NORTHWEST, isConnected(world, direction, northPos.relative(east.getOpposite())));
  }

