@Override
    public void tickServer() {
        super.tickServer();

        if (getPressure() >= PneumaticValues.MIN_PRESSURE_PNEUMATIC_DOOR) {
            if ((nonNullLevel().getGameTime() & 0x3f) == 0) {
                BlockEntity te = nonNullLevel().getBlockEntity(getBlockPos().relative(getRotation(), 3));
                if (te instanceof PneumaticDoorBaseBlockEntity) {
                    doubleDoor = (PneumaticDoorBaseBlockEntity) te;
                } else {
                    doubleDoor = null;
                }
            }
            setOpening(shouldOpen() || isNeighborOpening());
            setNeighborOpening(isOpening());
        } else {
            setOpening(true);
        }
        speedMultiplier = getSpeedMultiplierFromUpgrades();

        if (!PneumaticCraftUtils.epsilonEquals(oldProgress, progress)) {
            addAir((int) (-Math.abs(oldProgress - progress) * PneumaticValues.USAGE_PNEUMATIC_DOOR * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
        }

        if (door != null) {
            rightGoing = door.rightGoing;
        }
    }

@Override
	public void tick(BlockState state, ServerLevel level, BlockPos pos, RandomSource random) {
		if (this.isVanished(state)) {
			if (state.getValue(ACTIVE)) {
				level.setBlockAndUpdate(pos, state.setValue(VANISHED, false).setValue(ACTIVE, false));
				level.playSound(null, pos, TFSounds.REAPPEAR_BLOCK.get(), SoundSource.BLOCKS, 0.3F, 0.3F);
			} else {
				level.playSound(null, pos, TFSounds.REAPPEAR_POOF.get(), SoundSource.BLOCKS, 0.3F, 0.5F);
				level.setBlockAndUpdate(pos, state.setValue(ACTIVE, true));
				level.scheduleTick(pos, this, 15);
			}
		} else {
			if (state.getValue(ACTIVE)) {
				if (state.hasProperty(VANISHED)) {
					level.setBlockAndUpdate(pos, state.setValue(ACTIVE, false).setValue(VANISHED, true));
					level.scheduleTick(pos, this, 80);
				} else {
					level.removeBlock(pos, false);
				}

				level.playSound(null, pos, state.getBlock() == TFBlocks.REAPPEARING_BLOCK.get() ? TFSounds.REAPPEAR_POOF.get() : TFSounds.VANISHING_BLOCK.get(), SoundSource.BLOCKS, 0.3F, 0.5F);

				for (Direction e : Direction.values()) {
					this.activate(level, pos.relative(e));
				}
			}
		}
	}

@Override
	public void extractRenderState(OminousCandleBlockEntity blockEntity, OminousCandleRenderState state, float partialTicks, Vec3 cameraPosition, ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
		BlockEntityRenderer.super.extractRenderState(blockEntity, state, partialTicks, cameraPosition, breakProgress);
		if (blockEntity.getLevel() != null) {
			state.time = blockEntity.getLevel().getGameTime();
		}

		int candles = blockEntity.getBlockState().getValue(OminousCandleBlock.CANDLES);

		List<Vec2> vec2s = OminousCandleBlock.CANDLE_OFFSETS.get(candles);

		List<Vec3> offsets = new ArrayList<>();
		List<BlockModelRenderState> candleModels = new ArrayList<>();

		for (int i = 0; i < candles; i++) {
			double targetHeight = OminousCandleBlock.getCurrentY(state.time, partialTicks, blockEntity.getBlockPos(), i + 1);
			double yHeight = this.exponentialDecay(blockEntity.getVisualHeight(i), targetHeight, 0.05, partialTicks);
			offsets.add(new Vec3(-vec2s.get(i).x, yHeight, -vec2s.get(i).y));
			blockEntity.setVisualHeightScalar(yHeight, i);
			BlockModelRenderState modelState = new BlockModelRenderState();
			BlockState candle = (blockEntity.getBlockState().getBlock() instanceof OminousCandleBlock candleBlock ? candleBlock.candle : Blocks.CANDLE).defaultBlockState().setValue(CandleBlock.LIT, true);
			this.blockRenderer.update(modelState, candle, BlockDisplayContext.create());
			candleModels.add(modelState);
		}

		state.offsets = offsets;
		state.candles = candleModels;
	}

@Override
	protected void placeBlock(WorldGenLevel worldIn, BlockState blockstateIn, int x, int y, int z, BoundingBox boundingboxIn) {
		BlockPos blockpos = new BlockPos(this.getWorldX(x, z), this.getWorldY(y), this.getWorldZ(x, z));
		if (blockstateIn == null) {
			TwilightForestMod.LOGGER.warn("TFStructureComponent: Block at Pos {} {} {} was null! Ignoring!", blockpos.getX(), blockpos.getY(), blockpos.getZ());
		}

		if (boundingboxIn.isInside(blockpos)) {
			if (this.mirror != Mirror.NONE) {
				blockstateIn = blockstateIn.mirror(this.mirror);
			}

			if (this.rotation != Rotation.NONE) {
				blockstateIn = blockstateIn.rotate(this.rotation);
			}

			worldIn.setBlock(blockpos, blockstateIn, Block.UPDATE_CLIENTS);
			FluidState fluidstate = worldIn.getFluidState(blockpos);
			if (!fluidstate.isEmpty()) {
				worldIn.scheduleTick(blockpos, fluidstate.getType(), 0);
			}

			if (BLOCKS_NEEDING_POSTPROCESSING.get().contains(blockstateIn.getBlock())) {
				worldIn.getChunk(blockpos).markPosForPostprocessing(blockpos);
			}

		}
	}

@Nullable
		@Override
		@SideOnly(Side.CLIENT)
		default Function2<ItemStack, Integer, Integer> getItemColorFunction() {
			return (stack, tintIndex) -> {
				if (tintIndex != 0) return 0xFFFFFF;
				if (!stack.hasTagCompound())
					return Color.HSBtoRGB(MathHelper.sin(Minecraft.getMinecraft().world.getTotalWorldTime() / 140f), 0.75f, 1f);

				long lastCast = NBTHelper.getLong(stack, NBT.LAST_CAST, -1);
				int decayCooldown = NBTHelper.getInt(stack, NBT.LAST_COOLDOWN, -1);
				long tick = Minecraft.getMinecraft().world.getTotalWorldTime();
				long timeSinceCooldown = tick - lastCast;
				float decayStage = (decayCooldown > 0) ? ((float) timeSinceCooldown) / decayCooldown : 1f;


				float rand = NBTHelper.getFloat(stack, NBT.RAND, -1);
				float hue = rand < 0 ? (tick / 140f) % 140f : rand;
				float pow = Math.min(1f, Math.max(0f, getQuality(stack)));

				double decaySaturation = (lastCast == -1 || decayCooldown <= 0 || decayStage >= 1f) ? 1f :
						(decayStage < decayCurveDelimiter) ? Math.pow(Math.E, -15 * decayStage) : Math.pow(Math.E, 3 * decayStage - 3);

				float saturation = curveConst * (1 - (float) Math.pow(Math.E, -pow)) * (float) decaySaturation;

				return Color.HSBtoRGB(hue, saturation, 1f);
			};
		}

protected boolean doBlockDestruction(BlockHitResult rayTrace, BlockState block) {
        if (AoAGameRules.checkDestructiveWeaponPhysics(level())) {
            BlockPos blockPos = rayTrace.getBlockPos();
            float hardness = block.getDestroySpeed(level(), blockPos);

            if (hardness < 0)
                return false;

            float penetrationMod = 0.3f * Math.max(getBbWidth(), getBbHeight()) / 0.25f;

            if (hardness <= penetrationMod) {
                if (!level().isClientSide) {
                    if (this.random.nextBoolean()) {
                        level().destroyBlock(blockPos, true);
                    }
                    else {
                        level().setBlockAndUpdate(blockPos, Blocks.AIR.defaultBlockState());
                    }
                }

                this.random.setSeed((long)Math.pow(getId(), Math.pow(block.getSeed(blockPos), (level().getGameTime() / 3f))));

                return this.random.nextFloat() > hardness / ((1.5f * 0.3f) / penetrationMod);
            }
        }

        return false;
    }

