                    renderBeaconBeam(matrixStackIn, bufferIn, partialTicks, i, j, 10);
                }
            }

        }
    }

private void commonSetup(FMLCommonSetupEvent event) {
        event.enqueueWork(() -> {
            //Dispenser behavior
            DispenserBlock.registerBehavior(AdditionsBlocks.OBSIDIAN_TNT, new OptionalDispenseItemBehavior() {
                @Override
                protected ItemStack execute(BlockSource source, ItemStack dispensed) {
                    //Based heavily on vanilla's tnt dispense behavior
                    ServerLevel level = source.level();
                    if (!level.getGameRules().get(GameRules.TNT_EXPLODES)) {
                        setSuccess(false);
                        return dispensed;
                    }
                    BlockPos target = source.pos().relative(source.state().getValue(DispenserBlock.FACING));
                    if (SulfurCubeBlockDispenseItemBehavior.dispenseBlock(level, target, dispensed)) {
                        return dispensed;
                    }
                    if (BlockObsidianTNT.createAndAddEntity(source.level(), target, null)) {
                        level.gameEvent(null, GameEvent.ENTITY_PLACE, target);
                        dispensed.shrink(1);
                        setSuccess(true);
                    }
                    return dispensed;
                }
            });
            EnumColorCollection.zipApply(EnumColorCollection.VALUES, AdditionsItems.BALLOONS, (color, balloon) -> DispenserBlock.registerBehavior(balloon, new ItemBalloon.DispenserBehavior(color)));
        });
        Mekanism.logger.info("Loaded 'Mekanism: Additions' module.");
    }

public static <LEVEL extends BlockGetter, NODE extends @Nullable Object> int explore(LEVEL level, Long2ObjectMap<ChunkAccess> chunkMap, BlockPos start, NODE node,
          FormationChecker<LEVEL, NODE> checker, int maxCount) {
        if (!checker.check(level, chunkMap, start, node, start)) {
            return 0;
        }

        BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos();
        Queue<BlockPos> openSet = new LinkedList<>();
        Set<BlockPos> traversed = new ObjectOpenHashSet<>();
        openSet.add(start);
        traversed.add(start);
        while (!openSet.isEmpty()) {
            BlockPos ptr = openSet.poll();
            int traversedSize = traversed.size();
            if (traversedSize >= maxCount) {
                return traversedSize;
            }
            for (Direction side : EnumUtils.DIRECTIONS) {
                mutable.setWithOffset(ptr, side);
                if (!traversed.contains(mutable) && checker.check(level, chunkMap, start, node, mutable)) {
                    BlockPos offset = mutable.immutable();
                    openSet.add(offset);
                    traversed.add(offset);
                }
            }
        }
        return traversed.size();
    }

public static void sendToAllTracking(DynamicBufferedNetwork<?, ?, ?, ?> network, CustomPacketPayload... packets) {
        Range3D range = network.getPacketRange();
        if (range == null) {
            return;
        }
        //TODO: Create a method in DynamicNetwork to get all players that are "tracking" the network
        // Also evaluate moving various network packet things over to using this at that point
        //TODO - 1.20.4: If we just make the packet range instead keep track of the ChunkPositions that then we check if the player is tracking
        // it will allow us to have it hopefully work a bit more accurately and more cleanly?
        // and that way we can do a check that the player is tracking one of the chunks maybe instead of doing the weird radius check
        PlayerList playerList = ServerLifecycleHooks.getCurrentServer().getPlayerList();
        Packet<?> packet = makeClientboundPacket(packets);
        //Ignore height for partial Cubic chunks support as range comparison gets used ignoring player height normally anyway
        int radius = playerList.getViewDistance() * 16;
        for (ServerPlayer player : playerList.getPlayers()) {
            if (range.dimension() == player.level().dimension()) {
                //TODO - 1.20.4: Should this use proper position instead of the block position (if we switch to tracked chunks then this becomes irrelevant)
                BlockPos playerPosition = player.blockPosition();
                int playerX = playerPosition.getX();
                int playerZ = playerPosition.getZ();
                //playerX/Z + radius is the max, so to stay in line with how it was before, it has an extra + 1 added to it
                if (playerX + radius + 1.99999 > range.xMin() && range.xMax() + 0.99999 > playerX - radius &&
                    playerZ + radius + 1.99999 > range.zMin() && range.zMax() + 0.99999 > playerZ - radius) {
                    player.connection.send(packet);
                }
            }
        }
    }

@Test
	public void testShutdownRunsScheduledCommandsOnExecutorThread() {
		// Setup: a delayed command records the thread used when shutdown flushes it.
		Thread shutdownThread = Thread.currentThread();
		AtomicReference<@Nullable Thread> commandThread = new AtomicReference<>();
		ScheduledThreadPoolExecutor service = new ScheduledThreadPoolExecutor(
			1,
			runnable -> new Thread(runnable, "delayed-executor-test")
		);
		service.setRemoveOnCancelPolicy(true);
		service.setExecuteExistingDelayedTasksAfterShutdownPolicy(false);
		DelayedExecutor executor = new DelayedExecutor(SHUTDOWN_TIMEOUT, service);

		try {
			executor.schedule(() -> commandThread.set(Thread.currentThread()), LONG_DELAY);

			// Operation: shut down before the original delay expires.
			executor.shutdown();

			// Assertions: shutdown flushes the command through the executor, not on the shutdown caller thread.
			Thread thread = commandThread.get();
			Assertions.assertNotNull(thread, "Shutdown should run the tracked delayed command.");
			Assertions.assertNotSame(shutdownThread, thread, "Shutdown should not run delayed commands on the caller thread.");
			Assertions.assertEquals("delayed-executor-test", thread.getName(), "Shutdown should run delayed commands on the executor thread.");
		} finally {
			service.shutdownNow();
		}
	}

public static void handle(PacketFlameParticles msg, Supplier<NetworkEvent.Context> ctx) {
		if (AstralBreaker.flameParticlesToggle.getValue()) {
			ctx.get().enqueueWork(() -> {
				LocalPlayer player = Minecraft.getInstance().player;

				int amount = msg.num;
				float modifier = 1.0F;

				if (msg.check) {
					if (Minecraft.getInstance().options.particles().get() == ParticleStatus.MINIMAL) {
						modifier = 0.10F;
					} else if (Minecraft.getInstance().options.particles().get() == ParticleStatus.DECREASED) {
						modifier = 0.25F;
					} else {
						modifier = 0.35F;
					}
				}

				amount *= modifier;

				for (int counter = 0; counter <= amount; counter++) {
					player.level().addParticle(ParticleTypes.FLAME, true, msg.x + (Math.random() - 0.5), msg.y + (Math.random() - 0.5), msg.z + (Math.random() - 0.5), (Math.random() - 0.5D) * 0.1D, (Math.random() - 0.5D) * 0.1D, (Math.random() - 0.5D) * 0.1D);
				}

			});

			ctx.get().setPacketHandled(true);
		}
	}

