		inputs.add(EntryIngredients.of(TFREIClientPlugin.BLOCKSTATE_DEFINITION, List.of(TFBlocks.OMINOUS_FIRE.get().defaultBlockState())));

		getEntity(recipe.output(), Minecraft.getInstance().level).ifPresent(entity -> {
