public BlockState updatePostPlacement(BlockState thisBlockState, Direction directionFromThisToNeighbor, BlockState neighborState,
                                        IWorld world, BlockPos thisBlockPos, BlockPos neighborBlockPos) {
    if(thisBlockState.get(WATERLOGGED).booleanValue()) {
      world.getPendingFluidTicks().scheduleTick(thisBlockPos, Fluids.WATER, Fluids.WATER.getTickRate(world));
    }
    switch (directionFromThisToNeighbor) {  // Only update the specified direction.  Uses a switch for clarity but probably a map or similar is better for real code
      case UP:
        thisBlockState = thisBlockState.with(UP, canWebAttachToNeighbourInThisDirection(world, thisBlockPos, directionFromThisToNeighbor));
        break;
      case DOWN:
        thisBlockState = thisBlockState.with(DOWN, canWebAttachToNeighbourInThisDirection(world, thisBlockPos, directionFromThisToNeighbor));
        break;
      case EAST:
        thisBlockState = thisBlockState.with(EAST, canWebAttachToNeighbourInThisDirection(world, thisBlockPos, directionFromThisToNeighbor));
        break;
      case WEST:
        thisBlockState = thisBlockState.with(WEST, canWebAttachToNeighbourInThisDirection(world, thisBlockPos, directionFromThisToNeighbor));
        break;
      case NORTH:
        thisBlockState = thisBlockState.with(NORTH, canWebAttachToNeighbourInThisDirection(world, thisBlockPos, directionFromThisToNeighbor));
        break;
      case SOUTH:
        thisBlockState = thisBlockState.with(SOUTH, canWebAttachToNeighbourInThisDirection(world, thisBlockPos, directionFromThisToNeighbor));
        break;
      default:
        LOGGER.error("Unexpected facing:" + directionFromThisToNeighbor);
    }
    return thisBlockState;
  }

protected void checkAndPerformAttack(LivingEntity target, double sqrDistToTarget) {
		int animState = this.entity.getAnimationState(animKey);
		boolean withinReach = sqrDistToTarget <= getAttackReachSqr(target);

		if (animState > 0 && attackCooldown > 0)
			this.entity.setAnimationState(animKey, 0);

		if (withinReach || (animState > 0 && !this.stopAttackIfOutOfRange)) {
			if (attackCooldown <= 0) {
				this.attackCooldown = this.attackInterval;
				this.entity.swing(Hand.MAIN_HAND);
				this.entity.setAnimationState(animKey, 1);

				this.attackDamageTick = this.entity.level.getGameTime() + this.preAttackTime;
			}

			if (this.attackDamageTick >= 0 && this.entity.level.getGameTime() >= attackDamageTick) {
				if (withinReach)
					this.entity.doHurtTarget(target);

				this.entity.setAnimationState(animKey, 2);

				this.attackDamageTick = -1;
			}
		}
		else {
			this.attackDamageTick = -1;
		}
	}

@Override
	public void run() {
		try (Connection connection = DriverManager.getConnection(SkillsLeaderboard.getConnectionPath(), properties)) {
			if (!initialized && this instanceof InsertionConnection insertionConnection) {
				new InitializeLeaderboardTask().execute(connection, insertionConnection);
				initialized = true;
			}

			prepareStatements(connection);

			do {
				try {
					LeaderboardTask<LeaderboardConnection> task = queue.take();

					task.execute(connection, this);
				}
				catch (InterruptedException ex) {
					Logging.logMessage(Level.ERROR, "Attempted to perform operation while thread is interrupted. This shouldn't happen. Skipping task.", ex);
				}
			}
			while (SkillsLeaderboard.isEnabled() || !queue.isEmpty());

			closeStatements();
			connection.commit();
		}
		catch (SQLException ex) {
			Logging.logMessage(Level.ERROR, "Error connecting to leaderboard database, dropping thread.", ex);
		}
	}

