private void Icicle_Crash() {

        if (this.level().getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
            BlockPos ceil = this.blockPosition().offset(0, 5, 0);
            while ((!level().getBlockState(ceil).isSolid() || level().getBlockState(ceil).getBlock() == ModBlocks.POINTED_ICICLE.get()) && ceil.getY() < level().getMaxBuildHeight()) {
                ceil = ceil.above();
            }
            final int i = 8;
            final int j = 8;
            final int k = 8;

            for (BlockPos blockpos1 : BlockPos.betweenClosed(ceil.offset(-i, -j, -k), ceil.offset(i, j, k))) {
                if (level().getBlockState(blockpos1).getBlock() instanceof Fallable) {
                    if (isHangingIcicle(blockpos1)) {
                        while (isHangingIcicle(blockpos1.above()) && blockpos1.getY() < level().getMaxBuildHeight()) {
                            blockpos1 = blockpos1.above();
                        }
                        if (isHangingIcicle(blockpos1)) {
                            Vec3 vec3 = Vec3.atBottomCenterOf(blockpos1);
                            FallingBlockEntity.fall(level(), BlockPos.containing(vec3.x, vec3.y, vec3.z), level().getBlockState(blockpos1));
                        }
                    } else {
                        this.level().scheduleTick(blockpos1, level().getBlockState(blockpos1).getBlock(), 2);
                    }
                }
            }
        }

    }

public List<BoltRenderState> collectBoltStates(long gameTime, float partialTicks) {
        List<BoltRenderState> renderStates = new ArrayList<>();
        Timestamp timestamp = new Timestamp(gameTime, partialTicks);
        boolean refresh = timestamp.isPassed(refreshTimestamp, 1 / REFRESH_TIME);
        if (refresh) {
            refreshTimestamp = timestamp;
        }
        synchronized (boltOwners) {
            for (Iterator<Map.Entry<Object, BoltOwnerData>> iter = boltOwners.entrySet().iterator(); iter.hasNext(); ) {
                Map.Entry<Object, BoltOwnerData> entry = iter.next();
                BoltOwnerData data = entry.getValue();
                // tick our bolts based on the refresh rate, removing if they're now finished
                if (refresh) {
                    tickAndRemove(data, timestamp);
                }
                if (data.bolts.isEmpty() && data.lastBolt != null && data.lastBolt.getSpawnFunction().isConsecutive()) {
                    data.addBolt(new BoltInstance(data.lastBolt, timestamp), timestamp, random);
                }
                for (BoltInstance bolt : data.bolts) {
                    renderStates.add(bolt.renderState(timestamp));
                }

                if (data.bolts.isEmpty() && timestamp.isPassed(data.lastUpdateTimestamp, MAX_OWNER_TRACK_TIME)) {
                    iter.remove();
                }
            }
        }
        return renderStates;
    }

@Test
	public void replacesAllKeysWithoutResurrectingRemovedOrPendingEntries() {
		LuceneSearchStorageBuilder<Object> builder = new LuceneSearchStorageBuilder<>();
		Object crystal = new Object();
		Object other = new Object();
		builder.put("mysterious crystal", crystal);
		builder.put("undiscovered aspect", crystal);
		builder.put("other crystal", other);
		ISearchStorage<Object> storage = builder.build();
		for (int batch = 0; batch < 30; batch++) {
			storage.put("pending obsolete name", crystal);
			Assertions.assertTrue(storage.removeAll(List.of(crystal, crystal, new Object())));
			Assertions.assertEquals(Set.of(other), allElements(storage));
			storage.put("discarded replacement", crystal);
			Assertions.assertTrue(storage.removeAll(List.of(crystal)));
			storage.put("discovered aspect " + batch, crystal);
			Assertions.assertEquals(Set.of(crystal), search(storage, "discovered aspect " + batch));
			Assertions.assertEquals(Set.of(other), search(storage, "crystal"));
			Assertions.assertTrue(search(storage, "undiscovered").isEmpty());
			Assertions.assertTrue(search(storage, "pending").isEmpty());
			Assertions.assertTrue(search(storage, "discarded").isEmpty());
			Assertions.assertEquals(Set.of(crystal, other), allElements(storage));
		}
		Assertions.assertTrue(storage.removeAll(List.of(crystal, other)));
		Assertions.assertTrue(search(storage, "aspect").isEmpty());
		Assertions.assertTrue(allElements(storage).isEmpty());
		storage.put("new crystal", other);
		Assertions.assertEquals(Set.of(other), search(storage, "crystal"));
	}

public void render(GuiGraphics graphics, int x, int y, float delta) {
        long totalTimeStart = debugTime ? System.nanoTime() : 0;
        Minecraft minecraft = Minecraft.getInstance();
        Font font = minecraft.font;

        if (debugTime) {
            long totalTime = System.nanoTime() - totalTimeStart;
            averageDebugTime += (time.getValue() / size.doubleValue()) * delta;
            totalDebugTime += totalTime / 1000000d * delta;
            totalDebugTimeDelta += delta;
            if (totalDebugTimeDelta >= 20) {
                lastAverageDebugTime = averageDebugTime / totalDebugTimeDelta;
                lastTotalDebugTime = totalDebugTime / totalDebugTimeDelta;
                averageDebugTime = 0;
                totalDebugTime = 0;
                totalDebugTimeDelta = 0;
            } else if (lastAverageDebugTime == 0) {
                lastAverageDebugTime = time.getValue() / size.doubleValue();
                totalDebugTime = totalTime / 1000000d;
            }
            Component debugText = Component.literal(String.format("%d entries, avg. %.0fns, ttl. %.2fms, %s fps", size.getValue(), lastAverageDebugTime, lastTotalDebugTime, minecraft.getFps()));
            int stringWidth = font.width(debugText);
            graphics.fillGradient(Math.min(x, minecraft.gui.screen().width - stringWidth - 2), y, x + stringWidth + 2, y + font.lineHeight + 2, -16777216, -16777216);
            graphics.drawString(font, debugText, Math.min(x + 2, minecraft.gui.screen().width - stringWidth), y + 2, -1, false);
        }

        this.size.setValue(0);
        this.time.setValue(0);
    }

public EnumPaleoPages[] randomizePages(ItemStack paleopedia, ItemStack manuscript) {
        if (!level.isClientSide) {
            if (paleopedia.getItem() == PFItems.PALEOPEDIA.get()) {
                List<EnumPaleoPages> possibleList = getPossiblePages();
                localRand.setSeed(this.level.getGameTime());
                Collections.shuffle(possibleList, localRand);
                if (!possibleList.isEmpty()) {
                    selectedPages[0] = possibleList.get(0);
                } else {
                    selectedPages[0] = null;
                }
                if (possibleList.size() > 1) {
                    selectedPages[1] = possibleList.get(1);
                } else {
                    selectedPages[1] = null;
                }
                if (possibleList.size() > 2) {
                    selectedPages[2] = possibleList.get(2);
                } else {
                    selectedPages[2] = null;
                }
            }
            int page1 = selectedPages[0] == null ? -1 : selectedPages[0].ordinal();
            int page2 = selectedPages[1] == null ? -1 : selectedPages[1].ordinal();
            int page3 = selectedPages[2] == null ? -1 : selectedPages[2].ordinal();
            PrehistoricFauna.sendMSGToAll(new MessageUpdatePaleoscribe(worldPosition.asLong(), page1, page2, page3, false, 0));
        }
        return selectedPages;
    }

