@Override
    public boolean canUse() {
        if (this.pixie.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() || this.pixie.isTame()) {
            list = Collections.emptyList();
            return false;
        }

        if (this.pixie.level.getGameTime() % 4 == 0) // only update the list every 4 ticks
            list = this.pixie.level.getEntitiesOfClass(this.classToAvoid, this.pixie.getBoundingBox().inflate(this.avoidDistance, 3.0D, this.avoidDistance), EntitySelector.NO_SPECTATORS);

        if (list.isEmpty())
            return false;

        this.closestLivingEntity = list.get(0);
        if (closestLivingEntity != null) {
            Vec3 Vector3d = DefaultRandomPos.getPosAway(this.pixie, 16, 4, new Vec3(this.closestLivingEntity.getX(), this.closestLivingEntity.getY(), this.closestLivingEntity.getZ()));

            if (Vector3d == null) {
                return false;
            } else {
                Vector3d = Vector3d.add(0, 1, 0);
                this.pixie.getMoveControl().setWantedPosition(Vector3d.x, Vector3d.y, Vector3d.z, calculateRunSpeed());
                this.pixie.getLookControl().setLookAt(Vector3d.x, Vector3d.y, Vector3d.z, 180.0F, 20.0F);
                hidePlace = Vector3d;
                pixie.slowSpeed = true;
                return true;
            }
        }
        return false;
    }

public static void handle(MessageStartRidingMob message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            Player player = context.get().getSender();
            if(context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT){
                player = IceAndFire.PROXY.getClientSidePlayer();
            }
            if (player != null) {
                if (player.level != null) {
                    Entity entity = player.level.getEntity(message.dragonId);
                    if (entity != null && entity instanceof ISyncMount && entity instanceof TamableAnimal) {
                        TamableAnimal dragon = (TamableAnimal) entity;
                        if (dragon.isOwnedBy(player) && dragon.distanceTo(player) < 14) {
                            if (message.ride) {
                                if (message.baby) {
                                    dragon.startRiding(player, true);
                                } else {
                                    player.startRiding(dragon, true);
                                }
                            } else {
                                if (message.baby) {
                                    dragon.stopRiding();
                                } else {
                                    player.stopRiding();
                                }
                            }
                        }
                    }
                }
            }
        }

public static void jobStatus(UUID id,
            AEKey what,
            long requestedAmount,
            long remainingAmount,
            CraftingJobStatusPacket.Status status) {

        AELog.debug("Crafting job " + id + " for " + requestedAmount
                + "x" + what.getDisplayName().getString() + ". State=" + status);

        var existing = jobs.get(id);
        switch (status) {
            case STARTED -> {
                if (existing == null) {
                    jobs.put(id, new PendingJob(id, what, requestedAmount, remainingAmount));
                }
            }
            case CANCELLED -> jobs.remove(id);
            case FINISHED -> {
                jobs.remove(id);
                // Only toast if no terminal is open (i.e. REI/JEI or no screen at all)
                // and a wireless terminal is in the player inv
                var minecraft = Minecraft.getInstance();
                if (AEConfig.instance().isNotifyForFinishedCraftingJobs()
                        && !(minecraft.gui.screen() instanceof MEStorageScreen<?>)
                        && minecraft.player != null && hasNotificationEnablingItem(minecraft.player)) {
                    minecraft.gui.toastManager().addToast(new FinishedJobToast(what, requestedAmount));
                }
            }
        }
    }

@Override
    public boolean alertDevice(IGridNode node) {
        Objects.requireNonNull(node);

        // Avoid corrupting the tick queue if the node is already ticking at this time
        // The result of its ticking method will take precedence over this call
        if (node == currentlyTicking) {
            return false;
        }

        var tt = this.alertable.get(node);
        if (tt == null) {
            if (this.sleeping.containsKey(node) || this.awake.containsKey(node)) {
                throw new IllegalArgumentException("Trying to alert a node that isn't alertable");
            }
            return false;
        }

        // set to awake, this is for sanity.
        this.sleeping.remove(node);
        this.awake.put(node, tt);

        // configure sort.
        tt.setTickOnNextTick();

        // prevent dupes and tick build up.
        this.updateQueuePosition(node, tt);

        return true;
    }

public static void openWithCraftingList(@Nullable IActionHost terminal, ServerPlayer player,
            @Nullable MenuHostLocator locator, List<ICraftingGridMenu.AutoCraftEntry> stacksToCraft) {
        if (terminal == null || locator == null || stacksToCraft.isEmpty()) {
            return;
        }

        var firstToCraft = stacksToCraft.get(0);
        var subsequentCrafts = stacksToCraft.subList(1, stacksToCraft.size());

        try {
            MenuOpener.open(CraftConfirmMenu.TYPE, player, locator);

            if (player.containerMenu instanceof CraftConfirmMenu ccc) {
                if (!ccc.planJob(
                        firstToCraft.what(),
                        firstToCraft.slots().size(),
                        // Use CRAFT_LESS to still try to partially craft the ingredients.
                        CalculationStrategy.CRAFT_LESS)) {
                    ccc.setValidMenu(false);
                    return;
                }

                ccc.autoCraftingQueue = subsequentCrafts;
                ccc.requestedSlots = firstToCraft.slots();
                ccc.broadcastChanges();
            }
        } catch (Throwable e) {
            LOG.info("Failed to open craft confirm menu.", e);
        }
    }

public void startJob() {
        clearError();

        if (isClientSide()) {
            sendClientAction(ACTION_START_JOB);
            return;
        }

        if (this.result != null && !this.result.simulation()) {
            final ICraftingService cc = this.getGrid().getCraftingService();
            var submitResult = cc.submitJob(this.result, null, this.selectedCpu, true, this.getActionSrc());
            this.setAutoStart(false);
            if (submitResult.successful()) {
                if (autoCraftingQueue != null && !autoCraftingQueue.isEmpty()) {
                    // Process next stack!
                    CraftConfirmMenu.openWithCraftingList(getActionHost(), (ServerPlayer) getPlayer(), getLocator(),
                            autoCraftingQueue);
                } else {
                    this.host.returnToMainMenu(getPlayer(), this);
                }
            } else {
                AELog.info("Couldn't submit crafting job for %dx%s: %s [Detail: %s]",
                        result.finalOutput().amount(),
                        result.finalOutput().what(),
                        submitResult.errorCode(),
                        submitResult.errorDetail());
                this.submitError = new SyncableSubmitResult(submitResult);
            }
        }
    }

@ParameterizedTest
        @ValueSource(strings = { "wake", "alert", "sleep" })
        void testNodesCallingTickManagerFunctionsWhileTheyAreTicking(String operation) {
            var timesSinceLastTick = new ArrayList<Integer>();
            var node = makeTickingNode(new TickingRequest(1, 10, false), (tickingNode, ticksSinceLastCall) -> {
                timesSinceLastTick.add(ticksSinceLastCall);
                var result = switch (operation) {
                    case "wake" -> tickingNode.getGrid().getTickManager().wakeDevice(tickingNode);
                    case "alert" -> tickingNode.getGrid().getTickManager().alertDevice(tickingNode);
                    case "sleep" -> tickingNode.getGrid().getTickManager().sleepDevice(tickingNode);
                    default -> throw new IllegalArgumentException();
                };
                assertThat(result).isFalse();
                return TickRateModulation.IDLE;
            });
            // Set up a second node to ensure it does get ticked. In the regression, alertDevice would put
            // the other node at the front of the queue constantly, preventing this node from ticking
            var timesSinceLastTick2 = new ArrayList<Integer>();
            var secondNode = makeTickingNode(
                    new TickingRequest(6, 6, false),
                    (tickingNode, ticksSinceLastTick) -> {
                        timesSinceLastTick2.add(ticksSinceLastTick);
                        return TickRateModulation.SAME;
                    });
            GridHelper.createConnection(node, secondNode);

            runTick(node.getGrid(), 25);
            assertThat(timesSinceLastTick).containsExactly(5, 10, 10);
            assertThat(timesSinceLastTick2).containsExactly(6, 6, 6, 6);
        }

@Override
	public void tickServer()
	{
		if((isRSPowered()^redstoneControlInverted))
			return;

		if(tickCount%16==0)
		{
			if(tickCount%512==0)//Initial placement
				prepareAreaCheck();
			if(tank.getFluidAmount() >= FluidType.BUCKET_VOLUME&&
					!layeredPlacementQueue.isEmpty())
			{
				Queue<BlockPos> lowestLayer = layeredPlacementQueue.firstEntry().getValue();
				if(lowestLayer==null||lowestLayer.isEmpty())
					layeredPlacementQueue.pollFirstEntry();
				else
				{
					BlockPos targetPos = lowestLayer.poll();
					if(canFill(targetPos)&&tank.getFluid().getFluid().getFluidType().canBePlacedInLevel(level, targetPos, tank.getFluid()))
						if(place(targetPos, tank, level))
						{
							addConnectedSpaces(targetPos);
							handleTempFluids();
						}
				}
			}
		}
		tickCount++;
	}

@Override
	public void tickClient(IMultiblockContext<State> context)
	{
		final IMultiblockLevel level = context.getLevel();
		final Level rawLevel = level.getRawLevel();
		if(context.getState().active)
			for(final MultiblockProcess<BlueprintCraftingRecipe, ProcessContextInWorld<BlueprintCraftingRecipe>> process : context.getState().processor.getQueue())
			{
				++process.processTick;
				Player localPlayer = ImmersiveEngineering.proxy.getClientPlayer();
				switch(process.processTick)
				{
					default: break;
					case 39:
						rawLevel.playSound(localPlayer, level.toAbsolute(PROCESS_1_POS), IESounds.process1.value(), SoundSource.BLOCKS, .25f, 1f);
						break;
					case 40:
					case 78:
						rawLevel.playSound(localPlayer, level.toAbsolute(PROCESS_1_POS), IESounds.process1Lift.value(), SoundSource.BLOCKS, .64f, 1f);
						break;
					case 136:
					case 163:
						rawLevel.playSound(localPlayer, level.toAbsolute(PROCESS_2_POS), IESounds.process2Lift.value(), SoundSource.BLOCKS, 1f, 1f);
						break;
					case 144:
						rawLevel.playSound(localPlayer, level.toAbsolute(PROCESS_2_POS), IESounds.process2.value(), SoundSource.BLOCKS, 1F, 1f);
						break;
				}
			}
	}

@Override
	public void process(IPayloadContext context)
	{
		context.enqueueWork(() -> {
			ConnectionPoint start = this.connection.start();
			ConnectionPoint end = this.connection.end();
			WireType type = this.connection.type();
			WireLogger.logger.debug(
					"Processing sync for connection from {} to {}, type {}, op {}",
					start, end, type, operation.name()
			);
			Player player = ImmersiveEngineering.proxy.getClientPlayer();
			Level w = player.level();

			GlobalWireNetwork globalNet = GlobalWireNetwork.getNetwork(w);
			Connection connection = this.connection.toConnection();
			if(operation!=ADD&&globalNet.getNullableLocalNet(start)!=null&&globalNet.getNullableLocalNet(end)!=null)
			{
				globalNet.removeConnection(connection);
				removeProxyIfNoWires(start, globalNet);
				removeProxyIfNoWires(end, globalNet);
			}
			if(operation!=REMOVE)
				globalNet.addConnection(connection);
			Set<SectionPos> sectionsToRerender = new ObjectArraySet<>();
			WireUtils.forEachRenderPoint(connection, ($, $2, section) -> sectionsToRerender.add(section));
			for(SectionPos section : sectionsToRerender)
				Minecraft.getInstance().levelRenderer.setSectionDirty(section.x(), section.y(), section.z());
		});
	}

@Override
	public void readFromNBT(NBTTagCompound compound) {

		this.activated = compound.getBoolean("activated");
		this.conquered = compound.getBoolean("conquered");
		this.regenerationTime = compound.getLong("regenerationTime");
		this.lastRegenerationTime = compound.getLong("lastRegenerationTime");
		if (compound.hasKey("shrineElement"))
			this.shrineElement = Element.values()[compound.getInteger("shrineElement")];
		this.linkedContainerPos = NBTUtil.getPosFromTag(compound.getCompoundTag("linkedContainerPos"));

		NBTTagList wizardTagList = compound.getTagList("wizards", Constants.NBT.TAG_COMPOUND);
		int i = 0;
		for (NBTBase tag : wizardTagList) {
			if (tag instanceof NBTTagCompound) linkedWizards[i++] = NBTUtil.getUUIDFromTag((NBTTagCompound) tag);
			else Wizardry.logger.warn("Unexpected tag type in NBT tag list of compound tags!");
		}

		this.lootedPlayers.clear();
		if (compound.hasKey("lootedPlayers")) {
			NBTTagList playerTagList = compound.getTagList("lootedPlayers", Constants.NBT.TAG_COMPOUND);
