private boolean updateHeat() {
        if (heatQueue > 0) {
            // if received heat from overvolting or overamping, add heat
            setTemperature(temperature + heatQueue);
        }

        if (temperature >= meltTemp) {
            // cable melted
            level.setBlockAndUpdate(worldPosition, Blocks.FIRE.defaultBlockState());
            return false;
        }

        if (temperature <= getDefaultTemp()) {
            unsubscribeHeat();
            return false;
        }

        if (getPipeType().isCable() && temperature >= 1500 && GTValues.RNG.nextFloat() < 0.1f) {
            // insulation melted
            uninsulate();
            return false;
        }

        if (heatQueue <= 0) {
            // otherwise cool down
            setTemperature((int) (temperature - Math.pow(temperature - getDefaultTemp(), 0.35f)));
        }
        heatQueue = 0;
        return true;
    }

@Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        double temperature = this.getTemperature();
        double tickRate = this.getTickRate() / 5.0;
        double newTemperature;
        if (WorldHelper.isInWater(entity))
        {   newTemperature = CSMath.approach(temperature, this.getTargetTemperature(entity), ConfigSettings.WATER_SOAK_SPEED.get() * tickRate);
        }
        else if (WorldHelper.isRainingAt(entity.level(), entity.blockPosition()))
        {
            double maxRainEffect = -ConfigSettings.MAX_RAIN_SOAK.get();
            newTemperature = temperature > maxRainEffect
                           ? CSMath.approach(temperature, maxRainEffect, ConfigSettings.RAIN_SOAK_SPEED.get() * tickRate)
                           : temperature;
        }
        else
        {
            double worldTemp = Temperature.get(entity, Temperature.Trait.WORLD);
            double configDrySpeed = ConfigSettings.DRYOFF_SPEED.get();
            double dryAmount = CSMath.blendExp(configDrySpeed / 1.5, configDrySpeed * 5, worldTemp, ConfigSettings.MIN_TEMP.get(), ConfigSettings.MAX_TEMP.get(), 20);
            newTemperature = CSMath.shrink(temperature, dryAmount * tickRate);
        }
        if (newTemperature == 0)
        {   this.expires(0);
        }
        this.setTemperature(newTemperature);

        return temp -> temp + newTemperature;
    }

public static InsulationSnapshot getInsulationAt(Level level, BlockPos pos, int chunkRadius)
    {
        InsulationSnapshot snapshot = INSULATION_CACHE.computeIfAbsent(level.dimension(), dim -> new HashMap<>()).get(pos);
        if (snapshot != null && level.getGameTime() - snapshot.timestamp < 20)
        {   return snapshot;
        }
        pos = sublevelToWorld(level, pos);
        int maxCoolingLevel = 0;
        int maxHeatingLevel = 0;
        ChunkPos chunkPos = new ChunkPos(pos);
        for (int x = -chunkRadius; x <= chunkRadius; x++)
        for (int z = -chunkRadius; z <= chunkRadius; z++)
        {
            ChunkAccess chunk = getChunk(level, chunkPos.x + x, chunkPos.z + z);
            if (chunk == null) continue;

            for (BlockPos bePos : chunk.getBlockEntitiesPos())
            {
                BlockEntity be = chunk.getBlockEntity(bePos);
                if (be instanceof HearthBlockEntity hearth && hearth.getPathLookup().containsKey(pos))
                {
                    maxCoolingLevel = Math.max(maxCoolingLevel, hearth.getCoolingLevel());
                    maxHeatingLevel = Math.max(maxHeatingLevel, hearth.getHeatingLevel());
                }
            }
        }
        snapshot = new InsulationSnapshot(level.getGameTime(), maxCoolingLevel, maxHeatingLevel);
        INSULATION_CACHE.get(level.dimension()).put(pos, snapshot);
        return snapshot;
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();
            var level = player.level();

            CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(this.getIdentifier(), this.getIndex())).ifPresent(slot -> {
                var stack = slot.stack();
                var relic = (RollerSkateItem) stack.getItem();

                var spark = new RollerSparkEntity(RelicsEntities.ROLLER_SPARK.get(), level);

                spark.setDeltaMovement(this.motion.x(), this.motion.y(), this.motion.z());
                spark.setPos(this.pos.x(), this.pos.y(), this.pos.z());
                spark.setFlawless(this.flawless);
                spark.setDamage(this.damage);
                spark.setIgnite(this.ignite);
                spark.setStack(stack);

                if (level instanceof ServerLevel serverLevel)
                    spark.setOwner(serverLevel.getEntity(UUID.fromString(this.owner)));

                level.addFreshEntity(spark);

                relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("sparks_created").addValue(1);

                if (relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("skating").getStatisticData().getMetricData("sparks_created").getValue() % 10 == 0)
                    relic.getRelicData(player, stack).getLevelingData().addExperience("skating", "creating_sparks", 1);
            });
        });
    }

public void render(AnimatorBlockEntity pBlockEntity, float pPartialTicks, PoseStack pMatrixStack, MultiBufferSource pBuffer, int pCombinedLight, int pCombinedOverlay) {
        ItemStack itemStack = pBlockEntity.getItem();
        Minecraft minecraft = Minecraft.getInstance();
        if (pBlockEntity.getLevel() != null && itemStack != null && !itemStack.isEmpty()){
            pMatrixStack.pushPose();
            pMatrixStack.translate(0.5F, 0.5F, 0.5F);
            pMatrixStack.scale(1.0F, 1.0F, 1.0F);
            if (pBlockEntity.getSpinning() > 0){
                pMatrixStack.mulPose(Axis.YP.rotationDegrees(12 * (minecraft.level.getGameTime() % 360 + pPartialTicks)));
            } else {
                pMatrixStack.mulPose(Axis.YP.rotationDegrees(3 * (minecraft.level.getGameTime() % 360 + pPartialTicks)));
            }
            minecraft.getItemRenderer().renderStatic(itemStack, ItemDisplayContext.GROUND, pCombinedLight, pCombinedOverlay, pMatrixStack, pBuffer, pBlockEntity.getLevel(), 0);
            pMatrixStack.popPose();
            if (pBlockEntity.isShowBlock()) {
                Map<BlockPos, ColorUtil> renderCubes = new HashMap<>();
                GlobalPos loc = WaystoneItem.getPosition(itemStack);
                if (loc != null) {
                    if (loc.dimension() == pBlockEntity.getLevel().dimension()) {
                        renderCubes.put(loc.pos(), new ColorUtil(ChatFormatting.LIGHT_PURPLE));
                    }
                }
                if (!renderCubes.keySet().isEmpty()) {
                    Vec3 view = Vec3.atLowerCornerOf(pBlockEntity.getBlockPos());
                    RenderBlockUtils.renderColourCubes(pMatrixStack, view, renderCubes, 1.0F, 1.0F);
                }
                draw(pBlockEntity, pMatrixStack, pBuffer);
            }
        }
    }

@Override
    public void render(EndLanternBlockEntity blockEntity, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int packedLight, int packedOverlay) {
        BlockState state = blockEntity.getBlockState();
        if (!(state.getBlock() instanceof EndFloatingLanternBlock) || blockEntity.getLevel() == null) {
            return;
        }
        float offset = Math.floorMod(blockEntity.getBlockPos().asLong(), (long) LOOP_TICKS);
        float time = blockEntity.getLevel().getGameTime() + partialTick + offset;
        float key = (time % LOOP_TICKS) / LOOP_TICKS * KEYS;

        Minecraft minecraft = Minecraft.getInstance();
        ModelManager models = minecraft.getModelManager();
        ModelBlockRenderer renderer = minecraft.getBlockRenderer().getModelRenderer();
        VertexConsumer consumer = buffer.getBuffer(RenderType.solid());
        VertexConsumer consumer2 = buffer.getBuffer(RenderType.cutout());

        for (Part part : PARTS) {
            BakedModel model = models.getModel(part.model());
            poseStack.pushPose();
            poseStack.translate(part.x() / 16.0F, (part.y() + sample(part.track(), key)) / 16.0F, part.z() / 16.0F);
            poseStack.translate(-0.5F, -0.5F, -0.5F);
            renderer.renderModel(poseStack.last(), consumer, state, model, 1.0F, 1.0F, 1.0F, packedLight, packedOverlay, ModelData.EMPTY, RenderType.solid());
            poseStack.popPose();
            poseStack.pushPose();
            poseStack.translate(part.x() / 16.0F, (part.y() + sample(part.track(), key)) / 16.0F, part.z() / 16.0F);
            poseStack.translate(-0.5F, -0.5F, -0.5F);
            renderer.renderModel(poseStack.last(), consumer2, state, model, 1.0F, 1.0F, 1.0F, packedLight, packedOverlay, ModelData.EMPTY, RenderType.cutout());
            poseStack.popPose();
        }
    }

public boolean canUse() {
      long i = this.mob.level().getGameTime();
      if (i - this.lastCanUseCheck < 20L) {
         return false;
      } else {
         this.lastCanUseCheck = i;
         LivingEntity livingentity = this.mob.getTarget();
         if (livingentity == null) {
            return false;
         } else if (!livingentity.isAlive()) {
            return false;
         } else {
           if (canPenalize) {
               if (--this.ticksUntilNextPathRecalculation <= 0) {
                  this.path = this.mob.getNavigation().createPath(livingentity, 0);
                  this.ticksUntilNextPathRecalculation = 4 + this.mob.getRandom().nextInt(7);
                  return this.path != null;
               } else {
                  return true;
               }
            }
            this.path = this.mob.getNavigation().createPath(livingentity, 0);
            if (this.path != null) {
               return true;
            } else {
               return this.getAttackReachSqr(livingentity) >= this.mob.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
            }
         }
      }
   }

public InteractionResult useOn(UseOnContext pContext) {
        Level world = pContext.getLevel();
        ItemStack stack = pContext.getItemInHand();
        Player player = pContext.getPlayer();
        if (player != null) {
            if (!stack.isEmpty() && !hasRecall(stack)) {
                CompoundTag compoundTag = stack.getOrCreateTag();
                if (stack.getItem() instanceof RecallFocus) {
                    BlockPos blockpos = pContext.getClickedPos();
                    BlockEntity tileEntity = world.getBlockEntity(blockpos);
                    if (tileEntity instanceof ArcaBlockEntity arcaTile) {
                        if (pContext.getPlayer() == arcaTile.getPlayer() && arcaTile.getLevel() != null) {
                            this.addRecallTags(arcaTile.getLevel().dimension(), arcaTile.getBlockPos(), compoundTag);
                            stack.setTag(compoundTag);
                            player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                            return InteractionResult.sidedSuccess(world.isClientSide);
                        }
                    }
                    BlockState blockstate = world.getBlockState(blockpos);
                    if (blockstate.is(ModTags.Blocks.RECALL_BLOCKS)) {
                        this.addRecallTags(world.dimension(), blockpos, compoundTag);
                        stack.setTag(compoundTag);
                        player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                        return InteractionResult.sidedSuccess(world.isClientSide);
                    }
                }
            }
        }
        return InteractionResult.PASS;
    }

public static void consume(CAddFocusToBagPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Player player = ctx.get().getSender();
            if (player != null) {
                ItemStack stack = TotemFinder.findBag(player);
                if (stack.getCount() <= 0) {
                    return;
                }

                ItemStack wand = WandUtil.findWand(player);

                FocusBagItemHandler bagHandler = FocusBagItemHandler.get(stack);
                SoulUsingItemHandler wandHandler = SoulUsingItemHandler.get(wand);

                ItemStack wandFocus = wandHandler.getSlot();

                for (int i = 1; i < bagHandler.getSlots(); ++i) {
                    ItemStack itemStack = bagHandler.getStackInSlot(i);
                    if (itemStack.isEmpty()) {
                        bagHandler.setStackInSlot(i, wandFocus);
                        wandHandler.extractItem();
                        break;
                    }
                }
                if (player instanceof ServerPlayer serverPlayer){
                    serverPlayer.connection.send(new ClientboundSoundPacket(ModSounds.FOCUS_PICK.getHolder().get(), SoundSource.PLAYERS, serverPlayer.position().x, serverPlayer.position().y, serverPlayer.position().z, 1.0F, 1.0F, serverPlayer.level().getRandom().nextLong()));
                }
            }
        });
    }

