public void aiStep() {
        super.aiStep();
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (!this.level.isClientSide) {
            this.setAngry(this.getTarget() != null);
            if (this.tickCount % 1000 == 0) {
                if (this.wantsToBreed() && !this.isMale()) {
                    this.setAge(this.getPregnancyTime());
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }

        if (!this.isNoAi() && !this.isBaby()) {
            if (this.ringBufferIndex < 0) {
                for (int i = 0; i < this.ringBuffer.length; ++i) {
                    this.ringBuffer[i][0] = this.getYRot();
                    this.ringBuffer[i][1] = this.getY();
                }
            }
            this.ringBufferIndex++;
            if (this.ringBufferIndex == this.ringBuffer.length) {
                this.ringBufferIndex = 0;
            }
            this.ringBuffer[this.ringBufferIndex][0] = this.yRotO + 0.5F * Mth.wrapDegrees(this.getYRot() - this.yRotO);
            this.ringBuffer[ringBufferIndex][1] = this.getY();
        }
    }

public void createTreasuredSpawn(int tier)
    {
        if (!(this.level() instanceof ServerLevel serverLevel))
        {
            return;
        }

        var prevShoalSize = this.shoalFishData.size();
        this.shoalFishData.clear();

        for (var entityType : pickRandom(this.javaRandom, tier == 1 ? TIER_1_FISH_QUEST : TIER_2_FISH_QUEST, prevShoalSize))
        {
            var entity = entityType.create(serverLevel);

            if (entity instanceof ThievesFish<?> thievesFish)
            {
                var compoundTag = new CompoundTag();
                var key = Util.getRandom(thievesFish.getRegistry()
                        .entrySet()
                        .stream()
                        .filter(entry -> entry.getValue().isTreasured().isPresent())
                        .map(entry -> entry.getKey().location()).toList(), this.random);
                compoundTag.putString(ThievesFish.VARIANT_TAG, key.toString());
                compoundTag.putBoolean(ThievesFish.TROPHY_TAG, true);
                this.shoalFishData.add(new ShoalFishData(BuiltInRegistries.ENTITY_TYPE.getKey(entity.getType()).toString(), UUID.randomUUID(), compoundTag));
            }
        }
        this.expiredAt = -1;
        FOTPlatform.syncClientShoalFish(this, true);
    }

public static void renderSearch(PoseStack matrixStack, VertexConsumer builder, double x, double y, double z, int itemCount, int totalCount, float partialTicks) {
        matrixStack.pushPose();

        matrixStack.translate(x, y, z);
        RenderUtils.rotateToPlayerFacing(matrixStack);
        float ratio = (float) itemCount / totalCount;
        float diff = (1 - ratio) / 1.5F;
        float size = 1 - diff;
        float f = ((ClientUtils.getClientLevel().getGameTime() & 0x1f) + partialTicks) / 5.092f;  // 0 .. 2*pi every 32 ticks
        float alpha = 0.65F + Mth.sin(f) * 0.15f;
        Matrix4f posMat = matrixStack.last().pose();
        builder.addVertex(posMat, -size, size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(0, 1)
                .setLight(LightTexture.FULL_BRIGHT);
        builder.addVertex(posMat, size, size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(1, 1)
                .setLight(LightTexture.FULL_BRIGHT);
        builder.addVertex(posMat, size, -size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(1, 0)
                .setLight(LightTexture.FULL_BRIGHT);
        builder.addVertex(posMat, -size, -size, 0)
                .setColor(0, 1, 0, alpha)
                .setUv(0, 0)
                .setLight(LightTexture.FULL_BRIGHT);

        matrixStack.popPose();
    }

@Override
    public void tickServer() {
        super.tickServer();

        final Level level = nonNullLevel();
        if (level.getGameTime() % 5 == 0) {
            airPerTick = (BASE_FE_PRODUCTION * this.getSpeedUsageMultiplierFromUpgrades()
                    * (getHeatEfficiency() / 100f)
                    * (ConfigHelper.common().machines.fluxCompressorEfficiency.get() / 100f));
            rfPerTick = (int) (BASE_FE_PRODUCTION * this.getSpeedUsageMultiplierFromUpgrades());
        }
        boolean newEnabled = false;
        if (rsController.shouldRun() && energy.getEnergyStored() >= rfPerTick) {
            airBuffer += airPerTick;
            if (airBuffer >= 1f) {
                int toAdd = (int) airBuffer;
                this.addAir(toAdd);
                airBuffer -= toAdd;
                heatExchanger.addHeat(toAdd / 20d);
            }
            energy.extractEnergy(rfPerTick, false);
            newEnabled = true;
        }
        if ((level.getGameTime() & 0x7) == 0 && newEnabled != isEnabled) {
            isEnabled = newEnabled;
            BlockState state = level.getBlockState(worldPosition);
            level.setBlockAndUpdate(worldPosition, state.setValue(PNCBlockStateProperties.ACTIVE, isEnabled));
        }
        airHandler.setSideLeaking(hasNoConnectedAirHandlers() ? getRotation().getOpposite() : null);
    }

public List<IProgWidget> mergeWidgetsFromNBT(List<IProgWidget> toMerge) {
        List<IProgWidget> result = new ArrayList<>(progWidgets);

        if (!progWidgets.isEmpty() && !toMerge.isEmpty()) {
            // move merged widgets so that they definitely don't overlap any existing widgets
            PuzzleExtents extents1 = getPuzzleExtents(progWidgets);
            PuzzleExtents extents2 = getPuzzleExtents(toMerge);
            for (IProgWidget w : toMerge) {
                w.setPosition(
                        w.getX() - extents2.x() + extents1.x() + extents1.width() + 10,
                        w.getY() - extents2.y() + extents1.y());
            }
        }

        toMerge.forEach(w -> {
            if (w instanceof ProgWidgetStart) {
                // any start widget in the merged import is replaced with a label/text widget pair
                ProgWidgetLabel label = new ProgWidgetLabel();
                label.setPosition(w.getX(), w.getY());
                result.add(label);
                ProgWidgetText text = ProgWidgetText.withText("Merge #" + nonNullLevel().getGameTime());
                text.setPosition(label.getX() + label.getWidth() / 2, label.getY());
                result.add(text);
            } else {
                result.add(w);
            }
        });

        return result;
    }

