                        .sendToAllPlayersTrackingEntity(livingEntity);
            }
        }

        return stack;
    }

private void emitParticles(ItemStack stack, ManaSpreader spreader) {
		float rotationYaw = -(spreader.getRotationX() + 90F);
		float rotationPitch = spreader.getRotationY();

		// Lots of EntityThrowable copypasta
		float f = 0.3F;
		float mx = (float) (Mth.sin(rotationYaw / 180.0F * (float) Math.PI) * Mth.cos(rotationPitch / 180.0F * (float) Math.PI) * f / 2D);
		float mz = (float) (-(Mth.cos(rotationYaw / 180.0F * (float) Math.PI) * Mth.cos(rotationPitch / 180.0F * (float) Math.PI) * f) / 2D);
		float my = (float) (Mth.sin(rotationPitch / 180.0F * (float) Math.PI) * f / 2D);

		int storedColor = LensItem.getStoredColor(stack);
		int hex = -1;

		var level = spreader.getManaReceiverLevel();
		if (storedColor == 16) {
			hex = Mth.hsvToRgb(level.getGameTime() * 2 % 360 / 360F, 1F, 1F);
		} else if (storedColor >= 0) {
			hex = ColorHelper.getColorValue(DyeColor.byId(storedColor));
		}

		float r = ((hex & 0xFF0000) >> 16) / 255F;
		float g = ((hex & 0xFF00) >> 8) / 255F;
		float b = (hex & 0xFF) / 255F;

		WispParticleData data = WispParticleData.wisp(0.4F, r, g, b);
		// The start position is set a bit away from the spreader (along the burst's motion vector), as to not
		// collide with the spreader itself.
		var pos = spreader.getManaReceiverPos();
		level.addParticle(data, pos.getX() + 0.5 + mx * 4.5, pos.getY() + 0.5 + my * 4.5, pos.getZ() + 0.5 + mz * 4.5, mx, my, mz);
	}

@LoadEvent
	public void setup(ZCommonSetup e) {
		if(!isEnabled())
			return;

		BlockBehavior baseBehavior = new BlockBehavior();

		e.enqueueWork(() -> {
			Map<Item, DispenseItemBehavior> registry = DispenserBlock.DISPENSER_REGISTRY;

			for(Block b : BuiltInRegistries.BLOCK) {
				ResourceLocation res = BuiltInRegistries.BLOCK.getKey(b);
				if(!blacklist.contains(Objects.toString(res))) {
					Item item = b.asItem();
					if(item instanceof BlockItem) {
						DispenseItemBehavior original = registry.get(item);
						boolean exists = original != null && original.getClass() != DefaultDispenseItemBehavior.class;
						if(original instanceof BlockBehavior)
							continue; //some blocks map to same item (mob heads)
						if(exists) {
							if(wrapExistingBehaviors && original instanceof OptionalDispenseItemBehavior opt)
								registry.put(item, new BlockBehavior(opt));
						} else
							registry.put(item, baseBehavior);
					}

				}
			}
		});
	}

default boolean shouldRestock() {
        /*
        Game time is persistent, Day Time not.
        Day time does not reset to zero every day, but commands and such often reset it otherwise
        Therefore, day time is not consistent enough to base our trades off of.
        (one day is 24,000 ticks)
         */
        long timeToNextRestock = getLastRestockGameTime() + 12000L;
        long currentGameTime = level().getGameTime();
        //If total game time has exceeded one half day, we can restock.
        boolean hasDayElapsed = currentGameTime > timeToNextRestock;

        long currentDayTime = level().getDayTime();
        if (getLastRestockCheckDayTime() > 0L) {
            long lastRestockDay = getLastRestockCheckDayTime() / 24000L;
            long currentDay = currentDayTime / 24000L;
            //Or, if day time is accurate, and a whole day has passed, we can also restock.
            hasDayElapsed |= currentDay > lastRestockDay;
        } else {
            //Make our day time accurate again
            setLastRestockCheckDayTime(currentDayTime);
        }

        if (hasDayElapsed) {
            //update times
            setLastRestockCheckDayTime(currentDayTime);
            setRestocksToday(0);
        }
        return this.needsToRestock() && allowedToRestock();
    }

public boolean canUse() {
      long i = this.mob.level().getGameTime();
      if (i - this.lastCanUseCheck < 20L) {
         return false;
      } else {
         this.lastCanUseCheck = i;
         LivingEntity livingentity = this.mob.getTarget();
         if (livingentity == null) {
            return false;
         } else if (!livingentity.isAlive()) {
            return false;
         } else {
           if (canPenalize) {
               if (--this.ticksUntilNextPathRecalculation <= 0) {
                  this.path = this.mob.getNavigation().createPath(livingentity, 0);
                  this.ticksUntilNextPathRecalculation = 4 + this.mob.getRandom().nextInt(7);
                  return this.path != null;
               } else {
                  return true;
               }
            }
            this.path = this.mob.getNavigation().createPath(livingentity, 0);
            if (this.path != null) {
               return true;
            } else {
               return this.getAttackReachSqr(livingentity) >= this.mob.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
            }
         }
      }
   }

public static void registerFluidExtensions(RegisterClientExtensionsEvent event, FluidDeferredRegister allFluids) {
        for (Holder<FluidType> fluidTypeEntry : allFluids.getFluidTypeEntries()) {
            if (fluidTypeEntry.value() instanceof MekanismFluidType fluidType) {
                event.registerFluidType(new IClientFluidTypeExtensions() {

                    @Override
                    public Identifier getRenderOverlayTexture(Minecraft mc) {
                        return fluidType.renderOverlayTexture;
                    }

                    @Override
                    public void modifyFogColor(Camera camera, float partialTick, ClientLevel level, int renderDistance, float darkenWorldAmount, Vector4f fluidFogColor) {
                        //Note: Similarly to vanilla we don't bother applying a different value for alpha
                        fluidFogColor.set(ARGB.redFloat(fluidType.color), ARGB.greenFloat(fluidType.color), ARGB.blueFloat(fluidType.color));
                    }

                    @Override
                    public void modifyFogRender(Camera camera, @Nullable FogEnvironment environment, float renderDistance, float partialTick, FogData fog) {
                        //Copy of logic for water except always treating it as if it was a player who has no water vision
                        // and does not take the biome's closer water fog into account
                        fog.environmentalStart = camera.attributeProbe().getValue(EnvironmentAttributes.WATER_FOG_START_DISTANCE, partialTick);
                        fog.environmentalEnd = camera.attributeProbe().getValue(EnvironmentAttributes.WATER_FOG_END_DISTANCE, partialTick);

                        fog.skyEnd = fog.environmentalEnd;
                        fog.cloudEnd = fog.environmentalEnd;
                    }
                }, fluidType);
            }
        }
    }

public <BUCKET extends BucketItem> FluidRegistryObject<MekanismFluidType, Source, Flowing, LiquidBlock, BUCKET> register(String name,
          FluidType.Properties properties, FluidTypeRenderProperties renderProperties, BucketCreator<BUCKET> bucketCreator,
          BiFunction<FluidType.Properties, FluidTypeRenderProperties, MekanismFluidType> fluidTypeCreator) {
        DeferredHolder<FluidType, MekanismFluidType> fluidType = fluidTypeRegister.register(name, rl -> {
            //Set the translation string to the same as the block (we rely on the implementation detail that we make our fluid type's name is the same as the block's)
            properties.descriptionId(rl.toLanguageKey("block"));
            return fluidTypeCreator.apply(properties, renderProperties);
        });

        //TODO: Ideally we wouldn't have to create holders for these suppliers and instead could just somehow use the actual registered ones
        Identifier baseKey = Identifier.fromNamespaceAndPath(fluidRegister.getNamespace(), name);
        BaseFlowingFluid.Properties fluidProperties = new BaseFlowingFluid.Properties(
              fluidType,
              DeferredHolder.create(Registries.FLUID, baseKey),
              DeferredHolder.create(Registries.FLUID, baseKey.withPrefix("flowing_"))
        ).bucket(DeferredHolder.create(Registries.ITEM, baseKey.withSuffix("_bucket")))
              .block(DeferredHolder.create(Registries.BLOCK, baseKey));

        DeferredHolder<Fluid, Source> stillFluid = fluidRegister.register(name, () -> new Source(fluidProperties));
        DeferredHolder<Fluid, Flowing> flowingFluid = fluidRegister.register("flowing_" + name, () -> new Flowing(fluidProperties));
        ItemRegistryObject<BUCKET> bucket = itemRegister.registerItem(name + "_bucket", itemProperties -> bucketCreator.create(stillFluid.get(), itemProperties.stacksTo(1).craftRemainder(Items.BUCKET)));
        MapColor color = getClosestColor(renderProperties.color);
        //Note: The block properties used here is a copy of the ones for water
        DeferredHolder<Block, LiquidBlock> block = blockRegister.register(name, key -> new LiquidBlock(stillFluid.get(), BlockBehaviour.Properties.of()
              .setId(ResourceKey.create(blockRegister.getRegistryKey(), key))
              .noCollision().strength(100.0F).noLootTable().replaceable().pushReaction(PushReaction.POPPED).liquid().mapColor(color)));
        FluidRegistryObject<MekanismFluidType, Source, Flowing, LiquidBlock, BUCKET> registryObject = new FluidRegistryObject<>(fluidType, stillFluid, flowingFluid, bucket, block);
        allRegistered.add(registryObject);
        return registryObject;
    }

@Override
    protected boolean onUpdateServer(ServerLevel level, @Nullable QIOFrequency frequency) {
        boolean needsUpdate = super.onUpdateServer(level, frequency);
        if (level.getGameTime() % MekanismUtils.TICKS_PER_HALF_SECOND == 0) {
            for (int i = 0; i < DRIVE_SLOTS; i++) {
                QIODriveSlot slot = driveSlots.get(i);
                QIODriveData data = frequency == null ? null : frequency.getDriveData(slot.getKey());
                if (frequency == null || data == null) {
                    setDriveStatus(i, slot.isEmpty() ? DriveStatus.NONE : DriveStatus.OFFLINE);
                    continue;
                }
                if (data.getTotalCount() == data.getCountCapacity()) {
                    //If we are at max item capacity: Full
                    setDriveStatus(i, DriveStatus.FULL);
                } else if (data.getTotalTypes() == data.getTypeCapacity() || data.getTotalCount() >= data.getCountCapacity() * 0.75) {
                    //If we are at max type capacity OR we are at 75% or more capacity: Near full
                    setDriveStatus(i, DriveStatus.NEAR_FULL);
                } else {
                    //Otherwise: Ready
                    setDriveStatus(i, DriveStatus.READY);
                }
            }

            if (driveStatus != prevDriveStatus) {
                needsUpdate = true;
                prevDriveStatus = driveStatus;
            }
        }
        return needsUpdate;
    }

