                    if (mob.onGround()) {
                        Vec3 randomShake = new Vec3(random.nextFloat() - 0.5F, 0, random.nextFloat() - 0.5F).scale(0.1F);
                        mob.setDeltaMovement(mob.getDeltaMovement().multiply(0.7F, 1, 0.7F).add(randomShake));
                    }
                    if (lastScareTimestamp == tickCount) {
                        mob.getNavigation().stop();
                    }
                    if (mob.getNavigation().isDone()) {
                        Vec3 vec = LandRandomPos.getPosAway(mob, 30, 7, this.position());
                        if (vec != null) {
                            mob.getNavigation().moveTo(vec.x, vec.y, vec.z, 2D);
                        }
                    }
                }
                if (this.isTame()) {
                    e.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 200, 0, true, true));
                }
            }

        }
    }

@Override
	public void onLivingUpdate() {
		if (getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime()%5 + getEntityWorld().rand.nextInt(5) == 0) {
			if (isInWater()) {
				for (int i = 0; i < 2; ++i) {
					double a = Math.toRadians(rotationYaw);
					double offSetX = -Math.sin(a) * width * 0.5D;
					double offSetZ = Math.cos(a) * width * 0.5D;
					getEntityWorld().spawnParticle(EnumParticleTypes.WATER_BUBBLE, posX + offSetX, posY + height * 0.5D + rand.nextDouble() * 0.5D, posZ + offSetZ, 0.0D, 0.4D, 0.0D, new int[0]);
				}
			}
		}

		if (inWater) {
			setAir(300);
		} else if (onGround) {
			motionY += 0.5D;
			motionX += (double) ((rand.nextFloat() * 2.0F - 1.0F) * 0.4F);
			motionZ += (double) ((rand.nextFloat() * 2.0F - 1.0F) * 0.4F);
			rotationYaw = rand.nextFloat() * 360.0F;
			if(isLeaping())
				setIsLeaping(false);
			onGround = false;
			isAirBorne = true;
			if(getEntityWorld().getTotalWorldTime()%5==0)
				getEntityWorld().playSound((EntityPlayer) null, posX, posY, posZ, SoundRegistry.FISH_FLOP, SoundCategory.HOSTILE, 1F, 1F);
				damageEntity(DamageSource.DROWN, 0.5F);
		}

		super.onLivingUpdate();
	}

@Override
    protected void onImpact(RayTraceResult result) {
        if (!this.world.isRemote) {
            AxisAlignedBB hitBB = this.getEntityBoundingBox().grow(4.0D, 2.0D, 4.0D);
            List<EntityLivingBase> hitEntities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, hitBB);
            if (!hitEntities.isEmpty()) {
                Iterator<EntityLivingBase> hitEntitiesIT = hitEntities.iterator();
                while (hitEntitiesIT.hasNext()) {
                    EntityLivingBase affectedEntity = hitEntitiesIT.next();
                    double entityDst = this.getDistanceSq(affectedEntity);
                    if (entityDst < 16.0D) {
                        double modifier = 1.0D - Math.sqrt(entityDst) / 4.0D;
                        if (affectedEntity == result.entityHit) {
                            modifier = 1.0D;
                        }
                        PotionEffect effect = ItemRegistry.ELIXIR.createPotionEffect(getElixirStack(), modifier);
                        SplashPotionEvent event = new SplashPotionEvent(this, affectedEntity, effect, effect.getPotion().isInstant());
                        MinecraftForge.EVENT_BUS.post(event);
                        if(!event.isCanceled()) {
                        	affectedEntity.addPotionEffect(effect);
                        }
                    }
                }
            }
            this.world.playEvent(2002, new BlockPos(this), ItemRegistry.ELIXIR.getColorMultiplier(getElixirStack(), 0));
            this.entityDropItem(new ItemStack(ItemRegistry.ELIXIR.getDentrothystType(getElixirStack()) == EnumDentrothyst.GREEN ? ItemRegistry.DENTROTHYST_SHARD_GREEN : ItemRegistry.DENTROTHYST_SHARD_ORANGE,
            		this.world.rand.nextInt(2) + 2), this.height / 2);
            if(this.world.rand.nextInt(2) == 0) this.entityDropItem(EnumItemMisc.RUBBER_BALL.create(1), this.height / 2);
            this.setDead();
        }
    }

public NodeStatus getStatus(IGridNode node) {
        var sleepingTracker = sleeping.get(node);
        var awakeTracker = awake.get(node);
        var alertableTracker = alertable.get(node);

        // Also check if the node is _really_ queued for ticking. If it's awake
        // and not queued, this indicates a bug.
        boolean isQueued = false;
        var tickQueue = upcomingTicks.get(node.getLevel());
        if (awakeTracker != null && tickQueue != null) {
            isQueued = Iterators.contains(tickQueue.iterator(), awakeTracker);
        }

        // Get the tick-request stats
        var tracker = awakeTracker;
        if (tracker == null) {
            tracker = alertableTracker;
        }
        if (tracker == null) {
            tracker = sleepingTracker;
        }
        var currentRate = tracker != null ? tracker.getCurrentRate() : 0;
        var lastTick = tracker != null ? tracker.getLastTick() : 0;
        return new NodeStatus(
                alertableTracker != null,
                sleepingTracker != null,
                awakeTracker != null,
                isQueued,
                currentRate,
                currentTick - lastTick);
    }

private static FluidEntry make(
				String name, int burnTime,
				ResourceLocation stillTex, ResourceLocation flowingTex,
				Function<FluidEntry, ? extends IEFluid> makeStill, Function<FluidEntry, ? extends IEFluid> makeFlowing,
				@Nullable Consumer<FluidType.Properties> buildAttributes, List<Property<?>> properties)
		{
			FluidType.Properties builder = FluidType.Properties.create()
					.sound(SoundActions.BUCKET_FILL, SoundEvents.BUCKET_FILL)
					.sound(SoundActions.BUCKET_EMPTY, SoundEvents.BUCKET_EMPTY);
			if(buildAttributes!=null)
				buildAttributes.accept(builder);
			Holder<FluidType> type = TYPE_REGISTER.register(name, () -> new FluidType(builder));
			Mutable<FluidEntry> thisMutable = new MutableObject<>();
			DeferredHolder<Fluid, IEFluid> still = REGISTER.register(name, () -> IEFluid.makeFluid(
					makeStill, thisMutable.getValue()
			));
			DeferredHolder<Fluid, IEFluid> flowing = REGISTER.register(name+"_flowing", () -> IEFluid.makeFluid(
					makeFlowing, thisMutable.getValue()
			));
			BlockEntry<IEFluidBlock> block = new IEBlocks.BlockEntry<>(
					name+"_fluid_block",
					() -> Properties.ofFullCopy(Blocks.WATER),
					p -> new IEFluidBlock(thisMutable.getValue(), p)
			);
			DeferredHolder<Item, BucketItem> bucket = IEItems.REGISTER.register(name+"_bucket", () -> makeBucket(still, burnTime));
			FluidEntry entry = new FluidEntry(flowing, flowingTex, still, stillTex, block, bucket, type, properties);
			thisMutable.setValue(entry);
			ALL_FLUID_BLOCKS.add(block);
			ALL_ENTRIES.add(entry);
			return entry;
		}

