@Deprecated(since = "2.4.1", forRemoval = true)
    public static CompoundTag modifierToTag(TempModifier modifier)
    {
        // Write the modifier's data to a CompoundTag
        CompoundTag modifierTag = new CompoundTag();
        ResourceLocation modifierId = modifier.getID();
        if (modifierId == null)
        {
            ColdSweat.LOGGER.error("Failed to get key for TempModifier: {}", modifier.getClass().getSimpleName());
            return modifierTag;
        }
        modifierTag.putString("Id", modifierId.toString());

        // Add the modifier's arguments
        modifierTag.put("ModifierData", modifier.getNBT());

        // Read the modifier's expiration time
        if (modifier.getExpireTime() != -1)
            modifierTag.putInt("ExpireTicks", modifier.getExpireTime());

        // Read the modifier's tick rate
        if (modifier.getTickRate() > 1)
            modifierTag.putInt("TickRate", modifier.getTickRate());

        // Read the modifier's ticks existed
        modifierTag.putInt("TicksExisted", modifier.getTicksExisted());

        modifierTag.putInt("Hash", modifier.hashCode());

        return modifierTag;
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            Player player = ctx.player();

            if (player.containerMenu.containerId != container) {
                causeError(player);

                return;
            }

            ItemStack stack = DescriptionUtils.gatherRelicStack(player, slot);

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                causeError(player);

                return;
            }

            if (!switch (operation) {
                case RANKUP -> relic.getRelicData(player, stack).getLevelingData().rankup();
            }) return;

            try {
                player.containerMenu.getSlot(slot).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                causeError(player);
            }
        });
    }

@Override
	public void clientTick(Entity entity, Level level, BlockPos pos) {
		if (!level.isClientSide || entity == null) {
			return;
		}

		if (!(storageWrapper instanceof IBackpackWrapper backpackWrapper)) {
			return;
		}

		List<CapturedMob> capturedMobs = MobCatcherStorage.getCapturedMobs(backpackWrapper);
		if (capturedMobs.isEmpty()) {
			nextAmbientSoundTime = Long.MIN_VALUE;
			return;
		}

		long gameTime = level.getGameTime();
		if (nextAmbientSoundTime == Long.MIN_VALUE) {
			nextAmbientSoundTime = gameTime + 40 + level.random.nextInt(120);
			return;
		}
		if (gameTime < nextAmbientSoundTime) {
			return;
		}

		nextAmbientSoundTime = gameTime + MIN_AMBIENT_SOUND_DELAY + level.random.nextInt(AMBIENT_SOUND_DELAY_VARIATION);
		CapturedMob capturedMob = capturedMobs.get(level.random.nextInt(capturedMobs.size()));
		getAmbientSound(capturedMob, level).ifPresent(sound -> level.playLocalSound(entity.getX(), entity.getY(), entity.getZ(), sound, SoundSource.PLAYERS,
				MUFFLED_AMBIENT_VOLUME + level.random.nextFloat() * MUFFLED_AMBIENT_VOLUME_VARIATION,
				MUFFLED_AMBIENT_PITCH + (level.random.nextFloat() - 0.5F) * MUFFLED_AMBIENT_PITCH_VARIATION, false));
	}

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.herd == null) {
                IPackEntity.initPack(this);
            }
            else {
                this.herd.tick();
            }
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            int i = this.random.nextInt(3000);
            if (i == 13 && !this.isInWater() && this.getTarget() == null && this.isNotMoving() && this.canMove() && this.getAnimation() == NO_ANIMATION) {
                this.setSitting(true);
            }
            if (i == 14 && this.isSitting()) {
                this.setSitting(false);
            }
            this.setAngry(this.getTarget() != null);
        }
        else {
            if (this.getAnimation() == ATTACK_THREATEN) {
                this.setSprinting(this.getAnimationTick() % 18 < 6);
            }
        }
        super.aiStep();
    }

private static void tryProvideFluids(AbstractLogisticsFrameEntity provider, AbstractLogisticsFrameEntity requester, PriorityQueue<LogisticsTask> tasks) {
        IOHelper.getFluidHandlerForBlock(provider.getCachedTileEntity(), provider.getSide()).ifPresent(providerHandler -> {
            CountedFluidStacks counted;
            int keepStock = 0;
            if (provider instanceof ISpecificProvider sp && sp.getKeepFluidStocked() > 0) {
                counted = new CountedFluidStacks(providerHandler);
                keepStock = sp.getKeepFluidStocked();
            } else {
                counted = null;
            }

            FluidStack providingStack = providerHandler.drain(16000, IFluidHandler.FluidAction.SIMULATE);
            if (!providingStack.isEmpty()) {
                boolean canDrain = IntStream.range(0, providerHandler.getTanks()).anyMatch(i -> providerHandler.isFluidValid(i, providingStack));
                if (canDrain && (!(provider instanceof ISpecificProvider sp) || sp.canProvide(providingStack))) {
                    int requested = getRequestedAmount(requester, providingStack, true);
                    if (requested > 0) {
                        if (counted != null) {
                            int remaining = counted.getInt(providingStack) - requested - keepStock;
                            if (remaining < 0) {
                                // reduce amount if needed so stock levels are honoured
                                requested += remaining;
                            }
                            counted.adjust(providingStack, -requested);
                        }
                        tasks.add(new LogisticsTask(provider, requester, providingStack.copyWithAmount(requested)));
                    }
                }
            }
        });
    }

@Override
    public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
        Player player = commonArmorHandler.getPlayer();

        if (player.level().isClientSide || player.isSpectator() || !enabled
                || (player.level().getGameTime() & 0x3) != 0
                || !commonArmorHandler.hasMinPressure(EquipmentSlot.CHEST))
            return;

        int magnetRadius = PneumaticValues.MAGNET_BASE_RANGE
                + Math.min(commonArmorHandler.getUpgradeCount(EquipmentSlot.CHEST, ModUpgrades.MAGNET.get()), PneumaticValues.MAGNET_MAX_UPGRADES);
        int magnetRadiusSq = magnetRadius * magnetRadius;

        AABB box = new AABB(player.blockPosition()).inflate(magnetRadius);
        List<Entity> itemList = player.getCommandSenderWorld().getEntitiesOfClass(Entity.class, box,
                e -> (e instanceof ExperienceOrb || e instanceof ItemEntity) && e.isAlive());

        Vec3 playerVec = player.position();
        for (Entity item : itemList) {
            if (item instanceof ItemEntity && ((ItemEntity) item).hasPickUpDelay()) continue;

            if (item.position().distanceToSqr(playerVec) <= magnetRadiusSq
                    && !ItemRegistry.getInstance().shouldSuppressMagnet(item)
                    && !item.getPersistentData().getBoolean(Names.PREVENT_REMOTE_MOVEMENT)) {
                if (!commonArmorHandler.hasMinPressure(EquipmentSlot.CHEST)) break;
                item.setPos(player.getX(), player.getY(), player.getZ());
                if (item instanceof ItemEntity) ((ItemEntity) item).setPickUpDelay(0);
                commonArmorHandler.addAir(EquipmentSlot.CHEST, -ConfigHelper.common().armor.magnetAirUsage.get());
            }
        }
    }

default void setCooldown(World world, @Nullable EntityPlayer player, @Nullable EnumHand hand, ItemStack stack, @Nonnull SpellData data) {
		int maxCooldown = 0;

		List<SpellRing> rings = SpellUtils.getAllSpellRings(stack);

		for (SpellRing ring : rings) {
			if (ring.isContinuous()) return;

			if (ring.getModule() != null && ring.getModule().getModuleClass() instanceof IOverrideCooldown) {

				maxCooldown = ring.getCooldownTime(world, data);
				break;
			}
			if (ring.getCooldownTime() > maxCooldown)
				maxCooldown = ring.getCooldownTime();
		}

		if (maxCooldown <= 0) return;

		if (player != null && hand != null) {
			player.stopActiveHand();
			player.swingArm(hand);
			if (!world.isRemote)
				if (hand == EnumHand.MAIN_HAND)
					PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(true, false), (EntityPlayerMP) player);
				else PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(false, true), (EntityPlayerMP) player);
		}

		NBTHelper.setInt(stack, NBTConstants.NBT.LAST_COOLDOWN, maxCooldown);
		NBTHelper.setLong(stack, NBTConstants.NBT.LAST_CAST, world.getTotalWorldTime());
	}

public static boolean createPortal(Player player, Level level, BlockPos pos, @Nullable Direction direction, ItemStack stack, InteractionHand hand) {
        if (!level.isClientSide()) {
            if (!ModList.get().isLoaded("immersive_portals_core") || !AetherConfig.COMMON.enable_immersive_portals_compatibility.get()) {
                if (direction != null) {
                    BlockPos relativePos = pos.relative(direction);
                    if (stack.is(AetherTags.Items.AETHER_PORTAL_ACTIVATION_ITEMS)) { // Checks if the item can activate the portal.
                        // Checks whether the dimension can have a portal created in it, and that the portal isn't disabled.
                        if ((level.dimension() == LevelUtil.returnDimension() || level.dimension() == LevelUtil.destinationDimension())) {
                            Optional<AetherPortalShape> optional = AetherPortalShape.findEmptyAetherPortalShape(level, relativePos, Direction.Axis.X);
                            if (optional.isPresent()) {
                                PacketDistributor.sendToAllPlayers(new PortalInteractPacket(player.getId(), hand == InteractionHand.MAIN_HAND));
                                optional.get().createPortalBlocks();
                                if (!player.isCreative()) {
                                    if (stack.getCount() > 1) {
                                        stack.shrink(1);
                                        player.addItem(stack.hasCraftingRemainingItem() ? stack.getCraftingRemainingItem() : ItemStack.EMPTY);
                                    } else if (stack.isDamageableItem()) {
                                        stack.hurtAndBreak(1, player, LivingEntity.getSlotForHand(hand));
                                    } else {
                                        player.setItemInHand(hand, stack.hasCraftingRemainingItem() ? stack.getCraftingRemainingItem() : ItemStack.EMPTY);
                                    }
                                }
                                return true;
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

@Override
    public void tick(Level level) {
        if (!(level instanceof ServerLevel serverLevel))
            return;

        if (!isActive()) {
            if (this.nextSandstorm == -1)
                this.nextSandstorm = serverLevel.getGameTime() + this.interval.sample(serverLevel.getRandom());

            if (this.nextSandstorm <= serverLevel.getGameTime())
                start(serverLevel);

            return;
        }

        if (this.sandstormEndTime >= 0 && this.sandstormEndTime <= serverLevel.getGameTime()) {
            stop(serverLevel);

            return;
        }

        if (getIntensity(serverLevel.getGameTime()) >= 1 && serverLevel.getGameTime() % 10 == 0) {
            DamageSource source = DamageUtil.miscDamage(AoADamageTypes.SANDSTORM, serverLevel);

            Streams.stream(serverLevel.getEntities().getAll())
                    .filter(LivingEntity.class::isInstance)
                    .map(LivingEntity.class::cast)
                    .filter(this::isEntityAffected)
                    .forEach(entity -> entity.hurt(source, this.damage.sample(serverLevel.getRandom())));
        }
    }

private void handleItemSmelting(final RetrieveSmeltedItemEvent ev) {
		ItemStack baseStack = ev.getOriginalStack();
		ItemStack smeltedStack = ev.getOutputStack();

		if (!smeltedStack.has(DataComponents.FOOD) && !smeltedStack.is(AoATags.Items.NO_BONUS_SMELT_RESULT)) {
			int additional = 0;
			Player player = ev.getEntity();

			this.random.setSeed(this.uniqueIdHash * player.level().getGameTime() - (player.level().isClientSide ? 0 : 1) >> 4);
			this.random.setSeed(this.random.nextLong());
			this.random.setSeed(this.random.nextLong());

			for (int i = 0; i < baseStack.getCount(); i++) {
				if (this.random.nextFloat() < getScaledValue())
					additional++;
			}

			if (additional > 0) {
				int stackSize = smeltedStack.getMaxStackSize();

				while (smeltedStack.getCount() + additional > stackSize) {
					if (player instanceof ServerPlayer pl)
						InventoryUtil.giveItemTo(pl, smeltedStack.copyWithCount(stackSize));

					additional -= stackSize;
				}

				smeltedStack.setCount(smeltedStack.getCount() + additional);
			}
		}
	}

public boolean onUsedByWand(Player player, ItemStack stack, Level world, BlockPos pos) {
		if (world.isClientSide) {
			return false;
		}

		if (player == null || player.isShiftKeyDown()) {
			world.destroyBlock(pos, true);
		} else {
			GlobalPos clicked = GlobalPos.of(world.dimension(), pos.immutable());
			if (WandOfTheForestItem.getBindMode(stack)) {
				activeBindingAttempts.put(player.getUUID(), clicked);
				world.playSound(null, pos, BotaniaSounds.ding, SoundSource.BLOCKS, 0.5F, 1F);
			} else {
				var data = WorldData.get(world);
				if (XplatAbstractions.INSTANCE.isDevEnvironment()) {
					BotaniaAPI.LOGGER.info("PistonRelay pairs");
					for (var e : data.mapping.entrySet()) {
						BotaniaAPI.LOGGER.info("{} -> {}", e.getKey(), e.getValue());
					}
				}
				BlockPos dest = data.mapping.get(pos);
				if (dest != null) {
					XplatAbstractions.INSTANCE.sendToNear(world, pos, new BotaniaEffectPacket(EffectType.PARTICLE_BEAM,
							pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
							dest.getX(), dest.getY(), dest.getZ()));
				}
			}
		}

		return true;
	}

@Override
	public void tick() {
		super.tick();

		ItemStack item = getItem(0);
		if(item.isEmpty()) {
			if(matrix != null) {
				matrixDirty = true;
				matrix = null;
			}
		} else {
			loadMatrix(item);

			if(level.getGameTime() % 20 == 0 || matrixDirty)
				updateEnchantPower();
		}

		if(charge <= 0 && !level.isClientSide) {
			ItemStack lapis = getItem(1);
			if(!lapis.isEmpty()) {
				lapis.shrink(1);
				charge += MatrixEnchantingModule.chargePerLapis;
				sync();
			}
		}

		if(matrixDirty) {
			makeOutput();
			matrixDirty = false;
		}
	}

public static boolean requestShare() {
			Minecraft mc = Minecraft.getInstance();
			if(mc.level == null || !Screen.hasShiftDown())
				return false;

			if(!(mc.screen instanceof AbstractContainerScreen<?> gui))
				return false;

			for(GuiEventListener c : gui.children())
				if(c instanceof EditBox tf)
					if(tf.isFocused())
						return false;

			Slot slot = gui.getSlotUnderMouse();
			if(slot == null)
				return false;

			ItemStack stack = slot.getItem();
			if(stack.isEmpty())
				return false;

			if(mc.level.getGameTime() - lastClientShare > cooldown) {
				lastClientShare = mc.level.getGameTime();
			} else
				return false;

			//TODO: smuggle into a correctly signed chat message, so stuff like discord integration picks up on it

			PacketDistributor.sendToServer(new ShareItemC2SMessage(stack));
			return true;
		}

