public static @Nullable EnchantedFallingBlock fall(Level level, BlockPos pos, Entity owner, SpellContext context, SpellResolver resolver, SpellStats spellStats) {
        if (!canFall(level, pos, owner, spellStats)) return null;
        BlockState blockState = level.getBlockState(pos);
        EnchantedFallingBlock fallingblockentity;
        if (level.getBlockEntity(pos) instanceof MageBlockTile tile) {
            fallingblockentity = new EnchantedMageblock(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState);
            fallingblockentity.resolver = resolver;
        } else if (level.getBlockEntity(pos) instanceof SkullBlockEntity tile) {
            fallingblockentity = new EnchantedSkull(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState);
        } else {
            fallingblockentity = new EnchantedFallingBlock(level, pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D, blockState.hasProperty(BlockStateProperties.WATERLOGGED) ? blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE) : blockState, resolver);
        }
        if (level.getBlockEntity(pos) != null) {
            fallingblockentity.blockData = level.getBlockEntity(pos).saveWithoutMetadata(level.registryAccess());
        }
        level.addFreshEntity(fallingblockentity);
        fallingblockentity.setOwner(owner);
        fallingblockentity.context = context;
        fallingblockentity.baseDamage = (float) (9.0f + spellStats.getDamageModifier());
        fallingblockentity.dropItem = !blockState.is(BlockTagProvider.GRAVITY_BLACKLIST);
        fallingblockentity.spellStats = spellStats;
        if (resolver.hasFocus(ItemsRegistry.SHAPERS_FOCUS.get())) {
            fallingblockentity.hurtEntities = true;
        }
        if (context != null) {
            RewindAttachment rewindAttachment = RewindAttachment.get(context);
            rewindAttachment.addRewindEvent(level.getGameTime(), new BlockToEntityRewind(pos, blockState));
        }
        level.setBlock(pos, blockState.getFluidState().createLegacyBlock(), 3);
        return fallingblockentity;
    }

@Override
    protected void actuallyHurt(ServerLevel level, DamageSource source, float amount) {
        LivingEntity livingentity = this.getTarget();
        if (livingentity != null
                && (double) this.random.nextFloat() < this.getAttributeValue(Attributes.SPAWN_REINFORCEMENTS_CHANCE)
                && level.getGameRules().get(GameRules.SPAWN_MOBS)) {

            long currentGameTime = level.getGameTime();

            // Reset the counter if the time window has passed
            synchronized (PossessedBeeEntity.class) {
                if (currentGameTime - lastResetGameTime > TIME_WINDOW_TICKS) {
                    beeSpawnCounter.set(0);
                    lastResetGameTime = currentGameTime;
                }
            }

            // Check if the spawn limit has been reached
            if (beeSpawnCounter.get() < MAX_BEES_PER_TIME) {
                Bee bee = OccultismEntities.POSSESSED_BEE.get().create(level, EntitySpawnReason.REINFORCEMENT);
                double offsetX = level.getRandom().nextGaussian() * (1 + level.getRandom().nextInt(4));
                double offsetZ = level.getRandom().nextGaussian() * (1 + level.getRandom().nextInt(4));
                bee.snapTo(this.getBlockX() + offsetX, this.getBlockY() + 1.5, this.getBlockZ() + offsetZ, level.getRandom().nextInt(360), 0);
                level.addFreshEntity(bee);

                // Increment the counter
                beeSpawnCounter.incrementAndGet();
            }
        }
        super.actuallyHurt(level, source, amount);
    }

@Override
        public void recheckCanSeeSun() {
            if (!world.dimensionType().hasSkyLight() || world.getSkyDarken() >= 4) {
                //Inline of most of WorldUtils#canSeeSun so that we can exit early if it is not day or there is no skylight
                // We start with the basic dimension checks and always run those, as they are simple and quick checks, and
                // we want to be able to stop quickly when it gets too dark
                canSeeSun = false;
                return;
            }
            long time = world.getGameTime();
            if (time < lastCheckedSun + recheckFrequency) {
                //If we have checked for blocks above the solar panel in the past recheckFrequency
                // number of ticks, skip checking for now for performance reasons
                return;
            }
            // otherwise, mark that we checked and actually check
            lastCheckedSun = time;
            if (world.getFluidState(pos).isEmpty()) {
                //If the top isn't fluid logged we can just quickly check if the top can see the sun
                canSeeSun = world.canSeeSky(pos);
            } else {
                BlockPos above = pos.above();
                if (world.canSeeSky(above)) {
                    //If the spot above can see the sun, check to make sure we can see through the block there
                    BlockState state = world.getBlockState(above);
                    canSeeSun = !state.liquid() && state.getLightDampening() <= 0;
                } else {
                    canSeeSun = false;
                }
            }
        }

NETWORK getNetworkFromOrphan(Long2ObjectMap<Transmitter<?, ?, ?>> orphanTransmitters) {
            //Calculate the network
            if (queue.peek() != null) {
                Mekanism.logger.error("OrphanPathFinder queue was not empty?!");
                queue.clear();
            }
            queue.push(startPoint.getBlockPos());
            while (queue.peek() != null) {
                iterate(orphanTransmitters, queue.removeFirst());
            }
            //Create the network or grab the found ones
            NETWORK network;
            if (networksFound.size() == 1) {
                if (MekanismAPI.debug) {
                    Mekanism.logger.info("Adding {} transmitters to single found network", connectedTransmitters.size());
                }
                network = networksFound.iterator().next();
            } else {
                if (MekanismAPI.debug) {
                    if (networksFound.isEmpty()) {
                        Mekanism.logger.info("No networks found. Creating new network for {} transmitters", connectedTransmitters.size());
                    } else {
                        Mekanism.logger.info("Merging {} networks with {} new transmitters", networksFound.size(), connectedTransmitters.size());
                    }
                }
                //TODO: Should we take one of the existing network's uuids if there is one?
                network = startPoint.createNetworkByMerging(networksFound);
            }
            network.addNewTransmitters(connectedTransmitters, transmitterValidator);
            return network;
        }

private void iterate(Long2ObjectMap<Transmitter<?, ?, ?>> orphanTransmitters, BlockPos from) {
            if (iterated.add(from)) {
                Transmitter<?, ?, ?> transmitter = orphanTransmitters.get(from.asLong());
                if (transmitter != null) {
                    if (transmitter.isValid() && transmitter.isOrphan() && startPoint.supportsTransmissionType(transmitter) &&
                        transmitterValidator.isTransmitterCompatible(transmitter)) {
                        connectedTransmitters.add((TRANSMITTER) transmitter);
                        transmitter.setOrphan(false);
                        BlockPos.MutableBlockPos directionPos = new BlockPos.MutableBlockPos();
                        for (Direction direction : EnumUtils.DIRECTIONS) {
                            directionPos.setWithOffset(from, direction);
                            if (!iterated.contains(directionPos)) {
                                TileEntityTransmitter tile = WorldUtils.getTileEntity(TileEntityTransmitter.class, world, chunkMap, directionPos);
                                if (tile != null && transmitter.isValidTransmitterBasic(tile, direction)) {
                                    queue.addLast(directionPos.immutable());
                                }
                            }
                        }
                    }
                } else {
                    TileEntityTransmitter tile = WorldUtils.getTileEntity(TileEntityTransmitter.class, world, chunkMap, from);
                    if (tile != null && startPoint.supportsTransmissionType(tile)) {
                        NETWORK net = (NETWORK) tile.getTransmitter().getTransmitterNetwork();
                        //Make sure that there is an external network
                        if (net != null && transmitterValidator.isNetworkCompatible(net)) {
                            networksFound.add(net);
                        }
                    }
                }
            }
        }

private static RecipeMap loadVanillaRecipeRegistry(RegistryAccess registryAccess) {
		var recipeRegistryData = RegistryDataLoader.RELOADABLE_REGISTRIES.stream()
			.filter(registryData -> registryData.key().equals(Registries.RECIPE))
			.toList();
		try (CloseableResourceManager resourceManager = new MultiPackResourceManager(
			PackType.SERVER_DATA,
			List.of(ServerPacksSource.createVanillaPackSource().fullResources())
		)) {
			RegistryAccess.Frozen baseRegistryAccess = registryAccess.freeze();
			List<Registry.PendingTags<?>> basePendingTags = TagLoader.loadTagsForExistingRegistries(resourceManager, baseRegistryAccess);
			List<HolderLookup.RegistryLookup<?>> baseLookups = TagLoader.buildUpdatedLookups(baseRegistryAccess, basePendingTags);
			RegistryAccess.Frozen worldRegistryAccess = RegistryDataLoader.load(resourceManager, baseLookups, RegistryDataLoader.WORLD_REGISTRIES, Runnable::run)
				.join();
			List<Registry.PendingTags<?>> worldPendingTags = TagLoader.loadTagsForExistingRegistries(resourceManager, worldRegistryAccess);
			List<HolderLookup.RegistryLookup<?>> worldLookups = TagLoader.buildUpdatedLookups(worldRegistryAccess, worldPendingTags);
			var existingRegistryKeys = baseLookups.stream()
				.map(HolderLookup.RegistryLookup::key)
				.toList();
			List<HolderLookup.RegistryLookup<?>> updatedLookups = Stream.concat(
					baseLookups.stream(),
					worldLookups.stream()
						.filter(lookup -> !existingRegistryKeys.contains(lookup.key()))
				)
				.toList();
			RegistryAccess.Frozen recipeRegistryAccess = RegistryDataLoader.load(resourceManager, updatedLookups, recipeRegistryData, Runnable::run)
				.join();
			basePendingTags.forEach(Registry.PendingTags::apply);
			worldPendingTags.forEach(Registry.PendingTags::apply);
			return RecipeMap.create(recipeRegistryAccess.lookupOrThrow(Registries.RECIPE));
		}
	}

public boolean canUse() {
        long i = this.mob.level().getGameTime();

        if (i - this.lastCanUseCheck < 20L) {
            return false;
        } else {
            this.lastCanUseCheck = i;
            LivingEntity livingentity = this.mob.getTarget();
            if (livingentity == null) {
                return false;
            } else if (!livingentity.isAlive()) {
                return false;
            } else {
                if (canPenalize) {
                    if (--this.ticksUntilNextPathRecalculation <= 0) {
                        this.path = this.mob.getNavigation().createPath(livingentity, 0);
                        this.ticksUntilNextPathRecalculation = 4 + this.mob.getRandom().nextInt(7);
                        return this.path != null;
                    } else {
                        return true;
                    }
                }
                this.path = this.mob.getNavigation().createPath(livingentity, 0);
                if (this.path != null) {
                    return true;
                } else {
                    return this.getAttackReachSqr(livingentity) >= this.mob.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
                }
            }
        }
    }

