@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        if (shouldReload || !calculateOverlayBounds().equals(bounds)) {
            init();
            getEntryListWidget().updateSearch(REIRuntimeImpl.getSearchField().getText(), true);
        } else {
            for (OverlayDecider decider : ScreenRegistry.getInstance().getDeciders(minecraft.gui.screen())) {
                if (decider != null && decider.shouldRecalculateArea(ConfigObject.getInstance().getDisplayPanelLocation(), bounds)) {
                    init();
                    break;
                }
            }
        }
        if (shouldReloadSearch || (ConfigManager.getInstance().isCraftableOnlyEnabled() && CraftableFilter.INSTANCE.wasDirty())) {
            shouldReloadSearch = false;
            getEntryListWidget().updateSearch(REIRuntimeImpl.getSearchField().getText(), true);
        }
        if (OverlaySearchField.isHighlighting) {
            EntryHighlighter.render(graphics);
        }
        if (!hasSpace()) return;
        this.renderWidgets(graphics, mouseX, mouseY, delta);
        if (ConfigObject.getInstance().areClickableRecipeArrowsEnabled()) {
            Screen screen = Minecraft.getInstance().gui.screen();
            ClickArea.ClickAreaContext<Screen> context = createClickAreaContext(mouseX, mouseY, screen);
            List<Component> clickAreaTooltips = ScreenRegistry.getInstance().getClickAreaTooltips((Class<Screen>) screen.getClass(), context);
            if (clickAreaTooltips != null && !clickAreaTooltips.isEmpty()) {
                Tooltip.create(clickAreaTooltips).queue();
            }
        }
    }

public static void tick(Level level, BlockPos pos, BlockState state, ElderEyeBlockEntity elderEye) {
		if (level.getGameTime() % 4 == 0 && !level.isClientSide && state.getValue(ElderEyeBlock.ACTIVE)) {
			if (!(state.getBlock() instanceof ElderEyeBlock)) return;

			Direction facing = state.getValue(ElderEyeBlock.FACING);
			int range = calcRange(level, pos, facing);
			AABB bb = new AABB(0, 0, 0, 1, 1, 1).move(pos.relative(facing)).expandTowards(facing.getStepX() * range, 0, facing.getStepZ() * range);
			boolean hasEntity = level.getEntitiesOfClass(Entity.class, bb).size() > 0;

			int entityDistance = -1;
			if (hasEntity) {
				for (int i = 1; i < range; i++) {
					BlockPos newPos = pos.relative(facing, i);
					if (level.getEntitiesOfClass(LivingEntity.class, new AABB(0, 0, 0, 1, 1, 1).move(newPos)).size() > 0) {
						entityDistance = i;
						break;
					}
				}
			}

			BlockState newState = state.setValue(ElderEyeBlock.POWER, 0);
			if (hasEntity && entityDistance > -1) {
				newState = state.setValue(ElderEyeBlock.POWER, 16 - entityDistance);
			}

			if (state != newState) {
				level.setBlockAndUpdate(pos, newState);
				((ElderEyeBlock) state.getBlock()).updateRedstoneNeighbors(state, level, pos);
			}
		}
	}

public static void handle(MessageHurtMultipart message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            context.get().enqueueWork(() -> {
                Player player = context.get().getSender();
                if (context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                    player = AlexsMobs.PROXY.getClientSidePlayer();
                }

                if (player != null) {
                    if (player.level() != null) {
                        Entity part = player.level().getEntity(message.part);
                        Entity parent = player.level().getEntity(message.parent);
                        Registry<DamageType> registry = player.level().registryAccess().registry(Registries.DAMAGE_TYPE).get();
                        DamageType dmg = registry.get(new ResourceLocation(message.damageType));
                        if (dmg != null) {
                            Holder<DamageType> holder = registry.getHolder(registry.getId(dmg)).orElseGet(null);
                            if (holder != null) {
                                DamageSource source = new DamageSource(registry.getHolder(registry.getId(dmg)).get());
                                if (part instanceof IHurtableMultipart && parent instanceof LivingEntity) {
                                    ((IHurtableMultipart) part).onAttackedFromServer((LivingEntity) parent, message.damage, source);
                                }
                                if (part == null && parent != null && parent.isMultipartEntity()) {
                                    parent.hurt(source, message.damage);
                                }

                            }
                        }

                    }
                }
            });
        }

