        if (this.level.isClientSide) {
            for (int k = 0; k < 5; ++k) {
                double d2 = 0.4;
                double d0 = 0.1;
                double d1 = 0.1;
                IceAndFire.PROXY.spawnParticle(EnumParticles.Blood, this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getY(), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), d2, d0, d1);
            }
        }
        if (this.deathTime >= 200) {
            if (!this.level.isClientSide && (this.isAlwaysExperienceDropper() || this.lastHurtByPlayerTime > 0 && this.shouldDropExperience() && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS))) {
                int i = this.getExperienceReward(this.lastHurtByPlayer);
                i = net.minecraftforge.event.ForgeEventFactory.getExperienceDrop(this, this.lastHurtByPlayer, i);
                while (i > 0) {
                    int j = ExperienceOrb.getExperienceValue(i);
                    i -= j;
                    this.level.addFreshEntity(new ExperienceOrb(this.level, this.getX(), this.getY(), this.getZ(), j));
                }
            }
            this.remove(RemovalReason.KILLED);

            for (int k = 0; k < 20; ++k) {
                double d2 = this.random.nextGaussian() * 0.02D;
                double d0 = this.random.nextGaussian() * 0.02D;
                double d1 = this.random.nextGaussian() * 0.02D;
                this.level.addParticle(ParticleTypes.CLOUD, this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getY() + (double) (this.random.nextFloat() * this.getBbHeight()), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), d2, d0, d1);
            }
        }
    }

@Override
	public void onEntityCollision(IMultiblockContext<State> ctx, BlockPos posInMultiblock, Entity entity)
	{
		final Level world = ctx.getLevel().getRawLevel();
		if(world.isClientSide||!INPUT_POS.posInMultiblock().equals(posInMultiblock))
			return;
		if(entity instanceof ItemEntity itemEntity&&entity.isAlive()&&!itemEntity.getItem().isEmpty())
		{
			ItemStack stack = itemEntity.getItem();
			if(stack.isEmpty())
				return;
			final State state = ctx.getState();
			RecipeHolder<MetalPressRecipe> recipe = MetalPressRecipe.findRecipe(state.mold, stack, world);
			if(recipe==null)
				return;
			ItemStack displayStack = recipe.value().getDisplayStack(stack);
			MultiblockProcessInWorld<MetalPressRecipe> process;
			if(recipe.value() instanceof RecipeDelegate delegate)
				process = new SpecialMetalPressProcess(recipe.id(), delegate, displayStack);
			else
				process = new MultiblockProcessInWorld<>(recipe, displayStack);

			if(state.processor.addProcessToQueue(process, world, false))
			{
				ItemStack remaining = stack.copy();
				remaining.shrink(displayStack.getCount());
				itemEntity.setItem(remaining);
				if(remaining.isEmpty())
					entity.discard();
			}
		}
	}

public boolean advanceCurrentPos() {
		List<Entity> entities = blockReader.getEntityList();

		do {
			if (printStage == PrintStage.BLOCKS) {
				while (tryAdvanceCurrentPos()) {
					deferredBlocks.add(currentPos);
				}
			}

			if (printStage == PrintStage.DEFERRED_BLOCKS) {
				if (deferredBlocks.isEmpty()) {
					printStage = PrintStage.ENTITIES;
				} else {
					currentPos = deferredBlocks.remove(0);
				}
			}

			if (printStage == PrintStage.ENTITIES) {
				if (printingEntityIndex + 1 < entities.size()) {
					printingEntityIndex++;
					currentPos = entities.get(printingEntityIndex).blockPosition().subtract(schematicAnchor);
				} else {
					// Reached end of printing
					return false;
				}
			}
		} while (!blockReader.getBounds().isInside(currentPos));

		// More things available to print
		return true;
	}

public int addAlly(CommandSourceStack source, Collection<NameAndId> players) throws CommandSyntaxException {
		if (source.getPlayer() != null && !FTBTUtils.canPlayerUseCommand(source.getPlayer(), "ftbteams.party.allies.add")) {
			throw TeamArgument.NO_PERMISSION.create();
		}

		UUID from = source.getEntity() == null ? Util.NIL_UUID : source.getEntity().getUUID();

		List<NameAndId> addedPlayers = new ArrayList<>();
		for (NameAndId player : players) {
			UUID id = player.id();

			if (!isAllyOrBetter(id)) {
				ranks.put(id, TeamRank.ALLY);
				sendMessage(from, Component.translatable("ftbteams.message.add_ally",
						manager.getPlayerName(id).copy().withStyle(ChatFormatting.YELLOW)).withStyle(ChatFormatting.GREEN));
				addedPlayers.add(player);
				ServerPlayer invitedPlayer = manager.getServer().getPlayerList().getPlayer(id);
				if (invitedPlayer != null) {
					invitedPlayer.sendSystemMessage(Component.translatable("ftbteams.message.now_allied", getDisplayName()).withStyle(ChatFormatting.GREEN));
				}
			}
		}

		if (!addedPlayers.isEmpty()) {
			markDirty();
			manager.syncToAll(this);
			NativeEventPosting.INSTANCE.postEvent(new TeamAllyEvent.Data(this, addedPlayers, true));
			return Command.SINGLE_SUCCESS;
		}

		return 0;
	}

public static <T> Set<T> conditionalSearch(Class<T> clazz, T start, @Nullable Level level,
                                               Function<T, @NotNull BlockPos> posGetter,
                                               TriPredicate<T, T, Direction> condition,
                                               int blockLimit, int iterationLimit) {
        if (level == null) return Collections.emptySet();

        var passed = new LinkedHashSet<T>();
        var queue = new ObjectArrayFIFOQueue<Triple<T, T, Direction>>(16);
        queue.enqueue(new ImmutableTriple<>(null, start, null));

        var iterations = 0;
        while (!queue.isEmpty() && iterations < iterationLimit && passed.size() < blockLimit) {
            var tuple = queue.dequeue();
            var next = tuple.getMiddle();
            if (passed.contains(next)) {
                continue;
            }
            if (condition.test(tuple.getLeft(), next, tuple.getRight())) {
                passed.add(next);
                for (var direction : GTUtil.DIRECTIONS) {
                    var neighbor = level.getBlockEntity(posGetter.apply(next).relative(direction));
                    if (!clazz.isInstance(neighbor)) continue;
                    T casted = clazz.cast(neighbor);
                    if (passed.contains(casted)) continue;
                    queue.enqueue(new ImmutableTriple<>(next, casted, direction));
                }
            }
            iterations++;
        }

        return passed;
    }

@Override
    public final void tick() {
        // heartbeat first — it must beat during the start delay too
        if (tickHost != null) {
            lastHostTick = tickHost.tickCount();
        }
        lastTick++;
        if (delay > 0) {
            delay--;
            return;
        }
        // drive the timeline (root only) once the start delay has elapsed
        if (onUpdateTick != null) {
            onUpdateTick.run();
        }
        // inactive (timeline) nodes and their descendants neither tick nor render
        if (!isActive()) {
            return;
        }
        // snapshot the render origin (xo=x) ONCE per tick, before sub-stepping, so a frozen object holds
        // still (no xo!=x jitter) and a sped-up one interpolates the whole tick (not just the last step).
        onTickBegin();
        // advance the simulation by this tick's scaled dt (speed track). dt is sampled from the master
        // clock so it stays reproducible under simulateTo; default timeScale()==1 => one updateTick(1f).
        float owed = timeScale();
        int guard = 0;
        while (owed > 1e-6f && guard++ < MAX_SUBSTEPS) {
            float step = Math.min(owed, 1f); // <=1 keeps integration/collision stable at high speed
            updateTick(step);
            owed -= step;
        }
    }

@Override
    public void onPlayerTickActive(EntityPlayer player, ItemStack item) {
        if (MuseItemUtils.getWaterLevel(item) > ModuleManager.computeModularProperty(item, WATER_TANK_SIZE)) {
            MuseItemUtils.setWaterLevel(item, ModuleManager.computeModularProperty(item, WATER_TANK_SIZE));
        }

        // Fill tank if player is in water
        Block block = player.worldObj.getBlockState(player.getPosition()).getBlock();
        if (((block == Blocks.WATER) || block == Blocks.FLOWING_WATER) && MuseItemUtils.getWaterLevel(item) < ModuleManager.computeModularProperty(item, WATER_TANK_SIZE)) {
            MuseItemUtils.setWaterLevel(item, MuseItemUtils.getWaterLevel(item) + 1);
        }

        // Fill tank if raining
        int xCoord = MathHelper.floor_double(player.posX);
        int zCoord = MathHelper.floor_double(player.posZ);
        boolean isRaining = (player.worldObj.getBiomeForCoordsBody(player.getPosition()).getRainfall() > 0) && (player.worldObj.isRaining() || player.worldObj.isThundering());
        if (isRaining && player.worldObj.canBlockSeeSky(player.getPosition().add(0,1,0))
                && (player.worldObj.getTotalWorldTime() % 5) == 0 && MuseItemUtils.getWaterLevel(item) < ModuleManager.computeModularProperty(item, WATER_TANK_SIZE)) {
            MuseItemUtils.setWaterLevel(item, MuseItemUtils.getWaterLevel(item) + 1);
        }

        // Apply cooling
        double currentHeat = MuseHeatUtils.getPlayerHeat(player);
        double maxHeat = MuseHeatUtils.getMaxHeat(player);
        if ((currentHeat / maxHeat) >= ModuleManager.computeModularProperty(item, ACTIVATION_PERCENT) && MuseItemUtils.getWaterLevel(item) > 0) {
            MuseHeatUtils.coolPlayer(player, 1);
            MuseItemUtils.setWaterLevel(item, MuseItemUtils.getWaterLevel(item) - 1);
            for (int i = 0; i < 4; i++) {
                player.worldObj.spawnParticle(EnumParticleTypes.SMOKE_NORMAL, player.posX, player.posY + 0.5, player.posZ, 0.0D, 0.0D, 0.0D);
            }
        }
    }

public void build(DeferredRegister<Block> blocks, DeferredRegister<Item> items) {
            if (FMLEnvironment.dist.isClient()) {
                MultiblockSchematicScrollHandler.setupSchematic(identifier, width * height);
            }
            for (int i = 0; i < width; i++) {
                for (int j = 0; j < height; j++) {
                    int x = i;
                    int y = j;

                    String ruinedId = String.format(ruinedFormat, identifier, x, y);
                    ResourceLocation brokenPryTable = new ResourceLocation("tetra", pryTablePrefix + ruinedId);
                    RegistryObject<RuinedMultiblockSchematicBlock> ruinedRef = blocks.register(ruinedId, () -> new RuinedMultiblockSchematicBlock(ruinedProperties, brokenPryTable));

                    String id = String.format(format, identifier, x, y);
                    ResourceLocation pryTable = new ResourceLocation("tetra", pryTablePrefix + id);
                    RegistryObject<MultiblockSchematicBlock> ref = x == width / 2 && y == height / 2
                            ? blocks.register(id, () -> new PrimaryMultiblockSchematicBlock(properties, identifier, ruinedRef, pryTable, x, y, height, width))
                            : blocks.register(id, () -> new MultiblockSchematicBlock(properties, identifier, ruinedRef, pryTable, x, y, height, width));


                    items.register(id, () -> {
                        StackedMultiblockSchematicItem item = new StackedMultiblockSchematicItem(ref.get(), ruinedRef.get());
                        if (FMLEnvironment.dist.isClient()) {
                            MultiblockSchematicScrollHandler.addSchematic(identifier, y * width + x, item);
                        }
                        return item;
                    });
                    items.register(ruinedId, () -> new RuinedMultiblockSchematicItem(ruinedRef.get(), ref.get()));

                }
            }
        }

private int executeAddModifier(CommandContext<CommandSourceStack> context, Collection<? extends Entity> entities, Temperature.Trait trait, ResourceLocation modifierId,
                                   int duration, int tickRate, CompoundTag nbt, Mode mode, Order order, ResourceLocation otherId, int maxCount)
    {
        CommandSourceStack source = context.getSource();
        if (entities.stream().anyMatch(entity -> !(entity instanceof Player || EntityTempManager.isTemperatureEnabled(entity))))
        {   source.sendFailure(Component.translatable("commands.cold_sweat.temperature.invalid"));
            return 0;
        }
        Optional<TempModifier> modifierOpt = TempModifierRegistry.getValue(modifierId);
        if (modifierOpt.isEmpty())
        {   source.sendFailure(Component.translatable("commands.cold_sweat.temp_modifier.invalid"));
            return 0;
        }
        TempModifier modifier = modifierOpt.get();
        modifier.expires(duration).tickRate(tickRate);
        modifier.getNBT().merge(nbt);

        Placement placement = Placement.of(mode, order, mod -> otherId == null || mod.getID().equals(otherId))
                                       .limitDuplicates(Matcher.SAME_CLASS, maxCount);
        for (Entity entity : entities)
        {   Temperature.addModifier(((LivingEntity) entity), modifier, trait, placement);
        }
        if (entities.size() == 1)
        {   source.sendSuccess(() -> Component.translatable("commands.cold_sweat.temp_modifier.single.add.result",
                                                            modifierId, entities.iterator().next().getName().getString()), true);
        }
        else
        {   source.sendSuccess(() -> Component.translatable("commands.cold_sweat.temp_modifier.many.add.result",
                                                            modifierId, entities.size()), true);
        }
        return entities.size();
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();
            var level = player.level();
            var random = level.getRandom();
            var entity = level.getEntity(this.getId());

            if (entity == null)
                return;

            var motion = new Vec3(this.getMotion());
            var speed = Math.abs(motion.y());

            entity.setDeltaMovement(motion);

            for (float i = 0; i < speed * 5F; i += 0.1F) {
                var angle = random.nextFloat() * Math.PI * 2;
                var radius = Math.sqrt(random.nextFloat()) * speed * 0.15F;

                var dx = Math.cos(angle) * radius;
                var dz = Math.sin(angle) * radius;

                level.addParticle(ParticleTypes.CLOUD, entity.getX(), entity.getY(), entity.getZ(), dx, random.nextFloat() * 0.15F, dz);
            }

            for (int i = 0; i < 50 * speed; i += 1) {
                var particleMotion = motion.normalize().scale(random.nextFloat());

                level.addParticle(ParticleTypes.CLOUD, entity.getX() + MathUtils.randomFloat(random) * 0.5F, entity.getY(), entity.getZ() + MathUtils.randomFloat(random) * 0.5F, particleMotion.x(), particleMotion.y(), particleMotion.z());
            }
        });
    }

private static LinkedStorageService.LinkResult linkWithFeedback(Player player, ItemStack linker, @Nullable BlockPos blockPos,
			BiFunction<ServerLevel, ItemStack, LinkedStorageService.LinkResult> linkOperation) {
		if (!(player.level() instanceof ServerLevel level)) {
			return LinkedStorageService.LinkResult.SUCCESS;
		}
		if (linker.has(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT)) {
			if (!EnderLinkerEndpointRecipe.finalizePendingCraftLinker(level, linker)) {
				throw new IllegalStateException("Could not finalize pending Ender Linker craft claim");
			}
		}
		if (LinkedStorageStackLifecycle.classifyLinker(linker) == EnderLinkerStackState.UNLINKED && linker.getCount() > 1) {
			ItemStack boundLinker = linker.copyWithCount(1);
			LinkedStorageService.LinkResult result = linkOperation.apply(level, boundLinker);
			if (result != LinkedStorageService.LinkResult.SUCCESS) {
				playFailureFeedback(player, result);
				return result;
			}
			linker.shrink(1);
			if (!player.getInventory().add(boundLinker)) {
				player.drop(boundLinker, false);
			}
			playLinkFeedback(level, player, blockPos);
			return LinkedStorageService.LinkResult.SUCCESS;
		}
		LinkedStorageService.LinkResult result = linkOperation.apply(level, linker);
		if (result != LinkedStorageService.LinkResult.SUCCESS) {
			playFailureFeedback(player, result);
			return result;
		}
		playLinkFeedback(level, player, blockPos);
		return LinkedStorageService.LinkResult.SUCCESS;
	}

private void refreshCache() {
		ClientLevel level = Minecraft.getInstance().level;
		if (level != null && level.getGameTime() != lastCacheTime) {
			lastCacheTime = level.getGameTime();

			LocalPlayer player = Minecraft.getInstance().player;
			if (player == null) {
				holdsItemThatShowsUpgrades = false;
				holdsStorageToolSetToToggleUpgrades = false;
				holdsItemThatShowsHiddenTiers = false;
				holdsToolInToggleLockOrLockDisplay = false;
				return;
			}

			boolean holdsStorageTool = holdsItem(player, this::isStorageTool);
			holdsStorageToolSetToToggleUpgrades = holdsStorageTool && InventoryHelper.getItemFromEitherHand(player, ModItems.STORAGE_TOOL.get())
					.map(item -> StorageToolItem.getMode(item) == StorageToolItem.Mode.UPGRADES_DISPLAY).orElse(false);

			holdsItemThatShowsUpgrades = holdsStorageTool || holdsItem(player, this::isUpgrade);
			holdsItemThatShowsFillLevels = holdsStorageTool || holdsItem(player, this::isStorageTierUpgrade)
					|| holdsItem(player, stack -> isUpgrade(stack) && stack.getItem() instanceof StackUpgradeItem);
			holdsItemThatShowsHiddenTiers = (holdsStorageTool && InventoryHelper.getItemFromEitherHand(player, ModItems.STORAGE_TOOL.get())
					.map(item -> StorageToolItem.getMode(item) == StorageToolItem.Mode.TIER_DISPLAY).orElse(false))
					|| holdsItem(player, this::isStorageTierUpgrade);
			holdsToolInToggleLockOrLockDisplay = holdsStorageTool && InventoryHelper.getItemFromEitherHand(player, ModItems.STORAGE_TOOL.get()).map(item -> {
				StorageToolItem.Mode mode = StorageToolItem.getMode(item);
				return mode == StorageToolItem.Mode.LOCK_DISPLAY || mode == StorageToolItem.Mode.LOCK;
			}).orElse(false);
			holdsToolInToggleFillLevelDisplay = holdsStorageTool && InventoryHelper.getItemFromEitherHand(player, ModItems.STORAGE_TOOL.get())
					.map(item -> StorageToolItem.getMode(item) == StorageToolItem.Mode.FILL_LEVEL_DISPLAY).orElse(false);
		}
	}

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.herd == null) {
                IPackEntity.initPack(this);
            }
            else {
                this.herd.tick();
            }
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            int i = this.random.nextInt(3000);
            if (i == 13 && !this.isInWater() && this.getTarget() == null && this.isNotMoving() && this.canMove() && this.getAnimation() == NO_ANIMATION) {
                this.setSitting(true);
            }
            if (i == 14 && this.isSitting()) {
                this.setSitting(false);
            }
            if (i > 2980 && !this.isBaby()) {
                this.setAnimation(IDLE_TALK);
            }

            if (this.getAnimation() == IDLE_TALK && this.getAnimationTick() == 1 && this.getAmbientSound() != null) {
                this.playSound(this.getAmbientSound(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        super.aiStep();
    }

public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.tickCount % 1000 == 0) {
                if (this.random.nextInt(40) == 0) {
                    this.spawnAtLocation(new ItemStack(ModItems.MATERIAL_SNAKE_SKIN.get()), 0.2F);
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
            if (this.tickCount % 120 == 0) {
                this.setAnimation(ANIMATION_TONGUE);
            }
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                int i = this.random.nextInt(3000);
                if (i <= 10 && !this.isInWater() && this.isNotMoving() && this.canMove()) {
                    this.getNavigation().stop();
                    this.setSitting(true);
                }
                if ((i == 11 || this.isInWater() || this.isActive()) && this.isSitting()) {
                    this.setSitting(false);
                }
            }
            this.setAngry(this.getTarget() != null);
        }
        else {
            if (Math.abs(this.getYRot() - this.yRotO) > 0.005) {
                this.offset = Mth.rotLerp(0.05F, this.offset, (this.getYRot() - this.yRotO));
            }
        }
    }

public static void tick(Level level, BlockPos pos, BlockState state, AltarInfusionBlockEntity blockEntity) {
        if (blockEntity.abortPendingFromLoad && !level.isClientSide()) {
            blockEntity.abortPendingFromLoad = false;
            blockEntity.endRitual();
            return;
        }

        if (blockEntity.isRunning()) {
            if (!level.isClientSide()) {
                // Aborts if the player is offline, in a different dimension, dies, or leaves the 30-block radius. The slowdown is removed inside endRitual().
                ServerPlayer onlinePlayer = blockEntity.resolveOnlinePlayer();
                if (onlinePlayer == null || onlinePlayer.level() != level || onlinePlayer.isDeadOrDying() || onlinePlayer.distanceToSqr(blockEntity.worldPosition.getX() + 0.5, blockEntity.worldPosition.getY() + 0.5, blockEntity.worldPosition.getZ() + 0.5) > MAX_PLAYER_DISTANCE_SQ) {
                    blockEntity.player = onlinePlayer;
                    blockEntity.endRitual();
                    return;
                }
                blockEntity.player = onlinePlayer;
            }

            blockEntity.runTime--;
            blockEntity.tickRitual();
            if (!blockEntity.isRunning()) {
                blockEntity.updateClient();
                blockEntity.setChanged();
            }
        }

        if (level.isClientSide()) {
            tickSphereAnimation(blockEntity);
            tickClientSound(blockEntity);
        }
    }

@Override
    protected void actuallyHurt(ServerLevel level, DamageSource damageSource, float amount) {
        DraculaState state = this.getState();
        if (damageSource.is(DamageTypeTags.IS_PROJECTILE)) {
            if (state == DraculaState.RANGED) {
                amount *= 0.5f;
            } else if (state == DraculaState.RAGED) {
                if (damageSource.getDirectEntity() instanceof AbstractArrow) {
                    amount *= 1.5f;
                }
            }
        }
        super.actuallyHurt(level, damageSource, amount);
        if (damageSource.getEntity() instanceof ServerPlayer player) {
            addPlayerToEvent(player);
        }
        if (getState() == DraculaState.DEFAULT) {
            setState(DraculaState.PASSIVE);
        }

        if (this.getState() == DraculaState.PASSIVE && damageSource.getEntity() instanceof LivingEntity attacker) {
            double d0 = attacker.getX() - this.getX();
            double d1 = attacker.getZ() - this.getZ();
            attacker.knockback(0.5D, d0, d1);
        }

        if (this.getState() == DraculaState.RAGED) {
            this.recentDamage.add(Pair.of(level.getGameTime(), amount));
            this.checkMistFormTrigger();
        }
        updateEvent();
    }

@Override
