private static boolean applyCharm(DeferredItem<Item> charm, Inventory keptInventory, Player player, int fromSlot, int toSlot) {
		Inventory inventory = player.getInventory();
		List<ItemStack> mergedCheck = new ArrayList<>(inventory.getNonEquipmentItems().subList(fromSlot, toSlot));

		// Armor and offhand are always kept by a Charm of Keeping
		for (int slot : CHARM_EQUIPMENT_SLOTS) {
			mergedCheck.add(inventory.getItem(slot));
		}

		// Filter out the charm so it does not count towards keeping items if it is the only thing being held
		if (mergedCheck.stream().filter(stack -> !stack.is(charm)).allMatch(ItemStack::isEmpty)) {
			return false;
		}

		// Stop operation if there is no charm present
		if (!TFItemStackUtils.consumeInventoryItem(player, charm, getPlayerData(player), true) && !hasCharmCurio(charm.value(), player, true)) {
			return false;
		}

		boolean skipCasketCheck = charm == TFItems.CHARM_OF_KEEPING_3;
		boolean keptCasket = false;

		for (int slot = fromSlot; slot < toSlot; slot++) {
			keptCasket = keepItem(inventory, keptInventory, slot, skipCasketCheck, keptCasket);
		}

		for (int slot : CHARM_EQUIPMENT_SLOTS) {
			keptCasket = keepItem(inventory, keptInventory, slot, skipCasketCheck, keptCasket);
		}

		return true;
	}

public static void handle(UncraftingGuiPacket message, IPayloadContext ctx) {
		if (ctx.flow().isServerbound()) {
			ctx.enqueueWork(() -> {
				AbstractContainerMenu container = ctx.player().containerMenu;

				if (container instanceof UncraftingMenu uncrafting) {
					switch (message.operationType()) {
						case 0 -> uncrafting.unrecipeInCycle++;
						case 1 -> uncrafting.unrecipeInCycle--;
						case 2 -> {
							if (!TFConfig.disableIngredientSwitching) {
								uncrafting.ingredientsInCycle++;
							}
						}
						case 3 -> {
							if (!TFConfig.disableIngredientSwitching) {
								uncrafting.ingredientsInCycle--;
							}
						}
						case 4 -> uncrafting.recipeInCycle++;
						case 5 -> uncrafting.recipeInCycle--;
					}

					if (message.operationType() < 4)
						uncrafting.slotsChanged(uncrafting.tinkerInput);

					if (message.operationType() >= 4)
						uncrafting.slotsChanged(uncrafting.getCraftSlots());
				}
			});
		}
	}

public void syncToServer() {
		Set<CommonWorktableModule> commonModules = new HashSet<>();
		for (TableModule head : getSpellHeads()) {

			TableModule lastModule = head;
			CommonWorktableModule lastCommonModule = new CommonWorktableModule(lastModule.hashCode(), lastModule.getModule(), lastModule.getPos(), null, new HashMap<>());
			commonModules.add(lastCommonModule);

			while (lastModule != null) {

				if (lastModule != head) {
					CommonWorktableModule commonModule = new CommonWorktableModule(lastModule.hashCode(), lastModule.getModule(), lastModule.getPos(), null, new HashMap<>());
					lastCommonModule.setLinksTo(commonModule);
					lastCommonModule = commonModule;
				}

				for (ModuleInstance module : ModuleRegistry.INSTANCE.getModules(ModuleType.MODIFIER)) {
					if (!(module instanceof ModuleInstanceModifier)) continue;
					if (!lastModule.hasData(Integer.class, module.getNBTKey())) continue;

					int count = lastModule.getData(Integer.class, module.getNBTKey());

					lastCommonModule.addModifier((ModuleInstanceModifier) module, count);
				}

				lastModule = lastModule.getLinksTo();
			}
		}

		int dim = Minecraft.getMinecraft().world.provider.getDimension();
		PacketHandler.NETWORK.sendToServer(new PacketSyncWorktable(dim, pos, commonModules));
	}

default Function2<ItemStack, Integer, Integer> getBeltColorFunction() {
		return (pearlBelt, tintIndex) -> {
			if (tintIndex == 0) return 0xFFFFFF;

			IItemHandler handler = getPearls(pearlBelt);
			if (handler == null) return 0;

			ItemStack stack = handler.getStackInSlot(tintIndex - 1);
			if (stack.isEmpty()) return 0xFFFFFF;

			if (!stack.hasTagCompound())
				return Color.HSBtoRGB(MathHelper.sin(Minecraft.getMinecraft().world.getTotalWorldTime() / 140f), 0.75f, 1f);

			long lastCast = NBTHelper.getLong(stack, NBTConstants.NBT.LAST_CAST, -1);
			int decayCooldown = NBTHelper.getInt(stack, NBTConstants.NBT.LAST_COOLDOWN, -1);
			long tick = Minecraft.getMinecraft().world.getTotalWorldTime();
			long timeSinceCooldown = tick - lastCast;
			float decayStage = (decayCooldown > 0) ? ((float) timeSinceCooldown) / decayCooldown : 1f;


			float rand = NBTHelper.getFloat(stack, NBTConstants.NBT.RAND, -1);
			float hue = rand < 0 ? (tick / 140f) % 140f : rand;
			float pow = Math.min(1f, Math.max(0f, getQuality(stack)));

			double decaySaturation = (lastCast == -1 || decayCooldown <= 0 || decayStage >= 1f) ? 1f :
					(decayStage < decayCurveDelimiter) ? Math.pow(Math.E, -15 * decayStage) : Math.pow(Math.E, 3 * decayStage - 3);

			float saturation = curveConst * (1 - (float) Math.pow(Math.E, -pow)) * (float) decaySaturation;

			return Color.HSBtoRGB(hue, saturation, 1f);
		};
	}

public static void addXpParticle(AoASkill skill, float xp, boolean isLevelUp) {
		if (!particlesMap.containsKey(skill))
			particlesMap.put(skill, new CopyOnWriteArrayList<>());

		if (lastParticleSkill == skill && lastParticleReceived != null && System.currentTimeMillis() <= lastPacketReceivedTime + 10) {
			lastParticleReceived.modifyXp(xp, isLevelUp);

			if (lastParticleReceived.levelUp) {
				CopyOnWriteArrayList<XPParticle> array = particlesMap.get(skill);

				if (!array.isEmpty())
					array.removeLast();

				array.addFirst(lastParticleReceived);
			}

			return;
		}

		XPParticle particle;

		if (isLevelUp) {
			particlesMap.get(skill).addFirst(particle = new XPParticle(xp, true));
		}
		else {
			particlesMap.get(skill).add(particle = new XPParticle(xp, false));
		}

		lastParticleReceived = particle;
		lastParticleSkill = skill;
		lastPacketReceivedTime = System.currentTimeMillis();
	}

public static void onLevelTick(Level level) {
		if(!level.isClientSide()) {
			for(Entity entity : toUpdate.keySet()) {
				if(!entity.hurtMarked) { // Allow velocity change packets to take priority.
					MotionUpdate update = toUpdate.get(entity);
					if(update != null) { // Edge case where the entity expired in the ms between calls
						Vec3 total = update.predicted.add(update.unpredicted);
						//We want a player's motion to be handled client-side to ensure movement consistency
						//Otherwise it feels jerky.
						if(entity instanceof ServerPlayer player) {
							reduceAboveGroundTicks(player, entity);
							if(!update.predicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.predicted.x, update.predicted.y, update.predicted.z, true));
							}
							if(!update.unpredicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.unpredicted.x, update.unpredicted.y, update.unpredicted.z, false));
							}
							reduceAboveGroundTicks(player, entity);
						} else {
							entity.push(total.x, total.y, total.z);
						}
						if(entity.level() instanceof ServerLevel) {
							PsiNetwork.sendToPlayersTracking(entity, new MessageAdditiveMotion(entity.getId(), total.x, total.y, total.z, false));
						}

					}
				}
			}

			toUpdate.clear();
		}
	}

public void tick() {
		if(this.level == null)
			return;
		this.lastTicked = this.level.getGameTime();
		this.lastProgress = this.progress;
		if(this.lastProgress >= 1.0F) {
			this.level.removeBlockEntity(this.worldPosition);
			this.setRemoved();
			if(this.magnetState != null && this.level.getBlockState(this.worldPosition).getBlock() == MagnetsModule.magnetized_block) {
				BlockState blockstate = Block.updateFromNeighbourShapes(this.magnetState, this.level, this.worldPosition);
				if(blockstate.isAir()) {
					this.level.setBlock(this.worldPosition, this.magnetState, 84);
					Block.updateOrDestroy(this.magnetState, blockstate, this.level, this.worldPosition, 3);
				} else {
					if(blockstate.getValues().containsKey(BlockStateProperties.WATERLOGGED) && blockstate.getValue(BlockStateProperties.WATERLOGGED)) {
						blockstate = blockstate.setValue(BlockStateProperties.WATERLOGGED, Boolean.FALSE);
					}

					setAndUpdateBlock(blockstate, 67);
				}
			}

		} else {
			float newProgress = this.progress + 0.5F;
			this.moveCollidedEntities(newProgress);
			this.progress = newProgress;
			if(this.progress >= 1.0F) {
				this.progress = 1.0F;
			}

		}
	}

public void registerAllPackets() {
		if (packetsRegistered)
			throw new IllegalStateException("Cannot call registerAllPackets() more than once!");

		ModContainer container = ModList.get().getModContainerById(modId).orElseThrow();
		container.getEventBus().addListener((RegisterPayloadHandlersEvent e) -> {
			PayloadRegistrar registrar = e.registrar(networkVersion);

			for (CatnipPacketRegistry.PacketType<?> type : packetsView) {
				boolean clientbound = ClientboundPacketPayload.class.isAssignableFrom(type.clazz());
				boolean serverbound = ServerboundPacketPayload.class.isAssignableFrom(type.clazz());
				if (clientbound && serverbound) {
					throw new IllegalStateException("Packet class is both clientbound and serverbound: " + type.clazz());
				} else if (clientbound) {
					CatnipPacketRegistry.PacketType<ClientboundPacketPayload> casted = (CatnipPacketRegistry.PacketType<ClientboundPacketPayload>) type;
					registrar.playToClient(casted.type(), casted.codec(), (payload, ctx) -> {
						ctx.enqueueWork(() -> {
							payload.handleInternal(ctx.player());
						});
					});
				} else if (serverbound) {
					CatnipPacketRegistry.PacketType<ServerboundPacketPayload> casted = (CatnipPacketRegistry.PacketType<ServerboundPacketPayload>) type;
					registrar.playToServer(casted.type(), casted.codec(), (payload, ctx) -> {
						ctx.enqueueWork(() -> {
							payload.handle((ServerPlayer) ctx.player());
						});
					});
				}
			}
		});
		packetsRegistered = true;
	}

@Override
    public void tick() {
        if (level.isClientSide || connectedPos == null || level.getGameTime() % 20 != 0) {
            return;
        }
        BlockEntity tile = level.getBlockEntity(connectedPos);
        if (tile == null) {
            return;
        }
        IItemHandler handler = level.getCapability(Capabilities.ItemHandler.BLOCK, connectedPos, null);
        if (handler == null) {
            return;
        }
        int found = 0;
        for (int i = 0; i < handler.getSlots(); i++) {
            ItemStack ghostStack = handler.getStackInSlot(i);
            ItemStack extractedStack = handler.extractItem(i, ghostStack.getCount(), true);
            // This falls back to the getStack count if we attempted to extract beyond the max count.
            // This is a workaround for inventories that support > max stack count, as you can only extract the max stack count at a time.
            // and getStackInSlot will return counts for items that wouldn't necessarily be extractable.
            if (ghostStack.getCount() > extractedStack.getCount() && extractedStack.getMaxStackSize() == extractedStack.getCount()) {
                found += getCountForStack(ghostStack);
            } else {
                found += getCountForStack(extractedStack);
            }
            if (found > neededCount) {
                setReachedCount(true);
                return;
            }
        }
        setReachedCount(false);
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide)
            return;
        if (level.getGameTime() % 40 == 0 && this.canAcceptSource()) {
            for (ItemEntity i : level.getEntitiesOfClass(ItemEntity.class, new AABB(worldPosition).inflate(1.0))) {
                if (i.getItem().getItem().getFoodProperties(i.getItem(), null) != null) {
                    int source = getSourceValue(i.getItem());
                    this.addSource(source);
                    ItemStack containerItem = i.getItem().getCraftingRemainingItem();
                    i.getItem().shrink(1);
                    if (!containerItem.isEmpty()) {
                        level.addFreshEntity(new ItemEntity(level, i.getX(), i.getY(), i.getZ(), containerItem));
                    }
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.blockPosition(), new ParticleColor(255, 255, 255)));
                }
            }
            for (ArcanePedestalTile i : getSurroundingPedestals()) {
                int sourceValue = getSourceValue(i.getItem(0));
                if (sourceValue > 0) {
                    this.addSource(sourceValue);
                    ItemStack containerItem = i.getItem(0).getCraftingRemainingItem();
                    i.removeItem(0, 1);
                    i.setItem(0, containerItem);
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.getBlockPos().above(), new ParticleColor(255, 255, 255)));
                }
            }
        }
    }

public boolean canUse() {
        long i = this.mob.level.getGameTime();
        if (!canAttack.get())
            return false;
        if (i - this.lastCanUseCheck < 20L) {
            return false;
        } else {
            this.lastCanUseCheck = i;
            LivingEntity livingentity = this.mob.getTarget();
            if (livingentity == null) {
                return false;
            } else if (!livingentity.isAlive()) {
                return false;
            } else {
                if (canPenalize) {
                    if (--this.ticksUntilNextPathRecalculation <= 0) {
                        this.path = this.mob.getNavigation().createPath(livingentity, 0);
                        this.ticksUntilNextPathRecalculation = 4 + this.mob.getRandom().nextInt(7);
                        return this.path != null;
                    } else {
                        return true;
                    }
                }
                this.path = this.mob.getNavigation().createPath(livingentity, 0);
                if (this.path != null) {
                    return true;
                } else {
                    return this.getAttackReachSqr(livingentity) >= this.mob.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
                }
            }
        }
    }

@Override
    protected void tick() {
        if (getWorld().isClientSide) {
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), 5);
        } else {
            if (getWorld().getGameTime() % 100 == 0) {
                List<LivingEntity> entities = getWorld().getEntitiesOfClass(LivingEntity.class, new AABB(getPos()).inflate(5));
                Optional<LivingEntity> player = entities.stream().filter(e -> e instanceof Player).findFirst();

                boolean didWorkOnce = false;
                for (LivingEntity a : entities) {
                    if (a instanceof ZombieVillager zv) {
                        zv.startConverting(player.map(Entity::getUUID).orElse(null), 0);
                        didWorkOnce = true;
                        continue;
                    }

                    if (a.getHealth() < a.getMaxHealth() || a.isInvertedHealAndHarm()) {
                        if (a.isInvertedHealAndHarm()) {
                            FakePlayer player1 = ANFakePlayer.getPlayer((ServerLevel) getWorld());
                            a.hurt(getWorld().damageSources().playerAttack(player1), 10.0f);
                        } else {
                            a.heal(10.0f);
                        }
                        didWorkOnce = true;
                    }
                }
                if (didWorkOnce)
                    setNeedsSource(true);
            }
        }
    }

