@Override
    public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        if (this.getOwner() == pPlayer) {
            if (itemstack.is(Items.ROTTEN_FLESH)) {
                if (this.level().getGameTime() > this.lastLeatherTime + LEATHER_INTERVAL) {
                    this.lastLeatherTime = this.level().getGameTime();
                    itemstack.shrink(1);
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.LEATHER));
                } else if (pPlayer.level().isClientSide()) {
                    pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.fairy.leather_on_cooldown"));
                }
                return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
            }
            if (itemstack.is(Items.GLASS_BOTTLE)) {
                if (!this.hasBlacksmithUpgrade()) {
                    if (pPlayer.level().isClientSide())
                        pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.fairy.no_upgrade"));
                } else if (this.level().getGameTime() > this.lastBreathTime + BREATH_INTERVAL) {
                    this.lastBreathTime = this.level().getGameTime();
                    itemstack.shrink(1);
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.DRAGON_BREATH));
                } else if (pPlayer.level().isClientSide()) {
                    pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.fairy.breath_on_cooldown"));
                }
                //even if we don't give a breath we return success, otherwise we make the familiar change sitting position
                return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
            }

        }
        return super.mobInteract(pPlayer, pHand);
    }

public boolean canUse() {
        long worldTime = entity.level().getGameTime() % 10;
        if (worldTime != 0 && entity.getRandom().nextInt(reducedTickDelay(rate)) != 0) {
            return false;
        }
        if (!this.packAnimal.isPackFollower() && !this.packAnimal.hasPackFollower()) {
            double dist = 30D;
            List<? extends LivingEntity> list = entity.level().getEntitiesOfClass(entity.getClass(), entity.getBoundingBox().inflate(dist, dist, dist));
            LivingEntity closestTail = null;
            double d0 = Double.MAX_VALUE;
            for (LivingEntity animal : list) {
                if (!((PackAnimal) animal).hasPackFollower() && ((PackAnimal) animal).isValidLeader(((PackAnimal) animal).getPackLeader()) && !animal.getUUID().equals(entity.getUUID()) && !((PackAnimal) animal).isInPack(packAnimal) && ((PackAnimal) animal).getPackSize() < packSize) {
                    double d1 = this.entity.distanceToSqr(animal);
                    if (!(d1 > d0)) {
                        d0 = d1;
                        closestTail = animal;
                    }
                }
            }
            if (closestTail == null) {
                return false;
            } else if (d0 < 1.0D) {
                return false;
            } else if (!packAnimal.isValidLeader(((PackAnimal) closestTail).getPackLeader())) {
                return false;
            } else {
                this.packAnimal.joinPackOf((PackAnimal) closestTail);
                return true;
            }
        } else {
            return false;
        }
    }

