private RecipeEnqueueState enqueueNewRecipes(State state, Level rawLevel)
	{
		final List<MultiblockProcess<MixerRecipe, ProcessContextInMachine<MixerRecipe>>> processQueue = state.processor.getQueue();
		if(state.energy.getEnergyStored() <= 0||processQueue.size() >= state.processor.getMaxQueueSize())
			return RecipeEnqueueState.NOP;
		if(state.tank.getFluidAmount() <= 0)
			return RecipeEnqueueState.NOP;
		IntSet usedInvSlots = new IntOpenHashSet();
		for(MultiblockProcess<MixerRecipe, ?> process : processQueue)
			if(process instanceof MixingProcess mixingProcess)
				for(int i : mixingProcess.getInputSlots())
					usedInvSlots.add(i);
		NonNullList<ItemStack> components = NonNullList.withSize(NUM_SLOTS, ItemStack.EMPTY);
		for(int i = 0; i < components.size(); i++)
			if(!usedInvSlots.contains(i))
				components.set(i, state.inventory.getStackInSlot(i));

		boolean foundRecipe = false;
		boolean update = false;
		for(FluidStack fs : state.tank.fluids)
		{
			RecipeHolder<MixerRecipe> recipe = MixerRecipe.findRecipe(rawLevel, fs, components);
			if(recipe==null)
				continue;
			foundRecipe = true;
			MultiblockProcessInMachine<MixerRecipe> process = new MixingProcess(
					recipe, state.tank, recipe.value().getUsedSlots(fs, components)
			).setInputTanks(0);
			if(state.processor.addProcessToQueue(process, rawLevel, false))
				update = true;
		}
		return new RecipeEnqueueState(update, foundRecipe);
	}

@Override
	public void process(IPayloadContext context)
	{
		Player player = context.player();
		context.enqueueWork(() -> {
			ItemStack held = player.getItemInHand(InteractionHand.OFF_HAND);
			if(fetchSlot >= 0)
			{
				ItemStack s = player.getInventory().items.get(fetchSlot);
				UpgradeData upgrades = UpgradeableToolItem.getUpgradesStatic(s);
				if(s.getItem() instanceof IEShieldItem&&upgrades.has(UpgradeEffect.MAGNET))
				{
					var withSlot = upgrades.with(UpgradeEffect.MAGNET, new PrevSlot(fetchSlot));
					s.set(IEDataComponents.UPGRADE_DATA, withSlot);
					player.getInventory().items.set(fetchSlot, held);
					player.setItemInHand(InteractionHand.OFF_HAND, s);
				}
			}
			else
			{
				UpgradeData upgrades = UpgradeableToolItem.getUpgradesStatic(held);
				var prevSlot = upgrades.get(UpgradeEffect.MAGNET).prevSlot();
				if(held.getItem() instanceof IEShieldItem&&((IEShieldItem)held.getItem()).getUpgrades(held).has(UpgradeEffect.MAGNET)&&prevSlot.isPresent())
				{
					var withSlot = upgrades.with(UpgradeEffect.MAGNET, PrevSlot.NONE);
					held.set(IEDataComponents.UPGRADE_DATA, withSlot);
					ItemStack s = player.getInventory().items.get(prevSlot.get());
					player.getInventory().items.set(prevSlot.get(), held);
					player.setItemInHand(InteractionHand.OFF_HAND, s);
				}
			}
		});
	}

public void damageEquipment(Player player, int amount) {
            // entity has proper safety equipment, so damage it per material every 5 seconds.
            if (player.level().getGameTime() % 100 == 0) {
                for (ArmorItem.Type type : this.getEquipmentTypes()) {
                    ItemStack armor = player.getItemBySlot(type.getSlot());
                    if (!armor.isEmpty() && ((armor.getItem() instanceof ArmorComponentItem armorItem &&
                            armorItem.getArmorLogic().isPPE()) ||
                            armor.getTags().anyMatch(tag -> tag.equals(CustomTags.PPE_ARMOR)))) {
                        armor.hurtAndBreak(amount, player, p -> p.broadcastBreakEvent(type.getSlot()));
                    }
                }
                if (GTCEu.Mods.isCuriosLoaded()) {
                    ICuriosItemHandler curiosInventory = CuriosApi.getCuriosInventory(player)
                            .resolve()
                            .orElse(null);
                    if (curiosInventory != null) {
                        for (String curioItem : this.getCurioSlots()) {
                            curiosInventory.getStacksHandler(curioItem).ifPresent(handler -> {
                                IDynamicStackHandler stackHandler = handler.getStacks();
                                for (int i = 0; i < handler.getSlots(); ++i) {
                                    ItemStack armor = stackHandler.getStackInSlot(i);
                                    if (!armor.isEmpty() && ((armor.getItem() instanceof ArmorComponentItem armorItem &&
                                            armorItem.getArmorLogic().isPPE()) ||
                                            armor.getTags().anyMatch(tag -> tag.equals(CustomTags.PPE_ARMOR)))) {
                                        armor.hurtAndBreak(amount, player, p -> {});
                                    }
                                }
                            });
                        }
                    }
                }
            }
        }

private boolean createPotionEssence(List<PotionIngredient> potionIngredients, Level level) {
		PotionContents potionContents = PotionHelper.combineIngredients(potionIngredients);
		if (!potionContents.hasEffects()) {
			pestleUsedCounter = 0;
			for (int clearSlot = 0; clearSlot < items.getSlots(); ++clearSlot) {
				if (items.getStackInSlot(clearSlot).isEmpty()) {
					continue;
				}
				if (!level.isClientSide) {
					ItemEntity itemEntity = new ItemEntity(level, getBlockPos().getX() + 0.5D, getBlockPos().getY() + 0.5D, getBlockPos().getZ() + 0.5D,
							items.getStackInSlot(clearSlot).copy());
					level.addFreshEntity(itemEntity);
				}
				items.setStackInSlot(clearSlot, ItemStack.EMPTY);
			}
		} else {
			for (int clearSlot = 0; clearSlot < items.getSlots(); ++clearSlot) {
				items.setStackInSlot(clearSlot, ItemStack.EMPTY);
			}
			pestleUsedCounter = 0;
			finishCoolDown = level.getGameTime() + 20; // 1 second cooldown before essence can be put in to prevent insta insert of it
			if (level.isClientSide) {
				return true;
			}
			ItemStack resultItem = new ItemStack(ModItems.POTION_ESSENCE.get());
			PotionHelper.addPotionContentsToStack(resultItem, potionContents);

			ItemEntity itemEntity = new ItemEntity(level, getBlockPos().getX() + 0.5D, getBlockPos().getY() + 0.5D, getBlockPos().getZ() + 0.5D, resultItem);
			level.addFreshEntity(itemEntity);
		}
		setChanged();
		return false;
	}

public void setBackpack(ItemStack backpack) {
		if (level instanceof ServerLevel serverLevel) {
			LinkedStorageJukeboxPlaybackAnchors.removeBlockAnchor(serverLevel, worldPosition, backpackWrapper.getBackpack());
		}
		if (!isCurrentWrapperOpen()) {
			closeLinkedStorageSubscription();
		}
		backpackWrapper = level == null
				? BackpackWrapper.fromStack(backpack)
				: level.isClientSide ? new BackpackWrapper(backpack) : BackpackLinkedStorageResolver.resolveOrCreate(level, backpack);
		pendingLoadedBackpack = null;
		backpackWrapper.setContentsChangeHandler(() -> {
			setChanged();
			WorldHelper.notifyBlockUpdate(this);
		});
		backpackWrapper.setInventorySlotChangeHandler(this::setChanged);
		backpackWrapper.setUpgradeCachesInvalidatedHandler(this::invalidateHandlers);
		if (backpackWrapper instanceof LinkedStorageBackpackWrapper linkedStorageBackpackWrapper) {
			linkedStorageBackpackWrapper.setCanonicalContentsChangedHandler(this::refreshLinkedRenderState);
		}
		backpackWrapper.getRenderInfo().setRenderUpdateChangeListener(renderInfo -> {
			updateBlockRender = true;
			WorldHelper.notifyBlockUpdate(this);
		});
		if (level != null && !level.isClientSide()) {
			backpackWrapper.onInit(level);
			LinkedStorageJukeboxPlaybackAnchors.refreshBlockAnchor((ServerLevel) level, worldPosition, backpackWrapper.getBackpack());
			if (backpackWrapper instanceof LinkedStorageBackpackWrapper linkedStorageBackpackWrapper) {
				linkedStorageBackpackWrapper.refreshPhysicalProjection();
				refreshLinkedRenderState();
			}
		}
	}

public static void addEffect(ResourceLocation entityTypeName, CompoundTag entityNbt, Vec3 position, Vec3 collapsePosition, float yRot, float xRot) {
		Minecraft mc = Minecraft.getInstance();
		ClientLevel level = mc.level;
		if (level == null) {
			return;
		}

		if (ENTITY_RENDER_FAILURES.contains(entityTypeName)) {
			addNonRenderingEffect(entityTypeName, collapsePosition, level.getGameTime());
			return;
		}

		try {
			Entity entity = BuiltInRegistries.ENTITY_TYPE.getOptional(entityTypeName).map(entityType -> entityType.create(level)).orElse(null);
			if (!(entity instanceof LivingEntity livingEntity)) {
				return;
			}

			livingEntity.load(entityNbt.copy());
			livingEntity.moveTo(position.x, position.y, position.z, yRot, xRot);
			livingEntity.xOld = position.x;
			livingEntity.yOld = position.y;
			livingEntity.zOld = position.z;
			livingEntity.yRotO = yRot;
			livingEntity.xRotO = xRot;
			pinYRotation(livingEntity, yRot);
			CAPTURE_EFFECTS.add(new CaptureEffect(entityTypeName, livingEntity, collapsePosition, livingEntity.getBbWidth(), livingEntity.getBbHeight(), yRot,
					level.getGameTime()));
		} catch (RuntimeException e) {
			logRenderFailure(entityTypeName, e);
			addNonRenderingEffect(entityTypeName, collapsePosition, level.getGameTime());
		}
	}

private void handleInvalidSlotAccess(int handlerIndex, int slot, String methodName) {
		if (level == null) {
			return;
		}

		long gameTime = level.getGameTime();
		if (gameTime - lastInvalidSlotLogTime < INVALID_SLOT_LOG_INTERVAL_TICKS) {
			return;
		}

		lastInvalidSlotLogTime = gameTime;
		invalidSlotIncidentCount++;
		if (handlerIndex < 0 || handlerIndex >= storageKeys.size()) {
			SophisticatedCore.LOGGER.debug(
					"Invalid handler index calculated {} in controller's {} method. If you see many of these messages try replacing controller at {}",
					() -> handlerIndex, () -> methodName, () -> getBlockPos().toShortString());
		} else {
			SophisticatedCore.LOGGER.debug(
					"Invalid slot {} passed into controller's {} method for storage at {}. If you see many of these messages try replacing controller at {}",
					() -> slot, () -> methodName, () -> storageKeys.get(handlerIndex).position().toShortString(), () -> getBlockPos().toShortString());
		}

		if (!refreshingAfterInvalidSlots && invalidSlotIncidentCount >= INVALID_SLOT_REFRESH_THRESHOLD
				&& gameTime - lastInvalidSlotRefreshTime >= INVALID_SLOT_REFRESH_COOLDOWN_TICKS) {
			lastInvalidSlotRefreshTime = gameTime;
			refreshingAfterInvalidSlots = true;
			SophisticatedCore.LOGGER.debug("Refreshing controller at {} after {} invalid slot incidents were logged", () -> getBlockPos().toShortString(),
					() -> invalidSlotIncidentCount);
			refreshConnectedStoragesAfterRepeatedInvalidSlots();
			invalidSlotIncidentCount = 0;
			refreshingAfterInvalidSlots = false;
		}
	}

public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.tickCount % 1000 == 0) {
                if (this.wantsToBreed() && !this.isMale()) {
                    this.breed();
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
            this.setAngry(this.getTarget() != null);
            this.setClimbing(this.horizontalCollision && nextToClimbableBlock(this));
            if (!this.isOnGround() && !this.isClimbing() && this.getDeltaMovement().y() < 0 && nextToClimbableBlock(this)){
                this.setDeltaMovement(this.getDeltaMovement().multiply(0, 0.5, 0));
                this.setClimbing(true);
            }
        }
        if (this.level.isClientSide()) {
            if (this.isAngry() && this.aggroProgress < 40)
                this.aggroProgress++;
            else if (!this.isAngry() && this.aggroProgress > 0)
                this.aggroProgress--;

            if (this.isClimbing() && this.climbProgress < 20)
                this.climbProgress++;
            else if (!this.isClimbing() && this.climbProgress > 0)
                this.climbProgress--;

            if (this.climbProgress % 20 != 0 && this.invertClimbing != (this.getDeltaMovement().y() < 0))
                this.invertClimbing = !this.isOnGround() && this.getDeltaMovement().y() < 0;
        }
    }

