@Override
    protected void checkAndPerformAttack(ToyBase target) {
        long currentTime = dino.level.getGameTime();
        if (attackType == GRAB) {
            for (Entity passenger : swimming.getPassengers()) {
                if (passenger instanceof ToyBase toy && currentTime == grabStartTick + GRAB_DURATION) {
                    swimming.stopGrabAttack(passenger);
                    swimming.moodSystem.setToyTarget(null);
                    swimming.moodSystem.useToy(toy.moodBonus);
                }
            }
        } else if (attackType == ATTACK) {
            if (attackDamageTick > 0 && currentTime >= attackDamageTick) {
                target.hurt(DamageSource.mobAttack(dino), 0);
                attackDamageTick = -1;
                attackType = -1;
            }
        } else if (currentTime > attackEndTick + 20 && Util.canReachPrey(dino, target)) {
            boolean tooBig = !Util.isEntitySmallerThan(target, 2 * swimming.getScale() / swimming.data().maxScale());
            if (swimming.aiAttackType() != Attacking.GRAB || tooBig || swimming.getRandom().nextInt(5) > 0) {
                attackType = ATTACK;
                ServerAnimationInfo animationInfo = dino.startAttack();
                attackDamageTick = (long) (currentTime + animationInfo.actionDelay);
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
            } else {
                attackType = GRAB;
                swimming.startGrabAttack(target);
                attackEndTick = 1;
                grabStartTick = currentTime;
            }
        }
    }

private static List<Entry> sortByDepth(Collection<Entry> entries) {
        Map<Entry, Integer> remainingParents = new HashMap<>();
        Deque<Entry> queue = new ArrayDeque<>();
        List<Entry> sorted = new ArrayList<>(entries.size());

        for (Entry entry : entries) {
            remainingParents.put(entry, entry.parents().size());
            if (entry.parents().isEmpty()) {
                queue.add(entry);
            }
        }

        while (!queue.isEmpty()) {
            Entry entry = queue.poll();
            sorted.add(entry);

            for (Entry child : entry.children()) {
                child.setDepth(Math.max(child.depth(), entry.depth() + 1));
                if (remainingParents.merge(child, -1, Integer::sum) == 0) {
                    queue.add(child);
                }
            }
        }

        if (sorted.size() != entries.size()) {
            Set<Entry> resolved = new HashSet<>(sorted);
            LOGGER.error("Skill segments form a cycle and are ignored: {}", entries.stream().filter(entry -> !resolved.contains(entry)).map(entry -> entry.key().identifier().toString()).collect(Collectors.joining(", ")));
        }

        sorted.sort(Comparator.comparingInt(Entry::depth).thenComparing(entry -> entry.key().identifier()));

        return sorted.stream().collect(Collectors.groupingBy(Entry::depth, TreeMap::new, Collectors.toList())).values().stream().map(SkillTreeGraph::orderByPlacement).flatMap(List::stream).toList();
    }

@SuppressWarnings("Convert2Lambda")
	public static void handle(MagicMapPacket message, IPayloadContext ctx) {
		//ensure this is only done on clients as this uses client only code
		if (ctx.flow().isClientbound()) {
			ctx.enqueueWork(new Runnable() {
				@Override
				public void run() {
					if (!(ctx.player().level() instanceof ClientLevel clientLevel)) return;

					MapId mapId = message.inner.mapId();
					TFMagicMapData mapdata = MapDataManager.getClientMagicMapData(mapId);
					if (mapdata == null) {
						mapdata = new TFMagicMapData(0, 0, message.inner.scale(), false, false, message.inner.locked(), clientLevel.dimension());
						MapDataManager.saveClientMagicMapData(mapId, mapdata);
					}

					message.inner.applyToMap(mapdata);
					//TF: sync conquered structures for map
					mapdata.conqueredStructures.clear();
					mapdata.conqueredStructures.addAll(message.conqueredStructures());
					Minecraft.getInstance().getMapTextureManager().update(mapId, mapdata);

					MapItemSavedData saved = clientLevel.getMapData(message.inner.mapId());

					if (saved != null) {
						saved.addClientSideDecorations(
							StreamSupport.stream(mapdata.getDecorations().spliterator(), false).toList()
						);
					}
				}
			});
		}
	}

static void damageArmor(LivingEntity entity) {
        if (entity instanceof Player player) {
            var data = player.getData(AetherDataAttachments.AETHER_PLAYER);
            if (EquipmentUtil.hasAnyPhoenixArmor(entity) && entity.isInWaterRainOrBubble()) {
                if (entity.level().getGameTime() % 15 == 0) {
                    data.setObsidianConversionTime(data.getObsidianConversionTime() + 1);
                    entity.level().levelEvent(1501, entity.blockPosition(), 0);
                }
            } else {
                data.setObsidianConversionTime(0);
            }
            if (data.getObsidianConversionTime() >= data.getObsidianConversionTimerMax()) {
                for (EquipmentSlot equipmentSlot : EquipmentSlot.values()) {
                    if (equipmentSlot.getType() == EquipmentSlot.Type.HUMANOID_ARMOR) {
                        ItemStack equippedStack = entity.getItemBySlot(equipmentSlot);
                        if (equippedStack.is(AetherItems.PHOENIX_HELMET.get())) {
                            breakPhoenixArmor(entity, equippedStack, new ItemStack(AetherItems.OBSIDIAN_HELMET.get()), equipmentSlot);
                        } else if (equippedStack.is(AetherItems.PHOENIX_CHESTPLATE.get())) {
                            breakPhoenixArmor(entity, equippedStack, new ItemStack(AetherItems.OBSIDIAN_CHESTPLATE.get()), equipmentSlot);
                        } else if (equippedStack.is(AetherItems.PHOENIX_LEGGINGS.get())) {
                            breakPhoenixArmor(entity, equippedStack, new ItemStack(AetherItems.OBSIDIAN_LEGGINGS.get()), equipmentSlot);
                        } else if (equippedStack.is(AetherItems.PHOENIX_BOOTS.get())) {
                            breakPhoenixArmor(entity, equippedStack, new ItemStack(AetherItems.OBSIDIAN_BOOTS.get()), equipmentSlot);
                        }
                    }
                }
                SlotEntryReference slotResult = EquipmentUtil.getAccessory(entity, AetherItems.PHOENIX_GLOVES.get());
                if (slotResult != null) {
                    breakPhoenixGloves(entity, slotResult, new ItemStack(AetherItems.OBSIDIAN_GLOVES.get()));
                }
            }
        }
    }

