public void tick(@NotNull BlockState pState, ServerLevel pLevel, @NotNull BlockPos pPos, @NotNull RandomSource pRandom) {
        pLevel.scheduleTick(pPos, this, getFireTickDelay(pLevel.random));
        if (pLevel.getGameRules().getBoolean(GameRules.RULE_DOFIRETICK)) {
            BlockState blockstate = pLevel.getBlockState(pPos.below());
            boolean fireSourceBelow = blockstate.isFireSource(pLevel, pPos, Direction.UP);
            int age = pState.getValue(AGE);
            if (!fireSourceBelow && pLevel.isRaining() && this.isNearRain(pLevel, pPos) && pRandom.nextFloat() < 0.2F + (float) age * 0.064F) {
                pLevel.removeBlock(pPos, false);
            } else {
                int j = Math.min(MAX_AGE, age + pRandom.nextInt(3) / 2);
                if (age != j) {
                    pState = pState.setValue(AGE, j);
                    pLevel.setBlock(pPos, pState, 4);
                }

                if (!fireSourceBelow) {
                    if (!this.isValidFireLocation(pLevel, pPos)) {
                        BlockPos blockpos = pPos.below();
                        if (!pLevel.getBlockState(blockpos).isFaceSturdy(pLevel, blockpos, Direction.UP) || age > 3) {
                            pLevel.removeBlock(pPos, false);
                        }

                        return;
                    }

                    if (age == MAX_AGE && pRandom.nextInt(2) == 0 && !this.canCatchFire(pLevel, pPos.below(), Direction.UP)) {
                        pLevel.removeBlock(pPos, false);
                        return;
                    }
                }
            }
        }
    }

@Override
    public void tick() {
        if (key == null)
            return;

        if (level instanceof ServerLevel serverLevel) {
            if (level.getGameTime() % 200 == 0) {
                playersNearby = false;
                for (ServerPlayer serverPlayer : serverLevel.players()) {
                    if (BlockPosHelpers.distanceBetween(worldPosition, serverPlayer.blockPosition()) < 64) {
                        playersNearby = true;
                        break;
                    }
                }
            }
            if (!playersNearby) {
                return;
            }
            if (level.getGameTime() % ServerConfig.PLANARIUM_UPDATE_RATE.get() == 0) {
                DimManager.Entry entry1 = dimManager.getOrCreateTemplate(serverLevel, worldPosition, key);
                if (entry1 != null) {
                    // Notifies nearby players if the dimension has changed
                    if (entry1.lastUpdated > lastUpdated) {
                        lastUpdated = entry1.lastUpdated;
                        StructureTemplate template = dimManager.getTemplate(key);
                        if (template != null) {
                            Networking.sendToNearbyClient(level, worldPosition, new PacketUpdateDimTile(worldPosition, template));
                        }
                    }
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide)
            return;
        if (level.getGameTime() % 20 == 0 && this.canAcceptSource()) {
            for (ItemEntity i : level.getEntitiesOfClass(ItemEntity.class, new AABB(worldPosition).inflate(1.0))) {
                int source = getSourceValue(i.getItem());
                if (source > 0 && (canConsumeEntireItem(i.getItem()) || this.getSource() <= 0)) {
                    this.addSource(source);
                    ItemStack containerItem = i.getItem().getCraftingRemainingItem();
                    i.getItem().shrink(1);
                    if (!containerItem.isEmpty()) {
                        level.addFreshEntity(new ItemEntity(level, i.getX(), i.getY(), i.getZ(), containerItem));
                    }
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.blockPosition(), new ParticleColor(255, 0, 0)));
                    return;
                }
            }
            for (ArcanePedestalTile i : getSurroundingPedestals()) {
                int sourceValue = getSourceValue(i.getItem(0));
                if (sourceValue > 0 && (canConsumeEntireItem(i.getItem(0)) || this.getSource() <= 0)) {
                    this.addSource(sourceValue);
                    ItemStack containerItem = i.getItem(0).getCraftingRemainingItem();
                    i.removeItem(0, 1);
                    i.setItem(0, containerItem);
                    Networking.sendToNearbyClient(level, getBlockPos(),
                            new PacketANEffect(PacketANEffect.EffectType.BURST, i.getBlockPos().above(), new ParticleColor(255, 0, 0)));
                }
            }
        }
    }

@Override
    public StarbyState onDestinationReached() {
        this.starbuncle.getNavigation().stop();

        IItemHandler iItemHandler = behavior.getItemCapFromTile(targetPos, behavior.TO_DIRECTION_MAP.get(targetPos.hashCode()));
        if (iItemHandler == null) {
            starbuncle.addGoalDebug(this, new DebugEvent("NoItemHandler", "No item handler at " + targetPos.toString()));
            return nextState;
        }

        boolean didDeposit = depositStack(iItemHandler);
        if (!didDeposit) {
            starbuncle.setBackOff(5 + starbuncle.level.random.nextInt(20));
            starbuncle.addGoalDebug(this, new DebugEvent("no_room", targetPos.toString()));
            return nextState;
        }

        OpenChestEvent event = new OpenChestEvent((ServerLevel) starbuncle.level, targetPos, 20);
        event.open();
        EventQueue.getServerInstance().addEvent(event);

        ItemStack left = starbuncle.getHeldStack();
        starbuncle.addGoalDebug(this, new DebugEvent("stored_item", "successful at " + targetPos.toString() + "set stack to " + left.getCount() + "x " + left.getHoverName().getString()));
        boolean fetchPassengerStack = left.isEmpty();
        while (fetchPassengerStack) {
            fetchPassengerStack = false;
            starbuncle.getNextItemFromPassengers();
            if (!starbuncle.getHeldStack().isEmpty()) {
                fetchPassengerStack = depositStack(iItemHandler) && starbuncle.getHeldStack().isEmpty();
            }
        }
        return nextState;
    }

@SubscribeEvent
    public static void onFall(LivingFallEvent event) {
        LivingEntity entity = event.getEntity();
        if (entity == null || !entity.hasEffect(ModPotions.BOUNCE_EFFECT)) {
            return;
        }
        boolean isPlayer = entity instanceof Player;
        boolean isClient = entity.level.isClientSide;
        if (isClient && !isPlayer) {
            return;
        }
        if (event.getDistance() > 2) {
            if (entity.isCrouching()) {
                event.setDamageMultiplier(0.0f);
            } else {
                event.setDamageMultiplier(0);
                entity.fallDistance = 0.0F;
                if (!isPlayer || isClient) {
                    double f = 0.95d - .1 * entity.getEffect(ModPotions.BOUNCE_EFFECT).getAmplifier();
                    // only slow down half as much when bouncing
                    entity.setDeltaMovement(entity.getDeltaMovement().x / f, entity.getDeltaMovement().y * (-0.9), entity.getDeltaMovement().z / f);
                    entity.hurtMarked = true;
                    entity.setOnGround(false);
                }
                if (isClient) {
                    EventQueue.getClientQueue().addEvent(new BounceTimedEvent(entity, entity.getDeltaMovement().y));
                } else {
                    EventQueue.getServerInstance().addEvent(new BounceTimedEvent(entity, entity.getDeltaMovement().y));
                }
                event.setCanceled(true);
            }
        }
    }

public void markNextIngredient(Level level,
                                   BlockPos goldenBowlPosition,
                                   Ingredient ingredient, int tier) {
        List<SacrificialBowlBlockEntity> sacrificialBowls = this.getSacrificialBowls(level, goldenBowlPosition);
        for (SacrificialBowlBlockEntity sacrificialBowl : sacrificialBowls) {
            //first simulate removal to check the ingredient
            ItemStack stack = sacrificialBowl.itemStackHandler.getResource(0).toStack();
            if (ingredient.test(stack)) {
                double gameTime = level.getGameTime() * 0.05;
                //Show effect in level
                double sin = Math.sin(gameTime) * 0.3;
                double cos = Math.cos(gameTime) * 0.3;
                Vec3 center = sacrificialBowl.getBlockPos().getCenter();
                ((ServerLevel) level)
                        .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x + cos, center.y + 0.2 + cos, center.z + sin,
                                1, 0.0, 0.0, 0.0, 0.003);
                if (tier == 2) {
                    double sin2 = Math.sin(gameTime + (Math.PI * 0.5)) * 0.3;
                    double cos2 = Math.cos(gameTime + (Math.PI * 0.5)) * 0.3;
                    ((ServerLevel) level)
                            .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x + cos2, center.y + 0.2 + sin2, center.z + sin2,
                                    1, 0.0, 0.0, 0.0, 0.003);
                    ((ServerLevel) level)
                            .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x - cos2, center.y + 0.2 + cos2, center.z - sin2,
                                    1, 0.0, 0.0, 0.0, 0.003);
                    ((ServerLevel) level)
                            .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x - cos, center.y + 0.2 + sin, center.z - sin,
                                    1, 0.0, 0.0, 0.0, 0.003);
                }
                return;
            }
        }
    }

