private void sendTransferWithResult(
		List<TransferOperation> transferOperations,
		List<Slot> craftingSlots,
		List<Slot> inventorySlots,
		boolean maxTransfer,
		boolean requireCompleteSets,
		boolean useCountedTransferPacket,
		IRecipeTransferContext<R, C> context
	) {
		PacketRecipeTransferResult.registerPendingRecipeTransfer(context);
		int transferId = context.getTransferId();
		if (useCountedTransferPacket) {
			PacketRecipeTransferCountedWithResult packet = PacketRecipeTransferCountedWithResult.fromSlots(
				transferOperations,
				craftingSlots,
				inventorySlots,
				maxTransfer,
				requireCompleteSets,
				transferId
			);
			serverConnection.sendPacketToServer(packet);
		} else {
			PacketRecipeTransferWithResult packet = PacketRecipeTransferWithResult.fromSlots(
				transferOperations,
				craftingSlots,
				inventorySlots,
				maxTransfer,
				requireCompleteSets,
				transferId
			);
			serverConnection.sendPacketToServer(packet);
		}
	}

public boolean canUse() {
        long worldTime = entity.level().getGameTime() % 10;
        if (worldTime != 0 && entity.getRandom().nextInt(reducedTickDelay(rate)) != 0) {
            return false;
        }
        if (!this.packAnimal.isPackFollower() && !this.packAnimal.hasPackFollower()) {
            double dist = 30D;
            List<? extends LivingEntity> list = entity.level().getEntitiesOfClass(entity.getClass(), entity.getBoundingBox().inflate(dist, dist, dist));
            LivingEntity closestTail = null;
            double d0 = Double.MAX_VALUE;
            for (LivingEntity animal : list) {
                if (!((IPackHunter) animal).hasPackFollower() && ((IPackHunter) animal).isValidLeader(((IPackHunter) animal).getPackLeader()) && !animal.getUUID().equals(entity.getUUID()) && !((IPackHunter) animal).isInPack(packAnimal) && ((IPackHunter) animal).getPackSize() < packSize) {
                    double d1 = this.entity.distanceToSqr(animal);
                    if (!(d1 > d0)) {
                        d0 = d1;
                        closestTail = animal;
                    }
                }
            }
            if (closestTail == null) {
                return false;
            } else if (d0 < 1.0D) {
                return false;
            } else if (!packAnimal.isValidLeader(((IPackHunter) closestTail).getPackLeader())) {
                return false;
            } else {
                this.packAnimal.joinPackOf((IPackHunter) closestTail);
                return true;
            }
        } else {
            return false;
        }
    }

