@Override
	public void onUpdate() {
		// super.onUpdate();
		if (!getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime() % 5 == 0) {
			if (!getHasExploded())
				checkArea();
			if (getHasExploded())
				checkAreaOfEffect();
		}

		if (!getEntityWorld().isRemote) {
			if (!getSwelling() && getSwellCount() > MIN_SWELL)
				setSwellCount(getSwellCount() - 1);

			if (getSwelling() && getSwellCount() < MAX_SWELL)
				setSwellCount(getSwellCount() + 1);

			if(getHasExploded()) {
				if (getSwellCount() < MAX_SWELL)
					setSwellCount(MAX_SWELL);
				if (getAOESizeXZ() > 0.5F)
					setAOESizeXZ(getAOESizeXZ() - 0.01F);
				if (getAOESizeXZ() <= 0.5F)
					setDead();
			}
		}

		if (getHasExploded())
			setBoundingBoxSize();

		if (getEntityWorld().isRemote)
			if(getHasExploded())
				spawnCloudParticle();
	}

private boolean enqueueNewProcesses(IMultiblockContext<State> ctx)
	{
		final State state = ctx.getState();
		final Level level = ctx.getLevel().getRawLevel();
		boolean addedAny = false;
		final int[] usedInvSlots = new int[NUM_INPUT_SLOTS];
		for(final MultiblockProcess<FermenterRecipe, ProcessContextInMachine<FermenterRecipe>> process : state.processor.getQueue())
			if(process instanceof MultiblockProcessInMachine)
				for(int i : ((MultiblockProcessInMachine<FermenterRecipe>)process).getInputSlots())
					usedInvSlots[i]++;

		Integer[] preferredSlots = new Integer[]{0, 1, 2, 3, 4, 5, 6, 7};
		Arrays.sort(preferredSlots, 0, 8, Comparator.comparingInt(arg0 -> usedInvSlots[arg0]));
		for(int slot : preferredSlots)
		{
			ItemStack stack = state.inventory.getStackInSlot(slot);
			if(!stack.isEmpty())
			{
				stack = stack.copy();
				stack.shrink(usedInvSlots[slot]);
			}
			if(!stack.isEmpty()&&stack.getCount() > 0)
			{
				RecipeHolder<FermenterRecipe> recipe = FermenterRecipe.findRecipe(level, stack);
				if(recipe!=null)
				{
					MultiblockProcessInMachine<FermenterRecipe> process = new MultiblockProcessInMachine<>(recipe, slot);
					if(state.processor.addProcessToQueue(process, level, false))
						addedAny = true;
				}
			}
		}
		return addedAny;
	}

public static void render(PoseStack poseStack, MultiBufferSource bufferSource, LocalPlayer player, Vec3 cameraPos) {
		if(client.hitResult instanceof BlockHitResult hitResult && ArcanusComponents.isBlockWarded(player.clientLevel, hitResult.getBlockPos()) && player.swinging) {
			BlockPos blockPos = hitResult.getBlockPos();

			if(client.options.keyAttack.isDown() && player.attackAnim == 0)
				hitTimer = 20;

			if(!ArcanusComponents.isOwnerOfBlock(player, blockPos) || hitTimer > 0) {
				float alpha = Mth.clamp(hitTimer / 20f, 0f, 1f);

				renderWardedBlock(poseStack, bufferSource, player.clientLevel, cameraPos, blockPos, alpha);
				player.displayClientMessage(Component.translatable(TranslationKeys.BLOCK_IS_WARDED).withStyle(ChatFormatting.RED), true);
			}

			if(hitTimer > 0)
				hitTimer -= 1;
		}

		if(player.getMainHandItem().is(ArcanusItemTags.STAVES) || player.getOffhandItem().is(ArcanusItemTags.STAVES)) {
			AtomicReferenceArray<LevelChunk> chunks = player.clientLevel.getChunkSource().storage.chunks;
			float alpha = Mth.sin(player.clientLevel.getGameTime() * 0.06f) * 0.4f + 0.6f;

			for(int i = 0; i < chunks.length(); i++) {
				ChunkAccess chunk = chunks.get(i);

				if(chunk != null) {
					ArcanusComponents.getWardedBlocks(chunk).forEach((blockPos, uuid) -> {
						if(blockPos.distSqr(BlockPos.containing(cameraPos)) < 256)
							renderWardedBlock(poseStack, bufferSource, player.clientLevel, cameraPos, blockPos, alpha);
					});
				}
			}
		}
	}

@Override
	public void write(CompoundTag compound, HolderLookup.Provider registries, boolean clientPacket) {
		NBTHelper.writeEnum(compound, "Mode", mode);
		NBTHelper.writeEnum(compound, "State", state);
		compound.putInt("Timer", timer);
		compound.putBoolean("Powered", redstoneLocked);
		if (owner != null)
			compound.putUUID("Owner", owner);

		if (player != null) {
			ListTag invNBT = new ListTag();
			player.getInventory()
				.save(invNBT);
			compound.put("Inventory", invNBT);
			compound.put("HeldItem", player.getMainHandItem().saveOptional(registries));
			compound.put("Overflow", NBTHelper.writeItemList(overflowItems, registries));
		} else if (deferredInventoryList != null) {
			compound.put("Inventory", deferredInventoryList);
		}

		super.write(compound, registries, clientPacket);

		if (!clientPacket)
			return;
		compound.putBoolean("Fistbump", fistBump);
		compound.putFloat("Reach", reach);
		if (player == null)
			return;
		compound.put("HeldItem", player.getMainHandItem().saveOptional(registries));
		if (player.spawnedItemEffects != null) {
			compound.put("Particle", player.spawnedItemEffects.saveOptional(registries));
			player.spawnedItemEffects = null;
		}
	}

private void playerTick(Player player) {
		ServerQuestFile file = ServerQuestFile.INSTANCE;

		if (player instanceof ServerPlayer && file != null && !PlayerHooks.isFake(player)) {
			if (autoSubmitTasks == null) {
				autoSubmitTasks = file.collect(o -> o instanceof Task && ((Task) o).autoSubmitOnPlayerTick() > 0);
			}

			// Don't be deceived, its somehow possible to be null here
			if (autoSubmitTasks == null || autoSubmitTasks.isEmpty()) {
				return;
			}

			TeamData data = file.getOrCreateTeamData(player);

			if (data.isLocked()) {
				return;
			}

			long t = player.level().getGameTime();

			file.withPlayerContext((ServerPlayer) player, () -> {
				for (Task task : autoSubmitTasks) {
					long d = task.autoSubmitOnPlayerTick();

					if (d > 0L && t % d == 0L) {
						if (!data.isCompleted(task) && data.canStartTasks(task.getQuest())) {
							task.submitTask(data, (ServerPlayer) player);
						}
					}
				}
			});
		}
	}

private static void renderParticlesInLayer(PoseStack poseStack,
                                               Map<@Nullable IRenderSetup, Queue<GTParticle>> renderQueue,
                                               EffectRenderContext context) {
        for (var entry : renderQueue.entrySet()) {
            Queue<GTParticle> particles = entry.getValue();
            if (particles.isEmpty()) continue;

            IRenderSetup handler = entry.getKey();
            boolean initialized = false;

            BufferBuilder buffer = Tesselator.getInstance().getBuilder();
            for (GTParticle particle : particles) {
                if (!particle.shouldRender(context)) {
                    continue;
                }
                try {
                    if (!initialized) {
                        initialized = true;
                        if (handler != null) {
                            handler.preDraw(buffer);
                        }
                    }
                    particle.renderParticle(poseStack, buffer, context);

                } catch (Throwable throwable) {
                    GTCEu.LOGGER.error("Particle render error: {}", particle, throwable);
                    particle.setExpired();
                }
            }
            if (initialized && handler != null) {
                handler.postDraw(buffer);
            }
        }
    }

@Override
    protected void onTickBegin() {
        super.onTickBegin();
        // Transform's lazy matrix caches are not synchronized; warm them on the game thread
        // before particles may update via parallelStream.
        transform().localToWorldMatrix();
        transform().worldToLocalMatrix();
        var simSpace = resolveSimSpaceTransform();
        if (simSpace != null) {
            simSpace.localToWorldMatrix();
            simSpace.worldToLocalMatrix();
            simSpace.scale();
            simSpace.rotation();
        }
        if (runtime().forceOverLifetime.getSimulationSpace() == ValueSpace.Custom) {
            CustomSpace.warm(config.forceOverLifetime.customSpace, getScene());
        }
        if (runtime().velocityOverLifetime.space.get() == ValueSpace.Custom) {
            CustomSpace.warm(config.velocityOverLifetime.customSpace, getScene());
        }
        var araConfig = config.trails.araConfig;
        if (araConfig.physicsSetting.gravitySpace == ValueSpace.Custom) {
            CustomSpace.warm(araConfig.physicsSetting.gravityCustomSpace, getScene());
        }
        if (araConfig.space == AraTrailConfig.TrailSpace.Custom) {
            CustomSpace.warm(araConfig.customSpace, getScene());
        }
        activeForceFields = gatherForceFields();
        for (var queue : particles.values()) {
            for (var particle : queue) {
                particle.syncOrigin();
            }
        }
    }

