private void makeParticles() {
        BlockPos blockpos = this.getBlockPos();
        ServerLevel serverLevel = (ServerLevel) this.level;

        if (serverLevel != null) {
            long t = serverLevel.getGameTime();
            double d0 = (double)blockpos.getX() + serverLevel.getRandom().nextDouble();
            double d1 = (double)blockpos.getY() + serverLevel.getRandom().nextDouble();
            double d2 = (double)blockpos.getZ() + serverLevel.getRandom().nextDouble();
            if (t % 20L == 0L) {
                if (this.getBlockState().getValue(NecroBrazierBlock.WATERLOGGED)) {
                    if (serverLevel.getFluidState(blockpos.above()).isEmpty() && serverLevel.getBlockState(blockpos.above()).isAir()) {
                        ParticleOptions particleOptions = ModParticleTypes.NECRO_FIRE.get();
                        serverLevel.sendParticles(particleOptions, blockpos.getX() + 0.5F, blockpos.getY() + 1.0F, blockpos.getZ() + 0.5F, 1, 0, 0, 0, 0);
                        serverLevel.sendParticles(ModParticleTypes.NECRO_FIRE_DROP.get(), blockpos.getX() + 0.5F, blockpos.getY() + 1.0F, blockpos.getZ() + 0.5F, 1, 0, 0, 0, 0);
                    } else {
                        for (int p = 0; p < 4; ++p) {
                            serverLevel.sendParticles(ParticleTypes.BUBBLE, d0, d1, d2, 1, 0, 0, 0, 0);
                            serverLevel.sendParticles(ParticleTypes.BUBBLE_COLUMN_UP, d0, d1, d2, 0, 0.0D, 0.04D, 0.0D, 0.5F);
                        }
                    }
                } else {
                    if (serverLevel.getFluidState(blockpos.above()).isEmpty() && serverLevel.getBlockState(blockpos.above()).isAir()) {
                        for (int p = 0; p < 4; ++p) {
                            serverLevel.sendParticles(ParticleTypes.SMOKE, d0, d1, d2, 0, 0.0D, 5.0E-4D, 0.0D, 0.5F);
                        }
                        ParticleOptions particleOptions = ModParticleTypes.NECRO_FIRE.get();
                        serverLevel.sendParticles(particleOptions, blockpos.getX() + 0.5F, blockpos.getY() + 1.0F, blockpos.getZ() + 0.5F, 1, 0, 0, 0, 0);
                        serverLevel.sendParticles(ModParticleTypes.NECRO_FIRE_DROP.get(), blockpos.getX() + 0.5F, blockpos.getY() + 1.0F, blockpos.getZ() + 0.5F, 1, 0, 0, 0, 0);
                    }
                }
            }
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (powered != getTube().getPressure() >= ConfigHelper.common().logistics.minPressure.get()) {
            powered = !powered;
            NetworkHandler.sendToAllTracking(PacketUpdateLogisticsModule.create(this, 0), getTube());
        }
        if (--ticksUntilNextCycle <= 0) {
            LogisticsManager manager = new LogisticsManager();
            Int2ObjectMap<LogisticsModule> frame2module = new Int2ObjectOpenHashMap<>();
            ModuleNetworkManager networkManager = ModuleNetworkManager.getInstance(getTube().nonNullLevel());
            for (AbstractTubeModule module : networkManager.getConnectedModules(this)) {
                if (module.isValid() && module instanceof LogisticsModule logistics && logistics.getColorChannel() == this.getColorChannel()) {
                    // Make sure any connected module doesn't tick; set it to a 5-second timer.
                    // This is also a penalty value when no task is executed this tick.
                    // The timer will be reduced to 20 ticks later if the module does some work.
                    logistics.ticksUntilNextCycle = 100;
                    if (logistics.hasPower() && logistics.getFrame() != null) {
                        // record the frame->module mapping and add the frame to the logistics manager
                        frame2module.put(logistics.getFrame().getId(), logistics);
                        manager.addLogisticFrame(logistics.getFrame());
                    }
                }
            }

            PriorityQueue<LogisticsTask> tasks = manager.getTasks(null, false);
            for (LogisticsTask task : tasks) {
                task.resource
                        .ifLeft(itemStack -> handleItems(frame2module.get(task.provider.getId()), frame2module.get(task.requester.getId()), task, itemStack))
                        .ifRight(fluidStack -> handleFluids(frame2module.get(task.provider.getId()), frame2module.get(task.requester.getId()), task, fluidStack));
            }
        }
    }

@Override
	public void onLoad()
	{
		super.onLoad();

		int chunkX = pos.getX() >> 4;
		int chunkZ = pos.getZ() >> 4;

		Queue<TileCachable> toCheck = new LinkedList<>();

		for (int x = -CHUNK_RANGE; x <= CHUNK_RANGE; x++)
		{
			for (int z = -CHUNK_RANGE; z <= CHUNK_RANGE; z++)
			{
				if (x*x + z*z > CHUNK_DIST_SQ) continue;
				WizardryChunk chunk = WizardryChunkCapability.get(world.getChunk(chunkX + x, chunkZ + z));
				toCheck.addAll(chunk.getCachableTiles());
			}
		}

		while (!toCheck.isEmpty())
		{
			TileCachable tile = toCheck.remove();
			double dist = tile.getPos().distanceSq(pos);
			if (dist <= LINK_DIST_SQ)
			{
				tile.distanceCache.put(this, dist);
				distanceCache.put(tile, dist);
			}
		}

		WizardryChunk chunk = WizardryChunkCapability.get(world.getChunk(chunkX, chunkZ));
		chunk.addCachableTile(this);
	}

private static <T extends Block> Supplier<BlockItem> registerBlockItem(final DeferredBlock<T> deferredBlock) {
        return () -> {
            DeferredBlock<T> block = Objects.requireNonNull(deferredBlock);
            if (block == ENCHANTED_AETHER_GRASS_BLOCK
                    || block == QUICKSOIL_GLASS
                    || block == QUICKSOIL_GLASS_PANE
                    || block == ENCHANTED_GRAVITITE) {
                return new BlockItem(block.get(), new Item.Properties().rarity(Rarity.RARE));
            } else if (block == AEROGEL
                    || block == AEROGEL_WALL
                    || block == AEROGEL_STAIRS
                    || block == AEROGEL_SLAB) {
                return new BlockItem(block.get(), new Item.Properties().rarity(AetherItems.AETHER_LOOT));
            } else if (block == AMBROSIUM_TORCH) {
                return new StandingAndWallBlockItem(AMBROSIUM_TORCH.get(), AMBROSIUM_WALL_TORCH.get(), new Item.Properties(), Direction.DOWN);
            } else if (block == SKYROOT_SIGN) {
                return new SignItem(new Item.Properties().stacksTo(16), SKYROOT_SIGN.get(), SKYROOT_WALL_SIGN.get());
            } else if (block == SKYROOT_HANGING_SIGN) {
                return new HangingSignItem(SKYROOT_HANGING_SIGN.get(), SKYROOT_WALL_HANGING_SIGN.get(), new Item.Properties().stacksTo(16));
            } else if (block == CHEST_MIMIC) {
                return new EntityBlockItem(block.get(), ChestMimicBlockEntity::new, new Item.Properties());
            } else if (block == TREASURE_CHEST) {
                return new EntityBlockItem(block.get(), TreasureChestBlockEntity::new, new Item.Properties());
            } else if (block == SKYROOT_DOOR) {
                return new DoubleHighBlockItem(block.get(), new Item.Properties());
            } else if (block == SUN_ALTAR) {
                return new BlockItem(block.get(), new Item.Properties().fireResistant());
            } else if (block == SKYROOT_BED) {
                return new EntityBlockItem(block.get(), SkyrootBedBlockEntity::new, new Item.Properties().stacksTo(1));
            } else {
                return new BlockItem(block.get(), new Item.Properties());
            }
        };
    }

@Override
  public float call(ItemStack stack, @Nullable ClientWorld worldIn, @Nullable LivingEntity entityIn)
    {
      final float IDLE_FRAME_INDEX = 0.0F;
      final float FULLY_CHARGED_INDEX = 1.0F;

      World world = worldIn;
      if (worldIn == null && entityIn != null)  {
        world = entityIn.world;
      }

      if (entityIn == null || worldIn == null) return IDLE_FRAME_INDEX;
      if (!entityIn.isHandActive()) {  // player isn't holding down the right mouse button, i.e. not charging
        animationHasStarted = false;
        return IDLE_FRAME_INDEX;
      }

      long worldTicks = world.getGameTime();
      if (!animationHasStarted) {
        startingTick = worldTicks;
        animationHasStarted = true;
      }
      final long ticksInUse = worldTicks - startingTick;
      if (ticksInUse <= ItemNBTAnimate.CHARGE_UP_INITIAL_PAUSE_TICKS) {
        return IDLE_FRAME_INDEX;
      }

      final long chargeTicksSoFar = ticksInUse - ItemNBTAnimate.CHARGE_UP_INITIAL_PAUSE_TICKS;
      final double fractionCharged = chargeTicksSoFar/(double)ItemNBTAnimate.CHARGE_UP_DURATION_TICKS;
      if (fractionCharged < 0.0) return IDLE_FRAME_INDEX;
      if (fractionCharged > FULLY_CHARGED_INDEX) return FULLY_CHARGED_INDEX;

      return (float)fractionCharged*FULLY_CHARGED_INDEX;
  }

private static int renderBeam(PoseStack poseStack, List<ItemStack> contents, float partialTick, int packedLight, int packedOverlay, MultiBufferSource buffer) {
		if (contents.get(0).getItem() instanceof PowerStone powerStone) {
			int colour = powerStone.getColour();
			int currentIndex = 1;
			int lastIndex = 0;
			ItemStack slotStack;

			poseStack.mulPose(Axis.XP.rotationDegrees(90));
			poseStack.translate(-0.5f, -0.375f, -0.5f);

			do {
				if (!(slotStack = contents.get(currentIndex)).isEmpty() || currentIndex == 6) {
					int delta = (currentIndex - lastIndex);

					poseStack.pushPose();
					poseStack.translate(0, (lastIndex) * 0.137f, 0);
					poseStack.scale(1, 0.137f * delta, 1);
					BeaconRenderer.renderBeaconBeam(poseStack, buffer, BeaconRenderer.BEAM_LOCATION, partialTick, 0.125f, Minecraft.getInstance().level.getGameTime() * 12, 0, 1, colour, 0.1f, 0.12f);
					poseStack.popPose();

					if (slotStack.getItem() instanceof AspectFocusItem focus)
						colour = ColourUtil.lerpColour(colour, focus.getFocus().colour(), 0.75f);

					lastIndex = currentIndex;
				}

				currentIndex++;
			} while (currentIndex < contents.size());

			return colour;
		}

		return 0;
	}

public static int startChunkBanTest(CommandContext<CommandSourceStack> ctx, boolean withState) {
        String confirmation = ctx.getArgument("confirm", String.class);
        if (!confirmation.equals(CONFIRMATION_KEY)) {
            ctx.getSource().sendFailure(MSG_NO_CONFIRM);
            return 0;
        }

        if (!(ctx.getSource().getPlayer() instanceof ServerPlayer player) || player instanceof FakePlayer) {
            ctx.getSource().sendFailure(MSG_NOT_A_PLAYER);
            return 0;
        }

        if (dimension != null) {
            ctx.getSource().sendFailure(MSG_ALREADY_RUNNING);
            return 0;
        }

        if (withState) {
            state = BlockStateArgument.getBlock(ctx, "state").getState();
        } else {
            state = FBContent.BLOCK_FRAMED_DOUBLE_SLAB.value().defaultBlockState();
        }

        ServerLevel level = ctx.getSource().getLevel();
        ChunkPos chunk = ChunkPos.containing(new BlockPos((int) player.getX(), (int) player.getY(), (int) player.getZ()));
        int minY = level.getMinY();
        startPos = placePos = SectionPos.of(chunk, SectionPos.blockToSectionCoord(minY)).origin().above();
        dimension = level.dimension();
        resultMsgConsumer = msg -> ctx.getSource().sendSuccess(() -> msg, true);

        ctx.getSource().sendSuccess(() -> Component.literal("Starting chunkban test preparation in chunk " + chunk), true);

        return 1;
    }

@Override
    protected void tick() {
        Level world = getWorld();
        if (world.isClientSide) {
            BlockPos pos = getPos();
            for (int i = 0; i < 10; i++) {
                Vec3 particlePos = new Vec3(pos.getX(), pos.getY(), pos.getZ()).add(0.5, 0, 0.5);
                particlePos = particlePos.add(ParticleUtil.pointInSphere().multiply(5, 5, 5));
                world.addParticle(ParticleLineData.createData(getCenterColor()),
                        particlePos.x(), particlePos.y(), particlePos.z(),
                        pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5);
            }
        }
        if (!world.isClientSide && world.getGameTime() % 20 == 0) {
            incrementProgress();
            if (getProgress() >= 3) {
                List<Entity> entities = getWorld().getEntitiesOfClass(Entity.class, new AABB(getPos()).inflate(5));

                for (Entity entity : entities) {
                    for (AbstractFamiliarHolder familiarHolder : FamiliarRegistry.getFamiliarHolderMap().values()) {
                        if (familiarHolder.isEntity.test(entity)) {
                            entity.remove(Entity.RemovalReason.DISCARDED);
                            ParticleUtil.spawnPoof((ServerLevel) world, entity.blockPosition());
                            var pos = entity.blockPosition().getBottomCenter();
                            world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, familiarHolder.getOutputItem()));
                            world.playSound(null, entity.blockPosition(), SoundEvents.BOOK_PUT, SoundSource.NEUTRAL, 1.0f, 1.0f);
                            ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.FAMILIAR.get(), (ServerLevel) world, entity.blockPosition(), 8);
                        }
                    }
                }
                setFinished();
            }
        }
    }

public boolean canUse() {
        if(this.isHoldingCrossbow()){
            return  true;
        }else{
            long i = this.mob.level().getGameTime();
            if (i - this.lastCanUseCheck < 20L) {
                return false;
            } else {
                this.lastCanUseCheck = i;
                LivingEntity livingentity = this.mob.getTarget();
                if (livingentity == null) {
                    return false;
                } else if (!livingentity.isAlive()) {
                    return false;
                } else {
                    if (canPenalize) {
                        if (--this.ticksUntilNextPathRecalculation <= 0) {
                            this.path = this.mob.getNavigation().createPath(livingentity, 0);
                            this.ticksUntilNextPathRecalculation = 4 + this.mob.getRandom().nextInt(7);
                            return this.path != null;
                        } else {
                            return true;
                        }
                    }
                    this.path = this.mob.getNavigation().createPath(livingentity, 0);
                    if (this.path != null) {
                        return true;
                    } else {
                        return this.getAttackReachSqr(livingentity) >= this.mob.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
                    }
                }
            }
        }
    }

