public boolean canUse() {
		long i = this.attacker.level().getGameTime();
		if (i - this.lastCanUseCheck < 20L) {
			return false;
		} else if (!this.attacker.isHungry()) {
			return false;
		} else {
			this.lastCanUseCheck = i;
			Entity target = this.attacker.getBoofloAttackTarget();
			if (target == null) {
				return false;
			} else if (!target.isAlive()) {
				return false;
			} else if (this.attacker.hasFruit()) {
				return false;
			} else {
				if (this.canPenalize) {
					if (--this.delayCounter <= 0) {
						this.path = this.attacker.getNavigation().createPath(target, 0);
						this.delayCounter = 4 + this.attacker.getRandom().nextInt(7);
						return this.path != null;
					} else {
						return true;
					}
				}
				this.path = this.attacker.getNavigation().createPath(target, 0);
				if (this.path != null) {
					return true;
				} else {
					return this.getAttackReachSqr(target) >= this.attacker.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());
				}
			}
		}
	}

@Nullable
    public static Boolean shouldRender(ItemStack stack, SlotPath path, AccessoriesStorageLookup storageLookup, LivingEntity entity, LivingEntityRenderState entityState, RenderingFunction renderingFunction) {
        if (renderingFunction instanceof RenderingFunction.ArmedTargeted armedTargeted && entityState.hasStateData(AccessoriesRenderStateKeys.ARM)) {
            if (armedTargeted.firstPersonArmTarget().hasArm(entityState.getStateData(AccessoriesRenderStateKeys.ARM))) return true;
        }

        return switch (renderingFunction) {
            case RenderingFunction.Transformations transformation -> {
                yield shouldRender(stack, path, storageLookup, entity, entityState, transformation.renderingFunction());
            }
            case RenderingFunction.Compound compoundFunction -> {
                yield shouldRender(stack, path, storageLookup, entity, entityState, compoundFunction.renderingFunctions());
            }
            case RenderingFunction.RawRenderer data -> {
                var renderFunction = CustomRendererLoader.getOrResolveRawRenderer(data, !CustomRendererLoader.isConstantResolveTarget());

                if(renderFunction == null) yield null;

                yield shouldRender(stack, path, storageLookup, entity, entityState, renderFunction);
            }
            case RenderingFunction.DeferredRenderer renderer -> {
                var possibleRenderer = CustomRendererLoader.getOrResolveRenderer(renderer, !CustomRendererLoader.isConstantResolveTarget());

                if(possibleRenderer == null) yield null;

                yield Either.unwrap(
                        possibleRenderer.mapBoth(
                                accessoryRenderer -> accessoryRenderer.shouldRender(stack, path, storageLookup, entity, entityState, true),
                                renderFunction -> shouldRender(stack, path, storageLookup, entity, entityState, renderFunction))
                );
            }
            default -> null;
        };
    }

@Override
    public boolean canUse() {
        if (!this.myrmex.shouldHaveNormalAI()) {
            list = IAFMath.emptyEntityList;
            return false;
        }
        if (!this.myrmex.canMove() || this.myrmex.getTarget() != null || this.myrmex.releaseTicks < 400 || this.myrmex.mate != null) {
            list = IAFMath.emptyEntityList;
            return false;
        }
        MyrmexHive village = this.myrmex.getHive();
        if (village == null) {
            village = MyrmexWorldData.get(this.myrmex.level).getNearestHive(this.myrmex.blockPosition(), 100);
        }
        if (village != null && village.getCenter().distToCenterSqr(this.myrmex.getX(), village.getCenter().getY(), this.myrmex.getZ()) < 2000) {
            list = IAFMath.emptyEntityList;
            return false;
        }

        if (this.myrmex.level.getGameTime() % 4 == 0) // only update the list every 4 ticks
            list = this.mob.level.getEntities(myrmex, this.getTargetableArea(100), this.targetEntitySelector);

        if (list.isEmpty())
            return false;

        list.sort(this.theNearestAttackableTargetSorter);
        for (Entity royal : list) {
            if (this.myrmex.canMate((EntityMyrmexRoyal) royal)) {
                this.myrmex.mate = (EntityMyrmexRoyal) royal;
                this.myrmex.level.broadcastEntityEvent(this.myrmex, (byte) 76);
                return true;
            }
        }
        return false;
    }

@Override
	public void onLivingUpdate() {
		if (getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime()%5 + getEntityWorld().rand.nextInt(5) == 0) {
			if (isInWater()) {
				for (int i = 0; i < 2; ++i) {
					double a = Math.toRadians(rotationYaw);
					double offSetX = -Math.sin(a) * width * 0.5D;
					double offSetZ = Math.cos(a) * width * 0.5D;
					getEntityWorld().spawnParticle(EnumParticleTypes.WATER_BUBBLE, posX + offSetX, posY + height * 0.5D + rand.nextDouble() * 0.5D, posZ + offSetZ, 0.0D, 0.4D, 0.0D, new int[0]);
				}
			}
		}

		if(glowTimer > 0) {
			glowTimer--;
		}

		if (inWater) {
			setAir(300);
		} else if (onGround) {
			motionY += 0.5D;
			motionX += (double) ((rand.nextFloat() * 2.0F - 1.0F) * 0.4F);
			motionZ += (double) ((rand.nextFloat() * 2.0F - 1.0F) * 0.4F);
			rotationYaw = rand.nextFloat() * 360.0F;
			if(isLeaping())
				setIsLeaping(false);
			onGround = false;
			isAirBorne = true;
			if(getEntityWorld().getTotalWorldTime()%5==0)
				getEntityWorld().playSound((EntityPlayer) null, posX, posY, posZ, SoundRegistry.FISH_FLOP, SoundCategory.HOSTILE, 1F, 1F);
			damageEntity(DamageSource.DROWN, 0.5F);
		}

		super.onLivingUpdate();
	}

private static <T extends Block> BlockDefinition<T> block(
            String englishName,
            Identifier id,
            Function<Properties, T> blockSupplier,
            @Nullable BiFunction<Block, Item.Properties, BlockItem> itemFactory) {
        Preconditions.checkArgument(id.getNamespace().equals(AppEng.MOD_ID));

        // Create block and matching item
        var deferredBlock = DR.registerBlock(id.getPath(), blockSupplier);
        var deferredItem = AEItems.DR.register(id.getPath(), () -> {
            var block = deferredBlock.get();
            var itemProperties = new Item.Properties().setId(ResourceKey.create(Registries.ITEM, id))
                    .useBlockDescriptionPrefix();
            if (itemFactory != null) {
                var item = itemFactory.apply(block, itemProperties);
                if (item == null) {
                    throw new IllegalArgumentException("BlockItem factory for " + id + " returned null");
                }
                return item;
            } else if (block instanceof AEBaseBlock) {
                return new AEBaseBlockItem(block, itemProperties);
            } else {
                return new BlockItem(block, itemProperties);
            }
        });

        var itemDef = new ItemDefinition<>(englishName, deferredItem);
        MainCreativeTab.add(itemDef);
        BlockDefinition<T> definition = new BlockDefinition<>(englishName, deferredBlock, itemDef);

        BLOCKS.add(definition);

        return definition;

    }

@Override
	public void tick() {
		if(getCaster() == null || getTarget() == null) {
			kill();
			return;
		}

		if(!level().isClientSide()) {
			if(entityData.get(TARGET_ID) == -1 && getTarget() != null)
				entityData.set(TARGET_ID, getTarget().getId());
		}

		if(isBoundToTarget()) {
			int orbCount = ArcanusComponents.stockpileOrbCount(getTarget());
			int orbIndex = ArcanusComponents.stockpileOrbIndex(getTarget(), this) + 1;
			double angle = Math.toRadians(360d / orbCount * orbIndex);
			double cosYaw = Math.cos(Math.toRadians(-getTarget().yBodyRot));
			double sinYaw = Math.sin(Math.toRadians(-getTarget().yBodyRot));
			double radius = getTarget().getBbHeight() / 1.5;
			double rotXZ = Math.sin(level().getGameTime() * 0.1 + angle) * radius;
			double rotY = Math.cos(level().getGameTime() * 0.1 + angle) * radius;
			Vec3 bodyYaw = new Vec3(sinYaw, 1, cosYaw);
			Vec3 offset = new Vec3(sinYaw, 0, cosYaw).scale(-0.75);
			Vec3 imInSpainWithoutTheA = bodyYaw.multiply(rotXZ, rotY, rotXZ).yRot((float) Math.toRadians(90));
			Vec3 targetPos = getTarget().position().add(0, radius, 0).add(imInSpainWithoutTheA).add(offset);
			Vec3 direction = targetPos.subtract(position());
			move(MoverType.SELF, direction);
		}
		else {
			noPhysics = false;
			setNoGravity(false);
		}

		super.tick();
	}

@Override
	protected boolean addToInitialFrontier(Level world, BlockPos pos, Direction direction, Queue<BlockPos> frontier) throws AssemblyException {
		frontier.clear();
		boolean sticky = isStickyPiston(world.getBlockState(pos.relative(orientation, -1)));
		boolean retracting = direction != orientation;
		if (retracting && !sticky)
			return true;
		for (int offset = 0; offset <= AllConfigs.server().kinetics.maxChassisRange.get(); offset++) {
			if (offset == 1 && retracting)
				return true;
			BlockPos currentPos = pos.relative(orientation, offset + initialExtensionProgress);
			if (retracting && world.isOutsideBuildHeight(currentPos))
				return true;
			if (!world.isLoaded(currentPos))
				throw AssemblyException.unloadedChunk(currentPos);
			BlockState state = world.getBlockState(currentPos);
			if (!BlockMovementChecks.isMovementNecessary(state, world, currentPos))
				return true;
			if (BlockMovementChecks.isBrittle(state) && !(state.getBlock() instanceof WoolCarpetBlock))
				return true;
			if (isPistonHead(state) && state.getValue(FACING) == direction.getOpposite())
				return true;
			if (!BlockMovementChecks.isMovementAllowed(state, world, currentPos))
				if (retracting)
					return true;
				else
					throw AssemblyException.unmovableBlock(currentPos, state);
			if (retracting && state.getPistonPushReaction() == PushReaction.PUSH_ONLY)
				return true;
			frontier.add(currentPos);
			if (BlockMovementChecks.isNotSupportive(state, orientation))
				return true;
		}
		return true;
	}

private Map<PhotonFXRenderPass, Queue<IParticle>> routePasses() {
        lateGroup = null;
        // Under a shader pack there is nothing to split TO: every pass already accumulates into one
        // layer, and unreproducible blends are approximated rather than rerouted.
        if (irisTarget != null || !isLateCapablePipeline()) return particles;

        boolean anyInline = false;
        boolean anyLate = false;
        for (var entry : particles.entrySet()) {
            // an empty queue draws nothing; letting it vote would allocate and composite a blank
            // layer, and would keep the depth snapshot armed, for a pass with no particles in it
            if (entry.getValue().isEmpty()) continue;
            if (isLatePass(entry.getKey())) anyLate = true; else anyInline = true;
            if (anyInline && anyLate) break;
        }
        if (!anyLate) return particles;
        // Something wants the layer, so keep the snapshot coming even when the global default is
        // VANILLA. Recorded BEFORE the availability check on purpose: that is what arms the capture
        // for an emitter-level override, which would otherwise never get a snapshot to route into.
        OpaqueDepthCapture.demand();
        // No snapshot this frame means no depth to test against — anything drawn into the layer
        // would float in front of the terrain. Fall back rather than render something visibly broken.
        if (!OpaqueDepthCapture.hasCaptureThisFrame()) return particles;
        if (!anyInline) {
            lateGroup = particles;
            return Map.of();
        }
        var inline = new TreeMap<PhotonFXRenderPass, Queue<IParticle>>(makeRenderPassComparator());
        var late = new TreeMap<PhotonFXRenderPass, Queue<IParticle>>(makeRenderPassComparator());
        for (var entry : particles.entrySet()) {
            (isLatePass(entry.getKey()) ? late : inline).put(entry.getKey(), entry.getValue());
        }
        lateGroup = late;
        return inline;
    }

public void tick(Level level, BlockPos pos, BlockState state) {
        if (redstonePower > 0 && level.getGameTime() % tickrate() == 0 && level.hasNeighborSignal(pos) && isFunctional()) {
            BlockPos targetPos = pos.below(2);
            BlockState targetState = level.getBlockState(targetPos);

            HammerHeadBlockEntity head = TileEntityOptional.from(level, pos.below(), HammerHeadBlockEntity.class).orElse(null);

            if (head == null || head.isJammed()) {
                return;
            }

            CastOptional.cast(targetState.getBlock(), IInteractiveBlock.class)
                    .map(block -> block.getPotentialInteractions(level, targetPos, targetState, Direction.UP, Collections.singletonList(TetraToolActions.hammer)))
                    .stream()
                    .flatMap(Arrays::stream)
                    .filter(interaction -> TetraToolActions.hammer.equals(interaction.requiredTool))
                    .filter(interaction -> getHammerLevel() >= interaction.requiredLevel)
                    .findFirst()
                    .ifPresent(interaction -> {
                        interaction.applyOutcome(level, targetPos, targetState, null, null, Direction.UP);

                        // the workbench triggers the hammer on the server side, so no need to consume fuel and play sounds
                        if (!(targetState.getBlock() instanceof AbstractWorkbenchBlock)) {
                            if (!level.isClientSide) {
                                consumeFuel();
                            } else {
                                head.activate();
                                level.playSound(null, pos, SoundEvents.ANVIL_LAND, SoundSource.BLOCKS, 0.2f, (float) (0.5 + Math.random() * 0.2));
                            }
                        } else {
                            head.activate();
                        }
                    });
        }
    }

public static void handle(SyncConfigSettingsMessage message, Supplier<NetworkEvent.Context> contextSupplier)
    {
        NetworkEvent.Context context = contextSupplier.get();
        context.enqueueWork(() ->
        {
            RegistryAccess registryAccess = RegistryHelper.getRegistryAccess();

            if (context.getDirection().getReceptionSide().isServer())
            {
                if (context.getSender() != null && context.getSender().hasPermissions(2))
                {
                    ConfigSettings.decode(message.configValues);
                    ConfigSettings.saveValues(registryAccess);
                    MainSettingsConfig.save();
                    WorldSettingsConfig.save();
                    ItemSettingsConfig.save();
                    EntitySettingsConfig.save();
                    ColdSweatPacketHandler.INSTANCE.send(PacketDistributor.ALL.noArg(), new SyncConfigSettingsMessage(null, registryAccess));
                }
            }
            else if (context.getDirection().getReceptionSide().isClient())
            {
                try
                {   ConfigSettings.decode(message.configValues);
                }
                catch (Exception e)
                {   ColdSweat.LOGGER.error("Failed to decode config settings from server: ", e);
                }
                if (message.menuOpener != null && message.menuOpener.equals(ClientOnlyHelper.getClientPlayer().getUUID()))
                {   ClientOnlyHelper.openConfigScreen();
                }
            }
        });
        context.setPacketHandled(true);
    }

