public void tick() {
        if (this.level != null) {
            if (this.level.getBlockState(this.getBlockPos()).getBlock() instanceof WindBlowerBlock){
                Direction facing = this.level.getBlockState(this.getBlockPos()).getValue(WindBlowerBlock.FACING);
                double power = this.level.getBlockState(this.getBlockPos()).getValue(WindBlowerBlock.POWER);
                boolean active = power > 0;
                if (this.level.getBlockEntity(this.worldPosition) instanceof WindBlowerBlockEntity fan) {
                    if (this.level.getGameTime() % 2 == 0 && this.level.getBlockState(this.worldPosition).getBlock() instanceof WindBlowerBlock){
                        if (active) {
                            fan.blowEntities();
                        }
                    }
                    if (!this.level.isClientSide) {
                        this.level.sendBlockUpdated(this.getBlockPos(), this.level.getBlockState(this.getBlockPos()), this.level.getBlockState(this.getBlockPos()), 8);
                    }
                    //Particle codes based of Create mod's Air Flow Particle: https://github.com/Creators-of-Create/Create/blob/mc1.18/dev/src/main/java/com/simibubi/create/content/kinetics/fan/AirFlowParticle.java
                    if (this.level.isClientSide){
                        if (active && this.level.random.nextFloat() <= 0.25F) {
                            Vec3 pos = getCenterOf(this.getBlockPos()).add(Vec3.atLowerCornerOf(facing.getNormal()).scale(0.5D));
                            Vec3 direction = Vec3.atLowerCornerOf(facing.getNormal());
                            Vec3 motion = direction.scale(1 / 8.0F);
                            double distance = new Vec3(this.getBlockPos().getX(), this.getBlockPos().getY(), this.getBlockPos().getZ()).subtract(getCenterOf(this.getBlockPos())).multiply(direction).length() - 0.5F;
                            motion = motion.scale(power - (distance - 1.0F)).scale(0.5F);
                            this.level.addParticle(ModParticleTypes.FAN_CLOUD.get(), pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
                            pos = pos.offsetRandom(this.level.getRandom(), 1.01F);
                            int width = this.level.getRandom().nextIntBetweenInclusive(1, 4);
                            float height = this.level.getRandom().nextFloat() * 0.5F;
                            this.level.addParticle(new WindBlowParticleOption(ColorUtil.WHITE, width, height), pos.x, pos.y, pos.z, motion.x, motion.y, motion.z);
                        }
                    }
                }
                this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(WindBlowerBlock.POWERED, active), 3);
            }
        }
    }

public static void consume(SAddBrewParticlesPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            Level level = Goety.PROXY.getLevel();
            if (level instanceof ClientLevel clientWorld) {
                int area = BrewUtils.getAreaOfEffect(packet.itemStack) + 4;
                Vec3 vec3 = Vec3.atBottomCenterOf(packet.blockPos);

                for(int l = 0; l < 8; ++l) {
                    clientWorld.addParticle(new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(ModItems.SPLASH_BREW.get())), vec3.x, vec3.y, vec3.z, clientWorld.random.nextGaussian() * 0.15D, clientWorld.random.nextDouble() * 0.2D, clientWorld.random.nextGaussian() * 0.15D);
                }

                float f0 = (float)(packet.color >> 16 & 255) / 255.0F;
                float f1 = (float)(packet.color >> 8 & 255) / 255.0F;
                float f2 = (float)(packet.color & 255) / 255.0F;
                ParticleOptions particleoptions = packet.instant ? ParticleTypes.INSTANT_EFFECT : ParticleTypes.EFFECT;

                for(int j3 = 0; j3 < 100 * (BrewUtils.getAreaOfEffect(packet.itemStack) + 1); ++j3) {
                    float f3 = clientWorld.random.nextFloat() * area;
                    float f4 = clientWorld.random.nextFloat() * (float)(Math.PI * (area / 2.0F));
                    double d1 = Math.cos(f4) * f3;
                    double d2 = 0.01D + clientWorld.random.nextDouble() * 0.5D + (area / 10.0D);
                    double d3 = Math.sin(f4) * f3;
                    Particle particle = ParticleUtil.addParticleInternal(particleoptions, particleoptions.getType().getOverrideLimiter(), vec3.x + d1 * 0.1D, vec3.y + 0.3D, vec3.z + d3 * 0.1D, d1, d2, d3);
                    if (particle != null) {
                        float f5 = 0.75F + clientWorld.random.nextFloat() * 0.25F;
                        particle.setColor(f0 * f5, f1 * f5, f2 * f5);
                        particle.setPower((float)f3);
                    }
                }

                clientWorld.playLocalSound(packet.blockPos.getX(), packet.blockPos.getY(), packet.blockPos.getZ(), SoundEvents.SPLASH_POTION_BREAK, SoundSource.NEUTRAL, 1.0F, clientWorld.random.nextFloat() * 0.1F + 0.9F, false);
            }
        });
        ctx.get().setPacketHandled(true);
    }

@Override
        public boolean getAsBoolean() {
            if (++this.ticks % 2 != 0) {
                return false;
            }
            if (this.axe.isEmpty()) {
                return true;
            }
            int minY = this.hits.keySet().intStream().min().getAsInt();
            Queue<BlockPos> queue = this.hits.get(minY);
            int breaks = 0;
            while (!queue.isEmpty()) {
                BlockPos pos = queue.poll();
                for (BlockPos blockPos : BlockPos.betweenClosed(pos.offset(-1, -1, -1), pos.offset(1, 1, 1))) {
                    if (blockPos.equals(pos)) {
                        continue;
                    }
                    BlockState state = this.level.getBlockState(blockPos);
                    if (state.is(BlockTags.LOGS)) {
                        breakExtraBlock(this.level, blockPos, this.axe, this.owner);
                        if (!this.level.getBlockState(blockPos).is(BlockTags.LOGS)) {
                            this.hits.computeIfAbsent(blockPos.getY(), i -> new ArrayDeque<>()).add(blockPos.immutable());
                            breaks++;
                        }
                    }
                }
                if (breaks > 5) {
                    break;
                }
            }
            if (queue.isEmpty()) {
                this.hits.remove(minY);
            }
            return this.hits.isEmpty();
        }

@Override
        public void handleServer(LinkItemToChatPayload msg, IPayloadContext ctx) {
            Player player = ctx.player();
            if (ItemLinking.isOnCooldown(player.getUUID(), player.level().getGameTime())) {
                return;
            }

            if (!AdventureConfig.enableItemLinking) {
                player.sendSystemMessage(Apotheosis.lang("message", "item_linking_disabled"));
                return;
            }

            AbstractContainerMenu menu = player.containerMenu;
            if (menu.containerId == msg.containerId && menu.slots.size() > msg.slot) {
                Slot slot = menu.getSlot(msg.slot);
                ItemStack stack = slot.getItem();

                int count = stack.getCount();

                // Stacks with a count higher than 99 cannot be serialized, so we have to clamp them.
                if (count > 99) {
                    stack = stack.copyWithCount(99);
                }

                if (stack.getItem() == msg.intendedItem) {
                    Component comp = stack.getDisplayName();
                    if (count > 1) {
                        comp = Apotheosis.lang("chat", "link_item_with_count", String.valueOf(count), comp);
                    }
                    PlayerChatMessage chatMsg = PlayerChatMessage.system("").withUnsignedContent(comp);
                    player.level().getServer().getPlayerList().broadcastChatMessage(chatMsg, (ServerPlayer) player, ChatType.bind(ChatType.CHAT, player));
                    ItemLinking.startCooldown(player.getUUID(), player.level().getGameTime());
                }
            }
        }

@Override
	public void extractRenderState(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		if (tooltip.isEmpty()) {
			return;
		}

		// render background
		float alpha = IDisplayHelper.get().backgroundOpacity();
		boolean root = JadeIds.ROOT.equals(getTag());
		if (root) {
			alpha *= IWailaConfig.get().overlay().getAlpha();
		}
		if (alpha > 0) {
			style.render(graphics, this, getX(), getY(), getWidth(), getHeight(), alpha);
		}

		graphics.enableScissor(getX(), getY(), getX() + getWidth(), getY() + getHeight());
		for (Renderable renderable : renderables) {
			try {
				renderable.extractRenderState(graphics, mouseX, mouseY, partialTicks);
			} catch (Exception e) {
				WailaExceptionHandler.handleErr(e, null, null);
				IDisplayHelper.get().drawBorder(graphics, ((LayoutElement) renderable).getRectangle(), 1, 0x88FF0000, true);
			}
		}
		graphics.disableScissor();

		if (pendingProgress != null) {
			drawBoxProgressBar(graphics, pendingProgress);
		}

		if (root && tooltip.sneakyDetails) {
			IThemeHelper.get().theme().sneakyDetails.render(graphics, partialTicks, this);
		}
	}

@Override
    protected void addAdditionalSaveData(CompoundTag compound)
    {
        var shoalFishListTag = new ListTag();

        for (var fish : this.shoalFishData)
        {
            var compoundTag = new CompoundTag();
            compoundTag.putString(ShoalFishData.ID_TAG, fish.id());
            compoundTag.putUUID(ShoalFishData.UUID_TAG, fish.uuid());
            compoundTag.put(ShoalFishData.DATA_TAG, fish.data());

            shoalFishListTag.add(compoundTag);
        }

        compound.put(SHOAL_FISH_TAG, shoalFishListTag);

        if (this.expiredAt > 0)
        {
            compound.putLong(LIFETIME_TAG, this.expiredAt);
        }

        compound.putBoolean(TREASURED_TAG, this.isTreasured());

        var participatesListTag = new ListTag();

        for (var uuid : this.participates)
        {
            var compoundTag = new CompoundTag();
            compoundTag.putUUID(UUID_TAG, uuid);
            participatesListTag.add(compoundTag);
        }

        compound.put(PARTICIPATES_TAG, participatesListTag);
    }

private void addGlassBlocks() {
        var fusedQuartzTag = tag(EIOTags.Blocks.FUSED_QUARTZ);
        var enlightenedFusedQuartzTag = tag(EIOTags.Blocks.ENLIGHTENED_FUSED_QUARTZ);
        var darkFusedQuartzTag = tag(EIOTags.Blocks.DARK_FUSED_QUARTZ);
        var clearGlassTag = tag(EIOTags.Blocks.CLEAR_GLASS);

        var glassBlockCollections = EIOBlocks.GLASS_BLOCKS.entrySet()
            .stream()
            .sorted(Comparator.comparing(a -> a.getKey().glassName()))
            .map(Map.Entry::getValue)
            .toList();

        for (var glassBlocks : glassBlockCollections) {
            var glassItems = new ArrayList<>(glassBlocks.getAllBlocks()
                .sorted(Comparator.comparing(DeferredHolder::getKey))
                .map(DeferredHolder::get)
                .toList());

            for (var block : glassItems) {
                if (block.glassIdentifier().explosionResistance()) {
                    fusedQuartzTag.add(block);

                    if (block.glassIdentifier().lighting() == GlassLighting.EMITTING) {
                        enlightenedFusedQuartzTag.add(block);
                    }

                    if (block.glassIdentifier().lighting() == GlassLighting.BLOCKING) {
                        darkFusedQuartzTag.add(block);
                    }
                } else {
                    clearGlassTag.add(block);
                }
            }
        }
    }

