@Override
    public void tickServer() {
        super.tickServer();

        if (!acidTank.getFluid().isEmpty()) {
            int tickInterval = getTickInterval();

            final Level level = nonNullLevel();
            if (level.getGameTime() % tickInterval == 0) {
                boolean didWork = false;
                for (int i = 0; i < ETCHING_SLOTS; i++) {
                    ItemStack stack = itemHandler.getStackInSlot(i);
                    if (!stack.isEmpty()) {
                        int etchProgress = EmptyPCBItem.getEtchProgress(stack);
                        if (etchProgress < 100) {
                            EmptyPCBItem.setEtchProgress(stack, etchProgress + 1);
                            didWork = true;
                        } else if (!isOutputFull() && !isFailedOutputFull()) {
                            int uvProgress = UVLightBoxBlockEntity.getExposureProgress(stack);
                            boolean success = level.random.nextInt(100) <= uvProgress;
                            tryMoveFinishedItem(i, success);
                        }
                    }
                }

                if (didWork && tickInterval < 30) {
                    // heated - chance to use up some acid
                    if (level.random.nextInt(100) < 30 - tickInterval) {
                        acidTank.drain(1, IFluidHandler.FluidAction.EXECUTE);
                    }
                    heatExchanger.addHeat(-(30 - tickInterval));
                }
            }
        }
    }

@Override
    public void move(double nx, double ny, double nz) {

        if (this.hasPhysics) {
            if ((nx != 0.0 || ny != 0.0 || nz != 0.0) && nx * nx + ny * ny + nz * nz < MAX_COLLISION_VELOCITY) {
                var bb = this.getBoundingBox();
                Vec3 correctedSpeedFactor = Entity.collideBoundingBox(null, new Vec3(nx, ny, nz), bb, this.level, List.of());
                boolean xc = correctedSpeedFactor.x != nx;
                boolean yc = correctedSpeedFactor.y != ny;
                boolean zc = correctedSpeedFactor.z != nz;
                boolean collided = xc || yc || zc;
                if (collided) {
                    float bounciness = bounciness();


                    if (expireOnCollide()) {
                        this.remove();
                    }

                    if (xc)
                        this.speed.x *= -1;
                    if (yc)
                        this.speed.y *= -1;
                    if (zc)
                        this.speed.z *= -1;

                    this.position.y = (float) (yo + correctedSpeedFactor.y);

                    this.speed.y *= bounciness;
                    this.speed.x = Mth.sign(this.speed.x) * Mth.clamp(Math.abs(this.speed.x) - (collisionDrag() * TIME_SCALE), 0, Float.POSITIVE_INFINITY);
                    this.speed.z = Mth.sign(this.speed.z) * Mth.clamp(Math.abs(this.speed.z) - (collisionDrag() * TIME_SCALE), 0, Float.POSITIVE_INFINITY);
                }
            }
        }
    }

