public static void handle(PacketSyncOptions msg, Supplier<NetworkEvent.Context> ctx) {
		ctx.get().enqueueWork(() -> {

			/*
			 * Receiving this packet from server explicitly signifies that we have logged
			 * in to either a dedicated server, or integrated server that we do not host
			 * ourselves, so let's keep track of it.
			 */

			OmniconfigWrapper.onRemoteServer = true;

			OmniconfigWrapper wrapper = OmniconfigWrapper.wrapperRegistry.get(msg.fileName);

			if (wrapper != null) {

				EnigmaticLegacy.LOGGER.info("Synchronizing values of " + msg.fileName + " with ones dispatched by server...");

				for (String id : msg.synchronizedParameters.keySet()) {
					Omniconfig.GenericParameter parameter = wrapper.invokationMap.get(id);

					if (parameter != null) {
						String oldValue = parameter.valueToString();
						parameter.parseFromString(msg.synchronizedParameters.get(id));

						EnigmaticLegacy.LOGGER.info("Value of '" + parameter.getId() + "' was set to '" + parameter.valueToString() + "'; old value: " + oldValue);
					} else {
						EnigmaticLegacy.LOGGER.error("Value '" + id + "' does not exist in " + msg.fileName + "! Skipping.");
					}
				}
			} else {
				EnigmaticLegacy.LOGGER.fatal("Received synchronization packet for non-existent config file: " + msg.fileName);
			}

		});
		ctx.get().setPacketHandled(true);
	}

@Nullable
		private BlockPos findLightSource(BlockPos pos, int maxChecks) {
			int lightValue = this.entity.world.getLightFor(EnumSkyBlock.BLOCK, pos);

			if(lightValue > 0) {
				Set<BlockPos> checked = new HashSet<>();
				PriorityQueue<Pair<BlockPos, Integer>> queue = new PriorityQueue<>(1, (p1, p2) -> -Integer.compare(p1.getRight(), p2.getRight()));

				queue.add(Pair.of(pos, lightValue));

				while(!queue.isEmpty() && maxChecks-- > 0) {
					Pair<BlockPos, Integer> queueEntry = queue.remove();
					BlockPos queuePos = queueEntry.getLeft();
					int queueLight = queueEntry.getRight();

					IBlockState state = this.entity.world.getBlockState(queuePos);
					if(state.getLightValue(this.entity.world, queuePos) > 0) {
						return queuePos;
					}

					for(EnumFacing offset : EnumFacing.VALUES) {
						BlockPos offsetPos = queuePos.offset(offset);

						if(this.entity.world.isBlockLoaded(offsetPos, false)) {
							lightValue = this.entity.world.getLightFor(EnumSkyBlock.BLOCK, offsetPos);

							if(lightValue > queueLight && checked.add(offsetPos)) {
								queue.add(Pair.of(offsetPos, lightValue));
							}
						}
					}
				}
			}

			return null;
		}

public void resolveIntersectingEdgeGroups(Level level) {
		for (TrackEdge edge : deferredIntersectionUpdates) {
			if (!connectionsByNode.containsKey(edge.node1) || edge != connectionsByNode.get(edge.node1)
				.get(edge.node2))
				continue;
			EdgeData edgeData = edge.getEdgeData();
			for (TrackEdgeIntersection intersection : edgeData.getIntersections()) {
				UUID groupId = edgeData.getGroupAtPosition(this, intersection.location);
				Couple<TrackNodeLocation> target = intersection.target;
				TrackGraph graph = Create.RAILWAYS.getGraph(level, target.getFirst());
				if (graph == null)
					continue;

				TrackNode node1 = graph.locateNode(target.getFirst());
				TrackNode node2 = graph.locateNode(target.getSecond());
				Map<TrackNode, TrackEdge> connectionsFrom = graph.getConnectionsFrom(node1);
				if (connectionsFrom == null)
					continue;
				TrackEdge otherEdge = connectionsFrom.get(node2);
				if (otherEdge == null)
					continue;
				UUID otherGroupId = otherEdge.getEdgeData()
					.getGroupAtPosition(graph, intersection.targetLocation);

				SignalEdgeGroup group = Create.RAILWAYS.signalEdgeGroups.get(groupId);
				SignalEdgeGroup otherGroup = Create.RAILWAYS.signalEdgeGroups.get(otherGroupId);
				if (group == null || otherGroup == null || groupId == null || otherGroupId == null)
					continue;

				intersection.groupId = groupId;
				group.putIntersection(intersection.id, otherGroupId);
				otherGroup.putIntersection(intersection.id, groupId);
			}
		}
		deferredIntersectionUpdates.clear();
	}

public void submit(Iterable<? extends Iterable<?>> particleQueues, LightSink sink, float partialTick) {
            int budget = config.maxLights;
            for (var queue : particleQueues) {
                for (var element : queue) {
                    if (budget <= 0) return;
                    if (!(element instanceof TileParticle particle) || particle.getDelay() > 0 || !particle.isAlive()) continue;
                    if (particle.getMemRandom(pickKey) > config.ratio) continue;
                    float t = particle.getT(partialTick);
                    float intensity = this.intensity.get().get(t, () -> particle.getMemRandom(intensityKey)).floatValue();
                    float range = this.range.get().get(t, () -> particle.getMemRandom(rangeKey)).floatValue();
                    var rgba = particle.getRealColor(partialTick);
                    if (config.alphaAffectsIntensity) intensity *= rgba.w;
                    if (config.sizeAffectsRange) {
                        var size = particle.getRealSize(partialTick);
                        range *= Math.max(size.x, Math.max(size.y, size.z));
                    }
                    if (intensity <= 0 || range <= 0) continue;
                    HDRColorFunction.sample(color.get(), t, () -> particle.getMemRandom(colorKey), sample);
                    float r = sample.x, g = sample.y, b = sample.z;
                    if (config.useParticleColor) {
                        r *= rgba.x;
                        g *= rgba.y;
                        b *= rgba.z;
                    }
                    var position = particle.getWorldPos(partialTick);
                    var light = sink.next().at(position.x, position.y, position.z).color(r, g, b).intensity(intensity).range(range)
                            .shadows(config.castShadows).sourceRadius(config.sourceRadius);
                    if (config.spot.isEnable()) config.spot.aim(light, particle);
                    if (config.volumetric.isEnable()) {
                        light.volumetric(Math.max(0f, config.volumetric.getStrength()
                                .get(t, () -> particle.getMemRandom(volumetricKey)).floatValue()));
                    }
                    budget--;
                }
            }
        }

private void compositeToShaderPack() {
        assert irisTarget != null;
        // Defensive: a lock leaked from elsewhere would make the composite a no-op with no other
        // symptom than "the FX vanished".
        if (IrisCompat.isDepthColorLocked()) {
            IrisCompat.degrade("LOCK", "Iris held the depth/colour lock at composite time; released it");
            IrisCompat.unlockDepthColorIfLocked();
        }
        if (irisTarget.compositeMode() == IrisCompositeMode.AFTER_PACK) {
            // Nothing to write yet: the pack's particle target is packed material data. Park the
            // layer and let PhotonPostFX composite it once the pack's own passes are done. Bloom is
            // applied there, once, on the finished layer — not per build.
            pendingLateLayer = DRAW_TARGET;
            pendingLateBloom = wantsBloom();
            restoreEntryState();
            irisTarget = null;
            current = null;
            return;
        }

        int compositeFramebuffer = IrisCompat.compositeFramebuffer(irisTarget);
        if (compositeFramebuffer != 0) {
            int colorTexture = bloomedColorOf(DRAW_TARGET, wantsBloom());
            GlStateManager._glBindFramebuffer(GL30.GL_FRAMEBUFFER, compositeFramebuffer);
            RenderSystem.viewport(entryViewport.position.x, entryViewport.position.y,
                    entryViewport.size.width, entryViewport.size.height);
            // Write alpha only into a translucent accumulator, whose alpha IS the coverage the pack
            // blends with. A scene-colour target's alpha is either absent or the pack's own data.
            SceneBlit.compositePremultipliedToBound(colorTexture, DRAW_TARGET.getColorTextureId(),
                    !irisTarget.primaryIsSceneColor());
        }

        restoreEntryState();
        irisTarget = null;
        current = null;
    }

@SubscribeEvent
        public static void onEatFood(LivingEntityUseItemEvent.Finish event)
        {
            ItemStack item = event.getItem();
            if (event.getEntity() instanceof Player player
            && (item.getUseAnimation() == UseAnim.DRINK || item.getUseAnimation() == UseAnim.EAT)
            && !event.getEntity().level().isClientSide)
            {
                // If food item defined in config
                for (FoodData foodData : ConfigSettings.FOOD_TEMPERATURES.get().get(item.getItem()))
                {
                    if (foodData != null && foodData.test(item))
                    {
                        double temperature = foodData.temperature(item, player);
                        int duration = foodData.duration(item, player);
                        Trait modTrait = duration > 0 ? Trait.BASE : Trait.CORE;
                        // Custom class for soul sprouts
                        FoodTempModifier foodModifier = item.getItem() == ModItems.SOUL_SPROUT
                                                        ? new SoulSproutTempModifier(temperature)
                                                        : new FoodTempModifier(temperature);
                        // Store the item ID & duration of the TempModifier
                        foodModifier.getNBT().putString("item", ForgeRegistries.ITEMS.getKey(item.getItem()).toString());
                        foodModifier.getNBT().putInt("duration", duration);
                        // Set duration & tick rate
                        foodModifier.expires(duration).tickRate(duration);
                        // Add the TempModifier
                        Placement placement = Placement.LAST.limitDuplicates(Matcher.EQUALS, foodData.stackLimit(item, player))
                                              .orElse(Placement.of(Mode.REPLACE, Order.FIRST, foodModifier::equals));
                        Temperature.addModifier(player, foodModifier, modTrait, placement);
                        foodData.modifiers().forEach((trait, modifiers) ->
                        {   modifiers.forEach(modifier -> Temperature.addModifier(player, modifier.get(), trait, placement));
                        });
                    }
                }
            }
        }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            if (player.containerMenu.containerId != this.getContainer()) {
                this.causeError(player);

                return;
            }

            var stack = DescriptionUtils.gatherRelicStack(player, this.getSlot());

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                this.causeError(player);

                return;
            }

            var abilityData = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(this.getAbility());

            var event = new AbilityModeSwitchEvent(player, stack, this.getAbility(), abilityData.getMode(), this.getMode());

            NeoForge.EVENT_BUS.post(event);

            if (!event.isCanceled())
                abilityData.setMode(event.getToMode());

            try {
                player.containerMenu.getSlot(this.getSlot()).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                this.causeError(player);
            }
        });
    }

