@Override
    protected void onHitEntity(EntityHitResult hitResult) {
        Entity hit = hitResult.getEntity();
        if (properties().damageMultiplier() <= 0f) {
            if (!level().isClientSide() && hit instanceof LivingEntity target) {
                ItemStack arrow = getPickupItem();
                if (arrow.getItem() instanceof IVampirismQuarrel<?> quarrel) {
                    quarrel.onHitEntity(arrow, target, this, getOwner());
                }
            }
            return;
        }

        if (this.ignoreHurtTimer && !level().isClientSide() && hit instanceof LivingEntity living && living.getData(ModAttachments.QUARREL_HURT_BYPASS).registerHit(living.level().getGameTime())) {
            living.invulnerableTime = 0;
        }

        float knockbackFactor = properties().knockbackMultiplier();
        Vec3 preHitVelocity = knockbackFactor != 1f && hit instanceof LivingEntity ? hit.getDeltaMovement() : null;

        double ballistaScale = ballistaDamageScale();
        if (ballistaScale > 1) {
            double launchDamage = launchBaseDamage(properties());
            super.setBaseDamage(launchDamage * ballistaScale);
            super.onHitEntity(hitResult);
            super.setBaseDamage(launchDamage);
        } else {
            super.onHitEntity(hitResult);
        }

        if (preHitVelocity != null && hit.isAlive()) {
            Vec3 imparted = hit.getDeltaMovement().subtract(preHitVelocity);
            hit.setDeltaMovement(preHitVelocity.add(imparted.scale(knockbackFactor)));
            hit.hurtMarked = true; // resync the corrected velocity to clients
        }
    }

private void moveEntitiesOnPlatform(double elevatorDelta) {
        if (Math.abs(elevatorDelta) < 1.0E-5) return;

        double oldPlatformY = worldPosition.getY() + oldExtension + 1;
        double newPlatformY = worldPosition.getY() + extension + 1;
        double minPlatformY = Math.min(oldPlatformY, newPlatformY);
        double maxPlatformY = Math.max(oldPlatformY, newPlatformY);
        AABB platformColumn = new AABB(worldPosition.getX(), minPlatformY - 0.5D, worldPosition.getZ(),
                worldPosition.getX() + 1, maxPlatformY + 1.25D, worldPosition.getZ() + 1).inflate(0.2D, 0, 0.2D);

        long gameTime = nonNullLevel().getGameTime();
        for (Entity entity : nonNullLevel().getEntities((Entity) null, platformColumn, Entity::isAlive)) {
            if (MOVED_ENTITIES.getOrDefault(entity, Long.MIN_VALUE) == gameTime) continue;

            double feetY = entity.getBoundingBox().minY;
            if (feetY < minPlatformY - 0.5D || feetY > maxPlatformY + 0.6D) continue;

            MOVED_ENTITIES.put(entity, gameTime);
            entity.move(MoverType.SHULKER_BOX, new Vec3(0, elevatorDelta, 0));

            // On ascent, gently recover entities which are just below the server's platform after collision/latency.
            if (elevatorDelta > 0) {
                double platformGap = newPlatformY - entity.getBoundingBox().minY;
                if (platformGap > 0.01D && platformGap < 1.25D) {
                    entity.move(MoverType.SHULKER_BOX, new Vec3(0, platformGap, 0));
                }
            }

            Vec3 motion = entity.getDeltaMovement();
            if (motion.y < 0 || elevatorDelta > 0) {
                entity.setDeltaMovement(motion.x, 0, motion.z);
            }
            entity.setOnGround(true);
            entity.fallDistance = 0;
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (needUpdateNeighbours) {
            needUpdateNeighbours = false;
            updateNeighbours();
        }
        if (getLevel() instanceof ServerLevel serverLevel && (validatePlayerNow || (getLevel().getGameTime() & 0xf) == 0)) {
            ServerPlayer player = serverLevel.getServer().getPlayerList().getPlayer(playerUUID);
            setPlayer(player);
            if (player != null && player.getTags().contains(NO_AERIAL_INTERFACE)) {
                operatingProblem = OperatingProblem.PLAYER_BARRED;
            } else if (isDimensionBlacklisted(serverLevel, player)) {
                operatingProblem = OperatingProblem.BAD_DIMENSION;
            } else {
                operatingProblem = OperatingProblem.OK;
            }
            validatePlayerNow = false;
        }
        getPlayer().ifPresent(player -> {
            if (aiCanOperate()) {
                addAir(-PneumaticValues.USAGE_AERIAL_INTERFACE);
                if ((nonNullLevel().getGameTime() & 0x3f) == 0) {
                    scanForChargeableItems(player);
                }
                supplyEnergyToPlayer(player);
                supplyAirToPlayer(player);
            }
        });

        if (oldRedstoneStatus != rsController.shouldEmit()) {
            oldRedstoneStatus = rsController.shouldEmit();
            needUpdateNeighbours = true;
        }
    }

private static void validateMovement(ServerPlayer serverPlayer,
										 DeferredHolder<AttachmentType<?>, AttachmentType<Integer>> validator,
										 DeferredHolder<AttachmentType<?>, AttachmentType<Integer>> lastCheck,
										 String movementType) {
		MinecraftServer server = ServerLifecycleHooks.getCurrentServer();
		if (server == null || !server.isDedicatedServer())
			return;
		int count = serverPlayer.getData(validator);
		int lastTick = serverPlayer.getData(lastCheck);
		int currentTick = serverPlayer.tickCount;
		int diff = currentTick - lastTick;
		TwilightForestMod.LOGGER.debug("{} {} check: count={}, lastTick={}, currentTick={}, diff={}",
			serverPlayer.getName().getString(), movementType, count, lastTick, currentTick, diff);

		if (diff >= 45 && !serverPlayer.isFallFlying()) {
			count = -1;
		}

		serverPlayer.setData(lastCheck, currentTick);

		if (count >= 5) {
			serverPlayer.connection.disconnect(new DisconnectionDetails(Component.translatable("multiplayer.disconnect.flying")));
			return;
		}

		serverPlayer.setData(validator, count + 1);

		if (count > 1) {
			TwilightForestMod.LOGGER.warn("{} illegal {}", serverPlayer.getName().getString(), movementType);
			serverPlayer.absSnapTo(serverPlayer.getX(), serverPlayer.getY(), serverPlayer.getZ(),
				serverPlayer.getYRot(), serverPlayer.getXRot());
			serverPlayer.connection.send(ClientboundPlayerPositionPacket.of(serverPlayer.getId(),
				new PositionMoveRotation(serverPlayer.position(), Vec3.ZERO,
				serverPlayer.getYRot(), serverPlayer.getXRot()), Collections.emptySet()));
		}
	}

