	public static void handle(AreaProtectionPacket message, IPayloadContext ctx) {
		//ensure this is only done on clients as this uses client only code
		if (ctx.flow().isClientbound()) {
			ctx.enqueueWork(new Runnable() {
				@Override
				public void run() {
					ClientLevel level = ctx.player().level() instanceof ClientLevel clientLevel ? clientLevel : Minecraft.getInstance().level;
					message.sbb.forEach(box -> {
						for (Entity entity : level.entitiesForRendering()) {
							if (entity instanceof ProtectionBox prot) {
								if (prot.lifeTime > 0 && prot.matches(box)) {
									prot.resetLifetime();
									return;
								}
							}
						}

						level.addEntity(new ProtectionBox(level, box));
					});

					for (int i = 0; i < 20; i++) {
						double vx = level.getRandom().nextGaussian() * 0.02D;
						double vy = level.getRandom().nextGaussian() * 0.02D;
						double vz = level.getRandom().nextGaussian() * 0.02D;

						double x = message.pos.getX() + 0.5D + level.getRandom().nextFloat() - level.getRandom().nextFloat();
						double y = message.pos.getY() + 0.5D + level.getRandom().nextFloat() - level.getRandom().nextFloat();
						double z = message.pos.getZ() + 0.5D + level.getRandom().nextFloat() - level.getRandom().nextFloat();

						level.addParticle(TFParticleType.PROTECTION.get(), x, y, z, vx, vy, vz);
					}
				}
			});
		}
	}

@Override
  public void onProjectileCollision(World world, BlockState state, BlockRayTraceResult hit, ProjectileEntity projectile) {
    if (world.isRemote) return;  // on client - do nothing
    if (!(projectile instanceof AbstractArrowEntity)) return;  // only for arrows
    if (hit.getType() != RayTraceResult.Type.BLOCK) return;  // just being defensive; this should always be true

    BlockPos blockPos = hit.getPos();
    Direction hitFace = hit.getFace();
    Direction directionOfBack = state.get(DIRECTION_THAT_BACK_IS_POINTING);
    Direction directionOfFront = directionOfBack.getOpposite();
    if (hitFace != directionOfFront) return;          // only count hits on the front face

    // when a new arrow hits, remove all others which are already embedded:
    // search for all arrow entities which are colliding with the target, and remove them.

    VoxelShape voxelShape = state.getCollisionShape(world, hit.getPos());
    AxisAlignedBB targetAABB = voxelShape.getBoundingBox();
    AxisAlignedBB targetAABBinWorld = targetAABB.offset(blockPos);
    List<AbstractArrowEntity> embeddedArrows = world.getEntitiesWithinAABB(AbstractArrowEntity.class, targetAABBinWorld);

    for (AbstractArrowEntity embeddedEntity : embeddedArrows) {
      if (embeddedEntity.getEntityId() != projectile.getEntityId()) {
        embeddedEntity.remove();
      }
    }

    // update our blockstate to reflect which ring the arrow is stuck into.
    int arrowDistanceFromCentre = findArrowDistanceFromCentre(directionOfFront, targetAABBinWorld, hit.getHitVec());
    BlockState newBlockState = state.with(ARROW_DISTANCE_FROM_CENTRE, arrowDistanceFromCentre);
    final int FLAGS = SetBlockStateFlag.get(SetBlockStateFlag.BLOCK_UPDATE, SetBlockStateFlag.SEND_TO_CLIENTS);
    world.setBlockState(blockPos, newBlockState, FLAGS);
    informNeighborsOfPowerChange(newBlockState, world, blockPos);

    // start periodically checking whether the arrow has disappeared or been removed
    world.getPendingBlockTicks().scheduleTick(blockPos, this, this.tickRate(world));
  }

@Override
    public void tick() {
        if (level.isClientSide)
            return;
        if (backoffTicks > 0) {
            backoffTicks--;
        }
        if (!powered && backoffTicks <= 0 && level.getGameTime() % 20 == 0) {
            insertNearbyItems();
        }
        if (checkPlayerRangeTicks > 0) {
            checkPlayerRangeTicks--;
        }
        if (checkPlayerRangeTicks <= 0) {
            // Turn off bookwyrm tasks if no player is nearby
            checkPlayerRangeTicks = 60 + level.random.nextInt(5);
            canCreateTasks = false;
            ServerLevel serverLevel = (ServerLevel) level;
            for (ServerPlayer serverPlayer : serverLevel.players()) {
                if (BlockUtil.distanceFrom(level, serverPlayer.position(), this.getBlockPos()) < 40) {
                    canCreateTasks = true;
                    break;
                }
            }
        }

        if (invalidateNextTick) {
            invalidateCapabilities();
            invalidateNextTick = false;
        }

        if (updateItems) {
            updateItems();
            updateItems = false;
        }
    }

@Override
    public StarbyState onDestinationReached() {
        IItemHandler iItemHandler = behavior.getItemCapFromTile(targetPos, behavior.FROM_DIRECTION_MAP.get(targetPos.hashCode()));
        if (iItemHandler == null) {
            starbuncle.addGoalDebug(this, new DebugEvent("NoItemHandler", "No item handler at " + targetPos.toString()));
            return nextState;
        }

        giveStarbyStack(starbuncle, iItemHandler);
        if (starbuncle.getHeldStack().isEmpty()) {
            starbuncle.addGoalDebug(this, new DebugEvent("TakeFromChest", "No items to take? Cancelling goal."));
            return nextState;
        }

        starbuncle.addGoalDebug(this, new DebugEvent("SetHeld", "Taking " + starbuncle.getHeldStack().getHoverName().getString() + " from " + targetPos.toString()));
        starbuncle.level.playSound(null, starbuncle.getX(), starbuncle.getY(), starbuncle.getZ(),
                SoundEvents.ITEM_PICKUP, starbuncle.getSoundSource(), 1.0F, 1.0F);

        OpenChestEvent event = new OpenChestEvent((ServerLevel) level, targetPos, 20);
        event.open();
        EventQueue.getServerInstance().addEvent(event);

        for (Entity entity : starbuncle.getIndirectPassengers()) {
            if (!(entity instanceof Starbuncle passenger) || !passenger.getHeldStack().isEmpty()) {
                break;
            }
            giveStarbyStack(passenger, iItemHandler);
            if (passenger.getHeldStack().isEmpty()) {
                break;
            }
            starbuncle.addGoalDebug(this, new DebugEvent("SetHeldPassenger", "Taking " + passenger.getHeldStack().getHoverName().getString() + " from " + targetPos.toString()));
        }


        return nextState;
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        if (level instanceof ServerLevel serverlevel) {
            level.playSound(null, player, SoundEvents.UI_CARTOGRAPHY_TABLE_TAKE_RESULT, player.getSoundSource(), 1.0F, 1.0F);
            ItemStack itemStack = player.getItemInHand(hand);
            player.getCooldowns().addCooldown(itemStack.getItem(), 50);

            if (itemStack.has(ComponentRegistry.FURLED_MAP_COMPONENT)) {
                var furledMapData = itemStack.get(ComponentRegistry.FURLED_MAP_COMPONENT);
                ResourceKey<Structure> structureResourceKey = ResourceKey.create(Registries.STRUCTURE, furledMapData.destinationResource);
                var holder = serverlevel.registryAccess().registryOrThrow(Registries.STRUCTURE).getHolder(structureResourceKey).map(HolderSet::direct);
                if (furledMapData.dimension().isPresent()) {
                    var dimensionRestriction = furledMapData.dimension().get();
                    if (!serverlevel.dimension().equals(dimensionRestriction)) {
                        ((ServerPlayer) player).connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("item.irons_spellbooks.furled_map.dimension_fail").withStyle(ChatFormatting.RED)));
                        return InteractionResultHolder.fail(itemStack);
                    }
                }
                if (holder.isPresent()) {
                    Pair<BlockPos, Holder<Structure>> pair = serverlevel.getChunkSource().getGenerator().findNearestMapStructure(serverlevel, holder.get(), player.blockPosition(), 100, ServerConfigs.FURLED_MAPS_SKIP_CHUNKS.get());
                    if (pair != null) {
                        var blockpos = pair.getFirst();
                        ItemStack mapStack = MapItem.create(serverlevel, blockpos.getX(), blockpos.getZ(), (byte) 2, true, true);
                        MapItem.renderBiomePreviewMap(serverlevel, mapStack);
                        MapItemSavedData.addTargetDecoration(mapStack, blockpos, "red_x", MapDecorationTypes.RED_X);
                        furledMapData.descriptionOverride.ifPresent(component -> mapStack.set(DataComponents.CUSTOM_NAME, component));

                        replaceItem(player, mapStack, hand);
                        return InteractionResultHolder.sidedSuccess(itemStack, level.isClientSide);
                    }
                }
            }
            replaceItem(player, new ItemStack(Items.MAP), hand);
        }
        return super.use(level, player, hand);
    }

