@SubscribeEvent
    public static void setup(FMLCommonSetupEvent event) {
        event.enqueueWork(() -> {
            // enqueueWork swallows exceptions without logging
            try {
                //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                // ADVANCEMENT CRITERIA
                //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                CriteriaTriggers.register(BlockUseCriterion.trigger);
                CriteriaTriggers.register(BlockInteractionCriterion.trigger);
                CriteriaTriggers.register(ModuleCraftCriterion.trigger);
                CriteriaTriggers.register(ImprovementCraftCriterion.trigger);
                CriteriaTriggers.register(DestabilizeCriterion.trigger);

                //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                // ITEM PREDICATES
                //////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////
                ItemPredicate.register(new ResourceLocation("tetra:modular_item"), ItemPredicateModular::new);
                ItemPredicate.register(new ResourceLocation("tetra:item_effect"), EffectItemPredicate::new);
                ItemPredicate.register(new ResourceLocation("tetra:material"), MaterialItemPredicate::new);
                ItemPredicate.register(new ResourceLocation("tetra:loose"), LooseItemPredicate::new);
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        blocks.getEntries().stream()
                .map(RegistryObject::get)
                .filter(block -> block instanceof InitializableBlock)
                .map(block -> (InitializableBlock) block)
                .forEach(block -> block.commonInit(TetraMod.packetHandler));
        items.getEntries().stream()
                .map(RegistryObject::get)
                .filter(item -> item instanceof InitializableItem)
                .map(item -> (InitializableItem) item)
                .forEach(item -> item.commonInit(TetraMod.packetHandler));
    }

public static void onPlayerTick(TickEvent.PlayerTickEvent event) {
        if (event.player.level().getGameTime() % 2 == 0) {
            if (hasApplicableItem(event.player) && event.player.isCrouching()) {
                Player player = event.player;
                int id = getIdentifier(player);
                Integer duration = cache.getIfPresent(id);
                boolean isDrawing = isDrawing(event.player);
                int change = isDrawing ? 1 : 2;
                cache.put(id, duration != null ? duration + change : change);

                if (!player.level().isClientSide) {
                    int respiration = EnchantmentHelper.getRespiration(player);
                    int amount = isDrawing ? 6 : 2;
                    int reduction = 0;
                    if (respiration > 0) {
                        for (int i = 0; i < amount - 1; i++) {
                            // slightly offset from how the vanilla calculations work
                            if (player.getRandom().nextInt(respiration + 2) > 1) {
                                reduction++;
                            }
                        }
                    }
                    player.setAirSupply(player.getAirSupply() - (amount - reduction));

                    if (player.getAirSupply() <= -20) {
                        player.setAirSupply(0);

                        // todo 1.20: custom damage type for this
                        player.hurt(player.level().damageSources().drown(), 2.0F);
                    }
                }

            } else {
                cache.invalidate(getIdentifier(event.player));
            }
        }
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            if (player.containerMenu.containerId != this.getContainer()) {
                this.causeError(player);

                return;
            }

            var stack = DescriptionUtils.gatherRelicStack(player, this.getSlot());

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                this.causeError(player);

                return;
            }

            var abilityData = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(this.getAbility());

            if (abilityData.getTemplate() == null || !abilityData.getTemplate().getRankModifiers().containsValue(this.getRankModifier())) {
                this.causeError(player);

                return;
            }

            abilityData.getRankModifierData(this.getRankModifier()).setEnabled(this.isEnabled());

            try {
                player.containerMenu.getSlot(this.getSlot()).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                this.causeError(player);
            }
        });
    }

