public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            Player player = ctx.player();

            if (player.containerMenu.containerId != container) {
                causeError(player);

                return;
            }

            ItemStack stack = DescriptionUtils.gatherRelicStack(player, slot);

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                causeError(player);

                return;
            }

            var relicData = relic.getRelicData(player, stack);

            if (!relicData.getLevelingData().isPointsMismatch())
                return;

            relicData.getLevelingData().setPoints(relicData.getLevelingData().getLevel());

            for (var data : relicData.getTemplate().getAbilities().getAbilities().values())
                relicData.getAbilitiesData().getAbilityData(data.getId()).setLevel(0);

            try {
                player.containerMenu.getSlot(slot).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                causeError(player);
            }
        });
    }

@Override
	public void releaseUsing(ItemStack handgun, Level level, LivingEntity livingEntity, int timeLeft) {
		if (!(livingEntity instanceof Player player)) {
			return;
		}

		// fire bullet
		if (hasAmmo(handgun)) {
			if (isCooldownOver(player.level(), handgun)) {
				setFiringCooldown(handgun, level, player);
				fireBullet(handgun, level, player, handgun == player.getMainHandItem() ? InteractionHand.MAIN_HAND : InteractionHand.OFF_HAND);
			}
			return;
		}

		// arbitrary "feels good" cooldown for after the reload - this is to prevent accidentally discharging the weapon immediately after reload.
		setCooldown(handgun, player.level().getGameTime() + 12);

		getMagazineSlot(player).ifPresent(slot -> {
			ItemStack magazine = player.getInventory().items.get(slot);
			setMagazineType(handgun, magazine);
			setPotionEffects(handgun, magazine.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY));
			magazine.shrink(1);
			if (magazine.isEmpty()) {
				player.getInventory().items.set(slot, ItemStack.EMPTY);
			}
			player.swing(player.getUsedItemHand());
			spawnEmptyMagazine(player);
			setBulletCount(handgun, (short) 8);
			player.level().playSound(null, player.blockPosition(), ModSounds.HANDGUN_LOAD.get(), SoundSource.PLAYERS, 0.25F, 1.0F);
			setFiringCooldown(handgun, level, player);
		});

		if (getBulletCount(handgun) == 0) {
			setPotionEffects(handgun, PotionContents.EMPTY);
		}
	}

private void onWorldTick(LevelTickEvent.Post event) {
		if (event.getLevel().isClientSide()) {
			return;
		}

		ResourceLocation dimensionKey = event.getLevel().dimension().location();
		boolean runSlownessLogic = Boolean.TRUE.equals(Config.SERVER.nerfsConfig.tooManyBackpacksSlowness.get());
		boolean runDedupeLogic = Boolean.FALSE.equals(Config.SERVER.tickDedupeLogicDisabled.get());
		if ((!runSlownessLogic && !runDedupeLogic) || nextBackpackCheckTime.getOrDefault(dimensionKey, 0L) > event.getLevel().getGameTime()) {
			return;
		}
		nextBackpackCheckTime.put(dimensionKey, event.getLevel().getGameTime() + BACKPACK_CHECK_COOLDOWN);

		Map<UUID, IBackpackWrapper> backpackIds = new HashMap<>();

		event.getLevel().players().forEach(player -> {
			Set<ItemStack> allBackpacks = new HashSet<>();
			PlayerInventoryProvider.get().runOnBackpacks(player, (backpack, handlerName, identifier, slot) -> {
				if (runSlownessLogic) {
					allBackpacks.add(backpack);
				}
				if (runDedupeLogic && LinkedStorageStackLifecycle.classifyEndpoint(backpack) != LinkedStorageEndpointStackState.ENDPOINT) {
					addBackpackIdIfUniqueOrDedupe(backpackIds, BackpackWrapper.fromStack(backpack));
				}
				return false;
			});
			if (runSlownessLogic) {
				int maxNumberOfBackpacks = Config.SERVER.nerfsConfig.maxNumberOfBackpacks.get();
				if (allBackpacks.size() > maxNumberOfBackpacks) {
					int numberOfSlownessLevels = Math.min(10, (int) Math
							.ceil((allBackpacks.size() - maxNumberOfBackpacks) * Config.SERVER.nerfsConfig.slownessLevelsPerAdditionalBackpack.get()));
					Holder<MobEffect> effect = Config.SERVER.nerfsConfig.getEffect();
					player.addEffect(new MobEffectInstance(effect, BACKPACK_CHECK_COOLDOWN * 2, numberOfSlownessLevels - 1, false, false));
				}
			}
		});
	}

@Override
	public BlockState updateShape(BlockState state, Direction facing, BlockState facingState, LevelAccessor level, BlockPos currentPos, BlockPos facingPos) {
		if (level.getBlockEntity(currentPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).map(StorageBlockEntity::isBeingUpgraded).orElse(false)) {
			return state;
		}
		if (Boolean.TRUE.equals(state.getValue(WATERLOGGED))) {
			level.scheduleTick(currentPos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
		}

		if (isSameChest(facingState, level, currentPos, facingPos) && facing.getAxis().isHorizontal()) {
			ChestType chesttype = facingState.getValue(TYPE);
			if (state.getValue(TYPE) == ChestType.SINGLE && chesttype != ChestType.SINGLE && state.getValue(FACING) == facingState.getValue(FACING)
					&& getConnectedDirection(facingState) == facing.getOpposite()) {
				level.getBlockEntity(currentPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).ifPresent(be -> {
					if (state.getBlock() instanceof ChestBlock chestBlock
							&& be.getStorageWrapper().getInventoryHandler().getSlots() <= chestBlock.getNumberOfInventorySlots()) {
						joinWithChest(level, facingPos, chesttype.getOpposite(), be);
					}
					if (be.isMainChest()) {
						be.getStorageWrapper().getUpgradeHandler().refreshUpgradeWrappers();
					}
				});
				return state.setValue(TYPE, chesttype.getOpposite());
			}
		} else if (getConnectedDirection(state) == facing) {
			level.getBlockEntity(currentPos, ModBlocks.CHEST_BLOCK_ENTITY_TYPE.get()).ifPresent(be -> {
				if (!level.isClientSide() && !be.isBeingUpgraded() && !be.isPacked()) {
					if (be.isMainChest() && !isLinkedChest(be) && state.getBlock() instanceof ChestBlock chestBlock) {
						be.dropSecondPartContents(chestBlock, facingPos);
					}
				}
			});
			return state.setValue(TYPE, ChestType.SINGLE);
		}

		return super.updateShape(state, facing, facingState, level, currentPos, facingPos);
	}

@Override
    public void render(BrewCauldronBlockEntity entity, float tickDelta, PoseStack matrices, MultiBufferSource vertexConsumers, int light, int overlay) {
        Level world = entity.getLevel();
        if (world != null) {
            BlockPos pos = entity.getBlockPos();
            int level = entity.getBlockState().getValue(ModStateProperties.LEVEL_BREW);
            if (level > 0) {
                if (entity.isHeated() && !Minecraft.getInstance().isPaused()) {
                    float fluidHeight = 0;
                    float width = 0.35f;
                    switch (entity.getBlockState().getValue(ModStateProperties.LEVEL_BREW)) {
                        case 1 -> fluidHeight = 0.225f;
                        case 2 -> {
                            fluidHeight = 0.425f;
                            width = 0.3f;
                        }
                        case 3 -> fluidHeight = 0.625f;
                    }
                    if (fluidHeight > 0) {
                        double[] rgb = MathHelper.rgbParticle(entity.getColor());
                        if (entity.mode == BrewCauldronBlockEntity.Mode.BREWING) {
                            if (entity.isBrewing){
                                world.addParticle(ParticleTypes.WITCH, pos.getX() + 0.5, pos.getY() + fluidHeight, pos.getZ() + 0.5, 0.0F, 0.0F, 0.0F);
                            } else if (entity.getLevel().getGameTime() % 20 == 0){
                                world.addParticle(ParticleTypes.WITCH, pos.getX() + 0.5, pos.getY() + fluidHeight, pos.getZ() + 0.5, 0.0F, 0.0F, 0.0F);
                            }
                        } else if (entity.mode == BrewCauldronBlockEntity.Mode.COMPLETED){
                            world.addParticle(ParticleTypes.ENTITY_EFFECT, pos.getX() + 0.5, pos.getY() + fluidHeight, pos.getZ() + 0.5, rgb[0], rgb[1], rgb[2]);
                        } else if (entity.mode == BrewCauldronBlockEntity.Mode.FAILED){
                            world.addParticle(ParticleTypes.SMOKE, pos.getX() + 0.5, pos.getY() + fluidHeight, pos.getZ() + 0.5, 0.0F, 0.0F, 0.0F);
                        }
                        world.addParticle(ModParticleTypes.BREW_BUBBLE.get(), pos.getX() + 0.5 + Mth.nextDouble(world.random, -width, width), pos.getY() + fluidHeight, pos.getZ() + 0.5 + Mth.nextDouble(world.random, -width, width), rgb[0], rgb[1], rgb[2]);
                    }
                }
            }
        }
    }

@Override
    public BlockState updateShape(BlockState pState, Direction pFacing, BlockState pFacingState, LevelAccessor pLevel, BlockPos pCurrentPos, BlockPos pFacingPos) {
        if (FALLING_REMOVAL.get()) {
            return pState;
        }

        DoubleBlockHalf half = pState.getValue(HALF);

        if (half == DoubleBlockHalf.UPPER && pFacing == Direction.UP) {
            if (!pState.canSurvive(pLevel, pCurrentPos)) {
                if (pLevel instanceof Level level && !level.isClientSide) {
                    level.scheduleTick(pCurrentPos, this, 2);
                }
                return pState;
            }
        }

        if (half == DoubleBlockHalf.UPPER && pFacing == Direction.DOWN) {
            return pFacingState.is(this) && pFacingState.getValue(HALF) == DoubleBlockHalf.LOWER ? pState.setValue(LIT, pFacingState.getValue(LIT)) : Blocks.AIR.defaultBlockState();
        }

        if (half == DoubleBlockHalf.LOWER && pFacing == Direction.UP) {
            return pFacingState.is(this) && pFacingState.getValue(HALF) == DoubleBlockHalf.UPPER ? pState.setValue(LIT, pFacingState.getValue(LIT)) : Blocks.AIR.defaultBlockState();
        }

        if (half == DoubleBlockHalf.LOWER && pFacing == Direction.DOWN) {
            if (!pState.canSurvive(pLevel, pCurrentPos)) {
                BlockPos upperPos = pCurrentPos.above();
                if (pLevel instanceof Level level && !level.isClientSide && pLevel.getBlockState(upperPos).is(this)) {
                    level.scheduleTick(upperPos, this, 2);
                }
                return pState;
            }
        }

        return super.updateShape(pState, pFacing, pFacingState, pLevel, pCurrentPos, pFacingPos);
    }

public static void consume(SStaffParticlePacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            if (ctx.get().getDirection() == NetworkDirection.PLAY_TO_CLIENT) {
                Level level = Goety.PROXY.getLevel();
                if (level instanceof ClientLevel clientWorld && clientWorld.getEntity(packet.playerId) instanceof Player player) {
                    Optional<Vec3> staffEndPos;
                    if (player == Minecraft.getInstance().player && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON) {
                        // first-person staff end position
                        int arm = (player.getMainArm() == HumanoidArm.RIGHT ? 1 : -1) * (packet.offHand ? -1 : 1);
                        double fovFactor = 960.0 / (double) Minecraft.getInstance().options.fov().get();
                        float horizontalFactor = 0.125F * packet.staffHeight + 0.35F, verticalFactor = 1.5F * packet.staffHeight - 0.45F;
                        Vec3 vec3 = Minecraft.getInstance().gameRenderer.getMainCamera().getNearPlane().getPointOnPlane(horizontalFactor * arm, verticalFactor).scale(fovFactor);
                        staffEndPos = Optional.of(player.getEyePosition().add(vec3));
                    } else {
                        // third person staff end position
                        staffEndPos = ModelUtil.getThirdPersonPlayerHandPosition(
                                player,
                                Minecraft.getInstance().getEntityRenderDispatcher(),
                                player.yBodyRotO,
                                0,
                                packet.offHand ? player.getMainArm().getOpposite() : player.getMainArm(),
                                new Vec3(0, 0.55, -packet.staffHeight)
                        );
                    }
                    if (staffEndPos.isPresent()) {
                        Vec3 pos = staffEndPos.get().add(new Vec3(level.random.nextDouble() - 0.5, level.random.nextDouble() - 0.5, level.random.nextDouble() - 0.5).normalize().scale(packet.range));
                        level.addParticle(
                                new GatherTrailParticleOption(new ColorUtil(packet.color), staffEndPos.get()),
                                pos.x, pos.y, pos.z,
                                0, 0, 0
                        );
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

public void aiStep() {
        super.aiStep();

        if (!this.level.isClientSide) {
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.003D, 0.0D));
                if (!this.isNotMoving() && this.random.nextInt(5) == 0 && this.getDeltaMovement().horizontalDistance() > 0.08) {
                    Vec3 testpos = this.position().add(Math.cos(Math.toRadians(this.getYRot()+ 90)) * -0.8, 0, Math.sin(Math.toRadians(this.getYRot() + 90)) * -0.8);
                    BlockPos testblockpos = new BlockPos(testpos);
                    if (level.getBlockState(new BlockPos(testblockpos.below())).is(BlockTags.MINEABLE_WITH_SHOVEL))
                        ((ServerLevel)this.level).sendParticles(new BlockParticleOption(ParticleTypes.FALLING_DUST, this.level.getBlockState(testblockpos.below())), testpos.x, testpos.y + 0.2, testpos.z, 2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, 0);
                    else
                        ((ServerLevel)this.level).sendParticles(ParticleTypes.UNDERWATER, testpos.x, testpos.y + 0.2, testpos.z, 2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, 0);
                }
            }

            if (this.tickCount % 1000 == 0) {
                if (this.wantsToBreed() && !this.isMale()) {
                    this.breed();
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }
        else {
            if (Math.abs(this.getYRot() - this.yRotO) > 0.005) {
                this.offset = Mth.rotLerp(0.05F, this.offset, (this.getYRot() - this.yRotO));
            }
            if (this.isInWater() && !this.isNotMoving()) {
                if (this.swimProgress < 20)
                    this.swimProgress++;
            } else if ((!this.isInWater() || this.isNotMoving()) && this.swimProgress > 0) {
                this.swimProgress--;
            }
        }
    }

public void aiStep() {
        super.aiStep();
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (!this.level.isClientSide) {
            if (this.tickCount % 1000 == 0) {
                if (this.wantsToBreed() && !this.isMale()) {
                    this.breed();
                }
            }
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.005D, 0.0D));
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
            if (this.isInWater() && this.getAnimation() == NO_ANIMATION && this.getTarget() == null && this.level.getBlockState(this.blockPosition().below()).is(BlockTags.MINEABLE_WITH_SHOVEL)) {
                if (this.getCommandInt() == 0) {
                    int i = this.random.nextInt(3000);
                    if (i > 2940 && i < 2960)
                        this.setAnimation(EAT_RIGHT);
                    if (i > 2960 && i < 2980)
                        this.setAnimation(EAT_LEFT);
                    if (i > 2980)
                        this.setAnimation(EAT_BOTH);
                }
            }
            if (this.getAnimation() != NO_ANIMATION) {
                if (((this.getAnimation() == EAT_LEFT || this.getAnimation() == EAT_RIGHT) && (this.getAnimationTick() == 20)) || (this.getAnimation() == EAT_BOTH && (this.getAnimationTick() == 20 || this.getAnimationTick() == 44))) {
