        copy(EIOTags.Blocks.BLOCKS_REDSTONE_ALLOY, EIOTags.Items.BLOCKS_REDSTONE_ALLOY);
        copy(EIOTags.Blocks.BLOCKS_PULSATING_ALLOY, EIOTags.Items.BLOCKS_PULSATING_ALLOY);
        copy(EIOTags.Blocks.BLOCKS_DARK_STEEL, EIOTags.Items.BLOCKS_DARK_STEEL);
        copy(EIOTags.Blocks.BLOCKS_SOULARIUM, EIOTags.Items.BLOCKS_SOULARIUM);
        copy(EIOTags.Blocks.BLOCKS_END_STEEL, EIOTags.Items.BLOCKS_END_STEEL);

        copy(EIOTags.Blocks.FUSED_QUARTZ, EIOTags.Items.FUSED_QUARTZ);
        copy(EIOTags.Blocks.ENLIGHTENED_FUSED_QUARTZ, EIOTags.Items.ENLIGHTENED_FUSED_QUARTZ);
        copy(EIOTags.Blocks.DARK_FUSED_QUARTZ, EIOTags.Items.DARK_FUSED_QUARTZ);
        copy(EIOTags.Blocks.CLEAR_GLASS, EIOTags.Items.CLEAR_GLASS);

        var glassBlockCollections = EIOBlocks.GLASS_BLOCKS.entrySet()
            .stream()
            .sorted(Comparator.comparing(a -> a.getKey().glassName()))
            .toList();

        for (var entry : glassBlockCollections) {
            var glassIdentifier = entry.getKey();
            var glassBlocks = entry.getValue();

            var tag = tag(EIOTags.Items.GLASS_TAGS.get(glassIdentifier));

            var glassItems = new ArrayList<>(glassBlocks.getAllBlocks()
                .sorted(Comparator.comparing(DeferredHolder::getKey))
                .map(i -> i.get().asItem())
                .map(i -> BuiltInRegistries.ITEM.getResourceKey(i).orElseThrow())
                .toList());

            tag.addAll(glassItems);
        }

        tag(Tags.Items.CHAINS).add(EIOBlocks.SOUL_CHAIN.asItem());
    }

public static BehaviorControl<Dracula> create(double radius, int thresholdTicks, int minAttackers) {
        double radiusSqt = radius * radius;

        return BehaviorBuilder.create(inst -> inst.group(
                inst.present(ModMemoryTypes.SURROUNDED_SINCE.get()),
                inst.present(ModMemoryTypes.NEAREST_ATTACKABLE.get()),
                inst.registered(ModMemoryTypes.FLYING_SWORD_ACTIVE.get()),
                inst.registered(ModMemoryTypes.FLYING_SWORD_COOLDOWN.get()),
                inst.registered(ModMemoryTypes.ACTION_ACTIVE.get()),
                inst.registered(ModMemoryTypes.ACTION_COOLDOWN.get()),
                inst.absent(ModMemoryTypes.SURROUNDED_COOLDOWN.get())
        ).apply(inst, (timer,nearest, swordActive, swordCooldown, actionActive, actionCooldown, cooldown) -> (level, dracula, gameTime) -> {
            if (level.getGameTime() - inst.get(timer) < thresholdTicks) return false;

            List<LivingEntity> entities = inst.get(nearest).stream().filter(x -> x.distanceToSqr(dracula) < radiusSqt).toList();
            if (entities.size() < minAttackers) return false;

            for (LivingEntity livingEntity : entities) {
                livingEntity.knockback(1.5, livingEntity.getX() - dracula.getX(), livingEntity.getZ() - dracula.getZ());
                livingEntity.addEffect(new MobEffectInstance(ModEffects.FREEZE, 40, 1));
            }

            Vec3 avgAttackerPos = getAvgPos(entities);
            Vec3 safePos = DefaultRandomPos.getPosAway(dracula, 20, 7, avgAttackerPos);
            if (safePos != null) {
                dracula.teleportTo(safePos.x, safePos.y, safePos.z);
            }

            timer.erase();
            swordActive.set(Unit.INSTANCE);
            swordCooldown.erase();
            actionActive.set(Unit.INSTANCE);
            actionCooldown.erase();
            cooldown.setWithExpiry(Unit.INSTANCE, 20 * 10);
            return true;
        }));
    }

@Override
    public void tickServer() {
        super.tickServer();

        final Level level = nonNullLevel();
        if (level.getGameTime() % 20 == 0) {
            int efficiency = Math.max(1, ConfigHelper.common().machines.pneumaticDynamoEfficiency.get());
            airPerTick = (int) (40 * this.getSpeedUsageMultiplierFromUpgrades() * 100 / efficiency);
            rfPerTick = (int) (40 * this.getSpeedUsageMultiplierFromUpgrades() * getEfficiency() / 100);
        }

        boolean newEnabled;
        if (rsController.shouldRun() && getPressure() > getMinWorkingPressure() && energy.getMaxEnergyStored() - energy.getEnergyStored() >= rfPerTick) {
            this.addAir(-airPerTick);
            heatExchanger.addHeat(airPerTick / 100D);
            energy.receiveEnergy(rfPerTick, false);
            newEnabled = true;
        } else {
            newEnabled = false;
        }
        if ((level.getGameTime() & 0xf) == 0 && newEnabled != isEnabled) {
            isEnabled = newEnabled;
            BlockState state = level.getBlockState(worldPosition);
            level.setBlockAndUpdate(worldPosition, state.setValue(PNCBlockStateProperties.ACTIVE, isEnabled));
        }

        BlockEntity receiver = getCachedNeighbor(getRotation());
        if (receiver != null) {
            IOHelper.getEnergyStorageForBlock(receiver, getRotation().getOpposite()).ifPresent(neighborStorage -> {
                int extracted = energy.extractEnergy(rfPerTick * 2, true);
                int energyPushed = neighborStorage.receiveEnergy(extracted, true);
                if (energyPushed > 0) {
                    neighborStorage.receiveEnergy(energy.extractEnergy(energyPushed, false), false);
                }
            });
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (getMinigun().getAttackTarget() == null && rsController.shouldRun()) {
            getMinigun().setSweeping(true);
            if ((nonNullLevel().getGameTime() & 0xF) == 0) {
                List<LivingEntity> entities = nonNullLevel().getEntitiesOfClass(LivingEntity.class, getTargetingBoundingBox(), entitySelector);
                if (!entities.isEmpty()) {
                    entities.sort(new EntityDistanceComparator(getBlockPos()));
                    getMinigun().setAttackTarget(entities.getFirst());
                    targetEntityId = getMinigun().getAttackTarget().getId();
                } else if (targetEntityId > 0) {
                    getMinigun().setReturning(true);
                    targetEntityId = -1;
                }
            }
        } else {
            getMinigun().setSweeping(false);
        }
        LivingEntity target = getMinigun().getAttackTarget();
        if (target != null) {
            if (rsController.shouldRun() && entitySelector.test(target)) {
                if ((nonNullLevel().getGameTime() & 0x7) == 0) {
                    // Make sure any knockback has the right direction.
                    getFakePlayer().setPos(getBlockPos().getX() + 0.5, getBlockPos().getY() + 0.5, getBlockPos().getZ() + 0.5);
                    if (getMinigun().tryFireMinigun(target).ammoUsedUp()) {
                        clearEmptyAmmo();
                    }
                }
            } else {
                getMinigun().setAttackTarget(null);
                getMinigun().minigunYaw = idleYaw;
                targetEntityId = -1;
            }
        }
    }

private void handleDebugTick() {
        Collection<ServerPlayer> debuggingPlayers = getDebugger().getDebuggingPlayers();

        if (!ConfigHelper.common().drones.droneDebuggerPathParticles.get() || debuggingPlayers.isEmpty()) {
            return;
        }

        PathNavigation navi = getNavigation();
        if (level() instanceof ServerLevel && level().getGameTime() % 10 == 0) { // only generate every 0.5 seconds, to try and cut back on packet spam
            Path path = navi.getPath();
            if (path != null) {
                for (int i = path.getNextNodeIndex(); i < path.getNodeCount(); i++) {
                    //get current point
                    BlockPos pos = path.getNode(i).asBlockPos();  // asBlockPos() = copy()
                    //get next point (or current point)
                    BlockPos nextPos = (i+1) != path.getNodeCount() ? path.getNode(i+1).asBlockPos() : pos;
                    //get difference for vector
                    BlockPos endPos = nextPos.subtract(pos);
                    spawnDebugParticle(debuggingPlayers, ParticleTypes.HAPPY_VILLAGER,
                            pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 0,
                            0, 0, 0, 0);
                    //send a particle between points for direction
                    spawnDebugParticle(debuggingPlayers, ParticleTypes.END_ROD,
                            pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 0,
                            endPos.getX(), endPos.getY(), endPos.getZ(), 0.1);
                }
                // render end point
                BlockPos pos = navi.getTargetPos();  // yes, this *can* be null: https://github.com/TeamPneumatic/pnc-repressurized/issues/761
                //noinspection ConstantConditions
                if (pos != null && getDronePos().distanceToSqr(Vec3.atCenterOf(pos)) > 1) {
                    spawnDebugParticle(debuggingPlayers, ParticleTypes.HEART,
                            pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5, 0,
                            0, 0, 0, 0);
                }
            }
        }
    }

@Override
    public void extractRenderState(
            FramedBannerBlockEntity blockEntity,
            FramedBannerRenderState renderState,
            float partialTick,
            Vec3 cameraPosition,
            ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress
    ) {
        BlockEntityRenderer.super.extractRenderState(blockEntity, renderState, partialTick, cameraPosition, breakProgress);

        Level level = Objects.requireNonNull(blockEntity.getLevel());
        BlockPos pos = blockEntity.getBlockPos();
        BlockState state = blockEntity.getBlockState();

        BlockPos topPos;
        BlockModel blockModel;
        if (state.getBlock() instanceof FramedBannerBlock) {
            int rotation = state.getValue(BlockStateProperties.ROTATION_16);
            topPos = pos.above();
            blockModel = Objects.requireNonNull(flagModel).getModel(rotation);
            renderState.bannerModel = standingModel;
            renderState.bannerTransform = BannerRenderer.TRANSFORMATIONS.freeTransformations(rotation);
            renderState.flagTransform = FLAG_TRANSFORMS.freeTransformations(rotation);
        } else {
            Direction facing = state.getValue(FramedProperties.FACING_HOR);
            topPos = pos;
            blockModel = Objects.requireNonNull(flagModel).getModel(facing);
            renderState.bannerModel = wallModel;
            renderState.bannerTransform = BannerRenderer.TRANSFORMATIONS.wallTransformation(facing);
            renderState.flagTransform = FLAG_TRANSFORMS.wallTransformation(facing);
        }
        BlockDisplayContext context = new FramedBannerFlagModel.DisplayContext(ClientUtils.asTintGetter(level), topPos, level.getModelData(pos));
        blockModel.update(renderState.modelRenderState, state, context, 42L);

        long gameTime = blockEntity.getLevel() != null ? blockEntity.getLevel().getGameTime() : 0L;
        renderState.swing = ((float) Math.floorMod(pos.getX() * 7L + pos.getY() * 9L + pos.getZ() * 13L + gameTime, 100L) + partialTick) / 100.0F;
    }

@Override
    protected void tick() {
        WildenChimera.spawnPhaseParticles(getPos().above(), getWorld(), 1);
        if (getWorld().getGameTime() % 20 == 0)
            incrementProgress();
        if (getWorld().getGameTime() % 60 == 0 && (getWorld() instanceof ServerLevel serverLevel)) {
            FakePlayer fakePlayer = ANFakePlayer.getPlayer(serverLevel, this.playerUUID);
            if (!isBossSpawn()) {
                int wild = rand.nextInt(3);
                BlockPos summonPos = getPos().above().east(rand.nextInt(3) - rand.nextInt(6)).north(rand.nextInt(3) - rand.nextInt(6));
                Mob mobEntity = switch (wild) {
                    case 0 -> new WildenStalker(serverLevel);
                    case 1 -> new WildenGuardian(serverLevel);
                    default -> new WildenHunter(serverLevel);
                };
                summon(mobEntity, summonPos);
                if (getProgress() >= 15) {
                    setFinished();
                }
            } else {
                if (getProgress() >= 8) {
                    WildenChimera chimera = new WildenChimera(serverLevel);
                    summon(chimera, getPos().above());
                    for (BlockPos b : BlockPos.betweenClosed(getPos().east(5).north(5).above(), getPos().west(5).south(5).above(5))) {
                        if (!net.neoforged.neoforge.event.EventHooks.canEntityGrief(serverLevel, chimera)) {
                            continue;
                        }
                        if (serverLevel.getBlockState(b).getDestroySpeed(serverLevel, b) < 0) continue;
                        if (SpellUtil.isCorrectHarvestLevel(4, serverLevel.getBlockState(b))) {
                            BlockUtil.destroyBlockSafelyWithoutSound(serverLevel, b, true, fakePlayer);
                        }
                    }
                    setFinished();
                }
            }
        }
    }

