@Override
    protected void tick(E entity) {
        var treePos = BrainUtil.getMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get());
        if (NearestTreeSensor.isLog(entity.level(), treePos)) {
            BrainUtil.setMemory(entity, MemoryModuleType.LOOK_TARGET, new BlockPosTracker(treePos));
            this.breakingTime++;
            entity.swing(InteractionHand.MAIN_HAND, true);
            int i = (int) ((float) this.breakingTime / 160.0F * 10.0F);
            if (this.breakingTime % 20 == 0) {
                entity.playSound(SoundEvents.WOOD_HIT, 1, 1);
                entity.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1, 0.5F);
            }
            if (i != this.previousBreakProgress) {
                entity.level().destroyBlockProgress(entity.getId(), treePos, i);
                this.previousBreakProgress = i;
            }
            if (this.breakingTime == 160) {
                entity.playSound(SoundEvents.WOOD_BREAK, 1, 1);
                List<BlockPos> stump = new ArrayList<>(List.of());
                this.addAllStump(treePos, entity.level(), stump);
                this.fellTree(entity, treePos);
                var felled = BrainUtil.getMemory(entity, OccultismMemoryTypes.LAST_FELLED_TREE.get());
                if (felled != null) {
                    felled.addAll(stump);
                } else {
                    felled = stump;
                }
                BrainUtil.setMemory(entity, OccultismMemoryTypes.LAST_FELLED_TREE.get(), felled);
                this.doStop((ServerLevel) entity.level(), entity, entity.level().getGameTime());
                //we stop here (even though the above condition would save us) because sensor might reset last felled tree meanwhile
            }

        } else {
            //if the tree is gone, just stop and reset.
            this.doStop((ServerLevel) entity.level(), entity, entity.level().getGameTime());
        }
    }

@Override
    public void tick() {
        Player player = getPlayer();
        if (player == null || !player.isAlive()) {
            stop();
            volume = 0.0F;
            consecutiveTicks = 0;
            return;
        }

        if (shouldPlaySound(player) && sound != null && player.level().tickRateManager().runsNormally()) {
            if (volume < 1.0F) {
                // If we weren't max volume, start fading up
                volume = Math.min(1.0F, volume + fadeUpStep);
            }
            if (consecutiveTicks % subtitleFrequency == 0) {
                SoundManager soundHandler = Minecraft.getInstance().getSoundManager();
                if (!soundHandler.soundEngine.listeners.isEmpty()) {
                    float scaledVolume = Math.max(volume, 1.0F) * sound.getAttenuationDistance();
                    float range = !relative && attenuation != SoundInstance.Attenuation.NONE ? scaledVolume : Float.POSITIVE_INFINITY;
                    for (SoundEventListener soundEventListener : soundHandler.soundEngine.listeners) {
                        WeighedSoundEvents soundEventAccessor = getOrResolve(soundHandler);
                        if (soundEventAccessor != null) {
                            soundEventListener.onPlaySound(this, soundEventAccessor, range);
                        }
                    }
                }
                consecutiveTicks = 1;
            } else {
                consecutiveTicks++;
            }
        } else if (volume > 0.0F) {
            consecutiveTicks = 0;
            // Not yet fully muted, fade down
            volume = Math.max(0.0F, volume - fadeDownStep);
        }
    }

public static BehaviorControl<Yak> createHerdingController() {
		return BehaviorBuilder.create(
				(instance) -> instance.group(
						instance.present(EnvironmentalMemoryModuleTypes.NEAREST_VISIBLE_ADULT_YAKS.get()),
						instance.registered(EnvironmentalMemoryModuleTypes.SINCE_LAST_HERD.get()),
						instance.registered(EnvironmentalMemoryModuleTypes.HERDING_POSITION.get())
				).apply(instance, (nearest, herdTicks, herdPos) -> (level, yak, gameTime) -> {
					int ticksSinceLastHerd = instance.tryGet(herdTicks).orElse(0);

					// Randomly check for a new herd
					// After a certain amount of time, guarantee a herd check
					if (yak.getRandom().nextInt(Yaktelligence.HERD_CHECK_GUARANTEE) < ticksSinceLastHerd++) {
						ticksSinceLastHerd = 0;

						List<Yak> herd = instance.get(nearest);
						if (herd.isEmpty()) {
							// If the yak doesn't know of a herd and can't find a herd, then return back to idle
							// If the yak is leashed we want full control of the yak
							if (instance.tryGet(herdPos).isEmpty() || yak.isLeashed()) {
								yak.getBrain().useDefaultActivity();
								yak.clearRestriction();
							}
						} else if (!yak.isWithinRestriction() || instance.tryGet(herdPos).isEmpty()) {
							// Search for the nearest yaks and find the average position
							// Set the memory to expire to trigger a herd check
							Vector4d herdVec = herd.stream()
									.map(Yak::position)
									.reduce(new Vector4d(0, 0, 0, 0), (a, b) -> a.add(b.x, b.y, b.z, 1), Vector4d::add);
							herdVec = herdVec.div(herdVec.w);
							herdPos.setWithExpiry(BlockPos.containing(herdVec.x, herdVec.y, herdVec.z), Yaktelligence.HERD_MEMORY_EXPIRATION);
						}
					}
					herdTicks.set(ticksSinceLastHerd);

					return true;
				}));
	}

public static ServerLevel backToSpawn(ServerPlayer serverPlayer) {
		ResourceKey<Level> respawnDimension = AdvancedSpawnLocationHelper.getPlayerRespawnDimension(serverPlayer);
		ServerLevel respawnWorld = SuperpositionHandler.getWorld(respawnDimension);

		serverPlayer.level().playSound(null, serverPlayer.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(serverPlayer.getX(), serverPlayer.getY(), serverPlayer.getZ(), 128, serverPlayer.level().dimension())), new PacketPortalParticles(serverPlayer.getX(), serverPlayer.getY() + (serverPlayer.getBbHeight() / 2), serverPlayer.getZ(), 100, 1.25F, false));

		Optional<Vec3> vec = AdvancedSpawnLocationHelper.getValidSpawn(respawnWorld, serverPlayer);
		Optional<Vec3> vec2;
		ServerLevel destinationWorld = vec.isPresent() ? respawnWorld : serverPlayer.server.overworld();

		if (!serverPlayer.level().equals(destinationWorld)) {
			serverPlayer.changeDimension(destinationWorld, new RealSmoothTeleporter());
		}

		if (!respawnWorld.equals(destinationWorld)) {
			vec2 = AdvancedSpawnLocationHelper.getValidSpawn(destinationWorld, serverPlayer);
		} else {
			vec2 = Optional.empty();
		}

		if (vec.isPresent()) {
			Vec3 trueVec = vec.get();
			serverPlayer.teleportTo(trueVec.x, trueVec.y, trueVec.z);
		} else if (vec2.isPresent()) {
			Vec3 trueVec = vec2.get();
			serverPlayer.teleportTo(trueVec.x, trueVec.y, trueVec.z);
		} else {
			AdvancedSpawnLocationHelper.fuckBackToSpawn(serverPlayer.serverLevel(), serverPlayer);
		}

		serverPlayer.level().playSound(null, serverPlayer.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

