private void processQueue(Queue<IPathItem> oldOpen, int queueIndex) {
        while (!oldOpen.isEmpty()) {
            IPathItem i = oldOpen.poll();
            for (IPathItem pi : i.getPossibleOptions()) {
                if (!this.visited.contains(pi)) {
                    // Set BFS parent.
                    pi.setControllerRoute(i);

                    if (pi.hasFlag(GridFlags.REQUIRE_CHANNEL)) {
                        if (!this.multiblocksWithChannel.contains(pi)) {
                            // Try to use the channel along the path.
                            boolean worked = tryUseChannel((GridNode) pi);

                            if (worked && pi.hasFlag(GridFlags.MULTIBLOCK)) {
                                var multiblock = ((IGridNode) pi).getService(IGridMultiblock.class);
                                if (multiblock != null) {
                                    var oni = multiblock.getMultiblockNodes();
                                    while (oni.hasNext()) {
                                        final IGridNode otherNodes = oni.next();
                                        if (otherNodes == null) {
                                            // Only a log for now until addons are fixed too. See
                                            // https://github.com/AppliedEnergistics/Applied-Energistics-2/issues/8295
                                            LOG.error("Skipping null node returned by grid multiblock node {}",
                                                    multiblock);
                                        } else if (otherNodes != pi) {
                                            this.multiblocksWithChannel.add((GridNode) otherNodes);
                                        }
                                    }
                                }
                            }
                        }
                    }

                    enqueue(pi, queueIndex);
                }
            }
        }
    }

private static boolean insertItemToProcess(
			ItemStack stack, boolean simulate, State state, Level rawLevel
	)
	{
		if(state.sawmillProcessQueue.size() >= MAX_PROCESSES)
			return false;
		float dist = 1;
		float minProcessDist = 0.1f;
		SawmillProcess p = null;
		if(state.sawmillProcessQueue.size() > 0)
		{
			p = state.sawmillProcessQueue.get(state.sawmillProcessQueue.size()-1);
			if(p!=null)
			{
				dist = p.getRelativeProcessStep(rawLevel);
				// either it's a different item or we have 3 together already
				if(!ItemStack.isSameItem(stack, p.getInput())||state.combinedLogs > 2)
				{
					if(!simulate)
						state.combinedLogs = 0;
					minProcessDist = 0.5f;
				}
			}
		}
		else if(state.combinedLogs > 0)
			state.combinedLogs = 0;

		if(p!=null&&dist < minProcessDist)
			return false;
		if(!simulate)
		{
			p = new SawmillProcess(stack.copyWithCount(1));
			state.sawmillProcessQueue.add(p);
			state.combinedLogs++;
		}
		stack.shrink(1);
		return true;
	}

