private static boolean isPartOfCompactingLoop(ItemStack firstCompacted, ItemStack firstCompactResult, Level w) {
		ItemStack compactingResultStack;
		int iterations = 0;
		Set<Integer> compactedItemHashes = new HashSet<>();
		Queue<ItemStack> itemsToCompact = new LinkedList<>();
		itemsToCompact.add(firstCompactResult);
		while (!itemsToCompact.isEmpty()) {
			ItemStack itemToCompact = itemsToCompact.poll();
			compactingResultStack = getCompactingResult(itemToCompact, w, 2, 2).getResult();
			if (!compactingResultStack.isEmpty()) {
				if (ItemStack.isSameItemSameComponents(compactingResultStack, firstCompacted)) {
					return true;
				} else if (compactedItemHashes.contains(ItemStack.hashItemAndComponents(compactingResultStack))) {
					return false; // loop exists but the first compacted item isn't part of it so we will let it be compacted, but no follow up compacting will
									// happen
				}
				itemsToCompact.add(compactingResultStack);
			}

			compactingResultStack = getCompactingResult(itemToCompact, w, 3, 3).getResult();
			if (!compactingResultStack.isEmpty()) {
				if (ItemStack.isSameItemSameComponents(compactingResultStack, firstCompacted)) {
					return true;
				} else if (compactedItemHashes.contains(ItemStack.hashItemAndComponents(compactingResultStack))) {
					return false; // loop exists but the first compacted item isn't part of it so we will let it be compacted, but no follow up compacting will
									// happen
				}
				itemsToCompact.add(compactingResultStack);
			}
			compactedItemHashes.add(ItemStack.hashItemAndComponents(itemToCompact));
			iterations++;
			if (iterations > MAX_FOLLOW_UP_COMPACTING_RECIPES) {
				return true; // we were unable to figure out if the loop exists because of way too many follow up compacting recipe thus not allowing to compact
								// anyway
			}
		}
		return false;
	}

private void tryProvideItems(AbstractLogisticsFrameEntity provider, AbstractLogisticsFrameEntity requester, PriorityQueue<LogisticsTask> tasks) {
        IOHelper.getInventoryForBlock(provider.getCachedTileEntity(), provider.getSide()).ifPresent(providerHandler -> {
            if (requester instanceof IProvidingInventoryListener prov) {
                prov.notify(new BlockEntityAndFace(provider.getCachedTileEntity(), provider.getSide()));
            }
            CountedItemStacks counted;
            int keepStock = 0;
            if (provider instanceof ISpecificProvider sp && sp.getKeepItemsStocked() > 0) {
                counted = new CountedItemStacks(providerHandler);
                keepStock = sp.getKeepItemsStocked();
            } else {
                counted = null;
            }

            for (int i = 0; i < providerHandler.getSlots(); i++) {
                ItemStack providedStack = providerHandler.extractItem(i, 64, true);
                if (!providedStack.isEmpty() && (!(provider instanceof ISpecificProvider sp) || sp.canProvide(providedStack))) {
                    int requested = getRequestedAmount(requester, providedStack, true);
                    if (requested > 0) {
                        if (counted != null) {
                            int remaining = counted.getInt(providedStack) - requested - keepStock;
                            if (remaining < 0) {
                                // reduce amount if needed so stock levels are honoured
                                requested += remaining;
                            }
                            counted.adjust(providedStack, -requested);
                        }
                        tasks.add(new LogisticsTask(provider, requester, providedStack.copyWithCount(requested)));
                        if (droneAccess) {
                            // a logistics drone just handles the first applicable task, so we can bail here
                            // - but logistics modules process all applicable tasks!
                            return;
                        }
                    }
                }
            }
        });
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (pressureTube.nonNullLevel().isClientSide || (pressureTube.nonNullLevel().getGameTime() & 0x7) != 0) return;

        getConnectedInventory().ifPresent(itemHandler -> {
            // times 8 because we only run every 8 ticks
            int advMul = pressureTube instanceof AdvancedPressureTubeBlockEntity ? 4 : 1;
            int transferLimit = 8 * PneumaticValues.CHARGING_STATION_CHARGE_RATE * (upgraded ? 10 : 1) * advMul;
            PNCCapabilities.getAirHandler(pressureTube).ifPresent(airHandler -> {
                for (int slot = 0; slot < itemHandler.getSlots(); slot++) {
                    ItemStack chargedItem = itemHandler.getStackInSlot(slot);
                    if (chargedItem.getCount() != 1) continue;
                    PNCCapabilities.getAirHandler(chargedItem).ifPresent(airHandlerItem -> {
                        float itemPressure = airHandlerItem.getPressure();
                        float modulePressure = airHandler.getPressure();
                        float delta = Math.abs(modulePressure - itemPressure) / 2.0F;
                        int airInItem = airHandlerItem.getAir();
                        if (itemPressure > modulePressure + 0.01F && itemPressure > 0F) {
                            // move air from item to charger (tube)
                            int airToMove = Math.min(Math.min(transferLimit, airInItem), (int) (delta * airHandler.getVolume()));
                            airHandlerItem.addAir(-airToMove);
                            airHandler.addAir(airToMove);
                        } else if (itemPressure < modulePressure - 0.01F && itemPressure < airHandlerItem.maxPressure()) {
                            // move air from charger (tube) to item
                            float itemVolume = airHandlerItem.getVolume();
                            int maxAirInItem = (int) (airHandlerItem.maxPressure() * itemVolume);
                            int airToMove = Math.min(Math.min(transferLimit, airHandler.getAir()), (int) (delta * itemVolume));
                            airToMove = Math.min(maxAirInItem - airInItem, airToMove);
                            airHandlerItem.addAir(airToMove);
                            airHandler.addAir(-airToMove);
                        }
                    });
                }
            });
        });
    }

public static Set<BlockPos> blocksInSquare(BlockPos center, Axis axis, int maxBlocks, int maxRange, Predicate<BlockPos> ignore) {
		Set<BlockPos> blocks = new HashSet<>();
		if (ignore.test(center)) return blocks;
		blocks.add(center);
		if (blocks.size() >= maxBlocks) return blocks;

		Queue<BlockPos> blockQueue = new LinkedList<>();
		blockQueue.add(center);

		while (!blockQueue.isEmpty()) {
			BlockPos pos = blockQueue.remove();

			for (EnumFacing facing : EnumFacing.VALUES) {
				if (facing.getAxis() == axis)
					continue;
				BlockPos shift = pos.offset(facing);
				if (shift.getX() - center.getX() > maxRange || center.getX() - shift.getX() > maxRange)
					continue;
				if (shift.getY() - center.getY() > maxRange || center.getY() - shift.getY() > maxRange)
					continue;
				if (shift.getZ() - center.getZ() > maxRange || center.getZ() - shift.getZ() > maxRange)
					continue;
				if (blocks.contains(shift))
					continue;
				if (ignore.test(shift))
					continue;
				blocks.add(shift);
				blockQueue.add(shift);
				if (blocks.size() >= maxBlocks)
					break;
			}

			if (blocks.size() >= maxBlocks)
				break;
		}

		return blocks;
	}

@Override
	protected void tick(ServerWorld level, E owner, long gameTime) {
		if (owner.isBlocking()) {
			blockTime++;

			LivingEntity target = owner.getLastHurtByMob();

			if (blockTime >= 5) {
				if (BrainUtil.isWithinMeleeAttackRange(owner, target)) {
					owner.swing(Hand.MAIN_HAND);
					owner.doHurtTarget(target);
					doStop(level, owner, gameTime);
				}
				else if (owner.isOnGround()) {
					Vector3d lungeVector = new Vector3d(target.getX() - owner.getX(), 0, target.getZ() - owner.getZ());

					if (lungeVector.lengthSqr() > 1.0E-7D)
						lungeVector = lungeVector.normalize().scale(0.4d);

					owner.setDeltaMovement(lungeVector.x(), 0.1f, lungeVector.z());
				}
			}

			return;
		}

		if (lastHitTime != owner.getLastHurtByMobTimestamp()) {
			lastHitTime = owner.getLastHurtByMobTimestamp();
			stunCount++;
		}

		if (stunCount > 2) {
			if (!(owner.getItemInHand(Hand.OFF_HAND).getItem() instanceof ShieldItem))
				owner.setItemInHand(Hand.OFF_HAND, new ItemStack(Items.SHIELD));

			owner.startUsingItem(Hand.OFF_HAND);
		}
	}

