@Override
	public void createKeybindListener(Consumer<AoAPlayerKeybindListener> consumer) {
		consumer.accept(new AoAPlayerKeybindListener() {
			@Override
			public AoAPlayerEventListener getEventListener() {
				return InnervationDodge.this;
			}

			@Override
			public KeyMapping getKeybind() {
				return AoAKeybinds.ABILITY_ACTION;
			}

			@Override
			public boolean shouldSendKeyPress() {
				Minecraft mc = Minecraft.getInstance();
				LocalPlayer player = mc.player;
				TickRateManager tickRateManager = mc.level.tickRateManager();
				float yRot = player.getViewYRot(mc.getTimer().getGameTimeDeltaPartialTick(!tickRateManager.isEntityFrozen(player)));

				if (player.input.leftImpulse == 0 || player.input.hasForwardImpulse() || player.level().getGameTime() <= InnervationDodge.this.activationTime + 5 || player.getAbilities().flying)
					return false;

				if (ClientPlayerDataManager.get().getResource(AoAResources.ENERGY.get()).hasAmount(InnervationDodge.this.energyCost)) {
					Vec3 movement = player.getDeltaMovement();
					double limit = player.onGround() ? 2.5d : 0.9d;
					double velocityX = Mth.clamp(movement.x() + (Mth.cos(yRot * ((float)Math.PI / 180F)) * player.input.leftImpulse), -limit, limit);
					double velocityZ = Mth.clamp(movement.z() + (Mth.sin(yRot * ((float)Math.PI / 180F)) * player.input.leftImpulse), -limit, limit);

					player.setDeltaMovement(new Vec3(velocityX, movement.y(), velocityZ));

					InnervationDodge.this.activationTime = player.level().getGameTime();
				}

				return true;
			}
		});
	}

@Override
	public void interceptRequestLast(CorporeaRequestMatcher request, int count, CorporeaSpark spark, CorporeaSpark source, List<ItemStack> stacks, Set<CorporeaNode> nodes, boolean doit) {
		List<ItemStack> filter = getFilter();

		boolean filterMatch = false;
		for (ItemStack stack : filter) {
			if (request.test(stack)) {
				filterMatch = true;
			}
		}

		if (filterMatch || filter.isEmpty()) {
			int missing = count;
			for (ItemStack stack : stacks) {
				missing -= stack.getCount();
			}

			if (missing > 0 && !getBlockState().getValue(BlockStateProperties.POWERED)) {
				BlockPos requestorPos = source.getSparkNode().getPos();

				List<CorporeaRetainerBlockEntity> retainers = new ArrayList<>();
				for (Direction dir : Direction.values()) {
					BlockEntity tile = level.getBlockEntity(worldPosition.relative(dir));
					if (tile instanceof CorporeaRetainerBlockEntity retainer) {
						retainers.add(retainer);
						retainer.forget();
					}
				}

				level.setBlockAndUpdate(getBlockPos(), getBlockState().setValue(BlockStateProperties.POWERED, true));
				level.scheduleTick(getBlockPos(), getBlockState().getBlock(), 2);

				for (CorporeaRetainerBlockEntity retainer : retainers) {
					retainer.remember(requestorPos, request, count, missing);
				}
			}
		}
	}

@Override
    protected void tick() {

        Level world = getWorld();
        if (world == null || getPos() == null) return;

        if (recipe == null) recipe = getRecipe();

        //update the mob list if not initialized
        if (mobs == null) mobs = getMobs(world);

        //every 60 ticks, spawn a mob. 1 tick = 1/20th of a second
        if (world.getGameTime() % 60 == 0 && !world.isClientSide) {

            //randomize the spawn position
            BlockPos summonPos = getPos().above().east(rand.nextInt(3) - rand.nextInt(6)).north(rand.nextInt(3) - rand.nextInt(6));

            Optional<? extends WeightedEntry> opt = mobs.getRandom(rand);
            opt.ifPresent(entry -> {
                if (entry instanceof MobSpawnSettings.SpawnerData spawnerData) {
                    Entity mob = spawnerData.type.create(world);
                    if (mob == null) return;
                    summon(mob, summonPos);
                    incrementProgress();
                }
            });

            recipe.ifPresentOrElse(recipe -> {
                if (getProgress() >= recipe.value().count) {
                    setFinished();
                }
            }, () -> {
                if (getProgress() >= 5) {
                    setFinished();
                }
            });
        }
    }

@SubscribeEvent
    public static void livingTick(EntityTickEvent.Pre event) {
        GuidingBoltManager manager = event.getEntity().level instanceof ServerLevel ? GuidingBoltManager.INSTANCE : GuidingBoltManager.CLIENT_INSTANCE;
//        if (MinecraftInstanceHelper.getPlayer() == event.getEntity() && event.getEntity().tickCount % 20 == 0) {
//            IronsSpellbooks.LOGGER.debug("\nGuiding Bolt Dump");
//            for (Map.Entry entry : GuidingBoltManager.INSTANCE.trackedEntities.entrySet()) {
//                IronsSpellbooks.LOGGER.debug("{}: {}", entry.getKey(), entry.getValue());
//            }
//        }
        if (manager.trackedEntities.isEmpty()) {
            return;
        }
        if (event.getEntity() instanceof LivingEntity livingEntity) {
            if (livingEntity.tickCount % manager.tickDelay == 0) {
                var projectiles = manager.trackedEntities.get(event.getEntity().getUUID());
                if (projectiles != null) {
                    if (livingEntity.isRemoved() || livingEntity.isDeadOrDying()) {
                        manager.stopTracking(livingEntity);
                        return;
                    }
                    List<Projectile> projectilesToRemove = new ArrayList<>();
                    for (Projectile projectile : projectiles) {
                        Vec3 motion = projectile.getDeltaMovement();
                        float speed = (float) motion.length();
                        Vec3 home = livingEntity.getBoundingBox().getCenter().subtract(projectile.position()).normalize().scale(speed * .55f * manager.tickDelay / 3f);
                        if (projectile.isRemoved() || home.dot(motion) < -0.75) {
                            //We have passed the entity
                            projectilesToRemove.add(projectile);
                            continue;
                        }
                        Vec3 newMotion = motion.add(home).normalize().scale(speed);
                        projectile.setDeltaMovement(newMotion);
                    }
                    projectiles.removeAll(projectilesToRemove);
                }
            }
        }
    }

private void fellTree(E entity, BlockPos treePos) {
        Level level = entity.level();
        BlockPos base = treePos;
        Queue<BlockPos> blocks = new ArrayDeque<>();
        Set<BlockPos> visited = new HashSet<>();
        blocks.add(base);

        while (!blocks.isEmpty()) {

            BlockPos pos = blocks.remove();
            if (!visited.add(pos)) {
                continue;
            }

            if (!NearestTreeSensor.isLog(level, pos)) {
                continue;
            }

            for (Direction facing : Plane.HORIZONTAL) {
                BlockPos pos2 = pos.relative(facing);
                if (!visited.contains(pos2)) {
                    blocks.add(pos2);
                }
            }

            for (int x = 0; x < 3; x++) {
                for (int z = 0; z < 3; z++) {
                    BlockPos pos2 = pos.offset(-1 + x, 1, -1 + z);
                    if (!visited.contains(pos2)) {
                        blocks.add(pos2);
                    }
                }
            }

            level.destroyBlock(pos, true);
        }

    }

@GameTest
	@EmptyTemplate
	@TestHolder(description = "Acknowledges a correlated recipe transfer when the server rejects it.")
	public static void acknowledgesRejectedRecipeTransfer(RecipeTransferTestHelper helper) {
		// Setup: correlate a transfer packet whose allowed-slot list contains an invalid id.
		ServerPlayer player = helper.getPlayer();
		CraftingMenu menu = helper.openMenu(CraftingMenu::new);
		Slot targetSlot = menu.getInputGridSlots().get(CRAFTING_GRID_TOP_LEFT);
		Slot sourceSlot = helper.getStandardInventorySlots(menu).get(0);
		sourceSlot.set(new ItemStack(Items.OAK_PLANKS));
		PacketRecipeTransferWithResult packet = new PacketRecipeTransferWithResult(
			List.of(new TransferOperation(sourceSlot.index, targetSlot.index)),
			List.of(targetSlot.index, menu.slots.size()),
			List.of(sourceSlot.index),
			false,
			true,
			43
		);
		var connection = new RecordingConnectionToClient();
		var context = new ServerPacketContext(player, SERVER_CONFIG, connection);

		// Operation: process the invalid transfer packet with its correlation id.
		encodeAndDecode(player, packet).process(context);

		// Assertions: the server rejects the transfer without moving items and acknowledges the matching id.
		helper.assertTrue(connection.result != null, "Expected a recipe transfer result packet");
		helper.assertEquals(43, connection.result.transferId, "Expected matching transfer id");
		helper.assertEquals(RecipeTransferResult.REJECTED, connection.result.result, "Expected rejected transfer result");
		helper.createMenuChecker(menu)
			.assertResults(
				RecipeTransferGameTests::getCraftingResultSlots,
				List.of()
			)
			.assertCraftingArea(CraftingMenu::getInputGridSlots, List.of())
			.assertPlayerInventory(List.of(stackAt(0, Items.OAK_PLANKS)))
			.assertAllSlotsChecked();
		helper.succeed();
	}

