public void tick() {
        super.tick();
        prevGroundProgress = groundProgress;
        prevBiteProgress = biteProgress;
        if (this.onGround() && groundProgress < 5.0F) {
            groundProgress++;
        }
        if (!this.onGround() && groundProgress > 0.0F) {
            groundProgress--;
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (biteProgress < 5F) {
                biteProgress++;
            }
        } else {
            if (biteProgress > 4 && this.getTarget() != null && this.distanceTo(this.getTarget()) < 1.3D) {
                this.getTarget().hurt(damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            }
            if (biteProgress > 0F) {
                biteProgress--;
            }
        }
        if (!level().isClientSide) {
            float delta = (float) this.getDeltaMovement().horizontalDistance();
            if (crawling || !this.isInWaterOrBubble()) {
                timeSwimming = 0;
                if(delta > 0.01F){
                    if(tickCount - lastStepSoundTimestamp > 10){
                        lastStepSoundTimestamp = tickCount;
                        this.playSound(ACSoundRegistry.TRILOCARIS_STEP.get(), 0.2F, 1.0F);
                    }

                }
            } else {
                timeSwimming++;
            }
        }
    }

@SubscribeEvent
    public void onPostGameOverlay(RenderGuiOverlayEvent.Post event) {
            if(renderStaticScreenFor > 0){
                if (Minecraft.getInstance().player.isAlive() && lastStaticTick != Minecraft.getInstance().level.getGameTime()) {
                    renderStaticScreenFor--;
                }
                float staticLevel = (renderStaticScreenFor / 60F);
                if (event.getOverlay().id().equals(VanillaGuiOverlay.HELMET.id())) {
                    float screenWidth = event.getWindow().getScreenWidth();
                    float screenHeight = event.getWindow().getScreenHeight();
                    RenderSystem.disableDepthTest();
                    RenderSystem.depthMask(false);

                    float ageInTicks = Minecraft.getInstance().level.getGameTime() + event.getPartialTick();
                    float staticIndexX = (float) Math.sin(ageInTicks * 0.2F) * 2;
                    float staticIndexY = (float) Math.cos(ageInTicks * 0.2F + 3F) * 2;
                    RenderSystem.defaultBlendFunc();
                    RenderSystem.setShader(GameRenderer::getPositionTexShader);
                    RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, staticLevel);
                    RenderSystem.setShaderTexture(0, AMRenderTypes.STATIC_TEXTURE);
                    Tesselator tesselator = Tesselator.getInstance();
                    BufferBuilder bufferbuilder = tesselator.getBuilder();
                    bufferbuilder.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);
                    float minU = 10 * staticIndexX * 0.125F;
                    float maxU = 10 * (0.5F + staticIndexX * 0.125F);
                    float minV = 10 * staticIndexY * 0.125F;
                    float maxV = 10 * (0.125F + staticIndexY * 0.125F);
                    bufferbuilder.vertex(0.0D, screenHeight, -190.0D).uv(minU, maxV).endVertex();
                    bufferbuilder.vertex(screenWidth, screenHeight, -190.0D).uv(maxU, maxV).endVertex();
                    bufferbuilder.vertex(screenWidth, 0.0D, -190.0D).uv(maxU, minV).endVertex();
                    bufferbuilder.vertex(0.0D, 0.0D, -190.0D).uv(minU, minV).endVertex();
                    tesselator.end();
                    RenderSystem.depthMask(true);
                    RenderSystem.enableDepthTest();
                    RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
                }
                lastStaticTick = Minecraft.getInstance().level.getGameTime();
        }
    }

private boolean shearBlocks(ItemStack stack, Level level, IPedestal pedestal, FakePlayer fakePlayer, BlockPos pos, int shearsRange) {
		if (!isShearingBlock) {
			if (blockQueue.isEmpty()) {
				updateQueue(stack, level, pos, shearsRange);
				if (blockQueue.isEmpty()) {
					return false;
				}
			}

			blockPosBeingSheared = blockQueue.remove();
			BlockState blockState = level.getBlockState(blockPosBeingSheared);
			if (isShearableBlock(stack, level, blockState)) {
				float hardness = blockState.getDestroySpeed(level, blockPosBeingSheared);
				float digSpeed = stack.getItem().getDestroySpeed(stack, blockState);

				pedestal.setActionCoolDown((int) ((hardness * 1.5f * 20f) / digSpeed));
				isShearingBlock = true;
			}
		} else {
			BlockState blockState = level.getBlockState(blockPosBeingSheared);
			if (stack.getItem().canAttackBlock(blockState, level, blockPosBeingSheared, fakePlayer)) {
				if (blockState.getBlock() instanceof BeehiveBlock) {
					shearBeehive(level, blockPosBeingSheared, blockState, stack);
				} else {
					if (level.removeBlock(blockPosBeingSheared, false)) {
						Block.dropResources(blockState, level, blockPosBeingSheared, null, fakePlayer, new ItemStack(Items.SHEARS));
						level.levelEvent(2001, blockPosBeingSheared, Block.getId(blockState));
						if (level instanceof ServerLevel serverLevel) {
							stack.hurtAndBreak(1, serverLevel, null, item -> {
							});
						}
					}
				}
			}

			isShearingBlock = false;
		}
		return true;
	}

public static boolean recall(LivingEntity livingEntity, ItemStack stack){
        if (hasRecall(stack) && stack.getTag() != null) {
            if (getDimension(stack.getTag()).isPresent() && getRecallBlockPos(stack.getTag()) != null) {
                BlockPos blockPos = getRecallBlockPos(stack.getTag());
                if (blockPos != null) {
                    if (getDimension(stack.getTag()).get() == livingEntity.level.dimension()) {
                        Optional<Vec3> optional = RespawnAnchorBlock.findStandUpPosition(EntityType.PLAYER, livingEntity.level, blockPos);
                        if (optional.isPresent()) {
                            net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity, optional.get().x, optional.get().y, optional.get().z);
                            if (event.isCanceled()) {
                                return false;
                            }
                            livingEntity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                            ModNetwork.INSTANCE.send(PacketDistributor.ALL.noArg(), new SPlayWorldSoundPacket(BlockPos.containing(livingEntity.xo, livingEntity.yo, livingEntity.zo), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                            ModNetwork.INSTANCE.send(PacketDistributor.ALL.noArg(), new SPlayWorldSoundPacket(BlockPos.containing(optional.get()), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                            return true;
                        }
                    } else {
                        if (livingEntity.getServer() != null) {
                            ServerLevel serverWorld = livingEntity.getServer().getLevel(getDimension(stack.getTag()).get());
                            if (serverWorld != null) {
                                Optional<Vec3> optional = RespawnAnchorBlock.findStandUpPosition(EntityType.PLAYER, serverWorld, blockPos);
                                if (optional.isPresent()) {
                                    net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity, optional.get().x, optional.get().y, optional.get().z);
                                    if (event.isCanceled()) {
                                        return false;
                                    }
                                    livingEntity.changeDimension(serverWorld, new ArcaTeleporter(optional.get()));
                                    livingEntity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

public void update(Level world, BlockPos darkAltarPos, DarkAltarBlockEntity tileEntity,
                       Player castingPlayer, ItemStack activationItem,
                       List<Ingredient> remainingAdditionalIngredients, int time, int totalTime) {
        if (tileEntity.getConvertEntity != null){
            MiscCapHelper.setShakeTime(tileEntity.getConvertEntity, 20);
            if (tileEntity.getConvertEntity.tickCount % 20 == 0) {
                if (world instanceof ServerLevel serverLevel){
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.ENCHANT, tileEntity.getConvertEntity);
                }
            }
        }

        if (tileEntity.getCurrentRitualRecipe() != null && tileEntity.getCurrentRitualRecipe().getCraftType() != null) {
            for (IRitualType ritualType : RitualType.getAllRitualType()) {
                if (tileEntity.getCurrentRitualRecipe().getCraftType().contains(ritualType.getName())) {
                    ritualType.onPerformRitual(world, darkAltarPos, tileEntity, castingPlayer, activationItem);
                }
            }
        }

        int progress = totalTime - time;

        if (world.getGameTime() % MathHelper.secondsToTicks(4) == 0 && MathHelper.secondsToTicks(4) > progress) {
            world.playSound(null, darkAltarPos, ModSounds.ALTAR_LOOP.get(), SoundSource.BLOCKS, 1.0F, world.getRandom().nextFloat() * 0.4F + 0.8F);
        }

        List<PedestalBlockEntity> pedestals = this.getPedestals(world, darkAltarPos);
        for (PedestalBlockEntity pedestal : pedestals) {
            pedestal.setLocked(5);
            pedestal.itemStackHandler.map(handler -> {
                ItemStack stack = handler.extractItem(0, 1, true);
                if (!stack.isEmpty()) {
                    addItemParticles((ServerLevel) world, pedestal.getBlockPos(), darkAltarPos, stack);
                }
                return true;
            });
        }

    }

public static boolean handleBlockBreak(ItemStack stack, BlockPos pos, Player player) {
    // TODO: offhand harvest reconsidering
    /* this is a really dumb hack.
    // Basically when something with silktouch harvests a block from the offhand
    // the game can't detect that. so we have to switch around the items in the hands for the break call
    // it's switched back in onBlockDestroyed
    if (DualToolHarvestUtil.shouldUseOffhand(player, pos, player.getHeldItemMainhand())) {
      ItemStack off = player.getHeldItemOffhand();

      this.switchItemsInHands(player);
      // remember, off is in the mainhand now
      CompoundNBT tag = off.getOrCreateTag();
      tag.putLong(TAG_SWITCHED_HAND_HAX, player.getEntityWorld().getGameTime());
      off.setTag(tag);
    }*/

    // client can run normal block breaking
    if (player.level().isClientSide || !(player instanceof ServerPlayer serverPlayer)) {
      return false;
    }

    // if broken, clear the item stack temporarily then break
    ToolStack tool = ToolStack.from(stack);
    Direction sideHit = BlockSideHitListener.getSideHit(player);
    ServerLevel world = serverPlayer.serverLevel();
    BlockState state = world.getBlockState(pos);
    if (tool.isBroken()) {
      // no harvest context
      player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
      ToolHarvestContext context = new ToolHarvestContext(world, serverPlayer, state, pos, sideHit,
        !player.isCreative() && state.canHarvestBlock(world, pos, player), false);
      breakBlock(tool, ItemStack.EMPTY, context, true);
      player.setItemInHand(InteractionHand.MAIN_HAND, stack);
    } else {
      // run standard breaking logic
      runBlockBreak(stack, tool, state, pos, sideHit, serverPlayer, null);
    }
    return true;
  }

public void handleTransferItems(ServerboundTransferItemsPacket packet, IPayloadContext context) {
            context.enqueueWork(() -> {
                AbstractContainerMenu menu = context.player().containerMenu;
                for (int i = packet.endslot(); i < menu.slots.size(); i++) {
                    for (int j = packet.startslot(); j < packet.endslot(); j++) {
                        int relative = j - packet.startslot();
                        Slot recipeSlot = menu.getSlot(j);
                        Slot invSlot = menu.getSlot(i);

                        if (recipeSlot.getItem().isEmpty()) {
                            continue;
                        }

                        if ((recipeSlot.getItem().isEmpty() && packet.stacks().get(relative).test(invSlot.getItem()))
                                || ItemStack.isSameItemSameComponents(invSlot.getItem(), recipeSlot.getItem())) {
                            if (packet.maxTransfer()) {
                                int toTransfer = invSlot.getItem().getMaxStackSize() - recipeSlot.getItem().getCount();
                                int actual = Math.min(invSlot.getItem().getCount(), toTransfer);

                                if (actual == 0) {
                                    break;
                                }

                                recipeSlot.set(invSlot.getItem().copyWithCount(actual +  recipeSlot.getItem().getCount()));
                                invSlot.getItem().shrink(actual);

                                if (actual == toTransfer) {
                                    break;
                                }
                            } else if (recipeSlot.getItem().isEmpty()) {
                                recipeSlot.set(invSlot.getItem().copyWithCount(1));
                                invSlot.getItem().shrink(1);
                                break;
                            }
                        }
                    }
                }
            });
        }

public static void tick(Level level, BlockPos pos, BlockState state, VaporStillBlockEntity blockEntity) {
        ItemStack fuelStack = blockEntity.brewingItemStacks.getFirst();
        if (blockEntity.fuel <= 0 && fuelStack.getItem() == Items.BLAZE_POWDER) {
            blockEntity.fuel = 20;
            fuelStack.shrink(1);
            blockEntity.setChanged();
        }

        // Periodically sync capabilities from the owning player if they are loaded
        if (blockEntity.ownerID != null && level.getGameTime() % CAPABILITY_UPDATE_INTERVAL == 0) {
            Player owner = level.getPlayerByUUID(blockEntity.ownerID);
            if (owner != null) {
                blockEntity.config.deriveFromHunter(HunterPlayer.get(owner));
                blockEntity.ownerName = owner.getName();
            }
        }

        var brewData  = blockEntity.canBrew();
        boolean canBrew = brewData != null;
        boolean isBrewing = blockEntity.brewTime > 0;

        if (isBrewing) {
            blockEntity.brewTime--;
            boolean ingredientsChanged = blockEntity.ingredientID != blockEntity.brewingItemStacks.get(2).getItem() || blockEntity.extraIngredientID != blockEntity.brewingItemStacks.get(1).getItem();
            if (blockEntity.brewTime == 0 && canBrew) {
                blockEntity.brewPotions();
                blockEntity.setChanged();
            } else if (!canBrew || ingredientsChanged) {
                blockEntity.brewTime = 0;
                blockEntity.setChanged();
            }
        } else if (canBrew && blockEntity.fuel > 0) {
            blockEntity.fuel--;
            blockEntity.brewTime = blockEntity.maxBrewTime = blockEntity.getMaxBrewTime() * (brewData.efficient() ? 2 : 1);
            blockEntity.ingredientID = blockEntity.brewingItemStacks.get(2).getItem();
            blockEntity.extraIngredientID = blockEntity.brewingItemStacks.get(1).getItem();
            blockEntity.setChanged();
        }
    }

private void handleAirLeak(BlockEntity ownerTE, Direction actualLeakDir) {
        Level world = Objects.requireNonNull(ownerTE.getLevel());
        BlockPos pos = ownerTE.getBlockPos();

        float pressure = getPressure();

        if (!world.isClientSide) {
            if ((world.getGameTime() & 0xf) == 0 && checkForCrossChunkLeak(ownerTE, pos, actualLeakDir)) {
                setSideLeaking(null);
                return;
            }

            if (getAir() > 0) {
                int leakedAmount = (int) (pressure * PneumaticValues.AIR_LEAK_FACTOR) + 20;
                if (leakedAmount > getAir()) leakedAmount = getAir();
                onAirDispersion(ownerTE, actualLeakDir, -leakedAmount);
                addAir(-leakedAmount);
            } else if (getAir() < 0) {
                int leakedAmount = -(int) (pressure * PneumaticValues.AIR_LEAK_FACTOR) + 20;
                if (getAir() > leakedAmount) leakedAmount = -getAir();
                onAirDispersion(ownerTE, actualLeakDir, leakedAmount);
                addAir(leakedAmount);
            }
        } else {
            double mx = actualLeakDir.getStepX();
            double my = actualLeakDir.getStepY();
            double mz = actualLeakDir.getStepZ();
            double speed = getPressure() * 0.1F;
            if (getAir() > 0) {
                if (pressure > 1f || pressure > 0.5f && world.random.nextBoolean() || world.random.nextInt(3) == 0) {
                    world.addParticle(AirParticleData.DENSE, pos.getX() + 0.5D + mx * 0.6, pos.getY() + 0.5D + my * 0.6, pos.getZ() + 0.5D + mz * 0.6,
                            mx * speed, my * speed, mz * speed);
                }
            } else if (getAir() < 0 && world.random.nextBoolean()) {
                world.addParticle(AirParticleData.DENSE, pos.getX() + 0.5D + mx, pos.getY() + 0.5D + my, pos.getZ() + 0.5D + mz, mx * speed, my * speed, mz * speed);
            }
            MovingSounds.playMovingSound(MovingSounds.Sound.AIR_LEAK, ownerTE.getBlockPos(), anyConnectableFace());
        }
    }

