		TextureAtlasSprite iicon = getBaseIcon(tEntity);
		ClientXplatAbstractions.instance().markSpriteActive(iicon);

		ms.pushPose();

		double time = (tEntity.level().getGameTime() % 24000) + partialTicks + new Random(tEntity.getId()).nextInt(200);
		float a = 0.1F + (tEntity.isInvisible() ? 0 : 1) * 0.8F;

		int alpha = (int) ((0.7 + 0.3 * (Math.sin(time / 5.0) + 0.5) * 2) * a * 255.0);
		int iconColor = 0xFFFFFF | (alpha << 24);

		float scale = 0.75F + 0.1F * (float) Math.sin(time / 10);
		ms.scale(scale, scale, scale);

		VertexConsumer buffer = buffers.getBuffer(RenderHelper.SPARK);
		ms.pushPose();
		ms.mulPose(entityRenderDispatcher.cameraOrientation());
		ms.mulPose(VecHelper.rotateY(180));
		renderIcon(ms, buffer, iicon, iconColor);

		ms.pushPose();
		ms.translate(-0.02 + Math.sin(time / 20) * 0.2, 0.24 + Math.cos(time / 20) * 0.2, 0.005);
		ms.scale(0.2F, 0.2F, 0.2F);
		int starColor = ColorHelper.getColorValue(tEntity.getNetwork()) | ((int) (a * 255.0F) << 24);
		renderIcon(ms, buffer, this.starSprite, starColor);
		ms.popPose();

		TextureAtlasSprite spinningIcon = getSpinningIcon(tEntity);
		if (spinningIcon != null) {
			ms.translate(-0.02 + Math.sin(time / 20) * -0.2, 0.24 + Math.cos(time / 20) * -0.2, 0.005);
			ms.scale(0.2F, 0.2F, 0.2F);
			renderIcon(ms, buffer, spinningIcon, iconColor);
		}
		ms.popPose();

		ms.popPose();
	}

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide) {
            for (int i = 0; i < progress / 20; i++) {
                level.addParticle(
                        GlowParticleData.createData(new ParticleColor(
                                50,
                                255,
                                20
                        )),
                        getBlockPos().getX() + 0.5 + ParticleUtil.inRange(-0.1, 0.1), getBlockPos().getY() + 1.3 + ParticleUtil.inRange(-0.1, 0.1), getBlockPos().getZ() + 0.5 + ParticleUtil.inRange(-0.1, 0.1),
                        0, 0, 0);
            }

        }
        if (!level.isClientSide) {
            if (ticksToNextEval > 0)
                ticksToNextEval--;
            if (ticksToNextEval <= 0)
                evaluateGrove();

            if (level.getGameTime() % 60 == 0 && progress >= Config.WHIRLISPRIG_MAX_PROGRESS.get() && SourceUtil.takeSourceMultipleWithParticles(worldPosition, level, 5, Config.WHIRLISPRIG_SOURCE_COST.get()) != null) {
                this.progress = 0;
                DropDistribution<BlockState> blockDropDistribution = new DropDistribution<>(genTable);
                int numDrops = getDropsByDiversity() + 3;
                for (int i = 0; i < numDrops; i++) {
                    BlockState block = blockDropDistribution.nextDrop();
                    if (block == null)
                        return;

                    for (ItemStack s : getDrops(blockDropDistribution)) {
                        BlockUtil.insertItemAdjacent(level, worldPosition, s);
                    }
                }
                updateBlock();
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide || level.getGameTime() % 20 != 0)
            return;
        LivingEntity owner = getOwner();
        if (!(owner instanceof Player player))
            return;
        FilterableItemHandler filterableItemHandler = new FilterableItemHandler(new PlayerMainInvWrapper(player.inventory), new ArrayList<>());
        InventoryManager manager = new InventoryManager(new ArrayList<>() {{
            add(filterableItemHandler);
        }});
        for (Entity entity : level.getEntities(owner, new AABB(owner.getOnPos()).inflate(5.0))) {
            if (entity instanceof ItemEntity i) {
                ItemStack stack = i.getItem();
                if (stack.isEmpty() || i.hasPickUpDelay()
                        || i.getPersistentData().getBoolean("PreventRemoteMovement")
                        || !i.isAlive()) {
                    continue;
                }
                var prePickup = NeoForge.EVENT_BUS.post(new ItemEntityPickupEvent.Pre(player, i));
                if (prePickup.canPickup().isFalse()
                        || getOwnerID().equals(i.getOwner()))
                    continue;
                stack = manager.insertStack(stack);
                i.setItem(stack);
            }
            if (entity instanceof ExperienceOrb orb) {
                if (orb.isRemoved()) {
                    continue;
                }
                var pickupEvent = NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.entity.player.PlayerXpEvent.PickupXp(player, orb));
                if (pickupEvent.isCanceled())
                    continue;
                player.giveExperiencePoints(orb.value);
                orb.remove(Entity.RemovalReason.DISCARDED);
            }
        }
    }

@Override
    public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        if (this.getOwner() == pPlayer) {

            if (itemstack.is(Items.GOLDEN_APPLE)) {
                long time = this.hasIesniumUpgrade() ? -1 : this.getSinTime() + SIN_INTERVAL - this.level().getGameTime();
                if (!this.hasBlacksmithUpgrade()) {
                    if (pPlayer.level().isClientSide())
                        pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.devil.no_upgrade"));
                } else if (time < 0) {
                    this.setSinTime(this.level().getGameTime());
                    itemstack.shrink(1);
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.ENCHANTED_GOLDEN_APPLE));
                } else if (pPlayer.level().isClientSide()) {
                    pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.devil.sin_on_cooldown", time));
                }
                //even if we don't give a breath we return success, otherwise we make the familiar change sitting position
                return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
            }
            if (itemstack.is(OccultismItems.PITAYA_GOLDEN)) {
                long time = this.hasIesniumUpgrade() ? -1 : this.getSinTime() + SIN_INTERVAL - this.level().getGameTime();
                if (!this.hasBlacksmithUpgrade()) {
                    if (pPlayer.level().isClientSide())
                        pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.devil.no_upgrade"));
                } else if (time < 0) {
                    this.setSinTime(this.level().getGameTime());
                    itemstack.shrink(1);
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(OccultismItems.PITAYA_ENCHANTED.get()));
                } else if (pPlayer.level().isClientSide()) {
                    pPlayer.sendSystemMessage(Component.translatable("dialog.occultism.devil.sin_on_cooldown", time));
                }
                //even if we don't give a breath we return success, otherwise we make the familiar change sitting position
                return this.level().isClientSide() ? InteractionResult.SUCCESS : InteractionResult.SUCCESS_SERVER;
            }

        }
        return super.mobInteract(pPlayer, pHand);
    }

@Override
        public void tick() {
            // Every configured interval, see if we need to adjust muffling
            Level level = Minecraft.getInstance().level;
            if (level == null) {
                stop();
                return;
            }
            if (!MekanismUtils.isTickingNormally(level)) {
                //Mute it similar to how the minecart sound handling is
                volume = 0;
            } else if (level.getGameTime() % checkInterval == 0) {
                if (!isClientPlayerInRange(this)) {
                    //If the player is not in range of hearing this sound anymore; go ahead and shutdown
                    stop();
                    return;
                }
                // Run the event bus with the original sound. Note that we must make sure to set the GLOBAL/STATIC
                // flag that ensures we don't wrap already muffled sounds. This is...NOT ideal and makes some
                // significant (hopefully well-informed) assumptions about locking/ordering of all these calls.
                IN_MUFFLED_CHECK = true;
                //Make sure we set our volume back to what it actually would be for purposes of letting other mods know
                // what volume to use
                volume = originalVolume;
                SoundInstance s = soundEngine == null ? null : ClientHooks.playSound(soundEngine, this);
                IN_MUFFLED_CHECK = false;

                if (s == this) {
                    // No filtering done, use the original sound's volume
                    volume = originalVolume * getTileVolumeFactor();
                } else if (s == null) {
                    // Full on mute; go ahead and shutdown
                    stop();
                } else {
                    // Altered sound returned; adjust volume
                    volume = s.getVolume() * getTileVolumeFactor();
                }
            }
        }

@Override
    protected boolean onUpdateServer(ServerLevel level) {
        boolean sendUpdatePacket = super.onUpdateServer(level);
        long gameTime = level.getGameTime();
        if (gameTime > lastProcessTick) {
            //If we are not on the same tick do stuff, otherwise ignore it (anti tick accelerator protection)
            lastProcessTick = gameTime;
            if (!chemicalTank.isEmpty()) {
                ChemicalResource chemicalType = chemicalTank.resource();
                int decayAmount = MekanismConfig.general.radioactiveWasteBarrelDecayAmount.get();
                if (decayAmount > 0 && !chemicalType.is(MekanismAPITags.Chemicals.WASTE_BARREL_DECAY_BLACKLIST) &&
                    ++processTicks >= MekanismConfig.general.radioactiveWasteBarrelProcessTicks.get()) {
                    processTicks = 0;
                    try (Transaction transaction = Transaction.openRoot()) {
                        chemicalTank.extract(chemicalType, decayAmount, transaction, AutomationType.INTERNAL);
                        transaction.commit();
                    }
                }
            }
            if (getActive()) {
                if (belowTankCache == null) {
                    belowTankCache = new BelowContainerCache<>(Capabilities.CHEMICAL, level, worldPosition);
                }
                int toEmit = chemicalTank.amountAsInt();
                IChemicalTank below = belowTankCache.getContainer(StackedWasteBarrel.class);
                if (below != null) {
                    //If the block below this barrel, is also a barrel. Only emit as much as it might be able to accept.
                    // This prevents it then trying to go up the chain back to this barrel and any ones above it
                    toEmit = Math.min(below.getNeededAsInt(ChemicalResource.EMPTY), toEmit);
                }
                ResourceUtils.emit(belowTankCache.getHandler(), chemicalTank, toEmit, null);
            }
            //Note: We don't need to do any checking here if the packet needs due to capacity changing as we do it
            // in TileentityMekanism after this method is called. And given radioactive waste barrels can only contain
            // radioactive substances the check for radiation scale also will work for syncing capacity for purposes
            // of when the client sneak right-clicks on the barrel
        }
        return sendUpdatePacket;
    }

@Test
	public void listenerFailuresAreIsolated() {
		List<String> events = new ArrayList<>();
		AtomicReference<@Nullable IRecipeTransferContext<?, ?>> contextReference = new AtomicReference<>();
		IRecipeTransferListener brokenListener = new IRecipeTransferListener() {
			@Override
			public void beforeRecipeTransfer(IRecipeTransferContext<?, ?> context) {
				throw new IllegalStateException("before failed");
			}

			@Override
			public void afterRecipeTransfer(IRecipeTransferContext<?, ?> context, RecipeTransferResult result) {
				assertSame(contextReference.get(), context);
				throw new IllegalStateException("after failed");
			}
		};
		IRecipeTransferListener recordingListener = new IRecipeTransferListener() {
			@Override
			public void beforeRecipeTransfer(IRecipeTransferContext<?, ?> context) {
				assertSame(contextReference.get(), context);
				events.add("before");
			}

			@Override
			public void afterRecipeTransfer(IRecipeTransferContext<?, ?> context, RecipeTransferResult result) {
				assertSame(contextReference.get(), context);
				events.add("after:" + result);
			}
		};
		var lifecycleManager = new RecipeTransferLifecycleManager(List.of(brokenListener, recordingListener));
		var context = new TestRecipeTransferContext(lifecycleManager);
		contextReference.set(context);

		lifecycleManager.beforeRecipeTransfer(context);
		PacketRecipeTransferResult.registerPendingRecipeTransfer(context);
		new PacketRecipeTransferResult(TRANSFER_ID, true).completePendingRecipeTransfer();

		assertEquals(List.of("before", "after:SUCCESS"), events);
	}

static void doAfterGridInit(ServerLevel level, List<BlockPos> positions, boolean waitForActive,
            BiConsumer<IGrid, IGridNode> consumer) {
        Runnable delayedAction = new Runnable() {
            private int attempts = 240;

            @Override
            public void run() {
                // Check if there's a grid node there
                List<IGridNode> gridNodes = new ArrayList<>();

                for (var position : positions) {
                    var be = level.getBlockEntity(position);
                    if (be instanceof IGridConnectedBlockEntity host) {
                        gridNodes.add(host.getMainNode().getNode());
                    } else if (be instanceof CableBusBlockEntity cableBus) {
                        var centerPart = cableBus.getCableBus().getPart(null);
                        if (centerPart != null) {
                            gridNodes.add(centerPart.getGridNode());
                        } else {
                            return; // Stop -> not eligible
                        }
                    } else {
                        return; // Stop -> not eligible
                    }
                }

                if (gridNodes.stream().anyMatch(Objects::isNull)
                        || waitForActive && !gridNodes.stream().allMatch(IGridNode::isActive)) {
                    if (--attempts > 0) {
                        TickHandler.instance().addCallable(level, this);
                    } else {
                        throw new IllegalStateException("Couldn't access grid nodes @ " + positions);
                    }
                } else {
                    consumer.accept(gridNodes.getFirst().getGrid(), gridNodes.getFirst());
                }
            }
        };
        TickHandler.instance().addCallable(level, delayedAction);
    }

