private ArrayList<TorchPos> bfs(Level world, Queue<BlockPos> queue, HashMap<BlockPos, Integer> distances, int maxPoppedDist, int maxPushedDist, int playerElevation) {
    ArrayList<TorchPos> validTorchPositions = new ArrayList<>();
    while (!queue.isEmpty()) {
      final BlockPos poppedPos = queue.peek();
      final int poppedDistance = distances.get(poppedPos);
      if (poppedDistance > maxPoppedDist) {
        break;
      }
      queue.remove();
      // Enumerate all successors while keeping track whether a torch can be placed here.
      boolean isValidTorch = false;
      boolean wouldUpdateFloatingFallingBlock = false;
      EnumSet<Direction> solidDirections = EnumSet.noneOf(Direction.class);
      for (Direction direction : Direction.values()) {
        final BlockPos nextPos = poppedPos.relative(direction);
        final BlockState state = world.getBlockState(nextPos);
        if (state.canOcclude()) {
          solidDirections.add(direction);
          if (direction != Direction.UP) {
            isValidTorch = true;
          }
        }
        else if (poppedDistance < maxPushedDist && !distances.containsKey(nextPos)) {
          distances.put(nextPos, poppedDistance + 1);
          queue.add(nextPos);
        }
        // Check if placing a torch here would cause a floating block to fall.
        // Placing a torch BELOW a floating block is okay, though.
        if (direction != Direction.UP && state.getBlock() instanceof FallingBlock &&
            FallingBlock.isFree(world.getBlockState(nextPos.below()))) {
          wouldUpdateFloatingFallingBlock = true;
        }
      }
      if (isValidTorch && !wouldUpdateFloatingFallingBlock && world.isEmptyBlock(poppedPos)) {
        validTorchPositions.add(new TorchPos(poppedPos, poppedPos.getY() - playerElevation,
            TORCH_LIGHT_LEVEL - poppedDistance, world.getMaxLocalRawBrightness(poppedPos), solidDirections));
      }
    }
    return validTorchPositions;
  }

private void renderMaskSubPass() {
        boolean anyMask = false;
        for (var entry : particles.entrySet()) {
            if (!entry.getValue().isEmpty() && entry.getKey().renderer.isWriteCustomMask()) {
                anyMask = true;
                break;
            }
        }
        if (!anyMask) return;
        // demand-driven: flagged emitters cost nothing unless some pending effect this frame
        // actually reads the mask (MaskFilter request / Custom Mask input / the editor mask view)
        if (!PostEffectStack.currentSink().hasPendingMaskConsumer()) return;
        // clear() rebinds with a full-target viewport — preserve the current one (the editor
        // scene renders in a sub-viewport and the mask must stay pixel-aligned with it)
        int viewportX = GlStateManager.Viewport.x();
        int viewportY = GlStateManager.Viewport.y();
        int viewportWidth = GlStateManager.Viewport.width();
        int viewportHeight = GlStateManager.Viewport.height();
        if (MASK_TARGET == null) {
            MASK_TARGET = new FormatTarget(
                    DRAW_TARGET.width, DRAW_TARGET.height, GL11.GL_LINEAR,
                    TargetFormat.R8, true);
        } else if (MASK_TARGET.width != DRAW_TARGET.width || MASK_TARGET.height != DRAW_TARGET.height) {
            MASK_TARGET.resize(DRAW_TARGET.width, DRAW_TARGET.height, Minecraft.ON_OSX);
        }
        MASK_TARGET.setClearColor(0f, 0f, 0f, 0f);
        MASK_TARGET.clear(Minecraft.ON_OSX);
        // Whatever depth the FX themselves were clipped against — the live scene depth in place, the
        // opaque-only snapshot on the late path — so the mask lines up with what is on screen instead
        // of being cut by a water surface the effect is allowed to draw through.
        MASK_TARGET.copyDepthFrom(DRAW_TARGET);
        MASK_TARGET.bindWrite(false);
        RenderSystem.viewport(viewportX, viewportY, viewportWidth, viewportHeight);
        maskSubPass = true;
        renderQueuedPasses();
        maskSubPass = false;
        maskColorTexture = MASK_TARGET.getColorTextureId();
        maskDepthTexture = MASK_TARGET.getDepthTextureId();
        DRAW_TARGET.bindWrite(false);
    }

@Override
    public void render(HolosphereBlockEntity entity, float partialTicks, PoseStack matrixStack, MultiBufferSource buffer, int combinedLight,
            int combinedOverlay) {
        long timestamp = entity.getScanModeTimestamp();
        Level level = entity.getLevel();
        if (timestamp == 0 || timestamp < 0 && level.getGameTime() + timestamp > 20) {
            return;
        }
//        VertexConsumer builder = buffer.getBuffer(RenderType.solid());
        BlockPos pos = entity.getBlockPos();
        ChunkPos chunkPos = new ChunkPos(pos);

        matrixStack.pushPose();

//        matrixStack.mulPose(Vector3f.XN.rotationDegrees(90));
        matrixStack.translate(0.5, 1, 0.5);
//        drawLabel("test", matrixStack, buffer, combinedLight);
        matrixStack.popPose();

        int light = this.getLightColor(entity.getLevel(), entity.getBlockPos());

        double angle = RotationHelper.getHorizontalAngle(Minecraft.getInstance().getCameraEntity().getEyePosition(partialTicks),
                Vec3.atCenterOf(entity.getBlockPos()));
        Quaternionf rotation = new Quaternionf(0.0F, 0.0F, 0.0F, 1.0F);
        rotation.mul(Axis.YP.rotationDegrees((float) (angle / Math.PI * 180)));

        VertexConsumer vertexBuilder = material.buffer(buffer, RenderType::entityTranslucent);

        renderBackdrop(vertexBuilder, matrixStack, rotation, light, level.getGameTime() + partialTicks, timestamp);

        entity.getScanResults().stream()
                .filter(scan -> scan.timestamp() <= level.getGameTime())
                .forEach(scan -> {
                    int x = scan.chunkX() - chunkPos.x;
                    int z = scan.chunkZ() - chunkPos.z;
                    long openTimestamp = timestamp + (Math.abs(x) + Math.abs(z));
                    renderMarker(vertexBuilder, matrixStack, material.sprite(), rotation, level.getGameTime() + partialTicks, openTimestamp,
                            light, 0.5f + x * 1 / 16f, 0, 0.5f + z * 1 / 16f, scan);
                });
    }

private static int endDynamic(CommandSourceStack source, String templateName) {
		DynamicTemplate template = DYNAMIC_CACHE.getIfPresent(templateName);
		if (template == null) {
			source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.dynamic.templateNotInUse", templateName));
			return 1;
		}

		IBackpackWrapper wrapper = BackpackWrapper.fromStack(template.backpack);

		List<ItemStack> remainings = new ArrayList<>();
		remainings.addAll(InventoryHelper.insertIntoInventory(template.itemsForInventoryHandler, wrapper.getInventoryHandler(), false));
		remainings.addAll(InventoryHelper.insertIntoInventory(template.itemsForUpgradeHandler, wrapper.getUpgradeHandler(), false));
		if (!remainings.isEmpty()) {
			// List all items that could not be added
			for (ItemStack remaining : remainings) {
				source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.dynamic.end.addRemainingItemsFailed", remaining.getCount(),
						remaining.getDisplayName()));
			}
		}

		// Check if backpack wrapper is empty
		Optional<UUID> backpackUuid = wrapper.getContentsUuid();
		if (backpackUuid.isEmpty() || (InventoryHelper.isEmpty(wrapper.getInventoryHandler()) && InventoryHelper.isEmpty(wrapper.getUpgradeHandler()))) {
			source.sendFailure(Component.translatable("commands.sophisticatedbackpacks.template.backpackempty"));
			return 3;
		}

		// Spawn backpack
		if (source.isPlayer()) {
			giveBackpackToPlayer(template.backpack(), source.getPlayer());
		} else if (source.getEntity() != null) {
			dropBackpackToPosition(template.backpack(), source.getLevel(), source.getEntity().position());
		} else {
			dropBackpackToPosition(template.backpack(), source.getLevel(), source.getPosition());
		}

		DYNAMIC_CACHE.invalidate(templateName);
		source.sendSuccess(() -> Component.translatable("commands.sophisticatedbackpacks.dynamic.end.success", templateName), false);
		return 0;
	}

@Override
	public CompoundTag save(CompoundTag tag, HolderLookup.Provider registries) {
		ListTag groupsTag = new ListTag();
		for (LinkedStorageGroupRecord group : groups.values()) {
			CompoundTag groupTag = new CompoundTag();
			groupTag.putUUID(ID_TAG, group.id());
			groupTag.putLong(REVISION_TAG, group.revision());
			groupTag.putLong(RENDER_REVISION_TAG, group.renderRevision());
			groupTag.putInt(COLUMNS_TAKEN_TAG, group.columnsTaken());
			groupTag.putUUID(OWNER_ID_TAG, group.ownerId());
			groupTag.putUUID(PRIMARY_ENDPOINT_ID_TAG, group.primaryEndpointId());
			ListTag endpointsTag = new ListTag();
			for (LinkedStorageEndpointRecord endpoint : group.endpoints()) {
				CompoundTag endpointTag = new CompoundTag();
				endpointTag.putUUID(ID_TAG, endpoint.endpointId());
				if (endpoint.lastOpenedBy() != null) {
					endpointTag.putUUID(LAST_OPENED_BY_TAG, endpoint.lastOpenedBy());
				}
				endpointTag.putLong(LAST_OPENED_AT_TAG, endpoint.lastOpenedAt());
				endpointsTag.add(endpointTag);
			}
			groupTag.put(ENDPOINTS_TAG, endpointsTag);
			groupTag.putString(FACTORY_ID_TAG, group.hostDescriptor().factoryId().toString());
			groupTag.put(VIRTUAL_CARRIER_TAG, group.hostDescriptor().virtualCarrier());
			groupTag.put(CONTENTS_TAG, group.contents().copy());
			groupsTag.add(groupTag);
		}
		tag.put(GROUPS_TAG, groupsTag);
		ListTag claimsTag = new ListTag();
		for (ActivePendingCraftClaim claim : activePendingClaims.values()) {
			CompoundTag claimTag = new CompoundTag();
			claimTag.putUUID(CLAIM_ID_TAG, claim.claimId());
			claimTag.putUUID(GROUP_ID_TAG, claim.groupId());
			claimTag.putUUID(ENDPOINT_ID_TAG, claim.endpointId());
			claimTag.putString(PLAN_KIND_TAG, claim.plan().getSerializedName());
			claimsTag.add(claimTag);
		}
		tag.put(ACTIVE_PENDING_CLAIMS_TAG, claimsTag);
		return tag;
	}

@Override
	public void tick(@Nullable Entity entity, Level level, BlockPos pos) {
		if (level.isClientSide() || nextCheckTime > level.getGameTime()) {
			return;
		}

		if (remainingApplyTime > 0) {
			remainingApplyTime--;
			if (remainingApplyTime <= 0) {
				if (defBeingApplied.hasItemUseEffects()) {
					triggerItemUseEffects(level);
				}
				applying = false;
				ItemStack remainingStack = defBeingApplied.finishUsing.apply(stackBeingAplied, applyingToEntity);
				stackBeingAplied = ItemStack.EMPTY;
				applyingToEntity = null;
				defBeingApplied = null;
				storageWrapper.getInventoryForUpgradeProcessing().insertItem(remainingStack, false);
				nextCheckTime = level.getGameTime() + CHECK_INTERVAL;
			} else if (shouldTriggerItemUseEffects()) {
				triggerItemUseEffects(level);
			}
			return;
		}

		if (entity instanceof LivingEntity livingEntity) {
			applyTo(livingEntity);
		} else {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, new AABB(pos).inflate(CHECK_RADIUS), this::entityMatches);
			for (LivingEntity livingEntity : entities) {
				applyTo(livingEntity);
				if (applying) {
					break;
				}
			}
		}
		if (!applying) {
			nextCheckTime = level.getGameTime() + CHECK_INTERVAL;
		}
	}

@Override
    public void tick() {
        super.tick();
        if (this.cropPos.isPresent()) {
            BlockPos blockpos = this.cropPos.get();
            if (blockpos.closerToCenterThan(this.servant.position(), 2.0D)){
                if (this.servant.level.getGameTime() >= this.nextWorkCycleTime) {
                    ItemStack itemstack = ItemStack.EMPTY;
                    SimpleContainer simplecontainer = this.servant.getInventory();
                    int i = simplecontainer.getContainerSize();

                    for (int j = 0; j < i; ++j) {
                        ItemStack itemstack1 = simplecontainer.getItem(j);
                        if (itemstack1.is(Items.BONE_MEAL)) {
                            itemstack = itemstack1;
                            break;
                        }
                    }

                    if (!itemstack.isEmpty() && BoneMealItem.growCrop(itemstack, this.servant.level, blockpos)) {
                        this.servant.level.levelEvent(1505, blockpos, 0);
                        itemstack.shrink(1);
                        if (this.servant.getMainHandItem().is(Items.BONE_MEAL)) {
                            this.servant.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                        } else if (this.servant.getOffhandItem().is(Items.BONE_MEAL)){
                            this.servant.setItemSlot(EquipmentSlot.OFFHAND, ItemStack.EMPTY);
                        }
                        this.cropPos = this.pickNextTarget(this.servant.level, this.servant);
                        this.setCurrentCropAsTarget(this.servant);
                        this.nextWorkCycleTime = this.servant.level.getGameTime() + 40L;
                    }

                    ++this.timeWorkedSoFar;
                }
            } else {
                this.servant.getLookControl().setLookAt(blockpos.getCenter());
                this.servant.getNavigation().moveTo(blockpos.getCenter().x(), blockpos.getCenter().y(), blockpos.getCenter().z(), 1.0F);
            }
        }
    }

