@Override
    protected void checkAndPerformAttack(LivingEntity enemy, boolean inRange) {
        long currentTime = mob.level.getGameTime();
        if (attackType == GRAB) {
            for (Entity passenger : mob.getPassengers()) {
                if (passenger instanceof LivingEntity && passenger != mob.getRidingPlayer()) {
                    if (mob.tickCount % 20 == 0) {
                        boolean hurt = passenger.hurt(DamageSource.mobAttack(mob), (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        if (!hurt || (currentTime >= grabStartTick + GRAB_DURATION && mob.getRandom().nextInt(5) == 0)) {
                            attackEndTick = currentTime + 20;
                            mob.stopGrabAttack(passenger);
                        }
                    }
                }
            }
        } else if (attackType == ATTACK) {
            if (inRange && attackDamageTick > 0 && currentTime >= attackDamageTick) {
                mob.attackTarget(enemy);
                mob.destroyBoat(enemy);
                attackDamageTick = -1;
                attackType = -1;
            }
        } else if (currentTime > attackEndTick + 20 && inRange) {
            //Is target smaller than 1 block (if prehistoric is adult)
            boolean tooBig = !Util.isEntitySmallerThan(enemy, mob.grabTargetSize());
            if (tooBig || mob.getRandom().nextInt(5) > 0 || mob.getVehicle() == enemy) {
                attackType = ATTACK;
                ServerAnimationInfo animationInfo = mob.startAttack();
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength);
                attackDamageTick = Math.min((long) (currentTime + animationInfo.actionDelay), attackEndTick);
            } else {
                attackType = GRAB;
                mob.destroyBoat(enemy);
                mob.startGrabAttack(enemy);
                //TODO: Grab attack needs to be delayed and probably only start when looking at player?
                attackEndTick = 1;
                grabStartTick = currentTime;
            }
        }
    }

@Override
    public void render(PressureChamberValveBlockEntity te, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        if (te.multiBlockSize == 0 || !te.hasGlass) return;

        List<ItemStack> stacks = te.renderedItems;
        if (!stacks.isEmpty()){
            double x = te.multiBlockX - te.getBlockPos().getX() + te.multiBlockSize / 2D;
            double y = te.multiBlockY - te.getBlockPos().getY() + 1.1; // Set to '+ 1' for normal y value.
            double z = te.multiBlockZ - te.getBlockPos().getZ() + te.multiBlockSize / 2D;

            int light = ClientUtils.getLightAt(new BlockPos(te.multiBlockX + te.multiBlockSize / 2, te.multiBlockY + 1, te.multiBlockZ + te.multiBlockSize / 2));
            matrixStackIn.pushPose();
            matrixStackIn.translate(x, y, z);

            // render single item centered (looks best), multiple items arranged in a circle
            // around the centre of the chamber, radius dependent on chamber size
            float circleRadius = stacks.size() == 1 ? 0 : 0.33f * (te.multiBlockSize - 2);
            float degreesPerStack = 360f / stacks.size();

            // some gentle rotation and bobbing looks good here
            double ticks = te.nonNullLevel().getGameTime() + partialTicks;
            float yBob = Mth.sin(((float) ticks  / 10) % 360) * 0.01f;
            float yRot = (float) (ticks / 2) % 360;

            for (int i = 0; i < stacks.size(); i++) {
                matrixStackIn.pushPose();
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(i * degreesPerStack));
                matrixStackIn.translate(circleRadius, yBob + 0.2, 0);
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(yRot));
                matrixStackIn.scale(0.5f, 0.5f, 0.5f);

                ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
                BakedModel bakedModel = itemRenderer.getModel(stacks.get(i), te.getLevel(), null, 0);
                itemRenderer.render(stacks.get(i), ItemDisplayContext.FIXED, true, matrixStackIn, bufferIn, light, combinedOverlayIn, bakedModel);

                matrixStackIn.popPose();
            }
            matrixStackIn.popPose();
        }
    }

public static IHackableBlock getHackableForBlock(Level blockGetter, BlockPos pos, Player player) {
        BlockState state = blockGetter.getBlockState(pos);
        Block block = state.getBlock();
        HackManager manager = getInstance(player.level());
        MinecraftServer server = blockGetter.getServer();

        if (player.level().getGameTime() - 60 > manager.lastBlockPrune) {
            // clean up the tracked blocks map
            manager.hackableBlocks.entrySet().removeIf(
                    entry -> {
                        Block trackedBlock = entry.getValue().getLeft();
                        IHackableBlock hackableBlock = entry.getValue().getRight();
                        if (server == null && !blockGetter.dimension().equals(entry.getKey().dimension())) {
                            return false;  // on the client: we can only try to clean up entries for this dimension
                        }
                        Level level = server == null ? blockGetter : server.getLevel(entry.getKey().dimension());
                        return block != trackedBlock || level == null ||
                                !hackableBlock.canHack(level, entry.getKey().pos(), state, player)
                                        && !isInDisplayCooldown(hackableBlock, level, entry.getKey().pos(), player);
                    }
            );
            manager.lastBlockPrune = player.level().getGameTime();
        }

        if (block instanceof IHackableBlock h && h.canHack(blockGetter, pos, state, player))
            return h;

        GlobalPos gpos = GlobalPos.of(blockGetter.dimension(), pos);
        Pair<Block,IHackableBlock> pair = manager.hackableBlocks.get(gpos);
        if (pair == null) {
            IHackableBlock hackable = CommonArmorRegistry.getInstance().getHackable(block);
            if (hackable != null && hackable.canHack(blockGetter, pos, state, player)) {
                pair = Pair.of(block, hackable);
                manager.hackableBlocks.put(gpos, pair);
            } else {
                return null;
            }
        }
        return pair.getRight();
    }

public static void commonTick(Level level, BlockPos worldPosition, BlockState state, HoveringHourglassBlockEntity self) {
		int totalTime = self.getTotalTime();
		boolean dust = self.isDust();

		if (totalTime > 0 || dust) {
			if (self.move && !dust) {
				self.time++;
			}

			if (self.time >= totalTime) {
				self.time = 0;
				self.flip = !self.flip;
				self.flipTicks = 4;
				if (!level.isClientSide) {
					level.setBlock(worldPosition, state.setValue(BlockStateProperties.POWERED, true), Block.UPDATE_NEIGHBORS);
					level.scheduleTick(worldPosition, state.getBlock(), 4);
				}

				for (Direction facing : Direction.values()) {
					BlockPos pos = worldPosition.relative(facing);
					var trigger = XplatAbstractions.INSTANCE.findHourglassTrigger(level, pos,
							level.getBlockState(pos), level.getBlockEntity(pos));
					if (trigger != null) {
						trigger.onTriggeredByHourglass(self);
					}
				}
			}

			self.lastFraction = self.timeFraction;
			self.timeFraction = (float) self.time / (float) totalTime;
		} else {
			self.time = 0;
			self.lastFraction = 0F;
			self.timeFraction = 0F;
		}

		if (self.flipTicks > 0) {
			self.flipTicks--;
		}
	}

public static void flameCloud(Spell spell, float radius, float coefficient, float timeToLive, @Nullable String attribute) {
            spell.deliver.type = Spell.Delivery.Type.CLOUD;
            spell.deliver.delay = 10;
            var cloud = new Spell.Delivery.Cloud();
            cloud.volume.radius = radius;
            cloud.volume.area.vertical_range_multiplier = 0.3F;
            cloud.volume.sound = new Sound(SpellEngineSounds.GENERIC_FIRE_IMPACT_2.id().toString());
            cloud.impact_tick_interval = 8;
            cloud.time_to_live_seconds = timeToLive;
            cloud.spawn.sound = new Sound(SpellEngineSounds.GENERIC_FIRE_IGNITE.id().toString());
            cloud.client_data = new Spell.Delivery.Cloud.ClientData();
            cloud.client_data.light_level = 15;
            cloud.client_data.particles = List.of(
                    ParticleGroupBuilder.of(SpellEngineParticles.flame_ground)
                            .batch(b -> b.shape(ParticleGroup.Shape.PILLAR).verticalOrigin(0.1F).count(3)),
                    ParticleGroupBuilder.of(SpellEngineParticles.flame_medium_a)
                            .batch(ParticleGroupBuilder.Batches.cloud(2, 0.1F).andThen(b -> b.speed(0.02F, 0.1F))),
                    ParticleGroupBuilder.of(SpellEngineParticles.flame_medium_b)
                            .batch(ParticleGroupBuilder.Batches.cloud(1, 0.1F).andThen(b -> b.speed(0.02F, 0.1F))),
                    ParticleGroupBuilder.of(SpellEngineParticles.flame_spark)
                            .batch(ParticleGroupBuilder.Batches.cloud(3, 0.2F).andThen(b -> b.speed(0.03F, 0.2F))));
            spell.deliver.clouds = List.of(cloud);

            var damage = new Spell.Impact();
            if (attribute != null) {
                damage.attribute = attribute;
            }
            damage.action = new Spell.Impact.Action();
            damage.action.type = Spell.Impact.Action.Type.DAMAGE;
            damage.action.damage = new Spell.Impact.Action.Damage();
            damage.action.damage.knockback = 0.2F;
            damage.action.damage.spell_power_coefficient = coefficient;
            damage.sound = new Sound(SpellEngineSounds.GENERIC_FIRE_IMPACT_1.id().toString());
            damage.visuals = Fx.Visuals.of(
                    ParticleGroupBuilder.of(SpellEngineParticles.flame)
                            .batch(ParticleGroupBuilder.Batches.cloud(20, 0.15F).andThen(b -> b.speed(0.05F, 0.15F))),
                    ParticleGroupBuilder.of(SpellEngineParticles.flame_medium_a)
                            .batch(ParticleGroupBuilder.Batches.cloud(20, 0.15F).andThen(b -> b.speed(0.05F, 0.15F))));
            spell.impacts = List.of(damage);
        }

@SubscribeEvent
    public void onKeyInput(InputEvent.KeyInputEvent e) {
        ClientPlayerEntity player = minecraft.player;
        if (player == null) {
            return;
        }

        KeyBinding[] hotbarKeys = minecraft.gameSettings.keyBindsHotbar;
        updatePlayerValues(player);

        // Mode changinging GUI
        if (hotbarKeys[player.inventory.currentItem].isKeyDown() && minecraft.isGameFocused()) {
            player.inventory.getCurrentItem().getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY).ifPresent(iModeChanging->{
                if(player.world.isRemote) {
                    if (!(Minecraft.getInstance().currentScreen instanceof GuiModeSelector)) {
                        Minecraft.getInstance().enqueue(() -> Minecraft.getInstance().displayGuiScreen(new GuiModeSelector(player, new StringTextComponent("modeChanging"))));
                    }
                }
            });
        }

        /* cycleToolBackward/cycleToolForward */
        if (cycleToolBackward.isKeyDown()) {
            minecraft.playerController.tick();
            player.inventory.getStackInSlot(player.inventory.currentItem).getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY)
                    .ifPresent(handler-> {
                        if (handler instanceof IModeChangingItem)
                            ((IModeChangingItem) handler).cycleMode(player, 1);
                    });
        }

        if (cycleToolForward.isKeyDown()) {
            minecraft.playerController.tick();
            player.inventory.getStackInSlot(player.inventory.currentItem).getCapability(CapabilityItemHandler.ITEM_HANDLER_CAPABILITY)
                    .ifPresent(handler-> {
                        if (handler instanceof IModeChangingItem)
                            ((IModeChangingItem) handler).cycleMode(player, -1);
                    });
        }
    }

@Override
    public void aiStep() {
        if (this.isPregnant()) {
            if (this.random.nextInt(3000) == 0) {
                if (!this.level.isClientSide) {
                    ServerLevel level = (ServerLevel) this.level;
                    this.setPregnant(false);
                    Penguin penguin = ModEntityTypes.PENGUIN.get().create(level);
                    penguin.setBaby(true);
                    penguin.moveTo(this.getX(), this.getY(), this.getZ(), 0.0F, 0.0F);
                    level.addFreshEntityWithPassengers(penguin);
                    level.broadcastEntityEvent(this, (byte) 18);
                }
            }
        }
        if (level.getGameTime() % 80L == 0L) {
            if (this.level.getEntitiesOfClass(Penguin.class, this.getBoundingBox().inflate(20.0D)).size() > 4) {
                for (Player player : this.level.getEntitiesOfClass(Player.class, this.getBoundingBox().inflate(10.0D))) {
                    player.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 100, 0, true, true));
                }
            }
        }
        if (!this.level.isClientSide && this.isAlive() && this.isEffectiveAi()) {
            ++this.ticksSinceEaten;
            ItemStack stack = this.getItemBySlot(EquipmentSlot.MAINHAND);
            if (this.canEat(stack)) {
                if (this.ticksSinceEaten > 600) {
                    ItemStack finishedStack = stack.finishUsingItem(this.level, this);
                    if (!finishedStack.isEmpty()) {
                        this.setItemSlot(EquipmentSlot.MAINHAND, finishedStack);
                    }
                    this.ticksSinceEaten = 0;
                } else if (this.ticksSinceEaten > 560 && this.random.nextFloat() < 0.1f) {
                    this.playSound(this.getEatingSound(stack), 1.0f, 1.0f);
                    this.level.broadcastEntityEvent(this, (byte)45);
                }
            }
        }
        super.aiStep();
    }

public static void fellTree(ItemStack stack, Level level, BlockState origin, BlockPos originPos,
                                LivingEntity miner) {
        BlockPos.MutableBlockPos mutablePos = new BlockPos.MutableBlockPos();

        Queue<BlockPos> checking = new ArrayDeque<>();
        Set<BlockPos> visited = new ObjectOpenHashSet<>();

        checking.add(originPos);

        while (!checking.isEmpty()) {
            BlockPos check = checking.remove();
            if (check != originPos) {
                visited.add(check);
            }
            for (int y = 0; y <= 1; y++) {
                for (int x = -1; x <= 1; x++) {
                    for (int z = -1; z <= 1; z++) {
                        if (x != 0 || y != 0 || z != 0) {
                            mutablePos.set(check.getX() + x, check.getY() + y, check.getZ() + z);
                            if (!visited.contains(mutablePos)) {
                                // Check that the found block matches the original block state, which is wood.
                                if (origin.getBlock() == level.getBlockState(mutablePos).getBlock()) {
                                    if (!checking.contains(mutablePos)) {
                                        BlockPos immutablePos = mutablePos.immutable();
                                        checking.add(immutablePos);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        if (!visited.isEmpty() && miner instanceof ServerPlayer serverPlayer) {
            Deque<BlockPos> orderedBlocks = visited.stream()
                    .sorted(Comparator.comparingInt(pos -> pos.getY() - originPos.getY()))
                    .collect(Collectors.toCollection(LinkedList::new));
            new TreeFellingHelper(serverPlayer, stack, orderedBlocks);
        }
    }

public void createNaturalSpawn(boolean clientSync)
    {
        if (!(this.level() instanceof ServerLevel serverLevel))
        {
            return;
        }

        var commonFish = new ArrayList<>(COMMON_FISH);

        if (this.level().isThundering())
        {
            commonFish.add(FOTEntities.STORMFISH);
        }

        for (var entityType : pickRandom(this.javaRandom, commonFish, 3))
        {
            var entity = entityType.create(serverLevel);

            if (entity instanceof Mob mob)
            {
                var compoundTag = new CompoundTag();
                mob.finalizeSpawn(serverLevel, serverLevel.getCurrentDifficultyAt(entity.blockPosition()), MobSpawnType.NATURAL, null, null);

                var tempTag = mob.saveWithoutId(new CompoundTag());

                if (mob instanceof ThievesFish<?>)
                {
                    compoundTag.putString(ThievesFish.VARIANT_TAG, tempTag.getString(ThievesFish.VARIANT_TAG));
                    compoundTag.putBoolean(ThievesFish.TROPHY_TAG, this.random.nextFloat() < FishOfThieves.CONFIG.spawnRate.trophyProbability);
                }
                this.shoalFishData.add(new ShoalFishData(BuiltInRegistries.ENTITY_TYPE.getKey(mob.getType()).toString(), UUID.randomUUID(), compoundTag));
            }
        }

        this.expiredAt = this.level().getGameTime() + FishOfThieves.CONFIG.shoal.maxLifetimeDay * 24000L;

        if (clientSync)
        {
            FOTPlatform.syncClientShoalFish(this, false);
        }
    }

public static void handleSelectMinionTaskPacket(ServerboundSelectMinionTaskPacket msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            FactionPlayerHandler.get(context.player()).getPlayerLord().ifPresent(player -> {
                PlayerMinionController controller = MinionWorldData.getData(((ServerPlayer) context.player()).level()).getOrCreateController(player);
                if (RECALL.equals(msg.taskID())) {
                    if (msg.minionID() < 0) {
                        Collection<Integer> ids = controller.recallMinions(false);
                        for (Integer id : ids) {
                            controller.createMinionEntityAtPlayer(id, context.player());
                        }
                        printRecoveringMinions(((ServerPlayer) context.player()), controller.getRecoveringMinionNames());

                    } else {
                        if (controller.recallMinion(msg.minionID())) {
                            controller.createMinionEntityAtPlayer(msg.minionID(), context.player());
                        } else {
                            context.player().sendOverlayMessage(Component.translatable("message.factionapi.minion.still_recovering", controller.contactMinionData(msg.minionID(), MinionData::getFormattedName).orElseGet(() -> Component.literal("1"))));
                        }
                    }
                } else if (RESPAWN.equals(msg.taskID())) {
                    Collection<Integer> ids = controller.getUnclaimedMinions();
                    for (Integer id : ids) {
                        controller.createMinionEntityAtPlayer(id, context.player());
                    }
                    printRecoveringMinions(((ServerPlayer) context.player()), controller.getRecoveringMinionNames());

                } else {
                    var task = ModRegistries.MINION_TASKS.get(msg.taskID());
                    if (task.isEmpty()) {
                        LOGGER.error("Cannot find action to activate {}", msg.taskID());
                    } else if (msg.minionID() < -1) {
                        LOGGER.error("Illegal minion id {}", msg.minionID());
                    } else {
                        //noinspection unchecked
                        controller.activateTask(msg.minionID(), (IMinionTask<?, MinionData>) task.get().value());
                    }
                }
            });

        });
    }

public static Set<PoiRecord> getVillagePointsOfInterest(ServerLevel world, BlockPos pos) {
        int maxRadius = FactionConfig.server().villageMaximumTotemRadius.get();
        // expanded points are seeds or closer than maxRadius, and their neighbours are at most NEIGHBOUR_RADIUS away, so a single query covers every reachable point
        List<PoiRecord> candidates = world.getPoiManager().getInRange(type -> !type.is(FactionPoiTypeTags.HAS_FACTION), pos, Math.max(SEED_RADIUS, maxRadius) + NEIGHBOUR_RADIUS, PoiManager.Occupancy.ANY).toList();
        if (candidates.isEmpty()) {
            return Sets.newHashSet();
        }

        // bucket candidates into columns of NEIGHBOUR_RADIUS width, so neighbours are only searched in the 3x3 surrounding columns
        Long2ObjectOpenHashMap<List<PoiRecord>> grid = new Long2ObjectOpenHashMap<>();
        for (PoiRecord candidate : candidates) {
            grid.computeIfAbsent(gridKey(candidate.getPos().getX(), candidate.getPos().getZ()), key -> new ArrayList<>()).add(candidate);
        }

        Set<PoiRecord> finished = Sets.newHashSet();
        ArrayDeque<PoiRecord> queue = new ArrayDeque<>();
        for (PoiRecord candidate : candidates) {
            if (candidate.getPos().distSqr(pos) <= SEED_RADIUS * SEED_RADIUS) {
                // seeds are always expanded, even outside of maxRadius
                finished.add(candidate);
                queue.add(candidate);
            }
        }
        while (!queue.isEmpty()) {
            BlockPos current = queue.poll().getPos();
            int cellX = Math.floorDiv(current.getX(), NEIGHBOUR_RADIUS);
            int cellZ = Math.floorDiv(current.getZ(), NEIGHBOUR_RADIUS);
            for (int dx = -1; dx <= 1; dx++) {
                for (int dz = -1; dz <= 1; dz++) {
                    List<PoiRecord> cell = grid.get(ChunkPos.pack(cellX + dx, cellZ + dz));
                    if (cell == null) continue;
                    for (PoiRecord point : cell) {
                        if (point.getPos().distSqr(current) <= NEIGHBOUR_RADIUS * NEIGHBOUR_RADIUS && finished.add(point) && point.getPos().closerThan(pos, maxRadius)) {
                            queue.add(point);
                        }
                    }
                }
            }
        }
        return finished;
    }

@Override
	protected void tick(ServerLevel level, E owner, long gameTime) {
		if (owner.isBlocking()) {
			blockTime++;

			LivingEntity target = owner.getLastHurtByMob();

			if (blockTime >= 5) {
				if (!owner.getBrain().hasMemoryValue(MemoryModuleType.LOOK_TARGET))
					BehaviorUtils.lookAtEntity(owner, target);

				if (owner.isWithinMeleeAttackRange(target)) {
					owner.swing(InteractionHand.MAIN_HAND);
					owner.doHurtTarget(target);
					doStop(level, owner, gameTime);
				}
				else if (owner.onGround()) {
					Vec3 lungeVector = new Vec3(target.getX() - owner.getX(), 0, target.getZ() - owner.getZ());

					if (lungeVector.lengthSqr() > 1.0E-7D)
						lungeVector = lungeVector.normalize().scale(0.4d);

					owner.setDeltaMovement(lungeVector.x(), 0.1f, lungeVector.z());
				}
			}

			return;
		}

		if (lastHitTime != owner.getLastHurtByMobTimestamp()) {
			lastHitTime = owner.getLastHurtByMobTimestamp();
			stunCount++;
		}

		if (stunCount > 2) {
			if (!(owner.getItemInHand(InteractionHand.OFF_HAND).getItem() instanceof ShieldItem))
				owner.setItemInHand(InteractionHand.OFF_HAND, new ItemStack(Items.SHIELD));

			owner.startUsingItem(InteractionHand.OFF_HAND);
		}
	}

