@Override
    public void onResolveBlock(BlockHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
        int signalModifier = Mth.clamp((int) spellStats.getAmpMultiplier() + 10, 1, 15);
        int timeBonus = (int) spellStats.getDurationMultiplier();
        int delay = Math.max(GENERIC_INT.get() + timeBonus * BONUS_TIME.get(), 2);
        List<BlockPos> posList = SpellUtil.calcAOEBlocks(shooter, rayTraceResult.getBlockPos(), rayTraceResult, spellStats);
        Player fakePlayer = ANFakePlayer.getOrFakePlayer((ServerLevel) world, shooter);
        for (BlockPos pos1 : posList) {
            if (spellStats.isSensitive()) {
                if (!world.isInWorldBounds(pos1))
                    return;
                pos1 = pos1.immutable();
                RedstoneSavedData.from((ServerLevel) world).SIGNAL_MAP.put(pos1, new RedstoneSavedData.Entry(pos1, signalModifier, delay));
                world.neighborChanged(pos1, world.getBlockState(pos1).getBlock(), pos1);
                world.updateNeighborsAt(pos1, world.getBlockState(pos1).getBlock());
            } else {

                pos1 = pos1.relative(rayTraceResult.getDirection());

                if (!world.isInWorldBounds(pos1))
                    return;
                boolean notReplaceable = !world.getBlockState(pos1).canBeReplaced();
                if (notReplaceable)
                    continue;
                var event = NeoForge.EVENT_BUS.post(new BlockEvent.EntityPlaceEvent(BlockSnapshot.create(world.dimension(), world, pos1), world.getBlockState(pos1), fakePlayer));
                if (event.isCanceled()) {
                    continue;
                }
                BlockState state1 = BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState().setValue(TemporaryBlock.POWER, signalModifier);
                world.setBlockAndUpdate(pos1, state1);
                if (world.getBlockEntity(pos1) instanceof TemporaryTile tile) {
                    tile.gameTime = world.getGameTime();
                    tile.tickDuration = delay;
                    tile.mimicState = Blocks.REDSTONE_BLOCK.defaultBlockState();
                    tile.updateBlock();
                }
                world.sendBlockUpdated(pos1, world.getBlockState(pos1), world.getBlockState(pos1), 2);
            }
        }

    }

@SubscribeEvent
    public static void serverTick(LevelTickEvent.Post event) {
        if (INSTANCE.dirtyProjectiles.isEmpty()) {
            return;
        }
        if (event.getLevel() instanceof ServerLevel serverLevel) {
            HashMap<Entity, List<Projectile>> toSync = new HashMap<Entity, List<Projectile>>();
            var dirtyProjectiles = INSTANCE.dirtyProjectiles.getOrDefault(serverLevel.dimension(), List.of());
            for (int i = dirtyProjectiles.size() - 1; i >= 0; i--) {
                var projectile = dirtyProjectiles.get(i);
                if (projectile.isRemoved()) {
                    dirtyProjectiles.remove(i);
                    continue;
                }
                if (projectile.isAddedToLevel()) {
                    Vec3 start = projectile.position();
                    int searchRange = 48;
                    Vec3 end = Utils.raycastForBlock(serverLevel, start, projectile.getDeltaMovement().normalize().scale(searchRange).add(start), ClipContext.Fluid.NONE).getLocation();
                    for (Map.Entry<UUID, HashSet<Projectile>> entityToTrackedProjectiles : GuidingBoltManager.INSTANCE.trackedEntities.entrySet()) {
                        var entity = serverLevel.getEntity(entityToTrackedProjectiles.getKey());
                        if (entity != null) {
                            if (Math.abs(entity.getX() - projectile.getX()) > searchRange || Math.abs(entity.getY() - projectile.getY()) > searchRange || Math.abs(entity.getZ() - projectile.getZ()) > searchRange) {
                                continue;
                            }
                            float homeRadius = 3.5f + Math.min(entity.getBbWidth() * .5f, 2);
                            if (!entity.equals(projectile.getOwner()) && (entity.getBoundingBox().inflate(homeRadius).contains(start) || Utils.checkEntityIntersecting(entity, start, end, homeRadius).getType() == HitResult.Type.ENTITY)) {
                                updateTrackedProjectiles(entityToTrackedProjectiles.getValue(), projectile);
                                toSync.computeIfAbsent(entity, (key) -> new ArrayList<>()).add(projectile);
                                break;
                            }
                        }
                    }
                    dirtyProjectiles.remove(i);
                }
            }
            for (Map.Entry<Entity, List<Projectile>> entry : toSync.entrySet()) {
                var entity = entry.getKey();
                PacketDistributor.sendToPlayersTrackingEntity(entity, new GuidingBoltManagerStartTrackingPacket(entity, entry.getValue()));
            }
        }
    }

@Override
    public void tick() {
        super.tick();

        if (caster != null && !caster.isAlive()) this.discard();

        if (caster !=null){
            this.setYRot(caster.yHeadRot);
           // this.setXRot(caster.getXRot());
        }
        float yaw = (float) Math.toRadians(-getYRot());
        float pitch = (float) Math.toRadians(-getXRot());
        float spread = 0.25f;
        float speed = 0.56f;
        float xComp = (float) (Math.sin(yaw) * Math.cos(pitch));
        float yComp = (float) (Math.sin(pitch));
        float zComp = (float) (Math.cos(yaw) * Math.cos(pitch));
        double theta = (getYRot()) * (Math.PI / 180);
        theta += Math.PI / 2;
        double vecX = Math.cos(theta);
        double vecZ = Math.sin(theta);
        double vec = 0.9;
        if (level().isClientSide) {
            for (int i = 0; i < 80; i++) {
                double xSpeed = speed * xComp + (spread * 1 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - xComp * xComp)));
                double ySpeed = speed * yComp + (spread * 1 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - yComp * yComp)));
                double zSpeed = speed * zComp + (spread * 1 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - zComp * zComp)));
                level().addParticle(ParticleTypes.SMOKE, getX() + vec * vecX, getY(), getZ() + vec * vecZ, xSpeed, ySpeed, zSpeed);
            }
            for (int i = 0; i < 2; i++) {
                double xSpeed = speed * xComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - xComp * xComp)));
                double ySpeed = speed * yComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - yComp * yComp)));
                double zSpeed = speed * zComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - zComp * zComp)));
                level().addParticle(ParticleTypes.FLAME, getX() + vec * vecX, getY(), getZ() + vec * vecZ, xSpeed, ySpeed, zSpeed);
            }
        }
        if (tickCount > 2 && caster != null) {
            hitEntities();
        }
        if (tickCount > 25) discard() ;
    }

@SubscribeEvent
    public void tickEnd(ClientTickEvent.Post event) {
        //Note: We check that the game mode is not null as if it is that means the world is unloading, and we don't actually want to be rendering
        // as our data may be out of date or invalid. For example configs could unload while it is still unloading
        Level world;
        //noinspection ConstantValue
        if (minecraft.player != null && (world = minecraft.player.level()) != null && minecraft.gameMode != null && MekanismRenderer.isRunningNormally()) {
            float partialTicks = MekanismRenderer.getPartialTick();
            for (Player p : world.players()) {
                //Traverse active jetpacks and do animations
                if (Mekanism.playerState.isJetpackOn(p)) {
                    doJetpackRender(p, world, partialTicks);
                }

                if (world.getGameTime() % 4 == 0) {
                    //Traverse active scuba masks and do animations
                    if (Mekanism.playerState.isScubaMaskOn(p)) {
                        if (p.isInWater()) {
                            doScubaRender(p, world);
                        }
                    }

                    //Traverse players and do animations for idle flamethrowers
                    if (!p.isSwinging()) {
                        if (p.isUsingItem()) {
                            InteractionHand usedHand = p.getUsedItemHand();
                            if (!(p.getItemInHand(usedHand).getItem() instanceof ItemFlamethrower)) {
                                //If we the used item isn't a flamethrower, grab the other hand's item for checks
                                // if it was an active flamethrower we just skip adding the idle particles
                                tryAddIdleFlamethrowerParticles(minecraft, p, usedHand == InteractionHand.MAIN_HAND ? InteractionHand.OFF_HAND : InteractionHand.MAIN_HAND, partialTicks);
                            }
                        } else if (!tryAddIdleFlamethrowerParticles(minecraft, p, InteractionHand.MAIN_HAND, partialTicks)) {
                            //If the player isn't using an item, try to first add particles for a flamethrower in the main hand
                            // and then add particles for a flamethrower in the offhand if we failed
                            tryAddIdleFlamethrowerParticles(minecraft, p, InteractionHand.OFF_HAND, partialTicks);
                        }
                    }
                }
            }
        }
    }

