@Nullable
    private TransferHandler _getTransferHandler() {
        lastCheckTime = Util.getMillis();

        if (PluginManager.areAnyReloading()) {
            return null;
        }

        try {
            DisplayRegistry displayRegistry = DisplayRegistry.getInstance();
            DisplayCache displayCache = ((DisplayRegistryImpl) displayRegistry).cache();
            CategoryRegistry categoryRegistry = CategoryRegistry.getInstance();
            Map<CategoryIdentifier<?>, Boolean> filteringQuickCraftCategories = ConfigObject.getInstance().getFilteringQuickCraftCategories();
            boolean shouldFilterDisplays = ConfigObject.getInstance().shouldFilterDisplays();

            for (Display display : displayCache.getAllDisplaysByOutputs(getEntries())) {
                CategoryIdentifier<?> categoryIdentifier = display.getCategoryIdentifier();
                Optional<? extends CategoryRegistry.CategoryConfiguration<?>> configuration;
                if ((configuration = categoryRegistry.tryGet(categoryIdentifier)).isEmpty()
                        || categoryRegistry.isCategoryInvisible(configuration.get().getCategory())) continue;
                if (!filteringQuickCraftCategories.getOrDefault(categoryIdentifier, configuration.get().isQuickCraftingEnabledByDefault()))

                    continue;
                if ((!shouldFilterDisplays || displayRegistry.isDisplayVisible(display))
                ) {
                    AutoCraftingEvaluator.AutoCraftingResult result = AutoCraftingEvaluator.evaluateAutoCrafting(false, false, display, null);
                    if (result.successful) {
                        this.display = display;
                        this.displayTooltipComponent = Suppliers.memoize(() -> new DisplayTooltipComponent(display));
                        return result.successfulHandler;
                    }
                }
            }
        } catch (ConcurrentModificationException ignored) {
            display = null;
            displayTooltipComponent = null;
            lastCheckTime = -1;
        }

        return null;
    }

public static void handle(MessageMungusBiomeChange message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            context.get().enqueueWork(() -> {
                Player player = context.get().getSender();
                if (context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                    player = AlexsMobs.PROXY.getClientSidePlayer();
                }

                if (player != null) {
                    if (player.level() != null) {
                        Entity entity = player.level().getEntity(message.mungusID);
                        Registry<Biome> registry = player.level().registryAccess().registryOrThrow(Registries.BIOME);
                        Biome biome = registry.get(new ResourceLocation(message.biomeOption));
                        ResourceKey<Biome> resourceKey = registry.getResourceKey(biome).orElse(null);
                        Holder<Biome> holder = registry.getHolder(resourceKey).orElse(null);
                        if (AMConfig.mungusBiomeTransformationType == 2) {
                            if (entity instanceof EntityMungus && entity.distanceToSqr(message.posX, entity.getY(), message.posZ) < 1000 && biome != null) {
                                LevelChunk chunk = player.level().getChunkAt(new BlockPos(message.posX, 0, message.posZ));
                                int i = QuartPos.fromBlock(chunk.getMinBuildHeight());
                                int k = i + QuartPos.fromBlock(chunk.getHeight()) - 1;
                                int l = Mth.clamp(QuartPos.fromBlock((int)entity.getY()), i, k);
                                int j = chunk.getSectionIndex(QuartPos.toBlock(l));
                                LevelChunkSection section = chunk.getSection(j);
                                if(section != null){
                                    PalettedContainer<Holder<Biome>> container = section.getBiomes().recreate();
                                    for (int biomeX = 0; biomeX < 4; ++biomeX) {
                                        for (int biomeY = 0; biomeY < 4; ++biomeY) {
                                            for (int biomeZ = 0; biomeZ < 4; ++biomeZ) {
                                                container.getAndSetUnchecked(biomeX, biomeY, biomeZ, holder);
                                            }
                                        }
                                    }
                                    section.biomes = container;
                                }
                                AlexsMobs.PROXY.updateBiomeVisuals(message.posX, message.posZ);
                            }
                        }
                    }
                }
            });

        }

public static CraftingStatus create(IncrementalUpdateHelper changes, CraftingCpuLogic logic) {

        boolean full = changes.isFullUpdate();

        ImmutableList.Builder<CraftingStatusEntry> newEntries = ImmutableList.builder();
        for (var what : changes) {
            long storedCount = logic.getStored(what);
            long activeCount = logic.getWaitingFor(what);
            long pendingCount = logic.getPendingOutputs(what);

            var sentStack = what;
            if (!full && changes.getSerial(what) != null) {
                // The item was already sent to the client, so we can skip the item stack
                sentStack = null;
            }

            var entry = new CraftingStatusEntry(
                    changes.getOrAssignSerial(what),
                    sentStack,
                    storedCount,
                    activeCount,
                    pendingCount);
            newEntries.add(entry);

            if (entry.isDeleted()) {
                changes.removeSerial(what);
            }
        }

        long elapsedTime = logic.getElapsedTimeTracker().getElapsedTime();
        long remainingItems = logic.getElapsedTimeTracker().getRemainingItemCount();
        long startItems = logic.getElapsedTimeTracker().getStartItemCount();
        boolean suspended = logic.isJobSuspended();

        return new CraftingStatus(
                full,
                elapsedTime,
                remainingItems,
                startItems,
                newEntries.build(),
                suspended);
    }

@TestPlot("mechest_input_deferred_side_effects")
    public static void testMEChestInput(PlotBuilder plot) {
        plot.creativeEnergyCell(BlockPos.ZERO.below());
        plot.blockEntity(BlockPos.ZERO, AEBlocks.ME_CHEST, chest -> {
            chest.setCell(AEItems.ITEM_CELL_1K.stack());
        });

        plot.test(helper -> {
            helper.startSequence()
                    .thenExecute(() -> {
                        var chest = helper.getBlockEntity(BlockPos.ZERO,
                                MEChestBlockEntity.class);

                        // The input slot (any side other than the front) has its own side-effect: items
                        // placed there get automatically moved into the cell's storage (tryToStoreContents()).
                        var inputSide = chest.getFront().getOpposite();
                        var inputHandler = chest.getExposedItemHandler(inputSide);
                        helper.check(inputHandler != null, "input handler should not be null", BlockPos.ZERO);

                        try (var tx = Transaction.open(null)) {
                            var inserted = inputHandler.insert(ItemResource.of(Items.EMERALD), 1, tx);
                            helper.check(inserted == 1, "Should insert emerald into input slot", BlockPos.ZERO);

                            // The item should sit in the raw input slot, but not yet be moved into the cell
                            helper.check(!chest.getInternalInventory().getStackInSlot(0).isEmpty(),
                                    "Emerald visible in input slot during transaction", BlockPos.ZERO);
                            helper.check(
                                    chest.getInventory().getAvailableStacks().get(AEItemKey.of(Items.EMERALD)) == 0,
                                    "Emerald should not be in cell storage yet", BlockPos.ZERO);

                            tx.commit();
                        }

                        // After commit, the emerald should have been moved out of the input slot and into the cell
                        helper.check(chest.getInternalInventory().getStackInSlot(0).isEmpty(),
                                "Input slot should be empty after commit", BlockPos.ZERO);
                        helper.check(chest.getInventory().getAvailableStacks().get(AEItemKey.of(Items.EMERALD)) == 1,
                                "Emerald should have been stored in the cell after commit", BlockPos.ZERO);
                    })
                    .thenSucceed();
        });
    }

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		final IMultiblockLevel level = context.getLevel();
		final Level rawLevel = level.getRawLevel();
		final boolean rsAllowed = state.rsState.isEnabled(context);
		int i = 0;
		Iterator<SawmillProcess> processIterator = state.sawmillProcessQueue.iterator();
		Set<ItemStack> secondaries = new HashSet<>();
		while(rsAllowed&&processIterator.hasNext()&&i++ < MAX_PROCESSES)
		{
			SawmillProcess process = processIterator.next();
			if(process.processStep(rawLevel, state.energy, state.sawblade, secondaries))
				context.markMasterDirty();
			if(process.isProcessFinished())
			{
				state.output.insertOrDrop(process.getCurrentStack(rawLevel, !state.sawblade.isEmpty()).copy(), level);
				processIterator.remove();
				ItemUtils.damageStackableItem(state.sawblade, level.getRawLevel(), IEServerConfig.MACHINES.sawmill_bladeDamage.get());
				context.markDirtyAndSync();
			}
		}
		for(ItemStack output : secondaries)
			state.secondaryOutput.insertOrDrop(output.copy(), level);
		ActiveState renderActive;
		boolean noJobs = state.sawmillProcessQueue.isEmpty();
		boolean hasBlade = !state.sawblade.isEmpty();
		if(state.energy.getEnergyStored() <= 0||!rsAllowed||(noJobs&&!hasBlade))
			renderActive = ActiveState.NOT_RUNNING;
		else if(noJobs)
			renderActive = ActiveState.IDLE_WITH_BLADE;
		else if(hasBlade)
			renderActive = ActiveState.SAWING;
		else
			renderActive = ActiveState.RUNNING_NO_BLADE;
		if(state.active!=renderActive)
		{
			state.active = renderActive;
			context.markDirtyAndSync();
		}
	}

@Override
	public void tickServer()
	{
		if(level.getGameTime()%8!=0||!isActive())
			return;
		IItemHandler outputHandler = output.getCapability();
		if(outputHandler!=null)
		{
			boolean matched = true;
			if(this.batchMode==BatchMode.ALL)
			{
				for(int slot = 0; slot < NUM_SLOTS; slot++)
					if(!this.filters.get(slot).isEmpty())
						matched &= isFilterMatched(slot);
			}
			if(matched)
			{
				boolean anySent = false;
				for(int slot = 0; slot < NUM_SLOTS; slot++)
				{
					ItemStack filterStack = this.filters.get(slot);
					if(filterStack.isEmpty())
						continue;
					if(this.batchMode==BatchMode.ALL||isFilterMatched(slot))
					{
						ItemStack outStack = buffers.get(slot);
						int outSize = filterStack.getCount();
						ItemStack stack = outStack.copyWithCount(outSize);
						stack = ItemHandlerHelper.insertItem(outputHandler, stack, false);
						if(!stack.isEmpty())
							outSize -= stack.getCount();
						outStack.shrink(outSize);
						if(outStack.getCount() <= 0)
							this.buffers.set(slot, ItemStack.EMPTY);
						anySent = true;
					}
				}
				if(anySent)
					redstoneCap.markDirty();
			}
		}
	}

@OnlyIn(Dist.CLIENT)
	protected void tickAudio(WhistleSize size, boolean powered) {
		if (!powered) {
			if (soundInstance != null) {
				soundInstance.fadeOut();
				soundInstance = null;
			}
			return;
		}

		float f = (float) Math.pow(2, -pitch / 12.0);
		boolean particle = level.getGameTime() % 8 == 0;
		Vec3 eyePosition = Minecraft.getInstance().cameraEntity.getEyePosition();
		float maxVolume = (float) Mth.clamp((64 - eyePosition.distanceTo(Vec3.atCenterOf(worldPosition))) / 64, 0, 1);

		if (soundInstance == null || soundInstance.isStopped() || soundInstance.getOctave() != size) {
			Minecraft.getInstance()
				.getSoundManager()
				.play(soundInstance = new WhistleSoundInstance(size, worldPosition));
			AllSoundEvents.WHISTLE_CHIFF.playAt(level, worldPosition, maxVolume * .175f,
				size == WhistleSize.SMALL ? f + .75f : f, false);
			particle = true;
		}

		soundInstance.keepAlive();
		soundInstance.setPitch(f);

		if (!particle)
			return;

		Direction facing = getBlockState().getOptionalValue(WhistleBlock.FACING)
			.orElse(Direction.SOUTH);
		float angle = 180 + AngleHelper.horizontalAngle(facing);
		Vec3 sizeOffset = VecHelper.rotate(new Vec3(0, -0.4f, 1 / 16f * size.ordinal()), angle, Axis.Y);
		Vec3 offset = VecHelper.rotate(new Vec3(0, 1, 0.75f), angle, Axis.Y);
		Vec3 v = offset.scale(.45f)
			.add(sizeOffset)
			.add(Vec3.atCenterOf(worldPosition));
		Vec3 m = offset.subtract(Vec3.atLowerCornerOf(facing.getNormal())
			.scale(.75f));
		level.addParticle(new SteamJetParticleData(1), v.x, v.y, v.z, m.x, m.y, m.z);
	}

public static void handle(CopyQuestMessage message, NetworkManager.PacketContext context) {
        context.queue(() -> ServerQuestFile.getInstance().ifPresent(sqf -> {
            if (PermissionsHelper.canPlayerEdit(context) && sqf.get(message.id) instanceof Quest toCopy && sqf.get(message.chapterId) instanceof Chapter chapter) {
                var allocator = new BaseQuestFile.UniqueIdAllocator(sqf);

                // deep copy of the quest
                Quest newQuest = QuestObjectBase.copy(toCopy, () -> new Quest(allocator.newId(), chapter));
                if (newQuest == null) {
                    return;
                }
                if (!message.copyDeps) {
                    newQuest.clearDependencies();
                }
                newQuest.setPosition(message.qx, message.qy);
                newQuest.setRawSubtitle(toCopy.getRawSubtitle());
                newQuest.setRawDescription(toCopy.getRawDescription());

                // deep copy of all tasks and rewards
                List<CreateOrDeleteRecord> newTasks = new ArrayList<>();
                toCopy.getTasks().forEach(task -> {
                    Task newTask = QuestObjectBase.copy(task, () -> TaskType.createTask(allocator.newId(), newQuest, task.getType().getTypeForNBT()));
                    if (newTask != null) {
                        newTasks.add(CreateOrDeleteRecord.ofQuestObject(newTask));
                    }
                });
                List<CreateOrDeleteRecord> newRewards = new ArrayList<>();
                for (Reward reward : toCopy.getRewards()) {
                    Reward newReward = QuestObjectBase.copy(reward, () -> RewardType.createReward(allocator.newId(), newQuest, reward.getType().getTypeForNBT()));
                    if (newReward != null) {
                        newRewards.add(CreateOrDeleteRecord.ofQuestObject(newReward));
                    }
                }

                List<CreateOrDeleteRecord> recs = new ArrayList<>();
                recs.add(CreateOrDeleteRecord.ofQuestObject(newQuest));
                recs.addAll(newTasks);
                recs.addAll(newRewards);

                sqf.getHistoryStack().addAndApply(sqf, new CreateQuestObjects(recs, null));
            }
        }));
    }

