private static void assertEndpointFinalization(String adapterNamespace, String adapterPath, String hostNamespace, String hostPath, boolean accepted) {
		ResourceLocation adapterFactory = ResourceLocation.fromNamespaceAndPath(adapterNamespace, adapterPath);
		ResourceLocation hostFactory = ResourceLocation.fromNamespaceAndPath(hostNamespace, hostPath);
		if (accepted) {
			LinkedStorageHostFactories.registerCompatibility(adapterFactory, hostFactory);
		}
		ILinkedStorageItemEndpointAdapter adapter = new TestEndpointAdapter() {
			@Override
			public ResourceLocation factoryId() {
				return adapterFactory;
			}
		};
		ServerLevel level = Mockito.mock(ServerLevel.class);
		LinkedStorageGroupsSavedData savedData = Mockito.mock(LinkedStorageGroupsSavedData.class);
		LinkedStorageGroupManager manager = Mockito.mock(LinkedStorageGroupManager.class);
		UUID claimId = UUID.randomUUID();
		LinkedStorageEndpointData endpoint = new LinkedStorageEndpointData(UUID.randomUUID(), UUID.randomUUID());
		ItemStack result = new ItemStack(Items.STICK);
		EnderLinkPendingCraftData pending = new EnderLinkPendingCraftData(EnderLinkPendingCraftPlan.ADD_SECONDARY, claimId);
		result.set(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT, pending);
		Mockito.when(savedData.manager()).thenReturn(manager);
		Mockito.when(manager.getActivePendingCraftClaim(claimId))
				.thenReturn(Optional.of(new ActivePendingCraftClaim(claimId, endpoint.groupId(), endpoint.endpointId(), pending.plan())));
		Mockito.when(manager.getHostDescriptor(endpoint.groupId())).thenReturn(Optional.of(new LinkedStorageHostDescriptor(hostFactory, new CompoundTag())));
		try (MockedStatic<LinkedStorageGroupsSavedData> groups = Mockito.mockStatic(LinkedStorageGroupsSavedData.class);
				MockedStatic<LinkedStorageEndpointAdapters> adapters = Mockito.mockStatic(LinkedStorageEndpointAdapters.class)) {
			groups.when(() -> LinkedStorageGroupsSavedData.get(level)).thenReturn(savedData);
			adapters.when(() -> LinkedStorageEndpointAdapters.find(result)).thenReturn(Optional.of(adapter));

			assertEquals(accepted, EnderLinkerEndpointRecipe.finalizePendingCraftResult(level, result));
		}

		if (accepted) {
			assertEquals(endpoint, result.get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT));
			assertFalse(result.has(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT));
			Mockito.verify(manager).consumeActivePendingCraftClaim(claimId);
		} else {
			assertEquals(pending, result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT));
			assertFalse(result.has(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT));
			Mockito.verify(manager, Mockito.never()).consumeActivePendingCraftClaim(Mockito.any());
		}
	}

public List<BoltQuads> generate() {
        Random random = new Random();
        List<BoltQuads> quads = new ArrayList<>();
        Vec3 diff = end.subtract(start);
        float totalDistance = (float) diff.length();
        for (int i = 0; i < count; i++) {
            Queue<BoltInstructions> drawQueue = new ArrayDeque<>();
            drawQueue.add(new BoltInstructions(start, 0, Vec3.ZERO, null, false));
            while (!drawQueue.isEmpty()) {
                BoltInstructions data = drawQueue.poll();
                Vec3 perpendicularDist = data.perpendicularDist();
                float progress = data.progress() + (1F / segments) * (1 - renderInfo.parallelNoise + random.nextFloat() * renderInfo.parallelNoise * 2);
                Vec3 segmentEnd;
                float segmentDiffScale = renderInfo.spreadFunction.getMaxSpread(progress);
                if (progress >= 1 && segmentDiffScale <= 0) {
                    segmentEnd = end;
                } else {
                    float maxDiff = renderInfo.spreadFactor * segmentDiffScale * totalDistance;
                    Vec3 randVec = findRandomOrthogonalVector(diff, random);
                    double rand = renderInfo.randomFunction.getRandom(random);
                    perpendicularDist = renderInfo.segmentSpreader.getSegmentAdd(perpendicularDist, randVec, maxDiff, segmentDiffScale, progress, rand);
                    segmentEnd = start.add(diff.scale(progress)).add(perpendicularDist);
                }
                float boltSize = size * (0.5F + (1 - progress) * 0.5F);
                Pair<BoltQuads, QuadCache> quadData = createQuads(data.cache(), data.start(), segmentEnd, boltSize);
                quads.add(quadData.getLeft());

                if (progress >= 1) {
                    break;
                } else if (!data.isBranch()) {
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), false));
                } else if (random.nextFloat() < renderInfo.branchContinuationFactor) {
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
                }

                while (random.nextFloat() < renderInfo.branchInitiationFactor * (1 - progress)) {
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
                }
            }
        }
        return quads;
    }

@Override
    protected void tryAbsorbWater(Level level, BlockPos pos) {
        Queue<Tuple<BlockPos, Integer>> queue = Lists.newLinkedList();
        queue.add(new Tuple<>(pos, 0));
        int checkedBlocksCount = 0;

        while (!queue.isEmpty()) {
            Tuple<BlockPos, Integer> tuple = queue.poll();
            BlockPos blockpos = tuple.getA();
            int currentRange = tuple.getB();

            for (Direction direction : Direction.values()) {
                BlockPos blockToCheckPos = blockpos.relative(direction);
                BlockState blockToCheckState = level.getBlockState(blockToCheckPos);
                Block blockToCheck = blockToCheckState.getBlock();

                if (blockToCheck instanceof BucketPickup bucketPickup && !bucketPickup.pickupBlock(null, level, blockToCheckPos, blockToCheckState).isEmpty()) {
                    ++checkedBlocksCount;

                    if (currentRange < MAX_RANGE) {
                        queue.add(new Tuple<>(blockToCheckPos, currentRange + 1));
                    }

                } else if (blockToCheckState.getBlock() instanceof LiquidBlock) {
                    if (blockToCheckState.is(Blocks.KELP) || blockToCheckState.is(Blocks.KELP_PLANT) || blockToCheckState.is(Blocks.SEAGRASS) || blockToCheckState.is(Blocks.TALL_SEAGRASS)) {
                        BlockEntity blockEntity = blockToCheckState.hasBlockEntity() ? level.getBlockEntity(blockToCheckPos) : null;
                        dropResources(blockToCheckState, level, blockToCheckPos, blockEntity);
                    }
                    this.removeBlock(blockToCheckPos, level);
                    ++checkedBlocksCount;

                    if (currentRange < MAX_RANGE) {
                        queue.add(new Tuple<>(blockToCheckPos, currentRange + 1));
                    }
                }
            }

            if (checkedBlocksCount > MAX_REPLACES) {
                break;
            }
        }
    }

@SubscribeEvent
    public void blockDestroyed(BreakBlockEvent event) {
            if (!(event.getLevel() instanceof ServerLevel level)) return;
            //don't allow player to destroy blocks with PointOfInterests that are owned by a totem with different faction as the player
            if (event.getPlayer().isCreative()) return;
            if (FactionConfig.server().villageAllowPoiDestruction.get()) return;

            List<BlockPos> positions = new ArrayList<>();
            List<PoiRecord> inSquare = TotemHelper.findRecords(level, event.getPos()).toList();
            if (!inSquare.isEmpty()) {
                Block block = event.getState().getBlock();
                Optional<PoiRecord> self = inSquare.stream().filter(x -> x.getPos() == event.getPos()).findAny();
                if (self.isPresent()) {
                    positions.add(self.get().getPos());
                } else {
                    positions.addAll(inSquare.stream().map(PoiRecord::getPos).filter(pos -> level.getBlockState(pos).getBlock() == block).toList());
                }
            }

            for (BlockPos position : positions) {
                BlockPos totemPosition = TotemHelper.getTotemPosition(level.dimension(), position);
                if (totemPosition != null && level.isLoaded(totemPosition)) {
                    BlockEntity totem = (event.getLevel().getBlockEntity(totemPosition));
                    if (totem instanceof TotemBlockEntity blockEntity && !IFaction.isNeutral(blockEntity.getControllingFaction()) && !FactionPlayerHandler.get(event.getPlayer()).isInFaction(blockEntity.getControllingFaction())) {
                        event.setCanceled(true);
                        event.getPlayer().sendOverlayMessage(Component.translatable("text.vampirism.village.totem_destroy.fail_totem_faction"));
                        if (!positions.isEmpty() && event.getPlayer() instanceof ServerPlayer player) {
                            positions.forEach(pos -> {
                                player.connection.send(new ClientboundBlockUpdatePacket(event.getLevel(), pos));
                                BlockEntity tileentity = event.getLevel().getBlockEntity(pos);
                                if (tileentity != null) {
                                    Packet<?> pkt = tileentity.getUpdatePacket();
                                    if (pkt != null) {
                                        player.connection.send(pkt);
                                    }
                                }
                            });
                        }
                    }
                }
            }
        }

