@SubscribeEvent
  public void enderManAnger(final EndermanAngerEvent evt) {
    // Check cached value first
    if (enderManMaskCache.size() > 500) {
      enderManMaskCache.clear();
    }
    Player player = evt.getPlayer();
    long gameTime = player.level().getGameTime();

    if (enderManMaskCache.containsKey(player.getUUID())) {
      var pair = enderManMaskCache.get(player.getUUID());

      if (pair.getFirst() == gameTime) {
        evt.setCanceled(pair.getSecond());
        return;
      }
    }
    CuriosApi.getCuriosInventory(player).ifPresent(handler -> {
      all:
      for (Map.Entry<String, ICurioStacksHandler> entry : handler.getCurios().entrySet()) {
        IDynamicStackHandler stacks = entry.getValue().getStacks();

        for (int i = 0; i < stacks.getSlots(); i++) {
          final int index = i;
          NonNullList<Boolean> renderStates = entry.getValue().getRenders();
          boolean hasMask = CuriosApi.getCurio(stacks.getStackInSlot(i)).map(
                  curio -> curio.isEnderMask(new SlotContext(entry.getKey(), player, index, false,
                          renderStates.size() > index
                              && renderStates.get(index)),
                      evt.getEntity()))
              .orElse(false);

          if (hasMask) {
            enderManMaskCache.put(player.getUUID(), Pair.of(gameTime, true));
            evt.setCanceled(true);
            break all;
          }
        }
      }
    });
    enderManMaskCache.put(player.getUUID(), Pair.of(gameTime, false));
  }

@Nullable
    public static Entity teleportEntityTo(Entity entity, @Nullable Level world, BlockPos target, Vec2 rotationVec) {
        if (!(world instanceof ServerLevel targetWorld)) {
            return entity;
        }

        Vec3 destination = new Vec3(target.getX() + 0.5, target.getY(), target.getZ() + 0.5);
        if (entity.getCommandSenderWorld().dimension() == targetWorld.dimension()) {
            // Check if the target block is a portal, if so, don't teleport
            if (targetWorld.getBlockState(target).getBlock() instanceof PortalBlock) {
                return entity;
            }

            targetWorld.getChunkSource().addRegionTicket(TicketType.PORTAL, new ChunkPos(target), 3, target);
            var rotX = rotationVec != null ? rotationVec.x : entity.getXRot();
            var rotY = rotationVec != null ? rotationVec.y : entity.getYRot();
            Networking.sendToNearbyClient(targetWorld, entity, new PacketWarpPosition(entity.getId(), destination.x,destination.y, destination.z, rotX, rotY));
            entity.teleportTo(destination.x, destination.y, destination.z);
            entity.setXRot(rotX);
            entity.setYRot(rotY);

            if (!entity.getPassengers().isEmpty()) {
                //Force re-apply any passengers so that players don't get "stuck" outside what they may be riding
                ((ServerChunkCache) entity.getCommandSenderWorld().getChunkSource()).broadcast(entity, new ClientboundSetPassengersPacket(entity));
                Entity controller = entity.getControllingPassenger();
                if (controller != entity && controller instanceof ServerPlayer player && !(controller instanceof FakePlayer)) {
                    //noinspection ConstantValue
                    if (player.connection != null) {
                        //Force sync the fact that the vehicle moved to the client that is controlling it
                        // so that it makes sure to use the correct positions when sending move packets
                        // back to the server instead of running into moved wrongly issues
                        player.connection.send(new ClientboundMoveVehiclePacket(entity));
                    }
                }
            }
            return entity;
        }

        targetWorld.getChunkSource().addRegionTicket(TicketType.PORTAL, new ChunkPos(target), 3, target);
        //Note: We grab the passengers here instead of in placeEntity as changeDimension starts by removing any passengers
        return entity.changeDimension(new DimensionTransition(targetWorld, destination, Vec3.ZERO, rotationVec.y, rotationVec.x, false, DimensionTransition.DO_NOTHING));
    }

public int updateChunkLoading(MekGameTestHelper helper, boolean load, int level) {
            if (absolutePos == null) {
                absolutePos = helper.absolutePos(relativePos);
                absPos = absolutePos.pack();
            }
            if (helper.isChunkLoaded(relativePos) != load) {
                //If the chunk isn't watched and is loaded we want to try and unload it
                ChunkMap chunkMap = helper.getChunkMap();
                DistanceManager distanceManager = chunkMap.getDistanceManager();
                ChunkHolder holder = distanceManager.getChunk(absPos);
                //Watch the chunk and mark whether it is currently loaded or not
                if ((holder == null) == load) {
                    //If it is loaded then we need to try and unload it
                    isLoaded = !load;
                    if (DEBUG_CHUNK_LOADING) {
                        Mekanism.logger.info("Trying to {} chunk at: {}", load ? "load" : "unload", absolutePos);
                    }
                    if (load) {
                        //Load the chunk to the level it was unloaded at
                        holder = distanceManager.updateChunkScheduling(absPos, level, holder, MekGameTestHelper.UNLOAD_LEVEL);
                        if (holder == null) {//Should never happen unless start value was unloaded
                            helper.fail("Error loading chunk", relativePos);
                        } else {
                            //And ensure we schedule it to be updated by the distance manager
                            distanceManager.chunksToUpdateFutures.add(holder);
                        }
                    } else {
                        //If it is currently loaded, queue it for unload
                        level = holder.getTicketLevel();
                        distanceManager.updateChunkScheduling(absPos, MekGameTestHelper.UNLOAD_LEVEL, holder, level);
                        //And then unload it
                        chunkMap.processUnloads(ConstantPredicates.ALWAYS_TRUE);
                    }
                } else if (DEBUG_CHUNK_LOADING) {
                    //Note: Even with debug logging enabled odds are this case isn't even possible due to the earlier check to skip if unloaded
                    Mekanism.logger.info("Trying to {} already {} chunk at: {}", load ? "load" : "unload", load ? "loaded" : "unloaded", absolutePos);
                }
            } else if (DEBUG_CHUNK_LOADING) {
                Mekanism.logger.info("Chunk at: {} is already {}", absolutePos, load ? "unloaded" : "loaded");
            }
            return level;
        }

private void readyBlockEntities(ServerLevel level) {
        var levelQueue = blockEntities.getBlockEntities(level);
        if (levelQueue == null) {
            return;
        }

        // Make a copy because this set may be modified when new chunks are loaded by an onReady call below
        long[] workSet = levelQueue.keySet().toLongArray();

        for (long packedChunkPos : workSet) {
            // Readies all of our block entities in this chunk as soon as it can tick BEs
            // The following test is equivalent to ServerLevel#isPositionTickingWithEntitiesLoaded
            if (Platform.areBlockEntitiesTicking(level, packedChunkPos)) {
                // Take the currently waiting block entities for this chunk and ready them all. Should more block
                // entities be added to this chunk while we're working on it, a new list will be added automatically and
                // we'll work on this chunk again next tick.
                var chunkQueue = levelQueue.remove(packedChunkPos);
                if (chunkQueue == null) {
                    AELog.warn("Chunk %s was unloaded while we were readying block entities",
                            ChunkPos.unpack(packedChunkPos));
                    continue; // This should never happen, chunk unloaded under our noses
                }

                for (var info : chunkQueue) {
                    // Only ready block entities which weren't destroyed in the meantime.
                    if (!info.blockEntity().isRemoved()) {
                        try {
                            // This could load more chunks, but the earliest time to be initialized is the next tick.
                            info.callInit();
                        } catch (Throwable t) {
                            CrashReport crashReport = CrashReport.forThrowable(t, "Readying AE2 block entity");

                            var category = crashReport.addCategory("Block entity being readied");
                            category.setDetail("World", () -> level.dimension().identifier().toString());
                            info.blockEntity().fillCrashReportCategory(category);

                            throw new ReportedException(crashReport);
                        }
                    }
                }
            }
        }
    }

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final IMultiblockLevel level = ctx.getLevel();
		final State state = ctx.getState();

		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		matrixStack.translate(.5, 0, .5);
		bufferIn = BERenderUtils.mirror(level.getOrientation(), matrixStack, bufferIn);


		VertexConsumer solidBuilder = bufferIn.getBuffer(RenderType.solid());

		Direction facing = level.getOrientation().front();
		float dir = facing==Direction.SOUTH?Mth.PI: facing==Direction.NORTH?0: facing==Direction.EAST?-Mth.HALF_PI: Mth.HALF_PI;
		matrixStack.mulPose(new Quaternionf().rotateY(dir));

		// Sawblade
		boolean sawblade = !state.sawblade.isEmpty();
		if(sawblade)
		{
			matrixStack.pushPose();
			matrixStack.translate(1, .125, -.5);
			float spin = state.animation_bladeRotation;
			if(state.active!=ActiveState.NOT_RUNNING)
				spin += 36f*partialTicks;
			matrixStack.mulPose(new Quaternionf().rotateZ(spin*Mth.DEG_TO_RAD));
			RenderUtils.renderModelTESRFast(
					BLADE.getNullQuads(), solidBuilder, matrixStack, combinedLightIn, combinedOverlayIn
			);
			matrixStack.popPose();
		}

		// Items
		for(SawmillProcess process : state.sawmillProcessQueue)
		{
			float relative = process.getRelativeProcessStep(level.getRawLevel());
			ItemStack rendered = process.getCurrentStack(level.getRawLevel(), sawblade);
			renderItem(rendered, relative, matrixStack, bufferIn, combinedLightIn, combinedOverlayIn, level.getRawLevel());
		}
		matrixStack.popPose();
	}

@Override
        public IMessage onMessage(final MessageCasterOrb message, final MessageContext ctx) {
            EntityPlayer player = ctx.getServerHandler().player;
            WorldServer world = ctx.getServerHandler().player.getServerWorld();
            world.addScheduledTask(() -> {
                ItemStack heldStack = player.getHeldItemMainhand();
                if (ItemModUtil.hasHeat(heldStack)) {
                    int level = ItemModUtil.getModifierLevel(heldStack, EmbersAPI.CASTER_ORB);
                    UUID uuid = player.getUniqueID();
                    if (level > 0 && EmberInventoryUtil.getEmberTotal(player) > EmbersAPI.CASTER_ORB.cost && !ModifierCasterOrb.hasCooldown(uuid)) {
                        float handmod = player.getPrimaryHand() == EnumHandSide.RIGHT ? 1.0f : -1.0f;
                        float offX = handmod * 0.5f * (float) Math.sin(Math.toRadians(-player.rotationYaw - 90));
                        float offZ = handmod * 0.5f * (float) Math.cos(Math.toRadians(-player.rotationYaw - 90));
                        EmberInventoryUtil.removeEmber(player, EmbersAPI.CASTER_ORB.cost);
                        double lookDist = Math.sqrt(message.lookX * message.lookX + message.lookY * message.lookY + message.lookZ * message.lookZ);
                        if (lookDist == 0)
                            return;
                        double xVel = (message.lookX / lookDist) * 0.5;
                        double yVel = (message.lookY / lookDist) * 0.5;
                        double zVel = (message.lookZ / lookDist) * 0.5;
                        double xOrigin = player.posX + offX;
                        double yOrigin = player.posY + player.getEyeHeight();
                        double zOrigin = player.posZ + offZ;

                        double resonance = EmbersAPI.getEmberEfficiency(heldStack);
                        double value = 8.0 * (Math.atan(0.6 * (level)) / (1.25));
                        value *= resonance;
                        EffectDamage effect = new EffectDamage((float) value, DamageEmber.EMBER_DAMAGE_SOURCE_FACTORY, 1, 1.0);
                        ProjectileFireball fireball = new ProjectileFireball(player, new Vec3d(xOrigin, yOrigin, zOrigin), new Vec3d(xVel, yVel, zVel), value, 160, effect);
                        EmberProjectileEvent event = new EmberProjectileEvent(player, heldStack, 0.0, fireball);
                        MinecraftForge.EVENT_BUS.post(event);
                        if (!event.isCanceled()) {
                            for (IProjectilePreset projectile : event.getProjectiles()) {
                                projectile.shoot(world);
                            }
                        }
                        world.playSound(null, xOrigin, yOrigin, zOrigin, SoundManager.FIREBALL, SoundCategory.PLAYERS, 1.0f, 1.0f);
                        ModifierCasterOrb.setCooldown(uuid, 20);
                    }
                }
            });
            return null;
        }

