private void bindDynamicUniforms(ShaderInstance shader, CompiledShaderGraph compiled) {
        var viewport = shader.getUniform(PhotonShaderCompiler.VIEWPORT);
        if (viewport != null) {
            viewport.set((float) GlStateManager.Viewport.x(), (float) GlStateManager.Viewport.y(),
                    (float) GlStateManager.Viewport.width(), (float) GlStateManager.Viewport.height());
        }
        // KilaGraph's world-space nodes (Camera / Position "world" / WorldToScreenUV "absolute") read the
        // absolute camera position as KG's precision-split kg_CameraBlockPos - kg_CameraOffset, which
        // KGBuiltinUniforms binds from the GAME's main camera — wrong in the editor SceneView (orbit camera).
        // Override both halves with the pipeline's actual render camera (the one particles are rendered
        // camera-relative to), so those nodes are correct in the editor scene and in-world alike (mirrors
        // CustomShaderMaterial's U_CameraPosition). Runs after KGBuiltinUniforms.bind in getShader(), so it wins.
        var cameraBlockPos = shader.getUniform("kg_CameraBlockPos");
        var cameraOffset = shader.getUniform("kg_CameraOffset");
        if (cameraBlockPos != null || cameraOffset != null) {
            var camera = Optional.ofNullable(RenderPassPipeline.getCurrent())
                    .map(RenderPassPipeline::getCamera).orElse(null);
            if (camera != null) {
                var p = camera.getPosition();
                double bx = Math.floor(p.x), by = Math.floor(p.y), bz = Math.floor(p.z);
                if (cameraBlockPos != null) cameraBlockPos.set((float) bx, (float) by, (float) bz);
                if (cameraOffset != null) cameraOffset.set((float) (bx - p.x), (float) (by - p.y), (float) (bz - p.z));
            }
        }
        // Same story: KGBuiltinUniforms binds kg_Time (the Time node) from the WORLD clock
        // (mc.level.getGameTime()), which ignores the emitter timeline (play/pause/scrub) and disagrees
        // with the GameTime node — vanilla GameTime IS driven by Photon from the particle time. Override
        // kg_Time to that same particle time: RenderSystem's normalized shader game time (what Photon sets
        // each render) scaled to KG's seconds (24000 ticks = 1200 s), so Time and GameTime nodes agree and
        // freeze/scrub with the emitter.
        var engineTime = shader.getUniform("kg_Time");
        if (engineTime != null) {
            engineTime.set(RenderSystem.getShaderGameTime() * 1200f);
        }
        if (compiled.usesSceneColor() || compiled.usesSceneDepth()) {
            var sampler = Optional.ofNullable(RenderPassPipeline.getCurrent())
                    .map(RenderPassPipeline::getSceneSamplers);
            shader.setSampler(PhotonShaderCompiler.SCENE_COLOR,
                    sampler.map(RenderPassPipeline.SceneSamplers::colorTexture).orElse(-1));
            shader.setSampler(PhotonShaderCompiler.SCENE_DEPTH,
                    sampler.map(RenderPassPipeline.SceneSamplers::depthTexture).orElse(-1));
        }
    }

public void detectStationParts(Level world, BlockPos start) {
    Set<BlockPos> visited = Sets.newHashSet();

    // BFS for related blocks
    Queue<BlockPos> queue = new ArrayDeque<>();
    queue.add(start);

    while (!queue.isEmpty()) {
      BlockPos pos = queue.poll();
      // already visited between adding and call
      if (visited.contains(pos)) {
        continue;
      }

      BlockState state = world.getBlockState(pos);
      if (!(state.getBlock() instanceof ITabbedBlock)) {
        // not a valid block for us
        continue;
      }

      // found a part, add surrounding blocks that haven't been visited yet
      for (Direction direction : Direction.values()) {
        BlockPos offset = pos.relative(direction);
        if (!visited.contains(offset)) {
          queue.add(offset);
        }
      }

      // mark this block as visited to visited
      visited.add(pos);

      // save the thing
      this.stationBlocks.add(Pair.of(pos, state));

      // we only have space for 6 tabs, so stop after the first 6
      if (this.stationBlocks.size() >= 6) {
        break;
      }
    }

    // sort the found blocks by priority
    this.stationBlocks.sort(COMPARATOR);
  }

@Override
	public boolean generate(WorldGenLevel world, RandomSource random, BlockPos pos, BiConsumer<BlockPos, BlockState> trunkPlacer, BiConsumer<BlockPos, BlockState> leavesPlacer, RootPlacer decorationPlacer, TFTreeFeatureConfig config) {
		final int height = 8;
		final int radius = 1;

		// do we have enough height?
		if (world.isOutsideBuildHeight(pos.getY() + 1)
			|| world.isOutsideBuildHeight(pos.getY() + height + radius)
			|| FeatureUtil.isAnyMatchInArea(pos.subtract(new Vec3i(1, 4, 1)), 3, 4, 3, blockPos -> world.getBlockState(blockPos).is(BlockTags.FEATURES_CANNOT_REPLACE))
			|| FeatureUtil.isAnyMatchInArea(pos.subtract(new Vec3i(1, 0, 1)), 3, 16, 3, blockPos -> !FeaturePlacers.validTreePos(world, blockPos) || blockPos == pos)) {
				return false;
 		}

		// check if we're on dirt or grass
		if (world.getBlockState(pos.below()).canSustainPlant(world, pos.below(), Direction.UP, TFBlocks.TIME_SAPLING.get().defaultBlockState()).isFalse()) {
			return false;
		}

		// Start with roots first, so they don't fail placement because they intersect the trunk shell first
		// 3-5 roots at the bottom
		buildBranchRing(world, trunkPlacer, leavesPlacer, random, pos, radius, 1, 0, 12, 0.75D, 3, 5, 3, false, config);

		// several more taproots
		buildBranchRing(world, trunkPlacer, leavesPlacer, random, pos, radius, 1, 2, 18, 0.9D, 3, 5, 3, false, config);

		// make a tree!

		// build the trunk
		buildTrunk(world, trunkPlacer, decorationPlacer, random, pos, radius, height, config);

		// build the crown
		buildTinyCrown(world, trunkPlacer, leavesPlacer, random, pos, radius, height, config);

		// add clock block
		BlockPos corePos = pos.offset(-1, 2, 0);
		BlockState stateAtCorePos = world.getBlockState(pos.above());
		if (stateAtCorePos.is(BlockTags.LOGS) || stateAtCorePos.canBeReplaced()) {
			world.setBlock(corePos, TFBlocks.TIME_LOG_CORE.get().defaultBlockState(), Block.UPDATE_ALL);
			world.scheduleTick(corePos, TFBlocks.TIME_LOG_CORE.get(), 20);
		}

		return true;
	}

@Override
    public InteractionResult useOn(UseOnContext context) {
        ItemStack itemStack = context.getItemInHand();
        Player player = context.getPlayer();
        if (player != null && player.isCreative()) {
            Level level = context.getLevel();
            if (!(level instanceof ServerLevel serverLevel)) {
                return InteractionResult.SUCCESS;
            } else {
                BlockPos blockPos = context.getClickedPos();
                Direction direction = context.getClickedFace();
                BlockState blockState = level.getBlockState(blockPos);
                if (blockState.is(Blocks.SPAWNER)) {
                    BlockEntity blockEntity = level.getBlockEntity(blockPos);
                    if (blockEntity instanceof SpawnerBlockEntity spawnerBlockEntity) {
                        BaseSpawnerAccessor baseSpawnerAccessor = (BaseSpawnerAccessor) spawnerBlockEntity.getSpawner();
                        EntityType<Moa> entityType = AetherEntityTypes.MOA.get();
                        spawnerBlockEntity.setEntityId(entityType, level.getRandom());
                        baseSpawnerAccessor.aether$getNextSpawnData().getEntityToSpawn().putString("MoaType", this.getMoaType().location().toString());
                        baseSpawnerAccessor.aether$getNextSpawnData().getEntityToSpawn().putBoolean("PlayerGrown", true); // Moas spawned from a Mob Spawner as set by a Moa Egg will always be tamed.
                        blockEntity.setChanged();
                        level.sendBlockUpdated(blockPos, blockState, blockState, 3);
                        itemStack.shrink(1);
                        return InteractionResult.CONSUME;
                    }
                }

                BlockPos relativePos;
                if (blockState.getCollisionShape(level, blockPos).isEmpty()) {
                    relativePos = blockPos;
                } else {
                    relativePos = blockPos.relative(direction);
                }

                if (AetherEntityTypes.MOA.get().spawn(serverLevel, this.getStackWithTags(serverLevel, itemStack, player, false, this.getMoaType(), false, true), relativePos, MobSpawnType.SPAWN_EGG, true, !Objects.equals(blockPos, relativePos) && direction == Direction.UP) != null) {
                    level.gameEvent(player, GameEvent.ENTITY_PLACE, blockPos);
                }
                return InteractionResult.CONSUME;
            }
        } else {
            return InteractionResult.FAIL;
        }
    }

@Override
    public boolean spawnAmbientParticle(ClientLevel level, BlockPos pos, Biome biome, EasyRandom random) {
        if (pos.getY() > 125)
            return true;

        if (pos.getY() >= 85) {
            final long gameTick = level.getGameTime();

            if (this.sandstorm != null) {
                if (level.getBrightness(LightLayer.SKY, pos) == 15) {
                    float intensity = this.sandstorm.getIntensity(gameTick);
                    float rotProgress = ((gameTick / 60f) % 360) * Mth.DEG_TO_RAD;
                    Vec3 angle = new Vec3(Math.cos(rotProgress), 0, Math.sin(rotProgress)).scale(Mth.sin(((gameTick / (gameTick % 1000 > 250 ? 20f : 1f)) % 360) * Mth.DEG_TO_RAD) * 0.4f * intensity + 0.9f);

                    ParticleBuilder.forPositions(EntityTrackingParticleOptions.ambient(AoAParticleTypes.SANDSTORM), Vec3.atLowerCornerOf(pos).add(random.nextDouble(), random.nextDouble(), random.nextDouble()))
                            .scaleMod(0.6f * intensity)
                            .lifespan(Mth.ceil(5 / random.valueBetween(0.2f, 1f)))
                            .colourTint(0xC4C0A1)
                            .velocity(angle)
                            .spawnClientParticles(level);
                }
            }
            else if (0.01f * 0.98572f > random.nextFloat()) {
                float rotProgress = ((gameTick / 60f) % 360) * Mth.DEG_TO_RAD;
                Vec3 angle = new Vec3(Math.cos(rotProgress), 0, Math.sin(rotProgress)).scale(Mth.sin(((gameTick / (gameTick % 1000 > 250 ? 20f : 1f)) % 360) * Mth.DEG_TO_RAD) * 0.3f);

                ParticleBuilder.forPositions(EntityTrackingParticleOptions.ambient(AoAParticleTypes.SANDSTORM), Vec3.atLowerCornerOf(pos).add(random.nextDouble(), random.nextDouble(), random.nextDouble()))
                        .scaleMod(0.3f)
                        .lifespan(Mth.ceil(10 / random.valueBetween(0.2f, 1f)))
                        .colourTint(0xC4C0A1)
                        .velocity(angle)
                        .spawnClientParticles(level);
            }
        }
        else if (0.1f * 0.98572f >= random.nextFloat()) {
            ParticleBuilder.forPositions(ParticleTypes.SMOKE, Vec3.atLowerCornerOf(pos).add(random.nextDouble(), random.nextDouble(), random.nextDouble()))
                    .lifespan(Mth.ceil(5 / random.valueBetween(0.2f, 1f)))
                    .velocity(0, 0.05f, 0)
                    .spawnClientParticles(level);
        }

        return true;
    }

@Override
    protected void tick() {
        Level world = getWorld();
        if (world.isClientSide) {
            BlockPos pos = getPos();

            for (int i = 0; i < 10; i++) {
                Vec3 particlePos = new Vec3(pos.getX(), pos.getY(), pos.getZ()).add(0.5, 0, 0.5);
                particlePos = particlePos.add(ParticleUtil.pointInSphere().multiply(5, 5, 5));
                world.addParticle(ParticleLineData.createData(getCenterColor()),
                        particlePos.x(), particlePos.y(), particlePos.z(),
                        pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5);
            }
        }
        if (world instanceof ServerLevel serverLevel && serverLevel.getGameTime() % 20 == 0) {
            if (isBookwyrms()) {
                int progress = getProgress();
                int numBookwyrms = getConsumedItems().stream().filter(i -> i.getItem() instanceof WritableBookItem).mapToInt(ItemStack::getCount).sum();
                if (progress < numBookwyrms) {
                    ItemStack charm = new ItemStack(ItemsRegistry.BOOKWYRM_CHARM);
                    ItemEntity itemEntity = new ItemEntity(serverLevel, getPos().getX() + 0.5, getPos().getY() + 1, getPos().getZ() + 0.5, charm);
                    float range = 0.1f;
                    itemEntity.setDeltaMovement(ParticleUtil.inRange(-range, range), ParticleUtil.inRange(0.4, 0.6), ParticleUtil.inRange(-range, range));
                    serverLevel.playSound(null, getPos(), SoundEvents.BOOK_PAGE_TURN, SoundSource.BLOCKS, 1.0F, 1.0F);
                    serverLevel.addFreshEntity(itemEntity);
                } else {
                    setFinished();
                }
            } else {
                if (getProgress() > 5) {
                    findTargets(serverLevel);
                    if (entity != null) {
                        ParticleUtil.spawnPoof(serverLevel, foundPos);
                        LivingEntity walker = entity.create(serverLevel);
                        walker.setPos(foundPos.getX() + 0.5, foundPos.getY(), foundPos.getZ() + 0.5);
                        serverLevel.addFreshEntity(walker);
                        setFinished();
                    }
                }
            }
            incrementProgress();
        }
    }

private void launchWitherSkull(Level world, Player player, boolean invulnerable) {
		world.levelEvent((Player) null, 1024, BlockPos.containing(player.position()), 0);

		Vector3 look = new Vector3(player.getLookAngle()).multiply(1, 0, 1);

		double playerRot = Math.toRadians(player.getYRot() + 90);
		if (look.x == 0 && look.z == 0) {
			look = new Vector3(Math.cos(playerRot), 0, Math.sin(playerRot));
		}

		look = look.normalize().multiply(-2);

		double div = -0.75 + (random.nextDouble() * 0.75);
		double mod = -0.5D + (random.nextDouble() * 6D);

		Vector3 pl = look.add(Vector3.fromEntityCenter(player)).add(0, 1.6, div * 0.1);

		Vector3 axis = look.normalize().crossProduct(new Vector3(-1, 0, -1)).normalize();

		double rot = mod * Math.PI / 4D - Math.PI / 2D;

		Vector3 axis1 = axis.multiply(div * 3.5D + 5D).rotate(rot, look);
		if (axis1.y < 0) {
			axis1 = axis1.multiply(1, -1, 1);
		}

		Vector3 end = pl.add(axis1);

		//end = end.add(0, -1, 0);\

		LivingEntity doomedOne = SuperpositionHandler.getObservedEntity(player, world, 3, 64);
		UltimateWitherSkullEntity witherskullentity = doomedOne != null ? new UltimateWitherSkullEntity(world, player, doomedOne) : new UltimateWitherSkullEntity(world, player);

		if (invulnerable) {
			witherskullentity.setSkullInvulnerable(true);
		}

		witherskullentity.setPos(end.x, end.y, end.z);

		world.addFreshEntity(witherskullentity);

		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(witherskullentity.getX(), witherskullentity.getY(), witherskullentity.getZ(), 64, witherskullentity.level().dimension())), new PacketWitherParticles(witherskullentity.getX(), witherskullentity.getY() + (witherskullentity.getBbHeight() / 2), witherskullentity.getZ(), 8, false));

	}

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level worldIn, LivingEntity entityLiving) {
		if (!(entityLiving instanceof Player))
			return stack;

		Player player = (Player) entityLiving;

		if (player instanceof ServerPlayer) {
			CriteriaTriggers.CONSUME_ITEM.trigger((ServerPlayer) player, stack);
		}

		Player receiver = this.getBoundPlayer(worldIn, stack);

		if (!worldIn.isClientSide && receiver != null) {

			Vec3 vec = receiver.position();

			while (vec.distanceTo(receiver.position()) < 1.0D) {
				vec = receiver.position().add((random.nextDouble() - 0.5D) * 4D, 0, (random.nextDouble() - 0.5D) * 4D);
			}

			worldIn.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 100, 1.25F, false));

			player.teleportTo(vec.x, vec.y + 0.25, vec.z);
			worldIn.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
		}

		if (!player.getAbilities().instabuild) {

			stack.shrink(1);

			if (stack.isEmpty())
				return new ItemStack(Items.GLASS_BOTTLE);

			player.getInventory().add(new ItemStack(Items.GLASS_BOTTLE));

		}

		return stack;
	}

private void earthquake() {
        boolean flag = false;
        List<LivingEntity> list = this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(6, 8, 6));
        for (LivingEntity e : list) {
            if (!(e instanceof EntityRockyRoller) && e.isAlive()) {
                e.addEffect(new MobEffectInstance(AMEffectRegistry.EARTHQUAKE.get(), 20, 0, false, false, true));
                flag = true;
            }
        }
        if (!this.level().canSeeSky(this.blockPosition()) && this.level().getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
            BlockPos ceil = this.blockPosition().offset(0, 2, 0);
            while ((!level().getBlockState(ceil).isSolid() || level().getBlockState(ceil).getBlock() == Blocks.POINTED_DRIPSTONE) && ceil.getY() < level().getMaxBuildHeight()) {
                ceil = ceil.above();
            }
            final int i = 2 + random.nextInt(2);
            final int j = 2 + random.nextInt(2);
            final int k = 2 + random.nextInt(2);
            final float f = (float) (i + j + k) * 0.333F + 0.5F;
            final double fTimesF = f * f;

            for (BlockPos blockpos1 : BlockPos.betweenClosed(ceil.offset(-i, -j, -k), ceil.offset(i, j, k))) {
                if (blockpos1.distSqr(ceil) <= fTimesF && level().getBlockState(blockpos1).getBlock() instanceof Fallable) {
                    if (isHangingDripstone(blockpos1)) {
                        while (isHangingDripstone(blockpos1.above()) && blockpos1.getY() < level().getMaxBuildHeight()) {
                            blockpos1 = blockpos1.above();
                        }
                        if (isHangingDripstone(blockpos1)) {
                            Vec3 vec3 = Vec3.atBottomCenterOf(blockpos1);
                            FallingBlockEntity fallingblockentity = FallingBlockEntity.fall(level(), new BlockPos((int) vec3.x, (int) vec3.y, (int) vec3.z), level().getBlockState(blockpos1));
                            this.level().destroyBlock(blockpos1, false);
                            this.level().addFreshEntity(fallingblockentity);
                        }
                    } else {
                        this.level().scheduleTick(blockpos1, level().getBlockState(blockpos1).getBlock(), 2);
                    }
                    flag = true;
                }
            }
        }
        if(flag){
            this.gameEvent(GameEvent.ENTITY_ROAR);
            this.playSound(AMSoundRegistry.ROCKY_ROLLER_EARTHQUAKE.get(), this.getSoundVolume(), this.getVoicePitch());
        }
    }

public List<BoltQuads> generate() {
        List<BoltQuads> quads = new ArrayList<>();
        Vec3 diff = end.subtract(start);
        float totalDistance = (float) diff.length();
        for (int i = 0; i < count; i++) {
            LinkedList<BoltInstructions> drawQueue = new LinkedList<>();
            drawQueue.add(new BoltInstructions(start, 0, new Vec3(0, 0, 0), null, false));
            while (!drawQueue.isEmpty()) {
                BoltInstructions data = drawQueue.poll();
                Vec3 perpendicularDist = data.perpendicularDist;
                float progress = data.progress + (1F / segments) * (1 - renderInfo.parallelNoise + random.nextFloat() * renderInfo.parallelNoise * 2);
                Vec3 segmentEnd;
                if (progress >= 1) {
                    segmentEnd = end;
                } else {
                    float segmentDiffScale = renderInfo.spreadFunction.getMaxSpread(progress);
                    float maxDiff = renderInfo.spreadFactor * segmentDiffScale * totalDistance * renderInfo.randomFunction.getRandom(random);
                    Vec3 randVec = findRandomOrthogonalVector(diff, random);
                    perpendicularDist = renderInfo.segmentSpreader.getSegmentAdd(perpendicularDist, randVec, maxDiff, segmentDiffScale, progress);
                    // new vector is original + current progress through segments + perpendicular change
                    segmentEnd = start.add(diff.scale(progress)).add(perpendicularDist);
                }
                float boltSize = size * (0.5F + (1 - progress) * 0.5F);
                Pair<BoltQuads, QuadCache> quadData = createQuads(data.cache, data.start, segmentEnd, boltSize);
                quads.add(quadData.getLeft());

                if (segmentEnd == end) {
                    break; // break if we've reached the defined end point
                } else if (!data.isBranch) {
                    // continue the bolt if this is the primary (non-branch) segment
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), false));
                } else if (random.nextFloat() < renderInfo.branchContinuationFactor) {
                    // branch continuation
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
                }

                while (random.nextFloat() < renderInfo.branchInitiationFactor * (1 - progress)) {
                    // branch initiation (probability decreases as progress increases)
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
                }
            }
        }
        return quads;
    }

@Override
	public void onUpdate() {
		if (!this.getEntityWorld().isRemote)
			if (getParentEntity() == null || getParentEntity().isDead)
				setDead();

		checkCollision();

		if (parent != null && !getExtending()) {
				returnToParent();
			if (getEntityBoundingBox().intersects(parent.getEntityBoundingBox())) {
				if (posX != parent.posX || posZ != parent.posZ)
					setPosition(parent.posX, parent.posY + parent.height * 0.5D, parent.posZ);
				motionX = 0D;
				motionY = 0D;
				motionZ = 0D;

				if (!getEntityWorld().isRemote) {
					if (isBeingRidden() && !parent.isBeingRidden()) {
						Entity entity = getPassengers().get(0);
						entity.startRiding(parent, true);
					}
					setDead();
					parent.setTendrilCount(parent.getTendrilCount() - 1);
				}
			}
		}

		if (parent != null && (!isBeingRidden() && ticksExisted > 20) || parent != null && collidedVertically) {
			if (!getEntityWorld().isRemote) {
				if (getExtending())
					setExtending(false);
			}
		}

		if(getEntityWorld().isRemote && getEntityWorld().getTotalWorldTime()%5 == 0)
			spawnDrips();

		move(MoverType.SELF, motionX, motionY, motionZ);
		motionX *= 1D;
		motionY *= 1D;
		motionZ *= 1D;
		super.onUpdate();
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		boolean isRSEnabled = state.rsState.isEnabled(context);
		boolean active = state.processor.tickServer(state, context.getLevel(), isRSEnabled);
		if(active!=state.active)
		{
			state.active = active;
			context.requestMasterBESync();
		}
		if(!context.getLevel().shouldTickModulo(16))
			return;
		if(!isRSEnabled||state.inventory.getStackInSlot(BLUEPRINT_SLOT).isEmpty())
			return;

		List<RecipeHolder<BlueprintCraftingRecipe>> recipes = getAvailableRecipes(context.getLevel().getRawLevel(), state);
		if(state.selectedRecipe >= 0&&state.selectedRecipe < recipes.size())
		{
			RecipeHolder<BlueprintCraftingRecipe> holder = recipes.get(state.selectedRecipe);
			BlueprintCraftingRecipe recipe = holder.value();
			if(!recipe.output.get().isEmpty())
			{
				NonNullList<ItemStack> query = NonNullList.withSize(NUM_INPUT_SLOTS, ItemStack.EMPTY);
				for(int i = 0; i < query.size(); i++)
					query.set(i, state.inventory.getStackInSlot(i+FIRST_INPUT_SLOT));
				int crafted = recipe.getMaxCrafted(query);
				if(crafted > 0&&state.processor.addProcessToQueue(
						new MultiblockProcessInWorld<>(holder, 0.78f, NonNullList.create()),
						context.getLevel().getRawLevel(),
						true
				))
				{
					state.processor.addProcessToQueue(
							new MultiblockProcessInWorld<>(holder, 0.78f, recipe.consumeInputs(query, 1)),
							context.getLevel().getRawLevel(),
							false
					);
					for(int i = 0; i < query.size(); i++)
						state.inventory.setStackInSlot(i+FIRST_INPUT_SLOT, query.get(i));
				}
			}
		}
	}

private void tickArrivalSound(CarriageContraption cc) {
		List<Carriage> carriages = carriage.train.carriages;

		if (arrivalSoundTicks == Integer.MIN_VALUE) {
			int carriageCount = carriages.size();
			Integer tick = null;

			for (int index = 0; index < carriageCount; index++) {
				int i = arrivalSoundReversed ? carriageCount - 1 - index : index;
				Carriage carriage = carriages.get(i);
				CarriageContraptionEntity entity = carriage.getDimensional(level()).entity.get();
				if (entity == null || !(entity.contraption instanceof CarriageContraption otherCC))
					break;
				tick = arrivalSoundReversed ? otherCC.soundQueue.lastTick() : otherCC.soundQueue.firstTick();
				if (tick != null)
					break;
			}

			if (tick == null) {
				arrivalSoundPlaying = false;
				return;
			}

			arrivalSoundTicks = tick;
		}

		if (tickCount % 2 == 0)
			return;

		boolean keepTicking = false;
		for (Carriage c : carriages) {
			CarriageContraptionEntity entity = c.getDimensional(level()).entity.get();
			if (entity == null || !(entity.contraption instanceof CarriageContraption otherCC))
				continue;
			keepTicking |= otherCC.soundQueue.tick(entity, arrivalSoundTicks, arrivalSoundReversed);
		}

		if (!keepTicking) {
			arrivalSoundPlaying = false;
			return;
		}

		arrivalSoundTicks += arrivalSoundReversed ? -1 : 1;
	}

private void renderGroup(Map<PhotonFXRenderPass, Queue<IParticle>> group, boolean late, boolean lastGroup) {
        activeGroup = group;
        lateLayer = late;
        beforeRendering();
        RenderSystem.setShader(GameRenderer::getParticleShader);
        RenderSystem.setShaderColor(1.0F, 1.0F, 1.0F, 1.0F);
        // the draw target was freshly prepared -> stale sampler. The late path has to set the flag
        // directly: markSceneSamplerDirty() deliberately swallows it there (see its javadoc), but
        // the first sample of a build still needs a fresh copy of the frame.
        if (late) {
            IS_SCENE_SAMPLER_DIRTY = true;
        } else {
            markSceneSamplerDirty();
        }

        // shaded sub-pass (DRAW and BOTH)
        if (drawMode != SceneView.DrawMode.WIREFRAME) {
            wireframeSubPass = false;
            renderQueuedPasses();
            // in place, the working copy is bent once every effect is on it; the late/after-pack paths bend at their composite
            if (!late && irisTarget == null) StackedDistortion.bend(DRAW_TARGET, depthOf(DRAW_TARGET));
        }
        // wireframe overlay sub-pass (WIREFRAME and BOTH): global polygon LINE mode + the inverse
        // material draws each mesh as inverted-color lines over the (optional) shaded pass.
        if (drawMode != SceneView.DrawMode.DRAW) {
            wireframeSubPass = true;
            GL30.glPolygonMode(GL30.GL_FRONT_AND_BACK, GL30.GL_LINE);
            GL30.glEnable(GL30.GL_POLYGON_OFFSET_LINE);
            GL30.glPolygonOffset(-1.0f, -1.0f);
            renderQueuedPasses();
            GL30.glPolygonOffset(0f, 0f);
            GL30.glDisable(GL30.GL_POLYGON_OFFSET_LINE);
            GL30.glPolygonMode(GL30.GL_FRONT_AND_BACK, GL30.GL_FILL);
            wireframeSubPass = false;
        }

        if (lastGroup) {
            activeGroup = particles;
            renderMaskSubPass();
            activeGroup = group;
        }

        afterRendering();
    }

