public List<BoltQuads> generate() {
        List<BoltQuads> quads = new ArrayList<>();
        Vec3 diff = end.subtract(start);
        float totalDistance = (float) diff.length();
        for (int i = 0; i < count; i++) {
            LinkedList<BoltInstructions> drawQueue = new LinkedList<>();
            drawQueue.add(new BoltInstructions(start, 0, new Vec3(0, 0, 0), null, false));
            while (!drawQueue.isEmpty()) {
                BoltInstructions data = drawQueue.poll();
                Vec3 perpendicularDist = data.perpendicularDist;
                float progress = data.progress + (1F / segments) * (1 - renderInfo.parallelNoise + random.nextFloat() * renderInfo.parallelNoise * 2);
                Vec3 segmentEnd;
                if (progress >= 1) {
                    segmentEnd = end;
                } else {
                    float segmentDiffScale = renderInfo.spreadFunction.getMaxSpread(progress);
                    float maxDiff = renderInfo.spreadFactor * segmentDiffScale * totalDistance * renderInfo.randomFunction.getRandom(random);
                    Vec3 randVec = findRandomOrthogonalVector(diff, random);
                    perpendicularDist = renderInfo.segmentSpreader.getSegmentAdd(perpendicularDist, randVec, maxDiff, segmentDiffScale, progress);
                    // new vector is original + current progress through segments + perpendicular change
                    segmentEnd = start.add(diff.scale(progress)).add(perpendicularDist);
                }
                float boltSize = size * (0.5F + (1 - progress) * 0.5F);
                Pair<BoltQuads, QuadCache> quadData = createQuads(data.cache, data.start, segmentEnd, boltSize);
                quads.add(quadData.getLeft());

                if (segmentEnd == end) {
                    break; // break if we've reached the defined end point
                } else if (!data.isBranch) {
                    // continue the bolt if this is the primary (non-branch) segment
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), false));
                } else if (random.nextFloat() < renderInfo.branchContinuationFactor) {
                    // branch continuation
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
                }

                while (random.nextFloat() < renderInfo.branchInitiationFactor * (1 - progress)) {
                    // branch initiation (probability decreases as progress increases)
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
                }
            }
        }
        return quads;
    }

public static void handle(MessageDragonControl message, Supplier<NetworkEvent.Context> context) {
            context.get().setPacketHandled(true);
            Player player = context.get().getSender();
            if(context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT){
                player = IceAndFire.PROXY.getClientSidePlayer();
            }
            if (player != null) {
                if (player.level != null) {
                    Entity entity = player.level.getEntity(message.dragonId);
                    if (ServerEvents.isRidingOrBeingRiddenBy(entity, player)) {
                        if (entity != null && entity instanceof EntityDragonBase) {
                            EntityDragonBase dragon = (EntityDragonBase) entity;
                            if (dragon.isOwnedBy(player)) {
                                dragon.setControlState(message.controlState);
                            }
                            // The riding setPos is performed in Entity#move
                            // Extra setPos will cause server side movement check to fail, resulting move wrongly msg
//                            dragon.setPos(message.getPosX(), message.getPosY(), message.getPosZ());
                        } else if (entity instanceof EntityHippogryph) {
                            EntityHippogryph hippo = (EntityHippogryph) entity;
                            if (hippo.isOwnedBy(player)) {
                                hippo.setControlState(message.controlState);
                            }
//                            hippo.setPos(message.getPosX(), message.getPosY(), message.getPosZ());
                        } else if (entity instanceof EntityHippocampus) {
                            EntityHippocampus hippo = (EntityHippocampus) entity;
                            if (hippo.isOwnedBy(player)) {
                                hippo.setControlState(message.controlState);
                            }
//                            hippo.setPos(message.getPosX(), message.getPosY(), message.getPosZ());
                        } else if (entity instanceof EntityDeathWorm) {
                            EntityDeathWorm deathworm = (EntityDeathWorm) entity;
                            deathworm.setControlState(message.controlState);
                            deathworm.setPos(message.getPosX(), message.getPosY(), message.getPosZ());
                        } else if (entity instanceof EntityAmphithere) {
                            EntityAmphithere amphi = (EntityAmphithere) entity;
                            if (amphi.isOwnedBy(player)) {
                                amphi.setControlState(message.controlState);
                            }
//                            amphi.setPos(message.getPosX(), message.getPosY(), message.getPosZ());
                        }
                    }
                }
            }
        }

@Override
	public void tickServer()
	{
		tickCommon();
		if(level.getGameTime()%64==((getBlockPos().getX()^getBlockPos().getZ())&63))
			markContainingBlockForUpdate(null);

		int energy = IEServerConfig.MACHINES.turret_consumption.get();
		if(isRSPowered()^config.redstoneControlInverted)
		{
			if(energyStorage.extractEnergy(energy, true)==energy)
			{
				energyStorage.extractEnergy(energy, false);
				if(target==null||!target.isAlive()||level.getEntity(target.getId())==null||target.getHealth() <= 0||!canShootEntity(target))
				{
					target = getTarget();
					if(target!=null)
					{
						this.setChanged();
						markContainingBlockForUpdate(null);
					}
				}

				//has target, Redstone control check and has power+ammo
				if(target!=null&&canActivate())
				{
					tick++;
					int chargeup = getChargeupTicks();
					if(tick==chargeup)
						this.activate();
					else if(tick > chargeup)
					{
						if(loopActivation())
							this.activate();
						else if(tick==chargeup+getActiveTicks())
							tick = 0;
					}
				}
				else
					tick = 0;
			}
		}
		else if(target!=null)
			target = null;
	}

@Override
	public int doHeatTick(int energyAvailable, boolean redstone)
	{
		long now = furnace.getLevel().getGameTime();
		if(now < blockedUntilGameTime)
			return 0;
		int energyConsumed = 0;
		boolean canCook = canCook();
		if(canCook||redstone)
		{
			ContainerData furnaceData = ((FurnaceTEAccess)furnace).getDataAccess();
			int burnTime = furnaceData.get(DATA_LIT_TIME);
			if(burnTime < FULLY_HEATED_LIT_TIME)
			{
				final int heatEnergyRatio = Math.max(1, ExternalHeaterHandler.defaultFurnaceEnergyCost);
				if(burnTime==0&&energyAvailable < heatEnergyRatio)
				{
					// Turn off completely for one second if furnace goes out due to insufficient power to prevent fast
					// on/off cycling on weak power sources
					blockedUntilGameTime = now+20;
					return 0;
				}
				int heatAttempt = Math.min(4, FULLY_HEATED_LIT_TIME-burnTime);
				int energyToUse = Math.min(energyAvailable, heatAttempt*heatEnergyRatio);
				int heat = energyToUse/heatEnergyRatio;
				if(heat > 0)
				{
					furnaceData.set(DATA_LIT_TIME, burnTime+heat);
					energyConsumed += heat*heatEnergyRatio;
					setFurnaceActive();
				}
			}
			// Speed up once fully charged
			if(canCook&&furnaceData.get(DATA_LIT_TIME) >= FULLY_HEATED_LIT_TIME&&furnaceData.get(DATA_COOKING_PROGRESS) < furnaceData.get(DATA_COOKING_TOTAL_TIME)-1)
			{
				int energyToUse = ExternalHeaterHandler.defaultFurnaceSpeedupCost;
				if(energyAvailable-energyConsumed > energyToUse)
				{
					energyConsumed += energyToUse;
					furnaceData.set(DATA_COOKING_PROGRESS, furnaceData.get(DATA_COOKING_PROGRESS)+1);
				}
			}
		}
		return energyConsumed;
	}

@Override
	public void read(CompoundTag nbt, HolderLookup.Provider registries, boolean clientPacket) {
		CompoundTag panelTag = nbt.getCompound(CreateLang.asId(slot.name()));
		if (panelTag.isEmpty()) {
			active = false;
			return;
		}

		active = true;
		filter = FilterItemStack.of(registries, panelTag.getCompound("Filter"));
		count = panelTag.getInt("FilterAmount");
		upTo = panelTag.getBoolean("UpTo");
		timer = panelTag.getInt("Timer");
		lastReportedLevelInStorage = panelTag.getInt("LastLevel");
		lastReportedPromises = panelTag.getInt("LastPromised");
		lastReportedUnloadedLinks = panelTag.getInt("LastUnloadedLinks");
		satisfied = panelTag.getBoolean("Satisfied");
		promisedSatisfied = panelTag.getBoolean("PromisedSatisfied");
		waitingForNetwork = panelTag.getBoolean("Waiting");
		redstonePowered = panelTag.getBoolean("RedstonePowered");
		promiseClearingInterval = panelTag.getInt("PromiseClearingInterval");
		if (panelTag.hasUUID("Freq"))
			network = panelTag.getUUID("Freq");

		targeting.clear();
