			});
			promisePrimedForMarkDirty = false;
		}
	}

public static void handle(PacketRandomize message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      var player = ctx.player();

      Level world = player.getCommandSenderWorld();
      ItemStack held = player.getItemInHand(message.hand);
      IEnergyStorage storage = CapabilityUtil.energy(held);
      final int cost = RandomizerItem.COST.get();
      if (storage == null || storage.extractEnergy(cost, true) < cost) {
        return;
      }
      List<BlockPos> places = RandomizerItem.getPlaces(message.pos, message.side, held);
      List<BlockPos> rpos = new ArrayList<BlockPos>();
      List<BlockState> rstates = new ArrayList<BlockState>();
      //
      BlockState stateHere;
      for (BlockPos p : places) {
        stateHere = world.getBlockState(p);
        boolean canMove = RandomizerItem.canMove(stateHere, world, p);

        if (canMove) {
          //removed world.isSideSolid(p, message.side) && as it was blocking stairs/slabs from moving
          rpos.add(p);
          rstates.add(stateHere);
        }
      }
      Collections.shuffle(rpos, RND);
      BlockPos swapPos;
      BlockState swapState;
      synchronized (rpos) { //just in case
        for (int i = 0; i < rpos.size(); i++) {
          if (storage.extractEnergy(cost, true) < cost) {
            break;
          }
          swapPos = rpos.get(i);
          swapState = rstates.get(i);
          world.destroyBlock(swapPos, false);
          //playing sound here in large areas causes ConcurrentModificationException
          if (BlockUtil.placeStateSafe(world, player, swapPos, swapState, false)) {
            storage.extractEnergy(cost, false);
          }
        }
      }
    });
  }

private void hitEntities(ServerPlayer player, ItemModularHandheld item, ItemStack itemStack, AABB aoe,
            double damageMultiplier, int revengeLevel, boolean overextend, int overextendLevel, double momentumEfficiency,
            AtomicInteger kills, AtomicInteger revengeKills, AtomicInteger hits) {
        Collection<LivingEntity> momentumTargets = new LinkedList<>();
        player.level().getEntitiesOfClass(LivingEntity.class, aoe).stream()
                .filter(entity -> entity != player)
                .filter(entity -> !player.isAlliedTo(entity))
                .forEach(entity -> {
                    double individualDamageMultiplier = damageMultiplier;

                    boolean canRevenge = revengeLevel > 0 && RevengeTracker.canRevenge(player, entity);
                    if (canRevenge) {
                        individualDamageMultiplier += revengeLevel / 100d;
                    }

                    if (overextend && entity.getHealth() / entity.getMaxHealth() >= overextendLevel / 100f) {
                        individualDamageMultiplier *= 2;
                    }

                    AbilityUseResult result = item.hitEntity(itemStack, player, entity, individualDamageMultiplier, 0.5f, 0.2f);
                    if (result != AbilityUseResult.fail) {
                        if (!entity.isAlive()) {
                            kills.incrementAndGet();

                            if (canRevenge) {
                                revengeKills.incrementAndGet();
                                RevengeTracker.removeEnemySynced(player, entity);
                            }
                        } else if (momentumEfficiency > 0) {
                            momentumTargets.add(entity);
                        }

                        hits.incrementAndGet();
                    }

                    if (result == AbilityUseResult.crit) {
                        player.getCommandSenderWorld().playSound(player, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 1.3f);
                    }
                });

        if (momentumEfficiency > 0 && kills.get() > 0) {
            int stunDuration = (int) (momentumEfficiency * kills.get() * 20);
            momentumTargets.forEach(entity -> entity.addEffect(new MobEffectInstance(StunPotionEffect.instance, stunDuration, 0, false, false)));
        }
    }

public boolean hurt(DamageSource p_31579_, float p_31580_) {
        if (!this.level.isClientSide && !this.isRemoved()) {
            if (p_31579_.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                this.kill();
                return false;
            } else if (!this.isInvulnerableTo(p_31579_) && !this.isInvisible() && !this.isMarker()) {
                if (p_31579_.is(DamageTypeTags.IS_EXPLOSION)) {
                    this.brokenByAnything(p_31579_);
                    this.kill();
                    return false;
                } else {
                    boolean flag = p_31579_.getDirectEntity() instanceof AbstractArrow;
                    boolean flag1 = flag && ((AbstractArrow)p_31579_.getDirectEntity()).getPierceLevel() > 0;
                    boolean flag2 = "player".equals(p_31579_.getMsgId());
                    if (!flag2 && !flag) {
                        return false;
                    } else if (p_31579_.getEntity() instanceof Player && !((Player)p_31579_.getEntity()).getAbilities().mayBuild) {
                        return false;
                    } else if (p_31579_.isCreativePlayer()) {
                        this.playBrokenSound();
                        this.showBreakingParticles();
                        this.kill();
                        return flag1;
                    } else {
                        long i = this.level.getGameTime();
                        if (i - this.lastHit > 5L && !flag) {
                            this.level.broadcastEntityEvent(this, (byte)32);
                            this.gameEvent(GameEvent.ENTITY_DAMAGE, p_31579_.getEntity());
                            this.lastHit = i;
                        } else {
                            this.brokenByPlayer(p_31579_);
                            this.showBreakingParticles();
                            this.kill();
                        }

                        return true;
                    }
                }
            } else {
                return false;
            }
        } else {
            return false;
        }
    }

private void tryIngestModifierItem() {
        if (applicatorStack == null || player == null) {
            return;
        }

        if (!modInputSlot.hasItem()) {
            if (lastIngestStart != -1) {
                lastIngestStart = -1;
                lastIngestModifier = null;
                lastIngestItem = null;
            }
            return;
        }

        if (lastIngestItem != null && lastIngestItem != modInputSlot.getItem().getItem()) {
            lastIngestStart = -1;
            lastIngestModifier = null;
            lastIngestItem = null;
        }

        long gameTime = player.level().getGameTime();
        if (lastIngestStart == -1) {
            lastIngestStart = gameTime;
            lastIngestModifier = FrameModifier.findMatching(modInputSlot.getItem());
            lastIngestItem = modInputSlot.getItem().getItem();
        }
        if (lastIngestModifier != null && (gameTime - lastIngestStart) % MOD_INGEST_INTERVAL == 0) {
            CamoApplicatorContent content = CamoApplicatorContent.of(applicatorStack);
            int modStackSize = content.getModifierStack(lastIngestModifier);
            if (modStackSize < CamoApplicatorContent.MODIFIER_MAX_STACK_SIZE) {
                int inputCount = modInputSlot.getItem().getCount();
                int space = CamoApplicatorContent.MODIFIER_MAX_STACK_SIZE - modStackSize;
                int ingestCount = Math.min(MOD_INGEST_SIZE, Math.min(inputCount, space));

                CamoApplicatorUtils.updateModifierInContent(applicatorStack, lastIngestModifier, ingestCount);
                modInputSlot.remove(ingestCount);
            }

            if (!modInputSlot.hasItem()) {
                lastIngestStart = -1;
                lastIngestModifier = null;
                lastIngestItem = null;
            }
        }
    }

@Override
    public void tick() {
        try {
            super.tick();
        } catch (NoClassDefFoundError error) {
            System.out.println("Starbuncle threaded pathing failed.");
            System.out.println(this);
            return;
        }
        if (this.dynamicBehavior != null) {
            this.dynamicBehavior.tick();
        }
        if (level.isClientSide && level.getGameTime() % 5 == 0) {
            this.canSleep = this.getBlockStateOn().is(BlockTagProvider.SUMMON_SLEEPABLE);
        }
        SummonUtil.healOverTime(this);
        if (!level.isClientSide && level.getGameTime() % 10 == 0 && this.getName().getString().toLowerCase(Locale.ROOT).equals("jeb_")) {
            this.entityData.set(COLOR, carbyColors[level.random.nextInt(carbyColors.length)]);
        }

        if (!level.isClientSide) {
            lastAABBCalc++;
            if (this.backOff > 0)
                this.backOff--;
            if (this.bedBackoff > 0) {
                this.bedBackoff--;
            }
        }
        if (!level.isClientSide && dynamicBehavior != null && level.getGameTime() % 100 == 0) {
            dynamicBehavior.syncTag();
        }
        if (this.dead)
            return;

        if (!level.isClientSide && !this.isPassenger() && this.getStarbuncleWithSpace() != null) {
            for (ItemEntity itementity : this.level.getEntitiesOfClass(ItemEntity.class, this.getBoundingBox().inflate(1))) {
                if (itementity.isAlive() && !itementity.getItem().isEmpty() && !itementity.hasPickUpDelay()) {
                    this.pickUpItem(itementity);
                    if (getHeldStack() != null && !getHeldStack().isEmpty())
                        break;
                }
            }
        }
        attemptTame();
    }

@Override
    public void submit(SacrificialBowlRenderState renderState, PoseStack poseStack, SubmitNodeCollector submitCollector, CameraRenderState cameraRenderState) {
        ItemStack stack = renderState.itemStack;
        ItemStackRenderState stackRenderState = renderState.itemStackRenderState;
        Direction facing = renderState.facing;
        long gameTime = renderState.gameTime;
        long lastChangeTime = renderState.lastChangeTime;

        if (stack == null || stack.isEmpty() || facing == null || gameTime == 0) {
            return;
        }

        poseStack.pushPose();
        poseStack.pushPose();

        // Calculate bobbing offset
        double offset = Math.sin((gameTime - lastChangeTime) / 16.0) * 0.5 + 0.5;
        offset = offset / 4.0;

        double fixedOffset = 0.2;

        double xOffset = facing.getAxis() == Direction.Axis.X ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;
        double yOffset = facing.getAxis() == Direction.Axis.Y ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;
        double zOffset = facing.getAxis() == Direction.Axis.Z ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;

        poseStack.translate(0.5 + xOffset, 0.5 + yOffset, 0.5 + zOffset);

        // Rotate item around Y axis using system time
        long systemTime = System.currentTimeMillis();
        float angle = (systemTime / 16) % 360;
        poseStack.mulPose(Axis.YP.rotationDegrees(angle));

        // Scale
        float scale = getScale(stack) * 0.5f;
        poseStack.scale(scale, scale, scale);

        // Render the item using the pre-created ItemStackRenderState
        stackRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);

        poseStack.popPose();

        poseStack.mulPose(facing.getRotation());

        poseStack.popPose();
    }

@Override
    protected InteractionResult useOnServerSide(UseOnContext context) {
        if (context.getLevel().getBlockState(context.getClickedPos()).is(OccultismTags.Blocks.CENTER_SACRIFICIAL_BOWL))
            return this.collectPentacle(context);

        if (context.getLevel().getBlockState(context.getClickedPos()).is(OccultismTags.Blocks.CHALK_GLYPHS)) {
            if (this.tryErase(context)) {
                return InteractionResult.SUCCESS;
            } else {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_NO_VALID_BRUSH_IN_SATCHEL).withStyle(ChatFormatting.YELLOW));
                return InteractionResult.FAIL;
            }
        }

        var targetPentacle = this.targetPentacles().get(context.getPlayer().getUUID());
        if (targetPentacle == null || targetPentacle.timeWhenAdded() < context.getLevel().getGameTime() - 5) {
            //no or outdated info
            return InteractionResult.FAIL;
        }

        if (!targetPentacle.target().equals(context.getClickedPos())) {
            //silent fail -> the player clicked at two blocks in quick succession, the second block did not send anything to the server as it is not a chalk block, so we ignore. Client side already sent an error message for that second click!
            return InteractionResult.FAIL;
        }

        var multiblock = ModonomiconAPI.get().getMultiblock(targetPentacle.multiblock());
        var simulation = multiblock.simulate(context.getLevel(), targetPentacle.anchor(), targetPentacle.facing(), false, false);

        boolean placedAnything = false;
        for (var targetMatcher : simulation.getSecond()) {
            var localContext = new UseOnContext(context.getPlayer(), context.getHand(),
                    new BlockHitResult(targetMatcher.worldPosition().getCenter(), context.getClickedFace(), targetMatcher.worldPosition().above(), false));
            if (this.tryPlaceBlockForMatcher(localContext, targetMatcher) == PlacementResult.SUCCESS) {
                placedAnything = true;
            }
        }

        if (!placedAnything) {
            context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_NO_VALID_ITEM_IN_SATCHEL).withStyle(ChatFormatting.YELLOW));
            return InteractionResult.FAIL;

        }

        return InteractionResult.SUCCESS;
    }

public void hitEntities() {
        List<LivingEntity> entitiesHit = getEntityLivingBaseNearby(RANGE, RANGE, RANGE, RANGE);;
        for (LivingEntity entityHit : entitiesHit) {
            float entityHitYaw = (float) ((Math.atan2(entityHit.getZ() - getZ(), entityHit.getX() - getX()) * (180 / Math.PI) - 90) % 360);
            float entityAttackingYaw = getYRot() % 360;
            if (entityHitYaw < 0) {
                entityHitYaw += 360;
            }
            if (entityAttackingYaw < 0) {
                entityAttackingYaw += 360;
            }
            float entityRelativeYaw = entityHitYaw - entityAttackingYaw;

            float xzDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()));
            double hitY = entityHit.getY() + entityHit.getBbHeight() / 2.0;
            float entityHitPitch = (float) ((Math.atan2((hitY - getY()), xzDistance) * (180 / Math.PI)) % 360);
            float entityAttackingPitch = -getXRot() % 360;
            if (entityHitPitch < 0) {
                entityHitPitch += 360;
            }
            if (entityAttackingPitch < 0) {
                entityAttackingPitch += 360;
            }
            float entityRelativePitch = entityHitPitch - entityAttackingPitch;

            float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()) + (hitY - getY()) * (hitY - getY()));
            int distance = this.tickCount / 2 ;
            boolean inRange = entityHitDistance <= distance + 1.0F;
            boolean yawCheck = (entityRelativeYaw <= ARC / 2f && entityRelativeYaw >= -ARC / 2f) || (entityRelativeYaw >= 360 - ARC / 2f || entityRelativeYaw <= -360 + ARC / 2f);
            boolean pitchCheck = (entityRelativePitch <= ARC / 2f && entityRelativePitch >= -ARC / 2f) || (entityRelativePitch >= 360 - ARC / 2f || entityRelativePitch <= -360 + ARC / 2f);
            boolean CloseCheck = caster instanceof Ignited_Revenant_Entity && entityHitDistance <= 2;
            if (inRange && yawCheck && pitchCheck || CloseCheck) {
                if (this.tickCount % 3 == 0) {
                    if (!isAlliedTo(entityHit) && entityHit != caster) {
                        boolean flag = entityHit.hurt(this.damageSources().indirectMagic(this, caster), this.getDamage());
                        if (flag) {
                            //entityHit.setDeltaMovement(entityHit.getDeltaMovement().multiply(0.25, 1, 0.25));
                            MobEffectInstance effectinstance = new MobEffectInstance(MobEffects.BLINDNESS, 60, 0, false, false, true);
                            entityHit.addEffect(effectinstance);
                        }
                    }
                }
            }
        }
    }

