                        nodeCollector.submitSpecial(RenderPhaseKeys.TRANSLUCENT_CUSTOM_GEOMETRY, new BoltFeatureRenderer.Submit(pose, boltState));
                    }
                    poseStack.popPose();
                }
            }
        }
    }

public List<BoltQuads> generate() {
        List<BoltQuads> quads = new ArrayList<>();
        Vector3fc diff = end.sub(start, new Vector3f());
        float totalDistance = diff.length();
        for (int i = 0; i < count; i++) {
            Queue<BoltInstructions> drawQueue = new LinkedList<>();
            drawQueue.add(new BoltInstructions(start, 0, new Vector3f(), null, false));
            while (!drawQueue.isEmpty()) {
                BoltInstructions data = drawQueue.poll();
                Vector3fc perpendicularDist = data.perpendicularDist;
                float progress = data.progress + (1F / segments) * (1 - renderInfo.parallelNoise + random.nextFloat() * renderInfo.parallelNoise * 2);
                Vector3fc segmentEnd;
                float segmentDiffScale = renderInfo.spreadFunction.getMaxSpread(progress);
                if (progress >= 1 && segmentDiffScale <= 0) {
                    segmentEnd = end;
                } else {
                    float maxDiff = renderInfo.spreadFactor * segmentDiffScale * totalDistance;
                    Vector3fc randVec = findRandomOrthogonalVector(diff, random);
                    float rand = renderInfo.randomFunction.getRandom(random);
                    perpendicularDist = renderInfo.segmentSpreader.getSegmentAdd(perpendicularDist, randVec, maxDiff, segmentDiffScale, progress, rand);
                    // new vector is original + current progress through segments + perpendicular change
                    segmentEnd = start.add(progress * diff.x(), progress * diff.y(), progress * diff.z(), new Vector3f()).add(perpendicularDist);
                }
                float boltSize = size * (0.5F + (1 - progress) * 0.5F);
                BoltQuadData quadData = createQuads(data.cache, data.start, segmentEnd, boltSize);
                quads.add(quadData.quads());

                if (progress >= 1) {
                    break; // break if we've reached the defined end point
                } else if (!data.isBranch) {
                    // continue the bolt if this is the primary (non-branch) segment
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.cache(), false));
                } else if (random.nextFloat() < renderInfo.branchContinuationFactor) {
                    // branch continuation
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.cache(), true));
                }

                while (random.nextFloat() < renderInfo.branchInitiationFactor * (1 - progress)) {
                    // branch initiation (probability decreases as progress increases)
                    drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.cache(), true));
                }
            }
        }
        return quads;
    }

private static List<RecipeDisplayEntry> loadLocalRecipeDisplays(RegistryAccess registryAccess, FeatureFlagSet enabledFeatures) {
        InternalLogger.getInstance().info("[Local Recipes] Loading recipes from client data packs...");
        List<RecipeDisplayEntry> entries = new ArrayList<>();

        // The SERVER_DATA pack stack the client could load locally: vanilla data plus every mod's
        // data pack. Gathering mod data packs is loader-specific, so it goes through the platform.
        List<PackResources> packs = PlatformAdapter.get().gatherClientDataPacks();

        try (MultiPackResourceManager dataManager = new MultiPackResourceManager(PackType.SERVER_DATA, packs)) {
            // Recipe ingredients reference tags from builtin registries (e.g. #minecraft:planks).
            // Bind those from the loaded packs so tag ingredients resolve while parsing.
            int tagCount = 0;
            for (Registry<?> registry : BuiltInRegistries.REGISTRY) {
                if (registry instanceof @SuppressWarnings({"unchecked", "rawtypes"})WritableRegistry writable) {
                    try {
                        TagLoader.loadTagsForRegistry(dataManager, writable);
                        tagCount++;
                    } catch (Exception e) {
                        // Some registries have no tag directories; skip silently.
                    }
                }
            }
            InternalLogger.getInstance().debug("[Local Recipes] Loaded tags for %d builtin registries", tagCount);

            List<Registry.PendingTags<?>> pendingTags = TagLoader.loadTagsForExistingRegistries(dataManager, registryAccess);
            for (Registry.PendingTags<?> pt : pendingTags) {
                pt.apply();
            }

            // Parse the recipes directly. This produces a RecipeManager holding the same
            // RecipeDisplayEntry objects (with self-consistent RecipeDisplayIds) that a dedicated
            // server would send through the recipe book.
            RecipeManager recipeManager = new RecipeManager(registryAccess);
            recipeManager.reload(new PreparableReloadListener.SharedState(dataManager), Runnable::run,
                    CompletableFuture::completedFuture, Runnable::run).join();
            // reload() only parses recipes; the recipe-display index is built separately by
            // finalizeRecipeLoading, exactly as the server does before sending the recipe book.
            recipeManager.finalizeRecipeLoading(enabledFeatures);

            recipeManager.getRecipes().forEach(holder ->
                    recipeManager.listDisplaysForRecipe(holder.id(), entries::add));
        }
        InternalLogger.getInstance().info("[Local Recipes] Built %d local recipe displays", entries.size());
        return entries;
    }

@Override
			public float unclampedCall(ItemStack stack, @Nullable ClientLevel level, @Nullable LivingEntity living, int seed) {
				Entity entity = living != null ? living : stack.getEntityRepresentation();

				if (entity == null)
					return 0.0F;
				else {
					if (level == null && entity.level() instanceof ClientLevel) {
						level = (ClientLevel) entity.level();
					}

					assert level != null;

					BlockPos target = this.getTargetPosition();
					long gameTime = level.getGameTime();

					if (target != null && !(entity.position().distanceToSqr(target.getX() + 0.5D, entity.position().y(), target.getZ() + 0.5D) < 1.0E-5F)) {
						boolean isLocalPlayer = living instanceof Player && ((Player)living).isLocalPlayer();
						double bodyRotation = 0.0D;

						if (isLocalPlayer) {
							assert living != null;
							bodyRotation = living.getYRot();
						} else
							return this.randomAngle(gameTime, seed);

						if (!SuperpositionHandler.isTheCursedOne((Player) living)
								|| !SuperpositionHandler.hasExactStack((Player) living, stack)
								|| level.getBiome(living.blockPosition()).is(Biomes.SOUL_SAND_VALLEY))
							return this.randomAngle(gameTime, seed);

						bodyRotation = Mth.positiveModulo(bodyRotation / 360.0D, 1.0D);
						double angle = SoulCompass.this.getAngleTo(Vec3.atCenterOf(target), entity) / ((float)Math.PI * 2F);
						double otherAngle;

						if (this.wobble.shouldUpdate(gameTime)) {
							this.wobble.update(gameTime, 0.5D - (bodyRotation - 0.25D));
						}

						otherAngle = angle + this.wobble.rotation;

						return Mth.positiveModulo((float)otherAngle, 1.0F);
					} else
						return this.randomAngle(gameTime, seed);
				}
			}

@Override
    public void onUpdate() {
    	super.onUpdate();
    	renderYawOffset = rotationYaw;
		double a = Math.toRadians(rotationYaw);
		double offSetX = -Math.sin(a) * 1.5D;
		double offSetZ = Math.cos(a) * 1.5D;
		tailPart[0].setLocationAndAngles(posX - offSetX, posY, posZ - offSetZ, 0.0F, 0.0F);

		if (getEntityWorld().getTotalWorldTime()%5 == 0)
			if (getEntityWorld().isRemote)
				flameParticles(getEntityWorld(), tailPart[0].posX, tailPart[0].posY + 0.25, tailPart[0].posZ, rand);

		checkCollision();

		if (getEntityWorld().isRemote) {
			if (getIsCastingSpell()) {
				prevAnimationTicks = animationTicks;

				if (animationTicks <= 1F)
					animationTicks += 0.1F;

			}
			if (!getIsCastingSpell()) {
				prevAnimationTicks = animationTicks;

				if (animationTicks >= 0.1F)
					animationTicks -= 0.1F;

				if (animationTicks < 0F)
					animationTicks = 0F;
			}
		}
		if (!getEntityWorld().isRemote && recentlyHit > 40)
			if(getIsCastingSpell())
				setIsCastingSpell(false);

		if (getEntityWorld().isRemote) {
			if(rand.nextInt(4) == 0) {
				ParticleArgs<?> args = ParticleArgs.get().withDataBuilder().setData(2, this).buildData();
					args.withColor(1F, 1F, 1F, 1F);
					args.withScale(0.75F + rand.nextFloat() * 0.75F);
				BLParticles.EMBER_SWIRL.spawn(getEntityWorld(), posX, posY, posZ, args);
			}
		}
    }

private void hitWaves(double pow) {
        // TODO: custom smooth sync total world time
        double t = world.getTotalWorldTime() * 0.03;
        double roughness = 0.15 * pow * (inWaterTicks < 20 ? inWaterTicks / 20D : 1), scale = 0.5;
        double x = posX, z = posZ;
        Matrix mat = new Matrix();
        mat.rotate(rotation);
        mat.rotate(-rotationYaw * MathUtils.DEG_TO_RAD, 0, 1, 0);
        Vec3d posFront = mat.transform(new Vec3d(0, 0, 0.75));
        Vec3d posStarboard = mat.transform(new Vec3d(0.435, 0, -0.5));
        Vec3d posPort = mat.transform(new Vec3d(-0.435, 0, 0.5));
        double sx0 = posFront.x;
        double sz0 = posFront.z;
        double sx1 = posStarboard.x;
        double sz1 = posStarboard.z;
        double sx2 = posPort.x;
        double sz2 = posPort.z;
        double sy0 = WAVE_RNG.eval((x + sx0) * scale, t, (z + sz0) * scale) * roughness;
        double sy1 = WAVE_RNG.eval((x + sx1) * scale, t, (z + sz1) * scale) * roughness;
        double sy2 = WAVE_RNG.eval((x + sx2) * scale, t, (z + sz2) * scale) * roughness;
        Vec3d s0 = new Vec3d(sx0 * scale, sy0, sz0 * scale);
        Vec3d s1 = new Vec3d(sx1 * scale, sy1, sz1 * scale);
        Vec3d s2 = new Vec3d(sx2 * scale, sy2, sz2 * scale);
        Vec3d normal = s2.subtract(s1).crossProduct(s0.subtract(s1)).normalize();
        Vec3d yAxis = new Vec3d(0, 1, 0);
        double angle = Math.acos(Math.max(Math.min(normal.dotProduct(yAxis), 1), -1));
        Vec3d axis = normal.crossProduct(yAxis).normalize();
        Quat wave = Quat.fromAxisAngle(axis.x, axis.y, axis.z, -angle * 0.4);
        rotation.interpolate(wave, 0.2);
        Vec3d point = new Vec3d(0, roughness, 0);
        waveHeight = point.subtract(normal.scale(point.subtract(s0).dotProduct(normal))).y; 
        pullOarByWave(ShipSide.STARBOARD, normal);
        pullOarByWave(ShipSide.PORT, normal);
        if (!isTarred() && canPassengerSteer()) {
            double wx = normal.x;
            double wz = normal.z;
            double mag = Math.sqrt(wx * wx + wz * wz);
            double strength = mag / Math.min(((1 - normal.y) * 1.8 * roughness), 0.00125);
            if (strength > 0) {
                motionX += wx / strength;
                motionZ += wz / strength;
                double dir = Math.atan2(wz, wx) * MathUtils.RAD_TO_DEG;
                rotationalVelocity += Math.signum(MathUtils.modularDelta(rotationYaw, dir - 90, 360)) * Math.min((1 - normal.y) * 60 * roughness, roughness);   
            }
        }
    }

private void tickQueue(PriorityQueue<TickTracker> queue) {
        TickTracker tt;

        while (!queue.isEmpty()) {
            // Peek and stop once it reaches a TickTracker running at a later tick
            tt = queue.peek();
            if (tt.getNextTick() > this.currentTick) {
                break;
            }

            if (queue.poll() != tt) {
                throw new IllegalStateException();
            }
            var diff = (int) (this.currentTick - tt.getLastTick());
            currentlyTicking = tt.getNode();
            TickRateModulation mod;
            try {
                mod = this.unsafeTickingRequest(tt, diff);
            } finally {
                currentlyTicking = null;
            }

            // Update the last time this node was ticked
            tt.setLastTick(this.currentTick);

            var newRate = switch (mod) {
                case URGENT -> tt.getRequest().minTickRate();
                case FASTER -> tt.getCurrentRate() - TICK_RATE_SPEED_UP_FACTOR;
                case IDLE, SLEEP -> tt.getRequest().maxTickRate();
                case SLOWER -> tt.getCurrentRate() + TICK_RATE_SLOW_DOWN_FACTOR;
                case SAME -> tt.getCurrentRate();
            };
            // This will clamp to the min,max range
            tt.setCurrentRate(newRate);

            if (mod == TickRateModulation.SLEEP) {
                sleepDevice(tt.getNode());
            } else {
                // Note that the node _may_ have been removed entirely from the grid in its own tick
                if (this.awake.containsKey(tt.getNode())) {
                    // Queue already known, no need to use addToQueue() to resolve it again.
                    queue.add(tt);
                }
            }
        }
    }

@SubscribeEvent
        public static void initRegistries(FMLConstructModEvent event)
        {
            event.enqueueWork(() ->
            {
                if (REGISTRIES_INITIALIZED) return;

                ColdSweat.LOGGER.info("Gathering Cold Sweat registries");
                // Gather modded registries
                AddRegistriesEvent addRegistriesEvent = new AddRegistriesEvent();

                // Check if the event bus is closed
                boolean busWasClosed = !MinecraftForge.EVENT_BUS.post(new ProbeEventBusEvent());
                // Start the event bus temporarily
                MinecraftForge.EVENT_BUS.start();
                // Post AddRegistriesEvent to the event bus
                MinecraftForge.EVENT_BUS.post(addRegistriesEvent);
                // Re-close the event bus if it was closed before
                if (busWasClosed)
                {
                    ColdSweat.LOGGER.info("The event bus was started early to gather Cold Sweat registries; it will now be stopped again until the correct loading phase.");
                    try
                    {   Field shutdown = EventBus.class.getDeclaredField("shutdown");
                        shutdown.setAccessible(true);
                        shutdown.set(MinecraftForge.EVENT_BUS, true);
                    }
                    catch (Exception e)
                    {   ColdSweat.LOGGER.error("Failed to re-shutdown the event bus after gathering Cold Sweat registries", e);
                    }
                }

                // Add registries via dummy NewRegistry event
                DataPackRegistryEvent.NewRegistry dummyEvent = new DataPackRegistryEvent.NewRegistry();
                for (RegistryHolder holder : ModRegistries.getRegistries().values())
                {   dummyEvent.dataPackRegistry(holder.key(), holder.codec(), holder.codec());
                }
                try
                {   Method process = DataPackRegistryEvent.NewRegistry.class.getDeclaredMethod("process");
                    process.setAccessible(true);
                    process.invoke(dummyEvent);
                }
                catch (Exception ignored) {}

                REGISTRIES_INITIALIZED = true;
            });
        }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            if (ctx.player().level().isClientSide())
                return;

            ServerPlayer player = (ServerPlayer) ctx.player();

            if (player.containerMenu.containerId != container) {
                causeError(player);

                return;
            }

            ItemStack stack = DescriptionUtils.gatherRelicStack(player, slot);

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                causeError(player);

                return;
            }

            RandomSource random = player.getRandom();

            switch (operation) {
                case ADD -> {
                    relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().addLink(from, to);

                    if (relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().isComplete()) {
                        relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().setResearched(true);

                        player.connection.send(new ClientboundSoundPacket(Holder.direct(RelicsSounds.FINISH_RESEARCH.get()), SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 0.75F, 1F, random.nextLong()));
                    } else
                        player.connection.send(new ClientboundSoundPacket(Holder.direct(RelicsSounds.CONNECT_STARS.get()), SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 0.75F, 0.75F + random.nextFloat() * 0.5F, random.nextLong()));
                }
                case REMOVE -> relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().removeLink(from, to);
            }

            try {
                player.containerMenu.getSlot(slot).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                causeError(player);
            }
        });
    }

public static boolean completeCraft(ServerLevel level, Player player, Container inventory, ItemStack result) {
		Optional<Inputs> liveInputs = getInputs(inventory.getContainerSize(), inventory::getItem);
		EnderLinkPendingCraftData pendingCraft = result.get(ModCoreDataComponents.ENDER_LINK_PENDING_CRAFT);
		EnderLinkPendingCraftPlan plan = pendingCraft == null ? liveInputs.map(Inputs::plan).orElse(null) : pendingCraft.plan();
		if (plan == null) {
			return false;
		}
		InFlightClaim claim = findInFlightClaim(player, pendingCraft, plan);
		if (claim == null) {
			return false;
		}
		if (liveInputs.isEmpty() || liveInputs.get().plan() != plan) {
			return false;
		}
		Inputs inputs = liveInputs.get();
		LinkedStorageEndpointData endpointData;
		if (plan == EnderLinkPendingCraftPlan.CREATE_PRIMARY) {
			if (!LinkedStorageService.link(level, player.getUUID(), inputs.linker().copyWithCount(1), inputs.endpoint())) {
				return false;
			}
			endpointData = inputs.endpoint().get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		} else if (plan == EnderLinkPendingCraftPlan.BIND_EXISTING_ENDPOINT) {
			endpointData = inputs.endpoint().get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		} else {
			if (LinkedStorageStackLifecycle.classifyLinker(inputs.linker()) == EnderLinkerStackState.PENDING_CRAFT
					&& !finalizePendingCraftLinker(level, inputs.linker())) {
				return false;
			}
			ItemStack endpoint = inputs.endpoint().copyWithCount(1);
			if (!LinkedStorageService.link(level, inputs.linker().copyWithCount(1), endpoint)) {
				return false;
			}
			endpointData = endpoint.get(ModCoreDataComponents.LINKED_STORAGE_ENDPOINT);
		}
		LinkedStorageGroupsSavedData.get(level).manager()
				.activatePendingCraftClaim(new ActivePendingCraftClaim(claim.claimId(), endpointData.groupId(), endpointData.endpointId(), inputs.plan()));
		IN_FLIGHT_CLAIMS.remove(claim.claimId());
		Map<EnderLinkPendingCraftPlan, UUID> latestClaims = LATEST_IN_FLIGHT_CLAIMS.get(player.getUUID());
		if (latestClaims != null) {
			latestClaims.remove(plan, claim.claimId());
			if (latestClaims.isEmpty()) {
				LATEST_IN_FLIGHT_CLAIMS.remove(player.getUUID());
			}
		}
		return true;
	}

@Override
    public InteractionResult useOn(UseOnContext ctx) {
        ItemStack stack = ctx.getItemInHand();
        Level level = ctx.getLevel();
        if (!level.isClientSide()) {
            Player player = ctx.getPlayer();
            BlockPos blockPos = ctx.getClickedPos();
            BlockState blockState = level.getBlockState(blockPos);
            if (!blockState.getShape(level, blockPos).isEmpty()) {
                blockPos = blockPos.relative(ctx.getClickedFace());
            }
            List<GlobalPos> list = getList(stack);
            GlobalPos entry = GlobalPos.of(level.dimension(), blockPos);
            if (!list.isEmpty()) {
                GlobalPos last = list.get(list.size() - 1);
                if (!entry.dimension().equals(last.dimension())) {
                    if (player != null) {
                        player.displayClientMessage(Component.translatable("info.goety.patrol.dimension"), true);
                    }
                    return InteractionResult.FAIL;
                }
                if (!list.contains(entry) && entry.pos().distSqr(last.pos()) > 256) {
                    if (player != null) {
                        player.displayClientMessage(Component.translatable("info.goety.patrol.distance"), true);
                    }
                    return InteractionResult.FAIL;
                }
            }
            if (togglePos(stack, entry)) {
                if (player != null) {
                    player.displayClientMessage(Component.translatable("info.goety.patrol.add"), true);
                    if (!level.isClientSide) {
                        ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.BOOK_PAGE_TURN, 1.0F, 1.0F));
                    }
                }
            } else {
                if (player != null) {
                    player.displayClientMessage(Component.translatable("info.goety.patrol.remove"), true);
                    if (!level.isClientSide) {
                        ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.BOOK_PAGE_TURN, 1.0F, 0.5F));
                    }
                }
            }
        }
        return InteractionResult.SUCCESS;
    }

@Override
    public boolean isValid(Level world, BlockPos darkAltarPos, DarkAltarBlockEntity tileEntity,
                           Player castingPlayer, ItemStack activationItem,
                           List<Ingredient> remainingAdditionalIngredients) {
        if (world instanceof ServerLevel serverLevel) {
            if (this.recipe.getStructureTag() == null) {
                return false;
            }
            if (!this.areAdditionalIngredientsFulfilled(world, darkAltarPos, castingPlayer, remainingAdditionalIngredients)) {
                return false;
            }

            if (tileEntity.findStructurePos != null) {
                return true;
            }

            if (tileEntity.structureSearchFailed) {
                castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.location.fail"), true);
                tileEntity.structureSearchFailed = false;
                return false;
            }

            if (tileEntity.pendingStructureSearch != null) {
                if (!tileEntity.pendingStructureSearch.isDone()) {
                    return true;
                }
                BlockPos result = tileEntity.pendingStructureSearch.getNow(null);
                tileEntity.pendingStructureSearch = null;
                if (result != null) {
                    tileEntity.findStructurePos = result;
                } else {
                    tileEntity.structureSearchFailed = true;
                }
                return true;
            }
            final TagKey<Structure> structureTag = this.recipe.getStructureTag();
            final BlockPos searchCenter = darkAltarPos;

            tileEntity.pendingStructureSearch = CompletableFuture.supplyAsync(() ->
                    serverLevel.findNearestMapStructure(structureTag, searchCenter, 100, true)
            );

            return true;
        }
        return false;
    }

private void computeBoxProgress(Accessor<?> accessor, float partialTicks) {
		BoxProgress current = null;
		for (PrioritizedProvider entry : providers) {
			BoxProgress progress = entry.provider().getProgress(this, accessor, partialTicks);
			if (progress != null) {
				current = progress;
				break;
			}
		}
		if (current != null) {
			fadeProgress = current;
			fadeAlpha = current.alpha();
			pendingProgress = current;
			BoxProgressFadeTrackInfo track = getFadeTrack(true);
			if (track != null) {
				track.progress = fadeProgress;
				track.alpha = fadeAlpha;
				track.touch();
			}
			return;
		}
		BoxProgressFadeTrackInfo track = getFadeTrack(false);
		if (track != null && fadeProgress == null) {
			fadeProgress = track.progress;
			fadeAlpha = track.alpha;
		}
		if (fadeProgress == null) {
			pendingProgress = null;
			return;
		}
		fadeAlpha -= Minecraft.getInstance().getDeltaTracker().getGameTimeDeltaTicks() * 0.1F;
		if (fadeAlpha <= 0) {
			fadeAlpha = 0;
			fadeProgress = null;
			pendingProgress = null;
		} else {
			pendingProgress = new BoxProgress(fadeProgress.progress(), fadeProgress.type(), fadeProgress.color(), fadeAlpha);
		}
		if (track != null) {
			track.progress = fadeProgress;
			track.alpha = fadeAlpha;
			if (fadeProgress != null) {
				track.touch();
			}
		}
	}

public void updateActions(ServerLevel level, T entity, Brain<T> brain, Map<Activity, Collection<Action<T>>> actionsByActivity) {
        if (brain.hasMemoryValue(ModMemoryTypes.ACTION_ACTIVE.get())) {
            Optional<Long> actionActiveSince = brain.getMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get());

            if (actionActiveSince.isEmpty()) {
                brain.setMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get(), level.getGameTime());
                return;
            }

            if (level.getGameTime() - actionActiveSince.get() < 40) {
                return;
            }

            if (actionsByActivity.values().stream().flatMap(Collection::stream).map(Action::activity).noneMatch(brain::isActive)) {
                brain.eraseMemory(ModMemoryTypes.ACTION_ACTIVE.get());
                brain.eraseMemory(ModMemoryTypes.ACTION_COOLDOWN.get());
                brain.eraseMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get());
            }
        } else if (!brain.hasMemoryValue(ModMemoryTypes.ACTION_COOLDOWN.get())) {
            var activity = brain.getActiveNonCoreActivity().orElse(null);
            if (activity == null || activity == Activity.IDLE) return;
            var actionsSource = actionsByActivity.get(activity);
            if (actionsSource == null) return;
            ArrayList<Action<T>> actions = new ArrayList<>(actionsSource);
            Collections.shuffle(actions);

            for (Action<T> action : actions) {
                if (brain.hasMemoryValue(action.cooldownMemory().memory())) {
                    continue;
                }

                if (!action.precondition().test(level, entity)) {
                    continue;
                }

                if (!action.requirements().stream().allMatch(pair -> brain.checkMemory(pair.getFirst(), pair.getSecond()))) {
                    continue;
                }

                brain.setMemory(ModMemoryTypes.ACTION_ACTIVE.get(), Unit.INSTANCE);
                brain.setMemory(action.activeMemory(), Unit.INSTANCE);
                brain.setMemory(ModMemoryTypes.ACTION_ACTIVE_SINCE.get(), level.getGameTime());
                return;
            }
        }
    }

public static void tick(Level level, BlockPos pos, BlockState state, CarminiteBuilderBlockEntity te) {
		if (!level.isClientSide() && te.makingBlocks) {
			// if we are not tracking the nearest player, start tracking them
			if (te.trackedPlayer == null) {
				te.trackedPlayer = te.findClosestValidPlayer();
			}

			// find player facing
			Direction nextFacing = te.findNextFacing();

			++te.ticksRunning;

			// if we are at the half second marker, make a block and advance the block cursor
			if (te.ticksRunning % 10 == 0 && te.lastBlockCoords != null && nextFacing != null) {
				BlockPos nextPos = te.lastBlockCoords.relative(nextFacing);

				// make a block
				if (te.blocksMade <= RANGE && level.isEmptyBlock(nextPos)) {
					level.setBlock(nextPos, te.blockBuiltState, Block.UPDATE_ALL);

					level.playSound(null, pos, TFSounds.BUILDER_CREATE.get(), SoundSource.BLOCKS, 0.75F, 1.2F);

					te.lastBlockCoords = nextPos;

					te.blockedCounter = 0;
					te.blocksMade++;
				} else {
					te.blockedCounter++;
				}
			}

			// if we're blocked for more than a second, shut down block making
			if (te.blockedCounter > 0) {
				te.makingBlocks = false;
				te.trackedPlayer = null;
				te.ticksStopped = 0;
			}
		} else if (!level.isClientSide() && !te.makingBlocks) {
			te.trackedPlayer = null;
			if (++te.ticksStopped == 60) {
				// force the builder back into an inactive state
				level.setBlockAndUpdate(pos, state.setValue(BuilderBlock.STATE, TowerDeviceVariant.BUILDER_TIMEOUT));
				level.scheduleTick(pos, state.getBlock(), 4);
			}
		}
	}

