@Override
  public List<SlotResult> findCurios(Predicate<ItemStack> filter, boolean includeInactive,
                                     String cacheKey) {
    // Check cached value first
    long gameTime = this.livingEntity.level().getGameTime();
    Cache<String, Pair<Long, List<SlotResult>>> cache = this.curioInventory.findCuriosCache;

    if (!cacheKey.isEmpty()) {
      Pair<Long, List<SlotResult>> cached = cache.getIfPresent(cacheKey);

      if (cached != null && cached.getFirst() == gameTime) {
        return cached.getSecond();
      }
    }
    List<SlotResult> result = new ArrayList<>();
    Map<String, ICurioStacksHandler> curios = this.getCurios();

    for (String id : curios.keySet()) {
      ICurioStacksHandler stacksHandler = curios.get(id);
      IDynamicStackHandler stackHandler = stacksHandler.getStacks();
      NonNullList<Boolean> activeStates = stacksHandler.getActiveStates();

      for (int i = 0; i < stackHandler.getSlots(); i++) {

        if (!includeInactive && activeStates.size() > i && !activeStates.get(i)) {
          continue;
        }
        ItemStack stack = stackHandler.getStackInSlot(i);

        if (!stack.isEmpty() && filter.test(stack)) {
          NonNullList<Boolean> renderStates = stacksHandler.getRenders();
          result.add(
              new SlotResult(
                  new SlotContext(
                      id,
                      this.livingEntity,
                      i,
                      false,
                      renderStates.size() > i && renderStates.get(i)),
                  stack));
        }
      }
    }
    cache.put(cacheKey, Pair.of(gameTime, result));
    return result;
  }

public List<BoltQuads> generate() {
		Random random = new Random();
		List<BoltQuads> quads = new ArrayList<>();
		Vec3 diff = end.subtract(start);
		float totalDistance = (float) diff.length();
		for (int i = 0; i < count; i++) {
			Queue<BoltInstructions> drawQueue = new ArrayDeque<>();
			drawQueue.add(new BoltInstructions(start, 0, Vec3.ZERO, null, false));
			while (!drawQueue.isEmpty()) {
				BoltInstructions data = drawQueue.poll();
				Vec3 perpendicularDist = data.perpendicularDist();
				float progress = data.progress() + (1F / segments) * (1 - renderInfo.parallelNoise + random.nextFloat() * renderInfo.parallelNoise * 2);
				Vec3 segmentEnd;
				float segmentDiffScale = renderInfo.spreadFunction.getMaxSpread(progress);
				if (progress >= 1 && segmentDiffScale <= 0) {
					segmentEnd = end;
				} else {
					float maxDiff = renderInfo.spreadFactor * segmentDiffScale * totalDistance;
					Vec3 randVec = findRandomOrthogonalVector(diff, random);
					double rand = renderInfo.randomFunction.getRandom(random);
					perpendicularDist = renderInfo.segmentSpreader.getSegmentAdd(perpendicularDist, randVec, maxDiff, segmentDiffScale, progress, rand);
					// new vector is original + current progress through segments + perpendicular change
					segmentEnd = start.add(diff.scale(progress)).add(perpendicularDist);
				}
				float boltSize = size * (0.5F + (1 - progress) * 0.5F);
				Pair<BoltQuads, QuadCache> quadData = createQuads(data.cache(), data.start(), segmentEnd, boltSize);
				quads.add(quadData.getLeft());

				if (progress >= 1) {
					break; // break if we've reached the defined end point
				} else if (!data.isBranch()) {
					// continue the bolt if this is the primary (non-branch) segment
					drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), false));
				} else if (random.nextFloat() < renderInfo.branchContinuationFactor) {
					// branch continuation
					drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
				}

				while (random.nextFloat() < renderInfo.branchInitiationFactor * (1 - progress)) {
					// branch initiation (probability decreases as progress increases)
					drawQueue.add(new BoltInstructions(segmentEnd, progress, perpendicularDist, quadData.getRight(), true));
				}
			}
		}
		return quads;
	}

@Override
    public void tick() {
        super.tick();
        SummonUtil.healOverTime(this);
        if (!this.level.isClientSide) {
            if (!this.isRemoved() && !this.isTamed()) {
                Whirlisprig.WHIRLI_MAP.addEntity(level, this.getUUID());
            }
            if (level.getGameTime() % 20 == 0 && this.blockPosition().getY() < this.level.getMinBuildHeight()) {
                this.remove(RemovalReason.DISCARDED);
                return;
            }

            this.timeSinceBonemeal++;
            this.timeSinceGen++;
            if (level.getGameTime() % 20 == 0 && flowerPos != null && isTamed() && getTile() != null) {
                this.entityData.set(MOOD_SCORE, getTile().moodScore);
                this.diversityScore = getTile().diversityScore;
            }
        }

        if (!level.isClientSide && level.getGameTime() % 60 == 0 && isTamed() && flowerPos != null && !(level.getBlockEntity(flowerPos) instanceof WhirlisprigTile)) {
            this.hurt(level.damageSources().playerAttack(ANFakePlayer.getPlayer((ServerLevel) level)), 99);
            return;
        }

        if (this.droppingShards) {
            tamingTime++;
            if (tamingTime % 20 == 0 && !level.isClientSide())
                Networking.sendToNearbyClient(level, this, new PacketANEffect(PacketANEffect.EffectType.TIMED_HELIX, blockPosition(), ParticleColor.GREEN));

            if (tamingTime > 60 && !level.isClientSide) {
                ItemStack stack = new ItemStack(ItemsRegistry.WHIRLISPRIG_SHARDS, 1 + level.random.nextInt(1));
                level.addFreshEntity(new ItemEntity(level, getX(), getY() + 0.5, getZ(), stack));
                this.remove(RemovalReason.DISCARDED);
                level.playSound(null, getX(), getY(), getZ(), SoundEvents.ILLUSIONER_MIRROR_MOVE, SoundSource.NEUTRAL, 1f, 1f);
            } else if (tamingTime > 55 && level.isClientSide) {
                for (int i = 0; i < 10; i++) {
                    double d0 = getX();
                    double d1 = getY() + 0.1;
                    double d2 = getZ();
                    level.addParticle(ParticleTypes.END_ROD, d0, d1, d2, (level.random.nextFloat() * 1 - 0.5) / 3, (level.random.nextFloat() * 1 - 0.5) / 3, (level.random.nextFloat() * 1 - 0.5) / 3);
                }
            }
        }
    }

