@Override
    public void draw(OwoUIDrawContext context, int mouseX, int mouseY, float partialTicks, float delta) {
        if(!(entity instanceof LivingEntity living)) {
            super.draw(context, mouseX, mouseY, partialTicks, delta);

            return;
        }

        if (this.lastBbWidth != entity.getBbWidth() || this.lastBbHeight != entity.getBbHeight()) {
            switch (type) {
                case VERTICAL -> this.scaleToFitVertically(true);
                case HORIZONTAL -> this.scaleToFitHorizontally(true);
                case BOTH -> this.scaleToFit(true);
                case NONE -> {}
            }

            this.lastBbWidth = entity.getBbWidth();
            this.lastBbHeight = entity.getBbHeight();
        }

        var renderQueue = new ArrayList<Runnable>();

        renderQueue.add(
                () -> {
                    context.push();
                    renderLiving(context, living, mouseX, mouseY, partialTicks, true);
                    context.pop();
                }
        );

        if (sideBySideMode) {
            renderQueue.add(
                    () -> {
                        context.push();
                        renderLiving(context, living, mouseX, mouseY, partialTicks, false);
                        context.pop();
                    }
            );
        }

        this.renderWrapping.accept(
                context,
                this,
                renderQueue
        );
    }

@Override
	public void triggerActiveAbility(Level world, ServerPlayer player, ItemStack stack) {
		if (SuperpositionHandler.hasSpellstoneCooldown(player))
			return;

		CachedTeleportationLocation location = null;

		if (this.locationCache.containsKey(player)) {
			try {
				var future = this.locationCache.get(player);

				if (future.isDone()) {
					location = this.locationCache.get(player).get();
				} else {
					future.cancel(true);
				}

				this.locationCache.remove(player);
			} catch (Exception ex) {
				ex.printStackTrace();
			}
		}

		if (location == null) {
			EnigmaticLegacy.LOGGER.getInternal().info("No cached location found for {}, generating new one synchronously.", player.getGameProfile().getName());
			location = this.findRandomLocation(player);
		}

		ResourceKey<Level> key = location.dimension();

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));
		player.teleportTo(location.x(), location.y(), location.z());

		if (player.level().dimension() != key) {
			SuperpositionHandler.sendToDimension(player, key);
			player.teleportTo(location.x(), location.y(), location.z());
		}

		world.playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
		EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketRecallParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 48, false));

		SuperpositionHandler.setSpellstoneCooldown(player, this.getCooldown(player));

		EnigmaticLegacy.LOGGER.getInternal().info("Player {} triggered active ability of Non-Euclidean Cube. Teleported to D: {}, X: {}, Y: {}, Z: {}.",
				player.getGameProfile().getName(), player.level().dimension(), player.getX(), player.getY(), player.getZ());
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		State state = context.getState();
		IMultiblockLevel level = context.getLevel();
		final Level rawLevel = context.getLevel().getRawLevel();
		if(rawLevel instanceof ServerLevel serverLevel)
		{
			BlockPos broadcastPos = level.toAbsolute(BROADCAST_POS);
			// update the maximum range if it's undefined or every ~ 7 minutes
			if(state.rangeInChunks < 0||serverLevel.getGameTime()%8192==((broadcastPos.getX()^broadcastPos.getZ())&8191))
			{
				int maxRange = calculateMaxRange(serverLevel, broadcastPos, 4);
				state.rangeInChunks = maxRange;
			}

			// fetch the wireless handler for this world
			WirelessRedstoneHandler handler = WirelessRedstoneHandler.getHandler(serverLevel);

			// consume energy and set active state
			int consumed = IEServerConfig.MACHINES.radio_tower_consumption.get();
			int extracted = state.energy.extractEnergy(consumed, false);
			final boolean prevActive = state.active;
			state.active = extracted >= consumed;
			// if active state changed, notify the network
			if(state.active!=prevActive)
				state.markSendAndReceiveDirty();

			// register with handler if not yet done
			if(!handler.isRegistered(broadcastPos, context.getState()))
				handler.register(broadcastPos, context.getState());

			// if the sending signal has changed, notify other components
			if(state.sendingDirty)
			{
				handler.notifyComponents(broadcastPos, state);
				state.sendingDirty = false;
			}
			// if the network has changed, fetch new signal
			if(state.receivingDirty)
			{
				state.receivedSignals = state.isActive()?handler.fetchSignals(broadcastPos, state): new byte[16];
				state.bundleConnection.markDirty();
				state.receivingDirty = false;
			}
		}
	}

@Override
	public void process(IPayloadContext context)
	{
		if(context.flow().getReceptionSide()==LogicalSide.SERVER)
		{
			ServerPlayer player = IMessage.serverPlayer(context);
			UUID playerId = player.getUUID();
			context.enqueueWork(() -> {
				if(key==MessageType.SYNC)
				{
					ResourceLocation[] ss = ShaderRegistry.receivedShaders.get(playerId).stream().filter(Objects::nonNull).toArray(ResourceLocation[]::new);
					PacketDistributor.sendToPlayer(player, new MessageShaderManual(MessageType.SYNC, ss));
				}
				else if(key==MessageType.UNLOCK&&!args.isEmpty())
				{
					ShaderRegistry.receivedShaders.put(playerId, args.get(0));
				}
				else if(key==MessageType.SPAWN&&!args.isEmpty())
				{
					if(!player.getAbilities().instabuild)
						// TODO should we check that this actually passed?
						IngredientUtils.consumePlayerIngredient(player, ShaderRegistry.shaderRegistry.get(args.get(0)).replicationCost.get());
					ItemStack shaderStack = ShaderRegistry.makeShaderStack(args.get(0));
					ItemEntity entityitem = player.drop(shaderStack, false);
					if(entityitem!=null)
					{
						entityitem.setNoPickUpDelay();
						entityitem.setThrower(player);
					}
				}
			});
		}
		else
			context.enqueueWork(() -> {
				if(key==MessageType.SYNC)
				{
					Player player = ImmersiveEngineering.proxy.getClientPlayer();
					if(player!=null)
					{
						UUID name = player.getUUID();
						for(ResourceLocation shader : args)
							if(shader!=null)
								ShaderRegistry.receivedShaders.put(name, shader);
					}
				}
			});
	}

public boolean addAttachedChasses(Queue<BlockPos> frontier, Set<BlockPos> visited) {
		BlockState state = getBlockState();
		if (!(state.getBlock() instanceof AbstractChassisBlock))
			return false;
		Axis axis = state.getValue(AbstractChassisBlock.AXIS);
		if (isRadial()) {

			// Collect chain of radial chassis
			for (int offset : new int[]{-1, 1}) {
				Direction direction = Direction.get(AxisDirection.POSITIVE, axis);
				BlockPos currentPos = worldPosition.relative(direction, offset);
				if (!level.isLoaded(currentPos))
					return false;

				BlockState neighbourState = level.getBlockState(currentPos);
				if (!AllBlocks.RADIAL_CHASSIS.has(neighbourState))
					continue;
				if (axis != neighbourState.getValue(BlockStateProperties.AXIS))
					continue;
				if (!visited.contains(currentPos))
					frontier.add(currentPos);
			}

			return true;
		}

		// Collect group of connected linear chassis
		for (Direction offset : Iterate.directions) {
			BlockPos current = worldPosition.relative(offset);
			if (visited.contains(current))
				continue;
			if (!level.isLoaded(current))
				return false;

			BlockState neighbourState = level.getBlockState(current);
			if (!LinearChassisBlock.isChassis(neighbourState))
				continue;
			if (!LinearChassisBlock.sameKind(state, neighbourState))
				continue;
			if (neighbourState.getValue(LinearChassisBlock.AXIS) != axis)
				continue;

			frontier.add(current);
		}

		return true;
	}

private void submitNewArrivals(InventorySummary before, InventorySummary after) {
		if (before == null || after.isEmpty())
			return;

		Set<RequestPromiseQueue> promiseQueues = new HashSet<>();

		for (Direction d : Iterate.directions) {
			if (!level.isLoaded(worldPosition.relative(d)))
				continue;

			BlockState adjacentState = level.getBlockState(worldPosition.relative(d));
			if (AllBlocks.FACTORY_GAUGE.has(adjacentState)) {
				if (FactoryPanelBlock.connectedDirection(adjacentState) != d)
					continue;
				if (!(level.getBlockEntity(worldPosition.relative(d)) instanceof FactoryPanelBlockEntity fpbe))
					continue;
				if (!fpbe.restocker)
					continue;
				for (FactoryPanelBehaviour behaviour : fpbe.panels.values()) {
					if (!behaviour.isActive())
						continue;
					promiseQueues.add(behaviour.restockerPromises);
				}
			}

			if (AllBlocks.STOCK_LINK.has(adjacentState)) {
				if (PackagerLinkBlock.getConnectedDirection(adjacentState) != d)
					continue;
				if (!(level.getBlockEntity(worldPosition.relative(d)) instanceof PackagerLinkBlockEntity plbe))
					continue;
				UUID freqId = plbe.behaviour.freqId;
				if (!Create.LOGISTICS.hasQueuedPromises(freqId))
					continue;
				promiseQueues.add(Create.LOGISTICS.getQueuedPromises(freqId));
			}
		}

		if (promiseQueues.isEmpty())
			return;

		for (BigItemStack entry : after.getStacks())
			before.add(entry.stack, -entry.count);
		for (RequestPromiseQueue queue : promiseQueues)
			for (BigItemStack entry : before.getStacks())
				if (entry.count < 0)
					queue.itemEnteredSystem(entry.stack, -entry.count);
	}

protected final boolean drawParticlesInternal(List<MaterialSetting> materials, RenderPassPipeline pipeline, Collection<IParticle> particles, Camera camera, float partialTicks) {
        if (useInstancing()) {
            return drawInstanced(materials, pipeline, particles, camera, partialTicks);
        }

        var records = beginCpuRecords(materials, particles.size());

        // prepare mesh data
        var buffer = begin(Tesselator.getInstance());
        try {
            renderQueue(buffer, particles, camera, partialTicks);
        } finally {
            if (records) endCpuRecords();
        }
        var meshData = buffer.build();
        if (meshData == null) return false;

        // sort quads if necessary
        var sorting = getSorting();
        if (sorting != null) {
            var result = MeshDataSorter.sortPrimitives(meshData, pipeline.getSortingBuffer(), sorting);
            if (result != null) {
                result.applyTo(meshData);
            }
        }

        // upload to vbo
        var vbo = uploadFormatVbo(meshData);

        // render materials
        for (var materialSetting : materials) {
            for (int pass = 0, passes = materialSetting.passes(); pass < passes; pass++) {
                materialSetting.pre(pass);
                var material = materialSetting.getMaterial();
                if (records && readsParticleRecords(material)) {
                    renderWithCpuRecords(material, vbo);
                } else {
                    renderWithMaterial(material, MaterialContext.NORMAL, vbo);
                }
                materialSetting.post();
            }
        }

        // invalidate cache
        BufferUploader.invalidate();
        return true;
    }

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
        float potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster);
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
            range += WandUtil.getRangeLevel(caster);
        }
        float damage = this.damage + potency;
        if (!worldIn.isClientSide) {
            if (this.rightStaff(staff)) {
                damage *= 2.0F;
                if (SpellConfig.DragonFrostGriefing.get()) {
                    float flameRange = range * ((float) Math.PI / 180.0F);
                    for (int i = 0; i < 3; i++) {
                        Vec3 cast = caster.getLookAngle().normalize().xRot(worldIn.random.nextFloat() * flameRange * 2 - flameRange).yRot(worldIn.random.nextFloat() * flameRange * 2 - flameRange);
                        HitResult hitResult = worldIn.clip(new ClipContext(caster.getEyePosition(), caster.getEyePosition().add(cast.scale(10)), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, caster));
                        if (hitResult.getType() == HitResult.Type.BLOCK) {
                            Vec3 pos = hitResult.getLocation().subtract(cast.scale(0.5D));
                            BlockPos blockPos = BlockPos.containing(pos.x, pos.y, pos.z);
                            if ((worldIn.getBlockState(blockPos).isAir() ||
                                    (BlockFinder.canBeReplaced(worldIn, blockPos)
                                            && worldIn.getFluidState(blockPos).isEmpty()))
                                    && worldIn.getBlockState(blockPos.below()).isSolidRender(worldIn, blockPos.below())) {
                                worldIn.setBlockAndUpdate(blockPos, Blocks.SNOW.defaultBlockState());
                            }
                            BlockState blockstate = Blocks.FROSTED_ICE.defaultBlockState();
                            if (worldIn.getBlockState(blockPos) == FrostedIceBlock.meltsInto() && blockstate.canSurvive(worldIn, blockPos) && worldIn.isUnobstructed(blockstate, blockPos, CollisionContext.empty()) && !net.minecraftforge.event.ForgeEventFactory.onBlockPlace(caster, net.minecraftforge.common.util.BlockSnapshot.create(worldIn.dimension(), worldIn, blockPos), net.minecraft.core.Direction.UP)) {
                                worldIn.setBlockAndUpdate(blockPos, blockstate);
                                worldIn.scheduleTick(blockPos, Blocks.FROSTED_ICE, Mth.nextInt(caster.getRandom(), 60, 120));
                            }
                        }
                    }
                }
            }
            for (Entity target : getBreathTarget(caster, range)) {
                LivingEntity livingEntity = MobUtil.getLivingTarget(target);
                if (livingEntity != null) {
                    if (livingEntity.hurt(ModDamageSource.frostBreath(caster, caster), damage)) {
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(1) * duration));
                    }
                }
            }
        }
        worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.FROST_BREATH.get(), this.getSoundSource(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
    }

@UseOnly(LogicalSide.SERVER)
    private void onRandomTick(ServerLevel level, BlockPos pos) {
        // Get the ticked block state
        BlockState tickedBlockState = level.getBlockState(pos);

        // Ensure that we should process this block
        boolean isFire = tickedBlockState.is(BlockTags.FIRE);
        if (!isFire && !fireTracker.containsKey(pos)) {
            return;
        }

        // Find a potential recipe for this fire block.
        var matchingRecipe = getMatchingRecipe(level, pos);
        if (matchingRecipe == null) {
            // No recipe found, remove the fire block from tracking.
            fireTracker.remove(pos);
            return;
        }

        long gameTime = level.getGameTime();

        // If it's still fire, it should be tracked.
        // If it has been extinguished, it should 'pop'.
        if (isFire) {
            // Prune the oldest fires if we have too many in the tracker.
            int maxTracked = BaseConfig.COMMON.INFINITY.MAX_TRACKED_FIRES.get();
            int excess = fireTracker.size() - maxTracked;
            if (excess > 0) {
                // Remove the oldest fires (smallest expiration time first) until within the max
                var toRemove = fireTracker.entrySet().stream()
                    .sorted(Map.Entry.comparingByValue())
                    .limit(excess)
                    .map(Map.Entry::getKey)
                    .toList();

                toRemove.forEach(fireTracker::remove);
            }

            fireTracker.putIfAbsent(pos, gameTime + BaseConfig.COMMON.INFINITY.FIRE_MIN_AGE.get());
        } else {
            if (level.getBlockState(pos).isAir() && gameTime > fireTracker.get(pos)) {
                spawnInfinityDrops(level, pos, matchingRecipe);
            }

            fireTracker.remove(pos);
        }
    }

@Override
        protected void tick(ArkbackEntity entity) {
            if (this.runningTime == 25) {
                entity.setSynchedData(RESTING, true);
            }
            else if (this.shakeTick >= 0) {
                if (this.shakeTick++ > 16) {
                    entity.setSynchedData(RESTING, false);
                }
                else {
                    Vec3 shakeDirection = MathUtil.getBodyRight(entity).scale(Mth.floor(Mth.sin(45 * this.shakeTick) * 2)).add(0, 1, 0);
                    AABB plateBounds = AABB.ofSize(entity.position().add(0, entity.getBbHeight(), 0), entity.getBbWidth(), 1.5f * entity.getScale(), entity.getBbWidth());

                    for (Entity rider : EntityRetrievalUtil.<Entity>getEntities(entity.level(), plateBounds, rider -> rider != entity)) {
                        rider.setDeltaMovement(shakeDirection);
                        rider.hurtMarked = true;
                    }

                    if (this.shakeTick < 10 && entity.getSandLevel() > 0) {
                        float sine = Mth.sin(45 * this.shakeTick);

                        if (Mth.abs(sine) >= 0.9f) {
                            TMEParticlePacket packet = new TMEParticlePacket();
                            shakeDirection = MathUtil.getBodyRight(entity).scale(sine * 0.25f).add(0, 0.25f, 0);
                            plateBounds = plateBounds.move(0, 0.5f, 0);

                            for (int i = 0; i < 100; i++) {
                                packet.particle(ParticleBuilder.forRandomPosInBounds(new BlockParticleOption(ParticleTypes.BLOCK, Blocks.SAND.defaultBlockState()), plateBounds)
                                        .velocity(shakeDirection.add(entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f))
                                        .scaleMod((float)entity.random.nextGaussian() * 0.4f + 0.8f));
                                packet.particle(ParticleBuilder.forRandomPosInBounds(new BlockParticleOption(ParticleTypes.FALLING_DUST, Blocks.SAND.defaultBlockState()), plateBounds)
                                        .velocity(shakeDirection.scale(0.1f).add(entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f))
                                        .scaleMod(entity.random.nextFloat() * 0.4f + 0.3f));
                            }

                            packet.sendToAllPlayersTrackingEntity(entity);
                            entity.setSandLevel(entity.getSandLevel() - 10);
                        }
                    }
                }
            }

            if (this.shakeTick == -1 && timedOut(entity.level().getGameTime() + 37)) {
                this.shakeTick = 0;
                entity.triggerAnim("Main", "rest_stop");
            }
        }

@Override
    public void tick() {
        if (level.isClientSide || disabled) {
            return;
        }
        if (level.getGameTime() % 20 != 0)
            return;

        if (fromPos != null && level.isLoaded(fromPos)) {
            // Block has been removed
            if (!(level.getBlockEntity(fromPos) instanceof AbstractSourceMachine) && level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, fromPos, null) == null) {
                fromPos = null;
                updateBlock();
                return;
            } else if (level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, fromPos, null) instanceof ISourceCap sourceHandler) {
                // Transfer mana fromPos to this
                if (transferSource(sourceHandler, getSourceStorage()) > 0) {
                    ParticleUtil.spawnFollowProjectile(level, fromPos, worldPosition, this.getColor());
                }
            } else if (level.getBlockEntity(fromPos) instanceof AbstractSourceMachine fromTile) {
                // Transfer mana fromPos to this
                if (transferSource(fromTile, this) > 0) {
                    updateBlock();
                    ParticleUtil.spawnFollowProjectile(level, fromPos, worldPosition, this.getColor());
                }
            }
        }

        if (toPos != null && level.isLoaded(toPos)) {
            if (!(level.getBlockEntity(toPos) instanceof AbstractSourceMachine) && level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, toPos, null) == null) {
                toPos = null;
                updateBlock();
                return;
            }
            if (level.getCapability(CapabilityRegistry.SOURCE_CAPABILITY, toPos, null) instanceof ISourceCap sourceHandler) {
                // Transfer mana from this to toPos
                if (transferSource(this.getSourceStorage(), sourceHandler) > 0) {
                    ParticleUtil.spawnFollowProjectile(level, worldPosition, toPos, this.getColor());
                }
            } else if (level.getBlockEntity(toPos) instanceof AbstractSourceMachine toTile) {
                // Transfer mana from this to toPos
                if (transferSource(this, toTile) > 0) {
                    ParticleUtil.spawnFollowProjectile(level, worldPosition, toPos, this.getColor());
                }
            }
        }
    }

@Override
    protected void tick() {
        Level world = getWorld();
        BlockPos pos = getPos();


        if (getWorld().isClientSide) {
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), 5);
        } else {
            if (getWorld().getGameTime() % 200 != 0)
                return;

            if (isAnimalGrowth()) {
                List<AgeableMob> animals = getWorld().getEntitiesOfClass(AgeableMob.class, new AABB(getPos()).inflate(5));
                boolean didWorkOnce = false;
                for (AgeableMob a : animals) {
                    if (a.getType().is(EntityTags.OVERGROWTH_BLACKLIST))
                        continue;
                    if (a.isBaby()) {
                        a.ageUp(500, true);
                        didWorkOnce = true;
                    }
                }
                if (didWorkOnce)
                    setNeedsSource(true);
            } else {
                int range = 5;
                boolean didWorkOnce = false;
                for (BlockPos b : BlockPos.betweenClosed(pos.offset(range, -1, range), pos.offset(-range, 1, -range))) {
                    BlockState state = world.getBlockState(b);

                    if (state.getBlock() instanceof FarmBlock || world.getBlockState(b.above()).getBlock() instanceof BonemealableBlock) {
                        b = b.above();
                        state = world.getBlockState(b);
                    }

                    if (rand.nextInt(25) == 0)
                        if (BoneMealItem.applyBonemeal(new ItemStack(Items.BONE_MEAL), world, b, ANFakePlayer.getPlayer((ServerLevel) world))) {
                            didWorkOnce = true;
                        }
                }
                if (didWorkOnce)
                    setNeedsSource(true);
            }
        }

    }

@ApiStatus.Internal
    public static void init(OwoNetChannel channel, Consumer<Consumer<Player>> hookRegistration) {
        channel.registerClientboundDeferred(SyncAllLoaderDataPacket.class, SyncAllLoaderDataPacket.ENDEC);

        hookRegistration.accept(player -> {
            var endecDataLoaders = ALL_SYNCED_LOADERS.values()
                    .stream()
                    .collect(Collectors.toList());

            Set<ResourceLocation> resolvedIds = new HashSet<>();

            for (SyncedDataHelper<?> dataLoader : endecDataLoaders) {
                resolvedIds.add(dataLoader.getId());
            }

            List<SyncedDataHelper<?>> dataLoaders = new ArrayList<>();

            int lastSize = -1;

            while (dataLoaders.size() != lastSize) {
                lastSize = dataLoaders.size();

                var it = endecDataLoaders.iterator();

                while (it.hasNext()) {
                    SyncedDataHelper<?> dataLoader = it.next();

                    if (resolvedIds.containsAll(dataLoader.getDependencyIds())) {
                        resolvedIds.add(dataLoader.getId());
                        dataLoaders.add(dataLoader);
                        it.remove();
                    }
                }
            }

            var packets = dataLoaders.stream()
                    .map(dataLoader -> {
                        var id = dataLoader.getId();
                        var data = dataLoader.getServerData();

                        return new SyncLoaderDataPacket(id, data);
                    })
                    .toList();

            channel.serverHandle(player).send(new SyncAllLoaderDataPacket(packets));
        });
    }

public static boolean validTeleport(Entity entity, double x_init, double y_init, double z_init, Level world, int checkAxis) {
		int x = (int) x_init;
		int y = (int) y_init;
		int z = (int) z_init;

		BlockState block = world.getBlockState(new BlockPos(x, y - 1, z));

		if (!world.isEmptyBlock(new BlockPos(x, y - 1, z)) && block.canOcclude()) {
			for (int counter = 0; counter <= checkAxis; counter++) {
				if (!world.isEmptyBlock(new BlockPos(x, y + counter - 1, z)) && world.getBlockState(new BlockPos(x, y + counter - 1, z)).canOcclude() && world.isEmptyBlock(new BlockPos(x, y + counter, z)) && world.isEmptyBlock(new BlockPos(x, y + counter + 1, z))) {
					world.playSound(null, entity.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));

					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(entity.getX(), entity.getY(), entity.getZ(), 128, entity.level().dimension())), new PacketPortalParticles(entity.getX(), entity.getY() + (entity.getBbHeight() / 2), entity.getZ(), 72, 1.0F, false));

					if (entity instanceof ServerPlayer) {
						ServerPlayer player = (ServerPlayer) entity;
						player.teleportTo(x + 0.5, y + counter, z + 0.5);
					} else {
						((LivingEntity) entity).teleportTo(x + 0.5, y + counter, z + 0.5);
					}

					world.playSound(null, entity.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(entity.getX(), entity.getY(), entity.getZ(), 128, entity.level().dimension())), new PacketRecallParticles(entity.getX(), entity.getY() + (entity.getBbHeight() / 2), entity.getZ(), 48, false));
					return true;
				}
			}
		} else {
			for (int counter = 0; counter <= checkAxis; counter++) {
				if (!world.isEmptyBlock(new BlockPos(x, y - counter - 1, z)) && world.getBlockState(new BlockPos(x, y - counter - 1, z)).canOcclude() && world.isEmptyBlock(new BlockPos(x, y - counter, z)) && world.isEmptyBlock(new BlockPos(x, y - counter + 1, z))) {
					world.playSound(null, entity.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(entity.getX(), entity.getY(), entity.getZ(), 128, entity.level().dimension())), new PacketRecallParticles(entity.getX(), entity.getY() + (entity.getBbHeight() / 2), entity.getZ(), 48, false));

					if (entity instanceof ServerPlayer) {
						ServerPlayer player = (ServerPlayer) entity;
						player.teleportTo(x + 0.5, y - counter, z + 0.5);
					} else {
						((LivingEntity) entity).teleportTo(x + 0.5, y - counter, z + 0.5);
					}

					world.playSound(null, entity.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2D)));
					EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(entity.getX(), entity.getY(), entity.getZ(), 128, entity.level().dimension())), new PacketRecallParticles(entity.getX(), entity.getY() + (entity.getBbHeight() / 2), entity.getZ(), 48, false));
					return true;
				}
			}
		}

		return false;
	}

