@Override
    public void preRenderCallback(DinosaurEntity entity, final float partialTick) {
        float scaleModifier = entity.getAttributes().getScaleModifier();
        float scaleInfant = (float) (entity.isSkeleton() ? this.dinosaur.getSkeletonScaleInfant() : this.dinosaur.getScaleInfant());
        float scaleAdult = (float) (entity.isSkeleton() ? this.dinosaur.getSkeletonScaleAdult() : this.dinosaur.getScaleAdult());
        float scale = (float) entity.interpolate(scaleInfant, scaleAdult) * scaleModifier;
        this.shadowSize = scale * this.renderInfo.getShadowSize();

        float offsetX = entity.isSkeleton() ? this.dinosaur.getSkeletonOffsetX() : this.dinosaur.getOffsetX();
        float offsetY = entity.isSkeleton() ? this.dinosaur.getSkeletonOffsetY() : this.dinosaur.getOffsetY();
        float offsetZ = entity.isSkeleton() ? this.dinosaur.getSkeletonOffsetZ() : this.dinosaur.getOffsetZ();
        GlStateManager.translate(offsetX * scale, offsetY * scale, offsetZ * scale);

        String name = entity.getCustomNameTag();
        switch (name) {
            case "JTGhawk137":
                GlStateManager.scale(0.1F, scale, scale);
                break;
            case "Gegy":
                GlStateManager.scale(scale, 0.01F, scale);
                break;
            case "Destruction":
                GlStateManager.scale(scale * 1.2, scale * 1.2, scale * 1.2);
                break;
            case "Wyn":
                GlStateManager.scale(scale * 1.3, scale * 1.3, scale * 1.3);
                break;
            case "Notch":
                GlStateManager.scale(scale * 2, scale * 2, scale * 2);
                break;
            case "jglrxavpok":
                GlStateManager.scale(scale, scale, scale * -1);
                break;
            case "Vitiate":
                int color = Color.HSBtoRGB((entity.world.getTotalWorldTime() % 1000) / 100f, 1f, 1f);
                GlStateManager.color((color & 0xFF) / 255f, ((color >> 8) & 0xFF) / 255f, ((color >> 16) & 0xFF) / 255f);
                break;
            case "VPFbGsfp5QR3WsLXM4JBDJXMG":
                GlStateManager.scale(scale * random.nextInt(69), scale * random.nextInt(69), scale * random.nextInt(69));
                break;
            case "WIDE":
                GlStateManager.scale(scale * 5, scale * 0.5f, scale * 0.5f);
                break;
            default:
                GlStateManager.scale(scale, scale, scale);
                break;
        }
    }

public static double getRoughTemperatureAt(Level level, BlockPos pos, int flags)
    {
        pos = sublevelToWorld(level, pos);
        boolean sensitive = (flags & 1) != 0;
        boolean forceUpdate = (flags & 2) != 0;

        Map<BlockPos, TempSnapshot> snapshots = TEMPERATURE_CACHE.computeIfAbsent(level.dimension(), dim -> new HashMap<>());
        int tickSpeedMultiplier = 1 + level.getGameRules().getInt(GameRules.RULE_RANDOMTICKING) / 20;

        BlockPos segment = new BlockPos((pos.getX() >> 3) << 3,
                                        (pos.getY() >> 3) << 3,
                                        (pos.getZ() >> 3) << 3);

        // Use cached value if not forced update
        if (!forceUpdate)
        {
            int interval = sensitive ? 200 : 1000;
            TempSnapshot snapshot = snapshots.get(segment);
            if (snapshot != null)
            {
                long gameTime = level.getGameTime();
                if (gameTime - snapshot.timestamp < interval / tickSpeedMultiplier)
                {   return snapshot.temperature();
                }
            }
        }

        /* Get temperature based on dummy entity */
        // Init dummy at this location
        DummyEntity dummy = getDummyEntity(level);
        dummy.setPos(CSMath.getCenterPos(pos));
        // Get modifiers
        List<TempModifier> modifiers = new ArrayList<>(Temperature.getModifiers(dummy, Temperature.Trait.WORLD));

        // Get insulation from hearths
        InsulationSnapshot maxCoolingHeating = getInsulationAt(level, pos, 2);
        if (maxCoolingHeating.cooling() > 0)
        {   modifiers.add(new FrigidnessTempModifier(maxCoolingHeating.cooling()));
        }
        if (maxCoolingHeating.heating() > 0)
        {   modifiers.add(new WarmthTempModifier(maxCoolingHeating.heating()));
        }
        // Get & store temperature
        double tempAt = Temperature.apply(0, dummy, Temperature.Trait.WORLD, modifiers, true);
        snapshots.put(segment, new TempSnapshot(level.getGameTime(), tempAt));

        return tempAt;
    }

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            if (ctx.player().level().isClientSide())
                return;

            ServerPlayer player = (ServerPlayer) ctx.player();

            if (player.containerMenu.containerId != container) {
                causeError(player);

                return;
            }

            ItemStack stack = DescriptionUtils.gatherRelicStack(player, slot);

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                causeError(player);

                return;
            }

            RandomSource random = player.getRandom();

            int cost = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().getHintPlayerExperienceCost() * amount;

            if (EntityUtils.getPlayerTotalExperience(player) < cost)
                return;

            player.giveExperiencePoints(-cost);

            research(player, stack, amount);

            if (relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().isComplete()) {
                relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability).getResearchData().setResearched(true);

                player.connection.send(new ClientboundSoundPacket(Holder.direct(RelicsSounds.FINISH_RESEARCH.get()), SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 1F, 1F, random.nextLong()));
            } else
                player.connection.send(new ClientboundSoundPacket(Holder.direct(RelicsSounds.CONNECT_STARS.get()), SoundSource.PLAYERS, player.getX(), player.getY(), player.getZ(), 0.75F, 0.75F + random.nextFloat() * 0.5F, random.nextLong()));

            try {
                player.containerMenu.getSlot(slot).set(stack);
            } catch (Exception e) {
                e.printStackTrace();

                causeError(player);
            }
        });
    }

private boolean drainLiquid(Level level, IPedestal pedestal, BlockPos pos, int bucketRange) {
		if (queueToDrain.isEmpty()) {
			updateQueueToDrain(level, pos, bucketRange);
		}

		if (queueToDrain.isEmpty()) {
			return false;
		}

		Iterator<BlockPos> iterator = queueToDrain.iterator();

		// iterate through all the fluid blocks in queue - needed in case there are multiple fluids and next fluid in queue can't go in any tank
		while (iterator.hasNext()) {
			BlockPos blockToDrain = iterator.next();
			BlockState blockState = level.getBlockState(blockToDrain);
			Fluid fluid = blockState.getFluidState().getType();

			// make sure that the block is still fluid as we're working with cached queue
			if (fluid != Fluids.EMPTY) {
				Optional<FluidStack> fs = drainBlock(level, blockToDrain, blockState.getBlock(), blockState, fluid, IFluidHandler.FluidAction.SIMULATE);
				if (fs.isPresent()) {
					FluidStack fluidStack = fs.get();
					// check if we were able to fill the fluid in some tank, otherwise try the next fluid block in queue
					if ((pedestal.fillConnectedTank(fluidStack, IFluidHandler.FluidAction.SIMULATE) != fluidStack.getAmount())) {
						continue;
					}

					drainBlock(level, blockToDrain, blockState.getBlock(), blockState, fluid, IFluidHandler.FluidAction.EXECUTE);
					pedestal.fillConnectedTank(fluidStack);
					iterator.remove();
					return true;
				} else {
					iterator.remove();
				}
			} else {
				iterator.remove();
			}
		}

		unsuccessfulTries++;

		if (unsuccessfulTries >= UNSUCCESSFUL_TRIES_TO_CLEAN_QUEUE) {
			queueToDrain.clear();
			unsuccessfulTries = 0;
		}

		return false;
	}

public boolean depositItem(Player player, InteractionHand hand, ItemStack stackInHand, int slot) {
		// noinspection ConstantConditions
		long gameTime = getLevel().getGameTime();
		boolean doubleClick = gameTime - lastDepositTime < 10;
		lastDepositTime = gameTime;

		StorageWrapper storageWrapper = getStorageWrapper();
		InventoryHandler invHandler = storageWrapper.getInventoryHandler();
		ItemStack stackInSlot = invHandler.getStackInSlot(slot);

		MemorySettingsCategory memorySettings = getStorageWrapper().getSettingsHandler().getTypeCategory(MemorySettingsCategory.class);

		if (doubleClick) {
			return depositFromAllOfPlayersInventory(player, slot, invHandler, stackInSlot, memorySettings);
		}

		if (stackInSlot.isEmpty()) {
			if (invHandler.isItemValid(slot, stackInHand, player)) {
				ItemStack result = invHandler.insertItemOnlyToSlot(slot, stackInHand, true);
				if (result.getCount() != stackInHand.getCount()) {
					result = invHandler.insertItemOnlyToSlot(slot, stackInHand, false);
					if (isLocked()) {
						memorySettings.selectSlot(slot);
						if (player instanceof ServerPlayer serverPlayer) {
							syncLinkedStorageContentsToPlayer(serverPlayer);
						}
					}
					player.setItemInHand(hand, result);
					return true;
				}
			}
		} else {
			ItemStack result = invHandler.insertItemOnlyToSlot(slot, stackInHand, true);
			if (result.getCount() != stackInHand.getCount()) {
				result = invHandler.insertItemOnlyToSlot(slot, stackInHand, false);
				if (isLocked()) {
					memorySettings.selectSlot(slot);
					if (player instanceof ServerPlayer serverPlayer) {
						syncLinkedStorageContentsToPlayer(serverPlayer);
					}
				}
				player.setItemInHand(hand, result);
				return true;
			}
		}

		return false;
	}

