@Override
    public void onUpdate() {
        super.onUpdate();
        int level = getLevel();
        if (level > 0) {
            if (!isRemote()) {
                if (player.level().getGameTime() % 100 == 8) {
                    if (Arrays.stream(EquipmentSlot.values()).filter(i -> i.getType() == EquipmentSlot.Type.HUMANOID_ARMOR).map(player::getItemBySlot).allMatch(i -> i.is(ModItemTags.HUNTER_COAT))) {
                        if (this.getSkillHandler().isSkillEnabled(HunterSkills.ARMOR_JUMP)) {
                            MobEffectInstance mobEffectInstance = new MobEffectInstance(MobEffects.JUMP_BOOST, -1, 0, false, false);
                            mobEffectInstance.factions$addProperty(HunterSkills.ARMOR_JUMP.getId());
                            player.addEffect(mobEffectInstance);
                        } else {
                            IEffectInstanceWithSource.removePotionEffect(player, MobEffects.JUMP_BOOST, HunterSkills.ARMOR_JUMP.getId());
                        }
                        if (this.getSkillHandler().isSkillEnabled(HunterSkills.ARMOR_SPEED)) {
                            MobEffectInstance mobEffectInstance = new MobEffectInstance(MobEffects.SPEED, -1, 0, false, false);
                            mobEffectInstance.factions$addProperty(HunterSkills.ARMOR_SPEED.getId());
                            player.addEffect(mobEffectInstance);
                        } else {
                            IEffectInstanceWithSource.removePotionEffect(player, MobEffects.SPEED, HunterSkills.ARMOR_SPEED.getId());
                        }
                    } else {
                        IEffectInstanceWithSource.removePotionEffect(player, MobEffects.JUMP_BOOST, HunterSkills.ARMOR_JUMP.getId());
                        IEffectInstanceWithSource.removePotionEffect(player, MobEffects.SPEED, HunterSkills.ARMOR_SPEED.getId());
                    }
                }
            } else {
                if (getSpecialAttributes().blessingSoundReference != null && !player.isUsingItem()) {
                    //Make sure the blessing sound is stopped when player is not using {@link BlessableItem}. This is necessary because onReleaseUsing is not called for other client players.
                    getSpecialAttributes().blessingSoundReference.stopPlaying();
                    getSpecialAttributes().blessingSoundReference = null;
                }
                VampirismMod.proxy.handleSleepClient(player);

            }
        } else {
            if (this.player.level().getGameTime() % 100 == 16) {
                if (!OilUtils.getEquippedArmorOils(this.player).isEmpty()) {
                    this.player.addEffect(new MobEffectInstance(ModEffects.TOXICANT, 120, 0, false, false));
                }
                IEffectInstanceWithSource.removePotionEffect(player, MobEffects.JUMP_BOOST, HunterSkills.ARMOR_JUMP.getId());
                IEffectInstanceWithSource.removePotionEffect(player, MobEffects.SPEED, HunterSkills.ARMOR_SPEED.getId());
            }
        }
        getSpecialAttributes().fullHunterCoat = level > 0 ? HunterCoatItem.isFullyEquipped(player) : null;

    }

@Override
  public Optional<SlotResult> findFirstCurio(Predicate<ItemStack> filter, boolean includeInactive,
                                             String cacheKey) {
    // Check cached value first
    long gameTime = this.livingEntity.level().getGameTime();
    Cache<String, Pair<Long, Optional<SlotResult>>> cache = this.curioInventory.firstCurioCache;

    if (!cacheKey.isEmpty()) {
      Pair<Long, Optional<SlotResult>> cached = cache.getIfPresent(cacheKey);

      if (cached != null && cached.getFirst() == gameTime) {
        return cached.getSecond();
      }
    }
    Map<String, ICurioStacksHandler> curios = this.getCurios();

    for (String id : curios.keySet()) {
      ICurioStacksHandler stacksHandler = curios.get(id);
      IDynamicStackHandler stackHandler = stacksHandler.getStacks();
      NonNullList<Boolean> activeStates = stacksHandler.getActiveStates();

      for (int i = 0; i < stackHandler.getSlots(); i++) {

        if (!includeInactive && activeStates.size() > i && !activeStates.get(i)) {
          continue;
        }
        ItemStack stack = stackHandler.getStackInSlot(i);

        if (!stack.isEmpty() && filter.test(stack)) {
          NonNullList<Boolean> renderStates = stacksHandler.getRenders();
          var ret =
              Optional.of(
                  new SlotResult(
                      new SlotContext(
                          id,
                          this.livingEntity,
                          i,
                          false,
                          renderStates.size() > i && renderStates.get(i)),
                      stack));
          cache.put(cacheKey, Pair.of(gameTime, ret));
          return ret;
        }
      }
    }
    cache.put(cacheKey, Pair.of(gameTime, Optional.empty()));
    return Optional.empty();
  }

@Override
	public boolean place(FeaturePlaceContext<Configuration> context) {
		final BlockPos startPos = context.origin();
		final Configuration config = context.config();
		final RandomSource rand = context.random();
		final int depth = config.maxDepth().sample(rand);
		final int fluidRadius = config.fluidDiameter().sample(rand) / 2;
		final int chuteRadius = config.chuteDiameter().sample(rand) / 2;
		final BlockPos.MutableBlockPos pos = startPos.mutable();
		final WorldGenLevel level = context.level();
		final int fluidHypot = fluidRadius * fluidRadius;
		final int chuteHypot = chuteRadius * chuteRadius;
		final int chuteDepth = Math.min(depth, pos.getY() - level.getMinBuildHeight());

		for (int i = 0; i < chuteDepth; i++) {
			for (int x = -fluidRadius; x <= fluidRadius; x++) {
				for (int z = -fluidRadius; z <= fluidRadius; z++) {
					final int radius = x * x + z * z;

					if (radius < fluidHypot + rand.nextGaussian() * 4 + 1) {
						final BlockState state = level.getBlockState(pos.setWithOffset(startPos, x, -i, z));

						if (state.isAir() || (radius < chuteHypot + rand.nextGaussian() * 4 + 1 && state.getDestroySpeed(level, pos) >= 0)) {
							final BlockState aboveState = level.getBlockState(pos.above());

							if (aboveState.isAir()) {
								while (pos.getY() - 1 > level.getMinBuildHeight() && level.getBlockState(pos.below()).isAir()) {
									pos.move(0, -1, 0);
								}
							}

							final BlockState fluid = config.fluid().getState(rand, pos);

							level.setBlock(pos, fluid, Block.UPDATE_CLIENTS);

							if (aboveState.isAir())
								markAboveForPostProcessing(level, pos.immutable());

							if (pos.getY() >= startPos.getY())
								level.scheduleTick(pos.immutable(), fluid.getFluidState().getType(), 0);
						}
					}
				}
			}
		}

		return true;
	}

@Override
    public @Nullable StarbyState tick() {
        if (dest == null) {
            behavior.findItemBackoff = 30 + starbuncle.level.random.nextInt(30);
            starbuncle.addGoalDebug(this, new DebugEvent("NotReachable", "No pathable items nearby"));
            return new DecideStarbyActionState(starbuncle, behavior);
        }

        if (behavior.isPickupDisabled())
            return new DecideStarbyActionState(starbuncle, behavior);
        ItemStack itemstack = starbyWithSpace.getHeldStack();
        if (!itemstack.isEmpty()) {
            starbuncle.addGoalDebug(this, new DebugEvent("ItemPickup", "Received item, ending."));
            starbuncle.getNavigation().stop();
            Starbuncle nextAvailableStarby = starbuncle.getStarbuncleWithSpace();
            List<ItemEntity> nearbyItems = FindItemState.nearbyItems(starbuncle, behavior);
            if (nextAvailableStarby != null && !nearbyItems.isEmpty()) {
                return new FindItemState(starbuncle, behavior, nearbyItems);
            }
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        if (ticksRunning > 20 * 15) {
            starbuncle.addGoalDebug(this, new DebugEvent("TooLong", "Stopped finding item, time finding expired"));
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        if (itemStuck || this.starbyWithSpace == null) {
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        if (dest == null || dest.getItem().isEmpty() || dest.isRemoved()) {
            itemStuck = true;
            starbuncle.addGoalDebug(this, new DebugEvent("ItemRemoved", "Item removed during goal"));
            return new DecideStarbyActionState(starbuncle, behavior);
        }
        starbuncle.minecraftPathNav.stop();
        Path path = starbuncle.minecraftPathNav.createPath(BlockPos.containing(dest.position()), 1, 9);
        if (path == null || !path.canReach()) {
            stuckTicks++;
            if (stuckTicks > 20 * 5) { // Give up after 5 seconds of being unpathable, in case we fall or jump into the air
                itemStuck = true;
                starbuncle.addGoalDebug(this, new DebugEvent("ItemStuck", "Item stuck for 5 seconds. Ending goal"));
            }
            return super.tick();
        }

        starbuncle.getNavigation().moveTo(dest, 1.4d);
        starbuncle.addGoalDebug(this, new DebugEvent("PathTo", "Pathing to " + dest));
        return super.tick();
    }

