@SuppressWarnings("unchecked")
    @SafeVarargs
    private static <T extends AEBaseBlockEntity> DeferredBlockEntityType<T> create(String shortId,
            Class<T> entityClass,
            BlockEntityFactory<T> factory,
            BlockDefinition<? extends AEBaseEntityBlock<?>>... blockDefinitions) {
        Preconditions.checkArgument(blockDefinitions.length > 0);

        var deferred = DR.register(shortId, () -> {
            AtomicReference<BlockEntityType<T>> typeHolder = new AtomicReference<>();
            BlockEntityType.BlockEntitySupplier<T> supplier = (blockPos, blockState) -> factory.create(typeHolder.get(),
                    blockPos, blockState);

            var blocks = Arrays.stream(blockDefinitions)
                    .map(BlockDefinition::block)
                    .toArray(AEBaseEntityBlock[]::new);

            var type = new BlockEntityType<>(supplier, blocks);
            typeHolder.setPlain(type); // Makes it available to the supplier used above

            AEBaseBlockEntity.registerBlockEntityItem(type, blockDefinitions[0].asItem());

            // If the block entity classes implement specific interfaces, automatically register them
            // as tickers with the blocks that create that entity.
            BlockEntityTicker<T> serverTicker = null;
            if (ServerTickingBlockEntity.class.isAssignableFrom(entityClass)) {
                serverTicker = (level, pos, state, entity) -> {
                    ((ServerTickingBlockEntity) entity).serverTick();
                };
            }
            BlockEntityTicker<T> clientTicker = null;
            if (ClientTickingBlockEntity.class.isAssignableFrom(entityClass)) {
                clientTicker = (level, pos, state, entity) -> {
                    ((ClientTickingBlockEntity) entity).clientTick();
                };
            }

            for (var block : blocks) {
                AEBaseEntityBlock<T> baseBlock = (AEBaseEntityBlock<T>) block;
                baseBlock.setBlockEntity(entityClass, type, clientTicker, serverTicker);
            }

            return type;
        });

        var result = new DeferredBlockEntityType<>(entityClass, deferred);
        BLOCK_ENTITY_TYPES.add(result);
        return result;
    }

public static void handle(PacketContext<ServerboundSyncPatternPacket> context) {
		ServerPlayer player = context.sender();
		List<Pattern> pattern = context.message().patterns();

		ArcanusComponents.setPattern(player, pattern);

		if(pattern.size() >= 3 && context.message().castSpell()) {
			ItemStack stack = player.getMainHandItem();

			if(stack.getItem() instanceof StaffItem staff) {
				Optional<TrinketComponent> optional = TrinketsApi.getTrinketComponent(player);

				if(optional.isPresent()) {
					ItemStack spellBook = ArcanusHelper.getActiveSpellBook(player);
					SpellBookComponent spells = spellBook.getOrDefault(ArcanusDataComponents.SPELL_BOOK.get(), SpellBookComponent.empty());
					int index = ArcanusHelper.getSpellIndex(pattern);

					if(player.getCooldowns().getCooldownPercent(staff, 1f) == 0) {
						Spell spell = spells.getSpell(index);

						if(!spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).allMatch(spellComponent -> ArcanusComponents.knowsSpellComponents(player, spellComponent))) {
							player.displayClientMessage(Component.translatable(SPELL_UNKNOWN_SPELL_COMPONENTS).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
							return;
						}

						if(spell.getComponentGroups().stream().flatMap(SpellGroup::getAllComponents).count() > ArcanusComponents.maxSpellSize()) {
							player.displayClientMessage(Component.translatable(SPELL_TOO_MANY_COMPONENTS), true);
							return;
						}

						for(PrimalArcana primalArcana : spell.getArcanaCost().keySet()) {
							if(!player.isCreative() && !ArcanusComponents.drainArcana(player, primalArcana, spell.getArcanaCost().getDouble(primalArcana), false)) {
								player.displayClientMessage(Component.translatable(SPELL_NOT_ENOUGH_MANA).withStyle(ChatFormatting.RED, ChatFormatting.ITALIC), true);
								return;
							}
						}

						ArcanusComponents.setPattern(player, ArcanusHelper.getSpellPattern(index));
						ArcanusComponents.setLastCastTime(player, player.level().getGameTime());
						spell.cast(player, player.serverLevel(), stack);
						player.displayClientMessage(Component.translatable(spell.getName()).withStyle(ChatFormatting.GREEN), true);

						for(Holder<Item> holder : BuiltInRegistries.ITEM.getTagOrEmpty(ArcanusItemTags.STAVES))
							player.getCooldowns().addCooldown(holder.value(), (int) (spell.getCoolDown() * player.getAttributeValue(ArcanusAttributes.SPELL_COOL_DOWN.holder())));
					}
				}
			}
		}
	}

public void tick(Level level, BlockPos pos, BlockState state) {
        if (!level.isClientSide && activity > 0 && level.getGameTime() % getRate() == 0) {
            int intensity = getIntensity();
            Vec3 origin = Vec3.atCenterOf(pos);

            for (int i = 0; i < intensity; i++) {
                Vec3 target = getTarget(step + i);
                BlockHitResult result = raytrace(level, origin, origin.add(target));

                if (result.getType() != HitResult.Type.MISS) {
                    BlockPos hitPos = result.getBlockPos();
                    BlockState hitState = level.getBlockState(hitPos);

                    breakBlock(level, hitPos, hitState);

                    int minY = level.getMinBuildHeight();
                    BlockPos spawnPos = traceDown(hitPos, minY, level);
                    BlockState spawnState = level.getBlockState(spawnPos);

                    if (canReplace(spawnState)) {
                        if (level.getRandom().nextFloat() < spawnRatio) {
                            if (spawnPos.getY() < minY + spawnYLimit) {
                                spawnOre(spawnPos);
                            }
                        } else {
                            spawnMob(spawnPos);
                        }
                    } else {
                        breakBlock(level, spawnPos, spawnState);
                    }
                }
            }

            ((ServerLevel) level).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, FracturedBedrockBlock.instance.defaultBlockState()),
                    worldPosition.getX() + 0.5, worldPosition.getY() + 1.1, worldPosition.getZ() + 0.5,
                    8, 0, level.random.nextGaussian() * 0.1, 0, 0.1);

            step += intensity;
            activity -= intensity;

            if (shouldDeplete()) {
                level.setBlock(getBlockPos(), DepletedBedrockBlock.instance.defaultBlockState(), 2);
            }
        }

        if (!level.isClientSide && activity > 0 && this.level.getGameTime() % 80 == 0) {
            playSound();
        }
    }

public InteractionResult use(BlockState pState, Level pLevel, BlockPos pPos, Player pPlayer, InteractionHand pHand, BlockHitResult pHit) {
        if (pState.hasBlockEntity()) {
            BlockEntity tileEntity = pLevel.getBlockEntity(pPos);
            if (tileEntity instanceof ArcaBlockEntity arcaTileEntity) {
                if (arcaTileEntity.getPlayer() == pPlayer) {
                    ISoulEnergy soulEnergy = SEHelper.getCapability(arcaTileEntity.getPlayer());
                    ItemStack itemStack = pPlayer.getMainHandItem();
                    if (itemStack.isEmpty()) {
                        if (!pPlayer.isShiftKeyDown() && !pPlayer.isCrouching()){
                            if (soulEnergy.getArcaBlock() == null){
                                soulEnergy.setArcaBlock(arcaTileEntity.getBlockPos());
                                soulEnergy.setArcaBlockDimension(pLevel.dimension());
                                if (!soulEnergy.getSEActive()){
                                    soulEnergy.setSEActive(true);
                                }
                                SEHelper.sendSEUpdatePacket(arcaTileEntity.getPlayer());
                                return InteractionResult.SUCCESS;
                            }
                        } else {
                            pLevel.destroyBlock(pPos, true);
                            return InteractionResult.sidedSuccess(pLevel.isClientSide);
                        }
                    } else if (itemStack.is(ModItems.WAYSTONE.get())) {
                        if (WaystoneItem.isSameDimension(tileEntity, itemStack)){
                            BlockPos blockPos = WaystoneItem.getBlockPos(itemStack);
                            if (blockPos != null && soulEnergy.getArcaRevivePos() != blockPos) {
                                if (blockPos.distToCenterSqr(pPos.getCenter()) <= Mth.square(8)) {
                                    soulEnergy.setArcaRevivePos(blockPos);
                                    SEHelper.sendSEUpdatePacket(pPlayer);
                                    if (pLevel instanceof ServerLevel) {
                                        ModNetwork.sendTo(pPlayer, new SPlayPlayerSoundPacket(SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, 1.0F, 1.0F));
                                    }
                                    pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.revivePos"), true);
                                    return InteractionResult.sidedSuccess(pLevel.isClientSide);
                                } else {
                                    pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.difDimension"), true);
                                    return InteractionResult.FAIL;
                                }
                            }
                        } else {
                            pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.difDimension"), true);
                            return InteractionResult.FAIL;
                        }
                    }
                }
            }
        }
        return InteractionResult.PASS;
    }

protected void teleport() {
        if (!this.level.isClientSide() && !this.isNoAi() && this.isAlive() && this.toTeleportPos == null && !this.isSettingUpSecond() && !this.isCasting()) {
            if (MobsConfig.ApostleDelayedTeleport.get()) {
                if (this.pendingTeleportSearch != null) {
                    if (this.pendingTeleportSearch.isDone()) {
                        final double startY = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                        Vec3 result = this.pendingTeleportSearch.getNow(null);
                        this.pendingTeleportSearch = null;
                        Vec3 vec3 = findTeleportGroundY(this.level, result.x, result.y + 3, result.z, startY);
                        if (vec3 != null) {
                            this.toTeleportPos = vec3;
                            this.playSound(ModSounds.APOSTLE_PRE_TELEPORT.get(), 2.0F, 1.0F);
                            this.resetHitTime();
                        }
                    }
                } else {
                    final double startX = this.getX();
                    final double startY = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                    final double startZ = this.getZ();
                    final RandomSource randomSource = this.apostleRandom;

                    this.prevX = startX;
                    this.prevY = this.getY();
                    this.prevZ = startZ;

                    this.pendingTeleportSearch = CompletableFuture.supplyAsync(() -> {
                        double d0 = 32.0D;
                        double d1 = startX + (randomSource.nextDouble() - 0.5D) * d0;
                        double d2 = startY + 3.0D;
                        double d3 = startZ + (randomSource.nextDouble() - 0.5D) * d0;
                        return new Vec3(d1, d2, d3);
                    });
                }
            } else {
                for (int i = 0; i < 128; ++i) {
                    double d3 = this.getX() + (this.level.getRandom().nextDouble() - 0.5D) * 32.0D;
                    double d4 = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                    double d5 = this.getZ() + (this.level.getRandom().nextDouble() - 0.5D) * 32.0D;
                    BlockPos blockPos = BlockPos.containing(d3, d4, d5);
                    boolean flag = this.getTarget() == null || i >= 64 || BlockFinder.canSeeBlock(this.getTarget(), blockPos);
                    if (flag && this.randomTeleport(d3, d4, d5, false)) {
                        this.teleportHits();
                        this.resetHitTime();
                        break;
                    }
                }
            }
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        if (shouldUpdateNeighbours) {
            updateNeighbours();
            shouldUpdateNeighbours = false;
        }

        DroneFakePlayer fp = getFakePlayer();
        tickFakePlayer(fp);

        ChunkPos newChunkPos = new ChunkPos((int)curX >> 4, (int)curZ >> 4);
        if (chunkLoader != null) {
            if (PlayerLogoutTracker.INSTANCE.isPlayerLoggedOutTooLong(level.getServer(), ownerID)) {
                chunkLoader.unloadAll((ServerLevel) level);
            } else if (prevChunkPos == null || !prevChunkPos.equals(newChunkPos)) {
                chunkLoader.updateLoadedChunks((ServerLevel) level, newChunkPos);
            }
        }
        prevChunkPos = newChunkPos;

        heldItem = ConfigHelper.common().drones.dronesRenderHeldItem.get() ? fp.getMainHandItem() : ItemStack.EMPTY;

        if (getPressure() >= getMinWorkingPressure()) {
            if (!isIdle) {
                addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER);
                if (chunkloadWorkingChunk3x3) {
                    addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER_CHUNKLOAD_WORK3);
                } else if (chunkloadWorkingChunk) {
                    addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER_CHUNKLOAD_WORK);
                }
            }
            if (chunkloadSelf) {
                addAir(-PneumaticValues.USAGE_PROGRAMMABLE_CONTROLLER_CHUNKLOAD_SELF);
            }
            DroneAIManager prevActive = getActiveAIManager();
            aiManager.onUpdateTasks();
            if (getActiveAIManager() != prevActive) {
                // active AI has changed (started or stopped using External Program) - resync widget list to debugging players
                getDebugger().getDebuggingPlayers().forEach(p -> NetworkHandler.sendToPlayer(PacketSyncDroneProgWidgets.create(this), p));
            }
            maybeChargeHeldItem();
        }

        if (nonNullLevel().getGameTime() % 20 == 0) {
            debugger.updateDebuggingPlayers();
        }
    }

@Override
	public void render(DrawContext raw, int x, int y, float delta, int flags) {
		EmiDrawContext context = EmiDrawContext.wrap(raw);
		ChessPiece piece = EmiChess.getBoard().get(position);
		context.enableDepthTest();
		EmiChess chess = EmiChess.get();
		if (chess.pendingPromotion != -1) {
			PieceType type = null;
			int dir = chess.pendingPromotion > 31 ? -8 : 8;
			if (position == chess.pendingPromotion) {
				type = PieceType.QUEEN;
			} else if (position == chess.pendingPromotion + dir) {
				type = PieceType.KNIGHT;
			} else if (position == chess.pendingPromotion + dir * 2) {
				type = PieceType.ROOK;
			} else if (position == chess.pendingPromotion + dir * 3) {
				type = PieceType.BISHOP;
			}
			if (type != null) {
				context.push();
				context.matrices().translate(0, 0, 10);
				context.fill(x - 1, y - 1, 18, 18, 0x55000000);
				context.matrices().translate(0, 0, 90);
				context.drawTexture(EmiRenderHelper.PIECES, x, y, 100, type.u, chess.pendingPromotion > 31 ? 0 : 16, 16, 16, 256, 256);
				context.pop();
				return;
			}
		}
		context.push();
		context.matrices().translate(0, 0, 10);
		if (chess.isTarget(position)) {
			context.fill(x - 1, y - 1, 18, 18, 0x5555ff00);
		}
		boolean dragging = !EmiScreenManager.draggedStack.isEmpty();
		ChessMove move = chess.board.lastMove;
		if (!dragging &&move != null && (move.start() == position || move.end() == position)) {
			context.fill(x - 1, y - 1, 18, 18, 0x55aaaa00);
		}
		if (!dragging && piece != null && piece.type() == PieceType.KING && chess.board.isChecked(piece.color())) {
			context.fill(x - 1, y - 1, 18, 18, 0x55ff0000);
		}
		context.pop();
		if (piece != null) {
			context.push();
			context.matrices().translate(0, 0, 100);
			context.drawTexture(EmiRenderHelper.PIECES, x, y, 100, piece.type().u, piece.color() == PieceColor.BLACK ? 0 : 16, 16, 16, 256, 256);
			context.pop();
		}
	}

public void tick(Level level) {
        boolean doManaRegen = level.getServer().getTickCount() % MANA_REGEN_TICKS == 0;

        level.players().stream().toList().forEach(player -> {
            if (player instanceof ServerPlayer serverPlayer) {
                MagicData playerMagicData = MagicData.getPlayerMagicData(serverPlayer);
                playerMagicData.getPlayerCooldowns().tick(1);
                playerMagicData.getPlayerRecasts().tick(2);

                if (playerMagicData.isCasting()) {
                    var spell = SpellRegistry.getSpell(playerMagicData.getCastingSpellId());
                    if ((spell.getCastType() == CastType.LONG && !serverPlayer.isUsingItem()) || spell.getCastType() == CastType.INSTANT) {
                        if (playerMagicData.getCastDurationRemaining() <= 0) {
                            spell.castSpell(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData.getCastSource(), true);
                            if (playerMagicData.getCastSource() == CastSource.SCROLL) {
                                Scroll.attemptRemoveScrollAfterCast(serverPlayer);
                            }
                            spell.onServerCastComplete(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData, false);
                        }
                    } else if (spell.getCastType() == CastType.CONTINUOUS) {
                        if ((playerMagicData.getCastDurationRemaining()) % CONTINUOUS_CAST_TICK_INTERVAL == 0) {
                            if (playerMagicData.getCastDurationRemaining() <= 0 || (playerMagicData.getCastSource().consumesMana() && playerMagicData.getMana() - spell.getManaCost(playerMagicData.getCastingSpellLevel()) * 2 < 0)) {
                                spell.castSpell(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData.getCastSource(), true);

                                if (playerMagicData.getCastSource() == CastSource.SCROLL) {
                                    Scroll.attemptRemoveScrollAfterCast(serverPlayer);
                                }

                                spell.onServerCastComplete(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData, false);

                            } else {
                                spell.castSpell(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData.getCastSource(), false);
                            }
                        }
                    }
                    playerMagicData.handleCastDuration();
                    if (playerMagicData.isCasting()) {
                        spell.onServerCastTick(serverPlayer.level, playerMagicData.getCastingSpellLevel(), serverPlayer, playerMagicData);
                    }
                }

                if (doManaRegen) {
                    if (regenPlayerMana(serverPlayer, playerMagicData)) {
                        PacketDistributor.sendToPlayer(serverPlayer, new SyncManaPacket(playerMagicData));
                    }
                }
            }
        });
    }

