private static void validateSideConfigs(MekGameTestHelper helper, Collection<DeferredHolder<Block, ? extends Block>> blocks) {
        BlockPos center = helper.absolutePos(new BlockPos(0, 1, 0));
        for (DeferredHolder<Block, ? extends Block> holder : blocks) {
            Block block = holder.get();
            ItemStack stack = new ItemStack(block);
            if (!stack.isEmpty() && block instanceof IHasTileEntity<?> hasTileEntity &&
                //TODO: Would we rather actually place the block?
                hasTileEntity.newBlockEntity(center, block.defaultBlockState()) instanceof TileEntityConfigurableMachine configurable) {
                if (stack.get(MekanismDataComponents.EJECTOR) == null) {
                    helper.fail("Block " + holder.getId() + " is missing a default ejector data component");
                }
                AttachedSideConfig defaultConfig = stack.get(MekanismDataComponents.SIDE_CONFIG);
                if (defaultConfig == null) {
                    helper.fail("Block " + holder.getId() + " is missing a default side config data component");
                } else {
                    TileComponentConfig config = configurable.getConfig();
                    Set<TransmissionType> keys = defaultConfig.configInfo().keySet();
                    Set<TransmissionType> transmissionTypes = EnumSet.copyOf(config.getTransmissions());
                    if (!keys.containsAll(transmissionTypes)) {
                        helper.fail("Block " + holder.getId() + " is missing side configs for the following transmission types: " +
                                    Sets.difference(transmissionTypes, keys).stream().map(TransmissionType::getTransmission).collect(Collectors.joining(", ")));
                    } else if (keys.size() != transmissionTypes.size()) {
                        helper.fail("Block " + holder.getId() + " has side configs for the following transmission types, but the BE doesn't: " +
                                    Sets.difference(keys, transmissionTypes).stream().map(TransmissionType::getTransmission).collect(Collectors.joining(", ")));
                    } else {
                        for (Entry<TransmissionType, LightConfigInfo> entry : defaultConfig.configInfo().entrySet()) {
                            TransmissionType type = entry.getKey();
                            ConfigInfo info = config.getConfig(type);
                            helper.assertTrue(info != null, "Config " + type.getTransmission() + " cannot be null");
                            for (RelativeSide side : entry.getValue().sideConfig().keySet()) {
                                //noinspection DataFlowIssue (nullability checked by above assertTrue call)
                                if (!info.isSideEnabled(side)) {
                                    helper.fail("Block " + holder.getId() + " has side config for type: " + type.getTransmission() + " on side: " +
                                                side.name() + ", but the BE has side configs disabled on that side.");
                                }
                            }
                        }
                    }
                }
            } else if (!stack.isEmpty()) {
                if (stack.get(MekanismDataComponents.EJECTOR) != null) {
                    helper.fail("Block " + holder.getId() + " is has a default ejector data component, but the tile doesn't");
                }
                if (stack.get(MekanismDataComponents.SIDE_CONFIG) != null) {
                    helper.fail("Block " + holder.getId() + " is has a default side config data component, but the tile doesn't");
                }
            }
        }
    }

@Override
	protected void onHit(HitResult result) {
		if (!this.level().isClientSide) {

			this.clearInvincibility();

			if (result.getType() == HitResult.Type.ENTITY) {
				Entity entity = ((EntityHitResult) result).getEntity();

				if (entity == this.getOwner())
					return;

				if (this.getOwner() != null) {
					if (entity.hurt(entity.damageSources().indirectMagic(this, this.getOwner()), this.isSkullInvulnerable() ? 24.0F : 8.0F)) {
						if (entity.isAlive()) {
							this.doEnchantDamageEffects((LivingEntity) this.getOwner(), entity);
						}
					}
				} else {
					entity.hurt(entity.damageSources().magic(), this.isSkullInvulnerable() ? 16.0F : 5.0F);
				}

				if (entity instanceof LivingEntity) {

					((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.WITHER, 20 * 30, 1));

				}
			}

			float explosionRadius = this.isSkullInvulnerable() ? 1.5F : 1.0F;
			WitherExplosion explosion = new WitherExplosion(this.level(), this, this.getX(), this.getY(), this.getZ(), explosionRadius, false, Explosion.BlockInteraction.DESTROY);


			if (!net.minecraftforge.event.ForgeEventFactory.onExplosionStart(this.level(), explosion)) {
				explosion.explode();
				explosion.finalizeExplosion(true);

				for(ServerPlayer serverPlayer : this.level().getServer().getLevel(this.level().dimension()).players()) {
					if (serverPlayer.distanceToSqr(explosion.getPosition().x, explosion.getPosition().y, explosion.getPosition().z) < 4096.0D) {
						serverPlayer.connection.send(new ClientboundExplodePacket(explosion.getPosition().x, explosion.getPosition().y, explosion.getPosition().z, explosionRadius, explosion.getToBlow(), explosion.getHitPlayers().get(serverPlayer)));
					}
				}
			}

			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketWitherParticles(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), this.isSkullInvulnerable() ? 20 : 16, false));

			this.discard();
		}

	}

@Override
	public void curioTick(SlotContext context, ItemStack stack) {
		if (context.entity() instanceof Player player && !player.level().isClientSide) {
			if (!player.getCooldowns().isOnCooldown(this)) {
				List<BlockPos> doomedWaterBlocks = new ArrayList<BlockPos>();
				BlockPos initialPos = this.getCollidedWater(FluidTags.WATER, player);
				BlockState initialState = initialPos != null ? player.level().getBlockState(initialPos) : null;

				if (initialPos != null && initialState != null)
					if (initialState.getFluidState() != null && initialState.getFluidState().is(FluidTags.WATER)) {

						doomedWaterBlocks.add(initialPos);
						List<BlockPos> processedBlocks = new ArrayList<BlockPos>();
						processedBlocks.add(initialPos);

						for (int counter = 0; counter <= radius.getValue(); counter++) {
							List<BlockPos> outputBlocks = new ArrayList<BlockPos>();

							for (BlockPos checkedPos : processedBlocks) {
								outputBlocks.addAll(this.getNearbyWater(player.level(), checkedPos));
							}

							processedBlocks.clear();

							for (BlockPos thePos : outputBlocks) {
								if (!doomedWaterBlocks.contains(thePos)) {
									processedBlocks.add(thePos);
									doomedWaterBlocks.add(thePos);
								}
							}

							outputBlocks.clear();
						}

						processedBlocks.clear();

						for (BlockPos exterminatedBlock : doomedWaterBlocks) {
							this.absorbWaterBlock(exterminatedBlock, player.level().getBlockState(exterminatedBlock), player.level());
						}

						doomedWaterBlocks.clear();

						player.level().playSound(null, player.blockPosition(), SoundEvents.BUCKET_FILL, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 64, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 40, 1.0D, false));
						player.getCooldowns().addCooldown(this, 20);

					}
			}
		}
	}

public void itemReceived(DisplayLinkBlockEntity be, int amount) {
		if (be.getBlockState()
			.getOptionalValue(DisplayLinkBlock.POWERED)
			.orElse(true))
			return;

		CompoundTag conf = be.getSourceConfig();
		long gameTime = be.getLevel()
			.getGameTime();

		if (!conf.contains("LastReceived")) {
			conf.putLong("LastReceived", gameTime);
			return;
		}

		long previousTime = conf.getLong("LastReceived");
		ListTag rates = conf.getList("PrevRates", Tag.TAG_FLOAT);

		if (rates.size() != POOL_SIZE) {
			rates = new ListTag();
			for (int i = 0; i < POOL_SIZE; i++)
				rates.add(FloatTag.valueOf(-1));
		}

		int poolIndex = conf.getInt("Index") % POOL_SIZE;
		rates.set(poolIndex, FloatTag.valueOf((float) (amount / (double) (gameTime - previousTime))));

		float rate = 0;
		int validIntervals = 0;
		for (int i = 0; i < POOL_SIZE; i++) {
			float pooledRate = rates.getFloat(i);
			if (pooledRate >= 0) {
				rate += pooledRate;
				validIntervals++;
			}
		}

		conf.remove("Rate");
		if (validIntervals > 0) {
			rate /= validIntervals;
			conf.putFloat("Rate", rate);
		}

		conf.remove("Inactive");
		conf.putInt("LastReceivedAmount", amount);
		conf.putLong("LastReceived", gameTime);
		conf.putInt("Index", poolIndex + 1);
		conf.put("PrevRates", rates);
		be.updateGatheredData();
	}

