        if(!startPos.equals(this.getPosition())) {
            prevPos = this.getPosition();
        }
    }

@Override
    public void onUpdate() {
        BlockPos startPos = this.getPosition();
        if(!world.isRemote) {
            BlockPos rail = getPosition();
            boolean isRails = world.getBlockState(rail).getBlock() instanceof TourRailBlock;
            if(!isRails) {
                rail = rail.down();
                isRails = world.getBlockState(rail).getBlock() instanceof TourRailBlock;
            }
            if(!isRails && world.getBlockState(rail.down()).getBlock() instanceof TourRailBlock && Arrays.asList(TourRailBlock.EnumRailDirection.ASCENDING_EAST, TourRailBlock.EnumRailDirection.ASCENDING_NORTH, TourRailBlock.EnumRailDirection.ASCENDING_SOUTH, TourRailBlock.EnumRailDirection.ASCENDING_WEST).contains(TourRailBlock.getRailDirection(world, rail.down()))) {
                rail = rail.down(1);
                isRails = world.getBlockState(rail).getBlock() instanceof TourRailBlock;
            }

            if(onRails != isRails) {
                if(isRails) {
                    minecart.isInReverse = lastDirBackwards;
                }
                onRails = isRails;
                RebornMod.NETWORK_WRAPPER.sendToDimension(new MonorailChangeStateMessage(this), world.provider.getDimension());
            }
            this.railTracks = isRails ? rail : INACTIVE;
            if(!this.railTracks.equals(prevRailTracks)) {
                RebornMod.NETWORK_WRAPPER.sendToDimension(new MonorailUpdatePositionStateMessage(this, rail), world.provider.getDimension());
            }
            this.prevRailTracks = railTracks;
        }
        if(onRails) {
            this.setSize(0.75F, 0.25F);
//			this.stepHeight = 0F;
        } else {
            this.setSize(3.0F, 2.5F);
//			this.stepHeight = 1.5F;
        }
        this.setPosition(this.posX, this.posY, this.posZ); //Make sure that the car is in the right position. Can cause issues when changing size of car
        super.onUpdate();
        if(onRails) {
            minecart.onUpdate();
            Vector4d vec = wheeldata.carVector;
            this.backValue.setTarget(this.calculateWheelHeight(vec.y, false));
            this.frontValue.setTarget(this.calculateWheelHeight(vec.w, false));
            this.leftValue.setTarget(posY);
            this.rightValue.setTarget(posY);
        }
        prevOnRails = onRails;
        if(!startPos.equals(this.getPosition())) {
            prevPos = this.getPosition();
        }
    }

private static void drawLasers(RenderLevelStageEvent event, Vec3 from, HitResult trace, double xOffset, double yOffset, double zOffset, float thickness, Player player, float ticks, float speedModifier) {
        InteractionHand activeHand;
        if (WandUtil.getSpellOnHand(player, InteractionHand.MAIN_HAND) instanceof BurrowingSpell) {
            activeHand = InteractionHand.MAIN_HAND;
        } else {
            activeHand = InteractionHand.OFF_HAND;
        }

        VertexConsumer builder;
        double distance = Math.max(1, from.subtract(trace.getLocation()).length());
        long gameTime = player.level.getGameTime();
        double v = gameTime * speedModifier;
        float additiveThickness = (thickness * 3.5F) * calculateLaserFlickerModifier(gameTime);

        Vec3 view = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
        MultiBufferSource.BufferSource buffer = Minecraft.getInstance().renderBuffers().bufferSource();

        PoseStack matrix = event.getPoseStack();

        matrix.pushPose();

        matrix.translate(-view.x(), -view.y(), -view.z());
        matrix.translate(from.x, from.y, from.z);
        float yaw = MathHelper.positionToYaw(from, trace.getLocation());
        float pitch = MathHelper.positionToPitch(from, trace.getLocation());
        matrix.mulPose(Axis.YP.rotationDegrees(90 - yaw));
        matrix.mulPose(Axis.XP.rotationDegrees(-pitch));

        PoseStack.Pose matrixstack$entry = matrix.last();
        Matrix3f matrixNormal = matrixstack$entry.normal();
        Matrix4f positionMatrix = matrixstack$entry.pose();

        ColorUtil colorUtil = new ColorUtil(0xfff2d2);
        if (WandUtil.getLevels(ModEnchantments.BURNING.get(), player) > 0){
            colorUtil = new ColorUtil(0xff9166);
        }
        //additive laser beam
        builder = buffer.getBuffer(ModRenderType.magicBeam(laserBeam));
        drawBeam(xOffset, yOffset, zOffset, builder, positionMatrix, matrixNormal, additiveThickness, activeHand, distance, 0.5F, 1, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 0.7F);

        //main laser, colored part
        builder = buffer.getBuffer(ModRenderType.magicBeam(laserBeam2));
        drawBeam(xOffset, yOffset, zOffset, builder, positionMatrix, matrixNormal, thickness, activeHand, distance, v, v + distance * 1.5F, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);

        //core
        builder = buffer.getBuffer(ModRenderType.magicBeam(laserBeamGlow));
        drawBeam(xOffset, yOffset, zOffset, builder, positionMatrix, matrixNormal, thickness / 2, activeHand, distance, v, v + distance * 1.5F, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);
        matrix.popPose();
        buffer.endBatch();
    }

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            this.setAngry(this.getTarget() != null);
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            // Random idle animations
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping() && this.getCommandInt() == 0) {
                int i = this.random.nextInt(3000);
                if (i == 13 && !this.isInWater() && this.isNotMoving() && this.canMove()) {
                    this.setSitting(true);
                }
                if (i == 14 && this.isSitting()) {
                    this.setSitting(false);
                }
                if (i > 2980 && !this.isInWater() && this.getHunger() < 60 && this.canMove() && this.getAnimation() == NO_ANIMATION) {
                    if ((this.lastDugPos == null || this.distanceToSqr(this.lastDugPos.getX(), this.getY(), this.lastDugPos.getZ()) > 50) && this.level.getBlockState(this.blockPosition().below()).is(BlockTags.MINEABLE_WITH_SHOVEL)) {
                        this.setAnimation(WORK_DIG);
                        this.lastDugPos = this.blockPosition();
                    }
                }
            }

            if (this.getAnimation() == WORK_DIG && this.getAnimationTick() % 8 == 0) {
                ((ServerLevel)this.level).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, this.level.getBlockState(this.blockPosition().below())), this.getX(), this.getY(), this.getZ(), 20, 0.0D, 0.0D, 0.0D, 0.15F);
                this.playSound(SoundEvents.SHOVEL_FLATTEN, 0.8F, 0.6F);
                if (this.getAnimationTick() == 64) {
                    int rand = this.random.nextInt(6);
                    if (rand == 0) {
                        List<ItemStack> result = EntityUtils.getItemFromLootTable(ModLootTables.LOOT_DIGGING, this.level);
                        for (ItemStack itemstack : result)
                            this.spawnAtLocation(itemstack);
                    }
                    else if (rand == 1) {
                        this.spawnAtLocation(new ItemStack(ModItems.VEGETABLE_AARDVARK_CUCUMBER.get()));
                    }
                }
            }
        }
        if (this.getAnimation() != NO_ANIMATION) {
            if (this.getAnimation() == ATTACK && (this.getAnimationTick() == 8 || this.getAnimationTick() == 12)) {
                this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1.0F, 0.7F);
            }
        }
        super.aiStep();
    }

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.herd == null) {
                IPackEntity.initPack(this);
            }
            else {
                this.herd.tick();
            }
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            // Random idle animations
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                if (this.getCommandInt() == 0) {
                    int i = this.random.nextInt(3000);
                    if (i == 0 && !this.isInWater() && this.isNotMoving() && this.canMove() && this.isActive()) {
                        this.getNavigation().stop();
                        this.setSitting(true);
                    }
                    if ((i == 1 || this.isInWater()) && this.isSitting() && this.getCommandInt() < 2) {
                        this.setSitting(false);
                    }
                    if (i > 2980 && !this.isInWater() && !this.isBaby()) {
