private int placeNonBlockItem(FluidEffectContext.Block context, FluidAction action, Block block, BlockPlaceContext placeContext) {

    // following code is based on block item, with notably differences of not calling block item methods (as if we had one we'd use it above)
    // we do notably call this logic in simulation as we need to stop the block item logic early, differences are noted in comments with their vanilla impacts

    // simulate note: we don't ask the block item for its state for placement as that method is protected, this notably affects signs/banners (unlikely need)
    BlockState state = block.getStateForPlacement(placeContext);
    if (state == null) {
      return 0;
    }

    Level world = context.getLevel();
    BlockPos clicked = placeContext.getClickedPos();
    Player player = context.getPlayer();
    // simulate note: we don't call BlockItem#canPlace as its protected, though never overridden in vanilla
    if (!state.canSurvive(world, clicked) || !world.isUnobstructed(state, clicked, player == null ? CollisionContext.empty() : CollisionContext.of(player))) {
      return 0;
    }
    // at this point the only check we are missing on simulate is actually placing the block failing
    if (action.execute()) {
      // actually place the block
      if (!world.setBlock(clicked, state, Block.UPDATE_ALL_IMMEDIATE)) {
        return 0;
      }
      // if its the expected block, run some criteria stuffs
      BlockState placed = world.getBlockState(clicked);
      ItemStack stack = placeContext.getItemInHand();
      if (placed.is(block)) {
        // difference from BlockItem: do not update block state or block entity from tag as we have no tag
        // it might however be worth passing in a set of properties to set here as part of JSON
        // setPlacedBy only matters when placing from held item
        block.setPlacedBy(world, clicked, placed, player, stack);
        if (player instanceof ServerPlayer serverPlayer) {
          CriteriaTriggers.PLACED_BLOCK.trigger(serverPlayer, clicked, stack);
        }
      }

      // resulting events
      LivingEntity placer = context.getEntity(); // possible that living is nonnull when player is null
      world.gameEvent(GameEvent.BLOCK_PLACE, clicked, GameEvent.Context.of(placer, placed));
      SoundType sound = placed.getSoundType(world, clicked, placer);
      world.playSound(null, clicked, Objects.requireNonNullElse(this.sound, sound.getPlaceSound()), SoundSource.BLOCKS, (sound.getVolume() + 1.0F) / 2.0F, sound.getPitch() * 0.8F);

      // stack might be empty if we failed to find an item form; only matters in null block form anyways
      if ((player == null || !player.getAbilities().instabuild) && !stack.isEmpty()) {
        stack.shrink(1);
      }
    }
    return 1;
  }

@Override
    public void travel(Vec3 travelVector) {
        if (isImmobile() && !isVehicle()) {
            super.travel(Vec3.ZERO);
            return;
        }
        LivingEntity rider = (LivingEntity) getControllingPassenger();
        if (rider == null || !canBeControlledByRider() || !steering.trySteering(rider)) {
            super.travel(travelVector);
            return;
        }
        setYRot(rider.getYRot());
        yRotO = getYRot();
        setXRot(rider.getXRot() * 0.5f);
        setRot(getYRot(), getXRot());
        yBodyRot = getYRot();
        yHeadRot = getYRot();
        float newStrafeMovement = rider.xxa * 0.5f;
        float newForwardMovement = rider.zza;
        boolean fastInWater = aiMovingType() == Moving.AQUATIC || aiMovingType() == Moving.SEMI_AQUATIC;
        if (playerJumpPendingScale > 0) {
            double newYMovement = getJumpStrength() * playerJumpPendingScale * getBlockJumpFactor() + getJumpBoostPower();
            if (isInWater()) {
                if (fastInWater) {
                    doJump(newYMovement, newForwardMovement);
                } else {
                    doJump(newYMovement / 2, newForwardMovement / 2);
                }
            } else if (isOnGround()) {
                doJump(newYMovement, newForwardMovement);
            }
            playerJumpPendingScale = 0;
            //TODO: Fall damage reset
        }
        if (isControlledByLocalInstance()) {
            setSpeed((float) getAttributeValue(Attributes.MOVEMENT_SPEED));
            Vec3 newMovement = new Vec3(newStrafeMovement, travelVector.y, newForwardMovement).scale(0.5);
            if (isInWater()) {
                steering.slowWaterTravel(newMovement);
            } else {
                super.travel(newMovement);
            }
        } else {
            setDeltaMovement(Vec3.ZERO);
            calculateEntityAnimation(this, this instanceof FlyingAnimal);
        }
        if (isOnGround()) {
            playerJumpPendingScale = 0;
        }
    }

@Override
	public void complete(World world, BlockPos pos, ItemStack input, ItemStackHandler inventoryHandler) {
		TileEntity tileEntity = world.getTileEntity(pos.offset(EnumFacing.UP));
		if (!(tileEntity instanceof TileJar)) return;
		TileJar jar = (TileJar) tileEntity;

		ArrayList<ItemStack> stacks = new ArrayList<>();

		for (int i = 0; i < inventoryHandler.getSlots(); i++) {
			if (!inventoryHandler.getStackInSlot(i).isEmpty()) {
				stacks.add(inventoryHandler.getStackInSlot(i));
				inventoryHandler.setStackInSlot(i, ItemStack.EMPTY);
			}
		}

		SpellBuilder builder = new SpellBuilder(stacks);
		List<SpellRing> spell = builder.getSpell();
		if (spell.isEmpty()) return;

		NBTTagList list = new NBTTagList();
		for (SpellRing spellRing : builder.getSpell()) {
			list.appendTag(spellRing.serializeNBT());
		}

		jar.fairy.infusedSpell.clear();
		jar.fairy.infusedSpell.addAll(builder.getSpell());

		PacketHandler.NETWORK.sendToAllAround(new PacketExplode(new Vec3d(pos).add(0.5, 0.5, 0.5), Color.CYAN, Color.BLUE, 2, 2, 500, 300, 20, true),
				new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

		world.playSound(null, pos, ModSounds.BASS_BOOM, SoundCategory.BLOCKS, 1f, (float) RandUtil.nextDouble(1, 1.5));

		List<Entity> entityList = world.getEntitiesWithinAABBExcludingEntity(null, new AxisAlignedBB(pos).grow(32, 32, 32));
		for (Entity entity1 : entityList) {
			double dist = entity1.getDistance(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5);
			final double upperMag = 3;
			final double scale = 0.8;
			double mag = upperMag * (scale * dist / (-scale * dist - 1) + 1);
			Vec3d dir = entity1.getPositionVector().subtract(new Vec3d(pos).add(0.5, 0.5, 0.5)).normalize().scale(mag);

			entity1.motionX = (dir.x);
			entity1.motionY = (dir.y);
			entity1.motionZ = (dir.z);
			entity1.fallDistance = 0;
			entity1.velocityChanged = true;

			if (entity1 instanceof EntityPlayerMP)
				((EntityPlayerMP) entity1).connection.sendPacket(new SPacketEntityVelocity(entity1));
		}
	}

@Override
    public void tick() {
        time++;
        if (task == null || isDone || time > 20 * 10) {
            isDone = true;
            bookwyrm.setHeldStack(ItemStack.EMPTY);
            return;
        }
        if (!reachedFrom) {
            if (BlockUtil.distanceFrom(bookwyrm.level(), bookwyrm.position(), new Vec3(task.from.x, task.from.y(), task.from.z())) <= 1.5) {
                reachedFrom = true;
                if (task != null) {
                    bookwyrm.setHeldStack(task.stack);
                    bookwyrm.level.playSound(null, bookwyrm.getX(), bookwyrm.getY(), bookwyrm.getZ(),
                            SoundEvents.ITEM_PICKUP, bookwyrm.getSoundSource(), 0.3f + (float) ParticleUtil.inRange(-0.1, 0.1), 1.0F + (float) ParticleUtil.inRange(-0.1, 0.1));
                    if (bookwyrm.level instanceof ServerLevel serverLevel) {
                        OpenChestEvent event = new OpenChestEvent(serverLevel, BlockPos.containing(task.from.subtract(0, 1, 0)), 20);
                        event.open();
                        EventQueue.getServerInstance().addEvent(event);
                    }
                    if (bookwyrm.level.getBlockEntity(task.fromPos) instanceof RepositoryCatalogTile controllerTile) {
                        controllerTile.openRandomDrawer();
                    }
                }
            } else {
                bookwyrm.getNavigation().moveTo(task.from.x(), task.from.y(), task.from.z(), 1.3d);
                if (bookwyrm.getNavigation().getPath() == null) {
                    isDone = true;
                }
            }
        } else {
            if (BlockUtil.distanceFrom(bookwyrm.level(), bookwyrm.position(), new Vec3(task.to.x(), task.to.y(), task.to.z())) <= 1.5) {
                isDone = true;
                bookwyrm.setHeldStack(ItemStack.EMPTY);
                if (bookwyrm.level instanceof ServerLevel serverLevel) {
                    OpenChestEvent event = new OpenChestEvent(serverLevel, BlockPos.containing(task.to.subtract(0, 1, 0)), 20);
                    event.open();
                    EventQueue.getServerInstance().addEvent(event);
                }
                if (bookwyrm.level.getBlockEntity(task.toPos) instanceof RepositoryCatalogTile controllerTile) {
                    controllerTile.openRandomDrawer();
                }
            } else {
                bookwyrm.getNavigation().moveTo(task.to.x(), task.to.y(), task.to.z(), 1.3d);
                if (bookwyrm.getNavigation().getPath() == null) {
                    isDone = true;
                }
            }
        }
    }

@TestPlot("mechest_deferred_side_effects")
    public static void testMEChest(PlotBuilder plot) {
        plot.creativeEnergyCell(BlockPos.ZERO.below());
        plot.block(BlockPos.ZERO, AEBlocks.ME_CHEST);

        plot.test(helper -> {
            helper.startSequence()
                    .thenExecute(() -> {
                        var chest = helper.getBlockEntity(BlockPos.ZERO,
                                MEChestBlockEntity.class);

                        // Give the chest an initial cell, then force its storage cache to be built
                        chest.setCell(AEItems.ITEM_CELL_1K.stack());
                        // Store a diamond on the cached cell so we can tell its content apart from the new cell
                        chest.getInventory().insert(AEItemKey.of(Items.DIAMOND), 1, Actionable.MODULATE,
                                IActionSource.empty());

                        var stacksBefore = chest.getInventory().getAvailableStacks();
                        helper.check(stacksBefore.get(AEItemKey.of(Items.DIAMOND)) == 1,
                                "Chest should expose the diamond stored on the first cell", BlockPos.ZERO);

                        var handler = chest.getExposedItemHandler(chest.getFront());
                        helper.check(handler != null, "handler should not be null", BlockPos.ZERO);

                        try (var tx = Transaction.open(null)) {
                            // Swap out the cell for a different, empty one
                            var extracted = handler.extract(ItemResource.of(chest.getCell()), 1, tx);
                            helper.check(extracted == 1, "Should extract old cell", BlockPos.ZERO);

                            var newCell = AEItems.ITEM_CELL_4K.stack();
                            var inserted = handler.insert(ItemResource.of(newCell), 1, tx);
                            helper.check(inserted == 1, "Should insert new cell", BlockPos.ZERO);

                            // The cache is only invalidated on commit, so the chest should still report the
                            // OLD cell's content here even though a different cell now sits in the slot.
                            var stacksDuring = chest.getInventory().getAvailableStacks();
                            helper.check(stacksDuring.get(AEItemKey.of(Items.DIAMOND)) == 1,
                                    "No side-effects during transaction", BlockPos.ZERO);

                            tx.commit();
                        }

                        // After commit, the cache should have been invalidated, so the chest now correctly
                        // reports the new (empty) cell's content instead of the stale old one.
                        var stacksAfter = chest.getInventory().getAvailableStacks();
                        helper.check(stacksAfter.get(AEItemKey.of(Items.DIAMOND)) == 0,
                                "Storage cache invalidated after commit", BlockPos.ZERO);
                    })
                    .thenSucceed();
        });
    }

public void hitEntities() {
        List<Entity> entitiesHit = getEntityLivingBaseNearby(RANGE, RANGE, RANGE, RANGE);
        float damage = DAMAGE_PER_HIT;
        if (getCaster() instanceof EntityFrostmaw) damage *= ConfigHandler.COMMON.MOBS.FROSTMAW.combatConfig.attackMultiplier.get();
        if (getCaster() instanceof Player) damage *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.ICE_CRYSTAL.attackMultiplier.get();
        for (Entity entityHit : entitiesHit) {
            if (entityHit instanceof ItemEntity) continue;
            if (entityHit == getCaster()) continue;
            if (entityHit instanceof ItemEntity) continue;

            if (entityHit.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES) || entityHit instanceof EnderDragon) continue;

            float entityHitYaw = (float) ((Math.atan2(entityHit.getZ() - getZ(), entityHit.getX() - getX()) * (180 / Math.PI) - 90) % 360);
            float entityAttackingYaw = getYRot() % 360;
            if (entityHitYaw < 0) {
                entityHitYaw += 360;
            }
            if (entityAttackingYaw < 0) {
                entityAttackingYaw += 360;
            }
            float entityRelativeYaw = entityHitYaw - entityAttackingYaw;

            float xzDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()));
            double hitY = entityHit.getY() + entityHit.getBbHeight() / 2.0;
            float entityHitPitch = (float) ((Math.atan2((hitY - getY()), xzDistance) * (180 / Math.PI)) % 360);
            float entityAttackingPitch = -getXRot() % 360;
            if (entityHitPitch < 0) {
                entityHitPitch += 360;
            }
            if (entityAttackingPitch < 0) {
                entityAttackingPitch += 360;
            }
            float entityRelativePitch = entityHitPitch - entityAttackingPitch;

            float entityHitDistance = (float) Math.sqrt((entityHit.getZ() - getZ()) * (entityHit.getZ() - getZ()) + (entityHit.getX() - getX()) * (entityHit.getX() - getX()) + (hitY - getY()) * (hitY - getY()));

            boolean inRange = entityHitDistance <= RANGE;
            boolean yawCheck = (entityRelativeYaw <= ARC / 2f && entityRelativeYaw >= -ARC / 2f) || (entityRelativeYaw >= 360 - ARC / 2f || entityRelativeYaw <= -360 + ARC / 2f);
            boolean pitchCheck = (entityRelativePitch <= ARC / 2f && entityRelativePitch >= -ARC / 2f) || (entityRelativePitch >= 360 - ARC / 2f || entityRelativePitch <= -360 + ARC / 2f);
            boolean frostmawCloseCheck = getCaster() instanceof EntityFrostmaw && entityHitDistance <= 2;
            if (inRange && yawCheck && pitchCheck || frostmawCloseCheck) {
                // Do raycast check to prevent damaging through walls
                if (!raytraceCheckEntity(entityHit)) continue;

                if (entityHit.hurt(damageSources().freeze(), damage) && entityHit instanceof LivingEntity) {
                    entityHit.setDeltaMovement(entityHit.getDeltaMovement().multiply(0.25, 1, 0.25));
                    DataHandler.getData(entityHit, DataHandler.FROZEN_DATA).addFreezeProgress((LivingEntity) entityHit, 0.23f);
                }
            }
        }
    }

@SubscribeEvent
	public static void breatheUnderwater(LivingBreatheEvent event) {
		LivingEntity entity = event.getEntity();
		Level level = entity.level();

		if (level.isClientSide)
			entity.getPersistentData().remove("VisualBacktankAir");

		ItemStack helmet = getWornItem(entity);
		if (helmet.isEmpty())
			return;

		boolean lavaDiving = entity.isInLava();
		if (!helmet.has(DataComponents.FIRE_RESISTANT) && lavaDiving)
			return;

		if (event.canBreathe() && !lavaDiving)
			return;

		List<ItemStack> backtanks = BacktankUtil.getAllWithAir(entity);
		if (backtanks.isEmpty())
			return;

		if (lavaDiving) {
			if (entity instanceof ServerPlayer sp)
				AllAdvancements.DIVING_SUIT_LAVA.awardTo(sp);
			if (backtanks.stream()
				.noneMatch(backtank -> backtank.has(DataComponents.FIRE_RESISTANT)))
				return;
		}

		float visualBacktankAir = 0f;
		for (ItemStack stack : backtanks)
			visualBacktankAir += BacktankUtil.getAir(stack);

		if (level.isClientSide)
			entity.getPersistentData()
				.putInt("VisualBacktankAir", Math.round(visualBacktankAir));

		if (level.getGameTime() % 20 == 0)
			BacktankUtil.consumeAir(entity, backtanks.get(0), 1);

		if (lavaDiving)
			return;

		if (entity instanceof ServerPlayer sp)
			AllAdvancements.DIVING_SUIT.awardTo(sp);

		event.setCanBreathe(true);
		event.setRefillAirAmount(entity.getMaxAirSupply());
	}

@Override
    public void onPlayerTickActive(EntityPlayer player, ItemStack stack) {
        if (ElectricItemUtils.getPlayerEnergy(player) > ModuleManager.computeModularProperty(stack, MAGNET_ENERGY_CONSUMPTION)) {
            if ((player.worldObj.getTotalWorldTime() % 20) == 0) {
                ElectricItemUtils.drainPlayerEnergy(player, ModuleManager.computeModularProperty(stack, MAGNET_ENERGY_CONSUMPTION));
            }
            int range = (int) ModuleManager.computeModularProperty(stack, MAGNET_RADIUS);
            World world = player.worldObj;
            AxisAlignedBB bounds = player.getEntityBoundingBox().expand(range, range, range);
            if (FMLCommonHandler.instance().getEffectiveSide() == Side.SERVER) {
                bounds.expand(0.2000000029802322D, 0.2000000029802322D, 0.2000000029802322D);
                if (stack.getItemDamage() >> 1 >= 7) {
                    List<EntityArrow> arrows = world.getEntitiesWithinAABB(EntityArrow.class, bounds);
                    for (EntityArrow arrow : arrows) {
                        if ((arrow.pickupStatus == EntityArrow.PickupStatus.ALLOWED) && (world.rand.nextInt(6) == 0)) {
                            EntityItem replacement = new EntityItem(world, arrow.posX, arrow.posY, arrow.posZ, new ItemStack(Items.ARROW));
                            world.spawnEntityInWorld(replacement);
                        }
                        world.removeEntity(arrow);
                    }
                }
            }
            List<EntityItem> list = world.getEntitiesWithinAABB(EntityItem.class, bounds);
            for (EntityItem e : list) {
                if (!e.cannotPickup()) {
//                    getAge() >= 10
                    double x = player.posX - e.posX;
                    double y = player.posY - e.posY;
                    double z = player.posZ - e.posZ;

                    double length = Math.sqrt(x * x + y * y + z * z) * 0.75D;

                    x = x / length + player.motionX * 22.0D;
                    y = y / length + player.motionY / 22.0D;
                    z = z / length + player.motionZ * 22.0D;

                    e.motionX = x;
                    e.motionY = y;
                    e.motionZ = z;
                    e.isAirBorne = true;
                    if (e.isCollidedHorizontally) {
                        e.motionY += 1.0D;
                    }
                    if (world.rand.nextInt(20) == 0) {
                        float pitch = 0.85F - world.rand.nextFloat() * 3.0F / 10.0F;
                        world.playSound(e.posX, e.posY, e.posZ, SoundEvent.REGISTRY.getObject(new ResourceLocation("entity.endermen.teleport")), SoundCategory.PLAYERS, 0.6F, pitch, true);
                    }
                }
            }
        }
    }

private void work() {
        if (this.level != null) {
            if (!this.itemStack.isEmpty()) {
                int i = 1;
                if (!this.itemStack.getAllEnchantments().isEmpty()) {
                    i += this.itemStack.getAllEnchantments().size();
                }
                if (this.cursedCageTile.getSouls() > (MainConfig.SoulMenderCost.get() * i)) {
                    if (this.itemStack.getItem() instanceof ITotem){
                        if (!ITotem.isFull(this.itemStack)) {
                            if (this.level.getGameTime() % (MathHelper.secondsToTicks(MainConfig.SoulMenderSeconds.get().floatValue()) + 1) == 0) {
                                ITotem.increaseSouls(this.itemStack, 1);
                                this.cursedCageTile.decreaseSouls(1);
                            }
                            if (this.level.random.nextInt(24) == 0) {
                                this.level.playSound(null, this.getBlockPos(), SoundEvents.FIRE_AMBIENT, SoundSource.BLOCKS, 1.0F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F);
                            }
                        } else {
                            ItemStack finished = this.itemStack.copy();
                            this.itemStack.shrink(1);
                            this.finishParticles();
                            this.markUpdated();
                            if (!this.tryDepositItem(finished)) {
                                BlockPos blockpos = this.getBlockPos();
                                Vec3 vec3 = Vec3.atCenterOf(blockpos);
                                dropItemStack(this.level, vec3.x, vec3.y, vec3.z, finished);
                            }
                        }
                    } else if (this.itemStack.isDamaged()) {
                        if (this.level.getGameTime() % (MathHelper.secondsToTicks(MainConfig.SoulMenderSeconds.get().floatValue()) + 1) == 0) {
                            this.itemStack.setDamageValue(this.itemStack.getDamageValue() - 1);
                            this.cursedCageTile.decreaseSouls(MainConfig.SoulMenderCost.get() * i);
                        }
                        if (this.level.random.nextInt(24) == 0) {
                            this.level.playSound(null, this.getBlockPos(), SoundEvents.FIRE_AMBIENT, SoundSource.BLOCKS, 1.0F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F);
                        }
                    } else {
                        ItemStack finished = this.itemStack.copy();
                        this.itemStack.shrink(1);
                        this.finishParticles();
                        this.markUpdated();
                        if (!this.tryDepositItem(finished)) {
                            BlockPos blockpos = this.getBlockPos();
                            Vec3 vec3 = Vec3.atCenterOf(blockpos);
                            dropItemStack(this.level, vec3.x, vec3.y, vec3.z, finished);
                        }
                    }
                }
            }
        }
    }

public static void consume(CStopAttackPacket packet, Supplier<NetworkEvent.Context> ctx) {
        ctx.get().enqueueWork(() -> {
            ServerPlayer playerEntity = ctx.get().getSender();

            if (playerEntity != null) {
                if (playerEntity.level instanceof ServerLevel serverLevel){
                    for (Entity entity : serverLevel.getAllEntities()){
                        if (entity instanceof IOwned owned && entity instanceof Mob mob && owned.getTrueOwner() == playerEntity){
                            Entity pick = MobUtil.getSingleTarget(serverLevel, playerEntity, 16, 3);
                            if (pick instanceof LivingEntity target
                                    && target != mob
                                    && target != owned.getTrueOwner()
                                    && !MobUtil.areAllies(playerEntity, target)
                                    && mob.distanceTo(playerEntity) <= 32){
                                mob.setTarget(target);
                                if (mob.getLastHurtByMob() != target){
                                    mob.setLastHurtByMob(target);
                                }
                                entity.playSound(ModSounds.ROAR_SPELL.get(), 0.5F, 2.0F);
                                owned.onStopAttack();
                            } else {
                                owned.onCeaseFire(playerEntity);
                                if (mob.getTarget() != null) {
                                    mob.setTarget(null);
                                    if (mob.getLastHurtByMob() != null){
                                        mob.setLastHurtByMob(null);
                                    }
                                    if (playerEntity.getLastHurtMob() != null) {
                                        playerEntity.setLastHurtMob(null);
                                    }
                                    if (mob.getBrain() != null) {
                                        mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                                        mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                                        mob.getBrain().eraseMemory(MemoryModuleType.HURT_BY);
                                    }
                                    if (mob instanceof NeutralMob neutralMob) {
                                        neutralMob.setPersistentAngerTarget(null);
                                        neutralMob.stopBeingAngry();
                                    }
                                    mob.setAggressive(false);
                                    entity.playSound(ModSounds.CAST_SPELL.get(), 1.0F, 1.0F);
                                    owned.onStopAttack();
                                }
                            }
                        }
                    }
                }
            }
        });
        ctx.get().setPacketHandled(true);
    }

