private void recheckConnectionPrechecked(Direction side) {
        TileEntityTransmitter otherTile = WorldUtils.getTileEntity(TileEntityTransmitter.class, getLevel(), getBlockPos().relative(side));
        if (otherTile != null) {
            NETWORK network = getTransmitterNetworkNN();
            //The other one should always have the same incompatible networks state as us
            // But just in case it doesn't just check the boolean
            Transmitter<?, ?, ?> other = otherTile.getTransmitter();
            if (other instanceof BufferedTransmitter && ((BufferedTransmitter<?, ?, ?, ?>) other).canHaveIncompatibleNetworks() && other.hasTransmitterNetwork()) {
                NETWORK otherNetwork = (NETWORK) other.getTransmitterNetworkNN();
                if (network != otherNetwork && network.isCompatibleWith(otherNetwork)) {
                    //We have two networks that are now compatible, and they are not the same source network
                    // The most common cause that they would be same source network is that they would merge
                    // from the first pipe checking when it attempts to reconnect, and then the second
                    // pipe still is going to be checking the connection.

                    if (noBufferOrFallback()) {
                        //If we don't have any use them as primary network
                        NETWORK tempNetwork = network;
                        network = otherNetwork;
                        otherNetwork = tempNetwork;
                    }

                    // Manually merge the networks.
                    // This code is not in network registry as there is special handling needed to ensure
                    // it visually updates properly. There also were above checks that get us to a certain
                    // point where we can make some assumptions about the networks and if it is actually
                    // valid to merge them when otherwise people may try to merge things when they shouldn't
                    // be merged causing unexpected bugs.
                    List<TRANSMITTER> otherTransmitters = network.adoptTransmittersAndAcceptorsFrom(otherNetwork);

                    //Unregister the other network
                    otherNetwork.deregister();
                    //Commit the changes of the new network
                    network.commit();

                    //We did not have these as part of the update because they got directly added
                    // This means that we have to update the buffer and queue client updates ourselves
                    network.clampBuffer();
                    //Recheck the connections
                    other.refreshConnections(side.getOpposite());
                    //Force all the newly merged transmitters to send a sync update to the client
                    // to ensure that they now have the proper network id on the client
                    // Note: adoptTransmittersAndAcceptorsFrom will return all the new transmitters except for
                    // those that already have our network as their network (which should be none of them)
                    for (TRANSMITTER otherTransmitter : otherTransmitters) {
                        otherTransmitter.requestsUpdate();
                    }
                }
            }
        }
    }

public boolean canUse() {
        long worldTime = this.ant.level().getGameTime() % 10;
        if (this.ant.getNoActionTime() >= 100 && worldTime != 0) {
            return false;
        }
        if (this.ant.getRandom().nextInt(this.executionChance) != 0 && worldTime != 0) {
            return false;
        }
        if (!this.ant.shouldLeadCaravan() && !ant.isBaby() && !this.ant.isQueen() && !this.ant.inCaravan() && !this.ant.hasLeaf()) {
            double dist = 15D;
            List<EntityLeafcutterAnt> list = ant.level().getEntitiesOfClass(EntityLeafcutterAnt.class, ant.getBoundingBox().inflate(dist, dist/2, dist));
            EntityLeafcutterAnt LeafcutterAnt = null;
            double d0 = Double.MAX_VALUE;

            for(Entity entity : list) {
                EntityLeafcutterAnt LeafcutterAnt1 = (EntityLeafcutterAnt)entity;
                if (LeafcutterAnt1.inCaravan() && !LeafcutterAnt1.hasCaravanTrail()) {
                    double d1 = this.ant.distanceToSqr(LeafcutterAnt1);
                    if (!(d1 > d0)) {
                        d0 = d1;
                        LeafcutterAnt = LeafcutterAnt1;
                    }
                }
            }

            if (LeafcutterAnt == null) {
                for(Entity entity1 : list) {
                    EntityLeafcutterAnt llamaentity2 = (EntityLeafcutterAnt)entity1;
                    if (llamaentity2.shouldLeadCaravan() && !llamaentity2.hasCaravanTrail()) {
                        double d2 = this.ant.distanceToSqr(llamaentity2);
                        if (!(d2 > d0)) {
                            d0 = d2;
                            LeafcutterAnt = llamaentity2;
                        }
                    }
                }
            }

            if (LeafcutterAnt == null) {
                return false;
            } else if (d0 < 2.0D) {
                return false;
            } else if (!LeafcutterAnt.shouldLeadCaravan() && !this.firstIsSilverback(LeafcutterAnt, 1)) {
                return false;
            } else {
                this.ant.joinCaravan(LeafcutterAnt);
                return true;
            }
        } else {
            return false;
        }
    }

@Override
    public void tick() {
        super.tick();
        if (tickCount == 1) {
            if (level().isClientSide) {
                MMCommon.PROXY.playIceBreathSound(this);
            }
        }
        if (tickCount > 1 && getCaster() == null) this.discard() ;
        if (getCaster() != null && !getCaster().isAlive()) this.discard() ;
        if (tickCount == 1) playSound(MMSounds.ENTITY_FROSTMAW_ICEBREATH_START.get(), 1, 0.6f);
        if (getCaster() instanceof Player player) {
            absMoveTo(player.getX(), player.getEyeY() - 0.5f, player.getZ(), player.getYRot(), player.getXRot());
            AbilityData abilityData = DataHandler.getData(player, DataHandler.ABILITY_DATA);
            if (!abilityData.getAbilityFromType(AbilityHandler.ICE_BREATH_ABILITY).isUsing()) {
                this.discard();
            }
        }

        float yaw = (float) Math.toRadians(-getYRot());
        float pitch = (float) Math.toRadians(-getXRot());
        float spread = 0.25f;
        float speed = 0.56f;
        float xComp = (float) (Math.sin(yaw) * Math.cos(pitch));
        float yComp = (float) (Math.sin(pitch));
        float zComp = (float) (Math.cos(yaw) * Math.cos(pitch));
        if (level().isClientSide) {
            Camera camera = Minecraft.getInstance().gameRenderer.getMainCamera();
            boolean overrideLimiter = camera.getPosition().distanceToSqr(getX(), getY(), getZ()) < 64 * 64;
            if (tickCount % 8 == 0) {
                level().addAlwaysVisibleParticle(new ParticleRing.Data(yaw, -pitch, 40, 1f, 1f, 1f, 1f, (int) (110 * spread), false, ParticleRing.EnumRingBehavior.GROW), overrideLimiter, getX(), getY(), getZ(), 0.5f * xComp, 0.5f * yComp, 0.5f * zComp);
            }

            for (int i = 0; i < 6; i++) {
                double xSpeed = speed * 1f * xComp;// + (spread * (rand.nextFloat() * 2 - 1) * (1 - Math.abs(xComp)));
                double ySpeed = speed * 1f * yComp;// + (spread * (rand.nextFloat() * 2 - 1) * (1 - Math.abs(yComp)));
                double zSpeed = speed * 1f * zComp;// + (spread * (rand.nextFloat() * 2 - 1) * (1 - Math.abs(zComp)));
                level().addParticle(new ParticleSnowFlake.Data(37f, true), getX(), getY(), getZ(), xSpeed, ySpeed, zSpeed);
            }
            for (int i = 0; i < 5; i++) {
                double xSpeed = speed * xComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - xComp * xComp)));
                double ySpeed = speed * yComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - yComp * yComp)));
                double zSpeed = speed * zComp + (spread * 0.7 * (random.nextFloat() * 2 - 1) * (Math.sqrt(1 - zComp * zComp)));
                float value = random.nextFloat() * 0.15f;
                level().addAlwaysVisibleParticle(new ParticleCloud.Data(0.75f + value, 0.75f + value,1f, 10f + random.nextFloat() * 20f, 40, ParticleCloud.EnumCloudBehavior.GROW, 1f), overrideLimiter, getX(), getY(), getZ(), xSpeed, ySpeed, zSpeed);
            }
        }
        if (tickCount > 10) hitEntities();
        if (tickCount > 10) freezeBlocks();

        if (tickCount > 65 && !(getCaster() instanceof Player)) discard() ;
    }

@Override
    public void render(PoseStack pMatrixStack, Camera pActiveRenderInfo, float pPartialTicks, Predicate<ParticleRenderType> renderTypeFilter) {
        drawMode = options.getDrawMode();
        sceneBloomEnabled = options.isBloomEnabled();
        renderingManager = this;
        lastPartialTick = pPartialTicks;
        // route post-effect submission/consumption to the isolated editor-scene stack
        com.lowdragmc.photon.client.postfx.runtime.PostEffectStack.setEditorSceneRendering(true);
        com.lowdragmc.photon.client.postfx.runtime.PostEffectStack.EDITOR_SCENE
                .setEffectsEnabled(options.isEffectsEnabled());
        if (options.isMaskViewEnabled()) {
            // top-bar debug toggle: show the CustomMask contents instead of the scene this frame
            com.lowdragmc.photon.client.postfx.runtime.PostEffectStack.EDITOR_SCENE.submit(
                    com.lowdragmc.lowdraglib2.editor.resource.BuiltinResourceProvider.TYPE.createFullPath("show_mask"),
                    java.util.Map.of(), 1f);
        }
        RenderSystem.setShaderGameTime(getRealTime(), isPlaying ? pPartialTicks : 0);
        // The scene's own camera for post-effect world reconstruction (the game camera would be wrong here).
        // LDLib2's ParticleManager multiplies pMatrixStack onto the model-view stack around the draws, so
        // this is exactly the ModelViewMat the particles — and the scene's effect chain — are rendered with.
        PostFXCamera.captureSubViewport(
                new Matrix4f(RenderSystem.getModelViewMatrix()).mul(pMatrixStack.last().pose()),
                RenderSystem.getProjectionMatrix(), pActiveRenderInfo.getPosition());

        var startTime = System.nanoTime();
        GlStateManager._disableScissorTest();
        boolean translucentPass = renderTypeFilter.test(ParticleRenderType.PARTICLE_SHEET_TRANSLUCENT);
        // the first call of a frame: blocks drawn, particles not, the scene's own AFTER_BLOCK_ENTITIES
        if (!sceneLit && level != null && options.isDynamicLightsEnabled()) {
            sceneLit = true;
            DynamicLightRenderer.beginScene(level, new Matrix4f(RenderSystem.getModelViewMatrix()).mul(pMatrixStack.last().pose()),
                    RenderSystem.getProjectionMatrix(), pActiveRenderInfo.getPosition(), isPlaying ? pPartialTicks : 0);
        }
        super.render(pMatrixStack, pActiveRenderInfo, isPlaying ? pPartialTicks : 0, renderTypeFilter);
        consumeEditorEffectsWithoutParticles(renderTypeFilter);
        if (translucentPass && sceneLit) {
            sceneLit = false;
            DynamicLightRenderer.endScene();
        }
        GlStateManager._enableScissorTest();
        lastFrameTimes[frameIndex] = System.nanoTime() - startTime;
        frameIndex = (frameIndex + 1) % lastFrameTimes.length;

        // roll back to previous game time
        if (Minecraft.getInstance().level != null) {
            RenderSystem.setShaderGameTime(Minecraft.getInstance().level.getGameTime(), pPartialTicks);
        }
        drawMode = null;
        sceneBloomEnabled = true;
        renderingManager = null;
        com.lowdragmc.photon.client.postfx.runtime.PostEffectStack.setEditorSceneRendering(false);
    }

public void use(int hammerLevel, float hammerEfficiency, float angle) {
        ServerLevel serverLevel = (ServerLevel) getLevel();
        int count = 4 + (int) hammerEfficiency / 4;
        double cone = (20 + hammerLevel * 6) * Math.PI / 180;
        int ox = SectionPos.blockToSectionCoord(getBlockPos().getX());
        int oz = SectionPos.blockToSectionCoord(getBlockPos().getZ());

        int preResultSize = scanResults.size();
        AtomicInteger stagger = new AtomicInteger();

        ChunkPos.rangeClosed(new ChunkPos(-32, -32), new ChunkPos(32, 32))
                .filter(pos -> Math.abs(Mth.atan2(pos.x, pos.z) - angle) < cone)
                .sorted(Comparator.comparingInt(pos -> pos.x * pos.x + pos.z * pos.z))
                .map(pos -> new ChunkPos(pos.x + ox, pos.z + oz))
                .filter(pos -> Math.abs(pos.x - ox) + Math.abs(pos.z - oz) < 20)
                .filter(pos -> scanResults.stream().noneMatch(result -> result.chunkX == pos.x && result.chunkZ == pos.z))
                .limit(count)
                .forEach(pos -> {
//                    boolean wasLoaded = serverLevel.hasChunk(pos.x, pos.z);
//                    System.out.println("has chunk [" + pos.x + ", " + pos.z + "]: " + wasLoaded);
//                    serverLevel.getChunkSource().getGenerator().findNearestMapStructure()
                    long timestamp = this.getTimestamp(serverLevel.getGameTime(), pos.x - ox, pos.z - oz) + stagger.getAndIncrement() * 3L;
                    int height = serverLevel.getChunk(pos.x, pos.z, ChunkStatus.SURFACE).getHeight(Heightmap.Types.WORLD_SURFACE_WG, pos.x, pos.z);

                    BlockPos centerPos = pos.getMiddleBlockPosition(height);
                    float temperature = level.getBiome(centerPos).value().getTemperature(centerPos);
                    List<String> structures =
                            Arrays.stream(getScannableStructures())
                                    .filter(id -> ScanHelper.hasStructure(id, serverLevel, pos)).toList();
                    scanResults.add(new ScanResult(pos.x, pos.z, height, temperature, structures, timestamp));


//                    if (!wasLoaded) {
//                        System.out.println("[post]  Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z));
//                        ServerScheduler.schedule(100, () -> System.out.println("[delayed] Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z)));
//                    }


                    ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime())), () ->
                            serverLevel.playSound(null, getBlockPos(), TetraSounds.scanMiss, SoundSource.PLAYERS, 0.01f, 1.0f + (float) Math.random() * 0f));
                    if (!structures.isEmpty()) {
                        ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime()) + 20), () ->
                                serverLevel.playSound(null, getBlockPos(), TetraSounds.scanHit, SoundSource.PLAYERS, 0.1f, 1.0f));
                    }

                });

        if (preResultSize != scanResults.size()) {
            setChanged();
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

public static void handle(C2SChainedElectricityPacket packet, IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            if (!(ctx.player() instanceof ServerPlayer player) || player.level().isClientSide())
                return;

            var level = player.level();
            var position = new Vec3(packet.x, packet.y, packet.z);
            var slot = CuriosApi.getCuriosInventory(player).flatMap(inventory -> inventory.findCurio(packet.slotId, packet.slotIndex));

            if (slot.isEmpty())
                return;

            var stack = slot.get().stack();

            if (!(stack.getItem() instanceof KineticBeltItem))
                return;

            ChainedElectricityEntity previous = null;
            var previousId = stack.getOrDefault(RelicsDataComponents.KINETIC_BELT_LAST_ELECTRICITY_ID, -1);
            var bestDistance = Double.MAX_VALUE;

            if (previousId >= 0) {
                var raw = level.getEntity(previousId);

                if (raw instanceof ChainedElectricityEntity candidate && candidate.isAlive() && candidate.getOwner() == player) {
                    bestDistance = candidate.position().distanceToSqr(position);

                    if (bestDistance < 1D)
                        return;

                    if (bestDistance <= 100D)
                        previous = candidate;
                }
            }

            var electricity = new ChainedElectricityEntity(RelicsEntities.KINETIC_ELECTRICITY.get(), player.level());

            electricity.setLifetime(Math.max(1, packet.lifetime));
            electricity.setDamage(Math.max(0F, packet.damage));
            electricity.setFlawless(packet.flawless);
            electricity.setPos(position);
            electricity.setOwner(player);
            electricity.setStack(stack);

            if (previous != null && bestDistance <= 100D)
                electricity.setPreviousEntity(previous);

            level.addFreshEntity(electricity);

            stack.set(RelicsDataComponents.KINETIC_BELT_LAST_ELECTRICITY_ID, electricity.getId());
        });
    }

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.isInWater() && this.getTarget() == null) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.01D, 0.0D));
            }
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            int i = this.random.nextInt(3000);
            if (i <= 8 && !this.isInWater() && !this.isAngry() && !this.isSleeping() && this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(IDLE_YAWN);
            }
            if ((i > 8 && i <= 12) && !this.isAngry() && !this.isSleeping() && this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(IDLE_LOOK);
            }
            if (i == 13 && !this.isInWater() && this.isNotMoving() && this.canMove() && this.getAnimation() == NO_ANIMATION) {
                this.setSitting(true);
            }
            if (i == 14 && this.isSitting()) {
                this.setSitting(false);
            }
            if (i == 15 && !this.isActive() && !this.isSleeping() && this.isInWater()){
                this.setAnimation(IDLE_YAWN);
                this.setSleeping(true);
                this.forceSleep = -800 - this.random.nextInt(1200);
            }
            if (i > 2980 && !this.isBaby()) {
                this.setAnimation(IDLE_TALK);
            }
            if (this.getAnimation() == ATTACK && this.getTarget() != null && this.getBoundingBox().inflate(1.2F, 1.0F, 1.2F).contains(this.getTarget().getPosition(0)) && (this.getAnimationTick() > 8)) {
                LivingEntity target = this.getTarget();
                this.getTarget().hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                EntityUtils.destroyBoat(this.level, target);
            }
            this.setAngry(this.getTarget() != null);
        }
        if (this.getAnimation() != NO_ANIMATION) {
            if (this.getAnimation() == IDLE_TALK && this.getAnimationTick() == 1 && this.getAmbientSound() != null) {
                this.playSound(this.getAmbientSound(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        if (this.level.isClientSide && this.isAngry() && this.angryProgress < 40) {
            this.angryProgress += 4;
        } else if (this.level.isClientSide && !this.isAngry() && this.angryProgress > 0) {
            this.angryProgress -= 4;
        }
        super.aiStep();
    }

