private static void renderBlockShadow(
        PoseStack.Pose pose,
        VertexConsumer vertexConsumer,
        Entity entity,
        ChunkAccess chunk,
        float partialTicks,
        LevelReader level,
        BlockPos pos,
        double x,
        double y,
        double z,
        ShadowData data,
        int color) {
        BlockPos blockpos = pos;
        BlockState blockstate = chunk.getBlockState(blockpos);
        if (blockstate.getRenderShape() != RenderShape.INVISIBLE) { // Removed the brightness check here
            VoxelShape voxelshape = blockstate.getShape(chunk, blockpos);
            if (!voxelshape.isEmpty() && Block.isFaceFull(voxelshape, Direction.DOWN)) { // Use isFaceFull instead of isCollisionShapeFullBlock to render on top of flat blocks
                // Animation support logic (vanilla shadows are not animated)
                final int frames = data.frames();
                final float frameTime = data.frameTime();
                final float frame = (int) ((Minecraft.getInstance().level.getGameTime() + partialTicks) / frameTime % frames);

                float size = data.size();
                AABB aabb = voxelshape.bounds();
                // So, vanilla cheats to render the shadow. They actually render a bunch of quads outside of the texture space, which renders blank.
                // That works, until you add animation frames into the texture, at which point those off-texture quads are no longer off-texture.
                // This call locks the AABB into the intersection of the top of the block with the entity's BB, so only the real shadow is drawn.
                aabb = aabb.intersect(new AABB(entity.getX() - pos.getX() - size, 0, entity.getZ() - pos.getZ() - size, entity.getX() - pos.getX() + size, aabb.maxY, entity.getZ() - pos.getZ() + size));
                double minX = pos.getX() + aabb.minX;
                double maxX = pos.getX() + aabb.maxX;
                double minY = pos.getY() + aabb.maxY;
                double minZ = pos.getZ() + aabb.minZ;
                double maxZ = pos.getZ() + aabb.maxZ;
                float xi = (float) (minX - x);
                float xp = (float) (maxX - x);
                float yi = (float) (minY - y) + 0.001F; // Apply a slight offset to avoid Z-clipping with the block [Fixes flickering with BSL]
                float zi = (float) (minZ - z);
                float zp = (float) (maxZ - z);

                float u1 = -xi / 2.0F / size + 0.5F;
                float u2 = -xp / 2.0F / size + 0.5F;
                float v1 = -zi / 2.0F / size + 0.5F;
                float v2 = -zp / 2.0F / size + 0.5F;

                shadowVertex(pose, vertexConsumer, color, xi, yi, zi, u1, v1 / frames + frame / frames);
                shadowVertex(pose, vertexConsumer, color, xi, yi, zp, u1, v2 / frames + frame / frames);
                shadowVertex(pose, vertexConsumer, color, xp, yi, zp, u2, v2 / frames + frame / frames);
                shadowVertex(pose, vertexConsumer, color, xp, yi, zi, u2, v1 / frames + frame / frames);
            }
        }
    }

@Override
	protected boolean generate(WorldGenLevel world, RandomSource random, BlockPos pos, BiConsumer<BlockPos, BlockState> trunkPlacer, BiConsumer<BlockPos, BlockState> leavesPlacer, RootPlacer decorationPlacer, TFTreeFeatureConfig config) {
		if (world.isOutsideBuildHeight(pos.getY() + 12)) {
			return false;
		}

		// check soil
		if (world.getBlockState(pos.below()).canSustainPlant(world, pos.below(), Direction.UP, TFBlocks.MINING_SAPLING.get().defaultBlockState()).isFalse()) {
			return false;
		}

		// 9 block high trunk
		for (int dy = 0; dy <= 9; dy++) {
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, random, pos.above(dy), config.trunkProvider);
		}

		// branches with leaf blocks
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 9, 1), true, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 9, 2), false, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 8, 3), false, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 7, 4), false, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 6, 5), false, config);

		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 9, -1), true, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 9, -2), false, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 8, -3), false, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 7, -4), false, config);
		putBranchWithLeaves(world, trunkPlacer, leavesPlacer, random, pos.offset(0, 6, -5), false, config);

		// place minewood core
		BlockState stateAtCorePos = world.getBlockState(pos.above());
		if (stateAtCorePos.is(BlockTags.LOGS) || stateAtCorePos.canBeReplaced()) {
			world.setBlock(pos.above(), TFBlocks.MINING_LOG_CORE.get().defaultBlockState(), Block.UPDATE_ALL);
			world.scheduleTick(pos.above(), TFBlocks.MINING_LOG_CORE.get(), 20);
		}

		// root bulb
		if (FeatureUtil.hasAirAround(world, pos.below())) {
			FeaturePlacers.placeIfValidTreePos(world, trunkPlacer, random, pos.below(), config.trunkProvider);
		} else {
			FeaturePlacers.placeIfValidRootPos(world, decorationPlacer, random, pos.below(), config.rootsProvider);
		}

		// roots!
		int numRoots = 3 + random.nextInt(2);
		float offset = random.nextFloat();
		for (int b = 0; b < numRoots; b++) {
			FeaturePlacers.buildRoot(world, decorationPlacer, random, pos, offset, b, config.rootsProvider);
		}

		return true;
	}

public static void tick(Level level, BlockPos pos, BlockState state, PoweredFramingSawBlockEntity be) {
        if (!Utils.PRODUCTION && INSERT_ENERGY_DEBUG) {
            try (Transaction tx = Transaction.open(null)) {
                be.energyStorage.insert(be.energyStorage.getMaxReceive(), tx);
                tx.commit();
            }
        }

        if ((be.active || level.getGameTime() - be.lastActive > ACTIVE_TIMEOUT) && be.canRun()) {
            if (!be.active) {
                be.active = true;
                level.setBlockAndUpdate(pos, state.setValue(PropertyHolder.ACTIVE, true));
            }

            be.energyStorage.extractEnergyInternal(be.energyConsumption);
            be.progress++;

            if (be.progress >= be.craftingDuration) {
                be.progress = 0;

                ItemResource result = ItemResource.of(Objects.requireNonNull(be.selectedRecipe).value().getResultStack());
                be.internalAccess = true;
                try (Transaction tx = Transaction.open(null)) {
                    be.inhibitUpdate = true;
                    for (int i = 0; i < be.selectedRecipe.value().getAdditives().size(); i++) {
                        int slot = i + FramingSawMenu.SLOT_ADDITIVE_FIRST;
                        int additiveCount = Objects.requireNonNull(be.calculation).getAdditiveCount(i);
                        be.itemHandler.extract(slot, be.itemHandler.getResource(slot), additiveCount, tx);
                    }
                    be.inhibitUpdate = false;
                    int inputCount = Objects.requireNonNull(be.calculation).getInputCount();
                    be.itemHandler.extract(FramingSawMenu.SLOT_INPUT, be.itemHandler.getResource(FramingSawMenu.SLOT_INPUT), inputCount, tx);
                    be.itemHandler.insert(FramingSawMenu.SLOT_RESULT, result, be.outputCount, tx);
                    tx.commit();
                }
                be.internalAccess = false;
            }
        } else if (be.active) {
            be.active = false;
            level.setBlockAndUpdate(pos, state.setValue(PropertyHolder.ACTIVE, false));
            be.lastActive = level.getGameTime();

            if (!be.recipeSatisfied) {
                be.progress = 0;
            }
        }

        if (be.needSaving) {
            level.blockEntityChanged(be.worldPosition);
            be.needSaving = false;
        }
    }

@Override
    public void tick() {
        if (isDecorative && level.isClientSide) {
            makeParticle(color.nextColor((int) level.getGameTime() * 20), color.nextColor((int) level.getGameTime() * 20 + 200), 10);
            return;
        }


        if (level.isClientSide && ritual != null) {
            makeParticle(ritual.getCenterColor(), ritual.getOuterColor(), ritual.getParticleIntensity());
        }
        if (isOff)
            return;
        if (ritual != null) {

            if (ritual.getContext().isDone) {
                ritual.onEnd();
                ritual = null;
                getLevel().playSound(null, getBlockPos(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0f, 1.0f);
                getLevel().setBlock(getBlockPos(), getLevel().getBlockState(getBlockPos()).setValue(RitualBrazierBlock.LIT, false), 3);
                updateBlock();
                return;
            }
            if (!ritual.isRunning() && !level.isClientSide && level.getGameTime() % 5 == 0) {
                level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(1)).forEach(i -> {
                    tryBurnStack(i.getItem());
                });
            }
            if (ritual.consumesSource() && ritual.needsSourceNow()) {
                if (this.sourceBackoff-- <= 0) {
                    int cost = ritual.getSourceCost();
                    if (SourceUtil.takeSourceMultipleWithParticles(getBlockPos(), getLevel(), 6, cost) != null) {
                        ritual.setNeedsSource(false);
                        this.sourceBackoff = 0;
                        updateBlock();
                    } else {
                        this.sourceBackoff = 20;
                        return;
                    }
                } else {
                    return;
                }
            }
            if (this.relayPos != null && level.isLoaded(this.relayPos) && level.getBlockEntity(this.relayPos) instanceof BrazierRelayTile relayTile) {
                ritual.tryTick(relayTile);
                relayTile.ticksToLightOff = 2;
                relayTile.isDecorative = false;
            } else {
                ritual.tryTick(this);
            }
        }
    }

public void tick() {
        this.baseTick();
        if (this.lightningState == 2) {
            Difficulty difficulty = this.level.getDifficulty();

            this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.LIGHTNING_BOLT_THUNDER, SoundSource.WEATHER, 1.0f, 0.8F + this.random.nextFloat() * 0.2F);
            this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.WEATHER, 1.0F, 0.5F + this.random.nextFloat() * 0.2F);
        }

        --this.lightningState;
        if (this.lightningState < 0) {
            if (this.boltLivingTime == 0) {
                this.remove(RemovalReason.DISCARDED);
            } else if (this.lightningState < -this.random.nextInt(10)) {
                --this.boltLivingTime;
                this.lightningState = 1;
                this.boltVertex = this.random.nextLong();
            }
        }

        if (this.lightningState >= 0) {
            if (!(this.level instanceof ServerLevel)) {
                this.level.setSkyFlashTime(2);
            } else if (!this.effectOnly) {
                List<Entity> list = this.level.getEntities(this, new AABB(this.getX() - 3.0D, this.getY() - 3.0D, this.getZ() - 3.0D, this.getX() + 3.0D, this.getY() + 6.0D + 3.0D, this.getZ() + 3.0D), Entity::isAlive);
                for (Entity entity : list) {
                    if (!net.neoforged.neoforge.event.EventHooks.onEntityStruckByLightning(entity, this)) {
                        float origDamage = this.getDamage();
                        this.setDamage(this.getDamage(entity));
                        EntityStruckByLightningEvent event = new EntityStruckByLightningEvent(entity, this);
                        NeoForge.EVENT_BUS.post(event);
                        if (event.isCanceled())
                            continue;
                        entity.thunderHit((ServerLevel) this.level, this);
                        this.setDamage(origDamage);
                        if (!level.isClientSide && !hitEntities.contains(entity.getId()) && entity instanceof LivingEntity) {
                            MobEffectInstance effectInstance = ((LivingEntity) entity).getEffect(ModPotions.SHOCKED_EFFECT);
                            int amp = effectInstance != null ? effectInstance.getAmplifier() : -1;
                            ((LivingEntity) entity).addEffect(new MobEffectInstance(ModPotions.SHOCKED_EFFECT, 200 + 10 * 20 * extendTimes, Math.min(2, amp + 1)));
                        }
                        if (!level.isClientSide && !hitEntities.contains(entity.getId()))
                            hitEntities.add(entity.getId());

                    }
                }

                if (this.caster != null) {
                    CriteriaTriggers.CHANNELED_LIGHTNING.trigger(this.caster, list);
                }
            }
        }
    }

@Override
    protected void tick() {
        Level world = getWorld();
        if (world.isClientSide) {
            BlockPos pos = getPos();

            for (int i = 0; i < 10; i++) {
                Vec3 particlePos = new Vec3(pos.getX(), pos.getY(), pos.getZ()).add(0.5, 0, 0.5);
                particlePos = particlePos.add(ParticleUtil.pointInSphere().multiply(5, 5, 5));
                world.addParticle(ParticleLineData.createData(getCenterColor()),
                        particlePos.x(), particlePos.y(), particlePos.z(),
                        pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5);
            }
        }

        if (!world.isClientSide && world.getGameTime() % 60 == 0) {
            boolean didWorkOnce = false;
            List<LivingEntity> entityList = world.getEntitiesOfClass(LivingEntity.class, new AABB(getPos()).inflate(5.0),
                    (m) -> (m.getClassification(false).equals(MobCategory.MONSTER) || m.getType().is(EntityTags.DISINTEGRATION_WHITELIST)) && !(m instanceof Player));
            for (LivingEntity m : entityList) {
                if (m.getType().is(EntityTags.DISINTEGRATION_BLACKLIST)) {
                    continue;
                }
                m.remove(Entity.RemovalReason.DISCARDED);
                if (m.isRemoved()) {

                    ParticleUtil.spawnPoof((ServerLevel) world, m.blockPosition());
                    if (m.shouldDropExperience()) {
                        int exp = m.getExperienceReward((ServerLevel) world, null) * 2;
                        if (exp > 0) {
                            int numGreater = exp / 12;
                            exp -= numGreater * 12;
                            int numLesser = exp / 3;
                            if ((exp - numLesser * 3) > 0)
                                numLesser++;
                            var pos = m.blockPosition().getBottomCenter();
                            if (numGreater > 0) {
                                world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, new ItemStack(ItemsRegistry.GREATER_EXPERIENCE_GEM, numGreater)));
                            }
                            if (numLesser > 0) {
                                world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, new ItemStack(ItemsRegistry.EXPERIENCE_GEM, numLesser)));
                            }
                            didWorkOnce = true;
                        }

                    }
                }
            }
            if (didWorkOnce)
                setNeedsSource(true);
        }
    }

@Override
	public void tick() {
		super.tick();

		if (this.isEffectiveAi()) {
			if (this.isPassenger()) {
				this.setYRot(0.0F);
				this.setXRot(0.0F);
				this.setAirSupply(this.getMaxAirSupply());
			} else if (this.isInWater() && this.getNavigation().isDone()) {
				float yaw = this.getYRot();
				float pitch = this.getXRot();
				float pitchFactor = Mth.cos(pitch * ((float) Math.PI / 180F));
				float x = -Mth.sin(yaw * ((float) Math.PI / 180F)) * pitchFactor;
				float y = -Mth.sin(pitch * ((float) Math.PI / 180F));
				float z = Mth.cos(yaw * ((float) Math.PI / 180F)) * pitchFactor;
				Vec3 motion = new Vec3(x, y, z).normalize().scale(0.01666666666F);
				this.push(motion.x, motion.y, motion.z);
			}

			if (!this.level().isClientSide && (Mth.abs(this.xRotO - this.getXRot()) >= 1.0F || Mth.abs(this.yRotO - this.getYRot()) >= 1.0F)) {
				this.hasImpulse = true;
			}
		}

		if (this.hasCooldown()) {
			if (this.isEffectiveAi()) {
				this.setCooldown(this.getCooldown() - 1);
				if (!this.hasCooldown()) {
					this.playSound(UASoundEvents.JELLYFISH_COOLDOWN_END.get(), 1.0F, this.random.nextFloat() * 0.15F + 1.0F);
				}
			}

			if (this.level().isClientSide && this.level().getGameTime() % 4 == 0) {
				for (int i = 0; i < 2; i++) {
					this.level().addParticle(JellyTorchType.getBlobParticleType(this.getJellyTorchType()), this.getRandomX(0.5D), this.getY() + this.getEyeHeight(), this.getRandomZ(0.5D), makeNegativeRandomly(this.random.nextDouble() * 0.05F, this.getRandom()), -this.random.nextDouble() * 0.05F, makeNegativeRandomly(this.random.nextDouble() * 0.05F, this.getRandom()));
				}
			}
		}

		if (this.isAlive()) {
			for (LivingEntity entities : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.15D), CAN_STING)) {
				if (entities.isAlive()) {
					this.stingEntity(entities);
				}
			}

			if (this.isInWater() && this.isNoEndimationPlaying()) {
				this.setDeltaMovement(this.getDeltaMovement().subtract(0.0F, 0.005F, 0.0F));
			}
		}
	}

static void doAfterGridInit(ServerLevel level, List<BlockEntity> blockEntities, boolean waitForActive,
            Runnable callback) {
        Runnable delayedAction = new Runnable() {
            private int attempts = 120;

            @Override
            public void run() {
                var notInitialized = new ArrayList<BlockEntity>();
                var notActive = new ArrayList<BlockEntity>();

                for (var be : blockEntities) {
                    if (be.isRemoved()) {
                        return;
                    }

                    if (be instanceof IGridConnectedBlockEntity host) {
                        var mainNode = host.getMainNode();
                        if (mainNode == null) {
                            notInitialized.add(be);
                            notActive.add(be);
                            break;
                        } else if (!mainNode.isActive()) {
                            notActive.add(be);
                        }
                    } else if (be instanceof CableBusBlockEntity cableBus) {
                        var centerPart = cableBus.getCableBus().getPart(null);
                        if (centerPart != null) {
                            var mainNode = centerPart.getGridNode();
                            if (mainNode == null) {
                                notInitialized.add(be);
                                notActive.add(be);
                                break;
                            } else if (!mainNode.isActive()) {
                                notActive.add(be);
                            }
                        }
                    }
                }

                if (!notInitialized.isEmpty() || waitForActive && !notActive.isEmpty()) {
                    if (--attempts > 0) {
                        TickHandler.instance().addCallable(level, this);
                    } else {
                        throw new IllegalStateException("Couldn't wait for grid to initialize. Not initialized: "
                                + notInitialized + ". Not active: " + notActive);
                    }
                } else {
                    callback.run();
                }
            }
        };
        TickHandler.instance().addCallable(level, delayedAction);
    }

@Override
	public void render(ShaderBannerBlockEntity te, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		long time = te.getLevelNonnull().getGameTime();
		matrixStack.pushPose();

		// Check which of the two blocks we are so we can calculate the orientation.
		if(te.getState().getBlock()==Cloth.SHADER_BANNER.get())
		{
			// Standing banner, we have 16 different rotations.
			int orientation = te.getState().getValue(ShaderBannerStandingBlock.ROTATION);
			matrixStack.translate(0.5F, 0.5F, 0.5F);
			float f1 = (float)(orientation*360)/16.0F;
			matrixStack.mulPose(new Quaternionf().rotateY(-f1 * Mth.DEG_TO_RAD));
			standingModel.visible = true;
		}
		else
		{
			// Must be the wall banner, attaches to the side of the block with no support pillar.
			assert te.getState().getBlock()==Cloth.SHADER_BANNER_WALL.get();

			Direction facing = te.getState().getValue(ShaderBannerWallBlock.FACING);
			float rotation = facing.toYRot();

			matrixStack.translate(0.5F, -1/6f, 0.5F);
			matrixStack.mulPose(new Quaternionf().rotateY(-rotation * Mth.DEG_TO_RAD));
			matrixStack.translate(0.0F, -0.3125F, -0.4375F);
			standingModel.visible = false;
		}

		BlockPos blockpos = te.getBlockPos();
		float f3 = (float)(blockpos.getX()*7+blockpos.getY()*9+blockpos.getZ()*13)+(float)time+partialTicks;
		clothModel.xRot = (-0.0125F+0.01F*Mth.cos(f3*(float)Math.PI*0.02F))*(float)Math.PI;
		clothModel.y = -32.0F;
		ResourceLocation resourcelocation = this.getBannerResourceLocation(te);

		if(resourcelocation!=null)
		{
			matrixStack.pushPose();

			matrixStack.scale(2f/3, -2f/3, -2f/3);
			VertexConsumer builder;
			builder = bufferIn.getBuffer(RenderType.entitySolid(resourcelocation));
			this.clothModel.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);
			builder = ModelBakery.BANNER_BASE.buffer(bufferIn, RenderType::entitySolid);
			this.crossbar.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);
			this.standingModel.render(matrixStack, builder, combinedLightIn, combinedOverlayIn);

			matrixStack.popPose();
		}

		matrixStack.popPose();
	}

private void enqueueProcesses(State state, Level level)
	{
		Int2IntOpenHashMap usedInvSlots = new Int2IntOpenHashMap();
		for(MultiblockProcess<ArcFurnaceRecipe, ProcessContextInMachine<ArcFurnaceRecipe>> process : state.processor.getQueue())
			if(process instanceof ArcFurnaceProcess arcProcess)
			{
				int[] inputSlots = arcProcess.getInputSlots();
				int[] inputAmounts = arcProcess.getInputAmounts();
				if(inputAmounts==null)
					continue;
				for(int i = 0; i < inputSlots.length; i++)
					if(inputAmounts[i] > 0)
						usedInvSlots.addTo(inputSlots[i], inputAmounts[i]);
			}

		NonNullList<ItemStack> additives = NonNullList.withSize(ADDITIVE_SLOT_COUNT, ItemStack.EMPTY);
		for(int i = 0; i < ADDITIVE_SLOT_COUNT; i++)
		{
			final ItemStack additive = state.inventory.getStackInSlot(FIRST_ADDITIVE_SLOT+i);
			if(additive.isEmpty())
				continue;
			additives.set(i, additive.copy());
			if(usedInvSlots.containsKey(FIRST_ADDITIVE_SLOT+i))
				additives.get(i).shrink(usedInvSlots.get(FIRST_ADDITIVE_SLOT+i));
		}

		for(int slot = FIRST_IN_SLOT; slot < IN_SLOT_COUNT; slot++)
		{
			if(usedInvSlots.containsKey(slot))
				continue;
			ItemStack stack = state.inventory.getStackInSlot(slot);
			if(stack.isEmpty())
				continue;
			RecipeHolder<ArcFurnaceRecipe> recipe = ArcFurnaceRecipe.findRecipe(level, stack, additives);
			if(recipe==null)
				continue;
			ArcFurnaceProcess process = new ArcFurnaceProcess(
					recipe, ApiUtils.RANDOM.nextLong(), slot, 12, 13, 14, 15
			);
			if(state.processor.addProcessToQueue(process, level, false))
			{
				int[] consumedAdditives = recipe.value().getConsumedAdditives(additives, true);
				if(consumedAdditives!=null)
					process.setInputAmounts(
							recipe.value().input.getCount(),
							consumedAdditives[0],
							consumedAdditives[1],
							consumedAdditives[2],
							consumedAdditives[3]
					);
			}
		}
	}

