@SubscribeEvent
        public static void onBabySpawn(BabyEntitySpawnEvent event) {
            var player = event.getCausedByPlayer();

            if (player == null)
                return;

            long totalDeadlineExtension = 0L;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.RING_OF_THE_SEVEN_DEADLY_SINS.get())) {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                if (!relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("lust").canPlayerUse(player))
                    continue;

                var parentA = event.getParentA();
                var parentB = event.getParentB();
                var child = event.getChild();

                var level = player.level();
                var random = level.getRandom();

                if (child != null) {
                    var maxOffspring = Math.max(1, (int) Math.round(relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("lust").getStatData("amount").getValue()));
                    var count = random.nextInt(maxOffspring + 1);

                    for (int i = 0; i < count; i++) {
                        var extra = (AgeableMob) child.getType().create(level);

                        if (extra == null)
                            continue;

                        extra.setBaby(true);
                        extra.moveTo(parentA.getX(), parentA.getY(), parentA.getZ(), random.nextFloat() * 360F, 0F);
                        level.addFreshEntity(extra);
                    }

                    relic.getRelicData(player, stack).getLevelingData().addExperience("lust", "offspring", count);
                    relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("lust").getStatisticData().getMetricData("extra_offspring").addValue(count);
                }

                relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("lust").getStatisticData().getMetricData("breeding_attempts").addValue(1);

                totalDeadlineExtension += (long) (relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("lust").getStatData("time").getValue() * 20);
            }

            if (totalDeadlineExtension > 0L) {
                var deadline = player.level().getGameTime() + totalDeadlineExtension;

                CommonEvents.applyLustDeadline(event.getParentA(), deadline);
                CommonEvents.applyLustDeadline(event.getParentB(), deadline);
            }
        }

public void teleportTowards(Entity entity) {
        if (!this.level.isClientSide() && !this.isNoAi() && this.isAlive() && this.toTeleportPos == null && !this.isSettingUpSecond()) {
            if (MobsConfig.ApostleDelayedTeleport.get()) {
                if (this.pendingTeleportSearch != null) {
                    if (this.pendingTeleportSearch.isDone()) {
                        Vec3 result = this.pendingTeleportSearch.getNow(null);
                        this.pendingTeleportSearch = null;
                        if (result != null) {
                            Vec3 vec3 = findTeleportGroundY(this.level, result.x, result.y + 3, result.z, entity.getY());
                            if (vec3 != null) {
                                this.toTeleportPos = vec3;
                                this.playSound(ModSounds.APOSTLE_PRE_TELEPORT.get(), 2.0F, 1.0F);
                            }
                        }
                    }
                } else {
                    final double targetX = entity.getX();
                    final double targetY = entity.getEyeY();
                    final double targetZ = entity.getZ();
                    final double selfX = this.getX();
                    final double selfY = this.getY();
                    final double selfZ = this.getZ();
                    final RandomSource randomSource = this.apostleRandom;

                    this.prevX = selfX;
                    this.prevY = selfY;
                    this.prevZ = selfZ;

                    this.pendingTeleportSearch = CompletableFuture.supplyAsync(() -> {
                        Vec3 vec3 = new Vec3(selfX - targetX, selfY * 0.5D - targetY, selfZ - targetZ).normalize();
                        double d0 = 16.0D;
                        double d1 = selfX + (randomSource.nextDouble() - 0.5D) * 8.0D - vec3.x * d0;
                        double d2 = selfY + (randomSource.nextInt(16) - 8) - vec3.y * d0;
                        double d3 = selfZ + (randomSource.nextDouble() - 0.5D) * 8.0D - vec3.z * d0;
                        return new Vec3(d1, d2, d3);
                    });
                }
            } else {
                for (int i = 0; i < 128; ++i) {
                    Vec3 vector3d = new Vec3(this.getX() - entity.getX(), this.getY(0.5D) - entity.getEyeY(), this.getZ() - entity.getZ()).normalize();
                    double d0 = 16.0D;
                    double d1 = this.getX() + (this.level.getRandom().nextDouble() - 0.5D) * 8.0D - vector3d.x * d0;
                    double d2 = this.getY() + (this.level.getRandom().nextInt(16) - 8) - vector3d.y * d0;
                    double d3 = this.getZ() + (this.level.getRandom().nextDouble() - 0.5D) * 8.0D - vector3d.z * d0;
                    if (BlockFinder.canSeeBlock(entity, BlockPos.containing(d1, d2, d3))
                            && this.randomTeleport(d1, d2, d3, false)) {
                        this.teleportHits();
                        break;
                    }
                }
            }
        }
    }

@Override
    public void aiStep() {
        if (!this.level.isClientSide) {
            this.setAngry(this.getTarget() != null);
            if (this.level.getGameTime() % 1000 == 0) {
                this.addHunger(-10);
                if (!this.isStarving()) {
                    this.heal(1.0F);
                }
            }
            // Random idle animations
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping() && this.getCommandInt() == 0) {
                int i = this.random.nextInt(3000);
                if (i == 13 && !this.isInWater() && this.isNotMoving() && this.canMove()) {
                    this.setSitting(true);
                }
                if (i == 14 && this.isSitting()) {
                    this.setSitting(false);
                }
                if (i > 2960 && i < 2979 && !this.isInWater() && !this.isBaby()) {
                    this.setAnimation(TALK);
                }
                if (i > 2980 && !this.isInWater() && this.getHunger() < 60 && this.canMove() && this.getAnimation() == NO_ANIMATION) {
                    if ((this.lastDugPos == null || this.distanceToSqr(this.lastDugPos.getX(), this.getY(), this.lastDugPos.getZ()) > 50) && this.level.getBlockState(this.blockPosition().below()).is(BlockTags.MINEABLE_WITH_SHOVEL)) {
                        this.setAnimation(WORK_DIG);
                        this.addHunger(20);
                        this.lastDugPos = this.blockPosition();
                    }
                }
            }
            if (this.getAnimation() == WORK_DIG && this.getAnimationTick() % 8 == 0) {
                ((ServerLevel)this.level).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, this.level.getBlockState(this.blockPosition().below())), this.getX(), this.getY(), this.getZ(), 20, 0.0D, 0.0D, 0.0D, 0.15F);
                this.playSound(SoundEvents.SHOVEL_FLATTEN, 0.8F, 0.6F);
                if (this.getAnimationTick() == 64 && this.random.nextInt(5) == 0) {
                    List<ItemStack> result = EntityUtils.getItemFromLootTable(ModLootTables.LOOT_DIGGING, this.level);
                    for (ItemStack itemstack : result)
                        this.spawnAtLocation(itemstack);
                }
            }
            if (this.getAnimation() == TALK && this.getAnimationTick() == 1 && this.getAmbientSound() != null) {
                this.playSound(this.getAmbientSound(), this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.getTarget() != null && this.tickCount % 120 == 0) {
                this.playSound(this.getThreatSound(), this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.getAnimation() != NO_ANIMATION) {
                if (this.getAnimation() == ATTACK && this.getAnimationTick() == 8 && this.random.nextInt(3) == 0) {
                    this.playSound(ModSounds.ENTITY_BOAR_SQUEAL, this.getSoundVolume(), this.getVoicePitch());
                }
            }
        }
        super.aiStep();
    }

@Override
    public void tick() {
        List<Entity> nearbyEntities;
        baseTick();
        if (life == START_LIFE) {
            if (level.isClientSide()) {
                level.playLocalSound(getX(), getY(), getZ(), SoundEvents.LIGHTNING_BOLT_THUNDER, SoundSource.WEATHER, 10000, 0.8f + random.nextFloat() * 0.2f, false);
                level.playLocalSound(getX(), getY(), getZ(), SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.WEATHER, 2, 0.5f + random.nextFloat() * 0.2f, false);
            } else {
                Difficulty difficulty = level.getDifficulty();
                if (difficulty == Difficulty.NORMAL || difficulty == Difficulty.HARD) {
                    spawnFire(4);
                }
            }
        }
        --life;
        if (life < 0) {
            if (flashes == 0) {
                discard();
            } else if (life < -random.nextInt(10)) {
                --flashes;
                life = 1;
                seed = random.nextLong();
                spawnFire(0);
            }
        }
        if (life >= 0) {
            if (level.isClientSide) {
                level.setSkyFlashTime(2);
            } else if (!visualOnly) {
                nearbyEntities = level.getEntities(this, new AABB(getX() - 3, getY() - 3, getZ() - 3, getX() + 3, getY() + 6 + 3, getZ() + 3), Entity::isAlive);
                for (Entity entity : nearbyEntities) {
                    boolean canHit = true;
                    if (cause == null && entity instanceof AnuBoss) {
                        canHit = false;
                    } else if (cause != null) {
                        if (entity == cause || entity instanceof OwnableEntity ownable && ownable.getOwner() == cause) {
                            canHit = false;
                        }
                    } else if (entity instanceof Pig) {
                        canHit = false;
                    }
                    if (canHit) {
                        entity.thunderHit((ServerLevel) level, this);
                        hitEntities.add(entity);
                    }
                }
                if (cause != null) {
                    CriteriaTriggers.CHANNELED_LIGHTNING.trigger(cause, nearbyEntities);
                }
            }
        }
    }

@Override
    public MerchantOffers getOffers() {
        if (this.offers == null) {
            this.offers = new MerchantOffers();

            this.offers.addAll(createRandomOffers(3, 4));

            if (this.random.nextFloat() < 0.25f) {
                this.offers.add(new AdditionalWanderingTrades.InkBuyTrade((InkItem) ItemRegistry.INK_UNCOMMON.get()).getOffer(this, this.random));
            }
            if (this.random.nextFloat() < 0.25f) {
                this.offers.add(new AdditionalWanderingTrades.InkBuyTrade((InkItem) ItemRegistry.INK_RARE.get()).getOffer(this, this.random));
            }
            if (this.random.nextFloat() < 0.25f) {
                this.offers.add(new AdditionalWanderingTrades.InkBuyTrade((InkItem) ItemRegistry.INK_EPIC.get()).getOffer(this, this.random));
            }
            if (this.random.nextFloat() < 0.5f) {
                this.offers.add(new AdditionalWanderingTrades.ExilirBuyTrade(true, false).getOffer(this, this.random));
            }
            int j = random.nextIntBetweenInclusive(1, 3);
            for (int i = 0; i < j; i++) {
                this.offers.add(random.nextBoolean() ? new AdditionalWanderingTrades.PotionSellTrade(null).getOffer(this, this.random) : new AdditionalWanderingTrades.ExilirSellTrade(true, false).getOffer(this, this.random));
            }
            this.offers.add(new AdditionalWanderingTrades.RandomScrollTrade(new SpellFilter(SchoolRegistry.NATURE.get()), 0f, .4f).getOffer(this, this.random));
            if (this.random.nextFloat() < .65f) {
                this.offers.add(new AdditionalWanderingTrades.RandomScrollTrade(new SpellFilter(SchoolRegistry.NATURE.get()), .5f, .9f).getOffer(this, this.random));
            }
            this.offers.add(new MerchantOffer(
                    new ItemCost(Items.EMERALD, 16),
                    Optional.empty(),
                    new ItemStack(ItemRegistry.NETHERWARD_TINCTURE.get(), 1),
                    0,
                    8,
                    5,
                    0.01f
            ));
            Item greaterElixir = List.of(ItemRegistry.GREATER_EVASION_ELIXIR, ItemRegistry.GREATER_OAKSKIN_ELIXIR, ItemRegistry.GREATER_INVISIBILITY_ELIXIR, ItemRegistry.GREATER_HEALING_POTION).get(random.nextInt(4)).get();
            this.offers.add(new MerchantOffer(
                    new ItemCost(greaterElixir, 4),
                    Optional.empty(),
                    ItemRegistry.NATURE_RUNE.get().getDefaultInstance(),
                    0,
                    1,
                    5,
                    0.1f
            ));
            this.offers.removeIf(Objects::isNull);

            //We count the creation of our stock as a restock so that we do not immediately refresh trades the same day.
            setLastRestockGameTime(level.getGameTime());
        }
        return this.offers;
    }

@Override
    public @NonNull InteractionResult use(Level level, Player player, @NonNull InteractionHand hand) {
        final ItemStack stack = player.getItemInHand(hand);

        if (!level.isClientSide() && player instanceof ServerPlayer serverPlayer) {
            if (player.isShiftKeyDown()) {
                //here we use main hand item as selected slot
                int selectedSlot = hand == InteractionHand.MAIN_HAND ? player.getInventory().getSelectedSlot() : -1;

                serverPlayer.openMenu(
                        new SimpleMenuProvider((id, playerInventory, unused) -> {
                            return new TeleportTabletContainer(id, playerInventory,
                                    this.getInventory(serverPlayer, stack), selectedSlot);
                        }, stack.getDisplayName()), buffer -> {
                            buffer.writeVarInt(selectedSlot);
                        });
            } else { //Teleport logic
                if (stack.has(DataComponents.CONTAINER)) {
                    ItemContainerContents contents = stack.getOrDefault(DataComponents.CONTAINER, ItemContainerContents.EMPTY);
                    if (contents  == ItemContainerContents.EMPTY)
                        return InteractionResult.FAIL;

                    ItemStack compass = contents.getStackInSlot(0);
                    TeleportTransition transition = this.getDestination((ServerLevel) level, player, compass);
                    if (transition == null)
                        return InteractionResult.FAIL;

                    if (compass.getOrDefault(DataComponents.CUSTOM_NAME, "") != "BACK") {
                        boolean checking = true;
                        NonNullList<ItemStack> items = NonNullList.create();
                        for (int i = 0 ; i < contents.getSlots() ; i++) {
                            ItemStack back = contents.getStackInSlot(i);
                            if (checking && back.getOrDefault(DataComponents.CUSTOM_NAME, Component.empty()).getString().equals("BACK")) {
                                LodestoneTracker target = new LodestoneTracker(Optional.of(GlobalPos.of(level.dimension(), player.blockPosition())), true);
                                back.set(DataComponents.LODESTONE_TRACKER, target);
                                checking = false;
                            }
                            items.add(back);
                        }
                        if (!checking)
                            Networking.sendToServer(new MessageSetContents(ItemContainerContents.fromItems(items), hand));
                    }

                    player.teleport(transition);
                    player.getCooldowns().addCooldown(stack, 20 * Occultism.SERVER_CONFIG.itemSettings.wormholeTabletCooldown.getAsInt());
                    level.broadcastEntityEvent(player, (byte) 46);
                    return InteractionResult.SUCCESS;
                }
            }
        }

        return InteractionResult.SUCCESS;
    }

public static void tick(Level level, BlockPos pos, BlockState state, TileEntityDragonforge entityDragonforge) {
        boolean flag = entityDragonforge.isBurning();
        boolean flag1 = false;
        entityDragonforge.fireType = entityDragonforge.getFireType(entityDragonforge.getBlockState().getBlock());
        if (entityDragonforge.lastDragonFlameTimer > 0) {
            entityDragonforge.lastDragonFlameTimer--;
        }
        entityDragonforge.updateGrills(entityDragonforge.assembled());
        if (!level.isClientSide) {
            if (entityDragonforge.prevAssembled != entityDragonforge.assembled()) {
                BlockDragonforgeCore.setState(entityDragonforge.fireType, entityDragonforge.prevAssembled, level, pos);
            }
            entityDragonforge.prevAssembled = entityDragonforge.assembled();
            if (!entityDragonforge.assembled())
                return;
        }
        if (entityDragonforge.cookTime > 0 && entityDragonforge.canSmelt() && entityDragonforge.lastDragonFlameTimer == 0) {
            entityDragonforge.cookTime--;
        }
        if (entityDragonforge.getItem(0).isEmpty() && !level.isClientSide) {
            entityDragonforge.cookTime = 0;
        }
        if (!entityDragonforge.level.isClientSide) {
            if (entityDragonforge.isBurning()) {
                if (entityDragonforge.canSmelt()) {
                    ++entityDragonforge.cookTime;
                    if (entityDragonforge.cookTime >= entityDragonforge.getMaxCookTime()) {
                        entityDragonforge.cookTime = 0;
                        entityDragonforge.smeltItem();
                        flag1 = true;
                    }
                } else {
                    if (entityDragonforge.cookTime > 0) {
                        IceAndFire.sendMSGToAll(new MessageUpdateDragonforge(pos.asLong(), entityDragonforge.cookTime));
                        entityDragonforge.cookTime = 0;
                    }
                }
            } else if (!entityDragonforge.isBurning() && entityDragonforge.cookTime > 0) {
                entityDragonforge.cookTime = Mth.clamp(entityDragonforge.cookTime - 2, 0,
                        entityDragonforge.getMaxCookTime());
            }

            if (flag != entityDragonforge.isBurning()) {
                flag1 = true;
            }
        }

        if (flag1) {
            entityDragonforge.setChanged();
        }
        if (!entityDragonforge.canAddFlameAgain) {
            entityDragonforge.canAddFlameAgain = true;
        }
    }

@SubscribeEvent
    public void onPlayerAttack(AttackEntityEvent event) {
        if (event.getTarget() != null && isSheep(event.getTarget())) {
            float dist = IafConfig.cyclopesSheepSearchLength;
            final List<Entity> list = event.getTarget().level.getEntities(event.getPlayer(), event.getPlayer().getBoundingBox().expandTowards(dist, dist, dist));
            if (!list.isEmpty()) {
                for (final Entity entity : list) {
                    if (entity instanceof EntityCyclops) {
                        EntityCyclops cyclops = (EntityCyclops) entity;
                        if (!cyclops.isBlinded() && !event.getPlayer().isCreative()) {
                            cyclops.setTarget(event.getPlayer());
                        }
                    }
                }
            }
        }
        if (event.getTarget() instanceof EntityStoneStatue) {
            ((LivingEntity) event.getTarget()).setHealth(((LivingEntity) event.getTarget()).getMaxHealth());
            if (event.getPlayer() != null) {
                ItemStack stack = event.getPlayer().getMainHandItem();
                event.getTarget().playSound(SoundEvents.STONE_BREAK, 2, 0.5F + (this.rand.nextFloat() - this.rand.nextFloat()) * 0.2F + 0.5F);
                if (stack.getItem() != null && (stack.getItem().isCorrectToolForDrops(Blocks.STONE.defaultBlockState()) || stack.getItem().getDescriptionId().contains("pickaxe"))) {
                    boolean ready = false;
                    event.setCanceled(true);
                    EntityStoneStatue statue = (EntityStoneStatue) event.getTarget();
                    statue.setCrackAmount(statue.getCrackAmount() + 1);
                    ready = statue.getCrackAmount() > 9;
                    if (ready) {
                        CompoundTag writtenTag = new CompoundTag();
                        event.getTarget().saveWithoutId(writtenTag);
                        event.getTarget().playSound(SoundEvents.STONE_BREAK, 2, (this.rand.nextFloat() - this.rand.nextFloat()) * 0.2F + 0.5F);
                        event.getTarget().remove(Entity.RemovalReason.KILLED);
                        boolean silkTouch = EnchantmentHelper.getItemEnchantmentLevel(Enchantments.SILK_TOUCH, stack) > 0;
                        if (silkTouch) {
                            ItemStack statuette = new ItemStack(IafItemRegistry.STONE_STATUE.get());
                            statuette.setTag(new CompoundTag());
                            statuette.getTag().putBoolean("IAFStoneStatuePlayerEntity", statue.getTrappedEntityTypeString().equalsIgnoreCase("minecraft:player"));
                            statuette.getTag().putString("IAFStoneStatueEntityID", statue.getTrappedEntityTypeString());
                            statuette.getTag().put("IAFStoneStatueNBT", writtenTag);
                            ((LivingEntity) event.getTarget()).addAdditionalSaveData(statuette.getTag());
                            if (!event.getTarget().level.isClientSide) {
                                event.getTarget().spawnAtLocation(statuette, 1);
                            }
                        } else {
                            if (!event.getTarget().level.isClientSide) {
                                event.getTarget().spawnAtLocation(Blocks.COBBLESTONE.asItem(), 2 + event.getEntityLiving().getRandom().nextInt(4));
                            }
                        }
                        event.getTarget().remove(Entity.RemovalReason.KILLED);
                    }
                }
            }
        }
    }

@Override
	 public void onUpdate() {
		super.onUpdate();

		if (!world.isRemote) {
			if (startExtention && world.getTotalWorldTime() % 1 == 0) {
				List<BlockPos> pos = matchDistance(world, matchDistance);
				if (!pos.isEmpty()) {
					for (int index = 0; index < pos.size(); index++)
						world.setBlockState(pos.get(index), getTempBlock(), 2);
				}

				if (matchDistance < 16)
					matchDistance++;

				if (matchDistance >= 16) {
					startExtention = false;
					matchDistance = 0;
				}

			}

			if(startRetraction) {
				List<BlockPos> pos = matchDistance(world, matchDistance);
				if (!pos.isEmpty()) {
					for (int index = 0; index < pos.size(); index++)
						restoreBlocks(pos.get(index));
				}

				if (matchDistance < 16)
					matchDistance++;

				if (matchDistance >= 16)
					setDead();
			}	

			if (ticksExisted > 1) {
				if(isMist()) {
					if(world.getBlockState(getPosition()).getBlock() != BlockRegistry.MIST_BRIDGE || world.getBlockState(getPosition()).getBlock() == BlockRegistry.MIST_BRIDGE && !world.getBlockState(getPosition()).getValue(BlockMistBridge.SOLID) || ticksExisted >= 200) {
						if(!startRetraction)
							world.playSound((EntityPlayer)null, getPosition(), SoundRegistry.MIST_STAFF_VANISH, SoundCategory.BLOCKS, 1F, 1.0F);
						startRetraction = true;
					}
				}
				if(!isMist()) {
					if(ticksExisted >= 200) {
						if(!startRetraction)
							world.playSound((EntityPlayer)null, getPosition(), SoundRegistry.MIST_STAFF_VANISH, SoundCategory.BLOCKS, 1F, 1.0F);
						startRetraction = true;
					}
				}
			}
		}
	}

private void updateConnections() {
        var operation = pendingUpdate;
        pendingUpdate = ConnectionUpdate.NONE;

        var mainGrid = getMainNode().getGrid();

        if (isOutput()) {
            // It's possible to be woken up while we're still an input, then be made an output,
            // and THEN this method is called afterwards. Disconnect any potentially remaining
            // connections.
            operation = ConnectionUpdate.DISCONNECT;
        } else if (mainGrid == null) {
            // We got disconnected completely (are we being destroyed?)
            operation = ConnectionUpdate.DISCONNECT;
        }

        if (operation == ConnectionUpdate.DISCONNECT) {
            for (var cw : connections.values()) {
                cw.destroy();
            }
            connections.clear();
        } else if (operation == ConnectionUpdate.CONNECT) {
            var outputs = getOutputs();

            // Sever existing connections to tunnels that are no longer outputs of this input or
            // that have become invalid for other reasons.
            var it = connections.entrySet().iterator();
            while (it.hasNext()) {
                var entry = it.next();
                var output = entry.getKey();
                var connection = entry.getValue();

                // The previous tunnel could have moved to a different main grid (net-split), or lost his channel.
                // Or it may have been relinked to a different input.
                if (output.getMainNode().getGrid() != mainGrid
                        || !output.getMainNode().isOnline()
                        || !outputs.contains(output)) {
                    connection.destroy();
                    it.remove();
                }
            }

            for (var output : outputs) {
                // The other tunnel has no channel, or it's already connected
                if (!output.getMainNode().isOnline() || connections.containsKey(output)) {
                    continue;
                }

                var connection = GridHelper.createConnection(getExternalFacingNode(),
                        output.getExternalFacingNode());
                connections.put(output, connection);
            }
        }
    }

@TestPlot("drive_deferred_side_effects")
    public static void testDrive(PlotBuilder plot) {
        plot.creativeEnergyCell(BlockPos.ZERO.below());
        plot.block(BlockPos.ZERO, AEBlocks.DRIVE);

        plot.test(helper -> {
            helper.startSequence()
                    .thenExecute(() -> {
                        var drive = helper.getBlockEntity(BlockPos.ZERO,
                                DriveBlockEntity.class);

                        // Give the drive an initial cell, then force its storage cache to be built
                        drive.getInternalInventory().setItemDirect(0, AEItems.ITEM_CELL_1K.stack());
                        drive.setPriority(drive.getPriority());
                        var oldCellHandler = drive.getCellInventory(0);
                        helper.check(oldCellHandler != null, "Cell inventory should be cached", BlockPos.ZERO);

                        // Store a diamond on the cached cell so we can tell its content apart from the new cell
                        oldCellHandler.insert(AEItemKey.of(Items.DIAMOND), 1, Actionable.MODULATE,
                                IActionSource.empty());
                        helper.check(oldCellHandler.getAvailableStacks().get(AEItemKey.of(Items.DIAMOND)) == 1,
                                "Drive should expose the diamond stored on the first cell", BlockPos.ZERO);

                        var handler = drive.getExposedItemHandler(Direction.UP);
                        helper.check(handler != null, "handler should not be null", BlockPos.ZERO);

                        try (var tx = Transaction.open(null)) {
                            // Swap out the cell for a different, empty one
                            var oldCellStack = drive.getInternalInventory().getStackInSlot(0);
                            var extracted = handler.extract(ItemResource.of(oldCellStack), 1, tx);
                            helper.check(extracted == 1, "Should extract old cell", BlockPos.ZERO);

                            var newCell = AEItems.ITEM_CELL_4K.stack();
                            var inserted = handler.insert(ItemResource.of(newCell), 1, tx);
                            helper.check(inserted == 1, "Should insert new cell", BlockPos.ZERO);

                            // The cache is only invalidated on commit, so the drive should still report the
                            // OLD cell's content here even though a different cell now sits in the slot.
                            var stacksDuring = drive.getCellInventory(0).getAvailableStacks();
                            helper.check(stacksDuring.get(AEItemKey.of(Items.DIAMOND)) == 1,
                                    "No side-effects during transaction", BlockPos.ZERO);

                            tx.commit();
                        }

                        // After commit, the cache should have been invalidated and rebuilt, so the drive now
                        // correctly reports the new (empty) cell's content instead of the stale old one.
                        var stacksAfter = drive.getCellInventory(0).getAvailableStacks();
                        helper.check(stacksAfter.get(AEItemKey.of(Items.DIAMOND)) == 0,
                                "Storage cache invalidated after commit", BlockPos.ZERO);
                    })
                    .thenSucceed();
        });
    }

public static void call(ServerPlayer player, ItemStack stack){
        if (hasSummon(stack) && stack.getTag() != null) {
            CompoundTag compoundTag = stack.getTag();
            LivingEntity livingEntity = getSummon(compoundTag);
            if (player.level instanceof ServerLevel serverLevel) {
                if (livingEntity != null) {
                    LivingEntity original = null;
                    if (livingEntity.isPassenger() && livingEntity.getVehicle() instanceof LivingEntity vehicle) {
                        original = livingEntity;
                        livingEntity = vehicle;
                    }
                    if (!livingEntity.isDeadOrDying()) {
                        BlockPos blockPos = BlockFinder.SummonRadius(player.blockPosition(), livingEntity, serverLevel);
                        if (livingEntity.level.dimension() == player.level.dimension()) {
                            net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity, blockPos.getX(), blockPos.getY(), blockPos.getZ());
                            if (event.isCanceled()) {
                                return;
                            }
                            livingEntity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                            MobUtil.moveDownToGround(livingEntity);
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(blockPos, SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                            if (original instanceof IServant servant){
                                servant.setFollowing();
                            }
                            if (livingEntity instanceof IServant servant){
                                servant.setFollowing();
                            }
                        } else if (player.getServer() != null) {
                            ServerLevel serverWorld = player.getServer().getLevel(player.level.dimension());
                            if (serverWorld != null) {
                                blockPos = BlockFinder.SummonRadius(player.blockPosition(), livingEntity, serverWorld);
                                Vec3 vec3 = new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ());
                                net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity, blockPos.getX(), blockPos.getY(), blockPos.getZ());
                                if (event.isCanceled()) {
                                    return;
                                }
                                livingEntity.changeDimension(serverWorld, new ArcaTeleporter(vec3));
                                livingEntity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                                MobUtil.moveDownToGround(livingEntity);
                                ModNetwork.sendToALL(new SPlayWorldSoundPacket(player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                                if (original instanceof IServant servant){
                                    servant.setFollowing();
                                }
                                if (livingEntity instanceof IServant servant){
                                    servant.setFollowing();
                                }
                            }
                        }
                    }
                }
            }
        }
    }

@Override
    public @NotNull InteractionResultHolder<ItemStack> use(@NotNull Level world, Player player, @NotNull InteractionHand hand) {
        ItemStack stack = player.getItemInHand(hand);
        WarpScrollData data = stack.get(DataComponentRegistry.WARP_SCROLL);
        if (hand == InteractionHand.OFF_HAND)
            return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);

        if (!(world instanceof ServerLevel serverLevel))
            return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);

        if (data.isValid()) {
            if (!data.canTeleportWithDim(player.getCommandSenderWorld().dimension().location().toString())) {
                player.sendSystemMessage(Component.translatable("ars_nouveau.warp_scroll.wrong_dim"));
                return InteractionResultHolder.fail(stack);
            }
            BlockPos pos = data.pos().get();
            Vec2 rotation = data.rotation();
            Vec3 vec3 = player.position;
            Networking.sendToNearbyClient(world, player, new PacketWarpPosition(player.getId(), pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, rotation.x, rotation.y));
            player.teleportTo(pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5);
            player.level().gameEvent(GameEvent.TELEPORT, vec3, GameEvent.Context.of(player));
            player.setXRot(rotation.x);
            player.setYRot(rotation.y);

            serverLevel.sendParticles(ParticleTypes.PORTAL, pos.getX(), pos.getY() + 1.0, pos.getZ(),
                    10, (world.random.nextDouble() - 0.5D) * 2.0D, -world.random.nextDouble(), (world.random.nextDouble() - 0.5D) * 2.0D, 0.1f);
            world.playSound(null, pos, SoundEvents.ILLUSIONER_CAST_SPELL, SoundSource.NEUTRAL, 1.0f, 1.0f);
            if (!player.hasInfiniteMaterials()) {
                stack.shrink(1);
            }
            return InteractionResultHolder.pass(stack);
        }
        if (player.isShiftKeyDown()) {
            ItemStack newWarpStack = new ItemStack(ItemsRegistry.WARP_SCROLL.get());
            newWarpStack.set(DataComponentRegistry.WARP_SCROLL, new WarpScrollData(Optional.of(player.blockPosition()), player.getCommandSenderWorld().dimension().location().toString(), player.getRotationVector(), false));
            boolean didAdd;
            if (stack.getCount() == 1) {
                stack = newWarpStack;
                didAdd = true;
            } else {
                didAdd = player.addItem(newWarpStack);
                if (didAdd && !player.hasInfiniteMaterials()) {
                    stack.shrink(1);
                }
            }
            if (!didAdd) {
                player.sendSystemMessage(Component.translatable("ars_nouveau.warp_scroll.inv_full"));
                return InteractionResultHolder.fail(stack);
            } else {
                player.sendSystemMessage(Component.translatable("ars_nouveau.warp_scroll.recorded"));
            }
        }
        return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
    }

@Override
            public void onPlayerTickActive(PlayerEntity player, @Nonnull ItemStack item) {
                if (/*player.world.isRemote() &&*/ player.getEntityWorld().getGameTime() % 10 == 0 ) {
                    // we only have one tank, so index 0;
                    int maxFluid = fluidHandler.getTankCapacity(0);
                    int currentFluid = fluidHandler.getFluidInTank(0).getAmount();

                    // fill the tank
                    if (currentFluid < maxFluid) {
                        BlockPos pos = player.getPosition();
                        BlockState blockstate = player.world.getBlockState(pos);

                        // fill by being in water
                        if (player.isInWater() && player.world.getBlockState(pos).getBlock() != Blocks.BUBBLE_COLUMN) {
                            if (blockstate.getBlock() instanceof IBucketPickupHandler && blockstate.getFluidState().getFluid() == Fluids.WATER) {
                                Fluid fluid = ((IBucketPickupHandler) blockstate.getBlock()).pickupFluid(player.world, pos, blockstate);
                                FluidStack water = new FluidStack(fluid, 1000);
                                // only play sound if actually filling
                                if (fluidHandler.fill(water, IFluidHandler.FluidAction.EXECUTE) > 0) {
                                    player.playSound(SoundEvents.ITEM_BUCKET_FILL, 1.0F, 1.0F);
                                }
                            }
                            // fill by being in the rain or bubble column
                        } else if (player.isInWaterRainOrBubbleColumn()) {
                            FluidStack water = new FluidStack(Fluids.WATER, 100);
                            if (fluidHandler.fill(water, IFluidHandler.FluidAction.EXECUTE) > 0) {
                                player.playSound(SoundEvents.ITEM_BUCKET_FILL, 1.0F, 1.0F);
                            }
                        }
                    }
                }

                // Apply cooling
                double currentHeat = HeatUtils.getPlayerHeat(player);
                double maxHeat = HeatUtils.getPlayerMaxHeat(player);
                if ((currentHeat / maxHeat) >= ticker.applyPropertyModifiers(MPAConstants.HEAT_ACTIVATION_PERCENT)) {

                    // cool 200 per bucket
                    double coolAmount = fluidHandler.drain(
                            // adjust so cooling does not exceed cooling needed
                            (int) Math.min(1000, currentHeat/coolingFactor),
                            // only execute on server, simulate on client
                            player.world.isRemote ? IFluidHandler.FluidAction.SIMULATE : IFluidHandler.FluidAction.EXECUTE)
                            .getAmount() * coolingFactor;

                    HeatUtils.coolPlayer(player, coolAmount);
                    if (coolAmount > 0) {
                        player.world.playSound(player, player.getPosition(), SoundEvents.ENTITY_GENERIC_EXTINGUISH_FIRE, SoundCategory.MASTER, 1.0F, 1.0F);
                        for (int i = 0; i < 4; i++) {
                            player.world.addOptionalParticle(ParticleTypes.SMOKE, player.getPosX(), player.getPosY() + 0.5, player.getPosZ(), 0.0D, 0.0D, 0.0D);
                        }
                    }
                }
            }

