@Override
	public void tickServer()
	{
		this.energyStorage.updateAverage();
		IEnergyStorage itemEnergy = inventory.get(0).getCapability(EnergyStorage.ITEM);
		if(itemEnergy!=null)
		{
			if(charging)
			{
				if(energyStorage.getEnergyStored()==0)
				{
					charging = false;
					this.markContainingBlockForUpdate(null);
					return;
				}
				int stored = itemEnergy.getEnergyStored();
				int max = itemEnergy.getMaxEnergyStored();
				int space = max-stored;
				if(space > 0)
				{
					int energyDec = (10*stored)/max;
					int insert = Math.min(space, Math.max(energyStorage.getAverageInsertion(), IEServerConfig.MACHINES.charger_consumption.get()));
					int accepted = Math.min(itemEnergy.receiveEnergy(insert, true), this.energyStorage.extractEnergy(insert, true));
					if((accepted = this.energyStorage.extractEnergy(accepted, false)) > 0)
						stored += itemEnergy.receiveEnergy(accepted, false);
					int energyDecNew = (10*stored)/max;
					if(energyDec!=energyDecNew)
						this.markContainingBlockForUpdate(null);
				}
			}
			else if(energyStorage.getEnergyStored() >= energyStorage.getMaxEnergyStored()*.95)
			{
				charging = true;
				this.markContainingBlockForUpdate(null);
			}
		}


		if(level.getGameTime()%32==((getBlockPos().getX()^getBlockPos().getZ())&31))
		{
			float charge = 0;
			if(itemEnergy!=null)
			{
				float max = itemEnergy.getMaxEnergyStored();
				if(max > 0)
					charge = itemEnergy.getEnergyStored()/max;
			}
			int i = (int)(15*charge);
			if(i!=this.comparatorOutput)
			{
				this.comparatorOutput = i;
				level.updateNeighborsAt(getBlockPos(), getBlockState().getBlock());
			}
		}
	}

private boolean provideFluidToSpace(FluidStack fluid, boolean simulate) {
		if (world == null)
			return false;
		if (!world.isLoaded(outputPos))
			return false;

		BlockState state = world.getBlockState(outputPos);
		FluidState fluidState = state.getFluidState();
		boolean waterlog = state.hasProperty(WATERLOGGED);

		if (!waterlog && !state.canBeReplaced())
			return false;
		if (fluid.isEmpty())
			return false;
		if (!(fluid.getFluid() instanceof FlowingFluid))
			return false;
		if (!FluidHelper.hasBlockState(fluid.getFluid()))
			return true;

		if (!fluidState.isEmpty() && FluidHelper.convertToStill(fluidState.getType()) != fluid.getFluid()) {
			FluidReactions.handlePipeSpillCollision(world, outputPos, fluid.getFluid(), fluidState);
			return false;
		}

		if (fluidState.isSource())
			return false;
		if (waterlog && fluid.getFluid() != Fluids.WATER)
			return false;
		if (simulate)
			return true;

		if (!AllConfigs.server().fluids.pipesPlaceFluidSourceBlocks.get())
			return true;

		if (world.dimensionType()
			.ultraWarm() && FluidHelper.isTag(fluid, FluidTags.WATER)) {
			int i = outputPos.getX();
			int j = outputPos.getY();
			int k = outputPos.getZ();
			world.playSound(null, i, j, k, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F,
				2.6F + (world.random.nextFloat() - world.random.nextFloat()) * 0.8F);
			return true;
		}

		if (waterlog) {
			world.setBlock(outputPos, state.setValue(WATERLOGGED, true), Block.UPDATE_ALL);
			world.scheduleTick(outputPos, Fluids.WATER, 1);
			return true;
		}

		world.setBlock(outputPos, fluid.getFluid()
			.defaultFluidState()
			.createLegacyBlock(), Block.UPDATE_ALL);
		return true;
	}

@Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        canDrop = false;
        lastError = null;

        if (isMouseOver()) {
            if (getModularGui().getScreen() instanceof AbstractContainerScreen<?> containerScreen) {
                containerScreen.skipNextRelease = true;
            }

            try (ModuleHost host = grid.container.getModuleHost()) {
                InputConstants.Key mouseKey = InputConstants.Type.MOUSE.getOrCreate(button);
                boolean pickBlock = mc().options.keyPickItem.isActiveAndMatches(mouseKey);
                ModuleGrid.GridPos cell = getCellAtPos(host, mouseX, mouseY, true);
                long i = Util.getMillis();
                //Double click pickup wont track the cell you click
                doubleClick = i - lastClickTime < 250L && lastClickButton == button && getCellAtPos(host, mouseX, mouseY, false).equals(lastClickPos);

                if (cell.isValidCell()) {
                    ModuleEntity<?> entity = cell.getEntity();
                    if (entity != null) {
                        int cs = grid.getCellSize();
                        int mw = entity.getWidth() * cs;
                        int mh = entity.getHeight() * cs;
                        int xPos = (int) xMin() + (entity.getGridX() * cs);
                        int yPos = (int) yMin() + (entity.getGridY() * cs);
                        if (entity.clientModuleClicked(this, player.player, xPos, yPos, mw, mh, mouseX, mouseY, button)) {
                            return true;
                        }
                    }

                    if (player.player.containerMenu.getCarried().isEmpty()) {
                        if (pickBlock) {
                            handleGridClick(host, cell, mouseX, mouseY, button, ClickType.CLONE); //Creative Clone
                        } else {
                            boolean shiftClick = (InputConstants.isKeyDown(mc().getWindow().getWindow(), 340) || InputConstants.isKeyDown(mc().getWindow().getWindow(), 344));
                            ClickType clicktype = ClickType.PICKUP;
                            if (shiftClick) {
                                clicktype = ClickType.QUICK_MOVE;
                            }
                            handleGridClick(host, cell, mouseX, mouseY, button, clicktype);
                        }
                    } else {
                        canDrop = true;
                    }
                }

                lastClickTime = i;
                lastClickPos = getCellAtPos(host, mouseX, mouseY, false);
            }
            lastClickButton = button;
            return true;
        }
        return super.mouseClicked(mouseX, mouseY, button);
    }

static void updateBeam(Level level, BlockPos pos, BeamStuff beamStuff) {
    BlockPos blockpos;
    if (beamStuff.lastCheckY < pos.getY()) {
      blockpos = pos;
      beamStuff.checkingBeamSections = new ArrayList<>();
      beamStuff.lastCheckY = pos.getY() - 1;
    }
    else {
      blockpos = new BlockPos(pos.getX(), beamStuff.lastCheckY + 1, pos.getZ());
    }
    BeaconBlockEntity.BeaconBeamSection currentSection = beamStuff.checkingBeamSections.isEmpty()
        ? null
        : beamStuff.checkingBeamSections.get(beamStuff.checkingBeamSections.size() - 1);
    int surfaceHeight = level.getHeight(Heightmap.Types.WORLD_SURFACE, pos.getX(), pos.getZ());
    for (int yLoop = 0; yLoop < 10 && blockpos.getY() <= surfaceHeight; ++yLoop) {
      BlockState blockstate = level.getBlockState(blockpos);
      if (blockstate.getBlock() instanceof BeaconBeamBlock beamBlock) {
        int beamColor = beamBlock.getColor().getTextureDiffuseColor();
        if (beamStuff.checkingBeamSections.size() <= 1) {
          currentSection = new BeaconBlockEntity.BeaconBeamSection(beamColor);
          beamStuff.checkingBeamSections.add(currentSection);
        }
        else if (currentSection != null) {
          if (beamColor == currentSection.getColor()) {
            currentSection.increaseHeight();
          }
          else {
            int blended = FastColor.ARGB32.average(currentSection.getColor(), beamColor);
            currentSection = new BeaconBlockEntity.BeaconBeamSection(blended);
            beamStuff.checkingBeamSections.add(currentSection);
          }
        }
      }
      else {
        if (currentSection == null
            || (blockstate.getLightBlock(level, blockpos) >= 15 && !blockstate.is(Blocks.BEDROCK))) {
          beamStuff.checkingBeamSections.clear();
          beamStuff.lastCheckY = surfaceHeight;
          break;
        }
        currentSection.increaseHeight();
      }
      blockpos = blockpos.above();
      ++beamStuff.lastCheckY;
    }
    if (level.getGameTime() % 80L == 0L) {
      if (!beamStuff.beamSections.isEmpty()) {
        SoundUtil.playSound(level, pos, SoundEvents.BEACON_AMBIENT);
      }
    }
    if (beamStuff.lastCheckY >= surfaceHeight) {
      beamStuff.lastCheckY = level.getMinBuildHeight() - 1;
      beamStuff.beamSections = beamStuff.checkingBeamSections;
    }
  }

@Override
    public void render(T entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferSource, int packedLight) {
        super.render(entity, entityYaw, partialTicks, poseStack, bufferSource, packedLight);
        float age = entity.tickCount + partialTicks;
        poseStack.pushPose();
        float runeScale = Mth.lerp(partialTicks, entity.prevRuneScale, entity.runeScale) * 2.0F;
        poseStack.translate(0.0D, entity.getBbHeight() * 1.65F, 0.0D);
        poseStack.scale(runeScale, runeScale, runeScale);
        poseStack.mulPose(this.entityRenderDispatcher.cameraOrientation());
        poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
        poseStack.mulPose(Axis.ZP.rotationDegrees(age));
        PoseStack.Pose posestack$pose = poseStack.last();
        Matrix4f matrix4f = posestack$pose.pose();
        Matrix3f matrix3f = posestack$pose.normal();
        VertexConsumer vertexconsumer = bufferSource.getBuffer(RENDER_TYPE);
        vertex(vertexconsumer, matrix4f, matrix3f, LightTexture.FULL_BRIGHT, 0.0F, 0, 0, 1);
        vertex(vertexconsumer, matrix4f, matrix3f, LightTexture.FULL_BRIGHT, 1.0F, 0, 1, 1);
        vertex(vertexconsumer, matrix4f, matrix3f, LightTexture.FULL_BRIGHT, 1.0F, 1, 1, 0);
        vertex(vertexconsumer, matrix4f, matrix3f, LightTexture.FULL_BRIGHT, 0.0F, 1, 0, 0);
        poseStack.popPose();
        if (entity.isAlive()) {
            double currentX = Mth.lerp(partialTicks, entity.xo, entity.getX());
            double currentY = Mth.lerp(partialTicks, entity.yo, entity.getY());
            double currentZ = Mth.lerp(partialTicks, entity.zo, entity.getZ());
            float currentTick = getBob(entity, partialTicks);
            if (entity.trailSnapshots.isEmpty() || currentTick - entity.lastTrailTick > SNAPSHOT_INTERVAL) {
                if (entity.shouldAddTrailSnapshot()) {
                    Map<String, ModelPartPose> snapshot = ModelUtil.saveModelSnapshot(this.getModel().allPartNames, this.getModel()::getAnyDescendantWithName);
                    entity.trailSnapshots.add(0, Pair.of(new Vec3(currentX, currentY, currentZ), new ModelSnapshot(0, Mth.rotLerp(partialTicks, entity.yBodyRotO, entity.yBodyRot), currentTick, snapshot)));
                    entity.lastTrailTick = currentTick;
                }
                entity.trailSnapshots.removeIf(p -> currentTick - p.getSecond().timestamp() > SNAPSHOT_LIFESPAN);
                while (entity.trailSnapshots.size() > 32) {
                    entity.trailSnapshots.remove(entity.trailSnapshots.size() - 1);
                }
            }
            for (int i = 0; i < entity.trailSnapshots.size(); i++) {
                poseStack.pushPose();
                Vec3 trailPos = entity.trailSnapshots.get(i).getFirst();
                ModelSnapshot snapshot = entity.trailSnapshots.get(i).getSecond();
                ModelUtil.loadPoseFromSnapshot(snapshot.poses(), this.shadowModel::getAnyDescendantWithName);
                poseStack.translate(trailPos.x - currentX, trailPos.y - currentY, trailPos.z - currentZ);
                poseStack.mulPose(Axis.YP.rotationDegrees(180.0F - snapshot.yRot()));
                poseStack.scale(-1.0F, -1.0F, 1.0F);
                this.scale(entity, poseStack, partialTicks);
                poseStack.translate(0.0F, -1.5F, 0.0F);
                VertexConsumer vertexConsumer = bufferSource.getBuffer(AFTERIMAGE_RENDER_TYPE);
                float modelAlpha = (1 - Mth.clamp(currentTick - snapshot.timestamp(), 0, SNAPSHOT_LIFESPAN) / SNAPSHOT_LIFESPAN) * 0.35F;
                if (modelAlpha > 0) {
                    this.shadowModel.renderToBuffer(poseStack, vertexConsumer, packedLight, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, modelAlpha);
                }
                poseStack.popPose();
            }
        }
    }

@Nonnull
    @Override
    public InteractionResult useOn(UseOnContext context) {
        ItemStack stack = context.getItemInHand();
        BlockPos pos = context.getClickedPos();
        Level level = context.getLevel();
        Player player = context.getPlayer();

        if (this.getEntity(stack, level) != null) {
            if (level.getBlockState(pos).getBlock() == ModBlocks.CURSED_CAGE_BLOCK.get()){
                BlockEntity blockEntity = level.getBlockEntity(pos);
                if (blockEntity instanceof CursedCageBlockEntity cursedCageBlock){
                    if (!cursedCageBlock.getItem().isEmpty()){
                        return InteractionResult.PASS;
                    } else {
                        if (!level.isClientSide) {
                            level.setBlockAndUpdate(pos, Blocks.SPAWNER.defaultBlockState());
                            BlockEntity blockentity = level.getBlockEntity(pos);
                            if (blockentity instanceof SpawnerBlockEntity) {
                                ((SpawnerBlockEntity) blockentity).getSpawner().setEntityId(this.getEntity(stack, level).getType(), level, level.random, pos);
                            }
                        }
                        this.clearEntity(stack);
                        if (player != null) {
                            player.playSound(ModSounds.FLAME_CAPTURE_RELEASE.get());
                        }
                        stack.shrink(1);

                        return InteractionResult.sidedSuccess(level.isClientSide());
                    }
                }
            }
        } else {
            if (ItemConfig.FireSpawnCage.get()) {
                if (level.getBlockState(pos).getBlock() == Blocks.SPAWNER) {
                    if (!level.isClientSide()) {
                        BlockEntity blockentity = level.getBlockEntity(pos);
                        if (blockentity instanceof SpawnerBlockEntity spawnerBlockEntity) {
                            Entity entity = spawnerBlockEntity.getSpawner().getOrCreateDisplayEntity(level, level.getRandom(), blockentity.getBlockPos());
                            if (entity != null) {
                                this.setEntity(entity, stack);
                                level.destroyBlock(pos, false);
                            }
                        }
                    }
                    if (player != null) {
                        player.playSound(ModSounds.FLAME_CAPTURE_CATCH.get());
                    }
                    return InteractionResult.sidedSuccess(level.isClientSide());
                }
            }
        }

        return super.useOn(context);
    }

@Override
    protected void tick() {
        Level world = getWorld();
        BlockPos pos = getPos();
        if (world != null && world.isClientSide) {
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), 4);
            return;
        }
        if (world == null || pos == null || world.getGameTime() % 200 != 0)
            return;
        int range = 4;
        boolean hasPlayedSound = false;
        for (BlockPos blockpos : BlockPos.betweenClosed(pos.offset(range, -1, range), pos.offset(-range, 1, -range))) {
            BlockState state = world.getBlockState(blockpos);

            if (state.getBlock() instanceof FarmBlock || world.getBlockState(blockpos.above()).getBlock() instanceof CropBlock || world.getBlockState(blockpos.above()).getBlock() instanceof NetherWartBlock || world.getBlockState(blockpos.above()).is(BlockTagProvider.HARVEST_STEMS)) {
                blockpos = blockpos.above();
                state = world.getBlockState(blockpos);
            }
            if (state.getBlock() instanceof NetherWartBlock) {
                if (harvestNetherwart(blockpos, state, world) && !hasPlayedSound) {
                    world.playSound(null, getPos(), SoundEvents.CROP_BREAK, SoundSource.BLOCKS, 1, 1);
                    hasPlayedSound = true;
                }
                continue;
            }

            if (state.getBlock() instanceof CocoaBlock) {
                if (harvestPods(blockpos, state, world) && !hasPlayedSound) {
                    world.playSound(null, getPos(), SoundEvents.CROP_BREAK, SoundSource.BLOCKS, 1, 1);
                    hasPlayedSound = true;
                }
                continue;
            }

            if (state.is(BlockTagProvider.HARVEST_STEMS) && state.getBlock() == world.getBlockState(blockpos.below()).getBlock()) {
                processAndSpawnDrops(blockpos, state, world, false);
                BlockUtil.destroyBlockSafely(world, blockpos, false, null);
                continue;
            }

            if (!(state.getBlock() instanceof CropBlock))
                continue;
            CropBlock cropsBlock = (CropBlock) world.getBlockState(blockpos).getBlock();

            if (!cropsBlock.isMaxAge(state) || !(world instanceof ServerLevel))
                continue;

            if (processAndSpawnDrops(blockpos, state, world, true) && !hasPlayedSound) {
                world.playSound(null, getPos(), SoundEvents.CROP_BREAK, SoundSource.BLOCKS, 1, 1);
                hasPlayedSound = true;
            }
            world.setBlockAndUpdate(blockpos, cropsBlock.getStateForAge(1));
        }
    }

@Override
            public void onPlayerTickActive(PlayerEntity player, ItemStack stack) {
                int energyUSage = (int) applyPropertyModifiers(MPAConstants.ENERGY_CONSUMPTION);

                if (ElectricItemUtils.getPlayerEnergy(player) > energyUSage) {
                    boolean isServerSide = !player.world.isRemote;

                    if ((player.world.getGameTime() % 20) == 0 && isServerSide) {
                        ElectricItemUtils.drainPlayerEnergy(player, energyUSage);
                    }
                    int range = (int) applyPropertyModifiers(MPAConstants.RADIUS);
                    World world = player.world;
                    AxisAlignedBB bounds = player.getBoundingBox().grow(range);

                    if (isServerSide) {
                        bounds.expand(0.2000000029802322D, 0.2000000029802322D, 0.2000000029802322D);
                        if (stack.getDamage() >> 1 >= 7) {
                            List<ArrowEntity> arrows = world.getEntitiesWithinAABB(ArrowEntity.class, bounds);
                            for (ArrowEntity arrow : arrows) {
                                if ((arrow.pickupStatus == ArrowEntity.PickupStatus.ALLOWED) && (world.rand.nextInt(6) == 0)) {
                                    ItemEntity replacement = new ItemEntity(world, arrow.getPosX(), arrow.getPosY(), arrow.getPosZ(), new ItemStack(Items.ARROW));
                                    world.addEntity(replacement);
                                }
                                arrow.remove();
                            }
                        }
                    }

                    for (ItemEntity e : world.getEntitiesWithinAABB(ItemEntity.class, bounds)) {
                        if (e.isAlive() && !e.getItem().isEmpty() && !e.cannotPickup()) {
                            if (isServerSide) {
                                double x = player.getPosX() - e.getPosX();
                                double y = player.getPosY() - e.getPosY();
                                double z = player.getPosZ() - e.getPosZ();

                                double length = Math.sqrt(x * x + y * y + z * z) * 0.75D;

                                x = x / length + player.getMotion().x * 22.0D;
                                y = y / length + player.getMotion().y / 22.0D;
                                z = z / length + player.getMotion().z * 22.0D;

                                e.setMotion(x, y, z);

                                e.isAirBorne = true;
                                if (e.collidedHorizontally) {
                                    e.setMotion(e.getMotion().add(0, 1, 0));
                                }
                            } else if (world.rand.nextInt(20) == 0) {
                                float pitch = 0.85F - world.rand.nextFloat() * 3.0F / 10.0F;
                                world.playSound(e.getPosX(), e.getPosY(), e.getPosZ(), SoundEvents.ENTITY_ENDERMAN_TELEPORT, SoundCategory.PLAYERS, 0.6F, pitch, true);
                            }
                        }
                    }
                }
            }

