				if (this.onGround() && this.playerJumpPendingScale == 0.0F && this.isStanding() && !this.allowStandSliding) {
					f = 0.0F;
					f1 = 0.0F;
				}

				if (this.playerJumpPendingScale > 0.0F && !this.isJumping() && this.onGround()) {
					double d1 = 0;
					Vec3 vec3 = this.getDeltaMovement();
					this.setDeltaMovement(vec3.x, d1, vec3.z);
					this.hasImpulse = true;
					if (f1 > 0.0F) {
						float f2 = Mth.sin(this.getYRot() * ((float)Math.PI / 180F));
						float f3 = Mth.cos(this.getYRot() * ((float)Math.PI / 180F));
						this.setDeltaMovement(this.getDeltaMovement().add((double)(-0.4F * f2 * this.playerJumpPendingScale), 0.0D, (double)(0.4F * f3 * this.playerJumpPendingScale)));
					}

					this.playerJumpPendingScale = 0.0F;
				}

				if (this.isControlledByLocalInstance()) {
					this.setSpeed((float)this.getAttributeValue(Attributes.MOVEMENT_SPEED));
					super.travel(new Vec3((double)f, p_30633_.y, (double)f1));
				} else if (livingentity instanceof Player) {
					this.setDeltaMovement(Vec3.ZERO);
				}

				if (this.onGround()) {
					this.playerJumpPendingScale = 0.0F;
					this.setIsJumping(false);
				}

				this.calculateEntityAnimation(false);
				this.tryCheckInsideBlocks();
			} else {
				super.travel(p_30633_);
			}
		}
	}

private FluidStack removeFluidFromSpace(boolean simulate) {
		FluidStack empty = FluidStack.EMPTY;
		if (world == null)
			return empty;
		if (!world.isLoaded(outputPos))
			return empty;

		BlockState state = world.getBlockState(outputPos);
		FluidState fluidState = state.getFluidState();
		boolean waterlog = state.hasProperty(WATERLOGGED);

		FluidStack drainBlock = VanillaFluidTargets.drainBlock(world, outputPos, state, simulate);
		if (!drainBlock.isEmpty()) {
			if (!simulate && state.hasProperty(BlockStateProperties.LEVEL_HONEY)
				&& AllFluids.HONEY.is(drainBlock.getFluid()))
				AdvancementBehaviour.tryAward(world, pos, AllAdvancements.HONEY_DRAIN);
			return drainBlock;
		}

		if (!waterlog && !state.canBeReplaced())
			return empty;
		if (fluidState.isEmpty() || !fluidState.isSource())
			return empty;

		FluidStack stack = new FluidStack(fluidState.getType(), 1000);

		if (simulate)
			return stack;

		if (FluidHelper.isWater(stack.getFluid()))
			AdvancementBehaviour.tryAward(world, pos, AllAdvancements.WATER_SUPPLY);

		if (waterlog) {
			world.setBlock(outputPos, state.setValue(WATERLOGGED, false), Block.UPDATE_ALL);
			world.scheduleTick(outputPos, Fluids.WATER, 1);
		} else {
			var newState = fluidState.createLegacyBlock()
				.setValue(LiquidBlock.LEVEL, 14);

			var newFluidState = newState.getFluidState();

			if (newFluidState.getType() instanceof FlowingFluidAccessor flowing) {
				var potentiallyFilled = flowing.create$getNewLiquid(world, outputPos, newState);

				// Check if we'd immediately become the same fluid again.
				if (potentiallyFilled.equals(fluidState)) {
					// If so, no need to update the block state.
					return stack;
				}
			}

			world.setBlock(outputPos, newState, Block.UPDATE_ALL);
		}

		return stack;
	}

public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }

        if (!this.isNoAi() && !this.isBaby()) {
            if (this.ringBufferIndex < 0) {
                for (int i = 0; i < this.ringBuffer.length; ++i) {
                    this.ringBuffer[i][0] = this.getYRot();
                    this.ringBuffer[i][1] = this.getY();
                }
            }
            this.ringBufferIndex++;
            if (this.ringBufferIndex == this.ringBuffer.length) {
                this.ringBufferIndex = 0;
            }
            // Just replaced the contents of Mth.interpolateAngle with the returned formula. Why even is this shit @OnlyIn(Client)???
            this.ringBuffer[this.ringBufferIndex][0] = this.yRotO + 0.5F * Mth.wrapDegrees(this.getYRot() - this.yRotO);
            this.ringBuffer[ringBufferIndex][1] = this.getY();
            Vector3d[] avector3d = new Vector3d[this.whale_shark_parts.length];

            for (int j = 0; j < this.whale_shark_parts.length; ++j) {
                this.whale_shark_parts[j].collideWithNearbyEntities();
                avector3d[j] = new Vector3d(this.whale_shark_parts[j].getX(), this.whale_shark_parts[j].getY(), this.whale_shark_parts[j].getZ());
            }
            float f15 = (float) (this.getMovementOffsets(5, 1.0F)[1] - this.getMovementOffsets(10, 1.0F)[1]) * 10.0F * ((float) Math.PI / 180F);
            float f16 = Mth.cos(f15);
            float yaw = this.getYRot() * ((float) Math.PI / 180F);
            float pitch = this.getXRot() * ((float) Math.PI / 180F);
            float f3 = Mth.sin(yaw) * (1 - Math.abs(this.getXRot() / 90F));
            float f18 = Mth.cos(yaw) * (1 - Math.abs(this.getXRot() / 90F));

            double[] adouble = this.getMovementOffsets(5, 1.0F);

            for (int k = 0; k < getMultiparts(); ++k) {
                EntityWhaleSharkPart whale_shark_part = this.whale_shark_parts[k];

                double[] adouble1 = this.getMovementOffsets(5 + k * 2, 1.0F);
                float f7 = yaw + (float) Mth.wrapDegrees(adouble1[0] - adouble[0]) * ((float) Math.PI / 180F);
                float f20 = Mth.sin(f7) * (1 - Math.abs(this.getXRot() / 90F));
                float f21 = Mth.cos(f7) * (1 - Math.abs(this.getXRot() / 90F));
                float f23 = k == 0 ? (float) (k + 3) : (k + 3) * -1;
                float value = Mth.clamp(pitch * k, -20, 20);
                this.setPartPosition(whale_shark_part, -(f3 * 0.5F + f20 * f23) * f16, value, (f18 * 0.5F + f21 * f23) * f16);
                this.whale_shark_parts[k].xo = avector3d[k].x;
                this.whale_shark_parts[k].yo = avector3d[k].y;
                this.whale_shark_parts[k].zo = avector3d[k].z;
                this.whale_shark_parts[k].xOld = avector3d[k].x;
                this.whale_shark_parts[k].yOld = avector3d[k].y;
                this.whale_shark_parts[k].zOld = avector3d[k].z;
            }
        }
    }

@Override
    protected void readAdditionalSaveData(CompoundTag compound)
    {
        this.shoalFishData.clear();
        var shoalFishListTag = compound.getList(SHOAL_FISH_TAG, Tag.TAG_COMPOUND);

        for (var i = 0; i < shoalFishListTag.size(); i++)
        {
            var compoundTag = shoalFishListTag.getCompound(i);
            UUID uuid;

            if (!compoundTag.contains(ShoalFishData.ID_TAG, Tag.TAG_STRING) || compoundTag.getString(ShoalFishData.ID_TAG).isEmpty())
            {
                return;
            }

            if (compoundTag.hasUUID(ShoalFishData.UUID_TAG))
            {
                uuid = compoundTag.getUUID(ShoalFishData.UUID_TAG);
            }
            else
            {
                uuid = UUID.randomUUID();
            }

            this.shoalFishData.add(new ShoalFishData(compoundTag.getString(ShoalFishData.ID_TAG), uuid, compoundTag.getCompound(ShoalFishData.DATA_TAG)));
        }

        if (compound.contains(LIFETIME_TAG, Tag.TAG_LONG))
        {
            this.expiredAt = compound.getLong(LIFETIME_TAG);
        }
        if (compound.contains(TREASURED_TAG, Tag.TAG_BYTE))
        {
            this.setTreasured(compound.getBoolean(TREASURED_TAG));
        }

        var participatesListTag = compound.getList(PARTICIPATES_TAG, Tag.TAG_COMPOUND);

        for (var i = 0; i < participatesListTag.size(); i++)
        {
            var compoundTag = participatesListTag.getCompound(i);

            if (compoundTag.hasUUID(UUID_TAG))
            {
                this.participates.add(compoundTag.getUUID(UUID_TAG));
            }
        }

        if (!this.level().isClientSide() && compound.contains(NATURAL_TAG) && compound.getBoolean(NATURAL_TAG))
        {
            this.createNaturalSpawn(false);
        }

        FOTPlatform.syncClientShoalFish(this, false);
    }

@Override
    public void tick() {
        if (te.isRemoved() || !hacker.isAlive()) {
            // TODO maybe find a way to catch up with hackers who disconnect just to avoid getting zapped?
            return;
        }

        boolean wasDone = isSimulationDone();

        if (!(hacker.containerMenu instanceof SecurityStationHackingMenu) && !playerSimulation.isHackComplete()) {
            // hacker closed their window before hack complete: AI wins
            for (int slot = 0; slot < HackSimulation.GRID_SIZE; slot++) {
                HackSimulation.Node node = aiSimulation.getNodeAt(slot);
                if (node != null && node.getType() == NetworkComponentType.NETWORK_IO_PORT) {
                    node.setHackProgress(slot, 1F, true);
                    break;
                }
            }
        } else if (!wasDone) {
            playerSimulation.tick();
            aiSimulation.tick();
        }

        boolean syncToClient = (te.nonNullLevel().getGameTime() & 0x7) == 0;
        if (!wasDone && aiSimulation.isHackComplete()) {
            // security station wins
            syncToClient = true;
            if (aiSimulation.isAwake()) {
                // if hack window is closed before AI detects intrustion, hacker gets away with it
                if (te.nonNullLevel().isClientSide) {
                    hacker.playSound(SoundEvents.ENDERMAN_DEATH, 1f, 1f);
                } else {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.1").withStyle(ChatFormatting.RED), false);
                    if (!justTesting) {
                        hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.2").withStyle(ChatFormatting.RED), false);
                        te.retaliate(hacker);
                    }
                }
            }
        } else if (!wasDone && playerSimulation.isHackComplete()) {
            // hacker wins
            syncToClient = true;
            if (te.nonNullLevel().isClientSide) {
                hacker.playSound(SoundEvents.PLAYER_LEVELUP, 1f, 1f);
            } else {
                hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.1").withStyle(ChatFormatting.GREEN), false);
                if (!justTesting) {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.2").withStyle(ChatFormatting.GREEN), false);
                    te.addHacker(hacker.getGameProfile());
                }
            }
        }
        if (!te.nonNullLevel().isClientSide() && syncToClient) {
            NetworkHandler.sendToPlayer(PacketSyncHackSimulationUpdate.forSecurityStation(te), (ServerPlayer) hacker);
        }
    }

private void clientTick(ClientTickEvent.Post event) {
		Minecraft mc = Minecraft.getInstance();

		if (!mc.isPaused()) {
			time++;

			lastAurora = aurora;
			if (mc.level != null && mc.getCameraEntity() != null && !TFConfig.getValidAuroraBiomes(mc.level.registryAccess()).isEmpty()) {
				RegistryAccess access = mc.level.registryAccess();
				Holder<Biome> biome = mc.level.getBiome(mc.getCameraEntity().blockPosition());
				if (TFConfig.getValidAuroraBiomes(access).stream().anyMatch(c -> holderMatcher.match(c, biome)))
					aurora++;
				else
					aurora--;
				aurora = Mth.clamp(aurora, 0, 60);
			} else {
				aurora = 0;
			}

			BugModelAnimationHelper.animate();

			if (mc.level != null) {
				if (mc.level.getSkyFlashTime() > 0) {
					MagicPaintingRenderer.lastLightning = mc.level.getGameTime();
				}

				if (TFConfig.firstPersonEffects && mc.player != null) {
					HashSet<ChunkPos> chunksInRange = new HashSet<>();
					for (int x = -16; x <= 16; x += 16) {
						for (int z = -16; z <= 16; z += 16) {
							chunksInRange.add(new ChunkPos((int) (mc.player.getX() + x) >> 4, (int) (mc.player.getZ() + z) >> 4));
						}
					}
					for (ChunkPos pos : chunksInRange) {
						if (mc.level.getChunk(pos.x(), pos.z(), ChunkStatus.FULL, false) != null) {
							List<BlockEntity> beanstalksInChunk = mc.level.getChunk(pos.x(), pos.z()).getBlockEntities().values().stream()
								.filter(blockEntity -> blockEntity instanceof GrowingBeanstalkBlockEntity beanstalkBlock && beanstalkBlock.isBeanstalkRumbling())
								.toList();
							if (!beanstalksInChunk.isEmpty()) {
								BlockEntity beanstalk = beanstalksInChunk.getFirst();
								Player player = mc.player;
								shakeIntensity = (float) (1.0F - mc.player.distanceToSqr(Vec3.atCenterOf(beanstalk.getBlockPos())) / Math.pow(16, 2));
								if (shakeIntensity > 0) {
									player.snapTo(player.getX(), player.getY(), player.getZ(),
										player.getYRot() + (player.getRandom().nextFloat() - 0.5F) * shakeIntensity,
										player.getXRot() + (player.getRandom().nextFloat() * 2.5F - 1.25F) * shakeIntensity);
									shakeIntensity = 0.0F;
									break;
								}
							}
						}
					}
				}
			}
		}
	}

public static void init(MinecraftServer server) {
		enabled.set(AoAConfigs.SERVER.skillsLeaderboardEnabled.get());

		if (!isEnabled())
			return;

		try {
			dataPath = ObjectUtil.getOrCreateDirectory(server.getWorldPath(DATA_DIR), "aoa_leaderboards").toAbsolutePath().toString();
		}
		catch (Exception ex) {
			Logging.logMessage(Level.ERROR, "Unable to create or access directory for database storage. Disabling leaderboard.", ex);

			shutdown();
			return;
		}

		updateTaskQueue = new LinkedBlockingQueue<>();
		retrievalTaskQueue = new LinkedBlockingQueue<>();

		try {
			DriverManager.registerDriver(new JDBCDriver());
		}
		catch (SQLException ex) {
			Logging.logMessage(Level.ERROR, "Unable to attach Skills Leaderboard database driver, disabling leaderboard.", ex);

			shutdown();

			return;
		}

		Logging.logMessage(Level.INFO, "Starting threads and opening connections for skills database..");

		int maxThreads = AoAConfigs.SERVER.maxLeaderboardThreads.get();
		int updateThreadCount = (int)Math.ceil(maxThreads / 1.5f);
		int retrievalThreadCount = maxThreads - updateThreadCount;
		Properties connectionProperties = new Properties();
		updateThreads = new InsertionConnection[updateThreadCount];
		retrievalThreads = new RetrievalConnection[retrievalThreadCount];

		connectionProperties.put("user", AoAConfigs.SERVER.databaseUsername.get());
		connectionProperties.put("password", AoAConfigs.SERVER.databasePassword.get());
		connectionProperties.put("shutdown", "true");
		connectionProperties.put("hsqldb.log_size", "5");

		for (int i = 0; i < updateThreadCount; i++) {
			updateThreads[i] = new InsertionConnection(updateTaskQueue, connectionProperties);
			updateThreads[i].start();
		}

		for (int i = 0; i < retrievalThreadCount; i++) {
			retrievalThreads[i] = new RetrievalConnection(retrievalTaskQueue, connectionProperties);
			retrievalThreads[i].start();
		}

		new InitializeLeaderboardTask().queue();
	}

public void travel(Vec3 p_30633_) {
        if (this.isAlive()) {
            LivingEntity livingentity = (LivingEntity) this.getControllingPassenger();
            if (this.isVehicle() && this.isSaddled() && livingentity != null) {
                this.setYRot(livingentity.getYRot());
                this.yRotO = this.getYRot();
                this.setXRot(livingentity.getXRot() * 0.5F);
                this.setRot(this.getYRot(), this.getXRot());
                this.yBodyRot = this.getYRot();
                this.yHeadRot = this.yBodyRot;
                float f = livingentity.xxa * 0.5F;
                float f1 = livingentity.zza;

                if (this.onGround() && this.playerJumpPendingScale == 0.0F && this.isStanding() && !this.allowStandSliding) {
                    f = 0.0F;
                    f1 = 0.0F;
                }

                if (this.playerJumpPendingScale > 0.0F && !this.isJumping() && this.onGround()) {
                    double d0 = this.getCustomJump() * (double) this.playerJumpPendingScale * (double) this.getBlockJumpFactor();
                    double d1 = d0 + this.getJumpBoostPower();
                    Vec3 vec3 = this.getDeltaMovement();
                    this.setDeltaMovement(vec3.x, d1, vec3.z);
                    this.setIsJumping(true);
                    this.hasImpulse = true;
                    ForgeHooks.onLivingJump(this);
                    if (f1 > 0.0F) {
                        float f2 = Mth.sin(this.getYRot() * ((float) Math.PI / 180F));
                        float f3 = Mth.cos(this.getYRot() * ((float) Math.PI / 180F));
                        this.setDeltaMovement(this.getDeltaMovement().add((-0.4F * f2 * this.playerJumpPendingScale), 0.0D, (0.4F * f3 * this.playerJumpPendingScale)));
                    }

                    this.playerJumpPendingScale = 0.0F;
                }

                this.flyDist = this.getSpeed() * 0.1F;
                if (this.isControlledByLocalInstance()) {
                    this.setSpeed((float) this.getAttributeValue(Attributes.MOVEMENT_SPEED));
                    super.travel(new Vec3(f, p_30633_.y, f1));
                } else if (livingentity instanceof Player) {
                    this.setDeltaMovement(Vec3.ZERO);
                }

                if (this.onGround()) {
                    this.playerJumpPendingScale = 0.0F;
                    this.setIsJumping(false);
                }

                this.calculateEntityAnimation(false);
                this.tryCheckInsideBlocks();
            } else {
                this.flyDist = 0.02F;
                super.travel(p_30633_);
            }
        }
    }

@Override
    public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext context) {
        if (context.getLevel().isClientSide()) {
            return InteractionResult.PASS;
        }

        final Player player = context.getPlayer();
        final Level level = context.getLevel();
        final BlockPos pos = context.getClickedPos();

        if (player == null) {
            return InteractionResult.PASS;
        }

        final Block state = level.getBlockState(pos).getBlock();
        final boolean bulk = InteractionUtil.isInAlternateUseMode(player);
        final Queue<BlockPos> next = new ArrayDeque<>();
        final Set<BlockPos> closed = new HashSet<>();
        final Set<Block> commonBlocks = this.getCommonBlocks();

        next.add(pos);
        int blocks = 0;

        while (blocks < BLOCK_ERASE_LIMIT && next.peek() != null) {
            final BlockPos wc = next.poll();
            final Block c_state = level.getBlockState(wc).getBlock();
            final boolean contains = state == c_state || bulk && commonBlocks.contains(c_state);

            closed.add(wc);

            if (contains) {
                blocks++;
                level.setBlock(wc, Blocks.AIR.defaultBlockState(), 2);
                level.destroyBlock(wc, false);

                if (isInsideBox(wc, pos)) {
                    for (int x = -1; x <= 1; x++) {
                        for (int y = -1; y <= 1; y++) {
                            for (int z = -1; z <= 1; z++) {
                                if (0 == x && 0 == y && 0 == z) {
                                    continue;
                                }
                                final BlockPos nextPos = wc.offset(x, y, z);
                                if (!closed.contains(nextPos)) {
                                    next.add(nextPos);
                                }
                            }
                        }
                    }
                }
            }
        }

        AELog.info("Delete " + blocks + " blocks");

        return InteractionResult.SUCCESS;
    }

private void regenerate() {

		if (world.isRemote) return;

		// Remove containment effects from nearby targets when shrine regenerates
		removeContainmentFromNearbyTargets();

		// Reset shrine state
		this.conquered = false;
		this.regenerationTime = 0;
		this.activated = false;
		Arrays.fill(this.linkedWizards, null);
		// Keep lootedPlayers list - it's permanent for this shrine instance

		// Force a short delay before allowing reactivation to prevent immediate re-activation
		this.lastRegenerationTime = world.getTotalWorldTime();

		// Forcibly replace whatever block is above the altar with a fresh chest
		BlockPos chestPos = this.pos.up();

		// Always replace the block above with a fresh chest during regeneration
		world.setBlockState(chestPos, Blocks.CHEST.getDefaultState());

		// Set up the loot table for the shrine chest
		TileEntity chestTileEntity = world.getTileEntity(chestPos);
		if (chestTileEntity instanceof TileEntityChest) {
			TileEntityChest chest = (TileEntityChest) chestTileEntity;
			chest.setLootTable(new ResourceLocation(Wizardry.MODID, "chests/shrine"), world.rand.nextLong());
		}

		// Link and apply arcane lock to the container
		if (chestTileEntity != null) {
			this.linkContainer(chestTileEntity);
			chestTileEntity.getTileData().setUniqueId(ArcaneLock.NBT_KEY, new UUID(0, 0)); // Nil UUID for shrine lock
			chestTileEntity.markDirty(); // Mark tile entity as dirty for client sync

			// Trigger visual update for arcane lock effect
			IBlockState blockState = world.getBlockState(chestPos);
			world.markAndNotifyBlock(chestPos, null, blockState, blockState, 3);
			world.notifyBlockUpdate(chestPos, blockState, blockState, 3); // Additional client sync
		}

		// Visual and audio effects for regeneration
		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		//	WizardryPacketHandler.net.sendToAllAround(new PacketConquerShrine.Message(this.pos), new NetworkRegistry.TargetPoint(this.world.provider.getDimension(), x, y, z, 64));

		if (world.isRemote) {
			ParticleBuilder.create(Type.SPHERE).pos(x, y + 1, z).clr(0xf06495).scale(5).time(12).spawn(world);
		}

		world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_ACTIVATE, SoundCategory.BLOCKS, 1.5f, 1, false);

		this.markDirty();
	}

