private void showFlow(GuiGraphics graphics, int mouseX, int mouseY) {
        RenderSystem.setShader(GameRenderer::getPositionColorShader);
        RenderSystem.lineWidth(3f);

        IProgWidget hovered = getHoveredWidget(mouseX, mouseY);
        Map<String, List<IProgWidget>> labelWidgets = new HashMap<>();
        for (IProgWidget w : progWidgets) {
            if (w instanceof ILabel l) {
                labelWidgets.computeIfAbsent(l.getLabel(), k -> new ArrayList<>()).add(w);
            }
        }

        float pt = 0.125f + (Minecraft.getInstance().level.getGameTime() % 30 + Minecraft.getInstance().getTimer().getGameTimeDeltaTicks()) / 40f;

        for (IProgWidget widget : progWidgets) {
            if (widget instanceof IJump jump) {
                for (String jumpLocation : jump.getPossibleJumpLocations()) {
                    for (IProgWidget labelWidget : labelWidgets.getOrDefault(jumpLocation, List.of())) {
                        int x1 = widget.getX() + widget.getWidth() / 4;
                        int y1 = widget.getY() + widget.getHeight() / 4;
                        int x2 = labelWidget.getX() + labelWidget.getWidth() / 4;
                        int y2 = labelWidget.getY() + labelWidget.getHeight() / 4;
                        float angle = (float) Mth.atan2(y2 - y1, x2 - x1);
                        int len = (int) Math.sqrt((x2 - x1) * (x2 - x1) + (y2 - y1) * (y2 - y1));

                        boolean highlight = widget == hovered || labelWidget == hovered;
                        float arrowPos = len * (highlight ? pt : 0.5f);
                        int colorHi = highlight ? 0xFF00FF00 : 0xFFFFFFFF;
                        int colorLo = highlight ? 0xFF008000 : 0xFF606060;

                        graphics.pose().pushPose();
                        graphics.pose().translate(guiLeft + x1, guiTop + y1, highlight ? 100f : 0f);
                        graphics.pose().mulPose(Axis.ZP.rotation(angle));
                        Matrix4f posMat = graphics.pose().last().pose();

                        GuiUtils.drawWithTesselator(VertexFormat.Mode.DEBUG_LINES, DefaultVertexFormat.POSITION_COLOR, wr -> {
                            for (int i = 0; i < 2; i++) {
                                int color = i == 0 ? colorHi : colorLo;
                                float yOff = i == 0 ? 0f : 0.13f;
                                wr.addVertex(posMat, 0f, yOff, 0f).setColor(color);
                                wr.addVertex(posMat, len, yOff, 0f).setColor(color);

                                Vec3 arrowVec = new Vec3(-ARROW_SIZE, 0, 0);
                                arrowVec = arrowVec.yRot(ARROW_ANGLE);
                                wr.addVertex(posMat, arrowPos, yOff, 0.0f).setColor(color);
                                wr.addVertex(posMat, arrowPos + (float) arrowVec.x, (float) arrowVec.z + yOff, 0.0f).setColor(color);
                                arrowVec = arrowVec.yRot(-2 * ARROW_ANGLE);
                                wr.addVertex(posMat, arrowPos, yOff, 0.0f).setColor(color);
                                wr.addVertex(posMat, arrowPos + (float) arrowVec.x, (float) arrowVec.z + yOff, 0.0f).setColor(color);
                            }
                        });
                        graphics.pose().popPose();
                    }
                }
            }
        }
    }

@Nullable
	protected static TeleportTransition placeInExistingPortal(TeleporterCache cache, ServerLevel destDim, Entity entity, BlockPos pos) {
		boolean flag = true;
		BlockPos blockpos;
		ColumnPos columnPos = new ColumnPos(entity.blockPosition().getX(), entity.blockPosition().getZ()); // Must be the position from the src dim

		PortalPosition portalPosition = cache.getPortalPosition(destDim.dimension().identifier(), columnPos);
		if (portalPosition != null) {
			blockpos = portalPosition.pos;
			portalPosition.lastUpdateTime = destDim.getGameTime();
			flag = false;
			// Validate that the Portal still exists
			LOGGER.debug("Using cache, validating. {}", blockpos);
			if (blockpos == null || !destDim.getBlockState(blockpos).is(TFBlocks.TWILIGHT_PORTAL)) {
				// Portal was broken, we need to recreate it.
				LOGGER.debug("Portal Invalid, recreating.");
				blockpos = null;
				cache.removeInvalidPos(destDim.dimension(), columnPos);
			}
		} else {
			blockpos = getPortalPosition(destDim, pos);
		}

		if (blockpos == null) {
			return null;
		} else {
			if (flag) {
				LOGGER.debug("Caching Src Portal Blocks to {}", blockpos);
				Map<BlockPos, Boolean> portalBlocks = new HashMap<>();
				portalBlocks.put(entity.blockPosition(), true);
				TFPortalBlock.recursivelyValidatePortal(entity.level(), entity.blockPosition(), portalBlocks, new MutableInt(0), entity.level().getBlockState(entity.blockPosition()));
				BlockPos finalBlockpos = blockpos;
				portalBlocks.forEach((blockPos, b) -> {
					if (b) {
						LOGGER.debug("Caching {}", blockPos);
						cache.addBlockToCache(destDim.dimension(), new ColumnPos(blockPos.getX(), blockPos.getZ()), new PortalPosition(finalBlockpos, destDim.getGameTime()));
					}
				});
				destDim.getChunkSource().addTicketWithRadius(TicketType.PORTAL, ChunkPos.containing(blockpos), 3);
			}

			// replace with our own placement logic
			BlockPos[] portalBorder = getBoundaryPositions(destDim, blockpos).toArray(new BlockPos[0]);
			BlockPos borderPos;
			if (portalBorder.length > 0) {
				borderPos = portalBorder[destDim.getRandom().nextInt(portalBorder.length)];
			} else {
				borderPos = blockpos;
			}

			double portalX = borderPos.getX() + 0.5;
			double portalY = borderPos.getY() + 1.0;
			double portalZ = borderPos.getZ() + 0.5;

			return makeTransition(destDim, entity, safePosInColumn(destDim, entity, portalX, portalY, portalZ));
		}
	}

public boolean tick() {
			// If empty, this swapper is done.
			if (candidateQueue.isEmpty()) {
				return false;
			}

			int remainingSwaps = BLOCK_SWAP_RATE;
			while (remainingSwaps > 0 && !candidateQueue.isEmpty()) {
				SwapCandidate cand = candidateQueue.poll();

				// If we've already completed this location, move along, as this
				// is just a suboptimal one.
				if (completedCoords.contains(cand.coordinates)) {
					continue;
				}

				// If this candidate is out of range, discard it.
				if (cand.range <= 0) {
					continue;
				}

				// Otherwise, perform the break and then look at the adjacent tiles.
				ToolCommons.removeBlockWithDrops(player, truncator, world,
						cand.coordinates,
						state -> state.is(BlockTags.MINEABLE_WITH_AXE) || state.is(BlockTags.LEAVES));

				remainingSwaps--;

				completedCoords.add(cand.coordinates);

				// Then, go through all of the adjacent blocks and look if
				// any of them are any good.
				for (BlockPos adj : adjacent(cand.coordinates)) {
					var state = world.getBlockState(adj);

					boolean isWood = state.is(BlockTags.LOGS);
					boolean isLeaf = state.is(BlockTags.LEAVES);
					// TODO: Make "blocks the axe will propagate through" a tag
					boolean shouldPropagateThrough = isWood || isLeaf
							|| state.is(Blocks.MANGROVE_ROOTS);

					if (!shouldPropagateThrough) {
						continue;
					}

					// If this is a leaf, it gets
					// the minimum of the leaf range and the current range - 1.
					// Otherwise, it gets the standard range - 1.
					int newRange = isLeaf ? Math.min(LEAF_BLOCK_RANGE, cand.range - 1) : cand.range - 1;

					candidateQueue.offer(new SwapCandidate(adj, newRange));
				}
			}

			// If we did any iteration, then hang around until next tick.
			return true;
		}

