@TestPlot("qnb_deferred_side_effects")
    public static void testQuantumBridge(PlotBuilder plot) {
        var qnbA = BlockPos.ZERO.above();
        var qnbB = qnbA.east(4);

        buildQnbRing(plot, qnbA);
        buildQnbRing(plot, qnbB);

        plot.test(helper -> {
            helper.startSequence()
                    // Wait until both QNBs have formed
                    .thenWaitUntil(() -> {
                        var coreA = helper.getBlockEntity(qnbA, QuantumBridgeBlockEntity.class);
                        var coreB = helper.getBlockEntity(qnbB, QuantumBridgeBlockEntity.class);
                        helper.check(coreA.isFormed(), "QNB A not formed", qnbA);
                        helper.check(coreB.isFormed(), "QNB B not formed", qnbB);
                    })
                    .thenExecute(() -> {
                        var coreA = helper.getBlockEntity(qnbA, QuantumBridgeBlockEntity.class);
                        var coreB = helper.getBlockEntity(qnbB, QuantumBridgeBlockEntity.class);

                        // Create matching singularities
                        var singularities = AEItems.QUANTUM_ENTANGLED_SINGULARITY.stack();
                        QuantumBridgeBlockEntity.assignFrequency(singularities);
                        var resource = ItemResource.of(singularities);

                        // Get handlers for both QNBs
                        var handlerA = coreA.getExposedItemHandler(Direction.NORTH);
                        var handlerB = coreB.getExposedItemHandler(Direction.NORTH);

                        try (var tx = Transaction.open(null)) {
                            // Insert singularities into both QNBs
                            helper.check(handlerA.insert(resource, 1, tx) == 1, "Should insert singularity A", qnbA);
                            helper.check(handlerB.insert(resource, 1, tx) == 1, "Should insert singularity B", qnbB);

                            // Verify singularities are visible
                            helper.check(!coreA.getInternalInventory().getStackInSlot(0).isEmpty(),
                                    "Singularity A visible in transaction", qnbA);
                            helper.check(!coreB.getInternalInventory().getStackInSlot(0).isEmpty(),
                                    "Singularity B visible in transaction", qnbB);

                            // But clusters should NOT be linked yet (side-effect not triggered)
                            var gridA = helper.getGrid(qnbA);
                            var gridB = helper.getGrid(qnbB);
                            helper.check(gridA != gridB, "Grids should NOT be linked before commit", qnbA);

                            tx.commit();
                        }
                    })
                    // Wait until linked (-> same grid) after commit
                    .thenWaitUntil(() -> {
                        var gridA = helper.getGrid(qnbA);
                        var gridB = helper.getGrid(qnbB);
                        helper.check(gridA == gridB, "Grids should be linked after commit", qnbA);
                    })
                    .thenSucceed();
        });
    }

private static void renderVoltmeterOverlay(GuiGraphics graphics, Player player, int scaledWidth, int scaledHeight)
	{
		HitResult rrt = ClientUtils.mc().hitResult;
		Either<BlockPos, Integer> pos = null;
		if(rrt instanceof BlockHitResult mop)
			pos = Either.left(mop.getBlockPos());
		else if(rrt instanceof EntityHitResult ehr)
			pos = Either.right(ehr.getEntity().getId());

		if(pos==null)
			return;

		ArrayList<Component> text = new ArrayList<>();

		boolean matches = VoltmeterItem.lastEnergyUpdate.pos().equals(pos);
		long sinceLast = player.level().getGameTime()-VoltmeterItem.lastEnergyUpdate.measuredInTick();
		if(!matches||sinceLast > 20)
			PacketDistributor.sendToServer(new MessageRequestEnergyUpdate(pos));

		if(VoltmeterItem.lastEnergyUpdate.isValid()&&matches)
		{
			int maxStorage = VoltmeterItem.lastEnergyUpdate.capacity();
			int storage = VoltmeterItem.lastEnergyUpdate.stored();
			String storageText = Utils.toScientificNotation(storage, "0##", 100000);
			String capacityText = Utils.toScientificNotation(maxStorage, "0##", 100000);
			text.add(Component.translatable(Lib.DESC_INFO+"energyStored", storageText+" / "+capacityText));
		}

		if(rrt instanceof BlockHitResult mop)
		{
			matches = VoltmeterItem.lastRedstoneUpdate.pos().equals(mop.getBlockPos());
			sinceLast = player.level().getGameTime()-VoltmeterItem.lastRedstoneUpdate.measuredInTick();
			if(!matches||sinceLast > 20)
				PacketDistributor.sendToServer(new MessageRequestRedstoneUpdate(mop.getBlockPos()));

			if(VoltmeterItem.lastRedstoneUpdate.isSignalSource()&&matches)
				VoltmeterItem.lastRedstoneUpdate.rsLevels().consume(
						aByte -> text.add(Component.translatable(Lib.DESC_INFO+"redstone_level", String.valueOf(aByte))),
						pairs -> {
							if(pairs.length > 0)
							{
								text.add(Component.translatable(Lib.DESC_INFO+"redstone_level", ""));
								for(Pair<DyeColor, Byte> p : pairs)
								{
									Component c = Component.translatable(Lib.DESC_INFO+"redstone_level_on_channel",
											p.getSecond(),
											getRedstoneColorComponent(p.getFirst())
									);
									// if the value is less than 10, we want a space before it which has the same width as a digit
									text.add(p.getSecond() < 10?new SpacerComponent("0").append(c): c);
								}
							}
						}
				);
		}

		BlockOverlayUtils.drawBlockOverlayText(graphics, text, scaledWidth, scaledHeight);
	}

private void refreshList() {
        IGrid grid = this.getMainNode().getGrid();
        if (grid == null) {
            aeFluidHandler.clearInventory(0);
            return;
        }

        MEStorage networkStorage = grid.getStorageService().getInventory();
        var counter = networkStorage.getAvailableStacks();

        // Use a PriorityQueue to sort the stacks on size, take the first CONFIG_SIZE
        // biggest stacks.
        PriorityQueue<Object2LongMap.Entry<AEKey>> topFluids = new PriorityQueue<>(
                Comparator.comparingLong(Object2LongMap.Entry<AEKey>::getLongValue));

        for (Object2LongMap.Entry<AEKey> entry : counter) {
            long amount = entry.getLongValue();
            AEKey what = entry.getKey();

            if (amount <= 0) continue;
            if (!(what instanceof AEFluidKey fluidKey)) continue;

            long request = networkStorage.extract(what, amount, Actionable.SIMULATE, actionSource);
            if (request == 0) continue;

            // Ensure that it is valid to configure with this stack
            if (autoPullTest != null && !autoPullTest.test(new GenericStack(fluidKey, amount))) continue;
            if (amount >= minStackSize) {
                if (topFluids.size() < CONFIG_SIZE) {
                    topFluids.offer(entry);
                } else if (amount > topFluids.peek().getLongValue()) {
                    topFluids.poll();
                    topFluids.offer(entry);
                }
            }
        }

        // Now, topFluids is a PQ with CONFIG_SIZE highest amount fluids in the system.
        int index;
        int fluidAmount = topFluids.size();
        for (index = 0; index < CONFIG_SIZE; index++) {
            if (topFluids.isEmpty()) break;
            Object2LongMap.Entry<AEKey> entry = topFluids.poll();
            AEKey what = entry.getKey();
            long amount = entry.getLongValue();

            // If we get here, the fluid has already been checked by the PQ.
            long request = networkStorage.extract(what, amount, Actionable.SIMULATE, actionSource);

            // Since we want our fluids to be displayed from highest to lowest, but poll() returns
            // the lowest first, we fill in the slots starting at fluidAmount-1
            var slot = this.aeFluidHandler.getInventory()[fluidAmount - index - 1];
            slot.setConfig(new GenericStack(what, 1));
            slot.setStock(new GenericStack(what, request));
        }

        aeFluidHandler.clearInventory(index);
    }

public void aiStep() {
        super.aiStep();

        if (!this.level.isClientSide) {
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.003D, 0.0D));
                if (!this.isNotMoving() && this.random.nextInt(5) == 0 && this.getDeltaMovement().horizontalDistance() > 0.08) {
                    Vec3 testpos = this.position().add(Math.cos(Math.toRadians(this.getYRot()+ 90)) * -0.8, 0, Math.sin(Math.toRadians(this.getYRot() + 90)) * -0.8);
                    BlockPos testblockpos = new BlockPos(testpos);
                    if (level.getBlockState(new BlockPos(testblockpos.below())).is(BlockTags.MINEABLE_WITH_SHOVEL))
                        ((ServerLevel)this.level).sendParticles(new BlockParticleOption(ParticleTypes.FALLING_DUST, this.level.getBlockState(testblockpos.below())), testpos.x, testpos.y + 0.2, testpos.z, 2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, 0);
                    else
                        ((ServerLevel)this.level).sendParticles(ParticleTypes.UNDERWATER, testpos.x, testpos.y + 0.2, testpos.z, 2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, 0);
                }
            }

            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                int i = this.random.nextInt(3000);
                if (i <= 10 && !this.isInWater()) {
                    this.getNavigation().stop();
                    this.setSitting(true);
                }
                else if ((i == 11 || this.isInWater()) && this.isSitting()) {
                    this.setSitting(false);
                }
                else if (i > 2900) {
                    if (this.isVehicle() && this.getFirstPassenger() != null) {
                        this.setAnimation(ATTACK_THRASH);
                        doHurtTarget(this.getFirstPassenger());
                    }
                    else {
                        this.setAnimation(IDLE_TONGUE);
                    }
                }
            }
        }
        else {
            if (Math.abs(this.getYRot() - this.yRotO) > 0.005) {
                this.offset = Mth.rotLerp(0.05F, this.offset, (this.getYRot() - this.yRotO));
            }
            if (this.isInWater() && !this.isNotMoving()) {
                if (this.swimProgress < 20)
                    this.swimProgress++;
            } else if ((!this.isInWater() || this.isNotMoving()) && this.swimProgress > 0) {
                this.swimProgress--;
            }
            if (this.tickCount % 120 < 11) {
                if (this.tickCount % 120 == 1) {
                    neck_val = (float) (0.8F - this.random.nextDouble() * 1.6F);
                    head_val = (float) (0.4F - this.random.nextDouble() * 0.8F);
                }
                this.head_movement = new Pair<>(Mth.lerp(0.1F, head_movement.getA(), neck_val), Mth.lerp(0.1F, head_movement.getB(), head_val));
            }
        }
    }

public static void serverTick(@NotNull Level level, @NotNull BlockPos pos, @NotNull BlockState state, @NotNull TotemBlockEntity blockEntity) {
        if (blockEntity.isDisabled) {
            level.destroyBlock(pos, true);
            if (level.getBlockState(pos.below()).getBlock() instanceof TotemBaseBlock) {
                level.destroyBlock(pos.below(), true);
            }
        }

        //Update tile status
        long time = level.getGameTime();
        if (time % 20 == 0) {
            blockEntity.updateTileStatus();
        }


        //Update capture progress/states
        if (!blockEntity.checkTileStatus()) {
            if (!blockEntity.isInsideVillage && blockEntity.capturingFaction != null) {
                blockEntity.breakCapture();
            }
            return;
        }
        if (blockEntity.forcedFaction != null) {
            if (blockEntity.forcedFactionTimer > 0) {
                if (blockEntity.forcedFactionTimer == 1) {
                    blockEntity.breakCapture();
                }
                blockEntity.forcedFactionTimer--;
            } else {
                blockEntity.setCapturingFaction(blockEntity.forcedFaction);
                blockEntity.completeCapture(false, true);
                blockEntity.forcedFaction = null;
            }
        }
        if (blockEntity.forceVillageUpdate) {
            blockEntity.updateTileStatus();
            blockEntity.forceVillageUpdate = false;
        }
        if (time % 12000 == 0) {
            blockEntity.updateVillageArea();
        }

        //Capture
        if (blockEntity.capturingFaction != null) {
            if (time % 20 == 0) {
                assert blockEntity.level == level;
                blockEntity.serverTickSecondCapture((int) (time / 20));
            }
        }
        //Normal village life
        else {
            blockEntity.timeSinceLastRaid++;
            if (time % 20 == 7) {
                blockEntity.serverTickSecondNonCapture((int) (time / 20));
            }

        }
    }

@Override
	public void complete(World world, BlockPos pos, ItemStack input, ItemStackHandler inventoryHandler) {
		ArrayList<ItemStack> stacks = new ArrayList<>();

		for (int i = 0; i < inventoryHandler.getSlots(); i++) {
			if (!inventoryHandler.getStackInSlot(i).isEmpty()) {
				stacks.add(inventoryHandler.getStackInSlot(i));
				inventoryHandler.setStackInSlot(i, ItemStack.EMPTY);
			}
		}

		// Process spellData multipliers based on nacre quality
		double pearlMultiplier = 1;
		if (input.getItem() instanceof INacreProduct) {
			float purity = ((INacreProduct) input.getItem()).getQuality(input);
			if (purity >= 1f) pearlMultiplier = ConfigValues.perfectPearlMultiplier * purity;
			else if (purity <= ConfigValues.damagedPearlMultiplier)
				pearlMultiplier = ConfigValues.damagedPearlMultiplier;
			else {
				double base = purity - 1;
				pearlMultiplier = 1 - (base * base * base * base);
			}
		}

		SpellBuilder builder = new SpellBuilder(stacks, pearlMultiplier);

		NBTTagList list = new NBTTagList();
		for (SpellRing spellRing : builder.getSpell()) {
			list.appendTag(spellRing.serializeNBT());
		}

		SpellUtils.infuseSpell(input, list);

		//markDirty();

		PacketHandler.NETWORK.sendToAllAround(new PacketExplode(new Vec3d(pos).add(0.5, 0.5, 0.5), Color.CYAN, Color.BLUE, 2, 2, 500, 300, 20, true),
				new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

		world.playSound(null, pos, ModSounds.BASS_BOOM, SoundCategory.BLOCKS, 1f, (float) RandUtil.nextDouble(1, 1.5));

		List<Entity> entityList = world.getEntitiesWithinAABBExcludingEntity(null, new AxisAlignedBB(pos).grow(32, 32, 32));
		for (Entity entity1 : entityList) {
			double dist = entity1.getDistance(pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5);
			final double upperMag = 3;
			final double scale = 0.8;
			double mag = upperMag * (scale * dist / (-scale * dist - 1) + 1);
			Vec3d dir = entity1.getPositionVector().subtract(new Vec3d(pos).add(0.5, 0.5, 0.5)).normalize().scale(mag);

			entity1.motionX = (dir.x);
			entity1.motionY = (dir.y);
			entity1.motionZ = (dir.z);
			entity1.fallDistance = 0;
			entity1.velocityChanged = true;

			if (entity1 instanceof EntityPlayerMP)
				((EntityPlayerMP) entity1).connection.sendPacket(new SPacketEntityVelocity(entity1));
		}
	}

@Override
    public void tick() {
        if (getBlockState().getValue(ScribesBlock.PART) != ThreePartBlock.HEAD)
            return;
        if (!level.isClientSide && !synced) {
            updateBlock();
            synced = true;
        }
        if (craftingTicks > 0)
            craftingTicks--;

        if (recipeID != null && recipeID.equals(ResourceLocation.withDefaultNamespace(""))) {
            recipe = null; // Used on client to remove recipe since for some forsaken reason world is missing during load.
        }

        if (recipeID != null && !recipeID.toString().isEmpty() && (recipe == null || !recipe.id().equals(recipeID)) && level.getRecipeManager() != null) {
            recipe = level.getRecipeManager().byKeyTyped(RecipeRegistry.GLYPH_TYPE.get(), recipeID);
            setChanged();
        }
        if (!level.isClientSide && level.getGameTime() % 5 == 0 && recipe != null) {
            boolean foundStack = false;
            List<ItemEntity> nearbyItems = level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(2));
            for (ItemEntity e : nearbyItems) {
                if (canConsumeItemstack(e.getItem())) {
                    ItemStack copyStack = e.getItem().copy();
                    copyStack.setCount(1);
                    consumedStacks.add(copyStack);
                    e.getItem().shrink(1);
                    ParticleUtil.spawnTouchPacket(level, e.getOnPos(), ParticleColor.defaultParticleColor());
                    updateBlock();
                    foundStack = true;
                    break;
                }
            }
            if (!foundStack && level.getGameTime() % 20 == 0 && autoYoink) {
                takeNearby();
            }

            if (getRemainingRequired().isEmpty() && !crafting) {
                crafting = true;
                craftingTicks = 120;
                Networking.sendToNearbyClient(level, getBlockPos(), new PacketOneShotAnimation(getBlockPos(), 0));
                updateBlock();
            }
        }
        if (level.isClientSide && craftingTicks == 0 && crafting) {
            crafting = false;
            setChanged();
        }
        if (!level.isClientSide && crafting && craftingTicks == 0 && recipe != null) {
            level.addFreshEntity(new ItemEntity(level, getX() + 0.5, getY() + 1.1, getZ() + 0.5, recipe.value().output.copy()));
            recipe = null;
            recipeID = ResourceLocation.withDefaultNamespace("");
            crafting = false;
            consumedStacks = new ArrayList<>();
            updateBlock();
        }
    }

@Override
    public @NotNull InteractionResult useOn(UseOnContext context) {
        if (context.getLevel().isClientSide || context.getPlayer() == null)
            return super.useOn(context);
        BlockPos pos = context.getClickedPos();
        Direction face = context.getClickedFace();
        Player playerEntity = context.getPlayer();
        ItemStack stack = context.getItemInHand();
        DominionWandData data = stack.getOrDefault(DataComponentRegistry.DOMINION_WAND, new DominionWandData());
        Level world = data.storedPos().isPresent() ? playerEntity.getServer().getLevel(data.storedPos().get().dimension()) : context.getLevel();

        if (playerEntity.isShiftKeyDown() && world.getBlockEntity(pos) instanceof IWandable wandable && !data.hasStoredData()) {
            var result = wandable.onClearConnections(playerEntity);
            playSoundFromResult(world, pos, result);
            clear(stack, playerEntity);
            world.playSound(null, pos, SoundRegistry.DOMINION_WAND_CLEAR.get(), SoundSource.PLAYERS, 1.0F, 1.0F);
            return InteractionResult.CONSUME;
        }

        if (!data.hasStoredData()) {
            data = data.storePos(new GlobalPos(context.getLevel().dimension(), pos));
            if (data.strict()) data = data.setFace(face);
            stack.set(DataComponentRegistry.DOMINION_WAND, data);
            PortUtil.sendMessage(playerEntity, Component.translatable("ars_nouveau.dominion_wand.position_set"));
            playSoundFromResult(playerEntity.level, pos, IWandable.Result.SELECT);
            return InteractionResult.SUCCESS;
        }

        GlobalPos storedPos = data.storedPos().orElse(null);
        Direction storedDirection = data.face().orElse(null);

        // TODO: Make interface accept Entity
        Entity storedEntity = world.getEntity(data.storedEntityId());
        if (storedPos != null) {
            IWandable wandableStoredBlock = getWandableBlock(context, storedPos.pos(), storedDirection);

            if (wandableStoredBlock != null) {
                var result = wandableStoredBlock.onFirstConnection(new GlobalPos(world.dimension(), pos), storedDirection, storedEntity instanceof LivingEntity livingEntity ? livingEntity : null, playerEntity);
                playSoundFromResult(world, pos, result);
            }
        }

        IWandable wandableAtClickedPos = getWandableBlock(context, pos, face);

        if (wandableAtClickedPos != null) {
            var result = wandableAtClickedPos.onLastConnection(storedPos, storedDirection, storedEntity instanceof LivingEntity livingEntity ? livingEntity : null, playerEntity);
            playSoundFromResult(world, pos, result);
        }


        if (data.storedEntityId() != DominionWandData.NULL_ENTITY && world.getEntity(data.storedEntityId()) instanceof IWandable wandable) {
            var result = wandable.onFirstConnection(new GlobalPos(world.dimension(), pos), data.strict() ? face : null, null, playerEntity);
            playSoundFromResult(world, pos, result);
        }

        clear(stack, playerEntity);
        return super.useOn(context);
    }

@Override
    public void handle(IPayloadContext context) {
        ServerPlayer player = (ServerPlayer) context.player();
        ItemStack stack = player.getItemInHand(currentHand);
        if (!stack.isEmpty() && stack.getItem() instanceof ItemPortableTeleporter) {
            TeleporterFrequency found = FrequencyTypes.TELEPORTER.getFrequency(identity, player.getUUID());
            if (found == null) {
                return;
            }
            GlobalPos coords = found.getClosestCoords(player.level().dimension(), player.blockPosition());
            if (coords != null) {
                ServerLevel teleWorld = player.level().getServer().getLevel(coords.dimension());
                TileEntityTeleporter teleporter = WorldUtils.getTileEntity(TileEntityTeleporter.class, teleWorld, coords.pos());
                if (teleporter != null) {
                    int energyCost;
                    try (Transaction transaction = Transaction.openRoot()) {
                        if (MekanismUtils.isPlayingMode(player)) {
                            energyCost = TileEntityTeleporter.calculateEnergyCost(player, teleWorld, coords);
                            EnergyHandler energyHandler = AutomatedEnergyHandler.manual(Capabilities.ENERGY.getCapability(ItemAccessUtils.playerHandAccess(player, currentHand)));
                            if (energyHandler == null || energyHandler.extract(energyCost, transaction) < energyCost) {
                                //Fail if there is not enough energy available
                                return;
                            }
                        } else {
                            energyCost = 0;
                        }
                        teleporter.didTeleport.add(player.getUUID());
                        teleporter.teleDelay = 5;
                        BlockPos teleporterTargetPos = teleporter.getTeleporterTargetPos();
                        MekanismTeleportEvent.PortableTeleporter event = new MekanismTeleportEvent.PortableTeleporter(player, teleporterTargetPos, teleWorld, stack, energyCost);
                        if (NeoForge.EVENT_BUS.post(event).isCanceled()) {
                            //Fail if the event was cancelled
                            return;
                        }
                        //Commit the energy usage
                        transaction.commit();
                        player.connection.aboveGroundTickCount = 0;
                        player.closeContainer();
                        PacketUtils.sendToAllTracking(new PacketPortalFX(player.blockPosition()), player.level(), coords.pos());
                        if (player.isPassenger()) {
                            player.stopRiding();
                        }
                        double oldX = player.getX();
                        double oldY = player.getY();
                        double oldZ = player.getZ();
                        Level oldWorld = player.level();
                        TileEntityTeleporter.teleportEntityTo(player, teleWorld, teleporter, event, false, TeleportTransition.DO_NOTHING);
                        if (player.level() != oldWorld || player.distanceToSqr(oldX, oldY, oldZ) >= 25) {
                            //If the player teleported over 5 blocks, play the sound at both the destination and the source
                            oldWorld.playSound(null, oldX, oldY, oldZ, SoundEvents.PLAYER_TELEPORT, SoundSource.PLAYERS);
                        }
                        player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_TELEPORT, SoundSource.PLAYERS);
                        teleporter.sendTeleportParticles();
                    }
                }
            }
        }
    }

@TestPlot("inscriber_deferred_side_effects")
    public static void testInscriber(PlotBuilder plot) {
        plot.creativeEnergyCell(BlockPos.ZERO.below());
        plot.block(BlockPos.ZERO, AEBlocks.INSCRIBER);

        plot.test(helper -> {
            helper.startSequence()
                    .thenExecute(() -> {
                        var inscriber = helper.getBlockEntity(BlockPos.ZERO,
                                InscriberBlockEntity.class);
                        var handler = inscriber.getExposedItemHandler(Direction.UP);
                        helper.check(handler != null, "handler should not be null", BlockPos.ZERO);

                        // Set up a valid recipe (press + matching material) so the inscriber starts processing
                        try (var tx = Transaction.open(null)) {
                            var press = AEItems.CALCULATION_PROCESSOR_PRESS.stack();
                            helper.check(handler.insert(ItemResource.of(press), 1, tx) == 1,
                                    "Should insert press", BlockPos.ZERO);

                            var crystal = AEItems.CERTUS_QUARTZ_CRYSTAL.stack();
                            helper.check(handler.insert(ItemResource.of(crystal), 1, tx) == 1,
                                    "Should insert crystal", BlockPos.ZERO);

                            tx.commit();
                        }
                    })
                    // Wait until the inscriber has actually started processing the recipe
                    .thenWaitUntil(() -> {
                        var inscriber = helper.getBlockEntity(BlockPos.ZERO,
                                InscriberBlockEntity.class);
                        helper.check(inscriber.getProcessingTime() > 0,
                                "Processing time should have advanced", BlockPos.ZERO);
                    })
                    .thenExecute(() -> {
                        var inscriber = helper.getBlockEntity(BlockPos.ZERO,
                                InscriberBlockEntity.class);
                        var handler = inscriber.getExposedItemHandler(Direction.UP);
                        var processingTimeBeforeChange = inscriber.getProcessingTime();

                        try (var tx = Transaction.open(null)) {
                            // Filling the (still empty) bottom plate slot changes the recipe inputs
                            var namePress = AEItems.NAME_PRESS.stack();
                            helper.check(handler.insert(ItemResource.of(namePress), 1, tx) == 1,
                                    "Should insert name press", BlockPos.ZERO);

                            // Processing time should not be reset yet
                            helper.check(inscriber.getProcessingTime() == processingTimeBeforeChange,
                                    "No side-effects during transaction", BlockPos.ZERO);

                            tx.commit();
                        }

                        // After commit, the processing time should have been reset
                        helper.check(inscriber.getProcessingTime() == 0,
                                "Processing time reset after commit", BlockPos.ZERO);
                    })
                    .thenSucceed();
        });
    }

public static void getCoresampleInfo(
			ItemData data, List<Component> list, ChatFormatting baseColor, @Nullable Level level, boolean showYield, boolean showTimestamp
	)
	{
		if(level==null)
			return;
		if(!data.veins.isEmpty())
			data.veins.forEach(veinData -> {
				MutableComponent component = Component.literal(
						Utils.formatDouble(veinData.percentageInTotalSample*100, "0.00")+"% "
				);
				component.append(Component.translatable(MineralMix.getTranslationKey(veinData.mineral)));
				list.add(component.withStyle(baseColor));
				if(showYield)
				{
					component = Component.literal("  ");
					component.append(Component.translatable(Lib.DESC_INFO+"coresample.saturation",
							Utils.formatDouble(veinData.saturation*100, "0.00")
					));
					list.add(component.withStyle(ChatFormatting.DARK_GRAY));

					component = Component.literal("  ");
					// Used to be called "yield", but apparently IntelliJ gets confused over whether we're in a
					// switch-case or nor
					int yield_ = ExcavatorHandler.mineralVeinYield-veinData.depletion;
					MineralMix mineral = MineralMix.RECIPES.getById(level, veinData.mineral);
					yield_ *= (1-mineral.failChance);
					if(ExcavatorHandler.mineralVeinYield==0)
						component.append(Component.translatable(Lib.DESC_INFO+"coresample.infinite"));
					else
						component.append(Component.translatable(Lib.DESC_INFO+"coresample.yield",
								yield_));
					list.add(component.withStyle(ChatFormatting.DARK_GRAY));
				}
			});
		else
			list.add(Component.translatable(Lib.DESC_INFO+"coresample.noMineral").withStyle(baseColor));

		ResourceKey<Level> dimension = data.position.dimension;
		if(dimension!=null)
		{
			String s2 = dimension.location().getPath();
			if(s2.toLowerCase(Locale.ENGLISH).startsWith("the_"))
				s2 = s2.substring(4);
			list.add(Component.literal(Utils.toCamelCase(s2)).withStyle(baseColor));
		}
		ColumnPos pos = data.position.position();
		if(pos!=null)
			list.add(Component.translatable(Lib.DESC_INFO+"coresample.pos", pos.x(), pos.z()).withStyle(baseColor));

		if(showTimestamp)
		{
			long dist = level.getGameTime()-data.timestamp;
			if(dist < 0)
				list.add(Component.literal("Somehow this sample is dated in the future...are you a time traveller?!").withStyle(ChatFormatting.RED));
			else
				list.add(Component.translatable(Lib.DESC_INFO+"coresample.timestamp", TimestampFormat.formatTimestamp(dist, TimestampFormat.DHM)).withStyle(baseColor));
		}
	}

private void refreshList() {
        IGrid grid = this.getMainNode().getGrid();
        if (grid == null) {
            aeItemHandler.clearInventory(0);
            return;
        }

        MEStorage networkStorage = grid.getStorageService().getInventory();
        var counter = networkStorage.getAvailableStacks();

        // Use a PriorityQueue to sort the stacks on size, take the first CONFIG_SIZE
        // biggest stacks.
        PriorityQueue<Object2LongMap.Entry<AEKey>> topItems = new PriorityQueue<>(
                Comparator.comparingLong(Object2LongMap.Entry<AEKey>::getLongValue));

        for (Object2LongMap.Entry<AEKey> entry : counter) {
            long amount = entry.getLongValue();
            AEKey what = entry.getKey();

            if (amount <= 0) continue;
            if (!(what instanceof AEItemKey itemKey)) continue;

            long request = networkStorage.extract(what, amount, Actionable.SIMULATE, actionSource);
            if (request == 0) continue;

            // Ensure that it is valid to configure with this stack
            if (autoPullTest != null && !autoPullTest.test(new GenericStack(itemKey, amount))) continue;
            if (amount >= minStackSize) {
                if (topItems.size() < CONFIG_SIZE) {
                    topItems.offer(entry);
                } else if (amount > topItems.peek().getLongValue()) {
                    topItems.poll();
                    topItems.offer(entry);
                }
            }
        }

        // Now, topItems is a PQ with CONFIG_SIZE highest amount items in the system.
        int index;
        int itemAmount = topItems.size();
        for (index = 0; index < CONFIG_SIZE; index++) {
            if (topItems.isEmpty()) break;
            Object2LongMap.Entry<AEKey> entry = topItems.poll();

            AEKey what = entry.getKey();
            long amount = entry.getLongValue();

            // If we get here, the item has already been checked by the PQ.
            long request = networkStorage.extract(what, amount, Actionable.SIMULATE, actionSource);

            // Since we want our items to be displayed from highest to lowest, but poll() returns
            // the lowest first, we fill in the slots starting at itemAmount-1
            var slot = this.aeItemHandler.getInventory()[itemAmount - index - 1];
            slot.setConfig(new GenericStack(what, 1));
            slot.setStock(new GenericStack(what, request));
        }

        aeItemHandler.clearInventory(index);
    }

public void emitParticle(float dt) {
        updateLightRegistration();
        // calculate distance (scaled by this step's dt)
        accumulatedDistance += getVelocity().length() * dt;
        // emit new particle (maxParticles may be timeline-overridden; authored value is the fallback)
        var maxParticles = runtime().maxParticles.get();
        var particleAmount = getParticleAmount(); // streams all queues — compute once per call
        if (!removed && particleAmount < maxParticles) {
            var emissionCount = runtime().emission.getEmissionCount(this, getRandomSource(), dt);
            var available = Math.min(emissionCount, maxParticles - particleAmount);
            particleBatchCount = Math.max(1, available);
            particleBatchCursor = 0;
            for (int i = 0; i < available; i++) {
                emitParticle(createNewParticle());
            }
        }

        // particles life cycle
        if (!waitToAdded.isEmpty()) {
            for (var p : waitToAdded) {
                // modest initial capacity: maxParticles is timeline-drivable and may be huge
                particles.computeIfAbsent(p.getRenderType(), type -> new ArrayDeque<>(Math.min(maxParticles, 256))).add(p);
            }
            waitToAdded.clear();
        }

        var parallelAllowed = useParallelUpdate();
        for (var queue : particles.values()) {
            if (parallelAllowed && queue.size() >= PARALLEL_UPDATE_MIN_PARTICLES) { // parallel stream for particles tick.
                queue.removeIf(p -> !p.isAlive());
                setParallelLightPhase(true);
                try {
                    queue.parallelStream().forEach(p -> p.updateTick(dt));
                } finally {
                    setParallelLightPhase(false);
                }
            } else {
                var iter = queue.iterator();
                while (iter.hasNext()) {
                    var particle = iter.next();
                    if (!particle.isAlive()) {
                        iter.remove();
                    } else {
                        particle.updateTick(dt);
                    }
                }
            }
        }
        if (parallelAllowed) {
            // refresh every light position requested this tick on the game thread
            // (parallel reads only consult the cache; misses used the last value)
            rebuildLightCache();
        }

        // drain sub-emitter spawns collected during (possibly parallel) particle updates
        for (Runnable spawn; (spawn = pendingSubEmitterSpawns.poll()) != null; ) {
            spawn.run();
        }
    }

public static void render(PetalApothecaryBlockEntity altar, GuiGraphics gui, Minecraft mc) {
			int xc = mc.getWindow().getGuiScaledWidth() / 2;
			int yc = mc.getWindow().getGuiScaledHeight() / 2;

			float angle = -90;
			int radius = 24;
			int amt = 0;
			for (int i = 0; i < altar.inventorySize(); i++) {
				if (altar.getItemHandler().getItem(i).isEmpty()) {
					break;
				}
				amt++;
			}

			if (amt > 0) {
				float anglePer = 360F / amt;

				Optional<PetalApothecaryRecipe> maybeRecipe = altar.level.getRecipeManager()
						.getRecipeFor(BotaniaRecipeTypes.PETAL_TYPE, altar.getItemHandler(), altar.level);
				maybeRecipe.ifPresent(recipe -> {
					RenderSystem.setShaderColor(1F, 1F, 1F, 1F);
					RenderHelper.drawTexturedModalRect(gui, HUDHandler.manaBar, xc + radius + 9, yc - 8, 0, 8, 22, 15);

					ItemStack stack = recipe.assemble(altar.getItemHandler(), altar.getLevel().registryAccess());
					gui.renderFakeItem(stack, xc + radius + 32, yc - 8);

					var reagents = recipe.getReagent().getItems();
					ItemStack reagent;
					if (reagents.length == 0) {
						reagent = new ItemStack(Items.BARRIER);
					} else {
						int idx = (int) ((altar.level.getGameTime() / 20) % reagents.length);
						reagent = reagents[idx];
					}
					gui.renderFakeItem(reagent, xc + radius + 16, yc + 6);
					gui.drawString(mc.font, "+", xc + radius + 14, yc + 10, 0xFFFFFF, false);
				});

				for (int i = 0; i < amt; i++) {
					double xPos = xc + Math.cos(angle * Math.PI / 180D) * radius - 8;
					double yPos = yc + Math.sin(angle * Math.PI / 180D) * radius - 8;
					PoseStack pose = RenderSystem.getModelViewStack();
					pose.pushPose();
					pose.translate(xPos, yPos, 0);
					RenderSystem.applyModelViewMatrix();
					gui.renderFakeItem(altar.getItemHandler().getItem(i), 0, 0);
					pose.popPose();
					RenderSystem.applyModelViewMatrix();

					angle += anglePer;
				}
			}
			if (altar.recipeKeepTicks > 0 && altar.canAddLastRecipe()) {
				String s = I18n.get("botaniamisc.altarRefill0");
				gui.drawString(mc.font, s, xc - mc.font.width(s) / 2, yc + 10, 0xFFFFFF, false);
				s = I18n.get("botaniamisc.altarRefill1");
				gui.drawString(mc.font, s, xc - mc.font.width(s) / 2, yc + 20, 0xFFFFFF, false);
			}
		}

