@Override
    protected InteractionResult useOnServerSide(UseOnContext context) {
        if (context.getLevel().getBlockState(context.getClickedPos()).is(OccultismTags.Blocks.CHALK_GLYPHS)) {
            if (this.tryErase(context)) {
                return InteractionResult.SUCCESS;
            } else {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_NO_VALID_BRUSH_IN_SATCHEL).withStyle(ChatFormatting.YELLOW));
                return InteractionResult.FAIL;
            }
        }

        var targetPentacle = this.targetPentacles().get(context.getPlayer().getUUID());
        if (targetPentacle == null || targetPentacle.timeWhenAdded() < context.getLevel().getGameTime() - 5) {
            //no or outdated info
            return InteractionResult.FAIL;
        }

        if (!targetPentacle.target().equals(context.getClickedPos())) {
            //silent fail -> the player clicked at two blocks in quick succession, the second block did not send anything to the server as it is not a chalk block, so we ignore. Client side already sent an error message for that second click!
            return InteractionResult.FAIL;
        }

        var multiblock = ModonomiconAPI.get().getMultiblock(targetPentacle.multiblock());
        var simulation = multiblock.simulate(context.getLevel(), targetPentacle.anchor(), targetPentacle.facing(), false, false);

        var targetMatcher = simulation.getSecond().stream().filter(p -> p.worldPosition().equals(context.getClickedPos())).findFirst();
        if (targetMatcher.isEmpty()) {
            //should not happen, player clicked a non-preview block
            return InteractionResult.FAIL;
        }

        return switch (this.tryPlaceBlockForMatcher(context, targetMatcher.get())) {
            case SUCCESS -> InteractionResult.SUCCESS;
            case ERROR_NO_MATCHING_BLOCK_FOUND -> {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_NO_VALID_ITEM_IN_SATCHEL).withStyle(ChatFormatting.YELLOW));
                yield InteractionResult.FAIL;
            }
            case ERROR_BLOCK_ABOVE_NOT_AIR -> {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_BLOCK_ABOVE_NOT_AIR).withStyle(ChatFormatting.YELLOW));
                yield InteractionResult.FAIL;
            }
            case ERROR_BLOCK_AT_POSITION_NOT_AIR -> {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_BLOCK_AT_POSITION_NOT_AIR).withStyle(ChatFormatting.YELLOW));
                yield InteractionResult.FAIL;
            }
            case ERROR_INVALID_MATCHER -> {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_INVALID_MATCHER).withStyle(ChatFormatting.YELLOW));
                yield InteractionResult.FAIL;
            }
            case ERROR_GLYPH_CANNOT_SURVIVE -> {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_GLYPH_CANNOT_SURVIVE).withStyle(ChatFormatting.YELLOW));
                yield InteractionResult.FAIL;
            }
            case ERROR_WILL_BREAK_ITEM -> {
                context.getPlayer().sendSystemMessage(Component.translatable(TranslationKeys.RITUAL_SATCHEL_WILL_BREAK_ITEM).withStyle(ChatFormatting.YELLOW));
                yield InteractionResult.FAIL;
            }
            default -> InteractionResult.FAIL;
        };
    }

@Override
    public void extractRenderState(TileEntityNutritionalLiquifier liquifier, LiquifierRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        super.extractRenderState(liquifier, state, partialTick, cameraPosition, breakProgress);
        if (!liquifier.fluidTank.isEmpty()) {
            FluidResource paste = liquifier.fluidTank.resource();
            float fluidScale = liquifier.fluidTank.amountAsLong() / (float) liquifier.fluidTank.capacityAsLong(paste);
            state.pasteTint = MekanismRenderer.getColorARGB(paste, fluidScale);
            state.stage = ModelRenderer.getStage(paste, stages, fluidScale);
            state.pasteTexture = MekanismRenderer.getSinglePicker(MekanismRenderer.getFluidTexture(paste, FluidTextureType.STILL));
            state.pasteGlow = LightCoordsUtil.lightCoordsWithEmission(state.lightCoords, paste.getFluidType().getLightLevel());
        } else {
            state.stage = 0;
        }
        state.active = liquifier.getActive();
        if (state.active) {
            float animationTime = getAnimationTime(liquifier, partialTick);
            state.bladeRotation = (animationTime * BLADE_SPEED) % 360;
            state.itemRotation = (animationTime * ROTATE_SPEED) % 360;
        }
        ItemStack stack = liquifier.getRenderStack();
        if (!stack.isEmpty()) {
            Level level = liquifier.getLevel();
            //Copy from how the campfire renderer calculates the seed
            int seed = (int) state.blockPos.asLong();
            this.itemModelResolver.updateForTopItem(state.item, stack, ItemDisplayContext.GROUND, level, null, seed);

            if (state.active && Minecraft.getInstance().options.particles().get() != ParticleStatus.MINIMAL) {
                //Render eating particles
                PseudoParticleData pseudoParticles = particles.computeIfAbsent(liquifier, _ -> new PseudoParticleData());
                if (isTickingNormally(liquifier)) {
                    //Don't add particles if the game is paused
                    long gameTime = liquifier.getGameTime();
                    if (pseudoParticles.lastTick != gameTime) {
                        pseudoParticles.lastTick = gameTime;
                        for (Iterator<BreakingItemParticle> iterator = pseudoParticles.particles.iterator(); iterator.hasNext(); ) {
                            BreakingItemParticle particle = iterator.next();
                            particle.tick();
                            if (!particle.isAlive()) {
                                iterator.remove();
                            }
                        }
                    }
                    int rate = Minecraft.getInstance().options.particles().get() == ParticleStatus.DECREASED ? 10 : 3;
                    if (gameTime % rate == 0) {
                        RandomSource random = level.getRandom();
                        Material.Baked itemSprite = state.item.pickParticleMaterial(random);
                        pseudoParticles.particles.add(new EatingParticle((ClientLevel) level, state.blockPos, itemSprite, state.lightCoords));
                    }
                }
                Camera camera = Minecraft.getInstance().gameRenderer.mainCamera();
                for (BreakingItemParticle particle : pseudoParticles.particles) {
                    particle.extract(state.particles, camera, partialTick);
                }
                state.partialTick = partialTick;
            } else {
                particles.remove(liquifier);
            }
        }
    }

@SubscribeEvent
	public void onItemTooltip(ItemTooltipEvent event)
	{
		if(event.getItemStack().isEmpty())
			return;
		var wrapper = event.getItemStack().getCapability(CapabilityShader.ITEM);
		if(wrapper!=null)
		{
			var shader = wrapper.getShader();
			if(shader!=null)
				event.getToolTip().add(TextUtils.applyFormat(
						ShaderItem.getShaderName(shader),
						ChatFormatting.DARK_GRAY
				));
		}
		if(event.getItemStack().has(IEDataComponents.CONTAINED_EARMUFF))
		{
			ItemStack earmuffs = event.getItemStack().get(IEDataComponents.CONTAINED_EARMUFF).attached();
			if(!earmuffs.isEmpty())
				event.getToolTip().add(TextUtils.applyFormat(
						earmuffs.getHoverName(),
						ChatFormatting.GRAY
				));
		}
		if(event.getItemStack().has(IEDataComponents.CONTAINED_POWERPACK))
		{
			ItemStack powerpack = event.getItemStack().get(IEDataComponents.CONTAINED_POWERPACK).attached();
			IEnergyStorage packStorage = powerpack.getCapability(EnergyStorage.ITEM);
			if(!powerpack.isEmpty()&&packStorage!=null)
			{
				List<Component> tooltip = event.getToolTip();
				// find gap
				int idx = IntStream.range(0, tooltip.size()).filter(i -> tooltip.get(i)==CommonComponents.EMPTY).findFirst().orElse(tooltip.size()-1);
				// put tooltip in that gap
				tooltip.add(idx++, CommonComponents.EMPTY);
				tooltip.add(idx++, TextUtils.applyFormat(powerpack.getHoverName(), ChatFormatting.GRAY));
				tooltip.add(idx++, TextUtils.applyFormat(
						Component.literal(packStorage.getEnergyStored()+"/"+packStorage.getMaxEnergyStored()+" IF"),
						ChatFormatting.GRAY
				));
				tooltip.add(idx, TextUtils.applyFormat(Component.translatable("desc.immersiveengineering.info.noChargeOnArmor"), ChatFormatting.DARK_GRAY));
			}
		}
		Level clientLevel = ClientUtils.mc().level;
		if(ClientUtils.mc().screen!=null
				&&ClientUtils.mc().screen instanceof BlastFurnaceScreen
				&&BlastFurnaceFuel.isValidBlastFuel(clientLevel, event.getItemStack()))
			event.getToolTip().add(TextUtils.applyFormat(
					Component.translatable("desc.immersiveengineering.info.blastFuelTime", BlastFurnaceFuel.getBlastFuelTime(clientLevel, event.getItemStack())),
					ChatFormatting.GRAY
			));

		if(IEClientConfig.tagTooltips.get()&&event.getFlags().isAdvanced())
			event.getItemStack().getItem().builtInRegistryHolder().tags()
					.map(TagKey::location)
					.forEach(oid ->
							event.getToolTip().add(TextUtils.applyFormat(
									Component.literal(oid.toString()),
									ChatFormatting.GRAY
							)));
	}

@Override
	public void tickServer()
	{
		if(isDummy())
			return;
		if(tank.getFluidAmount() > 0)
		{
			int i = outputFluid(tank.getFluid(), FluidAction.EXECUTE);
			tank.drain(i, FluidAction.EXECUTE);
		}

		int consumption = IEServerConfig.MACHINES.pump_consumption.get();
		if(canRun())
		{
			for(Direction f : Direction.values())
				if(sideConfig.get(f)==IOSideConfig.INPUT)
				{
					IFluidHandler input = blockFluidHandlers.get(f).getCapability();
					// attempt to find an adjacent entity fluid handler
					if(input==null)
						input = getEntityFluidHandler(f);
					if(input!=null)
					{
						int drainAmount = IFluidPipe.getTransferableAmount(this.canOutputPressurized(false));
						FluidStack drain = input.drain(drainAmount, FluidAction.SIMULATE);
						if(drain.isEmpty())
							continue;
						int out = this.outputFluid(drain, FluidAction.EXECUTE);
						input.drain(out, FluidAction.EXECUTE);
					}
					else
						gatherInfiniteFluidFromWorld(f);
				}
			if(level.getGameTime()%40==(((getBlockPos().getX()^getBlockPos().getZ()))%40+40)%40)
			{
				if(closedList.isEmpty())
					prepareAreaCheck();
				else
				{
					int target = closedList.size()-1;
					BlockPos pos = closedList.get(target);
					FluidStack fs = Utils.drainFluidBlock(level, pos, FluidAction.SIMULATE);
					if(fs==null)
						closedList.remove(target);
					else if(tank.fill(fs, FluidAction.SIMULATE)==fs.getAmount()
							&&this.energyStorage.extractEnergy(consumption, true) >= consumption)
					{
						this.energyStorage.extractEnergy(consumption, false);
						fs = Utils.drainFluidBlock(level, pos, FluidAction.EXECUTE);
						if(IEServerConfig.MACHINES.pump_placeCobble.get()&&placeCobble)
							level.setBlockAndUpdate(pos, Blocks.COBBLESTONE.defaultBlockState());
						this.tank.fill(fs, FluidAction.EXECUTE);
						closedList.remove(target);
					}
				}
			}
		}

		if(checkingArea)
			checkAreaTick();
	}

public boolean addProcessToQueue(
			MultiblockProcess<R, CTX> process, Level level, boolean simulate, boolean addToPrevious
	)
	{
		if(addToPrevious&&process instanceof MultiblockProcessInWorld)
		{
			// Pattern variables look fine in IntelliJ, but cause the "real" compiler to complain. Probably related to
			// the CTX type parameter
			@SuppressWarnings("PatternVariableCanBeUsed") final MultiblockProcessInWorld<R> newProcess = (MultiblockProcessInWorld<R>)process;
			for(MultiblockProcess<R, CTX> curr : processQueue)
				if(curr instanceof MultiblockProcessInWorld&&process.getRecipeId().equals(curr.getRecipeId()))
				{
					boolean canStack = true;
					final MultiblockProcessInWorld<R> existingProcess = (MultiblockProcessInWorld<R>)curr;
					for(ItemStack old : existingProcess.inputItems)
					{
						for(ItemStack in : newProcess.inputItems)
							if(ItemStack.isSameItemSameComponents(old, in))
								if(old.getCount()+in.getCount() > old.getMaxStackSize())
								{
									canStack = false;
									break;
								}
						if(!canStack)
							break;
					}
					if(canStack)
					{
						if(!simulate)
							for(ItemStack old : existingProcess.inputItems)
							{
								for(ItemStack in : newProcess.inputItems)
									if(ItemStack.isSameItemSameComponents(old, in))
									{
										old.grow(in.getCount());
										break;
									}
							}
						return true;
					}
				}
		}
		if(maxQueueLength < 0||processQueue.size() < maxQueueLength)
		{
			if(!processQueue.isEmpty())
			{
				MultiblockProcess<R, CTX> previousProcess = processQueue.get(processQueue.size()-1);
				final int maxTime = previousProcess.getMaxTicks(level);
				float dist = previousProcess.processTick/(float)maxTime;
				if(dist < minDelayAfter.applyAsDouble(maxTime))
					return false;
			}

			if(!simulate)
				processQueue.add(process);
			markDirty.run();
			onQueueChange.run();
			return true;
		}
		return false;
	}

public void handle(IPayloadContext ctx) {
        ctx.enqueueWork(() -> {
            var player = ctx.player();

            if (player.containerMenu.containerId != this.getContainer()) {
                this.causeError(player);

                return;
            }

            var stack = DescriptionUtils.gatherRelicStack(player, this.getSlot());

            if (!(stack.getItem() instanceof IRelicItem relic)) {
                this.causeError(player);

                return;
            }

            var abilitiesData = relic.getRelicData(player, stack).getAbilitiesData();
            AbilityTargetingTemplate targeting = null;

            if (this.isSynergy()) {
                var template = abilitiesData.getSynergyData(this.getTarget()).getTemplate();

                targeting = template == null ? null : template.getTargeting();
            } else {
                var template = abilitiesData.getAbilityData(this.getTarget()).getTemplate();

                targeting = template == null ? null : template.getTargeting();
            }

            if (targeting == null || !targeting.isActive()) {
                this.causeError(player);

                return;
            }

            AbilityTargetingOption option;
            SelectorType selectorType;

            try {
                selectorType = SelectorType.valueOf(this.getSelector().toUpperCase(Locale.ROOT));
                option = AbilityTargetingOption.valueOf(this.getOption().toUpperCase(Locale.ROOT));
            } catch (IllegalArgumentException exception) {
                this.causeError(player);

                return;
            }

            if (!targeting.hasOption(selectorType, option)) {
                this.causeError(player);

                return;
            }

            if (this.isSynergy())
                abilitiesData.getSynergyData(this.getTarget()).getTargetingData().setOption(option, selectorType, this.isValue());
            else
                abilitiesData.getAbilityData(this.getTarget()).getTargetingData().setOption(option, selectorType, this.isValue());
        });
    }

public void tick(){
        if (this.level != null) {
            if (this.active > 0) {
                --this.active;
            }
            if (this.getBlockState().getValue(ResonanceCrystalBlock.POWERED)) {
                if (!this.isOn){
                    this.level.playSound(null, this.getBlockPos(), ModSounds.RESONANCE_CRYSTAL_ON.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                    this.isOn = true;
                } else {
                    if (this.level.getGameTime() % MathHelper.secondsToTicks(6) == 0){
                        this.level.playSound(null, this.getBlockPos(), ModSounds.RESONANCE_CRYSTAL_LOOP.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                    }
                }
                if (this.level instanceof ServerLevel world) {
                    this.chunkLoadBlock();
                    BlockPos blockPos = this.getBlockPos();
                    ServerParticleUtil.gatheringBlockParticles(ModParticleTypes.RESONANCE_GATHER.get(), blockPos, world);
                    ServerParticleUtil.windParticle(world, ColorUtil.WHITE, 1.0F + world.random.nextFloat() * 0.5F, 0.0F, -1, Vec3.atBottomCenterOf(blockPos));

                    if (!this.uuids.isEmpty()) {
                        this.uuids.removeIf(uuid -> {
                            Entity entity = EntityFinder.getEntityByUuiD(uuid);
                            if (!(entity instanceof SquallGolem squallGolem)){
                                return true;
                            } else if (!squallGolem.isAlive()) {
                                this.squallGolems.remove(squallGolem);
                                return true;
                            }
                            return false;
                        });
                        for (UUID uuid : this.uuids) {
                            if (uuid != null) {
                                Entity entity = EntityFinder.getEntityByUuiD(uuid);
                                if (entity instanceof SquallGolem squallGolem) {
                                    if (!this.squallGolems.contains(squallGolem)) {
                                        this.squallGolems.add(squallGolem);
                                    }
                                }
                            }
                        }
                    }
                    this.activateGolems();
                }
                if (!this.getBlockPosList().isEmpty()){
                    for (BlockPos blockPos1 : this.getBlockPosList()){
                        BlockEntity blockEntity = this.level.getBlockEntity(blockPos1);
                        if (blockEntity instanceof ResonanceCrystalBlockEntity crystalBlock){
                            crystalBlock.activate(20);
                        }
                    }
                }
            } else {
                if (this.isOn){
                    this.level.playSound(null, this.getBlockPos(), ModSounds.RESONANCE_CRYSTAL_OFF.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                    this.isOn = false;
                }
            }
            this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(ResonanceCrystalBlock.POWERED, this.active > 0), 3);
        }
    }

@Override
    public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
        boolean stable = isStable();
        this.bounds.update(delta);
        FloatingRectangle target = this.bounds.target();
        FloatingRectangle bounds = this.bounds.value();

        if (!reachedStable && Math.abs(bounds.x - target.x) <= 0.5 && Math.abs(bounds.y - target.y) <= 0.5 && Math.abs(bounds.width - target.width) <= 0.5 && Math.abs(bounds.height - target.height) <= 0.5) {
            reachedStable = true;
        }

        if (stable && (bounds.getMaxX() + xOffset < parent.getBounds().x || bounds.x + xOffset > parent.getBounds().getMaxX())) {
            return;
        }

        graphics.pose().pushMatrix();
        graphics.pose().translate(xOffset(), yOffset());
        graphics.pose().scale(xScale(), yScale());

        for (Widget widget : widgets.get()) {
            widget.render(graphics, transformMouseX(mouseX), transformMouseY(mouseY), delta);
        }
        graphics.pose().popMatrix();

        {
            graphics.pose().pushMatrix();
            if (stable && target.equals(bounds)) {
                graphics.pose().translate((float) this.xOffset, 0);
            }
            Vector3f mouse = new Vector3f((float) mouseX, (float) mouseY, 1);
            graphics.pose().transform(mouse);

            AutoCraftingEvaluator.AutoCraftingResult result = this.autoCraftingResult.get();

            plusButton.setEnabled(result.successful);
            plusButton.setTint(result.tint);
            plusButton.getBounds().setBounds(new Rectangle(bounds.getMaxX() - 14, bounds.getMaxY() - 14, 10, 10));

            if (result.hasApplicable) {
                plusButton.setText(Component.literal("+"));
                plusButton.render(graphics, Math.round(mouse.x()), Math.round(mouse.y()), delta);
                graphics.pose().popMatrix();

                if (plusButton.containsMouse(Math.round(mouse.x()), Math.round(mouse.y()))) {
                    result.tooltipRenderer.accept(new Point(mouseX, mouseY), Tooltip::queue);
                }

                if (result.renderer != null) {
                    graphics.pose().pushMatrix();
                    graphics.pose().translate(xOffset(), yOffset());
                    graphics.pose().scale(xScale(), yScale());

                    Rectangle transformedBounds = MatrixUtils.transform(MatrixUtils.inverse(graphics.pose()), getBounds());
                    result.renderer.render(graphics, mouseX, mouseY, delta, widgets.get(), transformedBounds, display);
                    graphics.pose().popMatrix();
                }
            } else {
                graphics.pose().popMatrix();
            }
        }
    }

@Nullable
	private Path findPath(PathPoint pathFrom, PathPoint pathTo, float maxDistance) {
		pathFrom.totalPathDistance = 0.0F;
		pathFrom.distanceToNext = pathFrom.distanceManhattan(pathTo);
		pathFrom.distanceToTarget = pathFrom.distanceToNext;
		this.path.clearPath();
		this.closedSet.clear();
		this.path.addPoint(pathFrom);
		PathPoint pathpoint = pathFrom;
		int i = 0;

		while (!this.path.isPathEmpty()) {
			++i;

			if (i >= 1000) { // TODO: Increased this slightly because flying mobs have more tiles available that need to be checked. Maybe need to check performance
				break;
			}

			PathPoint pathpoint1 = this.path.dequeue();

			if (pathpoint1.equals(pathTo)) {
				pathpoint = pathTo;
				break;
			}

			if (pathpoint1.distanceManhattan(pathTo) < pathpoint.distanceManhattan(pathTo)) {
				pathpoint = pathpoint1;
			}

			pathpoint1.visited = true;
			int j = this.nodeProcessor.findPathOptions(this.pathOptions, pathpoint1, pathTo, maxDistance);

			for (int k = 0; k < j; ++k) {
				PathPoint pathpoint2 = this.pathOptions[k];
				float f = pathpoint1.distanceManhattan(pathpoint2);
				pathpoint2.distanceFromOrigin = pathpoint1.distanceFromOrigin + f;
				pathpoint2.cost = f + pathpoint2.costMalus;
				float f1 = pathpoint1.totalPathDistance + pathpoint2.cost;

				if (pathpoint2.distanceFromOrigin < maxDistance
						&& (!pathpoint2.isAssigned() || f1 < pathpoint2.totalPathDistance)) {
					pathpoint2.previous = pathpoint1;
					pathpoint2.totalPathDistance = f1;
					pathpoint2.distanceToNext = pathpoint2.distanceManhattan(pathTo) + pathpoint2.costMalus;

					if (pathpoint2.isAssigned()) {
						this.path.changeDistance(pathpoint2, pathpoint2.totalPathDistance + pathpoint2.distanceToNext);
					} else {
						pathpoint2.distanceToTarget = pathpoint2.totalPathDistance + pathpoint2.distanceToNext;
						this.path.addPoint(pathpoint2);
					}
				}
			}
		}

		if (pathpoint == pathFrom) {
			return null;
		} else {
			Path path = this.createPath(pathFrom, pathpoint);
			return path;
		}
	}

@Override
	public void tickClient(IMultiblockContext<State> ctx)
	{
		final IMultiblockLevel level = ctx.getLevel();
		final State state = ctx.getState();
		//Handle sound
		final boolean shouldPlay = state.active.hasSound()||state.lastSoundState.hasSound();
		if(shouldPlay&&!state.soundPlaying.get(state.active).getAsBoolean())
		{
			final Vec3 soundPos = level.toAbsolute(new Vec3(2.5, 1, 1.5));
			final ActiveState active = state.active;
			Holder<SoundEvent> sound = switch(active)
			{
				case NOT_RUNNING -> IESounds.saw_shutdown;
				case RUNNING_NO_BLADE -> null;
				case IDLE_WITH_BLADE -> IESounds.saw_empty;
				case SAWING -> IESounds.saw_full;
			};
			if(sound!=null)
				state.soundPlaying.put(state.active, MultiblockSound.startSound(
						() -> state.active==active, ctx.isValid(), soundPos, sound, state.active!=ActiveState.NOT_RUNNING, 0.4f
				));
		}
		state.lastSoundState = state.active;
		if(state.active==ActiveState.NOT_RUNNING)
			return;
		state.animation_bladeRotation += 36f;
		state.animation_bladeRotation %= 360f;
		state.sawmillProcessQueue.forEach(SawmillProcess::incrementProcessOnClient);

		final Level rawLevel = level.getRawLevel();
		Optional<SawmillProcess> process = state.sawmillProcessQueue.stream()
				.filter(p -> p.isSawing(rawLevel))
				.findFirst();
		//Handle empty sound
		//Handle particles & full sound
		if(process.isPresent())
		{
			Direction particleDir = level.toAbsolute(RelativeBlockFace.RIGHT);
			AABB aabb = level.toAbsolute(SAWBLADE_AABB);
			double posX = aabb.minX+rawLevel.random.nextDouble()*(aabb.maxX-aabb.minX);
			double posY = aabb.minY+rawLevel.random.nextDouble()*(aabb.maxY-aabb.minY);
			double posZ = aabb.minZ+rawLevel.random.nextDouble()*(aabb.maxZ-aabb.minZ);
			double vX = rawLevel.random.nextDouble()*particleDir.getStepX()*0.3;
			double vY = rawLevel.random.nextDouble()*0.3;
			double vZ = rawLevel.random.nextDouble()*particleDir.getStepZ()*0.3;
			rawLevel.addAlwaysVisibleParticle(
					new ItemParticleOption(ParticleTypes.ITEM, process.get().getCurrentStack(rawLevel, true)),
					posX, posY, posZ, vX, vY, vZ
			);
			//Arbitrary constant is arbitrary, but it's what sounded good in game, so we keep it. Actual length is supposed to be 10t...
			state.count++;
			if(state.count%21==0)
				rawLevel.playSound(
						ImmersiveEngineering.proxy.getClientPlayer(),
						level.toAbsolute(new BlockPos(2, 1, 1)),
						IESounds.saw_full.value(),
						SoundSource.BLOCKS, .4F, 1);
		}
		else if(state.count!=-1)
			state.count = -1;
	}

public void activateDeferred() {
		if (cannotLaunch())
			return;
		Direction facing = getFacing();
		List<Entity> entities =
			level.getEntitiesOfClass(Entity.class, new AABB(worldPosition).inflate(-1 / 16f, 0, -1 / 16f));

		// Launch Items
		boolean doLogic = !level.isClientSide || isVirtual();
		if (doLogic)
			launchItems();

		// Launch Entities
		for (Entity entity : entities) {
			boolean isPlayerEntity = entity instanceof Player;
			if (!entity.isAlive())
				continue;
			if (entity instanceof ItemEntity)
				continue;
			if (entity instanceof PackageEntity)
				continue;
			if (entity.getPistonPushReaction() == PushReaction.IGNORE)
				continue;

			entity.setOnGround(false);

			if (isPlayerEntity != level.isClientSide)
				continue;

			entity.setPos(worldPosition.getX() + 0.5, worldPosition.getY() + 1.0, worldPosition.getZ() + 0.5);
			launcher.applyMotion(entity, facing);

			if (!isPlayerEntity)
				continue;

			Player playerEntity = (Player) entity;

			if (launcher.getHorizontalDistance() * launcher.getHorizontalDistance()
				+ launcher.getVerticalDistance() * launcher.getVerticalDistance() >= 25 * 25)
				CatnipServices.NETWORK.sendToServer(new EjectorAwardPacket(worldPosition));

			if (!(playerEntity.getItemBySlot(EquipmentSlot.CHEST)
				.getItem() instanceof ElytraItem))
				continue;

			playerEntity.setXRot(-35);
			playerEntity.setYRot(facing.toYRot());
			playerEntity.setDeltaMovement(playerEntity.getDeltaMovement()
				.scale(.75f));
			deployElytra(playerEntity);
			CatnipServices.NETWORK.sendToServer(new EjectorElytraPacket(worldPosition));
		}

		if (doLogic) {
			lidProgress.chase(1, .8f, Chaser.EXP);
			state = State.LAUNCHING;
			if (!level.isClientSide) {
				level.playSound(null, worldPosition, SoundEvents.WOODEN_TRAPDOOR_CLOSE, SoundSource.BLOCKS, .35f, 1f);
				level.playSound(null, worldPosition, SoundEvents.CHEST_OPEN, SoundSource.BLOCKS, .1f, 1.4f);
			}
		}
	}

