public PriorityQueue<LogisticsTask> getTasks(Object holdingStack, boolean droneAccess) {
        this.droneAccess = droneAccess;

        ItemStack item = holdingStack instanceof ItemStack is ? is : ItemStack.EMPTY;
        FluidStack fluid = holdingStack instanceof FluidStack fs ? fs : FluidStack.EMPTY;

        PriorityQueue<LogisticsTask> tasks = new PriorityQueue<>();
        for (int priority = logistics.size() - 1; priority >= 0; priority--) {
            for (int requesterId = 0; requesterId < logistics.get(priority).size(); requesterId++) {
                AbstractLogisticsFrameEntity requester = logistics.get(priority).get(requesterId);
                if (droneAccess && requester.isObstructed(PathComputationType.AIR)) {
                    continue;
                }
                for (int i = 0; i < priority; i++) {
                    for (int providerId = 0; providerId < logistics.get(i).size(); providerId++) {
                        AbstractLogisticsFrameEntity provider = logistics.get(i).get(providerId);
                        if (droneAccess && provider.isObstructed(PathComputationType.AIR)) {
                            continue;
                        }
                        if (provider.shouldProvideTo(priority)) {
                            if (!item.isEmpty()) {
                                int requestedAmount = getRequestedAmount(requester, item, false);
                                if (requestedAmount > 0) {
                                    tasks.add(new LogisticsTask(provider, requester, item.copyWithCount(requestedAmount)));
                                    return tasks;
                                }
                            } else if (!fluid.isEmpty()) {
                                int requestedAmount = getRequestedAmount(requester, fluid, false);
                                if (requestedAmount > 0) {
                                    tasks.add(new LogisticsTask(provider, requester, fluid.copyWithAmount(requestedAmount)));
                                    return tasks;
                                }
                            }
                            // it could be that the drone is carrying some item or fluid it can't drop off right now
                            // however it might still be able to transfer the other resource type (i.e. transfer items if
                            // it's holding a fluid, and vice versa)
                            if (provider.getCachedTileEntity() != null) {
                                if (item.isEmpty()) {
                                    tryProvideItems(provider, requester, tasks);
                                }
                                if (fluid.isEmpty()) {
                                    tryProvideFluids(provider, requester, tasks);
                                }
                            }

                            // if we provided something to the requester, move the requester and provider to last in their
                            // lists so another frame gets selected first, effectively round-robin.
                            if (!tasks.isEmpty()) {
                                if (logistics.get(priority).size() > 1)
                                    logistics.get(priority).add(logistics.get(priority).remove(requesterId));
                                if (logistics.get(i).size() > 1)
                                    logistics.get(i).add(logistics.get(i).remove(providerId));
                                return tasks;
                            }
                        }
                    }
                }
            }
        }

        return tasks;
    }

@Override
    public void tick(MobJarTile tile) {
        super.tick(tile);
        if (tile.getLevel().isClientSide) {
            Allay allay = entityFromJar(tile);
            allay.tickCount++;
            allay.holdingItemAnimationTicks0 = allay.holdingItemAnimationTicks;
            if (allay.hasItemInHand()) {
                allay.holdingItemAnimationTicks = Mth.clamp(allay.holdingItemAnimationTicks + 1.0F, 0.0F, 5.0F);
            } else {
                allay.holdingItemAnimationTicks = Mth.clamp(allay.holdingItemAnimationTicks - 1.0F, 0.0F, 5.0F);
            }

            if (allay.isDancing()) {
                ++allay.dancingAnimationTicks;
                allay.spinningAnimationTicks0 = allay.spinningAnimationTicks;
                if (allay.isSpinning()) {
                    ++allay.spinningAnimationTicks;
                } else {
                    --allay.spinningAnimationTicks;
                }

                allay.spinningAnimationTicks = Mth.clamp(allay.spinningAnimationTicks, 0.0F, 15.0F);
            } else {
                allay.dancingAnimationTicks = 0.0F;
                allay.spinningAnimationTicks = 0.0F;
                allay.spinningAnimationTicks0 = 0.0F;
            }
        } else {
            Level level = tile.getLevel();
            if (level.getGameTime() % 40 == 0) {
                Allay allay = entityFromJar(tile);
                ItemStack heldStack = allay.getItemInHand(InteractionHand.MAIN_HAND);
                List<FilterableItemHandler> inventories = InvUtil.adjacentInventories(level, tile.getBlockPos());
                if (inventories.isEmpty()) {
                    return;
                }

                if (heldStack.getItem() instanceof ItemScroll) {
                    for (FilterableItemHandler filterableItemHandler : inventories) {
                        if (filterableItemHandler.filters instanceof FilterSet.ListSet listSet) {
                            listSet.addFilterScroll(heldStack, filterableItemHandler.getHandler());
                        }
                    }
                }
                InventoryManager manager = new InventoryManager(inventories);
                for (ItemEntity entity : level.getEntitiesOfClass(ItemEntity.class, new AABB(tile.getBlockPos()).inflate(5.0D))) {
                    if (entity.isAlive() && !entity.getItem().isEmpty()) {
                        if (heldStack.isEmpty() || heldStack.getItem() instanceof ItemScroll || ItemStack.isSameItem(entity.getItem(), heldStack)) {
                            MultiInsertReference reference = manager.insertStackWithReference(entity.getItem());
                            if (!reference.isEmpty()) {
                                ItemStack remainder = reference.getRemainder();
                                entity.setItem(remainder);
                                level.playSound(null, tile.getBlockPos(), SoundEvents.ITEM_PICKUP, SoundSource.BLOCKS, 0.8F, 1.0F);
                                return;
                            }
                        }
                    }
                }
            }
        }
    }

@Override
    protected void tick() {
        Level world = getWorld();
        int radius = 3;
        if (world.isClientSide) {
            BlockPos pos = getPos();
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), radius);
        }
        if (!getWorld().isClientSide && world.getGameTime() % 60 == 0) {
            boolean didWorkOnce = false;
            Level level = getWorld();
            BlockPos pos = getPos();
            //Get nearby source jars
            for (BlockPos blockPos : BlockPos.betweenClosed(pos.offset(-radius, -radius, -radius), pos.offset(radius, radius, radius))) {
                if (level.getBlockState(blockPos).getBlock() instanceof MobJar) {
                    MobJarTile tile = (MobJarTile) level.getBlockEntity(blockPos);
                    if (tile == null || tile.getEntity() != null) {
                        continue;
                    }
                    for (Entity e : level.getEntities((Entity) null, new AABB(tile.getBlockPos()).inflate(5), this::canJar)) {
                        for (var passenger : e.getPassengers()) {
                            passenger.stopRiding();
                        }
                        if (e instanceof Mob mob && ((Mob) e).isLeashed() && e.shouldBeSaved()) {
                            if (mob.isLeashed()) {
                                mob.dropLeash(true, true);
                            }
                        }
                        if (e instanceof Raider raider && raider.hasActiveRaid()) {
                            raider.getCurrentRaid().removeFromRaid(raider, false);
                        }
                        if (e instanceof Villager villager) {
                            villager.releasePoi(MemoryModuleType.HOME);
                            villager.releasePoi(MemoryModuleType.JOB_SITE);
                            villager.releasePoi(MemoryModuleType.POTENTIAL_JOB_SITE);
                            villager.releasePoi(MemoryModuleType.MEETING_POINT);
                        }
                        if (tile.setEntityData(e)) {
                            e.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);
                            EntityFlyingItem followProjectile = new EntityFlyingItem(level, e.position, Vec3.atCenterOf(tile.getBlockPos()), 100, 50, 100);
                            level.addFreshEntity(followProjectile);
                            ParticleUtil.spawnPoof((ServerLevel) level, e.getOnPos().above());
                            didWorkOnce = true;
                            if (e instanceof Starbuncle starbuncle) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.SHRUNK_STARBY.get(), (ServerLevel) level, starbuncle.blockPosition(), 10);
                            }
                            if (e instanceof LightningBolt bolt) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.CAUGHT_LIGHTNING.get(), (ServerLevel) level, bolt.blockPosition(), 10);
                            }
                            if (e instanceof ItemEntity item && item.getItem().getItem() == Items.CLOCK) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.TIME_IN_BOTTLE.get(), (ServerLevel) level, item.blockPosition(), 10);
                            }
                            break;
                        }
                    }
                }
            }
            if (didWorkOnce) {
                this.setNeedsSource(true);
            }
        }
    }

@Override
    public void extractRenderState(TileEntitySPSCasing sps, SPSMultiblockData multiblock, SPSRenderState state, float partialTick, Vec3 cameraPosition,
          ModelFeatureRenderer.@Nullable CrumblingOverlay breakProgress) {
        state.setProcessed(multiblock.lastProcessed);

        state.center = Vec3.atLowerCornerOf(multiblock.getMinPos())
              .add(Vec3.atLowerCornerOf(multiblock.getMaxPos()))
              .add(1, 1, 1)
              .scale(0.5);

        BlockPos pos = state.blockPos;
        BoltRenderer bolts = boltRendererMap.computeIfAbsent(multiblock.inventoryID, _ -> new BoltRenderer());

        int targetEffectCount = 0;
        long gameTime = sps.getGameTime();
        boolean tickingNormally = isTickingNormally(sps);
        if (tickingNormally) {
            Vector3fc renderCenter = new Vector3f((float) (state.center.x() - pos.getX()), (float) (state.center.y() - pos.getY()), (float) (state.center.z() - pos.getZ()));
            for (CoilData data : multiblock.coilData.coilMap.values()) {
                if (data.prevLevel > 0) {
                    bolts.update(data.coilPos.hashCode(), getBoltFromData(data, pos, renderCenter), gameTime, partialTick);
                }
            }
            if (multiblock.lastReceivedEnergy > 0) {
                if (random.nextDouble() < state.lerpEnergy(0.01F, 0.4F)) {
                    CuboidSide side = Util.getRandom(CuboidSide.VALUES, random);
                    Plane plane = Plane.getInnerCuboidPlane(multiblock.getBounds(), side);
                    Vector3fc endPos = plane.getRandomPoint(random).sub(pos.getX(), pos.getY(), pos.getZ());
                    BoltEffect bolt = new BoltEffect(BoltRenderInfo.ELECTRICITY, renderCenter, endPos, 15)
                          .size(0.01F * state.lerpEnergy(0.5F, 5))
                          .lifespan(8)
                          .spawn(SpawnFunction.NO_DELAY);
                    bolts.update(31 * side.hashCode() + endPos.hashCode(), bolt, gameTime, partialTick);
                }
                targetEffectCount = (int) state.lerpEnergy(10, 120);
            }
        }

        if (state.processed > 0) {
            state.coreState = new BillboardingRenderState();
            state.coreState.color = 0xF0FFFFFF;
            state.coreState.gridSize = 4;
            state.coreState.scale = state.lerpEnergy(0.1F, 4F);
            //TODO - 26.3: Re-evaluate this, ConduitBlockEntity#tickCount?
            state.coreState.renderTick =  (int) gameTime;
        }

        if (sps.orbitEffects.size() > targetEffectCount) {
            sps.orbitEffects.poll();
        } else if (sps.orbitEffects.size() < targetEffectCount && random.nextDouble() < 0.5) {
            sps.orbitEffects.add(new SPSOrbitEffect(multiblock, random));
        }
        for (SPSOrbitEffect effect : sps.orbitEffects) {
            BillboardingRenderState orbitState = new BillboardingRenderState();
            orbitState.color = SPSOrbitEffect.COLOR;
            orbitState.scale = effect.getScale();
            orbitState.renderTick = effect.getTick();
            effect.transformPos(orbitState.pos, partialTick);
            state.orbitEffects.add(orbitState);
        }
        state.boltRenderStates = bolts.collectBoltStates(gameTime, partialTick);
    }

@Override
    public void tick() {
        if (startActive() && tickCount == 1) activate();
        super.tick();
        if (level().isLoaded(blockPosition()) && !level().isClientSide() && (getCaster() == null || getCaster().isRemoved())) {
            explode();
        }
        findRidingEntities();
        if (travelling){
            for (Entity entity : ridingEntities) {
                entity.move(MoverType.SHULKER_BOX, getDeltaMovement().add(0, 0.1, 0));
            }
        }

        // Hit entities
        List<Entity> entitiesHit = getEntitiesNearby(1.7);
        if (travelling && !entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity.isRemoved()) continue;
                if (entity instanceof LivingEntity livingEntity && livingEntity.isDeadOrDying()) continue;
                if (level().isClientSide) continue;
                if (entity == getCaster()) continue;
                if (entity.noPhysics) continue;
                if (!entity.canBeHitByProjectile()) continue;
                if (entity instanceof ItemEntity) continue;
                if (!travellingBlockedBy(entity)) continue;
                if (ridingEntities != null && ridingEntities.contains(entity)) continue;
                if (hitEntities.contains(entity)) continue;
                boolean didHurt;
                if (getCaster() != null) {
                    didHurt = entity.hurt(damageSources().mobProjectile(this, getCaster()), damage);
                }
                else {
                    didHurt = entity.hurt(damageSources().generic(), damage);
                }
                if (didHurt) hitEntities.add(entity);
                if (isAlive() && getTier() != GeomancyTier.HUGE) this.explode();
            }
        }

        // Hit other boulders
        handleHitOtherBoulders();

        // Hit blocks
        if (travelling) {
            if (
                    !level().getEntities(this, getBoundingBox().inflate(0.1), (e) -> (ridingEntities == null || !ridingEntities.contains(e)) && e.canBeCollidedWith() && this.travellingBlockedBy(e)).isEmpty() ||
                            Iterables.size(level().getBlockCollisions(this, getBoundingBox().inflate(0.1))) > 0
            ) {
                this.explode();
            }
        }

        if (level().isClientSide() && getEntityData().get(SHOOT_DIRECTION).length() > 0 && !didShootParticles) {
            Vec3 ringOffset = new Vec3(getEntityData().get(SHOOT_DIRECTION)).scale(-1).normalize();
            ParticleRotation.OrientVector rotation = new ParticleRotation.OrientVector(ringOffset);
            AdvancedParticleBase.spawnAlwaysVisibleParticle(level(), ParticleHandler.RING2, 64, (float) getX() + (float) ringOffset.x, (float) getY() + 0.5f + (float) ringOffset.y, (float) getZ() + (float) ringOffset.z, 0, 0, 0, rotation, 3.5F, 0.83f, 1, 0.39f, 1, 1, (int) (5 + 2 * getBbWidth()), true, true, new ParticleComponent[]{
                    new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.ALPHA, ParticleComponent.KeyTrack.startAndEnd(0.7f, 0f), false),
                    new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.SCALE, ParticleComponent.KeyTrack.startAndEnd(0f, (1.0f + 0.5f * getBbWidth()) * 8f * getShootRingParticleScale()), false)
            });
            didShootParticles = true;
        }
    }

@Override
	public boolean cast(World world, double x, double y, double z, EnumFacing direction, int ticksInUse, int duration, SpellModifiers modifiers){

		Vec3d origin = new Vec3d(x, y, z);

		RayTraceResult result = findTarget(world, null, origin, new Vec3d(direction.getDirectionVec()), modifiers);

		if(result.entityHit instanceof EntityLivingBase){

			Entity entity = result.entityHit;

			// If the target is an entity, we need to use the entity's centre rather than the original hit position
			// because the entity will have moved!
			Vec3d target = GeometryUtils.getCentre(entity);

			double distance = origin.distanceTo(target);
			Vec3d vec = target.subtract(origin).normalize();

			float extensionSpeed = getProperty(EXTENSION_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY);

			// If the vine stretched too far
			if(distance > getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade) * STRETCH_LIMIT){
				if(world.isRemote && (ticksInUse-1) * extensionSpeed < distance){
					spawnLeafParticles(world, origin.subtract(0, SpellRay.Y_OFFSET, 0), vec, distance);
				}
				return false;
			}

			Vec3d hookPosition;

			if(ticksInUse * extensionSpeed < distance){
				// Extension
				hookPosition = origin.add(vec.scale(ticksInUse * extensionSpeed));

			}else{
				// Retraction
				Vec3d velocity = vec.scale(getProperty(REEL_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY));

				// Reel the entity hit towards the caster
				if(distance > MINIMUM_REEL_DISTANCE){
					double ax1 = (-velocity.x - entity.motionX) * REEL_ACCELERATION;
					double ay1 = (-velocity.y - entity.motionY) * REEL_ACCELERATION;
					double az1 = (-velocity.z - entity.motionZ) * REEL_ACCELERATION;
					entity.addVelocity(ax1, ay1, az1);
					// Player motion is handled on that player's client so needs packets
					if(entity instanceof EntityPlayerMP){
						((EntityPlayerMP)entity).connection.sendPacket(new SPacketEntityVelocity(entity));
					}
				}

				hookPosition = target;
			}

			if(world.isRemote){
				// world.getTotalWorldTime() - ticksInUse generates a constant but unique seed each time the spell is cast
				ParticleBuilder.create(Type.VINE).pos(origin).target(hookPosition).seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
			}

			return true;
		}

		return false;
	}

public static List<Entry> orderByPlacement(List<Entry> row) {
        if (row.size() < 2) {
            return row;
        }

        Map<ResourceKey<ISkillSegment>, Entry> byKey = row.stream().collect(Collectors.toMap(Entry::key, Function.identity()));
        Map<Entry, Integer> indices = new HashMap<>();
        Map<Entry, List<Entry>> successors = new HashMap<>();
        Map<Entry, Integer> predecessors = new HashMap<>();

        for (Entry entry : row) {
            indices.put(entry, indices.size());
            predecessors.put(entry, 0);
        }

        for (Entry entry : row) {
            SegmentPlacement placement = entry.segment().value().placement().orElse(null);
            if (placement == null) {
                continue;
            }
            Entry relative = byKey.get(placement.segment());
            if (relative == null || relative == entry) {
                LOGGER.warn("Skill segment {} is placed {} a segment that is not part of its row", entry.key().identifier(), placement.type().getSerializedName());
                continue;
            }
            Entry first = switch (placement.type()) {
                case BEFORE -> entry;
                case AFTER -> relative;
            };
            Entry second = first == entry ? relative : entry;
            successors.computeIfAbsent(first, _ -> new ArrayList<>()).add(second);
            predecessors.merge(second, 1, Integer::sum);
        }

        if (successors.isEmpty()) {
            return row;
        }

        PriorityQueue<Entry> queue = new PriorityQueue<>(Comparator.comparingInt(indices::get));
        predecessors.forEach((entry, count) -> {
            if (count == 0) {
                queue.add(entry);
            }
        });

        List<Entry> ordered = new ArrayList<>(row.size());
        while (!queue.isEmpty()) {
            Entry entry = queue.poll();
            ordered.add(entry);
            for (Entry successor : successors.getOrDefault(entry, List.of())) {
                if (predecessors.merge(successor, -1, Integer::sum) == 0) {
                    queue.add(successor);
                }
            }
        }

        if (ordered.size() != row.size()) {
            LOGGER.error("Skill segment placements form a cycle and are ignored: {}", row.stream().filter(entry -> !ordered.contains(entry)).map(entry -> entry.key().identifier().toString()).collect(Collectors.joining(", ")));
            return row;
        }

        return ordered;
    }

public void tick() {
        if (hackComplete) return;

        isStarted = true;

        if (stopWormTimer > 0) {
            stopWormTimer--;
        }
        if (nukeVirusCooldown > 0) {
            nukeVirusCooldown--;
        }

        allConnections.clear();
        int nonNullNodes = 0;
        int completeNodes = 0;
        for (int i = 0; i < nodes.length; i++) {
            Node node = getNodeAt(i);
            if (node == null) continue;
            nonNullNodes++;

            int f = node.fortification;
            node.tick();
            if (controller != null && f < NODE_FORTIFICATION_TIME && node.fortification == NODE_FORTIFICATION_TIME) {
                controller.onNodeFortified(this, i);
            }

            if (side == HackingSide.AI && isAwake() && (isDummy() || node.isHacked()) && node.outGoingHacks.isEmpty()) {
                // start the trace to all neighbouring nodes
                for (int neighbourPos : getNeighbours(i)) {
                    Node neighbourNode = getNodeAt(neighbourPos);
                    if (neighbourNode != null && (isDummy() || !neighbourNode.isHacked())) {
                        // found an unhacked neighbour
                        node.startHacking(i, neighbourPos);
                    }
                }
            }

            if (pendingNukePos == i) {
                activateNukeVirus(i);
            }

            // update all in-progress connections
            int finishedConns = 0;
            for (Pair<Integer, Float> conn : node.outGoingHacks) {
                if (conn.getValue() < 1F) {
                    if (stopWormTimer == 0) {
                        Node targetNode = getNodeAt(conn.getKey());
                        if (targetNode != null) {
                            conn.setValue(Math.min(1F, conn.getValue() + targetNode.getProgressPerTick()));
                            targetNode.setHackProgress(conn.getKey(), conn.getValue(), true);
                        }
                    }
                } else {
                    finishedConns++;
                }
                allConnections.add(new ConnectionEntry(i, conn.getKey(), conn.getValue()));
            }
            if (finishedConns == node.outGoingHacks.size() && !node.outGoingHacks.isEmpty()) completeNodes++;
        }
        if (completeNodes >= nonNullNodes) {
            hackComplete = true;
        }
    }

@Override
	public void update() {
		super.update();

		if (getBlockType() == ModBlocks.MANA_BATTERY && !((BlockManaBattery) getBlockType()).testStructure(getWorld(), getPos()).isEmpty())
			return;

		if (getStructurePos() != getPos()) {
			setStructurePos(getPos());
			markDirty();
		}

		if (getBlockType() != ModBlocks.CREATIVE_MANA_BATTERY) {
			for (BlockPos relative : poses) {
				BlockPos target = getPos().add(relative);
				TileEntity tile = world.getTileEntity(target);
				if (tile instanceof TileOrbHolder) {
					if (!((TileOrbHolder) tile).isPartOfStructure() || ((TileOrbHolder) tile).canSuckFromOutside() || !((TileOrbHolder) tile).canGiveToOutside()) {
						((TileOrbHolder) tile).setStructurePos(getPos());
						((TileOrbHolder) tile).setCanSuckFromOutside(false);
						((TileOrbHolder) tile).setCanGiveToOutside(true);
						tile.markDirty();
					}
				}
			}


			if (world.getTotalWorldTime() % 20 == 0 && !ManaManager.forObject(getWizardryCap()).isManaFull()) {
				ManaManager.forObject(getWizardryCap())
						.addMana(5)
						.removeBurnout(5)
						.close();

				if (world.isRemote)
					ClientRunnable.run(new ClientRunnable() {
						@Override
						@SideOnly(Side.CLIENT)
						public void runIfClient() {
							Vec3d from = new Vec3d(getPos()).add(0.5, 1, 0.5);
							Vec3d to = from.add(RandUtil.nextDouble(-1, 1), -3, RandUtil.nextDouble(-1, 1));

							ParticleBuilder helix = new ParticleBuilder(200);
							helix.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
							helix.setAlphaFunction(new InterpFloatInOut(0.1f, 0.1f));
