@Override
	public void setTaskGuiProviders()
	{
		FTBQuestsTasks.ITEM.setGuiProvider((gui, quest, callback) -> new GuiSelectItemStack(gui, stack -> {
			if (!stack.isEmpty())
			{
				ItemTask itemTask = new ItemTask(quest);
				itemTask.items.add(ItemHandlerHelper.copyStackWithSize(stack, 1));
				itemTask.count = stack.getCount();

				if (!stack.isStackable())
				{
					itemTask.nbtMode = NBTMatchingMode.IGNORE;
					itemTask.ignoreDamage = !stack.getHasSubtypes();
				}

				callback.accept(itemTask);
			}
		}).openGui());

		FTBQuestsTasks.FLUID.setGuiProvider((gui, quest, callback) -> new GuiSelectFluid(gui, () -> FluidRegistry.WATER, fluid -> {
			if (fluid != null)
			{
				FluidTask fluidTask = new FluidTask(quest);
				fluidTask.fluid = fluid;
				callback.accept(fluidTask);
			}
		}).openGui());

		FTBQuestsTasks.DIMENSION.setGuiProvider((gui, quest, callback) -> {
			DimensionTask task = new DimensionTask(quest);
			task.dimension = Minecraft.getMinecraft().world.provider.getDimension();
			callback.accept(task);
		});

		FTBQuestsTasks.LOCATION.setGuiProvider((gui, quest, callback) -> {
			LocationTask task = new LocationTask(quest);
			Minecraft mc = Minecraft.getMinecraft();

			if (mc.objectMouseOver != null && mc.objectMouseOver.typeOfHit == RayTraceResult.Type.BLOCK)
			{
				TileEntity tileEntity = mc.world.getTileEntity(mc.objectMouseOver.getBlockPos());

				if (tileEntity instanceof TileEntityStructure)
				{
					BlockPos pos = ((TileEntityStructure) tileEntity).getPosition();
					BlockPos size = ((TileEntityStructure) tileEntity).getStructureSize();
					task.dimension = mc.world.provider.getDimension();
					task.x = pos.getX() + tileEntity.getPos().getX();
					task.y = pos.getY() + tileEntity.getPos().getY();
					task.z = pos.getZ() + tileEntity.getPos().getZ();
					task.w = Math.max(1, size.getX());
					task.h = Math.max(1, size.getY());
					task.d = Math.max(1, size.getZ());
					callback.accept(task);
					return;
				}
			}

			ConfigGroup group = ConfigGroup.newGroup(FTBQuests.MOD_ID);
			task.getConfig(task.createSubGroup(group));
			new GuiEditConfig(group, (g1, sender) -> callback.accept(task)).openGui();
		});
	}

@Override
    public void render(T pEntity, float pEntityYaw, float pPartialTicks, PoseStack pMatrixStack, MultiBufferSource pBuffer, int pPackedLight) {
        if (pEntity.isIntro() && pEntity.introTick < 5) {
            return;
        }
        super.render(pEntity, pEntityYaw, pPartialTicks, pMatrixStack, pBuffer, pPackedLight);
        if (pEntity.deathTime > MathHelper.secondsToTicks(2.5F)){
            pMatrixStack.pushPose();
            boolean flag = pEntity.hurtTime > 0;
            float f = Mth.rotLerp(pPartialTicks, pEntity.yBodyRotO, pEntity.yBodyRot);
            float f1 = Mth.rotLerp(pPartialTicks, pEntity.yHeadRotO, pEntity.yHeadRot);
            float f2 = f1 - f;
            float f6 = Mth.lerp(pPartialTicks, pEntity.xRotO, pEntity.getXRot());
            float f71 = this.getBob(pEntity, pPartialTicks);
            this.setupRotations(pEntity, pMatrixStack, f71, f, pPartialTicks);
            pMatrixStack.scale(-1.0F, -1.0F, 1.0F);
            this.scale(pEntity, pMatrixStack, pPartialTicks);
            pMatrixStack.translate(0.0D, -1.501F, 0.0D);
            this.model.prepareMobModel(pEntity, 0.0F, 0.0F, pPartialTicks);
            this.model.setupAnim(pEntity, 0.0F, 0.0F, f71, f2, f6);
            float f8 = MathHelper.secondsToTicks(5);
            float f9 = (pEntity.deathTime - MathHelper.secondsToTicks(2.5F)) / f8;
            float f10 = 1.0F - ((pEntity.deathTime - MathHelper.secondsToTicks(2.5F)) / f8);
            VertexConsumer vertexconsumer = pBuffer.getBuffer(RenderType.dragonExplosionAlpha(DEATH));
            this.model.renderToBuffer(pMatrixStack, vertexconsumer, pPackedLight, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, f9);
            VertexConsumer ivertexbuilder1 = pBuffer.getBuffer(RenderType.entityDecal(this.getTextureLocation(pEntity)));
            this.model.renderToBuffer(pMatrixStack, ivertexbuilder1, pPackedLight, OverlayTexture.pack(0.0F, flag), f10, f10, f10, 1.0F);
            pMatrixStack.popPose();
        }
        if (pEntity.isAlive()) {
            double currentX = Mth.lerp(pPartialTicks, pEntity.xo, pEntity.getX());
            double currentY = Mth.lerp(pPartialTicks, pEntity.yo, pEntity.getY());
            double currentZ = Mth.lerp(pPartialTicks, pEntity.zo, pEntity.getZ());
            float currentTick = getBob(pEntity, pPartialTicks);
            if (pEntity.trailSnapshots.isEmpty() || currentTick - pEntity.lastTrailTick > SNAPSHOT_INTERVAL) {
                if (pEntity.shouldAddTrailSnapshot()) {
                    Map<String, ModelPartPose> snapshot = ModelUtil.saveModelSnapshot(this.getModel().allPartNames, this.getModel()::getAnyDescendantWithName);
                    pEntity.trailSnapshots.add(0, Pair.of(new Vec3(currentX, currentY, currentZ), new ModelSnapshot(0, Mth.rotLerp(pPartialTicks, pEntity.yBodyRotO, pEntity.yBodyRot), currentTick, snapshot)));
                    pEntity.lastTrailTick = currentTick;
                }
                pEntity.trailSnapshots.removeIf(p -> currentTick - p.getSecond().timestamp() > SNAPSHOT_LIFESPAN);
                while (pEntity.trailSnapshots.size() > 32) {
                    pEntity.trailSnapshots.remove(pEntity.trailSnapshots.size() - 1);
                }
            }
            for (int i = 0; i < pEntity.trailSnapshots.size(); i++) {
                pMatrixStack.pushPose();
                Vec3 trailPos = pEntity.trailSnapshots.get(i).getFirst();
                ModelSnapshot snapshot = pEntity.trailSnapshots.get(i).getSecond();
                ModelUtil.loadPoseFromSnapshot(snapshot.poses(), this.shadowModel::getAnyDescendantWithName);
                pMatrixStack.translate(trailPos.x - currentX, trailPos.y - currentY, trailPos.z - currentZ);
                pMatrixStack.mulPose(Axis.YP.rotationDegrees(180.0F - snapshot.yRot()));
                pMatrixStack.scale(-1.0F, -1.0F, 1.0F);
                this.scale(pEntity, pMatrixStack, pPartialTicks);
                pMatrixStack.translate(0.0F, -1.5F, 0.0F);
                VertexConsumer vertexConsumer = pBuffer.getBuffer(AFTERIMAGE_RENDER_TYPE);
                float modelAlpha = (1 - Mth.clamp(currentTick - snapshot.timestamp(), 0, SNAPSHOT_LIFESPAN) / SNAPSHOT_LIFESPAN) * 0.35F;
                if (modelAlpha > 0) {
                    this.shadowModel.renderToBuffer(pMatrixStack, vertexConsumer, pPackedLight, OverlayTexture.NO_OVERLAY, 1.0F, 1.0F, 1.0F, modelAlpha);
                }
                pMatrixStack.popPose();
            }
        }
    }

public void aiStep() {
        super.aiStep();

        if (!this.level.isClientSide) {
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.003D, 0.0D));
                if (!this.isNotMoving() && this.random.nextInt(5) == 0 && this.getDeltaMovement().horizontalDistance() > 0.08) {
                    Vec3 testpos = this.position().add(Math.cos(Math.toRadians(this.getYRot()+ 90)) * -0.8, 0, Math.sin(Math.toRadians(this.getYRot() + 90)) * -0.8);
                    BlockPos testblockpos = new BlockPos(testpos);
                    if (level.getBlockState(new BlockPos(testblockpos.below())).is(BlockTags.MINEABLE_WITH_SHOVEL))
                        ((ServerLevel)this.level).sendParticles(new BlockParticleOption(ParticleTypes.FALLING_DUST, this.level.getBlockState(testblockpos.below())), testpos.x, testpos.y + 0.2, testpos.z, 2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, 0);
                    else
                        ((ServerLevel)this.level).sendParticles(ParticleTypes.UNDERWATER, testpos.x, testpos.y + 0.2, testpos.z, 2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, random.nextFloat() * 0.2, 0);
                }
            }
            if (this.isPlayingDead() && this.forceSleep == 0) {
                this.setPlayingDead(false);
            }

            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
                if (this.getJoeys() > 0 && this.random.nextInt(2) == 0) {
                    EntityOpossum child = this.getBreedOffspring((ServerLevel) this.level, this);
                    if (child != null) {
                        child.setVariant(this.getVariant());
                        child.setAge(this.getAdulthoodTime() * -1);
                        child.setGender(this.random.nextInt(2));
                        child.setRandomMobSize();
                        child.setBaby(true);
                        child.moveTo(this.getX(), this.getY(), this.getZ(), 0.0F, 0.0F);
                        if (this.getOwner() != null)
                            child.tame((Player) this.getOwner());
                        if (this instanceof INeedsPostUpdate) {
                            ((INeedsPostUpdate) child).updateAttributes();
                        }
                        if (TEXTURES_COMMON.containsKey(child.getType().getRegistryName().getPath())) {
                            chooseSkinForSpecies(child, true);
                        }
                        //((ServerLevel)this.level).addFreshEntityWithPassengers(child);
                        this.level.addFreshEntity(child);
                        this.level.broadcastEntityEvent(this, (byte)18);
                        this.setJoeys(this.getJoeys() - 1);
                    }
                }
            }
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                int i = this.random.nextInt(3000);
                if (i <= 8 && !this.isInWater()) {
                    this.getNavigation().stop();
                    this.setSitting(true);
                }
                else if ((i <= 12 || this.isInWater()) && this.isSitting()) {
                    this.setSitting(false);
                }
                else if (i > 2980) {
                    this.setAnimation(IDLE_SCRATCH);
                }
            }

            if (this.getAnimation() == THREAT_BACK_OFF) {
                this.getMoveControl().strafe(-0.5F, 0);
            }
        }
    }

