private void tickEnd(Player player) {
        Mekanism.playerState.updateElytraFlight(player);
        Mekanism.playerState.updateStepAssist(player);
        if (player instanceof ServerPlayer serverPlayer) {
            PlayerExposure.tickServer(serverPlayer);
        }
        RegistryAccess registryAccess = player.level().registryAccess();

        ItemAccess jetpack = IJetpackItem.getActiveJetpack(player);
        if (jetpack != null) {
            ItemResource primaryJetpack = IJetpackItem.getPrimaryJetpack(player);
            if (!primaryJetpack.isEmpty()) {
                IJetpackItem jetpackItem = (IJetpackItem) primaryJetpack.getItem();
                JetpackMode primaryMode = jetpackItem.getJetpackMode(primaryJetpack);
                JetpackMode mode = IJetpackItem.getPlayerJetpackMode(player, primaryMode, p -> Mekanism.keyMap.has(p.getUUID(), KeySync.ASCEND));
                if (mode != JetpackMode.DISABLED) {
                    try (Transaction transaction = Transaction.openRoot()) {
                        double jetpackThrust = ((IJetpackItem) jetpack.getResource().getItem()).useJetpackFuel(registryAccess, jetpack, primaryJetpack, transaction);
                        if (jetpackThrust > 0) {
                            if (IJetpackItem.handleJetpackMotion(player, mode, jetpackThrust, p -> Mekanism.keyMap.has(p.getUUID(), KeySync.ASCEND))) {
                                player.resetFallDistance();
                                if (player instanceof ServerPlayer serverPlayer) {
                                    serverPlayer.connection.aboveGroundTickCount = 0;
                                }
                            }
                            if (player.level().getGameTime() % MekanismUtils.TICKS_PER_HALF_SECOND == 0) {
                                player.gameEvent(MekanismGameEvents.JETPACK_BURN);
                            }
                            transaction.commit();
                        }
                    }
                }
            }
        }

        ItemAccess chest = ItemAccessUtils.forEntitySlot(player, EquipmentSlot.CHEST);
        if (isScubaMaskOn(player, chest)) {
            final int max = player.getMaxAirSupply();
            ResourceHandler<ChemicalResource> chemicalHandler = AutomatedResourceHandler.manual(Capabilities.CHEMICAL.getCapability(chest));
            if (chemicalHandler != null) {
                ChemicalResource oxygen = ChemicalUtils.getResource(registryAccess, ChemicalIds.OXYGEN);
                if (!oxygen.isEmpty()) {
                    try (Transaction transaction = Transaction.openRoot()) {
                        //TODO - 26.3: Re-evaluate this single usage on its own
                        chemicalHandler.extract(oxygen, 1, transaction);
                        int extracted = chemicalHandler.extract(oxygen, max - player.getAirSupply(), transaction);
                        if (extracted > 0) {
                            player.setAirSupply(player.getAirSupply() + extracted);
                            transaction.commit();
                        }
                    }
                }
            }
            if (player.getAirSupply() == max) {
                for (MobEffectInstance effect : player.getActiveEffects()) {
                    if (MekanismUtils.shouldSpeedUpEffect(effect)) {
                        for (int i = 0; i < 9; i++) {
                            MekanismUtils.speedUpEffectSafely(player, effect);
                        }
                    }
                }
            }
        }
    }

public static void renderOverlay(BoxElementImpl root, GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		root.updateRect(animation);

		WailaTickHandler tickHandler = JadeClient.tickHandler();
		if (tickHandler.state != null) {
			for (JadeBeforeRenderCallback callback : WailaClientRegistration.instance().beforeRenderCallback.callbacks()) {
				if (callback.beforeRender(root, animation, graphics, tickHandler.state.accessor())) {
					return;
				}
			}

			root.beforeRender(tickHandler.state.accessor(), partialTicks);
		}

		boolean renderDebug = IWailaConfig.get().general().isDebug() && JadeUI.hasControlDown();
		if (renderDebug) {
			Rect2f bossBarRect = ClientProxy.getBossBarRect();
			if (bossBarRect != null) {
				JadeInternals.getDisplayHelper().drawBorder(graphics, bossBarRect, 2, 0x88FF00FF, true);
			}
		}

		Matrix3x2fStack matrixStack = graphics.pose();
		matrixStack.pushMatrix();
		Rect2f rect = animation.rect;
		matrixStack.translate(rect.getX(), rect.getY());

		float scale = animation.scale;
		if (scale != 1f) {
			matrixStack.scale(scale);
		}

		Vector2i mouse = new Vector2i(mouseX, mouseY);
		if (mouseX != -1) {
			animation.mapMousePosition(mouseX, mouseY, (x, y) -> mouse.set(x.intValue(), y.intValue()));
		}

		root.setWidgetAlpha(animation.alpha);
		((JadeGuiGraphics) graphics).jade$setIgnoreScissorTest(true);
		graphics.deferredTooltip = null;
		root.extractRenderState(graphics, mouse.x, mouse.y, partialTicks);
		((JadeGuiGraphics) graphics).jade$setIgnoreScissorTest(false);
		if (renderDebug) {
			root.renderDebug(graphics, mouse.x, mouse.y, partialTicks, new Element.RenderDebugContext(root, rect, true));
		} else if (JadeUI.isPinned() && JadeUI.hasControlDown()) {
			if (root.getChildAt(mouse.x, mouse.y).orElse(root) instanceof Element element) {
				element.renderDebug(graphics, mouse.x, mouse.y, partialTicks, new Element.RenderDebugContext(root, rect, false));
			}
		}

		if (tickHandler.state != null) {
			WailaClientRegistration.instance().afterRenderCallback.call(callback -> {
				callback.afterRender(root, animation, graphics, tickHandler.state.accessor());
			});
		}

		matrixStack.popMatrix();
		graphics.extractDeferredElements(mouseX, mouseY, partialTicks);

		if (IWailaConfig.get().accessibility().shouldEnableTextToSpeech()) {
			tickHandler.narrate(root, true);
		}

		shown = true;
	}

@SubscribeEvent
	@SideOnly(Side.CLIENT)
	public static void render(RenderWorldLastEvent event) {
		World world = Minecraft.getMinecraft().world;
		EntityPlayer player = Minecraft.getMinecraft().player;
		if (player == null || world == null) return;

		GlStateManager.pushMatrix();

		double interpPosX = player.lastTickPosX + (player.posX - player.lastTickPosX) * event.getPartialTicks();
		double interpPosY = player.lastTickPosY + (player.posY - player.lastTickPosY) * event.getPartialTicks();
		double interpPosZ = player.lastTickPosZ + (player.posZ - player.lastTickPosZ) * event.getPartialTicks();

		GlStateManager.translate(-interpPosX, -interpPosY + 0.1, -interpPosZ);

		GlStateManager.disableCull();
		GlStateManager.depthMask(false);
		GlStateManager.enableBlend();
		GlStateManager.disableTexture2D();
		GlStateManager.shadeModel(GL11.GL_SMOOTH);
		GlStateManager.blendFunc(GL_SRC_ALPHA, GL_ONE);
		GlStateManager.enableColorMaterial();
		GlStateManager.disableLighting();

		Tessellator tessellator = Tessellator.getInstance();
		BufferBuilder vb = tessellator.getBuffer();

		Set<EntityUnicorn> corns = new HashSet<>(positions.keySet());
		for (EntityUnicorn corn : corns) {
			if (corn.world.provider.getDimension() != world.provider.getDimension()) continue;

			List<Point> points = new ArrayList<>(positions.getOrDefault(corn, new ArrayList<>()));
			boolean q = false;

			vb.begin(GL11.GL_TRIANGLE_STRIP, DefaultVertexFormats.POSITION_COLOR);
			for (Point pos : points) {
				if (pos == null) continue;

				float sub = (world.getTotalWorldTime() - pos.time);
				Color color = Color.getHSBColor(sub % 360.0f / 360.0f, 1f, 1f);

				int alpha;
				if (sub < 500) {
					alpha = (int) (MathHelper.clamp(Math.log(sub + 1) / 2.0, 0, 1) * 80.0);
				} else {
					alpha = (int) (MathHelper.clamp(1 - (Math.log(sub) / 2.0), 0, 1) * 80.0);
				}

				pos(vb, pos.origin.subtract(pos.normal.scale(1.5))).color(color.getRed(), color.getGreen(), color.getBlue(), alpha).endVertex();
				pos(vb, pos.origin.add(pos.normal.scale(1.5))).color(color.getRed(), color.getGreen(), color.getBlue(), alpha).endVertex();
				q = !q;
			}

			tessellator.draw();
		}

		GlStateManager.enableCull();
		GlStateManager.depthMask(true);
		GlStateManager.disableBlend();
		GlStateManager.enableTexture2D();
		GlStateManager.shadeModel(GL11.GL_FLAT);
		GlStateManager.tryBlendFuncSeparate(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA, GlStateManager.SourceFactor.ONE, GlStateManager.DestFactor.ZERO);

		GlStateManager.popMatrix();
	}

@Override
	public boolean collideBurst(ManaBurst burst, HitResult pos, boolean isManaBlock, boolean shouldKill, ItemStack stack) {
		Entity entity = burst.entity();
		int storedColor = LensItem.getStoredColor(stack);
		if (!entity.level().isClientSide && !burst.isFake() && storedColor > -1 && storedColor < 17) {
			if (pos.getType() == HitResult.Type.ENTITY) {
				Entity collidedWith = ((EntityHitResult) pos).getEntity();
				if (collidedWith instanceof Sheep sheep) {
					int r = 20;
					DyeColor sheepColor = sheep.getColor();
					List<Sheep> sheepList = entity.level().getEntitiesOfClass(Sheep.class,
							new AABB(sheep.getX() - r, sheep.getY() - r, sheep.getZ() - r,
									sheep.getX() + r, sheep.getY() + r, sheep.getZ() + r));
					for (Sheep other : sheepList) {
						if (other.getColor() == sheepColor) {
							other.setColor(DyeColor.byId(storedColor == 16 ? other.level().random.nextInt(16) : storedColor));
						}
					}
					shouldKill = true;
				} else if (collidedWith instanceof SparkEntity spark) {
					spark.setNetwork(DyeColor.byId(storedColor == 16 ? collidedWith.level().random.nextInt(16) : storedColor));
				}
			} else if (pos.getType() == HitResult.Type.BLOCK) {
				BlockPos hitPos = ((BlockHitResult) pos).getBlockPos();
				Block hitBlock = entity.level().getBlockState(hitPos).getBlock();
				ResourceLocation blockId = BuiltInRegistries.BLOCK.getKey(hitBlock);

				if (BotaniaAPI.instance().getPaintableBlocks().containsKey(blockId)
						&& entity.mayInteract(entity.level(), hitPos)) {
					List<BlockPos> coordsToPaint = new ArrayList<>();
					Queue<BlockPos> coordsToCheck = new ArrayDeque<>();
					Set<BlockPos> checkedCoords = new HashSet<>();
					coordsToCheck.add(hitPos);
					checkedCoords.add(hitPos);

					while (!coordsToCheck.isEmpty() && coordsToPaint.size() < 1000) {
						BlockPos coords = coordsToCheck.remove();
						coordsToPaint.add(coords);

						for (Direction dir : Direction.values()) {
							BlockPos candidatePos = coords.relative(dir);
							if (checkedCoords.add(candidatePos)
									&& entity.level().getBlockState(candidatePos).is(hitBlock)
									&& entity.mayInteract(entity.level(), hitPos)) {
								coordsToCheck.add(candidatePos);
							}
						}
					}
					for (BlockPos coords : coordsToPaint) {
						DyeColor placeColor = DyeColor.byId(storedColor == 16 ? entity.level().random.nextInt(16) : storedColor);
						BlockState stateThere = entity.level().getBlockState(coords);

						Function<DyeColor, Block> f = BotaniaAPI.instance().getPaintableBlocks().get(blockId);
						Block newBlock = f.apply(placeColor);
						if (newBlock != stateThere.getBlock()) {
							entity.level().setBlockAndUpdate(coords, newBlock.withPropertiesOf(stateThere));
							XplatAbstractions.INSTANCE.sendToNear(entity.level(), coords, new BotaniaEffectPacket(EffectType.PAINT_LENS, coords.getX(), coords.getY(), coords.getZ(), placeColor.getId()));
						}
					}
				}
			}
		}

		return shouldKill;
	}

@Override
	public boolean cast(World world, EntityLiving caster, EnumHand hand, int ticksInUse, EntityLivingBase target, SpellModifiers modifiers){

		if(target == null) return false;

		Vec3d origin = caster.getPositionEyes(1);

		// If the target is an entity, we need to use the entity's centre rather than the original hit position
		// because the entity will have moved!
		Vec3d targetVec = GeometryUtils.getCentre(target);

		RayTraceResult hit = findTarget(world, caster, origin, targetVec.subtract(origin).normalize(), modifiers);

		if(hit.typeOfHit != RayTraceResult.Type.ENTITY || hit.entityHit != target) return false; // Something was in the way

		double distance = origin.distanceTo(targetVec);

		// Can't cast the spell at all if the target is too far away
		if(ticksInUse <= 1 && distance > getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade))
			return false;

		Vec3d vec = targetVec.subtract(origin).normalize();

		float extensionSpeed = getProperty(EXTENSION_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY);

		// If the vine stretched too far
		if(distance > getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade) * STRETCH_LIMIT){
			if(world.isRemote && (ticksInUse-1) * extensionSpeed < distance){
				spawnLeafParticles(world, origin.subtract(0, SpellRay.Y_OFFSET, 0), vec, distance);
			}
			return false;
		}

		Vec3d hookPosition;

		if(ticksInUse * extensionSpeed < distance){
			// Extension
			hookPosition = origin.add(vec.scale(ticksInUse * extensionSpeed));

		}else{
			// Retraction
			Vec3d velocity = vec.scale(getProperty(REEL_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY));

			// Reel the entity hit towards the caster
			if(distance > MINIMUM_REEL_DISTANCE){
				double ax1 = (-velocity.x - target.motionX) * REEL_ACCELERATION;
				double ay1 = (-velocity.y - target.motionY) * REEL_ACCELERATION;
				double az1 = (-velocity.z - target.motionZ) * REEL_ACCELERATION;
				target.addVelocity(ax1, ay1, az1);
				// Player motion is handled on that player's client so needs packets
				if(target instanceof EntityPlayerMP){
					((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
				}
			}

			hookPosition = targetVec;
		}

		if(world.isRemote){
			// world.getTotalWorldTime() - ticksInUse generates a constant but unique seed each time the spell is cast
			ParticleBuilder.create(Type.VINE).pos(origin).target(hookPosition).tvel(vec.scale(extensionSpeed))
					.seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
		}

		return true;
	}

private void evaluate(double time) {
        lastEvalTime = time;
        var leaves = timeline.leafTracks(false);
        var controlled = controlledObjectIds(leaves);
        // revert objects that are no longer controlled (e.g. their track/clip was deleted)
        for (var id : lastControlled) {
            if (!controlled.contains(id) && runtime.objects.get(id) instanceof FXObject object) {
                object.setSelfActive(true);
                object.setSelfTimelineVisible(true);
                lastControlClip.remove(id);
            }
        }
        lastControlled.clear();
        lastControlled.addAll(controlled);

        for (var id : controlled) {
            if (!(runtime.objects.get(id) instanceof FXObject object)) {
                continue;
            }
            boolean hasActivator = false;
            boolean activatorActive = false;
            boolean hasControl = false;
            Clip controlClip = null;
            for (var track : leaves) {
                if (track.mute()) {
                    continue;
                }
                if (track instanceof ActivatorTrack activator) {
                    if (id.equals(activator.targetId())) {
                        hasActivator = true;
                        if (activator.clipAt(time) != null) {
                            activatorActive = true;
                        }
                    }
                } else if (track instanceof ControlTrack control) {
                    for (var clip : control.clips()) {
                        if (id.equals(clip.targetId())) {
                            hasControl = true;
                            break;
                        }
                    }
                    if (controlClip == null) {
                        controlClip = control.clipForObjectAt(id, time);
                    }
                }
            }

            // control restart: reset + reseed when entering (or switching to) a control clip
            var previous = lastControlClip.get(id);
            if (controlClip != previous) {
                if (controlClip != null) {
                    restart(object, controlClip);
                }
                lastControlClip.put(id, controlClip);
            }

            var state = TimelineState.resolve(hasActivator, activatorActive, hasControl, controlClip != null);
            object.setSelfActive(state.tick());
            object.setSelfTimelineVisible(state.render());
        }

        applyAnimations(time);
        applySpeed(leaves, time);
        dispatchSignals(leaves, time);
        applyAudio(leaves, time);
    }

public void tick() {
        if (this.level != null) {
            boolean flag = this.level.getBiome(this.getBlockPos()).is(Biomes.DEEP_DARK);
            if (flag) {
                this.findCandlesticks();
                if (!this.level.isClientSide) {
                    if (this.level.random.nextFloat() < 0.3F) {
                        if (this.level.random.nextFloat() < 0.17F) {
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.FURNACE_FIRE_CRACKLE, 0.5F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F));
                        }
                    }
                }
                if (!this.candlestickBlockEntityList.isEmpty()){
                    BrazierRecipe recipe = this.getRecipe();
                    double d0 = (double)this.worldPosition.getX() + this.level.random.nextDouble();
                    double d1 = (double)this.worldPosition.getY() + 0.5D + this.level.random.nextDouble();
                    double d2 = (double)this.worldPosition.getZ() + this.level.random.nextDouble();
                    if (!this.level.isClientSide) {
                        ServerLevel serverWorld = (ServerLevel) this.level;
                        this.makeParticles();
                        if (this.activate(this.level)) {
                            if (recipe != null) {
                                for (int p = 0; p < 2; ++p) {
                                    serverWorld.sendParticles(ModParticleTypes.SMALL_NECRO_FIRE.get(), d0, this.worldPosition.getY() + 0.5F, d2, 1, 0, 0, 0, 0);
                                    serverWorld.sendParticles(ParticleTypes.SMOKE, d0, d1, d2, 0, 0.0D, 5.0E-4D, 0.0D, 0.5F);
                                    serverWorld.sendParticles(ModParticleTypes.NECRO_EFFECT.get(), d0, d1, d2, 1, 0.0F, 0.0F, 0.0F, 0.0F);
                                }
                                for (BlockEntity blockEntity : this.candlestickBlockEntityList){
                                    if (blockEntity instanceof ISoulCandle soulCandle) {
                                        if (soulCandle.getSouls() > 0) {
                                            soulCandle.drainSouls(this.getBlockPos());
                                            this.currentTime += soulCandle.soulDrainAmount();
                                        }
                                    }
                                }
                                if (!this.playSound) {
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.BLAZE_AMBIENT, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F));
                                    this.playSound = true;
                                }
                                if (this.level.getGameTime() % 20 == 0) {
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.FIRE_AMBIENT, 1.0F + this.level.random.nextFloat(), this.level.random.nextFloat() * 0.7F + 0.3F));
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F));
                                    serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, (double) this.worldPosition.getX() + 0.5D, (double) this.worldPosition.getY() + 1.15D, (double) this.worldPosition.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
                                }

                                if (this.currentTime >= recipe.getSoulCost()) {
                                    this.stopBrazier(true);
                                } else {
                                    this.updateRecipe(this.level);
                                }
                            }
                        }
                    }
                } else {
                    if (!this.level.isClientSide) {
                        this.stopBrazier(false);
                    }
                }
            } else {
                if (!this.level.isClientSide) {
                    this.stopBrazier(false);
                }
            }
            this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(NecroBrazierBlock.LIT, flag), 3);
        }
    }

public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
        }

        if (!this.isNoAi() && !this.isBaby()) {
            if (this.ringBufferIndex < 0) {
                for (int i = 0; i < this.ringBuffer.length; ++i) {
                    this.ringBuffer[i][0] = this.getYRot();
                    this.ringBuffer[i][1] = this.getY();
                }
            }
            this.ringBufferIndex++;
            if (this.ringBufferIndex == this.ringBuffer.length) {
                this.ringBufferIndex = 0;
            }
            // Just replaced the contents of Mth.interpolateAngle with the returned formula. Why even is this shit @OnlyIn(Client)???
            this.ringBuffer[this.ringBufferIndex][0] = this.yRotO + 0.5F * Mth.wrapDegrees(this.getYRot() - this.yRotO);
            this.ringBuffer[ringBufferIndex][1] = this.getY();
            Vector3d[] avector3d = new Vector3d[this.whale_parts.length];

            for (int j = 0; j < this.whale_parts.length; ++j) {
                this.whale_parts[j].collideWithNearbyEntities();
                avector3d[j] = new Vector3d(this.whale_parts[j].getX(), this.whale_parts[j].getY(), this.whale_parts[j].getZ());
            }
            float f15 = (float) (this.getMovementOffsets(5, 1.0F)[1] - this.getMovementOffsets(10, 1.0F)[1]) * 10.0F * ((float) Math.PI / 180F);
            float f16 = Mth.cos(f15);
            float yaw = this.getYRot() * ((float) Math.PI / 180F);
            float pitch = this.getXRot() * ((float) Math.PI / 180F);
            float f3 = Mth.sin(yaw) * (1 - Math.abs(this.getXRot() / 90F));
            float f18 = Mth.cos(yaw) * (1 - Math.abs(this.getXRot() / 90F));

            double[] adouble = this.getMovementOffsets(5, 1.0F);

            float var = 1;
            for (int k = 0; k < getMultiparts(); ++k) {
                EntityWhalePart whale_part = this.whale_parts[k];

                double[] adouble1 = this.getMovementOffsets(5 + k * 2, 1.0F);
                float f7 = yaw + (float) Mth.wrapDegrees(adouble1[0] - adouble[0]) * ((float) Math.PI / 180F);
                float f20 = Mth.sin(f7) * (1 - Math.abs(this.getXRot() / 90F));
                float f21 = Mth.cos(f7) * (1 - Math.abs(this.getXRot() / 90F));
                float offset = k % 2 == 0 ? -1 : 1;
                if (k % 2 == 0) {
                    var++;
                }
                float f23 = var * 1.5F * offset;
                float value = Mth.clamp(pitch * k, (float)Math.toRadians(-40), (float)Math.toRadians(40));
                this.setPartPosition(whale_part, -(f3 * 0.5 + f20 * f23) * f16, value * -offset, (f18 * 0.5 + f21 * f23) * f16);
                this.whale_parts[k].xo = avector3d[k].x;
                this.whale_parts[k].yo = avector3d[k].y;
                this.whale_parts[k].zo = avector3d[k].z;
                this.whale_parts[k].xOld = avector3d[k].x;
                this.whale_parts[k].yOld = avector3d[k].y;
                this.whale_parts[k].zOld = avector3d[k].z;
            }
        }
        if (this.level.isClientSide && this.isFeeding() && this.gulpProgress < 50) {
            this.gulpProgress += 1;
        } else if (this.level.isClientSide && !this.isFeeding() && this.gulpProgress > 0) {
            this.gulpProgress -= 1;
        }
    }

@Override
    public void tickClient(ICommonArmorHandler armorHandler, boolean isEnabled) {
        if (!isEnabled) return;

        int rangeUpgrades = armorHandler.getUpgradeCount(EquipmentSlot.HEAD, ModUpgrades.RANGE.get());
        Player player = armorHandler.getPlayer();

        // check for filter change and recompile filter if necessary
        ItemStack helmetStack = player.getItemBySlot(EquipmentSlot.HEAD);
        String filterStr = helmetStack.isEmpty() ? "" : PneumaticArmorItem.getEntityFilter(helmetStack);
        if (!entityFilter.toString().equals(filterStr)) {
            EntityFilter newFilter = EntityFilter.fromString(filterStr);
            if (newFilter != null) {
                entityFilter = newFilter;
            }
        }

        // find applicable entities and create/update render targets for them as needed
        double entityTrackRange = ENTITY_TRACKING_RANGE + rangeUpgrades * PneumaticValues.RANGE_UPGRADE_HELMET_RANGE_INCREASE_ENTITY;
        AABB bbBox = getAABBFromRange(player, rangeUpgrades);
        List<Entity> entities = armorHandler.getPlayer().level().getEntitiesOfClass(Entity.class, bbBox,
                new EntityTrackerSelector(player, entityFilter, entityTrackRange));
        for (Entity entity : entities) {
            RenderEntityTarget target = targets.get(entity.getId());
            if (target != null) {
                target.ticksExisted = Math.abs(target.ticksExisted); // cancel lost targets
            } else {
                targets.put(entity.getId(), new RenderEntityTarget(entity));
            }
        }

        // prune no-longer-applicable entities from the render target list
        IntList toRemove = new IntArrayList();
        targets.forEach((entityId, target) -> {
            if (!target.entity.isAlive() || player.distanceTo(target.entity) > entityTrackRange + 5 || !entityFilter.test(target.entity)) {
                if (target.ticksExisted > 0) {
                    target.ticksExisted = -60;
                } else if (target.ticksExisted == -1) {
                    toRemove.add(entityId.intValue());
                }
            }
        });
        toRemove.forEach(targets::remove);

        // handle tick logic for every valid render target
        List<Component> text = new ArrayList<>();
        for (RenderEntityTarget target : targets.values()) {
            boolean wasNegative = target.ticksExisted < 0;
            target.ticksExisted += armorHandler.getSpeedFromUpgrades(EquipmentSlot.HEAD);
            if (target.ticksExisted >= 0 && wasNegative) target.ticksExisted = -1;
            target.tick();
            if (target.isLookingAtTarget) {
                if (target.isInitialized()) {
                    text.add(target.entity.getDisplayName().copy().withStyle(ChatFormatting.GRAY));
                    text.addAll(target.getEntityText());
                } else {
                    text.add(xlate("pneumaticcraft.entityTracker.info.acquiring").withStyle(ChatFormatting.GRAY));
                }
            }
        }
        if (text.isEmpty()) {
            String f = entityFilter.toString();
            text.add(xlate("pneumaticcraft.gui.entityFilter").append(": " + (f.isEmpty() ? "-" : f)));
        }
        entityTrackInfo.setText(text);
    }

@Override
    public void render(MobJarTile pBlockEntity, float pPartialTick, PoseStack pPoseStack, MultiBufferSource pBufferSource, int pPackedLight, int pPackedOverlay) {
        Entity entity = pBlockEntity.getEntity();
        if (entity == null)
            return;
        float f = 0.53125F;
        float f1 = Math.max(entity.getBbWidth(), entity.getBbHeight());

        if ((double) f1 > 1.0d) {
            f /= f1 * 1.0;
        }
        if (entity instanceof LightningBolt bolt) {
            if (bolt.level.getGameTime() % 20 == 0)
                bolt.seed = ClientInfo.ticksInGame;
            f = 0.0075f;
        }
        AtomicReference<Vec3> adjustedScale = new AtomicReference<>(new Vec3(0, 0, 0));
        AtomicReference<Vec3> adjustedTranslation = new AtomicReference<>(new Vec3(0, 0, 0));
        AtomicReference<Boolean> shouldParticlaTick = new AtomicReference<>(false);
        JarBehaviorRegistry.forEach(entity, jarBehavior -> {
            Vec3 customScale = jarBehavior.scaleOffset(pBlockEntity);
            adjustedScale.set(adjustedScale.get().add(customScale));
            adjustedTranslation.set(adjustedTranslation.get().add(jarBehavior.translate(pBlockEntity)));
            if (jarBehavior.shouldUsePartialTicks(pBlockEntity))
                shouldParticlaTick.set(true);
        });

        Vec3 scale = new Vec3(f, f, f).multiply(adjustedScale.get().add(1, 1, 1));
        Vec3 translate = new Vec3(0.5, 0, 0.5).add(adjustedTranslation.get());
        pPoseStack.translate(translate.x, translate.y, translate.z);
        pPoseStack.scale((float) scale.x, (float) scale.y, (float) scale.z);

        Direction direction = pBlockEntity.getBlockState().getValue(MobJar.FACING);
        if (direction == Direction.EAST) {
            pPoseStack.mulPose(Axis.ZP.rotationDegrees(90.0F));
        } else if (direction == Direction.WEST) {
            pPoseStack.mulPose(Axis.ZP.rotationDegrees(-90.0F));
        } else if (direction == Direction.NORTH) {
            pPoseStack.mulPose(Axis.XP.rotationDegrees(90.0F));
        } else if (direction == Direction.SOUTH) {
            pPoseStack.mulPose(Axis.XP.rotationDegrees(-90.0F));
        } else if (direction == Direction.DOWN) {
            pPoseStack.translate(0, entity.getBbHeight() + 0.75, 0);
        }
        pPoseStack.mulPose(pBlockEntity.getBlockState().getValue(MobJar.FACING).getRotation());
        entity.setDeltaMovement(0, 0, 0);
        if (shouldParticlaTick.get()) {
            entity.xo = entity.getX();
            entity.yo = entity.getY();
            entity.zo = entity.getZ();
            entity.xRotO = entity.xRot;
            entity.yRotO = entity.yRot;
            if (entity instanceof LivingEntity livingEntity) {
                livingEntity.yBodyRotO = livingEntity.yBodyRot;
                livingEntity.yHeadRotO = livingEntity.yHeadRot;
                // TODO: readd old animation speed for allay?
            }
        } else {
            pPartialTick = 0;
        }

        this.entityRenderer.render(entity, 0.0D, 0.0D, 0.0D, 0.0F, pPartialTick, pPoseStack, pBufferSource, pPackedLight);
        for (Entity entity1 : entity.getPassengers()) {
            this.entityRenderer.render(entity1, 0.0D, 0.0D, 0.0D, 0.0F, pPartialTick, pPoseStack, pBufferSource, pPackedLight);
        }
    }

@Override
	public void inventoryTick(ItemStack stack, Level world, Entity entity, int itemSlot, boolean isSelected) {
		if (entity instanceof Player && !world.isClientSide) {
			Player player = (Player) entity;
			List<Monster> genericMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(player, abilityRange.getValue()));

			if (SuperpositionHandler.isTheCursedOne(player) && Inventory.isHotbarSlot(itemSlot) && !player.getCooldowns().isOnCooldown(this)) {
				Monster oneWatched = null;

				for (Monster monster : genericMobs) {
					if (SuperpositionHandler.doesObserveEntity(player, monster) && !this.isExcluded(monster)) {
						oneWatched = monster;
						break;
					}
				}

				//System.out.println("The One: " + oneWatched);

				if (oneWatched != null && oneWatched.isAlive()) {
					final Monster theOne = oneWatched;
					Vector3 vec = Vector3.fromEntityCenter(theOne);
					List<Monster> surroundingMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(theOne, enrageRange.getValue()), (living) -> { return living.isAlive() && theOne.hasLineOfSight(living); });
					Monster closestMonster = SuperpositionHandler.getClosestEntity(surroundingMobs, (monster) -> monster != theOne, vec.x, vec.y, vec.z);

					//System.out.println("Closest monster: " + closestMonster);

					if (closestMonster != null) {
						this.setAttackTarget(theOne, closestMonster);
						theOne.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 300, 0, false, true));
						theOne.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 300, 1, false, false));
						theOne.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 300, 1, false, false));
						//theOne.addPotionEffect(new MobEffectInstance(MobEffects., 400, 1, false, true));

						for (Monster otherMonster : surroundingMobs) {
							this.setAttackTarget(otherMonster, theOne);
						}

						player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.ELDER_GUARDIAN_CURSE, SoundSource.HOSTILE, 1.0F, 1.0F);

						if (player instanceof ServerPlayer) {
							ServerPlayer serverPlayer = (ServerPlayer) player;
							EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(theOne.getX(), theOne.getY(), theOne.getZ(), 64, theOne.level().dimension())), new PacketGenericParticleEffect(theOne.getX(), theOne.getEyeY(), theOne.getZ(), 0, false, Effect.GUARDIAN_CURSE));
						}

						player.getCooldowns().addCooldown(this, abilityCooldown.getValue());
					}
				}

			}

			for (Monster monster : genericMobs) {
				if (monster instanceof Guardian && monster.getClass() != ElderGuardian.class) {
					final Guardian guardian = (Guardian) monster;

					if (guardian.getTarget() == null) {
						List<Monster> surroundingMobs = player.level().getEntitiesOfClass(Monster.class, SuperpositionHandler.getBoundingBoxAroundEntity(guardian, 12), (living) -> { return living.isAlive() && guardian.hasLineOfSight(living); });
						Monster closestMonster = SuperpositionHandler.getClosestEntity(surroundingMobs, (checked) -> { return !(checked instanceof Guardian); }, guardian.getX(), guardian.getY(), guardian.getZ());

						if (closestMonster != null) {
							this.setAttackTarget(guardian, closestMonster);
						}
					}
				}
			}

		}
	}

@Override
	protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hitResult) {
		if (level.isClientSide())
			return ItemInteractionResult.SUCCESS;
		if (player instanceof FakePlayer)
			return ItemInteractionResult.SUCCESS;

		BlockEntity blockEntity = level.getBlockEntity(pos.relative(state.getValue(FACING)));
		if (blockEntity == null)
			return ItemInteractionResult.FAIL;
		IItemHandler targetInv = level.getCapability(ItemHandler.BLOCK, blockEntity.getBlockPos(), null);
		if (targetInv == null)
			return ItemInteractionResult.FAIL;

		FilteringBehaviour filter = BlockEntityBehaviour.get(level, pos, FilteringBehaviour.TYPE);
		if (filter == null)
			return ItemInteractionResult.FAIL;

		Inventory inventory = player.getInventory();
		List<ItemStack> failedInsertions = new ArrayList<>();
		boolean anyInserted = false;
		boolean depositItemInHand = !player.isShiftKeyDown();

		if (!depositItemInHand && stack.is(Items.TOOLS_WRENCH))
			return ItemInteractionResult.PASS_TO_DEFAULT_BLOCK_INTERACTION;

		for (int i = 0; i < inventory.items.size(); i++) {
			if (Inventory.isHotbarSlot(i) != depositItemInHand)
				continue;
			if (depositItemInHand && i != inventory.selected)
				continue;
			ItemStack item = inventory.getItem(i);
			if (item.isEmpty())
				continue;
			if (!item.getItem()
				.canFitInsideContainerItems() && !PackageItem.isPackage(item))
				continue;
			if (!filter.getFilter()
				.isEmpty() && !filter.test(item))
				continue;

			ItemStack remainder = ItemHandlerHelper.insertItemStacked(targetInv, item, true);
			if (remainder.getCount() == item.getCount())
				continue;

			ItemStack extracted = inventory.removeItem(i, item.getCount() - remainder.getCount());
			remainder = ItemHandlerHelper.insertItemStacked(targetInv, extracted, false);
			anyInserted = true;

			// remainder might not be empty in itemhandler edge cases
			if (!remainder.isEmpty())
				failedInsertions.add(remainder);
		}

		failedInsertions.forEach(inventory::placeItemBackInInventory);

		if (!anyInserted)
			return ItemInteractionResult.SUCCESS;

		AllSoundEvents.ITEM_HATCH.playOnServer(level, pos);
		level.setBlockAndUpdate(pos, state.setValue(OPEN, true));
		level.scheduleTick(pos, this, 10);

		CreateLang.translate(depositItemInHand ? "item_hatch.deposit_item" : "item_hatch.deposit_inventory")
			.sendStatus(player);
		return ItemInteractionResult.SUCCESS;
	}

@Nullable
	private Path findPath(PathPoint start, PathPoint end, float range){

		start.totalPathDistance = 0.0F;
		start.distanceToNext = start.distanceManhattan(end);
		start.distanceToTarget = start.distanceToNext;
		this.path.clearPath();
		this.closedSet.clear();
		this.path.addPoint(start);
		PathPoint pathpoint = start;
		int i = 0;

		while(!this.path.isPathEmpty()){

			++i;

			// This is the offending line - timeout limit changed from 200 to 5000.
			if(i >= 5000){
				break;
			}

			PathPoint pathpoint1 = this.path.dequeue();

			if(pathpoint1.equals(end)){
				pathpoint = end;
				break;
			}

			if(pathpoint1.distanceManhattan(end) < pathpoint.distanceManhattan(end)){
				pathpoint = pathpoint1;
			}

			pathpoint1.visited = true;
			int j = this.nodeProcessor.findPathOptions(this.pathOptions, pathpoint1, end, range);

			for(int k = 0; k < j; ++k){

				PathPoint pathpoint2 = this.pathOptions[k];
				float f = pathpoint1.distanceManhattan(pathpoint2);
				pathpoint2.distanceFromOrigin = pathpoint1.distanceFromOrigin + f;
				pathpoint2.cost = f + pathpoint2.costMalus;
				float f1 = pathpoint1.totalPathDistance + pathpoint2.cost;

				if(pathpoint2.distanceFromOrigin < range
						&& (!pathpoint2.isAssigned() || f1 < pathpoint2.totalPathDistance)){

					pathpoint2.previous = pathpoint1;
					pathpoint2.totalPathDistance = f1;
					pathpoint2.distanceToNext = pathpoint2.distanceManhattan(end) + pathpoint2.costMalus;

					if(pathpoint2.isAssigned()){
						this.path.changeDistance(pathpoint2, pathpoint2.totalPathDistance + pathpoint2.distanceToNext);
					}else{
						pathpoint2.distanceToTarget = pathpoint2.totalPathDistance + pathpoint2.distanceToNext;
						this.path.addPoint(pathpoint2);
					}
				}
			}
		}

		if(pathpoint == start){
			return null;
		}else{
			Path path = this.createEntityPath(start, pathpoint);
			return path;
		}
	}

private void afterRendering() {
        if (irisTarget != null) {
            compositeToShaderPack();
            return;
        }
        if (lateLayer) {
            parkLateLayer();
            return;
        }
        var mainTarget = UISurface.currentTarget();
        var lastViewport = PositionedRect.of(GlStateManager.Viewport.x(), GlStateManager.Viewport.y(), GlStateManager.Viewport.width(), GlStateManager.Viewport.height());
        var background = UISurface.currentTarget();
        var hasDifferentViewPort = lastViewport.position.x != 0 ||
                lastViewport.position.y != 0 ||
                lastViewport.size.width != background.width ||
                lastViewport.size.height != background.height;
        // setup view port
        if (hasDifferentViewPort) {
            RenderSystem.viewport(0, 0, background.width, background.height);
        }

        var doBloom = wantsBloom();
        // Bloom and the custom effect chain want DIFFERENT timing, and the opaque/translucent queues
        // own separate pipelines that may both build in one frame:
        //
        //  - BLOOM must run on EVERY build. It is an HDR effect, and DRAW_TARGET (RGBA16F) is the only
        //    place this build's overbright exists: writing back to the main target (RGBA8) clamps it to
        //    1, and the bright pass keeps only luma > Threshold (1 by default). So a build that skips
        //    bloom can never get it back — its highlights are already gone by the next build.
        //  - THE EFFECT CHAIN must run once, on the LAST build. Effects are whole-frame image
        //    operations; running them per build applies them twice.
        //
        // Treating both the same is what broke this: whichever queue built first consumed the frame,
        // so a single opaque particle could take the bloom away from every translucent one.
        //
        // A late layer moves the chain again: it is composited after renderLevel returns, so
        // consuming here would post-process a frame that does not contain those FX yet.
        RenderTarget outputTarget = isLastBuildThisFrame() && !deferChainToComposite()
                ? PostEffectStack.currentSink().consumeAndExecute(DRAW_TARGET, doBloom)
                : (doBloom ? PhotonPostProcessing.postTarget(DRAW_TARGET) : DRAW_TARGET);

        // a sub-viewport means this scene is embedded inside a larger frame (the editor scene view):
        // the chain processed the whole frame, but the write-back must not touch pixels outside the
        // viewport — UI drawn before the scene would get post-processed too
        int[] uiScissorBox = null;
        if (hasDifferentViewPort) {
            uiScissorBox = new int[4];
            GL11.glGetIntegerv(GL11.GL_SCISSOR_BOX, uiScissorBox);
            RenderSystem.enableScissor(lastViewport.position.x, lastViewport.position.y,
                    lastViewport.size.width, lastViewport.size.height);
        }

        SceneBlit.writeBack(outputTarget, mainTarget);

        // restore the UI clip state the scene render suspended (the box outlives the disabled test)
        if (uiScissorBox != null) {
            RenderSystem.disableScissor();
            GlStateManager._scissorBox(uiScissorBox[0], uiScissorBox[1], uiScissorBox[2], uiScissorBox[3]);
        }

        // restore view port
        if (hasDifferentViewPort){
            RenderSystem.viewport(lastViewport.position.x, lastViewport.position.y, lastViewport.size.width, lastViewport.size.height);
        }

        RenderSystem.setShader(GameRenderer::getParticleShader);
    }

public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.tickCount % 600 == 0) {
                if (!this.getWantsToGrow())
                    this.setWantsToGrow(this.wantsToGrow());
                if (this.wantsToLayEggs() && !this.isMale()) {
                    for(int k = 0; k < 3; ++k) {
                        BlockState state = ModBlock.EGG_SPITTER.get().defaultBlockState();
                        BlockPos blockpos = this.blockPosition().offset(this.random.nextInt(3) - 1, 1 - this.random.nextInt(3), this.random.nextInt(3) - 1);
                        if (this.getLevel().isInWorldBounds(blockpos) && this.getLevel().getBlockState(blockpos).is(Blocks.WATER) && state.canSurvive(this.getLevel(), blockpos)) {
                            this.getLevel().setBlock(blockpos, state, 2);
                            this.setEggStatus(false);
                        }
                    }
                }
            }

            // Boosted Regeneration
            if (this.level.getGameTime() % 500 == 0) {
                this.addHunger(-3);
                if (!this.isStarving()) {
                    this.heal(2.0F);
                }
            }

            // Random idle animations
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                if (this.getCommandInt() == 0) {
                    int i = this.random.nextInt(3000);
                    if (i == 0 && !this.isInWater() && this.isNotMoving() && this.canMove() && this.isActive()) {
                        this.getNavigation().stop();
                        this.setSitting(true);
                    }
                    else if ((i == 1 || this.isInWater()) && this.isSitting() && this.getCommandInt() < 2) {
                        this.setSitting(false);
                    }
                    else if (i < 25 && !this.isInWater() && !this.isBaby()) {
                        this.setAnimation(IDLE_TALK);
                    }
                    else if (i > 2980 && !this.isInWater() && !this.isBaby() && this.canMove() && this.isNotMoving()) {
                        this.setAnimation(IDLE_WATCH);
                    }
                }
            }
            if (this.getTarget() != null && (this.getAnimation() == ATTACK_SPIT || this.isBaby())) {
                this.setDeltaMovement(this.getDeltaMovement().scale(0.6F));
                if (this.getAnimationTick() == 14)
                    performRangedAttack(this.getTarget(), 0.5F);
            }
            this.setAngry(this.getTarget() != null);
        }
        if (this.getAnimation() == ANIMATION_EAT && (this.getAnimationTick() == 10 || this.getAnimationTick() == 20 || this.getAnimationTick() == 30)) {
            this.playSound(SoundEvents.HORSE_EAT,1.5F, 0.8F);
        }
        if (this.getAnimation() == ATTACK_MAUL_RIGHT && this.getAnimationTick() == 10) {
            this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP,1.5F, 0.8F);
        }
        if (this.getAnimation() == IDLE_TALK && this.getAnimationTick() == 1 && this.getAmbientSound() != null) {
            this.playSound(this.getAmbientSound(), this.getSoundVolume(), this.getVoicePitch());
        }
        if (this.level.isClientSide && this.isAngry() && this.aggroProgress < 40) {
            this.aggroProgress++;
        } else if (this.level.isClientSide && !this.isAngry() && this.aggroProgress > 0) {
            this.aggroProgress--;
        }
        super.aiStep();
    }

private void startNext() {
        index++;
        tries = 0;
        if (instructions.size() == index) {
            if (shouldLoop) {
                syncWithClients();
                index = 0;
            } else {
                stop();
                return;
            }
        }
        endTick = 0;
        delayTick = 0;
        Instruction current = instructions.get(index);
        if (current instanceof Instruction.MoveTo moveTo) {
            mob.getNavigation().moveTo(moveTo.target.getX(), moveTo.target.getY(), moveTo.target.getZ(), 1);
        } else if (current instanceof Instruction.FlyTo flyTo) {
            if (mob instanceof PrehistoricFlying flying) {
                flying.moveTo(Vec3.atCenterOf(flyTo.target), false, true);
            }
        } else if (current instanceof Instruction.FlyLand flyLand) {
            if (mob instanceof PrehistoricFlying flying) {
                flying.moveTo(Vec3.atCenterOf(flyLand.target), true, true);
            }
        } else if (current instanceof Instruction.TeleportTo teleportTo) {
            mob.getNavigation().stop();
            mob.moveTo(teleportTo.target, teleportTo.rotation, mob.getXRot());
            mob.setYHeadRot(teleportTo.rotation);
            endTick = mob.level.getGameTime() + 5;
        } else if (current instanceof Instruction.AttachTo attachTo) {
            attached = false;
            mob.getNavigation().moveTo(attachTo.target.getX(), attachTo.target.getY(), attachTo.target.getZ(), 1);
            if (mob instanceof Meganeura meganeura) {
                Direction face = attachTo.direction;
                float rad = mob.getBbWidth() / 2;
                Vec3 pos = new Vec3(attachTo.location.x + rad * face.getStepX(), attachTo.location.y, attachTo.location.z + rad * face.getStepZ());
                meganeura.getAttachSystem().setAttachTarget(attachTo.target, face, pos);
            }
        } else if (current instanceof Instruction.LeapLand leapLand) {
            mob.getNavigation().moveTo(leapLand.location.x, leapLand.location.y, leapLand.location.z, 1);
        } else if (current instanceof Instruction.LeapAttack leapAttack) {
            Entity target = mob.level.getEntity(leapAttack.targetId);
            if (target instanceof LivingEntity && mob instanceof PrehistoricLeaping leaping) {
                mob.getNavigation().moveTo(target, 1);
                mob.lookAt(target, 120, 10);
                mob.setTarget(leaping);

               // leaping.getLeapSystem().setLeapTarget(target);
            }
        } else if (current instanceof Instruction.Idle idle) {
            endTick = mob.level.getGameTime() + idle.duration;
        } else if (current instanceof Instruction.PlayAnim playAnim) {
            if (playAnim.timeBased) {
                animCount = mob.level.getGameTime() + playAnim.count * 20L;
                activeAnim = mob.getAnimationLogic().forceAnimation(playAnim.controller, mob.getAllAnimations().get(playAnim.name), AnimationCategory.IDLE, 1, 5,true);
            } else {
                animCount = playAnim.count;
                activeAnim = mob.getAnimationLogic().forceAnimation(playAnim.controller, mob.getAllAnimations().get(playAnim.name), AnimationCategory.IDLE, 1,5,false);
            }
        } else if (current instanceof Instruction.Sleep sleep) {
            endTick = mob.level.getGameTime() + sleep.duration;
            mob.sleepSystem.setDisabled(false);
            mob.sleepSystem.setSleeping(true);
            mob.sleepSystem.setSleepForced(true);
        }
    }

public void serverTick(Level level, @NotNull BlockPos pos) {
        if (isActivated(level, pos)) {
            if (level instanceof ServerLevel) {
                if (this.spawnDelay == -1) {
                    this.resetTimer();
                }

                if (this.spawnDelay > 0) {
                    --this.spawnDelay;
                    return;
                }


                if ((level.getGameTime()) > this.spawnedLast + 24000) {
                    this.spawnedToday = 0;
                    this.flag = true;
                } else if (this.spawnedToday >= dailyLimit) {
                    this.flag = false;
                }
                if (!this.flag) {
                    return;
                }

                boolean flag1 = false;

                for (int i = 0; i < this.spawnCount; ++i) {
                    T entity = this.getEntityType().create(level, EntitySpawnReason.SPAWNER);

                    if (entity == null) {
                        break;
                    }

                    int j = level.getEntitiesOfClass(entity.getClass(), getSpawningBox(pos).inflate(5)).size();

                    if (j >= this.maxNearbyEntities) {
                        this.resetTimer();
                        break;
                    }

                    if (limitType != null) {
                        @Nullable
                        NaturalSpawner.SpawnState densityManager = ((ServerLevel) level).getChunkSource().getLastSpawnState();
                        try {
                            if (densityManager != null && !((ISpawnState) densityManager).vampirism$canSpawnForCategoryLocalI(limitType, new ChunkPos(pos.getX() / 16, pos.getZ() / 16))) {
                                this.resetTimer();
                                break;
                            }
                        } catch (NoSuchMethodError e) {
                            //Workaround for https://github.com/TeamLapen/Vampirism/issues/983
                            //Maybe remove when https://github.com/magmafoundation/Magma-1.16.x/issues/154 is solved
                        }

                    }

                    if (UtilLib.spawnEntityInWorld((ServerLevel) level, getSpawningBox(pos), entity, 1, Collections.emptyList(), EntitySpawnReason.SPAWNER)) {
                        onSpawned(entity);
                        flag1 = true;
                    }
                }
                if (flag1) {
                    this.resetTimer();
                    this.spawnedToday++;
                    this.spawnedLast = level.getGameTime();
                }
            }
        }
    }

@Override
		public void tick() {
			super.tick();

			if (getPassengers().isEmpty() && !level().isClientSide) {
				discard();
				return;
			}

			boolean isItem = getPassengers().stream().allMatch(ItemEntity.class::isInstance);
			if (!isItem && tickCount % 30 == 0) {
				playSound(BotaniaSounds.lightRelay, 0.25F, (float) Math.random() * 0.3F + 0.7F);
			}
			if (!isItem && tickCount % 10 == 0) {
				gameEvent(GameEvent.ELYTRA_GLIDE);
			}

			BlockPos pos = blockPosition();
			BlockPos exitPos = getExitPos();

			if (!level().isClientSide && pos.equals(exitPos)) {
				boolean done = true;
				BlockEntity tile = level().getBlockEntity(pos);
				if (tile instanceof LuminizerBlockEntity relay) {
					BlockState state = level().getBlockState(pos);
					if (state.is(BotaniaBlocks.lightRelayDetector)) {
						level().setBlockAndUpdate(pos, state.setValue(BlockStateProperties.POWERED, true));
						level().scheduleTick(pos, state.getBlock(), 2);
					}

					BlockPos bind = relay.getNextDestination();
					if (bind != null && relay.isValidBinding()) {
						setExit(bind);
						done = false;
					}
				}

				if (done) {
					for (Entity e : getPassengers()) {
						e.stopRiding();
					}
					discard();
					return;
				}
			}
			Vec3 thisVec = position();
			Vec3 motVec = thisVec.reverse().add(exitPos.getX() + 0.5, exitPos.getY() + 0.5, exitPos.getZ() + 0.5).normalize().scale(0.5);

			int color;

			int count = 4;
			for (int i = 0; i < count; i++) {
				color = Mth.hsvToRgb(tickCount / 36F + 1F / count * i, 1F, 1F);
				double rad = Math.PI * 2.0 / count * i + tickCount / Math.PI;
				double cos = Math.cos(rad);
				double sin = Math.sin(rad);
				double s = 0.4;

				int r = (color >> 16) & 0xFF;
				int g = (color >> 8) & 0xFF;
				int b = color & 0xFF;
				SparkleParticleData data = SparkleParticleData.sparkle(1.2F, r / 255F, g / 255F, b / 255F, 10);
				level().addParticle(data, getX() + cos * s, getY() - 0.5, getZ() + sin * s, 0, 0, 0);
			}

			setPos(getX() + motVec.x, getY() + motVec.y, getZ() + motVec.z);
		}

public boolean hurt(DamageSource pSource, float pAmount) {
        if (!this.level().isClientSide && !this.isRemoved()) {
            if (pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                this.discard();
                return false;
            } else if (!this.isInvulnerableTo(pSource) && !this.invisible) {
                if (pSource.is(DamageTypeTags.IS_EXPLOSION)) {
                    this.discard();
                    return false;

                    //todo change to custom tag
                } else if (pSource.is(DamageTypeTags.IGNITES_ARMOR_STANDS)) {
                    if (this.isOnFire()) {
                        this.causeDamage(pSource, 0.15F);
                    } else {
                        this.setSecondsOnFire(5);
                    }

                    return false;

                    //todo change to custom tag
                } else if (pSource.is(DamageTypeTags.BURNS_ARMOR_STANDS) && this.getHealth() > 0.5F) {
                    this.causeDamage(pSource, 4.0F);
                    return false;
                } else {
                    boolean flag = pSource.getDirectEntity() instanceof AbstractArrow;
                    boolean flag1 = flag && ((AbstractArrow)pSource.getDirectEntity()).getPierceLevel() > 0;
                    boolean flag2 = "player".equals(pSource.getMsgId());
                    if (!flag2 && !flag) {
                        return false;
                    } else {
                        Entity entity = pSource.getEntity();
                        if (entity instanceof Player) {
                            Player player = (Player)entity;
                            if (!player.getAbilities().mayBuild) {
                                return false;
                            }
                        }

                        if (pSource.isCreativePlayer()) {
                            this.playBrokenSound();
                            this.showBreakingParticles();
                            this.remove(RemovalReason.KILLED);
                            return flag1;
                        } else {
                            long i = this.level().getGameTime();
                            if (i - this.lastHit > 5L && !flag) {
                                this.level().broadcastEntityEvent(this, (byte)32);
                                this.gameEvent(GameEvent.ENTITY_DAMAGE, pSource.getEntity());
                                this.lastHit = i;
                            } else {
                                this.brokenByPlayer(pSource);
                                this.showBreakingParticles();
                                this.kill();
                            }

                            return true;
                        }
                    }
                }
            } else {
                return false;
            }
        } else {
            return false;
        }
    }

public void directFromPlayer(float rotationYaw, float rotationPitch, boolean loadChunk, Entity over) {
        final Entity owner = this.getOwner();
        if (owner != null && this.distanceTo(owner) > 150) {
            returnControlTime = 100;
        }
        if (Math.abs(xo - this.getX()) > 0.1F || Math.abs(yo - this.getY()) > 0.1F || Math.abs(zo - this.getZ()) > 0.1F) {
            stillTicksCounter = 0;
        } else {
            stillTicksCounter++;
        }
        int stillTPthreshold = AMConfig.falconryTeleportsBack ? 200 : 6000;
        this.setOrderedToSit(false);
        this.setLaunched(true);
        if (owner != null && (returnControlTime > 0 && AMConfig.falconryTeleportsBack || stillTicksCounter > stillTPthreshold && this.distanceTo(owner) > 30)) {
            this.copyPosition(owner);
            returnControlTime = 0;
            stillTicksCounter = 0;
            launchTime = Math.max(launchTime, 12000);
        }
        if (!this.level().isClientSide) {
            if (returnControlTime > 0 && owner != null) {
                this.getLookControl().setLookAt(owner, 30, 30);
            } else {
                this.yBodyRot = rotationYaw;
                this.setYRot(rotationYaw);
                this.yHeadRot = rotationYaw;
                this.setXRot(rotationPitch);
            }
            if (rotationPitch < 10 && this.onGround()) {
                this.setFlying(true);
            }
            final float yawOffset = rotationYaw + 90;
            final float rad = 3F;
            final float speed = 1.2F;
            if (returnControlTime > 0) {
                this.getMoveControl().setWantedPosition(owner.getX(), owner.getY() + 10, owner.getZ(), speed);
            } else {
                this.getMoveControl().setWantedPosition(this.getX() + rad * 1.5F * Math.cos(yawOffset * Mth.DEG_TO_RAD), this.getY() - rad * Math.sin(rotationPitch * Mth.DEG_TO_RAD), this.getZ() + rad * Math.sin(yawOffset * Mth.DEG_TO_RAD), speed);
            }
            if (loadChunk) {
                loadChunkOnServer(this.blockPosition());
            }
            this.setLastHurtByMob(null);
            this.setTarget(null);
            if (over == null) {
                final List<Entity> list = this.level().getEntities(this, this.getBoundingBox().inflate(3.0D), EntitySelector.NO_CREATIVE_OR_SPECTATOR);
                Entity closest = null;
                for (final Entity e : list) {
                    if (closest == null || this.distanceTo(e) < this.distanceTo(closest)) {
                        closest = e;
                    }
                }
                over = closest;
            }
        }
        if (over != null && over != owner && !this.isAlliedTo(over) && canFalconryAttack(over)) {
            if (tackleCapCooldown == 0 && this.distanceTo(over) <= over.getBbWidth() + 4D) {
                this.setTackling(true);
                if (this.distanceTo(over) <= over.getBbWidth() + 2D) {
                    final float speedDamage = (float) Math.ceil(Mth.clamp(this.getDeltaMovement().length() + 0.2, 0, 1.2D) * 3.333);
                    over.hurt(this.damageSources().mobAttack(this), 5 + speedDamage + random.nextInt(2));
                    tackleCapCooldown = 22;
                }
            }
        }
        this.lastPlayerControlTime = 10;
        this.controlledFlag = true;
    }

