        }
        ListTag miscRoomList = compound.getList("MiscRooms", 10);
        this.miscRooms.clear();
        for (int i = 0; i < miscRoomList.size(); ++i) {
            CompoundTag CompoundNBT = miscRoomList.getCompound(i);
            this.miscRooms.add(new BlockPos(CompoundNBT.getInt("X"), CompoundNBT.getInt("Y"), CompoundNBT.getInt("Z")));
        }
        ListTag entrancesList = compound.getList("Entrances", 10);
        this.entrances.clear();
        for (int i = 0; i < entrancesList.size(); ++i) {
            CompoundTag CompoundNBT = entrancesList.getCompound(i);
            this.entrances.put(new BlockPos(CompoundNBT.getInt("X"), CompoundNBT.getInt("Y"), CompoundNBT.getInt("Z")), Direction.from2DDataValue(CompoundNBT.getInt("Facing")));
        }

        ListTag entranceBottomsList = compound.getList("EntranceBottoms", 10);
        this.entranceBottoms.clear();
        for (int i = 0; i < entranceBottomsList.size(); ++i) {
            CompoundTag CompoundNBT = entranceBottomsList.getCompound(i);
            this.entranceBottoms.put(new BlockPos(CompoundNBT.getInt("X"), CompoundNBT.getInt("Y"), CompoundNBT.getInt("Z")), Direction.from2DDataValue(CompoundNBT.getInt("Facing")));
        }
        hiveUUID = compound.getUUID("HiveUUID");
        ListTag nbttaglist1 = compound.getList("Players", 10);
        this.playerReputation.clear();
        for (int j = 0; j < nbttaglist1.size(); ++j) {
            CompoundTag CompoundNBT1 = nbttaglist1.getCompound(j);

            if (CompoundNBT1.hasUUID("UUID")) {
                this.playerReputation.put(CompoundNBT1.getUUID("UUID"), CompoundNBT1.getInt("S"));
            } else {
                //World is never set here, so this will always be offline UUIDs, sadly there is no way to convert this.
                this.playerReputation.put(findUUID(CompoundNBT1.getString("Name")), CompoundNBT1.getInt("S"));
            }
        }
    }

@Nullable
	private Path findPath(PathPoint startPathPoint, PathPoint targetPathPoint, float maxDistance) {
		startPathPoint.totalPathDistance = 0.0F;
		startPathPoint.distanceToNext = this.heuristic.compute(startPathPoint, targetPathPoint, true);
		startPathPoint.distanceToTarget = startPathPoint.distanceToNext;
		this.path.clearPath();
		this.path.addPoint(startPathPoint);
		PathPoint finalPathPoint = startPathPoint;

		int expansions = 0;

		while(!this.path.isPathEmpty()) {
			++expansions;

			if(expansions >= this.maxExpansions) {
				break;
			}

			PathPoint openPathPoint = this.path.dequeue();

			if(openPathPoint.equals(targetPathPoint)) {
				finalPathPoint = targetPathPoint;
				break;
			}

			if(this.heuristic.compute(openPathPoint, targetPathPoint, true) < this.heuristic.compute(finalPathPoint, targetPathPoint, true)) {
				finalPathPoint = openPathPoint;
			}

			openPathPoint.visited = true;
			int numOptions = this.nodeProcessor.findPathOptions(this.pathOptions, openPathPoint, targetPathPoint, maxDistance);

			for(int i = 0; i < numOptions; ++i) {
				PathPoint successorPathPoint = this.pathOptions[i];

				float costHeuristic = this.heuristic.compute(openPathPoint, successorPathPoint, false);

				//distanceFromOrigin corresponds to the total path cost of the evaluation function
				successorPathPoint.distanceFromOrigin = openPathPoint.distanceFromOrigin + costHeuristic;
				successorPathPoint.cost = costHeuristic + successorPathPoint.costMalus;

				float totalSuccessorPathCost = openPathPoint.totalPathDistance + successorPathPoint.cost;

				if(successorPathPoint.distanceFromOrigin < maxDistance && (!successorPathPoint.isAssigned() || totalSuccessorPathCost < successorPathPoint.totalPathDistance)) {
					successorPathPoint.previous = openPathPoint;
					successorPathPoint.totalPathDistance = totalSuccessorPathCost;

					//distanceToNext corresponds to the heuristic part of the evaluation function
					successorPathPoint.distanceToNext = this.heuristic.compute(successorPathPoint, targetPathPoint, true) + successorPathPoint.costMalus;

					if(successorPathPoint.isAssigned()) {
						this.path.changeDistance(successorPathPoint, successorPathPoint.totalPathDistance + successorPathPoint.distanceToNext);
					} else {
						//distanceToTarget corresponds to the evaluation function, i.e. total path cost + heuristic
						successorPathPoint.distanceToTarget = successorPathPoint.totalPathDistance + successorPathPoint.distanceToNext;
						this.path.addPoint(successorPathPoint);
					}
				}
			}
		}

		if(finalPathPoint == startPathPoint) {
			return null;
		} else {
			Path path = this.createPath(startPathPoint, finalPathPoint);
			return path;
		}
	}

@Override
  public void onInventoryTick(IToolStackView tool, ModifierEntry modifier, Level world, LivingEntity holder, int itemSlot, boolean isSelected, boolean isCorrectSlot, ItemStack stack) {
    // overslime increases every 2^(4-level) seconds
    // that is 1 per second at 4 levels, 1 per 8 seconds at 1 level
    // we support max level 6, as that leaves us working with integers
    int level = Math.min(modifier.getLevel(), 6);
    int updateInterval = 5 << (6 - level);

    // don't run if drawing back a bow, prevents losing animation
    // does mean you may end up wasting some fuel, could be as much as 19 lost. So, don't hold your bows for 20 updates?
    if (!world.isClientSide && holder.tickCount % updateInterval == 0 && holder.getUseItem() != stack) {
      // must have overslime and space to fill
      if (OverslimeModule.INSTANCE.getAmount(tool) < OverslimeModule.getCapacity(tool)) {
        // find current fuel info
        ResourceLocation key = modifier.getId();
        FuelInfo info = FuelInfo.read(tool, key);

        // if we have no fuel, try and find some
        boolean neededFuel = info == null;
        // since we will write this to NBT, use game time as that is global
        long time = holder.level().getGameTime();
        if (neededFuel || info.expiration < time) {
          info = null;
          FluidStack fluid = ToolTankHelper.TANK_HELPER.getFluid(tool);
          if (!fluid.isEmpty()) {
            MeltingFuel fuel = MeltingFuelLookup.findFuel(fluid.getFluid());
            if (fuel != null) {
              // scale amount consumed by level
              int amount = fuel.getAmount(fluid.getFluid());
              // scale up fuel duration so we always get the same amount of overslime per fuel bucket
              // if we didn't do this, lower levels would consume way more than higher ones
              // this works out to equivalent to the alloyer/melter at level 4
              // note this does mean changing trait levels multiplies fuel efficiency, but the part swap costs more than just adding a slimeball so its fine
              int duration = fuel.getDuration() * updateInterval / 5;
              // if we don't have a full recipe, use what is left but scale down the duration
              if (amount > fluid.getAmount()) {
                ToolTankHelper.TANK_HELPER.setFluid(tool, FluidStack.EMPTY);
                duration = duration * fluid.getAmount() / amount;
              } else {
                // if we have a complete recipe, just decrease fluid in the tank
                fluid.shrink(amount);
                ToolTankHelper.TANK_HELPER.setFluid(tool, fluid);
              }
              info = new FuelInfo(time + duration, fuel.getRate());
            }
          }
          // store current fuel in NBT for next round if it will last
          // no need to store if it will expire before our next update tick though
          if (info != null && info.expiration >= time + updateInterval) {
            info.write(tool, key);
          } else if (!neededFuel) {
            // no need to remove if we had nothing, saves some hash map modifications
            tool.getPersistentData().remove(key);
          }
        }
        // if we have fuel, increase overslime
        if (info != null) {
          // restore 1 per 10 rate. For the remainder, treat it as a chance
          int restore = info.rate / 10;
          int remainder = info.rate % 10;
          if (remainder > 0 && Modifier.RANDOM.nextInt(10) < remainder) {
            restore++;
          }
          OverslimeModule.INSTANCE.addAmount(tool, restore);
        }
      }
    }
  }

private static void onEffectRender(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
		if (effects.isEmpty() || Minecraft.getInstance().level == null)
			return;

		Tesselator tesselator = Tesselator.getInstance();
		Minecraft mc = Minecraft.getInstance();
		Window window = mc.getWindow();

		long gameTime = mc.level.getGameTime();
		boolean hasExpiredEffects = false;
		PoseStack poseStack = guiGraphics.pose();
		boolean rendered = false;

		RenderSystem.disableDepthTest();
		RenderSystem.depthMask(false);
		RenderSystem.enableBlend();
		RenderSystem.defaultBlendFunc();
		RenderSystem.setShader(GameRenderer::getPositionTexShader);

		for (ScreenImageEffect effect : effects) {
			if (effect.isExpired(gameTime)) {
				hasExpiredEffects = true;

				continue;
			}

			rendered = true;
			float scale = effect.getScale();
			float fadeTime = (effect.getExpiry() - gameTime) / (float)effect.getDuration();
			BufferBuilder buffer = tesselator.begin(VertexFormat.Mode.QUADS, DefaultVertexFormat.POSITION_TEX);

			poseStack.pushPose();
			RenderSystem.setShaderColor(effect.getRed(), effect.getGreen(), effect.getBlue(), effect.getAlpha() * fadeTime);
			RenderUtil.setRenderingTexture(effect.getTexture());

			if (effect.isFullscreen()) {
				buffer.addVertex(0, 0, -90).setUv(0, 0);
				buffer.addVertex(0, window.getGuiScaledHeight(), -90).setUv(0, 1);
				buffer.addVertex(window.getGuiScaledWidth(), window.getGuiScaledHeight(), -90).setUv(1, 1);
				buffer.addVertex(window.getGuiScaledWidth(), 0, -90).setUv(1, 0);
			}
			else {
				poseStack.translate(-256, -256, 0);
				poseStack.scale(scale, scale, scale);
				poseStack.translate(effect.x(), effect.y(), 0);

				Matrix4f pose = poseStack.last().pose();

				buffer.addVertex(pose, 0, 256, -90).setUv(0, 1);
				buffer.addVertex(pose, 256, 256, -90).setUv(1, 1);
				buffer.addVertex(pose, 256, 0, -90).setUv(1, 0);
				buffer.addVertex(pose, 0, 0, -90).setUv(0, 0);
			}

			BufferUploader.drawWithShader(buffer.buildOrThrow());
			poseStack.popPose();
			RenderUtil.resetShaderColour();
		}

		if (rendered)

		RenderSystem.depthMask(true);
		RenderSystem.enableDepthTest();
		RenderSystem.disableBlend();

		if (hasExpiredEffects)
			effects.removeIf(effect -> effect.isExpired(gameTime));
	}

@Override
	@OnlyIn(Dist.CLIENT)
	public float call(@NotNull ItemStack stack, @Nullable ClientLevel worldIn, @Nullable LivingEntity entityIn, int id) {
		if(entityIn == null && !stack.isFramed())
			return 0F;

		if(CompassesWorkEverywhereModule.enableCompassNerf && (!Boolean.TRUE.equals(stack.get(QuarkDataComponents.IS_COMPASS_CALCULATED))))
			return 0F;

		boolean carried = entityIn != null;
		Entity entity = carried ? entityIn : stack.getFrame();

		if(entity == null)
			return 0;

		if(worldIn == null && entity != null && entity.level() instanceof ClientLevel level)
			worldIn = level;

		double angle;

		boolean calculate = false;
		BlockPos target = new BlockPos(0, 0, 0);

		ResourceLocation dimension = worldIn.dimension().location();
		boolean isLodestone = stack.has(DataComponents.LODESTONE_TRACKER);
		BlockPos lodestonePos = isLodestone ? this.getLodestonePosition(worldIn, stack.get(DataComponents.LODESTONE_TRACKER)) : null;

		if(lodestonePos != null) {
			calculate = true;
			target = lodestonePos;
		} else if (!isLodestone) {
			if(dimension.equals(LevelStem.END.location()) && CompassesWorkEverywhereModule.enableEnd)
				calculate = true;
			else if(dimension.equals(LevelStem.NETHER.location()) && CompassesWorkEverywhereModule.isCompassCalculated(stack) && CompassesWorkEverywhereModule.enableNether) {
				boolean set = Boolean.TRUE.equals(stack.get(QuarkDataComponents.IS_POS_SET));
				if(set) {
					int x = stack.get(QuarkDataComponents.NETHER_TARGET_X);
					int z = stack.get(QuarkDataComponents.NETHER_TARGET_Z);
					calculate = true;
					target = new BlockPos(x, 0, z);
				}
			} else if(worldIn.dimensionType().natural()) {
				calculate = true;
				target = getWorldSpawn(worldIn);
			}
		}

		long gameTime = worldIn.getGameTime();
		if(calculate && target != null) {
			double d1 = carried ? entity.getYRot() : getFrameRotation((ItemFrame) entity);
			d1 = Mth.positiveModulo(d1 / 360.0D, 1.0D);
			double d2 = getAngleToPosition(entity, target) / (Math.PI * 2D);

			if(carried) {
				if(normalAngle.needsUpdate(gameTime))
					normalAngle.wobble(gameTime, 0.5D - (d1 - 0.25D));
				angle = d2 + normalAngle.rotation;
			} else
				angle = 0.5D - (d1 - 0.25D - d2);
		} else {
			if(unknownAngle.needsUpdate(gameTime))
				unknownAngle.wobble(gameTime, Math.random());

			angle = unknownAngle.rotation + shift(id);
		}

		return Mth.positiveModulo((float) angle, 1.0F);
	}

@SubscribeEvent
	@OnlyIn(Dist.CLIENT)
	public void onEntityTick(TickEvent.ClientTickEvent event) {
		if (event.phase == Phase.END) {
			try {
				Player player = Minecraft.getInstance().player;

				if (player != null) {
					if (this.clientWorldTicks != player.level().getGameTime()) {
						this.clientWorldTicks = player.level().getGameTime();
						EnigmaticLegacy.PROXY.updateInfinitumCounters();
					}
				}

				/*
				 * This event seems to be the only way to detect player logging out of server
				 * on client side, since PlayerEvent.PlayerLoggedOutEvent seems to only be fired
				 * on the server side.
				 */

				if (player == null) {
					if (OmniconfigWrapper.onRemoteServer) {

						/*
						 * After we log out of remote server, dismiss config values it
						 * sent us and load our own ones from local file.
						 */

						for (OmniconfigWrapper wrapper : OmniconfigWrapper.wrapperRegistry.values()) {

							EnigmaticLegacy.LOGGER.info("Dismissing values of " + wrapper.config.getConfigFile().getName() + " in favor of local config...");

							for (Omniconfig.GenericParameter param : wrapper.retrieveInvocationList()) {
								if (param.isSynchronized()) {
									String oldValue = param.valueToString();
									param.invoke(wrapper.config);

									EnigmaticLegacy.LOGGER.info("Value of '" + param.getId() + "' was restored to '" + param.valueToString() + "'; former server-forced value: " + oldValue);
								}
							}
						}

						OmniconfigWrapper.onRemoteServer = false;

					}
				}


				/*
				 * Handler for displaying queued Toasts on client.
				 */

				EnigmaticEventHandler.DEFERRED_TOASTS.tick(player);

				if (EnigmaticEventHandler.DEFERRED_TOASTS.getCooldown(player) == 1) {
					Minecraft.getInstance().getToasts().addToast(EnigmaticEventHandler.SCHEDULED_TOASTS.get(0));
					EnigmaticEventHandler.SCHEDULED_TOASTS.remove(0);

					if (EnigmaticEventHandler.SCHEDULED_TOASTS.size() > 0) {
						EnigmaticEventHandler.DEFERRED_TOASTS.put(player, 5);
					}
				}

			} catch (Exception ex) {
				// DO NOTHING
			}

		}
	}

@Override
    public InteractionResult useOn(UseOnContext context) {
        ItemStack stack = context.getItemInHand();

        int aoe;
        try (ModuleHost host = DECapabilities.getHost(stack)) {
            assert host != null;
            aoe = host.getModuleData(ModuleTypes.AOE, new AOEData(0)).aoe();
            if (host instanceof PropertyProvider) {
                if (((PropertyProvider) host).hasInt("tool_aoe")) {
                    aoe = ((PropertyProvider) host).getInt("tool_aoe").getValue();
                }
            }
        }

        Level level = context.getLevel();
        if (!attemptTillOp(context) && !level.getBlockState(context.getClickedPos()).is(Blocks.FARMLAND)) {
            return InteractionResult.FAIL;
        }

        Player player = context.getPlayer();
        if (player == null || player.isShiftKeyDown()) {
            return InteractionResult.SUCCESS;
        }

        BlockPos origin = context.getClickedPos();

        int aoe_range = aoe;
        BlockToStackHelper.startItemCapture();
        for (BlockPos aoePos : BlockPos.betweenClosed(origin.offset(-aoe_range, 0, -aoe_range), origin.offset(aoe_range, 0, aoe_range))) {
            if (aoePos.equals(origin)) {
                continue;
            }

            BlockState aoeState = level.getBlockState(aoePos);
            boolean airOrReplaceable = level.isEmptyBlock(aoePos) || aoeState.is(BlockTags.REPLACEABLE);
            boolean lowerBlockOk = level.getBlockState(aoePos.below()).isFaceSturdy(level, aoePos.below(), Direction.UP, SupportType.CENTER) || level.getBlockState(aoePos.below()).is(Blocks.FARMLAND);

            //Fill
            if (airOrReplaceable && lowerBlockOk && (player.getAbilities().instabuild || player.getInventory().contains(new ItemStack(Items.DIRT)))) {
                boolean canceled = EventHooks.onBlockPlace(player, BlockSnapshot.create(level.dimension(), level, aoePos), Direction.UP);

                if (!canceled && (player.getAbilities().instabuild || consumeItem(Items.DIRT, player.getInventory()))) {
                    level.setBlockAndUpdate(aoePos, Blocks.DIRT.defaultBlockState());
                }
            }

            boolean canDropAbove = level.getBlockState(aoePos.above()).is(Blocks.DIRT) || level.getBlockState(aoePos.above()).is(Blocks.GRASS_BLOCK) || level.getBlockState(aoePos.above()).is(Blocks.FARMLAND);
            boolean canRemoveAbove = canDropAbove || level.getBlockState(aoePos.above()).is(BlockTags.REPLACEABLE);
            boolean up2OK = level.isEmptyBlock(aoePos.above().above()) || level.getBlockState(aoePos.above().above()).is(BlockTags.REPLACEABLE);

            if (!level.isEmptyBlock(aoePos.above()) && canRemoveAbove && up2OK) {
                if (!level.isClientSide && canDropAbove) {
                    level.addFreshEntity(new ItemEntity(level, player.getX(), player.getY(), player.getZ(), new ItemStack(Blocks.DIRT)));
                }
                level.removeBlock(aoePos.above(), false);
            }
            attemptTillOp(updateContext(context, aoePos));
        }

        Set<ItemStack> drops = BlockToStackHelper.collectAndEndCapture();
        if (!level.isClientSide) {
            for (ItemStack drop : drops) {
                ItemUtils.dropItem(drop, level, Vector3.fromEntityCenter(player));
            }
        }

        return InteractionResult.SUCCESS;
    }

public void render(RenderLevelStageEvent event, List<ItemStack> stacks) {
        if (MC.level == null)
            return;

        initialise();

        var matrices = new PoseStack();

        matrices.mulPose(event.getModelViewMatrix());

        var partialTick = event.getPartialTick().getGameTimeDeltaPartialTick(false);
        var renderTime = MC.level.getGameTime() + partialTick;
        var skyAngle = MC.level.getTimeOfDay(partialTick) * 360F;

        RenderSystem.depthMask(false);
        RenderSystem.enableBlend();
        RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 1.0f);
        RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);

        var skyOcclusion = hasNormalSky() ? getSkyOcclusion(event) : 0F;
        var visibility = getVisibility(event) * skyOcclusion;
        var equipped = !stacks.isEmpty();
        var tint = equipped ? getSkyTint(stacks) : new SkyTint(currentTintRed, currentTintGreen, currentTintBlue);
        var targetTintAlpha = equipped ? visibility * 0.075F : 0F;
        var targetStarAlpha = equipped ? skyOcclusion : 0F;

        updateTint(tint, targetTintAlpha, partialTick);
        updateStarAlpha(targetStarAlpha, partialTick);

        var starAlpha = visibility * currentStarAlpha;

        if (currentTintAlpha > 0.003F)
            renderSkyTint(matrices, currentTintRed, currentTintGreen, currentTintBlue, currentTintAlpha);

        if (currentStarAlpha > 0.003F && equipped && visibility > 0) {
            var color = getStarColor(stacks);

            matrices.pushPose();
            matrices.mulPose(com.mojang.math.Axis.YP.rotationDegrees(-90.0F));
            matrices.mulPose(com.mojang.math.Axis.XP.rotationDegrees(skyAngle));

            RenderSystem.setShaderTexture(0, STAR_0);
            renderStarLayer(matrices, starLayer0, renderTime, 0.024F, color.secondaryRed(), color.secondaryGreen(), color.secondaryBlue(), starAlpha * 0.95F);

            RenderSystem.setShaderTexture(0, STAR_1);
            renderStarLayer(matrices, starLayer1, renderTime, 0.020F, color.red(), color.green(), color.blue(), starAlpha);

            RenderSystem.setShaderTexture(0, STAR_2);
            renderStarLayer(matrices, starLayer2, renderTime, -0.017F, color.secondaryRed(), color.secondaryGreen(), color.secondaryBlue(), starAlpha * 0.90F);

            RenderSystem.setShaderTexture(0, STAR_3);
            renderStarLayer(matrices, starLayer3, renderTime, 0.013F, color.red(), color.green(), color.blue(), starAlpha * 0.78F);

            RenderSystem.setShaderTexture(0, STAR_4);
            renderStarLayer(matrices, starLayer4, renderTime, -0.011F, color.secondaryRed(), color.secondaryGreen(), color.secondaryBlue(), starAlpha * 0.42F);

            RenderSystem.setShaderTexture(0, STAR_5);
            renderStarLayer(matrices, starLayer5, renderTime, 0.009F, color.red(), color.green(), color.blue(), starAlpha * 0.42F);

            renderResearchConstellations(matrices, renderTime, color, starAlpha);

            matrices.popPose();
        }

        RenderSystem.depthMask(true);
        RenderSystem.defaultBlendFunc();
        RenderSystem.disableBlend();
        RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 1.0f);
    }

@Override
    public void tickCommonPre() {
        oldExtension = extension;

        super.tickCommonPre();

        if (!nonNullLevel().isClientSide) {
            runScheduledStructureRefresh();
        }

        if (!isCoreElevator()) {
            extension = 0f;
            return;
        }

        if (!nonNullLevel().isClientSide) {
            if (isControlledByRedstone()) {
                handleRedstoneControl();
            }
            syncedSpeedMult = getSpeedMultiplierFromUpgrades();
            chargingUpgrades = getUpgrades(ModUpgrades.CHARGING.get());  // sync'd to client to adjust elevator speed as appropriate
            MiscEventHandler.needsTPSSync(getLevel());
        } else {
            if (prevCamoState != camoState) {
                fakeFloorTextureUV = ClientUtils.getTextureUV(camoState, Direction.UP);
                fakeFloorTextureTint = camoState != null && camoState.getBlock() instanceof ColorHandlers.ITintableBlock t ?
                        0xFF000000 | t.getTintColor(camoState, level, getBlockPos(), 0) :
                        0xFFFFFFFF;
                prevCamoState = camoState;
            }
            if ((nonNullLevel().getGameTime() & 0xf) == 0) {
                // kludge to prevent elevator TER rendering unlit sometimes
                lightAbove = ClientUtils.getLightAt(worldPosition.above());
            }
        }

        double speedMultiplier = getEffectiveSpeedMultiplier();
        if (extension < targetExtension && !nonNullLevel().isClientSide && getPressure() < PneumaticValues.MIN_PRESSURE_ELEVATOR) {
            setTargetExtensionForConnectedElevators(extension);
            queueStateSyncForConnectedElevators();
        }

        double elevatorDelta = calculateElevatorDelta(extension, targetExtension, speedMultiplier);
        if (elevatorDelta != 0) {
            extension += elevatorDelta;

            if (elevatorDelta > 0) {
                addAir((int) (-elevatorDelta * PneumaticValues.USAGE_ELEVATOR * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
            } else if (!nonNullLevel().isClientSide && chargingUpgrades > 0 && getPressure() < airHandler.getDangerPressure() - 0.1f) {
                float mul = 0.15f * Math.min(4, chargingUpgrades);
                addAir((int) (-elevatorDelta * PneumaticValues.USAGE_ELEVATOR * mul * (getSpeedUsageMultiplierFromUpgrades() / speedMultiplier)));
            }
        }

        moveEntitiesOnPlatform(extension - oldExtension);

        if (PneumaticCraftUtils.epsilonEquals(oldExtension, extension) && !isStopped) {
            // just arrived
            isStopped = true;
            ticksRunning = 0;
            playStopStartSound();
            if (!nonNullLevel().isClientSide) updateFloors(false);
        } else if (!PneumaticCraftUtils.epsilonEquals(oldExtension, extension) && isStopped) {
            // just departed
            isStopped = false;
            playStopStartSound();
        }
        if (!isStopped) ticksRunning++;
    }

