@Override
	public void tickServer()
	{
		if(turnCooldown > 0)
			turnCooldown--;
		boolean activeBeforeTick = getIsActive();
		boolean enabled;
		if(shouldUpdate)
		{
			lightsToBePlaced.clear();
			updateFakeLights(true, activeBeforeTick);
			setChanged();
			this.markContainingBlockForUpdate(null);
			shouldUpdate = false;
		}

		if(computerControl.isAttached())
			enabled = computerControl.isEnabled();
		else
			enabled = isRSPowered()^redstoneControlInverted;
		if(energyStorage >= (!activeBeforeTick?energyDraw*10: energyDraw)&&enabled&&switchCooldown <= 0)
		{
			energyStorage -= energyDraw;
			if(!activeBeforeTick)
				setActive(true);
		}
		else if(activeBeforeTick)
		{
			setActive(false);
			switchCooldown = timeBetweenSwitches;
		}

		switchCooldown--;
		boolean activeAfterTick = getIsActive();
		if(activeAfterTick!=activeBeforeTick||level.getGameTime()%512==((getBlockPos().getX()^getBlockPos().getZ())&511))
		{
			this.markContainingBlockForUpdate(null);
			updateFakeLights(true, activeAfterTick);
			checkLight();
		}
		if(!activeAfterTick)
		{
			if(!lightsToBePlaced.isEmpty())
				lightsToBePlaced.clear();
		}
		if((!lightsToBePlaced.isEmpty()||!lightsToBeRemoved.isEmpty())&&level.getGameTime()%8==((getBlockPos().getX()^getBlockPos().getZ())&7))
		{
			Iterator<BlockPos> it = lightsToBePlaced.iterator();
			int timeout = 0;
			while(it.hasNext()&&timeout++ < Math.max(16, 32-lightsToBeRemoved.size()))
			{
				BlockPos cc = it.next();
				//				world.setBlockState(cc, Blocks.glass.getDefaultState(), 2);
				level.setBlock(cc, Misc.FAKE_LIGHT.defaultBlockState(), 2);
				BlockEntity te = level.getBlockEntity(cc);
				if(te instanceof FakeLightBlockEntity)
					((FakeLightBlockEntity)te).setFloodlightCoords(getBlockPos());
				fakeLights.add(cc);
				it.remove();
			}
			it = lightsToBeRemoved.iterator();
			while(it.hasNext()&&timeout++ < 32)
			{
				BlockPos cc = it.next();
				if(Utils.getExistingTileEntity(level, cc) instanceof FakeLightBlockEntity)
					level.removeBlock(cc, false);
				it.remove();
			}
		}
	}

@Override
	public void update() {

		if (this.linkedContainer == null && this.linkedContainerPos != null) {
			this.linkContainer(world.getTileEntity(this.linkedContainerPos));
		}

		// Handle shrine regeneration
		if (conquered && Wizardry.settings.shrineRegenerationEnabled && regenerationTime > 0) {
			if (world.getTotalWorldTime() >= regenerationTime) {
				regenerate();
				return; // Don't process other logic during regeneration
			}
		}

		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		if (!activated && !conquered && world.getClosestPlayer(x, y, z, ACTIVATION_RADIUS, false) != null && (lastRegenerationTime == 0 || world.getTotalWorldTime() - lastRegenerationTime > 100)) { // 5 second delay after regeneration

			this.activated = true;

			if (world.isRemote) {
				ParticleBuilder.create(Type.SPHERE).pos(x, y + 1, z).clr(0xf06495).scale(5).time(12).spawn(world);
			}

			world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_ACTIVATE, SoundCategory.BLOCKS, 1.5f, 1, false);

			if (!world.isRemote) {

				EntityEvilWizard[] wizards = new EntityEvilWizard[linkedWizards.length];

				for (int i = 0; i < linkedWizards.length; i++) {

					EntityEvilWizard wizard = new EntityEvilWizard(world);

					float angle = world.rand.nextFloat() * 2 * (float) Math.PI;
					double x1 = this.pos.getX() + 0.5 + 5 * MathHelper.sin(angle);
					double z1 = this.pos.getZ() + 0.5 + 5 * MathHelper.cos(angle);
					Integer y1 = BlockUtils.getNearestFloor(world, new BlockPos(x1, this.pos.getY(), z1), 8);
					if (y1 == null) {
						// Fallback to the position of the shrine core if it failed to find a position (unlikely)
						x1 = this.pos.getX() + 1; // Offset it so the wizard isn't inside the block
						y1 = this.pos.getY();
						z1 = this.pos.getZ();
					}

					wizard.setLocationAndAngles(x1, y1 + 0.5, z1, 0, 0);
					wizard.setElement(world.getBlockState(pos).getValue(BlockPedestal.ELEMENT));
					wizard.onInitialSpawn(world.getDifficultyForLocation(pos), null);
					wizard.hasStructure = true;

					world.spawnEntity(wizard);
					wizards[i] = wizard;
					linkedWizards[i] = wizard.getUniqueID();
				}

				for (EntityEvilWizard wizard : wizards) wizard.groupUUIDs.addAll(Arrays.asList(linkedWizards));
			}

			containNearbyTargets();
		}

		if (!areWizardsDead() && activated && world.getTotalWorldTime() % 20L == 0) containNearbyTargets();

		if (activated && areWizardsDead() && !world.isRemote) {
			conquer();
		}
	}

private void splitIfRequired(@Nullable Consumer<TNet> onNetworkCreated) {
        if (graph.nodes().isEmpty()) {
            return;
        }

        var remaining = Sets.newHashSet(graph.nodes());
        var seen = Sets.newHashSet();
        Queue<TNode> toVisit = Queues.newArrayDeque();

        // Add the starting node for this graph
        var firstNode = remaining.iterator().next();
        toVisit.add(firstNode);
        seen.add(firstNode);
        remaining.remove(firstNode);

        // Iterate over adjacent neighbours that will remain in this graph.
        while (!toVisit.isEmpty()) {
            var node = toVisit.poll();
            for (var neighbor : graph.adjacentNodes(node)) {
                if (!seen.contains(neighbor)) {
                    seen.add(neighbor);
                    toVisit.add(neighbor);
                    remaining.remove(neighbor);
                }
            }
        }

        // No new graphs, no further work to do.
        if (remaining.isEmpty()) {
            return;
        }

        // If any nodes remain, they are now disconnected - form graphs to replace them.
        Set<TNet> newGraphs = Sets.newHashSet();
        while (!remaining.isEmpty()) {
            // TODO: Potentially rework this to use the new constructor?
            var newGraph = createEmpty();

            firstNode = remaining.iterator().next();
            toVisit.add(firstNode);
            seen.add(firstNode);
            remaining.remove(firstNode);

            while (!toVisit.isEmpty()) {
                var node = toVisit.poll();
                for (var neighbor : graph.adjacentNodes(node)) {
                    if (!seen.contains(neighbor)) {
                        seen.add(neighbor);
                        toVisit.add(neighbor);
                        remaining.remove(neighbor);
                    }
                }

                // Add node and its edges to the new graph.
                newGraph.graph.addNode(node);
                graph.incidentEdges(node).forEach(newGraph.graph::putEdge);
                graph.removeNode(node);
                node.setNetwork(newGraph);
                newGraph.onNodeAdded(node);
            }

            newGraphs.add(newGraph);
            if (onNetworkCreated != null) {
                onNetworkCreated.accept(newGraph);
            }
        }

        // Perform any additional split actions
        onGraphSplit(newGraphs);
    }

@Override
	public void tick() {
		this.baseTick();

		if (this.life == 2) {
			if (level().isClientSide()) {
				if (!isSilent()) {
					level().playLocalSound(getX(), getY(), getZ(), SoundEvents.LIGHTNING_BOLT_THUNDER, SoundSource.WEATHER, 10, 0.8F + this.random.nextFloat() * 0.2F, false);
					level().playLocalSound(getX(), getY(), getZ(), SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.WEATHER, 1, 0.5F + this.random.nextFloat() * 0.2F, false);
				}
			}
			else {
				Difficulty difficulty = level().getDifficulty();

				if ((difficulty == Difficulty.NORMAL || difficulty == Difficulty.HARD) && this.doFire)
					spawnFire(4);

				powerLightningRod();
				clearCopperOnLightningStrike(level(), this.getStrikePosition());
				gameEvent(GameEvent.LIGHTNING_STRIKE);
			}
		}

		--this.life;

		if (this.life < 0) {
			if (this.flashes == 0) {
				if (level() instanceof ServerLevel) {
					List<Entity> entities = EntityRetrievalUtil.getEntities(level(), new AABB(getX() - 15, getY() - 15, getZ() - 15, getX() + 15, getY() + 21, getZ() + 15), entity -> entity != this && entity.isAlive() && !this.hitEntities.contains(entity));

					for (ServerPlayer player : ((ServerLevel)level()).getPlayers(player -> player.distanceTo(this) < 256)) {
						CriteriaTriggers.LIGHTNING_STRIKE.trigger(player, this, entities);
					}
				}

				discard();
			}
			else if (this.life < -this.random.nextInt(10)) {
				--this.flashes;
				this.life = 1;
				this.seed = this.random.nextLong();

				if (this.doFire)
					spawnFire(0);
			}
		}

		if (this.life >= 0) {
			if (!(level() instanceof ServerLevel serverLevel)) {
				level().setSkyFlashTime(2);
			}
			else if (!this.visualOnly) {
				List<Entity> entities = EntityRetrievalUtil.getEntities(serverLevel, new AABB(getX() - 3, getY() - 3, getZ() - 3, getX() + 3, getY() + 9, getZ() + 3), entity -> entity != this && entity.isAlive());

				for (Entity entity : entities) {
					if (!EventHooks.onEntityStruckByLightning(entity, this)) {
						entity.thunderHit(serverLevel, this);

						if (this.onEntityStrike != null)
							this.onEntityStrike.accept(entity);
					}
				}

				this.hitEntities.addAll(entities);

				if (this.cause != null)
					CriteriaTriggers.CHANNELED_LIGHTNING.trigger(this.cause, entities);
			}
		}
	}

