public void castSpells() {
        float aoe = getAoe();
        int flatAoe = Math.round(aoe);
        BlockPos start = blockPosition().offset(flatAoe * getDirection().getStepX(), 0, flatAoe * getDirection().getStepZ());
        BlockPos end = blockPosition().offset(-flatAoe * getDirection().getStepX(), flatAoe, -flatAoe * getDirection().getStepZ());
        if (isSensitive()) {
            if (age % (Math.max(1, 20 - 2 * getAccelerates())) != 0 && age != 1)
                return;
            for (BlockPos p : BlockPos.betweenClosed(start, end)) {
                p = p.immutable();
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new
                            BlockHitResult(new Vec3(p.getX(), p.getY(), p.getZ()), Direction.UP, p, false));
                }
                resolveEmitter.setPositionOffset(p.subtract(blockPosition()).getCenter());
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
            }
            if (!level.isClientSide) {
                resolveSound.playSound(level, getX(), getY(), getZ());
            }
        } else {
            int i = 0;
            // Expand the axis if start and end are equal

            AABB aabb = AABB.encapsulatingFullBlocks(start, end);
            if (aabb.maxX == aabb.minX) {
                aabb = aabb.inflate(growthFactor, 0, 0);
            }
            if (aabb.maxY == aabb.minY) {
                aabb = aabb.inflate(0, growthFactor, 0);
            }
            if (aabb.maxZ == aabb.minZ) {
                aabb = aabb.inflate(0, 0, growthFactor);
            }
            for (Entity entity : level.getEntities(null, aabb)) {
                if (entity.equals(this) || entity.getType().is(EntityTags.LINGERING_BLACKLIST)) {
                    continue;
                }
                Optional<EntityHit> hit = hitEntities.stream().filter(e -> e.entity.refersTo(entity)).findFirst();
                boolean skipEntity = hit.isPresent();
                if (hit.isPresent() && level.getGameTime() - hit.get().gameTime > 20) {
                    hitEntities.remove(hit.get());
                    skipEntity = false;
                }
                if (skipEntity)
                    continue;
                if (!level.isClientSide) {
                    resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new EntityHitResult(entity));
                }
                resolveEmitter.setPositionOffset(entity.position.subtract(position).add(0, entity.getBbHeight() / 2.0, 0));
                if (level.isClientSide) {
                    resolveEmitter.tick(level);
                }
                i++;
                if (hit.isEmpty()) {
                    hitEntities.add(new EntityHit(entity));
                }
                if (i > 5)
                    break;
                if (!level.isClientSide) {
                    resolveSound.playSound(level, getX(), getY(), getZ());
                }
            }
            totalProcs += i;
            if (totalProcs >= maxProcs)
                this.remove(RemovalReason.DISCARDED);
        }
    }

@Override
    public void submit(GoldenSacrificialBowlRenderState renderState, PoseStack poseStack, SubmitNodeCollector submitCollector, CameraRenderState cameraRenderState) {
        ItemStack stack = renderState.itemStack;
        ItemStackRenderState stackRenderState = renderState.itemStackRenderState;
        Direction facing = renderState.facing;
        long gameTime = renderState.gameTime;
        long lastChangeTime = renderState.lastChangeTime;

        if (stack == null || stack.isEmpty() || facing == null || gameTime == 0) {
            return;
        }

        poseStack.pushPose();
        poseStack.pushPose();

        // Calculate bobbing offset
        double offset = Math.sin((gameTime - lastChangeTime) / 16.0) * 0.5 + 0.5;
        offset = offset / 4.0;

        double fixedOffset = 0.2;

        double xOffset = facing.getAxis() == Direction.Axis.X ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;
        double yOffset = facing.getAxis() == Direction.Axis.Y ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;
        double zOffset = facing.getAxis() == Direction.Axis.Z ? (facing.getAxisDirection() == AxisDirection.POSITIVE ? offset + fixedOffset : -offset - fixedOffset) : 0.0;

        poseStack.translate(0.5 + xOffset, 0.5 + yOffset, 0.5 + zOffset);

        // Rotate item around Y axis using system time
        long systemTime = System.currentTimeMillis();
        float angle = (systemTime / 16) % 360;
        poseStack.mulPose(Axis.YP.rotationDegrees(angle));

        // Scale
        float scale = getScale(stack) * 0.5f;
        poseStack.scale(scale, scale, scale);

        // Render the main item using the pre-created ItemStackRenderState
        stackRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);

        // Render item-to-use indicator for GoldenSacrificialBowl
        if (renderState.isGoldenBowl && !stack.isEmpty() && renderState.itemToUseStacks != null && renderState.itemToUseStacks.length > 0) {
            poseStack.pushPose();
            poseStack.translate(0, 3.2 - (0.5 + yOffset) / scale, 0);
            if (!renderState.itemUseFulfilled && renderState.requiresItemUse) {
                int index = renderState.itemToUseIndex;
                ItemStack itemStack = renderState.itemToUseStacks[index];
                if (!itemStack.isEmpty()) {
                    float scaleUse = getScale(itemStack) * 0.5F;
                    poseStack.scale(scaleUse, scaleUse, scaleUse);
                    renderState.itemToUseRenderState.submit(poseStack, submitCollector, renderState.lightCoords, OverlayTexture.NO_OVERLAY, 0);
                }
            }
            poseStack.popPose();
        }

        if (renderState.isGoldenBowl && renderState.requiresSacrifice && !renderState.sacrificeFulfilled && renderState.sacrificeEntityRenderState != null) {
            poseStack.pushPose();
            poseStack.translate(0, 3.2 - (0.5 + yOffset) / scale, 0);
            poseStack.scale(renderState.sacrificeEntityScale, renderState.sacrificeEntityScale, renderState.sacrificeEntityScale);
            EntityRenderDispatcher dispatcher = Minecraft.getInstance().getEntityRenderDispatcher();
            dispatcher.submit(renderState.sacrificeEntityRenderState, cameraRenderState, 0, 0, 0, poseStack, submitCollector);
            poseStack.popPose();
        }

        poseStack.popPose();

        poseStack.mulPose(facing.getRotation());

        poseStack.popPose();
    }

private static <T extends BlockEntity & IMultiBlockEntityContainer> void formMulti(BlockEntityType<?> type,
																					   BlockGetter level, SearchCache<T> cache, List<T> frontier) {
		PriorityQueue<Pair<Integer, T>> creationQueue = makeCreationQueue();
		Set<BlockPos> visited = new HashSet<>();
		Direction.Axis mainAxis = frontier.get(0)
			.getMainConnectionAxis();

		// essentially, if it's a vertical multi then the search won't be restricted by
		// Y
		// alternately, a horizontal multi search shouldn't be restricted by X or Z
		int minX = (mainAxis == Direction.Axis.Y ? Integer.MAX_VALUE : Integer.MIN_VALUE);
		int minY = (mainAxis != Direction.Axis.Y ? Integer.MAX_VALUE : Integer.MIN_VALUE);
		int minZ = (mainAxis == Direction.Axis.Y ? Integer.MAX_VALUE : Integer.MIN_VALUE);

		for (T be : frontier) {
			BlockPos pos = be.getBlockPos();
			minX = Math.min(pos.getX(), minX);
			minY = Math.min(pos.getY(), minY);
			minZ = Math.min(pos.getZ(), minZ);
		}
		if (mainAxis == Direction.Axis.Y)
			minX -= frontier.get(0)
				.getMaxWidth();
		if (mainAxis != Direction.Axis.Y)
			minY -= frontier.get(0)
				.getMaxWidth();
		if (mainAxis == Direction.Axis.Y)
			minZ -= frontier.get(0)
				.getMaxWidth();

		while (!frontier.isEmpty()) {
			T part = frontier.remove(0);
			BlockPos partPos = part.getBlockPos();
			if (visited.contains(partPos))
				continue;

			visited.add(partPos);

			int amount = tryToFormNewMulti(part, cache, true);
			if (amount > 1) {
				creationQueue.add(Pair.of(amount, part));
			}

			for (Direction.Axis axis : Iterate.axes) {
				Direction dir = Direction.get(Direction.AxisDirection.NEGATIVE, axis);
				BlockPos next = partPos.relative(dir);

				if (next.getX() <= minX || next.getY() <= minY || next.getZ() <= minZ)
					continue;
				if (visited.contains(next))
					continue;
				T nextBe = partAt(type, level, next);
				if (nextBe == null)
					continue;
				if (nextBe.isRemoved())
					continue;
				frontier.add(nextBe);
			}
		}
		visited.clear();

		while (!creationQueue.isEmpty()) {
			Pair<Integer, T> next = creationQueue.poll();
			T toCreate = next.getValue();
			if (visited.contains(toCreate.getBlockPos()))
				continue;

			visited.add(toCreate.getBlockPos());
			tryToFormNewMulti(toCreate, cache, false);
		}
	}

public boolean mouseClicked(double pMouseX, double pMouseY, int pButton) {
		if (super.mouseClicked(pMouseX, pMouseY, pButton))
			return true;
		if (pButton != 0)
			return true;

		if (hoveredEntry != -1) {
			if (hoveredCheck) {
				editingIndex = -1;
				if (hoveredEntry < currentEntries.size()) {
					currentEntries.get(hoveredEntry).checked ^= true;
					if (currentEntries.get(hoveredEntry).checked)
						Minecraft.getInstance()
							.getSoundManager()
							.play(SimpleSoundInstance.forUI(AllSoundEvents.CLIPBOARD_CHECKMARK.getMainEvent(),
								0.95f + (float) Math.random() * 0.05f));
					else
						Minecraft.getInstance()
							.getSoundManager()
							.play(SimpleSoundInstance.forUI(AllSoundEvents.CLIPBOARD_ERASE.getMainEvent(),
								0.90f + (float) Math.random() * 0.2f));
				}
				sendIfEditingBlock();
				return true;
			}

			if (hoveredEntry != editingIndex && !readonly) {
				editingIndex = hoveredEntry;
				if (hoveredEntry >= currentEntries.size()) {
                    currentEntries.add(new ClipboardEntry(false, Component.empty()));
					if (!validateTextForEntry(" ")) {
						currentEntries.remove(hoveredEntry);
						editingIndex = -1;
						return true;
					}
				}
				clearDisplayCacheAfterChange();
			}
		}

		if (editingIndex == -1)
			return false;

		if (pMouseX < guiLeft + 50 || pMouseX > guiLeft + 220 || pMouseY < guiTop + 30 || pMouseY > guiTop + 230) {
			setFocused(null);
			clearDisplayCache();
			editingIndex = -1;
			return false;
		}

		long i = Util.getMillis();
		DisplayCache cache = getDisplayCache();
		int j = cache.getIndexAtPosition(font, convertScreenToLocal(new Pos2i((int) pMouseX, (int) pMouseY)));
		if (j >= 0) {
			if (j == lastIndex && i - lastClickTime < 250L) {
				if (!editContext.isSelecting()) {
					selectWord(j);
				} else {
					editContext.selectAll();
				}
			} else {
				editContext.setCursorPos(j, Screen.hasShiftDown());
			}

			clearDisplayCache();
		}

		lastIndex = j;
		lastClickTime = i;
		return true;
	}

public float getDistanceTo(TrackGraph graph, TravellingPoint current, TravellingPoint target, float maxDistance,
		boolean forward) {
		if (maxDistance == -1)
			maxDistance = 32;

		Set<TrackEdge> visited = new HashSet<>();
		Map<TrackEdge, Pair<Boolean, TrackEdge>> reachedVia = new IdentityHashMap<>();
		PriorityQueue<Pair<Double, Pair<Couple<TrackNode>, TrackEdge>>> frontier =
			new PriorityQueue<>((p1, p2) -> Double.compare(p1.getFirst(), p2.getFirst()));

		TrackNode initialNode1 = forward ? current.node1 : current.node2;
		TrackNode initialNode2 = forward ? current.node2 : current.node1;

		Map<TrackNode, TrackEdge> connectionsFromInitial = graph.getConnectionsFrom(initialNode1);
		if (connectionsFromInitial == null)
			return -1;

		TrackEdge initialEdge = connectionsFromInitial.get(initialNode2);
		if (initialEdge == null)
			return -1; // graph changed

		TrackNode targetNode1 = forward ? target.node1 : target.node2;
		TrackNode targetNode2 = forward ? target.node2 : target.node1;
		TrackEdge targetEdge = graph.getConnectionsFrom(targetNode1)
			.get(targetNode2);

		double distanceToNode2 = forward ? initialEdge.getLength() - current.position : current.position;

		frontier.add(Pair.of(distanceToNode2, Pair.of(Couple.create(initialNode1, initialNode2), initialEdge)));

		while (!frontier.isEmpty()) {
			Pair<Double, Pair<Couple<TrackNode>, TrackEdge>> poll = frontier.poll();
			double distance = poll.getFirst();

			Pair<Couple<TrackNode>, TrackEdge> currentEntry = poll.getSecond();
			TrackNode node2 = currentEntry.getFirst()
				.getSecond();
			TrackEdge edge = currentEntry.getSecond();

			if (edge == targetEdge)
				return (float) (distance - (forward ? edge.getLength() - target.position : target.position));

			if (distance > maxDistance)
				continue;

			List<Entry<TrackNode, TrackEdge>> validTargets = new ArrayList<>();
			Map<TrackNode, TrackEdge> connectionsFrom = graph.getConnectionsFrom(node2);
			for (Entry<TrackNode, TrackEdge> entry : connectionsFrom.entrySet()) {
				TrackEdge newEdge = entry.getValue();
				Vec3 currentDirection = edge.getDirection(false);
				Vec3 newDirection = newEdge.getDirection(true);
				if (currentDirection.dot(newDirection) < 7 / 8f)
					continue;
				if (!visited.add(entry.getValue()))
					continue;
				validTargets.add(entry);
			}

			if (validTargets.isEmpty())
				continue;

			for (Entry<TrackNode, TrackEdge> entry : validTargets) {
				TrackNode newNode = entry.getKey();
				TrackEdge newEdge = entry.getValue();
				reachedVia.put(newEdge, Pair.of(validTargets.size() > 1, edge));
				frontier.add(Pair.of(newEdge.getLength() + distance, Pair.of(Couple.create(node2, newNode), newEdge)));
			}
		}

		return -1;
	}

public void conquer() {

		double x = this.pos.getX() + 0.5;
		double y = this.pos.getY() + 0.5;
		double z = this.pos.getZ() + 0.5;

		if (!world.isRemote) {

			WizardryPacketHandler.net.sendToAllAround(new PacketConquerShrine.Message(this.pos), new NetworkRegistry.TargetPoint(this.world.provider.getDimension(), x, y, z, 64));

			// Remove containment effects from nearby targets when shrine is conquered
			removeContainmentFromNearbyTargets();

			// If regeneration is enabled, schedule regeneration instead of removing the tile entity
			if (Wizardry.settings.shrineRegenerationEnabled) {
				this.conquered = true;
				this.regenerationTime = world.getTotalWorldTime() + (Wizardry.settings.shrineRegenerationTime * 1200L); // Convert minutes to ticks (20 ticks per second * 60 seconds)
				this.activated = false;
				Arrays.fill(this.linkedWizards, null); // Clear wizard references
				// Keep lootedPlayers list - it's permanent tracking for this shrine instance

				// Handle chest breaking and loot dropping
				handleChestLootDrop();

				// Mark the tile entity for update
				this.markDirty();

				if (world.getBlockState(pos).getBlock() == WizardryBlocks.runestone_pedestal) {
					// Keep the block state the same, just mark as conquered
					this.shrineElement = world.getBlockState(pos).getValue(BlockPedestal.ELEMENT);
				} else {
					Wizardry.logger.warn("What's going on?! A shrine core is being conquered but the block at its position is not a runestone pedestal!");
				}
			} else {
				// Original behavior: remove the tile entity
				BlockPos chestPos = this.pos.up();
				TileEntity chestTileEntity = world.getTileEntity(chestPos);
				if (chestTileEntity instanceof TileEntityChest) {
					TileEntityChest chest = (TileEntityChest) chestTileEntity;
					NBTExtras.removeUniqueId(chest.getTileData(), ArcaneLock.NBT_KEY);
					chest.markDirty();
					world.markAndNotifyBlock(pos, null, world.getBlockState(pos), world.getBlockState(pos), 3);
				}
				if (world.getBlockState(pos).getBlock() == WizardryBlocks.runestone_pedestal) {
					world.setBlockState(pos, WizardryBlocks.runestone_pedestal.getDefaultState().withProperty(BlockPedestal.ELEMENT, world.getBlockState(pos).getValue(BlockPedestal.ELEMENT)));
				} else {
					Wizardry.logger.warn("What's going on?! A shrine core is being conquered but the block at its position is not a runestone pedestal!");
				}
				world.markTileEntityForRemoval(this);
			}
		}

		if (linkedContainer == null) {
			linkedContainer = world.getTileEntity(pos.up());
		}

		if (linkedContainer != null) {
			NBTExtras.removeUniqueId(linkedContainer.getTileData(), ArcaneLock.NBT_KEY);
			//linkedContainer.getTileData().removeTag("arcaneLockOwnerMost");
			//linkedContainer.getTileData().removeTag("arcaneLockOwnerLeast");
		}
		world.playSound(x, y, z, WizardrySounds.BLOCK_PEDESTAL_CONQUER, SoundCategory.BLOCKS, 1, 1, false);

		if (world.isRemote) {
			ParticleBuilder.create(Type.SPHERE).scale(5).pos(x, y + 1, z).clr(0xf06495).time(12).spawn(world);
			for (int i = 0; i < 5; i++) {
				float brightness = 0.8f + world.rand.nextFloat() * 0.2f;
				ParticleBuilder.create(Type.SPARKLE, world.rand, x, y + 1, z, 1, true).clr(1, brightness, brightness).spawn(world);
			}
		}
	}

public AbilityUseResult directSlam(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
        int stunDuration = 0;
        double damageMultiplier = item.getEffectLevel(itemStack, ItemEffect.slam) * 1.5 / 100;
        float knockbackBase = (float) item.getEffectEfficiency(itemStack, ItemEffect.slam);
        float knockbackMultiplier = 1f;

        boolean isDefensive = isDefensive(item, itemStack, hand);
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

        if (isDefensive) {
            damageMultiplier -= 0.3;
            stunDuration = item.getEffectLevel(itemStack, ItemEffect.abilityDefensive);
        }

        if (overchargeBonus > 0) {
            double bonus = overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
            damageMultiplier += bonus;
            knockbackMultiplier += bonus;
        }

        int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
        if (momentumLevel > 0) {
            stunDuration = momentumLevel;
        }

        double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
        if (momentumEfficiency > 0) {
            knockbackMultiplier = 0.4f;
        }

        double overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
        if (overextendLevel > 0 && !attacker.getFoodData().needsFood()) {
            damageMultiplier += overextendLevel / 100d;
        }

        AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockbackMultiplier * knockbackBase, knockbackMultiplier / 2);

        if (result != AbilityUseResult.fail) {
            if (stunDuration > 0) {
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, stunDuration, 0, false, false));
            }

            if (momentumEfficiency > 0) {
                double velocity = momentumEfficiency;
                velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                target.push(0, velocity, 0);
            }

            if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
            }

            double exhilarationEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationEfficiency > 0) {
                knockbackExhilaration(attacker, attacker.position(), target, target.level().getGameTime() + 200, exhilarationEfficiency);
            }

            RandomSource rand = target.getRandom();
            CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                    world.sendParticles(ParticleTypes.CRIT,
                            hitVec.x, hitVec.y, hitVec.z, 10,
                            rand.nextGaussian() * 0.3, rand.nextGaussian() * target.getBbHeight() * 0.8, rand.nextGaussian() * 0.3, 0.1f));

            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.7f);
        } else {
            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.7f);
        }

        return result;
    }

@SubscribeEvent
        public static void onLivingDamageModifiers(LivingDamageEvent.Pre event) {
            var target = event.getEntity();
            var source = event.getSource().getEntity();

            if (!target.level().isClientSide() && target.getPersistentData().getLong(FOG_SUFFOCATION_UNTIL_TAG) >= target.level().getGameTime()
                    && event.getSource().is(DamageTypes.IN_WALL)) {
                var modifier = target.getPersistentData().getFloat(FOG_SUFFOCATION_DAMAGE_TAG);

                event.setNewDamage((float) (event.getNewDamage() * (1D + modifier)));
            }

            if (!target.level().isClientSide()) {
                var targetId = target.getStringUUID();

                for (var player : target.level().players()) {
                    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                        var relic = (GhostlyMantleItem) stack.getItem();
                        var marks = relic.getReprisalMarks(stack);
                        var modifier = marks.remove(targetId);

                        if (modifier == null)
                            continue;

                        var original = event.getNewDamage();
                        var modified = original * (1D + modifier);
                        var extra = modified - original;

                        event.setNewDamage((float) modified);
                        relic.setReprisalMarks(stack, marks);

                        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("spectral_escape");

                        ability.getStatisticData().getMetricData("reprisal_damage").addValue(extra);

                        if (extra > 0D) {
                            var experience = player.getRandom().nextInt((int) (extra + 1D));

                            if (experience > 0)
                                relic.getRelicData(player, stack).getLevelingData().addExperience("spectral_escape", "reprisal_damage", experience);
                        }

                        return;
                    }
                }
            }

            if (!(target instanceof Player player) || !(source instanceof LivingEntity attacker) || source == target)
                return;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("gaze");

                if (!ability.canPlayerUse(player))
                    continue;

                var data = relic.getGazeCharges(stack).get(attacker.getStringUUID());

                if (data == null || data.charges() <= 0)
                    continue;

                var original = event.getNewDamage();
                var reduction = data.charges() * ability.getStatData("weakness").getValue();

                event.setNewDamage((float) Math.max(0D, original * (1D - reduction)));
                ability.getStatisticData().getMetricData("damage_reduced").addValue(original - event.getNewDamage());

                return;
            }
        }

private boolean trySpawnInvader(FinalizeSpawnEvent e, Mob mob, GenContext ctx, Player player) {
        // Invaders can only trigger off of natural spawns (chunk generation is considered "natural")
        if (e.getSpawnType() != EntitySpawnReason.NATURAL && e.getSpawnType() != EntitySpawnReason.CHUNK_GENERATION || !(mob instanceof Monster)) {
            debugLog("[Invaders]: Failed invader preconditions.");
            return false;
        }

        ServerLevelAccessor sLevel = e.getLevel();
        long gameTime = sLevel.getGameTime();

        if (player.getData(Attachments.INVADER_COOLDOWN) > gameTime) {
            debugLog("[Invaders]: Spawn cooldown is active for the context player {}.", player.getName().getString());
            return false;
        }

        ResourceKey<DimensionType> dimId = sLevel.getLevel().dimensionTypeRegistration().getKey();

        InvaderSpawnRules rules = sLevel.registryAccess().lookupOrThrow(Registries.DIMENSION_TYPE).getData(DataMaps.INVADER_SPAWN_RULES, dimId);
        if (rules == null) {
            debugLog("[Invaders]: No invader spawn rules present for dimension {}", dimId);
            return false;
        }

        float chance = rules.spawnChances().get(ctx.tier());
        SurfaceType surface = rules.surfaceType();

        if (ctx.rand().nextFloat() > chance) {
            debugLog("[Invaders]: Failed random chance roll.");
            return false;
        }

        if (surface.test(sLevel, BlockPos.containing(e.getX(), e.getY(), e.getZ()))) {
            debugLog("[Invaders]: Succeeded at random chance roll and surface test.");
            Invader item = InvaderRegistry.INSTANCE.getRandomItem(ctx);
            if (item == null) {
                Apotheosis.LOGGER.error("Attempted to spawn an Invader in dimension {} using configured spawn rules {} but no bosses were made available.", dimId, rules);
                return false;
            }

            if (!item.basicData().canSpawn(mob, sLevel, e.getSpawnType())) {
                debugLog("[Invaders]: Failed invader spawn conditions.");
                return false;
            }

            Mob boss = item.createBoss(sLevel, BlockPos.containing(e.getX() - 0.5, e.getY(), e.getZ() - 0.5), ctx);
            if (rules.autoAggro().orElse(AdventureConfig.bossAutoAggro) && !player.isCreative()) {
                boss.setTarget(player);
            }

            if (canSpawn(sLevel, boss, player.distanceToSqr(boss))) {
                sLevel.addFreshEntityWithPassengers(boss);
                e.setCanceled(true);
                e.setSpawnCancelled(true);

                sendInvaderSpawnNotification(sLevel.getLevel(), boss);

                long end = gameTime + rules.cooldown().orElse(AdventureConfig.bossSpawnCooldown);
                applyClusteredCooldown(sLevel.getLevel(), player, ctx.tier(), boss, end);
                debugLog("[Invaders]: Successfully spawned an invader {} at {}", boss.getName().getString(), boss.blockPosition());
                return true;
            }
            else {
                debugLog("Failed entity spawn checks.");
            }
        }
        else {
            debugLog("[Invaders]: Failed surface test " + surface);
        }

        return false;
    }

@Override
    public Optional<ConduitConnectionPath> findPath(
        ConduitBlockConnection from,
        ConduitBlockConnection to,
        PathfindingContext context
    ) {
        ConduitNode start = from.node();
        ConduitNode goal = to.node();

        // Collect starting node properties
        Map<ConnectionPathProperty<?>, List<Object>> startAggregates = 
            createAggregateMap(context.collectNodeProperties(start));

        // Special case: same node
        if (start.equals(goal)) {
            return Optional.of(new ConduitConnectionPath(
                from, 
                to, 
                1, 
                aggregatePropertyValues(startAggregates)
            ));
        }

        // BFS data structures
        Queue<ConduitNode> queue = new LinkedList<>();
        Set<ConduitNode> visited = new HashSet<>();
        Map<ConduitNode, Integer> distance = new HashMap<>();
        Map<ConduitNode, Map<ConnectionPathProperty<?>, List<Object>>> aggregateProperties = new HashMap<>();

        // Initialize with start node
        queue.add(start);
        visited.add(start);
        distance.put(start, 1);
        aggregateProperties.put(start, startAggregates);

        // BFS traversal
        while (!queue.isEmpty()) {
            ConduitNode current = queue.poll();
            int currentDist = distance.get(current);

            for (ConduitNode neighbor : context.neighbors(current)) {
                // Skip already visited nodes
                if (visited.contains(neighbor)) {
                    continue;
                }

                visited.add(neighbor);
                queue.add(neighbor);
                distance.put(neighbor, currentDist + 1);

                // Aggregate properties along the path
                Map<ConnectionPathProperty<?>, List<Object>> neighborAggregate = 
                    duplicatePropertyMap(aggregateProperties.get(current));
                mergePropertyMap(neighborAggregate, context.collectNodeProperties(neighbor));
                aggregateProperties.put(neighbor, neighborAggregate);

                // Check if we've reached the goal
                if (neighbor.equals(goal)) {
                    return Optional.of(new ConduitConnectionPath(
                        from,
                        to,
                        currentDist + 1,
                        aggregatePropertyValues(neighborAggregate)
                    ));
                }
            }
        }

        // No path found
        return Optional.empty();
    }

public static String generate(String packageName, String modId, List<CreatureModel> models) {
        String className = className(modId);
        boolean anyImmune = models.stream().anyMatch(m -> m.immuneToSweetBerryBush());
        StringBuilder im = new StringBuilder();
        List<String> imps = new ArrayList<>(List.of(
                "net.minecraft.world.entity.EntityType",
                "net.minecraft.world.entity.MobCategory",
                "net.minecraft.world.entity.SpawnPlacementTypes",
                "net.minecraft.world.level.Level",
                "net.minecraft.world.level.levelgen.Heightmap",
                "net.neoforged.bus.api.IEventBus",
                "net.neoforged.bus.api.SubscribeEvent",
                "net.neoforged.fml.common.EventBusSubscriber",
                "net.neoforged.fml.event.lifecycle.FMLConstructModEvent",
                "net.neoforged.fml.loading.moddiscovery.ModInfo",
                "net.neoforged.neoforge.event.entity.EntityAttributeCreationEvent",
                "net.neoforged.neoforge.event.entity.RegisterSpawnPlacementsEvent",
                "net.neoforged.neoforge.registries.DeferredHolder",
                "net.neoforged.neoforge.registries.DeferredRegister"));
        if (anyImmune) {
            imps.add("net.minecraft.world.level.block.Blocks");
        }
        ProcessorUtil.imports(im, imps.toArray(String[]::new));

        StringBuilder fields = new StringBuilder();
        StringBuilder attrs = new StringBuilder();
        StringBuilder spawns = new StringBuilder();
        for (CreatureModel m : models) {
            String factory = m.hasSubclass()
                    ? m.registeredSimple() + "::new"
                    : "(type, world) -> new %1$s(type, world) {}".formatted(m.className());
            String immune = m.immuneToSweetBerryBush() ? ".immuneTo(Blocks.SWEET_BERRY_BUSH)" : "";
            String sized = m.width() >= 0
                    ? "b.sized(%1$sF, %2$sF)".formatted(ProcessorUtil.str(m.width()), ProcessorUtil.str(m.height()))
                    : "b.sized(EntityType.%1$s.getDimensions().width(), EntityType.%1$s.getDimensions().height()).eyeHeight(EntityType.%1$s.getDimensions().eyeHeight())".formatted(m.entityType());
            fields.append("""
                        public static final DeferredHolder<EntityType<?>, EntityType<%2$s>> %1$s = CONVERTED.<%2$s>registerEntityType("%3$s", %4$s, MobCategory.%5$s, b -> %6$s%7$s.clientTrackingRange(80).setUpdateInterval(1).setShouldReceiveVelocityUpdates(true));
                    """.formatted(m.holderField(), m.registeredSimple(), m.registryName(), factory, m.mobCategory(), sized, immune));
            attrs.append("        event.put(%1$s.get(), %2$s.getAttributeBuilder().build());\n".formatted(m.holderField(), m.registeredSimple()));
            spawns.append("        event.register(%1$s.get(), SpawnPlacementTypes.ON_GROUND, Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, %2$s::checkSpawnRules, RegisterSpawnPlacementsEvent.Operation.OR);\n".formatted(m.holderField(), m.registeredSimple()));
        }

        String pkg = packageName.isEmpty() ? "" : "package " + packageName + ";\n\n";
        return pkg + im + "\n" + """
                /**
                 * Generated converted-entity registrar. Standalone: owns its own {@link DeferredRegister} and
                 * registers the attribute / spawn-placement listeners itself.
                 */
                @EventBusSubscriber(modid = "%2$s")
                public final class %1$s {

                    public static final DeferredRegister.Entities CONVERTED = DeferredRegister.createEntities("%2$s");

                %3$s
                    private %1$s() {}

                    @SubscribeEvent
                    public static void onModConstructed(FMLConstructModEvent modBus) {
                        CONVERTED.register(modBus.getContainer().getEventBus());
                    }

                    @SubscribeEvent
                    private static void onAttributes(EntityAttributeCreationEvent event) {
                %4$s    }

                    @SubscribeEvent
                    private static void onSpawnPlacements(RegisterSpawnPlacementsEvent event) {
                %5$s    }
                }
                """.formatted(className, modId, fields.toString(), attrs.toString(), spawns.toString());
    }

public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, MotherBlockEntity e) {

        //Handle fight ---------------------------------
        if (e.isFrozen && e.freezeTimer-- <= 0) {
            e.unFreezeFight(level, blockPos, blockState);
        }
        if (!e.isFrozen && e.level != null && e.isIntact()) {
            if (e.level.getRandom().nextInt(50) == 0) {
                e.updateFightStatus();
                if (!e.activePlayers.isEmpty()) {
                    List<Triple<BlockPos, BlockState, IRemainsBlock>> vuls = e.getTreeStructure(false).getVerifiedVulnerabilities(level).filter(t -> t.getRight().isVulnerable(t.getMiddle())).toList();
                    if (!vuls.isEmpty()) {
                        for (ServerPlayer player : e.activePlayers) {
                            if (player.getAbilities().invulnerable) {
                                continue;
                            }
                            BlockPos p = vuls.get(e.level.getRandom().nextInt(vuls.size())).getLeft();
                            player.addEffect(new MobEffectInstance(MobEffects.HUNGER, 5 * 20, 2));
                            ModParticles.spawnParticlesServer(player.level(), new MotherParticleOptions(100, false, p.getX() + 0.5, p.getY() + 0.5, p.getZ() + 0.5, 0.5f), player.getX(), player.getY() + player.getEyeHeight() / 2, player.getZ(), 5, 0.1f, 0.1f, 0.1f, 0);
                        }
                    }
                }
            }
            if (e.level.getRandom().nextFloat() < Math.clamp(e.activePlayers.size() * 0.002f, 0.02f, 0.1f)) {
                var blocks = e.getTreeStructure(false).getCachedBlocks();
                if (e.level.getEntitiesOfClass(GhostEntity.class, e.getArea().inflate(10)).size() < Math.min(e.activePlayers.size() * 1.6, 10)) {
                    blocks.stream().skip(e.level.getRandom().nextInt(blocks.size())).findFirst().ifPresent(pos -> e.spawnGhost(level, pos));
                }
            }
        }
        //Handle destruction --------------------------------
        if (e.level != null && e.destructionTimer > 0) {
            if (e.destructionTimer++ % 3 == 0) {
                MotherTreeStructure structure = e.getTreeStructure(false);
                Optional<Set<BlockPos>> hierarchy = structure.popHierarchy();
                if (hierarchy.isPresent()) {
                    for (BlockPos p : hierarchy.get()) {
                        if (level.getBlockState(p).getBlock() instanceof IRemainsBlock) {
                            level.setBlock(p, Blocks.AIR.defaultBlockState(), 3);
                            ModParticles.spawnParticlesServer(level, new DustParticleOptions(1, -1), p.getX() + 0.5, p.getY() + 0.5, p.getZ() + 0.5f, 20, 0.3, 0.3, 0.3, 0.01);
                            e.level.playSound(null, p, ModSounds.REMAINS_DEATH.get(), SoundSource.BLOCKS, 0.2f, 1f);
                        }
                    }
                } else {
                    //Destruction complete
                    e.destructionTimer = -1;
                    if (e.level != null) {
                        e.level.playSound(null, blockPos, ModSounds.MOTHER_DEATH.get(), SoundSource.BLOCKS, 2f, 0.8f);
                    }
                    e.concludeFight();
                }
            }
        }
        if (level.getGameTime() % 64 == 0) {
            AABB area = e.getArea();
            Stream.concat(e.activePlayers.stream(), e.bossEvent.getPlayers().stream()).distinct().filter(player -> area.distanceToSqr(player.position()) > 1600).toList().forEach(player -> {
                e.bossEvent.removePlayer(player);
                e.activePlayers.remove(player);
            });
            AABB inflate = area.inflate(5, 5, 5);
            AABB inflate2 = inflate.inflate(10, 10, 10);
            if (!e.activePlayers.isEmpty()) {
                inflate = inflate.inflate(10, 10, 10);
                inflate2 = inflate2.inflate(20, 10, 20);
            }
            if (e.isIntact()) {
                level.getEntitiesOfClass(ServerPlayer.class, inflate).forEach(e::addPlayer);
            }
            level.getEntitiesOfClass(ServerPlayer.class, inflate2).forEach(e::addPlayerToBossEvent);
        }
    }

@Override
    public void tick() {
        LivingEntity target = summonedEntity.getTarget();
        // If the target vanished mid-swing, abort the swing so shouldContinue() returns false
        // next tick and MOVE/LOOK get released — otherwise FollowSummonerGoal can never start.
        if (target == null || !target.isAlive()) {
            swingTick = -1;
            return;
        }
        // Lock onto the target — every tick the melee goal is active, the entity faces
        // its target without the 30°/tick smoothing lag of `lookAt`.
        summonedEntity.lockRotationTo(target);

        boolean inRange = isTargetInRange(target);

        // Begin a new swing only when not currently swinging, in range, and fully recovered.
        // Recovery uses vanilla LivingEntity.lastAttackTime: onAttacking(target) below sets it
        // to the current age, mirroring how PlayerEntity.getAttackCooldownProgress works.
        if (swingTick < 0 && inRange && attackCooldownProgress() >= 1F) {
            swingTick = 0;
            summonedEntity.onAttacking(target); // saves vanilla lastAttackTime = age
            summonedEntity.onAttackAnimated(config.duration, summonedEntity.pickVariant(config.animation_variants));
            summonedEntity.playConfiguredSound(config.swing_sound);
//            SummonedEntity.LOGGER.info("[WindupMelee] attack-start entity={} target={} duration={} windup={}->tick{} radius={} interval={}",
//                    summonedEntity.getId(), target.getId(),
//                    config.duration, config.windup, windupTick(), config.radius, swingInterval());
        }

        // Navigation: hold inside the (smaller) desired range — held back from full
        // attack reach so the entity doesn't bump into the target. Pursue otherwise,
        // slowed to movement_modifier × movement_speed during a swing.
        boolean atHoldRange = summonedEntity.squaredDistanceTo(target) <= squaredHoldRange(target);
        double moveSpeed = (swingTick >= 0)
                ? config.movement_speed * config.movement_modifier
                : config.movement_speed;
        navUpdateCountdown--;
        if (atHoldRange) {
            summonedEntity.getNavigation().stop();
        } else if (moveSpeed > 0) {
            if (navUpdateCountdown <= 0) {
                summonedEntity.getNavigation().startMovingTo(target, moveSpeed);
                navUpdateCountdown = 5;
            }
        } else {
            summonedEntity.getNavigation().stop();
        }

        // Drive swing progression.
        if (swingTick >= 0) {
            if (swingTick == windupTick()) {
                // Re-check reach with in-progress tolerance: if the target drifted only
                // slightly out during the windup the swing still connects; only a clear
                // dodge whiffs it.
                boolean hit = isTargetInRange(target, IN_PROGRESS_RANGE_TOLERANCE);
//                SummonedEntity.LOGGER.info("[WindupMelee] attack-impact entity={} target={} tick={} hit={}",
//                        summonedEntity.getId(), target.getId(), swingTick, hit);
                if (hit) {
                    performAttackImpact(target);
                }
            }
            swingTick++;
            if (swingTick >= config.duration) {
                swingTick = -1;
                // No explicit ATTACK_ANIMATION stop needed: the client auto-stops the
                // animation when `age - startAge >= duration`. Every new swing carries a
                // fresh monotonic startAge in the packed tracker, so back-to-back swings
                // always re-sync even if variant and duration repeat.
                summonedEntity.onActionCompleted(SummonBehaviour.Action.Type.MELEE_ATTACK, null);
            }
        }
    }

public boolean renderOverlay(GuiGraphicsExtractor guiGraphics, Player player, int height) {
        SwimData swimData = PlatformServices.getPlatformHelper().getSwimData(player);
        if (!ModDataComponents.SWIM_IN_AIR.on(player).includeItemsOnCooldown().findAny() || swimData == null) {
            return false;
        }

        GuiAccessor gui = (GuiAccessor) Minecraft.getInstance().gui;
        boolean isLosingCharge = swimData.shouldDepleteSwimFlyingCharge(player);

        // duration in ticks to fully charge/deplete
        int maxProgress = isLosingCharge
                ? SwimInAir.getMaxFlightDuration(player)
                : SwimInAir.getRechargeDuration(player);

        // current charging/depletion level, in ticks
        int progress = (int) Math.floor(swimData.getSwimFlyingCharge() * maxProgress);

        if (!isLosingCharge && progress >= maxProgress) {
            // fully charged and not depleting
            return false;
        }

        int hotbarEdge = guiGraphics.guiWidth() / 2 + 91;
        // Set height from bottom of screen, add config offset
        height = guiGraphics.guiHeight() - height - Artifacts.CONFIG.client.heliumFlamingoOverlayOffset.get();

        // the number of full bubbles (rendered right to left, index starting at 1)
        int fullBubble = getCurrentAirSupplyBubble(progress, maxProgress, -AIR_BUBBLE_POPPING_DURATION);
        // the location of the currently popping bubble sprite
        // only rendered when poppingBubble > fullBubble,
        // i.e. for AIR_BUBBLE_POPPING_DURATION ticks after a full bubble disappears
        int poppingBubble = getCurrentAirSupplyBubble(progress, maxProgress, 0);
        // the location of the rightmost empty bubble sprite
        // nothing is rendered for EMPTY_AIR_BUBBLE_DELAY_DURATION ticks after a bubble pops
        int emptyBubble = getCurrentAirSupplyBubble(progress, maxProgress, EMPTY_AIR_BUBBLE_DELAY_DURATION);

        if (!isLosingCharge) {
            // reset last bubble popped when recharging
            lastBubblePopSoundPlayed = 0;
        }

        for (int currentBubble = 1; currentBubble <= NUM_AIR_BUBBLES; ++currentBubble) {
            Identifier bubbleSprite = null;
            if (currentBubble <= fullBubble) {
                bubbleSprite = AIR_SPRITE;
            } else if (currentBubble == poppingBubble && isLosingCharge) {
                bubbleSprite = AIR_POPPING_SPRITE;
                playAirBubblePoppedSound(currentBubble, player, NUM_AIR_BUBBLES - emptyBubble);
            } else if (!isLosingCharge || currentBubble > emptyBubble) {
                bubbleSprite = AIR_EMPTY_SPRITE;
            }

            if (bubbleSprite != null) {
                int x = hotbarEdge - (currentBubble - 1) * AIR_BUBBLE_SEPARATION - AIR_BUBBLE_SIZE;
                // randomly offset the vertical height by 1 pixel every other tick
                // frequency increases as air depletes, starting at 6 bubbles left and maxing out at 2 bubbles left
                int y = height;
                if (isLosingCharge
                        && gui.getTickCount() % 2 == currentBubble % 2
                        && fullBubble <= 6
                        && gui.getRandom().nextInt(Math.max(1, (int) Math.pow(2, fullBubble - 2))) == 0
                        && gui.getRandom().nextBoolean()
                ) {
                    y += 1;
                }
                guiGraphics.blitSprite(RenderPipelines.GUI_TEXTURED, bubbleSprite, x, y, AIR_BUBBLE_SIZE, AIR_BUBBLE_SIZE);
            }
        }

        return true;
    }

