@Override
    public void tick() {
        super.tick();
        this.setYRot(this.getYHeadRot());
        this.yBodyRot = this.getYRot();
        this.noPhysics = true;
        this.setNoGravity(true);

        ++this.life;
        if (!this.level.isClientSide) {
            if (!this.sentSpawnEvent) {
                this.level.broadcastEntityEvent(this, (byte)4);
                this.sentSpawnEvent = true;
            }
            if (this.life < 30) {
                Vec3 vector3d;
                if (this.getTarget() != null) {
                    vector3d = this.getTarget().getEyePosition(1.0F);
                    MobUtil.instaLook(this, this.getTarget());
                } else {
                    vector3d = this.getViewVector(1.0F);
                    MobUtil.instaLook(this, vector3d);
                }
                double dx = this.getX() - vector3d.x();
                double dy = this.getY() - vector3d.y();
                double dz = this.getZ() - vector3d.z();
                double d0 = Math.sqrt(dx * dx + dy * dy + dz * dz);
                double velocity = 2.0D;
                double xPower = -(dx / d0 * velocity * 0.2D);
                double yPower = -(dy / d0 * velocity * 0.2D);
                double zPower = -(dz / d0 * velocity * 0.2D);
                this.chargePos = new Vec3(xPower, yPower, zPower);
                this.keepYRot = this.getYRot();
                this.keepXRot = this.getXRot();
            } else {
                this.setYRot(this.keepYRot);
                this.setXRot(this.keepXRot);
                if (!this.sentAttackEvent) {
                    this.level.broadcastEntityEvent(this, (byte)5);
                    this.sentAttackEvent = true;
                }
                if (this.chargePos != null) {
                    this.setDeltaMovement(this.chargePos);
                }
                if (this.life <= 40) {
                    for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                        if (!this.hitEntities.contains(livingEntity) && !MobUtil.areAllies(this.getOwner() != null ? this.getOwner() : this, livingEntity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                            DamageSource damageSource = this.damageSources().mobAttack(this);
                            if (this.getOwner() != null){
                                damageSource = ModDamageSource.summonAttack(this, this.getOwner());
                            }
                            if (livingEntity.hurt(damageSource, AttributesConfig.BlackBeastDamage.get().floatValue())) {
                                this.hitEntities.add(livingEntity);
                            }
                        }
                    }
                } else {
                    this.setDeltaMovement(this.getDeltaMovement().scale(0.25D));
                }
            }
            if (this.life >= 70) {
                this.discard();
            }
        } else {
            if (this.life > 10 && this.life < 50 && this.alpha < 1.0F){
                this.alpha = Mth.clamp(this.alpha + 0.1F, 0.0F, 1.0F);
            }
            if (this.life >= 50){
                this.alpha = Mth.clamp(this.alpha - 0.05F, 0.0F, 1.0F);
            }
        }
    }

public void dealDamageTo(LivingEntity target) {
        LivingEntity owner = this.getOwner();
        float damage = 4.0F;
        if (this.tickCount >= 14){
            damage = 2.0F;
        }
        if (target.isAlive() && !target.isInvulnerable() && target != owner) {
            if (target.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES)){
                return;
            }
            if (owner == null) {
                boolean flag = target.getType().is(EntityTypeTags.FREEZE_HURTS_EXTRA_TYPES);
                if (flag){
                    damage *= 2.0F;
                }
                if (target.hurt(this.damageSources().freeze(), damage)){
                    target.invulnerableTime = 16;
                }
            } else {
                if (owner instanceof Mob mobOwner) {
                    if (mobOwner instanceof Enemy && target instanceof Enemy) {
                        if (mobOwner.getTarget() != target) {
                            return;
                        }
                    }
                    if (mobOwner instanceof IOwned owned){
                        if (owned.getTrueOwner() != null){
                            if (MobUtil.areAllies(owned.getTrueOwner(), target)){
                                return;
                            }
                        }
                    }
                }
                if (MobUtil.areAllies(owner, target)){
                    return;
                }
                if (owner instanceof Mob) {
                    if (owner.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                        damage = (float) owner.getAttributeValue(Attributes.ATTACK_DAMAGE);
                        if (damage < 1){
                            damage = 1.0F;
                        }
                        if (this.tickCount >= 14){
                            damage /= 2.0F;
                        }
                    }
                } else {
                    damage += this.getExtraDamage();
                }
                DamageSource damageSource = ModDamageSource.iceBouquet(this, owner);
                if (this.isTrap()) {
                    damageSource = ModDamageSource.getDamageSource(this.level, ModDamageSource.ICE_BOUQUET);
                }
                if (target.hurt(damageSource, damage)){
                    target.invulnerableTime = 16;
                    if (owner instanceof Player player) {
                        if (target.isAlive() && this.isSoulEating() && SEHelper.getSoulGiven(target) > 0) {
                            SEHelper.increaseSouls(player, 1);
                        }
                        if (this.isTrap()) {
                            target.lastHurtByPlayer = player;
                            target.lastHurtByPlayerTime = 100;
                        }
                    }
                    if (this.isTrap()) {
                        target.lastHurtByMob = owner;
                        target.lastHurtByMobTimestamp = 100;
                    }
                }
            }
        }
    }

@Override
    public void tickServer() {
        super.tickServer();

        // Only does generation ticks for the main block
        if(!isBounding(this)) {
            final Level level = nonNullLevel();

            // Updates air generation amount every 5 ticks
            if (level.getGameTime() % 5 == 0) {
                float baseModifier = PneumaticValues.PRODUCTION_SOLAR_COMPRESSOR *
                        this.getSpeedUsageMultiplierFromUpgrades();
                float heatModifier = getHeatEfficiency();
                float configModifier = ConfigHelper.common().machines.solarCompressorMultiplier.get().floatValue();

                airPerTick = baseModifier * heatModifier * configModifier;
            }

            // Sets if the compressor can see the sun
            canSeeSunlight();

            // Generates air only when sky is visible and during day
            if (canGenerateAir()) {
                // Resets thermal resistance
                heatExchanger.setThermalResistance(1);

                airBuffer += airPerTick;

                if (airBuffer >= 1f) {
                    int toAdd = (int) airBuffer;
                    this.addAir(toAdd);
                    airBuffer -= toAdd;

                    // Heats up compressor proportionate to how much air is being generated
                    double heatToAdd = Math.round(toAdd / 20d) + 2;
                    heatExchanger.addHeat(heatToAdd);
                }
            }

            // Prevents heat loss when the compressor is inactive to make managing a stable heat easier
            else {
                heatExchanger.setThermalResistance(1000000000);
            }

            // Emits smoke particles if overheating
            if (heatExchanger.getTemperature() < MAX_TEMPERATURE
                    && heatExchanger.getTemperature() > WARNING_TEMPERATURE) {

                // Only emits smoke particles once every second
                if (level.getGameTime() % 20 == 0) {
                    BlockPos mainPos = getBlockPos();
                    if (!level.isClientSide()) {
                        ((ServerLevel) level).sendParticles(
                                ParticleTypes.SMOKE,
                                mainPos.getX() + 0.5,
                                mainPos.getY() + 1.2,
                                mainPos.getZ() + 0.5,
                                10,
                                0,
                                0,
                                0,
                                0.05);
                    }
                }
            }

            // Breaks compressor if overheated
            if (!isBroken && (heatExchanger.getTemperature() > MAX_TEMPERATURE)) {
                breakCompressor();
            }
        }
    }

@Override
	public void registerEntryTypes(EntryTypeRegistry registry) {
		registry.register(EntityEntryDefinition.ENTITY_TYPE, ENTITY_DEFINITION);
		registry.register(BlockStateEntryDefinition.BLOCKSTATE, BLOCKSTATE_DEFINITION);

		registry.registerBridge(VanillaEntryTypes.ITEM, EntityEntryDefinition.ENTITY_TYPE, object -> {
			Optional<Stream<EntryStack<Entity>>> stream;

			ItemStack stack = object.getValue();

			try {
				Entity entity;

				if (stack.getItem() instanceof DeferredSpawnEggItem spawnEggItem) {
					EntityType<?> type = spawnEggItem.getType(stack);

					entity = EntityRenderingUtil.fetchEntity(type, Minecraft.getInstance().level);
				} else {
					entity = createItemEntity(stack);
				}

				stream = Optional.of(Stream.of(EntryStack.of(ENTITY_DEFINITION, entity)));
			} catch (Exception e) {
				stream = Optional.empty();
				TwilightForestMod.LOGGER.error("Caught an error assigning an entity to a stack!", e);
			}

			return stream.map(CompoundEventResult::interruptTrue).orElseGet(CompoundEventResult::pass);
		});

		registry.registerBridge(EntityEntryDefinition.ENTITY_TYPE, VanillaEntryTypes.ITEM, object -> {
			Optional<Stream<EntryStack<ItemStack>>> stream = Optional.empty();

			Entity entity = EntityRenderingUtil.fetchEntity(object.getValue().getType(), Minecraft.getInstance().level);

			ItemStack stack = null;

			if (entity instanceof ItemEntity itemEntity) {
				stack = itemEntity.getItem();
			} else if (entity != null) {
				Item spawnEggItem = DeferredSpawnEggItem.byId(entity.getType());

				if (spawnEggItem != null) stack = spawnEggItem.getDefaultInstance();
			}

			if (stack != null) {
				stream = Optional.of(Stream.of(EntryStacks.of(stack)));
			}

			return stream.map(CompoundEventResult::interruptTrue).orElseGet(CompoundEventResult::pass);
		});

		registry.registerBridge(VanillaEntryTypes.ITEM, BlockStateEntryDefinition.BLOCKSTATE, object -> {
			Optional<Stream<EntryStack<BlockState>>> stream = Optional.empty();

			if (object.getValue().getItem() instanceof BlockItem block) {
				stream = Optional.of(Stream.of(EntryStack.of(BLOCKSTATE_DEFINITION, block.getBlock().defaultBlockState())));
			}

			return stream.map(CompoundEventResult::interruptTrue).orElseGet(CompoundEventResult::pass);
		});

		registry.registerBridge(BlockStateEntryDefinition.BLOCKSTATE, VanillaEntryTypes.ITEM, object -> {
			Optional<Stream<EntryStack<ItemStack>>> stream = Optional.empty();

			if (object.getValue().getBlock().asItem() != Items.AIR) {
				stream = Optional.of(Stream.of(EntryStacks.of(new ItemStack(object.getValue().getBlock()))));
			}

			return stream.map(CompoundEventResult::interruptTrue).orElseGet(CompoundEventResult::pass);
		});
	}

@Override
	public void update() {
		super.update();

		if (suckingCooldown > 0) {
			suckingCooldown--;
			//markDirty();
		}

		if (!((BlockCraftingPlate) getBlockType()).testStructure(getWorld(), getPos()).isEmpty()) return;

		if (getStructurePos() != getPos()) {
			setStructurePos(getPos());
			markDirty();
		}

		if (!ManaManager.isManaFull(getWizardryCap())) {
			for (BlockPos relative : poses) {
				BlockPos target = getPos().add(relative);
				TileEntity tile = world.getTileEntity(target);
				if (tile instanceof TileOrbHolder) {
					if (!((TileOrbHolder) tile).isPartOfStructure() || ((TileOrbHolder) tile).canGiveToOutside() || !((TileOrbHolder) tile).canSuckFromOutside()) {
						((TileOrbHolder) tile).setStructurePos(getPos());
						((TileOrbHolder) tile).setCanGiveToOutside(false);
						((TileOrbHolder) tile).setCanSuckFromOutside(true);
						tile.markDirty();
					}
				}
			}
		}

		if (!world.isRemote) {
			for (EntityItem entityItem : world.getEntitiesWithinAABB(EntityItem.class, new AxisAlignedBB(pos))) {
				if (entityItem.getItem().isEmpty()) continue;
				if (hasInput()) break;

				if (!isInventoryEmpty() && CraftingPlateRecipeManager.doesRecipeExistForItem(entityItem.getItem())) {

					ItemStack stack = entityItem.getItem().copy();
					stack.setCount(1);
					entityItem.getItem().shrink(1);

					input.getHandler().insertItem(0, stack, false);

					PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(getPos(), stack), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

				} else if (!(CraftingPlateRecipeManager.doesRecipeExistForItem(entityItem.getItem()))) {

					ItemStack stack = entityItem.getItem().copy();
					stack.setCount(1);

					ItemStack left = ItemHandlerHelper.insertItem(realInventory.getHandler(), stack, false);
					if (left.isEmpty()) {
						entityItem.getItem().shrink(1);
						PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(getPos(), stack), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
					}
				}
			}
		}

		boolean done = CraftingPlateRecipeManager.tick(world, pos, getInput(), realInventory.getHandler(), this::suckMana);
		if (done) {
			ItemStack inputStack = input.getHandler().extractItem(0, 1, false);
			if (!inputStack.isEmpty()) {
				output.getHandler().insertItem(0, inputStack, false);
				for (int i = 0; i < realInventory.getHandler().getSlots(); i++)
					realInventory.getHandler().setStackInSlot(i, ItemStack.EMPTY);
				PacketHandler.NETWORK.sendToAllAround(new PacketClearCraftingPlate(pos), new NetworkRegistry.TargetPoint(world.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 128));
			}
			markDirty();
		}
	}

public void handleUpdate(@Nullable Direction search)
	{
		//Recalculate dynamo attachment
		IEBlockCapabilityCache<IRotationAcceptor> facingCap = IEBlockCapabilityCaches.forNeighbor(IRotationAcceptor.CAPABILITY, this, this::getFacing);
		IEBlockCapabilityCache<IRotationAcceptor> oppositeCap = IEBlockCapabilityCaches.forNeighbor(IRotationAcceptor.CAPABILITY, this, () -> getFacing().getOpposite());
		dynamo = facingCap.getCapability()==null?oppositeCap: facingCap;
		//Search for the waterwheel with the dynamo, or process the update if we have the connected dynamo
		if(dynamo.getCapability()!=null)
		{
			//Get the direction to step in
			Direction step = facingCap.getCapability()==null?getFacing(): getFacing().getOpposite();
			//Set power & speed to zero to start calculation
			powerOut = 0;
			speed = 0;
			//Calculate the new torque this wheel will produce
			if (!this.isBlocked())
			{
				//Number of wheels in a row, determined to be at least one
				int wheels = 1;
				//Get total torque across all connected wheels up to maximum, and check how many connected wheels there are
				double torque = getIFScaledTorque();
				for(int i = 1; i < MAX_WHEELS; i++)
				{
					BlockEntity be = SafeChunkUtils.getSafeBE(level, getBlockPos().relative(step, i));
					if(be instanceof WatermillBlockEntity watermill)
						if(watermill.isBlocked())
							break;
						else
							torque += watermill.getIFScaledTorque();
					else
						break;
					wheels++;
				}
				//Calculate torque to use for this wheel
				powerOut = Math.abs(torque);
				speed = 0.00025*torque/wheels;
			}
			//Update client with the data we just set
			level.sendBlockUpdated(getBlockPos(), level.getBlockState(getBlockPos()), level.getBlockState(getBlockPos()), 3);
			//Updated connected waterwheels with torque & speed
			boolean blocked = false;
			for(int i=1; i < MAX_WHEELS; i++)
			{
				BlockPos pos = getBlockPos().relative(step, i);
				BlockEntity be = SafeChunkUtils.getSafeBE(level, pos);
				if(be instanceof WatermillBlockEntity watermill)
				{
					blocked = blocked || watermill.isBlocked();
					watermill.speed = blocked?0: speed;
					watermill.rotation = blocked?0: rotation;
				}
				//Update client with the data we just set
				level.sendBlockUpdated(pos, level.getBlockState(pos), level.getBlockState(pos), 3);
			}
		}
		//Start the search and go both directions as necessary
		else if(search==null)
		{
			BlockEntity be = SafeChunkUtils.getSafeBE(level, getBlockPos().relative(getFacing()));
			if(be instanceof WatermillBlockEntity watermill) watermill.handleUpdate(getFacing());
			be = SafeChunkUtils.getSafeBE(level, getBlockPos().relative(getFacing().getOpposite()));
			if(be instanceof WatermillBlockEntity watermill) watermill.handleUpdate(getFacing().getOpposite());
		}
		//Continue the search if we haven't found the dynamo yet
		else
		{
			BlockEntity be = SafeChunkUtils.getSafeBE(level, getBlockPos().relative(search));
			if(be instanceof WatermillBlockEntity watermill) watermill.handleUpdate(search);
		}
		//Set this block's deferred update tick to -1
		deferredUpdateTick = Long.MAX_VALUE;
		//Mark chunk dirty so data saves
		markChunkDirty();
	}

