@Override
    public void inventoryTick(ItemStack stack, Level level, Entity entity, int itemSlot, boolean isSelected)
    {
        if (!level.isClientSide && entity instanceof LivingEntity living && living.tickCount % 5 == 0)
        {
            boolean shouldBeOn = false;
            try
            {
                if (!(isSelected || living.getOffhandItem() == stack || CompatManager.Curios.hasCurio(living, stack)))
                {   return;
                }
                double max = Temperature.get(living, Temperature.Trait.BURNING_POINT);

                double temp = Temperature.getModifier(living, Temperature.Trait.WORLD, SoulLampTempModifier.class)
                              .map(mod -> mod.getLastInput(Temperature.Trait.WORLD)).orElseGet(() -> Temperature.get(living, Temperature.Trait.WORLD));

                // Is in valid dimension
                if ((ConfigSettings.LAMP_DIMENSIONS.get(level.registryAccess()).contains(level.dimensionType()))
                // Is world temp more than max
                && temp > max && getFuel(stack) > 0)
                {
                    shouldBeOn = true;
                    // Drain fuel
                    if (!(living instanceof Player player && player.isCreative() || living.isSpectator()))
                    {   addFuel(stack, -0.005 * CSMath.clamp(temp - max, 1, 3));
                    }

                    // Affect nearby players
                    double radius = 5d;
                    AABB bb = new AABB(living.getX() - radius, living.getY() + (living.getBbHeight() / 2) - radius, living.getZ() - radius,
                                       living.getX() + radius, living.getY() + (living.getBbHeight() / 2) + radius, living.getZ() + radius);

                    if (Math.random() < 0.6)
                    {
                        AABB bb2 = bb.inflate(-3);
                        double x = bb2.minX + (bb2.maxX - bb2.minX) * Math.random();
                        double y = bb2.minY + (bb2.maxY - bb2.minY) * Math.random();
                        double z = bb2.minZ + (bb2.maxZ - bb2.minZ) * Math.random();
                        double xSpeed = (Math.random() - 0.5) * 0.02;
                        double zSpeed = (Math.random() - 0.5) * 0.02;
                        new ParticleBatchMessage(0).addParticle(ParticleTypes.SOUL_FIRE_FLAME, x, y, z, xSpeed, 0, zSpeed)
                                                   .sendEntity(living);
                    }

                    for (LivingEntity ent : WorldHelper.getEntitiesOfClass(LivingEntity.class, level, bb, e -> true))
                    {
                        if (!EntityTempManager.isTemperatureEnabled(ent))
                        {   continue;
                        }
                        // Extend modifier time if it is present
                        Optional<SoulLampTempModifier> mod = Temperature.getModifier(ent, Temperature.Trait.WORLD, SoulLampTempModifier.class);
                        if (mod.isPresent())
                        {   mod.get().setTicksExisted(0);
                        }
                        else
                        {   Temperature.replaceOrAddModifier(ent, new SoulLampTempModifier().expires(5).tickRate(5), Temperature.Trait.WORLD, Matcher.SAME_CLASS);
                        }
                    }
                }
            }
            finally
            {
                // If the conditions are not met, turn off the lamp
                if (isLit(stack) != shouldBeOn)
                {
                    setLit(stack, shouldBeOn);
                    if (getFuel(stack) < 0.5)
                    {   setFuel(stack, 0);
                    }
                    WorldHelper.playEntitySound(shouldBeOn ? ModSounds.SOUL_LAMP_ON : ModSounds.SOUL_LAMP_OFF, living, living.getSoundSource(), 1.5f, (float) Math.random() / 5f + 0.9f);
                }
            }
        }
    }

@SubscribeEvent
        public static void onLivingHurt3(LivingDamageEvent.Pre event) {
            if (!(event.getSource().getEntity() instanceof LivingEntity attacker))
                return;

            var rings = EntityUtils.findEquippedCurios(attacker, RelicsItems.RING_OF_THE_SEVEN_DEADLY_SINS.get(), stack -> {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                return relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").canPlayerUse(attacker);
            });

            if (rings.isEmpty())
                return;

            var now = attacker.level().getGameTime();
            var baseDamage = event.getNewDamage();
            var totalModifier = 1D;
            var ringModifiers = new ArrayList<Double>(rings.size());

            for (var stack : rings) {
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();

                if (!TargetingUtils.canHarm(attacker, event.getEntity(), stack, "wrath")) {
                    ringModifiers.add(1D);
                    continue;
                }

                var windowTicks = Math.max(1, (int) Math.round(relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("window").getValue() * 20D));
                var state = stack.getOrDefault(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_WRATH.get(), WrathData.create(now));
                var delta = now - state.lastHitTick();

                double modifier = 1D;

                if (delta < windowTicks) {
                    var mid = windowTicks / 2D;
                    var earlyMultiplier = relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("early_multiplier").getValue();
                    var lateMultiplier = relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatData("late_multiplier").getValue();

                    if (delta <= mid) {
                        var t = delta / mid;
                        var start = 1D + earlyMultiplier;

                        modifier = start + (1D - start) * t;
                    } else {
                        var t = (delta - mid) / Math.max(1D, windowTicks - mid);
                        var end = 1D - lateMultiplier;

                        modifier = 1D + (end - 1D) * t;
                    }
                }

                ringModifiers.add(modifier);
                totalModifier *= modifier;
            }

            event.setNewDamage((float) (baseDamage * totalModifier));

            for (var i = 0; i < rings.size(); i++) {
                var stack = rings.get(i);
                var relic = (RingOfTheSevenDeadlySinsItem) stack.getItem();
                var modifier = ringModifiers.get(i);
                var extraDamage = baseDamage * (modifier - 1D);

                relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("windows").addValue(1);
                relic.getRelicData(attacker, stack).getLevelingData().addExperience("wrath", "timing", Math.abs(extraDamage));

                if (extraDamage > 0)
                    relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("bonus_damage").addValue(extraDamage);
                else if (extraDamage < 0)
                    relic.getRelicData(attacker, stack).getAbilitiesData().getAbilityData("wrath").getStatisticData().getMetricData("reduced_damage").addValue(Math.abs(extraDamage));

                stack.set(RelicsDataComponents.RING_OF_THE_SEVEN_DEADLY_SINS_WRATH.get(), new WrathData(now));
            }
        }

public void updateFloors(boolean notifyClient) {
        ElevatorBaseBlockEntity core = getCoreElevatorOrSelf();
        if (core != this) {
            core.updateFloors(notifyClient);
            return;
        }

        Level level = nonNullLevel();
        if (level.getGameTime() - lastFloorUpdate > 20) {
            callerList.clear();
            floorList.clear();
            if (multiElevators != null) {  // should always be the case, even if only a single member
                int yOffset = 0;
                int worldHeight = level.dimensionType().logicalHeight();
                BlockPos.MutableBlockPos mut = new BlockPos.MutableBlockPos();
                scanLoop: while (worldPosition.getY() + yOffset < worldHeight - 2) {
                    boolean registeredThisFloor = false;
                    for (ElevatorBaseBlockEntity base : multiElevators) {
                        for (Direction dir : Direction.Plane.HORIZONTAL) {
                            mut.set(base.getBlockPos());
                            mut.move(dir.getStepX(), yOffset + 2, dir.getStepZ());
                            if (base.nonNullLevel().getBlockState(mut).getBlock() == ModBlocks.ELEVATOR_CALLER.get()) {
                                callerList.add(mut.immutable());
                                if (!registeredThisFloor) floorList.add(yOffset);
                                registeredThisFloor = true;
                            }
                        }
                    }
                    yOffset++;
                    for (ElevatorBaseBlockEntity base : multiElevators) {
                        if (base.nonNullLevel().getBlockState(base.getBlockPos().above(yOffset)).getBlock() != ModBlocks.ELEVATOR_FRAME.get()) {
                            break scanLoop;
                        }
                    }
                }

                for (ElevatorBaseBlockEntity base : multiElevators) {
                    base.floorHeights = floorList.intStream().toArray();
                }
            }
            lastFloorUpdate = level.getGameTime();
        }

        ElevatorButton[] elevatorButtons = layoutElevatorButtons();

        if (multiElevators != null) {
            for (ElevatorBaseBlockEntity base : multiElevators) {
                base.floorNames = new Int2ObjectOpenHashMap<>(floorNames);
            }
            copyClientFacingStateToVerticalStacks(level);
        }

        for (BlockPos p : callerList) {
            BlockEntity te = level.getBlockEntity(p);
            if (te instanceof ElevatorCallerBlockEntity caller) {
                int callerFloorHeight = p.getY() - getBlockPos().getY() - 2;
                int callerFloor = -1;
                for (ElevatorButton floor : elevatorButtons) {
                    if (floor.floorHeight == callerFloorHeight) {
                        callerFloor = floor.floorNumber;
                        break;
                    }
                }
                if (callerFloor == -1) {
                    Log.error("Error while updating elevator floors! This will cause a indexOutOfBoundsException, index = -1");
                }
                caller.setEmittingRedstone(PneumaticCraftUtils.epsilonEquals(targetExtension, extension, 0.1)
                        && PneumaticCraftUtils.epsilonEquals(extension, callerFloorHeight, 0.1));
                caller.setFloors(elevatorButtons, callerFloor);
            }
        }

        if (notifyClient && !level.isClientSide) queueStateSyncForConnectedElevators();
    }

public void render(EntityMungus entityIn, float entityYaw, float partialTicks, PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn) {
        super.render(entityIn, entityYaw, partialTicks, matrixStackIn, bufferIn, packedLightIn);
        BlockPos target = entityIn.getBeamTarget();
        if (target != null) {
            float f = 1.0F;
            float f1 = (float) entityIn.level().getGameTime() + partialTicks;
            float f2 = -1.0F * (f1 * 0.15F % 1.0F);
            float f3 = 1.13F;
            if(entityIn.isBaby()){
                f3 = 0.555F;
            }
            matrixStackIn.pushPose();
            matrixStackIn.translate(0.0D, f3, 0.0D);
            Vec3 vector3d = Vec3.upFromBottomCenterOf(target, 0.15F);
            Vec3 vector3d1 = this.getPosition(entityIn, f3, partialTicks);
            Vec3 vector3d2 = vector3d.subtract(vector3d1);
            float f4 = (float) (vector3d2.length());
            vector3d2 = vector3d2.normalize();
            float f5 = (float) Math.acos(vector3d2.y);
            float f6 = (float) Math.atan2(vector3d2.z, vector3d2.x);
            matrixStackIn.mulPose(Axis.YP.rotationDegrees(((Mth.PI / 2F) - f6) * Mth.RAD_TO_DEG));
