public static void apply(Level world, ItemStack wand, Player player, BlockPos pos, BlockState block) {
		checkComponents(wand);
		if (!isEnabled(wand))
			return;
		if (!BlockItem.BY_BLOCK.containsKey(block.getBlock()))
			return;

		Map<BlockPos, BlockState> blockSet = new HashMap<>();
		blockSet.put(pos, block);
		SymmetryMirror symmetry = wand.get(AllDataComponents.SYMMETRY_WAND);

		Vec3 mirrorPos = symmetry.getPosition();
		if (mirrorPos.distanceTo(Vec3.atLowerCornerOf(pos)) > AllConfigs.server().equipment.maxSymmetryWandRange.get())
			return;
		if (!player.isCreative() && isHoldingBlock(player, block)
			&& BlockHelper.findAndRemoveInInventory(block, player, 1) == 0)
			return;

		symmetry.process(blockSet);
		BlockPos to = BlockPos.containing(mirrorPos);
		List<BlockPos> targets = new ArrayList<>();
		targets.add(pos);

		for (BlockPos position : blockSet.keySet()) {
			if (position.equals(pos))
				continue;

			if (world.isUnobstructed(block, position, CollisionContext.of(player))) {
				BlockState blockState = blockSet.get(position);
				for (Direction face : Iterate.directions)
					blockState = blockState.updateShape(face, world.getBlockState(position.relative(face)), world,
						position, position.relative(face));

				if (player.isCreative()) {
					world.setBlockAndUpdate(position, blockState);
					targets.add(position);
					continue;
				}

				BlockState toReplace = world.getBlockState(position);
				if (!toReplace.canBeReplaced())
					continue;
				if (toReplace.getDestroySpeed(world, position) == -1)
					continue;

				if (AllBlocks.CART_ASSEMBLER.has(blockState)) {
					BlockState railBlock = CartAssemblerBlock.getRailBlock(blockState);
					if (BlockHelper.findAndRemoveInInventory(railBlock, player, 1) == 0)
						continue;
					if (BlockHelper.findAndRemoveInInventory(blockState, player, 1) == 0)
						blockState = railBlock;
				} else {
					if (BlockHelper.findAndRemoveInInventory(blockState, player, 1) == 0)
						continue;
				}

				BlockSnapshot blocksnapshot = BlockSnapshot.create(world.dimension(), world, position);
				FluidState ifluidstate = world.getFluidState(position);
				world.setBlock(position, ifluidstate.createLegacyBlock(), Block.UPDATE_KNOWN_SHAPE);
				world.setBlockAndUpdate(position, blockState);

				wand.set(AllDataComponents.SYMMETRY_WAND_SIMULATE, true);
				boolean placeInterrupted = EventHooks.onBlockPlace(player, blocksnapshot, Direction.UP);
				wand.set(AllDataComponents.SYMMETRY_WAND_SIMULATE, false);

				if (placeInterrupted) {
					blocksnapshot.restore(Block.UPDATE_CLIENTS);
					continue;
				}
				targets.add(position);
			}
		}

		CatnipServices.NETWORK.sendToClientsTrackingAndSelf(player, new SymmetryEffectPacket(to, targets));
	}

@Override
    public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, @Nullable LivingEntity target, @Nullable BlockPos targetPos, @Nullable Vec3 hitVec, int chargedTicks) {
        if (!attacker.level().isClientSide) {
            int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
            double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
            int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);
            int overextendLevel = item.getEffectLevel(itemStack, ItemEffect.abilityOverextend);
            boolean overextend = overextendLevel > 0 && !attacker.getFoodData().needsFood();
            ServerPlayer serverPlayer = (ServerPlayer) attacker;

            int cooldown = getCooldown(item, itemStack);
            double damageMultiplier = EffectHelper.getEffectLevel(itemStack, ItemEffect.reap) / 100d;
            double range = EffectHelper.getEffectEfficiency(itemStack, ItemEffect.reap);

            if (overchargeBonus > 0) {
                damageMultiplier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
                range += overchargeBonus * 0.5;
            }

            int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
            int comboPoints = ComboPoints.get(attacker);
            if (comboLevel > 0) {
                damageMultiplier += comboLevel * comboPoints / 100d;
            }

            AtomicInteger kills = new AtomicInteger();
            AtomicInteger revengeKills = new AtomicInteger();
            AtomicInteger hits = new AtomicInteger();
            Vec3 targetVec;
            if (target != null) {
                targetVec = hitVec;
            } else {
                targetVec = Vec3.directionFromRotation(attacker.getXRot(), attacker.getYRot())
                        .normalize()
                        .scale(range)
                        .add(attacker.getEyePosition(0));
            }

            AABB aoe = new AABB(targetVec, targetVec).inflate(range, 1d, range);

            hitEntities(serverPlayer, item, itemStack, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel, momentumEfficiency,
                    kills, revengeKills, hits);

            applyBuff(attacker, kills.get(), hits.get(), hand, item, itemStack, chargedTicks, comboPoints, revengeKills.get());

            attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
                    SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

            item.tickProgression(attacker, itemStack, 1 + kills.get());

            attacker.sweepAttack();

            attacker.causeFoodExhaustion(overextendLevel > 0 ? 6 : 1);

            double exhilarationEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationEfficiency > 0 && kills.get() > 0) {
                cooldown = (int) (cooldown * (1 - exhilarationEfficiency / 100d));
            }

            attacker.getCooldowns().addCooldown(item, cooldown);

            int echoLevel = item.getEffectLevel(itemStack, ItemEffect.abilityEcho);
            if (echoLevel > 0) {
                echoReap(serverPlayer, hand, item, itemStack, chargedTicks, aoe, damageMultiplier, revengeLevel, overextend, overextendLevel,
                        momentumEfficiency, comboPoints);
            }
        }
        attacker.swing(hand, false);

        if (ComboPoints.canSpend(item, itemStack)) {
            ComboPoints.reset(attacker);
        }

        item.applyDamage(2, itemStack, attacker);
    }

@SubscribeEvent
        public static void tickTemperature(LivingEvent.LivingTickEvent event)
        {
            LivingEntity entity = event.getEntity();
            boolean isServer = !entity.level().isClientSide;
            if (!TEMPERATURE_ENABLED_ENTITIES.contains(entity.getType())) return;

            getTemperatureCap(entity).ifPresent(cap ->
            {
                // Tick modifiers serverside
                if (isServer)
                {   cap.tick(entity);
                }

                // Tick modifiers & removed expired
                AtomicBoolean sync = new AtomicBoolean(false);
                for (Trait trait : VALID_MODIFIER_TRAITS)
                {
                    List<TempModifier> modifiers = cap.getModifiers(trait);
                    for (int i = 0; i < modifiers.size(); i++)
                    {
                        TempModifier modifier = modifiers.get(i);
                        // Tick modifier
                        if (modifier.getTicksExisted() % modifier.getTickRate() == 0)
                        {   modifier.tick(entity);
                        }
                        if (isServer)
                        {
                            // Sync if the modifier is dirty
                            if (modifier.isDirty())
                            {   sync.set(true);
                                modifier.markClean();
                            }
                            // Remove expired modifiers
                            int expireTime = modifier.getExpireTime();
                            modifier.setTicksExisted(modifier.getTicksExisted() + 1);
                            if (modifier.getTicksExisted() > expireTime && expireTime != -1)
                            {
                                modifier.onRemoved(entity, trait);
                                Temperature.updateSiblingsRemove(modifiers, entity, trait, modifier);
                                modifiers.remove(i);
                                sync.set(true);
                                i--;
                            }
                        }
                    }
                }
                if (isServer && sync.get())
                {   Temperature.updateModifiers(entity, cap);
                }

                // Spawn particles for uninhabitable entities
                if (isServer && hasClimateData(entity))
                {
                    if (entity.tickCount % 5 == 0 && entity.getRandom().nextDouble() < 0.1)
                    {
                        double worldTemp = cap.getTrait(Trait.WORLD);
                        double entityX = entity.getX();
                        double entityY = entity.getY() + entity.getBbHeight();
                        double entityZ = entity.getZ();

                        if (worldTemp < cap.getTrait(Trait.FREEZING_POINT))
                        {
                            WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_COLD.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                           entity.getRandom().nextInt(2, 4), 0);
                        }
                        else if (worldTemp > cap.getTrait(Trait.BURNING_POINT))
                        {
                            WorldHelper.spawnParticleBatch(entity.level(), ParticleTypesInit.MOB_HOT.get(), entityX, entityY, entityZ, 0.5, 0.5, 0.5,
                                                           entity.getRandom().nextInt(2, 4), 0);
                        }
                    }
                }
            });
        }

public void tick() {
        this.baseTick();
        if (this.life == 2) {
            if (this.level.isClientSide()) {
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.LIGHTNING_BOLT_THUNDER, SoundSource.WEATHER, 10000.0F, 0.8F + this.random.nextFloat() * 0.2F, false);
                this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.WEATHER, 2.0F, 0.5F + this.random.nextFloat() * 0.2F, false);
            } else {
                Difficulty difficulty = this.level.getDifficulty();
                if (difficulty == Difficulty.NORMAL || difficulty == Difficulty.HARD) {
                    this.spawnFire(4);
                }

                this.powerLightningRod();
                clearCopperOnLightningStrike(this.level, this.getStrikePosition());
                this.gameEvent(GameEvent.LIGHTNING_STRIKE);
            }
        }

        --this.life;
        if (this.life < 0) {
            if (this.flashes == 0) {
                if (this.level instanceof ServerLevel serverLevel) {
                    List<Entity> list = this.level.getEntities(this, new AABB(this.getX() - 15.0D, this.getY() - 15.0D, this.getZ() - 15.0D, this.getX() + 15.0D, this.getY() + 6.0D + 15.0D, this.getZ() + 15.0D), (p_147140_) -> p_147140_.isAlive() && !this.hitEntities.contains(p_147140_));

                    for(ServerPlayer serverplayer : serverLevel.getPlayers((p_147157_) -> p_147157_.distanceTo(this) < 256.0F)) {
                        CriteriaTriggers.LIGHTNING_STRIKE.trigger(serverplayer, this, list);
                    }
                }

                this.discard();
            } else if (this.life < -this.random.nextInt(10)) {
                --this.flashes;
                this.life = 1;
                this.seed = this.random.nextLong();
                this.spawnFire(0);
            }
        }

        if (this.life >= 0) {
            if (!(this.level instanceof ServerLevel)) {
                this.level.setSkyFlashTime(2);
            } else if (!this.isVisualOnly()) {
                List<Entity> list1 = this.level.getEntities(this, new AABB(this.getX() - 3.0D, this.getY() - 3.0D, this.getZ() - 3.0D, this.getX() + 3.0D, this.getY() + 6.0D + 3.0D, this.getZ() + 3.0D), this::canHitEntity);

                for(Entity entity : list1) {
                    if (!net.minecraftforge.event.ForgeEventFactory.onEntityStruckByLightning(entity, this)) {
                        entity.thunderHit((ServerLevel) this.level, this);
                    }
                    if (entity instanceof LivingEntity livingEntity) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity)) {
                            boolean flag = false;
                            DamageSource damageSource = this.damageSources().lightningBolt();
                            if (this.getOwner() != null) {
                                if (!MobUtil.areAllies(this.getOwner(), livingEntity)) {
                                    flag = true;
                                    damageSource = ModDamageSource.lightning(this, this.getOwner());
                                }
                            } else {
                                flag = true;
                            }
                            if (flag) {
                                livingEntity.hurt(damageSource, this.getTrueDamage());
                            }
                        }
                    }
                }

                this.hitEntities.addAll(list1);
                if (this.getCause() != null) {
                    CriteriaTriggers.CHANNELED_LIGHTNING.trigger(this.getCause(), list1);
                }
            }
        }

    }

public static void call(ServerPlayer player, ItemStack stack){
        if (stack.getTag() != null) {
            CompoundTag compoundTag = stack.getTag();
            if (player.level instanceof ServerLevel serverLevel) {
                List<LivingEntity> list = new ArrayList<>();
                if (hasSummonType(stack)){
                    EntityType<?> entityType = getSummonType(compoundTag);
                    if (entityType != null){
                        for (Entity entity : serverLevel.getAllEntities()) {
                            if (entity instanceof LivingEntity livingEntity1 && entity.getType() == entityType) {
                                if (MobUtil.getOwner(livingEntity1) != null){
                                    if (MobUtil.getOwner(livingEntity1) == player && !SEHelper.getGroundedEntities(player).contains(livingEntity1)){
                                        list.add(livingEntity1);
                                    }
                                }
                            }
                        }
                    }
                }
                if (!list.isEmpty()) {
                    for (LivingEntity livingEntity1 : list) {
                        LivingEntity original = null;
                        if (livingEntity1.isPassenger() && livingEntity1.getVehicle() instanceof LivingEntity vehicle) {
                            original = livingEntity1;
                            livingEntity1 = vehicle;
                        }
                        if (!livingEntity1.isDeadOrDying()) {
                            BlockPos blockPos = BlockFinder.SummonRadius(player.blockPosition(), livingEntity1, serverLevel);
                            if (player.isShiftKeyDown() || player.isCrouching()) {
                                if (list.size() == 1) {
                                    blockPos = player.blockPosition();
                                }
                            }
                            if (livingEntity1.level.dimension() == player.level.dimension()) {
                                net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity1, blockPos.getX(), blockPos.getY(), blockPos.getZ());
                                if (event.isCanceled()) {
                                    break;
                                }
                                livingEntity1.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                                MobUtil.moveDownToGround(livingEntity1);
                                ModNetwork.sendToALL(new SPlayWorldSoundPacket(player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                                ModNetwork.sendToALL(new SPlayWorldSoundPacket(blockPos, SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                                if (original instanceof IServant servant){
                                    servant.setFollowing();
                                }
                                if (livingEntity1 instanceof IServant servant){
                                    servant.setFollowing();
                                }
                            } else if (player.getServer() != null) {
                                ServerLevel serverWorld = player.getServer().getLevel(player.level.dimension());
                                if (serverWorld != null) {
                                    blockPos = BlockFinder.SummonRadius(player.blockPosition(), livingEntity1, serverWorld);
                                    Vec3 vec3 = new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ());
                                    net.minecraftforge.event.entity.EntityTeleportEvent.EnderEntity event = net.minecraftforge.event.ForgeEventFactory.onEnderTeleport(livingEntity1, blockPos.getX(), blockPos.getY(), blockPos.getZ());
                                    if (event.isCanceled()) {
                                        break;
                                    }
                                    livingEntity1.changeDimension(serverWorld, new ArcaTeleporter(vec3));
                                    livingEntity1.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
                                    MobUtil.moveDownToGround(livingEntity1);
                                    ModNetwork.sendToALL(new SPlayWorldSoundPacket(player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, 1.0F, 1.0F));
                                    if (original instanceof IServant servant){
                                        servant.setFollowing();
                                    }
                                    if (livingEntity1 instanceof IServant servant){
                                        servant.setFollowing();
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

@Override
  public float apply(FluidStack fluid, EffectLevel level, FluidEffectContext.Block context, FluidAction action) {
    // compare our hardness to the block's hardness
    BlockState state = context.getBlockState();
    if (state.isAir()) {
      return 0;
    }
    Level world = context.getLevel();
    BlockPos pos = context.getBlockPos();
    float requirement = state.getDestroySpeed(world, pos);
    if (requirement < 0) {
      return 0;
    }

    // disallow acting if adventure mode and no proper item stack tags
    if (context.breakRestricted()) {
      return 0;
    }

    // 0 hardness means break any block, ignoring hardness
    if (hardness == 0) {
      requirement = 1;
    } else {
      requirement /= hardness;
    }
    // if we had enough level to destroy it, return how much fluid we used
    if (requirement <= level.value()) {
      if (action.execute() && world instanceof ServerLevel server) {
        // handle enchantments by making a fake items stack
        // actual item identity doesn't matter, we are past the point of asking if we can break it
        ItemStack fakeTool = ItemStack.EMPTY;
        if (!enchantments.isEmpty()) {
          fakeTool = new ItemStack(Items.STICK);
          EnchantmentHelper.setEnchantments(enchantments, fakeTool);
        }

        // ensures tile entity is fetched so its around for afterBlockBreak
        BlockEntity te = world.getBlockEntity(pos);
        Block block = state.getBlock();

        // remove the block
        Player player = context.getPlayer();
        boolean removed;
        if (player != null) {
          removed = state.onDestroyedByPlayer(world, pos, player, true, world.getFluidState(pos));
          if (removed) {
            player.awardStat(Stats.BLOCK_MINED.get(block));
          }
        } else {
          removed = world.setBlock(pos, world.getFluidState(pos).createLegacyBlock(), 3);
        }

        // drop resources
        if (removed) {
          state.getBlock().destroy(world, pos, state);

          // determine who to blame for this block breaking, projectile or original entity
          Entity source = context.getProjectile();
          if (source == null) {
            source = context.getEntity();
          }
          LootParams.Builder lootParams = new Builder(server)
            .withParameter(LootContextParams.ORIGIN, context.getHitResult().getLocation())
            .withParameter(LootContextParams.TOOL, fakeTool)
            .withOptionalParameter(LootContextParams.BLOCK_ENTITY, te)
            .withOptionalParameter(LootContextParams.THIS_ENTITY, source);
          state.getDrops(lootParams).forEach(stack -> Block.popResource(world, pos, stack));
          state.spawnAfterBreak(server, pos, fakeTool, player != null);
          world.levelEvent(LevelEvent.PARTICLES_DESTROY_BLOCK, pos, Block.getId(state));
        }
      }
      return requirement;
    }
    return 0;
  }

@Override
    public void onServerEndTick() {
        if (this.updateList) {
            this.updateList = false;
            this.updateCPUClusters();
            lastProcessedCraftingLogicChangeTick = -1; // Ensure caches below are also updated
        }

        this.craftingLinks.values().removeIf(nexus -> nexus.isDead(this.grid, this));

        long latestChange = 0;
        for (var cpu : this.craftingCPUClusters) {
            cpu.craftingLogic.tickCraftingLogic(energyGrid, this);
            latestChange = Math.max(
                    latestChange,
                    cpu.craftingLogic.getLastModifiedOnTick());
        }

        // There's nothing to do if we weren't crafting anything and we don't have any CPUs that could craft
        if (latestChange != lastProcessedCraftingLogicChangeTick) {
            lastProcessedCraftingLogicChangeTick = latestChange;

            Set<AEKey> previouslyCrafting = currentlyCrafting.isEmpty() ? Set.of() : new HashSet<>(currentlyCrafting);
            this.currentlyCrafting.clear();

            for (var cpu : this.craftingCPUClusters) {
                cpu.craftingLogic.getAllWaitingFor(this.currentlyCrafting);
            }

            // Notify watchers about items no longer being crafted, but only if there can be changes and there are
            // watchers
            if (!interests.isEmpty() && !(previouslyCrafting.isEmpty() && currentlyCrafting.isEmpty())) {
                var changed = new HashSet<AEKey>();
                changed.addAll(Sets.difference(previouslyCrafting, currentlyCrafting));
                changed.addAll(Sets.difference(currentlyCrafting, previouslyCrafting));
                for (var what : changed) {
                    for (var watcher : interestManager.get(what)) {
                        watcher.getHost().onRequestChange(what);
                    }
                    for (var watcher : interestManager.getAllStacksWatchers()) {
                        watcher.getHost().onRequestChange(what);
                    }
                }
            }
        }

        // Throttle updates of craftables to once every 10 ticks
        if (lastProcessedCraftableChangeTick != craftingProviders.getLastModifiedOnTick()) {
            lastProcessedCraftableChangeTick = craftingProviders.getLastModifiedOnTick();

            // If everything is empty, there's nothing to do
            if (!currentlyCraftable.isEmpty() || !craftingProviders.getCraftableKeys().isEmpty()
                    || !craftingProviders.getEmittableKeys().isEmpty()) {
                Set<AEKey> previouslyCraftable = currentlyCraftable.isEmpty() ? Set.of()
                        : new HashSet<>(currentlyCraftable);
                this.currentlyCraftable.clear();
                currentlyCraftable.addAll(craftingProviders.getCraftableKeys());
                currentlyCraftable.addAll(craftingProviders.getEmittableKeys());

                // Only perform the change tracking if there are watchers
                if (!interests.isEmpty()) {
                    var changedCraftable = new HashSet<AEKey>();
                    changedCraftable.addAll(Sets.difference(previouslyCraftable, currentlyCraftable));
                    changedCraftable.addAll(Sets.difference(currentlyCraftable, previouslyCraftable));
                    for (var what : changedCraftable) {
                        for (var watcher : interestManager.get(what)) {
                            watcher.getHost().onCraftableChange(what);
                        }
                        for (var watcher : interestManager.getAllStacksWatchers()) {
                            watcher.getHost().onCraftableChange(what);
                        }
                    }
                }
            }
        }
    }

public boolean tickServer(IMultiblockContext<? extends IFurnaceEnvironment<R>> ctx)
	{
		boolean active = false;
		final IFurnaceEnvironment<R> env = ctx.getState();

		if(burnTime > 0)
		{
			int processSpeed = 1;
			if(process > 0)
				processSpeed = env.getProcessSpeed(ctx.getLevel());
			burnTime -= processSpeed;
			if(process > 0)
			{
				if(isAnyInputEmpty(env.getInventory()))
				{
					process = 0;
					processMax = 0;
				}
				else
				{
					R recipe = getRecipe(env);
					if(recipe!=null&&getProcessTime(recipe)!=processMax)
					{
						processMax = 0;
						process = 0;
					}
					else
					{
						process -= processSpeed;
						processSpeed = 0;//Process speed is "used up"
						active = true;
					}
				}
				setChanged.run();
			}

			if(process <= 0)
			{
				if(processMax > 0)
				{
					doRecipeIO(env);
					processMax = 0;
					burnTime -= process;
				}
				R recipe = getRecipe(env);
				if(recipe!=null)
				{
					final int time = getProcessTime(recipe);
					this.process = time-processSpeed;
					this.processMax = time;
					active = true;
				}
			}
		}

		if(burnTime <= 0&&getRecipe(env)!=null)
		{
			final IItemHandlerModifiable inv = env.getInventory();
			final ItemStack fuel = inv.getStackInSlot(fuelSlot);
			final int addedBurntime = env.getBurnTimeOf(ctx.getLevel().getRawLevel(), fuel);
			if(addedBurntime > 0)
			{
				lastBurnTime = addedBurntime;
				burnTime += lastBurnTime;
				if(fuel.hasCraftingRemainingItem()&&fuel.getCount()==1)
					inv.setStackInSlot(fuelSlot, fuel.getCraftingRemainingItem());
				else
					fuel.shrink(1);
				setChanged.run();
			}
		}

		if(!active)
			env.turnOff(ctx.getLevel());
		return active;
	}

private static void onWorldRender(final RenderWorldLastEvent ev) {
		if (occultBlockMap.isEmpty())
			return;

		ArrayList<Integer> expiredBlocks = null;

		for (Map.Entry<Integer, ArrayList<Pair<BlockPos, BlockState>>> entry : occultBlockMap.entrySet()) {
			if (GlobalEvents.tick >= entry.getKey()) {
				if (expiredBlocks == null)
					expiredBlocks = new ArrayList<Integer>();

				expiredBlocks.add(entry.getKey());
			}
			else {
				ArrayList<Pair<BlockPos, BlockState>> invalidBlocks = null;
				Minecraft mc = Minecraft.getInstance();
				MatrixStack matrix = ev.getMatrixStack();
				Vector3d cameraPos = mc.gameRenderer.getMainCamera().getPosition();
				Tessellator tess = Tessellator.getInstance();
				BufferBuilder buff = tess.getBuilder();

				matrix.pushPose();
				matrix.translate(-cameraPos.x(), -cameraPos.y(), -cameraPos.z());

				RenderSystem.pushMatrix();
				RenderSystem.multMatrix(matrix.last().pose());

				RenderSystem.disableTexture();
				RenderSystem.disableDepthTest();
				RenderSystem.depthMask(false);
				RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_LINE);
				RenderSystem.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);
				RenderSystem.enableBlend();
				RenderSystem.lineWidth(4f);

				for (Pair<BlockPos, BlockState> block : entry.getValue()) {
					if (GlobalEvents.tick % 2 == 1 && mc.player.level.getBlockState(block.getFirst()) != block.getSecond()) {
						if (invalidBlocks == null)
							invalidBlocks = new ArrayList<Pair<BlockPos, BlockState>>();

						invalidBlocks.add(block);

						continue;
					}

					Vector4f colour = getColourForBlock(block.getSecond());
					BlockPos pos = block.getFirst();

					RenderSystem.pushMatrix();
					RenderSystem.translated(pos.getX(), pos.getY(), pos.getZ());
					buff.begin(GL_LINES, DefaultVertexFormats.POSITION_COLOR);
					RenderUtil.renderBlockOutline(buff, colour.x(), colour.y(), colour.z(), colour.w());
					tess.end();
					RenderSystem.popMatrix();
				}

				RenderSystem.polygonMode(GL11.GL_FRONT_AND_BACK, GL11.GL_FILL);
				RenderSystem.disableBlend();
				RenderSystem.enableDepthTest();
				RenderSystem.depthMask(true);
				RenderSystem.enableTexture();

				RenderSystem.popMatrix();
				matrix.popPose();

				if (invalidBlocks != null)
					entry.getValue().removeAll(invalidBlocks);
			}
		}

		if (expiredBlocks != null) {
			for (Integer tick : expiredBlocks) {
				occultBlockMap.remove(tick);
			}
		}
	}

@Override
    public void tick(boolean serverSide) {
        ticks++;
        if (ticks < 5)
            return;
        if (!serverSide || level.getGameTime() % 3 != 0)
            return;

        boolean destroyPortal = false;
        boolean placingFrame = !framePos.isEmpty();
        if (placingFrame) {
            BlockPos pos = framePos.get(0);
            framePos.remove(pos);
            BlockState bs = level.getBlockState(pos);
            if (bs.is(BlockTagProvider.DECORATIVE_AN) || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
                tick(true);
                if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                    tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                    tile.tickDuration = 20 * 60;
                    tile.gameTime = level.getGameTime();
                    tile.updateBlock();
                }
                return;
            }
            if (bs.canBeReplaced() || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
                level.setBlock(pos, BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState(), 3);
                if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                    tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                    tile.tickDuration = 20 * 60;
                    tile.gameTime = level.getGameTime();
                    tile.updateBlock();
                }
                level.playSound(null, pos, BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                ParticleUtil.spawnTouchPacket(level, pos, ParticleColor.makeRandomColor(255, 255, 255, level.random));
                placedBlocks.add(pos);
                return;
            } else {
                destroyPortal = true;
                ServerLevel serverLevel = (ServerLevel) level;
                serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
            }
        }
        boolean placingPortal = !portalPos.isEmpty() && framePos.isEmpty() && !destroyPortal;
        if (placingPortal) {
            for (BlockPos pos : portalPos) {
                if (level.getBlockState(pos).canBeReplaced()) {
                    level.setBlock(pos, BlockRegistry.PORTAL_BLOCK.defaultBlockState().setValue(PortalBlock.AXIS, direction.getAxis()), 2);
                    level.playSound(null, pos, BlockRegistry.PORTAL_BLOCK.get().defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                    placedBlocks.add(pos);
                } else {
                    destroyPortal = true;
                    ServerLevel serverLevel = (ServerLevel) level;
                    serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
                    break;
                }
            }
            portalPos.clear();
        }
        if (destroyPortal) {
            for (BlockPos pos : placedBlocks) {
                level.destroyBlock(pos, false);
            }
            level.playSound(null, targetPos, SoundRegistry.GAIA_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
            portalPos.clear();
            framePos.clear();
            return;
        }
        if (portalPos.isEmpty()) {
            level.playSound(null, targetPos.above(2), SoundRegistry.TEMPESTRY_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
            for (BlockPos pos : placedBlocks) {
                if (level.getBlockEntity(pos) instanceof PortalTile portalTile) {
                    portalTile.setFromScroll(warpScrollData);
                }
            }
        }
    }

@Override
    public void tick(ModuleContext moduleContext) {
        IOPStorage storage = moduleContext.getOpStorage();
        if (!(moduleContext instanceof StackModuleContext context && EffectiveSide.get().isServer() && storage != null)) {
            return;
        }

        if (tick++ % 10 == 0) clearCaches();
        markDirty();


        ShieldData shieldData = getShieldData(context.getEntity());
        data.shieldCapacity = shieldData.shieldCapacity();
        double chargeRate = shieldData.shieldRecharge();
        boolean enabled = shieldEnabled.getValue() && getShieldPoints() > 0;

        if (data.shieldPoints > data.shieldCapacity) {
            data.shieldPoints = data.shieldCapacity;
        }

        //# Rendering #
        //Hit Indicator (Controls the effect where the shield flashes brighter when hit)
        if (shieldHitIndicator > 0) {
            shieldHitIndicator -= 0.1F;
        }

        data.shieldVisible = enabled && (alwaysVisible.getValue() || System.currentTimeMillis() - lastHitTime < 5000);
        if (data.shieldVisible && shieldAnim < 1) {
            shieldAnim = Math.min(shieldAnim + 0.05F, 1F);
        } else if (!data.shieldVisible && shieldAnim > 0) {
            shieldAnim = Math.max(shieldAnim - 0.05F, 0F);
        }

        if (data.envDmgCoolDown > 0) data.envDmgCoolDown--;

        //# Logic #
        if (!context.isEquipped()) {
            return;
        }

        if (conflict) {
            data.shieldCapacity = 0;
            data.shieldPoints = 0;
            return;
        }

        //Passive Draw
        if (enabled && storage.getOPStored() > 0) {
            double passiveDraw = data.shieldPoints * data.shieldPoints * EquipCfg.shieldPassiveModifier;
            if (passiveDraw > 0) {
                passivePowerCache += passiveDraw;
                if (passivePowerCache >= 1) {
                    storage.modifyEnergyStored(-(int) passivePowerCache);
                    passivePowerCache = passivePowerCache % 1;
                }
            }
        } else if (enabled && data.shieldPoints > 0) {
            //Shield drains if you run out of power. It takes 60 seconds to drain from full to zero.
            data.shieldPoints = Math.max(0, data.shieldPoints - (data.shieldCapacity / (60D * 20D)));
        }
        if (data.shieldBoost > 0) {
            data.boostTime--;
            if (data.boostTime == 0) {
                data.shieldBoost = 0;
            }
        }

        //Recharge Logic
        if (!enabled) chargeRate *= 1.25;
        if (data.shieldCoolDown > 0) {
            data.shieldCoolDown = Math.max(0, data.shieldCoolDown - (enabled ? 100 : 125));
        } else if (data.shieldPoints < data.shieldCapacity && data.shieldCapacity > 0 && chargeRate > 0 && storage.getOPStored() > 0) {
            double energyPerPoint = Math.max(chargeRate * EquipCfg.energyShieldChg, EquipCfg.energyShieldChg);
            long extracted = storage.modifyEnergyStored(-(int) Math.max(1, Math.min(chargeRate, data.shieldCapacity - data.shieldPoints) * energyPerPoint));
            data.shieldPoints += extracted / energyPerPoint;
        }
    }

@Override
	public void extractRenderState(GuiGraphicsExtractor graphics, int mouseX, int mouseY, float partialTicks) {
		Objects.requireNonNull(minecraft);
		float deltaTicks = Minecraft.getInstance().getDeltaTracker().getRealtimeDeltaTicks();
		ticks += deltaTicks;
		particle:
		if (ticks > nextParticleIn) {
			if (festival == 3) {
				nextParticleIn = ticks;
				if (pendingParticles.isEmpty()) {
					festival3populateNew();
				}
				if (Mth.abs(mouseX - lastMouseX) < 3 && Mth.abs(mouseY - lastMouseY) < 3) {
					break particle;
				}
				lastMouseX = mouseX;
				lastMouseY = mouseY;
				TextParticle particle = pendingParticles.removeFirst();
				particle.x = mouseX;
				particle.y = mouseY;
				particle.gravity = 0F;
				particle.age = 40;
				particles.add(particle);
				persistentParticles.add(particle);
				if (persistentParticles.size() > 50) {
					TextParticle first = persistentParticles.removeFirst();
					first.persistent = false;
				}
			} else if (festival == 1) {
				nextParticleIn = ticks + 10 + random.nextFloat() * 10;
				int color = ARGB.colorFromFloat(1, 1 - random.nextFloat() * 0.6F, 1, 1);
				color |= (random.nextInt(80) + 40) << 24;
				int x = random.nextIntBetweenInclusive(40, width + 100);
				var particle = new TextParticle("❄", x, -20, -0.3F, 0.5f, color, 2F + random.nextFloat());
				particle.gravity = 0F;
				particles.add(particle);
			}
		}
		super.extractRenderState(graphics, mouseX, mouseY, partialTicks);
		int left = width / 2 - 105;
		int top = height / 4 - 20;
		graphics.pose().pushMatrix();
		graphics.pose().translate(left, top);

		float scale = 2F;
		graphics.pose().scale(scale);
		graphics.text(font, ModIdentification.getModFullName(Jade.ID).orElse("Jade"), 0, 0, 0xFFFFFFFF);

		graphics.pose().scale(0.5F);
		titleY.tick(deltaTicks);
		String desc2 = I18n.get("gui.jade.configuration.desc2");
		float scaledX, scaledY;
		if (desc2.isEmpty()) {
			graphics.pose().popMatrix();
			graphics.pose().pushMatrix();
			graphics.pose().translate(left, top);
			scaledX = mouseX - left;
			scaledY = mouseY - top;
		} else {
			scaledX = (mouseX - left) / scale * 2;
			scaledY = (mouseY - top) / scale * 2;
		}
		drawFancyTitle(graphics, I18n.get("gui.jade.configuration.desc1"), Math.min(titleY.value, 20F), 20F, scaledX, scaledY);
		if (!desc2.isEmpty()) {
			drawFancyTitle(graphics, desc2, Math.min(titleY.value + 3F, 32F), 32F, scaledX, scaledY);
		}
		graphics.pose().popMatrix();

		particles.removeIf(p -> {
			p.tick(deltaTicks);
			if (p.y > height + 20) {
				return true;
			}
			p.render(graphics, font, mouseX, mouseY);
			return false;
		});
	}

public static boolean swapLocations(Level initialWorld, BlockPos initialPos, Level finalWorld, BlockPos finalPos, boolean playSound)
	{
        BlockState initialState = initialWorld.getBlockState(initialPos);
        BlockState finalState = finalWorld.getBlockState(finalPos);

        if ((initialState.getBlock().equals(Blocks.AIR) && finalState.getBlock().equals(Blocks.AIR))
                || initialState.is(BloodMagicTags.TELEPOSE_BLOCK_BLACKLIST)
                || finalState.is(BloodMagicTags.TELEPOSE_BLOCK_BLACKLIST)) {
            return false;
        }

        BlockEntity initialTile = initialWorld.getBlockEntity(initialPos);
		BlockEntity finalTile = finalWorld.getBlockEntity(finalPos);
		CompoundTag initialTag = new CompoundTag();
		CompoundTag finalTag = new CompoundTag();

		if (initialTile != null)
			initialTag = initialTile.saveWithFullMetadata();
		if (finalTile != null)
			finalTag = finalTile.saveWithFullMetadata();

		if (playSound)
		{
			initialWorld.playSound(null, initialPos.getX(), initialPos.getY(), initialPos.getZ(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.AMBIENT, 1.0F, 1.0F);
			finalWorld.playSound(null, finalPos.getX(), finalPos.getY(), finalPos.getZ(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.AMBIENT, 1.0F, 1.0F);
		}

		// Finally, we get to do something! (CLEARING TILES)
		if (finalState.getBlock() instanceof EntityBlock)
			finalWorld.removeBlockEntity(finalPos);
		if (initialState.getBlock() instanceof EntityBlock)
			initialWorld.removeBlockEntity(initialPos);

		// TILES CLEARED
		BlockState initialBlockState = initialWorld.getBlockState(initialPos);
		BlockState finalBlockState = finalWorld.getBlockState(finalPos);
		finalWorld.setBlock(finalPos, initialBlockState, 3);
		initialWorld.setBlock(initialPos, finalBlockState, 3);

		if (initialTile != null)
		{
			BlockEntity newTileInitial = finalWorld.getBlockEntity(finalPos);

			// Just in case...
			if (newTileInitial != null)
			{
				newTileInitial.load(initialTag);
			}
		}

		if (finalTile != null)
		{
			BlockEntity newTileFinal = initialWorld.getBlockEntity(initialPos);

			// Just in case...
			if (newTileFinal != null)
			{
				newTileFinal.load(finalTag);
			}
		}

		initialWorld.updateNeighborsAt(initialPos, finalState.getBlock());
		finalWorld.updateNeighborsAt(finalPos, initialState.getBlock());

		// Block tick scheduling
		if (initialWorld.getBlockTicks().hasScheduledTick(initialPos, initialState.getBlock()))
		{
			finalWorld.scheduleTick(finalPos, initialState.getBlock(), 20);
		}

		if (finalWorld.getBlockTicks().hasScheduledTick(finalPos, finalState.getBlock()))
		{
			initialWorld.scheduleTick(initialPos, finalState.getBlock(), 20);
		}

		return true;
	}

void addNextPieceState(PieceSelection pieceSelection) {
            // Subtract the bounding box from the free space
            if (!(pieceSelection.nextPiece instanceof CataclysmPoolElement && (((CataclysmPoolElement) pieceSelection.nextPiece).ignoresBounds() || !((CataclysmPoolElement) pieceSelection.nextPiece).placeBounds()))) {
                free.setValue(Shapes.joinUnoptimized(free.getValue(), Shapes.create(AABB.of(pieceSelection.nextPieceBoundingBoxPlaced)), BooleanOp.ONLY_FIRST));
            }

            // Add the bounds to the interior space
            if (pieceSelection.nextPiece instanceof CataclysmPoolElement && pieceSelection.nextPieceInteriorBoundingBox != null) {
                interiorFree.setValue(Shapes.joinUnoptimized(interiorFree.getValue(), Shapes.create(AABB.of(pieceSelection.nextPieceInteriorBoundingBox)), BooleanOp.OR));
            }

            // Special bounds - add this piece's bounds to any special bounds its set to
            if (pieceSelection.nextPiece instanceof CataclysmPoolElement) {
                CataclysmPoolElement CataclysmPoolElement = (CataclysmPoolElement) pieceSelection.nextPiece;
                Optional<String> nextPieceSpecialBounds = CataclysmPoolElement.bounds.specialBounds;
                if (nextPieceSpecialBounds.isPresent()) {
                    if (specialBounds.getValue().containsKey(nextPieceSpecialBounds.get())) {
                        specialBounds.getValue().put(nextPieceSpecialBounds.get(), Shapes.joinUnoptimized(specialBounds.getValue().get(nextPieceSpecialBounds.get()), Shapes.create(AABB.of(pieceSelection.nextPieceBoundingBoxPlaced)), BooleanOp.OR));
                    } else {
                        specialBounds.getValue().put(nextPieceSpecialBounds.get(), Shapes.create(AABB.of(pieceSelection.nextPieceBoundingBoxPlaced)));
                    }
                }
            }

            BoundingBox thisPieceBoundingBox = pieceSelection.pieceState.piece.getBoundingBox();
            int thisPieceMinY = thisPieceBoundingBox.minY();
            int thisPieceHeightFromBottomToJigsawBlock = pieceSelection.origJigsaw.pos().getY() - thisPieceMinY;
            int pieceGroundLevelDelta = pieceSelection.pieceState.piece.getGroundLevelDelta();
            int k1 = thisPieceHeightFromBottomToJigsawBlock - pieceSelection.connectedJigsaw.pos().getY() + JigsawBlock.getFrontFacing(pieceSelection.origJigsaw.state()).getStepY();
            int k2;
            if (pieceSelection.nextPiece.getProjection() == StructureTemplatePool.Projection.RIGID) {
                k2 = pieceGroundLevelDelta - k1;
            } else {
                k2 = pieceSelection.nextPiece.getGroundLevelDelta();
            }

            pieceSelection.pieceState.piece.addJunction(new JigsawJunction(pieceSelection.connectedJigsaw.pos().getX(), pieceSelection.l2 - thisPieceHeightFromBottomToJigsawBlock + pieceGroundLevelDelta, pieceSelection.connectedJigsaw.pos().getZ(), k1, pieceSelection.nextPiece.getProjection()));
            pieceSelection.poolelementstructurepiece.addJunction(new JigsawJunction(pieceSelection.origJigsaw.pos().getX(), pieceSelection.l2 - pieceSelection.connectedJigsaw.pos().getY() + k2, pieceSelection.origJigsaw.pos().getZ(), -k1, pieceSelection.origPiece.getProjection()));
            this.pieces.add(pieceSelection.poolelementstructurepiece);
            String tag = null;
            if (pieceSelection.nextPiece instanceof CataclysmPoolElement) {
                CataclysmPoolElement CataclysmPoolElement = (CataclysmPoolElement) pieceSelection.nextPiece;
                if (CataclysmPoolElement.tags.inheritsTag) tag = pieceSelection.pieceState.tag;
                else tag = ((CataclysmPoolElement) pieceSelection.nextPiece).getRandomTag(random);
            }
            PieceState nextPieceState = new PieceState(pieceSelection.poolelementstructurepiece, pieceSelection.pieceState.depth + 1, pieceSelection.pieceState, tag);

            // Queue up the next jigsaw pieces
            List<StructureBlockInfo> nextJigsaws = getJigsawBlocksFromPieceState(nextPieceState);
            // Skip the jigsaw piece that just connected (unless its two-way)
            if (!(pieceSelection.poolelementstructurepiece.getElement() instanceof CataclysmPoolElement) || !((CataclysmPoolElement) pieceSelection.poolelementstructurepiece.getElement()).twoWay()) {
                nextJigsaws.removeIf(jigsaw -> {
                    Direction direction = JigsawBlock.getFrontFacing(pieceSelection.origJigsaw.state());
                    BlockPos thisJigsawBlockPos = pieceSelection.origJigsaw.pos();
                    BlockPos nextJigsawBlockPos = thisJigsawBlockPos.relative(direction);
                    return jigsaw.pos().equals(nextJigsawBlockPos);
                });
            }

            // Count up the number of next paths. Check for overridden count first.
            if (pieceSelection.nextPiece instanceof CataclysmPoolElement && ((CataclysmPoolElement) pieceSelection.nextPiece).conditions.numPathsOverride.isPresent()) {
                numPaths += ((CataclysmPoolElement) pieceSelection.nextPiece).conditions.numPathsOverride.get();
            }
            else {
                for (StructureBlockInfo jigsaw : nextJigsaws) {
                    if (jigsaw.nbt().getString("target").equals(pathJigsawName)) {
                        numPaths++;
                    }
                }
            }

            for (StructureBlockInfo jigsaw : nextJigsaws) {
                this.placing.add(new Pair<>(jigsaw, nextPieceState));
            }

            pieceSelection.pieceState.children.add(nextPieceState);
        }

public static float getDamageAbsorbed(LivingEntity entity, DamageSource source, float amount) {
        if (amount <= 0) {
            return 0;
        }
        float ratioAbsorbed = 0;
        List<FoundArmorDetails> armorDetails = new ArrayList<>();
        //Protect against any mods that might be doing transactional logic, such as if an auto clicker validates it has enough energy before calling this method
        try (Transaction transaction = TransactionHelper.openTransactionSafe()) {
            //Start by looping the armor, allowing modules to absorb damage if they can
            for (EquipmentSlot armorType : EquipmentSlotGroup.ARMOR) {
                //Player's don't have non-humanoid armor and the wrapper will throw for them, so skip them
                if (!(entity instanceof Player) || armorType.getType() == Type.HUMANOID_ARMOR) {
                    ResourceHandler<ItemResource> armorSlot = LivingEntityEquipmentWrapper.of(entity, armorType);
                    ItemResource itemType = armorSlot.getResource(0);
                    if (!itemType.isEmpty() && itemType.is(MekanismAPITags.Items.MODULE_CONTAINERS_ARMOR)) {
                        ItemAccess itemAccess = ItemAccess.forHandlerIndexStrict(armorSlot, 0);
                        EnergyHandler energyHandler = AutomatedEnergyHandler.manual(Capabilities.ENERGY.getCapability(itemAccess));
                        if (energyHandler != null) {
                            FoundArmorDetails details = new FoundArmorDetails(energyHandler, getAbsorption(armorType));
                            armorDetails.add(details);
                            for (IModule<?> module : IModuleHelper.INSTANCE.getAllModules(itemType)) {
                                if (module.isEnabled()) {
                                    ModuleDamageAbsorbInfo damageAbsorbInfo = getModuleDamageAbsorbInfo(module, source);
                                    if (damageAbsorbInfo != null) {
                                        float absorption = damageAbsorbInfo.absorptionRatio().getAsFloat();
                                        ratioAbsorbed += absorbDamage(details.energyHandler, amount, absorption, ratioAbsorbed, damageAbsorbInfo.energyCost(), transaction);
                                        if (ratioAbsorbed >= 1) {
                                            //If we have fully absorbed the damage, stop checking/trying to absorb more
                                            break;
                                        }
                                    }
                                }
                            }
                            if (ratioAbsorbed >= 1) {
                                //If we have fully absorbed the damage, stop checking/trying to absorb more
                                break;
                            }
                        }
                    }
                }
            }
            if (ratioAbsorbed < 1) {
                //If we haven't fully absorbed it check the individual pieces of armor for if they can absorb any
                Float absorbRatio = null;
                for (FoundArmorDetails details : armorDetails) {
                    if (absorbRatio == null) {
                        //If we haven't looked up yet if we can absorb the damage type and if we can't
                        // stop checking if the armor is able to
                        if (source.is(Tags.DamageTypes.IS_TECHNICAL) || !source.is(MekanismAPITags.DamageTypes.MEKASUIT_ALWAYS_SUPPORTED) && source.is(DamageTypeTags.BYPASSES_ARMOR)) {
                            break;
                        }
                        // Next lookup the ratio at which we can absorb the given damage type from the data map
                        MekaSuitAbsorption absorptionData = IMekanismDataMapTypes.INSTANCE.getMekaSuitAbsorption(entity.registryAccess(), source.typeHolder());
                        if (absorptionData == null) {
                            absorbRatio = MekanismConfig.gear.mekaSuitUnspecifiedDamageRatio.get();
                        } else {
                            absorbRatio = absorptionData.absorption();
                        }
                        if (absorbRatio == 0) {
                            //If the config or the data map specifies that the damage type shouldn't be blocked at all
                            // stop checking if the armor is able to
                            break;
                        }
                    }
                    float absorption = details.armorAbsorption * absorbRatio;
                    ratioAbsorbed += absorbDamage(details.energyHandler, amount, absorption, ratioAbsorbed, MekanismConfig.gear.mekaSuitEnergyUsageDamage, transaction);
                    if (ratioAbsorbed >= 1) {
                        //If we have fully absorbed the damage, stop checking/trying to absorb more
                        break;
                    }
                }
            }
            //Use energy/or enqueue usage for each piece as needed
            transaction.commit();
        }
        return Math.min(ratioAbsorbed, 1);
    }

@Override
	public void aiStep() {
		super.aiStep();
		this.eatTicks++;

		if (this.dropEatingLootCooldown > 0) this.dropEatingLootCooldown--;

		if (!this.isInWater() && this.onGround() && this.verticalCollision) {
			this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.05F, 0.4F, (this.random.nextFloat() * 2.0F - 1.0F) * 0.05F));
			this.setOnGround(false);
			this.hasImpulse = true;
			this.playSound(this.getFlopSound(), this.getSoundVolume(), this.getVoicePitch());
		}

		if (this.level().getGameTime() % 20 == 0) {
			LivingEntity caughtEntity = this.getCaughtEntity();
			if (caughtEntity != null && (!this.isPickerelweedNearby() || this.isHidingInPickerelweed())) {
				this.level().playSound(null, this.blockPosition(), UASoundEvents.PIKE_BITE.get(), SoundSource.HOSTILE, 0.8F, 0.90F);
				if (this.level().isClientSide && caughtEntity.getHealth() <= 1 && this.getVariant().is(UAPikeVariants.SPECTRAL)) {
					for (int i = 0; i < 3; ++i) {
						this.level().addParticle(UAParticleTypes.SPECTRAL_CONSUME.get(), caughtEntity.getX() + (caughtEntity.getRandom().nextDouble() - 0.5D) * (double) caughtEntity.getBbWidth(), caughtEntity.getY() + caughtEntity.getRandom().nextDouble() * (double) caughtEntity.getBbHeight() - 0.25D, caughtEntity.getZ() + (caughtEntity.getRandom().nextDouble() - 0.5D) * (double) caughtEntity.getBbWidth(), (this.getCaughtEntity().getRandom().nextDouble() - 0.5D) * 2.0D, -caughtEntity.getRandom().nextDouble(), (caughtEntity.getRandom().nextDouble() - 0.5D) * 2.0D);
					}
				}
				caughtEntity.hurt(this.damageSources().mobAttack(this), 1.0F);
			}
		}

		if (this.getAttackCooldown() > 0) {
			this.setAttackCooldown(this.getAttackCooldown() - 1);
		}

		ItemStack itemstack = this.getItemBySlot(EquipmentSlot.MAINHAND);
		if (!this.level().isClientSide && this.isAlive() && this.isEffectiveAi() && !itemstack.isEmpty() && this.canEatItem(itemstack) && this.isInWater()) {
			if (this.eatTicks > 600) {
				ItemStack itemstackFood = itemstack.finishUsingItem(this.level(), this);
				if (!itemstack.isEmpty()) {
					this.setItemSlot(EquipmentSlot.MAINHAND, itemstackFood);
				}

				if (this.dropEatingLootCooldown <= 0) {
					if (this.random.nextFloat() < 0.2F) {
						for (ItemStack stacks : this.generateFishingLoot()) {
							if (stacks.getCount() > 0) {
								stacks.shrink(stacks.getCount() - 1);
							}
							this.spitOutItem(stacks);
						}
					} else {
						this.spitOutItem(new ItemStack(Items.BONE_MEAL));
					}
					this.dropEatingLootCooldown = 3600 + this.getRandom().nextInt(400);
				}

				this.heal(6);
				this.eatTicks = 0;
			} else if (this.eatTicks > 560 && this.random.nextFloat() < 0.1F) {
				this.playSound(this.getEatingSound(itemstack), 1.0F, 1.0F);
				this.level().broadcastEntityEvent(this, (byte) 45);
			}
		}

		if (this.isMoving() && this.isInWater() && this.getVariant().is(UAPikeVariants.SUPERCHARGED)) {
			Vec3 vec3d1 = this.getViewVector(0.0F);

			for (int i = 0; i < 2; ++i) {
				this.level().addParticle(ParticleTypes.BUBBLE, this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() - vec3d1.x * 1.5D, this.getY() + this.random.nextDouble() * (double) this.getBbHeight() - vec3d1.y * 1.5D, this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() - vec3d1.z * 1.5D, 0.0D, 0.0D, 0.0D);
			}
		}

		if (this.getVariant().is(UAPikeVariants.OBSIDIAN) && this.isLit()) {
			if (this.level().isClientSide) {
				for (int i = 0; i < 2; i++) {
					this.level().addParticle(ParticleTypes.PORTAL, this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth(), this.getY() + this.random.nextDouble() * (double) this.getBbHeight() - 0.25D, this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth(), (this.random.nextDouble() - 0.5D) * 2.0D, -this.random.nextDouble(), (this.random.nextDouble() - 0.5D) * 2.0D);
				}
			}
		}
	}

