				ParticleBuilder glitter = new ParticleBuilder(30);
				glitter.setRender(new ResourceLocation(Wizardry.MODID, NBTConstants.MISC.SPARKLE_BLURRED));
				glitter.setAlphaFunction(new InterpFloatInOut(1f, 1f));
				glitter.setColor(new Color(0xf404d4));

				RandUtilSeed seed = new RandUtilSeed(getDataManager().get(DATA_SHIFT_SEED));

				Vec3d offset = new Vec3d(seed.nextDouble(-3, 3), seed.nextDouble(-3, 3), seed.nextDouble(-3, 3));

				ParticleSpawner.spawn(glitter, world, new StaticInterp<>(
						getPositionVector().add(0, getEyeHeight(), 0).add(offset)), 10, 0, (i, build) -> {
					double radius = 0.1;
					double theta = 2.0f * (float) Math.PI * RandUtil.nextFloat();
					double r = radius * RandUtil.nextFloat();
					double x = r * MathHelper.cos((float) theta);
					double z = r * MathHelper.sin((float) theta);

					glitter.setLifetime(RandUtil.nextInt(10, 40));
					glitter.setScaleFunction(new InterpScale(0, (float) RandUtil.nextDouble(3, 4)));
					glitter.setPositionOffset(new Vec3d(x, RandUtil.nextDouble(0, 0.2), z));
					if (RandUtil.nextInt(15) == 0)
						glitter.addMotion(new Vec3d(RandUtil.nextDouble(-0.01, 0.01),
								RandUtil.nextDouble(-0.03, 0),
								RandUtil.nextDouble(-0.01, 0.01)));
				});
			}
		});

		if (angry) {
			player.attackEntityFrom(DamageSource.MAGIC, 0.15f);
			player.hurtResistantTime = 0;
		}
	}

@Override
    @Nullable
    public Tooltip getCurrentTooltip(TooltipContext context) {
        Tooltip tooltip = getCurrentEntry().getTooltip(context);

        if (tooltip != null && !(Minecraft.getInstance().gui.screen() instanceof DisplayScreen)) {
            boolean exists = getTransferHandler(false) != null;

            if (!exists) {
                if (lastCheckedTime == -1 || Util.getMillis() - lastCheckedTime > 400) {
                    lastCheckedTime = Util.getMillis();
                }

                if (Util.getMillis() - lastCheckedTime > 200) {
                    lastCheckedTime = -1;
                    exists = getTransferHandler(true) != null;
                }
            } else {
                lastCheckedTime = -1;
            }

            if (exists) {
                tooltip.add(Component.translatable("text.auto_craft.move_items.tooltip").withStyle(ChatFormatting.YELLOW));
                tooltip.add(displayTooltipComponent.get());
            }
        }

        if (tooltip != null) {
            if (interactableFavorites && ConfigObject.getInstance().doDisplayFavoritesTooltip() && !ConfigObject.getInstance().getFavoriteKeyCode().isUnknown()) {
                String name = ConfigObject.getInstance().getFavoriteKeyCode().getLocalizedName().getString();
                if (reverseFavoritesAction())
                    tooltip.addAllTexts(Stream.of(I18n.get("text.rei.remove_favorites_tooltip", name).split("\n"))
                            .map(Component::literal).collect(Collectors.toList()));
                else
                    tooltip.addAllTexts(Stream.of(I18n.get("text.rei.favorites_tooltip", name).split("\n"))
                            .map(Component::literal).collect(Collectors.toList()));
            }

            if (tooltipProcessors != null) {
                for (UnaryOperator<Tooltip> processor : tooltipProcessors) {
                    tooltip = processor.apply(tooltip);
                }
            }
        }

        if (tooltip != null) {
            if (interactableFavorites && ConfigObject.getInstance().doDisplayFavoritesTooltip() && !ConfigObject.getInstance().getFavoriteKeyCode().isUnknown()) {
                String name = ConfigObject.getInstance().getFavoriteKeyCode().getLocalizedName().getString();
                if (reverseFavoritesAction())
                    tooltip.addAllTexts(Stream.of(I18n.get("text.rei.remove_favorites_tooltip", name).split("\n"))
                            .map(Component::literal).collect(Collectors.toList()));
                else
                    tooltip.addAllTexts(Stream.of(I18n.get("text.rei.favorites_tooltip", name).split("\n"))
                            .map(Component::literal).collect(Collectors.toList()));
            }

            if (tooltipProcessors != null) {
                for (UnaryOperator<Tooltip> processor : tooltipProcessors) {
                    tooltip = processor.apply(tooltip);
                }
            }

            if (!tooltip.entries().isEmpty() && ConfigObject.getInstance().doDisplayIMEHints()) {
                Tooltip.Entry entry = tooltip.entries().get(0);

                if (entry.isText()) {
                    String name = FormattingUtils.stripFormatting(entry.getAsText().getString());
                    InputMethod<?> active = InputMethod.active();
                    String suggested = active.suggestInputString(name);
                    if (suggested != null) {
                        tooltip.entries().add(1, Tooltip.entry(Component.literal(suggested).withStyle(ChatFormatting.GRAY)));
                    }
                }
            }
        }

        return tooltip;
    }

@Override
    public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.hysteriaCool > 0) {
                --this.hysteriaCool;
            }
            if (this.meleeCool > 0) {
                --this.meleeCool;
            }
            if (this.fightTick > 0) {
                if (this.getTarget() == null) {
                    --this.fightTick;
                }
            }
            if (this.lastHitTime > 0){
                --this.lastHitTime;
            } else if (this.hitTimes > 0) {
                this.hitTimes = 0;
            }
            if (this.overwhelmed > 0) {
                --this.overwhelmed;
            }
            if (this.getMonolith() == null){
                if (this.getLeader() instanceof ObsidianMonolith obsidianMonolith){
                    this.setMonolith(obsidianMonolith);
                } else {
                    for (ObsidianMonolith monolith1 : this.level.getEntitiesOfClass(ObsidianMonolith.class, this.getBoundingBox().inflate(64.0D, 8.0D, 64.0D))){
                        if (monolith1.getTrueOwner() == null || monolith1.getTrueOwner() instanceof Cultist){
                            this.setMonolith(monolith1);
                        }
                    }
                }
            } else if (this.getMonolith() != null){
                if (this.getLeader() != this.getMonolith()) {
                    this.setLeader(this.getMonolith());
                }
                this.getMonolith().empowered = 10;
                this.getMonolith().spawnMiniBossCool = MathHelper.minecraftDayToTicks(5);
                try {
                    if (this.getTarget() != null) {
                        if (this.tickCount % 20 == 0) {
                            if (this.level.getRandom().nextInt(64) == 0) {
                                int i = this.level.getEntitiesOfClass(Maverick.class, this.getMonolith().getBoundingBox().inflate(24.0D, 16.0D, 24.0D), livingEntity -> livingEntity.isAlive() && MobUtil.areAllies(livingEntity, this)).size();
                                if (i < 8) {
                                    this.getMonolith().summonMavericks();
                                }
                            }
                            if (this.level.getRandom().nextInt(256) == 0) {
                                int i = this.level.getEntitiesOfClass(Heretic.class, this.getMonolith().getBoundingBox().inflate(24.0D, 16.0D, 24.0D), livingEntity -> livingEntity.isAlive() && MobUtil.areAllies(livingEntity, this)).size();
                                if (i < 2) {
                                    this.getMonolith().summonHeretics();
                                }
                            }
                        }
                    }
                } catch (NullPointerException exception) {
                    this.setMonolith(null);
                }
            }
            if (this.isStartTeleporting()) {
                ++this.aboutToTeleport;
                int time = MobUtil.healthIsHalved(this) ? 30 : 45;
                if (this.overwhelmed > 0) {
                    time -= 20;
                }
                if (this.aboutToTeleport >= time && !this.isCurrentAnimation(MELEE)) {
                    if (this.getTarget() != null) {
                        this.teleport();
                    }
                    this.setStartTeleporting(false);
                }
            } else {
                if (this.aboutToTeleport > 0) {
                    this.aboutToTeleport = 0;
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();

        this.setDeltaMovement(0D, 0D, 0D);

        if (this.level().isClientSide()) {
            if (this.getLifetime() - this.tickCount > 1) {
                var random = this.random;
                var radius = this.getRadius();

                var x = this.getX() + MathUtils.randomFloat(random) * radius;
                var z = this.getZ() + MathUtils.randomFloat(random) * radius;

                this.level().addParticle(new GhostlyFogParticle.Options(this.getLifetime() - this.tickCount - 1),
                        x,
                        this.getY() + random.nextDouble() * 2,
                        z,
                        MathUtils.randomFloat(random) * 0.01F,
                        -0.025F,
                        MathUtils.randomFloat(random) * 0.01F);
            }

            return;
        }

        if (this.tickCount > this.getLifetime()) {
            this.discard();

            return;
        }

        var owner = this.getOwner();
        var radius = this.getRadius();
        var gameTime = this.level().getGameTime();

        if (lastExposureCleanupTick != gameTime && gameTime % 200L == 0L) {
            lastExposureCleanupTick = gameTime;

            LAST_EXPOSURE_TICK.values().removeIf(tick -> tick < gameTime - 200L);
        }

        for (var target : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(radius),
                entity -> entity != owner && entity.isAlive() && TargetingUtils.canHarm(owner, entity, this.getStack(), "fog"))) {
            target.getPersistentData().putFloat(GhostlyMantleItem.FOG_SUFFOCATION_DAMAGE_TAG, this.getSuffocationDamage());
            target.getPersistentData().putLong(GhostlyMantleItem.FOG_SUFFOCATION_UNTIL_TAG, this.level().getGameTime() + 5L);

            if (this.getAirDrain() > 0)
                target.setAirSupply(Math.max(-20, target.getAirSupply() - this.getAirDrain()));

            if (this.getTremorTicks() > 0)
                TargetingUtils.addHarmfulEffect(target, new MobEffectInstance(RelicsMobEffects.TREMOR, this.getTremorTicks(), 0, false, false), owner, this.getStack(), "fog");

            if (target.getAirSupply() <= -20 && this.tickCount % 20 == 0)
                target.hurt(this.level().damageSources().inWall(), 1F);

            if (owner == null)
                continue;

            var key = owner.getStringUUID() + ":" + target.getStringUUID();

            if (LAST_EXPOSURE_TICK.getOrDefault(key, Long.MIN_VALUE) == gameTime)
                continue;

            LAST_EXPOSURE_TICK.put(key, gameTime);

            for (var stack : EntityUtils.findEquippedCurios(owner, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("fog");

                if (!ability.canPlayerUse(owner))
                    continue;

                ability.getStatisticData().getMetricData("fog_exposure").addValue(1D / 20D);
                relic.getRelicData(owner, stack).getLevelingData().addExperience("fog", "fog_exposure", 1D / 20D);

                break;
            }
        }
    }

@Override
    public void tick() {
        if (level.isClientSide) {
            BlockPos pos = getBlockPos();
            if (level.random.nextInt(6) == 0) {
                level.addParticle(ParticleTypes.BUBBLE_POP, pos.getX() + ParticleUtil.inRange(-0.25, 0.25) + 0.5, pos.getY() + 1, pos.getZ() + 0.5 + ParticleUtil.inRange(-0.25, 0.25), 0, 0, 0);

            }
        }
        int maxMergeTicks = 160;
        if (isOff) {
            isMixing = false;
            timeMixing = 0;
            return;
        }
        if (!level.isClientSide && !hasSource && level.getGameTime() % 20 == 0) {
            if (SourceUtil.takeSourceMultipleWithParticles(worldPosition, level, 5, Config.MELDER_SOURCE_COST.get()) != null) {
                hasSource = true;
                updateBlock();
            }

        }

        if (!hasSource || toPos == null || !level.isLoaded(toPos) || !takeJarsValid() || !(level.getBlockEntity(toPos) instanceof PotionJarTile combJar)) {
            isMixing = false;
            timeMixing = 0;
            return;
        }

        PotionJarTile tile1 = (PotionJarTile) level.getBlockEntity(fromJars.get(0));
        PotionJarTile tile2 = (PotionJarTile) level.getBlockEntity(fromJars.get(1));
        PotionContents data = getCombinedResult(tile1, tile2);
        if (!isOutputUnique(data, tile1, tile2) || outputHasDuplicateEffect(data)) {
            return;
        }
        if (!combJar.canAccept(data, Config.MELDER_OUTPUT.get())) {
            isMixing = false;
            timeMixing = 0;
            return;
        }

        isMixing = true;
        timeMixing++;
        ParticleColor color1 = ParticleColor.fromInt(tile1.getColor());
        ParticleColor color2 = ParticleColor.fromInt(tile2.getColor());

        if (level.isClientSide) {
            //Burning jar
            if (timeMixing >= 120) {
                for (int i = 0; i < 3; i++) {
                    double d0 = worldPosition.getX() + 0.5 + ParticleUtil.inRange(-0.25, 0.25);
                    double d1 = worldPosition.getY() + 1 + ParticleUtil.inRange(-0.1, 0.4);
                    double d2 = worldPosition.getZ() + .5 + ParticleUtil.inRange(-0.25, 0.25);
                    level.addParticle(GlowParticleData.createData(
                                    ParticleColor.fromInt(PotionContents.getColor(data.getAllEffects()))),
                            d0, d1, d2,
                            0,
                            0.01f,
                            0);
                }
                lastMixedColor = PotionContents.getColor(data.getAllEffects());
            }
            if (timeMixing >= 160)
                timeMixing = 0;
            return;
        }

        if (level instanceof ServerLevel serverLevel) {
            if (timeMixing % 20 == 0 && timeMixing > 0 && timeMixing <= 60) {
                EntityFlyingItem.spawn(serverLevel, tile1.getBlockPos().above(), worldPosition, Math.round(255 * color1.getRed()), Math.round(255 * color1.getGreen()), Math.round(255 * color1.getBlue()))
                        .withNoTouch().setDistanceAdjust(2f);
                EntityFlyingItem.spawn(serverLevel, tile2.getBlockPos().above(), worldPosition, Math.round(255 * color2.getRed()), Math.round(255 * color2.getGreen()), Math.round(255 * color2.getBlue()))
                        .withNoTouch().setDistanceAdjust(2f);
            }
            if (timeMixing >= maxMergeTicks) {
                timeMixing = 0;
                mergePotions(combJar, tile1, tile2, data);
            }
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();

		updateMovementAndPathfinding();

		if (!getEntityWorld().isRemote) {

			if(getIsFlying()) {
				if(world.getTotalWorldTime()%120 ==0)
					if (!getIsFishing())
						setIsFishing(true);
				isAirBorne = true;
				onGround = false;
				if(getFlyingTimer() < MAX_FLIGHT_TIME)
					setFlyingTimer(getFlyingTimer() + 1);
				if(getFlyingTimer() >= MAX_FLIGHT_TIME) {
					if(!getCanLand()){
						setCanLand(true);
						setRestingTimer(0);
						//System.out.println("SHOULD FLY ABOUT NOW!");
					}
				}
			}

			if(!getIsFlying()) {
				if (getIsFishing())
					setIsFishing(false);
				isAirBorne = false;
				onGround = true;
				if(getRestingTimer() < MAX_RESTING_TIME)
					setRestingTimer(getRestingTimer() + 1);
				if(getRestingTimer() >= MAX_RESTING_TIME) {
					if(getCanLand()) {
						setCanLand(false);
						setFlyingTimer(0);
						//System.out.println("SHOULD FUCKING LAND!");
					}

			}	}
		}

		if (getIsLanding() && getEntityWorld().isAirBlock(getPosition())) {
			motionY -= 0.04D;
		}

		//if (isJumping && isInWater() && !getIsDiving()) {
		//	getMoveHelper().setMoveTo(posX, posY + 1, posZ, 1.0D);
	//	}

		//if (getIsFishing() && getAttackTarget() != null) {
		//	if (motionY < 0)
		//		if (!getIsDiving())
		//			setIsDiving(true);
		//}

		if (motionY >= 0 && !isInWater())
			if (getIsDiving())
				setIsDiving(false);

	//	if (getIsHovering()) {
	//		motionX = motionY = motionZ = 0.0D;
	//	}

		if (getEntityWorld().isRemote) {
			landingTimer.updateTimer();
			divingTimer.updateTimer();

