				divingTimer.increaseTimer();
				landingTimer.decreaseTimer();
			} 
			else if (!getIsFlying()) {
				landingTimer.increaseTimer();
				divingTimer.decreaseTimer();
			} else if (!getIsDiving() && getIsFlying()) {
				landingTimer.decreaseTimer();
				divingTimer.decreaseTimer(5);
			}
		}
