public static void serverTick(Level level, BlockPos blockPos, BlockState blockState, BarracksBlockEntity blockEntity) {
        if (level instanceof ServerLevel serverLevel){
            if (serverLevel.isRaining()) {
                if (serverLevel.isThundering()) {
                    if (!Objects.equals(blockEntity.currentWeather, STORM)) {
                        blockEntity.currentWeather = STORM;
                        blockEntity.updateVariant = 5;
                    }
                } else {
                    if (!Objects.equals(blockEntity.currentWeather, RAIN)) {
                        blockEntity.currentWeather = RAIN;
                        blockEntity.updateVariant = 5;
                    }
                }
            } else {
                if (!Objects.equals(blockEntity.currentWeather, CLEAR)) {
                    blockEntity.currentWeather = CLEAR;
                    blockEntity.updateVariant = 5;
                }
            }
            if (blockEntity.updateVariant > 0){
                --blockEntity.updateVariant;
                blockEntity.setVariant(level, blockPos);
            }
            EntityType<? extends Mob> entityType = blockEntity.getTrainedMob(serverLevel, blockPos);
            if (entityType != null) {
                if (!Objects.equals(blockEntity.currentMob, entityType.getDescriptionId())){
                    blockEntity.setCurrentMob(entityType.getDescriptionId());
                }
                if (serverLevel.getGameTime() % 10 == 0) {
                    if (!blockEntity.uuids.isEmpty()) {
                        List<UUID> toRemove = new ArrayList<>();
                        for (UUID uuid : blockEntity.uuids) {
                            if (uuid != null) {
                                Entity entity = serverLevel.getEntity(uuid);
                                if (entity instanceof Mob mob && mob instanceof ITrainable) {
                                    if (!mob.isRemoved()) {
                                        if (!blockEntity.trainingMobs.contains(mob)) {
                                            blockEntity.trainingMobs.add(mob);
                                        }
                                    } else {
                                        toRemove.add(uuid);
                                    }
                                } else {
                                    toRemove.add(uuid);
                                }
                            }
                        }
                        if (!toRemove.isEmpty()){
                            blockEntity.uuids.removeAll(toRemove);
                        }
                    }
                    if (!blockEntity.trainingMobs.isEmpty()) {
                        blockEntity.trainingMobs.removeIf(mob -> {
                            if (!(mob instanceof ITrainable trainable)) {
                                blockEntity.uuids.remove(mob.getUUID());
                                return true;
                            } else if (!mob.isAlive() || mob.level.dimension() != serverLevel.dimension() || trainable.isTrained() || !blockEntity.checkEligibility(mob, serverLevel, blockPos)) {
                                blockEntity.uuids.remove(mob.getUUID());
                                return true;
                            }
                            return false;
                        });
                    }
                }
                blockEntity.trainMobs(level, blockPos);
            } else if (!Objects.equals(blockEntity.currentMob, "None")) {
                blockEntity.setCurrentMob("None");
            }

            blockEntity.mobCountO = blockEntity.amountTraining(level, blockPos);
            if (blockEntity.mobCountO != blockEntity.mobCount) {
                blockEntity.mobCount = blockEntity.mobCountO;
                blockEntity.markUpdated();
            }
        }

        if (blockState.hasProperty(BlockStateProperties.POWERED)){
            level.setBlock(blockPos, blockState.setValue(BlockStateProperties.POWERED, blockEntity.getTrainedMob(level, blockPos) != null), 3);
        }
    }

private void render(EntityPlayer player, double x, double y, double z, float delta) {
			Tessellator tes = Tessellator.getInstance();
			BufferBuilder buf = tes.getBuffer();
			buf.begin(GL11.GL_QUADS, DefaultVertexFormats.POSITION_TEX_NORMAL);
			buf.setTranslation(x, y, z);
			for (Quad quad : quads) {
				Quad.Vertex v00 = quad.getV00();
				Quad.Vertex v01 = quad.getV01();
				Quad.Vertex v11 = quad.getV11();
				Quad.Vertex v10 = quad.getV10();
				float v00x = v00.getX(delta);
				float v00y = v00.getY(delta);
				float v00z = v00.getZ(delta);
				float v01x = v01.getX(delta);
				float v01y = v01.getY(delta);
				float v01z = v01.getZ(delta);
				float v11x = v11.getX(delta);
				float v11y = v11.getY(delta);
				float v11z = v11.getZ(delta);
				float v10x = v10.getX(delta);
				float v10y = v10.getY(delta);
				float v10z = v10.getZ(delta);
				float nx = (v11y - v00y) * (v10z - v01z) - (v11z - v00z) * (v10y - v01y);
				float ny = (v10x - v01x) * (v11z - v00z) - (v10z - v01z) * (v11x - v00x);
				float nz = (v11x - v00x) * (v10y - v01y) - (v11y - v00y) * (v10x - v01x);
				float len = MathHelper.sqrt(nx * nx + ny * ny + nz * nz);
				nx /= len;
				ny /= len;
				nz /= len;
				buf.pos(v00x, v00y, v00z)
						.tex(v00.getU(), v00.getV())
						.normal(nx, ny, nz)
						.endVertex();
				buf.pos(v01x, v01y, v01z)
						.tex(v01.getU(), v01.getV())
						.normal(nx, ny, nz)
						.endVertex();
				buf.pos(v11x, v11y, v11z)
						.tex(v11.getU(), v11.getV())
						.normal(nx, ny, nz)
						.endVertex();
				buf.pos(v10x, v10y, v10z)
						.tex(v10.getU(), v10.getV())
						.normal(nx, ny, nz)
						.endVertex();
			}
			buf.setTranslation(0, 0, 0);
			GlStateManager.color(1, 1, 1);
			GlStateManager.disableCull();
			GlStateManager.enableBlend();
			GlStateManager.blendFunc(GlStateManager.SourceFactor.SRC_ALPHA, GlStateManager.DestFactor.ONE_MINUS_SRC_ALPHA);

			ItemStack stack = BaublesSupport.getItem(player, ModItems.CAPE);

			ResourceLocation fallBackCape;
			UUID uuid = NBTHelper.getUniqueId(stack, "uuid");
			if (uuid != null) {
				RandUtilSeed seed = new RandUtilSeed(uuid.hashCode());
				fallBackCape = new ResourceLocation(Wizardry.MODID, "textures/capes/cape_normal_" + seed.nextInt(1, 4) + ".png");
			} else {
				fallBackCape = new ResourceLocation(Wizardry.MODID, "textures/capes/cape_normal_3.png");
			}

			String capeName = "cape_" + player.getUniqueID().toString().replace("-", "");
			ResourceLocation loc = new ResourceLocation(Wizardry.MODID, "capes/" + capeName);

			ResourceLocation finalFallBackCape = fallBackCape;
			Minecraft.getMinecraft().addScheduledTask(() -> {
				ITextureObject itextureobject = Minecraft.getMinecraft().getTextureManager().getTexture(loc);

				if (itextureobject == null) {
					ThreadDownloadImageData threaddownloadimagedata = new ThreadDownloadImageData(null, "https://raw.githubusercontent.com/TeamWizardry/Wizardry/master/capes/" + capeName + ".png", finalFallBackCape, null);
					Minecraft.getMinecraft().getTextureManager().loadTexture(loc, threaddownloadimagedata);
				}
			});

			Minecraft.getMinecraft().getTextureManager().bindTexture(loc);

			tes.draw();
			GlStateManager.enableCull();
		}

@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || (this.getOwner() != null && !this.getOwner().isEntityAlive()))) {
			this.setDead();
			return;
		}

		if(!this.isDead) {
			if(this.getRidingEntity() == null) {
				this.ticksInAir++;

				if(this.ticksInAir > 200) {
					this.setDead();
				}

				Vec3d currentPos = new Vec3d(this.posX, this.posY, this.posZ);
				Vec3d nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
				RayTraceResult hitObject = this.world.rayTraceBlocks(currentPos, nextPos);
				currentPos = new Vec3d(this.posX, this.posY, this.posZ);
				nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);

				if (hitObject != null) {
					nextPos = new Vec3d(hitObject.hitVec.x, hitObject.hitVec.y, hitObject.hitVec.z);
				}

				Entity hitEntity = null;
				List<Entity> hitEntities = this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox().grow(this.motionX, this.motionY, this.motionZ).grow(0.1D, 0.1D, 0.1D));
				double minDist = 0.0D;

				for (int i = 0; i < hitEntities.size(); ++i) {
					Entity entity = (Entity)hitEntities.get(i);
					if (entity.canBeCollidedWith() && entity != this.getThrower() && entity != this) {
						float f = 0.1F;
						AxisAlignedBB axisalignedbb = entity.getEntityBoundingBox().grow((double)f, (double)f, (double)f);
						RayTraceResult movingobjectposition1 = axisalignedbb.calculateIntercept(currentPos, nextPos);
						if (movingobjectposition1 != null) {
							double d1 = currentPos.distanceTo(movingobjectposition1.hitVec);
							if (d1 < minDist || minDist == 0.0D) {
								hitEntity = entity;
								minDist = d1;
							}
						}
					}
				}

				if (hitEntity != null) {
					hitObject = new RayTraceResult(hitEntity);
				}

				if (hitObject != null && hitObject.entityHit != this.getThrower()) {
					this.onImpact(hitObject);
				}
				this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
			} else {
				if(this.getRidingEntity() instanceof EntityPlayer) {
					EntityPlayer player = (EntityPlayer) this.getRidingEntity();
					ItemStack heldItem = player.getHeldItem(EnumHand.MAIN_HAND);
					if(!this.isDeflectable() || heldItem == null || heldItem.getItem() instanceof ItemSword == false) {
						if(!this.world.isRemote) {
							this.setDead();
						}
					} else {
						player.setInWeb();
						player.motionY -= 1.5D;
						if(player.isSwingInProgress) {
							if(this.canDismount) {
								Vec3d look = this.getRidingEntity().getLookVec();
								look.normalize();
								this.shoot(look.x, look.y, look.z, 0.5F, 0.0F);
								this.dismountRidingEntity();
								this.setThrower(player);
							}
						} else {
							this.canDismount = true;
						}
					}
				}
			}
		}

		super.onUpdate();
	}

