                return ItemSummoningCrystal.hasDragon(stack) ? 1.0F : 0.0F;
            });
            ItemProperties.register(IafItemRegistry.TIDE_TRIDENT.get(), new ResourceLocation("throwing"), (stack, level, entity, p) -> {
                return entity != null && entity.isUsingItem() && entity.getUseItem() == stack ? 1.0F : 0.0F;
            });
        });
    }

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity entity = result.getEntity();
        float f = (float) this.getDeltaMovement().length();
        int i = Mth.ceil(Math.max(f * this.getBaseDamage(), 0.0D));
        if (this.getPierceLevel() > 0) {
            if (this.piercedEntities == null) {
                this.piercedEntities = new IntOpenHashSet(5);
            }

            if (this.hitEntities == null) {
                this.hitEntities = Lists.newArrayListWithCapacity(5);
            }

            if (this.piercedEntities.size() >= this.getPierceLevel() + 1) {
                this.remove(RemovalReason.DISCARDED);
                return;
            }

            this.piercedEntities.add(entity.getId());
        }

        if (this.isCritArrow()) {
            i += this.random.nextInt(i / 2 + 2);
        }

        Entity entity1 = this.getOwner();
        DamageSource damagesource = DamageSource.MAGIC;

        if (entity1 != null) {
            if (entity1 instanceof LivingEntity) {
                damagesource = DamageSource.arrow(this, entity1);
                damagesource.setMagic();
                ((LivingEntity) entity1).setLastHurtMob(entity);
            }
        }

        boolean flag = entity.getType() == EntityType.ENDERMAN;
        int j = entity.getRemainingFireTicks();
        if (this.isOnFire() && !flag) {
            entity.setSecondsOnFire(5);
        }

        if (entity.hurt(damagesource, i)) {
            if (flag) {
                return;
            }

            if (entity instanceof LivingEntity) {
                LivingEntity livingentity = (LivingEntity) entity;

                if (this.knockbackStrength > 0) {
                    Vec3 vec3d = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize()
                        .scale(this.knockbackStrength * 0.6D);
                    if (vec3d.lengthSqr() > 0.0D) {
                        livingentity.push(vec3d.x, 0.1D, vec3d.z);
                    }
                }

                this.doPostHurtEffects(livingentity);
                if (entity1 != null && livingentity != entity1 && livingentity instanceof Player && entity1 instanceof ServerPlayer) {
                    ((ServerPlayer) entity1).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }

                if (!entity.isAlive() && this.hitEntities != null) {
                    this.hitEntities.add(livingentity);
                }

            }

            this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            if (this.getPierceLevel() <= 0) {
                this.remove(RemovalReason.DISCARDED);
            }
        } else {
            this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
            //this.ticksInAir = 0;
            if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                this.remove(RemovalReason.DISCARDED);
            }
        }

    }

@Override
	public void onUpdate() {
		if (getEntityWorld().isRemote) {
	            if (isInWater() && !getEntityWorld().getBlockState(getPosition().down()).getMaterial().isSolid())
					motionY -= 0.2D;

			if (isBeingRidden() && getJawAngle() == 16)
				if (getEntityWorld().getTotalWorldTime() % 20 == 0)
					spawnEatingParticles();
			if (getPearlTimer() == 1)
				spawnSpittingParticles();
			if (getPearlTimer() >= 30)
				if (getEntityWorld().getTotalWorldTime() % 10 == 0)
					spawnMakingParticles();
		}

		if (!getEntityWorld().isRemote) {
			if (getPearlTimer() < 0) {
				if (getEntityWorld().getTotalWorldTime() % 5 == 0)
					checkAreaHere();

				if (getAttackTarget() != null) {
					if (!isBeingRidden() && getJawAngle() < 80) {
						setJawAngle(getJawAngle() + 8);
						if (getEatingHeight() > 0)
							setEatingHeight(0);
					}
					if (isBeingRidden() && getJawAngle() > 16)
						setJawAngle(getJawAngle() - 8);
				}

				if (getAttackTarget() == null) {
					if (!isBeingRidden()) {
						if (getJawAngle() > 0 && getTendrilCount() <= 0)
							setJawAngle(getJawAngle() - 8);
					}
				}

				if (isBeingRidden() && getJawAngle() == 16 && getPlacedByPlayer()) {
					if (getEntityWorld().getTotalWorldTime() % 20 == 0) {

						setEatingHeight(getEatingHeight() + 1);
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
						getPassengers().get(0).attackEntityFrom(DamageSource.GENERIC, 0F);
						if (getEatingHeight() == 10 && getPassengers().get(0) != null) {
							setContainedXP(getContainedXP() + Math.round(getXPEaten((EntityLivingBase) getPassengers().get(0)) * 0.5F));
							getPassengers().get(0).setDead();
							if(getContainedXP() >= 10)
								setPearlTimer(PEARL_CREATION_TIME);
							setEatingHeight(0);
							setJawAngle(0);
						}
					}
				}

				if (isBeingRidden() && getJawAngle() == 16 && !getPlacedByPlayer())
					if (getEntityWorld().getTotalWorldTime() % 20 == 0) {
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
						getPassengers().get(0).attackEntityFrom(DamageSource.causeMobDamage(this), (float) getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
					}

			} else {
				if (getPearlTimer() >= 0) {
					setPearlTimer(getPearlTimer() - 1);
					if (getEntityWorld().getTotalWorldTime() % 20 == 0 && getPearlTimer() >= 30)
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_DIGEST, SoundCategory.HOSTILE, 1F, 0.8F + rand.nextFloat() * 0.5F);
				}

				if (getPearlTimer() == 0) {
					int quotient = getContainedXP() / 10;
				    int result = getContainedXP() - quotient * 10;
					setContainedXP(result);
					ItemStack pearl = new ItemStack(ItemRegistry.ROCK_SNOT_PEARL, quotient);
					EntityItem item = new EntityItem(world, posX, posY + 0.5D, posZ, pearl);
					item.motionX = item.motionZ = 0D;
					item.motionY = 0.4D;
					world.spawnEntity(item);
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_SPIT, SoundCategory.HOSTILE, 1F, 1F);
				}
			}
		}
		super.onUpdate();
	}

@SubscribeEvent
    public static void submitBeams(SubmitCustomGeometryEvent e) {
        if (!AdventureConfig.enableAffixItemEffects) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        if (mc.level == null) {
            return;
        }

        Vec3 camPos = e.getLevelRenderState().cameraRenderState.pos;
        PoseStack pose = e.getPoseStack();
        SubmitNodeCollector collector = e.getSubmitNodeCollector();
        float partials = mc.getDeltaTracker().getGameTimeDeltaPartialTick(false);
        long gameTime = mc.level.getGameTime();

        for (Entity ent : mc.level.entitiesForRendering()) {
            if (!(ent instanceof ItemEntity item)) {
                continue;
            }

            ItemStack stack = item.getItem();
            DynamicHolder<LootRarity> rarityHolder = AffixHelper.getRarity(stack);
            if (!rarityHolder.isBound() || !item.onGround()) {
                item.setData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED, false);
                continue;
            }

            if (!item.getData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED)) {
                item.setData(Apoth.Attachments.AFFIX_EFFECT_RENDER_STARTED, true);
                item.setData(Apoth.Attachments.AFFIX_EFFECT_START_TIME, item.tickCount);
            }

            LootRarity rarity = rarityHolder.get();
            RarityRenderData renderData = rarity.renderData();
            int color = rarity.color().getValue();

            float progress = Mth.clamp(item.tickCount - item.getData(Apoth.Attachments.AFFIX_EFFECT_START_TIME) + partials, 0, GROW_IN_TICKS) / GROW_IN_TICKS;

            double x = Mth.lerp(partials, item.xOld, item.getX());
            double y = Mth.lerp(partials, item.yOld, item.getY());
            double z = Mth.lerp(partials, item.zOld, item.getZ());

            // Translate to the item entity in camera space; shadow rendering relies on this outer translation.
            pose.pushPose();
            pose.translate(x - camPos.x, y - camPos.y, z - camPos.z);

            float beamHeight = renderData.beamHeight();
            if (beamHeight > 0) {
                // Center the beam under the item (the beam origin is at the NW corner of a 1x1 block).
                pose.pushPose();
                pose.translate(-item.getBbWidth() * 2, 0, -item.getBbWidth() * 2);

                float beamRadius = renderData.beamRadius();
                float glowRadius = renderData.glowRadius();
                float height = beamHeight * progress;

                // Render four segments of the beam to produce a transparency gradient (fade in, ramp up, solid, fade out).
                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    0.0F, Math.min(height, 0.5F), color(ALPHA_ZERO, color), color(ALPHA_LOW, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    0.5F, Mth.clamp(height, 0, 0.5F), color(ALPHA_LOW, color), color(ALPHA_MAX, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    1.0F, Mth.clamp(height, 0, 0.5F), color(ALPHA_MAX, color), color(ALPHA_MAX, color), beamRadius, glowRadius);
                height -= 0.5F;

                BeamRenderer.renderBeaconBeam(pose, collector, renderData.beamTexture(), renderData.glowTexture(), partials, 1, gameTime,
                    1.5F, Mth.clamp(height, 0, beamHeight), color(ALPHA_MAX, color), color(ALPHA_ZERO, color), beamRadius, glowRadius);

                pose.popPose();
            }

            ShadowData shadow = renderData.shadow();
            ShadowRenderer.renderShadow(pose, collector, item, partials, mc.level, shadow, ARGB.color(shadow.alpha(), color));

            pose.popPose();
        }
    }

public static void tick(Level pLevel, BlockPos pPos, BlockState pState, VampireBeaconBlockEntity pBlockEntity) {
        int i = pPos.getX();
        int j = pPos.getY();
        int k = pPos.getZ();
        BlockPos blockpos;
        if (pBlockEntity.lastCheckY < j) {
            blockpos = pPos;
            pBlockEntity.checkingBeamSections = Lists.newArrayList();
            pBlockEntity.lastCheckY = pPos.getY() - 1;
        } else {
            blockpos = new BlockPos(i, pBlockEntity.lastCheckY + 1, k);
        }

        BeaconBeamOwner.Section beaconblockentity$beaconbeamsection = pBlockEntity.checkingBeamSections.isEmpty()
                ? null
                : pBlockEntity.checkingBeamSections.getLast();
        int l = pLevel.getHeight(Heightmap.Types.WORLD_SURFACE, i, k);

        for (int i1 = 0; i1 < BLOCKS_CHECK_PER_TICK && blockpos.getY() <= l; i1++) {
            BlockState blockstate = pLevel.getBlockState(blockpos);
            Integer j1 = blockstate.getBeaconColorMultiplier(pLevel, blockpos, pPos);
            if (j1 != null) {
                if (pBlockEntity.checkingBeamSections.size() <= 1) {
                    beaconblockentity$beaconbeamsection = new BeaconBeamOwner.Section(j1);
                    pBlockEntity.checkingBeamSections.add(beaconblockentity$beaconbeamsection);
                } else if (beaconblockentity$beaconbeamsection != null) {
                    if (j1 == beaconblockentity$beaconbeamsection.getColor()) {
                        beaconblockentity$beaconbeamsection.increaseHeight();
                    } else {
                        beaconblockentity$beaconbeamsection = new BeaconBeamOwner.Section(
                                ARGB.average(beaconblockentity$beaconbeamsection.getColor(), j1)
                        );
                        pBlockEntity.checkingBeamSections.add(beaconblockentity$beaconbeamsection);
                    }
                }
            } else {
                if (beaconblockentity$beaconbeamsection == null || blockstate.getLightDampening() >= 15 && !blockstate.is(Blocks.BEDROCK)) {
                    pBlockEntity.checkingBeamSections.clear();
                    pBlockEntity.lastCheckY = l;
                    break;
                }

                beaconblockentity$beaconbeamsection.increaseHeight();
            }

            blockpos = blockpos.above();
            pBlockEntity.lastCheckY++;
        }

        int k1 = pBlockEntity.levels;
        if (pLevel.getGameTime() % 80L == 0L) {
            if (!pBlockEntity.beamSections.isEmpty()) {
                Pair<Integer, Integer> integerBooleanPair = updateBase(pLevel, i, j, k);
                pBlockEntity.levels = integerBooleanPair.getLeft();
                pBlockEntity.isUpgraded = integerBooleanPair.getRight();
            }

            if (pBlockEntity.levels > 0 && !pBlockEntity.beamSections.isEmpty()) {
                pBlockEntity.applyEffects(pLevel, pPos, pBlockEntity.levels, pBlockEntity.primaryPower, pBlockEntity.effectAmplifier + pBlockEntity.isUpgraded);
                playSound(pLevel, pPos, SoundEvents.BEACON_AMBIENT);
            }
        }

        if (pBlockEntity.lastCheckY >= l) {
            pBlockEntity.lastCheckY = pLevel.getMinY() - 1;
            boolean flag = k1 > 0;
            pBlockEntity.beamSections = pBlockEntity.checkingBeamSections;
            if (!pLevel.isClientSide()) {
                boolean flag1 = pBlockEntity.levels > 0;
                if (!flag && flag1) {
                    playSound(pLevel, pPos, SoundEvents.BEACON_ACTIVATE);

                    for (ServerPlayer serverplayer : pLevel.getEntitiesOfClass(
                            ServerPlayer.class, new AABB(i, j, k, i, j - MAX_LEVELS, k).inflate(10.0, 5.0, 10.0)
                    )) {
                        CriteriaTriggers.CONSTRUCT_BEACON.trigger(serverplayer, pBlockEntity.levels);
                    }
                } else if (flag && !flag1) {
                    playSound(pLevel, pPos, SoundEvents.BEACON_DEACTIVATE);
                }
            }
        }
    }

