@SubscribeEvent
	public void onProjectileImpact(ProjectileImpactEvent event) {
		if (event.getRayTraceResult() instanceof EntityHitResult) {
			EntityHitResult result = (EntityHitResult) event.getRayTraceResult();

			if (result.getEntity() instanceof Player) {
				Player player = (Player) result.getEntity();
				Entity arrow = event.getEntity();

				if (!player.level().isClientSide) {
					if (arrow instanceof Projectile) {
						Projectile projectile = (Projectile) arrow;

						if (projectile.getOwner() == player) {
							for (String tag : arrow.getTags()) {
								if (tag.startsWith("AB_DEFLECTED")) {
									try {
										int time = Integer.parseInt(tag.split(":")[1]);
										if (arrow.tickCount - time < 10)
											// If we cancel the event here it gets stuck in the infinite loop
											return;
									} catch (Exception ex) {
										ex.printStackTrace();
									}
								}
							}
						}
					}

					boolean trigger = false;
					double chance = 0.0D;

					if (SuperpositionHandler.hasCurio(player, EnigmaticItems.ANGEL_BLESSING)) {
						trigger = true;
						chance += AngelBlessing.deflectChance.getValue().asModifier(false);
					}

					if (SuperpositionHandler.hasCurio(player, EnigmaticItems.THE_CUBE)) {
						trigger = true;
						chance += 0.35;
					}

					if (EnigmaticItems.ENIGMATIC_AMULET.hasColor(player, AmuletColor.VIOLET)) {
						trigger = true;
						chance += 0.15;
					}

					if (trigger && Math.random() <= chance) {
						event.setCanceled(true);

						arrow.setDeltaMovement(arrow.getDeltaMovement().scale(-1.0D));
						arrow.yRotO = arrow.getYRot() + 180.0F;
						arrow.setYRot(arrow.getYRot() + 180.0F);;

						if (arrow instanceof AbstractArrow absar) {
							if (!(absar instanceof ThrownTrident)) {
								absar.setOwner(player);
							}

							((AccessorAbstractArrowEntity)absar).clearHitEntities();
							absar.pickup = Pickup.CREATIVE_ONLY;
							absar.setPierceLevel((byte) 0);
						} else if (arrow instanceof AbstractHurtingProjectile) {
							((AbstractHurtingProjectile) arrow).setOwner(player);

							((AbstractHurtingProjectile) arrow).xPower = -((AbstractHurtingProjectile) arrow).xPower;
							((AbstractHurtingProjectile) arrow).yPower = -((AbstractHurtingProjectile) arrow).yPower;
							((AbstractHurtingProjectile) arrow).zPower = -((AbstractHurtingProjectile) arrow).zPower;
						}

						arrow.getTags().removeIf(tag -> tag.startsWith("AB_DEFLECTED"));
						arrow.addTag("AB_DEFLECTED:" + arrow.tickCount);

						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 64.0D, player.level().dimension())), new PacketForceArrowRotations(arrow.getId(), arrow.getYRot(), arrow.getXRot(), arrow.getDeltaMovement().x, arrow.getDeltaMovement().y, arrow.getDeltaMovement().z, arrow.getX(), arrow.getY(), arrow.getZ()));
						player.level().playSound(null, player.blockPosition(), EnigmaticSounds.DEFLECT, SoundSource.PLAYERS, 1.0F, 0.95F + (float) (Math.random() * 0.1D));
					}
				} /*else {
					if (event.getEntity().getTags().contains("enigmaticlegacy.redirected")) {
						event.setCanceled(true);
						event.getEntity().removeTag("enigmaticlegacy.redirected");
					}
				}*/
			}
		}
	}

public static Multimap<PackagerBlockEntity, PackagingRequest> findPackagersForRequest(UUID freqId,
																						  PackageOrderWithCrafts order, @Nullable IdentifiedInventory ignoredHandler, String address) {
		List<BigItemStack> stacks = new ArrayList<>();

		for (BigItemStack stack : order.stacks())
			if (!stack.stack.isEmpty() && stack.count > 0)
				stacks.add(stack);

		Multimap<PackagerBlockEntity, PackagingRequest> requests = HashMultimap.create();

		// Packages need to track their index and successors for successful defrag
		Iterable<LogisticallyLinkedBehaviour> allAvailableLinks = LogisticallyLinkedBehaviour.getAllPresent(freqId,
			true);

		// Group links by InventoryIdentifier and randomly select one from each group
		Map<InventoryIdentifier, List<LogisticallyLinkedBehaviour>> linksByInventory = new HashMap<>();
		List<LogisticallyLinkedBehaviour> availableLinks = new ArrayList<>();

		// Group links by their inventory identifier
		for (LogisticallyLinkedBehaviour link : allAvailableLinks) {
			InventoryIdentifier inventoryId = getInventoryIdentifierFromLink(link);
			if (inventoryId != null) {
				linksByInventory.computeIfAbsent(inventoryId, k -> new ArrayList<>()).add(link);
			} else {
				// Links without inventory identifier are added directly
				availableLinks.add(link);
			}
		}

		// Randomly select one link from each inventory group
		for (List<LogisticallyLinkedBehaviour> linkGroup : linksByInventory.values()) {
			if (!linkGroup.isEmpty()) {
				LogisticallyLinkedBehaviour selectedLink = linkGroup.get(r.nextInt(linkGroup.size()));
				availableLinks.add(selectedLink);
			}
		}

		List<LogisticallyLinkedBehaviour> usedLinks = new ArrayList<>();
		MutableBoolean finalLinkTracker = new MutableBoolean(false);

		// First box needs to carry the order specifics for successful defrag
		PackageOrderWithCrafts context = order;

		// Packages from future orders should not be merged in the packager queue
		int orderId = r.nextInt();

		for (int i = 0; i < stacks.size(); i++) {
			BigItemStack entry = stacks.get(i);
			int remainingCount = entry.count;
			boolean finalEntry = i == stacks.size() - 1;
			ItemStack requestedItem = entry.stack;

			for (LogisticallyLinkedBehaviour link : availableLinks) {
				int usedIndex = usedLinks.indexOf(link);
				int linkIndex = usedIndex == -1 ? usedLinks.size() : usedIndex;
				MutableBoolean isFinalLink = new MutableBoolean(false);
				if (linkIndex == usedLinks.size() - 1)
					isFinalLink = finalLinkTracker;

				// Only send context and craftingContext with first package
				Pair<PackagerBlockEntity, PackagingRequest> request = link.processRequest(requestedItem, remainingCount,
					address, linkIndex, isFinalLink, orderId, context, ignoredHandler);
				if (request == null)
					continue;

				requests.put(request.getFirst(), request.getSecond());

				int processedCount = request.getSecond()
					.getCount();
				if (processedCount > 0 && usedIndex == -1) {
					context = null;
					usedLinks.add(link);
					finalLinkTracker = isFinalLink;
				}

				remainingCount -= processedCount;
				if (remainingCount > 0)
					continue;
				if (finalEntry)
					finalLinkTracker.setTrue();
				break;
			}
		}
		return requests;
	}

@Override
	public InteractionResult useOn(UseOnContext pContext) {
		ItemStack stack = pContext.getItemInHand();
		BlockPos pos = pContext.getClickedPos();
		Level level = pContext.getLevel();
		BlockState state = level.getBlockState(pos);
		Player player = pContext.getPlayer();
		String msgKey = getMessageTranslationKey();
		int maxDistance = getMaxDistanceFromSelection();

		if (player == null)
			return InteractionResult.FAIL;

		if (player.isShiftKeyDown() && stack.has(AllDataComponents.CLICK_TO_LINK_DATA)) {
			if (level.isClientSide)
				return InteractionResult.SUCCESS;
			player.displayClientMessage(CreateLang.translateDirect(msgKey + ".clear"), true);
			stack.remove(AllDataComponents.CLICK_TO_LINK_DATA);
			stack.remove(DataComponents.BLOCK_ENTITY_DATA);
			return InteractionResult.SUCCESS;
		}

		ResourceLocation placedDim = level.dimension()
			.location();

		if (!stack.has(AllDataComponents.CLICK_TO_LINK_DATA)) {
			if (!isValidTarget(level, pos)) {
				if (placeWhenInvalid()) {
					InteractionResult useOn = super.useOn(pContext);
					if (level.isClientSide || useOn == InteractionResult.FAIL)
						return useOn;

					ItemStack itemInHand = player.getItemInHand(pContext.getHand());
					if (!itemInHand.isEmpty()) {
						stack.remove(AllDataComponents.CLICK_TO_LINK_DATA);
						stack.remove(DataComponents.BLOCK_ENTITY_DATA);
					}
					return useOn;
				}

				if (level.isClientSide)
					AllSoundEvents.DENY.playFrom(player);
				player.displayClientMessage(CreateLang.translateDirect(msgKey + ".invalid"), true);
				return InteractionResult.FAIL;
			}

			if (level.isClientSide)
				return InteractionResult.SUCCESS;

			player.displayClientMessage(CreateLang.translateDirect(msgKey + ".set"), true);
			stack.set(AllDataComponents.CLICK_TO_LINK_DATA, new ClickToLinkData(pos, placedDim));
			return InteractionResult.SUCCESS;
		}

		ClickToLinkData data = stack.get(AllDataComponents.CLICK_TO_LINK_DATA);
		//noinspection DataFlowIssue
		BlockPos selectedPos = data.selectedPos();
		ResourceLocation selectedDim = data.selectedDim();
		BlockPos placedPos = pos.relative(pContext.getClickedFace(), state.canBeReplaced() ? 0 : 1);

		if (maxDistance != -1 && (!selectedPos.closerThan(placedPos, maxDistance) || !selectedDim.equals(placedDim))) {
			player.displayClientMessage(CreateLang.translateDirect(msgKey + ".too_far")
				.withStyle(ChatFormatting.RED), true);
			return InteractionResult.FAIL;
		}

		CompoundTag beTag = new CompoundTag();
		beTag.put("TargetOffset", NbtUtils.writeBlockPos(selectedPos.subtract(placedPos)));
		NBTHelper.writeResourceLocation(beTag, "TargetDimension", selectedDim);
		BlockEntity.addEntityType(beTag, ((IBE<?>) this.getBlock()).getBlockEntityType());
		stack.set(DataComponents.BLOCK_ENTITY_DATA, CustomData.of(beTag));

		InteractionResult useOn = super.useOn(pContext);
		if (level.isClientSide || useOn == InteractionResult.FAIL)
			return useOn;

		ItemStack itemInHand = player.getItemInHand(pContext.getHand());
		if (!itemInHand.isEmpty()) {
			stack.remove(AllDataComponents.CLICK_TO_LINK_DATA);
			stack.remove(DataComponents.BLOCK_ENTITY_DATA);
		}
		player.displayClientMessage(CreateLang.translateDirect(msgKey + ".success")
			.withStyle(ChatFormatting.GREEN), true);
		return useOn;
	}

public static void handle(PacketSwapBlock message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {

      var player = ctx.player();
      ItemStack itemStackHeld = player.getItemInHand(message.hand);
      BlockState targetState = BuilderActionType.getBlockState(player.level(), itemStackHeld);
      if (targetState == null || itemStackHeld.getItem() instanceof BuilderItem == false) {
        return;
      }
      BuildStyle buildStyle = ((BuilderItem) itemStackHeld.getItem()).style;
      Level world = player.getCommandSenderWorld();
      IEnergyStorage storage = CapabilityUtil.energy(itemStackHeld);
      final int cost = BuilderItem.COST.get();
      if (storage == null || storage.extractEnergy(cost, true) < cost) {
        return;
      }
      BlockState replacedBlockState;
      List<BlockPos> places = getSelectedBlocks(world, message.pos, message.actionType, message.side, buildStyle);
      Map<BlockPos, Integer> processed = new HashMap<BlockPos, Integer>();
      BlockPos curPos;
      synchronized (places) {
        for (Iterator<BlockPos> i = places.iterator(); i.hasNext();) {
          curPos = i.next();
          if (storage.extractEnergy(cost, true) < cost) {
            break;
          }
          if (processed.containsKey(curPos) == false) {
            processed.put(curPos, 0);
          }
          if (processed.get(curPos) > 0) {
            continue; //dont process the same location more than once per click
          }
          processed.put(curPos, processed.get(curPos) + 1);
          int slot = PlayerUtil.getFirstSlotWithBlock(player, targetState);
          if (slot < 0) {
            //nothign found. is that ok?
            if (!player.isCreative()) {
              ChatUtil.sendStatusMessage(player, "scepter.cyclic.empty");
              break;
              //you have no materials left
            }
          }
          if (world.getBlockEntity(curPos) != null) {
            continue;
            //ignore tile entities IE do not break chests / etc
          }
          replacedBlockState = world.getBlockState(curPos);
          Block replacedBlock = replacedBlockState.getBlock();
          boolean isInBlacklist = false;
          //          for (String s : ItemBuildSwapper.swapBlacklist) {//dont use .contains on the list. must use .equals on string
          //            if (s != null && s.equals(itemName)) {
          //              isInBlacklist = true;
          //              break;
          //            }
          //          }
          if (isInBlacklist) {
            continue;
          }
          if (replacedBlockState.getDestroySpeed(world, curPos) < 0) {
            continue; //since we know -1 is unbreakable
          }
          //wait, do they match? are they the same? do not replace myself
          if (LevelWorldUtil.doBlockStatesMatch(replacedBlockState, targetState)) {
            continue;
          }
          //break it and drop the whatever
          //the destroy then set was causing exceptions, changed to setAir // https://github.com/PrinceOfAmber/Cyclic/issues/114
          world.setBlock(curPos, Blocks.AIR.defaultBlockState(), 0);
          boolean success = false;
          //place item block gets slabs in top instead of bottom. but tries to do facing stairs
          // success = UtilPlaceBlocks.placeItemblock(world, curPos, stackBuildWith, player);
          if (!success) {
            success = BlockUtil.placeStateSafe(world, player, curPos, targetState);
          }
          if (success) {
            storage.extractEnergy(cost, false);
            PlayerUtil.decrStackSize(player, slot);
            world.levelEvent(2001, curPos, Block.getId(targetState));
            //always break with PLAYER CONTEXT in mind
            replacedBlock.playerDestroy(world, player, curPos, replacedBlockState, null, itemStackHeld);
          }
        } // close off the for loop
      }
    });
  }

@Override
	public void onUpdate() {
		this.prevJumpAnimationTicks = this.jumpAnimationTicks;
		super.onUpdate();
		if (this.onGround || (this.strokeTicks == 0 && this.isInWater())) {
			this.ticksOnGround++;
			if (this.jumpAnimationTicks > 0)
				this.jumpAnimationTicks = 0;
		} else {
			this.ticksOnGround = 0;
			this.jumpAnimationTicks++;
		}
		if (this.strokeTicks > 0)
			this.strokeTicks--;
		if (!this.world.isRemote) {
			if (this.strokeTicks > 0) {
				this.strokeTicks--;
				this.dataManager.set(DW_SWIM_STROKE, (byte) 1);
			} else {
				this.dataManager.set(DW_SWIM_STROKE, (byte) 0);
			}
		} else {
			if (this.dataManager.get(DW_SWIM_STROKE) == 1) {
				if (this.strokeTicks < 20)
					this.strokeTicks++;
			} else {
				this.strokeTicks = 0;
			}
		}
		if (!this.world.isRemote) {
			this.setAir(20);

			Path path = getNavigator().getPath();
			if (path != null && !path.isFinished() && (onGround || this.isInWater()) && !this.isMovementBlocked()) {
				int index = path.getCurrentPathIndex();
				if (index < path.getCurrentPathLength()) {
					PathPoint nextHopSpot = path.getPathPointFromIndex(index);
					float x = (float) (nextHopSpot.x - posX);
					float z = (float) (nextHopSpot.z - posZ);
					float angle = (float) (Math.atan2(z, x));
					float distance = (float) Math.sqrt(x * x + z * z);
					double speedMultiplier = Math.min(distance / 2.0D, 1);
					if (distance > 0.5D) {
						if (!this.isInWater()) {
							if (this.ticksOnGround > 5) {
								this.motionY += 0.4;
								this.motionX += 0.4 * MathHelper.cos(angle) * speedMultiplier;
								this.motionZ += 0.4 * MathHelper.sin(angle) * speedMultiplier;
								this.velocityChanged = true;
							}
						} else {
							if (this.strokeTicks == 0) {
								this.motionY += (nextHopSpot.y < this.posY ? -0.2D : 0.2D) * speedMultiplier;
								this.motionX += 0.45 * MathHelper.cos(angle) * speedMultiplier;
								this.motionZ += 0.45 * MathHelper.sin(angle) * speedMultiplier;
								this.velocityChanged = true;
								this.strokeTicks = 40;
								this.world.setEntityState(this, (byte) 8);
							} else if (this.collidedHorizontally) {
								motionX += 0.01 * MathHelper.cos(angle);
								motionZ += 0.01 * MathHelper.sin(angle);
							}
						}
					} else {
						path.incrementPathIndex();
					}
				}
			}

			if (!this.world.isRemote) {
				if (this.motionY < 0.0F && this.world.getBlockState(new BlockPos(MathHelper.floor(this.posX), MathHelper.floor(this.posY + 0.4D), MathHelper.floor(this.posZ))).getMaterial().isLiquid()) {
					this.motionY *= 0.1F;
					this.velocityChanged = true;
				}

				if ((path == null || path.isFinished()) && this.world.getBlockState(new BlockPos(MathHelper.floor(this.posX), MathHelper.floor(this.posY + 0.5D), MathHelper.floor(this.posZ))).getMaterial().isLiquid()) {
					this.motionY += 0.04F;
					this.velocityChanged = true;
				}
			}
		}

		if (world.isRemote && getSkin() == 4 && world.getTotalWorldTime() % 10 == 0) {
			BLParticles.DIRT_DECAY.spawn(world, posX, posY + 0.5D, posZ);
		}
	}

public BlockPos groundBlock(boolean ignoreAir) {
        Block block = this.blockState.getBlock();
        BlockPos blockpos = this.blockPosition();
        BlockState blockstate = this.level.getBlockState(blockpos);
        boolean isConcrete = this.blockState.getBlock() instanceof ConcretePowderBlock;
        boolean isConcreteInWater = isConcrete && this.level.getFluidState(blockpos).is(FluidTags.WATER);
        this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.5D, 0.7D));
        if (blockstate.is(Blocks.MOVING_PISTON))
            return null;
        if (this.cancelDrop) {
            this.discard();
            this.callOnBrokenAfterFall(block, blockpos);
            return null;
        }
        boolean canBeReplaced = blockstate.canBeReplaced(new DirectionalPlaceContext(this.level, blockpos, Direction.DOWN, ItemStack.EMPTY, Direction.UP));
        boolean isFreeBelow = FallingBlock.isFree(this.level.getBlockState(blockpos.below())) && (!isConcrete || !isConcreteInWater);
        boolean canSurvive = this.blockState.canSurvive(this.level, blockpos) && (!isFreeBelow || ignoreAir);
        if (canBeReplaced && canSurvive) {
            if (this.blockState.hasProperty(BlockStateProperties.WATERLOGGED) && this.level.getFluidState(blockpos).getType() == Fluids.WATER) {
                this.blockState = this.blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.TRUE);
            }

            if (this.level.setBlock(blockpos, this.blockState, 3)) {
                ((ServerLevel) this.level).getChunkSource().chunkMap.broadcast(this, new ClientboundBlockUpdatePacket(blockpos, this.level.getBlockState(blockpos)));
                this.discard();
                if (block instanceof Fallable fallable) {
                    fallable.onLand(this.level, blockpos, this.blockState, blockstate, new FallingBlockEntity(level, this.getX(), this.getY(), this.getZ(), this.blockState));
                } else if (context != null && resolver != null) {
                    RewindAttachment.get(context).addRewindEvent(level.getGameTime(), new EntityToBlockRewind(this, blockpos, this.blockState));
                    ShapersFocus.tryPropagateBlockSpell(new BlockHitResult(
                            new Vec3(blockpos.getX(), blockpos.getY(), blockpos.getZ()), Direction.DOWN, blockpos, false
                    ), level, getOwner(), context, resolver);
                }

                if (this.blockData != null && this.blockState.hasBlockEntity()) {
                    BlockEntity blockentity = this.level.getBlockEntity(blockpos);
                    if (blockentity != null) {

                        try {
                            blockentity.loadWithComponents(this.blockData, level.registryAccess());
                            if (blockentity instanceof SkullBlockEntity sk && this.blockData != null && this.blockData.contains("SkullOwner")) {
                                sk.setOwner(ANCodecs.decode(level.registryAccess(), ResolvableProfile.CODEC, this.blockData.getCompound("SkullOwner")));
                            }
                        } catch (Exception exception) {
                            exception.printStackTrace();
                        }

                        blockentity.setChanged();
                    }
                }
                if (this.level.getBlockEntity(blockpos) instanceof MageBlockTile mbt) {
                    if (context != null) {
                        mbt.color = context.getSpell().particleTimeline().get(ParticleTimelineRegistry.MAGEBLOCK_TIMELINE.get()).getColor();
                    }
                    mbt.setChanged();
                }

                return blockpos;
            } else if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.discard();
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));
                }
                this.spawnAtLocation(itemstack);
                return null;
            }
        } else {
            this.discard();
            if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));

                }
                this.spawnAtLocation(itemstack);
            }
        }
        return null;
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide && !initMusic) {
            initMusic = true;
            ((Runnable) () -> ChimeraMusic.play(WildenChimera.this)).run();
        }

        // written like this allows for hotswap
        // this.goalSelector.getAvailableGoals().stream().filter(WrappedGoal::isRunning).map(WrappedGoal::getGoal).forEach(System.out::println);


        if (!level.isClientSide && isDefensive()) {
            this.getNavigation().stop();
        }
        if (level.isClientSide && isFlying() && random.nextInt(18) == 0) {

            this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.BAT_LOOP, this.getSoundSource(),
                    0.95F + this.random.nextFloat() * 0.05F,
                    0.3f + this.random.nextFloat() * 0.05F,
                    false);

        }

        if (!level.isClientSide && this.isInLava() && this.level.getGameTime() % 10 == 0) {
            this.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 20, 4));
            this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, 3));
            this.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 20));
            this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20, 3));

        }

        if (this.isFlying()) {
            this.navigation.stop();
            flyingNavigator.tick();
        }

        if (!level.isClientSide) {
            // Reduce skill cooldown
            if (diveCooldown > 0) {
                diveCooldown--;
                if (this.isInLava() || this.isInWater())
                    diveCooldown -= 2;
            }
            if (summonCooldown > 0) summonCooldown--;
            if (spikeCooldown > 0) spikeCooldown--;
            if (ramCooldown > 0) ramCooldown--;

            if (getTarget() != null && this.invulnerableTime == 0 && !this.isDefensive() && !this.isFlying() && (this.onGround() || isInWater())) {
                var path = getNavigation().createPath(getTarget(), 1);
                if (path == null || !path.canReach() || getTarget().getY() - (this.getY() + 2) >= 3) {
                    rageTimer--;
                }
            }

        }

        if (!level.isClientSide && getPhaseSwapping() && !this.dead) {
            if (swapTicks < 60) {
                swapTicks++;
                this.navigation.stop();
            } else {
                this.removeAllEffects();
                this.setPhaseSwapping(false);
                for (LivingEntity e : level.getEntitiesOfClass(Player.class, new AABB(this.blockPosition()).inflate(5))) {
                    EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(level, new Spell().add(MethodTouch.INSTANCE)
                            .add(EffectLaunch.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            .add(EffectDelay.INSTANCE)
                            .add(EffectKnockback.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            , this, new LivingCaster(this)));
                    resolver.onCastOnEntity(ItemStack.EMPTY, e, InteractionHand.MAIN_HAND);
                }
                getRandomUpgrade();
                ParticleUtil.spawnPoof((ServerLevel) level, blockPosition().above());
                if (getPhase() == 1)
                    rageTimer = 200;
                swapTicks = 0;
            }
        }

        if (getPhaseSwapping() && level.isClientSide) {
            spawnPhaseParticles(blockPosition(), level, getPhase());
        }
    }

public void tick() {
        if (this.level.hasNeighborSignal(this.getBlockPos())) {
            this.miningTime = 0;
            return;
        }
        if (!this.level.isClientSide()) {
            ItemStack input = this.inputHandler.getStackInSlot(0);

            if (!this.cachedEnchantment) {
                this.setCachedEnchantment();
                this.cachedEnchantment = true;
            }

            // handle unusing enchantment from evilcraft, see
            // https://github.com/klikli-dev/occultism/issues/909
            if (input.isEnchanted() && input.getMaxDamage() - input.getDamageValue() < 6 &&
                    this.UNUSING != null && input.getEnchantmentLevel(this.UNUSING) > 0) {
                this.miningTime = 0;
                return;
            }

            if (this.miningTime > 0) {

                int efficiency = this.bonusEfficiency && input.isEnchanted() ? input.getEnchantmentLevel(this.EFFICIENCY) : 0;
                if (efficiency > 0) {
                    int extra1 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                    int extra2 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                    efficiency = Math.min(extra1, extra2);
                }

                this.miningTime -= 1 + efficiency;

                if (this.miningTime <= 0 && !this.level.isClientSide()) {
                    this.mine();
                }

                if (input.getItem() != this.currentInputType) {
                    this.miningTime = 0;
                    this.possibleResults = null;
                }

                // handled by delta check
            } else if (!input.isEmpty()) {

                this.currentInputType = input.getItem();

                forceInitStackNBT(input, (ServerLevel) this.level);
                this.maxMiningTime = getMaxMiningTime(input);
                this.rollsPerOperation = getRollsPerOperation(input);
                this.outputMultiplier = getOutputMultiplier(input);
                this.miningTime = this.maxMiningTime;
            }

            // Sync Logic
            boolean needsSync = this.maxMiningTime != this.lastSyncedMaxMiningTime;

            // Sync if max mining time changed (e.g. new item with different stats)

            // Sync if mining active state changes (0 <-> >0)
            boolean wasActive = this.lastSyncedMiningTime > 0;
            boolean isActive = this.miningTime > 0;
            if (wasActive != isActive) {
                needsSync = true;
            }

            // Syncs if progress drifts by 10
            if (Math.abs(this.miningTime - this.lastSyncedMiningTime) >= 10) {
                needsSync = true;
            }
            // Also sync if we just finished (already covered by 0 check above? sorta).

            if (needsSync) {
                this.markNetworkDirty();
            }

            if (this.outputDirty) {
                this.setChanged();
                this.outputDirty = false;
            }
        } else {
            if (this.miningTime > 0 && this.level.getGameTime() % 10 == 0) {
                this.level.addParticle(ParticleTypes.PORTAL, this.worldPosition.getX() + 0.5f,
                        this.worldPosition.getY() + 0.5, this.worldPosition.getZ() + 0.5f, 0.0D, 0.0D, 0.0D);
            }
        }
    }

@Override
    public void onEntityUpdate() {

        if (!world.isRemote) {
            if (this.getHealth() < 0 && !this.isDead) {
                this.setDead();
                if (this.world.getGameRules().getBoolean("doEntityDrops")) {
                    this.dropItems();
                    ItemStack recordItem = this.dataManager.get(RECORD_ITEM);
                    if (!recordItem.isEmpty()) {
                        this.entityDropItem(recordItem, 0);
                    }
                }
            }

        }

        for (int i = 0; i < this.seats.length; i++) {
            Entity e = this.getEntityInSeat(i);
            if(e != null && e instanceof EntityPlayerMP) {
                resetFlyTicks((EntityPlayerMP) e);
            }
        }

        if (this.getSpeed() == Speed.FAST) {
            this.allWheels.forEach(wheel -> this.createWheelParticles(wheel, true));
        }
        this.allWheels.forEach(this::createWheelParticles);

        if (shouldStopUpdates()) {
            super.onEntityUpdate();
            return;
        }
        if (!world.isRemote) {
            if (prevWorldTime != -1) {
                world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(0.1f),
                        this::canRunoverEntity).forEach(this::runOverEntity);
            }
        }
        if (this.isInWater()) {
            for (int i = 0; i < this.seats.length; i++) {
                Entity e = this.getEntityInSeat(i);
                if (e != null) {
                    e.attackEntityFrom(DamageSource.DROWN, 0.5f);
                }
            }
            this.setHealth(this.getHealth() - 0.25F);
        }
        if (previousPosition == null) {
            previousPosition = this.getPositionVector();
        }
        estimatedSpeed = this.getPositionVector().distanceTo(previousPosition)
                / (world.getTotalWorldTime() - prevWorldTime);
        previousPosition = this.getPositionVector();
        prevWorldTime = world.getTotalWorldTime();

        for (int i = 0; i < 4; i++) {
            List<WheelParticleData> markedRemoved = Lists.newArrayList();
            wheelDataList[i].forEach(wheel -> wheel.onUpdate(markedRemoved));
            markedRemoved.forEach(wheelDataList[i]::remove);
        }

        super.onEntityUpdate();

        this.allWheels.forEach(this::processWheel);

        Vector4d vec = wheeldata.carVector;
        this.backValue.setTarget(this.calculateWheelHeight(vec.y, false));
        this.frontValue.setTarget(this.calculateWheelHeight(vec.w, false));
        this.leftValue.setTarget(this.calculateWheelHeight(vec.z, true));
        this.rightValue.setTarget(this.calculateWheelHeight(vec.x, true));

        if (!this.world.isRemote) {
            this.updateHeal();
        }

        this.tickInterp();
        this.updateMotion();
        if (this.getPassengers().isEmpty() || !(this.getPassengers().get(0) instanceof EntityPlayer)) {
            this.setControlState((byte) 0);
        }
        if (this.world.isRemote) {
            this.handleControl();
        }
        this.applyMovement();
        this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
    }

public void tick() {
        super.tick();
        prevRunProgress = runProgress;
        prevShadeProgress = shadeProgress;
        Entity possessedEntity = getPossessedEntity();
        if (isRunning() && runProgress < 5F) {
            runProgress++;
        }
        if (!isRunning() && runProgress > 0F) {
            runProgress--;
        }
        if (isShadeMode() && shadeProgress < 5F) {
            shadeProgress++;
        }
        if (!isShadeMode() && shadeProgress > 0F) {
            shadeProgress--;
        }
        if (isShadeMode()) {
            this.fallDistance = 0;
            if (this.isLandNavigator) {
                switchNavigator(false);
            }
        } else {
            if (!this.isLandNavigator) {
                switchNavigator(true);
            }
        }
        if (possessedEntity instanceof Player) {
            this.yHeadRot = Mth.approachDegrees(this.yHeadRotO, yHeadRot, 3);
        }
        if (!level().isClientSide) {
            if (possessedEntity != null && possessedEntity.isAlive()) {
                double dist = possessedEntity.distanceTo(this);
                if (this.entityData.get(POSSESSED_ENTITY_ID) != possessedEntity.getId()) {
                    this.entityData.set(POSSESSED_ENTITY_ID, possessedEntity.getId());
                    this.setPossessionStrength(1.0F);
                }
                lastPossessionTimestamp = this.tickCount;
                if (possessedTimeout++ > 140) {
                    this.setPossessionStrength(Math.max(0, this.getPossessionStrength(1.0F) + 0.1F));
                }
                if (dist < 1 || stopPossession(possessedEntity) || !this.isAlive()) {
                    if(possessedEntity instanceof WatcherPossessionAccessor possessionAccessor){
                        possessionAccessor.setPossessedByWatcher(false);
                    }
                    if(possessedEntity instanceof Player player){
                        setLastPossessedTimeFor(player);
                    }
                    this.level().broadcastEntityEvent(this, (byte) 78);
                    this.setPossessedEntityUUID(null);
                    this.entityData.set(POSSESSED_ENTITY_ID, -1);
                } else {
                    this.level().broadcastEntityEvent(this, (byte) 77);
                    if (possessedEntity instanceof LivingEntity living) {
                        living.zza = 0;
                        living.yya = 0;
                        living.xxa = 0;
                    }
                }
            } else {
                if(possessedEntity != null || this.entityData.get(POSSESSED_ENTITY_ID) != -1){
                    this.level().broadcastEntityEvent(this, (byte) 78);
                }
                possessedTimeout = 0;
                this.entityData.set(POSSESSED_ENTITY_ID, -1);
            }
        } else if (possessedEntity instanceof LivingEntity living) {
            living.zza = 0;
            living.yya = 0;
            living.xxa = 0;
            if (this.getPossessionStrength(1.0F) == 0) {
                isPossessionBreakable = true;
            }
            if (living instanceof Player player && isPossessionBreakable) {
                player.jumping = false;
                Player clientSidePlayer = AlexsCaves.PROXY.getClientSidePlayer();
                if (AlexsCaves.PROXY.isKeyDown(-1) && player == clientSidePlayer) {
                    AlexsCaves.sendMSGToServer(new PossessionKeyMessage(this.getId(), player.getId(), 0));
                }
            }
            if (prevPossessedEntity != living) {
                isPossessionBreakable = false;
            }
            prevPossessedEntity = living;
        } else {
            prevPossessedEntity = null;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        this.noPhysics = true;
        if (this.getItem().isEmpty()){
            this.discard();
        }
        Vec3 vec3 = this.getDeltaMovement();
        double d0 = this.getX() + vec3.x;
        double d1 = this.getY() + vec3.y;
        double d2 = this.getZ() + vec3.z;
        double d3 = vec3.horizontalDistance();
        this.setXRot(lerpRotation(this.xRotO, (float)(Mth.atan2(vec3.y, d3) * (double)(180F / (float)Math.PI))));
        this.setYRot(lerpRotation(this.yRotO, (float)(Mth.atan2(vec3.x, vec3.z) * (double)(180F / (float)Math.PI))));
        if (this.getOwner() != null){
            double d4 = this.getOwner().getX() - this.getX();
            double d5 = this.getOwner().getZ() - this.getZ();
            this.setYRot(-((float) Mth.atan2(d4, d5)) * (180F / (float) Math.PI));
        }
        if (!this.level.isClientSide) {
            ++this.life;
            if (this.life < 80){
                this.setDeltaMovement(0.0D, 0.05D, 0.0D);
            } else if (this.life > 100) {
                if (this.getOwner() != null && this.getOwner().level.dimension() == this.level.dimension()) {
                    if (this.getOwner().distanceTo(this) >= 64){
                        this.teleportTowards(this.getOwner());
                    } else {
                        Vec3 vector3d = this.getOwner().getEyePosition();
                        Vec3 vector3d1 = this.position();
                        Vec3 vector3d2 = vector3d.subtract(vector3d1);
                        if (vector3d2.lengthSqr() > 1) {
                            vector3d2.normalize();
                        }
                        double speed = 0.1D;
                        Vec3 motion = new Vec3(vector3d2.x * speed, vector3d2.y * speed, vector3d2.z * speed);
                        this.setDeltaMovement(motion);
                        if (this.getOwner().getBoundingBox().inflate(1.0F).intersects(this.getBoundingBox())){
                            if (this.getOwner() instanceof Player player){
                                if (this.getSecondsCool() > 0){
                                    SEHelper.addSpecificCooldown(player, this.getItem(), MathHelper.secondsToTicks(this.getSecondsCool()));
                                }
                                if (!player.getInventory().add(this.getItem())) {
                                    player.drop(this.getItem(), false, true);
                                } else {
                                    if (!this.level.isClientSide){
                                        ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ITEM_PICKUP, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 1.4F + 2.0F));
                                    }
                                }
                            } else {
                                this.level.addFreshEntity(new ItemEntity(this.level, this.getX(), this.getY(), this.getZ(), this.getItem()));
                            }
                            this.discard();
                        }
                    }
                } else {
                    if (this.getOwner() instanceof Player player){
                        if (this.getSecondsCool() > 0){
                            SEHelper.addSpecificCooldown(player, this.getItem(), MathHelper.secondsToTicks(this.getSecondsCool()));
                        }
                        if (!player.getInventory().add(this.getItem())) {
                            player.drop(this.getItem(), false, true);
                        } else {
                            if (!this.level.isClientSide){
                                ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ITEM_PICKUP, 0.2F, (this.random.nextFloat() - this.random.nextFloat()) * 1.4F + 2.0F));
                            }
                        }
                    } else {
                        this.level.addFreshEntity(new ItemEntity(this.level, this.getX(), this.getY(), this.getZ(), this.getItem()));
                    }
                    this.discard();
                }
            }
        }

        if (this.isInWater()) {
            for(int i = 0; i < 4; ++i) {
                this.level.addParticle(ParticleTypes.BUBBLE, d0 - vec3.x * 0.25D, d1 - vec3.y * 0.25D, d2 - vec3.z * 0.25D, vec3.x, vec3.y, vec3.z);
            }
        } else {
            this.level.addParticle(this.getParticle(), d0 - vec3.x * 0.25D + this.random.nextDouble() * 0.6D - 0.3D, d1 - vec3.y * 0.25D, d2 - vec3.z * 0.25D + this.random.nextDouble() * 0.6D - 0.3D, vec3.x, vec3.y, vec3.z);
        }

        if (!this.level.isClientSide) {
            this.setPos(d0, d1, d2);
        } else {
            this.setPosRaw(d0, d1, d2);
        }

    }

public void aiStep() {
        super.aiStep();
        if (!this.level.isClientSide) {
            if (this.tickCount % 1000 == 0) {
                if (this.random.nextInt(40) == 0) {
                    this.spawnAtLocation(new ItemStack(ModItems.MATERIAL_SNAKE_SKIN.get()), 0.2F);
                }
            }
            if (this.level.getGameTime() % 4000 == 0) {
                this.heal(1.0F);
            }
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                int i = this.random.nextInt(3000);
                if (i <= 10 && !this.isInWater() && this.isNotMoving() && this.canMove()) {
                    this.getNavigation().stop();
                    this.setSitting(true);
                }
                if ((i == 11 || this.isInWater() || this.isActive()) && this.isSitting()) {
                    this.setSitting(false);
                }
            }
            if (this.isInWater()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0.0D, -0.006D, 0.0D));
            }
            this.setAngry(this.getTarget() != null);
        }

        if (!this.isNoAi() && !this.isBaby()) {
            if (this.canMove()) {
                if (this.ringBufferIndex < 0) {
                    for (int i = 0; i < this.ringBuffer.length; ++i) {
                        this.ringBuffer[i][0] = this.getYRot() ;
                        this.ringBuffer[i][1] = this.getY();
                    }
                }
                this.ringBufferIndex++;
                if (this.ringBufferIndex == this.ringBuffer.length) {
                    this.ringBufferIndex = 0;
                }
                this.ringBuffer[this.ringBufferIndex][0] = this.getYRot() ;
                this.ringBuffer[ringBufferIndex][1] = this.getY();
                Vector3d[] avector3d = new Vector3d[this.anacondaParts.length];

                for (int j = 0; j < this.anacondaParts.length; ++j) {
                    this.anacondaParts[j].collideWithNearbyEntities();
                    avector3d[j] = new Vector3d(this.anacondaParts[j].getX(), this.anacondaParts[j].getY(), this.anacondaParts[j].getZ());
                }
                float f15 = (float) (this.getMovementOffsets(5, 1.0F)[1] - this.getMovementOffsets(10, 1.0F)[1]) * 10.0F * ((float) Math.PI / 180F);
                float f16 = Mth.cos(f15);
                float yaw = this.getYRot()  * ((float) Math.PI / 180F);
                float pitch = this.getXRot() * ((float) Math.PI / 180F);
                float f3 = Mth.sin(yaw) * (1 - Math.abs(this.getXRot() / 90F));
                float f18 = Mth.cos(yaw) * (1 - Math.abs(this.getXRot() / 90F));

                double[] adouble = this.getMovementOffsets(5, 1.0F);

                for (int k = 0; k < getMultiparts(); ++k) {
                    EntityAnacondaPart anaconda_part = this.anacondaParts[k];

                    double[] adouble1 = this.getMovementOffsets(5 + k * 2, 1.0F);
                    float f7 = yaw + (float) Mth.wrapDegrees(adouble1[0] - adouble[0]) * ((float) Math.PI / 180F);
                    float f20 = Mth.sin(f7) * (1 - Math.abs(this.getXRot() / 90F));
                    float f21 = Mth.cos(f7) * (1 - Math.abs(this.getXRot() / 90F));
                    float f23 = k == 0 ? (float) (k + 1) : (k + 1) * -1;
                    float value = pitch * (k);
                    this.setPartPosition(anaconda_part, -(f3 * 0.5F + f20 * f23) * f16, value, (f18 * 0.5F + f21 * f23) * f16);

                    this.anacondaParts[k].xo = avector3d[k].x;
                    this.anacondaParts[k].yo = avector3d[k].y;
                    this.anacondaParts[k].zo = avector3d[k].z;
                    this.anacondaParts[k].xOld = avector3d[k].x;
                    this.anacondaParts[k].yOld = avector3d[k].y;
                    this.anacondaParts[k].zOld = avector3d[k].z;
                }
            }
            else {
                for (int k = 0; k < getMultiparts(); ++k) {
                    EntityAnacondaPart anaconda_part = this.anacondaParts[k];
                    this.setPartPosition(anaconda_part, 0, 0, 0);
                    this.anacondaParts[k].xo = this.getX();
                    this.anacondaParts[k].yo = this.getY();
                    this.anacondaParts[k].zo = this.getZ();
                    this.anacondaParts[k].xOld = this.getX();
                    this.anacondaParts[k].yOld = this.getY();
                    this.anacondaParts[k].zOld = this.getZ();
                }
            }
        }
    }

public static Widget createAutoCraftingButtonWidget(Rectangle displayBounds, Rectangle rectangle, Component text, Supplier<Display> displaySupplier, Supplier<Collection<Identifier>> idsSupplier, List<Widget> setupDisplay, DisplayCategory<?> category) {
        Button autoCraftingButton = Widgets.createButton(rectangle, text)
                .focusable(false)
                .onClick(button -> {
                    AutoCraftingEvaluator.evaluateAutoCrafting(true, Minecraft.getInstance().hasShiftDown(), displaySupplier.get(), idsSupplier);
                });
        return new DelegateWidget(autoCraftingButton) {
            final Supplier<AutoCraftingEvaluator.AutoCraftingResult> result = Suppliers.memoizeWithExpiration(
                    () -> AutoCraftingEvaluator.evaluateAutoCrafting(false, false, displaySupplier.get(), idsSupplier),
                    1000, TimeUnit.MILLISECONDS
            );

            @Override
            public void render(GuiGraphics graphics, int mouseX, int mouseY, float delta) {
                AutoCraftingEvaluator.AutoCraftingResult result = this.result.get();

                autoCraftingButton.setEnabled(result.successful);
                autoCraftingButton.setTint(result.tint);

                if (result.hasApplicable) {
                    autoCraftingButton.setText(text);
                } else {
                    autoCraftingButton.setText(Component.literal("!"));
                }

                if (result.hasApplicable && (containsMouse(mouseX, mouseY) || autoCraftingButton.isFocused()) && result.renderer != null) {
                    result.renderer.render(graphics, mouseX, mouseY, delta, setupDisplay, displayBounds, displaySupplier.get());
                }

                this.widget.render(graphics, mouseX, mouseY, delta);

                if (!autoCraftingButton.isFocused() && containsMouse(mouseX, mouseY)) {
                    tryTooltip(result, new Point(mouseX, mouseY));
                } else if (autoCraftingButton.isFocused()) {
                    Rectangle bounds = autoCraftingButton.getBounds();
                    tryTooltip(result, new Point(bounds.x + bounds.width / 2, bounds.y + bounds.height / 2));
                }
            }

            private void tryTooltip(AutoCraftingEvaluator.AutoCraftingResult result, Point point) {
                if (result.tooltipRenderer != null) {
                    result.tooltipRenderer.accept(point, Tooltip::queue);
                }
            }

            @Override
            public boolean keyPressed(KeyEvent event) {
                if (displaySupplier.get().getDisplayLocation().isPresent() && ConfigObject.getInstance().getCopyRecipeIdentifierKeybind().matchesKey(event.key(), event.scancode()) && containsMouse(PointHelper.ofMouse())) {
                    minecraft.keyboardHandler.setClipboard(displaySupplier.get().getDisplayLocation().get().toString());
