private void updateTarget(boolean forceFullUpdate) {
        if (isClientSide()) {
            return; // Part is not part of level yet or its client-side
        }

        MEStorage foundMonitor = null;
        Map<AEKeyType, MEStorage> foundExternalApi = Collections.emptyMap();

        // If the target position is not ticking, don't search for a target.
        if (Platform.areBlockEntitiesTicking(getLevel(), getBlockEntity().getBlockPos().relative(getSide()))) {
            // In any case we don't need any further update
            this.updateStatus = PendingUpdateStatus.NO_UPDATE;

            // Prioritize a handler to directly link to another ME network
            foundMonitor = adjacentStorageAccessor.find();

            if (foundMonitor == null) {
                // Query all available external APIs
                // TODO: If a filter is configured, we might want to only query external APIs for compatible key spaces
                foundExternalApi = new IdentityHashMap<>(2);
                findExternalStorages(foundExternalApi);
            }
        } else {
            // Try again in the future...
            this.updateStatus = PendingUpdateStatus.SLOW_UPDATE;
        }

        if (!forceFullUpdate && this.handler.getDelegate() instanceof CompositeStorage compositeStorage
                && !foundExternalApi.isEmpty()) {
            // Just update the inventory reference, the ticking monitor will take care of the rest.
            compositeStorage.setStorages(foundExternalApi);
            handlerDescription = compositeStorage.getDescription();
            return;
        } else if (!forceFullUpdate && foundMonitor == this.handler.getDelegate()) {
            // Monitor didn't change, nothing to do!
            return;
        }

        var wasSleeping = this.monitor == null;
        var wasRegistered = this.hasRegisteredCellToNetwork();

        // Update inventory
        MEStorage newInventory;
        if (foundMonitor != null) {
            newInventory = foundMonitor;
            this.checkStorageBusOnInterface();
            handlerDescription = newInventory.getDescription();
        } else if (!foundExternalApi.isEmpty()) {
            newInventory = new CompositeStorage(foundExternalApi);
            handlerDescription = newInventory.getDescription();
        } else {
            newInventory = NullInventory.of();
            handlerDescription = null;
        }
        this.handler.setDelegate(newInventory);

        // Apply other settings.
        this.handler.setAccessRestriction(this.getConfigManager().getSetting(Settings.ACCESS));
        this.handler.setWhitelist(isUpgradedWith(AEItems.INVERTER_CARD) ? IncludeExclude.BLACKLIST
                : IncludeExclude.WHITELIST);

        this.handler.setPartitionList(createFilter());
        this.handler.setVoidOverflow(this.isUpgradedWith(AEItems.VOID_CARD));

        // Ensure we apply the partition list to the available items.
        boolean filterOnExtract = this.getConfigManager().getSetting(Settings.FILTER_ON_EXTRACT) == YesNo.YES;
        this.handler.setExtractFiltering(filterOnExtract, isExtractableOnly() && filterOnExtract);

        // Let the new inventory react to us ticking.
        if (newInventory instanceof ITickingMonitor tickingMonitor) {
            this.monitor = tickingMonitor;
        } else {
            this.monitor = null;
        }

        // Update sleeping state.
        if (wasSleeping != (this.monitor == null)) {
            getMainNode().ifPresent((grid, node) -> {
                var tm = grid.getTickManager();
                if (this.monitor == null) {
                    tm.sleepDevice(node);
                } else {
                    tm.wakeDevice(node);
                }
            });
        }

        if (wasRegistered != this.hasRegisteredCellToNetwork()) {
            remountStorage();
        }
    }

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final State state = ctx.getState();
		float piston = 0;
		float[] shift = new float[state.processor.getQueueSize()];

		Level level = ctx.getLevel().getRawLevel();
		for(int i = 0; i < shift.length; i++)
		{
			MultiblockProcess<MetalPressRecipe, ?> process = state.processor.getQueue().get(i);
			float processMaxTicks = process.getMaxTicks(level);
			float transportTime = getTransportTime(processMaxTicks);
			float pressTime = getPressTime(processMaxTicks);
			//+partialTicks
			float fProcess = process.processTick;

			if(fProcess < transportTime)
				shift[i] = .5f*fProcess/transportTime;
			else if(fProcess < (processMaxTicks-transportTime))
				shift[i] = .5f;
			else
				shift[i] = .5f+.5f*(fProcess-(processMaxTicks-transportTime))/transportTime;
			if(!state.mold.isEmpty())
				if(fProcess >= transportTime&&fProcess < (processMaxTicks-transportTime))
				{
					if(fProcess < (transportTime+pressTime))
						piston = (fProcess-transportTime)/pressTime;
					else if(fProcess < (processMaxTicks-transportTime-pressTime))
						piston = 1;
					else
						piston = 1-(fProcess-(processMaxTicks-transportTime-pressTime))/pressTime;
				}
		}

		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);
		MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		Direction effectiveFacing = orientation.mirrored()?orientation.front().getOpposite(): orientation.front();
		rotateForFacingNoCentering(matrixStack, effectiveFacing);
		matrixStack.pushPose();
		matrixStack.translate(0, -piston*.6875f, 0);
		matrixStack.pushPose();
		matrixStack.translate(-0.5, -0.5, -0.5);
		final BlockRenderDispatcher blockRenderer = Minecraft.getInstance().getBlockRenderer();
		BakedModel pistonModel = PISTON.get();
		blockRenderer.getModelRenderer().renderModel(
				matrixStack.last(), bufferIn.getBuffer(RenderType.solid()), null, pistonModel,
				1, 1, 1,
				combinedLightIn, combinedOverlayIn, ModelData.EMPTY, RenderType.solid()
		);
		matrixStack.popPose();

		if(!state.mold.isEmpty())
		{
			matrixStack.translate(0, .34, 0);
			matrixStack.mulPose(new Quaternionf().rotateX(-Mth.HALF_PI));
			float scale = .75f;
			matrixStack.scale(scale, scale, 1);
			ClientUtils.mc().getItemRenderer().renderStatic(
					state.mold, ItemDisplayContext.FIXED,
					combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
					level, 0
			);
		}
		matrixStack.popPose();
		matrixStack.translate(-1.25, -.35, 0);
		for(int i = 0; i < shift.length; i++)
		{
			MultiblockProcess<?, ?> process = state.processor.getQueue().get(i);
			if(!(process instanceof MultiblockProcessInWorld<?> inWorld))
				continue;
			List<ItemStack> displays = inWorld.getDisplayItem(level);
			if(displays.isEmpty())
				continue;
			matrixStack.pushPose();
			matrixStack.translate(TRANSLATION_DISTANCE*shift[i], 0, 0);
			if(piston > .92)
				matrixStack.translate(0, .92-piston, 0);

			matrixStack.mulPose(new Quaternionf().rotateX(-Mth.HALF_PI));
			float scale = .625f;
			matrixStack.scale(scale, scale, 1);
			ClientUtils.mc().getItemRenderer().renderStatic(
					displays.get(0), ItemDisplayContext.FIXED,
					combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
					level, 0);
			matrixStack.popPose();
		}
		matrixStack.popPose();
	}

@Override
    public void tick() {
        if (level == null) return;
        if (level.isClientSide) {

            int baseAge = draining ? 20 : 40;
            int randBound = draining ? 3 : 6;
            int numParticles = draining ? 2 : 1;
            float scaleAge = draining ? (float) ParticleUtil.inRange(0.1, 0.2) : (float) ParticleUtil.inRange(0.05, 0.15);
            if (level.random.nextInt(randBound) == 0 && !Minecraft.getInstance().isPaused()) {
                for (int i = 0; i < numParticles; i++) {
                    Vec3 particlePos = new Vec3(getX(), getY(), getZ()).add(0.5, 0.5, 0.5);
                    particlePos = particlePos.add(ParticleUtil.pointInSphere());
                    level.addParticle(ParticleLineData.createData(new ParticleColor(255, 25, 180), scaleAge, baseAge + level.random.nextInt(20)),
                            particlePos.x(), particlePos.y(), particlePos.z(),
                            getX() + 0.5, getY() + 0.5, getZ() + 0.5);
                }
            }
            if (!stack.isEmpty() && recipe == null) {
                var holder = getRecipeNow();
                this.recipe = holder != null ? holder.value() : null;
            }
            return;
        }
        this.hasRecipe = recipe != null;
        if (backoff > 0) {
            backoff--;
            return;
        }
        if (stack.isEmpty()) {
            return;
        }
        if (craftTicks > 0)
            craftTicks--;

        // Restore the recipe on world restart
        if (recipe == null) {
            var foundRecipe = getRecipeNow();
            if (foundRecipe != null) {
                this.recipe = foundRecipe.value();
                this.craftTicks = 100;
            }
        }

        if (recipe == null || !recipe.matches(this, level)) {
            backoff = 20;
            recipe = null;
            if (this.draining) {
                this.draining = false;
                updateBlock();
            }
            return;
        }

        int transferRate = 200;

        int cost = recipe.getSourceCost(this);

        if (level instanceof ServerLevel serverLevel && this.level.getGameTime() % 20 == 0 && this.getSource() < cost) {
            if (!canAcceptSource(Math.min(200, cost)))
                return;

            List<ISpecialSourceProvider> takePos = SourceUtil.takeSourceMultiple(worldPosition, level, 2, Math.min(200, cost));
            if (takePos != null) {
                this.addSource(transferRate);
                for (ISpecialSourceProvider provider : takePos) {
                    EntityFlyingItem.spawn(worldPosition, serverLevel, provider.getCurrentPos().above(), worldPosition)
                            .withNoTouch().setDistanceAdjust(2f);
                }

                if (!draining) {
                    draining = true;
                    updateBlock();
                }
            } else {
                this.addSource(10);
                if (draining) {
                    draining = false;
                    updateBlock();
                }
            }

        }

        if (this.getSource() >= cost && craftTicks <= 0) {
            this.setItem(0, recipe.assemble(this, this.level.registryAccess()).copy());
            this.addSource(-cost);
            ParticleUtil.spawnTouchPacket(level, worldPosition, ParticleColor.defaultParticleColor());
            updateBlock();
        }
    }

@Override
    protected void doTick(@NotNull ServerLevel level, @NotNull E entity) {

        //if we currently have a crop, exit
        //Will be removed by the fell crop behaviour
        if (BrainUtil.hasMemory(entity, OccultismMemoryTypes.NEAREST_CROP.get()))
            return;

        //if work area is empty, exit. This memory expires on its own to allow rescan
        if (BrainUtil.hasMemory(entity, OccultismMemoryTypes.NO_CROP_IN_WORK_AREA.get()))
            return;

        var nonCrop = BrainUtil.memoryOrDefault(entity, OccultismMemoryTypes.NON_CROP.get(), HashSet::new);
        var unreachableCrops = BrainUtil.memoryOrDefault(entity, OccultismMemoryTypes.UNREACHABLE_CROPS.get(), HashSet::new);
        var workAreaCenter = BrainUtil.getMemory(entity, OccultismMemoryTypes.WORK_AREA_CENTER.get());
        var workAreaSize = BrainUtil.getMemory(entity, OccultismMemoryTypes.WORK_AREA_SIZE.get());

        if (Occultism.DEBUG.debugAI) {
            for (var crop : unreachableCrops) {
                Networking.sendToTracking(entity, new MessageSelectBlock(crop, 10000, Color.ORANGE));
            }
            for (var crop : nonCrop) {
                Networking.sendToTracking(entity, new MessageSelectBlock(crop, 10000, Color.ORANGE));
            }
        }

        //get blocks in work area. We do /2 because we offset from the center
        var blocksInWorkArea = workAreaCenter != null && workAreaSize != null ? BlockPos.betweenClosedStream(
                workAreaCenter.offset(-workAreaSize / 2, -workAreaSize / 2, -workAreaSize / 2),
                workAreaCenter.offset(workAreaSize / 2, workAreaSize / 2, workAreaSize / 2)
        ).map(BlockPos::immutable) : BlockPos.betweenClosedStream(-1, -1, -1, 1, 1, 1);

        //filter potential Roots
        List<BlockPos> potentialRoots = blocksInWorkArea
                .filter(pos -> isGrowthCrop(level, pos)
                        && isCropSoil(level, pos.below())
                        && !nonCrop.contains(pos)
                        && !unreachableCrops.contains(pos)
                )
                .collect(Collectors.toList());

        //TODO: refactor to search in increasing radius's? (manhattan distance helper might help, or "closest match"

        var foundCrop = false;
        if (!potentialRoots.isEmpty()) {
            potentialRoots.sort(new BlockSorter(entity));

            for (var potentialRoot : potentialRoots) {

                if (Occultism.DEBUG.debugAI) {
                    Networking.sendToTracking(entity, new MessageSelectBlock(potentialRoot, 5000, Color.WHITE));
                }

                //we only check if the Root is actually a crop one by one from closest to furthest to save perf.
                if (isGrowthCrop(level, potentialRoot)) {
                    //we have a crop, now we check if it is likely reachable
                    var isReachable = false;
                    for (Direction facing : Plane.HORIZONTAL) {
                        BlockPos pos = potentialRoot.relative(facing);
                        if (level.getBlockState(pos).getCollisionShape(level, pos).isEmpty()) {
                            isReachable = true;
                            break;
                        }
                    }

                    if (isReachable) {
                        if (Occultism.DEBUG.debugAI) {
                            Networking.sendToTracking(entity, new MessageSelectBlock(potentialRoot, 50000, 0x800080));
                        }

                        BrainUtil.setMemory(entity, OccultismMemoryTypes.NEAREST_CROP.get(), potentialRoot);
                        foundCrop = true;
                        break;
                    }
                } else {
                    //we have a Root, but it is not a crop, add it to the list of ignored Roots
                    nonCrop.add(potentialRoot);
                    BrainUtil.setMemory(entity, OccultismMemoryTypes.NON_CROP.get(), nonCrop);

                    if (Occultism.DEBUG.debugAI) {
                        Networking.sendToTracking(entity, new MessageSelectBlock(potentialRoot, 10000, 0xffff00));
                    }
                }
            }
        }

        if (!foundCrop) {
            BrainUtil.clearMemory(entity, OccultismMemoryTypes.NEAREST_CROP.get());
            BrainUtil.setForgettableMemory(entity, OccultismMemoryTypes.NO_CROP_IN_WORK_AREA.get(), true, RESCAN_EMPTY_WORK_AREA_AFTER_TICKS);
        }
    }

@Override
    protected void doTick(@NotNull ServerLevel level, @NotNull E entity) {

        //if we currently have a tree, exit
        //Will be removed by the fell tree behaviour
        if (BrainUtil.hasMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get()))
            return;

        //if work area is empty, exit. This memory expires on its own to allow rescan
        if (BrainUtil.hasMemory(entity, OccultismMemoryTypes.NO_TREE_IN_WORK_AREA.get()))
            return;

        var nonTreeLogs = BrainUtil.memoryOrDefault(entity, OccultismMemoryTypes.NON_TREE_LOGS.get(), HashSet::new);
        var unreachableTrees = BrainUtil.memoryOrDefault(entity, OccultismMemoryTypes.UNREACHABLE_TREES.get(), HashSet::new);
        var workAreaCenter = BrainUtil.getMemory(entity, OccultismMemoryTypes.WORK_AREA_CENTER.get());
        var workAreaSize = BrainUtil.getMemory(entity, OccultismMemoryTypes.WORK_AREA_SIZE.get());

        if (Occultism.DEBUG.debugAI) {
            for (var tree : unreachableTrees) {
                Networking.sendToTracking(entity, new MessageSelectBlock(tree, 10000, Color.ORANGE));
            }
            for (var tree : nonTreeLogs) {
                Networking.sendToTracking(entity, new MessageSelectBlock(tree, 10000, Color.ORANGE));
            }
        }

        //get blocks in work area. We do /2 because we offset from the center
        var blocksInWorkArea = BlockPos.betweenClosedStream(
                workAreaCenter.offset(-workAreaSize / 2, -workAreaSize / 2, -workAreaSize / 2),
                workAreaCenter.offset(workAreaSize / 2, workAreaSize / 2, workAreaSize / 2)
        ).map(BlockPos::immutable);

        //filter potential stumps
        List<BlockPos> potentialStumps = blocksInWorkArea
                .filter(pos -> isLog(level, pos)
                        && isTreeSoil(level, pos.below())
                        && !nonTreeLogs.contains(pos)
                        && !unreachableTrees.contains(pos)
                )
                .collect(Collectors.toList());

        //TODO: refactor to search in increaseing radiuses? (manhattan distance helper might help, or "closest match"

        var foundTree = false;
        if (!potentialStumps.isEmpty()) {
            potentialStumps.sort(new BlockSorter(entity));

            for (var potentialStump : potentialStumps) {

                if (Occultism.DEBUG.debugAI) {
                    Networking.sendToTracking(entity, new MessageSelectBlock(potentialStump, 5000, Color.WHITE));
                }

                //we only check if the stump is actually a tree one by one from closest to furthest to save perf.
                if (this.isTree(level, potentialStump)) {
                    //we have a tree, now we check if it is likely reachable
                    var isReachable = false;
                    for (Direction facing : Plane.HORIZONTAL) {
                        BlockPos pos = potentialStump.relative(facing);
                        if (level.isEmptyBlock(pos)) {
                            isReachable = true;
                            break;
                        }
                    }

                    if (isReachable) {
                        if (Occultism.DEBUG.debugAI) {
                            Networking.sendToTracking(entity, new MessageSelectBlock(potentialStump, 50000, 0x800080));
                        }

                        BrainUtil.setMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get(), potentialStump);
                        foundTree = true;
                        break;
                    }
                } else {
                    //we have a stump, but it is not a tree, add it to the list of ignored stumps
                    nonTreeLogs.add(potentialStump);
                    BrainUtil.setMemory(entity, OccultismMemoryTypes.NON_TREE_LOGS.get(), nonTreeLogs);

                    if (Occultism.DEBUG.debugAI) {
                        Networking.sendToTracking(entity, new MessageSelectBlock(potentialStump, 50000, 0xffff00));
                    }
                }
            }
        }

        if (!foundTree) {
            BrainUtil.clearMemory(entity, OccultismMemoryTypes.NEAREST_TREE.get());
            BrainUtil.setForgettableMemory(entity, OccultismMemoryTypes.NO_TREE_IN_WORK_AREA.get(), true, RESCAN_EMPTY_WORK_AREA_AFTER_TICKS);
        }
    }

public void writeVillageDataToNBT(CompoundTag compound) {
        compound.putInt("PopSize", this.numMyrmex);
        compound.putBoolean("Reproduces", this.reproduces);
        compound.putBoolean("HasOwner", this.hasOwner);
        if (this.ownerUUID != null) {
            compound.putUUID("OwnerUUID", this.ownerUUID);
        }
        compound.putString("ColonyName", this.colonyName);
        compound.putInt("Radius", this.villageRadius);
        compound.putInt("WanderRadius", this.wanderRadius);
        compound.putInt("Stable", this.lastAddDoorTimestamp);
        compound.putInt("Tick", this.tickCounter);
