private static void renderBar(PoseStack poseStack, Minecraft mc, int left, int top, float currentHealth, float maxHealth, boolean poisoned, boolean withered, boolean frozen, float absorption, boolean bleeding) {
		int uvY = 0;

		if (absorption > 0) {
			uvY = 48;
		}
		else if (frozen) {
			uvY = 96;
		}
		else if (withered) {
			uvY = 84;
		}
		else if (poisoned) {
			uvY = 72;
		}
		else if (bleeding) {
			uvY = 120;
		}
		else if (mc.player.hasEffect(MobEffects.HEALTH_BOOST)) {
			uvY = 60;
		}
		else if (mc.level.getLevelData().isHardcore()) {
			uvY = 108;
		}

		if (!NumberUtil.roundToNthDecimalPlace(lastTickHealth, 1).equals(NumberUtil.roundToNthDecimalPlace(currentHealth, 1))) {
			if (lastTickHealth < currentHealth) {
				if (lastHealthTime == 0) {
					lastTickHealth = currentHealth;
					lastHealthTime = mc.player.tickCount;

					return;
				}

				if (deltaHealth < 0)
					deltaHealth = 0;

				deltaHealth += currentHealth - lastTickHealth;
			}
			else {
				if (deltaHealth > 0)
					deltaHealth = 0;

				deltaHealth -= lastTickHealth - currentHealth;
			}

			lastHealthTime = mc.player.tickCount + 12;
		}

		if (deltaHealth != 0 && lastHealthTime + 20 < mc.player.tickCount)
			deltaHealth = 0;

		lastTickHealth = currentHealth;
		poseStack.pushPose();
		poseStack.translate(left, top - 1.9, 0);
		RenderUtil.prepRenderTexture(HEALTH_BAR);

		float healthWidth = 81 * (currentHealth / maxHealth);

		if (currentHealth < maxHealth)
			RenderUtil.renderCustomSizedTexture(poseStack, 0, 0, 0, 12, 81, 12, 81, 132);

		if (!mc.player.isAlive()) {
			poseStack.popPose();

			return;
		}

		RenderUtil.renderCustomSizedTexture(poseStack, 0, 0, 0, uvY, healthWidth, 12, 81, 132);

		if (deltaHealth != 0) {
			int deltaUvY = deltaHealth < 0 ? 24 : 36;
			float deltaWidth = mc.player.tickCount - lastHealthTime < 8 ? 1 : ((12 - (mc.player.tickCount - 8 - lastHealthTime)) / (float)12);
			float width = Math.min(Math.abs(deltaHealth), maxHealth) / maxHealth * 81 * deltaWidth;
			float x = deltaHealth < 0 ? healthWidth : healthWidth - width;

			if (deltaHealth < 0 && x + width > 81)
				width = 81 - x;

			RenderUtil.renderScaledCustomSizedTexture(poseStack, x, 0, x, deltaUvY, width, 12, width, 12, 81, 132);

			if (absorption <= 0) {
				Component deltaText = deltaHealth > 0 && deltaHealth < 100 ? Component.literal("+").append(NumberUtil.floorAndAppendSuffix(deltaHealth, true)) : Component.literal(NumberUtil.floorAndAppendSuffix(deltaHealth, true));
				int alpha = Math.max(10, (int)(deltaWidth * 255)) << 24;
				int colour = (deltaHealth > 0 ? 0x20B200 : 0xC81400) | alpha;

				RenderUtil.renderScaledText(poseStack, mc.font, deltaText, 2.5f, 3, 0.8f, colour, alpha, RenderUtil.TextRenderType.OUTLINED, LightTexture.FULL_BRIGHT, Minecraft.getInstance().renderBuffers().bufferSource());
			}
		}

		RenderUtil.drawRectangle(poseStack, 0, 0, 81, 11, 0x44000000);
		poseStack.popPose();
	}

private static void summon(Spell.Impact.Action.Summon def, List<Spell.Modifier> spellModifiers,
                               RegistryEntry<Spell> spellEntry, LivingEntity caster, ImpactContext context) {
        var world = caster.getWorld();
        if (!(world instanceof ServerWorld serverWorld)) return;

        // Fold in summon-targeting spell modifiers without mutating the shared Summon / SummonBehaviour
        // instances stored on the registered spell: counts and lifespan adds are accumulated into
        // locals, attribute scaling and behaviour are recomputed onto fresh copies only when needed.
        int spawnCount = def.spawn_count;
        int groupCount = def.group_count;
        int spawnTicksAdd = 0, activeSecondsAdd = 0, despawnTicksAdd = 0;
        var extraActions = new ArrayList<SummonBehaviour.Action.Entry>();
        var attributeScaling = def.attribute_scaling;
        for (var modifier : spellModifiers) {
            spawnCount += modifier.summon_spawn_count_add;
            groupCount += modifier.summon_group_count_add;
            var behaviourMod = modifier.summon_behaviour;
            if (behaviourMod != null) {
                extraActions.addAll(behaviourMod.actions_add);
                spawnTicksAdd += behaviourMod.lifespan.spawn_ticks_add;
                activeSecondsAdd += behaviourMod.lifespan.active_seconds_add;
                despawnTicksAdd += behaviourMod.lifespan.despawn_ticks_add;
            }
            if (modifier.summon_attribute_scaling != null) {
                attributeScaling = AttributeScaling.merged(attributeScaling, modifier.summon_attribute_scaling);
            }
        }
        spawnCount = Math.max(0, spawnCount);
        groupCount = Math.max(0, groupCount);
        var behaviour = (extraActions.isEmpty() && spawnTicksAdd == 0 && activeSecondsAdd == 0 && despawnTicksAdd == 0)
                ? def.behaviour
                : def.behaviour.withModifiers(extraActions, spawnTicksAdd, activeSecondsAdd, despawnTicksAdd);

        var type = Registries.ENTITY_TYPE.get(Identifier.of(def.entity_type_id));
        for (int g = 0; g < groupCount; g++) {
            // Next group slot, wrapping around the list (null when no group offset is configured).
            var groupPlacement = def.group_placements.isEmpty() ? null : def.group_placements.get(g % def.group_placements.size());
            int groupDelay = groupPlacement != null ? groupPlacement.delay_ticks : 0;
            Vec3d groupAnchor = null; // caster position + group offset; captured from the first entity

            for (int i = 0; i < spawnCount; i++) {
                var created = (Entity) type.create(world);
                if (!(created instanceof SpellSummoned summoned)) return;

                // Next per-entity slot, wrapping around the list (null when no slots are configured).
                var placement = def.placements.isEmpty() ? null : def.placements.get(i % def.placements.size());

                summoned.onSummonedBySpell(new SpellSummoned.Args(caster, spellEntry, behaviour, attributeScaling, context));

                // Compose placements: the group offset's resulting position seeds the per-entity
                // placement (both rotate the look-offset by the caster's yaw, so the formation keeps
                // a consistent caster-relative orientation across groups).
                var origin = caster.getPos();
                if (groupPlacement != null) {
                    EntityPlacements.applyEntityPlacement(created, caster, origin, groupPlacement);
                    origin = created.getPos();
                }
                if (i == 0) groupAnchor = origin; // the group's anchor (pre per-entity offset)
                EntityPlacements.applyEntityPlacement(created, caster, origin, placement);

                // applyEntityPlacement only sets entity yaw; sync head/body yaw so the initial pose matches.
                boolean appliedYaw = (groupPlacement != null && groupPlacement.apply_yaw)
                        || (placement != null && placement.apply_yaw);
                if (appliedYaw && created instanceof LivingEntity living) {
                    living.setHeadYaw(living.getYaw());
                    living.setBodyYaw(living.getYaw());
                }
                // Anti-clip: when a contributing placement opts into `line_of_sight`, pull a placed
                // position that is out of the caster's line of sight back to the nearest visible point.
                boolean checkLineOfSight = (placement != null && placement.line_of_sight)
                        || (groupPlacement != null && groupPlacement.line_of_sight);
                if (checkLineOfSight) {
                    var visible = nearestVisiblePosition(caster, created.getPos(), serverWorld);
                    created.setPosition(visible.x, visible.y, visible.z);
                }

                // Defer the world spawn by the combined group + per-entity delay (0 = spawn this tick).
                int entityDelay = placement != null ? placement.delay_ticks : 0;
                ((WorldScheduler) serverWorld).schedule(groupDelay + entityDelay, () -> serverWorld.spawnEntity(created));
            }

            // Group spawn FX + sound: one-shot at the group anchor, deferred by the group delay.
            if (groupAnchor != null && (def.group_spawn_fx != null || def.group_spawn_sound != null)) {
                var anchor = groupAnchor;
                var fx = def.group_spawn_fx;
                var sound = def.group_spawn_sound;
                ((WorldScheduler) serverWorld).schedule(groupDelay, () -> {
                    if (fx != null) emitSummonGroupFx(serverWorld, caster, anchor, fx);
                    if (sound != null) playSummonSound(serverWorld, anchor, sound);
                });
            }
        }
    }

@Override
    public void update() {
        ItemStack handHeld = this.entity.getItemInHand(InteractionHand.MAIN_HAND);
        var recipeInput = new TieredSingleRecipeInput(handHeld, this.tier.get());
        Level level = this.entity.level();

        if (!this.currentRecipe.isPresent() && !handHeld.isEmpty()) {
            this.currentRecipe = ((ServerLevel) level).recipeAccess().getRecipeFor(OccultismRecipes.CRUSHING_TYPE.get(),
                    recipeInput, level);
            this.crushingTimer = 0;

            if (this.currentRecipe.isPresent()) {
                //play crushing sound
                level
                        .playSound(null, this.entity.blockPosition(), OccultismSounds.CRUNCHING.get(), SoundSource.NEUTRAL, 1f,
                                1 + 0.5f * this.entity.getRandom().nextFloat());
            } else {
                //if no recipe is found, drop hand held item as we can't process it
                this.entity.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, handHeld);
                if (droppedItem != null) {
                    droppedItem.addTag(DROPPED_BY_CRUSHER);
                }
            }
        }
        if (this.currentRecipe.isPresent()) {
            if (handHeld.isEmpty() || !this.currentRecipe.get().value().matches(recipeInput, level)) {
                //Reset cached recipe if it no longer matches
                this.currentRecipe = Optional.empty();
            } else {
                //advance conversion
                this.crushingTimer++;

                //show particle effect while crushing
                if (level.getGameTime() % 10 == 0) {
                    Vec3 pos = this.entity.position();
                    ((ServerLevel) level)
                            .sendParticles(ParticleTypes.CRIT, pos.x + level.getRandom().nextGaussian() / 3,
                                    pos.y + 0.5, pos.z + level.getRandom().nextGaussian() / 3, 1, 0.0, 0.0, 0.0,
                                    0.0);
                }

                //every two seconds, play another crushing sound
                if (level.getGameTime() % 40 == 0) {
                    level.playSound(null, this.entity.blockPosition(), OccultismSounds.CRUNCHING.get(),
                            SoundSource.NEUTRAL, 1f,
                            1 + 0.5f * this.entity.getRandom().nextFloat());
                }

                if (this.crushingTimer >= this.currentRecipe.get().value().getCrushingTime() * this.crushingTimeMultiplier.get()) {
                    this.crushingTimer = 0;

                    ItemStack result = this.currentRecipe.get().value().assemble(recipeInput);
                    //make sure to ignore output multiplier on recipes that set that flag.
                    //prevents e.g. 1x ingot -> 3x dust -> 3x ingot -> 9x dust ...
                    float outputMultiplier = this.outputMultiplier.get();
                    if (this.currentRecipe.get().value().getIgnoreCrushingMultiplier())
                        outputMultiplier = 1;
                    int a = Math.min(this.operationCount.get(), handHeld.getCount());
                    result.setCount((int) (result.getCount() * a * outputMultiplier));
                    ItemStack inputCopy = handHeld.copy();
                    inputCopy.setCount(a);
                    handHeld.shrink(a);

                    this.entity.setItemInHand(InteractionHand.MAIN_HAND, handHeld);

                    this.onCrush(inputCopy, result);
                    var event = new CrusherJobEvent(this.entity, inputCopy, result);
                    NeoForge.EVENT_BUS.post(event);
                    if (!event.getResult().isEmpty()) {
                        boolean flag = true;
                        if (level.getBlockState(this.entity.blockPosition().below()).is(OccultismBlocks.DIMENSIONAL_EXTRACTOR)) {
                            if (this.cachedStateBelow != level.getBlockState(this.entity.blockPosition().below(2)))
                                this.updateBelowBlock();
                            if (this.handlerBelow != null) {
                                ItemTransferUtil.insertItemStacked(this.handlerBelow, event.getResult(), false);
                                flag = false;
                            }

                        }
                        if (flag) {
                            ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, event.getResult());
                            if (droppedItem != null) {
                                droppedItem.addTag(DROPPED_BY_CRUSHER);
                            }
                        }
                    }
                    //Don't reset recipe here, keep it cached
                }
            }
        }
        super.update();
    }

private static void addToExistingTabs(BuildCreativeModeTabContentsEvent event) {
        ResourceKey<CreativeModeTab> tabKey = event.getTabKey();
        if (tabKey == CreativeModeTabs.BUILDING_BLOCKS) {
            CreativeTabDeferredRegister.addToDisplay(event, MekanismBlocks.SALT_BLOCK, MekanismBlocks.BRONZE_BLOCK, MekanismBlocks.STEEL_BLOCK,
                  MekanismBlocks.CHARCOAL_BLOCK, MekanismBlocks.REFINED_OBSIDIAN_BLOCK, MekanismBlocks.REFINED_GLOWSTONE_BLOCK);
            for (PrimaryResource resource : PrimaryResource.VALUES) {
                BlockResourceInfo resourceInfo = resource.getResourceBlockInfo();
                if (resourceInfo != null) {
                    CreativeTabDeferredRegister.addToDisplay(event, MekanismBlocks.PROCESSED_RESOURCE_BLOCKS.get(resourceInfo));
                }
            }
        } else if (tabKey == CreativeModeTabs.NATURAL_BLOCKS) {
            CreativeTabDeferredRegister.addToDisplay(event, MekanismBlocks.SALT_BLOCK);
            for (OreBlockType oreType : MekanismBlocks.ORES.values()) {
                CreativeTabDeferredRegister.addToDisplay(event, oreType.stone(), oreType.deepslate());
