private void placeTorchIfNecessary(ItemStack stack, Level world, Player player) {
    BlockPos playerPos = player.blockPosition();
    if (world.getBlockState(playerPos).canOcclude()) {
      return;
    }
    // Find the surface below the player's feet.
    for (int i = 0; i < BLOCKS_TO_MOVE_FEET_DOWN; i++) {
      BlockPos next = playerPos.below();
      if (world.getBlockState(next).canOcclude()) {
        break;
      }
      else {
        playerPos = next;
      }
    }
    if (!world.getBlockState(playerPos.below()).canOcclude()) {
      return;
    }
    final int lightLimit = getLightLimit();
    final int playerPosLight = world.getMaxLocalRawBrightness(playerPos);
    world.getBrightness(LightLayer.BLOCK, playerPos);
    if (playerPosLight > lightLimit) {
      return;
    }
    // Increase the light target the darker the current light level is, compared to the light limit.
    // For example, if the player was moving very quickly away from a light source, it's possible that
    // `playerPosLight == lightLimit-1`, i.e. they moved over the block which would have `playerPosLight == lightLimit`.
    // To light up the "skipped" block to `lightTarget`, we need to light this block up to `lightTarget+1`.
    // Note that lightTarget, as a result, can exceed TORCH_LIGHT_LEVEL. This is dealt with below (by falling back to
    // maximising the current position's light value if lightTarget is unreachable).
    final int lightTarget = getLightTarget() + lightLimit - playerPosLight;
    // Do an initial BFS to try hitting lightTarget.
    final int targetDistance = TORCH_LIGHT_LEVEL - lightTarget;
    // The worst case is that we need to BFS to try hitting lightLimit + 1, so never push those onto the BFS.
    final int fallbackTargetDistance = TORCH_LIGHT_LEVEL - (lightLimit + 1);
    assert targetDistance <= fallbackTargetDistance;
    Queue<BlockPos> queue = new ArrayDeque<>();
    HashMap<BlockPos, Integer> distances = new HashMap<>();
    queue.add(playerPos);
    distances.put(playerPos, 0);
    final int playerElevation = playerPos.getY();
    ArrayList<TorchPos> validTorchPositions = bfs(world, queue, distances, targetDistance, fallbackTargetDistance, playerElevation);
    final boolean preferWalls = isPreferWalls();
    validTorchPositions.sort(
        // If preferWalls is enabled, always prefer torches that are not on the ground and are at feet level or above.
        // This is to prevent torches from being placed on the edge of platforms / cliffs.
        Comparator.<TorchPos, Boolean> comparing(torchPos -> preferWalls && torchPos.isNotOnGround() && torchPos.isNotBelowFeet())
            // Prefer torch positions which are currently darker.
            // This needs to be before the below. If the two were swapped, torches would be placed CLOSER to existing
            // light sources when digging a tunnel!
            // Additionally, prefer torches which are closer in elevation to the current position.
            // This is a naive heuristic to prevent torches from being placed too high from the ground, therefore
            // lighting up less of the ground.
            // The two heuristics are combined, with the elevation being weighted double (or quadruple if it's beneath
            // the player). Separating the two heuristics either results in torches being redundantly placed too high
            // up, or torches being placed in brighter areas just because they have a lower elevation. Using a weighted
            // mix fixes both of these problems.
            .thenComparing(torchPos -> -(torchPos.currentLightLevel + (torchPos.isNotBelowFeet() ? 2 : 4) * Math.abs(torchPos.relativeHeight)))
            // Prefer torches with a LOWER player light level as a heuristic to light up a bigger area.
            // In other words, torches which are further away from the player.
            .thenComparing(torchPos -> -torchPos.playerLightLevel)
            // Prefer torches which are on walls instead of on the ground.
            .thenComparing(TorchPos::isNotOnGround)
            // Reverse the comparator to get validTorchPositions from best to worst, instead of worst to best.
            .reversed());
    final Direction facing = player.getDirection();
    for (TorchPos torchPos : validTorchPositions) {
      if (BlockUtil.placeTorchSafely(world, torchPos.pos, torchPos.getPlacementDirection(facing))) {
        ItemStackUtil.damageItem(player, stack);
        timer.set(TICK_DELAY);
        return;
      }
    }
    // Couldn't find a valid position. Fall back on ANY torch which could increase the player light level above
    // lightLimit + 1.
    validTorchPositions = bfs(world, queue, distances, fallbackTargetDistance, fallbackTargetDistance, playerElevation);
    validTorchPositions.sort(
        // Prefer torches with the HIGHEST player light level, as we should compensate for not being able light up this
        // block to the expected light value.
        Comparator.<TorchPos, Integer> comparing(torchPos -> torchPos.playerLightLevel)
            // Same as above.
            .thenComparing(torchPos -> preferWalls && torchPos.isNotOnGround() && torchPos.isNotBelowFeet())
            .thenComparing(torchPos -> -(torchPos.currentLightLevel + (torchPos.isNotBelowFeet() ? 2 : 4) * Math.abs(torchPos.relativeHeight)))
            .thenComparing(TorchPos::isNotOnGround)
            .reversed());
    for (TorchPos torchPos : validTorchPositions) {
      if (BlockUtil.placeTorchSafely(world, torchPos.pos, torchPos.getPlacementDirection(facing))) {
        ItemStackUtil.damageItem(player, stack);
        timer.set(TICK_DELAY);
        return;
      }
    }
    // Didn't find a match. We'll probably get the same result next time, so delay the next placement attempt.
    timer.set(TICK_DELAY);
  }

public void tick() {
		//convert old pipes
		if(convert) {
			convert = false;
			refreshVisualConnections();
		}
		boolean enabled = isPipeEnabled();
		if(!enabled && level.getGameTime() % 10 == 0 && level instanceof ServerLevel serverLevel)
			serverLevel.sendParticles(new DustParticleOptions(new Vector3f(1.0F, 0.0F, 0.0F), 1.0F), worldPosition.getX() + 0.5, worldPosition.getY() + 0.5, worldPosition.getZ() + 0.5, 3, 0.2, 0.2, 0.2, 0);

		BlockState blockAt = level.getBlockState(worldPosition);
		if(!level.isClientSide && enabled && blockAt.is(PipesModule.pipesTag)) {
			for(Direction side : Direction.values()) {
				if(connectionsCache[side.ordinal()] == ConnectionType.OPENING) {
					double minX = worldPosition.getX() + 0.25 + 0.5 * Math.min(0, side.getStepX());
					double minY = worldPosition.getY() + 0.25 + 0.5 * Math.min(0, side.getStepY());
					double minZ = worldPosition.getZ() + 0.25 + 0.5 * Math.min(0, side.getStepZ());
					double maxX = worldPosition.getX() + 0.75 + 0.5 * Math.max(0, side.getStepX());
					double maxY = worldPosition.getY() + 0.75 + 0.5 * Math.max(0, side.getStepY());
					double maxZ = worldPosition.getZ() + 0.75 + 0.5 * Math.max(0, side.getStepZ());

					Direction opposite = side.getOpposite();

					boolean pickedItemsUp = false;
					Predicate<ItemEntity> predicate = entity -> {
						if(entity == null || !entity.isAlive())
							return false;

						Vec3 motion = entity.getDeltaMovement();
						Direction dir = Direction.getNearest(motion.x, motion.y, motion.z);

						return dir == opposite;
					};

					for(ItemEntity item : level.getEntitiesOfClass(ItemEntity.class, new AABB(minX, minY, minZ, maxX, maxY, maxZ), predicate)) {
						passIn(item.getItem().copy(), side);

						if(PipesModule.doPipesWhoosh) {
							if(isTheGoodDay())
								level.playSound(null, item.getX(), item.getY(), item.getZ(), QuarkSounds.BLOCK_PIPE_PICKUP_LENNY, SoundSource.BLOCKS, 1f, 1f);
							else
								level.playSound(null, item.getX(), item.getY(), item.getZ(), QuarkSounds.BLOCK_PIPE_PICKUP, SoundSource.BLOCKS, 1f, 1f);
						}

						if(PipesModule.emitVibrations)
							getLevel().gameEvent(GameEvent.PROJECTILE_LAND, getBlockPos(), Context.of(getBlockState()));

						pickedItemsUp = true;
						item.discard();
					}

					if(pickedItemsUp)
						sync();
				}
			}
		}

		int currentOut = getComparatorOutput();

		if(!pipeItems.isEmpty()) {
			if(PipesModule.maxPipeItems > 0 && pipeItems.size() > PipesModule.maxPipeItems && !level.isClientSide) {
				level.levelEvent(LevelEvent.PARTICLES_DESTROY_BLOCK, worldPosition, Block.getId(level.getBlockState(worldPosition)));
				dropItem(new ItemStack(getBlockState().getBlock()));
				level.removeBlock(getBlockPos(), false);
			}

			ListIterator<PipeItem> itemItr = pipeItems.listIterator();
			iterating = true;
			while(itemItr.hasNext()) {
				PipeItem item = itemItr.next();
				Direction lastFacing = item.outgoingFace;
				if(item.tick(this)) {
					itemItr.remove();

					if(item.valid)
						passOut(item);
					else if(!level.isClientSide) {
						dropItem(item.stack, lastFacing, true);
					}
				}
			}
			iterating = false;

			if(!queuedItems.isEmpty()) {
				pipeItems.addAll(queuedItems);
				queuedItems.clear();
                sync();
            }
		}



		if(getComparatorOutput() != currentOut)
			level.updateNeighbourForOutputSignal(getBlockPos(), getBlockState().getBlock());
	}

@Override
    public void update() {
        ItemStack handHeld = this.entity.getItemInHand(InteractionHand.MAIN_HAND);
        var recipeInput = new TraderRecipeInput(handHeld, this.getFactoryID().toString());
        Level level = this.entity.level();
        if (this.currentRecipe.isEmpty() && !handHeld.isEmpty()) {
            this.currentRecipe = ((ServerLevel) level).recipeAccess().getRecipes().stream()
                    .filter(r -> r.value() instanceof SpiritTradeRecipe && ((SpiritTradeRecipe) r.value()).matches(recipeInput, level))
                    .map(r -> (RecipeHolder<SpiritTradeRecipe>) r)
                    .filter(r -> r.value().getTrader() == null || r.value().getTrader().equals(this.getFactoryID().toString()))
                    .collect(Collectors.toList());
            this.conversionTimer = 0;

            if (!this.currentRecipe.isEmpty()) {
                //play coin sound
                level.playSound(null, this.entity.blockPosition(), OccultismSounds.COIN.get(),
                        SoundSource.NEUTRAL, 10f, 1 + 0.05f * this.entity.getRandom().nextFloat());
                this.possibleResults = this.currentRecipe.stream().map(r -> r.value().getWeightedResult()).collect(Collectors.toList());
            } else {
                //if no recipe is found, drop hand held item as we can't process it
                this.entity.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, handHeld);
                if (droppedItem != null) {
                    droppedItem.addTag(DROPPED_BY_TRADER);
                }
            }
        }
        if (!this.currentRecipe.isEmpty()) {
            if (handHeld.isEmpty() || !this.currentRecipe.get(0).value().matches(recipeInput, level)) {
                //Reset cached recipe if it no longer matches
                this.currentRecipe = List.of();
            } else {
                //advance conversion
                this.conversionTimer++;

                //show particle effect while trading
                if (level.getGameTime() % 10 == 0) {
                    Vec3 pos = this.entity.position();
                    ((ServerLevel) level)
                            .sendParticles(ParticleTypes.PORTAL, pos.x + level.getRandom().nextGaussian() / 3,
                                    pos.y + 0.5, pos.z + level.getRandom().nextGaussian() / 3, 1, 0.0, 0.0, 0.0,
                                    0.0);
                }

                //every two seconds, play another coin sound
                if (level.getGameTime() % 40 == 0) {
                    level.playSound(null, this.entity.blockPosition(), OccultismSounds.COIN.get(),
                            SoundSource.NEUTRAL, 10f,
                            1 + 0.05f * this.entity.getRandom().nextFloat());
                }

                if (this.conversionTimer >= this.timeToConvert) {
                    this.conversionTimer = 0;

                    int a = Math.min(this.maxTradesPerRound, handHeld.getCount());
                    for (int i = 0; i < a; i++) {
                        var result = WeightedRandom.getRandomItem(this.entity.getRandom(), this.possibleResults, WeightedRecipeResult::weight);
                        //Important: copy the result, don't use it raw!
                        result.ifPresent(r -> {
                            ItemStack finalResult = r.getStack().copy();
                            finalResult.setCount(finalResult.getCount());
                            ItemStack inputCopy = handHeld.copy();
                            handHeld.shrink(1);

                            this.entity.setItemInHand(InteractionHand.MAIN_HAND, handHeld);

                            this.onConvert(inputCopy, finalResult);
                            var event = new TraderJobEvent(this.entity, inputCopy, finalResult);
                            NeoForge.EVENT_BUS.post(event);
                            if (!event.getResult().isEmpty()) {
                                boolean flag = true;
                                if (level.getBlockState(this.entity.blockPosition().below()).is(OccultismBlocks.DIMENSIONAL_EXTRACTOR)) {
                                    if (this.cachedStateBelow != level.getBlockState(this.entity.blockPosition().below(2)))
                                        this.updateBelowBlock();
                                    if (this.handlerBelow != null) {
                                        ItemTransferUtil.insertItemStacked(this.handlerBelow, event.getResult(), false);
                                        flag = false;
                                    }
                                }
                                if (flag) {
                                    ItemEntity droppedItem = this.entity.spawnAtLocation((ServerLevel) level, event.getResult());
                                    if (droppedItem != null) {
                                        droppedItem.addTag(DROPPED_BY_TRADER);
                                    }
                                }
                            }
                        });
                    }

                    //Don't reset recipe here, keep it cached
                }
            }
        }
        super.update();
    }

@Override
    protected void renderTooltip(GuiGraphics guiGraphics, int x, int y) {
        boolean bl = false;

        if(this.hoveredSlot != null) {
            if (this.hoveredSlot instanceof AccessoriesBasedSlot accessoriesInternalSlot) {
                bl = !ArmorSlotTypes.isArmorType(accessoriesInternalSlot.slotName()) && this.getDefaultedData(PlayerOptions.MAIN_WIDGET_POSITION);
            } else if (this.hoveredSlot instanceof ArmorSlot) {
                bl = true;
            } else if (this.hoveredSlot.container instanceof TransientCraftingContainer || this.hoveredSlot instanceof ResultSlot) {
                bl = !(boolean) this.getDefaultedData(PlayerOptions.SHOW_GROUP_FILTER) && !(boolean) this.getDefaultedData(PlayerOptions.MAIN_WIDGET_POSITION);
            }
        }

        AccessoriesScreenBase.setPositioner(bl);

        super.renderTooltip(guiGraphics, x, y);

        if (this.hoveredSlot instanceof AccessoriesBasedSlot slot && ExtraSlotTypeProperties.getProperty(slot.slotName(), true).allowTooltipInfo()) {
            var client = Minecraft.getInstance();

            var ctx = Item.TooltipContext.of(client.level);
            var flag = TooltipFlagExtended.create();

            var key = new TooltipCacheData(slot, this.getMenu().getCarried(), flag.getModifiers());

            var builder = TooltipComponentBuilder.of();
            var existingTooltip = ((DeferredTooltipGetter) guiGraphics).accessories$getTooltip();

            if (existingTooltip != null) {
                builder.add(existingTooltip);
            } else {
                builder.addAll(TooltipInfoProvider.gatherInfo(slot, TooltipEntry.of(), ctx, flag).entries());
            }

            if (this.menu.getCarried().isEmpty()) {
                if (slot.hasItem() && Accessories.config().screenOptions.showEquippedStackSlotType()) {
                    builder
                        .divider(4)
                        .add(
                            Component.translatable(Accessories.translationKey("tooltip.currently_equipped_in"))
                                .withStyle(ChatFormatting.GRAY)
                                .append(
                                    Component.translatable(slot.slotType().translation())
                                        .withStyle(ChatFormatting.BLUE)
                                )
                        );
                }
            }

            var tooltipType = Accessories.config().screenOptions.equipCheckTooltipType();

            if (!key.equals(tooltipStackKey) && tooltipType != TooltipInfoType.DISABLED) {
                tooltipStackKey = key;
                validationTooltipComponents.clear();

                if (!key.isEmpty()) {
                    var stackType = StackType.HELD;
                    var buffer = slot.checkInsertion(key.heldStack);

                    if (buffer.isEmpty() || (buffer.canPerformAction().isValid() && !slot.getItem().isEmpty())) {
                        var otherBuffer = slot.checkExtraction();

                        if (buffer.isEmpty() || (!otherBuffer.isEmpty() && otherBuffer.canPerformAction() != ValidationState.VALID)){
                            stackType = StackType.SLOT;
                            buffer = otherBuffer;
                        }
                    }

                    if (!buffer.isEmpty()) {
                        addValidationInfo(buffer, tooltipType, stackType, validationTooltipComponents, ctx, flag);
                    }
                }
            }

            if (!validationTooltipComponents.isEmpty()) {
                builder
                    .divider(4)
                    .add(validationTooltipComponents);
            }

            if (!builder.isEmpty()) {
                ((GuiGraphicsAccessor) guiGraphics).accessories$setTooltipForNextFrameInternal(
                    this.font,
                    ((TooltipComponentBuilderImpl) builder).build(TextWrapper.createWrapper(240)),
                    x, y,
                    DefaultTooltipPositioner.INSTANCE,
                    null,
                    true
                );
            }
        }

        AccessoriesScreenBase.setPositioner(false);
    }

public void tick() {
        super.tick();
        this.prevPerchProgress = perchProgress;
        this.prevMouthProgress = mouthProgress;
        this.prevFlyProgress = flyProgress;

        if (this.isFlying()) {
            if (flyProgress < 5F)
                flyProgress++;
        } else {
            if (flyProgress > 0F)
                flyProgress--;
        }

        if (this.isPerching()) {
            if (perchProgress < 5F)
                perchProgress++;
        } else {
            if (perchProgress > 0F)
                perchProgress--;
        }

        if (this.ringBufferIndex < 0) {
            //initial population of buffer
            Arrays.fill(this.ringBuffer, 15);
        }
        this.ringBufferIndex++;
        if (this.ringBufferIndex == this.ringBuffer.length) {
            this.ringBufferIndex = 0;
        }
        this.ringBuffer[this.ringBufferIndex] = this.entityData.get(TEMP_BRIGHTNESS);
        if (perchCooldown > 0) {
            perchCooldown--;
        }
        if (!this.level().isClientSide) {
            this.entityData.set(TEMP_BRIGHTNESS, level().getMaxLocalRawBrightness(this.blockPosition()));
            if (isFlying()) {
                if (this.isLandNavigator)
                    switchNavigator(false);
            } else {
                if (!this.isLandNavigator)
                    switchNavigator(true);
            }

            if (this.isFlying()) {
                if (!this.onGround()) {
                    if (!this.isInWaterOrBubble()) {
                        this.setDeltaMovement(this.getDeltaMovement().multiply(1F, 0.6F, 1F));
                    }
                } else if (timeFlying > 20) {
                    this.setFlying(false);
                }
                this.timeFlying++;
            } else {
                this.timeFlying = 0;
            }
            if (this.isPerching() && !this.isVehicle()) {
                this.setSleeping(this.level().isDay() && (this.getTarget() == null || !this.getTarget().isAlive()));
            } else if (isSleeping()) {
                this.setSleeping(false);
            }
            if(isPerching() && this.getPerchPos() != null) {
                if ((!level().getBlockState(this.getPerchPos()).is(AMTagRegistry.POTOO_PERCHES) || this.distanceToSqr(Vec3.atCenterOf(this.getPerchPos())) > 2.25F)) {
                    this.setPerching(false);
                } else {
                    slideTowardsPerch();
                }
            }
        }
        if (this.entityData.get(MOUTH_TICK) > 0) {
            this.entityData.set(MOUTH_TICK, this.entityData.get(MOUTH_TICK) - 1);
            if (mouthProgress < 5F) {
                mouthProgress++;
            }
        } else {
            if (mouthProgress > 0F) {
                mouthProgress--;
            }
        }
        if (!isSleeping() && (this.getTarget() == null || !this.getTarget().isAlive())) {
            int j = tickCount - lastScreamTimestamp;
            if (getEyeScale(10, 1.0F) == 0F) {
                if (j > 40) {
                    this.openMouth(30);
                    this.playSound(AMSoundRegistry.POTOO_CALL.get());
                    this.gameEvent(GameEvent.ENTITY_ROAR);
                }
            } else if (getEyeScale(10, 1.0F) < 7) {
                if (j > 300 && j % 300 == 0 && random.nextInt(4) == 0) {
                    this.openMouth(30);
                    this.playSound(AMSoundRegistry.POTOO_CALL.get());
                    this.gameEvent(GameEvent.ENTITY_ROAR);
                }
            }
        }
    }

@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || this.getOwner() == null || this.getOwner().isDead)) {
			this.setDead();
			return;
		}

		if(!this.world.isRemote) {
			if((this.getOwner() == null || !this.getOwner().isEntityAlive() || this.getOwner() instanceof EntityWight == false || !((EntityWight)this.getOwner()).isVolatile()) /*|| this.target instanceof EntityFortressBoss*/)
				this.setDead();
		}

		if(!this.isDead) {
			this.ticksInAir++;
			if(this.world.isRemote) {
				this.trail.push(this.getPositionVector());
				while(this.trail.size() > 4) {
					this.trail.removeLast();
				}
			}
			if(this.target == null || this.target.isDead) {
				List<Entity> targetList = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(16.0D, 16.0D, 16.0D));
				List<Entity> eligibleTargets = new ArrayList<Entity>();
				if(this.world.rand.nextInt(4) > 0) {
					for(Entity e : targetList) {
						if(e instanceof EntityPlayer) {
							eligibleTargets.add((EntityPlayer)e);
						}
					}
				}
				if(eligibleTargets.isEmpty()) {
					for(Entity e : targetList) {
						if(e instanceof EntityWight == false) {
							eligibleTargets.add(e);
						}
					}
				}
				if(!eligibleTargets.isEmpty()) {
					this.target = eligibleTargets.get(this.world.rand.nextInt(eligibleTargets.size()));
				}
			} 
			if(this.target != null && this.ticksInAir >= 10) {
				double dx = this.target.getEntityBoundingBox().minX + (this.target.getEntityBoundingBox().maxX - this.target.getEntityBoundingBox().minX) / 2.0D - this.posX;
				double dy = this.target.getEntityBoundingBox().minY + (this.target.getEntityBoundingBox().maxY - this.target.getEntityBoundingBox().minY) / 2.0D - this.posY;
				double dz = this.target.getEntityBoundingBox().minZ + (this.target.getEntityBoundingBox().maxZ - this.target.getEntityBoundingBox().minZ) / 2.0D - this.posZ;
				double dist = MathHelper.sqrt(dx * dx + dy * dy + dz * dz);
				double speed = 0.075D;
				double maxSpeed = 0.8D;
				this.motionX += dx / dist * speed;
				this.motionY += dy / dist * speed;
				this.motionZ += dz / dist * speed;
				Vec3d motion = new Vec3d(this.motionX, this.motionY, this.motionZ);
				if(motion.length() > maxSpeed) {
					motion = motion.normalize();
					this.motionX = motion.x * maxSpeed;
					this.motionY = motion.y * maxSpeed;
					this.motionZ = motion.z * maxSpeed;
				}
			}
			Vec3d currentPos = new Vec3d(this.posX, this.posY, this.posZ);
			Vec3d nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
			RayTraceResult hitObject = this.world.rayTraceBlocks(currentPos, nextPos);
			currentPos = new Vec3d(this.posX, this.posY, this.posZ);
			nextPos = new Vec3d(this.posX + this.motionX, this.posY + this.motionY, this.posZ + this.motionZ);
			if (hitObject != null) {
				nextPos = new Vec3d(hitObject.hitVec.x, hitObject.hitVec.y, hitObject.hitVec.z);
			}
			Entity hitEntity = null;
			List<Entity> hitEntities = this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox().grow(this.motionX, this.motionY, this.motionZ).grow(2.0D, 2.0D, 2.0D));
			double minDist = 0.0D;
			for (int i = 0; i < hitEntities.size(); ++i) {
				Entity entity1 = (Entity)hitEntities.get(i);
				if (entity1.canBeCollidedWith() && (this.ticksInAir >= 10)) {
					float f = 0.3F;
					AxisAlignedBB axisalignedbb = entity1.getEntityBoundingBox().grow((double)f, (double)f, (double)f);
					RayTraceResult movingobjectposition1 = axisalignedbb.calculateIntercept(currentPos, nextPos);
					if (movingobjectposition1 != null) {
						double d1 = currentPos.distanceTo(movingobjectposition1.hitVec);
						if (d1 < minDist || minDist == 0.0D) {
							hitEntity = entity1;
							minDist = d1;
						}
					}
				}
			}
			if (hitEntity != null) {
				hitObject = new RayTraceResult(hitEntity);
			}
			if (hitObject != null) {
				this.onImpact(hitObject);
			}
			this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
		}

		super.onUpdate();
	}

@SubscribeEvent
    public static void AttackEvent(LivingAttackEvent event){
        LivingEntity victim = event.getEntity();
        Entity source = event.getSource().getEntity();
        Entity direct = event.getSource().getDirectEntity();
        if (!event.getEntity().level.isClientSide) {
            if (MiscCapHelper.getShields(victim) > 0
                    && !event.getSource().is(DamageTypeTags.BYPASSES_EFFECTS)
                    && !event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY)){
                if (MiscCapHelper.getShieldCool(victim) <= 0) {
                    MiscCapHelper.decreaseShields(victim);
                    if (SpellConfig.BulwarkShieldBreakExtra.get() > 0.0D) {
                        int extra = Mth.floor(event.getAmount() / SpellConfig.BulwarkShieldBreakExtra.get());
                        if (extra >= 1) {
                            for (int i = 0; i < extra; ++i) {
                                MiscCapHelper.decreaseShields(victim);
                            }
                        }
                    }
                    MiscCapHelper.setShieldCool(victim, 10);
                    if (event.getSource().getEntity() instanceof LivingEntity livingEntity){
                        MobUtil.knockBack(livingEntity, victim, 1.0D, 0.2D, 1.0D);
                    }
                }
                event.setCanceled(true);
            }
            if (MainConfig.GoodwillNoDamage.get()) {
                Player player = null;
                if (source instanceof Player player1) {
                    player = player1;
                } else if (MobUtil.getOwner(source) instanceof Player player1) {
                    player = player1;
                }
                if (player != null) {
                    if (SEHelper.isAlly(player, victim)) {
                        event.setCanceled(true);
                    }
                } else if (source instanceof IOwned owned) {
                    if (owned.isAllyWith(victim)) {
                        event.setCanceled(true);
                    }
                }
            }
            if (victim instanceof Witch witch) {
                double d0 = witch.getAttributeValue(Attributes.FOLLOW_RANGE);
                AABB axisalignedbb = AABB.unitCubeFromLowerCorner(witch.position()).inflate(d0, 10.0D, d0);
                List<Mob> list = witch.level.getEntitiesOfClass(Mob.class, axisalignedbb);

                for (Mob mob : list){
                    if (mob.getTarget() == null && witch.getLastHurtByMob() != null && !(witch.getLastHurtByMob() instanceof Raider) && !MobUtil.areAllies(witch.getLastHurtByMob(), witch)) {
                        if (mob instanceof Cultist && !mob.getType().is(Tags.EntityTypes.BOSSES) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(witch.getLastHurtByMob())) {
                            mob.setTarget(witch.getLastHurtByMob());
                        }
                    }
                }
            }
        }

        if (event.getSource() instanceof NoKnockBackDamageSource){
            if (!victim.level.isClientSide) {
                CompoundTag tag = victim.getPersistentData();
                tag.putInt(NO_KNOCKBACK_TAG, victim.tickCount);
            }
        }

        if (source instanceof IOwned owned){
            if (owned.getMasterOwner() instanceof Player player) {
                victim.lastHurtByPlayer = player;
                victim.lastHurtByPlayerTime = 100;
            }
        }

        if (direct instanceof AbstractArrow arrowEntity){
            if (arrowEntity.getTags().contains(ConstantPaths.rainArrow()) || arrowEntity.getOwner() instanceof Apostle){
                if (arrowEntity.getOwner() != null) {
                    if (victim instanceof IOwned ownedEntity) {
                        if (ownedEntity.getTrueOwner() != null) {
                            if (ownedEntity.getTrueOwner() == arrowEntity.getOwner()) {
                                event.setCanceled(true);
                            }
                        }
                    }
                    if (victim == arrowEntity.getOwner()){
                        event.setCanceled(true);
                    }
                }
            }
            if (!(arrowEntity.getOwner() instanceof Apostle && victim.level.getDifficulty() == Difficulty.HARD)) {
                if (victim instanceof Player player) {
                    if (MobUtil.starAmuletActive(player)) {
                        event.setCanceled(true);
                    }
                }
            }
        }
    }

public void tick() {
        super.tick();
        var cloudData = this.getCloudData();
        if (cloudData == null) {
            // this.discard();
            return;
        }
        var world = this.getWorld();
        if (world.isClient) {
            // Client side tick
            float trackedRadius = getDataTracker().get(RADIUS_TRACKER);
            if (spawnRenderRadius < 0F) {
                spawnRenderRadius = prevRenderRadius = renderRadius = trackedRadius;
            } else {
                prevRenderRadius = renderRadius;
                renderRadius = trackedRadius;
            }
            setupAnimationStates();
            var clientData = cloudData.client_data;
            var spawnParticles = clientData.particle_spawn_interval <= 1 || (this.age % clientData.particle_spawn_interval) == 0;
            if (spawnParticles) {
                for (var particleBatch : clientData.interval_particles) {
                    ParticleHelper.play(world, this, particleBatch);
                }
            }
            for (var particleBatch : clientData.particles) {
                ParticleHelper.play(world, this, particleBatch);
            }

            var presence_sound = cloudData.presence_sound;
            if (!presenceSoundFired && presence_sound != null) {
                var soundEvent = Registries.SOUND_EVENT.get(Identifier.of(presence_sound.id()));
                if (soundEvent != null) {
                    ((SoundPlayerWorld) world).playSoundFromEntity(this, soundEvent, SoundCategory.PLAYERS,
                            presence_sound.volume(),
                            presence_sound.randomizedPitch());
                    presenceSoundFired = true;
                } else {
                    System.out.println("SpellCloud: Failed to find presence sound " + presence_sound.id());
                }
            }

        } else {
            // Server side tick
            if (this.age >= this.timeToLive) {
                this.discard();
                return;
            }
            // Advance the lifecycle phase. Impacts are only performed while ACTIVE — the
            // spawning and despawning phases are warm-up / wind-down, matching SummonedEntity.
            byte phase;
            if (this.age < spawnDuration) {
                phase = PHASE_SPAWNING;
            } else if (this.age >= timeToLive - despawnDuration) {
                phase = PHASE_DESPAWNING;
            } else {
                phase = PHASE_ACTIVE;
            }
            setPhase(phase);
            // Lifetime growth: recompute the radius from the current age and republish it only when it
            // actually changes (i.e. on a growth-step boundary), so rendering/collision follow and sync
            // traffic stays minimal. `radiusForAge` is a no-op unless `growth` is configured.
            float grownRadius = radiusForAge(this.age);
            if (grownRadius != getDataTracker().get(RADIUS_TRACKER)) {
                getDataTracker().set(RADIUS_TRACKER, grownRadius);
                calculateDimensions();
            }
            if (phase == PHASE_ACTIVE && (this.age % cloudData.impact_tick_interval) == 0) {
                // Impact tick due
                var area_impact = cloudData.volume;
                var owner = (LivingEntity) this.getOwner();
                var spellEntry = getSpellEntry();
                if (area_impact != null && owner != null && spellEntry != null) {
                    var spell = spellEntry.value();
                    var context = this.context;
                    if (context == null) {
                        context = new SpellExecution.ImpactContext();
                    }
                    var performed = SpellImpacts.lookupAndPerformAreaImpact(area_impact, spellEntry, owner,null,
                            this, spell.impacts, context.position(this.getPos()), true, grownRadius);
                    if (performed) {
                        onImpactPerformed(owner, world, cloudData, context);
                        if (this.impactCap > 0 && this.impactsPerformed >= this.impactCap) {
                            // A spent cloud winds down through DESPAWNING rather than vanishing on
                            // the spot, so its model gets a phase to animate in. A subclass that
                            // already called `beginDespawn` from `onImpactPerformed` (e.g. to use a
                            // longer, bespoke clip) makes this a no-op.
                            beginDespawn(this.despawnDuration);
                        }
                    } else {
                        onImpactFailed(owner, world, cloudData, context);
                    }
                }
            }
        }
    }

@Override
    public void extractRenderState(SacrificialBowlBlockEntity blockEntity, GoldenSacrificialBowlRenderState renderState, float partialTick, Vec3 cameraPos, @Nullable CrumblingOverlay crumbling) {
        BlockEntityRenderer.super.extractRenderState(blockEntity, renderState, partialTick, cameraPos, crumbling);

        ItemStack stack = blockEntity.itemStackHandler.getResource(0).toStack();
        Direction facing = blockEntity.getBlockState().hasProperty(BlockStateProperties.FACING) ?
                blockEntity.getBlockState().getValue(BlockStateProperties.FACING) : Direction.UP;
        long gameTime = blockEntity.getLevel() != null ? blockEntity.getLevel().getGameTime() : 0L;
        long lastChangeTime = blockEntity.lastChangeTime;

        renderState.itemStack = stack;
        renderState.facing = facing;
        renderState.gameTime = gameTime;
        renderState.lastChangeTime = lastChangeTime;

        // Update the pre-initialized ItemStackRenderState with the current item
        if (!stack.isEmpty()) {
            int seed = (int) (blockEntity.getBlockPos().asLong() & 0xFFFFFFFFL);
            this.itemModelResolver.updateForTopItem(renderState.itemStackRenderState, stack, ItemDisplayContext.FIXED, blockEntity.getLevel(), null, seed);
        }

        // GoldenSacrificialBowl-specific data
        if (blockEntity instanceof GoldenSacrificialBowlBlockEntity goldenBowl) {
            renderState.isGoldenBowl = true;

            var recipe = goldenBowl.getCurrentRitualRecipe();
            if (recipe != null) {
                renderState.itemUseFulfilled = goldenBowl.itemUseFulfilled();
                renderState.sacrificeFulfilled = goldenBowl.sacrificeFulfilled();
                renderState.recipeId = recipe.id().toString();
                renderState.requiresItemUse = recipe.value().requiresItemUse();
                renderState.requiresSacrifice = recipe.value().requiresSacrifice();
                renderState.sacrificeEntityType = null;
                renderState.sacrificeEntityRenderState = null;
                renderState.sacrificeEntityScale = 1.0F;

                // Get item to use for cycling animation
                if (renderState.requiresItemUse) {
                    // Cache invalidation: only rebuild if recipe changed
                    boolean recipeChanged = !Objects.equals(renderState.recipeId, renderState.cachedRecipeId);

                    if (recipeChanged) {
                        var items = recipe.value().getItemToUse().items().toList();
                        if (!items.isEmpty()) {
                            renderState.itemToUseStacks = items.stream()
                                    .map(holder -> new ItemStack(holder.value()))
                                    .toArray(ItemStack[]::new);
                            renderState.cachedRecipeId = renderState.recipeId;
                        }
                    }

                    // Compute cycling index in extract (called every frame)
                    if (renderState.itemToUseStacks != null && renderState.itemToUseStacks.length > 0) {
                        renderState.itemToUseIndex = renderState.itemToUseStacks.length == 1 ? 0 : (int) ((System.currentTimeMillis() / 2880) % renderState.itemToUseStacks.length);

                        // Pre-update render state for current index
                        if (!renderState.itemToUseStacks[renderState.itemToUseIndex].isEmpty()) {
                            this.itemModelResolver.updateForTopItem(renderState.itemToUseRenderState, renderState.itemToUseStacks[renderState.itemToUseIndex], ItemDisplayContext.FIXED, blockEntity.getLevel(), null, renderState.itemToUseIndex + 1);
                        }
                    }
                }

                if (renderState.requiresSacrifice && !renderState.sacrificeFulfilled) {
                    var entityType = EntityUtil.getEntityInTag(blockEntity.getLevel(), recipe.value().getEntityToSacrifice());
                    renderState.sacrificeEntityType = entityType;
                    LivingEntity entity = this.getSacrificePreviewEntity(entityType, blockEntity.getLevel());
                    if (entity != null) {
                        entity.setYRot(0);
                        entity.yRotO = 0;
                        entity.setYBodyRot(0);
                        entity.yBodyRotO = 0;
                        entity.setYHeadRot(0);
                        entity.yHeadRotO = 0;

                        BlockPos previewPos = blockEntity.getBlockPos().relative(facing, 2).above(3);
                        entity.setPos(previewPos.getX() + 0.5, previewPos.getY(), previewPos.getZ() + 0.5);

                        float maxSize = Math.max(entity.getBbWidth(), Math.max(entity.getBbHeight(), entity.getBbWidth()));
                        renderState.sacrificeEntityScale = maxSize > 0 ? 0.5F / maxSize : 1.0F;
                        renderState.sacrificeEntityRenderState = Minecraft.getInstance().getEntityRenderDispatcher().extractEntity(entity, partialTick);
                        renderState.sacrificeEntityRenderState.lightCoords = LevelRenderer.getLightCoords(blockEntity.getLevel(), previewPos);
                    }
                }
            } else {
                renderState.itemUseFulfilled = true;
                renderState.sacrificeFulfilled = true;
                renderState.requiresItemUse = false;
                renderState.requiresSacrifice = false;
                renderState.sacrificeEntityType = null;
                renderState.sacrificeEntityRenderState = null;
                renderState.sacrificeEntityScale = 1.0F;
            }
        } else {
            renderState.isGoldenBowl = false;
        }
    }

@Override
	public void onEntityCollision(Level world, Entity entity)
	{
		boolean contact = false;
		Direction facing = getFacing();
		if(!diagonal)
			contact = entity.getY()-getBlockPos().getY() <= .125;
		else if(facing==Direction.NORTH)
			contact = entity.getZ()-getBlockPos().getZ() <= .125;
		else if(facing==Direction.SOUTH)
			contact = entity.getZ()-getBlockPos().getZ() >= .875;
		else if(facing==Direction.WEST)
			contact = entity.getX()-getBlockPos().getX() <= .125;
		else if(facing==Direction.EAST)
			contact = entity.getX()-getBlockPos().getX() >= .875;

		if(this.diagonal&&entity.getY()-getBlockPos().getY() <= .625)
		{
			BlockPos target = getBlockPos().relative(facing);
			BlockEntity targetTile = world.getBlockEntity(target);
			boolean opposedChute = targetTile instanceof ChuteBlockEntity&&((ChuteBlockEntity)targetTile).diagonal;
			// We're not going to redirect into another diagonal chute, to avoid infinite bouncing
			if(opposedChute)
				return;

			long time = world.getGameTime();
			long nbt_pos = getBlockPos().asLong();
			long timeSince = time-entity.getPersistentData().getLong(NBT_TIME);

			boolean prevent = entity.getPersistentData().contains(NBT_POS)
					&&nbt_pos==entity.getPersistentData().getLong(NBT_POS)
					&&timeSince < 20;
			// glitch timer resets after 60 seconds
			boolean glitched = entity.getPersistentData().contains(NBT_GLITCH)&&time-entity.getPersistentData().getLong(NBT_GLITCH) < 1200;

			if(entity.getBbWidth() > 0.75||entity.getBbHeight() > 0.75)
			{
				// We're not going to redirect into a colliding block
				if(world.getBlockState(target).isSuffocating(world, target))
					return;
				if(!glitched)
				{
					Vec3 oldPos = entity.position();
					double py = entity.getBbHeight() > 1?getBlockPos().getY()+.125: entity.getY();
					entity.setPos(target.getX()+.5, py, target.getZ()+.5);
					if(entity.isInWall())
					{
						entity.setPos(oldPos.x, oldPos.y, oldPos.z);
						entity.getPersistentData().putLong(NBT_GLITCH, time);
					}
				}
			}
			else
			{
				double mY = entity.getDeltaMovement().y;
				if(mY==0)
					mY = 0.015;
				entity.setDeltaMovement(facing.getStepX(), mY, facing.getStepZ());
			}

			if(!contact&&!prevent&&!glitched)
			{
				world.playSound(null, entity.getX(), entity.getY(), entity.getZ(), IESounds.chute.value(), SoundSource.BLOCKS, .6f+(.4f*world.random.nextFloat()), .5f+(.5f*world.random.nextFloat()));
				CompoundTag entityData = entity.getPersistentData();
				entityData.putLong(NBT_POS, nbt_pos);
				entityData.putLong(NBT_TIME, time);
				if(entity instanceof Player player&&!world.isClientSide())
				{
					int bonkCount = entityData.getInt(NBT_COUNT)+1;
					if(timeSince > 200)
						bonkCount = 1;
					entity.getPersistentData().putInt(NBT_COUNT, bonkCount);
					if(bonkCount >= 6)
						Utils.unlockIEAdvancement(player, "main/chute_bonk");
				}
			}
		}

		if(entity instanceof ItemEntity itemEntity)
		{
			itemEntity.setPickUpDelay(10);
			if(!contact)
			{
				if(itemEntity.getAge() > itemEntity.lifespan-60*20)
					((ItemEntityAccess)itemEntity).setAge(itemEntity.lifespan-60*20);
			}
			else
			{
				BlockEntity inventoryTile;
				BlockPos invPos = diagonal?getBlockPos().relative(facing): getBlockPos().below();
				inventoryTile = world.getBlockEntity(invPos);
				Direction insertFrom = diagonal?facing.getOpposite(): Direction.UP;
				if(!world.isClientSide&&isValidTargetInventory(inventoryTile))
					ItemUtils.tryInsertEntity(world, invPos, insertFrom, itemEntity);
			}
		}
	}

@Override
    protected BlockPos computeNext() {
      while (!upcomingPositions.isEmpty()) {
        // if the position matches the block, add it. Some positions are already added
        TreePos treePos = upcomingPositions.remove();

        // trunk logic
        if (treePos.direction == Direction.UP) {
          boolean isTreeUp = treePos.isChecked || isValidBlock(treePos.pos);

          // find branches in all 4 directions if going up, assuming we are in the
          for (Direction direction : Plane.HORIZONTAL) {
            // if the position is a branch, meaning its a log with no log above it, queue it
            mutable.set(treePos.pos).move(direction);
            // if we did not find a log at the current position, treat the position as our new tree, for acacia
            tryBranch(!isTreeUp ? Direction.UP : direction);
          }

          if (isTreeUp) {
            // corner case, only care if we have a tree at current position
            boolean isMinX = treePos.pos.getX() == minX;
            boolean isMaxX = treePos.pos.getX() == maxX;
            boolean isMinZ = treePos.pos.getZ() == minZ;
            boolean isMaxZ = treePos.pos.getZ() == maxZ;
            // if either min or max on both axis, but not both (1x1), we are a corner, do corner case
            if (isMinX) {
              if (isMinZ) {
                mutable.set(treePos.pos).move(-1, 0, -1);
                tryBranch(Direction.WEST);
              }
              if (isMaxZ) {
                mutable.set(treePos.pos).move(-1, 0, 1);
                tryBranch(Direction.WEST);
              }
            }
            if (isMaxX) {
              if (isMinZ) {
                mutable.set(treePos.pos).move(1, 0, -1);
                tryBranch(Direction.EAST);
              }
              if (isMaxZ) {
                mutable.set(treePos.pos).move(1, 0, 1);
                tryBranch(Direction.EAST);
              }
            }

            // finally, return this position
            // insert the updated position into the queue and return the current position
            mutable.set(treePos.pos);
            upcomingPositions.add(treePos.move());
            // acacia can continue outside the original trunk, so start marking it visited to prevent redundancy
            if (outsideTrunk(treePos.pos)) {
              branchVisited.add(treePos.pos);
            }
            return mutable;
          }
        } else {
          // branch logic, should always be checked ahead of time (question is which further branches can we find)
          // continue in same direction
          mutable.set(treePos.pos).move(0, 1, 0);
          if (isBranch(mutable)) {
            addBranch(treePos.direction);
            // just direction, no up
          } else if (isBranch(mutable.move(treePos.direction).move(0, -1, 0))) {
            addBranch(treePos.direction);
            // direction and up
          } else if (isBranch(mutable.move(0, 1, 0))) {
            addBranch(treePos.direction);
          }
          // try each side, we check pos, above, then continuing the side
          Direction rotated = treePos.direction.getClockWise();
          mutable.set(treePos.pos).move(rotated);
          if (isBranch(mutable)) {
            addBranch(rotated);
          } else if (isBranch(mutable.move(0, 1, 0))) {
            addBranch(rotated);
          } else if (isBranch(mutable.move(treePos.direction).move(0, -1, 0))) {
            addBranch(rotated);
          } else if (isBranch(mutable.move(0, 1, 0))) {
            addBranch(rotated);
          }
          rotated = rotated.getOpposite();
          mutable.set(treePos.pos).move(rotated);
          if (isBranch(mutable)) {
            addBranch(rotated);
          } else if (isBranch(mutable.move(0, 1, 0))) {
            addBranch(rotated);
          } else if (isBranch(mutable.move(treePos.direction).move(0, -1, 0))) {
            addBranch(rotated);
          } else if (isBranch(mutable.move(0, 1, 0))) {
            addBranch(rotated);
          }
          return treePos.pos;
        }
      }
      return endOfData();
    }

@Override
    public void onUpdate() {
        this.player.getCommandSenderWorld().getProfiler().push("werewolves_werewolfplayer");
        super.onUpdate();
        if (getLevel() > 0) {
            if (!isRemote()) {
                boolean sync = false;
                boolean syncToAll = false;
                CompoundTag syncPacket = new CompoundTag();
                if (this.actionHandler.updateActions()) {
                    sync = true;
                    syncToAll = true;
                    syncPacket.put(this.actionHandler.nbtKey(), this.actionHandler.serializeUpdateNBT(this.player.registryAccess()));
                }
                if (this.skillHandler.isDirty()) {
                    sync = true;
                    syncToAll = true;
                    syncPacket.put(this.skillHandler.nbtKey(), this.skillHandler.serializeUpdateNBT(this.player.registryAccess()));
                }
                if (this.player.level().getGameTime() % 10 == 0) {
                    if (this.specialAttributes.transformationTime > 0 && !FormHelper.isFormActionActive(this)) {
                        this.specialAttributes.transformationTime = Mth.clamp(this.specialAttributes.transformationTime - player.getAttribute(ModAttributes.TIME_REGAIN).getValue(), 0, 1);
                        syncPacket.putDouble("transformationTime", this.specialAttributes.transformationTime);
                    }
                    if (this.player.level().getGameTime() % 20 == 0) {
                        if (Helper.isFullMoon(this.getRepresentingPlayer().getCommandSenderWorld())) {
                            if (!FormHelper.isFormActionActive(this) && !this.skillHandler.isSkillEnabled(ModSkills.FREE_WILL.get())) {
                                Optional<? extends IAction<IWerewolfPlayer>> action = lastFormAction != null ? Optional.of(lastFormAction) : WerewolfFormAction.getAllAction().stream().filter(this.actionHandler::isActionUnlocked).findAny();
                                action.ifPresent(a -> this.actionHandler.toggleAction(a, new ActionHandler.ActivationContext()));
                            }
                        }

                        if (this.player.isInWater() && this.player.isEyeInFluidType(NeoForgeMod.WATER_TYPE.value()) && !this.skillHandler.isSkillEnabled(ModSkills.WATER_LOVER.get())) {
                            this.player.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 50, 0, true, true));
                        }
                    }
                }

                if (this.skillHandler.isSkillEnabled(ModSkills.HEALTH_REG.get())) {
                    this.tickFoodStats();
                }

                if (sync) {
                    sync(syncPacket, syncToAll);
                }

                MobEffectInstance effect = this.player.getEffect(MobEffects.NIGHT_VISION);
                if (this.getForm().isTransformed() && this.specialAttributes.night_vision) {
                    if (effect == null || !VReference.PERMANENT_INVISIBLE_MOB_EFFECT.equals(((EffectInstanceWithSource) effect).getSource())) {
                        if (effect != null) {
                            player.removeEffectNoUpdate(effect.getEffect());
                        }
                        player.addEffect(new WerewolfNightVisionEffectInstance(effect));
                    }
                } else {
                    if (effect != null && VReference.PERMANENT_INVISIBLE_MOB_EFFECT.equals(((EffectInstanceWithSource)effect).getSource())) {
                        this.player.removeEffect(effect.getEffect());
                        effect = ((EffectInstanceWithSource) effect).getHiddenEffect();
                        if (effect != null) {
                            this.player.addEffect(effect);
                        }
                    }
                }

                if (this.player.tickCount % de.teamlapen.vampirism.REFERENCE.REFRESH_GARLIC_TICKS == 0 && this.isAffectedByWolfsbane(this.player.level(), true)) {
                    this.player.addEffect(WolfsbaneEffect.createWolfsbaneEffect(this.player, de.teamlapen.vampirism.REFERENCE.REFRESH_GARLIC_TICKS + 10, this.wolfsbaneCache));
                }
            } else {

                this.actionHandler.updateActions();

                if (this.player.level().getGameTime() % 10 == 0) {
                    if (this.specialAttributes.transformationTime > 0 && !FormHelper.isFormActionActive(this)) {
                        this.specialAttributes.transformationTime = Mth.clamp(this.specialAttributes.transformationTime - ((float) player.getAttribute(ModAttributes.TIME_REGAIN).getValue()), 0, 1);
                    }
                }

                MobEffectInstance effect = this.player.getEffect(MobEffects.NIGHT_VISION);
                if (this.getForm().isTransformed() && this.specialAttributes.night_vision && !(effect instanceof WerewolfNightVisionEffectInstance)) {
                    player.removeEffectNoUpdate(MobEffects.NIGHT_VISION);
                    player.addEffect(new WerewolfNightVisionEffectInstance());
                }
            }

            this.specialAttributes.biteTicks = Math.max(0, this.specialAttributes.biteTicks - 1);

        } else if (!this.isRemote() && this.player.isSleeping() && this.player.hasEffect(ModEffects.LUPUS_SANGUINEM)) {
            if (this.sleepTimer++ >= 200) {
                this.player.getEffect(ModEffects.LUPUS_SANGUINEM).tick(this.player, () -> {});
                this.player.removeEffect(ModEffects.LUPUS_SANGUINEM);
                this.player.stopSleeping();
            }
        } else {
            this.sleepTimer = 0;
        }
        this.player.getCommandSenderWorld().getProfiler().pop();
    }

