@Override
    protected boolean doPlace(WorldGenLevel level, RandomSource rand, OreConfiguration config, double minX, double maxX, double minZ, double maxZ, double minY, double maxY, int x, int y, int z, int width, int height) {
        final PositionTableSet placements = PositionTableSet.of(width, height, width);
        final BlockPos.MutableBlockPos testPos = new BlockPos.MutableBlockPos();
        final int size = config.size;
        final double[] blobPoints = new double[size * 4];
        int placeCount = 0;

        for (int i = 0; i < size; ++i) {
            final float step = (float)i / (float)size;
            final double blobSize = rand.nextDouble() * (double)size / 16;

            blobPoints[i * 4 + 0] = Mth.lerp(step, minX, maxX);
            blobPoints[i * 4 + 1] = Mth.lerp(step, minY, maxY);
            blobPoints[i * 4 + 2] = Mth.lerp(step, minZ, maxZ);
            blobPoints[i * 4 + 3] = ((double)(Mth.sin((float)Math.PI * step) + 1) * blobSize + 1) / 2d;
        }

        for (int i = 0; i < size - 1; ++i) {
            if (blobPoints[i * 4 + 3] <= 0)
                continue;

            for (int j = i + 1; j < size; ++j) {
                if (blobPoints[j * 4 + 3] <= 0)
                    continue;

                double xSize = blobPoints[i * 4 + 0] - blobPoints[j * 4 + 0];
                double ySize = blobPoints[i * 4 + 1] - blobPoints[j * 4 + 1];
                double zSize = blobPoints[i * 4 + 2] - blobPoints[j * 4 + 2];
                double radius = blobPoints[i * 4 + 3] - blobPoints[j * 4 + 3];

                if (radius * radius > xSize * xSize + ySize * ySize + zSize * zSize)
                    blobPoints[(radius > 0 ? j : i) * 4 + 3] = -1;
            }
        }

        for (int i = 0; i < size; ++i) {
            final double blobPointRadius = blobPoints[i * 4 + 3];

            if (blobPointRadius < 0)
                continue;

            final double blobPointX = blobPoints[i * 4 + 0];
            final double blobPointY = blobPoints[i * 4 + 1];
            final double blobPointZ = blobPoints[i * 4 + 2];
            final int blobMinX = Math.max(Mth.floor(blobPointX - blobPointRadius), x);
            final int blobMinY = Math.max(Mth.floor(blobPointY - blobPointRadius), y);
            final int blobMinZ = Math.max(Mth.floor(blobPointZ - blobPointRadius), z);
            final int blobMaxX = Math.max(Mth.floor(blobPointX + blobPointRadius), blobMinX);
            final int blobMaxY = Math.max(Mth.floor(blobPointY + blobPointRadius), blobMinY);
            final int blobMaxZ = Math.max(Mth.floor(blobPointZ + blobPointRadius), blobMinZ);

            for (int oreX = blobMinX; oreX <= blobMaxX; ++oreX) {
                final double oreXRadius = ((double)oreX + 0.5D - blobPointX) / blobPointRadius;

                if (oreXRadius * oreXRadius >= 1)
                    continue;

                for (int oreY = blobMinY; oreY <= blobMaxY; ++oreY) {
                    final double oreYRadius = ((double)oreY + 0.5D - blobPointY) / blobPointRadius;

                    if (oreXRadius * oreXRadius + oreYRadius * oreYRadius >= 1)
                        continue;

                    for (int oreZ = blobMinZ; oreZ <= blobMaxZ; ++oreZ) {
                        final double oreZRadius = ((double)oreZ + 0.5D - blobPointZ) / blobPointRadius;

                        if (oreXRadius * oreXRadius + oreYRadius * oreYRadius + oreZRadius * oreZRadius >= 1 || level.isOutsideBuildHeight(oreY))
                            continue;

                        if (!placements.isFilledAt(oreX - x, oreY - y, oreZ - z)) {
                            placements.add(oreX - x, oreY - y, oreZ - z);
                            testPos.set(oreX, oreY, oreZ);

                            if (level.ensureCanWrite(testPos)) {
                                final BlockState preOreState = level.getBlockState(testPos);

                                for(OreConfiguration.TargetBlockState targetState : config.targetStates) {
                                    if (canPlaceOre(preOreState, level::getBlockState, rand, config, targetState, testPos)) {
                                        level.setBlock(testPos, targetState.state, Block.UPDATE_CLIENTS);

                                        if (!targetState.state.getFluidState().isEmpty())
                                            level.scheduleTick(testPos.immutable(), targetState.state.getFluidState().getType(), 0);

                                        ++placeCount;

                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        return placeCount > 0;
    }

public void tick() {
        super.tick();
        if (this.ringBufferIndex < 0) {
            for (int i = 0; i < this.ringBuffer.length; ++i) {
                this.ringBuffer[i] = this.getYRot();
            }
        }
        this.ringBufferIndex++;
        if (this.ringBufferIndex == this.ringBuffer.length) {
            this.ringBufferIndex = 0;
        }
        this.ringBuffer[this.ringBufferIndex] = this.getYRot();
        if(!this.level().isClientSide){
            final int segments = 15;
            final Entity child = getChild();
            if (child == null) {
                LivingEntity partParent = this;
                parts = new PalaeophisPartEntity[segments];
                PalaeophisPartIndex partIndex = PalaeophisPartIndex.HEAD;
                Vec3 prevPos = this.position();
                for (int i = 0; i < segments; i++) {
                    final float prevReqRot = calcPartRotation(i) + getYawForPart(i);
                    final float reqRot = calcPartRotation(i + 1) + getYawForPart(i);
                    PalaeophisPartEntity part = new PalaeophisPartEntity(UPEntities.PALAEOPHIS_PART.get(), this);
                    part.setParent(partParent);
                    part.copyDataFrom(this);
                    part.setBodyIndex(i);
                    part.setPartType(PalaeophisPartIndex.sizeAt(1 + i));
                    if (partParent == this) {
                        this.setChildId(part.getUUID());
                        this.entityData.set(CHILD_ID, part.getId());
                    }
                    if (partParent instanceof PalaeophisPartEntity) {
                        ((PalaeophisPartEntity) partParent).setChildId(part.getUUID());
                    }
                    part.setPos(part.tickMultipartPosition(this.getId(), partIndex, prevPos, this.getXRot(), prevReqRot, reqRot, true));
                    partParent = part;
                    level().addFreshEntity(part);
                    parts[i] = part;
                    partIndex = part.getPartType();
                    prevPos = part.position();
                }
            }
            if (shouldReplaceParts() && this.getChild() instanceof PalaeophisPartEntity) {
                parts = new PalaeophisPartEntity[segments];
                parts[0] = (PalaeophisPartEntity) this.getChild();
                this.entityData.set(CHILD_ID, parts[0].getId());
                int i = 1;
                while (i < parts.length && parts[i - 1].getChild() instanceof PalaeophisPartEntity) {
                    parts[i] = (PalaeophisPartEntity) parts[i - 1].getChild();
                    i++;
                }
            }
            PalaeophisPartIndex partIndex = PalaeophisPartIndex.HEAD;
            Vec3 prev = this.position();
            float xRot = this.getXRot();
            for (int i = 0; i < segments; i++) {
                if (this.parts[i] != null) {
                    final float prevReqRot = calcPartRotation(i) + getYawForPart(i);
                    final float reqRot = calcPartRotation(i + 1) + getYawForPart(i);
                    parts[i].setStrangleProgress(this.strangleProgress);
                    parts[i].copyDataFrom(this);
                    prev = parts[i].tickMultipartPosition(this.getId(), partIndex, prev, xRot, prevReqRot, reqRot, true);
                    partIndex = parts[i].getPartType();
                    xRot = parts[i].getXRot();
                }
            }

            if (isInWater()) swimTimer = Math.max(swimTimer + 1, 0);
            else swimTimer = Math.min(swimTimer - 1, 0);
        }
        if (sheddingCooldown >= 0) {
            sheddingCooldown--;
        }

        if (this.getSheddingTime() >= 0) {
            int shedTime = getSheddingTime();
            setSheddingTime(shedTime - 1);

            if (shedTime == 0) {
                // The snake was in "shed mode," and the shedding time has expired.
                // Reset sheddingCooldown for the next shedding event.
                sheddingCooldown = this.getRandom().nextInt(6000) + 1500;
            }
            return;
        }

        if (!this.level().isClientSide && this.isAlive() && this.getSheddingTime() < 0 && sheddingCooldown < 0) {
            // The snake is not in "shed mode," so let's start shedding.
            this.spawnAtLocation(UPItems.PALAEO_SKIN.get(), 1);

            // Set the shedding time for the snake (how long it will be in "shed mode").
            this.setSheddingTime(this.getRandom().nextInt(1000) + 1500);

        }


    }

@OnlyIn(Dist.CLIENT)
	public void registerVariants() {
		this.wobble = new CompassWobble(0.1);
		this.wobbleRandom = new CompassWobble(0.6); // 0.6 to make it GO FASTA

		ItemProperties.register(this, new ResourceLocation("angle"), new ClampedItemPropertyFunction() {
			private final CompassWobble wobble = SoulCompass.this.wobble;
			private final CompassWobble wobbleRandom = SoulCompass.this.wobbleRandom;

			@Override
			public float unclampedCall(ItemStack stack, @Nullable ClientLevel level, @Nullable LivingEntity living, int seed) {
				Entity entity = living != null ? living : stack.getEntityRepresentation();

				if (entity == null)
					return 0.0F;
				else {
					if (level == null && entity.level() instanceof ClientLevel) {
						level = (ClientLevel) entity.level();
					}

					assert level != null;

					BlockPos target = this.getTargetPosition();
					long gameTime = level.getGameTime();

					if (target != null && !(entity.position().distanceToSqr(target.getX() + 0.5D, entity.position().y(), target.getZ() + 0.5D) < 1.0E-5F)) {
						boolean isLocalPlayer = living instanceof Player && ((Player)living).isLocalPlayer();
						double bodyRotation = 0.0D;

						if (isLocalPlayer) {
							assert living != null;
							bodyRotation = living.getYRot();
						} else
							return this.randomAngle(gameTime, seed);

						if (!SuperpositionHandler.isTheCursedOne((Player) living)
								|| !SuperpositionHandler.hasExactStack((Player) living, stack)
								|| level.getBiome(living.blockPosition()).is(Biomes.SOUL_SAND_VALLEY))
							return this.randomAngle(gameTime, seed);

						bodyRotation = Mth.positiveModulo(bodyRotation / 360.0D, 1.0D);
						double angle = SoulCompass.this.getAngleTo(Vec3.atCenterOf(target), entity) / ((float)Math.PI * 2F);
						double otherAngle;

						if (this.wobble.shouldUpdate(gameTime)) {
							this.wobble.update(gameTime, 0.5D - (bodyRotation - 0.25D));
						}

						otherAngle = angle + this.wobble.rotation;

						return Mth.positiveModulo((float)otherAngle, 1.0F);
					} else
						return this.randomAngle(gameTime, seed);
				}
			}

			private float randomAngle(long gameTime, int seed) {
				if (this.wobbleRandom.shouldUpdate(gameTime)) {
					this.wobbleRandom.update(gameTime, Math.random());
				}

				double randomAngle = this.wobbleRandom.rotation + this.hash(seed) / 2.14748365E9F;
				return Mth.positiveModulo((float)randomAngle, 1.0F);
			}

			private int hash(int value) {
				return value * 1327217883;
			}

			@Nullable
			private BlockPos getTargetPosition() {
				return SoulCompass.this.nearestCrystal;
			}

			@Nullable
			private BlockPos getSpawnPosition(ClientLevel level) {
				return level.dimensionType().natural() ? level.getSharedSpawnPos() : null;
			}

			@Nullable
			private BlockPos getLodestonePosition(Level level, CompoundTag tag) {
				boolean flag = tag.contains("LodestonePos");
				boolean flag1 = tag.contains("LodestoneDimension");
				if (flag && flag1) {
					Optional<ResourceKey<Level>> optional = Level.RESOURCE_KEY_CODEC.parse(NbtOps.INSTANCE, tag.get("LodestoneDimension")).result();
					if (optional.isPresent() && level.dimension() == optional.get())
						return NbtUtils.readBlockPos(tag.getCompound("LodestonePos"));
				}

				return null;
			}

			private double getFrameRotation(ItemFrame frame) {
				Direction direction = frame.getDirection();
				int i = direction.getAxis().isVertical() ? 90 * direction.getAxisDirection().getStep() : 0;
				return Mth.wrapDegrees(180 + direction.get2DDataValue() * 90 + frame.getRotation() * 45 + i);
			}
		});
	}

@Inject(method = "respawn", at = @At("HEAD"), cancellable = true)
	private void respawn(ServerPlayer player, boolean keep, CallbackInfoReturnable<ServerPlayer> info) {
		BlockPos pos = player.getRespawnPosition();
		float angle = player.getRespawnAngle();
		boolean forced = player.isRespawnForced();
		boolean override = false;
		boolean endRespawn = false;
		ServerLevel level = this.server.getLevel(player.getRespawnDimension());
		Optional<Vec3> optional = Optional.empty();

		if (level != null && pos != null) {
			AnchorSearchResult result = EndAnchor.findEndAnchor(level, pos, angle, forced, keep);

			if (result.found()) {
				optional = result.location();
				override = true;

				if (keep && level.dimension() == Level.END && optional.isPresent()) {
					endRespawn = true;
					optional = Optional.empty();
				}
			}
		}

		if (!override)
			return;

		this.players.remove(player);
		player.serverLevel().removePlayerImmediately(player, Entity.RemovalReason.DISCARDED);
		PlayerList list = (PlayerList) (Object) this;

		ServerLevel newLevel = level != null && optional.isPresent() ? level : this.server.overworld();
		ServerPlayer newPlayer = new ServerPlayer(this.server, newLevel, player.getGameProfile());
		newPlayer.connection = player.connection;
		newPlayer.restoreFrom(player, keep);
		newPlayer.setId(player.getId());
		newPlayer.setMainArm(player.getMainArm());

		for (String tag : player.getTags()) {
			newPlayer.addTag(tag);
		}

		boolean usedAnchorCharge = false;
		if (optional.isPresent()) {
			BlockState respawnState = newLevel.getBlockState(pos);
			boolean isAnchor = respawnState.is(Blocks.RESPAWN_ANCHOR) || respawnState.is(EnigmaticBlocks.END_ANCHOR);
			Vec3 vec3 = optional.get();
			float f1;
			if (!respawnState.is(BlockTags.BEDS) && !isAnchor) {
				f1 = angle;
			} else {
				Vec3 vec31 = Vec3.atBottomCenterOf(pos).subtract(vec3).normalize();
				f1 = (float) Mth.wrapDegrees(Mth.atan2(vec31.z, vec31.x) * (180F / (float) Math.PI) - 90.0D);
			}

			newPlayer.moveTo(vec3.x, vec3.y, vec3.z, f1, 0.0F);
			newPlayer.setRespawnPosition(newLevel.dimension(), pos, angle, forced, false);
			usedAnchorCharge = !keep && isAnchor && EndAnchor.useEndAnchor(newLevel, pos, respawnState);
		} else if (pos != null && !endRespawn) {
			newPlayer.connection.send(new ClientboundGameEventPacket(
					ClientboundGameEventPacket.NO_RESPAWN_BLOCK_AVAILABLE, 0.0F));
		} else if (pos != null && endRespawn) {
			newPlayer.setRespawnPosition(Level.END, pos, angle, forced, false);
		}

		while (!newLevel.noCollision(newPlayer) && newPlayer.getY() < newLevel.getMaxBuildHeight()) {
			newPlayer.setPos(newPlayer.getX(), newPlayer.getY() + 1.0D, newPlayer.getZ());
		}

		byte keepByte = (byte) (keep ? 1 : 0);
		LevelData leveldata = newPlayer.level().getLevelData();
		newPlayer.connection.send(new ClientboundRespawnPacket(newPlayer.level().dimensionTypeId(),
				newPlayer.level().dimension(), BiomeManager.obfuscateSeed(newPlayer.serverLevel().getSeed()),
				newPlayer.gameMode.getGameModeForPlayer(), newPlayer.gameMode.getPreviousGameModeForPlayer(),
				newPlayer.level().isDebug(), newPlayer.serverLevel().isFlat(), keepByte, newPlayer.getLastDeathLocation(),
				newPlayer.getPortalCooldown()));
		newPlayer.connection.teleport(newPlayer.getX(), newPlayer.getY(), newPlayer.getZ(), newPlayer.getYRot(),
				newPlayer.getXRot());
		newPlayer.connection.send(new ClientboundSetDefaultSpawnPositionPacket(newLevel.getSharedSpawnPos(),
				newLevel.getSharedSpawnAngle()));
		newPlayer.connection.send(new ClientboundChangeDifficultyPacket(leveldata.getDifficulty(),
				leveldata.isDifficultyLocked()));
		newPlayer.connection.send(new ClientboundSetExperiencePacket(newPlayer.experienceProgress,
				newPlayer.totalExperience, newPlayer.experienceLevel));
		list.sendLevelInfo(newPlayer, newLevel);
		list.sendPlayerPermissionLevel(newPlayer);
		newLevel.addRespawnedPlayer(newPlayer);
		this.players.add(newPlayer);
		this.playersByUUID.put(newPlayer.getUUID(), newPlayer);
		newPlayer.initInventoryMenu();
		newPlayer.setHealth(newPlayer.getHealth());
		net.minecraftforge.event.ForgeEventFactory.firePlayerRespawnEvent(newPlayer, keep);

		if (usedAnchorCharge && pos != null) {
			newPlayer.connection.send(new ClientboundSoundPacket(SoundEvents.RESPAWN_ANCHOR_DEPLETE, SoundSource.BLOCKS, pos.getX(), pos.getY(), pos.getZ(), 1.0F, 1.0F, newLevel.getRandom().nextLong()));
		}

		info.setReturnValue(newPlayer);
	}

@Override
	public void render(GuiGraphics graphics, ManualScreen gui, int x, int y, int mouseX, int mouseY)
	{
		if(multiblock.getStructure(level)!=null)
		{
			PoseStack transform = graphics.pose();
			PoseStack.Pose lastEntryBeforeTry = transform.last();
			try
			{
				long currentTime = System.currentTimeMillis();
				if(lastStep < 0)
					lastStep = currentTime;
				else if(canTick&&currentTime-lastStep > 500)
				{
					renderInfo.step();
					lastStep = currentTime;
				}

				int structureLength = renderInfo.structureLength;
				int structureWidth = renderInfo.structureWidth;
				int structureHeight = renderInfo.structureHeight;

				transform.pushPose();

				final BlockRenderDispatcher blockRender = Minecraft.getInstance().getBlockRenderer();

				transform.translate(transX, transY, Math.max(structureHeight, Math.max(structureWidth, structureLength)));
				transform.scale(scale, -scale, 1);
				transform.pushTransformation(additionalTransform);
				transform.mulPose(new Quaternionf().rotateXYZ(0, Mth.HALF_PI, 0));

				transform.translate(structureLength/-2f, structureHeight/-2f, structureWidth/-2f);

				if(showCompleted&&renderProperties.canRenderFormedStructure())
				{
					transform.pushPose();
					renderProperties.renderFormedStructure(transform, graphics.bufferSource());
					transform.popPose();
				}
				else
				{
					TransformingVertexBuilder translucentFullbright = new TransformingVertexBuilder(
							graphics.bufferSource(), IERenderTypes.TRANSLUCENT_FULLBRIGHT
					);
					for(int h = 0; h < structureHeight; h++)
						for(int l = 0; l < structureLength; l++)
							for(int w = 0; w < structureWidth; w++)
							{
								BlockPos pos = new BlockPos(l, h, w);
								BlockState state = structureWorld.getBlockState(pos);
								if(!state.isAir())
								{
									transform.pushPose();
									transform.translate(l, h, w);
									int overlay;
									if(pos.equals(multiblock.getTriggerOffset()))
										overlay = OverlayTexture.pack(0, true);
									else
										overlay = OverlayTexture.NO_OVERLAY;
									translucentFullbright.setDefaultOverlay(overlay);
									ModelData modelData = ModelData.EMPTY;
									BlockEntity te = structureWorld.getBlockEntity(pos);
									if(te!=null)
										modelData = te.getModelData();
									final BakedModel model = blockRender.getBlockModel(state);
									modelData = model.getModelData(structureWorld, pos, state, modelData);
									blockRender.getModelRenderer().tesselateBlock(
											structureWorld, model, state, pos, transform,
											translucentFullbright, false, structureWorld.random, state.getSeed(pos),
											overlay, modelData, null
									);
									transform.popPose();
								}
							}
				}
				transform.popPose();
				transform.popPose();
			} catch(Exception e)
			{
				final long now = System.currentTimeMillis();
				if(now > lastPrintedErrorTimeMs+1000)
				{
					e.printStackTrace();
					lastPrintedErrorTimeMs = now;
				}
				while(lastEntryBeforeTry!=transform.last())
					transform.popPose();
			}

			if(componentTooltip!=null)
			{
				graphics.drawString(manual.fontRenderer(), "?", 116, yOffTotal/2-4, manual.getTextColour());
				if(mouseX >= 116&&mouseX < 122&&mouseY >= yOffTotal/2-4&&mouseY < yOffTotal/2+4)
					graphics.renderTooltip(manual.fontRenderer(), Language.getInstance().getVisualOrder(
							Collections.unmodifiableList(componentTooltip)
					), mouseX, mouseY);
			}
		}
	}

@Override
	public void tick() {
		super.tick();

		if (level.isClientSide())
			return;

		BlockState state = getBlockState();
		if (turnOffTicks > 0) {
			turnOffTicks--;
			if (turnOffTicks == 0)
				level.scheduleTick(worldPosition, state.getBlock(), 1);
		}

		if (!isActive())
			return;

		BlockPos targetPos = worldPosition.relative(SmartObserverBlock.getTargetDirection(state));
		Block block = level.getBlockState(targetPos)
			.getBlock();

		if (!filtering.getFilter()
			.isEmpty() && block.asItem() != null) {
			ItemStack stack = new ItemStack(block);
			if (block instanceof ShulkerBoxBlock
				&& level.getBlockEntity(targetPos) instanceof ShulkerBoxBlockEntity shulkerBoxBlockEntity
				&& !shulkerBoxBlockEntity.isEmpty()) {
				stack.applyComponents(shulkerBoxBlockEntity.collectComponents());
			}
			if (filtering.test(stack)) {
				activate(3);
				return;
			}
		}

		// Detect items on belt
		TransportedItemStackHandlerBehaviour behaviour =
			BlockEntityBehaviour.get(level, targetPos, TransportedItemStackHandlerBehaviour.TYPE);
		if (behaviour != null) {
			behaviour.handleCenteredProcessingOnAllItems(.45f, stack -> {
				if (!filtering.test(stack.stack) || turnOffTicks == 6)
					return TransportedResult.doNothing();
				activate();
				return TransportedResult.doNothing();
			});
			return;
		}

		// Detect fluids in pipe
		FluidTransportBehaviour fluidBehaviour =
			BlockEntityBehaviour.get(level, targetPos, FluidTransportBehaviour.TYPE);
		if (fluidBehaviour != null) {
			for (Direction side : Iterate.directions) {
				Flow flow = fluidBehaviour.getFlow(side);
				if (flow == null || !flow.inbound || !flow.complete)
					continue;
				if (!filtering.test(flow.fluid))
					continue;
				activate();
				return;
			}
			return;
		}

		// Detect packages looping on a chain conveyor
		if (level.getBlockEntity(targetPos) instanceof ChainConveyorBlockEntity ccbe) {
			for (ChainConveyorPackage box : ccbe.getLoopingPackages())
				if (filtering.test(box.item)) {
					activate();
					return;
				}
			return;
		}

		if (observedInventory.hasInventory()) {
			boolean skipInv = invVersionTracker.stillWaiting(observedInventory);
			invVersionTracker.awaitNewVersion(observedInventory);

			if (skipInv && sustainSignal)
				turnOffTicks = DEFAULT_DELAY;

			if (!skipInv) {
				sustainSignal = false;
				if (!observedInventory.simulate()
					.extract()
					.isEmpty()) {
					sustainSignal = true;
					activate();
					return;
				}
			}
		}

		if (!observedTank.simulate()
			.extractAny()
			.isEmpty()) {
			activate();
			return;
		}
	}

@SubscribeEvent
    public void onTick(ClientTickEvent.Pre event) {
        if (minecraft.level == null || minecraft.player == null) {
            return;
        }
        RegistryAccess registryAccess = minecraft.level.registryAccess();
        boolean tickingNormally = MekanismRenderer.isRunningNormally();
        HolidayManager.notify(minecraft.player);

        //Reboot player sounds if needed
        SoundHandler.restartSounds();

        if (tickingNormally) {
            ClientRadiation.tickClient(minecraft.player);
        }

        UUID playerUUID = minecraft.player.getUUID();
        // Update player's state for various items; this also automatically notifies server if something changed and
        // kicks off sounds as necessary
        ItemAccess jetpack = IJetpackItem.getActiveJetpack(minecraft.player);
        boolean jetpackInUse = isJetpackInUse(minecraft.player, jetpack);
        Mekanism.playerState.setJetpackState(playerUUID, jetpackInUse, true);
        Mekanism.playerState.setScubaMaskState(playerUUID, isScubaMaskOn(minecraft.player), true);
        Mekanism.playerState.setGravitationalModulationState(playerUUID, isGravitationalModulationOn(minecraft.player), true);

        if (tickingNormally) {
            //Note: If we aren't ticking normally we can skip adding the particles or checking if the time matches as we know the time hasn't changed
            for (Iterator<Entry<Player, TeleportData>> iter = portableTeleports.entrySet().iterator(); iter.hasNext(); ) {
                Entry<Player, TeleportData> entry = iter.next();
                Player player = entry.getKey();
                for (int i = 0; i < 100; i++) {
                    double x = player.getX() + rand.nextDouble() - 0.5D;
                    double y = player.getY() + rand.nextDouble() * 2 - 2D;
                    double z = player.getZ() + rand.nextDouble() - 0.5D;
                    minecraft.level.addParticle(ParticleTypes.PORTAL, x, y, z, 0, 1, 0);
                }
                TeleportData data = entry.getValue();
                if (minecraft.level.getGameTime() == data.teleportTime) {
                    PacketUtils.sendToServer(new PacketPortableTeleporterTeleport(data.hand, data.identity));
                    iter.remove();
                }
            }
        }

        if (jetpack != null) {
            ItemResource primaryJetpack = IJetpackItem.getPrimaryJetpack(minecraft.player);
            if (!primaryJetpack.isEmpty()) {
                JetpackMode primaryMode = ((IJetpackItem) primaryJetpack.getItem()).getJetpackMode(primaryJetpack);
                JetpackMode mode = IJetpackItem.getPlayerJetpackMode(minecraft.player, primaryMode, p -> p.input.keyPresses.jump());
                MekanismClient.updateKey(minecraft.player.input.keyPresses.jump(), KeySync.ASCEND);
                try (Transaction simulation = Transaction.openRoot()) {
                    double jetpackThrust = ((IJetpackItem) jetpack.getResource().getItem()).useJetpackFuel(registryAccess, jetpack, primaryJetpack, simulation);
                    if (jetpackThrust > 0 && jetpackInUse && IJetpackItem.handleJetpackMotion(minecraft.player, mode, jetpackThrust, p -> p.input.keyPresses.jump())) {
                        minecraft.player.resetFallDistance();
                    }
                }
            }
        }

        if (isScubaMaskOn(minecraft.player) && minecraft.player.getAirSupply() == minecraft.player.getMaxAirSupply()) {
            for (MobEffectInstance effect : minecraft.player.getActiveEffects()) {
                if (MekanismUtils.shouldSpeedUpEffect(effect)) {
                    for (int i = 0; i < 9; i++) {
                        MekanismUtils.speedUpEffectSafely(minecraft.player, effect);
                    }
                }
            }
        }

        if (isVisionEnhancementOn(minecraft.player)) {
            visionEnhancement = true;
            // adds if it doesn't exist, otherwise tops off duration to 220. equal or less than 200 will make vision flickers
            minecraft.player.addEffect(new MobEffectInstance(MobEffects.NIGHT_VISION, 11 * SharedConstants.TICKS_PER_SECOND, 0, false, false, false));
        } else if (visionEnhancement) {
            visionEnhancement = false;
            MobEffectInstance effect = minecraft.player.getEffect(MobEffects.NIGHT_VISION);
            if (effect != null && effect.getDuration() <= 11 * SharedConstants.TICKS_PER_SECOND) {
                //Only remove it if it is our effect and not one that has a longer remaining duration
                minecraft.player.removeEffect(MobEffects.NIGHT_VISION);
            }
        }

        if (RadialConflictContext.INSTANCE.isActive()) {
            if (!MekKeyHandler.isRadialPressed() || (!updateSelectorRenderer(EquipmentSlot.MAINHAND) && !updateSelectorRenderer(EquipmentSlot.OFFHAND))) {
                if (minecraft.gui.screen() != null) {
                    //If we currently have a radial selector gui open but shouldn't close it
                    minecraft.gui.setScreen(null);
                }
            }
        }

        if (tickingNormally && MekanismConfig.client.enablePlayerSounds.get()) {
            RadiationScale scale = ClientRadiation.getClientScale();
            if (scale != RadiationScale.NONE && !SoundHandler.radiationSoundMap.containsKey(scale)) {
                GeigerSound sound = GeigerSound.create(minecraft.player, scale);
                SoundHandler.radiationSoundMap.put(scale, sound);
                SoundHandler.playSound(sound);
            }
        }
    }

public void tick() {
        super.tick();
        this.prevLatchProgress = latchProgress;
        if (this.isLatched() && latchProgress < 5F) {
            latchProgress++;
        }
        if (!this.isLatched() && latchProgress > 0F) {
            latchProgress--;
        }
        if (noLatchCooldown > 0) {
            noLatchCooldown--;
        }
        double d1 = (this.getX() - xo);
        double d2 = (this.getZ() - zo);
        double d3 = Math.sqrt(d1 * d1 + d2 * d2);
        if (isLatched() && verticalCollision && d3 > 0.1F) {
            if (tickCount - lastStepTimestamp > 6) {
                lastStepTimestamp = tickCount;
                BlockState state = level().getBlockState(BlockPos.containing(this.getX(), this.getBoundingBox().maxY + 0.5, this.getZ()));
                this.playSound(state.getSoundType().getStepSound(), 1F, 0.5F);
            }
        }
        if (!level().isClientSide) {
            if (this.isLatched() && !this.isUpsideDownNavigator) {
                switchNavigator(true);
            }
            if (!this.isLatched() && this.isUpsideDownNavigator) {
                switchNavigator(false);
            }
        }
        Entity head = getHead();
        if (head instanceof BoundroidEntity boundroid) {
            if (!level().isClientSide) {
                this.entityData.set(HEAD_ID, head.getId());
                double distance = this.distanceTo(boundroid);
                double distanceGoal = isLatched() ? 1.25F + Math.sin(tickCount * 0.1F) * 0.25F : 3.5F;
                boolean headNoClip = false;
                float pullSpeed = boundroid.getTarget() != null ? 0.3F : 0.1F;
                if (!boundroid.hasLineOfSight(this) && !boundroid.stopPullingUp() && distance > 7) {
                    headNoClip = true;
                }
                if (distance > distanceGoal && !boundroid.stopPullingUp()) {
                    double disRem = Math.min(distance - distanceGoal, 1F);
                    Vec3 moveTo = getChainFrom(1.0F).subtract(boundroid.position());
                    if (moveTo.length() > 1.0D) {
                        moveTo = moveTo.normalize();
                    }
                    boundroid.draggedClimable = true;
                    boundroid.setDeltaMovement(boundroid.getDeltaMovement().multiply(0.95F, 0.7F, 0.95F).add(moveTo.scale(disRem * pullSpeed)));
                } else {
                    boundroid.draggedClimable = false;
                }
                distanceToCeiling = calculateDistanceToCeiling();
                if (this.isLatched()) {
                    this.setNoGravity(true);
                    if (distanceToCeiling > MAX_DIST_TO_CEILING || !isAlive() || noLatchCooldown > 0) {
                        changeLatchStateTime++;
                    } else {
                        changeLatchStateTime = 0;
                    }
                    if (changeLatchStateTime > 5) {
                        this.setLatched(false);
                        if(noLatchCooldown > 0){
                            this.playSound(ACSoundRegistry.BOUNDROID_DAZED.get(), 2.0F, 1.0F);
                        }
                        changeLatchStateTime = 0;
                    }
                    this.setDeltaMovement(this.getDeltaMovement().add(0, 0.14, 0).scale(0.85F));
                    goingUp = false;
                    boundroid.stopGravity = true;
                } else {
                    this.setNoGravity(false);
                    boundroid.stopGravity = false;
                    if ((distanceToCeiling < MAX_DIST_TO_CEILING || verticalCollision && !verticalCollisionBelow) && noLatchCooldown <= 0) {
                        changeLatchStateTime++;
                    } else {
                        changeLatchStateTime = 0;
                    }
                    if (changeLatchStateTime > 5) {
                        this.setLatched(true);
                        changeLatchStateTime = 0;
                    }
                    if(goingUp && !hasBlockAbove()){
                        goingUp = false;
                    }
                    if (goingUp) {
                        this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, 1.5F, this.getDeltaMovement().z));
                    } else if (this.onGround() && noLatchCooldown == 0 && this.isAlive() && random.nextInt(30) == 0 && distanceToCeiling > MAX_DIST_TO_CEILING && hasBlockAbove()) {
                        goingUp = true;
                    }
                }
                boundroid.noPhysics = headNoClip;
            }
            if (boundroid.hurtTime > 0 || boundroid.deathTime > 0) {
                this.hurtTime = boundroid.hurtTime;
                this.deathTime = boundroid.deathTime;
            }
        } else if (!level().isClientSide) {
            this.remove(RemovalReason.KILLED);
        }
    }

public boolean place(FeaturePlaceContext<AetherLakeConfiguration> context) {
        BlockPos blockPos = context.origin();
        WorldGenLevel level = context.level();
        RandomSource random = context.random();
        AetherLakeConfiguration aetherLakeConfiguration = context.config();
        if (blockPos.getY() <= level.getMinBuildHeight() + 4) {
            return false;
        } else {
            blockPos = blockPos.below(4);
            boolean[] booleans = new boolean[2048];
            int i = random.nextInt(4) + 4;

            for (int j = 0; j < i; ++j) {
                double d0 = random.nextDouble() * 6.0 + 3.0;
                double d1 = random.nextDouble() * 4.0 + 2.0;
                double d2 = random.nextDouble() * 6.0 + 3.0;
                double d3 = random.nextDouble() * (16.0 - d0 - 2.0) + 1.0 + d0 / 2.0;
                double d4 = random.nextDouble() * (8.0 - d1 - 4.0) + 2.0 + d1 / 2.0;
                double d5 = random.nextDouble() * (16.0 - d2 - 2.0) + 1.0 + d2 / 2.0;

                for (int l = 1; l < 15; ++l) {
                    for (int i1 = 1; i1 < 15; ++i1) {
                        for (int j1 = 1; j1 < 7; ++j1) {
                            double d6 = ((double) l - d3) / (d0 / 2.0);
                            double d7 = ((double) j1 - d4) / (d1 / 2.0);
                            double d8 = ((double) i1 - d5) / (d2 / 2.0);
                            double d9 = d6 * d6 + d7 * d7 + d8 * d8;
                            if (d9 < 1.0) {
                                booleans[(l * 16 + i1) * 8 + j1] = true;
                            }
                        }
                    }
                }
            }

            BlockState fluidBlockState = aetherLakeConfiguration.fluid().getState(random, blockPos);

            for (int k1 = 0; k1 < 16; ++k1) {
                for (int k = 0; k < 16; ++k) {
                    for (int l2 = 0; l2 < 8; ++l2) {
                        boolean flag = !booleans[(k1 * 16 + k) * 8 + l2] && (k1 < 15 && booleans[((k1 + 1) * 16 + k) * 8 + l2] || k1 > 0 && booleans[((k1 - 1) * 16 + k) * 8 + l2] || k < 15 && booleans[(k1 * 16 + k + 1) * 8 + l2] || k > 0 && booleans[(k1 * 16 + (k - 1)) * 8 + l2] || l2 < 7 && booleans[(k1 * 16 + k) * 8 + l2 + 1] || l2 > 0 && booleans[(k1 * 16 + k) * 8 + (l2 - 1)]);
                        if (flag) {
                            BlockState offsetState = level.getBlockState(blockPos.offset(k1, l2, k));
                            if (l2 >= 4 && offsetState.liquid()) {
                                return false;
                            }
                            if (l2 < 4 && !offsetState.isSolid() && level.getBlockState(blockPos.offset(k1, l2, k)) != fluidBlockState) {
                                return false;
                            }
                        }
                    }
                }
            }

            for (int l1 = 0; l1 < 16; ++l1) {
                for (int i2 = 0; i2 < 16; ++i2) {
                    for (int i3 = 0; i3 < 8; ++i3) {
                        if (booleans[(l1 * 16 + i2) * 8 + i3]) {
                            BlockPos offsetPos = blockPos.offset(l1, i3, i2);
                            if (this.canReplaceBlock(level.getBlockState(offsetPos))) {
                                boolean flag1 = i3 >= 4;
                                level.setBlock(offsetPos, flag1 ? AIR : fluidBlockState, 2);
                                if (flag1) {
                                    level.scheduleTick(offsetPos, AIR.getBlock(), 0);
                                    this.markAboveForPostProcessing(level, offsetPos);
                                }
                            }
                        }
                    }
                }
            }

            BlockState topBlockState = aetherLakeConfiguration.top().getState(random, blockPos);
            if (!topBlockState.isAir()) {
                for (int i2 = 0; i2 < 16; ++i2) {
                    for (int j3 = 0; j3 < 16; ++j3) {
                        for (int j4 = 4; j4 < 8; ++j4) {
                            if (booleans[(i2 * 16 + j3) * 8 + j4]) {
                                BlockPos offsetPos = blockPos.offset(i2, j4 - 1, j3);
                                if (isDirt(level.getBlockState(offsetPos)) && level.getBrightness(LightLayer.SKY, blockPos.offset(i2, j4, j3)) > 0) {
                                    level.setBlock(offsetPos, topBlockState, 2);
                                }
                            }
                        }
                    }
                }
            }

            if (fluidBlockState.getFluidState().is(FluidTags.WATER)) {
                for (int k2 = 0; k2 < 16; ++k2) {
                    for (int k3 = 0; k3 < 16; ++k3) {
                        BlockPos offsetPos = blockPos.offset(k2, 4, k3);
                        if (level.getBiome(offsetPos).value().shouldFreeze(level, offsetPos, false) && this.canReplaceBlock(level.getBlockState(offsetPos))) {
                            level.setBlock(offsetPos, Blocks.ICE.defaultBlockState(), 2);
                        }
                    }
                }
            }

            return true;
        }
    }

@Override
    public void serverTick() {
        long currentTick = mob.level.getGameTime();
        if (mob.getVehicle() != null) {
            if (mob.getVehicle().getUUID().equals(loadedTarget)) {
                setLeapTarget((LivingEntity) mob.getVehicle());
                loadedTarget = null;
            } else if (target == null && isAttackRiding()) {
                mob.stopRiding();
                stopAttackRiding();
            }
        }
        if (!isLeaping() && target != null && target.isAlive()) {
            mob.lookAt(target, 100, 10);
            if (mob.distanceToSqr(target) < JUMP_DISTANCE) {
                startLeap();
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLeapStartAnimation();
                    jumpDelayTick = (long) (currentTick + animation.actionDelay);
                } else {
                    jumpDelayTick = currentTick + 2;
                }
                mob.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (!isLeaping() && blockTarget != null) {
            if (mob.distanceToSqr(blockTarget) < JUMP_DISTANCE) {
                startLeap();
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLeapStartAnimation();
                    jumpDelayTick = (long) (currentTick + animation.actionDelay);
                } else {
                    jumpDelayTick = currentTick + 2;
                }
                mob.setDeltaMovement(Vec3.ZERO);
            }
        }
        if (isLeaping()) {
            if (target == null && blockTarget == null) {
                stopLeap();
            }
            if (target != null && ((target.isVehicle() && mob.getVehicle() != target) || target.isDeadOrDying())) {
                if (jumpDelayTick != -1) {
                    blockTarget = target.position();
                }
                setAttackRiding(false);
                setLeapTarget(null);
            }
            if (currentTick == jumpDelayTick) {
                double y;
                Vec3 offset;
                if (target != null) {
                    y = Math.min(target.getY() + target.getBbHeight() - mob.getY(), 5);
                    offset = Util.directionVecTo(mob, target).normalize();
                    offset = offset.add(target.getDeltaMovement().x, 0, target.getDeltaMovement().z);
                } else if (blockTarget != null) {
                    y = Math.min(blockTarget.y - mob.getY(), 5);
                    offset = blockTarget.subtract(mob.position()).normalize();
                } else {
                    //Shouldn't really happen
                    y = 0;
                    offset = Vec3.ZERO;
                }
                mob.setDeltaMovement(offset.x, -0.027 * Math.pow(y, 2) + 0.262 * y + 0.183, offset.z);
                setLeapStarted(false);
                setLeapFlying(true);
                landingDelayTick = jumpDelayTick + 5;
                jumpDelayTick = -1;
            }
            if (mob.isOnGround() && landingDelayTick != -1 && landingDelayTick <= currentTick) {
                if (mob.hasLeapAnimation()) {
                    ServerAnimationInfo animation = (ServerAnimationInfo) mob.getLandAnimation();
                    landingEndTick = (long) (currentTick + animation.animation.animationLength);
                } else {
                    landingEndTick = currentTick + 2;
                }
                landingDelayTick = -1;
                setLeapFlying(false);
                setLanding(true);
            }
            if (landingEndTick != -1 && landingEndTick <= currentTick) {
                setLanding(false);
                setLeaping(false);
                landingEndTick = -1;
                setBlockLeapTarget(null);
                setLeapTarget(null);
            }
            if (isAttackRiding() && target != null) {
                if (mob.tickCount % 20 == 0) {
                    target.hurt(DamageSource.mobAttack(mob), (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    //target can be set to null during hurt
                }
                if (target != null && target.isDeadOrDying()) {
                    stopAttackRiding();
                }
            }
            if(!isLeapFlying() && !hasLeapStarted() && !isLanding() && !isAttackRiding()) {
                //failsafe
                setLeaping(false);
            }
            //Collision is handled in entity class
        }
    }

public static void performAttackAgainstTargets(ServerPlayerEntity player, AttackContext context, int[] targetIds) {
        var world = player.getWorld();
        var focusMode = focusMode();
        var attributeInstance = player.getAttributes().getCustomInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE);
        EntityAttributeModifier appliedDamageModifier = null;
        EntityAttributeModifier appliedDualWieldModifier = null;
        EntityAttributeModifier appliedChargeModifier = null;
        // Arrived from the client, so it is never trusted as-is.
        var curvedRatio = MathHelper.clamp(context.charge(), 0F, 1F);
        try {
            var lastAttackTime = ((LivingEntityAccessor)player).spellEngine_getLastAttackedTicks();
            var targets = new ArrayList<Entity>();
            var resolvedContext = resolveAttackData(player, world, context.spellId, context.attackId);
            var spellEntry = resolvedContext.spell();
            ((SpellCaster.Player)player).setActiveMeleeSkill(spellEntry);
            var attack = resolvedContext.attack();
            Sound impactSound = null;
            int impactSoundLimit = 0;
            var resolvedCharge = resolveCharge(spellEntry, curvedRatio);
            var charge = resolvedCharge.outputMultiplier();
            var modifiers = SpellModifiers.of(player, spellEntry, resolvedCharge.modifier());
            var damageMultiplierBase = 0F;
            for (var modifier : modifiers) {
                damageMultiplierBase += modifier.melee_damage_multiplier;
            }
            // Read before any temporary modifier lands, so it cannot inflate its own ratio. Kept as a
            // separate modifier rather than summed into the one below: `ADD_MULTIPLIED_TOTAL`
            // modifiers compose multiplicatively, so this way percentage bonuses scale the dual
            // wielded swing instead of the main hand one.
            var dualWieldBonus = dualWieldDamageBonus(player, spellEntry != null ? spellEntry.value() : null);
            if (dualWieldBonus != 0 && attributeInstance != null) {
                appliedDualWieldModifier = new EntityAttributeModifier(DUAL_WIELD_MODIFIER_ID, dualWieldBonus, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedDualWieldModifier);
            }
            // Melee skills land their damage through vanilla `player.attack(...)`, which the
            // `ImpactContext` never reaches, so a partial CHARGE release scales the swing here.
            // Kept separate for the same reason as the dual wield bonus: `ADD_MULTIPLIED_TOTAL`
            // modifiers compose multiplicatively, so the charge scales the whole swing rather
            // than being diluted by the flat bonuses below.
            if (charge != 1F && attributeInstance != null) {
                appliedChargeModifier = new EntityAttributeModifier(CHARGE_MODIFIER_ID, charge - 1F, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedChargeModifier);
            }
            if (attack != null && attributeInstance != null) {
                var damageModifierAmount = attack.damage_bonus + damageMultiplierBase;
                if (damageModifierAmount != 0) {
                    appliedDamageModifier = new EntityAttributeModifier(DAMAGE_MODIFIER_ID, damageModifierAmount, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                    attributeInstance.addTemporaryModifier(appliedDamageModifier);
                }
                impactSound = attack.impact_sound;
                impactSoundLimit = attack.impact_sound_cap > 0 ? attack.impact_sound_cap : 999;
            }
            var attackRange = spellEntry != null ? SpellParameters.getRangeCurved(player, spellEntry, curvedRatio) : (float)player.getEntityInteractionRange();

            for (int targetId : targetIds) {
                var target = world.getEntityById(targetId);
                if (target != null && target.isAttackable()) {
                    if (!EntityRelations.actionAllowed(
                            focusMode, SpellTarget.Intent.HARMFUL,
                            player, target)) {
                        continue;
                    }

                    var distanceGuard = (attackRange + largesSideLength(target.getBoundingBox())) * 1.2F; // Adding some tolerance
                    if (player.squaredDistanceTo(target) > (distanceGuard * distanceGuard) ) {
                        continue;
                    }

                    var timeUntilRegen = target.timeUntilRegen;
                    target.timeUntilRegen = 0;
                    ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(100);
                    player.attack(target);
                    if (impactSound != null && impactSoundLimit > 0) {
                        SoundHelper.playSound(target.getWorld(), target, impactSound);
                        impactSoundLimit -= 1;
                    }
                    targets.add(target);
                    target.timeUntilRegen = timeUntilRegen;
                }
            }

            if (!targets.isEmpty()) {
                var impactContext = new SpellExecution.ImpactContext()
                        .position(player.getPos())
                        .charge(curvedRatio)
                        .chargeModifier(resolvedCharge.modifier());
                SpellImpacts.meleeImpact(player, targets, spellEntry, impactContext);
            }
            ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(lastAttackTime);
        } catch (Exception e) {
            System.err.println("Failed to perform melee attack: " + e.getMessage());
        }
        if (appliedDamageModifier != null) {
            attributeInstance.removeModifier(appliedDamageModifier);
        }
        if (appliedDualWieldModifier != null) {
            attributeInstance.removeModifier(appliedDualWieldModifier);
        }
        if (appliedChargeModifier != null) {
            attributeInstance.removeModifier(appliedChargeModifier);
        }
        ((SpellCaster.Player)player).setActiveMeleeSkill(null);
    }

protected void dropSelfWithContents(Collection<? extends DeferredHolder<Block, ?>> blockProviders) {
        //TODO: See if there is other stuff we want to be transferring which we currently do not
        // For example, when writing this we added dump mode for chemical tanks to getting transferred to the item
        for (DeferredHolder<Block, ?> blockProvider : blockProviders) {
            if (skipBlock(blockProvider)) {
                continue;
            }
            Block block = blockProvider.value();
            boolean hasComponents = false;
            CopyComponentsFunction.Builder componentsBuilder = CopyComponentsFunction.copyComponentsFromBlockEntity(BlockEntityTarget.BLOCK_ENTITY.contextParam());
            boolean hasContents = false;
            Item blockItem = block.asItem();
            LootItem.Builder<?> itemLootPool = LootItem.lootTableItem(block);
            //delayed items until after other copies are added, for cases like referencing the owner
            DelayedLootItemBuilder delayedPool = new DelayedLootItemBuilder();
            BlockEntity tile = null;
            if (block instanceof EntityBlock entityBlock) {
                tile = entityBlock.newBlockEntity(BlockPos.ZERO, block.defaultBlockState());
            }
            if (tile instanceof IFrequencyHandler frequencyHandler) {
                Set<FrequencyType<?>> customFrequencies = frequencyHandler.getFrequencyComponent().getCustomFrequencies();
                if (!customFrequencies.isEmpty() && blockItem instanceof IFrequencyItem frequencyItem) {
                    FrequencyType<?> frequencyType = frequencyItem.getFrequencyType();
                    if (!customFrequencies.contains(frequencyType)) {
                        Mekanism.logger.warn("Block missing frequency type '{}' expected by item: {}", frequencyType.getName(), blockProvider.getId());
                    }
                }
            }
            if (tile instanceof TileEntityUpdateable tileEntity) {
                List<DataComponentType<?>> components = tileEntity.getRemapEntries();
                if (!components.isEmpty()) {
                    Set<DataComponentType<?>> skipTypes = ContainerType.TYPES.stream().map(type -> type.getComponentType().get()).collect(Collectors.toSet());
                    hasComponents = true;
                    //Sort the components so that the order is consistent when writing to json
                    components.sort(Comparator.comparing(BuiltInRegistries.DATA_COMPONENT_TYPE::getKey, Identifier::compareNamespaced));
                    for (DataComponentType<?> remapEntry : components) {
                        //Allow containers to be handled below where we do extra validation that the stack actually supports it
                        if (!skipTypes.contains(remapEntry)) {
                            componentsBuilder.include(remapEntry);
                        }
                    }
                }
            }
            if (tile instanceof TileEntityMekanism tileEntity) {
                if (tileEntity.isNameable()) {
                    itemLootPool.apply(CopyNameFunction.copyName(BlockEntityTarget.BLOCK_ENTITY));
                }
                for (IContainerType<?, ?> type : ContainerType.TYPES) {
                    int containers = 0;
                    if (tileEntity.persists(type)) {
                        if (type instanceof IListContainerType<?, ?, ?> listType) {
                            containers = listType.getContainers(tileEntity).size();
                        } else if (type instanceof ISingleContainerType<?, ?> singleType && singleType.getContainer(tileEntity) != null) {
                            containers = 1;
                        }
                    }
                    int attachmentContainers = type.getContainerCount(blockItem);
                    if (containers == attachmentContainers) {
                        if (containers > 0) {
                            componentsBuilder.include(type.getComponentType().get());
                            hasComponents = true;
                            if (type != ContainerType.ENERGY && type != ContainerType.HEAT) {
                                hasContents = true;
                            }
                        }
                    } else if (attachmentContainers == 0) {
                        //TODO: Improve how we handle skipping warnings for known missing types
                        if (type == ContainerType.ITEM && block instanceof BlockPersonalStorage<?, ?>) {
                            //We don't want explosions causing personal storage items to be directly destroyed. It is also known that the attachment is missing
                            hasContents = true;
                        } else if (type != ContainerType.CHEMICAL || !MekanismBlocks.RADIOACTIVE_WASTE_BARREL.keyMatches(blockProvider)) {
                            Mekanism.logger.warn("Container type: {}, item missing attachments: {}", type.getComponentName(), blockProvider.getId());
                        }
                    } else if (containers == 0) {
                        Mekanism.logger.warn("Container type: {}, item has attachments but block doesn't have containers: {}", type.getComponentName(), blockProvider.getId());
                    } else {
                        Mekanism.logger.warn("Container type: {}, has {} item attachments and block has {} containers: {}", type.getComponentName(), attachmentContainers,
                              containers, blockProvider.getId());
                    }
                }
            }
            @SuppressWarnings("unchecked")
            AttributeInventory<DelayedLootItemBuilder> attributeInventory = Attribute.get(blockProvider, AttributeInventory.class);
            if (attributeInventory != null) {
                hasContents |= attributeInventory.applyLoot(delayedPool);
            }
            if (hasComponents) {
                itemLootPool.apply(componentsBuilder);
            }
            //apply the delayed ones last, so that NBT funcs have happened first
            for (Holder<LootItemFunction> function : delayedPool.functions) {
                itemLootPool.apply(function);
            }
            for (Holder<LootItemCondition> condition : delayedPool.conditions) {
                itemLootPool.when(condition);
            }
            add(block, LootTable.lootTable().withPool(applyExplosionCondition(hasContents, LootPool.lootPool()
                  .name("main")
                  .setRolls(ContextIntProviders.exactly(1))
                  .add(itemLootPool)
            )));
        }
    }

