@Override
    public InteractionResult useOn(UseOnContext context) {
        Player player = context.getPlayer();
        Level world = context.getLevel();
        if (player == null) {
            return InteractionResult.PASS;
        }
        BlockPos pos = context.getClickedPos();
        BlockState state = world.getBlockState(pos);
        if (state.is(MekanismBlocks.BOUNDING_BLOCK)) {
            BlockPos mainPos = BlockBounding.getMainBlockPos(world, pos);
            if (mainPos != null) {
                //If we are a bounding block with a main pos, update to pretend we interacted with the logic block
                pos = mainPos;
                state = world.getBlockState(mainPos);
            }
        }
        if (!IBlockSecurityUtils.INSTANCE.canAccessOrDisplayError(player, world, pos) || state.is(MekanismAPITags.Blocks.BLACKLIST_INSTALLER_UPGRADEABLE)) {
            return InteractionResult.FAIL;
        } else if (world.isClientSide()) {
            return InteractionResult.PASS;
        }
        Block block = state.getBlock();
        AttributeUpgradeable upgradeableBlock = Attribute.get(block, AttributeUpgradeable.class);
        if (upgradeableBlock != null) {
            BaseTier baseTier = Attribute.getBaseTier(block);
            if (baseTier == fromTier && baseTier != toTier) {
                BlockState upgradeState = upgradeableBlock.upgradeResult(state, toTier);
                if (state == upgradeState) {
                    return InteractionResult.PASS;
                }
                BlockEntity tile = WorldUtils.getTileEntity(world, pos);
                if (tile instanceof ITierUpgradable tierUpgradable) {
                    if (tile instanceof TileEntityMekanism tileMek && !tileMek.playersUsing.isEmpty()) {
                        return InteractionResult.FAIL;
                    }
                    IUpgradeData upgradeData = tierUpgradable.getUpgradeData(world.registryAccess());
                    if (upgradeData == null) {
                        if (tierUpgradable.canBeUpgraded()) {
                            Mekanism.logger.warn("Got no upgrade data for block {} at position: {} in {} but it said it would be able to provide some.", block, pos, world.dimension().identifier());
                            return InteractionResult.FAIL;
                        }
                    } else {
                        AttributeHasBounding upgradeBounding = Attribute.get(upgradeState, AttributeHasBounding.class);
                        //If the resulting block has bounding blocks, validate that all of them will be able to be placed
                        if (upgradeBounding != null && !upgradeBounding.handle(world, pos, upgradeState, pos, (Level level, BlockPos boundingPos, BlockPos mainPos) -> {
                            Optional<BlockState> blockState = WorldUtils.getBlockState(level, boundingPos);
                            if (blockState.isPresent()) {
                                BlockState boundingCurrentState = blockState.get();
                                if (boundingCurrentState.canBeReplaced()) {
                                    return true;
                                } else if (boundingCurrentState.is(MekanismBlocks.BOUNDING_BLOCK)) {
                                    //Treat bounding blocks that will be removed because they are actually part of the unupgraded multiblock as valid
                                    // for us to put a new bounding block in
                                    return mainPos.equals(BlockBounding.getMainBlockPos(level, boundingPos));
                                }
                            }
                            return false;
                        })) {
                            //At least one bounding block we would be adding can't be placed. Error out instead of upgrading the block
                            return InteractionResult.FAIL;
                        }
                        //Update the block
                        if (!world.setBlockAndUpdate(pos, upgradeState)) {
                            //Something went wrong, bail rather than trying to
                            Mekanism.logger.warn("Error upgrading block at position: {} in {}.", pos, world.dimension().identifier());
                            return InteractionResult.FAIL;
                        }
                        //Place any bounding blocks the new state may have
                        if (upgradeBounding != null) {
                            upgradeBounding.placeBoundingBlocks(world, pos, upgradeState);
                        }
                        TileEntityMekanism upgradedTile = WorldUtils.getTileEntity(TileEntityMekanism.class, world, pos);
                        if (upgradedTile == null) {
                            Mekanism.logger.warn("Error upgrading block at position: {} in {}. Expected a mekanism block as the result.", pos, world.dimension().identifier());
                            return InteractionResult.FAIL;
                        }
                        //TODO: Make it so it doesn't have to be a TileEntityMekanism in order to do these things?
                        if (tile instanceof ITileDirectional directional && directional.isDirectional()) {
                            upgradedTile.setFacing(directional.getDirection(), false);
                        }
                        try (Transaction transaction = TransactionHelper.openTransactionSafe()) {
                            upgradedTile.parseUpgradeData(upgradeData, world.registryAccess(), transaction);
                            transaction.commit();
                        }
                        upgradedTile.resyncMasterToBounding();
                        upgradedTile.sendUpdatePacket();
                        upgradedTile.setChanged();
                        //Notify the level that the caps at the position are no longer valid
                        // In general replacing the tile likely will have caused this to be invalidated
                        // but mark it just to be safe, and in case there are any bounding blocks so that they notify the level their caps might have changed
                        upgradedTile.invalidateCapabilitiesFull();
                        context.getItemInHand().consume(1, player);
                        if (player instanceof ServerPlayer serverPlayer) {
                            MekanismCriteriaTriggers.USE_TIER_INSTALLER.value().trigger(serverPlayer, toTier);
                        }
                        return InteractionResult.CONSUME;
                    }
                }
            }
        }
        return InteractionResult.PASS;
    }

private void tickRequests() {
		FactoryPanelBlockEntity panelBE = panelBE();
		if (targetedBy.isEmpty() && !panelBE.restocker)
			return;
		if (panelBE.restocker)
			restockerPromises.tick();
		if (satisfied || promisedSatisfied || waitingForNetwork || redstonePowered)
			return;
		if (timer > 0) {
			timer = Math.min(timer, getConfigRequestIntervalInTicks());
			timer--;
			return;
		}

		resetTimer();

		if (recipeAddress.isBlank())
			return;

		if (panelBE.restocker) {
			tryRestock();
			return;
		}

		boolean failed = false;

		Map<UUID, Map<ItemStack, ItemStackConnections>> consolidated = new HashMap<>();

		for (FactoryPanelConnection connection : targetedBy.values()) {
			FactoryPanelBehaviour source = at(getWorld(), connection);
			if (source == null)
				return;

			ItemStack item = source.getFilter();


			Map<ItemStack, ItemStackConnections> networkItemCounts = consolidated.computeIfAbsent(source.network, $ -> new Object2ObjectOpenCustomHashMap<>(ItemStackLinkedSet.TYPE_AND_TAG));
			networkItemCounts.computeIfAbsent(item, $ -> new ItemStackConnections(item));
			ItemStackConnections existingConnections = networkItemCounts.get(item);
			existingConnections.add(connection);
			existingConnections.totalAmount += connection.amount;
		}

		Multimap<UUID, BigItemStack> toRequest = HashMultimap.create();

		for (Entry<UUID, Map<ItemStack, ItemStackConnections>> entry : consolidated.entrySet()) {
			UUID network = entry.getKey();
			InventorySummary summary = LogisticsManager.getSummaryOfNetwork(network, true);

			for (ItemStackConnections connections : entry.getValue().values()) {
				if (connections.totalAmount == 0 || connections.item.isEmpty() || summary.getCountOf(connections.item) < connections.totalAmount) {
					for (FactoryPanelConnection connection : connections)
						sendEffect(connection.from, false);
					failed = true;
					continue;
				}

				BigItemStack stack = new BigItemStack(connections.item, connections.totalAmount);
				toRequest.put(network, stack);
				for (FactoryPanelConnection connection : connections)
					sendEffect(connection.from, true);
			}
		}

		if (failed)
			return;

		// Input items may come from differing networks
		Map<UUID, Collection<BigItemStack>> asMap = toRequest.asMap();
		PackageOrderWithCrafts craftingContext = PackageOrderWithCrafts.empty();
		List<Multimap<PackagerBlockEntity, PackagingRequest>> requests = new ArrayList<>();

		// Panel may enforce item arrangement
		if (!activeCraftingArrangement.isEmpty())
			craftingContext = PackageOrderWithCrafts.singleRecipe(activeCraftingArrangement.stream()
				.map(stack -> new BigItemStack(stack.copyWithCount(1)))
				.toList());

		// Collect request distributions
		for (Entry<UUID, Collection<BigItemStack>> entry : asMap.entrySet()) {
			PackageOrderWithCrafts order =
				new PackageOrderWithCrafts(new PackageOrder(new ArrayList<>(entry.getValue())), craftingContext.orderedCrafts());
			Multimap<PackagerBlockEntity, PackagingRequest> request =
				LogisticsManager.findPackagersForRequest(entry.getKey(), order, null, recipeAddress);
			requests.add(request);
		}

		// Check if any packager is busy - cancel all
		for (Multimap<PackagerBlockEntity, PackagingRequest> entry : requests)
			for (PackagerBlockEntity packager : entry.keySet())
				if (packager.isTooBusyFor(RequestType.RESTOCK))
					return;

		// Send it
		for (Multimap<PackagerBlockEntity, PackagingRequest> entry : requests)
			LogisticsManager.performPackageRequests(entry);

		// Keep the output promise
		RequestPromiseQueue promises = Create.LOGISTICS.getQueuedPromises(network);
		if (promises != null)
			promises.add(new RequestPromise(new BigItemStack(getFilter(), recipeOutput)));

		panelBE.advancements.awardPlayer(AllAdvancements.FACTORY_GAUGE);
	}

private void renderParticle(@Nonnull VertexConsumer buffer, TileParticle particle, Camera camera,
                                float partialTicks, @Nullable ModelPass model) {
        var vec3 = camera.getPosition();

        var localPos = particle.getSimPos(partialTicks).mulPosition(particle.getSpaceTransform());
        var x = (float) (localPos.x - vec3.x);
        var y = (float) (localPos.y - vec3.y);
        var z = (float) (localPos.z - vec3.z);

        var color = particle.getRealColor(partialTicks);
        var r = color.x();
        var g = color.y();
        var b = color.z();
        var a = color.w();

        var light = particle.getRealLight(partialTicks);

        var rotation = particle.getRealRotation(partialTicks);
        var renderMode = renderer.getRenderMode();

        var size = particle.getRealSize(partialTicks);

        if (model != null) { // non-null exactly in Model mode; see renderQueue
            // mesh positions are already in centered model space (PhotonMesh convention)
            var transform = new Matrix4f().translate(x, y, z)
                    .rotate(computeModelQuaternion(particle, rotation, camera, partialTicks))
                    .scale(size.mul(particle.getSpaceScale()));
            var mesh = model.mesh();
            // ⚠️ A baked pose table is not only the instanced path's business: GPU instancing is off by
            // default, and without this a per-particle-phase model drew its rest pose and never moved.
            int poseBase = poseBaseFor(model.animation(), particle, partialTicks);
            var table = poseBase < 0 ? null : model.table();
            // the normal matrix depends on the particle, not the face — it used to be rebuilt per quad
            var normalMat = transform.normal(new Matrix3f());
            var indices = mesh.indices();
            int triangle = 0;
            while (triangle < mesh.triangleCount()) {
                int i = triangle * 3;
                int va = indices[i], vb = indices[i + 1], vc = indices[i + 2];
                // ⚠️ a QUADS-mode buffer, so four vertices a primitive: an authored quad goes out
                // whole (its second triangle is (c, d, a)), a lone triangle repeats its last corner
                if (mesh.quadPaired(triangle)) {
                    int vd = indices[i + 4];
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, va, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vb, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vc, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vd, r, g, b, a, light);
                    triangle += 2;
                } else {
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, va, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vb, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vc, r, g, b, a, light);
                    putMeshVertex(transform, normalMat, buffer, model, table, poseBase, vc, r, g, b, a, light);
                    triangle++;
                }
            }
        } else {
            Quaternionf quaternion;
            float finalSizeX = size.x;
            float finalSizeY = size.y;
            float finalSizeZ = size.z;
            var spaceScale = particle.getSpaceScale();

            if (renderMode == ParticleRendererSetting.Mode.StretchedBillboard) {
                var frame = computeStretchedFrame(particle, localPos, vec3.x, vec3.y, vec3.z, size, spaceScale);
                quaternion = frame.rotation;
                finalSizeX = frame.stretchedSizeX;
                x -= frame.offsetX;
                y -= frame.offsetY;
                z -= frame.offsetZ;
            } else {
                quaternion = computeBillboardQuaternion(particle, renderMode, camera, partialTicks, rotation);
            }

            var rawVertexes = new Vector3f[]{
                    new Vector3f(1.0F, -1.0F, 0.0F),
                    new Vector3f(1.0F, 1.0F, 0.0F),
                    new Vector3f(-1.0F, 1.0F, 0.0F),
                    new Vector3f(-1.0F, -1.0F, 0.0F),
            };
            var normal = new Vector3f(0, 0, 1);

            for (var i = 0; i < 4; ++i) {
                var vertex = rawVertexes[i];
                vertex.mul(finalSizeX, finalSizeY, finalSizeZ);
                vertex = quaternion.transform(vertex);
                vertex.mul(spaceScale);
                vertex.add(x, y, z);
            }

            normal = quaternion.transform(normal);

            var uvs = particle.getRealUVs(partialTicks);
            var u0 = uvs.x();
            var v0 = uvs.y();
            var u1 = uvs.z();
            var v1 = uvs.w();

            buffer.addVertex(rawVertexes[0].x(), rawVertexes[0].y(), rawVertexes[0].z()).setUv(u1, v1).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
            buffer.addVertex(rawVertexes[1].x(), rawVertexes[1].y(), rawVertexes[1].z()).setUv(u1, v0).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
            buffer.addVertex(rawVertexes[2].x(), rawVertexes[2].y(), rawVertexes[2].z()).setUv(u0, v0).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
            buffer.addVertex(rawVertexes[3].x(), rawVertexes[3].y(), rawVertexes[3].z()).setUv(u0, v1).setColor(r, g, b, a).setLight(light).setNormal(normal.x, normal.y, normal.z);
        }
    }

private PumpQueue buildPumpQueue(Level level, BlockPos headPos, FluidType fluidType, int queueSourceAmount,
                                     boolean upSources) {
        Set<BlockPos> checked = new ObjectOpenHashSet<>();

        BlockPos headPosBelow = headPos.below();

        checked.add(headPos);
        checked.add(headPosBelow);

        int maxPumpRange = getMaxPumpRadius(getTier());

        List<BlockPos> pathStack = new ArrayList<>();

        Deque<BlockPos> nonSources = new ArrayDeque<>();
        Deque<BlockPos> pathToLastSource = new ArrayDeque<>();
        Deque<BlockPos> sourceStack = new ArrayDeque<>();

        pathStack.add(headPosBelow);
        nonSources.add(headPosBelow);

        int iterations = 0;
        int previousSources = 0;
        Queue<Deque<BlockPos>> paths = new ArrayDeque<>();
        List<BlockPos> sources = new ArrayList<>();
        // We do at most 1000 iterations to try and find source blocks
        while (!pathStack.isEmpty() && iterations < 1000) {
            // Peeks at the tail
            BlockPos searchHead = pathStack.get(pathStack.size() - 1);

            SearchResult next = searchNext(level, headPosBelow, searchHead, fluidType, maxPumpRange, upSources,
                    checked);

            iterations++;

            if (next == null) {
                boolean continueSearch = sources.size() < queueSourceAmount;

                int addedSources = sources.size() - previousSources;
                previousSources = sources.size();
                if (addedSources > 0) {
                    var toAdd = new ArrayDeque<>(pathToLastSource);
                    // This is always the headPosBelow, which we do not want to include
                    toAdd.removeFirst();
                    paths.add(toAdd);
                }

                if (!continueSearch) {
                    return new PumpQueue(paths, fluidType);
                }

                // Now we need to rewind our stack
                BlockPos last = pathStack.remove(pathStack.size() - 1);
                BlockPos lastSource = sourceStack.peekLast();
                if (last.equals(lastSource)) {
                    BlockPos prevSource = sourceStack.removeLast();
                    // Rebuild nonSources until previous source
                    for (int i = pathStack.size() - 1; i >= 0; i--) {
                        BlockPos p = pathStack.get(i);
                        if (!p.equals(prevSource)) {
                            nonSources.addFirst(p);
                        } else {
                            break;
                        }
                    }
                    // If the last is a source, then nonSources will be empty regardless
                } else if (!nonSources.isEmpty()) {
                    nonSources.removeLast();
                }
            } else {
                // Add the next
                pathStack.add(next.pos());
                // If we are in search up mode, we only count it as a source if it's up
                if (next.isSource() && (!upSources || next.pos().getY() > headPosBelow.getY())) {
                    sources.add(next.pos());
                    // Found a source, so add all the non-source blocks we passed since the last one
                    pathToLastSource.addAll(nonSources);
                    // Also add the source itself
                    pathToLastSource.add(next.pos());
                    // Reset non-sources because we just added them and found a source
                    nonSources.clear();
                    sources.add(next.pos());
                } else {
                    // Not a source, but we want to track it
                    nonSources.add(next.pos());
                }

            }
        }
        if (upSources) {
            // If we found none, we try again without the restriction
            if (paths.isEmpty()) {
                return buildPumpQueue(level, headPos, fluidType, queueSourceAmount, false);
            }

            return new PumpQueue(paths, fluidType);
        }

        // Only after everything except the block directly below the pipe is pumped, do we want to pump it
        // Otherwise we might advance the pump head prematurely
        if (paths.isEmpty() && level.getBlockState(headPosBelow).getFluidState().isSource()) {
            return new PumpQueue(new ArrayDeque<>(List.of(new ArrayDeque<>(List.of(headPosBelow)))), fluidType);
        }

        return new PumpQueue(paths, fluidType);
    }

@Override
    public void onUpdate() {
        if(this.shootingEntity != null || this.summoningPedestal != null) {
			this.projectileLife = 5;
		}
        super.onUpdate();

        // ==========Summoning Pedestal ==========
        if(!this.getEntityWorld().isRemote) {
            if(this.summoningPedestal != null) {
                this.shootingEntity = this.summoningPedestal.getPlayer();
                this.summonClass = this.summoningPedestal.getSummonClass();
            }
        }

        // ==========Sync Shooter Name ==========
        if(!this.getEntityWorld().isRemote) {
            // Summoning Staff or Summoning Pedestal (with active player):
            if(this.shootingEntity != null)
                this.dataManager.set(OWNER_NAME, this.shootingEntity.getName());
            // Summoning Pedestal:
            else if(this.summoningPedestal != null)
                this.dataManager.set(OWNER_NAME, this.summoningPedestal.getOwnerName());
            // Wild:
            else
                this.dataManager.set(OWNER_NAME, "");
        }
        else {
            this.ownerName = this.dataManager.get(OWNER_NAME);
        }

    	// ========== Check for Despawn ==========
    	if(!this.getEntityWorld().isRemote && !this.isDead) {
            // Summoning Pedestal:
            if(this.summoningPedestal != null) {
                if(this.summonClass == null) {
                    this.setDead();
                    return;
                }
            }

            // Summoning Staff:
            else {
                if(this.shootingEntity == null || !this.shootingEntity.isEntityAlive() || this.portalItem == null) {
                    this.setDead();
                    return;
                }
                ExtendedPlayer playerExt = ExtendedPlayer.getForPlayer(this.shootingEntity);
				if(playerExt != null && playerExt.staffPortal != this) {
					this.setDead();
					return;
				}
            }
    	}
    	
    	// ========== Move ==========
    	this.moveToTarget();

        // ========== Stat Sync ==========
        // Summoning Staff:
        if(this.shootingEntity != null && this.summoningPedestal == null) {
            ExtendedPlayer playerExt = ExtendedPlayer.getForPlayer(this.shootingEntity);
            if(playerExt != null && this.portalItem != null) {
                if(++this.summonTick >= this.portalItem.getRapidTime(null)) {
                    this.summonDuration = this.portalItem.getSummonDuration();
                    if(this.shootingEntity.capabilities.isCreativeMode)
                        this.summonAmount += this.portalItem.getSummonAmount();
                    else {
                        float summonMultiplier = (float) (CreatureManager.getInstance().getCreature(this.summonClass).summonCost + this.portalItem.getSummonCostBoost()) * this.portalItem.getSummonCostMod();
                        int summonCost = Math.round((float) playerExt.summonFocusCharge * summonMultiplier);
                        if(playerExt.summonFocus >= summonCost) {
                            if(this.portalItem.getAdditionalCosts(this.shootingEntity)) {
                                playerExt.summonFocus -= summonCost;
                                this.summonAmount += this.portalItem.getSummonAmount();
                            }
                        }
                    }
                    this.summonTick = 0;
                }
            }
        }

        // Summoning Pedestal:
        else if(this.summonClass != null) {
            if (++this.summonTick >= this.summonTime) {
                this.summonAmount = this.summoningPedestal.summonAmount;
                this.summonTick = 0;
            }
        }

        // ========== Client ==========
        if(this.getEntityWorld().isRemote) {
            for(int i = 0; i < 32; ++i) {
                double angle = Math.toRadians(this.rand.nextFloat() * 360);
                float distance = this.rand.nextFloat() * 2;
                double x = distance * Math.cos(angle) + Math.sin(angle);
                double z = distance * Math.sin(angle) - Math.cos(angle);
                this.getEntityWorld().spawnParticle(EnumParticleTypes.PORTAL,
                        this.posX + x,
                        this.posY + (4.0F * this.rand.nextFloat()) - 2.0F,
                        this.posZ + z,
                        0.0D, 0.0D, 0.0D);
            }
            return;
        }
    }

@Override
    protected void onHitEntity(EntityHitResult raytrace) {
        Entity target = raytrace.getEntity();
        Entity shooter = getOwner();
        Player playerShooter = CastOptional.cast(shooter, Player.class).orElse(null);

        DamageSource damagesource = level().damageSources().trident(this, (shooter == null ? this : shooter));
        SoundEvent soundevent = SoundEvents.TRIDENT_HIT;

        int pierceLevel = getEffectLevel(ItemEffect.piercing);
        int ricochetLevel = getEffectLevel(ItemEffect.ricochet);

        if (pierceLevel > 0 || ricochetLevel > 0) {
            if (hitEntities == null) {
                hitEntities = new IntOpenHashSet(5);
            }

            if (hitEntities.contains(target.getId())) {
                return;
            }

            if (hitEntities.size() < pierceLevel || hitEntities.size() < ricochetLevel) {
                hitEntities.add(target.getId());
            } else {
                dealtDamage = true;
            }
        } else {
            dealtDamage = true;
        }

        ItemStack heldTemp = null;
        if (playerShooter != null) {
            heldTemp = playerShooter.getMainHandItem();
            playerShooter.setItemInHand(InteractionHand.MAIN_HAND, thrownStack);
        }

        if (target instanceof LivingEntity && thrownStack.getItem() instanceof ItemModularHandheld) {
            LivingEntity targetLivingEntity = (LivingEntity) target;
            ItemModularHandheld item = (ItemModularHandheld) thrownStack.getItem();

            double abilityDamage = item.getAbilityBaseDamage(shooter instanceof LivingEntity living ? living : null, thrownStack);

            double critModifier = CritEffect.rollMultiplier(targetLivingEntity.getRandom(), item, thrownStack);
            double damage = abilityDamage * item.getEffectEfficiency(thrownStack, ItemEffect.throwable);

            damage += EnchantmentHelper.getDamageBonus(thrownStack, targetLivingEntity.getMobType());
            damage *= critModifier;

            if (target.hurt(damagesource, (float) damage)) {
                if (shooter instanceof LivingEntity livingShooter) {
                    EnchantmentHelper.doPostHurtEffects(targetLivingEntity, shooter);
                    EffectHelper.applyEnchantmentHitEffects(getPickupItem(), targetLivingEntity, livingShooter);
                    ItemEffectHandler.applyHitEffects(thrownStack, targetLivingEntity, livingShooter);

                    item.tickProgression(livingShooter, thrownStack, 1);
                }

                doPostHurtEffects(targetLivingEntity);

                if (critModifier != 1d && !level().isClientSide) {
                    Vec3 hitVec = raytrace.getLocation();
                    ((ServerLevel) level()).sendParticles(ParticleTypes.ENCHANTED_HIT,
                            hitVec.x(), hitVec.y(), hitVec.z(), 15, 0.2D, 0.2D, 0.2D, 0.0D);
                }
            }
        }

        float f1 = 1.0F;
        if (!level().isClientSide && level().isThundering() && EnchantmentHelper.hasChanneling(thrownStack)) {
            BlockPos blockpos = target.blockPosition();
            if (level().canSeeSky(blockpos)) {
                LightningBolt lightning = EntityType.LIGHTNING_BOLT.create(this.level());
                lightning.moveTo(Vec3.atBottomCenterOf(blockpos));
                lightning.setCause(shooter instanceof ServerPlayer ? (ServerPlayer) shooter : null);
                this.level().addFreshEntity(lightning);
                soundevent = SoundEvents.TRIDENT_THUNDER;
                f1 = 5.0F;
            }
        }

        if (playerShooter != null) {
            playerShooter.setItemInHand(InteractionHand.MAIN_HAND, heldTemp);
        }

        playSound(soundevent, f1, 1.0F);

        if (dealtDamage) {
            setDeltaMovement(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D));
        } else if (ricochetLevel > 0 && !level().isClientSide) {
            Vec3 hitPos = raytrace.getLocation();
            setPosRaw(hitPos.x(), hitPos.y(), hitPos.z());
            setDeltaMovement(level().getEntities(shooter, new AABB(target.blockPosition()).inflate(8d), entity ->
                            !hitEntities.contains(entity.getId())
                                    && entity instanceof LivingEntity
                                    && !entity.isInvulnerableTo(damagesource)
                                    && (shooter == null || !entity.isAlliedTo(shooter)))
                    .stream()
                    .map(entity -> entity.position().add(0, entity.getBbHeight() * 0.8, 0))
                    .map(pos -> pos.subtract(position()))
                    .min(Comparator.comparing(Vec3::lengthSqr))
                    .map(Vec3::normalize)
                    .map(direction -> direction.multiply(1, 0.5, 1))
                    .map(direction -> direction.scale(Math.max(getDeltaMovement().length() * 0.5, 0.3)))
                    .orElse(getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D)));
        }
    }

@Override
	protected void tickContraption() {
		if (nonDamageTicks > 0)
			nonDamageTicks--;
		if (!(contraption instanceof CarriageContraption cc))
			return;

		if (carriage == null) {
			if (level().isClientSide)
				bindCarriage();
			else
				discard();
			return;
		}

		if (!Create.RAILWAYS.sided(level()).trains.containsKey(carriage.train.id)) {
			discard();
			return;
		}

		tickActors();
		boolean isStalled = isStalled();
		carriage.stalled = isStalled;

		CarriageSyncData carriageData = getCarriageData();

		if (!level().isClientSide) {

			entityData.set(SCHEDULED, carriage.train.runtime.getSchedule() != null);

			boolean shouldCarriageSyncThisTick =
				carriage.train.shouldCarriageSyncThisTick(level().getGameTime(), getType().updateInterval());
			if (shouldCarriageSyncThisTick && carriageData.isDirty()) {
				entityData.set(CARRIAGE_DATA, null);
				entityData.set(CARRIAGE_DATA, carriageData);
				carriageData.setDirty(false);
			}

			Navigation navigation = carriage.train.navigation;
			if (navigation.announceArrival && Math.abs(navigation.distanceToDestination) < 60
				&& carriageIndex == (carriage.train.speed < 0 ? carriage.train.carriages.size() - 1 : 0)) {
				navigation.announceArrival = false;
				arrivalSoundPlaying = true;
				arrivalSoundReversed = carriage.train.speed < 0;
				arrivalSoundTicks = Integer.MIN_VALUE;
			}

			if (arrivalSoundPlaying)
				tickArrivalSound(cc);

			entityData.set(TRACK_GRAPH, Optional.ofNullable(carriage.train.graph)
				.map(g -> g.id));

			level().gameEvent(this, GameEvent.RESONATE_8, this.position());

			return;
		}

		DimensionalCarriageEntity dce = carriage.getDimensional(level());
		if (tickCount % 10 == 0)
			updateTrackGraph();

		if (!dce.pointsInitialised)
			return;

		carriageData.approach(this, carriage, 1f / getType().updateInterval());

		if (!carriage.train.derailed)
			carriage.updateContraptionAnchors();

		xo = getX();
		yo = getY();
		zo = getZ();

		dce.alignEntity(this);

		if (sounds == null)
			sounds = new CarriageSounds(this);
		sounds.tick(dce);

		if (particles == null)
			particles = new CarriageParticles(this);
		particles.tick(dce);

		double distanceTo = 0;
		if (!firstPositionUpdate) {
			Vec3 diff = position().subtract(xo, yo, zo);
			Vec3 relativeDiff = VecHelper.rotate(diff, yaw, Axis.Y);
			double signum = Math.signum(-relativeDiff.x);
			distanceTo = diff.length() * signum;
			movingBackwards = signum < 0;
		}

		carriage.bogeys.getFirst()
			.updateAngles(this, distanceTo);
		if (carriage.isOnTwoBogeys())
			carriage.bogeys.getSecond()
				.updateAngles(this, distanceTo);

		if (carriage.train.derailed)
			spawnDerailParticles(carriage);
		if (dce.pivot != null)
			spawnPortalParticles(dce);

		firstPositionUpdate = false;
		validForRender = true;
	}

private static void setHearts(RenderGuiOverlayEvent.Pre event) {
        Player player = Minecraft.getInstance().player;
        Minecraft mc = Minecraft.getInstance();
        if (player == null){
            return;
        }
        ForgeGui gui = (ForgeGui)mc.gui;
        GuiGraphics stack = event.getGuiGraphics();
        gui.setupOverlayRenderState(true, false);
        int width = event.getWindow().getGuiScaledWidth();
        int height = event.getWindow().getGuiScaledHeight();
        event.setCanceled(true);
        RenderSystem.setShaderTexture(0, CUSTOM_HEARTS);
        RenderSystem.enableBlend();
        int health = Mth.ceil(player.getHealth());
        int tickCount = gui.getGuiTicks();
        boolean highlight = healthBlinkTime > (long)tickCount && (healthBlinkTime - (long)tickCount) / 3L % 2L == 1L;
        if (health < lastHealth && player.invulnerableTime > 0) {
            lastHealthTime = Util.getMillis();
            healthBlinkTime = (long)(tickCount + 20);
        } else if (health > lastHealth && player.invulnerableTime > 0) {
            lastHealthTime = Util.getMillis();
            healthBlinkTime = (long)(tickCount + 10);
        }

        if (Util.getMillis() - lastHealthTime > 1000L) {
            lastHealth = health;
            displayHealth = health;
            lastHealthTime = Util.getMillis();
        }

        lastHealth = health;
        int healthLast = displayHealth;
        float healthMax = (float) player.getAttributeValue(Attributes.MAX_HEALTH);
        int absorption = Mth.ceil(player.getAbsorptionAmount());
        int healthRows = Mth.ceil((healthMax + (float)absorption) / 2.0F / 10.0F);
        int rowHeight = Math.max(10 - (healthRows - 2), 3);
        Random random = new Random();
        random.setSeed((long)tickCount * 312871L);
        int left = width / 2 - 91;
        int top = height - gui.leftHeight;
        gui.leftHeight += healthRows * rowHeight;
        if (rowHeight != 10) {
            gui.leftHeight += 10 - rowHeight;
        }

        int regen = -1;
        if (player.hasEffect(MobEffects.REGENERATION)) {
            regen = tickCount % Mth.ceil(healthMax + 5.0F);
        }

        int TOP = player.level().getLevelData().isHardcore() ? 9 : 0;
        if (highlight){
            TOP = player.level().getLevelData().isHardcore() ? 27 : 18;
        }
        int BACKGROUND = highlight ? 25 : 16;
        int heartX = 0;
        if (player.hasEffect(GoetyEffects.CURSED.get())){
            heartX = 52;
        } else if (player.hasEffect(GoetyEffects.ACID_VENOM.get())){
            heartX = 70;
        } else if (player.hasEffect(GoetyEffects.SPASMS.get())){
            heartX = 34;
        } else if (player.hasEffect(GoetyEffects.NECROSIS.get())){
            heartX = 88;
        }
        float absorptionRemaining = (float)absorption;

        for(int i = Mth.ceil((healthMax + (float)absorption) / 2.0F) - 1; i >= 0; --i) {
            int row = Mth.ceil((float)(i + 1) / 10.0F) - 1;
            int x = left + i % 10 * 8;
            int y = top - row * rowHeight;
            if (health <= 4) {
                y += random.nextInt(2);
            }

            if (i == regen) {
                y -= 2;
            }

            stack.blit(CUSTOM_HEARTS, x, y, BACKGROUND, 0, 9, 9);
            if (highlight) {
                if (i * 2 + 1 < healthLast) {
                    stack.blit(CUSTOM_HEARTS, x, y, heartX, TOP, 9, 9);
                } else if (i * 2 + 1 == healthLast) {
                    stack.blit(CUSTOM_HEARTS, x, y, heartX + 9, TOP, 9, 9);
                }
            }

            if (absorptionRemaining > 0.0F) {
                if (absorptionRemaining == (float)absorption && (float)absorption % 2.0F == 1.0F) {
                    stack.blit(CUSTOM_HEARTS, x, y, heartX + 9, TOP, 9, 9);
                    --absorptionRemaining;
                } else {
                    stack.blit(CUSTOM_HEARTS, x, y, heartX, TOP, 9, 9);
                    absorptionRemaining -= 2.0F;
                }
            } else if (i * 2 + 1 < health) {
                stack.blit(CUSTOM_HEARTS, x, y, heartX, TOP, 9, 9);
            } else if (i * 2 + 1 == health) {
                stack.blit(CUSTOM_HEARTS, x, y, heartX + 9, TOP, 9, 9);
            }
        }

        RenderSystem.disableBlend();
        RenderSystem.setShaderTexture(0, CUSTOM_HEARTS);
    }

