public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        ItemStack itemstack = player.getItemInHand(hand);
        player.startUsingItem(hand);
        if (player.isCrouching()) {
            switchMode(itemstack, player);
            if (level instanceof ServerLevel) {
                ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F));
            } else {
                player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
            }
            level.gameEvent(player, GameEvent.INSTRUMENT_PLAY, player.position());
        } else {
            if (level instanceof ServerLevel serverlevel) {
                ColorUtil colorUtil = new ColorUtil(ChatFormatting.AQUA);
                serverlevel.sendParticles(new ShockwaveParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, 16.0F, 0, true), player.getX(), player.getY() + 0.25F, player.getZ(), 0, 0, 0, 0, 0);
                for (LivingEntity livingEntity : serverlevel.getEntitiesOfClass(LivingEntity.class, player.getBoundingBox().inflate(RANGE))){
                    if (livingEntity instanceof IServant servant){
                        if (servant.getTrueOwner() == player){
                            if (!servant.isCommanded()
                                    && servant.canUpdateMove()
                                    && !SEHelper.getGroundedEntities(player).contains(livingEntity)
                                    && !SEHelper.getGroundedEntityTypes(player).contains(livingEntity.getType())) {
                                if (isNone(itemstack)) {
                                    boolean patrol = false;
                                    if (player.getOffhandItem().getItem() instanceof PatrolPlan && servant.canPatrol()) {
                                        boolean isLeader = false;
                                        if (servant instanceof RaiderServant raiderServant) {
                                            if (raiderServant.getLeader() != null && raiderServant.getLeader().canPatrol()) {
                                                servant = raiderServant.getLeader();
                                                isLeader = true;
                                            }
                                        }
                                        if (player.isShiftKeyDown()) {
                                            if (servant.isPatrolling()) {
                                                servant.clearPatrol();
                                                serverlevel.sendParticles(ModParticleTypes.STOP.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                                patrol = true;
                                            }
                                        } else {
                                            List<GlobalPos> route = PatrolPlan.getList((player.getOffhandItem()));
                                            if (!route.isEmpty() && route.get(0).dimension().equals(livingEntity.level.dimension())) {
                                                boolean flag = true;
                                                if (isLeader) {
                                                    if (servant.getPatrolRoute().equals(route)) {
                                                        flag = false;
                                                    }
                                                }
                                                if (flag) {
                                                    servant.setPatrolRoute(route);
                                                    servant.setPatrolIndex(0);
                                                    servant.setBoundPos(route.get(0).pos());
                                                    servant.setWandering(false);
                                                    servant.setStaying(false);
                                                    livingEntity.playSound(SoundEvents.ZOMBIE_VILLAGER_CONVERTED, 1.0F, 1.0F);
                                                    serverlevel.sendParticles(ModParticleTypes.GO.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                                    patrol = true;
                                                }
                                            }
                                        }
                                    }
                                    if (!patrol) {
                                        if (!servant.isGuardingArea()
                                                && servant.canStay()
                                                && servant.canWander()) {
                                            if (servant.isStaying() || servant.isWandering()) {
                                                servant.setFollowing();
                                                serverlevel.sendParticles(ModParticleTypes.GO.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                            } else {
                                                servant.setBoundPos(null);
                                                servant.setWandering(false);
                                                servant.setStaying(true);
                                                serverlevel.sendParticles(ModParticleTypes.STOP.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                            }
                                        }
                                    }
                                } else if (isFollow(itemstack)) {
                                    if (servant.canFollow()) {
                                        servant.setFollowing();
                                        serverlevel.sendParticles(ModParticleTypes.GO.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                    }
                                } else if (isWander(itemstack)) {
                                    if (servant.canWander()) {
                                        servant.setWandering();
                                        serverlevel.sendParticles(ModParticleTypes.GO.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                    }
                                } else if (isStandBy(itemstack)) {
                                    if (servant.canStay()) {
                                        servant.setStaying();
                                        serverlevel.sendParticles(ModParticleTypes.STOP.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                    }
                                } else if (isGuard(itemstack)) {
                                    if (servant.canGuardArea()) {
                                        servant.setGuarding();
                                        serverlevel.sendParticles(ModParticleTypes.STOP.get(), livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 0, 0, 2.0D, 0, 1.0F);
                                    }
                                }
                            }
                        }
                    }
                }
                player.playSound(ModSounds.WIND_HORN.get(), 1.0F, 0.45F);
                ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(ModSounds.WIND_HORN.get(), 1.0F, 0.45F));
                level.gameEvent(player, GameEvent.INSTRUMENT_PLAY, player.position());
            }
        }

        return InteractionResultHolder.consume(itemstack);
    }

private boolean tickRunning() {
        boolean debug = false;
        Instruction current = instructions.get(index);
        if (mob.isHungry()) {
            mob.setHunger(mob.getMaxHunger());
        }
        if (mob instanceof Parasaurolophus parasaurolophus) {
            parasaurolophus.setStanding(false);
        }

        if (current instanceof Instruction.MoveTo moveTo) {
            return tryUpdatePath(moveTo);
        } else if (current instanceof Instruction.FlyTo flyTo) {
            if (mob instanceof PrehistoricFlying flying) {
                if (flying.isUsingStuckNavigation()) {
                    return !flying.getNavigation().isDone();
                }
                return flying.getMoveControl().hasWanted();
            }
            return true;
        } else if (current instanceof Instruction.FlyLand flyLand) {
            if (mob instanceof PrehistoricFlying flying) {
                return flying.isFlying();
            }
        } else if (current instanceof Instruction.TeleportTo teleportTo) {
            if (endTick < mob.level.getGameTime()) {
                return false;
            }
            mob.moveTo(teleportTo.target, teleportTo.rotation, mob.getXRot());
            mob.setYHeadRot(teleportTo.rotation);
            return true;
        } else if (current instanceof Instruction.AttachTo attachTo) {
            if (mob instanceof Meganeura meganeura) {
                if (!meganeura.getAttachSystem().isAttached()) {
                    return true;
                } else if (!attached) {
                    attached = true;
                    endTick = mob.level.getGameTime() + 100;
                }
                if (endTick < mob.level.getGameTime()) {
                    meganeura.getAttachSystem().stopAttaching();
                    return false;
                }
                return true;
            }
            return false;
        } else if (current instanceof Instruction.LeapLand leapLand) {
            PrehistoricLeaping leaping = (PrehistoricLeaping) mob;
            if (leaping.getLeapSystem().isLeaping()) {
                if (leaping.getLeapSystem().isLanding()) {
                    delayTick = mob.level.getGameTime() + 25;
                }
            } else if ( mob.isOnGround() && delayTick > 0 && delayTick >= mob.level.getGameTime()) {
                return false;
            } else if (leaping.distanceToSqr(leapLand.location) < LeapSystem.JUMP_DISTANCE && delayTick == 0) {
                leaping.getLeapSystem().setBlockLeapTarget(leapLand.location);
            }
            return true;
        } else if (current instanceof Instruction.LeapAttack leapAttack) {
            Entity target = mob.level.getEntity(leapAttack.targetId);
            if (target instanceof LivingEntity livingEntity) {
                livingEntity.setHealth(livingEntity.getMaxHealth());
                PrehistoricLeaping leaping = (PrehistoricLeaping) mob;
                double jumpDistance = 30;
                if (leaping.getLeapSystem().isLeaping()) {
                    if (leaping.getLeapSystem().isLanding()) {
                        delayTick = mob.level.getGameTime() + 25;
                    }
                } else if ( mob.isOnGround() && delayTick > 0 && delayTick >= mob.level.getGameTime()) {
                    return false;
                } else if (leaping.distanceToSqr(target) < jumpDistance && delayTick == 0) {
                    leaping.getLeapSystem().setLeapTarget(livingEntity);
                } else {
                    mob.getNavigation().moveTo(target, 1);
                    mob.lookAt(target, 120, 10);
                }
                return true;
            }
        } else if (current instanceof Instruction.Idle idle) {
            return endTick >= mob.level.getGameTime();
        } else if (current instanceof Instruction.Sleep sleep) {
            if (endTick < mob.level.getGameTime()) {
                mob.sleepSystem.setSleeping(false);
                mob.sleepSystem.setSleepForced(false);
                return false;
            }
            return true;
        } else if (current instanceof Instruction.PlayAnim playAnim) {
            if (playAnim.timeBased) {
                if (animCount < mob.level.getGameTime()) {
                    mob.getAnimationLogic().cancelAnimation(playAnim.controller);
                    return false;
                }
                return true;
            } else {
                if (mob.getAnimationLogic().isAnimationDone(activeAnim)) {
                    animCount--;
                    if (animCount > 0) {
                        activeAnim = mob.getAnimationLogic().forceAnimation(playAnim.controller, mob.getAllAnimations().get(playAnim.name), AnimationCategory.IDLE, 1, 5, false);
                    } else {
                        return false;
                    }
                }
                return true;
            }
        }
        return false;
    }

protected static void tickWeatherEffects(ClientTickEvent.Post event) {
		Minecraft mc = Minecraft.getInstance();

		if (!mc.isPaused()) {
			if (mc.level != null && TFConfig.getClientCloudBlockPrecipitationDistance() > 0) { // Semi vanilla copy of the weather tick, but made to work with cloud blocks instead
				Vec3 vec3 = mc.gameRenderer.getMainCamera().position();
				if (mc.level.getGameTime() % 10L == 0L) {
					RENDER_HELPER.clear();

					double camX = vec3.x();
					double camY = vec3.y();
					double camZ = vec3.z();

					int floorX = Mth.floor(camX);
					int floorY = Mth.floor(camY);
					int floorZ = Mth.floor(camZ);

					int renderDistance = mc.options.weatherRadius().get();
					int precipitationDistance = TFConfig.getClientCloudBlockPrecipitationDistance();
					BlockPos.MutableBlockPos pos = new BlockPos.MutableBlockPos();

					for (int roofZ = floorZ - renderDistance; roofZ <= floorZ + renderDistance; ++roofZ) {
						for (int roofX = floorX - renderDistance; roofX <= floorX + renderDistance; ++roofX) {
							int lastBadYLevel = Integer.MIN_VALUE;
							for (int roofY = floorY - renderDistance; roofY < floorY + precipitationDistance + renderDistance; roofY++) {
								boolean skipLoop = roofY == lastBadYLevel + 1; // Cloud can't rain if there is an invalid blockState right below it, so might as well skip the loop
								pos.set(roofX, roofY, roofZ);
								if (Heightmap.Types.MOTION_BLOCKING.isOpaque().test(mc.level.getBlockState(pos)))
									lastBadYLevel = roofY; // Check if we skip next loop
								if (skipLoop) continue;

								if (mc.level.getBlockState(pos).getBlock() instanceof CloudBlock cloudBlock) {
									Pair<Biome.Precipitation, Float> precipitationRainLevelPair = cloudBlock.getCurrentPrecipitation(pos, mc.level, mc.level.getRainLevel(1.0F));
									if (precipitationRainLevelPair.getLeft() == Biome.Precipitation.NONE)
										continue; // No rain no gain

									int highestRainyBlock = roofY;
									for (int y = roofY - 1; y > roofY - precipitationDistance; y--) {
										if (!Heightmap.Types.MOTION_BLOCKING.isOpaque().test(mc.level.getBlockState(pos.atY(y))))
											highestRainyBlock = y;
										else break;
									}
									if (highestRainyBlock == roofY) continue;

									RENDER_HELPER.add(new PrecipitationRenderHelper(pos.immutable(), precipitationRainLevelPair.getLeft(), precipitationRainLevelPair.getRight(), highestRainyBlock));
								}
							}
						}
					}
				}

				if (!RENDER_HELPER.isEmpty()) {
					RandomSource randomsource = RandomSource.create((long) mc.levelRenderer.getTicks() * 312987231L);
					BlockPos particlePos = null;
					int weatherRadius = mc.options.weatherRadius().get();
					int weatherDiameter = 2 * weatherRadius + 1;
					int weatherArea = weatherDiameter * weatherDiameter;
					int particleCount = (int) (0.225F * weatherArea) / (mc.options.particles().get() == ParticleStatus.DECREASED ? 2 : 1);

					boolean yetToMakeASound = true;
					BlockPos camPos = BlockPos.containing(vec3);

					List<Vec2i> particleChecks = new ArrayList<>();
					for (int i = 0; i < particleCount; ++i) {
						particleChecks.add(new Vec2i(randomsource.nextInt(weatherDiameter) - weatherRadius + camPos.getX(), randomsource.nextInt(weatherDiameter) - weatherRadius + camPos.getZ()));
					}

					for (PrecipitationRenderHelper helper : RENDER_HELPER) {
						if (helper.precipitation() == Biome.Precipitation.RAIN) {
							for (Vec2i vec2 : particleChecks) {
								if (vec2.x == helper.cloudPos().getX() && vec2.z == helper.cloudPos().getZ()) {
									BlockPos highestRainyPos = helper.cloudPos().atY(helper.rainOnY());
									if (!Heightmap.Types.MOTION_BLOCKING.isOpaque().test(mc.level.getBlockState(highestRainyPos.below())))
										continue;

									if (yetToMakeASound && particlePos != null && randomsource.nextInt(3) < mc.levelRenderer.weatherEffectRenderer.rainSoundTime++) {
										mc.levelRenderer.weatherEffectRenderer.rainSoundTime = 0;
										if (particlePos.getY() > camPos.getY() + 1 && mc.level.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING, camPos).getY() > Mth.floor((float) camPos.getY())) {
											mc.level.playLocalSound(particlePos, SoundEvents.WEATHER_RAIN_ABOVE, SoundSource.WEATHER, 0.1F, 0.5F, false);
										} else {
											mc.level.playLocalSound(particlePos, SoundEvents.WEATHER_RAIN, SoundSource.WEATHER, 0.2F, 1.0F, false);
										}
										yetToMakeASound = false;
									}

									if (highestRainyPos.getY() > mc.level.getMinY() && highestRainyPos.getY() <= camPos.getY() + 10 && highestRainyPos.getY() >= camPos.getY() - 10) {
										particlePos = highestRainyPos.below();
										if (mc.options.particles().get() == ParticleStatus.MINIMAL) break;

										double particleX = randomsource.nextDouble();
										double particleZ = randomsource.nextDouble();
										BlockState blockstate = mc.level.getBlockState(particlePos);
										FluidState fluidstate = mc.level.getFluidState(particlePos);
										VoxelShape voxelshape = blockstate.getCollisionShape(mc.level, particlePos);
										double voxelMax = voxelshape.max(Direction.Axis.Y, particleX, particleZ);
										double fluidMax = fluidstate.getHeight(mc.level, particlePos);
										double particleY = Math.max(voxelMax, fluidMax);
										ParticleOptions particleoptions = !fluidstate.is(FluidTags.LAVA) && !blockstate.is(Blocks.MAGMA_BLOCK) && !CampfireBlock.isLitCampfire(blockstate) ? ParticleTypes.RAIN : ParticleTypes.SMOKE;
										mc.level.addParticle(particleoptions, (double) particlePos.getX() + particleX, (double) particlePos.getY() + particleY, (double) particlePos.getZ() + particleZ, 0.0D, 0.0D, 0.0D);
									}
								}
							}
						}
					}
				}
			}
		}
	}

private static void configureFallback(RegistryWrapper.WrapperLookup registries, String tableId,
                                          List<LootPool> existingPools, Consumer<LootPool> poolSink,
                                          LootConfig config, String configName, boolean isEntityLootTable) {
        var fallback = config.fallback;
        if (fallback == null || fallback.entries.isEmpty() || fallback.rolls_multiplier <= 0) { return; }
        for (var blacklisted: fallback.blacklist) {
            if (matchesId(tableId, blacklisted)) { return; }
        }
        var applicable = new ArrayList<LootConfig.Fallback.Entry>();
        for (var entry: fallback.entries) {
            if (entry.reference.isEmpty()) { continue; }
            var tables = entry.tables != null ? entry.tables : fallback.tables;
            if (matchesId(tableId, tables)) {
                applicable.add(entry);
            }
        }
        if (applicable.isEmpty()) { return; }

        var contents = inspect(existingPools);
        if (contents.isEmpty()) { return; }

        if (fallback.skip_tables_with_rpg_loot) {
            var rpgItems = rpgTierItems();
            for (var pool: contents) {
                for (var itemId: pool.items.keySet()) {
                    if (rpgItems.contains(itemId)) {
                        pendingReport.skipped.put(tableId, "already drops RPG Series loot: " + itemId);
                        return;
                    }
                }
            }
        }

        // Every applicable entry becomes a part of a single injected pool, so the total injected
        // loot is bounded by `max_rolls`, no matter how many references the table matches
        var parts = new ArrayList<FallbackPart>();
        var reportLines = new LinkedHashMap<String, String>();
        for (var entry: applicable) {
            var reference = entry.reference;
            float share = 0;
            String matchedItem = null;
            int plainWeight = 0, enchantedWeight = 0;
            Float minLevel = null, maxLevel = null;
            for (var pool: contents) {
                int matchedWeight = 0;
                for (var item: pool.items.entrySet()) {
                    if (!matchesItem(item.getKey(), reference)) { continue; }
                    var occurrence = item.getValue();
                    matchedWeight += occurrence.weight();
                    plainWeight += occurrence.plainWeight;
                    enchantedWeight += occurrence.enchantedWeight;
                    if (occurrence.minLevel != null) {
                        minLevel = minLevel == null ? occurrence.minLevel : Math.min(minLevel, occurrence.minLevel);
                        maxLevel = maxLevel == null ? occurrence.maxLevel : Math.max(maxLevel, occurrence.maxLevel);
                    }
                    if (matchedItem == null) { matchedItem = item.getKey(); }
                }
                if (matchedWeight > 0 && pool.totalWeight > 0) {
                    share = Math.max(share, (float) matchedWeight / (float) pool.totalWeight);
                }
            }
            if (share <= 0) { continue; }

            var scale = share * fallback.rolls_multiplier;
            var rolls = entry.rolls * scale;
            var bonusRolls = entry.bonus_rolls * scale;
            if (rolls <= 0) { continue; }
            var mix = new EnchantMix(plainWeight, enchantedWeight, minLevel, maxLevel);
            // A single roll, the combined pool decides how many times a part is rolled
            var partPool = buildPool(registries, entry.items, 1F, 0F, false, mix, config.behavior);
            if (partPool == null) { continue; }
            parts.add(new FallbackPart(partPool, rolls, bonusRolls));

            var enchantInfo = enchantedWeight == 0 ? "plain" : plainWeight == 0 ? "enchanted" :
                    String.format(Locale.ROOT, "%.0f%% enchanted", 100F * enchantedWeight / (plainWeight + enchantedWeight));
            if (enchantedWeight > 0 && minLevel != null) {
                enchantInfo += String.format(Locale.ROOT, " (levels %.0f-%.0f)", minLevel, maxLevel);
            }
            // The same reference may drive multiple entries (for example: gear and accessories)
            reportLines.put(configName + "/" + reference + " -> " + describe(entry.items), String.format(Locale.ROOT,
                    "matched %s, share %.2f, rolls %.2f, %s", matchedItem, share, rolls, enchantInfo));
        }
        if (parts.isEmpty()) { return; }

        float totalRolls = 0, totalBonusRolls = 0;
        for (var part: parts) {
            totalRolls += part.rolls();
            totalBonusRolls += part.bonusRolls();
        }
        var rolls = fallback.max_rolls > 0 ? Math.min(totalRolls, fallback.max_rolls) : totalRolls;
        var bonusRolls = totalBonusRolls * (rolls / totalRolls);

        LootPool.Builder lootPoolBuilder = LootPool.builder();
        if (isEntityLootTable) {
            lootPoolBuilder.conditionally(KilledByPlayerLootCondition.builder());
        }
        applyRolls(lootPoolBuilder, rolls, bonusRolls);
        for (var part: parts) {
            // Parts are picked proportionally to their own rolls, each an inline table keeping its item weights intact
            var weight = Math.max(1, Math.round(FALLBACK_PART_WEIGHT_SCALE * part.rolls() / totalRolls));
            lootPoolBuilder.with(LootTableEntry.builder(LootTable.builder().pool(part.pool()).build()).weight(weight));
        }
        poolSink.accept(lootPoolBuilder.build());

        var tableReport = pendingReport.injected.computeIfAbsent(tableId, k -> new LinkedHashMap<>());
        tableReport.putAll(reportLines);
        tableReport.put(configName + " (total)", String.format(Locale.ROOT,
                "rolls %.2f, injected %.2f", totalRolls, rolls));
    }

@Override
    public void tick() {
        if (tickCount == 1) {
            onFirstTick();
        }

        Level level = level();

        boolean enabled = !disabledByHacking && getAirHandler().getPressure() > 0.01F;
        if (!level.isClientSide) {
            entityData.set(PRESSURE, ((int) (getAirHandler().getPressure() * 10.0f)) / 10.0f);  // rounded for client

            setAccelerating(!standby && enabled);
            if (isAccelerating()) {
                fallDistance = 0;
            }

            if (healingInterval != 0 && getHealth() < getMaxHealth() && tickCount % healingInterval == 0) {
                heal(1);
                getAirHandler().addAir(-healingInterval);
            }

            if (!isSuffocating) {
                suffocationCounter = 40;
            }
            isSuffocating = false;

            if (chunkLoader != null && PlayerLogoutTracker.INSTANCE.isPlayerLoggedOutTooLong(level.getServer(), getOwnerUUID())) {
                chunkLoader.unloadAll((ServerLevel) level);
            }

            Path path = getNavigation().getPath();
            if (path != null) {
                Node target = path.getEndNode();
                if (target != null) {
                    setTargetedBlock(new BlockPos(target.x, target.y, target.z));
                } else {
                    setTargetedBlock(null);
                }
            } else {
                setTargetedBlock(null);
            }

            if (level.getGameTime() % 20 == 0) {
                debugger.updateDebuggingPlayers();
            }

            tickFakePlayer();

            if (securityUpgradeCount > 1 && getHealth() > 0F) {
                handleFluidDisplacement();
            }

            getAirHandler().addAir(-PneumaticValues.DRONE_USAGE_CHUNKLOAD * getUpgrades(ModUpgrades.CHUNKLOADER.get()));

            handleDebugTick();
        } else {
            oldLaserExtension = laserExtension;
            if (getActiveProgramKey().getPath().equals("dig")) {
                laserExtension = Math.min(1, laserExtension + LASER_EXTEND_SPEED);
            } else {
                laserExtension = Math.max(0, laserExtension - LASER_EXTEND_SPEED);
            }

            if (isAccelerating() && level.random.nextBoolean()) {
                int x = (int) Math.floor(getX());
                int y = (int) Math.floor(getY() - 1);
                int z = (int) Math.floor(getZ());
                BlockPos pos = new BlockPos(x, y, z);
                BlockState state = null;
                for (int i = 0; i < 3; i++, y--) {
                    state = level.getBlockState(pos);
                    if (!state.isAir()) break;
                }

                if (!state.isAir()) {
                    Vec3 vec = new Vec3(getY() - y, 0, 0);
                    vec = vec.yRot((float) (random.nextFloat() * Math.PI * 2));
                    ParticleOptions data = new BlockParticleOption(ParticleTypes.BLOCK, state);
                    level.addParticle(data, getX() + vec.x, y + 1, getZ() + vec.z, vec.x, 0, vec.z);
                }
            }
        }
        if (isAccelerating()) {
            setDeltaMovement(getDeltaMovement().scale(0.3));
            propSpeed = Math.min(1, propSpeed + 0.04F);
            if (!level.isClientSide) {
                getAirHandler().addAir(-1);
            }
        } else {
            propSpeed = Math.max(0, propSpeed - 0.04F);
        }
        oldPropRotation = propRotation;
        propRotation += propSpeed;

        super.tick();

        if (hasMinigun()) {
            getMinigun().setAttackTarget(getTarget()).tick(getX(), getY(), getZ());
        }

        if (!level.isClientSide && isAlive()) {
            if (enabled) {
                DroneAIManager prevActive = getActiveAIManager();
                aiManager.onUpdateTasks();
                if (getActiveAIManager() != prevActive) {
                    // active AI has changed (started or stopped using External Program) - resync widget list to debugging players
                    getDebugger().getDebuggingPlayers().forEach(p -> NetworkHandler.sendToPlayer(PacketSyncDroneProgWidgets.create(this), p));
                }
            }
            handleRedstoneEmission();
        }
    }

public void tick() {
        super.tick();
        prevExplodeProgress = explodeProgress;
        prevScanProgress = scanProgress;
        if (this.isScanning() && scanProgress < 5F) {
            scanProgress++;
        }
        if (!this.isScanning() && scanProgress > 0F) {
            scanProgress--;
        }
        if (this.isExploding() && explodeProgress < 10F) {
            explodeProgress += 0.5F;
        }
        if (!this.isExploding() && explodeProgress > 0F) {
            explodeProgress -= 0.5F;
        }
        if (this.isExploding()) {
            if (explodeProgress >= 10.0F) {
                this.remove(RemovalReason.KILLED);
                Explosion.BlockInteraction blockinteraction = net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(level(), this) ? level().getGameRules().getBoolean(GameRules.RULE_MOB_EXPLOSION_DROP_DECAY) ? Explosion.BlockInteraction.DESTROY_WITH_DECAY : Explosion.BlockInteraction.DESTROY : Explosion.BlockInteraction.KEEP;
                MineExplosion explosion = new MineExplosion(level(), this, this.getX(), this.getY(0.5), this.getZ(), 5.0F, this.isInWaterOrBubble(), blockinteraction);
                explosion.explode();
                explosion.finalizeExplosion(true);
            }
            this.setDeltaMovement(this.getDeltaMovement().multiply(0.3F, 1, 0.3F));
        }
        if (!level().isClientSide) {
            Entity entity = getAnchor();
            if (entity == null) {
                this.setMaxChainLength(7 + this.getRandom().nextInt(6));
                MineGuardianAnchorEntity created = new MineGuardianAnchorEntity(this);
                level().addFreshEntity(created);
                this.setAnchorUUID(created.getUUID());
                this.entityData.set(ANCHOR_ID, created.getId());
            } else {
                if (entity instanceof MineGuardianAnchorEntity anchorEntity) {
                    anchorEntity.linkWithGuardian(this);
                }
            }
            if (this.isInWaterOrBubble()) {
                this.setAirSupply(300);
            } else if (this.onGround()) {
                this.setDeltaMovement(this.getDeltaMovement().add((double) ((this.random.nextFloat() * 2.0F - 1.0F) * 0.6F), 0.6F, (double) ((this.random.nextFloat() * 2.0F - 1.0F) * 0.6F)));
                this.setYRot(this.random.nextFloat() * 360.0F);
                this.setOnGround(false);
                this.playSound(ACSoundRegistry.MINE_GUARDIAN_FLOP.get());
                this.hasImpulse = true;
            }
            Entity target = this.getTarget();
            if (target == null || !target.isAlive()) {
                timeSinceHadTarget++;
            } else {
                timeSinceHadTarget = 0;
            }
            if (this.isScanning()) {
                this.setEyeClosed(false);
                if (scanTime < maxScanTime) {
                    if(scanTime % 20 == 0){
                        this.playSound(ACSoundRegistry.MINE_GUARDIAN_SCAN.get());
                    }
                    if (scanTime % 5 == 0 && scanProgress >= 5.0F) {
                        Entity found = null;
                        HitResult hitresult = level().clip(new ClipContext(this.getEyePosition(), this.getEyePosition().add(this.getLookAngle().scale(8)), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
                        if (hitresult instanceof EntityHitResult entityHitResult && isValidTarget(entityHitResult.getEntity())) {
                            Entity inSight = entityHitResult.getEntity();
                            if (!inSight.equals(this) && !inSight.isAlliedTo(this) && !this.isAlliedTo(inSight) && this.hasLineOfSight(inSight)) {
                                found = inSight;
                            }
                        } else {
                            AABB around = new AABB(hitresult.getLocation().add(-0.5F, -0.5F, -0.5F), hitresult.getLocation().add(0.5F, 0.5F, 0.5F)).inflate(3);
                            for (Entity inSight : level().getEntitiesOfClass(LivingEntity.class, around)) {
                                if (!inSight.equals(this) && !inSight.isAlliedTo(this) && !this.isAlliedTo(inSight) && this.hasLineOfSight(inSight)) {
                                    if (found == null && isValidTarget(inSight) || found != null && isValidTarget(inSight) && inSight.distanceTo(this) < found.distanceTo(this)) {
                                        found = inSight;
                                    }
                                }
                            }
                        }
                        if (found instanceof LivingEntity living) {
                            this.setTarget(living);
                            this.setScanning(false);
                        }
                    }
                    scanTime++;
                } else {
                    scanTime = 0;
                    lastScanTime = tickCount;
                    this.setScanning(false);
                }
            } else if (this.isEyeClosed()) {
                int j = this.tickCount - lastScanTime;
                if (timeSinceHadTarget == 0 || !this.isInWaterOrBubble()) {
                    this.setEyeClosed(false);
                } else if (this.isInWaterOrBubble() && (timeSinceHadTarget > maxSleepTime && j > 200 || this.hurtTime > 0)) {
                    maxSleepTime = 200 + random.nextInt(100);
                    this.setScanning(true);
                    scanTime = 0;
                    maxScanTime = 100 + random.nextInt(100);
                }
            } else {
                if (this.isInWaterOrBubble() && timeSinceHadTarget > 100) {
                    this.setEyeClosed(true);
                }
            }
        } else {
            Vec3 vec3 = this.getDeltaMovement();
            if (vec3.y > 0.0D && this.clientSideTouchedGround && !this.isSilent()) {
                this.level().playLocalSound(this.getX(), this.getY(), this.getZ(), this.getFlopSound(), this.getSoundSource(), 1.0F, 1.0F, false);
            }

            this.clientSideTouchedGround = vec3.y < 0.0D && this.level().loadedAndEntityCanStandOn(this.blockPosition().below(), this);

        }
    }

public void tick() {
        if (this.level != null) {
            if (!this.level.isClientSide) {
                if (this.level.getGameTime() % 20 == 0 && this.glowTick <= 0) {
                    if (this.getDecreePos() != null) {
                        if (this.getDecreePos().dimension() == this.level.dimension()) {
                            BlockPos decreePos = this.getDecreePos().pos();
                            AABB aabb = new AABB(this.worldPosition).inflate(this.getRange());
                            List<Mob> list = this.level.getEntitiesOfClass(Mob.class, aabb, mob -> mob instanceof IServant servant && servant.getTrueOwner() == this.getTrueOwner() && !servant.isCommanded() && !servant.isPatrolling());
                            list.removeIf(mob -> {
                               if (this.getTrueOwner() instanceof Player player) {
                                   if (SEHelper.isGrounded(player, mob)) {
                                       return true;
                                   }
                               }

                               if (this.getEntityTypeTag() != null && !this.getEntityTypeTag().isEmpty()) {
                                   if (mob.getType() != this.getEntityType()) {
                                       return true;
                                   }
                               }

                               if (mob instanceof ITrainable trainable && trainable.isTraining()) {
                                   return true;
                               }

                               if (mob instanceof RaiderServant raiderServant && raiderServant.getLeader() != null) {
                                   return true;
                               }

                               if (this.getMode() == DecreeMode.BABY_ONLY) {
                                   return !mob.isBaby();
                               } else if (this.getMode() == DecreeMode.ADULT_ONLY) {
                                   return mob.isBaby();
                               }

                               return false;
                            });

                            if (this.level.getBlockEntity(decreePos) instanceof IBarrack barrack) {
                                Predicate<Mob> requirements = barrack.trainingRequirements(this.level, decreePos);
                                EntityType<? extends Mob> trainedType = barrack.getTrainedMob(this.level, decreePos);
                                boolean trainsMagic = trainedType != null && producesSpellCaster(trainedType, this.level);

                                list.removeIf(mob -> {
                                    if (!(mob instanceof ITrainable)) {
                                        return false;
                                    }
                                    boolean reject = !requirements.test(mob);
                                    if (mob instanceof Neollager neollager) {
                                        reject |= neollager.isMagic() != trainsMagic;
                                    }
                                    return reject;
                                });
                            }
                            int i = 0;
                            BlockEntity blockEntity = this.level.getBlockEntity(decreePos);
                            for (Mob mob : list) {
                                if (mob instanceof IServant servant) {
                                    boolean command = true;
                                    boolean alert = true;
                                    if (servant instanceof RaiderServant raiderServant) {
                                        if (raiderServant.getLeader() == null) {
                                            if (raiderServant instanceof ILooter looter && blockEntity instanceof ChestBlockEntity chestBlock) {
                                                if (chestBlock.getBlockState().is(ModTags.Blocks.RAIDING_CHESTS) && looter.getDumpChestPos() == null) {
                                                    looter.setDumpChestPos(decreePos);
                                                    looter.setDumpChestDim(this.level.dimension());
                                                } else if (looter.getChestPos() == null) {
                                                    looter.setChestPos(decreePos);
                                                    looter.setChestDim(this.level.dimension());
                                                } else {
                                                    alert = false;
                                                }
                                                command = false;
                                            } else if (blockEntity instanceof OminousIdolBlockEntity idolBlock && idolBlock.getTrueOwner() == raiderServant.getTrueOwner() && raiderServant.canLinkToIdol()) {
                                                if (raiderServant.getIdol() != idolBlock && idolBlock.hasSpace()) {
                                                    idolBlock.addIllager(raiderServant);
                                                    raiderServant.setRevivePos(idolBlock.getBlockPos());
                                                    if (idolBlock.getLevel() != null) {
                                                        raiderServant.setReviveDim(idolBlock.getLevel().dimension());
                                                    }
                                                } else {
                                                    alert = false;
                                                }
                                                command = false;
                                            }
                                        } else {
                                            alert = false;
                                            command = false;
                                        }
                                    }
                                    if (command) {
                                        servant.setCommandPos(decreePos);
                                        servant.setBoundPos(decreePos);
                                    }
                                    if (alert) {
                                        ++i;
                                    }
                                }
                            }
                            if (i > 0) {
                                this.glowTick = 20;
                                this.level.playSound(null, this.worldPosition, ModSounds.DECREE.get(), SoundSource.BLOCKS, 0.5F, 0.75F);
                            }
                        }
                    }
                }
                if (this.glowTick > 0) {
                    --this.glowTick;
                }
                this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(OminousDecreeBlock.POWERED, this.glowTick > 0), 3);
            }
        }
    }

@Override
	public void performRitual(IMasterRitualStone masterRitualStone)
	{
		/* Default Ritual Stuff */
		Level world = masterRitualStone.getWorldObj();
		int currentEssence = masterRitualStone.getOwnerNetwork().getCurrentEssence();
		BlockPos pos = masterRitualStone.getMasterBlockPos();

		if (currentEssence < getRefreshCost())
		{
			masterRitualStone.getOwnerNetwork().causeNausea();
			return;
		}

		int maxEffects = currentEssence / getRefreshCost();
		int totalEffects = 0;

		/* Default will augment stuff */
		List<EnumDemonWillType> willConfig = masterRitualStone.getActiveWillConfig();
		DemonWillHolder holder = WorldDemonWillHandler.getWillHolder(world, pos);

		double rawWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DEFAULT, willConfig);
		double corrosiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.CORROSIVE, willConfig);
		double destructiveWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.DESTRUCTIVE, willConfig);
		double steadfastWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.STEADFAST, willConfig);
		double vengefulWill = this.getWillRespectingConfig(world, pos, EnumDemonWillType.VENGEFUL, willConfig);

		double rawDrained = 0;
		double corrosiveDrained = 0;
		double destructiveDrained = 0;
		double steadfastDrained = 0;
		double vengefulDrained = 0;

		/* Actual ritual stuff begins here */
		AreaDescriptor groundingRange = masterRitualStone.getBlockRange(GROUNDING_RANGE);
		List<LivingEntity> entities = world.getEntitiesOfClass(LivingEntity.class, groundingRange.getAABB(pos));
		for (LivingEntity entity : entities)
		{
			if (totalEffects >= maxEffects)
			{
				break;
			}

			if (entity instanceof Player && ((Player) entity).isCreative())
				continue;

			totalEffects++;

			if (entity instanceof Player)
			{
				/* Raw will effect: Affects players */
				if (world.getGameTime() % 10 == 0)
				{
					if (rawWill >= willDrain)
					{

						rawDrained += willDrain;

						double[] drainagePlayer = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

						corrosiveDrained += drainagePlayer[0];
						destructiveDrained += drainagePlayer[1];
						vengefulDrained += drainagePlayer[2];
					}
				}
			} else if (entity.canChangeDimensions())
			{
				if (world.getGameTime() % 10 == 0)
				{
					double[] drainageEntity = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

					corrosiveDrained += drainageEntity[0];
					destructiveDrained += drainageEntity[1];
					vengefulDrained += drainageEntity[2];
				}
			} else if (!entity.canChangeDimensions())
			{
				/*
				 * Steadfast will effect: Affects bosses (some bosses, like the wither, have a
				 * restriction to motion modification, others, like the Ender Dragon, don't do
				 * potions)
				 */
				if (steadfastWill >= willDrain)
				{
					if (entity instanceof WitherBoss || entity instanceof EnderDragon)
						entity.move(MoverType.SELF, new Vec3(0, -0.05, 0)); // to work on Wither and EnderDragon
																				// without
					// interfering with other mod author's decisions
					// (looking at you, Vazkii)

					steadfastDrained += willDrain / 10f;

					double[] drainagePlayer = sharedWillEffects(world, entity, corrosiveWill, destructiveWill, vengefulWill, corrosiveDrained, destructiveDrained, vengefulDrained);

					corrosiveDrained += drainagePlayer[0];
					destructiveDrained += drainagePlayer[1];
					vengefulDrained += drainagePlayer[2];
				}
			}
		}

		if (rawDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DEFAULT, rawDrained, true);
		if (corrosiveDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.CORROSIVE, corrosiveDrained, true);
		if (destructiveDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.DESTRUCTIVE, destructiveDrained, true);
		if (steadfastDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.STEADFAST, steadfastDrained, true);
		if (vengefulDrained > 0)
			WorldDemonWillHandler.drainWill(world, pos, EnumDemonWillType.VENGEFUL, vengefulDrained, true);

		masterRitualStone.getOwnerNetwork().syphon(masterRitualStone.ticket(getRefreshCost() * totalEffects));
	}

public void aiStep() {
        if (!this.level.isClientSide && this.isAlive()) {
            if (this.lastHitTime > 0){
                --this.lastHitTime;
            } else if (this.hitTimes > 0) {
                this.hitTimes = 0;
            }
            if (this.toHealTime > 0) {
                --this.toHealTime;
            }
            if (this.overwhelmed > 0) {
                --this.overwhelmed;
            }
            this.healRaidersGoal.decrementCooldown();
            this.attackPlayersGoal.setCanAttack(this.healRaidersGoal.getCooldown() <= 0);

            if (this.isDrinkingPotion()) {
                if (this.usingTime-- <= 0) {
                    this.setUsingItem(false);
                    ItemStack itemstack = this.getMainHandItem();
                    this.setItemSlot(EquipmentSlot.MAINHAND, ItemStack.EMPTY);
                    if (itemstack.is(ModItems.BREW.get())) {
                        List<MobEffectInstance> list = PotionUtils.getMobEffects(itemstack);
                        for (MobEffectInstance mobeffectinstance : list) {
                            this.addEffect(new MobEffectInstance(mobeffectinstance));
                        }
                        List<BrewEffectInstance> list1 = BrewUtils.getBrewEffects(itemstack);
                        for (BrewEffectInstance brewEffectInstance : list1) {
                            brewEffectInstance.getEffect().drinkBlockEffect(this, this, this, brewEffectInstance.getAmplifier(), BrewUtils.getAreaOfEffect(itemstack));
                        }
                    }

                    this.getAttribute(Attributes.MOVEMENT_SPEED).removeModifier(SPEED_MODIFIER_DRINKING);
                }
            } else {
                int amp = 0;
                if (this.level.getRandom().nextFloat() <= 0.05F && this.level.getDifficulty() == Difficulty.NORMAL){
                    amp = 2;
                } else if (this.level.getRandom().nextFloat() <= 0.25F){
                    amp = 1;
                }
                List<MobEffectInstance> mobEffectInstance = new ArrayList<>();
                List<BrewEffectInstance> brewEffectInstance = new ArrayList<>();
                if (this.random.nextFloat() < 0.15F && (this.isInWall() || (this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypes.IN_WALL)))){
                    brewEffectInstance.add(new BrewEffectInstance(new BlindJumpBrewEffect(0), 1, amp));
                } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && (this.getLastDamageSource().is(DamageTypes.CACTUS) || this.getLastDamageSource().is(DamageTypes.SWEET_BERRY_BUSH))){
                    brewEffectInstance.add(new BrewEffectInstance(new HarvestBlockEffect()));
                } else if (this.random.nextFloat() < 0.15F && this.getHealth() < this.getMaxHealth() && (this.getTarget() == null || this.toHealTime == 0)) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.HEAL, 1, amp));
                } else if (this.random.nextFloat() < 0.15F && this.isEyeInFluidType(ForgeMod.WATER_TYPE.get()) && !this.hasEffect(MobEffects.WATER_BREATHING)) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.WATER_BREATHING, 3600));
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.SWIFT_SWIM.get(), 3600));
                } else if (this.random.nextFloat() < 0.15F && (this.isOnFire() || this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FIRE)) && !this.hasEffect(MobEffects.FIRE_RESISTANCE)) {
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 3600));
                } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && this.getLastDamageSource().is(DamageTypeTags.IS_FALL) && !this.hasEffect(MobEffects.SLOW_FALLING)){
                    mobEffectInstance.add(new MobEffectInstance(MobEffects.SLOW_FALLING, 3600));
                } else if (this.random.nextFloat() < 0.15F && this.getLastDamageSource() != null && ModDamageSource.physicalAttacks(this.getLastDamageSource()) && !this.hasEffect(GoetyEffects.REPULSIVE.get())){
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.REPULSIVE.get(), 1800 / (amp + 1), amp));
                } else if (this.random.nextFloat() < 0.15F && this.getTarget() != null) {
                    if ((this.random.nextFloat() <= 0.15F && this.getTarget().distanceTo(this) <= 4.0F)){
                        brewEffectInstance.add(new BrewEffectInstance(new BlindJumpBrewEffect(0), 1, amp));
                    } else if (this.random.nextFloat() <= 0.15F && !this.hasEffect(MobEffects.REGENERATION)){
                        mobEffectInstance.add(new MobEffectInstance(MobEffects.REGENERATION, 900 / (amp + 1), amp));
                        if (this.random.nextFloat() < 0.25F && MobUtil.isInSunlight(this) && !this.hasEffect(GoetyEffects.PHOTOSYNTHESIS.get())){
                            mobEffectInstance.add(new MobEffectInstance(GoetyEffects.PHOTOSYNTHESIS.get(), 1800));
                        }
                    } else if (this.random.nextFloat() < 0.05F && !this.hasEffect(MobEffects.DAMAGE_RESISTANCE)){
                        mobEffectInstance.add(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 1800));
                    } else if (this.random.nextFloat() < 0.05F && !this.hasEffect(GoetyEffects.FROSTY_AURA.get()) && !this.hasEffect(GoetyEffects.FIERY_AURA.get())) {
                        if (this.random.nextBoolean()) {
                            if (!this.getTarget().hasEffect(GoetyEffects.FREEZING.get()) && !this.getTarget().hasEffect(MobEffects.FIRE_RESISTANCE) && !this.getTarget().fireImmune()) {
                                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FIERY_AURA.get(), 1800 / (amp + 1), amp));
                            }
                        } else {
                            if (!this.getTarget().isOnFire() && this.getTarget().canFreeze()){
                                mobEffectInstance.add(new MobEffectInstance(GoetyEffects.FROSTY_AURA.get(), 1800 / (amp + 1), amp));
                            }
                        }
                    }
                } else if (this.random.nextFloat() <= 0.15F && MobUtil.isInWeb(this) && !this.hasEffect(GoetyEffects.CLIMBING.get())){
                    mobEffectInstance.add(new MobEffectInstance(GoetyEffects.CLIMBING.get(), 3600));
                } else if (this.random.nextFloat() < 0.05F && MobUtil.hasLongNegativeEffects(this)) {
                    brewEffectInstance.add(new BrewEffectInstance(new PurifyBrewEffect("purify_debuff", 0, 0, MobEffectCategory.BENEFICIAL, 0x385858, true)));
                }

                if (!mobEffectInstance.isEmpty() || !brewEffectInstance.isEmpty()) {
                    ItemStack brew = BrewUtils.setCustomEffects(new ItemStack(ModItems.BREW.get()), mobEffectInstance, brewEffectInstance);
                    BrewUtils.setAreaOfEffect(brew, this.level.getRandom().nextInt(amp + 1));
                    brew.getOrCreateTag().putInt("CustomPotionColor", BrewUtils.getColor(mobEffectInstance, brewEffectInstance));
                    this.setItemSlot(EquipmentSlot.MAINHAND, brew);
                    this.usingTime = this.overwhelmed > 0 ? this.getMainHandItem().getUseDuration() / 2 : this.getMainHandItem().getUseDuration();
                    this.setUsingItem(true);
                    if (!this.isSilent()) {
                        this.level.playSound((Player)null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_DRINK, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                    }

                    AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                } else if (this.getMainHandItem().getItem() instanceof BrewItem){
                    this.usingTime = this.overwhelmed > 0 ? this.getMainHandItem().getUseDuration() / 2 : this.getMainHandItem().getUseDuration();
                    this.setUsingItem(true);
                    AttributeInstance attributeinstance = this.getAttribute(Attributes.MOVEMENT_SPEED);
                    attributeinstance.removeModifier(SPEED_MODIFIER_DRINKING);
                    attributeinstance.addTransientModifier(SPEED_MODIFIER_DRINKING);
                }
            }

            if (this.random.nextFloat() < 7.5E-4F) {
                this.level.broadcastEntityEvent(this, (byte)15);
            }
        }

        super.aiStep();
    }

@Override
	public void render(InfusionTableBlockEntity blockEntity, float partialTick, PoseStack poseStack, MultiBufferSource buffer, int combinedLight, int combinedOverlay) {
		final NonNullList<ItemStack> contents = blockEntity.getItems();
		final ItemRenderer renderer = Minecraft.getInstance().getItemRenderer();
		final Level level = blockEntity.getLevel();
		final BlockPos pos = blockEntity.getBlockPos();
		final BlockPos abovePos = pos.above();

		if (level != null) {
			if (level.getBlockState(abovePos).isSolidRender(level, abovePos))
				return;

			combinedLight = LevelRenderer.getLightColor(level, abovePos);
		}
		else {
			combinedLight = LightTexture.FULL_BRIGHT;
		}

		poseStack.pushPose();

		poseStack.scale(0.25f, 0.25f, 0.25f);
		poseStack.translate(1.25f, 4.25f, 1.25f);
		poseStack.mulPose(Axis.YP.rotationDegrees(180f));

		ItemStack input = contents.get(0);
		ItemStack output = contents.get(10);

		if (!input.isEmpty()) {
			poseStack.pushPose();
			poseStack.translate(-0.75f, 1.25f, -0.75f);
			poseStack.mulPose(Axis.YP.rotationDegrees(level.getGameTime() + partialTick));
			poseStack.scale(1.25f, 1.25f, 1.25f);

			if (!(input.getItem() instanceof BlockItem))
				poseStack.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(input, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, poseStack, buffer, blockEntity.getLevel(), 0);
			poseStack.popPose();

			if (!output.isEmpty() && RandomUtil.oneInNChance(10)) {
				Vec3 slotItemPos = Vec3.atCenterOf(blockEntity.getBlockPos())
						.add(level.random.nextGaussian() * 0.02f, 0.9, level.random.nextGaussian() * 0.02f);
				Vec3 velocity = slotItemPos.vectorTo(slotItemPos.add(0, 0.25f, 0)).scale(0.02);

				ParticleBuilder.forPositions(new ItemParticleOption(ParticleTypes.ITEM, input), slotItemPos)
						.scaleMod(0.125f)
						.gravityOverride(0)
						.velocity(velocity.x, velocity.y,	velocity.z)
						.addTransition(ToVelocityParticleTransition.create(velocity))
						.lifespan(30)
						.cutoffDistance(20)
						.spawnClientParticles(level);
			}
		}

		if (!output.isEmpty()) {
			poseStack.pushPose();
			poseStack.translate(-0.75f, 2, -0.75f);
			poseStack.mulPose(Axis.YN.rotationDegrees(level.getGameTime() + partialTick));
			poseStack.scale(1.75f, 1.75f, 1.75f);

			if (!(output.getItem() instanceof BlockItem))
				poseStack.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(output, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, poseStack, buffer, blockEntity.getLevel(), 0);
			poseStack.popPose();
		}

		for (int i = 1; i < 10; i++) {
			ItemStack stack = contents.get(i);

			if (stack.isEmpty())
				continue;

			final int row = (i - 1) % 3;
			final int column = (i - 1) / 3;

			poseStack.pushPose();
			poseStack.translate(-0.75f * row, 0, -0.75f * column);

			if (!(stack.getItem() instanceof BlockItem))
				poseStack.scale(0.5f, 0.5f, 0.5f);

			renderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLight, combinedOverlay, poseStack, buffer, blockEntity.getLevel(), 0);
			poseStack.popPose();

			if (RandomUtil.oneInNChance(input.isEmpty() ? 50 : 10)) {
				Vec3 slotItemPos = Vec3.atLowerCornerOf(blockEntity.getBlockPos())
						.add(0.3125f, 1, 0.3125f)
						.add(row * 0.1875f, 0.0625f, column * 0.1875f)
						.add(level.random.nextGaussian() * 0.02f, level.random.nextGaussian() * 0.02f, level.random.nextGaussian() * 0.02f);
				Vec3 velocity;

				if (input.isEmpty()) {
					velocity = new Vec3(level.random.nextGaussian() * 0.001f, 0.01f, level.random.nextGaussian() * 0.001f);
				}
				else {
					Vec3 targetPos = Vec3.atCenterOf(blockEntity.getBlockPos())
							.add(0, 0.95, 0);
					velocity = slotItemPos.vectorTo(targetPos).normalize().scale(0.0125f);
				}

				ParticleBuilder.forPositions(new ItemParticleOption(ParticleTypes.ITEM, stack), slotItemPos)
						.scaleMod(0.125f)
						.gravityOverride(0)
						.lifespan(30)
						.velocity(velocity.x, velocity.y,	velocity.z)
						.addTransition(ToVelocityParticleTransition.create(velocity))
						.cutoffDistance(20)
						.spawnClientParticles(level);
			}
		}

		poseStack.popPose();
	}

@SubscribeEvent
  void commonSetup(final FMLCommonSetupEvent event) {
    event.enqueueWork(() -> {
      CauldronInteraction.WATER.put(splashBottle.get(), new FillBottle(Items.SPLASH_POTION));
      CauldronInteraction.WATER.put(lingeringBottle.get(), new FillBottle(Items.LINGERING_POTION));
      CauldronInteraction.WATER.put(Items.SPLASH_POTION,    new EmptyBottleIntoWater(splashBottle,    CauldronInteraction.WATER.get(Items.SPLASH_POTION)));
      CauldronInteraction.WATER.put(Items.LINGERING_POTION, new EmptyBottleIntoWater(lingeringBottle, CauldronInteraction.WATER.get(Items.LINGERING_POTION)));
      CauldronInteraction.EMPTY.put(Items.SPLASH_POTION,    new EmptyBottleIntoEmpty(splashBottle,    CauldronInteraction.EMPTY.get(Items.SPLASH_POTION)));
      CauldronInteraction.EMPTY.put(Items.LINGERING_POTION, new EmptyBottleIntoEmpty(lingeringBottle, CauldronInteraction.EMPTY.get(Items.LINGERING_POTION)));
      // brew bottles into each other, bit weird but feels better than shapeless
      BrewingRecipeRegistry.addRecipe(new BottleBrewingRecipe(Ingredient.of(Items.GLASS_BOTTLE), Items.POTION, Items.SPLASH_POTION, new ItemStack(splashBottle)));
      BrewingRecipeRegistry.addRecipe(new BottleBrewingRecipe(Ingredient.of(MantleTags.Items.SPLASH_BOTTLE), Items.SPLASH_POTION, Items.LINGERING_POTION, new ItemStack(lingeringBottle)));
    });

    // dispense buckets
    DispenseItemBehavior dispenseBucket = new DefaultDispenseItemBehavior() {
      private final DefaultDispenseItemBehavior defaultDispenseItemBehavior = new DefaultDispenseItemBehavior();

      @Override
      public ItemStack execute(BlockSource source, ItemStack stack) {
        DispensibleContainerItem container = (DispensibleContainerItem)stack.getItem();
        BlockPos blockpos = source.getPos().relative(source.getBlockState().getValue(DispenserBlock.FACING));
