private <MODE extends IRadialMode> void render(GuiGraphicsExtractor guiGraphics, int mouseX, int mouseY, float centerX, float centerY, RadialData<MODE> radialData) {
        // Calculate number of available modes to switch between
        List<MODE> modes = radialData.getModes();
        int activeModes = modes.size();
        if (activeModes == 0) {
            //If for some reason none are available try going up a level first, and if that fails close the screen
            RadialData<?> parent = parents.pollLast();
            if (parent == null) {
                onClose();
            } else {
                this.radialData = parent;
            }
            return;
        }
        float angleSize = 360F / activeModes;

        Matrix3x2fStack matrix = guiGraphics.pose();
        matrix.pushMatrix();
        matrix.translate(centerX, centerY);

        // draw base
        // Note: While there might be slightly better performance only drawing part of the Torus given
        // other bits may be drawn by hovering or current selection, it is not practical to do so due
        // to floating point precision causing some values to have gaps in the torus, and also the light
        // colors occasionally being harder to see without the added back layer torus
        drawTorus(guiGraphics, centerX, centerY, 0, 360, 0.3F, 0.3F, 0.3F, 0.5F);

        MODE current = getCurrent(radialData);
        if (current == null) {
            //See if the radial data has a default fallback to go to
            current = radialData.getDefaultMode(modes);
        }
        // Draw segments
        //Calculate the proper section to highlight as green based on the radial data in case indexing can be optimized or
        // some pieces are actually disabled
        int section = radialData.indexNullable(modes, current);
        if (current != null && section != -1) {
            // draw current selected if any is selected
            float startAngle = -90F + 360F * (-0.5F + section) / activeModes;
            EnumColor color = current.color();
            if (color == null) {
                drawTorus(guiGraphics, centerX, centerY, startAngle, angleSize, 0.4F, 0.4F, 0.4F, 0.7F);
            } else {
                drawTorus(guiGraphics, centerX, centerY, startAngle, angleSize, color.getColor(0), color.getColor(1), color.getColor(2), 0.3F);
            }
        }

        // Draw current hovered selection and selection highlighter
        double xDiff = mouseX - centerX;
        double yDiff = mouseY - centerY;
        double distanceFromCenter = Mth.length(xDiff, yDiff);
        if (distanceFromCenter > (parents.isEmpty() ? SELECT_RADIUS : SELECT_RADIUS_WITH_PARENT)) {
            // draw mouse selection highlight
            float angle = (float) (Mth.RAD_TO_DEG * Mth.atan2(yDiff, xDiff));
            float modeSize = 180F / activeModes;
            drawTorus(guiGraphics, centerX, centerY, angle - modeSize, angleSize, 0.8F, 0.8F, 0.8F, 0.3F);

            float selectionAngle = StatUtils.wrapDegrees(angle + modeSize + 90F);
            int selectionDrawnPos = (int) (selectionAngle * (activeModes / 360F));
            selection = modes.get(selectionDrawnPos);

            // draw hovered selection
            drawTorus(guiGraphics, centerX, centerY, -90F + 360F * (-0.5F + selectionDrawnPos) / activeModes, angleSize, 0.6F, 0.6F, 0.6F, 0.7F);
        } else {
            selection = null;
        }

        record PositionedText(float x, float y, Component text) {}
        List<PositionedText> textToDraw = new ArrayList<>(parents.isEmpty() ? activeModes : activeModes + 1);
        //Draw back button if needed
        if (!parents.isEmpty()) {
            overBackButton = distanceFromCenter <= SELECT_RADIUS_WITH_PARENT;
            if (overBackButton) {
                drawTorus(guiGraphics, centerX, centerY, 0, 360, 0, SELECT_RADIUS_WITH_PARENT, 0.8F, 0.8F, 0.8F, 0.3F);
            } else {
                drawTorus(guiGraphics, centerX, centerY, 0, 360, 0, SELECT_RADIUS_WITH_PARENT, 0.3F, 0.3F, 0.3F, 0.5F);
            }
            // draw icon
            guiGraphics.blitSprite(RenderPipelines.GUI_TEXTURED, BACK_BUTTON, -12, -18, 24, 24);
            textToDraw.add(new PositionedText(0, 0, MekanismLang.BACK.translate()));
        } else {
            overBackButton = false;
        }

        // Icons
        int position = 0;
        for (MODE mode : modes) {
            float degrees = 270 + 360 * ((float) position++ / activeModes);
            float angle = Mth.DEG_TO_RAD * degrees;
            float x = Mth.cos(angle) * MIDDLE_DISTANCE;
            float y = Mth.sin(angle) * MIDDLE_DISTANCE;
            // draw icon
            guiGraphics.blitSprite(RenderPipelines.GUI_TEXTURED, mode.icon(), Math.round(x - 12), Math.round(y - 20), 24, 24);
            // queue label
            textToDraw.add(new PositionedText(x, y, mode.sliceName()));
        }

        if (!textToDraw.isEmpty()) {
            // Labels (has to be separate from icons or the icons occasionally will get extra artifacts for some reason and also then we can't batch them)
            //TODO: Is delaying them even necessary anymore?
            boolean whiteRadialText = MekanismConfig.client.whiteRadialText.get();
            for (PositionedText toDraw : textToDraw) {
                matrix.pushMatrix();
                matrix.translate(toDraw.x, toDraw.y);
                matrix.scale(0.8F, 0.8F);
                Component text = toDraw.text;
                if (whiteRadialText) {
                    text = text.copy().withStyle(ChatFormatting.RESET);
                }
                float x = -font.width(text) / 2F;
                guiGraphics.text(font, text, (int) x, font.lineHeight, 0xCCFFFFFF, true);
                matrix.popMatrix();
            }
        }
        matrix.popMatrix();
    }

public static InteractionResult doCoilUse(
			IWireCoil coil, Player player, Level world, BlockPos pos, InteractionHand hand, Direction side,
			float hitX, float hitY, float hitZ
	)
	{
		BlockEntity tileEntity = world.getBlockEntity(pos);
		if(tileEntity instanceof IImmersiveConnectable&&((IImmersiveConnectable)tileEntity).canConnect())
		{
			ItemStack stack = player.getItemInHand(hand);
			TargetingInfo targetHere = new TargetingInfo(side, hitX-pos.getX(), hitY-pos.getY(), hitZ-pos.getZ());
			WireType wire = coil.getWireType(stack);
			BlockPos masterPos = ((IImmersiveConnectable)tileEntity).getConnectionMaster(wire, targetHere);
			BlockPos masterOffsetHere = pos.subtract(masterPos);
			tileEntity = world.getBlockEntity(masterPos);
			if(!(tileEntity instanceof IImmersiveConnectable iicHere)||!iicHere.canConnect())
				return InteractionResult.PASS;
			ConnectionPoint cpHere = iicHere.getTargetedPoint(targetHere, masterOffsetHere);

			if(cpHere==null||!iicHere.canConnectCable(wire, cpHere, masterOffsetHere)||
					!coil.canConnectCable(stack, tileEntity))
			{
				if(!world.isClientSide)
					player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"wrongCable"), true);
				return InteractionResult.FAIL;
			}

			if(!world.isClientSide)
			{
				final WireLink storedLink = stack.get(IEApiDataComponents.WIRE_LINK);
				if(storedLink==null)
					stack.set(IEApiDataComponents.WIRE_LINK, WireLink.create(cpHere, world, masterOffsetHere, targetHere));
				else
				{
					BlockEntity tileEntityLinkingPos = world.getBlockEntity(storedLink.cp().position());
					int distanceSq = (int)Math.ceil(storedLink.cp().position().distSqr(masterPos));
					int maxLengthSq = coil.getMaxLength(stack); //not squared yet
					maxLengthSq *= maxLengthSq;
					if(!storedLink.dimension().equals(world.dimension()))
						player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"wrongDimension"), true);
					else if(storedLink.cp().position().equals(masterPos))
						player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"sameConnection"), true);
					else if(distanceSq > maxLengthSq)
						player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"tooFar"), true);
					else
					{
						if(!(tileEntityLinkingPos instanceof IImmersiveConnectable iicLink))
							player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"invalidPoint"), true);
						else
						{
							if(!iicLink.canConnectCable(wire, storedLink.cp(), storedLink.offset())||
									!iicLink.getConnectionMaster(wire, storedLink.target()).equals(storedLink.cp().position())||
									!coil.canConnectCable(stack, tileEntityLinkingPos))
							{
								player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"invalidPoint"), true);
							}
							else
							{
								GlobalWireNetwork net = GlobalWireNetwork.getNetwork(world);
								boolean connectionExists = false;
								LocalWireNetwork localA = net.getLocalNet(cpHere);
								LocalWireNetwork localB = net.getLocalNet(storedLink.cp());
								if(localA==localB)
								{
									Collection<Connection> outputs = localA.getConnections(cpHere);
									if(outputs!=null)
										for(Connection con : outputs)
											if(!con.isInternal()&&con.getOtherEnd(cpHere).equals(storedLink.cp()))
												connectionExists = true;
								}
								if(connectionExists)
									player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"connectionExists"), true);
								else
								{
									Set<BlockPos> ignore = new HashSet<>();
									ignore.addAll(iicHere.getIgnored(iicLink));
									ignore.addAll(iicLink.getIgnored(iicHere));
									Connection conn = new Connection(wire, cpHere, storedLink.cp(), net);
									Set<BlockPos> failedReasons = findObstructingBlocks(world, conn, ignore);
									if(failedReasons.isEmpty())
									{
										net.addConnection(conn);

										iicHere.connectCable(wire, cpHere, iicLink, storedLink.cp());
										iicLink.connectCable(wire, storedLink.cp(), iicHere, cpHere);
										Utils.unlockIEAdvancement(player, "main/connect_wire");

										if(!player.getAbilities().instabuild)
											coil.consumeWire(stack, (int)Math.sqrt(distanceSq));
										((BlockEntity)iicHere).setChanged();
										//TODO is this needed with the new sync system?
										world.blockEvent(masterPos, ((BlockEntity)iicHere).getBlockState().getBlock(), -1, 0);
										BlockState state = world.getBlockState(masterPos);
										world.sendBlockUpdated(masterPos, state, state, 3);
										((BlockEntity)iicLink).setChanged();
										world.blockEvent(storedLink.cp().position(), tileEntityLinkingPos.getBlockState().getBlock(), -1, 0);
										state = world.getBlockState(storedLink.cp().position());
										world.sendBlockUpdated(storedLink.cp().position(), state, state, 3);
									}
									else
									{
										player.displayClientMessage(Component.translatable(Lib.CHAT_WARN+"cantSee"), true);
										PacketDistributor.sendToPlayer(
												(ServerPlayer)player,
												new MessageObstructedConnection(failedReasons, new SyncedConnection(conn))
										);
									}
								}
							}
						}
					}
					stack.remove(IEApiDataComponents.WIRE_LINK);
				}
			}
			return InteractionResult.SUCCESS;
		}
		return InteractionResult.PASS;
	}

@Override
	public void onUpdate() {
		if(getStaminaTicks() <= 0 && isBeingRidden() && getPassengers().get(0) instanceof EntityBLFishHook) {
			this.nettableTimer = MAX_NETTABLE_TIME;
		} else if(this.nettableTimer > 0) {
			this.nettableTimer--;
		}

		if (getEntityWorld().isRemote) {
			setSize(getFishSize(), getFishSize() * 0.75F);

			if(getEntityWorld().getTotalWorldTime()%4 == 0)
				animationFrame += 16;
			if(animationFrame > 48)
				animationFrame = 0;

			animationFrameCrab += 16;
			if(animationFrameCrab > 48)
				animationFrameCrab = 0;
		}

		if(!getEntityWorld().isRemote) {
			if(getAttackTarget() != null && !getEntityWorld().containsAnyLiquid(getAttackTarget().getEntityBoundingBox())) {
				double distance = getPosition().getDistance((int) getAttackTarget().posX, (int) getAttackTarget().posY, (int) getAttackTarget().posZ);
				if (distance > 1.0F && distance < 6.0F)
					if (isInWater() && getEntityWorld().isAirBlock(new BlockPos((int) posX, (int) posY + 1, (int) posZ))) 
						leapAtTarget(getAttackTarget().posX, getAttackTarget().posY, getAttackTarget().posZ);
			}

			//			if(getHungerCooldown() >= 0)
			//				setHungerCooldown(getHungerCooldown() - 1);

			//regains stamina over time whilst not hooked
			if(!isBeingRidden() ) {
				playAnadiaWonSound = true;

				if(getEscapeDelay() < (int) getStaminaMods() * 30)
					setEscapeDelay((int) (getStaminaMods() * 30));

				if(getStaminaTicks() < (int) (getStaminaMods() * 20))
					setStaminaTicks(getStaminaTicks() + 1);
				//if(getEscapeTicks() < 1024)
				//	setEscapeTicks(1024);
				if(getObstruction1Ticks() < 256)
					setObstruction1Ticks(256);
				if(getObstruction2Ticks() < 256)
					setObstruction2Ticks(256);
				if(getObstruction3Ticks() < 256)
					setObstruction3Ticks(256);
				if(getObstruction4Ticks() < 512)
					setObstruction4Ticks(512);
				if(getTreasureTicks() < 1024)
					setTreasureTicks(1024);
			}

			if (isBeingRidden() && getPassengers().get(0) instanceof EntityBLFishHook) {
				EntityBLFishHook hook = (EntityBLFishHook) getPassengers().get(0);

				if (getStaminaTicks() <= 0 && playAnadiaWonSound) {
					if (hook != null && hook.getAngler() != null)
						playAnadiaWonSound(hook.getAngler());
					playAnadiaWonSound = false;
					this.getNavigator().clearPath();
				}

				if (getStaminaTicks() > 0 && getEscapeDelay() > 0) {
					setEscapeDelay(getEscapeDelay() - 1);

					if (getEscapeDelay() == 10)
						if (hook != null && hook.getAngler() != null)
							playAnadiaCrab(hook.getAngler());
				}

				if (getEscapeTicks() > 0 && getEscapeDelay() <= 0)
					setEscapeTicks(getEscapeTicks() - 3);

				if (getEscapeTicks() * 256 / 1024 < getStaminaTicks() * 256 / 180 && getEscapeDelay() <= 0) {
					if (hook != null && hook.getAngler() != null) {
						playAnadiaLostSound(hook.getAngler());
						getPassengers().get(0).dismountRidingEntity(); // this just  releases the fish atm
					}
				}

				if (getObstruction1Ticks() >= 0) {
					setObstruction1Ticks(getObstruction1Ticks() - 1);
					if (getObstruction1Ticks() <= 0)
						setObstruction1Ticks(256);
				}

				if (getObstruction2Ticks() >= 0) {
					setObstruction2Ticks(getObstruction2Ticks() - 2);
					if (getObstruction2Ticks() <= 0)
						setObstruction2Ticks(256);
				}

				if (getObstruction3Ticks() >= 0) {
					setObstruction3Ticks(getObstruction3Ticks() - 1);
					if (getObstruction3Ticks() <= 0)
						setObstruction3Ticks(256);
				}

				if (getObstruction4Ticks() >= 0) {
					setObstruction4Ticks(getObstruction4Ticks() - 1);
					if (getObstruction4Ticks() <= 0)
						setObstruction4Ticks(512);
				}

				if (isTreasureFish() && getTreasureTicks() >= 0) {
					setTreasureTicks(getTreasureTicks() - 1);
					if (getTreasureTicks() <= 0) {
						if (getTreasureUnlocked())
							setIsTreasureFish(false);
						setTreasureTicks(1024);
					}
				}
			}
		}
		super.onUpdate();
	}

@Nullable
	public boolean pullNext(BlockPos root, boolean simulate) {
		if (!frontier.isEmpty())
			return false;
		if (!Objects.equals(root, rootPos)) {
			rebuildContext(root);
			return false;
		}

		if (counterpartActed) {
			counterpartActed = false;
			softReset(root);
			return false;
		}

		if (affectedArea == null)
			affectedArea = BoundingBox.fromCorners(root, root);

		Level world = getWorld();
		if (!queue.isEmpty() && !isValid) {
			rebuildContext(root);
			return false;
		}

		if (validationFrontier.isEmpty() && !queue.isEmpty() && !simulate && revalidateIn == 0)
			revalidate(root);

		if (infinite) {
			blockEntity.award(AllAdvancements.HOSE_PULLEY);
			if (FluidHelper.isLava(fluid))
				blockEntity.award(AllAdvancements.HOSE_PULLEY_LAVA);

			playEffect(world, root, fluid, true);
			return true;
		}

		while (!queue.isEmpty()) {
			// Dont dequeue here, so we can decide not to dequeue a valid entry when
			// simulating
			BlockPos currentPos = queue.first()
				.pos();

			BlockState blockState = world.getBlockState(currentPos);
			BlockState emptied = blockState;
			Fluid fluid = Fluids.EMPTY;

			if (blockState.hasProperty(BlockStateProperties.WATERLOGGED)
				&& blockState.getValue(BlockStateProperties.WATERLOGGED)) {
				emptied = blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.valueOf(false));
				fluid = Fluids.WATER;
			} else if (blockState.getBlock() instanceof LiquidBlock flowingFluid) {
				emptied = Blocks.AIR.defaultBlockState();
				if (blockState.getValue(LiquidBlock.LEVEL) == 0)
					fluid = flowingFluid.fluid;
				else {
					affectedArea = BBHelper.encapsulate(affectedArea, BoundingBox.fromCorners(currentPos, currentPos));
					if (!blockEntity.isVirtual())
						world.setBlock(currentPos, emptied, 2 | 16);
					queue.dequeue();
					if (queue.isEmpty()) {
						isValid = checkValid(world, rootPos);
						reset();
					}
					continue;
				}
			} else if (blockState.getFluidState()
				.getType() != Fluids.EMPTY && blockState.getCollisionShape(world, currentPos, CollisionContext.empty())
				.isEmpty()) {
				fluid = blockState.getFluidState()
					.getType();
				emptied = Blocks.AIR.defaultBlockState();
			}

			if (this.fluid == null)
				this.fluid = fluid;

			if (!this.fluid.isSame(fluid)) {
				queue.dequeue();
				if (queue.isEmpty()) {
					isValid = checkValid(world, rootPos);
					reset();
				}
				continue;
			}

			if (simulate)
				return true;

			playEffect(world, currentPos, fluid, true);
			blockEntity.award(AllAdvancements.HOSE_PULLEY);

			if (!blockEntity.isVirtual()) {
				world.setBlock(currentPos, emptied, 2 | 16);

				BlockState stateAbove = world.getBlockState(currentPos.above());
				if (stateAbove.getFluidState()
					.getType() == Fluids.EMPTY && !stateAbove.canSurvive(world, currentPos.above()))
					world.setBlock(currentPos.above(), Blocks.AIR.defaultBlockState(), 2 | 16);
			}
			affectedArea = BBHelper.encapsulate(affectedArea, currentPos);

			queue.dequeue();
			if (queue.isEmpty()) {
				isValid = checkValid(world, rootPos);
				reset();
			} else if (!validationSet.contains(currentPos)) {
				reset();
			}
			return true;
		}

		if (rootPos == null)
			return false;

		if (isValid)
			rebuildContext(root);

		return false;
	}

@Override
	public IMessage onMessage(Message message, MessageContext ctx){

		// Just to make sure that the side is correct
		if(ctx.side.isServer()){

			final EntityPlayerMP player = ctx.getServerHandler().player;

			player.getServerWorld().addScheduledTask(() -> {

				ItemStack wand = player.getHeldItemMainhand();

				if(!(wand.getItem() instanceof ISpellCastingItem)){
					wand = player.getHeldItemOffhand();
				}

				switch(message.controlType){

				case APPLY_BUTTON:

					if(!(player.openContainer instanceof ContainerArcaneWorkbench)){
						Wizardry.logger.warn("Received a PacketControlInput, but the player that sent it was not " +
								"currently using an arcane workbench. This should not happen!");
					}else{
						((ContainerArcaneWorkbench)player.openContainer).onApplyButtonPressed(player);
					}

					break;

				case CLEAR_BUTTON:

					if(!(player.openContainer instanceof ContainerArcaneWorkbench)){
						Wizardry.logger.warn("Received a PacketControlInput, but the player that sent it was not " +
								"currently using an arcane workbench. This should not happen!");
					}else{
						((ContainerArcaneWorkbench)player.openContainer).onClearButtonPressed(player);
					}

					break;

				case NEXT_SPELL_KEY:

					if(wand.getItem() instanceof ISpellCastingItem){

						((ISpellCastingItem)wand.getItem()).selectNextSpell(wand);
						// This line fixes the bug with continuous spells casting when they shouldn't be
						player.stopActiveHand();
					}

					break;

				case PREVIOUS_SPELL_KEY:

					if(wand.getItem() instanceof ISpellCastingItem){

						((ISpellCastingItem)wand.getItem()).selectPreviousSpell(wand);
						// This line fixes the bug with continuous spells casting when they shouldn't be
						player.stopActiveHand();
					}

					break;

				case RESURRECT_BUTTON:

					if(player.isDead && Resurrection.getRemainingWaitTime(player.deathTime) == 0){

						ItemStack stack = InventoryUtils.getHotbar(player).stream()
								.filter(s -> Resurrection.canStackResurrect(s, player)).findFirst().orElse(null);

						if(stack != null){
							if(MinecraftForge.EVENT_BUS.post(new ResurrectionEvent(player, player))) break;
							// This should suffice, since this is the only way a player can cast resurrection when dead!
							((ISpellCastingItem)stack.getItem()).cast(stack, Spells.resurrection, player, EnumHand.MAIN_HAND, 0, new SpellModifiers());
							break;
						}
					}

					Wizardry.logger.warn("Received a resurrect button packet, but the player that sent it was not" +
							" currently able to resurrect. This should not happen!");

					break;

				case CANCEL_RESURRECT:

					if(player.world.getGameRules().getBoolean("keepInventory")) break; // Shouldn't even receive this

					if(player.isDead){

						ItemStack stack = InventoryUtils.getHotbar(player).stream()
								.filter(s -> Resurrection.canStackResurrect(s, player)).findFirst().orElse(null);

						if(stack != null){
							player.dropItem(stack, true, false);
							player.inventory.deleteStack(stack); // Might as well
							break;
						}

						Wizardry.logger.warn("Received a cancel resurrect packet, but the player that sent it was not" +
								" holding a wand with the resurrection spell. This should not happen!");
					}

					Wizardry.logger.warn("Received a cancel resurrect packet, but the player that sent it was not" +
							" currently dead. This should not happen!");

					break;

				case POSSESSION_PROJECTILE:

					if(!Possession.isPossessing(player)) Wizardry.logger.warn("Received a possession projectile packet, " +
							"but the player that sent it is not currently possessing anything!");

					Possession.shootProjectile(player);

					break;
				}
			});
		}

		return null;
	}

