public void tick() {
        skipTravel = false;
        Entity entity = this.getOwner();
        var behaviour = getBehaviour();
        var spellEntry = getSpellEntry();
        if (!this.getWorld().isClient) {
            // Server side
            if (spellEntry == null) {
                System.err.println("Spell Projectile safeguard termination, failed to resolve spell: " + spellId());
                this.kill();
                return;
            }
            switch (behaviour) {
                case FLY -> {
                    if (distanceTraveled >= range || age > 1200) { // 1200 ticks = 1 minute
                        this.kill();
                        return;
                    }
                }
                case FALL -> {
                    var fallDistance = range * 0.98F;
                    if (distanceTraveled >= fallDistance) {
                        // Travel advances in whole velocity steps, so this threshold is overshot
                        // by up to a full step (e.g. velocity 1.5 against a 9.8 threshold ends
                        // 0.7 too low — below the aimed surface). Snap back along the travel
                        // direction so the impact and its area FX land where the threshold was
                        // actually crossed.
                        var overshoot = distanceTraveled - fallDistance;
                        var velocity = this.getVelocity();
                        if (overshoot > 0 && velocity.lengthSquared() > 1e-6) {
                            this.setPosition(this.getPos().subtract(velocity.normalize().multiply(overshoot)));
                        }
                        finishFalling();
                        this.kill();
                        return;
                    }
                    if (age > 1200) { // 1200 ticks = 1 minute
                        this.kill();
                        return;
                    }
                }
            }
            if (distanceTraveled >= range || age > 1200) { // 1200 ticks = 1 minute
                this.kill();
                return;
            }
        }
        this.previousVelocity = new Vec3d(getVelocity().x, getVelocity().y, getVelocity().z);
        if (this.getWorld().isClient || (entity == null || !entity.isRemoved()) && this.getWorld().isChunkLoaded(this.getBlockPos())) {
            super.tick();

            if (!getWorld().isClient) {
                HitResult hitResult = ProjectileUtil.getCollision(this, this::canHit);
                var data = projectileData();
                if (data != null && data.hitbox != null) {
                    if (hitResult.getType() == HitResult.Type.BLOCK) {
                        // Block hit: handle normally (preserves bounce/block-impact)
                        handleHitResult(hitResult, behaviour, spellEntry);
                    } else {
                        // Entity/miss from raycast: discard, use swept OBB detection instead
                        performVolumetricEntityCollision(behaviour, spellEntry, data);
                    }
                } else {
                    // RAYCAST mode (default) — original path with intersects bug fixed
                    handleHitResult(hitResult, behaviour, spellEntry);
                    if (hitResult.getType() == HitResult.Type.MISS && hasCustomDimensions) {
                        var boundingBox = this.getBoundingBox();
                        for (Entity areaTarget : this.getWorld().getOtherEntities(entity, this.getBoundingBox().expand(1), this::canHit)) {
                            if (areaTarget.getBoundingBox().intersects(boundingBox)) {
                                var areaHitResult = new EntityHitResult(areaTarget);
                                handleHitResult(areaHitResult, behaviour, spellEntry);
                            }
                        }
                    }
                }
            }

            this.checkBlockCollision();

            // Travel
            if (!skipTravel) {
                this.followTarget();
                // Flight physics (gravity/drag) run after homing and before the move, so homing
                // aims first and drag then damps the whole velocity (vanilla order). May expire
                // the projectile via `min_speed`.
                applyMotion();
                if (this.isRemoved()) {
                    return;
                }
                Vec3d velocity = this.getVelocity();
                double d = this.getX() + velocity.x;
                double e = this.getY() + velocity.y;
                double f = this.getZ() + velocity.z;
                ProjectileUtil.setRotationFromVelocity(this, 0.2F);

                if (this.isTouchingWater()) {
                    for(int i = 0; i < 4; ++i) {
                        this.getWorld().addParticle(ParticleTypes.BUBBLE, d - velocity.x * 0.25, e - velocity.y * 0.25, f - velocity.z * 0.25, velocity.x, velocity.y, velocity.z);
                    }
                }

                var data = projectileData();
                if (data != null) {
                    if (getWorld().isClient) {
                        for (var travel_particles : data.client_data.travel_particles) {
                            ParticleHelper.play(getWorld(), this, getYaw(), getPitch(), travel_particles);
                        }
                    } else {
                        if (data.travel_sound != null && age % data.travel_sound_interval == 0) {
                            SoundHelper.playSound(getWorld(), this, data.travel_sound);
                        }
                    }
                }

                this.setPosition(d, e, f);
                this.distanceTraveled += velocity.length();
            }
        } else {
            this.discard();
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();
		// TODO in case we want an animation grab smoothedAngle(float partialTicks) method for render class
		prevRotationTicks = rotationTicks;
		rotationTicks += 15;
		float wrap = MathHelper.wrapDegrees(rotationTicks) - rotationTicks;
		rotationTicks +=wrap;
		prevRotationTicks += wrap;

		if (!getEntityWorld().isRemote) {
			if(getHasExploded()) {
				if (getEntityWorld().getTotalWorldTime() % 5 == 0)
					checkAreaOfEffect();
				if (getAOESizeXZ() > 0.5F)
					setAOESizeXZ(getAOESizeXZ() - 0.01F);
				if (getAOESizeXZ() <= 0.5F)
					setDead();
			}
		} else {
			if (!getHasExploded() && this.ticksExisted % 4 == 0) {
				this.spawnDroppingsParticles();
			}
		}

		if (getHasExploded())
			setBoundingBoxSize();

		if (getEntityWorld().isRemote)
			if(getHasExploded())
				spawnCloudParticle();

		lastTickPosX = posX;
        lastTickPosY = posY;
        lastTickPosZ = posZ;

        Vec3d poopVector = new Vec3d(posX, posY, posZ);
        Vec3d poopMovementVector = new Vec3d(posX + motionX, posY + motionY, posZ + motionZ);
        RayTraceResult raytraceresult = world.rayTraceBlocks(poopVector, poopMovementVector);
        poopVector = new Vec3d(posX, posY, posZ);
        poopMovementVector = new Vec3d(posX + motionX, posY + motionY, posZ + motionZ);

        if (raytraceresult != null)
        	poopMovementVector = new Vec3d(raytraceresult.hitVec.x, raytraceresult.hitVec.y, raytraceresult.hitVec.z);

        Entity entityCollidedWith = null;
        List<Entity> list = world.getEntitiesWithinAABBExcludingEntity(this, getEntityBoundingBox().expand(motionX, motionY, motionZ).grow(1.0D));
        double collisionDistance = 0D;
        boolean miss = false;

        for (int entityCount = 0; entityCount < list.size(); ++entityCount)  {
            Entity entityInList = list.get(entityCount);

            if (entityInList.canBeCollidedWith()) {
                if (entityInList == ignoreEntity)
                	miss = true;
                else if (thrower != null && ticksExisted < 2 && ignoreEntity == null) {
                    ignoreEntity = entityInList;
                    miss = true;
                }
                else {
                	miss = false;
                    AxisAlignedBB axisalignedbb = entityInList.getEntityBoundingBox().grow(0.30000001192092896D);
                    RayTraceResult raytraceresult1 = axisalignedbb.calculateIntercept(poopVector, poopMovementVector);

                    if (raytraceresult1 != null) {
                        double inpactDistance = poopVector.squareDistanceTo(raytraceresult1.hitVec);

                        if (inpactDistance < collisionDistance || collisionDistance == 0.0D) {
                        	entityCollidedWith = entityInList;
                            collisionDistance = inpactDistance;
                        }
                    }
                }
            }
        }

        if (ignoreEntity != null)
            if (miss)
                ignoreTime = 2;
            else if (ignoreTime-- <= 0)
                ignoreEntity = null;

        if (entityCollidedWith != null)
            raytraceresult = new RayTraceResult(entityCollidedWith);

        if (raytraceresult != null)
            if (raytraceresult.typeOfHit == RayTraceResult.Type.BLOCK && world.getBlockState(raytraceresult.getBlockPos()).getBlock() == Blocks.PORTAL)
                setPortal(raytraceresult.getBlockPos());
            else if (!net.minecraftforge.event.ForgeEventFactory.onProjectileImpact(this, raytraceresult))
                onImpact(raytraceresult);

        posX += motionX;
        posY += motionY;
        posZ += motionZ;

        float fallAmount = 0.99F;
        float fallAmountWithGravity = getGravityVelocity();

        if (isInWater()) {
            for (int particleCount = 0; particleCount < 4; ++particleCount)
                world.spawnParticle(EnumParticleTypes.WATER_BUBBLE, posX - motionX * 0.25D, posY - motionY * 0.25D, posZ - motionZ * 0.25D, motionX, motionY, motionZ);
            fallAmount = 0.8F;
        }

        if(getHasExploded())
        	fallAmount = 0.0F;

        motionX *= (double)fallAmount;
        motionY *= (double)fallAmount;
        motionZ *= (double)fallAmount;

        if (!hasNoGravity())
            motionY -= (double)fallAmountWithGravity;

        if (raytraceresult != null)
        	if(getHasExploded())
        		if(posY < raytraceresult.hitVec.y)
        			posY = raytraceresult.hitVec.y;

        setPosition(posX, posY, posZ);
	}

public void tick() {
        RecipeHolder<RitualRecipe> recipe = this.getCurrentRitualRecipe();
        if (!this.level.isClientSide() && recipe != null) {
            this.restoreCastingPlayer();

            if (this.remainingAdditionalIngredients == null) {
                this.restoreRemainingAdditionalIngredients();
                if (this.remainingAdditionalIngredients == null) {
                    Occultism.LOGGER
                            .warn("Could not restore remainingAdditionalIngredients during tick - level seems to be null. Will attempt again next tick.");
                    return;
                }
            }

            if (!recipe.value().getRitual().isValid(this.level, this.getBlockPos(), this, this.castingPlayer,
                    this.itemStackHandler.getResource(0).toStack(), this.remainingAdditionalIngredients)) {
                //ritual is no longer valid, so interrupt
                this.stopRitual(false);
                return;
            }

            //if we do not have a sacrifice yet, we cannot advance time
            if (!this.sacrificeFulfilled() || !this.itemUseFulfilled()) {
                if (this.level.getGameTime() % 20 == 0)
                    this.level.updateNeighborsAt(this.getBlockPos(), this.getBlockState().getBlock());

                if (this.level.getRandom().nextInt(16) == 0) {
                    ((ServerLevel) this.level)
                            .sendParticles(OccultismParticles.RITUAL_WAITING.get(),
                                    this.getBlockPos().getX() + this.level.getRandom().nextGaussian(),
                                    this.getBlockPos().getY() + 0.5, this.getBlockPos().getZ() + this.level.getRandom().nextGaussian(),
                                    3,
                                    0.0, 0.0, 0.0,
                                    0.0);
                    ((ServerLevel) this.level)
                            .sendParticles(OccultismParticles.RITUAL_WAITING.get(),
                                    this.getBlockPos().getX() + this.level.getRandom().nextGaussian(),
                                    this.getBlockPos().getY() + 0.5, this.getBlockPos().getZ() + this.level.getRandom().nextGaussian(),
                                    3,
                                    0.0, 0.0, 0.0,
                                    0.0);
                    ((ServerLevel) this.level)
                            .sendParticles(OccultismParticles.RITUAL_WAITING.get(),
                                    this.getBlockPos().getX() + this.level.getRandom().nextGaussian(),
                                    this.getBlockPos().getY() + 0.5, this.getBlockPos().getZ() + this.level.getRandom().nextGaussian(),
                                    3,
                                    0.0, 0.0, 0.0,
                                    0.0);
                }
                return;
            }

            //spawn particles in random intervals
            if (this.level.getRandom().nextInt(16) == 0) {
                ((ServerLevel) this.level)
                        .sendParticles(ParticleTypes.PORTAL, this.getBlockPos().getX() + 0.5 + this.level.getRandom().nextGaussian() / 3,
                                this.getBlockPos().getY() + 0.5, this.getBlockPos().getZ() + 0.5 + this.level.getRandom().nextGaussian() / 3, 5,
                                0.0, 0.0, 0.0,
                                0.0);
            }

            //spawn particles in bowl before consume next item
            if (this.level.getGameTime() % 5 == 0) {
                if (!this.remainingAdditionalIngredients.isEmpty()) {
                    recipe.value().getRitual().markNextIngredient(this.level, this.getBlockPos(), this.remainingAdditionalIngredients.getFirst(), this.getTier(this.getBlockState()));
                } else {
                    double gameTime = this.level.getGameTime() * 0.05;
                    double sin = Math.sin(gameTime) * 0.3;
                    double cos = Math.cos(gameTime) * 0.3;
                    Vec3 center = this.getBlockPos().getCenter();
                    ((ServerLevel) this.level)
                            .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x + cos, center.y + 0.2 + cos, center.z + sin,
                                    1, 0.0, 0.0, 0.0, 0.003);
                    if (this.getTier(this.getBlockState()) == 2) {
                        double sin2 = Math.sin(gameTime + (Math.PI * 0.5)) * 0.3;
                        double cos2 = Math.cos(gameTime + (Math.PI * 0.5)) * 0.3;
                        ((ServerLevel) this.level)
                                .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x + cos2, center.y + 0.2 + sin2, center.z + sin2,
                                        1, 0.0, 0.0, 0.0, 0.003);
                        ((ServerLevel) this.level)
                                .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x - cos2, center.y + 0.2 + cos2, center.z - sin2,
                                        1, 0.0, 0.0, 0.0, 0.003);
                        ((ServerLevel) this.level)
                                .sendParticles(OccultismParticles.SPIRIT_FIRE_FLAME.get(), center.x - cos, center.y + 0.2 + sin, center.z - sin,
                                        1, 0.0, 0.0, 0.0, 0.003);
                    }
                }
            }

            //Advance ritual time every second, based on the standard 20 tps, but taking into account duration multiplier
            if (this.getTier(this.getBlockState()) == 1) { //golden bowl
                if (this.level.getGameTime() % ((int) (20 * Occultism.SERVER_CONFIG.rituals.ritualDurationMultiplier.get())) == 0) {
                    this.currentTime++;
                }
            } else if (this.getTier(this.getBlockState()) == 2) {
                if (Occultism.SERVER_CONFIG.rituals.ritualDurationMultiplier.get() < 0.2) { //avoiding crash of divide by 0 with iesnium bowl
                    this.currentTime++;
                } else if (this.level.getGameTime() % ((int) (5 * Occultism.SERVER_CONFIG.rituals.ritualDurationMultiplier.get())) == 0) {
                    this.currentTime++;
                }
            } else {
                this.currentTime = recipe.value().getDuration();
            }

            recipe
                    .value().getRitual()
                    .update(this.level, this.getBlockPos(), this, this.castingPlayer, this.itemStackHandler.getResource(0).toStack(),
                            this.currentTime);

            if (!recipe
                    .value().getRitual()
                    .consumeAdditionalIngredients(this.level, this.getBlockPos(), this.remainingAdditionalIngredients,
                            this.currentTime, this.consumedIngredients)) {
                //if ingredients cannot be found, interrupt
                this.stopRitual(false);
                return;
            }

            if (recipe.value().getDuration() >= 0 && this.currentTime >= recipe.value().getDuration())
                this.stopRitual(true);
        }
    }

@Override
    protected void generate() {
        OccultismBlocks.BLOCKS.getEntries().stream()
                .map(DeferredHolder::get)
                .forEach(block -> {
                    BlockDataGenSettings settings = OccultismBlocks.BLOCK_DATA_GEN_SETTINGS
                            .get(BuiltInRegistries.BLOCK.getKey(block));
                    if (settings == null) {
                        Occultism.LOGGER.warn("No block data-gen settings for block {}. Skipping loot table generation.",
                                BuiltInRegistries.BLOCK.getKey(block));
                        return;
                    }

                    if (settings.lootTableType == LootTableType.EMPTY)
                        this.registerDropNothingLootTable(block);
                    else if (settings.lootTableType == LootTableType.REPLANTABLE_CROP) {
                        IReplantableCrops cropsBlock = (IReplantableCrops) block;
                        LootItemCondition.Builder lootCondition =
                                LootItemBlockStatePropertyCondition.hasBlockStateProperties(block).setProperties(
                                        Builder.properties()
                                                .hasProperty(CropBlock.AGE, 7));
                        this.add(block,
                                this.createCropDrops(block, cropsBlock.getCropsItem().asItem(),
                                        cropsBlock.getSeedsItem().asItem(), lootCondition));
                    } else if (settings.lootTableType == LootTableType.DROP_SELF) {
                        if (block.asItem() != Items.AIR) {
                            this.dropSelf(block);
                        } else {
                            Occultism.LOGGER.warn("Block {} has DROP_SELF loot type but its item is AIR. Skipping.",
                                    BuiltInRegistries.BLOCK.getKey(block));
                        }
                    } else if (settings.lootTableType == LootTableType.OTHERWORLD_BLOCK)
                        this.registerOtherworldBlockTable(block);
                });

        this.add(OccultismBlocks.OTHERWORLD_LEAVES.get(),
                (block) -> this.createLeavesDrops(block, OccultismBlocks.OTHERWORLD_SAPLING.get(), DEFAULT_SAPLING_DROP_RATES)
