@Override
	public void tickServer()
	{
		ItemStack seed = inventory.get(SLOT_SEED);
		ItemStack soil = inventory.get(SLOT_SOIL);
		if(!seed.isEmpty())
		{
			ClocheRecipe recipe = cachedRecipe.get();
			int consumption = IEServerConfig.MACHINES.cloche_consumption.get();
			//Consume needs to be outside of seed check in case power runs down while there is still a seed, to properly propagate updates to the client
			boolean consume = false;
			if(recipe!=null&&fertilizerAmount > 0&&energyStorage.extractEnergy(consumption, true)==consumption)
			{
				if(growth >= recipe.getTime(seed, soil))
				{
					NonNullList<ItemStack> outputs = recipe.getOutputs(seed, soil);
					int canFit = 0;
					boolean[] emptySlotsUsed = new boolean[4];
					for(ItemStack output : outputs)
						if(!output.isEmpty())
							for(int j = 3; j < 7; j++)
							{
								ItemStack existing = inventory.get(j);
								if((existing.isEmpty()&&!emptySlotsUsed[j-3])||(ItemStack.isSameItemSameComponents(existing, output)&&existing.getCount()+output.getCount() <= existing.getMaxStackSize()))
								{
									canFit++;
									if(existing.isEmpty())
										emptySlotsUsed[j-3] = true;
									break;
								}
							}
					if(canFit >= outputs.size())
					{
						for(ItemStack output : outputs)
							for(int j = 3; j < 7; j++)
							{
								ItemStack existing = inventory.get(j);
								if(existing.isEmpty())
								{
									inventory.set(j, output.copy());
									break;
								}
								else if(ItemStack.isSameItemSameComponents(existing, output)&&existing.getCount()+output.getCount() <= existing.getMaxStackSize())
								{
									existing.grow(output.getCount());
									break;
								}
							}
						growth = 0;
						consume = true;
					}
				}
				else
				{
					growth += IEServerConfig.MACHINES.cloche_growth_mod.get()*fertilizerMod;
					consume = true;
					if(level.getGameTime()%32==((getBlockPos().getX()^getBlockPos().getZ())&31))
						sendSyncPacket();
				}
				if(consume)
				{
					energyStorage.extractEnergy(consumption, false);
					fertilizerAmount--;
					if(!renderActive)
					{
						renderActive = true;
						sendSyncPacket();
					}
				}
			}
			else
			{
				growth = 0;
				if(renderActive)
				{
					renderActive = false;
					sendSyncPacket();
				}
			}

			int fluidConsumption = IEServerConfig.MACHINES.cloche_fluid.get();
			if(fertilizerAmount <= 0&&tank.getFluidAmount() >= fluidConsumption)
			{
				fertilizerMod = 1;
				tank.drain(fluidConsumption, FluidAction.EXECUTE);
				ItemStack fertilizer = inventory.get(SLOT_FERTILIZER);
				if(!fertilizer.isEmpty())
				{
					float itemMod = ClocheFertilizer.getFertilizerGrowthModifier(level, fertilizer);
					if(itemMod > 0)
					{
						fertilizerMod *= itemMod;
						fertilizer.shrink(1);
						if(fertilizer.getCount() <= 0)
							inventory.set(2, ItemStack.EMPTY);
					}
				}
				fertilizerAmount = IEServerConfig.MACHINES.cloche_fertilizer.get();
			}
		}
		else
			growth = 0;

		if(level.getGameTime()%8==0)
		{
			IItemHandler outputHandler = output.getCapability();
			if(outputHandler!=null)
				for(int j = 3; j < 7; j++)
				{
					ItemStack outStack = inventory.get(j);
					if(!outStack.isEmpty())
					{
						int outCount = Math.min(outStack.getCount(), 16);
						ItemStack stack = outStack.copyWithCount(outCount);
						stack = ItemHandlerHelper.insertItem(outputHandler, stack, false);
						if(!stack.isEmpty())
							outCount -= stack.getCount();
						outStack.shrink(outCount);
						if(outStack.getCount() <= 0)
							this.inventory.set(j, ItemStack.EMPTY);
					}
				}
		}
	}

public void tick(){
        if (this.level != null) {
            if (!this.level.isClientSide) {
                if (this.checkFire()) {
                    int waterLevel = this.getBlockState().getValue(ModStateProperties.LEVEL_BREW);
                    if (!this.isHeated()) {
                        ++this.heatTime;
                    } else if (waterLevel > 0){
                        int bubbleTime = 60;
                        if (this.isBrewing || this.isCrafting) {
                            bubbleTime = 20;
                        }
                        if (this.level.getGameTime() % bubbleTime == 0) {
                            this.level.playSound(null, this.getBlockPos(), ModSounds.CAULDRON_BUBBLES.get(), SoundSource.BLOCKS, 0.33F, this.mode == Mode.FAILED ? 0.5F : 1);
                        }
                        if (this.mode == Mode.BREWING){
                            if (this.level.getGameTime() % 60 == 0 && this.level.random.nextBoolean()){
                                this.level.playSound(null, this.getBlockPos(), ModSounds.CAULDRON_CHIMES.get(), SoundSource.BLOCKS, 0.15F, this.level.random.nextFloat() * 0.4F + 0.8F);
                            }
                        }
                        this.findCandlesticks();
                        if (this.isBrewing && mode == Mode.BREWING) {
                            if (!this.candlestickBlockEntityList.isEmpty() || this.getBrewCost() <= 0) {
                                if (this.soulTime < this.getBrewCost() && this.getBrewCost() > 0) {
                                    this.drainSouls();
                                } else {
                                    this.setColor(PotionUtils.getColor(this.getBrew()));
                                    this.level.playSound(null, this.getBlockPos(), ModSounds.CAST_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                    this.soulTime = 0;
                                    this.totalCost = 0;
                                    this.isBrewing = false;
                                    this.mode = Mode.COMPLETED;
                                }
                            } else {
                                this.mode = this.fail();
                            }
                        }
                        if (this.mode == Mode.COMPLETED || this.mode == Mode.CRAFTED){
                            if (this.level instanceof ServerLevel serverLevel){
                                float f = 1.0F;
                                serverLevel.sendParticles(ParticleTypes.WITCH, this.worldPosition.getX() + 0.5F + Math.cos(serverLevel.getGameTime() * 0.25) * f, this.worldPosition.getY(), this.worldPosition.getZ() + 0.5F + Math.sin(serverLevel.getGameTime() * 0.25) * f, 0, 0, 0, 0, 0.5F);
                                serverLevel.sendParticles(ParticleTypes.WITCH, this.worldPosition.getX() + 0.5F + Math.cos(serverLevel.getGameTime() * 0.25 + Math.PI) * f, this.worldPosition.getY(), this.worldPosition.getZ() + 0.5F + Math.sin(serverLevel.getGameTime() * 0.25 + Math.PI) * f, 0, 0, 0, 0, 0.5F);
                            }
                        }
                        if (this.mode == Mode.CRAFTING) {
                            CauldronRecipe recipe = this.getRecipe();
                            if (this.isCrafting) {
                                if (this.canCraft(this.level)) {
                                    if (recipe != null) {
                                        if (!this.candlestickBlockEntityList.isEmpty() || recipe.getSoulCost() <= 0) {
                                            if (recipe.getSoulCost() > 0) {
                                                this.drainSouls();
                                            }

                                            if (this.soulTime >= recipe.getSoulCost()) {
                                                if (waterLevel > recipe.getLevelLeft()) {
                                                    if (this.level instanceof ServerLevel serverLevel) {
                                                        for (int i = 0; i < 8; ++i) {
                                                            Vec3 vec3 = this.worldPosition.getCenter();
                                                            vec3 = vec3.offsetRandom(serverLevel.getRandom(), 0.1F);
                                                            ColorUtil colorUtil = new ColorUtil(recipe.getColor());
                                                            serverLevel.sendParticles(ModParticleTypes.BIG_CULT_SPELL.get(), vec3.x, vec3.y, vec3.z, 0, colorUtil.red, colorUtil.green, colorUtil.blue, 1.0F);
                                                        }
                                                    }
                                                    this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(ModStateProperties.LEVEL_BREW, recipe.getLevelLeft()), 11);
                                                }
                                                this.level.playSound(null, this.getBlockPos(), ModSounds.CAST_SPELL.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                                this.soulTime = 0;
                                                this.totalCost = 0;
                                                this.isCrafting = false;
                                                this.mode = Mode.CRAFTED;
                                            } else {
                                                this.updateRecipe(this.level);
                                            }
                                        } else {
                                            this.mode = this.fail();
                                        }
                                    } else {
                                        this.mode = this.fail();
                                    }
                                } else {
                                    this.mode = this.fail();
                                }
                            } else {
                                if (recipe != null) {
                                    ItemStack result = this.getCraftedItem();
                                    if (!result.isEmpty() && !result.is(Items.AIR)) {
                                        if (this.getColor() != recipe.getColor()) {
                                            this.setColor(recipe.getColor());
                                        }
                                        if (this.totalCost <= 0 && recipe.getSoulCost() > 0) {
                                            this.addCost(recipe.getSoulCost());
                                        }
                                    } else {
                                        this.setColor(0x5fd01a);
                                    }
                                }
                            }
                        }
                    } else {
                        this.fullReset();
                    }
                } else {
                    this.isBrewing = false;
                    this.isCrafting = false;
                    this.soulTime = 0;
                    this.totalCost = 0;
                    this.mode = Mode.IDLE;
                    if (this.heatTime > 0) {
                        --this.heatTime;
                    }
                }
                if (this.update > 0){
                    --this.update;
                    if (this.update <= 1) {
                        this.level.setBlockAndUpdate(this.getBlockPos(), this.getBlockState().setValue(ModStateProperties.LEVEL_BREW, 3));
                        this.update = 0;
                    }
                }
                this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(ModStateProperties.FAILED, this.mode == Mode.FAILED).setValue(ModStateProperties.CRAFTING, this.mode == Mode.CRAFTING || this.mode == Mode.CRAFTED), 11);
                this.markUpdated();
            }
        }
    }

public void populateData() {
    Map<String, SlotType.Builder> slotMap = new HashMap<>();
    Map<EntityType<?>, ImmutableSet.Builder<String>> entityMap = new HashMap<>();
    Map<String, ImmutableSet.Builder<String>> modMap = new HashMap<>();
    HolderLookup.RegistryLookup<EntityType<?>> registry =
        this.registryLookup.lookupOrThrow(Registries.ENTITY_TYPE);

    // First parse through the slot data files
    for (Map.Entry<Identifier, JsonElement> entry : this.pendingData.entrySet()) {

      if (!entry.getKey().getPath().startsWith("slots")) {
        continue;
      }
      String namespace = entry.getKey().getNamespace();
      String id = entry.getKey().getPath().substring("slots/".length());
      ISlotData.Entry.CODEC.decode(
              this.registryLookup.createSerializationContext(JsonOps.INSTANCE), entry.getValue())
          .ifSuccess(pair -> {
            ISlotData.Entry slotDataEntry = pair.getFirst();
            slotDataEntry.entities().ifPresent(entities -> {
              List<EntityType<?>> list = getEntitiesFromEither(registry, entities);

              for (EntityType<?> entityType : list) {
                entityMap.computeIfAbsent(entityType, (k) -> ImmutableSet.builder())
                    .add(id);
              }
            });
            slotMap.computeIfAbsent(id, SlotType.Builder::new)
                .apply(slotDataEntry, this.registryLookup);
            modMap.computeIfAbsent(id, (k) -> ImmutableSet.builder())
                .add(namespace);
          });
    }

    // Secondly parse through the config slot data
    try {
      Set<String> configs = fromConfig(slotMap, this.registryLookup);
      this.configSlots = ImmutableSet.copyOf(configs);

      for (String id : configs) {
        modMap.computeIfAbsent(id, (k) -> ImmutableSet.builder()).add("config");
        // Assume player-like entities for config entries
        registry.get(CuriosTags.PLAYER_LIKE).ifPresent(entries -> {

          for (Holder<EntityType<?>> entry : entries) {
            entityMap.computeIfAbsent(entry.value(), (k) -> ImmutableSet.builder()).add(id);
          }
        });
      }
    } catch (IllegalArgumentException e) {
      CuriosConstants.LOG.error("Config parsing error", e);
    }

    for (Map.Entry<Identifier, JsonElement> entry : this.pendingData.entrySet()) {

      if (!entry.getKey().getPath().startsWith("entities")) {
        continue;
      }
      Identifier resourcelocation = entry.getKey();
      IEntitiesData.Entry.CODEC.decode(
              this.registryLookup.createSerializationContext(JsonOps.INSTANCE), entry.getValue())
          .ifSuccess(pair -> {
            IEntitiesData.Entry entityDataEntry = pair.getFirst();
            List<EntityType<?>> entities =
                getEntitiesFromEither(registry, entityDataEntry.entities());

            for (EntityType<?> entity : entities) {
              ImmutableSet.Builder<String> builder =
                  entityDataEntry.replace()
                  ? entityMap.computeIfPresent(entity, (k, v) -> ImmutableSet.builder())
                  : entityMap.computeIfAbsent(entity, k -> ImmutableSet.builder());
              List<Either<String, IEntitiesData.IEntitySlotEntry>> slots = entityDataEntry.slots();

              for (Either<String, IEntitiesData.IEntitySlotEntry> slot : slots) {
                IEntitiesData.IEntitySlotEntry slotEntry = slot.map(
                    str -> new EntitiesData.EntitySlotEntry(true, new SlotData(str, true).build()),
                    c -> c);
                String key = slotEntry.slot().id().orElse("");

                if (!key.isEmpty()) {
                  boolean create = slotEntry.create();
                  SlotType.Builder slotType = slotMap.get(key);

                  if (create && slotType == null) {
                    SlotType.Builder slotBuilder = new SlotType.Builder(key);
                    slotBuilder.apply(slotEntry.slot(), this.registryLookup);
                    slotType = slotBuilder;
                    slotMap.put(key, slotBuilder);
                  }

                  if (slotType != null) {
                    Objects.requireNonNull(builder).add(key);
                  }
                }
              }
            }
          });
      modMap.computeIfAbsent(resourcelocation.getPath(), (k) -> ImmutableSet.builder())
          .add(resourcelocation.getNamespace());
    }
    this.slots = slotMap.entrySet().stream()
        .collect(ImmutableMap.toImmutableMap(Map.Entry::getKey, entry -> entry.getValue().build()));
    this.idToMods = modMap.entrySet().stream()
        .collect(ImmutableMap.toImmutableMap(Map.Entry::getKey, entry -> entry.getValue().build()));
    Map<EntityType<?>, Map<String, ISlotType>> newEntitySlots = new LinkedHashMap<>();

    for (Map.Entry<EntityType<?>, ImmutableSet.Builder<String>> entry : entityMap.entrySet()) {
      Set<String> slots = entry.getValue().build();
      Map<String, ISlotType> innerMap = new LinkedHashMap<>();

      for (String id : slots) {
        ISlotType slotType = this.slots.get(id);

        if (slotType != null) {
          innerMap.put(id, slotType);
        }
      }
      newEntitySlots.put(entry.getKey(), innerMap);
    }
    this.entitySlots = ImmutableMap.copyOf(newEntitySlots);
    CuriosConstants.LOG.info("Loaded {} curio slots", slotMap.size());
    CuriosConstants.LOG.info("Loaded {} curio entities", entityMap.size());
    this.pendingData.clear();
  }

@Override
	public boolean place(FeaturePlaceContext<TFSmallLakeFeature.Configuration> context) {
		BlockPos blockpos = context.origin();
		WorldGenLevel worldgenlevel = context.level();
		RandomSource randomsource = context.random();
		TFSmallLakeFeature.Configuration config = context.config();

		if (blockpos.getY() <= worldgenlevel.getMinY() + 4) {
			return false;
		} else {
			blockpos = blockpos.below(4);
			boolean[] booleans = new boolean[2048];
			int i = randomsource.nextInt(4) + 4;

			for (int j = 0; j < i; j++) {
				double d0 = randomsource.nextDouble() * 6.0 + 3.0;
				double d1 = randomsource.nextDouble() * 4.0 + 2.0;
				double d2 = randomsource.nextDouble() * 6.0 + 3.0;
				double d3 = randomsource.nextDouble() * (16.0 - d0 - 2.0) + 1.0 + d0 / 2.0;
				double d4 = randomsource.nextDouble() * (8.0 - d1 - 4.0) + 2.0 + d1 / 2.0;
				double d5 = randomsource.nextDouble() * (16.0 - d2 - 2.0) + 1.0 + d2 / 2.0;

				for (int l = 1; l < 15; l++) {
					for (int i1 = 1; i1 < 15; i1++) {
						for (int j1 = 1; j1 < 7; j1++) {
							double d6 = ((double)l - d3) / (d0 / 2.0);
							double d7 = ((double)j1 - d4) / (d1 / 2.0);
							double d8 = ((double)i1 - d5) / (d2 / 2.0);
							double d9 = d6 * d6 + d7 * d7 + d8 * d8;
							if (d9 < 1.0) {
								booleans[(l * 16 + i1) * 8 + j1] = true;
							}
						}
					}
				}
			}

			BlockState fluidState = config.fluid().getState(worldgenlevel, randomsource, blockpos);

			for (int x = 0; x < 16; x++) {
				for (int z = 0; z < 16; z++) {
					for (int y = 0; y < 8; y++) {
						boolean flag = !booleans[(x * 16 + z) * 8 + y]
							&& (
							x < 15 && booleans[((x + 1) * 16 + z) * 8 + y]
								|| x > 0 && booleans[((x - 1) * 16 + z) * 8 + y]
								|| z < 15 && booleans[(x * 16 + z + 1) * 8 + y]
								|| z > 0 && booleans[(x * 16 + (z - 1)) * 8 + y]
								|| y < 7 && booleans[(x * 16 + z) * 8 + y + 1]
								|| y > 0 && booleans[(x * 16 + z) * 8 + (y - 1)]
						);
						if (flag) {
							BlockState blockstate3 = worldgenlevel.getBlockState(blockpos.offset(x, y, z));
							if (y >= 4 && blockstate3.liquid()) {
								return false;
							}

							if (y < 4 && !blockstate3.isSolid() && worldgenlevel.getBlockState(blockpos.offset(x, y, z)) != fluidState) {
								return false;
							}
						}
					}
				}
			}

			BlockState iceState = config.ice != null ? config.ice.getState(worldgenlevel, randomsource, blockpos) : null;

			for (int x = 0; x < 16; x++) {
				for (int z = 0; z < 16; z++) {
					for (int y = 0; y < 8; y++) {
						if (booleans[(x * 16 + z) * 8 + y]) {
							BlockPos offset = blockpos.offset(x, y, z);
							if (!(worldgenlevel.getBlockState(offset).is(TFBlockTags.SMALL_LAKES_DONT_REPLACE) ||
								worldgenlevel.getBlockState(offset.above()).is(TFBlockTags.SMALL_LAKES_DONT_REPLACE))) {
								if (y >= 4) {
									worldgenlevel.setBlock(offset, AIR, Block.UPDATE_CLIENTS);
                                    worldgenlevel.scheduleTick(offset, AIR.getBlock(), 0);
                                    this.markAboveForPostProcessing(worldgenlevel, offset);
									continue;
                                }

								if (y == 3 && iceState != null) {
									worldgenlevel.setBlock(offset, iceState, Block.UPDATE_CLIENTS);
									continue;
								}

								worldgenlevel.setBlock(offset, fluidState, Block.UPDATE_CLIENTS);
                            }
						}
					}
				}
			}

			if (config.barrier() != null) {
				BlockState barrierState = config.barrier().getState(worldgenlevel, randomsource, blockpos);
				if (!barrierState.isAir()) {
					for (int x = 0; x < 16; x++) {
						for (int z = 0; z < 16; z++) {
							for (int y = 0; y < 8; y++) {
								boolean flag2 = !booleans[(x * 16 + z) * 8 + y]
									&& (
									x < 15 && booleans[((x + 1) * 16 + z) * 8 + y]
										|| x > 0 && booleans[((x - 1) * 16 + z) * 8 + y]
										|| z < 15 && booleans[(x * 16 + z + 1) * 8 + y]
										|| z > 0 && booleans[(x * 16 + (z - 1)) * 8 + y]
										|| y < 7 && booleans[(x * 16 + z) * 8 + y + 1]
										|| y > 0 && booleans[(x * 16 + z) * 8 + (y - 1)]
								);
								if (flag2 && (y < 4 || randomsource.nextInt(2) != 0)) {
									BlockState blockstate = worldgenlevel.getBlockState(blockpos.offset(x, y, z));
									if (blockstate.isSolid() && !blockstate.is(BlockTags.LAVA_POOL_STONE_CANNOT_REPLACE)) {
										BlockPos blockpos3 = blockpos.offset(x, y, z);
										worldgenlevel.setBlock(blockpos3, barrierState, Block.UPDATE_CLIENTS);
										this.markAboveForPostProcessing(worldgenlevel, blockpos3);
									}
								}
							}
						}
					}
				}
			}

			return true;
		}
	}

protected void onHitEntity(EntityHitResult p_213868_1_)
	{
		super.onHitEntity(p_213868_1_);
		Entity entity = p_213868_1_.getEntity();
		float f = (float) this.getDeltaMovement().length();
		int i = Mth.ceil(Mth.clamp(this.damage, 0.0D, 2.147483647E9D));
		if (this.getPierceLevel() > 0)
		{
			if (this.piercedEntities == null)
			{
				this.piercedEntities = new IntOpenHashSet(5);
			}

			if (this.hitEntities == null)
			{
				this.hitEntities = Lists.newArrayListWithCapacity(5);
			}

			if (this.piercedEntities.size() >= this.getPierceLevel() + 1)
			{
				this.discard();
				return;
			}

			this.piercedEntities.add(entity.getId());
		}

		if (this.getIsCritical())
		{
			long j = (long) this.random.nextInt(i / 2 + 2);
			i = (int) Math.min(j + (long) i, 2147483647L);
		}

		Entity entity1 = this.getOwner();
		DamageSource damagesource;
		if (entity1 == null)
		{
			damagesource = entity.damageSources().thrown(this,this);
		} else
		{
			damagesource = entity.damageSources().thrown(this, entity1);
			if (entity1 instanceof LivingEntity)
			{
				((LivingEntity) entity1).setLastHurtMob(entity);
			}
		}

		boolean flag = entity.getType() == EntityType.ENDERMAN;
		int k = entity.getRemainingFireTicks();
		if (this.isOnFire() && !flag)
		{
			entity.setSecondsOnFire(5);
		}

		if (entity.hurt(damagesource, (float) i))
		{
			if (flag)
			{
				return;
			}

			if (!entity.isAlive() && entity1 instanceof Player && entity instanceof LivingEntity)
			{
				double willAmount = this.getWillDropForMobHealth(((LivingEntity) entity).getMaxHealth());
				if (willAmount > 0)
					PlayerDemonWillHandler.addDemonWill(willType, (Player) entity1, willAmount);
			}

			if (entity instanceof LivingEntity)
			{
				LivingEntity livingentity = (LivingEntity) entity;
//				if (!this.world.isRemote && this.getPierceLevel() <= 0)
//				{
//					livingentity.setArrowCountInEntity(livingentity.getArrowCountInEntity() + 1);
//				}

				if (this.knockbackStrength > 0)
				{
					Vec3 vector3d = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double) this.knockbackStrength * 0.6D);
					if (vector3d.lengthSqr() > 0.0D)
					{
						livingentity.push(vector3d.x, 0.1D, vector3d.z);
					}
				}

				if (!this.level().isClientSide && entity1 instanceof LivingEntity)
				{
					EnchantmentHelper.doPostHurtEffects(livingentity, entity1);
					EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingentity);
				}

				this.daggerHit(livingentity);
				if (entity1 != null && livingentity != entity1 && livingentity instanceof Player && entity1 instanceof ServerPlayer && !this.isSilent())
				{
					((ServerPlayer) entity1).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
				}

				if (!entity.isAlive() && this.hitEntities != null)
				{
					this.hitEntities.add(livingentity);
				}
			}

			this.playSound(this.hitSound, 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
			if (this.getPierceLevel() <= 0)
			{
				this.discard();
			}
		} else
		{
			entity.setRemainingFireTicks(k);
			this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
			this.setYRot(this.getYRot() + 180.0F);
			this.yRotO += 180.0F;
			if (!this.level().isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D)
			{
				if (this.pickupStatus == AbstractArrow.Pickup.ALLOWED)
				{
					this.spawnAtLocation(this.getArrowStack(), 0.1F);
				}

				this.discard();
			}
		}

	}

@Override
	public boolean onBlockActivated(World worldIn, BlockPos pos, IBlockState state, EntityPlayer playerIn, EnumHand hand, EnumFacing facing, float hitX, float hitY, float hitZ) {
		if (worldIn.isRemote) return true;

		ItemStack heldItem = playerIn.getHeldItem(hand);

		if (testStructure(worldIn, pos).isEmpty()) {
			TileCraftingPlate plate = getTE(worldIn, pos);
			if (!heldItem.isEmpty()) {
				if (heldItem.getItem() == ModItems.BOOK && playerIn.isCreative()) {
					ItemStack pearl = new ItemStack(ModItems.PEARL_NACRE);

					NBTTagList moduleList = NBTHelper.getList(heldItem, NBTConstants.NBT.SPELL, net.minecraftforge.common.util.Constants.NBT.TAG_STRING);
					if (moduleList == null) return false;

					SpellBuilder builder = new SpellBuilder(SpellUtils.getSpellItems(SpellUtils.deserializeModuleList(moduleList)));

					NBTTagList list = new NBTTagList();
					for (SpellRing spellRing : builder.getSpell()) {
						list.appendTag(spellRing.serializeNBT());
					}
					NBTHelper.setList(pearl, NBTConstants.NBT.SPELL, list);
					NBTHelper.setBoolean(pearl, "infused", true);

					//Color lastColor = SpellUtils.getAverageSpellColor(builder.getSpell());
//
					//float[] hsv = ColorUtils.getHSVFromColor(lastColor);
					//NBTHelper.setFloat(pearl, "hue", hsv[0]);
					//NBTHelper.setFloat(pearl, "saturation", hsv[1]);
					NBTHelper.setFloat(pearl, NBTConstants.NBT.RAND, playerIn.world.rand.nextFloat());

					plate.output.getHandler().setStackInSlot(0, pearl);
					plate.markDirty();
					PacketHandler.NETWORK.sendToAllAround(new PacketExplode(new Vec3d(pos).add(0.5, 0.5, 0.5), Color.CYAN, Color.BLUE, 2, 2, 500, 300, 20, false),
							new NetworkRegistry.TargetPoint(worldIn.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

					worldIn.playSound(null, pos, ModSounds.BASS_BOOM, SoundCategory.BLOCKS, 1f, (float) RandUtil.nextDouble(1, 1.5));
					return true;
				} else {
					ItemStack stack = heldItem.copy();
					int oldCount = stack.getCount();
					int subtractHand = playerIn.isSneaking() ? 64 : 1;
					heldItem.shrink(subtractHand);
					stack.setCount(oldCount - heldItem.getCount());

					boolean recipeExists = CraftingPlateRecipeManager.doesRecipeExistForItem(stack);

					if (!plate.isInventoryEmpty() && recipeExists) {
						plate.input.getHandler().insertItem(0, stack, false);

						plate.markDirty();
						playerIn.openContainer.detectAndSendChanges();

						PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(pos, stack), new NetworkRegistry.TargetPoint(worldIn.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));

					} else if (!recipeExists) {
						ItemHandlerHelper.insertItem(plate.realInventory.getHandler(), stack, false);

						plate.markDirty();
						playerIn.openContainer.detectAndSendChanges();

						PacketHandler.NETWORK.sendToAllAround(new PacketUpdateCraftingPlateSlot(pos, stack), new NetworkRegistry.TargetPoint(worldIn.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
					}

					return true;
				}
			} else {

				if (plate.hasInput()) {
					ItemStack stack = plate.input.getHandler().getStackInSlot(0);

					ICraftingPlateRecipe recipe = CraftingPlateRecipeManager.getRecipeForItem(stack);
					if (recipe != null) recipe.canceled(worldIn, pos, stack);

					ItemStack extract = plate.input.getHandler().extractItem(0, 1, false);
					if (!extract.isEmpty()) {

						playerIn.addItemStackToInventory(extract);

						plate.markDirty();
						playerIn.openContainer.detectAndSendChanges();

						PacketHandler.NETWORK.sendToAllAround(new PacketRemoveItemCraftingPlate(pos, 0), new NetworkRegistry.TargetPoint(worldIn.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
						return true;
					}

				} else if (plate.hasOutput()) {
					ItemStack extract = plate.output.getHandler().extractItem(0, 1, false);
					if (!extract.isEmpty()) {

						playerIn.addItemStackToInventory(extract);

						plate.markDirty();
						playerIn.openContainer.detectAndSendChanges();

						PacketHandler.NETWORK.sendToAllAround(new PacketRemoveItemCraftingPlate(pos, 0), new NetworkRegistry.TargetPoint(worldIn.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
						return true;
					}
				} else {

					for (int i = plate.realInventory.getHandler().getSlots() - 1; i >= 0; i--) {
						ItemStack extracted = plate.realInventory.getHandler().extractItem(i, playerIn.isSneaking() ? 64 : 1, false);
						if (!extracted.isEmpty()) {
							playerIn.addItemStackToInventory(extracted);

							plate.markDirty();
							playerIn.openContainer.detectAndSendChanges();

							PacketHandler.NETWORK.sendToAllAround(new PacketRemoveItemCraftingPlate(pos, i), new NetworkRegistry.TargetPoint(worldIn.provider.getDimension(), pos.getX(), pos.getY(), pos.getZ(), 256));
							break;
						}
					}
				}
				return true;
			}

		} else {
			if (playerIn.isCreative() && playerIn.isSneaking()) {
				buildStructure(worldIn, pos);
			} else {
				TileCraftingPlate plate = getTE(worldIn, pos);
				plate.revealStructure = !plate.revealStructure;
				plate.markDirty();
			}
		}
		return heldItem.isEmpty();
	}

@Override
    public void actuallyRender(PoseStack poseStack, GeckoPlayer animatable, BakedGeoModel model, RenderType renderType, MultiBufferSource bufferSource, VertexConsumer buffer, boolean isReRender, float partialTick, int packedLight, int packedOverlay, int color) {
        AbstractClientPlayer entity = (AbstractClientPlayer) animatable.getPlayer();
        this.model.attackTime = this.getAttackAnim(entity, partialTick);

        boolean shouldSit = entity.isPassenger() && (entity.getVehicle() != null && entity.getVehicle().shouldRiderSit());
        this.model.riding = shouldSit;
        this.model.young = entity.isBaby();
        float f_lerpBodyRot = Mth.rotLerp(partialTick, entity.yBodyRotO, entity.yBodyRot);
        float f1_lerpHeadRot = Mth.rotLerp(partialTick, entity.yHeadRotO, entity.yHeadRot);
        float f2_netHeadYaw = f1_lerpHeadRot - f_lerpBodyRot;
        if (shouldSit && entity.getVehicle() instanceof LivingEntity) {
            LivingEntity livingentity = (LivingEntity)entity.getVehicle();
            f_lerpBodyRot = Mth.rotLerp(partialTick, livingentity.yBodyRotO, livingentity.yBodyRot);
            f2_netHeadYaw = f1_lerpHeadRot - f_lerpBodyRot;
            float f3 = Mth.wrapDegrees(f2_netHeadYaw);
            if (f3 < -85.0F) {
                f3 = -85.0F;
            }

            if (f3 >= 85.0F) {
                f3 = 85.0F;
            }

            f_lerpBodyRot = f1_lerpHeadRot - f3;
            if (f3 * f3 > 2500.0F) {
                f_lerpBodyRot += f3 * 0.2F;
            }

            f2_netHeadYaw = f1_lerpHeadRot - f_lerpBodyRot;
        }

        float f6 = Mth.lerp(partialTick, entity.xRotO, entity.getXRot());
        if (isEntityUpsideDown(entity)) {
            f6 *= -1.0F;
            f2_netHeadYaw *= -1.0F;
        }

        if (entity.hasPose(Pose.SLEEPING)) {
            Direction direction = entity.getBedOrientation();
            if (direction != null) {
                float f4 = entity.getEyeHeight(Pose.STANDING) - 0.1F;
                poseStack.translate((float)(-direction.getStepX()) * f4, 0.0F, (float)(-direction.getStepZ()) * f4);
            }
        }

        float f7 = this.getBob(entity, partialTick);
//        this.setupRotations(entity, poseStack, f7, f_lerpBodyRot, partialTick);   This is where the vanilla function gets called. We move it lower down after animations are handled
        this.scale(entity, poseStack, partialTick);
        float f8_limbSwingAmount = 0.0F;
        float f5_limbSwing = 0.0F;
        if (!shouldSit && entity.isAlive()) {
            f8_limbSwingAmount = entity.walkAnimation.speed(partialTick);
            f5_limbSwing = entity.walkAnimation.position(partialTick);
            if (entity.isBaby()) {
                f5_limbSwing *= 3.0F;
            }

            if (f8_limbSwingAmount > 1.0F) {
                f8_limbSwingAmount = 1.0F;
            }
        }

        if (!isReRender) {
            float headPitch = Mth.lerp(partialTick, entity.xRotO, entity.getXRot());
            float motionThreshold = getMotionAnimThreshold(animatable);
            Vec3 velocity = entity.getDeltaMovement();
            float avgVelocity = (float)(Math.abs(velocity.x) + Math.abs(velocity.z)) / 2f;
            AnimationState<GeckoPlayer> animationState = new AnimationState<GeckoPlayer>(animatable, f5_limbSwing, f8_limbSwingAmount, partialTick, avgVelocity >= motionThreshold && f8_limbSwingAmount != 0);
            long instanceId = getInstanceId(animatable);

            AnimatableManager<GeckoPlayer> animatableManager = animatable.getAnimatableInstanceCache().getManagerForId(instanceId);
            animationState.setData(DataTickets.TICK, animatable.getTick(animatable) + animatableManager.getFirstTickTime() + partialTick);
            animationState.setData(DataTickets.ENTITY, entity);
            animationState.setData(DataTickets.ENTITY_MODEL_DATA, new EntityModelData(shouldSit, entity.isBaby(), -f2_netHeadYaw, -headPitch));
            this.getGeckoModel().addAdditionalStateData(animatable, instanceId, animationState::setData);
            this.getGeckoModel().handleAnimations(animatable, instanceId, animationState, partialTick);
        }

        if (this.geoModel.isInitialized()) {
            this.setupRotations(entity, poseStack, f7, f_lerpBodyRot, partialTick, f1_lerpHeadRot);
            float bodyRotateAmount = this.geoModel.getControllerValueInverted("BodyRotateController");
            this.geoModel.setRotationAngles(entity, f5_limbSwing, f8_limbSwingAmount, f7, Mth.rotLerp(bodyRotateAmount, 0, f2_netHeadYaw), f6, partialTick);

            MowzieGeoBone leftHeldItem = geoModel.getMowzieBone("LeftHeldItem");
            MowzieGeoBone rightHeldItem = geoModel.getMowzieBone("RightHeldItem");

            Matrix4f worldMatInverted = new Matrix4f(poseStack.last().pose());
            worldMatInverted.invert();
            Matrix3f worldNormInverted = new Matrix3f(poseStack.last().normal());
            worldNormInverted.invert();
            PoseStack toWorldSpace = new PoseStack();
            toWorldSpace.mulPose(MathUtils.quatFromRotationXYZ(0, -f_lerpBodyRot + 180, 0, true));
            toWorldSpace.translate(0, -1.5f, 0);
            toWorldSpace.last().normal().mul(worldNormInverted);
            toWorldSpace.last().pose().mul(worldMatInverted);

            Vector4f leftHeldItemPos = new Vector4f(0, 0, 0, 1);
            leftHeldItemPos.mul(leftHeldItem.getWorldSpaceMatrix());
            leftHeldItemPos.mul(toWorldSpace.last().pose());
            Vec3 leftHeldItemPos3 = new Vec3(leftHeldItemPos.x(), leftHeldItemPos.y(), leftHeldItemPos.z());

            Vector4f rightHeldItemPos = new Vector4f(0, 0, 0, 1);
            rightHeldItemPos.mul(rightHeldItem.getWorldSpaceMatrix());
            rightHeldItemPos.mul(toWorldSpace.last().pose());
            Vec3 rightHeldItemPos3 = new Vec3(rightHeldItemPos.x(), rightHeldItemPos.y(), rightHeldItemPos.z());

            betweenHandsPos = rightHeldItemPos3.add(leftHeldItemPos3.subtract(rightHeldItemPos3).scale(0.5));

            MowzieGeoBone particleEmitterRootBone = geoModel.getMowzieBone("ParticleEmitterRoot");
            Vector4f emitterRootPos = new Vector4f(0, 0, 0, 1);
            emitterRootPos.mul(particleEmitterRootBone.getWorldSpaceMatrix());
            emitterRootPos.mul(toWorldSpace.last().pose());
            particleEmitterRoot = new Vec3(emitterRootPos.x(), emitterRootPos.y(), emitterRootPos.z());
        }

        poseStack.translate(0, 0.01f, 0);

//        this.modelRenderTranslations = new Matrix4f(poseStack.last().pose());

        if (!entity.isInvisibleTo(Minecraft.getInstance().player))
            GeoRenderer.super.actuallyRender(poseStack, animatable, model, renderType, bufferSource, buffer, isReRender, partialTick, packedLight, packedOverlay, color);

        ModelPlayerAnimated.copyFromGeckoModel(this.model, geoModel);

        if (!entity.isSpectator()) {
            for(RenderLayer<AbstractClientPlayer, PlayerModel<AbstractClientPlayer>> layerrenderer : this.layers) {
                layerrenderer.render(poseStack, bufferSource, packedLight, entity, f5_limbSwing, f8_limbSwingAmount, partialTick, f7, f2_netHeadYaw, f6);
            }
        }
    }

protected boolean moveBlock(Level world, @Nullable Direction forcedDirection, Queue<BlockPos> frontier,
								Set<BlockPos> visited) throws AssemblyException {
		BlockPos pos = frontier.poll();
		if (pos == null)
			return false;
		visited.add(pos);

		if (world.isOutsideBuildHeight(pos))
			return true;
		if (!world.isLoaded(pos))
			throw AssemblyException.unloadedChunk(pos);
		if (isAnchoringBlockAt(pos))
			return true;
		BlockState state = world.getBlockState(pos);
		if (!BlockMovementChecks.isMovementNecessary(state, world, pos))
			return true;
		if (!movementAllowed(state, world, pos))
			throw AssemblyException.unmovableBlock(pos, state);
		if (state.getBlock() instanceof AbstractChassisBlock
			&& !moveChassis(world, pos, forcedDirection, frontier, visited))
			return false;

		if (AllBlocks.BELT.has(state))
			moveBelt(pos, frontier, visited, state);

		if (AllBlocks.WINDMILL_BEARING.has(state) && world.getBlockEntity(pos) instanceof WindmillBearingBlockEntity wbbe)
			wbbe.disassembleForMovement();

		if (AllBlocks.GANTRY_CARRIAGE.has(state))
			moveGantryPinion(world, pos, frontier, visited, state);

		if (AllBlocks.GANTRY_SHAFT.has(state))
			moveGantryShaft(world, pos, frontier, visited, state);

		if (AllBlocks.STICKER.has(state) && state.getValue(StickerBlock.EXTENDED)) {
			Direction offset = state.getValue(StickerBlock.FACING);
			BlockPos attached = pos.relative(offset);
			if (!visited.contains(attached)
				&& !BlockMovementChecks.isNotSupportive(world.getBlockState(attached), offset.getOpposite()))
				frontier.add(attached);
		}

		if (world.getBlockEntity(pos) instanceof ChainConveyorBlockEntity ccbe)
			ccbe.notifyConnectedToValidate();

		// Double Chest halves stick together
		if (state.hasProperty(ChestBlock.TYPE) && state.hasProperty(ChestBlock.FACING)
			&& state.getValue(ChestBlock.TYPE) != ChestType.SINGLE) {
			Direction offset = ChestBlock.getConnectedDirection(state);
			BlockPos attached = pos.relative(offset);
			if (!visited.contains(attached))
				frontier.add(attached);
		}

		// Bogeys tend to have sticky sides
		if (state.getBlock() instanceof AbstractBogeyBlock<?> bogey)
			for (Direction d : bogey.getStickySurfaces(world, pos, state))
				if (!visited.contains(pos.relative(d)))
					frontier.add(pos.relative(d));

		// Bearings potentially create stabilized sub-contraptions
		if (AllBlocks.MECHANICAL_BEARING.has(state))
			moveBearing(pos, frontier, visited, state);

		// WM Bearings attach their structure when moved
		if (AllBlocks.WINDMILL_BEARING.has(state))
			moveWindmillBearing(pos, frontier, visited, state);

		// Seats transfer their passenger to the contraption
		if (AllBlockTags.SEATS.matches(state))
			moveSeat(world, pos);

		// Pulleys drag their rope and their attached structure
		if (state.getBlock() instanceof PulleyBlock)
			movePulley(world, pos, frontier, visited);

		// Pistons drag their attaches poles and extension
		if (state.getBlock() instanceof MechanicalPistonBlock)
			if (!moveMechanicalPiston(world, pos, frontier, visited, state))
				return false;
		if (isExtensionPole(state))
			movePistonPole(world, pos, frontier, visited, state);
		if (isPistonHead(state))
			movePistonHead(world, pos, frontier, visited, state);

		// Cart assemblers attach themselves
		BlockPos posDown = pos.below();
		BlockState stateBelow = world.getBlockState(posDown);
		if (!visited.contains(posDown) && AllBlocks.CART_ASSEMBLER.has(stateBelow))
			frontier.add(posDown);

		// Slime blocks and super glue drag adjacent blocks if possible
		for (Direction offset : Iterate.directions) {
			BlockPos offsetPos = pos.relative(offset);
			BlockState blockState = world.getBlockState(offsetPos);
			if (isAnchoringBlockAt(offsetPos))
				continue;
			if (!movementAllowed(blockState, world, offsetPos)) {
				if (offset == forcedDirection)
					throw AssemblyException.unmovableBlock(pos, state);
				continue;
			}

			boolean wasVisited = visited.contains(offsetPos);
			boolean faceHasGlue = SuperGlueEntity.isGlued(world, pos, offset, glueToRemove);
			boolean blockAttachedTowardsFace =
				BlockMovementChecks.isBlockAttachedTowards(blockState, world, offsetPos, offset.getOpposite());
			boolean brittle = BlockMovementChecks.isBrittle(blockState);
			boolean canStick = !brittle && state.canStickTo(blockState) && blockState.canStickTo(state);
			if (canStick) {
				if (state.getPistonPushReaction() == PushReaction.PUSH_ONLY
					|| blockState.getPistonPushReaction() == PushReaction.PUSH_ONLY) {
					canStick = false;
				}
				if (BlockMovementChecks.isNotSupportive(state, offset)) {
					canStick = false;
				}
				if (BlockMovementChecks.isNotSupportive(blockState, offset.getOpposite())) {
					canStick = false;
				}
			}

			if (!wasVisited && (canStick || blockAttachedTowardsFace || faceHasGlue
				|| (offset == forcedDirection && !BlockMovementChecks.isNotSupportive(state, forcedDirection))))
				frontier.add(offsetPos);
		}

		addBlock(world, pos, capture(world, pos));
		if (blocks.size() <= AllConfigs.server().kinetics.maxBlocksMoved.get())
			return true;
		else
			throw AssemblyException.structureTooLarge();
	}

@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

		WizardData data = WizardData.get(caster);

		Vec3d origin = caster.getPositionEyes(1);

		float extensionSpeed = getProperty(EXTENSION_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY);

		RayTraceResult hit = data.getVariable(TARGET_KEY);

		// Initial targeting
		if(hit == null){
			hit = findTarget(world, caster, origin, caster.getLookVec(), modifiers);
			data.setVariable(TARGET_KEY, hit);
			caster.swingArm(hand);
			// This condition prevents the sound playing every tick after a missed shot has finished extending
			if(hit.typeOfHit != RayTraceResult.Type.MISS
					|| ticksInUse * extensionSpeed < getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade)){
				this.playSound(world, caster, ticksInUse, -1, modifiers, "shoot");
			}
		}

		Vec3d target = hit.hitVec;

		if(hit.entityHit instanceof EntityLivingBase){
			// If the target is an entity, we need to use the entity's centre rather than the original hit position
			// because the entity will have moved!
			target = GeometryUtils.getCentre(hit.entityHit);
		}

		double distance = origin.distanceTo(target);
		Vec3d direction = target.subtract(origin).normalize();

		double maxLength = getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade) * STRETCH_LIMIT;

		// If the vine stretched too far
		if(distance > maxLength){
			if(world.isRemote && (ticksInUse-1) * extensionSpeed < distance){
				spawnLeafParticles(world, origin.subtract(0, SpellRay.Y_OFFSET, 0), direction, distance);
			}
			data.setVariable(TARGET_KEY, null);
			return false; // The spell is finished
		}

		boolean extending = ticksInUse * extensionSpeed < distance;

		if(extending){
			// Extension
			if(world.isRemote){
				// world.getTotalWorldTime() - ticksInUse generates a constant but unique seed each time the spell is cast
				ParticleBuilder.create(Type.VINE).entity(caster).pos(0, caster.getEyeHeight() - SpellRay.Y_OFFSET, 0)
						.target(origin.add(direction.scale(ticksInUse * extensionSpeed))).tvel(direction.scale(extensionSpeed))
						.seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
			}

		}else{
			// Retraction
			Vec3d velocity = direction.scale(getProperty(REEL_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY));

			int retractTime = ticksInUse - (int)(distance/extensionSpeed);

			switch(hit.typeOfHit){

				case BLOCK:
					// Payout
					if(caster.isSneaking() && ItemArtefact.isArtefactActive(caster, WizardryItems.charm_abseiling))
						velocity = new Vec3d(velocity.x, distance < maxLength-1 ? -PAYOUT_SPEED : distance-maxLength+1, velocity.z);

					// Reel the caster towards the block hit
					double ax = (velocity.x - caster.motionX) * REEL_ACCELERATION;
					double ay = (velocity.y - caster.motionY) * REEL_ACCELERATION;
					double az = (velocity.z - caster.motionZ) * REEL_ACCELERATION;
					caster.addVelocity(ax, ay, az);

					if(caster.motionY > 0 && !Wizardry.settings.replaceVanillaFallDamage) caster.fallDistance = 0; // Reset fall distance if the caster moves upwards

					if(world.isRemote){
						ParticleBuilder.create(Type.VINE).entity(caster).pos(0, caster.getEyeHeight() - SpellRay.Y_OFFSET, 0)
								.target(target).seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
					}

					if(retractTime == 1){ // Just hit
						this.playSound(world, caster, ticksInUse, -1, modifiers,  "pull");
						this.playSound(world, hit.hitVec, ticksInUse, -1, modifiers,  "attach");
					}

					break;

				case ENTITY:
					// Payout
					if(caster.isSneaking() && ItemArtefact.isArtefactActive(caster, WizardryItems.charm_abseiling))
						velocity = new Vec3d(velocity.x, distance < maxLength-1 ? PAYOUT_SPEED : maxLength-1-distance, velocity.z);

					// Reel the entity hit towards the caster
					Entity entity = hit.entityHit;

					if(distance > MINIMUM_REEL_DISTANCE){
						double ax1 = (-velocity.x - entity.motionX) * REEL_ACCELERATION;
						double ay1 = (-velocity.y - entity.motionY) * REEL_ACCELERATION;
						double az1 = (-velocity.z - entity.motionZ) * REEL_ACCELERATION;
						entity.addVelocity(ax1, ay1, az1);
						// Player motion is handled on that player's client so needs packets
						if(entity instanceof EntityPlayerMP){
							((EntityPlayerMP)entity).connection.sendPacket(new SPacketEntityVelocity(entity));
						}
					}

					if(world.isRemote){
						ParticleBuilder.create(Type.VINE).entity(caster).pos(0, caster.getEyeHeight() - SpellRay.Y_OFFSET, 0)
								.target(entity).seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
					}

					if(retractTime == 1){ // Just hit
						this.playSound(world, caster, ticksInUse, -1, modifiers,  "pull");
						this.playSound(world, entity.posX, entity.posY, entity.posZ, ticksInUse, -1, modifiers,  "attach");
					}

					break;

				default:
					// Missed
					if(world.isRemote && (ticksInUse-1) * extensionSpeed < distance){
						spawnLeafParticles(world, origin.subtract(0, SpellRay.Y_OFFSET, 0), direction, distance);
					}
					//caster.resetActiveHand();
					data.setVariable(TARGET_KEY, null);
					return false; // The spell is finished
			}
		}

		return true;
	}

@Override
    public void curioTick(SlotContext slotContext, ItemStack stack) {
        super.curioTick(slotContext, stack);

        if (!(slotContext.entity() instanceof LivingEntity entity))
            return;

        var level = entity.level();
        var belowState = level.getBlockState(entity.getBlockPosBelowThatAffectsMyMovement());

        var ability = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch");
        var forcedFall = this.isForcedFall(stack);
        var onGround = entity.onGround();
        var glitchEnabled = this.isGlitchEnabled(entity, stack);

        if (!glitchEnabled) {
            this.setStandTicks(stack, 0);
            this.setForcedFall(stack, false);
            this.setPhaseTicks(stack, 0);
        } else {
            var stable = onGround && belowState.isAir() && !isMovingHorizontally(entity) && !entity.isShiftKeyDown();

            if (!forcedFall) {
                if (stable) {
                    this.addStandTicks(stack, 1);

                    if (this.getStandTicks(stack) >= (int) Math.max(1D, ability.getStatData("stability_time").getValue() * 20D)) {
                        this.setForcedFall(stack, true);
                        this.setForcedFallStartY(stack, entity.getY());
                        this.setStandTicks(stack, 0);

                        if (!level.isClientSide())
                            this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("glitch").getStatisticData().getMetricData("forced_falls").addValue(1);
                    }
                } else {
                    this.setStandTicks(stack, 0);
                }
            }

            if (this.isForcedFall(stack) && onGround && !belowState.isAir() && entity.fallDistance <= 0F)
                this.setForcedFall(stack, false);
        }

        if (level.isClientSide())
            return;

        var gameTime = level.getGameTime();

        if (glitchEnabled && belowState.isAir() && this.canCollideWithAirLike(entity, stack) && this.getLastAirTick(stack) != gameTime) {
            this.setLastAirTick(stack, gameTime);

            ability.getStatisticData().getMetricData("solid_air_duration").addValue(1D / 20D);

            if (isMovingHorizontally(entity))
                this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "air_walking", 1D / 20D);
        }

        var illusion = this.getRelicData(entity, stack).getAbilitiesData().getAbilityData("illusion");

        if (illusion.canPlayerUse(entity) && illusion.getMode().equals("enabled")) {
            if (this.getIllusionCooldown(stack) > 0) {
                this.addIllusionCooldown(stack, -1);
            } else {
                var look = entity.getLookAngle().multiply(1D, 0D, 1D);
                var backward = look.lengthSqr() > 1.0E-6D ? look.normalize().scale(-0.95D) : Vec3.ZERO;
                var spawnPos = entity.position().add(backward);
                var copy = new GlitchyIllusionEntity(RelicsEntities.GLITCHY_ILLUSION.get(), level);

                copy.setOwner(entity);
                copy.setLifetime((int) Math.max(1D, illusion.getStatData("duration").getValue() * 20D));
                copy.setStunDuration((int) Math.max(1D, illusion.getStatData("stun").getValue() * 20D));
                copy.setStunRadius((float) Math.max(0D, illusion.getStatData("stun_radius").getValue()));
                copy.setFlawless(this.getRelicData(entity, stack).isVisuallyFlawless());
                copy.setStack(stack);
                copy.setPos(spawnPos.x(), spawnPos.y(), spawnPos.z());
                copy.setYRot(entity.getYRot());
                copy.setXRot(entity.getXRot());
                copy.setYHeadRot(entity.getYHeadRot());
                copy.setSnapshotXRot(entity.getXRot());
                copy.setPose(entity.getPose());

                if (level.getEntitiesOfClass(GlitchyIllusionEntity.class, copy.getBoundingBox().inflate(0.05D)).isEmpty()) {
                    level.addFreshEntity(copy);

                    this.setIllusionCooldown(stack, (int) Math.max(1D, illusion.getStatData("interval").getValue() * 20D));
                    illusion.getStatisticData().getMetricData("illusions").addValue(1);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("illusion", "creation", 1);
                }
            }
        } else {
            this.setIllusionCooldown(stack, 0);
        }

        if (glitchEnabled && ability.getRankModifierData("phase").isEnabled()) {
            var eyesInsideBlock = areEyesInsideCollidingBlock(entity);

            if (!eyesInsideBlock) {
                this.setLastSafePosition(stack, entity.position());
                this.setPhaseTicks(stack, 0);
            } else {
                if (this.getLastPhaseTick(stack) != gameTime) {
                    this.setLastPhaseTick(stack, gameTime);

                    ability.getStatisticData().getMetricData("phase_duration").addValue(1D / 20D);
                    this.getRelicData(entity, stack).getLevelingData().addExperience("glitch", "phasing", 1D / 20D);
                }

                if (!level.isClientSide())
                    entity.addEffect(new MobEffectInstance(RelicsMobEffects.GLITCH, 5, 0, false, false));

                this.addPhaseTicks(stack, 1);

                var limit = Math.max(1, (int) Math.round(ability.getStatData("phase_time").getValue() * 20D));

                if (this.getPhaseTicks(stack) > limit) {
                    var pos = this.getLastSafePosition(stack);

                    if (entity instanceof ServerPlayer serverPlayer) {
                        serverPlayer.teleportTo(serverPlayer.serverLevel(), pos.x(), pos.y(), pos.z(), entity.getYRot(), entity.getXRot());
                        serverPlayer.setDeltaMovement(Vec3.ZERO);
                    } else {
                        entity.teleportTo(pos.x(), pos.y(), pos.z());
                        entity.setDeltaMovement(Vec3.ZERO);
                    }

                    level.playSound(null, BlockPos.containing(pos), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1F, 1F);

                    this.setPhaseTicks(stack, 0);
                    ability.getStatisticData().getMetricData("phase_rollbacks").addValue(1);
                }
            }
        }
    }

public boolean tryDeposit(Fluid fluid, BlockPos root, boolean simulate) {
		if (!Objects.equals(root, rootPos)) {
			reset();
			rootPos = root;
			queue.enqueue(new BlockPosEntry(root, 0));
			affectedArea = BoundingBox.fromCorners(rootPos, rootPos);
			return false;
		}

		if (counterpartActed) {
			counterpartActed = false;
			softReset(root);
			return false;
		}

		if (affectedArea == null)
			affectedArea = BoundingBox.fromCorners(root, root);

		if (revalidateIn == 0) {
			visited.clear();
			infinityCheckFrontier.clear();
			infinityCheckVisited.clear();
			infinityCheckFrontier.add(new BlockPosEntry(root, 0));
			setValidationTimer();
			softReset(root);
		}

		Level world = getWorld();
		int maxRange = maxRange();
		int maxRangeSq = maxRange * maxRange;
		int maxBlocks = maxBlocks();
		boolean evaporate = world.dimensionType()
			.ultraWarm() && FluidHelper.isTag(fluid, FluidTags.WATER);
		boolean canPlaceSources = AllConfigs.server().fluids.fluidFillPlaceFluidSourceBlocks.get();

		if ((!fillInfinite() && infinite) || evaporate || !canPlaceSources) {
			FluidState fluidState = world.getFluidState(rootPos);
			boolean equivalentTo = fluidState.getType()
				.isSame(fluid);
			if (!equivalentTo && !evaporate && canPlaceSources)
				return false;
			if (simulate)
				return true;
			playEffect(world, root, fluid, false);
			if (evaporate) {
				int i = root.getX();
				int j = root.getY();
				int k = root.getZ();
				world.playSound(null, i, j, k, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F,
					2.6F + (world.random.nextFloat() - world.random.nextFloat()) * 0.8F);
			} else if (!canPlaceSources)
				blockEntity.award(AllAdvancements.HOSE_PULLEY);
			return true;
		}

		boolean success = false;
		for (int i = 0; !success && !queue.isEmpty() && i < searchedPerTick; i++) {
			BlockPosEntry entry = queue.first();
			BlockPos currentPos = entry.pos();

			if (visited.contains(currentPos)) {
				queue.dequeue();
				continue;
			}

			if (!simulate)
				visited.add(currentPos);

			if (visited.size() >= maxBlocks && maxBlocks != -1) {
				infinite = true;
				if (!fillInfinite()) {
					visited.clear();
					queue.clear();
					return false;
				}
			}

			SpaceType spaceType = getAtPos(world, currentPos, fluid);
			if (spaceType == SpaceType.BLOCKING)
				continue;
			if (spaceType == SpaceType.FILLABLE) {
				success = true;
				if (!simulate) {
					playEffect(world, currentPos, fluid, false);

					BlockState blockState = world.getBlockState(currentPos);
					if (blockState.hasProperty(BlockStateProperties.WATERLOGGED) && fluid.isSame(Fluids.WATER)) {
						if (!blockEntity.isVirtual())
							world.setBlock(currentPos,
								updatePostWaterlogging(blockState.setValue(BlockStateProperties.WATERLOGGED, true)),
								2 | 16);
					} else {
						replaceBlock(world, currentPos, blockState);
						if (!blockEntity.isVirtual())
							world.setBlock(currentPos, FluidHelper.convertToStill(fluid)
								.defaultFluidState()
								.createLegacyBlock(), 2 | 16);
					}

					LevelTickAccess<Fluid> pendingFluidTicks = world.getFluidTicks();
					if (pendingFluidTicks instanceof LevelTicks<Fluid> serverTickList) {
						serverTickList.clearArea(new BoundingBox(currentPos));
					}

					affectedArea = BBHelper.encapsulate(affectedArea, currentPos);
				}
			}

			if (simulate && success)
				return true;

			visited.add(currentPos);
			queue.dequeue();

			for (Direction side : Iterate.directions) {
				if (side == Direction.UP)
					continue;

				BlockPos offsetPos = currentPos.relative(side);
				if (visited.contains(offsetPos))
					continue;
				if (offsetPos.distSqr(rootPos) > maxRangeSq)
					continue;

				SpaceType nextSpaceType = getAtPos(world, offsetPos, fluid);
				if (nextSpaceType != SpaceType.BLOCKING)
					queue.enqueue(new BlockPosEntry(offsetPos, entry.distance() + 1));
			}
		}

		if (!simulate && success)
			blockEntity.award(AllAdvancements.HOSE_PULLEY);
		return success;
	}

public InteractionResult useOn(UseOnContext pContext) {
        Level level = pContext.getLevel();
        BlockPos blockpos = pContext.getClickedPos();
        Player player = pContext.getPlayer();
        InteractionHand hand = pContext.getHand();
        ItemStack stack = pContext.getItemInHand();
        BlockState blockState = level.getBlockState(blockpos);
        if (player != null) {
            if (IWand.getFocus(stack).getItem() instanceof RecallFocus recallFocus){
                CompoundTag compoundTag = IWand.getFocus(stack).getOrCreateTag();
                if (!RecallFocus.hasRecall(IWand.getFocus(stack))){
                    BlockEntity tileEntity = level.getBlockEntity(blockpos);
                    if (tileEntity instanceof ArcaBlockEntity arcaTile) {
                        if (pContext.getPlayer() == arcaTile.getPlayer() && arcaTile.getLevel() != null) {
                            recallFocus.addRecallTags(arcaTile.getLevel().dimension(), arcaTile.getBlockPos(), compoundTag);
                            IWand.getFocus(stack).setTag(compoundTag);
                            player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                            if (!level.isClientSide) {
                                ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F));
                            }
                            return InteractionResult.sidedSuccess(level.isClientSide);
                        }
                    }
                    if (blockState.is(ModTags.Blocks.RECALL_BLOCKS)) {
                        recallFocus.addRecallTags(level.dimension(), blockpos, compoundTag);
                        IWand.getFocus(stack).setTag(compoundTag);
                        player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                        if (!level.isClientSide) {
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F));
                        }
                        return InteractionResult.sidedSuccess(level.isClientSide);
                    }
                }
            } else if (IWand.getFocus(stack).getItem() instanceof CommandFocus){
                if (CommandFocus.hasServant(IWand.getFocus(stack)) && CommandFocus.getServant(IWand.getFocus(stack)) instanceof IServant summoned){
                    LivingEntity livingEntity = CommandFocus.getServant(IWand.getFocus(stack));
                    if (livingEntity != null) {
                        if (summoned.getTrueOwner() == player && livingEntity.distanceTo(player) <= 64) {
                            BlockPos above = blockpos.above();
                            boolean flag = false;
                            if (summoned.canCommandToBlock(level, blockpos)) {
                                summoned.setCommandPos(blockpos);
                                flag = true;
                            } else if (summoned.canCommandToBlock(level, above)) {
                                summoned.setCommandPos(above);
                                flag = true;
                            }
                            if (flag) {
                                player.playSound(ModSounds.COMMAND.get(), 1.0F, 0.45F);
                                if (!level.isClientSide) {
                                    ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(ModSounds.COMMAND.get(), 1.0F, 0.45F));
                                }
                                return InteractionResult.sidedSuccess(level.isClientSide);
                            }
                        }
                    }
                }
            } else if (IWand.getFocus(stack).getItem() instanceof OrderFocus){
                if (!OrderFocus.getServants(IWand.getFocus(stack)).isEmpty()) {
                    int i = 0;
                    for (LivingEntity livingEntity : OrderFocus.getServants(IWand.getFocus(stack))) {
                        if (livingEntity instanceof IServant summoned && summoned.canBeCommanded()) {
                            if (summoned.getTrueOwner() == player && livingEntity.distanceTo(player) <= 64) {
                                BlockPos above = blockpos.above();
                                if (summoned.canCommandToBlock(level, blockpos)) {
                                    summoned.setCommandPos(blockpos);
                                    ++i;
                                } else if (summoned.canCommandToBlock(level, above)) {
                                    summoned.setCommandPos(above);
                                    ++i;
                                }
                            }
                        }
                    }
                    if (i > 0) {
                        player.playSound(ModSounds.COMMAND.get(), 1.0F, 0.45F);
                        if (!level.isClientSide) {
                            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(ModSounds.COMMAND.get(), 1.0F, 0.45F));
                        }
                        return InteractionResult.sidedSuccess(level.isClientSide);
                    }
                }
            } else if (this.getSpell(stack) instanceof IBlockSpell blockSpell0){
                ISpell spell2 = GoetyEventFactory.onBlockBasedSpell(player.level, blockpos, blockState, blockSpell0, pContext.getClickedFace(), player);
                if (spell2 instanceof IBlockSpell blockSpell) {
                    if (player.level instanceof ServerLevel serverLevel) {
                        if (blockSpell.rightBlock(serverLevel, player, blockpos, pContext.getClickedFace(), WandUtil.getStats(player, blockSpell))) {
                            if (this.canCastTouch(stack, level, player, null)) {
                                blockSpell.blockResult(serverLevel, player, stack, blockpos, pContext.getClickedFace(), WandUtil.getStats(player, blockSpell));
                            }
                            return InteractionResult.SUCCESS;
                        }
                    }
                }
            } else if (blockState.is(BlockTags.BANNERS) && level.getBlockEntity(blockpos) instanceof BannerBlockEntity bannerBlock){
                if (!level.isClientSide){
                    CompoundTag compoundtag = BlockItem.getBlockEntityData(bannerBlock.getItem());
                    if (compoundtag != null) {
                        if (compoundtag.contains("Patterns")) {
                            SEHelper.setBannerBaseColor(player, bannerBlock.getBaseColor());
                            SEHelper.setBannerPattern(player, compoundtag.getList("Patterns", 10));
                            player.displayClientMessage(Component.translatable("info.goety.banner.add", player.getDisplayName()), true);
                            level.playSound(null, blockpos.getX(), blockpos.getY(), blockpos.getZ(), ModSounds.CAST_SPELL.get(), SoundSource.BLOCKS, 1.0F, 0.5F);
                            return InteractionResult.SUCCESS;
                        }
                    }
                }
            } else if (blockState.getBlock() instanceof BrewCauldronBlock) {
                if (!level.isClientSide) {
                    if (level.getBlockEntity(blockpos) instanceof BrewCauldronBlockEntity cauldronBlock) {
                        if (MobUtil.isShifting(player)) {
                            if (stack.getItem() instanceof IWand){
                                cauldronBlock.fullReset();
                                level.playSound(null, blockpos, SoundEvents.BUCKET_EMPTY, SoundSource.BLOCKS, 1.0F, 1.0F);
                                level.playSound(null, blockpos, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 1.0F, 1.0F);
                                return InteractionResult.SUCCESS;
                            }
                        }
                    }
                }
            } else if (blockState.getBlock() instanceof HauntedJugBlock) {
                if (!level.isClientSide) {
                    level.playSound(null, blockpos, SoundEvents.BOTTLE_FILL, SoundSource.BLOCKS, 1.0F, 1.0F);
                    level.setBlockAndUpdate(blockpos, blockState.setValue(HauntedJugBlock.ENABLED, !blockState.getValue(HauntedJugBlock.ENABLED)));
                    return InteractionResult.SUCCESS;
                }
            } else if (!blockState.isAir()){
                if (!level.isClientSide){
                    return blockState.use(level, player, hand, new BlockHitResult(pContext.getClickLocation(), pContext.getClickedFace(), pContext.getClickedPos(), pContext.isInside()));
                }
            }
        }
        return super.useOn(pContext);
    }

