public void attemptToSend(List<PackagingRequest> queuedRequests) {
		if (queuedRequests == null && (!heldBox.isEmpty() || animationTicks != 0 || buttonCooldown > 0))
			return;

		IItemHandler targetInv = targetInventory.getInventory();
		if (targetInv == null || targetInv instanceof PackagerItemHandler)
			return;

		boolean anyItemPresent = false;
		ItemStackHandler extractedItems = new ItemStackHandler(PackageItem.SLOTS);
		ItemStack extractedPackageItem = ItemStack.EMPTY;
		PackagingRequest nextRequest = null;
		String fixedAddress = null;
		int fixedOrderId = 0;

		// Data written to packages for defrags
		int linkIndexInOrder = 0;
		boolean finalLinkInOrder = false;
		int packageIndexAtLink = 0;
		boolean finalPackageAtLink = false;
		PackageOrderWithCrafts orderContext = null;
		boolean requestQueue = queuedRequests != null;

		if (requestQueue && !queuedRequests.isEmpty()) {
			nextRequest = queuedRequests.get(0);
			fixedAddress = nextRequest.address();
			fixedOrderId = nextRequest.orderId();
			linkIndexInOrder = nextRequest.linkIndex();
			finalLinkInOrder = nextRequest.finalLink()
				.booleanValue();
			packageIndexAtLink = nextRequest.packageCounter()
				.getAndIncrement();
			orderContext = nextRequest.context();
		}

		Outer:
		for (int i = 0; i < PackageItem.SLOTS; i++) {
			boolean continuePacking = true;

			while (continuePacking) {
				continuePacking = false;

				for (int slot = 0; slot < targetInv.getSlots(); slot++) {
					int initialCount = requestQueue ? Math.min(64, nextRequest.getCount()) : 64;
					ItemStack extracted = targetInv.extractItem(slot, initialCount, true);
					if (extracted.isEmpty())
						continue;
					if (requestQueue && !ItemStack.isSameItemSameComponents(extracted, nextRequest.item()))
						continue;

					boolean bulky = !extracted.getItem()
						.canFitInsideContainerItems();
					if (bulky && anyItemPresent)
						continue;

					anyItemPresent = true;
					int leftovers = ItemHandlerHelper.insertItemStacked(extractedItems, extracted.copy(), false)
						.getCount();
					int transferred = extracted.getCount() - leftovers;
					targetInv.extractItem(slot, transferred, false);

					if (extracted.getItem() instanceof PackageItem)
						extractedPackageItem = extracted;

					if (!requestQueue) {
						if (bulky)
							break Outer;
						continue;
					}

					nextRequest.subtract(transferred);

					if (!nextRequest.isEmpty()) {
						if (bulky)
							break Outer;
						continue;
					}

					finalPackageAtLink = true;
					queuedRequests.remove(0);
					if (queuedRequests.isEmpty())
						break Outer;
					int previousCount = nextRequest.packageCounter()
						.intValue();
					nextRequest = queuedRequests.get(0);
					if (!fixedAddress.equals(nextRequest.address()))
						break Outer;
					if (fixedOrderId != nextRequest.orderId())
						break Outer;

					nextRequest.packageCounter()
						.setValue(previousCount);
					finalPackageAtLink = false;
					continuePacking = true;
					if (nextRequest.context() != null)
						orderContext = nextRequest.context();

					if (bulky)
						break Outer;
					break;
				}
			}
		}

		if (!anyItemPresent) {
			if (nextRequest != null)
				queuedRequests.remove(0);
			return;
		}

		ItemStack createdBox =
			extractedPackageItem.isEmpty() ? PackageItem.containing(extractedItems) : extractedPackageItem.copy();
		computerBehaviour.prepareComputerEvent(new PackageEvent(createdBox, "package_created"));
		PackageItem.clearAddress(createdBox);

		if (fixedAddress != null)
			PackageItem.addAddress(createdBox, fixedAddress);
		if (requestQueue)
			PackageItem.setOrder(createdBox, fixedOrderId, linkIndexInOrder, finalLinkInOrder, packageIndexAtLink,
				finalPackageAtLink, orderContext);
		if (!requestQueue && !signBasedAddress.isBlank())
			PackageItem.addAddress(createdBox, signBasedAddress);

		BlockPos linkPos = getLinkPos();
		if (extractedPackageItem.isEmpty() && linkPos != null
			&& level.getBlockEntity(linkPos) instanceof PackagerLinkBlockEntity plbe)
			plbe.behaviour.deductFromAccurateSummary(extractedItems);

		if (!heldBox.isEmpty() || animationTicks != 0) {
			queuedExitingPackages.add(new BigItemStack(createdBox, 1));
			return;
		}

		heldBox = createdBox;
		animationInward = false;
		animationTicks = CYCLE;

		advancements.awardPlayer(AllAdvancements.PACKAGER);
		triggerStockCheck();
		notifyUpdate();
	}

@Override
    public InteractionResult onItemUseFirst(ItemStack stack, UseOnContext context) {
        Level level = context.getLevel();
        if (level.isClientSide()) {
            // Needed, otherwise client will trigger onItemRightClick also on server...
            return InteractionResult.SUCCESS;
        }

        Player player = context.getPlayer();
        BlockPos pos = context.getClickedPos();
        Direction side = context.getClickedFace();
        InteractionHand hand = context.getHand();

        if (player == null) {
            return InteractionResult.PASS;
        }

        int x = pos.getX();
        int y = pos.getY();
        int z = pos.getZ();

        if (InteractionUtil.isInAlternateUseMode(player)) {
            var gridHost = GridHelper.getNodeHost(level, pos);

            if (gridHost != null) {
                CustomData.update(DataComponents.CUSTOM_DATA, player.getItemInHand(hand), tag -> {
                    tag.putInt("x", x);
                    tag.putInt("y", y);
                    tag.putInt("z", z);
                    tag.putInt("side", side.ordinal());
                    tag.putString("w", level.dimension().identifier().toString());
                    tag.putInt("r", 0);
                });

                this.outputMsg(player, "Set replicator source");
            } else {
                this.outputMsg(player, "This does not host a grid node");
            }
        } else {
            var ish = getTag(player.getItemInHand(hand));
            if (!ish.isEmpty()) {
                final int src_x = ish.getIntOr("x", 0);
                final int src_y = ish.getIntOr("y", 0);
                final int src_z = ish.getIntOr("z", 0);
                final int src_side = ish.getIntOr("side", 0);
                final String worldId = ish.getStringOr("w", "");
                final Level src_w = level.getServer()
                        .getLevel(ResourceKey.create(Registries.DIMENSION, Identifier.parse(worldId)));
                final int replications = ish.getIntOr("r", 0) + 1;

                var gh = GridHelper.getNodeHost(src_w, new BlockPos(src_x, src_y, src_z));

                if (gh != null) {
                    final Direction sideOff = Direction.values()[src_side];
                    final Direction currentSideOff = side;
                    final IGridNode n = gh.getGridNode(sideOff);

                    if (n != null) {
                        final IGrid g = n.getGrid();

                        final ISpatialService sc = g.getSpatialService();

                        if (sc.isValidRegion()) {
                            var min = sc.getMin();
                            var max = sc.getMax();

                            // TODO: Why??? Places it one block up each time...
                            // x += currentSideOff.getXOffset();
                            // y += currentSideOff.getYOffset();
                            // z += currentSideOff.getZOffset();

                            final int sc_size_x = max.getX() - min.getX();
                            final int sc_size_y = max.getY() - min.getY();
                            final int sc_size_z = max.getZ() - min.getZ();

                            final int min_x = min.getX();
                            final int min_y = min.getY();
                            final int min_z = min.getZ();

                            // Invert to maintain correct sign for west/east
                            final int x_rot = (int) -Math.signum(Mth.wrapDegrees(player.getYRot()));
                            // Rotate by 90 degree, so north/south are negative/positive
                            final int z_rot = (int) Math.signum(Mth.wrapDegrees(player.getYRot() + 90));

                            // Loops for replication in each direction
                            for (int r_x = 0; r_x < replications; r_x++) {
                                for (int r_y = 0; r_y < replications; r_y++) {
                                    for (int r_z = 0; r_z < replications; r_z++) {

                                        // Offset x/z by the rotation index.
                                        // For sake of simplicity always grow upwards.
                                        final int rel_x = min.getX() - src_x + x + r_x * sc_size_x * x_rot;
                                        final int rel_y = min.getY() - src_y + y + r_y * sc_size_y;
                                        final int rel_z = min.getZ() - src_z + z + r_z * sc_size_z * z_rot;

                                        // Copy a single SC instance completely
                                        for (int i = 1; i < sc_size_x; i++) {
                                            for (int j = 1; j < sc_size_y; j++) {
                                                for (int k = 1; k < sc_size_z; k++) {
                                                    final BlockPos p = new BlockPos(min_x + i, min_y + j,
                                                            min_z + k);
                                                    final BlockPos d = new BlockPos(i + rel_x, j + rel_y,
                                                            k + rel_z);

                                                    final BlockState state = src_w.getBlockState(p);
                                                    final BlockState prev = level.getBlockState(d);

                                                    level.setBlockAndUpdate(d, state);
                                                    if (state.hasBlockEntity()) {
                                                        final BlockEntity ote = src_w.getBlockEntity(p);
                                                        var dataOutput = TagValueOutput.createWithContext(
                                                                ProblemReporter.DISCARDING, level.registryAccess());
                                                        ote.saveWithId(dataOutput);
                                                        var newBe = BlockEntity.loadStatic(d, state,
                                                                dataOutput.buildResult(),
                                                                level.registryAccess());
                                                        if (newBe != null) {
                                                            level.setBlockEntity(newBe);
                                                        }
                                                    }
                                                    level.sendBlockUpdated(d, prev, state, 3);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        } else {
                            this.outputMsg(player, "requires valid spatial pylon setup.");
                        }
                    } else {
                        this.outputMsg(player, "No grid node?");
                    }
                } else {
                    this.outputMsg(player, "Src is no longer a grid block?");
                }
            } else {
                this.outputMsg(player, "No Source Defined");
            }
        }
        return InteractionResult.SUCCESS;
    }

@Override
	public void tickServer()
	{
		int timeKey = getBlockPos().getX()^getBlockPos().getZ();
		int energyDrain = IEServerConfig.MACHINES.teslacoil_consumption.get();
		if(lowPower)
			energyDrain /= 2;
		if(level.getGameTime()%32==(timeKey&31)&&canRun(energyDrain))
		{
			this.energyStorage.extractEnergy(energyDrain, false);

			double radius = 6;
			if(lowPower)
				radius /= 2;
			AABB aabbSmall = new AABB(getBlockPos().getX()+.5-radius, getBlockPos().getY()+.5-radius, getBlockPos().getZ()+.5-radius, getBlockPos().getX()+.5+radius, getBlockPos().getY()+.5+radius, getBlockPos().getZ()+.5+radius);
			AABB aabb = aabbSmall.inflate(radius/2);
			List<Entity> targetsAll = level.getEntitiesOfClass(Entity.class, aabb);
			List<Entity> targets = targetsAll.stream().filter((e) -> (e instanceof LivingEntity&&aabbSmall.intersects(e.getBoundingBox()))).collect(Collectors.toList());
			LivingEntity target = null;
			if(!targets.isEmpty())
			{
				ElectricDamageSource dmgsrc = IEDamageSources.causeTeslaDamage(level, IEServerConfig.MACHINES.teslacoil_damage.get().floatValue(), lowPower);
				int randomTarget = ApiUtils.RANDOM.nextInt(targets.size());
				target = (LivingEntity)targets.get(randomTarget);
				if(target!=null)
				{
					if(!level.isClientSide)
					{
						energyDrain = IEServerConfig.MACHINES.teslacoil_consumption_active.get();
						if(lowPower)
							energyDrain /= 2;
						if(energyStorage.extractEnergy(energyDrain, true)==energyDrain)
						{
							energyStorage.extractEnergy(energyDrain, false);
							target.addEffect(new MobEffectInstance(IEPotions.STUNNED, 128));
							if(dmgsrc.apply(target))
							{
								int prevFire = target.getRemainingFireTicks();
								target.setRemainingFireTicks(1);
								target.setRemainingFireTicks(prevFire);
							}
							this.sendRenderPacket(target);
						}
					}
				}
			}
			for(Entity e : targetsAll)
				if(e!=target)
				{
					if(e instanceof ITeslaEntity)
						((ITeslaEntity)e).onHit(this, lowPower);
					else if(e instanceof LivingEntity)
						IElectricEquipment.applyToEntity((LivingEntity)e, null, TC_FIELD);
				}
			if(targets.isEmpty()&&level.getGameTime()%128==(timeKey&127))
			{
				//target up to 4 blocks away
				double tV = (ApiUtils.RANDOM.nextDouble()-.5)*8;
				double tH = (ApiUtils.RANDOM.nextDouble()-.5)*8;
				if(lowPower)
				{
					tV /= 2;
					tH /= 2;
				}
				//Minimal distance to the coil is 2 blocks
				tV += tV < 0?-2: 2;
				tH += tH < 0?-2: 2;

				// TODO this looks like it might be wrong?
				BlockPos targetBlock = getBlockPos().offset(
						(int)(getFacing().getAxis()==Axis.X?0: tH),
						(int)(getFacing().getAxis()==Axis.Y?0: tV),
						(int)(getFacing().getAxis()==Axis.Y?tV: getFacing().getAxis()==Axis.X?tH: 0)
				);
				double tL = 0;
				boolean targetFound = false;
				if(!level.isEmptyBlock(targetBlock))
				{
					BlockState state = level.getBlockState(targetBlock);
					VoxelShape shape = state.getShape(level, targetBlock);
					if(!shape.isEmpty())
					{
						AABB blockBounds = shape.bounds();
						if(getFacing()==Direction.UP)
							tL = targetBlock.getY()-getBlockPos().getY()+blockBounds.maxY;
						else if(getFacing()==Direction.DOWN)
							tL = targetBlock.getY()-getBlockPos().getY()+blockBounds.minY;
						else if(getFacing()==Direction.NORTH)
							tL = targetBlock.getZ()-getBlockPos().getZ()+blockBounds.minZ;
						else if(getFacing()==Direction.SOUTH)
							tL = targetBlock.getZ()-getBlockPos().getZ()+blockBounds.maxZ;
						else if(getFacing()==Direction.WEST)
							tL = targetBlock.getX()-getBlockPos().getX()+blockBounds.minX;
						else
							tL = targetBlock.getX()-getBlockPos().getX()+blockBounds.maxX;
						targetFound = true;
					}
				}
				if(!targetFound)
				{
					boolean positiveFirst = ApiUtils.RANDOM.nextBoolean();
					for(int i = 0; i < 2; i++)
					{
						for(int ll = 0; ll <= 6; ll++)
						{
							BlockPos targetBlock2 = targetBlock.relative(positiveFirst?getFacing(): getFacing().getOpposite(), ll);
							if(!level.isEmptyBlock(targetBlock2))
							{
								BlockState state = level.getBlockState(targetBlock2);
								VoxelShape shape = state.getShape(level, targetBlock2);
								if(shape.isEmpty())
									continue;
								AABB blockBounds = shape.bounds();
								tL = getFacing().getAxis()==Axis.Y?(targetBlock2.getY()-getBlockPos().getY()): getFacing().getAxis()==Axis.Z?(targetBlock2.getZ()-getBlockPos().getZ()): (targetBlock2.getZ()-getBlockPos().getZ());
								Direction tempF = positiveFirst?getFacing(): getFacing().getOpposite();
								if(tempF==Direction.UP)
									tL += blockBounds.maxY;
								else if(tempF==Direction.DOWN)
									tL += blockBounds.minY;
								else if(tempF==Direction.NORTH)
									tL += blockBounds.minZ;
								else if(tempF==Direction.SOUTH)
									tL += blockBounds.maxZ;
								else if(tempF==Direction.WEST)
									tL += blockBounds.minX;
								else
									tL += blockBounds.maxX;
								targetFound = true;
								break;
							}
						}
						if(targetFound)
							break;
						positiveFirst = !positiveFirst;
					}
				}
				if(targetFound)
					sendFreePacket(tL, tH, tV);
			}
			this.setChanged();
		}
	}

public void tick() {
        boolean flag = this.checkCage();
        if (this.level == null){
            return;
        }
        if (flag) {
            if (this.cursedCageTile.getSouls() > 0){
                RitualRecipe recipe = this.getCurrentRitualRecipe();
                double d0 = (double)this.worldPosition.getX() + this.level.random.nextDouble();
                double d1 = (double)this.worldPosition.getY() + this.level.random.nextDouble();
                double d2 = (double)this.worldPosition.getZ() + this.level.random.nextDouble();
                if (!this.level.isClientSide) {
                    ServerLevel serverWorld = (ServerLevel) this.level;
                    if (recipe != null) {

                        this.restoreCastingPlayer();

                        if (this.castingPlayer == null || !this.sacrificeFulfilled()) {
                            for (int p = 0; p < 4; ++p) {
                                serverWorld.sendParticles(ParticleTypes.FLAME, d0, d1, d2, 1, 0.0F, 0.0F, 0.0F, 0.0F);
                            }
                        }

                        ServerParticleUtil.addAuraParticles(serverWorld, ModParticleTypes.TOTEM_EFFECT.get(), Vec3.atBottomCenterOf(this.worldPosition).add(0, 0.25, 0), 0.75F);

                        if (this.remainingAdditionalIngredients == null) {
                            this.restoreRemainingAdditionalIngredients();
                            if (this.remainingAdditionalIngredients == null) {
                                Goety.LOGGER
                                        .warn("Could not restore remainingAdditionalIngredients during tick - world seems to be null. Will attempt again next tick.");
                                return;
                            }
                        }

                        if (recipe.getRitual().isPending(this)) {
                            return;
                        }

                        IItemHandler handler = this.itemStackHandler.orElseThrow(RuntimeException::new);
                        if (!recipe.getRitual().isValid(this.level, this.worldPosition, this, this.castingPlayer,
                                handler.getStackInSlot(0), this.remainingAdditionalIngredients)) {
                            this.stopRitual(false);
                            return;
                        }

                        if (this.castingPlayer == null || !this.sacrificeFulfilled()) {
                            return;
                        }

                        if (this.level.getGameTime() % 20 == 0) {
                            if (this.cursedCageTile.getSouls() >= recipe.getSoulCost()){
                                this.cursedCageTile.decreaseSouls(recipe.getSoulCost());
                                serverWorld.playSound(null, this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, SoundSource.BLOCKS, 1.0F, this.level.random.nextFloat() * 0.1F + 0.9F);
                                serverWorld.sendParticles(ParticleTypes.SCULK_SOUL, (double)this.worldPosition.getX() + 0.5D, (double)this.worldPosition.getY() + 1.15D, (double)this.worldPosition.getZ() + 0.5D, 2, 0.2D, 0.0D, 0.2D, 0.0D);
                                this.currentTime++;
                            } else {
                                this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.noSouls.fail"), true);
                                this.stopRitual(false);
                                return;
                            }
                        }

                        if (recipe.getRitual() instanceof EnchantItemRitual enchantItemRitual) {
                            if (this.experienceTaken < enchantItemRitual.getLevelCost(handler.getStackInSlot(0))) {
                                if (this.castingPlayer.experienceLevel > 1) {
                                    if (this.level.getGameTime() % 10 == 0) {
                                        serverWorld.playSound(null, this.worldPosition, SoundEvents.SCULK_CATALYST_BLOOM, SoundSource.BLOCKS, 0.5F, 0.5F);
                                        this.castingPlayer.giveExperienceLevels(-1);
                                        this.experienceTaken += 1;
                                    }
                                    this.addXPParticles(serverWorld);
                                } else {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.noXP.fail"), true);
                                    this.stopRitual(false);
                                    return;
                                }
                            }
                        }

                        recipe.getRitual().update(this.level, this.worldPosition, this, this.castingPlayer, handler.getStackInSlot(0),
                                this.currentTime, recipe.getDuration());

                        if (!recipe.getRitual()
                                .consumeAdditionalIngredients(this.level, this.worldPosition, this.castingPlayer, this.remainingAdditionalIngredients,
                                        this.currentTime, this.consumedIngredients)) {
                            this.stopRitual(false);
                            return;
                        }

                        if (recipe.getDuration() >= 0 && this.currentTime >= recipe.getDuration()) {
                            if (recipe.getRitual() instanceof EnchantItemRitual enchantItemRitual){
                                if (this.experienceTaken >= enchantItemRitual.getLevelCost(handler.getStackInSlot(0))){
                                    this.stopRitual(true);
                                }
                            } else if (!recipe.isConversion()) {
                                this.stopRitual(true);
                            } else {
                                if (this.getConvertEntity != null){
                                    this.stopRitual(true);
                                } else {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.convert.fail"), true);
                                    this.stopRitual(false);
                                }
                            }
                        }

                        int totalTime = 60;

                        if (!RitualRequirements.getProperStructure(recipe.getCraftType(), this.castingPlayer, this, this.worldPosition, this.level)){
                            ++this.structureTime;
                            if (this.structureTime >= totalTime) {
                                this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.structure.fail"), true);
                                this.stopRitual(false);
                            }
                        } else {
                            this.structureTime = 0;
                        }
                        if (recipe.isConversion()){
                            if (RitualRequirements.noConvertEntity(recipe.getEntityToConvert(), this.worldPosition, this.level)){
                                ++this.convertTime;
                                if (this.getConvertEntity != null){
                                    this.getConvertEntity = null;
                                }
                                if (this.convertTime >= totalTime) {
                                    this.castingPlayer.displayClientMessage(Component.translatable("info.goety.ritual.convert.fail"), true);
                                    this.stopRitual(false);
                                }
                            } else {
                                this.getConvertEntity = RitualRequirements.getConvertEntity(recipe.getEntityToConvert(), this.worldPosition, this.level);
                                this.convertTime = 0;
                            }
                        }
                    } else {
                        if (this.level.getGameTime() % 20 == 0) {
                            ServerParticleUtil.addAuraParticles(serverWorld, ModParticleTypes.TOTEM_EFFECT.get(), Vec3.atBottomCenterOf(this.worldPosition).add(0, 0.25, 0), 0.75F);
                        }
                    }
                }
            } else {
                this.stopRitual(false);
            }
        } else {
            this.stopRitual(false);
        }
        this.level.setBlock(this.getBlockPos(), this.getBlockState().setValue(DarkAltarBlock.LIT, flag), 3);
    }

@Override
	public void render(IMultiblockContext<State> ctx, float partialTicks, PoseStack matrixStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn)
	{
		final MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		final State state = ctx.getState();
		Direction facing = orientation.front();

		final float pixelHeight = 1f/16f;

		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		matrixStack.translate(.5, .5, .5);
		final MultiBufferSource originalBuffer = bufferIn;
		bufferIn = BERenderUtils.mirror(orientation, matrixStack, bufferIn);

		//Item Displacement
		record ItemDisplay(float itemFill, Vector3f translation, BottlingProcess process)
		{
		}
		List<ItemDisplay> itemDisplays = new ArrayList<>();
		//Animations
		float lift = 0;

		Level level = ctx.getLevel().getRawLevel();
		VertexConsumer solidBuilder = bufferIn.getBuffer(RenderType.solid());
		for(int i = 0; i < state.processor.getQueueSize(); i++)
		{
			BottlingProcess process = (BottlingProcess)state.processor.getQueue().get(i);
			if(process==null)
				continue;
			float processMaxTicks = process.getMaxTicks(level);
			float transportTime = BottlingMachineLogic.getTransportTime(processMaxTicks);
			float liftTime = BottlingMachineLogic.getLiftTime(processMaxTicks);
			float fProcess = process.processTick;

			float itemX;
			float itemY = 0;
			float itemFill = 0;

			if(fProcess < transportTime)
				itemX = .5f*fProcess/transportTime;
			else if(fProcess < (processMaxTicks-transportTime))
			{
				itemX = .5f;
				if(fProcess < transportTime+liftTime)
					lift = (fProcess-transportTime)/liftTime;
				else if(fProcess < processMaxTicks-(transportTime+liftTime))
				{
					lift = 1;
					itemFill = (fProcess-(transportTime+liftTime))/(processMaxTicks-2*(transportTime+liftTime));
				}
				else
				{
					lift = 1-(fProcess-(processMaxTicks-transportTime-liftTime))/liftTime;
					itemFill = 1;
				}
				lift *= .125f;
				if(lift > pixelHeight)
					itemY += lift-pixelHeight;
			}
			else
			{
				itemX = .5f+.5f*(fProcess-(processMaxTicks-transportTime))/transportTime;
				itemFill = 1;
			}
			itemDisplays.add(new ItemDisplay(
					itemFill,
					new Vector3f((itemX-0.5f)*BottlingMachineLogic.TRANSLATION_DISTANCE, itemY-.15625f, 1),
					process
			));
		}

		matrixStack.pushPose();

		matrixStack.translate(0, lift, 0);
		renderModelPart(matrixStack, solidBuilder, facing, combinedLightIn, combinedOverlayIn, "lift");
		matrixStack.translate(0, -lift, 0);

		matrixStack.popPose();

		float dir = facing==Direction.SOUTH?Mth.PI: facing==Direction.NORTH?0: facing==Direction.EAST?-Mth.HALF_PI: Mth.HALF_PI;
		matrixStack.mulPose(new Quaternionf().rotateY(dir));

		FluidStack fs = state.tank.getFluid();
		if(!fs.isEmpty())
		{
			final float tankWidth = 7;
			matrixStack.pushPose();
			float fluidLevel = fs.getAmount()/(float)state.tank.getCapacity();
			matrixStack.translate(-.21875, .376, 1.21875);
			matrixStack.scale(pixelHeight, pixelHeight, pixelHeight);
			matrixStack.translate(tankWidth/2, 0, -tankWidth/2);
			float h = fluidLevel*9;
			// TODO does not work on fabulous
			VertexConsumer builder = originalBuffer.getBuffer(RenderType.translucent());
			for(int i = 0; i < 4; ++i)
			{
				matrixStack.pushPose();
				matrixStack.translate(0, 0, -tankWidth/2);
				GuiHelper.drawRepeatedFluidSprite(builder, matrixStack, fs, -tankWidth/2, 0, tankWidth, h);
				matrixStack.popPose();
				matrixStack.mulPose(new Quaternionf().rotateY(Mth.HALF_PI));
			}

			matrixStack.mulPose(new Quaternionf().rotateX(-Mth.HALF_PI));
			GuiHelper.drawRepeatedFluidSprite(builder, matrixStack, fs, -tankWidth/2, -tankWidth/2, tankWidth, tankWidth);
			matrixStack.mulPose(new Quaternionf().rotateX(Mth.PI));
			matrixStack.translate(0, 0, -h);
			GuiHelper.drawRepeatedFluidSprite(builder, matrixStack, fs, -tankWidth/2, -tankWidth/2, tankWidth, tankWidth);

			matrixStack.popPose();
		}


		//DRAW ITEMS HERE
		for(ItemDisplay item : itemDisplays)
		{
			List<ItemStack> display = item.process.getDisplayItem(level);

			matrixStack.pushPose();
			matrixStack.translate(item.translation.x(), item.translation.y(), item.translation.z());
			matrixStack.scale(.4375f, .4375f, .4375f);

			if(!ClientUtils.mc().getMainRenderTarget().isStencilEnabled())
			{
				for(ItemStack displayS : display)
					ClientUtils.mc().getItemRenderer().renderStatic(
							displayS, ItemDisplayContext.FIXED,
							combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
							level, 0
					);
			}
			else
			{
				float h0 = -.5f;
				float h1 = h0+item.itemFill;

				for(ItemStack inputS : item.process.inputItems)
					renderItemPart(bufferIn, matrixStack, inputS, h0, h1, combinedLightIn, combinedOverlayIn, 0, level);
				for(ItemStack displayS : display)
					renderItemPart(bufferIn, matrixStack, displayS, h0, h1, combinedLightIn, combinedOverlayIn, 1, level);
			}

			matrixStack.popPose();
		}
		matrixStack.popPose();
	}

public void tick() {
        super.tick();

        this.prevAttackProgress = attackProgress;
        this.prevBirdPitch = birdPitch;
        this.prevTackleProgress = tackleProgress;
        this.prevFlyProgress = flyProgress;
        this.prevFlapAmount = flapAmount;
        this.prevSwoopProgress = swoopProgress;
        this.prevSitProgress = sitProgress;
        float yMot = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
        this.birdPitch = yMot;

        if (isFlying()) {
            if (flyProgress < 5F)
                flyProgress++;
        } else {
            if (flyProgress > 0F)
                flyProgress--;
        }

        if (isTackling()) {
            if (tackleProgress < 5F)
                tackleProgress++;
        } else {
            if (tackleProgress > 0F)
                tackleProgress--;
        }

        final boolean sit = isSitting() || this.isPassenger();
        if (sit) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (this.isLaunched()) {
            launchTime++;
        } else {
            launchTime = 0;
        }

        if (lastPlayerControlTime > 0) {
            lastPlayerControlTime--;
        }
        if (lastPlayerControlTime <= 0) {
            controlledFlag = false;
        }

        if (yMot < 0.1F) {
            flapAmount = Math.min(-yMot * 0.2F, 1F);
            if (swoopProgress > 0) {
                swoopProgress--;
            }
        } else {
            if (flapAmount > 0.0F) {
                flapAmount -= Math.min(flapAmount, 0.1F);
            } else {
                flapAmount = 0;
            }
            if (swoopProgress < yMot * 0.2F) {
                swoopProgress = Math.min(yMot * 0.2F, swoopProgress + 1);
            }
        }

        if (this.isTackling()) {
            flapAmount = Math.min(2, flapAmount + 0.2F);
        }

        if (!this.level().isClientSide) {
            if (isFlying()) {
                if (this.isLandNavigator)
                    switchNavigator(false);
            } else {
                if (!this.isLandNavigator)
                    switchNavigator(true);
            }

            if (tackleCapCooldown == 0 && this.isTackling() && !this.isVehicle() && (this.getTarget() == null || !this.getTarget().isAlive())) {
                this.setTackling(false);
            }

            if (isFlying()) {
                timeFlying++;
                this.setNoGravity(true);
                if (this.isSitting() || this.isPassenger() || this.isInLove()) {
                    if (!isLaunched()) {
                        this.setFlying(false);
                    }
                }
                if (this.getTarget() != null && this.getTarget().getY() < this.getX() && !this.isVehicle()) {
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1.0, 0.9, 1.0));
                }
            } else {
                timeFlying = 0;
                this.setNoGravity(false);
            }

            if (this.isInWaterOrBubble() && this.isVehicle()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, 0.1F, 0));
            }

            if (this.isSitting() && !this.isLaunched()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.1F, 0));
            }

            if (this.getTarget() != null && this.isInWaterOrBubble()) {
                timeFlying = 0;
                this.setFlying(true);
            }

            if (this.onGround() && this.timeFlying > 30 && isFlying() && !this.isInWaterOrBubble()) {
                this.setFlying(false);
            }
        }

        final int attackTick = this.entityData.get(ATTACK_TICK);
        if (attackTick > 0) {
            if (attackTick == 2 && this.getTarget() != null && this.distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + 2D) {
                this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
            }
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }

        if (this.isPassenger()) {
            this.setFlying(false);
            this.setTackling(false);
        }

        if (boardingCooldown > 0) {
            boardingCooldown--;
        }
        if (returnControlTime > 0) {
            returnControlTime--;
        }
        if (tackleCapCooldown > 0) {
            tackleCapCooldown--;
        }
    }

@Override
    public Map<BlockPos, OreBlockPlacer> generate(WorldGenLevel level, RandomSource random, GTOreDefinition entry,
                                                  BlockPos origin) {
        // TODO refactor geode sizes for the new ore generation system. For now, geode veins are still generated in
        // place.

        BulkSectionAccess access = new BulkSectionAccess(level);

        BlockState blockState;
        int offset;
        int offset2;
        int minOffset = this.minGenOffset;
        int maxOffset = this.maxGenOffset;
        int distributionSample = this.distributionPoints.sample(random);
        List<ObjectIntPair<BlockPos>> points = new ArrayList<>(distributionSample);
        WorldgenRandom worldgenRandom = new WorldgenRandom(new LegacyRandomSource(level.getSeed()));
        NormalNoise normalNoise = NormalNoise.create(worldgenRandom, -4, 1.0);
        List<BlockPos> list2 = new ArrayList<>(3);
        double wallDistance = (double) distributionSample / (double) this.outerWallDistance.getMaxValue();
        double fillingSize = 1.0 / Math.sqrt(geodeLayerSettings.filling);
        double innerSize = 1.0 / Math.sqrt(geodeLayerSettings.innerLayer + wallDistance);
        double middleSize = 1.0 / Math.sqrt(geodeLayerSettings.middleLayer + wallDistance);
        double outerSize = 1.0 / Math.sqrt(geodeLayerSettings.outerLayer + wallDistance);
        double crackSize = 1.0 / Math.sqrt(geodeCrackSettings.baseCrackSize + random.nextDouble() / 2.0 +
                (distributionSample > 3 ? wallDistance : 0.0));
        boolean doCrack = (double) random.nextFloat() < geodeCrackSettings.generateCrackChance;
        int invalidBlocksCount = 0;
        for (offset2 = 0; offset2 < distributionSample; ++offset2) {
            offset = this.outerWallDistance.sample(random);
            BlockPos origin2 = origin.offset(offset, this.outerWallDistance.sample(random),
                    this.outerWallDistance.sample(random));
            blockState = access.getBlockState(origin2);
            if ((blockState.isAir() || blockState.is(BlockTags.GEODE_INVALID_BLOCKS)) &&
                    ++invalidBlocksCount > this.invalidBlocksThreshold) {
                return Map.of();
            }
            points.add(ObjectIntPair.of(origin2, this.pointOffset.sample(random)));
        }
        if (doCrack) {
            offset2 = random.nextInt(4);
            offset = distributionSample * 2 + 1;
            if (offset2 == 0) {
                list2.add(origin.offset(offset, 7, 0));
                list2.add(origin.offset(offset, 5, 0));
                list2.add(origin.offset(offset, 1, 0));
            } else if (offset2 == 1) {
                list2.add(origin.offset(0, 7, offset));
                list2.add(origin.offset(0, 5, offset));
                list2.add(origin.offset(0, 1, offset));
            } else if (offset2 == 2) {
                list2.add(origin.offset(offset, 7, offset));
                list2.add(origin.offset(offset, 5, offset));
                list2.add(origin.offset(offset, 1, offset));
            } else {
                list2.add(origin.offset(0, 7, 0));
                list2.add(origin.offset(0, 5, 0));
                list2.add(origin.offset(0, 1, 0));
            }
        }
        List<BlockPos> positions = new ArrayList<>();
        Predicate<BlockState> placementPredicate = GeodeFeature.isReplaceable(this.geodeBlockSettings.cannotReplace);
        for (BlockPos pos : BlockPos.betweenClosed(origin.offset(minOffset, minOffset, minOffset),
                origin.offset(maxOffset, maxOffset, maxOffset))) {
            double noiseValue = normalNoise.getValue(pos.getX(), pos.getY(), pos.getZ()) * this.noiseMultiplier;
            double s = 0.0;
            double t = 0.0;
            for (var pair : points) {
                s += Mth.invSqrt(pos.distSqr(pair.first()) + (double) pair.secondInt()) + noiseValue;
            }
            for (BlockPos origin4 : list2) {
                t += Mth.invSqrt(pos.distSqr(origin4) + (double) geodeCrackSettings.crackPointOffset) + noiseValue;
            }
            if (s < outerSize) continue;
            if (!level.ensureCanWrite(pos))
                continue;
            LevelChunkSection section = access.getSection(pos);
            if (section == null)
                continue;
            if (doCrack && t >= crackSize && s < fillingSize) {
                this.safeSetBlock(access, section, pos, Blocks.AIR.defaultBlockState(), placementPredicate);
                for (Direction direction : DIRECTIONS) {
                    BlockPos origin5 = pos.relative(direction);
                    FluidState fluidState = level.getFluidState(origin5);
                    if (fluidState.isEmpty()) continue;
                    level.scheduleTick(origin5, fluidState.getType(), 0);
                }
                continue;
            }
            if (s >= fillingSize) {
                this.safeSetBlock(access, section, pos,
                        getStateFromEither(geodeBlockSettings.fillingProvider, geodeBlockSettings, random, pos),
                        placementPredicate);
                continue;
            }
            if (s >= innerSize) {
                boolean useAltLayer = (double) random.nextFloat() < this.useAlternateLayer0Chance;
                if (useAltLayer) {
                    this.safeSetBlock(access, section, pos,
                            getStateFromEither(geodeBlockSettings.alternateInnerLayerProvider, geodeBlockSettings,
                                    random, pos),
                            placementPredicate);
                } else {
                    this.safeSetBlock(access, section, pos,
                            getStateFromEither(geodeBlockSettings.innerLayerProvider, geodeBlockSettings, random, pos),
                            placementPredicate);
                }
                if (this.placementsRequireLayer0Alternate && !useAltLayer ||
                        !((double) random.nextFloat() < this.usePotentialPlacementsChance))
                    continue;
                positions.add(pos.immutable());
                continue;
            }
            if (s >= middleSize) {
                this.safeSetBlock(access, section, pos,
                        getStateFromEither(geodeBlockSettings.middleLayerProvider, geodeBlockSettings, random, pos),
                        placementPredicate);
                continue;
            }
            if (!(s >= outerSize)) continue;
            this.safeSetBlock(access, section, pos,
                    getStateFromEither(geodeBlockSettings.outerLayerProvider, geodeBlockSettings, random, pos),
                    placementPredicate);
        }
        List<BlockState> innerPlacements = geodeBlockSettings.innerPlacements;
        block5:
        for (BlockPos origin2 : positions) {
            blockState = Util.getRandom(innerPlacements, random);
            for (Direction direction2 : DIRECTIONS) {
                if (blockState.hasProperty(BlockStateProperties.FACING)) {
                    blockState = blockState.setValue(BlockStateProperties.FACING, direction2);
                }
                BlockPos origin6 = origin2.relative(direction2);
                BlockState blockState2 = access.getBlockState(origin6);
                if (blockState.hasProperty(BlockStateProperties.WATERLOGGED)) {
                    blockState = blockState.setValue(BlockStateProperties.WATERLOGGED,
                            blockState2.getFluidState().isSource());
                }
                if (!BuddingAmethystBlock.canClusterGrowAtState(blockState2)) continue;
                if (!level.ensureCanWrite(origin6))
                    continue;
                LevelChunkSection section = access.getSection(origin6);
                if (section == null)
                    continue;
                this.safeSetBlock(access, section, origin6, blockState, placementPredicate);
                continue block5;
            }
        }

        access.close();
        return Map.of();
    }

@Override
	public void onUpdate() {
		if (this.world.isRemote) {
			prevGrowCount = growCount;
			growCount = getGrowTimer();
			if (getGrowTimer() > 0 && getGrowTimer() < 40)
				if (this.ticksExisted % 4 == 0)
					this.spawnVolatileParticles(true);
		}

        if (!this.world.isRemote) {
			if (isInTar()) {
				if (getGrowTimer() > 0)
					setGrowTimer(Math.max(0, getGrowTimer() - 1));
				if (getGrowTimer() <= 0) {
					EntityTarBeast tar_beast = new EntityTarBeast(getEntityWorld());
					tar_beast.setPositionAndRotation(posX, posY, posZ, rotationYaw, rotationPitch);
					tar_beast.setGrowTimer(0);
					getEntityWorld().spawnEntity(tar_beast);
					setDead();
				}
			}

			if (!isInTar() && getGrowTimer() < 40)
				setGrowTimer(Math.min(40, getGrowTimer() + 1));

            if (this.getAttackTarget() == null) {
                this.setHiding(true);

                this.canTurnVolatileOnTarget = false;
            } else {
                this.setHiding(false);

                if (this.canTurnVolatile && !this.isVolatile() && !this.isRiding() && this.canPossess(this.getAttackTarget()) && this.canTurnVolatileOnTarget) {
                    if (this.volatileCooldownTicks > 0) {
                        this.volatileCooldownTicks--;
                    }

                    if (this.getHealth() <= this.getMaxHealth() * this.getEntityAttribute(VOLATILE_HEALTH_START_ATTRIB).getAttributeValue() && this.volatileCooldownTicks <= 0) {
                        this.setVolatile(true);
                        this.didTurnVolatileOnPlayer = true;
                        this.volatileReceivedDamage = 0.0F;
                        this.volatileCooldownTicks = this.getMaxVolatileCooldown() + this.world.rand.nextInt(this.getMaxVolatileCooldown()) + 20;
                        this.volatileTicks = 0;

                        TheBetweenlands.networkWrapper.sendToAllAround(new MessageWightVolatileParticles(this), new TargetPoint(this.dimension, this.posX, this.posY, this.posZ, 32));
                        this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.WIGHT_ATTACK, SoundCategory.HOSTILE, 1.6F, 1.0F);
                    }
                } else if (this.didTurnVolatileOnPlayer && this.isVolatile() && !this.canPossess(this.getAttackTarget())) {
                    this.setVolatile(false);
                    this.didTurnVolatileOnPlayer = false;
                }
            }
        }

        if (this.isVolatile()) {
        	if(!this.world.isRemote) {
	        	if (this.volatileTicks < this.getEntityAttribute(VOLATILE_LENGTH_ATTRIB).getAttributeValue()) {
	            	this.volatileTicks++;

	                if (this.volatileTicks >= 20) {
	                    this.noClip = true;
	                }
	            } else {
	                if (!this.world.isRemote) {
	                    this.motionY -= 0.075D;

	                    this.fallDistance = 0;

	                    if (this.didTurnVolatileOnPlayer && this.onGround) {
	                        this.setVolatile(false);
	                        this.didTurnVolatileOnPlayer = false;
	                    }
	                }

	                this.noClip = false;
	            }

	            if (this.volatileTicks < 20) {
	                this.moveHelper.setMoveTo(this.posX, this.posY + 1.0D, this.posZ, 0.15D);
	            }

	            if (this.getAttackTarget() != null) {
	                EntityLivingBase attackTarget = this.getAttackTarget();

	                if (this.getRidingEntity() == null && this.getDistance(attackTarget) < 1.75D && this.canPossess(attackTarget)) {
	                    this.startRiding(attackTarget, true);
	                    this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(attackTarget));
	                }

	                if (this.getRidingEntity() == null) {
	                    double dx = attackTarget.posX - this.posX;
	                    double dz = attackTarget.posZ - this.posZ;
	                    double dy;
	                    if (attackTarget instanceof EntityLivingBase) {
	                        EntityLivingBase entitylivingbase = attackTarget;
	                        dy = entitylivingbase.posY + (double) entitylivingbase.getEyeHeight() - (this.posY + (double) this.getEyeHeight());
	                    } else {
	                        dy = (attackTarget.getEntityBoundingBox().minY + attackTarget.getEntityBoundingBox().maxY) / 2.0D - (this.posY + (double) this.getEyeHeight());
	                    }
	                    double dist = (double) MathHelper.sqrt(dx * dx + dz * dz);
	                    float yaw = (float) (Math.atan2(dz, dx) * 180.0D / Math.PI) - 90.0F;
	                    float pitch = (float) (-(Math.atan2(dy, dist) * 180.0D / Math.PI));
	                    this.setRotation(yaw, pitch);
	                    this.setRotationYawHead(yaw);
	                } else {
	                    this.setRotation(0, 0);
	                    this.setRotationYawHead(0);

	                    if (this.ticksExisted % 5 == 0 && this.canEntityBeSeen(this.getAttackTarget()) && !this.isWearingSkullMask(this.getAttackTarget())) {
	                        List<EntityVolatileSoul> existingSouls = this.world.getEntitiesWithinAABB(EntityVolatileSoul.class, this.getEntityBoundingBox().grow(16.0D, 16.0D, 16.0D));
	                        if (existingSouls.size() < 16) {
	                            EntityVolatileSoul soul = new EntityVolatileSoul(this.world);
	                            float mx = this.world.rand.nextFloat() - 0.5F;
	                            float my = this.world.rand.nextFloat() / 2.0F;
	                            float mz = this.world.rand.nextFloat() - 0.5F;
	                            Vec3d dir = new Vec3d(mx, my, mz).normalize();
	                            soul.setOwner(this.getUniqueID());
	                            soul.setLocationAndAngles(this.posX + dir.x * 0.5D, this.posY + dir.y * 1.5D, this.posZ + dir.z * 0.5D, 0, 0);
	                            soul.shoot(mx * 2.0D, my * 2.0D, mz * 2.0D, 1.0F, 1.0F);
	                            this.world.spawnEntity(soul);
	                        }
	                    }
	                }
	            }

	            this.moveHelper = this.flightMoveHelper;
        	}

            if (this.world.isRemote && (this.getRidingEntity() == null || this.ticksExisted % 4 == 0)) {
                this.spawnVolatileParticles(false);
            }

            this.setSize(0.7F, 0.7F);
        } else {
        	if(!this.world.isRemote) {
	            this.noClip = false;
	            this.moveHelper = this.groundMoveHelper;
        	}

            this.setSize(0.7F, 2.2F);
        }

        this.lastHidingAnimationTicks = this.hidingAnimationTicks;
        if (this.isHiding()) {
            if (this.hidingAnimationTicks < 12)
                this.hidingAnimationTicks++;
        } else {
            if (this.hidingAnimationTicks > 0)
                this.hidingAnimationTicks--;
        }

        super.onUpdate();
    }

private static void apply(boolean afterPack) {
        var frame = prepared;
        var passShader = PhotonShaders.getDynamicLightPassShader();
        var blurShader = PhotonShaders.getDynamicLightBlurShader();
        var compositeShader = PhotonShaders.getDynamicLightCompositeShader();
        if (frame == null || lightCount == 0 && fogCount == 0 || passShader == null || blurShader == null || compositeShader == null) {
            return;
        }
        long start = System.nanoTime();
        var config = PhotonConfig.INSTANCE;
        var scene = frame.scene();
        var level = frame.level();
        boolean soft = config.lightSoftShadows.get();
        int framebuffer = GlStateManager.getBoundFramebuffer();
        int viewportX = GlStateManager.Viewport.x();
        int viewportY = GlStateManager.Viewport.y();
        int viewportWidth = GlStateManager.Viewport.width();
        int viewportHeight = GlStateManager.Viewport.height();
        int width = frame.width(), height = frame.height();
        float scale = config.lightResolution.get().floatValue();
        int lightWidth = Math.max(1, Math.round(width * scale));
        int lightHeight = Math.max(1, Math.round(height * scale));

        LightPassTimer.start();
        var snapshot = scene.snapshot = allocate(scene.snapshot, width, height, TargetFormat.RGBA8, true);
        var lightBuffer = scene.lightBuffer = allocate(scene.lightBuffer, lightWidth, lightHeight, TargetFormat.RGBA16F, false);
        copyRegion(frame.target(), frame.x(), frame.y(), snapshot, afterPack ? IrisCompat.gbufferRenderScale() : 1f);
        LightPassTimer.mark(LightPassTimer.Stage.COPY);

        var projection = frame.projection();
        INVERSE_PROJECTION.set(projection).invert();
        INVERSE_VIEW.set(frame.view()).invert();
        var camera = frame.camera();
        int blockX = Mth.floor(camera.x), blockY = Mth.floor(camera.y), blockZ = Mth.floor(camera.z);
        var voxels = scene.voxels;

        // fog alone lights no surface: no light pass, no composite
        boolean surfaces = lightCount > 0;
        if (surfaces) {
            lightBuffer.bindWrite(true);
            bindCommon(passShader, width, height, scale, afterPack);
            passShader.safeGetUniform("ProjMat").set(projection);
            passShader.setSampler("SceneDepthSampler", snapshot.getDepthTextureId());
            bindLights(passShader, 0, 0);
            passShader.setSampler("VoxelPages", voxels.pageTexture());
            passShader.setSampler("VoxelBricks", voxels.brickTexture());
            passShader.safeGetUniform("ShadowParams").set((float) config.lightShadowMode.get().ordinal(),
                    (float) config.lightScreenShadowSteps.get(), config.lightScreenShadowThickness.get().floatValue(),
                    config.lightScreenShadowDistance.get().floatValue());
            passShader.safeGetUniform("ContactParams").set((float) config.lightContactShadowSteps.get(),
                    config.lightContactShadowLength.get().floatValue(), soft ? 1f : 0f, 0f);
            passShader.safeGetUniform("CameraFrac").set((float) (camera.x - blockX), (float) (camera.y - blockY), (float) (camera.z - blockZ));
            passShader.safeGetUniform("VoxelOrigin").set(voxels.originBlockX() - blockX, voxels.originBlockY() - blockY,
                    voxels.originBlockZ() - blockZ);
            draw(passShader, true);
        }
        LightPassTimer.mark(LightPassTimer.Stage.LIGHT);

        if (surfaces && soft && shadowedCount > 0) {
            var blurBuffer = scene.blurBuffer = allocate(scene.blurBuffer, lightWidth, lightHeight, TargetFormat.RGBA16F, false);
            blurBuffer.bindWrite(true);
            blurPass(blurShader, snapshot, lightBuffer, 1f, 0f, width, height, scale, -1f);
            lightBuffer.bindWrite(true);
            blurPass(blurShader, snapshot, blurBuffer, 0f, 1f, width, height, scale, -1f);
        }
        LightPassTimer.mark(LightPassTimer.Stage.BLUR);

        var volumeShader = PhotonShaders.getDynamicLightVolumeShader();
        var volumeBuffer = (volumeCount > 0 || fogCount > 0) && volumeShader != null
                ? scene.volumeBuffer = allocate(scene.volumeBuffer, lightWidth, lightHeight, TargetFormat.RGBA16F, false)
                : null;
        boolean absorbing = false;
        if (volumeBuffer != null) {
            int shadowedVolumes = Math.min(volumeShadowedCount, visibilityMapCount);
            if (volumeCount > 0) {
                uploadVolumes(frame, afterPack);
                volumeBuffer.bindWrite(true);
                bindCommon(volumeShader, width, height, scale, afterPack);
                volumeShader.setSampler("SceneDepthSampler", snapshot.getDepthTextureId());
                volumeShader.setSampler("VolumeLightData", volumeTexture);
                bindVisibility(volumeShader, scene);
                LightClusters.bindVolume(volumeShader);
                volumeShader.safeGetUniform("VolumeParams").set(config.volumetricForwardScattering.get().floatValue(),
                        (float) config.volumetricSamples.get(), (float) shadowedVolumes, 0f);
                draw(volumeShader, true);
            } else {
                // no haze yet, and a scene that still shows through completely
                volumeBuffer.setClearColor(0f, 0f, 0f, 1f);
                volumeBuffer.clear(Minecraft.ON_OSX);
            }
            LightPassTimer.mark(LightPassTimer.Stage.VOLUME);
            var fogShader = PhotonShaders.getDynamicLightFogShader();
            if (fogCount > 0 && fogShader != null) {
                absorbing = uploadFog(frame, afterPack);
                volumeBuffer.bindWrite(true);
                bindCommon(fogShader, width, height, scale, afterPack);
                fogShader.setSampler("SceneDepthSampler", snapshot.getDepthTextureId());
                bindLights(fogShader, 0, 0);
                bindVisibility(fogShader, scene);
                fogShader.setSampler("FogData", fogTexture);
                fogShader.safeGetUniform("FogInfo").set(fogCount, config.volumetricSamples.get() * 4, 0, 0);
                fogShader.safeGetUniform("ForwardScattering").set(config.volumetricForwardScattering.get().floatValue());
                // rgb adds to the haze, alpha multiplies into the transmittance
                drawBlended(fogShader, true, GL11.GL_ONE, GL11.GL_ONE, GL11.GL_ZERO, GL11.GL_SRC_ALPHA);
            }
            LightPassTimer.mark(LightPassTimer.Stage.FOG);
            if (shadowedVolumes > 0 || fogCount > 0) {
                // the shadowed haze and the fog are sampled at a different offset per pixel of a 4x4 tile
                var blurBuffer = scene.blurBuffer = allocate(scene.blurBuffer, lightWidth, lightHeight, TargetFormat.RGBA16F, false);
                blurBuffer.bindWrite(true);
                blurPass(blurShader, snapshot, volumeBuffer, 1f, 0f, width, height, scale, SKY_DEPTH);
                volumeBuffer.bindWrite(true);
                blurPass(blurShader, snapshot, blurBuffer, 0f, 1f, width, height, scale, SKY_DEPTH);
            }
            LightPassTimer.mark(LightPassTimer.Stage.VOLUME_BLUR);
        }

        // the volume debug view shows black under the haze without reading the light buffer
        if (surfaces || LightDebug.view == 6) {
            frame.target().bindWrite(false);
            RenderSystem.viewport(frame.x(), frame.y(), width, height);
            bindCommon(compositeShader, width, height, scale, afterPack);
            compositeShader.safeGetUniform("ViewportOrigin").set(frame.x(), frame.y());
            compositeShader.setSampler("SceneColorSampler", snapshot.getColorTextureId());
            compositeShader.setSampler("SceneDepthSampler", snapshot.getDepthTextureId());
            compositeShader.setSampler("IrradianceSampler", lightBuffer.getColorTextureId());
            compositeShader.safeGetUniform("FogStart").set(RenderSystem.getShaderFogStart());
            compositeShader.safeGetUniform("FogEnd").set(RenderSystem.getShaderFogEnd());
            var fog = RenderSystem.getShaderFogColor();
            // only the world's own frame is fogged by vanilla's numbers: a pack fogs its own way, an editor scene not at all
            compositeShader.safeGetUniform("FogColor").set(fog[0], fog[1], fog[2], frame.world() && !afterPack ? fog[3] : 0f);
            compositeShader.safeGetUniform("FogShape").set(RenderSystem.getShaderFogShape().getIndex());
            var floor = lightmap(0, 0);
            compositeShader.safeGetUniform("LightmapFloor").set(floor.x, floor.y, floor.z);
            compositeShader.safeGetUniform("FaceShade").set(level.getShade(Direction.DOWN, true), level.getShade(Direction.UP, true),
                    level.getShade(Direction.NORTH, true), level.getShade(Direction.EAST, true));
            compositeShader.safeGetUniform("AlbedoMax").set(config.lightAlbedoMax.get().floatValue());
            draw(compositeShader, false);
        }
        LightPassTimer.mark(LightPassTimer.Stage.COMPOSITE);
        // the other debug views show the surfaces alone
        if (volumeBuffer != null && (LightDebug.view == 0 || LightDebug.view == 6)) {
            var haze = new Haze(frame, new Matrix4f(INVERSE_PROJECTION), scale, afterPack);
            // what the fog hides goes dark now, before the particles: a flame in front of a fog bank stays bright
            if (absorbing) {
                drawHaze(haze, 1);
                LightPassTimer.mark(LightPassTimer.Stage.HAZE);
            }
            pendingHaze = haze;
        }

        restore(framebuffer, viewportX, viewportY, viewportWidth, viewportHeight);
        LightPassTimer.cpu((System.nanoTime() - start) / 1e6);
    }

@Override
    public @NotNull InteractionResult mobInteract(Player pPlayer, @NotNull InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);

        if (this.level().isClientSide()) {
            boolean willInteract = this.isOwnedBy(pPlayer) || this.isTame() || itemstack.is(Items.DIAMOND) && !this.isTame();
            return willInteract ? InteractionResult.CONSUME : InteractionResult.PASS;
        }

        if (!this.isTame()) {
            if (!EventHooks.onAnimalTame(this, pPlayer)) {
                this.tame(pPlayer);
                this.navigation.stop();
                this.setTarget(null);
                this.setOrderedToSit(true);
                this.level().broadcastEntityEvent(this, (byte) 7);
            } else {
                this.level().broadcastEntityEvent(this, (byte) 6);
            }
        }

        if (this.isTame() && this.isOwnedBy(pPlayer)) {

            if (itemstack.is(OccultismItems.CURSED_HONEY.asItem())) {
                long time = this.getHeartTime() + HEART_INTERVAL - this.level().getGameTime();
                if (time < 0) {
                    this.setHeartTime(this.level().getGameTime());
                    this.lastHeartTime = this.level().getGameTime();
                    itemstack.shrink(1);
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(OccultismItems.SWEET_HONEY_HEART.asItem()));
                } else if (pPlayer.level().isClientSide()) {
                    pPlayer.sendOverlayMessage(Component.translatable("dialog.occultism.partner.heart_on_cooldown", time));
                }
                return InteractionResult.SUCCESS;
            }

            var effects = itemstack.getOrDefault(DataComponents.POTION_CONTENTS, PotionContents.EMPTY);
            if (effects.hasEffects()) {
                for (var instance : effects.getAllEffects()) {
                    if (instance.getEffect().value().isInstantenous()) {
                        instance.getEffect().value().applyInstantenousEffect((ServerLevel) this.level(), this, this, pPlayer, instance.getAmplifier() + 2, 1.0D);
                    } else {
                        pPlayer.addEffect(new MobEffectInstance(instance.getEffect(), instance.getDuration() * 5, instance.getAmplifier(), instance.isAmbient(), instance.isVisible()));
                    }
                }

                if (!pPlayer.isCreative()) {
                    itemstack.shrink(1);
                    var remainder = itemstack.getItem().getCraftingRemainder();
                    if (remainder == null) {
                        ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.GLASS_BOTTLE));
                    } else {
                        ItemTransferUtil.giveItemToPlayer(pPlayer, remainder.create());
                    }
                }

                return InteractionResult.SUCCESS;
            }

            var effectsStew = itemstack.getOrDefault(DataComponents.SUSPICIOUS_STEW_EFFECTS, SuspiciousStewEffects.EMPTY);
            if (!effectsStew.effects().isEmpty()) {
                //Spoiler: int buff = hasCrown() ? 1 : 0;
                for (var instance : effectsStew.effects()) {
                    if (instance.effect().value().isInstantenous()) {
                        instance.effect().value().applyInstantenousEffect((ServerLevel) this.level(), this, this, pPlayer, 1 /*+ buff*/, 1.0D);
                    } else {
                        pPlayer.addEffect(new MobEffectInstance(instance.effect(), instance.duration() * (50 /*+ 25*buff*/), 0 /*buff*/, false, false));
                    }
                }
                //Double nutrition
                pPlayer.getFoodData().eat(Foods.SUSPICIOUS_STEW);
                pPlayer.getFoodData().eat(Foods.SUSPICIOUS_STEW);

                if (!pPlayer.isCreative()) {
                    itemstack.shrink(1);
                    ItemTransferUtil.giveItemToPlayer(pPlayer, new ItemStack(Items.BOWL));
                }

                return InteractionResult.SUCCESS;
            }

            //cook raw food
            var recipe = this.lastRecipe.isPresent() ? this.lastRecipe.get().value().input().test(itemstack) ? this.lastRecipe : this.getRecipe(itemstack) : this.getRecipe(itemstack);
            if (recipe.isPresent()) {
                this.lastRecipe = recipe;
                var result = recipe.get().value().assemble(new SingleRecipeInput(itemstack));

                if (pPlayer.isShiftKeyDown()) {
                    var multiResult = result.copy();
                    multiResult.setCount(result.getCount() * itemstack.getCount());

                    if (!pPlayer.isCreative()) {
                        itemstack.shrink(itemstack.getCount());
                    }
                    ItemTransferUtil.giveItemToPlayer(pPlayer, multiResult);
                } else {
                    if (!pPlayer.isCreative()) {
                        itemstack.shrink(1);
                    }
                    ItemTransferUtil.giveItemToPlayer(pPlayer, result);
                }

                for (int i = 0; i < 2; i++) {
                    Vec3 pos = this.position().add((this.getRandom().nextFloat() - 0.5f) * 0.7,
                            1.5 + (this.getRandom().nextFloat() - 0.5f) * 0.7, (this.getRandom().nextFloat() - 0.5f) * 0.7);
                    ((ServerLevel) this.level()).sendParticles(ParticleTypes.FLAME, pos.x, pos.y, pos.z, 1, 0, 0, 0, 0);
                }


                return InteractionResult.SUCCESS;
            }

            //heal with food
            if (this.isFood(itemstack) && this.getHealth() < this.getMaxHealth()) {
                FoodProperties foodProperties = itemstack.get(DataComponents.FOOD);
                this.heal(foodProperties != null ? (float) foodProperties.nutrition() : 1.0F);
                if (!pPlayer.isCreative()) {
                    itemstack.shrink(1);
                }

                this.gameEvent(GameEvent.EAT, this);
                return InteractionResult.SUCCESS;
            }

            //sit/stand
            InteractionResult interactionresult = super.mobInteract(pPlayer, pHand);
            if ((!interactionresult.consumesAction() || this.isBaby()) && itemstack.isEmpty()) {
                this.setOrderedToSit(!this.isOrderedToSit());
                this.jumping = false;
                this.navigation.stop();
                this.setTarget(null);
                return InteractionResult.SUCCESS;
            } else {
                return interactionresult;
            }
        } else if (itemstack.is(Items.DIAMOND)) {
            //tame with a diamond
            if (!pPlayer.isCreative()) {
                itemstack.shrink(1);
            }

            if (!EventHooks.onAnimalTame(this, pPlayer)) {
                this.tame(pPlayer);
                this.navigation.stop();
                this.setTarget(null);
                this.setOrderedToSit(true);
                this.level().broadcastEntityEvent(this, (byte) 7);
            } else {
                this.level().broadcastEntityEvent(this, (byte) 6);
            }

            return InteractionResult.SUCCESS;
        } else {
            return super.mobInteract(pPlayer, pHand);
        }
    }

public static void handleFunction(int uniqueKey, ItemStack stack, SlotPath path, PoseStack matrices, EntityModel<? extends LivingEntityRenderState> model, LivingEntityRenderState renderState, SubmitNodeCollector collector, int light, float partialTicks, @Nullable HumanoidArm arm, int packedLight, int packedOverlay, int color, RenderingFunction renderingFunction) {
        var client = Minecraft.getInstance();
        var level = client.level;
//        var targetEntity = reference.entity();

        var cameraState = renderState.getStateData(AccessoriesRenderStateKeys.CAMERA_STATE);

        switch (renderingFunction) {
            case RenderingFunction.Transformations transformation -> {
                TransformOps.transformStack(transformation.transformations(), matrices, model, () -> handleFunction(uniqueKey, stack, path, matrices, model, renderState, collector, light, partialTicks, arm, packedLight, packedOverlay, color, transformation.renderingFunction()));
            }
            case RenderingFunction.Block blockData -> {
                var state = blockData.state();
                var blockEntity = (blockData.type() != null) ? BlockEntity.loadStatic(BlockPos.ZERO, blockData.state(), blockData.data(), level.registryAccess()) : null;

                matrices.pushPose();

                matrices.translate(-0.5, 0, -0.5);

                // TODO: WHY THE HELL IS THE ZERO and NOT PARTIAL TICKS?
                renderBlock(client, state, blockEntity, cameraState, 0, matrices, collector, packedLight, packedOverlay, color);

                matrices.popPose();
            }
            case RenderingFunction.Entity entityData -> {
                try {
                    var currentEntityData = ENTITY_CACHE.computeIfAbsent(entityData.entityType(), entityType -> {
                        var entity = entityData.entityType().create(level, EntitySpawnReason.EVENT);

                        if (entity != null) {
                            var defaultData = Accessories.handleIoError("rendering_function_default_entity_data", scopedCollector -> {
                                var valueOutput = TagValueOutput.createWithContext(scopedCollector, level.registryAccess());

                                entity.saveWithoutId(valueOutput);

                                return valueOutput.buildResult();
                            });

                            return new EntityData(new SoftReference<>(entity), defaultData, true);
                        }

                        return new EntityData(null, new CompoundTag(), false);
                    });

                    if (!currentEntityData.wasSpawnable()) return;

                    if (!currentEntityData.canBeGotten()) {
                        currentEntityData.createNewReference(entityData.entityType(), level);
                    }

                    if (!currentEntityData.wasSpawnable()) return;

                    Entity entity = currentEntityData.reference().get();

                    if (entity == null) return;

                    boolean customData = false;

                    if (!entityData.data().isEmpty()) {
                        customData = true;

                        Accessories.handleIoError("rendering_function_entity_data", scopedCollector -> {
                            entity.load(TagValueInput.create(scopedCollector, level.registryAccess(), entityData.data()));
                        });
                    }

                    if (entityData.allowTicking() || entity instanceof Display) entity.tick();

                    var dispatcher = client.getEntityRenderDispatcher();

                    var state = dispatcher.extractEntity(entity, partialTicks);

                    dispatcher.submit(state, cameraState, 0, 0, 0, matrices, collector);

                    if (customData) {
                        currentEntityData.resetEntity(level);
                    }
                } catch (Exception ignored) {}
            }
            case RenderingFunction.Item itemData -> {
                ItemStack renderStack = itemData.stack();

                var state = new ItemStackRenderState();

                // TODO: FIND SOME WAY TO CONVERT RENDER FUNCTIONS TO A STATE OBJECT.... FUCK MY LIFE
                client.getItemModelResolver().updateForTopItem(
                    state,
                    renderStack,
                    ItemDisplayContext.GUI,
                    null,
                    null,
                    Objects.hash(itemData, uniqueKey) // TODO: CONFIRM THIS IS CORRECT
                );

                state.submit(matrices, collector, packedLight, packedOverlay, 0);
            }
            case RenderingFunction.Model modelData -> {
                var modelStack = Items.BEDROCK.getDefaultInstance();

                modelStack.set(DataComponents.ITEM_MODEL, modelData.id());

                var state = new ItemStackRenderState();

                // TODO: FIND SOME WAY TO CONVERT RENDER FUNCTIONS TO A STATE OBJECT.... FUCK MY LIFE
                client.getItemModelResolver().updateForTopItem(
                    state,
                    modelStack,
                    ItemDisplayContext.GUI,
                    null,
                    null,
                    Objects.hash(modelData, uniqueKey) // TODO: CONFIRM THIS IS CORRECT
                );
            }
            case RenderingFunction.Particle particleData -> {
                if (!PARTICLE_UPDATE_CACHE.hasAllottedTime(new ParticleTimeKey(((AccessoriesRenderStateAPI) renderState).getEntityUUIDForState(), uniqueKey, particleData), particleData.delay())) return;

                var pos = new Vector3f(0, 0, 0)
                        .mulPosition(matrices.last().pose())
                        .add(Minecraft.getInstance().gameRenderer.getMainCamera().getPosition().toVector3f());

                renderParticle(level, particleData, pos.x(), pos.y(), pos.z());
            }
            case RenderingFunction.Compound compoundFunction -> {
                if (arm != null && !compoundFunction.firstPersonArmTarget().hasArm(arm)) return;

                handleFunctions(uniqueKey, stack, path, matrices, model, renderState, collector, light, partialTicks, arm, packedLight, packedOverlay, color, compoundFunction.renderingFunctions());
            }
            case RenderingFunction.RawRenderer data -> {
                var renderFunction = CustomRendererLoader.getOrResolveRawRenderer(data, !CustomRendererLoader.isConstantResolveTarget());

                if(renderFunction == null) return;

                handleFunction(uniqueKey, stack, path, matrices, model, renderState, collector, light, partialTicks, arm, packedLight, packedOverlay, color, renderFunction);
            }
            case RenderingFunction.DeferredRenderer renderer -> {
                var renderFunction = CustomRendererLoader.getOrResolveRenderer(renderer, !CustomRendererLoader.isConstantResolveTarget());

                if(renderFunction == null) return;

                var lookup = renderState.getStateData(AccessoriesRenderStateKeys.STORAGE_LOOKUP);

                renderFunction.ifLeft(accessoryRenderer -> {
                    try {
                        // TODO: FIND SOME WAY TO CONVERT RENDER FUNCTIONS TO A STATE OBJECT.... FUCK MY LIFE
//                        if (!accessoryRenderer.shouldRender(stack, path, lookup, null, renderState, true)) return;
//
//                        accessoryRenderer.render(null, renderState, (EntityModel<LivingEntityRenderState>) model, matrices, collector);
                    } catch (Exception ignored) {}
                }).ifRight(function1 -> {
                    handleFunction(uniqueKey, stack, path, matrices, model, renderState, collector, light, partialTicks, arm, packedLight, packedOverlay, color, function1);
                });
            }
            default -> throw new IllegalStateException("Unimplemented RendererFunc: " + renderingFunction.key());
        }

    }

@Override
	public void tick() {
		super.tick();

		Level world = this.level();
		RandomSource random = this.random;
		if (this.isDeadOrDying()) {
			if (!this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT) && !this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT) && !world.isClientSide) {
				NetworkUtil.setPlayingAnimation(this, random.nextBoolean() ? EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT : EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT);
			}
			if (++this.deathTime >= 100) {
				if (!world.isClientSide) {
					ItemEntity elytra = this.spawnAtLocation(Items.ELYTRA);
					if (elytra != null) {
						elytra.setExtendedLifetime();
					}
					this.playSound(EESoundEvents.BROOD_EETLE_DEATH.get(), 2.0F, 0.9F + random.nextFloat() * 0.1F);
					this.discard();
					if (world instanceof ServerLevel serverLevel) {
						Vec3 eggSackPos = BroodEggSack.getEggPos(this.position(), this.yBodyRot, this.getEggCannonProgressServer(), this.getEggCannonFlyingProgressServer(), this.getFlyingRotations().getFlyPitch(), this.isOnLastHealthStage());
						serverLevel.sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, EEBlocks.EETLE_EGG.get().defaultBlockState()), eggSackPos.x(), eggSackPos.y() + 0.83F, eggSackPos.z(), 30, 0.3125F, 0.3125F, 0.3125F, 0.2D);
						serverLevel.sendParticles(new CorrockCrownParticleData(EEParticleTypes.END_CROWN, 180, 61, 0.0F, 0.1F, Optional.of(0.15F)), eggSackPos.x(), eggSackPos.y() + 0.83F, eggSackPos.z(), 2000, 0.3125F, 0.3125F, 0.3125F, 1.0D);
					}
				} else {
					for (int i = 0; i < 20; ++i) {
						world.addParticle(ParticleTypes.POOF, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), random.nextGaussian() * 0.02D, random.nextGaussian() * 0.02D, random.nextGaussian() * 0.02D);
					}
				}
			} else if (world.isClientSide) {
				int deathTime = this.deathTime;
				if (deathTime == 30 || deathTime == 50 || deathTime == 70) {
					Vec3[] directionals = this.dyingParticleDirectionals = new Vec3[8];
					for (int i = 0; i < 8; i++) {
						double xOffset = MathUtil.makeNegativeRandomly(random.nextDouble() * 0.5D, random);
						double yOffset = random.nextDouble() * 1.5D;
						double zOffset = MathUtil.makeNegativeRandomly(random.nextDouble() * 0.5D, random);
						directionals[i] = new Vec3(xOffset, yOffset, zOffset);
					}
				}
				if (deathTime >= 35 && deathTime <= 85 && deathTime % 2 == 0 && ((deathTime - 35) % 20 + 20) % 20 <= 10) {
					Vec3[] dyingParticleDirectionals = this.dyingParticleDirectionals;
					if (dyingParticleDirectionals != null) {
						CorrockCrownParticleData dyingParticle = new CorrockCrownParticleData(EEParticleTypes.END_CROWN, 30, 10, 1.0F, 0.05F, Optional.of(0.2F));
						Vec3 eggSackPos = BroodEggSack.getEggPos(this.position(), this.yBodyRot, this.getEggCannonProgress(), this.getEggCannonFlyingProgress(), this.getFlyingRotations().getFlyPitch(), this.isOnLastHealthStage());
						double minY = eggSackPos.y() - 0.4D;
						for (int i = 0; i < 8; i++) {
							Vec3 directional = dyingParticleDirectionals[i];
							double x = eggSackPos.x() + directional.x();
							double y = minY + directional.y();
							double z = eggSackPos.z() + directional.z();
							world.addParticle(dyingParticle, x, y, z, directional.x(), 0.5D + random.nextDouble() * 0.05D, directional.z());
						}
					}
				}
			}
		}

		if (!world.isClientSide) {
			if (this.idleDelay > 0) this.idleDelay--;
			if (this.slamCooldown > 0) this.slamCooldown--;
			if (this.eggCannonCooldown > 0) this.eggCannonCooldown--;
			if (this.flyCooldown > 0) this.flyCooldown--;
			if (this.eggDropOffCooldown > 0) this.eggDropOffCooldown--;

			if (random.nextFloat() < 0.005F && this.idleDelay <= 0 && this.onGround() && !this.isFiringCannon() && this.isNoEndimationPlaying()) {
				NetworkUtil.setPlayingAnimation(this, random.nextFloat() < 0.6F && !this.isFlying() ? EEPlayableEndimations.BROOD_EETLE_FLAP : EEPlayableEndimations.BROOD_EETLE_MUNCH);
				this.resetIdleFlapDelay();
			}

			BroodEggSack eggSackEntity = this.getEggSack(world);
			if (eggSackEntity != null && eggSackEntity.isAlive()) {
				eggSackEntity.xo = eggSackEntity.xOld = eggSackEntity.getX();
				eggSackEntity.yo = eggSackEntity.yOld = eggSackEntity.getY();
				eggSackEntity.zo = eggSackEntity.zOld = eggSackEntity.getZ();
				eggSackEntity.updatePosition(this);
			} else {
				eggSackEntity = new BroodEggSack(world);
				eggSackEntity.setBroodID(this.getId());
				eggSackEntity.updatePosition(this);
				world.addFreshEntity(eggSackEntity);
				this.setEggSackID(eggSackEntity.getId());
			}

			if (this.isFlying()) {
				this.ticksFlying++;

				if (this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_AIR_SLAM) && this.getAnimationTick() == 5 && (this.onGround() || !this.level().noCollision(DetectionHelper.checkOnGround(this.getBoundingBox(), 0.25F)))) {
					BroodEetleSlamGoal.slam(this, random, 1.0F);
				}
			} else {
				this.ticksFlying = 0;
			}

			if (this.level().getGameTime() % 5 == 0) {
				BlockPos takeoffPos = this.takeoffPos;
				if (takeoffPos != null && this.position().distanceToSqr(Vec3.atLowerCornerOf(takeoffPos)) > 256.0F) {
					this.takeoffPos = null;
				}
			}

			float percentage = this.getHealth() / this.getMaxHealth();
			this.bossInfo.setProgress(percentage);
			if (percentage != this.prevHealthPercentage) {
				HealthStage newStage = HealthStage.getStage(percentage);
				if (newStage.eggGrowthChance > 0.0F && newStage.ordinal() > this.getHealthStage().ordinal()) {
					newStage.awakeNearbyEggs(this);
				}
				this.setHealthStage(newStage);
			}
			this.prevHealthPercentage = percentage;
		} else {
			TimedEndimation takeoff = this.takeoffEndimation;
			takeoff.tick();
			if (takeoff.isMaxed()) {
				this.takeoffMoving = true;
				takeoff.setDecrementing(true);
			} else {
				if (this.takeoffMoving) {
					this.takeoffMoving = takeoff.getTick() > 15;
				} else {
					takeoff.setDecrementing(!this.isFlying());
				}
			}

			this.wingFlapSpeed += this.isMoving() ? (0.5F - this.wingFlapSpeed) * 0.1F : (0.125F - this.wingFlapSpeed) * 0.2F;
			this.prevWingFlap = this.wingFlap;
			this.wingFlap += this.wingFlapSpeed;
		}

		TimedEndimation eggCannonEndimation = this.eggCannonEndimation;
		eggCannonEndimation.setDecrementing(!this.isFiringCannon() && !((this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_LEFT) || this.isEndimationPlaying(EEPlayableEndimations.BROOD_EETLE_DEATH_RIGHT)) && this.getAnimationTick() >= 15));
		eggCannonEndimation.tick();

		TimedEndimation eggMouthEndimation = this.eggMouthEndimation;
		eggMouthEndimation.setDecrementing(!eggCannonEndimation.isMaxed() && this.isNotDroppingEggs());
		eggMouthEndimation.tick();

		TimedEndimation eggCannonFlyingEndimation = this.eggCannonFlyingEndimation;
		eggCannonFlyingEndimation.setDecrementing(!this.isFlying());
		eggCannonFlyingEndimation.tick();

		TimedEndimation flying = this.flyingEndimation;
		flying.setDecrementing(!this.isMoving());
		flying.tick();

		TimedEndimation sleepingEndimation = this.sleepingEndimation;
		sleepingEndimation.setDecrementing(!this.isSleeping());
		sleepingEndimation.tick();

		TimedEndimation healPulseEndimation = this.healPulseEndimation;
		if (healPulseEndimation.isMaxed()) {
			healPulseEndimation.setDecrementing(true);
		}
		healPulseEndimation.tick();

		this.flyingRotations.tick(this.getTargetFlyingRotations());
	}

@SubscribeEvent(priority = EventPriority.LOWEST)
	public void onLivingDropsLowest(LivingDropsEvent event) {
		Level level = event.getEntity().level();

		/*
		 * Eldritch Pan cooking logic.
		 */

        if (event.getSource().getDirectEntity() instanceof ServerPlayer player)
            if (SuperpositionHandler.isTheWorthyOne(player))
                if (player.getMainHandItem().is(EnigmaticItems.ELDRITCH_PAN)
                        || player.getOffhandItem().is(EnigmaticItems.ELDRITCH_PAN))
                    for (ItemEntity drop : new ArrayList<>(event.getDrops())) {
                        ItemStack stack = drop.getItem();
                        Optional<SmeltingRecipe> optional = level.getRecipeManager().getRecipeFor(
                                RecipeType.SMELTING, new SimpleContainer(stack), level);

                        optional.ifPresent(recipe -> {
                            ItemStack result = recipe.getResultItem(level.registryAccess());

                            if (!result.isEmpty()) {
                                ItemStack cooked = result.copyWithCount(stack.getCount() * result.getCount());

                                event.getDrops().remove(drop);
                                this.addDrop(event, cooked);
                            }
                        });
                    }

		/*
		 * Escape Scroll logic.
		 */

		if (event.getEntity() instanceof ServerPlayer player) {
			CompoundTag deathLocation = new CompoundTag();
			deathLocation.putDouble("x", player.getX());
			deathLocation.putDouble("y", player.getY());
			deathLocation.putDouble("z", player.getZ());
			deathLocation.putString("dimension", player.level().dimension().location().toString());

			SuperpositionHandler.setPersistentTag(player, "LastDeathLocation", deathLocation);

			boolean droppedCrystal = false;
			boolean hadEscapeScroll = this.hadEscapeScroll(player);

			DimensionalPosition dimPoint = hadEscapeScroll ? SuperpositionHandler.getRespawnPoint(player) : new DimensionalPosition(player.getX(), player.getY(), player.getZ(), player.level());

			if (hadEscapeScroll) {
				BlockPos respawnPos = player.getRespawnPosition();
				ServerLevel respawnLevel = ServerLifecycleHooks.getCurrentServer().getLevel(player.getRespawnDimension());
				boolean isEndAnchor = false;

				if (respawnLevel.getBlockState(respawnPos).is(EnigmaticBlocks.END_ANCHOR)) {
					dimPoint = new DimensionalPosition(respawnPos.getX() + 0.5, respawnPos.getY() + 1.5,
							respawnPos.getZ() + 0.5, respawnLevel);
					isEndAnchor = true;
				}

				player.level().playSound(null, player.blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 128, player.level().dimension())), new PacketPortalParticles(player.getX(), player.getY() + (player.getBbHeight() / 2), player.getZ(), 100, 1.25F, false));

				for (ItemEntity dropIt : event.getDrops()) {
					ItemEntity alternativeDrop = new ItemEntity(dimPoint.world, dimPoint.posX, dimPoint.posY, dimPoint.posZ, dropIt.getItem());
					alternativeDrop.teleportTo(dimPoint.posX, dimPoint.posY, dimPoint.posZ);

					if (!isEndAnchor) {
						alternativeDrop.setDeltaMovement(THEY_SEE_ME_ROLLIN.nextDouble()-0.5, THEY_SEE_ME_ROLLIN.nextDouble()-0.5, THEY_SEE_ME_ROLLIN.nextDouble()-0.5);
					} else {
						alternativeDrop.setDeltaMovement(0, 0, 0);
					}

					dimPoint.world.addFreshEntity(alternativeDrop);
					dropIt.setItem(ItemStack.EMPTY);
				}

				event.getDrops().clear();

				final DimensionalPosition dimPointFinal = dimPoint;

				dimPoint.world.playSound(null, BlockPos.containing(dimPoint.posX, dimPoint.posY, dimPoint.posZ), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
				EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(dimPointFinal.posX, dimPointFinal.posY, dimPointFinal.posZ, 128, dimPointFinal.world.dimension())), new PacketRecallParticles(dimPoint.posX, dimPoint.posY, dimPoint.posZ, 48, false));
			}

			if (this.hadEnigmaticAmulet(player) && !event.getDrops().isEmpty() && EnigmaticItems.ENIGMATIC_AMULET.isVesselEnabled()) {
				ItemStack soulCrystal = SuperpositionHandler.canDropSoulCrystal(player, this.hadCursedRing(player)) ? EnigmaticItems.SOUL_CRYSTAL.createCrystalFrom(player) : null;
				ItemStack storageCrystal = EnigmaticItems.STORAGE_CRYSTAL.storeDropsOnCrystal(event.getDrops(), player, soulCrystal);
				PermanentItemEntity droppedStorageCrystal = new PermanentItemEntity(dimPoint.world, dimPoint.getPosX(), dimPoint.getPosY() + 1.5, dimPoint.getPosZ(), storageCrystal);
				droppedStorageCrystal.setOwnerId(player.getUUID());
				dimPoint.world.addFreshEntity(droppedStorageCrystal);
				EnigmaticLegacy.LOGGER.info("Summoned Extradimensional Storage Crystal for " + player.getGameProfile().getName() + " at X: " + dimPoint.getPosX() + ", Y: " + dimPoint.getPosY() + ", Z: " + dimPoint.getPosZ());
				event.getDrops().clear();

				if (soulCrystal != null) {
					droppedCrystal = true;
				}

				SoulArchive.getInstance().addItem(droppedStorageCrystal);
			} else if (SuperpositionHandler.canDropSoulCrystal(player, this.hadCursedRing(player))) {
				ItemStack soulCrystal = EnigmaticItems.SOUL_CRYSTAL.createCrystalFrom(player);
				PermanentItemEntity droppedSoulCrystal = new PermanentItemEntity(dimPoint.world, dimPoint.getPosX(), dimPoint.getPosY() + 1.5, dimPoint.getPosZ(), soulCrystal);
				droppedSoulCrystal.setOwnerId(player.getUUID());
				dimPoint.world.addFreshEntity(droppedSoulCrystal);
				EnigmaticLegacy.LOGGER.info("Teared Soul Crystal from " + player.getGameProfile().getName() + " at X: " + dimPoint.getPosX() + ", Y: " + dimPoint.getPosY() + ", Z: " + dimPoint.getPosZ());

				droppedCrystal = true;
				SoulArchive.getInstance().addItem(droppedSoulCrystal);
			}

			if (SuperpositionHandler.isPermanentlyDead(player)) {
				EnigmaticLegacy.packetInstance.send(PacketDistributor.PLAYER.with(() -> player),
						new PacketPermadeath());
				SuperpositionHandler.setCurrentWorldFractured(true);
			}

			ResourceLocation soulLossAdvancement = new ResourceLocation(EnigmaticLegacy.MODID, "book/soul_loss");

			if (SuperpositionHandler.isAffectedBySoulLoss(player, this.hadCursedRing(player))) {
				SuperpositionHandler.grantAdvancement(player, soulLossAdvancement);
			} else if (SuperpositionHandler.hasAdvancement(player, soulLossAdvancement)) {
				SuperpositionHandler.revokeAdvancement(player, soulLossAdvancement);
			}

			POSTMORTAL_POSESSIONS.removeAll(player);
			return;
		} else if (event.getEntity() instanceof Player) {
			POSTMORTAL_POSESSIONS.removeAll(event.getEntity());
		}

		/*
		 * Ender Slayer XP conversion.
		 */

		if (event.isRecentlyHit() && event.getSource() != null && event.getSource().getEntity() instanceof Player && SuperpositionHandler.isTheCursedOne((Player) event.getSource().getEntity())) {
			Player player = (Player) event.getSource().getEntity();
			LivingEntity killed = event.getEntity();

			if (killed instanceof EnderMan && killed.level().dimension().equals(PROXY.getEndKey())
					&& killed.getPersistentData().getBoolean("EnderSlayerVictim")) {
				int extraXP = 0;

				for (ItemEntity entity : event.getDrops()) {
					if (entity.getItem() != null) {
						if (entity.getItem().is(Items.ENDER_PEARL)) {
							this.dropXPOrb(killed.level(), killed.getX(), killed.getY(), killed.getZ(), 10);
							//extraXP += 10;
						} else if (entity.getItem().is(Items.ENDER_EYE)) {
							this.dropXPOrb(killed.level(), killed.getX(), killed.getY(), killed.getZ(), 20);
							//extraXP += 20;
						}
					}
				}

				//killed.getPersistentData().remove("EnderSlayerVictim");
				//killed.getPersistentData().putInt("EnderSlayerExtraXP", extraXP);
				event.getDrops().clear();
				event.setCanceled(true);
			}
		}
	}

private void unregisterScheduledDimensions(final MinecraftServer server)
    {
        if (this.levelsPendingUnregistration.isEmpty())
            return;

        // flush the buffer
        final Map<ResourceKey<Level>, UnregistrationTicket> keysToRemove = this.levelsPendingUnregistration.stream().collect(Collectors.toMap(UnregistrationTicket::levelKey, x -> x));
        this.levelsPendingUnregistration = new HashSet<>();

        // we need to remove the dimension/level from three places:
        // the server's dimension/levelstem registry, the server's level registry, and
        // the overworld's border listener
        // the level registry is just a simple map and the border listener has a remove() method
        // the dimension registry has five sub-collections that need to be cleaned up
        // we should also eject players from removed worlds so they don't get stuck there

        WorldGenSettings worldGenSettings = server.getWorldGenSettings();
        //noinspection unchecked
        worldGenSettings.vampirism$removeDimension(keysToRemove.keySet().toArray(ResourceKey[]::new));

        final Registry<LevelStem> oldRegistry = server.registryAccess().lookupOrThrow(Registries.LEVEL_STEM);
        if (!(oldRegistry instanceof MappedRegistry<LevelStem> oldMappedRegistry))
        {
            LOGGER.warn("Cannot unload dimensions: dimension registry not an instance of MappedRegistry. There may be another mod causing incompatibility with Infiniverse, or Infiniverse may need to be updated for your version of forge/minecraft.");
            return;
        }
        LayeredRegistryAccess<RegistryLayer> layeredRegistryAccess = server.vampirism$registryAccess();
        RegistryAccess.Frozen composite = layeredRegistryAccess.compositeAccess();
        if (!(composite instanceof ImmutableRegistryAccess immutableRegistryAccess))
        {
            LOGGER.warn("Cannot unload dimensions: composite registry not an instance of ImmutableRegistryAccess. There may be another mod causing incompatibility with Infiniverse, or Infiniverse may be updated for your version of forge/minecraft.");
            return;
        }

        final Set<ResourceKey<Level>> removedLevelKeys = new HashSet<>();
        @NotNull
        final ServerLevel overworld = Objects.requireNonNull(server.getLevel(Level.OVERWORLD));

        for (final ResourceKey<Level> levelKeyToRemove : keysToRemove.keySet())
        {
            final @Nullable ServerLevel levelToRemove = server.getLevel(levelKeyToRemove);
            if (levelToRemove == null)
                continue;

            DimensionRemoveEvent unregisterDimensionEvent = new DimensionRemoveEvent(levelToRemove);
            NeoForge.EVENT_BUS.post(unregisterDimensionEvent);
            if (unregisterDimensionEvent.isCanceled())
                continue;

            // null if specified level not present
            @SuppressWarnings("deprecation")
            final @Nullable ServerLevel removedLevel = server.forgeGetWorldMap().remove(levelKeyToRemove);

            if (removedLevel != null) // if we removed the key from the map
            {
                // eject players from dead world
                // iterate over a copy as the world will remove players from the original list
                for (final ServerPlayer player : Lists.newArrayList(removedLevel.players()))
                {
                    // send players to their respawn point
                    @Nullable ServerPlayer.RespawnConfig respawnConfig = player.getRespawnConfig();
                    LevelData.RespawnData respawnData = respawnConfig == null ? server.getRespawnData() : respawnConfig.respawnData();
                    ResourceKey<Level> respawnKey = respawnData.dimension();
                    BlockPos destinationPos = respawnData.pos();
                    // if we're removing their respawn world then just send them to the overworld
                    if (keysToRemove.containsKey(respawnKey))
                    {
                        respawnKey = Level.OVERWORLD;
                        // make sure to wipe the player's respawn point if it was set here
                        if (respawnConfig != null && respawnConfig.respawnData().dimension() == respawnKey)
                        {
                            player.setRespawnPosition(null, false);
                        }
                    }

                    ServerLevel destinationLevel = server.getLevel(respawnKey);
                    if (destinationLevel == null)
                    {
                        destinationLevel = overworld;
                    }

                    // "respawning" the player via the player list schedules a task in the server to
                    // run after the post-server tick
                    // that causes some minor logspam due to the player's world no longer being
                    // loaded
                    // teleporting the player via a teleport avoids this
                    player.teleportTo(destinationLevel, destinationPos.getX(), destinationPos.getY(), destinationPos.getZ(), Set.of(), respawnData.pitch(), respawnData.yaw(), false);
                }
                // save the world now or it won't be saved later and data that may be wanted to
                // be kept may be lost
                removedLevel.save(null, false, removedLevel.noSave());

                // fire world unload event -- when the server stops, this would fire after
                // worlds get saved, we'll do that here too
                NeoForge.EVENT_BUS.post(new LevelEvent.Unload(removedLevel));

                // track the removed level
                removedLevelKeys.add(levelKeyToRemove);
            }
        }

        if (!removedLevelKeys.isEmpty())
        {
            // replace the old dimension registry with a new one containing the dimensions
            // that weren't removed, in the same order
            final MappedRegistry<LevelStem> newRegistry = new MappedRegistry<>(Registries.LEVEL_STEM, oldMappedRegistry.registryLifecycle());

            for (final var entry : oldRegistry.entrySet())
            {
                final ResourceKey<LevelStem> oldKey = entry.getKey();
                final ResourceKey<Level> oldLevelKey = ResourceKey.create(Registries.DIMENSION, oldKey.identifier());
                final LevelStem dimension = entry.getValue();
                if (dimension != null && removedLevelKeys.stream().noneMatch(x -> x == oldLevelKey))
                {
                    newRegistry.register(oldKey, dimension, oldRegistry.registrationInfo(oldKey).orElse(DIMENSION_REGISTRATION_INFO));
                }
            }

            // then replace the old registry with the new registry
            // as of 1.20.1 the dimension registry is stored in the server's layered registryaccess
            // this has several immutable collections of sub-registryaccesses,
            // so we'll need to recreate each of them.

            // Each ServerLevel has a reference to the layered registry access's *composite* registry access
            // so we should edit the internal fields where possible (instead of reconstructing the registry accesses)

            List<RegistryAccess.Frozen> newRegistryAccessList = new ArrayList<>();
            for (RegistryLayer layer : RegistryLayer.values())
            {
                if (layer == RegistryLayer.DIMENSIONS)
                {
                    newRegistryAccessList.add(new ImmutableRegistryAccess(List.of(newRegistry)).freeze());
                }
                else
                {
                    newRegistryAccessList.add(layeredRegistryAccess.getLayer(layer));
                }
            }
            Map<ResourceKey<? extends Registry<?>>, Registry<?>> newRegistryMap = new HashMap<>();
            for (var registryAccess : newRegistryAccessList)
            {
                var registries = registryAccess.registries().toList();
                for (var registryEntry : registries)
                {
                    newRegistryMap.put(registryEntry.key(), registryEntry.value());
                }
            }
            layeredRegistryAccess.vampirism$setValues(List.copyOf(newRegistryAccessList));
            immutableRegistryAccess.vampirism$setRegistries(newRegistryMap);

            // update the server's levels so dead levels don't get ticked
            server.markWorldsDirty();

            // notify client of the removed levels
            server.getPlayerList().broadcastAll(new ClientboundUpdateDimensionsPacket(removedLevelKeys.stream().collect(Collectors.toUnmodifiableSet()), false));
        }

        for (ResourceKey<Level> key : removedLevelKeys) {
            var ticket = keysToRemove.get(key);
            if (ticket.deleteDataFromDisk()) {
                deletePersistentData(server, ticket.levelKey());
            }
        }
    }

public InteractionResult mobInteract(Player pPlayer, InteractionHand pHand) {
        ItemStack itemstack = pPlayer.getItemInHand(pHand);
        if (this.getTrueOwner() != null && pPlayer == this.getTrueOwner()) {
            ItemStack leaderBanner = this.getLeaderBannerInstance();
            if (pHand == InteractionHand.MAIN_HAND
                    && this.canBeLeader()
                    && !leaderBanner.isEmpty()
                    && ItemHelper.sameBanner(itemstack, leaderBanner)
                    && !ItemHelper.sameBanner(this.getItemBySlot(EquipmentSlot.HEAD), leaderBanner)) {
                ItemStack helmet = this.getItemBySlot(EquipmentSlot.HEAD);
                this.playSound(SoundEvents.ARMOR_EQUIP_GENERIC, 1.0F, 1.0F);
                this.playSound(this.getCelebrateSound(), 1.0F, this.getVoicePitch());
                this.dropEquipment(EquipmentSlot.HEAD, helmet);
                this.setItemSlot(EquipmentSlot.HEAD, this.getLeaderBannerWithNameInstance());
                this.setGuaranteedDrop(EquipmentSlot.HEAD);
                if (!pPlayer.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }
                for (int i = 0; i < 7; ++i) {
                    double d0 = this.random.nextGaussian() * 0.02D;
                    double d1 = this.random.nextGaussian() * 0.02D;
                    double d2 = this.random.nextGaussian() * 0.02D;
                    this.level.addParticle(ParticleTypes.HAPPY_VILLAGER, this.getRandomX(1.0D), this.getRandomY() + 0.5D, this.getRandomZ(1.0D), d0, d1, d2);
                }
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().getItem() instanceof TaglockKit
                    && TaglockKit.hasEntity(pPlayer.getMainHandItem())
                    && !MobUtil.areAllies(pPlayer, TaglockKit.getEntity(pPlayer.getMainHandItem()))
                    && this.isLeader()){
                this.setMarked(TaglockKit.getEntity(pPlayer.getMainHandItem()));
                this.setTarget(this.getMarked());
                if (!pPlayer.getAbilities().instabuild) {
                    TaglockKit.removeEntity(pPlayer.getMainHandItem());
                }
                if (!this.level.isClientSide) {
                    if (this.getMarked() instanceof ServerPlayer player) {
                        if (CuriosFinder.hasCurio(player, ModItems.ALARMING_CHARM.get())) {
                            player.displayClientMessage(Component.translatable("info.goety.summon.hunt").withStyle(ChatFormatting.RED), true);
                            ModNetwork.sendToClient(player, new SPlayPlayerSoundPacket(SoundEvents.RAID_HORN.get(), 64.0F, 1.0F));
                        }
                    }
                }

                if (this.isStaying()){
                    this.setStaying(false);
                }
                if (this.isGuardingArea()){
                    this.setBoundPos(null);
                }
                for (RaiderServant servant : this.getNearbyCompanions()) {
                    servant.setMarked(this.getMarked());
                    servant.setTarget(this.getMarked());
                    if (servant.getLeader() == null){
                        servant.setLeader(this);
                        servant.setFollowing();
                    }
                    if (MobUtil.sameDimension(servant, this.getMarked())) {
                        servant.teleportTowards(this.getMarked());
                    }
                }
                if (MobUtil.sameDimension(this, this.getMarked())) {
                    this.teleportTowards(this.getMarked());
                }
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().is(ModItems.WAYSTONE.get())
                    && WaystoneItem.hasBlock(pPlayer.getMainHandItem())
                    && WaystoneItem.isSameDimension(this, pPlayer.getMainHandItem())
                    && (pPlayer.getOffhandItem().is(Items.GOAT_HORN) || pPlayer.getOffhandItem().is(ModItems.RAIDING_HORN.get()))
                    && !SEHelper.getFocusCoolDown(pPlayer).isOnCooldown(ModItems.WAYSTONE.get())
                    && this.isLeader()){
                if (this.level instanceof ServerLevel serverLevel) {
                    GlobalPos globalPos = WaystoneItem.getPosition(pPlayer.getMainHandItem());
                    if (globalPos != null){
                        BlockPos blockPos = globalPos.pos();
                        if (!serverLevel.isLoaded(blockPos)){
                            pPlayer.displayClientMessage(Component.translatable("info.goety.waystone.unloaded"), true);
                            return InteractionResult.FAIL;
                        }
                        if (serverLevel.isVillage(blockPos)){
                            if (this.isAllyWithType(EntityType.VILLAGER)) {
                                return InteractionResult.FAIL;
                            }
                            this.setRaidPos(blockPos);
                            this.setRaidDim(serverLevel.dimension());
                            if (this.isStaying()){
                                this.setStaying(false);
                            }
                            if (this.isGuardingArea()){
                                this.setBoundPos(null);
                            }
                            boolean flag = this.position().distanceToSqr(blockPos.getCenter()) <= Mth.square(32);
                            if (!flag) {
                                int k = 0;
                                BlockPos blockPos1 = this.findRandomSpawnPos(k, 20);
                                if (blockPos1 != null) {
                                    for (RaiderServant servant : this.getNearbyCompanions()) {
                                        servant.setRaidPos(blockPos);
                                        servant.setRaidDim(serverLevel.dimension());
                                        if (servant.getLeader() == null) {
                                            servant.setLeader(this);
                                            servant.setFollowing();
                                        }
                                        servant.moveTo(blockPos1, 0.0F, 0.0F);
                                    }
                                    this.moveTo(blockPos1, 0.0F, 0.0F);
                                    flag = true;
                                } else {
                                    ++k;
                                }
                            }
                            if (flag) {
                                long j = serverLevel.getRandom().nextLong();
                                for(ServerPlayer serverplayer : serverLevel.players()) {
                                    Vec3 vec3 = serverplayer.position();
                                    Vec3 vec31 = this.position();
                                    double d0 = Math.sqrt((vec31.x - vec3.x) * (vec31.x - vec3.x) + (vec31.z - vec3.z) * (vec31.z - vec3.z));
                                    double d1 = vec3.x + 13.0D / d0 * (vec31.x - vec3.x);
                                    double d2 = vec3.z + 13.0D / d0 * (vec31.z - vec3.z);
                                    if (d0 <= 64.0D) {
                                        serverplayer.connection.send(new ClientboundSoundPacket(SoundEvents.RAID_HORN, SoundSource.NEUTRAL, d1, serverplayer.getY(), d2, 64.0F, 1.0F, j));
                                    }
                                }
                                if (this.getTrueOwner() instanceof Player player) {
                                    SEHelper.addCooldown(player, ModItems.WAYSTONE.get(), 300);
                                }
                                return InteractionResult.SUCCESS;
                            }
                        }
                    }
                }
                return InteractionResult.CONSUME;
            } else if (pPlayer.getMainHandItem().is(ModItems.OMINOUS_SHACKLES.get())
                    && !this.isCapturing()
                    && !this.isFollower()){
                if (!this.level.isClientSide) {
                    this.setCaptureMode(true);
                    this.playSound(SoundEvents.CHAIN_PLACE, 1.0F, 1.0F);
                }

                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().is(Tags.Items.SHEARS)
                    && this.isCapturing()
                    && !this.isFollower()){
                if (!this.level.isClientSide) {
                    this.setCaptureMode(false);
                    this.playSound(SoundEvents.CHAIN_BREAK, 1.0F, 0.5F);
                }

                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().isEmpty() && this.isLeader() && !this.getBindPrisoners().isEmpty()){
                for (Prisoner prisoner : this.getBindPrisoners()) {
                    prisoner.setLeader(this);
                }
                this.playSound(SoundEvents.CHAIN_PLACE, 1.0F, 1.0F);
                return InteractionResult.SUCCESS;
            } else if (pPlayer.getMainHandItem().isEmpty() && this.getItemBySlot(EquipmentSlot.HEAD).getItem() instanceof BannerItem){
                ItemStack helmet = this.getItemBySlot(EquipmentSlot.HEAD);
                this.setItemSlot(EquipmentSlot.HEAD, ItemStack.EMPTY);
                this.dropEquipment(EquipmentSlot.HEAD, helmet);
                return InteractionResult.SUCCESS;
            } else if (this.canLinkToIdol()) {
                return this.linkToIdol(pPlayer, pHand);
            }
        }
        return super.mobInteract(pPlayer, pHand);
    }

@SubscribeEvent
  public void onRenderWorldLast(RenderLevelStageEvent event) {
    if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_ENTITIES) { // was AFTER_SOLID_BLOCKS / AFTER_TRANSLUCENT_BLOCKS / AFTER_PARTICLES - testing the very last stage
      return; //send it
    }
    Minecraft mc = Minecraft.getInstance();
    Player player = mc.player;
    if (player == null) {
      return;
    }
    Level world = player.level();
    ItemStack stack = ItemStack.EMPTY;
    List<BlockPos> putBoxHere = new ArrayList<>();
    /****************** rendering outline ********************/
    stack = OreProspector.getIfHeld(player);
    if (stack.getItem() instanceof OreProspector) {
      List<BlockPosDim> coords = OreProspector.getPosition(stack);
      for (BlockPosDim loc : coords) {
        if (loc != null) {
          if (loc.getDimension() == null ||
              loc.getDimension().equalsIgnoreCase(LevelWorldUtil.dimensionToString(world))) {
            RenderBlockUtils.createBox(event.getPoseStack(), loc.getPos());
            putBoxHere.add(loc.getPos());
          }
        }
      }
    }
    /****************** end rendering outline,. start cubes ********************/
    double range = 6F;
    float alpha = 1; //0.125F * 2;
    Map<BlockPos, Color> renderCubes = new HashMap<>();
    ///////////////////// BuilderItem
    stack = BuilderItem.getIfHeld(player);
    if (stack.getItem() instanceof BuilderItem) {
      BlockHitResult lookingAt = (BlockHitResult) player.pick(range, 0F, false);
      if (!world.isEmptyBlock(lookingAt.getBlockPos())) {
        BlockPos pos = lookingAt.getBlockPos();
        BuildStyle buildStyle = ((BuilderItem) stack.getItem()).style;
        if (buildStyle.isOffset() && lookingAt.getDirection() != null) {
          pos = pos.relative(lookingAt.getDirection());
        }
        alpha = .01f;
        //now the item has a build area
        List<BlockPos> coordinates = PacketSwapBlock.getSelectedBlocks(world, pos, BuilderItem.getActionType(stack), lookingAt.getDirection(), buildStyle);
        for (BlockPos coordinate : coordinates) {
          putBoxHere.add(coordinate);
        }
      }
    }
    ///////////////////// RandomizerItem
    stack = RandomizerItem.getIfHeld(player);
    if (stack.getItem() instanceof RandomizerItem) {
      BlockHitResult lookingAt = RenderBlockUtils.getLookingAt(player, (int) range);
      if (world.getBlockState(lookingAt.getBlockPos()).isAir()) {
        return;
      }
      List<BlockPos> coords = RandomizerItem.getPlaces(lookingAt.getBlockPos(), lookingAt.getDirection(), stack);
      for (BlockPos e : coords) {
        BlockState stHere = world.getBlockState(e);
        if (!RandomizerItem.canMove(stHere, world, e) && !stHere.isAir()) {
          renderCubes.put(e, Color.RED);
        }
        else if (!stHere.isAir()) {
          putBoxHere.add(e);
        }
      }
    }
    stack = player.getMainHandItem();

    ///////////////////// LocationGpsItem
    if (stack.getItem() instanceof LocationGpsCard) {
      BlockPosDim loc = LocationGpsCard.getPosition(stack);
      if (loc != null) {
        if (loc.getDimension() == null ||
            loc.getDimension().equalsIgnoreCase(LevelWorldUtil.dimensionToString(world))) {
          renderCubes.put(loc.getPos(), ClientConfigCyclic.getColor(stack));
        }
      }
    }
    ///////////////////////////////////////ShapeCard
    if (stack.getItem() instanceof ShapeCard) {
      RelativeShape shape = RelativeShape.read(stack);
      if (shape != null) {
        BlockPos here = player.blockPosition();
        for (BlockPos s : shape.getShape()) {
          putBoxHere.add(here.offset(s));
        }
      }
    }
    //the block edge outline
    for (BlockPos coordinate : putBoxHere) {
      RenderBlockUtils.createBox(event.getPoseStack(), coordinate);
    }
    //render the pos->colour map 
    if (renderCubes.keySet().size() > 0) {
      float scale = 1;
      PoseStack matrix = event.getPoseStack();
      Vec3 view = Minecraft.getInstance().gameRenderer.getMainCamera().getPosition();
      RenderBlockUtils.renderColourCubes(matrix, view, renderCubes, scale, alpha);
    }
    /****************** end rendering cubes. start laser beam render ********************/
    stack = LaserItem.getIfHeld(player);
    if (!stack.isEmpty() && player.isUsingItem()) {
      IEnergyStorage storage = CapabilityUtil.energy(stack);
      if (storage == null || storage.getEnergyStored() < ConfigRegistry.LaserItemEnergy.get()) {
        return;
      }
      // RayTraceResult  became HitResult
      // objectMouseOver became hitResult
      java.awt.Color laserColor;
      try {
        laserColor = java.awt.Color.decode(ClientConfigCyclic.LASER_COLOR.get());
      }
      catch (Exception e) {
        laserColor = new java.awt.Color(100, 0, 2);
      }
      float lr = laserColor.getRed() / 255f;
      float lg = laserColor.getGreen() / 255f;
      float lb = laserColor.getBlue() / 255f;
      if (mc.crosshairPickEntity != null) {
        //Render and Shoot. closerange version
        RenderEntityToBlockLaser.renderLaser(event, player, mc.getTimer().getGameTimeDeltaPartialTick(false), stack, InteractionHand.MAIN_HAND, 18, -0.02F, lr, lg, lb);
        if (world.getGameTime() % 4 == 0) {
          PacketDistributor.sendToServer(new PacketEntityLaser(mc.crosshairPickEntity.getId(), true));
          SoundUtil.playSound(player, SoundRegistry.LASERBEANPEW.get(), 0.2F);
        }
      }
      else {
        //out of range- do custom raytrace for longrange version
        final int laserRange = ConfigRegistry.LaserItemRange.get();
        double laserGamemodeRange = laserRange;// mc.gameMode.getPickRange() * LaserItem.RANGE_FACTOR;
        Entity camera = mc.getCameraEntity();
        Vec3 cameraViewVector = camera.getViewVector(1.0F);
        Vec3 cameraEyePosition = camera.getEyePosition(1.0F);
        Vec3 cameraEyeViewRay = cameraEyePosition.add(cameraViewVector.x * laserGamemodeRange, cameraViewVector.y * laserGamemodeRange, cameraViewVector.z * laserGamemodeRange);
        AABB aabb = camera.getBoundingBox().expandTowards(cameraViewVector.scale(laserGamemodeRange)).inflate(1.0D, 1.0D, 1.0D);
        //
        //
        EntityHitResult ehr = ProjectileUtil.getEntityHitResult(camera, cameraEyePosition, cameraEyeViewRay, aabb, (ent) -> {
          return ent.isAttackable() && ent.isAlive();
        }, 0);
        if (ehr != null) {
          Vec3 entityHitResultLocation = ehr.getLocation();
          double distance = Math.sqrt(cameraEyePosition.distanceToSqr(entityHitResultLocation));
          if (distance < laserRange) {
            //first vector is FROM, second is TO
            BlockHitResult miss = mc.level.clip(new ClipContext(cameraEyePosition, entityHitResultLocation, ClipContext.Block.VISUAL, ClipContext.Fluid.NONE, mc.player));
            if (miss.getType() != HitResult.Type.BLOCK) {
              //  dont shoot thru walls
              RenderEntityToBlockLaser.renderLaser(event, player, mc.getTimer().getGameTimeDeltaPartialTick(false), stack, InteractionHand.MAIN_HAND, lr, lg, lb);
              if (world.getGameTime() % 4 == 0) {
                PacketDistributor.sendToServer(new PacketEntityLaser(ehr.getEntity().getId(), false));
                SoundUtil.playSound(player, SoundRegistry.LASERBEANPEW.get(), 0.2F);
              }
            }
          }
        }
        else {
          //we missed. Do we render on a miss?
          if (ConfigRegistry.LaserRenderMisses.get()) {
            RenderEntityToBlockLaser.renderLaser(event, player, mc.getTimer().getGameTimeDeltaPartialTick(false), stack, InteractionHand.MAIN_HAND, lr, lg, lb);
          }
          else { //if we dont render the miss, show a message for better user experience
            ChatUtil.sendStatusMessage(player, "item.cyclic.laser_cannon.notarget");
          }
        }
      }
    }
  }

@Override
	public void tick() {
		if (isAlive()) {
			lastActiveTime = timeSinceIgnited;

			if (hasIgnited())
				setCreeperState(1);

			int creeperState = getCreeperState();

			if (creeperState > 0 && timeSinceIgnited == 0)
				playSound(SoundEvents.CREEPER_PRIMED, 1.0F, 0.5F);

			timeSinceIgnited += creeperState;

			if (timeSinceIgnited < 0)
				timeSinceIgnited = 0;

			if (timeSinceIgnited >= fuseTime) {
				timeSinceIgnited = fuseTime;

				explode();
			}
		}

		if (!net.minecraftforge.common.ForgeHooks.onLivingUpdate(this)) {
			if (!level.isClientSide)
				setSharedFlag(6, isGlowing());

			baseTick();

			lastSwimAnimation = swimAnimation;

			if (isVisuallySwimming()) {
				swimAnimation = Math.min(1.0F, swimAnimation + 0.09F);
			}
			else {
				swimAnimation = Math.max(0.0F, swimAnimation - 0.09F);
			}

			if (!level.isClientSide) {
				int arrowCount = getArrowCount();

				if (arrowCount > 0) {
					if (removeArrowTime <= 0)
						removeArrowTime = 20 * (30 - arrowCount);

					--removeArrowTime;

					if (removeArrowTime <= 0)
						setArrowCount(arrowCount - 1);
				}

				int beeStings = getStingerCount();

				if (beeStings > 0) {
					if (removeStingerTime <= 0)
						removeStingerTime = 20 * (30 - beeStings);

					--removeStingerTime;

					if (removeStingerTime <= 0)
						setStingerCount(beeStings - 1);
				}

				if (tickCount % 20 == 0)
					getCombatTracker().recheckStatus();

				if (!glowing) {
					boolean glowing = hasEffect(Effects.GLOWING);

					if (getSharedFlag(6) != glowing)
						setSharedFlag(6, glowing);
				}
			}

			aiStep();

			double diffX = getX() - xo;
			double diffZ = getZ() - zo;
			float movementDiff = (float)(diffX * diffX + diffZ * diffZ);
			float direction = yBodyRot;
			float distanceMoved = 0.0F;
			oRun = run;
			float moveSpeedBase = 0.0F;

			if (movementDiff > 0.0025000002F) {
				moveSpeedBase = 1.0F;
				distanceMoved = (float)Math.sqrt(movementDiff) * 3.0F;
				float f = (float)MathHelper.atan2(diffZ, diffX) * (180F / (float)Math.PI) - 90.0F;
				float f1 = MathHelper.abs(MathHelper.wrapDegrees(yRot) - f);

				if (95.0F < f1 && f1 < 265.0F) {
					direction = f - 180.0F;
				}
				else {
					direction = f;
				}
			}

			if (attackAnim > 0.0F)
				direction = yRot;

			if (!onGround)
				moveSpeedBase = 0.0F;

			run += (moveSpeedBase - run) * 0.3F;

			level.getProfiler().push("headTurn");

			distanceMoved = tickHeadTurn(direction, distanceMoved);

			level.getProfiler().pop();
			level.getProfiler().push("rangeChecks");

			while (yRot - yRotO < -180.0F) {
				yRotO -= 360.0F;
			}

			while (yRot - yRotO >= 180.0F) {
				yRotO += 360.0F;
			}

			while (yBodyRot - yBodyRotO < -180.0F) {
				yBodyRotO -= 360.0F;
			}

			while (yBodyRot - yBodyRotO >= 180.0F) {
				yBodyRotO += 360.0F;
			}

			while (xRot - xRotO < -180.0F) {
				xRotO -= 360.0F;
			}

			while (xRot - xRotO >= 180.0F) {
				xRotO += 360.0F;
			}

			while (yHeadRot - yHeadRotO < -180.0F) {
				yHeadRotO -= 360.0F;
			}

			while (yHeadRot - yHeadRotO >= 180.0F) {
				yHeadRotO += 360.0F;
			}

			level.getProfiler().pop();

			animStep += distanceMoved;

			if (isFallFlying()) {
				++fallFlyTicks;
			}
			else {
				fallFlyTicks = 0;
			}

			if (isSleeping())
				xRot = 0.0F;
		}

		if (!level.isClientSide) {
			tickLeash();

			if (tickCount % 5 == 0)
				updateControlFlags();
		}
	}

@Override
	public void onEntityUpdate() {
		if(!this.world.isRemote) {
			//Spawn puller entities that were loaded from nbt
			Iterator<Entity> entityIt = this.loadedPullerEntities.iterator();
			while(entityIt.hasNext()) {
				Entity entity = entityIt.next();

				//Spawning can fail if a chunk isn't loaded yet so keep trying until it works
				if(this.world.spawnEntity(entity)) {
					entityIt.remove();
				}
			}

			//Remove dead pullers
			Iterator<DraetonPhysicsPart> partIt = this.physicsParts.iterator();
			while(partIt.hasNext()) {
				DraetonPhysicsPart part = partIt.next();

				if(part.type == DraetonPhysicsPart.Type.PULLER) {
					Entity entity = part.getEntity();
					if(entity == null || !entity.isEntityAlive()) {
						part.isActive = false;
						partIt.remove();

						TheBetweenlands.networkWrapper.sendToAllTracking(new MessageUpdateDraetonPhysicsPart(this, part, Action.REMOVE), this);
					}
				}
			}

			//Updates leakages
			List<DraetonLeakage> expiredLeakages = null;
			for(DraetonLeakage leakage : this.leakages) {
				if(leakage.age++ > 6000) {
					if(expiredLeakages == null) {
						expiredLeakages = new ArrayList<>();
					}
					expiredLeakages.add(leakage);
				}
			}
			if(expiredLeakages != null) {
				for(DraetonLeakage expired : expiredLeakages) {
					this.removeLeakage(expired);
				}
			}
		}

		for(DraetonPhysicsPart part : this.physicsParts) {
			part.prevX = part.x;
			part.prevY = part.y;
			part.prevZ = part.z;
		}

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;

		float drag = 0.98f;
		for(DraetonPhysicsPart part : this.physicsParts) {
			if(part.getEntity() != null) {
				drag = part.getEntity().getCarriageDrag(drag);
			}
		}

		if(this.onGround || this.inWater) {
			drag *= 0.8f;
		}

		this.motionY *= drag;
		this.motionX *= drag;
		this.motionZ *= drag;

		float speed = MathHelper.sqrt(this.motionX*this.motionX + this.motionY*this.motionY + this.motionZ*this.motionZ);

		this.handleWaterMovement();

		if(this.waterLevel - this.posY > 0.2D) {
			if(this.motionY < 0) {
				this.motionY *= 0.75F;
			}

			this.motionY += 0.01D;
		}

		if(!this.world.isRemote || this.canPassengerSteer()) {
			this.move(MoverType.SELF, this.motionX, this.motionY - 0.0000001f, this.motionZ);
			this.pushOutOfBlocks(this.posX, this.posY, this.posZ);
		}

		float newSpeed = MathHelper.sqrt(this.motionX*this.motionX + this.motionY*this.motionY + this.motionZ*this.motionZ);

		if(!this.world.isRemote) {
			if(this.crashCooldown > 0) {
				if(!this.collided || this.onGround) {
					this.crashCooldown--;
				}
			} else if(this.getControllingPassenger() != null && !this.dataManager.get(ANCHOR_FIXATED) && (this.collided || this.onGround) && speed > this.crashSpeedThreshold && speed - newSpeed > this.crashSpeedThreshold * 0.5f) {
				float leakageChance = Math.min((speed - this.crashSpeedThreshold) * 3.0f, 0.5f) + 0.25f;
				if(this.world.rand.nextFloat() < leakageChance) {
					this.motionX = this.motionY = this.motionZ = 0;
					this.crashCooldown = 20;
					if(this.leakages.size() < 16) {
						this.addLeakage(this.generateRandomLeakage());
					}
				}
			}
		}

		if(!this.world.isRemote || this.canPassengerSteer()) {
			Entity controller = this.getControllingPassenger();

			if(this.world.isRemote && this.canPassengerSteer() && controller instanceof EntityLivingBase) {
				controller.fallDistance = 0;

				this.handleControllerMovement((EntityLivingBase) controller);
			}

			this.updateCarriage();

			if(!this.world.isRemote) {
				this.lerpX = this.posX;
				this.lerpY = this.posY;
				this.lerpZ = this.posZ;
				this.lerpYaw = this.rotationYaw;
				this.lerpPitch = this.rotationPitch;

				for(DraetonPhysicsPart part : this.physicsParts) {
					part.lerpX = part.x;
					part.lerpY = part.y;
					part.lerpZ = part.z;
				}
			}

			if(!this.inWater) {
				if(this.getPassengers().isEmpty() || this.physicsParts.isEmpty()) {
					this.motionY -= 0.005f;
				}
				if(!this.isBurnerRunning()) {
					this.motionY -= 0.06f;
				}
			}
		} else if(this.world.isRemote) {
			this.motionX = this.motionY = this.motionZ = 0;

			for(DraetonPhysicsPart part : this.physicsParts) {
				part.tickLerp();
			}
		}

		this.updateBurner();

		this.updatePullerSlots();

		if(this.world instanceof WorldServer) {
			//Send server state of parts to non-controller players
			if(this.ticksExisted % this.movementSyncTicks == 0) {
				for(DraetonPhysicsPart part : this.physicsParts) {
					MessageUpdateDraetonPhysicsPart msg = new MessageUpdateDraetonPhysicsPart(this, part, MessageUpdateDraetonPhysicsPart.Action.UPDATE);

					Set<? extends EntityPlayer> tracking = ((WorldServer) this.world).getEntityTracker().getTrackingPlayers(this);
					for(EntityPlayer player : tracking) {
						//Don't send to controller
						if(player instanceof EntityPlayerMP && player != this.getControllingPassenger()) {
							TheBetweenlands.networkWrapper.sendTo(msg, (EntityPlayerMP) player);
						}
					}
				}
			}
		}

		this.firstUpdate = false;
	}

@Override
    public Function<Double, Double> calculate(LivingEntity entity, Temperature.Trait trait)
    {
        groupTotals.clear();
        blockTempTotals.clear();
        triggers.clear();

        Level level = entity.level();
        long gameTime = level.getGameTime();
        if (lastTick != gameTime)
        {
            lastTick = gameTime;
            stateCache.clear();
            chunks.clear();
        }

        int range = this.getNBT().contains("RangeOverride", 3) ? this.getNBT().getInt("RangeOverride") : ConfigSettings.BLOCK_RANGE.get();
        BlockPos entPos = entity.blockPosition();

        int entX = entPos.getX();
        int entY = entPos.getY();
        int entZ = entPos.getZ();
        BlockPos.MutableBlockPos blockpos = new BlockPos.MutableBlockPos();

        // Only tick advancements every second, because Minecraft advancements are not performant at all
        boolean shouldTickAdvancements = this.getTicksExisted() % 20 == 0;

        ChunkAccess chunk = null;
        long chunkPos = 0;

        for (int x = -range; x < range; x++)
        {
            int chunkX = (entX + x) >> 4;
            for (int z = -range; z < range; z++)
            {
                int chunkZ = (entZ + z) >> 4;
                long newChunkPos = ChunkPos.asLong(chunkX, chunkZ);
                if (chunk == null || newChunkPos != chunkPos)
                {
                    chunkPos = newChunkPos;
                    chunk = chunks.get(chunkPos);
                    if (chunk == null) chunks.put(chunkPos, chunk = WorldHelper.getChunk(level, new ChunkPos(chunkPos)));
                    if (chunk == null) continue;
                }

                for (int y = -range; y < range; y++)
                {
                    blockpos.set(entX + x, entY + y, entZ + z);

                    long blockPosLong = blockpos.asLong();
                    BlockState state = stateCache.get(blockPosLong);
                    if (state == null)
                    {   LevelChunkSection section = WorldHelper.getChunkSection(chunk, blockpos.getY());
                        state = section.getBlockState(blockpos.getX() & 15, blockpos.getY() & 15, blockpos.getZ() & 15);
                        stateCache.put(blockPosLong, state);
                    }

                    if (state.isAir()) continue;

                    // Get the BlockTemp associated with the block
                    Collection<BlockTemp> blockTemps = BlockTempRegistry.getBlockTempsFor(state);

                    if (blockTemps.isEmpty() || (blockTemps.size() == 1 && blockTemps.contains(BlockTempRegistry.DEFAULT_BLOCK_TEMP))) continue;

                    for (BlockTemp blockTemp : blockTemps)
                    {   blockTempTotals.putIfAbsent(blockTemp, new BlockEffectData(entity, blockTemp, level, blockpos, state));
                    }

                    // Are any of the block temps able to affect the entity?
                    // This check prevents costly calculations if the block can't affect the entity anyway
                    if (this.areAnyBlockTempsInRange(blockTemps))
                    {
                        // Get Vector positions of the centers of the source block and player
                        Vec3 pos = Vec3.atCenterOf(blockpos);

                        // Gets the closest point in the player's BB to the block
                        Vec3 playerClosest = WorldHelper.getClosestPointOnEntity(entity, pos);

                        // Cast a ray between the player and the block
                        // Lessen the effect with each block between the player and the block
                        int[] blocks = new int[1];
                        Vec3 ray = pos.subtract(playerClosest);
                        Direction direction = Direction.getNearest(ray.x, ray.y, ray.z);

                        WorldHelper.forBlocksInRay(playerClosest, pos, level, chunk, stateCache,
                        (rayState, bpos) ->
                        {   if (!bpos.equals(blockpos) && WorldHelper.isSpreadBlocked(level, rayState, bpos, direction, direction))
                            {   blocks[0]++;
                            }
                        }, 3);

                        // Get the temperature of the block given the player's distance
                        double distance = CSMath.getDistance(playerClosest, pos);

                        for (BlockTemp blockTemp : blockTemps)
                        {
                            if (!blockTemp.isValid(level, blockpos, state)) continue;
                            double temperature = blockTemp.getTemperature(level, entity, state, blockpos, distance);
                            if (temperature == 0) continue;

                            BlockEffectData blockEffectData = blockTempTotals.get(blockTemp);
                            if (blockEffectData == null) continue;

                            double tempToAdd = blockEffectData.fades()
                                               ? CSMath.blend(temperature, 0, distance, 0.5, blockEffectData.range())
                                               : temperature;

                            double blockGroupTotal = this.getGroupTotal(blockTemp);
                            double blockGroupDelta = blockGroupTotal - blockEffectData.getTotalEffect();

                            if (blockTemp.isLogarithmic(entity, level, blockpos, state))
                            {   // Calculate amount of increase
                                double newTotal = Math.pow(Math.pow(blockEffectData.getTotalEffect(), 1/LOG_FACTOR) + tempToAdd, LOG_FACTOR);
                                double delta = newTotal - blockEffectData.getTotalEffect();
                                // Dampen the effect with each block between the player and the source
                                delta /= (blocks[0] + 1);
                                // Store this block type's total effect on the player
                                double newVal = CSMath.clamp(blockEffectData.getTotalEffect() + delta,
                                                             blockEffectData.minEffect() + blockGroupDelta,
                                                             blockEffectData.maxEffect() - blockGroupDelta);
                                blockEffectData.setTotalEffect(newVal);
                                updateGroupTotal(blockTemp, newVal - blockEffectData.getTotalEffect());
                            }
                            else
                            {   // Dampen the effect with each block between the player and the source
                                tempToAdd /= (blocks[0] + 1);
                                // Store this block type's total effect on the player
                                double newVal = CSMath.clamp(blockEffectData.getTotalEffect() + tempToAdd,
                                                             blockEffectData.minEffect() + blockGroupDelta,
                                                             blockEffectData.maxEffect() - blockGroupDelta);
                                blockEffectData.setTotalEffect(newVal);
                                updateGroupTotal(blockTemp, newVal - blockEffectData.getTotalEffect());
                            }
                            // Used to trigger advancements
                            if (shouldTickAdvancements)
                            {   triggers.add(new Triplet<>(blockpos, blockTemp, distance));
                            }
                            break;
                        }
                    }
                }
            }
        }
        // Trigger advancements at every BlockPos with a BlockEffect attached to it
        if (entity instanceof ServerPlayer player && shouldTickAdvancements)
        {
            for (Triplet<BlockPos, BlockTemp, Double> trigger : triggers)
            {   ModAdvancementTriggers.BLOCK_AFFECTS_TEMP.trigger(player, trigger.getA(), trigger.getC(), blockTempTotals.get(trigger.getB()).getTotalEffect());
            }
        }

        // Remove old chunks from the cache
        while (chunks.size() >= 16)
        {   chunks.remove(chunks.keySet().iterator().next());
        }

        // Add the effects of all the blocks together and return the result
        Map<BlockTemp, BlockEffectData> totals = new HashMap<>(blockTempTotals);
        return temp ->
        {
            for (Map.Entry<BlockTemp, BlockEffectData> entry : totals.entrySet())
            {
                BlockEffectData data = entry.getValue();
                double min = data.minTemp();
                double max = data.maxTemp();
                if (!CSMath.betweenInclusive(temp, min, max)) continue;
                double effectValue = data.getTotalEffect();
                temp = CSMath.clamp(temp + effectValue, min, max);
            }
            return temp;
        };
    }

