public static void ejector(SceneBuilder builder, SceneBuildingUtil util) {
		CreateSceneBuilder scene = new CreateSceneBuilder(builder);
		scene.title("weighted_ejector", "Using Weighted Ejectors");
		scene.configureBasePlate(0, 0, 5);
		scene.showBasePlate();

		BlockPos ejectorPos = util.grid().at(4, 1, 2);
		Selection ejectorS = util.select().position(ejectorPos);
		BlockPos targetPos = util.grid().at(0, 1, 2);
		Selection targetS = util.select().position(targetPos);

		scene.world().setBlock(targetPos, AllBlocks.ANDESITE_CASING.getDefaultState(), false);
		scene.idle(5);
		scene.world().showSection(targetS, Direction.DOWN);

		scene.idle(10);
		ItemStack asStack = AllBlocks.WEIGHTED_EJECTOR.asStack();
		scene.overlay().showControls(util.vector().topOf(targetPos), Pointing.DOWN, 50).rightClick()
			.whileSneaking()
			.withItem(asStack);
		scene.idle(7);
		Object slot = new Object();
		scene.overlay().chaseBoundingBoxOutline(PonderPalette.OUTPUT, slot, new AABB(targetPos), 160);

		scene.overlay().showText(70)
			.attachKeyFrame()
			.colored(PonderPalette.OUTPUT)
			.text("Sneak and Right-Click holding an Ejector to select its target location")
			.pointAt(util.vector().blockSurface(targetPos, Direction.WEST))
			.placeNearTarget();
		scene.idle(80);
		scene.overlay().showControls(util.vector().topOf(ejectorPos), Pointing.DOWN, 50).rightClick()
			.withItem(asStack);
		scene.idle(7);
		scene.world().setKineticSpeed(ejectorS, 0);
		scene.world().modifyBlockEntityNBT(ejectorS, EjectorBlockEntity.class, nbt -> {
			NBTHelper.writeEnum(nbt, "State", EjectorBlockEntity.State.RETRACTING);
			nbt.putFloat("ForceAngle", 1);
		});
		scene.world().showSection(ejectorS, Direction.DOWN);
		scene.idle(10);

		scene.overlay().showText(60)
			.colored(PonderPalette.OUTPUT)
			.text("The placed ejector will now launch objects to the marked location")
			.pointAt(util.vector().blockSurface(ejectorPos, Direction.WEST))
			.placeNearTarget();
		scene.idle(70);

		slot = new Object();
		AABB bb = new AABB(ejectorPos.west());
		scene.overlay().chaseBoundingBoxOutline(PonderPalette.OUTPUT, slot, bb, 20);
		scene.idle(10);
		scene.overlay().chaseBoundingBoxOutline(PonderPalette.GREEN, slot, bb.expandTowards(-15, 15, 0), 100);
		scene.idle(10);

		scene.overlay().showText(60)
			.attachKeyFrame()
			.colored(PonderPalette.GREEN)
			.text("A valid target can be at any height or distance within range")
			.pointAt(util.vector().blockSurface(targetPos, Direction.WEST))
			.placeNearTarget();
		scene.idle(70);
		scene.overlay().chaseBoundingBoxOutline(PonderPalette.RED, new Object(), bb.move(-2, 0, -1), 60);
		scene.idle(10);
		scene.overlay().showText(50)
			.colored(PonderPalette.RED)
			.text("They cannot however be off to a side")
			.pointAt(util.vector().blockSurface(targetPos.north()
				.east(), Direction.WEST))
			.placeNearTarget();
		scene.idle(70);
		scene.overlay().showOutlineWithText(util.select().position(ejectorPos.west()), 70)
			.colored(PonderPalette.OUTPUT)
			.text("If no valid Target was selected, it will simply target the block directly in front")
			.placeNearTarget();
		scene.idle(80);

		scene.world().showSection(util.select().position(3, 0, 5), Direction.UP);
		scene.world().showSection(util.select().fromTo(4, 1, 5, 4, 1, 3), Direction.DOWN);
		scene.idle(12);
		scene.world().setKineticSpeed(ejectorS, 32);
		scene.idle(10);
		scene.overlay().showText(50)
			.attachKeyFrame()
			.text("Supply Rotational Force in order to charge it up")
			.pointAt(util.vector().topOf(4, 1, 3))
			.placeNearTarget();
		scene.idle(60);

		ItemStack copperBlock = new ItemStack(Items.COPPER_BLOCK);
		ItemStack copperIngot = new ItemStack(Items.COPPER_INGOT);
		scene.overlay().showControls(util.vector().topOf(ejectorPos).add(0.5, 0, 0), Pointing.RIGHT, 30).withItem(copperBlock);
		scene.idle(7);
		scene.world().createItemOnBeltLike(ejectorPos, Direction.NORTH, copperBlock);
		scene.idle(20);
		scene.overlay().showText(50)
			.text("Items placed on the ejector cause it to trigger")
			.pointAt(util.vector().topOf(ejectorPos))
			.placeNearTarget();
		scene.idle(60);

		scene.world().modifyEntities(ItemEntity.class, Entity::discard);
		scene.world().hideSection(targetS, Direction.SOUTH);
		scene.idle(15);
		scene.world().restoreBlocks(targetS);
		scene.world().showSection(targetS, Direction.SOUTH);
		scene.idle(10);
		scene.world().createItemOnBeltLike(targetPos, Direction.SOUTH, copperIngot);
		scene.idle(20);
		scene.world().createItemOnBeltLike(ejectorPos, Direction.SOUTH, copperBlock);
		scene.overlay().showText(60)
			.attachKeyFrame()
			.text("If Inventories are targeted, the ejector will wait until there is space")
			.pointAt(util.vector().topOf(targetPos))
			.placeNearTarget();
		scene.idle(70);
		scene.effects().indicateSuccess(targetPos);
		scene.world().removeItemsFromBelt(targetPos);
		scene.idle(40);
		scene.world().hideSection(targetS, Direction.NORTH);
		scene.idle(15);
		scene.world().setBlock(targetPos, AllBlocks.ANDESITE_CASING.getDefaultState(), false);
		scene.world().showSection(targetS, Direction.NORTH);

		Vec3 input = util.vector().blockSurface(ejectorPos, Direction.WEST)
			.add(0, -2 / 16f, 0);
		Vec3 topOfSlot = input.add(0, 2 / 16f, 0);
		scene.overlay().showControls(topOfSlot, Pointing.DOWN, 60).rightClick();
		scene.overlay().showFilterSlotInput(input, Direction.WEST, 80);
		scene.idle(10);
		scene.overlay().showText(80)
			.attachKeyFrame()
			.text("Using the value panel, a required Stack Size can be configured")
			.pointAt(input.add(0, 0, 0.125))
			.placeNearTarget();
		scene.world().modifyBlockEntityNBT(ejectorS, EjectorBlockEntity.class, nbt -> {
			nbt.putInt("ScrollValue", 10);
		});
		scene.idle(90);

		scene.world().showSection(util.select().fromTo(5, 1, 0, 4, 1, 1), Direction.DOWN);
		scene.world().showSection(util.select().position(5, 0, 1), Direction.UP);
		scene.idle(15);

		BlockPos beltPos = util.grid().at(4, 1, 0);
		scene.world().createItemOnBeltLike(beltPos, Direction.UP, copperBlock);
		scene.overlay().showText(100)
			.text("It is now limited to this stack size, and only activates when its held stack reaches this amount")
			.pointAt(util.vector().topOf(ejectorPos))
			.placeNearTarget();
		for (int i = 0; i < 4; i++) {
			scene.idle(20);
			scene.world().createItemOnBeltLike(beltPos, Direction.UP, copperBlock);
		}
		scene.idle(20);
		scene.world().createItemOnBeltLike(beltPos, Direction.UP, copperBlock.copyWithCount(15));
		scene.idle(80);

		scene.world().hideSection(util.select().fromTo(5, 1, 0, 4, 1, 1), Direction.UP);
		scene.world().hideSection(util.select().position(5, 0, 1), Direction.DOWN);
		scene.idle(30);
		scene.world().modifyEntities(ItemEntity.class, Entity::discard);

		scene.addKeyframe();
		ElementLink<ParrotElement> birb = scene.special().createBirb(util.vector().topOf(ejectorPos)
			.add(0, -3 / 16f, 0), ParrotPose.FlappyPose::new);
		scene.idle(15);
		scene.world().modifyBlockEntity(ejectorPos, EjectorBlockEntity.class, ejector -> ejector.activateDeferred());
		scene.special().moveParrot(birb, util.vector().of(-2, 3, 0), 5);
		scene.special().rotateParrot(birb, 0, 360 * 2, 0, 21);
		scene.idle(5);
		scene.special().moveParrot(birb, util.vector().of(-1, 0, 0), 3);
		scene.idle(3);
		scene.special().moveParrot(birb, util.vector().of(-0.75, -1, 0), 6);
		scene.idle(6);
		scene.special().moveParrot(birb, util.vector().of(-0.25, -2 + 3 / 16f, 0), 12);
		scene.idle(15);
		scene.special().changeBirbPose(birb, ParrotPose.FaceCursorPose::new);
		scene.overlay().showText(80)
			.text("Mobs and Players will always trigger an Ejector when stepping on it")
			.pointAt(util.vector().topOf(targetPos))
			.placeNearTarget();
		scene.idle(50);

	}

@Override
    public void onUseTick(Level level, LivingEntity livingEntity, ItemStack stack, int remainingUseDuration) {
        if (!(livingEntity instanceof Player player))
            return;

        if (player.isPassenger())
            player.stopRiding();

        if (level.isClientSide())
            return;

        var path = new ArrayList<>(stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_PATH, List.<PathPointData>of()));

        if (path.size() < 2) {
            stack.set(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

            if (this.getCooldown(stack) <= 0)
                this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

            player.stopUsingItem();

            return;
        }

        var lastIndex = path.size() - 1;
        var cursor = (double) stack.getOrDefault(RelicsDataComponents.CLOT_OF_TIME_REWIND_CURSOR, -1D);

        if (cursor < 0D || cursor > lastIndex)
            cursor = lastIndex;

        var speed = 1.05D + Math.min(3D, Math.max(0, player.getTicksUsingItem() - 1) * 0.01D);

        cursor = Math.max(0D, cursor - speed);

        var segment = Mth.floor(cursor);

        var t = (float) (cursor - segment);

        var p1 = path.get(segment);
        var p2 = path.get(Math.min(lastIndex, segment + 1));

        if (player instanceof ServerPlayer serverPlayer) {
            var p0 = path.get(Math.max(0, segment - 1));
            var p3 = path.get(Math.min(lastIndex, segment + 2));
            var currentDimension = serverPlayer.level().dimension().location().toString();
            var p1Dimension = p1.dimension().isBlank() ? currentDimension : p1.dimension();
            var p2Dimension = p2.dimension().isBlank() ? currentDimension : p2.dimension();

            if (!p1Dimension.equals(currentDimension)) {
                var dimensionId = ResourceLocation.tryParse(p1Dimension);

                if (dimensionId != null) {
                    var key = ResourceKey.create(Registries.DIMENSION, dimensionId);
                    var targetLevel = serverPlayer.server.getLevel(key);

                    if (targetLevel != null) {
                        serverPlayer.teleportTo(targetLevel, p1.x(), p1.y(), p1.z(), p1.yRot(), p1.xRot());
                        serverPlayer.setPortalCooldown();
                        serverPlayer.setDeltaMovement(Vec3.ZERO);
                        serverPlayer.fallDistance = 0F;

                        setRewindCursor(stack, -1D);
                        setPath(stack, path);

                        player.stopUsingItem();

                        return;
                    }
                }
            }

            double targetX;
            double targetY;
            double targetZ;

            float targetYRot;
            float targetXRot;

            if (!p1Dimension.equals(p2Dimension)) {
                var point = p1Dimension.equals(currentDimension) ? p1 : p2;

                targetX = point.x();
                targetY = point.y();
                targetZ = point.z();

                targetYRot = point.yRot();
                targetXRot = point.xRot();
            } else {
                targetX = Mth.catmullrom(t, (float) p0.x(), (float) p1.x(), (float) p2.x(), (float) p3.x());
                targetY = Mth.catmullrom(t, (float) p0.y(), (float) p1.y(), (float) p2.y(), (float) p3.y());
                targetZ = Mth.catmullrom(t, (float) p0.z(), (float) p1.z(), (float) p2.z(), (float) p3.z());

                var targetRotation = this.interpolateLookRotationCatmullrom(t, p0, p1, p2, p3);

                targetYRot = targetRotation.yRot();
                targetXRot = targetRotation.xRot();
            }

            var clampedXRot = Mth.clamp(targetXRot, -90F, 90F);

            if (serverPlayer.distanceToSqr(targetX, targetY, targetZ) > 16D * 16D)
                serverPlayer.teleportTo((ServerLevel) serverPlayer.level(), targetX, targetY, targetZ, targetYRot, clampedXRot);
            else
                serverPlayer.moveTo(targetX, targetY, targetZ, targetYRot, clampedXRot);

            serverPlayer.setYHeadRot(targetYRot);
            serverPlayer.yHeadRotO = targetYRot;
            serverPlayer.yBodyRot = targetYRot;
            serverPlayer.yBodyRotO = targetYRot;
            serverPlayer.setDeltaMovement(Vec3.ZERO);
            serverPlayer.fallDistance = 0F;
        }

        if (level instanceof ServerLevel) {
            var random = level.random;
            var previousCenter = new Vec3(player.xOld, player.yOld + player.getBbHeight() * 0.55D, player.zOld);
            var currentCenter = new Vec3(player.getX(), player.getY() + player.getBbHeight() * 0.55D, player.getZ());
            var movement = currentCenter.subtract(previousCenter);
            var distance = movement.length();
            var spawnCount = Mth.clamp((int) Math.ceil(distance / 0.125D), 2, 5);
            var phase = player.tickCount * 0.45D;

            for (int step = 0; step <= spawnCount; step++) {
                var progress = spawnCount == 0 ? 0D : (double) step / spawnCount;
                var center = previousCenter.add(movement.scale(progress));
                var subPhase = phase + progress * 0.35D;

                for (int i = 0; i < 6; i++) {
                    var angle = subPhase + i * (Math.PI * 2D / 6D);
                    var radius = 0.45D + 0.12D * Math.sin(subPhase * 1.6D + i);

                    var px = center.x + Math.cos(angle) * radius;
                    var pz = center.z + Math.sin(angle) * radius;
                    var py = center.y + Math.sin(angle * 1.7D) * 0.2D;

                    var hue = (float) ((0.58D + subPhase * 0.025D + i * 0.06D) % 1D);
                    var color = Color.getHSBColor(hue, 0.6F + random.nextFloat() * 0.25F, 1F);

                    var inward = new Vec3(center.x - px, center.y - py, center.z - pz).scale(0.1D);
                    var swirl = new Vec3(-Math.sin(angle), 0D, Math.cos(angle)).scale(0.03D);

                    var velocity = inward.add(swirl).add(0D, 0.01D + random.nextDouble() * 0.01D, 0D);

                    NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat() * 0.15F, 20 + random.nextInt(10), 0.975F), new Vector3f((float) px, (float) py, (float) pz),
                            new Vector3f((float) velocity.x, (float) velocity.y, (float) velocity.z)), player);
                }
            }
        }

        var ability = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("rewind");

        if (ability.canPlayerUse(player)) {
            this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "rewind", 1D / 20D);

            ability.getStatisticData().getMetricData("rewind_duration").addValue(1D / 20D);
        }

        if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
            var rewindHealth = Mth.lerp(t, p1.health(), p2.health());
            var currentHealth = player.getHealth();
            var targetHealth = Math.min(player.getMaxHealth(), Math.max(currentHealth, rewindHealth));

            if (targetHealth > currentHealth) {
                player.setHealth(targetHealth);

                if (ability.canPlayerUse(player) && ability.getRankModifierData("health_rewind").isEnabled()) {
                    this.getRelicData(player, stack).getLevelingData().addExperience("rewind", "health_rewind", targetHealth - currentHealth);
                    ability.getStatisticData().getMetricData("health_restored").addValue(targetHealth - currentHealth);
                }
            }
        }

        while (path.size() > 2 && cursor <= path.size() - 2)
            path.removeLast();

        if (cursor <= 0D) {
            setRewindCursor(stack, -1D);
            setPath(stack, path);

            if (this.getCooldown(stack) <= 0)
                this.setCooldown(stack, Math.max(1, player.getTicksUsingItem()));

            player.stopUsingItem();

            return;
        }

        setRewindCursor(stack, cursor);
        setPath(stack, path);
    }

@Override
	public void tick() {
		this.noPhysics = this.getSize() == PurpoidSize.NORMAL && this.restOntoProgress >= 0.6F;
		super.tick();
		this.noPhysics = false;
		Level level = this.level();
		if (level.isClientSide) {
			this.restOntoProgressO = this.restOntoProgress;
			this.prevPull = this.pull;
			Vec3 pos = this.position();
			this.pull = pos.add(this.pull.subtract(pos).normalize().scale(0.25F));

			if ((this.isBoosting() || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_SQUIRT_ATTACK) || this.getStunTimer() > 0) && level.getGameTime() % 4 == 0) {
				double dy = this.pull.y() - pos.y();
				CorrockCrownParticleData particleData = this.createParticleData();
				RandomSource random = this.getRandom();
				for (int i = 0; i < 2; i++) {
					level.addParticle(particleData, this.getRandomX(0.5D), this.getY() + this.getEyeHeight(), this.getRandomZ(0.5D), MathUtil.makeNegativeRandomly(random.nextDouble() * 0.05F, random), dy * random.nextDouble(), MathUtil.makeNegativeRandomly(random.nextDouble() * 0.05F, random));
				}
			}

			if (!this.isDeadOrDying() && (this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_FAST_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM) || this.isPassenger() || this.getStunTimer() > 0) && this.shouldApplyRotationSnaps()) {
				pos = pos.subtract(0.0F, 1.0F, 0.0F);
				this.pull = pos.add(this.pull.subtract(pos).normalize().scale(0.1F));
			} else {
				float restOntoProgressO = this.restOntoProgressO;
				if (restOntoProgressO > 0.0F) {
					Direction restingSide = this.getRestingSide();
					if (restingSide != Direction.DOWN) {
						restOntoProgressO *= restOntoProgressO;
						pos = pos.subtract(restOntoProgressO * restingSide.getStepX(), restOntoProgressO * restingSide.getStepY(), restOntoProgressO * restingSide.getStepZ());
						this.pull = pos.add(this.pull.subtract(pos).normalize().scale(0.1F));
					}
				}
			}

			int animationTick = this.getAnimationTick();
			if ((this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_FAST_TELEPORT_TO)) && animationTick == 7 || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM) && animationTick == 4 || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEFRAG) && animationTick == 2) {
				this.burstParticles();
			}
		} else {
			if (this.isAlive()) {
				if (this.getSize() != PurpoidSize.PURPAZOID) {
					int age = this.growingAge;
					if (age < 0) {
						this.updateAge(++age);
					} else if (age > 0) {
						this.updateAge(--age);
					}

					if (this.despawnTimer > 0 && --this.despawnTimer == 0) {
						level.broadcastEntityEvent(this, (byte) 1);
						this.discard();
						return;
					}
				} else {
					int tickCount = this.tickCount;

					if (tickCount >= 40) {
						var shieldersIterator = this.shielders.iterator();
						int id = this.getId();
						double x = this.getX();
						double z = this.getZ();
						while (shieldersIterator.hasNext()) {
							if (((ServerLevel) level).getEntity(shieldersIterator.next()) instanceof Purpoid purpoid) {
								int shieldedMommyID = purpoid.getIDOfShieldedMommy();
								boolean purpDoesNotShield = shieldedMommyID < 0;
								if ((purpDoesNotShield || shieldedMommyID == id) && purpoid.isAlive() && purpoid.isBaby() && Mth.square(purpoid.getX() - x) + Mth.square(purpoid.getZ() - z) <= 4096.0D) {
									if (purpDoesNotShield) purpoid.setShieldedMommyId(id);
									continue;
								} else {
									purpoid.setShieldedMommyId(-1);
								}
							}
							shieldersIterator.remove();
						}

						int shieldedMommyID = this.getIDOfShieldedMommy();
						if (shieldedMommyID >= 0) {
							Entity shieldedMommy = level.getEntity(shieldedMommyID);
							if (!(shieldedMommy instanceof Purpoid mommy) || !mommy.shielders.contains(this.uuid)) {
								this.setShieldedMommyId(-1);
							}
						}
					}

					if (tickCount % 20 == 0) {
						AABB searchBox = this.getBoundingBox().inflate(32.0F);
						var nearbyRevengeTargets = level.getEntitiesOfClass(LivingEntity.class, searchBox, entity -> TargetingConditions.DEFAULT.test(this, entity) && this.revengeTargets.contains(entity.getUUID()));
						if (!nearbyRevengeTargets.isEmpty()) {
							var nearbyPassivePurps = level.getEntitiesOfClass(Purpoid.class, searchBox, purpoid -> {
								if (!purpoid.isBaby()) return false;
								LivingEntity purpoidTarget = purpoid.getTarget();
								return (purpoidTarget == null || !purpoidTarget.isAlive()) && !purpoid.isResting();
							});
							RandomSource random = this.getRandom();
							for (Purpoid purpoid : nearbyPassivePurps) {
								purpoid.setTarget(nearbyRevengeTargets.get(random.nextInt(nearbyRevengeTargets.size())));
							}
						}
					}
				}
			}

			if (this.wantsToFlee && this.isNoEndimationPlaying() && !this.getTeleportController().isTeleporting()) {
				BlockPos pos = this.blockPosition();
				int purpoidBlockX = pos.getX();
				int purpoidBlockZ = pos.getZ();
				int levelHeight = level.getHeight();
				RandomSource random = this.getRandom();
				EntityDimensions size = this.getDimensions(this.getPose());
				List<BlockPos> possiblePositions = new ArrayList<>();
				BlockPos.MutableBlockPos mutableBlockPos = new BlockPos.MutableBlockPos();
				for (int relX = -16; relX <= 16; relX++) {
					int x = purpoidBlockX + relX;
					double xMiddle = x + 0.5D;
					for (int relZ = -16; relZ <= 16; relZ++) {
						int z = purpoidBlockZ + relZ;
						int heightAtXZ = level.getHeight(Heightmap.Types.MOTION_BLOCKING, x, z);
						if (!Block.canSupportRigidBlock(level, mutableBlockPos.set(x, heightAtXZ - 1, z))) continue;
						double zMiddle = z + 0.5D;
						int minColumnHeight = Math.min(heightAtXZ + 4, levelHeight);
						int y = Math.min(minColumnHeight + 4 + random.nextInt(9), levelHeight);
						while (y >= minColumnHeight) {
							if (level.noCollision(size.makeBoundingBox(xMiddle, y, zMiddle))) {
								possiblePositions.add(new BlockPos(x, y, z));
								break;
							}
							y--;
						}
					}
				}
				if (!possiblePositions.isEmpty()) {
					this.teleportController.beginTeleportation(this, possiblePositions.get(random.nextInt(possiblePositions.size())), false);
					this.wantsToFlee = false;
				} else if (this.tryToTeleportRandomly(0, 24, 32)) {
					this.wantsToFlee = false;
				}
			}

			if (this.hasTeleportCooldown()) this.teleportCooldown--;
			if (this.hasRestCooldown()) this.restCooldown--;

			if (this.isBoosting()) {
				this.setBoostingTicks(this.getBoostingTicks() - 1);
			} else if (!this.isPassenger() && this.hasTeleportCooldown() && !this.isResting() && this.random.nextFloat() <= 0.001F) {
				this.setBoostingTicks(this.random.nextInt(81) + 80);
			}

			int stunTimer = this.getStunTimer();
			if (stunTimer > 0) this.setStunTimer(stunTimer - 1);

			this.teleportController.tick(this);
		}

		BlockPos restingPos = this.getRestingPos();
		if (restingPos != null && !(this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_TO) || this.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEPORT_FROM))) {
			Direction side = this.getRestingSide();
			Direction.Axis axis = side.getAxis();
			double chosenTestingPos = axis.choose(restingPos.getX(), restingPos.getY(), restingPos.getZ());
			if (side.getAxis().getPlane() == Direction.Plane.HORIZONTAL && side.getAxisDirection() == Direction.AxisDirection.POSITIVE) {
				chosenTestingPos += 1.0D;
			}
			this.restOntoProgress = (float) (1.0F - Mth.clamp(Math.abs(chosenTestingPos - axis.choose(this.getX(), this.getY(), this.getZ())) / 3.0D, 0.0D, 1.0D));
		} else if (this.getStunTimer() > 0) {
			this.restOntoProgress = Math.min(this.restOntoProgress + 0.025F, 1.0F);
		} else {
			this.restOntoProgress = Math.max(this.restOntoProgress - 0.025F, 0.0F);
		}

		if (this.isDeadOrDying()) {
			if (!this.isEndimationPlaying(EEPlayableEndimations.PURPOID_DEATH) && !level.isClientSide) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PURPOID_DEATH);
			}
			if (++this.deathTime >= 20) {
				if (!level.isClientSide) {
					this.discard();
				} else {
					CorrockCrownParticleData particleData = this.createParticleData();
					RandomSource random = this.getRandom();
					for (int i = 0; i < 12; ++i) {
						level.addParticle(particleData, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), MathUtil.makeNegativeRandomly(random.nextFloat() * 0.25F, random), (random.nextFloat() - random.nextFloat()) * 0.3F + 0.1F, MathUtil.makeNegativeRandomly(random.nextFloat() * 0.25F, random));
					}
					for (int i = 0; i < 20; ++i) {
						level.addParticle(ParticleTypes.POOF, this.getRandomX(1.0D), this.getRandomY(), this.getRandomZ(1.0D), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
					}
				}
			}
		}
	}

public void tick()
	{
//		if (world.isRemote)
//		{
//			return;
//		}

//		if (world.getGameTime() % 20 == 0)
//		{
//			outputTank.fill(new FluidStack(Fluids.WATER, 100), FluidAction.EXECUTE);
//		}

		boolean outputChanged = false;

		ItemStack fullBucketStack = this.getItem(INPUT_BUCKET_SLOT);
		ItemStack emptyBucketStack = this.getItem(OUTPUT_BUCKET_SLOT);

		ItemStack[] outputInventory = new ItemStack[] { getItem(1), getItem(2), getItem(3), getItem(4), getItem(5) };

		MultiSlotItemHandler outputSlotHandler = new MultiSlotItemHandler(outputInventory, 64);

		if (!level.isClientSide)
		{
			if (!fullBucketStack.isEmpty())
			{
				ItemStack testFullBucketStack = ItemHandlerHelper.copyStackWithSize(fullBucketStack, 1);
				LazyOptional<IFluidHandlerItem> fluidHandlerWrapper = FluidUtil.getFluidHandler(testFullBucketStack);
				if (fluidHandlerWrapper.isPresent())
				{
					IFluidHandlerItem fluidHandler = fluidHandlerWrapper.resolve().get(); // if its not present it cant go into the slot

					FluidStack transferredStack = FluidUtil.tryFluidTransfer(inputTank, fluidHandler, inputTank.getSpace(), false);
					if (!transferredStack.isEmpty())
					{
						fluidHandler.drain(transferredStack, FluidAction.EXECUTE);
						List<ItemStack> arrayList = new ArrayList<>();
						arrayList.add(fluidHandler.getContainer());
						if (outputSlotHandler.canTransferAllItemsToSlots(arrayList, true))
						{
							outputChanged = true;
							inputTank.fill(transferredStack, FluidAction.EXECUTE);
							outputSlotHandler.canTransferAllItemsToSlots(arrayList, false);
							if (fullBucketStack.getCount() > 1)
							{
								fullBucketStack.setCount(fullBucketStack.getCount() - 1);
							} else
							{
								setItem(INPUT_BUCKET_SLOT, ItemStack.EMPTY);
							}
						}
					} else {
                        transferredStack = FluidUtil.tryFluidTransfer(fluidHandler, inputTank, inputTank.getFluid().getAmount(), false);
                        if (!transferredStack.isEmpty()) {
                            int amount = fluidHandler.fill(transferredStack, FluidAction.EXECUTE);
                            List<ItemStack> arrayList = new ArrayList<>();
                            arrayList.add(fluidHandler.getContainer());
                            if (outputSlotHandler.canTransferAllItemsToSlots(arrayList, true)) {
                                outputChanged = true;
                                inputTank.drain(amount, FluidAction.EXECUTE);
                                outputSlotHandler.canTransferAllItemsToSlots(arrayList, false);
                                if (fullBucketStack.getCount() > 1)
                                {
                                    fullBucketStack.setCount(fullBucketStack.getCount() - 1);
                                } else
                                {
                                    setItem(INPUT_BUCKET_SLOT, ItemStack.EMPTY);
                                }
                            }
                        }
                    }
				}
			}

			if (!emptyBucketStack.isEmpty() && outputTank.getFluidAmount() >= 0)
			{
				ItemStack testEmptyBucketStack = ItemHandlerHelper.copyStackWithSize(emptyBucketStack, 1);
				LazyOptional<IFluidHandlerItem> fluidHandlerWrapper = FluidUtil.getFluidHandler(testEmptyBucketStack);
				if (fluidHandlerWrapper.isPresent())
				{
					IFluidHandlerItem fluidHandler = fluidHandlerWrapper.resolve().get();
					FluidStack transferedStack = FluidUtil.tryFluidTransfer(fluidHandler, outputTank, outputTank.getFluidAmount(), false);
					if (!transferedStack.isEmpty())
					{
						fluidHandler.fill(transferedStack, FluidAction.EXECUTE);
						List<ItemStack> arrayList = new ArrayList<>();
						arrayList.add(fluidHandler.getContainer());
						if (outputSlotHandler.canTransferAllItemsToSlots(arrayList, true))
						{
							outputChanged = true;
							outputTank.drain(transferedStack, FluidAction.EXECUTE);
							outputSlotHandler.canTransferAllItemsToSlots(arrayList, false);
							if (emptyBucketStack.getCount() > 1)
							{
								emptyBucketStack.setCount(emptyBucketStack.getCount() - 1);
							} else
							{
								setItem(OUTPUT_BUCKET_SLOT, ItemStack.EMPTY);
							}
						}
					}
				}
			}
		}

		ItemStack inputStack = this.getItem(INPUT_SLOT);
		ItemStack toolStack = this.getItem(ARC_TOOL_SLOT);

		double craftingMultiplier = 1;
		EnumDemonWillType type = EnumDemonWillType.DEFAULT;
		if (toolStack.getItem() instanceof IARCTool)
		{
			craftingMultiplier = ((IARCTool) toolStack.getItem()).getCraftingSpeedMultiplier(toolStack);
			type = ((IARCTool) toolStack.getItem()).getDominantWillType(toolStack);
		}

		RecipeARC recipe = BloodMagicAPI.INSTANCE.getRecipeRegistrar().getARC(level, inputStack, toolStack, inputTank.getFluid());
		if (canCraft(recipe, inputStack, toolStack, outputSlotHandler))
		{
			// We have enough fluid (if applicable) and the theoretical outputs can fit.
			setIsCrafting(level, worldPosition, getBlockState(), true);
			setDisplayedType(level, worldPosition, getBlockState(), type);
			currentProgress += craftingMultiplier * DEFAULT_SPEED;
			if (currentProgress >= 1)
			{
				if (!level.isClientSide)
				{
					outputChanged = true;
					double bonusChance = 1;
					if (toolStack.getItem() instanceof IARCTool)
					{
						bonusChance = ((IARCTool) toolStack.getItem()).getAdditionalOutputChanceMultiplier(toolStack);
					}

					craftItem(recipe, inputStack, toolStack, outputSlotHandler, bonusChance);
				}

				currentProgress = 0;
			}
		} else
		{
			if (toolStack.is(BloodMagicTags.ARC_TOOL_FURNACE))
			{
				InventoryWrapper invWrapper = new InventoryWrapper(1);
				invWrapper.setItem(0, inputStack.copy());
//				ItemStack[] outputInventory = new ItemStack[]
//				{ input };

//				MultiSlotItemHandler outputSlotHandler = new MultiSlotItemHandler(outputInventory, 64);
				Optional<SmeltingRecipe> furnaceRecipe = level.getRecipeManager().getRecipeFor(RecipeType.SMELTING, invWrapper, level);
				if (furnaceRecipe.isPresent())
				{
					ItemStack outputStack = furnaceRecipe.get().assemble(invWrapper, level.registryAccess());
					if (canCraftFurnace(outputStack, outputSlotHandler))
					{
						setIsCrafting(level, worldPosition, getBlockState(), true);
						setDisplayedType(level, worldPosition, getBlockState(), type);
						currentProgress += craftingMultiplier * DEFAULT_SPEED;
						if (currentProgress >= 1)
						{
							if (!level.isClientSide)
							{
								craftFurnace(outputStack, outputSlotHandler);
								outputChanged = true;
							}

							currentProgress = 0;
						}
					}
				} else
				{
					currentProgress = 0;
					setIsCrafting(level, getBlockPos(), getBlockState(), false);
					setDisplayedType(level, worldPosition, getBlockState(), type);
				}
			} else
			{
				currentProgress = 0;
				setIsCrafting(level, getBlockPos(), getBlockState(), false);
				setDisplayedType(level, worldPosition, getBlockState(), type);
			}
		}

		if (outputChanged && !level.isClientSide)
		{
			for (int i = 0; i < NUM_OUTPUTS; i++)
			{
				this.setItem(OUTPUT_SLOT + i, outputSlotHandler.getStackInSlot(i));
			}
		}

//		FluidUtil.tryEmptyContainer(container, fluidDestination, maxAmount, player, doDrain)
	}

public static void onLivingEntityTick(LivingEntity entity) {
        if (entity.isRemoved()) return;

        var capability = AccessoriesCapability.get(entity);

        if (capability != null) {
            var dirtyStacks = new HashMap<SlotPath, ItemStack>();
            var dirtyCosmeticStacks = new HashMap<SlotPath, ItemStack>();

            var removedAttributesBuilder = new AccessoryAttributeBuilder();
            var addedAttributesBuilder = new AccessoryAttributeBuilder();

            for (var containerEntry : AccessoriesHolderImpl.getHolder(capability).getAllSlotContainers().entrySet()) {
                var container = containerEntry.getValue();

                var accessories = container.getAccessories();
                var cosmetics = container.getCosmeticAccessories();

                for (int i = 0; i < accessories.getContainerSize(); i++) {
                    var slotReference = container.createReference(i);

                    var currentStack = accessories.getItem(i);

                    // TODO: Move ticking below checks?
                    if (!currentStack.isEmpty()) {
                        // TODO: Document this behavior to prevent double ticking maybe!!!
                        currentStack.inventoryTick(entity.level(), entity, null);

                        var accessory = AccessoryRegistry.getAccessoryOrDefault(currentStack);

                        if (accessory != null) {
                            accessory.tick(currentStack, slotReference);

                            AccessoryNestUtils.recursivelyConsume(currentStack, stack -> {
                                var effects = stack.get(AccessoriesDataComponents.MOB_EFFECTS);

                                if (effects != null) {
                                    effects.handleReapplyingEffects(entity, entity.level().getGameTime());
                                }
                            });
                        }
                    }

                    var lastStack = accessories.getPreviousItem(i);
                    var flagged = accessories.isSlotFlagged(i);

                    // Prevent attribute related logic on the client and if the entity
                    // is dead as such data should not be updated. Though we allow for
                    // ticking to occur at least for vanilla parity I guess.
                    if (entity.level().isClientSide() || entity.isDeadOrDying()) continue;

                    if (!ItemStack.matches(currentStack, lastStack) || flagged) {
                        if (!lastStack.isEmpty()) {
                            var removedEnchantmentBuilder = new AccessoryAttributeBuilder(slotReference);

                            // TODO: MAYBE MOVE THIS TO AccessoryAttributeLogic or something
                            EnchantmentHelper.forEachModifier(lastStack, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot(), (attributeHolder, modifier) -> {
                                var namespace = modifier.id().getNamespace();
                                var splitPath = new ArrayList<>(List.of(modifier.id().getPath().split("/")));

                                splitPath.removeLast();

                                removedEnchantmentBuilder.addStackable(attributeHolder, new AttributeModifier(ResourceLocation.fromNamespaceAndPath(namespace, String.join("/", splitPath)), modifier.amount(), modifier.operation()));
                            });

                            removedAttributesBuilder.addFrom(removedEnchantmentBuilder);
                            removedAttributesBuilder.addFrom(AccessoryAttributeLogic.getAttributeModifiers(lastStack, slotReference));

                            ((AccessoriesLivingEntityExtension) entity).pushEnchantmentContext(lastStack, slotReference);
                            EnchantmentHelper.stopLocationBasedEffects(lastStack, entity, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot());
                        }

                        if (!currentStack.isEmpty()) {
                            var addedEnchantmentBuilder = new AccessoryAttributeBuilder(slotReference);

                            EnchantmentHelper.forEachModifier(currentStack, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot(), (attributeHolder, modifier) -> {
                                var namespace = modifier.id().getNamespace();
                                var splitPath = new ArrayList<>(List.of(modifier.id().getPath().split("/")));

                                splitPath.removeLast();

                                addedEnchantmentBuilder.addStackable(attributeHolder, new AttributeModifier(ResourceLocation.fromNamespaceAndPath(namespace, String.join("/", splitPath)), modifier.amount(), modifier.operation()));
                            });

                            addedAttributesBuilder.addFrom(addedEnchantmentBuilder);
                            addedAttributesBuilder.addFrom(AccessoryAttributeLogic.getAttributeModifiers(currentStack, slotReference));

                            ((AccessoriesLivingEntityExtension) entity).pushEnchantmentContext(currentStack, slotReference);
                            EnchantmentHelper.runLocationChangedEffects((ServerLevel) entity.level(), currentStack, entity, AccessoriesInternals.INSTANCE.getInternalEquipmentSlot());
                        }

                        AccessoryNestUtils.recursivelyConsume(lastStack, stack -> {
                            if (stack.has(AccessoriesDataComponents.MOB_EFFECTS)) {
                                stack.get(AccessoriesDataComponents.MOB_EFFECTS)
                                    .handleRemovingEffects(entity);
                            }
                        });

                        AccessoryNestUtils.recursivelyConsume(currentStack, stack -> {
                            if (stack.has(AccessoriesDataComponents.MOB_EFFECTS)) {
                                stack.get(AccessoriesDataComponents.MOB_EFFECTS)
                                    .handleApplyingConstantEffects(entity);
                            }
                        });

                        boolean equipmentChange = false;

                        /*
                         * TODO: Does item check need to exist anymore?
                         */
                        if (!ItemStack.isSameItem(currentStack, lastStack) || flagged) {
                            AccessoryRegistry.getAccessoryOrDefault(lastStack).onUnequip(lastStack, slotReference);
                            AccessoryRegistry.getAccessoryOrDefault(currentStack).onEquip(currentStack, slotReference);

                            if (entity instanceof ServerPlayer serverPlayer) {
                                if (!currentStack.isEmpty()) {
                                    ACCESSORY_EQUIPPED.trigger(serverPlayer, currentStack, slotReference, false);
                                }

                                if (!lastStack.isEmpty()) {
                                    ACCESSORY_UNEQUIPPED.trigger(serverPlayer, lastStack, slotReference, false);
                                }
                            }

                            equipmentChange = true;
                        }

                        AccessoryChangeCallback.EVENT.invoker().onChange(lastStack, currentStack, slotReference, equipmentChange ? SlotStateChange.REPLACEMENT : SlotStateChange.MUTATION);

                        container.getAccessories().setPreviousItem(i, currentStack);
                        dirtyStacks.put(slotReference.slotPath(), currentStack.copy());

                        recursiveStackChange(slotReference, AccessoryNestUtils.getData(lastStack), AccessoryNestUtils.getData(currentStack));
                    }

                    var currentCosmeticStack = cosmetics.getItem(i);
                    var lastCosmeticStack = container.getCosmeticAccessories().getPreviousItem(i);

                    if (!ItemStack.matches(currentCosmeticStack, lastCosmeticStack)) {
                        cosmetics.setPreviousItem(i, currentCosmeticStack);
                        dirtyCosmeticStacks.put(slotReference.slotPath(), currentCosmeticStack.copy());

                        if (entity instanceof ServerPlayer serverPlayer) {
                            if (!currentStack.isEmpty()) {
                                ACCESSORY_EQUIPPED.trigger(serverPlayer, currentStack, slotReference, true);
                            }
                            if (!lastStack.isEmpty()) {
                                ACCESSORY_UNEQUIPPED.trigger(serverPlayer, lastStack, slotReference, true);
                            }
                        }
                    }
                }
            }

            if (entity.level().isClientSide()) return;

            AttributeUtils.removeTransientAttributeModifiers(entity, removedAttributesBuilder);
            AttributeUtils.addTransientAttributeModifiers(entity, addedAttributesBuilder);

            //--
            var updatedContainers = AccessoriesHolderImpl.getHolder(capability).containersRequiringUpdates();

            capability.updateContainers();

            ContainersChangeCallback.EVENT.invoker().onChange(entity, capability, ImmutableMap.copyOf(updatedContainers));

            if (!dirtyStacks.isEmpty() || !dirtyCosmeticStacks.isEmpty() || !updatedContainers.isEmpty()) {
                var packet = SyncContainerData.of(entity, updatedContainers.keySet(), dirtyStacks, dirtyCosmeticStacks);

                AccessoriesNetworking.sendToTrackingAndSelf(entity, packet);
            }

            updatedContainers.clear();
        }

        //--

        var holder = ((AccessoriesHolderImpl) AccessoriesInternals.INSTANCE.getHolder(entity));

        // Fix for holder data not being loaded so invalid stacks can be collected
        if (holder.loadedFromTag() && capability == null) {
            var tempCapability = new AccessoriesCapabilityImpl(entity);
        }

        var invalidStacks = (holder).invalidStacks;

        if (!invalidStacks.isEmpty() && entity.level() instanceof ServerLevel serverLevel) {
            for (ItemStack invalidStack : invalidStacks) {
                if (entity instanceof ServerPlayer serverPlayer) {
                    AccessoriesInternals.INSTANCE.giveItemToPlayer(serverPlayer, invalidStack);
                } else {
                    entity.spawnAtLocation(serverLevel, invalidStack);
                }
            }

            invalidStacks.clear();
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();

		if(this.attackDamageTicks > 0) {
			this.attackDamageTicks--;
		}

		boolean isMovingDown = this.isMoving() && !this.isSlow();

		if(this.getTargetEActive() && !isMovingDown) {
			this.beamTransparencyTicks[0] = Math.min(15, this.beamTransparencyTicks[0] + 1);
		} else {
			this.beamTransparencyTicks[0] = Math.max(0, this.beamTransparencyTicks[0] - 1);
		}

		if(this.getTargetWActive() && !isMovingDown) {
			this.beamTransparencyTicks[1] = Math.min(15, this.beamTransparencyTicks[1] + 1);
		} else {
			this.beamTransparencyTicks[1] = Math.max(0, this.beamTransparencyTicks[1] - 1);
		}

		if(this.getTargetSActive() && !isMovingDown) {
			this.beamTransparencyTicks[2] = Math.min(15, this.beamTransparencyTicks[2] + 1);
		} else {
			this.beamTransparencyTicks[2] = Math.max(0, this.beamTransparencyTicks[2] - 1);
		}

		if(this.getTargetNActive() && !isMovingDown) {
			this.beamTransparencyTicks[3] = Math.min(15, this.beamTransparencyTicks[3] + 1);
		} else {
			this.beamTransparencyTicks[3] = Math.max(0, this.beamTransparencyTicks[3] - 1);
		}

		float animationTicks = this.dataManager.get(ANIMATION_TICKS);

		animationTicksPrev = animationTicks;
		animationTicksChainPrev = animationTicksChain;

		if(!this.world.isRemote) {
			if (animationTicks + 1 >= 360F) {
				this.dataManager.set(ANIMATION_TICKS, 0.0F);
			} else {
				this.dataManager.set(ANIMATION_TICKS, animationTicks + 1);
			}
		}

		while(animationTicks - this.animationTicksPrev < -180.0F) {
			this.animationTicksPrev -= 360.0F;
        }
        while(animationTicks - this.animationTicksPrev >= 180.0F) {
        	this.animationTicksPrev += 360.0F;
        }

        //Set prev pos, rotation, etc.
        for(Entity entity : parts) {
        	entity.onUpdate();
        }

		setNewShieldHitboxPos(animationTicks, shield_1);
		setNewShieldHitboxPos(-animationTicks + 22.5F, shield_2);
		setNewShieldHitboxPos(animationTicks + 45F, shield_3);
		setNewShieldHitboxPos(-animationTicks + 67.5F, shield_4);
		setNewShieldHitboxPos(animationTicks + 90F, shield_5);
		setNewShieldHitboxPos(-animationTicks + 112.5F, shield_6);
		setNewShieldHitboxPos(animationTicks + 135F, shield_7);
		setNewShieldHitboxPos(-animationTicks + 157F, shield_8);

		setNewShieldHitboxPos(animationTicks + 180F, shield_9);
		setNewShieldHitboxPos(-animationTicks + 202.5F, shield_10);
		setNewShieldHitboxPos(animationTicks + 225F, shield_11);
		setNewShieldHitboxPos(-animationTicks + 247.5F, shield_12);
		setNewShieldHitboxPos(animationTicks + 270F, shield_13);
		setNewShieldHitboxPos(-animationTicks + 292.5F, shield_14);
		setNewShieldHitboxPos(animationTicks + 315F, shield_15);
		setNewShieldHitboxPos(-animationTicks + 337.5F, shield_16);

		target_north.setPosition(posX, posY + 3D, posZ - 0.75D);
		target_east.setPosition(posX + 0.75D, posY + 3D, posZ);
		target_south.setPosition(posX, posY + 3D, posZ + 0.75D);
		target_west.setPosition(posX - 0.75D, posY + 3D, posZ);
		bottom.setPosition(posX, posY, posZ);

		if (isMoving()) {
			if (isSlow())
				animationTicksChain++;
			else
				animationTicksChain += 8;
			if(getHangingChains() != null)
				getHangingChains().setProgress(getProgress());

			if (!isRaising() && getProgress() < MAX_PROGRESS) {
				move(MoverType.SELF, 0D, -MOVE_UNIT * 8D, 0D);
				setProgress(getProgress() + 8);

				if (getHangingChains() != null) {
					getHangingChains().setMoving(true);
					getHangingChains().setSlow(false);
				}

				if (getGroundChains() != null) {
					for (TileEntityDecayPitGroundChain chain : getGroundChains()) {
						chain.setRaising(true);
						chain.setMoving(true);
						chain.setSlow(false);
					}
				}
			}

			if (isRaising() && getProgress() > MIN_PROGRESS) {
				move(MoverType.SELF, 0D, + MOVE_UNIT, 0D);
				setProgress(getProgress() - 1);

				if (getHangingChains() != null) {
					getHangingChains().setMoving(true);
					getHangingChains().setSlow(true);
				}

				if (getGroundChains() != null) {
					for (TileEntityDecayPitGroundChain chain : getGroundChains()) {
						chain.setRaising(false);
						chain.setMoving(true);
						chain.setSlow(true);
					}
				}
			}

		}

		if (animationTicksChainPrev >= 128) {
			animationTicksChain = animationTicksChainPrev = 0;
			setMoving(false);
		}

		if (getProgress() > MAX_PROGRESS)
			setProgress(MAX_PROGRESS);

		if (getProgress() < MIN_PROGRESS)
			setProgress(MIN_PROGRESS);

		if (!getEntityWorld().isRemote) { // upsy-daisy
			if (getProgress() > MIN_PROGRESS && getEntityWorld().getTotalWorldTime() % 400 == 0 && attackDamageTicks == 0)
				moveUp();

			TileEntityDecayPitControl control = this.getControl();

			if (control != null && getEntityWorld().getTotalWorldTime() % 10 == 0) {
				if (getProgress() < 128)
					control.setSpawnType(0);
				if (getProgress() >= 128 && getProgress() < 256)
					control.setSpawnType(1);
				if (getProgress() >= 256 && getProgress() < 384)
					control.setSpawnType(2);
				if (getProgress() >= 384 && getProgress() < 512)
					control.setSpawnType(3);
				if (getProgress() >= 512 && getProgress() < 640)
					control.setSpawnType(4);
				if (getProgress() >= 640)
					control.setSpawnType(5);
			}

			if (control != null && control.getSpawnType() == 5) {
				TileEntityDecayPitHangingChain hangingChains = this.getHangingChains();

				if (hangingChains != null) {
					hangingChains.setBroken(true);
					hangingChains.setMoving(true);
					hangingChains.setSlow(false);
					hangingChains.updateBlock();
				}

				if (getGroundChains() != null) {
					for (TileEntityDecayPitGroundChain chain : getGroundChains()) {
						chain.setBroken(true);
						chain.setRaising(false);
						chain.setMoving(true);
						chain.setSlow(false);
						chain.updateBlock();
					}
				}
				setDead(); // TODO some particles to show the bobbing shields break
			}
		}

		if(!this.world.isRemote && this.isEntityAlive()) {
			for(int i = 0; i < this.dummies.length; i++) {
				DummyPart dummy = this.dummies[i];

				if(dummy == null || !dummy.isEntityAlive()) {
					Entity multipart = parts[i];

					if(multipart instanceof MultiPartEntityPart) {
						this.dummies[i] = dummy = new DummyPart(this.world, (MultiPartEntityPart) multipart);
						this.world.spawnEntity(dummy);
					}
				} else {
					dummy.updatePositioning();
				}
			}
		}
	}

public void tick() {
		if (pauseBeforePropagation > 0) {
			pauseBeforePropagation--;
			return;
		}

		for (int cycle = 0; cycle < CYCLES_PER_TICK; cycle++) {
			boolean shouldContinue = false;
			for (Iterator<BlockFace> iterator = queued.iterator(); iterator.hasNext();) {
				BlockFace blockFace = iterator.next();
				if (!isPresent(blockFace))
					continue;
				PipeConnection pipeConnection = get(blockFace);
				if (pipeConnection != null) {
					if (blockFace.equals(start))
						transferSpeed = (int) Math.max(1, pipeConnection.pressure.get(true) / 2f);
					frontier.add(Pair.of(blockFace, pipeConnection));
				}
				iterator.remove();
			}

//			drawDebugOutlines();

			for (Iterator<Pair<BlockFace, PipeConnection>> iterator = frontier.iterator(); iterator.hasNext();) {
				Pair<BlockFace, PipeConnection> pair = iterator.next();
				BlockFace blockFace = pair.getFirst();
				PipeConnection pipeConnection = pair.getSecond();

				if (!pipeConnection.hasFlow())
					continue;

				Flow flow = pipeConnection.flow.get();
				if (!fluid.isEmpty() && !FluidStack.isSameFluidSameComponents(flow.fluid, fluid)) {
					iterator.remove();
					continue;
				}
				if (!flow.inbound) {
					if (pipeConnection.comparePressure() >= 0)
						iterator.remove();
					continue;
				}
				if (!flow.complete)
					continue;

				if (fluid.isEmpty())
					fluid = flow.fluid;

				boolean canRemove = true;
				for (Direction side : Iterate.directions) {
					if (side == blockFace.getFace())
						continue;
					BlockFace adjacentLocation = new BlockFace(blockFace.getPos(), side);
					PipeConnection adjacent = get(adjacentLocation);
					if (adjacent == null)
						continue;
					if (!adjacent.hasFlow()) {
						// Branch could potentially still appear
						if (adjacent.hasPressure() && adjacent.pressure.getSecond() > 0)
							canRemove = false;
						continue;
					}
					Flow outFlow = adjacent.flow.get();
					if (outFlow.inbound) {
						if (adjacent.comparePressure() > 0)
							canRemove = false;
						continue;
					}
					if (!outFlow.complete) {
						canRemove = false;
						continue;
					}

					// Give pipe end a chance to init connections
					if (!adjacent.source.isPresent() && !adjacent.determineSource(world, blockFace.getPos())) {
						canRemove = false;
						continue;
					}

					if (adjacent.source.isPresent() && adjacent.source.get()
						.isEndpoint()) {
						targets.add(Pair.of(adjacentLocation, adjacent.source.get()));
						continue;
					}

					if (visited.add(adjacentLocation.getConnectedPos())) {
						queued.add(adjacentLocation.getOpposite());
						shouldContinue = true;
					}
				}
				if (canRemove)
					iterator.remove();
			}
			if (!shouldContinue)
				break;
		}

//		drawDebugOutlines();

		if (source == null)
			source = sourceSupplier.get();
		if (source == null)
			return;

		keepPortableFluidInterfaceEngaged();

		if (targets.isEmpty())
			return;
		for (Pair<BlockFace, FlowSource> pair : targets) {
			if (pair.getSecond() != null && world.getGameTime() % 40 != 0)
				continue;
			PipeConnection pipeConnection = get(pair.getFirst());
			if (pipeConnection == null)
				continue;
			pipeConnection.source.ifPresent(fs -> {
				if (fs.isEndpoint())
					pair.setSecond(fs);
			});
		}

		int flowSpeed = transferSpeed;
		Map<IFluidHandler, Integer> accumulatedFill = new IdentityHashMap<>();

		for (boolean simulate : Iterate.trueAndFalse) {
			FluidAction action = simulate ? FluidAction.SIMULATE : FluidAction.EXECUTE;

			if (source == null)
				return;
			IFluidHandler sourceCap = source.getCapability();
			if (sourceCap == null)
				return;

			FluidStack transfer = FluidStack.EMPTY;
			for (int i = 0; i < sourceCap.getTanks(); i++) {
				FluidStack contained = sourceCap.getFluidInTank(i);
				if (contained.isEmpty())
					continue;
				if (!FluidStack.isSameFluidSameComponents(contained, fluid))
					continue;
				FluidStack toExtract = FluidHelper.copyStackWithAmount(contained, flowSpeed);
				transfer = sourceCap.drain(toExtract, action);
				break;
			}

			if (transfer.isEmpty()) {
				FluidStack genericExtract = sourceCap.drain(flowSpeed, action);
				if (!genericExtract.isEmpty() && FluidStack.isSameFluidSameComponents(genericExtract, fluid))
					transfer = genericExtract;
			}

			if (transfer.isEmpty())
				return;
			if (simulate)
				flowSpeed = transfer.getAmount();

			List<Pair<BlockFace, FlowSource>> availableOutputs = new ArrayList<>(targets);
			while (!availableOutputs.isEmpty() && transfer.getAmount() > 0) {
				int dividedTransfer = transfer.getAmount() / availableOutputs.size();
				int remainder = transfer.getAmount() % availableOutputs.size();

				for (Iterator<Pair<BlockFace, FlowSource>> iterator = availableOutputs.iterator(); iterator.hasNext();) {
					Pair<BlockFace, FlowSource> pair = iterator.next();
					int toTransfer = dividedTransfer;
					if (remainder > 0) {
						toTransfer++;
						remainder--;
					}

					if (transfer.isEmpty())
						break;
					@Nullable ICapabilityProvider<IFluidHandler> targetHandlerProvider = pair.getSecond().provideHandler();
					if (targetHandlerProvider == null) {
						iterator.remove();
						continue;
					}
					IFluidHandler targetHandler = targetHandlerProvider.getCapability();
					if (targetHandler == null) {
						iterator.remove();
						continue;
					}

					int simulatedTransfer = toTransfer;
					if (simulate)
						simulatedTransfer += accumulatedFill.getOrDefault(targetHandler, 0);

					FluidStack divided = transfer.copy();
					divided.setAmount(simulatedTransfer);
					int fill = targetHandler.fill(divided, action);

					if (simulate) {
						accumulatedFill.put(targetHandler, Integer.valueOf(fill));
						fill -= simulatedTransfer - toTransfer;
					}

					transfer.setAmount(transfer.getAmount() - fill);
					if (fill < simulatedTransfer)
						iterator.remove();
				}

			}

			flowSpeed -= transfer.getAmount();
			transfer = FluidStack.EMPTY;
		}
	}

private void fireLaser(ServerLevel level, int firing, TransactionContext transaction) {
        Direction direction = getDirection();
        Axis axis = direction.getAxis();
        Vec3 from = Vec3.atCenterOf(worldPosition).relative(direction, 0.501);
        Vec3 to = from.relative(direction, MekanismConfig.general.laserRange.get() - 0.002);
        BlockHitResult result = level.clip(new ClipContext(from, to, ClipContext.Block.OUTLINE, ClipContext.Fluid.NONE, CollisionContext.empty()));
        if (result.getType() != Type.MISS) {
            to = result.getLocation();
        }

        float laserEnergyScale = getEnergyScale(firing);
        int remainingEnergy = firing;
        List<Entity> hitEntities = level.getEntitiesOfClass(Entity.class, getLaserBox(direction, from, to, laserEnergyScale));
        if (hitEntities.isEmpty()) {
            setEmittingRedstone(false);
        } else {
            setEmittingRedstone(true);
            //Sort the entities in order of which one is closest to the laser
            Vec3 finalFrom = from;
            hitEntities.sort(Comparator.comparingDouble(entity -> entity.distanceToSqr(finalFrom)));
            int energyPerDamage = MekanismConfig.general.laserEnergyPerDamage.get();
            AABB adjustedAABB = null;
            for (Entity entity : hitEntities) {
                if (adjustedAABB != null && !entity.getBoundingBox().intersects(adjustedAABB)) {
                    //If we have a smaller AABB than we started with, make sure the entity still is getting hit by the laser
                    // before we do any processing related to behavior when hit
                    continue;
                } else if (isInvulnerableToLaser(entity, level)) {
                    //The entity can absorb all the energy because they are immune to the damage
                    remainingEnergy = 0;
                    //Update the position that the laser is going to
                    to = from.with(axis, entity.position().get(axis));
                    break;
                } else if (entity instanceof ItemEntity item && handleHitItem(item, transaction)) {
                    //TODO: Allow the tractor beam to have an energy cost for pulling items?
                    continue;
                }
                boolean updateEnergyScale = false;
                double value = (double) remainingEnergy / energyPerDamage;
                float damage = (float) value;
                float health = 0;
                if (entity instanceof LivingEntity livingEntity) {
                    //If the entity is a living entity check if they are blocking with a shield and then allow
                    // the shield to cause some damage to be dissipated in exchange for durability
                    boolean updateDamage = false;
                    //TODO - V11: Add a laser reflector capability that shields can implement to cause the laser beam to be reflected
                    // maybe even implement this ability but don't add it to any of our things yet?
                    float damageBlocked = damageShield(level, livingEntity, from, damage);
                    if (damageBlocked > 0) {
                        if (livingEntity instanceof ServerPlayer player) {
                            //If the entity is a player trigger the advancement criteria for blocking a laser with a shield
                            MekanismCriteriaTriggers.BLOCK_LASER.value().trigger(player);
                        }
                        //Remove however much energy we were able to block
                        remainingEnergy -= MathUtils.clampToInt(energyPerDamage * damageBlocked);
                        if (remainingEnergy == 0) {
                            //If we absorbed it all then update the position the laser is going to and break
                            to = from.with(axis, entity.position().get(axis));
                            break;
                        }
                        updateDamage = true;
                    }
                    //After our shield checks see if the armor the entity is wearing can dissipate or refract lasers
                    float dissipationPercent = 0;
                    float refractionPercent = 0;
                    ResourceHandler<ItemResource> armorSlots = LivingEntityEquipmentWrapper.of(livingEntity, EquipmentSlot.Type.HUMANOID_ARMOR);
                    for (int slot = 0, size = armorSlots.size(); slot < size; slot++) {
                        ItemStack stack = ItemUtil.getStack(armorSlots, slot);
                        if (!stack.isEmpty()) {
                            ILaserDissipation laserDissipation = stack.getCapability(Capabilities.LASER_DISSIPATION);
                            if (laserDissipation != null) {
                                dissipationPercent += laserDissipation.getDissipationPercent();
                                refractionPercent += laserDissipation.getRefractionPercent();
                                if (dissipationPercent >= 1) {
                                    //If we will fully dissipate it, don't bother checking the rest of the armor slots
                                    break;
                                }
                            }
                        }
                    }
                    //We start by dissipating energy across the armor after it is blocked by the shield
                    // we check this after blocking by the shield as the shield is in front of the entity and their armor
                    if (dissipationPercent > 0) {
                        //If we will dissipate any energy, cap the dissipation amount at one
                        dissipationPercent = Math.min(dissipationPercent, 1);
                        remainingEnergy = (int) (remainingEnergy * (1 - dissipationPercent));
                        if (remainingEnergy == 0) {
                            //If we dissipated it all then update the position the laser is going to and break
                            to = from.with(axis, entity.position().get(axis));
                            break;
                        }
                        updateDamage = true;
                    }
                    //After dissipating any energy across the armor we try to refract some energy through the armor this
                    // will further reduce the damage the entity would take and allow the laser to continue through onto
                    // the other side
                    if (refractionPercent > 0) {
                        //If we will refract any energy, cap the refraction amount at one
                        refractionPercent = Math.min(refractionPercent, 1);
                        float refractedEnergy = remainingEnergy * refractionPercent;
                        //Don't actually use the refracted energy from our remaining energy
                        // but lower the damage values to not include the energy that is being refracted
                        // and mark that we don't actually need to update the damage values (as we just did so here)
                        value = (remainingEnergy - refractedEnergy) / energyPerDamage;
                        damage = (float) value;
                        updateDamage = false;
                        //Mark the energy scale should be checked for updates as if some energy got dissipated above, and
                        // we end up refracting all the remaining energy we won't do any damage and not get through the
                        // normal code path that checks if the energy scale changed
                        updateEnergyScale = true;
                    }
                    if (updateDamage) {
                        //Update the damage we are actually going to try and do to the entity as the amount of energy being used changed
                        value = (double) remainingEnergy / energyPerDamage;
                        damage = (float) value;
                    }
                    health = livingEntity.getHealth();
                }
                if (damage > 0) {
                    //If the damage is more than zero, which should be all cases except for when we are refracting all the energy past the entity
                    // set the entity on fire if it is not damage immune and try to damage it
                    if (!entity.fireImmune()) {
                        entity.igniteForTicks(MathUtils.clampToInt(value));
                    }
                    int totemTimesUsed = -1;
                    if (entity instanceof ServerPlayer player && level.getServer().isHardcore()) {
                        totemTimesUsed = player.getStats().getValue(Stats.ITEM_USED.get(Items.TOTEM_OF_UNDYING));
                    }
                    //Note: We add the laser damage type to bypass cooldown via tags so this will go off regardless of invulnerability timer
                    boolean damaged = entity.hurtServer(level, MekanismDamageTypes.LASER.source(level), damage);
                    if (damaged) {
                        //If we damaged it
                        if (entity instanceof LivingEntity livingEntity) {
                            //Update the damage to match how much health the entity lost
                            damage = Math.clamp(health - livingEntity.getHealth(), 0, damage);
                            if (entity instanceof ServerPlayer player) {
                                //If the damage actually went through fire the trigger
                                boolean hardcoreTotem = totemTimesUsed != -1 && totemTimesUsed < player.getStats().getValue(Stats.ITEM_USED.get(Items.TOTEM_OF_UNDYING));
                                MekanismCriteriaTriggers.DAMAGE.value().trigger(player, MekanismDamageTypes.LASER, hardcoreTotem);
                            }
                        }
                        remainingEnergy -= MathUtils.clampToInt(energyPerDamage * damage);
                        if (remainingEnergy == 0) {
                            //Update the position that the laser is going to
                            to = from.with(axis, entity.position().get(axis));
                            break;
                        }
                        //If we have any energy left over after damaging the entity, mark that we are going to need to update the energy scale
                        updateEnergyScale = true;
                    }
                }
                if (updateEnergyScale) {
                    float energyScale = getEnergyScale(remainingEnergy);
                    if (laserEnergyScale - energyScale > 0.01) {
                        //Otherwise, send the laser between the two positions and update the energy scale
                        Vec3 entityPos = from.with(axis, entity.position().get(axis));
                        sendLaserDataToPlayers(level, new LaserParticleData(direction, (float) entityPos.distanceTo(from), laserEnergyScale), from);
                        laserEnergyScale = energyScale;
                        //Update the from position to be where the entity is
                        from = entityPos;
                        //Mark we have a new AABB we have to check against, as the beam isn't as large anymore,
                        // so it is possible some things no longer should be getting hit by it
                        adjustedAABB = getLaserBox(direction, from, to, laserEnergyScale);
                    }
                }
            }
        }
        //Tell the clients to render the laser
        sendLaserDataToPlayers(level, new LaserParticleData(direction, (float) to.distanceTo(from), laserEnergyScale), from);

        if (remainingEnergy == 0 || result.getType() == Type.MISS) {
            //If all the energy was spent on damaging entities or if we aren't actively digging a block,
            // then reset any digging progress we may have
            digging = null;
            diggingProgress = 0;
        } else {
            //Otherwise, we still have energy left that we can use
            BlockPos hitPos = result.getBlockPos();
            if (!hitPos.equals(digging)) {
                digging = result.getType() == Type.MISS ? null : hitPos;
                diggingProgress = 0;
            }
            ILaserReceptor laserReceptor = WorldUtils.getCapability(level, Capabilities.LASER_RECEPTOR, hitPos, result.getDirection());
            if (laserReceptor != null && !laserReceptor.canLasersDig()) {
                //Give the energy to the receptor
                remainingEnergy -= laserReceptor.receiveLaserEnergy(remainingEnergy, transaction);
            } else {
                //Otherwise, make progress on breaking the block
                BlockState hitState = level.getBlockState(hitPos);
                float hardness = hitState.getDestroySpeed(level, hitPos);
                if (hardness >= 0) {
                    diggingProgress += remainingEnergy;
                    if (diggingProgress >= hardness * MekanismConfig.general.laserEnergyPerHardness.get()) {
                        if (MekanismConfig.general.aestheticWorldDamage.get()) {
                            withFakePlayer(level, to.x(), to.y(), to.z(), hitPos, hitState, result.getDirection(), transaction);
                        }
                        diggingProgress = 0;
                    } else {
                        //Note: If this has a significant network performance, we could instead convert this to a start/stop packet
                        PacketUtils.sendToAllTracking(new PacketHitBlockEffect(result.getBlockPos(), result.getDirection(), false), this);
                    }
                }
            }
        }
    }

@SubscribeEvent
	public void onEntityAttacked(LivingAttackEvent event) {
		if (event.getEntity().level().isClientSide)
			return;

		/*
		 * Handler for immunities and projectile deflection.
		 */

		if (event.getEntity() instanceof Player player) {
			if (player.hasEffect(EnigmaticEffects.MOLTEN_HEART) && EnigmaticEffects.MOLTEN_HEART.providesImmunity(event.getSource())) {
				event.setCanceled(true);
				return;
			}

			if (event.getSource().getDirectEntity() instanceof AbstractHurtingProjectile || event.getSource().getDirectEntity() instanceof AbstractArrow) {
				/*if (SuperpositionHandler.hasCurio(player, EnigmaticLegacy.angelBlessing) && Math.random() <= ConfigHandler.ANGEL_BLESSING_DEFLECT_CHANCE.getValue().asModifier(false)) {
					event.setCanceled(true);
					Entity arrow = event.getSource().getImmediateSource();

					if (!arrow.world.isRemote) {
						CompoundTag data = arrow.serializeNBT();
						Entity entity = arrow.getType().create(arrow.world);
						entity.deserializeNBT(data);
						entity.setUniqueId(Mth.getRandomUUID());
						entity.setPositionAndUpdate(arrow.getPosX(), arrow.getPosY(), arrow.getPosZ());
						entity.setMotion(arrow.getMotion().scale(-1.0D));

						entity.rotationYaw = arrow.rotationYaw + 180.0F;
						entity.prevRotationYaw = arrow.rotationYaw + 180.0F;

						if (entity instanceof AbstractArrow && !(entity instanceof ThrownTrident)) {
							((AbstractArrow) entity).setShooter(player);
						} else if (entity instanceof AbstractHurtingProjectile) {
							((AbstractHurtingProjectile) entity).setShooter(player);

							((AbstractHurtingProjectile) entity).accelerationX = -((AbstractHurtingProjectile) arrow).accelerationX;
							((AbstractHurtingProjectile) entity).accelerationY = -((AbstractHurtingProjectile) arrow).accelerationY;
							((AbstractHurtingProjectile) entity).accelerationZ = -((AbstractHurtingProjectile) arrow).accelerationZ;
						}

						arrow.remove();
						arrow.forceSetPosition(0, 0, 0);

						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getPosX(), player.getPosY(), player.getPosZ(), 64.0D, player.world.getDimensionKey())), new PacketForceArrowRotations(arrow.getEntityId(), arrow.rotationYaw, arrow.rotationPitch, arrow.getMotion().x, arrow.getMotion().y, arrow.getMotion().z));

						//player.world.playSound(null, player.getPosition(), SoundEvents.ENTITY_ENDER_PEARL_THROW, SoundSource.PLAYERS, 1.0F, 0.95F + (float) (Math.random() * 0.1D));
						player.world.playSound(null, player.getPosition(), EnigmaticLegacy.DEFLECT, SoundSource.PLAYERS, 1.0F, 0.95F + (float) (Math.random() * 0.1D));

						player.world.addEntity(entity);
					}

				}*/
			}

			if (event.getSource().is(DamageTypes.FALL)) {
				if (EnigmaticItems.ENIGMATIC_AMULET.hasColor(player, AmuletColor.MAGENTA) && event.getAmount() <= 2.0f) {
					event.setCanceled(true);
				}
			}

			List<ItemStack> advancedCurios = SuperpositionHandler.getAdvancedCurios(player);
			if (advancedCurios.size() > 0) {
				for (ItemStack advancedCurioStack : advancedCurios) {
					ItemSpellstoneCurio advancedCurio = (ItemSpellstoneCurio) advancedCurioStack.getItem();

					if (advancedCurio.immunityList.stream().anyMatch(event.getSource()::is)) {
						event.setCanceled(true);
					}

					/*
					 * This used to heal player from debuff damage if they have Pearl of the Void.
					 * Removed in 2.5.0 Release.
					 */

					/*
					if (advancedCurio == EnigmaticLegacy.voidPearl && EnigmaticLegacy.voidPearl.healList.contains(event.getSource().damageType)) {
						player.heal(event.getAmount());
						event.setCanceled(true);
					}
					 */
				}
			}

			/*
			 * Handler for Eye of the Nebula dodge effect.
			 */

			if (SuperpositionHandler.hasCurio(player, EnigmaticItems.EYE_OF_NEBULA) && !event.isCanceled()) {
				if (EyeOfNebula.dodgeProbability.getValue().roll() && player.invulnerableTime <= 10 && event.getSource().getEntity() instanceof LivingEntity) {

					for (int counter = 0; counter <= 32; counter++) {
						if (SuperpositionHandler.validTeleportRandomly(player, player.level(), (int) EyeOfNebula.dodgeRange.getValue())) {
							break;
						}
					}

					player.invulnerableTime = 20;
					event.setCanceled(true);
				}
			}

			if (!player.getAbilities().invulnerable && player.getEffect(MobEffects.FIRE_RESISTANCE) == null)
				if (SuperpositionHandler.hasCurio(player, EnigmaticItems.BLAZING_CORE) && !event.isCanceled() && event.getSource().is(DamageTypes.LAVA)) {
					TransientPlayerData data = TransientPlayerData.get(player);

					if (data.getFireImmunityTimer() < data.getFireImmunityTimerCap()) {
						if (data.getFireImmunityTimer() < (data.getFireImmunityTimerCap() - (data.getFireDiff()))) {
							event.setCanceled(true);
						}

						if (data.getFireImmunityTimer() == 0 && !player.level().isClientSide) {
							player.level().playSound(null, player.blockPosition(), SoundEvents.LAVA_EXTINGUISH, SoundSource.PLAYERS, 1.0F, 0.5F + (THEY_SEE_ME_ROLLIN.nextFloat() * 0.5F));
							EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(player.getX(), player.getY(), player.getZ(), 32, player.level().dimension())), new PacketWitherParticles(player.getX(), player.getY(0.25D), player.getZ(), 8, false, 1));
						}

						data.setFireImmunityTimer(data.getFireImmunityTimer()+200);
					}
				}

		} else if (event.getSource().getDirectEntity() instanceof Player && event.getSource().is(DamageTypes.PLAYER_ATTACK)) {
			Player player = (Player) event.getSource().getDirectEntity();

			/*
			 * Handler for triggering Extradimensional Eye's effects when player left-clicks
			 * (or, more technically correct, directly attacks) the entity with the Eye in
			 * main hand.
			 */

			if (player.getMainHandItem() != null && player.getMainHandItem().getItem() == EnigmaticItems.EXTRADIMENSIONAL_EYE)
				if (ItemNBTHelper.verifyExistance(player.getMainHandItem(), "BoundDimension"))
					if (ItemNBTHelper.getString(player.getMainHandItem(), "BoundDimension", "minecraft:overworld").equals(event.getEntity().level().dimension().location().toString())) {
						event.setCanceled(true);
						ItemStack stack = player.getMainHandItem();

						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(event.getEntity().getX(), event.getEntity().getY(), event.getEntity().getZ(), 128, event.getEntity().level().dimension())), new PacketPortalParticles(event.getEntity().getX(), event.getEntity().getY() + (event.getEntity().getBbHeight() / 2), event.getEntity().getZ(), 96, 1.5D, false));

						event.getEntity().level().playSound(null, event.getEntity().blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));
						event.getEntity().teleportTo(ItemNBTHelper.getDouble(stack, "BoundX", 0D), ItemNBTHelper.getDouble(stack, "BoundY", 0D), ItemNBTHelper.getDouble(stack, "BoundZ", 0D));
						event.getEntity().level().playSound(null, event.getEntity().blockPosition(), SoundEvents.ENDERMAN_TELEPORT, SoundSource.PLAYERS, 1.0F, (float) (0.8F + (Math.random() * 0.2)));

						EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(event.getEntity().getX(), event.getEntity().getY(), event.getEntity().getZ(), 128, event.getEntity().level().dimension())), new PacketRecallParticles(event.getEntity().getX(), event.getEntity().getY() + (event.getEntity().getBbHeight() / 2), event.getEntity().getZ(), 48, false));

						if (!player.getAbilities().instabuild) {
							stack.shrink(1);
						}
					}

			float knockbackPower = 1F;

			if (player.getMainHandItem() != null && player.getMainHandItem().getItem() == EnigmaticItems.THE_TWIST && SuperpositionHandler.isTheCursedOne(player)) {
				knockbackPower += TheTwist.knockbackBonus.getValue().asModifier(false);
			} else if (player.getMainHandItem() != null && player.getMainHandItem().getItem() == EnigmaticItems.THE_INFINITUM && SuperpositionHandler.isTheWorthyOne(player)) {
				knockbackPower += TheInfinitum.knockbackBonus.getValue().asModifier(false);
			} else if (player.getMainHandItem() != null && player.getMainHandItem().is(EnigmaticItems.ENDER_SLAYER) && SuperpositionHandler.isTheCursedOne(player)) {
				if (EnigmaticItems.ENDER_SLAYER.isEndDweller(event.getEntity())) {
					knockbackPower += EnderSlayer.endKnockbackBonus.getValue().asModifier(false);
				}
			}

			if (event.getEntity() instanceof Player victim) {
				if (SuperpositionHandler.hasArchitectsFavor(player)) {
					if (!SuperpositionHandler.isTheBlessedOne(victim)) {
						knockbackPower += CosmicScroll.unchosenKnockbackBonus.getValue().asModifier(false);
					}
				}
			}

			if (knockbackPower > 1) {
				KNOCKBACK_THAT_BASTARD.put(event.getEntity(), (event.getEntity() instanceof Phantom ? (knockbackPower*1.5F) : knockbackPower));
			}
		}

		if (event.getEntity() instanceof Animal animal && event.getSource().getEntity() instanceof Player player) {
			if (SuperpositionHandler.hasItem(player, EnigmaticItems.ANIMAL_GUIDEBOOK)) {
				if (EnigmaticItems.ANIMAL_GUIDEBOOK.isProtectedAnimal(animal)) {
					event.setCanceled(true);

					if (animal.getTarget() == player) {
						event.setCanceled(false);
					} else {
						for (WrappedGoal goal : animal.targetSelector.getAvailableGoals())
							if (goal.getGoal() instanceof TargetGoal targetGoal) {
								if (targetGoal.targetMob == player) {
									event.setCanceled(false);
								}
							}
					}

					Brain<?> brain = animal.getBrain();

					if (brain != null) {
						try {
							var memory = brain.hasMemoryValue(MemoryModuleType.ATTACK_TARGET)
									? brain.getMemory(MemoryModuleType.ATTACK_TARGET) : Optional.empty();
							if (memory.isPresent() && memory.get() == player) {
								event.setCanceled(false);
							}
						} catch (NullPointerException ex) {
							// I don't get why it happens here but it does lol
						}
					}
				}
			}
		}
	}

@Override
	public void execute(MinecraftServer server, ICommandSender sender, String[] arguments) throws CommandException{

		if(arguments.length < 1){
			throw new WrongUsageException("commands." + Wizardry.MODID + ":cast.usage", Wizardry.settings.castCommandName);
		}else{

			// ===== Parameter retrieval =====

			int i = 0;

			EntityPlayerMP caster = null;
			Vec3d origin = null;
			EnumFacing direction = null;

			try{
				caster = getCommandSenderAsPlayer(sender);
			}catch (PlayerNotFoundException exception){
				// Nothing here since the player specifying is done later, I just don't want it to throw an exception
				// here.
			}

			Spell spell = Spell.get(arguments[i++]);

			if(spell == null){
				throw new NumberInvalidException("commands." + Wizardry.MODID + ":cast.not_found", arguments[i - 1]);
			}

			boolean castAsOtherPlayer = false;

			if(i + 3 < arguments.length){

				Vec3d vec3d = sender.getPositionVector();
				CoordinateArg x = parseCoordinate(vec3d.x, arguments[i++], true);
				CoordinateArg y = parseCoordinate(vec3d.y, arguments[i++], 0, 256, false);
				CoordinateArg z = parseCoordinate(vec3d.z, arguments[i++], true);

				origin = new Vec3d(x.getResult(), y.getResult(), z.getResult());

				direction = EnumFacing.byName(arguments[i++]);
				if(direction == null) throw new NumberInvalidException("commands." + Wizardry.MODID + ":cast.invalid_direction", arguments[i - 1]);

			}else if(i < arguments.length){
				try{
					// If the second argument is a player and is not the player that gave the command, the spell is cast
					// as the given player rather than the command sender, and there is a different chat readout.
					EntityPlayerMP entityplayermp = getPlayer(server, sender, arguments[i++]);
					if(caster != entityplayermp){
						castAsOtherPlayer = true;
						caster = entityplayermp;
					}
				}catch (PlayerNotFoundException exception){
					// If no player was found, rather than give an error it simply assumes the player was unspecified.
					i--;
				}
			}

			// If, after this point, the player is still null, the sender must be a command block or the console and the
			// player must not have been specified, meaning an exception should be thrown.
			if(caster == null && origin == null)
				throw new PlayerNotFoundException("commands." + Wizardry.MODID + ":cast.origin_not_specified");

			int duration = DEFAULT_CASTING_DURATION;
			int seconds = duration/20;

			if(spell.isContinuous){

				if(i >= arguments.length) throw new CommandException("commands." + Wizardry.MODID + ":cast.duration_not_specified");

				try{
					seconds = parseInt(arguments[i++]);
				}catch(NumberInvalidException e){
					// If no duration was found, assume it was unspecified
					i--;
				}

				if(seconds < MIN_CASTING_DURATION){
					throw new NumberInvalidException("commands.generic.num.tooSmall", seconds, MIN_CASTING_DURATION);
				}else if(seconds > MAX_CASTING_DURATION){
					throw new NumberInvalidException("commands.generic.num.tooBig", seconds, MAX_CASTING_DURATION);
				}

				duration = seconds * 20;
			}

			SpellModifiers modifiers = new SpellModifiers();

			if(i < arguments.length){

				// Copied from CommandGive. Why it doesn't just use arguments[i] itself I don't know.
				String nbt = getChatComponentFromNthArg(sender, arguments, i++).getUnformattedText();

				try{
					modifiers = SpellModifiers.fromNBT(JsonToNBT.getTagFromJson(nbt));
				}catch (NBTException nbtexception){
					throw new CommandException("commands." + Wizardry.MODID + ":cast.tag_error", nbtexception.getMessage());
				}

				for(float multiplier : modifiers.getModifiers().values()){
					if(multiplier < 0){
						throw new NumberInvalidException("commands.generic.double.tooSmall", multiplier, 0);
					}else if(multiplier > Wizardry.settings.maxSpellCommandMultiplier){
						throw new NumberInvalidException("commands.generic.double.tooBig", multiplier,
								Wizardry.settings.maxSpellCommandMultiplier);
					}
				}

			}

			// ===== Spell casting =====

			if(origin != null){ // Positional

				World world = sender.getEntityWorld();

				// If anything stops the spell working at this point, nothing else happens.
				if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.COMMAND, spell, world,
						origin.x, origin.y, origin.z, direction, modifiers))){
					if(server.sendCommandFeedback()) displayFailMessage(sender, spell);
					return;
				}

				if(spell.isContinuous){
					// We need not query Spell#canBeCastByDispensers since with commands there's no difference between
					// a spell that can't be cast positionally and one that can be cast positionally but fails
					if(spell.cast(world, origin.x, origin.y, origin.z, direction, 0, duration, modifiers)){

						MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.COMMAND, spell, world, origin.x, origin.y, origin.z, direction, modifiers));

						SpellEmitter.add(spell, world, origin.x, origin.y, origin.z, direction, duration, modifiers);
						IMessage msg = new PacketCastSpellAtPos.Message(origin, direction, spell, modifiers, duration);
						WizardryPacketHandler.net.sendToDimension(msg, world.provider.getDimension());

						if(server.sendCommandFeedback()){
							sender.sendMessage(new TextComponentTranslation("commands." + Wizardry.MODID + ":cast.success_position_continuous",
									spell.getNameForTranslationFormatted(), origin.x, origin.y, origin.z, seconds));
						}

						return;
					}

				}else{

					if(spell.cast(world, origin.x, origin.y, origin.z, direction, 0, -1, modifiers)){

						MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.COMMAND, spell, world, origin.x, origin.y, origin.z, direction, modifiers));

						if(spell.requiresPacket()){
							// Sends a packet to all players in dimension to tell them to spawn particles.
							// Only sent if the spell succeeded, because if the spell failed, you wouldn't
							// need to spawn any particles!
							IMessage msg = new PacketCastSpellAtPos.Message(origin, direction, spell, modifiers);
							WizardryPacketHandler.net.sendToDimension(msg, world.provider.getDimension());
						}

						if(server.sendCommandFeedback()){
							sender.sendMessage(new TextComponentTranslation("commands." + Wizardry.MODID + ":cast.success_position",
									spell.getNameForTranslationFormatted(), origin.x, origin.y, origin.z));
						}

						return;
					}
				}

			}else{ // Player-based

				// If anything stops the spell working at this point, nothing else happens.
				if(MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Pre(Source.COMMAND, spell, caster, modifiers))){
					if(server.sendCommandFeedback()) displayFailMessage(sender, spell);
					return;
				}

				if(spell.isContinuous){

					WizardData data = WizardData.get(caster);

					// Events/packets for continuous spell casting via commands are dealt with in WizardData.

					if(data != null){
						if(data.isCasting()){
							data.stopCastingContinuousSpell(); // I think on balance this is quite a nice feature to leave in
						}else{

							data.startCastingContinuousSpell(spell, modifiers, duration);

							if(server.sendCommandFeedback()){
								if(castAsOtherPlayer){
									sender.sendMessage(
											new TextComponentTranslation("commands." + Wizardry.MODID + ":cast.success_remote_continuous",
													spell.getNameForTranslationFormatted(), caster.getName(), seconds));
								}else{
									sender.sendMessage(new TextComponentTranslation("commands." + Wizardry.MODID + ":cast.success_continuous",
											spell.getNameForTranslationFormatted(), seconds));
								}
							}
						}

						return;
					}

				}else{

					if(spell.cast(caster.world, caster, EnumHand.MAIN_HAND, 0, modifiers)){

						MinecraftForge.EVENT_BUS.post(new SpellCastEvent.Post(Source.COMMAND, spell, caster, modifiers));

						if(spell.requiresPacket()){
							// Sends a packet to all players in dimension to tell them to spawn particles.
							// Only sent if the spell succeeded, because if the spell failed, you wouldn't
							// need to spawn any particles!
							IMessage msg = new PacketCastSpell.Message(caster.getEntityId(), null, spell, modifiers);
							WizardryPacketHandler.net.sendToDimension(msg, caster.world.provider.getDimension());
						}

						if(server.sendCommandFeedback()){
							if(castAsOtherPlayer){
								sender.sendMessage(new TextComponentTranslation("commands." + Wizardry.MODID + ":cast.success_remote",
										spell.getNameForTranslationFormatted(), caster.getName()));
							}else{
								sender.sendMessage(new TextComponentTranslation("commands." + Wizardry.MODID + ":cast.success",
										spell.getNameForTranslationFormatted()));
							}
						}

						return;
					}
				}
			}

			if(server.sendCommandFeedback()) displayFailMessage(sender, spell);
		}
	}

