public void updateDragonServer() {
        // Update dragon rider
        dragon.updateRider();

        // Update dragon pitch
        dragon.updatePitch(dragon.yo - dragon.getY());

        if (dragon.lookingForRoostAIFlag && dragon.getLastHurtByMob() != null || dragon.isSleeping()) {
            dragon.lookingForRoostAIFlag = false;
        }
        if (IafConfig.doDragonsSleep && !dragon.isSleeping() && !dragon.isTimeToWake() && dragon.getPassengers().isEmpty() && this.dragon.getCommand() != 2) {
            if (dragon.hasHomePosition
                && dragon.getRestrictCenter() != null
                && DragonUtils.isInHomeDimension(dragon)
                && dragon.getDistanceSquared(Vec3.atCenterOf(dragon.getRestrictCenter())) > dragon.getBbWidth() * 10
                && this.dragon.getCommand() != 2 && this.dragon.getCommand() != 1) {
                dragon.lookingForRoostAIFlag = true;
            } else {
                dragon.lookingForRoostAIFlag = false;
                if ((/* Avoid immediately sleeping after killing the target */ dragon.level.getGameTime() - ticksAfterClearingTarget >= 20) && !dragon.isInWater() && dragon.isOnGround() && !dragon.isFlying() && !dragon.isHovering() && dragon.getTarget() == null) {
                    dragon.setInSittingPose(true);
                }
            }
        } else {
            dragon.lookingForRoostAIFlag = false;
        }
        if (dragon.isSleeping() && (dragon.isFlying() || dragon.isHovering() || dragon.isInWater() || (dragon.level.canSeeSkyFromBelowWater(dragon.blockPosition()) && dragon.isTimeToWake() && !dragon.isTame() || dragon.isTimeToWake() && dragon.isTame()) || dragon.getTarget() != null || !dragon.getPassengers().isEmpty())) {
            dragon.setInSittingPose(false);
        }
        if (dragon.isOrderedToSit() && dragon.getControllingPassenger() != null) {
            dragon.setOrderedToSit(false);
        }
        if (dragon.blockBreakCounter <= 0) {
            dragon.blockBreakCounter = IafConfig.dragonBreakBlockCooldown;
        }
        dragon.updateBurnTarget();
        if (dragon.isOrderedToSit()) {
            if (dragon.getCommand() != 1 || dragon.getControllingPassenger() != null)
                dragon.setOrderedToSit(false);
        } else {
            if (dragon.getCommand() == 1 && dragon.getControllingPassenger() == null)
                dragon.setOrderedToSit(true);
        }
        if (dragon.isOrderedToSit()) {
            dragon.getNavigation().stop();
        }
        if (dragon.isInLove()) {
            dragon.level.broadcastEntityEvent(dragon, (byte) 18);
        }
        if ((int) dragon.xo == (int) dragon.getX() && (int) dragon.zo == (int) dragon.getZ()) {
            dragon.ticksStill++;
        } else {
            dragon.ticksStill = 0;
        }
        if (dragon.getControllingPassenger() == null && dragon.isTackling() && !dragon.isFlying() && dragon.isOnGround()) {
            dragon.tacklingTicks++;
            if (dragon.tacklingTicks == 40) {
                dragon.tacklingTicks = 0;
                dragon.setTackling(false);
                dragon.setFlying(false);
            }
        }
        if (dragon.getRandom().nextInt(500) == 0 && !dragon.isModelDead() && !dragon.isSleeping()) {
            dragon.roar();
        }
        // In air tackle attack
        if (dragon.isFlying() && dragon.getTarget() != null) {
            if (dragon.airAttack == IafDragonAttacks.Air.TACKLE)
                dragon.setTackling(true);

            if (dragon.isTackling()) {
                if (dragon.getBoundingBox().expandTowards(2.0D, 2.0D, 2.0D).intersects(dragon.getTarget().getBoundingBox())) {
                    dragon.usingGroundAttack = true;
                    dragon.randomizeAttacks();
                    attackTarget(dragon.getTarget(), null, dragon.getDragonStage() * 3);
                    dragon.setFlying(false);
                    dragon.setHovering(false);
                }
            }
        }

        if (dragon.getControllingPassenger() == null && dragon.isTackling() && (dragon.getTarget() == null || dragon.airAttack != IafDragonAttacks.Air.TACKLE)) {
            dragon.setTackling(false);
            dragon.randomizeAttacks();
        }
        if (dragon.isPassenger()) {
            dragon.setFlying(false);
            dragon.setHovering(false);
            dragon.setInSittingPose(false);
        }
        if (dragon.isFlying() && dragon.tickCount % 40 == 0 || dragon.isFlying() && dragon.isSleeping()) {
            dragon.setInSittingPose(false);
        }
        if (!dragon.canMove()) {
            if (dragon.getTarget() != null) {
                dragon.setTarget(null);
                ticksAfterClearingTarget = dragon.level.getGameTime();
            }
            dragon.getNavigation().stop();
        }
        if (!dragon.isTame()) {
            dragon.updateCheckPlayer();
        }
        if (dragon.isModelDead() && (dragon.isFlying() || dragon.isHovering())) {
            dragon.setFlying(false);
            dragon.setHovering(false);
        }
        if (dragon.getControllingPassenger() == null) {
            if ((dragon.useFlyingPathFinder() || dragon.isHovering()) && dragon.navigatorType != 1) {
                dragon.switchNavigator(1);
            }
        } else {
            if ((dragon.useFlyingPathFinder() || dragon.isHovering()) && dragon.navigatorType != 2) {
                dragon.switchNavigator(2);
            }
        }
        if (dragon.getControllingPassenger() == null && !dragon.useFlyingPathFinder() && !dragon.isHovering() && dragon.navigatorType != 0) {
            dragon.switchNavigator(0);
        }
        // Dragon landing
        if (dragon.getControllingPassenger() == null && !dragon.isOverAir() && dragon.doesWantToLand() && (dragon.isFlying() || dragon.isHovering()) && !dragon.isInWater()) {
            dragon.setFlying(false);
            dragon.setHovering(false);
        }
        if (dragon.isHovering()) {
            if (dragon.isFlying() && dragon.flyTicks > 40) {
                dragon.setHovering(false);
                dragon.setFlying(true);
            }
            dragon.hoverTicks++;
        } else {
            dragon.hoverTicks = 0;
        }
        if (dragon.isHovering() && !dragon.isFlying()) {
            if (dragon.isSleeping()) {
                dragon.setHovering(false);
            }
            // Slowly land the hovering dragon
            if (dragon.getControllingPassenger() == null && dragon.doesWantToLand() && !dragon.isOnGround() && !dragon.isInWater()) {
                dragon.setDeltaMovement(dragon.getDeltaMovement().add(0, -0.25, 0));
            } else {
                if ((dragon.getControllingPassenger() == null || dragon.getControllingPassenger() instanceof EntityDreadQueen) && !dragon.isBeyondHeight()) {
                    double up = dragon.isInWater() ? 0.12D : 0.08D;
                    dragon.setDeltaMovement(dragon.getDeltaMovement().add(0, up, 0));
                }
                if (dragon.hoverTicks > 40) {
                    dragon.setHovering(false);
                    dragon.setFlying(true);
                    dragon.flyHovering = 0;
                    dragon.hoverTicks = 0;
                    dragon.flyTicks = 0;
                }
            }
        }
        if (dragon.isSleeping()) {
            dragon.getNavigation().stop();
        }
        if ((dragon.isOnGround() || dragon.isInWater()) && dragon.flyTicks != 0) {
            dragon.flyTicks = 0;
        }
        if (dragon.isAllowedToTriggerFlight() && dragon.isFlying() && dragon.doesWantToLand()) {
            dragon.setFlying(false);
            dragon.setHovering(dragon.isOverAir());
            if (!dragon.isOverAir()) {
                dragon.flyTicks = 0;
                dragon.setFlying(false);
            }
        }
        if (dragon.isFlying()) {
            dragon.flyTicks++;
        }
        if ((dragon.isHovering() || dragon.isFlying()) && dragon.isSleeping()) {
            dragon.setFlying(false);
            dragon.setHovering(false);
        }
        if (!dragon.isFlying() && !dragon.isHovering()) {
            if (dragon.isAllowedToTriggerFlight() || dragon.getY() < dragon.level.getMinBuildHeight()) {
                if (dragon.getRandom().nextInt(dragon.getFlightChancePerTick()) == 0 || dragon.getY() < dragon.level.getMinBuildHeight() || dragon.getTarget() != null && Math.abs(dragon.getTarget().getY() - dragon.getY()) > 5 || dragon.isInWater() && !dragon.isIceInWater()) {
                    dragon.setHovering(true);
                    dragon.setInSittingPose(false);
                    dragon.setOrderedToSit(false);
                    dragon.flyHovering = 0;
                    dragon.hoverTicks = 0;
                    dragon.flyTicks = 0;
                }
            }
        }
        if (dragon.getTarget() != null) {
            if (!DragonUtils.isAlive(dragon.getTarget())) {
                dragon.setTarget(null);
                ticksAfterClearingTarget = dragon.level.getGameTime();
            }
        }
        if (!dragon.isAgingDisabled()) {
            dragon.setAgeInTicks(dragon.getAgeInTicks() + 1);
            if (dragon.getAgeInTicks() % 24000 == 0) {
                dragon.updateAttributes();
                dragon.growDragon(0);
            }
        }
        if (dragon.tickCount % IafConfig.dragonHungerTickRate == 0 && IafConfig.dragonHungerTickRate > 0) {
            if (dragon.getHunger() > 0) {
                dragon.setHunger(dragon.getHunger() - 1);
            }
        }
        if ((dragon.groundAttack == IafDragonAttacks.Ground.FIRE) && dragon.getDragonStage() < 2) {
            dragon.usingGroundAttack = true;
            dragon.randomizeAttacks();
            dragon.playSound(dragon.getBabyFireSound(), 1, 1);
        }
        if (dragon.isBreathingFire()) {
            if(dragon.isSleeping() || dragon.isModelDead()){
                dragon.setBreathingFire(false);
                dragon.randomizeAttacks();
                dragon.fireTicks = 0;
            }
            if (dragon.burningTarget == null) {
                if (dragon.fireTicks > dragon.getDragonStage() * 25 || dragon.getOwner() != null && dragon.getPassengers().contains(dragon.getOwner()) && dragon.fireStopTicks <= 0) {
                    dragon.setBreathingFire(false);
                    dragon.randomizeAttacks();
                    dragon.fireTicks = 0;
                }
            }

            if (dragon.fireStopTicks > 0 && dragon.getOwner() != null && dragon.getPassengers().contains(dragon.getOwner())) {
                dragon.fireStopTicks--;
            }
        }
        if (dragon.isFlying()) {
            if (dragon.getTarget() != null && dragon.getBoundingBox().expandTowards(3.0F, 3.0F, 3.0F).intersects(dragon.getTarget().getBoundingBox())) {
                dragon.doHurtTarget(dragon.getTarget());
            }
            if (dragon.airAttack == IafDragonAttacks.Air.TACKLE && (dragon.horizontalCollision || dragon.isOnGround())) {
                dragon.usingGroundAttack = true;
                if (dragon.getControllingPassenger() == null) {
                    dragon.setFlying(false);
                    dragon.setHovering(false);
                }
            }
            if (dragon.usingGroundAttack) {
                dragon.airAttack = IafDragonAttacks.Air.TACKLE;
            }
            if (dragon.airAttack == IafDragonAttacks.Air.TACKLE && dragon.getTarget() != null && dragon.isTargetBlocked(dragon.getTarget().position())) {
                dragon.randomizeAttacks();
            }
        }

    }

@Override
	public void render(
			IMultiblockContext<State> ctx,
			float partialTicks,
			PoseStack matrixStack,
			MultiBufferSource bufferIn,
			int combinedLightIn,
			int combinedOverlayIn
	)
	{
		final BlockRenderDispatcher blockRenderer = Minecraft.getInstance().getBlockRenderer();
		BakedModel model = DYNAMIC.get();
		final State state = ctx.getState();

		//Item Displacement
		float[][] itemDisplays = new float[state.processor.getQueueSize()][];
		//Animations
		float drill = 0;
		float lift = 0;
		float press = 0;
		float liftPress = 0;

		Level level = ctx.getLevel().getRawLevel();
		for(int i = 0; i < itemDisplays.length; i++)
		{
			MultiblockProcess<?, ?> process = state.processor.getQueue().get(i);
			if(process==null||process.processTick <= 0||process.processTick==process.getMaxTicks(level))
				continue;
			//+partialTicks
			float processTimer = ((float)process.processTick)/process.getMaxTicks(level)*180;
			if(processTimer <= 9)
				continue;

			float itemX = -1;
			float itemY = -.34375f;
			float itemZ = -.9375f;
			float itemAngle = Mth.HALF_PI;

			if(processTimer <= 24)//slide
			{
				itemAngle = 67.5f * Mth.PI / 180;
				if(processTimer <= 19)
				{
					itemZ += .25+(19-processTimer)/10f*.5f;
					itemY += .25+(19-processTimer)/10f*.21875f;
				}
				else
				{
					itemZ += (24-processTimer)/5f*.25f;
					itemY += (24-processTimer)/5f*.25f;
				}
			}
			else if(processTimer <= 40)
			{
				itemX += (processTimer-24)/16f;
			}
			else if(processTimer <= 100)
			{
				itemX += 1;
				float drillStep = 0;
				if(processTimer <= 60)
				{
					lift = (processTimer-40)/20f*.3125f;
					drillStep = 4+(60-processTimer)*4;
				}
				else if(processTimer <= 80)
				{
					lift = .3125f;
					drillStep = 4;
				}
				else
				{
					lift = (100-processTimer)/20f*.3125f;
					drillStep = 4+(processTimer-80)*4;
				}
				if(drillStep > 0)
					drill = processTimer%drillStep/drillStep*2 * Mth.PI;
				itemY += Math.max(0, lift-.0625);
			}
			else if(processTimer <= 116)
			{
				itemX += 1;
				itemZ += (processTimer-100)/16f;
			}
			else if(processTimer <= 132)
			{
				itemX += 1+(processTimer-116)/16f;
				itemZ += 1;
			}
			else if(processTimer <= 172)
			{
				itemX += 2;
				itemZ += 1;
				if(processTimer <= 142)
					press = (processTimer-132)/10f;
				else if(processTimer <= 162)
					press = 1;
				else
					press = (172-processTimer)/10f;
				liftPress = press*.0625f;
				itemY += liftPress;
			}
			else if(processTimer <= 180)
			{
				itemX += 2+(processTimer-172)/16f;
				itemZ += 1;
			}
			itemDisplays[i] = new float[]{processTimer, itemX, itemY, itemZ, itemAngle};

		}

		final MultiblockOrientation orientation = ctx.getLevel().getOrientation();
		//Outer GL Wrapping, initial translation
		matrixStack.pushPose();
		bufferIn = BERenderUtils.mirror(orientation, matrixStack, bufferIn);
		Direction facing = orientation.front();
		if(orientation.mirrored())
		{
			if(facing.getAxis()==Axis.Z)
				matrixStack.translate(-1, 0, 0);
			else
				matrixStack.translate(0, 0, -1);
		}
		rotateForFacing(matrixStack, facing);
		matrixStack.translate(0.5, 0.5, 0.5);

		matrixStack.pushPose();
		ItemStack blueprintStack = state.inventory.getStackInSlot(AutoWorkbenchLogic.BLUEPRINT_SLOT);
		if(!blueprintStack.isEmpty())
			renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "blueprint");


		matrixStack.translate(0, lift, 0);
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "lift");
		matrixStack.translate(0, -lift, 0);

		float tx = 0;
		float tz = -.9375f;
		matrixStack.pushPose();
		matrixStack.translate(tx, 0, tz);
		matrixStack.mulPose(new Quaternionf().rotateXYZ(0, drill, 0));
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "drill");
		matrixStack.popPose();

		tx = 0;
		tz = -.59375f;
		matrixStack.pushPose();
		matrixStack.translate(tx, -.21875, tz);
		matrixStack.mulPose(new Quaternionf().rotateXYZ(press*Mth.HALF_PI, 0, 0));
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "press");
		matrixStack.popPose();

		matrixStack.translate(0, liftPress, 0);
		renderModelPart(matrixStack, blockRenderer, bufferIn, model, combinedLightIn, combinedOverlayIn, "pressLift");

		matrixStack.popPose();

		//DRAW ITEMS HERE
		for(int i = 0; i < itemDisplays.length; i++)
			if(itemDisplays[i]!=null)
			{
				MultiblockProcess<?, ?> process = state.processor.getQueue().get(i);
				if(!(process instanceof MultiblockProcessInWorld<?> inWorld))
					continue;

				float scale = .3125f;
				List<ItemStack> dList = inWorld.getDisplayItem(level);
				if(!dList.isEmpty())
					if(dList.size() < 2)
					{
						matrixStack.pushPose();
						matrixStack.translate(itemDisplays[i][1], itemDisplays[i][2], itemDisplays[i][3]);
						matrixStack.mulPose(new Quaternionf().rotateXYZ(itemDisplays[i][4], 0, 0));
						matrixStack.scale(scale, scale, .5f);
						ClientUtils.mc().getItemRenderer().renderStatic(
								dList.get(0), ItemDisplayContext.FIXED,
								combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
								level, 0
						);
						matrixStack.popPose();
					}
					else
					{
						int size = dList.size();
						int lines = (int)Math.ceil(size/2f);
						float spacer = (lines-1)*.234375f;
						for(int d = 0; d < size; d++)
						{
							float oX = (size > 2?-.3125f: 0)+(lines-d/2)*.0625f+d%2*.3125f;
							float oZ = -spacer/2f+d/2*.234375f;
							float oY = 0;

							float localItemX = itemDisplays[i][1]+oX;
							float localItemY = itemDisplays[i][2]+oY;
							float localItemZ = itemDisplays[i][3]+oZ;
							float subProcess = itemDisplays[i][0]-d/2*4;
							float localAngle = itemDisplays[i][4];
							if(subProcess <= 24)//slide
							{
								localAngle = 67.5f;
								if(subProcess <= 19)
								{
									localItemZ = -1+.25f+(19-subProcess)/10f*.5f;
									localItemY = -.34375f+.25f+(19-subProcess)/10f*.21875f;
								}
								else
								{
									localItemZ = -1+(oZ-(24-subProcess)/5f*oZ);
									localItemY = -.34375f+(24-subProcess)/5f*.25f;
								}
							}
							matrixStack.pushPose();
							matrixStack.translate(localItemX, localItemY, localItemZ);
							matrixStack.mulPose(new Quaternionf().rotateXYZ((float)Math.toRadians(localAngle), 0, 0));
							matrixStack.scale(scale, scale, .5f);
							ClientUtils.mc().getItemRenderer().renderStatic(
									dList.get(d), ItemDisplayContext.FIXED,
									combinedLightIn, combinedOverlayIn, matrixStack, bufferIn,
									level, 0
							);
							matrixStack.popPose();
						}
					}
			}

		//Blueprint
		double playerDistanceSq = ClientUtils.mc().player.distanceToSqr(Vec3.atCenterOf(
				ctx.getLevel().toAbsolute(IEMultiblockLogic.AUTO_WORKBENCH.masterPosInMB())
		));

		if(!blueprintStack.isEmpty()&&playerDistanceSq < 1000)
		{
			List<RecipeHolder<BlueprintCraftingRecipe>> recipes = BlueprintCraftingRecipe.findRecipes(level, IEApiDataComponents.getBlueprintType(blueprintStack));
			BlueprintCraftingRecipe recipe = (state.selectedRecipe < 0||state.selectedRecipe >= recipes.size())?null: recipes.get(state.selectedRecipe).value();
			BlueprintLines blueprint = recipe==null?null: getBlueprintDrawable(recipe, level);
			if(blueprint!=null)
			{
				matrixStack.pushPose();
				matrixStack.translate(-.195, .125, .97);
				matrixStack.mulPose(new Quaternionf().rotateXYZ(-Mth.PI / 4, 0, 0));
				float scale = .5f/blueprint.textureScale;
				matrixStack.scale(scale, -scale, scale);
				matrixStack.translate(0.5, 0.5, 0.5);
				blueprint.draw(matrixStack, bufferIn, combinedLightIn);
				matrixStack.popPose();
			}
		}
		matrixStack.popPose();
	}

public void search(double maxDistance, double maxCost, boolean forward, ArrayList<GlobalStation> destinations, StationTest stationTest) {
		TrackGraph graph = train.graph;
		if (graph == null)
			return;

		// Cache the list of track types that the train can travel on
		Set<TrackMaterial.TrackType> validTypes = new HashSet<>();
		for (int i = 0; i < train.carriages.size(); i++) {
			Carriage carriage = train.carriages.get(i);
			if (i == 0) {
				validTypes.addAll(carriage.leadingBogey().type.getValidPathfindingTypes(carriage.leadingBogey().getStyle()));
			} else {
				validTypes.retainAll(carriage.leadingBogey().type.getValidPathfindingTypes(carriage.leadingBogey().getStyle()));
			}
			if (carriage.isOnTwoBogeys())
				validTypes.retainAll(carriage.trailingBogey().type.getValidPathfindingTypes(carriage.trailingBogey().getStyle()));
		}
		if (validTypes.isEmpty()) // if there are no valid track types, a route can't be found
			return;

		Map<TrackEdge, Integer> penalties = new IdentityHashMap<>();
		boolean costRelevant = maxCost >= 0;
		if (costRelevant) {
			for (Train otherTrain : Create.RAILWAYS.trains.values()) {
				if (otherTrain.graph != graph)
					continue;
				if (otherTrain == train)
					continue;
				int navigationPenalty = otherTrain.getNavigationPenalty();
				otherTrain.getEndpointEdges()
					.forEach(nodes -> {
						if (nodes.either(Objects::isNull))
							return;
						for (boolean flip : Iterate.trueAndFalse) {
							TrackEdge e = graph.getConnection(flip ? nodes.swap() : nodes);
							if (e == null)
								continue;
							int existing = penalties.getOrDefault(e, 0);
							penalties.put(e, existing + navigationPenalty / 2);
						}
					});
			}
		}

		TravellingPoint startingPoint = forward ? train.carriages.get(0)
			.getLeadingPoint()
			: train.carriages.get(train.carriages.size() - 1)
				.getTrailingPoint();

		Set<TrackEdge> visited = new HashSet<>();
		Map<TrackEdge, Pair<Boolean, Couple<TrackNode>>> reachedVia = new IdentityHashMap<>();
		PriorityQueue<FrontierEntry> frontier = new PriorityQueue<>();

		TrackNode initialNode1 = forward ? startingPoint.node1 : startingPoint.node2;
		TrackNode initialNode2 = forward ? startingPoint.node2 : startingPoint.node1;
		TrackEdge initialEdge = graph.getConnectionsFrom(initialNode1)
			.get(initialNode2);
		if (initialEdge == null)
			return;

		double distanceToNode2 = forward ? initialEdge.getLength() - startingPoint.position : startingPoint.position;

		int signalWeight = Mth.clamp(ticksWaitingForSignal * 2, Train.Penalties.RED_SIGNAL, 200);

		// Apply penalties to initial edge
		int initialPenalty = 0;
		if (costRelevant)
			initialPenalty += penalties.getOrDefault(initialEdge, 0);

		EdgeData initialSignalData = initialEdge.getEdgeData();
		if (initialSignalData.hasPoints()) {
			for (TrackEdgePoint point : initialSignalData.getPoints()) {
				if (point.getLocationOn(initialEdge) < initialEdge.getLength() - distanceToNode2)
					continue;
				if (costRelevant && distanceToNode2 + initialPenalty > maxCost)
					return;
				if (!point.canNavigateVia(initialNode2))
					return;
				if (point instanceof SignalBoundary signal) {
					if (signal.isForcedRed(initialNode2)) {
						initialPenalty += Train.Penalties.REDSTONE_RED_SIGNAL;
						continue;
					}
					UUID group = signal.getGroup(initialNode2);
					if (group == null)
						continue;
					SignalEdgeGroup signalEdgeGroup = Create.RAILWAYS.signalEdgeGroups.get(group);
					if (signalEdgeGroup == null)
						continue;
					if (signalEdgeGroup.isOccupiedUnless(signal)) {
						initialPenalty += signalWeight;
						signalWeight /= 2;
					}
				}
				if (point instanceof GlobalStation station) {
					Train presentTrain = station.getPresentTrain();
					boolean isOwnStation = presentTrain == train;
					if (presentTrain != null && !isOwnStation)
						initialPenalty += Train.Penalties.STATION_WITH_TRAIN;
					if (station.canApproachFrom(initialNode2) && stationTest.test(distanceToNode2, distanceToNode2 + initialPenalty, reachedVia,
							Pair.of(Couple.create(initialNode1, initialNode2), initialEdge), station))
						return;
					if (!isOwnStation)
						initialPenalty += Train.Penalties.STATION;
				}
			}
		}

		if (costRelevant && distanceToNode2 + initialPenalty > maxCost)
			return;

		frontier.add(new FrontierEntry(distanceToNode2, initialPenalty, initialNode1, initialNode2, initialEdge));

		while (!frontier.isEmpty()) {
			FrontierEntry entry = frontier.poll();
			if (!visited.add(entry.edge))
				continue;

			double distance = entry.distance;
			int penalty = entry.penalty;

			if (distance > maxDistance)
				continue;

			TrackEdge edge = entry.edge;
			TrackNode node1 = entry.node1;
			TrackNode node2 = entry.node2;

			if (entry.hasDestination) {
				EdgeData signalData = edge.getEdgeData();
				if (signalData.hasPoints()) {
					for (TrackEdgePoint point : signalData.getPoints()) {
						if (point instanceof GlobalStation station) {
							if (station.canApproachFrom(node2) && stationTest.test(distance, penalty, reachedVia,
									Pair.of(Couple.create(node1, node2), edge), station))
								return;
						}
					}
				}
			}

			List<Entry<TrackNode, TrackEdge>> validTargets = new ArrayList<>();
			Map<TrackNode, TrackEdge> connectionsFrom = graph.getConnectionsFrom(node2);
			for (Entry<TrackNode, TrackEdge> connection : connectionsFrom.entrySet()) {
				TrackNode newNode = connection.getKey();
				if (newNode == node1)
					continue;
				if (edge.canTravelTo(connection.getValue()))
					validTargets.add(connection);
			}

			if (validTargets.isEmpty())
				continue;

			Search: for (Entry<TrackNode, TrackEdge> target : validTargets) {
				if (!validTypes.contains(target.getValue().getTrackMaterial().trackType))
					continue;
				TrackNode newNode = target.getKey();
				TrackEdge newEdge = target.getValue();
				int newPenalty = penalty;
				double edgeLength = newEdge.getLength();
				double newDistance = distance + edgeLength;

				if (costRelevant)
					newPenalty += penalties.getOrDefault(newEdge, 0);

				// Apply penalty to next connected edge
				boolean hasDestination = false;
				EdgeData signalData = newEdge.getEdgeData();
				if (signalData.hasPoints()) {
					for (TrackEdgePoint point : signalData.getPoints()) {
						if (node2 == initialNode1 && point.getLocationOn(newEdge) < edgeLength - distanceToNode2)
							continue;
						if (costRelevant && newDistance + newPenalty > maxCost)
							continue Search;
						if (!point.canNavigateVia(newNode))
							continue Search;
						if (point instanceof SignalBoundary signal) {
							if (signal.isForcedRed(newNode)) {
								newPenalty += Train.Penalties.REDSTONE_RED_SIGNAL;
								continue;
							}
							UUID group = signal.getGroup(newNode);
							if (group == null)
								continue;
							SignalEdgeGroup signalEdgeGroup = Create.RAILWAYS.signalEdgeGroups.get(group);
							if (signalEdgeGroup == null)
								continue;
							if (signalEdgeGroup.isOccupiedUnless(signal)) {
								newPenalty += signalWeight;
								signalWeight /= 2;
							}
						}
						if (point instanceof GlobalStation station) {
							Train presentTrain = station.getPresentTrain();
							boolean isOwnStation = presentTrain == train;
							if (presentTrain != null && !isOwnStation)
								newPenalty += Train.Penalties.STATION_WITH_TRAIN;
							if (station.canApproachFrom(newNode) && stationTest.test(newDistance, newDistance + newPenalty, reachedVia,
									Pair.of(Couple.create(node2, newNode), newEdge), station)) {
								hasDestination = true;
								break;
							}
							if (!isOwnStation)
								newPenalty += Train.Penalties.STATION;
						}
					}
				}

				if (costRelevant && newDistance + newPenalty > maxCost)
					continue;

				double remainingDist = 0;
				// Calculate remaining distance estimator for next connected edge
				if (destinations != null && !destinations.isEmpty()) {
					remainingDist = Double.MAX_VALUE;
					Vec3 newNodePosition = newNode.getLocation().getLocation();
					for (GlobalStation destination : destinations) {
						TrackNodeLocation destinationNode = destination.edgeLocation.getFirst();
						double dMin = Math.abs(newNodePosition.x - destinationNode.getLocation().x);
						double dMid = Math.abs(newNodePosition.y - destinationNode.getLocation().y);
						double dMax = Math.abs(newNodePosition.z - destinationNode.getLocation().z);
						// Sort distance vector in ascending order
						double temp;
						if (dMin > dMid) {
							temp = dMid;
							dMid = dMin;
							dMin = temp;
						}
						if (dMin > dMax) {
							temp = dMax;
							dMax = dMin;
							dMin = temp;
						}
						if (dMid > dMax) {
							temp = dMax;
							dMax = dMid;
							dMid = temp;
						}
						// Octile distance from newNode to station node
						double currentRemaining = 0.317837245195782 * dMin + 0.414213562373095 * dMid + dMax + destination.position;
						if (node2.getLocation().equals(destinationNode))
							currentRemaining -= newEdge.getLength() * 2; // Correct the distance estimator for station edge
						remainingDist = Math.min(remainingDist, currentRemaining);
					}
				}

				reachedVia.putIfAbsent(newEdge, Pair.of(validTargets.size() > 1, Couple.create(node1, node2)));
				frontier.add(new FrontierEntry(newDistance, newPenalty, remainingDist, hasDestination, node2, newNode, newEdge));
			}
		}
	}

@SuppressWarnings("deprecation")
	@Override
	public void tick() {
		if (this.stuckInBlock) {
			this.setDeltaMovement(Vec3.ZERO);
		}

		if (this.getVehicle() instanceof Booflo) {
			this.disableProjectile();
			this.removeLaunchDirection();
			this.setInflated(true);
		}

		super.tick();
		this.getRotationController().tick();
		this.keepEffectsAbsorbed();

		this.fallDistance = 0;

		Vec3 motion = this.getDeltaMovement();

		if (!this.level().isClientSide) {
			if (this.teleportCooldown > 0) {
				this.teleportCooldown--;
			}

			if (this.puffCooldown > 0) {
				this.puffCooldown--;
			}

			if (!this.isPassenger() && this.isInflated() && !this.getRotationController().rotating && this.isNoEndimationPlaying()) {
				if (this.isBoosting() && RayTraceHelper.rayTrace(this, 2.0D, 1.0F).getType() != Type.BLOCK || ((this.onGround() || this.isInWater()) && this.puffCooldown <= 0 && this.getPollinationPos() == null && this.getLaunchDirection() == null && this.getFireDirection() == null)) {
					NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PUFF_BUG_PUFF);
					this.playSound(this.getPuffSound(), 0.15F, this.getVoicePitch());
				}
			}

			if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_TO) && this.getAnimationTick() == 10 && !this.getTeleportController().hasNoDestination()) {
				this.getTeleportController().bringToDestination();
			} else if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_FROM)) {
				this.setDeltaMovement(Vec3.ZERO);
			}

			if (this.getHivePos() == null) {
				if (this.level().getGameTime() % 5 == 0 && this.getRandom().nextFloat() <= 0.1F) {
					PuffBugHiveTileEntity hive = this.findNewNearbyHive();
					if (hive != null) {
						this.addToHive(hive);
						if (this.isNoEndimationPlaying()) {
							NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PUFF_BUG_CLAIM_HIVE);
						}
					}
				}
				this.ticksAwayFromHive = 0;
			} else {
				if (this.getHive() == null) {
					this.setHivePos(null);
				} else {
					if (this.getAttachedHiveSide() == Direction.UP) {
						this.ticksAwayFromHive++;

						if (this.ticksAwayFromHive < 1500) {
							if (this.getTarget() == null && this.getRandom().nextInt(7500) == 0 && !this.isInLove() && !this.getHive().isHiveFull()) {
								for (PuffBug nearbyHiveMembers : this.level().getEntitiesOfClass(PuffBug.class, this.getBoundingBox().inflate(9.0F), puffbug -> (puffbug.getHive() != null && puffbug.getHive() == this.getHive()) && this.distanceTo(puffbug) < 12.0F)) {

									this.setInLoveTime(1000);
									this.level().broadcastEntityEvent(this, (byte) 18);

									nearbyHiveMembers.setInLoveTime(1000);
									this.level().broadcastEntityEvent(nearbyHiveMembers, (byte) 18);

									if (this.isInLove() || nearbyHiveMembers.isInLove()) break;
								}
							}
						}
					} else {
						this.ticksAwayFromHive = 0;
					}
				}
			}

			if (this.getAttachedHiveSide() != Direction.UP) {
				this.setInflated(false);
			} else if (!this.isInflated() && this.getFireDirection() == null) {
				this.setInflated(true);
			}

			if (this.getTarget() != null && !CAN_ANGER.test(this.getTarget())) {
				this.setTarget(null);
			}

			if (this.isProjectile() && (this.updateFluidHeightAndDoFluidPushing(FluidTags.WATER, 1.0F) || this.updateFluidHeightAndDoFluidPushing(FluidTags.LAVA, 1.0F))) {
				this.disableProjectile();
			}
		} else {
			this.prevSpin = this.spin;
			RandomSource rand = this.getRandom();

			if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_PUFF) && this.getAnimationTick() == 5) {
				for (int i = 0; i < 3; i++) {
					double offsetX = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);
					double offsetZ = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);

					double x = this.getX() + offsetX;
					double y = this.getY() + (rand.nextFloat() * 0.05F) + 0.7F;
					double z = this.getZ() + offsetZ;

					this.level().addParticle(EEParticleTypes.SHORT_POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.1F), rand) + 0.05F, (rand.nextFloat() * 0.05F) + 0.025F, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.1F), rand) + 0.05F);
				}
			} else if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_TO) && this.getAnimationTick() == 8) {
				for (int i = 0; i < 6; i++) {
					double offsetX = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);
					double offsetZ = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);

					double x = this.getX() + offsetX;
					double y = this.getY() + (rand.nextFloat() * 0.05F) + 0.7F;
					double z = this.getZ() + offsetZ;

					this.level().addParticle(EEParticleTypes.SHORT_POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F, (rand.nextFloat() * 0.025F) + 0.025F, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F);
				}
			} else if (this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_TELEPORT_FROM) && this.getAnimationTick() == 5) {
				for (int i = 0; i < 6; i++) {
					double offsetX = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);
					double offsetZ = MathUtil.makeNegativeRandomly(rand.nextFloat() * 0.1F, rand);

					double x = this.getX() + offsetX;
					double y = this.getY() + (rand.nextFloat() * 0.05F) + 0.7F;
					double z = this.getZ() + offsetZ;

					this.level().addParticle(EEParticleTypes.SHORT_POISE_BUBBLE.get(), x, y, z, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F, (rand.nextFloat() * 0.025F) + 0.025F, MathUtil.makeNegativeRandomly((rand.nextFloat() * 0.15F), rand) + 0.025F);
				}
			}

			this.HIVE_LANDING.tick();
			this.HIVE_SLEEP.tick();

			this.HIVE_LANDING.setDecrementing(this.getAttachedHiveSide() == Direction.UP);

			if (this.HIVE_LANDING.isMaxed()) {
				if (this.HIVE_SLEEP.isDecrementing() && this.HIVE_SLEEP.getTick() == 0) {
					this.HIVE_SLEEP.setDecrementing(false);
				} else if (this.HIVE_SLEEP.isMaxed()) {
					this.HIVE_SLEEP.setDecrementing(true);
				}
			} else {
				this.HIVE_SLEEP.setDecrementing(true);
			}

			if (this.isProjectile() && this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_FLY)) {
				this.spin = this.spin + 55.0F;
			} else {
				this.spin = 0.0F;
			}
		}

		if (this.getDesiredHiveSide() != null) {
			if (this.getHive() != null && this.getDesiredHiveSide() != Direction.DOWN) {
				float degrees = (this.getDesiredHiveSide() == Direction.SOUTH ? 0 : this.getDesiredHiveSide().getAxisDirection().getStep()) * (this.getDesiredHiveSide().getAxis() == Axis.Z ? 180.0F : -90.0F);
				this.setYRot(this.yRotO = degrees);
				this.yHeadRot = this.yHeadRotO = degrees;
				this.yBodyRot = this.yBodyRotO = degrees;
			}
		}

		if (this.getAttachedHiveSide() != Direction.UP) {
			if (this.getHive() != null) {
				this.setDeltaMovement(this.getDeltaMovement().multiply(1.0F, 0.0F, 1.0F));
				this.getNavigation().stop();
				this.setSpeed(0.0F);

				this.push(0.0F, 0.0025F, 0.0F);

				this.setYRot(this.yRotO);
				this.yHeadRot = this.yHeadRotO;
				this.yBodyRot = this.yBodyRotO;

				if (!this.level().isClientSide && !this.isAtCorrectRestLocation(this.getAttachedHiveSide())) {
					this.setAttachedHiveSide(Direction.UP);
				}
			} else {
				if (!this.level().isClientSide) {
					this.setAttachedHiveSide(Direction.UP);
				}
			}
		} else {
			if ((this.getLaunchDirection() != null || this.getFireDirection() != null)) {
				this.setYRot(0.0F);
				this.yHeadRot = 0.0F;
				this.yBodyRot = 0.0F;

				Vec3 fireDirection = this.getFireDirection();

				if (fireDirection != null) {
					if ((this.level().isClientSide && !this.stuckInBlock) || !this.level().isClientSide) {
						this.getRotationController().rotate((float) Mth.wrapDegrees(fireDirection.y() - this.getYRot()), (float) fireDirection.x() + 90.0F, 0.0F, 5);
					}

					LivingEntity target = this.getTarget();

					if (!this.stuckInBlock) {
						if (!this.level().isClientSide && target != null && this.isEndimationPlaying(EEPlayableEndimations.PUFF_BUG_FLY)) {
							float seekOffset = target.getY() > this.getY() ? 0.0F : 0.5F;
							Vec3 targetVecNoScale = new Vec3(target.getX() - this.getX(), target.getY() - seekOffset - this.getY(), target.getZ() - this.getZ());
							Vec3 targetVec = targetVecNoScale.scale(SEEKING_FACTOR);

							double motionLength = motion.length();
							double targetVecLength = targetVec.length();

							float totalVecLength = Mth.sqrt((float) (motionLength * motionLength + targetVecLength * targetVecLength));

							Vec3 newMotion = motion.scale(motionLength / totalVecLength).add(targetVec.scale(targetVecLength / totalVecLength));

							float gravityCompensator = totalVecLength <= 4.0F ? 0.05F : 0.1F;

							this.setDeltaMovement(newMotion.scale(0.4F).add(0.0F, gravityCompensator, 0.0F));
						}

						Vec3 newestMotion = this.getDeltaMovement();

						float pitch = -((float) (Mth.atan2(newestMotion.y(), Mth.sqrt((float) (newestMotion.x() * newestMotion.x() + newestMotion.z() * newestMotion.z()))) * (double) (180F / (float) Math.PI)));
						float yaw = (float) (Mth.atan2(newestMotion.z(), newestMotion.x()) * (double) (180F / (float) Math.PI)) - 90F;

						this.setFireDirection(pitch, yaw);
					}
				}
			}
		}

		if (this.isProjectile() && !this.isInflated()) {
			BlockPos blockpos = this.blockPosition();
			BlockState blockstate = this.level().getBlockState(blockpos);
			if (!blockstate.isAir() && !this.noPhysics) {
				VoxelShape voxelshape = blockstate.getCollisionShape(this.level(), blockpos);
				if (!voxelshape.isEmpty()) {
					for (AABB axisalignedbb : voxelshape.toAabbs()) {
						if (axisalignedbb.move(blockpos).contains(this.position())) {
							this.stuckInBlock = true;
							break;
						}
					}
				}
			}

			if (this.stuckInBlock && !this.noPhysics) {
				if (!this.level().isClientSide && this.stuckInBlockState != blockstate && this.level().noCollision(this.getBoundingBox().inflate(0.06D))) {
					this.disableProjectile();
				}
				this.setDeltaMovement(this.getDeltaMovement().multiply(0.0F, 1.0F, 0.0F));
			} else {
				Vec3 positionVec = new Vec3(this.getX(), this.getY(), this.getZ());
				Vec3 endVec = positionVec.add(motion);

				HitResult traceResult = this.level().clip(new ClipContext(positionVec, endVec, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
				EntityHitResult entityTraceResult = this.traceEntity(positionVec, endVec);

				if (entityTraceResult != null) {
					traceResult = entityTraceResult;
				}

				if (traceResult.getType() != Type.MISS) {
					this.onSting(traceResult);
					this.hasImpulse = true;
				}
			}
		}
	}

