@Override
    public boolean hurt(DamageSource source, float damage) {
    	if (source == level().damageSources().hotFloor()) return false;
        if (hasEffect(EffectHandler.SUNBLOCK) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            if (source.getDirectEntity() != null) playSound(MMSounds.ENTITY_WROUGHT_UNDAMAGED.get(), 0.4F, 2);
            return false;
        }
        timeUntilHeal = HEAL_PAUSE;
        float prevHealth = getHealth();
        boolean superResult = super.hurt(source, damage);
        if (superResult) {
            float diffHealth = prevHealth - getHealth();
            setHealthLost(getHealthLost() + diffHealth);
        }
        return superResult;
    }

private static boolean hit(Level world, BlockPos pos, @Nullable Player playerEntity, InteractionHand hand) {
        if (FeatureFlag.isEnabled(FeatureFlag.bedrockExtraction)) {
            int amount = Optional.ofNullable(playerEntity)
                    .map(player -> player.getItemInHand(hand))
                    .filter(itemStack -> itemStack.getItem() instanceof IToolProvider)
                    .map(itemStack -> ((IToolProvider) itemStack.getItem()).getToolEfficiency(itemStack, TetraToolActions.hammer))
                    .map(Math::round)
                    .orElse(4);

            TileEntityOptional.from(world, pos, ChthonicExtractorTile.class).ifPresent(tile -> tile.damage(amount));
            FracturedBedrockBlock.pierce(world, pos.below(), amount);
            world.playSound(playerEntity, pos, SoundEvents.NETHERITE_BLOCK_HIT, SoundSource.PLAYERS, 0.8f, 0.5f);
            return true;
        }
        return false;
    }

@Override
    default void tick(TrailProvider provider) {
        var mc = Minecraft.getInstance();
        var level = mc.level;
        if (level == null) return;

        if (provider.getTrailMaxLength() <= 0) {
            trimToSize(0);
            return;
        }

        double now = level.getGameTime() + mc.getTimer().getGameTimeDeltaTicks();
        var maxAge = provider.getTrailEffectiveMaxAgeTicks(provider.isTrailGrowing());
        pruneOlderThan(now - maxAge);
        trimToSize(provider.getTrailMaxSamples());
    }

