@Override
    public boolean hurtEnemy(@NotNull ItemStack stack, @NotNull LivingEntity targetEntity, LivingEntity attacker) {
        float f = (float) attacker.getAttribute(Attributes.ATTACK_DAMAGE).getValue();
        float f3 = 1.0F + EnchantmentHelper.getSweepingDamageRatio(attacker) * f;
        if (attacker instanceof Player) {
            Player player = (Player) attacker;
            for (LivingEntity LivingEntity : attacker.level.getEntitiesOfClass(LivingEntity.class, targetEntity.getBoundingBox().inflate(1.0D, 0.25D, 1.0D))) {
                if (LivingEntity != player && LivingEntity != targetEntity && !attacker.isAlliedTo(LivingEntity) && attacker.distanceToSqr(LivingEntity) < 9.0D) {
                    LivingEntity.knockback(0.4F, Mth.sin(attacker.getYRot() * 0.017453292F), -Mth.cos(attacker.getYRot() * 0.017453292F));
                    LivingEntity.hurt(DamageSource.playerAttack(player), f3);
                }
            }
            player.level.playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_SWEEP, player.getSoundSource(), 1.0F, 1.0F);
            player.sweepAttack();
        }
        return super.hurtEnemy(stack, targetEntity, attacker);
    }

protected void onHit(HitResult hitResult) {
        if (!this.level.isClientSide) {
            DamageSource damageSource = ModDamageSource.getDamageSource(this.level, ModDamageSource.SHOCK);
            float damage = SpellConfig.ElectroOrbDamage.get().floatValue() * WandUtil.damageMultiply();
            if (this.getOwner() != null) {
                damageSource = ModDamageSource.indirectShock(this, this.getOwner());
            }
            damage += this.getExtraDamage();
            if (hitResult instanceof EntityHitResult result) {
                Entity entity = result.getEntity();
                entity.hurt(damageSource, damage);
            }
            this.finalizeExplosion();
            this.playSound(ModSounds.THUNDERBOLT.get(), 1.0F, 1.0F + (this.random.nextFloat() - this.random.nextFloat()) * 0.2F);
            this.discard();
        }
    }

@Override
    public void render(SpiritJarBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        Level level = Minecraft.getInstance().level;
        ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
        if (blockEntityIn.contents != null) {
            var type = blockEntityIn.contents.getSpirit();
            float time = level.getGameTime() + partialTicks;
            double y = 0.5f + (float) Math.sin((time * 0.05f) % 6.28f) * 0.2f;
            poseStack.pushPose();
            poseStack.translate(0.5f, y, 0.5f);
            FloatingItemRenderer.renderSpiritGlimmer(poseStack, type, partialTicks);
            poseStack.mulPose(Axis.YP.rotationDegrees((time * 3) % 360));
            poseStack.scale(0.6f, 0.6f, 0.6f);
            itemRenderer.renderStatic(type.getSpiritStack(), ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
            poseStack.popPose();
        }
    }

public Vec3 getScarfStart(LivingEntity entity, float partialTicks) {
            float xLook = Mth.lerp(partialTicks, entity.xRotO, entity.getXRot());
            float yLook = Mth.lerp(partialTicks, entity.yRotO, entity.getYRot());
            var lookDirection = Vec3.directionFromRotation(new Vec2(xLook, yLook));
            float upwardsOffset = entity.getBbHeight() * 0.8f;
            var eyePosition = entity.getPosition(partialTicks).add(0, upwardsOffset, 0);
            float yRot = ((float) (Mth.atan2(lookDirection.x, lookDirection.z) * (double) (180F / (float) Math.PI)));
            float yaw = (float) Math.toRadians(yRot);
            var left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
            final Vec3 offsetPosition = eyePosition.subtract(lookDirection.scale(0.2f).add(left.scale(horizontalOffset)));
            float angle = ((entity.level().getGameTime()+partialTicks) * 0.05f) % 6.28f;
            float offsetStrength = 0.01f;
            float xOffset = Mth.sin(angle * 4) * offsetStrength;
            float yOffset = Mth.sin(angle * 4) * offsetStrength;
            float zOffset = Mth.cos(angle * 4) * offsetStrength;
            return offsetPosition.add(xOffset, yOffset, zOffset);
        }

