@Override
	protected void onHit(HitResult result) {
		if (result.getType() == HitResult.Type.ENTITY) {
			Entity entity = ((EntityHitResult) result).getEntity();
			entity.hurt(this.damageSources().thrown(this, this.getOwner()), (float) 0);
			if (entity instanceof Pig pig && MuddyPig.enabled()) {
				MuddyPig.setMuddy(pig, true);
				MuddyPig.updateDryingTime(pig, 1200);
			}
		}

		if (!this.level().isClientSide) {
			this.level().broadcastEntityEvent(this, (byte) 3);
			this.discard();
		}

	}

@Override
    public boolean causeFallDamage(float f1, float f2, DamageSource damageSource) {
        float[] ret = net.minecraftforge.common.ForgeHooks.onLivingFall(this, f1, f2);
        if (ret == null) return false;
        f1 = ret[0];
        f2 = ret[1];

        boolean flag = causeInternalFallDamage(f1, f2, damageSource);
        int i = this.calculateFallDamage(f1, f2);
        if (i > 0) {
            this.playSound(i > 4 ? this.getFallSounds().big() : this.getFallSounds().small(), 1.0F, 1.0F);
            this.playBlockFallSound();
            this.hurt(damageSource, (float)i);
            return true;
        } else {
            return flag;
        }
    }

@Override
        public void tick() {
            catfish.getNavigation().moveTo(food.getX(), food.getY(0.5F), food.getZ(), 1.0F);
            final float eatDist = catfish.getBbWidth() * 0.65F + food.getBbWidth();
            if (catfish.distanceTo(food) < eatDist + 3 && catfish.hasLineOfSight(food)) {
                final Vec3 delta = catfish.getMouthVec().subtract(food.position()).normalize().scale(0.1F);
                food.setDeltaMovement(food.getDeltaMovement().add(delta));
                if (catfish.distanceTo(food) < eatDist) {
                    if (food instanceof Player) {
                        food.hurt(catfish.damageSources().mobAttack(catfish), 12000);
                    } else if (catfish.swallowEntity(food)) {
                        catfish.gameEvent(GameEvent.EAT);
                        catfish.playSound(SoundEvents.GENERIC_EAT, catfish.getSoundVolume(), catfish.getVoicePitch());
                        food.discard();
                    }
                }
            }
        }

