@Override
	protected void onImpact(RayTraceResult mop) {
		if (!getEntityWorld().isRemote) {
			if (!playedSound) {
				getEntityWorld().playSound((EntityPlayer) null, getPosition(), getSplashSound(), SoundCategory.HOSTILE, 0.25F, 2.0F);
				playedSound = true;
			}
			if (mop.typeOfHit != null && mop.typeOfHit == RayTraceResult.Type.BLOCK)
				setDead();
			if (mop.entityHit != null) {
				if (mop.typeOfHit != null && mop.typeOfHit == RayTraceResult.Type.ENTITY && mop.entityHit != thrower) {
					mop.entityHit.attackEntityFrom(DamageSource.causeThrownDamage(this, getThrower()), 2F);
					getEntityWorld().setEntityState(this, EVENT_HIT_PARTICLES);
					setDead();
				}
			}
		}
	}

private void explode() {
        this.level().broadcastEntityEvent(this, EXPLOSION_PARTICLES_ID);

        playSound(MMSounds.ENTITY_NAGA_ACID_HIT.get(), 1, 1);

        List<Entity> entitiesHit = getEntitiesNearby(2);
        if (!entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity == getCaster()) continue;
                if (entity instanceof EntityNaga) continue;
                if (entity.hurt(damageSources().indirectMagic(this, getCaster()), 3 * ConfigHandler.COMMON.MOBS.NAGA.combatConfig.attackMultiplier.get().floatValue()) && entity instanceof LivingEntity livingEntity) {
                    livingEntity.addEffect(new MobEffectInstance(MobEffects.POISON, 80, 0, false, true));
                }
            }
        }

        discard() ;
    }

@Override
	public boolean hurt(DamageSource source, float amount) {
		boolean b = super.hurt(source, amount);
        if(!level().isClientSide() && isAlive()) {
            byte variant = getVariant();
            boolean isRed = variant == 4, isYellow = variant == 5, isBlue = variant == 6;
            for(EntityAyeraco e : getNearbyAyeracos(level(), position())) {
                if(isRed && e != this && e.getHealth() < e.getMaxHealth()) e.setHealth(e.getMaxHealth());
                if(isYellow) e.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 255, 2, true, false, false));
                if(isBlue) e.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 255, 2, true, false, false));
                if(e.isPurple()) {
                    playSound(SoundRegistry.AYERACO_TELEPORT.get(), 2.0F, 0.4F / (random.nextFloat() * 0.4F + 0.8F));
                    teleportRelative(random.nextInt(5) - 2, 3 + random.nextInt(15), random.nextInt(5) - 2);
                }
            }
        }
		return b;
	}

private static void causeTruesweepDamage(DamageSource damageSource, float baseDamage, ItemStack itemStack, LivingEntity attacker, LivingEntity target) {
        float targetModifier = EnchantmentHelper.getDamageBonus(itemStack, target.getMobType());
        float critMultiplier = CastOptional.cast(attacker, Player.class)
                .map(player -> ForgeHooks.getCriticalHit(player, target, false, 1.5f))
                .map(CriticalHitEvent::getDamageModifier)
                .orElse(1f);

        target.hurt(damageSource, (baseDamage + targetModifier) * critMultiplier);

        if (targetModifier > 0) {
            CastOptional.cast(attacker, Player.class).ifPresent(player -> player.magicCrit(target));
        }

        if (critMultiplier > 1) {
            attacker.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 1.3f);
            ((Player) attacker).crit(target);
        }
    }

public static void spawnEntity(World world, LivingEntity owner, ItemStack stack) {
		stack.damage(1, owner, stackUser -> stackUser.sendToolBreakStatus(stackUser.getActiveHand()));
		HornedSpearEntity spear = new HornedSpearEntity(BWEntityTypes.HORNED_SPEAR, owner, world, stack.copy());
		spear.setVelocity(owner, owner.getPitch(), owner.getYaw(), 0, 3, 1);
		if (owner instanceof PlayerEntity player) {
			if (player.isCreative()) {
				spear.pickupType = PersistentProjectileEntity.PickupPermission.CREATIVE_ONLY;
			}
		} else {
			spear.pickupType = PersistentProjectileEntity.PickupPermission.DISALLOWED;
		}
		world.spawnEntity(spear);
		PlayerLookup.tracking(spear).forEach(trackingPlayer -> SyncHornedSpearPacket.send(trackingPlayer, spear));
		world.playSoundFromEntity(null, spear, BWSoundEvents.ITEM_HORNED_SPEAR_USE, SoundCategory.PLAYERS, 1, 1);
		if (owner instanceof PlayerEntity player && !player.isCreative()) {
			stack.decrement(1);
		}
	}

public void areaAttack(){
        for (LivingEntity livingEntity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(16.0D),
                living -> !MobUtil.areAllies(living, this) && living.isAlive())){
            double xPower = this.getX() - livingEntity.getX();
            double yPower = this.getY() - livingEntity.getY();
            double zPower = this.getZ() - livingEntity.getZ();
            double distance = Math.sqrt(xPower * xPower + yPower * yPower + zPower * zPower);
            if (this.distanceToSqr(livingEntity) < 9.0D) {
                if (livingEntity.hurt(this.getServantAttack(), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE))) {
                    this.playSound(SoundEvents.PLAYER_ATTACK_KNOCKBACK, 1.0F, 1.0F);
                    livingEntity.hurtMarked = true;
                    if (!livingEntity.hasEffect(GoetyEffects.TANGLED.get())) {
                        MobUtil.push(livingEntity, -xPower / distance * 2.0D, -yPower / distance * 2.0D + 0.5D, -zPower / distance * 2.0D);
                    }
                }
            }
        }
    }

private SpiritInfluenceRendererData tickData(IArtificeAcceptor target) {
        ClientLevel level = Minecraft.getInstance().level;
        if (level.getGameTime() == gameTimeCache) {
            return this;
        }
        gameTimeCache = level.getGameTime();
        var activeSpiritType = target.getActiveSpiritType();
        if (activeSpiritType != null) {
            merge(activeSpiritType, 1, (a, b) -> Math.min(a + b, maxValue()));
        }
        for (SpiritArcanaType spiritType : keySet()) {
            if (spiritType.equals(activeSpiritType)) {
                continue;
            }
            merge(spiritType, 1, (a, b) -> Math.max(a - b, 0));
        }
        return this;
    }

private static void damageIfNeeded(UseOnContext context) {
    ItemStack stack = context.getItemInHand();
    Level level = context.getLevel();
    // vanilla tools tend not to call the proper damage methods if player is null, so just manually damage the stack
    // we expect modded items will have the same bug, so just go ahead and damage them. On the chance it works, they get 2 damage, no big deal
    // our tools we know work so ignore them
    if (!level.isClientSide && context.getPlayer() == null && stack.isDamageableItem() && !stack.is(TinkerTags.Items.MODIFIABLE)) {
      // unable to call Forge damageItem as that needs entity access, but its just vanilla broken anyways, right?
      stack.hurt(1, level.getRandom(), null);
      // calling methods again instead of using return as return may be incorrect for custom broken stacks
      if (stack.getDamageValue() >= stack.getMaxDamage()) {
        // but that won't happen, right? will need to consider another workaround in that case.
        stack.shrink(1);
        stack.setDamageValue(0);
        level.playSound(null, context.getClickedPos(), SoundEvents.ITEM_BREAK, SoundSource.BLOCKS, 1.0F, 1.0F);
      }
    }
  }

