            int cursesRemoved = removeCurses(lookup, p, EquipmentSlot.HEAD) +
                              removeCurses(lookup, p, EquipmentSlot.CHEST) +
                              removeCurses(lookup, p, EquipmentSlot.LEGS) +
                              removeCurses(lookup, p, EquipmentSlot.FEET) +
