public InteractionResult mobInteract(Player player, InteractionHand hand) {
        ItemStack itemstack = player.getItemInHand(hand);
        Item item = itemstack.getItem();
        InteractionResult type = super.mobInteract(player, hand);
        if (item == Items.SNOW && !this.isSnowy() && !this.level().isClientSide) {
            this.usePlayerItem(player, hand, itemstack);
            this.permSnow = true;
            this.setSnowy(true);
            this.gameEvent(GameEvent.ENTITY_INTERACT);
            this.playSound(SoundEvents.SNOW_PLACE, this.getSoundVolume(), this.getVoicePitch());
            return InteractionResult.SUCCESS;
        }
        if (item instanceof ShovelItem && this.isSnowy() && !this.level().isClientSide) {
            this.permSnow = false;
            if (!player.isCreative()) {
                itemstack.hurt(1, this.getRandom(), player instanceof ServerPlayer ? (ServerPlayer) player : null);
            }
            this.setSnowy(false);
            this.gameEvent(GameEvent.ENTITY_INTERACT);
            this.playSound(SoundEvents.SNOW_BREAK, this.getSoundVolume(), this.getVoicePitch());
            return InteractionResult.SUCCESS;
        }
        return type;
    }

@Override
    protected void fall(float f)
    {
        int i = (int) Math.ceil(f - 3F);
        if ((i > 0))
        {
            i /= 3;
            if (i > 0)
            {
                attackEntityFrom(DamageSource.fall, i);
            }
            if ((riddenByEntity != null) && (i > 0))
            {
                riddenByEntity.attackEntityFrom(DamageSource.fall, i);
            }

            int j = worldObj.getBlockId(MathHelper.floor_double(posX), MathHelper.floor_double(posY - 0.20000000298023221D - prevRotationPitch), MathHelper.floor_double(posZ));
            if (j > 0)
            {
                StepSound stepsound = Block.blocksList[j].stepSound;
                worldObj.playSoundAtEntity(this, stepsound.getStepSound(), stepsound.getVolume() * 0.5F, stepsound.getPitch() * 0.75F);
            }
        }
    }

public static void renderSpiritGlimmer(PoseStack poseStack, WorldVFXBuilder builder, Color primaryColor, Color secondaryColor, float scaleScalar, float alphaScalar, float partialTicks) {
        var minecraft = Minecraft.getInstance();
        var level = minecraft.level;
        var star = LodestoneRenderTypes.ADDITIVE_TEXTURE.apply(MalumRenderTypeTokens.STAR);
        var twinkle = LodestoneRenderTypes.ADDITIVE_TEXTURE.apply(MalumRenderTypeTokens.TWINKLE);

        float gameTime = level.getGameTime() + partialTicks;
        double sine = Math.abs(((Math.sin((gameTime / 80f) % 360)) * 0.075f));
        float scale = (float) ((0.12f + sine) * scaleScalar);

        poseStack.pushPose();
        poseStack.mulPose(minecraft.getEntityRenderDispatcher().cameraOrientation());
        builder.setAlpha(Mth.clamp(0.6f * alphaScalar, 0, 1))
                .setColor(primaryColor)
                .setRenderType(star)
                .renderQuad(poseStack, scale * 0.8f);
        builder.setAlpha(Mth.clamp(0.8f * alphaScalar, 0, 1))
                .setRenderType(twinkle)
                .renderQuad(poseStack, scale * 0.6f);
        builder.setAlpha(Mth.clamp(0.2f * alphaScalar, 0, 1))
                .setColor(secondaryColor)
                .renderQuad(poseStack, scale * 0.6f);
        poseStack.popPose();
    }

@Override
    public void rideTick() {
        super.rideTick();
        Entity vehicle = getVehicle();
        if (vehicle != null) {
            if (vehicle instanceof LivingEntity livingEntity) {
                if (!level.isClientSide && !livingEntity.hasEffect(MobEffects.BLINDNESS)) {
                    livingEntity.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 100), this);
                }
                if (tickCount % 20 == 0) {
                    if (!level.isClientSide) {
                        vehicle.hurt(DamageSource.mobAttack(this), getSize());
                        playSound(getJumpSound(), getSoundVolume(), getVoicePitch());
                    }
                    targetSquish = 0.7f;
                } else {
                    targetSquish = Math.max(0, targetSquish * 0.9f);
                }
