@Override
    public boolean hurt(DamageSource source, float amount) {
        Entity entity = source.getEntity();
        if (entity instanceof Player player && !source.is(DamageTypeTags.IS_PROJECTILE)) {
            if (player.getMainHandItem().isCorrectToolForDrops(Blocks.DIAMOND_ORE.defaultBlockState()) || player.getMainHandItem().is(MMItemTags.CAN_HIT_GROTTOL)) {
                if (EnchantmentUtils.getLevel(Enchantments.FORTUNE, player.level(), player.getMainHandItem()) > 0) {
                    death = EnumDeathType.FORTUNE_PICKAXE;
                    if (player instanceof ServerPlayer serverPlayer) AdvancementHandler.GROTTOL_KILL_FORTUNE_TRIGGER.value().trigger(serverPlayer);
                } else {
                    death = EnumDeathType.PICKAXE;
                }
                return super.hurt(source, getHealth());
            } else {
                if (timeSinceDeflectSound >= 5) {
                    timeSinceDeflectSound = 0;
                    playSound(MMSounds.ENTITY_GROTTOL_UNDAMAGED.get(), 0.4F, 2.0F);
                }
                return false;
            }
        }
        else if (entity instanceof Mob) {
            return false;
        }
        return super.hurt(source, amount);
    }

@Override
	protected void onHit(HitResult result) {
		Entity thrower = getOwner();
		if (level().isClientSide || result.getType() == HitResult.Type.ENTITY && ((EntityHitResult) result).getEntity() == thrower) {
			return;
		}

		if (result.getType() == HitResult.Type.ENTITY && ((EntityHitResult) result).getEntity() instanceof Mob living) {
			living.hurt(damageSources().thrown(this, thrower), 5.0f);
			living.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 20 * 20, 2));
			living.addEffect(new MobEffectInstance(ModEffects.PACIFICATION, 15 * 20));
		}

		double motionX = getDeltaMovement().x();
		double motionY = getDeltaMovement().y();
		double motionZ = getDeltaMovement().z();
		for (int count = 0; count < 6; ++count) {
			float amplifier = 0.25F;
			level().addParticle(ParticleTypes.ITEM_SLIME, getX() - motionX * amplifier + level().random.nextDouble(),
					getY() - motionY * amplifier + level().random.nextDouble(), getZ() - motionZ * amplifier + level().random.nextDouble(), motionX, motionY,
					motionZ);
		}
		level().playSound(null, blockPosition(), SoundEvents.SLIME_JUMP, SoundSource.NEUTRAL, 0.5F, 0.4F / (level().random.nextFloat() * 0.4F + 0.8F));
