@Override
	protected boolean effectOnDamage(DamageSource src, MutableFloat amount, Player player, ItemStack stack) {
		if (!src.is(DamageTypeTags.BYPASSES_ARMOR)) {
			int range = 6;
			@SuppressWarnings("unchecked")
			List<Enemy> mobs = (List<Enemy>) (List<?>) player.level().getEntitiesOfClass(Entity.class, new AABB(player.getX() - range, player.getY() - range, player.getZ() - range, player.getX() + range, player.getY() + range, player.getZ() + range), Predicates.instanceOf(Enemy.class));
			for (Enemy mob : mobs) {
				if (mob instanceof LivingEntity entity) {
					entity.hurt(player.damageSources().playerAttack(player), amount.getValue());
				}
			}

			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.unholyCloak, SoundSource.PLAYERS, 1F, 1F);
			for (int i = 0; i < 90; i++) {
				float rad = i * 4F * (float) Math.PI / 180F;
				float xMotion = (float) Math.cos(rad) * 0.2F;
				float zMotion = (float) Math.sin(rad) * 0.2F;
				WispParticleData data = WispParticleData.wisp(0.6F + (float) Math.random() * 0.2F, 0.4F + (float) Math.random() + 0.25F, 0F, 0F);
				player.level().addParticle(data, player.getX(), player.getY() + 0.5, player.getZ(), xMotion, 0F, zMotion);
			}

			return true;
		}

		return false;
	}

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (this.getAnimation() == GUARDIAN_MASS_DESTRUCTION && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }
        Entity entity = source.getDirectEntity();
        if (!this.getIsHelmetless()) {
            if (entity instanceof AbstractArrow) {
                return false;
            }
        }
        if (entity instanceof ShulkerBullet || entity instanceof Ender_Guardian_Bullet_Entity) {
            return false;
        }
        if (entity instanceof AbstractGolem) {
            damage *= 0.5;
        }

        boolean attack = super.hurt(source, damage);
        if(attack) {
            if (this.getIsHelmetless()) {
                this.playSound(SoundEvents.SHULKER_HURT, 1.0f, 0.8f);
            }
        }
        return attack;
    }

public InteractionResult mobInteract(Player player, InteractionHand hand) {
        final ItemStack itemstack = player.getItemInHand(hand);
        final Item item = itemstack.getItem();
        final InteractionResult type = super.mobInteract(player, hand);
        if (!this.level().isClientSide) {
            if (item == Items.SNOW && !this.isSnowy()) {
                this.usePlayerItem(player, hand, itemstack);
                this.permSnow = true;
                this.setSnowy(true);
                this.playSound(SoundEvents.SNOW_PLACE, this.getSoundVolume(), this.getVoicePitch());
                this.gameEvent(GameEvent.ENTITY_INTERACT);
                return InteractionResult.SUCCESS;
            }

            if (item instanceof ShovelItem && this.isSnowy()) {
                this.permSnow = false;
                if (!player.isCreative()) {
                    itemstack.hurt(1, this.getRandom(), player instanceof ServerPlayer ? (ServerPlayer) player : null);
                }
                this.setSnowy(false);
                this.playSound(SoundEvents.SNOW_BREAK, this.getSoundVolume(), this.getVoicePitch());
                this.gameEvent(GameEvent.ENTITY_INTERACT);
                return InteractionResult.SUCCESS;
            }
        }
        return type;
    }

public void tick() {
            if(vulture.isFlying()){
                vulture.setTackling(true);
            }else{
                vulture.setTackling(false);
            }
            if (vulture.getTarget() != null) {
                this.vulture.getMoveControl().setWantedPosition(vulture.getTarget().getX(), vulture.getTarget().getY() + vulture.getTarget().getEyeHeight(), vulture.getTarget().getZ(), 2.0D);
                final double d0 = this.vulture.getX() - this.vulture.getTarget().getX();
                final double d2 = this.vulture.getZ() - this.vulture.getTarget().getZ();
                final float f = (float)(Mth.atan2(d2, d0) * (double)Mth.RAD_TO_DEG) - 90.0F;
                vulture.setYRot(f);
                vulture.yBodyRot = vulture.getYRot();
                if (vulture.getBoundingBox().inflate(0.3F, 0.3F, 0.3F).intersects(vulture.getTarget().getBoundingBox()) && vulture.tackleCooldown == 0) {
                    tackleCooldown = 100 + random.nextInt(200);
                    float dmg = (float) vulture.getAttribute(Attributes.ATTACK_DAMAGE).getValue();
                    if(vulture.getTarget().hurt(vulture.damageSources().mobAttack(vulture), dmg)){
                        if(vulture.getHealth() < vulture.getMaxHealth() - dmg && vulture.getSoulLevel() < 5){
                            this.vulture.setSoulLevel(vulture.getSoulLevel() + 1);
                            this.vulture.heal(dmg);
                            this.vulture.level().broadcastEntityEvent(vulture, (byte)68);
                        }
                    }
                    stop();
                }
            }
        }

