public void entityInside(BlockState pState, Level pLevel, BlockPos pPos, Entity pEntity) {
        if (pState.getValue(LIT)) {
            if (!pEntity.fireImmune()
                    && pEntity instanceof LivingEntity livingEntity
                    && livingEntity.getMobType() != MobType.UNDEAD
                    && !LichdomHelper.isInLichMode(livingEntity)
                    && !EnchantmentHelper.hasFrostWalker((LivingEntity) pEntity)
                    && pEntity.getY() >= pPos.getY() + 0.5F) {
                pEntity.hurt(pEntity.damageSources().inFire(), 1.0F);
            }
            BlockEntity tileentity = pLevel.getBlockEntity(pPos);
            if (tileentity instanceof NecroBrazierBlockEntity blockEntity) {
                if (pEntity instanceof ItemEntity itemEntity) {
                    if (!pLevel.isClientSide) {
                        if (itemEntity.isAlive() && !itemEntity.getItem().isEmpty() && !itemEntity.getTags().contains(ConstantPaths.resultItem())) {
                            if (blockEntity.currentTime <= 0) {
                                if (blockEntity.addItem(null, itemEntity.getItem())) {
                                    pLevel.playSound(null, pPos, SoundEvents.ITEM_PICKUP, SoundSource.BLOCKS, 1.0F, 1.0F);
                                    syncItem(itemEntity);
                                }
                            }
                        }
                    }
                }
            }
        }

        super.entityInside(pState, pLevel, pPos, pEntity);
    }

@Override
        public void tickTask() {
            ++this.ticks;
            if (this.level.getEntity(this.owner) instanceof LivingEntity ownerLiving) {
                int width = this.level.getRandom().nextIntBetweenInclusive(1, 4);
                float height = this.level.getRandom().nextFloat() * 0.5F;
                Vec3 vec3 = ownerLiving.getEyePosition().offsetRandom(this.level.getRandom(), 2.0F);
                Vec3 angle = ownerLiving.getLookAngle().multiply(-1.0D, 1.0D, -1.0D);
                this.level.sendParticles(new WindBlowParticleOption(new ColorUtil(ChatFormatting.LIGHT_PURPLE), width, height), vec3.x, vec3.y, vec3.z, 0, angle.x, angle.y, angle.z, 1.0F);

                for (LivingEntity entityHit : this.level.getEntitiesOfClass(LivingEntity.class, ownerLiving.getBoundingBox().inflate(2.0F))) {
                    if (!MobUtil.areAllies(ownerLiving, entityHit) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(entityHit) && entityHit.isAttackable()) {
                        boolean flag = entityHit.hurt(this.level.damageSources().mobAttack(ownerLiving), this.damage);
                        if (entityHit.isDamageSourceBlocked(this.level.damageSources().mobAttack(ownerLiving))) {
                            MobUtil.disableShield(entityHit, 100);
                        }
                        if (flag) {
                            if (!entityHit.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
                                entityHit.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(5), 0, false, true));
                            }
                            double d0 = entityHit.getX() - ownerLiving.getX();
                            double d1 = entityHit.getZ() - ownerLiving.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            entityHit.push(d0 / d2 * 2.5D, 0.18D, d1 / d2 * 2.2D);
                        }
                    }
                }
            }
        }

@Override
	protected boolean effectOnDamage(DamageSource src, MutableFloat amount, Player player, ItemStack stack) {
		if (!src.is(DamageTypeTags.WITCH_RESISTANT_TO)) {
			amount.setValue(amount.getValue() / 2);

			if (src.getEntity() != null) {
				src.getEntity().hurt(player.damageSources().indirectMagic(player, player), amount.getValue());
			}

			if (amount.getValue() > player.getHealth()) {
				amount.setValue(player.getHealth() - 1);
			}

			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.holyCloak, SoundSource.PLAYERS, 1F, 1F);
			for (int i = 0; i < 30; i++) {
				double x = player.getX() + Math.random() * player.getBbWidth() * 2 - player.getBbWidth();
				double y = player.getY() + Math.random() * player.getBbHeight();
				double z = player.getZ() + Math.random() * player.getBbWidth() * 2 - player.getBbWidth();
				boolean green = Math.random() > 0.5;
				float g = green ? 1F : 0.3F;
				float b = green ? 0.3F : 1F;
