@Override
    public void aiStep() {
        super.aiStep();
        if (Math.abs(firstWidth - INITIAL_WIDTH * getSize()) > 0.01F || Math.abs(firstHeight - INITIAL_HEIGHT * getSize()) > 0.01F) {
            firstWidth = INITIAL_WIDTH * getSize();
            firstHeight = INITIAL_HEIGHT * getSize();
        }
        if (this.getAnimation() == ANIMATION_SPAWN && this.getAnimationTick() < 30) {
            BlockState belowBlock = level.getBlockState(this.blockPosition().below());
            if (belowBlock.getBlock() != Blocks.AIR) {
                for (int i = 0; i < 5; i++) {
                    this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, belowBlock), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getBoundingBox().minY, this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
                }
            }
            this.setDeltaMovement(0, this.getDeltaMovement().y, 0);
        }
        if (this.getTarget() != null && this.distanceTo(this.getTarget()) < 4 && this.hasLineOfSight(this.getTarget())) {
            if (this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(ANIMATION_BITE);
            }
            this.lookAt(this.getTarget(), 360, 80);
            if (this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 6) {
                this.getTarget().hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                // After calling hurt the target can become null due to forge hooks
                if (this.getTarget() != null)
                    this.getTarget().knockback(0.25F, this.getX() - this.getTarget().getX(), this.getZ() - this.getTarget().getZ());
            }
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public boolean plungeAttack(Level world, LivingEntity attacker, ItemStack stack) {

        if (attacker.fallDistance <= attacker.getMaxFallDistance() || !isEmpowered(stack) || !useEnergy(stack, true, attacker)) {
            return false;
        }
        float range = getPlungeRange(attacker.fallDistance);
        if (world.isClientSide) {
            // TODO circle particle
            world.addParticle(new CylindricalParticleOptions(CoreParticles.BLAST_WAVE.get(), range * 2.0F, range * 3.0F, 0, VFXHelper.windColor(world.random).toRGBA(), 1.5F), attacker.getX(), attacker.getY(), attacker.getZ(), 0, 0, 0);
            return true;
        }
        if (Utils.getItemEnchantmentLevel(Enchantments.CHANNELING, stack) > 0) {
            if (world.canSeeSky(attacker.blockPosition()) && world instanceof ServerLevel && world.isThundering()) {
                attacker.addEffect(new MobEffectInstance(LIGHTNING_RESISTANCE.get(), 40, 0, false, false));
                Utils.spawnLightningBolt(world, attacker.blockPosition(), attacker);
            }
        }
        double r2 = range * range;
        boolean hit = false;
        for (Entity target : world.getEntities(attacker, attacker.getBoundingBox().inflate(range, 1, range), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
            if (attacker.distanceToSqr(target) <= r2) {
                hit |= target.hurt(IFluxItem.fluxDirectDamage(attacker), getPlungeAttackDamage(attacker, stack));
            }
        }
        if (hit) {
            world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_RETURN, SoundSource.PLAYERS, 10.0F, 1.0F);
        } else {
            world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_HIT_GROUND, SoundSource.PLAYERS, 3.0F, 1.0F);
        }
        return hit;
    }

public void lifeSpanDamage(){
        if (this.getTrueOwner() != null
                && this.getTrueOwner().isAlive()
                && !this.getTrueOwner().isDeadOrDying()
                && (this.getStoredEffect() == null || this.getStoredEffect().getEffect().isBeneficial())){
            this.getNavigation().moveTo(this.getTrueOwner(), 1.25F);
            this.setTarget(null);
            ++this.searchTime;
            if (this.getBoundingBox().intersects(this.getTrueOwner().getBoundingBox())){
                this.getTrueOwner().heal(this.getHealth());
                for (MobEffectInstance mobEffectInstance : this.getActiveEffects()){
                    if (mobEffectInstance.getEffect().isBeneficial()){
                        this.getTrueOwner().addEffect(mobEffectInstance);
                    }
                }
                if (this.getStoredEffect() != null && this.getStoredEffect().getEffect().isBeneficial()){
                    this.getTrueOwner().addEffect(this.getStoredEffect());
                }
                this.playSound(SoundEvents.SCULK_BLOCK_SPREAD, 1.0F, 1.0F);
                if (!this.level.isClientSide) {
                    this.level.broadcastEntityEvent(this, (byte) 15);
                }
                this.discard();
            } else if (this.searchTime >= MathHelper.secondsToTicks(5)){
                this.hurt(this.damageSources().starve(), this.getMaxHealth());
            }
        } else {
            this.limitedLifeTicks = 20;
            this.hurt(this.damageSources().starve(), this.getMaxHealth());
        }
    }

@Override
  protected void onHitEntity(EntityHitResult result) {
    Entity target = result.getEntity();
    DamageSource source;
    // use a melee damage type if its targeting enderman
    if (TinkerEffects.needsEnderferenceOverride(target)) {
      source = CombatHelper.damageSource(TinkerDamageTypes.MELEE_THROWN, this, this.getOwner());
    } else {
      source = damageSources().thrown(this, this.getOwner());
    }
    boolean hit = target.hurt(source, power);

    if (hit && knockback > 0 && target instanceof LivingEntity living) {
      // knockback logic based on arrows
      double resistance = Math.max(0, 1 - living.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
      Vec3 motion = this.getDeltaMovement().multiply(1, 0, 1).normalize().scale(knockback * 0.6 * resistance);
      if (motion.lengthSqr() > 0) {
        target.push(motion.x, 0.1f, motion.z);
      }
    }

    Level level = level();
    if (!level.isClientSide) {
      if ((!hit || reclaim) && !this.isRemoved()) {
        this.spawnAtLocation(stack.copy());
      } else {
        level.broadcastEntityEvent(this, (byte) 3); // TODO: find the proper constant for this event ID
      }
      this.discard();
    }
  }

