protected boolean attack(Entity entity) {
		if (!this.world.isRemote) {
			if (this.onGround) {
				double dx = entity.posX - this.posX;
				double dz = entity.posZ - this.posZ;
				float dist = MathHelper.sqrt(dx * dx + dz * dz);
				this.motionX = dx / dist * 0.2D + this.motionX * 0.2D;
				this.motionZ = dz / dist * 0.2D + this.motionZ * 0.2D;
				this.motionY = 0.3D;
			}

			DamageSource damageSource;

			EntityLivingBase owner = this.getOwner();
			if(owner != null) {
				damageSource = new EntityDamageSourceIndirect("mob", this, owner);
			} else {
				damageSource = DamageSource.causeMobDamage(this);
			}

			entity.attackEntityFrom(damageSource, (float)this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());

			if(entity instanceof EntityLivingBase && this.world.rand.nextInt(4) == 0) {
				//Set revenge target to tarminion so it can be attacked by the mob
				((EntityLivingBase) entity).setRevengeTarget(this);
			}

			this.playSound(SoundRegistry.TAR_BEAST_STEP, 1.0F, 2.0F);

			((EntityLivingBase) entity).addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, world.getDifficulty().getId() * 50, 0));

			return true;
		}
		return true;
	}

@Override
    public void tick() {
        super.tick();

        var level = this.getCommandSenderWorld();

        level.addParticle((ParticleUtils.constructSimpleSpark(new Color(random.nextInt(150), 150 + random.nextInt(50), 200 + random.nextInt(50)), 0.05F, 10, 0.9F)), this.xOld, this.yOld, this.zOld,
                -this.getDeltaMovement().x * 0.1F * random.nextFloat(), -this.getDeltaMovement().y * 0.1F * random.nextFloat(), -this.getDeltaMovement().z * 0.1F * random.nextFloat());

        if (target == null || target.isDeadOrDying() || this.tickCount >= 250) {
            if (!level.isClientSide())
                this.discard();

            return;
        }

        if (this.position().distanceTo(target.getEyePosition()) > 1F) {
            var direction = target.getEyePosition().subtract(this.position()).normalize();
            var motion = this.getDeltaMovement();

            var window = 5;

            if (tickCount > window) {
                var factor = Math.clamp((tickCount - window) * 0.1F, 0F, 1F);

                this.setDeltaMovement(motion.x + (direction.x * factor - motion.x) * factor, motion.y + (direction.y * factor - motion.y) * factor, motion.z + (direction.z * factor - motion.z) * factor);
            }
        } else {
            target.invulnerableTime = 0;

            EntityUtils.hurt(target, level.damageSources().thrown(this, this.getOwner()), getDamage());

            this.discard();
        }
    }

