                        target.hurt(damageSources().mobAttack(this), damage);
                    }
                }
            }
        }
    }

public static void commonTick(Level level, BlockPos pos, BlockState state, TileEntitySculkBoomer tileEntity) {
        boolean hasPower = false;
        if (state.getBlock() instanceof BlockSculkBoomer && !tileEntity.isRemoved()) {
            if(tileEntity.screamTime < 0 && !state.getValue(BlockSculkBoomer.POWERED)){
                AABB screamBox = new AABB(pos.getX() - 4, pos.getY() - 0.25F, pos.getZ() - 4, pos.getX() + 4, pos.getY() + 0.25F, pos.getZ() + 4F);
                level.setBlockAndUpdate(pos, state.setValue(BlockSculkBoomer.OPEN, true));
                tileEntity.screamTime++;
                if(tileEntity.screamTime >= 0){
                    tileEntity.screamTime = 100;
                    level.setBlockAndUpdate(pos, state.setValue(BlockSculkBoomer.OPEN, false));
                }
                float screamProgress = 1F - (tileEntity.screamTime / -20F);
                Vec3 center = screamBox.getCenter();
                for(LivingEntity entity : level.getEntitiesOfClass(LivingEntity.class, screamBox)){
                    double distance = 0.5F + entity.position().subtract(center).horizontalDistance();
                    if(distance < 4 * screamProgress && distance > 3.5F * screamProgress && !isOccluded(level, Vec3.atCenterOf(pos), entity.position())){
                        entity.hurt(entity.damageSources().magic(), 6 + entity.getRandom().nextInt(3));
                        entity.knockback(0.4F,  center.x - entity.getX(), center.z - entity.getZ());
                    }
                }
            }
            if(tileEntity.screamTime > 0){
                tileEntity.screamTime--;
            }
            boolean openNow = state.getValue(BlockSculkBoomer.OPEN);
            if(!tileEntity.prevOpen && openNow){
                SoundEvent sound = AMSoundRegistry.SCULK_BOOMER.get();
                if(level.getRandom().nextInt(100) == 0){
                    sound = AMSoundRegistry.SCULK_BOOMER_FART.get();
                }
                level.playSound((Player)null, pos, sound, SoundSource.BLOCKS, 4F, level.random.nextFloat() * 0.2F + 0.9F);
                level.addParticle(AMParticleRegistry.SKULK_BOOM.get(), pos.getX() + 0.5F, pos.getY() + 0.5F, pos.getZ() + 0.5F, 0, 0, 0);
            }
            tileEntity.prevOpen = openNow;
        }
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){

				float damage = Spells.iceball.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FROST).setProjectile(),
						damage);

				if(entityHit instanceof EntityLivingBase && !MagicDamage.isEntityImmune(DamageType.FROST, entityHit)){
					((EntityLivingBase)entityHit).addPotionEffect(new PotionEffect(WizardryPotions.frost,
							Spells.iceball.getProperty(Spell.EFFECT_DURATION).intValue(),
							Spells.iceball.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}

			}else{

				BlockPos pos = rayTrace.getBlockPos();

				if(rayTrace.sideHit == EnumFacing.UP && !world.isRemote && world.isSideSolid(pos, EnumFacing.UP)
						&& BlockUtils.canBlockBeReplaced(world, pos.up()) && BlockUtils.canPlaceBlock(thrower, world, pos)){
					world.setBlockState(pos.up(), Blocks.SNOW_LAYER.getDefaultState());
				}
			}

			this.playSound(WizardrySounds.ENTITY_ICEBALL_HIT, 2, 0.8f + rand.nextFloat() * 0.3f);

			this.setDead();
		}
	}

public void entityInside(BlockState pState, Level pLevel, BlockPos pPos, Entity pEntity) {
        BrewCauldronBlockEntity blockEntity = (BrewCauldronBlockEntity) pLevel.getBlockEntity(pPos);
        if (!pLevel.isClientSide) {
            if (blockEntity != null) {
                if (pLevel.getBlockState(pPos).getValue(LEVEL) > 0 && pEntity instanceof LivingEntity && this.isEntityInsideContent(pState, pPos, pEntity)) {
                    if (blockEntity.isHeated() && !pEntity.fireImmune()) {
                        boolean flag = pEntity.hurt(ModDamageSource.getDamageSource(pLevel, ModDamageSource.BOILING), 1.0F);
                        if (flag && pLevel.getBlockState(pPos).getValue(LEVEL) == 3 && !pEntity.isAlive()){
                            blockEntity.mode = blockEntity.addSacrifice(pEntity);
                            blockEntity.markUpdated();
                        }
                    }
                }
                if (pLevel.getBlockState(pPos).getValue(LEVEL) == 3 && blockEntity.mode != BrewCauldronBlockEntity.Mode.COMPLETED && pEntity instanceof ItemEntity itemEntity) {
                    if (!itemEntity.getItem().isEmpty() && !itemEntity.getTags().contains(ConstantPaths.resultItem())) {
                        pLevel.playSound(null, pPos, SoundEvents.GENERIC_SPLASH, SoundSource.BLOCKS, 0.33F, 1.0F);
                        ItemStack stack = itemEntity.getItem();
                        ItemStack remain = stack.getCraftingRemainingItem();
                        if (stack.is(Items.POWDER_SNOW_BUCKET)) {
                            remain = new ItemStack(Items.BUCKET);
                        }
                        if (remain != null) {
                            ItemEntity remainder = new ItemEntity(pLevel, pPos.getX() + 0.5, pPos.getY() + 1, pPos.getZ() + 0.5, remain);
                            remainder.setDeltaMovement(Vec3.ZERO);
                            remainder.setNoGravity(true);
                            remainder.addTag(ConstantPaths.resultItem());
                            pLevel.addFreshEntity(remainder);
                        }
                        blockEntity.mode = blockEntity.insertItem(stack.split(1));
                        blockEntity.markUpdated();
                    }
                }
            }
        }
        super.entityInside(pState, pLevel, pPos, pEntity);
    }

@Override
	public void aiStep() {
		if (!this.onGround() && this.getDeltaMovement().y() < 0.0D) {
			Vec3 motion = getDeltaMovement();
			this.setDeltaMovement(motion.x(), motion.y() * 0.6D, motion.z());
		}
		super.aiStep();
		if (this.level().isClientSide() && !this.isDeadOrDying()) {
			// make snow particles
			for (int i = 0; i < 3; i++) {
