@Override
    public boolean hurt(DamageSource source, float damage) {
        Entity entity = source.getDirectEntity();

        if (!source.is(DamageTypeTags.BYPASSES_SHIELD) &&!this.isNoAi() && this.getAttackState() == 4) {
            Vec3 vector3d2 = source.getSourcePosition();
            if (vector3d2 != null) {
                Vec3 vector3d = this.getViewVector(1.0F);
                Vec3 vector3d1 = vector3d2.vectorTo(this.position()).normalize();
                vector3d1 = new Vec3(vector3d1.x, 0.0D, vector3d1.z);
                if(vector3d1.dot(vector3d) < 0.0D){
                    if (this.attackTicks >= 7 && this.attackTicks <= 17) {
                        if(entity instanceof LivingEntity living) {
                            this.block_stage = 1;
                            if (!this.level().isClientSide ) {
                                living.addEffect(new MobEffectInstance(ModEffect.EFFECTSTUN.get(), 50));
                            }
                            this.playSound(ModSounds.PARRY.get(),0.8F,1.0F);
                        }
                        return false;

                    }else if (this.attackTicks > 17 && this.attackTicks <= 43){
                        if(entity instanceof LivingEntity living) {
                            this.block_stage =2;
                            living.knockback(0.5F, this.getX() - living.getX(), this.getZ() - living.getZ());
                        }
                        return false;
                    } else{
                        return super.hurt(source, damage);
                    }
                }
            }
        }


        return super.hurt(source, damage);
    }

private void Whip(double startdistance,double range,double inflateXZ,double inflateY,int number, float anglestep,float damage, float hpdamage){
        double theta = (yBodyRot) * (Math.PI / 180);
        theta += Math.PI / 2;
        double vecX = startdistance * Math.cos(theta);
        double vecZ = startdistance * Math.sin(theta);

        double px = this.getX() + vecX ;
        double pz = this.getZ() + vecZ;
        double firstAngleOffset = (number - 1) / 2.0 * anglestep;
        DamageSource damagesource = CMDamageTypes.causeLightningMobDamage(this);
        for (int i = 0; i < number; i++) {
            double angle = yBodyRot + 90 - firstAngleOffset + (i * anglestep);
            float f1 = (float) Math.cos(Math.toRadians(angle));
            float f2 = (float) Math.sin(Math.toRadians(angle));

            AABB attackRange = new AABB(
                    px - inflateXZ, this.getY() - inflateY, pz - inflateXZ,
                    px + inflateXZ, this.getY() + inflateY, pz + inflateXZ
            ).expandTowards(f1 * range * 0.75, 0, f2 * range * 0.75);

            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, attackRange)) {
                if (!isAlliedTo(entity) && entity != this) {
                    entity.hurt(damagesource, (float) (this.getAttributeValue(Attributes.ATTACK_DAMAGE) * damage + Math.min((float) (this.getAttributeValue(Attributes.ATTACK_DAMAGE) * damage), entity.getMaxHealth() * hpdamage)));

                }
            }

            if (this.level().isClientSide) {
                double d0 = px + f1 * range;
                double d1 = this.getY() + 0.3;
                double d2 = pz + f2 * range;
                this.level().addParticle(new CircleLightningParticleOptions(0.1F,143, 241, 215), px, this.getY(), pz, d0+ (random.nextFloat() - 0.5F) * 2, d1, d2+ (random.nextFloat() - 0.5F) * 2);

            }

        }
    }

@Override
	public void onUpdate(){

		double extensionSpeed = 0;

		if(!world.isRemote){
			if(lifetime - this.ticksExisted < 15){
				extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 15));
			}else if(lifetime - this.ticksExisted < 25){
				extensionSpeed = 0;
			}else if(lifetime - this.ticksExisted < 28){
				extensionSpeed = 0.25;
			}

			if(facing != null){ // Will probably be null on the client side, but should never be on the server side
				this.move(MoverType.SELF, this.facing.getXOffset() * extensionSpeed, this.facing.getYOffset() * extensionSpeed,
						this.facing.getZOffset() * extensionSpeed);
			}
		}

		if(lifetime - this.ticksExisted == 30) this.playSound(WizardrySounds.ENTITY_ICE_SPIKE_EXTEND, 1, 2.5f);

		if(!this.world.isRemote){
			for(Object entity : this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox())){
				if(entity instanceof EntityLivingBase && this.isValidTarget((EntityLivingBase)entity)){
					DamageSource source = this.getCaster() == null ? DamageSource.MAGIC : MagicDamage.causeDirectMagicDamage(this.getCaster(), DamageType.FROST);
					// Potion effect only gets added if the damage succeeded
					// We DO want knockback here or the entity gets stuck on the spike, which is a bit of a cheat
					if(((EntityLivingBase)entity).attackEntityFrom(source, Spells.ice_spikes.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier))
						((EntityLivingBase)entity).addPotionEffect(new PotionEffect(WizardryPotions.frost,
								Spells.ice_spikes.getProperty(Spell.EFFECT_DURATION).intValue(),
								Spells.ice_spikes.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}
			}
		}

		super.onUpdate();
	}

public static void sweepAttack(ItemStack itemStack, LivingEntity target, LivingEntity attacker, int sweepingLevel) {
        boolean trueSweep = EffectHelper.getEffectLevel(itemStack, ItemEffect.truesweep) > 0;
        float damage = (float) Math.max(attacker.getAttributeValue(Attributes.ATTACK_DAMAGE) * (sweepingLevel * 0.125f), 1);
        float knockback = trueSweep ? (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack) + 1) * 0.5f : 0.5f;
        double range = 1 + EffectHelper.getEffectEfficiency(itemStack, ItemEffect.sweeping);
        double reach = attacker.getAttributeValue(ForgeMod.ENTITY_REACH.get());

        // range values set up to mimic vanilla behaviour
        attacker.level().getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(range, 0.25d, range)).stream()
                .filter(entity -> entity != attacker)
                .filter(entity -> entity != target)
                .filter(entity -> !attacker.isAlliedTo(entity))
                .filter(entity -> attacker.distanceToSqr(entity) < (range + reach) * (range + reach))
                .forEach(entity -> {
                    entity.knockback(knockback,
                            Mth.sin(attacker.getYRot() * (float) Math.PI / 180F),
                            -Mth.cos(attacker.getYRot() * (float) Math.PI / 180F));

                    DamageSource damageSource = attacker instanceof Player
                            ? attacker.damageSources().playerAttack((Player) attacker)
                            : attacker.damageSources().mobAttack(attacker);

                    if (trueSweep) {
                        ItemEffectHandler.applyHitEffects(itemStack, entity, attacker);
                        EffectHelper.applyEnchantmentHitEffects(itemStack, entity, attacker);

                        causeTruesweepDamage(damageSource, damage, itemStack, attacker, entity);
                    } else {
                        entity.hurt(damageSource, damage);
                    }

                });

        attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
                SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

        CastOptional.cast(attacker, Player.class).ifPresent(Player::sweepAttack);
    }

@SubscribeEvent
    public static void onEntityHit(LivingAttackEvent event)
    {
        if (event.getSource().getEntity() instanceof Player attacker && !(event.getEntity() instanceof Player))
        {
            Level level = attacker.level();
            ItemStack stack = attacker.getMainHandItem();
            if (!(stack.getItem() instanceof SoulspringLampItem)) return;

            LivingEntity target = event.getEntity();

            // If fuel < 64 and target NOT player
            if (getFuel(stack) < 64
            && target.getMobType() != MobType.UNDEAD
            && !target.getPersistentData().getBoolean("SoulSucked"))
            {
                target.getPersistentData().putBoolean("SoulSucked", true);

                // Add fuel
                addFuel(stack, (int) Math.min(8, target.getMaxHealth() / 2));
                float extraDamage = Math.max(0, 8 - event.getAmount());
                if (extraDamage > 0)
                    target.hurt(level.damageSources().playerAttack(attacker), extraDamage);

                // Spawn particles
                if (!target.level().isClientSide)
                {
                    int particleCount = (int) CSMath.clamp(target.getBbWidth() * target.getBbWidth() * target.getBbHeight() * 3, 5, 50);
                    WorldHelper.spawnParticleBatch(attacker.level(), ParticleTypes.SOUL, target.getX(), target.getY() + target.getBbHeight() / 2, target.getZ(),
                                                   target.getBbWidth() / 2, target.getBbHeight() / 2, target.getBbWidth() / 2, particleCount, 0.05);
                }
                // Play soul stealing sound
                if (attacker.level().isClientSide)
                {   WorldHelper.playEntitySound(ModSounds.SOUL_LAMP_ON, attacker, attacker.getSoundSource(), 1f, (float) Math.random() / 5f + 1.3f);
                }
            }
        }
    }

public static void tremor(LivingEntity livingEntity, int distance, double topY, float side, float damage, float airborne) {
        int hitY = Mth.floor(livingEntity.getBoundingBox().minY - 0.5D);
        double minY = livingEntity.getY() - 2.0D;
        double maxY = livingEntity.getY() + topY;
        float angle = (float) ((Math.PI / 180.0F) * livingEntity.yHeadRot);
        float f = Mth.cos(livingEntity.yHeadRot * ((float) Math.PI / 180F));
        float f1 = Mth.sin(livingEntity.yHeadRot * ((float) Math.PI / 180F));
        double extraX = distance * Mth.sin((float) (Math.PI + angle));
        double extraZ = distance * Mth.cos(angle);
        double px = livingEntity.getX() + extraX + f * side;
        double pz = livingEntity.getZ() + extraZ + f1 * side;
        int hitX = Mth.floor(px);
        int hitZ = Mth.floor(pz);
        BlockPos blockPos = new BlockPos(hitX, hitY, hitZ);
        BlockPos abovePos = new BlockPos(blockPos).above();
        BlockState blockState = livingEntity.level.getBlockState(blockPos);
        BlockState blockAbove = livingEntity.level.getBlockState(abovePos);

        if (blockState != Blocks.AIR.defaultBlockState() && !blockState.hasBlockEntity() && !blockAbove.blocksMotion()) {
            ModFallingBlock fallingBlock = new ModFallingBlock(livingEntity.level, Vec3.atCenterOf(blockPos.above()), blockState, (float) (0.2D + livingEntity.getRandom().nextGaussian() * 0.15D));
            livingEntity.level.addFreshEntity(fallingBlock);
        }
        AABB selection = new AABB(px - 0.5D, minY, pz - 0.5D, px + 0.5D, maxY, pz + 0.5D);
        List<LivingEntity> entities = livingEntity.level.getEntitiesOfClass(LivingEntity.class, selection);
        for (LivingEntity target : entities) {
            if (!MobUtil.areAllies(target, livingEntity) && target != livingEntity) {
                boolean flag = target.hurt(livingEntity.damageSources().mobAttack(livingEntity), damage);
                if (flag) {
                    MobUtil.push(target, 0.0D, (double) (airborne * (float) distance) + livingEntity.getRandom().nextDouble() * 0.15D, 0.0D);
                }
            }
        }
        if (distance % 4 == 0) {
            livingEntity.level.playSound(null, blockPos.above(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            livingEntity.level.playSound(null, blockPos.above(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            livingEntity.level.playSound(null, blockPos.above(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
        }
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        int range = spellStat.getRange();
        if (WandUtil.enchantedFocus(caster)) {
            potency += WandUtil.getPotencyLevel(caster);
            duration += WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
            range += WandUtil.getRangeLevel(caster);
        }
        float damage = this.damage + potency;
        if (!worldIn.isClientSide) {
            for (Entity target : getBreathTarget(caster, range)) {
                if (target != null) {
                    if (target.hurt(ModDamageSource.swarm(caster, caster), damage)){
                        if (rightStaff(staff)) {
                            if (target instanceof LivingEntity livingTarget) {
                                MobEffect mobEffect = MobEffects.POISON;
                                if (CuriosFinder.hasWildRobe(caster)) {
                                    mobEffect = GoetyEffects.ACID_VENOM.get();
                                }
                                livingTarget.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(5) * duration));
                            }
                        }
                        if (!target.isAlive()){
                            InsectSwarm insectSwarm = new InsectSwarm(worldIn, caster, target.position());
                            insectSwarm.setLimitedLife(200 * duration);
                            if (potency > 0){
                                insectSwarm.addEffect(new MobEffectInstance(GoetyEffects.BUFF.get(), EffectsUtil.infiniteEffect(), potency - 1, false, false));
                            }
                            worldIn.addFreshEntity(insectSwarm);
                        }
                    }
                }
            }
        }
        this.playSound(worldIn, caster, ModSounds.INSECT_SWARM.get(), worldIn.random.nextFloat() * 0.5F, worldIn.random.nextFloat() * 0.5F);
    }

@Override
	public boolean attackEntityFrom(DamageSource source, float damage) {
		if(source != DamageSource.IN_WALL) {
			if(source instanceof EntityDamageSource) {
				Entity direct = ((EntityDamageSource) source).getImmediateSource();
				if(direct instanceof EntityPlayer) {
					EntityPlayer player = (EntityPlayer) direct;

					ItemStack held = player.getHeldItem(EnumHand.MAIN_HAND);

					if(!held.isEmpty() && held.getItem() == ItemRegistry.DENTROTHYST_VIAL && held.getItemDamage() != 1) {
						if(this.world.isRemote) {
							for(int i = 0; i < 10; i++) {
								this.world.spawnParticle(EnumParticleTypes.CRIT, this.posX + this.motionX, this.posY + this.motionY + this.height * 0.5f, this.posZ + this.motionZ, -this.motionX + (this.rand.nextFloat() - 0.5f), -this.motionY + 0.2D + (this.rand.nextFloat() - 0.5f), -this.motionZ + (this.rand.nextFloat() - 0.5f));
							}
						}

						if(super.attackEntityFrom(source, damage * 3.0f)) {
							if(!this.world.isRemote) {
								if(!this.isEntityAlive()) {
									held.shrink(1);
									ItemHandlerHelper.giveItemToPlayer(player, ItemRegistry.DENTROTHYST_FLUID_VIAL.withFluid(held.getItemDamage() == 2 ? 1 : 0, FluidRegistry.SHALLOWBREATH));
								}

								this.world.playSound(null, player.posX, player.posY, player.posZ, FluidRegistry.SHALLOWBREATH.getFillSound(new FluidStack(FluidRegistry.SHALLOWBREATH, 1000)), SoundCategory.BLOCKS, 1.0F, 1.0F);
							}

							return true;
						}

						return false;
					}
				}
			}

			return super.attackEntityFrom(source, damage);
		}
		return false;
	}

@Override
	protected void onHitEntity(@NotNull EntityHitResult result) {
		super.onHitEntity(result);
		if (this.level().isClientSide) {
			return;
		}
		Entity entity = result.getEntity();
		if (entity.getType() == EntityType.GHAST && this.level().dimension() == Level.OVERWORLD) {
			this.level().levelEvent(LevelEvent.PARTICLES_SPELL_POTION_SPLASH, blockPosition(), PARTICLE_COLOR);
			DamageSource source = entity.damageSources().thrown(this, getOwner());
			entity.hurt(source, 0);

			// Ghasts render as if they are looking straight ahead, but the look y component
			// can actually be nonzero, correct for that
			Vec3 lookVec = entity.getLookAngle();
			Vec3 vec = new Vec3(lookVec.x(), 0, lookVec.z()).normalize();

			// Position chosen to appear roughly in the ghast's face
			((ServerLevel) this.level()).sendParticles(new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(Items.GHAST_TEAR)),
					entity.getX() + (2.3 * vec.x), entity.getY() + vec.y + 2.6, entity.getZ() + (2.3 * vec.z),
					40,
					Math.abs(vec.z) + 0.15, 0.2, Math.abs(vec.x) + 0.15, 0.2);

			LootTable table = this.level().getServer().getLootData().getLootTable(GHAST_LOOT_TABLE);
			LootParams.Builder builder = new LootParams.Builder(((ServerLevel) level()));
			builder.withParameter(LootContextParams.THIS_ENTITY, entity);
			builder.withParameter(LootContextParams.ORIGIN, entity.position());
			builder.withParameter(LootContextParams.DAMAGE_SOURCE, source);

			LootParams context = builder.create(LootContextParamSets.ENTITY);
			for (ItemStack stack : table.getRandomItems(context)) {
				ItemEntity item = entity.spawnAtLocation(stack, 2);
				item.setDeltaMovement(item.getDeltaMovement().add(vec.scale(0.4)));
			}
		} else {
			convertBlock(BlockPos.containing(result.getLocation()));
		}
		discard();
	}

public void tick() {
        // Entity.super
        if (!this.level.isClientSide) {
            this.setSharedFlag(6, this.isCurrentlyGlowing());
        }
        this.baseTick();
        if (this.level.isClientSide) {
            if (this.clientSideAttackStarted) {
                --this.lifeTicks;
                if (this.lifeTicks == 14) {
                    for (int i = 0; i < 12; ++i) {
                        double d0 = this.getX() + (this.random.nextDouble() * 2.0D - 1.0D) * (double) this.getBbWidth() * 0.5D;
                        double d1 = this.getY() + 0.05D + this.random.nextDouble();
                        double d2 = this.getZ() + (this.random.nextDouble() * 2.0D - 1.0D) * (double) this.getBbWidth() * 0.5D;
                        double d3 = (this.random.nextDouble() * 2.0D - 1.0D) * 0.3D;
                        double d4 = 0.3D + this.random.nextDouble() * 0.3D;
                        double d5 = (this.random.nextDouble() * 2.0D - 1.0D) * 0.3D;
                        this.level.addParticle(ParticleTypes.CRIT, d0, d1 + 1.0D, d2, d3, d4, d5);
                    }
                }
            }
        } else if (--this.warmupDelayTicks < 0) {
            if (this.warmupDelayTicks == -8) {
                for (LivingEntity livingentity : this.level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.2D, 0.0D, 0.2D))) {
                    this.damage(livingentity);
                }
            }

            if (!this.sentSpikeEvent) {
                this.level.broadcastEntityEvent(this, (byte) 4);
                this.sentSpikeEvent = true;
            }

            if (--this.lifeTicks < 0) {
                this.remove(RemovalReason.DISCARDED);
            }
        }

    }

@Override
        protected void checkAndPerformAttack(LivingEntity pEnemy) {
            this.attackTimer--;

            if (this.canPerformAttack(pEnemy)) {
                this.fairy.setMagicTarget(pEnemy);
                if (this.attackTimer <= 0) {
                    this.attackTimer = 10;
                    LivingEntity owner = this.fairy.getFamiliarOwner();
                    if (owner != null) {
                        AttributeInstance dmgInstance = this.fairy.getAttribute(Attributes.ATTACK_DAMAGE);
                        float dmg = dmgInstance == null ? 6 : (float) dmgInstance.getValue();
                        pEnemy.hurt(this.fairy.damageSources().mobAttack(owner), dmg/3);

                        int effect = this.fairy.hasIesniumUpgrade() ? this.fairy.level().getRandom().nextInt(5) :
                                this.fairy.hasBlacksmithUpgrade() ? this.fairy.level().getRandom().nextInt(3) : 0;
                        switch (effect) {
                            case 4 -> pEnemy.addEffect(new MobEffectInstance(MobEffects.WITHER, 40, 2));
                            case 3 -> pEnemy.addEffect(new MobEffectInstance(MobEffects.POISON, 40, 2));
                            case 2 -> pEnemy.addEffect(new MobEffectInstance(MobEffects.LEVITATION, 40, 0));
                            case 1 -> pEnemy.addEffect(new MobEffectInstance(MobEffects.GLOWING, 40, 0));
                            default -> pEnemy.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 40, 1));
                        }

                        List<LivingEntity> allies = this.fairy.level().getEntitiesOfClass(LivingEntity.class,
                                this.fairy.getBoundingBox().inflate(7), e -> e != this.fairy && e instanceof IFamiliar
                                        && ((IFamiliar) e).getFamiliarOwner() == owner);
                        int healing = this.fairy.hasIesniumUpgrade() ? 12 : this.fairy.hasBlacksmithUpgrade() ? 7 : 3;
                        for (LivingEntity ally : allies) {
                            ally.heal(healing);
                            ((ServerLevel) this.fairy.level()).sendParticles(ParticleTypes.HEART, ally.getX(),
                                    ally.getY() + ally.getBbHeight(), ally.getZ(), 1, 0, 0, 0, 1);
                        }
                    }
                }
            } else {
                this.fairy.setMagicTarget(null);
            }
        }

protected void onHitEntity(EntityHitResult p_37573_) {
