public void positionRider(Entity passenger, MoveFunction moveFunc) {
        double theta = (yBodyRot) * (Math.PI / 180);
        theta += Math.PI / 2;
        double vecX = Math.cos(theta);
        double vecZ = Math.sin(theta);
        double px = this.getX() + 0.7F * vecX;
        double pz = this.getZ() + 0.7F * vecZ;

        double y = this.getY() + passenger.getMyRidingOffset() + 0.6D;
        if (hasPassenger(passenger)) {
            if(this.getAttackState() == 6){
                if(this.attackTicks == 1) {
                    if(passenger instanceof LivingEntity living){
                        DamageSource damagesource =  CMDamageTypes.causeMaledictioDamage(this) ;
                        boolean flag = living.hurt(damagesource, (float) (this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 1.5F));
                        if(flag){
                            this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.9f);
                        }
                    }
                    if (!this.level().isClientSide) {
                        passenger.stopRiding();
                        Cataclysm.NETWORK_WRAPPER.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> passenger), new MessageEntityCamera(passenger.getId(),true));
                    }
                }
            }else if(this.getAttackState() == 5){
                if(this.attackTicks == 1) {
                    if (!this.level().isClientSide) {
                        passenger.stopRiding();
                        Cataclysm.NETWORK_WRAPPER.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> passenger), new MessageEntityCamera(passenger.getId(),true));
                    }
                }
            }else if (this.getAttackState() != 4){
                if (!this.level().isClientSide) {
                    passenger.stopRiding();
                    Cataclysm.NETWORK_WRAPPER.send(PacketDistributor.TRACKING_ENTITY_AND_SELF.with(() -> passenger), new MessageEntityCamera(passenger.getId(),true));
                }
            }
            moveFunc.accept(passenger, px, y, pz);
        }
    }

protected void onHitEntity(EntityHitResult hitResult) {
        Entity entity = hitResult.getEntity();
        float f = 10.0F;
        if (entity instanceof LivingEntity livingentity) {
            f += EnchantmentHelper.getDamageBonus(this.getPickupItem(), livingentity.getMobType());
        }

        Entity entity1 = this.getOwner();
        DamageSource damagesource = ACDamageTypes.causeSpiritDinosaurDamage(level().registryAccess(), (Entity) (entity1 == null ? this : entity1));
        this.dealtDamage = true;
        SoundEvent soundevent = ACSoundRegistry.EXTINCTION_SPEAR_HIT.get();
        entity.setSecondsOnFire(5);
        if (entity.hurt(damagesource, f)) {
            if (entity.getType() == EntityType.ENDERMAN) {
                return;
            }
            if (entity instanceof LivingEntity) {
                LivingEntity livingentity1 = (LivingEntity) entity;
                if (entity1 instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingentity1, entity1);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingentity1);
                }

                this.doPostHurtEffects(livingentity1);
            }
            if(entity1 != null){
                DinosaurSpiritEntity dinosaurSpirit = ACEntityRegistry.DINOSAUR_SPIRIT.get().create(level());
                dinosaurSpirit.setPos(entity.getX(), entity.getY() + entity.getBbHeight(), entity.getZ());
                dinosaurSpirit.setDinosaurType(DinosaurSpiritEntity.DinosaurType.SUBTERRANODON);
                dinosaurSpirit.setPlayerUUID(entity1.getUUID());
                dinosaurSpirit.setAttackingEntityId(entity.getId());
                dinosaurSpirit.lookAt(EntityAnchorArgument.Anchor.EYES, entity1.getEyePosition());
                dinosaurSpirit.setEnchantmentLevel(spearItem.getEnchantmentLevel(ACEnchantmentRegistry.PLUMMETING_FLIGHT.get()));
                this.playSound(ACSoundRegistry.EXTINCTION_SPEAR_SUMMON.get(), 1.0F, 1.0F);
                level().addFreshEntity(dinosaurSpirit);
            }
        }
        this.setDeltaMovement(this.getDeltaMovement().multiply(-0.01D, -0.1D, -0.01D));
        float f1 = 1.0F;
        this.playSound(soundevent, f1, 1.0F);
    }

@Override
        public void tick() {
            checkForMobsTime--;
            LivingEntity target = GammaroachEntity.this.getTarget();
            if (target != null && target.isAlive()) {
                if (checkForMobsTime < 0) {
                    checkForMobsTime = 120 + GammaroachEntity.this.random.nextInt(100);
                    Predicate<Entity> monsterAway = (animal) -> animal instanceof Enemy && !(animal instanceof GammaroachEntity) && animal.distanceTo(target) > 5 && !animal.isPassenger();
                    List<Mob> list = GammaroachEntity.this.level().getEntitiesOfClass(Mob.class, GammaroachEntity.this.getBoundingBox().inflate(30, 12, 30), EntitySelector.NO_SPECTATORS.and(monsterAway));
                    list.sort(Comparator.comparingDouble(GammaroachEntity.this::distanceToSqr));
                    if (!list.isEmpty()) {
                        pickupMonster = list.get(0);
                    }
                }
                if (pickupMonster == null || pickupMonster.isPassengerOfSameVehicle(GammaroachEntity.this)) {
                    GammaroachEntity.this.getNavigation().moveTo(target, 1.0D);
                    GammaroachEntity.this.lookAt(target, 180, 30);
                    if (GammaroachEntity.this.distanceTo(target) < 1.5F + target.getBbWidth()) {
                        if (GammaroachEntity.this.getAnimation() == NO_ANIMATION) {
                            GammaroachEntity.this.setAnimation(GammaroachEntity.ANIMATION_RAM);
                        } else if (GammaroachEntity.this.getAnimation() == GammaroachEntity.ANIMATION_RAM && GammaroachEntity.this.getAnimationTick() > 8 && GammaroachEntity.this.getAnimationTick() < 15) {
                            GammaroachEntity.this.playSound(ACSoundRegistry.GAMMAROACH_ATTACK.get());
                            target.hurt(damageSources().mobAttack(GammaroachEntity.this), (float) GammaroachEntity.this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        }
                        if (pickupMonster != null) {
                            pickupMonster.stopRiding();
                            pickupMonster = null;
                        }
                    }
                } else if (pickupMonster.isAlive() && (!pickupMonster.isPassenger())) {
                    GammaroachEntity.this.getNavigation().moveTo(pickupMonster, 1.0D);
                    GammaroachEntity.this.lookAt(pickupMonster, 180, 30);
                    if (GammaroachEntity.this.distanceTo(pickupMonster) < 1.5F + pickupMonster.getBbWidth()) {
                        pickupMonster.startRiding(GammaroachEntity.this, true);
                        pickupMonster.hurt(damageSources().cactus(), 1);
                    }
                } else {
                    pickupMonster = null;
                }
            }
        }

public void onUse(World world, BlockPos pos, PlayerEntity player, Hand hand) {
		if (!getCachedState().get(Properties.WATERLOGGED)) {
			ItemStack stack = player.getStackInHand(hand);
			if (getCachedState().get(Properties.LIT)) {
				world.setBlockState(pos, getCachedState().with(Properties.LIT, false));
				world.playSound(null, pos, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 1, 2);
				reset(hasIncense);
				syncBrazier();
			} else {
				if (stack.getItem() instanceof FlintAndSteelItem) {
					world.setBlockState(pos, getCachedState().with(Properties.LIT, true));
					world.playSound(null, pos, SoundEvents.ITEM_FLINTANDSTEEL_USE, SoundCategory.BLOCKS, 1, 1);
					stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(hand));
					IncenseRecipe foundIncenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
					if (foundIncenseRecipe != null) {
						incenseRecipe = foundIncenseRecipe;
						timer = -6000;
						hasIncense = true;
						syncBrazier();
					} else if (BWConfig.enableCurses) {
						CurseRecipe foundCurseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
						if (foundCurseRecipe != null && getTarget() != null) {
							curseRecipe = foundCurseRecipe;
							timer = -100;
							syncBrazier();
						}
					}
				} else if (!stack.isEmpty()) {
					int firstEmpty = getFirstEmptySlot();
					if (firstEmpty != -1) {
						setStack(firstEmpty, stack.split(1));
						syncBrazier();
					}
				} else {
					reset(hasIncense);
					syncBrazier();
				}
			}
		}
		markDirty();
	}

public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat){
        float potency = spellStat.getPotency();
        int range = spellStat.getRange();
        int burning = spellStat.getBurning();
        if (WandUtil.enchantedFocus(caster)) {
            potency += WandUtil.getPotencyLevel(caster);
            range += WandUtil.getRangeLevel(caster);
            burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
        }
        float damage = SpellConfig.WaterJetDamage.get().floatValue() * WandUtil.damageMultiply();
        damage += potency;
        HitResult result = this.rayTrace(worldIn, caster, range, 3.0F);
        if (result.getType() != HitResult.Type.MISS) {
            double particleOffset = 0;
            if (result instanceof EntityHitResult entityHitResult) {
                Entity target = entityHitResult.getEntity();
                if (!MobUtil.areAllies(caster, target)) {
                    MiscCapHelper.setClientTarget(caster, target);
                    if (target.hurt(ModDamageSource.directDrench(caster), damage)) {
                        if (this.rightStaff(staff) && target instanceof LivingEntity livingEntity) {
                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), MathHelper.secondsToTicks(5)));
                        }
                    }
                }
                if (burning <= 0) {
                    target.clearFire();
                } else if (!MobUtil.areAllies(caster, target)) {
                    target.setSecondsOnFire(5 * burning);
                }
                particleOffset = target.getBbHeight() / 2;
            } else if (result instanceof BlockHitResult blockHitResult) {
                BlockPos blockPos = blockHitResult.getBlockPos();
                this.dowseFire(caster, worldIn, blockPos);
            }
            Vec3 vec3 = result.getLocation();
            worldIn.sendParticles(ModParticleTypes.WATER_TRAIL.get(), vec3.x, vec3.y + particleOffset, vec3.z, 1, 0, 0, 0, 0.15);
        }
        if (result.getType() == HitResult.Type.MISS || !(result instanceof EntityHitResult)) {
            MiscCapHelper.setClientTarget(caster, null);
        }
    }

@Override
    public void tick() {
        super.tick();
        if (!level().isClientSide()) {
            int temp = entityData.get(TIMER);
            if (watchedEntities != null && source != null) {
                if (!watchedEntities.isEmpty()) {
                    List<YUnchangedLivingEntity> entitiesRemoveFromWatchList = new ArrayList<>();
                    for (YUnchangedLivingEntity entity : watchedEntities) {
                        if (entity.livingEntity.horizontalCollision) {
                            if (!entity.livingEntity.isAlliedTo(source)) {
                                entity.livingEntity.invulnerableTime = 0;
                                float realDamageApplied = damagePerEffectiveCharge * effectiveChargeTime + 1;
                                boolean flag = entity.livingEntity.hurt(this.damageSources().mobProjectile(this, source), realDamageApplied);
                                if (flag) {
                                    entity.livingEntity.playSound(ModSounds.EXPLOSION.get(), 0.3F, 1);
                                    entity.livingEntity.addEffect(new MobEffectInstance(ModEffect.EFFECTSTUN.get(), 50));
                                }
                            }

                            entitiesRemoveFromWatchList.add(entity);
                        } else {
                            entity.setMotion(dx * knockbackSpeedIndex, dz * knockbackSpeedIndex);
                        }
                    }
                    for (YUnchangedLivingEntity remove : entitiesRemoveFromWatchList) {
                        removeFromWatchList(remove);
                    }
                    if (temp - 1 == 0) {
                        watchedEntities.clear();
                        remove(RemovalReason.DISCARDED);
                    } else entityData.set(TIMER, temp - 1);
                } else {
                    if (temp - 1 == 0) remove(RemovalReason.DISCARDED);
                    else entityData.set(TIMER, temp - 1);
                }
            } else {
                remove(RemovalReason.DISCARDED);
            }
        }
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (source.is(DamageTypeTags.IS_FALL)) return false;
        if (source.is(DamageTypes.LAVA) && getAnimation() == NO_ANIMATION) {
            AnimationHandler.INSTANCE.sendAnimationMessage(this, DODGE_ANIMATION);
        }

        if (source.is(DamageTypeTags.IS_FIRE)) damage *= 1.25;

        if (source.getDirectEntity() instanceof AbstractArrow) {
            playSound(MMSounds.ENTITY_WROUGHT_UNDAMAGED.get(), 0.4F, 2);
            Entity entity = source.getEntity();
            if (entity != null && entity instanceof LivingEntity && (!(entity instanceof Player) || !((Player)entity).isCreative()) && getTarget() == null && !(entity instanceof EntityFrostmaw)) setTarget((LivingEntity) entity);
            if (!getActive()) {
                if (getAnimation() != DIE_ANIMATION) {
                    if (level().getDifficulty() != Difficulty.PEACEFUL) {
                        if (getHasCrystal()) AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_ANIMATION);
                        else AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_NO_CRYSTAL_ANIMATION);
                    }
                }
                if (level().getDifficulty() != Difficulty.PEACEFUL) setActive(true);
            }
            return false;
        }

        boolean attack = super.hurt(source, damage);

        if (attack) {
            shouldDodgeMeasure += damage;
            Entity entity = source.getEntity();
            if (entity != null && entity instanceof LivingEntity && (!(entity instanceof Player) || !((Player)entity).isCreative()) && getTarget() == null && !(entity instanceof EntityFrostmaw)) setTarget((LivingEntity) entity);
            if (!getActive()) {
                if (getAnimation() != DIE_ANIMATION && level().getDifficulty() != Difficulty.PEACEFUL) {
                    if (getHasCrystal()) AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_ANIMATION);
                    else AnimationHandler.INSTANCE.sendAnimationMessage(this, ACTIVATE_NO_CRYSTAL_ANIMATION);
                }
                if (level().getDifficulty() != Difficulty.PEACEFUL) setActive(true);
            }
        }

        return attack;
    }

public void onUpdate(){

		if(this.ticksExisted % 40 == 1){
			this.playSound(WizardrySounds.ENTITY_FIRE_RING_AMBIENT, 4.0f, 0.7f);
		}

		super.onUpdate();

		if(this.ticksExisted % 5 == 0 && !this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2, this.posX, this.posY, this.posZ, this.height, this.world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					double velX = target.motionX;
					double velY = target.motionY;
					double velZ = target.motionZ;

					if(!MagicDamage.isEntityImmune(DamageType.FIRE, target)){

						target.setFire(Spells.ring_of_fire.getProperty(Spell.BURN_DURATION).intValue());

						float damage = Spells.ring_of_fire.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

						if(this.getCaster() != null){
							target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
									DamageType.FIRE), damage);
						}else{
							target.attackEntityFrom(DamageSource.MAGIC, damage);
						}
					}

					// Removes knockback
					target.motionX = velX;
					target.motionY = velY;
					target.motionZ = velZ;
				}
			}
		}
	}

private void onImpactEntity(EntityHitResult entityRayTrace) {
    Entity entityHit = entityRayTrace.getEntity();
    if (entityHit == null || !entityHit.isAlive()) {
      return;
    }
    Entity owner = getOwner();
    if (owner == entityHit) {
      //player catch it on return 
      dropAsItem();
      return;
    }
    switch (this.boomerangType) {
      case CARRY:
        if (!entityHit.level().isClientSide) {
          entityHit.startRiding(this);
        }
      break;
      case DAMAGE:
        if (entityHit instanceof LivingEntity) {
          LivingEntity live = (LivingEntity) entityHit;
          float damage = Mth.nextFloat(level().random, ConfigRegistry.BOOMERANG_DAMAGE_MIN.get().floatValue(), ConfigRegistry.BOOMERANG_DAMAGE_MAX.get().floatValue());
          boolean attackSucc = live.hurt(level().damageSources().thrown(this, owner), damage);
          if (attackSucc && live.isAlive() == false) {
            //           ("killed one");
          }
        }
      break;
      case STUN:
        //!entityHit.getUniqueID().equals(owner.getUniqueID()) 
        if (entityHit != owner && entityHit instanceof LivingEntity
            && !(entityHit instanceof Player)) {
          LivingEntity live = (LivingEntity) entityHit;
          if (!live.hasEffect(PotionEffectRegistry.STUN)) {
            live.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, ConfigRegistry.BOOMERANG_STUN_SECONDS.get() * Const.TICKS_PER_SEC, 1, false, true, true));
            SoundUtil.playSound(live, SoundEvents.IRON_GOLEM_ATTACK);
          }
        }
      break;
      default:
      break;
    }
  }

