@Override
	public void onUpdate(){

		super.onUpdate();

		if(!this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2, this.posX, this.posY, this.posZ, this.height, this.world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					double velX = target.motionX;
					double velY = target.motionY;
					double velZ = target.motionZ;

					target.attackEntityFrom(this.getCaster() != null
							? MagicDamage.causeIndirectMagicDamage(this, this.getCaster(), DamageType.FIRE)
							: DamageSource.MAGIC, Spells.fire_sigil.getProperty(Spell.DAMAGE).floatValue()
							* damageMultiplier);

					// Removes knockback
					target.motionX = velX;
					target.motionY = velY;
					target.motionZ = velZ;

					if(!MagicDamage.isEntityImmune(DamageType.FIRE, target))
						target.setFire(Spells.fire_sigil.getProperty(Spell.BURN_DURATION).intValue());

					this.playSound(WizardrySounds.ENTITY_FIRE_SIGIL_TRIGGER, 1, 1);

					// The trap is destroyed once triggered.
					this.setDead();
				}
			}
		}else if(this.rand.nextInt(15) == 0){
			double radius = (0.5 + rand.nextDouble() * 0.3) * width/2;
			float angle = rand.nextFloat() * (float)Math.PI * 2;
			world.spawnParticle(EnumParticleTypes.FLAME, this.posX + radius * MathHelper.cos(angle), this.posY + 0.1,
					this.posZ + radius * MathHelper.sin(angle), 0, 0, 0);
		}
	}

@Override
    public boolean hurt(DamageSource source, float amount) {
        boolean flag = false;
        if (amount > 0.0F && this.isDamageSourceBlocked(source)) {
            net.minecraftforge.event.entity.living.ShieldBlockEvent ev = net.minecraftforge.common.ForgeHooks.onShieldBlock(this, source, amount);
            if(!ev.isCanceled()) {
                if(ev.shieldTakesDamage()) {
                    this.hurtCurrentlyUsedShield(amount);
                }
                amount -= ev.getBlockedDamage();
                if (!source.is(DamageTypeTags.IS_PROJECTILE)) {
                    Entity entity = source.getDirectEntity();
                    if (entity instanceof LivingEntity) {
                        this.blockUsingShield((LivingEntity)entity);
                    }
                }

                flag = true;
            }
        }
        if (source.is(DamageTypeTags.IS_FIRE) && !source.is(DamageTypes.LAVA)){
            return false;
        }
        if (flag) {
            this.playSound(SoundEvents.SHIELD_BLOCK, 1.0F, 0.8F + this.level.random.nextFloat() * 0.4F);
            this.level.broadcastEntityEvent(this, (byte)29);
            if (amount <= 1.0F){
                return false;
            }
        }
        if (!this.isGuarding() && this.coolTime > 0 && !this.canDisableShield(source) && !source.is(DamageTypeTags.BYPASSES_ARMOR)){
            this.coolTime -= (int) (amount * 10);
        }
        if (this.level instanceof ServerLevel serverLevel && !this.isDamageSourceBlocked(source)){
            if (!this.getItemBySlot(EquipmentSlot.CHEST).isEmpty()) {
                int j = (int) Math.min(amount, 10);
                for (int i = 0; i < j; ++i) {
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, new ItemParticleOption(ParticleTypes.ITEM, this.getItemBySlot(EquipmentSlot.CHEST)), this);
                }
            }
        }
        return super.hurt(source, amount);
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        int particles = 5;
        int efficiency = 0;
        boolean damage = false;
        if (!this.level.isClientSide && !this.isEmerging()) {
            if (pSource.is(DamageTypeTags.IS_EXPLOSION) || pSource.is(DamageTypeTags.IS_FIRE)){
                return false;
            }
            if (this.empowered > 0 && !pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)){
                this.level.broadcastEntityEvent(this, (byte) 6);
                this.playSound(SoundEvents.LAVA_EXTINGUISH, 1.0F, 0.5F);
                if (pSource.is(DamageTypes.IN_WALL)){
                    if (this.destroyBlocksTick <= 0) {
                        this.destroyBlocksTick = 20;
                    }
                }
                return false;
            }
            if (pSource.is(DamageTypes.IN_WALL) || pSource.is(DamageTypes.OUTSIDE_BORDER)){
                if (this.getTrueOwner() instanceof Apostle apostle) {
                    this.teleportTowards(apostle);
                }
            }
            if (ModDamageSource.physicalAttacks(pSource)) {
                if (pSource.getDirectEntity() instanceof LivingEntity living) {
                    if (living.getMainHandItem().isCorrectToolForDrops(this.getState())){
                        damage = true;
                        efficiency += EnchantmentHelper.getBlockEfficiency(living);
                    }
                }
            }
            if (damage){
                pAmount *= 2.0F + (efficiency / 2.0F);
                particles = 20;
            }
            if (this.level instanceof ServerLevel serverLevel){
                for(int i = 0; i < particles; ++i) {
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, this.getParticles(), this);
                }
            }
        }
        return super.hurt(pSource, pAmount);
    }

public void chainCharge(ServerLevel serverLevel, LivingEntity pTarget, LivingEntity pAttacker, double range) {
        List<Entity> harmed = new ArrayList<>();
        Predicate<Entity> selector = entity -> entity instanceof LivingEntity livingEntity && !harmed.contains(livingEntity);
        if (pAttacker != null){
            selector = selector.and(entity -> entity instanceof LivingEntity livingEntity && livingEntity != pAttacker && pTarget instanceof OwnableEntity ownable && ownable.getOwner() == pAttacker);
        }
        Entity prevTarget = pTarget;

        int hops = serverLevel.isThundering() ? 8 : 4;

        for (int i = 0; i < hops; i++) {
            AABB aabb = new AABB(Vec3Util.subtract(prevTarget.position(), range), Vec3Util.add(prevTarget.position(), range));
            Entity finalPrevTarget = prevTarget;
            List<Entity> entities = serverLevel.getEntities(prevTarget, aabb, selector.and(entity -> MobUtil.hasLineOfSight(finalPrevTarget, entity)));
            if (!entities.isEmpty()) {
                Entity entity = entities.get(serverLevel.getRandom().nextInt(entities.size()));
                if (entity instanceof LivingEntity target) {
                    if (!target.hasEffect(GoetyEffects.CHARGED.get())) {
                        this.playSound(serverLevel, target, 1.0F, 0.5F);
                        target.addEffect(new MobEffectInstance(GoetyEffects.CHARGED.get(), MathHelper.secondsToTicks(30), 0, false, false));
                    } else {
                        MobEffectInstance instance = target.getEffect(GoetyEffects.CHARGED.get());
                        if (instance != null) {
                            if (instance.getAmplifier() >= 1) {
                                target.hurt(ModDamageSource.directShock(pAttacker), SpellConfig.ChargeDamage.get().floatValue());
                            } else {
                                this.playSound(serverLevel, target, 1.0F, 0.75F);
                            }
                            EffectsUtil.amplifyEffect(target, GoetyEffects.CHARGED.get(), MathHelper.secondsToTicks(30), 3, false, false);
                        }
                    }
                    if (prevTarget != target) {
                        Vec3 vec3 = prevTarget.getEyePosition();
                        Vec3 vec31 = target.getEyePosition();
                        ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, 5));
                    }

                    harmed.add(target);
                    prevTarget = target;
                }
            }
        }
    }

@Override
    public void render(EntropyChargeProjectile entity, float entityYaw, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int packedLightIn) {
        super.render(entity, entityYaw, partialTicks, poseStack, bufferIn, packedLightIn);
        if (entity.isAwaitingSpawn()) {
            return;
        }

        var builder = VFXBuilders.createWorld().replaceBufferSource(LodestoneRenderingSystem.LATE_DEFERRED_RENDER);
        float delta = Math.min(entity.primedTime / 40f, 1) * entity.getVisualEffectScalar();
        float timeDelta = ((entity.level().getGameTime() + partialTicks) % 80L) / 80f;
        for (int i = 0; i < 6; i++) {
            float angleDelay = i * 0.75f;
            float offset = (0.8f - i * 0.1f) * delta;
            float angle = (timeDelta * 6.28f - angleDelay) % 6.28f;
            float x = Mth.sin(angle) * offset;
            float y = Mth.sin(angle) * offset*0.4f;
            float z = Mth.cos(angle) * offset;
            float falloff = (1 - i * 0.1f);
            var primaryColor = ColorHelper.darker(this.primaryColor, i);
            var secondaryColor = ColorHelper.darker(this.secondaryColor, i);
            float scale = 0.4f * delta * falloff;
            var texture = switch (Mth.floor(i/2f)) {
                case 0 -> ENTROPY_CHARGE;
                case 1 -> ENTROPY_CHARGE_SECONDARY;
                default -> ENTROPY_CHARGE_TRINARY;
            };

            poseStack.pushPose();
            poseStack.translate(x, y, z);
            poseStack.mulPose(Minecraft.getInstance().getEntityRenderDispatcher().cameraOrientation());
            for (int j = 0; j < 2; j++) {
                float alpha = (j == 1 ? 0.3f : 1.0f) * falloff;
                var renderType = j == 1 ? LodestoneRenderTypes.ADDITIVE_DISTORTED_TEXTURE : LodestoneRenderTypes.TRANSPARENT_DISTORTED_TEXTURE;
                var wawawawa = renderType.apply(texture).addUniformData(UniformData.LUMITRANSPARENT);

                builder.setRenderType(wawawawa)
                        .setColor(primaryColor, 0.8f * alpha).renderQuad(poseStack, scale)
                        .setColor(secondaryColor, 0.6f * alpha).renderQuad(poseStack, scale)
                        .setColor(secondaryColor, 0.4f * alpha).renderQuad(poseStack, scale);
            }
            poseStack.popPose();
        }
    }

@Override
    protected void onHitEntity(@NotNull EntityHitResult pResult) {
        if (!hurtEntities)
            return;
        super.onHitEntity(pResult);
        Entity entity = pResult.getEntity();
        float f = (float) this.getDeltaMovement().length();
        int i = Mth.ceil(Mth.clamp((Math.min(f, 2.5) * this.baseDamage) + getStateDamageBonus(), 0.0D, 2.147483647E9D));
        this.piercingIgnoreEntityIds.add(entity.getId());

        Entity owner = this.getOwner();
        DamageSource damagesource;
        damagesource = getDamageSource(owner, entity);

        boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !isEnderman) {
            entity.igniteForTicks(5);
        }

        if (entity.hurt(damagesource, (float) i)) {
            if (isEnderman) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {

                if (this.knockback > 0) {
                    Vec3 vec3 = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double) this.knockback * 0.6D);
                    if (vec3.lengthSqr() > 0.0D) {
                        livingentity.push(vec3.x, 0.1D, vec3.z);
                    }
                }

                this.doPostHurtEffects(livingentity);
            }

            this.playSound(this.blockState.getSoundType().getBreakSound(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));

        } else {
            entity.setRemainingFireTicks(k);
        }
    }

@Override
        public void tick(LivingEntity entity) {
            if(isRush()) {
                int standingOnY = Mth.floor(entity.getY()) - 3;
                double headY = entity.getY() + 2.0D;
                float yawRadians = (float) (Math.toRadians(90 + entity.getYRot()));
                int temp = getTimer();

                    setTimer(temp - 1);
                    //Deal with rocket punch is valid
                    if (temp > 0) {
                        double yaw = Math.toRadians(entity.getYRot() + 90);
                        double xExpand = 3 * Math.cos(yaw);
                        double zExpand = 3 * Math.sin(yaw);
                        AABB attackRange = entity.getBoundingBox().expandTowards(xExpand, 0, zExpand);
                        for (LivingEntity target : entity.level().getEntitiesOfClass(LivingEntity.class, attackRange)) {
                            if (!target.isAlliedTo(entity) && target != entity) {
                                target.hurt(entity.damageSources().mobAttack(entity), getdamage());

                            }
                        }


                        if(temp % 2 ==0){
                            this.spawnFangs(entity.getX(), headY, entity.getZ(), standingOnY, yawRadians, 1, entity.level(), entity);
                            double x = entity.getX();
                            double y = entity.getY() + entity.getBbHeight() / 2;
                            double z = entity.getZ();
                            float yaw2 = (float) Math.toRadians(-entity.getYRot());
                            float yaw3 = (float) Math.toRadians(-entity.getYRot() + 180);
                            entity.level().addParticle(new RingParticleOptions(yaw2, 0, 20, 86, 236, 204, 1.0f, 30f, false, 2), x, y, z, 0, 0, 0);

                            entity.level().addParticle(new RingParticleOptions(yaw3, 0, 20, 86, 236, 204, 1.0f, 30f, false, 2), x, y, z, 0, 0, 0);

                        }
                    }

                    if (temp == 0) {
                        setRush(false);

                }
            }
        }

