protected void onImpact(RayTraceResult target) {
		if(target.entityHit instanceof EntityFortressBossProjectile == false) {
			if (target.entityHit != null && target.entityHit instanceof EntityLivingBase) {
				if(target.entityHit instanceof EntityFortressBoss) {
					EntityFortressBoss boss = (EntityFortressBoss) target.entityHit;
					Vec3d ray = new Vec3d(this.motionX, this.motionY, this.motionZ);
					ray = ray.normalize().scale(64.0D);
					int shieldHit = EntityFortressBoss.rayTraceShield(boss.shield, new Vec3d(boss.posX + EntityFortressBoss.SHIELD_OFFSET_X, boss.posY + EntityFortressBoss.SHIELD_OFFSET_Y, boss.posZ + EntityFortressBoss.SHIELD_OFFSET_Z), boss.getShieldRotationYaw(1), boss.getShieldRotationPitch(1), boss.getShieldRotationYaw(1), boss.getShieldExplosion(1), new Vec3d(this.posX, this.posY, this.posZ), ray, false);
					if(shieldHit >= 0) {
						if(!this.world.isRemote) {
							boss.shield.setActive(shieldHit, false);

							this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_SHIELD_DOWN, SoundCategory.HOSTILE, 1.0F, 1.0F);

							double angle = Math.PI * 2.0D / 18;
							for(int i = 0; i < 18; i++) {
								Vec3d dir = new Vec3d(Math.sin(angle * i), 0, Math.cos(angle * i));
								dir = dir.normalize();
								float speed = 0.8F;
								EntityFortressBossProjectile bullet = new EntityFortressBossProjectile(this.world, this.getOwner());
								bullet.setLocationAndAngles(boss.posX, boss.posY, boss.posZ, 0, 0);
								bullet.shoot(dir.x, dir.y, dir.z, speed, 0.0F);
								this.world.spawnEntity(bullet);
							}
						}
					} else {
						boss.attackEntityFrom(DamageSource.GENERIC, 10);
					}

					if(!this.world.isRemote) {
						boss.setFloating(false);
					}
				} else {
					target.entityHit.attackEntityFrom(DamageSource.causeIndirectMagicDamage(this, this.getOwner()), 2);
				}

				if(!this.world.isRemote) {
					this.setDead();
				}
			} else if(target.typeOfHit == RayTraceResult.Type.BLOCK) {
				this.setDead();
			}
		}
	}

private static int update(EntityPlayer player, Integer chargeTime){

		if(chargeTime == null) chargeTime = 0;

		if(chargeTime > 0){

			SpellModifiers modifiers = WizardData.get(player).getVariable(CHARGE_MODIFIERS);
			if(modifiers == null) modifiers = new SpellModifiers();

			Vec3d look = player.getLookVec();

			float speed = Spells.charge.getProperty(Charge.CHARGE_SPEED).floatValue() * modifiers.get(WizardryItems.range_upgrade);

			player.motionX = look.x * speed;
			player.motionZ = look.z * speed;

			if(player.world.isRemote){
				for(int i = 0; i < 5; i++){
					ParticleBuilder.create(Type.SPARK, player).spawn(player.world);
				}
			}

			List<EntityLivingBase> collided = player.world.getEntitiesWithinAABB(EntityLivingBase.class, player.getEntityBoundingBox().grow(EXTRA_HIT_MARGIN));

			collided.remove(player);

			float damage = Spells.charge.getProperty(DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY);
			float knockback = Spells.charge.getProperty(KNOCKBACK_STRENGTH).floatValue();

			collided.forEach(e -> e.attackEntityFrom(MagicDamage.causeDirectMagicDamage(player, MagicDamage.DamageType.SHOCK), damage));
			collided.forEach(e -> e.addVelocity(player.motionX * knockback, player.motionY * knockback + 0.3f, player.motionZ * knockback));

			if(player.world.isRemote) player.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE,
					player.posX + player.motionX, player.posY + player.height/2, player.posZ + player.motionZ, 0, 0, 0);

			if(collided.isEmpty()) chargeTime--;
			else{
				EntityUtils.playSoundAtPlayer(player, SoundEvents.ENTITY_GENERIC_HURT, 1, 1);
				chargeTime = 0;
			}
		}

		return chargeTime;
	}

