private void onThrowableCollision(HitResult result) {
		Entity thrower = getOwner();
		if (!(thrower instanceof Player) || ((int) getY()) <= 0) {
			discard();
			return;
		}

		for (int i = 0; i < 32; i++) {
			level().addParticle(ParticleTypes.PORTAL, getX(), getY() + random.nextDouble() * 2D, getZ(), random.nextGaussian(), 0.0D, random.nextGaussian());
		}

		if (!level().isClientSide) {
			thrower.fallDistance = 0.0F;

			int x = (int) Math.round(getX());
			int y = (int) Math.round(getY());
			int z = (int) Math.round(getZ());

			if (result.getType() != HitResult.Type.MISS) {
				BlockPos pos;
				if (result.getType() == HitResult.Type.ENTITY) {
					Entity entityHit = ((EntityHitResult) result).getEntity();
					entityHit.hurt(damageSources().thrown(this, thrower), 0);
					pos = entityHit.blockPosition();
				} else {
					BlockHitResult blockResult = (BlockHitResult) result;
					pos = blockResult.getBlockPos().relative(blockResult.getDirection());
				}

				y = pos.getY();
				x = pos.getX();
				z = pos.getZ();
			}
			float targetX = x + 0.5F;
			float targetY = y + 0.5F;
			float targetZ = z + 0.5F;
			if (thrower instanceof ServerPlayer serverPlayer) {
				EventHooks.onEnderPearlLand(serverPlayer, targetX, targetY, targetZ, new ThrownEnderpearl(level(), serverPlayer), 0, result);
			}

			thrower.playSound(SoundEvents.ENDERMAN_TELEPORT, 1.0f, 1.0f);
			thrower.teleportTo(targetX, targetY, targetZ);
		}
		discard();
	}

public void silentDie(DamageSource cause){
        super.die(cause);
        if (this.level instanceof ServerLevel serverLevel){
            serverLevel.sendParticles(new PortalShockwaveParticleOption(), this.getX(), this.getY(), this.getZ(), 0, 0, 0, 0, 0);
            ServerParticleUtil.blockBreakParticles(this.getParticles(), BlockPos.containing(this.position()), this.getState(), serverLevel);
            ServerParticleUtil.blockBreakParticles(this.getParticles(), BlockPos.containing(this.position()).above(), this.getState(), serverLevel);
            ServerParticleUtil.blockBreakParticles(this.getParticles(), BlockPos.containing(this.position()).above().above(), Blocks.CRYING_OBSIDIAN.defaultBlockState(), serverLevel);
            new SpellExplosion(this.level, null, this.damageSources().magic(), this.blockPosition(), 16, 5.0F){
                @Override
                public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                    if (target instanceof IOwned owned && target instanceof LivingEntity living){
                        if (owned.getTrueOwner() == AbstractObsidianMonolith.this.getTrueOwner() || owned.getTrueOwner() == AbstractObsidianMonolith.this){
                            if (!(owned instanceof AbstractObsidianMonolith)) {
                                if (living.hurt(living.damageSources().magic(), AbstractObsidianMonolith.this.level.random.nextInt(10) + 5.0F)){
                                    AbstractObsidianMonolith.this.launch(living, AbstractObsidianMonolith.this);
                                }
                            }
                        }
                    }
                    if (target instanceof ZombifiedPiglin piglin){
                        if (piglin.isAlive()){
                            piglin.spawnAnim();
                            piglin.discard();
                        }
                    }
                }
            };
            if (cause.getEntity() instanceof Mob mob && mob.getTarget() == this && this.getTrueOwner() != null){
                mob.setTarget(this.getTrueOwner());
                try {
                    mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, this.getTrueOwner().getUUID(), 600L);
                    mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, this.getTrueOwner(), 600L);
                    if (mob instanceof Warden warden) {
                        warden.increaseAngerAt(this.getTrueOwner(), AngerLevel.ANGRY.getMinimumAnger() + 20, false);
                        warden.setAttackTarget(this.getTrueOwner());
                    }
                } catch (NullPointerException ignored) {
                }
            }
            if (this.getTrueOwner() instanceof Apostle apostle && apostle.isAlive()){
                apostle.setMonolithCoolDown(MathHelper.minutesToTicks(1));
            }
        }
        this.remove(RemovalReason.KILLED);
    }

public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            float f5 = (float) Math.PI * this.radius() * this.radius();
            if (serverLevel.random.nextFloat() <= 0.05F) {
                for (int j1 = 0; j1 < serverLevel.random.nextInt(16) + 1; ++j1) {
                    for (int k1 = 0; (float) k1 < f5; ++k1) {
                        float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        float f7 = Mth.sqrt(this.random.nextFloat()) * this.radius();
                        float f8 = Mth.cos(f6) * f7;
                        float f9 = Mth.sin(f6) * f7;
                        serverLevel.sendParticles(ParticleTypes.WITCH, this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 0, 0, 0.5D, 0, 0.5F);
                    }
                }
            }
        }
        List<LivingEntity> targets = new ArrayList<>();
        for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox())) {
            LivingEntity livingEntity = MobUtil.getLivingTarget(entity);
            if (livingEntity != null) {
                if (this.getOwner() != null) {
                    if (livingEntity != this.getOwner() && !MobUtil.areAllies(this.getOwner(), livingEntity)) {
                        targets.add(livingEntity);
                    }
                } else {
                    targets.add(livingEntity);
                }
            }
        }
        if (!targets.isEmpty()){
            for (LivingEntity livingEntity : targets) {
                livingEntity.hurt(damageSources().magic(), 4.0F);
                if (this.getOwner() != null){
                    float damage = 4.0F;
                    if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                        damage = (float) (mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F);
                    }
                    livingEntity.hurt(damageSources().indirectMagic(this, this.getOwner()), damage);
                }
            }
        }
        if (this.tickCount >= this.getDuration()) {
            this.discard();
        }
    }

public ItemStack finishUsingItem(ItemStack pStack, Level pLevel, LivingEntity pEntityLiving) {
        super.finishUsingItem(pStack, pLevel, pEntityLiving);
        if (pEntityLiving instanceof Player player) {
            if (MainConfig.LichEnable.get()) {
                if (pLevel instanceof ServerLevel serverWorld) {
                    ILichdom lichdom = LichdomHelper.getCapability(player);
                    ISoulEnergy soulEnergy = SEHelper.getCapability(player);
                    boolean isLich = lichdom.getLichdom();
                    if (isLich) {
                        player.heal(20.0F);
                    } else {
                        if (serverWorld.getMoonBrightness() > 0.9F && serverWorld.isNight()) {
                            if (soulEnergy.getSEActive() && soulEnergy.getArcaBlock() != null) {
                                if (pEntityLiving instanceof ServerPlayer serverPlayer) {
                                    CriteriaTriggers.CONSUME_ITEM.trigger(serverPlayer, pStack);
                                    serverPlayer.awardStat(Stats.ITEM_USED.get(this));
                                }
                                lichdom.setLichdom(true);
                                lichdom.setLichMode(true);
                                LichdomHelper.sendLichUpdatePacket(player);
                                player.displayClientMessage(Component.translatable("info.goety.lichdom.success"), true);
                                player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 20, 1));
                                player.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 20, 1));
                                player.playSound(SoundEvents.WITHER_DEATH, 1.0F, 0.5F);
                                player.playSound(SoundEvents.ZOMBIE_VILLAGER_CURE, 1.0F, 0.5F);
                                player.hurt(player.damageSources().wither(), 50.0F);
                            } else {
                                player.displayClientMessage(Component.translatable("info.goety.lichdom.fail"), true);
                                player.hurt(player.damageSources().wither(), 50.0F);
                            }
                        } else {
                            player.displayClientMessage(Component.translatable("info.goety.lichdom.fail"), true);
                            player.hurt(player.damageSources().wither(), 50.0F);
                        }
                    }
                    if (!player.getAbilities().instabuild) {
                        pStack.shrink(1);
                    }
                }
            } else {
                player.displayClientMessage(Component.translatable("info.goety.lichdom.disable").withStyle(ChatFormatting.DARK_RED), false);
            }
        }
        return pStack.isEmpty() ? new ItemStack(Items.GLASS_BOTTLE) : pStack;
    }

@Override
    protected void onHitEntity(EntityHitResult rayTraceResult) {
        Entity entity = rayTraceResult.getEntity();

        float damage = 7.5f;

        Entity entity1 = this.getOwner();
        DamageSource damagesource;
        if (entity1 == null) {
            damagesource = level.damageSources().indirectMagic(this, null);
        } else {
            damagesource = level.damageSources().magic();
            if (entity1 instanceof LivingEntity) {
                ((LivingEntity) entity1).setLastHurtMob(entity);
            }
        }

        boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !isEnderman) {
            entity.igniteForSeconds(5);
        }

        if (entity.hurt(damagesource, damage)) {
            if (isEnderman) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {
                this.doPostHurtEffects(livingentity);
            }

            this.playSound(this.getDefaultHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            this.remove(RemovalReason.DISCARDED);

        } else {
            entity.setRemainingFireTicks(k);
            this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
            this.setYRot(this.getYRot() + 180f);
            this.yRotO += 180.0F;
            if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                this.remove(RemovalReason.DISCARDED);
            }
        }
    }

