        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            damage += WandUtil.getPotencyLevel(caster);
        }
        ColorUtil colorUtil = new ColorUtil(0xb1abf1);
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            colorUtil = new ColorUtil(0xa7fc3e);
        }
        damage += spellStat.getPotency();
        Vec3 vec3 = caster.getEyePosition();
        BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
        Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
        Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
        if (lightningRod.isPresent() && !rightStaff(staff)){
            BlockPos blockPos = lightningRod.get();
            ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
            this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
        } else {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
                Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, vec31, colorUtil, 10));
                if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                    float chance = rightStaff(staff) ? 0.25F : 0.05F;
                    float chainDamage = damage / 2.0F;
                    if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                        chance += 0.25F;
                        chainDamage = damage;
                    }
                    if (worldIn.random.nextFloat() <= chance){
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (rightStaff(staff)){
                        WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage);
                    }
                }
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            } else {
                BlockPos blockPos = rayTraceResult.getBlockPos();
                ModNetwork.sendToALL(new SThunderBoltPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 10));
                this.playSound(worldIn, caster, ModSounds.THUNDERBOLT.get());
            }
        }
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);
		BlockPos pos = spell.getTargetPos();

		if (pos == null) return false;

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell) / 2;

		if (!spellRing.taxCaster(world, spell, true)) return false;

		if (targetEntity instanceof EntityLivingBase) {

			PotionEffect slowness = ((EntityLivingBase) targetEntity).getActivePotionEffect(MobEffects.SLOWNESS);
			PotionEffect frost = ((EntityLivingBase) targetEntity).getActivePotionEffect(ModPotions.SLIPPERY);
			int mult = 0;
			if (slowness != null)
				mult += slowness.getAmplifier() + 1;
			if (frost != null)
				mult += frost.getAmplifier() + 1;
			potency *= 1 + mult * 0.5;

			int invTime = targetEntity.hurtResistantTime;
			targetEntity.hurtResistantTime = 0;

			world.playSound(null, pos, ModSounds.MARBLE_EXPLOSION, CommonProxy.SoundCategory_WizardryGeneral, 2, RandUtil.nextFloat(0.8f, 1.2f));
			world.playSound(null, pos, ModSounds.FIREWORK, CommonProxy.SoundCategory_WizardryGeneral, 2, RandUtil.nextFloat(0.8f, 1.2f));
			if (caster instanceof EntityLivingBase)
			{
				((EntityLivingBase) caster).setLastAttackedEntity(targetEntity);
				if (caster instanceof EntityPlayer)
					targetEntity.attackEntityFrom(DamageSource.causePlayerDamage((EntityPlayer) caster).setMagicDamage(), (float) potency);
				else
					targetEntity.attackEntityFrom(new DamageSource("generic").setMagicDamage(), (float) potency);
			}
			else
				targetEntity.attackEntityFrom(new DamageSource("generic").setMagicDamage(), (float) potency);

			targetEntity.hurtResistantTime = invTime;
		}

		// TODO: EffectShatter Sound
//		Vec3d target = spell.getTargetWithFallback();
//		if (target != null)
//			world.playSound(null, new BlockPos(target), ModSounds.CHAINY_ZAP, SoundCategory.NEUTRAL, 0.5f, 1f);
		return true;
	}

public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        prevangryProgress = angryProgress;
        if (this.isAggressive() && angryProgress < 10F) {
            angryProgress++;
        }
        if (!this.isAggressive() && angryProgress > 0F) {
            angryProgress--;
        }
        LivingEntity target = this.getTarget();
        if(this.isAlive()) {
            if (this.getAnimation() == COBOLETON_ATTACK) {
                if (this.getAnimationTick() == 11) {
                    this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                    if (target != null) {
                        if (this.distanceTo(target) < this.getBbWidth() * 2.5F * this.getBbWidth() * 2.5F + target.getBbWidth()) {
                            float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                            target.hurt(damageSources().mobAttack(this), damage);

                            ItemStack offhand = target.getOffhandItem();
                            ItemStack mainhand = target.getMainHandItem();
                            Optional<SlotResult> slot = CuriosApi.getCuriosHelper().findFirstCurio(target, stack -> stack.is(ModItems.STICKY_GLOVES.get()));
                            if(this.random.nextFloat() * 100.0F <= (float)CMCommonConfig.Koboleton.CauseKoboletontoDropItemInHandPercent) {
                                if (slot.isEmpty()) {
                                    if (!offhand.isEmpty()) {
                                        if (!offhand.is(ModTag.STICKY_ITEM)) {
                                            int i = offhand.getCount();
                                            this.koboletonstealdrop(offhand.copyWithCount(1), target);
                                            target.setItemSlot(EquipmentSlot.OFFHAND, offhand.split(i - 1));
                                        }
                                    } else {
                                        if (!mainhand.isEmpty()) {
                                            if (!mainhand.is(ModTag.STICKY_ITEM)) {
                                                int i = mainhand.getCount();
                                                this.koboletonstealdrop(mainhand.copyWithCount(1), target);
                                                target.setItemSlot(EquipmentSlot.MAINHAND, mainhand.split(i - 1));
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public void tick(){
        super.tick();
        this.prevOnLandProgress = onLandProgress;
        boolean onLand = !this.isInWaterOrBubble() && this.onGround();
        if (onLand && onLandProgress < 5F) {
            onLandProgress++;
        }
        if (!onLand && onLandProgress > 0F) {
            onLandProgress--;
        }
        float targetXRot = 0;
        if(this.getDeltaMovement().length() > 0.09){
            targetXRot = -((float)(Mth.atan2(this.getDeltaMovement().y, this.getDeltaMovement().horizontalDistance()) * (double)Mth.RAD_TO_DEG));
        }
        if(targetXRot < this.getXRot() - 5){
            targetXRot = this.getXRot() - 5;
        }
        if(targetXRot > this.getXRot() + 5){
            targetXRot = this.getXRot() + 5;
        }
        this.setXRot(targetXRot);
        if (!this.level().isClientSide && this.getTarget() != null && this.distanceTo(this.getTarget()) < 2.0F + this.getTarget().getBbWidth()) {
            this.lookAt(this.getTarget(), 350, 200);
            if(this.getAnimation() == ANIMATION_STAB && this.getAnimationTick() == 7 && this.hasLineOfSight(this.getTarget())){
                float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            }
            if(this.getAnimation() == ANIMATION_SLASH && this.getAnimationTick() % 5 == 0 && this.getAnimationTick() > 0 && this.getAnimationTick() < 25 && this.hasLineOfSight(this.getTarget())){
                for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getTarget().getBoundingBox().inflate(2.0D))) {
                    if (!entity.isPassengerOfSameVehicle(this) && entity != this && !entity.isAlliedTo(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue() * 0.5F);
                    }
                }
            }
        }
        if(onLandProgress >= 5.0F && this.isVehicle()){
            this.ejectPassengers();
        }
        if(!isInWaterOrBubble()){
            if (this.onGround() && random.nextFloat() < 0.2F) {
                this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
                this.setYRot(this.random.nextFloat() * 360.0F);
                this.playSound(AMSoundRegistry.SKELEWAG_HURT.get(), this.getSoundVolume(), this.getVoicePitch());
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public void setDead() {
		if(!this.isDead && this.dropContentsWhenDead) {
			if(this.getAttackTarget() != null) {
				if(this.world.isRemote) {
					for(int i = 0; i < 200; i++) {
						Random rnd = this.world.rand;
						float rx = rnd.nextFloat() * 1.0F - 0.5F;
						float ry = rnd.nextFloat() * 1.0F - 0.5F;
						float rz = rnd.nextFloat() * 1.0F - 0.5F;
						Vec3d vec = new Vec3d(rx, ry, rz);
						vec = vec.normalize();
						BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.1F, this.posY + ry, this.posZ + rz + 0.1F, ParticleArgs.get().withMotion(vec.x * 0.4F, vec.y * 0.4F, vec.z * 0.4F));
					}
				} else {
					for(int i = 0; i < 8; i++) {
						this.playSound(SoundRegistry.TAR_BEAST_STEP, 1F, (this.rand.nextFloat() * 0.4F + 0.8F) * 0.8F);
					}
					List<EntityCreature> affectedEntities = (List<EntityCreature>)this.world.getEntitiesWithinAABB(EntityCreature.class, this.getEntityBoundingBox().grow(5.25F, 5.25F, 5.25F));
					for(EntityCreature e : affectedEntities) {
						if(e == this || e.getDistance(this) > 5.25F || !e.canEntityBeSeen(this) || e instanceof EntityTarminion) continue;
						double dst = e.getDistance(this);
						e.attackEntityFrom(DamageSource.causeMobDamage(this), (float)this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue() * 4);
						e.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, (int)(20 + (1.0F - dst / 5.25F) * 150), 1));
					}
				}
			}

			if(!this.world.isRemote) {
				this.dropLoot(false, 0, DamageSource.GENERIC);
			}

			this.playSound(SoundRegistry.TAR_BEAST_STEP, 2.5F, 0.5F);

			if(this.world.isRemote) {
				for(int i = 0; i < 100; i++) {
					Random rnd = world.rand;
					float rx = rnd.nextFloat() * 1.0F - 0.5F;
					float ry = rnd.nextFloat() * 1.0F - 0.5F;
					float rz = rnd.nextFloat() * 1.0F - 0.5F;
					Vec3d vec = new Vec3d(rx, ry, rz);
					vec = vec.normalize();
					BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.1F, this.posY + ry, this.posZ + rz + 0.1F, ParticleArgs.get().withMotion(vec.x * 0.2F, vec.y * 0.2F, vec.z * 0.2F));
				}
			}
		}

		super.setDead();
	}

public void fire() {
		Vec3d ray = (new Vec3d(target.getX()-getPos().getX(),target.getY()-getPos().getY(),target.getZ()-getPos().getZ())).normalize();
		double impactDist = Double.POSITIVE_INFINITY;
		double damage = UpgradeUtil.getOtherParameter(this,"damage",DAMAGE,upgrades);
		if (!getWorld().isRemote){
			double posX = getPos().getX()+0.5;
			double posY = getPos().getY()+0.5;
			double posZ = getPos().getZ()+0.5;
			double startX = posX;
			double startY = posY;
			double startZ = posZ;
			boolean doContinue = true;
			int maxDist = UpgradeUtil.getOtherParameter(this,"distance",MAX_DISTANCE,upgrades);
			for (int i = 0; i < maxDist * 10 && doContinue; i++){
				posX += ray.x*0.1;
				posY += ray.y*0.1;
				posZ += ray.z*0.1;
				IBlockState state = getWorld().getBlockState(new BlockPos(posX,posY,posZ));
				TileEntity tile = getWorld().getTileEntity(new BlockPos(posX,posY,posZ));
				if(sparkTarget(tile))
					doContinue = false;
				else if (tile instanceof IEmberPacketReceiver){
					if (tile.hasCapability(EmbersCapabilities.EMBER_CAPABILITY, null)){
						tile.getCapability(EmbersCapabilities.EMBER_CAPABILITY, null).addAmount(capability.getEmber(), true);
						tile.markDirty();
					}
					doContinue = false;
				}
				else if (state.isFullCube() && state.isOpaqueCube()){
					doContinue = false;
				}
				//TODO: OPTIMIZE THIS, THIS CALL IS GARBAGE
				List<EntityLivingBase> rawEntities = getWorld().getEntitiesWithinAABB(EntityLivingBase.class, new AxisAlignedBB(posX-0.85,posY-0.85,posZ-0.85,posX+0.85,posY+0.85,posZ+0.85));
				for (EntityLivingBase rawEntity : rawEntities) {
					rawEntity.attackEntityFrom(RegistryManager.damage_ember, (float)damage);
				}
				if(!doContinue) {
					world.playSound(null, posX, posY, posZ, SoundManager.BEAM_CANNON_HIT, SoundCategory.BLOCKS, 1.0f, 1.0f);
					impactDist = i;
				}
			}
			PacketHandler.INSTANCE.sendToAll(new MessageBeamCannonFX(startX,startY,startZ,ray.x,ray.y,ray.z,impactDist));
			UpgradeUtil.throwEvent(this, new EmberEvent(this, EmberEvent.EnumType.CONSUME, this.capability.getEmber()), upgrades);
			this.capability.setEmber(0);
			markDirty();

			world.playSound(null,pos.getX()+0.5,pos.getY()+0.5,pos.getZ()+0.5, SoundManager.BEAM_CANNON_FIRE, SoundCategory.BLOCKS, 1.0f, 1.0f);
		}
	}

public void serverTick() {
        if (targetPlayer == null || isValidTarget(targetPlayer)) {
            debug("Aborting charge player as no target was set or target is dead");
            guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed();
        } else if (timeSinceCharge > 0 && timeSinceCharge >= 20 * 5) {
            guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed().prevAttackFailed();
            debug("Aborting charge, Timed out");
        } else {
            double distance = targetPlayer.distanceTo(guardian);
            if (distance - closestApproach > 16 && timeSinceCharge > 10) {
                guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed().prevAttackFailed();
                debug("Aborting charge, Player got away");
            } else {
                closestApproach = Math.min(distance, closestApproach);
                targetLocation = targetPlayer.position();
                if (!charging) {
                    double tRelX = targetLocation.x - guardian.getX();
                    double tRelZ = targetLocation.z - guardian.getZ();
                    double relTargetAngle = Mth.clamp(Mth.wrapDegrees(180.0D - Mth.atan2(tRelX, tRelZ) * (double) (180F / (float) Math.PI) - (double) guardian.getYRot()), -50.0D, 50.0D);
                    charging = Math.abs(relTargetAngle) < 1;
                    if (charging) {
                        debug("CHARGE!");
                    }
                }
                else {
                    timeSinceCharge++;
                }

                if (distance <= 5) {
                    guardian.getPhaseManager().setPhase(PhaseType.START);
                    debug("Charge Successful");
                    targetPlayer.hurt(DEDamage.guardian(guardian.level(), guardian), GuardianFightManager.CHARGE_DAMAGE);
                    guardian.playSound(SoundEvents.GENERIC_EAT, 20, 0.95F + (guardian.getRandom().nextFloat() * 0.2F));
                    guardian.playSound(SoundEvents.GENERIC_EAT, 20, 0.95F + (guardian.getRandom().nextFloat() * 0.2F));
                    DraconicNetwork.sendImpactEffect(guardian.level(), targetPlayer.blockPosition(), 0);
                }
            }
        }

        if (tick > 10*20) {
            guardian.getPhaseManager().setPhase(PhaseType.START).prevAttackFailed().prevAttackFailed();
            debug("Aborting charge, Master timed out");
        }
        else if (charging && timeSinceCharge < 20 && timeSinceCharge % 5 == 0) {
            guardian.playSound(SoundEvents.ENDER_DRAGON_GROWL, 20, 0.95F + (guardian.getRandom().nextFloat() * 0.2F));
        }

        tick++;
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        double potency = spellStat.getPotency();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster) / 2.0D;
        }
        if (this.victim != null){
            try {
                Vec3 vec3 = this.victim.getDeltaMovement();
                Vec3 force = (caster.getLookAngle()
                        .normalize()
                        .scale(Math.max(caster.distanceTo(this.victim), 4))
                        .add(caster.position())
                        .subtract(this.victim.position()))
                        .scale(potency);
                if (force.y > 0) {
                    this.victim.resetFallDistance();
                }
                Vec3 newMotion = force.subtract(vec3).scale(0.25).add(vec3);
                Vec3 delta = newMotion.subtract(vec3);
                Vec3 clampedMotion = new Vec3(signedMin(delta.x, force.x * 4), signedMin(delta.y, force.y * 4), signedMin(delta.z, force.z * 4));
                MobUtil.push(this.victim, clampedMotion, 0.25D);
                Vec3 old = new Vec3(this.victim.xOld, this.victim.yOld, this.victim.zOld);
                Vec3 travel = this.victim.position().subtract(old);
                if (this.victim.horizontalCollision && this.victim instanceof LivingEntity livingTarget) {
                    double d11 = livingTarget.getDeltaMovement().horizontalDistance();
                    float f1 = (float) (d11 * 10.0D - 3.0D);
                    int airborne = (int) travel.horizontalDistanceSqr() / 2;
                    if (f1 >= 1.0F) {
                        if (livingTarget.hurt(livingTarget.damageSources().flyIntoWall(), 4.0F + (airborne + 1) * 0.5F)) {
                            livingTarget.playSound(livingTarget.getFallSounds().big(), 2.0F, 1.0F);
                        }
                    }
                }
                if (CuriosFinder.hasCurio(caster, ModItems.RING_OF_FORCE.get())){
                    this.victim.setAirSupply(Math.max(-20, this.victim.getAirSupply() - 10));
                    if (this.victim.getAirSupply() <= -20){
                        this.victim.setAirSupply(0);
                        this.victim.hurt(ModDamageSource.choke(caster, caster), 2.0F);
                    }
                }
                ServerParticleUtil.addParticlesAroundMiddleSelf(worldIn, ParticleTypes.PORTAL, this.victim);
            } catch (NullPointerException exception) {
                caster.stopUsingItem();
            }
        } else {
            this.findVictim(worldIn, caster, spellStat);
        }
    }

@Override
	public boolean run(@NotNull World world, ModuleInstanceEffect instance, @Nonnull SpellData spell, @Nonnull SpellRing spellRing) {
		Entity targetEntity = spell.getVictim(world);
		Entity caster = spell.getCaster(world);

		double potency = spellRing.getAttributeValue(world, AttributeRegistry.POTENCY, spell);

		if (!spellRing.taxCaster(world, spell, true)) return false;

		if (targetEntity instanceof EntityLivingBase) {
			int invTime = targetEntity.hurtResistantTime;
			targetEntity.hurtResistantTime = 0;
			if (targetEntity instanceof EntityPlayer) {

				double targetMana = ManaManager.getMana(targetEntity);

				targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);
				if (targetEntity.isDead) {
					targetMana /= 2;
					targetMana = MathHelper.clamp(targetMana, targetMana, spellRing.getManaDrain(spell) * 2);
					ManaManager.forObject(caster).addMana(targetMana).close();
				}

			} else if (targetEntity instanceof EntityWitch) {

				double targetMana = spellRing.getManaDrain(spell) * 2;

				targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);
				if (targetEntity.isDead) {
					ManaManager.forObject(caster).addMana(targetMana).close();
				}

			} else {
				if (caster instanceof EntityLivingBase) ((EntityLivingBase) caster).setLastAttackedEntity(targetEntity);

				if (caster != null)
					targetEntity.attackEntityFrom(new EntityDamageSource("magic", caster).setDamageBypassesArmor().setMagicDamage(), (float) potency);
				else
					targetEntity.attackEntityFrom(DamageSource.MAGIC, (float) potency);

			}
			targetEntity.hurtResistantTime = invTime;
		}

		Vec3d target = spell.getTargetWithFallback(world);
		if (target != null)
			world.playSound(null, new BlockPos(target), ModSounds.CHAINY_ZAP, CommonProxy.SoundCategory_WizardryGeneral, 0.5f, 1f);
		return true;
	}

@Override
    public boolean hurt(DamageSource pSource, float pAmount) {
        if (level.isClientSide) {
            return false;
        }
        /*
        can parry:
        - serverside
        - in combat
        - we aren't in melee attack anim or spell cast
        - the damage source is caused by an entity (ie not fall damage)
        - the damage is caused within our rough field of vision (117 degrees)
        - the damage is not /kill
         */
        boolean isDodgeableAttack = this.isAggressive() &&
                parryCooldown <= 0 &&
                !isImmobile() &&
                pSource.getEntity() != null &&
                !pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY);
        boolean canParry = isDodgeableAttack &&
                !attackGoal.isActing() &&
                pSource.getSourcePosition() != null && pSource.getSourcePosition().subtract(this.position()).normalize().dot(this.getForward()) >= 0.35;
        if (canParry && this.random.nextFloat() < 0.5) {
            serverTriggerAnimation("offhand_parry");
            procSpectralDagger();
            this.parryCooldown = 100;
            this.playSound(SoundRegistry.FIRE_DAGGER_PARRY.get());
            return false;
        }
        if (isStanceBroken()) {
            pAmount *= 0.40f;
        }
        if (isSoulMode()) {
            pAmount *= 0.50f;
        }
        if (isHalfHealthAttacking()) {
            pAmount *= 0.80f;
        }
        // damage limiter
        var limit = getMaxHealth() * 0.025f;
        if (pAmount > limit) {
            pAmount = limit + (pAmount - limit) * .3f; // damage about limit has .3x multiplier applied
        }
        if (pSource.is(DamageTypes.IN_WALL) && this.destroyBlockDelay <= 0) {
            Utils.doMobBreakSuffocatingBlocks(this);
            destroyBlockDelay = 40;
        }
        return super.hurt(pSource, pAmount);
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            if(canBlockFaceSource(source)) {
                if (!this.level().isClientSide) {
                    if (CanParryState()) {
                        if (this.getParryCount() >= MAX_PARRY_COUNT) {
                            this.setParryCount(CAN_PARRY);
                            this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.8f);
                            this.level().broadcastEntityEvent(this, (byte) 11);
                            return false;
                        } else {
                            if (this.random.nextFloat() * 100.0F < (this.getParryCount() + 1) * 5 && Scylla_Entity.this.parry_cooldown <= 0) {
                                this.setParryCount(CAN_PARRY);
                                this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.8f);
                                this.level().broadcastEntityEvent(this, (byte) 11);
                                return false;
                            }
                        }
                    }
                    if (this.getAttackState() == 19 && this.attackTicks < 11 && this.attackTicks > 1) {
                        this.playSound(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1.0F, 0.8f);
                        this.level().broadcastEntityEvent(this, (byte) 11);
                        return false;
                    }
                }
            }
            if (this.getAttackState() == 21 || this.getAttackState() == 22) {
                return false;
            }

            if (this.isSleep()) {
                return false;
            }
        }
        if (this.destroyBlocksTick <= 0) {
            this.destroyBlocksTick = 20;
        }
        boolean flag = super.hurt(source, damage);
        if(flag) {
            if(canBlockFaceSource(source)) {
                if (this.getParryCount() < MAX_PARRY_COUNT) {
                    this.setParryCount(this.getParryCount() + (source.is(DamageTypeTags.IS_PROJECTILE) ? 2 : 1));
                }
            }
        }

        return flag;
    }

@Override
	public void tick() {
		super.tick();

		if (this.getTarget() != null && !this.getTarget().isAlive() && this.ticksSinceLastSonarFire >= 55 && this.getRandom().nextFloat() < 0.05F) {
			this.setTarget(null);
		}

		if (!this.isNoAi()) {
			if (this.isEndimationPlaying(UAPlayableEndimations.THRASHER_SONAR_FIRE)) {
				this.ticksSinceLastSonarFire = 0;
			} else {
				this.ticksSinceLastSonarFire++;
			}
			if (this.isInWaterRainOrBubble()) {
				this.setWaterTime(2400);
			} else {
				this.setWaterTime(this.getWaterTime() - 1);
				if (this.getWaterTime() <= 0) {
					this.hurt(this.damageSources().dryOut(), 1.0F);
				}

				if (!this.isInWater() && !this.isStunned() && this.onGround()) {
					this.setDeltaMovement(this.getDeltaMovement().add((this.random.nextFloat() * 2.0F - 1.0F) * 0.2F, 0.5D, (this.random.nextFloat() * 2.0F - 1.0F) * 0.2F));
					this.setYRot(this.random.nextFloat() * 360.0F);
					this.setXRot(this.random.nextFloat() * -50.0F);
					this.setOnGround(false);
					this.hasImpulse = true;
					this.playSound(this.getFlopSound(), this.getSoundVolume(), this.getVoicePitch());
				}
			}
			if (this.level().isClientSide()) {
				if (!this.getPassengers().isEmpty() && this.isEndimationPlaying(UAPlayableEndimations.THRASHER_THRASH) && this.getAnimationTick() % 2 == 0 && this.getAnimationTick() > 5) {
					Entity passenger = this.getFirstPassenger();
					for (int i = 0; i < 3; ++i) {
						if (passenger.isEyeInFluid(FluidTags.WATER)) {
							this.level().addParticle(ParticleTypes.BUBBLE, passenger.getX() + (this.getRandom().nextDouble() - 0.5D) * (double) passenger.getBbWidth(), passenger.getY(), passenger.getZ() + (this.getRandom().nextDouble() - 0.5D) * (double) passenger.getBbWidth(), (this.getRandom().nextDouble() - 0.5D) * 2.0D, -this.getRandom().nextDouble(), (this.getRandom().nextDouble() - 0.5D) * 2.0D);
						}
					}
				}
			}
			if (!this.level().isClientSide && this.isStunned()) {
				if (!this.getPassengers().isEmpty()) {
					this.ejectPassengers();
				}
				this.setStunned(this.getStunTime() - 1);
			}
		}
	}

protected void onHitEntity(EntityHitResult p_37626_) {
        if (!this.level.isClientSide) {
            float baseDamage = SpellConfig.IceSpikeDamage.get().floatValue() * WandUtil.damageMultiply();
            Entity entity = p_37626_.getEntity();
            if (this.getPierceLevel() > 0) {
                if (this.piercingIgnoreEntityIds == null) {
                    this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
                }

                if (this.piercedAndKilledEntities == null) {
                    this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
                }

                if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
                    this.discard();
                    return;
                }

                this.piercingIgnoreEntityIds.add(entity.getId());
            }
            Entity entity1 = this.getOwner();
            boolean flag;
            baseDamage += this.getExtraDamage();
            if (entity1 instanceof LivingEntity livingentity) {
                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }
                flag = entity.hurt(ModDamageSource.iceSpike(this, livingentity), baseDamage);
                if (flag) {
                    if (entity.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, entity);
                    }
                }
            } else {
                flag = entity.hurt(ModDamageSource.iceSpike(this, this), baseDamage);
            }

            if (flag && entity instanceof LivingEntity livingEntity) {
                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + livingEntity.getRandom().nextInt(2))));
                this.playSound(ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                if (livingEntity.level instanceof ServerLevel serverLevel){
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.PACKED_ICE.defaultBlockState()), livingEntity);
                }
                if (this.getPierceLevel() <= 0) {
                    this.discard();
                }
            }

        }
    }

@Override
    public void render(TotemPoleBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        var spiritType = blockEntityIn.getSpirit();
        if (spiritType == null) {
            return;
        }
        var direction = blockEntityIn.getBlockState().getValue(BlockStateProperties.HORIZONTAL_FACING);

        var level = Minecraft.getInstance().level;
        var renderType = LodestoneRenderTypes.ADDITIVE_TEXTURE.apply(RenderTypeToken.createToken(spiritType.getGlowTexture()));
        float delta = blockEntityIn.getGlowDelta();
        float alpha = delta * 0.7f;
        float ease = Easing.SINE_OUT.ease(delta);
        float offsetDistance = 0.2f - ease * 0.2f;
        float wobbleStrength = 0.1f - ease * 0.075f;
        var offset = 0.5125f;
        Vector3f[] vertices = new Vector3f[]{
                new Vector3f(-offset, 0f, offset), new Vector3f(offset, 0f, offset),
                new Vector3f(offset, 1f, offset), new Vector3f(-offset, 1f, offset)};

        poseStack.pushPose();
        poseStack.translate(0.5f, 0, 0.5f);
        poseStack.mulPose(Axis.YN.rotationDegrees(direction.toYRot()));


        float gameTime = level.getGameTime() + partialTicks;
        int time = 160;
        for (int i = 0; i < 4; i++) {
            var color = i <= 2 ? spiritType.getPrimaryColor() : spiritType.getSecondaryColor();
            poseStack.pushPose();
            if (offsetDistance > 0) {
                double angle = i / 4f * (Math.PI * 2);
                angle += ((gameTime % time) / time) * (Math.PI * 2);
                double primingOffset = (offsetDistance * Math.cos(angle));
                if (i % 2 == 0) {
                    primingOffset *= -1;
                }
                poseStack.translate(primingOffset, 0, 0);
            }

            CubeVertexData.applyVertexWobble(vertices, 0, wobbleStrength);
            SpiritBasedWorldVFXBuilder.create(spiritType)
                    .setColor(color, alpha)
                    .setRenderType(renderType)
                    .renderQuad(poseStack, vertices, 1f);
            poseStack.popPose();
            alpha *= (1 - (delta+0.2f) * 0.5f);
        }
        poseStack.popPose();
    }

@Override
        public void tick(LivingEntity entity) {
            if(isCharge()) {
                if (!entity.level().isClientSide()) {
                    int temp = getTimer();
                    setTimer(temp - 1);
                    //Deal with rocket punch is valid
                    if (temp > 0) {
                        //Slightly enlarge player's hitbox
                        AABB collideBox = entity.getBoundingBox().inflate(0.75f, 0.75f, 0.75f);

                        //Collision Detection
                        List<LivingEntity> checks = entity.level().getEntitiesOfClass(LivingEntity.class, collideBox);
                        checks.remove(entity);

                        //If any mob is detected
                        if (!checks.isEmpty()) {
                            // spawn an watchEntity to simulate rocket punch effect
                            Wall_Watcher_Entity watchEntity = new Wall_Watcher_Entity(entity.level(), entity.blockPosition(), temp, effectiveChargeTime,
                                    knockbackSpeedIndex, damagePerEffectiveCharge, dx, dz,
                                    entity);

                            List<LivingEntity> impact = entity.level().getEntitiesOfClass(LivingEntity.class, entity.getBoundingBox().inflate(3.5f, 0.75f, 3.5f));
                            impact.remove(entity);

                            for (LivingEntity target : impact) {
                                // Deal damage
                                if (!target.isAlliedTo(entity)) {
                                    boolean flag = target.hurt(entity.damageSources().mobProjectile(entity, entity), damagePerEffectiveCharge * effectiveChargeTime);
                                    watchEntity.watch(target);
                                    if (flag) {
                                        target.playSound(SoundEvents.ANVIL_LAND, 1.5f, 0.8F);
                                    }

                                }
                            }
                            entity.level().addFreshEntity(watchEntity);

                            // Player stop moving and clear pocket punch status
                            entity.setDeltaMovement(0, 0, 0);
                            entity.hurtMarked = true;
                            setCharge(false);
                        }
                    }
                    if (entity.horizontalCollision || temp == 0) {
                        setCharge(false);
                    }
                }
            }
        }

