private void EarthQuake(UseOnContext context, Player player) {
        Level world = context.getLevel();

        boolean berserk = player.getHealth() <= player.getMaxHealth() * 0.5F;
        double radius = 4.0D;

        world.playSound(player, player.blockPosition(), ModSounds.EXPLOSION.get(), SoundSource.PLAYERS, 1.5F, 1.0F / (world.getRandom().nextFloat() * 0.4F + 0.8F));

        if (world.isClientSide) {
            BlockState block = world.getBlockState(context.getClickedPos());
            int numParticles = 80;
            for (int i = 0; i < numParticles; i++) {

                double angle = (double) i / numParticles * (Math.PI * 2.0D);
                double d0 = player.getX() + radius * Math.sin(angle);
                double d1 = player.getY() + 0.15D;
                double d2 = player.getZ() + radius * Math.cos(angle);

                double d3 = world.getRandom().nextGaussian() * 0.1D;
                double d4 = world.getRandom().nextGaussian() * 0.1D;
                double d5 = world.getRandom().nextGaussian() * 0.1D;

                world.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, block), d0, d1, d2, d3, d4, d5);
                if (berserk) {
                    world.addParticle(ParticleTypes.FLAME, d0, d1, d2, d3, d4, d5);
                }
            }
        } else if (world instanceof ServerLevel serverLevel) {
            ScreenShake_Entity.ScreenShake(serverLevel, player.position(), 30, 0.1f, 0, 30);

            DamageSource shredderDamage = serverLevel.damageSources().playerAttack(player);
            float basedmg = AttributeUtils.OriginDamage(player, context.getItemInHand());

            List<Entity> list = serverLevel.getEntities(player, player.getBoundingBox().inflate(radius));
            for (Entity entity : list) {
                if (entity instanceof LivingEntity living) {
                    float bonusDamage = EnchantmentHelper.getDamageBonus(context.getItemInHand(), living.getMobType());
                    float enchanteddmg = basedmg + bonusDamage;

                    if (living.hurt(shredderDamage, enchanteddmg)) {
                        living.setDeltaMovement(living.getDeltaMovement().multiply(0.5D, 1.0D, 0.5D).add(0.0D, 0.6D, 0.0D));
                        if (berserk) {
                            living.setSecondsOnFire(5);
                        }
                    }

                }
            }
        }
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!this.world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){
				// This is if the poison bomb gets a direct hit
				float damage = Spells.poison_bomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.POISON).setProjectile(),
						damage);

				if(!this.world.isRemote && entityHit instanceof EntityLivingBase && !MagicDamage.isEntityImmune(DamageType.POISON, entityHit))
					((EntityLivingBase)entityHit).addPotionEffect(new PotionEffect(MobEffects.POISON,
							Spells.poison_bomb.getProperty(Spell.DIRECT_EFFECT_DURATION).intValue(),
							Spells.poison_bomb.getProperty(Spell.DIRECT_EFFECT_STRENGTH).intValue()));
			}

			// Notify clients to play the explosion effect
			WizardryPacketHandler.net.sendToAllAround(
					new PacketBombExplosion.Message(PacketBombExplosion.POISON_BOMB, posX, posY, posZ, blastMultiplier),
					new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

			this.playSound(WizardrySounds.ENTITY_POISON_BOMB_SMASH, 1.5F, rand.nextFloat() * 0.4F + 0.6F);
			this.playSound(WizardrySounds.ENTITY_POISON_BOMB_POISON, 1.2F, 1.0f);

			double range = Spells.poison_bomb.getProperty(Spell.EFFECT_RADIUS).floatValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(range, this.posX, this.posY,
					this.posZ, this.world);

			for(EntityLivingBase target : targets){
				if(target != entityHit && target != this.getThrower()
						&& !MagicDamage.isEntityImmune(DamageType.POISON, target)){
					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.POISON),
							Spells.poison_bomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);
					if(!this.world.isRemote){
						target.addPotionEffect(new PotionEffect(MobEffects.POISON,
								Spells.poison_bomb.getProperty(Spell.SPLASH_EFFECT_DURATION).intValue(),
								Spells.poison_bomb.getProperty(Spell.SPLASH_EFFECT_STRENGTH).intValue()));
					}
				}
			}
		}

		this.setDead();
	}

@Override
        public void tick() {
            this.charger.getLookControl().setLookAt(this.chargePos.x(), this.chargePos.y() - 1, this.chargePos.z(), 10.0F, this.charger.getMaxHeadXRot());

            --this.windup;
            if (this.windup == 0){
                PathNavigation pathnavigation = this.charger.getNavigation();
                Path path = pathnavigation.createPath(BlockPos.containing(this.chargePos), 0);
                if (path != null && path.canReach()){
                    pathnavigation.moveTo(path, this.speed);
                } else {
                    pathnavigation.moveTo(this.chargePos.x(), this.chargePos.y(), this.chargePos.z(), this.speed);
                }
            }
            if (this.windup <= 0) {
                List<LivingEntity> list = this.charger.level.getNearbyEntities(LivingEntity.class, RAM_TARGET_CONDITIONS, this.charger, this.charger.getBoundingBox());
                list.removeIf(livingEntity -> MobUtil.areAllies(this.charger, livingEntity));
                if (!list.isEmpty()) {
                    LivingEntity livingentity = list.get(0);
                    DamageSource damageSource = this.charger instanceof IOwned owned && owned.getTrueOwner() != null ? ModDamageSource.summonAttack(this.charger, owned.getTrueOwner()) : this.charger.damageSources().mobAttack(this.charger);
                    livingentity.hurt(damageSource, (float)this.charger.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    int i = this.charger.hasEffect(MobEffects.MOVEMENT_SPEED) ? this.charger.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier() + 1 : 0;
                    int j = this.charger.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) ? this.charger.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier() + 1 : 0;
                    float f = 0.25F * (float)(i - j);
                    float f1 = Mth.clamp(this.charger.getSpeed() * 1.65F, 0.2F, 3.0F) + f;
                    float f2 = livingentity.isDamageSourceBlocked(damageSource) ? 0.5F : 1.0F;
                    if (this.ramDirection != null) {
                        livingentity.knockback((double) (f2 * f1) * this.getKnockbackForce.applyAsDouble(this.charger), this.ramDirection.x(), this.ramDirection.z());
                    }
                    this.stop();
                    this.charger.level.playSound((Player)null, this.charger, this.getImpactSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                } else if (this.hasRammedHornBreakingBlock()) {
                    this.charger.level.playSound((Player)null, this.charger, this.getImpactSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                    boolean flag = this.charger instanceof TwilightGoat goat && goat.dropHorn();
                    if (flag) {
                        this.charger.level.playSound((Player)null, this.charger, this.getHornBreakSound.apply(this.charger), SoundSource.NEUTRAL, 1.0F, 1.0F);
                    }

                    this.stop();
                } else {
                    boolean flag1 = this.chargePos == null || this.chargePos.closerThan(this.charger.position(), 0.25D);
                    if (flag1) {
                        this.stop();
                    }
                }
            } else {
                if (this.charger instanceof ICharger chargeMob) {
                    chargeMob.setCharging(true);
                }
            }
        }

public void attackMobs(LivingEntity pTarget, AbstractReaper reaper){
            if (reaper.getMasterOwner() instanceof Player player) {
                if (SEHelper.getSoulGiven(pTarget) > 0) {
                    SEHelper.increaseSouls(player, ItemConfig.DarkScytheSouls.get() * 5);
                }
            }
            float f = (float)reaper.getAttributeValue(Attributes.ATTACK_DAMAGE);
            float f1 = EnchantmentHelper.getDamageBonus(reaper.getMainHandItem(), pTarget.getMobType());
            float f2 = 1.0F;
            f = f * (0.2F + f2 * f2 * 0.8F);
            f1 = f1 * f2;
            f = f + f1;

            float f3 = 1.0F + SweepingEdgeEnchantment.getSweepingDamageRatio(3) * f;
            int j = EnchantmentHelper.getFireAspect(reaper);
            double area = 2.0D;
            for (LivingEntity livingentity : reaper.level.getEntitiesOfClass(LivingEntity.class, this.reaper.getBoundingBox().move(this.getHorizontalLookAngle().scale(2.0D)).inflate(area, area, area))) {
                if (livingentity != reaper && !MobUtil.areAllies(reaper, livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && reaper.distanceToSqr(livingentity) < 16.0D && livingentity != reaper.getVehicle()) {
                    livingentity.knockback(0.4F, (double) Mth.sin(reaper.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(reaper.getYRot() * ((float) Math.PI / 180F))));
                    if (livingentity.hurt(this.reaper.getServantAttack(), f3)) {
                        if (j > 0) {
                            livingentity.setSecondsOnFire(j * 4);
                        }
                        if (reaper.getMasterOwner() instanceof Player player) {
                            boolean giveSoul = false;
                            if (livingentity instanceof IOwned owned) {
                                if (owned.getMasterOwner() != reaper) {
                                    giveSoul = true;
                                }
                            } else {
                                giveSoul = true;
                            }
                            if (giveSoul) {
                                if (SEHelper.getSoulGiven(livingentity) > 0) {
                                    SEHelper.increaseSouls(player, ItemConfig.DarkScytheSouls.get() * 5);
                                }
                            }
                        }
                        EnchantmentHelper.doPostHurtEffects(livingentity, reaper);
                        EnchantmentHelper.doPostDamageEffects(reaper, livingentity);
                    }
                }
            }

            reaper.level.playSound(null, reaper.getX(), reaper.getY(), reaper.getZ(), ModSounds.SCYTHE_SWING.get(), reaper.getSoundSource(), 1.0F, 1.0F);
            double d0 = -Mth.sin(reaper.getYRot() * ((float)Math.PI / 180F));
            double d1 = Mth.cos(reaper.getYRot() * ((float)Math.PI / 180F));
            if (reaper.level instanceof ServerLevel serverLevel) {
                serverLevel.sendParticles(ParticleTypes.SWEEP_ATTACK, reaper.getX() + d0, reaper.getY(0.5D), reaper.getZ() + d1, 0, d0, 0.0D, d1, 0.0D);
            }
        }

public static void renderDarknessVignette(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
        Minecraft minecraft = Minecraft.getInstance();
        PoseStack poseStack = guiGraphics.pose();
        Player player = minecraft.player;
        var data = player.getData(MalumAttachmentTypes.TOUCH_OF_DARKNESS);
        if (data.touchOfDarkness == 0f) {
            return;
        }
        int screenWidth = minecraft.getWindow().getGuiScaledWidth();
        int screenHeight = minecraft.getWindow().getGuiScaledHeight();

        float effectStrength = Easing.SINE_IN_OUT.ease(data.touchOfDarkness / TouchOfDarknessData.MAX_TOUCH_OF_DARKNESS);
        float alpha = Math.min(1, effectStrength * 5);
        float zoom = 0.5f + Math.min(0.35f, effectStrength);
        float intensity = 1f + (effectStrength > 0.5f ? (effectStrength - 0.5f) * 2.5f : 0);

        ExtendedShaderInstance shaderInstance = MalumShaders.TOUCH_OF_DARKNESS.getShaderInstance();
        shaderInstance.safeGetUniform("Speed").set(1000f);
        Consumer<Float> setZoom = f -> shaderInstance.safeGetUniform("Zoom").set(f);
        Consumer<Float> setIntensity = f -> shaderInstance.safeGetUniform("Intensity").set(f);
        ScreenVFXBuilder builder = VFXBuilders.createScreen()
                .setPositionWithWidth(screenWidth*-0.2f, screenHeight*-0.2f, screenWidth*1.4f, screenHeight*1.4f)
                .setAlpha(alpha)
                .setColor(0, 0,0)
                .setShader(shaderInstance);

        poseStack.pushPose();
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();

        for (int i = 0; i < 4; i++) {
            poseStack.pushPose();
            float angle = ((player.level().getGameTime() + deltaTracker.getGameTimeDeltaTicks()) / 80 + i * 2.09f) * 6.28f;
            float xOffset = Mth.sin(angle) * 20;
            float yOffset = Mth.cos(angle) * 20;
            poseStack.translate(xOffset, yOffset, 0);
            setZoom.accept(zoom);
            setIntensity.accept(intensity);
            builder.setAlpha(alpha).blit(poseStack);

            setZoom.accept(zoom * 1.25f + 0.15f);
            setIntensity.accept(intensity * 0.8f + 0.5f);
            builder.setAlpha(0.5f * alpha).blit(poseStack);
            poseStack.popPose();
        }

        RenderSystem.disableBlend();
        poseStack.popPose();

        shaderInstance.applyUniformDefaults();
    }

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity target = result.getEntity();
        Entity shooter = this.getOwner();

        float motion = (float) this.getDeltaMovement().length();
        int damage = Mth.ceil(Mth.clamp((double) motion * 0.5F * this.getBaseDamage(), 0.0D, 2.147483647E9D));

        DamageSource damagesource = UPDamageTypes.shuriken(this.level(), this, shooter);

        if (shooter instanceof LivingEntity living) {
            living.setLastHurtMob(target);
        }

        boolean isEnderman = target.getType() == EntityType.ENDERMAN;
        if (this.isOnFire() && !isEnderman) {
            target.setSecondsOnFire(5);
        }

        if (target.hurt(damagesource, (float) damage)) {
            if (isEnderman) return;

            if (target instanceof LivingEntity livingTarget) {

                if (!this.level().isClientSide() && shooter instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingTarget, shooter);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) shooter, livingTarget);
                }

                this.doPostHurtEffects(livingTarget);
                if (livingTarget != shooter && livingTarget instanceof Player && shooter instanceof ServerPlayer && !this.isSilent()) {
                    ((ServerPlayer) shooter).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }

            }

            this.playSound(this.getDefaultHitGroundSoundEvent(), 1.0F, 1.25F / (this.random.nextFloat() * 0.2F + 0.9F));
        }
        else {
            target.setRemainingFireTicks(target.getRemainingFireTicks());
            this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
            this.setYRot(this.getYRot() + 180.0F);
            this.yRotO += 180.0F;
            if (!this.level().isClientSide() && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                    this.spawnAtLocation(this.getPickupItem(), 0.1F);
                }
                this.discard();
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        refreshDimensions();
        onUpdateParts();
        if (this.attack() && this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player) {
            LivingEntity target = DragonUtils.riderLookingAtEntity(this, (Player) this.getControllingPassenger(), 3);
            if (this.getAnimation() != ANIMATION_BITE) {
                this.setAnimation(ANIMATION_BITE);
                this.playSound(this.getScale() > 3 ? IafSoundRegistry.DEATHWORM_GIANT_ATTACK : IafSoundRegistry.DEATHWORM_ATTACK, 1, 1);
                if (this.getRandom().nextInt(3) == 0 && this.getScale() > 1) {
                    float radius = 1.5F * this.getScale();
                    float angle = (0.01745329251F * this.yBodyRot);
                    double extraX = radius * Mth.sin((float) (Math.PI + angle));
                    double extraZ = radius * Mth.cos(angle);
                    BlockLaunchExplosion explosion = new BlockLaunchExplosion(level, this, this.getX() + extraX, this.getY() - this.getEyeHeight(), this.getZ() + extraZ, this.getScale() * 0.75F);
                    explosion.explode();
                    explosion.finalizeExplosion(true);
                }
            }
            if (target != null) {
                target.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (this.isInSand()) {
            BlockPos pos = new BlockPos(this.getX(), this.getSurface((int) Math.floor(this.getX()), (int) Math.floor(this.getY()), (int) Math.floor(this.getZ())), this.getZ()).below();
            BlockState state = level.getBlockState(pos);
            if (state.isSolidRender(level, pos)) {
                if (level.isClientSide) {
                    this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, state), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getSurface((int) Math.floor(this.getX()), (int) Math.floor(this.getY()), (int) Math.floor(this.getZ())) + 0.5F, this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
                }
            }
            if (this.tickCount % 10 == 0) {
                this.playSound(SoundEvents.SAND_BREAK, 1, 0.5F);
            }
        }
        if (this.up() && this.onGround) {
            this.jumpFromGround();
        }
        boolean inSand = isInSand() || this.getControllingPassenger() == null;
        if (inSand && !this.isSandNavigator) {
            switchNavigator(true);
        }
        if (!inSand && this.isSandNavigator) {
            switchNavigator(false);
        }
        if (level.isClientSide) {
            tail_buffer.calculateChainSwingBuffer(90, 20, 5F, this);
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void tick() {
        super.tick();

        if (damageDelay >= 0) --damageDelay;

        if (!emerged) {
            emerged = true;
            damageDelay = 2;
            playSound(MMSounds.ENTITY_BLUFF_SPIKE_EMERGE.get(), 1, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
            if (level().isClientSide()) {
                for (int i = 0; i < 30; i++) {
                    Vec3 offset = new Vec3(0.6 + random.nextFloat() * 0.2, 0.1, 0).yRot(random.nextFloat() * (float) Math.PI * 2f);
                    Vec3 vel = offset.normalize().scale(random.nextGaussian() * 0.12).yRot(random.nextFloat() * 0.2f - 0.1f).add(0, random.nextDouble() * 0.45 + 0.2, 0).add(getForward().scale(0.1));
                    AdvancedTerrainParticle.spawnTerrainParticle(level(), ParticleHandler.TERRAIN, getX() + offset.x, getY(), getZ() + offset.z, vel.x, vel.y, vel.z, 0, 0.4f + random.nextGaussian() * 0.3, 0.94f, 25 + random.nextFloat() * 10, getBlock(), new ParticleComponent[]{
                            new ParticleComponent.Gravity(1)
                    });
                }
            }
        }

        if (damageDelay == 0 && !level().isClientSide()) {
            damageDelay = -1;
            List<Entity> entitiesHit = level().getEntities(this, getBoundingBox().inflate(0.4), e -> e.canBeHitByProjectile() && e != getCaster() && !(e instanceof ItemEntity));
            double damage = 10;
            if (getCaster() != null) {
                if (getCaster() instanceof EntityBluff) {
                    AttributeInstance attrib = getCaster().getAttribute(Attributes.ATTACK_DAMAGE);
                    if (attrib != null) {
                        damage = attrib.getValue();
                    }
                    damage = damage * ConfigHandler.COMMON.MOBS.BLUFF.combatConfig.attackMultiplier.get();
                }
            }
            for (Entity entity : entitiesHit) {
                if (getCaster() instanceof EntityBluff && entity instanceof EntityBluff) continue;
                if (entity instanceof ItemEntity) continue;
                entity.hurt(damageSources().mobProjectile(this, getCaster()), (float) damage);
                float applyKnockbackResistance = 0;
                if (entity instanceof LivingEntity) {
                    applyKnockbackResistance = (float) ((LivingEntity) entity).getAttribute(Attributes.KNOCKBACK_RESISTANCE).getValue();
                }
                double y = 0;
                if (entity.onGround()) {
                    y += 0.15 * (1 - applyKnockbackResistance);
                }
                entity.setDeltaMovement(entity.getDeltaMovement().add(0, y, 0));
                if (entity instanceof ServerPlayer) {
                    ((ServerPlayer) entity).connection.send(new ClientboundSetEntityMotionPacket(entity));
                }
            }
        }
    }

public void tick() {
        if (this.level != null) {
            ++this.tickCount;
            if (this.level instanceof ServerLevel serverLevel) {
                int radius = 8 + this.getEnchantments().getOrDefault(ModEnchantments.RADIUS.get(), 0);
                if (this.target == null) {
                    for (LivingEntity livingEntity : serverLevel.getEntitiesOfClass(LivingEntity.class, new AABB(this.worldPosition).inflate(radius * 2))) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.distanceToSqr(this.getBlockPos().getCenter()) <= Mth.square(radius)) {
                            boolean flag = livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.25F;
                            if (this.getTrueOwner() != null) {
                                flag &= !MobUtil.areAllies(this.getTrueOwner(), livingEntity);
                            } else {
                                flag &= !this.isAllyWith(livingEntity);
                            }
                            if (flag) {
                                this.target = livingEntity;
                            }
                        }
                    }
                } else {
                    if (!this.target.isAlive() || this.target.getHealth() < this.target.getMaxHealth() * 0.25F || this.target.distanceToSqr(this.getBlockPos().getCenter()) > Mth.square(radius)) {
                        this.attackTick = 0;
                        this.target = null;
                    } else {
                        ++this.attackTick;
                        if (this.attackTick % 20 == 0) {
                            Vec3 vector3d1 = this.getBlockPos().getCenter();
                            DamageSource damageSource = this.getTrueOwner() != null ? ModDamageSource.soulLeech(this.getTrueOwner(), this.getTrueOwner()) : this.level.damageSources().magic();
                            this.target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), 10, 0, false, false));
                            if (this.target.hurt(damageSource, this.target.getMaxHealth() * 0.1F)) {
                                ColorUtil colorUtil1 = new ColorUtil(0x5038dd);
                                serverLevel.sendParticles(new SpirallingParticleOption(1.0F, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 5), vector3d1.x, vector3d1.y, vector3d1.z, 1, 0.0D, 0.0D, 0.0D, 1.0D);
                                Vec3 vec3 = new Vec3(this.target.getX(), this.target.getY() + (this.target.getBbHeight() / 2.0F), this.target.getZ());
                                serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil1, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                                for (int i = 0; i < 8; ++i) {
                                    Vec3 vec31 = new Vec3(this.target.getRandomX(1.0F), this.target.getRandomY(), this.target.getRandomZ(1.0F));
                                    serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 0x5038dd, 10), vec31.x, vec31.y, vec31.z, 1, 0.0, 0.0, 0.0, 0.0);
                                }
                                this.level.playSound(null, this.worldPosition, ModSounds.SOUL_EAT.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                if (this.getTrueOwner() instanceof Player player) {
                                    if (SEHelper.getSoulGiven(this.target) > 0) {
                                        int enchantment = this.getEnchantments().getOrDefault(ModEnchantments.SOUL_EATER.get(), 0);
                                        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                        SEHelper.increaseSouls(player, MainConfig.BlackCrystalSouls.get() * soulEater);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public void attackMobs(ItemStack pStack, LivingEntity pTarget, Player pPlayer){
        int enchantment = pStack.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get());
        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
        if (SEHelper.getSoulGiven(pTarget) > 0) {
            SEHelper.increaseSouls(pPlayer, ItemConfig.DarkScytheSouls.get() * soulEater);
        }

        float f = (float)pPlayer.getAttributeValue(Attributes.ATTACK_DAMAGE);
        float f1 = EnchantmentHelper.getDamageBonus(pPlayer.getMainHandItem(), pTarget.getMobType());
        float f2 = pPlayer.getAttackStrengthScale(0.5F);
        f = f * (0.2F + f2 * f2 * 0.8F);
        f1 = f1 * f2;
        f = f + f1;

        if (f > 0.5F || f1 > 0.5F) {
            float f3 = 1.0F + EnchantmentHelper.getSweepingDamageRatio(pPlayer) * f;
            int j = EnchantmentHelper.getFireAspect(pPlayer);
            double area = 1.0D;
            if (f2 > 0.9F) {
                area = 2.0D;
            }
            for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area, 0.25D, area))) {
                if (livingentity != pPlayer && livingentity != pTarget && !pPlayer.isAlliedTo(livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && pPlayer.distanceToSqr(livingentity) < 16.0D && livingentity != pPlayer.getVehicle()) {
                    livingentity.knockback(0.4F, (double) Mth.sin(pPlayer.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(pPlayer.getYRot() * ((float) Math.PI / 180F))));
                    if (livingentity.hurt(livingentity.damageSources().playerAttack(pPlayer), f3)) {
                        if (j > 0) {
                            livingentity.setSecondsOnFire(j * 4);
                        }
                        pStack.hurtAndBreak(1, pPlayer, (p_220045_0_) ->
                                p_220045_0_.broadcastBreakEvent(EquipmentSlot.MAINHAND));
                        boolean giveSoul = false;
                        if (livingentity instanceof OwnableEntity owned){
                            if (owned.getOwner() != pPlayer){
                                giveSoul = true;
                            }
                        } else {
                            giveSoul = true;
                        }
                        if (giveSoul) {
                            if (SEHelper.getSoulGiven(livingentity) > 0) {
                                SEHelper.increaseSouls(pPlayer, ItemConfig.DarkScytheSouls.get() * soulEater);
                            }
                        }
                        EnchantmentHelper.doPostHurtEffects(livingentity, pPlayer);
                        EnchantmentHelper.doPostDamageEffects(pPlayer, livingentity);
                    }
                }
            }
        }

        pPlayer.level.playSound((Player) null, pPlayer.getX(), pPlayer.getY(), pPlayer.getZ(), ModSounds.SCYTHE_SWING.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
        pPlayer.sweepAttack();
    }

@Override
	public boolean hurtEnemy(ItemStack stack, LivingEntity target, LivingEntity attacker)
	{
		if (attacker instanceof FakePlayer)
			return false;

		if (target == null || attacker == null || attacker.getCommandSenderWorld().isClientSide || (attacker instanceof Player && !(attacker instanceof ServerPlayer)))
			return false;

		if (!target.canChangeDimensions())
			return false;

		if (target instanceof Player)
			return false;

		if (target.isBaby() && !(target instanceof Enemy))
			return false;

		if (!target.isAlive() || target.getHealth() < 0.5F)
			return false;

//		EntityEntry entityEntry = EntityRegistry.getEntry(target.getClass());
//		if (entityEntry == null)
//			return false;
		ResourceLocation id = ForgeRegistries.ENTITY_TYPES.getKey(target.getType());
		int lifeEssenceRatio = BloodMagicAPI.INSTANCE.getValueManager().getSacrificial().getOrDefault(id, ConfigManager.COMMON.entitySacrificeDefault.get());
//		int lifeEssenceRatio = 25;

		if (lifeEssenceRatio <= 0)
			return false;

		int lifeEssence = (int) (lifeEssenceRatio * target.getHealth());
//		if (target instanceof AnimalEntity)
//		{
//			lifeEssence = (int) (lifeEssence * (1 + PurificationHelper.getCurrentPurity((AnimalEntity) target)));
//		}

		if (target.isBaby())
		{
			lifeEssence *= 0.5F;
		}

		if (PlayerSacrificeHelper.findAndFillAltar(attacker.getCommandSenderWorld(), target, lifeEssence, true))
		{
			target.getCommandSenderWorld().playSound(null, target.getX(), target.getY(), target.getZ(), SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F, 2.6F + (target.getCommandSenderWorld().random.nextFloat() - target.getCommandSenderWorld().random.nextFloat()) * 0.8F);
			target.setHealth(0.00001f);
			target.invulnerableTime = 0;
			target.hurt(target.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 10);
//			target.onDeath(DamageSourceBloodMagic.INSTANCE);
		}

		return false;
	}

public void aiStep() {
		if (this.isSitting() || this.isTameSitting()) {
			this.getNavigation().stop();
			this.moveControl.setWantedPosition(this.getX(), this.getY(), this.getZ(), 0);
			this.setSpeed(0);
			this.setDeltaMovement(0, this.getDeltaMovement().y, 0);
		}
		if (!this.level().isClientSide() && this.isAlive()) {
			if (this.isSitting() || this.isTameSitting()) {
				this.getNavigation().stop();
				this.moveControl.setWantedPosition(this.getX(), this.getY(), this.getZ(), 0);
				this.setSpeed(0);
				this.setDeltaMovement(0, this.getDeltaMovement().y, 0);
			}
			++this.eatTicks;
			ItemStack itemstack = this.getItemBySlot(EquipmentSlot.MAINHAND);
			if (this.canEatItem(itemstack)) {
				if (this.eatTicks > 600) {
					ItemStack itemstack1 = itemstack.finishUsingItem(this.level(), this);
					if (!itemstack1.isEmpty()) {
						this.setItemSlot(EquipmentSlot.MAINHAND, itemstack1);
					}

					this.eatTicks = 0;
				} else if (this.eatTicks > 560 && this.random.nextFloat() < 0.1F) {
					this.level().broadcastEntityEvent(this, (byte)45);
				}
			}

			LivingEntity livingentity = this.getTarget();
			if (livingentity == null || !livingentity.isAlive()) {
				this.setCrouching(false);
				this.func_213502_u(false);
			}
		}
		if (this.getTarget() != null) {
			if (this.getVehicle() != null) {
				if (this.getVehicle() == this.getTarget() && this.tickCount % 20 == 0) {
					AttributeInstance iattributeinstance = this.getAttribute(Attributes.ATTACK_DAMAGE);
					this.getTarget().hurt(this.damageSources().mobAttack(this), (float) iattributeinstance.getBaseValue());
				}
			}
		}

		if (this.isSleeping() || this.isMovementBlocked() || this.isAsleep() || this.isTameSitting()) {
			this.jumping = false;
			this.xxa = 0.0F;
			this.zza = 0.0F;
		}
		super.aiStep();
		if (this.isVelociraptorAggroed() && this.random.nextFloat() < 0.05F) {
		}
	}

@Override
    public void aiStep() {
        super.aiStep();
        LivingEntity attackTarget = this.getTarget();
        if (Math.abs(firstWidth - INITIAL_WIDTH * getSize()) > 0.01F || Math.abs(firstHeight - INITIAL_HEIGHT * getSize()) > 0.01F) {
            firstWidth = INITIAL_WIDTH * getSize();
            firstHeight = INITIAL_HEIGHT * getSize();
        }
        if (this.getAnimation() == ANIMATION_SPAWN && this.getAnimationTick() < 30) {
            BlockState belowBlock = level.getBlockState(this.blockPosition().below());
            if (belowBlock.getBlock() != Blocks.AIR) {
                for (int i = 0; i < 5; i++) {
                    this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, belowBlock), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.getBoundingBox().minY, this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth() * 2.0F) - (double) this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
                }
            }
            this.setDeltaMovement(0, this.getDeltaMovement().y, this.getDeltaMovement().z);
        }
        if (attackTarget != null && this.distanceTo(attackTarget) < 4 && this.hasLineOfSight(attackTarget)) {
            if (this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(ANIMATION_SLASH);
            }
            this.lookAt(attackTarget, 360, 80);
            if (this.getAnimation() == ANIMATION_SLASH && (this.getAnimationTick() == 9 || this.getAnimationTick() == 19)) {
                attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                attackTarget.knockback(0.25F, this.getX() - attackTarget.getX(), this.getZ() - attackTarget.getZ());
            }
        }
        if (!level.isClientSide) {
            if (this.getTarget() != null) {
                hostileTicks++;
                if (this.getScreamStage() == 0) {
                    if (hostileTicks > 20) {
                        this.setScreamStage(1);
                    }
                } else {
                    if (this.tickCount % 20 < 10) {
                        this.setScreamStage(1);
                    } else {
                        this.setScreamStage(2);
                    }
                }
            } else {
                if (this.getScreamStage() > 0) {
                    if (this.tickCount % 20 < 10 && this.getScreamStage() == 2) {
                        this.setScreamStage(1);
                    } else {
                        this.setScreamStage(0);
                    }
                }
                hostileTicks = 0;
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	protected void onImpact(RayTraceResult par1RayTraceResult){

		if(par1RayTraceResult.entityHit != null){
			// This is if the force orb gets a direct hit
			this.playSound(WizardrySounds.ENTITY_FORCE_ORB_HIT, 1.0F, 1.2F / (this.rand.nextFloat() * 0.2F + 0.9F));
		}

		// Particle effect
		if(this.world.isRemote){
			for(int j = 0; j < 20; j++){
				float brightness = 0.5f + (rand.nextFloat() / 2);
				ParticleBuilder.create(Type.SPARKLE, rand, posX, posY, posZ, 0.25, true).time(6)
				.clr(brightness, 1.0f, brightness + 0.2f).spawn(world);
			}
			this.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, this.posX, this.posY, this.posZ, 0, 0, 0);
		}

		if(!this.world.isRemote){

			// 2 gives a cool flanging effect!
			float pitch = this.rand.nextFloat() * 0.2F + 0.3F;
			this.playSound(WizardrySounds.ENTITY_FORCE_ORB_HIT_BLOCK, 1.5F, pitch);
			this.playSound(WizardrySounds.ENTITY_FORCE_ORB_HIT_BLOCK, 1.5F, pitch - 0.01f);

			double blastRadius = Spells.force_orb.getProperty(Spell.BLAST_RADIUS).floatValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(blastRadius, this.posX,
					this.posY, this.posZ, this.world);

			for(EntityLivingBase target : targets){
				if(target != this.getThrower()){

					double velY = target.motionY;

					double dx = this.posX - target.posX > 0 ? -0.5 - (this.posX - target.posX) / 8
							: 0.5 - (this.posX - target.posX) / 8;
					double dz = this.posZ - target.posZ > 0 ? -0.5 - (this.posZ - target.posZ) / 8
							: 0.5 - (this.posZ - target.posZ) / 8;

					float damage = Spells.force_orb.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.BLAST), damage);

					target.motionX = dx;
					target.motionY = velY + 0.4;
					target.motionZ = dz;
				}
			}

			this.setDead();
		}
	}

public static void surroundTremor(LivingEntity livingEntity, int distance, double topY, float side, boolean grab, float damage, float airborne) {
        int hitY = Mth.floor(livingEntity.getBoundingBox().minY - 0.5D);
        double spread = Math.PI * (double)2.0F;
        int arcLen = Mth.ceil((double)distance * spread);
        double minY = livingEntity.getY() - 1.0D;
        double maxY = livingEntity.getY() + topY;

        for(int i = 0; i < arcLen; ++i) {
            double theta = ((double)i / ((double)arcLen - 1.0D) - 0.5D) * spread;
            double vx = Math.cos(theta);
            double vz = Math.sin(theta);
            double px = livingEntity.getX() + vx * (double)distance + (double)side * Math.cos((double)(livingEntity.yBodyRot + 90.0F) * Math.PI / 180.0D);
            double pz = livingEntity.getZ() + vz * (double)distance + (double)side * Math.sin((double)(livingEntity.yBodyRot + 90.0F) * Math.PI / 180.0D);
            float factor = 1.0F - (float)distance / 12.0F;
            int hitX = Mth.floor(px);
            int hitZ = Mth.floor(pz);
            BlockPos blockPos = new BlockPos(hitX, hitY, hitZ);

            BlockState blockState;
            for(blockState = livingEntity.level.getBlockState(blockPos); blockState.getRenderShape() != RenderShape.MODEL; blockState = livingEntity.level.getBlockState(blockPos)) {
                blockPos = blockPos.below();
            }
            BlockState blockAbove = livingEntity.level.getBlockState(blockPos.above());

            if (blockState != Blocks.AIR.defaultBlockState() && !blockState.hasBlockEntity() && !blockAbove.blocksMotion()) {
                ModFallingBlock fallingBlock = new ModFallingBlock(livingEntity.level, Vec3.atCenterOf(blockPos.above()), blockState, (float) (0.2D + livingEntity.getRandom().nextGaussian() * 0.15D));
                livingEntity.level.addFreshEntity(fallingBlock);
            }

            if (distance % 4 == 0) {
                livingEntity.level.playSound(null, blockPos.above(), ModSounds.WALL_ERUPT.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
                livingEntity.level.playSound(null, blockPos.above(), ModSounds.DIRT_DEBRIS.get(), SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
                livingEntity.level.playSound(null, blockPos.above(), SoundEvents.GENERIC_EXPLODE, SoundSource.PLAYERS, 1.0F, 0.8F + livingEntity.level.random.nextFloat() * 0.4F);
            }

            AABB selection = new AABB(px - 0.5D, minY, pz - 0.5D, px + 0.5D, maxY, pz + 0.5D);
            List<LivingEntity> entities = livingEntity.level.getEntitiesOfClass(LivingEntity.class, selection);
            for (LivingEntity target : entities) {
                if (!MobUtil.areAllies(target, livingEntity) && target != livingEntity) {
                    boolean flag = target.hurt(livingEntity.damageSources().mobAttack(livingEntity), damage);
                    if (flag) {
                        if (grab) {
                            if (target.isDamageSourceBlocked(livingEntity.damageSources().mobAttack(livingEntity))) {
                                MobUtil.disableShield(target);
                            }
                        } else {
                            MobUtil.push(target, 0.0D, (double) (airborne * (float) distance) + livingEntity.getRandom().nextDouble() * 0.15D, 0.0D);
                        }
                    }
                }
            }
        }

    }

@Override
    public void onLivingUpdate() {
        super.onLivingUpdate();

        if (this.getAnimation() == EntityAnimation.RESTING.get()) {
            if (this.getAttackTarget() != null || this.isInWater() || !this.onGround || this.hurtTime > 0) {
                this.setAnimation(EntityAnimation.IDLE.get());
            }
        }

        if (isBaskingNow()) {
            this.getNavigator().clearPath();
            this.getMoveHelper().setMoveTo(this.posX, this.posY, this.posZ, 0.0D);
            this.setAIMoveSpeed(0.0F);
            this.setSprinting(false);
            this.isJumping = false;
            this.moveForward = 0.0F;
            this.moveStrafing = 0.0F;

            this.motionX = 0.0D;
            this.motionZ = 0.0D;
            this.velocityChanged = false;
        }

        if (!this.world.isRemote
                && this.isInWater()
                && this.getAnimation() == EntityAnimation.SNAP.get()
                && this.getAttackTarget() != null
                && this.getAttackTarget().isEntityAlive()) {
            if (this.ticksExisted % 20 == 0) {
                EntityLivingBase target = this.getAttackTarget();
                target.attackEntityFrom(DamageSource.causeMobDamage(this), DEATH_ROLL_DOT_DAMAGE);
                Vec3d push = this.getLookVec().scale(0.15D).addVector(0, 0.02D, 0);
                target.motionX += push.x;
                target.motionY += push.y;
                target.motionZ += push.z;
            }
        }

        if (!this.world.isRemote
                && this.getAttackTarget() == null
                && !this.isInWater()
                && this.onGround
                && this.getAnimation() == EntityAnimation.IDLE.get()) {

            boolean canSeeSky = this.world.canSeeSky(this.getPosition());
            int sky = this.world.getLightFor(EnumSkyBlock.SKY, this.getPosition());
            boolean bright = sky > 10;

            if (canSeeSky && bright && this.rand.nextInt(BASKING_RAND) == 0) {
                this.setAnimation(EntityAnimation.RESTING.get());
                this.playSound(SoundEvents.BLOCK_SAND_PLACE, 0.2F, 0.9F + this.rand.nextFloat() * 0.2F);
            }
        }
    }

public InteractionResult mobInteract(Player p_34394_, InteractionHand p_34395_) {
        ItemStack itemstack = p_34394_.getItemInHand(p_34395_);
        if (itemstack.is(this.getIncreaseItem())) {
            if (this.getSize() < MobsConfig.MaxSlimeSize.get()) {
                if (!p_34394_.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }

                this.setSize(this.getSize() + 1, true);
                this.playSound(this.getAttackSound());

                return InteractionResult.SUCCESS;
            } else if (this.getHealth() < this.getMaxHealth()) {
                if (!p_34394_.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }
                this.heal(20.0F);
                this.playSound(this.getSquishSound());
                return InteractionResult.SUCCESS;
            } else {
                return InteractionResult.CONSUME;
            }
        } else if (itemstack.is(this.getHealItem())) {
            if (this.getHealth() < this.getMaxHealth()) {
                if (!p_34394_.getAbilities().instabuild) {
                    itemstack.shrink(1);
                }
                this.heal(2.0F);
                this.playSound(this.getSquishSound());
                return InteractionResult.SUCCESS;
            } else {
                return InteractionResult.CONSUME;
            }
        } else if (this.getTrueOwner() != null && p_34394_ == this.getTrueOwner()) {
            if (!this.isInterested()) {
                if (p_34395_ == InteractionHand.MAIN_HAND && itemstack.isEmpty() && !p_34394_.isCrouching()) {
                    this.setIsInterested(true);
                    this.interestTime = 40;
                    this.level.broadcastEntityEvent(this, (byte) 102);
                    this.playSound(this.getSquishSound(), 1.0F, 2.0F);
                    this.heal(1.0F);
                    if (this instanceof MagmaCubeServant){
                        if (!p_34394_.fireImmune()){
                            p_34394_.setSecondsOnFire(5);
                            if (p_34394_.hurt(this.damageSources().hotFloor(), 2.0F)) {
                                p_34394_.playSound(SoundEvents.GENERIC_BURN, 0.4F, 2.0F + this.random.nextFloat() * 0.4F);
                            }
                        }
                    }
                    return InteractionResult.SUCCESS;
                }
            }
        }
        return super.mobInteract(p_34394_, p_34395_);
    }

private void executeAttacks() {
		if (this.currentState == State.MORTAR_SHOOTING && this.ticksProgress % 10 == 0) {
			HydraMortar mortar = new HydraMortar(TFEntities.HYDRA_MORTAR.get(), this.headEntity.level(), this.headEntity);

			// launch blasting mortars if the player is hiding
			if (this.targetEntity != null && !this.headEntity.canEntityBeSeen(this.targetEntity)) {
				mortar.setToBlasting();
			}

			this.headEntity.playSound(TFSounds.HYDRA_SHOOT.get(), 10.0F, (this.headEntity.level().getRandom().nextFloat() - this.headEntity.level().getRandom().nextFloat()) * 0.2F + 1.0F);
			this.headEntity.level().addFreshEntity(mortar);

		}
		if (this.headEntity.getState() == State.BITING) {
			// damage nearby things
			List<Entity> nearbyList = this.headEntity.level().getEntities(this.headEntity, this.headEntity.getBoundingBox().inflate(0.0, 1.0, 0.0));

			for (Entity nearby : nearbyList) {
				if (nearby instanceof LivingEntity living && nearby != this.hydra) {
					//is a player holding a shield? Let's do some extra stuff!
					if (nearby instanceof Player player && player.isBlocking()) {
						if (!player.getCooldowns().isOnCooldown(player.getUseItem())) {
							//cause severe damage and play a shatter sound
							this.headEntity.level().playSound(null, player.blockPosition(), player.getUseItem().is(Items.SHIELD) ? TFSounds.WOOD_SHIELD_SHATTERS.get() : TFSounds.METAL_SHIELD_SHATTERS.get(), SoundSource.PLAYERS, 1.0F, player.getVoicePitch());
							player.getUseItem().hurtAndBreak(112, player, player.getUsedItemHand());
						}
						//add cooldown and knockback
						player.getCooldowns().addCooldown(player.getUseItem(), 200);
						player.stopUsingItem();
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.15F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					}

					// bite it!
					nearby.hurt(TFDamageTypes.getEntityDamageSource(living.level(), TFDamageTypes.HYDRA_BITE, this.hydra, TFEntities.HYDRA.get()), BITE_DAMAGE);

					//knockback!
					if (living instanceof Player player) {
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.1F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					} else {
						living.knockback(-this.headEntity.getDirection().getStepX(), 0.1F, -this.headEntity.getDirection().getStepZ());
					}
				}
			}
		}

		if (this.headEntity.getState() == State.FLAMING) {
			Entity target = getHeadLookTarget();

			if (target != null && target != this.headEntity.getParent() && (!(target instanceof HydraPart) || ((HydraPart) target).getParent() != this.headEntity.getParent()) && this.hydra.level() instanceof ServerLevel serverLevel) {
				if (!target.fireImmune() && target.hurtServer(serverLevel, TFDamageTypes.getEntityDamageSource(target.level(), TFDamageTypes.HYDRA_FIRE, this.hydra, TFEntities.HYDRA.get()), FLAME_DAMAGE)) {
					target.igniteForSeconds(FLAME_BURN_FACTOR);
				}
			}
		}
	}

