@Override
    public void tick() {
        super.tick();
        LivingEntity target = this.getTarget();
        if(this.isAlive()) {
            if (this.getAnimation() == DEEPLING_BRUTE_TRIDENT_THROW) {
                if (target != null) {
                    if (this.getAnimationTick() == 11) {
                        if(this.isInWaterOrRain() && !this.isPassenger()) {
                            double f1 = target.getX() - this.getX();
                            double f2 = target.getY() - this.getY();
                            double f3 = target.getZ() - this.getZ();
                            double f4 = Mth.sqrt((float) (f1 * f1 + f2 * f2 + f3 * f3));
                            float f5 = 2.0F;
                            f1 *= f5 / f4;
                            f2 *= f5 / f4;
                            f3 *= f5 / f4;
                            this.push((double)f1, (double)f2, (double)f3);
                            this.startAutoSpinAttack(20);
                            if (this.onGround()) {
                                this.move(MoverType.SELF, new Vec3(0.0D, (double)1.1999999F, 0.0D));
                            }
                            this.playSound( SoundEvents.TRIDENT_RIPTIDE_3,1.0F, 1.0F);
                        }else{
                            ThrownCoral_Bardiche_Entity throwntrident = new ThrownCoral_Bardiche_Entity(this.level(), this, new ItemStack(ModItems.CORAL_BARDICHE.get()));
                            double p0 = target.getX() - this.getX();
                            double p1 = target.getY(0.3333333333333333D) - throwntrident.getY();
                            double p2 = target.getZ() - this.getZ();
                            double p3 = Math.sqrt(p0 * p0 + p2 * p2);
                            throwntrident.shoot(p0, p1 + p3 * (double) 0.2F, p2, 1.6F, (float) (14 - this.level().getDifficulty().getId() * 4));
                            this.playSound(SoundEvents.DROWNED_SHOOT, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                            this.level().addFreshEntity(throwntrident);
                        }
                    }
                }
            }
            if (this.getAnimation() == DEEPLING_BRUTE_MELEE) {
                if (this.getAnimationTick() == 5) {
                    this.playSound(ModSounds.DEEPLING_SWING.get(), 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                    if (target != null) {
                        if (this.distanceTo(target) < 3.0F) {
                            float damage = (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE);
                            target.hurt(damageSources().mobAttack(this), damage);
                        }
                    }
                }
            }
        }
        AABB aabb = this.getBoundingBox();
        if (this.SpinAttackTicks > 0) {
            --this.SpinAttackTicks;
            this.checkAutoSpinAttack(aabb, this.getBoundingBox());
        }

    }

public void tick() {
        super.tick();
        this.prevGroundProgress = groundProgress;
        this.yBodyRot = this.getYRot();
        if (this.onGround() && groundProgress < 5F) {
            groundProgress++;
        }
        if (!this.onGround() && groundProgress > 0F) {
            groundProgress--;
        }
        if (!level().isClientSide) {
            Entity winch = getWinch();
            if (winch == null) {
                LivingEntity created = createWinch();
                level().addFreshEntity(created);
                this.setWinchUUID(created.getUUID());
                this.entityData.set(WINCH_ID, created.getId());
            } else {
                if (winch instanceof BoundroidWinchEntity winchEntity) {
                    winchEntity.linkWithHead(this);
                }
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                Vec3 distanceVec = target.position().subtract(this.position());
                if (distanceVec.horizontalDistance() < 1.2 && stopSlammingFor == 0) {
                    this.setSlamming(true);
                }
            }
            if (this.isSlamming()) {
                this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, -1, this.getDeltaMovement().z));
                if (this.onGround()) {
                    this.setSlamming(false);
                    this.playSound(ACSoundRegistry.BOUNDROID_SLAM.get());
                    this.stayOnGroundFor = 10;
                    this.stopSlammingFor = 30 + random.nextInt(20);
                    this.level().broadcastEntityEvent(this, (byte) 45);
                    AABB bashBox = new AABB(-1.5F, -2F, -1.5F, 1.5F, 1F, 1.5F);
                    bashBox = bashBox.move(this.position());
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
                        if (!isAlliedTo(entity) && !(entity instanceof BoundroidEntity) && !(entity instanceof BoundroidWinchEntity)) {
                            entity.hurt(damageSources().mobAttack(this), 5);
                        }
                    }
                }
            }
        }else if(isAlive()){
            AlexsCaves.PROXY.playWorldSound(this, (byte) 12);
        }
        if (stopSlammingFor > 0) {
            stopSlammingFor--;
        }
        if (stayOnGroundFor > 0) {
            stayOnGroundFor--;
        }
    }

@Override
    public void aiStep() {
        super.aiStep();
        if (playerStatueCooldown > 0) {
            playerStatueCooldown--;
        }
        LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null) {
            boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget.hasEffect(MobEffects.BLINDNESS);
            if (!blindness && this.deathTime == 0 && attackTarget instanceof Mob && !(attackTarget instanceof Player)) {
                forcePreyToLook(attackTarget);
            }
            if (isEntityLookingAt(attackTarget, this, 0.4)) {
                this.getLookControl().setLookAt(attackTarget.getX(), attackTarget.getY() + (double) attackTarget.getEyeHeight(), attackTarget.getZ(), (float) this.getMaxHeadYRot(), (float) this.getMaxHeadXRot());
            }
        }


        if (attackTarget != null && isEntityLookingAt(this, attackTarget, 0.4) && isEntityLookingAt(attackTarget, this, 0.4) && !isBlindfolded(attackTarget)) {
            boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget.hasEffect(MobEffects.BLINDNESS) || attackTarget instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) attackTarget).canBeTurnedToStone();
            if (!blindness && this.deathTime == 0) {
                if (this.getAnimation() != ANIMATION_SCARE) {
                    this.playSound(IafSoundRegistry.GORGON_ATTACK, 1, 1);
                    this.setAnimation(ANIMATION_SCARE);
                }
                if (this.getAnimation() == ANIMATION_SCARE) {
                    if (this.getAnimationTick() > 10) {
                        if (!level.isClientSide) {
                            if (playerStatueCooldown == 0) {
                                EntityStoneStatue statue = EntityStoneStatue.buildStatueEntity(attackTarget);
                                statue.absMoveTo(attackTarget.getX(), attackTarget.getY(), attackTarget.getZ(), attackTarget.getYRot(), attackTarget.getXRot());
                                if (!level.isClientSide) {
                                    level.addFreshEntity(statue);
                                }
                                statue.setYRot(attackTarget.getYRot());
                                statue.setYRot(attackTarget.getYRot());
                                statue.yHeadRot = attackTarget.getYRot();
                                statue.yBodyRot = attackTarget.getYRot();
                                statue.yBodyRotO = attackTarget.getYRot();
                                playerStatueCooldown = 40;
                                if (attackTarget instanceof Player) {

                                    attackTarget.hurt(IafDamageRegistry.causeGorgonDamage(this), Integer.MAX_VALUE);
                                } else {
                                    attackTarget.remove(RemovalReason.KILLED);
                                }
                                this.setTarget(null);

                            }
                        }
                    }
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!this.world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){
				// This is if the spark bomb gets a direct hit
				float damage = Spells.spark_bomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

				this.playSound(WizardrySounds.ENTITY_SPARK_BOMB_HIT, 1.0F, 1.2F / (this.rand.nextFloat() * 0.2F + 0.9F));

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK).setProjectile(),
						damage);
			}

			double seekerRange = Spells.spark_bomb.getProperty(Spell.EFFECT_RADIUS).doubleValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX, this.posY,
					this.posZ, this.world);

			List<Integer> secondaryTargetIDs = new ArrayList<>();

			for(int i = 0; i < Math.min(targets.size(), Spells.spark_bomb.getProperty(SECONDARY_MAX_TARGETS).intValue()); i++){

				boolean flag = targets.get(i) != entityHit && targets.get(i) != this.getThrower()
						&& !(targets.get(i) instanceof EntityPlayer
								&& ((EntityPlayer)targets.get(i)).isCreative());

				if(flag){
					EntityLivingBase target = targets.get(i);

					target.playSound(WizardrySounds.ENTITY_SPARK_BOMB_CHAIN, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK),
							Spells.spark_bomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);

					secondaryTargetIDs.add(target.getEntityId());
				}
			}

			// Notify clients to play the explosion effect, including lightning arcs to secondary targets
			int[] idArray = secondaryTargetIDs.stream().mapToInt(Integer::intValue).toArray();
			WizardryPacketHandler.net.sendToAllAround(
					new PacketBombExplosion.Message(PacketBombExplosion.SPARK_BOMB, posX, posY + height / 2, posZ,
							blastMultiplier, idArray),
					new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

			this.playSound(WizardrySounds.ENTITY_SPARK_BOMB_HIT_BLOCK, 0.5f, 0.5f);
		}

		this.setDead();
	}

@Inject(method = "tryUseTotem", at = @At("RETURN"), cancellable = true)
	private void tryUseTotem(DamageSource source, CallbackInfoReturnable<Boolean> callbackInfo) {
		if (!getWorld().isClient) {
			if (!callbackInfo.getReturnValueZ()) {
				boolean isPlayer = (Object) this instanceof PlayerEntity;
				PoppetData poppetData = BewitchmentAPI.getPoppet(getWorld(), BWObjects.DEATH_PROTECTION_POPPET, this);
				if (!poppetData.stack().isEmpty() && !(isPlayer && ReviveEvents.CANCEL_REVIVE.invoker().shouldCancel((PlayerEntity) (Object) this, source, poppetData.stack()))) {
					if (isPlayer) {
						ReviveEvents.ON_REVIVE.invoker().onRevive((PlayerEntity) (Object) this, source, poppetData.stack());
					}
					boolean sync = false;
					if (poppetData.stack().damage((Object) this instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == EntityType.WOLF && random.nextBoolean() ? 0 : 1, random, null) && poppetData.stack().getDamage() >= poppetData.stack().getMaxDamage()) {
						poppetData.stack().decrement(1);
						sync = true;
					}
					poppetData.update(getWorld(), sync);
					setHealth(1);
					clearStatusEffects();
					addStatusEffect(new StatusEffectInstance(StatusEffects.REGENERATION, 900, 1));
					addStatusEffect(new StatusEffectInstance(StatusEffects.ABSORPTION, 100, 1));
					addStatusEffect(new StatusEffectInstance(StatusEffects.FIRE_RESISTANCE, 800, 0));
					callbackInfo.setReturnValue(true);
				}
			}
			if (callbackInfo.getReturnValueZ() && (Object) this instanceof ServerPlayerEntity player && (!BWConfig.enableCurses || BWComponents.CURSES_COMPONENT.get(player).hasCurse(BWCurses.SUSCEPTIBILITY))) {
				BWComponents.TRANSFORMATION_COMPONENT.maybeGet(player).ifPresent(transformationComponent -> {
					if (transformationComponent.getTransformation() == BWTransformations.HUMAN) {
						if (source.getSource() instanceof VampireEntity || (source.getSource() instanceof PlayerEntity playerSource && BewitchmentAPI.isVampire(playerSource, true) && BewitchmentAPI.isPledged(playerSource, BWPledges.LILITH))) {
							transformationComponent.getTransformation().onRemoved(player);
							transformationComponent.setTransformation(BWTransformations.VAMPIRE);
							transformationComponent.getTransformation().onAdded(player);
							PlayerLookup.tracking(this).forEach(trackingPlayer -> SpawnSmokeParticlesPacket.send(trackingPlayer, this));
							SpawnSmokeParticlesPacket.send(player, this);
							getWorld().playSound(null, getBlockPos(), BWSoundEvents.ENTITY_GENERIC_CURSE, getSoundCategory(), getSoundVolume(), getSoundPitch());
						} else if (source.getSource() instanceof WerewolfEntity || (source.getSource() instanceof PlayerEntity playerSource && BewitchmentAPI.isWerewolf(playerSource, false) && BewitchmentAPI.isPledged(playerSource, BWPledges.HERNE))) {
							transformationComponent.getTransformation().onRemoved(player);
							transformationComponent.setTransformation(BWTransformations.WEREWOLF);
							transformationComponent.getTransformation().onAdded(player);
							int variant = -1;
							if (source.getSource() instanceof WerewolfEntity) {
								variant = source.getSource().getDataTracker().get(BWHostileEntity.VARIANT);
							} else if (source.getSource() instanceof PlayerEntity playerSource) {
								variant = BWComponents.ADDITIONAL_WEREWOLF_DATA_COMPONENT.get(playerSource).getVariant();
							}
							if (variant > -1) {
								BWComponents.ADDITIONAL_WEREWOLF_DATA_COMPONENT.get(player).setVariant(variant);
							}
							PlayerLookup.tracking(this).forEach(trackingPlayer -> SpawnSmokeParticlesPacket.send(trackingPlayer, this));
							SpawnSmokeParticlesPacket.send(player, this);
							getWorld().playSound(null, getBlockPos(), BWSoundEvents.ENTITY_GENERIC_CURSE, getSoundCategory(), getSoundVolume(), getSoundPitch());
						}
					}
				});
			}
		}
	}

@Override
    public void render(SoulwovenBannerBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        var blockState = blockEntityIn.getBlockState();
        var pos = blockEntityIn.getBlockPos();
        var spirit = blockEntityIn.spirit;
        var type = blockState.getValue(SoulwovenBannerBlock.BANNER_TYPE);
        var direction = type.direction.getAxis().isVertical() ? type.equals(SoulwovenBannerBlock.BannerType.HANGING_Z) ? Direction.NORTH : Direction.WEST : type.direction;
        float sway = ((float) Math.floorMod((pos.getX() * 7L + pos.getY() * 9L + pos.getZ() * 13L) + blockEntityIn.getLevel().getGameTime(), 100L) + partialTicks) / 100.0F;
        float swayRotation = (0.01F * Mth.cos((float) (Math.PI * 2) * sway)) * (float) Math.PI;

        poseStack.pushPose();
        poseStack.translate(0.5f, 0.5f, 0.5f);
        poseStack.mulPose(Axis.YN.rotationDegrees(direction.toYRot()));
        poseStack.translate(-0.5f, -0.5f, -0.5f);
        if (type.direction.getAxis().isHorizontal()) {
            poseStack.translate(0, -0.25f, 0.0625f);
            swayRotation -= 0.0125f;
        } else {
            poseStack.translate(0, 0, 0.5f);
            swayRotation = swayRotation - 0.0157f;
        }
        poseStack.translate(0, 1f, 0);
        poseStack.mulPose(Axis.XP.rotation(swayRotation));
        float xStart = 0;
        float xEnd = 1;
        float yStart = -2;
        float yEnd = 0;
        var patternData = blockEntityIn.patternData;
        var token = RenderTypeToken.createToken(patternData.texturePath());
        var banner = LodestoneRenderTypes.CUTOUT_TEXTURE.apply(token).addModifier(b -> b.setCullState(RenderStateShard.NO_CULL));
        var vertices = new Vector3f[]{new Vector3f(xEnd, yStart, 0), new Vector3f(xStart, yStart, 0), new Vector3f(xStart, yEnd, 0), new Vector3f(xEnd, yEnd, 0)};
        var builder = VFXBuilders.createWorld()
                .setRenderType(banner)
                .setLightLevel(pos);
        builder.renderQuad(poseStack, vertices, 1f);
        if (spirit != null) {
            var glow = LodestoneRenderTypes.ADDITIVE_TEXTURE.apply(token).addModifier(b -> b.setCullState(RenderStateShard.NO_CULL));
            if (!blockEntityIn.intense) {
                glow.addUniformData(UniformData.LUMITRANSPARENT);
            }
            for (int i = 1; i < 4; i++) {
                Color color = spirit.getPrimaryColor();
                float alpha = 0.9f;
                var spiritBuilder = VFXBuilders.createWorld()
                        .setRenderType(glow)
                        .setColor(color);
                poseStack.pushPose();
                poseStack.translate(0, 0, 0.001f * i);
                spiritBuilder.setAlpha(alpha).renderQuad(poseStack, vertices);
                poseStack.translate(0, 0, -0.002f * i);
                spiritBuilder.setAlpha(alpha).renderQuad(poseStack, vertices);
                poseStack.popPose();
            }
        }
        poseStack.popPose();
    }

public void tick(){
            LivingEntity target = EntityMurmurHead.this.getTarget();
            Entity body = EntityMurmurHead.this.getBody();
            if(target != null){
                double dist = Math.sqrt(EntityMurmurHead.this.distanceToSqr(target.getEyePosition()));
                double bodyDist = body != null ? body.distanceTo(target) : 0.0;
                if(bodyDist > 16 && time > 30){
                    if(body instanceof EntityMurmur){
                        EntityMurmur murmur = (EntityMurmur) body;
                        murmur.setTarget(target);
                        murmur.getNavigation().moveTo(target, 1.35D);
                    }
                }
                if(bodyDist > 64){
                    EntityMurmurHead.this.setPulledIn(true);
                }else if(biteCooldown == 0){
                    EntityMurmurHead.this.setPulledIn(false);
                    Vec3 moveTo = target.getEyePosition();
                    if(time > 30){
                        if(!EntityMurmurHead.this.isAngry()){
                            EntityMurmurHead.this.playSound(AMSoundRegistry.MURMUR_ANGER.get(), 1.5F * EntityMurmurHead.this.getSoundVolume(), EntityMurmurHead.this.getVoicePitch());
                            EntityMurmurHead.this.gameEvent(GameEvent.ENTITY_ROAR);
                        }
                        EntityMurmurHead.this.setAngry(true);
                        EntityMurmurHead.this.getNavigation().moveTo(moveTo.x, moveTo.y, moveTo.z, 1.3D);
                    }else{
                        if(time == 0){
                            emergeFrom = EntityMurmurHead.this.getNeckTop(1.0F).add(0, 0.5F, 0);
                            Vec3 face = moveTo.subtract(emergeFrom);
                        }
                        boolean clockwise = false;
                        float circleDistance = 2.5F;
                        float circlingTime = 30 * time;
                        float angle = (Maths.STARTING_ANGLE * (clockwise ? -circlingTime : circlingTime));
                        double extraX = circleDistance * Mth.sin(Mth.PI + angle);
                        double extraZ = circleDistance * Mth.cos(angle);
                        double y = Math.max(emergeFrom.y + 2, target.getEyeY());
                        Vec3 vec3 = new Vec3(emergeFrom.x + extraX, y, emergeFrom.z + extraZ);
                        EntityMurmurHead.this.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 0.7D);
                    }
                    EntityMurmurHead.this.lookAt(EntityAnchorArgument.Anchor.EYES, moveTo);
                    if(dist < 1.5F && EntityMurmurHead.this.hasLineOfSight(target)){
                        EntityMurmurHead.this.playSound(AMSoundRegistry.MURMUR_ATTACK.get(), EntityMurmurHead.this.getSoundVolume(), EntityMurmurHead.this.getVoicePitch());
                        biteCooldown = 5 + EntityMurmurHead.this.getRandom().nextInt(15);
                        target.hurt(EntityMurmurHead.this.damageSources().mobAttack(EntityMurmurHead.this), 5.0F);
                    }
                }else{
                    EntityMurmurHead.this.setPulledIn(true);
                    EntityMurmurHead.this.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                    EntityMurmurHead.this.setAngry(false);
                }
                time++;
            }
            if(biteCooldown > 0){
                biteCooldown--;
            }
        }

private static Vec3 handleDamageFromTrain(Level world, AbstractContraptionEntity contraptionEntity,
		Vec3 contraptionMotion, Entity entity, Vec3 entityMotion, PlayerType playerType) {

		if (!(contraptionEntity instanceof CarriageContraptionEntity cce))
			return entityMotion;
		if (!entity.onGround())
			return entityMotion;

		CompoundTag persistentData = entity.getPersistentData();
		if (persistentData.contains("ContraptionGrounded")) {
			persistentData.remove("ContraptionGrounded");
			return entityMotion;
		}

		if (cce.collidingEntities.containsKey(entity))
			return entityMotion;
		if (entity instanceof ItemEntity)
			return entityMotion;
		if (cce.nonDamageTicks != 0)
			return entityMotion;
		if (!AllConfigs.server().trains.trainsCauseDamage.get())
			return entityMotion;

		Vec3 diffMotion = contraptionMotion.subtract(entity.getDeltaMovement());

		if (diffMotion.length() <= 0.35f || contraptionMotion.length() <= 0.35f)
			return entityMotion;

		DamageSource source = CreateDamageSources.runOver(world, contraptionEntity);
		double damage = diffMotion.length();
		if (entity.getClassification(false) == MobCategory.MONSTER)
			damage *= 2;

		if (entity instanceof Player p && (p.isCreative() || p.isSpectator()))
			return entityMotion;

		if (playerType == PlayerType.CLIENT) {
			CatnipServices.NETWORK.sendToServer(new TrainCollisionPacket((int) (damage * 16), contraptionEntity.getId()));
			world.playSound((Player) entity, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT,
				SoundSource.NEUTRAL, 1, .75f);
		} else {
			entity.hurt(source, (int) (damage * 16));
			world.playSound(null, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.NEUTRAL, 1, .75f);
			if (!entity.isAlive())
				contraptionEntity.getControllingPlayer()
					.map(world::getPlayerByUUID)
					.ifPresent(AllAdvancements.TRAIN_ROADKILL::awardTo);
		}

		Vec3 added = entityMotion.add(contraptionMotion.multiply(1, 0, 1)
			.normalize()
			.add(0, .25, 0)
			.scale(damage * 4))
			.add(diffMotion);

		return VecHelper.clamp(added, 3);
	}

public void onUpdate(){

		super.onUpdate();

		// Synchronises the rider field
		if((this.rider == null || this.rider.get() == null)
				&& EntityUtils.getRider(this) instanceof EntityLivingBase
				&& !EntityUtils.getRider(this).isDead){
			this.rider = new WeakReference<>((EntityLivingBase)EntityUtils.getRider(this));
		}

		// Prevents dismounting
		if(EntityUtils.getRider(this) == null && this.rider != null && this.rider.get() != null
				&& !this.rider.get().isDead){
			this.rider.get().startRiding(this);
		}

		// Stops the bubble bursting instantly.
		if(this.ticksExisted < 1 && !isDarkOrb) ((EntityLivingBase)EntityUtils.getRider(this)).hurtTime = 0;

		this.move(MoverType.SELF, 0, 0.03, 0);

		if(isDarkOrb){

			if(EntityUtils.getRider(this) != null
					&& EntityUtils.getRider(this).ticksExisted % Spells.entrapment.getProperty(Entrapment.DAMAGE_INTERVAL).intValue() == 0){
				if(this.getCaster() != null){
					EntityUtils.getRider(this).attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.MAGIC),
							1 * damageMultiplier);
				}else{
					EntityUtils.getRider(this).attackEntityFrom(DamageSource.MAGIC, 1 * damageMultiplier);
				}
			}

			for(int i = 0; i < 5; i++){
				this.world.spawnParticle(EnumParticleTypes.PORTAL,
						this.posX + (this.rand.nextDouble() - 0.5D) * (double)this.width,
						this.posY + this.rand.nextDouble() * (double)this.height + 0.5d,
						this.posZ + (this.rand.nextDouble() - 0.5D) * (double)this.width,
						(this.rand.nextDouble() - 0.5D) * 2.0D, -this.rand.nextDouble(),
						(this.rand.nextDouble() - 0.5D) * 2.0D);
			}
			if(lifetime - this.ticksExisted == 75){
				this.playSound(WizardrySounds.ENTITY_ENTRAPMENT_VANISH, 1.5f, 1.0f);
			}else if(this.ticksExisted % 100 == 1 && this.ticksExisted < 150){
				this.playSound(WizardrySounds.ENTITY_ENTRAPMENT_AMBIENT, 1.5f, 1.0f);
			}
		}

		// Bubble bursts if the entity is hurt (see event handler) or killed, or if the bubble has existed for more than
		// 10 seconds.
		if(EntityUtils.getRider(this) == null && this.ticksExisted > 1){
			if(!this.isDarkOrb) this.playSound(WizardrySounds.ENTITY_BUBBLE_POP, 1.5f, 1.0f);
			this.setDead();
		}
	}

@Override
	public void onUpdate(){

		if(this.ticksExisted % 25 == 1){
			this.playSound(WizardrySounds.ENTITY_HEAL_AURA_AMBIENT, 0.1f, 1.0f);
		}

		super.onUpdate();

		if(!this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(width/2, posX, posY, posZ, this.height, world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					if(target.isEntityUndead()) {

						double velX = target.motionX;
						double velY = target.motionY;
						double velZ = target.motionZ;

						if (this.ticksExisted % 10 == 1) {
							if (this.getCaster() != null) {
								target.attackEntityFrom(
										MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.RADIANT),
										Spells.healing_aura.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier);
							} else {
								target.attackEntityFrom(DamageSource.MAGIC, Spells.healing_aura.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier);
							}

							// Removes knockback
							target.motionX = velX;
							target.motionY = velY;
							target.motionZ = velZ;
						}
					}

				}else if(target.getHealth() < target.getMaxHealth() && target.ticksExisted % 5 == 0){
					target.heal(Spells.healing_aura.getProperty(Spell.HEALTH).floatValue() * damageMultiplier);
				}
			}
		}else{
			for(int i=1; i<3; i++){
				float brightness = 0.5f + (rand.nextFloat() * 0.5f);
				double radius = rand.nextDouble() * (width/2);
				float angle = rand.nextFloat() * (float)Math.PI * 2;
				ParticleBuilder.create(Type.SPARKLE)
				.pos(this.posX + radius * MathHelper.cos(angle), this.posY, this.posZ + radius * MathHelper.sin(angle))
				.vel(0, 0.05, 0)
				.time(48 + this.rand.nextInt(12))
				.clr(1.0f, 1.0f, brightness)
				.spawn(world);
			}
		}
	}

@Override
    public void render(VoidConduitBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        float height = 0.375f;
        float width = 4.5f;

        Vector3f[] positions = new Vector3f[]{new Vector3f(-width, height, width), new Vector3f(width, height, width), new Vector3f(width, height, -width), new Vector3f(-width, height, -width)};
        WorldVFXBuilder builder = VFXBuilders.createWorld();
        poseStack.pushPose();
        poseStack.translate(0.5f, 0.01f, 0.5f);

        var vignette = LodestoneRenderTypes.TRANSPARENT_TEXTURE.apply(MalumRenderTypeTokens.VOID_VIGNETTE);
        builder.replaceBufferSource(LodestoneRenderingSystem.LATE_DEFERRED_RENDER)
                .setRenderType(vignette);

        poseStack.pushPose();
        for (int i = 0; i < 5; i++) {
            float alpha = 0.75f - i * 0.1f;
            builder.setAlpha(alpha).renderQuad(poseStack, positions);
            poseStack.translate(0, 0.15f, 0);
        }
        poseStack.popPose();

        long gameTime = blockEntityIn.getLevel().getGameTime();
        float uOffset = ((gameTime + partialTicks) % 4000) / 2000f;
        float vOffset = ((gameTime + 500f + partialTicks) % 8000) / 8000f;

        builder.replaceBufferSource(LodestoneRenderingSystem.DEFERRED_RENDER.getTarget());

        Color[] colors = new Color[] {
                MalumSpiritTypes.ELDRITCH_SPIRIT.getPrimaryColor(),
                MalumSpiritTypes.WICKED_SPIRIT.getSecondaryColor(),
                MalumSpiritTypes.AQUEOUS_SPIRIT.getPrimaryColor(),
                MalumSpiritTypes.AERIAL_SPIRIT.getSecondaryColor()
        };
        for (int i = 0; i < 8; i++) {
            float speed = 1000f + 250f * i;
            float alpha = 0.115f - i * 0.01f;

            var uniforms = UniformData.create()
                    .setUniform("Speed", speed)
                    .setUniform("Width", 1024f)
                    .setUniform("Height", 1024f)
                    .setSampler("Skybox", ParallelWorldRenderer.INSTANCE.getTarget().getColorTextureId())
                    .build();

            var distortion = MalumRenderTypes.WEEPING_SPYHOLE.apply(MalumRenderTypeTokens.VOID_NOISE).addUniformData(uniforms);
            builder.setColor(colors[i % 4]).setLightLevel(blockEntityIn.getBlockPos()).setRenderType(distortion);

            builder.setAlpha(alpha);
            builder.setUV(-uOffset, vOffset, 1 - uOffset, 1 + vOffset).renderQuad(poseStack, positions, 1f);
            builder.setUV(uOffset, -vOffset, 1 + uOffset, 1 - vOffset).renderQuad(poseStack, positions, 1f);
            uOffset = -uOffset - 0.2f;
            vOffset = -vOffset + 0.7f;
            poseStack.translate(0, 0.15f, 0);
            poseStack.mulPose(Axis.YP.rotationDegrees(90));
        }
        poseStack.popPose();
    }

public void tick() {
        super.tick();
        this.setYHeadRot(this.getYRot());
        prevMergeProgress = mergeProgress;
        prevAttackProgress = attackProgress;
        if (prevHeadCount != this.getHeadCount()) {
            refreshDimensions();
            if (this.mergeProgress < 5.0F) {
                this.mergeProgress++;
            } else {
                this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(Mth.clamp(getHeadCount() * 10, 10, 100));
                this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(Mth.clamp(getHeadCount() * 2, 2, 10));
                double d = this.getAttribute(Attributes.MAX_HEALTH).getValue();
                if(this.getHealth() < d && getHeadCount() > 0){
                    this.heal((float) Math.ceil(d - this.getHealth()));
                }
                prevHeadCount = this.getHeadCount();
            }
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            LivingEntity target = this.getTarget();
            if (attackProgress >= 3F && target != null && this.distanceTo(target) < getSlimeSize(1.0F)) {
                target.hurt(damageSources().mobAttack(this), 4F + getHeadCount() * 2);
            }
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if (level().isClientSide && isAlive()) {
            float slimeSize = getSlimeSize(1);
            for (int i = 0; i < Math.ceil(slimeSize); i++) {
                double particleX = this.getX() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                double particleY = this.getY() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                double particleZ = this.getZ() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                level().addParticle(ACParticleRegistry.FERROUSLIME.get(), particleX, particleY, particleZ, this.getId(), 0, 0);
            }
            AlexsCaves.PROXY.playWorldSound(this, (byte) 13);
        } else {
            LivingEntity living = this.getTarget();
            if (living != null && living.isAlive()) {
                if (this.getDeltaMovement().length() < 0.1) {
                    noMoveTime++;
                } else {
                    noMoveTime = 0;
                }
                if (noMoveTime > 40 && mergeCooldown <= 0) {
                    split(1200);
                }
            }
        }
        if (mergeCooldown > 0) {
            mergeCooldown--;
        }
    }

@Override
    public void tick() {
        super.tick();
        double dist = bear.distanceTo(target);
        bear.getLookControl().setLookAt(this.target.getX(), this.target.getEyeY(), this.target.getZ());
        if(dist <= 6 && bear.hasLineOfSight(target)){
            bear.getNavigation().stop();
            if(bear.getAprilFoolsFlag() == 5){
                leapTimer++;
                if(leapTimer == 7){
                    AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                }
                if(leapTimer >= 10){
                    bear.setAprilFoolsFlag(0);
                    if(bear.level().getLevelData().isHardcore()){
                        target.hurt(AMDamageTypes.causeFreddyBearDamage(bear), target.getMaxHealth() - 1);
                        target.setHealth(1);
                    }else{
                        target.hurt(AMDamageTypes.causeFreddyBearDamage(bear), target.getMaxHealth() + 1000F);
                    }
                    stop();
                    return;
                }
            }else if(bear.getAprilFoolsFlag() < 4) {
                if(powerOutTimer == 0){
                    target.addEffect(new MobEffectInstance(AMEffectRegistry.POWER_DOWN.get(), 2 * (maxMusicBoxTime + 100), 0, false, false, true));
                }
                powerOutTimer++;
                if (powerOutTimer >= 60) {
                    bear.setAprilFoolsFlag(4);
                    powerOutTimer = 0;
                }else{
                    bear.setAprilFoolsFlag(3);
                }
            }else{
                if(musicBoxTimer == 0){
                    bear.level().broadcastEntityEvent(bear, (byte) 67);
                }
                musicBoxTimer++;
                if (musicBoxTimer >= maxMusicBoxTime) {
                    if(bear.getAprilFoolsFlag() != 5){
                        bear.level().broadcastEntityEvent(bear, (byte) 68);
                        bear.setAprilFoolsFlag(5);
                        bear.gameEvent(GameEvent.ENTITY_ROAR);
                        bear.playSound(AMSoundRegistry.APRIL_FOOLS_SCREAM.get(), 3, 1);
                        musicBoxTimer = 0;
                    }
                }
            }
            if(bear.getAprilFoolsFlag() < 2){
                bear.setAprilFoolsFlag(2);
            }
        }else{
            bear.getNavigation().moveTo(target, 1.2F);
            if(bear.getAprilFoolsFlag() < 1){
                bear.setAprilFoolsFlag(1);
            }
        }
    }

@Override
	public ActionResult useOnBlock(ItemUsageContext context) {
		World world = context.getWorld();
		BlockPos pos = context.getBlockPos();
		BlockState state = world.getBlockState(pos);
		PlayerEntity player = context.getPlayer();
		boolean client = world.isClient;
		AthameStrippingRecipe entry = world.getRecipeManager().listAllOfType(BWRecipeTypes.ATHAME_STRIPPING_RECIPE_TYPE).stream().filter(recipe -> recipe.log == state.getBlock()).findFirst().orElse(null);
		if (entry != null) {
			world.playSound(player, pos, BWSoundEvents.ITEM_ATHAME_STRIP, SoundCategory.BLOCKS, 1, 1);
			if (!client) {
				world.setBlockState(pos, entry.strippedLog.getDefaultState().with(PillarBlock.AXIS, state.get(PillarBlock.AXIS)), 11);
				if (player != null) {
					context.getStack().damage(1, player, stackUser -> stackUser.sendToolBreakStatus(context.getHand()));
					if (world.random.nextFloat() < 2 / 3f) {
						ItemStack bark = entry.getOutput(world.getRegistryManager()).copy();
						if (!player.getInventory().insertStack(bark)) {
							player.dropStack(bark);
						}
					}
				}
			}
			return ActionResult.success(client);
		}
		BlockEntity blockEntity = world.getBlockEntity(state.getBlock() instanceof DoorBlock && state.get(DoorBlock.HALF) == DoubleBlockHalf.UPPER ? pos.down() : pos);
		if (blockEntity instanceof SigilHolder sigilHolder) {
			if (player != null && player.getUuid().equals(sigilHolder.getOwner())) {
				if (!client && !sigilHolder.getEntities().isEmpty()) {
					boolean whitelist = sigilHolder.getModeOnWhitelist();
					world.playSound(null, pos, BWSoundEvents.BLOCK_SIGIL_PLING, SoundCategory.BLOCKS, 1, whitelist ? 0.5f : 1);
					player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.toggle_" + (!whitelist ? "whitelist" : "blacklist")), true);
					sigilHolder.setModeOnWhitelist(!whitelist);
					blockEntity.markDirty();
				}
				return ActionResult.success(client);
			}
		} else if (blockEntity instanceof TaglockHolder taglockHolder) {
			if (player != null && player.getUuid().equals(taglockHolder.getOwner()) && taglockHolder.getFirstEmptySlot() != 0) {
				if (!client) {
					ItemScatterer.spawn(world, pos, taglockHolder.getTaglockInventory());
					taglockHolder.syncTaglockHolder(blockEntity);
					blockEntity.markDirty();
				}
				return ActionResult.success(client);
			}
		} else if (blockEntity instanceof Lockable lockable) {
			if (player != null && player.getUuid().equals(lockable.getOwner()) && !lockable.getEntities().isEmpty()) {
				if (!client) {
					boolean whitelist = lockable.getModeOnWhitelist();
					world.playSound(null, pos, BWSoundEvents.BLOCK_SIGIL_PLING, SoundCategory.BLOCKS, 1, whitelist ? 0.5f : 1);
					player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.toggle_" + (!whitelist ? "whitelist" : "blacklist")), true);
					lockable.setModeOnWhitelist(!whitelist);
					blockEntity.markDirty();
				}
				return ActionResult.success(client);
			}
		}
		return super.useOnBlock(context);
	}

@Override
    protected void onHitEntity(EntityHitResult pResult) {
        if (!this.level.isClientSide) {
            Entity entity = pResult.getEntity();
            if (this.getSpearLevel() > 0) {
                if (this.piercingIgnoreEntityIds == null) {
                    this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
                }

                if (this.piercedAndKilledEntities == null) {
                    this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
                }

                if (this.piercingIgnoreEntityIds.size() >= this.getSpearLevel() + 1) {
                    this.discard();
                    return;
                }

                this.piercingIgnoreEntityIds.add(entity.getId());
            }
            Entity entity1 = this.getOwner();
            boolean flag;
            float damage = entity1 instanceof Mob mob ? (float) MobUtil.getAttributeValue(mob, Attributes.ATTACK_DAMAGE, 2.0D) : SpellConfig.PoisonDartDamage.get().floatValue();
            damage += this.getExtraDamage();
            if (entity1 instanceof LivingEntity livingentity) {
                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }
                flag = entity.hurt(this.damageSources().arrow(this, entity1), damage);
                if (flag) {
                    if (entity.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, entity);
                    }
                }
            } else {
                flag = entity.hurt(this.damageSources().arrow(this, this), damage);
            }
            if (flag && entity.getType() != EntityType.ENDERMAN && entity instanceof LivingEntity livingEntity) {
                if (entity1 instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingEntity, entity1);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity) entity1, livingEntity);
                }

                this.doPostHurtEffects(livingEntity);

                MobEffect mobEffect = MobEffects.POISON;
                if ((entity1 instanceof IOwned owned && CuriosFinder.hasWildRobe(owned.getMasterOwner()))
                        || (entity1 instanceof LivingEntity livingEntity1 && CuriosFinder.hasWildRobe(livingEntity1))) {
                    mobEffect = GoetyEffects.ACID_VENOM.get();
                }
                livingEntity.addEffect(new MobEffectInstance(mobEffect, MathHelper.secondsToTicks(2 + this.getDuration())));

                this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                if (this.getSpearLevel() <= 0) {
                    this.discard();
                }
            }
        }
    }

@Override
	public void onUpdate() {
		this.world.profiler.startSection("entityBaseTick");

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;
		this.motionX = 0;
		this.motionZ = 0;
		this.lastTickPosX = this.posX;
		this.lastTickPosY = this.posY;
		this.lastTickPosZ = this.posZ;

		if(this.ticksExisted >= this.delay) {
			if(this.world.isRemote && this.ticksExisted == this.delay) {
				this.spawnEmergeParticles();
				this.world.playSound(this.posX, this.posY, this.posZ, SoundRegistry.SPIRIT_TREE_SPIKES, SoundCategory.HOSTILE, 0.7F, 0.9F + this.rand.nextFloat() * 0.2F, false);
			}
			if(this.ticksExisted == this.delay && this.motionY <= 0.0D) {
				this.motionY += 0.25D;
			} else {
				this.motionY -= 0.05D;

				if(!this.world.isRemote && (this.posY <= this.origin.getY() || this.onGround)) {
					this.setDead();
				}
			}
		} else {
			this.motionY = 0.0D;
		}

		if(this.posY < -64.0D) {
			this.setDead();
		}

		if(this.posY + this.motionY <= this.origin.getY()) {
			this.motionY = 0.0D;
			this.setLocationAndAngles(this.posX, this.origin.getY(), this.posZ, 0, 0);
		} else {
			this.move(MoverType.SELF, 0, this.motionY, 0);
		}

		if(this.motionY > 0.1D && !this.world.isRemote) {
			DamageSource damageSource = new EntityDamageSource("bl.spikewave", this);
			for(BlockPos pos : this.positions) {
				AxisAlignedBB aabb = new AxisAlignedBB(pos).offset(this.posX - (this.origin.getX() + 0.5D), this.posY - this.origin.getY(), this.posZ - (this.origin.getZ() + 0.5D)).shrink(0.1D).offset(0, 0.2D, 0);
				List<EntityLivingBase> entities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, aabb);
				for(EntityLivingBase entity : entities) {      
					if (entity instanceof EntityLivingBase) {    
						entity.attackEntityFrom(damageSource, this.attackDamage);
					}
				}
			}
		}

		this.renderingBounds = this.blockEnclosingBounds.offset(this.posX - (this.origin.getX() + 0.5D), this.posY - this.origin.getY(), this.posZ - (this.origin.getZ() + 0.5D));

		this.firstUpdate = false;
		this.world.profiler.endSection();
	}

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        float damage = SpellConfig.ShockingDamage.get().floatValue() * WandUtil.damageMultiply();
        if (caster instanceof SpriteMob spriteMob) {
            if (spriteMob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                damage = (float) spriteMob.getAttributeValue(Attributes.ATTACK_DAMAGE);
            }
        }
        int range = spellStat.getRange();
        int burning = spellStat.getBurning();
        if (WandUtil.enchantedFocus(caster)) {
            range += WandUtil.getRangeLevel(caster);
            damage += WandUtil.getPotencyLevel(caster);
            burning += WandUtil.getLevels(ModEnchantments.BURNING.get(), caster);
        }
        ColorUtil colorUtil = new ColorUtil(0xb1abf1);
        if (staff.is(ModItems.NAMELESS_STAFF.get())) {
            colorUtil = new ColorUtil(0xa7fc3e);
        }
        damage += spellStat.getPotency();
        Vec3 vec3 = caster.getEyePosition();
        BlockHitResult rayTraceResult = this.blockResult(worldIn, caster, range);
        Entity target = MobUtil.getNearbyTarget(worldIn, caster, range, 1.0F);
        Optional<BlockPos> lightningRod = BlockFinder.findLightningRod(worldIn, BlockPos.containing(rayTraceResult.getLocation()), range);
        if (lightningRod.isPresent() && !this.rightStaff(staff)){
            BlockPos blockPos = lightningRod.get();
            ModNetwork.sendToALL(new SLightningPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 5));
            worldIn.playSound(null, caster.getX(), caster.getY(), caster.getZ(), ModSounds.ZAP.get(), this.getSoundSource(), 1.0F, 1.0F);
        } else {
            LivingEntity livingEntity = MobUtil.getLivingTarget(target);
            if (livingEntity != null && ForgeHooks.onLivingAttack(livingEntity, ModDamageSource.directShock(caster), damage)) {
                Vec3 vec31 = new Vec3(livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() / 2, livingEntity.getZ());
                ModNetwork.sendToALL(new SLightningPacket(vec3, vec31, colorUtil, 5));
                if (livingEntity.hurt(ModDamageSource.directShock(caster), damage)){
                    float chance = rightStaff(staff) ? 0.25F : 0.05F;
                    float chainDamage = damage / 2.0F;
                    if (worldIn.isThundering() && worldIn.isRainingAt(livingEntity.blockPosition())){
                        chance += 0.25F;
                        chainDamage = damage;
                    }
                    if (worldIn.random.nextFloat() <= chance){
                        livingEntity.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                    }
                    if (burning > 0){
                        if (worldIn.random.nextFloat() < 0.05F){
                            livingEntity.setSecondsOnFire(5 * burning);
                        }
                    }
                    if (this.rightStaff(staff)){
                        WandUtil.chainLightning(livingEntity, caster, range / 4.0D, chainDamage, true);
                    }
                }
                this.playSound(worldIn, caster, ModSounds.ZAP.get());
            } else {
                BlockPos blockPos = rayTraceResult.getBlockPos();
                ModNetwork.sendToALL(new SLightningPacket(vec3, new Vec3(blockPos.getX(), blockPos.getY(), blockPos.getZ()), colorUtil, 5));
                this.playSound(worldIn, caster, ModSounds.ZAP.get());
            }
        }
    }

@Override
    protected void onHitEntity(EntityHitResult result) {
        Entity entity = result.getEntity();
        float f = (float) this.getDeltaMovement().length();
        double d0 = this.getBaseDamage();
        Entity owner = this.getOwner();
        DamageSource damageSource = this.damageSources().arrow(this, owner != null ? owner : this);
        if (this.getWeaponItem() != null && this.level() instanceof ServerLevel serverlevel) {
            d0 = EnchantmentHelper.modifyDamage(serverlevel, this.getWeaponItem(), entity, damageSource, (float)d0);
        }
        int i = Mth.ceil(Mth.clamp((double) f * d0, 0.0, Integer.MAX_VALUE));

        if (this.isCritArrow()) {
            long j = this.random.nextInt(i / 2 + 2);
            i = (int) Math.min(j + (long) i, 2147483647L);
        }

        if (owner instanceof LivingEntity livingEntity) {
            livingEntity.setLastHurtMob(entity);
        }

        boolean flag = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !flag) {
            entity.igniteForSeconds(5);
        }

        if (entity.hurt(damageSource, (float) i)) {
            if (flag) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {
                this.doKnockback(livingentity, damageSource);

                if (!this.level().isClientSide() && owner instanceof LivingEntity && this.level() instanceof ServerLevel serverlevel) {
                    EnchantmentHelper.doPostAttackEffectsWithItemSource(serverlevel, livingentity, damageSource, this.getWeaponItem());
                }

                this.doPostHurtEffects(livingentity);
                if (livingentity != owner && livingentity instanceof Player && owner instanceof ServerPlayer serverPlayer && !this.isSilent()) {
                    serverPlayer.connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }
            }

            this.playSound(this.getDefaultHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            this.discard();
        } else {
            entity.setRemainingFireTicks(k);
            this.deflect(ProjectileDeflection.REVERSE, entity, this.getOwner(), false);
            this.setDeltaMovement(this.getDeltaMovement().scale(0.2));
            if (!this.level().isClientSide() && this.getDeltaMovement().lengthSqr() < 1.0E-7) {
                if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                    this.spawnAtLocation(this.getPickupItem(), 0.1F);
                }
                this.discard();
            }
        }
        this.setNoGravity(false); // Restores gravity to the dart when it hits an entity.
    }

public void tick() {
        super.tick();
        this.prevSitProgress = this.sitProgress;
        if (this.isSitting()) {
            if (sitProgress < 10F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
            this.setOrderedToSit(false);
            sittingTime = 0;
            maxSitTime = 75 + random.nextInt(50);
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isSitting() && this.getCommand() != 1 && random.nextInt(1500) == 0) {
            maxSitTime = 300 + random.nextInt(250);
            this.setOrderedToSit(true);
        }
        this.setMaxUpStep(2);
        if (!forcedSit && this.isSitting() && (this.getDartTarget() != null || this.getCommand() == 1)) {
            this.setOrderedToSit(false);
        }

        if (!this.level().isClientSide) {
            if (this.getTarget() != null && this.getAnimation() == ANIMATION_SCRATCH && this.getAnimationTick() == 10) {
                float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.3F, 0.0D, Mth.cos(f1) * 0.3F));
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                this.setAttackDecision(this.getTarget());
            }
            if (this.getDartTarget() != null && this.getDartTarget().isAlive() && this.getAnimation() == ANIMATION_THROW && this.getAnimationTick() == 5) {
                final Vec3 vector3d = this.getDartTarget().getDeltaMovement();
                final double d0 = this.getDartTarget().getX() + vector3d.x - this.getX();
                final double d1 = this.getDartTarget().getEyeY() - (double) 1.1F - this.getY();
                final double d2 = this.getDartTarget().getZ() + vector3d.z - this.getZ();
                final float f = Mth.sqrt((float)(d0 * d0 + d2 * d2));
                EntityTossedItem tossedItem = new EntityTossedItem(this.level(), this);
                tossedItem.setDart(this.hasDart());
                tossedItem.setXRot(tossedItem.getXRot() - 20F);
                tossedItem.shoot(d0, d1 + (double) (f * 0.2F), d2, hasDart() ? 1.15F : 0.75F, 8.0F);
                if (!this.isSilent()) {
                    this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.WITCH_THROW, this.getSoundSource(), 1.0F, 0.8F + this.random.nextFloat() * 0.4F);
                    this.gameEvent(GameEvent.PROJECTILE_SHOOT);
                }
                this.level().addFreshEntity(tossedItem);
                this.setAttackDecision(this.getDartTarget());
            }
        }
        if (rideCooldown > 0) {
            rideCooldown--;
        }
        if (!this.level().isClientSide && getAnimation() == NO_ANIMATION && this.getRandom().nextInt(300) == 0) {
            setAnimation(ANIMATION_HEADTILT);
        }
        if (!this.level().isClientSide && this.isSitting()) {
            this.getNavigation().stop();
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
            super.tick();
            LivingEntity target = EntityFarseer.this.getTarget();
            if (laserCooldown > 0) {
                laserCooldown--;
            }
            timeSinceLastSuccessfulAttack++;
            if (timeSinceLastSuccessfulAttack > 100) {
                timeSinceLastSuccessfulAttack = 0;
                attackDecision = !attackDecision;
            }
            if (target != null) {
                double dist = EntityFarseer.this.distanceTo(target);
                boolean canLaserHit = willLaserHit(target);
                if (this.laserCooldown == 0 && attackDecision && canLaserHit && dist > 2F) {
                    EntityFarseer.this.setAngry(true);
                    EntityFarseer.this.entityData.set(LASER_ENTITY_ID, target.getId());
                    if(laserUseTime == 0){
                        EntityFarseer.this.playSound(AMSoundRegistry.FARSEER_BEAM.get(), EntityFarseer.this.getSoundVolume(), EntityFarseer.this.getVoicePitch());
                    }
                    laserUseTime++;
                    if (laserUseTime > LASER_ATTACK_DURATION) {
                        laserUseTime = 0;
                        if (canLaserHit) {
                            float healthTenth = target.getMaxHealth() * 0.1F;
                            if(target.hurt(AMDamageTypes.causeFarseerDamage(EntityFarseer.this), random.nextInt(2) + Math.max(6, healthTenth)) && !target.isAlive()){
                                AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                            }
                            timeSinceLastSuccessfulAttack = 0;
                        }
                        if (lasersShot++ > 5) {
                            lasersShot = 0;
                            laserCooldown = 80 + random.nextInt(40);
                            EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                            attackDecision = EntityFarseer.this.getRandom().nextBoolean();
                        }
                    }
                    EntityFarseer.this.entityData.set(LASER_ATTACK_LVL, laserUseTime);
                    EntityFarseer.this.lookAt(target, 180F, 180F);
                    if (dist < 17F && canLaserHit) {
                        EntityFarseer.this.getNavigation().stop();
                    } else {
                        EntityFarseer.this.getNavigation().moveTo(target, 1F);
                    }
                    EntityFarseer.this.entityData.set(MELEEING, false);
                } else {
                    if (!canLaserHit && dist > 10) {
                        EntityFarseer.this.setAngry(false);
                    }
                    if (EntityFarseer.this.hasLaser()) {
                        EntityFarseer.this.entityData.set(LASER_ENTITY_ID, -1);
                    }
                    EntityFarseer.this.entityData.set(MELEEING, dist < 4F);
                    if (dist < 4F) {
                        timeSinceLastSuccessfulAttack = 0;
                    } else {
                        EntityFarseer.this.getNavigation().moveTo(target, 1F);
                        EntityFarseer.this.moveControl.setWantedPosition(target.getX(), target.getEyeY(), target.getZ(), 1F);
                    }
                }
            }
        }

@Override
	public void tick() {
		double lastTickPosX = this.xOld;
		double lastTickPosY = this.yOld;
		double lastTickPosZ = this.zOld;

		super.tick();

		if (!level().isClientSide && (!findTarget() || time > 40)) {
			discard();
			return;
		}

		boolean evil = isEvil();
		Vec3 thisVec = VecHelper.fromEntityCenter(this);
		Vec3 oldPos = new Vec3(lastTickPosX, lastTickPosY, lastTickPosZ);
		Vec3 diff = thisVec.subtract(oldPos);
		Vec3 step = diff.normalize().scale(0.05);
		int steps = (int) (diff.length() / step.length());
		Vec3 particlePos = oldPos;

		SparkleParticleData data = evil ? SparkleParticleData.corrupt(0.8F, 1F, 0.0F, 1F, 2)
				: SparkleParticleData.sparkle(0.8F, 1F, 0.4F, 1F, 2);
		for (int i = 0; i < steps; i++) {
			level().addParticle(data, particlePos.x, particlePos.y, particlePos.z, 0, 0, 0);

			if (level().random.nextInt(steps) <= 1) {
				level().addParticle(data, particlePos.x + (Math.random() - 0.5) * 0.4, particlePos.y + (Math.random() - 0.5) * 0.4, particlePos.z + (Math.random() - 0.5) * 0.4, 0, 0, 0);
			}

			particlePos = particlePos.add(step);
		}

		LivingEntity target = getTargetEntity();
		if (target != null) {
			if (lockY == Integer.MIN_VALUE) {
				lockX = target.getX();
				lockY = target.getY();
				lockZ = target.getZ();
			}

			Vec3 targetVec = evil ? new Vec3(lockX, lockY, lockZ) : VecHelper.fromEntityCenter(target);
			Vec3 diffVec = targetVec.subtract(thisVec);
			Vec3 motionVec = diffVec.normalize().scale(evil ? 0.5 : 0.6);
			setDeltaMovement(motionVec);
			if (time < 10) {
				setDeltaMovement(getDeltaMovement().x(), Math.abs(getDeltaMovement().y()), getDeltaMovement().z());
			}

			List<LivingEntity> targetList = level().getEntitiesOfClass(LivingEntity.class, new AABB(getX() - 0.5, getY() - 0.5, getZ() - 0.5, getX() + 0.5, getY() + 0.5, getZ() + 0.5));
			if (targetList.contains(target)) {
				target.hurt(this.getDamageSource(), evil ? 12 : 7);
				discard();
			}

			if (evil && diffVec.length() < 1) {
				discard();
			}
		}

		time++;
	}

public void tick(){
        super.tick();
        prevCurlProgress = curlProgress;

        if (this.isCurled()) {
            if (curlProgress < 5F)
                curlProgress += 0.5F;
        } else {
            if (curlProgress > 0F)
                curlProgress--;
        }

        if (randomToungeTick == 0 && random.nextInt(15) == 0) {
            randomToungeTick = 10 + random.nextInt(20);
        }
        if (randomToungeTick > 0) {
            randomToungeTick--;
        }
        if (isCurled() && !isRattling() && ++curlTime > maxCurlTime) {
            this.setCurled(false);
            curlTime = 0;
            maxCurlTime = 75 + random.nextInt(50);
        }

        LivingEntity target = this.getTarget();
        if (!this.level().isClientSide) {
            if (this.isCurled() && (target != null && target.isAlive())) {
                this.setCurled(false);
            }
            if (this.isRattling() && target == null) {
                this.setCurled(true);

            }
            if (!this.isCurled() && this.getTarget() == null && random.nextInt(500) == 0) {
                maxCurlTime = 300 + random.nextInt(250);
                this.setCurled(true);
            }
        }
        if (this.getAnimation() == ANIMATION_BITE) {
            if (this.getAnimationTick() == 4) {
                this.playSound(AMSoundRegistry.RATTLESNAKE_ATTACK.get(), getSoundVolume(), getVoicePitch());
            }
            if (this.getAnimationTick() == 8 && target != null && this.distanceTo(target) < 2D) {
                final boolean meepMeep = target instanceof EntityRoadrunner;
                final int f = isBaby() ? 2 : 1;
                target.hurt(this.damageSources().mobAttack(this), meepMeep ? 1.0F : f * (float) getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                if (!meepMeep) {
                    target.addEffect(new MobEffectInstance(MobEffects.POISON, 300, f * 2));
                }
            }
        }
        if(isRattling()){
            if(loopSoundTick == 0){
                this.gameEvent(GameEvent.ENTITY_ROAR);
                this.playSound(AMSoundRegistry.RATTLESNAKE_LOOP.get(), this.getSoundVolume() * 0.5F, this.getVoicePitch());
            }
            loopSoundTick++;
            if(loopSoundTick > 50){
                loopSoundTick = 0;
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void releaseUsing(@NotNull ItemStack stack, Level worldIn, LivingEntity entity, int timeLeft) {
        double dist = 32;
        Vec3 Vector3d = entity.getEyePosition(1.0F);
        Vec3 Vector3d1 = entity.getViewVector(1.0F);
        Vec3 Vector3d2 = Vector3d.add(Vector3d1.x * dist, Vector3d1.y * dist, Vector3d1.z * dist);
        double d1 = dist;
        Entity pointedEntity = null;
        List<Entity> list = worldIn.getEntities(entity, entity.getBoundingBox().expandTowards(Vector3d1.x * dist, Vector3d1.y * dist, Vector3d1.z * dist).inflate(1.0D, 1.0D, 1.0D), new Predicate<Entity>() {
            @Override
            public boolean apply(@Nullable Entity entity) {
                boolean blindness = entity instanceof LivingEntity && ((LivingEntity) entity).hasEffect(MobEffects.BLINDNESS) || (entity instanceof IBlacklistedFromStatues && !((IBlacklistedFromStatues) entity).canBeTurnedToStone());
                return entity != null && entity.isPickable() && !blindness && (entity instanceof Player || (entity instanceof LivingEntity && DragonUtils.isAlive((LivingEntity) entity)));
            }
        });
        double d2 = d1;
        for (int j = 0; j < list.size(); ++j) {
            Entity entity1 = list.get(j);
            AABB axisalignedbb = entity1.getBoundingBox().inflate(entity1.getPickRadius());
            Optional<Vec3> optional = axisalignedbb.clip(Vector3d, Vector3d2);

            if (axisalignedbb.contains(Vector3d)) {
                if (d2 >= 0.0D) {
                    //pointedEntity = entity1;
                    d2 = 0.0D;
                }
            } else if (optional.isPresent()) {
                double d3 = Vector3d.distanceTo(optional.get());

                if (d3 < d2 || d2 == 0.0D) {
                    if (entity1.getRootVehicle() == entity.getRootVehicle() && !entity.canRiderInteract()) {
                        if (d2 == 0.0D) {
                            pointedEntity = entity1;
                        }
                    } else {
                        pointedEntity = entity1;
                        d2 = d3;
                    }
                }
            }
        }
        if (pointedEntity != null) {
            if (pointedEntity instanceof LivingEntity) {
                pointedEntity.playSound(IafSoundRegistry.TURN_STONE, 1, 1);
                EntityStoneStatue statue = EntityStoneStatue.buildStatueEntity((LivingEntity) pointedEntity);
                if (pointedEntity instanceof Player) {
                    pointedEntity.hurt(IafDamageRegistry.causeGorgonDamage(pointedEntity), Integer.MAX_VALUE);
                } else {
                    if (!worldIn.isClientSide)
                        pointedEntity.remove(Entity.RemovalReason.KILLED);
                }
                statue.absMoveTo(pointedEntity.getX(), pointedEntity.getY(), pointedEntity.getZ(), pointedEntity.getYRot(), pointedEntity.getXRot());
                statue.yBodyRot = pointedEntity.getYRot();
                if (!worldIn.isClientSide) {
                    worldIn.addFreshEntity(statue);
                }
                if (entity instanceof Player && !((Player) entity).isCreative()) {
                    stack.shrink(1);
                }
            }
        }
        stack.getTag().putBoolean("Active", false);
    }

@Override
	public void onUpdate() {
		if (!world.isRemote) {
			if (fleeingTick == 0 && getAttackTarget() != null && getDistance(getAttackTarget()) < 2) {
				onCollideWithEntity(getAttackTarget());
			}
			if (getRidingEntity() != null) {
				setRotation(getRidingEntity().rotationYaw, getRidingEntity().rotationPitch);
				if (getRidingEntity().isBurning() && getRidingEntity() instanceof EntityLivingBase) {
					PotionEffect stomachContents = new PotionEffect(MobEffects.POISON, 120 + getBloodConsumed() * 200 / MAX_BLOOD_LEVEL, 0);
					((EntityLivingBase) getRidingEntity()).addPotionEffect(stomachContents);
					setBloodConsumed(0);
					Entity mount = this.getRidingEntity();
					dismountEntity(mount);
					flee();
					dismountRidingEntity();
					this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(mount));
				}
			}
			if (getBloodConsumed() == MAX_BLOOD_LEVEL && getRidingEntity() != null) {
				Entity mount = this.getRidingEntity();
				dismountEntity(getRidingEntity());
				dismountRidingEntity();
				this.getServer().getPlayerList().sendPacketToAllPlayers(new SPacketSetPassengers(mount));
			}
			if (fleeingTick > 0) {
				fleeingTick--;
				if (fleeingTick == 0) {
					stopFleeing();
				}
			}
		}

		if (!firstTickCheck) {
			dismountRidingEntity();
			firstTickCheck = true;
		}
		if (--hungerCoolDown == 0) {
			if (getBloodConsumed() > 0) {
				setBloodConsumed(getBloodConsumed() - 1);
			}
		}
		if (getRidingEntity() != null) {
			moveProgress = 1 + mathSucking.swing(1, 0.15F, false);
			if (rand.nextInt(10) == 0) {
				for (int i = 0; i < 8; i++) {
					world.spawnParticle(EnumParticleTypes.REDSTONE, posX + (rand.nextFloat() - rand.nextFloat()), posY + rand.nextFloat(), posZ + (rand.nextFloat() - rand.nextFloat()), 0, 0, 0);
				}
			}
		} else if (!world.isRemote) {
			moveProgress = 0F + mathSucking.swing(1, 0.15F, false);
		}

		if (getRidingEntity() != null && getRidingEntity() instanceof EntityLivingBase && getBloodConsumed() < MAX_BLOOD_LEVEL) {
			drainage++;
			if (drainage >= attackCountDown && this.deathTime == 0) {
				getRidingEntity().attackEntityFrom(DamageSource.causeMobDamage(this), (int)getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
				drainage = 0;
				setBloodConsumed(getBloodConsumed() + 1);
			}
		}
		super.onUpdate();
	}

protected void onHit(RayTraceResult raytraceResultIn) {
		Entity entity = raytraceResultIn.entityHit;

		if (entity != null) {
			float f = MathHelper.sqrt(motionX * motionX + motionY * motionY + motionZ * motionZ);
			int i = MathHelper.ceil((double) f * damage);

			if (getIsCritical())
				i += rand.nextInt(i / 2 + 2);

			DamageSource damagesource;

			if (shootingEntity == null)
				damagesource = DamageSource.causeThrownDamage(this, this);
			else
				damagesource = DamageSource.causeThrownDamage(this, shootingEntity);

			if (isBurning() && !(entity instanceof EntityEnderman))
				entity.setFire(5);

			if (entity.attackEntityFrom(damagesource, (float) i)) {
				if (entity instanceof EntityLivingBase) {
					EntityLivingBase entitylivingbase = (EntityLivingBase) entity;

					if (knockbackStrength > 0) {
						float f1 = MathHelper.sqrt(motionX * motionX + motionZ * motionZ);

						if (f1 > 0.0F) {
							entitylivingbase.addVelocity(motionX * (double) knockbackStrength * 0.6000000238418579D / (double) f1, 0.1D, motionZ * (double) knockbackStrength * 0.6000000238418579D / (double) f1);
						}
					}

					if (shootingEntity instanceof EntityLivingBase) {
						EnchantmentHelper.applyThornEnchantments(entitylivingbase, shootingEntity);
						EnchantmentHelper.applyArthropodEnchantments((EntityLivingBase) shootingEntity, entitylivingbase);
						if (shootingEntity instanceof EntityChiromawGreeblingRider) {
							getEntityWorld().playSound(null, shootingEntity.getPosition(), SoundRegistry.GREEBLING_GIGGLE, SoundCategory.HOSTILE, 1F, 1F);
						}
					}

					if (shootingEntity != null && entitylivingbase != shootingEntity && entitylivingbase instanceof EntityPlayer && shootingEntity instanceof EntityPlayerMP) {
						((EntityPlayerMP) shootingEntity).connection .sendPacket(new SPacketChangeGameState(6, 0.0F));
					}
				}


				if (!(entity instanceof EntityEnderman))
					setDead();

			} else {
				motionX *= -0.10000000149011612D;
				motionY *= -0.10000000149011612D;
				motionZ *= -0.10000000149011612D;
				this.ticksInAir = 0;

				if (!world.isRemote && motionX * motionX + motionY * motionY + motionZ * motionZ < 0.0010000000474974513D)
					setDead();
			}
		} else
			setDead();

		getEntityWorld().playSound(null, getPosition(), SoundRegistry.SLINGSHOT_HIT, SoundCategory.HOSTILE, 1F, 1F + (getEntityWorld().rand.nextFloat() - getEntityWorld().rand.nextFloat()) * 0.8F);
	}

@Override
    protected void onHitBlock(BlockHitResult traceResult) {
        byte basePenetration = entityData.get(PENETRATION);
        int remainingPenetration = basePenetration - blockPenetration;
        if (piercingIgnoreEntityIds != null) {
            remainingPenetration -= piercingIgnoreEntityIds.size();
        }
        double canPenetrate = remainingPenetration * 0.25;
        byte techLevel = entityData.get(TECH_LEVEL);
        if (canPenetrate > 0 && basePenetration >= techLevel * 1.5) {
            blockPenetration += remainingPenetration;
            BlockPos pos = traceResult.getBlockPos();
            BlockState blockstate = level().getBlockState(pos);
            if (!blockstate.isAir()) {
                VoxelShape voxelshape = blockstate.getCollisionShape(level(), pos);
                if (!voxelshape.isEmpty()) {
                    boolean canPass = true;
                    Vec3 vector3d1 = traceResult.getLocation().add(getDeltaMovement().normalize().multiply(canPenetrate, canPenetrate, canPenetrate));

                    for (AABB axisalignedbb : voxelshape.toAabbs()) {
                        if (axisalignedbb.move(pos).contains(vector3d1)) {
                            canPass = false;
                            break;
                        }
                    }
                    if (canPass) {
                        this.playSound(SoundEvents.ANCIENT_DEBRIS_BREAK, 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                        for (int i = 0; i < 25; i++) {
                            Vec3 critPos = traceResult.getLocation().add(getDeltaMovement().normalize().multiply(2, 2, 2).add((-0.5 + random.nextGaussian()) * 0.2, (-0.5 + random.nextGaussian()) * 0.2, (-0.5 + random.nextGaussian()) * 0.2));
                            Vec3 critVel = getDeltaMovement().normalize().multiply(5, 5, 5);
                            level().addParticle(ParticleTypes.CRIT, critPos.x, critPos.y, critPos.z, critVel.x, critVel.y, critVel.z);
                        }

                        //Fire Shrapnel
                        Vec3 shrapnelTravelEnd = traceResult.getLocation().add(getDeltaMovement().normalize().multiply(remainingPenetration, remainingPenetration, remainingPenetration));
                        EntityHitResult result = findHitEntity(traceResult.getLocation(), shrapnelTravelEnd);
                        if (result != null) {
                            Entity entity = result.getEntity();
                            DamageSource damagesource = getDamageSource(entity);
                            float velocity = (float) this.getDeltaMovement().length();
                            int damage = Mth.ceil(Mth.clamp((double) velocity * this.getBaseDamage(), 0.0D, 2.147483647E9D));
                            entity.hurt(damagesource, (float) damage * 0.75F);
                        }
                    }
                }
            }
        }

        this.lastState = level().getBlockState(traceResult.getBlockPos());
        BlockState blockstate = level().getBlockState(traceResult.getBlockPos());
        blockstate.onProjectileHit(level(), blockstate, traceResult, this);
        Vec3 vector3d = traceResult.getLocation().subtract(this.getX(), this.getY(), this.getZ());
        this.setDeltaMovement(vector3d);
        Vec3 vector3d1 = vector3d.normalize().scale((double) 0.05F);
        this.setPosRaw(this.getX() - vector3d1.x, this.getY() - vector3d1.y, this.getZ() - vector3d1.z);
        this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
        this.inGround = true;
        this.shakeTime = 7;
        this.setCritArrow(false);
        this.setPierceLevel((byte) 0);
        this.setSoundEvent(SoundEvents.ARROW_HIT);
        this.resetPiercedEntities();
    }

public void onUse(World world, BlockPos pos, LivingEntity user, Hand hand, LivingEntity sacrifice) {
		ItemStack stack = user.getStackInHand(hand);
		if (ritualFunction != null && pos.equals(effectivePos) && stack.getItem() instanceof WaystoneItem && stack.hasNbt() && stack.getOrCreateNbt().contains("LocationPos") && world.getRegistryKey().getValue().toString().equals(stack.getOrCreateNbt().getString("LocationWorld"))) {
			effectivePos = BlockPos.fromLong(stack.getOrCreateNbt().getLong("LocationPos"));
			stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(hand));
			syncGlyph();
		} else {
			if (ritualFunction == null) {
				SimpleInventory test = new SimpleInventory(size());
				List<ItemEntity> items = world.getEntitiesByType(EntityType.ITEM, new Box(pos).expand(2, 0, 2), entity -> true);
				for (ItemEntity entity : items) {
					test.addStack(entity.getStack().copy().split(1));
				}
				RitualRecipe recipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.RITUAL_RECIPE_TYPE).stream().filter(ritualRecipe -> ritualRecipe.matches(test, world)).findFirst().orElse(null);
				if (recipe != null && recipe.input.size() == items.size() && hasValidChalk(recipe)) {
					if (recipe.ritualFunction.isValid((ServerWorld) world, pos, test) || (recipe.ritualFunction.sacrifice != null && sacrifice != null && recipe.ritualFunction.sacrifice.test(sacrifice))) {
						boolean cat = user instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == EntityType.CAT;
						if (altarPos != null && ((WitchAltarBlockEntity) world.getBlockEntity(altarPos)).drain((int) (recipe.cost * (cat ? 0.75f : 1)), false)) {
							world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FIRE, SoundCategory.BLOCKS, 1, 1);
							if (user instanceof PlayerEntity player) {
								player.sendMessage(Text.translatable("ritual." + recipe.getId().toString().replace(":", ".").replace("/", ".")), true);
							}
							for (int i = 0; i < items.size(); i++) {
								ItemEntity item = items.get(i);
								PlayerLookup.tracking(item).forEach(foundPlayer -> SpawnSmokeParticlesPacket.send(foundPlayer, item));
								setStack(i, item.getStack().split(1));
							}
							effectivePos = pos;
							ritualFunction = recipe.ritualFunction;
							timer = -100;
							endTime = recipe.runningTime;
							catFamiliar = cat;
							syncGlyph();
							return;
						}
						world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
						if (user instanceof PlayerEntity player) {
							player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.insufficent_altar_power"), true);
						}
						return;
					}
					world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
					if (user instanceof PlayerEntity player) {
						player.sendMessage(Text.translatable(recipe.ritualFunction.getInvalidMessage()), true);
					}
					return;
				}
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				if (user instanceof PlayerEntity player) {
					player.sendMessage(Text.translatable("ritual.none"), true);
				}
			} else if (sacrifice == null) {
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				ItemScatterer.spawn(world, pos, this);
				effectivePos = null;
				ritualFunction = null;
				timer = 0;
				endTime = 0;
				catFamiliar = false;
				syncGlyph();
			}
		}
	}

@Override
  public InteractionResult afterBlockUse(IToolStackView tool, ModifierEntry modifier, UseOnContext context, InteractionSource source) {
    if (!tool.isBroken() && tool.getHook(ToolHooks.INTERACTION).canInteract(tool, modifier.getId(), source)) {
      FluidStack fluid = TANK_HELPER.getFluid(tool);
      if (!fluid.isEmpty()) {
        FluidEffects recipe = FluidEffectManager.INSTANCE.find(fluid.getFluid());
        if (recipe.hasBlockEffects()) {
          Player player = context.getPlayer();
          Level world = context.getLevel();

          // cooldown based on draw speed, works similarly enough to attack speed
          // applied before we do the effect to block recursive calls, notably ender might cause that
          if (player != null) {
            player.getCooldowns().addCooldown(tool.getItem(), (int)(20 / ConditionalStatModifierHook.getModifiedStat(tool, player, ToolStats.DRAW_SPEED)));
          }

          if (!world.isClientSide) {
            float level = strength.compute(modifier);
            int numTargets = 0;
            BlockHitResult hit = context.getHitResult();
            BlockState state = world.getBlockState(hit.getBlockPos());
            int consumed = recipe.applyToBlock(fluid, level, FluidEffectContext.builder(world).user(player).block(hit), FluidAction.EXECUTE);
            if (consumed > 0) {
              numTargets++;
              spawnParticles(world, hit, fluid);
              fluid.shrink(consumed);
            }

            // AOE selection logic, get boosted from expanded
            if (!fluid.isEmpty()) {
              for (BlockPos offset : tool.getHook(ToolHooks.AOE_ITERATOR).getBlocks(tool, context, state, AOEMatchType.TRANSFORM)) {
                BlockHitResult offsetHit = Util.offset(hit, offset);
                consumed = recipe.applyToBlock(fluid, level, FluidEffectContext.builder(world).user(player).block(offsetHit), FluidAction.EXECUTE);
                if (consumed > 0) {
                  numTargets++;
                  spawnParticles(world, offsetHit, fluid);
                  fluid.shrink(consumed);
                  // stop if we run out of fluid
                  if (fluid.isEmpty()) {
                    break;
                  }
                }
              }
            }

            // update fluid in tool and damage tool
            if (ModifierUtil.consumesResources(player)) {
              if (numTargets > 0) {
                TANK_HELPER.setFluid(tool, fluid);
              }

              // damage the tool, we charge for the multiplier and for the number of targets hit
              ItemStack stack = context.getItemInHand();
              if (ToolDamageUtil.damage(tool, Mth.ceil(numTargets * level), player, stack, modifier.getId()) && player != null) {
                player.broadcastBreakEvent(source.getSlot(context.getHand()));
              }
            }
          }
          return InteractionResult.SUCCESS;
        }
      }
    }
    return InteractionResult.PASS;
  }

public void tick() {
        super.tick();
        prevactivateProgress = activateProgress;

        if (isActivate() && this.activateProgress > 0F) {
            this.activateProgress--;
        }

        if (this.level().isClientSide) {
            if (this.clientSideAttackStarted) {
                --this.lifeTicks;
                if (!isActivate() && this.activateProgress < 10F) {
                    this.activateProgress++;
                }
                if (this.lifeTicks == 33) {
                    for(int i = 0; i < 80; ++i) {
                        BlockState block = level().getBlockState(blockPosition().below());
                        double d0 = this.getX() + (this.random.nextDouble() * 2.0D - 1.0D) * (double) this.getBbWidth() * 0.5D;
                        double d1 = this.getY() + 0.03D;
                        double d2 = this.getZ() + (this.random.nextDouble() * 2.0D - 1.0D) * (double) this.getBbWidth() * 0.5D;
                        double d3 = (this.random.nextGaussian() * 0.07D);
                        double d4 = (this.random.nextGaussian() * 0.07D);
                        double d5 = (this.random.nextGaussian() * 0.07D);
                        this.level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, block), d0, d1, d2, d3, d4, d5);
                    }
                }

                if (this.lifeTicks == 14) {
                    this.setActivate(true);
                    for(int i = 0; i < 12; ++i) {
                        double d0 = this.getX() + (this.random.nextDouble() * 2.0D - 1.0D) * (double)this.getBbWidth() * 0.5D;
                        double d1 = this.getY() + 0.05D + this.random.nextDouble();
                        double d2 = this.getZ() + (this.random.nextDouble() * 2.0D - 1.0D) * (double)this.getBbWidth() * 0.5D;
                        double d3 = (this.random.nextDouble() * 2.0D - 1.0D) * 0.3D;
                        double d4 = 0.3D + this.random.nextDouble() * 0.3D;
                        double d5 = (this.random.nextDouble() * 2.0D - 1.0D) * 0.3D;
                        this.level().addParticle(ParticleTypes.REVERSE_PORTAL, d0, d1, d2, d3, d4, d5);
                    }
                }
            }
        } else if (--this.warmupDelayTicks < 0) {
            if (this.warmupDelayTicks == -10) {
                if(isActivate()) {
                    this.setActivate(false);
                }
            }
            if (this.warmupDelayTicks < -10 && this.warmupDelayTicks > -30) {
                for(LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.2D, 0.0D, 0.2D))) {
                    this.damage(livingentity);
                }
            }


            if (!this.sentSpikeEvent) {
                this.level().broadcastEntityEvent(this, (byte)4);
                this.sentSpikeEvent = true;
            }

            if (--this.lifeTicks < 0) {
                this.discard();
            }
        }

    }

@Override
    public void render(ArcanaPylonBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        var level = Minecraft.getInstance().level;
        var itemRenderer = Minecraft.getInstance().getItemRenderer();
        var stack = blockEntityIn.inventory.getStackInSlot(0);
        if (!stack.isEmpty()) {
            poseStack.pushPose();
            Vec3 offset = blockEntityIn.getCentralItemOffset();
            poseStack.translate(offset.x, offset.y, offset.z);
            poseStack.mulPose(Axis.YP.rotationDegrees(((level.getGameTime() % 360) + partialTicks) * 3));
            poseStack.scale(0.45f, 0.45f, 0.45f);
            itemRenderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
            poseStack.popPose();
        }

        var spirit = blockEntityIn.spirit;
        if (spirit == null) {
            return;
        }

        float delta = blockEntityIn.getGlowDelta();
        float ease = Easing.SINE_OUT.ease(delta);
        float offsetDistance = 0.2f - ease * 0.2f;
        float wobbleStrength = 0.1f - ease * 0.075f;
        float gameTime = level.getGameTime() + partialTicks;

        poseStack.pushPose();
        poseStack.translate(0.5f, 0, 0.5f);
        for (int i = 0; i < 5; i++) {
            float alpha = delta * 0.7f;
            var token = i == 4 ? MalumRenderTypeTokens.PYLON_GLOW_TOP : MalumRenderTypeTokens.PYLON_GLOW_SIDE;
            var renderType = LodestoneRenderTypes.ADDITIVE_TEXTURE.apply(token);
            var vertices = getVertexPositions(i);
            poseStack.pushPose();
            if (i < 4) {
                poseStack.mulPose(Axis.YN.rotationDegrees(i * 90));
            }

            int time = 160;
            for (int j = 0; j < 4; j++) {
                var color = j <= 1 ? spirit.getPrimaryColor() : spirit.getSecondaryColor();
                double offset = 0;
                if (offsetDistance > 0) {
                    double angle = j / 4f * (Math.PI * 2);
                    angle += ((gameTime % time) / time) * (Math.PI * 2);
                    offset = (offsetDistance * Math.cos(angle));
                    if (j % 2 == 0) {
                        offset *= -1;
                    }
                }

                poseStack.pushPose();
                poseStack.translate(offset, 0, 0);
                CubeVertexData.applyVertexWobble(vertices, j*2f, wobbleStrength);
                SpiritBasedWorldVFXBuilder.create(spirit)
                        .setColor(color, alpha)
                        .setRenderType(renderType)
                        .renderQuad(poseStack, vertices, 1f);
                poseStack.popPose();
                alpha *= (1 - (delta + 0.2f) * 0.4f);
            }
            poseStack.popPose();
        }
        poseStack.popPose();
    }

