								mutable.move(Direction.UP);
								AABB collisionBox = size.makeBoundingBox(mutable.getX() + 0.5F, mutable.getY(), mutable.getZ() + 0.5F);
								if (world.noCollision(collisionBox) && !world.containsAnyLiquid(collisionBox)) {
									teleportPos = mutable;
									break;
								}
							}
						}
					}
				}
				if (teleportPos != null) {
					teleportController.beginTeleportation(purpoid, teleportPos, true);
					ridingEntity.hurt(purpoid.level().damageSources().mobAttack(purpoid), (float) purpoid.getAttributeValue(Attributes.ATTACK_DAMAGE));
					if (ridingEntity instanceof ServerPlayer) {
						EndergeticExpansion.CHANNEL.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) ridingEntity), new S2CEnablePurpoidFlash());
					}
				}
			}
		}
	}

@Override
    public void tick() {
        LivingEntity target = watcher.getTarget();
        if (navigationCheckCooldown-- < 0) {
            calculateReach();
        }
        if (target != null && target.isAlive()) {
            double dist = watcher.distanceTo(target);
            watcher.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());

            if (retreatFor-- > 0) {
                if (retreatTo == null) {
                    retreatFor = 0;
                } else {
                    Vec3 retreatVec = retreatTo.subtract(watcher.position());
                    if (retreatVec.length() > 1) {
                        retreatVec = retreatVec.normalize();
                        watcher.setDeltaMovement(watcher.getDeltaMovement().add(retreatVec.scale(0.2F)));
                        watcher.setShadeMode(true);
                    } else {
                        retreatTo = null;
                    }
                }
            } else {
                if (!canReachViaGround && !watcher.isShadeMode() && watcher.onGround()) {
                    watcher.setShadeMode(true);
                }
                watcher.setShadeMode(!canReachViaGround);
                if (dist < 6 && watcher.hasLineOfSight(target) && watcher.onGround()) {
                    watcher.setShadeMode(false);
                }
                if (dist > target.getBbWidth() + watcher.getBbWidth() + 0.5F) {
                    watcher.getNavigation().moveTo(target, (watcher.isRunning() ? 1.3F : 1F) + Math.min(Math.log(possessions + 1), 1F) * 0.6F);
                } else {
                    if (watcher.hasLineOfSight(target)) {
                        if (watcher.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                            watcher.setAnimation(watcher.getRandom().nextBoolean() ? WatcherEntity.ANIMATION_ATTACK_0 : WatcherEntity.ANIMATION_ATTACK_1);
                            watcher.playSound(ACSoundRegistry.WATCHER_ATTACK.get());
                        } else if (watcher.getAnimationTick() == 8) {
                            target.hurt(target.damageSources().mobAttack(watcher), (float) watcher.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                            target.knockback(0.5D, watcher.getX() - target.getX(), watcher.getZ() - target.getZ());
                            retreatFor = 30 + watcher.getRandom().nextInt(30);
                            for (int i = 0; i < 15; i++) {
                                Vec3 vec3 = DefaultRandomPos.getPosAway(watcher, 30, 15, target.position());
                                if (vec3 != null) {
                                    retreatTo = vec3;
                                    break;
                                }
                            }
                        }
                    }
                    watcher.getNavigation().stop();
                }
            }
            if (possessions > 2 || dist < 20) {
                watcher.setRunning(true);
            }

            if (watcher.attemptPossession(target)) {
                if (watcher.getPossessedEntity() == null) {
                    possessions++;
                }
                watcher.setPossessedEntityUUID(target.getUUID());
            }
        }
    }

public void rideTick() {
        final Entity entity = this.getVehicle();
        if (this.isPassenger() && !entity.isAlive()) {
            this.stopRiding();
        } else {
            this.setDeltaMovement(0, 0, 0);
            this.tick();
            if (this.isPassenger()) {
                final Entity mount = this.getVehicle();
                if (mount instanceof final LivingEntity livingEntity) {
                    this.yBodyRot = livingEntity.yBodyRot;
                    this.setYRot(livingEntity.getYRot());
                    this.yHeadRot = livingEntity.yHeadRot;
                    this.yRotO = livingEntity.yHeadRot;
                    final float radius = 1F;
                    final float angle = (Maths.STARTING_ANGLE * livingEntity.yBodyRot);
                    final double extraX = radius * Mth.sin(Mth.PI + angle);
                    final double extraZ = radius * Mth.cos(angle);
                    this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                    if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                        this.removeVehicle();
                    }
                    if (!this.level().isClientSide) {
                        if (drinkTime % 20 == 0 && this.isAlive()) {
                            final boolean mungus = AMConfig.warpedMoscoTransformation && mount instanceof EntityMungus && ((EntityMungus) mount).isWarpedMoscoReady();
                            if (mount.hurt(this.damageSources().mobAttack(this), mungus ? 7F : 2.0F)) {
                                if (mungus) {
                                    ((EntityMungus) mount).disableExplosion();
                                }
                                final boolean sick = this.isNonMungusWarpedTrigger(mount);
                                if (sick || mungus) {
                                    if (!this.isSick()) {
                                        for (ServerPlayer serverplayerentity : this.level().getEntitiesOfClass(ServerPlayer.class, this.getBoundingBox().inflate(40.0D, 25.0D, 40.0D))) {
                                            AMAdvancementTriggerRegistry.MOSQUITO_SICK.trigger(serverplayerentity);
                                        }
                                    }
                                    this.setSick(true);
                                    this.setFlying(false);
                                    flightTicks = -150 - random.nextInt(200);
                                }
                                this.gameEvent(GameEvent.EAT);
                                this.playSound(SoundEvents.HONEY_DRINK, this.getSoundVolume(), this.getVoicePitch());
                                this.setBloodLevel(this.getBloodLevel() + 1);
                                if (this.getBloodLevel() > 3) {
                                    this.removeVehicle();
                                    AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                                    this.setFlying(false);
                                    this.flightTicks = -15;
                                }
                            }
                        }

                        if (drinkTime > 81) {
                            drinkTime = -20 - random.nextInt(20);
                            this.removeVehicle();
                            AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                            this.setFlying(false);
                            this.flightTicks = -15;
                        }
                    }
                }

            }
        }

    }

@Override
    public void aiStep() {
        super.aiStep();
        if (eyeEntity == null) {
            eyeEntity = new EntityCyclopsEye(this, 0.2F, 0, 7.4F, 1.2F, 0.6F, 1);
            eyeEntity.copyPosition(this);
        }
        if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
            this.setTarget(null);
        }
        if (this.isBlinded() && this.getTarget() != null && this.distanceToSqr(this.getTarget()) > 6) {
            this.setTarget(null);
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 5) {
            this.playSound(IafSoundRegistry.CYCLOPS_BLINDED, 1, 1);
        }
        if (this.getAnimation() == ANIMATION_EATPLAYER && this.getAnimationTick() == 25) {
            this.playSound(IafSoundRegistry.CYCLOPS_BITE, 1, 1);
        }
        if (this.getAnimation() == ANIMATION_STOMP && this.getTarget() != null && this.distanceToSqr(this.getTarget()) < 12D && this.getAnimationTick() == 14) {
            this.getTarget().hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
        }
        if (this.getAnimation() == ANIMATION_KICK && this.getTarget() != null && this.distanceToSqr(this.getTarget()) < 14D && this.getAnimationTick() == 12) {
            this.getTarget().hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            // After calling hurt the target can become null due to forge hooks
            if (this.getTarget() != null)
                this.getTarget().knockback(2, this.getX() - this.getTarget().getX(), this.getZ() - this.getTarget().getZ());

        }
        if (this.getAnimation() != ANIMATION_EATPLAYER && this.getTarget() != null && !this.getPassengers().isEmpty() && this.getPassengers().contains(this.getTarget())) {
            this.setAnimation(ANIMATION_EATPLAYER);
        }
        if (this.getAnimation() == NO_ANIMATION && this.getTarget() != null && this.getRandom().nextInt(100) == 0) {
            this.setAnimation(ANIMATION_ROAR);
        }
        if (this.getAnimation() == ANIMATION_STOMP && this.getAnimationTick() == 14) {
            for (int i1 = 0; i1 < 20; i1++) {
                double motionX = getRandom().nextGaussian() * 0.07D;
                double motionY = getRandom().nextGaussian() * 0.07D;
                double motionZ = getRandom().nextGaussian() * 0.07D;
                float radius = 0.75F * -2F;
                float angle = (0.01745329251F * this.yBodyRot) + i1 * 1F;
                double extraX = radius * Mth.sin((float) (Math.PI + angle));
                double extraY = 0.8F;
                double extraZ = radius * Mth.cos(angle);

                BlockState BlockState = this.level.getBlockState(new BlockPos(Mth.floor(this.getX() + extraX), Mth.floor(this.getY() + extraY) - 1, Mth.floor(this.getZ() + extraZ)));
                if (BlockState.getMaterial() != Material.AIR) {
                    if (level.isClientSide) {
                        level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, BlockState), this.getX() + extraX, this.getY() + extraY, this.getZ() + extraZ, motionX, motionY, motionZ);
                    }
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (eyeEntity == null) {
            eyeEntity = new EntityCyclopsEye(this, 0.2F, 0, 7.4F, 1.2F, 0.5F, 1);
            eyeEntity.copyPosition(this);
            eyeEntity.setParent(this);

        }
        if (!eyeEntity.shouldContinuePersisting()) {
            level.addFreshEntity(eyeEntity);
        }
        eyeEntity.setParent(this);
        breakBlock();
    }

@Override
    public void tick() {
        prevMotionX = getDeltaMovement().x;
        prevMotionY = getDeltaMovement().y;
        prevMotionZ = getDeltaMovement().z;

        super.tick();
        setDeltaMovement(getDeltaMovement().subtract(0, GRAVITY, 0));
        move(MoverType.SELF, getDeltaMovement());

        setYRot(-((float) Mth.atan2(getDeltaMovement().x, getDeltaMovement().z)) * (180F / (float)Math.PI));

        List<Entity> entitiesHit = getEntitiesNearby(1);
        if (!entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity instanceof ItemEntity) continue;
                if (entity == getCaster()) continue;
                if (entity instanceof EntityNaga) continue;
                if (entity instanceof ItemEntity) continue;
                if (entity.hurt(damageSources().indirectMagic(this, getCaster()), 3 * ConfigHandler.COMMON.MOBS.NAGA.combatConfig.attackMultiplier.get().floatValue()) && entity instanceof LivingEntity) {
                    ((LivingEntity)entity).addEffect(new MobEffectInstance(MobEffects.POISON, 80, 1, false, true));
                }
            }
        }

        if (!level().noCollision(this, getBoundingBox().inflate(0.1))) explode();

        if (level().isClientSide) {
            float scale = 1f;
            int steps = 4;
            double motionX = getDeltaMovement().x;
            double motionY = getDeltaMovement().y;
            double motionZ = getDeltaMovement().z;
            for (int step = 0; step < steps; step++) {
                double x = xo + step * (getX() - xo) / (double)steps;
                double y = yo + step * (getY() - yo) / (double)steps + getBbHeight() / 2f;
                double z = zo + step * (getZ() - zo) / (double)steps;
                for (int i = 0; i < 1; i++) {
                    double xSpeed = scale * 0.02 * (random.nextFloat() * 2 - 1);
                    double ySpeed = scale * 0.02 * (random.nextFloat() * 2 - 1);
                    double zSpeed = scale * 0.02 * (random.nextFloat() * 2 - 1);
                    double value = random.nextFloat() * 0.1f;
                    double life = random.nextFloat() * 10f + 15f;
                    ParticleVanillaCloudExtended.spawnVanillaCloud(level(), x - motionX * 0.5, y - motionY * 0.5, z - motionZ * 0.5, xSpeed, ySpeed, zSpeed, scale, 0.25d + value, 0.75d + value, 0.25d + value, 0.99, life);
                }
                for (int i = 0; i < 2; i++) {
                    double xSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                    double ySpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                    double zSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                    double value = random.nextFloat() * 0.1f;
                    double life = random.nextFloat() * 5f + 10f;
                    AdvancedParticleBase.spawnParticle(level(), ParticleHandler.PIXEL, x + xSpeed - motionX * 0.5, y + ySpeed - motionY * 0.5, z + zSpeed - motionZ * 0.5, xSpeed, ySpeed, zSpeed, true, 0, 0, 0, 0, scale * 3f, 0.07d + value, 0.25d + value, 0.07d + value, 1d, 0.99, life * 0.9, false, true);
                }
                for (int i = 0; i < 1; i++) {
                    if (random.nextFloat() < 0.9f) {
                        double xSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                        double ySpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                        double zSpeed = scale * 0.06 * (random.nextFloat() * 2 - 1);
                        double value = random.nextFloat() * 0.1f;
                        double life = random.nextFloat() * 5f + 10f;
                        AdvancedParticleBase.spawnParticle(level(), ParticleHandler.BUBBLE, x - motionX * 0.5, y - motionY * 0.5, z - motionZ * 0.5, xSpeed, ySpeed, zSpeed, true, 0, 0, 0, 0, 3f, 0.25d + value, 0.75d + value, 0.25d + value, 1d, 0.85, life, false, true);
                    }
                }
            }
        }
        if (tickCount > 50) discard() ;
    }

@Override
    public void tick() {
        super.tick();
        if (!level().isClientSide() && (getCaster() == null || getCaster().isRemoved() || !getCaster().isAlive())) this.discard();

        if (tickCount == 1) {
            EntityCameraShake.cameraShake(level(), position(), 30, 0.05f, 10, 30);
            playSound(MMSounds.ENTITY_SUPERNOVA_END.get(), 3f, 1f);
            if (level().isClientSide) {
                float scale = 8.2f;
                for (int i = 0; i < 15; i++) {
                    float phaseOffset = random.nextFloat();
                    AdvancedParticleBase.spawnParticle(level(), ParticleHandler.ARROW_HEAD, getX(), getY(), getZ(), 0, 0, 0, false, 0, 0, 0, 0, 8F, 0.95, 0.9, 0.35, 1, 1, 30, true, true, new ParticleComponent[]{
                            new ParticleComponent.Orbit(new Vec3[]{position().add(0, getBbHeight() / 2, 0)}, KeyTrack.startAndEnd(0 + phaseOffset, 1.6f + phaseOffset), new ParticleComponent.KeyTrack(
                                    new float[]{0.2f * scale, 0.63f * scale, 0.87f * scale, 0.974f * scale, 0.998f * scale, 1f * scale},
                                    new float[]{0, 0.15f, 0.3f, 0.45f, 0.6f, 0.75f}
                            ), KeyTrack.startAndEnd(random.nextFloat() * 2 - 1, random.nextFloat() * 2 - 1), KeyTrack.startAndEnd(random.nextFloat() * 2 - 1, random.nextFloat() * 2 - 1), KeyTrack.startAndEnd(random.nextFloat() * 2 - 1, random.nextFloat() * 2 - 1), false),
                            new RibbonComponent(ParticleHandler.RIBBON_FLAT, 10, 0, 0, 0, 0.2F, 0.95, 0.9, 0.35, 1, true, true, new ParticleComponent[]{
                                    new PropertyOverLength(PropertyOverLength.EnumRibbonProperty.SCALE, KeyTrack.startAndEnd(1, 0)),
                                    new ParticleComponent.PropertyControl(EnumParticleProperty.ALPHA, KeyTrack.startAndEnd(1, 0), false)
                            }),
                            new ParticleComponent.PropertyControl(EnumParticleProperty.ALPHA, KeyTrack.startAndEnd(1, 0), false),
                            new ParticleComponent.FaceMotion()
                    });
                }
            }
        }

        if (getCaster() != null) {
            float ageFrac = tickCount / (float)(EntitySuperNova.DURATION);
            float scale = (float) Math.pow(ageFrac, 0.5) * 5f;
            setBoundingBox(getBoundingBox().inflate(scale));
            setPos(xo, yo, zo);
            List<Entity> hitList = getEntitiesNearbyCube(Entity.class, scale);
            for (Entity entity : hitList) {
                if (entity instanceof ItemEntity) continue;
            	if (getCaster() == entity) continue;
                if (entity instanceof ItemEntity) continue;
                if (getCaster() instanceof EntityUmvuthi && entity instanceof LeaderSunstrikeImmune) continue;
                if (entity instanceof LivingEntity livingEntity) {
                    if (getCaster().canAttack(livingEntity)) {
                        float damageFire = 4f;
                        float damageMob = 4f;
                        if (getCaster() instanceof EntityUmvuthi) {
                            damageFire *= ConfigHandler.COMMON.MOBS.UMVUTHI.combatConfig.attackMultiplier.get();
                            damageMob *= ConfigHandler.COMMON.MOBS.UMVUTHI.combatConfig.attackMultiplier.get();
                        }
                        if (getCaster() instanceof Player) {
                            damageFire *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.SUNS_BLESSING.sunsBlessingAttackMultiplier.get() * 0.8;
                            damageMob *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.SUNS_BLESSING.sunsBlessingAttackMultiplier.get() * 0.8;
                        }
                        boolean hitWithFire = DamageUtil.dealMixedDamage(livingEntity, damageSources().mobProjectile(this, getCaster()), damageMob, damageSources().onFire(), damageFire).getRight();
                        if (hitWithFire) {
                            Vec3 diff = livingEntity.position().subtract(position());
                            diff = diff.normalize();
                            livingEntity.knockback(0.4f, -diff.x, -diff.z);
                            livingEntity.igniteForSeconds(5);
                        }
                    }
                }
                else {
                    entity.hurt(damageSources().mobProjectile(this, getCaster()), 4);
                }
            }
        }
        if (tickCount > DURATION) discard() ;
    }

@Override
	public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand)
	{
		ItemStack stack = player.getItemInHand(hand);
		if (PlayerHelper.isFakePlayer(player))
			return super.use(world, player, hand);

		if (this.canUseForSacrifice(stack))
		{
			player.startUsingItem(hand);
			return InteractionResultHolder.success(stack);
		}

		int lpAdded = ConfigManager.COMMON.sacrificialDaggerConversion.get() * 2;

//		RayTraceResult rayTrace = rayTrace(world, player, false);
//		if (rayTrace != null && rayTrace.typeOfHit == RayTraceResult.Type.BLOCK)
//		{
//			TileEntity tile = world.getTileEntity(rayTrace.getBlockPos());
//
//			if (tile != null && tile instanceof TileAltar && stack.getItemDamage() == 1)
//				lpAdded = ((TileAltar) tile).getCapacity();
//		}

		if (!player.getAbilities().instabuild)
		{
			SacrificeKnifeUsedEvent evt = new SacrificeKnifeUsedEvent(player, true, true, 2, lpAdded);
			if (MinecraftForge.EVENT_BUS.post(evt))
				return super.use(world, player, hand);

			if (evt.shouldDrainHealth)
			{
				player.invulnerableTime = 0;

				player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 0.001F);
				player.setHealth(Math.max(player.getHealth() - 1.998F, 0.0001f));
				if (player.getHealth() <= 0.001f && !world.isClientSide)
				{
					player.invulnerableTime = 0;
					player.hurt(player.damageSources().source(BloodMagicDamageTypes.SACRIFICE), 10);
				}
			}

			if (!evt.shouldFillAltar)
				return super.use(world, player, hand);

			lpAdded = evt.lpAdded;
		} else if (player.isShiftKeyDown())
		{
			lpAdded = Integer.MAX_VALUE;
		}

		double posX = player.getX();
		double posY = player.getY();
		double posZ = player.getZ();
		world.playSound(player, posX, posY, posZ, SoundEvents.FIRE_EXTINGUISH, SoundSource.BLOCKS, 0.5F, 2.6F + (world.random.nextFloat() - world.random.nextFloat()) * 0.8F);

		for (int l = 0; l < 8; ++l)
			world.addParticle(DustParticleOptions.REDSTONE, posX + Math.random() - Math.random(), posY + Math.random() - Math.random(), posZ + Math.random() - Math.random(), 0, 0, 0);

		if (!world.isClientSide && PlayerHelper.isFakePlayer(player))
			return super.use(world, player, hand);

		// TODO - Check if SoulFray is active
		PlayerSacrificeHelper.findAndFillAltar(world, player, lpAdded, false);

		return super.use(world, player, hand);
	}

@Override
    public void tick() {
        super.tick();
        prevStab = this.getStab();
        Entity entity = getTargetEntity();
        if (level().isClientSide) {
            level().addParticle(DustParticleOptions.REDSTONE, (double) this.getRandomX(0.75F), (double) this.getRandomY(), (double) this.getRandomZ(0.75F), 0.0D, 0.0D, 0.0D);
        }
        if (!playedSummonNoise) {
            this.playSound(ACSoundRegistry.DESOLATE_DAGGER_SUMMON.get());
            playedSummonNoise = true;
        }
        if (entity != null) {
            this.noPhysics = true;
            float invStab = 1F - getStab();
            Vec3 orbitAround = entity.position().add(0, entity.getBbHeight() * 0.25F, 0);
            orbitRandom.setSeed(this.getId());
            if (orbitOffset == 0) {
                orbitOffset = orbitRandom.nextInt(360);
            }
            Vec3 orbitAdd = new Vec3(0, (orbitRandom.nextFloat() + entity.getBbHeight()) * invStab, (orbitRandom.nextFloat() + entity.getBbWidth()) * invStab).yRot((float) Math.toRadians((orbitOffset)));
            this.setDeltaMovement(orbitAround.add(orbitAdd).subtract(this.position()));
            if (!level().isClientSide) {
                if (orbitFor > 0 && entity.isAlive()) {
                    orbitFor--;
                } else {
                    this.setStab(Math.min(this.getStab() + 0.2F, 1F));
                }
                if (this.getStab() >= 1F) {
                    Entity player = getPlayer();
                    Entity damageFrom = player == null ? this : player;
                    float damage = 2 + this.getItemStack().getEnchantmentLevel(ACEnchantmentRegistry.IMPENDING_STAB.get()) * 2F;
                    if (entity.hurt(ACDamageTypes.causeDesolateDaggerDamage(this.level().registryAccess(), damageFrom), damage)) {
                        this.playSound(ACSoundRegistry.DESOLATE_DAGGER_HIT.get());
                        int healBy = this.getItemStack().getEnchantmentLevel(ACEnchantmentRegistry.SATED_BLADE.get());
                        if(healBy > 0 && damageFrom instanceof Player healPlayer && healPlayer.getFoodData().getSaturationLevel() < 5F){
                            healPlayer.getFoodData().setSaturation(healPlayer.getFoodData().getSaturationLevel() + healBy * 0.1F);
                        }
                    }
                    this.discard();
                }
            }
            double d1 = entity.getZ() - this.getZ();
            double d3 = entity.getEyeY() - this.getEyeY();
            double d2 = entity.getX() - this.getX();
            float f = Mth.sqrt((float) (d2 * d2 + d1 * d1));
            this.setYRot(-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
            this.setXRot(-(float) (Mth.atan2(d3, f) * (double) (180F / (float) Math.PI)));
        } else if (tickCount > 3) {
            this.noPhysics = false;
            this.discard();
        }
        this.move(MoverType.SELF, this.getDeltaMovement());
        this.setDeltaMovement(this.getDeltaMovement().scale(0.9F));

        if (this.level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        move(MoverType.SELF, getDeltaMovement());

        if (tickCount == 1) {
            if (level().isClientSide) {
                MMCommon.PROXY.playIceBreathSound(this);
            }
        }

        List<Entity> entitiesHit = getEntitiesNearby(2);
        if (!entitiesHit.isEmpty()) {
            for (Entity entity : entitiesHit) {
                if (entity instanceof ItemEntity) continue;
                if (entity == getCaster()) continue;
                if (entity instanceof ItemEntity) continue;
                if (entity.getType().is(EntityTypeTags.FREEZE_IMMUNE_ENTITY_TYPES) || entity instanceof EnderDragon) continue;
                if (entity.hurt(damageSources().freeze(), 3f * ConfigHandler.COMMON.MOBS.FROSTMAW.combatConfig.attackMultiplier.get().floatValue())) {
                    if (entity instanceof LivingEntity) DataHandler.getData(entity, DataHandler.FROZEN_DATA).addFreezeProgress((LivingEntity) entity, 1);
                }
            }
        }

        if (!level().noCollision(this, getBoundingBox().inflate(0.15))) {
            explode();
        }

        if (level().isClientSide) {
            float scale = 2f;
            double x = getX();
            double y = getY() + getBbHeight() / 2;
            double z = getZ();
            double motionX = getDeltaMovement().x;
            double motionY = getDeltaMovement().y;
            double motionZ = getDeltaMovement().z;
            for (int i = 0; i < 4; i++) {
                double xSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double ySpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double zSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                float value = random.nextFloat() * 0.15f;
                level().addParticle(new ParticleCloud.Data(0.75f + value, 0.75f + value,1f, scale * (10f + random.nextFloat() * 20f), 20, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x + xSpeed, y + ySpeed, z + zSpeed, xSpeed, ySpeed, zSpeed);
            }
            for (int i = 0; i < 1; i++) {
                double xSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double ySpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                double zSpeed = scale * 0.01 * (random.nextFloat() * 2 - 1);
                level().addParticle(new ParticleCloud.Data(1f, 1f, 1f, scale * (5f + random.nextFloat() * 10f), 40, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x, y, z, xSpeed, ySpeed, zSpeed);
            }

            for (int i = 0; i < 5; i++) {
                double xSpeed = scale * 0.05 * (random.nextFloat() * 2 - 1);
                double ySpeed = scale * 0.05 * (random.nextFloat() * 2 - 1);
                double zSpeed = scale * 0.05 * (random.nextFloat() * 2 - 1);
                level().addParticle(new ParticleSnowFlake.Data(40, false), x - 20 * (xSpeed) + motionX, y - 20 * ySpeed + motionY, z - 20 * zSpeed + motionZ, xSpeed, ySpeed, zSpeed);
            }

            float yaw = (float) Math.atan2(motionX, motionZ);
            float pitch = (float) (Math.acos(motionY / Math.sqrt(motionX * motionX + motionY * motionY + motionZ * motionZ)) + Math.PI / 2);
            if (tickCount % 3 == 0) {
                level().addParticle(new ParticleRing.Data(yaw, pitch, 40, 0.9f, 0.9f, 1f, 0.4f, (int) (scale * 16), false, ParticleRing.EnumRingBehavior.GROW_THEN_SHRINK), x + 1.5f * motionX, y + 1.5f *motionY, z + 1.5f * motionZ, 0, 0, 0);
            }

            if (tickCount == 1) {
                level().addParticle(new ParticleRing.Data(yaw, pitch, 20, 0.9f, 0.9f, 1f, 0.4f, (int) (scale * 16), false, ParticleRing.EnumRingBehavior.GROW), x, y, z, 0, 0, 0);
            }
        }
        if (tickCount > 50) discard() ;
    }

public void tick() {
        super.tick();
        boolean flag = this.isWaiting();
        float f = this.getRadius();
        if (this.level().isClientSide) {
            if (flag && this.random.nextBoolean()) {
                return;
            }
            ParticleOptions particleoptions = this.isSoul() ? ParticleTypes.SOUL_FIRE_FLAME : ParticleTypes.FLAME ;
            float f1 = flag ? 0.2F : f;
            double spread = Math.PI * 2 ;
            int arcLen = Mth.ceil(this.getRadius() * spread);

            if(!flag) {
                if (this.tickCount % 2 == 0) {
                    for (int j = 0; j < arcLen; ++j) {
                        float f2 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        double d0 = this.getX() + (double) (Mth.cos(f2) * f1) * 0.9;
                        double d2 = this.getY();
                        double d4 = this.getZ() + (double) (Mth.sin(f2) * f1) * 0.9;
                        this.level().addParticle(particleoptions, d0, d2, d4, random.nextGaussian() * 0.07D, 0.125D * this.getRadius() + 0.4D, random.nextGaussian() * 0.07D);
                    }
                }
                if (this.random.nextInt(24) == 0) {
                    this.level().playLocalSound(this.getX() + 0.5D, this.getY() + 0.5D, this.getZ() + 0.5D, SoundEvents.BLAZE_BURN, this.getSoundSource(), 1.0F + this.random.nextFloat(), this.random.nextFloat() * 0.7F + 0.3F, false);
                }
            }
        } else {
            if (this.tickCount >= this.waitTime + this.duration + this.warmupDelayTicks) {
                if(this.getRadius() > 0 ){
                    this.setRadius(getRadius() - 0.1F);
                }else{
                    if(!this.isSoul()) {
                        int explosionradius = this.owner instanceof Player ? 1 : 2;

                        IgnisExplosion explosion = new IgnisExplosion(level(), this.owner,null,null, this.getX(), this.getY(), this.getZ(), explosionradius, false, Explosion.BlockInteraction.KEEP);
                        explosion.explode();
                        explosion.finalizeExplosion(0,0);
                    }
                    this.level().broadcastEntityEvent(this, (byte)4);
                    this.discard();
                }
            }


            if (this.tickCount >= this.warmupDelayTicks) {
                this.setSee(true);
            }


            boolean flag1 = this.tickCount < this.waitTime + this.warmupDelayTicks;
            if (flag != flag1) {
                this.setWaiting(flag1);
            }

            if (flag1) {
                return;
            }

        }

        if(!flag) {
            if (this.tickCount % 5 == 0) {
                for (LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())) {
                    this.damage(livingentity);
                }
            }
        }
    }

default void kick(boolean backKick, boolean softBackKick) {
		AbstractHorse horse = (AbstractHorse) this;

		this.setKickTime(1);
		horse.setEating(false);

		AttributeInstance attributeinstance = horse.getAttribute(Attributes.MOVEMENT_SPEED);
		if (!attributeinstance.hasModifier(SPEED_MODIFIER_KICKING.id()))
			attributeinstance.addTransientModifier(SPEED_MODIFIER_KICKING);

		if (!backKick) {
			this.playFrontKickAnim();
			horse.level().broadcastEntityEvent(horse, (byte) 8);
		} else {
			this.playBackKickAnim();
			horse.level().broadcastEntityEvent(horse, (byte) 9);
		}

		List<LivingEntity> nearby = horse.level().getEntitiesOfClass(LivingEntity.class, horse.getBoundingBox().inflate(1.0F), KICKABLE_PREDICATE);
		for (LivingEntity living : nearby) {
			Vec3 attackAngleVector = living.position().subtract(horse.position()).normalize();
			attackAngleVector = new Vec3(attackAngleVector.x, 0.0D, attackAngleVector.z);

			float rot = horse.getVisualRotationYInDegrees();
			float x = Mth.sin(rot * Mth.DEG_TO_RAD);
			float z = -Mth.cos(rot * Mth.DEG_TO_RAD);
			double angle = attackAngleVector.dot(Vec3.directionFromRotation(0.0F, rot).normalize());
			boolean jumpkick = this.canJumpKick();

			if (!backKick && angle > 0.7D || backKick && angle < -0.7D) {
				DamageSource source;
				LivingEntity rider = horse.getControllingPassenger();
				if (rider != null) {
					source = EnvironmentalDamageTypes.ridingZebra(horse.level(), horse, rider);
				} else {
					source = horse.damageSources().mobAttack(horse);
				}
				float damage = (float) horse.getAttributeValue(Attributes.ATTACK_DAMAGE);
				float knockback = (float) horse.getAttributeValue(Attributes.ATTACK_KNOCKBACK);

				if (jumpkick) {
					float f = this.getJumpStrength();
					if (rider != null && rider.zza <= 0.0F)
						f *= 0.5F;
					damage += f * 6.0F;
					knockback = knockback * 0.8F + f * 1.1F;
				} else if (backKick) {
					if (!softBackKick)
						damage += 2.0F;
					else if (damage > 1.0F)
						damage = 1.0F;
					knockback *= 1.2F;
				} else {
					knockback *= 0.8F;
				}

				if (living.hurt(source, (int) damage)) {
					if (horse.level() instanceof ServerLevel serverLevel) {
						EnchantmentHelper.doPostAttackEffects(serverLevel, living, source);
					}

					if (!backKick)
						living.knockback(knockback, x, z);
					else
						living.knockback(knockback, -x, -z);
				}
			}
		}
	}

public void tick() {
        super.tick();
        if(!madeOpenNoise){
            this.gameEvent(GameEvent.ENTITY_PLACE);
            this.playSound(ModSounds.BLACK_HOLE_OPENING.get(), 0.7F, 1 + random.nextFloat() * 0.2F);
            madeOpenNoise = true;
        }


        for (Entity entity : this.level().getEntities(this, this.getBoundingBox().inflate(30))) {
            if (entity != owner) {
                if (entity instanceof Player && ((Player) entity).getAbilities().invulnerable) continue;
                if (isAlliedTo(entity)) continue;
                if (entity instanceof The_Leviathan_Entity) continue;
                if (entity instanceof The_Leviathan_Tongue_Entity) continue;
                Vec3 diff = entity.position().subtract(this.position().add(0, 0, 0));
                if (entity instanceof LivingEntity) {
                    diff = diff.normalize().scale( getStage() * 0.015);
                    entity.setDeltaMovement(entity.getDeltaMovement().subtract(diff));
                } else if(!entity.getType().is(ModTag.DIMENSIONAL_LIFT_IMMUNE)) {
                    diff = diff.normalize().scale(getStage() * 0.045);
                    entity.setDeltaMovement(entity.getDeltaMovement().subtract(diff));
                }
            }
        }
            berserkBlockBreaking(15, 15, 15);

            for (LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.2D, 0.0D, 0.2D))) {
                this.damage(livingentity);
            }

            for (Entity entity : this.level().getEntities(this, this.getBoundingBox().inflate(0.5))) {
                if (entity instanceof Cm_Falling_Block_Entity) {
                    entity.remove(RemovalReason.DISCARDED);
                }
            }


            if (this.random.nextInt(3000) < this.ambientSoundTime++) {
                this.resetAmbientSoundTime();
                this.playSound(ModSounds.BLACK_HOLE_LOOP.get(), 0.7F, 1 + random.nextFloat() * 0.2F);
            }



        this.setLifespan(this.getLifespan() - 1);
        if(this.getLifespan() <= 100){
            if(!madeCloseNoise){
                this.gameEvent(GameEvent.ENTITY_PLACE);
                this.playSound(ModSounds.BLACK_HOLE_CLOSING.get(), 0.7F, 1 + random.nextFloat() * 0.2F);
                madeCloseNoise = true;
            }
            if(this.tickCount % 40 == 0){
                this.setStage(this.getStage() - 1);
            }

            if (this.getStage() <= 0) {
                if(!madeParticle){
                    if (this.level().isClientSide) {
                        this.level().addParticle(ModParticle.SHOCK_WAVE.get(), this.getX(), this.getY(), this.getZ(), 0, 0, 0);
                    }else{
                        this.level().explode(this.owner, this.getX(), this.getY(), this.getZ(), 4.0F, false, Level.ExplosionInteraction.NONE);
                    }
                    madeParticle = true;
                }else{
                    this.discard();
                }
            }
        }
    }

@Override
    protected void explode() {
        this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.GENERIC_EXPLODE.value(),
                SoundSource.BLOCKS, 4.0F,
                (1.0F + (this.level().getRandom().nextFloat() - this.level().getRandom().nextFloat()) * 0.2F) * 32.9F);

        if (this.isInWater()) {
            return;
        }

        // TODO 1.21.4: Can likely be rewritten to use the explosion calculator
        var damageSource = Explosion.getDefaultDamageSource(this.level(), this);
        var ex = new ServerExplosion(
                (ServerLevel) this.level(),
                this,
                damageSource,
                new ExplosionDamageCalculator(),
                new Vec3(this.getX(), this.getY(), this.getZ()),
                0.2f,
                false,
                AEConfig.instance().isTinyTntBlockDamageEnabled() ? BlockInteraction.DESTROY_WITH_DECAY
                        : BlockInteraction.KEEP);
        final AABB area = new AABB(this.getX() - 1.5, this.getY() - 1.5f, this.getZ() - 1.5,
                this.getX() + 1.5, this.getY() + 1.5, this.getZ() + 1.5);
        final List<Entity> list = this.level().getEntities(this, area);

        for (Entity e : list) {
            e.hurt(level().damageSources().explosion(ex), 6);
        }

        var pos = new ArrayList<BlockPos>();
        if (AEConfig.instance().isTinyTntBlockDamageEnabled()) {
            this.setPos(this.getX(), this.getY() - 0.25, this.getZ());

            for (int x = (int) (this.getX() - 2); x <= this.getX() + 2; x++) {
                for (int y = (int) (this.getY() - 2); y <= this.getY() + 2; y++) {
                    for (int z = (int) (this.getZ() - 2); z <= this.getZ() + 2; z++) {
                        final BlockPos point = new BlockPos(x, y, z);
                        final BlockState state = this.level().getBlockState(point);
                        final Block block = state.getBlock();

                        if (!state.isAir()) {
                            float strength = (float) (2.3f
                                    - ((x + 0.5f - this.getX()) * (x + 0.5f - this.getX())
                                            + (y + 0.5f - this.getY()) * (y + 0.5f - this.getY())
                                            + (z + 0.5f - this.getZ()) * (z + 0.5f - this.getZ())));

                            final float fluidResistance = !state.getFluidState().isEmpty()
                                    ? state.getFluidState().getExplosionResistance()
                                    : 0f;
                            final float resistance = Math
                                    .max(block.getExplosionResistance(state, this.level(), point, ex), fluidResistance);
                            strength -= (resistance + 0.3F) * 0.11f;

                            if (strength > 0.01 && !state.isAir()) {
                                level().setBlock(point, Blocks.AIR.defaultBlockState(), 3);
                                state.onExplosionHit((ServerLevel) this.level(), point, ex, (stack, dropPoint) -> {
                                    Block.popResource(this.level(), dropPoint, stack);
                                });
                                pos.add(point);
                            }
                        }
                    }
                }
            }
        }
        EventHooks.onExplosionDetonate(this.level(), ex, list, pos);

        AppEng.instance().sendToAllNearExcept(null, this.getX(), this.getY(), this.getZ(), 64, this.level(),
                new MockExplosionPacket(this.getX(), this.getY(), this.getZ()));
    }

@SubscribeEvent
        public static void onPlayerFall(LivingFallEvent event) {
            if (event.getDistance() > 3.0F && event.getEntity() instanceof Player player) {
                float origDistance = event.getDistance();

                CommonArmorHandler handler = CommonArmorHandler.getHandlerForPlayer(player);

                JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
                if (event.getEntity().level().getDifficulty() == Difficulty.HARD && jbState.isActive()) {
                    // thrusting into the ground hurts at hard difficulty!
                    event.setDamageMultiplier(0.2F);
                    return;
                }
                if (handler.upgradeUsable(CommonUpgradeHandlers.jumpBoostHandler, true)) {
                    // straight fall distance reduction if jump upgrade operational in legs
                    event.setDistance(Math.max(0, event.getDistance() - 1.5f * handler.getUpgradeCount(EquipmentSlot.LEGS, ModUpgrades.JUMPING.get())));
                    if (event.getDistance() < 2) {
                        event.setCanceled(true);
                        return;
                    }
                }
                if (!handler.upgradeUsable(CommonUpgradeHandlers.fallProtectionHandler, true)) {
                    return;
                }

                if (!player.level().isClientSide) {
                    float airNeeded = event.getDistance() * PneumaticValues.PNEUMATIC_ARMOR_FALL_USAGE;
                    float extraAirNeeded = 0f;

                    int airAvailable = handler.getAir(EquipmentSlot.FEET);
                    List<Entity> stomped = new ArrayList<>();
                    if (handler.upgradeUsable(CommonUpgradeHandlers.stompHandler, true)) {
                        for (Entity e: player.level().getEntities(player, new AABB(player.blockPosition()).inflate(7.0), e -> e instanceof Mob && e.isAlive())) {
                            if (airAvailable > airNeeded + extraAirNeeded) {
                                stomped.add(e);
                                extraAirNeeded += airNeeded;
                            } else {
                                break;
                            }
                        }
                    }
                    if (airAvailable < 1) {
                        return;
                    } else if (airAvailable >= airNeeded + extraAirNeeded) {
                        event.setCanceled(true);
                    } else {
                        event.setDamageMultiplier(1.0F - (airAvailable / airNeeded));
                    }
                    for (int i = 0; i < event.getDistance() / 2; i++) {
                        float sx = player.getRandom().nextFloat() * 0.6F - 0.3F;
                        float sz = player.getRandom().nextFloat() * 0.6F - 0.3F;
                        NetworkHandler.sendToAllTracking(PacketSpawnParticle.oneParticle(AirParticleData.DENSE,
                                player.position().toVector3f(),
                                new Vector3f(sx, 0.1f, sz)
                        ), player.level(), player.blockPosition());
                    }
                    for (Entity e : stomped) {
                        NetworkHandler.sendToAllTracking(PacketSpawnParticle.oneParticle(ParticleTypes.EXPLOSION,
                                e.position().toVector3f(),
                                PneumaticCraftUtils.VEC3F_ZERO
                        ), player.level(), player.blockPosition());
                        e.hurt(player.damageSources().explosion(player, null), Mth.clamp(origDistance / 3f, 1f, 20f));
                    }
                    if (!stomped.isEmpty()) {
                        player.level().playSound(null, player.blockPosition(), SoundEvents.GENERIC_EXPLODE.value(), SoundSource.PLAYERS, 1f, 0.5f);
                    }
                    player.level().playSound(null, player.blockPosition(), ModSounds.SHORT_HISS.get(), SoundSource.PLAYERS, 0.3f, 0.8f);
                    handler.addAir(EquipmentSlot.FEET, (int) -(airNeeded + extraAirNeeded));
                }
            }
        }

@Override
    public void render(DeltaTracker deltaTracker, Camera camera, GameRenderer gameRenderer, Matrix4f viewMat, Matrix4f projMat) {
        Minecraft mc = Minecraft.getInstance();
        long gameTime = mc.level.getGameTime();
        var partialTicks = deltaTracker.getGameTimeDeltaTicks();
        float uOffset = ((gameTime + partialTicks) % 8000) / 4000f;
        float vOffset = ((gameTime + 500f + partialTicks) % 8000) / 8000f;

        target.setClearColor(0, 0, 0, 0);

        target.clear(Minecraft.ON_OSX);
        MultiBufferSource.BufferSource bufferSource = mc.renderBuffers().bufferSource();
        Matrix4fStack matrix4fstack = RenderSystem.getModelViewStack();
        matrix4fstack.pushMatrix();
        matrix4fstack.mul(viewMat);
        RenderSystem.applyModelViewMatrix();


        PoseStack poseStack = new PoseStack();
        poseStack.pushPose();
        int cubeScale = 200;
        poseStack.scale(cubeScale, cubeScale, cubeScale);
//        Vector3f cameraPosition = camera.getPosition().toVector3f();
//        poseStack.translate(-cameraPosition.x(), -cameraPosition.y(), -cameraPosition.z());
        poseStack.mulPose(Axis.XP.rotationDegrees(((gameTime + partialTicks) * 0.2f) % 360));
        poseStack.mulPose(Axis.YP.rotationDegrees(((gameTime + partialTicks) * 0.1f) % 360));
        poseStack.mulPose(Axis.ZP.rotationDegrees(((gameTime + partialTicks) * 0.05f) % 360));


        for (int i = 0; i < 4; i++) {
            float speed = 200f + 100f * i;
            float distortion = 4f + 2 * i;
            float scale = (2 - 0.05f * i);
            float red = 0.8f;
            float green = 0.6f;
            float blue = 0.7f;
            float alpha = 0.8f - i * 0.05f;

            var uniforms = UniformData.create()
                    .setUniform("Speed", speed)
                    .setUniform("Distortion", distortion)
                    .setUniform("Width", 512f)
                    .setUniform("Height", 512f)
                    .setUniform("UVCoordinates", -20f, 40f, -20f, 40f)
                    .build();

            var builder = MalumRenderTypes.WEEPING_SKYBOX.apply(MalumRenderTypeTokens.VOID_NOISE)
                    .addUniformData(uniforms);

            var renderType = builder.getRenderType();
            VertexConsumer consumer = bufferSource.getBuffer(renderType);
            var vfxBuilder = VFXBuilders.createWorld()
                    .setVertexConsumer(consumer)
                    .setRenderType(renderType)
                    .setColor(red, green, blue)
                    .setAlpha(alpha);
            var cubeData = CubeVertexData.makeCubePositions(-scale).applyWobble(0, 0.5f, 0.015f);

            vfxBuilder.setUV(-uOffset, vOffset, 1 - uOffset, 1 + vOffset).renderCube(poseStack, cubeData);
            vfxBuilder.setUV(uOffset * 2, -vOffset * 2, (1 + uOffset) * 2, (1 - vOffset) * 2).renderCube(poseStack, cubeData);

            uOffset = -uOffset * 1.25f - 0.2f;
            vOffset = -vOffset * 1.25f + 0.4f;
            bufferSource.endBatch(renderType);
        }
        poseStack.popPose();

        matrix4fstack.popMatrix();
        RenderSystem.applyModelViewMatrix();
        Minecraft.getInstance().getMainRenderTarget().bindWrite(true);

    }

@Override
    protected void handleAttackLogic(double distanceSquared) {
        var meleeRange = meleeRange();
        if (meleeAnimTimer < 0 && (!wantsToMelee || distanceSquared > meleeRange * meleeRange || spellCastingMob.isCasting())) {
            super.handleAttackLogic(distanceSquared);
            return;
        }
        //Handling Animation hit frames
        mob.getLookControl().setLookAt(target);
        deadKing.isMeleeing = meleeAnimTimer > 0;
        if (meleeAnimTimer > 0) {
            //We are currently attacking and are in a melee animation
            forceFaceTarget();
            meleeAnimTimer--;
            if (currentAttack.data.isHitFrame(meleeAnimTimer - 4)) {
                if (currentAttack == DeadKingBoss.AttackType.SLAM) {
                    mob.playSound(SoundRegistry.DEAD_KING_SLAM.get());
                } else {
                    playSwingSound();
                }
            } else if (currentAttack.data.isHitFrame(meleeAnimTimer)) {
                Vec3 lunge = target.position().subtract(mob.position()).normalize().scale(.35f);
                mob.push(lunge.x, lunge.y, lunge.z);
                if (currentAttack == DeadKingBoss.AttackType.SLAM) {
                    Vec3 slamPos = mob.position().add(mob.getForward().multiply(1, 0, 1).normalize().scale(2.5f));
                    Vec3 bbHalf = new Vec3(meleeRange, meleeRange, meleeRange).scale(.3);
                    float damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) * 1.5f;
                    mob.level.getEntitiesOfClass(LivingEntity.class, new AABB(slamPos.subtract(bbHalf), slamPos.add(bbHalf))).forEach((entity) -> {
                        if (entity.isPickable() && !DamageSources.isFriendlyFireBetween(mob, entity)) {
                            entity.hurt(mob.level().damageSources().mobAttack(mob), damage);
                            var impulse = (slamPos.subtract(entity.position()).add(0, 0.75, 0)).normalize().scale(Mth.lerp(entity.distanceToSqr(mob.position()) / (meleeRange * meleeRange), 2, .5));
                            entity.setDeltaMovement(entity.getDeltaMovement().add(impulse));
                            entity.hurtMarked = true;
                            if (entity instanceof Player player && player.isBlocking()) {
                                player.disableShield();
                            }
                        }
                    });
                } else {
                    if (distanceSquared <= meleeRange * meleeRange && Utils.hasLineOfSight(mob.level, mob, target, true)) {
                        boolean flag = this.mob.doHurtTarget(target);
                        target.invulnerableTime = 0;
                        if (flag) {
                            if (currentAttack.data.isSingleHit() && ((mob.getRandom().nextFloat() < .75f) || target.isBlocking())) {
                                //Attack again! combos!
                                queueCombo = randomizeNextAttack(0);
                            }
                        }
                    }
                }

            }
        } else if (queueCombo != null && target != null && !target.isDeadOrDying()) {
            nextAttack = queueCombo;
            queueCombo = null;
            doMeleeAction();
        } else if (meleeAnimTimer == 0) {
            //Reset animations/attack
            nextAttack = randomizeNextAttack((float) distanceSquared);
            resetMeleeAttackInterval(distanceSquared);
            meleeAnimTimer = -1;
        } else {
            //Handling attack delay
            if (distanceSquared < meleeRange * meleeRange * 1.2 * 1.2) {
                if (hasLineOfSight && --this.meleeAttackDelay == 0) {
                    doMeleeAction();
                } else if (this.meleeAttackDelay < 0) {
                    resetMeleeAttackInterval(distanceSquared);
                }
            }
        }
    }

@Override
	public void tick() {
		Purpoid purpoid = this.purpoid;
		if (!purpoid.isBoosting()) {
			purpoid.setBoostingTicks(5);
		}
		this.delayCounter = Math.max(this.delayCounter - 1, 0);
		LivingEntity target = purpoid.getTarget();
		double distanceToTargetSq = purpoid.distanceToSqr(target);
		RandomSource random = purpoid.getRandom();
		if (this.delayCounter <= 0 && random.nextFloat() < 0.05F) {
			this.delayCounter = 15 + random.nextInt(11);
			PathNavigation pathNavigator = purpoid.getNavigation();
			if (distanceToTargetSq >= 9.0F) {
				Path path = pathNavigator.createPath(purpoid.getSize() == PurpoidSize.NORMAL ? findAirPosAboveTarget(purpoid.level(), target) : target.blockPosition().above(random.nextInt(3)), 0);
				if (path == null || !pathNavigator.moveTo(path, 2.25F)) {
					this.delayCounter += 20;
				}
			} else {
				purpoid.getMoveControl().setWantedPosition(target.getX(), target.getY(), target.getZ(), 2.25F);
			}
		}

		boolean small = purpoid.getSize() == PurpoidSize.PURP;
		float width = purpoid.getBbWidth() * (small ? 3.25F : 2.0F);
		double reachRange = width * width + target.getBbWidth();
		if (distanceToTargetSq <= reachRange) {
			if (small) {
				if (purpoid.isEndimationPlaying(EEPlayableEndimations.PURPOID_TELEFRAG) && purpoid.getAnimationTick() == 5) {
					target.hurt(purpoid.level().damageSources().mobAttack(purpoid), (float) purpoid.getAttributeValue(Attributes.ATTACK_DAMAGE));
					double targetX = target.getX();
					double targetY = target.getY();
					double targetZ = target.getZ();
					for (int i = 0; i < 16; i++) {
						double randomX = targetX + (random.nextDouble() - 0.5D) * 32.0D;
						double randomY = targetY + (random.nextInt(33) - 16);
						double randomZ = targetZ + (random.nextDouble() - 0.5D) * 32.0D;
						if (target.randomTeleport(randomX, randomY, randomZ, false)) {
							if (target instanceof ServerPlayer) {
								EndergeticExpansion.CHANNEL.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) target), new S2CEnablePurpoidFlash());
							}
							break;
						}
					}
				} else if (purpoid.isNoEndimationPlaying()) {
					NetworkUtil.setPlayingAnimation(purpoid, EEPlayableEndimations.PURPOID_TELEFRAG);
				}
			} else {
				purpoid.startRiding(target);
			}
			this.teleportToTargetTimer = 0;
		} else if (small && distanceToTargetSq >= 2.0D && distanceToTargetSq <= 1024.0D && random.nextFloat() < 0.1F && ++this.teleportToTargetTimer >= 10) {
			double targetX = target.getX();
			double targetY = target.getY();
			double targetZ = target.getZ();
			Level level = purpoid.level();
			EntityDimensions dimensions = purpoid.getDimensions(purpoid.getPose());
			double predictedXDisplacement = Mth.clamp(target.getDeltaMovement().x() * 57.0F, -7.0D, 7.0D);
			double predictedZDisplacement = Mth.clamp(target.getDeltaMovement().z() * 57.0F, -7.0D, 7.0D);
			for (int i = 0; i < 16; i++) {
				double randomX = targetX + predictedXDisplacement;
				double randomY = targetY + random.triangle(0.0D, 2.0D);
				double randomZ = targetZ + predictedZDisplacement;
				if (level.noCollision(dimensions.makeBoundingBox(randomX, randomY, randomZ))) {
					purpoid.getTeleportController().beginTeleportation(purpoid, new Vec3(randomX, randomY, randomZ), false);
					purpoid.getNavigation().stop();
					break;
				}
			}
			this.teleportToTargetTimer = 0;
		}
	}

public void aiStep() {
        super.aiStep();
        if (this.isBaby() && this.getEyeHeight() > this.getBbHeight()) {
            this.refreshDimensions();
        }
        prevLeftPitch = this.getEyePitch(true);
        prevRightPitch = this.getEyePitch(false);
        prevLeftYaw = this.getEyeYaw(true);
        prevRightYaw = this.getEyeYaw(false);
        prevInWaterProgress = this.inWaterProgress;
        prevPunchProgress = this.punchProgress;
        updateEyes();
        if (this.isSitting() && this.getNavigation().isDone()) {
            this.getNavigation().stop();
        }

        if (this.isInWater()) {
            if (inWaterProgress < 5F)
                inWaterProgress++;

            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (inWaterProgress > 0F)
                inWaterProgress--;

            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        if (this.entityData.get(PUNCH_TICK) > 0) {
            if (this.entityData.get(PUNCH_TICK) == 2 && this.getTarget() != null && this.distanceTo(this.getTarget()) < 2.8D) {
                if (this.getTarget() instanceof AbstractFish && !this.isTame()) {
                    AbstractFish fish = (AbstractFish) this.getTarget();
                    CompoundTag fishNbt = new CompoundTag();
                    fish.addAdditionalSaveData(fishNbt);
                    fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
                    fish.readAdditionalSaveData(fishNbt);
                }
                this.getTarget().knockback(1.7F, this.getX() - this.getTarget().getX(), this.getZ() - this.getTarget().getZ());
                float knockbackResist = (float) Mth.clamp((1.0D - this.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)), 0, 1);
                this.getTarget().setDeltaMovement(this.getTarget().getDeltaMovement().add(0, knockbackResist * 0.8F, 0));
                if (!this.getTarget().isInWater()) {
                    this.getTarget().setSecondsOnFire(2);
                }
                this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
            }
            if(punchProgress == 1){
                this.playSound(AMSoundRegistry.MANTIS_SHRIMP_SNAP.get(), this.getVoicePitch(), this.getSoundVolume());
            }
            if (punchProgress == 2 && this.level().isClientSide && this.isInWater()) {
                for (int i = 0; i < 10 + random.nextInt(8); i++) {
                    double d2 = this.random.nextGaussian() * 0.6D;
                    double d0 = this.random.nextGaussian() * 0.2D;
                    double d1 = this.random.nextGaussian() * 0.6D;
                    float radius = this.getBbWidth() * 0.85F;
                    float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                    double extraX = radius * Mth.sin(Mth.PI + angle) + random.nextFloat() * 0.5F - 0.25F;
                    double extraZ = radius * Mth.cos(angle) + random.nextFloat() * 0.5F - 0.25F;
                    ParticleOptions data = ParticleTypes.BUBBLE;
                    this.level().addParticle(data, this.getX() + extraX, this.getY() + this.getBbHeight() * 0.3F + random.nextFloat() * 0.15F, this.getZ() + extraZ, d0, d1, d2);
                }
            }
            if (punchProgress < 2F) {
                punchProgress++;
            }
            this.entityData.set(PUNCH_TICK, this.entityData.get(PUNCH_TICK) - 1);
        } else {
            if (punchProgress > 0F) {
                punchProgress -= 0.25F;
            }
        }
    }

@Override
    public void render(T blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        if (blockEntityIn.visualTransitionDuration != 0) {
            float timing = (blockEntityIn.getLevel().getGameTime() - blockEntityIn.visualStartTime) / (float) blockEntityIn.visualTransitionDuration;
            float delta = Mth.clampedLerp(blockEntityIn.visualTransitionStart, blockEntityIn.visualTransitionEnd, timing);
            float glow = Mth.clamp(getGlowDelta(blockEntityIn, delta), 0, 1);
            if (glow > 0) {
                float alpha = Easing.CUBIC_OUT.ease(glow) * 0.8f;
                float glowAlpha = Easing.SINE_OUT.ease(glow) * 0.4f;
                var cubeVertexData = CubeVertexData.makeCubePositions(1.002f);
                var builder = VFXBuilders.createWorld()
                        .setColor(COLOR);
                poseStack.pushPose();
                poseStack.translate(0.5f, 0.5f, 0.5f);
                BlockState state = blockEntityIn.getBlockState();
                for (int i = 0; i < 4; i++) {
                    var direction = Direction.from2DDataValue(i);
                    var token = getTokenForSide(state, direction);
                    var transparent = LodestoneRenderTypes.TRANSPARENT_TEXTURE.apply(token);
                    var additive = LodestoneRenderTypes.ADDITIVE_TEXTURE.apply(token);
                    builder.setAlpha(alpha).setRenderType(transparent).renderCubeSide(poseStack, cubeVertexData, direction);
                    builder.setAlpha(glowAlpha).setRenderType(additive).renderCubeSide(poseStack, cubeVertexData, direction);
                }
                poseStack.popPose();
            }
        }

        if (CLAW_TRACKER.isVisible()) {
            Minecraft minecraft = Minecraft.getInstance();
            var font = minecraft.font;
            float delta = CLAW_TRACKER.getDelta(partialTicks);
            float eased = Easing.SINE_IN_OUT.ease(delta);
            float scale = 0.016F - (1 - eased) * 0.004f;
            poseStack.pushPose();
            poseStack.translate(0.5f, 1.75f, 0.55f);
            poseStack.mulPose(minecraft.getEntityRenderDispatcher().cameraOrientation());
            poseStack.scale(scale, -scale, -scale);
            var base = Component.translatable(langKey).append(Component.translatable("malum.waveform_artifice.value_display", blockEntityIn.frequency, blockEntityIn.type.getText(blockEntityIn)));
            MutableComponent textComponent = base.copy().withStyle(ChatFormatting.RED);
            MutableComponent outlineComponent = base.withStyle(ChatFormatting.DARK_RED);

            float f = (-font.width(textComponent) / 2f);
            float xPos = 0 + f;
            Matrix4f pose = poseStack.last().pose();
            float alpha = 0.38f * eased; //We're rendering in additive, so whether we change alpha or the color it doesn't really matter.
            //Minecraft for whatever reason treats alpha values between 0-3 as 255 when rendering text, so we're going to modify color instead of alpha
            int color = ColorHelper.getColor(1, 1, 1, alpha);
            if (alpha > 0.02f) {
                renderText(textComponent, xPos, 0, color, pose);
            }
            alpha = 0.18f * eased;
            if (alpha > 0.02f) {
                color = ColorHelper.getColor(1, 1, 1, alpha);
                renderText(textComponent, xPos - 0.5f, 0, color, pose);
                renderText(textComponent, xPos - 0.5f, 0, color, pose);
                renderText(textComponent, xPos, 0.5f, color, pose);
                renderText(textComponent, xPos, -0.5f, color, pose);
            }
            alpha = 0.12f * eased;
            if (alpha > 0.02f) {
                color = ColorHelper.getColor(1, 1, 1, alpha);
                renderText(textComponent, xPos - 1, 0, color, pose);
                renderText(outlineComponent, xPos + 1, 0, color, pose);
                renderText(outlineComponent, xPos, 1, color, pose);
                renderText(textComponent, xPos, -1, color, pose);
                renderText(outlineComponent, xPos - 0.5f, -0.5f, color, pose);
                renderText(textComponent, xPos - 0.5f, 0.5f, color, pose);
                renderText(outlineComponent, xPos + 0.5f, 0.5f, color, pose);
                renderText(textComponent, xPos + 0.5f, -0.5f, color, pose);
            }
            poseStack.popPose();
        }
    }

public static void renderMalignantAegis(GuiGraphics guiGraphics, DeltaTracker deltaTracker) {
        var minecraft = Minecraft.getInstance();
        var poseStack = guiGraphics.pose();
        if (!minecraft.options.hideGui) {
            var player = minecraft.player;
            if (!player.isCreative() && !player.isSpectator()) {
                double capacity = MalignantInfluenceData.getMalignantAegisCapacity(player);
                if (displayedReinforcement > 0 && capacity > 0) {
                    float delta = (float) (displayedReinforcement / capacity);
                    float dissolvement = Easing.QUAD_OUT.ease(delta);
                    float alpha = (1 - fadeout / 80f) * 0.75f;
                    int left = guiGraphics.guiWidth() / 2 - ClientConfig.UI_SHIELD_X_OFFSET.getConfigValue();
                    int top = guiGraphics.guiHeight() - ClientConfig.UI_SHIELD_Y_OFFSET.getConfigValue();

                    poseStack.pushPose();
                    RenderSystem.depthMask(true);
                    RenderSystem.enableBlend();
                    RenderSystem.defaultBlendFunc();
                    var distorted = LodestoneShaders.SCREEN_DISTORTED_TEXTURE.getShaderInstance();
                    distorted.safeGetUniform("YFrequency").set(24f);
                    distorted.safeGetUniform("XFrequency").set(16f);
                    distorted.safeGetUniform("Speed").set(1000f);
                    distorted.safeGetUniform("Intensity").set(80f);
                    distorted.safeGetUniform("Width").set(64f);
                    distorted.safeGetUniform("Height").set(64f);

                    var builder = VFXBuilders.createScreen().setZLevel(100).setShader(distorted);
                    builder.setPositionWithWidth(left - 16, top - 16, 32, 32);
                    builder.setAlpha(alpha).setTexture(EMPTY).blit(poseStack);

                    var hud = MalumShaders.DISSOLVING_HUD_ELEMENT.getShaderInstance();
                    RenderSystem.setShaderTexture(1, DISSOLVEMENT);
                    hud.safeGetUniform("YFrequency").set(24f);
                    hud.safeGetUniform("XFrequency").set(16f);
                    hud.safeGetUniform("Speed").set(1000f);
                    hud.safeGetUniform("Intensity").set(80f);
                    hud.safeGetUniform("Dissolvement").set(dissolvement);
                    hud.safeGetUniform("Width").set(64f);
                    hud.safeGetUniform("Height").set(64f);

                    builder.setShader(hud).setTexture(REINFORCEMENT).blit(poseStack);
                    RenderSystem.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE);
                    builder.setAlpha(0.2f * alpha).blit(poseStack);
                    if (glow > 0 && glow < 80) {
                        float time = minecraft.level.getGameTime() + deltaTracker.getGameTimeDeltaPartialTick(true);
                        float glowAlpha = (40 - Math.abs(40 - glow)) / 40f;
                        int angle = Mth.floor((time * 20) % 360);
                        float range = Easing.SINE_IN_OUT.lerp(glowAlpha, 160f, 320f);
                        var light = LodestoneShaders.RADIAL_DISTORTED_SCREEN_LIGHT.getShaderInstance();
                        light.safeGetUniform("YFrequency").set(24f);
                        light.safeGetUniform("XFrequency").set(16f);
                        light.safeGetUniform("Speed").set(1000f);
                        light.safeGetUniform("Intensity").set(80f);
                        light.safeGetUniform("Width").set(64f);
                        light.safeGetUniform("Height").set(64f);
                        light.safeGetUniform("Angle").set(angle);
                        light.safeGetUniform("LightAngleRange").set(range);
                        RenderSystem.blendFunc(GL11.GL_SRC_ALPHA, GL11.GL_ONE);
                        builder.setShader(light).setAlpha(alpha);
                        if (displayedReinforcement >= capacity) {
                            builder.setTexture(REINFORCEMENT).blit(poseStack);
                        }
                        builder.setTexture(GLOW).blit(poseStack);
                        light.applyUniformDefaults();
                    }
                    distorted.applyUniformDefaults();
                    hud.applyUniformDefaults();
                    RenderSystem.defaultBlendFunc();
                    RenderSystem.disableBlend();
                    poseStack.popPose();
                }
            }
        }
    }

