public void tick() {
            LivingEntity target = EntityMimicOctopus.this.getTarget();
            if (target != null) {
                if (scareMobTime > 0) {
                    if (fleePosition == null || target.distanceToSqr(fleePosition) < target.getBbWidth() * target.getBbWidth() * 2) {
                        fleePosition = generateFleePosition(target);
                    }
                    if (target instanceof Mob) {
                        if (fleePosition != null) {
                            ((Mob) target).getNavigation().moveTo(fleePosition.x, fleePosition.y, fleePosition.z, 1.5F);
                            ((Mob) target).getMoveControl().setWantedPosition(fleePosition.x, fleePosition.y, fleePosition.z, 1.5F);
                            ((Mob) target).setTarget(null);
                        }
                    }
                    camoCooldown = Math.max(camoCooldown, 20);
                    stopMimicCooldown = Math.max(stopMimicCooldown, 20);
                    scareMobTime--;
                    if (scareMobTime == 0) {
                        stop();
                        return;
                    }
                }
                double dist = EntityMimicOctopus.this.distanceTo(target);
                boolean move = true;
                if (dist < 7F && EntityMimicOctopus.this.hasLineOfSight(target) && EntityMimicOctopus.this.getMimicState() == MimicState.GUARDIAN && EntityMimicOctopus.this.isUpgraded()) {
                    EntityMimicOctopus.this.entityData.set(UPGRADED_LASER_ENTITY_ID, target.getId());
                    move = false;
                }
                if (dist < 3) {
                    EntityMimicOctopus.this.entityData.set(LAST_SCARED_MOB_ID, target.getId());
                    if (move) {
                        move = EntityMimicOctopus.this.isUpgraded() && dist > 2;
                    }
                    EntityMimicOctopus.this.getNavigation().stop();
                    if (!EntityMimicOctopus.this.isStopChange()) {
                        EntityMimicOctopus.this.setMimickedBlock(null);
                        MimicState prev = EntityMimicOctopus.this.getMimicState();
                        if (EntityMimicOctopus.this.isInWaterOrBubble()) {
                            if (prev != MimicState.GUARDIAN && prev != MimicState.PUFFERFISH) {
                                if (random.nextBoolean()) {
                                    EntityMimicOctopus.this.setMimicState(MimicState.GUARDIAN);
                                } else {
                                    EntityMimicOctopus.this.setMimicState(MimicState.PUFFERFISH);
                                }
                            }
                        } else {
                            EntityMimicOctopus.this.setMimicState(MimicState.CREEPER);
                        }
                    }
                    if (EntityMimicOctopus.this.getMimicState() != MimicState.OVERLAY) {
                        EntityMimicOctopus.this.mimicCooldown = 40;
                        EntityMimicOctopus.this.stopMimicCooldown = Math.max(EntityMimicOctopus.this.stopMimicCooldown, 60);
                    }
                    if (EntityMimicOctopus.this.isUpgraded() && EntityMimicOctopus.this.transProgress >= 5.0F) {
                        if (EntityMimicOctopus.this.getMimicState() == MimicState.PUFFERFISH) {
                            if (EntityMimicOctopus.this.getBoundingBox().expandTowards(2, 1.3, 2).intersects(target.getBoundingBox())) {
                                target.hurt(EntityMimicOctopus.this.damageSources().mobAttack(EntityMimicOctopus.this), 4);
                                target.addEffect(new MobEffectInstance(MobEffects.POISON, 400, 2));
                            }
                        }
                        if (EntityMimicOctopus.this.getMimicState() == MimicState.GUARDIAN) {
                            if (EntityMimicOctopus.this.getBoundingBox().expandTowards(1, 1, 1).intersects(target.getBoundingBox())) {
                                target.hurt(EntityMimicOctopus.this.damageSources().mobAttack(EntityMimicOctopus.this), 1);
                            }
                            EntityMimicOctopus.this.entityData.set(UPGRADED_LASER_ENTITY_ID, target.getId());
                        }
                        if (EntityMimicOctopus.this.getMimicState() == MimicState.CREEPER) {
                            EntityMimicOctopus.this.creeperExplode();
                            EntityMimicOctopus.this.level().broadcastEntityEvent(EntityMimicOctopus.this, (byte) 69);
                            executionCooldown = 300;
                        }
                    }
                    if (scareMobTime == 0) {
                        EntityMimicOctopus.this.level().broadcastEntityEvent(EntityMimicOctopus.this, (byte) 68);
                        scareMobTime = 60 + random.nextInt(60);
                    }
                }
                if (move) {
                    EntityMimicOctopus.this.lookAt(target, 30, 30);
                    EntityMimicOctopus.this.getNavigation().moveTo(target, 1.2F);
                }
            }
        }

public boolean hurt(DamageSource pSource, float pAmount) {
        LivingEntity livingEntity = this.getTarget();
        if (!this.level.isClientSide) {
            if (livingEntity != null && pSource.getEntity() instanceof LivingEntity) {
                this.increaseHitTime();
            }
        }

        int smiteLevel = 0;
        if (pSource.getDirectEntity() instanceof LivingEntity living){
            int smite = EnchantmentHelper.getEnchantmentLevel(Enchantments.SMITE, living);
            if (smite > 0){
                int smite2 = Mth.clamp(smite, 1, 5);
                int duration = MathHelper.secondsToTicks(smite2);
                this.antiRegenTotal = duration;
                this.antiRegen = duration;
                smiteLevel = smite;
                if (this.level instanceof ServerLevel){
                    ModNetwork.sendToALL(new SApostleSmitePacket(this.getId(), duration));
                    if (this.getCoolDown() < this.coolDownLimit()){
                        this.coolDown += 10;
                    }
                }
            }
        }

        if (pSource.is(DamageTypes.FELL_OUT_OF_WORLD) && pSource.getEntity() == null){
            this.discard();
        }

        if (pSource.is(DamageTypes.LIGHTNING_BOLT) || pSource.is(DamageTypes.FALL) || pSource.is(DamageTypes.IN_WALL)){
            return false;
        }

        if (pSource.getDirectEntity() instanceof AbstractArrow && ((AbstractArrow) pSource.getDirectEntity()).getOwner() == this){
            return false;
        }

        if (this.isSettingUpSecond()){
            return false;
        }

        if (pSource.getDirectEntity() instanceof NetherMeteor || pSource.getEntity() instanceof NetherMeteor){
            return false;
        }

        if (this.moddedInvul > 0 || this.obsidianInvul > 0){
            return false;
        }

        float trueAmount = this.isInNether() ? pAmount * (1.0F - (MobsConfig.ApostleNetherDamageReduction.get() / 100.0F)) : pAmount;

        if (!this.isNoAi()) {
            if (this.getHealth() > trueAmount) {
                if (this.getHitTimes() >= this.hitTimeTeleport()) {
                    this.teleport();
                } else if (pSource.getEntity() == null) {
                    if (this.level.getRandom().nextBoolean()) {
                        this.teleport();
                    }
                }
            }
        }

        if (!this.level.getNearbyPlayers(TargetingConditions.forCombat().selector(MobUtil.NO_CREATIVE_OR_SPECTATOR), this, this.getBoundingBox().inflate(32)).isEmpty()){
            if (!(pSource.getEntity() instanceof Player)){
                trueAmount = trueAmount / 2;
            }
        }

        if (smiteLevel > 0) {
            if (MobsConfig.ApostleSmiteDamageReduction.get() > 0) {
                float reduce = 1.0F - (MobsConfig.ApostleSmiteDamageReduction.get() / 100.0F);
                trueAmount *= reduce;
            }
        }

        if (this.isDeadOrDying()) {
            this.deathBlow = pSource;
        }

        return super.hurt(pSource, trueAmount);
    }

private void doTick(Level level, BlockPos pos, BlockState blockState) {
		if (!(blockState.getBlock() instanceof HenostoneFireSpitterBlock fireSpitter)) return;

		Direction dir = fireSpitter.getDirection(blockState);

		rangeLen = raycastRange(level, pos, dir, 8.0);

		AABB detectionAABB = buildAABB(pos, dir, rangeLen);

		switch (state) {

		case IDLE -> {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			if (!entities.isEmpty()) {
				boolean hasValidTarget = entities.stream().anyMatch(e ->
				!(e instanceof Player player && player.isCreative()));
				if (hasValidTarget) {
					transitionTo(FireState.WARNING_1, level, pos);
				}
			}
			setPowered(level, pos, blockState, false);
		}

		case WARNING_1 -> {
			timer++;
			if (timer == WARNING_1_TICKS + 1) {
				playWarningSound(level, pos);
			}
			if (timer >= WARNING_2_TICKS) {
				transitionTo(FireState.WARNING_2, level, pos);
			}
		}

		case WARNING_2 -> {
			timer++;
			if (timer == WARNING_1_TICKS + 1) {
				playWarningSound(level, pos);
			}
			if (timer >= WARNING_2_TICKS) {
				transitionTo(FireState.WARNING_3, level, pos);
			}
		}

		case WARNING_3 -> {
			timer++;
			if (timer == WARNING_3A_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer == WARNING_3B_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer == WARNING_3C_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer >= FIRE_START_TICKS - WARNING_3A_TICKS) {
				transitionTo(FireState.FIRING, level, pos);
			}
		}

		case FIRING -> {
			timer++;
			setPowered(level, pos, blockState, true);

			List<LivingEntity> targets = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			double ox = pos.getX() + 0.5;
			double oy = pos.getY() + 0.5;
			double oz = pos.getZ() + 0.5;
			level.addParticle(ParticleTypes.FLAME, ox, oy, oz, dir.getStepX() * 0.5, 0, dir.getStepZ() * 0.5);
			for (LivingEntity entity : targets) {
				if (!entity.fireImmune()) {
					entity.setSecondsOnFire(8);
					entity.hurt(level.damageSources().inFire(), 1);
				}
			}

			if (timer >= FIRE_END_TICKS - FIRE_START_TICKS) {
				transitionTo(FireState.COOLDOWN, level, pos);
			}
		}

		case COOLDOWN -> {
			timer++;
			setPowered(level, pos, blockState, false);
			if (timer >= COOLDOWN_TICKS) {
				transitionTo(FireState.IDLE, level, pos);
			}
		}
		}
	}

@Override
	public void onUpdate(){

		super.onUpdate();

//		if(this.ticksExisted % 20 == 1 && !this.onGround && world.isRemote){
//			// Though this sound does repeat, it stops when it hits the ground.
//			Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_HAMMER_FALLING, WizardrySounds.SPELLS, 3.0f, 1.0f, false);
//		}

		if(this.world.isRemote && this.ticksExisted % 3 == 0){
			ParticleBuilder.create(Type.SPARK)
					.pos(this.posX - 0.5d + rand.nextDouble(), this.posY + 2 * rand.nextDouble(), this.posZ - 0.5d + rand.nextDouble())
					.spawn(world);
		}

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;
		++this.fallTime;
		this.motionY -= 0.03999999910593033D;
		this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
		this.motionX *= 0.9800000190734863D;
		this.motionY *= 0.9800000190734863D;
		this.motionZ *= 0.9800000190734863D;

		if(this.onGround){

			this.motionX *= 0.699999988079071D;
			this.motionZ *= 0.699999988079071D;
			this.motionY *= -0.5D;

			this.rotationPitch = 0;
			this.spin = false;

			double seekerRange = Spells.lightning_hammer.getProperty(Spell.EFFECT_RADIUS).doubleValue();

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX,
					this.posY + 1, this.posZ, world);

			int maxTargets = Spells.lightning_hammer.getProperty(LightningHammer.SECONDARY_MAX_TARGETS).intValue();
			while(targets.size() > maxTargets) targets.remove(targets.size() - 1);

			for(EntityLivingBase target : targets){

				if(EntityUtils.isLiving(target) && this.isValidTarget(target)
						&& target.ticksExisted % Spells.lightning_hammer.getProperty(LightningHammer.ATTACK_INTERVAL).floatValue() == 0){

					if(world.isRemote){

						ParticleBuilder.create(Type.LIGHTNING).pos(posX, posY + height - 0.1, posZ) .target(target).spawn(world);

						ParticleBuilder.spawnShockParticles(world, target.posX,
								target.posY + target.height, target.posZ);
					}

					target.playSound(WizardrySounds.ENTITY_HAMMER_ATTACK, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					float damage = Spells.lightning_hammer.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier;

					if(this.getCaster() != null){
						EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(
								this, getCaster(), DamageType.SHOCK), damage);
						EntityUtils.applyStandardKnockback(this, target);
					}else{
						target.attackEntityFrom(DamageSource.MAGIC, damage);
					}
				}
			}

		}else{

			if(spin) this.setRotation(this.rotationYaw, this.rotationPitch + 15);

			List<Entity> collided = world.getEntitiesInAABBexcluding(this, this.getCollisionBoundingBox(), e -> e instanceof EntityLivingBase);

			float damage = Spells.lightning_hammer.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

			for(Entity entity : collided){
				entity.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.SHOCK), damage);
				//if(entity instanceof EntityLivingBase) ((EntityLivingBase)entity).knockBack(this, 2, -this.motionX, -this.motionZ);
			}
		}
	}

@SubscribeEvent
    public static void HurtEvent(LivingHurtEvent event){
        LivingEntity victim = event.getEntity();
        Entity directEntity = event.getSource().getDirectEntity();
        if (event.getAmount() > 0.0F) {
            if (directEntity instanceof LivingEntity livingAttacker) {
                ItemStack itemStack = livingAttacker.getMainHandItem();
                if (ModDamageSource.physicalAttacks(event.getSource())) {
                    ItemHelper.setItemEffect(itemStack, victim);
                    if (itemStack.getItem() instanceof TieredItem weapon) {
                        if (weapon == ModItems.FANGED_DAGGER.get()){
                            MobEffect effect = MobEffects.POISON;
                            if (CuriosFinder.hasWildRobe(livingAttacker)){
                                effect = GoetyEffects.ACID_VENOM.get();
                            }
                            if (livingAttacker.hasEffect(GoetyEffects.VENOMOUS_HANDS.get())){
                                EffectsUtil.increaseDuration(victim, effect, 600);
                            } else {
                                victim.addEffect(new MobEffectInstance(effect, 200));
                            }
                        }
                        if (weapon == ModItems.FROZEN_BLADE.get()) {
                            if (victim.getType().is(EntityTypeTags.FREEZE_HURTS_EXTRA_TYPES)) {
                                event.setAmount(event.getAmount() * 2);
                            }
                        }
                        if (weapon == ModItems.HUNGRY_DAGGER.get()){
                            int soulEat = EnchantmentHelper.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get(), livingAttacker) + 1;
                            livingAttacker.heal(event.getAmount() * (0.05F * soulEat));
                        }
                        if (weapon instanceof DarkScytheItem) {
                            victim.playSound(ModSounds.SCYTHE_HIT_MEATY.get());
                        }
                        if (weapon instanceof DeathScytheItem) {
                            if (ItemConfig.DeathScytheSappedDuration.get() > 0) {
                                int seconds = MathHelper.secondsToTicks(ItemConfig.DeathScytheSappedDuration.get());
                                if (!victim.hasEffect(GoetyEffects.SAPPED.get())) {
                                    victim.addEffect(new MobEffectInstance(GoetyEffects.SAPPED.get(), seconds));
                                    victim.playSound(SoundEvents.SHIELD_BREAK, 2.0F, 1.0F);
                                } else {
                                    if (ItemConfig.DeathScytheSappedChance.get() > 0 && victim.level.random.nextFloat() <= (ItemConfig.DeathScytheSappedChance.get() / 100.0F)) {
                                        EffectsUtil.amplifyEffect(victim, GoetyEffects.SAPPED.get(), seconds);
                                        victim.playSound(SoundEvents.SHIELD_BREAK, 2.0F, 1.0F);
                                    } else {
                                        EffectsUtil.resetDuration(victim, GoetyEffects.SAPPED.get(), seconds);
                                    }
                                }
                            }
                        }
                    }
                    if (itemStack.is(ModTags.Items.SOUL_TAKING)) {
                        if (livingAttacker instanceof Player player) {
                            boolean giveSoul = false;
                            if (victim instanceof OwnableEntity owned){
                                if (owned.getOwner() != player){
                                    giveSoul = true;
                                }
                            } else {
                                giveSoul = true;
                            }
                            if (giveSoul) {
                                int enchantment = itemStack.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get());
                                int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                if (SEHelper.getSoulGiven(victim) > 0) {
                                    SEHelper.increaseSouls(player, ItemConfig.DarkScytheSouls.get() * soulEater);
                                }
                            }
                        }
                    }
                }
            }
        }
        if (victim instanceof Player player) {
            if (CuriosFinder.hasCurio(victim, ModItems.SPITEFUL_BELT.get())) {
                int a = EnchantmentHelper.getTagEnchantmentLevel(Enchantments.THORNS, CuriosFinder.findCurio(victim, ModItems.SPITEFUL_BELT.get()));
                if (SEHelper.getSoulsAmount(player, ItemConfig.SpitefulBeltUseAmount.get() * (a + 1))) {
                    if (!event.getSource().is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !event.getSource().is(DamageTypes.THORNS) && event.getSource().getEntity() instanceof LivingEntity livingentity && livingentity != victim) {
                        livingentity.hurt(livingentity.damageSources().thorns(victim), 2.0F + a);
                        SEHelper.decreaseSouls(player, ItemConfig.SpitefulBeltUseAmount.get() * (a + 1));
                    }
                }
            }
        }
    }

public void tick() {
        super.tick();
        this.prevStandProgress = this.standProgress;
        this.prevBegProgress = this.begProgress;
        this.prevWashProgress = this.washProgress;
        this.prevSitProgress = this.sitProgress;

        if (this.isStanding()) {
            if (standProgress < 5F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        if (this.isBegging()) {
            if (begProgress < 5F)
                begProgress++;
        } else {
            if (begProgress > 0F)
                begProgress--;
        }

        if (this.isWashing()) {
            if (washProgress < 5F)
                washProgress++;
        } else {
            if (washProgress > 0F)
                washProgress--;
        }

        if (this.isSitting()) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }
        if (!this.level().isClientSide) {
            if (lookForWaterBeforeEatingTimer > 0) {
                lookForWaterBeforeEatingTimer--;
            } else if (!isWashing() && canTargetItem(this.getMainHandItem())) {
                onEatItem();
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.getMainHandItem().shrink(1);
            }
        }
        if (isWashing()) {
            if (getWashPos() != null) {
                BlockPos washingPos = getWashPos();
                if (this.distanceToSqr(washingPos.getX() + 0.5D, washingPos.getY() + 0.5D, washingPos.getZ() + 0.5D) < 3) {
                    for (int j = 0; (float) j < 4; ++j) {
                        double d2 = (this.random.nextDouble());
                        double d3 = (this.random.nextDouble());
                        Vec3 vector3d = this.getDeltaMovement();

                        this.level().addParticle(ParticleTypes.SPLASH, washingPos.getX() + d2, (double) (washingPos.getY() + 0.8F), washingPos.getZ() + d3, vector3d.x, vector3d.y, vector3d.z);
                    }
                } else {
                    setWashing(false);
                }
            }
        }
        if (!this.level().isClientSide && this.getTarget() != null && this.hasLineOfSight(this.getTarget()) && this.distanceTo(this.getTarget()) < 4 && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 5) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add((double) (-Mth.sin(f1) * -0.06F), 0.0D, (double) (Mth.cos(f1) * -0.06F)));
            this.getTarget().knockback(0.35F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        if (stealCooldown > 0) {
            stealCooldown--;
        }
        if (pickupItemCooldown > 0) {
            pickupItemCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

