private void shootPaintBalls(AEColor color, boolean lit, Level level, @Nullable Player p, Vec3 Vector3d,
            Vec3 Vector3d1, Vec3 direction, double d0, double d1, double d2) {
        final AABB bb = new AABB(Math.min(Vector3d.x, Vector3d1.x), Math.min(Vector3d.y, Vector3d1.y),
                Math.min(Vector3d.z, Vector3d1.z), Math.max(Vector3d.x, Vector3d1.x), Math.max(Vector3d.y, Vector3d1.y),
                Math.max(Vector3d.z, Vector3d1.z)).inflate(16, 16, 16);

        Entity entity = null;
        Vec3 entityIntersection = null;
        final List<Entity> list = level.getEntities(p, bb,
                e -> !(e instanceof ItemEntity) && e.isAlive());
        double closest = 9999999.0D;

        for (Entity entity1 : list) {
            if (p.isPassenger() && entity1.hasPassenger(p)) {
                continue;
            }

            final float f1 = 0.3F;

            final AABB boundingBox = entity1.getBoundingBox().inflate(f1, f1, f1);
            final Vec3 intersection = boundingBox.clip(Vector3d, Vector3d1).orElse(null);

            if (intersection != null) {
                final double nd = Vector3d.distanceToSqr(intersection);

                if (nd < closest) {
                    entity = entity1;
                    entityIntersection = intersection;
                    closest = nd;
                }
            }
        }

        ClipContext rayTraceContext = new ClipContext(Vector3d, Vector3d1, Block.COLLIDER,
                Fluid.NONE, p);
        HitResult pos = level.clip(rayTraceContext);

        final Vec3 vec = new Vec3(d0, d1, d2);
        if (entity != null && pos.getType() != Type.MISS
                && pos.getLocation().distanceToSqr(vec) > closest) {
            pos = new EntityHitResult(entity, entityIntersection);
        } else if (entity != null && pos.getType() == Type.MISS) {
            pos = new EntityHitResult(entity, entityIntersection);
        }

        AppEng.instance().sendToAllNearExcept(null, d0, d1, d2, 256, level,
                new MatterCannonPacket(d0, d1, d2, (float) direction.x, (float) direction.y, (float) direction.z,
                        (byte) (pos.getType() == Type.MISS ? 32
                                : pos.getLocation().distanceToSqr(vec) + 1)));

        if (pos.getType() != Type.MISS) {
            if (pos instanceof EntityHitResult entityResult) {
                var entityHit = entityResult.getEntity();

                if (entityHit instanceof Sheep sh) {
                    sh.setColor(color.dye);
                }

                entityHit.hurt(level.damageSources().playerAttack(p), 0);
            } else if (pos instanceof BlockHitResult blockResult) {
                final Direction side = blockResult.getDirection();
                final BlockPos hitPos = blockResult.getBlockPos().relative(side);

                if (!Platform.hasPermissions(new DimensionalBlockPos(level, hitPos), p)) {
                    return;
                }

                if (EventHooks.onBlockPlace(p, BlockSnapshot.create(p.level().dimension(), level, hitPos),
                        blockResult.getDirection())) {
                    return;
                }

                final BlockState whatsThere = level.getBlockState(hitPos);
                if (whatsThere.canBeReplaced() && level.isEmptyBlock(hitPos)) {
                    level.setBlock(hitPos, AEBlocks.PAINT.block().defaultBlockState(), 3);
                }

                final BlockEntity te = level.getBlockEntity(hitPos);
                if (te instanceof PaintSplotchesBlockEntity) {
                    final Vec3 hp = pos.getLocation().subtract(hitPos.getX(), hitPos.getY(), hitPos.getZ());
                    ((PaintSplotchesBlockEntity) te).addBlot(color, lit, side.getOpposite(), hp);
                }
            }
        }
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        Entity entity = source.getDirectEntity();
        LivingEntity target = this.getTarget();
        double range = calculateRange(source);

        if (entity != null && !isNoAi() && (blockingProgress == 10 || swordProgress == 10)) {
            if (target != null && target.isAlive()) {
                if (this.getAnimation() == NO_ANIMATION) {
                    if (this.getRandom().nextFloat() * 100.0F < 12f && counter_strike_cooldown <= 0 && range < 225) {
                        counter_strike_cooldown = CONTER_STRIKE_COOLDOWN;
                        Animation counter = this.getIsShieldBreak() ? SHIELD_BREAK_COUNTER : COUNTER;
                        this.setAnimation(counter);
                    }
                }
            }
            if (this.getAnimation() == COUNTER) {
                if (this.getAnimationTick() > 16 && this.getAnimationTick() <= 46) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, STRIKE);
                    this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
                    if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                        return false;
                    }
                }
            }
            if (this.getAnimation() == SHIELD_BREAK_COUNTER) {
                if (this.getAnimationTick() > 8 && this.getAnimationTick() <= 38) {
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, SHIELD_BREAK_STRIKE);
                    this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
                    if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
                        return false;
                    }
                }
            }
        }

        if (source.getDirectEntity() instanceof Ignis_Abyss_Fireball_Entity) {
            if (!(source.getEntity() instanceof Ignis_Entity)) {
                if (source.is(DamageTypeTags.IS_PROJECTILE)) {
                    if (this.getShieldDurability() < 3) {
                        this.playSound(ModSounds.IGNIS_ARMOR_BREAK.get(), 1.0F, 0.8F);
                        if (!level().isClientSide) {
                            this.setShieldDurability(this.getShieldDurability() + 1);
                        }
                    }
                }
            } else {
                return false;
            }
        }


        if ((this.getAnimation() == ULTIMATE_ATTACK || this.getBossPhase() == 1 && this.getHealth() <= this.getMaxHealth() * 1 / 3 || this.getBossPhase() == 0 && this.getHealth() <= this.getMaxHealth() * 2 / 3) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            damage *= 0.5;
        }

        if ((this.getAnimation() == PHASE_3 || this.getAnimation() == PHASE_2 || this.getAnimation() == STRIKE) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }
        if (source.getDirectEntity() instanceof Ignis_Fireball_Entity) {
            return false;
        }
        if (damage > 0.0F && this.canBlockDamageSource(source)) {
            this.hurtCurrentlyUsedShield(damage);
            if (!source.is(DamageTypeTags.IS_PROJECTILE)) {
                if (entity instanceof LivingEntity) {
                    this.blockUsingShield((LivingEntity) entity);
                }
            }
            this.playSound(SoundEvents.BLAZE_HURT, 0.5f, 0.4F + this.getRandom().nextFloat() * 0.1F);
            return false;
        }

        if (this.destroyBlocksTick <= 0) {
            this.destroyBlocksTick = 20;
        }

        Crackiness irongolem$crackiness = this.getCrackiness();
        boolean attack = super.hurt(source, damage);
        if (attack && this.getCrackiness() != irongolem$crackiness) {
            this.playSound(ModSounds.IGNIS_ARMOR_BREAK.get(), 1.0f, 0.8f);
        }

        return attack;
    }

@Override
    public void tick() {
        super.tick();

        var level = getCommandSenderWorld();

        var particleCenter = this.position().add(this.getDeltaMovement().scale(-1F));

        for (int i = 0; i < 5; i++)
            level.addParticle(ParticleUtils.constructSimpleSpark(new Color(50 + random.nextInt(100), 0, 150 + random.nextInt(100)), 0.1F + random.nextFloat() * 0.15F, 5 + random.nextInt(10), 0.85F),
                    particleCenter.x() + MathUtils.randomFloat(random) * 0.25F, particleCenter.y(), particleCenter.z() + MathUtils.randomFloat(random) * 0.25F, 0F, 0F, 0F);

        var currentTarget = getTarget();

        if (currentTarget != null && (this.position().distanceTo(currentTarget.position()) >= 16F || currentTarget.isDeadOrDying()))
            currentTarget = null;

        if (!level.isClientSide()) {
            LivingEntity potentialTarget = null;

            var candidateEntities = locateNearestTargets();

            candidateEntities.removeIf(entity -> blacklistedTargets.contains(entity.getStringUUID()));

            var targetEntities = candidateEntities.stream()
                    .filter(entity -> {
                        var uuid = entity.getStringUUID();

                        return !bouncedTargets.contains(uuid) && !blacklistedTargets.contains(uuid);
                    })
                    .toList();

            if (!targetEntities.isEmpty())
                potentialTarget = targetEntities.getFirst();
            else if (!candidateEntities.isEmpty()) {
                bouncedTargets.clear();

                potentialTarget = candidateEntities.getFirst();
            }

            if (potentialTarget != null && (currentTarget == null || !currentTarget.getStringUUID().equals(potentialTarget.getStringUUID()))) {
                NetworkHandler.sendToClientsTrackingEntity(new S2CSyncEntityTargetPacket(this.getId(), potentialTarget.getId()), this);

                setTarget(potentialTarget);

                currentTarget = potentialTarget;
            }
        }

        if (currentTarget == null || currentTarget.isDeadOrDying() || this.tickCount >= 250 || getBounces() >= getMaxBounces()) {
            if (!level.isClientSide())
                this.discard();

            return;
        }

        if (this.getEyePosition().distanceTo(currentTarget.getEyePosition()) <= 1.5F) {
            currentTarget.invulnerableTime = 0;

            if (currentTarget.hurt(level.damageSources().thrown(this, getOwner()), getDamage())) {
                bouncedTargets.add(currentTarget.getStringUUID());
                lastTarget = currentTarget;

                setTarget(null);
                addBounces(1);

                if (random.nextDouble() <= getChance()) {
                    var entity = new ShadowGlaiveEntity(RelicsEntities.SHADOW_GLAIVE.get(), level);

                    entity.setMaxBounces(getMaxBounces());
                    entity.setBounces(getBounces());
                    entity.setPos(getEyePosition());
                    entity.setDamage(getDamage());
                    entity.setOwner(getOwner());

                    level.addFreshEntity(entity);
                }
            } else {
                blacklistedTargets.add(currentTarget.getStringUUID());

                setTarget(null);
            }
        } else {
            this.setDeltaMovement(currentTarget.getEyePosition().subtract(this.getEyePosition()).normalize());
        }
    }

public void rideTick() {
        Entity entity = this.getVehicle();
        if (this.isPassenger() && !entity.isAlive()) {
            this.stopRiding();
        } else {
            this.setDeltaMovement(0, 0, 0);
            this.tick();
            if (this.isPassenger()) {
                attachTime++;
                Entity mount = this.getVehicle();
                if (mount instanceof LivingEntity) {
                    passengerIndex = mount.getPassengers().indexOf(this);
                    this.yBodyRot = ((LivingEntity) mount).yBodyRot;
                    this.setYRot( ((LivingEntity) mount).getYRot());
                    this.yHeadRot = ((LivingEntity) mount).yHeadRot;
                    this.yRotO = ((LivingEntity) mount).yHeadRot;
                    float radius = mount.getBbWidth();
                    float angle = (Maths.STARTING_ANGLE * (((LivingEntity) mount).yBodyRot + passengerIndex * 90F));
                    double extraX = radius * Mth.sin(Mth.PI + angle);
                    double extraZ = radius * Mth.cos(angle);
                    this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                    if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                        this.removeVehicle();
                    }
                    this.setPhagePitch(0F);
                    if (!this.level().isClientSide && attachTime > 15) {
                        LivingEntity target = (LivingEntity) mount;
                        float dmg = 1F;
                        if (target.getHealth() > target.getMaxHealth() * 0.2F) {
                            dmg = 6F;
                        }
                        if ((target.getHealth() < 1.5D || mount.hurt(this.damageSources().mobAttack(this), dmg)) && mount instanceof LivingEntity) {
                            dismountCooldown = 100;
                            if (mount instanceof EnderMan) {
                                this.setMissingEye(false);
                                this.gameEvent(GameEvent.EAT);
                                this.playSound(SoundEvents.ENDER_EYE_DEATH, this.getSoundVolume(), this.getVoicePitch());
                                this.heal(5);
                                ((EnderMan) mount).addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 400));
                                this.fleeAfterStealTime = 400;
                                this.setFlying(true);
                                this.angryEnderman = (PathfinderMob) mount;
                            } else {
                                if (random.nextInt(3) == 0) {
                                    if (!this.isMissingEye()) {
                                        if (target.getEffect(AMEffectRegistry.ENDER_FLU.get()) == null) {
                                            target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), 12000));
                                        } else {
                                            MobEffectInstance inst = target.getEffect(AMEffectRegistry.ENDER_FLU.get());
                                            int duration = 12000;
                                            int level = 0;
                                            if (inst != null) {
                                                duration = inst.getDuration();
                                                level = inst.getAmplifier();
                                            }
                                            target.removeEffect(AMEffectRegistry.ENDER_FLU.get());
                                            target.addEffect(new MobEffectInstance(AMEffectRegistry.ENDER_FLU.get(), duration, Math.min(level + 1, 4)));
                                        }
                                        this.heal(5);
                                        this.gameEvent(GameEvent.ENTITY_ROAR);
                                        this.playSound(SoundEvents.ITEM_BREAK, this.getSoundVolume(), this.getVoicePitch());
                                        this.setMissingEye(true);
                                    }
                                    if (!this.level().isClientSide) {
                                        this.setTarget(null);
                                        this.setLastHurtMob(null);
                                        this.setLastHurtByMob(null);
                                        this.goalSelector.getRunningGoals().forEach(Goal::stop);
                                        this.targetSelector.getRunningGoals().forEach(Goal::stop);
                                    }
                                }
                            }
                        }
                        if (((LivingEntity) mount).getHealth() <= 0 || this.fleeAfterStealTime > 0 || this.isMissingEye() && !(mount instanceof EnderMan) || !this.isMissingEye() && mount instanceof EnderMan) {
                            this.removeVehicle();
                            this.setTarget(null);
                            dismountCooldown = 100;
                            AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                            this.setFlying(true);
                        }
                    }
                }

            }
        }

    }

public void tick() {
        super.tick();
        prevFlyRightProgress = flyRightProgress;
        prevLeftFlyProgress = flyLeftProgress;
        final boolean dashRight = isDashRight();
        final boolean flying = isFlying();
        if (flying && dashRight && flyRightProgress < 5F) {
            flyRightProgress++;
        }
        if ((!flying || !dashRight) && flyRightProgress > 0F) {
            flyRightProgress--;
        }
        if (flying && !dashRight && flyLeftProgress < 5F) {
            flyLeftProgress++;
        }
        if ((!flying || dashRight) && flyLeftProgress > 0F) {
            flyLeftProgress--;
        }
        if (!this.level().isClientSide) {
            if (flying) {
                if (this.isLandNavigator)
                    switchNavigator(false);
            } else {
                if (!this.isLandNavigator)
                    switchNavigator(true);
            }
        }
        if (flying) {
            if (loopSoundTick == 0) {
                this.playSound(AMSoundRegistry.MOSQUITO_LOOP.get(), this.getSoundVolume(), this.getVoicePitch() * 0.3F);
            }
            loopSoundTick++;
            if (loopSoundTick > 100) {
                loopSoundTick = 0;
            }
            timeFlying++;
            this.setNoGravity(true);
            if (this.isPassenger() || this.isVehicle()) {
                this.setFlying(false);
            }
        } else {
            timeFlying = 0;
            this.setNoGravity(false);
        }
        if (this.horizontalCollision && net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
            boolean flag = false;
            AABB axisalignedbb = this.getBoundingBox().inflate(0.2D);
            for (BlockPos blockpos : BlockPos.betweenClosed(Mth.floor(axisalignedbb.minX), Mth.floor(axisalignedbb.minY), Mth.floor(axisalignedbb.minZ), Mth.floor(axisalignedbb.maxX), Mth.floor(axisalignedbb.maxY), Mth.floor(axisalignedbb.maxZ))) {
                BlockState blockstate = this.level().getBlockState(blockpos);
                if (blockstate.is(AMTagRegistry.WARPED_MOSCO_BREAKABLES)) {
                    flag = this.level().destroyBlock(blockpos, true, this) || flag;
                }
            }
            if (!flag && this.onGround()) {
                this.jumpFromGround();
            }
        }

        LivingEntity target = this.getTarget();
        if (target != null && this.isAlive()) {
            if (this.getAnimation() == ANIMATION_SUCK && this.getAnimationTick() == 3 && this.distanceTo(target) < 4.7F) {
                target.startRiding(this, true);
            }
            if (this.getAnimation() == ANIMATION_SLAM) {
                if (this.getAnimationTick() == 19) {
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(5.0D))) {
                        if (!isAlliedTo(entity) && !(entity instanceof EntityWarpedMosco) && entity != this) {
                            entity.hurt(this.damageSources().mobAttack(this), 10.0F + random.nextFloat() * 8.0F);
                            launch(entity, true);
                        }
                    }

                }
            }
            if ((this.getAnimation() == ANIMATION_PUNCH_R || this.getAnimation() == ANIMATION_PUNCH_L) && this.getAnimationTick() == 13) {
                if (this.distanceTo(target) < 4.7F) {
                    target.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackRidiculous(target, 0.9F);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_SLAM && this.getAnimationTick() == 19) {
            spawnGroundEffects();
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

private boolean doCasting(World world, EntityLivingBase caster, SpellModifiers modifiers){

		if(world.canBlockSeeSky(new BlockPos(caster))){

			double maxRadius = getProperty(EFFECT_RADIUS).doubleValue();

			for(int i = 0; i < getProperty(LIGHTNING_BOLTS).intValue(); i++){

				double radius = maxRadius * CENTRE_RADIUS_FRACTION + world.rand.nextDouble() * maxRadius
						* (1 - CENTRE_RADIUS_FRACTION) * modifiers.get(WizardryItems.blast_upgrade);
				float angle = world.rand.nextFloat() * (float)Math.PI * 2;

				double x = caster.posX + radius * MathHelper.cos(angle);
				double z = caster.posZ + radius * MathHelper.sin(angle);
				Integer y = BlockUtils.getNearestFloor(world, new BlockPos(x, caster.posY, z), (int)maxRadius);

				if(y != null){

					if(!world.isRemote){
						EntityLightningBolt lightning = new EntityLightningBolt(world, x, y, z, false);
						lightning.getEntityData().setUniqueId(LightningBolt.SUMMONER_NBT_KEY, caster.getUniqueID());
						lightning.getEntityData().setFloat(LightningBolt.DAMAGE_MODIFIER_NBT_KEY, modifiers.get(SpellModifiers.POTENCY));
						world.addWeatherEffect(lightning);
					}

					// Secondary chaining effect
					List<EntityLivingBase> secondaryTargets = EntityUtils.getLivingWithinRadius(
							getProperty(SECONDARY_RANGE).doubleValue(), x, y + 1, z, world);

					for(int j = 0; j < Math.min(secondaryTargets.size(), getProperty(SECONDARY_MAX_TARGETS).intValue()); j++){

						EntityLivingBase secondaryTarget = secondaryTargets.get(j);

						if(AllyDesignationSystem.isValidTarget(caster, secondaryTarget)){

							if(world.isRemote){

								ParticleBuilder.create(Type.LIGHTNING).pos(x, y, z).target(secondaryTarget).spawn(world);

								ParticleBuilder.spawnShockParticles(world, secondaryTarget.posX,
										secondaryTarget.posY + secondaryTarget.height / 2,
										secondaryTarget.posZ);
							}

							playSound(world, secondaryTarget, 0, -1, modifiers);

							secondaryTarget.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
									getProperty(SECONDARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

							// Tertiary chaining effect

							List<EntityLivingBase> tertiaryTargets = EntityUtils.getLivingWithinRadius(
									getProperty(TERTIARY_RANGE).doubleValue(), secondaryTarget.posX,
									secondaryTarget.posY + secondaryTarget.height / 2, secondaryTarget.posZ, world);

							for(int k = 0; k < Math.min(tertiaryTargets.size(), getProperty(TERTIARY_MAX_TARGETS).intValue()); k++){

								EntityLivingBase tertiaryTarget = tertiaryTargets.get(k);

								if(!secondaryTargets.contains(tertiaryTarget)
										&& AllyDesignationSystem.isValidTarget(caster, tertiaryTarget)){

									if(world.isRemote){
										ParticleBuilder.create(Type.LIGHTNING).entity(secondaryTarget)
												.pos(0, secondaryTarget.height / 2, 0).target(tertiaryTarget).spawn(world);
										ParticleBuilder.spawnShockParticles(world, tertiaryTarget.posX,
												tertiaryTarget.posY + tertiaryTarget.height / 2,
												tertiaryTarget.posZ);
									}

									playSound(world, tertiaryTarget, 0, -1, modifiers);

									tertiaryTarget.attackEntityFrom(
											MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
											getProperty(TERTIARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));
								}
							}
						}
					}
				}
			}

			return true;
		}

		return false;
	}

@Override
    public void tick() {
        super.tick();
        this.prevAttachChangeProgress = this.attachChangeProgress;
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (attachChangeProgress > 0F) {
            attachChangeProgress -= 0.25F;
        }
        Vec3 Vec3 = this.getDeltaMovement();
        if (!this.level().isClientSide) {
            this.setBesideClimbableBlock(this.horizontalCollision || this.verticalCollision && !this.onGround());
            if (this.onGround() || this.isInWaterOrBubble() || this.isInLava()) {
                this.entityData.set(ATTACHED_FACE, Direction.DOWN);
            } else if (this.verticalCollision) {
                this.entityData.set(ATTACHED_FACE, Direction.UP);
            } else {
                Direction closestDirection = Direction.DOWN;
                double closestDistance = 100;
                for (Direction dir : HORIZONTALS) {
                    BlockPos antPos = new BlockPos(Mth.floor(this.getX()), Mth.floor(this.getY()), Mth.floor(this.getZ()));
                    BlockPos offsetPos = antPos.relative(dir);
                    Vec3 offset = Vec3.atCenterOf(offsetPos);
                    if (closestDistance > this.position().distanceTo(offset) && level().loadedAndEntityCanStandOnFace(offsetPos, this, dir.getOpposite())) {
                        closestDistance = this.position().distanceTo(offset);
                        closestDirection = dir;
                    }
                }
                this.entityData.set(ATTACHED_FACE, closestDirection);
            }
        }
        boolean flag = false;
        if (this.getAttachmentFacing() != Direction.DOWN) {
            if (this.getAttachmentFacing() == Direction.UP) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, 1, 0));
            } else {
                if (!this.horizontalCollision && this.getAttachmentFacing() != Direction.UP) {
                    Vec3 vec = Vec3.atLowerCornerOf(this.getAttachmentFacing().getNormal());
                    this.setDeltaMovement(this.getDeltaMovement().add(vec.normalize().multiply(0.1F, 0.1F, 0.1F)));
                }
                if (!this.onGround() && Vec3.y < 0.0D) {
                    this.setDeltaMovement(this.getDeltaMovement().multiply(1.0D, 0.5D, 1.0D));
                    flag = true;
                }
            }
        }
        if (this.getAttachmentFacing() == Direction.UP) {
            this.setNoGravity(true);
            this.setDeltaMovement(Vec3.multiply(0.7D, 1D, 0.7D));
        } else {
            this.setNoGravity(false);
        }
        if (!flag) {
            if (this.onClimbable()) {
                this.setDeltaMovement(Vec3.multiply(1.0D, 0.4D, 1.0D));
            }
        }
        if (prevAttachDir != this.getAttachmentFacing()) {
            attachChangeProgress = 1F;
        }
        this.prevAttachDir = this.getAttachmentFacing();
        if (!this.level().isClientSide) {
            if (this.getAttachmentFacing() == Direction.UP && !this.isUpsideDownNavigator) {
                switchNavigator(false);
            }
            if (this.getAttachmentFacing() != Direction.UP && this.isUpsideDownNavigator) {
                switchNavigator(true);
            }
            LivingEntity target = this.getTarget();
            if (target != null && distanceTo(target) < target.getBbWidth() + this.getBbWidth() && this.hasLineOfSight(target)) {
                float damage = (float) ((int) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                if (this.getAnimation() == JAW_ATTACK && this.getAnimationTick() == 11) {
                    target.hurt(this.damageSources().mobAttack(this), damage);
                    if (this.random.nextInt(6) == 0) {
                        BrokenJaws();
                    }
                }
                if (this.getAnimation() == HEADBUTT_ATTACK && this.getAnimationTick() == 6) {
                    target.hurt(this.damageSources().mobAttack(this), damage * 0.75f);
                }
            }
        } else {
            for (int i = 0; i < 2; ++i) {
                this.level().addParticle(ParticleTypes.PORTAL, this.getRandomX(0.5D), this.getRandomY(), this.getRandomZ(0.5D), (this.random.nextDouble() - 0.5D) * 2.0D, -this.random.nextDouble(), (this.random.nextDouble() - 0.5D) * 2.0D);
            }
        }

    }

@Override
    public void tick() {
        super.tick();
        if (getCaster() != null) {
            if (!getCaster().isAlive()) discard();
            absMoveTo(getCaster().getX(), getCaster().getY() + getCaster().getEyeHeight(), getCaster().getZ(), getCaster().getYRot(), getCaster().getXRot());
        }
        if (!level().isClientSide && tickCount == 7) playSound(MMSounds.ENTITY_WROUGHT_WHOOSH.get(), 0.7F, 1.1f);
        if (!level().isClientSide && getCaster() != null) {
            if (!getVertical() && tickCount == SWING_DURATION_HOR /2 - 1) dealDamage(7.0f * ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue() / 9.0f, 4f, 160, 1.2f);
            else if (getVertical() && tickCount == SWING_DURATION_VER /2 - 1) {
                dealDamage(ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue(), 4.5f, 40, 0.8f);
                quakeAngle = getYRot();
                quakeBB = getBoundingBox().move(0, -getCaster().getEyeHeight(), 0);
                playSound(MMSounds.ENTITY_WROUGHT_AXE_LAND.get(), 0.3F, 0.5F);
                playSound(SoundEvents.GENERIC_EXPLODE.value(), 2, 0.9F + random.nextFloat() * 0.1F);
            }
            else if (getVertical() && tickCount == SWING_DURATION_VER /2 + 1) {
                EntityCameraShake.cameraShake(level(), position(), 10, 0.05f, 0, 10);
            }
        }

        if (getVertical() && getCaster() != null) {
            if (tickCount >= SWING_DURATION_VER /2) {
                int maxDistance = 16;
                double perpFacing = quakeAngle * (Math.PI / 180);
                double facingAngle = perpFacing + Math.PI / 2;
                int hitY = Mth.floor(quakeBB.minY - 0.5);
                int distance = tickCount - 15;
                double spread = Math.PI * 0.35F;
                int arcLen = Mth.ceil(distance * spread);
                double minY = quakeBB.minY;
                double maxY = quakeBB.maxY;
                for (int i = 0; i < arcLen; i++) {
                    double theta = (i / (arcLen - 1.0) - 0.5) * spread + facingAngle;
                    double vx = Math.cos(theta);
                    double vz = Math.sin(theta);
                    double px = getX() + vx * distance;
                    double pz = getZ() + vz * distance;
                    float factor = 1 - distance / (float) maxDistance;
                    AABB selection = new AABB(px - 1.5, minY, pz - 1.5, px + 1.5, maxY, pz + 1.5);
                    List<Entity> hit = level().getEntitiesOfClass(Entity.class, selection);
                    for (Entity entity : hit) {
                        if (entity.onGround()) {
                            if (entity == this || entity instanceof FallingBlockEntity || entity == getCaster()) {
                                continue;
                            }
                            float applyKnockbackResistance = 0;
                            boolean hitEntity = false;
                            if (!raytraceCheckEntity(entity)) continue;

                            if (getCaster() instanceof Player)
                                hitEntity = entity.hurt(damageSources().playerAttack((Player) getCaster()), (factor * 5 + 1) * (ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue() / 9.0f));
                            else
                                hitEntity = entity.hurt(damageSources().mobAttack(getCaster()), (factor * 5 + 1) * (ConfigHandler.COMMON.TOOLS_AND_ABILITIES.AXE_OF_A_THOUSAND_METALS.toolConfig.attackDamage.get().floatValue() / 9.0f));
                            if (entity instanceof LivingEntity) {
                                applyKnockbackResistance = (float) ((LivingEntity) entity).getAttribute(Attributes.KNOCKBACK_RESISTANCE).getValue();
                            }
                            if (hitEntity) {
                                double magnitude = -4;
                                double x = vx * (1 - factor) * magnitude * (1 - applyKnockbackResistance);
                                double y = 0;
                                if (entity.onGround()) {
                                    y += 0.15 * (1 - applyKnockbackResistance);
                                }
                                double z = vz * (1 - factor) * magnitude * (1 - applyKnockbackResistance);
                                entity.setDeltaMovement(entity.getDeltaMovement().add(x, y, z));
                                if (entity instanceof ServerPlayer) {
                                    ((ServerPlayer) entity).connection.send(new ClientboundSetEntityMotionPacket(entity));
                                }
                            }
                        }
                    }
                    if (level().random.nextBoolean()) {
                        int hitX = Mth.floor(px);
                        int hitZ = Mth.floor(pz);
                        BlockPos pos = new BlockPos(hitX, hitY, hitZ);
                        BlockPos abovePos = new BlockPos(pos).above();
                        BlockState block = level().getBlockState(pos);
                        BlockState blockAbove = level().getBlockState(abovePos);
                        if (!block.isAir() && block.isRedstoneConductor(level(), pos) && !block.hasBlockEntity() && !blockAbove.blocksMotion()) {
                            EntityFallingBlock fallingBlock = new EntityFallingBlock(EntityHandler.FALLING_BLOCK.get(), level(), block, 0.3f);
                            fallingBlock.setPos(hitX + 0.5, hitY + 1, hitZ + 0.5);
                            level().addFreshEntity(fallingBlock);
                        }
                    }
                }
            }
        }
        if (tickCount > SWING_DURATION_HOR) discard();
    }

@Override
    public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            float area = this.getAreaOfEffect() / 2;
            float f = 1.5F + area;
            float f5 = (float) Math.PI * f * f;
            for (int k1 = 0; (float) k1 < f5; ++k1) {
                float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                float f7 = Mth.sqrt(this.random.nextFloat()) * f;
                float f8 = Mth.cos(f6) * f7;
                float f9 = Mth.sin(f6) * f7;
                serverLevel.sendParticles(ModParticleTypes.BURNING.get(), this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 1, 0, 0, 0, 0);
            }
            ColorUtil color = ColorUtil.GOLD;
            ServerParticleUtil.windParticle(serverLevel, color, (f - 1.0F) + serverLevel.random.nextFloat() * 0.5F, 0.0F, this.getId(), this.position());
            ServerParticleUtil.windParticle(serverLevel, color, f + serverLevel.random.nextFloat() * 0.5F, 0.0F, this.getId(), this.position());

            if (this.tickCount == 20 || this.getImmediate()){
                for (int j1 = 0; j1 < 16; ++j1) {
                    for (int k1 = 0; (float) k1 < f5; ++k1) {
                        float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        float f7 = Mth.sqrt(this.random.nextFloat()) * f;
                        float f8 = Mth.cos(f6) * f7;
                        float f9 = Mth.sin(f6) * f7;
                        serverLevel.sendParticles(ParticleTypes.FLAME, this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 0, 0, 0.5D, 0, 0.5F);
                    }
                }
                List<Entity> targets = new ArrayList<>();
                float area0 = 1.0F + area;
                AABB aabb = this.getBoundingBox();
                AABB aabb1 = new AABB(aabb.minX - area0, aabb.minY - 1.0F, aabb.minZ - area0, aabb.maxX + area0, aabb.maxY + 1.0F, aabb.maxZ + area0);
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, aabb1)){
                    if (this.owner != null) {
                        if (entity != this.owner && !MobUtil.areAllies(entity, this.owner)) {
                            if (this.owner instanceof Mob mob && this.owner instanceof Enemy && entity instanceof Enemy) {
                                if (mob.getTarget() == entity) {
                                    targets.add(entity);
                                }
                            } else {
                                targets.add(entity);
                            }
                        }
                    } else {
                        targets.add(entity);
                    }
                }
                if (!targets.isEmpty()){
                    for (Entity entity : targets) {
                        if ((this.owner != null && CuriosFinder.hasUnholySet(this.owner))) {
                            if (entity instanceof LivingEntity livingEntity) {
                                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.BURN_HEX.get(), 1200));
                            }
                            entity.hurt(ModDamageSource.hellfire(this, this.owner), AttributesConfig.ApostleMagicDamage.get().floatValue() + this.getExtraDamage());
                        } else {
                            float damage = 5.0F;
                            if (this.owner != null){
                                if (this.owner instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                                    damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE);
                                }
                                entity.hurt(ModDamageSource.magicFireBreath(this, this.owner), damage + this.getExtraDamage());
                            } else {
                                entity.hurt(damageSources().magic(), damage + this.getExtraDamage());
                            }
                        }
                        if (entity instanceof LivingEntity livingEntity) {
                            MobUtil.push(livingEntity, 0.0D, 1.0D, 0.0D, 0.5D);
                            if (this.burning > 0){
                                livingEntity.setSecondsOnFire(this.burning * 4);
                            }
                        }
                    }
                }
            }
        }
        if (this.tickCount > 20 || (this.getImmediate() && this.tickCount > 5)){
            this.setDeltaMovement(this.getDeltaMovement().add(0.0D, 0.25D, 0.0D));
            this.move(MoverType.SELF, this.getDeltaMovement());
        }
        if (this.tickCount == 20 || (this.getImmediate() && this.tickCount == 5)){
            this.playSound(SoundEvents.GENERIC_EXPLODE, 1.0F, 0.5F);
        }
        if (this.owner != null){
            if (this.owner.isDeadOrDying() || this.owner.isRemoved()){
                this.discard();
            }
        }
        if (this.tickCount % 30 == 0){
            this.discard();
        }
    }

public void tick() {
        super.tick();
        repelEntities(1.7F, 3.7f, 1.7F, 1.7F);
        LivingEntity target = this.getTarget();
        prevdeactivateProgress = deactivateProgress;
        if (!this.getIsAwaken() && deactivateProgress < 30F) {
            deactivateProgress++;
        }
        if (this.getIsAwaken() && deactivateProgress > 0F) {
            deactivateProgress--;

        }

        if(!this.getIsAwaken()) {
            if (this.tickCount % 20 == 0) {
                this.heal(2.0F);
            }
        }

        if (deactivateProgress == 0 && this.isAlive()) {
            if (target != null && target.isAlive()) {
                if (void_rune_attack_cooldown <= 0 && !isNoAi() && this.getAnimation() == NO_ANIMATION && target.onGround() && (this.random.nextInt(45) == 0 && this.distanceTo(target) < 4 || this.random.nextInt(24) == 0 && this.distanceTo(target) < 10)) {
                    void_rune_attack_cooldown = VOID_RUNE_ATTACK_COOLDOWN;
                    this.setAnimation(VOID_RUNE_ATTACK);

                } else if (this.distanceTo(target) < 4 && !isNoAi() && this.getAnimation() == NO_ANIMATION) {
                    Animation animation = getRandomAttack(random);
                    this.setAnimation(animation);
                }
            }

            if (this.getAnimation() == ANIMATION_EARTHQUAKE) {
                if (this.getAnimationTick() == 19) {
                    EarthQuake(5,6);
                    EarthQuakeParticle();
                    if (!this.level().isClientSide) {
                        if (CMCommonConfig.EnderGolem.ignoreMobGriefing) {
                            BlockBreaking(4, 4, 4);
                        } else {
                            if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                                BlockBreaking(4, 4, 4);
                            }
                        }
                    }
                }
            }
            if ((this.getAnimation() == ANIMATION_ATTACK1 || this.getAnimation() == ANIMATION_ATTACK2) && this.getAnimationTick() == 13) {
                this.playSound(ModSounds.GOLEMATTACK.get(), 1, 1);
                if (target != null && target.isAlive()) {
                    if (this.distanceTo(target) < 4.75F) {
                        target.hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) + this.random.nextInt(4));
                        target.knockback(1.25F, this.getX() - target.getX(), this.getZ() - target.getZ());
                    }
                }
            }
            if (this.getAnimation() == VOID_RUNE_ATTACK) {
                if (this.getAnimationTick() == 22) {
                    EarthQuake(4.25f,4);
                    EarthQuakeParticle();
                    if (!this.level().isClientSide) {
                        if (CMCommonConfig.EnderGolem.ignoreMobGriefing) {
                            BlockBreaking(4, 4, 4);
                        } else {
                            if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level(), this)) {
                                BlockBreaking(4, 4, 4);
                            }
                        }
                    }
                }
                if (this.getAnimationTick() == 28) {
                    VoidRuneAttack();
                }
            }
        }
        if (void_rune_attack_cooldown > 0) void_rune_attack_cooldown--;
        if (!level().isClientSide) {
            timeWithoutTarget++;
            if (target != null) {
                timeWithoutTarget = 0;
                if(!this.getIsAwaken()) {
                    this.setIsAwaken(true);
                }
            }

            if (timeWithoutTarget > 400 && this.getIsAwaken() && target == null) {
                timeWithoutTarget = 0;
                this.setIsAwaken(false);
            }
        }

    }

@Override
    public void tick() {
        super.tick();
        LivingEntity target = this.getTarget();
        if (target != null && this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() == 7) {
            double dist = this.distanceToSqr(target);
            if (dist < 10) {
                target.knockback(0.6F, Mth.sin(this.getYRot() * 0.017453292F), -Mth.cos(this.getYRot() * 0.017453292F));
                target.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (this.getAnimation() == ANIMATION_WING_BLAST && this.getAnimationTick() == 5) {
            this.playSound(IafSoundRegistry.AMPHITHERE_GUST, 1, 1);
        }
        if ((this.getAnimation() == ANIMATION_BITE || this.getAnimation() == ANIMATION_BITE_RIDER) && this.getAnimationTick() == 1) {
            this.playSound(IafSoundRegistry.AMPHITHERE_BITE, 1, 1);
        }
        if (target != null && this.getAnimation() == ANIMATION_WING_BLAST && this.getAnimationTick() > 5 && this.getAnimationTick() < 22) {

            double dist = this.distanceToSqr(target);
            if (dist < 25) {
                target.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue() / 2));
                target.hasImpulse = true;
                if (!(this.random.nextDouble() < this.getAttribute(Attributes.KNOCKBACK_RESISTANCE).getValue())) {
                    this.hasImpulse = true;
                    double d1 = target.getX() - this.getX();

                    double d0;
                    for (d0 = target.getZ() - this.getZ(); d1 * d1 + d0 * d0 < 1.0E-4D; d0 = (Math.random() - Math.random()) * 0.01D) {
                        d1 = (Math.random() - Math.random()) * 0.01D;
                    }
                    Vec3 Vector3d = this.getDeltaMovement();
                    Vec3 Vector3d1 = (new Vec3(d0, 0.0D, d1)).normalize().scale(0.5);
                    this.setDeltaMovement(Vector3d.x / 2.0D - Vector3d1.x, this.isOnGround() ? Math.min(0.4D, Vector3d.y / 2.0D + 0.5) : Vector3d.y, Vector3d.z / 2.0D - Vector3d1.z);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_TAIL_WHIP && target != null && this.getAnimationTick() == 7) {
            double dist = this.distanceToSqr(target);
            if (dist < 10) {
                target.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
                target.hasImpulse = true;
                float f = Mth.sqrt((float) (0.5 * 0.5 + 0.5 * 0.5));
                double d0;
                double d1 = target.getX() - this.getX();
                for (d0 = target.getZ() - this.getZ(); d1 * d1 + d0 * d0 < 1.0E-4D; d0 = (Math.random() - Math.random()) * 0.01D) {
                    d1 = (Math.random() - Math.random()) * 0.01D;
                }
                Vec3 Vector3d = this.getDeltaMovement();
                Vec3 Vector3d1 = (new Vec3(d0, 0.0D, d1)).normalize().scale(0.5);
                this.setDeltaMovement(Vector3d.x / 2.0D - Vector3d1.x, this.isOnGround() ? Math.min(0.4D, Vector3d.y / 2.0D + 0.5) : Vector3d.y, Vector3d.z / 2.0D - Vector3d1.z);

            }
        }
        if (this.isGoingUp() && !level.isClientSide) {
            if (!this.isFlying()) {
                // TODO: separate take off with rider logic
                this.setDeltaMovement(this.getDeltaMovement().add(0, 1, 0));
                this.setFlying(true);
            }
        }
        if (!this.isOverAir() && this.isFlying() && ticksFlying > 25) {
            this.setFlying(false);
        }
        if (this.dismountIAF()) {
            if (this.isFlying()) {
                if (this.onGround) {
                    this.setFlying(false);
                }
            }
        }
        if (this.getUntamedRider() != null && this.getUntamedRider().isShiftKeyDown()) {
            if (this.getUntamedRider() instanceof LivingEntity)
                MiscProperties.setDismountedDragon((LivingEntity) this.getUntamedRider(), true);
            this.getUntamedRider().stopRiding();
        }
        if (this.attack() && this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player) {
            LivingEntity riderTarget = DragonUtils.riderLookingAtEntity(this, (Player) this.getControllingPassenger(), 2.5D);
            if (this.getAnimation() != ANIMATION_BITE) {
                this.setAnimation(ANIMATION_BITE);
            }
            if (riderTarget != null) {
                riderTarget.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (target != null && this.isOwnedBy(target)) {
            this.setTarget(null);
        }
        if (target != null && this.isOnGround() && this.isFlying() && ticksFlying > 40) {
            this.setFlying(false);
        }
    }

@Override
    public void tick() {
        float progress = this.getProgress();
        this.prevProgress = progress;
        super.tick();
        Entity creator = getCreatorEntity();
        Entity current = getToEntity();
        if(tickCount == 1){
            if(!this.level().isClientSide){
                this.playSound(ModSounds.TIDAL_TENTACLE.get(),1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        }
        if(!this.isRetracting() && progress < MAX_EXTEND_TIME){
            this.setProgress(progress + 1);
        }
        if(this.isRetracting() && progress > 0F){
            this.setProgress(progress - 1);
        }
        if(this.isRetracting() && progress == 0F){
            Entity from = this.getFromEntity();
            if(from instanceof Tidal_Tentacle_Entity){
                Tidal_Tentacle_Entity tendonSegment = (Tidal_Tentacle_Entity) from;
                tendonSegment.setRetracting(true);
                updateLastTendon(tendonSegment);
            }else{
                updateLastTendon(null);
            }

            kill();
        }
        if (creator instanceof LivingEntity) {
            if (current != null) {
                Vec3 target = new Vec3(current.getX(), current.getY(0.4F), current.getZ());
                Vec3 lerp = target.subtract(this.position());
                this.setDeltaMovement(lerp.scale(0.5F));
                if(!this.level().isClientSide){
                    if(progress >= MAX_EXTEND_TIME){
                        if (this.tickCount % 2 == 0) {
                            Entity entity = getCreatorEntity();
                            if(entity instanceof LivingEntity) {
                                if (current != creator && current.hurt(damageSources().mobProjectile(this, (LivingEntity) entity), this.getBaseDamage())) {
                                    MobEffectInstance effectinstance1 = ((LivingEntity)current).getEffect(ModEffect.EFFECTABYSSAL_CURSE.get());
                                    int i = 1;
                                    if (effectinstance1 != null) {
                                        i += effectinstance1.getAmplifier();
                                        ((LivingEntity)current).removeEffectNoUpdate(ModEffect.EFFECTABYSSAL_CURSE.get());
                                    } else {
                                        --i;
                                    }

                                    i = Mth.clamp(i, 0, 4);
                                    MobEffectInstance effectinstance = new MobEffectInstance(ModEffect.EFFECTABYSSAL_CURSE.get(), 60, i, false, true, true);
                                    ((LivingEntity)current).addEffect(effectinstance);

                                    // this.doEnchantDamageEffects((LivingEntity) creator, current);
                                }
                            }
                        }
                    }
                }
            }
        }
        Vec3 vector3d = this.getDeltaMovement();
        if(!this.level().isClientSide){
            if(!hasChained){
                if(this.getTargetsHit() > 5){
                    this.setRetracting(true);
                }else if(creator instanceof LivingEntity && this.getProgress() >= MAX_EXTEND_TIME) {
                    Entity closestValid = null;
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(12.0D))) {
                        if (!entity.equals(creator) && !previouslyTouched.contains(entity) && isValidTarget((LivingEntity) creator, entity) && this.hasLineOfSight(entity)) {
                            if (closestValid == null || this.distanceTo(entity) < this.distanceTo(closestValid)) {
                                closestValid = entity;
                            }
                        }
                    }
                    if(closestValid != null){
                        createChain(closestValid);
                        hasChained = true;
                    }else{
                        this.setRetracting(true);
                    }
                }
            }
        }

        double d0 = this.getX() + vector3d.x;
        double d1 = this.getY() + vector3d.y;
        double d2 = this.getZ() + vector3d.z;
        this.setDeltaMovement(vector3d.scale(0.99F));
        this.setPos(d0, d1, d2);
    }

public static AttackShieldResult attackShield(World world, ProtectionShield shield, Vec3d centerPos, float shieldRotationYaw, float shieldRotationPitch, float shieldRotationRoll, float shieldExplosion, Object2IntMap<Entity> deflectionDamageCooldowns, DamageSource source, boolean checkOnly) {
		if(source instanceof EntityDamageSource) {
			EntityDamageSource entityDamage = (EntityDamageSource) source;

			Entity sourceEntity = entityDamage.getTrueSource();
			Entity immediateEntity = entityDamage.getImmediateSource();

			Entity attackingEntity = immediateEntity != null ? immediateEntity : sourceEntity;

			int shieldHit = -1;
			boolean isDeflected = false;

			Vec3d ray = null;
			Vec3d pos = null;

			if(attackingEntity == null) {
				isDeflected = true;
			} else {
				if(attackingEntity instanceof EntityLivingBase) {
					ray = attackingEntity.getLookVec();
				} else {
					ray = new Vec3d(attackingEntity.motionX, attackingEntity.motionY, attackingEntity.motionZ).normalize();
				}
				ray = ray.scale(64.0D);

				pos = new Vec3d(attackingEntity.posX, attackingEntity.posY + attackingEntity.getEyeHeight(), attackingEntity.posZ);

				if(shield.hasShield() && (attackingEntity instanceof EntityPlayer == false || !((EntityPlayer)attackingEntity).capabilities.isCreativeMode) || attackingEntity.isSneaking()) {
					shieldHit = rayTraceShield(shield, centerPos, shieldRotationYaw, shieldRotationPitch, shieldRotationRoll, shieldExplosion, pos, ray, false);

					if(shieldHit >= 0) {
						if(!checkOnly) {
							if(!world.isRemote && attackingEntity.isSneaking() && ((EntityPlayer)attackingEntity).capabilities.isCreativeMode) {
								shield.setActive(shieldHit, false);
							}

							if(world.isRemote) {
								shield.setAnimationTicks(shieldHit, 20);
							}
						}

						isDeflected = true;
					}
				}
			}

			if(isDeflected) {
				if(!checkOnly && !world.isRemote) {
					boolean damaged = false;

					if(sourceEntity != null && !deflectionDamageCooldowns.containsKey(sourceEntity)) {
						double dx = sourceEntity.posX - centerPos.x;
						double dy = sourceEntity.posY - centerPos.y;
						double dz = sourceEntity.posZ - centerPos.z;
						double len = Math.sqrt(dx*dx+dy*dy+dz*dz);
						sourceEntity.motionX = dx / len * 0.8F;
						sourceEntity.motionY = dy / len * 0.8F;
						sourceEntity.motionZ = dz / len * 0.8F;
						sourceEntity.velocityChanged = sourceEntity.isAirBorne = true;
						sourceEntity.attackEntityFrom(DamageSource.MAGIC, 2);

						deflectionDamageCooldowns.put(sourceEntity, 10);
						damaged = true;
					}

					if(immediateEntity != null && !deflectionDamageCooldowns.containsKey(immediateEntity)) {
						double dx = immediateEntity.posX - centerPos.x;
						double dy = immediateEntity.posY - centerPos.y;
						double dz = immediateEntity.posZ - centerPos.z;
						double len = Math.sqrt(dx*dx+dy*dy+dz*dz);
						immediateEntity.motionX = dx / len * 0.8F;
						immediateEntity.motionY = dy / len * 0.8F;
						immediateEntity.motionZ = dz / len * 0.8F;
						immediateEntity.velocityChanged = immediateEntity.isAirBorne = true;
						immediateEntity.attackEntityFrom(DamageSource.MAGIC, 2);

						deflectionDamageCooldowns.put(immediateEntity, 10);
						damaged = true;
					}

					if(damaged) {
						world.playSound(null, centerPos.x, centerPos.y, centerPos.z, SoundRegistry.FORTRESS_BOSS_NOPE, SoundCategory.HOSTILE, 1, 1);
					}
				}

				return new AttackShieldResult(true, shieldHit, pos, ray);
			} else {
				return new AttackShieldResult(false, shieldHit, pos, ray);
			}
		}

		return new AttackShieldResult(true, -1, null, null);
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		BlockPos pos = this.getPosition().down(1);
		IBlockState blockState = this.world.getBlockState(pos);

		if(!this.world.isRemote) {
			if(blockState.getBlock() == Blocks.AIR || (this.hasPlayerOwner() && !blockState.isSideSolid(this.world, pos, EnumFacing.UP))) {
				this.setDead();
			}

			Entity owner = this.getPlayerOwner();

			if(this.hasPlayerOwner() && (owner == null || owner.getDistance(this) > 32.0D)) {
				this.setHealth(0);
			} else if(owner instanceof EntityPlayer) {
				EntityPlayer player = (EntityPlayer) owner;
				if(!ItemRingOfSummoning.isRingActive(player)) {
					this.setHealth(0);
				}
			}

			if(this.despawnTicks >= 150) {
				this.setHealth(0);
			} else {
				if(this.spawnTicks >= 40) {
					this.despawnTicks++;
				}
			}
		}

		if(this.deathTicks > 0) {
			this.yOffset = -this.deathTicks / 40.0F;
		} else if(this.spawnTicks >= 40) {
			this.yOffset = 0.0F;
		}

		if(this.isEntityAlive()) {
			if(this.spawnTicks >= 4) {
				List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox());
				for(EntityLivingBase target : targets) {

					boolean isValidTarget;
					if(this.hasPlayerOwner()) {
						isValidTarget = target != this && target != this.getPlayerOwner() && (target instanceof EntityMob || target instanceof IMob);
					} else {
						isValidTarget = target instanceof EntityPlayer;
					}
					if(isValidTarget) {
						target.setInWeb();

						if(target.hurtResistantTime < 10) {
							DamageSource damageSource;
							Entity owner = this.getPlayerOwner();
							if(owner != null) {
								damageSource = new EntityDamageSourceIndirect("mob", this, owner);
							} else {
								damageSource = DamageSource.causeMobDamage(this);
							}

							target.attackEntityFrom(damageSource, (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());

							if(this.attackSwing <= 0) {
								this.attackSwing = 20;
							}
						}
					}
				}
			}

			if(this.spawnTicks < 40) {
				this.spawnTicks++;
				this.yOffset = -1 + this.spawnTicks / 40.0F;
			} else {
				this.yOffset = 0.0F;
			}

			if(this.attackSwing > 0) {
				this.attackSwing--;
			}
		}

		if(this.world.isRemote && this.rand.nextInt(this.yOffset < 0.0F ? 2 : 8) == 0) {
			if(blockState.getBlock() != Blocks.AIR) {
				double px = this.posX;
				double py = this.posY;
				double pz = this.posZ;
				for (int i = 0, amount = 2 + this.rand.nextInt(this.yOffset < 0.0F ? 8 : 3); i < amount; i++) {
					double ox = this.rand.nextDouble() * 0.1F - 0.05F;
					double oz = this.rand.nextDouble() * 0.1F - 0.05F;
					double motionX = this.rand.nextDouble() * 0.2 - 0.1;
					double motionY = this.rand.nextDouble() * 0.1 + 0.1;
					double motionZ = this.rand.nextDouble() * 0.2 - 0.1;
					this.world.spawnParticle(EnumParticleTypes.BLOCK_DUST, px + ox, py, pz + oz, motionX, motionY, motionZ, Block.getStateId(blockState));
				}
			}
		}
	}

@Override
	protected void onImpact(RayTraceResult rayTrace){

		Entity entityHit = rayTrace.entityHit;

		if(entityHit != null){
			// This is if the ice charge gets a direct hit
			float damage = Spells.ice_charge.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

			entityHit.attackEntityFrom(
					MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.FROST).setProjectile(),
					damage);

			if(!this.world.isRemote && entityHit instanceof EntityLivingBase && !MagicDamage.isEntityImmune(DamageType.FROST, entityHit))
				((EntityLivingBase)entityHit).addPotionEffect(new PotionEffect(WizardryPotions.frost,
						Spells.ice_charge.getProperty(Spell.DIRECT_EFFECT_DURATION).intValue(),
						Spells.ice_charge.getProperty(Spell.DIRECT_EFFECT_STRENGTH).intValue()));
		}

		// Particle effect
		if(world.isRemote){
			this.world.spawnParticle(EnumParticleTypes.EXPLOSION_LARGE, this.posX, this.posY, this.posZ, 0, 0, 0);
			for(int i = 0; i < 30 * blastMultiplier; i++){

				ParticleBuilder.create(Type.ICE, rand, this.posX, this.posY, this.posZ, 2 * blastMultiplier, false)
				.time(35).gravity(true).spawn(world);

				float brightness = 0.4f + rand.nextFloat() * 0.5f;
				ParticleBuilder.create(Type.DARK_MAGIC, rand, this.posX, this.posY, this.posZ, 2 * blastMultiplier, false)
				.clr(brightness, brightness + 0.1f, 1.0f).spawn(world);
			}
		}

		if(!this.world.isRemote){

			this.playSound(WizardrySounds.ENTITY_ICE_CHARGE_SMASH, 1.5f, rand.nextFloat() * 0.4f + 0.6f);
			this.playSound(WizardrySounds.ENTITY_ICE_CHARGE_ICE, 1.2f, rand.nextFloat() * 0.4f + 1.2f);

			double radius = Spells.ice_charge.getProperty(Spell.EFFECT_RADIUS).floatValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(radius, this.posX, this.posY,
					this.posZ, this.world);

			// Slows targets
			for(EntityLivingBase target : targets){
				if(target != entityHit && target != this.getThrower()){
					if(!MagicDamage.isEntityImmune(DamageType.FROST, target))
						target.addPotionEffect(new PotionEffect(WizardryPotions.frost,
								Spells.ice_charge.getProperty(Spell.SPLASH_EFFECT_DURATION).intValue(),
								Spells.ice_charge.getProperty(Spell.SPLASH_EFFECT_STRENGTH).intValue()));
				}
			}

			// Places snow and ice on ground.
			for(int i = -1; i < 2; i++){
				for(int j = -1; j < 2; j++){

					BlockPos pos = new BlockPos(this.posX + i, this.posY, this.posZ + j);

					Integer y = BlockUtils.getNearestSurface(world, pos, EnumFacing.UP, 7, true,
							BlockUtils.SurfaceCriteria.SOLID_LIQUID_TO_AIR);

					if(y != null){

						pos = new BlockPos(pos.getX(), y, pos.getZ());

						double dist = this.getDistance(pos.getX(), pos.getY(), pos.getZ());

						// Randomised with weighting so that the nearer the block the more likely it is to be snowed.
						if(rand.nextInt((int)dist * 2 + 1) < 1 && dist < 2){
							if(world.getBlockState(pos.down()).getBlock() == Blocks.WATER){
								world.setBlockState(pos.down(), Blocks.ICE.getDefaultState());
							}else{
								// Don't need to check whether the block at pos can be replaced since getNearestFloorLevelB
								// only ever returns floors with air above them.
								world.setBlockState(pos, Blocks.SNOW_LAYER.getDefaultState());
							}
						}
					}
				}
			}

			// Releases shards
			for(int i = 0; i < Spells.ice_charge.getProperty(ICE_SHARDS).intValue(); i++){
				double dx = rand.nextDouble() - 0.5;
				double dy = rand.nextDouble() - 0.5;
				double dz = rand.nextDouble() - 0.5;
				EntityIceShard iceshard = new EntityIceShard(world);
				iceshard.setPosition(this.posX + dx, this.posY + dy, this.posZ + dz);
				iceshard.motionX = dx * 1.5;
				iceshard.motionY = dy * 1.5;
				iceshard.motionZ = dz * 1.5;
				iceshard.setCaster(this.getThrower());
				iceshard.damageMultiplier = this.damageMultiplier;
				world.spawnEntity(iceshard);
			}

			this.setDead();
		}
	}

@Override
    public void tick(ICommonArmorHandler commonArmorHandler, boolean enabled) {
        if (commonArmorHandler.isOnCooldown(EquipmentSlot.FEET)) {
            // putting the boots on cooldown is a way for other mods to temporarily suppress jet boots
            return;
        }

        int jetbootsCount = commonArmorHandler.getUpgradeCount(EquipmentSlot.FEET, ModUpgrades.JET_BOOTS.get());
        if (jetbootsCount == 0) return;

        int jetbootsAirUsage = 0;

        Player player = commonArmorHandler.getPlayer();
        JetBootsStateTracker.JetBootsState jbState = JetBootsStateTracker.getTracker(player).getJetBootsState(player);
        JetBootsLocalState jbLocal = commonArmorHandler.getExtensionData(this);

        if (commonArmorHandler.hasMinPressure(EquipmentSlot.FEET)) {
            boolean vibration = !player.level().isClientSide() && player.tickCount % 10 == 0;
            if (jbState.isActive()) {
                if (jbState.isBuilderMode() && jetbootsCount >= BUILDER_MODE_LEVEL) {
                    // builder mode - rise vertically (or hover if sneaking and firing)
                    setYMotion(player, player.isShiftKeyDown() ? 0 : 0.15 + 0.15 * (jetbootsCount - 3));
                    jetbootsAirUsage = (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * jetbootsCount / 2.5F);
                    if (vibration) {
                        player.gameEvent(ModGameEvents.JET_BOOTS_FLY_BUILDER);
                    }
                } else {
                    // jetboots firing - move in direction of looking
                    Vec3 lookVec = player.getLookAngle().scale(0.3 * jetbootsCount);
                    jbLocal.updateAccel(lookVec);
                    lookVec = jbLocal.getEffectiveMotion(lookVec, player.isFallFlying());
                    player.setDeltaMovement(lookVec.x, player.onGround() ? 0 : lookVec.y, lookVec.z);
                    jetbootsAirUsage = jbLocal.calcAirUsage(jetbootsCount);
                    if (vibration) {
                        player.gameEvent(ModGameEvents.JET_BOOTS_FLY);
                    }
                }
                if (player.isInWater()) jetbootsAirUsage *= 4;
                jbLocal.tickActive();
            } else if (jbState.isEnabled() && !isOnGround(player) && !player.isFallFlying()) {
                // jetboots not firing, but enabled - slowly descend (or hover if enough upgrades)
                // and bring player to complete halt if flight stabilizers and not actively moving forward/sideways
                boolean reallyHovering = jbLocal.canHover() && (!jbLocal.isSmartHover() || jbLocal.isHovering());
                boolean stopped = jbLocal.isFlightStabilizers()
                        && jetbootsCount >= STABILIZERS_LEVEL
                        && PneumaticCraftUtils.epsilonEquals(player.zza, 0f)
                        && PneumaticCraftUtils.epsilonEquals(player.xxa, 0f);
                double xMotion = stopped ? 0 : player.getDeltaMovement().x;
                double yMotion = reallyHovering ? (player.isShiftKeyDown() ? -0.45 : -0.1 + 0.02 * jetbootsCount) : player.getDeltaMovement().y;
                double zMotion = stopped ? 0 : player.getDeltaMovement().z;
                player.setDeltaMovement(new Vec3(xMotion, yMotion, zMotion));
                if (vibration && player.getKnownMovement().lengthSqr() > 0.03) {
                    player.gameEvent(jbState.isBuilderMode() ? ModGameEvents.JET_BOOTS_FLY_BUILDER : ModGameEvents.JET_BOOTS_FLY);
                }
                if (reallyHovering) player.fallDistance = 0;
                jetbootsAirUsage = reallyHovering ? (int) (ConfigHelper.common().armor.jetBootsAirUsage.get() * (player.isShiftKeyDown() ? 0.25F : 0.5F)) : 0;
                jbLocal.resetAccel();
            } else if (isOnGround(player)) {
                jbLocal.setHovering(false);
            } else {
                jbLocal.resetAccel();
            }
        } else {
            // insufficient pressure!
            if (jbState.isEnabled() && !player.onGround() && !player.isFallFlying() && jbLocal.isHovering()) {
                // still active and in the air: using minimal air here keeps the boots running
                // and thus avoids triggering multiple looping sounds (see "jet boots starting up" code below)
                jetbootsAirUsage = 1;
            }
            setJetBootsActive(commonArmorHandler,false);
        }

        if (jetbootsAirUsage != 0 && !player.level().isClientSide) {
            if (jbLocal.getPrevJetBootsAirUsage() == 0) {
                // jet boots starting up
                NetworkHandler.sendToAllTracking(new PacketPlayMovingSound(MovingSounds.Sound.JET_BOOTS, MovingSoundFocus.of(player)), player.level(), player.blockPosition());
                ModCriterionTriggers.FLIGHT.get().trigger((ServerPlayer) player);
            }
            if (player.horizontalCollision) {
                double vel = player.getDeltaMovement().length();
                if (player.level().getDifficulty() == Difficulty.HARD) {
                    vel *= 2;
                } else if (player.level().getDifficulty() == Difficulty.NORMAL) {
                    vel *= 1.5;
                }
                if (vel > 2) {
                    player.playSound(vel > 2.5 ? SoundEvents.GENERIC_BIG_FALL : SoundEvents.GENERIC_SMALL_FALL, 1.0F, 1.0F);
                    player.hurt(player.damageSources().flyIntoWall(), (float) vel);
                    ModCriterionTriggers.FLY_INTO_WALL.get().trigger((ServerPlayer) player);
                }
            }
            commonArmorHandler.addAir(EquipmentSlot.FEET, -jetbootsAirUsage);

            if (player.position().y > player.level().getMaxBuildHeight() + ConfigHelper.common().armor.jetBootsHeightLimit.get()) {
                player.getCooldowns().addCooldown(ModItems.PNEUMATIC_BOOTS.get(), 20);
            }
        }
        jbLocal.setPrevJetBootsAirUsage(jetbootsAirUsage);

    }

public void tick() {
        super.tick();
        if(isInNether()) {
            conversionTime++;
            if (conversionTime > 300 && !this.level().isClientSide) {
                Hoglin hoglin = this.convertTo(EntityType.HOGLIN, false);
                if(hoglin != null){
                    hoglin.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 200, 0));
                    this.dropEquipment();
                    level().addFreshEntity(hoglin);
                    this.remove(RemovalReason.DISCARDED);
                }
            }
        }
        if (entityToLaunchId != -1 && this.isAlive()) {
            Entity launch = this.level().getEntity(entityToLaunchId);
            this.ejectPassengers();
            entityToLaunchId = -1;
            if (launch != null && !launch.isPassenger()) {
                if (launch instanceof LivingEntity) {
                    launch.setPos(this.getEyePosition().add(0, 1, 0));
                    float rot = 180F + this.getYRot();
                    float strength = (float) (getLaunchStrength() * (1.0D - ((LivingEntity) launch).getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)));
                    float x = Mth.sin(rot * Mth.DEG_TO_RAD);
                    float z = -Mth.cos(rot * Mth.DEG_TO_RAD);
                    if (!(strength <= 0.0D)) {
                        launch.hasImpulse = true;
                        Vec3 vec3 = this.getDeltaMovement();
                        Vec3 vec31 = vec3.add((new Vec3(x, 0.0D, z)).normalize().scale(strength));
                        launch.setDeltaMovement(vec31.x, strength, vec31.z);
                    }
                }
            }
        }
        if (this.getAnimation() == ANIMATION_BUCK && this.getAnimationTick() >= 5) {
            Entity passenger = this.getControllingPassenger();
            if (passenger instanceof LivingEntity) {
                entityToLaunchId = passenger.getId();
            }
        }
        if (!this.level().isClientSide) {
            if (this.isVehicle()) {
                ridingTime++;
                if (ridingTime >= this.getMaxRidingTime() && this.getAnimation() != ANIMATION_BUCK) {
                    this.setAnimation(ANIMATION_BUCK);
                }
            } else {
                ridingTime = 0;
            }
            if (this.isAlive() && ridingTime > 0 && this.getDeltaMovement().horizontalDistanceSqr() > 0.1D) {
                for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                    if (!(entity instanceof EntityTusklin) && !entity.isPassengerOfSameVehicle(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), 4F + random.nextFloat() * 3.0F);
                        if (entity.onGround()) {
                            double d0 = entity.getX() - this.getX();
                            double d1 = entity.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            float f = 0.5F;
                            entity.push(d0 / d2 * f, f, d1 / d2 * f);
                        }
                    }
                }
                this.setMaxUpStep(2F);
            }else{
                this.setMaxUpStep(1.1F);
            }
            if (this.getTarget() != null && this.hasLineOfSight(this.getTarget()) && distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + this.getBbWidth() + 1.8F) {
                if (this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() == 6) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackTarget(this.getTarget(), 0.9F, 0F);
                }
                if ((this.getAnimation() == ANIMATION_GORE_L) && this.getAnimationTick() == 6) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackTarget(this.getTarget(), 0.5F, -90F);
                }
                if ((this.getAnimation() == ANIMATION_GORE_R) && this.getAnimationTick() == 6) {
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                    knockbackTarget(this.getTarget(), 0.5F, 90F);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_RUT && this.getAnimationTick() == 23) {
            if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
                if (this.isBaby()) {
                    if (level().getBlockState(this.blockPosition()).canBeReplaced() && random.nextInt(3) == 0) {
                        level().setBlockAndUpdate(this.blockPosition(), Blocks.BROWN_MUSHROOM.defaultBlockState());
                        this.gameEvent(GameEvent.BLOCK_DESTROY);
                        this.playSound(SoundEvents.CROP_PLANTED, this.getSoundVolume(), this.getVoicePitch());
                    }
                }
                this.level().levelEvent(2001, blockPosition().below(), Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
                this.level().setBlock(blockPosition().below(), Blocks.DIRT.defaultBlockState(), 2);
                this.heal(5);
            }
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && getRandom().nextInt(isBaby() ? 140 : 70) == 0 && (this.getLastHurtByMob() == null || this.distanceTo(this.getLastHurtByMob()) > 30)) {
            if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
                this.setAnimation(ANIMATION_RUT);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    protected void onHitEntity(EntityHitResult p_213868_1_) {
        Entity entity = p_213868_1_.getEntity();
        float velLength = (float) this.getDeltaMovement().length();
        double baseDamage = this.getBaseDamage();
        Entity owner = this.getOwner();
        DamageSource damagesource = getDamageSource(entity);
        if (this.getWeaponItem() != null && this.level() instanceof ServerLevel serverlevel) {
            baseDamage = EnchantmentHelper.modifyDamage(serverlevel, this.getWeaponItem(), entity, damagesource, (float)baseDamage);
        }
        int damage = Mth.ceil(Mth.clamp((double)velLength * baseDamage, 0.0D, 2.147483647E9D));

        int penetration = entityData.get(PENETRATION);
        if (this.getPierceLevel() > 0 || penetration > 0) {
            if (this.piercingIgnoreEntityIds == null) {
                this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
            }

            if (this.piercedAndKilledEntities == null) {
                this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
            }

            if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1 && this.piercingIgnoreEntityIds.size() >= penetration + 1) {
                this.discard();
                return;
            }

            this.piercingIgnoreEntityIds.add(entity.getId());
        }

        if (this.isCritArrow()) {
            long j = (long) this.random.nextInt(damage / 2 + 2);
            damage = (int) Math.min(j + (long) damage, 2147483647L);
        }

        boolean isEnderman = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !isEnderman) {
            entity.setRemainingFireTicks(5);
        }

        //Break shields with penetration
        if (penetration > 1 && entity instanceof Player) {
            Player player = (Player) entity;
            if (player.isUsingItem() && player.getUseItem().getItem() instanceof ShieldItem) {
                player.getCooldowns().addCooldown(player.getUseItem().getItem(), 100);
                level().broadcastEntityEvent(player, (byte) 30);
                player.stopUsingItem();
            }
        }

        if (entity.hurt(damagesource, (float) damage)) {
            if (isEnderman) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {
                if (!level().isClientSide && this.getPierceLevel() <= 0 && penetration <= 0) {
                    livingentity.setArrowCount(livingentity.getArrowCount() + 1);
                }

                this.doKnockback(livingentity, damagesource);
                if (this.level() instanceof ServerLevel serverlevel1) {
                    EnchantmentHelper.doPostAttackEffectsWithItemSource(serverlevel1, livingentity, damagesource, this.getWeaponItem());
                }

                this.doPostHurtEffects(livingentity);
                if (livingentity != owner && livingentity instanceof Player && owner instanceof ServerPlayer && !this.isSilent()) {
                    ((ServerPlayer) owner).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }

                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }

                if (!level().isClientSide && owner instanceof ServerPlayer serverPlayer) {
                    if (this.piercedAndKilledEntities != null && this.shotFromCrossbow()) {
                        CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverPlayer, this.piercedAndKilledEntities);
                    } else if (!entity.isAlive() && this.shotFromCrossbow()) {
                        CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverPlayer, Arrays.asList(entity));
                    }
                }
            }

            this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            if (this.getPierceLevel() <= 0 && penetration <= 0) {
                this.discard();
            }
        } else {
            entity.setRemainingFireTicks(k);
            this.setDeltaMovement(this.getDeltaMovement().scale(0));
            this.setYRot(getYRot() + 180.0F);
            this.yRotO += 180.0F;
            if (!level().isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                    this.spawnAtLocation(this.getPickupItem(), 0.1F);
                }

                this.discard();
            }
        }
    }

