protected void onHitEntity(EntityHitResult p_36757_) {
        Entity entity = p_36757_.getEntity();
        double baseDamage = this.getBaseDamage();
        this.hitEnemy = true;
        if (!this.level.isClientSide) {
            this.level.broadcastEntityEvent(this, (byte) 4);
        }
        if (this.getPierceLevel() > 0) {
            if (this.piercingIgnoreEntityIds == null) {
                this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
            }

            if (this.piercedAndKilledEntities == null) {
                this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
            }

            if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
                this.discard();
                return;
            }

            this.piercingIgnoreEntityIds.add(entity.getId());
        }

        if (this.isCritArrow()) {
            long j = this.random.nextInt(Mth.floor(baseDamage) / 2 + 2);
            baseDamage = (int)Math.min(j + (long)baseDamage, 2147483647L);
        }

        Entity entity1 = this.getOwner();
        DamageSource damagesource;
        if (entity1 == null) {
            damagesource = this.damageSources().arrow(this, this);
        } else {
            damagesource = this.damageSources().arrow(this, entity1);
            if (entity1 instanceof LivingEntity) {
                ((LivingEntity)entity1).setLastHurtMob(entity);
            }
        }

        boolean flag = entity.getType() == EntityType.ENDERMAN;
        int k = entity.getRemainingFireTicks();
        if (this.isOnFire() && !flag) {
            entity.setSecondsOnFire(5);
        }

        if (entity.hurt(damagesource, (float)baseDamage)) {
            if (flag) {
                return;
            }

            if (entity instanceof LivingEntity livingentity) {
                if (!this.level.isClientSide && this.getPierceLevel() <= 0) {
                    livingentity.setArrowCount(livingentity.getArrowCount() + 1);
                }

                if (this.getKnockback() > 0) {
                    double d0 = Math.max(0.0D, 1.0D - livingentity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
                    Vec3 vec3 = this.getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale((double)this.getKnockback() * 0.6D * d0);
                    if (vec3.lengthSqr() > 0.0D) {
                        livingentity.push(vec3.x, 0.1D, vec3.z);
                    }
                }

                if (!this.level.isClientSide && entity1 instanceof LivingEntity) {
                    EnchantmentHelper.doPostHurtEffects(livingentity, entity1);
                    EnchantmentHelper.doPostDamageEffects((LivingEntity)entity1, livingentity);
                }

                this.doPostHurtEffects(livingentity);
                if (livingentity != entity1 && livingentity instanceof Player && entity1 instanceof ServerPlayer && !this.isSilent()) {
                    ((ServerPlayer)entity1).connection.send(new ClientboundGameEventPacket(ClientboundGameEventPacket.ARROW_HIT_PLAYER, 0.0F));
                }

                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }

                if (!this.level.isClientSide && entity1 instanceof ServerPlayer serverplayer) {
                    if (this.piercedAndKilledEntities != null && this.shotFromCrossbow()) {
                        CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayer, this.piercedAndKilledEntities);
                    } else if (!entity.isAlive() && this.shotFromCrossbow()) {
                        CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayer, Arrays.asList(entity));
                    }
                }
            }

            this.playSound(this.getHitGroundSoundEvent(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
            if (this.getPierceLevel() <= 0) {
                this.discard();
            }
        } else {
            entity.setRemainingFireTicks(k);
            this.setDeltaMovement(this.getDeltaMovement().scale(-0.1D));
            this.setYRot(this.getYRot() + 180.0F);
            this.yRotO += 180.0F;
            if (!this.level.isClientSide && this.getDeltaMovement().lengthSqr() < 1.0E-7D) {
                if (this.pickup == AbstractArrow.Pickup.ALLOWED) {
                    this.spawnAtLocation(this.getPickupItem(), 0.1F);
                }

                this.discard();
            }
        }

    }

@Override
    public void render(SoulBrazierBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        var level = Minecraft.getInstance().level;
        var itemRenderer = Minecraft.getInstance().getItemRenderer();
        var inventory = blockEntityIn.inventory;
        var spiritInventory = blockEntityIn.spiritInventory;
        int spiritsRendered = 0;
        if (!spiritInventory.isEmpty()) {
            for (int i = 0; i < spiritInventory.getSlotCount(); i++) {
                ItemStack item = spiritInventory.getStackInSlot(i);
                if (item.getItem() instanceof SpiritShardItem shardItem) {
                    poseStack.pushPose();
                    Vector3f offset = blockEntityIn.getSpiritOffset(spiritsRendered++, partialTicks).toVector3f();
                    poseStack.translate(offset.x(), offset.y(), offset.z());
                    FloatingItemRenderer.renderSpiritGlimmer(poseStack, shardItem.getSpiritHolder(), partialTicks);
                    poseStack.mulPose(Axis.YP.rotationDegrees(((level.getGameTime() % 360) + partialTicks) * 3));
                    poseStack.scale(0.5f, 0.5f, 0.5f);
                    itemRenderer.renderStatic(item, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
                    poseStack.popPose();
                }
            }
        }
        int extrasRendered = 0;
        if (!inventory.isEmpty()) {
            for (int i = 0; i < inventory.getSlotCount()-1; i++) {
                ItemStack item = inventory.getStackInSlot(i+1);
                poseStack.pushPose();
                Vector3f offset = blockEntityIn.getExtrasOffset(extrasRendered++, partialTicks).toVector3f();
                poseStack.translate(offset.x(), offset.y(), offset.z());
                poseStack.mulPose(Axis.YN.rotationDegrees(((level.getGameTime() % 360) + partialTicks) * 3));
                poseStack.scale(0.5f, 0.5f, 0.5f);
                itemRenderer.renderStatic(item, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
                poseStack.popPose();
            }
        }
        ItemStack stack = inventory.getStackInSlot(0);
        if (!stack.isEmpty()) {
            poseStack.pushPose();
            Vec3 offset = SoulBrazierBlockEntity.BRAZIER_ITEM_OFFSET;
            poseStack.translate(offset.x, offset.y, offset.z);
            poseStack.mulPose(Axis.YP.rotationDegrees((((level.getGameTime() + partialTicks) * 3) % 360)));
            poseStack.scale(0.55f, 0.55f, 0.55f);
            itemRenderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
            poseStack.popPose();
        }

        if (blockEntityIn.isActive()) {
            var recipe = blockEntityIn.recipe;
            var spirits = recipe.spirits;
            var geas = recipe.result;
            var texture = geas.getIcon();
            var additive = LodestoneRenderTypes.ADDITIVE_DISTORTED_TEXTURE.apply(RenderTypeToken.createToken(texture));
            var transparent = LodestoneRenderTypes.TRANSPARENT_DISTORTED_TEXTURE.apply(RenderTypeToken.createToken(texture));
            var offset = SoulBrazierBlockEntity.BRAZIER_GEAS_ICON_OFFSET;
            float progress = blockEntityIn.progress + partialTicks;
            float alpha = 0.9f * Math.clamp(progress / 5f, 0, 1);
            float scale = 0.4f * Math.min(1 + progress / 10f, 2);
            var worldVFXBuilder = VFXBuilders.createWorld();
            var cycle = new AtomicInteger();
            Function<Function<SpiritLike, Color>, Color> colorSupplier = (b) -> b.apply(spirits.get(cycle.getAndIncrement() % spirits.size())); //TODO: this kinda smells...
            var mainColor = colorSupplier.apply(SpiritLike::getPrimaryColor);

            poseStack.pushPose();
            poseStack.translate(offset.x, offset.y, offset.z);
            poseStack.mulPose(Minecraft.getInstance().getEntityRenderDispatcher().cameraOrientation());

            int interval = 160;
            float gameTime = level.getGameTime() + partialTicks;
            float distance = scale * 0.08f;

            worldVFXBuilder
                    .setColor(colorSupplier.apply(SpiritLike::getPrimaryColor)).multiplyColor(0.32f)
                    .setRenderType(transparent)
                    .setAlpha(alpha*0.4f)
                    .renderQuad(poseStack, scale);
            for (int i = 0; i < 4; i++) {
                double angle = i * 1.57f;
                angle += ((gameTime % interval) / interval) * 6.28f;
                double xOffset = (distance * Math.cos(angle));
                double yOffset = (distance * Math.sin(angle));
                poseStack.translate(xOffset, yOffset, -0.02*i);
                worldVFXBuilder
                        .setColor(colorSupplier.apply(SpiritLike::getPrimaryColor)).multiplyColor(0.32f)
                        .renderQuad(poseStack, scale);
                poseStack.translate(-xOffset, -yOffset, 0.02*i);
            }

            worldVFXBuilder
                    .replaceBufferSource(LodestoneRenderingSystem.LATE_DEFERRED_RENDER)
                    .setColor(mainColor)
                    .setRenderType(additive)
                    .setAlpha(alpha*0.8f)
                    .renderQuad(poseStack, scale);
            for (int i = 0; i < 4; i++) {
                double angle = i * 1.57f;
                angle += ((gameTime % interval) / interval) * 6.28f;
                double xOffset = (distance * Math.cos(angle));
                double yOffset = (distance * Math.sin(angle));
                poseStack.translate(xOffset, yOffset, 0);
                worldVFXBuilder
                        .setAlpha(alpha*0.4f)
                        .setColor(colorSupplier.apply(SpiritLike::getSecondaryColor))
                        .renderQuad(poseStack, scale);
                poseStack.translate(-xOffset, -yOffset, 0);
            }
            poseStack.popPose();
        }
    }

public static boolean onDamageSourceBlocking(LivingEntity blocker, ItemStack useItem, DamageSource source,
												 CallbackInfoReturnable<Boolean> info) {
		if (blocker instanceof Player player && useItem != null) {
			boolean blocking = ((IProperShieldUser)blocker).isActuallyReallyBlocking();

			if (!blocking)
				return false;

			if (useItem.getItem() instanceof InfernalShield) {
				boolean piercingArrow = false;
				Entity entity = source.getDirectEntity();

				if (entity instanceof AbstractArrow arrow) {
					if (arrow.getPierceLevel() > 0) {
						piercingArrow = true;
					}
				}

				piercingArrow = false; // defend against Piercing... for now

				if (!source.is(DamageTypeTags.BYPASSES_SHIELD) && !piercingArrow) {
					Vec3 sourcePos = source.getSourcePosition();

					if (sourcePos != null) {
						Vec3 lookVec = blocker.getViewVector(1.0F);
						Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
						sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

						if (sourceToSelf.dot(lookVec) < 0.0D) {
							int strength = -1;

							if (player.hasEffect(EnigmaticEffects.BLAZING_STRENGTH)) {
								MobEffectInstance effectInstance = player.getEffect(EnigmaticEffects.BLAZING_STRENGTH);
								strength = effectInstance.getAmplifier();
								player.removeEffect(EnigmaticEffects.BLAZING_STRENGTH);
								strength = strength > 2 ? 2 : strength;
							}

							player.addEffect(new MobEffectInstance(EnigmaticEffects.BLAZING_STRENGTH, 1200, strength + 1, true, true));

							if (source.getDirectEntity() instanceof LivingEntity living && living.isAlive()) {
								if (!living.fireImmune() && !(living instanceof Guardian)) {
									StackTraceElement[] stacktrace = Thread.currentThread().getStackTrace();

									// Ensure that we will not be caught in any sort of StackOverflow because of thorns-like effects
									if (Arrays.stream(stacktrace).filter(element -> {
										return SuperpositionHandler.class.getName().equals(element.getClassName());
									}).count() < 2) {
										living.invulnerableTime = 0;
										living.hurt(living.damageSources().source(DamageTypes.ON_FIRE, player), 4F);
										living.setSecondsOnFire(4);
										EnigmaticEventHandler.KNOCKBACK_THAT_BASTARD.remove(living);
									}
								}
							}

							return true;
						}
					}
				}
			} else if (useItem.getItem() instanceof EldritchPan) {
				Entity projectile = source.getDirectEntity();

				if (!(projectile instanceof Projectile))
					return false;

				if (!source.is(DamageTypeTags.BYPASSES_SHIELD)) {
					Vec3 sourcePos = source.getSourcePosition();

					if (sourcePos != null) {
						Vec3 lookVec = blocker.getViewVector(1.0F);
						Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
						sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

						if (sourceToSelf.dot(lookVec) < 0.0D) {
							projectile.kill();

							FoodData data = player.getFoodData();
							data.eat(4, 0.5F);

							player.level().playSound(null, player.getX(), player.getY(), player.getZ(),
									SoundEvents.PLAYER_BURP, SoundSource.PLAYERS, 0.5F,
									player.level().random.nextFloat() * 0.1F + 0.9F);

							player.gameEvent(GameEvent.EAT);

							if (projectile instanceof LargeFireball fireball) {
								fireball.explosionPower = 0;
							}

							if (player.level() instanceof ServerLevel level) {
								Vec3 angle = player.getLookAngle();
								angle.multiply(1, 0, 1).normalize().multiply(0.5, 0.5, 0.5);

								level.sendParticles(new ItemParticleOption(ParticleTypes.ITEM,
										new ItemStack(Items.FIRE_CHARGE)), player.getX() + angle.x,
										player.getY() + player.getEyeHeight() - 0.1, player.getZ() + angle.z,
										10, 0.3D, 0.3D, 0.3D, 0.03D);
							}

							return true;
						}
					}
				}
			}
		}

		return false;
	}

@Override
    public void aiStep() {
        super.aiStep();
        if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
            this.setTarget(null);
        }
        boolean stone = EntityGorgon.isStoneMob(this);
        if (stone && stoneProgress < 20.0F) {
            stoneProgress += 2F;
        } else if (!stone && stoneProgress > 0.0F) {
            stoneProgress -= 2F;
        }
        if (!stone && this.getAnimation() == NO_ANIMATION && this.getTarget() != null && this.getRandom().nextInt(100) == 0) {
            this.setAnimation(ANIMATION_ROAR);
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 5) {
            this.playSound(IafSoundRegistry.TROLL_ROAR, 1, 1);
        }
        if (!stone && this.getHealth() < this.getMaxHealth() && this.tickCount % 30 == 0) {
            this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 30, 1, false, false));
        }
        setAvoidSun(this.level.isDay());
        if (this.level.isDay() && !this.level.isClientSide) {
            float f = this.getBrightness();
            BlockPos blockpos = this.getVehicle() instanceof Boat ? (new BlockPos(this.getX(), Math.round(this.getY()), this.getZ())).above() : new BlockPos(this.getX(), Math.round(this.getY()), this.getZ());
            if (f > 0.5F && this.level.canSeeSky(blockpos)) {
                this.setDeltaMovement(0, 0, 0);
                this.setAnimation(NO_ANIMATION);
                this.playSound(IafSoundRegistry.TURN_STONE, 1, 1);
                this.stoneProgress = 20;
                EntityStoneStatue statue = EntityStoneStatue.buildStatueEntity(this);
                statue.getTrappedTag().putFloat("StoneProgress", 20);
                statue.absMoveTo(this.getX(), this.getY(), this.getZ(), this.getYRot(), this.getXRot());
                if (!level.isClientSide) {
                    level.addFreshEntity(statue);
                }
                statue.yRotO = this.getYRot();
                statue.setYRot(this.getYRot());
                statue.yHeadRot = this.getYRot();
                statue.yBodyRot = this.getYRot();
                statue.yBodyRotO = this.getYRot();
                this.remove(RemovalReason.KILLED);
            }
        }
        if (this.getAnimation() == ANIMATION_STRIKE_VERTICAL && this.getAnimationTick() == 10) {
            float weaponX = (float) (getX() + 1.9F * Mth.cos((float) ((yBodyRot + 90) * Math.PI / 180)));
            float weaponZ = (float) (getZ() + 1.9F * Mth.sin((float) ((yBodyRot + 90) * Math.PI / 180)));
            float weaponY = (float) (getY() + (0.2F));
            BlockState state = level.getBlockState(new BlockPos(weaponX, weaponY - 1, weaponZ));
            for (int i = 0; i < 20; i++) {
                double motionX = getRandom().nextGaussian() * 0.07D;
                double motionY = getRandom().nextGaussian() * 0.07D;
                double motionZ = getRandom().nextGaussian() * 0.07D;
                if (state.getMaterial().isSolid() && level.isClientSide) {
                    this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, state), weaponX + (this.getRandom().nextFloat() - 0.5F), weaponY + (this.getRandom().nextFloat() - 0.5F), weaponZ + (this.getRandom().nextFloat() - 0.5F), motionX, motionY, motionZ);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_STRIKE_VERTICAL && this.getTarget() != null && this.distanceToSqr(this.getTarget()) < 4D && this.getAnimationTick() == 10 && this.deathTime <= 0) {
            this.getTarget().hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
        }
        if (this.getAnimation() == ANIMATION_STRIKE_HORIZONTAL && this.getTarget() != null && this.distanceToSqr(this.getTarget()) < 4D && this.getAnimationTick() == 10 && this.deathTime <= 0) {
            LivingEntity target = this.getTarget();
            target.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            float f1 = 0.5F;
            float f2 = target.zza;
            float f3 = 0.6F;
            float f4 = Mth.sqrt(f2 * f2 + f3 * f3);

            if (f4 < 1.0F) {
                f4 = 1.0F;
            }

            f4 = f1 / f4;
            f2 = f2 * f4;
            f3 = f3 * f4;
            float f5 = Mth.sin(this.getYRot() * 0.017453292F);
            float f6 = Mth.cos(this.getYRot() * 0.017453292F);
            // float f7 = f2 * f6 - f3 * f5;
            // float f8 = f3 * f6 + f2 * f5;
            target.setDeltaMovement(f5, f6, 0.4F);
        }
        if (this.getNavigation().isDone() && this.getTarget() != null && this.distanceToSqr(this.getTarget()) > 3 && this.distanceToSqr(this.getTarget()) < 30 && this.level.getGameRules().getBoolean(GameRules.RULE_MOBGRIEFING)) {
            this.lookAt(this.getTarget(), 30, 30);
            if (this.getAnimation() == NO_ANIMATION && this.random.nextInt(15) == 0) {
                this.setAnimation(ANIMATION_STRIKE_VERTICAL);
            }
            if (this.getAnimation() == ANIMATION_STRIKE_VERTICAL && this.getAnimationTick() == 10) {
                float weaponX = (float) (getX() + 1.9F * Mth.cos((float) ((yBodyRot + 90) * Math.PI / 180)));
                float weaponZ = (float) (getZ() + 1.9F * Mth.sin((float) ((yBodyRot + 90) * Math.PI / 180)));
                float weaponY = (float) (getY() + (this.getEyeHeight() / 2));
                BlockBreakExplosion explosion = new BlockBreakExplosion(level, this, weaponX, weaponY, weaponZ, 1F + this.getRandom().nextFloat());
                if (!MinecraftForge.EVENT_BUS.post(new GenericGriefEvent(this, weaponX, weaponY, weaponZ))) {
                    explosion.explode();
                    explosion.finalizeExplosion(true);
                }

                this.playSound(SoundEvents.GENERIC_EXPLODE, 1, 1);

            }
        }
        if (this.getAnimation() == ANIMATION_STRIKE_VERTICAL && this.getAnimationTick() == 10) {
            this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 2.5F, 0.5F);

        }
        if (this.getAnimation() == ANIMATION_STRIKE_HORIZONTAL && this.getAnimationTick() == 10) {
            this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 2.5F, 0.5F);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        prevDanceProgress = danceProgress;
        prevSitProgress = sitProgress;
        prevStandProgress = standProgress;
        prevSleepProgress = sleepProgress;
        prevStomachAlpha = stomachAlpha;
        if (this.jukeboxPosition == null || !this.jukeboxPosition.closerToCenterThan(this.position(), 15) || !this.level().getBlockState(this.jukeboxPosition).is(Blocks.JUKEBOX)) {
            this.setDancing(false);
            this.jukeboxPosition = null;
        }
        if (isDancing() && danceProgress < 5F) {
            danceProgress++;
        }
        if (!isDancing() && danceProgress > 0F) {
            danceProgress--;
        }
        if (isSitting() && sitProgress < 10F) {
            sitProgress++;
        }
        if (!isSitting() && sitProgress > 0F) {
            sitProgress--;
        }
        if (isStanding() && standProgress < 10F) {
            standProgress++;
        }
        if (!isStanding() && standProgress > 0F) {
            standProgress--;
        }
        if (isBearSleeping() && sleepProgress < 10F) {
            sleepProgress++;
        }
        if (!isBearSleeping() && sleepProgress > 0F) {
            sleepProgress--;
        }
        if (isDigesting()) {
            stomachAlpha = Mth.approach(stomachAlpha, 1.0F, 0.05F);
        } else {
            stomachAlpha = Mth.approach(stomachAlpha, 0.0F, 0.05F);
            if (stomachAlpha <= 0.0F && digestingEffect != null) {
                digestingEffect = null;
            }
        }
        if (level().isClientSide) {
            if (this.isBearSleeping()) {
                int sleepDiv = tickCount % 50;
                if (sleepDiv == 2 || sleepDiv == 10 || sleepDiv == 18) {
                    Vec3 headPos = this.getEyePosition().add(new Vec3(0.2F, -0.4F, 1.2F).yRot(-yBodyRot * ((float) Math.PI / 180F)));
                    this.level().addParticle(ACParticleRegistry.SLEEP.get(), headPos.x, headPos.y, headPos.z, 0, 0.1F, 0);
                }
            }
            spawnPossessedParticles(getRandomX(0.5D), getRandomY(), getRandomZ(0.5D), this.level());
        } else {
            int animationDurationLeft = currentAnimation == null ? 0 : currentAnimation.getDuration() - this.getAnimationTick();
            if (this.isSittingAnimation() && sitFor < animationDurationLeft) {
                sitFor = animationDurationLeft;
            }
            if (this.isStandingAnimation() && standFor < animationDurationLeft) {
                standFor = animationDurationLeft;
            }
            if (sleepFor > 0) {
                this.setStanding(false);
                this.setSitting(false);
                this.setBearSleeping(true);
                sleepFor--;
            } else {
                this.setBearSleeping(false);
                if (sitFor > 0) {
                    sitFor--;
                    this.setSitting(true);
                } else {
                    this.setSitting(false);
                    if (standFor > 0) {
                        standFor--;
                        this.setStanding(true);
                    } else {
                        this.setStanding(false);
                    }
                }
            }
            if (this.getAnimation() == ANIMATION_BACKSCRATCH) {
                if (this.getAnimationTick() % 15 == 0 && this.getAnimationTick() > 0) {
                    if (jellybeansToMake > 0) {
                        spawnAtLocation(createJellybean(), 1.0F + random.nextFloat());
                        jellybeansToMake--;
                    }
                }
                if (jellybeansToMake <= 0 || this.getAnimationTick() > 85) {
                    this.setDigesting(false);
                }
            }
        }
        Entity heldMob = getHeldMob();
        if (heldMob != null && heldMob.isAlive() && heldMob.distanceTo(this) < 10) {
            Vec3 heldPos = this.getEyePosition().add(new Vec3(0.0F, 0.25F, 0.5F).yRot(-yBodyRot * ((float) Math.PI / 180F)));
            Vec3 minus = new Vec3(heldPos.x - heldMob.getX(), heldPos.y - heldMob.getY(), heldPos.z - heldMob.getZ());
            heldMob.setDeltaMovement(minus);
            heldMob.fallDistance = 0.0F;
            heldMob.setYRot(0.0F);
            heldMob.setYBodyRot(0.0F);
            heldMob.setYHeadRot(0.0F);
            heldMob.setXRot(0.0F);
            heldMob.setAirSupply(40);
            this.setAnimation(ANIMATION_EAT);
            if (tickCount % 15 == 0) {
                heldMob.hurt(this.damageSources().mobAttack(this), random.nextBoolean() ? 0.0F : 1.0F);
            }
        } else if (!level().isClientSide) {
            this.setHeldMobId(-1);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void aiStep() {
        super.aiStep();
        yBodyRot = getYRot();

        LivingEntity attackTarget = this.getTarget();
        if (singCooldown > 0) {
            singCooldown--;
            this.setSinging(false);
        }
        if (!level.isClientSide && attackTarget == null && !this.isAgressive()) {
            this.setSinging(true);
        }
        if (this.getAnimation() == ANIMATION_BITE && attackTarget != null && this.distanceToSqr(attackTarget) < 7D && this.getAnimationTick() == 5) {
            attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
        }
        if (this.getAnimation() == ANIMATION_PULL && attackTarget != null && this.distanceToSqr(attackTarget) < 16D && this.getAnimationTick() == 5) {
            attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
            double attackmotionX = (Math.signum(this.getX() - attackTarget.getX()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;
            double attackmotionY = (Math.signum(this.getY() - attackTarget.getY() + 1) * 0.5D - attackTarget.getDeltaMovement().y) * 0.100000000372529 * 5;
            double attackmotionZ = (Math.signum(this.getZ() - attackTarget.getZ()) * 0.5D - attackTarget.getDeltaMovement().z) * 0.100000000372529 * 5;

            attackTarget.setDeltaMovement(attackTarget.getDeltaMovement().add(attackmotionX, attackmotionY, attackmotionZ));
            // float angle = (float) (Math.atan2(attackTarget.getDeltaMovement().z, attackTarget.getDeltaMovement().x) * 180.0D / Math.PI) - 90.0F;
            // entity.moveForward = 0.5F;
            double d0 = this.getX() - attackTarget.getX();
            double d2 = this.getZ() - attackTarget.getZ();
            double d1 = this.getY() - 1 - attackTarget.getY();
            double d3 = Math.sqrt((float) (d0 * d0 + d2 * d2));
            float f = (float) (Mth.atan2(d2, d0) * (180D / Math.PI)) - 90.0F;
            float f1 = (float) (-(Mth.atan2(d1, d3) * (180D / Math.PI)));
            attackTarget.setXRot(updateRotation(attackTarget.getXRot(), f1, 30F));
            attackTarget.setYRot(updateRotation(attackTarget.getYRot(), f, 30F));
        }
        if (level.isClientSide) {
            tail_buffer.calculateChainSwingBuffer(40, 10, 2.5F, this);
        }
        if (this.isAgressive()) {
            ticksAgressive++;
        } else {
            ticksAgressive = 0;
        }
        if (ticksAgressive > 300 && this.isAgressive() && attackTarget == null && !level.isClientSide) {
            this.setAggressive(false);
            this.ticksAgressive = 0;
            this.setSinging(false);
        }

        if (this.isInWater() && !this.isSwimming()) {
            this.setSwimming(true);
        }
        if (!this.isInWater() && this.isSwimming()) {
            this.setSwimming(false);
        }
        LivingEntity target = getTarget();
        boolean pathOnHighGround = this.isPathOnHighGround() || !level.isClientSide && target != null && !target.isInWater();
        if (target == null || !target.isInWater() && !target.isInWater()) {
            if (pathOnHighGround && this.isInWater()) {
                jumpFromGround();
                doWaterSplashEffect();
            }
        }
        if ((this.isInWater() && !pathOnHighGround) && this.isLandNavigator) {
            switchNavigator(false);
        }
        if ((!this.isInWater() || pathOnHighGround) && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (target instanceof Player && ((Player) target).isCreative()) {
            this.setTarget(null);
            this.setAggressive(false);
        }
        if (target != null && !this.isAgressive()) {
            this.setAggressive(true);
        }
        boolean singing = isActuallySinging() && !this.isAgressive() && !this.isInWater() && onGround;
        if (singing && singProgress < 20.0F) {
            singProgress += 1F;
        } else if (!singing && singProgress > 0.0F) {
            singProgress -= 1F;
        }
        boolean swimming = isSwimming();
        if (swimming && swimProgress < 20.0F) {
            swimProgress += 1F;
        } else if (!swimming && swimProgress > 0.0F) {
            swimProgress -= 0.5F;
        }
        if (!level.isClientSide && !EntityGorgon.isStoneMob(this) && this.isActuallySinging()) {
            updateLure();
            checkForPrey();

        }
        if (!level.isClientSide && EntityGorgon.isStoneMob(this) && this.isSinging()) {
            this.setSinging(false);
        }
        if (isActuallySinging() && !this.isInWater()) {
            if (this.getRandom().nextInt(3) == 0) {
                yBodyRot = getYRot();
                if (this.level.isClientSide) {
                    float radius = -0.9F;
                    float angle = (0.01745329251F * this.yBodyRot) - 3F;
                    double extraX = radius * Mth.sin((float) (Math.PI + angle));
                    double extraY = 1.2F;
                    double extraZ = radius * Mth.cos(angle);
                    IceAndFire.PROXY.spawnParticle(EnumParticles.Siren_Music, this.getX() + extraX + this.random.nextFloat() - 0.5, this.getY() + extraY + this.random.nextFloat() - 0.5, this.getZ() + extraZ + this.random.nextFloat() - 0.5, 0, 0, 0);
                }
            }
        }
        if (this.isActuallySinging() && !this.isInWater() && this.tickCount % 200 == 0) {
            this.playSound(IafSoundRegistry.SIREN_SONG, 2, 1);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public void onUpdate() {
		super.onUpdate();

		if(!this.world.isRemote) {
			if(this.source == null) {
				this.setDead();
			} else {
				Entity shootingEntity;
				DamageSource damageSource;

				if(this.source instanceof EntityBLArrow) {
					shootingEntity = ((EntityBLArrow) this.source).getThrower();

					if(shootingEntity != null) {
						damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, shootingEntity);
					} else {
						damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, (EntityBLArrow) this.source);
					}
				} else if(this.source instanceof EntityLivingBase) {
					shootingEntity = null;
					damageSource = DamageSource.causeMobDamage((EntityLivingBase) this.source);
				} else {
					shootingEntity = null;
					damageSource = DamageSource.GENERIC;
				}

				List<Pair<Entity, Entity>> chain = new ArrayList<>();

				if(this.jumps < this.maxJumps) {
					if(this.ticksExisted != 0 && this.ticksExisted % 3 == 0) {
						Set<EntityLivingBase> newTargets = new HashSet<>();

						entityLoop: for(Entity entity : this.targets) {
							boolean isWet = entity.isWet() || entity.isInWater() || this.world.isRainingAt(entity.getPosition().up());

							List<EntityLivingBase> entities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, entity.getEntityBoundingBox().grow(isWet ? 6 : 4), e -> {
								Entity riding = e.getLowestRidingEntity();

								//Passengers are handled further down
								if(riding != e && riding instanceof EntityLivingBase) {
									return false;
								}

								return true;	
							});

							if(entities.size() > 1) {
								Collections.sort(entities, (e1, e2) -> Double.compare(e1.getDistanceSq(entity), e2.getDistanceSq(entity)));

								for(int j = 1; j < entities.size(); j++) {
									EntityLivingBase newTarget = entities.get(j);

									if(!this.targets.contains(newTarget) && !newTargets.contains(newTarget)) {
										newTargets.add(newTarget);

										chain.add(Pair.of(entity, newTarget));

										float f = MathHelper.sqrt(this.source.motionX * this.source.motionX + this.source.motionY * this.source.motionY + this.source.motionZ * this.source.motionZ);

										float damage = this.damage;
										if(this.source instanceof EntityBLArrow) {
											damage = MathHelper.ceil((double)f * ((EntityBLArrow) this.source).getDamage());

											if (((EntityBLArrow) this.source).getIsCritical()) {
												damage += this.rand.nextInt((int)damage / 2 + 2);
											}
										}

										boolean blocked = false;

										for(ItemStack stack : newTarget.getEquipmentAndArmor()) {
											if(!stack.isEmpty() && stack.getItem() instanceof ItemRubberBoots) {
												stack.damageItem(2, newTarget);
												blocked = true;
											}
										}

										boolean wasShocked = false;

										if(!blocked) {
											wasShocked = newTarget.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);

											//Also zap all passengers >:)
											for(Entity passenger : newTarget.getRecursivePassengers()) {
												if(passenger instanceof EntityLivingBase && !this.targets.contains(passenger) && !newTargets.contains(passenger)) {
													passenger.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);
													newTargets.add((EntityLivingBase) passenger);
												}
											}
										}

										if(!wasShocked) {
											newTarget.addPotionEffect(ElixirEffectRegistry.EFFECT_SHOCKED.createEffect(newTarget instanceof EntityPlayer ? 30 : 80, 0, true, true));
										}

										continue entityLoop;
									}
								}
							}
						}

						this.targets.addAll(newTargets);

						TheBetweenlands.networkWrapper.sendToAllTracking(new MessageShockArrowHit(chain), this);

						this.jumps++;
					}
				} else {
					this.setDead();
				}
			}
		}
	}

public void tick() {
        super.tick();
        prevScreenShakeAmount = screenShakeAmount;
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        this.legSolver.update(this, this.yBodyRot, this.getScale());
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (screenShakeAmount > 0) {
            screenShakeAmount = Math.max(0, screenShakeAmount - 0.34F);
        }
        if (this.onGround() && !this.isInFluidType() && this.walkAnimation.speed() > 0.1F && !this.isBaby()) {
            float f = (float) Math.cos(this.walkAnimation.position() * 0.8F - 1.5F);
            if (Math.abs(f) < 0.2) {
                if (screenShakeAmount <= 0.3) {
                    this.playSound(ACSoundRegistry.TREMORSAURUS_STOMP.get(), 2, 1.0F);
                    this.shakeWater();
                }
                screenShakeAmount = 1F;
            }
        }
        if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
        }
        if(this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 5){
            this.playRoarSound();
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 40 && !this.isBaby()) {
            screenShakeAmount = 1F;
            roarScatterTime = 30;
            if (this.getAnimationTick() % 5 == 0 && level().isClientSide) {
                this.shakeWater();
            }
        }
        if (roarScatterTime > 0) {
            roarScatterTime--;
            scareMobs();
        }
        if (this.getAnimation() == ANIMATION_SPEAK && this.getAnimationTick() == 5) {
            actuallyPlayAmbientSound();
        }
        if (!level().isClientSide) {
            if (this.getDeltaMovement().horizontalDistance() < 0.05 && this.getAnimation() == NO_ANIMATION && !this.isDancing() && !this.isInSittingPose()) {
                if (random.nextInt(180) == 0) {
                    this.setAnimation(ANIMATION_SNIFF);
                }
                if (random.nextInt(600) == 0 && !this.isVehicle()) {
                    this.tryRoar();
                }
            }
            boolean held = false;
            if (riderHitEntity != null && this.getAnimation() == ANIMATION_BITE && this.getAnimationTick() > 10 && this.getAnimationTick() <= 12) {
                if (this.hasLineOfSight(riderHitEntity) && this.distanceTo(riderHitEntity) < this.getBbWidth() + riderHitEntity.getBbWidth() + 2.0D) {
                    riderHitEntity.hurt(riderHitEntity.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                    if (riderHitEntity instanceof LivingEntity living) {
                        living.knockback(0.5D, this.getX() - riderHitEntity.getX(), this.getZ() - riderHitEntity.getZ());
                    }
                    riderHitEntity = null;
                }
            }
            LivingEntity target = riderHitEntity instanceof LivingEntity ? (LivingEntity) riderHitEntity : this.getTarget();
            if (target != null && target.isAlive() && target.distanceTo(this) < (isVehicle() ? 10.0F : 5.5F)) {
                if (this.getAnimation() == ANIMATION_SHAKE_PREY && this.getAnimationTick() <= 35) {
                    held = true;
                    this.setHeldMobId(target.getId());
                }
            }
            if (!held && getHeldMobId() != -1) {
                this.setHeldMobId(-1);
                this.playSound(ACSoundRegistry.TREMORSAURUS_THROW.get());
                riderHitEntity = null;
            }
        } else {
            Player player = AlexsCaves.PROXY.getClientSidePlayer();
            if (player != null && player.isPassengerOfSameVehicle(this)) {
                if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
                }
                if (AlexsCaves.PROXY.isKeyDown(3) && (this.getAnimation() == NO_ANIMATION || this.getAnimation() == null)) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 3));
                }
            }
        }
        if (this.isVehicle()) {
            if (this.getMeterAmount() < 1.0F) {
                this.setMeterAmount(Math.min(this.getMeterAmount() + 0.0035F, 1.0F));
            }
        } else {
            this.setMeterAmount(0.0F);
        }
        if(this.getAnimation() == ANIMATION_SHAKE_PREY && getHeldMobId() != -1){
            Entity entity = level().getEntity(getHeldMobId());
            if(entity != null){
                if (this.getAnimationTick() <= 35) {
                    Vec3 shakePreyPos = getShakePreyPos();
                    Vec3 minus = new Vec3(shakePreyPos.x - entity.getX(), shakePreyPos.y - entity.getY(), shakePreyPos.z - entity.getZ());
                    entity.setDeltaMovement(minus);
                    if (this.getAnimationTick() % 10 == 0) {
                        entity.hurt(damageSources().mobAttack(this), 5 + this.getRandom().nextInt(2));
                    }
                }else{
                    entity.setDeltaMovement(entity.getDeltaMovement().scale(0.6F));
                }
            }
        }
        if (roarCooldown > 0) {
            roarCooldown--;
        }
        lastStompX = this.getX();
        lastStompZ = this.getZ();
    }

@Override
    public void aiStep() {
        super.aiStep();
        LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null && this.hasLineOfSight(attackTarget)) {
            int index = random.nextInt(getHeadCount());
            if (!isBreathing[index] && !isStriking[index]) {
                if (this.distanceTo(attackTarget) < 6) {
                    if (strikeCooldown == 0 && strikingProgress[index] == 0) {
                        isBreathing[index] = false;
                        isStriking[index] = true;
                        this.level.broadcastEntityEvent(this, (byte) (40 + index));
                        strikeCooldown = 3;
                    }
                } else if (random.nextBoolean() && breathCooldown == 0) {
                    isBreathing[index] = true;
                    isStriking[index] = false;
                    this.level.broadcastEntityEvent(this, (byte) (50 + index));
                    breathCooldown = 15;
                }

            }

        }
        for (int i = 0; i < HEADS; i++) {
            boolean striking = isStriking[i];
            boolean breathing = isBreathing[i];
            prevStrikeProgress[i] = strikingProgress[i];
            if (striking && strikingProgress[i] > 9) {
                isStriking[i] = false;
                if (attackTarget != null && this.distanceTo(attackTarget) < 6) {
                    attackTarget.hurt(DamageSource.mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                    attackTarget.addEffect(new MobEffectInstance(MobEffects.POISON, 100, 3, false, false));
                    attackTarget.knockback(0.25F, this.getX() - attackTarget.getX(), this.getZ() - attackTarget.getZ());
                }
            }
            if (breathing) {
                if (tickCount % 7 == 0 && attackTarget != null && i < this.getHeadCount()) {
                    Vec3 Vector3d = this.getViewVector(1.0F);
                    if (random.nextFloat() < 0.2F) {
                        this.playSound(IafSoundRegistry.HYDRA_SPIT, this.getSoundVolume(), this.getVoicePitch());
                    }
                    double headPosX = this.headBoxes[i].getX() + Vector3d.x;
                    double headPosY = this.headBoxes[i].getY() + 1.3F;
                    double headPosZ = this.headBoxes[i].getZ() + Vector3d.z;
                    double d2 = attackTarget.getX() - headPosX + this.random.nextGaussian() * 0.4D;
                    double d3 = attackTarget.getY() + attackTarget.getEyeHeight() - headPosY + this.random.nextGaussian() * 0.4D;
                    double d4 = attackTarget.getZ() - headPosZ + this.random.nextGaussian() * 0.4D;
                    EntityHydraBreath entitylargefireball = new EntityHydraBreath(IafEntityRegistry.HYDRA_BREATH.get(),
                        level, this, d2, d3, d4);
                    entitylargefireball.setPos(headPosX, headPosY, headPosZ);
                    if (!level.isClientSide) {
                        level.addFreshEntity(entitylargefireball);
                    }
                }
                if (isBreathing[i] && (attackTarget == null || !attackTarget.isAlive() || breathTicks[i] > 60) && !level.isClientSide) {
                    isBreathing[i] = false;
                    breathTicks[i] = 0;
                    breathCooldown = 15;
                    this.level.broadcastEntityEvent(this, (byte) (60 + i));
                }
                breathTicks[i]++;
            } else {
                breathTicks[i] = 0;
            }
            if (striking && strikingProgress[i] < 10.0F) {
                strikingProgress[i] += 2.5F;
            } else if (!striking && strikingProgress[i] > 0.0F) {
                strikingProgress[i] -= 2.5F;
            }
            prevSpeakingProgress[i] = speakingProgress[i];
            if (speakingProgress[i] > 0.0F) {
                speakingProgress[i] -= 0.1F;
            }
            prevBreathProgress[i] = breathProgress[i];
            if (breathing && breathProgress[i] < 10.0F) {
                breathProgress[i] += 1.0F;
            } else if (!breathing && breathProgress[i] > 0.0F) {
                breathProgress[i] -= 1.0F;
            }

        }
        if (strikeCooldown > 0) {
            strikeCooldown--;
        }
        if (breathCooldown > 0) {
            breathCooldown--;
        }
        if (this.getHeadCount() == 1 && this.getSeveredHead() != -1) {
            this.setSeveredHead(-1);
        }
        if (this.getHeadCount() == 1 && !this.isOnFire()) {
            this.setHeadCount(2);
            this.setSeveredHead(1);
            onlyRegrowOneHeadNotTwo = true;
        }

        if (this.getSeveredHead() != -1 && this.getSeveredHead() < this.getHeadCount()) {
            this.setSeveredHead(Mth.clamp(this.getSeveredHead(), 0, this.getHeadCount() - 1));
            regrowHeadCooldown++;
            if (regrowHeadCooldown >= 100) {
                headDamageTracker[this.getSeveredHead()] = 0;
                this.setSeveredHead(-1);
                if (this.isOnFire()) {
                    this.setHeadCount(this.getHeadCount() - 1);
                } else {
                    this.playSound(IafSoundRegistry.HYDRA_REGEN_HEAD, this.getSoundVolume(), this.getVoicePitch());
                    if (!onlyRegrowOneHeadNotTwo) {
                        this.setHeadCount(this.getHeadCount() + 1);
                    }
                }
                onlyRegrowOneHeadNotTwo = false;
                regrowHeadCooldown = 0;
            }
        } else {
            regrowHeadCooldown = 0;
        }
    }

public void attackTargetEntityWithCurrentItem(Entity targetEntity, Player player, float damageMult, float knockbackMult) {
        if (!CommonHooks.onPlayerAttackTarget(player, targetEntity) || !targetEntity.isAttackable()) {
            return;
        }

        ItemStack oldStack = player.getMainHandItem();
        ItemStack newStack = getAxeStack();
        resetModifiers(player, oldStack, newStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, newStack);

        // Check this after swapping main hand in cases the main hand item impacts the result
        if (targetEntity.skipAttackInteraction(player)) {
            resetModifiers(player, newStack, oldStack);
            player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
            return;
        }

        if (targetEntity.getType().is(EntityTypeTags.REDIRECTABLE_PROJECTILE) && targetEntity instanceof Projectile projectile && projectile.deflect(ProjectileDeflection.AIM_DEFLECT, this, this, true)) {
            this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, this.getSoundSource());
            resetModifiers(player, newStack, oldStack);
            player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
            return;
        }

        DamageSource damageSource = damageSources().playerAttack(player);

        float attackDamage = (float) player.getAttributeValue(Attributes.ATTACK_DAMAGE) * damageMult;
        float enchantedDamage = player.getEnchantedDamage(targetEntity, attackDamage, damageSource);

        if (attackDamage > 0 || enchantedDamage > 0) {
            boolean wasSprinting = false;

            if (player.isSprinting()) {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_KNOCKBACK, player.getSoundSource(), 1.0F, 1.0F);
                wasSprinting = true;
            }

            attackDamage += newStack.getItem().getAttackDamageBonus(targetEntity, attackDamage, damageSource);
            float damage = attackDamage + enchantedDamage;
            float targetHealth = targetEntity instanceof LivingEntity livingTarget ? livingTarget.getHealth() : 0;

            Vec3 targetMovement = targetEntity.getDeltaMovement();
            boolean wasHurt = targetEntity.hurt(damageSource, damage);

            if (wasHurt) {
                float knockback = player.getKnockback(targetEntity, damageSource) + (wasSprinting ? 1 : 0);

                if (knockback > 0) {
                    if (targetEntity instanceof LivingEntity livingTarget) {
                        livingTarget.knockback(knockback * 0.5F * knockbackMult, Mth.sin(player.getYRot() * ((float) Math.PI / 180F)), -Mth.cos(player.getYRot() * ((float) Math.PI / 180F)));
                    } else {
                        targetEntity.push(-Mth.sin(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult, 0.1D, Mth.cos(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult);
                    }

                    player.setDeltaMovement(player.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
                    player.setSprinting(false);
                }

                if (targetEntity instanceof ServerPlayer && targetEntity.hurtMarked) {
                    ((ServerPlayer) targetEntity).connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
                    targetEntity.hurtMarked = false;
                    targetEntity.setDeltaMovement(targetMovement);
                }

                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_STRONG, player.getSoundSource(), 1.0F, 1.0F);

                if (enchantedDamage > 0) {
                    player.magicCrit(targetEntity);
                }

                player.setLastHurtMob(targetEntity);
                Entity entity = targetEntity;

                if (targetEntity instanceof PartEntity<?> part) {
                    entity = part.getParent();
                }

                ItemStack copy = newStack.copy();
                boolean hurtEnemy = false;

                if (level() instanceof ServerLevel serverLevel) {
                    if (entity instanceof LivingEntity livingEntity) {
                        hurtEnemy = newStack.hurtEnemy(livingEntity, player);
                    }

                    EnchantmentHelper.doPostAttackEffects(serverLevel, targetEntity, damageSource);
                }

                if (!level().isClientSide() && !copy.isEmpty() && entity instanceof LivingEntity livingEntity) {
                    if (hurtEnemy) {
                        newStack.postHurtEnemy(livingEntity, player);
                    }

                    if (newStack.isEmpty()) {
                        EventHooks.onPlayerDestroyItem(player, copy, InteractionHand.MAIN_HAND);
                        player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    }
                }

                if (targetEntity instanceof LivingEntity livingTarget) {
                    float healthDifference = targetHealth - livingTarget.getHealth();
                    player.awardStat(Stats.DAMAGE_DEALT, Math.round(healthDifference * 10));

                    if (level() instanceof ServerLevel serverLevel && healthDifference > 2) {
                        int particleCount = (int) ((double) healthDifference * 0.5);
                        serverLevel.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0.0, 0.1, 0.2);
                    }
                }

                player.causeFoodExhaustion(0.1F);
            } else {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, player.getSoundSource(), 1.0F, 1.0F);
            }
        }

        resetModifiers(player, newStack, oldStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
    }

@Override
	protected void onHitEntity(EntityRayTraceResult rayTrace) {
		Entity target = rayTrace.getEntity();
		float drawPower = (float)this.getDeltaMovement().length();
		double damage = getBaseDamage();
		boolean critical = isCritArrow();

		if (bow != null) {
			damage = bow.getArrowDamage(this, target, damage, drawPower, critical);
		}
		else if (crossbow != null) {
			damage = crossbow.getArrowDamage(this, target, damage, drawPower, critical);
		}

		damage = Math.max(damage, 0.0D);

		if (getPierceLevel() > 0) {
			if (piercingIgnoreEntityIds == null)
				piercingIgnoreEntityIds = new IntOpenHashSet(5);

			if (piercedAndKilledEntities == null)
				piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);

			if (piercingIgnoreEntityIds.size() >= getPierceLevel() + 1) {
				remove();

				return;
			}

			piercingIgnoreEntityIds.add(target.getId());
		}

		Entity shooter = this.getOwner();
		DamageSource source;

		if (shooter == null) {
			source = DamageSource.arrow(this, this);
		}
		else {
			source = DamageSource.arrow(this, shooter);

			if (shooter instanceof LivingEntity)
				((LivingEntity)shooter).setLastHurtMob(target);
		}

		boolean isEnderman = target.getType() == EntityType.ENDERMAN;
		int fireTimer = target.getRemainingFireTicks();

		if (isOnFire() && !isEnderman)
			target.setSecondsOnFire(5);

		if (target.hurt(source, (float)damage)) {
			if (isEnderman)
				return;

			if (bow != null) {
				bow.onEntityHit(this, target, shooter, damage, drawPower);
			}
			else if (crossbow != null) {
				crossbow.onEntityHit(this, target, shooter, damage, drawPower);
			}

			if (target instanceof LivingEntity) {
				LivingEntity livingTarget = (LivingEntity)target;

				if (!level.isClientSide && getPierceLevel() <= 0)
					livingTarget.setArrowCount(livingTarget.getArrowCount() + 1);

				if (knockback > 0) {
					Vector3d Vector3d = getDeltaMovement().multiply(1.0D, 0.0D, 1.0D).normalize().scale(knockback * 0.6D);

					if (Vector3d.lengthSqr() > 0.0D)
						livingTarget.push(Vector3d.x, 0.1D, Vector3d.z);
				}

				if (!level.isClientSide && shooter instanceof LivingEntity) {
					EnchantmentHelper.doPostHurtEffects(livingTarget, shooter);
					EnchantmentHelper.doPostDamageEffects((LivingEntity)shooter, livingTarget);
				}

				doPostHurtEffects(livingTarget);

				if (livingTarget != shooter && livingTarget instanceof PlayerEntity && shooter instanceof ServerPlayerEntity)
					((ServerPlayerEntity)shooter).connection.send(new SChangeGameStatePacket(SChangeGameStatePacket.ARROW_HIT_PLAYER, 0.0F));

				if (!target.isAlive() && piercedAndKilledEntities != null)
					piercedAndKilledEntities.add(livingTarget);

				if (!level.isClientSide && shooter instanceof ServerPlayerEntity) {
					ServerPlayerEntity serverplayerentity = (ServerPlayerEntity)shooter;

					if (piercedAndKilledEntities != null && shotFromCrossbow()) {
						CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayerentity, this.piercedAndKilledEntities);
					}
					else if (!target.isAlive() && shotFromCrossbow()) {
						CriteriaTriggers.KILLED_BY_CROSSBOW.trigger(serverplayerentity, Arrays.asList(target));
					}
				}
			}

			playSound(getHitGroundSoundEvent(), 1.0F, 1.2F / (random.nextFloat() * 0.2F + 0.9F));

			if (getPierceLevel() <= 0)
				remove();
		}
		else {
			target.setRemainingFireTicks(fireTimer);
			setDeltaMovement(getDeltaMovement().scale(-0.1D));

			yRot += 180.0F;
			yRotO += 180.0F;

			if (!level.isClientSide && getDeltaMovement().lengthSqr() < 0.0000001) {
				if (pickup == PickupStatus.ALLOWED)
					spawnAtLocation(getPickupItem(), 0.1F);

				remove();
			}
		}
	}

@Override
	public void tick() {
		super.tick();
		prevRightPunchProgress = rightPunchProgress;
		prevLeftPunchProgress = leftPunchProgress;
		prevLaserX = this.getLaserX();
		prevLaserY = this.getLaserY();
		prevLaserZ = this.getLaserZ();
		prevLaserProgress = laserProgress;
		if (laserProgress < 1.0F && this.isUsingBeamAttack() && !this.isUsingRegularAttack()) {
			laserProgress += 0.1F;
		}
		if (laserProgress > 0.0F && (!this.isUsingBeamAttack() || this.isUsingRegularAttack())) {
			laserProgress -= 0.1F;
		}
		if (getTarget() != null) {
			targetDistance = distanceTo(getTarget()) - getTarget().getBbWidth() / 2f;
			targetAngle = (float) getAngleBetweenEntities(this, getTarget());
		}
		if (getTarget() != null && (!getTarget().isAlive() || getTarget().getHealth() <= 0))
			setTarget(null);
		if (!level().isClientSide()) {
			if (!isNoAi()) {
				if (isActive()) {
					if (getTarget() == null) {
						setActive(false);
					}
				} else if (getTarget() != null && targetDistance <= 30 || getTarget() != null && targetDistance <= 30) {
					setActive(true);
				}
				if(this.getHealthRatio() < 0.5F && shieldCooldown == 0 && !this.hasHealingShield()){
					shieldCooldown = 300 + random.nextInt(300);
					this.setHealingShield(3);
				}
			}
		}
		if (!isActive()) {
			setDeltaMovement(0, getDeltaMovement().y, 0);
			yRot = yRotO;
			if (this.getHealth() < this.getMaxHealth()) {
				this.setHealingShield(1);
			}
			if (this.getHealth() == this.getMaxHealth()) {
				this.setHealingShield(0);
			}
		}
		yBodyRot = yHeadRot;
		if (!level().isClientSide() && hasHealingShield()){
			if(this.getTarget() == null){
				this.heal(0.3F);
			}else{
				double dist = this.distanceTo(this.getTarget());
				if(dist > 16.0F){
					this.heal(3F);
				}else{
					this.heal((float)Mth.clamp(dist * 0.085F, 0.2F, 3F));
				}
			}
		}
		if (this.entityData.get(MELEE_TICK) > 0 && isUsingRegularAttack()) {
			if (Math.max(rightPunchProgress, leftPunchProgress) == 5 && this.getTarget() != null && this.distanceTo(this.getTarget()) < this.getTarget().getBbWidth() + this.getBbWidth() + 2.0F) {
				this.getTarget().hurt(this.damageSources().mobAttack(this), 2);
				if (this.getTarget().isBlocking()) {
					((Player)this.getTarget()).getCooldowns().addCooldown(Items.SHIELD, 100);
					((Player)this.getTarget()).stopUsingItem();
					this.level().broadcastEntityEvent(((Player)this.getTarget()), (byte)30);
				}
			}
			this.entityData.set(MELEE_TICK, this.entityData.get(MELEE_TICK) - 1);
			if (this.entityData.get(MELEE_TICK) == 0) {
				usingLeftHand = !usingLeftHand;
			}
			if (!usingLeftHand && rightPunchProgress < 5F) {
				rightPunchProgress += 2.5F;
			}
			if (usingLeftHand && leftPunchProgress < 5F) {
				leftPunchProgress += 2.5F;
			}
		} else {
			if (leftPunchProgress > 0F) {
				leftPunchProgress -= Math.min(0.5F, leftPunchProgress);
			}
			if (rightPunchProgress > 0F) {
				rightPunchProgress -= Math.min(0.5F, rightPunchProgress);
			}
		}
		if (usingLeftHand) {
			if (rightPunchProgress > 0F) {
				rightPunchProgress--;
			}
		} else {
			if (leftPunchProgress > 0F) {
				leftPunchProgress--;
			}
		}
		if (this.isUsingBeamAttack()) {
			double d0 = this.getLaserX() - this.getX();
			double d1 = this.getLaserY() - this.getY(1);
			double d2 = this.getLaserZ() - this.getZ();
			double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
			d0 = d0 / d3;
			d1 = d1 / d3;
			d2 = d2 / d3;
			double d4 = this.random.nextDouble();
			while (d4 < d3) {
				d4 += 3.0D - this.random.nextDouble() * 2.5D;
				this.level().addParticle(PFParticles.BOSS_LASER.get(), this.getX() + d0 * d4, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4, (random.nextFloat() - 0.5F) * 0.1F, random.nextFloat() * 0.2F, (random.nextFloat() - 0.5F) * 0.1F);
			}
		}
		if(this.hasHealingShield() && level().isClientSide()){
			for(int i = 0; i < 2 + random.nextInt(2); i++){
				this.level().addParticle(PFParticles.BOSS_HEAL.get(), this.getRandomX(2.0D), this.getY(), this.getRandomZ(2.0D), this.getX(), this.getY(0.75F), this.getZ());
			}
		}
		if (this.getLaserTick() < 0) {
			this.setLaserTick(this.getLaserTick() + 1);
		}
		if(shieldCooldown > 0 && !this.hasHealingShield()){
			shieldCooldown--;
		}
	}

public void tick() {
        super.tick();
        prevOpenProgress = openProgress;
        prevClutchProgress = clutchProgress;
        prevBiteProgress = biteProgress;
        prevCosmawPitch = this.getCosmawPitch();
        if (!this.level().isClientSide) {
            final float f2 = (float) -((float) this.getDeltaMovement().y * Mth.RAD_TO_DEG);
            this.setCosmawPitch(this.getCosmawPitch() + 0.6F * (this.getCosmawPitch() + f2) - this.getCosmawPitch());
        }

        if (isMouthOpen()) {
            if (openProgress < 5F)
                openProgress++;
        } else {
            if (openProgress > 0F)
                openProgress--;
        }

        if (isVehicle()) {
            if (clutchProgress < 5F)
                clutchProgress++;
        } else {
            if (clutchProgress > 0F)
                clutchProgress--;
        }

        if (this.entityData.get(ATTACK_TICK) > 0) {
            if (biteProgress < 5F) {
                biteProgress = Math.min(5F, biteProgress + 2F);
            } else {
                if (this.getTarget() != null && this.distanceTo(this.getTarget()) < 3.3D) {
                    if (this.getTarget() instanceof EntityCosmicCod && !this.isTame()) {
                        EntityCosmicCod fish = (EntityCosmicCod) this.getTarget();
                        CompoundTag fishNbt = new CompoundTag();
                        fish.addAdditionalSaveData(fishNbt);
                        fishNbt.putString("DeathLootTable", BuiltInLootTables.EMPTY.toString());
                        fish.readAdditionalSaveData(fishNbt);
                    }
                    this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                }
                this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            }
        } else {
            if (biteProgress > 0F) {
                biteProgress -= 1F;
            }
        }
        if (!this.getMainHandItem().isEmpty()) {
            heldItemTime++;
            if (heldItemTime > 30 && canTargetItem(this.getMainHandItem())) {
                heldItemTime = 0;
                this.heal(4);
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.DOLPHIN_EAT, this.getSoundVolume(), this.getVoicePitch());
                if (this.getMainHandItem().is(AMTagRegistry.COSMAW_TAMEABLES) && fishThrowerID != null && !this.isTame()) {
                    if (getRandom().nextFloat() < 0.3F) {
                        this.setTame(true);
                        this.setCommand(1);
                        this.setOwnerUUID(this.fishThrowerID);
                        Player player = level().getPlayerByUUID(fishThrowerID);
                        if (player instanceof ServerPlayer) {
                            CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer) player, this);
                        }
                        this.level().broadcastEntityEvent(this, (byte) 7);
                    } else {
                        this.level().broadcastEntityEvent(this, (byte) 6);
                    }
                }
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.getMainHandItem().shrink(1);
            }
        } else {
            heldItemTime = 0;
        }
        if (!this.level().isClientSide) {
            if (tickCount % 100 == 0 || lastSafeTpPosition == null) {
                BlockPos pos = getCosmawGround(this.blockPosition());
                if (pos.getY() > 1) {
                    lastSafeTpPosition = pos;
                }
            }

            if (this.isVehicle()) {
                if (lastSafeTpPosition != null) {
                    final double dist = this.distanceToSqr(Vec3.atCenterOf(lastSafeTpPosition));
                    float speed = 0.8F;
                    if(this.getY() < -40){
                        speed = 3F;
                    }
                    if (verticalCollision && dist > 14) {
                        this.setYRot(this.stuckRot);
                        if (random.nextInt(50) == 0) {
                            this.stuckRot = Mth.wrapDegrees(this.stuckRot + 90);

                        }
                        final float angle = (Maths.STARTING_ANGLE * stuckRot);
                        final double extraX = -2 * Mth.sin(Mth.PI + angle);
                        final double extraZ = -2 * Mth.cos(angle);
                        this.getMoveControl().setWantedPosition(this.getX() + extraX, this.getY() + 2, this.getZ() + extraZ, speed);
                    } else if (lastSafeTpPosition.getY() > this.getY() + 2.3F) {
                        this.getMoveControl().setWantedPosition(this.getX(), this.getY() + 2, this.getZ(), speed);
                    } else {
                        this.getMoveControl().setWantedPosition(lastSafeTpPosition.getX(), lastSafeTpPosition.getY() + 2, lastSafeTpPosition.getZ(), speed);
                    }
                    if (dist < 7 && getCosmawGround(this.blockPosition()).getY() > 1) {
                        this.ejectPassengers();
                    }
                } else {
                    if (this.getY() < 0F) {
                        this.getDeltaMovement().add(0, 0.75F, 0);
                    } else if (this.getY() < 80F) {
                        this.getDeltaMovement().add(0, 0.1F, 0);
                    }
                }

            }
        }

    }

public void tick() {
        super.tick();
        prevSitProgress = sitProgress;
        prevSleepProgress = sleepProgress;
        prevHoldProgress = holdProgress;
        prevStealthProgress = stealthProgress;

        final boolean sitting = isSitting();
        final boolean sleeping = isSleeping();
        final boolean holding = isHolding();
        final boolean stealth = isStealth();

        if (sitting) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (sleeping) {
            if (sleepProgress < 5F)
                sleepProgress++;
        } else {
            if (sleepProgress > 0F)
                sleepProgress--;
        }

        if (holding) {
            if (holdProgress < 5F)
                holdProgress++;
        } else {
            if (holdProgress > 0F)
                holdProgress--;
        }

        if (stealth) {
            if (stealthProgress < 10F)
                stealthProgress += 0.25F;
        } else {
            if (stealthProgress > 0F)
                stealthProgress--;
        }

        if (!this.level().isClientSide) {
            if (isRunning() && !hasSpedUp) {
                hasSpedUp = true;
                this.setMaxUpStep(1F);
                this.setSprinting(true);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.4F);
            }
            if (!isRunning() && hasSpedUp) {
                hasSpedUp = false;
                this.setMaxUpStep(0.6F);
                this.setSprinting(false);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
            if ((isSitting() || isSleeping()) && (++sittingTime > maxSitTime || this.getTarget() != null || this.isInLove() || dontSitFlag || this.isInWaterOrBubble())) {
                this.setSitting(false);
                this.setSleeping(false);
                sittingTime = 0;
                maxSitTime = 100 + random.nextInt(50);
            }
            if (this.getTarget() == null && !dontSitFlag && this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSleeping() && !this.isSitting() && !this.isInWaterOrBubble() && random.nextInt(100) == 0) {
                sittingTime = 0;
                if (this.getRandom().nextBoolean()) {
                    maxSitTime = 100 + random.nextInt(550);
                    this.setSitting(true);
                    this.setSleeping(false);
                } else {
                    maxSitTime = 200 + random.nextInt(550);
                    this.setSitting(false);
                    this.setSleeping(true);
                }
            }
            if (this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSleeping() && !this.isSitting() && random.nextInt(100) == 0) {
                this.setAnimation(ANIMATION_TAIL_FLICK);
            }
        }
        if (this.isHolding()) {
            this.setSprinting(false);
            this.setRunning(false);
            Entity target = this.getTarget();
            if (!this.level().isClientSide && target != null && target.isAlive()) {
                this.setXRot(0);
                final float radius = 1.0F + target.getBbWidth() * 0.5F;
                final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                final double extraX = radius * Mth.sin(Mth.PI + angle);
                final double extraZ = radius * Mth.cos(angle);
                final double extraY = -0.5F;
                Vec3 minus = new Vec3(this.getX() + extraX - target.getX(), this.getY() + extraY - target.getY(), this.getZ() + extraZ - target.getZ());
                target.setDeltaMovement(minus);
                target.hasImpulse = true;
                if (holdTime % 20 == 0) {
                    target.hurt(this.damageSources().mobAttack(this), 5 + this.getRandom().nextInt(2));
                }
                if(target.distanceTo(this) > 8.0F){
                    this.setHolding(false);
                    holdTime = 150;
                }
            }
            holdTime++;
            if (holdTime > 100) {
                holdTime = 0;
                this.setHolding(false);
            }
        } else {
            holdTime = 0;
        }
        if (prevScaredMobId != this.entityData.get(LAST_SCARED_MOB_ID) && this.level().isClientSide) {
            Entity e = level().getEntity(this.entityData.get(LAST_SCARED_MOB_ID));
            if (e != null) {
                final double d2 = this.random.nextGaussian() * 0.1D;
                final double d0 = this.random.nextGaussian() * 0.1D;
                final double d1 = this.random.nextGaussian() * 0.1D;
                this.level().addParticle(AMParticleRegistry.SHOCKED.get(), e.getX(), e.getEyeY() + e.getBbHeight() * 0.15F + (double) (this.random.nextFloat() * e.getBbHeight() * 0.15F), e.getZ(), d0, d1, d2);
            }
        }
        if(this.getTarget() != null && this.getTarget().hasEffect(AMEffectRegistry.TIGERS_BLESSING.get())){
            this.setTarget(null);
            this.setLastHurtByMob(null);
        }
        prevScaredMobId = this.entityData.get(LAST_SCARED_MOB_ID);
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void onUpdate(){

		super.onUpdate();

		// System.out.println("Client side: " + this.world.isRemote + ", Caster: " + this.caster);

		// Particle effect. Finishes 40 ticks before the end so the particles disappear at the same time.
		if(this.ticksExisted + 40 < this.lifetime){
			for(int i = 0; i < 5; i++){
				// this.world.spawnParticle(EnumParticleTypes.PORTAL, this.posX + (this.rand.nextDouble() - 0.5D) *
				// (double)this.width, this.posY + this.rand.nextDouble() * (double)this.height - 0.75D, this.posZ +
				// (this.rand.nextDouble() - 0.5D) * (double)this.width, (this.rand.nextDouble() - 0.5D) * 2.0D,
				// -this.rand.nextDouble(), (this.rand.nextDouble() - 0.5D) * 2.0D);
				this.world.spawnParticle(EnumParticleTypes.PORTAL, this.posX, this.posY, this.posZ,
						(this.rand.nextDouble() - 0.5D) * 4.0D, (this.rand.nextDouble() - 0.5D) * 4.0D - 1,
						(this.rand.nextDouble() - 0.5D) * 4.0D);
			}
		}

		if(this.lifetime - this.ticksExisted == 75){
			this.playSound(WizardrySounds.ENTITY_BLACK_HOLE_VANISH, 1.5f, 1.0f);
		}else if(this.ticksExisted % 80 == 1 && this.ticksExisted + 80 < this.lifetime){
			this.playSound(WizardrySounds.ENTITY_BLACK_HOLE_AMBIENT, 1.5f, 1.0f);
		}

		if(!this.world.isRemote){

			double radius = 2 * height * sizeMultiplier;

			boolean suckInBlocks = getCaster() instanceof EntityPlayer && EntityUtils.canDamageBlocks(getCaster(), world)
					&& ItemArtefact.isArtefactActive((EntityPlayer)getCaster(), WizardryItems.charm_black_hole);

			if(suckInBlocks){

				List<BlockPos> sphere = BlockUtils.getBlockSphere(new BlockPos(this), radius);

				int blocksUnhooked = 0;

				for(BlockPos pos : sphere){

					if(rand.nextInt(Math.max(1, (int)this.getDistanceSq(pos) * 3)) == 0){

						if(!BlockUtils.isBlockUnbreakable(world, pos) && !world.isAirBlock(pos)
								&& world.isBlockNormalCube(pos, false) && BlockUtils.canBreakBlock(getCaster(), world, pos)){
							// Checks that the block above is not solid, since this causes the falling block to vanish.
//							&& !world.isBlockNormalCube(pos.up(), false)){

							EntityFallingBlock fallingBlock = new EntityLevitatingBlock(world, pos.getX() + 0.5,
									pos.getY() + 0.5, pos.getZ() + 0.5, world.getBlockState(pos));
//							fallingBlock.noClip = true;
							fallingBlock.fallTime = 1; // Prevent it from trying to delete the block itself
							world.spawnEntity(fallingBlock);
							world.setBlockToAir(pos);

							if(++blocksUnhooked >= BLOCK_UNHOOK_LIMIT) break; // Lag prevention
						}
					}
				}

			}

			List<Entity> targets = EntityUtils.getEntitiesWithinRadius(radius, this.posX, this.posY,
					this.posZ, this.world, Entity.class);

			targets.removeIf(t -> !(t instanceof EntityLivingBase || (suckInBlocks && t instanceof EntityFallingBlock)));

			for(Entity target : targets){

				if(this.isValidTarget(target)){

					// If the target can't be moved, it isn't sucked in but is still damaged if it gets too close
					if(!(target instanceof EntityPlayer && ((getCaster() instanceof EntityPlayer && !Wizardry.settings.playersMoveEachOther)
							|| ItemArtefact.isArtefactActive((EntityPlayer)target, WizardryItems.amulet_anchoring)))){

						EntityUtils.undoGravity(target);
						if(target instanceof EntityLevitatingBlock) ((EntityLevitatingBlock)target).suspend();

						// Sucks the target in
						if(this.posX > target.posX && target.motionX < 1){
							target.motionX += SUCTION_STRENGTH;
						}else if(this.posX < target.posX && target.motionX > -1){
							target.motionX -= SUCTION_STRENGTH;
						}

						if(this.posY > target.posY && target.motionY < 1){
							target.motionY += SUCTION_STRENGTH;
						}else if(this.posY < target.posY && target.motionY > -1){
							target.motionY -= SUCTION_STRENGTH;
						}

						if(this.posZ > target.posZ && target.motionZ < 1){
							target.motionZ += SUCTION_STRENGTH;
						}else if(this.posZ < target.posZ && target.motionZ > -1){
							target.motionZ -= SUCTION_STRENGTH;
						}

						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}
					}

					if(this.getDistance(target) <= 2){
						// Damages the target if it is close enough, or destroys it if it's a block
						if(target instanceof EntityFallingBlock){
							target.playSound(WizardrySounds.ENTITY_BLACK_HOLE_BREAK_BLOCK, 0.5f,
									(rand.nextFloat() - rand.nextFloat()) * 0.2f + 1);
							IBlockState state = ((EntityFallingBlock)target).getBlock();
							if(state != null) world.playEvent(2001, new BlockPos(target), Block.getStateId(state));
							target.setDead();

						}else{
							if(this.getCaster() != null){
								target.attackEntityFrom(
										MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.MAGIC),
										2 * damageMultiplier);
							}else{
								target.attackEntityFrom(DamageSource.MAGIC, 2 * damageMultiplier);
							}
						}
					}
				}
			}
		}
	}

@Override
    public void render(SpiritCrucibleCoreBlockEntity blockEntityIn, float partialTicks, PoseStack poseStack, MultiBufferSource bufferIn, int combinedLightIn, int combinedOverlayIn) {
        renderModifiers(blockEntityIn, partialTicks, poseStack, bufferIn, combinedLightIn, combinedOverlayIn);

        Level level = Minecraft.getInstance().level;
        ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
        LodestoneItemStackHandler inventory = blockEntityIn.spiritInventory;
        int spiritsRendered = 0;
        if (!inventory.isEmpty()) {
            for (int i = 0; i < inventory.getSlotCount(); i++) {
                ItemStack item = inventory.getStackInSlot(i);
                if (item.getItem() instanceof SpiritShardItem shardItem) {
                    poseStack.pushPose();
                    Vector3f offset = blockEntityIn.getSpiritItemOffset(spiritsRendered++, partialTicks).toVector3f();
                    poseStack.translate(offset.x(), offset.y(), offset.z());
                    FloatingItemRenderer.renderSpiritGlimmer(poseStack, shardItem.getSpiritHolder(), partialTicks);
                    poseStack.mulPose(Axis.YP.rotationDegrees(((level.getGameTime() % 360) + partialTicks) * 3));
                    poseStack.scale(0.5f, 0.5f, 0.5f);
                    itemRenderer.renderStatic(item, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
                    poseStack.popPose();
                }
            }
        }
        ItemStack stack = blockEntityIn.inventory.getStackInSlot(0);
        if (!stack.isEmpty()) {
            poseStack.pushPose();
            Vec3 offset = SpiritCrucibleCoreBlockEntity.CRUCIBLE_ITEM_OFFSET;
            poseStack.translate(offset.x + 0.5f, offset.y + 0.5f, offset.z + 0.5f);
            poseStack.mulPose(Axis.YP.rotationDegrees(((level.getGameTime() % 360) + partialTicks) * 3));
            poseStack.scale(0.45f, 0.45f, 0.45f);
            itemRenderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
            poseStack.popPose();
        }
        stack = blockEntityIn.coreAugmentInventory.getStackInSlot(0);
        if (!stack.isEmpty()) {
            poseStack.pushPose();
            Vec3 offset = SpiritCrucibleCoreBlockEntity.CRUCIBLE_CORE_AUGMENT_OFFSET;
            poseStack.translate(offset.x + 0.5f, offset.y + 0.5f, offset.z + 0.5f);
            poseStack.mulPose(Axis.YP.rotationDegrees(((-level.getGameTime() % 360) - partialTicks) * 3));
            poseStack.scale(0.45f, 0.45f, 0.45f);
            itemRenderer.renderStatic(stack, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
            poseStack.popPose();
        }

        final LodestoneItemStackHandler augmentInventory = blockEntityIn.augmentInventory;

        int augmentsRendered = 0;
        if (!augmentInventory.isEmpty()) {
            float total = augmentInventory.getSlotCount();
            float time = 240;
            for (int i = 0; i < total; i++) {
                ItemStack item = augmentInventory.getStackInSlot(i);
                if (item.getItem() instanceof AugmentItem) {
                    double angle = augmentsRendered / total * (Math.PI * 2);
                    angle -= (((long) (blockEntityIn.spiritSpin + partialTicks) % time) / time) * (Math.PI * 2);
                    poseStack.pushPose();
                    Vector3f offset = blockEntityIn.getAugmentItemOffset(augmentsRendered++, partialTicks).toVector3f();
                    poseStack.translate(offset.x(), offset.y(), offset.z());
                    poseStack.mulPose(Axis.YP.rotation((float) angle - (i % 2 == 0 ? 4.71f : 1.57f)));
                    poseStack.scale(0.5f, 0.5f, 0.5f);
                    itemRenderer.renderStatic(item, ItemDisplayContext.FIXED, combinedLightIn, NO_OVERLAY, poseStack, bufferIn, level, 0);
                    poseStack.popPose();
                }
            }
        }
        if (FORK_TRACKER.isVisible()) {
            var accelerationData = blockEntityIn.getAttributes();
            var attributes = accelerationData.getExistingAttributesForTuning();
            var font = Minecraft.getInstance().font;
            float delta = FORK_TRACKER.getDelta(partialTicks);
            float eased = Easing.SINE_IN_OUT.ease(delta);
            float scale = 0.016F - (1 - eased) * 0.004f;
            poseStack.pushPose();
            poseStack.translate(0.5f, 2f, 0.55f);
            poseStack.mulPose(Minecraft.getInstance().getEntityRenderDispatcher().cameraOrientation());
            for (int i = 0; i < attributes.size(); i++) {
                var attributeType = attributes.get(i);
                var dataPrint = attributeType.getDataPrint(accelerationData);
                boolean important = attributeType.equals(accelerationData.tunedAttribute);
                MutableComponent dataText = Component.literal(" <" + dataPrint + ">");
                MutableComponent text = Component.translatable(attributeType.getLangKey());
                MutableComponent outlineText = Component.translatable(attributeType.getLangKey());
                if (important) {
                    dataText.withStyle(ChatFormatting.BOLD);
                    text = Component.literal("[").append(text).append(Component.literal("]")).withStyle(ChatFormatting.BOLD);
                    outlineText = Component.literal("[").append(outlineText).append(Component.literal("]")).withStyle(ChatFormatting.BOLD);
                }

                text.append(dataText).withStyle(ChatFormatting.AQUA);
                outlineText.append(dataText).withStyle(ChatFormatting.LIGHT_PURPLE);

                float f = (-font.width(text) / 2f);
                float xPos = 0 + f;
                poseStack.pushPose();
                poseStack.translate(0, i * 0.15f, 0);
                poseStack.scale(scale, -scale, -scale);
                Matrix4f pose = poseStack.last().pose();
                float alpha = 0.38f * eased;
                int color = ColorHelper.getColor(1, 1, 1, alpha);
                if (alpha > 0.02) { //For whatever reason Font#adjustColor gets considers alpha lesser than 3 to be "unset" and so it sets it to 255...
                    renderText(text, xPos, 0, color, pose);
                }
                alpha = 0.18f * eased;
                if (alpha > 0.02) {
                    color = ColorHelper.getColor(1, 1, 1, alpha);
                    renderText(text, xPos - 0.5f, 0, color, pose);
                    renderText(text, xPos - 0.5f, 0, color, pose);
                    renderText(text, xPos, 0.5f, color, pose);
                    renderText(text, xPos, -0.5f, color, pose);
                }
                alpha = 0.12f * eased;
                if (alpha > 0.02) {
                    color = ColorHelper.getColor(1, 1, 1, alpha);
                    renderText(text, xPos - 1, 0, color, pose);
                    renderText(outlineText, xPos + 1, 0, color, pose);
                    renderText(outlineText, xPos, 1, color, pose);
                    renderText(text, xPos, -1, color, pose);
                    renderText(outlineText, xPos - 0.5f, -0.5f, color, pose);
                    renderText(text, xPos - 0.5f, 0.5f, color, pose);
                    renderText(outlineText, xPos + 0.5f, 0.5f, color, pose);
                    renderText(text, xPos + 0.5f, -0.5f, color, pose);
                }
                poseStack.popPose();
            }
            poseStack.popPose();
        }
    }

public void tick() {
        super.tick();

        this.prevSwimProgress = swimProgress;

        final boolean ground = !this.isInWaterOrBubble();

        if (!ground && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (ground && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (ground && swimProgress > 0) {
            swimProgress--;
        }
        if (!ground && swimProgress < 5F) {
            swimProgress++;
        }
        if (!this.level().isClientSide) {
            if (isInWater()) {
                swimTimer++;
            } else {
                swimTimer--;
            }
        }

        prevHeadHeight = this.getHeadHeight();
        float neckBase = 5.5F;
        if (!this.isNoAi() && !this.isBaby()) {
            Vec3[] avector3d = new Vec3[this.allParts.length];
            for (int j = 0; j < this.allParts.length; ++j) {
                this.allParts[j].collideWithNearbyEntities();
                avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
            }
            float yaw = this.getYRot() * ((float) Math.PI / 180F);
            float neckContraction = 0.3F * Math.abs(getHeadHeight() / 3) + 0.5F * Math.abs(getHeadYaw(0) / 50F);

            for (int l = 0; l < this.theEntireNeck.length; ++l) {
                float f = l / ((float) this.theEntireNeck.length);
                float f1 = -(2.2F + l - f * neckContraction);
                float f2 = Mth.sin(yaw + (float) Math.toRadians(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
                float f3 = Mth.cos(yaw + (float) Math.toRadians(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
                this.setPartPosition(this.theEntireNeck[l], f2 * f1, neckBase + Math.sin(f * Math.PI * 0.5F) * (getHeadHeight() * -11.1F), -f3 * f1);
            }

            for (int l = 0; l < this.allParts.length; ++l) {
                this.allParts[l].xo = avector3d[l].x;
                this.allParts[l].yo = avector3d[l].y;
                this.allParts[l].zo = avector3d[l].z;
                this.allParts[l].xOld = avector3d[l].x;
                this.allParts[l].yOld = avector3d[l].y;
                this.allParts[l].zOld = avector3d[l].z;
            }
        }
        if (entityToLaunchId != -1 && this.isAlive()) {
            Entity launch = this.level().getEntity(entityToLaunchId);
            this.ejectPassengers();
            entityToLaunchId = -1;
            if (launch != null && !launch.isPassenger()) {
                if (launch instanceof LivingEntity) {
                    this.playSound(UPSounds.BRACHI_TOSS.get(), 0.5F, 0.5F);
                    launch.setPos(this.getEyePosition().add(0, 1, 0));
                    float rot = 180F + this.getYRot();
                    float strength = (float) (getLaunchStrength() * (1.0D - ((LivingEntity) launch).getAttributeValue(Attributes.KNOCKBACK_RESISTANCE)));
                    float x = Mth.sin(rot * ((float) Math.PI / 180F));
                    float z = -Mth.cos(rot * ((float) Math.PI / 180F));
                    if (!(strength <= 0.0D)) {
                        launch.hasImpulse = true;
                        Vec3 vec3 = this.getDeltaMovement();
                        Vec3 vec31 = vec3.add((new Vec3(x, 0.0D, z)).normalize().scale(strength));
                        launch.setDeltaMovement(vec31.x, strength, vec31.z);
                    }
                }
            }
        }
        if (this.isLaunching()) {
            Entity passenger = this.getControllingPassenger();
            if (passenger instanceof LivingEntity) {
                entityToLaunchId = passenger.getId();
                this.setLaunching(false);
                for (Entity rider : this.getPassengers()) {
                    if (rider instanceof Player player) {
                        player.addEffect(new MobEffectInstance(UPEffects.BRACHI_PROTECTION.get(), 200));
                    }
                }
            }
        }
        if (!level().isClientSide) {
            if (this.isVehicle()) {
                ridingTime++;
                if (ridingTime >= this.getMaxRidingTime()) {
                    this.setLaunching(true);
                    this.isLaunching();
                }
            } else {
                ridingTime = 0;
                this.setLaunching(false);
            }
            if (this.isAlive() && ridingTime > 0 && this.getDeltaMovement().horizontalDistanceSqr() > 0.1D && this.isLaunching()) {
                for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                    if (!(entity instanceof BrachiosaurusEntity) && !entity.isPassengerOfSameVehicle(this)) {
                        entity.hurt(this.damageSources().mobAttack(this), 4F + random.nextFloat() * 3.0F);
                        if (entity.onGround()) {
                            double d0 = entity.getX() - this.getX();
                            double d1 = entity.getZ() - this.getZ();
                            double d2 = Math.max(d0 * d0 + d1 * d1, 0.001D);
                            float f = 0.5F;
                            entity.push(d0 / d2 * f, f, d1 / d2 * f);
                        }
                    }
                }
            }
        }
        if ( headPeakCooldown == 0) {
            float low = getLowHeadHeight();
            this.setHeadHeight(this.getHeadHeight() + (0.5F + ((getLowHeadHeight() + getHighHeadHeight(low)) / 2F) - this.getHeadHeight()) * 0.2F);
        } else {
            if (getMaxFluidHeight() <= this.getBbHeight() * 0.5F && getMaxFluidHeight() >= this.getBbHeight() * 0.25F) {
                float mot = (float) this.getDeltaMovement().lengthSqr();
                this.setHeadHeight(Mth.clamp(this.getHeadHeight() + 0.1F - 0.2F * mot, 0, 2));
                headPeakCooldown = 5;
            }
        }

        this.TailKinematics.calculateTailAngles(this);
    }

public void tick() {
        prevFlyAngle = this.getFlyAngle();
        super.tick();
        prevAttackProgress = attackProgress;
        prevFlyProgress = flyProgress;
        prevSitProgress = sitProgress;
        prevDragProgress = dragProgress;
        prevDigProgress = digProgress;

        final boolean flying = this.isFlying();
        final boolean sitting = this.isSitting();
        final boolean dragging = this.isDragging();
        final boolean digging = this.isDigging();

        if (flying) {
            if (flyProgress < 5F)
                flyProgress++;
        } else {
            if (flyProgress > 0F)
                flyProgress--;
        }

        if (sitting) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (dragging) {
            if (dragProgress < 5F)
                dragProgress++;
        } else {
            if (dragProgress > 0F)
                dragProgress--;
        }

        if (digging) {
            if (digProgress < 5F)
                digProgress++;
        } else {
            if (digProgress > 0F)
                digProgress--;
        }

        if (flightSize && !flying) {
            this.refreshDimensions();
            flightSize = false;
        }
        if (!flightSize && isFlying()) {
            this.refreshDimensions();
            flightSize = true;
        }
        float threshold = 0.015F;
        if (isFlying() && this.yRotO - this.getYRot() > threshold) {
            this.setFlyAngle(this.getFlyAngle() + 5);
        } else if (isFlying() && this.yRotO - this.getYRot() < -threshold) {
            this.setFlyAngle(this.getFlyAngle() - 5);
        } else if (this.getFlyAngle() > 0) {
            this.setFlyAngle(Math.max(this.getFlyAngle() - 4, 0));
        } else if (this.getFlyAngle() < 0) {
            this.setFlyAngle(Math.min(this.getFlyAngle() + 4, 0));
        }
        this.setFlyAngle(Mth.clamp(this.getFlyAngle(), -30, 30));
        if (!this.level().isClientSide) {
            if (isFlying() && this.isLandNavigator) {
                switchNavigator(false);
            }
            if (!isFlying() && !this.isLandNavigator) {
                switchNavigator(true);
            }
            if (isFlying()) {
                if(timeFlying % 25 == 0){
                    this.playSound(AMSoundRegistry.TARANTULA_HAWK_WING.get(), this.getSoundVolume(), this.getVoicePitch());
                }
                timeFlying++;
                this.setNoGravity(true);
                if (this.isSitting() || this.isPassenger() || this.isInLove()) {
                    this.setFlying(false);
                }
            } else {
                timeFlying = 0;
                this.setNoGravity(false);
            }
            if (this.getTarget() != null && this.getTarget() instanceof Player && !this.isTame()) {
                this.entityData.set(ANGRY, true);
            } else {
                this.entityData.set(ANGRY, false);
            }
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if (isDigging() && level().getBlockState(this.getBlockPosBelowThatAffectsMyMovement()).canOcclude()) {
            BlockPos posit = this.getBlockPosBelowThatAffectsMyMovement();
            BlockState understate = level().getBlockState(posit);
            for (int i = 0; i < 4 + random.nextInt(2); i++) {
                final double particleX = posit.getX() + random.nextFloat();
                final double particleY = posit.getY() + 1F;
                final double particleZ = posit.getZ() + random.nextFloat();
                final double motX = this.random.nextGaussian() * 0.02D;
                final double motY = 0.1F + random.nextFloat() * 0.2F;
                final double motZ = this.random.nextGaussian() * 0.02D;
                level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, understate), particleX, particleY, particleZ, motX, motY, motZ);
            }
        }
        if(this.tickCount > 0 && tickCount % 300 == 0 && this.getHealth() < this.getMaxHealth()){
            this.heal(1);
        }
        if(!this.level().isClientSide && this.isDragging() && this.getPassengers().isEmpty() && !this.isDigging()){
            dragTime++;
            if(dragTime > 5000){
                dragTime = 0;
                for(Entity e : this.getPassengers()){
                    e.hurt(this.damageSources().mobAttack(this), 10);
                }
                this.ejectPassengers();
                this.setDragging(false);
            }
        }
    }

public void tick() {
        super.tick();
        if (!this.getItemInHand(InteractionHand.MAIN_HAND).isEmpty() && this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setEating(true);
            this.setOrderedToSit(true);
            this.setStanding(false);
        }
        if (isEating() && !this.canTargetItem(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setEating(false);
            eatingTime = 0;
            if (!forcedSit) {
                this.setOrderedToSit(true);
            }
        }
        if (isEating()) {
            eatingTime++;
            if (!this.getMainHandItem().is(ItemTags.LEAVES)) {
                for (int i = 0; i < 3; i++) {
                    double d2 = this.random.nextGaussian() * 0.02D;
                    double d0 = this.random.nextGaussian() * 0.02D;
                    double d1 = this.random.nextGaussian() * 0.02D;
                    this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
                }
            }
            if (eatingTime % 5 == 0) {
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.PANDA_EAT, this.getSoundVolume(), this.getVoicePitch());
            }
            if (eatingTime > 100) {
                ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
                if (!stack.isEmpty()) {
                    this.heal(4);
                    if (isTameableFood(stack) && bananaThrowerID != null) {
                        if (getRandom().nextFloat() < 0.3F) {
                            this.setTame(true);
                            this.setOwnerUUID(this.bananaThrowerID);
                            Player player = level().getPlayerByUUID(bananaThrowerID);
                            if (player instanceof ServerPlayer) {
                                CriteriaTriggers.TAME_ANIMAL.trigger((ServerPlayer)player, this);
                            }
                            this.level().broadcastEntityEvent(this, (byte) 7);
                        } else {
                            this.level().broadcastEntityEvent(this, (byte) 6);
                        }
                    }
                    if (stack.hasCraftingRemainingItem()) {
                        this.spawnAtLocation(stack.getCraftingRemainingItem());
                    }
                    stack.shrink(1);
                }
                eatingTime = 0;
            }
        }
        prevSitProgress = sitProgress;
        prevStandProgress = standProgress;

        if (this.isSitting()) {
            if (sitProgress < 10F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (this.isStanding()) {
            if (standProgress < 10F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        if (this.isPassenger() && this.getVehicle() instanceof EntityGorilla) {
            if(!this.isBaby()){
                this.removeVehicle();
            }else{
                EntityGorilla mount = (EntityGorilla) this.getVehicle();
                this.setYRot( mount.yBodyRot);
                this.yHeadRot = mount.yBodyRot;
                this.yBodyRot = mount.yBodyRot;
            }
        }
        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }
        if (!forcedSit && isSitting() && ++sittingTime > maxSitTime) {
            this.setOrderedToSit(false);
            sittingTime = 0;
            maxSitTime = 75 + random.nextInt(50);
        }
        if (!forcedSit && this.isSitting() && (this.getTarget() != null || this.isStanding()) && !this.isEating()) {
            this.setOrderedToSit(false);
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && !this.isStanding() && !this.isSitting() && random.nextInt(1500) == 0) {
            maxSitTime = 300 + random.nextInt(250);
            this.setOrderedToSit(true);
        }
        if (this.forcedSit && !this.isVehicle() && this.isTame()) {
            this.setOrderedToSit(true);
        }
        if (sitProgress == 0 && poundChestCooldown <= 0 && this.isSilverback() && random.nextInt(800) == 0 && this.getAnimation() == NO_ANIMATION && !this.isSitting() && !this.isNoAi() && this.getMainHandItem().isEmpty()) {
            this.setAnimation(ANIMATION_POUNDCHEST);
        }
        if (!this.level().isClientSide && this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 10) {
            float f1 = this.getYRot() * Mth.DEG_TO_RAD;
            this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
            getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        if (!hasSilverbackAttributes && isSilverback() && !isBaby()) {
            hasSilverbackAttributes = true;
            refreshDimensions();
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(50F);
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(10F);
            this.heal(50F);
        }
        if (hasSilverbackAttributes && !isSilverback() && !isBaby()) {
            hasSilverbackAttributes = false;
            refreshDimensions();
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(30F);
            this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(8F);
            this.heal(30F);
        }
        if(poundChestCooldown > 0){
            poundChestCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

