                double vecX = this.getX() + Math.cos(theta) * 8;
                double vecZ = this.getZ() + Math.sin(theta) * 8;
                AABB selection = new AABB(vecX - 1.5,this.getY()- 2,vecZ - 1.5, vecX + 1.5,this.getY() + this.getBbHeight(),vecZ + 1.5);
