                this.level().broadcastEntityEvent(this, (byte)4);
                this.sentSpikeEvent = true;
            }

            if (++this.lifeTicks > 70) {
                this.discard();
            }
        }

    }

@Override
	public void onUpdate() {
		if(!this.world.isRemote && (this.world.getDifficulty() == EnumDifficulty.PEACEFUL || (this.getOwner() != null && !this.getOwner().isEntityAlive()))) {
			this.setDead();
			return;
		}

		this.setTriangleSize(this.getTriangleSize());

		this.motionX = 0;
		this.motionY = 0;
		this.motionZ = 0;

		super.onUpdate();

		if(!this.world.isRemote) {
			this.despawnTicks++;
			if(this.despawnTicks >= this.getMaxDespawnTicks()) {
				this.setDead();
			}

			this.rotation += 1.0F;
			this.getDataManager().set(ROTATION, this.rotation);

			List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(this.getTriangleSize()*2, 0, this.getTriangleSize()*2));
			for(EntityLivingBase target : targets) {
				if(target != this.getOwner()) {
					Vec3d[] vertices = this.getTriangleVertices(1);

					if(EntityFortressBoss.rayTraceTriangle(new Vec3d(target.posX - this.posX, 1, target.posZ - this.posZ), new Vec3d(0, -2, 0), vertices[0], vertices[1], vertices[2])) {

						if(this.isPlayerControlled()) {
							IPuppetCapability cap = target.getCapability(CapabilityRegistry.CAPABILITY_PUPPET, null);

							Entity owner = this.getOwner();

							if(cap != null && cap.getPuppeteer() == owner && owner instanceof EntityPlayer) {
								EntityPlayer player = (EntityPlayer) owner;

								IPuppeteerCapability playerCap = player.getCapability(CapabilityRegistry.CAPABILITY_PUPPETEER, null);
								if(playerCap != null) {
									ProtectionShield shield = playerCap.getShield();

									if(shield != null) {
										float healthPercent = 0.3f;

										if(target.getHealth() * (1 - healthPercent) > 5.0f) {
											float healthCost = target.getHealth() * healthPercent;
											float prevHealth = target.getHealth();

											if(target.attackEntityFrom(DamageSource.MAGIC, healthCost) && (prevHealth - target.getHealth()) >= healthCost * 0.5f) {
												List<Integer> indices = new ArrayList<>();
												for(int i = 0; i < 20; i++) {
													indices.add(i);
												}
												Collections.shuffle(indices, this.rand);

												for(int index : indices) {
													if(!shield.isActive(index)) {
														shield.setActive(index, true);
														break;
													}
												}

												this.maxDespawnTicks = this.despawnTicks + 8;
											}
										}
									}
								}
							}
						} else if(target instanceof EntityPlayer)  {
							float damage = (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue();
							if(target.attackEntityFrom(DamageSource.MAGIC, damage) && this.getOwner() != null && this.getOwner() instanceof EntityLivingBase) {
								EntityLivingBase owner = (EntityLivingBase) this.getOwner();
								if(owner.getHealth() < owner.getMaxHealth() - damage) {
									owner.heal(damage * 3.0F);
								}
							}
						}

					}
				}
			}
		} else {
			this.prevRotation = this.rotation;
			this.rotation = this.getDataManager().get(ROTATION);

			for(int c = 0; c < 4; c++) {
				float r1 = this.world.rand.nextFloat();
				float r2 = this.world.rand.nextFloat();
				this.rotation += 15;
				Vec3d[] vertices = this.getTriangleVertices(1);
				this.rotation -= 15;
				double xc = 0, zc = 0;
				for(int i = 0; i < 3; i++) {
					Vec3d vertex = vertices[i];
					switch(i) {
					default:
					case 0:
						xc += vertex.x * (1 - Math.sqrt(r1));
						zc += vertex.z * (1 - Math.sqrt(r1));
						break;
					case 1:
						xc += (Math.sqrt(r1) * (1 - r2)) * vertex.x;
						zc += (Math.sqrt(r1) * (1 - r2)) * vertex.z;
						break;
					case 2:
						xc += (Math.sqrt(r1) * r2) * vertex.x;
						zc += (Math.sqrt(r1) * r2) * vertex.z;
						break;
					}
				}
				Vec3d rp = new Vec3d(xc, vertices[0].y, zc);

				double sx = this.posX + rp.x;
				double sy = this.posY + rp.y + 4;
				double sz = this.posZ + rp.z;
				double ex = this.posX + rp.x;
				double ey = this.posY + rp.y;
				double ez = this.posZ + rp.z;

				if(this.getOwner() != null) {
					sx = this.getOwner().posX;
					sy = this.getOwner().getEntityBoundingBox().minY + (this.getOwner().getEntityBoundingBox().maxY - this.getOwner().getEntityBoundingBox().minY) / 2.0D;
					sz = this.getOwner().posZ;
				}

				if(!this.isPlayerControlled()) {
					this.world.spawnParticle(EnumParticleTypes.PORTAL, sx, sy, sz, ex - sx, ey - sy, ez - sz);
				}
			}
		}
	}

public void tick() {
        super.tick();
        if (!this.isActivated()){
            int count = SpellConfig.RuptureDuration.get() / 3;
            if (this.tickCount % count == 0) {
                if (this.level.isClientSide) {
                    if (this.getAnimation() < 2) {
                        this.setAnimation(this.getAnimation() + 1);
                    }
                }
                this.playSound(ModSounds.RUMBLE.get(), 2.0F, this.random.nextFloat() + 0.75F);
            }
        } else {
            if (this.level.isClientSide) {
                if (this.tickCount % 20 == 0) {
                    if (this.isClosing) {
                        if (this.getAnimation() > 0) {
                            this.setAnimation(this.getAnimation() - 1);
                        }
                    } else {
                        if (this.getAnimation() < 7) {
                            this.setAnimation(this.getAnimation() + 1);
                        } else {
                            this.setAnimation(3);
                        }
                    }
                }
            }
        }
        if (!this.level.isClientSide) {
            if (this.warmUp <= 0) {
                if (!this.isActivated()) {
                    this.setActivated(true);
                    this.level.broadcastEntityEvent(this, (byte) 100);
                }
                if (!this.playEvent) {
                    this.playSound(ModSounds.VOID_RIFT_OPEN.get(), 5.0F, 1.0F);
                    ModNetwork.sendToALL(new SPlayLoopSoundPacket(this, ModSounds.VOID_RIFT.get(), 5.0F, 1.0F));
                    this.playEvent = true;
                }
                if (this.tickCount % 200 == 0){
                    this.playSound(SoundEvents.PORTAL_AMBIENT, 5.0F, 0.75F);
                }
                List<Entity> targets = new ArrayList<>();
                float range = 16.0F * (this.getSize() + 1.0F);
                /*if (!this.isClosing) {
                    int rangeInt = Mth.floor(range);
                    this.suckBlocks(rangeInt, rangeInt, rangeInt);
                }*/
                if (this.level instanceof ServerLevel serverWorld) {
                    ServerParticleUtil.gatheringParticles(ParticleTypes.PORTAL, this, serverWorld, (int)range);
                }
                for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox().inflate(range))) {
                    if (!(entity instanceof Endermite)) {
                        if (entity instanceof ModFallingBlock modFallingBlock && modFallingBlock.getMode() == ModFallingBlock.FallingBlockMode.DEBRIS){
                            targets.add(entity);
                            if (entity.distanceTo(this) <= 1.0F){
                                entity.discard();
                            }
                        }
                        if (this.getOwner() != null) {
                            if (!MobUtil.areAllies(this.getOwner(), entity) && MobUtil.getOwner(entity) != this.getOwner()) {
                                targets.add(entity);
                            }
                        } else {
                            targets.add(entity);
                        }
                    }
                }
                if (!targets.isEmpty()) {
                    for (Entity entity : targets) {
                        double distance = 1.0D - (entity.distanceTo(this) / range);
                        double scale = distance * 0.25D;
                        Vec3 vec3 = entity.position().subtract(this.position());
                        vec3 = vec3.normalize().scale(scale);
                        MobUtil.pull(entity, vec3.x, vec3.y, vec3.z, 0.5D);
                        if (entity.distanceTo(this) <= this.getBoundingBox().getSize()){
                            if (entity instanceof LivingEntity livingEntity) {
                                float damage = SpellConfig.RuptureDamage.get().floatValue() * WandUtil.damageMultiply();
                                if (this.getOwner() != null) {
                                    if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null) {
                                        damage = (float) mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F;
                                    }
                                }
                                damage += this.getExtraDamage();
                                livingEntity.hurt(this.damageSources().indirectMagic(this, this.getOwner()), damage);
                            }
                        }
                    }
                }
            } else {
                if (this.level instanceof ServerLevel serverWorld) {
                    double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    double d2 = this.getY() + 0.5F;
                    double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth();
                    serverWorld.sendParticles(ParticleTypes.PORTAL, d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
                }
                if (this.getOwner() != null && this.getOwner().isDeadOrDying()) {
                    this.discard();
                }
                --this.warmUp;
            }
            if (this.tickCount >= this.getDuration()) {
                if (!this.isClosing){
                    this.isClosing = true;
                    this.level.broadcastEntityEvent(this, (byte) 101);
                }
                if (this.tickCount >= this.getDuration() + 20) {
                    if (this.level instanceof ServerLevel serverLevel) {
                        ColorUtil colorUtil = new ColorUtil(0x7317d2);
                        float range = 8.0F * (this.getSize() + 1.0F);
                        serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red, colorUtil.green, colorUtil.blue, range, 0, true), this.getX(), this.getY() + 0.5D, this.getZ(), 0, 0, 0, 0, 0);
                        ServerParticleUtil.createParticleBall(ParticleTypes.DRAGON_BREATH, this.getX(), this.getY() + 0.5D, this.getZ(), serverLevel,  8 + (int) this.getSize());
                        this.playSound(SoundEvents.RESPAWN_ANCHOR_DEPLETE.get(), 5.0F, 0.5F);
                        this.playSound(SoundEvents.GENERIC_EXPLODE, 5.0F, 0.5F);
                        new SpellExplosion(this.level, this.getOwner() != null ? this.getOwner() : this, this.damageSources().indirectMagic(this, this.getOwner()), this.blockPosition(), range / 4, 0.0F) {
                            @Override
                            public void explodeHurt(Entity target, DamageSource damageSource, double x, double y, double z, double seen, float actualDamage) {
                                super.explodeHurt(target, damageSource, x, y, z, seen, actualDamage);
                                if (VoidRift.this.isStaff()) {
                                    if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target)) {
                                        if (target instanceof LivingEntity livingEntity) {
                                            livingEntity.addEffect(new MobEffectInstance(GoetyEffects.VOID_TOUCHED.get(), MathHelper.secondsToTicks(5), 2, false, true));
                                        }
                                    }
                                }
                            }
                        };
                    }
                    this.discard();
                }
            }
        }
    }

@Override
    public void aiStep() {
        super.aiStep();
        if (level.getDifficulty() == Difficulty.PEACEFUL && this.getTarget() instanceof Player) {
            this.setTarget(null);
        }
        if (this.getTarget() != null && (this.getTarget() instanceof Player && ((Player) this.getTarget()).isCreative() || this.getVictor() != null && this.isVictor(this.getTarget()))) {
            this.setTarget(null);
        }
        if (this.flock == null) {
            StymphalianBirdFlock otherFlock = StymphalianBirdFlock.getNearbyFlock(this);
            if (otherFlock == null) {
                this.flock = StymphalianBirdFlock.createFlock(this);
            } else {
                this.flock = otherFlock;
                this.flock.addToFlock(this);
            }
        } else {
            if (!this.flock.isLeader(this)) {
                double dist = this.distanceToSqr(this.flock.getLeader());
                if (dist > 360) {
                    this.setFlying(true);
                    this.navigation.stop();
                    this.airTarget = StymphalianBirdAIAirTarget.getNearbyAirTarget(this.flock.getLeader());
                    this.aiFlightLaunch = false;
                } else if (!this.flock.getLeader().isFlying()) {
                    this.setFlying(false);
                    this.airTarget = null;
                    this.aiFlightLaunch = false;
                }
                if (this.isOnGround() && dist < 40 && this.getAnimation() != ANIMATION_SHOOT_ARROWS) {
                    this.setFlying(false);
                }
            }
            this.flock.update();
        }
        if (!level.isClientSide && this.getTarget() != null && this.getTarget().isAlive()) {
            double dist = this.distanceToSqr(this.getTarget());
            if (this.getAnimation() == ANIMATION_PECK && this.getAnimationTick() == 7) {
                if (dist < 1.5F) {
                    this.getTarget().hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
                }
                if (onGround) {
                    this.setFlying(false);
                }
            }
            if (this.getAnimation() != ANIMATION_PECK && this.getAnimation() != ANIMATION_SHOOT_ARROWS && dist > 3 && dist < 225) {
                this.setAnimation(ANIMATION_SHOOT_ARROWS);
            }
            if (this.getAnimation() == ANIMATION_SHOOT_ARROWS) {
                LivingEntity target = this.getTarget();
                this.lookAt(target, 360, 360);
                if (this.isFlying()) {
                    setYRot(yBodyRot);
                    if ((this.getAnimationTick() == 7 || this.getAnimationTick() == 14) && isDirectPathBetweenPoints(this, this.position(), target.position())) {
                        this.playSound(IafSoundRegistry.STYMPHALIAN_BIRD_ATTACK, 1, 1);
                        for (int i = 0; i < 4; i++) {
                            float wingX = (float) (getX() + 1.8F * 0.5F * Mth.cos((float) ((getYRot() + 180 * (i % 2)) * Math.PI / 180)));
                            float wingZ = (float) (getZ() + 1.8F * 0.5F * Mth.sin((float) ((getYRot() + 180 * (i % 2)) * Math.PI / 180)));
                            float wingY = (float) (getY() + 1F);
                            double d0 = target.getX() - wingX;
                            double d1 = target.getBoundingBox().minY - wingY;
                            double d2 = target.getZ() - wingZ;
                            double d3 = Math.sqrt(d0 * d0 + d2 * d2);
                            EntityStymphalianFeather entityarrow = new EntityStymphalianFeather(
                                IafEntityRegistry.STYMPHALIAN_FEATHER.get(), level, this);
                            entityarrow.setPos(wingX, wingY, wingZ);
                            entityarrow.shoot(d0, d1 + d3 * 0.10000000298023224D, d2, 1.6F,
                                14 - this.level.getDifficulty().getId() * 4);
                            this.playSound(SoundEvents.SKELETON_SHOOT, 1.0F, 1.0F / (this.getRandom().nextFloat() * 0.4F + 0.8F));
                            this.level.addFreshEntity(entityarrow);
                        }
                    }
                } else {
                    this.setFlying(true);
                }
            }
        }
        boolean flying = this.isFlying() && !this.isOnGround() || airBorneCounter > 10 || this.getAnimation() == ANIMATION_SHOOT_ARROWS;
        if (flying && flyProgress < 20.0F) {
            flyProgress += 1F;
        } else if (!flying && flyProgress > 0.0F) {
            flyProgress -= 1F;
        }
        if (!this.isFlying() && this.airTarget != null && this.isOnGround() && !level.isClientSide) {
            this.airTarget = null;
        }
        if (this.isFlying() && getTarget() == null) {
            flyAround();
        } else if (getTarget() != null) {
            flyTowardsTarget();
        }
        if (!level.isClientSide && this.doesWantToLand() && !aiFlightLaunch && this.getAnimation() != ANIMATION_SHOOT_ARROWS) {
            this.setFlying(false);
            this.airTarget = null;
        }
        if (!level.isClientSide && this.isFree(0, 0, 0) && !this.isFlying()) {
            this.setFlying(true);
            this.launchTicks = 0;
            this.flyTicks = 0;
            this.aiFlightLaunch = true;
        }
        if (!level.isClientSide && this.isOnGround() && this.isFlying() && !aiFlightLaunch && this.getAnimation() != ANIMATION_SHOOT_ARROWS) {
            this.setFlying(false);
            this.airTarget = null;
        }
        if (!level.isClientSide && (this.flock == null || this.flock != null && this.flock.isLeader(this)) && this.getRandom().nextInt(FLIGHT_CHANCE_PER_TICK) == 0 && !this.isFlying() && this.getPassengers().isEmpty() && !this.isBaby() && this.onGround) {
            this.setFlying(true);
            this.launchTicks = 0;
            this.flyTicks = 0;
            this.aiFlightLaunch = true;
        }
        if (!level.isClientSide) {
            if (aiFlightLaunch && this.launchTicks < 40) {
                this.launchTicks++;
            } else {
                this.launchTicks = 0;
                aiFlightLaunch = false;
            }
            if (this.isFlying()) {
                this.flyTicks++;
            } else {
                this.flyTicks = 0;
            }
        }
        if (!this.onGround) {
            airBorneCounter++;
        } else {
            airBorneCounter = 0;
        }
        if (this.getAnimation() == ANIMATION_SHOOT_ARROWS && !this.isFlying() && !level.isClientSide) {
            this.setFlying(true);
            aiFlightLaunch = true;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public void onUpdate(){

		super.onUpdate();

		if(ticksExisted == 1 && world.isRemote){
			Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_FORCEFIELD_AMBIENT, WizardrySounds.SPELLS, 0.5f, 1, true);
		}

		// New forcefield repulsion system:
		// Searches for all entities near the forcefield and determines where they will be next tick.
		// If they will be inside the forcefield next tick, sets their position and velocity such that they appear to
		// bounce off the forcefield and creates impact particle effects and sounds where they hit it

		List<Entity> targets = EntityUtils.getEntitiesWithinRadius(radius + SEARCH_BORDER_SIZE, posX, posY, posZ, world, Entity.class);

		targets.remove(this);
		targets.removeIf(t -> t instanceof EntityXPOrb); // Gets annoying since they're attracted to the player

		// Ring of the defender allows players to shoot through their own forcefields
		if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
				WizardryItems.ring_defender)){
			targets.removeIf(t -> t instanceof EntityMagicArrow && !this.isValidTarget(((EntityMagicArrow)t).getCaster())
								|| t instanceof EntityThrowable && !this.isValidTarget(((EntityThrowable)t).getThrower())
								|| t instanceof EntityArrow && !this.isValidTarget(((EntityArrow)t).shootingEntity));
		}

		for(Entity target : targets){

			if(this.isValidTarget(target)){

				Vec3d currentPos = Arrays.stream(GeometryUtils.getVertices(target.getEntityBoundingBox()))
						.min(Comparator.comparingDouble(v -> v.distanceTo(this.getPositionVector())))
						.orElse(target.getPositionVector()); // This will never happen, it's just here to make the compiler happy

				double currentDistance = target.getDistance(this);

				// Estimate the target's position next tick
				// We have to assume the same vertex is closest or the velocity will be wrong
				Vec3d nextTickPos = currentPos.add(target.motionX, target.motionY, target.motionZ);
				double nextTickDistance = nextTickPos.distanceTo(this.getPositionVector());

				boolean flag;

				if(EntityUtils.isLiving(target)){
					// Non-allied living entities shouldn't be inside at all
					flag = nextTickDistance <= radius;
				}else{
					// Non-living entities will bounce off if they hit the forcefield within the next tick...
					flag = (currentDistance > radius && nextTickDistance <= radius) // ...from the outside...
							|| (currentDistance < radius && nextTickDistance >= radius); // ...or from the inside
				}

				if(flag){

					// Ring of interdiction
					if(getCaster() instanceof EntityPlayer && ItemArtefact.isArtefactActive((EntityPlayer)getCaster(),
							WizardryItems.ring_interdiction) && EntityUtils.isLiving(target)){
						target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
								MagicDamage.DamageType.MAGIC), 1);
					}

					Vec3d targetRelativePos = currentPos.subtract(this.getPositionVector());

					double nudgeVelocity = this.contains(target) ? -0.1 : 0.1;
					if(EntityUtils.isLiving(target)) nudgeVelocity = 0.25;
					Vec3d extraVelocity = targetRelativePos.normalize().scale(nudgeVelocity);

					//Moved up the check by "19" so that way allied players aren't being moved out of the forcefield because
					//allied players aren't synced to client like minions. Minions are only synced because it's saved to their
					//entity data which is synced in their serialize/deserialize methods
					if(!world.isRemote){
						// ...make it bounce off!

						target.motionX = target.motionX * -BOUNCINESS + extraVelocity.x;
						target.motionY = target.motionY * -BOUNCINESS + extraVelocity.y;
						target.motionZ = target.motionZ * -BOUNCINESS + extraVelocity.z;

						// Prevents the forcefield bouncing things into the floor
						if(target.onGround && target.motionY < 0) target.motionY = 0.1;

						// How far the target needs to move towards the centre (negative means away from the centre)
						double distanceTowardsCentre = -(targetRelativePos.length() - radius) - (radius - nextTickDistance);
						Vec3d targetNewPos = target.getPositionVector().add(targetRelativePos.normalize().scale(distanceTowardsCentre));
						target.setPosition(targetNewPos.x, targetNewPos.y, targetNewPos.z);

						world.playSound(target.posX, target.posY, target.posZ, WizardrySounds.ENTITY_FORCEFIELD_DEFLECT,
								WizardrySounds.SPELLS, 0.3f, 1.3f, false);


						// Player motion is handled on that player's client so needs packets
						if(target instanceof EntityPlayerMP){
							((EntityPlayerMP)target).connection.sendPacket(new SPacketEntityVelocity(target));
						}

						if (this.ticksExisted % 5 == 0) {
							this.lifetime = (int) (lifetime * 0.99);
						}

					}else{

						//This is a super lazy way to make sure the visual isn't playing for players and probably won't display the visual
						//for players if their velocity towards the forcefield is high. But it prevents the visual being spammed when ally player
						//is in forcefield so it's fine #19
						if(target instanceof EntityPlayer && target.getPositionVector().distanceTo(this.getPositionVector()) < this.getRadius()) return;

						Vec3d relativeImpactPos = targetRelativePos.normalize().scale(radius);

						float yaw = (float)Math.atan2(relativeImpactPos.x, -relativeImpactPos.z);
						float pitch = (float)Math.asin(relativeImpactPos.y/ radius);

						ParticleBuilder.create(Type.FLASH).pos(this.getPositionVector().add(relativeImpactPos))
						.time(6).face((float)(yaw * 180/Math.PI), (float)(pitch * 180/Math.PI))
						.clr(0.9f, 0.95f, 1).spawn(world);

						for(int i = 0; i < 12; i++){

							float yaw1 = yaw + 0.3f * (rand.nextFloat() - 0.5f) - (float)Math.PI/2;
							float pitch1 = pitch + 0.3f * (rand.nextFloat() - 0.5f);

							float brightness = rand.nextFloat();

							double r = radius + 0.05;
							double x = this.posX + r * MathHelper.cos(yaw1) * MathHelper.cos(pitch1);
							double y = this.posY + r * MathHelper.sin(pitch1);
							double z = this.posZ + r * MathHelper.sin(yaw1) * MathHelper.cos(pitch1);

							ParticleBuilder.create(Type.DUST).pos(x, y, z).time(6 + rand.nextInt(6))
							.face((float)(yaw1 * 180/Math.PI) + 90, (float)(pitch1 * 180/Math.PI)).scale(1.5f)
							.clr(0.7f + 0.3f * brightness, 0.85f + 0.15f * brightness, 1).spawn(world);
						}
					}
				}
			}
		}
	}

public void tick() {
        super.tick();
        prevFaceCameraProgress = faceCameraProgress;
        prevLaserLvl = this.getLaserAttackLvl();
        if (this.getAnimation() == ANIMATION_EMERGE) {
            this.setHasEmerged(true);
            faceCameraProgress = 1F;
        } else if (faceCameraProgress > 0.0F) {
            faceCameraProgress = Math.max(0, faceCameraProgress - 0.2F);
        }
        prevAngryProgress = angryProgress;
        for (int i = 0; i < HANDS; i++) {
            prevClaspProgress[i] = claspProgress[i];
            prevStrikeProgress[i] = strikeProgress[i];
        }
        if (this.posPointer < 0) {
            for (int i = 0; i < this.positions.length; ++i) {
                this.positions[i][0] = this.getX();
                this.positions[i][1] = this.getY();
                this.positions[i][2] = this.getZ();
                this.positions[i][3] = this.yBodyRot;
            }
        }
        if (++this.posPointer == this.positions.length) {
            this.posPointer = 0;
        }
        this.positions[this.posPointer][0] = this.getX();
        this.positions[this.posPointer][1] = this.getY();
        this.positions[this.posPointer][2] = this.getZ();
        this.positions[this.posPointer][3] = this.yBodyRot;
        if (this.isAngry() && angryProgress < 5F) {
            angryProgress++;
        }
        if (!this.isAngry() && angryProgress > 0F) {
            angryProgress--;
        }
        if (this.isAlive()) {
            if (random.nextInt(isAngry() ? 12 : 40) == 0 && claspingHand == -1) {
                int i = Mth.clamp(random.nextInt(HANDS), 0, 3);
                if (claspProgress[i] == 0) {
                    claspingHand = i;
                }
            }
            if (claspingHand >= 0) {
                if (claspProgress[claspingHand] < 5F) {
                    claspProgress[claspingHand]++;
                } else {
                    claspingHand = -1;
                }
            } else {
                for (int i = 0; i < HANDS; i++) {
                    if (claspProgress[i] > 0) {
                        claspProgress[i]--;
                    }
                }
            }
            if (!this.hasEmerged()) {
                this.setInvisible(true);
                if(this.level().hasNearbyAlivePlayer(this.getX(), this.getY(), this.getZ(), 9)){
                    this.setAnimation(ANIMATION_EMERGE);
                }
            }else{
                this.setInvisible(this.hasEffect(MobEffects.INVISIBILITY));
            }
            if (this.getAnimation() == ANIMATION_EMERGE) {
                if(this.level().isClientSide){
                    this.level().addParticle(AMParticleRegistry.STATIC_SPARK.get(), this.getRandomX(0.75F), this.getRandomY(), this.getRandomZ(0.75F), (this.getRandom().nextFloat() - 0.5F) * 0.2F, this.getRandom().nextFloat() * 0.2F, (this.getRandom().nextFloat() - 0.5F) * 0.2F);
                }
                if(this.getAnimationTick() == 1){
                    this.playSound(AMSoundRegistry.FARSEER_EMERGE.get(), this.getSoundVolume(), this.getVoicePitch());
                }
            }
            LivingEntity target = this.getTarget();
            if (target != null) {
                if (this.entityData.get(MELEEING)) {
                    if (meleeCooldown == 0) {
                        meleeCooldown = 5;
                        int i = random.nextInt(HANDS);
                        this.isStriking[i] = true;
                        this.level().broadcastEntityEvent(this, (byte) (40 + i));
                    }
                }
            }
            if (meleeCooldown > 0) {
                meleeCooldown--;
            }
            for (int i = 0; i < HANDS; i++) {
                if (!this.isStriking[i] || !this.entityData.get(MELEEING)) {
                    if (strikeProgress[i] > 0F) {
                        strikeProgress[i]--;
                    }
                } else if (this.isStriking[i]) {
                    if (strikeProgress[i] < 5F) {
                        strikeProgress[i]++;
                    }
                    if (strikeProgress[i] == 5F) {
                        isStriking[i] = false;
                        this.level().broadcastEntityEvent(this, (byte) (44 + i));
                        if (target != null && distanceTo(target) <= 4F) {
                            target.hurt(this.damageSources().mobAttack(this), 5 + random.nextInt(5));
                        }
                    }
                }
            }

            if (this.hasLaser()) {
                LivingEntity livingentity = this.getLaserTarget();
                if (livingentity != null) {
                    Vec3 hit = this.calculateLaserHit(livingentity.getEyePosition());
                    this.entityData.set(LASER_DISTANCE, (float) hit.distanceTo(this.getEyePosition()));
                    this.getLookControl().setLookAt(livingentity, 90.0F, 90.0F);
                    this.getLookControl().tick();
                    double d0 = hit.x - this.getX();
                    double d1 = hit.y - this.getEyeY();
                    double d2 = hit.z - this.getZ();
                    double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                    d0 = d0 / d3;
                    d1 = d1 / d3;
                    d2 = d2 / d3;
                    float progress = this.getLaserAttackLvl() / (float) LASER_ATTACK_DURATION;
                    double d4 = this.random.nextDouble();
                    while (d4 < d3 * progress) {
                        d4 += 0.5F + 2F * this.random.nextDouble();
                        double width = d4 / (d3 * progress);
                        double d5 = (random.nextDouble() - 0.5F) * width;
                        double d6 = (random.nextDouble() - 0.5F) * width;
                        this.level().addParticle(AMParticleRegistry.STATIC_SPARK.get(), this.getX() + d0 * d4 + d5, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4 + d6, (this.getRandom().nextFloat() - 0.5F) * 0.2F, this.getRandom().nextFloat() * 0.2F, (this.getRandom().nextFloat() - 0.5F) * 0.2F);
                    }
                }
            }
        }
        if (this.isAngry()) {
            angryShakeVec = new Vec3(random.nextFloat() - 0.5F, random.nextFloat() - 0.5F, random.nextFloat() - 0.5F);
        } else {
            angryShakeVec = Vec3.ZERO;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        if (localMimic != this.getPrevMimickedBlock()) {
            localMimic = this.getPrevMimickedBlock();
            colorShiftProgress = 0.0F;
        }
        if (localMimicState != this.getPrevMimicState()) {
            localMimicState = this.getPrevMimicState();
            transProgress = 0.0F;
        }

        if (this.isInWater()) {
            if (this.isLandNavigator)
                switchNavigator(false);
        } else {
            if (!this.isLandNavigator)
                switchNavigator(true);
        }

        BlockPos pos = AMBlockPos.fromCoords(this.getX(), this.getEyeY() - 1F, this.getZ());
        boolean ground = level().getBlockState(pos).isFaceSturdy(level(), pos, Direction.UP) && this.getMimicState() != MimicState.GUARDIAN || !this.isInWaterOrBubble() || this.isSitting();
        this.prevTransProgress = transProgress;
        this.prevColorShiftProgress = colorShiftProgress;
        this.prevGroundProgress = groundProgress;
        this.prevSitProgress = sitProgress;
        if (this.getPrevMimicState() != this.getMimicState() && transProgress < 5.0F) {
            transProgress += 0.25F;
        }
        if (this.getPrevMimicState() == this.getMimicState() && transProgress > 0F) {
            transProgress -= 0.25F;
        }
        if (getPrevMimickedBlock() != this.getMimickedBlock() && colorShiftProgress < 5.0F) {
            colorShiftProgress += 0.25F;
        }
        if (getPrevMimickedBlock() == this.getMimickedBlock() && colorShiftProgress > 0F) {
            colorShiftProgress -= 0.25F;
        }
        if (ground && groundProgress < 5F) {
            groundProgress += 0.5F;
        }
        if (!ground && groundProgress > 0F) {
            groundProgress -= 0.5F;
        }
        if (isSitting() && sitProgress < 5F) {
            sitProgress += 0.5F;
        }
        if (!isSitting() && sitProgress > 0F) {
            sitProgress -= 0.5F;
        }
        if (this.isInWaterOrBubble()) {
            float f2 = (float) -((float) this.getDeltaMovement().y * 3 * (double) Mth.RAD_TO_DEG);
            this.setXRot(f2);
        }
        if (camoCooldown > 0) {
            camoCooldown--;
        }
        if (mimicCooldown > 0) {
            mimicCooldown--;
        }
        if (stopMimicCooldown > 0) {
            stopMimicCooldown--;
        }
        if (this.isNoAi()) {
            this.setAirSupply(this.getMaxAirSupply());
        } else {
            if (this.isInWaterRainOrBubble() || this.getMainHandItem().getItem() == Items.WATER_BUCKET) {
                this.setMoistness(60000);
            } else {
                this.setMoistness(this.getMoistness() - 1);
                if (this.getMoistness() <= 0 && moistureAttackTime-- <= 0) {
                    this.setOrderedToSit(false);
                    this.hurt(damageSources().dryOut(), random.nextInt(2) == 0 ? 1.0F : 0F);
                    moistureAttackTime = 20;
                }
            }
        }
        if (camoCooldown <= 0 && random.nextInt(300) == 0) {
            mimicEnvironment();
            camoCooldown = this.getRandom().nextInt(2200) + 200;
        }
        if ((this.getMimicState() != MimicState.OVERLAY || this.getMimickedBlock() != null) && stopMimicCooldown == 0 && !this.isStopChange()) {
            this.setMimicState(MimicState.OVERLAY);
            this.setMimickedBlock(null);
            stopMimicCooldown = -1;
        }
        if (this.level().isClientSide && exclaimTime > 0) {
            exclaimTime--;
            if (exclaimTime == 0) {
                Entity e = level().getEntity(this.entityData.get(LAST_SCARED_MOB_ID));
                if (e != null && transProgress >= 5.0F) {
                    double d2 = this.random.nextGaussian() * 0.1D;
                    double d0 = this.random.nextGaussian() * 0.1D;
                    double d1 = this.random.nextGaussian() * 0.1D;
                    this.level().addParticle(AMParticleRegistry.SHOCKED.get(), e.getX(), e.getEyeY() + e.getBbHeight() * 0.15F + (double) (this.random.nextFloat() * e.getBbHeight() * 0.15F), e.getZ(), d0, d1, d2);
                }
            }
        }

        if (this.hasGuardianLaser()) {
            if (this.guardianLaserTime < 30) {
                ++this.guardianLaserTime;
            }
            LivingEntity livingentity = this.getGuardianLaser();
            if (livingentity != null && this.isInWaterOrBubble()) {
                this.getLookControl().setLookAt(livingentity, 90.0F, 90.0F);
                this.getLookControl().tick();
                double d5 = this.getLaserAttackAnimationScale(0.0F);
                double d0 = livingentity.getX() - this.getX();
                double d1 = livingentity.getY(0.5D) - this.getEyeY();
                double d2 = livingentity.getZ() - this.getZ();
                double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                d0 = d0 / d3;
                d1 = d1 / d3;
                d2 = d2 / d3;
                double d4 = this.random.nextDouble();
                while (d4 < d3) {
                    d4 += 1.8D - d5 + this.random.nextDouble() * (1.7D - d5);
                    this.level().addParticle(ParticleTypes.BUBBLE, this.getX() + d0 * d4, this.getEyeY() + d1 * d4, this.getZ() + d2 * d4, 0.0D, 0.0D, 0.0D);
                }
                if (guardianLaserTime == 30) {
                    livingentity.hurt(this.damageSources().mobAttack(this), 5);
                    guardianLaserTime = 0;
                    this.entityData.set(UPGRADED_LASER_ENTITY_ID, -1);
                }
            }
        }
        if (!this.level().isClientSide && tickCount % 40 == 0) {
            this.heal(2);
        }
    /*if(!world.isRemote){
            if(ticksExisted % 80 == 0){
                mimicEnvironment();
            }else if(ticksExisted % 40 == 0){
                this.setMimicState(MimicState.OVERLAY);
                this.setMimickedBlock(null);
            }
        }*/
    }

public void tick() {
        super.tick();
        if(this.tickCount % 100 == 0){
            this.heal(2);
        }
        float f = Mth.wrapDegrees(180 + this.getYRot());
        this.yBodyRot = rotlerp(this.yBodyRot, f, 180);
        prevSquidPitch = getSquidPitch();
        prevDepressurization = getDepressurization();
        prevDryProgress = dryProgress;
        prevGrabProgress = grabProgress;
        prevCapturedProgress = capturedProgress;
        if (!this.isInWater() && dryProgress < 5F) {
            dryProgress++;
        }
        if (this.isInWater() && dryProgress > 0F) {
            dryProgress--;
        }

        if (this.isGrabbing()) {
            if (grabProgress < 5F)
                grabProgress += 0.25F;
        } else {
            if (grabProgress > 0F)
                grabProgress -= 0.25F;
        }

        if (this.isCaptured()) {
            if (capturedProgress < 5F)
                capturedProgress += 0.5F;
        } else {
            if (capturedProgress > 0F)
                capturedProgress -= 0.5F;
        }

        if (this.isGrabbing()) {
            Entity target = getGrabbedEntity();
            if(!this.level().isClientSide && target != null){
                this.entityData.set(GRAB_ENTITY, target.getId());
                if (holdTime % 20 == 0 && holdTime > 30) {
                    target.hurt(this.damageSources().mobAttack(this), 3 + random.nextInt(5));
                }
            }
            if (target != null && target.isAlive()) {
                this.setXRot(0);
                float invert = 1F - grabProgress * 0.2F;
                Vec3 extraVec = new Vec3(0, 0, 2F + invert * 7F).xRot(-this.getXRot() * Mth.DEG_TO_RAD).yRot(-this.yBodyRot * Mth.DEG_TO_RAD);
                Vec3 minus = new Vec3(this.getX() + extraVec.x - target.getX(), this.getY() + extraVec.y - target.getY(), this.getZ() + extraVec.z - target.getZ());
                target.setDeltaMovement(minus);
            }
            holdTime++;
            if (holdTime > 1000) {
                holdTime = 0;
                this.setGrabbing(false);
            }
        } else {
            holdTime = 0;
        }
        if (!this.isNoAi()) {
            Vec3[] avector3d = new Vec3[this.allParts.length];
            for (int j = 0; j < this.allParts.length; ++j) {
                this.allParts[j].collideWithNearbyEntities();
                avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
            }
            final float pitch = this.getXRot() * Mth.DEG_TO_RAD * 0.8F;
            this.mantleCollisionPart.setPos(this.getX(), this.getY() - ((this.mantleCollisionPart.getBbHeight() - this.getEyeHeight()) * 0.5F) * (1F - dryProgress * 0.2F), this.getZ());
            this.setPartPositionFromBuffer(this.mantlePart1, pitch, 0.9F, 0);
            this.setPartPositionFromBuffer(this.mantlePart2, pitch, 1.6F, 0);
            this.setPartPositionFromBuffer(this.mantlePart3, pitch, 2.45F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart1, pitch, -0.8F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart2, pitch, -1.5F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart3, pitch, -2.3F, 5);
            this.setPartPositionFromBuffer(this.tentaclesPart4, pitch, -3.4F, 10);
            this.setPartPositionFromBuffer(this.tentaclesPart5, pitch, -5.4F, 15);
            this.setPartPositionFromBuffer(this.tentaclesPart6, pitch, -7.4F, 20);
            if (this.isInWaterOrBubble()) {
                if (this.mantleCollisionPart.scale != 1F) {
                    this.mantleCollisionPart.scale = 1F;
                    this.mantleCollisionPart.refreshDimensions();
                }
            } else {
                if (this.mantleCollisionPart.scale != 0.25F) {
                    this.mantleCollisionPart.scale = 0.25F;
                    this.mantleCollisionPart.refreshDimensions();
                }
            }
            for (int l = 0; l < this.allParts.length; ++l) {
                this.allParts[l].xo = avector3d[l].x;
                this.allParts[l].yo = avector3d[l].y;
                this.allParts[l].zo = avector3d[l].z;
                this.allParts[l].xOld = avector3d[l].x;
                this.allParts[l].yOld = avector3d[l].y;
                this.allParts[l].zOld = avector3d[l].z;
            }
            this.setNoGravity(this.isInWater());
        }
        if (!this.level().isClientSide) {
            if (this.getSquidPitch() > 0F) {
                float decrease = Math.min(2F, this.getSquidPitch());
                this.decrementSquidPitch(decrease);
            }
            if (this.getSquidPitch() < 0F) {
                float decrease = Math.min(2F, -this.getSquidPitch());
                this.incrementSquidPitch(decrease);
            }
            if (this.isInWaterOrBubble()) {
                float dist = (float) this.getDeltaMovement().y() * 45;
                if (entityData.get(OVERRIDE_BODYROT)) {
                    this.decrementSquidPitch(dist);
                } else {
                    this.incrementSquidPitch(dist);
                }
            }
            if (!this.onGround() && this.getFluidHeight(FluidTags.WATER) < this.getBbHeight()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.1F, 0));
            }
            float pressure = getDepressureLevel();
            if (this.getDepressurization() < pressure) {
                this.setDepressurization(this.getDepressurization() + 0.1F);
            }
            if (this.getDepressurization() > pressure) {
                this.setDepressurization(this.getDepressurization() - 0.1F);
            }
        }
        if (this.isHumming()) {
            if (humTick % 20 == 0) {
                this.playSound(AMSoundRegistry.GIANT_SQUID_GAMES.get(), this.getSoundVolume(), 1);
                humTick = 0;
            }
            humTick++;
        }
        if(!this.level().isClientSide){
            if(resetCapturedStateIn > 0){
                resetCapturedStateIn--;
            }else{
                this.setCaptured(false);
            }
        }
    }

default void travelFlying(PathfinderMob entity, Vec3 travelVector) {
        if (entity.isControlledByLocalInstance()) {
            Level level = entity.level();
            double gravity = entity.getGravity();
            boolean isDescending = entity.getDeltaMovement().y <= 0;

            if (isDescending && entity.hasEffect(MobEffects.SLOW_FALLING))
                gravity = Math.min(gravity, 0.01f);

            FluidState fluidState = level.getFluidState(entity.blockPosition());

            if ((entity.isInWater() || (entity.isInFluidType(fluidState) && fluidState.getFluidType() != NeoForgeMod.LAVA_TYPE.value())) && entity.isAffectedByFluids() && !entity.canStandOnFluid(fluidState)) {
                if (entity.isInWater() || (entity.isInFluidType(fluidState) && !entity.moveInFluid(fluidState, travelVector, gravity))) {
                    double prevY = entity.getY();
                    float drag = entity.isSprinting() ? 0.9F : entity.getWaterSlowDown();
                    float impulse = 0.02F;
                    float waterMovementEfficiency = (float)entity.getAttributeValue(Attributes.WATER_MOVEMENT_EFFICIENCY);

                    if (!entity.onGround())
                        waterMovementEfficiency *= 0.5f;

                    if (waterMovementEfficiency > 0) {
                        drag += (0.54600006f - drag) * waterMovementEfficiency;
                        impulse += (entity.getSpeed() - impulse) * waterMovementEfficiency;
                    }

                    if (entity.hasEffect(MobEffects.DOLPHINS_GRACE))
                        drag = 0.96F;

                    impulse *= (float)entity.getAttributeValue(NeoForgeMod.SWIM_SPEED);

                    entity.moveRelative(impulse, travelVector);
                    entity.move(MoverType.SELF, entity.getDeltaMovement());
                    Vec3 velocity = entity.getDeltaMovement();

                    if (entity.horizontalCollision && entity.onClimbable())
                        velocity = new Vec3(velocity.x, 0.2f, velocity.z);

                    entity.setDeltaMovement(velocity.multiply(drag, 0.8f, drag));

                    velocity = entity.getFluidFallingAdjustedMovement(gravity, isDescending, entity.getDeltaMovement());

                    entity.setDeltaMovement(velocity);

                    if (entity.horizontalCollision && entity.isFree(velocity.x, velocity.y + 0.6F - entity.getY() + prevY, velocity.z))
                        entity.setDeltaMovement(velocity.x, 0.3F, velocity.z);
                }
            }
            else if (entity.isInLava() && entity.isAffectedByFluids() && !entity.canStandOnFluid(fluidState)) {
                double prevY = entity.getY();

                entity.moveRelative(0.02f, travelVector);
                entity.move(MoverType.SELF, entity.getDeltaMovement());

                if (entity.getFluidHeight(FluidTags.LAVA) <= entity.getFluidJumpThreshold()) {
                    entity.setDeltaMovement(entity.getDeltaMovement().multiply(0.5f, 0.8f, 0.5f));
                    entity.setDeltaMovement(entity.getFluidFallingAdjustedMovement(gravity, isDescending, entity.getDeltaMovement()));
                }
                else {
                    entity.setDeltaMovement(entity.getDeltaMovement().scale(0.5f));
                }

                if (gravity != 0)
                    entity.setDeltaMovement(entity.getDeltaMovement().add(0, -gravity / 4d, 0));

                Vec3 velocity = entity.getDeltaMovement();

                if (entity.horizontalCollision && entity.isFree(velocity.x, velocity.y + 0.6f - entity.getY() + prevY, velocity.z))
                    entity.setDeltaMovement(velocity.x, 0.3f, velocity.z);
            }
            else if (entity.isFallFlying()) {
                entity.checkSlowFallDistance();

                Vec3 velocity = entity.getDeltaMovement();
                Vec3 lookAngle = entity.getLookAngle();
                float xRot = entity.getXRot() * Mth.DEG_TO_RAD;
                double lookLateralLength = Math.sqrt(lookAngle.x * lookAngle.x + lookAngle.z * lookAngle.z);
                double velocityLateralLength = velocity.horizontalDistance();
                double lookLength = lookAngle.length();
                double dive = Math.cos(xRot);
                dive = dive * dive * Math.min(1, lookLength / 0.4d);
                velocity = entity.getDeltaMovement().add(0, gravity * (-1d + dive * 0.75d), 0);

                if (velocity.y < 0 && lookLateralLength > 0) {
                    double diveVelocity = velocity.y * -0.1 * dive;
                    velocity = velocity.add(lookAngle.x * diveVelocity / lookLateralLength, diveVelocity, lookAngle.z * diveVelocity / lookLateralLength);
                }

                if (xRot < 0 && lookLateralLength > 0) {
                    double fallVelocity = velocityLateralLength * -Mth.sin(xRot) * 0.04f;
                    velocity = velocity.add(-lookAngle.x * fallVelocity / lookLateralLength, fallVelocity * 3.2f, -lookAngle.z * fallVelocity / lookLateralLength);
                }

                if (lookLateralLength > 0)
                    velocity = velocity.add((lookAngle.x / lookLateralLength * velocityLateralLength - velocity.x) * 0.1f, 0, (lookAngle.z / lookLateralLength * velocityLateralLength - velocity.z) * 0.1f);

                entity.setDeltaMovement(velocity.multiply(0.99f, 0.98f, 0.99f));
                entity.move(MoverType.SELF, entity.getDeltaMovement());

                if (entity.horizontalCollision && !level.isClientSide) {
                    double velocityLateralDelta = velocityLateralLength - entity.getDeltaMovement().horizontalDistance();
                    float collisionVelocity = (float)(velocityLateralDelta * 10f - 3f);

                    if (collisionVelocity > 0) {
                        entity.playSound(entity.getFallDamageSound((int)collisionVelocity), 1f, 1f);
                        entity.hurt(entity.damageSources().flyIntoWall(), collisionVelocity);
                    }
                }

                if (entity.onGround() && !level.isClientSide)
                    entity.setSharedFlag(Entity.FLAG_FALL_FLYING, false);
            }
            else {
                BlockPos groundPos = entity.getBlockPosBelowThatAffectsMyMovement();
                float groundFriction = level.getBlockState(groundPos).getFriction(level, groundPos, entity);
                float friction = entity.onGround() ? groundFriction * 0.91f : 0.6f * 0.91f;
                Vec3 newVelocity = entity.handleRelativeFrictionAndCalculateMovement(travelVector, groundFriction);
                double newVelocityY = newVelocity.y;

                if (entity.hasEffect(MobEffects.LEVITATION)) {
                    newVelocityY += (0.05f * (double)(entity.getEffect(MobEffects.LEVITATION).getAmplifier() + 1) - newVelocity.y) * 0.2f;
                }
                else if (!level.isClientSide || level.hasChunkAt(groundPos)) {
                    newVelocityY -= gravity;
                }
                else if (entity.getY() > (double)level.getMinBuildHeight()) {
                    newVelocityY = -0.1f;
                }
                else {
                    newVelocityY = 0;
                }

                if (entity.shouldDiscardFriction()) {
                    entity.setDeltaMovement(newVelocity.x, newVelocityY, newVelocity.z);
                }
                else {
                    entity.setDeltaMovement(newVelocity.x * (double)friction, newVelocityY * (double)friction, newVelocity.z * (double)friction);
                }
            }
        }

        entity.calculateEntityAnimation(true);
    }

@Override
    public void tick() {
        super.tick();
        prevFlyProgress = flyProgress;
        prevHoverProgress = hoverProgress;
        prevAttackProgress = attackProgress;
        prevFlapAmount = flapAmount;
        prevFlightPitch = flightPitch;
        prevFlightRoll = flightRoll;
        prevTailYaw = tailYaw;
        if (isFlying() && flyProgress < 5F) {
            flyProgress++;
        }
        if (!isFlying() && flyProgress > 0F) {
            flyProgress--;
        }
        if (isHovering() && hoverProgress < 5F) {
            hoverProgress++;
        }
        if (!isHovering() && hoverProgress > 0F) {
            hoverProgress--;
        }
        if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        float yMov = (float) this.getDeltaMovement().y;
        if (yMov > 0 || this.isHovering()) {
            if (flapAmount < 5F) {
                flapAmount += 1F;
            }
        } else if (yMov <= 0.05F) {
            if (flapAmount > 0) {
                flapAmount -= 0.5F;
            }
        }
        if (isFlying()) {
            if(timeFlying % 10 == 0 && (flapAmount > 0 || controlUpTicks > 0)){
                this.playSound(ACSoundRegistry.SUBTERRANODON_FLAP.get());
            }
            timeFlying++;
            if (this.isLandNavigator) {
                switchNavigator(false);
            }
            if (this.getDeltaMovement().y < 0 && this.isAlive()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(1, 0.6D, 1));
            }
            if (this.isDancing() || this.isPassenger()) {
                this.setHovering(false);
                this.setFlying(false);
            }
            if (!level().isClientSide && this.onGround()) {
                LivingEntity target = this.getTarget();
                if (target != null && target.isAlive()) {
                    this.setHovering(false);
                    this.setFlying(false);
                }
            }
        } else {
            timeFlying = 0;
            if (!this.isLandNavigator) {
                switchNavigator(true);
            }
        }
        if (this.isVehicle() && !this.isBaby()) {
            this.setFlying(true);
            Entity rider = getControllingPassenger();
            if (rider != null) {
                this.flightCollisionBox = this.getBoundingBox().expandTowards(0, -0.5F - rider.getBbHeight(), 0);
                if (isRiderInWall()) {
                    this.setDeltaMovement(this.getDeltaMovement().add(0, 0.2, 0));
                }
            }
        }
        if (!level().isClientSide) {
            this.setHovering(isHoveringFromServer() && isFlying());
            if (this.isHovering() && isFlying() && this.isAlive() && !this.isVehicle()) {
                if (timeFlying < 30) {
                    this.setDeltaMovement(this.getDeltaMovement().add(0, 0.075D, 0));
                }
                if (landingFlag) {
                    this.setDeltaMovement(this.getDeltaMovement().add(0, -0.3D, 0));
                }
            }
            if (!this.isHovering() && this.isFlying() && timeFlying > 40 && this.onGround()) {
                this.setFlying(false);
            }
        } else {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
            Player player = AlexsCaves.PROXY.getClientSidePlayer();
            if (player != null && player.isPassengerOfSameVehicle(this)) {
                if (AlexsCaves.PROXY.isKeyDown(0) && !AlexsCaves.PROXY.isKeyDown(1) && controlUpTicks < 2 && getMeterAmount() > 0.1F) {
                    if (getMeterAmount() > 0.1F) {
                        AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 0));
                        controlUpTicks = 5;
                    }
                }
                if (AlexsCaves.PROXY.isKeyDown(1) && !AlexsCaves.PROXY.isKeyDown(0) && controlDownTicks < 2) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 1));
                    controlDownTicks = 5;
                }
            }
        }
        if (controlDownTicks > 0) {
            controlDownTicks--;
        } else if (controlUpTicks > 0) {
            controlUpTicks--;
        }
        if (isVehicle()) {
            timeVehicle++;
        } else {
            timeVehicle = 0;
        }
        if (this.getMeterAmount() < 1.0F && controlUpTicks == 0) {
            this.setMeterAmount(this.getMeterAmount() + (slowRidden ? 0.002F : 0.001F));
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            LivingEntity target = this.getTarget();
            if (attackProgress == 5F && target != null && this.distanceTo(target) < 3D + target.getBbWidth() && this.hasLineOfSight(target)) {
                target.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue());
                this.playSound(ACSoundRegistry.SUBTERRANODON_ATTACK.get());
            }
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        tickRotation(Mth.clamp(yMov, -1.0F, 1.0F) * -(float) (180F / (float) Math.PI));
        lastStepX = this.xo;
        lastStepZ = this.zo;
    }

public void tick() {
        super.tick();
        prevJumpProgress = jumpProgress;
        prevReboundProgress = reboundProgress;
        prevSleepProgress = sleepProgress;
        prevInterestedProgress = interestedProgress;
        prevTransformTime = this.transformsIn();

        if (!this.level().isClientSide) {
            this.entityData.set(JUMP_ACTIVE, !this.onGround());
        }

        if (this.entityData.get(JUMP_ACTIVE) && !isInWaterOrBubble()) {
            if (jumpProgress < 5F) {
                jumpProgress += 0.5F;
                if (reboundProgress > 0) {
                    reboundProgress--;
                }
            }
            if (jumpProgress >= 5F) {
                if (reboundProgress < 5F) {
                    reboundProgress += 0.5F;
                }
            }
        } else {
            if (reboundProgress > 0) {
                reboundProgress = Math.max(reboundProgress - 1F, 0);
            }
            if (jumpProgress > 0) {
                jumpProgress = Math.max(jumpProgress - 1F, 0);
            }
        }

        if (this.isSleepingPose()) {
            if (sleepProgress < 5F)
                sleepProgress++;
        } else {
            if (sleepProgress > 0F)
                sleepProgress--;
        }

        if (this.isBegging()) {
            if (interestedProgress < 5F)
                interestedProgress++;
        } else {
            if (interestedProgress > 0F)
                interestedProgress--;
        }

        if (!this.level().isClientSide) {
            final LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                if (this.isSleeping()) {
                    this.setSleeping(false);
                }
                final double dist = this.distanceTo(target);
                boolean flag = false;
                if (this.getAnimationTick() == 5) {
                    if (dist < 3.5D && this.getAnimation() == ANIMATION_BELLY) {
                        for (final LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(2.0D))) {
                            if ((entity == target || entity instanceof Monster) && !entity.getType().is(AMTagRegistry.BUNFUNGUS_IGNORE_AOE_ATTACKS)) {
                                flag = true;
                                launch(entity);
                                entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                            }
                        }
                    } else if (dist < 2.5D && this.getAnimation() == ANIMATION_SLAM) {
                        for (final LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(2.0D))) {
                            if ((entity == target || entity instanceof Monster) && !entity.getType().is(AMTagRegistry.BUNFUNGUS_IGNORE_AOE_ATTACKS)) {
                                flag = true;
                                entity.knockback(0.2F, entity.getX() - this.getX(), entity.getZ() - this.getZ());
                                entity.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                            }
                        }
                    }
                }
                if (flag) {
                    this.playSound(AMSoundRegistry.BUNFUNGUS_ATTACK.get(), this.getSoundVolume(), this.getVoicePitch());
                }
            }
            if (this.tickCount % 40 == 0) {
                this.heal(1);
            }
        }
        if (this.getAnimation() == NO_ANIMATION && this.isCarrot(this.getItemInHand(InteractionHand.MAIN_HAND))) {
            this.setAnimation(ANIMATION_EAT);
        }
        if (this.getAnimation() == ANIMATION_EAT) {
            if (this.getAnimationTick() % 4 == 0) {
                this.gameEvent(GameEvent.EAT);
                this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.getAnimationTick() >= 18) {
                ItemStack stack = this.getItemInHand(InteractionHand.MAIN_HAND);
                if (!stack.isEmpty()) {
                    stack.shrink(1);
                    this.setCarroted(true);
                    this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1000));
                    this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 1000, 1));
                    this.heal(8);
                }
            } else {
                for (int i = 0; i < 3; i++) {
                    final double d2 = this.random.nextGaussian() * 0.02D;
                    final double d0 = this.random.nextGaussian() * 0.02D;
                    final double d1 = this.random.nextGaussian() * 0.02D;
                    this.level().addParticle(new ItemParticleOption(ParticleTypes.ITEM, this.getItemInHand(InteractionHand.MAIN_HAND)), this.getX() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, this.getY() + this.getBbHeight() * 0.5F + (double) (this.random.nextFloat() * this.getBbHeight() * 0.5F), this.getZ() + (double) (this.random.nextFloat() * this.getBbWidth()) - (double) this.getBbWidth() * 0.5F, d0, d1, d2);
                }
            }
        }
        if (!this.level().isClientSide) {
            if (this.transformsIn() > 0) {
                this.setTransformsIn(this.transformsIn() - 1);
            }
        }

        if (this.level().isClientSide) {
            if (isRabbitForm()){
                for (int i = 0; i < 3; i++) {
                    final double d2 = this.random.nextGaussian() * 0.02D;
                    final double d0 = this.random.nextGaussian() * 0.02D;
                    final double d1 = this.random.nextGaussian() * 0.02D;
                    final float f1 = (EntityBunfungus.MAX_TRANSFORM_TIME - this.transformsIn()) / (float)EntityBunfungus.MAX_TRANSFORM_TIME;
                    final float scale = f1 * 0.5F + 0.15F;
                    this.level().addParticle(AMParticleRegistry.BUNFUNGUS_TRANSFORMATION.get(), this.getRandomX(scale), this.getY(this.random.nextDouble() * scale), this.getRandomZ(scale), d0, d1, d2);
                }
            }

            if (isSleeping() && random.nextFloat() < 0.3F) {
                final double d0 = this.random.nextGaussian() * 0.02D;
                final float radius = this.getBbWidth() * (0.7F + random.nextFloat() * 0.1F);
                final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                final double extraX = radius * Mth.sin(Mth.PI + angle) + random.nextFloat() * 0.5F - 0.25F;
                final double extraZ = radius * Mth.cos(angle) + random.nextFloat() * 0.5F - 0.25F;
                ParticleOptions data = random.nextFloat() < 0.3F ? AMParticleRegistry.BUNFUNGUS_TRANSFORMATION.get() : AMParticleRegistry.FUNGUS_BUBBLE.get();
                this.level().addParticle(data, this.getX() + extraX, this.getY() + random.nextFloat() * 0.1F, this.getZ() + extraZ, 0, d0, 0);
            }
        } else {
            if (this.level().isDay() && this.getTarget() == null && !this.isBegging() && !this.isInWaterOrBubble()) {
                if (tickCount % 10 == 0 && this.getRandom().nextInt(300) == 0) {
                    this.setSleeping(true);
                }
            } else if (this.isSleeping()) {
                this.setSleeping(false);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void tick() {
        LivingEntity target = entity.getTarget();
        if (target != null && target.isAlive()) {
            double distance = entity.distanceTo(target);
            double attackDistance = entity.getBbWidth() + target.getBbWidth();
            boolean inPursuit = !this.isMovementFrozen();
            if (attemptSonicDamageIn > 0) {
                attemptSonicDamageIn--;
                if (attemptSonicDamageIn == 0 && this.entity.hasLineOfSight(target)) {
                    target.hurt(ACDamageTypes.causeForsakenSonicBoomDamage(entity.level().registryAccess(), entity), entity.getSonicDamageAgainst(target));
                    knockBackAngle(target, 1.0F, 0F);
                }
            }
            if (sonicEnqueued && this.entity.hasLineOfSight(target) && distance < 200F) {
                this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                entity.setSonarId(target.getId());
                this.entity.getNavigation().stop();
                if(distance > 10 || entity.getRandom().nextFloat() < 0.4){
                    tryAnimation(ForsakenEntity.ANIMATION_SONIC_ATTACK);
                    this.entity.playSound(ACSoundRegistry.FORSAKEN_SCREECH.get(), this.entity.getSoundVolume(), this.entity.getVoicePitch());
                }else{
                    tryAnimation(ForsakenEntity.ANIMATION_SONIC_BLAST);
                    this.entity.playSound(ACSoundRegistry.FORSAKEN_AOE.get(), this.entity.getSoundVolume(), this.entity.getVoicePitch());
                }
                if (this.entity.getAnimation() == ForsakenEntity.ANIMATION_SONIC_ATTACK) {
                    inPursuit = false;
                    if (this.entity.getAnimationTick() >= 10 && this.entity.getAnimationTick() <= 30 && attemptSonicDamageIn <= 0) {
                        attemptSonicDamageIn = (int) Math.ceil(distance * 0.2F);
                    }
                    if (this.entity.getAnimationTick() > 30) {
                        sonicEnqueued = false;
                    }
                }
                if (this.entity.getAnimation() == ForsakenEntity.ANIMATION_SONIC_BLAST) {
                    inPursuit = false;
                    if (this.entity.getAnimationTick() >= 10 && this.entity.getAnimationTick() <= 30) {
                        if (this.entity.getAnimationTick() % 5 == 0) {
                            List<LivingEntity> list = this.entity.level().getEntitiesOfClass(LivingEntity.class, this.entity.getBoundingBox().inflate(16, 8, 16));
                            for (LivingEntity living : list) {
                                if (living != this.entity && !this.entity.isAlliedTo(living) && !living.isAlliedTo(entity) && living.distanceTo(entity) <= 14F && !living.getType().is(ACTagRegistry.FORSAKEN_IGNORES)) {
                                    living.hurt(ACDamageTypes.causeForsakenSonicBoomDamage(entity.level().registryAccess(), entity), (float) Math.ceil(entity.getSonicDamageAgainst(target) * 0.65F));
                                }
                            }
                        }
                    }
                    if (this.entity.getAnimationTick() > 40) {
                        sonicEnqueued = false;
                    }
                }
            } else if (jumpEnqueued) {
                if (jumpTarget == null) {
                    jumpTarget = findJumpTarget(target, distance > 20.0F);
                } else {
                    inPursuit = false;
                    if (entity.isLeaping()) {
                        Vec3 vec3 = this.entity.getDeltaMovement();
                        Vec3 vec31 = new Vec3(this.jumpTarget.getX() + 0.5F - this.entity.getX(), 0.0D, this.jumpTarget.getZ() + 0.5F - this.entity.getZ());
                        if (vec31.lengthSqr() > 1.0E-7D) {
                            vec31 = vec31.scale(0.155F).add(vec3.scale(0.2D));
                        }
                        this.entity.setDeltaMovement(vec31.x, 0.2F + (double) vec31.length() * 0.3F, vec31.z);
                        jumpEnqueued = false;
                        jumpTarget = null;
                    } else if (entity.onGround()) {
                        entity.lookAt(EntityAnchorArgument.Anchor.EYES, Vec3.atCenterOf(jumpTarget));
                        tryAnimation(ForsakenEntity.ANIMATION_PREPARE_JUMP);
                    }
                }
            }
            if (inPursuit) {
                this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
                this.entity.getNavigation().moveTo(target, 1.0D);
                if (distance < attackDistance + 1.0F && this.entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    float attackType = entity.getRandom().nextFloat();
                    if (attackType < 0.25F && target.getBbWidth() < 2.0F) {
                        tryAnimation(this.entity.getRandom().nextBoolean() ? ForsakenEntity.ANIMATION_LEFT_PICKUP : ForsakenEntity.ANIMATION_RIGHT_PICKUP);
                    } else if (attackType < 0.5F) {
                        tryAnimation(this.entity.getRandom().nextBoolean() ? ForsakenEntity.ANIMATION_LEFT_SLASH : ForsakenEntity.ANIMATION_RIGHT_SLASH);
                    } else if (attackType < 0.75F) {
                        tryAnimation(ForsakenEntity.ANIMATION_GROUND_SMASH);
                    } else {
                        tryAnimation(ForsakenEntity.ANIMATION_BITE);
                        this.entity.playSound(ACSoundRegistry.FORSAKEN_BITE.get());
                    }
                }
            } else {
                entity.getNavigation().stop();
            }
            if ((distance > 20.0F && this.entity.getRandom().nextFloat() < 0.01 || entity.hasSonicCharge()) && !this.sonicEnqueued) {
                this.sonicEnqueued = true;
                this.entity.setSonicCharge(false);
            }
            if (distance > 30.0F && this.entity.getRandom().nextFloat() < 0.05 && !this.jumpEnqueued) {
                this.startCleanJump();
            }
            if (distance < 64.0F && distance > attackDistance && inPursuit) {
                this.entity.setRunning(true);
            } else {
                this.entity.setRunning(false);
            }
            if ((entity.getAnimation() == ForsakenEntity.ANIMATION_RIGHT_PICKUP || entity.getAnimation() == ForsakenEntity.ANIMATION_LEFT_PICKUP) && entity.getHeldMobId() == target.getId() && entity.getAnimationTick() >= 30) {
                checkAndDealDamage(target, 1.2F, 5);
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_RIGHT_SLASH && entity.getAnimationTick() >= 15 && entity.getAnimationTick() <= 18) {
                float knockbackStrength = 0.5F;
                if (checkAndDealDamage(target, 0.8F, 2)) {
                    knockbackStrength = 3F;
                    entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
                }
                knockBackAngle(target, knockbackStrength, -90F);
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_LEFT_SLASH && entity.getAnimationTick() >= 15 && entity.getAnimationTick() <= 18) {
                float knockbackStrength = 0.5F;
                if (checkAndDealDamage(target, 0.8F, 2)) {
                    knockbackStrength = 3F;
                    entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
                }
                knockBackAngle(target, knockbackStrength, 90F);
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_GROUND_SMASH && entity.getAnimationTick() >= 10 && entity.getAnimationTick() <= 15) {
                Vec3 smashPos = entity.position().add(new Vec3(0, 0, 3.5F).yRot((float) -Math.toRadians(entity.yBodyRot)));
                List<LivingEntity> list = this.entity.level().getEntitiesOfClass(LivingEntity.class, new AABB(smashPos.x - 4, smashPos.y - 2, smashPos.z - 4, smashPos.x + 4, smashPos.y + 3, smashPos.z + 4));
                boolean flag = false;
                for (LivingEntity living : list) {
                    if (living != this.entity && !this.entity.isAlliedTo(living) && !living.isAlliedTo(entity) && living.distanceToSqr(smashPos) <= 16F && !living.getType().is(ACTagRegistry.FORSAKEN_IGNORES)) {
                        if (checkAndDealDamage(living, 0.8F, 3) && living.onGround()) {
                            living.setDeltaMovement(living.getDeltaMovement().add(0, 0.5, 0));
                            flag = true;
                        }
                    }
                }
                if(flag){
                    entity.playSound(ACSoundRegistry.FORSAKEN_GRAB.get());
                }
            }
            if (entity.getAnimation() == ForsakenEntity.ANIMATION_BITE && entity.getAnimationTick() >= 5 && entity.getAnimationTick() <= 8) {
                float knockbackStrength = 0.0F;
                if (checkAndDealDamage(target, 1F, 1)) {
                    knockbackStrength = 0.5F;
                }
                knockBackAngle(target, knockbackStrength, 0F);
            }
            if (navigationCheckCooldown-- < 0 && this.entity.onGround()) {
                navigationCheckCooldown = 20 + entity.getRandom().nextInt(40);
                if (!canReach(target)) {
                    this.startCleanJump();
                }
            }
        }
    }

public void tick() {
        super.tick();
        this.prevGroundProgress = groundProgress;
        this.prevSwimProgress = swimProgress;
        this.prevBaskingProgress = baskingProgress;
        this.prevGrabProgress = grabProgress;

        final boolean ground = !this.isInWater();
        final boolean groundAnimate = !this.isInWater();
        final boolean basking = groundAnimate && this.isSitting();
        final boolean grabbing = !this.getPassengers().isEmpty();

        if (!ground && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (ground && !this.isLandNavigator) {
            switchNavigator(true);
        }

        if (groundAnimate) {
            if (this.groundProgress < 10F)
                this.groundProgress++;

            if (this.swimProgress > 0F)
                this.swimProgress--;
        } else {
            if (this.groundProgress > 0F)
                this.groundProgress--;

            if (this.swimProgress < 10F)
                this.swimProgress++;
        }

        if (basking) {
            if (this.baskingProgress < 10F)
                this.baskingProgress++;
        } else {
            if (this.baskingProgress > 0F)
                this.baskingProgress--;
        }

        if (grabbing) {
            if (this.grabProgress < 10F)
                this.grabProgress++;
        } else {
            if (this.grabProgress > 0F)
                this.grabProgress--;
        }

        if (this.getTarget() == null) {
            if (hasSpedUp) {
                hasSpedUp = false;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
        } else {
            if (!hasSpedUp) {
                hasSpedUp = true;
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.28F);
            }
        }

        if (!this.level().isClientSide) {
            this.setBesideClimbableBlock(this.horizontalCollision);
        }
        if (baskingTimer < 0) {
            baskingTimer++;
        }
        if (passengerTimer > 0 && this.getPassengers().isEmpty()) {
            passengerTimer = 0;
        }
        if (!this.level().isClientSide) {
            if (isInWater()) {
                swimTimer++;
                ticksSinceInWater = 0;
            } else {
                ticksSinceInWater++;
                swimTimer--;
            }

            if (!this.isInWater() && this.onGround()) {
                if (!this.isTame()) {
                    if (!this.isSitting() && baskingTimer == 0 && this.getTarget() == null && this.getNavigation().isDone()) {
                        this.setOrderedToSit(true);
                        this.baskingTimer = 1000 + random.nextInt(750);
                    }
                    if (this.isSitting() && (baskingTimer <= 0 || this.getTarget() != null || swimTimer < -1000)) {
                        this.setOrderedToSit(false);
                        this.baskingTimer = -2000 - random.nextInt(750);
                    }
                    if (this.isSitting() && baskingTimer > 0) {
                        baskingTimer--;
                    }
                }
            }
            if (this.getStunTicks() == 0 && this.isAlive() && this.getTarget() != null && this.getAnimation() == ANIMATION_LUNGE && (level().getDifficulty() != Difficulty.PEACEFUL || !(this.getTarget() instanceof Player)) && this.getAnimationTick() > 5 && this.getAnimationTick() < 9) {
                final float f1 = this.getYRot() * Mth.DEG_TO_RAD;
                this.setDeltaMovement(this.getDeltaMovement().add(-Mth.sin(f1) * 0.02F, 0.0D, Mth.cos(f1) * 0.02F));
                if (this.distanceTo(this.getTarget()) < 3.5F && this.hasLineOfSight(this.getTarget())) {
                    boolean flag = this.getTarget().isBlocking();
                    if (!flag) {
                        if (this.getTarget().getBbWidth() < this.getBbWidth() && this.getPassengers().isEmpty() && !this.getTarget().isShiftKeyDown()) {
                            this.getTarget().startRiding(this, true);
                        }
                    }
                    if (flag) {
                        if (this.getTarget() instanceof final Player player) {
                            this.damageShieldFor(player, (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                        }
                        if (this.getStunTicks() == 0) {
                            this.setStunTicks(25 + random.nextInt(20));
                        }
                    } else {
                        this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                    }
                    this.playSound(AMSoundRegistry.CROCODILE_BITE.get(), this.getSoundVolume(), this.getVoicePitch());

                }
            }
            if (this.isAlive() && this.getTarget() != null && this.isInWater() && (level().getDifficulty() != Difficulty.PEACEFUL || !(this.getTarget() instanceof Player))) {
                if (this.getTarget().getVehicle() != null && this.getTarget().getVehicle() == this) {
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(ANIMATION_DEATHROLL);
                    }
                    if (this.getAnimation() == ANIMATION_DEATHROLL && this.getAnimationTick() % 10 == 0 && this.distanceTo(this.getTarget()) < 5D) {
                        this.getTarget().hurt(this.damageSources().mobAttack(this), 5);
                    }
                }
            }
        }
        if (this.getAnimation() == ANIMATION_DEATHROLL) {
            this.getNavigation().stop();
        }
        if (this.isInLove() && this.getTarget() != null) {
            this.setTarget(null);
        }
        if (this.getStunTicks() > 0) {
            this.setStunTicks(this.getStunTicks() - 1);
            if (this.level().isClientSide) {
                final float angle = (Maths.STARTING_ANGLE * this.yBodyRot);
                final double headX = 1.5F * getScale() * Mth.sin(Mth.PI + angle);
                final double headZ = 1.5F * getScale() * Mth.cos(angle);
                for (int i = 0; i < 5; i++) {
                    final float innerAngle = (Maths.STARTING_ANGLE * (this.yBodyRot + tickCount * 5) * (i + 1));
                    final double extraX = 0.5F * Mth.sin((float) (Math.PI + innerAngle));
                    final double extraZ = 0.5F * Mth.cos(innerAngle);
                    level().addParticle(ParticleTypes.CRIT, true, this.getX() + headX + extraX, this.getEyeY() + 0.5F, this.getZ() + headZ + extraZ, 0, 0, 0);
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void tick() {
        super.tick();
        prevCollidePosX = collidePosX;
        prevCollidePosY = collidePosY;
        prevCollidePosZ = collidePosZ;
        prevYaw = renderYaw;
        prevPitch = renderPitch;
        xo = getX();
        yo = getY();
        zo = getZ();
        if (tickCount == 1 && level().isClientSide) {
            caster = (LivingEntity) level().getEntity(getCasterID());
        }

        if (!level().isClientSide) {
            if (getHasPlayer()) {
                this.updateWithPlayer();
            }
            else if (caster instanceof EntityUmvuthi) {
                this.updateWithUmvuthi();
            }
        }
        if (caster != null) {
            renderYaw = (float) ((caster.yHeadRot + 90.0d) * Math.PI / 180.0d);
            renderPitch = (float) (-caster.getXRot() * Math.PI / 180.0d);
        }

        if (!on && appear.getTimer() == 0) {
            this.discard() ;
        }
        if (on && tickCount > 20) {
            appear.increaseTimer();
        } else {
            appear.decreaseTimer();
        }

        if (caster != null && !caster.isAlive()) discard() ;

        if (level().isClientSide && tickCount <= 10 && caster != null) {
            int particleCount = 8;
            while (--particleCount != 0) {
                double radius = 2f * caster.getBbWidth();
                double yaw = random.nextFloat() * 2 * Math.PI;
                double pitch = random.nextFloat() * 2 * Math.PI;
                double ox = radius * Math.sin(yaw) * Math.sin(pitch);
                double oy = radius * Math.cos(pitch);
                double oz = radius * Math.cos(yaw) * Math.sin(pitch);
                double rootX = caster.getX();
                double rootY = caster.getY() + caster.getBbHeight() / 2f + 0.3f;
                double rootZ = caster.getZ();
                if (getHasPlayer()) {
                    if (caster instanceof Player && !(caster == MMCommon.PROXY.getLocalPlayer() && Minecraft.getInstance().options.getCameraType() == CameraType.FIRST_PERSON)) {
                        GeckoPlayer geckoPlayer = GeckoPlayer.getGeckoPlayer((Player) caster, GeckoPlayer.Perspective.THIRD_PERSON);
                        if (geckoPlayer != null) {
                            GeckoRenderPlayer renderPlayer = (GeckoRenderPlayer) geckoPlayer.getPlayerRenderer();
                            if (renderPlayer.betweenHandsPos != null) {
                                rootX += renderPlayer.betweenHandsPos.x();
                                rootY += renderPlayer.betweenHandsPos.y();
                                rootZ += renderPlayer.betweenHandsPos.z();
                            }
                        }
                    }
                    attractorPos[0] = new Vec3(rootX, rootY, rootZ);
                }
                else if (caster instanceof EntityUmvuthi) {
                    EntityUmvuthi umvuthi = (EntityUmvuthi)caster;
                    if (umvuthi.headPos != null && umvuthi.headPos[0] != null) {
                        attractorPos[0] = ((EntityUmvuthi) caster).headPos[0];
                        rootX = attractorPos[0].x();
                        rootY = attractorPos[0].y();
                        rootZ = attractorPos[0].z();
                    }
                }
                else {
                    attractorPos[0] = new Vec3(rootX, rootY, rootZ);
                }
                AdvancedParticleBase.spawnParticle(level(), ParticleHandler.ORB2, rootX + ox, rootY + oy, rootZ + oz, 0, 0, 0, true, 0, 0, 0, 0, 5F, 1, 1, 1, 1, 1, 7, true, false, new ParticleComponent[]{
                        new ParticleComponent.Attractor(attractorPos, 1.7f, 0.0f, ParticleComponent.Attractor.EnumAttractorBehavior.EXPONENTIAL),
                        new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.ALPHA, new ParticleComponent.KeyTrack(
                                new float[]{0f, 0.8f},
                                new float[]{0f, 1f}
                        ), false),
                        new ParticleComponent.PropertyControl(ParticleComponent.PropertyControl.EnumParticleProperty.SCALE, new ParticleComponent.KeyTrack(
                                new float[]{3f, 6f},
                                new float[]{0f, 1f}
                        ), false)
                });
            }
        }
        if (tickCount > 20) {
            this.calculateEndPos();
            List<Entity> hit = raytraceEntities(level(), new Vec3(getX(), getY(), getZ()), new Vec3(endPosX, endPosY, endPosZ), false, true, true).entities;
            if (blockSide != null) {
                spawnExplosionParticles(2);
            }
            if (!level().isClientSide) {
                for (Entity target : hit) {
                    if (target instanceof ItemEntity) continue;
                    if (caster instanceof EntityUmvuthi && target instanceof LeaderSunstrikeImmune) {
                        continue;
                    }
                    float damageFire = 1f;
                    float damageMob = 1.5f;
                    if (caster instanceof EntityUmvuthi) {
                        damageFire *= ConfigHandler.COMMON.MOBS.UMVUTHI.combatConfig.attackMultiplier.get();
                        damageMob *= ConfigHandler.COMMON.MOBS.UMVUTHI.combatConfig.attackMultiplier.get();
                    }
                    if (caster instanceof Player) {
                        damageFire *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.SUNS_BLESSING.sunsBlessingAttackMultiplier.get() * 0.75;
                        damageMob *= ConfigHandler.COMMON.TOOLS_AND_ABILITIES.SUNS_BLESSING.sunsBlessingAttackMultiplier.get() * 0.75;
                    }
                    if (target instanceof LivingEntity) {
                        DamageUtil.dealMixedDamage((LivingEntity) target, damageSources().mobProjectile(this, caster), damageMob, damageSources().onFire(), damageFire);
                    }
                    else {
                        target.hurt(damageSources().mobProjectile(this, caster), damageMob);
                    }
                }
            } else {
                if (tickCount - 15 < getDuration()) {
                    int particleCount = 4;
                    while (particleCount --> 0) {
                        double radius = 1f;
                        double yaw = (float) (random.nextFloat() * 2 * Math.PI);
                        double pitch = (float) (random.nextFloat() * 2 * Math.PI);
                        double ox = (float) (radius * Math.sin(yaw) * Math.sin(pitch));
                        double oy = (float) (radius * Math.cos(pitch));
                        double oz = (float) (radius * Math.cos(yaw) * Math.sin(pitch));
                        double o2x = (float) (-1 * Math.cos(getYaw()) * Math.cos(getPitch()));
                        double o2y = (float) (-1 * Math.sin(getPitch()));
                        double o2z = (float) (-1 * Math.sin(getYaw()) * Math.cos(getPitch()));
                        level().addParticle(ParticleOrb.Data.create((float) (collidePosX + o2x + ox), (float) (collidePosY + o2y + oy), (float) (collidePosZ + o2z + oz), 15), getX() + o2x + ox, getY() + o2y + oy, getZ() + o2z + oz, 0, 0, 0);
                    }
                    particleCount = 4;
                    while (particleCount --> 0) {
                        double radius = 2f;
                        double yaw = random.nextFloat() * 2 * Math.PI;
                        double pitch = random.nextFloat() * 2 * Math.PI;
                        double ox = radius * Math.sin(yaw) * Math.sin(pitch);
                        double oy = radius * Math.cos(pitch);
                        double oz = radius * Math.cos(yaw) * Math.sin(pitch);
                        double o2x = -1 * Math.cos(getYaw()) * Math.cos(getPitch());
                        double o2y = -1 * Math.sin(getPitch());
                        double o2z = -1 * Math.sin(getYaw()) * Math.cos(getPitch());
                        level().addParticle(ParticleOrb.Data.create((float) (collidePosX + o2x + ox), (float) (collidePosY + o2y + oy), (float) (collidePosZ + o2z + oz), 20), collidePosX + o2x, collidePosY + o2y, collidePosZ + o2z, 0, 0, 0);
                    }
                }
            }
        }
        if (tickCount - 20 > getDuration()) {
            on = false;
        }
    }

public void tick() {
        super.tick();
        if (this.tickCount % 5 == 0) {
            this.bossInfo.update();
        }
        this.bossInfo.setProgress(this.getHealth() / this.getMaxHealth());
        if (this.isDeadOrDying()){
            this.setAnimationState(DEATH);
            this.setYRot(this.deathRotation);
            this.setYBodyRot(this.deathRotation);
        }
        if (this.hasPose(Pose.EMERGING)){
            ++this.activateTick;
            this.setAnimationState(ACTIVATE);
            if (this.activateTick == 1){
                this.playSound(ModSounds.REDSTONE_MONSTROSITY_AWAKEN.get(), 10.0F, 1.0F);
            }
            if (this.activateTick == 40){
                CameraShake.cameraShake(this.level, this.position(), 40.0F, 0.5F, 0, 20);
            }
            if (this.activateTick > MathHelper.secondsToTicks(3.25F)){
                this.setPose(Pose.STANDING);
            }
        }
        MiscCapHelper.updateMobTarget(this);
        if (this.level.isClientSide) {
            this.idleAnimationState.animateWhen(this.isCurrentAnimation(IDLE) && !this.walkAnimation.isMoving(), this.tickCount);
        }
        if (!this.level.isClientSide){
            if (this.isAlive() && !this.isActivating()) {
                if (MobsConfig.RedstoneMonstrosityLeafBreak.get()) {
                    if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level, this)) {
                        boolean flag = false;
                        AABB aabb = this.getBoundingBox().inflate(0.2D);

                        for (BlockPos blockpos : BlockPos.betweenClosed(Mth.floor(aabb.minX), Mth.floor(aabb.minY), Mth.floor(aabb.minZ), Mth.floor(aabb.maxX), Mth.floor(aabb.maxY), Mth.floor(aabb.maxZ))) {
                            BlockState blockstate = this.level.getBlockState(blockpos);
                            Block block = blockstate.getBlock();
                            if (block instanceof LeavesBlock || blockstate.is(ModTags.Blocks.MONSTROSITY_BREAKS)) {
                                flag = this.level.destroyBlock(blockpos, true, this) || flag;
                            }
                        }
                    }
                }
                if (!this.isMeleeAttacking() && !this.isBelching() && !this.isSummoning()) {
                    this.level.broadcastEntityEvent(this, (byte) 7);
                    this.setAnimationState(IDLE);
                }
                if (this.isMeleeAttacking()) {
                    ++this.attackTick;
                    if (this.attackTick > MathHelper.secondsToTicks(3.3F)){
                        this.setMeleeAttacking(false);
                    }
                }
                if (this.isSummoning()) {
                    this.makeBigGlow();
                    --this.summonTick;
                    if (this.level instanceof ServerLevel serverLevel) {
                        for (int i = 0; i < 5; ++i) {
                            double d0 = serverLevel.random.nextGaussian() * 0.02D;
                            double d1 = serverLevel.random.nextGaussian() * 0.02D;
                            double d2 = serverLevel.random.nextGaussian() * 0.02D;
                            serverLevel.sendParticles(ModParticleTypes.ELECTRIC.get(), this.getRandomX(0.5D), this.getEyeY() - serverLevel.random.nextInt(2), this.getRandomZ(0.5D), 0, d0, d1, d2, 0.5F);
                        }
                        if (this.summonTick < MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 1)
                            && this.summonTick >= MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 2)) {
                            if (!this.level.getBlockState(this.blockPosition().below()).isAir()) {
                                for (int j = 0; j < 4; ++j) {
                                    double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() * 2.0D;
                                    double d2 = this.blockPosition().getY() + 0.5F;
                                    double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() * 2.0D;
                                    serverLevel.sendParticles(ModParticleTypes.BIG_FIRE_GROUND.get(), d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
                                }
                            }
                        }
                        if (this.summonTick == MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 1)){
                            ColorUtil colorUtil = new ColorUtil(0xff8200);
                            serverLevel.sendParticles(new SmashParticleOption(colorUtil, 3, 1.5F, 10), this.getXLeft(), BlockFinder.moveDownToGround(this), this.getZLeft(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                            serverLevel.sendParticles(new SmashParticleOption(colorUtil, 3, 1.5F, 10), this.getXRight(), BlockFinder.moveDownToGround(this), this.getZRight(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                            ServerParticleUtil.sendGodRay(serverLevel, this.getXLeft(), BlockFinder.moveDownToGround(this), this.getZLeft(), colorUtil);
                            ServerParticleUtil.sendGodRay(serverLevel, this.getXRight(), BlockFinder.moveDownToGround(this), this.getZRight(), colorUtil);
                            this.playSound(ModSounds.REDSTONE_MONSTROSITY_BELCH.get(), this.getSoundVolume(), 0.7F);
                            AABB aabb = new AABB(this.blockPosition());
                            for (LivingEntity target : this.level.getEntitiesOfClass(LivingEntity.class, aabb.inflate(MELEE_RANGE / 2.0F))) {
                                if (target != this && !MobUtil.areAllies(this, target)) {
                                    if (target.hurt(this.damageSources().mobAttack(this), 2.0F)){
                                        float f1 = 2.0F;
                                        if (target.getBoundingBox().getSize() > this.getBoundingBox().getSize()){
                                            target.knockback((double)(f1 * 0.5F), (double) Mth.sin(this.getYRot() * ((float)Math.PI / 180F)), (double)(-Mth.cos(this.getYRot() * ((float)Math.PI / 180F))));
                                        } else {
                                            MobUtil.forcefulKnockBack(target, (double)(f1 * 0.5F), (double)Mth.sin(this.getYRot() * ((float)Math.PI / 180F)), (double)(-Mth.cos(this.getYRot() * ((float)Math.PI / 180F))), 0.5D);
                                        }
                                    }
                                }
                            }
                        }
                        if (this.summonTick == MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 1.2F)) {
                            CameraShake.cameraShake(this.level, this.position(), 25.0F, 0.3F, 0, 20);
                        }
                        if (this.summonTick <= (MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 2)) && this.summonCount != 0) {
                            for (int i = 0; i < 10; ++i){
                                BlockPos blockPos = this.blockPosition();
                                blockPos = blockPos.offset(-16 + this.level.random.nextInt(32), 0, -16 + this.level.random.nextInt(32));
                                Vec3 vec3 = Vec3.atBottomCenterOf(blockPos);
                                Summoned summoned = new RedstoneCube(ModEntityType.REDSTONE_CUBE.get(), this.level);
                                if (this.level.noCollision(summoned, summoned.getBoundingBox().move(vec3))){
                                    SummonCircleVariant summonCircle = new SummonCircleVariant(this.level, vec3, summoned, this);
                                    summonCircle.playSound(ModSounds.DIRT_DEBRIS.get(), 3.0F, 0.4F);
                                    this.level.addFreshEntity(summonCircle);
                                }
                            }
                            this.summonCount = 0;
                        }
                        if (this.summonTick <= 1){
                            if (this.summonCool <= 0) {
                                this.summonCool = MathHelper.secondsToTicks(13);
                            }
                            if (this.postAttackCool <= 0) {
                                this.postAttackCool = (int) MathHelper.secondsToTicks(0.5F);
                            }
                        }
                    }
                }
                if (this.summonCool > 0) {
                    --this.summonCool;
                }
                if (this.postAttackCool > 0) {
                    --this.postAttackCool;
                }
                if (this.belchCool > 0){
                    --this.belchCool;
                }
            }
        } else {
            if (this.isAlive()) {
                if (this.bigGlowCool > 0){
                    --this.bigGlowCool;
                }
                if (!this.isActivating()) {
                    if (this.bigGlow > 0.0F) {
                        if (this.bigGlowCool <= 0) {
                            this.bigGlow -= 0.1F;
                        }
                    } else {
                        this.glow();
                    }
                } else {
                    if (this.activateTick > 40){
                        this.bigGlow = 1.0F;
                    }
                }
            }
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();

		if (world.isRemote) {
			prevGrowCount = growCount;
			growCount = getGrowTimer();
			if(ticksExisted % 10 == 0) {
				renderParticles(world, posX, posY, posZ, rand);
			}
			if(this.sheddingProgress > this.getSheddingSpeed()) {
				this.sheddingProgress = 0;

				for(int i = 0; i < 200; i++) {
					Random rnd = world.rand;
					float rx = rnd.nextFloat() * 4.0F - 2.0F;
					float ry = rnd.nextFloat() * 4.0F - 2.0F;
					float rz = rnd.nextFloat() * 4.0F - 2.0F;
					Vec3d vec = new Vec3d(rx, ry, rz);
					vec = vec.normalize();
					BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.25F, this.posY + ry, this.posZ + rz + 0.25F, ParticleArgs.get().withMotion(vec.x * 0.5F, vec.y * 0.5F, vec.z * 0.5F));
				}
			} else if(this.isShedding() || this.sheddingProgress > 0) {
				this.sheddingProgress++;
			} else {
				this.sheddingProgress = 0;
			}

			if(this.isSucking()) {
				for(int i = 0; i < 5; i++) {
					Random rnd = world.rand;
					float rx = rnd.nextFloat() * 8.0F - 4.0F;
					float ry = rnd.nextFloat() * 8.0F - 4.0F;
					float rz = rnd.nextFloat() * 8.0F - 4.0F;
					Vec3d vec = new Vec3d(rx, ry, rz);
					vec = vec.normalize();
					this.world.spawnParticle(EnumParticleTypes.SMOKE_LARGE, this.posX + rx + 0.25F, this.posY + ry, this.posZ + rz + 0.25F, -vec.x * 0.5F, -vec.y * 0.5F, -vec.z * 0.5F);
				}
			}
		}

		if(!world.isRemote) {
			if(this.isInsideOfMaterial(BLMaterialRegistry.TAR)) {
				this.stepHeight = 2.0F;
			} else {
				this.stepHeight = 0.75F;
			}

			if(this.shedCooldown > 0 && this.getAttackTarget() != null) {
				this.shedCooldown--;
			}

			if(!this.isSucking() && !this.isPreparing()) {
				if(this.shedCooldown == 0 && this.getAttackTarget() != null && this.getAttackTarget().getDistance(this) < 6.0D && this.canEntityBeSeen(this.getAttackTarget())) {
					this.setShedding(true);
					this.shedCooldown = this.getSheddingCooldown() + this.world.rand.nextInt(this.getSheddingCooldown() / 2);
				}

				if(this.sheddingProgress > this.getSheddingSpeed()) {
					this.playSound(SoundRegistry.TAR_BEAST_LIVING, 1F, (this.rand.nextFloat() * 0.2F + 1.0F) * 0.6F);
					for(int i = 0; i < 8; i++) {
						this.playSound(SoundRegistry.TAR_BEAST_STEP, 1F, (this.rand.nextFloat() * 0.4F + 0.8F) * 0.8F);
					}
					this.sheddingProgress = 0;
					this.setShedding(false);
					if(this.getAttackTarget() != null) {
						List<EntityLivingBase> affectedEntities = (List<EntityLivingBase>)this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(6.0F, 6.0F, 6.0F));
						for(EntityLivingBase e : affectedEntities) {
							if(e == this || e.getDistance(this) > 6.0F || !e.canEntityBeSeen(this) || e instanceof EntityTarBeast) continue;
							if(e instanceof EntityPlayer) {
								if(((EntityPlayer)e).isActiveItemStackBlocking()) continue;
							}
							double dst = e.getDistance(this);
							float dmg = (float) (this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue() / dst * 7.0F);
							e.attackEntityFrom(DamageSource.causeMobDamage(this), dmg);
							e.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, (int)(20 + (1.0F - dst / 6.0F) * 150), 1));
						}
					}
				}

				if(this.isShedding()) {
					this.sheddingProgress++;
				} else {
					this.sheddingProgress = 0;
				}
			}

			if(this.suckingCooldown > 0 && this.getAttackTarget() != null) {
				this.suckingCooldown--;
			}

			if(!this.isShedding()) {
				if(this.suckingCooldown == 0 && this.getAttackTarget() != null && this.getAttackTarget().getDistance(this) <= 10.0D && this.canEntityBeSeen(this.getAttackTarget())) {
					this.setPreparing();
				}

				if(this.isPreparing()) {
					this.suckingPreparation++;

					if(this.suckingPreparation > this.getEntityAttribute(SUCK_PREPARATION_SPEED_ATTRIB).getAttributeValue()) {
						this.suckingPreparation = 0;

						this.setSucking(true);
						this.suckingCooldown = this.getSuckingCooldown() + this.world.rand.nextInt(this.getSuckingCooldown() / 2);
						this.playSound(SoundRegistry.TAR_BEAST_SUCK, 1F, 1F);
					}
				}

				if(this.suckingProgress > (int)this.getEntityAttribute(SUCK_LENGTH_ATTRIB).getAttributeValue()) {
					this.setSucking(false);
					this.suckingProgress = 0;
				}

				if(this.isSucking()) {
					this.suckingProgress++;

					List<Entity> affectedEntities = (List<Entity>)this.world.getEntitiesWithinAABB(Entity.class, this.getEntityBoundingBox().grow(10.0F, 10.0F, 10.0F));
					for(Entity e : affectedEntities) {
						if(e == this || e.getDistance(this) > 10.0F || !this.canEntityBeSeen(e) || e instanceof EntityTarBeast) continue;
						Vec3d vec = new Vec3d(this.posX - e.posX, this.posY - e.posY, this.posZ - e.posZ);
						vec = vec.normalize();
						float dst = e.getDistance(this);
						float mod = (float) Math.pow(1.0F - dst / 13.0F, 1.2D);
						if(e instanceof EntityPlayer) {
							if(((EntityPlayer)e).isActiveItemStackBlocking()) mod *= 0.18F;
						}
						if(dst < 1.0F && e instanceof EntityLivingBase) {
							((EntityLivingBase) e).addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, 20, 3));
							((EntityLivingBase) e).addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, 20, 3));
							e.motionX *= 0.008F;
							e.motionY *= 0.008F;
							e.motionZ *= 0.008F;
							if(e instanceof EntityPlayer) {
								((EntityPlayer)e).jumpMovementFactor = 0.0F;
							}
							if(this.ticksExisted % 12 == 0) {
								e.attackEntityFrom(DamageSource.DROWN, 1);
							}
						}
						e.motionX += vec.x * 0.18F * mod;
						e.motionY += vec.y * 0.18F * mod;
						e.motionZ += vec.z * 0.18F * mod;
						e.velocityChanged = true;
					}
					getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(0.75D);
				} else {
					this.suckingProgress = 0;
					getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(1.0D);
				}
			}

			if (getGrowTimer() < 40) {
				setGrowTimer(Math.min(40, getGrowTimer() + 1));
			}
		}
	}

@Override
    public void aiStep() {
        super.aiStep();
        LivingEntity attackTarget = this.getTarget();
        if (this.level.getDifficulty() == Difficulty.PEACEFUL && attackTarget instanceof Player) {
            this.setTarget(null);
        }
        if (this.isOrderedToSit() && this.getCommand() != 1) {
            this.setOrderedToSit(false);
        }
        if (this.isOrderedToSit() && attackTarget != null) {
            this.setTarget(null);
        }
        if (attackTarget != null && this.isAlliedTo(attackTarget)) {
            this.setTarget(null);
        }
        if (!level.isClientSide) {
            if (attackTarget == null || !attackTarget.isAlive()) {
                this.setTargetedEntity(0);
            } else if (this.isStaring() || this.shouldStareAttack(attackTarget)) {
                this.setTargetedEntity(attackTarget.getId());
            }
        }
        if (this.getAnimation() == ANIMATION_BITE && attackTarget != null && this.getAnimationTick() == 7) {
            double dist = this.distanceToSqr(attackTarget);
            if (dist < 8) {
                attackTarget.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (this.getAnimation() == ANIMATION_JUMPAT && attackTarget != null) {
            double dist = this.distanceToSqr(attackTarget);
            double d0 = attackTarget.getX() - this.getX();
            double d1 = attackTarget.getZ() - this.getZ();
            float leap = Mth.sqrt((float) (d0 * d0 + d1 * d1));
            if (dist <= 16.0D && this.isOnGround() && this.getAnimationTick() > 7 && this.getAnimationTick() < 12) {
                Vec3 Vector3d = this.getDeltaMovement();
                Vec3 Vector3d1 = new Vec3(attackTarget.getX() - this.getX(), 0.0D, attackTarget.getZ() - this.getZ());
                if (Vector3d1.lengthSqr() > 1.0E-7D) {
                    Vector3d1 = Vector3d1.normalize().scale(0.4D).add(Vector3d.scale(0.2D));
                }
            }
            if (dist < 4 && this.getAnimationTick() > 10) {
                attackTarget.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
                if ((double) leap >= 1.0E-4D) {
                    attackTarget.setDeltaMovement(attackTarget.getDeltaMovement().add(d0 / (double) leap * 0.800000011920929D + this.getDeltaMovement().x * 0.20000000298023224D, 0, d1 / (double) leap * 0.800000011920929D + this.getDeltaMovement().z * 0.20000000298023224D));
                }
            }
        }
        boolean sitting = isOrderedToSit();
        if (sitting && sitProgress < 20.0F) {
            sitProgress += 0.5F;
        } else if (!sitting && sitProgress > 0.0F) {
            sitProgress -= 0.5F;
        }

        boolean staring = isStaring();
        if (staring && stareProgress < 20.0F) {
            stareProgress += 0.5F;
        } else if (!staring && stareProgress > 0.0F) {
            stareProgress -= 0.5F;
        }
        if (!level.isClientSide) {
            if (staring) {
                ticksStaring++;
            } else {
                ticksStaring = 0;
            }
        }
        if (!level.isClientSide && staring && (attackTarget == null || this.shouldMelee())) {
            this.setStaring(false);
        }
        if (attackTarget != null) {
            this.getLookControl().setLookAt(attackTarget.getX(), attackTarget.getY() + (double) attackTarget.getEyeHeight(), attackTarget.getZ(), (float) this.getMaxHeadYRot(), (float) this.getMaxHeadXRot());
            if (!shouldMelee() && attackTarget instanceof Mob) {
                forcePreyToLook((Mob) attackTarget);
            }
        }
        boolean blindness = this.hasEffect(MobEffects.BLINDNESS) || attackTarget != null && attackTarget.hasEffect(MobEffects.BLINDNESS);
        if (blindness) {
            this.setStaring(false);
        }
        if (!this.level.isClientSide && !blindness && attackTarget != null && EntityGorgon.isEntityLookingAt(this, attackTarget, VIEW_RADIUS) && EntityGorgon.isEntityLookingAt(attackTarget, this, VIEW_RADIUS) && !EntityGorgon.isBlindfolded(attackTarget)) {
            if (!shouldMelee()) {
                if (!this.isStaring()) {
                    this.setStaring(true);
                } else {
                    int attackStrength = this.getFriendsCount(attackTarget);
                    if (this.level.getDifficulty() == Difficulty.HARD) {
                        attackStrength++;
                    }
                    attackTarget.addEffect(new MobEffectInstance(MobEffects.WITHER, 10, 2 + Math.min(1, attackStrength)));
                    attackTarget.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, 10, Math.min(4, attackStrength)));
                    attackTarget.addEffect(new MobEffectInstance(MobEffects.CONFUSION, 200, 0));
                    if (attackStrength >= 2 && attackTarget.tickCount % 40 == 0) {
                        attackTarget.hurt(DamageSource.WITHER, attackStrength - 1);
                    }
                    attackTarget.setLastHurtByMob(this);
                    if (!this.isTame() && attackTarget instanceof Player) {
                        this.setTamingPlayer(attackTarget.getId());
                        this.setTamingLevel(this.getTamingLevel() + 1);
                        if (this.getTamingLevel() % 100 == 0) {
                            this.level.broadcastEntityEvent(this, (byte) 46);
                        }
                        if (this.getTamingLevel() >= 1000) {
                            this.level.broadcastEntityEvent(this, (byte) 45);
                            if (this.getTamingPlayer() instanceof Player)
                                this.tame((Player) this.getTamingPlayer());
                            this.setTarget(null);
                            this.setTamingPlayer(0);
                            this.setTargetedEntity(0);
                        }
                    }
                }
            }
        }
        if (!this.level.isClientSide && attackTarget == null && this.getRandom().nextInt(300) == 0 && this.getAnimation() == NO_ANIMATION) {
            this.setAnimation(ANIMATION_WATTLESHAKE);
        }
        if (!this.level.isClientSide) {
            if (shouldMelee() && !this.isMeleeMode) {
                switchAI(true);
            }
            if (!shouldMelee() && this.isMeleeMode) {
                switchAI(false);
            }
        }

        if (this.level.isClientSide && this.getTargetedEntity() != null && EntityGorgon.isEntityLookingAt(this, this.getTargetedEntity(), VIEW_RADIUS) && EntityGorgon.isEntityLookingAt(this.getTargetedEntity(), this, VIEW_RADIUS) && this.isStaring()) {
            if (this.hasTargetedEntity()) {
                if (this.clientSideAttackTime < this.getAttackDuration()) {
                    ++this.clientSideAttackTime;
                }

                LivingEntity livingEntity = this.getTargetedEntity();

                if (livingEntity != null) {
                    this.getLookControl().setLookAt(livingEntity, 90.0F, 90.0F);
                    this.getLookControl().tick();
                    double d5 = this.getAttackAnimationScale(0.0F);
                    double d0 = livingEntity.getX() - this.getX();
                    double d1 = livingEntity.getY() + (double) (livingEntity.getBbHeight() * 0.5F) - (this.getY() + (double) this.getEyeHeight());
                    double d2 = livingEntity.getZ() - this.getZ();
                    double d3 = Math.sqrt(d0 * d0 + d1 * d1 + d2 * d2);
                    d0 = d0 / d3;
                    d1 = d1 / d3;
                    d2 = d2 / d3;
                    double d4 = this.random.nextDouble();

                    while (d4 < d3) {
                        d4 += 1.8D - d5 + this.random.nextDouble() * (1.7D - d5);
                        this.level.addParticle(ParticleTypes.ENTITY_EFFECT, this.getX() + d0 * d4, this.getY() + d1 * d4 + (double) this.getEyeHeight(), this.getZ() + d2 * d4, 0.0D, 0.0D, 0.0D);
                    }
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void onUpdate() {
        super.onUpdate();
        if(this.world.isRemote && this.dataManager.get(WATCHER_WAS_FED)) {
            this.world.spawnParticle(EnumParticleTypes.VILLAGER_HAPPY, this.posX + (double)(this.rand.nextFloat() * this.width * 2.0F) - (double)this.width, this.posY + 0.5D + (double)(this.rand.nextFloat() * this.height), this.posZ + (double)(this.rand.nextFloat() * this.width * 2.0F) - (double)this.width, 0.0D, 0.0D, 0.0D);
        }
        if (!this.world.isRemote) {
            DinosaurPersistenceHandler.trackEntity(this);
        }
        if(this.ticksUntilDeath > 0) {
            if(--this.ticksUntilDeath == 0) {
                this.playSound(this.getSoundForAnimation(EntityAnimation.DYING.get()), this.getSoundVolume(), this.getSoundPitch());
                this.setHealth(this.getMaxHealth());
                this.setCarcass(true);
            }
        }

        if (this.attackCooldown > 0) {
            this.attackCooldown--;
        }

        if (!this.world.isRemote) {
            if (this.animation == EntityAnimation.LEAP.get()) {
                if (this.motionY < 0) {
                    this.setAnimation(EntityAnimation.LEAP_LAND.get());
                }
            } else if (this.animation == EntityAnimation.LEAP_LAND.get() && (this.onGround || this.isSwimming())) {
                this.setAnimation(EntityAnimation.IDLE.get());
            }
        }

        if (this.animation != null && this.animation != EntityAnimation.IDLE.get()) {
            boolean shouldHold = EntityAnimation.getAnimation(this.animation).shouldHold();

            if (this.animationTick < this.animationLength) {
                this.animationTick++;
            } else if (!shouldHold) {
                this.animationTick = 0;
                if (this.animation == EntityAnimation.PREPARE_LEAP.get()) {
                    this.setAnimation(EntityAnimation.LEAP.get());
                } else {
                    this.setAnimation(EntityAnimation.IDLE.get());
                }
            } else {
                this.animationTick = this.animationLength - 1;
            }
        }

        if (!this.world.isRemote) {
            this.dataManager.set(WATCHER_WAS_MOVED, this.wasMoved);
            this.dataManager.set(WATCHER_AGE, this.dinosaurAge);
            this.dataManager.set(WATCHER_IS_SLEEPING, this.isSleeping);
            this.dataManager.set(WATCHER_IS_CARCASS, this.isCarcass);
            this.dataManager.set(WATCHER_TRACKERS, new ArrayList<>(this.trackersUUID)); // Ensure a new list is set
            this.dataManager.set(WATCHER_CURRENT_ORDER, (byte) this.order.ordinal());
            this.dataManager.set(WATCHER_OWNER_IDENTIFIER, this.owner != null ? this.owner.toString() : "");
            this.dataManager.set(WATCHER_IS_RUNNING, this.getAIMoveSpeed() > this.getEntityAttribute(SharedMonsterAttributes.MOVEMENT_SPEED).getAttributeValue());
        } else {
            this.updateTailBuffer();
            this.wasMoved = this.dataManager.get(WATCHER_WAS_MOVED);
            this.dinosaurAge = this.dataManager.get(WATCHER_AGE);
            this.isSleeping = this.dataManager.get(WATCHER_IS_SLEEPING);
            this.isCarcass = this.dataManager.get(WATCHER_IS_CARCASS);
            try {
                this.trackersUUID = new ArrayList<>(this.dataManager.get(WATCHER_TRACKERS));
            } catch (ClassCastException e) {
                this.trackersUUID = new ArrayList<>();
            }
            String owner = this.dataManager.get(WATCHER_OWNER_IDENTIFIER);
            this.order = Order.values()[this.dataManager.get(WATCHER_CURRENT_ORDER)];

            if (!owner.isEmpty() && (this.owner == null || !owner.equals(this.owner.toString()))) {
                this.owner = UUID.fromString(owner);
            } else if (owner.isEmpty()) {
                this.owner = null;
            }
        }

        if (this.ticksExisted % 20 == 0) {
            this.updateAttributes();
            this.updateBounds();
        }

        if (this.isCarcass) {
            this.renderYawOffset = this.rotationYaw;
            this.rotationYawHead = this.rotationYaw;
        }

        if (this.isSleeping) {
            if (this.getAnimation() != EntityAnimation.SLEEPING.get()) {
                this.setAnimation(EntityAnimation.SLEEPING.get());
            }
        } else if (this.getAnimation() == EntityAnimation.SLEEPING.get()) {
            this.setAnimation(EntityAnimation.IDLE.get());
        }

        if (!this.world.isRemote) {
            if (this.isCarcass) {
                if (this.getAnimation() != EntityAnimation.DYING.get()) {
                    this.setAnimation(EntityAnimation.DYING.get());
                }

                if (this.ticksExisted % 1000 == 0) {
                    this.attackEntityFrom(DamageSource.GENERIC, 1.0F);
                }
            } else {
                if (this.isSleeping) {
                    if (this.ticksExisted % 20 == 0) {
                        if (this.stayAwakeTime <= 0 && this.hasPredators()) {
                            this.disturbSleep();
                        }
                    }

                    if (!this.shouldSleep() && !this.world.isRemote && tranquilizerTicks-- <= 0) {
                        this.isSleeping = false;
                        this.tranquilizerTicks = 0;
                        this.tranqed = false;
                    }
                } else if (this.getAnimation() == EntityAnimation.SLEEPING.get()) {
                    this.setAnimation(EntityAnimation.IDLE.get());
                }

                if (!this.isSleeping) {
                    if (this.order == Order.SIT) {
                        if (this.getAnimation() != EntityAnimation.RESTING.get()) {
                            this.setAnimation(EntityAnimation.RESTING.get());
                        }
                    } else if (!this.isSittingNaturally && this.getAnimation() == EntityAnimation.RESTING.get() && !this.world.isRemote) {
                        this.setAnimation(EntityAnimation.IDLE.get());
                    }
                }
            }
        }

        if (!this.shouldSleep() && !this.isSleeping) {
            this.stayAwakeTime = 0;
        }

        if (this.isServerWorld()) {
            this.animationTasks.onUpdateTasks();
        }

        if (this.stayAwakeTime > 0) {
            this.stayAwakeTime--;
        }
        if (this.wireTicks > 0) {
            this.wireTicks--;
        }
        if (this.disableHerdingTicks > 0) {
            this.disableHerdingTicks--;
        }

        if (this.legSolver != null) {
            double msc = dinosaur.getScaleInfant() / dinosaur.getScaleAdult();
            this.legSolver.update(this, (float) this.interpolate(msc, 1.0) * this.getAttributes().getScaleModifier());
        }

        this.prevAge = this.dinosaurAge;
    }

@Override
     protected void onImpact(RayTraceResult rayTraceResult) {
     	 boolean collided = false;
         boolean entityCollision = false;
         boolean blockCollision = false;
     	
     	// Entity Hit:
     	if(rayTraceResult.entityHit != null) {
     		if(this.getThrower() != null && rayTraceResult.entityHit == this.getThrower())
     			return;
     		boolean doDamage = true;
 			if(rayTraceResult.entityHit instanceof EntityLivingBase) {
 				doDamage = this.canDamage((EntityLivingBase)rayTraceResult.entityHit);
 			}
 			if(!this.getEntityWorld().isRemote) {
				if (this.getThrower() == null || rayTraceResult.entityHit != this.getThrower()) {
					this.onEntityCollision(rayTraceResult.entityHit);
				}
			}
			if(doDamage) {
 				if(rayTraceResult.entityHit instanceof EntityLivingBase) {
 					EntityLivingBase target = (EntityLivingBase)rayTraceResult.entityHit;
 					if(this.onEntityLivingDamage(target)) {
 						//movingObjectPosition.entityHit.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()), this.getDamage((EntityLivingBase)movingObjectPosition.entityHit));

                        boolean attackSuccess = false;
 						float damage = this.getDamage(target);

 						if(damage != 0) {
							float damageInit = damage;

							// Prevent Knockback:
							double targetKnockbackResistance = 0;
							boolean stopKnockback = false;
							if (this.knockbackChance < 1) {
								if (this.knockbackChance <= 0 || this.rand.nextDouble() <= this.knockbackChance) {
									if (target instanceof EntityLivingBase) {
										targetKnockbackResistance = target.getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).getAttributeValue();
										target.getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(1);
										stopKnockback = true;
									}
								}
							}

							// Deal Damage:
							if (this.getThrower() instanceof EntityCreatureBase) {
								EntityCreatureBase creatureThrower = (EntityCreatureBase) this.getThrower();
								attackSuccess = creatureThrower.doRangedDamage(target, this, damage);
							}
							else {
								double pierceDamage = 1;
								if (damage <= pierceDamage)
									attackSuccess = target.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()).setDamageBypassesArmor().setDamageIsAbsolute(), damage);
								else {
									int hurtResistantTimeBefore = target.hurtResistantTime;
									target.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()).setDamageBypassesArmor().setDamageIsAbsolute(), (float) pierceDamage);
									target.hurtResistantTime = hurtResistantTimeBefore;
									damage -= pierceDamage;
									attackSuccess = target.attackEntityFrom(DamageSource.causeThrownDamage(this, this.getThrower()), damage);
								}
							}

							this.onDamage(target, damageInit, attackSuccess);

							// Restore Knockback:
							if (stopKnockback) {
								target.getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(targetKnockbackResistance);
							}
						}
 					}
 				}
 			}
 			collided = true;
            entityCollision = true;

     		int i = (int)Math.floor(rayTraceResult.entityHit.posX);
     		int j = (int)Math.floor(rayTraceResult.entityHit.posY);
            int k = (int)Math.floor(rayTraceResult.entityHit.posZ);
            BlockPos pos = new BlockPos(i, j, k);
            if(!this.getEntityWorld().isRemote && this.canDestroyBlock(pos)) {
            	try {
					this.placeBlock(this.getEntityWorld(), pos);
				}
				catch(Exception e) {}
			}
     	}
     	
     	// Block Hit:
     	else {
			int i = rayTraceResult.getBlockPos().getX();
			int j = rayTraceResult.getBlockPos().getY();
			int k = rayTraceResult.getBlockPos().getZ();
			BlockPos blockPos = new BlockPos(i, j, k);
			IBlockState blockState = this.getEntityWorld().getBlockState(blockPos);
			if (blockState.getBlock() instanceof BlockTallGrass || blockState.getBlock() == Blocks.DOUBLE_PLANT) {
				if (this.cutsGrass) {
					world.destroyBlock(blockPos, false);
				}
			}
			else {
				collided = blockState.getMaterial().isSolid();
				if (!this.waterProof && blockState.getMaterial() == Material.WATER) {
					collided = true;
				}
				if (!this.lavaProof && blockState.getMaterial() == Material.LAVA) {
					collided = true;
				}
			}
             
 	        if(collided) {
                blockCollision = true;
 	            switch(rayTraceResult.sideHit) {
                    case DOWN:
 		                --j;
 		                break;
                    case UP:
 		                ++j;
 		                break;
                    case SOUTH:
 		                --k;
 		                break;
                    case NORTH:
 		                ++k;
 		                break;
                    case WEST:
 		                --i;
 		                break;
                    case EAST:
 		                ++i;
 	            }

                BlockPos pos = new BlockPos(i, j, k);
 	            if(!this.getEntityWorld().isRemote && this.canDestroyBlock(pos)) {
 	            	try {
						this.placeBlock(this.getEntityWorld(), pos);
					}
					catch(Exception e) {}
				}
 	        }
     	}
     	
     	if(collided) {
 	    	// Impact Particles:
 	        if(!this.getEntityWorld().isRemote) {
				this.onImpact();
			}
 	        else {
				this.onImpactVisuals();
			}
 	        
 	        // Remove Projectile:
            boolean entityPierced = this.pierce && entityCollision;
            boolean blockPierced = this.pierceBlocks && blockCollision;
 	        if(!this.getEntityWorld().isRemote && !entityPierced && !blockPierced) {
 	            this.setDead();
				if(this.getImpactSound() != null) {
					this.playSound(this.getImpactSound(), 1.0F, 1.0F / (this.getEntityWorld().rand.nextFloat() * 0.4F + 0.8F));
				}
 	        }
     	}
     }

@SuppressWarnings("ConstantConditions")
	@Override
	public void onInitialize() {
		MidnightConfig.init(MOD_ID, BWConfig.class);
		ServerPlayNetworking.registerGlobalReceiver(CauldronTeleportPacket.ID, new CauldronTeleportPacket.Receiver());
		ServerPlayNetworking.registerGlobalReceiver(TransformationAbilityPacket.ID, new TransformationAbilityPacket.Receiver());
		ServerPlayNetworking.registerGlobalReceiver(TogglePressingForwardPacket.ID, new TogglePressingForwardPacket.Receiver());
		CommandRegistrationCallback.EVENT.register(BWCommands::init);
		ServerLifecycleEvents.SERVER_STOPPED.register(server -> BewitchmentAPI.fakePlayer = null);
		ServerPlayerEvents.AFTER_RESPAWN.register((oldPlayer, newPlayer, alive) -> {
			BWComponents.TRANSFORMATION_COMPONENT.get(newPlayer).setAlternateForm(false);
			BWComponents.ADDITIONAL_WEREWOLF_DATA_COMPONENT.get(newPlayer).setForcedTransformation(false);
		});
		ServerPlayerEvents.COPY_FROM.register((oldPlayer, newPlayer, alive) -> {
			if (alive && BWComponents.TRANSFORMATION_COMPONENT.get(oldPlayer).isAlternateForm()) {
				TransformationAbilityPacket.useAbility(newPlayer, true);
			}
		});
		ServerEntityCombatEvents.AFTER_KILLED_OTHER_ENTITY.register((world, entity, killedEntity) -> {
			if (entity instanceof LivingEntity livingEntity) {
				if (livingEntity instanceof PlayerEntity player && killedEntity.getGroup() == EntityGroup.ARTHROPOD && BewitchmentAPI.getFamiliar(player) == BWEntityTypes.TOAD) {
					livingEntity.heal(livingEntity.getMaxHealth() * 1 / 4f);
				}
				if (livingEntity instanceof PlayerEntity player && BWComponents.CONTRACTS_COMPONENT.get(player).hasContract(BWContracts.DEATH)) {
					livingEntity.heal(livingEntity.getMaxHealth() / 4f);
				}
				if (livingEntity.getMainHandStack().getItem() instanceof AthameItem) {
					BlockPos glyphPos = BWUtil.getClosestBlockPos(killedEntity.getBlockPos(), 6, currentPos -> world.getBlockEntity(currentPos) instanceof GlyphBlockEntity);
					if (glyphPos != null) {
						((GlyphBlockEntity) world.getBlockEntity(glyphPos)).onUse(world, glyphPos, livingEntity, Hand.MAIN_HAND, killedEntity);
					}
					if (world.isNight()) {
						boolean chicken = killedEntity instanceof ChickenEntity, wolf = killedEntity instanceof WolfEntity;
						if (chicken || wolf) {
							RegistryEntry<Biome> biome = world.getBiome(killedEntity.getBlockPos());
							MobEntity boss = null;
							if (chicken) {
								if (biome.isIn(ConventionalBiomeTags.EXTREME_HILLS) || biome.isIn(ConventionalBiomeTags.ICY) || biome.isIn(ConventionalBiomeTags.MOUNTAIN)) {
									boss = BWEntityTypes.LILITH.create(world);
								}
							}
							if (wolf) {
								if (biome.isIn(ConventionalBiomeTags.TAIGA) || biome.isIn(ConventionalBiomeTags.FOREST)) {
									boss = BWEntityTypes.HERNE.create(world);
								}
							}
							if (boss != null) {
								BlockPos brazierPos = BWUtil.getClosestBlockPos(killedEntity.getBlockPos(), 8, currentPos -> world.getBlockEntity(currentPos) instanceof BrazierBlockEntity brazier && brazier.incenseRecipe.effect == BWStatusEffects.MORTAL_COIL);
								if (brazierPos != null) {
									world.breakBlock(brazierPos, false);
									world.createExplosion(null, brazierPos.getX() + 0.5, brazierPos.getY() + 0.5, brazierPos.getZ() + 0.5, 3, World.ExplosionSourceType.TNT);
									boss.initialize(world, world.getLocalDifficulty(brazierPos), SpawnReason.EVENT, null, null);
									boss.updatePositionAndAngles(brazierPos.getX() + 0.5, brazierPos.getY(), brazierPos.getZ() + 0.5, world.random.nextFloat() * 360, 0);
									world.spawnEntity(boss);
								}
							}
						}
					}
					for (AthameDropRecipe recipe : world.getRecipeManager().listAllOfType(BWRecipeTypes.ATHAME_DROP_RECIPE_TYPE)) {
						if (recipe.entity_type.equals(killedEntity.getType()) && world.random.nextFloat() < recipe.chance * (EnchantmentHelper.getLooting(livingEntity) + 1)) {
							ItemStack drop = recipe.getOutput(entity.getWorld().getRegistryManager()).copy();
							if (recipe.entity_type == EntityType.PLAYER) {
								drop.getOrCreateNbt().putString("SkullOwner", killedEntity.getName().getString());
							}
							ItemScatterer.spawn(world, killedEntity.getX() + 0.5, killedEntity.getY() + 0.5, killedEntity.getZ() + 0.5, drop);
						}
					}
					if (livingEntity instanceof PlayerEntity player && livingEntity.getOffHandStack().getItem() == Items.GLASS_BOTTLE && BWComponents.BLOOD_COMPONENT.get(killedEntity).getBlood() > 20 && killedEntity.getType().isIn(BWTags.HAS_BLOOD)) {
						world.playSound(null, livingEntity.getBlockPos(), SoundEvents.ITEM_BOTTLE_FILL, SoundCategory.PLAYERS, 1, 0.5f);
						BWUtil.addItemToInventoryAndConsume(player, Hand.OFF_HAND, new ItemStack(BWObjects.BOTTLE_OF_BLOOD));
					}
				}
			}
		});
		UseEntityCallback.EVENT.register((player, world, hand, entity, hitResult) -> {
			if (entity instanceof LivingEntity livingEntity && hand == Hand.MAIN_HAND && player.isSneaking() && entity.isAlive() && BewitchmentAPI.isVampire(player, true) && player.getStackInHand(hand).isEmpty()) {
				int toGive = entity.getType().isIn(BWTags.HAS_BLOOD) ? 5 : entity instanceof AnimalEntity ? 1 : 0;
				toGive = BloodSuckEvents.BLOOD_AMOUNT.invoker().onBloodSuck(player, livingEntity, toGive);
				if (toGive > 0) {
					BloodComponent playerBloodComponent = BWComponents.BLOOD_COMPONENT.get(player);
					BloodComponent entityBloodComponent = BWComponents.BLOOD_COMPONENT.get(livingEntity);
					if (playerBloodComponent.fillBlood(toGive, true) && entityBloodComponent.drainBlood(10, true)) {
						if (!world.isClient && livingEntity.hurtTime == 0) {
							BloodSuckEvents.ON_BLOOD_SUCK.invoker().onBloodSuck(player, livingEntity, toGive);
							world.playSound(null, player.getBlockPos(), SoundEvents.ITEM_HONEY_BOTTLE_DRINK, player.getSoundCategory(), 1, 0.5f);
							if (!livingEntity.isSleeping() || entityBloodComponent.getBlood() < BloodComponent.MAX_BLOOD / 2) {
								entity.damage(BWDamageSources.create(entity.getWorld(), BWDamageSources.VAMPIRE), 2);
							}
							playerBloodComponent.fillBlood(toGive, false);
							entityBloodComponent.drainBlood(10, false);
						}
						return ActionResult.success(world.isClient);
					}
				}
			}
			return ActionResult.PASS;
		});
		EntitySleepEvents.ALLOW_SLEEP_TIME.register((player, sleepingPos, vanillaResult) -> player.getWorld().getBlockState(sleepingPos).getBlock() instanceof CoffinBlock && player.getWorld().isDay() ? ActionResult.success(player.getWorld().isClient) : ActionResult.PASS);
		EntitySleepEvents.ALLOW_SLEEPING.register((player, sleepingPos) -> {
			if (BWComponents.TRANSFORMATION_COMPONENT.get(player).isAlternateForm()) {
				player.sendMessage(Text.translatable("block.minecraft.bed.transformation"), true);
				return PlayerEntity.SleepFailureReason.OTHER_PROBLEM;
			}
			if (player.getWorld().getBlockState(sleepingPos).getBlock() instanceof CoffinBlock) {
				if (player.getWorld().isNight()) {
					player.sendMessage(Text.translatable("block.minecraft.bed.coffin"), true);
					return PlayerEntity.SleepFailureReason.OTHER_PROBLEM;
				}
				return null;
			}
			return null;
		});
		EntitySleepEvents.STOP_SLEEPING.register((entity, sleepingPos) -> {
			if (!entity.getWorld().isClient) {
				BWWorldState worldState = BWWorldState.get(entity.getWorld());
				for (BlockPos foundPos : BWUtil.getBlockPoses(entity.getBlockPos(), 12)) {
					if (entity.getWorld().getWorldBorder().contains(foundPos) && entity.getWorld().getBlockEntity(foundPos) instanceof BrazierBlockEntity brazier && brazier.incenseRecipe != null) {
						IncenseRecipe recipe = brazier.incenseRecipe;
						int durationMultiplier = 1;
						for (BlockPos sigilPos : BWUtil.getBlockPoses(foundPos, 16)) {
							if (entity.getWorld().getWorldBorder().contains(foundPos) && worldState.potentialSigils.contains(sigilPos.asLong()) && entity.getWorld().getBlockEntity(sigilPos) instanceof SigilBlockEntity sigil && sigil.getSigil() == BWSigils.EXTENDING) {
								if (sigil.test(entity)) {
									sigil.setUses(sigil.getUses() - 1);
									sigil.markDirty();
									durationMultiplier = 2;
									break;
								}
							}
						}
						entity.addStatusEffect(new StatusEffectInstance(recipe.effect, 24000 * durationMultiplier, recipe.amplifier, true, false));
					}
				}
			}
		});
		BWScaleTypes.init();
