@Override
	public void tick() {
		super.tick();
		if (searchForEntity) {
			searchForEntity = false;
			List<Entity> search = level.getEntities((Entity) null, new AABB(getBlockPos()),
				e -> entityUUID.equals(e.getUUID()));
			if (search.isEmpty())
				clear();
			else
				processingEntity = search.get(0);
		}

		if (!isOccupied())
			return;
		if (crushingspeed == 0)
			return;

		if (level.isClientSide)
			CatnipServices.PLATFORM.executeOnClientOnly(() -> () -> this.tickAudio());

		float speed = crushingspeed * 4;

		Vec3 centerPos = VecHelper.getCenterOf(worldPosition);
		Direction facing = getBlockState().getValue(CrushingWheelControllerBlock.FACING);
		int offset = facing.getAxisDirection()
			.getStep();
		Vec3 outSpeed = new Vec3((facing.getAxis() == Axis.X ? 0.25D : 0.0D) * offset,
			offset == 1 ? (facing.getAxis() == Axis.Y ? 0.5D : 0.0D) : 0.0D // Increased upwards speed so upwards
			// crushing wheels shoot out the item
			// properly.
			, (facing.getAxis() == Axis.Z ? 0.25D : 0.0D) * offset); // No downwards speed, so downwards crushing wheels
		// drop the items as before.
		Vec3 outPos = centerPos.add((facing.getAxis() == Axis.X ? .55f * offset : 0f),
			(facing.getAxis() == Axis.Y ? .55f * offset : 0f), (facing.getAxis() == Axis.Z ? .55f * offset : 0f));

		if (!hasEntity()) {

			float processingSpeed =
				Mth.clamp((speed) / (!inventory.appliedRecipe ? (float) Math.log(inventory.getStackInSlot(0)
					.getCount()) / (float) Math.log(2) : 1), .25f, 20);
			inventory.remainingTime -= processingSpeed;
			spawnParticles(inventory.getStackInSlot(0));

			if (level.isClientSide)
				return;

			if (inventory.remainingTime < 20 && !inventory.appliedRecipe) {
				applyRecipe();
				inventory.appliedRecipe = true;
				level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 2 | 16);
				return;
			}

			if (inventory.remainingTime > 0) {
				return;
			}
			inventory.remainingTime = 0;

			// Output Items
			if (facing != Direction.UP) {
				BlockPos nextPos = worldPosition.below()
					.relative(facing, facing.getAxis() == Axis.Y ? 0 : 1);

				DirectBeltInputBehaviour behaviour =
					BlockEntityBehaviour.get(level, nextPos, DirectBeltInputBehaviour.TYPE);
				if (behaviour != null) {
					boolean changed = false;
					if (!behaviour.canInsertFromSide(facing))
						return;
					for (int slot = 0; slot < inventory.getSlots(); slot++) {
						ItemStack stack = inventory.getStackInSlot(slot);
						if (stack.isEmpty())
							continue;
						ItemStack remainder = behaviour.handleInsertion(stack, facing, false);
						if (ItemStack.matches(remainder, stack))
							continue;
						inventory.setStackInSlot(slot, remainder);
						changed = true;
					}
					if (changed) {
						setChanged();
						sendData();
					}
					return;
				}
			}

			// Eject Items
			for (int slot = 0; slot < inventory.getSlots(); slot++) {
				ItemStack stack = inventory.getStackInSlot(slot);
				if (stack.isEmpty())
					continue;
				ItemEntity entityIn = new ItemEntity(level, outPos.x, outPos.y, outPos.z, stack);
				entityIn.setDeltaMovement(outSpeed);
				entityIn.getPersistentData()
					.put("BypassCrushingWheel", NbtUtils.writeBlockPos(worldPosition));
				level.addFreshEntity(entityIn);
			}
			inventory.clear();
			level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 2 | 16);

			return;
		}

		if (!processingEntity.isAlive() || !processingEntity.getBoundingBox()
			.intersects(new AABB(worldPosition).inflate(.5f))) {
			clear();
			return;
		}

		double xMotion = ((worldPosition.getX() + .5f) - processingEntity.getX()) / 2f;
		double zMotion = ((worldPosition.getZ() + .5f) - processingEntity.getZ()) / 2f;
		if (processingEntity.isShiftKeyDown())
			xMotion = zMotion = 0;
		double movement = Math.max(-speed / 4f, -.5f) * -offset;
		processingEntity.setDeltaMovement(
			new Vec3(facing.getAxis() == Axis.X ? movement : xMotion, facing.getAxis() == Axis.Y ? movement : 0f // Do
				// not
				// move
				// entities
				// upwards
				// or
				// downwards
				// for
				// horizontal
				// crushers,
				, facing.getAxis() == Axis.Z ? movement : zMotion)); // Or they'll only get their feet crushed.

		if (level.isClientSide)
			return;

		if (!(processingEntity instanceof ItemEntity itemEntity)) {
			Vec3 entityOutPos = outPos.add(facing.getAxis() == Axis.X ? .5f * offset : 0f,
				facing.getAxis() == Axis.Y ? .5f * offset : 0f, facing.getAxis() == Axis.Z ? .5f * offset : 0f);
			int crusherDamage = AllConfigs.server().kinetics.crushingDamage.get();

			if (processingEntity instanceof LivingEntity livingEntity) {
				if (livingEntity.getHealth() - crusherDamage <= 0 // Takes LivingEntity instances
					// as exception, so it can
					// move them before it would
					// kill them.
					&& livingEntity.hurtTime <= 0) { // This way it can actually output the items
					// to the right spot.
					processingEntity.setPos(entityOutPos.x, entityOutPos.y, entityOutPos.z);
				}
			}
			processingEntity.hurt(CreateDamageSources.crush(level), crusherDamage);
			if (!processingEntity.isAlive()) {
				processingEntity.setPos(entityOutPos.x, entityOutPos.y, entityOutPos.z);
			}
			return;
		}

		itemEntity.setPickUpDelay(20);
		if (facing.getAxis() == Axis.Y) {
			if (processingEntity.getY() * -offset < (centerPos.y - .25f) * -offset) {
				intakeItem(itemEntity);
			}
		} else if (facing.getAxis() == Axis.Z) {
			if (processingEntity.getZ() * -offset < (centerPos.z - .25f) * -offset) {
				intakeItem(itemEntity);
			}
		} else {
			if (processingEntity.getX() * -offset < (centerPos.x - .25f) * -offset) {
				intakeItem(itemEntity);
			}
		}
	}

@SubscribeEvent
    public static void LivingEffects(LivingEvent.LivingTickEvent event){
        LivingEntity livingEntity = event.getEntity();
        if (livingEntity != null){
            if (livingEntity.level instanceof ServerLevel serverLevel) {
                if (livingEntity.hasEffect(GoetyEffects.ILLAGUE.get())) {
                    EffectsUtil.Illague(serverLevel, livingEntity);
                }
                if (livingEntity.hasEffect(GoetyEffects.SOUL_BURN.get())) {
                    if (livingEntity.tickCount % 2 == 0) {
                        serverLevel.sendParticles(ModParticleTypes.BIG_SOUL_FIRE.get(), livingEntity.getRandomX(1.0D), livingEntity.getY(livingEntity.getRandom().nextDouble() * 0.5F), livingEntity.getRandomZ(1.0D), 1, 0, 0, 0, 0);
                    }
                }
                if (livingEntity.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
                    if (livingEntity.tickCount % 10 == 0) {
                        ColorUtil colorUtil = VOID_TOUCHED;
                        serverLevel.sendParticles(new FollowFireParticleOption(livingEntity.getId()), livingEntity.getX(), livingEntity.getY() + (livingEntity.getBbHeight() / 2.0F), livingEntity.getZ(), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);
                    }
                }
                if (VampirismLoaded.VAMPIRISM.isLoaded()) {
                    if (VampirismIntegration.hasSunscreen(livingEntity)) {
                        MiscCapHelper.setSunscreen(livingEntity, 20);
                    }
                }
            }
            AttributeInstance armor = livingEntity.getAttribute(Attributes.ARMOR);
            if (armor != null){
                if (livingEntity.hasEffect(GoetyEffects.SOUL_ARMOR.get())){
                    if (ItemHelper.noArmor(livingEntity)){
                        if (!armor.hasModifier(SOUL_ARMOR_MOD)){
                            armor.addPermanentModifier(SOUL_ARMOR_MOD);
                        }
                    } else {
                        if (armor.hasModifier(SOUL_ARMOR_MOD)){
                            armor.removeModifier(SOUL_ARMOR_MOD);
                        }
                    }
                } else {
                    if (armor.hasModifier(SOUL_ARMOR_MOD)){
                        armor.removeModifier(SOUL_ARMOR_MOD);
                    }
                }
            }
            if (livingEntity.getTags().contains(ConstantPaths.gassed())){
                if (livingEntity.tickCount % 20 == 0){
                    livingEntity.getTags().remove(ConstantPaths.gassed());
                }
            }
            if (livingEntity.hasEffect(GoetyEffects.BURN_HEX.get())){
                if (livingEntity.hasEffect(MobEffects.FIRE_RESISTANCE)){
                    livingEntity.removeEffectNoUpdate(MobEffects.FIRE_RESISTANCE);
                }
            }
            if (livingEntity.hasEffect(GoetyEffects.CLIMBING.get())){
                MobUtil.ClimbAnyWall(livingEntity);
            }
            if (livingEntity instanceof Bee bee){
                if (!bee.level.isClientSide) {
                    if (bee.getTags().contains(ConstantPaths.conjuredBee())){
                        if ((bee.getTarget() == null && bee.getPersistentAngerTarget() == null) || bee.hasStung()){
                            if (bee.tickCount % MathHelper.secondsToTicks(10) == 0){
                                bee.spawnAnim();
                                bee.discard();
                            }
                        }
                    }
                }
            }
            if (livingEntity instanceof Bat bat){
                if (!bat.level.isClientSide){
                    if (bat.getTags().contains(ConstantPaths.conjuredBat())){
                        if (bat.tickCount % MathHelper.secondsToTicks(20) == 0){
                            bat.spawnAnim();
                            bat.discard();
                        }
                    }
                }
            }
            if (livingEntity.hasEffect(GoetyEffects.FREEZING.get())){
                if (!livingEntity.level.isClientSide){
                    MobEffectInstance instance = livingEntity.getEffect(GoetyEffects.FREEZING.get());
                    if (instance != null) {
                        livingEntity.setIsInPowderSnow(true);
                        if (livingEntity.canFreeze()) {
                            int h = instance.getAmplifier() + 1;
                            MiscCapHelper.setFreezing(livingEntity, h);
                            if (livingEntity.level instanceof ServerLevel serverLevel) {
                                float chance = 0.005F * (h * h);
                                if (serverLevel.getRandom().nextFloat() <= chance) {
                                    ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.SNOWFLAKE, livingEntity);
                                }
                            }
                            int i = livingEntity.getTicksFrozen();
                            int j = h * 4;
                            livingEntity.setTicksFrozen(Math.min(livingEntity.getTicksRequiredToFreeze() + 5, i + j));
                        }
                    }
                }
            } else {
                if (!livingEntity.level.isClientSide){
                    if (MiscCapHelper.isFreezing(livingEntity)){
                        MiscCapHelper.setFreezing(livingEntity, 0);
                    }
                }
            }
            if (livingEntity instanceof Player && livingEntity.hasEffect(GoetyEffects.SENSE_LOSS.get())){
                MobEffectInstance mobEffectInstance = livingEntity.getEffect(GoetyEffects.SENSE_LOSS.get());
                if (mobEffectInstance != null) {
                    if (livingEntity.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, mobEffectInstance.getDuration(), mobEffectInstance.getAmplifier(), mobEffectInstance.isAmbient(), mobEffectInstance.isVisible()))){
                        livingEntity.removeEffect(GoetyEffects.SENSE_LOSS.get());
                    }
                }
            }
            if (livingEntity.hasEffect(GoetyEffects.EXPLOSIVE.get())) {
                MobEffectInstance mobEffectInstance = livingEntity.getEffect(GoetyEffects.EXPLOSIVE.get());
                if (mobEffectInstance != null){
                    int a = mobEffectInstance.getAmplifier() + 1;
                    if (MobUtil.isPushed(livingEntity)) {
                        int max = Math.max(1, 100 - (a * 10));
                        if (livingEntity.getRandom().nextInt(max) == 0) {
                            if (!livingEntity.level.isClientSide) {
                                livingEntity.level.explode(livingEntity, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), 3.0F + (a / 2.0F), Level.ExplosionInteraction.BLOCK);
                                livingEntity.removeEffect(GoetyEffects.EXPLOSIVE.get());
                            }
                        }
                    }
                }
            }
            if (livingEntity.hasEffect(GoetyEffects.SNOW_SKIN.get())){
                MobEffectInstance mobEffectInstance = livingEntity.getEffect(GoetyEffects.SNOW_SKIN.get());
                if(mobEffectInstance != null){
                    if (!livingEntity.level.isClientSide){
                        int i = Mth.floor(livingEntity.getX());
                        int j = Mth.floor(livingEntity.getY());
                        int k = Mth.floor(livingEntity.getZ());
                        BlockPos blockpos = new BlockPos(i, j, k);
                        Holder<Biome> biome = livingEntity.level.getBiome(blockpos);
                        if (biome.is(BiomeTags.SNOW_GOLEM_MELTS)) {
                            livingEntity.hurt(livingEntity.damageSources().onFire(), 1.0F);
                        }

                        livingEntity.setIsInPowderSnow(false);
                        livingEntity.setTicksFrozen(0);

                        BlockState blockstate = Blocks.SNOW.defaultBlockState();

                        for(int l = 0; l < 4; ++l) {
                            i = Mth.floor(livingEntity.getX() + (double)((float)(l % 2 * 2 - 1) * 0.25F));
                            j = Mth.floor(livingEntity.getY());
                            k = Mth.floor(livingEntity.getZ() + (double)((float)(l / 2 % 2 * 2 - 1) * 0.25F));
                            BlockPos blockpos1 = new BlockPos(i, j, k);
                            if (livingEntity.level.isEmptyBlock(blockpos1) && blockstate.canSurvive(livingEntity.level, blockpos1)) {
                                livingEntity.level.setBlockAndUpdate(blockpos1, blockstate);
                                livingEntity.level.gameEvent(GameEvent.BLOCK_PLACE, blockpos1, GameEvent.Context.of(livingEntity, blockstate));
                            }
                        }
                    }
                }
            }
            /*if (livingEntity instanceof Mob mob) {
                if (mob.getTarget() != null) {
                    if (mob.getTarget().hasEffect(GoetyEffects.ENCHANTED.get())) {
                        if (MiscCapHelper.getEnchanter(mob.getTarget()) instanceof LivingEntity enchanter && TargetingConditions.forCombat().test(mob, enchanter)) {
                            mob.setTarget(enchanter);
                        }
                    }
                }
            }*/
        }
    }

@SubscribeEvent
    public static void DamageEvents(LivingDamageEvent event){
        LivingEntity target = event.getEntity();
        Entity attacker = event.getSource().getEntity();
        float finalDamage = event.getAmount();

        if (!target.level.isClientSide) {
            if (target.hasEffect(GoetyEffects.SAPPED.get())) {
                MobEffectInstance effectInstance = target.getEffect(GoetyEffects.SAPPED.get());
                if (effectInstance != null) {
                    int i = effectInstance.getAmplifier() + 1;
                    finalDamage += finalDamage * (0.2F * i);
                }
            }

            if (target.hasEffect(GoetyEffects.VOID_TOUCHED.get())) {
                if (!event.getSource().is(ModDamageSource.VOIDED)) {
                    MobEffectInstance effectInstance = target.getEffect(GoetyEffects.VOID_TOUCHED.get());
                    if (effectInstance != null) {
                        int i = effectInstance.getAmplifier() + 2;
                        finalDamage *= i;
                        target.removeEffect(GoetyEffects.VOID_TOUCHED.get());
                    }
                }
            }

            if (target.hasEffect(GoetyEffects.SHIELDING.get()) || target.hasEffect(GoetyEffects.SHIELDED.get())) {
                if (!event.getSource().is(DamageTypeTags.BYPASSES_EFFECTS) && !event.getSource().is(DamageTypeTags.BYPASSES_RESISTANCE)) {
                    MobEffectInstance effectInstance = target.getEffect(GoetyEffects.SHIELDING.get());
                    if (effectInstance == null && target.hasEffect(GoetyEffects.SHIELDED.get())) {
                        effectInstance = target.getEffect(GoetyEffects.SHIELDED.get());
                    }
                    if (effectInstance != null) {
                        int i = effectInstance.getAmplifier() + 1;
                        finalDamage -= finalDamage * (0.05F * i);
                    }
                }
            }

            if (attacker instanceof LivingEntity attackerL) {
                if (attackerL.hasEffect(GoetyEffects.SHADOW_WALK.get())) {
                    float multiply = 1.25F + (EffectsUtil.getAmplifier(attackerL, GoetyEffects.SHADOW_WALK.get()) / 4.0F);
                    finalDamage *= multiply;
                    attackerL.removeEffect(GoetyEffects.SHADOW_WALK.get());
                }
                if (target.hasEffect(GoetyEffects.CHILL_HIDE.get()) && ModDamageSource.physicalAttacks(event.getSource())) {
                    MobEffectInstance effectInstance = target.getEffect(GoetyEffects.CHILL_HIDE.get());
                    if (effectInstance != null) {
                        int i = effectInstance.getAmplifier() * 2;
                        attackerL.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + i), 1));
                    }
                }
                if (attackerL.hasEffect(GoetyEffects.RADIANCE.get())) {
                    MobEffectInstance effectInstance = attackerL.getEffect(GoetyEffects.RADIANCE.get());
                    if (effectInstance != null) {
                        int amp = effectInstance.getAmplifier() + 1;
                        float heal = 6.0F * ((amp / 2.0F) + 1);
                        if (attackerL.level instanceof ServerLevel serverLevel) {
                            float chance = event.getSource().is(DamageTypeTags.IS_PROJECTILE) ? 0.5F : 0.2F;
                            if (attackerL.level.getRandom().nextFloat() <= chance) {
                                attackerL.level.playSound(null, target, ModSounds.RADIANCE_WAVE.get(), attacker.getSoundSource(), 0.9F, 1.0F);
                                serverLevel.sendParticles(new ShockwaveParticleOption(4, 1), target.getX(), target.getY() + 0.25F, target.getZ(), 0, 0, 0, 0, 0.5F);
                                for (LivingEntity living2 : attackerL.level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(4.0D), ally -> MobUtil.areAllies(attackerL, ally) || ally == attackerL)) {
                                    living2.heal(heal);
                                    for (int i = 0; i < serverLevel.getRandom().nextInt(10) + 10; ++i) {
                                        serverLevel.sendParticles(ModParticleTypes.HEAL_EFFECT_2.get(), living2.getRandomX(1.5D), living2.getRandomY(), living2.getRandomZ(1.5D), 0, 0.0F, 1.0F, 0.0F, 1.0F);
                                    }
                                    ColorUtil colorUtil = new ColorUtil(0xfffcc5);
                                    serverLevel.sendParticles(new RisingCircleParticleOption(0), living2.getX(), living2.getY(), living2.getZ(), 0, colorUtil.red(), colorUtil.green(), colorUtil.blue(), 1.0F);
                                    living2.level.playSound(null, living2, ModSounds.HEAL_SPELL.get(), living2.getSoundSource(), 1.0F, 1.0F);
                                }
                            }
                        }
                    }
                }
                if (attackerL.hasEffect(GoetyEffects.LEECHING.get())) {
                    MobEffectInstance effectInstance = attackerL.getEffect(GoetyEffects.LEECHING.get());
                    if (effectInstance != null) {
                        if (ModDamageSource.physicalAttacks(event.getSource())) {
                            int amp = effectInstance.getAmplifier();
                            float increase = 0.02F * amp;
                            float heal = target.getMaxHealth() * (0.05F + increase);
                            if (heal > 0.0F) {
                                attackerL.level.playSound(null, attackerL, ModSounds.LEECHING.get(), attackerL.getSoundSource(), 1.0F, 1.0F);
                                attackerL.heal(heal);
                            }
                        }
                    }
                }
                if (attackerL.hasEffect(GoetyEffects.SWIRLING.get())) {
                    MobEffectInstance effectInstance = attackerL.getEffect(GoetyEffects.SWIRLING.get());
                    if (effectInstance != null) {
                        if (ModDamageSource.physicalAttacks(event.getSource()) && !event.getSource().is(ModDamageSource.SWORD)) {
                            int amp = effectInstance.getAmplifier();
                            float damage = 5.0F * ((amp / 2.0F) + 1);
                            if (attackerL.level instanceof ServerLevel serverLevel) {
                                ServerParticleUtil.windShockwaveParticle(serverLevel, ColorUtil.WHITE, 4.0F, 0, -1, attackerL.position().add(0.0D, 1.0D, 0.0D));
                                for (LivingEntity livingEntity : attackerL.level.getEntitiesOfClass(LivingEntity.class, attackerL.getBoundingBox().inflate(4.0D, 1.0D, 4.0D))) {
                                    if (attackerL != livingEntity && livingEntity != target && !MobUtil.areAllies(attackerL, livingEntity)) {
                                        livingEntity.hurt(ModDamageSource.sword(attackerL, attackerL), damage);
                                    }
                                }
                            }
                        }
                    }
                }
            }

            if (event.getAmount() > 0.0F) {
                if (target.hasEffect(GoetyEffects.ALTRUISTIC.get())) {
                    MobEffectInstance effectInstance = target.getEffect(GoetyEffects.ALTRUISTIC.get());
                    if (effectInstance != null) {
                        int amp = effectInstance.getAmplifier() + 1;
                        float heal = Math.min(0.25F * amp, 1.0F);
                        for (LivingEntity living : target.level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(60.0D), livingEntity -> MobUtil.areAllies(target, livingEntity) && livingEntity != target)) {
                            living.heal(event.getAmount() * heal);
                        }
                    }
                }
                if (target.hasEffect(GoetyEffects.MANDATE.get())) {
                    MobEffectInstance effectInstance = target.getEffect(GoetyEffects.MANDATE.get());
                    if (effectInstance != null) {
                        int amp = effectInstance.getAmplifier() + 1;
                        double radius = 8.0D * amp;
                        int size = 4 * amp;
                        List<LivingEntity> allies = target.level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(radius), livingEntity -> MobUtil.areAllies(target, livingEntity) && livingEntity != target && !livingEntity.hasEffect(GoetyEffects.MANDATE.get()));
                        if (target instanceof Mob mob) {
                            allies.removeIf(livingEntity -> MobUtil.getOwner(livingEntity) != mob);
                        }
                        if (!allies.isEmpty()) {
                            allies.sort(Comparator.comparingDouble(target::distanceToSqr));
                            if (allies.size() > size) {
                                allies.subList(size, allies.size()).clear();
                            }
                            finalDamage /= (allies.size() + 1);
                            float distribute = finalDamage;
                            for (LivingEntity living : allies) {
                                if (living != target) {
                                    living.hurt(event.getSource(), distribute);
                                }
                            }
                        }
                    }
                }
                Entity aggressor = null;
                LivingEntity enchanted = null;
                if (target.hasEffect(GoetyEffects.ENCHANTED.get())) {
                    finalDamage *= 0.5F;
                    aggressor = attacker;
                    enchanted = target;
                } else if (attacker instanceof LivingEntity livingEntity && livingEntity.hasEffect(GoetyEffects.ENCHANTED.get())) {
                    aggressor = target;
                    enchanted = livingEntity;
                }
                if (aggressor instanceof Mob mob && mob.getTarget() == enchanted) {
                    if (MiscCapHelper.getEnchanter(enchanted) instanceof LivingEntity livingEntity) {
                        float chance = 0.05F;
                        if (mob.getHealth() < mob.getMaxHealth() * 0.5F) {
                            chance += 0.2F;
                        }
                        if (mob.getHealth() < mob.getMaxHealth() * 0.25F) {
                            chance += 0.2F;
                        }
                        if (mob.getRandom().nextFloat() <= chance) {
                            mob.setTarget(livingEntity);
                        }
                    }
                }
            }
            if (finalDamage != event.getAmount()) {
                event.setAmount(finalDamage);
            }
        }
    }

public void tick() {
        super.tick();
        prevSitProgress = sitProgress;
        prevStandProgress = standProgress;

        if (isSitting()) {
            if (this.sitProgress < 5F)
                this.sitProgress++;
        } else {
            if (this.sitProgress > 0F)
                this.sitProgress--;
        }

        if (isStanding()) {
            if (this.standProgress < 5F)
                this.standProgress += 0.5F;
        } else {
            if (this.standProgress > 0F)
                this.standProgress -= 0.5F;
        }

        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }
        if (isSitting() && isStanding()) {
            this.setStanding(false);
        }
        if (hasChestVarChanged && elephantInventory != null && !this.isChested()) {
            for (int i = 3; i < 18; i++) {
                if (!elephantInventory.getItem(i).isEmpty()) {
                    if (!this.level().isClientSide) {
                        this.spawnAtLocation(elephantInventory.getItem(i), 1);
                    }
                    elephantInventory.removeItemNoUpdate(i);
                }
            }
            hasChestVarChanged = false;
        }
        if (!hasTuskedAttributes && isTusked() && !isBaby()) {
            refreshDimensions();
        }
        if (hasTuskedAttributes && !isTusked() && !isBaby()) {
            refreshDimensions();
        }
        if (charging) {
            chargingTicks++;
        }
        if (!this.getMainHandItem().isEmpty() && this.canTargetItem(this.getMainHandItem())) {
            if (this.getAnimation() == NO_ANIMATION) {
                this.setAnimation(ANIMATION_EAT);
            }
            if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() == 17) {
                this.eatItemEffect(this.getMainHandItem());
                if (this.getMainHandItem().is(AMTagRegistry.ELEPHANT_TAMEABLES) && !this.isTame() && (!isTusked() || isBaby()) && blossomThrowerUUID != null) {
                    if (random.nextInt(3) == 0) {
                        this.setTame(true);
                        this.setOwnerUUID(blossomThrowerUUID);
                        Player player = this.level().getPlayerByUUID(blossomThrowerUUID);
                        if (player != null) {
                            this.tame(player);
                        }
                        for (Entity passenger : this.getPassengers()) {
                            passenger.removeVehicle();
                        }
                        this.level().broadcastEntityEvent(this, (byte) 7);
                    } else {
                        this.level().broadcastEntityEvent(this, (byte) 6);
                    }
                }
                this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                this.heal(10);
            }
        }
        if (chargeCooldown > 0) {
            chargeCooldown--;
        }
        if (charging) {
            chargingTicks++;
        } else {
            chargingTicks = 0;
        }
        if (this.getAnimation() == ANIMATION_CHARGE_PREPARE) {
            this.yBodyRot = getYRot();
            if (this.getAnimationTick() == 20) {
                this.charging = true;
            }
        }
        if (this.getControllingPassenger() != null && charging && chargingTicks > 100) {
            this.charging = false;
            this.chargeCooldown = 200;
        }
        LivingEntity target = this.getTarget();
        double maxAttackMod = 0.0F;
        if (this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player) {
            Player rider = (Player) this.getControllingPassenger();
            if (rider.getLastHurtMob() != null && !this.isAlliedTo(rider.getLastHurtMob())) {
                UUID preyUUID = rider.getLastHurtMob().getUUID();
                if (!this.getUUID().equals(preyUUID)) {
                    target = rider.getLastHurtMob();
                    maxAttackMod = 4F;
                }
            }
        }
        if (!this.level().isClientSide && target != null) {
            if (this.distanceTo(target) > this.getBbWidth() * 0.5F + 0.5F && this.getControllingPassenger() == null && this.isTusked() && this.hasLineOfSight(target) && this.getAnimation() == NO_ANIMATION && !charging && chargeCooldown == 0) {
                this.setAnimation(ANIMATION_CHARGE_PREPARE);
            }
            if (this.getAnimation() == ANIMATION_CHARGE_PREPARE && this.getControllingPassenger() == null) {
                this.lookAt(target, 360, 30);
                this.yBodyRot = getYRot();
                if (this.getAnimationTick() == 20) {
                    this.charging = true;
                }
            }
            if (this.distanceTo(target) < 10D && charging) {
                this.setAnimation(ANIMATION_FLING);
            }
            if (this.distanceTo(target) < 2.1D && charging) {
                target.knockback(1F, target.getX() - this.getX(), target.getZ() - this.getZ());
                target.hasImpulse = true;
                target.setDeltaMovement(target.getDeltaMovement().add(0, 0.7F, 0));
                target.hurt(this.damageSources().mobAttack(this), 2.4F * (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                launch(target, true);
                this.charging = false;
                this.chargeCooldown = 400;
            }
            double dist = this.distanceTo(target);
            if (dist < 4.5D + maxAttackMod && this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() == 15) {
                target.knockback(1F, target.getX() - this.getX(), target.getZ() - this.getZ());
                target.setDeltaMovement(target.getDeltaMovement().add(0, 0.3F, 0));
                launch(target, false);
                target.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            }
            if (dist < 4.5D + maxAttackMod && this.getAnimation() == ANIMATION_STOMP && this.getAnimationTick() == 17) {
                target.knockback(0.3F, target.getX() - this.getX(), target.getZ() - this.getZ());
                target.hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
            }
        }
        if (!this.level().isClientSide && this.getTarget() == null && this.getControllingPassenger() == null) {
            charging = false;
        }
        if (charging && !hasChargedSpeed) {
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.65F);
            hasChargedSpeed = true;
        }
        if (!charging && hasChargedSpeed) {
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35F);
            hasChargedSpeed = false;
        }
        if (!this.level().isClientSide && this.getRandom().nextInt(400) == 0 && this.getAnimation() == NO_ANIMATION) {
            this.setAnimation(this.getRandom().nextBoolean() ? ANIMATION_TRUMPET_0 : ANIMATION_TRUMPET_1);
        }
        if (this.getAnimation() == ANIMATION_TRUMPET_0 && this.getAnimationTick() == 8 || this.getAnimation() == ANIMATION_TRUMPET_1 && this.getAnimationTick() == 4) {
            this.gameEvent(GameEvent.ENTITY_ROAR);
            this.playSound(AMSoundRegistry.ELEPHANT_TRUMPET.get(), this.getSoundVolume(), this.getVoicePitch());
        }
        if (this.isAlive() && charging) {
            for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                if (!(this.isTame() && isAlliedTo(entity)) && !(!this.isTame() && entity instanceof EntityElephant) && entity != this) {
                    entity.hurt(this.damageSources().mobAttack(this), 8.0F + random.nextFloat() * 8.0F);
                    launch(entity, true);
                }
            }
            this.setMaxUpStep(2F);
        }else{
            this.setMaxUpStep(1.1F);
        }
        if (!isTame() && isTrader()) {
            if (!this.level().isClientSide) {
                this.tryDespawn();
            }
        }
        if (this.getTarget() != null && !this.getTarget().isAlive()) {
            this.setTarget(null);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        prevSwimProgress = swimProgress;
        prevBiteProgress = biteProgress;
        prevHeadHeight = this.getHeadHeight();
        if (shouldSwim()) {
            if (swimProgress < 5F)
                swimProgress++;
        } else {
            if (swimProgress > 0F)
                swimProgress--;
        }

        if (this.isObsidian()) {
            if (!hasObsidianArmor) {
                hasObsidianArmor = true;
                this.getAttribute(Attributes.ARMOR).setBaseValue(30F);
            }
        } else {
            if (hasObsidianArmor) {
                hasObsidianArmor = false;
                this.getAttribute(Attributes.ARMOR).setBaseValue(10F);
            }
        }

        if (!this.level().isClientSide) {
            if (!this.isObsidian() && this.isInWaterOrBubble()) {
                if (conversionTime < 300) {
                    conversionTime++;
                } else {
                    this.setObsidian(true);
                }

            }
            if (shouldSwim()) {
                fallDistance = 0.0F;
            }
        }
        float neckBase = 0.8F;
        if (!this.isNoAi()) {
            Vec3[] avector3d = new Vec3[this.allParts.length];
            for (int j = 0; j < this.allParts.length; ++j) {
                this.allParts[j].collideWithNearbyEntities();
                avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
            }
            float yaw = this.yBodyRot * Mth.DEG_TO_RAD;
            float neckContraction = 2.0F * Math.abs(getHeadHeight() / 3) + 0.5F * Math.abs(getHeadYaw(0) / 50F);

            for (int l = 0; l < this.theEntireNeck.length; ++l) {
                float f = l / ((float) this.theEntireNeck.length);
                float f1 = -(2.2F + l - f * neckContraction);
                float f2 = Mth.sin(yaw + Maths.rad(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
                float f3 = Mth.cos(yaw + Maths.rad(f * getHeadYaw(0))) * (1 - Math.abs((this.getXRot()) / 90F));
                this.setPartPosition(this.theEntireNeck[l], f2 * f1, neckBase + Math.sin(f * Math.PI * 0.5F) * (getHeadHeight() * 1.1F), -f3 * f1);
            }
            this.setPartPosition(this.seat1, getXForPart(yaw, 145) * 0.75F, 2F, getZForPart(yaw, 145) * 0.75F);
            this.setPartPosition(this.seat2, getXForPart(yaw, -145) * 0.75F, 2F, getZForPart(yaw, -145) * 0.75F);
            this.setPartPosition(this.seat3, getXForPart(yaw, 35) * 0.95F, 2F, getZForPart(yaw, 35) * 0.95F);
            this.setPartPosition(this.seat4, getXForPart(yaw, -35) * 0.95F, 2F, getZForPart(yaw, -35) * 0.95F);

            if (this.level().isClientSide && this.isChilling()) {
                if (!this.isBaby()) {
                    this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, 158) * 1.75F, this.getY(1), this.getZ() + getZForPart(yaw, 158) * 1.75F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                    this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, -166) * 1.48F, this.getY(1), this.getZ() + getZForPart(yaw, -166) * 1.48F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                    this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, 14) * 1.78F, this.getY(0.9), this.getZ() + getZForPart(yaw, 14) * 1.78F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                    this.level().addParticle(ParticleTypes.SMOKE, this.getX() + getXForPart(yaw, -14) * 1.6F, this.getY(1.1), this.getZ() + getZForPart(yaw, -14) * 1.6F, 0.0D, this.random.nextDouble() / 5.0D, 0.0D);
                }
                this.level().addParticle(ParticleTypes.SMOKE, this.headPart.getRandomX(0.6D), this.headPart.getY(0.9), this.headPart.getRandomZ(0.6D), 0.0D, this.random.nextDouble() / 5.0D, 0.0D);

            }

            for (int l = 0; l < this.allParts.length; ++l) {
                this.allParts[l].xo = avector3d[l].x;
                this.allParts[l].yo = avector3d[l].y;
                this.allParts[l].zo = avector3d[l].z;
                this.allParts[l].xOld = avector3d[l].x;
                this.allParts[l].yOld = avector3d[l].y;
                this.allParts[l].zOld = avector3d[l].z;
            }
        }
        if ((this.isInLava() || this.isInWaterOrBubble()) && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!(this.isInLava() || this.isInWaterOrBubble()) && !this.isLandNavigator) {
            switchNavigator(true);
        }
        if (!this.level().isClientSide) {
            if (this.getChillTime() > 0) {
                this.setChillTime(this.getChillTime() - 1);
            } else if (this.shouldSwim()) {
                if (random.nextInt(this.isVehicle() ? 200 : 2000) == 0 && revengeCooldown == 0) {
                    this.setChillTime(100 + random.nextInt(500));
                }
            }
            if (revengeCooldown > 0) {
                revengeCooldown--;
            }
            if (headPeakCooldown > 0) {
                headPeakCooldown--;
            }
            if (revengeCooldown == 0 && this.getLastHurtByMob() != null) {
                this.setLastHurtByMob(null);
            }
        }
        if (!this.level().isClientSide) {
            if (this.getControllingPassenger() == null && (this.getChillTime() > 0 || this.hasHeadGear() || dismountCooldown > 0)) {
                floatLaviathan();
            }

            if (!this.isChilling() && headPeakCooldown == 0) {
                float low = getLowHeadHeight();
                this.setHeadHeight(this.getHeadHeight() + (0.5F + ((getLowHeadHeight() + getHighHeadHeight(low)) / 2F) - this.getHeadHeight()) * 0.2F);
            } else {
                if (getMaxFluidHeight() <= this.getBbHeight() * 0.5F && getMaxFluidHeight() >= this.getBbHeight() * 0.25F) {
                    float mot = (float) this.getDeltaMovement().lengthSqr();
                    this.setHeadHeight(Mth.clamp(this.getHeadHeight() + 0.1F - 0.2F * mot, 0, 2));
                    headPeakCooldown = 5;
                }
            }
        }
        if (this.isChilling()) {
            boolean keepChillin = false;
            boolean startBiting = false;
            for (EntityCrimsonMosquito entity : this.level().getEntitiesOfClass(EntityCrimsonMosquito.class, this.getBoundingBox().inflate(30.0D), HEALTHY_MOSQUITOES)) {
                entity.setLuringLaviathan(this.getId());
                keepChillin = true;
            }
            if (keepChillin) {
                this.setChillTime(Math.max(20, this.getChillTime()));
            }
            for (EntityCrimsonMosquito entity : this.level().getEntitiesOfClass(EntityCrimsonMosquito.class, this.headPart.getBoundingBox().inflate(1.0D), HEALTHY_MOSQUITOES)) {
                startBiting = true;
                if (this.biteProgress == 5.0F) {
                    entity.hurt(this.damageSources().mobAttack(this), 1000);
                    entity.setShrink(true);
                    this.setChillTime(0);
                }
            }
            if (startBiting) {
                if (this.entityData.get(ATTACK_TICK) <= 0 && this.biteProgress == 0) {
                    this.entityData.set(ATTACK_TICK, 7);
                }
            }
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
        }
        if (this.entityData.get(ATTACK_TICK) > 0 && this.biteProgress < 5.0F) {
            this.biteProgress++;
        }
        if (this.entityData.get(ATTACK_TICK) <= 0 && this.biteProgress > 0.0F) {
            this.biteProgress--;
        }
        if (dismountCooldown > 0) {
            dismountCooldown--;
        }
        if (this.hasBodyGear()) {
            List<Entity> list = this.level().getEntities(this, this.getBoundingBox().inflate(0.2F, -0.01F, 0.2F), EntitySelector.pushableBy(this));
            if (!list.isEmpty()) {
                boolean flag2 = !this.level().isClientSide;
                for (int j = 0; j < list.size(); ++j) {
                    Entity entity = list.get(j);
                    if (!entity.hasPassenger(this)) {
                        if (flag2 && !(entity instanceof Player) && !entity.isPassenger() && entity.getBbWidth() < this.getBbWidth() && !(entity instanceof EntityLaviathan) && !(entity instanceof Enemy) && entity instanceof Mob && this.canAddPassenger(entity) && !(entity instanceof WaterAnimal)) {
                            entity.startRiding(this);
                        } else {
                            this.push(entity);
                        }
                    }
                }
            }
        }
        if (this.isVehicle() && !this.level().isClientSide && tickCount % 40 == 0 && this.getPassengers().size() > 3) {
            for (Entity entity : this.getPassengers()) {
                if (entity instanceof ServerPlayer) {
                    AMAdvancementTriggerRegistry.LAVIATHAN_FOUR_PASSENGERS.trigger((ServerPlayer) entity);
                }
            }
        }
        lastX = this.getX();
        lastZ = this.getZ();
    }

public void handleEpicFightKeyMappings() {
        // Pause here if playerpatch is null
        if (this.playerpatch == null) {
            return;
        }

        InputManager.triggerOnPress(EpicFightInputAction.OPEN_SKILL_SCREEN, this::openSkillEditor);

        InputManager.triggerOnPress(EpicFightInputAction.OPEN_CONFIG_SCREEN, this::openConfig);

        // TODO: We need another way to detect when the key first pressed especailly for UI open key mappings
        InputManager.triggerOnPress(EpicFightInputAction.OPEN_EMOTE_WHEEL_SCREEN, this::mayOpenEmoteWheel);

        InputManager.triggerOnPress(EpicFightInputAction.SWITCH_VANILLA_MODEL_DEBUGGING, this::switchVanillaModelDebugging);

        // The "runKeyboardMouseEvent" is used as a workaround to this issue:
        // * https://github.com/Epic-Fight/epicfight/issues/1771
        // * https://github.com/Creators-of-Create/Create/issues/6901

        InputManager.triggerOnPress(
            EpicFightInputAction.ATTACK,
            () -> InputUtils.runKeyboardMouseEvent(EpicFightInputAction.ATTACK, this::maybeAttack)
        );

        InputManager.triggerOnPress(
            EpicFightInputAction.DODGE,
            () -> InputUtils.runKeyboardMouseEvent(EpicFightInputAction.DODGE, this::maybeDodge)
        );

        if (InputManager.isActionActive(EpicFightInputAction.GUARD)) this.maybeGuard();

        InputManager.triggerOnPress(
            EpicFightInputAction.WEAPON_INNATE_SKILL,
            () -> InputUtils.runKeyboardMouseEvent(EpicFightInputAction.WEAPON_INNATE_SKILL, this::handleSeparateWeaponInnateSkill)
        );

        InputManager.triggerOnPress(
            EpicFightInputAction.MOBILITY,
            () -> InputUtils.runKeyboardMouseEvent(EpicFightInputAction.MOBILITY, this::maybePerformMoverSkill)
        );

        InputManager.triggerOnPress(EpicFightInputAction.SWITCH_MODE, this::switchMode);

        InputManager.triggerOnPress(EpicFightInputAction.LOCK_ON, this::toggleLockOnState);

        InputManager.triggerOnPress(EpicFightInputAction.LOCK_ON_SHIFT_LEFT, this::searchNewTargetFromLeft);

        InputManager.triggerOnPress(EpicFightInputAction.LOCK_ON_SHIFT_RIGHT, this::searchNewTargetFromRight);

        if (shouldDisableSwapHandItems()) consumeSwapOffhandKeyClicks();

        // Pause here if player is not in battle mode
        if (!this.playerpatch.isEpicFightMode() || Minecraft.getInstance().isPaused()) {
            return;
        }

        if (this.player.tickCount - this.lastHotbarLockedTime > 20 && this.hotbarLocked) {
            this.unlockHotkeys();
        }

        if (this.weaponInnatePressToggle) {
            if (!InputManager.isActionActive(EpicFightInputAction.WEAPON_INNATE_SKILL)) {
                this.attackLightPressToggle = true;
                this.weaponInnatePressToggle = false;
                this.weaponInnatePressCounter = 0;
            } else {
                if (InputManager.isBoundToSamePhysicalInput(EpicFightInputAction.WEAPON_INNATE_SKILL, EpicFightInputAction.ATTACK)) {
                    if (this.weaponInnatePressCounter > ClientConfig.holdingThreshold) {
                        if (this.playerpatch.getSkill(SkillSlots.WEAPON_INNATE).sendCastRequest(this.playerpatch, this).shouldReserveKey()) {
                            if (!this.player.isSpectator()) {
                                this.reserveKey(SkillSlots.WEAPON_INNATE, EpicFightInputAction.WEAPON_INNATE_SKILL);
                            }
                        } else {
                            this.lockHotkeys();
                        }

                        this.weaponInnatePressToggle = false;
                        this.weaponInnatePressCounter = 0;
                    } else {
                        this.weaponInnatePressCounter++;
                    }
                }
            }
        }

        if (this.attackLightPressToggle) {
            SkillCastEvent skillCastEvent = this.playerpatch.getSkill(SkillSlots.COMBO_ATTACKS).sendCastRequest(this.playerpatch, this);

            if (skillCastEvent.isExecutable()) {
                this.player.resetAttackStrengthTicker();
                this.releaseAllServedKeys();
            } else {
                if (!this.player.isSpectator()) {
                    this.reserveKey(SkillSlots.COMBO_ATTACKS, EpicFightInputAction.ATTACK);
                }
            }

            this.lockHotkeys();

            this.attackLightPressToggle = false;
            this.weaponInnatePressToggle = false;
            this.weaponInnatePressCounter = 0;
        }

        if (this.sneakPressToggle) {
            if (!InputManager.isActionActive(MinecraftInputAction.SNEAK)) {
                SkillSlot skillSlot = (this.playerpatch.getEntityState().knockDown()) ? SkillSlots.KNOCKDOWN_WAKEUP : SkillSlots.DODGE;
                SkillContainer skill = this.playerpatch.getSkill(skillSlot);

                if (skill.sendCastRequest(this.playerpatch, this).shouldReserveKey()) {
                    this.reserveKey(skillSlot, MinecraftInputAction.SNEAK);
                }

                this.sneakPressToggle = false;
                this.sneakPressCounter = 0;
            } else {
                if (this.sneakPressCounter > ClientConfig.holdingThreshold) {
                    this.sneakPressToggle = false;
                    this.sneakPressCounter = 0;
                } else {
                    this.sneakPressCounter++;
                }
            }
        }

        if (this.currentHoldingKey != null) {
            SkillContainer container = this.playerpatch.getSkill(this.reservedOrHoldingSkillSlot);

            if (!container.isEmpty()) {
                if (container.getSkill() instanceof HoldableSkill) {
                    if (!this.isCurrentHoldingActionActive()) {
                        this.holdingFinished = true;
                    }

                    if (container.getSkill() instanceof ChargeableSkill chargingSkill) {
                        if (this.holdingFinished) {
                            if (this.playerpatch.getSkillChargingTicks() > chargingSkill.getMinChargingTicks()) {
                                container.sendCastRequest(this.playerpatch, this);
                                this.releaseAllServedKeys();
                            }
                        } else if (this.playerpatch.getSkillChargingTicks() >= chargingSkill.getAllowedMaxChargingTicks()) {
                            this.releaseAllServedKeys();
                        }
                    } else {
                        if (this.holdingFinished) {
                            // Note: Holdable skills are canceled in client first
                            this.playerpatch.resetHolding();
                            CompoundTag arguments = new CompoundTag();
                            container.getSkill().gatherArguments(container, this, arguments);
                            container.getSkill().cancelOnClient(container, arguments);
                            container.sendCancelRequest(this.playerpatch, this);
                            this.releaseAllServedKeys();
                        }
                    }
                } else {
                    this.releaseAllServedKeys();
                }
            }
        }

        if (this.reservedKey != null) {
            if (this.reserveCounter > 0) {
                SkillContainer skill = this.playerpatch.getSkill(this.reservedOrHoldingSkillSlot);
                this.reserveCounter--;

                if (skill.getSkill() != null) {
                    if (skill.sendCastRequest(this.playerpatch, this).isExecutable()) {
                        this.releaseAllServedKeys();
                        this.lockHotkeys();
                    }
                }
            } else {
                this.releaseAllServedKeys();
			}
		}

		if (isSwitchOrDropBlocked()) {
			disableHotbarSlotPresses();
			consumeDropKeyClicks();
		}

        maybeCorrectTPSPosition();
    }

public void tick() {
        super.tick();
        if (this.isHostile()) {
            if (MobsConfig.RedstoneMonstrosityHostileConvert.get()) {
                if (this.tickCount % 10 == 0) {
                    Mob mob = this.convertTo(ModEntityType.HOSTILE_REDSTONE_MONSTROSITY.get(), false);
                    if (mob != null) {
                        mob.setXRot(this.getXRot());
                        mob.setYRot(this.getYRot());
                        mob.setYBodyRot(this.getYRot());
                        mob.setYHeadRot(this.getYHeadRot());
                    }
                }
            }
        }
        if (this.isDeadOrDying()){
            this.setAnimationState(DEATH);
            this.setYRot(this.deathRotation);
            this.setYBodyRot(this.deathRotation);
        }
        if (this.hasPose(Pose.EMERGING)){
            ++this.activateTick;
            this.isStandingUp = 0;
            this.setAnimationState(ACTIVATE);
            if (this.activateTick == 1){
                this.playSound(ModSounds.REDSTONE_MONSTROSITY_AWAKEN.get(), 10.0F, 1.0F);
            }
            if (this.activateTick == 40){
                CameraShake.cameraShake(this.level, this.position(), 40.0F, 0.5F, 0, 20);
            }
            if (this.activateTick > MathHelper.secondsToTicks(3.25F)){
                this.setPose(Pose.STANDING);
            }
        }
        if (this.level.isClientSide) {
            this.idleAnimationState.animateWhen(this.isCurrentAnimation(IDLE) && !this.walkAnimation.isMoving(), this.tickCount);
            this.sitAnimationState.animateWhen(this.isCurrentAnimation(SIT) && !this.walkAnimation.isMoving(), this.tickCount);
        }
        if (!this.level.isClientSide){
            if (this.isAlive() && !this.isActivating()) {
                if (MobsConfig.RedstoneMonstrosityLeafBreak.get()) {
                    if (net.minecraftforge.event.ForgeEventFactory.getMobGriefingEvent(this.level, this)) {
                        boolean flag = false;
                        AABB aabb = this.getBoundingBox().inflate(0.2D);

                        for (BlockPos blockpos : BlockPos.betweenClosed(Mth.floor(aabb.minX), Mth.floor(aabb.minY), Mth.floor(aabb.minZ), Mth.floor(aabb.maxX), Mth.floor(aabb.maxY), Mth.floor(aabb.maxZ))) {
                            BlockState blockstate = this.level.getBlockState(blockpos);
                            Block block = blockstate.getBlock();
                            if (block instanceof LeavesBlock || blockstate.is(ModTags.Blocks.MONSTROSITY_BREAKS)) {
                                flag = this.level.destroyBlock(blockpos, true, this) || flag;
                            }
                        }
                    }
                }
                if (!this.isMeleeAttacking() && !this.isBelching() && !this.isSummoning()) {
                    this.level.broadcastEntityEvent(this, (byte) 7);
                    if (this.isStaying()) {
                        if (this.isSittingDown > 0){
                            --this.isSittingDown;
                            this.setAnimationState(TO_SIT);
                        } else {
                            this.setAnimationState(SIT);
                        }
                    } else {
                        if (this.isStandingUp > 0){
                            --this.isStandingUp;
                            this.setAnimationState(TO_STAND);
                        } else {
                            this.setAnimationState(IDLE);
                        }
                    }
                } else {
                    this.level.broadcastEntityEvent(this, (byte) 6);
                    if (this.isStaying()){
                        this.isSittingDown = MathHelper.secondsToTicks(1);
                    } else {
                        this.isSittingDown = 0;
                    }
                    this.isStandingUp = 0;
                }
                if (this.isMeleeAttacking()) {
                    ++this.attackTick;
                    if (this.attackTick > MathHelper.secondsToTicks(3.3F)){
                        this.setMeleeAttacking(false);
                    }
                }
                if (this.isSummoning()) {
                    this.makeBigGlow();
                    --this.summonTick;
                    if (this.level instanceof ServerLevel serverLevel) {
                        for (int i = 0; i < 5; ++i) {
                            double d0 = serverLevel.random.nextGaussian() * 0.02D;
                            double d1 = serverLevel.random.nextGaussian() * 0.02D;
                            double d2 = serverLevel.random.nextGaussian() * 0.02D;
                            serverLevel.sendParticles(ModParticleTypes.ELECTRIC.get(), this.getRandomX(0.5D), this.getEyeY() - serverLevel.random.nextInt(2), this.getRandomZ(0.5D), 0, d0, d1, d2, 0.5F);
                        }
                        if (this.summonTick < MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 1)
                            && this.summonTick >= MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 2)) {
                            if (!this.level.getBlockState(this.blockPosition().below()).isAir()) {
                                for (int j = 0; j < 4; ++j) {
                                    double d1 = this.getX() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() * 2.0D;
                                    double d2 = this.blockPosition().getY() + 0.5F;
                                    double d3 = this.getZ() + (this.random.nextDouble() - 0.5D) * (double) this.getBbWidth() * 2.0D;
                                    serverLevel.sendParticles(ModParticleTypes.BIG_FIRE_GROUND.get(), d1, d2, d3, 0, 0.0D, 0.0D, 0.0D, 0.5F);
                                }
                            }
                        }
                        if (this.summonTick == MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 1)){
                            ColorUtil colorUtil = new ColorUtil(0xff8200);
                            serverLevel.sendParticles(new SmashParticleOption(colorUtil, 3, 1.5F, 10), this.getXLeft(), BlockFinder.moveDownToGround(this), this.getZLeft(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                            serverLevel.sendParticles(new SmashParticleOption(colorUtil, 3, 1.5F, 10), this.getXRight(), BlockFinder.moveDownToGround(this), this.getZRight(), 1, 0.0D, 0.0D, 0.0D, 0.0D);
                            ServerParticleUtil.sendGodRay(serverLevel, this.getXLeft(), BlockFinder.moveDownToGround(this), this.getZLeft(), colorUtil);
                            ServerParticleUtil.sendGodRay(serverLevel, this.getXRight(), BlockFinder.moveDownToGround(this), this.getZRight(), colorUtil);
                            this.playSound(ModSounds.REDSTONE_MONSTROSITY_BELCH.get(), this.getSoundVolume(), 0.7F);
                            AABB aabb = new AABB(this.blockPosition());
                            for (LivingEntity target : this.level.getEntitiesOfClass(LivingEntity.class, aabb.inflate(MELEE_RANGE / 2.0F))) {
                                if (target != this && !MobUtil.areAllies(this, target)) {
                                    if (target.hurt(this.getServantAttack(), 2.0F)){
                                        float f1 = 2.0F;
                                        if (target.getBoundingBox().getSize() > this.getBoundingBox().getSize()){
                                            target.knockback((double)(f1 * 0.5F), (double) Mth.sin(this.getYRot() * ((float)Math.PI / 180F)), (double)(-Mth.cos(this.getYRot() * ((float)Math.PI / 180F))));
                                        } else {
                                            MobUtil.forcefulKnockBack(target, (double)(f1 * 0.5F), (double)Mth.sin(this.getYRot() * ((float)Math.PI / 180F)), (double)(-Mth.cos(this.getYRot() * ((float)Math.PI / 180F))), 0.5D);
                                        }
                                    }
                                }
                            }
                        }
                        if (this.summonTick == MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 1.2F)) {
                            CameraShake.cameraShake(this.level, this.position(), 25.0F, 0.3F, 0, 20);
                        }
                        if (this.summonTick <= (MathHelper.secondsToTicks(SUMMON_SECONDS_TIME - 2)) && this.summonCount != 0) {
                            for (int i = 0; i < 10; ++i){
                                BlockPos blockPos = this.blockPosition();
                                blockPos = blockPos.offset(-16 + this.level.random.nextInt(32), 0, -16 + this.level.random.nextInt(32));
                                Vec3 vec3 = Vec3.atBottomCenterOf(blockPos);
                                Summoned summoned = new RedstoneCube(ModEntityType.REDSTONE_CUBE.get(), this.level);
                                if (this.level.noCollision(summoned, summoned.getBoundingBox().move(vec3))){
                                    SummonCircleVariant summonCircle = new SummonCircleVariant(this.level, vec3, summoned, this);
                                    summonCircle.playSound(ModSounds.DIRT_DEBRIS.get(), 3.0F, 0.4F);
                                    this.level.addFreshEntity(summonCircle);
                                }
                            }
                            this.summonCount = 0;
                        }
                        if (this.summonTick <= 1){
                            if (this.summonCool <= 0) {
                                this.summonCool = MathHelper.secondsToTicks(13);
                            }
                            if (this.postAttackCool <= 0) {
                                this.postAttackCool = (int) MathHelper.secondsToTicks(0.5F);
                            }
                        }
                    }
                }
                if (this.summonCool > 0) {
                    --this.summonCool;
                }
                if (this.postAttackCool > 0) {
                    --this.postAttackCool;
                }
                if (this.belchCool > 0){
                    --this.belchCool;
                }
            }
        } else {
            if (this.isAlive()) {
                if (this.bigGlowCool > 0){
                    --this.bigGlowCool;
                }
                if (!this.isActivating()) {
                    if (this.bigGlow > 0.0F) {
                        if (this.bigGlowCool <= 0) {
                            this.bigGlow -= 0.1F;
                        }
                    } else {
                        this.glow();
                    }
                } else {
                    if (this.activateTick > 40){
                        this.bigGlow = 1.0F;
                    }
                }
            }
        }
    }

