@Override
    public void onLivingUpdate()
    {
        /*
         * EntityPlayer nearentityplayer =
         * worldObj.getClosestPlayerToEntity(this, 3D); if (nearentityplayer !=
         * null)// && !hasPath()) { MoCTools.MoveToWater(this, worldObj);
