         * setIsResting(false); }else { boolean restingflag = (entityToAttack ==
         * null && !caughtPrey && !isInsideOfMaterial(Material.water));
         * setIsResting(restingflag);
         * 
         * }
         * 
         * }
         */
        if (getIsResting())
        {
            // biteProgress = 0.4F;
            rotationPitch = -5F;
            if (!isInsideOfMaterial(Material.water) && biteProgress < 0.3F && rand.nextInt(5) == 0)
            {
                biteProgress += 0.005F;
            }
            entityToAttack = findPlayerToAttack();
            if (entityToAttack != null)
            {
                setIsResting(false);
                getMyOwnPath(entityToAttack, 16F);
                // pathToEntity = worldObj.getPathToEntity(this, entityToAttack,
                // f);
            }
            if (MoCreatures.isServer() && entityToAttack != null || getHasCaughtPrey() || rand.nextInt(500) == 0)// isInsideOfMaterial(Material.water)
            // ||
            {
                // boolean restingflag = (entityToAttack == null && !caughtPrey
                // && !isInsideOfMaterial(Material.water));
                setIsResting(false);
                biteProgress = 0;
                hunting = 1;

            }

        }
        else
        {
            if (MoCreatures.isServer() && (rand.nextInt(500) == 0) && entityToAttack == null && !getHasCaughtPrey())// && !isInsideOfMaterial(Material.water))
            {
                setIsResting(true);
                setPathToEntity(null);
            }

        }

        if (isInsideOfMaterial(Material.water))
        {
            myMoveSpeed = 0.8F;
            // setIsResting(false);
        }
        else
        {
            myMoveSpeed = 0.4F;

        }
        if (hunting > 0)
        {
            hunting++;
            if (hunting > 120)
            {
                hunting = 0;
                myMoveSpeed = 0.5F;
            }
            else
            {
                myMoveSpeed = 1.0F;
            }

            if (entityToAttack == null)
            {
                hunting = 0;
                myMoveSpeed = 0.5F;
            }

        }

        if (rand.nextInt(80) == 0 && !getHasCaughtPrey() && !getIsResting())
        {
            crocBite();
        }

        if (MoCreatures.isServer() && rand.nextInt(500) == 0 && !waterbound && !getIsResting() && !isInsideOfMaterial(Material.water))
        {
            MoCTools.MoveToWater(this);
        }

        if (MoCreatures.isServer() && getEdad() < 150 && (rand.nextInt(200) == 0))
        {
            setEdad(getEdad() + 1);
            if (getEdad() >= 90)
            {
                setAdult(true);
            }
        }

        if (waterbound)
        {
            if (!isInsideOfMaterial(Material.water))
            {
                MoCTools.MoveToWater(this);
            }
            else
            {
                waterbound = false;
            }
        }

        if (getHasCaughtPrey())
        {
            if (riddenByEntity != null)
            {
                entityToAttack = null;

                biteProgress = 0.4F;
                setIsResting(false);

                if (!isInsideOfMaterial(Material.water))
                {
                    waterbound = true;
                    if (riddenByEntity instanceof EntityLiving && ((EntityLiving) riddenByEntity).getHealth() > 0)
                    {
                        ((EntityLiving) riddenByEntity).deathTime = 0;
                    }

                    if (MoCreatures.isServer() && rand.nextInt(50) == 0)
                    {
                        riddenByEntity.attackEntityFrom(DamageSource.causeMobDamage(this), 2);
                        if (!(riddenByEntity instanceof EntityPlayer))
                        {
                            MoCTools.destroyDrops(this, 3D);
                        }
                    }

                    /*
                     * if (rand.nextInt(50)==0) { //MoCTools.MoveToWater(this,
                     * worldObj); 
                     *System.out.println("moving to water");
                     * waterbound = true; }
                     */
                }
            }
            else
            {
                setHasCaughtPrey(false);
                biteProgress = 0F;
                waterbound = false;
            }

            if (isSpinning())
            {
                spinInt += 3;
                if ((spinInt % 20) == 0)
                {
                    worldObj.playSoundAtEntity(this, "crocroll", 1.0F, 1.0F + ((rand.nextFloat() - rand.nextFloat()) * 0.2F));
                }
                if (spinInt > 80)
                {
                    spinInt = 0;
                    riddenByEntity.attackEntityFrom(DamageSource.causeMobDamage(this), 4);
                    if (!(riddenByEntity instanceof EntityPlayer))
                    {
                        MoCTools.destroyDrops(this, 3D);
                    }
                }

                //the following if to be removed from SMP

                if (!worldObj.isRemote && riddenByEntity != null && riddenByEntity instanceof EntityPlayer)
                {
                    //TODO 4FIX
                    //MoCreatures.mc.gameSettings.thirdPersonView = 1; 
                }
            }
        }

        super.onLivingUpdate();
    }

@Override
	public void tick() {
		super.tick();

		if (this.breedDelay > 0) this.breedDelay--;
		if (this.deflateDelay > 0) this.deflateDelay--;
		if (this.croakDelay > 0) this.croakDelay--;

		if (this.isBoofed()) {
			if (this.hasAggressiveAttackTarget()) {
				this.navigation = this.attackingNavigator;
			} else {
				if (this.navigation instanceof EndergeticFlyingPathNavigator) {
					this.navigation = new FlyingPathNavigation(this, this.level()) {

						@Override
						public boolean isStableDestination(BlockPos pos) {
							return this.level.isEmptyBlock(pos);
						}

					};
				}

				if (this.getBoofloAttackTarget() == null && this.isPathFinding() && this.getDeltaMovement().length() < 0.25F && RayTraceHelper.rayTrace(this, 2.0D, 1.0F).getType() == Type.BLOCK) {
					this.getNavigation().stop();
				}
			}
		}

		if (this.isControlledByLocalInstance() && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_CHARGE) && this.getAnimationTick() >= 15) {
			this.setDeltaMovement(this.getDeltaMovement().multiply(0.9D, 1.0D, 0.9D));
			this.push(0.0F, -0.225F, 0.0F);
		}

		if (!this.level().isClientSide) {
			this.setOnGround(!this.level().noCollision(DetectionHelper.checkOnGround(this.getBoundingBox(), 0.07F)));

			int power = this.getBoostPower();
			if (power > 0 && !this.isBoostExpanding()) {
				this.setBoostPower(Math.max(0, power - (this.onGround() ? 3 : 2)));
				if (this.getBoostPower() <= 0) {
					this.setBoostLocked(false);
				}
			} else if (this.isBoostExpanding()) {
				if (power < MAX_BOOST_POWER) {
					if (this.isBoostLocked()) {
						int incremented = power + BOOST_POWER_INCREMENT;
						this.setBoostPower(Math.min(HALF_BOOST_POWER, incremented));
						if (incremented >= HALF_BOOST_POWER) {
							this.setBoostExpanding(false);
						}
					} else {
						this.setBoostPower(Math.min(MAX_BOOST_POWER, power + BOOST_POWER_INCREMENT));
					}
				} else {
					if (!this.isBoostLocked() && this.getControllingPassenger() instanceof Player) {
						NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_INFLATE);
						this.playSound(this.getInflateSound(), 0.75F, 1.0F);
					}
					this.setBoostExpanding(false);
				}
			}

			if (this.onGround() && !this.isBoofed() && this.isBoostExpanding()) {
				this.setBoostExpanding(false);
				this.setBoostLocked(false);
			}

			/*
			 * Resends data to clients
			 */
			if (this.isBoofed() && !this.onGround()) {
				this.setBoofed(true);
			}

			if (this.isBoofed() && this.isNoEndimationPlaying() && this.isMovingInAir()) {
				if (RayTraceHelper.rayTrace(this, 2.0D, 1.0F).getType() != Type.BLOCK) {
					NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SWIM);
				}
			}

			if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SWIM) && this.getAnimationTick() <= 15) {
				this.setMovingInAir(true);
			}

			if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_EAT)) {
				if ((this.getAnimationTick() > 20 && this.getAnimationTick() <= 140)) {
					if (this.getAnimationTick() % 20 == 0) {
						if (this.level() instanceof ServerLevel && this.hasCaughtFruit()) {
							((ServerLevel) this.level()).sendParticles(new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(EEItems.BOLLOOM_FRUIT.get())), this.getX(), this.getY() + (double) this.getBbHeight() / 1.5D, this.getZ(), 10, (double) (this.getBbWidth() / 4.0F), (double) (this.getBbHeight() / 4.0F), (double) (this.getBbWidth() / 4.0F), 0.05D);
						}

						if (this.hasCaughtPuffBug()) {
							this.getPassengers().get(0).hurt(this.level().damageSources().mobAttack(this), 0.0F);
						}

						this.playSound(SoundEvents.GENERIC_EAT, 1.0F, 1.0F);
					}
					if (this.getAnimationTick() == 140) {
						this.setCaughtFruit(false);
						this.heal(5.0F);

						if (this.hasCaughtPuffBug()) {
							this.playSound(SoundEvents.PLAYER_BURP, 1.0F, 0.75F);
							this.getPassengers().get(0).discard();
						}
					}
				}
			}

			if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_HOP)) {
				if (this.getAnimationTick() == 10) {
					this.playSound(this.getHopSound(false), 0.95F, this.getVoicePitch());
					this.shouldPlayLandSound = true;
				}
			}

			if (this.shouldPlayLandSound && this.onGround() && !this.wasOnGround) {
				this.playSound(this.getHopSound(true), 0.95F, this.getVoicePitch());
				this.shouldPlayLandSound = false;
			}
		}

		if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_INFLATE) && this.getAnimationTick() == 2) {
			this.boof(1.0F, 1.0F, false);
		}

		if (!this.level().isClientSide && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_GROWL)) {
			if (this.getAnimationTick() == 10) {
				this.playSound(this.getGrowlSound(), 0.75F, this.getVoicePitch());
			}

			if (this.getAnimationTick() >= 20) {
				for (Player players : this.getNearbyPlayers(0.4F)) {
					if (!this.hasAggressiveAttackTarget()) {
						this.setBoofloAttackTargetId(players.getId());
					}
				}
			}
		}

		if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SLAM) && this.getAnimationTick() == 3) {
			this.boof(1.2F, 2.2F, true);
			this.playSound(this.getSlamSound(), 0.75F, 1.0F);
		}

		if (this.isInWater()) {
			if (!this.isBoofed()) {
				this.setBoofed(true);
			} else if (this.random.nextFloat() < 0.7F && this.isControlledByLocalInstance()) {
				this.push(0.0F, 0.05F, 0.0F);
			}
		}

		if (this.onGround() && this.isBoofed()) {
			if (this.hasAggressiveAttackTarget() && !this.hasCaughtPuffBug()) {
				if (!this.level().isClientSide) {
					if (this.isNoEndimationPlaying()) {
						NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_INFLATE);
					} else if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_CHARGE)) {
						NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SLAM);
					}
				}
			} else {
				if (this.isVehicle() && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_CHARGE)) {
					NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SLAM);
				} else {
					if (this.deflateDelay <= 0 && (!this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SLAM) && !this.isInWater())) {
						this.setBoofed(false);
					}
				}
			}
		}

		if (this.getRandom().nextInt(40000) < 10 && !this.hasCaughtFruit() && !this.hasCaughtPuffBug()) {
			this.setHungry(true);
		}

		if (this.level().isClientSide) {
			if (this.isBoofed()) {
				this.OPEN_JAW.setDecrementing(this.getBoofloAttackTarget() == null || this.hasCaughtPuffBug() || (this.hasAggressiveAttackTarget() && !(this.getBoofloAttackTarget() instanceof PuffBug)));

				this.OPEN_JAW.tick();
			}
		}

		this.wasOnGround = this.onGround();

		if (this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_EAT) && !this.hasCaughtFruit()) {
			this.setYRot(this.yHeadRot = this.yBodyRot = this.getLockedYaw());
		}
	}

@SuppressWarnings("unused")
	@SubscribeEvent
	public void entityMove(EntityTravelEvent event) {
		if (!event.entity.isPotionActive(this)) return;
		event.setCanceled(true); // TODO: 10/6/18 fix your shit demoniaque

		EntityLivingBase entity = event.entity;
		float strafe = event.strafe / 2.0f;
		float forward = event.forward / 2.0f;
		float vertical = event.vertical / 2.0f;
		float slipperiness = 1.04f;
		if (entity.isServerWorld() || entity.canPassengerSteer()) {
			if (!entity.isInWater() || entity instanceof EntityPlayer && ((EntityPlayer) entity).capabilities.isFlying) {
				if (!entity.isInLava() || entity instanceof EntityPlayer && ((EntityPlayer) entity).capabilities.isFlying) {
					if (entity.isElytraFlying()) {
						if (entity.motionY > -0.5D) {
							entity.fallDistance = 1.0F;
						}

						Vec3d vec3d = entity.getLookVec();
						float f = entity.rotationPitch * 0.017453292F;
						double d6 = Math.sqrt(vec3d.x * vec3d.x + vec3d.z * vec3d.z);
						double d8 = Math.sqrt(entity.motionX * entity.motionX + entity.motionZ * entity.motionZ);
						double d1 = vec3d.length();
						float f4 = MathHelper.cos(f);
						f4 = (float) ((double) f4 * (double) f4 * Math.min(1.0D, d1 / 0.4D));
						entity.motionY += -0.08D + (double) f4 * 0.06D;

						if (entity.motionY < 0.0D && d6 > 0.0D) {
							double d2 = entity.motionY * -0.1D * (double) f4;
							entity.motionY += d2;
							entity.motionX += vec3d.x * d2 / d6;
							entity.motionZ += vec3d.z * d2 / d6;
						}

						if (f < 0.0F) {
							double d10 = d8 * (double) (-MathHelper.sin(f)) * 0.04D;
							entity.motionY += d10 * 3.2D;
							entity.motionX -= vec3d.x * d10 / d6;
							entity.motionZ -= vec3d.z * d10 / d6;
						}

						if (d6 > 0.0D) {
							entity.motionX += (vec3d.x / d6 * d8 - entity.motionX) * 0.1D;
							entity.motionZ += (vec3d.z / d6 * d8 - entity.motionZ) * 0.1D;
						}

						entity.motionX *= 0.9900000095367432D;
						entity.motionY *= 0.9800000190734863D;
						entity.motionZ *= 0.9900000095367432D;
						entity.move(MoverType.SELF, entity.motionX, entity.motionY, entity.motionZ);

						if (entity.collidedHorizontally && !entity.world.isRemote) {
							double d11 = Math.sqrt(entity.motionX * entity.motionX + entity.motionZ * entity.motionZ);
							double d3 = d8 - d11;
							float f5 = (float) (d3 * 10.0D - 3.0D);

							if (f5 > 0.0F) {
								//entity.playSound(entity.getFallSound((int) f5), 1.0F, 1.0F);
								entity.attackEntityFrom(DamageSource.FLY_INTO_WALL, f5);
							}
						}

						//if (entity.onGround && !entity.world.isRemote) {
						//	entity.setFlag(7, false);
						//}
					} else {
						float f6 = 0.91F;
						BlockPos.PooledMutableBlockPos blockpos$pooledmutableblockpos = BlockPos.PooledMutableBlockPos.retain(entity.posX, entity.getEntityBoundingBox().minY - 1.0D, entity.posZ);

						if (entity.onGround) {
							f6 = slipperiness * 0.91F;
						}

						float f7 = 0.16277136F / (f6 * f6 * f6);
						float f8;

						if (entity.onGround) {
							f8 = entity.getAIMoveSpeed() * f7;
						} else {
							f8 = entity.jumpMovementFactor;
						}

						entity.moveRelative(strafe, vertical, forward, f8);
						f6 = 0.91F;

						if (entity.onGround) {
							f6 = slipperiness * 0.91F;
						}

						if (entity.isOnLadder()) {
							float f9 = 0.15F;
							entity.motionX = MathHelper.clamp(entity.motionX, -0.15000000596046448D, 0.15000000596046448D);
							entity.motionZ = MathHelper.clamp(entity.motionZ, -0.15000000596046448D, 0.15000000596046448D);
							entity.fallDistance = 0.0F;

							if (entity.motionY < -0.15D) {
								entity.motionY = -0.15D;
							}

							boolean flag = entity.isSneaking() && entity instanceof EntityPlayer;

							if (flag && entity.motionY < 0.0D) {
								entity.motionY = 0.0D;
							}
						}

						entity.move(MoverType.SELF, entity.motionX, entity.motionY, entity.motionZ);

						if (entity.collidedHorizontally && entity.isOnLadder()) {
							entity.motionY = 0.2D;
						}

						if (entity.isPotionActive(MobEffects.LEVITATION)) {
							entity.motionY += (0.05D * (double) (entity.getActivePotionEffect(MobEffects.LEVITATION).getAmplifier() + 1) - entity.motionY) * 0.2D;
						} else {
							blockpos$pooledmutableblockpos.setPos(entity.posX, 0.0D, entity.posZ);

							if (!entity.world.isRemote || entity.world.isBlockLoaded(blockpos$pooledmutableblockpos) && entity.world.getChunk(blockpos$pooledmutableblockpos).isLoaded()) {
								if (!entity.hasNoGravity()) {
									entity.motionY -= 0.08D;
								}
							} else if (entity.posY > 0.0D) {
								entity.motionY = -0.1D;
							} else {
								entity.motionY = 0.0D;
							}
						}

						entity.motionY *= 0.9800000190734863D;
						entity.motionX *= (double) f6;
						entity.motionZ *= (double) f6;
						blockpos$pooledmutableblockpos.release();
					}
				} else {
					double d4 = entity.posY;
					entity.moveRelative(strafe, vertical, forward, 0.02F);
					entity.move(MoverType.SELF, entity.motionX, entity.motionY, entity.motionZ);
					entity.motionX *= 0.5D;
					entity.motionY *= 0.5D;
					entity.motionZ *= 0.5D;

					if (!entity.hasNoGravity()) {
						entity.motionY -= 0.02D;
					}

					if (entity.collidedHorizontally && entity.isOffsetPositionInLiquid(entity.motionX, entity.motionY + 0.6000000238418579D - entity.posY + d4, entity.motionZ)) {
						entity.motionY = 0.30000001192092896D;
					}
				}
			} else {
				double d0 = entity.posY;
				float f1 = 0.8f;
				float f2 = 0.02F;
				float f3 = (float) EnchantmentHelper.getDepthStriderModifier(entity);

				if (f3 > 3.0F) {
					f3 = 3.0F;
				}

				if (!entity.onGround) {
					f3 *= 0.5F;
				}

				if (f3 > 0.0F) {
					f1 += (0.54600006F - f1) * f3 / 3.0F;
					f2 += (entity.getAIMoveSpeed() - f2) * f3 / 3.0F;
				}

				entity.moveRelative(strafe, vertical, forward, f2);
				entity.move(MoverType.SELF, entity.motionX, entity.motionY, entity.motionZ);
				entity.motionX *= (double) f1;
				entity.motionY *= 0.800000011920929D;
				entity.motionZ *= (double) f1;

				if (!entity.hasNoGravity()) {
					entity.motionY -= 0.02D;
				}

				if (entity.collidedHorizontally && entity.isOffsetPositionInLiquid(entity.motionX, entity.motionY + 0.6000000238418579D - entity.posY + d0, entity.motionZ)) {
					entity.motionY = 0.30000001192092896D;
				}
			}
		}

		entity.prevLimbSwingAmount = entity.limbSwingAmount;
		double d5 = entity.posX - entity.prevPosX;
		double d7 = entity.posZ - entity.prevPosZ;
		double d9 = entity instanceof net.minecraft.entity.passive.EntityFlying ? entity.posY - entity.prevPosY : 0.0D;
		float f10 = MathHelper.sqrt(d5 * d5 + d9 * d9 + d7 * d7) * 4.0F;

		if (f10 > 1.0F) {
			f10 = 1.0F;
		}

		entity.limbSwingAmount += (f10 - entity.limbSwingAmount) * 0.4F;
		entity.limbSwing += entity.limbSwingAmount;
	}

public static boolean performAttack(IToolStackView tool, ToolAttackContext context) {
    // moved damage calculation, knockback, and cooldown to ToolAttackUtil.Builder
    // missing: enchantment modifiers, we handle modifiers instead

    // calculate conditional damage from modifiers
    float baseDamage = context.getBaseDamage();
    float damage = baseDamage;
    List<ModifierEntry> modifiers = tool.getModifierList();
    for (ModifierEntry entry : modifiers) {
      damage = entry.getHook(ModifierHooks.MELEE_DAMAGE).getMeleeDamage(tool, entry, context, baseDamage, damage);
    }
    // no damage? do nothing
    if (damage <= 0) {
      return false;
    }
    // checked immediately in case anything else changes damage
    boolean isMagic = damage > baseDamage;

    // knockback moved lower

    // apply critical damage boost
    float criticalModifier = context.getCriticalModifier();
    if (criticalModifier != 1) {
      damage += baseDamage * (criticalModifier - 1);
    }

    // removed: sword check hook, replaced by weapon callback
    // removed: fire aspect check, replaced by before damage lower

    // apply cutoff and cooldown, store if damage was above base for magic particles
    float cooldown = context.getCooldown();
    if (cooldown < 1) {
      damage *= (0.2f + cooldown * cooldown * 0.8f);
    }

    // track original health and motion before attack
    // Vec3 originalTargetMotion = targetEntity.getDeltaMovement();
    float oldHealth = 0.0F;
    LivingEntity targetLiving = context.getLivingTarget();
    if (targetLiving != null) {
      oldHealth = targetLiving.getHealth();
    }

    // removed: vanilla knockback enchant support
    // changed: knockback halved for simplicity

    // apply modifier knockback and special effects
    float baseKnockback = context.getBaseKnockback();
    float knockback = baseKnockback;
    for (ModifierEntry entry : modifiers) {
      knockback = entry.getHook(ModifierHooks.MELEE_HIT).beforeMeleeHit(tool, entry, context, damage, baseKnockback, knockback);
    }

    // set hand for proper looting context
    LivingEntity attackerLiving = context.getAttacker();
    EquipmentSlot sourceSlot = context.getSlotType();
    ModifierLootingHandler.setLootingSlot(attackerLiving, sourceSlot);

    // if knockback is below the vanilla amount, we need to prevent knockback, the remainder will be applied later
    AttributeInstance knockbackModifier = null;
    if (knockback < 0.4f) {
      knockbackModifier = disableKnockback(targetLiving);
    } else if (targetLiving != null) {
      // we will apply 0.4 of the knockback in the attack hook, need to apply the remainder ourself
      knockback -= 0.4f;
    }

    ///////////////////
    // actual attack //
    ///////////////////

    // removed: sword special attack check and logic, replaced by this
    Entity targetEntity = context.getTarget();
    boolean didHit = targetEntity.hurt(context.makeDamageSource(), damage);

    // reset hand to make sure we don't mess with vanilla tools
    ModifierLootingHandler.setLootingSlot(attackerLiving, EquipmentSlot.MAINHAND);
    // reset knockback if needed
    enableKnockback(knockbackModifier);

    // if we failed to hit, fire failure hooks
    // alternatively, if we cannot hit this target, we are supposed to return true for the sake of special casing endermen,
    Level level = context.getLevel();
    boolean isExtraAttack = context.isExtraAttack();
    Projectile projectile = context.getProjectile();
    if (!didHit || projectile != null && !TinkerEffects.canHitWithProjectile(targetLiving)) {
      if (!isExtraAttack) {
        level.playSound(null, attackerLiving.getX(), attackerLiving.getY(), attackerLiving.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, attackerLiving.getSoundSource(), 1.0F, 1.0F);
      }
      // alert modifiers nothing was hit, mainly used for fiery
      for (ModifierEntry entry : modifiers) {
        entry.getHook(ModifierHooks.MELEE_HIT).failedMeleeHit(tool, entry, context, damage);
      }
      return false;
    }

    // post melee hook - TODO: should this be lower?
    tool.getHook(ToolHooks.MELEE_HIT).afterMeleeHit(tool, context, damage);

    // determine damage actually dealt
    float damageDealt = damage;
    if (targetLiving != null) {
      damageDealt = oldHealth - targetLiving.getHealth();
    }

    // apply knockback
    if (knockback > 0) {
      if (targetLiving != null) {
        targetLiving.knockback(knockback, Mth.sin(attackerLiving.getYRot() * DEGREE_TO_RADIANS), -Mth.cos(attackerLiving.getYRot() * DEGREE_TO_RADIANS));
      } else {
        targetEntity.push(-Mth.sin(attackerLiving.getYRot() * DEGREE_TO_RADIANS) * knockback, 0.1d, Mth.cos(attackerLiving.getYRot() * DEGREE_TO_RADIANS) * knockback);
      }
      attackerLiving.setDeltaMovement(attackerLiving.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
      attackerLiving.setSprinting(false);
    }

    // removed: sword sweep attack, handled above

    // apply velocity change to players if needed
    if (targetEntity.hurtMarked && targetEntity instanceof ServerPlayer serverPlayer) {
      serverPlayer.connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
      targetEntity.hurtMarked = false;
      // TODO: why was this needed before? targetEntity.setDeltaMovement(originalTargetMotion);
    }

    // play sound effects and particles

    Player attackerPlayer = context.getPlayerAttacker();
    if (attackerPlayer != null) {
      // particles
      if (criticalModifier > 1) {
        attackerPlayer.crit(targetEntity);
      }
      if (isMagic) {
        attackerPlayer.magicCrit(targetEntity);
      }
      // sounds
      level.playSound(null, attackerLiving.getX(), attackerLiving.getY(), attackerLiving.getZ(), context.getSound(), attackerLiving.getSoundSource(), 1.0F, 1.0F);
    }
    if (damageDealt > 2.0F && level instanceof ServerLevel server) {
      int particleCount = (int)(damageDealt * 0.5f);
      server.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0, 0.1, 0.2);
    }

    // deal attacker thorns damage
    attackerLiving.setLastHurtMob(targetEntity);
    if (targetLiving != null) {
      EnchantmentHelper.doPostHurtEffects(targetLiving, attackerLiving);
    }

    // apply modifier effects
    // removed: bane of arthropods hook, replaced by this
    for (ModifierEntry entry : modifiers) {
      entry.getHook(ModifierHooks.MELEE_HIT).afterMeleeHit(tool, entry, context, damageDealt);
    }

    // hurt resistance adjustment for high speed weapons
    float speed = tool.getStats().get(ToolStats.ATTACK_SPEED);
    int time = Math.round(20f / speed);
    if (time < targetEntity.invulnerableTime) {
      targetEntity.invulnerableTime = (targetEntity.invulnerableTime + time) / 2;
    }

    // final attack hooks
    if (attackerPlayer != null) {
      if (targetLiving != null) {
        if (!level.isClientSide && !isExtraAttack) {
          ItemStack held = attackerLiving.getItemBySlot(sourceSlot);
          if (!held.isEmpty()) {
            held.hurtEnemy(targetLiving, attackerPlayer);
          }
        }
        attackerPlayer.awardStat(Stats.DAMAGE_DEALT, Math.round(damageDealt * 10.0F));
      }
      // removed: fire damage, handled in modifier hook above
      if (projectile == null) {
        attackerPlayer.causeFoodExhaustion(0.1F);
      }

      // add usage stat
      if (!isExtraAttack && projectile == null) {
        attackerPlayer.awardStat(Stats.ITEM_USED.get(tool.getItem()));
      }
    }

    // damage the tool
    if (!tool.hasTag(TinkerTags.Items.UNARMED)) {
      int durabilityLost = targetLiving != null ? 1 : 0;
      if (!tool.hasTag(TinkerTags.Items.MELEE_PRIMARY)) {
        durabilityLost *= 2;
      }
      // don't do the full damage animation for broken projectiles as it's not next to you, so that's weird
      if (projectile != null) {
        ToolDamageUtil.damage(tool, durabilityLost, attackerLiving, attackerLiving.getItemBySlot(sourceSlot));
      } else {
        ToolDamageUtil.damageAnimated(tool, durabilityLost, attackerLiving, sourceSlot);
      }
    }

    return true;
  }

@Override
    @Deprecated
    public void render(float pTicks, PoseStack poseStack, MultiBufferSource bufferSourceList) {
        var world = Minecraft.getInstance().level;
        if (world == null) return;

        var matrixTranslation = this.getRenderPosition(pTicks);
        var now = world.getGameTime() + pTicks;

        if (this.getTrailMaxLength() <= 0) return;

        var buffer = OctoRenderManager.getOrCreateBuffer(this);

        if (buffer == null)
            return;

        var aliveNow = this.isTrailAlive();
        var growingNow = aliveNow && this.isTrailGrowing();
        var minDistance = getTrailMinSampleDistance();
        var minDistanceSq = minDistance * minDistance;

        if (growingNow) {
            var head = buffer.peekFirst();
            if (head == null) {
                buffer.write(matrixTranslation, now);
            } else {
                var distSq = head.position().distanceToSqr(matrixTranslation);
                if (distSq >= minDistanceSq && now > head.time()) {
                    var samplesPerTick = Math.max(1, getTrailSamplesPerTick());
                    var sampleInterval = 1.0 / samplesPerTick;
                    var deltaTime = Math.max(1e-6, now - head.time());
                    var stepsByTime = (int) Math.floor(deltaTime / sampleInterval);

                    if (stepsByTime > 0) {
                        var stepsByDistance = (int) Math.ceil(Math.sqrt(distSq) / minDistance);
                        var steps = Math.min(stepsByTime, Math.max(1, stepsByDistance));

                        for (int i = 1; i <= steps; i++) {
                            var sampleTime = head.time() + sampleInterval * i;
                            if (sampleTime > now) break;
                            double t = (sampleTime - head.time()) / deltaTime;
                            var samplePos = head.position().lerp(matrixTranslation, t);
                            buffer.write(samplePos, sampleTime);
                        }
                    }
                }
            }
        }

        var maxAge = getTrailEffectiveMaxAgeTicks(growingNow);
        buffer.pruneOlderThan(now - maxAge);
        buffer.trimToSize(this.getTrailMaxSamples());

        var points = new ArrayList<Vec3>();
        var lifeFractions = new ArrayList<Float>();

        if (aliveNow) {
            var headLife = 0f;
            if (!growingNow && buffer.peekFirst() != null) {
                headLife = (float) Mth.clamp((now - buffer.peekFirst().time()) / maxAge, 0.0, 1.0);
            }
            points.add(Vec3.ZERO);
            lifeFractions.add(headLife);
        }

        for (var sample : buffer) {
            var relative = sample.position().subtract(matrixTranslation);
            var life = (float) Mth.clamp((now - sample.time()) / maxAge, 0.0, 1.0);
            points.add(relative);
            lifeFractions.add(life);
        }

        if (points.size() < 2) return;

        points = new ArrayList<>(this.getTrailRenderPositions(points, pTicks));
        if (points.size() != lifeFractions.size()) {
            var size = Math.min(points.size(), lifeFractions.size());
            points = new ArrayList<>(points.subList(0, size));
            lifeFractions = new ArrayList<>(lifeFractions.subList(0, size));
        }

        if (points.size() > 1) {
            var densePoints = new ArrayList<Vec3>(points.size());
            var denseLives = new ArrayList<Float>(lifeFractions.size());
            var maxSteps = Math.max(2, getTrailSamplesPerTick() * 4);

            densePoints.add(points.getFirst());
            denseLives.add(lifeFractions.getFirst());

            for (int i = 0; i < points.size() - 1; i++) {
                var p1 = points.get(i);
                var p2 = points.get(i + 1);
                var l1 = lifeFractions.get(i);
                var l2 = lifeFractions.get(i + 1);
                var dist = p1.distanceTo(p2);

                if (dist > minDistance) {
                    var steps = (int) Math.ceil(dist / minDistance);
                    steps = Math.min(steps, maxSteps);

                    for (int s = 1; s < steps; s++) {
                        float t = s / (float) steps;
                        densePoints.add(p1.lerp(p2, t));
                        denseLives.add(Mth.lerp(t, l1, l2));
                    }
                }

                densePoints.add(p2);
                denseLives.add(l2);
            }

            points = densePoints;
            lifeFractions = denseLives;
        }

        var partialPoses = new ArrayList<Vec3>();
        var partialLives = new ArrayList<Float>();

        if (points.size() > 2) {
            for (var i = 0; i < points.size() - 1; i++) {
                var p0 = i == 0 ? points.getFirst() : points.get(i - 1);
                var p1 = points.get(i);
                var p2 = points.get(i + 1);
                var p3 = i == points.size() - 2 ? points.getLast() : points.get(i + 2);

                var l1 = lifeFractions.get(i);
                var l2 = lifeFractions.get(i + 1);

                partialPoses.add(p1);
                partialLives.add(l1);

                var interpolationPoints = Math.max(1, this.getTrailInterpolationPoints() + 1);
                for (float f = 1f / interpolationPoints; f < 1; f += 1f / interpolationPoints) {
                    partialPoses.add(VectorUtils.catmullromVec(f, p0, p1, p2, p3));
                    partialLives.add(Mth.lerp(f, l1, l2));
                }
            }
            partialPoses.add(points.getLast());
            partialLives.add(lifeFractions.getLast());
        } else {
            partialPoses.addAll(points);
            partialLives.addAll(lifeFractions);
        }

        if (partialPoses.size() < 2) return;

        var cleanPoses = new ArrayList<Vec3>();
        var cleanLives = new ArrayList<Float>();
        for (var i = 0; i < partialPoses.size(); i++) {
            var v = partialPoses.get(i);
            if (v == null) continue;
            cleanPoses.add(v);
            cleanLives.add(partialLives.get(i));
        }

        partialPoses = cleanPoses;
        partialLives = cleanLives;

        if (partialPoses.size() < 2) return;

        var faces = Math.max(1, getTrailFaces());
        var ringSize = faces == 1 ? 2 : faces;
        var crossVecs = new Vec3[partialPoses.size()][ringSize];
        var lastIndex = partialPoses.size() - 1;
        var baseScale = this.getTrailScale();

        var widthPower = Math.max(0.05, getTrailWidthPower());
        var angleStep = faces == 1 ? 180.0 : 360.0 / faces;

        for (var i = 0; i < partialPoses.size(); i++) {
            var current = partialPoses.get(i);
            if (current == null) continue;

            var prev = i == 0 ? current : partialPoses.get(i - 1);
            var next = i == lastIndex ? current : partialPoses.get(i + 1);

            var tangent = next.subtract(prev);
            if (tangent.lengthSqr() < 1e-6) continue;

            var perpendicular = tangent.cross(Y_VEC);
            if (perpendicular.lengthSqr() < 1e-6) {
                perpendicular = tangent.cross(VectorUtils.X_VEC);
            }

            if (perpendicular.lengthSqr() < 1e-6) continue;

            var axis = tangent.normalize();
            var base = perpendicular.normalize();

            var ratio = 1.0 - Math.pow((double) i / Math.max(1, lastIndex), widthPower);
            var scale = baseScale * ratio;
            if (scale <= 1e-6) {
                continue;
            }

            var first = base.scale(scale);
            for (var j = 0; j < ringSize; j++) {
                crossVecs[i][j] = VectorUtils.rotate(first, axis, angleStep * j);
            }
        }

        var color1 = new Color(this.getTrailFadeInColor(), true);
        var color2 = new Color(this.getTrailFadeOutColor(), true);

        poseStack.pushPose();

        var matrix4f = poseStack.last().pose();
        var tes = bufferSourceList.getBuffer(TRAIL_RENDER_TYPE);

        for (var i = 0; i < partialPoses.size() - 1; i++) {
            var pos1 = partialPoses.get(i);
            var pos2 = partialPoses.get(i + 1);

            if (pos1 == null || pos2 == null) continue;
            if (pos2.subtract(pos1).lengthSqr() < 1e-6) continue;

            var t1 = i / (float) (partialPoses.size() - 1);
            var t2 = (i + 1) / (float) (partialPoses.size() - 1);
            var c1 = ColorUtils.blend(color1, color2, t1);
            var c2 = ColorUtils.blend(color1, color2, t2);

            for (var j = 0; j < ringSize; j++) {
                var jNext = (j + 1) % ringSize;
                var o1a = crossVecs[i][j];
                var o1b = crossVecs[i][jNext];
                var o2a = crossVecs[i + 1][j];
                var o2b = crossVecs[i + 1][jNext];
                if (o1a == null || o1b == null || o2a == null || o2b == null) continue;

                TesselatorUtils.drawQuadGradient(tes, matrix4f,
                        (float) (pos2.x + o2b.x), (float) (pos2.y + o2b.y), (float) (pos2.z + o2b.z),
                        (float) (pos1.x + o1b.x), (float) (pos1.y + o1b.y), (float) (pos1.z + o1b.z),
                        (float) (pos1.x + o1a.x), (float) (pos1.y + o1a.y), (float) (pos1.z + o1a.z),
                        (float) (pos2.x + o2a.x), (float) (pos2.y + o2a.y), (float) (pos2.z + o2a.z),
                        c2, c1);
            }
        }

        poseStack.popPose();
    }

@SuppressWarnings("deprecation")
    public void applyEffectTick(LivingEntity livingEntity, int amplify) {
        Level world = livingEntity.level;
        if (this == GoetyEffects.PRESSURE.get()){
            int count = 0;
            for (LivingEntity other : world.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(8.0F + amplify))){
                if (livingEntity.hasLineOfSight(other)){
                    ++count;
                }
            }
            if (count >= 3){
                livingEntity.hurt(ModDamageSource.getDamageSource(livingEntity.level, ModDamageSource.PHOBIA), 1.0F);
            }
        }
        if (this == GoetyEffects.NYCTOPHOBIA.get()){
            if (world.getLightLevelDependentMagicValue(livingEntity.blockPosition()) < 0.1 || livingEntity.hasEffect(MobEffects.DARKNESS)) {
                livingEntity.hurt(ModDamageSource.getDamageSource(livingEntity.level, ModDamageSource.PHOBIA), 1.0F);
            }
        }
        if (this == GoetyEffects.SUN_ALLERGY.get()){
            boolean burn = MobUtil.isInSunlight(livingEntity);

            if (burn){
                ItemStack helmet = livingEntity.getItemBySlot(EquipmentSlot.HEAD);
                if (!helmet.isEmpty()) {
                    if (MobUtil.validEntity(livingEntity)) {
                        if (helmet.isDamageableItem()) {
                            helmet.setDamageValue(helmet.getDamageValue() + world.random.nextInt(2));
                            if (helmet.getDamageValue() >= helmet.getMaxDamage()) {
                                livingEntity.broadcastBreakEvent(EquipmentSlot.HEAD);
                                livingEntity.setItemSlot(EquipmentSlot.HEAD, ItemStack.EMPTY);
                            }
                        }
                    }
                    burn = false;
                }
                if (burn){
                    livingEntity.setSecondsOnFire(8);
                }
            }
        }
        if (this == GoetyEffects.STORMS_WRATH.get()){
            float chance = 0.1F;
            chance += amplify / 10.0F;
            if (livingEntity.level.isRainingAt(livingEntity.blockPosition())){
                chance += 0.1F;
                if (livingEntity.level.isThundering()){
                    chance += 0.25F;
                }
            }
            if (livingEntity.level.canSeeSky(livingEntity.blockPosition())){
                if (livingEntity.getRandom().nextFloat() <= chance){
                    LightningBolt lightningBolt = new LightningBolt(EntityType.LIGHTNING_BOLT, livingEntity.level);
                    lightningBolt.moveTo(Vec3.atBottomCenterOf(livingEntity.blockPosition()));
                    livingEntity.level.addFreshEntity(lightningBolt);
                }
            }
        }
        if (this == GoetyEffects.PHOTOSYNTHESIS.get()){
            if (MobUtil.isInSunlightNoChance(livingEntity)) {
                if (livingEntity.getHealth() < livingEntity.getMaxHealth()) {
                    livingEntity.heal(1.0F);
                }
            }
        }
        if (this == GoetyEffects.TRIPPING.get()) {
            if (world.random.nextFloat() <= 0.25F + (amplify / 10.0F) && MobUtil.isMoving(livingEntity)) {
                double d0 = world.random.nextDouble() * world.random.nextIntBetweenInclusive(-1, 1);
                double d1 = (world.random.nextDouble() * world.random.nextIntBetweenInclusive(-1, 1)) / 2.0D;
                double d2 = world.random.nextDouble() * world.random.nextIntBetweenInclusive(-1, 1);
                MobUtil.push(livingEntity, d0, d1, d2);
            }
        }
        if (this == GoetyEffects.ARROWMANTIC.get()){
            for (AbstractArrow abstractArrow : world.getEntitiesOfClass(AbstractArrow.class, livingEntity.getBoundingBox().inflate(2.0F + amplify))){
                if (!abstractArrow.onGround()){
                    double d0 = livingEntity.getX() - abstractArrow.getX();
                    double d1 = livingEntity.getY(0.3333333333333333D) - abstractArrow.getY();
                    double d2 = livingEntity.getZ() - abstractArrow.getZ();
                    double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                    abstractArrow.shoot(d0, d1 + d3 * (double)0.2F, d2, 1.0F + (amplify / 5.0F), 10);
                }
            }
        }
        if (this == GoetyEffects.FIERY_AURA.get()){
            if (world instanceof ServerLevel serverLevel) {
                float f = 2.0F + amplify;
                ServerParticleUtil.addAuraParticles(serverLevel, ParticleTypes.FLAME, livingEntity, f);
                for (LivingEntity living : world.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(f))) {
                    if (!living.isOnFire() && !living.hasEffect(MobEffects.FIRE_RESISTANCE) && !living.fireImmune() && !MobUtil.areAllies(livingEntity, living) && MobUtil.validEntity(living) && living != livingEntity) {
                        living.setSecondsOnFire(5 * (amplify + 1));
                        if (living.getRemainingFireTicks() > 0) {
                            ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.FLAME, living);
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(livingEntity.blockPosition(), SoundEvents.FIRECHARGE_USE, 1.0F, 0.75F));
                        }
                    }
                }
            }
        }
        if (this == GoetyEffects.FROSTY_AURA.get()){
            if (world instanceof ServerLevel serverLevel) {
                float f = 2.0F + amplify;
                ServerParticleUtil.addAuraParticles(serverLevel, ParticleTypes.SNOWFLAKE, livingEntity, f);
                for (LivingEntity living : world.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(f))) {
                    if (!living.isFreezing() && living.canFreeze() && !MobUtil.areAllies(livingEntity, living) && MobUtil.validEntity(living) && living != livingEntity) {
                        if (living.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), 100, amplify))) {
                            ServerParticleUtil.addParticlesAroundSelf(serverLevel, ParticleTypes.SNOWFLAKE, living);
                            ModNetwork.sendToALL(new SPlayWorldSoundPacket(livingEntity.blockPosition(), SoundEvents.PLAYER_HURT_FREEZE, 1.0F, 0.75F));
                        }
                    }
                }
            }
        }
        if (this == GoetyEffects.CHILL_HIDE.get()){
            if (world instanceof ServerLevel serverLevel) {
                if (livingEntity.tickCount % 5 == 0) {
                    float f = livingEntity.getBbWidth();
                    ServerParticleUtil.windParticle(serverLevel, CHILL_HIDE, f, livingEntity.getBbHeight() / 2.0F, livingEntity.getId(), livingEntity.position());
                }
                if (livingEntity.tickCount % 15 == 0) {
                    serverLevel.sendParticles(new AuraParticleOption(livingEntity.getId(), livingEntity.getBbHeight(), CHILL_HIDE_AURA), livingEntity.getX(), livingEntity.getY() + (livingEntity.getBbHeight() / 2.0F), livingEntity.getZ(), 1, 0, 0, 0, 0.5F);
                }
            }
        }
        if (this == GoetyEffects.FIRE_TRAIL.get()){
            BlockState blockState = world.getBlockState(livingEntity.blockPosition());
            if (MobUtil.isMoving(livingEntity)){
                if (blockState.canBeReplaced(new DirectionalPlaceContext(world, livingEntity.blockPosition(), Direction.DOWN, ItemStack.EMPTY, Direction.UP))
                        && world.getFluidState(livingEntity.blockPosition()).isEmpty()
                        && world.getBlockState(livingEntity.blockPosition().below()).isSolidRender(world, livingEntity.blockPosition().below())){
                    world.setBlockAndUpdate(livingEntity.blockPosition(), BaseFireBlock.getState(world, livingEntity.blockPosition()));
                }
            }
        }
        if (this == GoetyEffects.GRAVITY_PULSE.get()) {
            if (livingEntity.tickCount % MathHelper.secondsToTicks(10) == 0) {
                if (world instanceof ServerLevel serverLevel) {
                    double area = Mth.square(livingEntity.getBoundingBox().getSize()) * 2.0F;
                    area *= ((amplify / 2.0D) + 1.0D);
                    ColorUtil colorUtil = GRAVITY_PULSE;
                    serverLevel.sendParticles(new ShockwaveParticleOption(colorUtil.red(), colorUtil.green(), colorUtil.blue(), (float) area, 1, true), livingEntity.getX(), livingEntity.getY() + 0.25F, livingEntity.getZ(), 0, 0, 0, 0, 0.5F);
                    for (LivingEntity target : livingEntity.level.getEntitiesOfClass(LivingEntity.class, livingEntity.getBoundingBox().inflate(area))) {
                        if (target != livingEntity && !MobUtil.areAllies(livingEntity, target) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(target) && target != livingEntity.getVehicle()) {
                            Vec3 vec3 = target.position().subtract(livingEntity.position());
                            vec3 = vec3.scale(2.0D).normalize();
                            target.level.playSound(null, target.getX(), target.getY(), target.getZ(), ModSounds.GRAVITY.get(), livingEntity.getSoundSource(), 0.65F, 0.9F + (livingEntity.getRandom().nextFloat() * 0.4F));
                            MobUtil.pull(target, vec3.x, vec3.y, vec3.z);
                        }
                    }
                }
            }
        }
        if (this == GoetyEffects.PLUNGE.get()){
            if (!livingEntity.hasEffect(MobEffects.LEVITATION)){
                if (MobUtil.validEntity(livingEntity)) {
                    if (livingEntity instanceof Player player) {
                        player.getAbilities().flying &= player.isCreative();
                    }
                    if (livingEntity.isInFluidType()) {
                        livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().subtract(0, 0.05D + (amplify / 100.0D), 0));
                    } else if (BlockFinder.distanceFromGround(livingEntity) > 4) {
                        livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().subtract(0, 0.2D + (amplify / 10.0D), 0));
                    }
                    livingEntity.setSwimming(false);
                }
            }
        }
        if (this == GoetyEffects.NECROSIS.get()){
            if (livingEntity.getMobType() == MobType.UNDEAD) {
                if (livingEntity.tickCount % 50 == 0) {
                    if (livingEntity.getHealth() < livingEntity.getMaxHealth()) {
                        livingEntity.heal(1.0F);
                    }
                }
            } else {
                if (livingEntity.tickCount % 25 == 0) {
                    if (!CuriosFinder.hasUndeadSet(livingEntity)) {
                        livingEntity.hurt(ModDamageSource.getDamageSource(world, ModDamageSource.ROT), 1.0F);
                    } else {
                        if (!CuriosFinder.hasNamelessSet(livingEntity)) {
                            livingEntity.addEffect(new MobEffectInstance(MobEffects.WEAKNESS, 5, 0, false, false));
                        }
                    }
                }
            }
        }
        if (this == GoetyEffects.SOUL_BURN.get()){
            if (livingEntity.tickCount % 20 == 0) {
                boolean flag = livingEntity.hurt(ModDamageSource.getDamageSource(world, ModDamageSource.SOUL_BURN), 2.0F);
                if (livingEntity instanceof Player player && flag) {
                    int amount;
                    if (ISoulContainer.MAX_SOULS <= 100) {
                        amount = 2;
                    } else {
                        amount = (ISoulContainer.MAX_SOULS / 100) * 2;
                    }
                    SEHelper.decreaseSoulsNoDiscount(player, amount);
                }

            }
        }
        if (this == GoetyEffects.ENCHANTED.get()) {
            /*if (livingEntity.tickCount % 4 == 0) {
                livingEntity.heal(livingEntity.getMaxHealth() * 0.01F);
            }*/
            if (!world.isClientSide) {
                if (world instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(new MagicSmokeParticleOption(0xffecff, 0x9f34cd, 10 + world.getRandom().nextInt(10), 0.2F, -0.01F), livingEntity.getRandomX(0.5D), livingEntity.getRandomY(), livingEntity.getRandomZ(0.5D), 0, 0.0F, 0.0F, 0.0F, 1.0F);
                }
                Entity entity = MiscCapHelper.getEnchanter(livingEntity);
                if (entity == null || !entity.isAlive() || (entity instanceof LivingEntity living && living.isDeadOrDying())) {
                    livingEntity.removeEffect(GoetyEffects.ENCHANTED.get());
                } else if (entity instanceof LivingEntity living) {
                    MiscCapHelper.setEnchanterTime(living, 5);
                }
            }
        }
        if (this == GoetyEffects.WOUNDED.get()) {
            if (livingEntity.tickCount % 10 == 0) {
                if (world instanceof ServerLevel serverLevel) {
                    ServerParticleUtil.addParticlesAroundMiddleSelf(serverLevel, ParticleTypes.CRIT, livingEntity);
                }
            }
        }
        if (this == GoetyEffects.CRIPPLED.get()) {
            if (livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.75F) {
                livingEntity.removeEffect(GoetyEffects.CRIPPLED.get());
            }
        }
        if (this == GoetyEffects.STUNNED.get()){
            if (livingEntity.level instanceof ServerLevel serverLevel){
                if (livingEntity.tickCount % 15 == 0) {
                    serverLevel.sendParticles(ModParticleTypes.STUN.get(), livingEntity.getX(), livingEntity.getY() + livingEntity.getBbHeight() + 0.5F, livingEntity.getZ(), 1, 0, 0, 0, 0.5F);
                }
            }
        }
        if (this == GoetyEffects.WILD_RAGE.get()){
            if (!livingEntity.level.isClientSide){
                if (livingEntity instanceof Mob mob && (mob.getAttribute(Attributes.ATTACK_DAMAGE) != null || mob instanceof RangedAttackMob) && mob.getAttribute(Attributes.FOLLOW_RANGE) != null){
                    double follow = mob.getAttributeValue(Attributes.FOLLOW_RANGE);
                    LivingEntity target = world.getNearestEntity(world.getEntitiesOfClass(LivingEntity.class, mob.getBoundingBox().inflate(follow, 4.0D, follow), (p_148152_) -> {
                        return true;
                    }), TargetingConditions.forCombat(), mob, mob.getX(), mob.getEyeY(), mob.getZ());
                    if (target != null && mob != target && mob.getTarget() != target){
                        mob.setTarget(target);
                        mob.setLastHurtByMob(target);
                        mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ANGRY_AT, target.getUUID(), 600L);
                        mob.getBrain().setMemoryWithExpiry(MemoryModuleType.ATTACK_TARGET, target, 600L);
                    }
                    if (mob.getTarget() != null && mob.getTarget().isRemoved()){
                        mob.setTarget(null);
                        mob.setLastHurtByMob(null);
                        mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                        mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                    }
                }
            }
        }
    }

