@Override
	public void onInitialize() {
		// Register the payload on both sides for play and configuration
		PayloadTypeRegistry.clientboundPlay().register(CommonPayload.TYPE, CommonPayload.CODEC);
		PayloadTypeRegistry.serverboundPlay().register(CommonPayload.TYPE, CommonPayload.CODEC);
		PayloadTypeRegistry.clientboundConfiguration().register(CommonPayload.TYPE, CommonPayload.CODEC);
		PayloadTypeRegistry.serverboundConfiguration().register(CommonPayload.TYPE, CommonPayload.CODEC);

		// When the client joins, send a packet expecting it to be echoed back
		ServerPlayConnectionEvents.JOIN.register((listener, sender, server) -> sender.sendPacket(new CommonPayload("play")));
		ServerConfigurationConnectionEvents.CONFIGURE.register((listener, server) -> ServerConfigurationNetworking.send(listener, new CommonPayload("configuration")));

		// Store the player uuid once received from the client
		ServerPlayNetworking.registerGlobalReceiver(CommonPayload.TYPE, (payload, context) -> receivedPlay.add(context.player().getStringUUID()));
		ServerConfigurationNetworking.registerGlobalReceiver(CommonPayload.TYPE, (payload, context) -> receivedConfig.add(context.packetListener().getOwner().id().toString()));

		AtomicLong runOnTick = new AtomicLong(-1);
		AtomicReference<String> uuid = new AtomicReference<>();

		// Ensure that the packets were received on the server
		ServerEntityEvents.ENTITY_LOAD.register((entity, level) -> {
			if (!firstLoad) {
				// No need to check again if the player changes dimensions
				return;
			}

			firstLoad = false;

			if (entity instanceof ServerPlayer player) {
				uuid.set(player.getStringUUID());
				runOnTick.set(player.level().getServer().getLevel(Level.OVERWORLD).getGameTime() + 50);
			}
		});

		ServerTickEvents.END_SERVER_TICK.register(server -> {
			if (server.getLevel(Level.OVERWORLD).getGameTime() != runOnTick.get()) {
				return;
			}

			if (!receivedPlay.remove(uuid.get())) {
				throw new IllegalStateException("Did not receive play response");
			}

			if (!receivedConfig.remove(uuid.get())) {
				throw new IllegalStateException("Did not receive configuration response");
			}

			runOnTick.set(-1);
		});
	}

@SubscribeEvent
    public void worldTick(TickEvent.LevelTickEvent event)
    {
        if (!event.level.isClientSide)
        {
            if (ticks++ > 60)
            {
                ticks = 0;
                Level w = event.level;
                List<LivingEntity> list;
                if(w.isClientSide)
                {
                    ClientLevel cw = (ClientLevel)w;
                    list = new ArrayList<>(100);
                    for(Entity e : cw.entitiesForRendering())
                    {
                        if(e.isAlive() && e instanceof LivingEntity)
                            list.add((LivingEntity)e);
                    }
                }
                else
                {
                    ServerLevel sw = (ServerLevel)w;
                    Stream<LivingEntity> s = StreamSupport.stream(sw.getEntities().getAll().spliterator(), false)
                            .filter(Entity::isAlive)
                            .filter(e -> e instanceof LivingEntity)
                            .map(e -> (LivingEntity)e);
                    list = s.collect(Collectors.toList());
                }

                for(LivingEntity liv : list)
                {
                    AttributeInstance grav = liv.getAttribute(ForgeMod.ENTITY_GRAVITY.get());

                    boolean inPlains = liv.level().getBiome(liv.blockPosition()).is(BiomeTags.IS_FOREST);
                    if (inPlains && !grav.hasModifier(REDUCED_GRAVITY))
                    {
                        logger.info("Granted low gravity to Entity: {}", liv);
                        grav.addTransientModifier(REDUCED_GRAVITY);
                    }
                    else if (!inPlains && grav.hasModifier(REDUCED_GRAVITY))
                    {
                        logger.info("Removed low gravity from Entity: {}", liv);
                        grav.removeModifier(REDUCED_GRAVITY.getId());
                    }
                }
            }

        }
    }

public static Block validateBlockForNeighborNotification(final ServerLevel worldServer, final BlockPos pos, @Nullable Block blockIn,
        final BlockPos otherPos, final LevelChunk chunk) {
        if (blockIn == null) {
            // If the block is null, check with the PhaseState to see if it can perform a safe way
            final PhaseContext<?> currentContext = PhaseTracker.getInstance().getPhaseContext();
            final PhaseTrackerCategory trackerConfig = SpongeConfigs.getCommon().get().phaseTracker;

            if (currentContext.state == TickPhase.Tick.TILE_ENTITY) {
                // Try to save ourselves
                final @Nullable BlockEntity source = (BlockEntity) currentContext.getSource();

                final @Nullable BlockEntityType<?> type = Optional.ofNullable(source)
                                                   .map(BlockEntity::getType)
                                                   .orElse(null);
                if (type != null) {
                    @Nullable ResourceLocation id = BlockEntityType.getKey(type);
                    if (id == null) {
                        id = ResourceLocation.parse(source.getClass().getCanonicalName());
                    }
                    final Map<String, Boolean> autoFixedTiles = trackerConfig.autoFixNullSourceBlockProvidingBlockEntities;
                    final boolean contained = autoFixedTiles.containsKey(type.toString());
                    // If we didn't map the tile entity yet, we should apply the mapping
                    // based on whether the source is the same as the TileEntity.
                    if (!contained) {
                        autoFixedTiles.put(id.toString(), pos.equals(source.getBlockPos()));
                    }
                    final boolean useTile = contained && autoFixedTiles.get(id.toString());
                    if (useTile) {
                        blockIn = source.getBlockState().getBlock();
                    } else {
                        blockIn = (pos.getX() >> 4 == chunk.getPos().x && pos.getZ() >> 4 == chunk.getPos().z)
                                      ? chunk.getBlockState(pos).getBlock()
                                      : worldServer.getBlockState(pos).getBlock();
                    }
                    if (!contained && trackerConfig.reportNullSourceBlocksOnNeighborNotifications) {
                        PhasePrinter.printNullSourceBlockWithTile(pos, blockIn, otherPos, id, useTile, new NullPointerException("Null Source Block For TileEntity Neighbor Notification"));
                    }
                } else {
                    blockIn = (pos.getX() >> 4 == chunk.getPos().x && pos.getZ() >> 4 == chunk.getPos().z)
                                  ? chunk.getBlockState(pos).getBlock()
                                  : worldServer.getBlockState(pos).getBlock();
                    if (trackerConfig.reportNullSourceBlocksOnNeighborNotifications) {
                        PhasePrinter.printNullSourceBlockNeighborNotificationWithNoTileSource(pos, blockIn, otherPos,
                            new NullPointerException("Null Source Block For Neighbor Notification"));
                    }
                }

            } else {
                blockIn = (pos.getX() >> 4 == chunk.getPos().x && pos.getZ() >> 4 == chunk.getPos().z)
                              ? chunk.getBlockState(pos).getBlock()
                              : worldServer.getBlockState(pos).getBlock();
                if (trackerConfig.reportNullSourceBlocksOnNeighborNotifications) {
                    PhasePrinter.printNullSourceForBlock(worldServer, pos, blockIn, otherPos, new NullPointerException("Null Source Block For Neighbor Notification"));
                }
            }
        }
        return blockIn;
    }

@Override
	public void onInitialize() {
		final Logger logger = ServerLifecycleTests.LOGGER;

		ServerBlockEntityEvents.BLOCK_ENTITY_LOAD.register((blockEntity, level) -> {
			this.serverBlockEntities.add(blockEntity);

			if (PRINT_SERVER_BLOCKENTITY_MESSAGES) {
				logger.info("[SERVER] LOADED " + BuiltInRegistries.BLOCK_ENTITY_TYPE.getKey(blockEntity.getType()).toString() + " - BlockEntities: " + this.serverBlockEntities.size());
			}
		});

		ServerBlockEntityEvents.BLOCK_ENTITY_UNLOAD.register((blockEntity, level) -> {
			this.serverBlockEntities.remove(blockEntity);

			if (PRINT_SERVER_BLOCKENTITY_MESSAGES) {
				logger.info("[SERVER] UNLOADED " + BuiltInRegistries.BLOCK_ENTITY_TYPE.getKey(blockEntity.getType()).toString() + " - BlockEntities: " + this.serverBlockEntities.size());
			}
		});

		ServerTickEvents.END_SERVER_TICK.register(minecraftServer -> {
			if (minecraftServer.getTickCount() % 200 == 0) {
				int entities = 0;

				if (PRINT_SERVER_BLOCKENTITY_MESSAGES) {
					logger.info("[SERVER] Tracked BlockEntities:" + this.serverBlockEntities.size() + " Ticked at: " + minecraftServer.getTickCount() + "ticks");
				}

				for (ServerLevel level : minecraftServer.getAllLevels()) {
					int levelEntities = 0;

					for (LevelChunk chunk : ((LoadedChunksCache) level).fabric_getLoadedChunks()) {
						levelEntities += chunk.getBlockEntities().size();
					}

					if (PRINT_SERVER_BLOCKENTITY_MESSAGES) {
						logger.info("[SERVER] Tracked BlockEntities in " + level.dimension().toString() + " - " + levelEntities);
					}

					entities += levelEntities;
				}

				if (PRINT_SERVER_BLOCKENTITY_MESSAGES) {
					logger.info("[SERVER] Actual Total BlockEntities: " + entities);
				}

				if (entities != this.serverBlockEntities.size()) {
					// Always print mismatches
					logger.error("[SERVER] Mismatch in tracked blockentities and actual blockentities");
				}
			}
		});

		ServerLifecycleEvents.SERVER_STOPPED.register(minecraftServer -> {
			logger.info("[SERVER] Disconnected. Tracking: " + this.serverBlockEntities.size() + " blockentities");

			if (this.serverBlockEntities.size() != 0) {
				logger.error("[SERVER] Mismatch in tracked blockentities, expected 0");
			}
		});
	}

private static void setupFullChunkStatusChangeTest() {
		final Object2ObjectMap<Identifier, Object2IntMap<FullChunkStatus>> numOfEventsPerLevel = new Object2ObjectOpenHashMap<>();
		final Object2ObjectMap<Identifier, Long2ObjectOpenHashMap<FullChunkStatusEvent>> eventsPerChunk = new Object2ObjectOpenHashMap<>();

		ServerChunkEvents.FULL_CHUNK_STATUS_CHANGE.register((level, levelChunk, oldChunkStatus, newChunkStatus) -> {
			final Identifier dimensionId = level.dimension().identifier();

			if (!level.getServer().isSameThread()) {
				level.getServer().halt(false); // make sure the server actually "crashes", the throw below will just log the error.
				throw new AssertionError("FULL_CHUNK_STATUS_CHANGE for " + dimensionId + " NOT ON SERVER THREAD: " + oldChunkStatus + "->" + newChunkStatus);
			}

			if (levelChunk == null) {
				throw new AssertionError("FULL_CHUNK_STATUS_CHANGE for " + dimensionId + " NULL LEVEL CHUNK: " + oldChunkStatus + "->" + newChunkStatus);
			}

			final ChunkPos chunkPos = levelChunk.getPos();

			if (Math.abs(oldChunkStatus.ordinal() - newChunkStatus.ordinal()) != 1) { // check if the chunkStatuses are actually sequential, also ensures chunkStatuses are not the same
				throw new AssertionError("FULL_CHUNK_STATUS_CHANGE for " + dimensionId + " " + chunkPos + " NOT SEQUENTIAL: " + oldChunkStatus + "->" + newChunkStatus);
			}

			FullChunkStatusEvent prevEvent = eventsPerChunk.computeIfAbsent(dimensionId, obj -> new Long2ObjectOpenHashMap<>()).computeIfAbsent(chunkPos.pack(), l -> new FullChunkStatusEvent(FullChunkStatus.INACCESSIBLE, FullChunkStatus.INACCESSIBLE));

			if (prevEvent.newChunkStatus() != oldChunkStatus) { // check if newChunkStatus from the previous event == oldChunkStatus for this current event. Catches any out-of-sync firing issues.
				throw new AssertionError("FULL_CHUNK_STATUS_CHANGE for " + dimensionId + " " + chunkPos + " PREVIOUS_EVENT: " + prevEvent.oldChunkStatus() + "->" + prevEvent.newChunkStatus() + " / CURRENT_EVENT: " + oldChunkStatus + "->" + newChunkStatus);
			}

			eventsPerChunk.get(dimensionId).put(chunkPos.pack(), new FullChunkStatusEvent(oldChunkStatus, newChunkStatus));
			numOfEventsPerLevel.computeIfAbsent(dimensionId, obj -> new Object2IntOpenHashMap<>()).mergeInt(newChunkStatus, 1, Integer::sum);
		});

		ServerTickEvents.END_LEVEL_TICK.register(level -> {
			if (level.getGameTime() % 20 == 0) { // limit to 1 per second
				Object2IntMap<FullChunkStatus> chunkStatuses = numOfEventsPerLevel.get(level.dimension().identifier());

				if (chunkStatuses != null && !chunkStatuses.isEmpty()) {
					StringBuilder sb = new StringBuilder(level.dimension().identifier() + " ");
					// Logs the number of full chunk status changes for each FullChunkStatus, only logs the newChunkStatus
					chunkStatuses.forEach((newChunkStatus, numOfEvents) -> sb.append(newChunkStatus).append(": ").append(numOfEvents).append(", "));
					LOGGER.info(sb.toString());
					chunkStatuses.clear();
				}
			}
		});

		ServerLifecycleEvents.SERVER_STOPPED.register(server -> {
			eventsPerChunk.forEach((id, chunks) -> {
				final Object2IntMap<FullChunkStatus> totals = new Object2IntOpenHashMap<>();
				chunks.forEach((chunkPos, fullChunkStatusEvent) -> {
					totals.mergeInt(fullChunkStatusEvent.newChunkStatus(), 1, Integer::sum);
				});

				if (totals.containsKey(FullChunkStatus.FULL) || totals.containsKey(FullChunkStatus.BLOCK_TICKING) || totals.containsKey(FullChunkStatus.ENTITY_TICKING)) {
					StringBuilder sb = new StringBuilder("FULL_CHUNK_STATUS_CHANGE expected all chunks to be INACCESSIBLE for " + id + ", instead got ");
					totals.forEach((chunkStatus, finalTotal) -> {
						sb.append(chunkStatus).append(": ").append(finalTotal);
					});
					LOGGER.error(sb.toString());
				}
			});

			// clear everything otherwise it may trip the test incorrectly when you open another world
			numOfEventsPerLevel.clear();
			eventsPerChunk.clear();
		});
	}

@Override
	public void onInitialize() {
		final Logger logger = ServerLifecycleTests.LOGGER;

		ServerEntityEvents.ENTITY_LOAD.register((entity, level) -> {
			this.serverEntities.add(entity);

			if (PRINT_SERVER_ENTITY_MESSAGES) {
				logger.info("[SERVER] LOADED {} with reason {} and isFromDisk {} - Entities: {}", entity.toString(), entity.spawnReason(), entity.isLoadedFromDisk(), this.serverEntities.size());
			}
		});

		ServerEntityEvents.ALLOW_LOAD.register(((entity, level, spawnReason, isLoadedFromDisk) -> {
			if (entity instanceof Sniffer && spawnReason == EntitySpawnReason.COMMAND) {
				logger.info("Stopped sniffer from spawning via command.");
				return false;
			}

			return true;
		}));

		ServerEntityEvents.ENTITY_UNLOAD.register((entity, level) -> {
			this.serverEntities.remove(entity);

			if (PRINT_SERVER_ENTITY_MESSAGES) {
				logger.info("[SERVER] UNLOADED " + entity.toString() + " - Entities: " + this.serverEntities.size());
			}
		});

		ServerEntityEvents.EQUIPMENT_CHANGE.register((livingEntity, equipmentSlot, previousStack, currentStack) -> {
			if (PRINT_SERVER_ENTITY_MESSAGES) {
				logger.info("[SERVER] Entity equipment change: Entity: {}, Slot {}, Previous: {}, Current {} ", livingEntity, equipmentSlot.name(), previousStack, currentStack);
			}
		});

		ServerTickEvents.END_SERVER_TICK.register(server -> {
			if (this.serverTicks++ % 200 == 0) {
				int entities = 0;

				for (ServerLevel level : server.getAllLevels()) {
					final int levelEntities = Iterables.size(level.getAllEntities());

					if (PRINT_SERVER_ENTITY_MESSAGES) {
						logger.info("[SERVER] Tracked Entities in " + level.dimension().toString() + " - " + levelEntities);
					}

					entities += levelEntities;
				}

				if (PRINT_SERVER_ENTITY_MESSAGES) {
					logger.info("[SERVER] Actual Total Entities: " + entities);
				}

				if (entities != this.serverEntities.size()) {
					// Always print mismatches
					logger.error("[SERVER] Mismatch in tracked entities and actual entities");
				}
			}
		});

		ServerLifecycleEvents.SERVER_STOPPED.register(server -> {
			logger.info("[SERVER] Disconnected. Tracking: " + this.serverEntities.size() + " entities");

			if (this.serverEntities.size() != 0) {
				logger.error("[SERVER] Mismatch in tracked entities, expected 0");
			}
		});
	}

