private ChannelFuture flushInbound(boolean recordException, ChannelPromise promise) {
        executingStackCnt++;
        try {
            if (checkOpen(recordException)) {
                pipeline().fireChannelReadComplete();
                runPendingTasks();
            }
        } finally {
            executingStackCnt--;
            maybeRunPendingTasks();
        }

      return checkException(promise);
    }

