@Override
    public ScheduledTask runDelayed(final Plugin plugin, final Consumer<ScheduledTask> task, final long delay,
                                    final TimeUnit unit) {
        Objects.requireNonNull(plugin, "Plugin may not be null");
        Objects.requireNonNull(task, "Task may not be null");
        Objects.requireNonNull(unit, "Time unit may not be null");
        if (delay < 0L) {
            throw new IllegalArgumentException("Delay may not be < 0");
        }

        if (!plugin.isEnabled()) {
            throw new IllegalPluginAccessException("Plugin attempted to register task while disabled");
        }

        return this.scheduleTimerTask(plugin, task, delay, -1L, unit);
    }

private static Consumer<? extends Entity> wrap(final Plugin plugin, final Runnable runnable) {
        Objects.requireNonNull(plugin, "Plugin may not be null");
        Objects.requireNonNull(runnable, "Runnable may not be null");

        return (final Entity nmsEntity) -> {
            if (!plugin.isEnabled()) {
                // don't execute if the plugin is disabled
                return;
            }
            try {
                runnable.run();
            } catch (final Throwable throwable) {
                plugin.getLogger().log(Level.WARNING, "Entity task for " + plugin.getDescription().getFullName() + " generated an exception", throwable);
            }
        };
    }

private synchronized void runTasks(int currentTick) {
        parsePending();
        while (!this.pending.isEmpty() && this.pending.peek().getNextRun() <= currentTick) {
            CraftTask task = this.pending.remove();
            if (executeTask(task)) {
                final long period = task.getPeriod();
                if (period > 0) {
                    task.setNextRun(currentTick + period);
                    temp.add(task);
                }
            }
            parsePending();
        }
        this.pending.addAll(temp);
        temp.clear();
    }

@Override
    public TaskStatus status() {
      if (future == null) {
        return TaskStatus.SCHEDULED;
      }

      if (future.isCancelled()) {
        return TaskStatus.CANCELLED;
      }

      if (future.isDone()) {
        return TaskStatus.FINISHED;
      }

      return TaskStatus.SCHEDULED;
    }

