private void setMaxConcurrentStreams(boolean autoAckSettings, int newValue) {
        try {
            Http2Settings settings = new Http2Settings().maxConcurrentStreams(newValue);
            // Mimic behavior of DefaultHttp2ConnectionDecoder.onSettingsRead:
            if (autoAckSettings) {
                encoder.writeSettingsAck(ctx, newPromise());
                encoder.remoteSettings(settings);
            } else {
                encoder.consumeReceivedSettings(settings);
                encoder.writeSettingsAck(ctx, newPromise());
            }
            // Flush the remote flow controller to write data
            encoder.flowController().writePendingBytes();
        } catch (Http2Exception e) {
            throw new RuntimeException(e);
        }
    }

@Override
    public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
        assert qpackAttributes != null;
        if (writeResumptionListener != null) {
            writeResumptionListener.enqueue(msg, promise);
            return;
        }

        if ((msg instanceof Http3HeadersFrame || msg instanceof Http3PushPromiseFrame) &&
                !qpackAttributes.dynamicTableDisabled() && !qpackAttributes.encoderStreamAvailable()) {
            writeResumptionListener = WriteResumptionListener.newListener(ctx, this);
            writeResumptionListener.enqueue(msg, promise);
            return;
        }

        write0(ctx, msg, promise);
    }

@Override
            public void rejected(Runnable task, SingleThreadEventExecutor executor) {
                if (!executor.inEventLoop()) {
                    for (int i = 0; i < retries; i++) {
                        // Try to wake up the executor so it will empty its task queue.
                        executor.wakeup(false);

                        LockSupport.parkNanos(backOffNanos);
                        if (executor.offerTask(task)) {
                            return;
                        }
                    }
                }
                // Either we tried to add the task from within the EventLoop or we was not able to add it even with
                // backoff.
                throw new RejectedExecutionException();
            }

