public static <T> void applyToDynamicRegistries(LayeredRegistryAccess<T> registries, T phase) {
		Iterator<RegistryAccess.RegistryEntry<?>> registryEntries = registries.getLayer(phase).registries().iterator();

		while (registryEntries.hasNext()) {
			Registry<?> registry = registryEntries.next().value();

			if (registry instanceof MappedRegistryExtension extension) {
				extension.fabric_applyPendingTagAliases();
				// This is not needed in the static registry code path as the tag aliases are applied
				// before the tags are refreshed. Dynamic registry loading (including tags) takes place earlier
				// than the rest of a data reload, so we need to refresh the tags manually.
				extension.fabric_refreshTags();
			} else {
				throw new ClassCastException("[Fabric] Couldn't apply pending tag aliases to registry %s (%s) since it doesn't implement MappedRegistryExtension"
						.formatted(registry, registry.getClass().getName()));
			}
		}
	}

private RegistryData populate(List<Map<ResourceKey<? extends Registry<?>>, DeferredRegisterData<?>>> registries) {
        var reloadableRegistries = RegistryDataLoader.RELOADABLE_REGISTRIES.stream().map(RegistryDataLoader.RegistryData::key).collect(Collectors.toSet());
        var dataBuilder = RegistryDataBuilder.of().name(modid());

        RegistrySetBuilder world = null, reload = null;
        for (var level : this.dataRegistries) {
            world = new RegistrySetBuilder();
            reload = new RegistrySetBuilder();
            for (var reg : level.values()) {
                if (reloadableRegistries.contains(reg.getRegistryKey()))
                    reload.add(reg);
                else
                    world.add(reg);
            }
            dataBuilder.layer(world, reload);
        }
        return new RegistryData(dataBuilder, world != null && !world.getEntryKeys().isEmpty(), reload != null && !reload.getEntryKeys().isEmpty());
    }

@Override
    @SuppressWarnings("unchecked")
    public <T extends Snapshot> AtomicReference<T> reference(Snapshotable snapshotable) {
        AtomicReference<Snapshot> ref;
        // Very often the same snapshotable is referenced multiple times.
        var readOnly = this.readOnlyReferenceMap;
        if (readOnly != null && (ref = readOnly.get(snapshotable)) != null) {
            return (AtomicReference<T>) ref;
        }
        // If this is a new snapshotable, we need to create a new reference.
        synchronized (this) {
            ref = new AtomicReference<>();
            var prev = referenceMap.putIfAbsent(snapshotable, ref);
            if (prev != null) return (AtomicReference<T>) prev;
            this.queue.add(new Entry(snapshotable, ref));
            return (AtomicReference<T>) ref;
        }
    }

