	static void transfer(AttachmentTarget original, AttachmentTarget target, boolean isDeath) {
		Map<AttachmentType<?>, ?> attachments = ((AttachmentTargetImpl) original).fabric_getAttachments();

		if (attachments == null) {
			return;
		}

		for (Map.Entry<AttachmentType<?>, ?> entry : attachments.entrySet()) {
			AttachmentType<Object> type = (AttachmentType<Object>) entry.getKey();

			if (!isDeath || type.copyOnDeath()) {
				target.setAttached(type, entry.getValue());
			}
		}

		// Avoid unnecessary extra syncing after initial sync
		((AttachmentTargetImpl) target).fabric_clearDeferredSyncChanges();
	}

@Override
		public long insert(ItemVariant resource, long maxAmount, TransactionContext transaction) {
			StoragePreconditions.notBlankNotNegative(resource, maxAmount);

			// Check amount.
			if (maxAmount < 1) return 0;
			// Check that no action is scheduled.
			if (pendingAction != PendingAction.NONE) return 0;
			// Check that the composter can accept items.
			if (location.getBlockState().getValue(ComposterBlock.LEVEL) >= 7) return 0;
			// Check that the item is compostable.
			Compostable compostable = resource.getComponents().get(DataComponents.COMPOSTABLE);
			if (compostable == null || !(location.level instanceof ServerLevel)) return 0;

			// Schedule insertion.
			updateSnapshots(transaction);
			pendingAction = PendingAction.insert(compostable.layers());
			return 1;
		}

@SubscribeEvent(priority = Priority.HIGH)
    static boolean onEntityJoinWorld(EntityJoinLevelEvent event) {
        Entity entity = event.getEntity();
        if (entity.getClass() == ItemEntity.class) {
            ItemStack stack = ((ItemEntity)entity).getItem();
            Item item = stack.getItem();
            if (item.hasCustomEntity(stack)) {
                Entity newEntity = item.createEntity(event.getLevel(), entity, stack);
                if (newEntity != null) {
                    entity.discard();
                    @SuppressWarnings("resource")
                    var executor = LogicalSidedProvider.WORKQUEUE.get(event.getLevel().isClientSide() ? LogicalSide.CLIENT : LogicalSide.SERVER);
                    executor.schedule(new TickTask(0, () -> event.getLevel().addFreshEntity(newEntity)));
                    return true;
                }
            }
        }
        return false;
    }

private void sendRegistries(Acknowledge msg, CustomPayloadEvent.Context ctx) {
        if (msg.token() != expectedToken) {
            LOGGER.error(MARKER, "Received unknown acknowledgement received {} exptected {}", msg.token(), expectedToken);
            ctx.getConnection().disconnect(Component.literal("Illegal Acknowledge packet received, unknown token: " + msg.token()));
            return;
        }

        // We've got no more to send, so finish this task!
        if (this.snapshot == null || this.snapshot.isEmpty()) {
            taskCtx.finish(type());
            return;
        }

        // Send the next registry!
        var name = this.snapshot.keySet().iterator().next();
        var data = this.snapshot.remove(name);
        expectedToken = this.handler.expectAck(this::sendRegistries);
        NetworkInitialization.CONFIG.reply(new RegistryData(expectedToken, name, data), ctx);
    }

