public void tick() {
        final List<GlobalScheduledTask> run;
        synchronized (this.stateLock) {
            ++this.tickCount;
            if (this.tasksByDeadline.isEmpty()) {
                run = null;
            } else {
                run = this.tasksByDeadline.remove(this.tickCount);
            }
        }

        if (run == null) {
            return;
        }

        for (int i = 0, len = run.size(); i < len; ++i) {
            run.get(i).run();
        }
    }

