void parsePending() { // Paper
        CraftTask head = this.head;
        CraftTask task = head.getNext();
        CraftTask lastTask = head;
        for (; task != null; task = (lastTask = task).getNext()) {
            if (task.getTaskId() == -1) {
                task.run();
            } else if (task.getPeriod() >= CraftTask.NO_REPEATING) {
                this.pending.add(task);
                this.runners.put(task.getTaskId(), task);
            }
        }
        // We split this because of the way things are ordered for all of the async calls in CraftScheduler
        // (it prevents race-conditions)
        for (task = head; task != lastTask; task = head) {
            head = task.getNext();
            task.setNext(null);
        }
        this.head = lastTask;
    }

public static PackedRegistries createRegistries(ResourceManager resourceManager) {
        // add tags and loot tables for unit tests
        LayeredRegistryAccess<RegistryLayer> layers = RegistryLayer.createRegistryAccess();
        List<Registry.PendingTags<?>> pendingTags = TagLoader.loadTagsForExistingRegistries(resourceManager, layers.getLayer(RegistryLayer.STATIC));

        List<HolderLookup.RegistryLookup<?>> lookupsWithPendingTags = TagLoader.buildUpdatedLookups(layers.getAccessForLoading(RegistryLayer.WORLD), pendingTags);
        RegistryAccess.Frozen worldGenRegistries = RegistryDataLoader.load(resourceManager, lookupsWithPendingTags, RegistryDataLoader.WORLD_REGISTRIES, Util.backgroundExecutor()).join();
        layers = layers.replaceFrom(RegistryLayer.WORLD, worldGenRegistries);

        List<HolderLookup.RegistryLookup<?>> staticAndWorldgenLookups = Stream.concat(lookupsWithPendingTags.stream(), worldGenRegistries.listRegistries()).toList();
        RegistryAccess.Frozen dimensionRegistries = RegistryDataLoader.load(resourceManager, staticAndWorldgenLookups, RegistryDataLoader.DIMENSION_REGISTRIES, Util.backgroundExecutor()).join();
        layers = layers.replaceFrom(RegistryLayer.DIMENSIONS, dimensionRegistries);
        // load registry here to ensure bukkit object registry are correctly delayed if needed
        try {
            Class.forName(org.bukkit.Registry.class.getName());
        } catch (final ClassNotFoundException ignored) {
        }

        return new PackedRegistries(layers, pendingTags);
    }

private boolean enqueueLoginPluginMessage(PluginMessagePacket packet) {
    if (loginPluginMessagesOverflowed) {
      ReferenceCountUtil.release(packet);
      return false;
    }
    int packetSize = packet.content().readableBytes();
    long newBytes = loginPluginMessagesBytes.addAndGet(packetSize);
    int newCount = loginPluginMessagesCount.incrementAndGet();
    if (newBytes > MAX_QUEUED_LOGIN_PLUGIN_MESSAGE_BYTES
        || newCount > MAX_QUEUED_LOGIN_PLUGIN_MESSAGES) {
      loginPluginMessagesOverflowed = true;
      ReferenceCountUtil.release(packet);
      logger.warn("Disconnecting {}: pre-join plugin-message queue exceeded its limits "
              + "({} messages, {} bytes).", player, newCount, newBytes);
      player.disconnect(Component.translatable("velocity.error.plugin-message-overflow"));
      return false;
    }
    loginPluginMessages.add(packet);
    return true;
  }

@Override
        public @NonNull Optional<? extends Consumer<CommandCause>> parseValue(
                final Parameter.@NonNull Key<? super Consumer<CommandCause>> parameterKey,
                final ArgumentReader.@NonNull Mutable reader,
                final CommandContext.@NonNull Builder context
        ) throws ArgumentParseException {
            final String next = reader.parseString();
            try {
                final UUID id = UUID.fromString(next);
                final Consumer<CommandCause> ret = CallbackCommand.this.callbacks.getIfPresent(id);
                if (ret == null) {
                    throw reader.createException(Component.text(
                            "The callback you provided was not valid. Keep in mind that callbacks will expire after 10 " +
                            "minutes, so you might want to consider clicking faster next time!"));
                }
                return Optional.of(ret);
            } catch (final IllegalArgumentException ex) {
                throw reader.createException(Component.text("Input " + next + " was not a valid UUID"));
            }
        }

