public void runTasks() {
        if (tasks.isEmpty()) return;
        LOGGER.debug(LOADING, "Dispatching synchronous work for work queue {}: {} jobs", modLoadingStage, tasks.size());
        RuntimeException aggregate = new RuntimeException();
        Stopwatch timer = Stopwatch.createStarted();
        for (TaskInfo t : tasks) {
            makeRunnable(t, Runnable::run, aggregate);
        }
        timer.stop();
        if (aggregate.getSuppressed().length > 0) {
            LOGGER.fatal(
                    LOADING,
                    "Synchronous work queue completed exceptionally in {}, see suppressed exceptions for details:",
                    timer,
                    aggregate
            );
            throw aggregate;
        } else {
            LOGGER.debug(LOADING, "Synchronous work queue completed in {}", timer);
        }
    }

public ClickEvent<ClickEvent.Payload.Custom> createClickEvent(final ClickCallback<Audience> callback, final ClickCallback.Options options) {
        Objects.requireNonNull(callback, "callback");
        Objects.requireNonNull(options, "options");
        final UUID uuid = UUID.randomUUID();
        final int uses = options.uses();

        long expiry;
        try {
            expiry = System.nanoTime() + options.lifetime().toNanos();
        } catch (final ArithmeticException _) {
            expiry = Long.MAX_VALUE;
        }

        if (expiry == Long.MAX_VALUE && uses == ClickCallback.UNLIMITED_USES) {
            this.permanent.put(uuid, callback);
        } else if (uses > 0 && expiry > System.nanoTime()) {
            this.temporary.put(uuid, new CallbackData(callback, expiry, new AtomicInteger(uses)));
        }

        return ClickEvent.custom(KEY, new BinaryTagHolderImpl(UUIDUtils.toNbt(uuid)));
    }

@ApiStatus.Internal
    public void onResourcePackStatus(UUID id, ResourcePackStatus status) {
        var pendingPack = pendingResourcePacks.get(id);
        if (pendingPack == null) return;

        pendingPack.callback().packEventReceived(id, status, this);
        if (!status.intermediate()) {
            // Remove the callback and finish the future if relevant
            pendingResourcePacks.remove(id);

            // If the resource pack is required and failed to load, bye bye!
            if (pendingPack.required() && status != ResourcePackStatus.SUCCESSFULLY_LOADED) {
                kick(MISSING_REQUIRED_RESOURCE_PACK);
            }

            if (pendingResourcePacks.isEmpty() && resourcePackFuture != null) {
                resourcePackFuture.complete(null);
                resourcePackFuture = null;
            }
        }
    }

@Override
    public Set<Point> calculateExternal(Palette blockPalette,
                                        Point[] neighbors,
                                        LightLookup lightLookup,
                                        PaletteLookup paletteLookup) {
        if (!isValidBorders) return Set.of();
        ShortArrayFIFOQueue queue = buildExternalQueue(blockPalette, neighbors, content, lightLookup, paletteLookup);
        final byte[] contentPropagationTemp = LightCompute.compute(blockPalette, queue);
        this.contentPropagationSwap = LightCompute.bake(contentPropagationSwap, contentPropagationTemp);
        // Propagate changes to neighbors and self
        Set<Point> toUpdate = new HashSet<>();
        for (int i = 0; i < neighbors.length; i++) {
            final Point neighbor = neighbors[i];
            if (neighbor == null) continue;
            final BlockFace face = FACES[i];
            if (!LightCompute.compareBorders(content, contentPropagation, contentPropagationTemp, face)) {
                toUpdate.add(neighbor);
            }
        }
        return toUpdate;
    }

