@SuppressWarnings("rawtypes")
    private void checkProviders() {
        // Seriously, ok so, uh...
        if (!this.pendingProviders.compareAndSet(true, false)) {
            return; // we've done our work already
        }
        // Then, we want to inversely iterate the stack (from bottom to top)
        // to properly mimic as though the frames were created at the time of the
        // phase switches. It does not help the debugging of cause frames
        // except for this method call-point.
        for (final Iterator<PhaseContext<@NonNull ?>> iterator = this.phaseContextProviders.descendingIterator(); iterator.hasNext(); ) {
            final PhaseContext<@NonNull ?> context = iterator.next();
            final StackFrame frame = this.pushCauseFrame(); // these should auto close
            context.getFrameModifier().accept(frame); // The frame will be auto closed by the phase context
        }
        // Clear the list since everything is now loaded.
        // PhaseStates will handle automatically closing their frames
        // and then any new phase states that get entered can still be lazily loaded afterwards, while
        // we take advantage of the already made modifications are being tracked by the stack manager
        this.phaseContextProviders.clear();
    }

private void startTask(final SpongeScheduledTask task) {
        this.executeRunnable(() -> {
            task.setState(SpongeScheduledTask.ScheduledTaskState.EXECUTING);
            try (final @Nullable PhaseContext<@NonNull ?> context = this.createContext(task, task.task().plugin())) {
                if (context != null) {
                    context.buildAndSwitch();
                }
                try {
                    task.task.executor().accept(task);
                } catch (final Throwable t) {
                    SpongeCommon.logger().error("The Scheduler tried to run the task '{}' owned by '{}' but an error occurred.",
                            task.name(), task.task().plugin().metadata().id(), t);
                }
            } finally {
                if (!task.isCancelled()) {
                    task.setState(SpongeScheduledTask.ScheduledTaskState.RUNNING);
                }
                this.onTaskCompletion(task);
            }
        });
    }

void recvComplete() {
        try {
            QuicheQuicConnection conn = connection;
            if (conn.isFreed()) {
                // Ensure we flush all pending writes.
                forceFlushParent();
                return;
            }
            fireChannelReadCompleteIfNeeded();

            // If we had called recv we need to ensure we call send as well.
            // See https://docs.rs/quiche/0.6.0/quiche/struct.Connection.html#method.send
            connectionSend(conn);

            // We are done with the read loop, flush all pending writes now.
            forceFlushParent();
            freeIfClosed();
        } finally {
            inFireChannelReadCompleteQueue = false;
        }
    }

@Override
        public void process(InetSocketAddress sender, InetSocketAddress recipient, ByteBuf buffer, QuicPacketType type,
                            long version, ByteBuf scid, ByteBuf dcid, ByteBuf token) throws Exception {
            QuicheQuicChannel channel = quicPacketRead(ctx, sender, recipient,
                    type, version, scid,
                    dcid, token, senderSockaddrMemory, recipientSockaddrMemory, freeTask, localConnIdLength, config);
            if (channel != null) {
                // Add to queue first, we might be able to safe some flushes and consolidate them
                // in channelReadComplete(...) this way.
                if (channel.markInFireChannelReadCompleteQueue()) {
                    needsFireChannelReadComplete.add(channel);
                }
                channel.recv(sender, recipient, buffer);
                for (ByteBuffer retiredSourceConnectionId : channel.retiredSourceConnectionId()) {
                    removeMapping(channel, retiredSourceConnectionId);
                }
                for (ByteBuffer newSourceConnectionId : channel.newSourceConnectionIds()) {
                    addMapping(channel, newSourceConnectionId);
                }
            }
        }

