@Test
    public void initialWindowSizeChangeForReservedStreamShouldBeAppliedWhenActivated() throws Http2Exception {
        Http2Stream pushStream = reservePushStreamOnServer();

        // The peer only grants credit for the pushed stream via WINDOW_UPDATE.
        controller.initialWindowSize(0);
        reset(listener);
        controller.incrementWindowSize(pushStream, 100);
        // The credit already makes the reserved stream writable, and the listener is told so.
        verify(listener, times(1)).writabilityChanged(pushStream);
        assertTrue(controller.isWritable(pushStream));
        reset(listener);

        pushStream.open(false);
        // Activation keeps the credit, so the stream stays writable and the listener is not told otherwise.
        verify(listener, never()).writabilityChanged(pushStream);
        assertTrue(controller.isWritable(pushStream));
        assertEquals(100, controller.windowSize(pushStream));

        FakeFlowControlled data = new FakeFlowControlled(100);
        controller.addFlowControlled(pushStream, data);
        controller.writePendingBytes();
        data.assertFullyWritten();
    }

@Test
    public void sectionAcknowledgmentOfLowerRequiredInsertCountDoesNotLowerAcknowledgedInsertCount() throws Exception {
        setup(128, 2);
        BiConsumer<CharSequence, CharSequence> sink = (n, v) -> { };
        ByteBuf blocked = encodeBlockingFrame(2);
        ByteBuf lower = encodeBlockingFrame(1);
        try {
            assertFalse(decoder.decode(attributes, 0L, blocked, blocked.readableBytes(), sink, () -> {
                // Decoding is not repeated, only the Section Acknowledgment sent on resumption matters here.
            }));
            // Unblocks stream 0 on the second insertion and acknowledges a Required Insert Count of 2 in doing so.
            decoder.insertLiteral(decoderStream, FOO, BAR);
            decoder.insertLiteral(decoderStream, FOO + 2, BAR + 2);
            // Stream 4 is not blocked and acknowledges a Required Insert Count that is lower than the one of stream 0.
            assertTrue(decoder.decode(attributes, 4L, lower, lower.readableBytes(), sink, () -> { }));
            decoder.insertLiteral(decoderStream, FOO + 3, BAR + 3);

            assertThat(knownReceivedCountOfEncoder(streamId -> streamId == 0 ? 2 : 1), is(3));
        } finally {
            blocked.release();
            lower.release();
            assertFalse(decoderStream.finishAndReleaseAll());
        }
    }

@Override
        public int poll() {
            final long cIndex = consumerIndex;
            final int offset = (int) (cIndex & mask);
            // If we can't see the next available element we can't poll
            int value = get(offset);
            if (emptyValue == value) {
                /*
                 * NOTE: Queue may not actually be empty in the case of a producer (P1) being interrupted after
                 * winning the CAS on offer but before storing the element in the queue. Other producers may go on
                 * to fill up the queue after this element.
                 */
                if (cIndex != producerIndex) {
                    do {
                        value = get(offset);
                    } while (emptyValue == value);
                } else {
                    return emptyValue;
                }
            }
            lazySet(offset, emptyValue);
            CONSUMER_INDEX.lazySet(this, cIndex + 1);
            return value;
        }

