@Test
    public void testClientCloseWhileConnectionIsQueued() throws Exception {
        BlockingQueue<LocalChannel> accepted = new LinkedBlockingQueue<>();
        Channel sc = bindServerWithAutoReadDisabled(accepted);
        ChannelFuture cf = null;
        try {
            cf = connectClient();
            LocalChannel child = accepted.poll(5, SECONDS);
            assertNotNull(child);

            assertTrue(cf.channel().close().await().isSuccess());
            assertInstanceOf(ClosedChannelException.class, cf.cause());

            // Accepting the queued connection now must not reopen or activate the client, and the accepted
            // channel must be closed.
            sc.config().setAutoRead(true);
            assertTrue(child.closeFuture().await(5, SECONDS));
            assertFalse(child.isActive());
            assertFalse(cf.channel().isOpen());
            assertFalse(cf.channel().isActive());
        } finally {
            closeQuietly(cf);
            closeChannel(sc);
        }
    }

@Override
    public Set<Point> calculateExternal(Palette blockPalette,
                                        Point[] neighbors,
                                        LightLookup lightLookup,
                                        PaletteLookup paletteLookup) {
        if (!isValidBorders) return Set.of();
        byte[] contentPropagationTemp = CONTENT_FULLY_LIT;
        if (!fullyLit) {
            ShortArrayFIFOQueue queue = buildExternalQueue(blockPalette, neighbors, content, lightLookup, paletteLookup);
            contentPropagationTemp = LightCompute.compute(blockPalette, queue);
            this.contentPropagationSwap = LightCompute.bake(contentPropagationSwap, contentPropagationTemp);
        } else {
            this.contentPropagationSwap = null;
        }
        // Propagate changes to neighbors and self
        Set<Point> toUpdate = new HashSet<>();
        for (int i = 0; i < neighbors.length; i++) {
            final Point neighbor = neighbors[i];
            if (neighbor == null) continue;
            final BlockFace face = FACES[i];
            if (!LightCompute.compareBorders(content, contentPropagation, contentPropagationTemp, face)) {
                toUpdate.add(neighbor);
            }
        }
        return toUpdate;
    }

