public void clean() {
        while (true) {
            ListenerReference ref = (ListenerReference) queue.poll();
            if (ref == null)
                return;

            var chunkHolder = byChunkThenBlock.get(ChunkPos.pack(ref.pos));
            if (chunkHolder == null)
                continue;

            var set = chunkHolder.get(ref.pos.asLong());
            if (set == null)
                continue;
            // We might remove a different garbage-collected reference,
            // or we might remove nothing if the reference was already removed.
            // Because the hash codes will match, that is fine.
            boolean removed = set.remove(ref);

            if (removed && set.isEmpty()) {
                chunkHolder.remove(ref.pos.asLong());
                if (chunkHolder.isEmpty()) {
                    byChunkThenBlock.remove(ChunkPos.pack(ref.pos));
                }
            }
        }
    }

@Override
    public @Nullable ScheduledTask runDelayed(final Plugin plugin, final Consumer<ScheduledTask> task, final Runnable retired,
                                              final long delayTicks) {
        Objects.requireNonNull(plugin, "Plugin may not be null");
        Objects.requireNonNull(task, "Task may not be null");
        if (delayTicks <= 0) {
            throw new IllegalArgumentException("Delay ticks may not be <= 0");
        }

        if (!plugin.isEnabled()) {
            throw new IllegalPluginAccessException("Plugin attempted to register task while disabled");
        }

        final EntityScheduledTask ret = new EntityScheduledTask(plugin, -1, task, retired);

        if (!this.scheduleInternal(ret, delayTicks)) {
            return null;
        }

        if (!plugin.isEnabled()) {
            // handle race condition where plugin is disabled asynchronously
            ret.cancel();
        }

        return ret;
    }

@Override
    public ScheduledTask runAtFixedRate(final Plugin plugin, final Consumer<ScheduledTask> task, final long initialDelayTicks, final long periodTicks) {
        Objects.requireNonNull(plugin, "Plugin may not be null");
        Objects.requireNonNull(task, "Task may not be null");
        if (initialDelayTicks <= 0) {
            throw new IllegalArgumentException("Initial delay ticks may not be <= 0");
        }
        if (periodTicks <= 0) {
            throw new IllegalArgumentException("Period ticks may not be <= 0");
        }

        if (!plugin.isEnabled()) {
            throw new IllegalPluginAccessException("Plugin attempted to register task while disabled");
        }

        final GlobalScheduledTask ret = new GlobalScheduledTask(plugin, periodTicks, task);

        this.scheduleInternal(ret, initialDelayTicks);

        if (!plugin.isEnabled()) {
            // handle race condition where plugin is disabled asynchronously
            ret.cancel();
        }

        return ret;
    }

