public static void syncPendingConfigs(MinecraftServer server) {
        synchronized (lock) {
            for (var player : server.getPlayerList().getPlayers()) {
                if (!player.connection.hasChannel(ConfigFilePayload.TYPE)) {
                    continue; // Only sync configs to NeoForge clients supporting config sync
                }

                if (player.connection.getConnection().isMemoryConnection()) {
                    continue; // Do not sync server configs with ourselves
                }

                var toSync = configsToSync.get(player.connection.getConnection());
                if (toSync == null) {
                    // null for GameTestPlayer. Should not happen for normal players though.
                    if (player.getClass() == ServerPlayer.class) {
                        throw new IllegalStateException("configsToSync should contain an entry for player " + player.getName());
                    } else {
                        continue;
                    }
                }
                toSync.forEach((fileName, data) -> {
                    PacketDistributor.sendToPlayer(player, new ConfigFilePayload(fileName, data));
                });
                toSync.clear();
            }
        }
    }

@Override
    protected void onRootCommit(BlockState originalState) {
        BlockState currentState = location.getBlockState();

        // Skip updating if the composter was removed
        if (!currentState.is(Blocks.COMPOSTER)) return;

        // Note: even if originalState == currentState, we want to send the COMPOSTER_FILL level event below
        if (originalState != currentState) {
            // Revert back to the blockstate before any changes happened so that the next
            // call will not short-circuit due to the blockstate not really changing.
            location.level.setBlock(location.pos, originalState, 0);
            // Now perform the change that will trigger notifications to other blocks/neighbors/clients.
            location.level.setBlockAndUpdate(location.pos, currentState);
            location.level.gameEvent(GameEvent.BLOCK_CHANGE, location.pos, GameEvent.Context.of(currentState));
        }

        int originalLevel = originalState.getValue(ComposterBlock.LEVEL);
        int currentLevel = currentState.getValue(ComposterBlock.LEVEL);

        if (originalLevel < ComposterBlock.MAX_LEVEL) {
            if (currentLevel == ComposterBlock.MAX_LEVEL) {
                location.level.scheduleTick(location.pos, currentState.getBlock(), SharedConstants.TICKS_PER_SECOND);
            }
            location.level.levelEvent(LevelEvent.COMPOSTER_FILL, location.pos, currentLevel > originalLevel ? 1 : 0);
        }
    }

public void registerTo(final EntitySchedulerTickList newTickList) {
        synchronized (this.stateLock) {
            final EntitySchedulerTickList prevList = this.scheduledList;
            if (prevList == newTickList) {
                return;
            }
            this.scheduledList = newTickList;

            // make sure tasks scheduled before registration can be ticked
            if (prevList == null && this.hasTasks()) {
                this.insideScheduledList = true;
            }

            // transfer to new list
            if (this.insideScheduledList) {
                if (prevList != null) {
                    prevList.remove(this);
                }
                if (newTickList != null) {
                    newTickList.add(this);
                } else {
                    // retired
                    this.insideScheduledList = false;
                }
            }
        }
    }

@Override
        public void run() {
            final boolean repeating = this.isRepeatingTask();
            if (STATE_IDLE != this.compareAndExchangeStateVolatile(STATE_IDLE, STATE_EXECUTING)) {
                // cancelled
                return;
            }

            try {
                this.run.accept(this);
            } catch (final Throwable throwable) {
                this.plugin.getLogger().log(Level.WARNING, "Global task for " + this.plugin.getDescription().getFullName() + " generated an exception", throwable);
            } finally {
                boolean reschedule = false;
                if (!repeating) {
                    this.setStateVolatile(STATE_FINISHED);
                } else if (STATE_EXECUTING == this.compareAndExchangeStateVolatile(STATE_EXECUTING, STATE_IDLE)) {
                    reschedule = true;
                } // else: cancelled repeating task

                if (!reschedule) {
                    this.run = null;
                } else {
                    FoliaGlobalRegionScheduler.this.scheduleInternal(this, this.repeatDelay);
                }
            }
        }

@Test
  void obtainTasksFromPlugin() throws Exception {
    DeterministicSchedulerBackend backend = new DeterministicSchedulerBackend();
    VelocityScheduler scheduler = new VelocityScheduler(new FakePluginManager(), backend);

    CountDownLatch runningLatch = new CountDownLatch(1);
    CountDownLatch endingLatch = new CountDownLatch(1);

    scheduler.buildTask(FakePluginManager.PLUGIN_A, task -> {
      runningLatch.countDown();
      try {
        endingLatch.await();
      } catch (InterruptedException ignored) {
        Thread.currentThread().interrupt();
      }
      task.cancel();
    }).delay(50, TimeUnit.MILLISECONDS)
        .repeat(Duration.ofMillis(5))
        .schedule();

    backend.advance(50, TimeUnit.MILLISECONDS); // run first tick only (no wall clock)
    assertTrue(runningLatch.await(5, TimeUnit.SECONDS));

    assertEquals(1, scheduler.tasksByPlugin(FakePluginManager.PLUGIN_A).size());

    endingLatch.countDown();
  }

