private void tickResourcePackQueue() {
    ResourcePackInfo queued = outstandingResourcePacks.peek();

    if (queued != null) {
      // Check if the player declined a resource pack once already
      if (previousResourceResponse != null && !previousResourceResponse) {
        // If that happened we can flush the queue right away.
        // Unless its 1.17+ and forced it will come back denied anyway
        while (!outstandingResourcePacks.isEmpty()) {
          queued = outstandingResourcePacks.peek();
          if (queued.getShouldForce() && player.getProtocolVersion()
                  .noLessThan(ProtocolVersion.MINECRAFT_1_17)) {
            break;
          }
          onResourcePackResponse(new ResourcePackResponseBundle(queued.getId(),
                  queued.getHash() == null ? "" : new String(queued.getHash()),
                  PlayerResourcePackStatusEvent.Status.DECLINED));
          queued = null;
        }
        if (queued == null) {
          // Exit as the queue was cleared
          return;
        }
      }

      sendResourcePackRequestPacket(queued);
    }
  }

@Override
  public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
    if (msg instanceof final MinecraftPacket packet) {
      // If the packet exists in the CONFIG state, we want to always
      // ensure that it gets handled by the current handler
      if (this.registry.containsPacket(packet)) {
        ctx.fireChannelRead(msg);
        return;
      }
    }

    int length = 0;
    if (msg instanceof ByteBuf) {
      // keep track of raw packets
      length = ((ByteBuf) msg).readableBytes();
    } else if (msg instanceof ByteBufHolder) {
      // keep track of bytebufs wrapped inside packets
      length = ((ByteBufHolder) msg).content().readableBytes();
    }
    if (this.queueSize + length > MAXIMUM_SIZE) {
      ReferenceCountUtil.release(msg);
      throw QUEUE_LIMIT_FAILED;
    }
    this.queueSize += length;

    // Otherwise, queue the packet
    this.queue.offer(msg);
  }

@Override
  public void encode(ByteBuf buf, ProtocolUtils.Direction direction,
      ProtocolVersion protocolVersion) {
    ProtocolUtils.writeString(buf, message);

    buf.writeLong(unsigned ? Instant.now().toEpochMilli() : expiry.toEpochMilli());
    buf.writeLong(unsigned ? 0L : Longs.fromByteArray(salt));

    ProtocolUtils.writeByteArray(buf, unsigned ? EncryptionUtils.EMPTY : signature);

    buf.writeBoolean(signedPreview);

    if (protocolVersion.noLessThan(ProtocolVersion.MINECRAFT_1_19_1)) {
      ProtocolUtils.writeVarInt(buf, previousMessages.length);
      for (SignaturePair previousMessage : previousMessages) {
        ProtocolUtils.writeUuid(buf, previousMessage.getSigner());
        ProtocolUtils.writeByteArray(buf, previousMessage.getSignature());
      }

      if (lastMessage != null) {
        buf.writeBoolean(true);
        ProtocolUtils.writeUuid(buf, lastMessage.getSigner());
        ProtocolUtils.writeByteArray(buf, lastMessage.getSignature());
      } else {
        buf.writeBoolean(false);
      }
    }
  }

