@Test
    public void testForceCloseTimeoutAppliedToInboundCloseFrame() throws Exception {
        final long forceCloseTimeoutMillis = 100;
        final Queue<ChannelPromise> stalledWrites = new ArrayDeque<ChannelPromise>();
        EmbeddedChannel client = createClient();
        EmbeddedChannel server = createStallingServer(forceCloseTimeoutMillis, stalledWrites);

        assertFalse(server.writeInbound(client.<ByteBuf>readOutbound()));
        assertFalse(client.writeInbound(server.<ByteBuf>readOutbound()));

        // The peer initiates the close handshake.
        assertTrue(client.writeOutbound(new CloseWebSocketFrame(WebSocketCloseStatus.NORMAL_CLOSURE)));
        assertFalse(server.writeInbound(client.<ByteBuf>readOutbound()));

        // The server's echo write is stalled, simulating a peer that stopped draining its socket
        // receive buffer. The channel must not stay open indefinitely waiting on that write.
        assertEquals(1, stalledWrites.size());
        assertTrue(server.isOpen());

        server.advanceTimeBy(forceCloseTimeoutMillis * 2, TimeUnit.MILLISECONDS);
        server.runScheduledPendingTasks();

        assertFalse(server.isOpen());

        client.close();
        assertFalse(client.finishAndReleaseAll());
        assertFalse(server.finishAndReleaseAll());
    }

void fireChildRead(Http2Frame frame) {
        assert eventLoop().inEventLoop();
        if (!isActive()) {
            ReferenceCountUtil.release(frame);
        } else if (readStatus != ReadStatus.IDLE && isInboundBufferEmpty()) {
            // A read is in progress or has been requested and nothing is queued, so dispatch directly. If frames are
            // still queued (e.g. this frame was delivered re-entrantly while doBeginRead() is running pipeline
            // callbacks after it stopped early) we must queue behind them below to preserve ordering; the read loop
            // that is still on the stack will drain them.
            final RecvByteBufAllocator.Handle allocHandle = unsafe.recvBufAllocHandle();

            unsafe.doRead0(frame, allocHandle);
            // We currently don't need to check for readEOS because the parent channel and child channel are limited
            // to the same EventLoop thread. There are a limited number of frame types that may come after EOS is
            // read (unknown, reset) and the trade off is less conditionals for the hot path (headers/data) at the
            // cost of additional readComplete notifications on the rare path.
            if (allocHandle.continueReading()) {
                maybeAddChannelToReadCompletePendingQueue();
            } else {
                unsafe.notifyReadComplete(allocHandle, true, false);
            }
        } else {
            if (inboundBuffer == null) {
                inboundBuffer = new ArrayDeque<Object>(4);
            }
            inboundBuffer.add(frame);
        }
    }

private int distributeToChildren(int maxBytes, Writer writer, State state) throws Http2Exception {
        long oldTotalQueuedWeights = state.totalQueuedWeights;
        State childState = state.pollPseudoTimeQueue();
        State nextChildState = state.peekPseudoTimeQueue();
        childState.setDistributing();
        try {
            assert nextChildState == null || nextChildState.pseudoTimeToWrite >= childState.pseudoTimeToWrite :
                "nextChildState[" + nextChildState.streamId + "].pseudoTime(" + nextChildState.pseudoTimeToWrite +
                ") < " + " childState[" + childState.streamId + "].pseudoTime(" + childState.pseudoTimeToWrite + ')';
            int nsent = distribute(nextChildState == null ? maxBytes :
                            min(maxBytes, (int) min((nextChildState.pseudoTimeToWrite - childState.pseudoTimeToWrite) *
                                               childState.weight / oldTotalQueuedWeights + allocationQuantum, MAX_VALUE)
                               ),
                               writer,
                               childState);
            state.pseudoTime += nsent;
            childState.updatePseudoTime(state, nsent, oldTotalQueuedWeights);
            return nsent;
        } finally {
            childState.unsetDistributing();
            // Do in finally to ensure the internal flags is not corrupted if an exception is thrown.
            // The offer operation is delayed until we unroll up the recursive stack, so we don't have to remove from
            // the priority pseudoTimeQueue due to a write operation.
            if (childState.activeCountForTree != 0) {
                state.offerPseudoTimeQueue(childState);
            }
        }
    }

@ParameterizedTest
    @ValueSource(longs = { 30000, -1 })
    public void gracefulShutdownCompletesWhenChannelBecomesInactive(long gracefulShutdownTimeoutMillis) {
        Http2ConnectionHandler serverHandler = new Http2ConnectionHandlerBuilder()
                .server(true).frameListener(new Http2FrameAdapter()).build();
        EmbeddedChannel server = new EmbeddedChannel(serverHandler);
        EmbeddedChannel client = newClientChannel(gracefulShutdownTimeoutMillis);
        Http2ConnectionHandler clientHandler = client.pipeline().get(Http2ConnectionHandler.class);
        try {
            exchangeFrames(client, server);
            writeHeadersOnStream3(clientHandler, client);

            // Close via the pipeline: EmbeddedChannel.close() would cancel the graceful shutdown timeout task.
            ChannelFuture closeFuture = client.pipeline().close();
            assertFalse(closeFuture.isDone());

            // The connection is lost while the graceful shutdown waits for stream 3.
            client.unsafe().close(client.voidPromise());
            client.runPendingTasks();

            assertFalse(client.isOpen());
            assertEquals(0, clientHandler.connection().numActiveStreams());
            assertTrue(closeFuture.isSuccess(), "close() must complete once the channel is closed");
        } finally {
            client.finishAndReleaseAll();
            server.finishAndReleaseAll();
        }
    }

