private void setup(long maxTableCapacity, int maxBlockedStreams, int expectedTableFreePercentage) throws Exception {
        attributes = new QpackAttributes(parent, false);
        Http3.setQpackAttributes(parent, attributes);
        maxEntries = Math.toIntExact(QpackUtil.maxEntries(maxTableCapacity));
        DefaultHttp3SettingsFrame localSettingsFrame = new DefaultHttp3SettingsFrame();
        localSettingsFrame.settings().put(HTTP3_SETTINGS_QPACK_MAX_TABLE_CAPACITY.id(), maxTableCapacity);
        localSettingsFrame.settings().put(HTTP3_SETTINGS_QPACK_BLOCKED_STREAMS.id(), (long) maxBlockedStreams);
        if (maxBlockedStreams > 0) {
            // section acknowledgment will implicitly ack insert count.
            stateSyncStrategyAckNextInsert = false;
        }
        when(syncStrategy.entryAdded(anyInt())).thenAnswer(__ -> stateSyncStrategyAckNextInsert);
        encDynamicTable = new QpackEncoderDynamicTable(16, expectedTableFreePercentage);
        decDynamicTable = new QpackDecoderDynamicTable();
        decoder = new QpackDecoder(maxTableCapacity, maxBlockedStreams, decDynamicTable, syncStrategy);
        encoder = new QpackEncoder(encDynamicTable, sensitivityDetector);
        if (maxBlockedStreams > 0) {
            suspendedEncoderInstructions = new LinkedBlockingQueue<>();
        }
        EmbeddedQuicStreamChannel encoderStream = (EmbeddedQuicStreamChannel) parent.createStream(UNIDIRECTIONAL,
                new ForwardWriteToReadOnOtherHandler(new QpackEncoderHandler(maxTableCapacity, decoder),
                        suspendedEncoderInstructions)).get();
        EmbeddedQuicStreamChannel decoderStream = (EmbeddedQuicStreamChannel) parent.createStream(UNIDIRECTIONAL,
                new ForwardWriteToReadOnOtherHandler(new QpackDecoderHandler(encoder))).get();
        attributes.encoderStream(encoderStream);
        attributes.decoderStream(decoderStream);
        encoder.configureDynamicTable(attributes, maxTableCapacity, maxBlockedStreams);
    }

@Override
    protected void decode(ChannelHandlerContext ctx, RedisMessage msg, List<Object> out) throws Exception {
        if (msg instanceof ArrayHeaderRedisMessage) {
            msg = decodeRedisArrayHeader((ArrayHeaderRedisMessage) msg);
            if (msg == null) {
                return;
            }
        } else {
            ReferenceCountUtil.retain(msg);
        }

        while (!depths.isEmpty()) {
            AggregateState current = depths.peek();
            current.children.add(msg);

            // if current aggregation completed, go to parent aggregation.
            if (current.children.size() == current.length) {
                msg = new ArrayRedisMessage(current.children);
                depths.pop();
                pendingElements -= current.length;
            } else {
                // not aggregated yet. try next time.
                return;
            }
        }

        out.add(msg);
    }

@ParameterizedTest(name = "{index}: {0}")
    @MethodSource("proxyTypes")
    public void testPendingWritesFailedWhenConnectionToProxyFails(String type) throws Exception {
        EventLoopGroup localGroup = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());
        try {
            // Nothing is bound to this address, so the connection to the proxy server fails and the channel is
            // closed without ever becoming active.
            ProxyHandler handler = newProxyHandler(type, new LocalAddress("unbound-proxy-" + type));
            Channel ch = new Bootstrap().group(localGroup).channel(LocalChannel.class).handler(handler)
                    .register().sync().channel();

            // Written before the connection is established, so the handler queues it until the proxy handshake
            // is done.
            ByteBuf msg = Unpooled.copiedBuffer("hello", CharsetUtil.US_ASCII);
            ChannelFuture writeFuture = ch.writeAndFlush(msg);
            ChannelFuture connectFuture = ch.connect(DESTINATION);

            assertThat(connectFuture.await(5, TimeUnit.SECONDS)).isTrue();
            assertThat(connectFuture.cause()).isInstanceOf(ConnectException.class);
            assertThat(writeFuture.await(5, TimeUnit.SECONDS)).isTrue();
            assertThat(writeFuture.cause()).isInstanceOf(ProxyConnectException.class);
            assertThat(msg.refCnt()).isZero();
            assertThat(handler.connectFuture().await(5, TimeUnit.SECONDS)).isTrue();
            assertThat(handler.connectFuture().cause()).isInstanceOf(ProxyConnectException.class);
        } finally {
            localGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS);
        }
    }

@Override
    public void handlerAdded(final ChannelHandlerContext ctx) throws Exception {
        this.ctx = ctx;
        Channel channel = ctx.channel();
        pendingUnencryptedWrites = new SslHandlerCoalescingBufferQueue(channel, 16, engineType.wantsDirectBuffer) {
            @Override
            protected int wrapDataSize() {
                return SslHandler.this.wrapDataSize;
            }
        };

        setOpensslEngineSocketFd(channel);
        boolean fastOpen = Boolean.TRUE.equals(channel.config().getOption(ChannelOption.TCP_FASTOPEN_CONNECT));
        boolean active = channel.isActive();
        if (active || fastOpen) {
            // Explicitly flush the handshake only if the channel is already active.
            // With TCP Fast Open, we write to the outbound buffer before the TCP connect is established.
            // The buffer will then be flushed as part of establishing the connection, saving us a round-trip.
            startHandshakeProcessing(active);
            // If we weren't able to include client_hello in the TCP SYN (e.g. no token, disabled at the OS) we have to
            // flush pending data in the outbound buffer later in channelActive().
            final ChannelOutboundBuffer outboundBuffer;
            if (fastOpen && ((outboundBuffer = channel.unsafe().outboundBuffer()) == null ||
                    outboundBuffer.totalPendingWriteBytes() > 0)) {
                setState(STATE_NEEDS_FLUSH);
            }
        }
    }

private void initialize(ChannelHandlerContext ctx) {
        // Avoid the case where destroy() is called before scheduling timeouts.
        // See: https://github.com/netty/netty/issues/143
        switch (state) {
        case 1:
        case 2:
            return;
        default:
             break;
        }

        state = ST_INITIALIZED;
        initOutputChanged(ctx);

        lastReadTime = lastWriteTime = ticker.nanoTime();
        if (readerIdleTimeNanos > 0) {
            readerIdleTimeout = schedule(ctx, new ReaderIdleTimeoutTask(ctx),
                    readerIdleTimeNanos, TimeUnit.NANOSECONDS);
        }
        if (writerIdleTimeNanos > 0) {
            writerIdleTimeout = schedule(ctx, new WriterIdleTimeoutTask(ctx),
                    writerIdleTimeNanos, TimeUnit.NANOSECONDS);
        }
        if (allIdleTimeNanos > 0) {
            allIdleTimeout = schedule(ctx, new AllIdleTimeoutTask(ctx),
                    allIdleTimeNanos, TimeUnit.NANOSECONDS);
        }
    }

@Test
    public void testFlushReenteredFromReadChunkMustNotConsumeQueueEntryTwice() {
        final EmbeddedChannel ch = new EmbeddedChannel(new ChunkedWriteHandler());
        ReentrantFlushChunkedInput input = new ReentrantFlushChunkedInput(ch);
        ChannelFuture future = ch.write(input);
        ch.flush();

        ByteBuf first = ch.readOutbound();
        ByteBuf second = ch.readOutbound();
        assertNull(ch.readOutbound());
        // Before the re-entrancy guard, the nested flush() consumed the queue entry and both
        // invocations read from the same input; the outer doFlush(...) then failed with
        // NoSuchElementException from ArrayDeque.remove() on the already-empty queue.
        // Both chunks were read above, so no message must be left in the buffers.
        assertFalse(ch.finishAndReleaseAll());

        assertEquals(1, first.readInt());
        first.release();
        assertEquals(2, second.readInt());
        second.release();
        // The input must have been read exactly twice, and closed exactly once, after the last
        // read: before the guard, close() happened from the nested invocation while the outer
        // readChunk(...) call had not even returned yet.
        assertEquals(2, input.readChunkCalls());
        assertTrue(input.isClosed());
        assertEquals(2, input.readChunkCallsAtClose());
        assertTrue(future.isSuccess());
    }

private void scheduleCacheExpirationIfNeeded(int ttl, EventLoop loop) {
            for (;;) {
                // We currently don't calculate a new TTL when we need to retry the CAS as we don't expect this to
                // be invoked very concurrently and also we use SECONDS anyway. If this ever becomes a problem
                // we can reconsider.
                ScheduledFuture<?> oldFuture = FUTURE_UPDATER.get(this);
                if (oldFuture == null || oldFuture.getDelay(TimeUnit.SECONDS) > ttl) {
                    ScheduledFuture<?> newFuture = loop.schedule(this, ttl, TimeUnit.SECONDS);
                    // It is possible that
                    // 1. task will fire in between this line, or
                    // 2. multiple timers may be set if there is concurrency
                    // (1) Shouldn't be a problem because we will fail the CAS and then the next loop will see CANCELLED
                    //     so the ttl will not be less, and we will bail out of the loop.
                    // (2) This is a trade-off to avoid concurrency resulting in contention on a synchronized block.
                    if (FUTURE_UPDATER.compareAndSet(this, oldFuture, newFuture)) {
                        if (oldFuture != null) {
                            oldFuture.cancel(true);
                        }
                        break;
                    } else {
                        // There was something else scheduled in the meantime... Cancel and try again.
                        newFuture.cancel(true);
                    }
                } else {
                    break;
                }
            }
        }

@Override
    public void prepareToDestroy() {
        shuttingDown = true;
        CompletionQueue completionQueue = ringBuffer.ioUringCompletionQueue();
        SubmissionQueue submissionQueue = ringBuffer.ioUringSubmissionQueue();

        List<DefaultIoUringIoRegistration> copy = new ArrayList<>(registrations.values());

        for (DefaultIoUringIoRegistration registration: copy) {
            registration.close();
        }

        // Write to the eventfd to ensure that if we submitted a read for the eventfd we will see the completion event.
        Native.eventFdWrite(eventfd.intValue(), 1L);

        // Ensure all previously submitted IOs get to complete before tearing down everything.
        submissionQueue.addNop((byte) Native.IOSQE_IO_DRAIN, RINGFD_TOKEN);

        // Submit everything and wait until we could drain i.
        submissionQueue.submitAndGet();

        while (completionQueue.hasCompletions()) {
            processCompletionsAndHandleOverflow(submissionQueue, completionQueue, completionCallback);
            if (submissionQueue.count() > 0) {
                submissionQueue.submitAndGetNow();
            }
        }
    }

private int processReady(int ready) {
        int ioCount = 0;
        for (int i = 0; i < ready; ++i) {
            final short filter = eventList.filter(i);
            final short flags = eventList.flags(i);
            final int ident = eventList.ident(i);
            if (filter == Native.EVFILT_USER || (flags & Native.EV_ERROR) != 0) {
                // EV_ERROR is returned if the FD is closed synchronously (which removes from kqueue) and then
                // we later attempt to delete the filters from kqueue.
                assert filter != Native.EVFILT_USER ||
                        (filter == Native.EVFILT_USER && ident == KQUEUE_WAKE_UP_IDENT);
                continue;
            }

            ioCount++;
            long id = eventList.udata(i);
            DefaultKqueueIoRegistration registration = registrations.get(id);
            if (registration == null) {
                // This may happen if the channel has already been closed, and it will be removed from kqueue anyways.
                // We also handle EV_ERROR above to skip this even early if it is a result of a referencing a closed and
                // thus removed from kqueue FD.
                logger.warn("events[{}]=[{}, {}, {}] had no registration!", i, ident, id, filter);
                continue;
            }
            registration.handle(ident, filter, flags, eventList.fflags(i), eventList.data(i), id);
        }
        return ioCount;
    }

private int run(IoHandlerContext context, long runAllTasksTimeoutNanos) {
        if (!initialized) {
            if (owningThread.get() == null) {
                throw new IllegalStateException("Owning thread not set");
            }
            initialized = true;
            handler.initialize();
        }
        EventExecutor old = ThreadExecutorMap.setCurrentExecutor(this);
        try {
            if (isShuttingDown()) {
                if (terminationFuture.isDone()) {
                    // Already completely terminated
                    return 0;
                }
                return runAllTasksBeforeDestroy();
            }
            final int ioTasks = handler.run(context);
            // Now run all tasks.
            if (runAllTasksTimeoutNanos < 0) {
                return ioTasks;
            }
            assert runAllTasksTimeoutNanos >= 0;
            return ioTasks + runAllTasks(runAllTasksTimeoutNanos, false);
        } finally {
            ThreadExecutorMap.setCurrentExecutor(old);
        }
    }

@Override
    protected void run() {
        for (;;) {
            Runnable task = takeTask();
            if (task != null) {
                task.run();
                updateLastExecutionTime();
            }

            Channel ch = this.ch;
            if (isShuttingDown()) {
                if (ch != null) {
                    ch.unsafe().close(ch.unsafe().voidPromise());
                }
                if (confirmShutdown()) {
                    break;
                }
            } else {
                if (ch != null) {
                    // Handle deregistration
                    if (!ch.isRegistered()) {
                        runAllTasks();
                        deregister();
                    }
                }
            }
        }
    }

@Override
    public boolean awaitTermination(long timeout, TimeUnit unit)
            throws InterruptedException {
        long deadline = System.nanoTime() + unit.toNanos(timeout);
        for (EventLoop l: activeChildren) {
            for (;;) {
                long timeLeft = deadline - System.nanoTime();
                if (timeLeft <= 0) {
                    return isTerminated();
                }
                if (l.awaitTermination(timeLeft, TimeUnit.NANOSECONDS)) {
                    break;
                }
            }
        }
        for (EventLoop l: idleChildren) {
            for (;;) {
                long timeLeft = deadline - System.nanoTime();
                if (timeLeft <= 0) {
                    return isTerminated();
                }
                if (l.awaitTermination(timeLeft, TimeUnit.NANOSECONDS)) {
                    break;
                }
            }
        }
        return isTerminated();
    }

@Test
    public void testClientCloseAfterServerClosedWithQueuedConnection() throws Exception {
        BlockingQueue<LocalChannel> accepted = new LinkedBlockingQueue<>();
        Channel sc = bindServerWithAutoReadDisabled(accepted);
        ChannelFuture cf = null;
        try {
            cf = connectClient();
            assertNotNull(accepted.poll(5, SECONDS));

            // Close the server and then the client in one event loop task, so the client is closed before it
            // learns that the queued connection was closed: closing the server only schedules that notification on
            // the client's event loop. Calling both from this thread would let the event loop run the server's
            // close, and so the notification, before the client's close is submitted.
            Channel client = cf.channel();
            ChannelFuture closeFuture = sc.eventLoop().submit(() -> {
                sc.close();
                return client.close();
            }).get(5, SECONDS);

            assertTrue(closeFuture.await(5, SECONDS));
            assertTrue(closeFuture.isSuccess(), () -> String.valueOf(closeFuture.cause()));
            assertTrue(cf.isDone());
            assertInstanceOf(ClosedChannelException.class, cf.cause());
        } finally {
            closeQuietly(cf);
            closeChannel(sc);
        }
    }

