public static void registerEventListeners() {
        for (var modContainer : ModList.get().getSortedMods()) {
            var modBus = modContainer.getEventBus();
            if (modBus != null) {
                modBus.addListener(ModConfigEvent.Reloading.class, event -> {
                    var config = event.getConfig();
                    if (config.getType() != ModConfig.Type.SYNCED) {
                        return;
                    }
                    var loadedConfig = config.getLoadedConfig();
                    if (loadedConfig == null) {
                        return;
                    }

                    var configFormat = loadedConfig.config().configFormat();
                    if (configFormat.isInMemory()) {
                        return; // An in-memory format indicates that we received this config from a server and shouldn't try to sync it
                    }

                    // Write config bytes and queue for syncing to all connected players.
                    var bytes = configFormat.createWriter().writeToString(loadedConfig.config()).getBytes(StandardCharsets.UTF_8);
                    synchronized (lock) {
                        for (var toSync : configsToSync.values()) {
                            toSync.put(config.getFileName(), bytes);
                        }
                    }
                });
            }
        }
    }

@Nullable
    RuntimeException processRootCommitQueue(@Nullable RuntimeException closeException) {
        if (processingRootCommitQueue) {
            // onRootCommit callbacks can trigger more transactions, which will trigger more onRootCommit callbacks.
            // When this happens, the additional callbacks are added to the back of the queue of the transaction manager,
            // such that they are eventually processed.
            // The queue is already being processed higher up the call stack.
            // Let control resume to queue processing of the "true" root transaction.
            return closeException;
        }

        processingRootCommitQueue = true;

        // Invoke root close callbacks
        while (!rootCommitQueue.isEmpty()) {
            SnapshotJournal<?> journal = rootCommitQueue.remove();
            try {
                journal.callOnRootCommit();
            } catch (Exception exception) {
                if (closeException == null) {
                    closeException = new RuntimeException("Encountered an exception while invoking a journal's onRootCommit method.", exception);
                } else {
                    closeException.addSuppressed(exception);
                }
            }
        }

        processingRootCommitQueue = false;
        return closeException;
    }

@Override
    public void postBlockTransactionApplication(
        final T context, final BlockChange blockChange,
        final BlockTransactionReceipt receipt
    ) {
        // If we do not have a notifier at this point then there is no need to attempt to retrieve one from the chunk
        context.applyNotifierIfAvailable(user -> {
            final SpongeBlockSnapshot original = (SpongeBlockSnapshot) receipt.originalBlock();
            final Block block = (Block) original.state().type();
            final BlockPos changedBlockPos = original.getBlockPos();
            original.getServerWorld().ifPresent(worldServer -> {
                final LevelChunkBridge changedMixinChunk = (LevelChunkBridge) worldServer.getChunkAt(changedBlockPos);
                changedMixinChunk.bridge$addTrackedBlockPosition(block, changedBlockPos, user, PlayerTracker.Type.NOTIFIER);
                // and check for owner, if it's available, only if the block change was placement
                // We don't want to set owners on modify because that would mean the current context owner
                // would be setting itself onto potentially other owner's blocks, which since it is a modification, it's considered a
                // notification for a block change so to speak (this is how you can avoid blocks changing colors and being re-branded for
                // ownership to whoever triggered some redstone devices that caused a color change). Only block placements will be considered
                // to have new owners, which we can gather from the context.
                if (blockChange == BlockChange.PLACE) {
                    context.applyOwnerIfAvailable(owner -> {
                        // We can do this when we check for notifiers because owners will always have a notifier set
                        // if not, well, file a bug report and find out the corner case that owners are set but not notifiers with block changes.
                        changedMixinChunk.bridge$addTrackedBlockPosition(block, changedBlockPos, owner, PlayerTracker.Type.CREATOR);
                    });
                }
            });

        });
    }

private long allocateRun(int runSize) {
        int pages = runSize >> pageShifts;
        int pageIdx = arena.sizeClass.pages2pageIdx(pages);

        runsAvailLock.lock();
        try {
            //find first queue which has at least one big enough run
            int queueIdx = runFirstBestFit(pageIdx);
            if (queueIdx == -1) {
                return -1;
            }

            //get run with min offset in this queue
            IntPriorityQueue queue = runsAvail[queueIdx];
            long handle = queue.poll();
            assert handle != IntPriorityQueue.NO_VALUE;
            handle <<= BITMAP_IDX_BIT_LENGTH;
            assert !isUsed(handle) : "invalid handle: " + handle;

            removeAvailRun0(handle);

            handle = splitLargeRun(handle, pages);

            int pinnedSize = runSize(pageShifts, handle);
            freeBytes -= pinnedSize;
            return handle;
        } finally {
            runsAvailLock.unlock();
        }
    }

private boolean handlePendingChannelActive(QuicheQuicConnection conn) {
            if (conn.isFreed() || state == ChannelState.CLOSED) {
                return true;
            }
            if (server) {
                if (state == ChannelState.OPEN && Quiche.quiche_conn_is_established(conn.address())) {
                    // We didn't notify before about channelActive... Update state and fire the event.
                    state = ChannelState.ACTIVE;

                    fireDatagramExtensionEvent(conn);
                    pipeline().fireChannelActive();
                    notifyAboutHandshakeCompletionIfNeeded(conn, null);
                }
            } else if (connectPromise != null && Quiche.quiche_conn_is_established(conn.address())) {
                ChannelPromise promise = connectPromise;
                connectPromise = null;
                state = ChannelState.ACTIVE;

                boolean promiseSet = promise.trySuccess();
                fireDatagramExtensionEvent(conn);
                pipeline().fireChannelActive();
                notifyAboutHandshakeCompletionIfNeeded(conn, null);
                if (!promiseSet) {
                    fireConnectCloseEventIfNeeded(conn);
                    this.close(this.voidPromise());
                    return true;
                }
            }
            return false;
        }

@Override
    public void handlerRemoved(ChannelHandlerContext ctx) {
        try {
            // Use a copy of the array as closing the channel may cause an unwritable event that could also
            // remove channels.
            for (QuicheQuicChannel ch : channels.toArray(new QuicheQuicChannel[0])) {
                ch.forceClose();
            }
            if (pendingPackets > 0) {
                flushNow(ctx);
            }
        } finally {
            channels.clear();
            connectionIdToChannel.clear();
            needsFireChannelReadComplete.clear();
            delayedRemoval.clear();

            config.free();
            if (senderSockaddrMemory != null) {
                senderSockaddrMemory.release();
            }
            if (recipientSockaddrMemory != null) {
                recipientSockaddrMemory.release();
            }
            if (headerParser != null) {
                headerParser.close();
                headerParser = null;
            }
        }
    }

@Override
    protected void decode(ChannelHandlerContext ctx, HttpRequest msg, List<Object> out) throws Exception {
        if (maxPipelineDepth <= acceptEncodingQueue.size()) {
            throw new IllegalStateException("maxPipelineDepth exceeded: " + maxPipelineDepth);
        }
        CharSequence acceptEncoding;
        List<String> acceptEncodingHeaders = msg.headers().getAll(ACCEPT_ENCODING);
        switch (acceptEncodingHeaders.size()) {
        case 0:
            acceptEncoding = HttpContentDecoder.IDENTITY;
            break;
        case 1:
            acceptEncoding = acceptEncodingHeaders.get(0);
            break;
        default:
            // Multiple message-header fields https://www.w3.org/Protocols/rfc2616/rfc2616-sec4.html#sec4.2
            acceptEncoding = StringUtil.join(",", acceptEncodingHeaders);
            break;
        }

        HttpMethod method = msg.method();
        if (HttpMethod.HEAD.equals(method)) {
            acceptEncoding = ZERO_LENGTH_HEAD;
        } else if (HttpMethod.CONNECT.equals(method)) {
            acceptEncoding = ZERO_LENGTH_CONNECT;
        }

        acceptEncodingQueue.add(acceptEncoding);
        out.add(ReferenceCountUtil.retain(msg));
    }

private static EmbeddedChannel createStallingServer(
            long forceCloseTimeoutMillis, final Queue<ChannelPromise> stalledWrites) throws Exception {
        WebSocketServerProtocolConfig serverConfig = WebSocketServerProtocolConfig.newBuilder()
                .websocketPath("/test")
                .dropPongFrames(false)
                .forceCloseTimeoutMillis(forceCloseTimeoutMillis)
                .build();
        EmbeddedChannel ch = new EmbeddedChannel(false, false,
                new ChannelOutboundHandlerAdapter() {
                    private boolean handshakeResponseSent;

                    @Override
                    public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                        if (msg instanceof ByteBuf && handshakeResponseSent) {
                            // Simulate a peer that stopped draining its socket receive buffer: the
                            // close-frame echo write never completes on its own.
                            ReferenceCountUtil.release(msg);
                            stalledWrites.add(promise);
                            return;
                        }
                        handshakeResponseSent = true;
                        ctx.write(msg, promise);
                    }
                },
                new HttpServerCodec(),
                new HttpObjectAggregator(8192),
                new WebSocketServerProtocolHandler(serverConfig));
        ch.register();
        return ch;
    }

