    public void testSingleThreadEventExecutorAddTask() throws Exception {
        TestLinkedBlockingQueue<Runnable> taskQueue = new TestLinkedBlockingQueue<>();
        SingleThreadEventExecutor executor =
                new SingleThreadEventExecutor(null, new DefaultThreadFactory("test"), true) {
                    @Override
                    protected Queue<Runnable> newTaskQueue(int maxPendingTasks) {
                        return taskQueue;
                    }

                    @Override
                    protected void run() {
                        while (!confirmShutdown()) {
                            Runnable task = takeTask();
                            if (task != null) {
                                task.run();
                            }
                        }
                    }
                };
        taskQueue.emulateContention();
        CountDownLatch latch = new CountDownLatch(1);
        executor.submit(() -> {
            executor.execute(() -> { }); // calls addTask
            latch.countDown();
        });
        taskQueue.waitUntilContented();
        taskQueue.removeContention();
        latch.await();
    }

private void handleSlowPath(int res, int flags, long udata, ByteBuffer extraCqeData) {
        long sequence = PendingOpMap.tokenSequence(udata);
        int slot = pendingOps.findSlot(udata);
        if (slot != -1) {
            int registrationId = pendingOps.registrationId(slot);
            DefaultIoUringIoRegistration registration = registrations.get(registrationId);
            byte op = pendingOps.op(slot);
            long userData = pendingOps.userData(slot);

            // Recycle if this completion is terminal (no more CQEs expected for this SQE).
            if ((flags & Native.IORING_CQE_F_MORE) == 0) {
                pendingOps.release(slot);
            }

            // Resolve slow-path completions through the live registration table to align with the fast path.
            if (registration != null) {
                traceCompletion(registration, registrationId, op, res);
                registration.handle(res, flags, op, userData, extraCqeData);
                return;
            }
            if (logger.isDebugEnabled()) {
                logger.debug("ignoring slow-path completion for missing registration (registrationId={}, seq={}, "
                                + "op={}, userData={}, res={})",
                        registrationId, sequence, Native.opToStr(op), userData, res);
            }
            return;
        }
        if (logger.isDebugEnabled()) {
            logger.debug("ignoring slow-path completion for unknown sequence (seq={}, res={})", sequence, res);
        }
    }

@Override
    @SuppressWarnings("deprecation")
    public <T> boolean setOption(ChannelOption<T> option, T value) {
        validate(option, value);

        if (option == SO_BROADCAST) {
            setBroadcast((Boolean) value);
        } else if (option == SO_RCVBUF) {
            setReceiveBufferSize((Integer) value);
        } else if (option == SO_SNDBUF) {
            setSendBufferSize((Integer) value);
        } else if (option == SO_REUSEADDR) {
            setReuseAddress((Boolean) value);
        } else if (option == IP_MULTICAST_LOOP_DISABLED) {
            setLoopbackModeDisabled((Boolean) value);
        } else if (option == IP_MULTICAST_ADDR) {
            setInterface((InetAddress) value);
        } else if (option == IP_MULTICAST_IF) {
            setNetworkInterface((NetworkInterface) value);
        } else if (option == IP_MULTICAST_TTL) {
            setTimeToLive((Integer) value);
        } else if (option == IP_TOS) {
            setTrafficClass((Integer) value);
        } else if (option == DATAGRAM_CHANNEL_ACTIVE_ON_REGISTRATION) {
            setActiveOnOpen((Boolean) value);
        } else {
            return super.setOption(option, value);
        }

        return true;
    }

@Test
    public void testRemoveAndWriteAllReentrantWrite() {
        EmbeddedChannel channel = new EmbeddedChannel(new ChannelOutboundHandlerAdapter() {
            @Override
            public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                // Convert to writeAndFlush(...) so the promise will be notified by the transport.
                ctx.writeAndFlush(msg, promise);
            }
        }, new ChannelOutboundHandlerAdapter());

        final PendingWriteQueue queue = new PendingWriteQueue(channel.pipeline().lastContext());

        ChannelPromise promise = channel.newPromise();
        final ChannelPromise promise3 = channel.newPromise();
        promise.addListener(future -> queue.add(3L, promise3));
        queue.add(1L, promise);
        ChannelPromise promise2 = channel.newPromise();
        queue.add(2L, promise2);
        queue.removeAndWriteAll();

        assertTrue(promise.isDone());
        assertTrue(promise.isSuccess());
        assertTrue(promise2.isDone());
        assertTrue(promise2.isSuccess());
        assertTrue(promise3.isDone());
        assertTrue(promise3.isSuccess());
        assertTrue(channel.finish());
        assertEquals(1L, (Long) channel.readOutbound());
        assertEquals(2L, (Long) channel.readOutbound());
        assertEquals(3L, (Long) channel.readOutbound());
    }

@Test
    public void testTooManyClientChannels() throws Exception {
        EventLoopGroup g = new OioEventLoopGroup(1);
        ServerBootstrap sb = new ServerBootstrap();
        sb.channel(OioServerSocketChannel.class);
        sb.group(g);
        sb.childHandler(new ChannelInboundHandlerAdapter());
        ChannelFuture f1 = sb.bind(0);
        f1.sync();

        Bootstrap cb = new Bootstrap();
        cb.channel(OioSocketChannel.class);
        cb.group(g);
        cb.handler(new ChannelInboundHandlerAdapter());
        ChannelFuture f2 = cb.connect(NetUtil.LOCALHOST, ((InetSocketAddress) f1.channel().localAddress()).getPort());
        f2.await();

        assertInstanceOf(ChannelException.class, f2.cause());
        assertThat(f2.cause().getMessage().toLowerCase()).contains("too many channels");

        final CountDownLatch notified = new CountDownLatch(1);
        f2.addListener(new ChannelFutureListener() {
            @Override
            public void operationComplete(ChannelFuture future) throws Exception {
                notified.countDown();
            }
        });

        notified.await();
        g.shutdownGracefully();
    }

@Override
	public void fabric_readAttachmentsFromNbt(ValueInput input) {
		if (DataAccessorHandler.APPLYING_DATA_CHANGE.isBound()) {
			// DataAccessorHandler handles applying data changes separately.
			return;
		}

		// Note on player targets: no syncing can happen here as the networkHandler is still null
		// Instead it is done on player join (see AttachmentSync)
		IdentityHashMap<AttachmentType<?>, Object> fromNbt = AttachmentSerializingImpl.deserializeAttachmentData(input);

		// If the NBT is devoid of data attachments, treat it as a no-op, rather than wiping them out.
		// Any changes to data attachments (including removals) post-load are done independently of this
		// code path, so we don't need to blindly overwrite it every time if Vanilla MC sends updates
		// (i.e. block entity updates) sans data attachments. See https://github.com/FabricMC/fabric/issues/4638
		if (fromNbt == null) {
			return;
		}

		this.dataAttachments = fromNbt;

		if (this.fabric_shouldTryToSync() && this.dataAttachments != null) {
			this.dataAttachments.forEach((type, value) -> {
				if (type.isSynced()) {
					acknowledgeSynced(type, value);
				}
			});

			// Avoid unnecessary extra syncing after initial sync
			fabric_clearDeferredSyncChanges();
		}
	}

@Unique
	private void acknowledgeSyncedEntry(AttachmentType<?> type, @Nullable AttachmentChange change) {
		if (change == null) {
			if (syncedAttachments == null) {
				return;
			}

			syncedAttachments.remove(type);

			if (fabric_shouldDeferSync()) {
				if (deferredSyncedAttachments == null) {
					deferredSyncedAttachments = Collections.newSetFromMap(new IdentityHashMap<>());
				}

				deferredSyncedAttachments.add(type);
			}
		} else {
			if (syncedAttachments == null) {
				syncedAttachments = new IdentityHashMap<>();
			}

			syncedAttachments.put(type, change);

			if (fabric_shouldDeferSync()) {
				if (deferredSyncedAttachments == null) {
					deferredSyncedAttachments = Collections.newSetFromMap(new IdentityHashMap<>());
				}

				deferredSyncedAttachments.add(type);
			}
		}
	}

@Override
	public void fabric_sendAndClearDeferredSyncChanges(List<ServerPlayer> players) {
		if (syncedAttachments == null || deferredSyncedAttachments == null || deferredSyncedAttachments.isEmpty()) {
			return;
		}

		List<AttachmentChange> deferredChanges = deferredSyncedAttachments.stream().map(type -> {
			AttachmentChange change = syncedAttachments.get(type);

			if (change == null) { // attachment was removed
				change = new AttachmentChange(fabric_getSyncTargetInfo(), type, null);
			}

			return change;
		}).toList();

		for (ServerPlayer player : players) {
			List<AttachmentChange> syncableChanges = new ArrayList<>();

			for (AttachmentChange change : deferredChanges) {
				if (((AttachmentTypeImpl<?>) change.type()).syncPredicate().test(this, player)) {
					syncableChanges.add(change);
				}
			}

			if (!syncableChanges.isEmpty()) {
				AttachmentSync.trySync(syncableChanges, player);
			}
		}

		deferredSyncedAttachments.clear();
	}

public static ParticleEffectSpawner gluttonyRing(Vec3 center, WorldParticleBuilder builder, float distance, int count, float lifetimeScalar) {
        return new ParticleEffectSpawner(builder, b -> {
            Level level = Minecraft.getInstance().level;
            long gameTime = level.getGameTime();
            var random = level.random;
            for (int i = 0; i < count; i++) {
                Vec3 offsetPosition = VecHelper.rotatingRadialOffset(center, distance, i, count, gameTime, 320);
                for (int j = 0; j < 3; j++) {
                    boolean isAdditive = j == 0;
                    Color bright = j < 2 ? GLUTTONY_GREEN : GLUTTONY_DARK;
                    Color dark = j < 2 ? GLUTTONY_GREEN : GLUTTONY_SHADE;
                    float alphaMultiplier = isAdditive ? 1.5f : 3f;
                    float scaleMultiplier = (isAdditive ? 1.25f : 2.5f) * Easing.SINE_IN_OUT.asWeighedRandom(random, 0.8f, 1.2f);
                    float lengthMultiplier = (isAdditive ? 0.75f : 1.25f) * Easing.SINE_IN_OUT.asWeighedRandom(random, 0.8f, 1.2f);;
                    float colorCoefficient = isAdditive ? 1f : 1.75f;
                    var renderType = isAdditive ? LodestoneWorldParticleRenderType.ADDITIVE : LodestoneWorldParticleRenderType.LUMITRANSPARENT;
                    var renderTarget = j < 2 ? LodestoneRenderingSystem.LATE_DEFERRED_RENDER : LodestoneRenderingSystem.DEFERRED_RENDER;
                    builder
                            .modifyLengthData(d -> d.copy().multiplyValue(lengthMultiplier))
                            .modifyTransparencyData(d -> d.copy().multiplyValue(alphaMultiplier))
                            .modifyScaleData(d -> d.copy().multiplyValue(scaleMultiplier))
                            .setColorData(ColorParticleData.create(bright, dark).setCoefficient(colorCoefficient).build())
                            .setLifetime((int) (Easing.SINE_IN_OUT.asWeighedRandom(random, 30, 60) * lifetimeScalar))
                            .setMotion(0, 0.001f, 0)
                            .setRenderTarget(renderTarget)
                            .setRenderType(renderType)
                            .enableNoClip()
                            .spawn(level, offsetPosition.x, offsetPosition.y, offsetPosition.z);
                }
            }
        });
    }

public static void runewoodObeliskParticles(RunewoodObeliskBlockEntity obelisk, SpiritAltarBlockEntity altar, SpiritArcanaType spiritType) {
        var level = obelisk.getLevel();
        var obeliskPos = obelisk.getBlockPos();
        var startPos = obelisk.getParticleOffset().add(obeliskPos.getX(), obeliskPos.getY(), obeliskPos.getZ());
        spiritLightSpecs(level, startPos, spiritType).spawnParticles();
        if (level.getGameTime() % 2L == 0) {
            var random = level.random;
            long gameTime = level.getGameTime();
            var targetPos = getItemPos(altar);
            var direction = targetPos.subtract(startPos).normalize();
            var velocity = direction.scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.01f, 0.02f));
            double yOffset = Math.sin((gameTime*0.2f) % 6.28f) * 0.1f;
            var offsetPosition = VecHelper.rotatingRadialOffset(startPos.add(0, yOffset, 0), 0.45f, 0, 1, gameTime, 30);
            Consumer<WorldParticleBuilder> behavior = b -> b.addTickActor(p -> {
                if (gameTime % 6L == 0) {
                    p.setParticleSpeed(p.getParticleSpeed().scale(1.05f));
                }
            });
            var lightSpecs = spiritLightSpecs(level, offsetPosition, spiritType);
            lightSpecs.getBuilder()
                    .act(behavior)
                    .setMotion(velocity)
                    .multiplyLifetime(2f)
                    .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 2f)));
            lightSpecs.getBloomBuilder()
                    .act(behavior)
                    .setMotion(velocity)
                    .multiplyLifetime(1.5f)
                    .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 1.5f)));
            lightSpecs.spawnParticles();
        }
    }

@Test
    public void testForwardPendingData() {
        ByteToMessageCodec<Integer> codec = new ByteToMessageCodec<Integer>() {
            @Override
            protected void encode(ChannelHandlerContext ctx, Integer msg, ByteBuf out) {
                out.writeInt(msg);
            }

            @Override
            protected void decode(ChannelHandlerContext ctx, ByteBuf in, List<Object> out) {
                if (in.readableBytes() >= 4) {
                    out.add(in.readInt());
                }
            }
        };

        ByteBuf buffer = Unpooled.buffer();
        buffer.writeInt(1);
        buffer.writeByte('0');

        EmbeddedChannel ch = new EmbeddedChannel(codec);
        assertTrue(ch.writeInbound(buffer));
        ch.pipeline().remove(codec);
        assertTrue(ch.finish());
        assertEquals(1, (Integer) ch.readInbound());

        ByteBuf buf = ch.readInbound();
        assertEquals(Unpooled.wrappedBuffer(new byte[]{'0'}), buf);
        buf.release();
        assertNull(ch.readInbound());
        assertNull(ch.readOutbound());
    }

private boolean enqueueMethod(HttpMethod method) {
        Queue<Byte> overflowQueue = methodOverflowQueue;
        int currentDepth = methodQueueSize + (overflowQueue != null ? overflowQueue.size() : 0);
        if (currentDepth >= maxPipelineDepth) {
            return false;
        }

        final byte flag;
        if (HttpMethod.HEAD.equals(method)) {
            flag = METHOD_FLAG_HEAD;
        } else if (HttpMethod.CONNECT.equals(method)) {
            flag = METHOD_FLAG_CONNECT;
        } else {
            flag = METHOD_FLAG_OTHER;
        }

        // Once we have overflow, always append there until it drains completely.
        if (overflowQueue != null) {
            overflowQueue.add(flag);
            return true;
        }

        if (methodQueueSize < INLINE_QUEUE_CAPACITY) {
            methodQueue |= (long) flag << (methodQueueSize << 1);
            methodQueueSize++;
        } else {
            overflowQueue = new ArrayDeque<>(4);
            overflowQueue.add(flag);
            methodOverflowQueue = overflowQueue;
        }
        return true;
    }

@Test
    public void testResponseContentLength1() {
        // case 1: test that ContentDecompressor either sets the correct Content-Length header
        // or removes it completely (handlers down the chain must rely on LastHttpContent object)

        // force content to be in more than one chunk (5 bytes/chunk)
        HttpResponseDecoder decoder = new HttpResponseDecoder(4096, 4096, 5);
        HttpContentDecoder decompressor = new HttpContentDecompressor(0);
        EmbeddedChannel channel = new EmbeddedChannel(decoder, decompressor);
        String headers = "HTTP/1.1 200 OK\r\n" +
                         "Content-Length: " + GZ_HELLO_WORLD.length + "\r\n" +
                         "Content-Encoding: gzip\r\n" +
                         "\r\n";
        ByteBuf buf = Unpooled.copiedBuffer(headers.getBytes(CharsetUtil.US_ASCII), GZ_HELLO_WORLD);
        assertTrue(channel.writeInbound(buf));

        Queue<Object> resp = channel.inboundMessages();
        assertTrue(resp.size() >= 1);
        Object o = resp.peek();
        assertInstanceOf(HttpResponse.class, o);
        HttpResponse r = (HttpResponse) o;

        assertFalse(r.headers().contains(HttpHeaderNames.CONTENT_LENGTH), "Content-Length header not removed.");

        String transferEncoding = r.headers().get(HttpHeaderNames.TRANSFER_ENCODING);
        assertNotNull(transferEncoding, "Content-length as well as transfer-encoding not set.");
        assertEquals(HttpHeaderValues.CHUNKED.toString(), transferEncoding, "Unexpected transfer-encoding value.");

        assertHasInboundMessages(channel, true);
        assertHasOutboundMessages(channel, false);
        assertFalse(channel.finish());
    }

@Test
    public void initialWindowUpdateShouldSendEmptyFrame() throws Http2Exception {
        controller.initialWindowSize(0);
        assertWritabilityChanged(1, false);
        reset(listener);

        // First send a frame that will get buffered.
        FakeFlowControlled data = new FakeFlowControlled(10, false);
        sendData(STREAM_A, data);
        controller.writePendingBytes();
        data.assertNotWritten();

        // Now send an empty frame on the same stream and verify that it's also buffered.
        FakeFlowControlled data2 = new FakeFlowControlled(0, false);
        sendData(STREAM_A, data2);
        controller.writePendingBytes();
        data2.assertNotWritten();

        // Re-expand the window and verify that both frames were sent.
        controller.initialWindowSize(10);
        verify(listener, never()).writabilityChanged(stream(STREAM_A));
        verify(listener, times(1)).writabilityChanged(stream(STREAM_B));
        verify(listener, times(1)).writabilityChanged(stream(STREAM_C));
        verify(listener, times(1)).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));

        data.assertFullyWritten();
        data2.assertFullyWritten();
    }

@Test
    public void nonWritableChannelDoesNotAttemptToWrite() throws Exception {
        // Start the channel as not writable and exercise the public methods of the flow controller
        // making sure no frames are written.
        setChannelWritability(false);
        assertWritabilityChanged(1, false);
        reset(listener);
        FakeFlowControlled dataA = new FakeFlowControlled(1);
        FakeFlowControlled dataB = new FakeFlowControlled(1);
        final Http2Stream stream = stream(STREAM_A);

        controller.addFlowControlled(stream, dataA);
        controller.writePendingBytes();
        dataA.assertNotWritten();

        controller.incrementWindowSize(stream, 100);
        controller.writePendingBytes();
        dataA.assertNotWritten();

        controller.addFlowControlled(stream, dataB);
        controller.writePendingBytes();
        dataA.assertNotWritten();
        dataB.assertNotWritten();
        assertWritabilityChanged(0, false);

        // Now change the channel to writable and make sure frames are written.
        setChannelWritability(true);
        assertWritabilityChanged(1, true);
        controller.writePendingBytes();
        dataA.assertFullyWritten();
        dataB.assertFullyWritten();
    }

@ParameterizedTest
    @ValueSource(longs = { 30000, -1 })
    public void gracefulShutdownCompletesWhenGoAwayClosesLastStream(long gracefulShutdownTimeoutMillis) {
        Http2ConnectionHandler serverHandler = new Http2ConnectionHandlerBuilder()
                .server(true).frameListener(new Http2FrameAdapter()).build();
        EmbeddedChannel server = new EmbeddedChannel(serverHandler);
        EmbeddedChannel client = newClientChannel(gracefulShutdownTimeoutMillis);
        Http2ConnectionHandler clientHandler = client.pipeline().get(Http2ConnectionHandler.class);
        try {
            exchangeFrames(client, server);
            writeHeadersOnStream3(clientHandler, client);

            // Close via the pipeline: EmbeddedChannel.close() would cancel the graceful shutdown timeout task.
            ChannelFuture closeFuture = client.pipeline().close();
            assertFalse(closeFuture.isDone());

            // The server shuts down before it has seen stream 3 and answers with a GOAWAY that does not include it.
            client.releaseOutbound();
            serverHandler.goAway(server.pipeline().firstContext(), 0, Http2Error.NO_ERROR.code(),
                    Unpooled.EMPTY_BUFFER, server.newPromise());
            server.flush();
            exchangeFrames(server, client);
            client.runPendingTasks();

            assertEquals(0, clientHandler.connection().numActiveStreams());
            assertTrue(closeFuture.isSuccess(), "close() must complete once the GOAWAY closed the last stream");
            assertFalse(client.isOpen());
        } finally {
            client.finishAndReleaseAll();
            server.finishAndReleaseAll();
        }
    }

