private ChannelFuture doBind(final SocketAddress localAddress) {
        final ChannelFuture regFuture = initAndRegister();
        final Channel channel = regFuture.channel();
        if (regFuture.cause() != null) {
            return regFuture;
        }

        if (regFuture.isDone()) {
            // At this point we know that the registration was complete and successful.
            ChannelPromise promise = channel.newPromise();
            doBind0(regFuture, channel, localAddress, promise);
            return promise;
        } else {
            // Registration future is almost always fulfilled already, but just in case it's not.
            final PendingRegistrationPromise promise = new PendingRegistrationPromise(channel);
            regFuture.addListener(future -> {
                Throwable cause = future.cause();
                if (cause != null) {
                    // Registration on the EventLoop failed so fail the ChannelPromise directly to not cause an
                    // IllegalStateException once we try to access the EventLoop of the Channel.
                    promise.setFailure(cause);
                } else {
                    // Registration was successful, so set the correct executor to use.
                    // See https://github.com/netty/netty/issues/2586
                    promise.registered();

                    doBind0(regFuture, channel, localAddress, promise);
                }
            });
            return promise;
        }
    }

@Override
    protected void doBeginRead() throws Exception {
        if (readInProgress) {
            return;
        }

        Queue<Object> inboundBuffer = this.inboundBuffer;
        if (inboundBuffer.isEmpty()) {
            readInProgress = true;
            return;
        }

        final InternalThreadLocalMap threadLocals = InternalThreadLocalMap.get();
        final int stackDepth = threadLocals.localChannelReaderStackDepth();
        if (stackDepth < MAX_READER_STACK_DEPTH) {
            threadLocals.setLocalChannelReaderStackDepth(stackDepth + 1);
            try {
                readInbound();
            } finally {
                threadLocals.setLocalChannelReaderStackDepth(stackDepth);
            }
        } else {
            try {
                eventLoop().execute(readTask);
            } catch (Throwable cause) {
                logger.warn("Closing Local channels {}-{} because exception occurred!", this, peer, cause);
                close();
                peer.close();
                PlatformDependent.throwException(cause);
            }
        }
    }

private Future<Void> close0() {
        assert executor.inEventLoop();

        if (!closed) {
            closed = true;
            for (;;) {
                AcquireTask task = pendingAcquireQueue.poll();
                if (task == null) {
                    break;
                }
                ScheduledFuture<?> f = task.timeoutFuture;
                if (f != null) {
                    f.cancel(false);
                }
                task.promise.setFailure(new ClosedChannelException());
            }
            acquiredChannelCount.set(0);
            pendingAcquireCount = 0;

            // Ensure we dispatch this on another Thread as close0 will be called from the EventExecutor and we need
            // to ensure we will not block in a EventExecutor.
            return GlobalEventExecutor.INSTANCE.submit(new Callable<Void>() {
                @Override
                public Void call() throws Exception {
                    FixedChannelPool.super.close();
                    return null;
                }
            });
        }

        return GlobalEventExecutor.INSTANCE.newSucceededFuture(null);
    }

@Test
    @Timeout(30)
    public void testScalingWithIoRegistrationLifecycle() throws InterruptedException {
        TestMultiThreadIoEventLoopGroup group = new TestMultiThreadIoEventLoopGroup(0, 2, 200, TimeUnit.MILLISECONDS);
        try {
            startAllExecutors(group);
            assertEquals(2, countActiveExecutors(group));

            waitForSuspension(group, 1, 2000);
            assertEquals(1, countActiveExecutors(group), "One executor should have been suspended");

            TestableIoEventLoop activeExecutor = (TestableIoEventLoop) findActiveExecutor(group);
            assertNotNull(activeExecutor, "One executor should remain active");

            IoRegistration registration = activeExecutor.register(new TestIoHandle()).syncUninterruptibly().getNow();
            activeExecutor.setSimulateWorkload(true);

            Thread.sleep(450);

            // The executor will not be suspended because its workload generates utilization.
            assertFalse(activeExecutor.isSuspended(), "Executor with active handle should not be suspended");

            activeExecutor.setSimulateWorkload(false);
            assertTrue(registration.cancel());

            waitForSuspension(group, 2, 2000);
            assertTrue(activeExecutor.isSuspended(),
                       "Executor should suspend after handle is cancelled and idle");
        } finally {
            group.shutdownGracefully().syncUninterruptibly();
        }
    }

@Override
	protected void onFinalCommit() {
		// Apply pending action
		if (pendingAction.extractBonemeal) {
			// Mimic ComposterBlock#emptyComposter logic.
			BlockState newState = location.getBlockState().setValue(ComposterBlock.LEVEL, 0);
			location.setBlockState(newState);
			location.level.gameEvent(GameEvent.BLOCK_CHANGE, location.pos, GameEvent.Context.of(newState));
			// Play the sound
			location.level.playSound(null, location.pos, SoundEvents.COMPOSTER_EMPTY, SoundSource.BLOCKS, 1.0F, 1.0F);
		} else if (pendingAction.compostProvider != null && location.level instanceof ServerLevel serverLevel) {
			BlockState state = location.getBlockState();
			int layersToAdd = getLayersToAdd(serverLevel, location.pos, state, pendingAction.compostProvider);
			boolean increaseSuccessful = layersToAdd > 0;

			if (increaseSuccessful) {
				// Mimic ComposterBlock#addToComposter logic.
				int newLevel = Mth.clamp(state.getValue(ComposterBlock.LEVEL) + layersToAdd, 0, 7);
				BlockState newState = state.setValue(ComposterBlock.LEVEL, newLevel);
				location.setBlockState(newState);
				location.level.gameEvent(GameEvent.BLOCK_CHANGE, location.pos, GameEvent.Context.of(newState));

				if (newLevel == 7) {
					location.level.scheduleTick(location.pos, state.getBlock(), 20);
				}
			}

			location.level.levelEvent(LevelEvent.COMPOSTER_FILL, location.pos, increaseSuccessful ? 1 : 0);
		}

		// Reset after successful commit.
		pendingAction = PendingAction.NONE;
	}

public static void activateEntities(final ServerLevel world) {
        if (((LevelBridge) world).bridge$isFake()) {
            return;
        }

        for (final ServerPlayer player : world.players()) {
            int maxRange = 0;
            for (final Integer range : EntityActivationRange.maxActivationRanges.values()) {
                if (range > maxRange) {
                    maxRange = range;
                }
            }

            maxRange = Math.min((((ServerWorld) world).properties().viewDistance() << 4) - 8, maxRange);
            ((ActivationCapabilityBridge) player).activation$setActivatedTick(SpongeCommon.server().getTickCount());
            final AABB aabb = EntityActivationRange.maxBB;
            EntityActivationRange.growBb(aabb, player.getBoundingBox(), maxRange, 256, maxRange);

            final int i = Mth.floor(aabb.minX / 16.0D);
            final int j = Mth.floor(aabb.maxX / 16.0D);
            final int k = Mth.floor(aabb.minZ / 16.0D);
            final int l = Mth.floor(aabb.maxZ / 16.0D);

            for (int i1 = i; i1 <= j; ++i1) {
                for (int j1 = k; j1 <= l; ++j1) {
                    final LevelChunk chunk = world.getChunkSource().getChunkNow(i1, j1);
                    if (chunk != null) {
                        EntityActivationRange.activateChunkEntities(player, chunk);
                    }
                }
            }
        }
    }

