@Override
    protected void run() {
        assert inEventLoop();
        ioHandler.initialize();
        do {
            final int ioRatio = this.ioRatio;
            final long taskQuantumNs;

            // reset before calling runIo() which is responsible for calling reportActiveIoTime(...).
            activeIoTimeNanos = -1;
            runIo();
            if (ioRatio == 100 || activeIoTimeNanos == -1) {
                taskQuantumNs = maxTaskProcessingQuantumNs;
            } else {
                // Give tasks a budget proportional to the time just spent on IO, still bounded by the
                // configured maximum so a burst of IO activity cannot starve the task queue indefinitely.
                long quantum = Math.min(maxTaskProcessingQuantumNs, activeIoTimeNanos * (100 - ioRatio) / ioRatio);
                if (quantum == 0) {
                    // Ensure we always use a "deadline"
                    taskQuantumNs = maxTaskProcessingQuantumNs;
                } else {
                    taskQuantumNs = quantum;
                }
            }
            if (isShuttingDown()) {
                ioHandler.prepareToDestroy();
            }
            // Now run tasks for the computed amount of time before trying to run IO again.
            runAllTasks(taskQuantumNs);

            // We should continue with our loop until we either confirmed a shutdown or we can suspend it.
        } while (!confirmShutdown() && !canSuspend());
    }

@Override
        public void operationComplete(Future<Channel> future) throws Exception {
            try {
                assert executor.inEventLoop();

                if (closed) {
                    if (future.isSuccess()) {
                        // Since the pool is closed, we have no choice but to close the channel
                        future.getNow().close();
                    }
                    originalPromise.setFailure(new IllegalStateException("FixedChannelPool was closed"));
                    return;
                }

                if (future.isSuccess()) {
                    Channel channel = future.getNow();
                    if (!originalPromise.trySuccess(channel)) {
                        // Promise was completed in the meantime (like cancelled), just release the channel again.
                        release(channel);
                    }
                } else {
                    if (acquired) {
                        decrementAndRunTaskQueue();
                    } else {
                        runTaskQueue();
                    }

                    originalPromise.setFailure(future.cause());
                }
            } catch (Throwable cause) {
                originalPromise.tryFailure(cause);
            }
        }

@Test
    public void testUserDefinedWritability() {
        final StringBuilder buf = new StringBuilder();
        EmbeddedChannel ch = new EmbeddedChannel(new ChannelInboundHandlerAdapter() {
            @Override
            public void channelWritabilityChanged(ChannelHandlerContext ctx) {
                buf.append(ctx.channel().isWritable());
                buf.append(' ');
            }
        });

        ch.config().setWriteBufferLowWaterMark(128);
        ch.config().setWriteBufferHighWaterMark(256);

        ChannelOutboundBuffer cob = ch.unsafe().outboundBuffer();

        // Ensure that the default value of a user-defined writability flag is true.
        for (int i = 1; i <= 30; i ++) {
            assertTrue(cob.getUserDefinedWritability(i));
        }

        // Ensure that setting a user-defined writability flag to false affects channel.isWritable();
        cob.setUserDefinedWritability(1, false);
        ch.runPendingTasks();
        assertEquals("false ", buf.toString());

        // Ensure that setting a user-defined writability flag to true affects channel.isWritable();
        cob.setUserDefinedWritability(1, true);
        ch.runPendingTasks();
        assertEquals("false true ", buf.toString());

        safeClose(ch);
    }

