@Test
    @Timeout(value = 3000, unit = TimeUnit.MILLISECONDS)
    public void testSelectableChannel() throws Exception {
        IoEventLoopGroup group = new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory());
        IoEventLoop loop = group.next();

        try {
            Channel channel = new NioServerSocketChannel();
            loop.register(channel).syncUninterruptibly();
            channel.bind(new InetSocketAddress(0)).syncUninterruptibly();

            SocketChannel selectableChannel = SocketChannel.open();
            selectableChannel.configureBlocking(false);
            selectableChannel.connect(channel.localAddress());

            final CountDownLatch latch = new CountDownLatch(1);

            IoRegistration registration = loop.register(
                            new NioSelectableChannelIoHandle<SocketChannel>(selectableChannel) {
                @Override
                protected void handle(SocketChannel channel, SelectionKey key) {
                    latch.countDown();
                }
            }).get();

            registration.submit(NioIoOps.valueOf(SelectionKey.OP_CONNECT));

            latch.await();

            selectableChannel.close();
            channel.close().syncUninterruptibly();
        } finally {
            group.shutdownGracefully();
        }
    }

private static boolean claim(int[] ret, BitSet data, int claimed, int elements) {
        Queue<Integer> pending = new LinkedList<Integer>();
        pending.add(claimed);

        while (pending.peek() != null) {
            int test = pending.poll();
            int offset = (test + 2) * elements;
            int used = data.nextSetBit(offset) - offset;

            if (used >= elements || used < 0)
                throw new IllegalStateException("What? We matched something, but it wasn't set in the range of this test! Test: " + test +  " Used: " + used);

            data.set(used);
            data.set(elements + test);
            ret[used] = test;

            for (int x = 0; x < elements; x++) {
                offset = (x + 2) * elements;
                if (data.get(offset + used) && !data.get(elements + x)) {
                    data.clear(offset + used);
                    int count = 0;
                    for (int y = offset; y < offset + elements; y++)
                        if (data.get(y))
                            count++;

                    if (count == 0)
                        return false; //Claiming this caused another test to lose its last match..

                    if (count == 1)
                        pending.add(x);
                }
            }
        }

        return true;
    }

private void handleTask(TaskImpl task) {
        TaskSchedule schedule;
        try {
            schedule = task.task().get();
        } catch (Throwable t) {
            MinecraftServer.getExceptionManager().handleException(new RuntimeException("Exception in scheduled task", t));
            schedule = TaskSchedule.stop();
        }

        switch (schedule) {
            case TaskScheduleImpl.DurationSchedule durationSchedule -> {
                final Duration duration = durationSchedule.duration();
                var _ = SCHEDULER.schedule(() -> safeExecute(task), duration.toMillis(), TimeUnit.MILLISECONDS);
            }
            case TaskScheduleImpl.TickSchedule tickSchedule -> {
                synchronized (this) {
                    final int target = tickState + tickSchedule.tick();
                    var targetTaskQueue = switch (task.executionType()) {
                        case TICK_START -> tickStartTaskQueue;
                        case TICK_END -> tickEndTaskQueue;
                    };
                    targetTaskQueue.computeIfAbsent(target, _ -> new ArrayList<>()).add(task);
                }
            }
            case TaskScheduleImpl.FutureSchedule futureSchedule -> {
                var _ = futureSchedule.future().thenRun(() -> safeExecute(task));
            }
            case TaskScheduleImpl.Park _ -> task.parked = true;
            case TaskScheduleImpl.Stop _ -> task.cancel();
            case TaskScheduleImpl.Immediate _ -> {
                if (task.executionType() == ExecutionType.TICK_END) {
                    tickEndTasksToExecute.relaxedOffer(task);
                } else tasksToExecute.relaxedOffer(task);
            }
        }
    }

