public static <T> List<T> topologicalSort(Graph<T> graph, @Nullable Comparator<? super T> comparator) throws IllegalArgumentException {
        Preconditions.checkArgument(graph.isDirected(), "Cannot topologically sort an undirected graph!");
        Preconditions.checkArgument(!graph.allowsSelfLoops(), "Cannot topologically sort a graph with self loops!");

        final Queue<T> queue = comparator == null ? new ArrayDeque<>() : new PriorityQueue<>(comparator);
        final Map<T, Integer> degrees = new HashMap<>();
        final List<T> results = new ArrayList<>();

        for (final T node : graph.nodes()) {
            final int degree = graph.inDegree(node);
            if (degree == 0) {
                queue.add(node);
            } else {
                degrees.put(node, degree);
            }
        }

        while (!queue.isEmpty()) {
            final T current = queue.remove();
            results.add(current);
            for (final T successor : graph.successors(current)) {
                final int updated = degrees.compute(successor, (node, degree) -> Objects.requireNonNull(degree, () -> "Invalid degree present for " + node) - 1);
                if (updated == 0) {
                    queue.add(successor);
                    degrees.remove(successor);
                }
            }
        }

        if (!degrees.isEmpty()) {
            Set<Set<T>> components = new StronglyConnectedComponentDetector<>(graph).getComponents();
            components.removeIf(set -> set.size() < 2);
            throwCyclePresentException(components);
        }

        return results;
    }

public static <T> void writeQueue(NetworkBuffer buffer, MessagePassingQueue<T> queue, int minWrite,
                                      BiPredicate<NetworkBuffer, T> writer) {
        // The goal of this method is to write at the very least `minWrite` packets if the queue permits it.
        // The buffer is resized if it cannot hold this minimum.
        final int size = queue.size();
        minWrite = Math.min(minWrite, size);
        T packet;
        int written = 0;
        while ((packet = queue.peek()) != null) {
            final long index = buffer.writeIndex();
            boolean success;
            try {
                success = writer.test(buffer, packet);
            } catch (IndexOutOfBoundsException _) {
                success = false;
            }
            assert !success || buffer.writeIndex() > 0;
            // Poll the packet only if fully written
            if (success) {
                // Packet fully written
                queue.poll();
                written++;
            } else {
                buffer.writeIndex(index);
                if (written < minWrite) {
                    // Try again with a bigger buffer
                    final long newSize = Math.min(buffer.capacity() * 2, ServerProperties.MAX_PACKET_SIZE.get());
                    if (newSize == buffer.capacity()) break; // We reached the maximum size
                    buffer.resize(newSize);
                } else {
                    // At least one packet has been written
                    // Not worth resizing to fit more, we'll try again next flush
                    break;
                }
            }
        }
    }

private void onGatherData(final GatherDataEvent.Client event) {
        // Example of how to datagen datapack registry objects.
        // Objects to be datagenerated must be registered (e.g. via DeferredRegister above).
        // This outputs to data/data_pack_registries_test/data_pack_registries_test/unsyncable/datagen_test.json
        final DataGenerator generator = event.getGenerator();
        final Path outputFolder = generator.getPackOutput().getOutputFolder();
        final CompletableFuture<HolderLookup.Provider> providerCompletableFuture = event.getReloadableLookupProvider();
        final Gson gson = new GsonBuilder().setPrettyPrinting().create();
        final Identifier registryId = Unsyncable.REGISTRY_KEY.identifier();
        final Identifier id = this.datagenTestObject.getId();
        final Unsyncable element = new Unsyncable("Datagen Success");
        final String pathString = String.join("/", PackType.SERVER_DATA.getDirectory(), id.getNamespace(), registryId.getNamespace(), registryId.getPath(), id.getPath() + ".json");
        final Path path = outputFolder.resolve(pathString);

        generator.addProvider(true, new DataProvider() {
            @Override
            public CompletableFuture<?> run(final CachedOutput cache) {
                return providerCompletableFuture.thenCompose(provider -> {
                    final RegistryOps<JsonElement> ops = RegistryOps.create(JsonOps.INSTANCE, provider);

                    Unsyncable.DIRECT_CODEC.encodeStart(ops, element)
                            .resultOrPartial(msg -> LOGGER.error("Failed to encode {}: {}", path, msg)) // Log error on encode failure.
                            .ifPresent(json -> // Output to file on encode success.
                    {
                                DataProvider.saveStable(cache, json, path);
                            });

                    return CompletableFuture.allOf();
                });
            }

            @Override
            public String getName() {
                return String.format("%s provider for %s", registryId, MODID);
            }
        });
    }

