                anyChannelPromise());

        assertTrue(parentChannel.outboundMessages().isEmpty());
    }

@Test
    public void testEmptyRead() throws Exception {
        final UpstreamReadCounter upstream = new UpstreamReadCounter();
        final AtomicInteger reads = new AtomicInteger();
        final AtomicInteger readCompletes = new AtomicInteger();
        final EmbeddedChannel channel = new EmbeddedChannel(
                false, false,
                upstream,
                new FlowControlHandler(),
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        reads.incrementAndGet();
                    }

                    @Override
                    public void channelReadComplete(ChannelHandlerContext ctx) {
                        readCompletes.incrementAndGet();
                    }
                });

        channel.config().setAutoRead(false);
        channel.register();

        // Downstream issues a read() but upstream has no data and only fires channelReadComplete.
        // FlowControlHandler must forward that channelReadComplete to satisfy the outstanding read.
        channel.read();
        channel.flushInbound();

        assertEquals(0, reads.get());
        assertEquals(1, readCompletes.get());

        // The empty read() could not be satisfied from the queue, so it was forwarded upstream exactly once.
        assertEquals(1, upstream.reads.get());

        assertFalse(channel.finishAndReleaseAll());
    }

private static EmbeddedChannel initChannel(SslProvider provider, String protocol, final boolean useClientMode,
            final BlockingQueue<Object> eventQueue) throws Exception {

        SelfSignedCertificate ssc = CachedSelfSignedCertificate.getCachedCertificate();
        final SslContext sslContext = (useClientMode
                ? SslContextBuilder.forClient().trustManager(InsecureTrustManagerFactory.INSTANCE)
                : SslContextBuilder.forServer(ssc.certificate(), ssc.privateKey()))
                 .sslProvider(provider)
                 .protocols(protocol)
                .build();
        // use sslContext.newHandler(ALLOC) instead of new SslHandler(sslContext.newEngine(ALLOC)) to create
        // non-JDK compatible OpenSSL engine that can process partial packets:
        SslHandler handler = sslContext.newHandler(ALLOC);
        // handler incremented the reference count and will destroy it when removed
        ReferenceCountUtil.release(sslContext);
        return new EmbeddedChannel(
                handler,
                new SimpleChannelInboundHandler<ByteBuf>() {

                    @Override
                    protected void channelRead0(ChannelHandlerContext ctx, ByteBuf msg) {
                        eventQueue.add(msg.toString(US_ASCII));
                    }

                    @Override
                    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                        eventQueue.add(evt);
                    }

                    @Override
                    public void channelInactive(ChannelHandlerContext ctx) throws Exception {
                        eventQueue.add(INACTIVE);
                        super.channelInactive(ctx);
                    }
                }
        );
    }

@ParameterizedTest
    @EnumSource(CumulationTestScenario.class)
    public void testCumulation(CumulationTestScenario testScenario) {
        EmbeddedChannel channel = new EmbeddedChannel();
        SslHandlerCoalescingBufferQueue queue = new SslHandlerCoalescingBufferQueue(channel, 16, false) {
            @Override
            protected int wrapDataSize() {
                return 128;
            }
        };

        ByteBuf original = testScenario.bufferSupplier.get();
        original.writerIndex(8);
        ByteBuf first = testScenario.bufferWrapper.apply(original);
        first.retain();
        queue.add(first);
        ByteBuf second = Unpooled.copyLong(3);
        queue.add(second);

        ChannelPromise promise = channel.newPromise();
        assertFalse(queue.isEmpty());
        ByteBuf buffer = queue.remove(UnpooledByteBufAllocator.DEFAULT, 128, promise);
        try {
            assertEquals(16, buffer.readableBytes());
            assertEquals(1, buffer.readLong());
            assertEquals(3, buffer.readLong());
        } finally {
            buffer.release();
        }
        assertTrue(queue.isEmpty());
        assertEquals(8, original.writerIndex());
        original.writerIndex(original.capacity());
        assertEquals(2, original.getLong(8));
        first.release();
        assertEquals(0, first.refCnt());
        assertEquals(0, second.refCnt());
    }

