private void close(boolean wasAborted) {
        manager.validateCurrentTransaction(this);
        validateOpen();
        // Block transaction operations
        open = false;

        // Note: it is important that we don't let exceptions corrupt the global state of the transaction manager.
        // That is why every callback has to run inside its own try-with-resources block.
        RuntimeException closeException = null;

        // Invoke callbacks
        for (SnapshotJournal<?> journal : journalsToClose) {
            try {
                journal.onClose(this, wasAborted);
            } catch (Exception exception) {
                if (closeException == null) {
                    closeException = new RuntimeException("Encountered an exception while invoking a transaction close callback.", exception);
                } else {
                    closeException.addSuppressed(exception);
                }
            }
        }

        journalsToClose.clear();

        // After this decrement, transactions can again be opened
        manager.currentDepth--;

        // Root transaction: process all onRootCommit callbacks.
        if (manager.currentDepth == -1) {
            closeException = manager.processRootCommitQueue(closeException);
        }

        // Throw exception if necessary
        if (closeException != null) {
            throw closeException;
        }
    }

@Override
        public void println(@Nullable final String line) {
            final Class<?> clazz = STACK_WALKER.getCallerClass();
            try {
                final JavaPlugin plugin = JavaPlugin.getProvidingPlugin(clazz);

                // Instead of just printing the message, send it to the plugin's logger
                plugin.getLogger().log(this.level, this.prefix + line);

                if (SysoutCatcher.SUPPRESS_NAGS) {
                    return;
                }
                if (SysoutCatcher.NAG_INTERVAL > 0 || SysoutCatcher.NAG_TIMEOUT > 0) {
                    final PluginNag nagRecord = SysoutCatcher.this.nagRecords.computeIfAbsent(plugin.getName(), k -> new PluginNag());
                    final boolean hasTimePassed = SysoutCatcher.NAG_TIMEOUT > 0
                        && (nagRecord.lastNagTimestamp == Long.MIN_VALUE
                        || nagRecord.lastNagTimestamp + SysoutCatcher.NAG_TIMEOUT <= System.nanoTime());
                    final boolean hasMessagesPassed = SysoutCatcher.NAG_INTERVAL > 0
                        && (nagRecord.messagesSinceNag == Long.MIN_VALUE
                        || ++nagRecord.messagesSinceNag >= SysoutCatcher.NAG_INTERVAL);
                    if (!hasMessagesPassed && !hasTimePassed) {
                        return;
                    }
                    nagRecord.lastNagTimestamp = System.nanoTime();
                    nagRecord.messagesSinceNag = 0;
                }
                Bukkit.getLogger().warning(
                    String.format("Nag author(s): '%s' of '%s' about their usage of System.out/err.print. "
                            + "Please use your plugin's logger instead (JavaPlugin#getLogger).",
                        plugin.getPluginMeta().getAuthors(),
                        plugin.getPluginMeta().getDisplayName())
                );
            } catch (final IllegalArgumentException | IllegalStateException e) {
                // If anything happens, the calling class doesn't exist, there is no JavaPlugin that "owns" the calling class, etc
                // Just print out normally, with some added information
                Bukkit.getLogger().log(this.level, String.format("%s[%s] %s", this.prefix, clazz.getName(), line));
            }
        }

@Override
        public CancelledState cancel() {
            for (int curr = this.getStateVolatile();;) {
                switch (curr) {
                    case STATE_IDLE: {
                        if (STATE_IDLE == (curr = this.compareAndExchangeStateVolatile(STATE_IDLE, STATE_CANCELLED))) {
                            this.state = STATE_CANCELLED;
                            this.run = null;
                            return CancelledState.CANCELLED_BY_CALLER;
                        }
                        // try again
                        continue;
                    }
                    case STATE_EXECUTING: {
                        if (!this.isRepeatingTask()) {
                            return CancelledState.RUNNING;
                        }
                        if (STATE_EXECUTING == (curr = this.compareAndExchangeStateVolatile(STATE_EXECUTING, STATE_EXECUTING_CANCELLED))) {
                            return CancelledState.NEXT_RUNS_CANCELLED;
                        }
                        // try again
                        continue;
                    }
                    case STATE_EXECUTING_CANCELLED: {
                        return CancelledState.NEXT_RUNS_CANCELLED_ALREADY;
                    }
                    case STATE_FINISHED: {
                        return CancelledState.ALREADY_EXECUTED;
                    }
                    case STATE_CANCELLED: {
                        return CancelledState.CANCELLED_ALREADY;
                    }
                    default: {
                        throw new IllegalStateException("Unknown state: " + curr);
                    }
                }
            }
        }

