void writeWithoutCheckChannelState(Object msg, ChannelPromise promise) {
            try {
                msg = filterMsg(msg);
            } catch (UnsupportedOperationException e) {
                ReferenceCountUtil.release(msg);
                promise.setFailure(e);
                return;
            }

            boolean wasFinSent = QuicheQuicStreamChannel.this.finSent;
            boolean mayNeedWritabilityUpdate = false;
            try {
                int res = write0(msg);
                if (res > 0) {
                    ReferenceCountUtil.release(msg);
                    promise.setSuccess();
                    mayNeedWritabilityUpdate = capacity == 0;
                } else if (res == 0 || res == Quiche.QUICHE_ERR_DONE) {
                    // Touch the message to make things easier in terms of debugging buffer leaks.
                    ReferenceCountUtil.touch(msg);
                    queue.add(msg, promise);
                    mayNeedWritabilityUpdate = true;
                } else if (res == Quiche.QUICHE_ERR_STREAM_STOPPED) {
                    throw new ChannelOutputShutdownException("STOP_SENDING frame received");
                } else {
                    throw Quiche.convertToException(res);
                }
            } catch (Exception e) {
                ReferenceCountUtil.release(msg);
                promise.setFailure(e);
                mayNeedWritabilityUpdate = capacity == 0;
            } finally {
                if (mayNeedWritabilityUpdate) {
                    updateWritabilityIfNeeded(false);
                }
                closeIfNeeded(wasFinSent);
            }
        }

@Test
    public void testSimultaneousCloseDoesNotLeakOriginalPromise() throws Exception {
        // The application initiates an outbound close (e.g. via ctx.close()) while the peer's own CLOSE
        // frame is concurrently in flight. Both paths call closeSent(): the second call must not silently
        // overwrite (and orphan) the promise the first call already armed a deadline for.
        final long forceCloseTimeoutMillis = 100;
        final Queue<ChannelPromise> stalledWrites = new ArrayDeque<ChannelPromise>();
        EmbeddedChannel client = createClient();
        EmbeddedChannel server = createStallingServer(forceCloseTimeoutMillis, stalledWrites);

        assertFalse(server.writeInbound(client.<ByteBuf>readOutbound()));
        assertFalse(client.writeInbound(server.<ByteBuf>readOutbound()));

        // The application decides to close first.
        ChannelHandlerContext serverCtx = server.pipeline().context(WebSocketServerProtocolHandler.class);
        ChannelPromise applicationClosePromise = serverCtx.newPromise();
        ((WebSocketServerProtocolHandler) serverCtx.handler()).close(serverCtx, applicationClosePromise);

        // Before that echo completes, the peer's own CLOSE frame arrives too.
        assertTrue(client.writeOutbound(new CloseWebSocketFrame(WebSocketCloseStatus.NORMAL_CLOSURE)));
        assertFalse(server.writeInbound(client.<ByteBuf>readOutbound()));

        // We already sent a close frame, so no second close frame must be written in response to the peer's
        // one. A single deadline governs the close handshake.
        assertEquals(1, stalledWrites.size());
        assertTrue(server.isOpen());

        server.advanceTimeBy(forceCloseTimeoutMillis * 2, TimeUnit.MILLISECONDS);
        server.runScheduledPendingTasks();

        assertFalse(server.isOpen());
        // The application's own close promise is not left hanging forever.
        assertTrue(applicationClosePromise.isDone());

        client.close();
        assertFalse(client.finishAndReleaseAll());
        assertFalse(server.finishAndReleaseAll());
    }

@ParameterizedTest
    @ValueSource(longs = { 30000, -1 })
    public void gracefulShutdownClosesChannelWhenSubclassCloseThrows(long gracefulShutdownTimeoutMillis) {
        Http2ConnectionHandler serverHandler = new Http2ConnectionHandlerBuilder()
                .server(true).frameListener(new Http2FrameAdapter()).build();
        EmbeddedChannel server = new EmbeddedChannel(serverHandler);
        CloseFailingHandler clientHandler = new CloseFailingHandlerBuilder()
                .server(false).frameListener(new Http2FrameAdapter())
                .gracefulShutdownTimeoutMillis(gracefulShutdownTimeoutMillis).build();
        EmbeddedChannel client = new EmbeddedChannel(clientHandler);
        // The graceful shutdown timeout must not elapse during the test.
        client.freezeTime();
        try {
            exchangeFrames(client, server);
            writeHeadersOnStream3(clientHandler, client);

            // Close via the pipeline: EmbeddedChannel.close() would cancel the graceful shutdown timeout task.
            // The subclass throws after the graceful shutdown started, so the pipeline fails the close() promise
            // while the graceful shutdown still waits for stream 3.
            ChannelPromise closePromise = client.newPromise();
            client.pipeline().close(closePromise);
            assertFalse(closePromise.isSuccess());
            assertSame(clientHandler.closeFailure, closePromise.cause());
            assertTrue(client.isOpen());

            ChannelHandlerContext ctx = client.pipeline().context(clientHandler);
            clientHandler.resetStream(ctx, 3, CANCEL.code(), ctx.newPromise());
            client.flush();
            client.runPendingTasks();

            assertEquals(0, clientHandler.connection().numActiveStreams());
            assertFalse(client.isOpen(), "the channel must be closed once the last stream is closed");
            assertSame(clientHandler.closeFailure, closePromise.cause());
        } finally {
            client.finishAndReleaseAll();
            server.finishAndReleaseAll();
        }
    }

Runnable takeTask() {
        BlockingQueue<Runnable> taskQueue = this.taskQueue;
        for (;;) {
            ScheduledFutureTask<?> scheduledTask = peekScheduledTask();
            if (scheduledTask == null) {
                Runnable task = null;
                try {
                    task = taskQueue.take();
                } catch (InterruptedException e) {
                    // Ignore
                }
                return task;
            } else {
                long delayNanos = scheduledTask.delayNanos();
                Runnable task = null;
                if (delayNanos > 0) {
                    try {
                        task = taskQueue.poll(delayNanos, TimeUnit.NANOSECONDS);
                    } catch (InterruptedException e) {
                        // Waken up.
                        return null;
                    }
                }
                if (task == null) {
                    // We need to fetch the scheduled tasks now as otherwise there may be a chance that
                    // scheduled tasks are never executed if there is always one task in the taskQueue.
                    // This is for example true for the read task of OIO Transport
                    // See https://github.com/netty/netty/issues/1614
                    fetchFromScheduledTaskQueue();
                    task = taskQueue.poll();
                }

                if (task != null) {
                    return task;
                }
            }
        }
    }

@Test
    @Timeout(value = 10, unit = TimeUnit.SECONDS)
    void testNotSuspendedUntilScheduledTaskIsCancelled() throws Exception {
        TestThreadFactory threadFactory = new TestThreadFactory();
        final SingleThreadEventExecutor executor = new SuspendingSingleThreadEventExecutor(threadFactory);

        // Schedule a task which is so far in the future that we are sure it will not run at all.
        Future<?> future = executor.schedule(() -> { }, 1, TimeUnit.DAYS);
        TestThread currentThread = threadFactory.threads.take();
        // Let's wait until the thread is started
        currentThread.awaitStarted();
        currentThread.awaitRunnableExecution();
        assertTrue(executor.trySuspend());

        // Now cancel the task which should allow the suspension to let the thread die once we call trySuspend() again
        assertTrue(future.cancel(false));
        future.await();

        // Call in a loop as removal of scheduled tasks from task queue might be lazy
        while (!executor.trySuspend()) {
            Thread.sleep(50);
        }

        currentThread.join();

        // Should be suspended now, we should be able to also call trySuspend() again.
        assertTrue(executor.trySuspend());
        assertTrue(executor.isSuspended());

        executor.shutdownGracefully(0, 0, TimeUnit.MILLISECONDS).syncUninterruptibly();
        assertFalse(executor.isSuspended());
        assertTrue(executor.isShutdown());

        // Guarantee that al tasks were able to die...
        while ((currentThread = threadFactory.threads.poll()) != null) {
            currentThread.join();
        }
    }

