@Test
    public void testCloseEventLoopGroupWhileConnected() throws Exception {
        MultiThreadIoEventLoopGroup group = new MultiThreadIoEventLoopGroup(1,
                IoUringIoHandler.newFactory()
        );
        try {
            final BlockingQueue<Channel> acceptedChannels = new LinkedBlockingQueue<>();
            ServerBootstrap serverBootstrap = new ServerBootstrap();
            serverBootstrap.channel(IoUringServerSocketChannel.class);
            Channel serverChannel = serverBootstrap.group(group)
                    .childHandler(new ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelActive(ChannelHandlerContext ctx) {
                            acceptedChannels.add(ctx.channel());
                        }
                    })
                    .bind(new InetSocketAddress(0))
                    .syncUninterruptibly().channel();

            Bootstrap clientBoostrap = new Bootstrap();
            clientBoostrap.group(group)
                    .channel(IoUringSocketChannel.class)
                    .handler(new ChannelInboundHandlerAdapter());
            ChannelFuture channelFuture = clientBoostrap.connect(serverChannel.localAddress());
            Channel clientChannel = channelFuture.sync().channel();

            group.shutdownGracefully().syncUninterruptibly();
            clientChannel.closeFuture().sync();
            serverChannel.closeFuture().sync();
            acceptedChannels.take().closeFuture().sync();
            assertTrue(acceptedChannels.isEmpty());
        } catch (Throwable t) {
            if (!group.isShutdown()) {
                group.shutdownGracefully().syncUninterruptibly();
            }
            throw t;
        }
    }

@Test
    @DisabledIf("setUpCQSizeUnavailable")
    public void testCqOverflow() {
        int cqSize = 2;
        RingBuffer ringBuffer = Native.createRingBuffer(2, cqSize, Native.IORING_SETUP_CQSIZE);
        try {
            assertNotNull(ringBuffer);
            ringBuffer.enable();
            assertNotEquals(0, ringBuffer.features() & Native.IORING_FEAT_NODROP);

            CompletionQueue completionQueue = ringBuffer.ioUringCompletionQueue();
            assertEquals(cqSize, completionQueue.ringEntries);

            SubmissionQueue submissionQueue = ringBuffer.ioUringSubmissionQueue();
            assertThat(submissionQueue.addNop((byte) 0, 1)).isNotZero();
            assertThat(submissionQueue.addNop((byte) 0, 1)).isNotZero();
            submissionQueue.submitAndGet();
            assertEquals(0, submissionQueue.flags() & Native.IORING_SQ_CQ_OVERFLOW);

            assertThat(submissionQueue.addNop((byte) 0, 1)).isNotZero();
            submissionQueue.submitAndGet();
            assertNotEquals(0, ringBuffer.ioUringSubmissionQueue().flags() & Native.IORING_SQ_CQ_OVERFLOW);

            // The completion queue should have only had space for 2 events
            int processed = (int) (completionQueue.process((res, flags, udata, extraCqeData) -> true) >>> 32);
            assertEquals(2, processed);

            // submit again to ensure we flush the event that did overflow
            submissionQueue.submitAndGetNow();
            processed = (int) (completionQueue.process((res, flags, udata, extraCqeData) -> true) >>> 32);
            assertEquals(1, processed);

            // Everything was processed and so the overflow flag should have been cleared
            assertEquals(0, submissionQueue.flags() & Native.IORING_SQ_CQ_OVERFLOW);
        } finally {
            ringBuffer.close();
        }
    }

@Test
    public void testMixedWritability() {
        final StringBuilder buf = new StringBuilder();
        EmbeddedChannel ch = new EmbeddedChannel(new ChannelInboundHandlerAdapter() {
            @Override
            public void channelWritabilityChanged(ChannelHandlerContext ctx) {
                buf.append(ctx.channel().isWritable());
                buf.append(' ');
            }
        });

        ch.config().setWriteBufferLowWaterMark(128);
        ch.config().setWriteBufferHighWaterMark(256);

        ChannelOutboundBuffer cob = ch.unsafe().outboundBuffer();

        // Trigger channelWritabilityChanged() by writing a lot.
        ch.write(buffer().writeZero(257));
        assertEquals("false ", buf.toString());

        // Ensure that setting a user-defined writability flag to false does not trigger channelWritabilityChanged()
        cob.setUserDefinedWritability(1, false);
        ch.runPendingTasks();
        assertEquals("false ", buf.toString());

        // Ensure reducing the totalPendingWriteBytes down to zero does not trigger channelWritabilityChanged()
        // because of the user-defined writability flag.
        ch.flush();
        assertEquals(0L, cob.totalPendingWriteBytes());
        assertEquals("false ", buf.toString());

        // Ensure that setting the user-defined writability flag to true triggers channelWritabilityChanged()
        cob.setUserDefinedWritability(1, true);
        ch.runPendingTasks();
        assertEquals("false true ", buf.toString());

        safeClose(ch);
    }

@Test
    @Timeout(value = 5000, unit = TimeUnit.MILLISECONDS, threadMode = Timeout.ThreadMode.SEPARATE_THREAD)
    public void testHandlerReplacedBeforeRegistrationAndHandlerAddedThrows() throws Exception {
        final LifecycleCountingHandler replacement = new LifecycleCountingHandler();
        final AtomicInteger removed = new AtomicInteger();
        final IllegalStateException error = new IllegalStateException();
        EmbeddedChannel channel = new EmbeddedChannel(false, false);
        channel.pipeline().addLast("handler", new ChannelInboundHandlerAdapter() {
            @Override
            public void handlerAdded(ChannelHandlerContext ctx) {
                throw error;
            }

            @Override
            public void handlerRemoved(ChannelHandlerContext ctx) {
                removed.incrementAndGet();
            }
        });
        channel.pipeline().replace("handler", "replacement", replacement);
        // The deferred handlerAdded(...) of the replaced handler throws once the channel is registered.
        channel.register();
        assertThatThrownBy(channel::checkException)
                .isInstanceOf(ChannelPipelineException.class)
                .cause().isSameAs(error);

        assertPipelineLinked(channel.pipeline(), "replacement");
        assertThat(removed).as("handlerRemoved(...) calls of the replaced handler").hasValue(1);
        assertThat(replacement.added).as("handlerAdded(...) calls of the replacement").hasValue(1);

        Object msg = new Object();
        assertThat(channel.writeInbound(msg)).isTrue();
        assertThat(replacement.read).as("channelRead(...) calls of the replacement").hasValue(1);
        assertThat(channel.<Object>readInbound()).isSameAs(msg);

        assertThat(channel.finish()).isFalse();
        assertThat(removed).as("handlerRemoved(...) calls of the replaced handler").hasValue(1);
        assertThat(replacement.removed).as("handlerRemoved(...) calls of the replacement").hasValue(1);
    }

@Override
    public void tick(long time) {
        if (instance == null || isRemoved() || !ChunkUtils.isLoaded(currentChunk))
            return;

        // scheduled tasks
        this.scheduler.processTick();
        if (isRemoved()) return;

        // Entity tick
        {
            // handle position and velocity updates
            movementTick();

            // handle block contacts
            touchTick();

            // Call the abstract update method
            update(time);

            ticks++;
            EventDispatcher.call(new EntityTickEvent(this));

            // remove expired effects
            effectTick();
        }
        // Scheduled synchronization
        if (ticks >= nextSynchronizationTick) {
            if (vehicle == null) {
                synchronizePosition();
                sendPacketToViewers(getVelocityPacket());
            } else {
                synchronizeView();
                nextSynchronizationTick = ticks + synchronizationTicks;
            }
        }
        // End of tick scheduled tasks
        this.scheduler.processTickEnd();
    }

@Override
        public CancelledState cancel() {
            for (int curr = this.getStateVolatile();;) {
                switch (curr) {
                    case STATE_IDLE: {
                        if (STATE_IDLE == (curr = this.compareAndExchangeStateVolatile(STATE_IDLE, STATE_CANCELLED))) {
                            this.state = STATE_CANCELLED;
                            this.run = null;
                            this.retired = null;
                            return CancelledState.CANCELLED_BY_CALLER;
                        }
                        // try again
                        continue;
                    }
                    case STATE_EXECUTING: {
                        if (!this.isRepeatingTask()) {
                            return CancelledState.RUNNING;
                        }
                        if (STATE_EXECUTING == (curr = this.compareAndExchangeStateVolatile(STATE_EXECUTING, STATE_EXECUTING_CANCELLED))) {
                            return CancelledState.NEXT_RUNS_CANCELLED;
                        }
                        // try again
                        continue;
                    }
                    case STATE_EXECUTING_CANCELLED: {
                        return CancelledState.NEXT_RUNS_CANCELLED_ALREADY;
                    }
                    case STATE_FINISHED: {
                        return CancelledState.ALREADY_EXECUTED;
                    }
                    case STATE_CANCELLED: {
                        return CancelledState.CANCELLED_ALREADY;
                    }
                    default: {
                        throw new IllegalStateException("Unknown state: " + curr);
                    }
                }
            }
        }

@Override
  public void handlePlayerChatInternal(SessionPlayerChatPacket packet) {
    ChatQueue chatQueue = this.player.getChatQueue();
    EventManager eventManager = this.server.getEventManager();
    PlayerChatEvent toSend = new PlayerChatEvent(player, packet.getMessage());
    CompletableFuture<PlayerChatEvent> eventFuture = eventManager.fire(toSend);
    chatQueue.queuePacket(
        newLastSeenMessages -> eventFuture
            .thenApply(pme -> {
              PlayerChatEvent.ChatResult chatResult = pme.getResult();
              if (!chatResult.isAllowed()) {
                if (packet.isSigned()) {
                  invalidCancel(logger, player);
                }
                return null;
              }

              if (chatResult.getMessage().map(str -> !str.equals(packet.getMessage()))
                  .orElse(false)) {
                if (packet.isSigned()) {
                  invalidChange(logger, player);
                  return null;
                }
                return this.player.getChatBuilderFactory().builder()
                    .message(chatResult.getMessage().orElse(packet.getMessage()))
                    .setTimestamp(packet.timestamp)
                    .setLastSeenMessages(newLastSeenMessages)
                    .toServer();
              }
              return packet.withLastSeenMessages(newLastSeenMessages);
            })
            .exceptionally((ex) -> {
              logger.error("Exception while handling player chat for {}", player, ex);
              return null;
            }),
        packet.getTimestamp(),
        packet.getLastSeenMessages()
    );
  }

