@ParameterizedTest(name = "always acknowledge insertions: {0}")
    @ValueSource(booleans = { false, true })
    public void insertCountIncrementDoesNotRepeatInsertsAcknowledgedBySection(boolean alwaysAcknowledgeInsertions)
            throws Exception {
        setup(128, 1, alwaysAcknowledgeInsertions ? new QpackDecoderStateSyncStrategy() {
            @Override
            public void sectionAcknowledged(int requiredInsertCount) {
                // NOOP
            }

            @Override
            public boolean entryAdded(int insertCount) {
                return true;
            }
        } : ackEachInsert());
        BiConsumer<CharSequence, CharSequence> sink = (n, v) -> { };
        ByteBuf in = encodeBlockingFrame(1);
        try {
            boolean[] resumed = new boolean[1];
            // Like Http3FrameCodec, decode the header block again once the stream is unblocked.
            assertFalse(decoder.decode(attributes, 0L, in, in.readableBytes(), sink, () -> {
                try {
                    resumed[0] = decoder.decode(attributes, 0L, in, in.readableBytes(), sink, () -> { });
                } catch (QpackException e) {
                    throw new AssertionError(e);
                }
            }));

            // Unblocks stream 0, which sends a Section Acknowledgment for a Required Insert Count of 1.
            decoder.insertLiteral(decoderStream, FOO, BAR);
            assertTrue(resumed[0]);
            decoder.insertLiteral(decoderStream, FOO + 2, BAR + 2);

            assertThat(knownReceivedCountOfEncoder(streamId -> 1), is(2));
        } finally {
            in.release();
            assertFalse(decoderStream.finishAndReleaseAll());
        }
    }

@Test
    void testNotSuspendedUntilScheduledTaskDidRun() throws Exception {
        TestThreadFactory threadFactory = new TestThreadFactory();
        final SingleThreadEventExecutor executor = new SuspendingSingleThreadEventExecutor(threadFactory);

        final CountDownLatch latch = new CountDownLatch(1);
        // Schedule a task which is so far in the future that we are sure it will not run at all.
        Future<?> future = executor.schedule(() -> {
            try {
                latch.await();
            } catch (InterruptedException ignore) {
                // ignore
            }
        }, 100, TimeUnit.MILLISECONDS);
        TestThread currentThread = threadFactory.threads.take();
        // Let's wait until the thread is started
        currentThread.awaitStarted();
        currentThread.awaitRunnableExecution();
        latch.countDown();
        assertTrue(executor.trySuspend());

        // Now wait till the scheduled task was run
        future.sync();

        currentThread.join();

        // Should be suspended now, we should be able to also call trySuspend() again.
        assertTrue(executor.trySuspend());
        assertTrue(executor.isSuspended());

        executor.shutdownGracefully(0, 0, TimeUnit.MILLISECONDS).syncUninterruptibly();
        assertFalse(executor.isSuspended());
        assertTrue(executor.isShutdown());

        // Guarantee that al tasks were able to die...
        while ((currentThread = threadFactory.threads.poll()) != null) {
            currentThread.join();
        }
    }

@Test
    public void testHandlerRemovedFlushesQueuedMessages() throws Exception {
        final UpstreamReadCounter upstream = new UpstreamReadCounter();
        final List<Object> received = new ArrayList<Object>();
        final AtomicInteger readCompletes = new AtomicInteger();
        final FlowControlHandler flow = new FlowControlHandler();
        final EmbeddedChannel channel = new EmbeddedChannel(false, false,
                upstream,
                flow,
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        received.add(msg);
                    }

                    @Override
                    public void channelReadComplete(ChannelHandlerContext ctx) {
                        readCompletes.incrementAndGet();
                    }
                });
        channel.config().setAutoRead(false);
        channel.register();

        // With auto-read off and no read(), all five messages stay queued in the handler.
        channel.writeInbound("1", "2", "3", "4", "5");
        assertEquals(0, received.size());
        assertEquals(0, readCompletes.get());

        // Removing the handler flushes the whole queue downstream, in order, then completes the batch once.
        channel.pipeline().remove(flow);
        assertEquals(Arrays.asList("1", "2", "3", "4", "5"), received);
        assertEquals(1, readCompletes.get());
        assertTrue(flow.isQueueEmpty());

        // The flush happens locally on removal; nothing is read upstream.
        assertEquals(0, upstream.reads.get());

        assertFalse(channel.finishAndReleaseAll());
    }

