    public void testExceptionCaughtBothCombinedHandlers() {
        final Exception exception = new Exception();
        final Queue<ChannelHandler> queue = new ArrayDeque<ChannelHandler>();

        ChannelInboundHandler inboundHandler = new ChannelInboundHandlerAdapter() {
            @Override
            public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                assertSame(exception, cause);
                queue.add(this);
                ctx.fireExceptionCaught(cause);
            }
        };
        ChannelOutboundHandler outboundHandler = new ChannelOutboundHandlerAdapter() {
            @SuppressWarnings("deprecation")
            @Override
            public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                assertSame(exception, cause);
                queue.add(this);
                ctx.fireExceptionCaught(cause);
            }
        };
        ChannelInboundHandler lastHandler = new ChannelInboundHandlerAdapter() {
            @Override
            public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                assertSame(exception, cause);
                queue.add(this);
            }
        };
        EmbeddedChannel channel = new EmbeddedChannel(
                new CombinedChannelDuplexHandler<ChannelInboundHandler, ChannelOutboundHandler>(
                        inboundHandler, outboundHandler), lastHandler);
        channel.pipeline().fireExceptionCaught(exception);
        assertFalse(channel.finish());
        assertSame(inboundHandler, queue.poll());
        assertSame(outboundHandler, queue.poll());
        assertSame(lastHandler, queue.poll());
        assertTrue(queue.isEmpty());
    }

private void sendPendingChunks() {
        // If we have nothing to send or have sent the max # of batches without reply, do nothing
        if (chunkQueue.isEmpty() || chunkBatchLead >= maxChunkBatchLead) return;

        // Increment the pending chunk count by the target chunks per tick
        pendingChunkCount = Math.min(pendingChunkCount + targetChunksPerTick, ServerProperties.MAX_CHUNKS_PER_TICK.get());
        if (pendingChunkCount < 1) return; // Cant send anything

        chunkQueueLock.lock();
        try {
            int batchSize = 0;
            sendPacket(new ChunkBatchStartPacket());
            while (!chunkQueue.isEmpty() && pendingChunkCount >= 1f) {
                long chunkIndex = chunkQueue.dequeueLong();
                int chunkX = CoordConversion.chunkIndexGetX(chunkIndex), chunkZ = CoordConversion.chunkIndexGetZ(chunkIndex);
                var chunk = instance.getChunk(chunkX, chunkZ);
                if (chunk == null || !chunk.isLoaded()) continue;

                sendPacket(chunk.getFullDataPacket());
                EventDispatcher.call(new PlayerChunkLoadEvent(this, chunkX, chunkZ));

                pendingChunkCount -= 1f;
                batchSize += 1;
            }
            sendPacket(new ChunkBatchFinishedPacket(batchSize));
            chunkBatchLead += 1;
//            logger.debug("chunk batch sent player={} chunks={} lead={}", username, batchSize, chunkBatchLead);

            // After sending the first chunk we always send a synchronize position to the client. This is to prevent
            // cases where the client falls through the floor slightly while loading the first chunk.
            // In the vanilla server they have an anticheat which teleports the client back if they enter the floor,
            // but since Minestom does not have an anticheat this provides a similar effect.
            if (needsChunkPositionSync) {
                synchronizePositionAfterTeleport(getPosition(), Vec.ZERO, RelativeFlags.NONE, true);
                needsChunkPositionSync = false;
            }
        } finally {
            chunkQueueLock.unlock();
        }
    }

@Contract(value = "-> new", pure = true)
        public EventListener<T> build() {
            final boolean ignoreCancelled = this.ignoreCancelled;
            AtomicInteger expirationCount = new AtomicInteger(this.expireCount);
            final boolean hasExpirationCount = expirationCount.get() > 0;

            final Predicate<T> expireWhen = this.expireWhen;

            final var filters = new ArrayList<>(this.filters);
            final var handler = this.handler;
            return new ListenerImpl<>(eventType, event -> {
                // Event cancellation
                if (ignoreCancelled && event instanceof CancellableEvent cancellableEvent &&
                        cancellableEvent.isCancelled()) {
                    return Result.INVALID;
                }
                // Expiration predicate
                if (expireWhen != null && expireWhen.test(event)) {
                    return Result.EXPIRED;
                }
                // Filtering
                if (!filters.isEmpty()) {
                    for (var filter : filters) {
                        if (!filter.test(event)) {
                            // Cancelled
                            return Result.INVALID;
                        }
                    }
                }
                // Handler
                if (handler != null) {
                    handler.accept(event);
                }
                // Expiration count
                if (hasExpirationCount && expirationCount.decrementAndGet() == 0) {
                    return Result.EXPIRED;
                }
                return Result.SUCCESS;
            });
        }

@Override
    public Set<Point> calculateInternal(Palette blockPalette,
                                        int chunkX, int chunkY, int chunkZ,
                                        int[] heightmap, int maxY,
                                        LightLookup lightLookup) {
        this.isValidBorders = true;

        // Update single section with base lighting changes
        int queueSize = SECTION_BLOCK_COUNT;
        ShortArrayFIFOQueue queue = new ShortArrayFIFOQueue(0);
        if (!fullyLit) {
            queue = buildInternalQueue(heightmap, maxY, chunkY);
            queueSize = queue.size();
        }

        if (queueSize == SECTION_BLOCK_COUNT) {
            this.fullyLit = true;
            this.content = CONTENT_FULLY_LIT;
        } else {
            this.content = LightCompute.compute(blockPalette, queue);
        }

        // Propagate changes to neighbors and self
        Set<Point> toUpdate = new HashSet<>();
        for (int i = -1; i <= 1; i++) {
            for (int j = -1; j <= 1; j++) {
                for (int k = -1; k <= 1; k++) {
                    final int neighborX = chunkX + i;
                    final int neighborY = chunkY + j;
                    final int neighborZ = chunkZ + k;
                    if (!(lightLookup.light(neighborX, neighborY, neighborZ) instanceof SkyLight skyLight))
                        continue;
                    skyLight.contentPropagation = null;
                    toUpdate.add(new BlockVec(neighborX, neighborY, neighborZ));
                }
            }
        }
        toUpdate.add(new BlockVec(chunkX, chunkY, chunkZ));
        return toUpdate;
    }

private boolean receivedPacket(SplitPacketPayload payload, IPayloadContext context) {
        byte state = payload.payload()[0];
        if (state == STATE_FIRST) {
            if (!receivedBuffers.isEmpty()) {
                LOGGER.warn("neoforge:split received out of order - inbound buffer not empty when receiving first");
                receivedBuffers.clear();
                sizeCounter = 0L;
            }
        }

        int contentSize = payload.payload().length - 1;
        byte[] buffer = new byte[contentSize];
        System.arraycopy(payload.payload(), 1, buffer, 0, contentSize); // We cut of the initial byte here that indicates the state
        receivedBuffers.add(buffer);
        sizeCounter += buffer.length;

        long maxSize = NeoForgeLocalConfig.INSTANCE.splitPacketMaxSizeLimitMb.getAsInt() * ONE_MB;
        if (sizeCounter > maxSize || receivedBuffers.size() > MAX_PACKETS_SAFETY_LIMIT) {
            // Reset data, as we are going to disconnect anyway
            sizeCounter = 0L;
            receivedBuffers.clear();
            return false;
        }

        if (state == STATE_LAST) {
            final byte[][] buffers = receivedBuffers.toArray(new byte[0][]);
            FriendlyByteBuf full = new FriendlyByteBuf(Unpooled.wrappedBuffer(buffers));

            try {
                Packet<?> packet = context.connection().getInboundProtocol().codec().decode(full);
                context.enqueueWork(() -> context.handle(packet));
            } finally {
                sizeCounter = 0L;
                receivedBuffers.clear();
                full.release();
            }
        }

        return true;
    }

public boolean propagateUpdates() {
        if (this.updatedSources.isEmpty()) {
            return false;
        }

        boolean ret = false;

        for (final LongIterator iterator = this.updatedSources.iterator(); iterator.hasNext();) {
            final long coordinate = iterator.nextLong();

            final byte currentLevel = this.levels.get(coordinate);
            final byte updatedSource = this.sources.get(coordinate);

            if (currentLevel == updatedSource) {
                continue;
            }
            ret = true;

            if (updatedSource > currentLevel) {
                // level increase
                this.addToIncreaseWorkQueue(coordinate, updatedSource);
            } else {
                // level decrease
                this.addToRemoveWorkQueue(coordinate, currentLevel);
                // if the current coordinate is a source, then the decrease propagation will detect that and queue
                // the source propagation
            }
        }

        this.updatedSources.clear();

        // propagate source level increases first for performance reasons (in crowded areas hopefully the additions
        // make the removes remove less)
        this.propagateIncreases();

        // now we propagate the decreases (which will then re-propagate clobbered sources)
        this.propagateDecreases();

        return ret;
    }

