    }

@Test
    public void channelClosedWhenWriteFutureFails() {
        final Queue<ChannelPromise> writePromises = new ArrayDeque<ChannelPromise>();

        LastInboundHandler inboundHandler = new LastInboundHandler();
        Http2StreamChannel childChannel = newInboundStream(3, false, inboundHandler);

        assertTrue(childChannel.isOpen());
        assertTrue(childChannel.isActive());

        final AtomicBoolean channelOpen = new AtomicBoolean(true);
        final AtomicBoolean channelActive = new AtomicBoolean(true);

        Http2Headers headers = new DefaultHttp2Headers();
        when(frameWriter.writeHeaders(eqCodecCtx(), anyInt(),
                eq(headers), anyInt(), anyBoolean(),
                any(ChannelPromise.class))).thenAnswer(new Answer<ChannelFuture>() {
            @Override
            public ChannelFuture answer(InvocationOnMock invocationOnMock) {
                ChannelPromise promise = invocationOnMock.getArgument(5);
                writePromises.offer(promise);
                return promise;
            }
        });

        ChannelFuture f = childChannel.writeAndFlush(new DefaultHttp2HeadersFrame(headers));
        assertFalse(f.isDone());
        f.addListener((ChannelFutureListener) future -> {
            channelOpen.set(future.channel().isOpen());
            channelActive.set(future.channel().isActive());
        });

        ChannelPromise first = writePromises.poll();
        first.setFailure(new ClosedChannelException());
        f.awaitUninterruptibly();

        assertFalse(channelOpen.get());
        assertFalse(channelActive.get());
        assertFalse(childChannel.isActive());
    }

@Override
        public void run() {
            // Initialize the startTime.
            startTime = System.nanoTime();
            if (startTime == 0) {
                // We use 0 as an indicator for the uninitialized value here, so make sure it's not 0 when initialized.
                startTime = 1;
            }

            // Notify the other threads waiting for the initialization at start().
            startTimeInitialized.countDown();

            do {
                final long deadline = waitForNextTick();
                if (deadline > 0) {
                    int idx = (int) (tick & mask);
                    processCancelledTasks();
                    HashedWheelBucket bucket =
                            wheel[idx];
                    transferTimeoutsToBuckets();
                    bucket.expireTimeouts(deadline);
                    tick++;
                }
            } while (WORKER_STATE_UPDATER.get(HashedWheelTimer.this) == WORKER_STATE_STARTED);

            // Fill the unprocessedTimeouts so we can return them from stop() method.
            for (HashedWheelBucket bucket: wheel) {
                bucket.clearTimeouts(unprocessedTimeouts);
            }
            for (;;) {
                HashedWheelTimeout timeout = timeouts.poll();
                if (timeout == null) {
                    break;
                }
                if (!timeout.isCancelled()) {
                    unprocessedTimeouts.add(timeout);
                }
            }
            processCancelledTasks();
        }

long enqueueSqe(byte opcode, byte flags, short ioPrio, int fd, long union1, long union2, int len,
                             int union3, long udata, short union4, short personality, int union5, long union6) {
        checkClosed();
        int pending = tail - head;
        if (pending == ringEntries) {
            int submitted = submit();
            if (submitted == 0) {
                // We have a problem, could not submit to make more room in the ring
                throw new RuntimeException("SQ ring full and no submissions accepted");
            }
        }
        int sqe = sqeIndex(tail++, ringMask);

        //set sqe(submission queue) properties
        submissionQueueArray.put(sqe + SQE_OP_CODE_FIELD, opcode);
        submissionQueueArray.put(sqe + SQE_FLAGS_FIELD, flags);
        // This constant is set up-front
        submissionQueueArray.putShort(sqe + SQE_IOPRIO_FIELD, ioPrio);
        submissionQueueArray.putInt(sqe + SQE_FD_FIELD, fd);
        submissionQueueArray.putLong(sqe + SQE_UNION1_FIELD, union1);
        submissionQueueArray.putLong(sqe + SQE_UNION2_FIELD, union2);
        submissionQueueArray.putInt(sqe + SQE_LEN_FIELD, len);
        submissionQueueArray.putInt(sqe + SQE_UNION3_FIELD, union3);
        submissionQueueArray.putLong(sqe + SQE_USER_DATA_FIELD, udata);
        submissionQueueArray.putShort(sqe + SQE_UNION4_FIELD, union4);
        submissionQueueArray.putShort(sqe + SQE_PERSONALITY_FIELD, personality);
        submissionQueueArray.putInt(sqe + SQE_UNION5_FIELD, union5);
        submissionQueueArray.putLong(sqe + SQE_UNION6_FIELD, union6);

        if (logger.isTraceEnabled()) {
            if (opcode == Native.IORING_OP_WRITEV || opcode == Native.IORING_OP_READV) {
                logger.trace("add(ring={}, enterRing:{} ): {}(fd={}, len={}, off={}, data={})",
                        ringFd, enterRingFd, Native.opToStr(opcode), fd, len, union1, udata);
            } else {
                logger.trace("add(ring={}, enterRing:{}): {}(fd={}, len={}, off={}, data={})",
                        ringFd, enterRingFd, Native.opToStr(opcode), fd, len, union1, udata);
            }
        }
        return udata;
    }

void close(final Throwable cause, final boolean allowChannelOpen) {
        if (inFail) {
            channel.eventLoop().execute(new Runnable() {
                @Override
                public void run() {
                    close(cause, allowChannelOpen);
                }
            });
            return;
        }

        inFail = true;

        if (!allowChannelOpen && channel.isOpen()) {
            throw new IllegalStateException("close() must be invoked after the channel is closed.");
        }

        if (!isEmpty()) {
            throw new IllegalStateException("close() must be invoked after all flushed writes are handled.");
        }

        // Release all unflushed messages.
        try {
            Entry e = unflushedEntry;
            while (e != null) {
                // Just decrease; do not trigger any events via decrementPendingOutboundBytes()
                int size = e.pendingSize;
                TOTAL_PENDING_SIZE_UPDATER.addAndGet(this, -size);

                if (!e.cancelled) {
                    ReferenceCountUtil.safeRelease(e.msg);
                    safeFail(e.promise, cause);
                }
                e = e.unguardedRecycleAndGetNext();
            }
        } finally {
            inFail = false;
        }
        clearNioBuffers();
    }

@Test
    public void testWriteAndFlushFromReleaseOfCancelledWrite() {
        final EmbeddedChannel ch = new EmbeddedChannel();
        final List<ChannelFuture> reentrantWrites = new ArrayList<ChannelFuture>();
        ReferenceCounted cancelledMsg = new AbstractReferenceCounted() {
            @Override
            protected void deallocate() {
                // Release of a cancelled write runs user code which writes and flushes on the same channel.
                reentrantWrites.add(ch.writeAndFlush(wrappedBuffer(new byte[] { 2 })));
            }

            @Override
            public ReferenceCounted touch(Object hint) {
                return this;
            }
        };

        ChannelFuture cancelled = ch.write(cancelledMsg);
        ChannelFuture second = ch.write(wrappedBuffer(new byte[] { 1 }));
        assertTrue(cancelled.cancel(false));

        ch.flush();

        assertEquals(1, reentrantWrites.size());
        assertEquals(0, cancelledMsg.refCnt());
        assertTrue(second.isSuccess());
        assertTrue(reentrantWrites.get(0).isSuccess());
        ChannelOutboundBuffer buffer = ch.unsafe().outboundBuffer();
        assertTrue(buffer.isEmpty());
        assertEquals(0, buffer.size());
        assertEquals(0, buffer.totalPendingWriteBytes());
        // The cancelled write is replaced by an empty buffer.
        assertOutbound(ch, 0);
        assertOutbound(ch, 1);
        assertOutbound(ch, 2);
        assertNull(ch.readOutbound());

        assertFalse(ch.finish());
        assertFalse(ch.isOpen());
    }

