private void recalibrateMinimumTimeout() {
        this.lock.lock();
        try {
            final Set<ScheduledTask> tasks = this.tasks();
            this.minimumTimeout = Long.MAX_VALUE;
            final long now = System.nanoTime();
            for (final ScheduledTask tmpTask : tasks) {
                final SpongeScheduledTask task = (SpongeScheduledTask) tmpTask;
                if (task.state() == SpongeScheduledTask.ScheduledTaskState.EXECUTING) {
                    // bail out for this task. We'll signal when we complete the task.
                    continue;
                }
                // Recalibrate the wait delay for processing tasks before new
                // tasks cause the scheduler to process pending tasks.
                if (task.task.delay == 0 && task.task.interval == 0) {
                    this.minimumTimeout = 0;
                }
                // The time since the task last executed or was added to the map
                final long timeSinceLast = now - task.timestamp();

                if (task.task.delay > 0 && task.state() == SpongeScheduledTask.ScheduledTaskState.WAITING) {
                    // There is an delay and the task hasn't run yet
                    this.minimumTimeout = Math.min(task.task.delay - timeSinceLast, this.minimumTimeout);
                }
                if (task.task.interval > 0 && task.state().isActive) {
                    // The task repeats and has run after the initial delay
                    this.minimumTimeout = Math.min(task.task.interval - timeSinceLast, this.minimumTimeout);
                }
                if (this.minimumTimeout <= 0) {
                    break;
                }
            }
            if (!tasks.isEmpty()) {
                final long latency = System.nanoTime() - this.lastProcessingTimestamp;
                this.minimumTimeout -= (latency <= 0) ? 0 : latency;
                this.minimumTimeout = (this.minimumTimeout < 0) ? 0 : this.minimumTimeout;
            }
        } finally {
            this.lock.unlock();
        }
    }

@Test
    public void testPoll() {
        PriorityQueue<TestElement> queue = new DefaultPriorityQueue<TestElement>(TestElementComparator.INSTANCE, 0);
        assertEmptyQueue(queue);

        TestElement a = new TestElement(5);
        TestElement b = new TestElement(10);
        TestElement c = new TestElement(2);
        TestElement d = new TestElement(7);
        TestElement e = new TestElement(6);

        assertOffer(queue, a);
        assertOffer(queue, b);
        assertOffer(queue, c);
        assertOffer(queue, d);

        // Remove the first element
        assertSame(c, queue.peek());
        assertSame(c, queue.poll());
        assertEquals(3, queue.size());

        // Test that offering another element preserves the priority queue semantics.
        assertOffer(queue, e);
        assertEquals(4, queue.size());
        assertSame(a, queue.peek());
        assertSame(a, queue.poll());
        assertEquals(3, queue.size());

        // Keep removing the remaining elements
        assertSame(e, queue.peek());
        assertSame(e, queue.poll());
        assertEquals(2, queue.size());

        assertSame(d, queue.peek());
        assertSame(d, queue.poll());
        assertEquals(1, queue.size());

        assertSame(b, queue.peek());
        assertSame(b, queue.poll());
        assertEmptyQueue(queue);
    }

@Test
    public void testCompletingReadWithNonEmptyQueue() throws Exception {
        final UpstreamReadCounter upstream = new UpstreamReadCounter();
        final AtomicInteger reads = new AtomicInteger();
        final AtomicInteger readCompletes = new AtomicInteger();
        final EmbeddedChannel channel = new EmbeddedChannel(
                false, false,
                upstream,
                new FlowControlHandler(),
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        reads.incrementAndGet();
                    }

                    @Override
                    public void channelReadComplete(ChannelHandlerContext ctx) {
                        readCompletes.incrementAndGet();
                    }
                });

        channel.config().setAutoRead(false);
        channel.register();

        assertFalse(channel.writeInbound("msg1", "msg2"));
        assertEquals(0, reads.get());
        assertEquals(0, readCompletes.get());

        channel.read();
        assertEquals(1, reads.get());
        assertEquals(1, readCompletes.get());

        channel.read();
        assertEquals(2, reads.get());
        assertEquals(2, readCompletes.get());

        // Every read() was satisfied straight from the queue, so none was forwarded upstream.
        assertEquals(0, upstream.reads.get());

        assertFalse(channel.finishAndReleaseAll());
    }

