private void drainEventFd() {
        CompletionQueue completionQueue = ringBuffer.ioUringCompletionQueue();
        SubmissionQueue submissionQueue = ringBuffer.ioUringSubmissionQueue();
        assert !eventFdClosing;
        eventFdClosing = true;
        boolean eventPending = eventfdAsyncNotify.getAndSet(true);
        if (eventPending) {
            // There is an event that has been or will be written by another thread, so we must wait for the event.
            // Make sure we're actually listening for writes to the event fd.
            while (eventfdReadSubmitted == 0) {
                submitEventFdRead();
                submissionQueue.submit();
            }
            // Drain the eventfd of the pending wakup.
            class DrainFdEventCallback implements CompletionCallback {
                boolean eventFdDrained;

                @Override
                public boolean handle(int res, int flags, long udata, ByteBuffer extraCqeData) {
                    if (udata == EVENTFD_TOKEN) {
                        eventFdDrained = true;
                    }
                    return IoUringIoHandler.this.handle(res, flags, udata, extraCqeData);
                }
            }
            final DrainFdEventCallback handler = new DrainFdEventCallback();
            completionQueue.process(handler);
            while (!handler.eventFdDrained) {
                submissionQueue.submitAndGet();
                processCompletionsAndHandleOverflow(submissionQueue, completionQueue, handler);
            }
        }
        // We've consumed any pending eventfd read and `eventfdAsyncNotify` should never
        // transition back to false, thus we should never have any more events written.
        // So, if we have a read event pending, we can cancel it.
        if (eventfdReadSubmitted != 0) {
            submissionQueue.addCancel(eventfdReadSubmitted, EVENTFD_TOKEN);
            eventfdReadSubmitted = 0;
            submissionQueue.submit();
        }
    }

public void addFlush() {
        // There is no need to process all entries if there was already a flush before and no new messages
        // where added in the meantime.
        //
        // See https://github.com/netty/netty/issues/2577
        Entry entry = unflushedEntry;
        if (entry != null) {
            if (flushedEntry == null) {
                // there is no flushedEntry yet, so start with the entry
                flushedEntry = entry;
            }
            long cancelledBytes = 0;
            List<Object> cancelledMsgs = null;
            do {
                flushed ++;
                if (!entry.promise.setUncancellable()) {
                    // Was cancelled so make sure we free up memory. The message is released only once this buffer is
                    // consistent again, as releasing it may run arbitrary user code.
                    if (cancelledMsgs == null) {
                        cancelledMsgs = new ArrayList<Object>(2);
                    }
                    cancelledMsgs.add(entry.msg);
                    cancelledBytes += entry.cancel();
                }
                entry = entry.next;
            } while (entry != null);

            // All flushed so reset unflushedEntry
            unflushedEntry = null;

            if (cancelledMsgs != null) {
                for (int i = 0; i < cancelledMsgs.size(); i++) {
                    ReferenceCountUtil.safeRelease(cancelledMsgs.get(i));
                }
                // Notify about the freed bytes only now. This may fire channelWritabilityChanged(...) synchronously,
                // and a handler may write, flush or close the channel from there, so this buffer must be consistent
                // first.
                decrementPendingOutboundBytes(cancelledBytes, false, true);
            }
        }
    }

private void acquire0(final Promise<Channel> promise) {
        try {
            assert executor.inEventLoop();

            if (closed) {
                promise.setFailure(new IllegalStateException("FixedChannelPool was closed"));
                return;
            }
            if (acquiredChannelCount.get() < maxConnections) {
                assert acquiredChannelCount.get() >= 0;

                // We need to create a new promise as we need to ensure the AcquireListener runs in the correct
                // EventLoop
                Promise<Channel> p = executor.newPromise();
                AcquireListener l = new AcquireListener(promise);
                l.acquired();
                p.addListener(l);
                super.acquire(p);
            } else {
                if (pendingAcquireCount >= maxPendingAcquires) {
                    tooManyOutstanding(promise);
                } else {
                    AcquireTask task = new AcquireTask(promise);
                    if (pendingAcquireQueue.offer(task)) {
                        ++pendingAcquireCount;

                        if (timeoutTask != null) {
                            task.timeoutFuture = executor.schedule(timeoutTask, acquireTimeoutNanos,
                                  TimeUnit.NANOSECONDS);
                        }
                    } else {
                        tooManyOutstanding(promise);
                    }
                }

                assert pendingAcquireCount > 0;
            }
        } catch (Throwable cause) {
            promise.tryFailure(cause);
        }
    }

@Test
    public void testWriteAndFlushFromWritabilityChangedCausedByCancelledWrite() {
        final List<ChannelFuture> reentrantWrites = new ArrayList<ChannelFuture>();
        EmbeddedChannel ch = new EmbeddedChannel(new ChannelInboundHandlerAdapter() {
            @Override
            public void channelWritabilityChanged(ChannelHandlerContext ctx) {
                if (ctx.channel().isWritable() && reentrantWrites.isEmpty()) {
                    reentrantWrites.add(ctx.writeAndFlush(wrappedBuffer(new byte[] { 2 })));
                }
                ctx.fireChannelWritabilityChanged();
            }
        });
        ch.config().setWriteBufferWaterMark(new WriteBufferWaterMark(256, 512));

        ByteBuf cancelledBuf = buffer().writeZero(512);
        ChannelFuture cancelled = ch.write(cancelledBuf);
        ChannelFuture second = ch.write(wrappedBuffer(new byte[] { 1 }));
        assertFalse(ch.isWritable());
        assertTrue(cancelled.cancel(false));

        // Releasing the cancelled write makes the channel writable while addFlush() runs.
        ch.flush();

        assertTrue(ch.isWritable());
        assertEquals(1, reentrantWrites.size());
        assertEquals(0, cancelledBuf.refCnt());
        assertTrue(second.isSuccess());
        assertTrue(reentrantWrites.get(0).isSuccess());
        ChannelOutboundBuffer buffer = ch.unsafe().outboundBuffer();
        assertTrue(buffer.isEmpty());
        assertEquals(0, buffer.size());
        assertEquals(0, buffer.totalPendingWriteBytes());
        // The cancelled write is replaced by an empty buffer.
        assertOutbound(ch, 0);
        assertOutbound(ch, 1);
        assertOutbound(ch, 2);
        assertNull(ch.readOutbound());

        assertFalse(ch.finish());
        assertFalse(ch.isOpen());
    }

public static CompletableFuture<Void> bootStrap(boolean withTags) {
        SharedConstants.tryDetectVersion();
        Bootstrap.bootStrap();
        Bootstrap.validate();

        PackRepository packRepository = ServerPacksSource.createVanillaTrustedRepository();
        FeatureFlagSet flags = FeatureFlags.REGISTRY.allFlags();
        MinecraftServer.configurePackRepository(packRepository, new WorldDataConfiguration(new DataPackConfig(FeatureFlags.REGISTRY.toNames(flags).stream().map(Identifier::getPath).toList(), List.of()), flags), true, false);
        CloseableResourceManager resourceManager = new MultiPackResourceManager(PackType.SERVER_DATA, packRepository.openAllSelected());

        LayeredRegistryAccess<RegistryLayer> layers = RegistryLayer.createRegistryAccess();
        List<Registry.PendingTags<?>> pendingTags = TagLoader.loadTagsForExistingRegistries(resourceManager, layers.getLayer(RegistryLayer.STATIC));
        List<HolderLookup.RegistryLookup<?>> worldGenLayer = TagLoader.buildUpdatedLookups(layers.getAccessForLoading(RegistryLayer.WORLD), pendingTags);
        RegistryAccess.Frozen frozenWorldgenRegistries = RegistryDataLoader.load(resourceManager, worldGenLayer, RegistryDataLoader.WORLD_REGISTRIES, Util.backgroundExecutor()).join();
        layers = layers.replaceFrom(RegistryLayer.WORLD, frozenWorldgenRegistries);
        List<HolderLookup.RegistryLookup<?>> staticAndWorldgenLookups = Stream.concat(worldGenLayer.stream(), frozenWorldgenRegistries.listRegistries()).toList();
        RegistryAccess.Frozen dimensionRegistries = RegistryDataLoader.load(resourceManager, staticAndWorldgenLookups, RegistryDataLoader.DIMENSION_REGISTRIES, Util.backgroundExecutor()).join();
        layers = layers.replaceFrom(RegistryLayer.DIMENSIONS, dimensionRegistries);
        REGISTRY_ACCESS = layers.compositeAccess().freeze();
        if (withTags) {
            return ReloadableServerResources.loadResources(
                resourceManager,
                layers,
                pendingTags,
                flags,
                Commands.CommandSelection.DEDICATED,
                LevelBasedPermissionSet.GAMEMASTER,
                Util.backgroundExecutor(),
                Runnable::run
            ).whenComplete((result, ex) -> {
                if (ex != null) {
                    resourceManager.close();
                }
            }).thenAccept(resources -> {
                resources.updateComponentsAndStaticRegistryTags();
                EXPERIMENTAL_TAGS = ExperimentalCollector.collectTags(resourceManager);
            });
        } else {
            EXPERIMENTAL_TAGS = Map.of();
            return CompletableFuture.completedFuture(null);
        }
    }

public static void eatItemParticles(Level level, SpiritAltarBlockEntity altar, IMalumSpecialItemAccessPoint holder, MalumNetworkedParticleEffectColorData colorData, ItemStack stack) {
        SpiritLike activeSpiritType = getCentralSpiritType(altar);
        if (activeSpiritType == null) {
            return;
        }
        long gameTime = level.getGameTime();
        var random = level.random;
        var altarTargetPos = getItemPos(altar);
        var holderTargetPos = holder.getItemPos();
        for (int i = 0; i < 2; i++) {
            SpiritLightSpecs.coolLookingShinyThing(level, holderTargetPos, activeSpiritType);
        }
        for (int i = 0; i < 16; i++) {
            int finalI = i;
            SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
            Vec3 velocity = altarTargetPos.subtract(holderTargetPos).normalize().scale(0.025f);
            Vec3 offsetPosition = VecHelper.rotatingRadialOffset(holderTargetPos, 0.5f, i, 16, gameTime, 160);
            final Consumer<LodestoneWorldParticle> behavior = p -> {
                if (level.getGameTime() > gameTime + finalI * 2 && level.getGameTime() < gameTime + (finalI + 4) * 2) {
                    p.setParticleSpeed(p.getParticleSpeed().add(velocity));
                }
            };
            var lightSpecs = spiritLightSpecs(level, offsetPosition, cyclingSpiritType);
            lightSpecs.getBuilder()
                    .addTickActor(behavior)
                    .multiplyLifetime(2.5f)
                    .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 2f)));
            lightSpecs.getBloomBuilder()
                    .addTickActor(behavior)
                    .multiplyLifetime(2f)
                    .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 1.5f)));
            lightSpecs.spawnParticles();

            var crumbles = ItemCrumbleParticleEffects.spawnItemCrumbs(level, holderTargetPos, stack);
            crumbles.getBuilder()
                    .setLifeDelay(i)
                    .addTickActor(behavior);
            crumbles.spawnParticles();
            crumbles.getBuilder().setRandomOffset(0.2f);
            crumbles.spawnParticles();
        }
