@Test
    public void testInterruptEventLoopThread() throws Exception {
        EventLoopGroup group = new NioEventLoopGroup(1);
        final NioEventLoop loop = (NioEventLoop) group.next();
        try {
            Selector selector = loop.unwrappedSelector();
            assertTrue(selector.isOpen());

            loop.submit(new Runnable() {
                @Override
                public void run() {
                    // Interrupt the thread which should not end-up in a busy spin and
                    // so the selector should not have been rebuild.
                    Thread.currentThread().interrupt();
                }
            }).syncUninterruptibly();

            assertTrue(selector.isOpen());

            final CountDownLatch latch = new CountDownLatch(2);
            loop.submit(new Runnable() {
                @Override
                public void run() {
                    latch.countDown();
                }
            }).syncUninterruptibly();

            loop.schedule(new Runnable() {
                @Override
                public void run() {
                    latch.countDown();
                }
            }, 2, TimeUnit.SECONDS).syncUninterruptibly();

            latch.await();

            assertSame(selector, loop.unwrappedSelector());
            assertTrue(selector.isOpen());
        } finally {
            group.shutdownGracefully();
        }
    }

@SuppressWarnings("deprecation")
    @Test
    public void testTaskRemovalOnShutdownThrowsNoUnsupportedOperationException() throws Exception {
        final AtomicReference<Throwable> error = new AtomicReference<>();
        final AtomicBoolean loopStarted = new AtomicBoolean();
        final Runnable task = () -> {
            // NOOP
        };
        // Just run often enough to trigger it normally.
        for (int i = 0; i < 250; i++) {
            EventLoopGroup group = new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory());
            final EventLoop loop = group.next();
            final SingleThreadEventExecutor executor = (SingleThreadEventExecutor) loop;

            Thread t = new Thread(() -> {
                try {
                    for (;;) {
                        loop.execute(task);
                        loopStarted.set(true);
                        // Don't let the queue grow without bounds if the producer is faster than the event loop,
                        // otherwise we may run into an OutOfMemoryError. Keep it non-empty so we still race with
                        // the task removal on shutdown.
                        while (executor.pendingTasks() > MAX_PENDING_TASKS && !executor.isShuttingDown()) {
                            Thread.yield();
                        }
                    }
                } catch (Throwable cause) {
                    error.set(cause);
                }
            });
            t.start();
            do {
                Thread.yield();
            } while (!loopStarted.get());
            group.shutdownNow();
            t.join();
            group.terminationFuture().syncUninterruptibly();
            assertInstanceOf(RejectedExecutionException.class, error.get());
            error.set(null);
            loopStarted.set(false);
        }
    }

@Test
    public void testCancelledPendingAcquireRunsNextTask() throws Exception {
        EventLoopGroup localGroup = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());
        Tuple t = bootstrap(localGroup);
        FixedChannelPool pool = null;
        Channel sc = null;
        Channel channel = null;
        try {
            sc = t.sb.bind(t.address).syncUninterruptibly().channel();
            pool = new FixedChannelPool(t.cb, new TestChannelPoolHandler(), 1);
            channel = pool.acquire().syncUninterruptibly().getNow();

            Future<Channel> cancelledAcquire = pool.acquire();
            localGroup.submit(() -> { }).syncUninterruptibly();
            assertFalse(cancelledAcquire.isDone());
            assertTrue(cancelledAcquire.cancel(false));

            Future<Channel> nextAcquire = pool.acquire();
            localGroup.submit(() -> { }).syncUninterruptibly();
            assertFalse(nextAcquire.isDone());

            pool.release(channel).syncUninterruptibly();
            assertTrue(nextAcquire.await(5, TimeUnit.SECONDS));
            assertTrue(nextAcquire.isSuccess());
            assertSame(channel, nextAcquire.getNow());
            assertEquals(1, pool.acquiredChannelCount());

            pool.release(nextAcquire.getNow()).syncUninterruptibly();
            assertEquals(0, pool.acquiredChannelCount());
        } finally {
            if (pool != null) {
                pool.close();
            }
            if (channel != null) {
                channel.close().syncUninterruptibly();
            }
            if (sc != null) {
                sc.close().syncUninterruptibly();
            }
            localGroup.shutdownGracefully(0, 0, TimeUnit.SECONDS).syncUninterruptibly();
        }
    }

@SuppressWarnings("unchecked")
	@Override
	public void fabric_applyPendingTagAliases() {
		if (pendingTagAliasGroups == null) return;

		Set<Set<TagKey<?>>> uniqueAliasGroups = Sets.newIdentityHashSet();
		uniqueAliasGroups.addAll(pendingTagAliasGroups.values());

		for (Set<TagKey<?>> aliasGroup : uniqueAliasGroups) {
			Set<Holder<T>> entries = Sets.newIdentityHashSet();

			// Fetch all entries from each tag.
			for (TagKey<?> tag : aliasGroup) {
				HolderSet.Named<T> entryList = allTags.get((TagKey<T>) tag).orElse(null);

				if (entryList != null) {
					entries.addAll(entryList.contents);
				} else {
					LOGGER.info("[Fabric] Creating a new empty tag {} for unknown tag used in a tag alias group in {}", tag.location(), tag.registry().identifier());
					Map<TagKey<T>, HolderSet.Named<T>> tagMap = ((MappedRegistryTagSet2Accessor<T>) allTags).fabric_getTagMap();

					if (!(tagMap instanceof HashMap<?, ?>)) {
						// Unfreeze the backing map.
						tagMap = new HashMap<>(tagMap);
						((MappedRegistryTagSet2Accessor<T>) allTags).fabric_setTagMap(tagMap);
					}

					tagMap.put((TagKey<T>) tag, createTag((TagKey<T>) tag));
				}
			}

			List<Holder<T>> entriesAsList = List.copyOf(entries);

			// Replace the old entry list contents with the merged list.
			for (TagKey<?> tag : aliasGroup) {
				HolderSet.Named<T> entryList = allTags.get((TagKey<T>) tag).orElseThrow();
				entryList.contents = entriesAsList;
			}
		}

		LOGGER.debug("[Fabric] Loaded {} tag alias groups for {}", uniqueAliasGroups.size(), key.identifier());
		pendingTagAliasGroups = null;
	}

@Overwrite
    private CompletableFuture<BitSet> createOldDataForRegion(final int x, final int z) {
        //The impl$submitTaskCancellable is related to another fix for a separate deadlock case.
        //The returned future is used inside the isOldChunkAround which tries to wait for the
        //completion but also ends up deadlocking when the IOWorker closes. This is fixed by
        //throwing a special exception when the IOWorker is no longer accepting new tasks.
        //See ChunkStatusMixin
        return this.impl$submitTaskCancellable(() -> { //Sponge: Use submitTask instead
            try {
                final ChunkPos min = ChunkPos.minFromRegion(x, z);
                final ChunkPos max = ChunkPos.maxFromRegion(x, z);
                final BitSet oldDataRegions = new BitSet();
                ChunkPos.rangeClosed(min, max).forEach(pos -> {
                    final CollectFields fields = new CollectFields(new FieldSelector(IntTag.TYPE, "DataVersion"), new FieldSelector(CompoundTag.TYPE, "blending_data"));

                    try {
                        //Sponge start: unwrapped the scanChunk content to not submit another task
                        final IOWorker$PendingStoreAccessor store = this.pendingWrites.get(pos);
                        if (store != null) {
                            if (store.accessor$data() != null) {
                                store.accessor$data().acceptAsRoot(fields);
                            }
                        } else {
                            this.storage.scanChunk(pos, fields);
                        }
                        //Sponge end
                    } catch (final Exception e) {
                        IOWorkerMixin.LOGGER.warn("Failed to scan chunk {}", pos, e);
                        return;
                    }

                    final Tag result = fields.getResult();
                    if (result instanceof final CompoundTag compoundTag && this.shadow$isOldChunk(compoundTag)) {
                        final int regionIndex = pos.getRegionLocalZ() * 32 + pos.getRegionLocalX();
                        oldDataRegions.set(regionIndex);
                    }
                });
                return Either.left(oldDataRegions);
            } catch (final Exception e) {
                return Either.right(e);
            }
        });
    }

private void runPurgeScan() {
            long generation = ++purgeGeneration;
            int retained = 0;
            ArrayList<SizeClassedChunk> deferred = deferredBuffer;
            SizeClassedChunk chunk;
            while ((chunk = queue.poll()) != null) {
                if (chunk.lastPurgeGeneration == generation) {
                    offerOrDeallocate(chunk, generation);
                    break;
                }
                retained++;
                if (chunk.hasFullCapacity()) {
                    chunk.purgeEpoch++;
                    if (chunk.purgeEpoch > CHUNK_PURGE_THRESHOLD) {
                        deferred.add(chunk);
                        continue;
                    }
                } else {
                    chunk.purgeEpoch = 0;
                }
                int remaining = chunk.remainingCapacity();
                if (remaining > 0) {
                    if (!offerOrDeallocate(chunk, generation)) {
                        retained--;
                    }
                } else {
                    deferred.add(chunk);
                }
            }
            for (int i = 0, size = deferred.size(); i < size; i++) {
                chunk = deferred.get(i);
                if (chunk.purgeEpoch > CHUNK_PURGE_THRESHOLD && retained > CHUNK_REUSE_QUEUE) {
                    chunk.markToDeallocate();
                    retained--;
                } else {
                    if (!offerOrDeallocate(chunk, generation)) {
                        retained--;
                    }
                }
            }
            deferred.clear();
            purgeBudget.lazySet(CHUNK_PURGE_POLLS_SHARED);
        }

@Test
    public void testPipelinedResponseContentPreservedAfterInterimResponse() {
        // A 1xx interim response for one pipelined request must not consume a method queue entry,
        // so the queue order is preserved for the remaining pipelined requests.
        EmbeddedChannel ch = new EmbeddedChannel(new HttpServerCodec());

        // Pipeline two requests: GET /a then HEAD /b. Method queue = [OTHER, HEAD].
        assertTrue(ch.writeInbound(Unpooled.copiedBuffer(
                "GET /a HTTP/1.1\r\nHost: a\r\n\r\n" +
                "HEAD /b HTTP/1.1\r\nHost: a\r\n\r\n", CharsetUtil.UTF_8)));

        HttpRequest requestA = ch.readInbound();
        assertEquals(HttpMethod.GET, requestA.method());
        LastHttpContent requestAContent = ch.readInbound();
        assertFalse(requestAContent.content().isReadable());
        requestAContent.release();

        HttpRequest requestB = ch.readInbound();
        assertEquals(HttpMethod.HEAD, requestB.method());
        LastHttpContent requestBContent = ch.readInbound();
        assertFalse(requestBContent.content().isReadable());
        requestBContent.release();

        // Send a 1xx interim response for /a. The queue must stay at [OTHER, HEAD].
        FullHttpResponse earlyHints = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.EARLY_HINTS);
        assertTrue(ch.writeOutbound(earlyHints));
        ByteBuf earlyHintsBuf = ch.readOutbound();
        assertEquals("HTTP/1.1 103 Early Hints\r\n\r\n", earlyHintsBuf.toString(CharsetUtil.US_ASCII));
        earlyHintsBuf.release();

        // Now send the final response to /a, with content attached.
        FullHttpResponse finalResponseA = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
                Unpooled.copiedBuffer("body-a", CharsetUtil.UTF_8));
        finalResponseA.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 6);
        assertTrue(ch.writeOutbound(finalResponseA));

        // The GET /a response body must be preserved.
        ByteBuf buf = ch.readOutbound();
        assertEquals("HTTP/1.1 200 OK\r\ncontent-length: 6\r\n\r\nbody-a", buf.toString(CharsetUtil.US_ASCII));
        buf.release();

        assertFalse(ch.finishAndReleaseAll());
    }

@Test
    @Timeout(30)
    public void testSubmittingTaskWakesUpSuspendedExecutor() throws Exception {
        EventLoopGroup group = newAutoScalingEventLoopGroup();
        if (group == null) {
            return;
        }
        try {
            startAllExecutors(group);
            assertEquals(SCALING_MAX_THREADS, countActiveExecutors(group),
                         "Group should start with max threads.");

            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
            while (countActiveExecutors(group) > SCALING_MIN_THREADS && System.nanoTime() < deadline) {
                Thread.sleep(100);
            }
            assertEquals(SCALING_MIN_THREADS, countActiveExecutors(group),
                         "Group did not scale down to min threads in time.");

            EventLoop suspendedLoop = null;
            for (EventExecutor exec : group) {
                if (exec.isSuspended()) {
                    suspendedLoop = (EventLoop) exec;
                    break;
                }
            }
            assertNotNull(suspendedLoop, "Could not find a suspended executor to test.");

            // Submit a task directly to the suspended loop, this should trigger the wake-up mechanism.
            int i = 0;
            boolean isSuspended;
            do {
                Future<?> future = suspendedLoop.submit(() -> { });
                future.sync();
            } while ((isSuspended = suspendedLoop.isSuspended()) && i++ < 10);

            assertFalse(isSuspended, "Executor should wake up after task submission.");
            assertEquals(SCALING_MAX_THREADS, countActiveExecutors(group),
                         "Active executor count should increase after wake-up.");
        } finally {
            group.shutdownGracefully().sync();
        }
    }

