@Override
  public boolean onResourcePackResponse(
          final @NotNull ResourcePackResponseBundle bundle
  ) {
    final boolean peek = bundle.status().isIntermediate();
    final ResourcePackInfo queued = peek
            ? outstandingResourcePacks.peek() : outstandingResourcePacks.poll();

    server.getEventManager()
            .fire(new PlayerResourcePackStatusEvent(
                this.player, bundle.uuid(), bundle.status(), queued))
            .thenAcceptAsync(event -> {
              if (shouldDisconnectForForcePack(event)) {
                event.getPlayer().disconnect(Component
                        .translatable("multiplayer.requiredTexturePrompt.disconnect"));
              }
            });

    switch (bundle.status()) {
      case ACCEPTED -> {
        previousResourceResponse = true;
        pendingResourcePack = queued;
      }
      case DECLINED -> previousResourceResponse = false;
      case SUCCESSFUL -> {
        appliedResourcePack = queued;
        pendingResourcePack = null;
      }
      case FAILED_DOWNLOAD -> pendingResourcePack = null;
      case DISCARDED -> {
        if (queued != null && queued.getId() != null
                && appliedResourcePack != null
                && appliedResourcePack.getId().equals(queued.getId())) {
          appliedResourcePack = null;
        }
      }
      default -> {
      }
    }

    if (!peek) {
      player.getConnection().eventLoop().execute(this::tickResourcePackQueue);
    }

    return handleResponseResult(queued, bundle);
  }

public boolean shutdown() throws InterruptedException {
    Collection<ScheduledTask> terminating;
    synchronized (tasksByPlugin) {
      terminating = ImmutableList.copyOf(tasksByPlugin.values());
    }
    for (ScheduledTask task : terminating) {
      task.cancel();
    }
    backend.shutdown();
    final List<PluginContainer> plugins = new ArrayList<>(this.pluginManager.getPlugins());
    final Iterator<PluginContainer> pluginIterator = plugins.iterator();
    while (pluginIterator.hasNext()) {
      final PluginContainer container = pluginIterator.next();
      if (container instanceof VelocityPluginContainer) {
        final VelocityPluginContainer pluginContainer = (VelocityPluginContainer) container;
        if (pluginContainer.hasExecutorService()) {
          container.getExecutorService().shutdown();
        } else {
          pluginIterator.remove();
        }
      } else {
        pluginIterator.remove();
      }
    }

    boolean allShutdown = true;
    for (final PluginContainer container : plugins) {
      final String id = container.getDescription().getId();
      final ExecutorService service = (container).getExecutorService();

      try {
        if (!service.awaitTermination(10, TimeUnit.SECONDS)) {
          service.shutdownNow();
          Log.logger.warn("Executor for plugin {} did not shut down within 10 seconds. "
              + "Continuing with shutdown...", id);
          allShutdown = false;
        }

      } catch (final InterruptedException e) {
        Log.logger.warn("Executor for plugin {} did not shut down within 10 seconds. "
            + "Continuing with shutdown...", id);
      }
    }

    return allShutdown;
  }

