                    .modifyScaleData(d -> d.multiplyValue(4f))
                    .modifyTransparencyData(d -> d.multiplyValue(3f))
                    .setLifeDelay(20);
            lightSpecs.spawnParticles();
        }
        for (int i = 0; i < 32; i++) {
            var spirit = colorData.getSpirit();
            float delta = i / 32f;
            int lifeDelay = Mth.floor(delta*20);
            Vec3 offsetPosition = VecHelper.rotatingRadialOffset(targetPos, Mth.lerp(delta, 0.7f, 0.35f), i, 16, gameTime, 160);
            var lightSpecs = spiritLightSpecs(level, offsetPosition, spirit);
            if (i % 2 == 0) {
                lightSpecs.getBuilder().act(b -> b.setColorData(b.getColorData().invert().build()));
                lightSpecs.getBloomBuilder().act(b -> b.setColorData(b.getColorData().invert().build()));
            }

            lightSpecs.getBuilder()
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(2f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .setLifeDelay(lifeDelay);
            lightSpecs.getBloomBuilder()
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(1.2f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.4f))
                    .setLifeDelay(lifeDelay);
            lightSpecs.spawnParticles();
        }
    }

@Override
    protected void consumeEventsAndMarker(
        PhaseContext<@NonNull ?> context,
        final Collection<? extends ChangeBlockEvent.All> changeBlockEvents
    ) {

        final Multimap<ResourceKey, ChangeBlockEvent.All> eventsByWorld = LinkedListMultimap.create();
        changeBlockEvents.forEach(event -> eventsByWorld.put(event.world().key(), event));

        eventsByWorld.asMap().forEach((key, events) -> {
            final Optional<ServerWorld> serverWorld = ((SpongeServer) SpongeCommon.server()).worldManager().world(key);
            if (!serverWorld.isPresent()) {
                return;
            }

            // Gather transactions that were valid
            final ArrayList<BlockTransactionReceipt> transactions = new ArrayList<>();
            for (final ChangeBlockEvent.All event : events) {
                if (event.isCancelled()) {
                    continue;
                }

                transactions.ensureCapacity(event.transactions().size());
                for (final BlockTransaction transaction : event.transactions()) {
                    if (!transaction.isValid()) {
                        continue;
                    }

                    final SpongeBlockSnapshot original = (SpongeBlockSnapshot) transaction.original();
                    final SpongeBlockSnapshot result = (SpongeBlockSnapshot) transaction.finalReplacement();
                    final Operation operation = context.getBlockOperation(original, result);
                    final BlockTransactionReceipt eventTransaction = new BlockTransactionReceipt(original, result, operation);
                    transactions.add(eventTransaction);
                    context.postBlockTransactionApplication(original.blockChange, eventTransaction);
                }
            }

            if (transactions.isEmpty()) {
                return;
            }

            final Cause cause = PhaseTracker.getInstance().currentCause();

            SpongeCommon.post(SpongeEventFactory.createChangeBlockEventPost(cause, Collections.unmodifiableList(transactions), serverWorld.get()));
        });
    }

public static boolean checkIfActive(final Entity entity) {
        // Never safe to skip fireworks or entities not yet added to chunk
        if (entity instanceof Player || entity.level().isClientSide() || entity.touchingUnloadedChunk() || entity instanceof FireworkRocketEntity) {
            return true;
        }
        final LevelChunkBridge activeChunk = ((ActiveChunkReferantBridge) entity).bridge$getActiveChunk();
        if (activeChunk == null) {
            // Should never happen but just in case for mods, always tick
            return true;
        }

        if (!activeChunk.bridge$isActive()) {
            return false;
        }

        // If in forced chunk or is player
        if (activeChunk.bridge$isPersistedChunk() || ((PlatformEntityBridge) entity).bridge$isFakePlayer() && entity instanceof ServerPlayer) {
            return true;
        }

        final long currentTick = SpongeCommon.server().getTickCount();
        final ActivationCapabilityBridge spongeEntity = (ActivationCapabilityBridge) entity;
        boolean isActive = spongeEntity.activation$getActivatedTick() >= currentTick || spongeEntity.activation$getDefaultActivationState();

        // Should this entity tick?
        if (!isActive) {
            if ((currentTick - spongeEntity.activation$getActivatedTick() - 1) % 20 == 0) {
                // Check immunities every 20 ticks.
                if (EntityActivationRange.checkEntityImmunities(entity)) {
                    // Triggered some sort of immunity, give 20 full ticks before we check again.
                    spongeEntity.activation$setActivatedTick(currentTick + 20);
                }
                isActive = true;
            }
            // Add a little performance juice to active entities. Skip 1/4 if not immune.
        } else if (!spongeEntity.activation$getDefaultActivationState() && entity.tickCount % 4 == 0 && !EntityActivationRange
            .checkEntityImmunities(entity)) {
            isActive = false;
        }

        if (isActive && !activeChunk.bridge$areNeighborsLoaded()) {
            isActive = false;
        }

        return isActive;
    }

static <T extends NetworkEvent> Consumer<T> createPacketHandler(Class<T> clazz, Map<ResourceLocation, PacketTransformer> map) {
        return event -> {
            if (event.getClass() != clazz) return;
            NetworkEvent.Context context = event.getSource().get();
            if (context.getPacketHandled()) return;
            FriendlyByteBuf buffer = event.getPayload();
            if (buffer == null) return;
            ResourceLocation type = buffer.readResourceLocation();
            PacketTransformer transformer = map.get(type);

            if (transformer != null) {
                NetworkManager.Side side = context.getDirection().getReceptionSide() == LogicalSide.CLIENT ? NetworkManager.Side.S2C : NetworkManager.Side.C2S;
                NetworkManager.PacketContext packetContext = new NetworkManager.PacketContext() {
                    @Override
                    public Player getPlayer() {
                        return getEnvironment() == Env.CLIENT ? getClientPlayer() : context.getSender();
                    }

                    @Override
                    public void queue(Runnable runnable) {
                        context.enqueueWork(runnable);
                    }

                    @Override
                    public Env getEnvironment() {
                        return context.getDirection().getReceptionSide() == LogicalSide.CLIENT ? Env.CLIENT : Env.SERVER;
                    }

                    private Player getClientPlayer() {
                        return DistExecutor.unsafeCallWhenOn(Dist.CLIENT, () -> ClientNetworkingManager::getClientPlayer);
                    }
                };
                transformer.inbound(side, type, buffer, packetContext, (side1, id1, buf1) -> {
                    NetworkReceiver networkReceiver = side == NetworkManager.Side.C2S ? C2S.get(id1) : S2C.get(id1);
                    if (networkReceiver == null) {
                        throw new IllegalArgumentException("Network Receiver not found! " + id1);
                    }
                    networkReceiver.receive(buf1, packetContext);
                });
            } else {
                LOGGER.error("Unknown message ID: " + type);
            }

            context.setPacketHandled(true);
        };
    }

@Override
        public void run() {
            for (;;) {
                fetchWatchees();
                notifyWatchees();

                // Try once again just in case notifyWatchees() triggered watch() or unwatch().
                fetchWatchees();
                notifyWatchees();

                try {
                    Thread.sleep(1000);
                } catch (InterruptedException ignore) {
                    // Ignore the interrupt; do not terminate until all tasks are run.
                }

                if (watchees.isEmpty() && pendingEntries.isEmpty()) {

                    // Mark the current worker thread as stopped.
                    // The following CAS must always success and must be uncontended,
                    // because only one watcher thread should be running at the same time.
                    boolean stopped = started.compareAndSet(true, false);
                    assert stopped;

                    // Check if there are pending entries added by watch() while we do CAS above.
                    if (pendingEntries.isEmpty()) {
                        // A) watch() was not invoked and thus there's nothing to handle
                        //    -> safe to terminate because there's nothing left to do
                        // B) a new watcher thread started and handled them all
                        //    -> safe to terminate the new watcher thread will take care the rest
                        break;
                    }

                    // There are pending entries again, added by watch()
                    if (!started.compareAndSet(false, true)) {
                        // watch() started a new watcher thread and set 'started' to true.
                        // -> terminate this thread so that the new watcher reads from pendingEntries exclusively.
                        break;
                    }

                    // watch() added an entry, but this worker was faster to set 'started' to true.
                    // i.e. a new watcher thread was not started
                    // -> keep this thread alive to handle the newly added entries.
                }
            }
        }

@ParameterizedTest
    @MethodSource("notNoneOwnerAndUnguarded")
    public void testDiscardingExceedingElementsWithRecycleAtDifferentThread(OwnerType ownerType, boolean unguarded)
            throws Exception {
        final int maxCapacity = 32;
        final AtomicInteger instancesCount = new AtomicInteger(0);

        final Recycler<HandledObject> recycler = newRecycler(ownerType, unguarded, maxCapacity, ignore ->
                instancesCount.incrementAndGet());

        // Borrow 2 * maxCapacity objects.
        final HandledObject[] array = new HandledObject[maxCapacity * 2];
        for (int i = 0; i < array.length; i++) {
            array[i] = recycler.get();
        }

        assertEquals(array.length, instancesCount.get());
        // Reset counter.
        instancesCount.set(0);

        // Recycle from other thread.
        final Thread thread = newThread(new Runnable() {
            @Override
            public void run() {
                for (HandledObject object: array) {
                    object.recycle();
                }
            }
        });
        thread.start();
        thread.join();

        assertEquals(0, instancesCount.get());

        // Borrow 2 * maxCapacity objects. Half of them should come from
        // the recycler queue, the other half should be freshly allocated.
        for (int i = 0; i < array.length; i++) {
            recycler.get();
        }

        // The implementation uses maxCapacity / 2 as limit per WeakOrderQueue
        assertTrue(array.length - maxCapacity / 2 <= instancesCount.get(),
                "The instances count (" +  instancesCount.get() + ") must be <= array.length (" + array.length
                + ") - maxCapacity (" + maxCapacity + ") / 2 as we not pool all new handles" +
                " internally");
    }

