public void executeTick() {
        final Entity thisEntity = this.entity.getHandleRaw();

        TickThread.ensureTickThread(thisEntity, "May not tick entity scheduler asynchronously");
        final List<ScheduledTask> toRun;
        synchronized (this.stateLock) {
            if (this.tickCount == RETIRED_TICK_COUNT) {
                throw new IllegalStateException("Ticking retired scheduler");
            }
            ++this.tickCount;

            if (this.scheduledList != null && !this.hasTasks()) {
                this.scheduledList.remove(this);
                this.insideScheduledList = false;
            }

            if (this.oneTimeDelayed.isEmpty()) {
                toRun = null;
            } else {
                toRun = this.oneTimeDelayed.remove(this.tickCount);
            }
        }

        if (toRun != null) {
            for (int i = 0, len = toRun.size(); i < len; ++i) {
                this.currentlyExecuting.addLast(toRun.get(i));
            }
        }

        // Note: It is allowed for the tasks executed to retire the entity in a given task.
        for (int i = 0, len = this.currentlyExecuting.size(); i < len; ++i) {
            if (!TickThread.isTickThreadFor(thisEntity)) {
                // tp has been queued sync by one of the tasks
                // in this case, we need to delay the tasks for next tick
                break;
            }
            final ScheduledTask task = this.currentlyExecuting.pollFirst();

            if (this.tickCount != RETIRED_TICK_COUNT) {
                ((Consumer<Entity>)task.run).accept(thisEntity);
            } else {
                // retired synchronously
                // note: here task is null
                break;
            }
        }
    }

@Override
        public CancelledState cancel() {
            ScheduledFuture<?> delay = null;
            CancelledState ret;
            synchronized (this) {
                switch (this.state) {
                    case STATE_ON_TIMER: {
                        delay = this.delay;
                        this.delay = null;
                        this.state = STATE_CANCELLED;
                        ret = CancelledState.CANCELLED_BY_CALLER;
                        break;
                    }
                    case STATE_SCHEDULED_EXECUTOR: {
                        this.state = STATE_CANCELLED;
                        ret = CancelledState.CANCELLED_BY_CALLER;
                        break;
                    }
                    case STATE_EXECUTING: {
                        if (!this.isRepeatingTask()) {
                            return CancelledState.RUNNING;
                        }
                        this.state = STATE_EXECUTING_CANCELLED;
                        return CancelledState.NEXT_RUNS_CANCELLED;
                    }
                    case STATE_EXECUTING_CANCELLED: {
                        return CancelledState.NEXT_RUNS_CANCELLED_ALREADY;
                    }
                    case STATE_FINISHED: {
                        return CancelledState.ALREADY_EXECUTED;
                    }
                    case STATE_CANCELLED: {
                        return CancelledState.CANCELLED_ALREADY;
                    }
                    default: {
                        throw new IllegalStateException("Unknown state: " + this.state);
                    }
                }
            }

            if (delay != null) {
                delay.cancel(false);
            }
            this.run = null;
            FoliaAsyncScheduler.this.tasks.remove(this);
            return ret;
        }

@Override
        public void accept(final Entity entity) {
            if (!this.plugin.isEnabled()) {
                // don't execute if the plugin is disabled
                this.setStateVolatile(STATE_CANCELLED);
                return;
            }

            final boolean repeating = this.isRepeatingTask();
            if (STATE_IDLE != this.compareAndExchangeStateVolatile(STATE_IDLE, STATE_EXECUTING)) {
                // cancelled
                return;
            }

            final boolean retired = entity.isRemoved();

            try {
                if (!retired) {
                    this.run.accept(this);
                } else {
                    if (this.retired != null) {
                        this.retired.run();
                    }
                }
            } catch (final Throwable throwable) {
                this.plugin.getLogger().log(Level.WARNING, "Entity task for " + this.plugin.getDescription().getFullName() + " generated an exception", throwable);
            } finally {
                boolean reschedule = false;
                 if (!repeating && !retired) {
                    this.setStateVolatile(STATE_FINISHED);
                } else if (retired || !this.plugin.isEnabled()) {
                     this.setStateVolatile(STATE_CANCELLED);
                } else if (STATE_EXECUTING == this.compareAndExchangeStateVolatile(STATE_EXECUTING, STATE_IDLE)) {
                    reschedule = true;
                } // else: cancelled repeating task

                if (!reschedule) {
                    this.run = null;
                    this.retired = null;
                } else {
                    if (!FoliaEntityScheduler.this.scheduleInternal(this, this.repeatDelay)) {
                        // the task itself must have removed the entity, so in this case we need to mark as cancelled
                        this.setStateVolatile(STATE_CANCELLED);
                    }
                }
            }
        }

@Override
    public void postBlockTransactionApplication(
        final EntityTickContext context, final BlockChange blockChange,
        final BlockTransactionReceipt transaction
    ) {
        if (blockChange == BlockChange.BREAK) {
            final Entity tickingEntity = context.getSource(Entity.class).get();
            final BlockPos blockPos = VecHelper.toBlockPos(transaction.originalBlock().position());
            final Vec3 aabbBase = VecHelper.toVanillaVector3d(transaction.originalBlock().position().toDouble());
            final List<HangingEntity> hangingEntities = ((ServerLevel) tickingEntity.world())
                .getEntitiesOfClass(HangingEntity.class, new AABB(aabbBase, aabbBase).inflate(1.1D, 1.1D, 1.1D),
                    entityIn -> {
                        if (entityIn == null) {
                            return false;
                        }

                        final BlockPos entityPos = entityIn.getPos();
                        // Hanging Neighbor Entity
                        if (entityPos.equals(blockPos.offset(0, 1, 0))) {
                            return true;
                        }

                        // Check around source block
                        final Direction entityFacing = entityIn.getDirection();

                        if (entityFacing == Direction.NORTH) {
                            return entityPos.equals(blockPos.offset(Constants.Entity.HANGING_OFFSET_NORTH));
                        } else if (entityFacing == Direction.SOUTH) {
                            return entityIn.getPos().equals(blockPos.offset(Constants.Entity.HANGING_OFFSET_SOUTH));
                        } else if (entityFacing == Direction.WEST) {
                            return entityIn.getPos().equals(blockPos.offset(Constants.Entity.HANGING_OFFSET_WEST));
                        } else if (entityFacing == Direction.EAST) {
                            return entityIn.getPos().equals(blockPos.offset(Constants.Entity.HANGING_OFFSET_EAST));
                        }
                        return false;
                    });
            for (final HangingEntity entityHanging : hangingEntities) {
                if (entityHanging instanceof ItemFrame) {
                    final ItemFrame itemFrame = (ItemFrame) entityHanging;
                    if (!itemFrame.isRemoved()) {
                        ((ItemFrameAccessor) itemFrame).invoker$dropItem((net.minecraft.world.entity.Entity) tickingEntity, true);
                    }
                    itemFrame.remove(net.minecraft.world.entity.Entity.RemovalReason.DISCARDED);
                }
            }
        }
    }

void doBeginRead() {
            if (readStatus == ReadStatus.IDLE) {
                // Don't wait for the user to request a read to notify of channel closure.
                if (readEOS && isInboundBufferEmpty()) {
                    // Double check there is nothing left to flush such as a window update frame.
                    flush();
                    closeIfReadEOSAndDrained();
                }
            } else {
                do { // Process messages until there are none left (or the user stopped requesting) and also handle EOS.
                    Object message = pollQueuedMessage();
                    if (message == null) {
                        // Double check there is nothing left to flush such as a window update frame.
                        flush();
                        if (!isInboundBufferEmpty()) {
                            // The flush re-entrantly delivered more frames which got queued; keep reading if we
                            // still should.
                            continue;
                        }
                        closeIfReadEOSAndDrained();
                        break;
                    }
                    final RecvByteBufAllocator.Handle allocHandle = recvBufAllocHandle();
                    allocHandle.reset(config());
                    boolean continueReading = false;
                    do {
                        doRead0((Http2Frame) message, allocHandle);
                    } while ((readEOS || (continueReading = allocHandle.continueReading()))
                            && (message = pollQueuedMessage()) != null);

                    if (continueReading && isParentReadInProgress() && !readEOS) {
                        // Currently the parent and child channel are on the same EventLoop thread. If the parent is
                        // currently reading it is possible that more frames will be delivered to this child channel. In
                        // the case that this child channel still wants to read we delay the channelReadComplete on this
                        // child channel until the parent is done reading.
                        maybeAddChannelToReadCompletePendingQueue();
                    } else {
                        notifyReadComplete(allocHandle, true, true);

                        // While in the read loop reset the readState AFTER calling readComplete (or other pipeline
                        // callbacks) to prevents re-entry into this method (if autoRead is disabled and the user calls
                        // read on each readComplete) and StackOverflowException.
                        resetReadStatus();
                    }
                } while (readStatus != ReadStatus.IDLE);
            }
        }

@Test
    public void flowControlledWriteCompleteThrowsAnException() throws Exception {
        final Http2RemoteFlowController.FlowControlled flowControlled =
                mock(Http2RemoteFlowController.FlowControlled.class);
        Http2Stream streamA = stream(STREAM_A);
        final AtomicInteger size = new AtomicInteger(150);
        doAnswer(new Answer<Integer>() {
            @Override
            public Integer answer(InvocationOnMock invocationOnMock) throws Throwable {
                return size.get();
            }
        }).when(flowControlled).size();
        doAnswer(new Answer<Void>() {
            @Override
            public Void answer(InvocationOnMock invocationOnMock) throws Throwable {
                size.addAndGet(-50);
                return null;
            }
        }).when(flowControlled).write(any(ChannelHandlerContext.class), anyInt());

        final Http2Stream stream = stream(STREAM_A);
        doAnswer(new Answer<Void>() {
            @Override
            public Void answer(InvocationOnMock invocationOnMock) {
                throw new RuntimeException("writeComplete failed");
            }
        }).when(flowControlled).writeComplete();

        int windowBefore = window(STREAM_A);

        controller.addFlowControlled(stream, flowControlled);
        controller.writePendingBytes();

        verify(flowControlled, times(3)).write(any(ChannelHandlerContext.class), anyInt());
        verify(flowControlled, never()).error(any(ChannelHandlerContext.class), any(Throwable.class));
        verify(flowControlled).writeComplete();

        assertEquals(150, windowBefore - window(STREAM_A));
        verify(listener, times(1)).writabilityChanged(streamA);
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(streamA));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
    }

@Test
    @Timeout(value = 30, unit = TimeUnit.SECONDS)
    void testSuspendDoesNotRaceWithCancelledScheduledTask() throws Exception {
        // Regression test: cancelling a scheduled task right as the executor is about to suspend used to
        // be able to race with the suspend confirmation in doStartThread(). The cancelled task schedules
        // its own removal via scheduleRemoveScheduled(), which can land in the task queue in the tiny
        // window between run() deciding it can suspend and doStartThread() re-checking canSuspend().
        // That caused the executor to treat the situation as if run() returned without confirming
        // shutdown, spuriously shutting itself down instead of suspending (or continuing to run).
        // The race is timing dependent, so we repeat the scenario many times to make a regression likely
        // to be caught.
        for (int i = 0; i < 2000; i++) {
            TestThreadFactory threadFactory = new TestThreadFactory();
            final SingleThreadEventExecutor executor = new SuspendingSingleThreadEventExecutor(threadFactory);

            Future<?> future = executor.schedule(() -> { }, 1, TimeUnit.DAYS);
            TestThread currentThread = threadFactory.threads.take();
            currentThread.awaitStarted();
            currentThread.awaitRunnableExecution();
            assertTrue(executor.trySuspend(), "iteration " + i);

            assertTrue(future.cancel(false), "iteration " + i);
            future.await();

            long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(2);
            while (!executor.trySuspend()) {
                if (System.nanoTime() > deadline) {
                    fail("executor got stuck instead of suspending at iteration " + i
                            + " (isShutdown=" + executor.isShutdown() + ')');
                }
                Thread.sleep(1);
            }

            currentThread.join(TimeUnit.SECONDS.toMillis(2));
            assertFalse(currentThread.isAlive(), "worker thread did not terminate at iteration " + i);

            assertTrue(executor.trySuspend(), "iteration " + i + " (isShutdown=" + executor.isShutdown() + ')');
            assertTrue(executor.isSuspended(), "iteration " + i);

            executor.shutdownGracefully(0, 0, TimeUnit.MILLISECONDS).syncUninterruptibly();

            TestThread t;
            while ((t = threadFactory.threads.poll()) != null) {
                t.join();
            }
        }
    }

private static void testRemoval(boolean typed) {
        PriorityQueue<TestElement> queue = new DefaultPriorityQueue<>(TestElementComparator.INSTANCE, 4);
        assertEmptyQueue(queue);

        TestElement a = new TestElement(5);
        TestElement b = new TestElement(10);
        TestElement c = new TestElement(2);
        TestElement d = new TestElement(6);
        TestElement notInQueue = new TestElement(-1);

        assertOffer(queue, a);
        assertOffer(queue, b);
        assertOffer(queue, c);
        assertOffer(queue, d);

        // Remove an element that isn't in the queue.
        assertFalse(typed ? queue.removeTyped(notInQueue) : queue.remove(notInQueue));
        assertSame(c, queue.peek());
        assertEquals(4, queue.size());

        // Remove the last element in the array, when the array is non-empty.
        assertTrue(typed ? queue.removeTyped(b) : queue.remove(b));
        assertSame(c, queue.peek());
        assertEquals(3, queue.size());

        // Re-insert the element after removal
        assertOffer(queue, b);
        assertSame(c, queue.peek());
        assertEquals(4, queue.size());

        // Repeat remove the last element in the array, when the array is non-empty.
        assertTrue(typed ? queue.removeTyped(d) : queue.remove(d));
        assertSame(c, queue.peek());
        assertEquals(3, queue.size());

        assertTrue(typed ? queue.removeTyped(b) : queue.remove(b));
        assertSame(c, queue.peek());
        assertEquals(2, queue.size());

        // Remove the head of the queue.
        assertTrue(typed ? queue.removeTyped(c) : queue.remove(c));
        assertSame(a, queue.peek());
        assertEquals(1, queue.size());

        assertTrue(typed ? queue.removeTyped(a) : queue.remove(a));
        assertEmptyQueue(queue);
    }

private static void testResolveTryWithoutSearchDomainFirst(
            DnsNameResolverChannelStrategy strategy, final boolean absoluteSuccess) throws Exception {
        final String addressString = "10.0.0.1";
        final Queue<String> names = new ConcurrentLinkedQueue<String>();
        final TestDnsServer dnsServer2 = new TestDnsServer(new RecordStore() {
            private int called;
            @Override
            public Set<ResourceRecord> getRecords(QuestionRecord question) {
                names.offer(question.getDomainName());
                ++called;
                if ((absoluteSuccess && called == 1) || called == 3) {
                    ResourceRecordModifier rm = new ResourceRecordModifier();
                    rm.setDnsClass(RecordClass.IN);
                    rm.setDnsName(question.getDomainName());
                    rm.setDnsTtl(100);

                    rm.setDnsType(question.getRecordType());
                    rm.put(DnsAttribute.IP_ADDRESS, addressString);
                    return Collections.singleton(rm.getEntry());
                }
                return null;
            }
        });
        dnsServer2.start();

        DnsNameResolver resolver = newResolver(strategy).searchDomains(
                        Arrays.asList("search1.netty.io", "search2.netty.io", "search3.netty.io"))
                .ndots(1).nameServerProvider(new SingletonDnsServerAddressStreamProvider(dnsServer2.localAddress()))
                .resolvedAddressTypes(ResolvedAddressTypes.IPV4_ONLY)
                .build();

        byte[] bytes =  NetUtil.createByteArrayFromIpAddressString(addressString);
        InetAddress inetAddress = InetAddress.getByAddress(bytes);
        try {
            final InetAddress addr = resolver.resolve("netty.io").sync().getNow();
            assertEquals(inetAddress, addr);
        } finally {
            resolver.close();
            dnsServer2.stop();
            assertEquals("netty.io", names.poll());
            if (!absoluteSuccess) {
                assertEquals("netty.io.search1.netty.io", names.poll());
                assertEquals("netty.io.search2.netty.io", names.poll());
            }
            assertTrue(names.isEmpty());
        }
    }

@Override
        public void connect(final SocketAddress remoteAddress,
                SocketAddress localAddress, final ChannelPromise promise) {
            if (!promise.setUncancellable() || !ensureOpen(promise)) {
                return;
            }

            if (state == State.CONNECTED) {
                Exception cause = new AlreadyConnectedException();
                safeSetFailure(promise, cause);
                return;
            }

            if (connectPromise != null) {
                throw new ConnectionPendingException();
            }

            connectPromise = promise;

            if (state != State.BOUND) {
                // Not bound yet and no localAddress specified - get one.
                if (localAddress == null) {
                    localAddress = new LocalAddress(LocalChannel.this);
                }
            }

            if (localAddress != null) {
                try {
                    doBind(localAddress);
                } catch (Throwable t) {
                    safeSetFailure(promise, t);
                    close(voidPromise());
                    return;
                }
            }

            Channel boundChannel = LocalChannelRegistry.get(remoteAddress);
            if (!(boundChannel instanceof LocalServerChannel)) {
                Exception cause = new ConnectException("connection refused: " + remoteAddress);
                safeSetFailure(promise, cause);
                close(voidPromise());
                return;
            }

            LocalServerChannel serverChannel = (LocalServerChannel) boundChannel;
            peer = serverChannel.serve(LocalChannel.this);
        }

public static void init() {
		PayloadTypeRegistry.serverboundConfiguration().register(CommonVersionPayload.TYPE, CommonVersionPayload.CODEC);
		PayloadTypeRegistry.clientboundConfiguration().register(CommonVersionPayload.TYPE, CommonVersionPayload.CODEC);
		PayloadTypeRegistry.serverboundPlay().register(CommonVersionPayload.TYPE, CommonVersionPayload.CODEC);
		PayloadTypeRegistry.clientboundPlay().register(CommonVersionPayload.TYPE, CommonVersionPayload.CODEC);
		PayloadTypeRegistry.serverboundConfiguration().register(CommonRegisterPayload.TYPE, CommonRegisterPayload.CODEC);
		PayloadTypeRegistry.clientboundConfiguration().register(CommonRegisterPayload.TYPE, CommonRegisterPayload.CODEC);
		PayloadTypeRegistry.serverboundPlay().register(CommonRegisterPayload.TYPE, CommonRegisterPayload.CODEC);
		PayloadTypeRegistry.clientboundPlay().register(CommonRegisterPayload.TYPE, CommonRegisterPayload.CODEC);

		ServerConfigurationNetworking.registerGlobalReceiver(CommonVersionPayload.TYPE, (payload, context) -> {
			ServerConfigurationNetworkAddon addon = ServerNetworkingImpl.getAddon(context.packetListener());
			addon.onCommonVersionPacket(getNegotiatedVersion(payload));
			context.packetListener().completeTask(CommonVersionConfigurationTask.KEY);
		});

		ServerConfigurationNetworking.registerGlobalReceiver(CommonRegisterPayload.TYPE, (payload, context) -> {
			ServerConfigurationNetworkAddon addon = ServerNetworkingImpl.getAddon(context.packetListener());

			if (CommonRegisterPayload.PLAY_PROTOCOL.equals(payload.protocol())) {
				if (payload.version() != addon.getNegotiatedVersion()) {
					throw new IllegalStateException("Negotiated common packet version: %d but received packet with version: %d".formatted(addon.getNegotiatedVersion(), payload.version()));
				}

				// Play phase hasnt started yet, add them to the pending names.
				addon.getChannelInfoHolder().fabric_getPendingChannelsNames(ConnectionProtocol.PLAY).addAll(payload.channels());
				NetworkingImpl.LOGGER.debug("Received accepted channels from the client for play phase");
			} else {
				addon.onCommonRegisterPacket(payload);
			}

			context.packetListener().completeTask(CommonRegisterConfigurationTask.KEY);
		});

		// Create a configuration task to send and receive the common packets
		ServerConfigurationConnectionEvents.CONFIGURE.register((listener, server) -> {
			final ServerConfigurationNetworkAddon addon = ServerNetworkingImpl.getAddon(listener);

			if (ServerConfigurationNetworking.canSend(listener, CommonVersionPayload.TYPE)) {
				// Tasks are processed in order.
				listener.addTask(new CommonVersionConfigurationTask(addon));

				if (ServerConfigurationNetworking.canSend(listener, CommonRegisterPayload.TYPE)) {
					listener.addTask(new CommonRegisterConfigurationTask(addon));
				}
			}
		});
	}

