static RingBuffer createRingBuffer(int ringSize, int cqeSize, int setupFlags) {
        ObjectUtil.checkPositive(ringSize, "ringSize");
        ObjectUtil.checkPositive(cqeSize, "cqeSize");
        long[] values = ioUringSetup(ringSize, cqeSize, setupFlags);
        assert values.length == 20;
        long cqkhead = values[0];
        long cqktail = values[1];
        int cqringMask = (int) values[2];
        int cqringEntries = (int) values[3];
        long cqkflags = values[4];
        long cqArrayAddress = values[5];
        int cqringSize = (int) values[6];
        long cqringAddress = values[7];
        int cqringFd = (int) values[8];
        int cqringCapacity = (int) values[9];
        int cqeLength = (setupFlags & IORING_SETUP_CQE32) == 0 ? CQE_SIZE : CQE32_SIZE;
        boolean extraCqeDataNeeded = (setupFlags & (IORING_SETUP_CQE32 | IORING_SETUP_CQE_MIXED)) != 0;
        CompletionQueue completionQueue = new CompletionQueue(
                Buffer.wrapMemoryAddressWithNativeOrder(cqkhead, Integer.BYTES),
                Buffer.wrapMemoryAddressWithNativeOrder(cqktail, Integer.BYTES),
                cqringMask,
                cqringEntries,
                Buffer.wrapMemoryAddressWithNativeOrder(cqkflags, Integer.BYTES),
                Buffer.wrapMemoryAddressWithNativeOrder(cqArrayAddress, cqringEntries * cqeLength),
                cqringSize,
                cqringAddress,
                cqringFd,
                cqringCapacity, cqeLength, extraCqeDataNeeded);

        long sqkhead = values[10];
        long sqktail = values[11];
        int sqringMask = (int) values[12];
        int sqringEntries = (int) values[13];
        long sqkflags = values[14];
        long sqArrayAddress = values[15];
        int sqringSize = (int) values[16];
        long sqringAddress = values[17];
        int sqringFd = (int) values[18];
        SubmissionQueue submissionQueue = new SubmissionQueue(
                Buffer.wrapMemoryAddressWithNativeOrder(sqkhead, Integer.BYTES),
                Buffer.wrapMemoryAddressWithNativeOrder(sqktail, Integer.BYTES),
                sqringMask,
                sqringEntries,
                Buffer.wrapMemoryAddressWithNativeOrder(sqkflags, Integer.BYTES),
                Buffer.wrapMemoryAddressWithNativeOrder(sqArrayAddress, sqringEntries * SubmissionQueue.SQE_SIZE),
                sqringSize,
                sqringAddress,
                sqringFd);
        return new RingBuffer(submissionQueue, completionQueue, (int) values[19]);
    }

@ParameterizedTest
    @EnumSource(CqeSize.class)
    public void testCqe(CqeSize cqeSize) {
        assumeTrue(Native.ioUringSetupSupportsFlags(cqeSize.setupFlag()));

        RingBuffer ringBuffer = Native.createRingBuffer(8, cqeSize.setupFlag());
        ringBuffer.enable();
        try {
            SubmissionQueue submissionQueue = ringBuffer.ioUringSubmissionQueue();
            final CompletionQueue completionQueue = ringBuffer.ioUringCompletionQueue();

            assertNotNull(ringBuffer);
            assertNotNull(submissionQueue);
            assertNotNull(completionQueue);

            long result;
            if (cqeSize == CqeSize.MIXED) {
                result = submissionQueue.addNop((byte) 0, Native.IORING_NOP_CQE32, 1);
            } else {
                result = submissionQueue.addNop((byte) 0, 1);
            }
            assertThat(result).isNotZero();
            assertThat(submissionQueue.addNop((byte) 0, 1)).isNotZero();

            assertEquals(2, submissionQueue.submitAndGet());
            assertEquals(cqeSize == CqeSize.MIXED ? 3 : 2, completionQueue.count());
            long packed = completionQueue.process(new CompletionCallback() {
                private boolean first = true;
                @Override
                public boolean handle(int res, int flags, long udata, ByteBuffer extraCqeData) {
                    assertEquals(0, res);
                    assertEquals(cqeSize == CqeSize.MIXED && first ? Native.IORING_CQE_F_32 : 0, flags);
                    assertEquals(1, udata);
                    if (cqeSize == CqeSize.LARGE || (cqeSize == CqeSize.MIXED && first)) {
                        assertNotNull(extraCqeData);
                        assertEquals(0, extraCqeData.position());
                        assertEquals(16, extraCqeData.limit());
                    } else {
                        assertNull(extraCqeData);
                    }
                    first = false;
                    return true;
                }
            });
            assertEquals(2, (int) (packed >>> 32));
            assertFalse(completionQueue.hasCompletions());
        } finally {
            ringBuffer.close();
        }
    }

@Override
    public Future<Void> close(final Promise<Void> promise) {
        checkNotNull(promise, "promise");
        // Since we allow this method to be called multiple times, we must make sure that all the promises are notified
        // when all streams are removed and the close operation completes.
        if (closePromise != null) {
            if (closePromise == promise) {
                // Do nothing
            } else if (promise instanceof ChannelPromise && ((ChannelFuture) closePromise).isVoid()) {
                closePromise = promise;
            } else {
                PromiseNotifier.cascade(closePromise, promise);
            }
        } else {
            closePromise = promise;
        }
        if (isStreamMapEmpty()) {
            promise.trySuccess(null);
            return promise;
        }

        Iterator<PrimitiveEntry<Http2Stream>> itr = streamMap.entries().iterator();
        // We must take care while iterating the streamMap as to not modify while iterating in case there are other code
        // paths iterating over the active streams.
        if (activeStreams.allowModifications()) {
            activeStreams.incrementPendingIterations();
            try {
                while (itr.hasNext()) {
                    DefaultStream stream = (DefaultStream) itr.next().value();
                    if (stream.id() != CONNECTION_STREAM_ID) {
                        // If modifications of the activeStream map is allowed, then a stream close operation will also
                        // modify the streamMap. Pass the iterator in so that remove will be called to prevent
                        // concurrent modification exceptions.
                        stream.close(itr);
                    }
                }
            } finally {
                activeStreams.decrementPendingIterations();
            }
        } else {
            while (itr.hasNext()) {
                Http2Stream stream = itr.next().value();
                if (stream.id() != CONNECTION_STREAM_ID) {
                    // We are not allowed to make modifications, so the close calls will be executed after this
                    // iteration completes.
                    stream.close();
                }
            }
        }
        return closePromise;
    }

@Test
    public void testAutoReadDisabledDuringDequeueStopsDelivery() throws Exception {
        final UpstreamReadCounter upstream = new UpstreamReadCounter();
        final AtomicInteger reads = new AtomicInteger();
        final AtomicInteger readCompletes = new AtomicInteger();
        final EmbeddedChannel channel = new EmbeddedChannel(false, false,
                upstream,
                new FlowControlHandler(),
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        reads.incrementAndGet();
                        ctx.channel().config().setAutoRead(false);
                    }

                    @Override
                    public void channelReadComplete(ChannelHandlerContext ctx) {
                        readCompletes.incrementAndGet();
                    }
                });
        channel.config().setAutoRead(false);
        channel.register();

        // Begin with auto-read on while the queue is empty: that forwards a single read upstream and delivers
        // nothing.
        channel.config().setAutoRead(true);
        assertEquals(0, reads.get());
        assertEquals(1, upstream.reads.get());

        // Messages now arrive with auto-read on. The handler disables auto-read while processing the first, so
        // messages 2..5 stay queued: delivery stops after one and the cycle completes once (from channelRead).
        channel.writeInbound("1", "2", "3", "4", "5");
        assertEquals(1, reads.get());
        assertEquals(1, readCompletes.get());
        assertEquals(1, upstream.reads.get());

        // A trailing upstream channelReadComplete (auto-read off, no read outstanding) is dropped.
        channel.flushInbound();
        assertEquals(1, readCompletes.get());

        // Resume: re-enabling auto-read starts draining the four queued messages, but the handler disables it
        // again while processing the first. The dequeue must observe the renewed setAutoRead(false), release
        // exactly one more, and complete once (from read()). The message was served from the queue, so nothing
        // is read further upstream.
        channel.config().setAutoRead(true);
        assertEquals(2, reads.get());
        assertEquals(2, readCompletes.get());
        assertEquals(1, upstream.reads.get());

        assertFalse(channel.finishAndReleaseAll());
    }

private Future<List<DnsRecord>> resolveAll(final DnsQuestion question, final DnsRecord[] additionals,
                                               final Promise<List<DnsRecord>> promise) {
        checkNotNull(question, "question");
        checkNotNull(promise, "promise");

        // Respect /etc/hosts as well if the record type is A or AAAA.
        final DnsRecordType type = question.type();
        final String hostname = question.name();

        if (type == DnsRecordType.A || type == DnsRecordType.AAAA) {
            final List<InetAddress> hostsFileEntries = resolveHostsFileEntries(hostname);
            if (hostsFileEntries != null) {
                List<DnsRecord> result = new ArrayList<DnsRecord>();
                for (InetAddress hostsFileEntry : hostsFileEntries) {
                    ByteBuf content = null;
                    if (hostsFileEntry instanceof Inet4Address) {
                        if (type == DnsRecordType.A) {
                            content = Unpooled.wrappedBuffer(hostsFileEntry.getAddress());
                        }
                    } else if (hostsFileEntry instanceof Inet6Address) {
                        if (type == DnsRecordType.AAAA) {
                            content = Unpooled.wrappedBuffer(hostsFileEntry.getAddress());
                        }
                    }
                    if (content != null) {
                        // Our current implementation does not support reloading the hosts file,
                        // so use a fairly large TTL (1 day, i.e. 86400 seconds).
                        result.add(new DefaultDnsRawRecord(hostname, type, 86400, content));
                    }
                }

                if (!result.isEmpty()) {
                    if (!trySuccess(promise, result)) {
                        // We were not able to transfer ownership, release the records to prevent leaks.
                        for (DnsRecord r: result) {
                            ReferenceCountUtil.safeRelease(r);
                        }
                    }
                    return promise;
                }
            }
        }

        ChannelFuture f = resolveChannelProvider.nextResolveChannel(promise);
        if (f.isDone()) {
            resolveAllNow(f, hostname, question, additionals, promise);
        } else {
            f.addListener((ChannelFutureListener) f1 -> resolveAllNow(f1, hostname, question, additionals, promise));
        }
        return promise;
    }

@ApiStatus.Internal
    public void doConfiguration(Player player, boolean isFirstConfig) {
        assert ServerProperties.INSIDE_TEST.get() || Thread.currentThread().isVirtual();
        if (isFirstConfig) {
            configurationPlayers.add(player);
            keepAlivePlayers.add(player);
        }
        player.sendPacket(PluginMessagePacket.brandPacket(MinecraftServer.getBrandName()));
        // Request known packs immediately, but don't wait for the response until required (sending registry data).
        final var knownPacksFuture = player.getPlayerConnection().requestKnownPacks(List.of(SelectKnownPacksPacket.MINECRAFT_CORE));

        var event = new AsyncPlayerConfigurationEvent(player, isFirstConfig);
        EventDispatcher.call(event);
        if (!player.isOnline()) return; // Player was kicked during config.

        // send player features that were enabled or disabled during async config event
        player.sendPacket(new UpdateEnabledFeaturesPacket(event.getFeatureFlags().stream().map(StaticProtocolObject::name).toList()));

        final Instance spawningInstance = event.getSpawningInstance();
        Objects.requireNonNull(spawningInstance, "You need to specify a spawning instance in the AsyncPlayerConfigurationEvent");

        if (event.willClearChat()) player.sendPacket(new ResetChatPacket());

        // Registry data (if it should be sent)
        if (event.willSendRegistryData()) {
            List<SelectKnownPacksPacket.Entry> knownPacks;
            try {
                knownPacks = knownPacksFuture.get(ServerProperties.KNOWN_PACKS_RESPONSE_TIMEOUT.get(), TimeUnit.MILLISECONDS);
            } catch (InterruptedException | TimeoutException _) {
                LOGGER.warn("Player {} failed to respond to known packs query", player.getUsername());
                player.getPlayerConnection().disconnect();
                return;
            } catch (ExecutionException e) {
                throw new RuntimeException("Error receiving known packs", e);
            }
            boolean excludeVanilla = knownPacks.contains(SelectKnownPacksPacket.MINECRAFT_CORE);

            Registries registries = MinecraftServer.getRegistries();
            player.sendPackets(Registries.registryDataPackets(registries, excludeVanilla));
            // TODO: TEST_ENVIRONMENT, TEST_INSTANCE

            sendRegistryTags(player);
        }

        // Wait for pending resource packs if any
        var packFuture = player.getResourcePackFuture();
        if (packFuture != null) packFuture.join();

        keepAlivePlayers.remove(player);
        player.setPendingOptions(spawningInstance, event.isHardcore());
        player.sendPacket(new FinishConfigurationPacket());
    }

@Test
    public void chunkUpdateDebounceTest(Env env) {
        final Instance flatInstance = env.createFlatInstance();
        final int viewDiameter = (ServerProperties.CHUNK_VIEW_DISTANCE.get() + 1) * 2 + 1;
        // Preload all possible chunks to avoid issues due to async loading
        Set<CompletableFuture<Chunk>> chunks = new HashSet<>();
        ChunkRange.chunksInRange(0, 0, viewDiameter + 2, (x, z) -> chunks.add(flatInstance.loadChunk(x, z)));
        CompletableFuture.allOf(chunks.toArray(CompletableFuture[]::new)).join();
        final TestConnection connection = env.createConnection();
        Collector<ChunkDataPacket> chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        final Player player = connection.connect(flatInstance, new Pos(0.5, 40, 0.5));
        // Initial join
        chunkDataPacketCollector.assertCount(ChunkRange.chunksCount(player.effectiveViewDistance()));
        player.addPacketToQueue(new ClientTeleportConfirmPacket(player.getLastSentTeleportId()));

        // Move to next chunk
        chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        player.addPacketToQueue(new ClientPlayerPositionPacket(new Vec(-0.5, 40, 0.5), true, false));
        player.interpretPacketQueue();
        chunkDataPacketCollector.assertCount(viewDiameter);

        // Move to next chunk
        chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        player.addPacketToQueue(new ClientPlayerPositionPacket(new Vec(-0.5, 40, -0.5), true, false));
        player.interpretPacketQueue();
        chunkDataPacketCollector.assertCount(viewDiameter);

        // Move to next chunk
        chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        player.addPacketToQueue(new ClientPlayerPositionPacket(new Vec(0.5, 40, -0.5), true, false));
        player.interpretPacketQueue();
        chunkDataPacketCollector.assertCount(viewDiameter);

        // Move to next chunk
        chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        player.addPacketToQueue(new ClientPlayerPositionPacket(new Vec(0.5, 40, 0.5), true, false));
        player.interpretPacketQueue();
        chunkDataPacketCollector.assertEmpty();

        // Move to next chunk
        chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        player.addPacketToQueue(new ClientPlayerPositionPacket(new Vec(0.5, 40, -0.5), true, false));
        player.interpretPacketQueue();
        chunkDataPacketCollector.assertEmpty();

        // Move to next chunk
        chunkDataPacketCollector = connection.trackIncoming(ChunkDataPacket.class);
        // Abuse the fact that there is no delta check
        player.addPacketToQueue(new ClientPlayerPositionPacket(new Vec(16.5, 40, -16.5), true, false));
        player.interpretPacketQueue();
        chunkDataPacketCollector.assertCount(viewDiameter * 2 - 1);
    }

@TestHolder(description = "Regression test for neoforged/Neoforge#2728", enabledByDefault = true)
    static void pseudoEmptyAttachmentSerialization(DynamicTest test, RegistrationHelper reg) {
        record EmptyObject(int value) {}

        class TestAttachmentHolder extends AttachmentHolder {
            public void deserialize(ValueInput input) {
                // Deserialize is protected final, so we need a wrapper method
                this.deserializeAttachments(input);
            }
        }

        var nullableAttachment = reg.attachments()
                .register("nullable_attachment", () -> AttachmentType.builder(() -> new EmptyObject(1))
                        .serialize(RecordCodecBuilder.mapCodec(
                                instance -> instance.group(
                                        Codec.INT.optionalFieldOf("value", 0).forGetter(EmptyObject::value)).apply(instance, EmptyObject::new)))
                        .build());

        test.framework().modEventBus().addListener((FMLLoadCompleteEvent event) -> event.enqueueWork(() -> {
            // Serialize and deserialize object
            var lookup = RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);

            var originalHolder = new TestAttachmentHolder();
            originalHolder.setData(nullableAttachment, new EmptyObject(0));

            var output = TagValueOutput.createWithContext(ProblemReporter.DISCARDING, lookup);
            originalHolder.serializeAttachments(output);

            var anotherHolder = new TestAttachmentHolder();
            try {
                // Try to deserialize
                anotherHolder.deserialize(TagValueInput.create(ProblemReporter.DISCARDING, lookup, output.buildResult()));
            } catch (Exception e) {
                // If an exception is thrown
                test.fail(e.getMessage());
            }

            // Check if deserialized successfully
            if (!anotherHolder.hasData(nullableAttachment)) {
                test.fail("Unable to find nullable attachment data after deserialiation.");
            }

            // Check if data matches original
            if (!Objects.equals(
                    originalHolder.getData(nullableAttachment).value,
                    anotherHolder.getData(nullableAttachment).value)) {
                test.fail("Data from holder does not match after serialization loop.");
            }

            test.pass();
        }));
    }

private void shutdown0(long quietPeriod, long timeout, int shutdownState) {
        if (isShuttingDown()) {
            return;
        }

        boolean inEventLoop = inEventLoop();
        boolean wakeup;
        int oldState;
        for (;;) {
            if (isShuttingDown()) {
                return;
            }
            int newState;
            wakeup = true;
            oldState = state;
            if (inEventLoop) {
                newState = shutdownState;
            } else {
                switch (oldState) {
                    case ST_NOT_STARTED:
                    case ST_STARTED:
                    case ST_SUSPENDING:
                    case ST_SUSPENDED:
                        newState = shutdownState;
                        break;
                    default:
                        newState = oldState;
                        wakeup = false;
                }
            }
            if (STATE_UPDATER.compareAndSet(this, oldState, newState)) {
                break;
            }
        }
        if (quietPeriod != -1) {
            gracefulShutdownQuietPeriod = quietPeriod;
        }
        if (timeout != -1) {
            gracefulShutdownTimeout = timeout;
        }

        if (ensureThreadStarted(oldState)) {
            return;
        }

        if (wakeup) {
            taskQueue.offer(WAKEUP_TASK);
            if (!addTaskWakesUp) {
                wakeup(inEventLoop);
            }
        }
    }

@Test
    @Timeout(value = 10000, unit = TimeUnit.MILLISECONDS)
    public void testClientHandshakerForceClose() throws Exception {
        final WebSocketClientHandshaker handshaker = WebSocketClientHandshakerFactory.newHandshaker(
                new URI("ws://localhost:1234/test"), WebSocketVersion.V13, null, true,
                EmptyHttpHeaders.INSTANCE, Integer.MAX_VALUE, true, false, 20);

        EmbeddedChannel serverChannel = createServerChannel(
                new CloseNoOpServerProtocolHandler("/test"),
                new SimpleChannelInboundHandler<Object>() {
                    @Override
                    protected void channelRead0(ChannelHandlerContext ctx, Object msg) throws Exception {
                    }
                });

        EmbeddedChannel clientChannel = createClientChannel(handshaker, new SimpleChannelInboundHandler<Object>() {
            @Override
            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                if (evt == ClientHandshakeStateEvent.HANDSHAKE_COMPLETE) {
                    ctx.channel().closeFuture().addListener(future -> clientForceClosed = true);
                    handshaker.close(ctx.channel(), new CloseWebSocketFrame());
                }
            }
            @Override
            protected void channelRead0(ChannelHandlerContext ctx, Object msg) throws Exception {
            }
        });

        // Transfer the handshake from the client to the server
        transferAllDataWithMerge(clientChannel, serverChannel);
        // Transfer the handshake from the server to client
        transferAllDataWithMerge(serverChannel, clientChannel);

        // Transfer closing handshake
        transferAllDataWithMerge(clientChannel, serverChannel);
        assertTrue(serverReceivedCloseHandshake);
        // Should not be closed yet as we disabled closing the connection on the server
        assertFalse(clientForceClosed);

        while (!clientForceClosed) {
            Thread.sleep(10);
            // We need to run all pending tasks as the force close timeout is scheduled on the EventLoop.
            clientChannel.runPendingTasks();
        }

        // clientForceClosed would be set to TRUE after any close,
        // so check here that force close timeout was actually fired
        assertTrue(handshaker.isForceCloseComplete());

        // Both should be empty
        assertFalse(serverChannel.finishAndReleaseAll());
        assertFalse(clientChannel.finishAndReleaseAll());
    }

@Test
    @Timeout(value = 5000, unit = TimeUnit.MILLISECONDS)
    public void testNonApplicationDataFailureFailsQueuedWrites() throws NoSuchAlgorithmException, InterruptedException {
        final CountDownLatch writeLatch = new CountDownLatch(1);
        final Queue<ChannelPromise> writesToFail = new ConcurrentLinkedQueue<ChannelPromise>();
        SSLEngine engine = newClientModeSSLEngine();
        SslHandler handler = new SslHandler(engine) {
            @Override
            public void write(final ChannelHandlerContext ctx, Object msg, ChannelPromise promise) throws Exception {
                super.write(ctx, msg, promise);
                writeLatch.countDown();
            }
        };
        EmbeddedChannel ch = new EmbeddedChannel(new ChannelDuplexHandler() {
            @Override
            public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                if (msg instanceof ByteBuf) {
                    if (((ByteBuf) msg).isReadable()) {
                        writesToFail.add(promise);
                    } else {
                        promise.setSuccess();
                    }
                }
                ReferenceCountUtil.release(msg);
            }
        }, handler);

        try {
            final CountDownLatch writeCauseLatch = new CountDownLatch(1);
            final AtomicReference<Throwable> failureRef = new AtomicReference<Throwable>();
            ch.write(Unpooled.wrappedBuffer(new byte[]{1})).addListener(future -> {
                failureRef.compareAndSet(null, future.cause());
                writeCauseLatch.countDown();
            });
            writeLatch.await();

            // Simulate failing the SslHandler non-application writes after there are applications writes queued.
            ChannelPromise promiseToFail;
            while ((promiseToFail = writesToFail.poll()) != null) {
                promiseToFail.setFailure(new RuntimeException("fake exception"));
            }

            writeCauseLatch.await();
            Throwable writeCause = failureRef.get();
            assertNotNull(writeCause);
            assertInstanceOf(SSLException.class, writeCause);
            Throwable cause = handler.handshakeFuture().cause();
            assertNotNull(cause);
            assertInstanceOf(SSLException.class, cause);
        } finally {
            assertFalse(ch.finishAndReleaseAll());
        }
    }

@Test
    public void testFlushCloseReentrance() throws Exception {
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory());
        try {
            final Queue<ChannelFuture> futures = new LinkedBlockingQueue<ChannelFuture>();

            ServerBootstrap sb = new ServerBootstrap();
            sb.group(group).channel(NioServerSocketChannel.class);
            sb.childOption(ChannelOption.SO_SNDBUF, 1024);
            sb.childHandler(new ChannelInboundHandlerAdapter() {
                @Override
                public void channelActive(ChannelHandlerContext ctx) throws Exception {
                    // Write a large enough data so that it is split into two loops.
                    futures.add(ctx.write(
                            ctx.alloc().buffer().writeZero(1048576)).addListener(ChannelFutureListener.CLOSE));
                    futures.add(ctx.write(ctx.alloc().buffer().writeZero(1048576)));
                    ctx.flush();
                    futures.add(ctx.write(ctx.alloc().buffer().writeZero(1048576)));
                    ctx.flush();
                }
            });

            SocketAddress address = sb.bind(0).sync().channel().localAddress();

            Socket s = new Socket(NetUtil.LOCALHOST, ((InetSocketAddress) address).getPort());

            InputStream in = s.getInputStream();
            byte[] buf = new byte[8192];
            for (;;) {
                if (in.read(buf) == -1) {
                    break;
                }

                // Wait a little bit so that the write attempts are split into multiple flush attempts.
                Thread.sleep(10);
            }
            s.close();

            assertEquals(3, futures.size());
            ChannelFuture f1 = futures.poll();
            ChannelFuture f2 = futures.poll();
            ChannelFuture f3 = futures.poll();
            assertTrue(f1.isSuccess());
            assertTrue(f2.isDone());
            assertFalse(f2.isSuccess());
            assertInstanceOf(ClosedChannelException.class, f2.cause());
            assertTrue(f3.isDone());
            assertFalse(f3.isSuccess());
            assertInstanceOf(ClosedChannelException.class, f3.cause());
        } finally {
            group.shutdownGracefully().sync();
        }
    }

public void setCapacity(long capacity) {
        if (capacity < MIN_HEADER_TABLE_SIZE || capacity > MAX_HEADER_TABLE_SIZE) {
            throw new IllegalArgumentException("capacity is invalid: " + capacity);
        }
        // initially capacity will be -1 so init won't return here
        if (this.capacity == capacity) {
            return;
        }
        this.capacity = capacity;

        if (capacity == 0) {
            clear();
        } else {
            // initially size will be 0 so remove won't be called
            while (size > capacity) {
                remove();
            }
        }

        int maxEntries = (int) (capacity / HpackHeaderField.HEADER_ENTRY_OVERHEAD);
        if (capacity % HpackHeaderField.HEADER_ENTRY_OVERHEAD != 0) {
            maxEntries++;
        }

        // The entries are held in a circular queue that uses head == tail to represent the empty table. It can
        // therefore hold at most (array length - 1) entries: one slot must stay free, otherwise adding the
        // maxEntries-th entry wraps head onto tail and length() wrongly reports an empty table, which makes the
        // just-added entries unreachable and lets a valid indexed reference fail with "illegal index value".
        int arrayLength = maxEntries + 1;

        // check if capacity change requires us to reallocate the array
        if (hpackHeaderFields != null && hpackHeaderFields.length == arrayLength) {
            return;
        }

        HpackHeaderField[] tmp = new HpackHeaderField[arrayLength];

        // initially length will be 0 so there will be no copy
        int len = length();
        if (hpackHeaderFields != null) {
            int cursor = tail;
            for (int i = 0; i < len; i++) {
                HpackHeaderField entry = hpackHeaderFields[cursor++];
                tmp[i] = entry;
                if (cursor == hpackHeaderFields.length) {
                    cursor = 0;
                }
            }
        }

        tail = 0;
        head = tail + len;
        hpackHeaderFields = tmp;
    }

@Test
    public void testListenerNotifyOrder() throws Exception {
        EventExecutor executor = new TestEventExecutor();
        try {
            final BlockingQueue<FutureListener<Void>> listeners = new LinkedBlockingQueue<FutureListener<Void>>();
            int runs = 100000;

            for (int i = 0; i < runs; i++) {
                final Promise<Void> promise = new DefaultPromise<Void>(executor);
                final FutureListener<Void> listener1 = new FutureListener<Void>() {
                    @Override
                    public void operationComplete(Future<Void> future) throws Exception {
                        listeners.add(this);
                    }
                };
                final FutureListener<Void> listener2 = new FutureListener<Void>() {
                    @Override
                    public void operationComplete(Future<Void> future) throws Exception {
                        listeners.add(this);
                    }
                };
                final FutureListener<Void> listener4 = new FutureListener<Void>() {
                    @Override
                    public void operationComplete(Future<Void> future) throws Exception {
                        listeners.add(this);
                    }
                };
                final FutureListener<Void> listener3 = new FutureListener<Void>() {
                    @Override
                    public void operationComplete(Future<Void> future) throws Exception {
                        listeners.add(this);
                        future.addListener(listener4);
                    }
                };

                GlobalEventExecutor.INSTANCE.execute(new Runnable() {
                    @Override
                    public void run() {
                        promise.setSuccess(null);
                    }
                });

                promise.addListener(listener1).addListener(listener2).addListener(listener3);

                assertSame(listener1, listeners.take(), "Fail 1 during run " + i + " / " + runs);
                assertSame(listener2, listeners.take(), "Fail 2 during run " + i + " / " + runs);
                assertSame(listener3, listeners.take(), "Fail 3 during run " + i + " / " + runs);
                assertSame(listener4, listeners.take(), "Fail 4 during run " + i + " / " + runs);
                assertTrue(listeners.isEmpty(), "Fail during run " + i + " / " + runs);
            }
        } finally {
            executor.shutdownGracefully(0, 0, TimeUnit.SECONDS).sync();
        }
    }

private void updateSendWindowSize(final ChannelHandlerContext ctx, int streamId, int deltaWindowSize) {
        spdySession.updateSendWindowSize(streamId, deltaWindowSize);

        while (true) {
            // Check if we have unblocked a stalled stream
            SpdySession.PendingWrite pendingWrite = spdySession.getPendingWrite(streamId);
            if (pendingWrite == null) {
                return;
            }

            SpdyDataFrame spdyDataFrame = pendingWrite.spdyDataFrame;
            int dataFrameSize = spdyDataFrame.content().readableBytes();
            int writeStreamId = spdyDataFrame.streamId();
            int sendWindowSize = spdySession.getSendWindowSize(writeStreamId);
            int sessionSendWindowSize = spdySession.getSendWindowSize(SPDY_SESSION_STREAM_ID);
            sendWindowSize = Math.min(sendWindowSize, sessionSendWindowSize);

            if (sendWindowSize <= 0) {
                return;
            } else if (sendWindowSize < dataFrameSize) {
                // We can send a partial frame
                spdySession.updateSendWindowSize(writeStreamId, -1 * sendWindowSize);
                spdySession.updateSendWindowSize(SPDY_SESSION_STREAM_ID, -1 * sendWindowSize);

                // Create a partial data frame whose length is the current window size
                SpdyDataFrame partialDataFrame = new DefaultSpdyDataFrame(
                        writeStreamId, spdyDataFrame.content().readRetainedSlice(sendWindowSize));

                // The transfer window size is pre-decremented when sending a data frame downstream.
                ctx.writeAndFlush(partialDataFrame).addListener(future -> {
                    if (!future.isSuccess()) {
                        issueSessionError(ctx, SpdySessionStatus.INTERNAL_ERROR);
                    }
                });
            } else {
                // Window size is large enough to send entire data frame
                spdySession.removePendingWrite(writeStreamId);
                spdySession.updateSendWindowSize(writeStreamId, -1 * dataFrameSize);
                spdySession.updateSendWindowSize(SPDY_SESSION_STREAM_ID, -1 * dataFrameSize);

                // Close the local side of the stream if this is the last frame
                if (spdyDataFrame.isLast()) {
                    halfCloseStream(writeStreamId, false, pendingWrite.promise);
                }

                // The transfer window size is pre-decremented when sending a data frame downstream.
                // Close the session on write failures that leave the transfer window in a corrupt state.
                ctx.writeAndFlush(spdyDataFrame, pendingWrite.promise).addListener(future -> {
                    if (!future.isSuccess()) {
                        issueSessionError(ctx, SpdySessionStatus.INTERNAL_ERROR);
                    }
                });
            }
        }
    }

@Test
    public void testSwallowedReadComplete() throws Exception {
        final long delayMillis = 100;
        final Queue<IdleStateEvent> userEvents = new LinkedBlockingQueue<IdleStateEvent>();
        final EmbeddedChannel channel = new EmbeddedChannel(false, false,
            new FlowControlHandler(),
            new IdleStateHandler(delayMillis, 0, 0, MILLISECONDS),
            new ChannelInboundHandlerAdapter() {
                @Override
                public void channelActive(ChannelHandlerContext ctx) {
                    ctx.fireChannelActive();
                    ctx.read();
                }

                @Override
                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                    ctx.fireChannelRead(msg);
                    ctx.read();
                }

                @Override
                public void channelReadComplete(ChannelHandlerContext ctx) {
                    ctx.fireChannelReadComplete();
                    ctx.read();
                }

                @Override
                public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                    if (evt instanceof IdleStateEvent) {
                        userEvents.add((IdleStateEvent) evt);
                    }
                    ctx.fireUserEventTriggered(evt);
                }
            }
        );

        channel.config().setAutoRead(false);
        assertFalse(channel.config().isAutoRead());

        channel.register();

        // Reset read timeout by some message
        assertTrue(channel.writeInbound(Unpooled.EMPTY_BUFFER));
        channel.flushInbound();
        assertEquals(Unpooled.EMPTY_BUFFER, channel.readInbound());

        // Emulate 'no more messages in NIO channel' on the next read attempt.
        channel.flushInbound();
        assertNull(channel.readInbound());

        Thread.sleep(delayMillis + 20L);
        channel.runPendingTasks();
        assertEquals(IdleStateEvent.FIRST_READER_IDLE_STATE_EVENT, userEvents.poll());
        assertFalse(channel.finish());
    }

public void testWriteAfterShutdownOutputNoWritabilityChange(Bootstrap cb) throws Throwable {
        final TestHandler h = new TestHandler();
        ServerSocket ss = new ServerSocket();
        Socket s = null;
        SocketChannel ch = null;
        try {
            ss.bind(newSocketAddress());
            cb.option(ChannelOption.WRITE_BUFFER_WATER_MARK, new WriteBufferWaterMark(2, 4));
            ch = (SocketChannel) cb.handler(h).connect(ss.getLocalSocketAddress()).sync().channel();
            assumeFalse(ch instanceof OioSocketChannel);
            assertTrue(ch.isActive());
            assertFalse(ch.isOutputShutdown());

            s = ss.accept();

            byte[] expectedBytes = new byte[]{ 1, 2, 3, 4, 5, 6 };
            ChannelFuture writeFuture = ch.write(Unpooled.wrappedBuffer(expectedBytes));
            h.assertWritability(false);
            ch.flush();
            writeFuture.sync();
            h.assertWritability(true);
            for (int i = 0; i < expectedBytes.length; ++i) {
                assertEquals(expectedBytes[i], s.getInputStream().read());
            }

            assertTrue(h.ch.isOpen());
            assertTrue(h.ch.isActive());
            assertFalse(h.ch.isInputShutdown());
            assertFalse(h.ch.isOutputShutdown());

            // Make the connection half-closed and ensure read() returns -1.
            ch.shutdownOutput().sync();
            assertEquals(-1, s.getInputStream().read());

            assertTrue(h.ch.isOpen());
            assertTrue(h.ch.isActive());
            assertFalse(h.ch.isInputShutdown());
            assertTrue(h.ch.isOutputShutdown());

            // If half-closed, the local endpoint shouldn't be able to write
            SocketChannel finalCh = ch;
            Throwable cause = assertThrows(Throwable.class,
                    () -> finalCh.writeAndFlush(randomBufferType(finalCh.alloc(), new byte[]{ 2 }, 0 , 2)).sync());
            checkThrowable(cause);
            assertNull(h.writabilityQueue.poll());
        } finally {
            if (s != null) {
                s.close();
            }
            if (ch != null) {
                ch.close();
            }
            ss.close();
        }
    }

private static void testInvokeInEventLoop(final boolean any, final boolean timeout) {
        Semaphore semaphore = new Semaphore(0);
        ManualIoEventLoop eventLoop = new ManualIoEventLoop(Thread.currentThread(), executor ->
                new TestIoHandler(semaphore));
        try {
            assertThrows(RejectedExecutionException.class, new Executable() {
                @Override
                public void execute() throws Throwable {
                    final Promise<Void> promise = eventLoop.newPromise();
                    eventLoop.execute(new Runnable() {
                        @Override
                        public void run() {
                            try {
                                Set<Callable<Boolean>> set = Collections.<Callable<Boolean>>singleton(
                                        new Callable<Boolean>() {
                                            @Override
                                            public Boolean call() {
                                                promise.setFailure(
                                                        new AssertionError("Should never execute the Callable"));
                                                return Boolean.TRUE;
                                            }
                                        });
                                if (any) {
                                    if (timeout) {
                                        eventLoop.invokeAny(set, 10, TimeUnit.SECONDS);
                                    } else {
                                        eventLoop.invokeAny(set);
                                    }
                                } else {
                                    if (timeout) {
                                        eventLoop.invokeAll(set, 10, TimeUnit.SECONDS);
                                    } else {
                                        eventLoop.invokeAll(set);
                                    }
                                }
                                promise.setFailure(new AssertionError("Should never reach here"));
                            } catch (Throwable cause) {
                                promise.setFailure(cause);
                            }
                        }
                    });
                    while (!promise.isDone()) {
                        eventLoop.runNow();
                    }
                    promise.syncUninterruptibly();
                }
            });
        } finally {
            eventLoop.shutdownGracefully(0, 0, TimeUnit.MILLISECONDS);
            while (!eventLoop.isTerminated()) {
                eventLoop.runNow();
            }
            assertTrue(eventLoop.terminationFuture().isSuccess());
        }
    }

@Override
    public void update(long time) {
        // Process received packets
        interpretPacketQueue();
        // It is possible to be removed during packet processing, if thats the case exit immediately.
        if (isRemoved()) return;

        // Send any available queued chunks
        sendPendingChunks();

        super.update(time); // Super update (item pickup/fire management)

        // Experience orb pickup
        if (gameMode != GameMode.SPECTATOR && !isDead() && experiencePickupCooldown.isReady(time)) {
            experiencePickupCooldown.refreshLastUpdate(time);
            this.instance.getEntityTracker().nearbyEntities(position, expandedBoundingBox.width(),
                    EntityTracker.Target.EXPERIENCE_ORBS, experienceOrb -> {
                        if (!expandedBoundingBox.intersectEntity(position, experienceOrb)) return;
                        final PickupExperienceEvent pickupExperienceEvent = new PickupExperienceEvent(this, experienceOrb);
                        EventDispatcher.callCancellable(pickupExperienceEvent, () -> {
//                            short experienceCount = pickupExperienceEvent.getExperienceCount(); // TODO give to player
                            experienceOrb.remove();
                        });
                    });
        }

        // Eating animation
        if (isUsingItem()) {
            final PlayerHand itemUseHand = this.itemUseHand;
            if (itemUseTime > 0 && getCurrentItemUseTime() >= itemUseTime) {
                final ItemStack itemStack = getItemInHand(itemUseHand);
                PlayerFinishItemUseEvent finishUseEvent = new PlayerFinishItemUseEvent(this, itemUseHand, itemStack, itemUseTime);
                EventDispatcher.call(finishUseEvent);

                // Reset client state
                triggerStatus((byte) EntityStatuses.Player.MARK_ITEM_FINISHED);

                // Reset server state
                final boolean isOffHand = itemUseHand == PlayerHand.OFF;
                refreshActiveHand(false, isOffHand, finishUseEvent.isRiptideSpinAttack());
                clearItemUse();

                // The client has predicted that the itemstack will have its count reduced, if the server
                // has not changed the item (the default behavior) we need to refresh the slot.
                if (itemStack.equals(getItemInHand(itemUseHand))) {
                    final int slot = isOffHand ? PlayerInventoryUtils.OFFHAND_SLOT : getHeldSlot();
                    inventory.sendSlotRefresh(slot, itemStack);
                }
            }
        }

        updatePose();

        // Tick event
        EventDispatcher.call(new PlayerTickEvent(this));
    }

@GameTest
    @EmptyTemplate
    @TestHolder(description = "Tests if custom game rules work")
    static void customGameRule(final DynamicTest test, final RegistrationHelper reg) {
        final GameRuleCategory category = new GameRuleCategory(Identifier.fromNamespaceAndPath(reg.modId(), "game_rules"));
        final DeferredHolder<GameRule<?>, GameRule<Boolean>> booleanGameRule = reg.register(Registries.GAME_RULE, "custom_boolean_game_rule", (r, n) -> GameRules.registerBoolean(n.toString(), category, true));
        final DeferredHolder<GameRule<?>, GameRule<Integer>> integerGameRule = reg.register(Registries.GAME_RULE, "custom_integer_game_rule", (r, n) -> GameRules.registerInteger(n.toString(), category, 1337, 1337));
        // '(visitor, gameRule) -> {}' is intentional here
        // `GameRules#visitGameRuleTypes` calls the default `GameRuleTypeVisitor#visit(GameRule<T>)` before invoking the game rule specific visitor
        // DO NOT call `GameRuleTypeVisitor#visit` from your custom visitor, this will double up 'visits' to your game rule
        final DeferredHolder<GameRule<?>, GameRule<Double>> doubleGameRule = reg.register(Registries.GAME_RULE, "custom_double_game_rule", (r, n) -> GameRules.register(n.toString(), category, GameRuleType.valueOf("NEOTESTS_DOUBLE"), DoubleArgumentType.doubleArg(), Codec.DOUBLE, 0D, FeatureFlagSet.of(), (visitor, gameRule) -> {}, value -> Command.SINGLE_SUCCESS));
        final DeferredHolder<GameRule<?>, GameRule<String>> stringGameRule = reg.register(Registries.GAME_RULE, "custom_string_game_rule", (r, n) -> GameRules.register(n.toString(), category, GameRuleType.valueOf("NEOTESTS_STRING"), StringArgumentType.string(), Codec.STRING, "", FeatureFlagSet.of(), (visitor, gameRule) -> {}, value -> Command.SINGLE_SUCCESS));

        test.eventListeners().forge().addListener((EntityTickEvent.Pre event) -> {
            if (event.getEntity() instanceof ServerPlayer player && player.getGameProfile().name().equals("test-mock-player")) {
                if (player.level().getGameRules().get(booleanGameRule.get())) {
                    player.setHealth(player.getHealth() - player.level().getGameRules().get(integerGameRule.get()));
                }
            }
        });

        test.eventListeners().mod().addListener((RegisterGameRuleCategoryEvent event) -> event.register(category));

        reg.clientProvider(LanguageProvider.class, provider -> {
            provider.add(category, "Custom GameRules");
            provider.addGameRule(booleanGameRule, "Custom Boolean", "A custom boolean game rule");
            provider.addGameRule(integerGameRule, "Custom Integer", "A custom integer game rule");
            provider.addGameRule(doubleGameRule, "Custom Double", "A custom double game rule");
            provider.addGameRule(stringGameRule, "Custom String", "A custom string game rule");
        });

        test.onGameTest(helper -> {
            final ServerPlayer player = helper.makeTickingMockServerPlayerInCorner(GameType.SURVIVAL);

            var gameRules = player.level().getGameRules();
            final var oldBool = gameRules.get(booleanGameRule.get());
            final var oldInt = gameRules.get(integerGameRule.get());
            final var oldDouble = gameRules.get(doubleGameRule.get());
            final var oldString = gameRules.get(stringGameRule.get());

            helper.startSequence()
                    .thenExecute(() -> gameRules.set(booleanGameRule.get(), true, player.level().getServer()))
                    .thenExecute(() -> gameRules.set(integerGameRule.get(), 12, player.level().getServer()))
                    .thenExecute(() -> gameRules.set(doubleGameRule.get(), 64D, player.level().getServer()))
                    .thenExecute(() -> gameRules.set(stringGameRule.get(), "test", player.level().getServer()))

                    .thenIdle(1)
                    .thenExecute(() -> helper.assertEntityProperty(player, ServerPlayer::getHealth, "player health", 8f))

                    .thenExecute(() -> gameRules.set(booleanGameRule.get(), oldBool, player.level().getServer()))
                    .thenExecute(() -> gameRules.set(integerGameRule.get(), oldInt, player.level().getServer()))
                    .thenExecute(() -> gameRules.set(doubleGameRule.get(), oldDouble, player.level().getServer()))
                    .thenExecute(() -> gameRules.set(stringGameRule.get(), oldString, player.level().getServer()))
                    .thenSucceed();
        });
    }

public static void spawnExplosionSparks(Level level, Vec3 position, MalumNetworkedParticleEffectColorData colorData, int amount, float speed) {
        var random = level.random;
        for (int i = 0; i < amount; i++) {
            var color = colorData.getColor();
            float lifetimeMultiplier = Easing.SINE_IN_OUT.asWeighedRandom(random, 2f, 2.5f);
            float gravityStrength = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.03f, 0.06f);
            double horizontalAngle = random.nextDouble() * Math.PI * 2;
            double x = Math.sin(horizontalAngle);
            double y = Mth.nextFloat(random, 0.35f, 1);
            double z = Math.cos(horizontalAngle);
            Vec3 direction = new Vec3(x, y, z);
            Vec3 motion = direction.scale(speed * Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 1.25f));
            Vec3 spawnPosition = position.add(direction.scale(0.25f));
            Consumer<LodestoneWorldParticle> sparkBehavior = p -> {
                Vec3 velocity = p.getParticleSpeed().scale(0.75f);
                if (velocity.equals(Vec3.ZERO)) {
                    velocity = p.getParticleSpeed();
                }
                p.setParticleSpeed(velocity.x, (velocity.y - gravityStrength) * 0.98f, velocity.z);
                if (p.getAge() < p.getLifetime() * 0.7f) {
                    if (level.getGameTime() % 2 == 0) {
                        var lightSpecs = spiritLightSpecs(level, p.getParticlePosition(), p.colorData);
                        lightSpecs.getBuilder()
                                .setTransparencyData(GenericParticleData.create(0.9f))
                                .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                                .multiplyLifetime(lifetimeMultiplier / 2f)
                                .enableForcedSpawn();
                        lightSpecs.getBloomBuilder()
                                .setTransparencyData(GenericParticleData.create(0.9f))
                                .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                                .multiplyLifetime(lifetimeMultiplier / 4f);
                        lightSpecs.spawnParticles();
                    }
                }
            };
            float scalar = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.8f, 1.1f);
            var sparks = SparkParticleEffects.spiritMotionSparks(level, spawnPosition, color).act(b -> b.getParticleOptions().setBehavior(SparkParticleBehavior.sparkBehavior()));
            sparks.getBuilder()
                    .setLengthData(GenericParticleData.create(3f * scalar, 0.75f * scalar, 0f).setEasing(Easing.QUARTIC_OUT, Easing.SINE_IN_OUT))
                    .setScaleData(GenericParticleData.create(0.4f * scalar, 0.2f * scalar, 0f).setEasing(Easing.SINE_IN, Easing.QUAD_IN))
                    .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                    .setTransparencyData(GenericParticleData.create(0.9f))
                    .multiplyLifetime(lifetimeMultiplier)
                    .addTickActor(sparkBehavior)
                    .enableForcedSpawn()
                    .setMotion(motion);
            sparks.getBloomBuilder()
                    .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                    .setTransparencyData(GenericParticleData.create(0.9f))
                    .modifyScaleData(d -> d.multiplyValue(2f))
                    .multiplyLifetime(lifetimeMultiplier)
                    .addTickActor(sparkBehavior)
                    .setMotion(motion);
            sparks.spawnParticles();
        }
    }

