private static void testIp(InetAddress address, int prefix) throws Exception {
        int lowOrderBitsToPreserve = prefix % Byte.SIZE;

        ByteBuf addressPart = Unpooled.wrappedBuffer(address.getAddress(), 0,
                DefaultDnsRecordEncoder.calculateEcsAddressLength(prefix, lowOrderBitsToPreserve));

        if (lowOrderBitsToPreserve > 0) {
            // Pad the leftover of the last byte with zeros.
            int idx = addressPart.writerIndex() - 1;
            byte lastByte = addressPart.getByte(idx);
            int paddingMask = -1 << 8 - lowOrderBitsToPreserve;
            addressPart.setByte(idx, lastByte & paddingMask);
        }

        int payloadSize = nextInt(Short.MAX_VALUE);
        int extendedRcode = nextInt(Byte.MAX_VALUE * 2); // Unsigned
        int version = nextInt(Byte.MAX_VALUE * 2); // Unsigned

        DefaultDnsRecordEncoder encoder = new DefaultDnsRecordEncoder();
        ByteBuf out = Unpooled.buffer();
        try {
            DnsOptEcsRecord record = new DefaultDnsOptEcsRecord(
                    payloadSize, extendedRcode, version, prefix, address.getAddress());
            encoder.encodeRecord(record, out);

            assertEquals(0, out.readByte()); // Name
            assertEquals(DnsRecordType.OPT.intValue(), out.readUnsignedShort()); // Opt
            assertEquals(payloadSize, out.readUnsignedShort()); // payload
            assertEquals(record.timeToLive(), out.getUnsignedInt(out.readerIndex()));

            // Read unpacked TTL.
            assertEquals(extendedRcode, out.readUnsignedByte());
            assertEquals(version, out.readUnsignedByte());
            assertEquals(extendedRcode, record.extendedRcode());
            assertEquals(version, record.version());
            assertEquals(0, record.flags());

            assertEquals(0, out.readShort());

            int payloadLength = out.readUnsignedShort();
            assertEquals(payloadLength, out.readableBytes());

            assertEquals(8, out.readShort()); // As defined by RFC.

            int rdataLength = out.readUnsignedShort();
            assertEquals(rdataLength, out.readableBytes());

            assertEquals((short) (address instanceof Inet4Address ? 1 : 2), out.readShort());

            assertEquals(prefix, out.readUnsignedByte());
            assertEquals(0, out.readUnsignedByte()); // This must be 0 for requests.
            assertEquals(addressPart, out);
        } finally {
            addressPart.release();
            out.release();
        }
    }

@Test
    public void testOverflowDrainsBeforeInlineRefill() {
        // Verify that once overflow is activated, subsequent enqueues also go to overflow
        // until the overflow drains, keeping FIFO order correct.
        EmbeddedChannel ch = new EmbeddedChannel(new HttpServerCodec());

        int totalRequests = 34; // 32 inline + 2 overflow

        // Send 34 pipelined requests: position 33 (overflow) is HEAD.
        StringBuilder requests = new StringBuilder();
        for (int i = 0; i < totalRequests; i++) {
            if (i == 33) {
                requests.append("HEAD /").append(i).append(" HTTP/1.1\r\nHost: a\r\n\r\n");
            } else {
                requests.append("GET /").append(i).append(" HTTP/1.1\r\nHost: a\r\n\r\n");
            }
        }
        assertTrue(ch.writeInbound(Unpooled.copiedBuffer(requests.toString(), CharsetUtil.UTF_8)));

        // Drain inbound.
        for (;;) {
            Object msg = ch.readInbound();
            if (msg == null) {
                break;
            }
            if (msg instanceof HttpContent) {
                ((HttpContent) msg).release();
            }
        }

        // Send responses for first 33 (all GET).
        for (int i = 0; i < 33; i++) {
            FullHttpResponse resp = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
                    Unpooled.copiedBuffer("ok", CharsetUtil.UTF_8));
            resp.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 2);
            assertTrue(ch.writeOutbound(resp));
            ByteBuf buf = ch.readOutbound();
            String encoded = buf.toString(CharsetUtil.US_ASCII);
            assertTrue(encoded.contains("ok"), "GET response at position " + i + " should contain body");
            buf.release();
        }

        // Response for position 33 — HEAD from overflow queue.
        HttpResponse headResp = new DefaultHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK);
        headResp.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 42);
        assertTrue(ch.writeOutbound(headResp));
        assertTrue(ch.writeOutbound(LastHttpContent.EMPTY_LAST_CONTENT));

        ByteBuf buf = ch.readOutbound();
        buf.release();

        buf = ch.readOutbound();
        assertFalse(buf.isReadable(), "HEAD response from overflow queue body should be empty");
        buf.release();

        assertFalse(ch.finishAndReleaseAll());
    }

private void testFlushStrategy(boolean useBytes) {
        final int bytes = 8;
        final AtomicInteger numBytesTracker = new AtomicInteger();
        final AtomicInteger numPacketsTracker = new AtomicInteger();
        final AtomicInteger flushCount = new AtomicInteger();
        B builder = newCodecBuilder();
        builder.flushStrategy((numPackets, numBytes) -> {
            numPacketsTracker.set(numPackets);
            numBytesTracker.set(numBytes);
            if (useBytes) {
                return numBytes > 8;
            }
            if (numPackets == 2) {
                return true;
            }
            return false;
        });

        EmbeddedChannel channel = new EmbeddedChannel(new ChannelOutboundHandlerAdapter() {
            @Override
            public void flush(ChannelHandlerContext ctx) throws Exception {
                flushCount.incrementAndGet();
                super.flush(ctx);
            }
        }, builder.build());
        assertEquals(0, numPacketsTracker.get());
        assertEquals(0, numBytesTracker.get());
        assertEquals(0, flushCount.get());

        channel.write(new DatagramPacket(Unpooled.buffer().writeZero(bytes), new InetSocketAddress(0)));
        assertEquals(1, numPacketsTracker.get());
        assertEquals(8, numBytesTracker.get());
        assertEquals(0, flushCount.get());

        channel.write(new DatagramPacket(Unpooled.buffer().writeZero(bytes), new InetSocketAddress(0)));
        assertEquals(2, numPacketsTracker.get());
        assertEquals(16, numBytesTracker.get());
        assertEquals(1, flushCount.get());

        // As a flush did happen we should see two packets in the outbound queue.
        for (int i = 0; i < 2; i++) {
            DatagramPacket packet = channel.readOutbound();
            assertNotNull(packet);
            packet.release();
        }

        ChannelFuture future = channel.write(new DatagramPacket(Unpooled.buffer().writeZero(bytes),
                new InetSocketAddress(0)));
        assertEquals(1, numPacketsTracker.get());
        assertEquals(8, numBytesTracker.get());
        assertEquals(1, flushCount.get());

        // We never flushed the last datagram packet so it should be failed.
        assertFalse(channel.finish());
        assertTrue(future.isDone());
        assertFalse(future.isSuccess());
    }

