@ParameterizedTest
    @EnumSource(DeregisterMethod.class)
    void testReregisterOnChannelHandlerContext(DeregisterMethod method) throws Exception {
        EventLoopGroup group = newEventLoopGroup();
        AtomicReference<Throwable> throwable = new AtomicReference<>();
        try {
            ServerBootstrap b = new ServerBootstrap();
            ReRegisterHandler reRegisterHandler = new ReRegisterHandler(group, method, throwable);
            b.group(group)
                    .channel(newChannel())
                    .childHandler(new ChannelInitializer<SocketChannel>() {
                        @Override
                        public void initChannel(SocketChannel ch) {
                            ChannelPipeline p = ch.pipeline();
                            p.addLast("logging", new LoggingHandler());
                            p.addLast(reRegisterHandler);
                        }
                    });

            ChannelFuture f = b.bind(0).sync();

            Channel client = new Bootstrap()
                    .group(group)
                    .channel(newSocketChannel())
                    .handler(new ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                            ReferenceCountUtil.release(msg);
                        }

                        @Override
                        public void channelReadComplete(ChannelHandlerContext ctx) throws Exception {
                            super.channelReadComplete(ctx);
                            ctx.close();
                        }

                        @Override
                        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) throws Exception {
                            throwable.set(cause);
                            super.exceptionCaught(ctx, cause);
                            ctx.close();
                        }
                    })
                    .connect(f.channel().localAddress())
                    .sync()
                    .channel();
            client.closeFuture().addListener(ignore -> f.channel().close());
            client.writeAndFlush(Unpooled.copiedBuffer("hello", StandardCharsets.US_ASCII));

            f.channel().closeFuture().sync();
            Throwable caughtThrowable = throwable.get();
            if (caughtThrowable != null) {
                fail(caughtThrowable);
            }
        } finally {
            group.shutdownGracefully();
        }
    }

@Test
    public void testBoundedChannelPoolSegment() throws Exception {
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(LocalIoHandler.newFactory());
        LocalAddress addr = new LocalAddress(getLocalAddrId());
        Bootstrap cb = new Bootstrap();
        cb.remoteAddress(addr);
        cb.group(group)
          .channel(LocalChannel.class);

        ServerBootstrap sb = new ServerBootstrap();
        sb.group(group)
          .channel(LocalServerChannel.class)
          .childHandler(new ChannelInitializer<LocalChannel>() {
              @Override
              public void initChannel(LocalChannel ch) throws Exception {
                  ch.pipeline().addLast(new ChannelInboundHandlerAdapter());
              }
          });

        // Start server
        Channel sc = sb.bind(addr).sync().channel();
        CountingChannelPoolHandler handler = new CountingChannelPoolHandler();

        final ChannelPool pool = new SimpleChannelPool(cb, handler, ChannelHealthChecker.ACTIVE) {
            private final Queue<Channel> queue = new LinkedBlockingQueue<Channel>(1);

            @Override
            protected Channel pollChannel() {
                return queue.poll();
            }

            @Override
            protected boolean offerChannel(Channel ch) {
                return queue.offer(ch);
            }
        };

        Channel channel = pool.acquire().sync().getNow();
        final Channel channel2 = pool.acquire().sync().getNow();

        pool.release(channel).syncUninterruptibly().getNow();
        assertThrows(IllegalStateException.class, new Executable() {
            @Override
            public void execute() throws Throwable {
                pool.release(channel2).syncUninterruptibly();
            }
        });
        channel2.close().sync();

        assertEquals(2, handler.channelCount());
        assertEquals(2, handler.acquiredCount());
        assertEquals(1, handler.releasedCount());
        sc.close().sync();
        channel.close().sync();
        channel2.close().sync();
        pool.close();
        group.shutdownGracefully();
    }

@Test
    public void testSettingsViewDistanceCappedByInstance(Env env) {
        var instance = env.createFlatInstance();
        // Cap the instance's view distance at 4.
        instance.viewDistance(4);
        var connection = env.createConnection();
        var player = connection.connect(instance, new Pos(0, 42, 0));

        // Preload chunks, otherwise our first assertCount call will fail randomly due to chunks being loaded off the main thread
        ChunkRange.chunksInRange(0, 0, 13, (chunkX, chunkZ) -> instance.loadChunk(chunkX, chunkZ).join());

        // The default view distance is 8. Capped at instance view distance (4) + 1 = 5.
        assertEquals(5, player.effectiveViewDistance());

        // Expand settings view distance to 12. Since it is capped by instance view distance 4,
        // the effective view distance remains 5. No chunk packets should be sent.
        var added = connection.trackIncoming(ChunkDataPacket.class);
        var removed = connection.trackIncoming(UnloadChunkPacket.class);
        player.addPacketToQueue(new ClientSettingsPacket(new ClientSettings(Locale.US, (byte) 12,
                ChatMessageType.FULL, false, (byte) 0, MainHand.RIGHT,
                false, true, ClientSettings.ParticleSetting.ALL)));
        player.interpretPacketQueue();
        assertEquals(5, player.effectiveViewDistance());
        added.assertCount(0);
        removed.assertCount(0);

        // Shrink settings view distance to 3. Capped by min(3, 4) + 1 = 4.
        // It shrinks from 5 to 4. We expect UnloadChunkPackets.
        int beforeShrink = player.effectiveViewDistance();
        var removed2 = connection.trackIncoming(UnloadChunkPacket.class);
        player.addPacketToQueue(new ClientSettingsPacket(new ClientSettings(Locale.US, (byte) 3,
                ChatMessageType.FULL, false, (byte) 0, MainHand.RIGHT,
                false, true, ClientSettings.ParticleSetting.ALL)));
        player.interpretPacketQueue();
        assertEquals(4, player.effectiveViewDistance());
        removed2.assertCount(ChunkRange.chunksCount(beforeShrink) - ChunkRange.chunksCount(player.effectiveViewDistance()));

        // Shrink settings view distance to 2. Capped by min(2, 4) + 1 = 3.
        // It shrinks from 4 to 3. We expect UnloadChunkPackets.
        int beforeShrink2 = player.effectiveViewDistance();
        var removed3 = connection.trackIncoming(UnloadChunkPacket.class);
        player.addPacketToQueue(new ClientSettingsPacket(new ClientSettings(Locale.US, (byte) 2,
                ChatMessageType.FULL, false, (byte) 0, MainHand.RIGHT,
                false, true, ClientSettings.ParticleSetting.ALL)));
        player.interpretPacketQueue();
        assertEquals(3, player.effectiveViewDistance());
        removed3.assertCount(ChunkRange.chunksCount(beforeShrink2) - ChunkRange.chunksCount(player.effectiveViewDistance()));

        // Expand settings view distance back to 8. Effective view distance becomes min(8, 4) + 1 = 5.
        // It expands from 3 to 5. We expect ChunkDataPackets.
        int beforeExpand = player.effectiveViewDistance();
        var added2 = connection.trackIncoming(ChunkDataPacket.class);
        player.addPacketToQueue(new ClientSettingsPacket(new ClientSettings(Locale.US, (byte) 8,
                ChatMessageType.FULL, false, (byte) 0, MainHand.RIGHT,
                false, true, ClientSettings.ParticleSetting.ALL)));
        player.interpretPacketQueue();
        assertEquals(5, player.effectiveViewDistance());
        added2.assertCount(ChunkRange.chunksCount(player.effectiveViewDistance()) - ChunkRange.chunksCount(beforeExpand));
    }

public static void altarBlessTarget(Level level, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, LivingEntity target) {
        var random = level.random;
        var position = positionData.getAsVector();

        Function<Vec3, Consumer<LodestoneWorldParticle>> behavior = initialOffset -> p -> {
            var targetPosition = target.getPosition(p.partialTicksCache);
            p.setParticlePosition(targetPosition.add(initialOffset).add(p.getInterpolatedTravelledDistance()));
        };
        var offset = behavior.apply(position.subtract(target.position()));
        for (int i = 0; i < 5; i++) {
            int lifeDelay = i * 2;
            float upwardsMotion = 0.01f * i;
            float scale = 2f + i * 0.25f;
            cultistSigil(level, colorData)
                    .setSpinData(SpinParticleData.createRandomDirection(random, 0.3f, 0).setEasing(Easing.EXPO_OUT).build())
                    .modifyScaleData(d -> d.multiplyValue(scale))
                    .setBehavior(DirectionalParticleBehavior.directional(new Vec3(0, 1, 0)))
                    .setFriction(0.9f)
                    .addRenderActor(offset)
                    .addMotion(0, upwardsMotion, 0f)
                    .setLifetime(15)
                    .setLifeDelay(lifeDelay)
                    .spawn(level, position);
        }
        long gameTime = level.getGameTime();
        float time = 16;
        for (int i = 0; i < 8; i++) {
            var offsetPosition = VecHelper.rotatingRadialOffset(position, 0.9f, i, 8, gameTime, time);
            offsetPosition = offsetPosition.add(0, (Math.cos(((gameTime + i * 480) % time) / time) * 0.25f) + 0.5f, 0);
            offset = behavior.apply(offsetPosition.subtract(position));
            float upwardsVelocity = 0.2f;
            for (int j = 0; j < 3; j++) {
                var lightSpecs = SparkParticleEffects.spiritMotionSparks(level, offsetPosition, colorData.getColor(), new WorldParticleOptions(MalumParticles.MOTION_LINES));
                float velocity = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.05f, 0.1f);
                var motion = offsetPosition.subtract(position).normalize().scale(velocity);
                int lifeDelay = j * 3;
                lightSpecs.getBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .addRenderActor(offset)
                        .multiplyLifetime(1.25f)
                        .setMotion(motion)
                        .addMotion(0, upwardsVelocity, 0)
                        .setLifeDelay(lifeDelay)
                        .setLengthData(GenericParticleData.create(2f, 0.5f).setEasing(Easing.EXPO_OUT).build())
                        .setTransparencyData(GenericParticleData.create(0.6f, 0.8f, 0f).build())
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 3f, 4f)));
                lightSpecs.getBloomBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .addRenderActor(offset)
                        .multiplyLifetime(0.75f)
                        .setMotion(motion)
                        .addMotion(0, upwardsVelocity, 0)
                        .setLifeDelay(lifeDelay)
                        .setScaleData(GenericParticleData.create(1f, 0.25f).setEasing(Easing.EXPO_OUT).build())
                        .setTransparencyData(GenericParticleData.create(0.05f, 0.35f, 0f).build());
                lightSpecs.spawnParticles();
            }
        }
    }

