@Override
    ByteBuf processOutput(ByteBuf buf) throws DecompressionException {
        int proposedCapacity = Math.max(inflater.getRemaining() << 1, MIN_OUTPUT_BUFFER_SIZE);
        int targetCapacity = maxAllocation == 0
                ? proposedCapacity : Math.min(maxAllocation, proposedCapacity);
        ByteBuf decompressed = allocator.heapBuffer(targetCapacity);
        boolean success = false;
        try {
            byte[] outArray = decompressed.array();
            int writerIndex = decompressed.writerIndex();
            int outIndex = decompressed.arrayOffset() + writerIndex;
            int writableBytes = decompressed.writableBytes();
            int outputLength;
            try {
                outputLength = inflater.inflate(outArray, outIndex, writableBytes);
            } catch (DataFormatException e) {
                throw new DecompressionException("decompression failure", e);
            }
            consumeInput(buf);
            if (outputLength > 0) {
                decompressed.writerIndex(writerIndex + outputLength);
                if (crc != null) {
                    crc.update(outArray, outIndex, outputLength);
                }
            }
            if (inflater.needsDictionary()) {
                if (dictionary == null) {
                    throw new DecompressionException(
                            "decompression failure, unable to set dictionary as none was specified");
                }
                try {
                    inflater.setDictionary(dictionary);
                } catch (IllegalArgumentException e) {
                    // The dictionary ID in the stream header does not match the configured dictionary.
                    throw new DecompressionException("decompression failure, dictionary mismatch", e);
                }
            }
            if (inflater.finished()) {
                inputBufferInInflater = false;
                if (crc == null) {
                    finished = true; // Do not decode anymore.
                } else {
                    gzipState = GzipState.FOOTER_START;
                    // potentially consume footer
                    processInput(buf);
                }
            }
            // If we filled the whole buffer the inflater may still have decoded data left that it could not write.
            // In that case we must ask for another output buffer, as needsInput() only tells us that all input
            // bytes were consumed, not that all output was produced.
            inflaterHasPendingOutput = outputLength == writableBytes && !inflater.finished();
            success = true;
            return decompressed;
        } finally {
            if (!success) {
                decompressed.release();
            }
        }
    }

@Test
    public void testMultipleReadsOnEmptyQueue() throws Exception {
        final AtomicInteger reads = new AtomicInteger();
        final AtomicInteger readCompletes = new AtomicInteger();
        final EmbeddedChannel channel = new EmbeddedChannel(
                false, false,
                new FlowControlHandler(),
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        reads.incrementAndGet();
                    }

                    @Override
                    public void channelReadComplete(ChannelHandlerContext ctx) {
                        readCompletes.incrementAndGet();
                    }
                });
        channel.config().setAutoRead(false);
        channel.register();

        channel.read();
        channel.read();
        channel.read();

        channel.writeOneInbound("msg1");

        assertEquals(1, reads.get());
        assertEquals(0, readCompletes.get());

        channel.flushInbound();

        assertEquals(1, reads.get());
        assertEquals(1, readCompletes.get());

        channel.read();
        channel.read();
        channel.read();

        // empty read
        channel.flushInbound();

        assertEquals(1, reads.get());
        assertEquals(2, readCompletes.get());

        // quick check that internal state is not broken
        channel.writeOneInbound("msg2");
        channel.flushInbound();

        assertEquals(1, reads.get());
        assertEquals(2, readCompletes.get());

        channel.read();

        assertEquals(2, reads.get());
        assertEquals(3, readCompletes.get());

        assertFalse(channel.finishAndReleaseAll());
    }

@Timeout(value = 60, threadMode = Timeout.ThreadMode.SEPARATE_THREAD)
    @MethodSource("newTestParams")
    @ParameterizedTest
    public void mustCallResumeTrustedOnSessionResumption(SSLEngineTestParam param) throws Exception {
        SelfSignedCertificate ssc = CachedSelfSignedCertificate.getCachedCertificate();
        SessionValueSettingTrustManager clientTm = new SessionValueSettingTrustManager("key", "client");
        SessionValueSettingTrustManager serverTm = new SessionValueSettingTrustManager("key", "server");
        buildClientSslContextForMTLS(param, ssc, clientTm);
        buildServerSslContextForMTLS(param, ssc, serverTm);
        final BlockingQueue<String> clientSessionValues = new LinkedBlockingQueue<String>();
        final BlockingQueue<String> serverSessionValues = new LinkedBlockingQueue<String>();
        OnNextMessage checkClient = new OnNextMessage() {
            @Override
            public void messageReceived(ChannelHandlerContext ctx, ByteBuf msg) throws Exception {
                msg.release();
                SslHandler sslHandler = ctx.pipeline().get(SslHandler.class);
                SSLEngine engine = sslHandler.engine();
                logger.debug("Client message received: {} ({}) {} {}",
                        engine.getSession(), engine.getHandshakeStatus(), isSessionReused(engine),
                        Arrays.toString(engine.getSession().getValueNames()));
                Object value = engine.getSession().getValue("key");
                clientSessionValues.put((String) value);
            }
        };
        OnNextMessage checkServer = new OnNextMessage() {
            @Override
            public void messageReceived(ChannelHandlerContext ctx, ByteBuf msg) throws Exception {
                SslHandler sslHandler = ctx.pipeline().get(SslHandler.class);
                SSLEngine engine = sslHandler.engine();
                logger.debug("Server message received: {} ({}) {} {}",
                        engine.getSession(), engine.getHandshakeStatus(), isSessionReused(engine),
                        Arrays.toString(engine.getSession().getValueNames()));
                Object value = engine.getSession().getValue("key");
                serverSessionValues.put((String) value);
                ctx.writeAndFlush(msg).addListener(ChannelFutureListener.CLOSE);
            }
        };

        setupServer(param.type(), param.delegate());
        InetSocketAddress addr = (InetSocketAddress) serverChannel.localAddress();
        setupClient(param.type(), param.delegate(), "a.netty.io", addr.getPort());
        for (int i = 0; i < 10; i++) {
            clientReceiver.onNextMessages.offer(checkClient);
            serverReceiver.onNextMessages.offer(checkServer);

            ChannelFuture ccf = cb.connect(addr);
            assertTrue(ccf.syncUninterruptibly().isSuccess());
            clientChannel = ccf.channel();

            clientChannel.writeAndFlush(clientChannel.alloc().buffer().writeInt(42)).sync();
            assertEquals("client", clientSessionValues.take());
            assertEquals("server", serverSessionValues.take());
            clientChannel.closeFuture().sync();
        }
        assertTrue(clientReceiver.onNextMessages.isEmpty());
        assertTrue(serverReceiver.onNextMessages.isEmpty());
        assertTrue(clientSessionValues.isEmpty());
        assertTrue(serverSessionValues.isEmpty());
    }

