public static long getInitialSeedUniquifier() {
        // Use the value set via the setter.
        long initialSeedUniquifier = ThreadLocalRandom.initialSeedUniquifier;
        if (initialSeedUniquifier != 0) {
            return initialSeedUniquifier;
        }

        synchronized (ThreadLocalRandom.class) {
            initialSeedUniquifier = ThreadLocalRandom.initialSeedUniquifier;
            if (initialSeedUniquifier != 0) {
                return initialSeedUniquifier;
            }

            // Get the random seed from the generator thread with timeout.
            final long timeoutSeconds = 3;
            final long deadLine = seedGeneratorStartTime + TimeUnit.SECONDS.toNanos(timeoutSeconds);
            boolean interrupted = false;
            for (;;) {
                final long waitTime = deadLine - System.nanoTime();
                try {
                    final Long seed;
                    if (waitTime <= 0) {
                        seed = seedQueue.poll();
                    } else {
                        seed = seedQueue.poll(waitTime, TimeUnit.NANOSECONDS);
                    }

                    if (seed != null) {
                        initialSeedUniquifier = seed;
                        break;
                    }
                } catch (InterruptedException e) {
                    interrupted = true;
                    logger.warn("Failed to generate a seed from SecureRandom due to an InterruptedException.");
                    break;
                }

                if (waitTime <= 0) {
                    seedGeneratorThread.interrupt();
                    logger.warn(
                            "Failed to generate a seed from SecureRandom within {} seconds. " +
                            "Not enough entropy?", timeoutSeconds
                    );
                    break;
                }
            }

            // Just in case the initialSeedUniquifier is zero or some other constant
            initialSeedUniquifier ^= 0x3255ecdc33bae119L; // just a meaningless random number
            initialSeedUniquifier ^= Long.reverse(System.nanoTime());

            ThreadLocalRandom.initialSeedUniquifier = initialSeedUniquifier;

            if (interrupted) {
                // Restore the interrupt status because we don't know how to/don't need to handle it here.
                Thread.currentThread().interrupt();

                // Interrupt the generator thread if it's still running,
                // in the hope that the SecureRandom provider raises an exception on interruption.
                seedGeneratorThread.interrupt();
            }

            if (seedGeneratorEndTime == 0) {
                seedGeneratorEndTime = System.nanoTime();
            }

            return initialSeedUniquifier;
        }
    }

@ParameterizedTest
    @ValueSource(booleans = {true, false})
    public void testOutboundOperationsViaContext(boolean inEventLoop) throws Exception {
        ChannelPipeline pipeline = new LocalChannel().pipeline();
        final ChannelHandler handler = new ChannelHandlerAdapter() { };
        pipeline.addLast(handler);
        group.register(pipeline.channel()).syncUninterruptibly();
        final BlockingQueue<String> events = new LinkedBlockingQueue<>();
        pipeline.addFirst(new ChannelOutboundHandlerAdapter() {
            @Override
            public void bind(ChannelHandlerContext ctx, SocketAddress localAddress, ChannelPromise promise) {
                events.add("bind");
                promise.setSuccess();
            }

            @Override
            public void connect(ChannelHandlerContext ctx, SocketAddress remoteAddress, SocketAddress localAddress,
                                ChannelPromise promise)  {
                events.add("connect");
                promise.setSuccess();
            }

            @Override
            public void close(ChannelHandlerContext ctx, ChannelPromise promise) {
                events.add("close");
                promise.setSuccess();
            }

            @Override
            public void deregister(ChannelHandlerContext ctx, ChannelPromise promise)  {
                events.add("deregister");
                promise.setSuccess();
            }

            @Override
            public void read(ChannelHandlerContext ctx)  {
                events.add("read");
            }

            @Override
            public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                events.add("write");
                promise.setSuccess();
            }

            @Override
            public void flush(ChannelHandlerContext ctx) {
                events.add("flush");
                ctx.flush();
            }
        });
        ChannelHandlerContext ctx = pipeline.context(handler);
        if (inEventLoop) {
            pipeline.channel().eventLoop().execute(() -> executeOutboundOperations(ctx));
        } else {
            executeOutboundOperations(ctx);
        }

        assertEquals("bind", events.take());
        assertEquals("connect", events.take());
        assertEquals("close", events.take());
        assertEquals("deregister", events.take());
        assertEquals("read", events.take());
        assertEquals("write", events.take());
        assertEquals("flush", events.take());
        assertTrue(events.isEmpty());
        pipeline.removeFirst();
        pipeline.channel().close().syncUninterruptibly();
    }

@ApiStatus.Internal
    public static void readAdditionalLevelSaveData(CompoundTag rootTag, LevelStorageSource.LevelDirectory levelDirectory) {
        CompoundTag tag = rootTag.getCompoundOrEmpty("fml");
        if (tag.contains("LoadingModList")) {
            ListTag modList = tag.getListOrEmpty("LoadingModList");
            Map<String, ArtifactVersion> mismatchedVersions = new HashMap<>(modList.size());
            Map<String, ArtifactVersion> missingVersions = new HashMap<>(modList.size());
            for (int i = 0; i < modList.size(); i++) {
                CompoundTag mod = modList.getCompoundOrEmpty(i);
                String modId = mod.getStringOr("ModId", "");
                if (Objects.equals("minecraft", modId)) {
                    continue;
                }

                String modVersion = mod.getStringOr("ModVersion", "");
                final var previousVersion = new DefaultArtifactVersion(modVersion);
                ModList.get().getModContainerById(modId).ifPresentOrElse(container -> {
                    final var loadingVersion = container.getModInfo().getVersion();
                    if (!loadingVersion.equals(previousVersion)) {
                        // Enqueue mismatched versions for bulk event
                        mismatchedVersions.put(modId, previousVersion);
                    }
                }, () -> missingVersions.put(modId, previousVersion));
            }

            final var mismatchEvent = new ModMismatchEvent(levelDirectory, mismatchedVersions, missingVersions);
            ModLoader.postEvent(mismatchEvent);

            StringBuilder resolved = new StringBuilder("The following mods have version differences that were marked resolved:");
            StringBuilder unresolved = new StringBuilder("The following mods have version differences that were not resolved:");

            // For mods that were marked resolved, log the version resolution and the mod that resolved the mismatch
            mismatchEvent.getResolved().forEachOrdered((res) -> {
                final var modid = res.modid();
                final var diff = res.versionDifference();
                if (res.wasSelfResolved()) {
                    resolved.append(System.lineSeparator())
                            .append(diff.isMissing()
                                    ? "%s (version %s -> MISSING, self-resolved)".formatted(modid, diff.oldVersion())
                                    : "%s (version %s -> %s, self-resolved)".formatted(modid, diff.oldVersion(), diff.newVersion()));
                } else {
                    final var resolver = res.resolver().getModId();
                    resolved.append(System.lineSeparator())
                            .append(diff.isMissing()
                                    ? "%s (version %s -> MISSING, resolved by %s)".formatted(modid, diff.oldVersion(), resolver)
                                    : "%s (version %s -> %s, resolved by %s)".formatted(modid, diff.oldVersion(), diff.newVersion(), resolver));
                }
            });

            // For mods that did not specify handling, show a warning to users that errors may occur
            mismatchEvent.getUnresolved().forEachOrdered((unres) -> {
                final var modid = unres.modid();
                final var diff = unres.versionDifference();
                unresolved.append(System.lineSeparator())
                        .append(diff.isMissing()
                                ? "%s (version %s -> MISSING)".formatted(modid, diff.oldVersion())
                                : "%s (version %s -> %s)".formatted(modid, diff.oldVersion(), diff.newVersion()));
            });

            if (mismatchEvent.anyResolved()) {
                resolved.append(System.lineSeparator()).append("Things may not work well.");
                LOGGER.debug(WORLDPERSISTENCE, resolved.toString());
            }

            if (mismatchEvent.anyUnresolved()) {
                unresolved.append(System.lineSeparator()).append("Things may not work well.");
                LOGGER.warn(WORLDPERSISTENCE, unresolved.toString());
            }
        }
    }

@Test
    @Timeout(value = 60000, unit = TimeUnit.MILLISECONDS)
    public void testConcurrentUsage() throws Throwable {
        final AtomicBoolean finished = new AtomicBoolean();
        final AtomicReference<Throwable> error = new AtomicReference<Throwable>();
        // With 50 threads issue #6087 is reproducible on every run.
        Thread[] threads = new Thread[50];
        final CyclicBarrier barrier = new CyclicBarrier(threads.length);
        for (int i = 0; i < threads.length; i++) {
            Thread t = new Thread(new Runnable() {
                final Queue<LeakAwareResource> resources = new ArrayDeque<LeakAwareResource>(100);

                @Override
                public void run() {
                    try {
                        barrier.await();

                        // Run 10000 times or until the test is marked as finished.
                        for (int b = 0; b < 1000 && !finished.get(); b++) {

                            // Allocate 100 LeakAwareResource per run and close them after it.
                            for (int a = 0; a < 100; a++) {
                                DefaultResource resource = new DefaultResource();
                                ResourceLeakTracker<Resource> leak = DefaultResource.detector.track(resource);
                                LeakAwareResource leakAwareResource = new LeakAwareResource(resource, leak);
                                resources.add(leakAwareResource);
                            }
                            if (closeResources(true)) {
                                finished.set(true);
                            }
                        }
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                    } catch (Throwable e) {
                        error.compareAndSet(null, e);
                    } finally {
                        // Just close all resource now without assert it to eliminate more reports.
                        closeResources(false);
                    }
                }

                private boolean closeResources(boolean checkClosed) {
                    for (;;) {
                        LeakAwareResource r = resources.poll();
                        if (r == null) {
                            return false;
                        }
                        boolean closed = r.close();
                        if (checkClosed && !closed) {
                            error.compareAndSet(null,
                                    new AssertionError("ResourceLeak.close() returned 'false' but expected 'true'"));
                            return true;
                        }
                    }
                }
            });
            threads[i] = t;
            t.start();
        }

        // Just wait until all threads are done.
        for (Thread t: threads) {
            t.join();
        }

        // Check if we had any leak reports in the ResourceLeakDetector itself
        DefaultResource.detector.assertNoErrors();

        assertNoErrors(error);
    }

@Override
    public void complete(LineReader reader, ParsedLine line, List<Candidate> candidates) {
        final CraftServer server = this.server.server;
        final String buffer = "/" + line.line();
        // Async Tab Complete
        final com.destroystokyo.paper.event.server.AsyncTabCompleteEvent event =
            new com.destroystokyo.paper.event.server.AsyncTabCompleteEvent(server.getConsoleSender(), buffer, true, null);
        event.callEvent();
        final List<com.destroystokyo.paper.event.server.AsyncTabCompleteEvent.Completion> completions = event.isCancelled() ? com.google.common.collect.ImmutableList.of() : event.completions();

        if (event.isCancelled() || event.isHandled()) {
            // Still fire sync event with the provided completions, if someone is listening
            if (!event.isCancelled() && TabCompleteEvent.getHandlerList().getRegisteredListeners().length > 0) {
                List<com.destroystokyo.paper.event.server.AsyncTabCompleteEvent.Completion> finalCompletions = new java.util.ArrayList<>(completions);
                Waitable<List<String>> syncCompletions = new Waitable<>() {
                    @Override
                    protected List<String> evaluate() {
                        org.bukkit.event.server.TabCompleteEvent syncEvent = new org.bukkit.event.server.TabCompleteEvent(server.getConsoleSender(), buffer,
                            finalCompletions.stream()
                                .map(com.destroystokyo.paper.event.server.AsyncTabCompleteEvent.Completion::suggestion)
                                .collect(java.util.stream.Collectors.toList()));
                        return syncEvent.callEvent() ? syncEvent.getCompletions() : com.google.common.collect.ImmutableList.of();
                    }
                };
                server.getServer().processQueue.add(syncCompletions);
                try {
                    final List<String> legacyCompletions = syncCompletions.get();
                    completions.removeIf(it -> !legacyCompletions.contains(it.suggestion())); // remove any suggestions that were removed
                    // add any new suggestions
                    for (final String completion : legacyCompletions) {
                        if (notNewSuggestion(completions, completion)) {
                            continue;
                        }
                        completions.add(com.destroystokyo.paper.event.server.AsyncTabCompleteEvent.Completion.completion(completion));
                    }
                } catch (InterruptedException | ExecutionException e1) {
                    e1.printStackTrace();
                }
            }

            this.addCompletions(reader, line, candidates, completions);
            return;
        }

        // Paper end
        Waitable<List<String>> waitable = new Waitable<>() {
            @Override
            protected List<String> evaluate() {
                List<String> offers = server.getCommandMap().tabComplete(server.getConsoleSender(), buffer); // Paper - Remove "this."

                TabCompleteEvent tabEvent = new TabCompleteEvent(server.getConsoleSender(), buffer, (offers == null) ? Collections.emptyList() : offers); // Paper - Remove "this."
                server.getPluginManager().callEvent(tabEvent); // Paper - Remove "this."

                return tabEvent.isCancelled() ? Collections.emptyList() : tabEvent.getCompletions();
            }
        };
        server.getServer().processQueue.add(waitable); // Paper - Remove "this."
        try {
            List<String> offers = waitable.get();
            if (offers == null) {
                this.addCompletions(reader, line, candidates, Collections.emptyList()); // Paper - Enhance console tab completions for brigadier commands
                return; // Paper - Method returns void
            }

            this.addCompletions(reader, line, candidates, offers.stream().map(com.destroystokyo.paper.event.server.AsyncTabCompleteEvent.Completion::completion).collect(java.util.stream.Collectors.toList()));
        } catch (ExecutionException e) {
            server.getLogger().log(Level.WARNING, "Unhandled exception when tab completing", e); // Paper - Remove "this."
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

@Test
    public void childQueueIsDrainedAndNewDataIsDispatchedInParentReadLoopNoAutoRead() {
        final AtomicInteger numReads = new AtomicInteger(1);
        final AtomicInteger channelReadCompleteCount = new AtomicInteger(0);
        final AtomicBoolean shouldDisableAutoRead = new AtomicBoolean();
        Consumer<ChannelHandlerContext> ctxConsumer = new Consumer<ChannelHandlerContext>() {
            @Override
            public void accept(ChannelHandlerContext obj) {
                channelReadCompleteCount.incrementAndGet();
                if (shouldDisableAutoRead.get()) {
                    obj.channel().config().setAutoRead(false);
                }
            }
        };
        final LastInboundHandler inboundHandler = new LastInboundHandler(ctxConsumer);
        Http2StreamChannel childChannel = newInboundStream(3, false, numReads, inboundHandler);
        childChannel.config().setAutoRead(false);

        Http2DataFrame dataFrame1 = new DefaultHttp2DataFrame(bb("1")).stream(childChannel.stream());
        Http2DataFrame dataFrame2 = new DefaultHttp2DataFrame(bb("2")).stream(childChannel.stream());
        Http2DataFrame dataFrame3 = new DefaultHttp2DataFrame(bb("3")).stream(childChannel.stream());
        Http2DataFrame dataFrame4 = new DefaultHttp2DataFrame(bb("4")).stream(childChannel.stream());

        assertEquals(new DefaultHttp2HeadersFrame(request).stream(childChannel.stream()), inboundHandler.readInbound());

        ChannelHandler readCompleteSupressHandler = new ChannelInboundHandlerAdapter() {
            @Override
            public void channelReadComplete(ChannelHandlerContext ctx) throws Exception {
                // We want to simulate the parent channel calling channelRead and delay calling channelReadComplete.
            }
        };
        parentChannel.pipeline().addFirst(readCompleteSupressHandler);

        frameInboundWriter.writeInboundData(childChannel.stream().id(), bb("1"), 0, false);

        assertEqualsAndRelease(dataFrame1, inboundHandler.<Http2Frame>readInbound());

        // We want one item to be in the queue, and allow the numReads to be larger than 1. This will ensure that
        // when beginRead() is called the child channel is added to the readPending queue of the parent channel.
        frameInboundWriter.writeInboundData(childChannel.stream().id(), bb("2"), 0, false);

        numReads.set(2);
        childChannel.read();

        assertEqualsAndRelease(dataFrame2, inboundHandler.<Http2Frame>readInbound());

        assertNull(inboundHandler.readInbound());

        // This is the second item that was read, this should be the last until we call read() again. This should also
        // notify of readComplete().
        frameInboundWriter.writeInboundData(childChannel.stream().id(), bb("3"), 0, false);

        assertEqualsAndRelease(dataFrame3, inboundHandler.<Http2Frame>readInbound());

        frameInboundWriter.writeInboundData(childChannel.stream().id(), bb("4"), 0, false);
        assertNull(inboundHandler.readInbound());

        childChannel.read();

        assertEqualsAndRelease(dataFrame4, inboundHandler.<Http2Frame>readInbound());

        assertNull(inboundHandler.readInbound());

        // Now we want to call channelReadComplete and simulate the end of the read loop.
        parentChannel.pipeline().remove(readCompleteSupressHandler);
        parentChannel.flushInbound();

        // 3 = 1 for initialization + 1 for first read of 2 items + 1 for second read of 2 items +
        // 1 for parent channel readComplete
        assertEquals(4, channelReadCompleteCount.get());
    }

@ParameterizedTest
    @ValueSource(booleans = {true, false})
    @EnabledIf("recvsendBundleEnabled")
    public void testProviderBufferReadWithRecvsendBundle(boolean incremental) throws InterruptedException {
        // See https://lore.kernel.org/io-uring/184f9f92-a682-4205-a15d-89e18f664502@kernel.dk/T/#u
        assumeTrue(IoUring.isRecvMultishotEnabled());

        if (incremental) {
            assumeTrue(IoUring.isRegisterBufferRingIncSupported());
        }
        int bufferRingChunkSize = 8;
        IoUringIoHandlerConfig ioUringIoHandlerConfiguration = new IoUringIoHandlerConfig();
        IoUringBufferRingConfig bufferRingConfig = new IoUringBufferRingConfig(
                // let's use a small chunkSize so we are sure a recv will span multiple buffers.
                (short) 1, (short) 16, 8, 16 * 16,
                incremental, new IoUringFixedBufferRingAllocator(bufferRingChunkSize));

        ioUringIoHandlerConfiguration.setBufferRingConfig(bufferRingConfig);

        MultiThreadIoEventLoopGroup group = new MultiThreadIoEventLoopGroup(1,
                IoUringIoHandler.newFactory(ioUringIoHandlerConfiguration)
        );
        ServerBootstrap serverBootstrap = new ServerBootstrap();
        serverBootstrap.channel(IoUringServerSocketChannel.class);

        final BlockingQueue<ByteBuf> buffers = new LinkedBlockingQueue<>();
        Channel serverChannel = serverBootstrap.group(group)
                .childHandler(new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        buffers.offer((ByteBuf) msg);
                    }
                })
                .childOption(IoUringChannelOption.IO_URING_BUFFER_GROUP_ID, (short) 1)
                .bind(new InetSocketAddress(0))
                .syncUninterruptibly().channel();

        Bootstrap clientBoostrap = new Bootstrap();
        clientBoostrap.group(group)
                .channel(IoUringSocketChannel.class)
                .handler(new ChannelInboundHandlerAdapter());
        ChannelFuture channelFuture = clientBoostrap.connect(serverChannel.localAddress()).syncUninterruptibly();
        assertTrue(channelFuture.isSuccess());
        Channel clientChannel = channelFuture.channel();

        // Create a buffer that will span multiple buffers that are used out of the buffer ring.
        ByteBuf writeBuffer = Unpooled.directBuffer(bufferRingChunkSize * 16);
        CompositeByteBuf received = Unpooled.compositeBuffer();
        try {
            // Fill the buffer with something so we can assert if the received bytes are the same.
            for (int i = 0; i < writeBuffer.capacity(); i++) {
                writeBuffer.writeByte((byte) i);
            }
            clientChannel.writeAndFlush(writeBuffer.retainedDuplicate()).syncUninterruptibly();

            // Aggregate all received buffers until we received everything.
            do {
                ByteBuf buffer = buffers.take();
                received.addComponent(true, buffer);
            } while (received.readableBytes() != writeBuffer.readableBytes());

            assertEquals(writeBuffer, received);
            serverChannel.close().syncUninterruptibly();
            clientChannel.close().syncUninterruptibly();
            group.shutdownGracefully();
            assertTrue(buffers.isEmpty());
        } finally {
            writeBuffer.release();
            received.release();
        }
    }

@Test
    public void testMultipleCancelledWritesWithEarlierFlush() {
        final AtomicInteger writable = new AtomicInteger();
        final AtomicInteger sizeAtEvent = new AtomicInteger(-1);
        final AtomicLong pendingAtEvent = new AtomicLong(-1);
        final AtomicReference<Object> currentAtEvent = new AtomicReference<Object>();
        EmbeddedChannel ch = new EmbeddedChannel();
        final ChannelOutboundBuffer buffer = ch.unsafe().outboundBuffer();
        ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
            @Override
            public void channelWritabilityChanged(ChannelHandlerContext ctx) {
                if (ctx.channel().isWritable()) {
                    writable.incrementAndGet();
                    sizeAtEvent.set(buffer.size());
                    pendingAtEvent.set(buffer.totalPendingWriteBytes());
                    currentAtEvent.set(buffer.current());
                }
                ctx.fireChannelWritabilityChanged();
            }
        });
        ch.config().setWriteBufferWaterMark(new WriteBufferWaterMark(400, 800));

        // Use the ChannelOutboundBuffer directly so nothing is written and flushedEntry stays set after the flush.
        ByteBuf live0 = wrappedBuffer(new byte[] { 0 });
        buffer.addMessage(live0, 1, ch.newPromise());
        buffer.addFlush();
        assertEquals(1, buffer.size());
        assertSame(live0, buffer.current());

        // Cancelled writes at the head, in the middle and at the tail of the second batch.
        ByteBuf[] cancelledBufs = new ByteBuf[3];
        ByteBuf[] liveBufs = new ByteBuf[2];
        ChannelPromise[] cancelledPromises = new ChannelPromise[3];
        for (int i = 0; i < 3; i++) {
            cancelledBufs[i] = buffer().writeZero(300);
            cancelledPromises[i] = ch.newPromise();
            buffer.addMessage(cancelledBufs[i], 300, cancelledPromises[i]);
            if (i < 2) {
                liveBufs[i] = wrappedBuffer(new byte[] { (byte) (i + 1) });
                buffer.addMessage(liveBufs[i], 1, ch.newPromise());
            }
        }
        assertFalse(ch.isWritable());
        for (ChannelPromise promise : cancelledPromises) {
            assertTrue(promise.cancel(false));
        }

        buffer.addFlush();

        assertEquals(1, writable.get());
        // The buffer must already be consistent when the event is fired.
        assertEquals(6, sizeAtEvent.get());
        assertEquals(buffer.totalPendingWriteBytes(), pendingAtEvent.get());
        assertSame(live0, currentAtEvent.get());
        assertEquals(6, buffer.size());
        assertTrue(ch.isWritable());
        for (ByteBuf cancelledBuf : cancelledBufs) {
            assertEquals(0, cancelledBuf.refCnt());
        }
        assertEquals(1, live0.refCnt());
        for (ByteBuf liveBuf : liveBufs) {
            assertEquals(1, liveBuf.refCnt());
        }

        ch.close();
        assertEquals(0, live0.refCnt());
        for (ByteBuf liveBuf : liveBufs) {
            assertEquals(0, liveBuf.refCnt());
        }
        assertEquals(0, buffer.totalPendingWriteBytes());
    }

@OnlyIn(Dist.CLIENT)
    @Override
    public void act(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, UnwindingChaosChargeEffectData extraData) {
        final Entity entity = level.getEntity(extraData.entityId);
        if (entity != null) {
            var smokeColor = new Color(45, 15, 15);
            long gameTime = level.getGameTime();
            var pos = positionData.getAsVector();
            var direction = pos.subtract(entity.position()).normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
            float yaw = (float) Math.toRadians(yRot);
            Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
            Vec3 up = left.cross(direction);

            Consumer<LodestoneWorldParticle> behavior = p -> {
                Vec3 distance = entity.position().add(0, entity.getBbHeight() / 2f, 0).subtract(p.getParticlePosition());
                if (distance.length() == 0) {
                    distance = new Vec3(0, 0.02f, 0);
                }
                float delta = Math.max(p.getAge() / (float) p.getLifetime(), 0);
                float lerp = Easing.QUINTIC_IN_OUT.lerp(delta, 0.05f, 0.5f);
                float velocity = (float) Easing.CIRC_IN.lerp(delta, 0.05f, 0.2f + distance.length() * 1.2f);
                final Vec3 speed = p.getParticleSpeed().lerp(distance.normalize().scale(velocity), lerp);
                p.setParticleSpeed(speed);
            };

            for (int i = 0; i < 16; i++) {
                SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
                float spread = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 0.6f);
                float speed = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float angle = i / 16f * (float) Math.PI * 2f;
                Vec3 particleDirection = direction
                        .add(left.scale(Math.sin(angle) * spread))
                        .add(up.scale(Math.cos(angle) * spread))
                        .normalize().scale(speed);
                Vec3 particlePosition = pos.add(particleDirection.scale(2f));
                var lightSpecs = spiritLightSpecs(level, particlePosition, cyclingSpiritType, new WorldParticleOptions(MalumParticles.SPARK.get()));
                var transparencyData = GenericParticleData.create(0.4f, 0.8f, 0f).setEasing(Easing.SINE_IN_OUT, Easing.EXPO_IN_OUT).build();
                int lifeDelay = i * 2;
                int lifetime = 20;
                lightSpecs.getBuilder()
                        .setBehavior(SparkParticleBehavior.sparkBehavior())
                        .setLengthData(GenericParticleData.create(0.2f, 2f, 0f).setEasing(Easing.SINE_IN, Easing.SINE_IN_OUT).build())
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 2, 2.5f)))
                        .modifyColorData(c -> c.multiplyCoefficient(0.5f))
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .setLifetime(lifetime)
                        .addTickActor(behavior);
                lightSpecs.getBloomBuilder()
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .setLifetime(lifetime)
                        .addTickActor(behavior)
                        .modifyColorData(c -> c.multiplyCoefficient(0.5f))
                        .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.7f, 1.1f)))
                        .modifyTransparencyData(d -> d.multiplyCoefficient(1.4f));
                lightSpecs.spawnParticles();

                lightSpecs = spiritLightSpecs(level, particlePosition, cyclingSpiritType, new WorldParticleOptions(LodestoneParticleTypes.WISP_PARTICLE.get()));
                transparencyData = GenericParticleData.create(1f, 0f).setCoefficient(1.5f).build();
                lightSpecs.getBuilder()
                        .setRenderType(LodestoneWorldParticleRenderType.LUMITRANSPARENT)
                        .setColorData(ColorParticleData.create(smokeColor).build())
                        .setTransparencyData(transparencyData)
                        .setLifeDelay(lifeDelay)
                        .addTickActor(behavior)
                        .setLifetime(lifetime);
                lightSpecs.spawnParticlesRaw();
            }
        }
    }

@ParameterizedTest(name = "{index}: provider={0}, protocol={1}")
    @Timeout(30)
    @MethodSource("data")
    public void eventsOrder(SslProvider provider, String protocol) throws Exception {
        assumeTrue(provider != SslProvider.OPENSSL || OpenSsl.isAvailable(), "OpenSSL is not available");

        if (SslProtocols.TLS_v1_3.equals(protocol)) {
            // Ensure we support TLSv1.3
            assumeTrue(SslProvider.isTlsv13Supported(provider));
        }
        BlockingQueue<Object> clientEventQueue = new LinkedBlockingQueue<Object>();
        BlockingQueue<Object> serverEventQueue = new LinkedBlockingQueue<Object>();

        EmbeddedChannel clientChannel = initChannel(provider, protocol, true, clientEventQueue);
        EmbeddedChannel serverChannel = initChannel(provider, protocol, false, serverEventQueue);

        try {
            // handshake:
            forwardData(clientChannel, serverChannel);
            forwardData(serverChannel, clientChannel);
            forwardData(clientChannel, serverChannel);
            forwardData(serverChannel, clientChannel);
            assertInstanceOf(SslHandshakeCompletionEvent.class, clientEventQueue.poll());
            assertInstanceOf(SslHandshakeCompletionEvent.class, serverEventQueue.poll());
            assertEquals(protocol, handshakenProtocol(clientChannel));

            // send data:
            clientChannel.writeOutbound(writeAscii(ALLOC, "request_msg"));
            forwardData(clientChannel, serverChannel);
            assertEquals("request_msg", serverEventQueue.poll());

            // respond with data and close_notify:
            serverChannel.writeOutbound(writeAscii(ALLOC, "response_msg"));
            assertTrue(serverChannel.finish());
            assertInstanceOf(SslCloseCompletionEvent.class, serverEventQueue.poll());
            assertTrue(clientEventQueue.isEmpty());

            // consume server response with close_notify:
            forwardAllWithCloseNotify(serverChannel, clientChannel);
            assertEquals("response_msg", clientEventQueue.poll());
            assertInstanceOf(SslCloseCompletionEvent.class, clientEventQueue.poll());

            // make sure client automatically responds with close_notify:
            if (!jdkTls13(provider, protocol)) {
                // JDK impl of TLSv1.3 does not automatically generate "close_notify" in response to the received
                // "close_notify" alert. This is a legit behavior according to the spec:
                // https://tools.ietf.org/html/rfc8446#section-6.1. Handle it differently:
                assertCloseNotify((ByteBuf) clientChannel.readOutbound());
            }
        } finally {
            try {
                clientChannel.finish();
            } finally {
                serverChannel.finish();
            }
        }

        if (jdkTls13(provider, protocol)) {
            assertCloseNotify((ByteBuf) clientChannel.readOutbound());
        } else {
            discardEmptyOutboundBuffers(clientChannel);
        }

        assertEquals(INACTIVE, clientEventQueue.poll());
        assertTrue(clientEventQueue.isEmpty());
        assertEquals(INACTIVE, serverEventQueue.poll());
        assertTrue(serverEventQueue.isEmpty());

        assertFalse(clientChannel.releaseInbound());
        assertFalse(clientChannel.releaseOutbound());
        assertFalse(serverChannel.releaseInbound());
        assertFalse(serverChannel.releaseOutbound());
    }

@Timeout(value = 60, threadMode = Timeout.ThreadMode.SEPARATE_THREAD)
    @MethodSource("newTestParams")
    @ParameterizedTest
    public void mustNotCallResumeWhenClientAuthIsOptionalAndNoClientCertIsProvided(SSLEngineTestParam param)
            throws Exception {
        SelfSignedCertificate ssc = CachedSelfSignedCertificate.getCachedCertificate();
        SessionValueSettingTrustManager clientTm = new SessionValueSettingTrustManager("key", "client");
        SessionValueSettingTrustManager serverTm = new SessionValueSettingTrustManager("key", "server");
        clientSslCtx = wrapContext(param, SslContextBuilder.forClient()
                .trustManager(clientTm)
                .sslProvider(sslClientProvider())
                .sslContextProvider(clientSslContextProvider())
                .protocols(param.protocols())
                .ciphers(param.ciphers())
                .build()); // Client provides no certificate!
        serverSslCtx = wrapContext(param, SslContextBuilder.forServer(ssc.certificate(), ssc.privateKey())
                .trustManager(serverTm)
                .sslProvider(sslServerProvider())
                .sslContextProvider(serverSslContextProvider())
                .protocols(param.protocols())
                .ciphers(param.ciphers())
                .clientAuth(ClientAuth.OPTIONAL) // Client auth is OPTIONAL!
                .build());
        final BlockingQueue<String> clientSessionValues = new LinkedBlockingQueue<String>();
        final BlockingQueue<String> serverSessionValues = new LinkedBlockingQueue<String>();
        OnNextMessage checkClient = new OnNextMessage() {
            @Override
            public void messageReceived(ChannelHandlerContext ctx, ByteBuf msg) throws Exception {
                msg.release();
                SslHandler sslHandler = ctx.pipeline().get(SslHandler.class);
                SSLEngine engine = sslHandler.engine();
                logger.debug("Client message received: {} ({}) {} {}",
                        engine.getSession(), engine.getHandshakeStatus(), isSessionReused(engine),
                        Arrays.toString(engine.getSession().getValueNames()));
                Object value = engine.getSession().getValue("key");
                clientSessionValues.put((String) value);
            }
        };
        OnNextMessage checkServer = new OnNextMessage() {
            @Override
            public void messageReceived(ChannelHandlerContext ctx, ByteBuf msg) throws Exception {
                SslHandler sslHandler = ctx.pipeline().get(SslHandler.class);
                SSLEngine engine = sslHandler.engine();
                logger.debug("Server message received: {} ({}) {} {}",
                        engine.getSession(), engine.getHandshakeStatus(), isSessionReused(engine),
                        Arrays.toString(engine.getSession().getValueNames()));
                Object value = engine.getSession().getValue("key");
                serverSessionValues.put(value == null ? "NULL" : String.valueOf(value));
                ctx.writeAndFlush(msg).addListener(ChannelFutureListener.CLOSE);
            }
        };

        setupServer(param.type(), param.delegate());
        InetSocketAddress addr = (InetSocketAddress) serverChannel.localAddress();
        setupClient(param.type(), param.delegate(), "a.netty.io", addr.getPort());
        for (int i = 0; i < 10; i++) {
            clientReceiver.onNextMessages.offer(checkClient);
            serverReceiver.onNextMessages.offer(checkServer);

            ChannelFuture ccf = cb.connect(addr);
            assertTrue(ccf.syncUninterruptibly().isSuccess());
            clientChannel = ccf.channel();

            clientChannel.writeAndFlush(clientChannel.alloc().buffer().writeInt(42)).sync();
            assertEquals("client", clientSessionValues.take());
            assertEquals("NULL", serverSessionValues.take());
            clientChannel.closeFuture().sync();
        }
        assertTrue(clientReceiver.onNextMessages.isEmpty());
        assertTrue(serverReceiver.onNextMessages.isEmpty());
        assertTrue(clientSessionValues.isEmpty());
        assertTrue(serverSessionValues.isEmpty());
    }

@Test
    public void testAcquireCancelledDuringHealthCheckOffersChannelBack() throws Exception {
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(LocalIoHandler.newFactory());
        LocalAddress addr = new LocalAddress(getLocalAddrId());
        Bootstrap cb = new Bootstrap()
                .group(group)
                .channel(LocalChannel.class)
                .remoteAddress(addr);
        ServerBootstrap sb = new ServerBootstrap()
                .group(group)
                .channel(LocalServerChannel.class)
                .childHandler(new ChannelInitializer<LocalChannel>() {
                    @Override
                    public void initChannel(LocalChannel ch) throws Exception {
                        ch.pipeline().addLast(new ChannelInboundHandlerAdapter());
                    }
                });
        Channel sc = sb.bind(addr).sync().channel();
        CountingChannelPoolHandler handler = new CountingChannelPoolHandler();

        // Hand out health checks that we complete ourselves, so the acquire Promise can be cancelled while the
        // health check of an already pooled Channel is still pending.
        final BlockingQueue<Promise<Boolean>> healthChecks = new LinkedBlockingQueue<Promise<Boolean>>();
        ChannelHealthChecker healthChecker = channel -> {
            Promise<Boolean> healthCheck = channel.eventLoop().newPromise();
            healthChecks.add(healthCheck);
            return healthCheck;
        };
        // Health checks on release are turned off, so releasing does not need a hand-completed health check as well.
        SimpleChannelPool pool = new SimpleChannelPool(cb, handler, healthChecker, false);

        Channel channel = null;
        try {
            // Nothing is pooled yet, so this connects a new Channel and does not run a health check at all.
            channel = pool.acquire().sync().getNow();
            pool.release(channel).sync();
            assertTrue(healthChecks.isEmpty());
            assertEquals(1, handler.acquiredCount());
            assertEquals(1, handler.releasedCount());

            // This acquire reuses the pooled Channel, so it has to pass the health check first.
            Promise<Channel> acquirePromise = group.next().newPromise();
            pool.acquire(acquirePromise);
            Promise<Boolean> healthCheck = healthChecks.poll(5, TimeUnit.SECONDS);
            assertNotNull(healthCheck);

            assertTrue(acquirePromise.cancel(false));
            healthCheck.setSuccess(Boolean.TRUE);

            // Let the health check listener run on the EventLoop of the Channel.
            channel.eventLoop().submit(() -> { }).sync();

            assertTrue(acquirePromise.isCancelled());
            assertEquals(2, handler.acquiredCount());
            assertEquals(2, handler.releasedCount());
            assertTrue(channel.isActive());

            // The Channel went back into the pool, so the next acquire hands out the very same Channel.
            Promise<Channel> secondAcquirePromise = group.next().newPromise();
            pool.acquire(secondAcquirePromise);
            Promise<Boolean> secondHealthCheck = healthChecks.poll(5, TimeUnit.SECONDS);
            assertNotNull(secondHealthCheck);
            secondHealthCheck.setSuccess(Boolean.TRUE);
            assertSame(channel, secondAcquirePromise.sync().getNow());
        } finally {
            if (channel != null) {
                channel.close().sync();
            }
            sc.close().sync();
            pool.close();
            group.shutdownGracefully();
        }
    }

@Override
    protected void doWrite(ChannelOutboundBuffer channelOutboundBuffer) throws Exception {
        if (!supportsDatagram) {
            throw new UnsupportedOperationException("Datagram extension is not supported");
        }
        boolean sendSomething = false;
        boolean retry = false;
        QuicheQuicConnection conn = connection;
        try {
            for (;;) {
                ByteBuf buffer = (ByteBuf) channelOutboundBuffer.current();
                if (buffer == null) {
                    break;
                }

                int readable = buffer.readableBytes();
                if (readable == 0) {
                    // Skip empty buffers.
                    channelOutboundBuffer.remove();
                    continue;
                }

                final int res;
                if (!buffer.isDirect() || buffer.nioBufferCount() > 1) {
                    ByteBuf tmpBuffer = alloc().directBuffer(readable);
                    try {
                        tmpBuffer.writeBytes(buffer, buffer.readerIndex(), readable);
                        res = sendDatagram(conn, tmpBuffer);
                    } finally {
                        tmpBuffer.release();
                    }
                } else {
                    res = sendDatagram(conn, buffer);
                }
                if (res >= 0) {
                    channelOutboundBuffer.remove();
                    sendSomething = true;
                    retry = false;
                } else {
                    if (res == Quiche.QUICHE_ERR_BUFFER_TOO_SHORT) {
                        retry = false;
                        channelOutboundBuffer.remove(new BufferUnderflowException());
                    } else if (res == Quiche.QUICHE_ERR_INVALID_STATE) {
                        throw new UnsupportedOperationException("Remote peer does not support Datagram extension");
                    } else if (res == Quiche.QUICHE_ERR_DONE) {
                        if (retry) {
                            // We already retried and it didn't work. Let's drop the datagrams on the floor.
                            for (;;) {
                                if (!channelOutboundBuffer.remove()) {
                                    // The buffer is empty now.
                                    return;
                                }
                            }
                        }
                        // Set sendSomething to false a we will call connectionSend() now.
                        sendSomething = false;
                        // If this returned DONE we couldn't write anymore. This happens if the internal queue
                        // is full. In this case we should call quiche_conn_send(...) and so make space again.
                        if (connectionSend(conn) != SendResult.NONE) {
                            forceFlushParent();
                        }
                        // Let's try again to write the message.
                        retry = true;
                    } else {
                        throw Quiche.convertToException(res);
                    }
                }
            }
        } finally {
            if (sendSomething && connectionSend(conn) != SendResult.NONE) {
                flushParent();
            }
        }
    }

@ParameterizedTest
    @ValueSource(booleans = {true, false})
    public void testInboundOperationsViaContext(boolean inEventLoop) throws Exception {
        ChannelPipeline pipeline = new LocalChannel().pipeline();
        final ChannelHandler handler = new ChannelHandlerAdapter() { };
        pipeline.addLast(handler);
        group.register(pipeline.channel()).syncUninterruptibly();
        final BlockingQueue<String> events = new LinkedBlockingQueue<>();
        pipeline.addLast(new ChannelInboundHandlerAdapter() {
            @Override
            public void channelRegistered(ChannelHandlerContext ctx) {
                events.add("channelRegistered");
            }

            @Override
            public void channelUnregistered(ChannelHandlerContext ctx) {
                events.add("channelUnregistered");
            }

            @Override
            public void channelActive(ChannelHandlerContext ctx) {
                events.add("channelActive");
            }

            @Override
            public void channelInactive(ChannelHandlerContext ctx) {
                events.add("channelInactive");
            }

            @Override
            public void channelRead(ChannelHandlerContext ctx, Object msg) {
                events.add("channelRead");
            }

            @Override
            public void channelReadComplete(ChannelHandlerContext ctx) {
                events.add("channelReadComplete");
            }

            @Override
            public void userEventTriggered(ChannelHandlerContext ctx, Object evt)  {
                events.add("userEventTriggered");
            }

            @Override
            public void channelWritabilityChanged(ChannelHandlerContext ctx) {
                events.add("channelWritabilityChanged");
            }

            @Override
            public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                events.add("exceptionCaught");
            }
        });
        final ChannelHandlerContext ctx = pipeline.context(handler);
        if (inEventLoop) {
            pipeline.channel().eventLoop().execute(() -> executeInboundOperations(ctx));
        } else {
            executeInboundOperations(ctx);
        }

        assertEquals("channelRegistered", events.take());
        assertEquals("channelUnregistered", events.take());
        assertEquals("channelActive", events.take());
        assertEquals("channelInactive", events.take());
        assertEquals("channelRead", events.take());
        assertEquals("channelReadComplete", events.take());
        assertEquals("userEventTriggered", events.take());
        assertEquals("channelWritabilityChanged", events.take());
        assertEquals("exceptionCaught", events.take());
        assertTrue(events.isEmpty());
        pipeline.removeLast();
        pipeline.channel().close().syncUninterruptibly();
    }

