public final ByteBuf remove(ByteBufAllocator alloc, int bytes, ChannelPromise aggregatePromise) {
        checkPositiveOrZero(bytes, "bytes");
        checkNotNull(aggregatePromise, "aggregatePromise");

        // Use isEmpty rather than readableBytes==0 as we may have a promise associated with an empty buffer.
        if (bufAndListenerPairs.isEmpty()) {
            reconcileReadableBytes();
            return removeEmptyValue();
        }
        bytes = Math.min(bytes, readableBytes);

        ByteBuf toReturn = null;
        ByteBuf entryBuffer = null;
        int originalBytes = bytes;
        Object entry = null;
        try {
            for (;;) {
                entry = bufAndListenerPairs.poll();
                if (entry == null) {
                    break;
                }
                // fast-path vs abstract type
                if (entry instanceof ByteBuf) {
                    entryBuffer = (ByteBuf) entry;
                    int bufferBytes = entryBuffer.readableBytes();

                    if (bufferBytes > bytes) {
                        // Add the buffer back to the queue as we can't consume all of it.
                        bufAndListenerPairs.addFirst(entryBuffer);
                        if (bytes > 0) {
                            // Take a slice of what we can consume and retain it.
                            entryBuffer = entryBuffer.readRetainedSlice(bytes);
                            // we end here, so if this is the only buffer to return, skip composing
                            toReturn = toReturn == null ? entryBuffer
                                    : compose(alloc, toReturn, entryBuffer);
                            bytes = 0;
                        }
                        break;
                    }

                    bytes -= bufferBytes;
                    if (toReturn == null) {
                        // if there are no more bytes to read, there's no reason to compose
                        toReturn = bytes == 0
                                ? entryBuffer
                                : composeFirst(alloc, entryBuffer, bufferBytes + bytes);
                    } else {
                        toReturn = compose(alloc, toReturn, entryBuffer);
                    }
                    entryBuffer = null;
                } else if (entry instanceof DelegatingChannelPromiseNotifier) {
                    aggregatePromise.addListener((DelegatingChannelPromiseNotifier) entry);
                } else if (entry instanceof ChannelFutureListener) {
                    aggregatePromise.addListener((ChannelFutureListener) entry);
                }
            }
        } catch (Throwable cause) {
            // Always decrement to keep things consistent. We decrement directly here and not in a finally-block
            // to ensure that the state is consistent even if it would be accessed via a listener that is
            // attached to the promise that we fail below.
            decrementReadableBytes(originalBytes - bytes);

            // Poll the next element if it's a listener that belongs to the ByteBuf.
            entry = bufAndListenerPairs.peek();
            if (entry instanceof ChannelFutureListener) {
                aggregatePromise.addListener((ChannelFutureListener) entry);
                bufAndListenerPairs.poll();
            }

            safeRelease(entryBuffer);
            safeRelease(toReturn);
            aggregatePromise.setFailure(cause);
            throwException(cause);
        }
        decrementReadableBytes(originalBytes - bytes);
        reconcileReadableBytes();
        return toReturn;
    }

@Override
    protected void doClose() throws Exception {
        final LocalChannel peer = this.peer;
        State oldState = state;
        State closedFrom = oldState;
        try {
            if (oldState != State.CLOSED) {
                // Update all internal state before the closeFuture is notified.
                if (localAddress != null) {
                    if (parent() == null) {
                        LocalChannelRegistry.unregister(localAddress);
                    }
                    localAddress = null;
                }

                // State change must happen before finishPeerRead to ensure writes are released either in doWrite or
                // channelRead.
                // Use getAndSet() as an accepted channel may concurrently move this channel from BOUND to CONNECTED
                // when it is registered. See LocalUnsafe.registered().
                closedFrom = STATE_UPDATER.getAndSet(this, State.CLOSED);

                // Preserve order of event and force a read operation now before the close operation is processed.
                if (writeInProgress && peer != null) {
                    finishPeerRead(peer);
                }

                ChannelPromise promise = connectPromise;
                if (promise != null) {
                    // Use tryFailure() instead of setFailure() to avoid the race against cancel().
                    promise.tryFailure(new ClosedChannelException());
                    connectPromise = null;
                }
            }

            if (peer != null && parent() == null && closedFrom != State.CONNECTED) {
                // The accepted channel did not complete the connection. Don't touch it: it may not have an event
                // loop yet and is owned by the server channel or its own event loop. When it is registered it sees
                // that this channel is closed and closes itself. If it was closed already, its close has notified
                // this channel or will do so.
                this.peer = null;
            } else if (peer != null) {
                this.peer = null;
                // Always call peer.eventLoop().execute() even if peer.eventLoop().inEventLoop() is true.
                // This ensures that if both channels are on the same event loop, the peer's channelInActive
                // event is triggered *after* this peer's channelInActive event
                EventLoop peerEventLoop = peer.eventLoop();
                final boolean peerIsActive = peer.isActive();
                try {
                    peerEventLoop.execute(new Runnable() {
                        @Override
                        public void run() {
                            peer.tryClose(peerIsActive);
                        }
                    });
                } catch (Throwable cause) {
                    logger.warn("Releasing Inbound Queues for channels {}-{} because exception occurred!",
                            this, peer, cause);
                    if (peerEventLoop.inEventLoop()) {
                        peer.releaseInboundBuffers();
                    } else {
                        // inboundBuffers is a SPSC so we may leak if the event loop is shutdown prematurely or
                        // rejects the close Runnable but give a best effort.
                        peer.close();
                    }
                    PlatformDependent.throwException(cause);
                }
            }
        } finally {
            // Release all buffers if the Channel was already registered in the past and if it was not closed before.
            if (oldState != null && oldState != State.CLOSED) {
                // We need to release all the buffers that may be put into our inbound queue since we closed the Channel
                // to ensure we not leak any memory. This is fine as it basically gives the same guarantees as TCP which
                // means even if the promise was notified before its not really guaranteed that the "remote peer" will
                // see the buffer at all.
                releaseInboundBuffers();
            }
        }
    }

@Test
    @Timeout(value = 5000, unit = TimeUnit.MILLISECONDS)
    public void testServerMaxMessagesPerReadRespectedWithQueuedConnections() throws Exception {
        final int maxMessagesPerRead = 2;
        final int connections = 5;
        final CountDownLatch queuedConnections = new CountDownLatch(connections);
        final BlockingQueue<Integer> messagesPerReadComplete = new LinkedBlockingQueue<Integer>();
        final List<ChannelFuture> connectFutures = new ArrayList<ChannelFuture>();

        Bootstrap cb = new Bootstrap();
        ServerBootstrap sb = new ServerBootstrap();

        cb.group(sharedGroup)
                .channel(LocalChannel.class)
                .handler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) {
                        // NOOP
                    }
                });

        sb.group(sharedGroup)
                .channelFactory(() -> new LocalServerChannel() {
                    @Override
                    protected LocalChannel newLocalChannel(LocalChannel peer) {
                        LocalChannel child = super.newLocalChannel(peer);
                        queuedConnections.countDown();
                        return child;
                    }
                })
                .option(ChannelOption.AUTO_READ, false)
                .option(ChannelOption.MAX_MESSAGES_PER_READ, maxMessagesPerRead)
                .handler(new ChannelInboundHandlerAdapter() {
                    private int messagesRead;

                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        messagesRead++;
                        ctx.fireChannelRead(msg);
                    }

                    @Override
                    public void channelReadComplete(ChannelHandlerContext ctx) {
                        messagesPerReadComplete.add(messagesRead);
                        messagesRead = 0;
                        ctx.fireChannelReadComplete();
                    }
                })
                .childHandler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) {
                        // NOOP
                    }
                });

        Channel sc = null;
        try {
            sc = sb.bind(TEST_ADDRESS).sync().channel();
            for (int i = 0; i < connections; i++) {
                connectFutures.add(cb.connect(TEST_ADDRESS));
            }

            assertTrue(queuedConnections.await(5, SECONDS));

            sc.config().setAutoRead(true);
            assertEquals(maxMessagesPerRead, messagesPerReadComplete.take());
            assertEquals(maxMessagesPerRead, messagesPerReadComplete.take());
            assertEquals(connections - 2 * maxMessagesPerRead, messagesPerReadComplete.take());
            for (ChannelFuture connectFuture : connectFutures) {
                connectFuture.sync();
            }
        } finally {
            for (ChannelFuture connectFuture : connectFutures) {
                closeChannel(connectFuture.channel());
            }
            closeChannel(sc);
        }
    }

private static Set<Chunk> flushQueue(Instance instance, Set<Point> queue, LightType type, QueueType queueType) {
        Set<Light> sections = ConcurrentHashMap.newKeySet();
        Set<Point> newQueue = ConcurrentHashMap.newKeySet();

        Set<Chunk> responseChunks = ConcurrentHashMap.newKeySet();
        List<CompletableFuture<Void>> tasks = new ArrayList<>();

        Light.LightLookup lightLookup = (x, y, z) -> {
            Chunk chunk = instance.getChunk(x, z);
            if (chunk == null) return null;
            if (!(chunk instanceof LightingChunk lighting)) return null;
            if (y - lighting.getMinSection() < 0 || y - lighting.getMaxSection() >= 0) return null;
            final Section section = lighting.getSection(y);
            return switch (type) {
                case BLOCK -> section.blockLight();
                case SKY -> section.skyLight();
            };
        };

        Light.PaletteLookup paletteLookup = (x, y, z) -> {
            Chunk chunk = instance.getChunk(x, z);
            if (chunk == null) return null;
            if (!(chunk instanceof LightingChunk lighting)) return null;
            if (y - lighting.getMinSection() < 0 || y - lighting.getMaxSection() >= 0) return null;
            return chunk.getSection(y).blockPalette();
        };

        for (Point point : queue) {
            Chunk chunk = instance.getChunk(point.blockX(), point.blockZ());
            if (!(chunk instanceof LightingChunk lightingChunk)) continue;

            Section section = chunk.getSection(point.blockY());
            responseChunks.add(chunk);

            Light light = switch (type) {
                case BLOCK -> section.blockLight();
                case SKY -> section.skyLight();
            };

            final Palette blockPalette = section.blockPalette();
            CompletableFuture<Void> task = CompletableFuture.runAsync(() -> {
                try {
                    final Set<Point> toAdd;
                    lightingChunk.lockReadLock();
                    try {
                        toAdd = switch (queueType) {
                            case INTERNAL -> light.calculateInternal(blockPalette,
                                    chunk.getChunkX(), point.blockY(), chunk.getChunkZ(),
                                    lightingChunk.getOcclusionMap(), chunk.instance.getCachedDimensionType().maxY(),
                                    lightLookup);
                            case EXTERNAL -> light.calculateExternal(blockPalette,
                                    Light.getNeighbors(chunk, point.blockY()),
                                    lightLookup, paletteLookup);
                        };
                    } finally {
                        lightingChunk.unlockReadLock();
                    }

                    sections.add(light);

                    light.flip();
                    newQueue.addAll(toAdd);
                } catch (Exception e) {
                    MinecraftServer.getExceptionManager().handleException(e);
                }
            }, pool);

            tasks.add(task);
        }

        tasks.forEach(CompletableFuture::join);

        if (!newQueue.isEmpty()) {
            var newResponse = flushQueue(instance, newQueue, type, QueueType.EXTERNAL);
            responseChunks.addAll(newResponse);
        }

        return responseChunks;
    }

@Override
    public int run(IoHandlerContext context) {
        int handled = 0;
        try {
            int strategy = selectStrategy.calculateStrategy(selectNowSupplier, !context.canBlock());
            switch (strategy) {
                case SelectStrategy.CONTINUE:
                    if (context.shouldReportActiveIoTime()) {
                        context.reportActiveIoTime(0); // Report zero as we did no I/O.
                    }
                    return 0;

                case SelectStrategy.BUSY_WAIT:
                    // fall-through to SELECT since the busy-wait is not supported with kqueue

                case SelectStrategy.SELECT:
                    strategy = kqueueWait(context, WAKEN_UP_UPDATER.getAndSet(this, 0) == 1);

                    // 'wakenUp.compareAndSet(false, true)' is always evaluated
                    // before calling 'selector.wakeup()' to reduce the wake-up
                    // overhead. (Selector.wakeup() is an expensive operation.)
                    //
                    // However, there is a race condition in this approach.
                    // The race condition is triggered when 'wakenUp' is set to
                    // true too early.
                    //
                    // 'wakenUp' is set to true too early if:
                    // 1) Selector is waken up between 'wakenUp.set(false)' and
                    //    'selector.select(...)'. (BAD)
                    // 2) Selector is waken up between 'selector.select(...)' and
                    //    'if (wakenUp.get()) { ... }'. (OK)
                    //
                    // In the first case, 'wakenUp' is set to true and the
                    // following 'selector.select(...)' will wake up immediately.
                    // Until 'wakenUp' is set to false again in the next round,
                    // 'wakenUp.compareAndSet(false, true)' will fail, and therefore
                    // any attempt to wake up the Selector will fail, too, causing
                    // the following 'selector.select(...)' call to block
                    // unnecessarily.
                    //
                    // To fix this problem, we wake up the selector again if wakenUp
                    // is true immediately after selector.select(...).
                    // It is inefficient in that it wakes up the selector for both
                    // the first case (BAD - wake-up required) and the second case
                    // (OK - no wake-up required).

                    if (wakenUp == 1) {
                        wakeup0();
                    }
                    // fall-through
                default:
            }

            if (strategy > 0) {
                if (context.shouldReportActiveIoTime()) {
                    long activeIoStartTimeNanos = System.nanoTime();
                    handled = processReady(strategy);
                    long activeIoEndTimeNanos = System.nanoTime();
                    context.reportActiveIoTime(activeIoEndTimeNanos - activeIoStartTimeNanos);
                } else {
                    handled = processReady(strategy);
                }
            } else if (context.shouldReportActiveIoTime()) {
                context.reportActiveIoTime(0);
            }

            if (allowGrowing && strategy == eventList.capacity()) {
                //increase the size of the array as we needed the whole space for the events
                eventList.realloc(false);
            }
        } catch (Error e) {
            throw e;
        } catch (Throwable t) {
            handleLoopException(t);
        } finally {
            processCancelledRegistrations();
        }
        return handled;
    }

public static void repairItemParticles(Level level, SpiritLike activeSpiritType, Vec3 itemPos, MalumNetworkedParticleEffectColorData colorData) {
        long gameTime = level.getGameTime();
        var random = level.random;
        for (int i = 0; i < 2; i++) {
            SpiritLightSpecs.coolLookingShinyThing(level, itemPos, activeSpiritType);
        }
        for (int i = 0; i < 24; i++) {
            int lifeDelay = i / 8;
            SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
            float xVelocity = Easing.CUBIC_OUT.asWeighedRandom(random, -0.075f, 0.075f);
            float yVelocity = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.2f, 0.5f);
            float zVelocity = Easing.CUBIC_OUT.asWeighedRandom(random, -0.075f, 0.075f);
            float gravityStrength = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.75f, 1f);
            if (random.nextFloat() < 0.85f) {
                var sparkParticles = SparkParticleEffects.spiritMotionSparks(level, itemPos, cyclingSpiritType);
                sparkParticles.getBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(2)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyScaleData(d -> d.multiplyValue(2f));
                sparkParticles.getBloomBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(2)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyTransparencyData(d -> d.multiplyValue(1.25f));
                sparkParticles.spawnParticles();
            }
            if (random.nextFloat() < 0.85f) {
                xVelocity *= 1.25f;
                yVelocity *= 0.75f;
                zVelocity *= 1.25f;
                var lightSpecs = SpiritLightSpecs.spiritLightSpecs(level, itemPos, cyclingSpiritType);
                lightSpecs.getBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(4)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyScaleData(d -> d.multiplyValue(2.5f));
                lightSpecs.getBloomBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(4)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyTransparencyData(d -> d.multiplyValue(1.25f));
                lightSpecs.spawnParticles();
            }
        }
        for (int i = 0; i < 8; i++) {
            int finalI = i;
            Vec3 offsetPosition = VecHelper.rotatingRadialOffset(itemPos, 0.6f, i, 8, gameTime, 160);
            Consumer<WorldParticleBuilder> behavior = b -> b.addTickActor(p -> {
                if (level.getGameTime() > gameTime + finalI * 4 && level.getGameTime() < gameTime + (finalI + 4) * 4) {
                    p.setParticleSpeed(p.getParticleSpeed().add(0, 0.015f, 0));
                }
            });

            var lightSpecs = spiritLightSpecs(level, offsetPosition, activeSpiritType);
            lightSpecs.getBuilder()
                    .act(behavior)
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(2f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .multiplyLifetime(1.5f)
                    .setLifetimeModifier(l -> l + finalI * 2);
            lightSpecs.getBloomBuilder()
                    .act(behavior)
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(2f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .multiplyLifetime(1.5f)
                    .setLifetimeModifier(l -> (int)(l + finalI * 2.5f));
            lightSpecs.spawnParticles();
        }
    }

