private Command.Parameterized registerTicketCommand() {
        final Parameter.Value<ServerLocation> serverLocationParameter = Parameter.location().key("position").build();
        final Parameter.Value<Integer> timeParameter = Parameter.integerNumber().key("time").optional().build();

        return Command.builder()
                .addParameter(serverLocationParameter)
                .addParameter(timeParameter)
                .executor(context -> {
                    final ServerLocation location = context.requireOne(serverLocationParameter);
                    final Optional<Integer> time = context.one(timeParameter);

                    final TicketType<Vector3i> ticketType = TicketType.<Vector3i>builder()
                            .name("chunkManagerTest")
                            .comparator(Vector3i::compareTo)
                            .lifetime(time.map(Ticks::of).orElse(Ticks.infinite()))
                            .build();

                    final ChunkManager manager = location.world().chunkManager();
                    final Optional<Ticket<Vector3i>> optionalTicket = manager
                            .requestTicket(ticketType, location.chunkPosition(), location.chunkPosition(), 5);
                    if (optionalTicket.isPresent()) {
                        final Ticket<Vector3i> ticket = optionalTicket.get();
                        final Set<Ticket<Vector3i>> tickets = this.ticketsMap.computeIfAbsent(location.chunkPosition(), k -> new HashSet<>());
                        tickets.add(ticket);
                        context.sendMessage(Identity.nil(), LinearComponents.linear(
                                Component.text("Ticket registered. Lifetime - "),
                                Component.text(manager.timeLeft(ticket).ticks())));

                        context.sendMessage(Identity.nil(), LinearComponents.linear(
                                Component.text("Ticket validity check: "),
                                Component.text(manager.valid(ticket))
                        ));

                        // now find the ticket
                        if (manager.findTickets(ticketType).contains(ticket)) {
                            context.sendMessage(Identity.nil(),
                                    Component.text().content("Ticket was found in the chunk manager").color(NamedTextColor.GREEN).build());
                        } else {
                            context.sendMessage(Identity.nil(),
                                    Component.text().content("Ticket was not found in the chunk manager").color(NamedTextColor.RED).build());
                        }

                        time.ifPresentOrElse(t -> {
                            Sponge.server().scheduler().submit(Task.builder()
                                    .plugin(this.pluginContainer)
                                    .delay(Ticks.of(t + 1))
                                    .execute(() -> context.sendMessage(Identity.nil(), LinearComponents.linear(
                                            Component.text("Ticket validity check (1 tick before expiration): "),
                                            Component.text(manager.valid(ticket))
                                    ))).build());

                            Sponge.server().scheduler().submit(Task.builder()
                                    .plugin(this.pluginContainer)
                                    .delay(Ticks.of(t + 2))
                                    .execute(() -> {
                                        tickets.remove(ticket);
                                        if (tickets.isEmpty()) {
                                            this.ticketsMap.remove(location.chunkPosition(), tickets);
                                        }
                                        context.sendMessage(Identity.nil(), LinearComponents.linear(
                                            Component.text("Ticket validity check (After expiration): "),
                                            Component.text(manager.valid(ticket))));
                                    }).build());
                        }, () -> Sponge.server().scheduler().submit(Task.builder()
                                .plugin(this.pluginContainer)
                                .interval(Ticks.of(20))
                                .execute(t -> {
                                    context.sendMessage(Identity.nil(), LinearComponents.linear(
                                        Component.text("Ticket validity check (Repeating 20 ticks): "),
                                        Component.text(manager.valid(ticket))));
                                    if (!manager.valid(ticket)) {
                                        t.cancel();
                                    }
                                }).build()));
                    } else {
                        context.sendMessage(Identity.nil(), Component.text("Ticket was not registered."));
                    }
                    return CommandResult.success();
                })
                .build();
    }

public static void main(String[] args) throws Exception {
        // We assume there's a private key.
        PrivateKey privateKey = null;

        // Step 1: Load the certificate chain for netty.io. We'll need the certificate
        // and the issuer's certificate and we don't need any of the intermediate certs.
        // The array is assumed to be a certain order to keep things simple.
        X509Certificate[] keyCertChain = parseCertificates(OcspServerExample.class, "netty_io_chain.pem");

        X509Certificate certificate = keyCertChain[0];
        X509Certificate issuer = keyCertChain[keyCertChain.length - 1];

        // Step 2: We need the URL of the CA's OCSP responder server. It's somewhere encoded
        // into the certificate! Notice that it's an HTTP URL.
        URI uri = OcspUtils.ocspUri(certificate);
        System.out.println("OCSP Responder URI: " + uri);

        if (uri == null) {
            throw new IllegalStateException("The CA/certificate doesn't have an OCSP responder");
        }

        // Step 3: Construct the OCSP request
        OCSPReq request = new OcspRequestBuilder()
                .certificate(certificate)
                .issuer(issuer)
                .build();

        // Step 4: Do the request to the CA's OCSP responder
        OCSPResp response = OcspUtils.request(uri, request, 5L, TimeUnit.SECONDS);
        if (response.getStatus() != OCSPResponseStatus.SUCCESSFUL) {
            throw new IllegalStateException("response-status=" + response.getStatus());
        }

        // Step 5: Is my certificate any good or has the CA revoked it?
        BasicOCSPResp basicResponse = (BasicOCSPResp) response.getResponseObject();
        SingleResp first = basicResponse.getResponses()[0];

        CertificateStatus status = first.getCertStatus();
        System.out.println("Status: " + (status == CertificateStatus.GOOD ? "Good" : status));
        System.out.println("This Update: " + first.getThisUpdate());
        System.out.println("Next Update: " + first.getNextUpdate());

        if (status != null) {
            throw new IllegalStateException("certificate-status=" + status);
        }

        BigInteger certSerial = certificate.getSerialNumber();
        BigInteger ocspSerial = first.getCertID().getSerialNumber();
        if (!certSerial.equals(ocspSerial)) {
            throw new IllegalStateException("Bad Serials=" + certSerial + " vs. " + ocspSerial);
        }

        // Step 6: Cache the OCSP response and use it as long as it's not
        // expired. The exact semantics are beyond the scope of this example.

        if (!OpenSsl.isAvailable()) {
            throw new IllegalStateException("OpenSSL is not available!");
        }

        if (!OpenSsl.isOcspSupported()) {
            throw new IllegalStateException("OCSP is not supported!");
        }

        if (privateKey == null) {
            throw new IllegalStateException("Because we don't have a PrivateKey we can't continue past this point.");
        }

        ReferenceCountedOpenSslContext context
            = (ReferenceCountedOpenSslContext) SslContextBuilder.forServer(privateKey, keyCertChain)
                .sslProvider(SslProvider.OPENSSL)
                .enableOcsp(true)
                .build();

        try {
            ServerBootstrap bootstrap = new ServerBootstrap()
                    .childHandler(newServerHandler(context, response));

            // so on and so forth...
        } finally {
            context.release();
        }
    }

private boolean wrapNonAppData(final ChannelHandlerContext ctx, boolean inUnwrap) throws SSLException {
        ByteBuf out = null;
        ByteBufAllocator alloc = ctx.alloc();
        try {
            // Only continue to loop if the handler was not removed in the meantime.
            // See https://github.com/netty/netty/issues/5860
            outer: while (!ctx.isRemoved()) {
                if (out == null) {
                    // As this is called for the handshake we have no real idea how big the buffer needs to be.
                    // That said 2048 should give us enough room to include everything like ALPN / NPN data.
                    // If this is not enough we will increase the buffer in wrap(...).
                    out = allocateOutNetBuf(ctx, 2048, 1);
                }
                SSLEngineResult result = wrap(alloc, engine, Unpooled.EMPTY_BUFFER, out);
                if (result.bytesProduced() > 0) {
                    ctx.write(out).addListener(future -> {
                        Throwable cause = future.cause();
                        if (cause != null) {
                            setHandshakeFailureTransportFailure(ctx, cause);
                        }
                    });
                    if (inUnwrap) {
                        setState(STATE_NEEDS_FLUSH);
                    }
                    out = null;
                }

                HandshakeStatus status = result.getHandshakeStatus();
                switch (status) {
                    case FINISHED:
                        // We may be here because we read data and discovered the remote peer initiated a renegotiation
                        // and this write is to complete the new handshake. The user may have previously done a
                        // writeAndFlush which wasn't able to wrap data due to needing the pending handshake, so we
                        // attempt to wrap application data here if any is pending.
                        if (setHandshakeSuccess() && inUnwrap && !pendingUnencryptedWrites.isEmpty()) {
                            wrap(ctx, true);
                        }
                        return false;
                    case NEED_TASK:
                        if (!runDelegatedTasks(inUnwrap)) {
                            // We scheduled a task on the delegatingTaskExecutor, so stop processing as we will
                            // resume once the task completes.
                            break outer;
                        }
                        break;
                    case NEED_UNWRAP:
                        if (inUnwrap || unwrapNonAppData(ctx) <= 0) {
                            // If we asked for a wrap, the engine requested an unwrap, and we are in unwrap there is
                            // no use in trying to call wrap again because we have already attempted (or will after we
                            // return) to feed more data to the engine.
                            return false;
                        }
                        break;
                    case NEED_WRAP:
                        break;
                    case NOT_HANDSHAKING:
                        if (setHandshakeSuccess() && inUnwrap && !pendingUnencryptedWrites.isEmpty()) {
                            wrap(ctx, true);
                        }
                        // Workaround for TLS False Start problem reported at:
                        // https://github.com/netty/netty/issues/1108#issuecomment-14266970
                        if (!inUnwrap) {
                            unwrapNonAppData(ctx);
                        }
                        return true;
                    default:
                        throw new IllegalStateException("Unknown handshake status: " + result.getHandshakeStatus());
                }

                // Check if did not produce any bytes and if so break out of the loop, but only if we did not process
                // a task as last action. It's fine to not produce any data as part of executing a task.
                if (result.bytesProduced() == 0 && status != HandshakeStatus.NEED_TASK) {
                    break;
                }
            }
        }  finally {
            if (out != null) {
                out.release();
            }
        }
        return false;
    }

@Override
    protected void doClose() throws Exception {
        if (state == ChannelState.CLOSED) {
            return;
        }
        state = ChannelState.CLOSED;

        QuicheQuicConnection conn = this.connection;
        if (conn == null || conn.isFreed()) {
            if (closeData != null) {
                closeData.reason.release();
                closeData = null;
            }
            failPendingConnectPromise();
            return;
        }

        // Call connectionSend() so we ensure we send all that is queued before we close the channel
        SendResult sendResult = connectionSend(conn);

        final boolean app;
        final int err;
        final ByteBuf reason;
        if (closeData == null) {
            app = false;
            err = 0;
            reason = Unpooled.EMPTY_BUFFER;
        } else {
            app = closeData.applicationClose;
            err = closeData.err;
            reason = closeData.reason;
            closeData = null;
        }

        failPendingConnectPromise();
        try {
            int res = Quiche.quiche_conn_close(conn.address(), app, err,
                    Quiche.readerMemoryAddress(reason), reason.readableBytes());
            if (res < 0 && res != Quiche.QUICHE_ERR_DONE) {
                throw Quiche.convertToException(res);
            }
            // As we called quiche_conn_close(...) we need to ensure we will call quiche_conn_send(...) either
            // now or we will do so once we see the channelReadComplete event.
            //
            // See https://docs.rs/quiche/0.6.0/quiche/struct.Connection.html#method.close
            if (connectionSend(conn) == SendResult.SOME) {
                sendResult = SendResult.SOME;
            }
        } finally {

            // making sure that connection statistics is available
            // even after channel is closed
            statsAtClose = collectStats0(conn, eventLoop().newPromise());
            try {
                timedOut = Quiche.quiche_conn_is_timed_out(conn.address());

                closeStreams();
                if (finBuffer != null) {
                    finBuffer.release();
                    finBuffer = null;
                }
                if (outErrorCodeBuffer != null) {
                    outErrorCodeBuffer.release();
                    outErrorCodeBuffer = null;
                }
            } finally {
                if (sendResult == SendResult.SOME) {
                    // As this is the close let us flush it asap.
                    forceFlushParent();
                } else {
                    flushParent();
                }
                conn.free();
                if (freeTask != null) {
                    freeTask.accept(this);
                }
                timeoutHandler.cancel();

                local = null;
                remote = null;
            }
        }
    }

public static void wyrdReconstructionRevive(Level level, Entity entity, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData) {
        double posX = positionData.getPosX();
        double posY = positionData.getPosY();
        double posZ = positionData.getPosZ();
        Vec3 pos = new Vec3(posX, posY, posZ);
        final Color smokeColor = new Color(45, 15, 15);

        for (int i = 0; i < 12; i++) {
            Color primaryColor = colorData.getColor().getStartingColor();
            int lifetime = Easing.SINE_IN_OUT.asWeighedRandom(random, 20, 40);
            final boolean isAdditive = i % 2 == 0;
            final float scale = (2f + i * 0.5f) * (isAdditive ? 1 : 2);
            final LodestoneWorldParticleRenderType renderType = (isAdditive ? LodestoneWorldParticleRenderType.ADDITIVE : LodestoneWorldParticleRenderType.LUMITRANSPARENT).withDepthFade();
            final float spin = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.04f, 0.08f);
            float randomOffset = i * 0.2f;
            for (int j = 0; j < 2; j++) {
                var options = new WorldParticleOptions(MalumParticles.GIANT_GLOWING_STAR);
                if (j == 1) {
                    options.setBehavior(DirectionalParticleBehavior.directional());
                }
                WorldParticleBuilder.create(options)
                        .setTransparencyData(GenericParticleData.create(0.1f, 0.4f, 0).build())
                        .setColorData(ColorParticleData.create(primaryColor, smokeColor).setCoefficient(4f).build())
                        .setScaleData(GenericParticleData.create(scale / 2f, scale, 0.5f).setCoefficient(1.25f).setEasing(Easing.EXPO_OUT, Easing.EXPO_IN).build())
                        .setSpinData(SpinParticleData.createRandomDirection(random, spin).build())
                        .setRenderType(renderType)
                        .setRandomOffset(randomOffset, 0)
                        .setMotion(0, 0.001f, 0)
                        .setLifetime(lifetime)
                        .enableNoClip()
                        .repeat(level, posX, posY - 0.3f, posZ, 2);
            }
        }

        int sparkCount = 64;
        float distance = 0.7f;
        long gameTime = level.getGameTime();
        Consumer<LodestoneWorldParticle> behavior = p -> {
            Vec3 offset = entity.position().add(0, entity.getBbHeight() / 2f, 0).subtract(p.getParticlePosition());
            float length = (float) offset.length();
            if (length == 0) {
                offset = new Vec3(0, 0.02f, 0);
            }
            float delta = Math.max(p.getAge() / (float) p.getLifetime(), 0) * 2;
            float lerp = Easing.QUINTIC_IN.lerp(delta, 0, 0.3f);
            float velocity = Easing.CIRC_IN.lerp(delta, 0f, 0.3f + length * 0.6f);
            final Vec3 speed = p.getParticleSpeed().lerp(offset.normalize().scale(velocity), lerp);
            p.setParticleSpeed(speed);
        };
        for (int i = 0; i < sparkCount; i++) {
            ColorParticleData color = colorData.getColor();
            Color primaryColor = color.getStartingColor();
            Color secondaryColor = color.getEndingColor();
            Vec3 offsetPosition = VecHelper.rotatingRadialOffset(pos, distance, i, sparkCount, gameTime, 320);
            final float motionFactor = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.06f, 0.12f);
            int lifetime = Easing.SINE_IN_OUT.asWeighedRandom(random, 20, 40);
            Vec3 motion = offsetPosition.subtract(pos).normalize().scale(motionFactor);
            distance += 0.03f;
            gameTime += 10;
            for (int j = 0; j < 12; j++) {
                boolean isAdditive = j % 2 == 0;
                Color start = isAdditive ? primaryColor : secondaryColor;
                Color end = isAdditive ? secondaryColor : smokeColor;
                float lengthMultiplier = (isAdditive ? 0.5f : 1f) * Easing.SINE_IN_OUT.asWeighedRandom(random, 0.4f, 1.8f);
                float scaleMultiplier = (isAdditive ? 1.75f : 5.5f) * Easing.SINE_IN_OUT.asWeighedRandom(random, 0.4f, 1.8f);
                float alphaMultiplier = isAdditive ? 1.5f : 3f;
                float colorCoefficient = isAdditive ? 1f : 1.75f;
                var renderType = isAdditive ? LodestoneWorldParticleRenderType.ADDITIVE : LodestoneWorldParticleRenderType.LUMITRANSPARENT;
                var renderTarget = isAdditive ? LodestoneRenderingSystem.LATE_DEFERRED_RENDER : LodestoneRenderingSystem.DEFERRED_RENDER;
                WorldParticleBuilder.create(new WorldParticleOptions(MalumParticles.GIANT_GLOWING_STAR))
                        .setBehavior(SparkParticleBehavior.sparkBehavior().setForcedDirection(new Vec3(0, 1, 0)))
                        .setLengthData(GenericParticleData.create(0.1f, 0.6f, 0.3f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).setCoefficient(1.25f).build().multiplyValue(lengthMultiplier))
                        .setScaleData(GenericParticleData.create(0.025f, 0.25f, 0.6f).build().multiplyValue(scaleMultiplier))
                        .setTransparencyData(GenericParticleData.create(0.8f, 0f).build().multiplyValue(alphaMultiplier))
                        .setColorData(ColorParticleData.create(start, end).setCoefficient(colorCoefficient).build())
                        .setRenderTarget(renderTarget)
                        .setRenderType(renderType)
                        .setLifeDelay(j + i / 2)
                        .addTickActor(behavior)
                        .setLifetime(lifetime)
                        .enableNoClip()
                        .setMotion(motion)
                        .spawn(level, offsetPosition.x, offsetPosition.y, offsetPosition.z);
            }
        }
    }

