        final BlockingQueue<LocalChannel> accepted = new LinkedBlockingQueue<>();

        ServerBootstrap sb = new ServerBootstrap()
                .group(group1, group2)
                .channel(LocalServerChannel.class)
                .childHandler(new ChannelInitializer<LocalChannel>() {
                    @Override
                    protected void initChannel(LocalChannel ch) {
                        accepted.add(ch);
                    }
                });
        Bootstrap cb = new Bootstrap()
                .group(group1)
                .channel(LocalChannel.class)
                .handler(new ChannelInitializer<LocalChannel>() {
                    @Override
                    protected void initChannel(LocalChannel ch) {
                        ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                            @Override
                            public void channelRead(ChannelHandlerContext ctx, Object msg) {
                                ReferenceCountUtil.release(msg);
                                dataReceived.countDown();
                            }

                            @Override
                            public void channelInactive(ChannelHandlerContext ctx) {
                                receivedBeforeInactive.set(dataReceived.getCount() == 0);
                                clientInactive.countDown();
                            }
                        });
                    }
                });

        Channel sc = null;
        Channel cc = null;
        try {
            sc = sb.bind(TEST_ADDRESS).sync().channel();
            cc = cb.connect(TEST_ADDRESS).sync().channel();
            final LocalChannel child = accepted.poll(5, SECONDS);
            assertNotNull(child);
            while (!child.isActive()) {
                Thread.sleep(10);
            }

            // Block the client inside doWrite(...) (the promise listener is run while writeInProgress is true) so
            // that the peer sees the client as writing.
            cc.writeAndFlush(Unpooled.wrappedBuffer(new byte[] { 'X' })).addListener(new ChannelFutureListener() {
                @Override
                public void operationComplete(ChannelFuture future) throws Exception {
                    writeListenerEntered.countDown();
                    try {
                        releaseWriteListener.await();
                    } catch (InterruptedException ignore) {
                        Thread.currentThread().interrupt();
                    }
                }
            });
            assertTrue(writeListenerEntered.await(5, SECONDS));

            // Write and close from the peer while the client is still writing, then unblock the client.
            child.eventLoop().submit(new Runnable() {
                @Override
                public void run() {
                    child.writeAndFlush(Unpooled.wrappedBuffer(new byte[] { 'P' }));
                    child.close();
                }
            }).sync();
            releaseWriteListener.countDown();

            assertTrue(clientInactive.await(5, SECONDS));
            assertEquals(Boolean.TRUE, receivedBeforeInactive.get(),
                    "Data written by the peer before it closed must not be dropped");
        } finally {
            releaseWriteListener.countDown();
            closeChannel(cc);
            closeChannel(sc);
        }
    }

@Override
    public Registry.PendingTags<T> prepareTagReload(TagLoader.LoadResult<T> data) {
        if (!this.frozen)
            throw new IllegalStateException("Invalid method used for tag loading");

        var _old = ImmutableMap.<TagKey<T>, HolderSet.Named<T>>builder();
        var _new = ImmutableMap.<TagKey<T>, List<Holder<T>>>builder();

        for (var entry : data.tags().entrySet()) {
            var key = entry.getKey();
            var existing = this.tags.get(key);
            if (existing == null)
                existing = this.createTag(key);
            _old.put(key, existing);
            _new.put(key, List.copyOf(entry.getValue()));
        }

        for (var entry : this.optionalTags.entries()) {
            var key = entry.getKey();
            if (data.tags().containsKey(key))
                continue;

            var value = entry.getValue().get();
            var holder = this.getHolder(value).orElse(null);
            if (holder == null)
                continue;

            var existing = this.tags.get(key);
            if (existing == null)
                existing = this.createTag(key);
            _old.put(key, existing);
            _new.put(key, List.of(holder));
        }

        var oldBindings = _old.build();
        var newBindings = _new.build();

        var oldSnapshot = new HolderLookup.RegistryLookup.Delegate<T>() {
            @Override
            public HolderLookup.RegistryLookup<T> parent() {
                return NamespacedWrapper.this;
            }

            @Override
            public Optional<HolderSet.Named<T>> get(TagKey<T> p_259486_) {
                return Optional.ofNullable(oldBindings.get(p_259486_));
            }

            @Override
            public Stream<HolderSet.Named<T>> listTags() {
                return oldBindings.values().stream();
            }
        };

        return new Registry.PendingTags<T>() {
            @Override
            public ResourceKey<? extends Registry<? extends T>> key() {
                return NamespacedWrapper.this.key();
            }

            @Override
            public int size() {
                return newBindings.size();
            }

            @Override
            public HolderLookup.RegistryLookup<T> lookup() {
                return oldSnapshot;
            }

            @Override
            public List<Holder<T>> getPending(TagKey<T> key) {
                return newBindings.getOrDefault(key, List.of());
            }

            @Override
            public void apply() {
                for (var entry : oldBindings.entrySet()) {
                    var newList = newBindings.getOrDefault(entry.getKey(), List.of());
                    entry.getValue().bind(newList);
                }

                NamespacedWrapper.this.frozenTags = MappedRegistry.TagSet.fromMap(oldBindings);
                NamespacedWrapper.this.delegate.onBindTags(NamespacedWrapper.this.tags);
                NamespacedWrapper.this.refreshTagsInHoldersForge();
            }
        };
    }

@TestHolder(description = "Renders debug info for a new block entity using debug renderers and subscribers", enabledByDefault = true)
    static void testDebugSubscriptions(DynamicTest test, RegistrationHelper reg) {
        var id = "debug_subscription";
        var registryName = Identifier.fromNamespaceAndPath(reg.modId(), id);
        var blockEntityType = DeferredHolder.create(Registries.BLOCK_ENTITY_TYPE, registryName);

        // register our custom debug subscription
        var debugSubscription = reg.registrar(Registries.DEBUG_SUBSCRIPTION).register(id, () -> new DebugSubscription<>(ByteBufCodecs.VAR_INT, 200));

        final class DebugBlockEntity extends BlockEntity {
            private int counter = 0;

            private DebugBlockEntity(BlockPos pos, BlockState blockState) {
                super(blockEntityType.value(), pos, blockState);
            }

            public void incrementCounter() {
                counter++;
                setChanged();
            }

            @Override
            protected void saveAdditional(ValueOutput output) {
                super.saveAdditional(output);
                output.putInt("counter", counter);
            }

            @Override
            protected void loadAdditional(ValueInput input) {
                super.loadAdditional(input);
                counter = input.getIntOr("counter", 0);
            }

            @Override
            public void registerDebugValues(ServerLevel level, Registration registration) {
                // mark this entity for displaying debug info for our subscription
                registration.register(debugSubscription.value(), () -> counter);
            }
        }

        // generic block for our block entity
        final class DebugBlock extends BaseEntityBlock {
            private DebugBlock(Properties properties) {
                super(properties);
            }

            @Override
            protected InteractionResult useWithoutItem(BlockState blockState, Level level, BlockPos pos, Player player, BlockHitResult hitResult) {
                if (!(level.getBlockEntity(pos) instanceof DebugBlockEntity blockEntity)) {
                    return InteractionResult.FAIL;
                }

                blockEntity.incrementCounter();
                return InteractionResult.SUCCESS;
            }

            @Override
            public BlockEntity newBlockEntity(BlockPos pos, BlockState blockState) {
                return new DebugBlockEntity(pos, blockState);
            }
        }

        var block = reg.blocks().registerBlock(id, DebugBlock::new);
        reg.items().registerSimpleBlockItem(block);
        reg.registrar(Registries.BLOCK_ENTITY_TYPE).register(id, () -> new BlockEntityType<>(DebugBlockEntity::new, block.value()));

        // debug renderer used to render counters above our block entities
        final class DebugCountRenderer implements DebugRenderer.SimpleDebugRenderer {
            private DebugCountRenderer(Minecraft client) {}

            @Override
            public void emitGizmos(double camX, double camY, double camZ, DebugValueAccess valueAccess, Frustum frustum, float partialTicks) {
                // list is populated via 'DebugBlockEntity.registerDebugValues'
                // while we are using block entities this, you can also register subscribers for entities and chunks too
                valueAccess.forEachBlock(debugSubscription.value(), (pos, count) -> {
                    Gizmos.billboardTextOverBlock(count + "", pos, 0, CommonColors.WHITE, .5F);
                });
            }
        }

        // mark our subscriber as only being active in dev
        NeoForge.EVENT_BUS.addListener(AddDebugSubscriptionFlagsEvent.class, event -> event.addActiveInDev(debugSubscription.value()));

        // register our debug renderer
        reg.eventListeners().accept((RegisterDebugRenderersEvent event) -> event.register(DebugCountRenderer::new));

        test.pass();
    }

public static void craftRuneParticles(Level level, RunicWorkbenchBlockEntity workbench, MalumNetworkedParticleEffectColorData colorData, RunicWorkbenchEffectData extraData) {
        long gameTime = level.getGameTime();
        var rand = level.random;
        Vec3 targetPos = workbench.getItemPos();
        for (int i = 0; i < 2; i++) {
            var spirit = colorData.getSpirit();
            SpiritLightSpecs.coolLookingShinyThing(level, targetPos, spirit);
        }
        for (int i = 0; i < 6; i++) {
            int lifeDelay = 2 + i;
            var scaleData = GenericParticleData.create(0.1f, Easing.SINE_IN_OUT.asWeighedRandom(rand, 0.5f, 0.6f) + i * 0.05f, 0.5f)
                    .setEasing(Easing.SINE_OUT, Easing.SINE_IN)
                    .setCoefficient(Easing.SINE_IN_OUT.asWeighedRandom(rand, 1.5f, 2f)).build();
            var builder = SpiritBasedParticleBuilder.createSpirit(MalumParticles.SQUARE.get())
                    .setSpirit(colorData.getSpirit())
                    .setBehavior(DirectionalParticleBehavior.directional(new Vec3(0, 1, 0)))
                    .setTransparencyData(GenericParticleData.create(0.7f, 0f).setEasing(Easing.SINE_IN_OUT).build())
                    .setSpritePicker(SimpleParticleOptions.ParticleSpritePicker.WITH_AGE)
                    .setScaleData(scaleData)
                    .setLifetime(15)
                    .setLifeDelay(lifeDelay)
                    .enableNoClip();
            if (i % 2 == 0) {
                builder.act(b -> b.setColorData(b.getColorData().invert().build()));
            }
            builder
                    .spawn(level, targetPos.x, targetPos.y, targetPos.z)
                    .setBehavior(BillboardParticleBehavior.INSTANCE)
                    .setLifetime(8)
                    .setLifeDelay((int) (lifeDelay * 1.5f))
                    .modifyScaleData(d -> d.multiplyValue(1.25f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyValue(0.6f))
                    .spawn(level, targetPos.x, targetPos.y, targetPos.z);
        }

        for (int i = 0; i < 4; i++) {
            int lifeDelay = 18;
            var scaleData = GenericParticleData.create(0.2f, Easing.SINE_IN_OUT.asWeighedRandom(rand, 0.3f, 0.4f) + i * 0.1f, 0.3f)
                    .setEasing(Easing.SINE_OUT, Easing.SINE_IN)
                    .setCoefficient(Easing.SINE_IN_OUT.asWeighedRandom(rand, 1.5f, 2f)).build();
            var builder = SpiritBasedParticleBuilder.createSpirit(MalumParticles.SQUARE.get())
                    .setSpirit(colorData.getSpirit())
                    .setBehavior(DirectionalParticleBehavior.directional(new Vec3(0, 1, 0)))
                    .setTransparencyData(GenericParticleData.create(0.9f, 0f).setEasing(Easing.EXPO_IN).build())
                    .setSpritePicker(SimpleParticleOptions.ParticleSpritePicker.WITH_AGE)
                    .setScaleData(scaleData)
                    .setLifetime(15)
                    .setLifeDelay(lifeDelay)
                    .enableNoClip();
            if (i % 2 == 0) {
                builder.act(b -> b.setColorData(b.getColorData().invert().build()));
            }
            builder
                    .spawn(level, targetPos.x, targetPos.y, targetPos.z)
                    .setBehavior(BillboardParticleBehavior.INSTANCE)
                    .setLifetime(10)
                    .modifyScaleData(d -> d.multiplyValue(1.25f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyValue(0.6f))
                    .spawn(level, targetPos.x, targetPos.y, targetPos.z);
        }

        for (int i = 0; i < 32; i++) {
            var spirit = colorData.getSpirit();
            Vec3 offsetPosition = VecHelper.rotatingRadialOffset(targetPos, 0.6f, i, 16, gameTime, 160);
            var lightSpecs = spiritLightSpecs(level, offsetPosition, spirit);
            int lifeDelay = i / 2;
            if (i % 2 == 0) {
                lightSpecs.getBuilder().act(b -> b.setColorData(b.getColorData().invert().build()));
                lightSpecs.getBloomBuilder().act(b -> b.setColorData(b.getColorData().invert().build()));
            }

            lightSpecs.getBuilder()
                    .setMotion(0, 0.1f, 0)
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(2f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .setLifetime(10)
                    .setLifeDelay(4+ lifeDelay);
            lightSpecs.getBloomBuilder()
                    .setMotion(0, 0.1f, 0)
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(1.6f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .setLifetime(10)
                    .setLifeDelay(4+ lifeDelay);
            lightSpecs.spawnParticles();
        }
    }

public static void lifeWeaverHealingBeam(Level level, RandomSource random, NetworkedParticleEffectPositionData positionData, MalumNetworkedParticleEffectColorData colorData, LifeweaverHealingBeamParticleEffect.LifeweaverHealingBeamEffectData extraData) {
        var target = level.getEntity(extraData.targetId());
        var source = level.getEntity(extraData.sourceId());
        if (target != null && source != null) {
            var pos = positionData.getAsVector();
            final Vec3 targetPos = target.position().add(0, target.getBbHeight() / 2f, 0);
            var direction = targetPos.subtract(pos).normalize();
            float yRot = ((float) (Mth.atan2(direction.x, direction.z) * (double) (180F / (float) Math.PI)));
            float yaw = (float) Math.toRadians(yRot);
            Vec3 left = new Vec3(-Math.cos(yaw), 0, Math.sin(yaw));
            Vec3 up = left.cross(direction);

            final Consumer<LodestoneWorldParticle> behavior = p -> {
                float partialTick = Minecraft.getInstance().getTimer().getGameTimeDeltaPartialTick(true);
                var spark = (SparkParticleBehavior) p.behavior;
                final Vec3 distance = target.getPosition(partialTick).add(0, target.getBbHeight()/2f, 0).subtract(p.getParticlePosition());
                spark.setForcedDirection(distance.normalize());
                final float length = (float) Math.clamp(distance.length(), 2, 4);
                p.lengthData.overrideValueMultiplier(length / 6f);
                p.scaleData.overrideValueMultiplier(length / 4f);
            };
            for (int i = 0; i < 4; i++) {
                SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
                float spread = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float speed = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.6f, 0.8f);
                float angle = i / 4f * (float) Math.PI * 2f;
                Vec3 particleDirection = direction
                        .add(left.scale(Math.sin(angle) * spread))
                        .add(up.scale(Math.cos(angle) * spread))
                        .normalize().scale(speed);
                Vec3 particlePosition = pos.add(particleDirection.scale(0.4f));
                final int lifeDelay = i * 2;
                SpiritBasedParticleBuilder.createSpirit(LodestoneParticleTypes.EXTRUDING_SPARK_PARTICLE)
                        .setSpirit(cyclingSpiritType)
                        .setTransparencyData(GenericParticleData.create(0f, 0.7f, 0).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setLengthData(GenericParticleData.create(0.8f, 2.6f, 0.4f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setScaleData(GenericParticleData.create(0.2f, 0.4f, 0.2f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setBehavior(SparkParticleBehavior.sparkBehavior().setForcedDirection(direction).setLengthCenter(1f))
                        .setRandomOffset(0.1f)
                        .setLifetime(15)
                        .setLifeDelay(lifeDelay)
                        .enableNoClip()
                        .addRenderActor(behavior)
                        .spawn(level, particlePosition.x, particlePosition.y, particlePosition.z);


                SpiritBasedParticleBuilder.createSpirit(MalumParticles.GIANT_GLOWING_STAR)
                        .setSpirit(cyclingSpiritType)
                        .setTransparencyData(GenericParticleData.create(0.2f, 0.3f, 0).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setScaleData(GenericParticleData.create(0.3f, 0.6f, 0.2f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setLifetime(15)
                        .setLifeDelay(lifeDelay)
                        .enableNoClip()
                        .spawn(level, particlePosition.x, particlePosition.y, particlePosition.z);
                SpiritBasedParticleBuilder.createSpirit(MalumParticles.STAR)
                        .setSpirit(cyclingSpiritType)
                        .setTransparencyData(GenericParticleData.create(0.15f, 0.5f, 0).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setScaleData(GenericParticleData.create(0.05f, 0.2f, 0.1f).setEasing(Easing.SINE_IN_OUT, Easing.SINE_IN_OUT).build())
                        .setLifetime(15)
                        .setLifeDelay(lifeDelay)
                        .enableNoClip()
                        .spawn(level, particlePosition.x, particlePosition.y, particlePosition.z);
            }

            long gameTime = level.getGameTime();
            float time = 16;
            for (int i = 0; i < 6; i++) {
                var offsetTargetPosition = VecHelper.rotatingRadialOffset(targetPos, 1.1f, i, 6, gameTime, time);
                double timeOffset = (Math.cos(((gameTime + i * 480) % time) / time) * 0.25f) - 0.25f;
                offsetTargetPosition = offsetTargetPosition.add(0, timeOffset, 0);
                 for (int j = 0; j < 2; j++) {
                    var lightSpecs = spiritLightSpecs(level, offsetTargetPosition, colorData.getColor());
                    float velocity = -Easing.SINE_IN_OUT.asWeighedRandom(random, 0.05f, 0.1f);
                    var motion = offsetTargetPosition.subtract(targetPos).normalize().scale(velocity);
                    lightSpecs.getBuilder()
                            .multiplyLifetime(0.8f)
                            .setMotion(motion)
                            .setTransparencyData(GenericParticleData.create(0.2f, 0.8f, 0f).build())
                            .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 1f, 2f)));
                    lightSpecs.getBloomBuilder()
                            .multiplyLifetime(0.6f)
                            .setMotion(motion)
                            .setTransparencyData(GenericParticleData.create(0.05f, 0.35f, 0f).build())
                            .modifyScaleData(d -> d.multiplyValue(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.5f, 1f)));
                    lightSpecs.spawnParticles();
                }
            }
        }
    }

@ParameterizedTest
    @ValueSource(booleans = {true, false})
    public void testProviderBufferRead(boolean incremental) throws InterruptedException {
        if (incremental) {
            assumeTrue(IoUring.isRegisterBufferRingIncSupported());
        }
        final BlockingQueue<ByteBuf> bufferSyncer = new LinkedBlockingQueue<>();
        IoUringIoHandlerConfig ioUringIoHandlerConfiguration = new IoUringIoHandlerConfig();
        IoUringBufferRingConfig bufferRingConfig =
                IoUringBufferRingConfig.builder()
                        .bufferGroupId((short) 1)
                        .bufferRingSize((short) 2)
                        .batchSize(2).incremental(incremental)
                        .allocator(new IoUringFixedBufferRingAllocator(1024))
                        .batchAllocation(false)
                        .build();

        IoUringBufferRingConfig bufferRingConfig1 =
                IoUringBufferRingConfig.builder()
                        .bufferGroupId((short) 2)
                        .bufferRingSize((short) 16)
                        .batchSize(8)
                        .incremental(incremental)
                        .allocator(new IoUringFixedBufferRingAllocator(1024))
                        .batchAllocation(true)
                        .build();
        ioUringIoHandlerConfiguration.setBufferRingConfig(bufferRingConfig, bufferRingConfig1);

        MultiThreadIoEventLoopGroup group = new MultiThreadIoEventLoopGroup(1,
                IoUringIoHandler.newFactory(ioUringIoHandlerConfiguration)
        );
        ServerBootstrap serverBootstrap = new ServerBootstrap();
        serverBootstrap.channel(IoUringServerSocketChannel.class);

        String randomString = UUID.randomUUID().toString();
        int randomStringLength = randomString.length();

        ArrayBlockingQueue<IoUringBufferRingExhaustedEvent> eventSyncer = new ArrayBlockingQueue<>(1);

        Channel serverChannel = serverBootstrap.group(group)
                .childHandler(new ChannelInboundHandlerAdapter() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        bufferSyncer.offer((ByteBuf) msg);
                    }

                    @Override
                    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                        if (evt instanceof IoUringBufferRingExhaustedEvent) {
                            eventSyncer.add((IoUringBufferRingExhaustedEvent) evt);
                        }
                    }
                })
                .childOption(IoUringChannelOption.IO_URING_BUFFER_GROUP_ID, bufferRingConfig.bufferGroupId())
                .bind(NetUtil.LOCALHOST, 0)
                .syncUninterruptibly().channel();

        Bootstrap clientBoostrap = new Bootstrap();
        clientBoostrap.group(group)
                .channel(IoUringSocketChannel.class)
                .handler(new ChannelInboundHandlerAdapter());
        ChannelFuture channelFuture = clientBoostrap.connect(serverChannel.localAddress()).syncUninterruptibly();
        assertTrue(channelFuture.isSuccess());
        Channel clientChannel = channelFuture.channel();

        //is provider buffer read?
        ByteBuf writeBuffer = Unpooled.directBuffer(randomStringLength);
        ByteBufUtil.writeAscii(writeBuffer, randomString);
        ByteBuf userspaceIoUringBufferElement1 = sendAndRecvMessage(clientChannel, writeBuffer, bufferSyncer);
        ByteBuf userspaceIoUringBufferElement2 = sendAndRecvMessage(clientChannel, writeBuffer, bufferSyncer);
        ByteBuf readBuffer = sendAndRecvMessage(clientChannel, writeBuffer, bufferSyncer);
        readBuffer.release();

        // Now we release the buffer and so put it back into the buffer ring.
        userspaceIoUringBufferElement1.release();
        userspaceIoUringBufferElement2.release();

        readBuffer = sendAndRecvMessage(clientChannel, writeBuffer, bufferSyncer);
        readBuffer.release();

        // The next buffer is expected to be provided out of the ring again.
        readBuffer = sendAndRecvMessage(clientChannel, writeBuffer, bufferSyncer);
        readBuffer.release();

        writeBuffer.release();

        serverChannel.close().syncUninterruptibly();
        clientChannel.close().syncUninterruptibly();
        group.shutdownGracefully();
    }

@ParameterizedTest
    @MethodSource("newSslTaskExecutors")
    @Timeout(10)
    public void testTimedOut(Executor executor) throws Throwable {
        final AtomicBoolean dropPackets = new AtomicBoolean();
        final BlockingQueue<QuicStreamChannel> acceptedStreams = new LinkedBlockingQueue<>();
        Channel server = QuicTestUtils.newServer(
                QuicTestUtils.newQuicServerBuilder(executor).maxIdleTimeout(1, TimeUnit.MILLISECONDS),
                NoQuicTokenHandler.INSTANCE,
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public boolean isSharable() {
                        return true;
                    }
                },
                new ChannelInboundHandlerAdapter() {
                    @Override
                    public boolean isSharable() {
                        return true;
                    }

                    @Override
                    public void channelActive(ChannelHandlerContext ctx) {
                        acceptedStreams.add((QuicStreamChannel) ctx.channel());
                        dropPackets.set(true);
                        ctx.fireChannelActive();
                    }

                    @Override
                    public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                        // Server closes the stream whenever the client sends a FIN.
                        if (evt instanceof ChannelInputShutdownEvent) {
                            ctx.close();
                        }
                        ctx.fireUserEventTriggered(evt);
                    }
                });

        // Have the server drop packets once we tell it to do so.
        server.pipeline().addFirst(
                new ChannelDuplexHandler() {
                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        if (dropPackets.get()) {
                            ReferenceCountUtil.release(msg);
                        } else {
                            ctx.fireChannelRead(msg);
                        }
                    }

                    @Override
                    public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                        if (dropPackets.get()) {
                            ReferenceCountUtil.release(msg);
                            promise.setSuccess();
                        } else {
                            ctx.write(msg, promise);
                        }
                    }
                });

        InetSocketAddress address = (InetSocketAddress) server.localAddress();
        Channel channel = QuicTestUtils.newClient(QuicTestUtils.newQuicClientBuilder(executor));
        ChannelActiveVerifyHandler clientQuicChannelHandler = new ChannelActiveVerifyHandler();
        try {
            QuicChannel quicChannel = QuicTestUtils.newQuicChannelBootstrap(channel)
                    .handler(clientQuicChannelHandler)
                    .remoteAddress(address)
                    .connect()
                    .get();

            QuicStreamChannel quicStream = quicChannel.createStream(QuicStreamType.BIDIRECTIONAL,
                    new ChannelInboundHandlerAdapter()).get();

            ByteBuf payload = Unpooled.wrappedBuffer("HELLO!".getBytes(StandardCharsets.US_ASCII));
            quicStream.writeAndFlush(payload).sync();
            assertTrue(quicStream.closeFuture().await().isSuccess());

            QuicStreamChannel accepted = acceptedStreams.take();
            accepted.closeFuture().sync();
            assertTrue(accepted.parent().isTimedOut());

            ChannelFuture closeFuture = channel.close().await();
            assertTrue(closeFuture.isSuccess());
        } finally {
            clientQuicChannelHandler.assertState();
            channel.close().sync();
            server.close().sync();
            shutdown(executor);
        }
    }

public static <N extends SortableNode<N>> boolean sort(List<N> sortedNodes, String elementDescription, Comparator<N> comparator) {
		// FIRST KOSARAJU SCC VISIT
		List<N> toposort = new ArrayList<>(sortedNodes.size());

		for (N node : sortedNodes) {
			forwardVisit(node, null, toposort);
		}

		clearStatus(toposort);
		Collections.reverse(toposort);

		// SECOND KOSARAJU SCC VISIT
		Map<N, NodeScc<N>> nodeToScc = new IdentityHashMap<>();

		for (N node : toposort) {
			if (!node.visited) {
				List<N> sccNodes = new ArrayList<>();
				// Collect nodes in SCC.
				backwardVisit(node, sccNodes);
				// Sort nodes by id.
				sccNodes.sort(comparator);
				// Mark nodes as belonging to this SCC.
				NodeScc<N> scc = new NodeScc<>(sccNodes);

				for (N nodeInScc : sccNodes) {
					nodeToScc.put(nodeInScc, scc);
				}
			}
		}

		clearStatus(toposort);

		// Build SCC graph
		for (NodeScc<N> scc : nodeToScc.values()) {
			for (N node : scc.nodes) {
				for (N subsequentNode : node.subsequentNodes) {
					NodeScc<N> subsequentScc = nodeToScc.get(subsequentNode);

					if (subsequentScc != scc) {
						scc.subsequentSccs.add(subsequentScc);
						subsequentScc.inDegree++;
					}
				}
			}
		}

		// Order SCCs according to priorities. When there is a choice, use the SCC with the lowest id.
		// The priority queue contains all SCCs that currently have 0 in-degree.
		PriorityQueue<NodeScc<N>> pq = new PriorityQueue<>(Comparator.comparing(scc -> scc.nodes.get(0), comparator));
		sortedNodes.clear();

		for (NodeScc<N> scc : nodeToScc.values()) {
			if (scc.inDegree == 0) {
				pq.add(scc);
				// Prevent adding the same SCC multiple times, as nodeToScc may contain the same value multiple times.
				scc.inDegree = -1;
			}
		}

		boolean noCycle = true;

		while (!pq.isEmpty()) {
			NodeScc<N> scc = pq.poll();
			sortedNodes.addAll(scc.nodes);

			if (scc.nodes.size() > 1) {
				noCycle = false;

				if (ENABLE_CYCLE_WARNING) {
					// Print cycle warning
					StringBuilder builder = new StringBuilder();
					builder.append("Found cycle while sorting ").append(elementDescription).append(":\n");

					for (N node : scc.nodes) {
						builder.append("\t").append(node.getDescription()).append("\n");
					}

					LOGGER.warn(builder.toString());
				}
			}

			for (NodeScc<N> subsequentScc : scc.subsequentSccs) {
				subsequentScc.inDegree--;

				if (subsequentScc.inDegree == 0) {
					pq.add(subsequentScc);
				}
			}
		}

		return noCycle;
	}

@Override
    public int run(IoHandlerContext context) {
        int handled = 0;
        try {
            int strategy = selectStrategy.calculateStrategy(selectNowSupplier, !context.canBlock());
            switch (strategy) {
                case SelectStrategy.CONTINUE:
                    if (context.shouldReportActiveIoTime()) {
                        context.reportActiveIoTime(0); // Report zero as we did no I/O.
                    }
                    return 0;

                case SelectStrategy.BUSY_WAIT:
                    strategy = epollBusyWait();
                    break;

                case SelectStrategy.SELECT:
                    if (pendingWakeup) {
                        // We are going to be immediately woken so no need to reset wakenUp
                        // or check for timerfd adjustment.
                        strategy = epollWaitTimeboxed();
                        if (strategy != 0) {
                            break;
                        }
                        // We timed out so assume that we missed the write event due to an
                        // abnormally failed syscall (the write itself or a prior epoll_wait)
                        logger.warn("Missed eventfd write (not seen after > 1 second)");
                        pendingWakeup = false;
                        if (!context.canBlock()) {
                            break;
                        }
                        // fall-through
                    }

                    long curDeadlineNanos = context.deadlineNanos();
                    if (curDeadlineNanos == -1L) {
                        curDeadlineNanos = NONE; // nothing on the calendar
                    }
                    nextWakeupNanos.set(curDeadlineNanos);
                    try {
                        if (context.canBlock()) {
                            if (curDeadlineNanos == prevDeadlineNanos) {
                                // No timer activity needed
                                strategy = epollWaitNoTimerChange();
                            } else {
                                // Timerfd needs to be re-armed or disarmed
                                long result = epollWait(context, curDeadlineNanos);
                                // The result contains the actual return value and if a timer was used or not.
                                // We need to "unpack" using the helper methods exposed in Native.
                                strategy = Native.epollReady(result);
                                prevDeadlineNanos = Native.epollTimerWasUsed(result) ? curDeadlineNanos : NONE;
                            }
                        }
                    } finally {
                        // Try get() first to avoid much more expensive CAS in the case we
                        // were woken via the wakeup() method (submitted task)
                        if (nextWakeupNanos.get() == AWAKE || nextWakeupNanos.getAndSet(AWAKE) == AWAKE) {
                            pendingWakeup = true;
                        }
                    }
                    // fallthrough
                default:
            }
            if (strategy > 0) {
                int packed;
                if (context.shouldReportActiveIoTime()) {
                    long activeIoStartTimeNanos = System.nanoTime();
                    packed = processReady(events, strategy);
                    long activeIoEndTimeNanos = System.nanoTime();
                    context.reportActiveIoTime(activeIoEndTimeNanos - activeIoStartTimeNanos);
                } else {
                    packed = processReady(events, strategy);
                }
                handled = packed >>> 1;
                if ((packed & 1) != 0) {
                    prevDeadlineNanos = NONE;
                }
            } else if (context.shouldReportActiveIoTime()) {
                context.reportActiveIoTime(0);
            }

            if (allowGrowing && strategy == events.length()) {
                //increase the size of the array as we needed the whole space for the events
                events.increase();
            }
        } catch (Error e) {
            throw e;
        } catch (Throwable t) {
            handleLoopException(t);
        }
        return handled;
    }

private static void computePath(Block.Getter getter, Point start, Point target,
                                    double closeDistance, double maxDistance, double pathVariance,
                                    BoundingBox boundingBox, PPath path, NodeGenerator generator) {
        double closestDistance = Double.MAX_VALUE;
        double straightDistance = generator.heuristic(start, target);
        int maxSize = (int) Math.floor(maxDistance * 10);

        closeDistance = Math.max(0.8, closeDistance);
        List<PNode> closestFoundNodes = List.of();

        PNode pStart = new PNode(start, 0, generator.heuristic(start, target), PNode.Type.WALK, null);

        ObjectHeapPriorityQueue<PNode> open = new ObjectHeapPriorityQueue<>(pNodeComparator);
        open.enqueue(pStart);

        Set<PNode> closed = new ObjectOpenHashBigSet<>(maxSize);

        while (!open.isEmpty() && closed.size() < maxSize) {
            if (path.getState() == PPath.State.TERMINATING) {
                path.setState(PPath.State.TERMINATED);
                return;
            }

            PNode current = open.dequeue();

            //var chunk = instance.getChunkAt(current.x(), current.z());
            //if (chunk == null) continue;
            //if (!chunk.isLoaded()) continue;

            if (((current.g() + current.h()) - straightDistance) > pathVariance) continue;
            if (!withinDistance(current, start, maxDistance)) continue;
            if (withinDistance(current, target, closeDistance)) {
                open.enqueue(current);
                break;
            }

            if (current.h() < closestDistance) {
                closestDistance = current.h();
                closestFoundNodes = List.of(current);
            }

            Collection<? extends PNode> found = generator.getWalkable(getter, closed, current, target, boundingBox);
            found.forEach(p -> {
                if (getDistanceSquared(p.x(), p.y(), p.z(), start) <= (maxDistance * maxDistance)) {
                    open.enqueue(p);
                    closed.add(p);
                }
            });
        }

        PNode current = open.isEmpty() ? null : open.dequeue();

        if (current == null || !withinDistance(current, target, closeDistance)) {
            if (closestFoundNodes.isEmpty()) {
                path.setState(PPath.State.INVALID);
                return;
            }

            current = closestFoundNodes.getFirst();

            if (!open.isEmpty()) {
                current = buildRepathNode(current);
            }
        }

        while (current.parent() != null) {
            path.getNodes().add(current);
            current = current.parent();
        }

        Collections.reverse(path.getNodes());

        if (path.getCurrentType() == PNode.Type.REPATH) {
            path.setState(PPath.State.INVALID);
            path.getNodes().clear();
            return;
        }

        if (path.getNodes().isEmpty()) {
            path.setState(PPath.State.INVALID);
            return;
        }

        var lastNode = path.getNodes().getLast();
        if (getDistanceSquared(lastNode.x(), lastNode.y(), lastNode.z(), target) > (closeDistance * closeDistance)) {
            path.setState(PPath.State.BEST_EFFORT);
            return;
        }

        PNode pEnd = new PNode(target, 0, 0, PNode.Type.WALK, null);
        path.getNodes().add(pEnd);
        path.setState(PPath.State.COMPUTED);
    }

@Override
  public boolean handle(PluginMessagePacket packet) {
    // Handling edge case when packet with FML client handshake (state COMPLETE)
    // arrives after JoinGame packet from destination server
    VelocityServerConnection serverConn =
        (player.getConnectedServer() == null
            && packet.getChannel().equals(
            LegacyForgeConstants.FORGE_LEGACY_HANDSHAKE_CHANNEL))
            ? player.getConnectionInFlight() : player.getConnectedServer();

    MinecraftConnection backendConn = serverConn != null ? serverConn.getConnection() : null;
    if (serverConn != null && backendConn != null) {
      if (backendConn.getState() != StateRegistry.PLAY) {
        logger.warn("A plugin message was received while the backend server was not "
            + "ready. Channel: {}. Packet discarded.", packet.getChannel());
      } else if (PluginMessageUtil.isRegister(packet)) {
        List<ChannelIdentifier> channels =
            PluginMessageUtil.getChannels(this.player.getClientsideChannels().size(), packet,
                this.player.getProtocolVersion());
        player.getClientsideChannels().addAll(channels);
        server.getEventManager()
            .fireAndForget(
                new PlayerChannelRegisterEvent(player, ImmutableList.copyOf(channels)));
        backendConn.write(packet.retain());
      } else if (PluginMessageUtil.isUnregister(packet)) {
        List<ChannelIdentifier> channels =
            PluginMessageUtil.getChannels(0, packet, this.player.getProtocolVersion());
        player.getClientsideChannels().removeAll(channels);
        server.getEventManager()
            .fireAndForget(
                new PlayerChannelUnregisterEvent(player, ImmutableList.copyOf(channels)));
        backendConn.write(packet.retain());
      } else if (PluginMessageUtil.isMcBrand(packet)) {
        String brand = PluginMessageUtil.readBrandMessage(packet.content());
        server.getEventManager().fireAndForget(new PlayerClientBrandEvent(player, brand));
        player.setClientBrand(brand);
        backendConn.write(packet.retain());
      } else if (BungeeCordMessageResponder.isBungeeCordMessage(packet)) {
        return true;
      } else {
        if (serverConn.getPhase() == BackendConnectionPhases.IN_TRANSITION) {
          // We must bypass the currently-connected server when forwarding Forge packets.
          VelocityServerConnection inFlight = player.getConnectionInFlight();
          if (inFlight != null) {
            player.getPhase().handle(player, packet, inFlight);
          }
          return true;
        }

        if (!player.getPhase().handle(player, packet, serverConn)) {
          ChannelIdentifier id = server.getChannelRegistrar().getFromId(packet.getChannel());
          if (id == null) {
            // We don't have any plugins listening on this channel, process the packet now.
            if (!player.getPhase().consideredComplete() || !serverConn.getPhase()
                .consideredComplete()) {
              // The client is trying to send messages too early. This is primarily caused by mods,
              // but further aggravated by Velocity. To work around these issues, we will queue any
              // non-FML handshake messages to be sent once the FML handshake has completed or the
              // JoinGame packet has been received by the proxy, whichever comes first.
              //
              // We also need to make sure to retain these packets, so they can be flushed
              // appropriately.
              enqueueLoginPluginMessage(packet.retain());
            } else {
              // The connection is ready, send the packet now.
              backendConn.write(packet.retain());
            }
          } else {
            byte[] copy = ByteBufUtil.getBytes(packet.content());
            PluginMessageEvent event = new PluginMessageEvent(player, serverConn, id, copy);
            server.getEventManager().fire(event).thenAcceptAsync(pme -> {
              if (pme.getResult().isAllowed()) {
                PluginMessagePacket message = new PluginMessagePacket(packet.getChannel(),
                    Unpooled.wrappedBuffer(copy));
                if (!player.getPhase().consideredComplete() || !serverConn.getPhase()
                    .consideredComplete()) {
                  // We're still processing the connection (see above), enqueue the packet for now.
                  enqueueLoginPluginMessage(message.retain());
                } else {
                  backendConn.write(message);
                }
              }
            }, backendConn.eventLoop()).exceptionally((ex) -> {
              logger.error("Exception while handling plugin message packet for {}", player, ex);
              return null;
            });
          }
        }
      }
    }

    return true;
  }

@Test
    public void testInterleavedRequestResponseAcrossOverflow() {
        // Test interleaved enqueue/dequeue that crosses the inline-to-overflow boundary.
        // Send some requests, process some responses, then send more requests to trigger overflow.
        EmbeddedChannel ch = new EmbeddedChannel(new HttpServerCodec());

        // Send 30 GET requests (not yet filling the 32-slot inline queue).
        StringBuilder requests = new StringBuilder();
        for (int i = 0; i < 30; i++) {
            requests.append("GET /").append(i).append(" HTTP/1.1\r\nHost: a\r\n\r\n");
        }
        assertTrue(ch.writeInbound(Unpooled.copiedBuffer(requests.toString(), CharsetUtil.UTF_8)));

        // Drain inbound.
        for (;;) {
            Object msg = ch.readInbound();
            if (msg == null) {
                break;
            }
            if (msg instanceof HttpContent) {
                ((HttpContent) msg).release();
            }
        }

        // Respond to 10 of them (draining 10 from the queue, leaving 20).
        for (int i = 0; i < 10; i++) {
            FullHttpResponse resp = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
                    Unpooled.copiedBuffer("ok", CharsetUtil.UTF_8));
            resp.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 2);
            assertTrue(ch.writeOutbound(resp));
            ByteBuf buf = ch.readOutbound();
            buf.release();
        }

        // Now send 15 more requests (20 remaining + 15 = 35 total, exceeding inline capacity of 32).
        // Put a HEAD request as the last one to verify overflow ordering.
        requests = new StringBuilder();
        for (int i = 30; i < 44; i++) {
            requests.append("GET /").append(i).append(" HTTP/1.1\r\nHost: a\r\n\r\n");
        }
        requests.append("HEAD /44 HTTP/1.1\r\nHost: a\r\n\r\n");
        assertTrue(ch.writeInbound(Unpooled.copiedBuffer(requests.toString(), CharsetUtil.UTF_8)));

        // Drain inbound.
        for (;;) {
            Object msg = ch.readInbound();
            if (msg == null) {
                break;
            }
            if (msg instanceof HttpContent) {
                ((HttpContent) msg).release();
            }
        }

        // Respond to remaining 20 GET requests (inline queue).
        for (int i = 10; i < 30; i++) {
            FullHttpResponse resp = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
                    Unpooled.copiedBuffer("ok", CharsetUtil.UTF_8));
            resp.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 2);
            assertTrue(ch.writeOutbound(resp));
            ByteBuf buf = ch.readOutbound();
            buf.release();
        }

        // Respond to the 14 GET requests that were added.
        for (int i = 30; i < 44; i++) {
            FullHttpResponse resp = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
                    Unpooled.copiedBuffer("ok", CharsetUtil.UTF_8));
            resp.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 2);
            assertTrue(ch.writeOutbound(resp));
            ByteBuf buf = ch.readOutbound();
            String encoded = buf.toString(CharsetUtil.US_ASCII);
            assertTrue(encoded.contains("ok"), "GET response at position " + i + " should contain body");
            buf.release();
        }

        // Respond to the HEAD request at position 44 — must be content-always-empty.
        HttpResponse headResp = new DefaultHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK);
        headResp.headers().setInt(HttpHeaderNames.CONTENT_LENGTH, 999);
        assertTrue(ch.writeOutbound(headResp));
        assertTrue(ch.writeOutbound(LastHttpContent.EMPTY_LAST_CONTENT));

        ByteBuf buf = ch.readOutbound();
        String encoded = buf.toString(CharsetUtil.US_ASCII);
        assertTrue(encoded.contains("HTTP/1.1 200 OK"), "HEAD response should be 200 OK");
        buf.release();

        buf = ch.readOutbound();
        assertFalse(buf.isReadable(), "HEAD response body should be empty in overflow scenario");
        buf.release();

        assertFalse(ch.finishAndReleaseAll());
    }

@Test
    @Timeout(value = 5000, unit = TimeUnit.MILLISECONDS)
    public void testHandshakeFailBeforeWritePromise() throws Exception {
        SelfSignedCertificate ssc = CachedSelfSignedCertificate.getCachedCertificate();
        final SslContext sslServerCtx = SslContextBuilder.forServer(ssc.certificate(), ssc.privateKey()).build();
        final CountDownLatch latch = new CountDownLatch(2);
        final CountDownLatch latch2 = new CountDownLatch(2);
        final BlockingQueue<Object> events = new LinkedBlockingQueue<Object>();
        Channel serverChannel = null;
        Channel clientChannel = null;
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(LocalIoHandler.newFactory());
        try {
            ServerBootstrap sb = new ServerBootstrap();
            sb.group(group)
                .channel(LocalServerChannel.class)
                .childHandler(new ChannelInitializer<Channel>() {
                  @Override
                  protected void initChannel(Channel ch) {
                      ch.pipeline().addLast(sslServerCtx.newHandler(ch.alloc()));
                      ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                          @Override
                          public void channelActive(ChannelHandlerContext ctx) {
                              ByteBuf buf = ctx.alloc().buffer(10);
                              buf.writeZero(buf.capacity());
                              ctx.writeAndFlush(buf).addListener(future -> {
                                  events.add(future);
                                  latch.countDown();
                              });
                          }

                          @Override
                          public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                              if (evt instanceof SslCompletionEvent) {
                                  events.add(evt);
                                  latch.countDown();
                                  latch2.countDown();
                              }
                          }
                      });
                      ch.pipeline().addLast(new SilenceExceptionHandler()
                              .rootCauseInstanceOf(NotSslRecordException.class));
                  }
                });

            Bootstrap cb = new Bootstrap();
            cb.group(group)
                .channel(LocalChannel.class)
                .handler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) {
                        ch.pipeline().addFirst(new ChannelInboundHandlerAdapter() {
                            @Override
                            public void channelActive(ChannelHandlerContext ctx) {
                                ByteBuf buf = ctx.alloc().buffer(1000);
                                buf.writeZero(buf.capacity());
                                ctx.writeAndFlush(buf);
                            }
                        });
                    }
                });

            serverChannel = sb.bind(new LocalAddress(SslHandlerTest.class)).sync().channel();
            clientChannel = cb.connect(serverChannel.localAddress()).sync().channel();
            latch.await();

            SslCompletionEvent evt = (SslCompletionEvent) events.take();
            assertInstanceOf(SslHandshakeCompletionEvent.class, evt);
            assertInstanceOf(SSLException.class, evt.cause());

            ChannelFuture future = (ChannelFuture) events.take();
            assertInstanceOf(SSLException.class, future.cause());

            serverChannel.close().sync();
            serverChannel = null;
            clientChannel.close().sync();
            clientChannel = null;

            latch2.await();
            evt = (SslCompletionEvent) events.take();
            assertInstanceOf(SslCloseCompletionEvent.class, evt);
            assertInstanceOf(ClosedChannelException.class, evt.cause());
            assertTrue(events.isEmpty());
        } finally {
            if (serverChannel != null) {
                serverChannel.close();
            }
            if (clientChannel != null) {
                clientChannel.close();
            }
            group.shutdownGracefully();
            ReferenceCountUtil.release(sslServerCtx);
        }
    }

private void select(IoHandlerContext runner, boolean oldWakenUp) throws IOException {
        Selector selector = this.selector;
        try {
            int selectCnt = 0;
            long currentTimeNanos = System.nanoTime();
            final long delayNanos = runner.delayNanos(currentTimeNanos);
            // that's some special value which is used to indicate that no scheduled task is present.
            // we set the deadline to a bogus (unused) value for us to represent infinity
            long selectDeadLineNanos = Long.MAX_VALUE;
            if (delayNanos != Long.MAX_VALUE) {
                selectDeadLineNanos = currentTimeNanos + runner.delayNanos(currentTimeNanos);
            }
            for (;;) {
                final long timeoutMillis;
                if (delayNanos != Long.MAX_VALUE) {
                    long millisBeforeDeadline = millisBeforeDeadline(selectDeadLineNanos, currentTimeNanos);
                    if (millisBeforeDeadline <= 0) {
                        if (selectCnt == 0) {
                            selector.selectNow();
                            selectCnt = 1;
                        }
                        break;
                    }
                    timeoutMillis = millisBeforeDeadline;
                } else {
                    // in NIO this means to block without any deadline
                    timeoutMillis = 0;
                }
                // If a task was submitted when wakenUp value was true, the task didn't get a chance to call
                // Selector#wakeup. So we need to check task queue again before executing select operation.
                // If we don't, the task might be pended until select operation was timed out.
                // It might be pended until idle timeout if IdleStateHandler existed in pipeline.
                if (!runner.canBlock() && wakenUp.compareAndSet(false, true)) {
                    selector.selectNow();
                    selectCnt = 1;
                    break;
                }

                int selectedKeys = selector.select(timeoutMillis);
                selectCnt ++;

                if (selectedKeys != 0 || oldWakenUp || wakenUp.get() || !runner.canBlock()) {
                    // - Selected something,
                    // - waken up by user, or
                    // - the task queue has a pending task.
                    // - a scheduled task is ready for processing
                    break;
                }
                if (Thread.interrupted()) {
                    // Thread was interrupted so reset selected keys and break so we not run into a busy loop.
                    // As this is most likely a bug in the handler of the user or it's client library we will
                    // also log it.
                    //
                    // See https://github.com/netty/netty/issues/2426
                    if (logger.isDebugEnabled()) {
                        logger.debug("Selector.select() returned prematurely because " +
                                "Thread.currentThread().interrupt() was called. Use " +
                                "NioHandler.shutdownGracefully() to shutdown the NioHandler.");
                    }
                    selectCnt = 1;
                    break;
                }

                long time = System.nanoTime();
                if (time - TimeUnit.MILLISECONDS.toNanos(timeoutMillis) >= currentTimeNanos) {
                    // timeoutMillis elapsed without anything selected.
                    selectCnt = 1;
                } else if (SELECTOR_AUTO_REBUILD_THRESHOLD > 0 &&
                        selectCnt >= SELECTOR_AUTO_REBUILD_THRESHOLD) {
                    // The code exists in an extra method to ensure the method is not too big to inline as this
                    // branch is not very likely to get hit very frequently.
                    selector = selectRebuildSelector(selectCnt);
                    selectCnt = 1;
                    break;
                }

                currentTimeNanos = time;
            }

            if (selectCnt > MIN_PREMATURE_SELECTOR_RETURNS) {
                if (logger.isDebugEnabled()) {
                    logger.debug("Selector.select() returned prematurely {} times in a row for Selector {}.",
                            selectCnt - 1, selector);
                }
            }
        } catch (CancelledKeyException e) {
            if (logger.isDebugEnabled()) {
                logger.debug(CancelledKeyException.class.getSimpleName() + " raised by a Selector {} - JDK bug?",
                        selector, e);
            }
            // Harmless exception - log anyway
        }
    }

@Override
        void epollInReady() {
            final ChannelConfig config = config();
            if (shouldBreakEpollInReady(config)) {
                clearEpollIn0();
                return;
            }
            final EpollRecvByteAllocatorHandle allocHandle = recvBufAllocHandle();
            final ChannelPipeline pipeline = pipeline();
            final ByteBufAllocator allocator = config.getAllocator();
            allocHandle.reset(config);

            ByteBuf byteBuf = null;
            boolean allDataRead = false;
            Queue<SpliceInTask> sQueue = null;
            try {
                do {
                    if (sQueue != null || (sQueue = spliceQueue) != null) {
                        SpliceInTask spliceTask = sQueue.peek();
                        if (spliceTask != null) {
                            boolean spliceInResult = spliceTask.spliceIn(allocHandle);

                            if (allocHandle.isReceivedRdHup()) {
                                shutdownInput(false);
                            }
                            if (spliceInResult) {
                                // We need to check if it is still active as if not we removed all SpliceTasks in
                                // doClose(...)
                                if (isActive()) {
                                    sQueue.remove();
                                }
                                continue;
                            } else {
                                break;
                            }
                        }
                    }

                    // we use a direct buffer here as the native implementations only be able
                    // to handle direct buffers.
                    byteBuf = allocHandle.allocate(allocator);
                    allocHandle.lastBytesRead(doReadBytes(byteBuf));
                    if (allocHandle.lastBytesRead() <= 0) {
                        // nothing was read, release the buffer.
                        byteBuf.release();
                        byteBuf = null;
                        allDataRead = allocHandle.lastBytesRead() < 0;
                        if (allDataRead) {
                            // There is nothing left to read as we received an EOF.
                            readPending = false;
                        }
                        break;
                    }
                    allocHandle.incMessagesRead(1);
                    readPending = false;
                    pipeline.fireChannelRead(byteBuf);
                    byteBuf = null;

                    if (shouldBreakEpollInReady(config)) {
                        // We need to do this for two reasons:
                        //
                        // - If the input was shutdown in between (which may be the case when the user did it in the
                        //   fireChannelRead(...) method we should not try to read again to not produce any
                        //   miss-leading exceptions.
                        //
                        // - If the user closes the channel we need to ensure we not try to read from it again as
                        //   the filedescriptor may be re-used already by the OS if the system is handling a lot of
                        //   concurrent connections and so needs a lot of filedescriptors. If not do this we risk
                        //   reading data from a filedescriptor that belongs to another socket then the socket that
                        //   was "wrapped" by this Channel implementation.
                        break;
                    }
                } while (allocHandle.continueReading());

                allocHandle.readComplete();
                pipeline.fireChannelReadComplete();

                if (allDataRead) {
                    shutdownInput(true);
                }
            } catch (Throwable t) {
                handleReadException(pipeline, byteBuf, t, allDataRead, allocHandle);
            } finally {
                if (sQueue == null) {
                    if (shouldStopReading(config)) {
                        clearEpollIn();
                    }
                } else {
                    if (!config.isAutoRead()) {
                        clearEpollIn();
                    }
                }
            }
        }

private static void testBufferLifecycleCorrectlyHandled(Bootstrap cb, boolean multiple, Close remoteClose)
            throws Throwable {
        cb.handler(new ChannelInboundHandlerAdapter());
        // Force to use send_zc / sendmsg_zc if supported.
        cb.option(IoUringChannelOption.IO_URING_WRITE_ZERO_COPY_THRESHOLD, 0);
        if (remoteClose == Close.LOCAL) {
            // Configure TCP_USER_TIMEOUT to a small number so the buffers can be returned quickly.
            // See:
            // - https://man7.org/linux/man-pages/man7/tcp.7.html
            // - https://github.com/torvalds/linux/blob/v6.16/include/uapi/linux/tcp.h#L111
            cb.option(new IntegerUnixChannelOption("TCP_USER_TIMEOUT", 6, 18), 1000);
        }

        try (ServerSocket serverSocket = new ServerSocket()) {
            serverSocket.bind(new InetSocketAddress(0));
            ChannelFuture future = cb.connect(serverSocket.getLocalSocketAddress());
            final AtomicReference<Throwable> causeRef = new AtomicReference<>();

            try (Socket socket = serverSocket.accept()) {
                // We accept the socket but don't read data, this way we will not receive the second notification
                // for the send as we never see a TCP ack until we start reading.
                Channel channel = future.sync().channel();
                try {
                    final int numBuffers = multiple ? 2: 1;
                    CountDownLatch latch = new CountDownLatch(numBuffers);
                    int bufferSize = 1024 * 1024;
                    final ByteBuf buffer = channel.alloc().buffer(bufferSize);
                    future.addListener(f -> {
                        if (f.isSuccess()) {
                            ChannelFutureListener writeListener = f2 -> {
                                if (!f2.isSuccess()) {
                                    causeRef.compareAndSet(null, f2.cause());
                                }
                                latch.countDown();
                            };

                            buffer.writerIndex(buffer.capacity());
                            if (multiple) {
                                channel.write(buffer.readRetainedSlice(buffer.readableBytes() / 2))
                                        .addListener(writeListener);
                            }
                            channel.writeAndFlush(buffer)
                                    .addListener(writeListener);
                        } else {
                            buffer.release();
                            causeRef.set(f.cause());

                            for (int i = 0; i < numBuffers; i++) {
                                latch.countDown();
                            }
                        }
                    });
                    latch.await();
                    Throwable cause = causeRef.get();
                    if (cause != null) {
                        fail(cause);
                    }
                    // This is the primary CQE with IORING_CQE_F_MORE. The zero-copy references must remain live
                    // until the following IORING_CQE_F_NOTIF, because the peer has neither acknowledged nor closed.
                    assertEquals(numBuffers, buffer.refCnt());

                    switch (remoteClose) {
                        case REMOTE:
                            // Don't read any data but just close the socket. This should trigger the required
                            // notifications to release the buffers.
                            socket.close();
                            break;
                        case LOCAL:
                            // Don't read any data but just close the channel. Once we did not see an ack for the
                            // configured TCP_USER_TIMEOUT we will get the required notifications to release the buffers
                            channel.close().sync();
                            break;
                        case NONE:
                            // Let's read the bytes now so the buffer can be released again from the NIC.
                            try (InputStream stream = socket.getInputStream()) {
                                byte[] bytes = new byte[64 * 1024];
                                int r;
                                while (bufferSize != 0 &&
                                        (r = stream.read(bytes, 0, Math.min(bufferSize, bytes.length))) != -1) {
                                    bufferSize -= r;
                                }
                            }
                            break;
                    }

                    // Wait till the buffer was finally released, which should be done in a timely fashion.
                    assertTrue(awaitRefCntZero(channel, buffer, 5, TimeUnit.SECONDS),
                            "zero-copy buffer was not released in time");
                } finally {
                    // Close the channel now
                    channel.close().sync();
                }
            }
        }
    }

@Test
    public void negativeWindowShouldNotThrowException() throws Http2Exception {
        final int initWindow = 20;
        final int secondWindowSize = 10;
        controller.initialWindowSize(initWindow);
        assertWritabilityChanged(0, true);
        reset(listener);

        FakeFlowControlled data1 = new FakeFlowControlled(initWindow);
        FakeFlowControlled data2 = new FakeFlowControlled(5);

        // Deplete the stream A window to 0
        sendData(STREAM_A, data1);
        controller.writePendingBytes();
        data1.assertFullyWritten();
        assertTrue(window(CONNECTION_STREAM_ID) > 0);
        verify(listener, times(1)).writabilityChanged(stream(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
        reset(listener);

        // Make the window size for stream A negative
        controller.initialWindowSize(initWindow - secondWindowSize);
        assertEquals(-secondWindowSize, window(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
        reset(listener);

        // Queue up a write. It should not be written now because the window is negative
        sendData(STREAM_A, data2);
        controller.writePendingBytes();
        data2.assertNotWritten();
        verify(listener, never()).writabilityChanged(stream(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
        reset(listener);

        // Open the window size back up a bit (no send should happen)
        incrementWindowSize(STREAM_A, 5);
        controller.writePendingBytes();
        assertEquals(-5, window(STREAM_A));
        data2.assertNotWritten();
        verify(listener, never()).writabilityChanged(stream(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
        reset(listener);

        // Open the window size back up a bit (no send should happen)
        incrementWindowSize(STREAM_A, 5);
        controller.writePendingBytes();
        assertEquals(0, window(STREAM_A));
        data2.assertNotWritten();
        verify(listener, never()).writabilityChanged(stream(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
        reset(listener);

        // Open the window size back up and allow the write to happen
        incrementWindowSize(STREAM_A, 5);
        controller.writePendingBytes();
        data2.assertFullyWritten();
        verify(listener, never()).writabilityChanged(stream(STREAM_A));
        verify(listener, never()).writabilityChanged(stream(STREAM_B));
        verify(listener, never()).writabilityChanged(stream(STREAM_C));
        verify(listener, never()).writabilityChanged(stream(STREAM_D));
        assertFalse(controller.isWritable(stream(STREAM_A)));
        assertTrue(controller.isWritable(stream(STREAM_B)));
        assertTrue(controller.isWritable(stream(STREAM_C)));
        assertTrue(controller.isWritable(stream(STREAM_D)));
    }

@Test
    void testNioHandlerCanBeDrivenByMainThread() throws Exception {
        IoHandlerFactory factory = NioIoHandler.newFactory();
        final Thread current = Thread.currentThread();
        final Queue<Runnable> tasks = new ConcurrentLinkedQueue<>();
        // Create our own IoExecutor that is driven by the main thread
        final ThreadAwareExecutor executor = new ThreadAwareExecutor() {
            @Override
            public boolean isExecutorThread(Thread thread) {
                return current == thread;
            }

            @Override
            public void execute(Runnable command) {
                tasks.add(command);
            }
        };
        IoHandlerContext context = new IoHandlerContext() {
            @Override
            public boolean canBlock() {
                // Just busy spin.
                return false;
            }

            @Override
            public long delayNanos(long currentTimeNanos) {
                return 0;
            }

            @Override
            public long deadlineNanos() {
                return -1;
            }
        };
        IoHandler handler = factory.newHandler(executor);

        // Open a ServerSocketChannel that we can connect to.
        ServerSocketChannel channel = SelectorProvider.provider().openServerSocketChannel();
        channel.configureBlocking(false);
        channel.bind(new InetSocketAddress(NetUtil.LOCALHOST, 0));
        // Do the connect in another thread so we don't block our io execution loop.
        Thread t = new Thread(new Runnable() {
            @Override
            public void run() {
                Socket socket = new Socket();
                try {
                    socket.connect(channel.getLocalAddress());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
        });
        AtomicBoolean acceptedConnection = new AtomicBoolean();
        IoRegistration registration = handler.register(new NioSelectableChannelIoHandle<ServerSocketChannel>(channel) {
            @Override
            protected void handle(ServerSocketChannel channel, SelectionKey key) {
                if (key.isAcceptable()) {
                    try {
                        // Just accept the connection and close it.
                        java.nio.channels.SocketChannel accepted = channel.accept();
                        accepted.close();
                    } catch (Exception e) {
                        // ignore
                    } finally {
                        acceptedConnection.set(true);
                    }
                }
            }
        });
        registration.submit(NioIoOps.ACCEPT);
        t.start();

        // Let's loop until our registration was cancelled.
        while (registration.isValid()) {
            handler.run(context);
            for (;;) {
                // Execute all tasks that were dispatched.
                Runnable r = tasks.poll();
                if (r == null) {
                    break;
                }
                r.run();
            }
            if (acceptedConnection.get()) {
                // We accepted the connection, let's cancel the registration.
                assertTrue(registration.cancel());
            }
        }
        // Wait until the connect thread is done.
        t.join();

        // Let's now close the ServerSocketChannel and after that destroy the IoHandler.
        channel.close();
        handler.prepareToDestroy();
        handler.destroy();
    }

@Test
    public void testExecutorPreserveOrdering() throws Exception {
        final EventLoopGroup compressorGroup = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());
        EventLoopGroup localGroup = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());
        Channel server = null;
        Channel client = null;
        try {
            ServerBootstrap bootstrap = new ServerBootstrap()
                .channel(LocalServerChannel.class)
                .group(localGroup)
                .childHandler(new ChannelInitializer<LocalChannel>() {
                @Override
                protected void initChannel(LocalChannel ch) throws Exception {
                    ch.pipeline()
                        .addLast(new HttpServerCodec())
                        .addLast(new HttpObjectAggregator(1024))
                        .addLast(compressorGroup, new HttpContentCompressor())
                        .addLast(new ChannelOutboundHandlerAdapter() {
                            @Override
                            public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise)
                                throws Exception {
                                super.write(ctx, msg, promise);
                            }
                        })
                        .addLast(new ChannelInboundHandlerAdapter() {
                            @Override
                            public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                                if (msg instanceof FullHttpRequest) {
                                    FullHttpResponse res =
                                        new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
                                            Unpooled.copiedBuffer("Hello, World", CharsetUtil.US_ASCII));
                                    ctx.writeAndFlush(res);
                                    ReferenceCountUtil.release(msg);
                                    return;
                                }
                                super.channelRead(ctx, msg);
                            }
                        });
                }
            });

            LocalAddress address = new LocalAddress(UUID.randomUUID().toString());
            server = bootstrap.bind(address).sync().channel();

            final BlockingQueue<HttpObject> responses = new LinkedBlockingQueue<HttpObject>();

            client = new Bootstrap()
                .channel(LocalChannel.class)
                .remoteAddress(address)
                .group(localGroup)
                .handler(new ChannelInitializer<LocalChannel>() {
                @Override
                protected void initChannel(LocalChannel ch) throws Exception {
                    ch.pipeline().addLast(new HttpClientCodec()).addLast(new ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                            if (msg instanceof HttpObject) {
                                responses.put((HttpObject) msg);
                                return;
                            }
                            super.channelRead(ctx, msg);
                        }
                    });
                }
            }).connect().sync().channel();

            client.writeAndFlush(newRequest()).sync();

            assertEncodedResponse((HttpResponse) responses.poll(5, TimeUnit.SECONDS));
            HttpContent c = (HttpContent) responses.poll(5, TimeUnit.SECONDS);
            assertNotNull(c);
            assertEquals("1f8b0800000000000000f248cdc9c9d75108cf2fca4901000000ffff",
                    ByteBufUtil.hexDump(c.content()));
            c.release();

            c = (HttpContent) responses.poll(5, TimeUnit.SECONDS);
            assertNotNull(c);
            assertEquals("0300c6865b260c000000", ByteBufUtil.hexDump(c.content()));
            c.release();

            LastHttpContent last = (LastHttpContent) responses.poll(5, TimeUnit.SECONDS);
            assertNotNull(last);
            assertEquals(0, last.content().readableBytes());
            last.release();

            assertNull(responses.poll(1, TimeUnit.SECONDS));
        } finally {
            if (client != null) {
                client.close().sync();
            }
            if (server != null) {
                server.close().sync();
            }
            compressorGroup.shutdownGracefully();
            localGroup.shutdownGracefully();
        }
    }

@Test
    @Timeout(value = 5000, unit = TimeUnit.MILLISECONDS)
    public void testWriteTaskRejected() throws Exception {
        final SingleThreadEventExecutor executor = new SingleThreadEventExecutor(
                null, new DefaultThreadFactory("executorPool"),
                true, 1, RejectedExecutionHandlers.reject()) {
            @Override
            protected void run() {
                do {
                    Runnable task = takeTask();
                    if (task != null) {
                        task.run();
                        updateLastExecutionTime();
                    }
                } while (!confirmShutdown());
            }

            @Override
            protected Queue<Runnable> newTaskQueue(int maxPendingTasks) {
                return super.newTaskQueue(1);
            }
        };
        final CountDownLatch handlerAddedLatch = new CountDownLatch(1);
        final CountDownLatch handlerRemovedLatch = new CountDownLatch(1);
        EmbeddedChannel ch = new EmbeddedChannel();
        ch.pipeline().addLast(executor, "handler", new ChannelOutboundHandlerAdapter() {
            @Override
            public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                promise.setFailure(new AssertionError("Should not be called"));
            }

            @Override
            public void handlerAdded(ChannelHandlerContext ctx) {
                handlerAddedLatch.countDown();
            }

            @Override
            public void handlerRemoved(ChannelHandlerContext ctx) {
                handlerRemovedLatch.countDown();
            }
        });

        // Lets wait until we are sure the handler was added.
        handlerAddedLatch.await();

        final CountDownLatch executeLatch = new CountDownLatch(1);
        final CountDownLatch runLatch = new CountDownLatch(1);
        executor.execute(new Runnable() {
            @Override
            public void run() {
                try {
                    runLatch.countDown();
                    executeLatch.await();
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
            }
        });

        runLatch.await();

        executor.execute(new Runnable() {
            @Override
            public void run() {
                // Will not be executed but ensure the pending count is 1.
            }
        });

        assertEquals(1, executor.pendingTasks());
        assertEquals(0, ch.unsafe().outboundBuffer().totalPendingWriteBytes());

        ByteBuf buffer = buffer(128).writeZero(128);
        ChannelFuture future = ch.write(buffer);
        ch.runPendingTasks();

        assertInstanceOf(RejectedExecutionException.class, future.cause());
        assertEquals(0, buffer.refCnt());

        // In case of rejected task we should not have anything pending.
        assertEquals(0, ch.unsafe().outboundBuffer().totalPendingWriteBytes());
        executeLatch.countDown();

        while (executor.pendingTasks() != 0) {
            // Wait until there is no more pending task left.
            Thread.sleep(10);
        }

        ch.pipeline().remove("handler");

        // Ensure we do not try to shutdown the executor before we handled everything for the Channel. Otherwise
        // the Executor may reject when the Channel tries to add a task to it.
        handlerRemovedLatch.await();

        safeClose(ch);

        executor.shutdownGracefully();
    }

private boolean allocate(int size, int maxCapacity, AdaptiveByteBuf buf, boolean reallocate) {
            int startingCapacity = chunkController.computeBufferCapacity(size, maxCapacity, reallocate);
            Chunk curr = current;
            if (curr != null) {
                boolean success = curr.readInitInto(buf, size, startingCapacity, maxCapacity);
                int remainingCapacity = curr.remainingCapacity();
                if (!success && remainingCapacity > 0) {
                    current = null;
                    transferToNextInLineOrRelease(curr);
                } else if (remainingCapacity == 0) {
                    current = null;
                    curr.releaseFromMagazine();
                }
                if (success) {
                    return true;
                }
            }

            assert current == null;
            // The fast-path for allocations did not work.
            //
            // Try to fetch the next "Magazine local" Chunk first, if this fails because we don't have a
            // next-in-line chunk available, we will poll our centralQueue.
            // If this fails as well we will just allocate a new Chunk.
            //
            // In any case we will store the Chunk as the current so it will be used again for the next allocation and
            // thus be "reserved" by this Magazine for exclusive usage.
            curr = NEXT_IN_LINE.getAndSet(this, null);
            if (curr != null) {
                if (curr == MAGAZINE_FREED) {
                    // Allocation raced with a stripe-resize that freed this magazine.
                    restoreMagazineFreed();
                    return false;
                }

                int remainingCapacity = curr.remainingCapacity();
                if (remainingCapacity > startingCapacity &&
                        curr.readInitInto(buf, size, startingCapacity, maxCapacity)) {
                    // We have a Chunk that has some space left.
                    current = curr;
                    return true;
                }

                try {
                    if (remainingCapacity >= size) {
                        // At this point we know that this will be the last time curr will be used, so directly set it
                        // to null and release it once we are done.
                        return curr.readInitInto(buf, size, remainingCapacity, maxCapacity);
                    }
                } finally {
                    // Release in a finally block so even if readInitInto(...) would throw we would still correctly
                    // release the current chunk before null it out.
                    curr.releaseFromMagazine();
                }
            }

            // Now try to poll from the central queue first
            curr = group.pollChunk(size);
            if (curr == null) {
                curr = chunkController.newChunkAllocation(size, this);
            } else {
                curr.attachToMagazine(this);

                int remainingCapacity = curr.remainingCapacity();
                if (remainingCapacity == 0 || remainingCapacity < size) {
                    // Check if we either retain the chunk in the nextInLine cache or releasing it.
                    if (remainingCapacity < RETIRE_CAPACITY) {
                        curr.releaseFromMagazine();
                    } else {
                        // See if it makes sense to transfer the Chunk to the nextInLine cache for later usage.
                        // This method will release curr if this is not the case
                        transferToNextInLineOrRelease(curr);
                    }
                    curr = chunkController.newChunkAllocation(size, this);
                }
            }

            current = curr;
            boolean success;
            try {
                int remainingCapacity = curr.remainingCapacity();
                assert remainingCapacity >= size;
                if (remainingCapacity > startingCapacity) {
                    success = curr.readInitInto(buf, size, startingCapacity, maxCapacity);
                    curr = null;
                } else {
                    success = curr.readInitInto(buf, size, remainingCapacity, maxCapacity);
                }
            } finally {
                if (curr != null) {
                    // Release in a finally block so even if readInitInto(...) would throw we would still correctly
                    // release the current chunk before null it out.
                    curr.releaseFromMagazine();
                    current = null;
                }
            }
            return success;
        }

@ParameterizedTest
    @EnumSource(CancelWhich.class)
    @Timeout(30)
    public void consolidatedQueryReleasesResponseWhenACallerIsCancelledBeforeResponse(CancelWhich cancelWhich)
            throws Exception {
        final AtomicInteger serverCalls = new AtomicInteger();
        final CountDownLatch serverReached = new CountDownLatch(1);
        final CountDownLatch releaseResponse = new CountDownLatch(1);
        final TestDnsServer dnsServer = new TestDnsServer(new RecordStore() {
            @Override
            public Set<ResourceRecord> getRecords(QuestionRecord question) {
                serverCalls.incrementAndGet();
                serverReached.countDown();
                try {
                    // Hold the response so the test can cancel one of the consolidated callers first.
                    releaseResponse.await(10, TimeUnit.SECONDS);
                } catch (InterruptedException e) {
                    throw new IllegalStateException(e);
                }
                ResourceRecordModifier rm = new ResourceRecordModifier();
                rm.setDnsClass(RecordClass.IN);
                rm.setDnsName(question.getDomainName());
                rm.setDnsTtl(100);
                rm.setDnsType(question.getRecordType());
                rm.put(DnsAttribute.IP_ADDRESS, "10.0.0.1");
                return Collections.singleton(rm.getEntry());
            }
        });
        dnsServer.start();
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory());
        EventLoop loop = group.next();
        // ChannelPerResolver shares one channel and ignores the query promise, so cancelling a caller has no channel
        // side effects; consolidateCacheSize > 0 enables the inflightLookups consolidation path in doQuery(...).
        DnsNameResolver resolver = new DnsNameResolverBuilder(loop)
                .datagramChannelType(NioDatagramChannel.class)
                .datagramChannelStrategy(DnsNameResolverChannelStrategy.ChannelPerResolver)
                .optResourceEnabled(false)
                .queryTimeoutMillis(10000)
                .consolidateCacheSize(2)
                .nameServerProvider(new SingletonDnsServerAddressStreamProvider(dnsServer.localAddress()))
                .build();

        AddressedEnvelope<? extends DnsResponse, InetSocketAddress> toRelease = null;
        try {
            final Promise<AddressedEnvelope<? extends DnsResponse, InetSocketAddress>> ownerPromise =
                    loop.newPromise();
            final Promise<AddressedEnvelope<? extends DnsResponse, InetSocketAddress>> waiterPromise =
                    loop.newPromise();

            // Issue both queries ON the event loop (doQuery and inflightLookups must stay loop-confined); one loop
            // task keeps the owner first so the waiter consolidates onto it. query() returns the caller's promise.
            loop.submit((Runnable) () -> {
                resolver.query(dnsServer.localAddress(), new DefaultDnsQuestion(HOSTNAME, DnsRecordType.A),
                        Collections.<DnsRecord>emptyList(), ownerPromise);
                resolver.query(dnsServer.localAddress(), new DefaultDnsQuestion(HOSTNAME, DnsRecordType.A),
                        Collections.<DnsRecord>emptyList(), waiterPromise);
            }).sync();

            // Wait until the (single, consolidated) query reached the gated server, then fence so the waiter's
            // deferred doQuery has run.
            assertTrue(serverReached.await(10, TimeUnit.SECONDS), "the consolidated query should reach the server");
            loop.submit((Runnable) () -> { }).sync();

            final Promise<AddressedEnvelope<? extends DnsResponse, InetSocketAddress>> cancelledPromise =
                    cancelWhich == CancelWhich.OWNER ? ownerPromise : waiterPromise;
            final Promise<AddressedEnvelope<? extends DnsResponse, InetSocketAddress>> livePromise =
                    cancelWhich == CancelWhich.OWNER ? waiterPromise : ownerPromise;

            // Cancel one caller BEFORE the gated response arrives (the other stays live); the gate plus the network
            // round-trip guarantee the loop processes the response well after this cancel.
            assertTrue(cancelledPromise.cancel(false), "the caller should be cancellable before the response");
            releaseResponse.countDown();

            assertTrue(livePromise.await(10, TimeUnit.SECONDS), "live caller should complete in time");
            assertTrue(livePromise.isSuccess(), "live caller should receive the response");
            // Fence so every consolidation listener (including RELEASE_LISTENER on the internal promise) has run.
            loop.submit((Runnable) () -> { }).sync();

            assertTrue(cancelledPromise.isCancelled(), "the cancelled caller stays cancelled");
            assertEquals(1, serverCalls.get(), "the waiter must consolidate onto the owner (single network query)");

            final AddressedEnvelope<? extends DnsResponse, InetSocketAddress> response = livePromise.getNow();
            assertNotNull(response, "the live caller must expose the response");
            toRelease = response;

            assertEquals(1, response.refCnt(),
                    "consolidated response must be owned exactly once by the live caller "
                            + "(the cancelled caller must not leak its retained reference)");

            assertTrue(ReferenceCountUtil.release(response), "single release should free the consolidated response");
            toRelease = null;
            assertEquals(0, response.refCnt(), "response must reach refCnt 0 with a single release");
        } finally {
            releaseResponse.countDown();
            if (toRelease != null && toRelease.refCnt() > 0) {
                ReferenceCountUtil.release(toRelease);
            }
            resolver.close();
            dnsServer.stop();
            group.shutdownGracefully(0, 0, TimeUnit.SECONDS).syncUninterruptibly();
        }
    }

@Overwrite
    public boolean saveAllChunks(final boolean suppressLog, final boolean flush, final boolean isForced) {
        boolean result = false;

        for (final ServerLevel level : this.shadow$getAllLevels()) {
            // Sponge start - use our own config
            final SerializationBehavior serializationBehavior = ((ServerLevelDataBridge) level.getLevelData()).bridge$serializationBehavior().orElse(SerializationBehavior.AUTOMATIC);
            final InheritableConfigHandle<WorldConfig> configAdapter = SpongeGameConfigs.getForWorld(level);
            final AutoSaveOptions configAutoSave = configAdapter.get().world.configAutoSave;

            // If the server isn't running or we hit save interval or this was triggered
            // by a command, save our configs
            if (!this.shadow$isRunning() || isForced || (configAutoSave.interval > 0 && this.tickCount % configAutoSave.interval == 0)) {
                if (flush || configAutoSave.batchInterval == 0) {
                    this.impl$worldConfigSaveQueue.remove(((ServerWorld) level).key());
                    this.impl$saveWorldConfig(level, configAdapter, configAutoSave.log);
                } else {
                    this.impl$worldConfigSaveQueue.add(configAutoSave, ((ServerWorld) level).key());
                }
            }

            final boolean canSaveAtAll = serializationBehavior != SerializationBehavior.NONE;

            // This world is set to not save of any time, no reason to check the auto-save/etc, skip it
            if (!canSaveAtAll) {
                continue;
            }

            final AutoSaveOptions autoSave = configAdapter.get().world.autoSave;

            // Only run auto-save skipping if the server is still running and the save is not forced
            if (this.bridge$performAutosaveChecks() && !isForced) {

                // Do not process properties or chunks if the world is not set to do so unless the server is shutting down
                if (autoSave.interval <= 0 || serializationBehavior != SerializationBehavior.AUTOMATIC) {
                    continue;
                }

                // Now check the interval vs the tick counter and skip it
                if (this.tickCount % autoSave.interval != 0) {
                    continue;
                }

                if (!flush && autoSave.batchInterval > 0) {
                    this.impl$worldSaveQueue.add(autoSave, ((ServerWorld) level).key());
                    result = true;
                    continue;
                }
            }

            this.impl$worldSaveQueue.remove(((ServerWorld) level).key());
            // Sponge end

            if (autoSave.log) {
                LOGGER.info("Saving chunks for level '{}'/{}", level, level.dimension().location());
            }

            level.save(null, flush, level.noSave && !isForced);
            result = true;
        }

        // Sponge start - We do per-world WorldInfo/WorldBorders/BossBars
//        ServerLevel var2 = this.overworld();
//        ServerLevelData var3 = this.worldData.overworldData();
//        var3.setWorldBorder(var2.getWorldBorder().createSettings());
//        this.worldData.setCustomBossEvents(this.getCustomBossEvents().save(this.registryAccess()));
//        this.storageSource.saveDataTag(this.registryHolder, this.worldData, this.shadow$getPlayerList().getSingleplayerData());
        // Sponge end

        // Sponge start
        // Save the usercache.json file every 10 minutes or if forced to
        if (isForced || this.tickCount % 6000 == 0) {
            // We want to save the username cache json, as we normally bypass it.
            final GameProfileCache profileCache = this.shadow$getProfileCache();
            // The game test server has no profile cache
            if (profileCache != null) {
                ((GameProfileCacheBridge) profileCache).bridge$setCanSave(true);
                profileCache.save();
                ((GameProfileCacheBridge) profileCache).bridge$setCanSave(false);
            }
        }
        // Sponge end

        if (flush) {
            for (final ServerLevel level : this.shadow$getAllLevels()) {
                // Sponge start - use our own config
                final InheritableConfigHandle<WorldConfig> configAdapter = SpongeGameConfigs.getForWorld(level);
                final boolean log = configAdapter.get().world.autoSave.log;
                // Sponge end

                if (log) {
                    LOGGER.info("ThreadedAnvilChunkStorage ({}): All chunks are saved", level.getChunkSource().chunkMap.getStorageName());
                }
            }

            LOGGER.info("ThreadedAnvilChunkStorage: All dimensions are saved");
        }

        this.impl$worldConfigSaveQueue.drain();
        this.impl$worldSaveQueue.drain();

        return result;
    }

@Test
    public void multipleFramesInFin() throws Exception {
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory());
        try {
            Bootstrap bootstrap = new Bootstrap()
                    .channel(NioDatagramChannel.class)
                    .handler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) throws Exception {
                            // initialized below
                        }
                    })
                    .group(group);

            SelfSignedCertificate cert = new SelfSignedCertificate();

            Channel server = bootstrap.bind("127.0.0.1", 0).sync().channel();
            server.pipeline().addLast(Http3.newQuicServerCodecBuilder()
                    .initialMaxData(10000000)
                    .initialMaxStreamDataBidirectionalLocal(1000000)
                    .initialMaxStreamDataBidirectionalRemote(1000000)
                    .initialMaxStreamsBidirectional(100)
                    .sslContext(QuicSslContextBuilder.forServer(cert.key(), null, cert.cert())
                            .applicationProtocols(Http3.supportedApplicationProtocols()).build())
                    .tokenHandler(InsecureQuicTokenHandler.INSTANCE)
                    .handler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) throws Exception {
                            ch.pipeline().addLast(new Http3ServerConnectionHandler(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                                    if (msg instanceof Http3HeadersFrame) {
                                        DefaultHttp3HeadersFrame responseHeaders = new DefaultHttp3HeadersFrame();
                                        responseHeaders.headers().status(HttpResponseStatus.OK.codeAsText());
                                        ctx.write(responseHeaders, ctx.voidPromise());
                                        ctx.write(new DefaultHttp3DataFrame(ByteBufUtil.encodeString(
                                                ctx.alloc(), CharBuffer.wrap("foo"), CharsetUtil.UTF_8)),
                                                ctx.voidPromise());
                                        // send a fin, this also flushes
                                        ((DuplexChannel) ctx.channel()).shutdownOutput();
                                    } else {
                                        super.channelRead(ctx, msg);
                                    }
                                }
                            }));
                        }
                    })
                    .build());

            Channel client = bootstrap.bind("127.0.0.1", 0).sync().channel();
            client.config().setAutoRead(true);
            client.pipeline().addLast(Http3.newQuicClientCodecBuilder()
                    .initialMaxData(10000000)
                    .initialMaxStreamDataBidirectionalLocal(1000000)
                    .sslContext(QuicSslContextBuilder.forClient()
                            .trustManager(InsecureTrustManagerFactory.INSTANCE)
                            .applicationProtocols(Http3.supportedApplicationProtocols())
                            .build())
                    .build());

            QuicChannel quicChannel = QuicChannel.newBootstrap(client)
                    .handler(new ChannelInitializer<QuicChannel>() {
                        @Override
                        protected void initChannel(QuicChannel ch) throws Exception {
                            ch.pipeline().addLast(new Http3ClientConnectionHandler());
                        }
                    })
                    .remoteAddress(server.localAddress())
                    .localAddress(client.localAddress())
                    .connect().get();

            BlockingQueue<Object> received = new LinkedBlockingQueue<>();
            QuicStreamChannel stream = Http3.newRequestStream(quicChannel, new Http3RequestStreamInitializer() {
                @Override
                protected void initRequestStream(QuicStreamChannel ch) {
                    ch.pipeline()
                            .addLast(new Http3FrameToHttpObjectCodec(false))
                            .addLast(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                                    received.put(msg);
                                }
                            });
                }
            }).get();
            DefaultFullHttpRequest request = new DefaultFullHttpRequest(HttpVersion.HTTP_1_1, HttpMethod.GET, "/");
            request.headers().add(HttpHeaderNames.HOST, "localhost");
            stream.writeAndFlush(request);

            HttpResponse respHeaders = (HttpResponse) received.poll(20, TimeUnit.SECONDS);
            assertThat(respHeaders, notNullValue());
            assertThat(respHeaders.status(), is(HttpResponseStatus.OK));
            assertThat(respHeaders, not(instanceOf(LastHttpContent.class)));
            HttpContent respBody = (HttpContent) received.poll(20, TimeUnit.SECONDS);
            assertThat(respBody, notNullValue());
            assertThat(respBody.content().toString(CharsetUtil.UTF_8), is("foo"));
            respBody.release();

            LastHttpContent last = (LastHttpContent) received.poll(20, TimeUnit.SECONDS);
            assertThat(last, notNullValue());
            last.release();
        } finally {
            group.shutdownGracefully();
        }
    }

public static void passiveCrucibleParticles(SpiritCrucibleCoreBlockEntity crucible) {
        var activeSpiritType = crucible.getActiveSpiritType();
        var level = crucible.getLevel();
        var random = level.random;
        if (level.getGameTime() % 16L == 0) {
            var item = crucible.coreAugmentInventory.getStackInSlot(0);
            if (item.getItem() instanceof CoreAugmentItem augmentItem) {
                var blockPos = crucible.getBlockPos();
                for (var augmentSpiritType : augmentItem.spiritTypes) {
                    Vec3 offset = SpiritCrucibleCoreBlockEntity.CRUCIBLE_CORE_AUGMENT_OFFSET.add(
                            Mth.nextFloat(random, -0.1f, 0.1f),
                            Mth.nextFloat(random, -0.1f, 0.1f),
                            Mth.nextFloat(random, -0.1f, 0.1f));
                    var particlePosition = blockPos.getCenter().add(offset);
                    var lightSpecs = SpiritLightSpecs.spiritLightSpecs(level, particlePosition, augmentSpiritType);
                    lightSpecs.getBuilder().multiplyLifetime(2.5f).modifyScaleData(d -> d.multiplyValue(1.3f));
                    lightSpecs.getBloomBuilder().multiplyLifetime(1.5f);
                    lightSpecs.spawnParticles();
                }
            }
        }

        if (activeSpiritType == null) {
            return;
        }
        var itemPos = crucible.getItemPos();
        var spiritInventory = crucible.spiritInventory;
        var augmentInventory = crucible.augmentInventory;
        var recipe = crucible.recipe;
        if (recipe != null) {
            Optional<ArtificeInfluenceData> influenceData = crucible.attributes.getInfluenceData(level);
            influenceData.ifPresent(d -> {
                for (ArtificeModifierSourceInstance modifier : d.modifiers()) {
                    modifier.addParticles(crucible, activeSpiritType);
                }
            });
        }
        if (recipe != null) {
            var lightSpecs = spiritLightSpecs(level, itemPos, activeSpiritType, new WorldParticleOptions(MalumParticles.STAR.get()));
            lightSpecs.getBuilder()
                    .setSpinData(SpinParticleData.create(0).setSpinOffset((level.getGameTime() * 0.05f) % 6.28f).build())
                    .modifyScaleData(d -> d.multiplyValue(2f))
                    .modifyTransparencyData(d -> d.multiplyValue(0.25f));
            lightSpecs.getBloomBuilder()
                    .modifyScaleData(d -> d.multiplyValue(2f))
                    .modifyTransparencyData(d -> d.multiplyValue(0.5f));
            lightSpecs.spawnParticles();
        }

        if (recipe != null) {
            int spiritsRendered = 0;
            for (int i = 0; i < spiritInventory.getSlotCount(); i++) {
                var item = spiritInventory.getStackInSlot(i);
                if (item.getItem() instanceof SpiritShardItem shardItem) {
                    var offset = crucible.getSpiritItemOffset(spiritsRendered++, 0);
                    var blockPos = crucible.getBlockPos();
                    var spiritPosition = new Vec3(blockPos.getX() + offset.x, blockPos.getY() + offset.y, blockPos.getZ() + offset.z);
                    Vec3 velocity = itemPos.subtract(spiritPosition).normalize().scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.03f, 0.06f));
                    if (random.nextFloat() < 0.85f) {
                        var sparkParticles = SparkParticleEffects.spiritMotionSparks(level, spiritPosition, shardItem);
                        sparkParticles.getBuilder().setMotion(velocity).modifyScaleData(d -> d.multiplyValue(1.2f));
                        sparkParticles.getBloomBuilder().setMotion(velocity);
                        sparkParticles.spawnParticles();
                    }
                    if (random.nextFloat() < 0.85f) {
                        var lightSpecs = SpiritLightSpecs.spiritLightSpecs(level, spiritPosition, shardItem);
                        lightSpecs.getBuilder().multiplyLifetime(0.8f).setMotion(velocity.scale(1.5f)).modifyScaleData(d -> d.multiplyValue(1.6f));
                        lightSpecs.getBloomBuilder().setMotion(velocity);
                        lightSpecs.spawnParticles();
                    }
                }
            }
        }
        if (level.getGameTime() % 4L == 0) {
            int augmentsRendered = 0;
            for (int i = 0; i < augmentInventory.getSlotCount(); i++) {
                var item = augmentInventory.getStackInSlot(i);
                if (item.getItem() instanceof AugmentItem augmentItem) {
                    var offset = crucible.getAugmentItemOffset(augmentsRendered++, 0);
                    var blockPos = crucible.getBlockPos();
                    var particlePosition = new Vec3(blockPos.getX() + offset.x, blockPos.getY() + offset.y, blockPos.getZ() + offset.z);
                    for (var spiritType : augmentItem.spiritTypes) {
                        if (recipe != null) {
                            Vec3 velocity = itemPos.subtract(particlePosition).normalize().scale(Easing.SINE_IN_OUT.asWeighedRandom(random, 0.01f, 0.02f));
                            if (random.nextFloat() < 0.15f) {
                                var sparkParticles = SparkParticleEffects.spiritMotionSparks(level, particlePosition, spiritType);
                                sparkParticles.getBuilder().multiplyLifetime(2.5f).setMotion(velocity).modifyScaleData(d -> d.multiplyValue(1.2f));
                                sparkParticles.getBloomBuilder().multiplyLifetime(1.5f).setMotion(velocity);
                                sparkParticles.spawnParticles();
                            }
                            if (random.nextFloat() < 0.15f) {
                                var lightSpecs = SpiritLightSpecs.spiritLightSpecs(level, particlePosition, spiritType);
                                lightSpecs.getBuilder().multiplyLifetime(2.5f).setMotion(velocity.scale(1.5f)).modifyScaleData(d -> d.multiplyValue(1.6f));
                                lightSpecs.getBloomBuilder().multiplyLifetime(1.5f).setMotion(velocity);
                                lightSpecs.spawnParticles();
                            }
                        }
                        var lightSpecs = SpiritLightSpecs.spiritLightSpecs(level, particlePosition, spiritType);
                        lightSpecs.getBuilder().multiplyLifetime(2.5f).modifyScaleData(d -> d.multiplyValue(1.3f));
                        lightSpecs.getBloomBuilder().multiplyLifetime(1.5f);
                        lightSpecs.spawnParticles();
                    }
                }
            }
        }
    }

@ApiStatus.Internal
    public static void readAdditionalLevelSaveData(LevelStorageSource.LevelStorageAccess access, LevelStorageSource.LevelDirectory levelDirectory) {
        CompoundTag tag = null;
        try {
            CompoundTag rootTag = access.getDataTagRaw(false);
            tag = rootTag.getCompoundOrEmpty("fml");
        } catch (IOException e) {
            try {
                CompoundTag rootTag = access.getDataTagRaw(true);
                tag = rootTag.getCompoundOrEmpty("fml");
            } catch (IOException e2) {
                LOGGER.error(WORLDPERSISTENCE, "Failed to read level data.. ", e2);
                return;
            }
        }
        if (tag.contains("LoadingModList")) {
            ListTag modList = tag.getListOrEmpty("LoadingModList");
            Map<String, ArtifactVersion> mismatchedVersions = new HashMap<>(modList.size());
            Map<String, ArtifactVersion> missingVersions = new HashMap<>(modList.size());
            for (int i = 0; i < modList.size(); i++) {
                CompoundTag mod = modList.getCompoundOrEmpty(i);
                String modId = mod.getStringOr("ModId", null);
                if (Objects.equals("minecraft",  modId))
                    continue;

                String modVersion = mod.getStringOr("ModVersion", null);
                final var previousVersion = new DefaultArtifactVersion(modVersion);
                ModList.getModContainerById(modId).ifPresentOrElse(container -> {
                    final var loadingVersion = container.getModInfo().getVersion();
                    if (!loadingVersion.equals(previousVersion)) {
                        // Enqueue mismatched versions for bulk event
                        mismatchedVersions.put(modId, previousVersion);
                    }
                }, () -> missingVersions.put(modId, previousVersion));
            }

            final var mismatchEvent = new ModMismatchEvent(levelDirectory, mismatchedVersions, missingVersions);
            ModLoader.postEvent(mismatchEvent);

            StringBuilder resolved = new StringBuilder("The following mods have version differences that were marked resolved:");
            StringBuilder unresolved = new StringBuilder("The following mods have version differences that were not resolved:");

            // For mods that were marked resolved, log the version resolution and the mod that resolved the mismatch
            mismatchEvent.getResolved().forEachOrdered((res) -> {
                final var modid = res.modid();
                final var diff = res.versionDifference();
                if (res.wasSelfResolved()) {
                    resolved.append(System.lineSeparator())
                    .append(diff.isMissing()
                        ? "%s (version %s -> MISSING, self-resolved)".formatted(modid, diff.oldVersion())
                        : "%s (version %s -> %s, self-resolved)".formatted(modid, diff.oldVersion(), diff.newVersion())
                    );
                } else {
                    final var resolver = res.resolver().getModId();
                    resolved.append(System.lineSeparator())
                    .append(diff.isMissing()
                        ? "%s (version %s -> MISSING, resolved by %s)".formatted(modid, diff.oldVersion(), resolver)
                        : "%s (version %s -> %s, resolved by %s)".formatted(modid, diff.oldVersion(), diff.newVersion(), resolver)
                    );
                }
            });

            // For mods that did not specify handling, show a warning to users that errors may occur
            mismatchEvent.getUnresolved().forEachOrdered((unres) -> {
                final var modid = unres.modid();
                final var diff = unres.versionDifference();
                unresolved.append(System.lineSeparator())
                .append(diff.isMissing()
                    ? "%s (version %s -> MISSING)".formatted(modid, diff.oldVersion())
                    : "%s (version %s -> %s)".formatted(modid, diff.oldVersion(), diff.newVersion())
                );
            });

            if (mismatchEvent.anyResolved()) {
                resolved.append(System.lineSeparator()).append("Things may not work well.");
                LOGGER.debug(WORLDPERSISTENCE, resolved.toString());
            }

            if (mismatchEvent.anyUnresolved()) {
                unresolved.append(System.lineSeparator()).append("Things may not work well.");
                LOGGER.warn(WORLDPERSISTENCE, unresolved.toString());
            }
        }

        Multimap<Identifier, Identifier> failedElements = null;

        if (tag.contains("Registries")) {
            Map<Identifier, ForgeRegistry.Snapshot> snapshot = new HashMap<>();
            CompoundTag regs = tag.getCompoundOrEmpty("Registries");
            for (String key : regs.keySet())
                snapshot.put(Identifier.parse(key), ForgeRegistry.Snapshot.read(regs.getCompoundOrEmpty(key)));
            failedElements = GameData.injectSnapshot(snapshot, true, true);
        }

        if (failedElements != null && !failedElements.isEmpty()) {
            StringBuilder buf = new StringBuilder();
            buf.append("Forge Mod Loader could not load this save.\n\n")
                .append("There are ").append(failedElements.size()).append(" unassigned registry entries in this save.\n")
                .append("You will not be able to load until they are present again.\n\n");

            failedElements.asMap().forEach((name, entries) -> {
                buf.append("Missing ").append(name).append(":\n");
                entries.forEach(rl -> buf.append("    ").append(rl).append("\n"));
            });
            LOGGER.error(WORLDPERSISTENCE, buf.toString());
        }
    }

@Test
    public void nestReentrancy() throws Exception {
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());
        try {
            LocalAddress addr = new LocalAddress(ReentrantChannelTest.class);

            BlockingQueue<Object> received = new LinkedBlockingQueue<>();

            Channel server = new ServerBootstrap()
                    .group(group)
                    .channel(LocalServerChannel.class)
                    .childHandler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) throws Exception {
                            ch.config().setAutoRead(false);
                            // first handler splits input by \n and into strings
                            ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) throws Exception {
                                    String string = ((ByteBuf) msg).toString(StandardCharsets.UTF_8);
                                    ((ByteBuf) msg).release();
                                    for (String s : string.split("\n")) {
                                        ctx.fireChannelRead(s);
                                    }
                                }
                            });
                            // second handler buffers messages, sends them on in channelReadComplete, and acts as flow
                            // control
                            ch.pipeline().addLast(new ChannelDuplexHandler() {
                                final Queue<Object> queue = new ArrayDeque<>();
                                boolean demand = true;

                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                                    queue.add(msg);
                                }

                                @Override
                                public void channelReadComplete(ChannelHandlerContext ctx) {
                                    while (demand) {
                                        Object item = queue.poll();
                                        if (item == null) {
                                            break;
                                        }
                                        demand = false;
                                        ctx.fireChannelRead(item);
                                    }
                                    ctx.fireChannelReadComplete();
                                }

                                @Override
                                public void read(ChannelHandlerContext ctx) {
                                    Object item = queue.poll();
                                    if (item != null) {
                                        ctx.fireChannelRead(item);
                                    } else {
                                        demand = true;
                                        ctx.read();
                                    }
                                }

                                @Override
                                public void handlerAdded(ChannelHandlerContext ctx) {
                                    ctx.read();
                                }
                            });
                            // third handler saves incoming packets so that we can test their order
                            ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                                    received.add(msg);
                                    ctx.fireChannelRead(msg);
                                }
                            });
                            // final handler relieves backpressure, triggering reentrant channelReads
                            ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                                    ctx.read();
                                }

                                @Override
                                public void channelReadComplete(ChannelHandlerContext ctx) {
                                    ctx.read();
                                }
                            });
                        }
                    }).bind(addr).sync().channel();
            Channel client = new Bootstrap()
                    .group(group)
                    .channel(LocalChannel.class)
                    .handler(new ChannelInboundHandlerAdapter())
                    .connect(addr).sync().channel();

            client.writeAndFlush(Unpooled.copiedBuffer("A\nB\nC", StandardCharsets.UTF_8)).sync();

            // order should be unchanged
            assertEquals("A", received.take());
            assertEquals("B", received.take());
            assertEquals("C", received.take());

            client.close().sync();
            server.close().sync();
        } finally {
            group.shutdownGracefully();
        }
    }

public static void craftItemParticles(Level level, SpiritAltarBlockEntity altar, MalumNetworkedParticleEffectColorData colorData) {
        SpiritLike activeSpiritType = getCentralSpiritType(altar);
        if (activeSpiritType == null) {
            return;
        }
        long gameTime = level.getGameTime();
        var random = level.random;
        var targetPos = getItemPos(altar);

        for (int i = 0; i < 2; i++) {
            SpiritLightSpecs.coolLookingShinyThing(level, targetPos, activeSpiritType);
        }
        for (int i = 0; i < 8; i++) {
            SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
            float xOffset = Easing.CUBIC_OUT.asWeighedRandom(random, 0.1f, 0.5f) * (random.nextBoolean() ? -1 : 1);
            float yOffset = i * 0.08f;
            float zOffset = Easing.CUBIC_OUT.asWeighedRandom(random, 0.1f, 0.5f) * (random.nextBoolean() ? -1 : 1);

            var offsetPos = targetPos.add(xOffset, yOffset, zOffset);
