                    .setSpritePicker(SimpleParticleOptions.ParticleSpritePicker.WITH_AGE)
                    .setScaleData(GenericParticleData.create(0.3f).build())
                    .multiplyLifetime(1.25f)
                    .setLifeDelay(lifeDelay)
                    .disableNoClip();
            lightSpecs.getBloomBuilder()
                    .modifyScaleData(d -> d.multiplyValue(3f))
                    .modifyTransparencyData(d -> d.multiplyValue(1.25f))
                    .multiplyLifetime(0.85f)
                    .setLifeDelay(lifeDelay)
                    .disableNoClip();
            lightSpecs.spawnParticles();
        }

        for (int i = 0; i < 12; i++) {
            int lifeDelay = i / 4;
            SpiritArcanaType cyclingSpiritType = colorData.getSpirit();
            float xVelocity = Easing.CUBIC_OUT.asWeighedRandom(random, -0.075f, 0.075f);
            float yVelocity = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.2f, 0.5f);
            float zVelocity = Easing.CUBIC_OUT.asWeighedRandom(random, -0.075f, 0.075f);
            float gravityStrength = Easing.SINE_IN_OUT.asWeighedRandom(random, 0.75f, 1f);
            if (random.nextFloat() < 0.85f) {
                var sparkParticles = SparkParticleEffects.spiritMotionSparks(level, targetPos, cyclingSpiritType);
                sparkParticles.getBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(1.5f)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyScaleData(d -> d.multiplyValue(2f));
                sparkParticles.getBloomBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(1.5f)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyTransparencyData(d -> d.multiplyValue(1.25f));
                sparkParticles.spawnParticles();
            }
            if (random.nextFloat() < 0.85f) {
                xVelocity *= 1.25f;
                yVelocity *= 0.75f;
                zVelocity *= 1.25f;
                var lightSpecs = SpiritLightSpecs.spiritLightSpecs(level, targetPos, cyclingSpiritType);
                lightSpecs.getBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(2)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyScaleData(d -> d.multiplyValue(2.5f));
                lightSpecs.getBloomBuilder()
                        .disableNoClip()
                        .setLifeDelay(lifeDelay)
                        .multiplyLifetime(1.5f)
                        .setGravity(gravityStrength)
                        .setMotion(xVelocity, yVelocity, zVelocity)
                        .modifyTransparencyData(d -> d.multiplyValue(1.25f));
                lightSpecs.spawnParticles();
            }
        }
        for (int i = 0; i < 8; i++) {
            int finalI = i;
            Vec3 offsetPosition = VecHelper.rotatingRadialOffset(targetPos, 0.6f, i, 8, gameTime, 160);
            Consumer<WorldParticleBuilder> behavior = b -> b.addTickActor(p -> {
                if (level.getGameTime() > gameTime + finalI * 4 && level.getGameTime() < gameTime + (finalI + 4) * 4) {
                    p.setParticleSpeed(p.getParticleSpeed().add(0, 0.015f, 0));
                }
            });
            int lifetime = Easing.SINE_IN_OUT.asWeighedRandom(random, 10, 20) + finalI * 2;
            var lightSpecs = spiritLightSpecs(level, offsetPosition, activeSpiritType);
            lightSpecs.getBuilder()
                    .act(behavior)
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(2f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .setLifetime(lifetime);
            lightSpecs.getBloomBuilder()
                    .act(behavior)
                    .modifyColorData(d -> d.multiplyCoefficient(0.35f))
                    .modifyScaleData(d -> d.multiplyValue(1.6f).multiplyCoefficient(0.9f))
                    .modifyTransparencyData(d -> d.multiplyCoefficient(0.9f))
                    .setLifetime(lifetime);
            lightSpecs.spawnParticles();
        }
    }

@Test
    @Timeout(value = 10000, unit = TimeUnit.MILLISECONDS)
    public void testHandshakeFailureOnlyFireExceptionOnce() throws Exception {
        final SslContext sslClientCtx = SslContextBuilder.forClient()
                .trustManager(new X509ExtendedTrustManager() {
                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType, Socket socket)
                            throws CertificateException {
                        failVerification();
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType, Socket socket)
                            throws CertificateException {
                        failVerification();
                    }

                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType, SSLEngine engine)
                            throws CertificateException {
                        failVerification();
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType, SSLEngine engine)
                            throws CertificateException {
                        failVerification();
                    }

                    @Override
                    public void checkClientTrusted(X509Certificate[] chain, String authType)
                            throws CertificateException {
                        failVerification();
                    }

                    @Override
                    public void checkServerTrusted(X509Certificate[] chain, String authType)
                            throws CertificateException {
                        failVerification();
                    }

                    @Override
                    public X509Certificate[] getAcceptedIssuers() {
                        return EmptyArrays.EMPTY_X509_CERTIFICATES;
                    }

                    private void failVerification() throws CertificateException {
                        throw new CertificateException();
                    }
                })
                .sslProvider(SslProvider.JDK).build();

        final SelfSignedCertificate cert = CachedSelfSignedCertificate.getCachedCertificate();
        final SslContext sslServerCtx = SslContextBuilder.forServer(cert.key(), cert.cert())
                .sslProvider(SslProvider.JDK).build();

        EventLoopGroup group = new MultiThreadIoEventLoopGroup(NioIoHandler.newFactory());
        Channel sc = null;
        final SslHandler clientSslHandler = sslClientCtx.newHandler(UnpooledByteBufAllocator.DEFAULT);
        final SslHandler serverSslHandler = sslServerCtx.newHandler(UnpooledByteBufAllocator.DEFAULT);

        try {
            final Object terminalEvent = new Object();
            final BlockingQueue<Object> errorQueue = new LinkedBlockingQueue<Object>();
            sc = new ServerBootstrap()
                    .group(group)
                    .channel(NioServerSocketChannel.class)
                    .childHandler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) {
                            ch.pipeline().addLast(serverSslHandler);
                            ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void exceptionCaught(final ChannelHandlerContext ctx, Throwable cause) {
                                    errorQueue.add(cause);
                                }

                                @Override
                                public void channelInactive(ChannelHandlerContext ctx) {
                                    errorQueue.add(terminalEvent);
                                }
                            });
                        }
                    })
                    .bind(new InetSocketAddress(0)).syncUninterruptibly().channel();
            final ChannelFuture future = new Bootstrap()
                    .group(group)
                    .channel(NioSocketChannel.class)
                    .handler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) {
                            ch.pipeline().addLast(clientSslHandler);
                            ch.pipeline().addLast(new SilenceExceptionHandler()
                                    .rootCauseInstanceOf(CertificateException.class));
                        }
                    }).connect(sc.localAddress());
            future.syncUninterruptibly();
            clientSslHandler.handshakeFuture().addListener((FutureListener<Channel>) f -> future.channel().close());
            assertFalse(clientSslHandler.handshakeFuture().await().isSuccess());
            assertFalse(serverSslHandler.handshakeFuture().await().isSuccess());

            Object error = errorQueue.take();
            assertInstanceOf(DecoderException.class, error);
            assertInstanceOf(SSLException.class, ((Throwable) error).getCause());
            Object terminal = errorQueue.take();
            assertSame(terminalEvent, terminal);

            assertNull(errorQueue.poll(1, TimeUnit.MILLISECONDS));
        } finally {
            if (sc != null) {
                sc.close().syncUninterruptibly();
            }
            group.shutdownGracefully();
        }
    }

@Test
    public void testPromiseCorrectExecutor() throws Exception {
        final ChannelPipeline pipeline = new LocalChannel().pipeline();
        final BlockingQueue<Boolean> queue = new ArrayBlockingQueue<Boolean>(6);
        EventExecutor executor = new DefaultEventExecutor();
        try {
            pipeline.addLast(new ChannelOutboundHandlerAdapter() {
                @Override
                public void bind(ChannelHandlerContext ctx, SocketAddress localAddress, ChannelPromise promise) {
                    promise.setSuccess();
                }

                @Override
                public void connect(ChannelHandlerContext ctx, SocketAddress remoteAddress,
                                    SocketAddress localAddress, ChannelPromise promise) {
                    promise.setSuccess();
                }

                @Override
                public void disconnect(ChannelHandlerContext ctx, ChannelPromise promise) {
                    promise.setSuccess();
                }

                @Override
                public void close(ChannelHandlerContext ctx, ChannelPromise promise) {
                    promise.setSuccess();
                }

                @Override
                public void deregister(ChannelHandlerContext ctx, ChannelPromise promise) {
                    promise.setSuccess();
                }

                @Override
                public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                    promise.setSuccess();
                }
            }, new ChannelOutboundHandlerAdapter() {

                ChannelFutureListener listener;

                @Override
                public void handlerAdded(ChannelHandlerContext ctx) {
                    listener = f -> {
                        queue.add(ctx.executor().inEventLoop());
                    };
                }

                @Override
                public void bind(ChannelHandlerContext ctx, SocketAddress localAddress, ChannelPromise promise) {
                    ctx.bind(localAddress, promise.addListener(listener));
                }

                @Override
                public void connect(ChannelHandlerContext ctx, SocketAddress remoteAddress,
                                    SocketAddress localAddress, ChannelPromise promise) {
                    ctx.connect(remoteAddress, localAddress, promise.addListener(listener));
                }

                @Override
                public void disconnect(ChannelHandlerContext ctx, ChannelPromise promise) {
                    ctx.disconnect(promise.addListener(listener));
                }

                @Override
                public void close(ChannelHandlerContext ctx, ChannelPromise promise) {
                    ctx.close(promise.addListener(listener));
                }

                @Override
                public void deregister(ChannelHandlerContext ctx, ChannelPromise promise) {
                    ctx.deregister(promise.addListener(listener));
                }

                @Override
                public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
                    ctx.write(msg, promise.addListener(listener));
                }
            });
            group.register(pipeline.channel()).sync();

            ChannelPromise promise = new DefaultChannelPromise(pipeline.channel(), executor);
            pipeline.bind(new SocketAddress() { }, promise);
            promise.sync();

            promise = new DefaultChannelPromise(pipeline.channel(), executor);
            pipeline.connect(new SocketAddress() { }, promise);
            promise.sync();

            promise = new DefaultChannelPromise(pipeline.channel(), executor);
            pipeline.disconnect(promise);
            promise.sync();

            promise = new DefaultChannelPromise(pipeline.channel(), executor);
            pipeline.close(promise);
            promise.sync();

            promise = new DefaultChannelPromise(pipeline.channel(), executor);
            pipeline.deregister(promise);
            promise.sync();

            promise = new DefaultChannelPromise(pipeline.channel(), executor);
            pipeline.write("", promise);
            promise.sync();
        } finally {
            // Remove the handlers before closing so we don't intercept it.
            while (pipeline.lastContext() != null) {
                pipeline.removeLast();
            }
            pipeline.close();
            executor.shutdownGracefully();
        }

        for (int i = 0; i < 6; i++) {
            assertTrue(queue.take());
        }
    }

@Override
        public void connect(
                final SocketAddress remoteAddress, final SocketAddress localAddress, final ChannelPromise promise) {
            // Don't mark the connect promise as uncancellable as in fact we can cancel it as it is using
            // non-blocking io.
            if (promise.isDone() || !ensureOpen(promise)) {
                return;
            }

            if (delayedClose != null) {
                promise.tryFailure(annotateConnectException(new ClosedChannelException(), remoteAddress));
                return;
            }
            try {
                if (connectPromise != null) {
                    throw new ConnectionPendingException();
                }
                if (localAddress instanceof InetSocketAddress) {
                    checkResolvable((InetSocketAddress) localAddress);
                }

                if (remoteAddress instanceof InetSocketAddress) {
                    checkResolvable((InetSocketAddress) remoteAddress);
                }

                if (remote != null) {
                    // Check if already connected before trying to connect. This is needed as connect(...) will not#
                    // return -1 and set errno to EISCONN if a previous connect(...) attempt was setting errno to
                    // EINPROGRESS and finished later.
                    throw new AlreadyConnectedException();
                }

                if (localAddress != null) {
                    socket.bind(localAddress);
                }

                if (remoteAddress instanceof InetSocketAddress) {
                    InetSocketAddress inetSocketAddress = (InetSocketAddress) remoteAddress;
                    ByteBuf initialData = null;
                    if (IoUring.isTcpFastOpenClientSideAvailable() &&
                        config().getOption(ChannelOption.TCP_FASTOPEN_CONNECT) == Boolean.TRUE) {
                        ChannelOutboundBuffer outbound = unsafe().outboundBuffer();
                        outbound.addFlush();
                        Object curr;
                        if ((curr = outbound.current()) instanceof ByteBuf) {
                            initialData = (ByteBuf) curr;
                        }
                    }
                    if (initialData != null) {
                        msgHdrMemoryArray = new MsgHdrMemoryArray((short) 1);
                        MsgHdrMemory hdr = msgHdrMemoryArray.hdr(0);
                        fillTFOInitData(hdr, inetSocketAddress, initialData);

                        int fd = fd().intValue();
                        IoRegistration registration = registration();
                        short opsId = writeTracker.nextId();
                        if (opsId == 0) {
                            freeMsgHdrArray();
                            submitConnect(inetSocketAddress);
                        } else {
                            IoUringIoOps ops = IoUringIoOps.newSendmsg(fd, (byte) 0, Native.MSG_FASTOPEN,
                                    hdr.address(), opsId);
                            writeTracker.record(opsId, ops.opcode(), initialData);
                            connectId = registration.submit(ops);
                            if (connectId == 0) {
                                writeTracker.abandon(opsId, ops.opcode());
                                // Directly release the memory if submitting failed.
                                freeMsgHdrArray();
                            }
                        }
                    } else {
                        submitConnect(inetSocketAddress);
                    }
                } else if (remoteAddress instanceof DomainSocketAddress) {
                    DomainSocketAddress unixDomainSocketAddress = (DomainSocketAddress) remoteAddress;
                    submitConnect(unixDomainSocketAddress);
                } else {
                    throw new Error("Unexpected SocketAddress implementation " + className(remoteAddress));
                }

                if (connectId != 0) {
                    ioState |= CONNECT_SCHEDULED;
                }
            } catch (Throwable t) {
                closeIfClosed();
                promise.tryFailure(annotateConnectException(t, remoteAddress));
                return;
            }
            connectPromise = promise;
            requestedRemoteAddress = remoteAddress;
            // Schedule connect timeout.
            int connectTimeoutMillis = config().getConnectTimeoutMillis();
            if (connectTimeoutMillis > 0) {
                connectTimeoutFuture = eventLoop().schedule(new Runnable() {
                    @Override
                    public void run() {
                        ChannelPromise connectPromise = AbstractIoUringChannel.this.connectPromise;
                        if (connectPromise != null && !connectPromise.isDone() &&
                                connectPromise.tryFailure(new ConnectTimeoutException(
                                        "connection timed out: " + remoteAddress))) {
                            close(voidPromise());
                        }
                    }
                }, connectTimeoutMillis, TimeUnit.MILLISECONDS);
            }

            promise.addListener(new ChannelFutureListener() {
                @Override
                public void operationComplete(ChannelFuture future) {
                    // If the connect future is cancelled we also cancel the timeout and close the
                    // underlying socket.
                    if (future.isCancelled()) {
                        cancelConnectTimeoutFuture();
                        connectPromise = null;
                        close(voidPromise());
                    }
                }
            });
        }

@Override
    public void render(GuiGraphicsExtractor graphics, DeltaTracker deltaTracker) {
        if (!enabled.getAsBoolean()) return;

        List<Test> enabled = impl.tests().enabled().collect(Collectors.toCollection(ArrayList::new));
        if (enabled.isEmpty()) return;

        final Font font = Minecraft.getInstance().font;
        final int startX = 10, startY = 10;
        final int maxWidth = graphics.guiWidth() / 3;
        int x = startX, y = startY;
        int maxX = x;

        final CommitBasedList<Runnable> renderingQueue = new CommitBasedList<>(new ArrayList<>());
        final Component title = Component.literal("Tests overlay for ").append(Component.literal(impl.id().toString()).withStyle(ChatFormatting.AQUA));
        renderingQueue.addDirectly(withXY(x, y, (x$, y$) -> graphics.text(font, title, x$, y$, 0xffffffff)));
        y += font.lineHeight + 5;
        maxX += font.width(title);

        if (enabled.size() > MAX_DISPLAYED) {
            // In this case, we only render the first 5 which are NOT passed
            // But keeping the last completed ones, if present, and fading them out
            // TODO - may need to tweak this logic to only fade ONLY IF the amount of tests not passed is >= 5
            final Map<Test, Integer> lastCompleted = lastRenderedTests.stream()
                    .filter(it -> impl.tests().getStatus(it.id()).result() == Test.Result.PASSED)
                    .collect(Collectors.toMap(Function.identity(), lastRenderedTests::indexOf));

            List<Test> actuallyToRender = new ArrayList<>(MAX_DISPLAYED);
            List<Test> finalActuallyToRender = actuallyToRender;
            for (int i = 0; i < MAX_DISPLAYED; i++) actuallyToRender.add(null);
            lastCompleted.forEach((test, index) -> finalActuallyToRender.set(index, test));
            enabled.stream()
                    .filter(it -> impl.tests().getStatus(it.id()).result() != Test.Result.PASSED)
                    .limit(MAX_DISPLAYED - lastCompleted.size())
                    .forEach(it -> finalActuallyToRender.set(finalActuallyToRender.indexOf(null), it));

            int nullIndex;
            while ((nullIndex = actuallyToRender.indexOf(null)) >= 0) {
                actuallyToRender.remove(nullIndex);
            }

            for (final Test test : List.copyOf(actuallyToRender)) {
                // If we find one that isn't passed, we need to start fading it out
                renderingQueue.push();
                int lastY = y;
                int lastMaxX = maxX;
                if (impl.tests().getStatus(test.id()).result() == Test.Result.PASSED) {
                    final float fade = fading.computeIfAbsent(test, it -> 1f) - 0.005f;
                    if (fade <= 0) {
                        fading.removeFloat(test);
                        actuallyToRender.remove(test);
                        continue; // We don't need to render this one anymore, hurray!
                    }

                    final XY xy = renderTest(font, test, graphics, maxWidth, x, y, ((int) (fade * 255f) << 24) | 0xffffff, renderingQueue.currentProgress());
                    y = xy.y() + 5;
                    maxX = Math.max(maxX, xy.x());

                    fading.put(test, fade);
                } else {
                    final XY xy = renderTest(font, test, graphics, maxWidth, x, y, 0xffffffff, renderingQueue.currentProgress());
                    y = xy.y() + 5;
                    maxX = Math.max(maxX, xy.x());
                }

                if (y >= graphics.guiHeight()) {
                    int endIndex = actuallyToRender.indexOf(test) + 1;
                    // If the y is greater than the height, don't render this test at all
                    if (y > graphics.guiHeight()) {
                        endIndex--;
                        renderingQueue.revert();
                        y = lastY;
                        maxX = lastMaxX;
                    }
                    // Otherwise, break and render this test
                    else {
                        renderingQueue.popAndCommit();
                    }
                    actuallyToRender = actuallyToRender.subList(0, endIndex);
                    break;
                } else {
                    renderingQueue.popAndCommit();
                }
            }

            lastRenderedTests.clear();
            lastRenderedTests.addAll(actuallyToRender);
        } else {
            for (final Test test : enabled) {
                int lastY = y;
                int lastMaxX = maxX;
                renderingQueue.push();
                final XY xy = renderTest(font, test, graphics, maxWidth, x, y, 0xffffffff, renderingQueue.currentProgress());
                y = xy.y() + 5;
                maxX = Math.max(maxX, xy.x());

                if (y >= graphics.guiHeight()) {
                    int endIndex = enabled.indexOf(test) + 1;
                    // If the y is greater than the height, don't render this test at all
                    if (y > graphics.guiHeight()) {
                        renderingQueue.revert();
                        y = lastY;
                        maxX = lastMaxX;
                        endIndex--;
                    }
                    // Otherwise, break and render this test
                    else {
                        renderingQueue.popAndCommit();
                    }
                    enabled = enabled.subList(0, endIndex);
                    break;
                } else {
                    renderingQueue.popAndCommit();
                }
            }
            lastRenderedTests.clear();
            lastRenderedTests.addAll(enabled);
        }

        maxX += 3;

        graphics.blitSprite(RenderPipelines.GUI_TEXTURED, BG_TEXTURE, startX - 4, startY - 4, (maxX - startX) + 4 + 4, (y - startY) + 4, 0x7FFFFFFF);
        renderingQueue.forEach(Runnable::run);
    }

@Override
            public void run() {
                if (executors.length == 0 || executors[0].isShuttingDown()) {
                    // The group is shutting down, so no scaling decisions should be made.
                    // The lifecycle listener on the terminationFuture will handle the final cancellation.
                    return;
                }

                // Calculate the actual elapsed time since the last run.
                final long now = executors[0].ticker().nanoTime();
                long totalTime;

                if (lastCheckTimeNanos == 0) {
                    // On the first run, use the configured period as a baseline to avoid skipping the cycle.
                    totalTime = utilizationCheckPeriodNanos;
                } else {
                    // On subsequent runs, calculate the actual elapsed time.
                    totalTime = now - lastCheckTimeNanos;
                }

                // Always update the timestamp for the next cycle.
                lastCheckTimeNanos = now;

                if (totalTime <= 0) {
                    // Skip this cycle if the clock has issues or the interval is invalid.
                    return;
                }

                consistentlyIdleChildren.clear();
                consistentlyBusyChildren.clear();

                final AutoScalingState currentState = state.get();

                for (int i = 0; i < executors.length; i++) {
                    EventExecutor child = executors[i];
                    if (!(child instanceof SingleThreadEventExecutor)) {
                        continue;
                    }

                    SingleThreadEventExecutor eventExecutor = (SingleThreadEventExecutor) child;

                    double utilization = 0.0;
                    if (!eventExecutor.isSuspended()) {
                        long activeTime = eventExecutor.getAndResetAccumulatedActiveTimeNanos();

                        if (activeTime == 0) {
                            long lastActivity = eventExecutor.getLastActivityTimeNanos();
                            long idleTime = now - lastActivity;

                            // If the event loop has been idle for less time than our utilization window,
                            // it means it was active for the remainder of that window.
                            if (idleTime < totalTime) {
                                activeTime = totalTime - idleTime;
                            }
                            // If idleTime >= totalTime, it was idle for the whole window, so activeTime remains 0.
                        }

                        utilization = Math.min(1.0, (double) activeTime / totalTime);

                        if (utilization < scaleDownThreshold) {
                            // Utilization is low, increment idle counter and reset busy counter.
                            int idleCycles = eventExecutor.getAndIncrementIdleCycles();
                            eventExecutor.resetBusyCycles();
                            if (idleCycles >= scalingPatienceCycles &&
                                eventExecutor.getNumOfRegisteredChannels() <= 0) {
                                consistentlyIdleChildren.add(eventExecutor);
                            }
                        } else if (utilization > scaleUpThreshold) {
                            // Utilization is high, increment busy counter and reset idle counter.
                            int busyCycles = eventExecutor.getAndIncrementBusyCycles();
                            eventExecutor.resetIdleCycles();
                            if (busyCycles >= scalingPatienceCycles) {
                                consistentlyBusyChildren.add(eventExecutor);
                            }
                        } else {
                            // Utilization is in the normal range, reset counters.
                            eventExecutor.resetIdleCycles();
                            eventExecutor.resetBusyCycles();
                        }
                    }

                    utilizationMetrics.get(i).setUtilization(utilization);
                }

                int currentActive = currentState.activeChildrenCount;

                // Make scaling decisions based on stable states.
                if (!consistentlyBusyChildren.isEmpty() && currentActive < maxChildren) {
                    // Scale Up, we have children that have been busy for multiple cycles.
                    int threadsToAdd = Math.min(consistentlyBusyChildren.size(), maxRampUpStep);
                    threadsToAdd = Math.min(threadsToAdd, maxChildren - currentActive);
                    if (threadsToAdd > 0) {
                        // Reset the counters of the children that justified this decision so that they need
                        // another full patience period of sustained load before triggering a further scale-up.
                        for (SingleThreadEventExecutor busyChild : consistentlyBusyChildren) {
                            busyChild.resetBusyCycles();
                            busyChild.resetIdleCycles();
                        }
                        tryScaleUpBy(threadsToAdd);
                        // State change is handled by tryScaleUpBy, no need for rebuild here.
                        return; // Exit to avoid conflicting scale down logic in the same cycle.
                    }
                }

                boolean changed = false; // Flag to track if we need to rebuild the active executors list.
                if (!consistentlyIdleChildren.isEmpty() && currentActive > minChildren) {
                    // Scale down, we have children that have been idle for multiple cycles.

                    int threadsToRemove = Math.min(consistentlyIdleChildren.size(), maxRampDownStep);
                    threadsToRemove = Math.min(threadsToRemove, currentActive - minChildren);

                    for (int i = 0; i < threadsToRemove; i++) {
                        SingleThreadEventExecutor childToSuspend = consistentlyIdleChildren.get(i);
                        if (childToSuspend.trySuspend()) {
                            // Reset cycles upon suspension so it doesn't get immediately re-suspended on wake-up.
                            childToSuspend.resetBusyCycles();
                            childToSuspend.resetIdleCycles();
                            changed = true;
                        }
                    }
                }

                // If a scale-down occurred, or if the actual state differs from our view, rebuild.
                if (changed || currentActive != currentState.activeExecutors.length) {
                    rebuildActiveExecutors();
                }
            }

private int unwrap(ChannelHandlerContext ctx, ByteBuf packet, int length) throws SSLException {
        final int originalLength = length;
        boolean wrapLater = false;
        boolean notifyClosure = false;
        boolean executedRead = false;
        ByteBuf decodeOut = allocate(ctx, length);
        try {
            // Only continue to loop if the handler was not removed in the meantime.
            // See https://github.com/netty/netty/issues/5860
            do {
                final SSLEngineResult result = engineType.unwrap(this, packet, length, decodeOut);
                final Status status = result.getStatus();
                final HandshakeStatus handshakeStatus = result.getHandshakeStatus();
                final int produced = result.bytesProduced();
                final int consumed = result.bytesConsumed();

                // Skip bytes now in case unwrap is called in a re-entry scenario. For example LocalChannel.read()
                // may entry this method in a re-entry fashion and if the peer is writing into a shared buffer we may
                // unwrap the same data multiple times.
                packet.skipBytes(consumed);
                length -= consumed;

                // The expected sequence of events is:
                // 1. Notify of handshake success
                // 2. fireChannelRead for unwrapped data
                if (handshakeStatus == HandshakeStatus.FINISHED || handshakeStatus == HandshakeStatus.NOT_HANDSHAKING) {
                    wrapLater |= (decodeOut.isReadable() ?
                            setHandshakeSuccessUnwrapMarkReentry() : setHandshakeSuccess()) ||
                            handshakeStatus == HandshakeStatus.FINISHED ||
                            // We need to check if pendingUnecryptedWrites is null as the SslHandler
                            // might have been removed in the meantime.
                            (pendingUnencryptedWrites != null  && !pendingUnencryptedWrites.isEmpty());
                }

                // Dispatch decoded data after we have notified of handshake success. If this method has been invoked
                // in a re-entry fashion we execute a task on the executor queue to process after the stack unwinds
                // to preserve order of events.
                if (decodeOut.isReadable()) {
                    setState(STATE_FIRE_CHANNEL_READ);
                    if (isStateSet(STATE_UNWRAP_REENTRY)) {
                        executedRead = true;
                        executeChannelRead(ctx, decodeOut);
                    } else {
                        ctx.fireChannelRead(decodeOut);
                    }
                    decodeOut = null;
                }

                if (status == Status.CLOSED) {
                    notifyClosure = true; // notify about the CLOSED state of the SSLEngine. See #137
                } else if (status == Status.BUFFER_OVERFLOW) {
                    if (decodeOut != null) {
                        decodeOut.release();
                    }
                    final int applicationBufferSize = engine.getSession().getApplicationBufferSize();
                    // Allocate a new buffer which can hold all the rest data and loop again.
                    // It may happen that applicationBufferSize < produced while there is still more to unwrap, in this
                    // case we will just allocate a new buffer with the capacity of applicationBufferSize and call
                    // unwrap again.
                    decodeOut = allocate(ctx, engineType.calculatePendingData(this, applicationBufferSize < produced ?
                            applicationBufferSize : applicationBufferSize - produced));
                    continue;
                }

                if (handshakeStatus == HandshakeStatus.NEED_TASK) {
                    boolean pending = runDelegatedTasks(true);
                    if (!pending) {
                        // We scheduled a task on the delegatingTaskExecutor, so stop processing as we will
                        // resume once the task completes.
                        //
                        // We break out of the loop only and do NOT return here as we still may need to notify
                        // about the closure of the SSLEngine.
                        wrapLater = false;
                        break;
                    }
                } else if (handshakeStatus == HandshakeStatus.NEED_WRAP) {
                    // If the wrap operation transitions the status to NOT_HANDSHAKING and there is no more data to
                    // unwrap then the next call to unwrap will not produce any data. We can avoid the potentially
                    // costly unwrap operation and break out of the loop.
                    if (wrapNonAppData(ctx, true) && length == 0) {
                        break;
                    }
                }

                if (status == Status.BUFFER_UNDERFLOW ||
                        // If we processed NEED_TASK we should try again even we did not consume or produce anything.
                        handshakeStatus != HandshakeStatus.NEED_TASK && (consumed == 0 && produced == 0 ||
                                (length == 0 && handshakeStatus == HandshakeStatus.NOT_HANDSHAKING))) {
                    if (handshakeStatus == HandshakeStatus.NEED_UNWRAP) {
                        // The underlying engine is starving so we need to feed it with more data.
                        // See https://github.com/netty/netty/pull/5039
                        readIfNeeded(ctx);
                    }

                    break;
                } else if (decodeOut == null) {
                    decodeOut = allocate(ctx, length);
                }
            } while (!ctx.isRemoved());

            if (isStateSet(STATE_FLUSHED_BEFORE_HANDSHAKE) && handshakePromise.isDone()) {
                // We need to call wrap(...) in case there was a flush done before the handshake completed to ensure
                // we do not stale.
                //
                // See https://github.com/netty/netty/pull/2437
                clearState(STATE_FLUSHED_BEFORE_HANDSHAKE);
                wrapLater = true;
            }

            if (wrapLater) {
                wrap(ctx, true);
            }
        } finally {
            if (decodeOut != null) {
                decodeOut.release();
            }

            if (notifyClosure) {
                if (executedRead) {
                    executeNotifyClosePromise(ctx);
                } else {
                    notifyClosePromise(null);
                }
            }
        }
        return originalLength - length;
    }

private static void observeOutputIdle(boolean writer) throws Exception {

        long writerIdleTime = 0L;
        long allIdleTime = 0L;
        IdleStateEvent expected;

        if (writer) {
            writerIdleTime = 5L;
            expected = IdleStateEvent.FIRST_WRITER_IDLE_STATE_EVENT;
        } else {
            allIdleTime = 5L;
            expected = IdleStateEvent.FIRST_ALL_IDLE_STATE_EVENT;
        }

        IdleStateHandler idleStateHandler = new IdleStateHandler(
                true, 0L, writerIdleTime, allIdleTime, TimeUnit.SECONDS);

        final List<Object> events = new ArrayList<Object>();
        ChannelInboundHandlerAdapter handler = new ChannelInboundHandlerAdapter() {
            @Override
            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) throws Exception {
                events.add(evt);
            }
        };

        ObservableChannel channel = new ObservableChannel(idleStateHandler, handler);
        channel.freezeTime();
        try {
            // We're writing 3 messages that will be consumed at different rates!
            channel.writeAndFlush(Unpooled.wrappedBuffer(new byte[] { 1 }));
            channel.writeAndFlush(Unpooled.wrappedBuffer(new byte[] { 2 }));
            channel.writeAndFlush(Unpooled.wrappedBuffer(new byte[] { 3 }));
            channel.writeAndFlush(Unpooled.wrappedBuffer(new byte[5 * 1024]));

            // Establish a baseline. We're not consuming anything and let it idle once.
            channel.advanceTimeBy(5, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(1, events.size());
            assertSame(expected, events.get(0));
            events.clear();

            // Consume one message in 4 seconds, then be idle for 2 seconds,
            // then run the task and we shouldn't get an IdleStateEvent because
            // we haven't been idle for long enough!
            channel.advanceTimeBy(4, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consume());

            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(0, events.size());

            // Consume one message in 3 seconds, then be idle for 4 seconds,
            // then run the task and we shouldn't get an IdleStateEvent because
            // we haven't been idle for long enough!
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consume());

            channel.advanceTimeBy(4, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(0, events.size());

            // Don't consume a message and be idle for 5 seconds.
            // We should get an IdleStateEvent!
            channel.advanceTimeBy(5, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(1, events.size());
            events.clear();

            // Consume one message in 2 seconds, then be idle for 1 seconds,
            // then run the task and we shouldn't get an IdleStateEvent because
            // we haven't been idle for long enough!
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consume());

            channel.advanceTimeBy(1, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(0, events.size());

            // Consume part of the message every 2 seconds, then be idle for 1 seconds,
            // then run the task and we should get an IdleStateEvent because the first trigger
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consumePart(1024));
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consumePart(1024));
            channel.advanceTimeBy(1, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(1, events.size());
            events.clear();

            // Consume part of the message every 2 seconds, then be idle for 1 seconds,
            // then consume all the rest of the message, then run the task and we shouldn't
            // get an IdleStateEvent because the data is flowing and we haven't been idle for long enough!
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consumePart(1024));
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consumePart(1024));
            channel.advanceTimeBy(1, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(0, events.size());
            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNotNullAndRelease(channel.consumePart(1024));

            // There are no messages left! Advance the ticker by 3 seconds,
            // attempt a consume() but it will be null, then advance the
            // ticker by an another 2 seconds and we should get an IdleStateEvent
            // because we've been idle for 5 seconds.
            channel.advanceTimeBy(3, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertNull(channel.consume());

            channel.advanceTimeBy(2, TimeUnit.SECONDS);
            channel.runPendingTasks();
            assertEquals(1, events.size());

            // q.e.d.
        } finally {
            channel.finishAndReleaseAll();
        }
    }

@Override
    protected void decode(ChannelHandlerContext ctx, ByteBuf in, List<Object> out) throws Exception {
        needsRead = true;
        if (finished) {
            // Skip data received after finished.
            in.skipBytes(in.readableBytes());
            return;
        }

        int readableBytes = in.readableBytes();
        if (readableBytes == 0) {
            return;
        }

        if (decideZlibOrNone) {
            // First two bytes are needed to decide if it's a ZLIB stream.
            if (readableBytes < 2) {
                return;
            }

            boolean nowrap = !looksLikeZlib(in.getShort(in.readerIndex()));
            inflater = new Inflater(nowrap);
            decideZlibOrNone = false;
        }

        if (crc != null) {
            if (gzipState != GzipState.HEADER_END) {
                if (gzipState == GzipState.FOOTER_START) {
                    if (!handleGzipFooter(in)) {
                        // Either there was not enough data or the input is finished.
                        return;
                    }
                    // If we consumed the footer we will start with the header again.
                    assert gzipState == GzipState.HEADER_START;
                }
                if (!readGZIPHeader(in)) {
                    // There was not enough data readable to read the GZIP header.
                    return;
                }
                // Some bytes may have been consumed, and so we must re-set the number of readable bytes.
                readableBytes = in.readableBytes();
                if (readableBytes == 0) {
                    return;
                }
            }
        }

        if (inflater.needsInput()) {
            if (in.hasArray()) {
                inflater.setInput(in.array(), in.arrayOffset() + in.readerIndex(), readableBytes);
            } else {
                byte[] array = new byte[readableBytes];
                in.getBytes(in.readerIndex(), array);
                inflater.setInput(array);
            }
        }

        ByteBuf decompressed = prepareDecompressBuffer(ctx, null, preferredOutputBufferSize());
        try {
            boolean readFooter = false;
            // If this is true the last inflate(...) filled the output buffer completely, so the inflater may still
            // hold decoded data even once all input bytes were consumed. needsInput() only tells us that the input
            // was consumed, not that all output was produced, so on its own it would end the loop too early and
            // the pending bytes would be dropped together with the input we skip below.
            boolean pendingOutput = false;
            while (pendingOutput || !inflater.needsInput()) {
                byte[] outArray = decompressed.array();
                int writerIndex = decompressed.writerIndex();
                int outIndex = decompressed.arrayOffset() + writerIndex;
                int writable = decompressed.writableBytes();
                int outputLength = inflater.inflate(outArray, outIndex, writable);
                pendingOutput = outputLength == writable;
                if (outputLength > 0) {
                    decompressed.writerIndex(writerIndex + outputLength);
                    if (crc != null) {
                        crc.update(outArray, outIndex, outputLength);
                    }
                    if (maxAllocation == 0 && decompressed.readableBytes() >= maxForwardBytes) {
                        // Forward the buffer once it exceeds the threshold to bound memory
                        // while avoiding excessive fireChannelRead calls.
                        ByteBuf buffer = decompressed;
                        decompressed = null;
                        needsRead = false;
                        ctx.fireChannelRead(buffer);
                    }
                } else if (inflater.needsDictionary()) {
                    if (dictionary == null) {
                        throw new DecompressionException(
                                "decompression failure, unable to set dictionary as non was specified");
                    }
                    try {
                        inflater.setDictionary(dictionary);
                    } catch (IllegalArgumentException e) {
                        // The dictionary ID in the stream header does not match the configured dictionary.
                        throw new DecompressionException("decompression failure, dictionary mismatch", e);
                    }
                }

                if (inflater.finished()) {
                    if (crc == null) {
                        finished = true; // Do not decode anymore.
                    } else {
                        readFooter = true;
                    }
                    break;
                } else {
                    decompressed = prepareDecompressBuffer(ctx, decompressed, preferredOutputBufferSize());
                }
            }

            in.skipBytes(readableBytes - inflater.getRemaining());

            if (readFooter) {
                gzipState = GzipState.FOOTER_START;
                handleGzipFooter(in);
            }
        } catch (DataFormatException e) {
            throw new DecompressionException("decompression failure", e);
        } finally {
            if (decompressed != null) {
                if (decompressed.isReadable()) {
                    needsRead = false;
                    ctx.fireChannelRead(decompressed);
                } else {
                    decompressed.release();
                }
            }
        }
    }

private void doFlush0(final ChannelHandlerContext ctx) {
        final Channel channel = ctx.channel();
        if (!channel.isActive()) {
            // Even after discarding all previous queued objects we should propagate the flush through
            // to ensure previous written objects via writeAndFlush(...) that were not queued will be flushed and
            // so eventually fail the promise.
            discard(null);
            ctx.flush();
            return;
        }

        if (queueIsEmpty()) {
            ctx.flush();
            return;
        }

        boolean requiresFlush = true;
        ByteBufAllocator allocator = ctx.alloc();
        while (channel.isWritable()) {
            final PendingWrite currentWrite = queue.peek();

            if (currentWrite == null) {
                break;
            }

            if (currentWrite.promise.isDone()) {
                // This might happen e.g. in the case when a write operation
                // failed, but there are still unconsumed chunks left.
                // Most chunked input sources would stop generating chunks
                // and report end of input, but this doesn't work with any
                // source wrapped in HttpChunkedInput.
                // Note, that we're not trying to release the message/chunks
                // as this had to be done already by someone who resolved the
                // promise (using ChunkedInput.close method).
                // See https://github.com/netty/netty/issues/8700.
                // A promise that was cancelled by the user is different: nobody closed or released the message.
                queue.remove();
                if (currentWrite.promise.isCancelled()) {
                    if (currentWrite.msg instanceof ChunkedInput) {
                        closeInput((ChunkedInput<?>) currentWrite.msg);
                    } else {
                        ReferenceCountUtil.release(currentWrite.msg);
                    }
                }
                continue;
            }

            final Object pendingMessage = currentWrite.msg;

            if (pendingMessage instanceof ChunkedInput) {
                final ChunkedInput<?> chunks = (ChunkedInput<?>) pendingMessage;
                boolean endOfInput;
                boolean suspend;
                Object message = null;
                try {
                    message = chunks.readChunk(allocator);
                    endOfInput = chunks.isEndOfInput();
                    // No need to suspend when reached at the end.
                    suspend = message == null && !endOfInput;

                } catch (final Throwable t) {
                    queue.remove();

                    if (message != null) {
                        ReferenceCountUtil.release(message);
                    }

                    closeInput(chunks);
                    currentWrite.fail(t);
                    break;
                }

                if (suspend) {
                    // ChunkedInput.nextChunk() returned null and it has
                    // not reached at the end of input. Let's wait until
                    // more chunks arrive. Nothing to write or notify.
                    break;
                }

                if (message == null) {
                    // If message is null write an empty ByteBuf.
                    // See https://github.com/netty/netty/issues/1671
                    message = Unpooled.EMPTY_BUFFER;
                }

                if (endOfInput) {
                    // We need to remove the element from the queue before we call writeAndFlush() as this operation
                    // may cause an action that also touches the queue.
                    queue.remove();
                }
                // Flush each chunk to conserve memory
                ChannelFuture f = ctx.writeAndFlush(message);
                if (endOfInput) {
                    if (f.isDone()) {
                        handleEndOfInputFuture(f, chunks, currentWrite);
                    } else {
                        // Register a listener which will close the input once the write is complete.
                        // This is needed because the Chunk may have some resource bound that can not
                        // be closed before it's not written.
                        //
                        // See https://github.com/netty/netty/issues/303
                        f.addListener((ChannelFutureListener) future ->
                                handleEndOfInputFuture(future, chunks, currentWrite));
                    }
                } else {
                    final boolean resume = !channel.isWritable();
                    if (f.isDone()) {
                        handleFuture(f, chunks, currentWrite, resume);
                    } else {
                        f.addListener((ChannelFutureListener) future ->
                                handleFuture(future, chunks, currentWrite, resume));
                    }
                }
                requiresFlush = false;
            } else {
                queue.remove();
                ctx.write(pendingMessage, currentWrite.promise);
                requiresFlush = true;
            }

            if (!channel.isActive()) {
                discard(new ClosedChannelException());
                break;
            }
        }

        if (requiresFlush) {
            ctx.flush();
        }
    }

@Override
	public void runTest(ClientGameTestContext context) {
		Properties serverProps = new Properties();
		serverProps.setProperty("gamemode", "creative");

		try (TestDedicatedServerContext serverContext = context.worldBuilder().createServer(serverProps)) {
			var state = new Object() {
				BlockPos furnacePos;
				UUID villagerId;
			};

			context.runOnClient(client -> {
				// set client render distance before the server sets it
				client.options.renderDistance().set(5);
			});

			LOGGER.info("Setting up synced attachments before join");
			// setup before player joins
			serverContext.runOnServer(server -> {
				ServerLevel level = server.overworld();
				BlockPos top = level.getHeightmapPos(Heightmap.Types.MOTION_BLOCKING_NO_LEAVES, BlockPos.ZERO);
				state.furnacePos = top;

				level.setBlockAndUpdate(top, Blocks.FURNACE.defaultBlockState());
				setSyncedWithAll(level.getBlockEntity(top, BlockEntityTypes.FURNACE).orElseThrow());

				var villager = new Villager(EntityTypes.VILLAGER, level);
				villager.setNoAi(true);
				villager.setPermanentlyInvulnerable(true);
				villager.setCustomName(Component.literal("TestVillager"));
				state.villagerId = villager.getUUID();
				level.addFreshEntity(villager);
				setSyncedWithAll(villager);
				set(villager, AttachmentTestMod.SYNCED_WITH_TARGET);
				villager.setAttached(AttachmentTestMod.SYNCED_LARGE, AttachmentTestMod.LARGE_DATA);
				villager.setAttached(AttachmentTestMod.SYNCED_ITEM, new ItemStack(Items.EGG));

				LevelChunk originChunk = level.getChunk(0, 0);
				setSyncedWithAll(originChunk);

				ServerLevel nether = server.getLevel(Level.NETHER);
				setSyncedWithAll(Objects.requireNonNull(nether));

				setSyncedWithAll(server.globalAttachments());
			});

			LOGGER.info("Joining dedicated server");

			try (TestDedicatedServerConnection connection = serverContext.connect()) {
				connection.waitForChunksDownload();

				LOGGER.info("Setting up rest of synced attachments");
				serverContext.runOnServer(server -> {
					ServerPlayer player = connection.getServerPlayer();
					setSyncedWithAll(player);
					set(player, AttachmentTestMod.SYNCED_EXCEPT_TARGET);
					set(player, AttachmentTestMod.SYNCED_CREATIVE_ONLY);

					// check registry objects are synced correctly
					player.setAttached(AttachmentTestMod.SYNCED_ITEM, Items.APPLE.getDefaultInstance());

					// check that the client changes the render distance as requested
					player.setAttached(AttachmentTestMod.SYNCED_RENDER_DISTANCE, 8);

					// check that block entity deferred syncing works correctly
					set(server.overworld().getBlockEntity(state.furnacePos), AttachmentTestMod.SYNCED_EXCEPT_TARGET);
				});

				connection.waitForClientboundPackets();

				LOGGER.info("Testing synced attachments (1/2)");
				context.runOnClient(client -> {
					ClientLevel level = connection.getClientLevel();
					Entity villager = level.getEntity(state.villagerId);
					BlockEntity furnace = level.getBlockEntity(state.furnacePos);

					assertHasSyncedWithAll(furnace);
					assertHasSyncedWithAll(villager);
					assertHasSyncedWithAll(level.getChunk(0, 0));
					assertHasSyncedWithAll(client.player);
					assertHasSyncedWithAll(level.globalAttachments());
					assertHasSynced(client.player, AttachmentTestMod.SYNCED_CREATIVE_ONLY);
					assertHasSynced(client.player, AttachmentTestMod.SYNCED_ITEM);
					assertHasSynced(villager, AttachmentTestMod.SYNCED_LARGE);
					assertHasSynced(furnace, AttachmentTestMod.SYNCED_EXCEPT_TARGET);

					// `level` is the overworld here
					assertHasNotSynced(level, AttachmentTestMod.SYNCED_WITH_ALL);
					assertHasNotSynced(client.player, AttachmentTestMod.SYNCED_EXCEPT_TARGET);
					assertHasNotSynced(villager, AttachmentTestMod.SYNCED_WITH_TARGET);

					if (client.options.renderDistance().get() != 8) {
						throw new AssertionError("Client did not set render distance to server requested synced attachment.");
					}

					// reset view distance
					client.options.renderDistance().set(12);
				});

				// Test modifying attachments using the data command, and that the changes are synced to the client.
				serverContext.runCommand("data modify entity @n[name=\"TestVillager\"] \"fabric:attachments\".\"fabric-data-attachment-api-v1-testmod:synced_item\".id set value \"minecraft:diamond\"");
				connection.waitForClientboundPackets();
				context.runOnClient(client -> {
					ClientLevel level = connection.getClientLevel();
					Entity villager = level.getEntity(state.villagerId);
					ItemStack syncedItem = villager.getAttached(AttachmentTestMod.SYNCED_ITEM);

					if (syncedItem.getItem() != Items.DIAMOND) {
						throw new AssertionError("Unexpected synced item: %s".formatted(syncedItem.getItem()));
					}
				});

				LOGGER.info("Setting up second phase");
				// now teleport to nether, on roof to avoid suffocation when switching to survival
				serverContext.runCommand("execute in minecraft:the_nether run tp @p ~ 128 ~");
				serverContext.runCommand("gamemode survival @p");
				serverContext.runOnServer(server -> connection.getServerPlayer().removeAttached(AttachmentTestMod.SYNCED_CREATIVE_ONLY));

				connection.waitForClientboundPackets();

				LOGGER.info("Testing synced attachments (2/2)");
				context.runOnClient(client -> {
					assertHasSyncedWithAll(client.level);
					assertHasSyncedWithAll(client.level.globalAttachments());
					// asserts the removal wasn't synced
					assertPresence(client.player, AttachmentTestMod.SYNCED_CREATIVE_ONLY, true);
				});

				LOGGER.info("Done");
			}
		}
	}

@Override
    protected void encode(ChannelHandlerContext ctx, HttpObject msg, List<Object> out) throws Exception {
        final boolean isFull = msg instanceof HttpResponse && msg instanceof LastHttpContent;
        switch (state) {
            case AWAIT_HEADERS: {
                ensureHeaders(msg);
                assert encoder == null;

                final HttpResponse res = (HttpResponse) msg;
                final int code = res.status().code();
                final HttpStatusClass codeClass = res.status().codeClass();
                final CharSequence acceptEncoding;
                if (codeClass == HttpStatusClass.INFORMATIONAL) {
                    // We need to not poll the encoding when response with 1xx codes as another response will follow
                    // for the issued request.
                    // See https://github.com/netty/netty/issues/12904 and https://github.com/netty/netty/issues/4079
                    acceptEncoding = null;
                } else {
                    // Get the list of encodings accepted by the peer.
                    acceptEncoding = acceptEncodingQueue.poll();
                    if (acceptEncoding == null) {
                        throw new IllegalStateException("cannot send more responses than requests");
                    }
                }

                /*
                 * per rfc2616 4.3 Message Body
                 * All 1xx (informational), 204 (no content), and 304 (not modified) responses MUST NOT include a
                 * message-body. All other responses do include a message-body, although it MAY be of zero length.
                 *
                 * 9.4 HEAD
                 * The HEAD method is identical to GET except that the server MUST NOT return a message-body
                 * in the response.
                 *
                 * Also we should pass through HTTP/1.0 as transfer-encoding: chunked is not supported.
                 *
                 * See https://github.com/netty/netty/issues/5382
                 */
                if (isPassthru(res.protocolVersion(), code, acceptEncoding)) {
                    out.add(ReferenceCountUtil.retain(res));
                    if (!isFull) {
                        // Pass through all following contents.
                        state = State.PASS_THROUGH;
                    }
                    break;
                }

                if (isFull) {
                    // Pass through the full response with empty content and continue waiting for the next resp.
                    if (!((ByteBufHolder) res).content().isReadable()) {
                        out.add(ReferenceCountUtil.retain(res));
                        break;
                    }
                }

                // Prepare to encode the content.
                final Result result = beginEncode(res, acceptEncoding.toString());

                // If unable to encode, pass through.
                if (result == null) {
                    out.add(ReferenceCountUtil.retain(res));
                    if (!isFull) {
                        // Pass through all following contents.
                        state = State.PASS_THROUGH;
                    }
                    break;
                }

                EmbeddedChannel contentEncoder = result.contentEncoder();
                try {
                    // Encode the content and remove or replace the existing headers
                    // so that the message looks like a decoded message.
                    res.headers().set(HttpHeaderNames.CONTENT_ENCODING, result.targetContentEncoding());

                    // Output the rewritten response.
                    if (isFull) {
                        // Convert full message into unfull one.
                        HttpResponse newRes = new DefaultHttpResponse(res.protocolVersion(), res.status());
                        newRes.headers().set(res.headers());
                        out.add(newRes);

                        ensureContent(res);
                        encoder = contentEncoder;
                        encodeFullResponse(newRes, (HttpContent) res, out);
                        contentEncoder = null;
                        break;
                    } else {
                        // Make the response chunked to simplify content transformation.
                        res.headers().remove(HttpHeaderNames.CONTENT_LENGTH);
                        res.headers().set(HttpHeaderNames.TRANSFER_ENCODING, HttpHeaderValues.CHUNKED);

                        out.add(ReferenceCountUtil.retain(res));
                        state = State.AWAIT_CONTENT;
                        encoder = contentEncoder;
                        contentEncoder = null;
                        if (!(msg instanceof HttpContent)) {
                            // only break out the switch statement if we have not content to process
                            // See https://github.com/netty/netty/issues/2006
                            break;
                        }
                        // Fall through to encode the content
                    }
                } finally {
                    if (contentEncoder != null) {
                        if (encoder == contentEncoder) {
                            encoder = null;
                        }
                        contentEncoder.finishAndReleaseAll();
                    }
                }
            }
            case AWAIT_CONTENT: {
                ensureContent(msg);
                if (encodeContent((HttpContent) msg, out)) {
                    state = State.AWAIT_HEADERS;
                } else if (out.isEmpty()) {
                    // MessageToMessageCodec needs at least one output message
                    out.add(new DefaultHttpContent(Unpooled.EMPTY_BUFFER));
                }
                break;
            }
            case PASS_THROUGH: {
                ensureContent(msg);
                out.add(ReferenceCountUtil.retain(msg));
                // Passed through all following contents of the current response.
                if (msg instanceof LastHttpContent) {
                    state = State.AWAIT_HEADERS;
                }
                break;
            }
        }
    }

public static void main(String[] args) throws Exception {

        String transport = "nio";
        boolean ssl = false;
        SslProvider sslProvider = SslProvider.JDK;
        boolean http3 = false;

        Integer port = null;
        for (int i = 0; i < args.length; i++) {
            if (args[i].equals("--help")) {
                System.out.println("usage: [options]");
                System.out.println("--ssl");
                System.out.println("--ssl-provider [ JDK | OPENSSL ]");
                System.out.println("--port <port>");
                System.out.println("--transport [ nio | kqueue | epoll | io_uring ]");
                System.out.println("--http3");
                System.exit(0);
            }
            if (args[i].equals("--ssl")) {
                ssl = true;
            }
            if (args[i].equals("--ssl-provider")) {
                if (i < args.length - 1) {
                    sslProvider = SslProvider.valueOf(args[++i]);
                } else {
                    System.exit(1);
                }
            }
            if (args[i].equals("--port")) {
                if (i < args.length - 1) {
                    port = Integer.parseInt(args[++i]);
                } else {
                    System.exit(1);
                }
            }
            if (args[i].equals("--transport")) {
                if (i < args.length - 1) {
                    transport = args[++i];
                } else {
                    System.exit(1);
                }
            }
            if (args[i].equals("--http3")) {
                http3 = true;
            }
        }

        if (port == null) {
            port = ssl ? 8443 : 8080;
        }

        IoHandlerFactory ioHandlerFactory;
        Class<? extends ServerSocketChannel> serverSocketChannelFactory;
        switch (transport) {
            case "nio":
                ioHandlerFactory = NioIoHandler.newFactory();
                serverSocketChannelFactory = NioServerSocketChannel.class;
                break;
            case "kqueue":
                ioHandlerFactory = KQueueIoHandler.newFactory();
                serverSocketChannelFactory = KQueueServerSocketChannel.class;
                break;
            case "epoll":
                ioHandlerFactory = EpollIoHandler.newFactory();
                serverSocketChannelFactory = EpollServerSocketChannel.class;
                break;
            case "io_uring":
                ioHandlerFactory = IoUringIoHandler.newFactory();
                serverSocketChannelFactory = IoUringServerSocketChannel.class;
                break;
            default:
                System.exit(1);
                return;
        }

        X509Bundle cert = new CertificateBuilder()
                .subject("cn=localhost")
                .setIsCertificateAuthority(true)
                .buildSelfSigned();

        // Configure the server.
        EventLoopGroup group = new MultiThreadIoEventLoopGroup(ioHandlerFactory);
        try {
            Channel ch;
            if (http3) {
                QuicSslContext quicCslContext = QuicSslContextBuilder.forServer(cert.toKeyManagerFactory(), null)
                        .applicationProtocols(Http3.supportedApplicationProtocols()).build();
                ChannelHandler codec = Http3.newQuicServerCodecBuilder()
                        .sslContext(quicCslContext)
                        .maxIdleTimeout(5000, TimeUnit.MILLISECONDS)
                        .initialMaxData(10000000)
                        .initialMaxStreamDataBidirectionalLocal(1000000)
                        .initialMaxStreamDataBidirectionalRemote(1000000)
                        .initialMaxStreamsBidirectional(100)
                        .tokenHandler(InsecureQuicTokenHandler.INSTANCE)
                        .handler(new Http3HelloWorldServerInitializer())
                        .build();

                Bootstrap bs = new Bootstrap();
                ch = bs.group(group)
                        .channel(NioDatagramChannel.class)
                        .handler(codec)
                        .bind(new InetSocketAddress(port)).sync().channel();
            } else {
                SslContext sslContext;
                if (ssl) {
                    sslContext = forServer(cert.toKeyManagerFactory())
                            .sslProvider(sslProvider)
                            .protocols("TLSv1.2")
                            .trustManager(InsecureTrustManagerFactory.INSTANCE)
                            .ciphers(null, IdentityCipherSuiteFilter.INSTANCE)
                            .sessionCacheSize(0)
                            .sessionTimeout(0)
                            .build();
                } else {
                    sslContext = null;
                }
                ServerBootstrap b = new ServerBootstrap();
                b.option(ChannelOption.SO_BACKLOG, 1024);
                b.group(group)
                        .channel(serverSocketChannelFactory)
                        .handler(new LoggingHandler(LogLevel.INFO))
                        .childHandler(new HttpHelloWorldServerInitializer(sslContext));

                ch = b.bind(port).sync().channel();
            }

            System.err.println("Open your web browser and navigate to " +
                    ((ssl || http3)? "https" : "http") + "://127.0.0.1:" + port + '/');

            ch.closeFuture().sync();
        } finally {
            group.shutdownGracefully();
        }
    }

@Override
            public void run() {
                processingLock.lock();
                assert thread == null;
                thread = Thread.currentThread();
                if (interrupted) {
                    thread.interrupt();
                    interrupted = false;
                }
                boolean success = false;
                Throwable unexpectedException = null;
                updateLastExecutionTime();
                boolean suspend = false;
                try {
                    for (;;) {
                        SingleThreadEventExecutor.this.run();
                        success = true;

                        int currentState = state;
                        if (canSuspend(currentState)) {
                            // currentState might already be ST_SUSPENDED here (we can loop back around with the
                            // state still ST_SUSPENDED via the ST_SUSPENDING/ST_SUSPENDED branch below), so we must
                            // CAS from currentState and not hardcode ST_SUSPENDING as the expected value, or the CAS
                            // would spuriously "fail" forever and livelock this thread instead of finishing suspend.
                            if (!STATE_UPDATER.compareAndSet(SingleThreadEventExecutor.this,
                                    currentState, ST_SUSPENDED)) {
                                // Try again as the CAS failed.
                                continue;
                            }

                            if (!canSuspend(ST_SUSPENDED) && STATE_UPDATER.compareAndSet(SingleThreadEventExecutor.this,
                                        ST_SUSPENDED, ST_STARTED)) {
                                // Seems like there was something added to the task queue again in the meantime but we
                                // were able to re-engage this thread as the event loop thread.
                                continue;
                            }
                            suspend = true;
                        } else if (currentState == ST_SUSPENDING || currentState == ST_SUSPENDED) {
                            // We were trying to suspend (or just did) but something raced in - e.g. a scheduled
                            // task being cancelled and re-submitted itself for removal via scheduleRemoveScheduled()
                            // - so we can no longer suspend right now. No shutdown was requested, so this must not
                            // be treated as if run() returned without confirming shutdown; just go around the loop
                            // again so run() can pick up whatever raced in.
                            continue;
                        }
                        break;
                    }
                } catch (Throwable t) {
                    unexpectedException = t;
                    logger.warn("Unexpected exception from an event executor: ", t);
                } finally {
                    boolean shutdown = !suspend;
                    if (shutdown) {
                        for (;;) {
                            // We are re-fetching the state as it might have been shutdown in the meantime.
                            int oldState = state;
                            if (oldState >= ST_SHUTTING_DOWN || STATE_UPDATER.compareAndSet(
                                    SingleThreadEventExecutor.this, oldState, ST_SHUTTING_DOWN)) {
                                break;
                            }
                        }
                        if (success && gracefulShutdownStartTime == 0) {
                            // Check if confirmShutdown() was called at the end of the loop.
                            if (logger.isErrorEnabled()) {
                                logger.error("Buggy " + EventExecutor.class.getSimpleName() + " implementation; " +
                                        SingleThreadEventExecutor.class.getSimpleName() + ".confirmShutdown() must " +
                                        "be called before run() implementation terminates.");
                            }
                        }
                    }

                    try {
                        if (shutdown) {
                            // Run all remaining tasks and shutdown hooks. At this point the event loop
                            // is in ST_SHUTTING_DOWN state still accepting tasks which is needed for
                            // graceful shutdown with quietPeriod.
                            for (;;) {
                                if (confirmShutdown()) {
                                    break;
                                }
                            }

                            // Now we want to make sure no more tasks can be added from this point. This is
                            // achieved by switching the state. Any new tasks beyond this point will be rejected.
                            for (;;) {
                                int currentState = state;
                                if (currentState >= ST_SHUTDOWN || STATE_UPDATER.compareAndSet(
                                        SingleThreadEventExecutor.this, currentState, ST_SHUTDOWN)) {
                                    break;
                                }
                            }

                            // We have the final set of tasks in the queue now, no more can be added, run all remaining.
                            // No need to loop here, this is the final pass.
                            confirmShutdown();
                        }
                    } finally {
                        try {
                            if (shutdown) {
                                try {
                                    cleanup();
                                } finally {
                                    // Lets remove all FastThreadLocals for the Thread as we are about to terminate and
                                    // notify the future. The user may block on the future and once it unblocks the JVM
                                    // may terminate and start unloading classes.
                                    // See https://github.com/netty/netty/issues/6596.
                                    FastThreadLocal.removeAll();

                                    STATE_UPDATER.set(SingleThreadEventExecutor.this, ST_TERMINATED);
                                    threadLock.countDown();
                                    int numUserTasks = drainTasks();
                                    if (numUserTasks > 0 && logger.isWarnEnabled()) {
                                        logger.warn("An event executor terminated with " +
                                                "non-empty task queue (" + numUserTasks + ')');
                                    }
                                    if (unexpectedException == null) {
                                        terminationFuture.setSuccess(null);
                                    } else {
                                        terminationFuture.setFailure(unexpectedException);
                                    }
                                }
                            } else {
                                // Lets remove all FastThreadLocals for the Thread as we are about to terminate it.
                                FastThreadLocal.removeAll();

                                // Reset the stored threadProperties in case of suspension.
                                threadProperties = null;
                            }
                        } finally {
                            thread = null;
                            // Let the next thread take over if needed.
                            processingLock.unlock();
                        }
                    }
                }
            }

private void wrap(ChannelHandlerContext ctx, boolean inUnwrap) throws SSLException {
        ByteBuf out = null;
        ByteBufAllocator alloc = ctx.alloc();
        try {
            final int wrapDataSize = this.wrapDataSize;
            // Only continue to loop if the handler was not removed in the meantime.
            // See https://github.com/netty/netty/issues/5860
            outer: while (!ctx.isRemoved() && !pendingUnencryptedWrites.isEmpty()) {
                ChannelPromise promise = ctx.newPromise();
                ByteBuf buf = wrapDataSize > 0 ?
                        pendingUnencryptedWrites.remove(alloc, wrapDataSize, promise) :
                        pendingUnencryptedWrites.removeFirst(promise);
                if (buf == null) {
                    break;
                }

                SSLEngineResult result;

                try {
                    if (buf.readableBytes() > MAX_PLAINTEXT_LENGTH) {
                        // If we pulled a buffer larger than the supported packet size, we can slice it up and
                        // iteratively, encrypting multiple packets into a single larger buffer. This substantially
                        // saves on allocations for large responses. Here we estimate how large of a buffer we need.
                        // If we overestimate a bit, that's fine. If we underestimate, we'll simply re-enqueue the
                        // remaining buffer and get it on the next outer loop.
                        int readableBytes = buf.readableBytes();
                        int numPackets = readableBytes / MAX_PLAINTEXT_LENGTH;
                        if (readableBytes % MAX_PLAINTEXT_LENGTH != 0) {
                            numPackets += 1;
                        }

                        if (out == null) {
                            out = allocateOutNetBuf(ctx, readableBytes, buf.nioBufferCount() + numPackets);
                        }
                        result = wrapMultiple(alloc, engine, buf, out);
                    } else {
                        if (out == null) {
                            out = allocateOutNetBuf(ctx, buf.readableBytes(), buf.nioBufferCount());
                        }
                        result = wrap(alloc, engine, buf, out);
                    }
                } catch (Throwable e) {
                    // Either wrapMultiple(...), wrap(...) or allocateOutNetBuf(...) did throw.
                    // In this case we need to release the buffer that we removed from pendingUnencryptedWrites
                    // before failing the promise and rethrowing it. Failing to do so would result in a buffer leak.
                    // See https://github.com/netty/netty/issues/14644
                    //
                    // We don't need to release out here as this is done in a finally block already.
                    buf.release();
                    promise.setFailure(e);
                    throw e;
                }

                if (buf.isReadable()) {
                    pendingUnencryptedWrites.addFirst(buf, promise);
                    // When we add the buffer/promise pair back we need to be sure we don't complete the promise
                    // later. We only complete the promise if the buffer is completely consumed.
                    promise = null;
                } else {
                    buf.release();
                }

                // We need to write any data before we invoke any methods which may trigger re-entry, otherwise
                // writes may occur out of order and TLS sequencing may be off (e.g. SSLV3_ALERT_BAD_RECORD_MAC).
                if (out.isReadable()) {
                    final ByteBuf b = out;
                    out = null;
                    if (promise != null) {
                        ctx.write(b, promise);
                    } else {
                        ctx.write(b);
                    }
                } else if (promise != null) {
                    ctx.write(Unpooled.EMPTY_BUFFER, promise);
                }
                // else out is not readable we can re-use it and so save an extra allocation

                if (result.getStatus() == Status.CLOSED) {
                    // First check if there is any write left that needs to be failed, if there is none we don't need
                    // to create a new exception or obtain an existing one.
                    if (!pendingUnencryptedWrites.isEmpty()) {
                        // Make a best effort to preserve any exception that way previously encountered from the
                        // handshake or the transport, else fallback to a general error.
                        Throwable exception = handshakePromise.cause();
                        if (exception == null) {
                            exception = sslClosePromise.cause();
                            if (exception == null) {
                                exception = new SslClosedEngineException("SSLEngine closed already");
                            }
                        }
                        pendingUnencryptedWrites.releaseAndFailAll(ctx, exception);
                    }

                    return;
                } else {
                    switch (result.getHandshakeStatus()) {
                        case NEED_TASK:
                            if (!runDelegatedTasks(inUnwrap)) {
                                // We scheduled a task on the delegatingTaskExecutor, so stop processing as we will
                                // resume once the task completes.
                                break outer;
                            }
                            break;
                        case FINISHED:
                        case NOT_HANDSHAKING: // work around for android bug that skips the FINISHED state.
                            setHandshakeSuccess();
                            break;
                        case NEED_WRAP:
                            // If we are expected to wrap again and we produced some data we need to ensure there
                            // is something in the queue to process as otherwise we will not try again before there
                            // was more added. Failing to do so may fail to produce an alert that can be
                            // consumed by the remote peer.
                            if (result.bytesProduced() > 0 && pendingUnencryptedWrites.isEmpty()) {
                                pendingUnencryptedWrites.add(Unpooled.EMPTY_BUFFER);
                            }
                            break;
                        case NEED_UNWRAP:
                            // The underlying engine is starving so we need to feed it with more data.
                            // See https://github.com/netty/netty/pull/5039
                            readIfNeeded(ctx);
                            return;
                        default:
                            throw new IllegalStateException(
                                    "Unknown handshake status: " + result.getHandshakeStatus());
                    }
                }
            }
        } finally {
            if (out != null) {
                out.release();
            }
            if (inUnwrap) {
                setState(STATE_NEEDS_FLUSH);
            }
        }
    }

