private void testSslCompletionEvents(SslProvider provider, final String protocol, boolean clientClose)
            throws Exception {
        final SslContext sslClientCtx = SslContextBuilder.forClient()
                .trustManager(InsecureTrustManagerFactory.INSTANCE)
                .protocols(protocol)
                .sslProvider(provider).build();

        final SelfSignedCertificate cert = CachedSelfSignedCertificate.getCachedCertificate();
        final SslContext sslServerCtx = SslContextBuilder.forServer(cert.key(), cert.cert())
                .protocols(protocol)
                .sslProvider(provider).build();

        EventLoopGroup group = new MultiThreadIoEventLoopGroup(NioIoHandler.newFactory());

        final LinkedBlockingQueue<Channel> acceptedChannels =
                new LinkedBlockingQueue<Channel>();

        final LinkedBlockingQueue<SslHandshakeCompletionEvent> serverHandshakeCompletionEvents =
                new LinkedBlockingQueue<SslHandshakeCompletionEvent>();

        final LinkedBlockingQueue<SslHandshakeCompletionEvent> clientHandshakeCompletionEvents =
                new LinkedBlockingQueue<SslHandshakeCompletionEvent>();

        final LinkedBlockingQueue<SslCloseCompletionEvent> serverCloseCompletionEvents =
                new LinkedBlockingQueue<SslCloseCompletionEvent>();

        final LinkedBlockingQueue<SslCloseCompletionEvent> clientCloseCompletionEvents =
                new LinkedBlockingQueue<SslCloseCompletionEvent>();
        try {
            Channel sc = new ServerBootstrap()
                    .group(group)
                    .channel(NioServerSocketChannel.class)
                    .childHandler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) {
                            acceptedChannels.add(ch);
                            SslHandler handler = sslServerCtx.newHandler(ch.alloc());
                            if (!SslProtocols.TLS_v1_3.equals(protocol)) {
                                handler.setCloseNotifyReadTimeout(5, TimeUnit.SECONDS);
                            }
                            ch.pipeline().addLast(handler);
                            ch.pipeline().addLast(new SslCompletionEventHandler(
                                    serverHandshakeCompletionEvents, serverCloseCompletionEvents));
                        }
                    })
                    .bind(new InetSocketAddress(0)).syncUninterruptibly().channel();

            Bootstrap bs = new Bootstrap()
                    .group(group)
                    .channel(NioSocketChannel.class)
                    .handler(new ChannelInitializer<Channel>() {
                        @Override
                        protected void initChannel(Channel ch) {
                            SslHandler handler = sslClientCtx.newHandler(
                                    ch.alloc(), "netty.io", 9999);
                            if (!SslProtocols.TLS_v1_3.equals(protocol)) {
                                handler.setCloseNotifyReadTimeout(5, TimeUnit.SECONDS);
                            }
                            ch.pipeline().addLast(handler);
                            ch.pipeline().addLast(
                                    new SslCompletionEventHandler(
                                            clientHandshakeCompletionEvents, clientCloseCompletionEvents));
                        }
                    })
                    .remoteAddress(sc.localAddress());

            Channel cc1 = bs.connect().sync().channel();
            Channel cc2 = bs.connect().sync().channel();

            // We expect 4 events as we have 2 connections and for each connection there should be one event
            // on the server-side and one on the client-side.
            for (int i = 0; i < 2; i++) {
                SslHandshakeCompletionEvent event = clientHandshakeCompletionEvents.take();
                assertTrue(event.isSuccess());
            }
            for (int i = 0; i < 2; i++) {
                SslHandshakeCompletionEvent event = serverHandshakeCompletionEvents.take();
                assertTrue(event.isSuccess());
            }

            assertEquals(0, clientCloseCompletionEvents.size());
            assertEquals(0, serverCloseCompletionEvents.size());

            if (clientClose) {
                cc1.close().sync();
                cc2.close().sync();

                acceptedChannels.take().closeFuture().sync();
                acceptedChannels.take().closeFuture().sync();
            } else {
                acceptedChannels.take().close().sync();
                acceptedChannels.take().close().sync();

                cc1.closeFuture().sync();
                cc2.closeFuture().sync();
            }

            // We expect 4 events as we have 2 connections and for each connection there should be one event
            // on the server-side and one on the client-side.
            for (int i = 0; i < 2; i++) {
                SslCloseCompletionEvent event = clientCloseCompletionEvents.take();
                if (clientClose) {
                    // When we use TLSv1.3 the remote peer is not required to send a close_notify as response.
                    // See:
                    //  - https://datatracker.ietf.org/doc/html/rfc8446#section-6.1
                    //  - https://bugs.openjdk.org/browse/JDK-8208526
                    if (SslProtocols.TLS_v1_3.equals(protocol)) {
                        assertNotNull(event);
                    } else {
                        assertTrue(event.isSuccess());
                    }
                } else {
                    assertTrue(event.isSuccess());
                }
            }
            for (int i = 0; i < 2; i++) {
                SslCloseCompletionEvent event = serverCloseCompletionEvents.take();

                if (clientClose) {
                    assertTrue(event.isSuccess());
                } else {
                    // When we use TLSv1.3 the remote peer is not required to send a close_notify as response.
                    // See:
                    //  - https://datatracker.ietf.org/doc/html/rfc8446#section-6.1
                    //  - https://bugs.openjdk.org/browse/JDK-8208526
                    if (SslProtocols.TLS_v1_3.equals(protocol)) {
                        assertNotNull(event);
                    } else {
                        assertTrue(event.isSuccess());
                    }
                }
            }

            sc.close().sync();
            assertEquals(0, clientHandshakeCompletionEvents.size());
            assertEquals(0, serverHandshakeCompletionEvents.size());
            assertEquals(0, clientCloseCompletionEvents.size());
            assertEquals(0, serverCloseCompletionEvents.size());
        } finally {
            group.shutdownGracefully();
            ReferenceCountUtil.release(sslClientCtx);
            ReferenceCountUtil.release(sslServerCtx);
        }
    }

@Test
    public void testInEventLoopAfterReschedulingFailure() throws Exception {
        final UnorderedThreadPoolEventExecutor underlying = new UnorderedThreadPoolEventExecutor(1);
        final AtomicInteger executeCount = new AtomicInteger();

        final EventExecutorGroup wrapper = new AbstractEventExecutorGroup() {
            @Override
            public void shutdown() {
                shutdownGracefully();
            }

            private final EventExecutor executor = new AbstractEventExecutor(this) {
                @Override
                public boolean inEventLoop(Thread thread) {
                    return underlying.inEventLoop(thread);
                }

                @Override
                public void shutdown() {
                    shutdownGracefully();
                }

                @Override
                public void execute(Runnable command) {
                    // Reject the 2nd execute() call (the reschedule attempt)
                    // 1st call: initial task submission
                    // 2nd call: reschedule after maxTaskExecutePerRun
                    if (executeCount.incrementAndGet() == 2) {
                        throw new RejectedExecutionException("Simulated queue full");
                    }
                    underlying.execute(command);
                }

                @Override
                public boolean isShuttingDown() {
                    return underlying.isShuttingDown();
                }

                @Override
                public Future<?> shutdownGracefully(long quietPeriod, long timeout, TimeUnit unit) {
                    return underlying.shutdownGracefully(quietPeriod, timeout, unit);
                }

                @Override
                public Future<?> terminationFuture() {
                    return underlying.terminationFuture();
                }

                @Override
                public boolean isShutdown() {
                    return underlying.isShutdown();
                }

                @Override
                public boolean isTerminated() {
                    return underlying.isTerminated();
                }

                @Override
                public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
                    return underlying.awaitTermination(timeout, unit);
                }
            };

            @Override
            public EventExecutor next() {
                return executor;
            }

            @Override
            public Iterator<EventExecutor> iterator() {
                return Collections.singletonList(executor).iterator();
            }

            @Override
            public boolean isShuttingDown() {
                return underlying.isShuttingDown();
            }

            @Override
            public Future<?> shutdownGracefully(long quietPeriod, long timeout, TimeUnit unit) {
                return underlying.shutdownGracefully(quietPeriod, timeout, unit);
            }

            @Override
            public Future<?> terminationFuture() {
                return underlying.terminationFuture();
            }

            @Override
            public boolean isShutdown() {
                return underlying.isShutdown();
            }

            @Override
            public boolean isTerminated() {
                return underlying.isTerminated();
            }

            @Override
            public boolean awaitTermination(long timeout, TimeUnit unit) throws InterruptedException {
                return underlying.awaitTermination(timeout, unit);
            }
        };

        // Use maxTaskExecutePerRun=1 so reschedule happens after first task
        NonStickyEventExecutorGroup nonStickyGroup = new NonStickyEventExecutorGroup(wrapper, 1);

        try {
            final EventExecutor executor = nonStickyGroup.next();

            final CountDownLatch latch = new CountDownLatch(1);
            final AtomicReference<Boolean> inEventLoopResult = new AtomicReference<Boolean>();

            // Submit 2 tasks:
            // Task 1: completes, triggers reschedule which will be rejected
            // Task 2: verifies inEventLoop() still works after failed reschedule
            executor.execute(new Runnable() {
                @Override
                public void run() {
                    // First task - will trigger reschedule attempt that fails
                }
            });

            executor.execute(new Runnable() {
                @Override
                public void run() {
                    // This runs AFTER the failed rescheduling
                    // WITHOUT line 262 fix: executingThread is null, inEventLoop() returns false
                    // WITH line 262 fix: executingThread restored, inEventLoop() returns true
                    inEventLoopResult.set(executor.inEventLoop());
                    latch.countDown();
                }
            });

            assertTrue(latch.await(5, TimeUnit.SECONDS), "Tasks should complete");
            Boolean result = inEventLoopResult.get();
            assertNotNull(result, "inEventLoop() should have been called");
            assertTrue(result,
                "inEventLoop() should return true even after failed reschedule attempt. " +
                "This indicates executingThread was properly restored in the exception handler.");
        } finally {
            nonStickyGroup.shutdownGracefully();
            underlying.shutdownGracefully();
        }
    }

