public static void applyChanges(LivingEntity livingEntity, List<Diff> changes) {
        for (var change : changes) {
            final var newAmplifier = change.newAmplifier;
            if (change.delay > 0) {
                final var effectType = change.effect.getEffectType();
                ((WorldScheduler)livingEntity.getWorld()).schedule(change.delay - 1, () -> {
                    var effect = livingEntity.getStatusEffect(effectType);
                    if (effect == null) {
                        // If the effect is not present, we can skip processing
                        return;
                    }
                    processRemoval(livingEntity, effect, newAmplifier);
                });
            } else {
                processRemoval(livingEntity, change.effect, newAmplifier);
            }
        }
    }

private void tick(MinecraftClient client, DevourerMassVisualEntity mass) {
            if (!mass.isAlive() || mass.isCollapsing()) {
                stop(client);
                lastSequence = mass.getVoiceSequence();
                return;
            }
            int sequence = mass.getVoiceSequence();
            if (sequence == lastSequence) {
                return;
            }
            lastSequence = sequence;
            DevourerMassVoice voice = DevourerMassVoice.fromIndex(mass.getVoiceIndex());
            if (voice == null) {
                return;
            }
            stop(client);
            activeSound = new MassVoiceSound(mass, voice);
            client.getSoundManager().play(activeSound);
        }

private void tick(MinecraftClient client, SoulstalkerStrideEntity stride) {
            if (!hasValidRider(stride)) {
                stop(client);
                lastSequence = stride.getVoiceSequence();
                return;
            }
            int sequence = stride.getVoiceSequence();
            if (sequence == lastSequence) {
                return;
            }
            lastSequence = sequence;
            SoulstalkerVoice voice = SoulstalkerVoice.fromIndex(stride.getVoiceIndex());
            if (voice == null || (voice.isIdle() && stride.isLeapInProgress())) {
                return;
            }
            stop(client);
            activeSound = new StrideVoiceSound(stride, voice);
            client.getSoundManager().play(activeSound);
        }

private static void drawWisps(VertexConsumer vertices, Matrix4f matrix, float width,
                                  int seed, float age, int color, int alpha,
                                  int light, boolean deferred) {
        for (int index = 0; index < WISPS; index++) {
            float progress = 0.18F + noise(seed + index * 5779L) * 0.64F;
            CrescentPoint anchor = point(progress, width, seed, age);
            float length = width * (0.22F + noise(seed + index * 7717L) * 0.38F);
            float sway = (noise(seed + index * 3313L) - 0.5F) * width * 0.3F
                    + MathHelper.sin(age * 0.3F + index * 1.7F) * width * 0.06F;
            float lift = (noise(seed + index * 2477L) - 0.5F) * width * 0.22F;
            float half = Math.max(0.02F, width * 0.055F);
            Vec3d base = anchor.inner;
            Vec3d middle = new Vec3d(base.x + sway * 0.45, base.y - length * 0.5, base.z + lift * 0.5);
            Vec3d tip = new Vec3d(base.x + sway, base.y - length, base.z + lift);
            wisp(vertices, matrix, base, middle, half, half * 0.55F, color, alpha, light, deferred);
            wisp(vertices, matrix, middle, tip, half * 0.55F, half * 0.12F, color,
                    Math.round(alpha * 0.45F), light, deferred);
        }
    }

