public void closeWith(Object msg) {
    if (channel.isActive()) {
      boolean is17 = this.getProtocolVersion().lessThan(ProtocolVersion.MINECRAFT_1_8)
          && this.getProtocolVersion().noLessThan(ProtocolVersion.MINECRAFT_1_7_2);
      if (is17 && this.getState() != StateRegistry.STATUS) {
        channel.eventLoop().execute(() -> {
          // 1.7.x versions have a race condition with switching protocol states, so just explicitly
          // close the connection after a short while.
          this.setAutoReading(false);
          channel.eventLoop().schedule(() -> {
            knownDisconnect = true;
            channel.writeAndFlush(msg).addListener(ChannelFutureListener.CLOSE);
          }, 250, TimeUnit.MILLISECONDS);
        });
      } else {
        knownDisconnect = true;
        channel.writeAndFlush(msg).addListener(ChannelFutureListener.CLOSE);
      }
    }
  }

private static double getSmoothRenderPhase(DancingBladeVisualEntity entity, float tickDelta) {
        float ageTicks = entity.age + tickDelta;
        RenderOrbitState state = RENDER_STATES.computeIfAbsent(entity.getId(), ignored -> new RenderOrbitState(entity.getOrbitPhase(), ageTicks));
        float deltaTicks = ageTicks - state.lastAgeTicks;
        if (deltaTicks < 0.0F || deltaTicks > 5.0F) {
            state.phase = entity.getOrbitPhase();
        } else if (deltaTicks > 0.0F) {
            state.phase += deltaTicks * BASE_ANGULAR_SPEED;
        }
        state.lastAgeTicks = ageTicks;
        while (state.phase > Math.PI * 2.0) {
            state.phase -= Math.PI * 2.0;
        }

        if (entity.age % 80 == 0) {
            RENDER_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId() && ageTicks - entry.getValue().lastAgeTicks > 100.0F);
        }
        return state.phase;
    }

@Test
	public void testShutdownDuringScheduleRunsCommandOnce() {
		// Setup: shutdown is triggered after the service accepts the task but before the Future is returned.
		ShutdownDuringScheduleExecutorService service = new ShutdownDuringScheduleExecutorService(false);
		DelayedExecutor executor = new DelayedExecutor(SHUTDOWN_TIMEOUT, service);
		AtomicInteger runs = new AtomicInteger();
		service.setOnScheduleAccepted(executor::shutdown);

		try {
			// Operation: schedule a delayed command, causing shutdown before schedule returns.
			Future<?> future = executor.schedule(runs::incrementAndGet, Duration.ofMillis(50));

			// Assertions: the command is flushed once and the queued scheduled Future does not run it again.
			Assertions.assertTrue(service.isShutdown(), "The scheduler hook should have triggered shutdown.");
			Assertions.assertEquals(1, runs.get(), "Shutdown during schedule should run the command exactly once.");
			Assertions.assertTrue(future.isCancelled(), "The queued delayed task should be canceled when shutdown flushes it.");
		} finally {
			service.shutdownNow();
		}
	}

@Override
    protected void sendResponse(final ChannelHandlerContext ctx, String streamId, int latency,
            final FullHttpResponse response, final FullHttpRequest request) {
        HttpUtil.setContentLength(response, response.content().readableBytes());
        ctx.executor().schedule(new Runnable() {
            @Override
            public void run() {
                if (isKeepAlive(request)) {
                    if (request.protocolVersion().equals(HTTP_1_0)) {
                        response.headers().set(CONNECTION, KEEP_ALIVE);
                    }
                    ctx.writeAndFlush(response);
                } else {
                    // Tell the client we're going to close the connection.
                    response.headers().set(CONNECTION, CLOSE);
                    ctx.writeAndFlush(response).addListener(ChannelFutureListener.CLOSE);
                }
            }
        }, latency, TimeUnit.MILLISECONDS);
    }

private void sendInitialMessage(final ChannelHandlerContext ctx) throws Exception {
        final long connectTimeoutMillis = this.connectTimeoutMillis;
        if (connectTimeoutMillis > 0) {
            connectTimeoutFuture = ctx.executor().schedule(new Runnable() {
                @Override
                public void run() {
                    if (!connectPromise.isDone()) {
                        setConnectFailure(new ProxyConnectException(exceptionMessage("timeout")));
                    }
                }
            }, connectTimeoutMillis, TimeUnit.MILLISECONDS);
        }

        final Object initialMessage = newInitialMessage(ctx);
        if (initialMessage != null) {
            sendToProxyServer(initialMessage);
        }

        readIfNeeded(ctx);
    }

private static void enqueueBlockBreak(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos, float refHardness, ToolAction refTool, int remaining) {
        ServerScheduler.schedule(1, () -> {
            BlockState offsetState = world.getBlockState(pos);

            float blockHardness = offsetState.getDestroySpeed(world, pos);
            if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
                    && blockHardness != -1
                    && blockHardness <= refHardness
                    && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
                if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
                    EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

                    item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

                    if (remaining > 0) {
                        enqueueBlockBreak(world, player, item, itemStack, direction, pos.relative(direction), refHardness, refTool, remaining - 1);
                    }
                }
            }
        });
    }

@Override
    public boolean perform(ItemEffectContext context) {
        if (key != null || keyEntity != null) {
            String entityId = Optional.ofNullable(keyEntity)
                    .map(provider -> provider.getEntity(context))
                    .map(Entity::getStringUUID)
                    .orElse(null);
            String concatenatedKey = Stream.of(key, entityId)
                    .filter(Objects::nonNull)
                    .collect(Collectors.joining(""));

            if (replaceKey.test(context) || !ServerScheduler.isScheduled(concatenatedKey)) {
                ServerScheduler.schedule(concatenatedKey, delay.getIntegerValue(context), () -> outcome.perform(context));
                return true;
            }
            return false;
        }

        ServerScheduler.schedule(delay.getIntegerValue(context), () -> outcome.perform(context));
        return true;
    }

