static void closeAfterFinishEncode(final ChannelHandlerContext ctx, final ChannelFuture finishFuture,
                                       final ChannelPromise promise) {
        if (!finishFuture.isDone()) {
            // Ensure the channel is closed even if the write operation completes in time.
            final Future<?> future = ctx.executor().schedule(new Runnable() {
                @Override
                public void run() {
                    ctx.close(promise);
                }
            }, THREAD_POOL_DELAY_SECONDS, TimeUnit.SECONDS);

            finishFuture.addListener(f -> {
                // Cancel the scheduled timeout.
                future.cancel(true);
                if (!promise.isDone()) {
                    ctx.close(promise);
                }
            });
        } else {
            ctx.close(promise);
        }
    }

private void applyHandshakeTimeout() {
        final ChannelPromise localHandshakePromise = handshakePromise;
        final long handshakeTimeoutMillis = serverConfig.handshakeTimeoutMillis();
        if (handshakeTimeoutMillis <= 0 || localHandshakePromise.isDone()) {
            return;
        }

        final Future<?> timeoutFuture = ctx.executor().schedule(new Runnable() {
            @Override
            public void run() {
                if (!localHandshakePromise.isDone() &&
                    localHandshakePromise.tryFailure(new WebSocketServerHandshakeException("handshake timed out"))) {
                    ctx.flush()
                       .fireUserEventTriggered(ServerHandshakeStateEvent.HANDSHAKE_TIMEOUT)
                       .close();
                }
            }
        }, handshakeTimeoutMillis, TimeUnit.MILLISECONDS);

        // Cancel the handshake timeout when handshake is finished.
        localHandshakePromise.addListener(f -> timeoutFuture.cancel(false));
    }

public static synchronized boolean open(OpenToLANConfig config) {
        Objects.requireNonNull(config, "config");
        if (state != null) return false;
        final long eventDelayNanos = config.delayBetweenEvent.toNanos();
        final DatagramSocket socket;
        try {
            socket = new DatagramSocket(config.port);
        } catch (SocketException e) {
            LOGGER.warn("Could not bind to the port!", e);
            return false;
        }
        final Task task;
        try {
            task = MinecraftServer.getSchedulerManager().buildTask(OpenToLAN::ping)
                    .repeat(config.delayBetweenPings)
                    .schedule();
        } catch (RuntimeException exception) {
            socket.close();
            throw exception;
        }
        state = new State(socket, task, eventDelayNanos);
        return true;
    }

