private static <T extends Entity & ParchmentBoltRenderData> Vec3d resolveSmoothedOffset(T entity, float tickDelta) {
        float ageTicks = entity.age + tickDelta;
        Vec3d target = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));

        RenderState state = RENDER_STATES.computeIfAbsent(entity.getId(),
                ignored -> new RenderState(target, ageTicks));

        float deltaTicks = ageTicks - state.lastAgeTicks;
        if (deltaTicks < 0.0F || deltaTicks > 5.0F) {
            state.position = target;
        } else if (deltaTicks > 0.0F) {
            state.position = state.position.lerp(target,
                    Math.min(1.0F, POSITION_SMOOTHING_RATE * deltaTicks));
        }
        state.lastAgeTicks = ageTicks;

        if (entity.age % 80 == 0) {
            RENDER_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId() && ageTicks - entry.getValue().lastAgeTicks > 100.0F);
        }
        return state.position.subtract(target);
    }

private static double getSmoothRenderPhase(SoulkeeperLanternVisualEntity entity, float tickDelta, float speedMultiplier) {
        float ageTicks = entity.age + tickDelta;
        RenderOrbitState state = RENDER_STATES.computeIfAbsent(entity.getId(), ignored -> new RenderOrbitState(entity.getOrbitPhase(), ageTicks));
        float deltaTicks = ageTicks - state.lastAgeTicks;
        if (deltaTicks < 0.0F || deltaTicks > 5.0F) {
            state.phase = entity.getOrbitPhase();
        } else if (deltaTicks > 0.0F) {
            state.phase += deltaTicks * BASE_ANGULAR_SPEED * speedMultiplier;
        }
        state.lastAgeTicks = ageTicks;
        while (state.phase > Math.PI * 2.0) {
            state.phase -= Math.PI * 2.0;
        }

        if (entity.age % 80 == 0) {
            Iterator<Map.Entry<Integer, RenderOrbitState>> iterator = RENDER_STATES.entrySet().iterator();
            while (iterator.hasNext()) {
                Map.Entry<Integer, RenderOrbitState> entry = iterator.next();
                if (entry.getKey() != entity.getId() && ageTicks - entry.getValue().lastAgeTicks > 100.0F) {
                    iterator.remove();
                }
            }
        }
        return state.phase;
    }

private void doSlam(BlockPos fromPos, float chance) {
        TMEParticlePacket packet = new TMEParticlePacket();

        for (Direction dir : Direction.values()) {
            if (RandomUtil.percentChance(chance)) {
                BlockPos pos = fromPos.offset(dir.getNormal());
                BlockState state = level().getBlockState(pos);

                if (state.is(AoATags.Blocks.INFERNAL_CAN_CONVERT)) {
                    int tickTime = Math.max(1, 1 - pos.distManhattan(fromPos));

                    packet.particle(ParticleBuilder.forPosition(ParticleTypes.FLAME, pos.getX() + RandomUtil.valueUpTo(1), pos.getY() + 1.1, pos.getZ() + RandomUtil.valueUpTo(1)));
                    level().setBlockAndUpdate(pos, Blocks.MAGMA_BLOCK.defaultBlockState());
                    AoAScheduler.schedule(tickTime, tick -> doSlam(pos, chance * 0.8f));
                    AoAScheduler.schedule(tickTime + 100, tick -> {
                        if (level().getBlockState(pos).getBlock() == Blocks.MAGMA_BLOCK)
                            level().setBlockAndUpdate(pos, state);
                    });
                }
            }
        }

        if (!packet.isEmpty())
            packet.sendToAllPlayersTrackingEntity(this);
    }

