                            ctx.close();
                        }
                    });
                }

@Override
	public void fabric_markChanged(AttachmentType<?> type) {
		if (this.level instanceof ServerLevel serverLevel) {
			ChunkHolder chunkHolder = serverLevel.getChunkSource().chunkMap.getUpdatingChunkIfPresent(ChunkPos.pack(this.worldPosition));

			// If chunkHolder is null, then chunk is probably unloaded/unloading.
			// calling setChanged() may start loading the chunk again, causing an infinite loop of chunk loading/unloading.
			// so just do nothing.
			if (chunkHolder == null) {
				return;
			}

			CompletableFuture<ChunkResult<LevelChunk>> chunkFuture = chunkHolder.getFullChunkFuture();

			if (chunkFuture.isDone()) {
				// If chunk is already loaded successfully, then call setChanged() immediately
				chunkFuture.thenAccept(chunkResult -> chunkResult.ifSuccess(_ -> this.setChanged()));
			} else {
				// Otherwise setChanged() is called after to avoid deadlocking the server thread
				MinecraftServer server = serverLevel.getServer();
				server.schedule(server.wrapRunnable(() -> fabric_markChanged(type)));
			}
		} else {
			this.setChanged();
		}
	}

static void prism(VertexConsumer vertices, Matrix4f matrix, Vec3d start, Vec3d end,
                      float halfWidth, int color, int alpha, int light, boolean deferred) {
        Vec3d direction = end.subtract(start);
        if (direction.lengthSquared() < 1.0E-6) {
            return;
        }
        Vec3d forward = direction.normalize();
        Vec3d reference = Math.abs(forward.y) > 0.88
                ? new Vec3d(1.0, 0.0, 0.0) : new Vec3d(0.0, 1.0, 0.0);
        Vec3d side = forward.crossProduct(reference).normalize().multiply(halfWidth);
        Vec3d up = forward.crossProduct(side.normalize()).normalize().multiply(halfWidth);
        Vec3d a = start.add(side).add(up);
        Vec3d b = start.subtract(side).add(up);
        Vec3d c = start.subtract(side).subtract(up);
        Vec3d d = start.add(side).subtract(up);
        Vec3d e = end.add(side).add(up);
        Vec3d f = end.subtract(side).add(up);
        Vec3d g = end.subtract(side).subtract(up);
        Vec3d h = end.add(side).subtract(up);
        quad(vertices, matrix, a, b, f, e, color, alpha, light, deferred);
        quad(vertices, matrix, b, c, g, f, color, alpha, light, deferred);
        quad(vertices, matrix, c, d, h, g, color, alpha, light, deferred);
        quad(vertices, matrix, d, a, e, h, color, alpha, light, deferred);
        quad(vertices, matrix, a, d, c, b, color, alpha, light, deferred);
        quad(vertices, matrix, e, f, g, h, color, alpha, light, deferred);
    }

private void applyHandshakeTimeout() {
        final Promise<Channel> localHandshakePromise = this.handshakePromise;

        // Set timeout if necessary.
        final long handshakeTimeoutMillis = this.handshakeTimeoutMillis;
        if (handshakeTimeoutMillis <= 0 || localHandshakePromise.isDone()) {
            return;
        }

        final Future<?> timeoutFuture = ctx.executor().schedule(() -> {
            if (localHandshakePromise.isDone()) {
                return;
            }
            SSLException exception =
                    new SslHandshakeTimeoutException("handshake timed out after " + handshakeTimeoutMillis + "ms");
            try {
                if (localHandshakePromise.tryFailure(exception)) {
                    SslUtils.handleHandshakeFailure(ctx, exception, true);
                }
            } finally {
                releaseAndFailAll(ctx, exception);
            }
        }, handshakeTimeoutMillis, TimeUnit.MILLISECONDS);

        // Cancel the handshake timeout when handshake is finished.
        localHandshakePromise.addListener(f -> timeoutFuture.cancel(false));
    }

