        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-entity.getYaw(tickDelta)));
        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(entity.getPitch(tickDelta)));
        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(90.0F));
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        int packedLight = Math.max(light, LightmapTextureManager.MAX_LIGHT_COORDINATE);
        VertexConsumer dark = consumers.getBuffer(RenderLayer.getDebugQuads());
        drawBody(dark, matrix, width, entity.getSeed(), age, alpha, packedLight, false);
        drawWisps(dark, matrix, width, entity.getSeed(), age, DARK,
                Math.round(alpha * 0.78F), packedLight, false);
        VertexConsumer glow = IonDeferredRenderController.getLightningBuffer();
        drawRim(glow, matrix, width, entity.getSeed(), age, Math.round(alpha * 0.95F));
        drawWisps(glow, matrix, width, entity.getSeed(), age, GLOW,
                Math.round(alpha * 0.3F), 0, true);
        matrices.pop();
        super.render(entity, yaw, tickDelta, matrices, consumers, light);
    }

private void beginFrame(SoulstalkerStrideEntity entity, float time) {
            if (surfaceMode != solveMode(entity.getSurfaceMode())) {
                surfaceMode = solveMode(entity.getSurfaceMode());
                modeChangedAt = time;
                for (LegState leg : legs) {
                    if (leg != null) {
                        leg.pendingTransition = true;
                    }
                }
            }
            if (stepSequence != entity.getStepSequence()) {
                if (stepSequence != Integer.MIN_VALUE) {
                    commandedLeg = entity.getStepLeg();
                }
                stepSequence = entity.getStepSequence();
            }
            if (leapSequence != entity.getLeapSequence()) {
                if (leapSequence != Integer.MIN_VALUE) {
                    for (LegState leg : legs) {
                        if (leg != null) {
                            leg.pendingTransition = true;
                        }
                    }
                    modeChangedAt = time;
                }
                leapSequence = entity.getLeapSequence();
            }
        }

@Override
    public void close(
            final ChannelHandlerContext ctx,
            final ChannelPromise promise) {
        ChannelFuture f = finishEncode(ctx, ctx.newPromise());

        if (!f.isDone()) {
            // Ensure the channel is closed even if the write operation completes in time.
            final Future<?> future = ctx.executor().schedule(new Runnable() {
                @Override
                public void run() {
                    if (!promise.isDone()) {
                        ctx.close(promise);
                    }
                }
            }, THREAD_POOL_DELAY_SECONDS, TimeUnit.SECONDS);

            f.addListener(f1 -> {
                // Cancel the scheduled timeout.
                future.cancel(true);
                if (!promise.isDone()) {
                    ctx.close(promise);
                }
            });
        } else {
            ctx.close(promise);
        }
    }

