@Test
	public void testShutdownDoesNotKeepUnclaimedDelayedTasksAlive() throws Exception {
		// Setup: a delayed task is accepted by the default scheduler but is not tracked by DelayedExecutor.
		try (ScheduledThreadPoolExecutor service = DelayedExecutor.createDefaultService()) {
			Assertions.assertFalse(
				service.getExecuteExistingDelayedTasksAfterShutdownPolicy(),
				"Default service must not keep delayed tasks queued after shutdown."
			);
			AtomicBoolean ran = new AtomicBoolean(false);
			service.schedule(() -> ran.set(true), LONG_DELAY.toMillis(), TimeUnit.MILLISECONDS);

			try {
				// Operation: shut down the scheduler before the task's delay elapses.
				service.shutdown();

				// Assertions: unclaimed delayed tasks do not keep shutdown waiting and cannot run after shutdown.
				Assertions.assertTrue(
					service.awaitTermination(100, TimeUnit.MILLISECONDS),
					"Default service shutdown should not wait for unclaimed delayed tasks."
				);
				Assertions.assertFalse(
					ran.get(),
					"Unclaimed delayed tasks should not run from the scheduler after shutdown."
				);
			} finally {
				service.shutdownNow();
			}
		}
	}

@Test
	public void testRetainedDelayedTasksKeepShutdownAlive() throws Exception {
		// This contrast test shows the failure mode protected by testShutdownDoesNotKeepUnclaimedDelayedTasksAlive.
		// It sets executeExistingDelayedTasksAfterShutdownPolicy to true to prove retained delayed tasks can block shutdown.
		// The default service must keep this policy false so shutdown is not held open by original task delays.
		// Setup: a scheduler keeps delayed tasks after shutdown, which is what DelayedExecutor's default avoids.
		try (ScheduledThreadPoolExecutor service = new ScheduledThreadPoolExecutor(1)) {
			service.setExecuteExistingDelayedTasksAfterShutdownPolicy(true);
			AtomicBoolean ran = new AtomicBoolean(false);
			service.schedule(() -> ran.set(true), LONG_DELAY.toMillis(), TimeUnit.MILLISECONDS);

			try {
				// Operation: shut down the scheduler before the task's delay elapses.
				service.shutdown();

				// Assertions: retained delayed tasks keep shutdown open until their original delay can pass.
				Assertions.assertFalse(
					service.awaitTermination(100, TimeUnit.MILLISECONDS),
					"Shutdown should keep waiting while a retained delayed task is queued."
				);
				Assertions.assertFalse(
					ran.get(),
					"The retained delayed task should not have run before its original delay."
				);
			} finally {
				service.shutdownNow();
			}
		}
	}

private TerrainCache getTerrainCache(CaelestisBreachVisualEntity entity) {
        World world = entity.getWorld();
        long now = world.getTime();
        terrainCaches.entrySet().removeIf(entry ->
                entry.getValue().world != world
                        || now - entry.getValue().lastSeenTick > TERRAIN_CACHE_GRACE_TICKS);

        UUID id = entity.getUuid();
        int centerX = MathHelper.floor(entity.getX());
        int centerY = MathHelper.floor(entity.getY());
        int centerZ = MathHelper.floor(entity.getZ());
        int maxRadius = MathHelper.ceil(entity.getMaxRadius()) + 2;
        float verticalRange = entity.getVerticalRange();
        TerrainCache cache = terrainCaches.get(id);
        boolean rebuild = cache == null
                || cache.world != world
                || cache.centerX != centerX
                || cache.centerY != centerY
                || cache.centerZ != centerZ
                || cache.maxRadius != maxRadius
                || Float.compare(cache.verticalRange, verticalRange) != 0
                || now - cache.lastRefreshTick >= TERRAIN_REFRESH_TICKS;
        if (rebuild) {
            cache = buildTerrainCache(
                    world, centerX, centerY, centerZ, maxRadius, verticalRange, now);
            terrainCaches.put(id, cache);
        }
        cache.lastSeenTick = now;
        return cache;
    }

@Override
	public void tick() {
		super.tick();

		if (!level.isClientSide) {
			if (random.nextInt(200) == 0 && !level.dimensionType().ultraWarm() && level.getBlockState(blockPosition()).getMaterial().isReplaceable()) {
				level.setBlockAndUpdate(blockPosition(), Blocks.WATER.defaultBlockState());
				new DracyonCleanupTask(level, blockPosition()).schedule(5, TimeUnit.SECONDS);
			}

			if (random.nextInt(70) == 0 && getTarget() != null) {
				LivingEntity target = getTarget();
				BaseMobProjectile projectile = new SpectralShotEntity(this, BaseMobProjectile.Type.MAGIC);

				double distanceFactorX = target.getX() - projectile.getX();
				double distanceFactorY = target.getBoundingBox().minY + (target.getBbHeight() / 3) - projectile.getY();
				double distanceFactorZ = target.getZ() - projectile.getZ();
				double hyp = MathHelper.sqrt(distanceFactorX * distanceFactorX + distanceFactorZ * distanceFactorZ) * 0.05d;

				level.playSound(null, blockPosition(), AoASounds.ENTITY_DRACYON_AMBIENT.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
				projectile.shoot(distanceFactorX, distanceFactorY + hyp, distanceFactorZ, 1.6f, (float)(4 - this.level.getDifficulty().getId()));
				level.addFreshEntity(projectile);
			}

			float healthPercent = getHealth() / getMaxHealth();

			if (healthPercent != bossInfo.getPercent())
				bossInfo.setPercent(healthPercent);
		}
	}

private ChannelFuture close0(final ChannelOutboundInvoker invoker, final Channel channel,
                                 CloseWebSocketFrame frame, ChannelPromise promise) {
        invoker.writeAndFlush(frame, promise);
        final long forceCloseTimeoutMillis = this.forceCloseTimeoutMillis;
        final WebSocketClientHandshaker handshaker = this;
        if (forceCloseTimeoutMillis <= 0 || !channel.isActive() || forceCloseInit != 0) {
            return promise;
        }

        promise.addListener(future -> {
            // If flush operation failed, there is no reason to expect
            // a server to receive CloseFrame. Thus this should be handled
            // by the application separately.
            // Also, close might be called twice from different threads.
            if (future.isSuccess() && channel.isActive() &&
                    FORCE_CLOSE_INIT_UPDATER.compareAndSet(handshaker, 0, 1)) {
                final Future<?> forceCloseFuture = channel.eventLoop().schedule(new Runnable() {
                    @Override
                    public void run() {
                        if (channel.isActive()) {
                            invoker.close();
                            forceCloseComplete = true;
                        }
                    }
                }, forceCloseTimeoutMillis, TimeUnit.MILLISECONDS);
                channel.closeFuture().addListener(f -> forceCloseFuture.cancel(false));
            }
        });
        return promise;
    }

