        }, 1);
    }

private void updateDevourerGrowth(
            DevourerGrowthState growth, float targetProgress, float animationTime) {
        float elapsed = MathHelper.clamp(animationTime - growth.lastAnimationTime, 0.0F, 20.0F);
        float target = Math.max(growth.displayedProgress, targetProgress);
        if (elapsed > 0.0F && target > growth.displayedProgress) {
            float response = 1.0F - (float) Math.exp(-elapsed / DEVOURER_SPREAD_RESPONSE);
            growth.displayedProgress = MathHelper.lerp(
                    response, growth.displayedProgress, target);
        }
        growth.displayedProgress = Math.max(growth.displayedProgress,
                Math.min(target, 0.001F));
        growth.lastAnimationTime = animationTime;
        growth.lastSeenTick = growth.world.getTime();
        for (int i = 0; i < growth.arrivals.length; i++) {
            if (Float.isNaN(growth.activatedAt[i])
                    && growth.arrivals[i] <= growth.displayedProgress + 1.0E-5F) {
                growth.activatedAt[i] = animationTime;
            }
            if (Float.isNaN(growth.activatedAt[i])) {
                growth.wetness[i] = 0.0F;
                continue;
            }
            float progress = MathHelper.clamp(
                    (animationTime - growth.activatedAt[i])
                            / DEVOURER_CELL_FADE_TICKS,
                    0.0F, 1.0F);
            growth.wetness[i] = progress * progress * (3.0F - 2.0F * progress);
        }
        long now = growth.world.getTime();
        devourerGrowth.entrySet().removeIf(entry ->
                entry.getValue() != growth
                        && (entry.getValue().world != growth.world
                        || now - entry.getValue().lastSeenTick > 1200L));
    }

public static void doDeathPrevention(final LivingDamageEvent.Pre ev, ServerPlayerDataManager plData) {
		ServerPlayer player = plData.getPlayer();

		if (player.server.isHardcore() && NowhereEvents.isInBossRegion(player.blockPosition()))
			return;

		LivingEntity killer = player.getKillCredit();

		player.getScoreboard().forAllObjectives(ObjectiveCriteria.DEATH_COUNT, player, ScoreAccess::increment);

		if (killer != null) {
			player.awardStat(Stats.ENTITY_KILLED_BY.get(killer.getType()));
			killer.awardKillScore(player, 1, ev.getContainer().getSource());
		}

		player.awardStat(Stats.DEATHS);
		player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_DEATH));
		player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_REST));

		if (!AdvancementUtil.isAdvancementCompleted(player, AdventOfAscension.id("nowhere/root"))) {
			AoAScheduler.schedule(1, tick -> {
				PlayerUtil.resetToDefaultStatus(player);
				player.connection.teleport(17.5d, 452.5d, 3.5d, 0, player.getXRot());
				InventoryUtil.clearItems(player, AoAItems.RETURN_CRYSTAL);
				PlayerUtil.getAdventPlayer(player).storage.returnStoredItems();
			});
		}
		else {
			NowhereActivityPortal.Activity.RETURN.activate(plData.getPlayer());
		}

		player.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
		ev.getContainer().setNewDamage(0);
	}

