public static void consume(PlayerEntity player, float progress, SpellContainerSource.SourcedContainer spellSource, Identifier spellId, RegistryEntry<Spell> spellEntry, ItemStack heldItemStack, Ammo.Result ammoResult, boolean scheduled) {
        var spell = spellEntry.value();
        var batching = spell.cost.batching;
        if (batching && !scheduled) {
            if (((SpellBatcher)player).hasBatchedCost(spellId)) {
                return;
            }
            ((WorldScheduler)player.getWorld()).schedule(0, () -> consume(player, progress, spellSource, spellId, spellEntry, heldItemStack, ammoResult, true));
            ((SpellBatcher)player).batchCost(spellId, true);
            return;
        }

        // Consume things
        // Cooldown
        SpellCooldowns.imposeCooldown(player, spellSource, spellEntry, progress);
        // Exhaust
        player.addExhaustion(spell.cost.exhaust * SpellEngineMod.config.spell_cost_exhaust_multiplier);
        // Durability
        if (SpellEngineMod.config.spell_cost_durability_allowed && spell.cost.durability > 0) {
            var stackToDamage = (spellSource.itemStack() != null && spellSource.itemStack().isDamageable()) ? spellSource.itemStack() : heldItemStack;
            stackToDamage.damage(spell.cost.durability, player, EquipmentSlot.MAINHAND);
        }
        // Item
        Ammo.consume(ammoResult, player);
        // Status effect
        if (spell.cost.effect_id != null) {
            var effect = Registries.STATUS_EFFECT.getEntry(Identifier.of(spell.cost.effect_id));
            if (effect.isPresent()) {
                player.removeStatusEffect(effect.get());
            }
        }
        if (SpellEvents.COST_CONSUME.isListened()) {
            var args = new SpellEvents.SpellCostConsumeEvent.Args(player, spellEntry, heldItemStack);
            SpellEvents.COST_CONSUME.invoke(l -> l.onSpellCostConsume(args));
        }
    }

@Override
        protected void doDelayedAction(FlamewalkerEntity entity) {
            if (this.target == null)
                return;

            if (!BrainUtils.canSee(entity, this.target) || entity.distanceToSqr(this.target) > this.attackRadius)
                return;

            for (int tick = 1; tick < 12; tick++) {
                final int thisTick = tick;
                final Vec3 targetPos = this.targetingPosition;
                final EasyRandom random = entity.rand();

                AoAScheduler.schedule(thisTick, tick2 -> {
                    TMEParticlePacket packet = new TMEParticlePacket(45);

                    for (int i = 0; i < 8; i++) {
                        if (thisTick == 1) {
                            packet.particle(ParticleBuilder.forPositions(EntityTrackingParticleOptions.fromEntity(AoAParticleTypes.BURNING_FLAME, entity), targetPos.add(random.scaledGaussianValue(0.8f), random.valueBetween(-0.5f, 0), random.scaledGaussianValue(0.8f)))
                                    .scaleMod(random.valueBetween(1, 3))
                                    .lifespan(Mth.ceil(5 / random.valueBetween(0.2f, 1f)))
                                    .velocity(random.scaledGaussianValue(0.05f), 0.5, random.scaledGaussianValue(0.05f)));
                        }

                        packet.particle(ParticleBuilder.forPositions(ParticleTypes.SMOKE, targetPos.add(random.scaledGaussianValue(1), random.valueBetween(-0.5f, 0), random.scaledGaussianValue(1)))
                                .velocity(random.scaledGaussianValue(0.05f), 0.5, random.scaledGaussianValue(0.05f)));
                        packet.particle(ParticleBuilder.forPositions(EntityTrackingParticleOptions.ambient(AoAParticleTypes.BURNING_FLAME), targetPos.add(random.scaledGaussianValue(0.5f), random.valueBetween(-0.5f, 0), random.scaledGaussianValue(0.5f)))
                                .scaleMod(random.valueBetween(0.5f, 1.5f))
                                .velocity(random.scaledGaussianValue(0.05f), 0.5, random.scaledGaussianValue(0.05f)));
                    }

                    packet.sendToAllPlayersTrackingEntity(entity);
                });
            }

            BrainUtils.setForgettableMemory(entity, MemoryModuleType.ATTACK_COOLING_DOWN, true, this.attackIntervalSupplier.apply(entity));
        }

private static void onEntityInteract(final PlayerInteractEvent.EntityInteractSpecific ev) {
		if (!ev.getEntity().level().isClientSide) {
			if (ev.getItemStack().getItem() instanceof StasisCapsule stasisCapsule && ev.getTarget() instanceof LivingEntity target) {
				InteractionResult result = stasisCapsule.tryCapture(ev.getEntity(), target, ev.getItemStack(), ev.getHand());

				if (result != InteractionResult.PASS) {
					ev.setCancellationResult(result);

					return;
				}
			}

			if (ev.getTarget() instanceof Piglin piglin && piglin.getItemBySlot(EquipmentSlot.HEAD).getItem() == Items.GOLDEN_HELMET) {
				ItemStack stack = ev.getEntity().getItemInHand(ev.getHand());

				if ((stack.getItem() == Items.ENCHANTED_GOLDEN_APPLE || stack.getItem() == AoAItems.GOLD_COIN.get()) && piglin.getOffhandItem().isEmpty()) {
					piglin.addTag("BarteringForExplosiveIdol");
					piglin.setItemSlot(EquipmentSlot.OFFHAND, stack.split(1));
					piglin.setGuaranteedDrop(EquipmentSlot.OFFHAND);
					piglin.getBrain().setMemoryWithExpiry(MemoryModuleType.ADMIRING_ITEM, true, 121);
					piglin.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);
					piglin.getNavigation().stop();

					AoAScheduler.schedule(120, tick -> {
						if (piglin != null && piglin.isAlive() && piglin.getHealth() >= piglin.getMaxHealth()) {
							ItemStack offHandItem = piglin.getItemInHand(InteractionHand.OFF_HAND);

							if (offHandItem.getItem() == Items.ENCHANTED_GOLDEN_APPLE || offHandItem.getItem() == AoAItems.GOLD_COIN.get()) {
								piglin.setItemInHand(InteractionHand.OFF_HAND, Items.GOLD_INGOT.getDefaultInstance());
								piglin.getBrain().eraseMemory(MemoryModuleType.ADMIRING_ITEM);
							}
						}
					});
				}
			}
		}
	}

private static void fireTriggers(Event event) {
        if (event.player.getWorld().isClient()) { return; }
        // Iterate stash effects
        SpellStashHelper.useStashes(event);
        // Iterate passive spells
        var player = event.player;
        var caster = (SpellCaster.Player)player;
        for(var spellEntry: SpellContainerSource.passiveSpellsOf(event.player)) {
            var spell = spellEntry.value();
            var spellId = spellEntry.getKey().get().getValue();
            if (spell.passive != null && !caster.getCooldownManager().isCoolingDown(spellEntry)) {
                for (var trigger : spell.passive.triggers) {
                    if (evaluateTrigger(spellEntry, trigger, event)) {
                        SpellTarget.SearchResult targetResult;
                        if (spell.target.type == Spell.Target.Type.FROM_TRIGGER) {
                            if (event.target == null && event.location != null) {
                                targetResult = SpellTarget.SearchResult.of(event.location);
                            } else {
                                List<Entity> targets = List.of(event.target(trigger));
                                targetResult = SpellTarget.SearchResult.of(targets);
                            }
                        } else {
                            targetResult = SpellTarget.findTargets(player, spellEntry, SpellTarget.SearchResult.empty(), true);
                        }
                        if (trigger.fire_delay > 0) {
                            ((WorldScheduler)player.getWorld()).schedule(trigger.fire_delay - 1, () -> {
                                SpellExecution.performSpell(player.getWorld(), player, spellEntry, targetResult, SpellCast.Action.TRIGGER, 1);
                            });
                        } else {
                            SpellExecution.performSpell(player.getWorld(), player, spellEntry, targetResult, SpellCast.Action.TRIGGER, 1);
                        }
                        break;
                    }
                }
            }
        }
    }

public static synchronized void apply(ObserverStatusEffectsPacket packet) {
        if (packet.replaceAll()) {
            EFFECTS.clear();
        }

        Map<UUID, Map<Identifier, StoredEffect>> dimensionEffects =
                EFFECTS.computeIfAbsent(packet.dimensionId(), ignored -> new HashMap<>());
        for (ObserverStatusEffectsPacket.Entry entry : packet.entries()) {
            if (!entry.active()) {
                Map<Identifier, StoredEffect> entityEffects = dimensionEffects.get(entry.entityId());
                if (entityEffects == null) {
                    continue;
                }
                entityEffects.remove(entry.effectId());
                if (entityEffects.isEmpty()) {
                    dimensionEffects.remove(entry.entityId());
                }
                continue;
            }

            long expiryTick = entry.infinite()
                    ? Long.MAX_VALUE
                    : packet.serverWorldTime() + Math.max(0, entry.duration());
            dimensionEffects
                    .computeIfAbsent(entry.entityId(), ignored -> new HashMap<>())
                    .put(entry.effectId(), new StoredEffect(
                            entry.amplifier(),
                            expiryTick,
                            entry.infinite(),
                            entry.ambient(),
                            entry.showParticles(),
                            entry.showIcon()));
        }

        if (dimensionEffects.isEmpty()) {
            EFFECTS.remove(packet.dimensionId());
        }
    }

private RenderPose resolvePose(GloampiercerSpearEntity entity, float tickDelta) {
        Vec3d targetPosition = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        Vec3d targetDirection = entity.getFlightDirection();
        if (targetDirection.lengthSquared() < 1.0E-6) {
            targetDirection = new Vec3d(0.0, -1.0, 0.0);
        } else {
            targetDirection = targetDirection.normalize();
        }
        float ageTicks = entity.age + tickDelta;
        long worldTick = entity.getWorld().getTime();
        RenderState state = RENDER_STATES.get(entity.getId());
        float delta = state == null ? 0.0F : ageTicks - state.lastAge;
        if (state == null || state.world != entity.getWorld() || !state.uuid.equals(entity.getUuid())
                || delta < 0.0F || delta > 5.0F) {
            state = new RenderState(entity.getWorld(), entity.getUuid(), targetPosition,
                    targetDirection, ageTicks, worldTick);
            RENDER_STATES.put(entity.getId(), state);
        } else if (delta > 0.0F) {
            double positionResponse = 1.0 - Math.pow(0.34, delta);
            double directionResponse = 1.0 - Math.pow(0.42, delta);
            state.position = state.position.lerp(targetPosition, positionResponse);
            Vec3d blended = state.direction.multiply(1.0 - directionResponse)
                    .add(targetDirection.multiply(directionResponse));
            state.direction = blended.lengthSquared() < 1.0E-6 ? targetDirection : blended.normalize();
            state.lastAge = ageTicks;
            state.lastWorldTick = worldTick;
        }
        if (entity.age % 80 == 0) {
            long cutoff = worldTick - 100L;
            RENDER_STATES.entrySet().removeIf(entry -> entry.getKey() != entity.getId()
                    && (entry.getValue().world != entity.getWorld()
                    || entry.getValue().lastWorldTick < cutoff));
        }
        return new RenderPose(state.position.subtract(targetPosition), state.direction, state.position);
    }

public static void processCtrlAltNavigation(Identifier entry, String modId, Identifier customConfigPath, ItemStack itemStack, List<Text> tooltip) {
        String customPath;
        if (Screen.hasControlDown()) {
            // Note: ctrlKeyPressTimestamp is initialised in addDynamicButtonTooltip(),
            // which is called earlier in the same tooltip-render frame.

            // Show error message in tooltip if no info mods installed
            if (!Platform.isModLoaded("oracle_index") && !Platform.isModLoaded("roughlyenoughitems") && !Platform.isModLoaded("emi")) {
                tooltip.add(Text.translatable("message.simplyswords.documentation.error").setStyle(Styles.TEXT));
                tooltip.add(Text.translatable("message.simplyswords.documentation.error2").setStyle(Styles.TEXT));
            }

            if ((System.currentTimeMillis() - ctrlKeyPressTimestamp) >= 500) {
                if (Screen.hasAltDown()) {
                    if (customConfigPath == null) {
                        TooltipUtils.openFzzyConfig(modId);
                    }
                    else {
                        customPath = customConfigPath.getPath().replace(modId+":", "");
                        TooltipUtils.openFzzyConfig(customPath);
                    }
                    ctrlKeyPressTimestamp = 0;
                } else if (Platform.isModLoaded("oracle_index")) {
                    // Do NOT reset ctrlKeyPressTimestamp here — the gradient must continue
                    // running from 500 ms up to 1 200 ms so the icon finishes filling.
                    // OracleIndexUtils guards against re-setting pendingSetTime on repeat calls.
                    OracleIndexUtils.openOracleIndex(entry, modId);
                } else {
                    // REI / EMI open instantly, so the gradient can stop immediately.
                    if (Platform.isModLoaded("roughlyenoughitems")) ReiUtils.openRei(entry, modId, itemStack);
                    else if (Platform.isModLoaded("emi")) EmiUtils.openEmi(entry, modId, itemStack);
                    ctrlKeyPressTimestamp = 0;
                }
            }
        } else {
            ctrlKeyPressTimestamp = 0;
        }
    }

public static <T> LiteralArgumentBuilder<T> create(
			Function<String, LiteralArgumentBuilder<T>> literalFactory,
			ArgumentFactory<T> argumentFactory,
			BiConsumer<T, Component> sendSuccess,
			BiConsumer<T, Component> sendFailure) {
		return literalFactory.apply(Jade.ID + "c").then(literalFactory.apply("handlers").executes(context -> {
			File file = new File("jade_handlers.md");
			try (FileWriter writer = new FileWriter(file)) {
				writer.write(DumpGenerator.generateInfoDump());
				sendSuccess.accept(context.getSource(), Component.translatable("command.jade.dump.success"));
				return 1;
			} catch (IOException e) {
				sendFailure.accept(context.getSource(), Component.literal(e.getClass().getSimpleName() + ": " + e.getMessage()));
				return 0;
			}
		})).then(literalFactory.apply("config").executes(_ -> {
			// execute in the next tick because when we press enter in chat, after the command is executed, any screen will be closed
			Minecraft.getInstance().schedule(() -> {
				IWailaConfig.get().invalidate();
				Minecraft.getInstance().gui.setScreen(new HomeConfigScreen(null));
			});
			return 1;
		})).then(literalFactory.apply("use_profile")
				.then(argumentFactory.apply("index", IntegerArgumentType.integer(0, 3)).executes(context -> {
					int index = IntegerArgumentType.getInteger(context, "index");
					Minecraft.getInstance().execute(() -> Jade.useProfile(index));
					return 1;
				}))
		).then(literalFactory.apply("pin").executes(_ -> {
			Minecraft.getInstance().schedule(() -> Minecraft.getInstance().gui.setScreen(new PinScreen()));
			return 1;
		})).then(literalFactory.apply("generate_server_overrides")
				.executes(context -> generate(context.getSource(), sendSuccess, sendFailure, null))
				.then(argumentFactory.apply("pattern", StringArgumentType.greedyString())
						.executes(context -> {
							String pattern = StringArgumentType.getString(context, "pattern");
							return generate(context.getSource(), sendSuccess, sendFailure, pattern);
						})));
	}

private Vec3d update(int index, Vec3d desired, Vec3d normal, float time, byte mode) {
            LegState state = legs[index];
            if (state == null) {
                state = new LegState(desired, normal);
                legs[index] = state;
            }
            if (mode == SoulstalkerStrideEntity.SURFACE_AIRBORNE) {
                state.planted = state.planted.lerp(desired, 0.38);
                state.stepNormal = normal;
                state.stepping = false;
                state.pendingTransition = false;
                return state.planted;
            }
            if (commandedLeg == index) {
                state.begin(desired, normal, time);
                state.pendingTransition = false;
                commandedLeg = -1;
            } else if (state.pendingTransition
                    && time >= modeChangedAt + transitionRank(index) * 1.0F) {
                state.begin(desired, normal, time);
                state.pendingTransition = false;
            } else if (!state.stepping && state.planted.squaredDistanceTo(desired) > 12.0) {
                state.begin(desired, normal, time - 2.5F);
            }
            if (state.stepping) {
                float progress = MathHelper.clamp((time - state.stepStarted) / 5.0F, 0.0F, 1.0F);
                float eased = ease(progress);
                Vec3d point = state.stepStart.lerp(state.stepTarget, eased)
                        .add(state.stepNormal.multiply(Math.sin(progress * Math.PI)
                                * (mode == SoulstalkerStrideEntity.SURFACE_WALL ? 0.24 : 0.42)));
                if (progress >= 1.0F) {
                    state.planted = state.stepTarget;
                    state.stepping = false;
                    return state.planted;
                }
                return point;
            }
            return state.planted;
        }

