@Override
    public void channelRead(final ChannelHandlerContext ctx, final Object msg) throws Exception {
        long size = calculateSize(msg);
        long now = TrafficCounter.milliSecondFromNano();
        if (size > 0) {
            // compute the number of ms to wait before reopening the channel
            long wait = trafficCounter.readTimeToWait(size, readLimit, maxTime, now);
            wait = checkWaitReadTime(ctx, wait, now);
            if (wait >= MINIMAL_WAIT) { // At least 10ms seems a minimal
                // time in order to try to limit the traffic
                // Only AutoRead AND HandlerActive True means Context Active
                Channel channel = ctx.channel();
                ChannelConfig config = channel.config();
                if (logger.isDebugEnabled()) {
                    logger.debug("Read suspend: " + wait + ':' + config.isAutoRead() + ':'
                            + isHandlerActive(ctx));
                }
                if (config.isAutoRead() && isHandlerActive(ctx)) {
                    config.setAutoRead(false);
                    channel.attr(READ_SUSPENDED).set(true);
                    // Create a Runnable to reactive the read if needed. If one was create before it will just be
                    // reused to limit object creation
                    Attribute<Runnable> attr = channel.attr(REOPEN_TASK);
                    Runnable reopenTask = attr.get();
                    if (reopenTask == null) {
                        reopenTask = new ReopenReadTimerTask(ctx);
                        attr.set(reopenTask);
                    }
                    ctx.executor().schedule(reopenTask, wait, TimeUnit.MILLISECONDS);
                    if (logger.isDebugEnabled()) {
                        logger.debug("Suspend final status => " + config.isAutoRead() + ':'
                                + isHandlerActive(ctx) + " will reopened at: " + wait);
                    }
                }
            }
        }
        informReadOperation(ctx, now);
        ctx.fireChannelRead(msg);
    }

private static void groundSlamEntity(Player attacker, LivingEntity target, ItemModularHandheld item, ItemStack itemStack, Vec3 origin,
            double damageMultiplier, int slowDuration, double momentumEfficiency, int revengeLevel) {
        ServerScheduler.schedule(target.blockPosition().distManhattan(BlockPos.containing(origin)) - 3, () -> {
            float knockback = momentumEfficiency > 0 ? 0.1f : 0.5f;

            AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockback, knockback);

            if (momentumEfficiency > 0) {
                target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.GENERIC_BIG_FALL, SoundSource.PLAYERS, 1, 0.7f);
            } else {
                target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.9f);
            }

            if (result != AbilityUseResult.fail) {
                if (slowDuration > 0) {
                    target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, slowDuration, 1, false, true));
                }

                if (momentumEfficiency > 0) {
                    double velocity = momentumEfficiency;
                    velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                    target.push(0, velocity, 0);
                    target.addEffect(new MobEffectInstance(StunPotionEffect.instance, 40, 0, false, false));
                }

                if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                    target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
                    RevengeTracker.removeEnemySynced((ServerPlayer) attacker, target);
                }
            }

            if (result == AbilityUseResult.crit) {
                RandomSource rand = target.getRandom();
                CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                        world.sendParticles(ParticleTypes.CRIT,
                                target.getX(), target.getY(), target.getZ(), 10,
                                rand.nextGaussian() * 0.3, rand.nextGaussian() * 0.5, rand.nextGaussian() * 0.3, 0.1f));
            }
        });
    }

private void setBlock(ServerLevel level, BlockPos pos) {
        if (delay > 0 || randomDelay > 0) {
            int actualDelay = delay + (randomDelay > 0 ? level.getRandom().nextInt(randomDelay) : 0);
            ServerScheduler.schedule(actualDelay, () -> {
                if (blockState.canSurvive(level, pos) && testRequirements(level, level.getBlockState(pos), pos)) {
                    level.setBlock(pos, blockState, Block.UPDATE_ALL);
                    if (particle != null) {
                        level.sendParticles(particle, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
                                8, 0.5, 0.5, 0.5, 0.1);
                    }
                    if (sound != null) {
                        level.playSound(null, pos, sound.type, SoundSource.BLOCKS, sound.volume, sound.pitch);
                    }
                }
            });
            if (intervalParticle != null && fxInterval > 0) {
                for (int i = 1; i * fxInterval < actualDelay; i++) {
                    ServerScheduler.schedule(i * fxInterval, () -> level.sendParticles(intervalParticle, pos.getX() + 0.5, pos.getY() + 0.5,
                            pos.getZ() + 0.5,
                            8, 0.5, 0.5, 0.5, 0.1));
                }
            }
            if (intervalSound != null && fxInterval > 0) {
                for (int i = 1; i * fxInterval < actualDelay; i++) {
                    float volume = intervalSound.volume + i * intervalSoundVolumeChange;
                    float pitch = intervalSound.pitch + i * intervalSoundPitchChange;
                    ServerScheduler.schedule(i * fxInterval, () -> level.playSound(null, pos, intervalSound.type, SoundSource.PLAYERS, volume,
                            pitch));
                }
            }
        } else {
            level.setBlock(pos, blockState, Block.UPDATE_ALL);
            if (particle != null) {
                level.sendParticles(particle, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
                        8, 0.5, 0.5, 0.5, 0.1);
            }
            if (sound != null) {
                level.playSound(null, pos, sound.type, SoundSource.BLOCKS, sound.volume, sound.pitch);
            }
        }
    }

@Override
        public void connect(
                final SocketAddress remoteAddress,
                final SocketAddress localAddress, final ChannelPromise promise) {
            if (!promise.setUncancellable() || !ensureOpen(promise)) {
                return;
            }

            try {
                final boolean wasActive = isActive();
                doConnect(remoteAddress, localAddress);

                int waitTime = config().getOption(WAIT_TIME);
                if (waitTime > 0) {
                    eventLoop().schedule(new Runnable() {
                        @Override
                        public void run() {
                            try {
                                doInit();
                                safeSetSuccess(promise);
                                if (!wasActive && isActive()) {
                                    pipeline().fireChannelActive();
                                }
                            } catch (Throwable t) {
                                safeSetFailure(promise, t);
                                closeIfClosed();
                            }
                        }
                   }, waitTime, TimeUnit.MILLISECONDS);
                } else {
                    doInit();
                    safeSetSuccess(promise);
                    if (!wasActive && isActive()) {
                        pipeline().fireChannelActive();
                    }
                }
            } catch (Throwable t) {
                safeSetFailure(promise, t);
                closeIfClosed();
            }
        }

public static synchronized Optional<ObserverStatusEffectSnapshot> get(LivingEntity entity, Identifier effectId) {
        if (entity == null || effectId == null || entity.getWorld() == null) {
            return Optional.empty();
        }

        Identifier dimensionId = entity.getWorld().getRegistryKey().getValue();
        Map<UUID, Map<Identifier, StoredEffect>> dimensionEffects = EFFECTS.get(dimensionId);
        if (dimensionEffects == null) {
            return Optional.empty();
        }
        Map<Identifier, StoredEffect> entityEffects = dimensionEffects.get(entity.getUuid());
        if (entityEffects == null) {
            return Optional.empty();
        }
        StoredEffect stored = entityEffects.get(effectId);
        if (stored == null) {
            return Optional.empty();
        }

        long worldTime = entity.getWorld().getTime();
        if (!stored.infinite() && stored.expiryTick() <= worldTime) {
            entityEffects.remove(effectId);
            if (entityEffects.isEmpty()) {
                dimensionEffects.remove(entity.getUuid());
            }
            if (dimensionEffects.isEmpty()) {
                EFFECTS.remove(dimensionId);
            }
            return Optional.empty();
        }

        int remainingDuration = stored.infinite()
                ? -1
                : (int) Math.min(Integer.MAX_VALUE, stored.expiryTick() - worldTime);
        return Optional.of(new ObserverStatusEffectSnapshot(
                stored.amplifier(),
                remainingDuration,
                stored.infinite(),
                stored.ambient(),
                stored.showParticles(),
                stored.showIcon()));
    }

public boolean checkAndClear(ServerLevel level) {
		AABB bounds = getStructureBounds(level);

		if (bounds == null)
			return false;

		if (!level.isLoaded(BlockPos.containing(bounds.getCenter())))
			return true;

		List<Player> players = getPlayersInside(level, bounds);
		List<Entity> entities = getEntitiesInside(level, bounds);

		if (!players.isEmpty()) {
			boolean keepArena = false;

			for (Entity entity : entities) {
				if (entity instanceof ItemEntity || entity.getType().is(Tags.EntityTypes.BOSSES)) {
					keepArena = true;

					break;
				}
			}

			if (keepArena)
				return false;

			for (Player player : players) {
				AoAScheduler.schedule(1, tick -> {
					ServerPlayer pl = (ServerPlayer)player;
					PlayerUtil.resetToDefaultStatus(pl);
					pl.teleportTo(pl.serverLevel(), 17.5d, 452.5d, 3.5d, Set.of(), 0, pl.getXRot());
					InventoryUtil.clearItems(pl, AoAItems.RETURN_CRYSTAL);
					PlayerUtil.getAdventPlayer(pl).storage.returnStoredItems();
				});
			}
		}

		for (Entity entity : entities) {
			entity.discard();
		}

		return true;
	}

public static void breakBlocks(ItemModularHandheld item, ItemStack itemStack, int effectLevel, ServerLevel world, BlockState state, BlockPos pos, LivingEntity entity) {
        Player player = CastOptional.cast(entity, Player.class).orElse(null);

        if (player != null && effectLevel > 0) {
            Vec3 entityPosition = entity.getEyePosition(0);
            double lookDistance = Optional.ofNullable(entity.getAttribute(ForgeMod.BLOCK_REACH.get()))
                    .map(AttributeInstance::getValue)
                    .orElse(5d);

            Vec3 lookingPosition = entity.getLookAngle().scale(lookDistance).add(entityPosition);
            BlockHitResult rayTrace = world.clip(new ClipContext(entityPosition, lookingPosition,
                    ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, entity));

            Direction direction = rayTrace.getType() == HitResult.Type.BLOCK
                    ? rayTrace.getDirection().getOpposite()
                    : Direction.orderedByNearest(entity)[0];

            float referenceHardness = state.getDestroySpeed(world, pos);
            ToolAction referenceTool = ToolActionHelper.getAppropriateTools(state).stream()
                    .filter(tool -> item.canPerformAction(itemStack, tool))
                    .findFirst()
                    .orElse(null);

            if (referenceTool != null && item.getToolLevel(itemStack, referenceTool) > 0) {
                double critMultiplier = CritEffect.rollMultiplier(entity.getRandom(), item, itemStack);
                if (critMultiplier != 1) {
                    effectLevel *= critMultiplier;
                    world.sendParticles(ParticleTypes.ENCHANTED_HIT, pos.getX() + .5f, pos.getY() + .5f, pos.getZ() + .5f, 15, 0.2D, 0.2D, 0.2D, 0.0D);
                }

                Vec3i limiter = getLimiter(item, direction, player.getDirection(), itemStack);

                List<BlockPos> positions = new LinkedList<>(getRegularOffsets(pos, pos, limiter));
                List<BlockPos> backupPositions = new LinkedList<>(getBackupOffsets(pos, pos, limiter));

                int blockCount = effectLevel;
                ServerScheduler.schedule(player.getRandom().nextInt(3), () -> breakRecursive(world, player, item, itemStack, direction, pos,
                        limiter, positions, backupPositions, referenceHardness, referenceTool, blockCount));

                item.applyDamage(effectLevel, itemStack, entity);
                item.tickProgression(entity, itemStack, Mth.ceil(effectLevel / 2d));
            }
        }
    }

public static boolean performPourAction(ItemStack stack, LivingEntity entity, InteractionHand hand)
    {
        if (!(entity instanceof Player player && stack.is(ModItems.FILLED_WATERSKIN))) return false;

        // Play empty sound
        if (!player.level().isClientSide)
        {
            double temperature = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE);
            double wetnessTemp = 0.05 * CSMath.sign(temperature == 0 ? 1 : temperature);
            // Replace or add water temp modifier
            Placement modPlacement = Placement.of(Mode.REPLACE, Order.FIRST, mod -> mod instanceof WaterTempModifier).orElse(Placement.LAST);
            Temperature.addModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, modPlacement);

            WorldHelper.playEntitySound(ModSounds.WATERSKIN_POUR, player, player.getSoundSource(), 2f, (float) ((Math.random() / 5) + 0.9));
        }

        consumeWaterskin(stack, player, hand);
        MinecraftForge.EVENT_BUS.post(new LivingEntityUseItemEvent.Finish(player, stack, 1, stack.getCraftingRemainingItem()));
        player.swing(hand, true);

        // spawn falling water particles
        Random rand = new Random();
        for (int i = 0; i < 6; i++)
        {
            TaskScheduler.scheduleServer(() ->
            {
                ParticleBatchMessage particleBatch = new ParticleBatchMessage(2);
                for (int p = 0; p < 10; p++)
                {
                    AABB playerBB = player.getDimensions(player.getPose()).makeBoundingBox(player.position()).inflate(0.2);
                    particleBatch.addParticle(ParticleTypes.FALLING_WATER,
                                              Mth.lerp(rand.nextFloat(), playerBB.minX, playerBB.maxX),
                                              playerBB.maxY,
                                              Mth.lerp(rand.nextFloat(), playerBB.minZ, playerBB.maxZ),
                                              0.3, 0.3, 0.3);
                }
                particleBatch.sendEntity(player);
            }, i);
        }
        player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
        player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);

        return true;
    }

@Override
    public Result onEaten(ItemStack item, Chameleon entity, Entity thrower)
    {
        if (!entity.level().isClientSide)
        {
            // Flag for searching
            entity.setSearching(true);

            // Create a new thread to look for the biome
            Thread searchThread = new Thread(null, () ->
            {
                // Search for a cold biome
                BlockPos entityPos = WorldHelper.sublevelToWorld(entity.level(), entity.blockPosition());
                Pair<BlockPos, Holder<Biome>> biomePair = ((ServerLevel) entity.level()).findClosestBiome3d(biome -> this.biomePredicate.test(entity.level(), biome), entityPos, 2000, 32, 64);

                if (biomePair != null)
                {
                    TaskScheduler.scheduleServer(() ->
                    {
                        // Set the chameleon to track this position
                        entity.setTrackingPos(biomePair.getFirst());

                        WorldHelper.playEntitySound(ModSounds.CHAMELEON_FIND, entity, entity.getSoundSource(), 1.2f, entity.getVoicePitch());
                        WorldHelper.spawnParticleBatch(entity.level(), ParticleTypes.HAPPY_VILLAGER, entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), 1, 1, 1, 6, 0.01);

                        // Stop searching
                        entity.setSearching(false);
                    }, (int) (Math.random() * 20 + 40));
                }
                else
                {
                    TaskScheduler.scheduleServer(() ->
                    {
                        WorldHelper.spawnParticleBatch(entity.level(), ParticleTypes.SMOKE, entity.getX(), entity.getY() + entity.getBbHeight() / 2, entity.getZ(), 1, 1, 1, 6, 0.01);

                        // Stop searching
                        entity.setSearching(false);
                    }, (int) (Math.random() * 20 + 40));
                }
            }, "(Cold Sweat) Chameleon search thread");
            // Execute the search thread
            searchThread.start();
        }
        return Result.SUCCESS;
    }

@Override
                    public void initChannel(SocketChannel ch) {
                        ch.config().setAllocator(new TestByteBufAllocator(ch.config().getAllocator(), param.type));

                        ChannelPipeline p = ch.pipeline();

                        SslHandler handler = !param.delegate ?
                                serverSslCtx.newHandler(ch.alloc()) :
                                serverSslCtx.newHandler(ch.alloc(), delegatingExecutor);

                        p.addLast(handler);
                        p.addLast(new ChannelInboundHandlerAdapter() {
                            @Override
                            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                                if (evt instanceof SslHandshakeCompletionEvent &&
                                        ((SslHandshakeCompletionEvent) evt).isSuccess()) {
                                    // This data will be sent to the client before any of the re-negotiation data can be
                                    // sent. The client will read this, detect that it is not the response to
                                    // renegotiation which was expected, and respond with a fatal alert.
                                    ctx.writeAndFlush(ctx.alloc().buffer(1).writeByte(100));
                                }
                                ctx.fireUserEventTriggered(evt);
                            }

                            @Override
                            public void channelRead(final ChannelHandlerContext ctx, Object msg) {
                                ReferenceCountUtil.release(msg);
                                // The server then attempts to trigger a flush operation once the application data is
                                // received from the client. The flush will encrypt all data and should not result in
                                // deadlock.
                                ctx.channel().eventLoop().schedule(new Runnable() {
                                    @Override
                                    public void run() {
                                        ctx.writeAndFlush(ctx.alloc().buffer(1).writeByte(101));
                                    }
                                }, 500, TimeUnit.MILLISECONDS);
                            }

                            @Override
                            public void channelInactive(ChannelHandlerContext ctx) {
                                serverLatch.countDown();
                            }
                        });
                        serverConnectedChannel = ch;
                    }

private TerrainCache getCache(World world, UUID id,
                                  double centerX, double centerY, double centerZ,
                                  float scanExtent, float verticalRange, Palette palette) {
        long now = world.getTime();
        caches.entrySet().removeIf(entry ->
                entry.getValue().world != world
                        || now - entry.getValue().lastSeenTick > CACHE_GRACE_TICKS);
        bloodShapes.keySet().removeIf(shapeId ->
                !shapeId.equals(id)
                        && !caches.containsKey(shapeId)
                        && !bloodMasks.containsKey(shapeId));

        int requestedX = MathHelper.floor(centerX);
        int requestedY = MathHelper.floor(centerY);
        int requestedZ = MathHelper.floor(centerZ);
        int requiredScanRadius = MathHelper.ceil(scanExtent)
                + 2 + palette.movementMargin;
        boolean bloodPalette = palette.bloodStyle != null;
        int scanRadius = requiredScanRadius
                + (bloodPalette ? BLOOD_CACHE_GROWTH_MARGIN : 0);
        TerrainCache cache = caches.get(id);
        boolean movedOutsideMargin = cache != null && (bloodPalette
                ? requestedX - requiredScanRadius < cache.centerX - cache.scanRadius
                || requestedX + requiredScanRadius > cache.centerX + cache.scanRadius
                || requestedZ - requiredScanRadius < cache.centerZ - cache.scanRadius
                || requestedZ + requiredScanRadius > cache.centerZ + cache.scanRadius
                || Math.abs(requestedY - cache.centerY) > 1
                : Math.abs(requestedX - cache.centerX) > palette.movementMargin
                || Math.abs(requestedZ - cache.centerZ) > palette.movementMargin
                || Math.abs(requestedY - cache.centerY) > 1);
        boolean rebuild = cache == null
                || cache.world != world
                || movedOutsideMargin
                || (!bloodPalette && cache.scanRadius != scanRadius)
                || Float.compare(cache.verticalRange, verticalRange) != 0
                || cache.palette != palette
                || now - cache.lastRefreshTick >= palette.refreshTicks;
        if (rebuild) {
            cache = buildCache(
                    world, requestedX, requestedY, requestedZ,
                    scanRadius, verticalRange, palette, now);
            caches.put(id, cache);
        }
        cache.lastSeenTick = now;
        return cache;
    }

private void spawnGroundParticles(Level world, Vec3 origin, Vec3 direction, double yaw, double range) {
        RandomSource rand = world.getRandom();

        BlockState originState = world.getBlockState(BlockPos.containing(origin));
        ((ServerLevel) world).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, originState),
                origin.x(), origin.y(), origin.z(),
                8, 0, rand.nextGaussian() * 0.1, 0, 0.1);
        world.playSound(null, BlockPos.containing(origin), originState.getSoundType().getBreakSound(), SoundSource.PLAYERS, 1.5f, 0.5f);

        int bound = (int) Math.ceil(range / 2);

        BlockPos center = BlockPos.containing(origin.add(direction.scale(range / 2)));
        origin = origin.add(direction.scale(-1));
        BlockPos.MutableBlockPos targetPos = new BlockPos.MutableBlockPos(0, 0, 0);
        for (int x = -bound; x <= bound; x++) {
            for (int z = -bound; z <= bound; z++) {
                targetPos.setWithOffset(center, x, 0, z);
                if (compareAngle(origin, targetPos, yaw)) {
                    for (int y = -2; y < 2; y++) {
                        targetPos.setWithOffset(center, x, y, z);
                        BlockState targetState = world.getBlockState(targetPos);
                        if (targetState.canOcclude() && !world.getBlockState(targetPos.above()).canOcclude()) {
                            targetPos.below();

                            double distance = targetPos.distToCenterSqr(origin.x, origin.y, origin.z);

                            if (distance < range * range) {
                                double yOffset = targetState.getShape(world, targetPos).bounds().maxY;
                                BlockPos particlePos = targetPos.immutable();

                                ServerScheduler.schedule(particlePos.distManhattan(BlockPos.containing(origin)) - 3, () -> {
                                    ((ServerLevel) world).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, targetState),
                                            particlePos.getX() + 0.5, particlePos.getY() + yOffset, particlePos.getZ() + 0.5,
                                            3, 0, rand.nextGaussian() * 0.1, 0, 0.1);

                                    if (rand.nextFloat() < 0.3f) {
                                        world.playSound(null, particlePos, targetState.getSoundType().getFallSound(), SoundSource.PLAYERS, 1, 0.5f);
                                    }
                                });
                            }
                            break;
                        }
                    }
                }
            }
        }
    }

private static void renderWoundBurst(DreadwhisperVisualEntity entity, float tickDelta, MatrixStack matrices) {
        float age = entity.age + tickDelta;
        float progress = MathHelper.clamp(age / Math.max(1.0F, entity.getLifetime()), 0.0F, 1.0F);
        float eased = 1.0F - (1.0F - progress) * (1.0F - progress);
        float fade = 1.0F - smooth(progress);
        float flash = 1.0F - smooth(MathHelper.clamp(age / 3.2F, 0.0F, 1.0F));
        float span = Math.max(entity.getVisualWidth(), entity.getVisualHeight() * 0.46F);
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer field = IonDeferredRenderController.getFieldBuffer();
        diamond(field, matrix, Vec3d.ZERO, new Vec3d(1.0, 0.0, 0.0),
                entity.getVisualWidth() * (0.34F + flash * 0.16F),
                entity.getVisualHeight() * (0.2F + flash * 0.08F),
                VOID_BLACK, alpha((205.0F + flash * 35.0F) * fade));
        for (int i = 0; i < 10; i++) {
            Vec3d direction = burstDirection(entity.getSeed(), i, 10);
            Vec3d side = perpendicular(direction);
            Vec3d up = side.crossProduct(direction).normalize();
            float distance = eased * span * (0.28F + noise(entity.getSeed() + 149, i) * 1.05F);
            Vec3d center = direction.multiply(distance);
            float width = span * (0.065F + noise(entity.getSeed() + 211, i) * 0.075F);
            float height = span * (0.09F + noise(entity.getSeed() + 239, i) * 0.11F);
            Vec3d trailStart = center.subtract(direction.multiply(span * (0.16F + noise(entity.getSeed() + 263, i) * 0.2F)));
            ribbon(field, matrix, trailStart, center, side, width * 0.28F,
                    VOID_BLACK, alpha(118.0F * fade));
            tornFragment(field, matrix, center, side, up, width, height,
                    i % 3 == 0 ? MID_PURPLE : DEEP_PURPLE, alpha(205.0F * fade));
        }
        VertexConsumer energy = IonDeferredRenderController.getLightningBuffer();
        diamond(energy, matrix, Vec3d.ZERO, new Vec3d(1.0, 0.0, 0.0),
                entity.getVisualWidth() * (0.2F + flash * 0.16F),
                entity.getVisualHeight() * (0.12F + flash * 0.1F),
                SICKLY_GREEN, alpha(248.0F * flash));
        diamond(energy, matrix, Vec3d.ZERO, new Vec3d(0.0, 0.0, 1.0),
                entity.getVisualWidth() * (0.16F + flash * 0.12F),
                entity.getVisualHeight() * (0.1F + flash * 0.08F),
                PALE_GREEN, alpha(235.0F * flash));
        for (int i = 0; i < 10; i++) {
            Vec3d direction = burstDirection(entity.getSeed(), i, 10);
            Vec3d side = perpendicular(direction);
            Vec3d up = side.crossProduct(direction).normalize();
            float distance = eased * span * (0.28F + noise(entity.getSeed() + 149, i) * 1.05F);
            Vec3d center = direction.multiply(distance).add(direction.multiply(0.003F));
            float width = span * (0.03F + noise(entity.getSeed() + 211, i) * 0.035F);
            float height = span * (0.045F + noise(entity.getSeed() + 239, i) * 0.05F);
            tornFragment(energy, matrix, center, side, up, width, height,
                    i % 3 == 0 ? SICKLY_GREEN : REND_PURPLE, alpha(238.0F * fade));
        }
    }

private static void renderCorridor(IonboundStormscaleVisualEntity entity, float age,
                                       MatrixStack matrices, VertexConsumerProvider consumers) {
        float materialize = Math.max(1, entity.getMaterializeTicks());
        float holdEnds = materialize + Math.max(1, entity.getHoldTicks());
        float closeTicks = Math.max(1, entity.getCloseTicks());
        float rise = ease(MathHelper.clamp(age / materialize, 0.0F, 1.0F));
        float close = ease(MathHelper.clamp((age - holdEnds) / closeTicks, 0.0F, 1.0F));
        float halfWidth = entity.getVisualWidth() * 0.5F * (1.0F - close);
        float height = entity.getVisualHeight() * rise;
        float sink = (1.0F - rise) * entity.getVisualHeight();

        matrices.push();
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-entity.getYaw()));
        matrices.translate(0.0, -sink, 0.0);
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        int segments = Math.max(4, MathHelper.ceil(entity.getLength() / 1.5F));
        float segmentLength = entity.getLength() / segments;
        VertexConsumer faces = IonDeferredRenderController.getFieldBuffer();
        for (int wall = -1; wall <= 1; wall += 2) {
            float x = halfWidth * wall;
            for (int i = 0; i < segments; i++) {
                float z0 = i * segmentLength + 0.025F;
                float z1 = (i + 1) * segmentLength - 0.025F;
                int color = (i + wall & 1) == 0 ? DARK_BLUE : 0x153B78;
                quad(faces, matrix, new Vec3d(x, 0.0, z0), new Vec3d(x, 0.0, z1),
                        new Vec3d(x, height, z1), new Vec3d(x, height, z0), color, 66);
            }
        }

        VertexConsumer lightning = IonDeferredRenderController.getLightningBuffer();
        for (int wall = -1; wall <= 1; wall += 2) {
            float x = halfWidth * wall;
            drawBolt(lightning, matrix, new Vec3d(x, 0.0, 0.0), new Vec3d(x, height, 0.0),
                    entity.getSeed() + wall * 31L, age, 0.038F, 0.93F);
            drawBolt(lightning, matrix, new Vec3d(x, 0.0, entity.getLength()),
                    new Vec3d(x, height, entity.getLength()), entity.getSeed() + wall * 67L, age, 0.038F, 0.93F);
            for (int i = 0; i <= segments; i++) {
                float z = i * segmentLength;
                drawBolt(lightning, matrix, new Vec3d(x, 0.0, z), new Vec3d(x, height, z),
                        entity.getSeed() + wall * 101L + i * 3571L, age, 0.024F, 0.62F);
            }
            for (int row = 0; row <= 2; row++) {
                float y = height * row / 2.0F;
                drawBolt(lightning, matrix, new Vec3d(x, y, 0.0), new Vec3d(x, y, entity.getLength()),
                        entity.getSeed() + wall * 151L + row * 7283L, age, 0.030F, 0.75F);
            }
        }
        matrices.pop();
    }

public static void main(String[] args) throws Exception {
        ServerBootstrap bootstrap = new ServerBootstrap().group(
                new MultiThreadIoEventLoopGroup(NioIoHandler.newFactory()))
                .channel(NioServerSocketChannel.class)
                .handler(new LoggingHandler(LogLevel.INFO))
                .childHandler(new ChannelInitializer<Channel>() {
                    @Override
                    protected void initChannel(Channel ch) throws Exception {
                        ch.pipeline().addLast(new TcpDnsQueryDecoder(), new TcpDnsResponseEncoder(),
                                new SimpleChannelInboundHandler<DnsQuery>() {
                                    @Override
                                    protected void channelRead0(ChannelHandlerContext ctx,
                                                                DnsQuery msg) throws Exception {
                                        DnsQuestion question = msg.recordAt(DnsSection.QUESTION);
                                        System.out.println("Query domain: " + question);

                                        //always return 192.168.1.1
                                        ctx.writeAndFlush(newResponse(msg, question, 600, QUERY_RESULT));
                                    }

                                    private DefaultDnsResponse newResponse(DnsQuery query,
                                                                           DnsQuestion question,
                                                                           long ttl, byte[]... addresses) {
                                        DefaultDnsResponse response = new DefaultDnsResponse(query.id());
                                        response.addRecord(DnsSection.QUESTION, question);

                                        for (byte[] address : addresses) {
                                            DefaultDnsRawRecord queryAnswer = new DefaultDnsRawRecord(
                                                    question.name(),
                                                    DnsRecordType.A, ttl, Unpooled.wrappedBuffer(address));
                                            response.addRecord(DnsSection.ANSWER, queryAnswer);
                                        }
                                        return response;
                                    }
                                });
                    }
                });
        final Channel channel = bootstrap.bind(DNS_SERVER_PORT).channel();
        Executors.newSingleThreadScheduledExecutor().schedule(new Runnable() {
            @Override
            public void run() {
                try {
                    clientQuery();
                    channel.close();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }, 1000, TimeUnit.MILLISECONDS);
        channel.closeFuture().sync();
    }

private static void renderLeechHit(DreadwhisperVisualEntity entity, float tickDelta, MatrixStack matrices) {
        float age = entity.age + tickDelta;
        float progress = MathHelper.clamp(age / Math.max(1.0F, entity.getLifetime()), 0.0F, 1.0F);
        float fade = 1.0F - smooth(progress);
        float burst = smooth(MathHelper.clamp(age / 2.0F, 0.0F, 1.0F));
        LivingEntity owner = entity.getOwner();
        Vec3d ownerPoint = owner == null ? new Vec3d(0.0, 0.7, 0.0)
                : owner.getLerpedPos(tickDelta).add(0.0, owner.getHeight() * 0.55, 0.0)
                .subtract(entity.getLerpedPos(tickDelta));
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer field = IonDeferredRenderController.getFieldBuffer();

        for (int i = 0; i < 10; i++) {
            float angle = MathHelper.TAU * i / 10.0F + noise(entity.getSeed(), i) * 0.5F;
            Vec3d direction = new Vec3d(MathHelper.sin(angle),
                    (noise(entity.getSeed() + 29, i) - 0.28F) * 0.85F,
                    MathHelper.cos(angle)).normalize();
            Vec3d side = perpendicular(direction);
            Vec3d start = direction.multiply(entity.getVisualWidth() * 0.12F);
            Vec3d end = direction.multiply(entity.getVisualWidth() * (0.5F + noise(entity.getSeed() + 53, i) * 0.8F) * burst);
            ribbon(field, matrix, start, end, side, 0.055F, DEEP_PURPLE, alpha(172.0F * fade));
        }

        VertexConsumer energy = IonDeferredRenderController.getLightningBuffer();
        for (int i = 0; i < 10; i++) {
            float angle = MathHelper.TAU * i / 10.0F + noise(entity.getSeed(), i) * 0.5F;
            Vec3d direction = new Vec3d(MathHelper.sin(angle),
                    (noise(entity.getSeed() + 29, i) - 0.28F) * 0.85F,
                    MathHelper.cos(angle)).normalize();
            Vec3d side = perpendicular(direction);
            Vec3d start = direction.multiply(entity.getVisualWidth() * 0.12F);
            Vec3d end = direction.multiply(entity.getVisualWidth() * (0.5F + noise(entity.getSeed() + 53, i) * 0.8F) * burst);
            ribbon(energy, matrix, start, end, side, 0.018F,
                    i % 3 == 0 ? SICKLY_GREEN : REND_PURPLE, alpha(238.0F * fade));
        }

        if (owner != null && ownerPoint.lengthSquared() > 0.25) {
            for (int stream = 0; stream < 3; stream++) {
                Vec3d offset = perpendicular(ownerPoint).multiply((stream - 1) * 0.13F);
                Vec3d start = offset;
                Vec3d end = ownerPoint.add(offset.multiply(-0.35));
                Vec3d midpoint = start.add(end).multiply(0.5)
                        .add(0.0, 0.45F + stream * 0.11F, 0.0)
                        .add(perpendicular(end.subtract(start)).multiply((stream - 1) * 0.18F));
                curvedRibbon(energy, matrix, start, midpoint, end, 7, 0.026F,
                        stream == 1 ? PALE_GREEN : SICKLY_GREEN, alpha(218.0F * fade));
                float pulse = fract(progress * 2.25F - stream * 0.18F);
                Vec3d pulsePoint = quadratic(start, midpoint, end, pulse);
                diamond(energy, matrix, pulsePoint, perpendicular(ownerPoint), 0.13F, 0.13F,
                        PALE_GREEN, alpha(245.0F * fade));
            }
        }
    }

private static void renderBeam(IonboundStormscaleVisualEntity entity, Entity owner, float age, float tickDelta,
                                   MatrixStack matrices, VertexConsumerProvider consumers) {
        float life = Math.max(1.0F, entity.getLifetime());
        float appear = ease(MathHelper.clamp(age / 3.0F, 0.0F, 1.0F));
        float fade = ease(MathHelper.clamp((life - age) / 7.0F, 0.0F, 1.0F));
        float half = entity.getVisualWidth() * 0.5F * appear;
        float ownerHeight = owner == null ? Math.max(0.8F, entity.getVisualHeight()) : Math.max(0.8F, owner.getHeight());
        float beamYaw = owner == null ? entity.getYaw(tickDelta) : owner.getYaw(tickDelta);
        float beamPitch = owner == null ? entity.getPitch(tickDelta) : owner.getPitch(tickDelta);
        matrices.push();
        if (isFirstPersonOwner(owner)) {
            MinecraftClient client = MinecraftClient.getInstance();
            Vec3d cameraOffset = client.gameRenderer.getCamera().getPos()
                    .subtract(owner.getLerpedPos(tickDelta));
            Vector3f cameraUp = client.gameRenderer.getCamera().getVerticalPlane();
            matrices.translate(cameraOffset.x - cameraUp.x * 0.9F,
                    cameraOffset.y - cameraUp.y * 0.9F,
                    cameraOffset.z - cameraUp.z * 0.9F);
        } else {
            matrices.translate(0.0, ownerHeight * 0.68F, 0.0);
        }
        matrices.multiply(RotationAxis.POSITIVE_Y.rotationDegrees(-beamYaw));
        matrices.multiply(RotationAxis.POSITIVE_X.rotationDegrees(beamPitch));
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer core = IonDeferredRenderController.getFieldBuffer();
        quad(core, matrix, new Vec3d(-half, -half, 0.0), new Vec3d(half, -half, 0.0),
                new Vec3d(half, -half, entity.getLength()), new Vec3d(-half, -half, entity.getLength()),
                PALE_BLUE, Math.round(205 * fade));
        quad(core, matrix, new Vec3d(-half, half, 0.0), new Vec3d(-half, half, entity.getLength()),
                new Vec3d(half, half, entity.getLength()), new Vec3d(half, half, 0.0),
                WHITE_BLUE, Math.round(235 * fade));
        quad(core, matrix, new Vec3d(-half, -half, 0.0), new Vec3d(-half, -half, entity.getLength()),
                new Vec3d(-half, half, entity.getLength()), new Vec3d(-half, half, 0.0),
                ION_BLUE, Math.round(190 * fade));
        quad(core, matrix, new Vec3d(half, -half, 0.0), new Vec3d(half, half, 0.0),
                new Vec3d(half, half, entity.getLength()), new Vec3d(half, -half, entity.getLength()),
                ION_BLUE, Math.round(190 * fade));

        for (int i = 0; i < 3; i++) {
            float travel = ((age * 0.48F + i * entity.getLength() / 3.0F) % entity.getLength());
            renderBeamCharge(core, matrix, travel, Math.max(half * 1.5F, 0.22F),
                    Math.max(0.12F, entity.getVisualWidth() * 0.18F), Math.round(220 * fade));
        }

        VertexConsumer arcs = IonDeferredRenderController.getLightningBuffer();
        for (int i = 0; i < 5; i++) {
            float x = MathHelper.lerp(i / 4.0F, -half, half);
            float yy = (i & 1) == 0 ? -half * 0.55F : half * 0.55F;
            drawBolt(arcs, matrix, new Vec3d(x, yy, 0.0), new Vec3d(x, yy, entity.getLength()),
                    entity.getSeed() + i * 9151L, age * 1.8F, 0.042F, fade);
        }
        matrices.pop();
    }

@Override
	public void run(int tick) {
		if (shooter == null || target == null || shooter.level().isClientSide || !shooter.blockPosition().equals(shooterPos) || !target.blockPosition().equals(targetPos)) {
			resetStates();

			return;
		}

		float healthPercent = 1 - (GlobalEvents.tick - startingTick) / 200f;
		float targetPostHealth = targetStartHealth * healthPercent;
		float shooterPostHealth = shooterStartHealth * healthPercent;

		if (targetTurn) {
			if (target.getHealth() == 0) {
				resetStates();

				return;
			}

			if (targetPostHealth <= 0) {
				resetStates();
				DamageUtil.doRecoilAttack(target, target.getHealth() - targetPostHealth);
				target.setDeltaMovement(0, 0, 0);

				if (shooter instanceof Player pl) {
					target.setLastHurtByPlayer(pl);
				}
				else {
					target.setLastHurtByMob(shooter);
				}
			}
			else {
				target.setHealth(targetPostHealth);
			}

			((ServerLevel)shooter.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, target.getX(), target.getY() + target.getBbHeight(), target.getZ(), (int)Math.ceil(10 * healthPercent), 0, 0, 0, 0);
		}
		else {
			if (!(shooter instanceof Player) || !((Player)shooter).isCreative()) {
				if (shooterPostHealth <= 0) {
					resetStates();
					DamageUtil.doRecoilAttack(shooter, shooter.getHealth() - shooterPostHealth);
				}
				else {
					shooter.setHealth(shooterPostHealth);
				}

				((ServerLevel)shooter.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, shooter.getX(), shooter.getY() + shooter.getBbHeight(), shooter.getZ(), (int)Math.ceil(10 * healthPercent), 0, 0, 0, 0);
			}
		}

		targetTurn = !targetTurn;

		AoAScheduler.schedule(1, this);
	}

@Override
	protected ItemInteractionResult useItemOn(ItemStack stack, BlockState state, Level level, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hitResult) {
		if (!WorldUtil.isWorld(level, AoADimensions.NOWHERE))
			return InteractionResults.BlockUseItemOn.noActionTaken();

		if (level.getDifficulty() == Difficulty.PEACEFUL) {
			if (!level.isClientSide && hand == InteractionHand.MAIN_HAND)
				player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.difficulty"), ChatFormatting.RED));

			return InteractionResults.BlockUseItemOn.noActionTaken();
		}

		ItemStack heldItem = player.getItemInHand(hand);
		BossTokenItem bossItem;
		EntityType<?> entityType;

		if ((bossItem = getEntityTypeFromStack(heldItem)) == null || (entityType = bossItem.getEntityType(heldItem)) == null) {
			if (hand == InteractionHand.OFF_HAND && !level.isClientSide())
				player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.badItem"), ChatFormatting.RED));

			return InteractionResults.BlockUseItemOn.noActionTaken();
		}

		if (level instanceof ServerLevel serverLevel) {
			AABB teleportBounds = new AABB(pos.getX() - 3, pos.getY(), pos.getZ() - 3, pos.getX() + 4, pos.getY() + 3, pos.getZ() + 3);
			List<Player> players = EntityRetrievalUtil.getPlayers(level, teleportBounds, LivingEntity::isAlive);

			if (players.isEmpty()) {
				player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.tooFar"), ChatFormatting.RED));

				return InteractionResults.BlockUseItemOn.noActionTaken();
			}

			NowhereBossArena arena = NowhereBossArena.getFreeArena(serverLevel);

			if (arena == null) {
				player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.full"), ChatFormatting.RED));
			}
			else {
				BlockEntity blockEntity = level.getBlockEntity(pos);

				if (blockEntity instanceof BossAltarBlockEntity bossAltar) {
					if (bossAltar.getCurrentEntity() != null) {
						player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.inUse"), ChatFormatting.RED));

						return InteractionResults.BlockUseItemOn.noActionTaken();
					}

					bossAltar.updateEntity(entityType);
					AoAScheduler.schedule(95, tick -> bossAltar.updateEntity(null));
				}

				arena.placePlayersAndBoss(serverLevel, players, pl -> pl.level() == level && pl.isAlive() && teleportBounds.contains(pl.position()), heldItem, entityType, bossItem::spawnBoss);
			}
		}

		return InteractionResults.BlockUseItemOn.succeedAndSwingArmBothSides(level.isClientSide);
	}

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            var source = event.getSource().getEntity();
            var damage = event.getOriginalDamage();
            var entity = event.getEntity();

            var level = entity.level();
            var random = level.getRandom();

            if (damage >= 1) {
                for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.REFLECTIVE_NECKLACE.get())) {
                    var relic = (ReflectiveNecklaceItem) stack.getItem();

                    if (level.getRandom().nextDouble() > relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("chance").getValue())
                        continue;

                    var orbDamage = Math.clamp((float) (damage * relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("damage").getValue()), Float.MIN_VALUE, Float.MAX_VALUE);

                    var orb = new ReflectiveOrbEntity(RelicsEntities.REFLECTIVE_ORB.get(), level);

                    orb.setPiercings(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("piercing").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("piercings").getValue() : 0);
                    orb.setBounces(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("bounce").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("bounces").getValue() : 0);
                    orb.setStun(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("stun").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("stun").getValue() : 0);
                    orb.setLifetime((int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("lifetime").getValue() * 20));
                    orb.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
                    orb.setPos(entity.getEyePosition());
                    orb.setDamage(orbDamage);
                    orb.setOwner(entity);
                    orb.setStack(stack);

                    if (source != null)
                        orb.setDeltaMovement(entity.position().subtract(source.position()).normalize().add(MathUtils.randomFloat(random) * 0.5D, 0, MathUtils.randomFloat(random) * 0.5D));
                    else
                        orb.setDeltaMovement(MathUtils.randomFloat(random) * 0.5D, 0.5D + random.nextFloat() * 0.25D, MathUtils.randomFloat(random) * 0.5D);

                    level.addFreshEntity(orb);

                    relic.getRelicData(entity, stack).getLevelingData().addExperience("reflection", "construct", orbDamage * 0.1D);

                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_orbs").addValue(1);
                }
            }

            if (!(event.getSource().getEntity() instanceof LivingEntity livingSource))
                return;

            var stack = EntityUtils.findEquippedCurio(livingSource, RelicsItems.REFLECTIVE_NECKLACE.get());

            if (!stack.isEmpty()) {
                var step = 0;

                for (var orb : level.getEntitiesOfClass(ReflectiveOrbEntity.class, livingSource.getBoundingBox().inflate(ORB_SEARCH_RADIUS)).stream()
                        .filter(orb -> !orb.isTargeted() && orb.getOwner() instanceof LivingEntity owner && owner.getStringUUID().equals(livingSource.getStringUUID()))
                        .sorted(Comparator.comparingInt(orb -> (int) orb.position().distanceTo(entity.position())))
                        .toList()) {

                    ServerScheduler.schedule(step++ * 2, () -> orb.setTarget(entity.position().add(0D, entity.getBbHeight(), 0D).add(entity.getKnownMovement())));
                }
            }
        }

@Override
    public void channelRead(final ChannelHandlerContext ctx, final Object msg) throws Exception {
        long size = calculateSize(msg);
        long now = TrafficCounter.milliSecondFromNano();
        if (size > 0) {
            // compute the number of ms to wait before reopening the channel
            long waitGlobal = trafficCounter.readTimeToWait(size, getReadLimit(), maxTime, now);
            Integer key = ctx.channel().hashCode();
            PerChannel perChannel = channelQueues.get(key);
            long wait = 0;
            if (perChannel != null) {
                wait = perChannel.channelTrafficCounter.readTimeToWait(size, readChannelLimit, maxTime, now);
                if (readDeviationActive) {
                    // now try to balance between the channels
                    long maxLocalRead;
                    maxLocalRead = perChannel.channelTrafficCounter.cumulativeReadBytes();
                    long maxGlobalRead = cumulativeReadBytes.get();
                    if (maxLocalRead <= 0) {
                        maxLocalRead = 0;
                    }
                    if (maxGlobalRead < maxLocalRead) {
                        maxGlobalRead = maxLocalRead;
                    }
                    wait = computeBalancedWait(maxLocalRead, maxGlobalRead, wait);
                }
            }
            if (wait < waitGlobal) {
                wait = waitGlobal;
            }
            wait = checkWaitReadTime(ctx, wait, now);
            if (wait >= MINIMAL_WAIT) { // At least 10ms seems a minimal
                // time in order to try to limit the traffic
                // Only AutoRead AND HandlerActive True means Context Active
                Channel channel = ctx.channel();
                ChannelConfig config = channel.config();
                if (logger.isDebugEnabled()) {
                    logger.debug("Read Suspend: " + wait + ':' + config.isAutoRead() + ':'
                            + isHandlerActive(ctx));
                }
                if (config.isAutoRead() && isHandlerActive(ctx)) {
                    config.setAutoRead(false);
                    channel.attr(READ_SUSPENDED).set(true);
                    // Create a Runnable to reactive the read if needed. If one was create before it will just be
                    // reused to limit object creation
                    Attribute<Runnable> attr = channel.attr(REOPEN_TASK);
                    Runnable reopenTask = attr.get();
                    if (reopenTask == null) {
                        reopenTask = new ReopenReadTimerTask(ctx);
                        attr.set(reopenTask);
                    }
                    ctx.executor().schedule(reopenTask, wait, TimeUnit.MILLISECONDS);
                    if (logger.isDebugEnabled()) {
                        logger.debug("Suspend final status => " + config.isAutoRead() + ':'
                                + isHandlerActive(ctx) + " will reopened at: " + wait);
                    }
                }
            }
        }
        informReadOperation(ctx, now);
        ctx.fireChannelRead(msg);
    }

final void writeQuery(boolean flush) {
        assert id == Integer.MIN_VALUE : this.getClass().getSimpleName() +
                ".writeQuery(...) can only be executed once.";

        if ((id = queryContextManager.add(nameServerAddr, this)) == -1) {
            // We did exhaust the id space, fail the query
            IllegalStateException e = new IllegalStateException("query ID space exhausted: " + question());
            finishFailure("failed to send a query via " + protocol(), e, false);
            queryLifecycleObserver.queryWritten(nameServerAddr, channel.newFailedFuture(e));
            return;
        }

        // Ensure we remove the id from the QueryContextManager once the query completes.
        promise.addListener((FutureListener<AddressedEnvelope<DnsResponse, InetSocketAddress>>) future -> {
            // Cancel the timeout task.
            Future<?> timeoutFuture = DnsQueryContext.this.timeoutFuture;
            if (timeoutFuture != null) {
                DnsQueryContext.this.timeoutFuture = null;
                timeoutFuture.cancel(false);
            }

            Throwable cause = future.cause();
            if (cause instanceof DnsNameResolverTimeoutException || cause instanceof CancellationException) {
                // This query was failed due a timeout or cancellation. Let's delay the removal of the id to reduce
                // the risk of reusing the same id again while the remote nameserver might send the response after
                // the timeout.
                channel.eventLoop().schedule(new Runnable() {
                    @Override
                    public void run() {
                        removeFromContextManager(nameServerAddr);
                    }
                }, ID_REUSE_ON_TIMEOUT_DELAY_MILLIS, TimeUnit.MILLISECONDS);
            } else {
                // Remove the id from the manager as soon as the query completes. This may be because of success,
                // failure or cancellation
                removeFromContextManager(nameServerAddr);
            }
        });
        final DnsQuestion question = question();
        final DnsQuery query = newQuery(id, nameServerAddr);

        query.setRecursionDesired(recursionDesired);

        query.addRecord(DnsSection.QUESTION, question);

        for (DnsRecord record: additionals) {
            query.addRecord(DnsSection.ADDITIONAL, record);
        }

        if (optResource != null) {
            query.addRecord(DnsSection.ADDITIONAL, optResource);
        }

        if (logger.isDebugEnabled()) {
            logger.debug("{} WRITE: {}, [{}: {}], {}",
                    channel, protocol(), id, nameServerAddr, question);
        }

        ChannelFuture f = sendQuery(query, flush);
        queryLifecycleObserver.queryWritten(nameServerAddr, f);
    }

private static <T extends Entity & ParchmentBookRenderData> PageState updatePageState(
            T entity, float tickDelta, float channel) {
        float ageTicks = entity.age + tickDelta;
        Vec3d targetPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        float targetYaw = MathHelper.lerpAngleDegrees(tickDelta, entity.prevYaw, entity.getYaw());
        float targetPulse = entity.getRecitePulseProgress();

        PageState state = PAGE_STATES.computeIfAbsent(entity.getId(),
                ignored -> new PageState(targetPos, targetYaw, targetPulse, channel, ageTicks));

        float deltaTicks = ageTicks - state.lastAgeTicks;
        if (deltaTicks < 0.0F || deltaTicks > 5.0F) {
            state.position = targetPos;
            state.velocity = Vec3d.ZERO;
            state.yaw = targetYaw;
            state.pulse = targetPulse;
            state.channel = channel;
            state.agitation = channel * 0.8F;
            state.openAmount = MathHelper.clamp(0.32F + state.agitation * 0.35F + targetPulse * 0.5F, 0.0F, 1.0F);
        } else if (deltaTicks > 0.0F) {
            Vec3d eased = state.position.lerp(targetPos,
                    Math.min(1.0F, POSITION_SMOOTHING_RATE * deltaTicks));
            state.velocity = eased.subtract(state.position).multiply(1.0 / deltaTicks);
            state.position = eased;
            float yawRate = MathHelper.lerp(MathHelper.clamp(channel, 0.0F, 1.0F),
                    YAW_SMOOTHING_RATE, CHANNEL_YAW_SMOOTHING_RATE);
            state.yaw = MathHelper.lerpAngleDegrees(
                    Math.min(1.0F, yawRate * deltaTicks), state.yaw, targetYaw);

            float speed = (float) state.velocity.horizontalLength();
            float targetAgitation = MathHelper.clamp(speed * 6.0F, 0.0F, 0.5F) + channel * 0.8F;
            float targetOpen = MathHelper.clamp(
                    0.32F + targetAgitation * 0.35F + targetPulse * 0.5F, 0.0F, 1.0F);

            float ease = Math.min(1.0F, SMOOTHING_RATE * deltaTicks);
            state.agitation = MathHelper.lerp(ease, state.agitation, targetAgitation);
            state.openAmount = MathHelper.lerp(ease, state.openAmount, targetOpen);
            state.pulse = MathHelper.lerp(ease, state.pulse, targetPulse);
            state.channel = MathHelper.lerp(ease, state.channel, channel);

            state.flutterPhase += deltaTicks * (0.16F + state.agitation * 0.5F);
            state.pageTurnPhase += deltaTicks * (0.05F + state.channel * 0.2F);
        }
        state.lastAgeTicks = ageTicks;
        state.offset = state.position.subtract(targetPos);

        while (state.flutterPhase > MathHelper.TAU) {
            state.flutterPhase -= MathHelper.TAU;
        }
        while (state.pageTurnPhase > MathHelper.TAU) {
            state.pageTurnPhase -= MathHelper.TAU;
        }

        if (entity.age % 80 == 0) {
            PAGE_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId() && ageTicks - entry.getValue().lastAgeTicks > 100.0F);
        }
        return state;
    }

private static GloamTendrilState updateGloamTendrilState(
            LivingEntity entity, int stage, float age,
            Vec3d targetPosition, float scale) {
        long now = Util.getMeasuringTimeMs();
        GloamTendrilState state = GLOAM_TENDRIL_STATES.get(entity.getUuid());
        if (state == null) {
            state = new GloamTendrilState(now);
            GLOAM_TENDRIL_STATES.put(entity.getUuid(), state);
        }
        state.lastSeenTime = now;
        for (int index = 0; index < GLOAM_TENDRIL_SLOTS; index++) {
            boolean desired = index < stage;
            AnchoredGloamTendril tendril = state.tendrils[index];
            if (tendril == null) {
                if (desired) {
                    state.tendrils[index] = createAnchoredGloamTendril(
                            entity, state, index, targetPosition, age, scale);
                }
                continue;
            }
            Vec3d attachment = gloamTendrilAttachment(
                    entity, targetPosition, tendril.anchor, index);
            float phaseAge = age - tendril.phaseStart;
            if (tendril.phase == GloamTendrilPhase.SNAPPING) {
                if (phaseAge >= GLOAM_TENDRIL_SNAP_TICKS) {
                    state.tendrils[index] = desired
                            ? createAnchoredGloamTendril(
                            entity, state, index, targetPosition, age, scale)
                            : null;
                }
                continue;
            }
            if (tendril.phase == GloamTendrilPhase.RETRACTING) {
                if (desired) {
                    state.tendrils[index] = createAnchoredGloamTendril(
                            entity, state, index, targetPosition, age, scale);
                } else if (phaseAge >= GLOAM_TENDRIL_RETRACT_TICKS) {
                    state.tendrils[index] = null;
                }
                continue;
            }
            if (!desired) {
                tendril.phase = GloamTendrilPhase.RETRACTING;
                tendril.phaseStart = age;
                tendril.phaseAttachment = attachment;
                continue;
            }
            if (tendril.phase == GloamTendrilPhase.EMERGING
                    && phaseAge >= GLOAM_TENDRIL_EMERGE_TICKS) {
                tendril.phase = GloamTendrilPhase.ATTACHED;
                tendril.phaseStart = age;
            }
            if (tendril.anchor.squaredDistanceTo(attachment)
                    > GLOAM_TENDRIL_SNAP_DISTANCE_SQUARED) {
                tendril.phase = GloamTendrilPhase.SNAPPING;
                tendril.phaseStart = age;
                tendril.phaseAttachment = attachment;
                tendril.breakPoint = tendril.anchor.lerp(attachment, 0.56);
            }
        }
        return state;
    }

public void testHalfClosureOnlyOneEventWhenAutoRead(ServerBootstrap sb, Bootstrap cb) throws Throwable {
        Channel serverChannel = null;
        try {
            cb.option(ChannelOption.ALLOW_HALF_CLOSURE, true)
                    .option(ChannelOption.AUTO_READ, true);
            sb.childHandler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelActive(ChannelHandlerContext ctx) {
                            ((DuplexChannel) ctx).shutdownOutput();
                        }

                        @Override
                        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                            ctx.close();
                        }
                    });
                }
            });

            final AtomicInteger shutdownEventReceivedCounter = new AtomicInteger();
            final AtomicInteger shutdownReadCompleteEventReceivedCounter = new AtomicInteger();

            cb.handler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {

                        @Override
                        public void userEventTriggered(final ChannelHandlerContext ctx, Object evt) {
                            if (evt == ChannelInputShutdownEvent.INSTANCE) {
                                shutdownEventReceivedCounter.incrementAndGet();
                            } else if (evt == ChannelInputShutdownReadComplete.INSTANCE) {
                                shutdownReadCompleteEventReceivedCounter.incrementAndGet();
                                ctx.executor().schedule(new Runnable() {
                                    @Override
                                    public void run() {
                                        ctx.close();
                                    }
                                }, 100, MILLISECONDS);
                            }
                        }

                        @Override
                        public void exceptionCaught(ChannelHandlerContext ctx, Throwable cause) {
                            ctx.close();
                        }
                    });
                }
            });

            serverChannel = sb.bind().sync().channel();
            Channel clientChannel = cb.connect(serverChannel.localAddress()).sync().channel();
            clientChannel.closeFuture().await();
            assertEquals(1, shutdownEventReceivedCounter.get());
            assertEquals(1, shutdownReadCompleteEventReceivedCounter.get());
        } finally {
            if (serverChannel != null) {
                serverChannel.close().sync();
            }
        }
    }

public void placePlayersAndBoss(ServerLevel level, List<Player> players, Predicate<Player> playerStillValid, ItemStack stack, EntityType<?> entityType, BossTokenItem.SpawningFunction bossFunction) {
		if (players.isEmpty())
			return;

		StructureStart structureStart = getStructureStart(level);

		if (structureStart == null)
			return;

		AoAScheduler.schedule(100, tick -> {
			boolean spawnBoss = false;
			Entity entity = entityType.create(level);
			SoundBuilder soundBuilder = entity instanceof AoABoss boss && boss.getMusic() != null ? SoundBuilder.asMusic(boss.getMusic(), level) : null;

			if (entity != null)
				entity.discard();

			for (Player player : players) {
				if (!(player instanceof ServerPlayer serverPlayer))
					continue;

				if (playerStillValid.test(serverPlayer)) {
					Vec3 pos = RandomUtil.selection(this.playerSpawnPoints);
					spawnBoss = true;

					serverPlayer.connection.teleport(pos.x, pos.y, pos.z, 0, 0);
					InventoryUtil.giveItemTo(serverPlayer, AoAItems.RETURN_CRYSTAL);
					serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.bossWarning"), ChatFormatting.GREEN));
				}
				else {
					serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.tooFar"), ChatFormatting.RED));
				}

				if (soundBuilder != null)
					soundBuilder.onlyFor(player);
			}

			if (spawnBoss) {
				AABB bounds = getStructureBounds(level);

				AoAScheduler.schedule(1, tick2 -> {
					getEntitiesInside(level, bounds).forEach(entity2 -> {
						if (!(entity2 instanceof Player) && !(entity2 instanceof ItemEntity))
							entity2.discard();
					});
				});

				AoAScheduler.schedule(40, tick2 -> {
					if (soundBuilder != null)
						soundBuilder.play();
				});

				AoAScheduler.schedule(140, tick2 -> {
					int playerCount = getPlayersInside(level, bounds).size();

					if (playerCount > 0)
						bossFunction.spawn(level, getRandomBossSpawn(), stack, playerCount);
				});
			}
		});

		for (Player player : players) {
			player.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("nowhere.boss.teleportWarning"), ChatFormatting.GOLD));
		}
	}

private void safeClose(
            final ChannelHandlerContext ctx, final ChannelFuture flushFuture,
            final ChannelPromise promise) {
        if (!ctx.channel().isActive()) {
            ctx.close(promise);
            return;
        }

        final Future<?> timeoutFuture;
        if (!flushFuture.isDone()) {
            long closeNotifyTimeout = closeNotifyFlushTimeoutMillis;
            if (closeNotifyTimeout > 0) {
                // Force-close the connection if close_notify is not fully sent in time.
                timeoutFuture = ctx.executor().schedule(() -> {
                    // May be done in the meantime as cancel(...) is only best effort.
                    if (!flushFuture.isDone()) {
                        logger.warn("{} Last write attempt timed out; force-closing the connection.",
                                ctx.channel());
                        addCloseListener(ctx.close(ctx.newPromise()), promise);
                    }
                }, closeNotifyTimeout, TimeUnit.MILLISECONDS);
            } else {
                timeoutFuture = null;
            }
        } else {
            timeoutFuture = null;
        }

        // Close the connection if close_notify is sent in time.
        flushFuture.addListener(f -> {
            if (timeoutFuture != null) {
                timeoutFuture.cancel(false);
            }
            final long closeNotifyReadTimeout = closeNotifyReadTimeoutMillis;
            if (closeNotifyReadTimeout <= 0) {
                // Trigger the close in all cases to make sure the promise is notified
                // See https://github.com/netty/netty/issues/2358
                addCloseListener(ctx.close(ctx.newPromise()), promise);
            } else {
                final Future<?> closeNotifyReadTimeoutFuture;

                if (!sslClosePromise.isDone()) {
                    closeNotifyReadTimeoutFuture = ctx.executor().schedule(() -> {
                        if (!sslClosePromise.isDone()) {
                            logger.debug(
                                    "{} did not receive close_notify in {}ms; force-closing the connection.",
                                    ctx.channel(), closeNotifyReadTimeout);

                            // Do the close now...
                            addCloseListener(ctx.close(ctx.newPromise()), promise);
                        }
                    }, closeNotifyReadTimeout, TimeUnit.MILLISECONDS);
                } else {
                    closeNotifyReadTimeoutFuture = null;
                }

                // Do the close once the we received the close_notify.
                sslClosePromise.addListener(future -> {
                    if (closeNotifyReadTimeoutFuture != null) {
                        closeNotifyReadTimeoutFuture.cancel(false);
                    }
                    addCloseListener(ctx.close(ctx.newPromise()), promise);
                });
            }
        });
    }

@SubscribeEvent
    public static void onShearGoat(PlayerInteractEvent.EntityInteract event)
    {
        Entity entity = event.getTarget();
        Player player = event.getEntity();
        ItemStack stack = event.getItemStack();

        if (entity instanceof LivingEntity living && (!(living instanceof AgeableMob ageable) || !ageable.isBaby())
        && !entity.level().isClientSide && stack.is(Tags.Items.SHEARS))
        {
            getFurCap(living).ifPresent(cap ->
            {
                if (cap.isSheared())
                {   event.setResult(PlayerInteractEvent.Result.DENY);
                    return;
                }

                // Use shears
                player.swing(event.getHand(), true);
                shear(living, player);
                if (!player.getAbilities().instabuild)
                {   stack.hurtAndBreak(1, player, (p) -> p.broadcastBreakEvent(player.getUsedItemHand()));
                }

                // Random chance to ram the player when sheared
                if (living instanceof Goat goat && !player.getAbilities().instabuild && goat.level().getDifficulty() != Difficulty.PEACEFUL
                && !goat.level().isClientSide && goat.getRandom().nextDouble() < 0.4)
                {
                    // Set ram cooldown ticks
                    goat.getBrain().setMemory(MemoryModuleType.RAM_COOLDOWN_TICKS, 30);
                    // Stop active goals
                    for (WrappedGoal goal : goat.goalSelector.getAvailableGoals())
                    {
                        if (goal.isInterruptable())
                        {   goal.stop();
                        }
                    }

                    // Start lowering head
                    TaskScheduler.scheduleServer(() ->
                    {
                        ClientboundEntityEventPacket packet = new ClientboundEntityEventPacket(goat, (byte) 58);
                        ((ServerChunkCache) goat.level().getChunkSource()).broadcastAndSend(goat, packet);
                    }, 5);

                    // Look at player
                    BehaviorUtils.lookAtEntity(goat, player);
                    // Stop walking
                    goat.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);

                    // Set ram target to player pos
                    goat.getBrain().setMemory(MemoryModuleType.RAM_TARGET, player.position());
                    TaskScheduler.scheduleServer(() ->
                    {
                        if (player.distanceTo(goat) <= 10)
                        {
                            goat.playSound(goat.isScreamingGoat() ? SoundEvents.GOAT_SCREAMING_PREPARE_RAM : SoundEvents.GOAT_PREPARE_RAM, 1.0F, 1.0F);
                            goat.getBrain().setMemory(MemoryModuleType.RAM_TARGET, player.position());
                        }
                    }, 30);

                    // Trigger ram
                    goat.getBrain().setActiveActivityIfPossible(Activity.RAM);
                }
                event.setResult(PlayerInteractEvent.Result.ALLOW);
            });
        }
    }

@Override
        public void channelRead0(final ChannelHandlerContext ctx, ByteBuf in) throws Exception {
            byte[] actual = new byte[in.readableBytes()];
            int nb = actual.length / messageSize;
            loggerServer.info("Step: " + step + " Read: " + nb + " blocks");
            in.readBytes(actual);
            long timestamp = TrafficCounter.milliSecondFromNano();
            int isAutoRead = 0;
            int laststep = step;
            for (int i = 0; i < nb; i++) {
                multipleMessage[step]--;
                if (multipleMessage[step] == 0) {
                    // setAutoRead test
                    if (autoRead != null) {
                        isAutoRead = autoRead[step];
                    }
                    step++;
                }
            }
            if (laststep != step) {
                // setAutoRead test
                if (autoRead != null && isAutoRead != 2) {
                    if (isAutoRead != 0) {
                        loggerServer.info("Step: " + step + " Set AutoRead: " + (isAutoRead > 0));
                        channel.config().setAutoRead(isAutoRead > 0);
                    } else {
                        loggerServer.info("Step: " + step + " AutoRead: NO");
                    }
                }
            }
            Thread.sleep(10);
            loggerServer.debug("Step: " + step + " Write: " + nb);
            for (int i = 0; i < nb; i++) {
                channel.write(Unpooled.copyLong(timestamp));
            }
            channel.flush();
            if (laststep != step) {
                // setAutoRead test
                if (isAutoRead != 0) {
                    if (isAutoRead < 0) {
                        final int exactStep = step;
                        long wait = isAutoRead == -1? minimalms : stepms + minimalms;
                        if (isAutoRead == -3) {
                            wait = stepms * 3;
                        }
                        executor.schedule(new Runnable() {
                            @Override
                            public void run() {
                                loggerServer.info("Step: " + exactStep + " Reset AutoRead");
                                channel.config().setAutoRead(true);
                            }
                        }, wait, TimeUnit.MILLISECONDS);
                    } else {
                        if (isAutoRead > 1) {
                            loggerServer.debug("Step: " + step + " Will Set AutoRead: True");
                            final int exactStep = step;
                            executor.schedule(new Runnable() {
                                @Override
                                public void run() {
                                    loggerServer.info("Step: " + exactStep + " Set AutoRead: True");
                                    channel.config().setAutoRead(true);
                                }
                            }, stepms + minimalms, TimeUnit.MILLISECONDS);
                        }
                    }
                }
            }
        }

private RenderPose resolveRenderPose(WraithmawCutlassEntity entity, float tickDelta) {
        Vec3d entityPos = new Vec3d(
                MathHelper.lerp(tickDelta, entity.prevX, entity.getX()),
                MathHelper.lerp(tickDelta, entity.prevY, entity.getY()),
                MathHelper.lerp(tickDelta, entity.prevZ, entity.getZ()));
        int cutlassState = entity.getState();
        Vec3d targetPosition = entityPos;
        Vec3d targetDirection = normalizedDirection(entity.getVelocity());
        if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
            Entity ownerEntity = entity.getWorld().getEntityById(entity.getOwnerId());
            if (!(ownerEntity instanceof LivingEntity owner)
                    || !owner.getMainHandStack().isOf(ItemsRegistry.WRAITHMAW.get())
                    && !owner.getOffHandStack().isOf(ItemsRegistry.WRAITHMAW.get())) {
                RENDER_STATES.remove(entity.getId());
                return null;
            }
            targetPosition = orbitPosition(entity, owner, tickDelta);
            double ownerYaw = Math.toRadians(MathHelper.lerpAngleDegrees(
                    tickDelta, owner.prevYaw, owner.getYaw()));
            targetDirection = new Vec3d(-Math.sin(ownerYaw), 0.0, Math.cos(ownerYaw));
        }

        float ageTicks = entity.age + tickDelta;
        long worldTick = entity.getWorld().getTime();
        RenderState renderState = RENDER_STATES.get(entity.getId());
        float deltaTicks = renderState == null ? 0.0F : ageTicks - renderState.lastAgeTicks;
        boolean reset = renderState == null
                || renderState.world != entity.getWorld()
                || !entity.getUuid().equals(renderState.entityUuid)
                || deltaTicks < 0.0F || deltaTicks > 5.0F;
        if (!reset && renderState.state == WraithmawCutlassEntity.STATE_ORBITING
                && cutlassState == WraithmawCutlassEntity.STATE_LAUNCHED) {
            targetPosition = entity.getPos();
        }
        if (reset) {
            renderState = new RenderState(entity.getWorld(), entity.getUuid(), targetPosition,
                    targetDirection, ageTicks, worldTick, cutlassState);
            RENDER_STATES.put(entity.getId(), renderState);
        } else {
            if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
                renderState.position = targetPosition;
            } else if (deltaTicks > 0.0F) {
                renderState.position = renderState.position.lerp(targetPosition,
                        response(POSITION_RESPONSE, deltaTicks));
            }
            if (cutlassState == WraithmawCutlassEntity.STATE_ORBITING) {
                renderState.direction = targetDirection;
            } else if ((cutlassState == WraithmawCutlassEntity.STATE_FALLING
                    || cutlassState == WraithmawCutlassEntity.STATE_LAUNCHED)
                    && targetDirection != null) {
                if (renderState.direction == null) {
                    renderState.direction = targetDirection;
                } else if (deltaTicks > 0.0F) {
                    renderState.direction = interpolateDirection(
                            renderState.direction, targetDirection,
                            response(DIRECTION_RESPONSE, deltaTicks));
                }
            }
            renderState.lastAgeTicks = ageTicks;
            renderState.lastWorldTick = worldTick;
            renderState.state = cutlassState;
        }
        if (entity.age % 80 == 0) {
            long cutoff = worldTick - 100L;
            RENDER_STATES.entrySet().removeIf(entry ->
                    entry.getKey() != entity.getId()
                            && (entry.getValue().world != entity.getWorld()
                            || entry.getValue().lastWorldTick < cutoff));
        }
        return new RenderPose(renderState.position.subtract(entityPos), renderState.direction);
    }

public static boolean performImpacts(World world, LivingEntity caster, @Nullable Entity target, Entity aoeSource,
                                         RegistryEntry<Spell> spellEntry, List<Spell.Impact> impacts, ImpactContext context,
                                         boolean additionalTargetLookup, @Nullable Spell.Impact.Action.Type filteredAction) {
        var trackers = target != null ? Platform.tracking(target) : null;
        SpellTarget.Intent selectedIntent = null;

        var extendedImpacts = SpellModifiers.extendedImpactsOf(caster, spellEntry);
        var area_impact = extendedImpacts.areaImpact();
        var mutableImpacts = extendedImpacts.impacts();

        var perform = true;
        if (additionalTargetLookup && area_impact != null && area_impact.force_indirect) {
            perform = false;
        }

        EnumSet<Spell.Impact.Action.Type> performedActionTypes = EnumSet.noneOf(Spell.Impact.Action.Type.class);
        if (perform) {
            for (var impact : mutableImpacts) {
                var intent = SpellIntents.impactIntent(impact.action);
                if (!impact.action.apply_to_caster // Only filtering for cases when another entity is actually targeted
                        && (selectedIntent != null && selectedIntent != intent)) {
                    // Filter out mixed intents
                    // So dual intent spells either damage or heal, and not do both
                    continue;
                }
                if (filteredAction != null && impact.action.type != filteredAction) {
                    // Filter out actions that are not of the specified type
                    continue;
                }
                if (additionalTargetLookup && !impact.action.allow_on_center_target) {
                    // Skip center target if additional target lookup is enabled
                    continue;
                }

                if (target != null) {
                    var result = performImpact(world, caster, target, spellEntry, impact, context, trackers);
                    if (result) {
                        performedActionTypes.add(impact.action.type);
                        if (!impact.action.apply_to_caster) {
                            // Caster-only impacts hit the caster, not the shared AOE targets, so they
                            // must not define the intent that gates subsequent target impacts (mirrors
                            // the apply_to_caster exemption in the mixed-intent filter above). Otherwise
                            // e.g. a self-buff would cancel the damage dealt to everyone else.
                            selectedIntent = intent;
                        }
                    }
                }
            }
        }

        if (area_impact != null
                && additionalTargetLookup
                && (shouldApplyAreaImpact(area_impact, performedActionTypes) || target == null) ) {
            var exclude = area_impact.force_indirect ? null : target;
            lookupAndPerformAreaImpact(area_impact, spellEntry, caster, exclude, aoeSource, impacts, context, false);
            if (caster instanceof PlayerEntity player) {
                ((WorldScheduler)world).schedule(0, () -> {
                    var location = target != null ? target.getPos() : context.position();
                    SpellTriggers.onSpellAreaImpact(player, target, location, spellEntry);
                });
            }
        }

        var anyPerformed = !performedActionTypes.isEmpty();
        if (anyPerformed && caster instanceof PlayerEntity player) {
            ((WorldScheduler)world).schedule(0, () -> {
                SpellTriggers.onSpellImpactAny(player, target, aoeSource, spellEntry);
            });
        }

        return anyPerformed;
    }

@Override
    public void perform(Player attacker, InteractionHand hand, ItemModularHandheld item, ItemStack itemStack, LivingEntity target, Vec3 hitVec, int chargedTicks) {
        boolean isDefensive = isDefensive(item, itemStack, hand);
        int overchargeBonus = canOvercharge(item, itemStack) ? getOverchargeBonus(item, itemStack, chargedTicks) : 0;
        int revengeLevel = item.getEffectLevel(itemStack, ItemEffect.abilityRevenge);

        double damageMultiplier = item.getEffectLevel(itemStack, isDefensive ? ItemEffect.abilityDefensive : ItemEffect.overpower) / 100f;
        double efficiency = item.getEffectEfficiency(itemStack, ItemEffect.overpower);

        if (overchargeBonus > 0) {
            damageMultiplier += overchargeBonus * item.getEffectLevel(itemStack, ItemEffect.abilityOvercharge) / 100d;
        }

        int comboLevel = item.getEffectLevel(itemStack, ItemEffect.abilityCombo);
        if (comboLevel > 0) {
            damageMultiplier += comboLevel * ComboPoints.get(attacker) / 100d;
        }

        if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
            damageMultiplier += revengeLevel / 100d;
        }

        AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, 0.1f, 0.1f);
        if (result != AbilityUseResult.fail) {
            int currentAmplifier = Optional.ofNullable(target.getEffect(ExhaustedPotionEffect.instance))
                    .map(MobEffectInstance::getAmplifier)
                    .orElse(-1);

            int amplifier = currentAmplifier + 2;

            if (isDefensive) {
                amplifier--;
            }

            if (overchargeBonus > 0) {
                amplifier += (int) (overchargeBonus * item.getEffectEfficiency(itemStack, ItemEffect.abilityOvercharge));
            }

            int momentumLevel = item.getEffectLevel(itemStack, ItemEffect.abilityMomentum);
            if (momentumLevel > 0 && currentAmplifier > -1) {
                double momentumEfficiency = item.getEffectEfficiency(itemStack, ItemEffect.abilityMomentum);
                double velocity = momentumLevel / 100d;
                velocity += momentumEfficiency * (currentAmplifier + 1);

                velocity += momentumEfficiency * Optional.ofNullable(attacker.getEffect(ExhaustedPotionEffect.instance))
                        .map(MobEffectInstance::getAmplifier)
                        .map(amp -> amp + 1)
                        .orElse(0);

                velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);

                if (velocity > 0) {
                    target.push(0, velocity, 0);
                }
            }


            int exhilarationLevel = item.getEffectLevel(itemStack, ItemEffect.abilityExhilaration);
            if (exhilarationLevel > 0 && !target.isAlive()) {
                ServerScheduler.schedule(0, () -> attacker.removeEffect(ExhaustedPotionEffect.instance));

            }

            target.addEffect(new MobEffectInstance(ExhaustedPotionEffect.instance, (int) (efficiency * 20), amplifier, false, true));

            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.PLAYERS, 1, 0.8f);
        } else {
            target.getCommandSenderWorld().playSound(attacker, target.blockPosition(), SoundEvents.PLAYER_ATTACK_WEAK, SoundSource.PLAYERS, 1, 0.8f);
        }


        item.tickProgression(attacker, itemStack, result == AbilityUseResult.fail ? 1 : 2);
        item.applyDamage(2, itemStack, attacker);
    }

@Test
    @Timeout(value = 5000L, unit = MILLISECONDS)
    public void testFlushNotDiscarded()
            throws InterruptedException {
        final ScheduledExecutorService executorService = Executors.newScheduledThreadPool(1);

        try {
            ServerBootstrap sb = new ServerBootstrap();
            sb.group(eventLoopGroup);
            sb.channel(NioServerSocketChannel.class);
            sb.childHandler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new Http2FrameCodecBuilder(true).build());
                    ch.pipeline().addLast(new Http2MultiplexHandler(new ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelRead(final ChannelHandlerContext ctx, Object msg) {
                            if (msg instanceof Http2HeadersFrame && ((Http2HeadersFrame) msg).isEndStream()) {
                                executorService.schedule(new Runnable() {
                                    @Override
                                    public void run() {
                                        ctx.writeAndFlush(new DefaultHttp2HeadersFrame(
                                                new DefaultHttp2Headers(), false)).addListener(
                                                (ChannelFutureListener) future -> {
                                                    ctx.write(new DefaultHttp2DataFrame(
                                                            Unpooled.copiedBuffer(
                                                                    "Hello World", CharsetUtil.US_ASCII),
                                                            true));
                                                    ctx.channel().eventLoop().execute(new Runnable() {
                                                        @Override
                                                        public void run() {
                                                            ctx.flush();
                                                        }
                                                    });
                                                });
                                    }
                                }, 500, MILLISECONDS);
                            }
                            ReferenceCountUtil.release(msg);
                        }
                    }));
                }
            });
            serverChannel = sb.bind(new InetSocketAddress(NetUtil.LOCALHOST, 0)).syncUninterruptibly().channel();

            final CountDownLatch latch = new CountDownLatch(1);
            Bootstrap bs = new Bootstrap();
            bs.group(eventLoopGroup);
            bs.channel(NioSocketChannel.class);
            bs.handler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new Http2FrameCodecBuilder(false).build());
                    ch.pipeline().addLast(new Http2MultiplexHandler(DISCARD_HANDLER));
                }
            });
            clientChannel = bs.connect(serverChannel.localAddress()).syncUninterruptibly().channel();
            Http2StreamChannelBootstrap h2Bootstrap = new Http2StreamChannelBootstrap(clientChannel);
            h2Bootstrap.handler(new ChannelInboundHandlerAdapter() {
                @Override
                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                    if (msg instanceof Http2DataFrame && ((Http2DataFrame) msg).isEndStream()) {
                        latch.countDown();
                    }
                    ReferenceCountUtil.release(msg);
                }
            });
            Http2StreamChannel streamChannel = h2Bootstrap.open().syncUninterruptibly().getNow();
            streamChannel.writeAndFlush(new DefaultHttp2HeadersFrame(new DefaultHttp2Headers(), true))
                    .syncUninterruptibly();

            latch.await();
        } finally {
            executorService.shutdown();
        }
    }

private static float[] devourerArrivalTimes(
            long[] cells, Long2IntOpenHashMap indices,
            double centerX, double centerZ, float maximumRadius, int seed) {
        float[] arrivals = new float[cells.length];
        Arrays.fill(arrivals, Float.POSITIVE_INFINITY);
        PriorityQueue<DevourerSpreadNode> frontier = new PriorityQueue<>(
                Comparator.comparingDouble(DevourerSpreadNode::arrival));
        boolean firstComponent = true;
        while (true) {
            int componentSeed = -1;
            double closestDistance = Double.POSITIVE_INFINITY;
            for (int i = 0; i < cells.length; i++) {
                if (Float.isFinite(arrivals[i])) {
                    continue;
                }
                double cellX = (gridCellX(cells[i]) + 0.5)
                        / BLOOD_COARSE_GRID_SCALE;
                double cellZ = (gridCellZ(cells[i]) + 0.5)
                        / BLOOD_COARSE_GRID_SCALE;
                double distance = MathHelper.hypot(
                        cellX - centerX, cellZ - centerZ);
                if (distance < closestDistance) {
                    closestDistance = distance;
                    componentSeed = i;
                }
            }
            if (componentSeed < 0) {
                break;
            }
            float seedArrival = firstComponent ? 0.0F
                    : MathHelper.clamp(
                    (float) (closestDistance / maximumRadius) * 0.88F
                            + 0.035F
                            + devourerNoise(seed, cells[componentSeed], 91) * 0.04F,
                    0.0F, 0.94F);
            arrivals[componentSeed] = seedArrival;
            frontier.add(new DevourerSpreadNode(componentSeed, seedArrival));
            while (!frontier.isEmpty()) {
                DevourerSpreadNode node = frontier.poll();
                if (node.arrival() > arrivals[node.index()] + 1.0E-6F) {
                    continue;
                }
                long cell = cells[node.index()];
                int gridX = gridCellX(cell);
                int gridZ = gridCellZ(cell);
                for (Direction direction : Direction.Type.HORIZONTAL) {
                    long neighborCell = packGridCell(
                            gridX + direction.getOffsetX(),
                            gridZ + direction.getOffsetZ());
                    int neighbor = indices.get(neighborCell);
                    if (neighbor < 0) {
                        continue;
                    }
                    float step = (0.76F
                            + devourerNoise(seed, neighborCell,
                            direction.getHorizontal() + 17) * 0.48F)
                            / (maximumRadius * BLOOD_COARSE_GRID_SCALE);
                    float candidate = node.arrival() + step;
                    if (candidate + 1.0E-6F < arrivals[neighbor]) {
                        arrivals[neighbor] = candidate;
                        frontier.add(new DevourerSpreadNode(neighbor, candidate));
                    }
                }
            }
            firstComponent = false;
        }
        float maximumArrival = 0.0F;
        for (float arrival : arrivals) {
            if (Float.isFinite(arrival)) {
                maximumArrival = Math.max(maximumArrival, arrival);
            }
        }
        float scale = maximumArrival <= 1.0E-5F ? 1.0F : 0.96F / maximumArrival;
        for (int i = 0; i < arrivals.length; i++) {
            arrivals[i] = MathHelper.clamp(arrivals[i] * scale, 0.0F, 0.96F);
        }
        return arrivals;
    }

public static boolean fallProjectile(World world, LivingEntity caster, Entity target, @Nullable Vec3d targetLocation, RegistryEntry<Spell> spellEntry, ImpactContext context, int sequenceIndex) {
        if (world.isClient) {
            return false;
        }

        Vec3d targetPosition = (target != null) ? target.getPos() : targetLocation;
        if (targetPosition == null) {
            return false;
        }

        var spell = spellEntry.value();
        var meteor = spell.deliver.meteor;
        var height = meteor.launch_height;
        var launchPoint = targetPosition.add(0, height, 0);
        var data = spell.deliver.meteor;
        var projectileData = data.projectile;
        var mutableLaunchProperties = data.launch_properties.copy();
        var mutablePerks = projectileData.perks.copy();
        var scaleMultiplier = 1F;
        var launchRadius = meteor.launch_radius;

        for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
            if (modifier.projectile_launch != null) {
                mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
            }
            if (modifier.projectile_perks != null) {
                mutablePerks.mutatingCombine(modifier.projectile_perks);
            }
            scaleMultiplier += modifier.projectile_scale_multiply;
            launchRadius += modifier.meteor_launch_radius_add;
        }

        var projectile = new SpellProjectile(world, caster,
                launchPoint.getX(), launchPoint.getY(), launchPoint.getZ(),
                SpellProjectile.Behaviour.FALL, spellEntry, context, mutablePerks);
        projectile.setScaleMultiplier(scaleMultiplier);

        if (SpellEvents.PROJECTILE_FALL.isListened()) {
            SpellEvents.PROJECTILE_FALL.invoke((listener) -> listener.onProjectileLaunch(new SpellEvents.ProjectileLaunchEvent(projectile, mutableLaunchProperties, caster, target, spellEntry, context, sequenceIndex)));
        }

        projectile.setYaw(0);
        projectile.setPitch(90);

        if (launchSequenceEligible(sequenceIndex, meteor.divergence_requires_sequence)) {
            projectile.setVelocity( 0, - 1, 0, mutableLaunchProperties.velocity, 0.5F, projectileData.divergence);
        } else {
            projectile.setVelocity(new Vec3d(0, - mutableLaunchProperties.velocity, 0));
        }
        if (launchSequenceEligible(sequenceIndex, meteor.follow_target_requires_sequence)) {
            projectile.setFollowedTarget(target);
        } else {
            projectile.setFollowedTarget(null);
        }
        if (launchRadius > 0 && launchSequenceEligible(sequenceIndex, meteor.offset_requires_sequence)) {
            var randomAngle = Math.toRadians(world.random.nextFloat() * 360);
            var offset = (new Vec3d(launchRadius, 0, 0)).rotateY((float) randomAngle);
            projectile.setPosition(projectile.getPos().add(offset));
        }

        projectile.prevYaw = projectile.getYaw();
        projectile.prevPitch = projectile.getPitch();
        projectile.range = height;

        world.spawnEntity(projectile);

        if (sequenceIndex == 0 && mutableLaunchProperties.extra_launch_count > 0) {
            for (int i = 0; i < mutableLaunchProperties.extra_launch_count; i++) {
                var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                var nextSequenceIndex = i + 1;
                ((WorldScheduler)world).schedule(ticks, () -> {
                    if (caster == null || !caster.isAlive()) {
                        return;
                    }
                    fallProjectile(world, caster, target, targetLocation, spellEntry, context, nextSequenceIndex);
                });
            }
        }
        return true;
    }

@Setup
    public void setup() throws Exception {
        group = new MultiThreadIoEventLoopGroup(1, EpollIoHandler.newFactory());

        // add an arbitrary timeout to make the timer reschedule
        future = group.schedule(new Runnable() {
            @Override
            public void run() {
                throw new AssertionError();
            }
        }, 5, TimeUnit.MINUTES);
        serverChan = new ServerBootstrap()
            .channel(EpollServerSocketChannel.class)
            .group(group)
            .childHandler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new ChannelDuplexHandler() {
                        @Override
                        public void channelRead(ChannelHandlerContext ctx, Object msg) {
                            if (msg instanceof ByteBuf) {
                                ctx.writeAndFlush(msg, ctx.voidPromise());
                            } else {
                                throw new AssertionError();
                            }
                        }
                    });
                }
            })
            .bind(0)
            .sync()
            .channel();
    chan = new Bootstrap()
        .channel(EpollSocketChannel.class)
        .handler(new ChannelInitializer<Channel>() {
            @Override
            protected void initChannel(Channel ch) {
                ch.pipeline().addLast(new ChannelDuplexHandler() {

                private ChannelPromise lastWritePromise;

                    @Override
                    public void channelRead(ChannelHandlerContext ctx, Object msg) {
                        if (msg instanceof ByteBuf) {

                            ByteBuf buf = (ByteBuf) msg;
                            try {
                                if (buf.readableBytes() == 1) {
                                    lastWritePromise.trySuccess();
                                    lastWritePromise = null;
                                } else {
                                    throw new AssertionError();
                                }
                            } finally {
                                buf.release();
                            }
                        } else {
                            throw new AssertionError();
                        }
                    }

                    @Override
                    public void write(ChannelHandlerContext ctx, Object msg, ChannelPromise promise)
                            throws Exception {
                        if (lastWritePromise != null) {
                            throw new IllegalStateException();
                        }
                        lastWritePromise = promise;
                        super.write(ctx, msg, ctx.voidPromise());
                    }
                });
            }
        })
        .group(group)
        .connect(serverChan.localAddress())
        .sync()
        .channel();

        abyte = chan.alloc().directBuffer(1);
        abyte.writeByte('a');
    }

public void tick()
    {
        if ((this.target == null || this.target.isRemoved()) && this.entity.getEatTimer() <= 0)
        {
            this.stop();
            return;
        }

        // Look at target position
        this.lookPos = this.target.position().add(this.target.getDeltaMovement());
        this.entity.getLookControl().setLookAt(lookPos);

        if (this.entity.getEatTimer() <= 0)
        {
            // Move to the target
            PathNavigation navigator = this.entity.getNavigation();
            Path path = navigator.createPath(target, 0);
            if (path != null) navigator.moveTo(path, 1.5);

            // Update look position

            // If within 1.5 blocks, eat the item
            if (Math.sqrt(this.entity.distanceToSqr(this.target)) < 1.5 && Math.abs(this.entity.getY() - this.target.getY()) < 1 && this.target.isAlive())
            {
                navigator.stop();
                this.entity.getLookControl().setLookAt(lookPos);

                // Play tongue stretch animation
                this.entity.eatAnimation();

                // Play tongue out sound
                WorldHelper.playEntitySound(ModSounds.CHAMELEON_TONGUE_OUT, this.entity, this.entity.getSoundSource(), 1, (float) Math.random() * 0.2f + 0.9f);

                // Remove target item
                TaskScheduler.scheduleServer(() ->
                {
                    if (this.target != null && this.target.isAlive() && !this.target.isRemoved())
                    {
                        this.entity.onEatEntity(this.target);
                        this.target.remove(Entity.RemovalReason.KILLED);

                        if (this.target instanceof ItemEntity item)
                        {   this.entity.onItemPickup(item);

                            Entity thrower = item.getOwner();
                            if (thrower != null)
                            {
                                if (item.getItem().getCount() > 0)
                                {   ItemStack stack = item.getItem().copy();
                                    stack.shrink(1);
                                    if (!stack.isEmpty())
                                    {   ItemEntity remainingStack = WorldHelper.entityDropItem(this.entity, stack);
                                        remainingStack.setThrower(thrower.getUUID());
                                        remainingStack.getPersistentData().putUUID("Recipient", this.entity.getUUID());
                                    }
                                }
                            }
                        }

                        // Play tongue in sound
                        WorldHelper.playEntitySound(ModSounds.CHAMELEON_TONGUE_IN, this.entity, this.entity.getSoundSource(), 1, (float) Math.random() * 0.2f + 0.9f);
                    }
                }, this.entity.getEatAnimLength() / 2 + 2);

                // Send the entity toward the chameleon
                TaskScheduler.scheduleServer(() ->
                {
                    this.target.setDeltaMovement(this.entity.position().subtract(this.target.position()).normalize().scale(0.75));
                }, this.entity.getEatAnimLength() / 2);
            }

            this.entity.goalSelector.getRunningGoals().forEach(goal ->
            {
                Goal g = goal.getGoal();
                if (g instanceof TemptGoal || g instanceof LookAtPlayerGoal || g instanceof RandomLookAroundGoal || g instanceof LazyLookGoal)
                {
                    this.stoppedTasks = true;
                    goal.stop();
                }
            });
        }
    }

private static void processConfigFormatting(ModConfig config)
    {
        Path filePath = config.getFullPath().toAbsolutePath();

        // Mark as being processed to prevent saves
        markWriting(config);
        TaskScheduler.schedule(() -> unmarkWriting(config), 10);

        try
        {   List<String> lines = Files.readAllLines(config.getFullPath());
            List<String> processedLines = new ArrayList<>();
            boolean nextArrayShouldDrillDown = false;
            boolean fileModified = false;

            for (int i = 0; i < lines.size(); i++)
            {   String line = lines.get(i);
                String trimmed = line.trim();

                // Check for drill_down comment
                if (trimmed.startsWith("#") && trimmed.contains("//v"))
                {   nextArrayShouldDrillDown = true;
                    processedLines.add(line);
                    continue;
                }

                // Skip empty lines and other comments
                if (trimmed.isEmpty() || (trimmed.startsWith("#") && !trimmed.contains("//v")))
                {   processedLines.add(line);
                    continue;
                }

                // Process array formatting if we're in drill_down mode and this line contains an assignment
                if (nextArrayShouldDrillDown && line.contains("="))
                {   ArrayParseResult result = parseCompleteArray(lines, i);

                    if (result.isArray)
                    {   // Format the array with drill-down
                        List<String> formattedLines = formatArrayWithNewlines(result.keyPart, result.arrayContent, getIndentation(line));
                        processedLines.addAll(formattedLines);

                        // Skip the lines we just processed
                        i = result.endIndex;
                        nextArrayShouldDrillDown = false;
                        if (lines.get(i).endsWith("]"))
                        {   fileModified = true;
                        }
                    }
                    else
                    {   processedLines.add(line);
                        nextArrayShouldDrillDown = false;
                    }
                }
                // Check if this line starts a vertical array without //v directive (only if not in drill-down mode)
                else if (line.contains("=") && line.trim().endsWith("= ["))
                {
                    VerticalArrayParseResult verticalResult = parseVerticalArray(lines, i);
                    if (verticalResult.isVerticalArray)
                    {
                        // Convert to horizontal format since no //v directive preceded it
                        String horizontalFormat = formatArrayHorizontally(verticalResult.keyPart, verticalResult.elements, getIndentation(line));
                        processedLines.add(horizontalFormat);
                        i = verticalResult.endIndex;
                        fileModified = true;
                    }
                    else
                    {
                        processedLines.add(line);
                    }
                }
                else
                {   processedLines.add(line);
                }
            }

            // Only write the file if we made modifications
            if (fileModified)
            {   Files.write(filePath, processedLines);
                ColdSweat.LOGGER.debug("Formatted config file: {}", config.getFileName());
            }
        }
        catch (IOException e)
        {   ColdSweat.LOGGER.error("Failed to process config file: {}", filePath, e);
        }
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        var stack = player.getItemInHand(hand);

        if (!this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").canPlayerUse(player))
            return InteractionResultHolder.pass(stack);

        if (player.isShiftKeyDown() && this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getRankModifierData("salvo").isEnabled()) {
            if (!level.isClientSide()) {
                var hit = EntityUtils.rayTraceEntity(player, entity -> entity instanceof LivingEntity living && !living.isDeadOrDying() && !EntityUtils.isAlliedTo(player, living) && !living.is(player), 64D);

                if (!(hit instanceof EntityHitResult entityHit) || !(entityHit.getEntity() instanceof LivingEntity target))
                    return InteractionResultHolder.pass(stack);

                var stacks = this.getHealingStacks(stack);

                if (stacks.isEmpty())
                    return InteractionResultHolder.pass(stack);

                var look = player.getLookAngle();
                var eye = player.getEyePosition();
                var right = look.cross(new Vec3(0, 1, 0));

                if (right.lengthSqr() < 1e-4)
                    right = new Vec3(1, 0, 0);

                var up = look.cross(right).normalize();
                right = right.normalize();

                var count = stacks.size();
                var radius = 0.6D;
                var basePos = eye.subtract(look.scale(0.75D));

                for (int i = 0; i < count; i++) {
                    var healingStack = stacks.get(i);
                    var projectileDamage = Math.max(0F, healingStack.remainingHeal());

                    var angle = (Math.PI * 2D / count) * i + player.getRandom().nextDouble() * (Math.PI / count);
                    var offset = right.scale(Math.cos(angle) * radius).add(up.scale(Math.sin(angle) * radius));
                    var spawnPos = basePos.add(offset);

                    ServerScheduler.schedule(i * 2, () -> {
                        var projectile = new SelfSacrificeProjectileEntity(RelicsEntities.SELF_SACRIFICE_PROJECTILE.get(), level);

                        projectile.setOwner(player);
                        projectile.setPos(spawnPos);
                        projectile.setStack(stack);
                        projectile.setDeltaMovement(look.scale(0.25F).add(offset.normalize().scale(0.25F)).add(0, 0.05F, 0));
                        projectile.setDamage(projectileDamage);
                        projectile.setTarget(target);
                        projectile.setFlawless(this.getRelicData(player, stack).isVisuallyFlawless());

                        level.addFreshEntity(projectile);

                        this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getStatisticData().getMetricData("projectiles_created").addValue(1);
                    });
                }

                this.setHealingStacks(stack, List.of());
            }

            return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
        }

        if (!level.isClientSide()) {
            if (player.getHealth() / player.getMaxHealth() < 0.33F || this.getHealingStacks(stack).size() >= this.getRelicData(player, stack).getAbilitiesData().getAbilityData("sacrifice").getStatData("stacks").getValue())
                return InteractionResultHolder.pass(stack);

            var damage = this.getHealthCost(player);

            var remaining = Math.max(0F, player.getHealth() - 1F);

            damage = Math.min(damage, remaining);

            player.invulnerableTime = 0;
            player.hurt(level.damageSources().magic(), damage);

            this.getRelicData(player, stack).getLevelingData().addExperience("sacrifice", "self_inflicted", 1);

            this.addHealingStack(player, stack, this.buildHealingStack(player));
        }

        return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
    }

public static void shootProjectile(World world, LivingEntity caster, Entity target, RegistryEntry<Spell> spellEntry, ImpactContext context, int sequenceIndex) {
        if (world.isClient) {
            return;
        }

        var spell = spellEntry.value();
        var launchPoint = LaunchGeometry.launchPoint(caster);
        var data = spell.deliver.projectile;
        var projectileData = data.projectile;
        var mutablePerks = projectileData.perks.copy();
        var mutableLaunchProperties = data.launch_properties.copy();
        var scaleMultiplier = 1F;

        for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
            if (modifier.projectile_launch != null) {
                mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
            }
            if (modifier.projectile_perks != null) {
                mutablePerks.mutatingCombine(modifier.projectile_perks);
            }
            scaleMultiplier += modifier.projectile_scale_multiply;
        }

        var effectiveCaster = context.effectiveCaster(world);
        var owner = effectiveCaster != null ? effectiveCaster : caster;

        var projectile = new SpellProjectile(world, owner,
                launchPoint.getX(), launchPoint.getY(), launchPoint.getZ(),
                SpellProjectile.Behaviour.FLY, spellEntry, context, mutablePerks);
        projectile.setScaleMultiplier(scaleMultiplier);

        if (SpellEvents.PROJECTILE_SHOOT.isListened()) {
            SpellEvents.PROJECTILE_SHOOT.invoke((listener) -> listener.onProjectileLaunch(
                    new SpellEvents.ProjectileLaunchEvent(projectile, mutableLaunchProperties, caster, target, spellEntry, context, sequenceIndex)));
        }
        var velocity = mutableLaunchProperties.velocity;
        var divergence = projectileData.divergence;
        var directionPitch = data.inherit_shooter_pitch ? caster.getPitch() : 0;
        var directionYaw = data.inherit_shooter_yaw ? caster.getYaw() : 0;
        if (data.direct_towards_target && target != null) {
            var directionVector = target.getPos().subtract(caster.getPos()).normalize();
            // Yaw and pitch from distance vector
            directionPitch = (float) VectorHelper.pitchFromNormalized(directionVector);
            directionYaw = (float) VectorHelper.yawFromNormalized(directionVector);
        }
        if (data.inherit_shooter_velocity) {
            projectile.setVelocity(caster, directionPitch, directionYaw, 0, velocity, divergence);
        } else {
            if (data.direction_offsets != null && data.direction_offsets.length > 0
                && (!data.direction_offsets_require_target || target != null)) {
                var baseIndex = context.isChanneled() ? context.channelTickIndex() : sequenceIndex;
                var index = baseIndex % data.direction_offsets.length;
                var offset = data.direction_offsets[index];
                directionPitch += offset.pitch;
                directionYaw += offset.yaw;
            }
            // var look = caster.getRotationVector().normalize();
            var look = caster.getRotationVector(directionPitch, directionYaw).normalize();
            projectile.setVelocity(look.x, look.y, look.z, velocity, divergence);
        }
        // Charge `bonus.range_add` extends the projectile's flight distance (already ratio-scaled).
        var chargeModifier = context.chargeModifier();
        projectile.range = spell.range + (chargeModifier != null ? chargeModifier.range_add : 0F);
        projectile.setPitch(directionPitch);
        projectile.setYaw(directionYaw);

        projectile.setFollowedTarget(target);
        world.spawnEntity(projectile);
        SoundHelper.playSound(world, projectile, mutableLaunchProperties.sound);

        var allowExtraShoot = (context.isChanneled() && mutableLaunchProperties.extra_launch_mod >= 0)
                ? context.channelTickIndex() % mutableLaunchProperties.extra_launch_mod == 0
                : true;
        if (sequenceIndex == 0 && mutableLaunchProperties.extra_launch_count > 0 && allowExtraShoot) {
            for (int i = 0; i < mutableLaunchProperties.extra_launch_count; i++) {
                var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                var nextSequenceIndex = i + 1;
                ((WorldScheduler)world).schedule(ticks, () -> {
                    if (caster == null || !caster.isAlive()) {
                        return;
                    }
                    shootProjectile(world, caster, target, spellEntry, context, nextSequenceIndex);
                });
            }
        }
    }

public static void shootArrow(World world, LivingEntity shooter, RegistryEntry<Spell> spellEntry, SpellExecution.ImpactContext context, int sequenceIndex) {
        var spell = spellEntry.value();
        var shoot_arrow = spell.deliver.shoot_arrow;
        var weaponStack = shooter.getMainHandStack();

        // var weapon = weaponStack.getItem();
        // Using CROSSBOW statically, so arrows fired behave consistently
        // When using any bow, divergence is applied in an unhelpful manner
        var weapon = Items.CROSSBOW;
        if (shoot_arrow != null
                && (world instanceof ServerWorld serverWorld)
                && (weapon instanceof RangedWeaponItem rangedWeapon)) {
            var mutableLaunchProperties = shoot_arrow.launch_properties.copy();
            if (shooter instanceof PlayerEntity player) {
                var spellModifiers = SpellModifiers.of(player, spellEntry);
                for (var modifier: spellModifiers) {
                    if (modifier.projectile_launch != null) {
                        mutableLaunchProperties.mutatingCombine(modifier.projectile_launch);
                    }
                }
            }

            ItemStack ammo;
            if (shooter instanceof PlayerEntity player) {
                ammo = player.getProjectileType(weaponStack);
            } else {
                ammo = new ItemStack(Items.ARROW);
            }
            var loadedAmmo = RangedWeaponAccessor.load_SpellEngine(weaponStack, ammo, shooter);
            if (loadedAmmo.isEmpty()) {
                return;
            }

            // Save as active spell
            if (shooter instanceof SpellCaster.Player caster) {
                var shotContext = caster.getArrowShootContext();
                shotContext.firedBySpell = true;
                shotContext.activeSpells.add(spellEntry);
            }
            var divergence = (sequenceIndex == 0) ? 0F : shoot_arrow.divergence;
            // Perform shoot
            ((RangedWeaponAccessor) rangedWeapon).shootAll_SpellEngine(
                    serverWorld,
                    shooter,
                    Hand.MAIN_HAND,
                    weaponStack,
                    loadedAmmo,
                    shoot_arrow.launch_properties.velocity,
                    divergence,
                    shoot_arrow.arrow_critical_strike,
                    null);
            // Arrow perks applied by `RangedWeaponItemMixin`

            // Fixing inconsistent Vanille code, shoot sound is played by `BOW` outside of `shootAll`
            if (weapon instanceof BowItem) {
                world.playSound(
                        null,
                        shooter.getX(),
                        shooter.getY(),
                        shooter.getZ(),
                        SoundEvents.ENTITY_ARROW_SHOOT,
                        SoundCategory.PLAYERS,
                        1.0F,
                        1.0F / (world.getRandom().nextFloat() * 0.4F + 1.2F) + 1 * 0.5F
                );
            }

            if (shooter instanceof SpellCaster.Player caster) {
                caster.setArrowShootContext(ArrowShootContext.empty());
            }

            var extra_launch = mutableLaunchProperties.extra_launch_count;
            if (sequenceIndex == 0 && extra_launch > 0) {
                for (int i = 0; i < extra_launch; i++) {
                    var ticks = (i + 1) * mutableLaunchProperties.extra_launch_delay;
                    var nextSequenceIndex = i + 1;
                    ((WorldScheduler)world).schedule(ticks, () -> {
                        if (shooter == null || !shooter.isAlive()) {
                            return;
                        }
                        shootArrow(world, shooter, spellEntry, context, nextSequenceIndex);
                    });
                }
            }
        }
    }

public static void doPlayerTick(final PlayerTickEvent ev) {
		Player pl = ev.getEntity();

		if (ev instanceof PlayerTickEvent.Pre) {
			if (pl instanceof ServerPlayer serverPl) {
				if (isInParkourRegion(serverPl.blockPosition())) {
					if (PlayerUtil.shouldPlayerBeAffected(serverPl))
						PlayerUtil.getAdventPlayer(serverPl).stats.setInAbilityLockRegion();
				}
				else {
					PlayerUtil.getAdventPlayer(serverPl).stats.leaveAbilityLockRegion();
				}
			}
			else if (isInBossRegion(pl.blockPosition())) {
				List<AoABoss> bosses = EntityRetrievalUtil.getEntities(pl, 80, AoABoss.class);

				if (!bosses.isEmpty()) {
					AoABoss boss = bosses.getFirst();

					if (boss.getMusic() != null)
						SoundBuilder.asMusic(boss.getMusic(), boss.level()).onlyFor(pl).play();
				}
			}
		}
		else {
			pl.getAbilities().mayBuild = pl.isCreative();

			if (PlayerUtil.shouldPlayerBeAffected(pl)) {
				if (pl.getY() < pl.level().getMinBuildHeight()) {
					pl.fallDistance = -1;

					if (pl instanceof ServerPlayer serverPlayer) {
						if (!AdvancementUtil.isAdvancementCompleted(serverPlayer, AdventOfAscension.id("nowhere/root"))) {
							AoAScheduler.schedule(1, tick -> {
								PlayerUtil.resetToDefaultStatus(serverPlayer);
								InventoryUtil.clearItems(serverPlayer, AoAItems.RETURN_CRYSTAL);
								serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
								serverPlayer.connection.teleport(17.5d, 452.5d, 3.5d, 0, serverPlayer.getXRot());
							});
						}
						else {
							ServerPlayerDataManager plData = PlayerUtil.getAdventPlayer(serverPlayer);
							PositionAndRotation checkpoint = plData.storage.getActiveCheckpoint();

							if (checkpoint != null) {
								if (CheckpointBlock.isValidCheckpoint(serverPlayer.level(), checkpoint)) {
									AoAScheduler.schedule(1, tick -> {
										if (NowhereEvents.isInBossRegion(serverPlayer.blockPosition()))
											InventoryUtil.clearItems(serverPlayer, AoAItems.RETURN_CRYSTAL);

										PlayerUtil.resetToDefaultStatus(serverPlayer);

										if (!NowhereEvents.isInParkourRegion(serverPlayer.blockPosition())) {
											serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
										}
										else if (!InventoryUtil.hasItem(serverPlayer, AoAItems.RETURN_CRYSTAL)) {
											InventoryUtil.giveItemTo(serverPlayer, AoAItems.RETURN_CRYSTAL);
										}

										serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("checkpoint.respawn"), ChatFormatting.GREEN), true);
										checkpoint.applyToEntity(serverPlayer);
									});

									return;
								}
								else {
									plData.storage.clearActiveCheckpoint();
									serverPlayer.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("checkpoint.invalid"), ChatFormatting.RED));
								}
							}
							else {
								NowhereActivityPortal.Activity.RETURN.activate((ServerPlayer)pl);
							}
						}
					}
				}

				if (pl.isFallFlying())
					pl.stopFallFlying();

				if (isInFoodFreeRegion(pl.blockPosition())) {
					FoodData foodData = pl.getFoodData();

					foodData.setExhaustion(-4);
					foodData.setFoodLevel(20);
					foodData.setSaturation(20);
				}
			}
		}
	}

public static void placeCloud(World world, LivingEntity caster,
                                  @Nullable Entity target, @Nullable Vec3d location,
                                  RegistryEntry<Spell> spellEntry, ImpactContext context) {
        var spell = spellEntry.value();
        var clouds = spell.deliver.clouds;
        if (clouds == null || clouds.isEmpty()) {
            return;
        }
        if (target == null && location == null) {
            target = caster;
        }

        List<Spell.Modifier> spellModifiers = SpellModifiers.of(caster, spellEntry, context.chargeModifier());
        float extraTimeToLive = 0;
        var extraPlacements = new ArrayList<Spell.EntityPlacement>();
        // Summed cloud bonus, snapshotted onto each cloud below. Magnitudes accumulate; growth timing is
        // taken from the first modifier that actually contributes growth (see radiusForAge merge rules).
        var cloudModifier = new Spell.Modifier.Cloud();
        boolean cloudTimingSet = false;
        for (var spellModifier: spellModifiers) {
            extraTimeToLive += spellModifier.spawn_duration_add;
            extraPlacements.addAll(spellModifier.additional_placements);
            var cm = spellModifier.cloud;
            if (cm != null) {
                cloudModifier.radius_add += cm.radius_add;
                cloudModifier.growth.radius_step += cm.growth.radius_step;
                if (cm.growth.duration_ticks < 0 || cloudModifier.growth.duration_ticks < 0) {
                    cloudModifier.growth.duration_ticks = -1; // "whole life" sentinel wins over any span
                } else {
                    cloudModifier.growth.duration_ticks += cm.growth.duration_ticks;
                }
                if (!cloudTimingSet && cm.growth.radius_step != 0F) {
                    cloudModifier.growth.step_interval = cm.growth.step_interval;
                    cloudModifier.growth.start_tick = cm.growth.start_tick;
                    cloudTimingSet = true;
                }
            }
        }

        var index = 0;
        for (var cloud: clouds) {
            var placements = new ArrayList<Spell.EntityPlacement>();
            placements.add(cloud.placement);
            placements.addAll(cloud.additional_placements);
            if (index == 0) {
                placements.addAll(extraPlacements);
            }
            var base_delay = cloud.delay_ticks;

            for (var placement: placements) {
                var delay = base_delay + placement.delay_ticks;

                SpellCloud entity;
                if (cloud.entity_type_id != null) {
                    var id = Identifier.of(cloud.entity_type_id);
                    var type = Registries.ENTITY_TYPE.get(id);
                    entity = (SpellCloud) type.create(world);
                } else {
                    entity = new SpellCloud(world);
                }
                entity.setOwner(caster);
                entity.onCreatedFromSpell(spellEntry.getKey().get().getValue(), cloud, context, cloud.time_to_live_seconds + extraTimeToLive, cloudModifier);

                if (target != null) {
                    EntityPlacements.applyEntityPlacement(entity, target, target.getPos(), placement);
                } else if (location != null) {
                    EntityPlacements.applyEntityPlacement(caster.getWorld(), entity,
                            caster.getYaw(), caster.getPitch(), null,
                            location, placement);
                } else {
                    continue;
                }


                ((WorldScheduler)world).schedule(delay, () -> {
                    world.spawnEntity(entity);
                    var sound = cloud.spawn.sound;
                    if (sound != null) {
                        SoundHelper.playSound(world, entity, sound);
                    }
                    var spawnVisuals = cloud.spawn.visuals.resolved(Fx.Context.NONE);
                    ParticleHelper.sendBatches(entity, spawnVisuals.particles);
                    ModelEffectHelper.spawn(world, entity.getPos(), entity.getYaw(), spawnVisuals.models, null);
                });

                if (cloud.placement_delay_stacks) {
                    base_delay = delay;
                }
            }
            index += 1;
        }
    }

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            var entity = event.getEntity();
            var level = entity.level();
            var random = level.getRandom();

            var damage = event.getNewDamage();
            var health = entity.getHealth();
            var absorption = entity.getAbsorptionAmount();

            if (damage < health)
                return;

            var damageToThreshold = health - 0.1F;
            var remaining = damage - damageToThreshold;
            var diff = absorption - remaining;

            if (diff > 0)
                return;

            for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.LEAFY_MANTLE.get())) {
                var relic = (LeafyMantleItem) stack.getItem();

                if (!relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").canPlayerUse(entity))
                    continue;

                if (diff > 0)
                    break;

                if (!level.isClientSide())
                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("damage_negated").addValue(Math.abs(diff));

                var radius = (int) Math.ceil(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("radius").getValue());
                var heal = (float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("heal").getValue();

                var center = entity.blockPosition();

                var positions = IntStream.rangeClosed(-radius, radius).boxed()
                        .flatMap(dx -> IntStream.rangeClosed(-radius, radius)
                                .boxed()
                                .flatMap(dy -> IntStream.rangeClosed(-radius, radius)
                                        .mapToObj(dz -> new BlockPos(center.getX() + dx, center.getY() + dy, center.getZ() + dz))))
                        .filter(pos -> level.getBlockState(pos).is(BlockTags.LEAVES))
                        .sorted(Comparator.comparingDouble(pos -> pos.distSqr(center)))
                        .toList();

                var potential = positions.size() * heal;

                if (potential + diff < 0)
                    continue;

                var blocks = 0;

                for (var pos : positions) {
                    ServerScheduler.schedule(blocks + random.nextInt(10), () -> {
                        var leaves = new LeavesBlockEntity(RelicsEntities.LEAVES_BLOCK.get(), level);

                        var posVec = new Vec3(pos.getX() + 0.5D, pos.getY() + 0.5D, pos.getZ() + 0.5D);

                        var toPlayer = entity.position().subtract(posVec).normalize();
                        var randomVec = new Vec3(MathUtils.randomFloat(random), MathUtils.randomFloat(random), MathUtils.randomFloat(random));
                        var perpendicular = randomVec.subtract(toPlayer.scale(randomVec.dot(toPlayer))).normalize().scale(0.5D + random.nextDouble() * 0.5D);

                        leaves.setParalysis((float) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatData("paralysis").getValue());
                        leaves.setDeltaMovement(perpendicular.scale(0.5F + random.nextFloat()));
                        leaves.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
                        leaves.setPos(posVec.x(), posVec.y(), posVec.z());
                        leaves.setBlockState(level.getBlockState(pos));
                        leaves.setTarget(entity);
                        leaves.setOwner(entity);
                        leaves.setDamage(heal);
                        leaves.setStack(stack);

                        level.addFreshEntity(leaves);

                        level.destroyBlock(pos, false);

                        if (!level.isClientSide()) {
                            relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("revival").getStatisticData().getMetricData("leaves_consumed").addValue(1);

                            relic.getRelicData(entity, stack).getLevelingData().addExperience("revival", "consuming_leaves", 1);
                        }
                    });

                    blocks++;

                    diff += heal;

                    if (diff >= 0)
                        break;
                }

                if (blocks > 0) {
                    event.setNewDamage(damageToThreshold);

                    if (diff > 0) {
                        var healAmount = diff;

                        ServerScheduler.schedule(1, () -> {
                            entity.heal(healAmount);
                        });
                    }
                }
            }
        }

private void renderFront(DreadwhisperVisualEntity entity, float tickDelta, MatrixStack matrices,
                             VertexConsumerProvider consumers) {
        LivingEntity owner = entity.getOwner();
        if (entity.getCollapseAge() < 0 && owner != null) {
            Vec3d correction = owner.getLerpedPos(tickDelta).subtract(entity.getLerpedPos(tickDelta));
            matrices.translate(correction.x, correction.y, correction.z);
        }

        float age = entity.age + tickDelta;
        float appear = smooth(MathHelper.clamp(age / 2.2F, 0.0F, 1.0F));
        float fade = 1.0F;
        if (entity.getCollapseAge() >= 0) {
            fade = 1.0F - smooth(MathHelper.clamp(
                    (age - entity.getCollapseAge()) / Math.max(1.0F, entity.getLifetime() - entity.getCollapseAge()),
                    0.0F, 1.0F));
        }
        float opacity = appear * fade;
        if (opacity <= 0.01F) {
            return;
        }

        Vec3d direction = entity.getDirection();
        Vec3d side = new Vec3d(-direction.z, 0.0, direction.x);
        float width = entity.getVisualWidth() * (0.84F + appear * 0.16F);
        float height = entity.getVisualHeight();
        float firstPersonOpacity = 1.0F;
        if (isFirstPersonOwner(owner)) {
            matrices.translate(direction.x * 0.72, -0.52, direction.z * 0.72);
            firstPersonOpacity = 0.56F;
        }
        renderSmoke(entity, age, opacity, firstPersonOpacity, width, height, direction, side, matrices, consumers);
        Matrix4f matrix = matrices.peek().getPositionMatrix();
        VertexConsumer field = IonDeferredRenderController.getFieldBuffer();

        for (int i = 0; i < 15; i++) {
            float sidePosition = (i & 1) == 0
                    ? MathHelper.lerp(noise(entity.getSeed() + 31, i), 0.18F, 0.54F) * width
                    : MathHelper.lerp(noise(entity.getSeed() + 31, i), -0.54F, -0.18F) * width;
            float edge = Math.abs(sidePosition) / Math.max(0.1F, width * 0.5F);
            float baseY = 0.18F + noise(entity.getSeed() + 59, i) * height * 0.52F;
            float radius = (0.46F + noise(entity.getSeed() + 83, i) * 0.48F)
                    * (0.92F + edge * 0.24F);
            float pulse = 0.92F + MathHelper.sin(age * 0.19F + i * 1.67F) * 0.08F;
            Vec3d center = side.multiply(sidePosition)
                    .add(direction.multiply((noise(entity.getSeed() + 107, i) - 0.5F) * 0.72F))
                    .add(0.0, baseY, 0.0);
            int color = i % 3 == 0 ? VOID_BLACK : i % 3 == 1 ? DEEP_PURPLE : MID_PURPLE;
            int alpha = alpha((i % 3 == 0 ? 170.0F : 132.0F) * opacity
                    * (edge < 0.26F ? firstPersonOpacity : 1.0F));
            cloudLobe(field, matrix, center, side, direction, radius * pulse,
                    radius * (0.72F + noise(entity.getSeed() + 137, i) * 0.55F), color, alpha,
                    noise(entity.getSeed() + 163, i) * MathHelper.TAU);
        }

        for (int i = 0; i < 12; i++) {
            float lateral = MathHelper.lerp(noise(entity.getSeed() + 211, i), -0.49F, 0.49F) * width;
            float y = 0.3F + noise(entity.getSeed() + 251, i) * height * 0.66F;
            float trailLength = (2.4F + noise(entity.getSeed() + 277, i) * 2.4F) * appear;
            float wobble = MathHelper.sin(age * 0.22F + i * 1.37F) * 0.16F;
            Vec3d start = side.multiply(lateral).add(direction.multiply(-0.1F)).add(0.0, y, 0.0);
            Vec3d middle = side.multiply(lateral + wobble)
                    .add(direction.multiply(-trailLength * 0.48F))
                    .add(0.0, y + (noise(entity.getSeed() + 313, i) - 0.5F) * 0.52F, 0.0);
            Vec3d end = side.multiply(lateral + wobble * 0.4F)
                    .add(direction.multiply(-trailLength))
                    .add(0.0, y + (noise(entity.getSeed() + 337, i) - 0.5F) * 0.72F, 0.0);
            float thickness = 0.13F + noise(entity.getSeed() + 359, i) * 0.14F;
            ribbon(field, matrix, start, middle, side, thickness, DEEP_PURPLE, alpha(150.0F * opacity));
            ribbon(field, matrix, middle, end, side, thickness * 0.58F, VOID_BLACK, alpha(122.0F * opacity));
        }

        VertexConsumer energy = IonDeferredRenderController.getLightningBuffer();
        for (int i = 0; i < 12; i++) {
            float lateral = MathHelper.lerp(noise(entity.getSeed() + 211, i), -0.49F, 0.49F) * width;
            float y = 0.3F + noise(entity.getSeed() + 251, i) * height * 0.66F;
            float trailLength = (2.4F + noise(entity.getSeed() + 277, i) * 2.4F) * appear;
            float wobble = MathHelper.sin(age * 0.22F + i * 1.37F) * 0.16F;
            Vec3d start = side.multiply(lateral).add(direction.multiply(-0.09F)).add(0.0, y, 0.0);
            Vec3d middle = side.multiply(lateral + wobble)
                    .add(direction.multiply(-trailLength * 0.48F))
                    .add(0.0, y + (noise(entity.getSeed() + 313, i) - 0.5F) * 0.52F, 0.0);
            Vec3d end = side.multiply(lateral + wobble * 0.4F)
                    .add(direction.multiply(-trailLength))
                    .add(0.0, y + (noise(entity.getSeed() + 337, i) - 0.5F) * 0.72F, 0.0);
            int color = i % 4 == 0 ? SICKLY_GREEN : REND_PURPLE;
            ribbon(energy, matrix, start, middle, side, 0.026F, color, alpha(220.0F * opacity));
            ribbon(energy, matrix, middle, end, side, 0.014F, color, alpha(176.0F * opacity));
        }

        float[] nodes = {-0.31F, 0.0F, 0.31F};
        for (int i = 0; i < nodes.length; i++) {
            float bob = MathHelper.sin(age * 0.34F + i * 2.1F) * 0.08F;
            Vec3d center = side.multiply(nodes[i] * width)
                    .add(direction.multiply(0.18F))
                    .add(0.0, height * (i == 1 ? 0.53F : 0.46F) + bob, 0.0);
            float size = (i == 1 ? 0.28F : 0.23F) * (0.9F + MathHelper.sin(age * 0.45F + i) * 0.1F);
            diamond(energy, matrix, center, side, size * 2.1F, size * 1.45F,
                    MID_PURPLE, alpha(150.0F * opacity));
            diamond(energy, matrix, center.add(direction.multiply(0.012F)), side, size * 1.25F, size,
                    SICKLY_GREEN, alpha(235.0F * opacity));
            diamond(energy, matrix, center.add(direction.multiply(0.018F)), side, size * 0.46F, size * 0.42F,
                    PALE_GREEN, alpha(245.0F * opacity));
        }

        for (int i = 0; i < 24; i++) {
            float phase = fract(noise(entity.getSeed() + 401, i) + age * (0.035F + noise(entity.getSeed() + 431, i) * 0.025F));
            float lateral = MathHelper.lerp(noise(entity.getSeed() + 457, i), -0.56F, 0.56F) * width;
            float y = 0.18F + noise(entity.getSeed() + 479, i) * height;
            float rear = phase * (3.2F + noise(entity.getSeed() + 503, i) * 1.7F);
            Vec3d head = side.multiply(lateral).add(direction.multiply(-rear)).add(0.0, y, 0.0);
            Vec3d tail = head.add(direction.multiply(-0.22F - noise(entity.getSeed() + 541, i) * 0.38F))
                    .add(0.0, (noise(entity.getSeed() + 563, i) - 0.5F) * 0.25F, 0.0);
            ribbon(energy, matrix, head, tail, side, 0.018F + noise(entity.getSeed() + 587, i) * 0.016F,
                    i % 5 == 0 ? SICKLY_GREEN : REND_PURPLE,
                    alpha((170.0F + (1.0F - phase) * 65.0F) * opacity));
        }
    }

@MethodSource("newTestParams")
    @ParameterizedTest
    @Timeout(30)
    public void clientInitiatedRenegotiationWithFatalAlertDoesNotInfiniteLoopServer(final SSLEngineTestParam param)
            throws Exception {
        assumeTrue(PlatformDependent.javaVersion() >= 11);
        final SelfSignedCertificate ssc = CachedSelfSignedCertificate.getCachedCertificate();
        serverSslCtx = wrapContext(param, SslContextBuilder.forServer(ssc.certificate(), ssc.privateKey())
                                        .sslProvider(sslServerProvider())
                                        .sslContextProvider(serverSslContextProvider())
                                        .protocols(param.protocols())
                                        .ciphers(param.ciphers())
                                        .build());
        sb = new ServerBootstrap()
                .group(new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory()))
                .channel(NioServerSocketChannel.class)
                .childHandler(new ChannelInitializer<SocketChannel>() {
                    @Override
                    public void initChannel(SocketChannel ch) {
                        ch.config().setAllocator(new TestByteBufAllocator(ch.config().getAllocator(), param.type));

                        ChannelPipeline p = ch.pipeline();

                        SslHandler handler = !param.delegate ?
                                serverSslCtx.newHandler(ch.alloc()) :
                                serverSslCtx.newHandler(ch.alloc(), delegatingExecutor);

                        p.addLast(handler);
                        p.addLast(new ChannelInboundHandlerAdapter() {
                            @Override
                            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                                if (evt instanceof SslHandshakeCompletionEvent &&
                                        ((SslHandshakeCompletionEvent) evt).isSuccess()) {
                                    // This data will be sent to the client before any of the re-negotiation data can be
                                    // sent. The client will read this, detect that it is not the response to
                                    // renegotiation which was expected, and respond with a fatal alert.
                                    ctx.writeAndFlush(ctx.alloc().buffer(1).writeByte(100));
                                }
                                ctx.fireUserEventTriggered(evt);
                            }

                            @Override
                            public void channelRead(final ChannelHandlerContext ctx, Object msg) {
                                ReferenceCountUtil.release(msg);
                                // The server then attempts to trigger a flush operation once the application data is
                                // received from the client. The flush will encrypt all data and should not result in
                                // deadlock.
                                ctx.channel().eventLoop().schedule(new Runnable() {
                                    @Override
                                    public void run() {
                                        ctx.writeAndFlush(ctx.alloc().buffer(1).writeByte(101));
                                    }
                                }, 500, TimeUnit.MILLISECONDS);
                            }

                            @Override
                            public void channelInactive(ChannelHandlerContext ctx) {
                                serverLatch.countDown();
                            }
                        });
                        serverConnectedChannel = ch;
                    }
                });

        serverChannel = sb.bind(new InetSocketAddress(0)).syncUninterruptibly().channel();

        clientSslCtx = wrapContext(param, SslContextBuilder.forClient()
                                        // OpenSslEngine doesn't support renegotiation on client side
                                        .sslProvider(SslProvider.JDK)
                                        .trustManager(InsecureTrustManagerFactory.INSTANCE)
                                        .protocols(param.protocols())
                                        .ciphers(param.ciphers())
                                        .build());

        cb = new Bootstrap();
        cb.group(new MultiThreadIoEventLoopGroup(1, NioIoHandler.newFactory()))
                .channel(NioSocketChannel.class)
                .handler(new ChannelInitializer<SocketChannel>() {
                    @Override
                    public void initChannel(SocketChannel ch) {
                        ch.config().setAllocator(new TestByteBufAllocator(ch.config().getAllocator(), param.type()));

                        ChannelPipeline p = ch.pipeline();

                        SslHandler sslHandler = !param.delegate ?
                                clientSslCtx.newHandler(ch.alloc()) :
                                clientSslCtx.newHandler(ch.alloc(), delegatingExecutor);

                        // The renegotiate is not expected to succeed, so we should stop trying in a timely manner so
                        // the unit test can terminate relativley quicly.
                        sslHandler.setHandshakeTimeout(1, TimeUnit.SECONDS);
                        p.addLast(sslHandler);
                        p.addLast(new ChannelInboundHandlerAdapter() {
                            private int handshakeCount;
                            @Override
                            public void userEventTriggered(ChannelHandlerContext ctx, Object evt) {
                                // OpenSSL SSLEngine sends a fatal alert for the renegotiation handshake because the
                                // user data read as part of the handshake. The client receives this fatal alert and is
                                // expected to shutdown the connection. The "invalid data" during the renegotiation
                                // handshake is also delivered to channelRead(..) on the server.
                                // JDK SSLEngine completes the renegotiation handshake and delivers the "invalid data"
                                // is also delivered to channelRead(..) on the server. JDK SSLEngine does not send a
                                // fatal error and so for testing purposes we close the connection after we have
                                // completed the first renegotiation handshake (which is the second handshake).
                                if (evt instanceof SslHandshakeCompletionEvent && ++handshakeCount == 2) {
                                    ctx.close();
                                    return;
                                }
                                ctx.fireUserEventTriggered(evt);
                            }

                            @Override
                            public void channelRead(ChannelHandlerContext ctx, Object msg) {
                                ReferenceCountUtil.release(msg);
                                // Simulate a request that the server's application logic will think is invalid.
                                ctx.writeAndFlush(ctx.alloc().buffer(1).writeByte(102));
                                ctx.pipeline().get(SslHandler.class).renegotiate();
                            }
                        });
                        p.addLast(new SilenceExceptionHandler()
                                .messageContains("no_renegotiation"));
                    }
                });

        ChannelFuture ccf = cb.connect(serverChannel.localAddress());
        assertTrue(ccf.syncUninterruptibly().isSuccess());
        clientChannel = ccf.channel();

        serverLatch.await();
    }

@SubscribeEvent
    public static void eventHandler(ScreenEvent.Init.Post event)
    {
        if (event.getScreen() instanceof OptionsScreen && ConfigSettings.SHOW_CONFIG_BUTTON.get())
        {
            // The offset from the config
            Supplier<Vector2i> buttonPos = ConfigSettings.CONFIG_BUTTON_POS;
            AtomicInteger xOffset = new AtomicInteger(buttonPos.get().x());
            AtomicInteger yOffset = new AtomicInteger(buttonPos.get().y());
            int buttonX = event.getScreen().width / 2 - 183;
            int buttonY = event.getScreen().height / 6 + 110;
            int screenWidth = event.getScreen().width;
            int screenHeight = event.getScreen().height;

            if (xOffset.get() + buttonX < -1 || yOffset.get() + buttonY < -1)
            {   xOffset.set(0);
                yOffset.set(0);
                ConfigSettings.CONFIG_BUTTON_POS.set(new Vector2i(0, 0));
            }

            // Main config button
            ImageButton mainButton = new ImageButton(buttonX + xOffset.get(), buttonY + yOffset.get(),
                                     24, 24, 40, 40, 24,
                                     new ResourceLocation("cold_sweat:textures/gui/screen/config_gui.png"),
                                     button ->
                                     {
                                         ConfigScreen.CURRENT_PAGE = 0;
                                         if (Minecraft.getInstance().player != null)
                                         {   ColdSweatPacketHandler.INSTANCE.sendToServer(new ClientConfigAskMessage(Minecraft.getInstance().player.getUUID()));
                                         }
                                     });

            if (Minecraft.getInstance().level == null)
            {
                mainButton.active = false;
                mainButton.setTooltip(Tooltip.create(Component.translatable("tooltip.cold_sweat.config.must_be_in_game").withStyle(ChatFormatting.RED)));
            }

            // Add main button
            event.addListener(mainButton);

            // Reconfigure the options screen with controls for the position of the config button
            if (EDIT_MODE)
            {
                int buttonStartX = event.getScreen().width / 2 - 183;
                int buttonStartY = event.getScreen().height / 6 + 110;
                Runnable saveAndClamp = () ->
                {   xOffset.set(CSMath.clamp(xOffset.get(), -buttonStartX, screenWidth - mainButton.getWidth() - buttonStartX));
                    yOffset.set(CSMath.clamp(yOffset.get(), -buttonStartY, screenHeight - mainButton.getHeight() - buttonStartY));
                    mainButton.setPosition(buttonStartX + xOffset.get(), buttonStartY + yOffset.get());
                    ConfigSettings.CONFIG_BUTTON_POS.set(new Vector2i(xOffset.get(), yOffset.get()));
                };

                AtomicReference<AbstractButton> doneButtonAtomic = new AtomicReference<>(null);
                // Disable all other buttons
                event.getScreen().children().forEach(child ->
                {
                    // Don't disable "Done" button
                    if (child instanceof AbstractButton button)
                    {
                        boolean isDoneButton = button.getMessage().getString().equals(CommonComponents.GUI_DONE.getString());
                        if (!isDoneButton)
                        {   button.active = false;
                        }
                        else
                        {   doneButtonAtomic.set(button);
                            button.setWidth(button.getWidth() - 72);
                        }
                    }
                    if (child instanceof AbstractSliderButton slider)
                    {   slider.active = false;
                    }
                });

                if (doneButtonAtomic.get() == null) return;
                AbstractButton doneButton = doneButtonAtomic.get();

                // Create "left" button
                ImageButton leftButton = new ImageButton(doneButton.getX() + doneButton.getWidth() + 2, doneButton.getY(), 14, 20, 0, 0, 20,
                                     new ResourceLocation("cold_sweat:textures/gui/screen/config_gui.png"),
                                     button ->
                                     {   xOffset.set(xOffset.get() - ConfigScreen.SHIFT_AMOUNT.get());
                                         saveAndClamp.run();
                                     });
                // Add left button
                event.addListener(leftButton);

                // Create "up" button
                ImageButton upButton = new ImageButton(leftButton.getX() + leftButton.getWidth(), leftButton.getY(), 20, 10, 14, 0, 20,
                                     new ResourceLocation("cold_sweat:textures/gui/screen/config_gui.png"),
                                     button ->
                                     {   yOffset.set(yOffset.get() - ConfigScreen.SHIFT_AMOUNT.get());
                                         saveAndClamp.run();
                                     });
                // Add up button
                event.addListener(upButton);

                // Create "down" button
                ImageButton downButton = new ImageButton(upButton.getX(), upButton.getY() + upButton.getHeight(), 20, 10, 14, 10, 20,
                                     new ResourceLocation("cold_sweat:textures/gui/screen/config_gui.png"),
                                     button ->
                                     {   yOffset.set(yOffset.get() + ConfigScreen.SHIFT_AMOUNT.get());
                                         saveAndClamp.run();
                                     });
                // Add down button
                event.addListener(downButton);

                // Create "right" button
                ImageButton rightButton = new ImageButton(upButton.getX() + upButton.getWidth(), upButton.getY(), 14, 20, 34, 0, 20,
                                     new ResourceLocation("cold_sweat:textures/gui/screen/config_gui.png"),
                                     button ->
                                     {   xOffset.set(xOffset.get() + ConfigScreen.SHIFT_AMOUNT.get());
                                         saveAndClamp.run();
                                     });
                // Add right button
                event.addListener(rightButton);

                // Create "reset" button
                ImageButton resetButton = new ImageButton(rightButton.getX() + rightButton.getWidth() + 2, rightButton.getY(), 20, 20, 48, 0, 20,
                                     new ResourceLocation("cold_sweat:textures/gui/screen/config_gui.png"),
                                     button ->
                                     {   xOffset.set(0);
                                         yOffset.set(0);
                                         saveAndClamp.run();
                                     });
                // Add reset button
                event.addListener(resetButton);

                TaskScheduler.scheduleClient(() -> EDIT_MODE = false, 1);
            }
        }
    }

@Inject(method = "updateEntityAfterFallOn", at = @At("HEAD"), cancellable = true)
    public void onEntityFall(BlockGetter getter, Entity entity, CallbackInfo ci) {
        if (!(entity instanceof LivingEntity livingEntity))
            return;

        var level = livingEntity.level();

        var waveIndex = 0;

        for (var stack : EntityUtils.findEquippedCurios(livingEntity, RelicsItems.SPRINGY_BOOT.get())) {
            if (!(stack.getItem() instanceof SpringyBootItem relic))
                continue;

            if (relic.isLeaped(stack)) {
                if (relic.getBounceCooldown(stack) <= 0) {
                    if (!livingEntity.level().isClientSide()) {
                        var motion = livingEntity.getKnownMovement();
                        var speed = motion.y();

                        if (speed <= -0.75D) {
                            relic.addBounceCooldown(stack, 5);
                            relic.addLeaps(stack, 1);

                            speed = Math.abs(speed);

                            if (!livingEntity.isShiftKeyDown()) {
                                if (!level.isClientSide()) {
                                    relic.getRelicData(livingEntity, stack).getLevelingData().addExperience("bounce", "bounce", 1);

                                    relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("secondary_bounces").addValue(1);
                                }

                                level.playSound(null, livingEntity.blockPosition(), RelicsSounds.SPRING_BOING.get(), SoundSource.PLAYERS, (float) Math.clamp(0.5F + speed * 0.5F, 0.5F, 2F), (float) Math.max(0.1F, 2F - speed * 0.75F));

                                NetworkHandler.sendToClientsTrackingEntityAndSelf(new S2CBounceFromSurface(livingEntity.getId(), motion.multiply(1F, -1F, 1F).toVector3f()), livingEntity);

                                SpringyBootItem.spawnBounceFog(level, livingEntity, Math.max(1.1D, speed * 0.85D), 12 + Mth.ceil(speed * 2.5D));
                            } else {
                                if (relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getRankModifierData("shockwave").isEnabled()) {
                                    var delayTicks = waveIndex * 20;

                                    var center = livingEntity.blockPosition();
                                    var verticalSpeed = Math.abs(livingEntity.getKnownMovement().y());
                                    var radius = (int) Math.min(25, Math.round((1 + relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("radius").getValue()) * verticalSpeed));
                                    var damage = (float) relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("damage").getValue();
                                    var stun = (int) relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatData("stun").getValue() * 20;
                                    var serverLevel = (ServerLevel) level;

                                    relic.getRelicData(livingEntity, stack).getLevelingData().addExperience("bounce", "create_shockwave", radius);

                                    ServerScheduler.schedule(delayTicks, () -> {
                                        relic.getRelicData(livingEntity, stack).getAbilitiesData().getAbilityData("bounce").getStatisticData().getMetricData("shockwaves_amount").addValue(1);

                                        var poses = new ArrayList<BlockPos>();

                                        for (var i = -radius; i <= radius; i++) {
                                            var r1 = (int) Mth.sqrt(radius * radius - i * i);

                                            for (var j = -r1; j <= r1; j++)
                                                poses.add(center.offset(i, 0, j));
                                        }

                                        for (var step = 0; step <= radius; step++) {
                                            var finalStep = step;

                                            ServerScheduler.schedule(finalStep, () -> {
                                                var height = 0.25F;

                                                poses.stream().filter(pos -> {
                                                    var dx = pos.getX() - center.getX();
                                                    var dz = pos.getZ() - center.getZ();

                                                    var dist = Math.hypot(dx, dz);

                                                    return dist >= finalStep && dist < finalStep + 1;
                                                }).forEach(entryPos -> {
                                                    var centerY = center.getY();
                                                    var maxOffset = 8;

                                                    var groundY = WorldUtils.findSurfaceY(level, entryPos.getX(), entryPos.getZ(), centerY, maxOffset);

                                                    var minAllowedY = Math.max(level.getMinBuildHeight(), centerY - maxOffset);
                                                    var maxAllowedY = Math.min(level.getMaxBuildHeight(), centerY + maxOffset);

                                                    if (groundY < minAllowedY || groundY > maxAllowedY)
                                                        return;

                                                    var surfacePos = new BlockPos(entryPos.getX(), groundY, entryPos.getZ());
                                                    var shockwave = new SpringyBootShockwaveBlockEntity(RelicsEntities.SHOCKWAVE_BLOCK.get(), level);

                                                    shockwave.setDamage(damage);
                                                    shockwave.setStun(stun);
                                                    shockwave.setPos(surfacePos.getX() + 0.5F, surfacePos.getY(), surfacePos.getZ() + 0.5F);
                                                    shockwave.setBlockState(level.getBlockState(surfacePos));
                                                    shockwave.setDeltaMovement(0, height, 0);
                                                    shockwave.setOwner(livingEntity);
                                                    shockwave.setCenter(surfacePos);
                                                    shockwave.setKnockback(1F);
                                                    shockwave.setStack(stack);

                                                    level.addFreshEntity(shockwave);

                                                    var px = surfacePos.getX() + 0.15D + level.random.nextDouble() * 0.7D;
                                                    var pz = surfacePos.getZ() + 0.15D + level.random.nextDouble() * 0.7D;

                                                    var direction = new Vec3(px - (center.getX() + 0.5D), 0D, pz - (center.getZ() + 0.5D));

                                                    if (direction.lengthSqr() < 0.001D)
                                                        direction = new Vec3(level.random.nextDouble() - 0.5D, 0D, level.random.nextDouble() - 0.5D);

                                                    direction = direction.normalize();

                                                    var particleSpeed = 0.008D + level.random.nextDouble() * 0.012D;
                                                    var lifetime = 10 + level.random.nextInt(25);
                                                    var fogPosition = new Vector3f((float) px, surfacePos.getY() + 0.04F, (float) pz);
                                                    var fogMotion = new Vector3f((float) (direction.x * particleSpeed), height / 2F, (float) (direction.z * particleSpeed));

                                                    NetworkHandler.sendToClientsTrackingChunk(new S2CSpawnParticle(new GhostlyFogParticle.Options(lifetime), fogPosition, fogMotion), serverLevel, new ChunkPos(surfacePos));
                                                });
                                            });
                                        }
                                    });

                                    waveIndex++;
                                }
                            }
                        }
                    }
                }

                ci.cancel();
            }
        }
    }

public void initWindow(@Nullable String mcVersion) {
        // Initialize a time guard, in case something goes wrong
        long initBegin = System.nanoTime();
        if (!SDL_Init(SDL_INIT_VIDEO)) {
            crashElegantly("We are unable to initialize the graphics system.\nSDL_Init failed.\n");
            throw new IllegalStateException("Unable to initialize SDL");
        }
        long initEnd = System.nanoTime();

        if (initEnd - initBegin > 1e9)
            LOGGER.error("WARNING : Window init took {} seconds to start.", (initEnd - initBegin) / 1.0e9);

        // Set window hints for the new window we're gonna create.
        SDL_ResetHints();

        String vanillaWindowTitle = "Minecraft* ";
        if (mcVersion != null)
            vanillaWindowTitle += mcVersion;

        var primaryMonitor = SDL_GetPrimaryDisplay();
        if (primaryMonitor == 0) {
            LOGGER.error("Failed to find a primary monitor - this means LWJGL isn't working properly");
            crashElegantly("Failed to locate a primary monitor.\nSDL_GetPrimaryDisplay failed.\n");
            throw new IllegalStateException("Can't find a primary monitor");
        }

        var vidmode = SDL_GetDesktopDisplayMode(primaryMonitor);
        if (vidmode == null) {
            LOGGER.error("Failed to get the current display video mode.");
            crashElegantly("Failed to get current display resolution.\nSDL_GetDesktopDisplayMode failed.\n");
            throw new IllegalStateException("Can't get a resolution");
        }

        long window = 0;
        var successfulWindow = new AtomicBoolean(false);
        var windowFailFuture = renderScheduler.schedule(() -> {
            if (!successfulWindow.get())
                crashElegantly("Timed out trying to setup the Game Window.");
        }, 10, TimeUnit.SECONDS);

        var skipVersions = FMLConfig.<String>getListConfigValue(FMLConfig.ConfigValue.EARLY_WINDOW_SKIP_GL_VERSIONS);
        boolean showHelpLog = FMLConfig.getBoolConfigValue(FMLConfig.ConfigValue.EARLY_WINDOW_LOG_HELP_MSG);

        record Attempt(String vesion, String error) {}
        final List<Attempt> attempts = new ArrayList<>();
        String requestedVersion = null;

        for (int x = 0; x < GL_VERSIONS.length; x++) {
            var version = GL_VERSIONS[x];
            requestedVersion = version[0] + "." + version[1];

            if (skipVersions.contains(requestedVersion)) {
                LOGGER.info("Skipping GL version " + requestedVersion + " because of configuration");
                continue;
            }

            LOGGER.info("Trying GL version " + requestedVersion);
            if (showHelpLog && x == 0) {
                LOGGER.info("""
                If this message is the only thing at the bottom of your log before a crash, you probably have a driver issue.

                Possible solutions:
                A) Make sure Minecraft is set to prefer high performance graphics in the OS and/or driver control panel
                B) Check for driver updates on the graphics brand's website
                C) Try reinstalling your graphics drivers
                D) If still not working after trying all of the above, ask for further help on the Forge forums or Discord

                You can safely ignore this message if the game starts up successfully.""");
            }

            SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,    version[0]);
            SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,    version[1]);
            SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,     SDL_GL_CONTEXT_PROFILE_CORE);
            SDL_GL_SetAttribute(SDL_GL_CONTEXT_FLAGS,            SDL_GL_CONTEXT_FORWARD_COMPATIBLE_FLAG);
            SDL_GL_SetAttribute(SDL_GL_FRAMEBUFFER_SRGB_CAPABLE, GL_TRUE);
            window = SDL_CreateWindow(vanillaWindowTitle, winWidth, winHeight,
                  SDL_WINDOW_OPENGL
                | SDL_WINDOW_RESIZABLE
                | SDL_WINDOW_HIGH_PIXEL_DENSITY
            );

            if (window == 0) {
                var error = Objects.requireNonNullElse(SDLError.SDL_GetError(), "<no error>");
                attempts.add(new Attempt(requestedVersion, error));
                LOGGER.trace("Failed to create window using %d.%d: %s", version[0], version[1], error);
            } else {
                SDLVideo.SDL_SetWindowMinimumSize(window, 320, 240);
                LOGGER.info("Created window using SDL video driver: {}", SDLVideo.SDL_GetCurrentVideoDriver());
                break; // We got a valid window!
            }
        }

        if (window == 0) {
            LOGGER.error("Failed to find any valid GLFW profile.");
            var message = new StringBuilder()
                .append("Failed to find a valid GLFW profile.\n");

            if (attempts.isEmpty()) {
                message.append("All GL Versions were skipped");
            } else {
                message.append("We tried:");
                for (var attempt : attempts)
                    message.append("\n\t").append(attempt.vesion).append(':').append(attempt.error);
            }

            crashElegantly(message.toString());
            throw new IllegalStateException("Failed to create a GLFW window with any profile");
        }

        successfulWindow.set(true);
        if (!windowFailFuture.cancel(true))
            throw new IllegalStateException("We died but didn't somehow?");

        try (var stack = org.lwjgl.system.MemoryStack.stackPush()) {
            var majBuf = stack.mallocInt(1);
            var minBuf = stack.mallocInt(1);
            SDL_GL_GetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION, majBuf);
            SDL_GL_GetAttribute(SDL_GL_CONTEXT_MINOR_VERSION, minBuf);
           this.glVersion = majBuf.get(0) + "." + minBuf.get(0);
        }

        LOGGER.info("Requested GL version " + requestedVersion + " got version " + this.glVersion);
        this.window = window;

        if (showHelpLog)
            FMLConfig.updateConfig(FMLConfig.ConfigValue.EARLY_WINDOW_LOG_HELP_MSG, false);

        if (this.maximized)
            SDL_MaximizeWindow(window);

        var size = getWindowSize(window);
        this.onWindowResize(size.x, size.y);

        var monitor = getMonitorSize(primaryMonitor);
        if (monitor != null)
            SDL_SetWindowPosition(window, (monitor.width - size.x) / 2 + monitor.x, (monitor.height - size.y) / 2 + monitor.y);

        pollEvents();

        SDL_ShowWindow(window);
    }

@Override
    protected void onHitBlock(BlockHitResult result) {
        var center = result.getBlockPos();
        var level = this.level();

        ShakeManager.add(level, Shake.builder(this)
                .amplitude(0.075F)
                .duration(5)
                .radius(16)
                .build());

        if (level.isClientSide())
            return;

        var serverLevel = (ServerLevel) level;
        var position = this.position();
        var radius = Math.max(this.getRadius() - this.bounces, 1);

        var ringParticleCount = 250 + random.nextInt(250);

        for (var i = 0; i < ringParticleCount; i++) {
            var angle = 2 * Math.PI * i / ringParticleCount;
            var velocity = new Vec3(Math.cos(angle), 0.15D + random.nextDouble() * 0.1D, Math.sin(angle)).normalize().scale(0.5 + random.nextDouble() * 0.25D);

            var color = this.isFlawless() ? new Color(255, 215, 0) : new Color(50 + random.nextInt(150), 50 + random.nextInt(150), 255);

            NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.75F + random.nextFloat() * 0.25F, 5 + random.nextInt(5), 0.8F), position.toVector3f(), velocity.toVector3f()), this);
        }

        var burstParticleCount = 250 + random.nextInt(100);

        for (var i = 0; i < burstParticleCount; i++) {
            var velocity = new Vec3(random.nextGaussian(), random.nextGaussian(), random.nextGaussian()).normalize().scale(0.1 + random.nextDouble() * 0.25);
            var color = this.isFlawless() ? new Color(255, 235, 100) : new Color(100 + random.nextInt(155), 100 + random.nextInt(155), 255);

            NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(ParticleUtils.constructSimpleSpark(color, 0.25F + random.nextFloat(), 10 + random.nextInt(10), 0.9F), position.toVector3f(), velocity.toVector3f()), this);
        }

        var trailCount = 10;
        var pointCount = 75;
        var maxDistance = 5;

        for (var i = 0; i < trailCount; i++) {
            var direction = new Vec3(random.nextGaussian(), random.nextDouble(), random.nextGaussian()).normalize();

            for (var j = 1; j <= pointCount; j++) {
                var t = j / (double) pointCount;

                var spacedT = Math.pow(t, 1.5);

                var px = position.x + direction.x * spacedT * maxDistance;
                var py = position.y + direction.y * spacedT * maxDistance;
                var pz = position.z + direction.z * spacedT * maxDistance;

                var color = this.isFlawless() ? new Color(255, 200, 50) : new Color(80 + random.nextInt(100), 80 + random.nextInt(100), 255);
                var spark = ParticleUtils.constructSimpleSpark(color, (float) (1F * (1 - t) + 0.1F), 15 + random.nextInt(15), 0.5F);

                NetworkHandler.sendToClientsTrackingEntity(new S2CSpawnParticle(spark, new Vector3f((float) px, (float) py, (float) pz), new Vector3f((float) (direction.x * 0.02F), (float) (direction.y * 0.02F), (float) (direction.z * 0.02F))), this);
            }
        }

        if (this.noPhysics || !level.getBlockState(center).blocksMotion())
            return;

        var poses = new ArrayList<BlockPos>();

        for (var i = -radius; i <= radius; i++) {
            var r1 = (int) Mth.sqrt(radius * radius - i * i);

            for (var j = -r1; j <= r1; j++)
                poses.add(center.offset(i, 0, j));
        }

        for (var step = 0; step <= radius; step++) {
            int finalStep = step;

            ServerScheduler.schedule(finalStep, () -> {
                var height = 0.25F;

                poses.stream().filter(pos -> {
                    var dx = pos.getX() - center.getX();
                    var dz = pos.getZ() - center.getZ();
                    var dist = Math.hypot(dx, dz);

                    return dist >= finalStep && dist < finalStep + 1;
                }).forEach(entryPos -> {
                    var centerY = center.getY();

                    int maxOffset = 8;

                    var groundY = WorldUtils.findSurfaceY(level, entryPos.getX(), entryPos.getZ(), centerY, maxOffset);

                    var minAllowedY = Math.max(level.getMinBuildHeight(), centerY - maxOffset);
                    var maxAllowedY = Math.min(level.getMaxBuildHeight(), centerY + maxOffset);

                    if (groundY < minAllowedY || groundY > maxAllowedY)
                        return;

                    var surfacePos = new BlockPos(entryPos.getX(), groundY, entryPos.getZ());

                    var shockwave = new FallingStarShockwaveBlockEntity(RelicsEntities.SHOCKWAVE_BLOCK.get(), level);

                    shockwave.setPos(surfacePos.getX() + 0.5F, surfacePos.getY(), surfacePos.getZ() + 0.5F);
                    shockwave.setBlockState(level.getBlockState(surfacePos));
                    shockwave.setDeltaMovement(0, height, 0);
                    shockwave.setDamage(this.getDamage());
                    shockwave.setOwner(this.getOwner());
                    shockwave.setStack(this.getStack());
                    shockwave.setStun(this.getStun());
                    shockwave.setCenter(surfacePos);
                    shockwave.setKnockback(0.75F);

                    level.addFreshEntity(shockwave);

                    var px = surfacePos.getX() + 0.15D + random.nextDouble() * 0.7D;
                    var pz = surfacePos.getZ() + 0.15D + random.nextDouble() * 0.7D;

                    var direction = new Vec3(px - (center.getX() + 0.5D), 0D, pz - (center.getZ() + 0.5D));

                    if (direction.lengthSqr() < 0.001D)
                        direction = new Vec3(random.nextDouble() - 0.5D, 0D, random.nextDouble() - 0.5D);

                    direction = direction.normalize();

                    var speed = 0.008D + random.nextDouble() * 0.012D;
                    var lifetime = 10 + random.nextInt(25);
                    var fogPosition = new Vector3f((float) px, surfacePos.getY() + 0.04F, (float) pz);
                    var fogMotion = new Vector3f((float) (direction.x * speed), height / 2F, (float) (direction.z * speed));

                    NetworkHandler.sendToClientsTrackingChunk(new S2CSpawnParticle(new GhostlyFogParticle.Options(lifetime), fogPosition, fogMotion), serverLevel, new ChunkPos(surfacePos));
                });
            });
        }

        level.playSound(null, this.blockPosition(), RelicsSounds.FALLING_STAR_FALL.get(), SoundSource.MASTER, 0.5F, 1F + random.nextFloat() + this.bounces * 0.2F);

        var bounceChance = this.getBounceChance();

        if (bounceChance > 0F) {
            if (this.bounced)
                return;

            if (random.nextFloat() <= bounceChance) {
                var normal = Vec3.atLowerCornerOf(result.getDirection().getNormal()).normalize();

                var motion = this.getDeltaMovement();
                var reflected = motion.subtract(normal.scale(2 * motion.dot(normal))).normalize().scale(0.5F + this.getRadius() * 0.075F);

                this.setDeltaMovement(reflected);

                this.bounced = true;
                this.bounces++;

                var stack = this.getStack();

                if (stack.getItem() instanceof MidnightMantleItem relic && this.getOwner() instanceof LivingEntity owner) {
                    relic.getRelicData(owner, stack).getAbilitiesData().getAbilityData("starfall").getStatisticData().getMetricData("star_bounces").addValue(1);

                    relic.getRelicData(owner, stack).getLevelingData().addExperience("starfall", "star_bounce", 1);
                }
            } else
                this.discard();
        } else
            this.discard();
    }

@Override
    public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
        var stack = player.getItemInHand(hand);

        if (!this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").canPlayerUse(player))
            return InteractionResultHolder.pass(stack);

        var radius = this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatData("distance").getValue();

        var eyePos = player.getEyePosition();
        var lookAngle = player.getLookAngle().normalize();

        var destination = eyePos.add(lookAngle.scale(radius));

        var hit = level.clip(new ClipContext(eyePos, destination, ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, player));

        var impulse = Vec3.ZERO;

        var charge = this.getCharge(player, stack);

        if (charge <= 0)
            return InteractionResultHolder.pass(stack);

        if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("ascent").isEnabled()
                && hit.getType() == HitResult.Type.BLOCK && hit.getLocation().distanceTo(eyePos) <= radius) {
            var current = hit.getBlockPos();

            var maxUp = (int) Math.floor(radius - eyePos.distanceTo(hit.getLocation()));

            BlockPos feetPos = null;

            for (int i = 1; i <= maxUp && current.getY() + i < level.getMaxBuildHeight(); i++) {
                var feet = current.above(i);
                var head = feet.above();

                if (level.isEmptyBlock(feet) && level.isEmptyBlock(head)) {
                    feetPos = feet;

                    break;
                }
            }

            if (feetPos != null)
                destination = feetPos.getBottomCenter();
            else
                destination = hit.getLocation().subtract(lookAngle.scale(0.5));
        } else {
            destination = hit.getLocation();

            if (!level.getBlockState(hit.getBlockPos().below()).blocksMotion())
                destination = destination.add(0, -1, 0);

            var extra = Math.min(player.getKnownMovement().length(), 5);

            impulse = lookAngle.scale(1.25 + extra);
        }

        var random = level.getRandom();

        var shift = player.getBbHeight() / 2F;
        var from = player.position().add(0F, shift, 0F);
        var to = destination.add(0F, shift, 0F);

        level.playSound(player, new BlockPos((int) from.x(), (int) from.y(), (int) from.z()), SoundEvents.ENDERMAN_TELEPORT, SoundSource.MASTER, 1F, 1F);
        level.playSound(player, new BlockPos((int) to.x(), (int) to.y(), (int) to.z()), SoundEvents.ENDERMAN_TELEPORT, SoundSource.MASTER, 1F, 1F);

        if (!level.isClientSide) {
            ServerScheduler.schedule(1, () -> {
                var direction = to.subtract(from);
                var dist = Math.max(0.001, direction.length());

                var forward = direction.scale(1.0 / dist);
                var up = Math.abs(forward.y) < 0.99 ? new Vec3(0, 1, 0) : new Vec3(1, 0, 0);
                var right = forward.cross(up).normalize();
                var binormal = forward.cross(right).normalize();

                var pointCount = (int) Math.round(dist);
                var points = new Vec3[pointCount];

                for (int i = 0; i < pointCount; i++) {
                    var t = i / (float) (pointCount - 1);

                    var base = new Vec3(Mth.lerp(t, from.x, to.x), Mth.lerp(t, from.y, to.y), Mth.lerp(t, from.z, to.z));
                    var wobble = 1F + 0.5F * (float) Math.sin(t * Math.PI);

                    var ox = (random.nextFloat() - 0.5F) * wobble;
                    var oy = (random.nextFloat() - 0.5F) * wobble;

                    points[i] = base.add(right.scale(ox)).add(binormal.scale(oy));
                }

                var segments = 12;

                for (int i = 0; i < pointCount - 1; i++) {
                    var p0 = points[i];
                    var p1 = points[i + 1];

                    for (int s = 0; s <= segments; s++) {
                        var t = s / (float) segments;

                        var px = Mth.lerp(t, p0.x, p1.x);
                        var py = Mth.lerp(t, p0.y, p1.y);
                        var pz = Mth.lerp(t, p0.z, p1.z);

                        if (level instanceof ServerLevel serverLevel)
                            serverLevel.sendParticles(ParticleUtils.constructSimpleSpark(FlawlessUtils.getColor(player, stack, new Color(155 + random.nextInt(100), 80, 255)), 1F, 3, 0.5F), px, py, pz, 1, 0, 0, 0, 0);
                    }
                }
            });

            if (player instanceof ServerPlayer serverPlayer) {
                serverPlayer.teleportTo((ServerLevel) level, destination.x, destination.y, destination.z, player.getYRot(), player.getXRot());

                serverPlayer.fallDistance = 0;

                NetworkHandler.sendToClient(new S2CSetEntityMotion(player.getId(), impulse.toVector3f()), serverPlayer);

                var finalImpulse = impulse;

                ServerScheduler.schedule(1, () -> NetworkHandler.sendToClient(new S2CSetEntityMotion(player.getId(), finalImpulse.toVector3f()), serverPlayer));

                this.addCharge(player, stack, -1);

                this.getRelicData(player, stack).getLevelingData().addExperience("blink", "blink", 1);

                this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("blinks_amount").addValue(1);
                this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("distance_traveled").addValue(from.distanceTo(to));

                if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("safe_fall").isEnabled())
                    this.setSafeFall(stack, true);

                if (this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getRankModifierData("flicker").isEnabled()) {
                    for (var mob : level.getEntitiesOfClass(Mob.class, player.getBoundingBox().inflate(32))) {
                        if (mob.getTarget() == player) {
                            mob.setTarget(null);

                            this.getRelicData(player, stack).getLevelingData().addExperience("blink", "flicker", 1);

                            this.getRelicData(player, stack).getAbilitiesData().getAbilityData("blink").getStatisticData().getMetricData("targets").addValue(1);
                        }
                    }
                }
            }
        } else {
            if (impulse == Vec3.ZERO)
                ShakeManager.add(level, Shake.builder(player)
                        .radius(Integer.MAX_VALUE)
                        .amplitude(0.2F)
                        .duration(5)
                        .build());
            else
                ShakeManager.add(level, Shake.builder(player)
                        .radius(Integer.MAX_VALUE)
                        .amplitude(0)
                        .fovAmplitude(0.35F)
                        .duration(10)
                        .speed(2)
                        .build());

            ChromaticAberrationManager.add(level, ChromaticAberration.builder(player)
                    .radius(Integer.MAX_VALUE)
                    .strength(0.075F)
                    .duration(10)
                    .build());
        }
        return InteractionResultHolder.sidedSuccess(stack, level.isClientSide());
    }

public static boolean deliver(World world, RegistryEntry<Spell> spellEntry, LivingEntity caster, List<DeliveryTarget> targets, ImpactContext context,
                                  @Nullable Vec3d targetLocation, @Nullable Consumer<DeliveryCompletion> completion, boolean forceSuccess, boolean scheduled) {
        var spell = spellEntry.value();

        if (spell.deliver.delay > 0) {
            if (scheduled) {
                Predicate<Entity> validator = (entity) -> !(entity == null || entity.isRemoved());
                if (!validator.test(caster)) {
                    return false;
                }
                targets = targets.stream().filter(target -> validator.test(target.entity())).toList();
            } else {
                List<DeliveryTarget> finalTargets = targets;
                ((WorldScheduler) world).schedule(spell.deliver.delay, () -> deliver(world, spellEntry, caster, finalTargets, context, targetLocation, completion, forceSuccess, true));
                return true;
            }
        }

        var delivered = false;
        switch (spell.deliver.type) {
            case DIRECT -> {
                var anySuccess = false;
                var casterPos = caster.getPos().add(0, caster.getHeight() / 2F, 0);
                if (targets.isEmpty() && targetLocation != null
                        && spell.area_impact != null) { // Special check to allow area impacts only, in the absence of targets
                    var position = targetLocation.lerp(casterPos, 0.001F);
                    var targetSpecificContext = context.position(position);
                    SpellImpacts.performImpacts(world, caster, caster, null, spellEntry, spell.impacts, targetSpecificContext);
                    anySuccess = true; // The area impact will be executed, hence always true
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var position = target == caster
                                ? casterPos
                                : target.getPos().add(0, target.getHeight() / 2F, 0).lerp(casterPos, 0.01F);
                        var targetSpecificContext = targeted.context().position(position);
                        var result = SpellImpacts.performImpacts(world, caster, target, target, spellEntry, spell.impacts, targetSpecificContext);
                        anySuccess = anySuccess || result;
                    }
                }
                delivered = anySuccess;
            }
            case PROJECTILE -> {
                if (targets.isEmpty()) {
                    ProjectileLauncher.shootProjectile(world, caster, null, spellEntry, context);
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var targetSpecificContext = targeted.context();
                        ProjectileLauncher.shootProjectile(world, caster, target, spellEntry, targetSpecificContext);
                    }
                }
                delivered = true;
            }
            case METEOR -> {
                var anyLaunched = false;
                if (targets.isEmpty() && targetLocation != null) {
                    ProjectileLauncher.fallProjectile(world, caster, null, targetLocation, spellEntry, context);
                    anyLaunched = true;
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var targetSpecificContext = targeted.context();
                        ProjectileLauncher.fallProjectile(world, caster, target, null, spellEntry, targetSpecificContext);
                        anyLaunched = true;
                    }
                }
                delivered = anyLaunched;
            }
            case CLOUD -> {
                var placedAny = false;
                if (targets.isEmpty() && targetLocation != null) {
                    CloudPlacer.placeCloud(world, caster, null, targetLocation, spellEntry, context.position(targetLocation));
                    placedAny = true;
                } else {
                    for(var targeted: targets) {
                        var target = targeted.entity();
                        var targetSpecificContext = targeted.context();
                        CloudPlacer.placeCloud(world, caster, target, null, spellEntry, targetSpecificContext);
                        placedAny = true;
                    }
                }
                delivered = placedAny;
            }
            case SHOOT_ARROW -> {
                ArrowHelper.shootArrow(world, caster, spellEntry, context);
                delivered = true;
            }
            case AFFECT_ARROW -> {
                if (caster instanceof SpellCaster.Player shooter) {
                    var arrowContext = shooter.getArrowShootContext();
                    arrowContext.activeSpells.add(spellEntry);
                }
                delivered = true;
            }
            case MELEE -> {
                if (spell.deliver.melee != null
                        && !spell.deliver.melee.attacks.isEmpty()) {
                    var attackers = !targets.isEmpty()
                            ? targets.stream().map(e -> e.entity()).toList()
                            : List.of(caster);
                    var meleeData = spell.deliver.melee;
                    var spellId = spellEntry.getKey().get().getValue();
                    var attacks = meleeData.attacks;
                    if (context.isChanneled()) {
                        var index = context.channelTickIndex() % attacks.size();
                        attacks = List.of(attacks.get(index));
                    }
                    for (var attacker: attackers) {
                        if (!attacker.isOnGround() && !spell.deliver.melee.allow_airborne) {
                            break;
                        }
                        if (attacker instanceof ServerPlayerEntity serverPlayer) {
                            // Map to resolved MeleeAttack structures
                            var meleeAttacks = Melee.createMeleeAttacks(serverPlayer, attacks, spellEntry,
                                    context.charge(), context.chargeModifier());
                            // Send AttackAvailable packet to client
                            var packet = new Packets.AttackAvailable(spellId, meleeAttacks);
                            Platform.util().networkS2C_Send(serverPlayer, packet);
                            delivered = true;
                        }
                    }
                }
            }
            case STASH_EFFECT -> {
                var anyAdded = false;
                var stash = spell.deliver.stash_effect;
                var id = Identifier.of(stash.id);
                var effect = Registries.STATUS_EFFECT.getEntry(id).get();

                var amplifier = stash.amplifier;
                if (stash.amplifier_power_multiplier != 0) {
                    var power = SpellPower.getSpellPower(spell.school, caster);
                    amplifier += (int)(stash.amplifier_power_multiplier * power.nonCriticalValue());
                }
                for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
                    amplifier += modifier.stash_amplifier_add;
                }
                for (var targeted: targets) {
                    if (targeted.entity() instanceof LivingEntity livingEntity) {
                        if (stash.stacking) {
                            var stack = -1;
                            var existingInstance = livingEntity.getStatusEffect(effect);
                            if (existingInstance != null) {
                                stack = existingInstance.getAmplifier();
                                livingEntity.removeStatusEffect(effect);
                            }
                            stack += 1;
                            var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), Math.min(stack, amplifier), false, stash.show_particles, true);
                            livingEntity.addStatusEffect(instance);
                        } else {
                            var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), amplifier, false, stash.show_particles, true);
                            livingEntity.addStatusEffect(instance);
                        }
                        anyAdded = true;
                    }
                }
                delivered = anyAdded;
            }
            case CUSTOM -> {
                if (spell.deliver.custom != null) {
                    var handler = SpellHandlers.customDelivery.get(spell.deliver.custom.handler);
                    if (handler != null) {
                        delivered = handler.onSpellDelivery(world, spellEntry, caster, targets, context, targetLocation);
                    }
                }
            }
        }

        if (completion != null) {
            completion.accept(new DeliveryCompletion(delivered || forceSuccess));
        }

        return delivered;
    }

@Override
    public void onPress() {
        var player = minecraft.player;
        var stack = screen.getStack();
        var random = player.getRandom();

        if (!(stack.getItem() instanceof IRelicItem relic))
            return;

        var abilityData = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData(ability);
        var isEnoughConditions = abilityData.isEnoughLevel() && abilityData.isEnoughRank();
        var isLockUnlocked = abilityData.getLockData().isUnlocked();
        var isAbilityResearched = abilityData.getResearchData().isResearched();

        var soundManager = minecraft.getSoundManager();

        if (isEnoughConditions) {
            if (isLockUnlocked) {
                if (isAbilityResearched) {
                    if (!screen.getSelectedAbility().equals(ability)) {
                        screen.setSelectedAbility(ability);

                        var subcategories = DescriptionSubcategories.getSubcategories().values().stream()
                                .filter(subcategory -> subcategory.shouldAppear(this.screen, player, stack))
                                .toList();

                        if (!subcategories.contains(screen.getSubcategory()))
                            screen.setSubcategory(DescriptionSubcategories.getSubcategory("ability_description"));

                        screen.rebuildWidgets();

                        for (var entry : screen.renderables) {
                            if (!(entry instanceof AbilityCardWidget card) || !card.ability.equals(ability))
                                continue;
                        }
                    }
                } else
                    minecraft.setScreen(new AbilityResearchScreen(minecraft.player, screen.container, screen.slot, screen, ability));
            } else {
                var unlocks = abilityData.getLockData().getUnlocks() + 1;

                NetworkHandler.sendToServer(new C2SPacketAbilityUnlock(screen.container, screen.slot, ability, unlocks));

                var overshootFactor = 0.035F * unlocks;
                var overshoot = 1F + overshootFactor;

                var tween = Tween.create().setParallel(true);

                tween.tweenMethod(this::setClickYSqueeze, this.getClickYSqueeze(), overshoot, 0.08D)
                        .setEaseType(EaseType.EASE_OUT)
                        .setTransitionType(TransitionType.QUAD);
                tween.tweenMethod(this::setClickXSqueeze, this.getClickXSqueeze(), overshoot, 0.08D)
                        .setEaseType(EaseType.EASE_OUT)
                        .setTransitionType(TransitionType.QUAD);

                tween.tweenMethod(this::setClickYSqueeze, overshoot, 1F, 0.12D)
                        .setDelay(0.04D)
                        .setEaseType(EaseType.EASE_IN)
                        .setTransitionType(TransitionType.QUAD);
                tween.tweenMethod(this::setClickXSqueeze, overshoot, 1F, 0.12D)
                        .setDelay(0.04D)
                        .setEaseType(EaseType.EASE_IN)
                        .setTransitionType(TransitionType.QUAD);

                var initialRotation = this.getClickZRotation();
                var rotationBase = 0.025F * unlocks;
                var amplitude = random.nextBoolean() ? rotationBase : -rotationBase;
                var decay = 0.75F;
                var segmentDuration = 0.2D;
                var delay = 0D;
                var lastTarget = initialRotation;

                for (var i = 0; i < 10; i++) {
                    var nextTarget = (i % 2 == 0 ? amplitude : -amplitude);

                    tween.tweenMethod(this::setClickZRotation, lastTarget, nextTarget, segmentDuration)
                            .setDelay(delay)
                            .setEaseType(i == 0 ? EaseType.EASE_OUT : EaseType.EASE_IN_OUT)
                            .setTransitionType(TransitionType.QUAD);

                    lastTarget = nextTarget;
                    delay += segmentDuration;
                    amplitude *= decay;
                }

                tween.tweenMethod(this::setClickZRotation, lastTarget, 0f, segmentDuration)
                        .setDelay(delay)
                        .setEaseType(EaseType.EASE_IN);

                tween.start();

                for (int i = 0; i < unlocks * 75; i++) {
                    var center = new Vec2(width / 2F, height / 2F);
                    var margin = new Vec2(center.x + MathUtils.randomFloat(random) * 7F, center.y + MathUtils.randomFloat(random) * 8.5F);

                    var particle = new PixelUIParticle(5F, random.nextInt(20, 40), getX() + margin.x, getY() + margin.y, UIParticle.Layer.SCREEN, 110);

                    var size = (random.nextFloat() * 0.5F) + 0.75F;

                    particle.setColors(new OctoColor(1F, 0.5F + random.nextFloat() * 0.5F, random.nextFloat() * 0.25F, 1F), new OctoColor(1F, 0F, 0F, 1F));
                    particle.setDirection(MathUtils.randomFloat(random), -random.nextFloat());
                    particle.setRollVelocity(MathUtils.randomFloat(random) * 15);
                    particle.getTransform().setSize(new Vector2f(size, size));
                    particle.setGravity(0.5F + random.nextFloat() * 0.5F);
                    particle.setSpeed(1.5F + random.nextFloat() * 1.5F);
                    particle.setGravityDirection(0, 1);
                    particle.setScreen(this.screen);

                    particle.instantiate();
                }

                soundManager.play(SimpleSoundInstance.forUI(SoundEvents.ZOMBIE_ATTACK_IRON_DOOR, 1F));

                if (unlocks >= abilityData.getLockData().getMaxUnlocks()) {
                    ClientScheduler.schedule(1, this::rebuildActionButtons);

                    for (int i = 0; i < 25; i++) {
                        var center = new Vec2(width / 2F, height / 2F);
                        var margin = new Vec2(center.x + MathUtils.randomFloat(random) * 7F, center.y + MathUtils.randomFloat(random) * 8.5F);

                        var particle = new ExtendedUIParticle(new UIParticle.Texture2D(ResourceLocation.fromNamespaceAndPath(Relics.MODID, "textures/gui/description/relic/particle/chain.png"), 0, 0, 6, 6, 6, 6),
                                5F, random.nextInt(40, 60), getX() + margin.x, getY() + margin.y, UIParticle.Layer.SCREEN, 110);

                        var size = (random.nextFloat() * 0.5F) + 0.75F;

                        particle.setDirection(MathUtils.randomFloat(random) * 0.25F, -random.nextFloat());
                        particle.setRollVelocity(MathUtils.randomFloat(random) * 15);
                        particle.getTransform().setSize(new Vector2f(size, size));
                        particle.setGravityDirection(0, 1);
                        particle.enableBlend(false);
                        particle.setScreen(this.screen);
                        particle.setGravity(1F);
                        particle.setSpeed(3.5F);

                        particle.instantiate();
                    }

                    soundManager.play(SimpleSoundInstance.forUI(SoundEvents.WITHER_BREAK_BLOCK, 1F));
                    soundManager.play(SimpleSoundInstance.forUI(SoundEvents.GENERIC_EXPLODE, 1F));
                }
            }
        } else {
            var overshootFactor = 0.035F;
            var overshoot = 1F + overshootFactor;

            var tween = Tween.create().setParallel(true);

            tween.tweenMethod(this::setClickYSqueeze, this.getClickYSqueeze(), overshoot, 0.08D)
                    .setEaseType(EaseType.EASE_OUT)
                    .setTransitionType(TransitionType.QUAD);
            tween.tweenMethod(this::setClickXSqueeze, this.getClickXSqueeze(), overshoot, 0.08D)
                    .setEaseType(EaseType.EASE_OUT)
                    .setTransitionType(TransitionType.QUAD);

            tween.tweenMethod(this::setClickYSqueeze, overshoot, 1F, 0.12D)
                    .setDelay(0.04D)
                    .setEaseType(EaseType.EASE_IN)
                    .setTransitionType(TransitionType.QUAD);
            tween.tweenMethod(this::setClickXSqueeze, overshoot, 1F, 0.12D)
                    .setDelay(0.04D)
                    .setEaseType(EaseType.EASE_IN)
                    .setTransitionType(TransitionType.QUAD);

            var initialRotation = this.getClickZRotation();
            var rotationBase = 0.025F;
            var amplitude = random.nextBoolean() ? rotationBase : -rotationBase;
            var decay = 0.75F;
            var segmentDuration = 0.25D;
            var delay = 0D;
            var lastTarget = initialRotation;

            for (var i = 0; i < 10; i++) {
                var nextTarget = (i % 2 == 0 ? amplitude : -amplitude);

                tween.tweenMethod(this::setClickZRotation, lastTarget, nextTarget, segmentDuration)
                        .setDelay(delay)
                        .setEaseType(i == 0 ? EaseType.EASE_OUT : EaseType.EASE_IN_OUT)
                        .setTransitionType(TransitionType.QUAD);

                lastTarget = nextTarget;
                delay += segmentDuration;
                amplitude *= decay;
            }

            tween.tweenMethod(this::setClickZRotation, lastTarget, 0f, segmentDuration)
                    .setDelay(delay)
                    .setEaseType(EaseType.EASE_IN);

            tween.start();

            soundManager.play(SimpleSoundInstance.forUI(SoundEvents.CHAIN_BREAK, 1F));
        }
    }

@Test
    @Timeout(value = 30000L, unit = MILLISECONDS)
    public void proxyMirroringWritabilityToAutoReadAcrossEventLoopsDoesNotStallStream() throws Exception {
        // Large enough to force many rounds of the (default 64KiB) HTTP/2 stream flow-control window.
        final int payloadLength = 2 * 1024 * 1024;
        final byte[] payloadBytes = new byte[payloadLength];
        for (int i = 0; i < payloadLength; i++) {
            payloadBytes[i] = (byte) i;
        }

        // Two independent Http2 "connections" (each with its own EventLoop/thread) are proxied together: data
        // received on "in" is forwarded onto "out", and "out"'s writability is mirrored onto "in"'s auto-read
        // state -- exactly the pattern from https://github.com/netty/netty/issues/17600. Because "in" and "out"
        // live on different EventLoops, this ends up calling setAutoRead() across threads.
        EventLoopGroup inGroup = null;
        EventLoopGroup outGroup = null;
        Channel inServerChannel = null;
        Channel inClientChannel = null;
        Channel outServerChannel = null;
        Channel outClientChannel = null;
        Http2StreamChannel inStream = null;
        Http2StreamChannel outStream = null;
        final AtomicReference<ByteBuf> receivedHolder = new AtomicReference<ByteBuf>();
        try {
            inGroup = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());
            outGroup = new MultiThreadIoEventLoopGroup(1, LocalIoHandler.newFactory());

            LocalAddress inAddress = new LocalAddress(getClass().getName() + ".in");
            LocalAddress outAddress = new LocalAddress(getClass().getName() + ".out");

            // "in" server: sends the whole payload as fast as its peer's flow-control window allows.
            ServerBootstrap inSb = new ServerBootstrap();
            inSb.group(inGroup);
            inSb.channel(LocalServerChannel.class);
            inSb.childHandler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new Http2FrameCodecBuilder(true).build());
                    ch.pipeline().addLast(new Http2MultiplexHandler(new ChannelInboundHandlerAdapter() {
                        @Override
                        public void channelRead(ChannelHandlerContext ctx, Object msg) {
                            if (msg instanceof Http2HeadersFrame && ((Http2HeadersFrame) msg).isEndStream()) {
                                ctx.writeAndFlush(new DefaultHttp2HeadersFrame(new DefaultHttp2Headers(), false));
                                ctx.writeAndFlush(new DefaultHttp2DataFrame(
                                        Unpooled.wrappedBuffer(payloadBytes), true));
                            }
                            ReferenceCountUtil.release(msg);
                        }
                    }));
                }
            });
            inServerChannel = inSb.bind(inAddress).sync().channel();

            Bootstrap inBs = new Bootstrap();
            inBs.group(inGroup);
            inBs.channel(LocalChannel.class);
            inBs.handler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new Http2FrameCodecBuilder(false).build());
                    ch.pipeline().addLast(new Http2MultiplexHandler(DISCARD_HANDLER));
                }
            });
            inClientChannel = inBs.connect(inAddress).sync().channel();

            // "out" server: a receiver that (like a slow / congested downstream) doesn't drain anything -- and
            // hence doesn't send WINDOW_UPDATE -- for a little while, so the proxied "out" stream genuinely
            // accumulates a write backlog and becomes unwritable, rather than always draining instantly (as it
            // would with local, same-JVM, always-on auto-read).
            final CountDownLatch outComplete = new CountDownLatch(1);
            final ByteBuf received = Unpooled.buffer(payloadLength);
            receivedHolder.set(received);
            final AtomicReference<Throwable> failure = new AtomicReference<Throwable>();

            ServerBootstrap outSb = new ServerBootstrap();
            outSb.group(outGroup);
            outSb.channel(LocalServerChannel.class);
            outSb.childHandler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new Http2FrameCodecBuilder(true).build());
                    ch.pipeline().addLast(new Http2MultiplexHandler(new ChannelInitializer<Http2StreamChannel>() {
                        @Override
                        protected void initChannel(Http2StreamChannel ch) {
                            ch.config().setAutoRead(false);
                            ch.eventLoop().schedule(new Runnable() {
                                @Override
                                public void run() {
                                    ch.config().setAutoRead(true);
                                }
                            }, 500, MILLISECONDS);
                            ch.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                                @Override
                                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                                    try {
                                        if (msg instanceof Http2DataFrame) {
                                            Http2DataFrame data = (Http2DataFrame) msg;
                                            received.writeBytes(data.content());
                                            if (data.isEndStream()) {
                                                outComplete.countDown();
                                            }
                                        }
                                    } catch (Throwable cause) {
                                        failure.compareAndSet(null, cause);
                                    } finally {
                                        ReferenceCountUtil.release(msg);
                                    }
                                }
                            });
                        }
                    }));
                }
            });
            outServerChannel = outSb.bind(outAddress).sync().channel();

            Bootstrap outBs = new Bootstrap();
            outBs.group(outGroup);
            outBs.channel(LocalChannel.class);
            outBs.handler(new ChannelInitializer<Channel>() {
                @Override
                protected void initChannel(Channel ch) {
                    ch.pipeline().addLast(new Http2FrameCodecBuilder(false).build());
                    ch.pipeline().addLast(new Http2MultiplexHandler(DISCARD_HANDLER));
                }
            });
            outClientChannel = outBs.connect(outAddress).sync().channel();

            // Open "out" first so "in"'s handler can forward straight onto it.
            outStream = new Http2StreamChannelBootstrap(outClientChannel).open().syncUninterruptibly().getNow();
            outStream.writeAndFlush(new DefaultHttp2HeadersFrame(new DefaultHttp2Headers(), false)).sync();

            final Http2StreamChannel finalOutStream = outStream;
            Http2StreamChannelBootstrap inH2Bootstrap = new Http2StreamChannelBootstrap(inClientChannel);
            inH2Bootstrap.handler(new ChannelInboundHandlerAdapter() {
                @Override
                public void channelRead(ChannelHandlerContext ctx, Object msg) {
                    if (msg instanceof Http2DataFrame) {
                        Http2DataFrame data = (Http2DataFrame) msg;
                        finalOutStream.writeAndFlush(
                                new DefaultHttp2DataFrame(data.content().retain(), data.isEndStream()));
                    }
                    ReferenceCountUtil.release(msg);
                }
            });
            inStream = inH2Bootstrap.open().syncUninterruptibly().getNow();

            // Mirror "out"'s writability onto "in"'s auto-read state, exactly like
            // https://github.com/netty/netty/issues/17600. "in" and "out" are registered to different EventLoops,
            // so this ends up calling Http2StreamChannelConfig#setAutoRead() from a thread other than the one
            // "in" is registered to.
            final Http2StreamChannel finalInStream = inStream;
            outStream.pipeline().addLast(new ChannelInboundHandlerAdapter() {
                @Override
                public void channelWritabilityChanged(ChannelHandlerContext ctx) {
                    finalInStream.config().setAutoRead(finalOutStream.isWritable());
                }
            });

            inStream.writeAndFlush(new DefaultHttp2HeadersFrame(new DefaultHttp2Headers(), true)).sync();

            assertTrue(outComplete.await(20, SECONDS), "proxying stalled: never received the full payload");
            Throwable cause = failure.get();
            if (cause != null) {
                throw new AssertionError(cause);
            }
            assertEquals(payloadLength, received.readableBytes());
            byte[] actual = new byte[payloadLength];
            received.readBytes(actual);
            assertArrayEquals(payloadBytes, actual);
        } finally {
            ByteBuf received = receivedHolder.get();
            if (received != null) {
                received.release();
            }
            if (inStream != null) {
                inStream.close().syncUninterruptibly();
            }
            if (outStream != null) {
                outStream.close().syncUninterruptibly();
            }
            if (inClientChannel != null) {
                inClientChannel.close().syncUninterruptibly();
            }
            if (outClientChannel != null) {
                outClientChannel.close().syncUninterruptibly();
            }
            if (inServerChannel != null) {
                inServerChannel.close().syncUninterruptibly();
            }
            if (outServerChannel != null) {
                outServerChannel.close().syncUninterruptibly();
            }
            if (inGroup != null) {
                inGroup.shutdownGracefully(0, 0, MILLISECONDS);
            }
            if (outGroup != null) {
                outGroup.shutdownGracefully(0, 0, MILLISECONDS);
            }
        }
    }

private void handleDismount(Entity passenger)
	{
		final var passengerPosition = getPassengerRidingPosition(passenger);
		passenger.teleportTo(passengerPosition.x, passengerPosition.y, passengerPosition.z);
		passenger.setDeltaMovement(getDeltaMovement());
		if(getDeltaMovement().y < 0)
		{
			passenger.fallDistance = SkylineHelper.fallDistanceFromSpeed(getDeltaMovement().y);
			passenger.setOnGround(false);
		}
		passenger.getData(IEDataAttachments.SKYHOOK_USER.get()).release();
		if(hand!=null&&passenger instanceof Player)
		{
			ItemStack held = ((Player)passenger).getItemInHand(hand);
			if(held.getItem()==Misc.SKYHOOK.asItem())
				((Player)passenger).getCooldowns().addCooldown(Misc.SKYHOOK.asItem(), 10);
		}
	}

@Override
	protected void removePassenger(Entity passenger)
	{
		super.removePassenger(passenger);
		if(!level().isClientSide)
			ApiUtils.addFutureServerTask(level(), () -> handleDismount(passenger));
		else
			//TODO is this still needed?
			ApiUtils.addFutureServerTask(level(), () -> handleDismount(passenger), true);
	}

