        double x = centerX;
        double z = centerZ;

        switch (currentCorner) {
            case 0 -> {
                x += 9;
                z += 9;
            }
            case 1 -> {
                x -= 9;
                z += 9;
            }
            case 2 -> {
                x -= 9;
                z -= 9;
            }
            case 3 -> {
                x += 9;
                z -= 9;
            }
