    public void aiStep() {
        super.aiStep();
        if (this.getAnimation() == ANIMATION_SPAWN && this.getAnimationTick() < 30) {
            BlockState belowBlock = level.getBlockState(this.blockPosition().below());
            if (belowBlock.getBlock() != Blocks.AIR) {
                for (int i = 0; i < 5; i++) {
                    this.level.addParticle(new BlockParticleOption(ParticleTypes.BLOCK, belowBlock), this.getX() + this.random.nextFloat() * this.getBbWidth() * 2.0F - this.getBbWidth(), this.getBoundingBox().minY, this.getZ() + this.random.nextFloat() * this.getBbWidth() * 2.0F - this.getBbWidth(), this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D, this.random.nextGaussian() * 0.02D);
                }
            }
            this.setDeltaMovement(0, this.getDeltaMovement().y, this.getDeltaMovement().z);

        }
        if (this.level.isClientSide && this.getAnimation() == ANIMATION_SUMMON) {
            double d0 = 0;
            double d1 = 0;
            double d2 = 0;
            float f = this.yBodyRot * 0.017453292F + Mth.cos(this.tickCount * 0.6662F) * 0.25F;
            float f1 = Mth.cos(f);
            float f2 = Mth.sin(f);
            IceAndFire.PROXY.spawnParticle(EnumParticles.Dread_Torch, this.getX() + (double) f1 * 0.6D, this.getY() + 1.8D, this.getZ() + (double) f2 * 0.6D, d0, d1, d2);
            IceAndFire.PROXY.spawnParticle(EnumParticles.Dread_Torch, this.getX() - (double) f1 * 0.6D, this.getY() + 1.8D, this.getZ() - (double) f2 * 0.6D, d0, d1, d2);
        }
        if (fireCooldown > 0) {
            fireCooldown--;
        }
        if (minionCooldown > 0) {
            minionCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void update(LivingEntityPatch<?> entitypatch) {
		if (this.paused) {
			this.animationPlayer.setElapsedTime(this.animationPlayer.getElapsedTime());
		} else {
			this.animationPlayer.tick(entitypatch);
		}

		if (!this.animationPlayer.isEnd()) {
			this.animationPlayer.getAnimation().get().tick(entitypatch);
		} else if (!this.paused) {
			if (this.nextAnimation != null) {
				if (!this.animationPlayer.getAnimation().get().isLinkAnimation() && !this.nextAnimation.get().isLinkAnimation()) {
					this.nextAnimation.get().begin(entitypatch);
				}

				this.nextAnimation.get().putOnPlayer(this.animationPlayer, entitypatch);
				this.nextAnimation = null;
			} else {
				if (this.animationPlayer.getAnimation() instanceof LayerOffAnimation) {
					this.animationPlayer.getAnimation().get().end(entitypatch, Animations.EMPTY_ANIMATION, true);
				} else {
					this.off(entitypatch);
				}
			}
		}

		if (this.isBaseLayer()) {
			entitypatch.updateEntityState();
			entitypatch.updateMotion(true);
		}
	}

@Override
	protected void renderLayer(WitherPatch entitypatch, WitherBoss entityliving, WitherArmorLayer vanillaLayer, PoseStack poseStack, MultiBufferSource buffers, int packedLight, OpenMatrix4f[] poses, float bob, float yRot, float xRot, float partialTick) {
		if (entitypatch.isArmorActivated()) {
			float progress = (float)entityliving.tickCount + partialTick;
			poseStack.pushPose();
			poseStack.translate(0.0D, -0.1D, 0.0D);
			poseStack.scale(1.05F, 1.05F, 1.05F);
			int transparencyCount = entitypatch.getTransparency();
			float transparency = 1.0F;

			if (transparencyCount == 0) {
				transparency = entitypatch.isGhost() ? 0.0F : 1.0F;
				AnimationPlayer animationPlayer = entitypatch.getAnimator().getPlayerFor(null);

				if (animationPlayer.getAnimation().get() == Animations.WITHER_SPELL_ARMOR) {
					transparency = (animationPlayer.getPrevElapsedTime() + (animationPlayer.getElapsedTime() - animationPlayer.getPrevElapsedTime()) * partialTick) / (Animations.WITHER_SPELL_ARMOR.get().getTotalTime() - 0.5F);
				}
			} else {
				if (transparencyCount < 0) {
					transparency = 1.0F - (Math.abs(transparencyCount) + partialTick) / 41.0F;
				} else if (transparencyCount > 0) {
					transparency = (Math.abs(transparencyCount) + partialTick) / 41.0F;
				}
			}

			RenderType renderType = EpicFightRenderTypes.makeTriangulated(RenderType.energySwirl(WITHER_ARMOR_LOCATION, Mth.cos(progress * 0.02F) * 3.0F % 1.0F, progress * 0.01F % 1.0F));
			this.mesh.get().drawPosed(poseStack, buffers.getBuffer(renderType), Mesh.DrawingFunction.NEW_ENTITY, packedLight, 0.5F * transparency, 0.5F * transparency, 0.5F * transparency, 1.0F, OverlayTexture.NO_OVERLAY, entitypatch.getArmature(), poses);

			poseStack.popPose();
		}
	}

@Override
    protected void updateBeforeRender() {
        super.updateBeforeRender();

        // Update the dialog title with an ETA if possible
        Component title = this.getGuiDisplayName(GuiText.CraftingStatus.text());
        if (status != null) {
            final long elapsedTime = status.getElapsedTime();
            final double remainingItems = status.getRemainingItemCount();
            final double startItems = status.getStartItemCount();
            final long eta = (long) (elapsedTime / Math.max(1d, startItems - remainingItems)
                    * remainingItems);

            if (eta > 0 && !getVisualEntries().isEmpty()) {
                final long etaInMilliseconds = TimeUnit.MILLISECONDS.convert(eta, TimeUnit.NANOSECONDS);
                final String etaTimeText = DurationFormatUtils.formatDuration(etaInMilliseconds,
                        GuiText.ETAFormat.getLocal());
                title = title.copy().append(" - " + etaTimeText);
            }
        }
        // Mention that items can't be stored if applicable
        if (menu.isCantStoreItems()) {
            title = title.copy().append(" - ").append(GuiText.CantStoreItems.text().withStyle(ChatFormatting.RED));
        }
        setTextContent(TEXT_ID_DIALOG_TITLE, title);

        final int size = this.status != null ? this.status.getEntries().size() : 0;
        scrollbar.setRange(0, this.table.getScrollableRows(size), 1);

        this.schedulingModeButton.set(this.menu.getSchedulingMode());
    }

