public PlayState paraPredicate(AnimationEvent<Parasaurolophus> event) {
            if (isBlocked()) return PlayState.STOP;
            AnimationController<Parasaurolophus> controller = event.getController();
            if (tryNextAnimation(controller)) {
                return PlayState.CONTINUE;
            }
            Optional<ActiveAnimationInfo> activeAnimation = getActiveAnimation(controller.getName());
            if (activeAnimation.isPresent() && tryForcedAnimation(event, activeAnimation.get())) {
                return PlayState.CONTINUE;
            }
            if (event.getAnimatable().isStanding()) {
                controller.setAnimation(new AnimationBuilder().playOnce(STAND_UP).loop(STAND));
                return PlayState.CONTINUE;
            }
            double animationSpeed = 1;
            if (entity.isSleeping()) {
                addActiveAnimation(controller.getName(), AnimationCategory.SLEEP);
            } else if (event.getAnimatable().sitSystem.isSitting()) {
                addActiveAnimation(controller.getName(), AnimationCategory.SIT);
            } else if (entity.isInWater()) {
                addActiveAnimation(controller.getName(), AnimationCategory.SWIM, true);
            } else if (event.isMoving()) {
                animationSpeed = addMovementAnimation(event, true);
            } else {
                addActiveAnimation(controller.getName(), AnimationCategory.IDLE);
            }
            setAnimationSpeed(controller, animationSpeed, event.getAnimationTick());
            Optional<ActiveAnimationInfo> newAnimation = getActiveAnimation(controller.getName());
            if (newAnimation.isPresent()) {
                controller.transitionLengthTicks = newAnimation.get().transitionLength();
                controller.setAnimation(new AnimationBuilder().addAnimation(newAnimation.get().animationName(), newAnimation.get().loop() ? LOOP : PLAY_ONCE));
            }
            return PlayState.CONTINUE;
        }

@Override
	protected void doMeleeEffect(ItemStack stack, LivingEntity target, LivingEntity attacker, float attackCooldown) {
		if (!attacker.level().isClientSide && attackCooldown > 0.75) {
			ItemStack offhandStack = attacker.getOffhandItem();

			if (offhandStack.is(AoATags.Items.ADVENT_RUNE) && offhandStack.getCount() >= 5) {
				Item rune = offhandStack.getItem();

				if (rune == AoAItems.POISON_RUNE.get()) {
					EntityUtil.applyPotions(target, attacker, new EffectBuilder(MobEffects.POISON, 72).level(2));
				}
				else if (rune == AoAItems.WITHER_RUNE.get()) {
					EntityUtil.applyPotions(target, attacker, new EffectBuilder(MobEffects.WITHER, 40).level(3));
				}
				else if (rune == AoAItems.WIND_RUNE.get()) {
					DamageUtil.doScaledKnockback(target, attacker, 0.5f, 1, 1, 1);
				}
				else if (rune == AoAItems.WATER_RUNE.get()) {
					EntityUtil.applyPotions(target, attacker, new EffectBuilder(MobEffects.MOVEMENT_SLOWDOWN, 60));
				}
				else if (rune == AoAItems.CHARGED_RUNE.get()) {
					((ServerLevel)target.level()).sendParticles(ParticleTypes.ANGRY_VILLAGER, target.getX() + (RandomUtil.valueUpTo(1) * target.getBbWidth() * 2f) - target.getBbWidth(), target.getY() + 1 + (RandomUtil.valueUpTo(1) * target.getBbHeight()), target.getZ() + (RandomUtil.valueUpTo(1) * target.getBbWidth() * 2f) - target.getBbWidth(), 3, 0, 0, 0, (double)0);
				}
				else if (rune != AoAItems.FIRE_RUNE.get()) {
					return;
				}

				if (attacker instanceof Player pl && !pl.getAbilities().instabuild) {
					offhandStack.shrink(5);
					ItemUtil.damageItemForUser(pl, stack, EquipmentSlot.MAINHAND);
				}
			}
		}
	}

