        super.tick();
        this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        prevLandProgress = landProgress;
        prevFishPitch = fishPitch;
        prevPulseAmount = pulseAmount;
        float targetFishPitch = Mth.clamp((float) this.getDeltaMovement().y * 2F, -1.4F, 1.4F) * -(float) (180F / (float) Math.PI);
        if(!isAlive()){
            targetFishPitch = 0.0F;
        }
        fishPitch = Mth.approachDegrees(fishPitch, targetFishPitch, 2.5F);
        boolean grounded = this.onGround() && !isInWaterOrBubble();
        if (grounded && landProgress < 5F) {
            landProgress++;
        }
        if (!grounded && landProgress > 0F) {
            landProgress--;
        }
        float pulseBy = getInterestLevel() * 0.45F;
        pulseAmount += pulseBy;
        if (!level().isClientSide) {
            double waterHeight = getFluidTypeHeight(ForgeMod.WATER_TYPE.get());
            if (waterHeight > 0 && waterHeight < this.getBbHeight() - 1.0F) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.05, 0));
            }
        }
        if (this.getAnimation() == HullbreakerEntity.ANIMATION_BASH && this.getAnimationTick() > 10 && this.getAnimationTick() <= 20) {
            breakBlock();
        }
        if (blockBreakCooldown > 0) {
            blockBreakCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Inject(method = "handleInputEvents", at = @At(value = "HEAD"))
    private void handleInputEvents_HEAD_SpellHotbar(CallbackInfo ci) {
        // spellHotbarHandle = null;
        if (player == null || options == null) { return; }

        // Update the content of the Spell Hotbar
        // This needs to run every tick because the player's held caster item may change any time
        var hotbarUpdated = SpellHotbar.INSTANCE.update(player, options);
        if (hotbarUpdated) {
            itemUseCooldown = 4;
        }
        SpellHotbar.INSTANCE.prepare(itemUseCooldown);
        if (player.isUsingItem()) {
            return;
        }
        var caster = (SpellCaster.Client) player;
        if (caster.getCurrentSkillAttack() != null) {
            itemUseCooldown = Math.max(itemUseCooldown, 1); // Blocking item use
            attackCooldown = 1; // Blocking attacks
            // Prevent spell cast start until the attack is finished
            // but allow ongoing process to continue
            if (caster.getSpellCastProcess() == null) {
                return;
            }
        }

        concurrentKeys.removeIf(k -> !k.isPressed());
        SpellHotbar.Handle handled;
        if (useKeySpellCastingLock || SpellEngineClient.config.useKeyHighPriority) {
            handled = SpellHotbar.INSTANCE.handleAll(player, options, concurrentKeys);
        } else {
            handled = SpellHotbar.INSTANCE.handleOther(player, options, concurrentKeys);
        }
        onSpellHotbarInputHandled(handled);
    }

public void tick() {
            LivingEntity target = this.mob.getTarget();
            if (target != null) {
                if (this.mob.mode == AttackMode.CIRCLE) {
                    circlingTime++;
                    circleEntity(target, circleDistance, 1.0f, clockwise, circlingTime, 0, 1);
                    if (circlingTime >= maxcirclingTime) {
                        this.mob.mode = AttackMode.MELEE;
                    }
                    if (target.distanceTo(this.mob) < 5) {
                        this.mob.mode = AttackMode.MELEE;
                    }
                } else if (this.mob.mode == AttackMode.MELEE) {
                    MeleeModeTime++;
                    this.mob.getNavigation().moveTo(target, 1.0D);
                    this.mob.getLookControl().setLookAt(target, 30, 30);
                    if(MeleeModeTime >= MELEE_MODE_TIME) {
                        start();
                    }else if (this.mob.distanceToSqr(target) <= 4D && this.mob.getAnimation() == NO_ANIMATION) {
                        this.mob.setAnimation(MODERN_REMNANT_BITE);
                    }
                }

                if (this.mob.getAnimation() == MODERN_REMNANT_BITE) {
                    if (this.mob.getAnimationTick() == 5) {
