                        caniac.setAnimation(CaniacEntity.ANIMATION_LUNGE);
                    }
                }else {
                    caniac.setRunning(false);
                }
            }
        }
    }

@Override
    public Vec3 getHeadPosition() {
        //this.setDragonPitch(this.ticksExisted % 180 - 90);
        float sitProg = this.sitProgress * 0.005F;
        float deadProg = this.modelDeadProgress * -0.02F;
        float hoverProg = this.hoverProgress * 0.03F;
        float flyProg = Math.max(0, this.flyProgress * 0.01F);
        int tick = 0;
        if (this.getAnimationTick() < 10) {
            tick = this.getAnimationTick();
        } else if (this.getAnimationTick() > 50) {
            tick = 60 - this.getAnimationTick();
        } else {
            tick = 10;
        }
        float epicRoarProg = this.getAnimation() == ANIMATION_EPIC_ROAR && !this.isOrderedToSit() ? tick * 0.1F : 0;
        float sleepProg = this.sleepProgress * 0.025F;
        float pitchY = 0;
        float pitchAdjustment = 0;
        float pitchMinus = 0;
        float dragonPitch = -getDragonPitch();// -90 = down, 0 = straight, 90 = up
        if (this.isFlying() || this.isHovering()) {
            if (dragonPitch > 0) {
                pitchY = (dragonPitch / 90F) * 1.2F;
            } else {
                pitchY = (dragonPitch / 90F) * 3F;
            }
        }
        float flightXz = 1.0F + flyProg + hoverProg;
        float absPitch = Math.abs(dragonPitch) / 90F;//1 down/up, 0 straight
        float minXZ = dragonPitch > 20 ? (dragonPitch - 20) * 0.009F : 0;
        float xzMod = (0.58F - hoverProg * 0.45F + flyProg * 0.2F + absPitch * 0.3F - sitProg) * flightXz * getRenderSize();
        float xzModSine = xzMod * (Math.max(0.25F, Mth.cos((float) Math.toRadians(dragonPitch))) - minXZ);
        float headPosX = (float) (getX() + (xzModSine) * Mth.cos((float) ((yBodyRot + 90) * Math.PI / 180)));
        float headPosY = (float) (getY() + (0.7F + (sitProg * 5F) + hoverProg + deadProg + epicRoarProg + sleepProg + flyProg + pitchY) * getRenderSize() * 0.3F);
        float headPosZ = (float) (getZ() + (xzModSine) * Mth.sin((float) ((yBodyRot + 90) * Math.PI / 180)));
        return new Vec3(headPosX, headPosY, headPosZ);
    }

@Override
    public void tick() {
        if (attackTime > 0) {
            attackTime--;
        } else {
            LivingEntity target = entity.getTarget();
            if (target != null) {
                double d0 = this.entity.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());
                boolean canSee = this.entity.getSensing().hasLineOfSight(target);
                boolean couldSee = this.seeTime > 0;

                if (canSee != couldSee) {
                    this.seeTime = 0;
                }

                if (canSee) {
                    ++this.seeTime;
                    this.entity.lookAt(target, 19.0F, 10.0F);


                    this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition(1.0F));
                } else {
                    --this.seeTime;
                }

                if (d0 <= (double) this.maxAttackDistance && this.seeTime >= 20) {
                    attack(target);
                    this.attackTime = attackCooldown;
                    entity.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 20));


                } else {
                    this.entity.getNavigation().moveTo(target, 1.0);

                }
            }
        }
    }

public void render(PoseStack matrixStackIn, MultiBufferSource bufferIn, int packedLightIn, Deepling_Priest_Entity entity, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        matrixStackIn.pushPose();
        if (entity.getAnimation() == Deepling_Priest_Entity.DEEPLING_BLIND && entity.getAnimationTick() >18 && entity.getAnimationTick() <47) {
            float f5 = ((float)entity.getAnimationTick() + partialTicks) / 144;
            float f7 = Math.min(f5 > 0.8F ? (f5 - 0.8F) / 0.2F : 0.0F, 1.0F);
            RandomSource randomsource = RandomSource.create(432L);
            VertexConsumer vertexconsumer2 = bufferIn.getBuffer(RenderType.lightning());
            matrixStackIn.pushPose();
            translateToLight(matrixStackIn);

            for(int i = 0; (float)i < 4; ++i) {
                matrixStackIn.mulPose(Axis.XP.rotationDegrees(randomsource.nextFloat() * 360.0F));
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(randomsource.nextFloat() * 360.0F));
                matrixStackIn.mulPose(Axis.ZP.rotationDegrees(randomsource.nextFloat() * 360.0F));
                matrixStackIn.mulPose(Axis.XP.rotationDegrees(randomsource.nextFloat() * 360.0F));
                matrixStackIn.mulPose(Axis.YP.rotationDegrees(randomsource.nextFloat() * 360.0F));
                matrixStackIn.mulPose(Axis.ZP.rotationDegrees(randomsource.nextFloat() * 360.0F + f5 * 90.0F));
                float f3 = 2.75F;
                float f4 = 2.75F;
                Matrix4f matrix4f = matrixStackIn.last().pose();
                int j = (int)(255.0F * (1.0F - f7));
                vertex01(vertexconsumer2, matrix4f, j);
                vertex2(vertexconsumer2, matrix4f, f3, f4);
                vertex3(vertexconsumer2, matrix4f, f3, f4);
                vertex01(vertexconsumer2, matrix4f, j);
                vertex3(vertexconsumer2, matrix4f, f3, f4);
                vertex4(vertexconsumer2, matrix4f, f3, f4);
                vertex01(vertexconsumer2, matrix4f, j);
                vertex4(vertexconsumer2, matrix4f, f3, f4);
                vertex2(vertexconsumer2, matrix4f, f3, f4);
            }

            matrixStackIn.popPose();
        }

        matrixStackIn.popPose();

    }

public void tick() {
            LivingEntity target = entity.getTarget();
            if (target != null) {
                entity.getLookControl().setLookAt(target, 30, 90);
                if (this.entity.getAnimationTick() > 53 && this.entity.getAnimationTick() < 134) {
                    final double d0 = target.getX() - entity.getX();
                    final double d1 = target.getEyeY() - entity.getEyeY();
                    final double d2 = target.getZ() - entity.getZ();
                    final double d3 = Mth.sqrt((float) (d0 * d0 + d2 * d2));
                    final float targetYaw = (float) (Mth.atan2(d2, d0) * 180.0F / (float) Math.PI - 90.0F);
                    final float targetPitch = (float) (-(Mth.atan2(d1, d3) * 180.0F / (float) Math.PI));
                    entity.setXRot((entity.getXRot() + Mth.clamp(targetPitch - entity.getXRot(), -2, 2)));
                    if (d0 * d0 + d2 * d2 >= 9) {
                        entity.setYRot((entity.getYRot() + Mth.clamp(targetYaw - entity.getYRot(), -2, 2)));
                        entity.yBodyRot = entity.getYRot();
                    }
                    if (Math.abs(Mth.wrapDegrees(targetYaw) - Mth.wrapDegrees(entity.getYRot())) < 4) {
                        final double distSq = d0 * d0 + d2 * d2;
                        if (distSq < 9) {
                            entity.setYRot(entity.yRotO);
                            entity.yBodyRot = entity.yRotO;
                            entity.setDeltaMovement(entity.getDeltaMovement().multiply(0.8, 1, 0.8));
                        } else {
                            if (entity.isInWater() && target.isInWater()) {
                                final Vec3 vector3d = entity.getDeltaMovement();
                                Vec3 vector3d1 = new Vec3(target.getX() - entity.getX(), target.getY() - entity.getY(), target.getZ() - entity.getZ());
                                if (vector3d1.lengthSqr() > 1.0E-7D) {
                                    vector3d1 = vector3d1.normalize().scale(0.5D).add(vector3d.scale(0.5D));
                                }
                                entity.setDeltaMovement(vector3d1.x, vector3d1.y, vector3d1.z);
                            }
                            entity.getMoveControl().setWantedPosition(target.getX(), target.getY(), target.getZ(), 1.0D);
                            entity.getNavigation().moveTo(target, 1.0F);
                        }
                    }
                }
            }
        }

public PlayState waterPredicate(AnimationEvent<PrehistoricSwimming> event) {
        if (isBlocked()) return PlayState.STOP;
        AnimationController<PrehistoricSwimming> controller = event.getController();
        if (tryNextAnimation(controller)) {
            return PlayState.CONTINUE;
        }
        Optional<ActiveAnimationInfo> activeAnimation = getActiveAnimation(controller.getName());
        if (activeAnimation.isPresent() && tryForcedAnimation(event, activeAnimation.get())) {
            return PlayState.CONTINUE;
        }
        double animationSpeed = 1;
        if (event.getAnimatable().isBeached()) {
            addActiveAnimation(controller.getName(), AnimationCategory.BEACHED);
        } else if (entity.isSleeping()) {
            addActiveAnimation(controller.getName(), AnimationCategory.SLEEP);
        } else if (event.isMoving()) {
            //TODO: AnimSpeed for amphibians on land
            if (entity.isInWater()) {
                if (entity.isSprinting()) {
                    addActiveAnimation(controller.getName(), AnimationCategory.SWIM_FAST);
                } else {
                    addActiveAnimation(controller.getName(), AnimationCategory.SWIM);
                }
            } else {
                animationSpeed = addMovementAnimation(event, true);
            }
        } else if (event.getAnimatable().isWeak()) {
            addActiveAnimation(controller.getName(), AnimationCategory.KNOCKOUT);
        } else {
            addActiveAnimation(controller.getName(), AnimationCategory.IDLE);
        }
        prevAnimationSpeeds.put(controller.getName(), (float) animationSpeed);
        setAnimationSpeed(controller, animationSpeed, event.getAnimationTick());
        Optional<ActiveAnimationInfo> newAnimation = getActiveAnimation(controller.getName());
        if (newAnimation.isPresent()) {
            controller.setAnimation(new AnimationBuilder().addAnimation(newAnimation.get().animationName, newAnimation.get().loop ? LOOP : PLAY_ONCE));
        }
        return PlayState.CONTINUE;
    }

public void tick() {
            LivingEntity target = Ignis_Entity.this.getTarget();
            if (Ignis_Entity.this.getAnimationTick() < look1 && target != null
                    || Ignis_Entity.this.getAnimationTick() < 59 && Ignis_Entity.this.getAnimationTick() > 43 && target != null
                    || Ignis_Entity.this.getAnimationTick() < 74 && Ignis_Entity.this.getAnimationTick() > 61 && target != null) {
                Ignis_Entity.this.getLookControl().setLookAt(target, 30.0F, 30.0F);
                setYRot(yBodyRot);
            } else {
                Ignis_Entity.this.setYRot(Ignis_Entity.this.yRotO);
            }
            if (entity.getAnimationTick() < charge && target != null) {
                double x = target.getX();
                double z = target.getZ();
                double vx = (x - prevX) / charge;
                double vz = (z - prevZ) / charge;
                Vec3 vec3 = new Vec3(Mth.floor(x + vx * sensing),0,Mth.floor(z + vz * sensing));

                entity.setTargetPosition(vec3);
            }

            if (entity.getAnimationTick() == charge) {
                if(entity.getTargetPosition() != null) {
                    entity.setDeltaMovement((entity.getTargetPosition().x - entity.getX()) * motionx, 0, (entity.getTargetPosition().z - entity.getZ()) * motionz);
                }
                entity.setTargetPosition(null);
            }

            float f1 = (float) Math.cos(Math.toRadians(Ignis_Entity.this.getYRot() + 90));
            float f2 = (float) Math.sin(Math.toRadians(Ignis_Entity.this.getYRot() + 90));
            if (Ignis_Entity.this.getAnimationTick() == 55 || Ignis_Entity.this.getAnimationTick() == 70) {
                if (target != null) {
                    if (Ignis_Entity.this.distanceTo(target) > 3.5F) {
                        Ignis_Entity.this.push(f1 * 1.5, 0, f2 * 1.5);
                    }
                } else {
                    Ignis_Entity.this.push(f1 * 1.5, 0, f2 * 1.5);
                }
            }
        }

public boolean hurt(DamageSource source, float damage) {
        Entity entity = source.getDirectEntity();
        if (entity instanceof Abyss_Blast_Entity || entity instanceof Portal_Abyss_Blast_Entity) {
            return false;
        }
        if (this.destroyBlocksTick <= 0) {
            this.destroyBlocksTick = 20;
        }
        double range = calculateRange(source);


        boolean flag1 = this.canInFluidType(this.getEyeInFluidType());
        if (!flag1) {
            if(!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY) &&  CMCommonConfig.Leviathan.ImmuneOutofWater) {
                if (entity instanceof Player player) {
                    player.displayClientMessage(Component.translatable("entity.cataclysm.the_leviathan_immune"), true);
                }
                return false;
            }
        }

        if ((this.getAnimation() == LEVIATHAN_PHASE2) && !source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
            return false;
        }


        boolean attack = super.hurt(source, damage);

        if(this.getAnimation() == LEVIATHAN_RUSH) {
            if (this.getAnimationTick() >= 38 && this.getAnimationTick() <= 54) {
                if(attack){
                    AnimationHandler.INSTANCE.sendAnimationMessage(this, LEVIATHAN_STUN);
                }
            }
        }


        return attack;
    }

@Override
	public void tick() {
		double targetDistance = this.taskOwner.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
		boolean canSeeTarget = this.taskOwner.getSensing().hasLineOfSight(this.target);

		if (canSeeTarget) {
			++this.seeTime;
		}
		else {
			this.seeTime = 0;
		}

		if (!(targetDistance > (double)this.attackRadius * this.attackRadius) && this.seeTime >= 5) {
			this.taskOwner.getNavigation().stop();
		}
		else {
			this.taskOwner.getNavigation().moveTo(this.target, this.speedModifier);
		}

		this.taskOwner.getLookControl().setLookAt(this.target, 30f, 30f);

		if (--this.attackTime <= 0 && this.attackTime >= -preAttackTime) {
			if (!canSeeTarget)
				return;

			if (this.attackTime == 0)
				this.taskOwner.swing(InteractionHand.MAIN_HAND);

			if (this.attackTime == -preAttackTime) {
				float distMod = (float)Math.sqrt(targetDistance) / this.attackRadius;
				float distFactor = Mth.clamp(distMod, 0.1f, 1);

				this.taskOwner.performRangedAttack(this.target, distFactor);
				this.attackTime = Mth.floor(distMod * (float)(this.attackCooldownMax - this.attackCooldownMin) + (float)this.attackCooldownMin);
			}
		}
		else if (this.attackTime < 0) {
			this.attackTime = Mth.floor(Mth.lerp(Math.sqrt(targetDistance) / (double)this.attackRadius, this.attackCooldownMin, this.attackCooldownMax));
		}
	}

@SubscribeEvent
    public void onProjectileHit(ProjectileImpactEvent event) {
        if (event.getRayTraceResult() instanceof EntityHitResult hitResult
            && hitResult.getEntity() instanceof EntityEmu emu && !event.getEntity().level().isClientSide) {
            if (event.getEntity() instanceof AbstractArrow arrow) {
                //fixes soft crash with vanilla
                arrow.setPierceLevel((byte) 0);
            }
            if ((emu.getAnimation() == EntityEmu.ANIMATION_DODGE_RIGHT || emu.getAnimation() == EntityEmu.ANIMATION_DODGE_LEFT) && emu.getAnimationTick() < 7) {
                event.setCanceled(true);
            }
            if (emu.getAnimation() != EntityEmu.ANIMATION_DODGE_RIGHT && emu.getAnimation() != EntityEmu.ANIMATION_DODGE_LEFT) {
                boolean left = true;
                Vec3 arrowPos = event.getEntity().position();
                Vec3 rightVector = emu.getLookAngle().yRot(0.5F * Mth.PI).add(emu.position());
                Vec3 leftVector = emu.getLookAngle().yRot(-0.5F * Mth.PI).add(emu.position());
                if (arrowPos.distanceTo(rightVector) < arrowPos.distanceTo(leftVector)) {
                    left = false;
                } else if (arrowPos.distanceTo(rightVector) > arrowPos.distanceTo(leftVector)) {
                    left = true;
                } else {
                    left = emu.getRandom().nextBoolean();
                }
                Vec3 vector3d2 = event.getEntity().getDeltaMovement().yRot((float) ((left ? -0.5F : 0.5F) * Math.PI)).normalize();
                emu.setAnimation(left ? EntityEmu.ANIMATION_DODGE_LEFT : EntityEmu.ANIMATION_DODGE_RIGHT);
                emu.hasImpulse = true;
                if (!emu.horizontalCollision) {
                    emu.move(MoverType.SELF, new Vec3(vector3d2.x() * 0.25F, 0.1F, vector3d2.z() * 0.25F));
                }
                if (!event.getEntity().level().isClientSide) {
                    if (event.getEntity() instanceof Projectile projectile) {
                        if (projectile.getOwner() instanceof ServerPlayer serverPlayer) {
                            AMAdvancementTriggerRegistry.EMU_DODGE.trigger(serverPlayer);
                        }
                    }
                }
                emu.setDeltaMovement(emu.getDeltaMovement().add(vector3d2.x() * 0.5F, 0.32F, vector3d2.z() * 0.5F));
                event.setCanceled(true);
            }
        }
    }

