public void aiStep() {
        super.aiStep();
        if (this.isSitting() && this.getNavigation().isDone()) {
            this.getNavigation().stop();
        }
        boolean swim = this.isInWater();
        this.prevSwimProgress = SwimProgress;
        this.prevSitProgress = sitProgress;
        if(SwimProgress < 5F && swim){
            SwimProgress++;
        }
        if(SwimProgress > 0 && !swim){
            SwimProgress--;
        }
        if (this.isSitting() && sitProgress < 5) {
            this.sitProgress ++;
        }
        if (!this.isSitting() && sitProgress > 0) {
            this.sitProgress --;
        }

        if (this.isInWater() && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!this.isInWater() && !this.isLandNavigator) {
            switchNavigator(true);
        }

        if (blast_cooldown > 0) {
            blast_cooldown--;
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
        if (this.getAnimation() == BABY_LEVIATHAN_BITE) {
            if (this.getAnimationTick() == 7) {
                this.playSound(ModSounds.LEVIATHAN_BITE.get(), 0.5f, 2.0f);
            }
            if (this.getAnimationTick() == 9) {
                biteattack(1.5f, 0.5, 0.5, 0.5);
            }
        }
    }

@Override
    public void startAttackBehavior(LivingEntity target) {
        double distance = this.distanceTo(target);
        float f = this.getBbWidth() + target.getBbWidth();
        boolean meleeOnly = this.getItemInHand(InteractionHand.MAIN_HAND).is(ACItemRegistry.ORTHOLANCE.get());
        if ((distance > 15 || !melee) && !meleeOnly) {
            melee = false;
            if (!pickUpTrident() && this.getItemInHand(InteractionHand.MAIN_HAND).is(Items.TRIDENT)) {
                if (this.hasLineOfSight(target) && distance < 35) {
                    this.getNavigation().stop();
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(ANIMATION_THROW);
                    } else if (this.getAnimation() == ANIMATION_THROW && this.getAnimationTick() > 8) {
                        melee = true;
                        throwTrident(target);
                        this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    }
                } else {
                    this.getNavigation().moveTo(target, 1.2);
                }
            }
        }
        if (melee || meleeOnly) {
            if (distance < f + 1.0F) {
                if (this.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    setAnimation(this.getRandom().nextBoolean() ? ANIMATION_SCRATCH : ANIMATION_BITE);
                    this.playSound(ACSoundRegistry.DEEP_ONE_KNIGHT_ATTACK.get());
                }
            } else {
                this.getNavigation().moveTo(target, 1.2);
            }
        }
        if (this.getAnimation() == ANIMATION_SCRATCH) {
            if (this.getAnimationTick() > 5 && this.getAnimationTick() < 9 || this.getAnimationTick() > 12 && this.getAnimationTick() < 16) {
                checkAndDealMeleeDamage(target, 1.0F);
            }
        }
        if (this.getAnimation() == ANIMATION_BITE) {
            if (this.getAnimationTick() > 3 && this.getAnimationTick() <= 7) {
                checkAndDealMeleeDamage(target, 1.0F);
            }
        }
    }

protected void tickDeath() {
        if(deathTime <= 0){
            this.toggleServerEruptionStatus(false);
        }
        this.deathTime++;
        this.setAnimation(ANIMATION_EPIC_DEATH);
        this.setEnraged(true);
        screenShakeAmount = 0;
        this.setXRot(0.0F);
        this.setYHeadRot(this.getYRot());
        if (!level().isClientSide) {
            if (!collectedLoot) {
                populateDeathLootForLuxtructosaurus();
            }
        }
        if (this.getAnimation() == ANIMATION_EPIC_DEATH) {
            if (this.getAnimationTick() >= 100 && this.getAnimationTick() <= 110 && level().isClientSide) {
                for (int i = 0; i < 50; i++) {
                    level().addAlwaysVisibleParticle(ACParticleRegistry.LUXTRUCTOSAURUS_ASH.get(), true, this.getX(), this.getY(), this.getZ(), this.getId(), 0, 0);
                }
            }
            if (this.getAnimationTick() > 110 && !this.level().isClientSide() & !this.isRemoved()) {
                if (!deathItems.isEmpty()) {
                    ItemStack currentStack = ItemStack.EMPTY;
                    while (!deathItems.isEmpty() || !currentStack.isEmpty()) {
                        if (currentStack.isEmpty()) {
                            currentStack = deathItems.remove(0);
                        }
                        if (currentStack.getCount() > 0) {
                            ItemStack one = currentStack.copy();
                            one.setCount(1);
                            currentStack.shrink(1);
                            spawnAtLocation(one);
                        }
                    }

                }
                this.level().broadcastEntityEvent(this, (byte) 60);
                this.remove(Entity.RemovalReason.KILLED);
            }
        }

    }

