@Override
	public void tickRidden(Player rider, Vec3 vec3d) {
		super.tickRidden(rider, vec3d);
		this.setYRot(rider.getYRot());
		this.yRotO = this.getYRot();
		this.setXRot(0.0F);
		this.setRot(this.getYRot(), this.getXRot());
		this.yBodyRot = this.getYRot();
		this.yHeadRot = this.getYRot();

		float playerMoveFoward = rider.zza;

		if (!this.level().isClientSide() && playerMoveFoward > 0.0F) {
			if (this.onGround() && this.isNoEndimationPlaying() && !this.isBoofed()) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_HOP);
			} else if (!this.onGround() && this.isNoEndimationPlaying() && this.isBoofed()) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.BOOFLO_SWIM);
			}
		}

		if (this.isControlledByLocalInstance()) {
			if (this.getControllingPassenger() instanceof Player && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_INFLATE) && this.getAnimationTick() == 2 && !this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_SLAM)) {
				float boostPower = Mth.clamp(this.getBoostPower() * 0.01F, 0.35F, 1.82F);
				float verticalStrength = Mth.clamp(boostPower, 0.35F, 1.5F);

				float xMotion = -Mth.sin(this.getYRot() * ((float) Math.PI / 180F)) * Mth.cos(this.getXRot() * ((float) Math.PI / 180F));
				float zMotion = Mth.cos(this.getYRot() * ((float) Math.PI / 180F)) * Mth.cos(this.getXRot() * ((float) Math.PI / 180F));
				Vec3 boostFowardForce = new Vec3(xMotion, 1.3F * verticalStrength, zMotion).normalize().scale(boostPower > 0.35 ? boostPower * 2.0F : boostPower);

				this.setDeltaMovement(boostFowardForce.x(), 1.3F * verticalStrength, boostFowardForce.z());
				this.hasImpulse = true;
			}

			if (!this.isBoofed() && this.onGround() && this.isEndimationPlaying(EEPlayableEndimations.BOOFLO_HOP) && this.getAnimationTick() == 10) {
				Vec3 motion = this.getDeltaMovement();
				MobEffectInstance jumpBoost = this.getEffect(MobEffects.JUMP);
				float boostPower = jumpBoost == null ? 1.0F : (float) (jumpBoost.getAmplifier() + 1);

				this.setDeltaMovement(motion.x, 0.55F * boostPower, motion.z);
				this.hasImpulse = true;

				float xMotion = -Mth.sin(this.getYRot() * ((float) Math.PI / 180F));
				float zMotion = Mth.cos(this.getYRot() * ((float) Math.PI / 180F));

				float multiplier = 0.5F + (float) this.getAttribute(Attributes.MOVEMENT_SPEED).getValue();

				this.setDeltaMovement(this.getDeltaMovement().add(xMotion * multiplier, 0.0F, zMotion * multiplier));
			}
		}
	}

@Override
        protected void renderArmWithItem(LivingEntity livingEntity, ItemStack itemStack, ItemDisplayContext displayContext, HumanoidArm humanoidArm, PoseStack poseStack, MultiBufferSource multiBufferSource, int packedLight) {
            if (!itemStack.isEmpty() && livingEntity instanceof LicowitchEntity licowitch) {
                float partialTicks = Minecraft.getInstance().getPartialTick();
                boolean crossedArms = licowitch.areArmsVisuallyCrossed(partialTicks);

                boolean staff = itemStack.is(ACItemRegistry.SUGAR_STAFF.get());
                poseStack.pushPose();
                if (crossedArms) {
                    this.getParentModel().translateToCrossedArms(humanoidArm, poseStack);
                } else {
                    this.getParentModel().translateToHand(humanoidArm, poseStack);
                }
                poseStack.mulPose(Axis.XP.rotationDegrees(-90.0F));
                poseStack.mulPose(Axis.YP.rotationDegrees(180.0F));
                boolean flag = humanoidArm == HumanoidArm.LEFT;
                if (crossedArms) {
                    poseStack.translate(0.0F, 0.125F, -0.125F);
                } else {
                    poseStack.translate((float) (flag ? 1 : -1) * 0.0325F, 0.125F, -0.125F);
                }
                if (staff) {
                    float forwardsBend = 0;
                    if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0) {
                        forwardsBend = 0.66F * ACMath.cullAnimationTick(licowitch.getAnimationTick(), 1, LicowitchEntity.ANIMATION_SPELL_0, partialTicks, 18, 25);
                    }
                    if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1) {
                        forwardsBend = 0.4F * ACMath.cullAnimationTick(licowitch.getAnimationTick(), 1, LicowitchEntity.ANIMATION_SPELL_1, partialTicks, 25, 27);
                    }
                    if (crossedArms) {
                        poseStack.translate(0.0F, 0, 0.1F);
                        poseStack.mulPose(Axis.YP.rotationDegrees(90.0F));
                        poseStack.mulPose(Axis.ZP.rotationDegrees(5F));
                        poseStack.mulPose(Axis.XP.rotationDegrees(flag ? 20.0F : -20.0F));
                        poseStack.translate(0.0F, 0, -0.05F);
                    } else {
                        poseStack.mulPose(Axis.XP.rotationDegrees(-2.5F));
                    }
                    poseStack.translate(0F, -0.25F * forwardsBend, 0F);
                    poseStack.mulPose(Axis.XP.rotationDegrees(forwardsBend * -90F));
                } else {
                    poseStack.mulPose(Axis.XP.rotationDegrees(10.0F));
                }
                if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT) {
                    float animationIntensity = ACMath.cullAnimationTick(licowitch.getAnimationTick(), 4, LicowitchEntity.ANIMATION_EAT, partialTicks, 0);
                    poseStack.mulPose(Axis.XP.rotationDegrees(animationIntensity * 30.0F));
                }
                this.witchItemInHandRenderer.renderItem(livingEntity, itemStack, displayContext, flag, poseStack, multiBufferSource, packedLight);
                poseStack.popPose();
            }
        }

@Override
    public void tick() {
        super.tick();
        isOverAir = this.isOverAirLogic();
        if (this.isGoingUp()) {
            if (this.airBorneCounter == 0) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, 0.02F, 0));
            }
            if (!this.isFlying() && !this.isHovering()) {
                this.spacebarTicks += 2;
            }
        } else if (this.dismountIAF()) {
            if (this.isFlying() || this.isHovering()) {
                this.setFlying(false);
                this.setHovering(false);
            }
        }
        if (this.attack() && this.getControllingPassenger() != null && this.getControllingPassenger() instanceof Player) {

            LivingEntity target = DragonUtils.riderLookingAtEntity(this, (Player) this.getControllingPassenger(), 3);
            if (this.getAnimation() != ANIMATION_BITE && this.getAnimation() != ANIMATION_SCRATCH) {
                this.setAnimation(this.getRandom().nextBoolean() ? ANIMATION_SCRATCH : ANIMATION_BITE);
            }
            if (target != null && this.getAnimationTick() >= 10 && this.getAnimationTick() < 13) {
                target.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (this.getControllingPassenger() != null && this.getControllingPassenger().isShiftKeyDown()) {
            this.getControllingPassenger().stopRiding();
        }

        double motion = this.getDeltaMovement().x * this.getDeltaMovement().x + this.getDeltaMovement().z * this.getDeltaMovement().z;//Use squared norm2

        if (this.isFlying() && !this.isHovering() && this.getControllingPassenger() != null && this.isOverAir() &&  motion < 0.01F) {
            this.setHovering(true);
            this.setFlying(false);
        }
        if (this.isHovering() && !this.isFlying() && this.getControllingPassenger() != null && this.isOverAir() && motion > 0.01F) {
            this.setFlying(true);
            this.setHovering(false);
        }
        if (this.spacebarTicks > 0) {
            this.spacebarTicks--;
        }
        if (this.spacebarTicks > 10 && this.getOwner() != null && this.getPassengers().contains(this.getOwner()) && !this.isFlying() && !this.isHovering()) {
            this.setHovering(true);
        }
        if (this.getTarget() != null && this.getVehicle() == null && !this.getTarget().isAlive() || this.getTarget() != null && this.getTarget() instanceof EntityDragonBase && !this.getTarget().isAlive()) {
            this.setTarget(null);
        }
    }

