private void doStompFX() {
        double perpFacing = yBodyRot * (Math.PI / 180);
        double facingAngle = perpFacing + Math.PI / 2;
        int tick = getAnimationTick();
        final int maxDistance = 6;
        if (tick > 9 && tick < 17) {
            if (tick == 12) {
                final double infront = 1.47, side = -0.21;
                double vx = Math.cos(facingAngle) * infront;
                double vz = Math.sin(facingAngle) * infront;
                double perpX = Math.cos(perpFacing);
                double perpZ = Math.sin(perpFacing);
                double fx = getX() + vx + perpX * side;
                double fy = getBoundingBox().minY + 0.1;
                double fz = getZ() + vz + perpZ * side;
                int amount = 16 + level().random.nextInt(8);
                while (amount-- > 0) {
                    double theta = level().random.nextDouble() * Math.PI * 2;
                    double dist = level().random.nextDouble() * 0.1 + 0.25;
                    double sx = Math.cos(theta);
                    double sz = Math.sin(theta);
                    double px = fx + sx * dist;
                    double py = fy + level().random.nextDouble() * 0.1;
                    double pz = fz + sz * dist;
                    level().addParticle(ParticleTypes.SMOKE, px, py, pz, sx * 0.065, 0, sz * 0.065);
                }
            }
            if (tick % 2 == 0) {
                int distance = tick / 2 - 2;
                double spread = Math.PI * 2;
                int arcLen = Mth.ceil(distance * spread);
                for (int i = 0; i < arcLen; i++) {
                    double theta = (i / (arcLen - 1.0) - 0.5) * spread + facingAngle;
                    double vx = Math.cos(theta);
                    double vz = Math.sin(theta);
                    double px = getX() + vx * distance;
                    double pz = getZ() + vz * distance;
                    float factor = 1 - distance / (float) maxDistance;
                    if (level().random.nextBoolean()) {
                        int amount = level().random.nextInt(5);
                        while (amount-- > 0) {
                            double velX = vx * 0.075;
                            double velY = factor * 0.3 + 0.025;
                            double velZ = vz * 0.075;
                            level().addParticle(ParticleTypes.CLOUD, px + level().random.nextFloat() * 2 - 1, getBoundingBox().minY + 0.1 + level().random.nextFloat() * 1.5, pz + level().random.nextFloat() * 2 - 1, velX, velY, velZ);
                        }
                    }
                }
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        BlockPos target = getMoveToTarget();
        if (target != null) {
            if (isReachedTarget()) {
                if (relicheirus.lockTreePosition(blockPos)) {
                    if (relicheirus.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        relicheirus.setPeckY(blockPos.getY());
                        relicheirus.setAnimation(RelicheirusEntity.ANIMATION_PUSH_TREE);
                    } else if (relicheirus.getAnimation() == RelicheirusEntity.ANIMATION_PUSH_TREE) {
                        if (relicheirus.getAnimationTick() >= 35 && !madeTreeEntity) {
                            madeTreeEntity = true;
                            relicheirus.playSound(ACSoundRegistry.RELICHEIRUS_TOPPLE.get());
                            List<BlockPos> gathered = new ArrayList<>();
                            gatherAttachedBlocks(blockPos, blockPos, gathered);
                            if (!gathered.isEmpty()) {
                                List<MovingBlockData> allData = new ArrayList<>();
                                for (BlockPos pos : gathered) {
                                    BlockState moveState = relicheirus.level().getBlockState(pos);
                                    BlockEntity te = relicheirus.level().getBlockEntity(pos);
                                    BlockPos offset = pos.subtract(blockPos);
                                    MovingBlockData data = new MovingBlockData(moveState, moveState.getShape(relicheirus.level(), pos), offset, te == null ? null : te.saveWithoutMetadata());
                                    relicheirus.level().removeBlockEntity(pos);
                                    allData.add(data);
                                }
                                for (BlockPos pos : gathered) {
                                    relicheirus.level().setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
                                }
                                FallingTreeBlockEntity fallingTree = ACEntityRegistry.FALLING_TREE_BLOCK.get().create(relicheirus.level());
                                fallingTree.moveTo(Vec3.atCenterOf(blockPos));
                                fallingTree.setAllBlockData(FallingTreeBlockEntity.createTagFromData(allData));
                                fallingTree.setPlacementCooldown(1);
                                Vec3 vec3 = Vec3.atCenterOf(blockPos).subtract(relicheirus.position());
                                float f = -((float) Mth.atan2(vec3.x, vec3.z)) * 180.0F / (float) Math.PI;
                                fallingTree.setFallDirection(Direction.fromYRot(f));
                                relicheirus.level().addFreshEntity(fallingTree);
                            }
                        }
                    }
                }
            } else {
                if (relicheirus.getNavigation().isDone()) {
                    Vec3 vec31 = Vec3.atCenterOf(target);
                    Vec3 vec32 = vec31.subtract(relicheirus.position());
                    if (vec32.length() > 1) {
                        vec32 = vec32.normalize();
                    }
                    Vec3 delta = new Vec3(vec32.x * 0.1F, 0F, vec32.z * 0.1F);
                    relicheirus.setDeltaMovement(relicheirus.getDeltaMovement().add(delta));
                }
            }
        }
    }

public void tick() {
        if(jumpCooldown > 0){
            jumpCooldown--;
        }
        if (stalk) {
            if (secondPartOfLeap) {
                this.leopard.setTackling(!leopard.onGround());
                leopard.lookAt(target, 180F, 10F);
                leopard.yBodyRot = leopard.getYRot();
                if (this.leopard.distanceTo(target) < 3F && this.leopard.hasLineOfSight(target)) {
                    target.hurt(this.leopard.damageSources().mobAttack(leopard), (float) (leopard.getAttribute(Attributes.ATTACK_DAMAGE).getValue() * 2.5F));
                    this.stalk = false;
                    this.secondPartOfLeap = false;
                }else if (leopard.onGround() && jumpCooldown == 0) {
                    this.leopard.setSlSneaking(false);
                    jumpCooldown = 10 + leopard.getRandom().nextInt(10);
                    Vec3 vector3d = this.leopard.getDeltaMovement();
                    Vec3 vector3d1 = new Vec3(this.target.getX() - this.leopard.getX(), 0.0D, this.target.getZ() - this.leopard.getZ());
                    if (vector3d1.lengthSqr() > 1.0E-7D) {
                        vector3d1 = vector3d1.normalize().scale(0.9D).add(vector3d.scale(0.8D));
                    }
                    this.leopard.setDeltaMovement(vector3d1.x, vector3d1.y + 0.6F, vector3d1.z);
                }
            } else {
                if (leapPos == null || target.distanceToSqr(leapPos) > 250) {
                    Vec3 vector3d1 = calculateFarPoint(50);
                    if (vector3d1 != null) {
                        leapPos = vector3d1;
                    }else{
                        leapPos = LandRandomPos.getPosTowards(leopard, 10, 10, target.position());
                    }
                } else {
                    this.leopard.setSlSneaking(true);
                    this.leopard.getNavigation().moveTo(leapPos.x, leapPos.y, leapPos.z, 1D);
                    if (this.leopard.distanceToSqr(leapPos.x, leapPos.y, leapPos.z) < 9) {
                        if (this.leopard.hasLineOfSight(target)) {
                            secondPartOfLeap = true;
                            this.leopard.getNavigation().stop();
                        }
                    }
                }
            }
        } else {
            this.leopard.setSlSneaking(false);
            this.leopard.getNavigation().moveTo(target, 1D);
            if (this.leopard.distanceTo(target) < 3F) {
                if(leopard.getAnimation() == IAnimatedEntity.NO_ANIMATION){
                    leopard.setAnimation(leopard.getRandom().nextBoolean() ? EntitySnowLeopard.ANIMATION_ATTACK_R : EntitySnowLeopard.ANIMATION_ATTACK_L);
                }else if(this.leopard.getAnimationTick() == 5){
                    leopard.doHurtTarget(target);
                }
            }
        }
    }

