public PlayState spinoPredicate(AnimationEvent<PrehistoricSwimming> event) {
            if (isBlocked()) return PlayState.STOP;
            AnimationController<PrehistoricSwimming> controller = event.getController();
            if (tryNextAnimation(controller)) {
                return PlayState.CONTINUE;
            }
            Optional<ActiveAnimationInfo> activeAnimation = getActiveAnimation(controller.getName());
            if (activeAnimation.isPresent() && tryForcedAnimation(event, activeAnimation.get())) {
                return PlayState.CONTINUE;
            }
            double animationSpeed = 1;
            if (event.getAnimatable().isBeached()) {
                addActiveAnimation(controller.getName(), AnimationCategory.BEACHED);
            } else if (entity.isSleeping()) {
                addActiveAnimation(controller.getName(), AnimationCategory.SLEEP);
            } else if (event.isMoving()) {
                if (entity.isInWater()) {
                    boolean onGround = (entity.getY() - Math.floor(entity.getY()) < 0.05) && entity.level.getFluidState(entity.blockPosition().below()).isEmpty();
                    if (entity.isEyeInFluid(FluidTags.WATER)) {
                        if (onGround) {
                            addActiveAnimation(controller.getName(), entity.getAnimation(SWIM_GROUND).animation, AnimationCategory.SWIM, false);
                        } else {
                            addActiveAnimation(controller.getName(), entity.getAnimation(SWIM_UNDERWATER).animation, AnimationCategory.SWIM, false);
                        }
                    } else {
                        if (onGround) {
                            animationSpeed = addMovementAnimation(event, false);
                        } else {
                            addActiveAnimation(controller.getName(), entity.getAnimation(SWIM_FLOATING).animation, AnimationCategory.SWIM, false);
                        }
                    }
                } else {
                    animationSpeed = addMovementAnimation(event, false);
                }
            } else if (event.getAnimatable().isWeak()) {
                addActiveAnimation(controller.getName(), AnimationCategory.KNOCKOUT);
            } else {
                if (entity.isInWater()) {
                    if (entity.isEyeInFluid(FluidTags.WATER)) {
                        addActiveAnimation(controller.getName(), entity.getAnimation(IDLE_WATER).animation, AnimationCategory.IDLE, false);
                    } else {
                        addActiveAnimation(controller.getName(), entity.getAnimation(IDLE_WATER_FLOAT).animation, AnimationCategory.IDLE, false);
                    }
                } else {
                    addActiveAnimation(controller.getName(), entity.getAnimation(IDLE).animation, AnimationCategory.IDLE, false);
                }
            }
            setAnimationSpeed(controller, animationSpeed, event.getAnimationTick());
            Optional<ActiveAnimationInfo> newAnimation = getActiveAnimation(controller.getName());
            if (newAnimation.isPresent()) {
                controller.setAnimation(new AnimationBuilder().addAnimation(newAnimation.get().animationName(), newAnimation.get().loop() ? LOOP : PLAY_ONCE));
            }
            return PlayState.CONTINUE;
        }

private void epicfight$computeCameraAngles(ViewportEvent.ComputeCameraAngles event) {
        EpicFightCapabilities.getUnparameterizedEntityPatch(this.minecraft.player, LocalPlayerPatch.class).ifPresent(playerpatch -> {
            // First person camera correction
            if (ClientConfig.enableFirstPersonCameraMove && this.minecraft.options.getCameraType().isFirstPerson() && playerpatch.isEpicFightMode() && !playerpatch.getFirstPersonLayer().isOff()) {
                float partialTick = (float)event.getPartialTick();
                EpicFightCameraAPI cameraApi = EpicFightCameraAPI.getInstance();

                if (cameraApi.isLerpingFpv()) {
                    float xRot = cameraApi.getLerpedFpvXRot(partialTick);
                    float yRot = cameraApi.getLerpedFpvYRot(partialTick);
                    this.minecraft.cameraEntity.setXRot(xRot);
                    this.minecraft.cameraEntity.setYRot(yRot);
                } else {
                    AnimationSubFileReader.PovSettings.ViewLimit viewLimit = playerpatch.getPovSettings().viewLimit();

                    if (viewLimit != null) {
                        float clampedXRot = Mth.clamp(event.getPitch(), viewLimit.xRotMin(), viewLimit.xRotMax());
                        float bodyY = MathUtils.findNearestRotation(event.getYaw(), playerpatch.getYRot());
                        float clampedYRot = Mth.clamp(event.getYaw(), bodyY + viewLimit.yRotMin(), bodyY + viewLimit.yRotMax());

                        if (Float.compare(clampedXRot, event.getPitch()) != 0 || Float.compare(clampedYRot, event.getYaw()) != 0) {
                            cameraApi.fixFpvRotation(clampedXRot, playerpatch.getYRot(), 5);
                        }
                    }
                }

                if (playerpatch.hasCameraAnimation()) {
                    float time = Mth.lerp(partialTick, playerpatch.getFirstPersonLayer().animationPlayer.getPrevElapsedTime(), playerpatch.getFirstPersonLayer().animationPlayer.getElapsedTime());
                    JointTransform cameraTransform;

                    if (playerpatch.getFirstPersonLayer().animationPlayer.getAnimation().get().isLinkAnimation() || playerpatch.getPovSettings() == null) {
                        cameraTransform = playerpatch.getFirstPersonLayer().getLinkCameraTransform().getInterpolatedTransform(time);
                    } else {
                        cameraTransform = playerpatch.getPovSettings().cameraTransform().getInterpolatedTransform(time);
                    }

                    float xRot = playerpatch.getOriginal().getXRot();
                    float yRot = playerpatch.getOriginal().getYRot();

                    Vec3f translation = OpenMatrix4f.transform3v(OpenMatrix4f.ofRotationDegree(yRot, Vec3f.Y_AXIS, PLAYER_ROTATION).rotate(xRot, Vec3f.X_AXIS), cameraTransform.translation(), null);
                    Quaternionf rot = cameraTransform.rotation();
                    rot.getEulerAnglesXYZ(CAMERA_ROTATION_EULER);

                    CAMERA_ROTATION_EULER.x = (float)Math.toDegrees(CAMERA_ROTATION_EULER.x);
                    CAMERA_ROTATION_EULER.y = (float)Math.toDegrees(CAMERA_ROTATION_EULER.y);
                    CAMERA_ROTATION_EULER.z = (float)Math.toDegrees(CAMERA_ROTATION_EULER.z);

                    event.getCamera().move(translation.x, translation.y, translation.z);
                    event.setPitch(event.getPitch() + CAMERA_ROTATION_EULER.x);
                    event.setYaw(event.getYaw() + CAMERA_ROTATION_EULER.y);
                    event.setRoll(event.getRoll() + CAMERA_ROTATION_EULER.z);
                }
            }
        });
    }

public void tick() {
        if (entity.groundedFor <= 0) {
            if (entity.isHanging()) {
                entity.setHanging(false);
                entity.setFlying(true);
            } else if (!entity.isFlying()) {
                entity.setFlying(true);
            }
        } else {
            entity.setFlying(false);
        }
        LivingEntity target = entity.getTarget();
        if (target != null && target.isAlive()) {
            double distance = entity.distanceTo(target);
            float f = entity.getBbWidth() + target.getBbWidth();
            if (startOrbitFrom == null) {
                entity.getNavigation().moveTo(target, entity.isFlying() ? 2.5D : 1D);
                entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition());
            } else if (orbitTime < maxOrbitTime && entity.groundedFor <= 0) {
                orbitTime++;
                float zoomIn = 1F - orbitTime / (float) maxOrbitTime;
                Vec3 orbitPos = orbitAroundPos(3.0F + zoomIn * 5.0F).add(0, 4 + zoomIn * 3, 0);
                entity.getNavigation().moveTo(orbitPos.x, orbitPos.y, orbitPos.z, entity.isFlying() ? 2.5D : 1D);
                entity.lookAt(EntityAnchorArgument.Anchor.EYES, orbitPos);
            } else {
                orbitTime = 0;
                startOrbitFrom = null;
            }
            if (distance < f + 0.5D) {
                if (entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    entity.setAnimation(VesperEntity.ANIMATION_BITE);
                } else if (entity.getAnimationTick() == 8 && entity.hasLineOfSight(target)) {
                    boolean flag = target.isBlocking();
                    if (target.hurt(target.damageSources().mobAttack(entity), (float) entity.getAttribute(Attributes.ATTACK_DAMAGE).getValue())) {
                        if (!target.isAlive() && target instanceof GloomothEntity gloomothEntity) {
                            if (gloomothEntity.lightPos != null && gloomothEntity.distanceToSqr(Vec3.atCenterOf(gloomothEntity.lightPos)) < 32.0F) {
                                entity.groundedFor = 100 + entity.getRandom().nextInt(40);
                                entity.setFlying(false);
                            }
                        }
                    }
                    maxOrbitTime = 60 + entity.getRandom().nextInt(80);
                    startOrbitFrom = target.getEyePosition();
                    if (flag) {
                        if (target instanceof final Player player) {
                            damageShieldFor(player, (float) entity.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
                        }
                        entity.groundedFor = 60 + entity.getRandom().nextInt(40);
                        entity.setFlying(false);
                        startOrbitFrom = null;
                    }
                }
            }

        }
    }

@Override
    public void render(PoseStack matrixStackIn, @NotNull MultiBufferSource bufferIn, int packedLightIn, EntityDragonBase dragon, float limbSwing, float limbSwingAmount, float partialTicks, float ageInTicks, float netHeadYaw, float headPitch) {
        matrixStackIn.pushPose();
        if (!dragon.getPassengers().isEmpty()) {
            float dragonScale = dragon.getRenderSize() / 3;
            for (Entity passenger : dragon.getPassengers()) {
                boolean prey = dragon.getControllingPassenger() == null || dragon.getControllingPassenger().getId() != passenger.getId();
                if (excludeDreadQueenMob && passenger instanceof EntityDreadQueen) {
                    prey = false;
                }
                ClientProxy.currentDragonRiders.remove(passenger.getUUID());
                float riderRot = passenger.yRotO + (passenger.getYRot() - passenger.yRotO) * partialTicks;
                int animationTicks = 0;
                if (dragon.getAnimation() == EntityDragonBase.ANIMATION_SHAKEPREY) {
                    animationTicks = dragon.getAnimationTick();
                }
                if (animationTicks == 0 || animationTicks >= 15) {
                    translateToBody(matrixStackIn);
                }
                if (prey) {
                    if (animationTicks == 0 || animationTicks >= 15 || dragon.isFlying()) {
                        translateToHead(matrixStackIn);
                        offsetPerDragonType(dragon.dragonType, matrixStackIn);
                        EntityRenderer render = Minecraft.getInstance().getEntityRenderDispatcher().getRenderer(passenger);
                        EntityModel modelBase = null;
                        if (render instanceof MobRenderer) {
                            modelBase = ((MobRenderer) render).getModel();
                        }
                        if ((passenger.getBbHeight() > passenger.getBbWidth() || modelBase instanceof HumanoidModel) && !(modelBase instanceof QuadrupedModel) && !(modelBase instanceof HorseModel)) {
                            matrixStackIn.translate(-0.15F * passenger.getBbHeight(), 0.1F * dragonScale - 0.1F * passenger.getBbHeight(), -0.1F * dragonScale - 0.1F * passenger.getBbWidth());
                            matrixStackIn.mulPose(new Quaternion(Vector3f.ZP, 90, true));
                            matrixStackIn.mulPose(new Quaternion(Vector3f.YP, 45, true));
                        } else {
                            boolean horse = modelBase instanceof HorseModel;
                            matrixStackIn.translate((horse ? -0.08F : -0.15F) * passenger.getBbWidth(), 0.1F * dragonScale - 0.15F * passenger.getBbWidth(), -0.1F * dragonScale - 0.1F * passenger.getBbWidth());
                            matrixStackIn.mulPose(new Quaternion(Vector3f.XN, 90, true));
                        }
                    } else {
                        matrixStackIn.translate(0, 0.555F * dragonScale, -0.5F * dragonScale);
                    }

                } else {
                    matrixStackIn.translate(0, -0.01F * dragonScale, -0.035F * dragonScale);
                }
                matrixStackIn.pushPose();
                matrixStackIn.mulPose(new Quaternion(Vector3f.ZP, 180, true));
                matrixStackIn.mulPose(new Quaternion(Vector3f.YP, riderRot + 180, true));
                matrixStackIn.scale(1 / dragonScale, 1 / dragonScale, 1 / dragonScale);
                matrixStackIn.translate(0, -0.25F, 0);
                renderEntity(passenger, 0.0D, 0.0D, 0.0D, 0.0F, partialTicks, matrixStackIn, bufferIn, packedLightIn);
                matrixStackIn.popPose();
                ClientProxy.currentDragonRiders.add(passenger.getUUID());
            }
        }
        matrixStackIn.popPose();
    }

