public void tick() {
        super.tick();
        if (this.getAnimation() != ANIMATION_EAT_TREE) {
            this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, yBodyRot, getHeadRotSpeed());
        }
        this.prevRaiseArmsAmount = raiseArmsAmount;
        this.legSolver.update(this, this.yBodyRot, this.getScale());
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (shouldRaiseArms() && raiseArmsAmount < 5F) {
            raiseArmsAmount++;
        }
        if (!shouldRaiseArms() && raiseArmsAmount > 0F) {
            raiseArmsAmount--;
        }
        if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        if (!level().isClientSide) {
            if (isStillEnough() && random.nextInt(200) == 0 && this.getAnimation() == NO_ANIMATION && !this.isDancing()) {
                Animation idle;
                float rand = random.nextFloat();
                if (rand < 0.15F) {
                    idle = ANIMATION_SCRATCH_1;
                } else if (rand < 0.3F) {
                    idle = ANIMATION_SCRATCH_2;
                } else {
                    idle = ANIMATION_SHAKE;
                }
                this.setAnimation(idle);
            }
            boolean held = false;
            LivingEntity target = this.getTarget();
            if (target != null && target.distanceTo(this) < 10 && target instanceof TrilocarisEntity) {
                if (this.getAnimation() == ANIMATION_EAT_TRILOCARIS) {
                    if (this.getAnimationTick() < 20) {
                        held = true;
                        this.setHeldMobId(target.getId());
                    } else if (this.getAnimationTick() <= 50) {
                        Vec3 trilocarisPos = getTrilocarisPos();
                        target.setPos(trilocarisPos);
                        if (this.getAnimationTick() >= 45 && target.isAlive()) {
                            target.hurt(damageSources().mobAttack(this), 20);
                        }
                        held = true;
                        target.fallDistance = 0;
                    }
                }
            }
            if (!held && getHeldMobId() != -1) {
                this.setHeldMobId(-1);
            }
            if (this.getPushingTreesFor() > 0) {
                this.setPushingTreesFor(this.getPushingTreesFor() - 1);
            }
        }
        if (this.getAnimation() == ANIMATION_SPEAK_1 && this.getAnimationTick() == 1 || this.getAnimation() == ANIMATION_SPEAK_2 && this.getAnimationTick() == 1) {
            actuallyPlayAmbientSound();
        }
    }

private void tickMultipart() {
        if (yawPointer == -1) {
            for (int i = 0; i < yawBuffer.length; i++) {
                yawBuffer[i] = this.yBodyRot;
            }
        }
        if (++this.yawPointer == this.yawBuffer.length) {
            this.yawPointer = 0;
        }
        this.yawBuffer[this.yawPointer] = this.yBodyRot;

        Vec3[] avector3d = new Vec3[this.allParts.length];
        for (int j = 0; j < this.allParts.length; ++j) {
            avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
        }
        float neckRotateSpeed = getNeckRotateSpeed();
        float tailRotateSpeed = getTailRotateSpeed();
        if(turningFast){
            neckRotateSpeed += 30;
            tailRotateSpeed += 30;
        }
        this.neckXRot = wrapNeckDegrees(Mth.approachDegrees(this.neckXRot, getTargetNeckXRot(), neckRotateSpeed));
        this.neckYRot = wrapNeckDegrees(Mth.approachDegrees(this.neckYRot, getTargetNeckYRot(), neckRotateSpeed));
        this.tailXRot = wrapNeckDegrees(Mth.approachDegrees(this.tailXRot, getTargetTailXRot(), tailRotateSpeed));
        this.tailYRot = wrapNeckDegrees(Mth.approachDegrees(this.tailYRot, getTargetTailYRot(), tailRotateSpeed));
        Vec3 center = this.position().add(0, this.getBbHeight() * 0.5F - getLegSolverBodyOffset(), 0);
        float headXStep = neckXRot / 4F;
        float headYStep = neckYRot / 4F;
        float tailXStep = tailXRot / 3F;
        float tailYStep = tailYRot / 3F;
        float neckAdditionalY = 0F;
        float neckAdditionalZ = 0F;
        if (this.getAnimation() == ANIMATION_STOMP) {
            float f = ACMath.cullAnimationTick(this.getAnimationTick(), 2, ANIMATION_STOMP, 1.0F, 0, 30);
            neckAdditionalY = 4 * f;
            neckAdditionalZ = -4 * f;
        }else if(this.isDancing()){
            float f = this.getDanceProgress(1.0F);
            neckAdditionalY = 4 * f;
            neckAdditionalZ = -4 * f;
            headYStep *= (1F - f);
        }
        this.neckPart1.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, 2F + neckAdditionalY, 5F + neckAdditionalZ).scale(this.getScale()), headXStep, (yBodyRot + headYStep)).add(center));
        this.neckPart2.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, 0, 2.5F).scale(this.getScale()), headXStep, (yBodyRot + headYStep * 2F)).add(this.neckPart1.centeredPosition()));
        this.neckPart3.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, 0, 2F).scale(this.getScale()), headXStep, (yBodyRot + headYStep * 3F)).add(this.neckPart2.centeredPosition()));
        this.headPart.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, 0, 2.5F).scale(this.getScale()), headXStep, (yBodyRot + headYStep * 4F)).add(this.neckPart3.centeredPosition()));
        this.tailPart1.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, -0.5F, -3.5F).scale(this.getScale()), tailXStep, (yBodyRot + tailYStep)).add(center));
        this.tailPart2.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, -0.25F, -3.25F).scale(this.getScale()), tailXStep, (yBodyRot + tailYStep * 2F)).add(this.tailPart1.centeredPosition()));
        this.tailPart3.setPosCenteredY(this.rotateOffsetVec(new Vec3(0, 0, -2.5F).scale(this.getScale()), tailXStep, (yBodyRot + tailYStep * 3F)).add(this.tailPart2.centeredPosition()));

        for (int l = 0; l < this.allParts.length; ++l) {
            this.allParts[l].xo = avector3d[l].x;
            this.allParts[l].yo = avector3d[l].y;
            this.allParts[l].zo = avector3d[l].z;
            this.allParts[l].xOld = avector3d[l].x;
            this.allParts[l].yOld = avector3d[l].y;
            this.allParts[l].zOld = avector3d[l].z;
        }
    }

public void tick() {
        super.tick();
        if(this.isInWater()){
            this.setMaxUpStep(1.2F);
        }else{
            this.setMaxUpStep(0.6F);
        }
        prevFlyProgress = flyProgress;

        final boolean flying = isFlying();

        if (flying) {
            if (flyProgress < 5F)
                flyProgress++;
        } else {
            if (flyProgress > 0F)
                flyProgress--;
        }

        if (revengeCooldown > 0) {
            revengeCooldown--;
        }
        if (revengeCooldown == 0 && this.getLastHurtByMob() != null) {
            this.setLastHurtByMob(null);
        }
        if (!this.level().isClientSide) {
            if(fishingCooldown > 0){
                fishingCooldown--;
            }
            if(this.getAnimation() == NO_ANIMATION && this.getRandom().nextInt(700) == 0){
                this.setAnimation(ANIMATION_BEAKSHAKE);
            }

            if (flying) {
                if (this.isLandNavigator)
                    switchNavigator(false);
            } else {
                if (!this.isLandNavigator)
                    switchNavigator(true);
            }

            if (this.revengeCooldown > 0 && !this.isFlying()) {
                if (this.onGround() || this.isInWater()) {
                    this.setFlying(false);
                }
            }

            if (isFlying()) {
                this.setNoGravity(true);
            } else {
                this.setNoGravity(false);
            }
        }
        if (!this.level().isClientSide && this.getTarget() != null && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 9 && this.hasLineOfSight(this.getTarget())) {
            getTarget().knockback(0.3F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
            this.getTarget().hurt(this.damageSources().mobAttack(this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue());
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void tick() {
        super.tick();
        float maxHealth = this.getMaxHealth();
        float currentHealth = this.getHealth();
        this.bossEvent.setProgress(currentHealth / maxHealth);
        int daggerTime = getSpectralDaggerTime();
        if (getSpectralDaggerTime() != 0) {
            this.entityData.set(DATA_DAGGER_TIME, daggerTime - Mth.sign(daggerTime));
        }
        if (parryCooldown > 0) {
            parryCooldown--;
        }
        if (isSpawning()) {
            spawnTimer--;
            handleSpawnSequence();
            if (spawnTimer == 0 && !level.isClientSide) {
                spawnKnight(true);
                spawnKnight(false);
            }
        } else if (isDespawning()) {
            // reuse death time for fadeout animations
            deathTime++;
            if (!level.isClientSide) {
                deathParticles();
                if (getTarget() != null) {
                    // stop despawning if we re-aggro
                    setDespawning(false);
                }
                if (deathTime > 160) {
                    doForcedDespawned();
                }
            }
        } else if (deathTime > 0 && !isDeadOrDying()) {
            // quickly fade back in from despawn animation
            deathTime = Math.max(0, deathTime - 3);
        } else if (isHalfHealthAttacking()) {
            halfHealthTimer--;
            if (!level.isClientSide) {
                handleHalfHealthSequence();
            }
        }
        if (!level.isClientSide) {
            // while this is server-only logic, this cannot be in aistep because ai is disabled during stance breaks
            if (isStanceBroken()) {
                stanceBreakTimer--;
                handleStanceBreakSequence();
            }
            if (isSoulMode() && !dead && !isSpawning()) {
                soulParticles();
            }
        }
        if (destroyBlockDelay > 0) {
            --destroyBlockDelay;
        }
        if (stuckDetectorDelay > 0) {
            --stuckDetectorDelay;
        }
    }

@Override
    public void tick() {
        super.tick();
        if (level().isClientSide) {
            if (this.getAnimation() == ANIMATION_EAT_LEAVES && this.getAnimationTick() > 35 && this.getAnimationTick() < 90) {
                BlockState lastEatenBlock = getLastEatenBlock();
                if (lastEatenBlock != null) {
                    Vec3 crumbPos = this.headPart.position().add((random.nextFloat() - 0.5F) * 2.0F * this.getScale(), (0.5F + (random.nextFloat() - 0.5F) * 0.2F) * this.getScale(), (random.nextFloat() - 0.5F) * 2.0F * this.getScale());
                    this.level().addParticle(new BlockParticleOption(ParticleTypes.BLOCK, lastEatenBlock), crumbPos.x, crumbPos.y, crumbPos.z, ((double) this.random.nextFloat() - 0.5D) * 0.1D, ((double) this.random.nextFloat() - 0.5D) * 0.1D, ((double) this.random.nextFloat() - 0.5D) * 0.1D);
                }
            }
            if(this.getRideableFor() > 0 && level().random.nextInt(2) == 0 && !this.isDancing()){
                Vec3 particlePos = this.headPart.position().add((random.nextFloat() - 0.5F) * 2.0F * this.getScale(), random.nextFloat() * 2.0F * this.getScale(), (random.nextFloat() - 0.5F) * 2.0F * this.getScale()).add(this.getDeltaMovement());
                this.level().addParticle(ACParticleRegistry.HAPPINESS.get(), particlePos.x, particlePos.y, particlePos.z, ((double) this.random.nextFloat() - 0.5D) * 0.1D, ((double) this.random.nextFloat() - 0.5D) * 0.1D, ((double) this.random.nextFloat() - 0.5D) * 0.1D);
            }
            Player player = AlexsCaves.PROXY.getClientSidePlayer();
            if (player != null && player.isPassengerOfSameVehicle(this)) {
                if (AlexsCaves.PROXY.isKeyDown(2) && getMeterAmount() >= 1.0F) {
                    AlexsCaves.sendMSGToServer(new MountedEntityKeyMessage(this.getId(), player.getId(), 2));
                }
            }
        }else{
            if(this.getAnimation() == ANIMATION_STOMP && this.getAnimationTick() == 30){
                this.playSound(ACSoundRegistry.ATLATITAN_STOMP.get(), 3.0F, 1.0F);
                if(this.screenShakeAmount < 4.0F){
                    this.screenShakeAmount = 4.0F;
                }
                crushBlocksInRing(15, this.getBlockX(), this.getBlockZ(), 1.0F);
                if(this.isVehicle() && !this.level().isClientSide){
                    for(Entity passenger : this.getPassengers()){
                        ACAdvancementTriggerRegistry.ATLATITAN_STOMP.triggerForEntity(passenger);
                    }
                }
            }
            if(this.getRideableFor() > 0){
                this.setRideableFor(this.getRideableFor() - 1);
            }
            if (this.tickCount % 100 == 0 && this.getHealth() < this.getMaxHealth()) {
                this.heal(2);
            }
            if(this.getAnimation() == ANIMATION_RIGHT_KICK && this.getAnimationTick() == 8){
                Vec3 armPos = this.position().add(rotateOffsetVec(new Vec3(-2, 0, 2.5F), 0, this.yBodyRot));
                this.hurtEntitiesAround(armPos, 5.0F,  (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 0.8F, 1.0F, false, false);
            }
            if(this.getAnimation() == ANIMATION_LEFT_KICK && this.getAnimationTick() == 8){
                Vec3 armPos = this.position().add(rotateOffsetVec(new Vec3(2, 0, 2.5F), 0, this.yBodyRot));
                this.hurtEntitiesAround(armPos, 5.0F,  (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 0.8F, 1.0F, false, false);
            }
            if((this.getAnimation() == ANIMATION_LEFT_WHIP || this.getAnimation() == ANIMATION_RIGHT_WHIP) && this.getAnimationTick() > 20 && this.getAnimationTick() < 30){
                this.hurtEntitiesAround(this.tailPart2.position(), 12.0F, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE), 1.0F, false, false);
            }
        }
        if (this.isVehicle()) {
            if (this.getMeterAmount() < 1.0F) {
                this.setMeterAmount(Math.min(this.getMeterAmount() + 0.0025F, 1.0F));
            }
        } else {
            this.setMeterAmount(0.0F);
        }
    }

@Override
    public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        this.prevRaiseArmsAmount = raiseArmsAmount;
        this.prevScreenShakeAmount = screenShakeAmount;
        this.legSolver.update(this, this.yBodyRot, this.getScale());
        if (shouldRaiseArms() && raiseArmsAmount < 5F) {
            raiseArmsAmount++;
        }
        if (!shouldRaiseArms() && raiseArmsAmount > 0F) {
            raiseArmsAmount--;
        }
        if (screenShakeAmount > 0) {
            screenShakeAmount = Math.max(0, screenShakeAmount - 0.3F);
        }
        if (this.getAnimation() != ANIMATION_LEFT_WHIP && this.getAnimation() != ANIMATION_RIGHT_WHIP) {
            this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, this.getYRot(), turningFast ? 10 : 2);
            lastYawBeforeWhip = this.getYRot();
        } else {
            float negative = this.getAnimation() == ANIMATION_RIGHT_WHIP ? -1 : 1;
            float target = 0;
            if (this.getAnimationTick() > 10) {
                float f = (this.getAnimationTick() - 10) / 30F;
                target = f * 230;
            }
            if (this.getAnimationTick() > 30F) {
                this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, lastYawBeforeWhip, 15);
            } else {
                this.yBodyRot = Mth.approachDegrees(this.yBodyRotO, lastYawBeforeWhip + negative * target, 90);
            }
        }
        tickMultipart();
        tickWalking();
        if (level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
        }
        if (this.getAnimation() == ANIMATION_STOMP && this.getAnimationTick() > 25 && this.getAnimationTick() < 35 || this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() > 5 && this.getAnimationTick() < 45) {
            if (screenShakeAmount <= 2.0F) {
                screenShakeAmount = 2.0F;
            }
        }
        if(wasPreviouslyChild != this.isBaby()){
            wasPreviouslyChild = this.isBaby();
            this.refreshDimensions();
            for(SauropodPartEntity sauropodPartEntity : this.allParts){
                sauropodPartEntity.refreshDimensions();
            }
        }
    }

public void tick() {
            if (dashCooldown > 0) {
                dashCooldown--;
            }
            if (EntityWarpedMosco.this.getTarget() != null) {
                LivingEntity target = EntityWarpedMosco.this.getTarget();
                ranged = EntityWarpedMosco.this.shouldRangeAttack(target);
                if (EntityWarpedMosco.this.isFlying() || ranged || EntityWarpedMosco.this.distanceTo(target) > 12 && !EntityWarpedMosco.this.isTargetBlocked(target.position().add(0, target.getBbHeight() * 0.6F, 0))) {
                    float speedRush = 5F;
                    upTicks++;
                    EntityWarpedMosco.this.setFlying(true);
                    if (ranged) {
                        if (farTarget == null || EntityWarpedMosco.this.distanceToSqr(Vec3.atCenterOf(farTarget)) < 9) {
                            farTarget = this.getAvoidTarget(target);
                        }
                        if (farTarget != null) {
                            EntityWarpedMosco.this.getMoveControl().setWantedPosition(farTarget.getX(), farTarget.getY() + target.getEyeHeight() * 0.6F, farTarget.getZ(), 3D);
                        }
                        EntityWarpedMosco.this.setAnimation(ANIMATION_SPIT);
                        if(upTicks % 30 == 0){
                            EntityWarpedMosco.this.heal(1);
                        }
                        final int tick = EntityWarpedMosco.this.getAnimationTick();
                        switch (tick) {
                            case 10, 20, 30, 40 -> EntityWarpedMosco.this.spit(target);
                        }
                    } else {
                        if (upTicks > 20 || EntityWarpedMosco.this.distanceTo(target) < 6) {
                            EntityWarpedMosco.this.getMoveControl().setWantedPosition(target.getX(), target.getY() + target.getEyeHeight() * 0.6F, target.getZ(), speedRush);
                        } else {
                            EntityWarpedMosco.this.getMoveControl().setWantedPosition(EntityWarpedMosco.this.getX(), EntityWarpedMosco.this.getY() + 3, EntityWarpedMosco.this.getZ(), 0.5F);
                        }
                    }
                } else {
                    EntityWarpedMosco.this.getNavigation().moveTo(EntityWarpedMosco.this.getTarget(), 1.25F);
                }
                if (EntityWarpedMosco.this.isFlying()) {
                    if (EntityWarpedMosco.this.distanceTo(target) < 4.3F) {
                        if (dashCooldown == 0 || target.onGround() || target.isInLava() || target.isInWater()) {
                            target.hurt(EntityWarpedMosco.this.damageSources().mobAttack(EntityWarpedMosco.this), 5F);
                            EntityWarpedMosco.this.knockbackRidiculous(target, 1.0F);
                            dashCooldown = 30;
                        }
                        final float groundHeight = EntityWarpedMosco.this.getMoscoGround(EntityWarpedMosco.this.blockPosition()).getY();
                        if (Math.abs(EntityWarpedMosco.this.getY() - groundHeight) < 3.0F && !EntityWarpedMosco.this.isOverLiquid()) {
                            EntityWarpedMosco.this.timeFlying += 300;
                            EntityWarpedMosco.this.setFlying(false);
                        }
                    }
                } else {
                    if (EntityWarpedMosco.this.distanceTo(target) < 4F && EntityWarpedMosco.this.getAnimation() == NO_ANIMATION) {
                        Animation animation = getRandomAttack(random);
                        if (animation == ANIMATION_SUCK && target.isPassenger()) {
                            animation = ANIMATION_SLAM;
                        }
                        EntityWarpedMosco.this.setAnimation(animation);
                    }
                }
            }
        }

public void tick() {
        LivingEntity target = entity.getTarget();
        if (target != null) {
            double dist = entity.distanceTo(target);
            float f = entity.getBbWidth() + target.getBbWidth();
            if (burrowCheckTime++ > 40 && entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                burrowCheckTime = 0;
                if (!burrowing) {
                    if (entity.onGround() && dist > f && (!entity.canReach(target.blockPosition()) || dist > 20 || entity.getRandom().nextInt(20) == 0)) {
                        burrowing = true;
                        evadeFor = 60 + entity.getRandom().nextInt(40);
                    }
                } else {
                    if (dist < f + 1 || entity.getRandom().nextInt(10) == 0) {
                        burrowing = false;
                        evadeFor = 0;
                    }
                }
            }
            if (evadeFor > 0) {
                evadeFor--;
                burrowing = true;
                this.entity.setDigging(true);
                if (this.entity.getNavigation().isDone()) {
                    Vec3 vec3 = generateEvadePosition(target.blockPosition());
                    if (vec3 != null) {
                        this.entity.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
                    }
                }
            } else if (burrowing) {
                if (this.entity.onGround()) {
                    this.entity.setDigging(true);
                }
                this.entity.getNavigation().moveTo(target, 2D);
                if (!this.entity.isInWall()) {
                    this.entity.setDigging(false);
                    this.burrowing = false;
                }
            } else {
                if (!this.entity.isInWall()) {
                    this.entity.setDigging(false);
                } else {
                    this.entity.setDigging(true);
                    this.entity.setDeltaMovement(this.entity.getDeltaMovement().add(0, 0.1D, 0));
                }
                this.entity.getNavigation().moveTo(target, 1.5F);
            }
            if (dist < f + 1.0F) {
                tryAnimation(CorrodentEntity.ANIMATION_BITE);
            }
            if (entity.getAnimation() == CorrodentEntity.ANIMATION_BITE) {
                this.entity.setDigging(false);
                if (entity.getAnimationTick() == 8) {
                    checkAndDealDamage(target, 1.5F);
                    if (entity.getRandom().nextBoolean()) {
                        evadeFor = 60 + entity.getRandom().nextInt(40);
                    }
                }
            }
        }
    }

