public void tick() {
        if (tossItemCooldown > 0) {
            tossItemCooldown--;
        }
        if (checkReachCooldown > 0) {
            checkReachCooldown--;
        }
        if (checkReachCooldown == 0) {
            checkReachCooldown = 100 + mob.getRandom().nextInt(40);
            if (mob.canTeleport() && !mob.canReach(cruciblePos)) {
                mob.setTeleportingToPos(Vec3.atCenterOf(cruciblePos.relative(Util.getRandom(ACMath.HORIZONTAL_DIRECTIONS, mob.getRandom()))));
                return;
            }
        }
        Vec3 center = Vec3.atCenterOf(cruciblePos);
        double distance = Vec3.atBottomCenterOf(cruciblePos).subtract(mob.position()).horizontalDistance();
        if (distance < 8.0D) {
            mob.getLookControl().setLookAt(center.x, center.y + 1.0F - Math.sin(cookTime * 0.2F) * 0.2F, center.z, 10.0F, (float) this.mob.getMaxHeadXRot());
        }
        if (distance > 2.5D) {
            mob.getNavigation().moveTo(cruciblePos.getX() + 0.5F, cruciblePos.getY(), cruciblePos.getZ() + 0.5F, 1);
        } else {
            if (distance < 1.25D) {
                mob.getMoveControl().strafe(0.1F, 0F);
            } else {
                mob.getMoveControl().strafe(0F, 0F);
            }
            mob.setLastCruciblePos(cruciblePos);
            mob.getNavigation().stop();
            if (mob.level().getBlockEntity(cruciblePos) instanceof ConversionCrucibleBlockEntity crucibleBlock && hasLineOfSightCrucible()) {
                mob.updateHeldItems = false;
                boolean flag = crucibleBlock.isWitchMode();
                crucibleBlock.setWitchModeDuration(10);
                if (!flag && crucibleBlock.isWitchMode()) {
                    crucibleBlock.rerollWantedItem();
                    crucibleBlock.markUpdated();
                }
                if (mob.areArmsVisuallyCrossed(1.0F) && mob.getAnimation() == IAnimatedEntity.NO_ANIMATION && !crucibleBlock.getWantItem().isEmpty() && crucibleBlock.getItemDisplayProgress(1.0F) >= 1.0F) {
                    mob.setItemInHand(InteractionHand.MAIN_HAND, crucibleBlock.getWantItem().copy());
                }
                if (!crucibleBlock.getWantItem().isEmpty() && crucibleBlock.getItemDisplayProgress(1.0F) >= 1.0F && tossItemCooldown == 0) {
                    if (tossedItem != null) {
                        tossedItem.discard();
                    }
                    if (mob.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        mob.setAnimation(mob.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                    } else if ((mob.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || mob.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && mob.getAnimationTick() == 4) {
                        mob.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                        Vec3 from = mob.getSwingArmPosition();
                        ItemStack stack = crucibleBlock.getWantItem().copy();
                        tossedItem = new ItemEntity(mob.level(), from.x, from.y, from.z, stack);
                        Vec3 delta = center.subtract(from).normalize().scale(0.13F).add(0, 0.4F, 0);
                        tossedItem.setNeverPickUp();
                        tossedItem.setDeltaMovement(delta);
                        tossedItem.checkDespawn();
                        mob.level().addFreshEntity(tossedItem);
                        tossItemCooldown = 50;
                    }
                }
                cookTime++;
            }
        }
    }

public PlayState leapingPredicate(AnimationEvent<PrehistoricLeaping> event) {
        AnimationController<PrehistoricLeaping> controller = event.getController();
        if (tryNextAnimation(controller)) {
            return PlayState.CONTINUE;
        }
        Optional<ActiveAnimationInfo> activeAnimation = getActiveAnimation(controller.getName());
        if (activeAnimation.isPresent() && tryForcedAnimation(event, activeAnimation.get())) {
            return PlayState.CONTINUE;
        }
        double animationSpeed = 1;
        PrehistoricLeaping entity = event.getAnimatable();

        if (entity.getLeapSystem().isAttackRiding()) {
            setAnimationSpeed(controller, 1, event.getAnimationTick());
            controller.transitionLengthTicks = 10;
            controller.setAnimation(new AnimationBuilder().loop(entity.getLeapAttackAnimationName()));
            return PlayState.CONTINUE;
        } else if (entity.getLeapSystem().hasLeapStarted() || entity.getLeapSystem().isLeapFlying()) {
            setAnimationSpeed(controller, 1, event.getAnimationTick());
            if (controller.getCurrentAnimation() != null && entity.getAnimations().get(AnimationCategory.FALL).hasAnimation(controller.getCurrentAnimation().animationName) && entity.isOnGround()) {
                controller.transitionLengthTicks = 0;
                controller.setAnimation(new AnimationBuilder().playOnce(entity.getLandAnimationName()));
            } else {
                controller.setAnimation(new AnimationBuilder().playOnce(entity.getLeapStartAnimationName()).loop(entity.getAnimation(AnimationCategory.FALL).animation.animationName));
            }
            return PlayState.CONTINUE;
        } else if (entity.getLeapSystem().isLanding()) {
            setAnimationSpeed(controller, 1, event.getAnimationTick());
            controller.transitionLengthTicks = 0;
            controller.setAnimation(new AnimationBuilder().playOnce(entity.getLandAnimationName()));
            return PlayState.CONTINUE;
        } else if (entity.isSleeping()) {
            addActiveAnimation(controller.getName(), AnimationCategory.SLEEP);
        } else if (entity.sitSystem.isSitting()) {
            addActiveAnimation(controller.getName(), AnimationCategory.SIT);
        } else if (entity.isClimbing()) {
            addActiveAnimation(controller.getName(), AnimationCategory.CLIMB);
            //TODO: Quick fix. Think of something better leater
            animationSpeed = 2;
        } else if (event.isMoving()) {
            if (entity.isInWater()) {
                ActiveAnimationInfo info = addActiveAnimation(controller.getName(), AnimationCategory.SWIM, true);
                if (info != null) {
                    additionalLogic.put(info, entity::isOnGround);
                }
            } else {
                animationSpeed = addMovementAnimation(event, true);
            }
        } else {
            if (entity.isInWater()) {
                addActiveAnimation(controller.getName(), AnimationCategory.SWIM);
            } else {
                addActiveAnimation(controller.getName(), AnimationCategory.IDLE);
            }
        }
        setAnimationSpeed(controller, animationSpeed, event.getAnimationTick());
        Optional<ActiveAnimationInfo> newAnimation = getActiveAnimation(controller.getName());
        if (newAnimation.isPresent()) {
            controller.transitionLengthTicks = newAnimation.get().transitionLength;
            controller.setAnimation(new AnimationBuilder().addAnimation(newAnimation.get().animationName, newAnimation.get().loop ? LOOP : PLAY_ONCE));
        }
        return PlayState.CONTINUE;
    }

