@Override
    public void tick() {
        super.tick();
        AnimationHandler.INSTANCE.updateAnimations(this);
        if (!this.level().isClientSide) {
            if (this.getAnimation() == NO_ANIMATION && (this.getTarget() == null || !this.getTarget().isAlive())) {
                if (this.getDeltaMovement().lengthSqr() < 0.03D && (getRandom().nextInt(500) == 0 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK))) {
                    this.setAnimation(ANIMATION_EAT_GRASS);
                } else if (getRandom().nextInt(200) == 0) {
                    this.setAnimation(ANIMATION_FLICK_EARS);
                }
            }
            if (this.getAnimation() == ANIMATION_EAT_GRASS && this.getAnimationTick() == 30 && level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK)) {
                BlockPos down = this.blockPosition().below();
                this.level().levelEvent(2001, down, Block.getId(Blocks.GRASS_BLOCK.defaultBlockState()));
                this.level().setBlock(down, Blocks.DIRT.defaultBlockState(), 2);
                this.heal(10);
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                this.setAngry(this.distanceTo(target) < 20);
                double dist = this.distanceTo(target);
                if (hasLineOfSight(target)) {
                    this.lookAt(target, 30, 30);
                    this.yBodyRot = this.getYRot();
                }
                if (dist < this.getBbWidth() + 3.0F) {
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(random.nextBoolean() ? ANIMATION_SLASH : ANIMATION_FLING);
                    }
                    if(dist < this.getBbWidth() + 1.5F && this.hasLineOfSight(target)){
                        if (this.getAnimation() == ANIMATION_FLING && this.getAnimationTick() >= 5 && this.getAnimationTick() <= 8) {
                            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                            if (target instanceof Raider) {
                                dmg = 10;
                            }
                            attackWithPotion(target, dmg);
                            launch(target, 0, 1F);
                            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                                if(!(entity instanceof Animal) && !trusts(entity.getUUID()) && entity != target){
                                    attackWithPotion(entity, Math.max(dmg - 5, 1));
                                    launch(entity, 0, 0.5F);
                                }
                            }
                        }
                        if (this.getAnimation() == ANIMATION_SLASH && (this.getAnimationTick() >= 9 && this.getAnimationTick() <= 11 || this.getAnimationTick() >= 19 && this.getAnimationTick() <= 21)) {
                            float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                            if (target instanceof Raider) {
                                dmg = 10;
                            }
                            attackWithPotion(target, dmg);
                            launch(target, this.getAnimationTick() <= 15 ? -90 : 90, 1F);
                            for (LivingEntity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(1.0D))) {
                                if(!(entity instanceof Animal) && !trusts(entity.getUUID()) && entity != target){
                                    attackWithPotion(entity, Math.max(dmg - 5, 1));
                                    launch(entity, this.getAnimationTick() <= 15 ? -90 : 90, 0.5F);
                                }
                            }
                        }
                    }
                }
            }else{
                this.setAngry(false);
            }
        }
    }

public void tick() {
        super.tick();
        prevJostleProgress = jostleProgress;
        prevJostleAngle = this.getJostleAngle();

        if (this.isJostling()) {
            if (jostleProgress < 5F)
                jostleProgress++;
        } else {
            if (jostleProgress > 0F)
                jostleProgress--;
        }

        if (jostleCooldown > 0) {
            jostleCooldown--;
        }
        if (!this.level().isClientSide && this.getAnimation() == NO_ANIMATION && getRandom().nextInt(120) == 0 && (this.getTarget() == null || !this.getTarget().isAlive()) && !this.isJostling() && this.getJostlingPartnerUUID() == null) {
            if (level().getBlockState(this.blockPosition().below()).is(Blocks.GRASS_BLOCK) && getRandom().nextInt(3) == 0) {
                this.setAnimation(ANIMATION_EAT_GRASS);
            }
        }
        if (timeUntilAntlerDrop > 0) {
            timeUntilAntlerDrop--;
        }
        if (timeUntilAntlerDrop == 0) {
            if (this.isAntlered()) {
                this.setAntlered(false);
                this.spawnAtLocation(new ItemStack(AMItemRegistry.MOOSE_ANTLER.get()));
                timeUntilAntlerDrop = 2 * DAY + this.random.nextInt(3) * DAY;
            } else {
                this.setAntlered(true);
                timeUntilAntlerDrop = 7 * DAY + this.random.nextInt(3) * DAY;
            }
        }
        if (this.getTarget() != null && this.getTarget().isAlive()) {
            if (this.isJostling()) {
                this.setJostling(false);
            }
            if (!this.level().isClientSide && this.getAnimation() == ANIMATION_ATTACK && this.getAnimationTick() == 8) {
                float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                if (!isAntlered()) {
                    dmg = 3;
                }
                if (this.getTarget() instanceof Wolf || this.getTarget() instanceof EntityOrca) {
                    dmg = 2;
                }
                getTarget().knockback(1F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                this.getTarget().hurt(this.damageSources().mobAttack(this), dmg);
            }
        }
        if(snowTimer > 0){
            snowTimer--;
        }
        if (snowTimer == 0 && !this.level().isClientSide) {
            snowTimer = 200 + random.nextInt(400);
            if(this.isSnowy()){
                if(!permSnow){
                    if (!this.level().isClientSide || this.getRemainingFireTicks() > 0 || this.isInWaterOrBubble() || !EntityGrizzlyBear.isSnowingAt(level(), this.blockPosition().above())) {
                        this.setSnowy(false);
                    }
                }
            }else{
                if (!this.level().isClientSide && EntityGrizzlyBear.isSnowingAt(level(), this.blockPosition())) {
                    this.setSnowy(true);
                }
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
	public void onUpdate() {
		if (!this.world.isRemote && this.world.getDifficulty() == EnumDifficulty.PEACEFUL) {
			this.isDead = true;
		}

		if(this.attackCooldown > 0) {
			this.attackCooldown--;
		}

		this.prevSquishFactor = this.squishFactor;
		this.squishFactor += (this.squishAmount - this.squishFactor) * 0.5F;

		if (!this.world.isRemote) {
			if (getIsPlayerNearby(7, 3, 7, 7) || getAttackTarget() != null || this.world.rand.nextInt(2200) == 0) {
				if (!this.isActive()) {
					this.setActive(true);
					this.motionY += 0.6;
				}
			}

			if(this.isActive()) {
				if(this.getEntityAttribute(SLUDGE_TRAIL).getAttributeValue() == 1 && this.world.getClosestPlayer(this.posX, this.posY, this.posZ, 16, false) != null) {
					BlockPos position = new BlockPos(this.posX, this.posY, this.posZ);;
					if (this.world.isAirBlock(position)) {
						this.createTrail(position);
					}
				}

				if (this.getAttackTarget() == null && this.onGround && this.world.rand.nextInt(350) == 0 && !this.isInWater() && this.canHideIn(this.world.getBlockState(this.getPosition().down()))) {
					this.setActive(false);
				}
			} else if(this.isInWater() || !this.onGround) {
				this.setActive(true);
			} else {
				this.motionX = 0;
				this.motionY -= 0.1;
				this.motionZ = 0;
			}
		}

		super.onUpdate();

		if(this.isActive()) {
			this.setNormalSize();
		} else {
			this.setSmallSize();
		}

		if (this.onGround && !this.wasOnGround) {
			//Particles
			this.squishAmount = -0.5F;
		} else if (!this.onGround && this.wasOnGround) {
			this.squishAmount = 1.0F;
		}

		this.wasOnGround = this.onGround;
		this.alterSquishAmount();

		//Update animation
		if (this.world.isRemote) {
			this.scale.updateTimer();
			if (this.isActive()) {
				this.scale.increaseTimer();
			} else {
				this.scale.decreaseTimer();
			}
		}
	}

public void tick() {
        LivingEntity livingentity = this.entity.getTarget();
        if(crossbowCooldown > 0){
            crossbowCooldown--;
        }
        if (livingentity != null) {
            double d0 = this.entity.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
            boolean flag = this.entity.hasLineOfSight(livingentity);
            boolean flag1 = this.seeTime > 0;
            if (flag != flag1) {
                this.seeTime = 0;
            }

            if (flag) {
                ++this.seeTime;
            } else {
                --this.seeTime;
            }

            if (!(d0 > (double)this.maxAttackDistance) && this.seeTime >= 20) {
                this.entity.getNavigation().stop();
                ++this.strafingTime;
            } else {
                this.entity.getNavigation().moveTo(livingentity, this.moveSpeedAmp);
                this.strafingTime = -1;
            }

            if (this.strafingTime >= 20) {
                if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                    this.strafingClockwise = !this.strafingClockwise;
                }

                if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                    this.strafingBackwards = !this.strafingBackwards;
                }

                this.strafingTime = 0;
            }

            if (this.strafingTime > -1) {
                if (d0 > (double)(this.maxAttackDistance * 0.75F)) {
                    this.strafingBackwards = false;
                } else if (d0 < (double)(this.maxAttackDistance * 0.25F)) {
                    this.strafingBackwards = true;
                }

                this.entity.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
                this.entity.lookAt(livingentity, 30.0F, 30.0F);
            } else {
                this.entity.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
            }
            boolean crossbow = this.entity.getMainHandItem().getItem() instanceof CrossbowItem;
            if (this.entity.isUsingItem() || crossbow) {
                if (!flag && this.seeTime < -60) {
                    this.entity.stopUsingItem();
                } else if (flag) {
                    int i = this.entity.getTicksUsingItem();
                    if (i >= 20 || crossbow && crossbowCooldown == 0) {
                        this.entity.stopUsingItem();
                        this.entity.performRangedAttack(livingentity, BowItem.getPowerForTime(i));
                        this.attackTime = this.attackCooldown;
                        crossbowCooldown = 20;
                    }
                }
            } else if (--this.attackTime <= 0 && this.seeTime >= -60) {
                this.entity.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.entity, Items.BOW));
            }

        }
    }

public void tick() {
		LivingEntity target = shooter.getTarget();

		if (target != null) {
			double distanceToTarget = shooter.distanceToSqr(target.getX(), target.getY(), target.getZ());
			boolean canSeeTarget = shooter.getSensing().canSee(target);


			if (canSeeTarget != seeTime > 0)
				seeTime = 0;

			if (canSeeTarget) {
				++seeTime;
			}
			else {
				--seeTime;
			}

			if (!(distanceToTarget > maxAttackDistance) && seeTime >= 20) {
				shooter.getNavigation().stop();
				++strafingTime;
			}
			else {
				shooter.getNavigation().moveTo(target, moveSpeedAmp);
				strafingTime = -1;
			}

			if (strafingTime >= 20) {
				if (shooter.getRandom().nextFloat() < 0.3D)
					strafingClockwise = !strafingClockwise;

				if (shooter.getRandom().nextFloat() < 0.3D)
					strafingBackwards = !strafingBackwards;

				strafingTime = 0;
			}

			if (strafingTime > -1) {
				if (distanceToTarget > maxAttackDistance * 0.75F) {
					strafingBackwards = false;
				}
				else if (distanceToTarget < maxAttackDistance * 0.25F) {
					strafingBackwards = true;
				}

				shooter.getMoveControl().strafe(strafingBackwards ? -0.5F : 0.5F, strafingClockwise ? 0.5F : -0.5F);
				shooter.lookAt(target, 30.0F, 30.0F);
			}
			else {
				shooter.getLookControl().setLookAt(target, 30.0F, 30.0F);
			}

			if (shooter.isUsingItem()) {
				if (!canSeeTarget && seeTime < -60) {
					shooter.stopUsingItem();
				}
				else if (canSeeTarget) {
					int maxItemUseTime = shooter.getTicksUsingItem();

					if (maxItemUseTime >= 20) {
						shooter.stopUsingItem();
						shooter.performRangedAttack(target, BowItem.getPowerForTime(maxItemUseTime));
						attackTime = attackCooldown;
					}
				}
			}
			else if (--attackTime <= 0 && seeTime >= -60) {
				shooter.startUsingItem(ProjectileHelper.getWeaponHoldingHand(shooter, Items.BOW));
			}
		}
	}

