        rleg.rotationPointY += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount, walkSpeed, -0.5F, 5F, false)) - bodyBob;
        rleg.rotationPointZ += ACMath.walkValue(limbSwing, limbSwingAmount, walkSpeed, -0.5F, 1F, false);
        if (entity.getAnimation() != GrottoceratopsEntity.ANIMATION_MELEE_TAIL_1 && entity.getAnimation() != GrottoceratopsEntity.ANIMATION_MELEE_TAIL_2) {
            float yawAmount = netHeadYaw / 57.295776F;
            float pitchAmount = headPitch / 57.295776F;
            this.neck.rotateAngleX += pitchAmount * 0.1F;
            this.head.rotateAngleX += pitchAmount * 0.2F;
            this.neck.rotateAngleY += yawAmount * 0.3F;
            this.head.rotateAngleY += yawAmount * 0.4F;
        }
        neck.rotationPointY += ACMath.walkValue(ageInTicks, danceAmount, danceSpeed * 1.5F, 1F, 1.5F, false);
        neck.rotationPointX += ACMath.walkValue(ageInTicks, danceAmount, danceSpeed * 1.5F, 0F, 3F, false);
        this.swing(body, danceSpeed, 0.1F, false, 1, 0, ageInTicks, danceAmount);
        this.swing(tail, danceSpeed, 0.5F, false, 1, 0, ageInTicks, danceAmount);
        this.swing(tail2, danceSpeed, 0.5F, false, 1, 0, ageInTicks, danceAmount);

    }

@Override
    public void setupAnim(LicowitchEntity entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
        this.resetToDefaultPose();
        animate(entity);
        float partialTicks = ageInTicks - entity.tickCount;
        float unfurlArmsProgress = entity.getArmsUncrossedProgress(partialTicks);
        float teleportingProgress = Math.min(entity.getTeleportingProgress(partialTicks) * 5, 1F) * unfurlArmsProgress;
        boolean crossedArms = entity.areArmsVisuallyCrossed(partialTicks);
        float walkSpeed = 0.5F;
        float walkDegree = 0.8F;
        progressPositionPrev(dress, limbSwingAmount, 0, -0.5F, -3, 1F);
        progressRotationPrev(dress, limbSwingAmount, (float) Math.toRadians(10), 0, 0, 1F);
        progressRotationPrev(left_Arm, unfurlArmsProgress, (float) Math.toRadians(40), (float) Math.toRadians(20), (float) Math.toRadians(-20), 1F);
        progressRotationPrev(right_Arm, unfurlArmsProgress, (float) Math.toRadians(40), (float) Math.toRadians(-20), (float) Math.toRadians(20), 1F);
        progressPositionPrev(left_Arm, teleportingProgress, 0, -2, 0, 1F);
        progressPositionPrev(right_Arm, teleportingProgress, 0, -2, 0, 1F);
        progressRotationPrev(head, teleportingProgress, (float) Math.toRadians(-20), 0, 0, 1F);
        progressRotationPrev(left_Arm, teleportingProgress, (float) Math.toRadians(-160), (float) Math.toRadians(-40), (float) Math.toRadians(40), 1F);
        progressRotationPrev(right_Arm, teleportingProgress, (float) Math.toRadians(-160), (float) Math.toRadians(40), (float) Math.toRadians(-40), 1F);
        this.flap(nose, 0.035F, 0.08F, false, -1F, 0.0F, ageInTicks, 1F);
        this.walk(nose, 0.035F, 0.08F, false, 0F, -0.08F, ageInTicks, 1F);
        this.flap(left_Arm, 0.1F, 0.1F, false, 0F, -0.15F, ageInTicks, unfurlArmsProgress);
        this.flap(right_Arm, 0.1F, 0.1F, true, 0F, -0.15F, ageInTicks, unfurlArmsProgress);

        this.armsCrossed.showModel = crossedArms;
        this.left_Hand.showModel = !crossedArms;
        this.right_Hand.showModel = !crossedArms;
        this.head.rotateAngleY += netHeadYaw * ((float)Math.PI / 180F);
        this.head.rotateAngleX += headPitch * ((float)Math.PI / 180F);

        this.walk(left_Leg, walkSpeed, walkDegree, false, 1F, 0F, limbSwing, limbSwingAmount);
        this.walk(right_Leg, walkSpeed, walkDegree, true, 1F, 0F, limbSwing, limbSwingAmount);
        this.walk(left_Arm, walkSpeed, walkDegree, true, 0F, 0.3F, limbSwing, limbSwingAmount * unfurlArmsProgress);
        this.walk(right_Arm, walkSpeed, walkDegree, false, 0F, -0.3F, limbSwing, limbSwingAmount * unfurlArmsProgress);
        this.swing(dress, walkSpeed, walkDegree * 0.1F, true, 1F, 0F, limbSwing, limbSwingAmount);
        this.swing(body, walkSpeed, walkDegree * 0.05F, true, 2F, 0F, limbSwing, limbSwingAmount);
        this.swing(head, walkSpeed, walkDegree * 0.05F, false, 1F, 0F, limbSwing, limbSwingAmount);

        this.walk(left_Arm, 0.5F, 0.5F, true, 0F, 0.0F, ageInTicks, teleportingProgress);
        this.walk(right_Arm, 0.5F, 0.5F, false, 0F, 0.0F, ageInTicks, teleportingProgress);
        this.body.rotationPointY += teleportingProgress * (-5 - ACMath.walkValue(ageInTicks, 1F, 0.25F, 0F, 4, false));

        float f = -Math.min(left_Leg.rotateAngleX, right_Leg.rotateAngleX);
        this.dress.rotationPointZ -= f * 1.5F;
        this.dress.setScale(1F, 1F, 1F + limbSwingAmount * 0.33F);
        float runWalkBob = -Math.abs(ACMath.walkValue(limbSwing, limbSwingAmount, walkSpeed, 1F, 1F, false));
        this.body.rotationPointY += runWalkBob;
        this.left_Leg.rotationPointY -= runWalkBob;
        this.right_Leg.rotationPointY -= runWalkBob;
        this.dress.rotationPointY -= runWalkBob;
        if (entity.getAnimation() == LicowitchEntity.ANIMATION_EAT) {
            float animationIntensity = ACMath.cullAnimationTick(entity.getAnimationTick(), 4, LicowitchEntity.ANIMATION_EAT, partialTicks, 0);
            this.walk(head, 0.75F, 0.1F, false, 0F, 0.2F, ageInTicks, animationIntensity);
            this.walk(arms, 0.75F, 0.3F, true, 1F, 0.2F, ageInTicks, animationIntensity);
        }
        if (entity.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0) {
            float animationIntensity = ACMath.cullAnimationTick(entity.getAnimationTick(), 2, LicowitchEntity.ANIMATION_SPELL_0, partialTicks, 18, 25);
            AdvancedModelBox arm = getArmCube(entity);
            arm.rotationPointZ += animationIntensity * Math.sin(ageInTicks * 2F);
            this.walk(arm, 1F, 0.1F, false, 0F, -0.1F, ageInTicks, animationIntensity);
        }
        if (entity.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1) {
            float animationIntensity1 = ACMath.cullAnimationTick(entity.getAnimationTick(), 3, LicowitchEntity.ANIMATION_SPELL_1, partialTicks, 0, 40);
            float animationIntensity2 = ACMath.cullAnimationTick(entity.getAnimationTick(), 3, LicowitchEntity.ANIMATION_SPELL_1, partialTicks, 25, 25);
            this.walk(left_Leg, 0.3F, 0.2F, false, 0F, 0.0F, ageInTicks, animationIntensity1);
            this.walk(right_Leg, 0.3F, 0.2F, true, 0F, 0.0F, ageInTicks, animationIntensity1);
            this.walk(body, 0.2F, 0.1F, true, 1F, 0.0F, ageInTicks, animationIntensity1);
            this.bob(body, 0.4F, 2, false, ageInTicks, animationIntensity1);
            AdvancedModelBox arm = getArmCube(entity);
            arm.rotationPointZ += animationIntensity2 * Math.sin(ageInTicks * 2F);
            this.walk(arm, 1F, 0.1F, false, 0F, -0.1F, ageInTicks, animationIntensity2);
        }
    }

@Override
    public void aiStep() {
        super.aiStep();
        LivingEntity attackTarget = this.getTarget();
        if (visibleTicks > 0) {
            visibleTicks--;
        } else {
            visibleTicks = 0;
        }
        if (attackTarget != null) {
            visibleTicks = 100;
        }
        if (this.canSeeSky()) {
            this.daylightTicks++;
        } else {
            this.daylightTicks = 0;
        }
        boolean holding = getHeldEntity() != null;
        boolean hiding = isHiding() && !this.hasCustomer();
        if ((holding || this.isOnResin() || attackTarget != null) || visibleTicks > 0) {
            this.setHiding(false);
        }
        if (holding && holdingProgress < 20.0F) {
            holdingProgress += 1.0F;
        } else if (!holding && holdingProgress > 0.0F) {
            holdingProgress -= 1.0F;
        }
        if (hiding) {
            this.setYRot(this.yRotO);
        }
        if (hiding && hidingProgress < 20.0F) {
            hidingProgress += 1.0F;
        } else if (!hiding && hidingProgress > 0.0F) {
            hidingProgress -= 1.0F;
        }
        if (this.getHeldEntity() != null) {
            this.setAnimation(ANIMATION_NIBBLE);
            if (this.getAnimationTick() == 5) {
                this.playBiteSound();
                this.getHeldEntity().hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue() / 6));
            }
        }
        if (this.getAnimation() == ANIMATION_GRAB && attackTarget != null && this.getAnimationTick() == 7) {
            this.playStingSound();
            if (this.getAttackBounds().intersects(attackTarget.getBoundingBox())) {
                attackTarget.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue() / 2));
                //Make sure it doesn't grab a dead dragon
                if (attackTarget instanceof EntityDragonBase) {
                    if (!((EntityDragonBase) attackTarget).isMobDead()) {
                        attackTarget.startRiding(this);
                    }
                } else {
                    attackTarget.startRiding(this);
                }
            }
        }
        if (this.getAnimation() == ANIMATION_SLASH && attackTarget != null && this.getAnimationTick() % 5 == 0 && this.getAnimationTick() <= 20) {
            this.playBiteSound();
            if (this.getAttackBounds().intersects(attackTarget.getBoundingBox())) {
                attackTarget.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()) / 4);
            }
        }
        if (this.getAnimation() == ANIMATION_STING && (this.getAnimationTick() == 0 || this.getAnimationTick() == 10)) {
            this.playStingSound();
        }
        if (this.getAnimation() == ANIMATION_STING && attackTarget != null && (this.getAnimationTick() == 6 || this.getAnimationTick() == 16)) {
            double dist = this.distanceToSqr(attackTarget);
            if (dist < 18) {
                attackTarget.hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
                attackTarget.addEffect(new MobEffectInstance(MobEffects.POISON, 100, 3));
            }
        }
    }

public void tick() {
        super.tick();
        prevLeftArmRot = leftArmRot;
        prevRightArmRot = rightArmRot;
        prevRunProgress = runProgress;
        float armSpinSpeed = getArmSpinSpeed();
        if (armSpinSpeed > 0 && this.isAlive()) {
            if(swingSoundTimer-- < 0){
                swingSoundTimer = 5 + level().random.nextInt(10);
                this.playSound(ACSoundRegistry.CANIAC_SWING.get());
            }
            if(this.isLeftHanded()){
                leftArmRot += armSpinSpeed;
                if(leftArmRot % 360 > 180){
                    spinSecondArm = true;
                }
                if(spinSecondArm){
                    rightArmRot += armSpinSpeed;
                }
            }else{
                rightArmRot += armSpinSpeed;
                if(rightArmRot % 360 > 180){
                    spinSecondArm = true;
                }
                if(spinSecondArm){
                    leftArmRot += armSpinSpeed;
                }
            }
            if(level().isClientSide){
                if(Mth.wrapDegrees(leftArmRot) % 180 > 70){
                    spawnArmSwingParticles(true);
                }
                if(Mth.wrapDegrees(rightArmRot) % 180 > 70){
                    spawnArmSwingParticles(false);
                }
            }else{
                if(Mth.wrapDegrees(leftArmRot) % 180 > 75){
                    hurtMobsFromArmSwing(true, (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue(), 0.1F);
                }
                if(Mth.wrapDegrees(rightArmRot) % 180 > 75){
                    hurtMobsFromArmSwing(false, (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue(), 0.1F);
                }
            }
        }else{
            spinSecondArm = false;
            float f = this.getAnimation() == ANIMATION_LUNGE ? 40 : 15;
            if(Mth.wrapDegrees(leftArmRot) != 0){
                leftArmRot = Mth.approachDegrees(leftArmRot, 0, f);
            }
            if(Mth.wrapDegrees(rightArmRot) != 0){
                rightArmRot = Mth.approachDegrees(rightArmRot, 0, f);
            }
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.4D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25D);
        }
        if (isRunning() && runProgress < 5F) {
            runProgress++;
        }
        if (!isRunning() && runProgress > 0F) {
            runProgress--;
        }
        if(level().isClientSide){
            spawnPossessedParticles(getRandomX(0.5D), getRandomY(), getRandomZ(0.5D), this.level());
        }
        if(this.getAnimation() == ANIMATION_LUNGE && this.getAnimationTick() == 10){
            this.playSound(ACSoundRegistry.CANIAC_ATTACK.get());
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        if (peppermintCooldown > 0) {
            peppermintCooldown--;
        }
        if (hexCooldown > 0) {
            hexCooldown--;
        }
        if (potionCooldown > 0) {
            potionCooldown--;
        }
        if (checkReachCooldown > 0) {
            checkReachCooldown--;
        }
        LivingEntity target = licowitch.getTarget();
        if(duration > 200 && checkReachCooldown == 0 && target != null){
            checkReachCooldown = 100 + licowitch.getRandom().nextInt(40);
            if(licowitch.canTeleport() && !licowitch.canReach(target.blockPosition())){
                licowitch.setTeleportingToPos(Vec3.atBottomCenterOf(target.blockPosition()));
                return;
            }
        }
        if (target != null && target.isAlive() && licowitch.getTeleportingToPos() == null) {
            double distance = licowitch.distanceTo(target);
            double distanceXZ = Mth.sqrt((float) licowitch.distanceToSqr(target.getX(), licowitch.getY(), target.getZ()));
            double attackDistance = licowitch.getBbWidth() + target.getBbWidth() + 5;
            licowitch.lookAt(target, 30.0F, 30.0F);
            if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT || enqueuedAttackType == 0 && distance < attackDistance - 1 || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && distanceXZ < 6.0F) {
                licowitch.getMoveControl().strafe(-4, 0.0F);
                licowitch.getNavigation().stop();
            } else if (distance > attackDistance || !this.licowitch.hasLineOfSight(target)) {
                this.licowitch.getNavigation().moveTo(target, 1.0D);
            }
            if (this.licowitch.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                if (enqueuedAttackType == 0) {
                    if (this.licowitch.hasLineOfSight(target)) {
                        if (peppermintCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                            enqueuedAttackType = 1;
                            peppermintCooldown = 80;
                        } else if (hexCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                            enqueuedAttackType = 2;
                            hexCooldown = 200;
                        } else if (potionCooldown <= 0 && distance < 10.0D && !target.hasEffect(MobEffects.HUNGER)) {
                            enqueuedAttackType = 3;
                            licowitch.updateHeldItems = false;
                            licowitch.setItemInHand(InteractionHand.MAIN_HAND, LicowitchEntity.hungerPotion.copy());
                            potionCooldown = 100;
                        }
                    }
                } else {
                    if (enqueuedAttackType == 1 && distance < 10.0D) {
                        this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_0);
                    }
                    if ((enqueuedAttackType == 2 || enqueuedAttackType == 4) && distance < 7.0D) {
                        this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_1);
                    }
                    if (enqueuedAttackType == 3 && distance < 10.0D) {
                        this.licowitch.setAnimation(licowitch.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                    }
                }
            }
            if (enqueuedAttackType == 1 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0 && licowitch.getAnimationTick() == 18) {
                peppermintAttack(target);
                enqueuedAttackType = 0;
            }
            if (enqueuedAttackType == 2 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && licowitch.getAnimationTick() == 36) {
                hexAttack(target);
                enqueuedAttackType = 0;
            }
            if (enqueuedAttackType == 3 && (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && licowitch.getAnimationTick() == 6) {
                potionAttack(target);
                licowitch.updateHeldItems = true;
                enqueuedAttackType = 0;
            }
        }
        duration++;
    }

