@Override
    public void tick() {
        super.tick();
        if (!level().isClientSide) {
            Entity e = getVehicle();
            if (isMinecart(e)) {
                AbstractMinecart minecart = (AbstractMinecart) e;
                reader.accept(minecart);
                boolean onRail = isBlockRail(level().getBlockState(e.blockPosition()).getBlock()) || isBlockRail(findGroundBelow(level(), e.blockPosition()).getBlock());
                if ((e.onGround() && !level().getBlockState(e.blockPosition().below()).isAir() && !level().getBlockState(e.blockPosition()).isAir())
                        && ((timeSinceMinecart > 3 && e.getDeltaMovement().length() < 0.001) || !onRail)) {
                    minecart.ejectPassengers();
                    timeSinceMinecart = 0;
                }
                else if (onRail) {
                    if (minecart.getDeltaMovement().length() < 0.001) minecart.setDeltaMovement(minecart.getForward().scale(2.7));
                    else minecart.setDeltaMovement(minecart.getDeltaMovement().normalize().scale(2.7));
                    timeSinceMinecart++;
                }
            }
        }
//        if (ticksExisted == 1) System.out.println("Grottle at " + getPosition());

        //Sparkle particles
        if (level().isClientSide && isAlive() && random.nextInt(15) == 0) {
            double x = getX() + 0.5f * (2 * random.nextFloat() - 1f);
            double y = getY() + 0.8f + 0.3f * (2 * random.nextFloat() - 1f);
            double z = getZ() + 0.5f * (2 * random.nextFloat() - 1f);
            if (isBlackPinkInYourArea()) {
                level().addParticle(ParticleTypes.NOTE, x, y, z, random.nextDouble() / 2, 0, 0);
            } else {
                level().addParticle(ParticleHandler.SPARKLE.get(), x, y, z, 0, 0, 0);
            }
        }

        //Footstep Sounds
        float moveX = (float) (getX() - xo);
        float moveZ = (float) (getZ() - zo);
        float speed = Mth.sqrt(moveX * moveX + moveZ * moveZ);
        if (frame % 6 == 0 && speed > 0.05) {
            playSound(MMSounds.ENTITY_GROTTOL_STEP.get(), 1F, 1.8f);
        }

        if (timeSinceFlee < 50) {
            timeSinceFlee++;
        } else {
            fleeTime = 0;
        }

        if (timeSinceDeflectSound < 5) timeSinceDeflectSound++;

        // AI Task
        if (!level().isClientSide && fleeTime >= 55 && getAnimation() == NO_ANIMATION && !isNoAi() && !hasEffect(EffectHandler.FROZEN)) {
            BlockState blockBeneath = level().getBlockState(blockPosition().below());
            if (isBlockDiggable(blockBeneath)) {
                AnimationHandler.INSTANCE.sendAnimationMessage(this, BURROW_ANIMATION);
            }
        }
        if (!level().isClientSide && getAnimation() == BURROW_ANIMATION) {
            if (getAnimationTick() % 4 == 3) {
                playSound(MMSounds.ENTITY_GROTTOL_BURROW.get(), 1, 0.8f + random.nextFloat() * 0.4f);
                BlockState blockBeneath = level().getBlockState(blockPosition().below());
                if (isBlockDiggable(blockBeneath)) {
                    Vec3 pos = new Vec3(0.5D, 0.05D, 0.0D).yRot((float) Math.toRadians(-yBodyRot - 90));
                    if (level() instanceof ServerLevel) {
                        ((ServerLevel) level()).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, blockBeneath),
                                getX() + pos.x, getY() + pos.y, getZ() + pos.z,
                                8,
                                0.25D, 0.025D, 0.25D,
                                0.1D
                        );
                    }
                }
            }
        }
    }

public void aiStep() {
        if (!this.level.isClientSide) {
            if (this.tickCount % 1000 == 0) {
                this.addHunger(-2);
                if (!this.isStarving()) {
                    this.heal(2.0F);
                }
            }
            // Bearserk
            if (this.getHealth() < this.getMaxHealth() / 2) {
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 1200, 0, true, true));
                this.forceSleep = -1200;
            }

            this.setAngry(this.getTarget() != null);
            if (this.getAnimation() == NO_ANIMATION && this.getTarget() == null && !this.isSleeping()) {
                if (this.getCommandInt() == 0) {
                    int i = this.random.nextInt(3000);
                    if (i == 0 && !this.isInWater() && this.isNotMoving() && this.canMove() && this.isActive()) {
                        this.getNavigation().stop();
                        this.setSitting(true);
                    }
                    if ((i == 1 || this.isInWater()) && this.isSitting() && this.getCommandInt() < 2) {
                        this.setSitting(false);
                    }
                    if (i == 2 && this.canMove() && !this.isInWater() && !this.isBaby()) {
                        if (!this.isSitting()) {
                            this.setAnimation(IDLE_STAND);
                        }
                    }
                    if (i > 2980 && !this.isInWater() && !this.isBaby()) {
                        this.setAnimation(IDLE_TALK);
                    }
                }
            }
        }
        if (this.tickCount % 100 == 0 && this.getTarget() != null && this.getAnimation() == NO_ANIMATION) {
            this.setAnimation(ANIMATION_ROAR);
        }
        if (this.getAnimation() != NO_ANIMATION) {
            if (this.getAnimation() == ATTACK_BITE && this.getAnimationTick() == 1) {
                this.playSound(ModSounds.ENTITY_ATTACK_BITE, 1.5F, 0.8F);
            }
            if (this.getAnimation() == ATTACK_SWIPE && this.getAnimationTick() == 8) {
                this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1.5F, 0.8F);
            }
            if (this.getAnimation() == ATTACK_POUND && this.getAnimationTick() == 10) {
                this.getMoveControl().strafe(2F, 0);
                this.playSound(SoundEvents.PLAYER_ATTACK_SWEEP, 1.5F, 0.8F);
            }
            if (this.getAnimation() == ATTACK_MAUL) {
                if (this.getAnimationTick() == 10) {
                    this.playSound(this.getThreatSound(), this.getSoundVolume(), this.getVoicePitch());
                }
                if (this.getAnimationTick() == 20) {
                    this.playSound(SoundEvents.PLAYER_SMALL_FALL, 1.5F, 0.8F);
                    if (!this.level.isClientSide()) {
                        BlockPos pos = this.blockPosition().below();
                        BlockState state = this.level.getBlockState(pos);
                        if (!state.addLandingEffects((ServerLevel) this.level, pos, state, this, 40))
                            ((ServerLevel)this.level).sendParticles(new BlockParticleOption(ParticleTypes.BLOCK, state), this.getX(), this.getY(), this.getZ(), 40, 0.0D, 0.0D, 0.0D, 99.3F);
                    }
                }
            }
            if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 7) {
                this.playSound(this.getThreatSound(), this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.getAnimation() == IDLE_TALK && this.getAnimationTick() == 1) {
                this.playSound(ModSounds.ENTITY_BEAR_AMBIENT, this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.getAnimation() == ANIMATION_EAT && (this.getAnimationTick() == 10 || this.getAnimationTick() == 20 || this.getAnimationTick() == 30)) {
                this.playSound(SoundEvents.HORSE_EAT, 1.5F, 0.8F);
            }
        }
        super.aiStep();
    }

@Override
    public void tick() {
        super.tick();
        this.prevRaiseArmsAmount = raiseArmsAmount;
        this.prevLeftArmAmount = raiseLeftArmAmount;
        this.prevShootTongueAmount = shootTongueAmount;
        this.prevLastTongueDistance = lastTongueDistance;
        if (this.getAnimation() == ANIMATION_SMASH && raiseArmsAmount < 5F) {
            raiseArmsAmount++;
        }
        if (this.getAnimation() != ANIMATION_SMASH && raiseArmsAmount > 0F) {
            raiseArmsAmount--;
        }
        if (this.raisingLeftArm() && raiseLeftArmAmount < 5F) {
            raiseLeftArmAmount++;
        }
        if (!this.raisingLeftArm() && raiseLeftArmAmount > 0F) {
            raiseLeftArmAmount--;
        }
        if (this.getLickTicks() > 0 && shootTongueAmount < 10F) {
            shootTongueAmount++;
        }
        if (this.getLickTicks() <= 0 && shootTongueAmount > 0F) {
            shootTongueAmount--;
        }
        if (!level().isClientSide && this.hasBarrel()) {
            if (this.getAnimation() == ANIMATION_DRINK_BARREL && this.getAnimationTick() >= 60) {
                this.setHasBarrel(false);
                this.heal(10);
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_BOOST, 400, 0));
                this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 400, 0));
                this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 400, 4));
            }
            if (this.getAnimation() == ANIMATION_THROW_BARREL && this.getAnimationTick() >= 15) {
                LivingEntity attackTarget = this.getTarget();
                if (attackTarget != null && attackTarget.isAlive()) {
                    this.setHasBarrel(false);
                    Vec3 hand = new Vec3(0.65F, -0.3F, 0.9F).xRot(-this.getXRot() * ((float) Math.PI / 180F)).yRot(-this.getYHeadRot() * ((float) Math.PI / 180F));
                    Vec3 handOnBody = this.getEyePosition().add(hand);
                    ThrownWasteDrumEntity wasteDrumEntity = ACEntityRegistry.THROWN_WASTE_DRUM.get().create(level());
                    wasteDrumEntity.setPos(handOnBody);
                    Vec3 toss = attackTarget.getEyePosition().subtract(handOnBody).multiply(0.35F, 0, 0.35F).add(0, 0.4, 0);
                    wasteDrumEntity.setYRot(-((float) Mth.atan2(toss.x, toss.z)) * 180.0F / (float) Math.PI);
                    level().addFreshEntity(wasteDrumEntity);
                    wasteDrumEntity.setDeltaMovement(toss.normalize().scale(attackTarget.distanceTo(this) * 0.2F));
                }
            }
        }
        Entity tongueTarget = this.getTongueTarget();
        if (level().isClientSide) {
            if (tongueTarget != null && tongueTarget.isAlive()) {
                lastTongueDistance = this.distanceTo(tongueTarget) - 0.5F;
            }
        } else {
            LivingEntity attackTarget = this.getTarget();
            if (this.getLickTicks() > 0) {
                this.setLickTicks(this.getLickTicks() - 1);
                if (attackTarget != null && attackTarget.isAlive() && this.hasLineOfSight(attackTarget) && attackTarget.distanceTo(this) < 20) {
                    this.setTongueTargetId(attackTarget.getId());
                    this.lookAt(EntityAnchorArgument.Anchor.EYES, attackTarget.getEyePosition());
                } else {
                    this.setTongueTargetId(-1);
                }
            } else {
                this.setTongueTargetId(-1);
            }
        }
        if (tongueTarget instanceof LivingEntity living) {
            if (this.shootTongueAmount >= 5F) {
                postAttackEffect(living);
                tongueTarget.hurt(damageSources().mobAttack(this), 4);
                living.knockback(0.3D, living.getX() - this.getX(), tongueTarget.getZ() - this.getZ());
                this.setLickTicks(0);
            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void stimulateFire(double burnX, double burnY, double burnZ, int syncType) {
        if (MinecraftForge.EVENT_BUS.post(new DragonFireEvent(this, burnX, burnY, burnZ))) return;
        if (syncType == 1 && !level.isClientSide) {
            //sync with client
            IceAndFire.sendMSGToAll(new MessageDragonSyncFire(this.getId(), burnX, burnY, burnZ, 0));
        }
        if (syncType == 2 && level.isClientSide) {
            //sync with server
            IceAndFire.NETWORK_WRAPPER.sendToServer(new MessageDragonSyncFire(this.getId(), burnX, burnY, burnZ, 0));
        }
        if (syncType == 3 && !level.isClientSide) {
            //sync with client, fire bomb
            IceAndFire.sendMSGToAll(new MessageDragonSyncFire(this.getId(), burnX, burnY, burnZ, 5));
        }
        if (syncType == 4 && level.isClientSide) {
            //sync with server, fire bomb
            IceAndFire.NETWORK_WRAPPER.sendToServer(new MessageDragonSyncFire(this.getId(), burnX, burnY, burnZ, 5));
        }
        if (syncType > 2 && syncType < 6) {
            if (this.getAnimation() != ANIMATION_FIRECHARGE) {
                this.setAnimation(ANIMATION_FIRECHARGE);
            } else if (this.getAnimationTick() == 20) {
                setYRot(yBodyRot);
                Vec3 headVec = this.getHeadPosition();
                double d2 = burnX - headVec.x;
                double d3 = burnY - headVec.y;
                double d4 = burnZ - headVec.z;
                float inaccuracy = 1.0F;
                d2 = d2 + this.random.nextGaussian() * 0.007499999832361937D * inaccuracy;
                d3 = d3 + this.random.nextGaussian() * 0.007499999832361937D * inaccuracy;
                d4 = d4 + this.random.nextGaussian() * 0.007499999832361937D * inaccuracy;
                this.playSound(IafSoundRegistry.FIREDRAGON_BREATH, 4, 1);
                EntityDragonFireCharge entitylargefireball = new EntityDragonFireCharge(
                    IafEntityRegistry.FIRE_DRAGON_CHARGE.get(), level, this, d2, d3, d4);
                entitylargefireball.setPos(headVec.x, headVec.y, headVec.z);
                if (!level.isClientSide) {
                    level.addFreshEntity(entitylargefireball);
                }
                this.randomizeAttacks();
            }
            return;
        }
        this.getNavigation().stop();
        this.burnParticleX = burnX;
        this.burnParticleY = burnY;
        this.burnParticleZ = burnZ;
        Vec3 headPos = getHeadPosition();
        double d2 = burnX - headPos.x;
        double d3 = burnY - headPos.y;
        double d4 = burnZ - headPos.z;
        double distance = Math.max(2.5F * this.distanceToSqr(burnX, burnY, burnZ), 0);
        double conqueredDistance = burnProgress / 40D * distance;
        int increment = (int) Math.ceil(conqueredDistance / 100);
        int particleCount = this.getDragonStage() <= 3 ? 6 : 3;
        for (int i = 0; i < conqueredDistance; i += increment) {
            double progressX = headPos.x + d2 * (i / (float) distance);
            double progressY = headPos.y + d3 * (i / (float) distance);
            double progressZ = headPos.z + d4 * (i / (float) distance);
            if (canPositionBeSeen(progressX, progressY, progressZ)) {
                if (level.isClientSide && random.nextInt(particleCount) == 0) {
                    IceAndFire.PROXY.spawnDragonParticle(EnumParticles.DragonFire, headPos.x, headPos.y, headPos.z, 0, 0, 0, this);
                }
            } else {
                if (!level.isClientSide) {
                    HitResult result = this.level.clip(new ClipContext(new Vec3(this.getX(), this.getY() + this.getEyeHeight(), this.getZ()), new Vec3(progressX, progressY, progressZ), ClipContext.Block.COLLIDER, ClipContext.Fluid.NONE, this));
                    BlockPos pos = new BlockPos(result.getLocation());
                    IafDragonDestructionManager.destroyAreaFire(level, pos, this);
                }
            }
        }
        if (burnProgress >= 40D && canPositionBeSeen(burnX, burnY, burnZ)) {
            double spawnX = burnX + (random.nextFloat() * 3.0) - 1.5;
            double spawnY = burnY + (random.nextFloat() * 3.0) - 1.5;
            double spawnZ = burnZ + (random.nextFloat() * 3.0) - 1.5;
            if (!level.isClientSide) {
                IafDragonDestructionManager.destroyAreaFire(level, new BlockPos(spawnX, spawnY, spawnZ), this);
            }
        }
    }

public void tick() {
        super.tick();
        this.prevSitProgress = this.sitProgress;

        if (this.isSitting()) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (!this.level().isClientSide) {
            if (isSitting() && ++sittingTime > maxSitTime) {
                this.setSitting(false);
                sittingTime = 0;
                maxSitTime = 75 + random.nextInt(50);
            }
            if (this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSitting() && random.nextInt(500) == 0) {
                sittingTime = 0;
                maxSitTime = 200 + random.nextInt(550);
                this.setSitting(true);
            }
            if (this.isSitting() && (this.getTarget() != null || this.isInLove())) {
                this.setSitting(false);
            }
            if (this.getTarget() != null && (this.getAnimation() == ANIMATION_SWIPE_L || this.getAnimation() == ANIMATION_SWIPE_R) && this.getAnimationTick() == 7 && this.hasLineOfSight(this.getTarget()) && this.distanceTo(this.getTarget()) < this.getBbHeight() + this.getTarget().getBbHeight() + 1) {
                getTarget().knockback(0.4F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                if (this.isLeader() && getTarget() instanceof EntityGeladaMonkey monkey) {
                    if (monkey.isLeader()) {
                        monkey.setTarget(this);
                        monkey.leaderFightTime = this.leaderFightTime;
                        dmg = 0;
                    }
                }
                this.getTarget().hurt(this.damageSources().mobAttack(this), dmg);
            }
            if (this.getTarget() != null && this.getTarget().isAlive()) {
                this.setAggro(true);
                if (this.isLeader() && this.getTarget() instanceof EntityGeladaMonkey monkey) {
                    if (monkey.isLeader()) {
                        this.leaderFightTime++;
                    }
                    if(leaderFightTime < 10 && random.nextInt(5) == 0 && this.getAnimation() == NO_ANIMATION){
                        this.setAnimation(ANIMATION_CHEST);
                    }
                    if (Math.max(this.leaderFightTime, monkey.leaderFightTime) >= 250) {
                        this.resetAttackAI();
                        monkey.resetAttackAI();
                    }
                }

            } else {
                this.setAggro(false);
            }
            if (this.leaderFightTime < 0) {
                this.leaderFightTime++;
            }
        }

        if (isAggro()) {
            if (!hasSpedUp) {
                hasSpedUp = true;
                this.setSprinting(true);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.31F);
            }
        } else {
            if (hasSpedUp) {
                hasSpedUp = false;
                this.setSprinting(false);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
        }

        if (getClearGrassTime() > 0) {
            setClearGrassTime(getClearGrassTime() - 1);
        }
        if (getClearGrassTime() < 0) {
            setClearGrassTime(getClearGrassTime() + 1);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

