@Override
	protected void createNextCurve() {
		AnimationPlayer animPlayer = this.owner.getAnimator().getPlayerFor(this.animation);
		boolean isTrailInvisible = animPlayer.getAnimation().get().isLinkAnimation() || animPlayer.getElapsedTime() <= this.trailInfo.startTime();
		boolean isFirstTrail = this.trailEdges.isEmpty();
		boolean needCorrection = (!isTrailInvisible && isFirstTrail);

		if (needCorrection) {
			float startCorrection = Math.max((this.trailInfo.startTime() - animPlayer.getPrevElapsedTime()) / (animPlayer.getElapsedTime() - animPlayer.getPrevElapsedTime()), 0.0F);
			this.startEdgeCorrection = this.trailInfo.interpolateCount() * 2 * startCorrection;
		}

		TrailInfo trailInfo = this.trailInfo;
		Pose prevPose = this.owner.getAnimator().getPose(0.0F);//this.lastPose;
		Pose currentPose = this.owner.getAnimator().getPose(1.0F);
		Pose middlePose = this.owner.getAnimator().getPose(0.5F);//Pose.interpolatePose(prevPose, currentPose, 0.5F);

		Vec3 posOld = this.owner.getOriginal().getPosition(0.0F);
		Vec3 posCur = this.owner.getOriginal().getPosition(1.0F);
		Vec3 posMid = MathUtils.lerpVector(posOld, posCur, 0.5F);

		OpenMatrix4f prevModelMatrix = this.owner.getModelMatrix(0.0F);
		OpenMatrix4f curModelMatrix = this.owner.getModelMatrix(1.0F);
		JointTransform lastTransform = JointTransform.fromMatrix(curModelMatrix);
		JointTransform currentTransform = JointTransform.fromMatrix(curModelMatrix);

		OpenMatrix4f prvmodelTf
			= OpenMatrix4f
				.createTranslation((float)posOld.x, (float)posOld.y, (float)posOld.z)
				.rotateDeg(180.0F, Vec3f.Y_AXIS)
				.mulBack(prevModelMatrix);
		OpenMatrix4f middleModelTf
			= OpenMatrix4f
				.createTranslation((float)posMid.x, (float)posMid.y, (float)posMid.z)
				.rotateDeg(180.0F, Vec3f.Y_AXIS)
				.mulBack(JointTransform.interpolate(lastTransform, currentTransform, 0.5F).toMatrix());
		OpenMatrix4f curModelTf
			= OpenMatrix4f
				.createTranslation((float)posCur.x, (float)posCur.y, (float)posCur.z)
				.rotateDeg(180.0F, Vec3f.Y_AXIS)
				.mulBack(curModelMatrix);

		OpenMatrix4f prevJointTf = this.owner.getArmature().getBoundTransformFor(prevPose, this.joint).mulFront(prvmodelTf);
		OpenMatrix4f middleJointTf = this.owner.getArmature().getBoundTransformFor(middlePose, this.joint).mulFront(middleModelTf);
		OpenMatrix4f currentJointTf = this.owner.getArmature().getBoundTransformFor(currentPose, this.joint).mulFront(curModelTf);
		Vec3 prevStartPos = OpenMatrix4f.transform(prevJointTf, trailInfo.start());
		Vec3 prevEndPos = OpenMatrix4f.transform(prevJointTf, trailInfo.end());
		Vec3 middleStartPos = OpenMatrix4f.transform(middleJointTf, trailInfo.start());
		Vec3 middleEndPos = OpenMatrix4f.transform(middleJointTf, trailInfo.end());
		Vec3 currentStartPos = OpenMatrix4f.transform(currentJointTf, trailInfo.start());
		Vec3 currentEndPos = OpenMatrix4f.transform(currentJointTf, trailInfo.end());

		List<Vec3> finalStartPositions;
		List<Vec3> finalEndPositions;
		boolean visibleTrail;

		if (isTrailInvisible) {
			finalStartPositions = Lists.newArrayList();
			finalEndPositions = Lists.newArrayList();
			finalStartPositions.add(prevStartPos);
			finalStartPositions.add(middleStartPos);
			finalEndPositions.add(prevEndPos);
			finalEndPositions.add(middleEndPos);

			this.invisibleTrailEdges.clear();
			visibleTrail = false;
		} else {
			List<Vec3> startPosList = Lists.newArrayList();
			List<Vec3> endPosList = Lists.newArrayList();
			TrailEdge edge1;
			TrailEdge edge2;

			if (isFirstTrail) {
				int lastIdx = this.invisibleTrailEdges.size() - 1;
				edge1 = this.invisibleTrailEdges.get(lastIdx);
				edge2 = new TrailEdge(prevStartPos, prevEndPos, -1);
			} else {
				edge1 = this.trailEdges.get(this.trailEdges.size() - (this.trailInfo.interpolateCount() / 2 + 1));
				edge2 = this.trailEdges.get(this.trailEdges.size() - 1);
				edge2.lifetime++;
			}

			startPosList.add(edge1.start);
			endPosList.add(edge1.end);
			startPosList.add(edge2.start);
			endPosList.add(edge2.end);
			startPosList.add(middleStartPos);
			endPosList.add(middleEndPos);
			startPosList.add(currentStartPos);
			endPosList.add(currentEndPos);

			finalStartPositions = CubicBezierCurve.getBezierInterpolatedPoints(startPosList, 1, 3, this.trailInfo.interpolateCount());
			finalEndPositions = CubicBezierCurve.getBezierInterpolatedPoints(endPosList, 1, 3, this.trailInfo.interpolateCount());

			if (!isFirstTrail) {
				finalStartPositions.remove(0);
				finalEndPositions.remove(0);
			}

			visibleTrail = true;
		}

		this.makeTrailEdges(finalStartPositions, finalEndPositions, visibleTrail ? this.trailEdges : this.invisibleTrailEdges);
	}

public void tick() {
        super.tick();
        prevFishPitch = fishPitch;
        prevSummonedProgress = summonedProgress;
        boolean water = this.isInWaterOrBubble();
        if (water && this.isLandNavigator) {
            switchNavigator(false);
        }
        if (!water && !this.isLandNavigator) {
            switchNavigator(true);
        }
        float pitchTarget;
        if (isDeepOneSwimming()) {
            pitchTarget = (float) this.getDeltaMovement().y * getPitchScale();
            if (!level().isClientSide && this.getNavigation().isDone() && this.onGround()) {
                this.setDeepOneSwimming(false);
            }
        } else {
            pitchTarget = 0;
        }
        if (isSummoned()) {
            if (this.getSummonTime() > 0) {
                if (summonedProgress < 20.0F) {
                    if (summonedProgress == 0) {
                        if (!level().isClientSide) {
                            this.level().broadcastEntityEvent(this, (byte) 61);
                        }
                        this.playSound(ACSoundRegistry.MAGIC_CONCH_SUMMON.get());
                    }
                    summonedProgress++;
                }
            } else {
                if (summonedProgress > 0.0F) {
                    summonedProgress--;
                }
            }
            if (getSummonTime() > 0) {
                if (!level().isClientSide) {
                    setSummonTime(getSummonTime() - 1);
                }
                if (getSummonTime() == 0) {
                    if (!level().isClientSide) {
                        this.level().broadcastEntityEvent(this, (byte) 61);
                    }
                    this.playSound(ACSoundRegistry.MAGIC_CONCH_SUMMON.get());
                }
            } else {
                if (!level().isClientSide && this.summonedProgress <= 0) {
                    this.remove(RemovalReason.DISCARDED);
                }
            }
        }
        if (!isSummoned() && summonedProgress > 0.0F) {
            summonedProgress--;
        }
        if (hasSwimmingBoundingBox()) {
            if (!hasSwimmingSize) {
                hasSwimmingSize = true;
                refreshDimensions();
            }
        } else {
            if (hasSwimmingSize) {
                hasSwimmingSize = false;
                refreshDimensions();
            }
        }
        if (tradingLockedTime > 0) {
            tradingLockedTime--;
        }
        if (!level().isClientSide && this.getAnimation() == getTradingAnimation() && this.getMainHandItem().is(ACTagRegistry.DEEP_ONE_BARTERS)) {
            BlockPos altarPos = getLastAltarPos();
            if (altarPos != null) {
                Vec3 center = Vec3.atCenterOf(altarPos);
                if (this.getAnimationTick() > getTradingAnimation().getDuration() - 10) {
                    if (level().getBlockEntity(altarPos) instanceof AbyssalAltarBlockEntity altar && !spawnedLootItem) {
                        List<ItemStack> possibles = generateBarterLoot();
                        ItemStack stack = possibles.isEmpty() ? ItemStack.EMPTY : possibles.get(0);
                        if (altar.getItem(0).isEmpty()) {
                            altar.setItem(0, stack);
                            this.level().broadcastEntityEvent(this, (byte) 68);
                            altar.onEntityInteract(this, false);
                        } else {
                            Vec3 vec3 = center.add(0, 0.5F, 0);
                            ItemEntity itemEntity = new ItemEntity(level(), vec3.x, vec3.y, vec3.z, stack);
                            level().addFreshEntity(itemEntity);
                        }
                        double advancementRange = 20.0D;
                        for (Player player : level().getNearbyPlayers(TargetingConditions.forNonCombat().range(advancementRange), this, this.getBoundingBox().inflate(advancementRange))) {
                            if (player.distanceTo(this) < advancementRange) {
                                ACAdvancementTriggerRegistry.DEEP_ONE_TRADE.triggerForEntity(player);
                            }
                        }
                        spawnedLootItem = true;
                    }
                    restoreSwappedItem();
                }
                this.lookAt(EntityAnchorArgument.Anchor.EYES, center);
            }
        }
        if (spawnedLootItem && this.getAnimation() != getTradingAnimation()) {
            spawnedLootItem = false;
        }
        fishPitch = Mth.approachDegrees(fishPitch, Mth.clamp((float) pitchTarget, -1.4F, 1.4F) * -(float) (180F / (float) Math.PI), 5);
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick(){
        super.tick();
        this.prevSitProgress = sitProgress;
        this.prevSneakProgress = sneakProgress;
        this.prevTackleProgress = tackleProgress;
        this.prevSleepProgress = sleepProgress;

        final boolean sitting = isSitting();
        final boolean slSneaking = isSLSneaking();
        final boolean tackling = isTackling();
        final boolean sleeping = isSleeping();

        if (sitting) {
            if (sitProgress < 5F) {
                sitProgress += 0.5F;
            }
        } else {
            if (sitProgress > 0F) {
                sitProgress -= 0.5F;
            }
        }

        if (slSneaking) {
            if (sneakProgress < 5F) {
                sneakProgress += 0.5F;
            }
        } else {
            if (sneakProgress > 0F) {
                sneakProgress -= 0.5F;
            }
        }

        if (tackling) {
            if (tackleProgress < 3F) {
                tackleProgress++;
            }
        } else {
            if (tackleProgress > 0F) {
                tackleProgress--;
            }
        }

        if (sleeping) {
            if (sleepProgress < 5F) {
                sleepProgress += 0.5F;
            }
        } else {
            if (sleepProgress > 0F) {
                sleepProgress -= 0.5F;
            }
        }

        if(slSneaking && !hasSlowedDown){
            hasSlowedDown = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
        }
        if(!slSneaking && hasSlowedDown){
            hasSlowedDown = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35F);
        }
        if(tackling){
            this.yBodyRot = this.getYRot();
        }
        if(!this.level().isClientSide) {
            if (this.getTarget() != null && (this.isSitting() || this.isSleeping())) {
                this.setSitting(false);
                this.setSleeping(false);
            }
            if ((isSitting() || isSleeping()) && (++sittingTime > maxSitTime || this.getTarget() != null || this.isInLove() || this.isInWaterOrBubble())) {
                this.setSitting(false);
                this.setSleeping(false);
                sittingTime = 0;
                maxSitTime = 100 + random.nextInt(50);
            }
            if (this.getTarget() == null && this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSleeping() && !this.isSitting() && !this.isInWaterOrBubble() && random.nextInt(340) == 0) {
                sittingTime = 0;
                if (this.getRandom().nextInt(2) != 0) {
                    maxSitTime = 200 + random.nextInt(800);
                    this.setSitting(true);
                    this.setSleeping(false);
                } else {
                    maxSitTime = 2000 + random.nextInt(2600);
                    this.setSitting(false);
                    this.setSleeping(true);
                }
            }
        }
        LivingEntity attackTarget = this.getTarget();
        if (attackTarget != null) {
            if (distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 0.6D && this.hasLineOfSight(attackTarget)) {
                if (this.getAnimation() == ANIMATION_ATTACK_L && this.getAnimationTick() == 7) {
                    doHurtTarget(attackTarget);
                    float rot = getYRot() + 90;
                    attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                }
                if (this.getAnimation() == ANIMATION_ATTACK_R && this.getAnimationTick() == 7) {
                    doHurtTarget(attackTarget);
                    float rot = getYRot() - 90;
                    attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                }

            }
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void setupAnim(GummyBearEntity entity, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
        this.resetToDefaultPose();
        animate(entity);
        boolean november13th = entity.lookForTheGummyBearAlbumInStoresOnNovember13th;
        float partialTicks = ageInTicks - entity.tickCount;
        float walkSpeed = 0.5F;
        float walkDegree = 1F;
        float bounceSpeed = 1.0F;
        float bounceDegree = 1.0F;
        float headYawAmount = netHeadYaw / 57.295776F;
        float headPitchAmount = headPitch / 57.295776F;
        float sleepProgress = entity.getSleepProgress(partialTicks);
        float danceProgress = (1F - sleepProgress) * entity.getDanceProgress(partialTicks);
        float sitProgress = (1F - sleepProgress) * Math.max(entity.getSitProgress(partialTicks), danceProgress);
        float standProgress = (1F - sleepProgress) * (1F - sitProgress) * (november13th ? Math.min(1.0F, limbSwingAmount * entity.getStandProgress(partialTicks)) : entity.getStandProgress(partialTicks));
        float uprightProgress = Math.max(sitProgress, standProgress);
        float allFoursProgress = 1F - uprightProgress;
        progressRotationPrev(body, uprightProgress, (float) Math.toRadians(-90), 0, 0, 1F);
        progressRotationPrev(head, uprightProgress, (float) Math.toRadians(90), 0, 0, 1F);
        progressPositionPrev(head, uprightProgress, 0, -4, -4, 1F);
        progressPositionPrev(body, sitProgress, 0, 2.5F, 2.5F, 1F);
        progressPositionPrev(body, standProgress, 0, -2.8F, 0F, 1F);
        progressPositionPrev(left_Leg, standProgress, 0, -2.5F, 2, 1F);
        progressPositionPrev(right_Leg, standProgress, 0, -2.5F, 2, 1F);
        progressPositionPrev(tail, standProgress, 0, -2.5F, 0, 1F);
        if (november13th) {
            progressRotationPrev(left_Leg, standProgress, (float) Math.toRadians(90), 0, 0, 1F);
            progressRotationPrev(right_Leg, standProgress, (float) Math.toRadians(90), 0, 0, 1F);
            progressRotationPrev(right_Arm, standProgress, 0, 0, (float) Math.toRadians(60), 1F);
            progressRotationPrev(left_Arm, standProgress, 0, 0, (float) Math.toRadians(-60), 1F);
        } else {
            progressRotationPrev(body, standProgress, (float) Math.toRadians(10), 0, 0, 1F);
            progressRotationPrev(head, standProgress, (float) Math.toRadians(-10), 0, 0, 1F);
            progressRotationPrev(left_Leg, standProgress, (float) Math.toRadians(80), 0, 0, 1F);
            progressRotationPrev(right_Leg, standProgress, (float) Math.toRadians(80), 0, 0, 1F);
        }
        progressRotationPrev(right_Arm, sleepProgress, (float) Math.toRadians(-30), 0, (float) Math.toRadians(90), 1F);
        progressRotationPrev(left_Arm, sleepProgress, (float) Math.toRadians(-30), 0, (float) Math.toRadians(-90), 1F);
        progressRotationPrev(head, sleepProgress, (float) Math.toRadians(10), (float) Math.toRadians(-20), (float) Math.toRadians(10), 1F);
        progressRotationPrev(right_Leg, sleepProgress, (float) Math.toRadians(30), 0, (float) Math.toRadians(90), 1F);
        progressRotationPrev(left_Leg, sleepProgress, (float) Math.toRadians(30), 0, (float) Math.toRadians(-90), 1F);
        progressPositionPrev(body, sleepProgress, 0, 5F, 0, 1F);
        progressPositionPrev(right_Arm, sleepProgress, -1, -2F, 0, 1F);
        progressPositionPrev(left_Arm, sleepProgress, 1, -2F, 0, 1F);
        progressPositionPrev(head, sleepProgress, 0, -1F, 1, 1F);
        progressPositionPrev(right_Leg, sleepProgress, -1, -2F, 0, 1F);
        progressPositionPrev(left_Leg, sleepProgress, 1, -2F, 0, 1F);

        this.flap(tail, 0.06F, 0.1F, false, -1F, 0.0F, ageInTicks, 1F);
        this.swing(left_Ear, 0.06F, 0.1F, false, -1F, 0.0F, ageInTicks, 1F);
        this.swing(right_Ear, 0.06F, 0.1F, true, -1F, 0.0F, ageInTicks, 1F);
        this.bob(head, 0.06F, 0.2F, false, ageInTicks, 1F);
        this.flap(right_Leg, 0.06F, 0.2F, false, -1F, 0.2F, ageInTicks, sitProgress);
        this.flap(left_Leg, 0.06F, 0.2F, true, -1F, 0.2F, ageInTicks, sitProgress);
        this.walk(right_Arm, 0.06F, 0.1F, false, -2F, 0.2F, ageInTicks, sitProgress);
        this.walk(left_Arm, 0.06F, 0.1F, false, -2F, 0.2F, ageInTicks, sitProgress);
        this.walk(right_Arm, 0.06F, 0.1F, false, -2F, 0.4F, ageInTicks, standProgress);
        this.walk(left_Arm, 0.06F, 0.1F, false, -2F, 0.4F, ageInTicks, standProgress);
        this.flap(body, 0.3F, 0.1F, false, -2F, 0.0F, ageInTicks, danceProgress);
        this.bob(body, 0.3F, 7, true, ageInTicks, danceProgress);
        this.flap(head, 0.3F, 0.1F, false, -2F, 0.0F, ageInTicks, danceProgress);
        this.swing(head, 0.3F, 0.1F, false, -2F, 0.0F, ageInTicks, danceProgress);
        this.walk(left_Arm, 0.3F, 0.5F, true, -2F, 0.5F, ageInTicks, danceProgress);
        this.walk(right_Arm, 0.3F, 0.5F, false, -2F, -0.5F, ageInTicks, danceProgress);
        this.walk(left_Leg, 0.3F, 0.3F, true, -1.5F, -0.1F, ageInTicks, danceProgress);
        this.walk(right_Leg, 0.3F, 0.3F, true, -1.5F, -0.1F, ageInTicks, danceProgress);
        if (november13th) {
            this.walk(body, bounceSpeed, bounceDegree * 0.1F, true, 1F, -0.1F, limbSwing, limbSwingAmount);
            this.walk(left_Leg, bounceSpeed, bounceDegree, true, 1F, 0F, limbSwing, limbSwingAmount);
            this.walk(right_Leg, bounceSpeed, bounceDegree, true, 1F, 0F, limbSwing, limbSwingAmount);
            this.walk(right_Arm, bounceSpeed, bounceDegree, true, 2F, 0.3F, limbSwing, limbSwingAmount);
            this.walk(left_Arm, bounceSpeed, bounceDegree, true, 2F, 0.3F, limbSwing, limbSwingAmount);
            body.rotationPointY += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount, bounceSpeed, 0.4F, bounceDegree * 15, false));
            body.rotationPointZ += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount, bounceSpeed, 0.8F, bounceDegree * 6, false));
        } else {
            this.flap(body, walkSpeed * 2F, walkDegree * 0.1F, false, 0F, 0.0F, limbSwing, limbSwingAmount);
            this.flap(head, walkSpeed * 2F, walkDegree * 0.1F, true, 1F, 0.0F, limbSwing, limbSwingAmount);
            this.walk(left_Leg, walkSpeed, walkDegree, false, 1F, 0F, limbSwing, limbSwingAmount);
            left_Leg.rotationPointY += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount, walkSpeed, -0.5F, walkDegree * 2, true));
            this.walk(right_Leg, walkSpeed, walkDegree, true, 1F, 0F, limbSwing, limbSwingAmount);
            right_Leg.rotationPointY += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount, walkSpeed, -0.5F, walkDegree * 2, false));
            this.walk(left_Arm, walkSpeed, walkDegree, false, 2.5F, 0F, limbSwing, limbSwingAmount * allFoursProgress);
            left_Arm.rotationPointY += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount * allFoursProgress, walkSpeed, 1.0F, walkDegree * 2, true));
            this.walk(right_Arm, walkSpeed, walkDegree, true, 2.5F, 0F, limbSwing, limbSwingAmount * allFoursProgress);
            right_Arm.rotationPointY += Math.min(0, ACMath.walkValue(limbSwing, limbSwingAmount * allFoursProgress, walkSpeed, 1.0F, walkDegree * 2, false));
        }
        if (entity.getAnimation() == GummyBearEntity.ANIMATION_EAT) {
            float animationIntensity = ACMath.cullAnimationTick(entity.getAnimationTick(), 4, GummyBearEntity.ANIMATION_EAT, partialTicks, 0);
            this.walk(head, 0.5F, 0.3F, true, 0F, 0.2F, ageInTicks, animationIntensity);
            this.walk(left_Arm, 0.5F, 0.3F, true, 1F, 0.2F, ageInTicks, animationIntensity);
            this.walk(right_Arm, 0.5F, 0.3F, true, 1F, 0.2F, ageInTicks, animationIntensity);
        }
        if (entity.getAnimation() == GummyBearEntity.ANIMATION_BACKSCRATCH) {
            float animationIntensity = ACMath.cullAnimationTick(entity.getAnimationTick(), 4, GummyBearEntity.ANIMATION_BACKSCRATCH, partialTicks, 0);
            float bodyScratchUp = animationIntensity * 2.0F - ACMath.walkValue(ageInTicks, animationIntensity, 0.45F, -0.5F, 2.0F, true);
            this.body.rotationPointY += bodyScratchUp;
            this.left_Leg.rotationPointZ -= bodyScratchUp;
            this.right_Leg.rotationPointZ -= bodyScratchUp;
            this.walk(body, 0.45F, 0.1F, true, 0F, 0.2F, ageInTicks, animationIntensity);
            this.walk(left_Leg, 0.45F, 0.1F, false, 0F, 0.2F, ageInTicks, animationIntensity);
            this.walk(right_Leg, 0.45F, 0.1F, false, 0F, 0.2F, ageInTicks, animationIntensity);
            this.walk(head, 0.45F, 0.1F, true, 1F, 0.1F, ageInTicks, animationIntensity);
            this.flap(right_Arm, 0.45F, 0.1F, true, 1F, -0.3F, ageInTicks, animationIntensity);
            this.flap(left_Arm, 0.45F, 0.1F, true, 1F, 0.3F, ageInTicks, animationIntensity);
        }
        this.head.rotateAngleY += headYawAmount * 0.65F;
        this.head.rotateAngleX += headPitchAmount * 0.75F;
    }

private void spawnSwipeParticles() {
        if (level().isClientSide && getHasCrystal()) {
            double motionX = getDeltaMovement().x();
            double motionY = getDeltaMovement().y();
            double motionZ = getDeltaMovement().z();

            int snowflakeDensity = 4;
            float snowflakeRandomness = 0.5f;
            int cloudDensity = 2;
            float cloudRandomness = 0.5f;
            if (getAnimation() == SWIPE_ANIMATION || getAnimation() == SWIPE_TWICE_ANIMATION) {
                Vec3 rightHandPos = socketPosArray[0];
                Vec3 leftHandPos = socketPosArray[1];
                if (getAnimation() == SWIPE_ANIMATION) {
                    if (getAnimationTick() > 8 && getAnimationTick() < 14) {
                        if (swingWhichArm) {
                            double length = prevRightHandPos.subtract(rightHandPos).length();
                            int numClouds = (int) Math.floor(2 * length);
                            for (int i = 0; i < numClouds; i++) {
                                double x = prevRightHandPos.x + i * (rightHandPos.x - prevRightHandPos.x) / numClouds;
                                double y = prevRightHandPos.y + i * (rightHandPos.y - prevRightHandPos.y) / numClouds;
                                double z = prevRightHandPos.z + i * (rightHandPos.z - prevRightHandPos.z) / numClouds;
                                for (int j = 0; j < snowflakeDensity; j++) {
                                    float xOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                    float yOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                    float zOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                    level().addParticle(new ParticleSnowFlake.Data(40, false), x + xOffset, y + yOffset, z + zOffset, motionX, motionY - 0.01f, motionZ);
                                }
                                for (int j = 0; j < cloudDensity; j++) {
                                    float xOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                    float yOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                    float zOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                    float value = random.nextFloat() * 0.1f;
                                    level().addParticle(new ParticleCloud.Data(0.8f + value, 0.8f + value, 1f, (float) (10d + random.nextDouble() * 10d), 40, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x + xOffset, y + yOffset, z + zOffset, motionX, motionY, motionZ);
                                }
                            }
                        } else {
                            double length = prevLeftHandPos.subtract(leftHandPos).length();
                            int numClouds = (int) Math.floor(2.5 * length);
                            for (int i = 0; i < numClouds; i++) {
                                double x = prevLeftHandPos.x + i * (leftHandPos.x - prevLeftHandPos.x) / numClouds;
                                double y = prevLeftHandPos.y + i * (leftHandPos.y - prevLeftHandPos.y) / numClouds;
                                double z = prevLeftHandPos.z + i * (leftHandPos.z - prevLeftHandPos.z) / numClouds;
                                for (int j = 0; j < snowflakeDensity; j++) {
                                    float xOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                    float yOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                    float zOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                    level().addParticle(new ParticleSnowFlake.Data(40, false), x + xOffset, y + yOffset, z + zOffset, motionX, motionY - 0.01f, motionZ);
                                }
                                for (int j = 0; j < cloudDensity; j++) {
                                    float xOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                    float yOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                    float zOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                    float value = random.nextFloat() * 0.1f;
                                    level().addParticle(new ParticleCloud.Data(0.8f + value, 0.8f + value, 1f, (float) (10d + random.nextDouble() * 10d), 40, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x + xOffset, y + yOffset, z + zOffset, motionX, motionY, motionZ);
                                }
                            }
                        }
                    }
                } else {
                    if ((swingWhichArm && getAnimationTick() > 8 && getAnimationTick() < 14) || (!swingWhichArm && getAnimationTick() > 19 && getAnimationTick() < 25)) {
                        double length = prevRightHandPos.subtract(rightHandPos).length();
                        int numClouds = (int) Math.floor(2 * length);
                        for (int i = 0; i < numClouds; i++) {
                            double x = prevRightHandPos.x + i * (rightHandPos.x - prevRightHandPos.x) / numClouds;
                            double y = prevRightHandPos.y + i * (rightHandPos.y - prevRightHandPos.y) / numClouds;
                            double z = prevRightHandPos.z + i * (rightHandPos.z - prevRightHandPos.z) / numClouds;
                            for (int j = 0; j < snowflakeDensity; j++) {
                                float xOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                float yOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                float zOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                level().addParticle(new ParticleSnowFlake.Data(40, false), x + xOffset, y + yOffset, z + zOffset, motionX, motionY - 0.01f, motionZ);
                            }
                            for (int j = 0; j < cloudDensity; j++) {
                                float xOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                float yOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                float zOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                float value = random.nextFloat() * 0.1f;
                                level().addParticle(new ParticleCloud.Data(0.8f + value, 0.8f + value, 1f, (float) (10d + random.nextDouble() * 10d), 40, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x + xOffset, y + yOffset, z + zOffset, motionX, motionY, motionZ);
                            }
                        }
                    } else if ((!swingWhichArm && getAnimationTick() > 8 && getAnimationTick() < 14) || (swingWhichArm && getAnimationTick() > 19 && getAnimationTick() < 25)) {
                        double length = prevLeftHandPos.subtract(leftHandPos).length();
                        int numClouds = (int) Math.floor(2.5 * length);
                        for (int i = 0; i < numClouds; i++) {
                            double x = prevLeftHandPos.x + i * (leftHandPos.x - prevLeftHandPos.x) / numClouds;
                            double y = prevLeftHandPos.y + i * (leftHandPos.y - prevLeftHandPos.y) / numClouds;
                            double z = prevLeftHandPos.z + i * (leftHandPos.z - prevLeftHandPos.z) / numClouds;
                            for (int j = 0; j < snowflakeDensity; j++) {
                                float xOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                float yOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                float zOffset = snowflakeRandomness * (2 * random.nextFloat() - 1);
                                level().addParticle(new ParticleSnowFlake.Data(40, false), x + xOffset, y + yOffset, z + zOffset, motionX, motionY - 0.01f, motionZ);
                            }
                            for (int j = 0; j < cloudDensity; j++) {
                                float xOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                float yOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                float zOffset = cloudRandomness * (2 * random.nextFloat() - 1);
                                float value = random.nextFloat() * 0.1f;
                                level().addParticle(new ParticleCloud.Data(0.8f + value, 0.8f + value, 1f, (float) (10d + random.nextDouble() * 10d), 40, ParticleCloud.EnumCloudBehavior.SHRINK, 1f), x + xOffset, y + yOffset, z + zOffset, motionX, motionY, motionZ);
                            }
                        }
                    }
                }
                prevLeftHandPos = leftHandPos;
                prevRightHandPos = rightHandPos;
            }
        }
    }

public void tick() {
        super.tick();
        prevStandProgress = standProgress;
        prevTongueProgress = tongueProgress;
        prevLeaningProgress = leaningProgress;

        if (isStanding()) {
            if (standProgress < 5F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        final boolean isTongueOut = this.getAnimation() == ANIMATION_TOUNGE_IDLE;
        if (isTongueOut) {
            if (tongueProgress < 5F)
                tongueProgress++;
        } else {
            if (tongueProgress > 0F)
                tongueProgress--;
        }

        if (isLeaning()) {
            if (leaningProgress < 5F)
                leaningProgress++;
        } else {
            if (leaningProgress > 0F)
                leaningProgress--;
        }

        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }

        if (this.isPassenger() && this.getVehicle() instanceof final EntityAnteater mount) {
            if (this.isBaby()) {
                this.setYRot(mount.yBodyRot);
                this.yHeadRot = mount.yBodyRot;
                this.yBodyRot = mount.yBodyRot;
            } else {
                this.removeVehicle();
            }
        }

        if (eatAntCooldown > 0) {
            eatAntCooldown--;
        }
        if (antsEatenRecently >= 3 && eatAntCooldown <= 0) {
            this.resetAntCooldown();
        }
        if (ticksAntOnTongue > 10 && this.hasAntOnTongue()) {
            this.heal(6);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.setAntOnTongue(false);
        }
        if (this.hasAntOnTongue()) {
            ticksAntOnTongue++;
        } else {
            ticksAntOnTongue = 0;
        }
        if (!this.level().isClientSide && getTongueStickOut() > 0.6F && !this.hasAntOnTongue() && antsEatenRecently < 3) {
            EntityLeafcutterAnt closestAnt = null;
            for (EntityLeafcutterAnt entity : this.level().getEntitiesOfClass(EntityLeafcutterAnt.class, this.getBoundingBox().inflate(2.6F))) {
                if (closestAnt == null || entity.distanceTo(this) < closestAnt.distanceTo(this) && this.hasLineOfSight(entity)) {
                    closestAnt = entity;
                }
            }
            if (closestAnt != null) {
                closestAnt.remove(RemovalReason.KILLED);
                ticksAntOnTongue = 0;
                this.setAntOnTongue(true);
                antsEatenRecently++;
            }
        }
        if (!this.getMainHandItem().isEmpty()) {
            heldItemTime++;
            if (heldItemTime > 10 && getTongueStickOut() < 0.3F && canTargetItem(this.getMainHandItem())) {
                heldItemTime = 0;
                this.heal(4);
                this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
                this.gameEvent(GameEvent.EAT);
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.stopBeingAngry();
                this.getMainHandItem().shrink(1);
            }
        } else {
            heldItemTime = 0;
        }

        if (!this.level().isClientSide) {
            if (getRandom().nextInt(300) == 0)
                this.setAnimation(ANIMATION_TOUNGE_IDLE);

            final LivingEntity attackTarget = this.getTarget();
            if (attackTarget != null) {
                if (distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 2) {
                    if (this.getAnimationTick() == 7) {
                        if (this.getAnimation() == ANIMATION_SLASH_L) {
                            doHurtTarget(attackTarget);
                            final float rot = getYRot() + 90;
                            attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                        } else if (this.getAnimation() == ANIMATION_SLASH_R) {
                            doHurtTarget(attackTarget);
                            final float rot = getYRot() - 90;
                            attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                        }
                    }
                }
            }
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

