@Override
    public void tick() {
        super.tick();
        activate.updatePrevTimer();
        deathFlail.updatePrevTimer();
        stopDance.updatePrevTimer();
        openMouth.updatePrevTimer();
        setDeltaMovement(0, getDeltaMovement().y, 0);
        // Open mouth animation
        if (getAnimation() == NO_ANIMATION && !activate.canIncreaseTimer()) {
            openMouth.update();
        } else {
            openMouth.stop();
        }

        if (activate.getAnimationFraction() >= 0.8F) {
            if (!active) {
                active = true;
            }
        } else if (activate.getAnimationFraction() < 0.8F) {
            if (active) {
                active = false;
            }
        }

        // Sounds
        if (frame % 13 == 3 && getAnimation() != DIE_ANIMATION) {
            if (openMouth.getTimeRunning() >= 10) {
                playSound(MMSounds.ENTITY_FOLIAATH_PANT_1.get(), 1, 1);
            } else if (activate.getTimer() >= 25) {
                playSound(MMSounds.ENTITY_FOLIAATH_PANT_2.get(), 1, 1);
            }
        }

        int openMouthTime = openMouth.getTimeRunning();
        if (prevOpenMouth - openMouthTime < 0) {
            if (openMouthTime == 1) {
                playSound(MMSounds.ENTITY_FOLIAATH_RUSTLE.get(), 1, 1);
            } else if (openMouthTime == 13) {
                playSound(MMSounds.ENTITY_FOLIAATH_GRUNT.get(), 1, 1);
            }
        }

        prevOpenMouth = openMouthTime;

        int activateTime = activate.getTimer();
        if (!level().isClientSide) {
            SoundEvent sound = null;
            if (prevActivate - activateTime < 0) {
                switch (activateTime) {
                    case 1:
                        sound = MMSounds.ENTITY_FOLIAATH_RUSTLE.get();
                        break;
                    case 5:
                        sound = MMSounds.ENTITY_FOLIAATH_MERGE.get();
                        break;
                }
            } else if (prevActivate - activateTime > 0) {
                switch (activateTime) {
                    case 24:
                        sound = MMSounds.ENTITY_FOLIAATH_RETREAT.get();
                        break;
                    case 28:
                        sound = MMSounds.ENTITY_FOLIAATH_RUSTLE.get();
                        break;
                }
            }
            if (sound != null) {
                playSound(sound, 1, 1);
            }
        }

        prevActivate = activateTime;

        // Targetting, attacking, and activating
        yBodyRot = 0;
        setYRot(0);

        if (resettingTargetTimer > 0 && !level().isClientSide) {
            yHeadRot = yHeadRotO;
        }

        if (getTarget() != null) {
            yHeadRot = targetAngle;

            if (targetDistance <= 4 && getTarget().getY() - getY() >= -1 && getTarget().getY() - getY() <= 2 && getAnimation() == NO_ANIMATION && active) {
                AnimationHandler.INSTANCE.sendAnimationMessage(this, ATTACK_ANIMATION);
            }

            if (targetDistance <= 10.5 && getTarget().getY() - getY() >= -1.5 && getTarget().getY() - getY() <= 2) {
                setActivateTarget(ACTIVATE_DURATION);
                lastTimeDecrease = 0;
            } else if (lastTimeDecrease <= 30 && getAnimation() == NO_ANIMATION) {
                setActivateTarget(0);
                lastTimeDecrease++;
            }
        } else if (!level().isClientSide && lastTimeDecrease <= 30 && getAnimation() == NO_ANIMATION && resettingTargetTimer == 0) {
            setActivateTarget(0);
            lastTimeDecrease++;
        }

        if (getAnimation() == DIE_ANIMATION) {
            if (getAnimationTick() <= 12) {
                deathFlail.increaseTimer();
            } else {
                deathFlail.decreaseTimer();
            }
            stopDance.increaseTimer();
            setActivateTarget(ACTIVATE_DURATION);
        }

        if (resettingTargetTimer > 0) {
            resettingTargetTimer--;
        }

        if (activateTarget == activateTime) {
            activateTarget = getActivateTarget();
        } else if (activateTime < activateTarget && activate.canIncreaseTimer() || activateTime > activateTarget && activate.canDecreaseTimer()) {
            activate.increaseTimer(activateTime < activateTarget ? 1 : -2);
        }

        if (!this.level().isClientSide && this.level().getDifficulty() == Difficulty.PEACEFUL)
        {
            this.discard() ;
        }
    }

public void tick() {
        super.tick();
        prevRunProgress = runProgress;
        prevLeapProgress = leapProgress;
        prevRelaxedProgress = relaxedProgress;
        prevHideProgress = hideProgress;
        prevTailYaw = tailYaw;
        float headPuzzleRot = getPuzzledHeadRot();
        if (isRunning() && runProgress < 5F) {
            runProgress++;
        }
        if (!isRunning() && runProgress > 0F) {
            runProgress--;
        }
        if (isLeaping() && leapProgress < 5F) {
            leapProgress++;
        }
        if (!isLeaping() && leapProgress > 0F) {
            leapProgress--;
        }
        if (getRelaxedFor() > 0 && relaxedProgress < 20F) {
            relaxedProgress++;
        }
        if (getRelaxedFor() <= 0 && relaxedProgress > 0F) {
            relaxedProgress--;
        }
        if (getHideFor() > 0 && hideProgress < 20F) {
            hideProgress++;
        }
        if (getHideFor() <= 0 && hideProgress > 0F) {
            hideProgress--;
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.35D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.2D);
        }
        if (isElder() && !hasElderAttributes) {
            hasElderAttributes = true;
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(32.0D);
            this.getAttribute(Attributes.ARMOR).setBaseValue(5.0D);
            this.heal(36.0F);
        }
        if (!isElder() && hasElderAttributes) {
            hasElderAttributes = false;
            this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(24.0D);
            this.getAttribute(Attributes.ARMOR).setBaseValue(0.0D);
            this.heal(28.0F);
        }
        if (this.tickCount % (this.getHideFor() > 0 ? 15 : 100) == 0 && this.getHealth() < this.getMaxHealth()) {
            this.heal(2);
        }
        if (!level().isClientSide) {
            puzzledTick(headPuzzleRot);
            if (isStillEnough() && random.nextInt(100) == 0 && this.getAnimation() == NO_ANIMATION && this.getRelaxedFor() <= 0 && !this.isDancing()) {
                Animation idle;
                float rand = random.nextFloat();
                if (rand < 0.45F) {
                    idle = ANIMATION_SCRATCH_1;
                } else if (rand < 0.9F) {
                    idle = ANIMATION_SCRATCH_2;
                } else {
                    idle = ANIMATION_SHAKE;
                }
                this.setAnimation(idle);
            }
            if (fleeTicks > 0) {
                fleeTicks--;
            }
            if (this.isLeaping()) {
                this.setDeltaMovement(this.getDeltaMovement().multiply(1.1F, 1, 1.1F));
            }
        }
        if (this.getAnimation() == ANIMATION_CALL_1 && this.getAnimationTick() == 5 || this.getAnimation() == ANIMATION_CALL_2 && this.getAnimationTick() == 4) {
            actuallyPlayAmbientSound();
        }
        if (!level().isClientSide) {
            if (eatHeldItemIn > 0) {
                eatHeldItemIn--;
            } else if (canTargetItem(this.getMainHandItem())) {
                ItemStack stack = this.getMainHandItem();
                this.level().broadcastEntityEvent(this, (byte) 45);
                this.heal(5);
                if (stack.is(ACItemRegistry.DINOSAUR_NUGGET.get()) && justLootedChest) {
                    this.setRelaxedForTime(200 + random.nextInt(200));
                }
                if (!this.level().isClientSide) {
                    stack.shrink(1);
                }
                justLootedChest = false;
            }
            if (getRelaxedFor() > 0) {
                this.setRelaxedForTime(this.getRelaxedFor() - 1);
            }
            if (getHideFor() > 0) {
                this.setHideFor(this.getHideFor() - 1);
            }
        }
        LivingEntity target = this.getTarget();
        if (target != null && target.isAlive() && !(target instanceof Player player && player.isCreative())) {
            if (this.isElder()) {
                PackAnimal leader = this;
                while (leader.getAfterPackMember() != null) {
                    leader = leader.getAfterPackMember();
                    if(!((VallumraptorEntity) leader).isAlliedTo(target)){
                        ((VallumraptorEntity) leader).setTarget(target);
                    }
                }
            }
            if (this.getHealth() < this.getMaxHealth() * 0.45F && this.isTame() && this.getHideFor() <= 0) {
                int i = 80 + random.nextInt(40);
                this.setHideFor(i);
                this.fleeFromPosition = target.position();
                this.fleeTicks = i;
                if (target instanceof Mob mob) {
                    mob.setTarget(null);
                    mob.setLastHurtByMob(null);
                    mob.setLastHurtMob(null);
                }
            }
            if (target instanceof GrottoceratopsEntity && (tickCount + this.getId()) % 20 == 0 && getPackSize() < 4 && !this.isTame()) {
                this.fleeFromPosition = target.position();
                this.fleeTicks = 100 + random.nextInt(100);
                this.setTarget(null);
                this.setLastHurtByMob(null);
            }
        }
        tailYaw = Mth.approachDegrees(this.tailYaw, yBodyRot, 8);
        prevPuzzleHeadRot = headPuzzleRot;
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();

        this.prevEnragedProgress = enragedProgress;
        if (this.isEnraged() && enragedProgress < 20.0F) {
            enragedProgress++;
        }
        if (!this.isEnraged() && enragedProgress > 0.0F) {
            enragedProgress--;
        }

        if (level().isClientSide) {
            if (this.isAlive()) {
                if (this.isEnraged()) {
                    if (random.nextInt(8) == 0) {
                        level().addParticle(ACParticleRegistry.LUXTRUCTOSAURUS_SPIT.get(), this.getX(), this.getY() + 0.5F, this.getZ(), this.getId(), 0, 0);
                    }
                    if (this.getAnimation() == ANIMATION_RIGHT_WHIP || this.getAnimation() == ANIMATION_LEFT_WHIP) {
                        float tailPitch = tailPart1.calculateAnimationAngle(1.0F, true) + tailPart2.calculateAnimationAngle(1.0F, true) + tailPart3.calculateAnimationAngle(1.0F, true);
                        float tailYaw = this.yBodyRot + tailPart1.calculateAnimationAngle(1.0F, false) + tailPart2.calculateAnimationAngle(1.0F, false) + tailPart3.calculateAnimationAngle(1.0F, false);
                        Vec3 tailOffset = rotateOffsetVec(new Vec3((random.nextFloat() - 0.5F) * 0.1F, 0.5F + (random.nextFloat() - 0.5F) * 0.2F, -2 + (random.nextFloat() - 0.5F) * 2), tailPitch, tailYaw);
                        Vec3 tailCenter = this.tailPart3.centeredPosition().add(tailOffset);
                        level().addParticle(ACParticleRegistry.TEPHRA_FLAME.get(), tailCenter.x, tailCenter.y, tailCenter.z, (random.nextFloat() - 0.5F) * 0.1F, random.nextFloat() * 0.1F, (random.nextFloat() - 0.5F) * 0.1F);
                    }
                }
                if (this.getAnimation() == ANIMATION_SPEW_FLAMES && this.getAnimationTick() > 10F && this.getAnimationTick() < 70F) {
                    Vec3 headPos = this.headPart.centeredPosition().add((random.nextFloat() - 0.5F) * 0.1F, (random.nextFloat() - 0.5F) * 0.1F, (random.nextFloat() - 0.5F) * 0.1F);
                    float flameRot = this.yBodyRot + (neckPart1.calculateAnimationAngle(1.0F, false) + neckPart2.calculateAnimationAngle(1.0F, false) + neckPart3.calculateAnimationAngle(1.0F, false)) / 3F;
                    for (int i = -3; i <= 3; i++) {
                        Vec3 flameDelta = rotateOffsetVec(new Vec3(0, random.nextFloat() * 0.2F - 0.1F, random.nextFloat() * 0.5F + 0.5F), (random.nextFloat() - 0.5F) * 5F, 180 + flameRot + (i * 10));
                        level().addParticle(ACParticleRegistry.TEPHRA_FLAME.get(), headPos.x, headPos.y, headPos.z, flameDelta.x, flameDelta.y, flameDelta.z);
                    }
                }
                if (this.getAnimation() == ANIMATION_JUMP && this.getAnimationTick() > 25 && this.onGround()) {
                    if (this.getAnimationTick() > 25 && this.screenShakeAmount < 3.0F) {
                        this.screenShakeAmount = 3.0F;
                    }
                }
            }
        } else {
            if (this.getAnimation() == ANIMATION_JUMP) {
                if (this.getAnimationTick() >= 15 && this.getAnimationTick() <= 25 && jumpTarget != null) {
                    Vec3 vec3 = this.getDeltaMovement();
                    Vec3 vec31 = new Vec3(this.jumpTarget.x - this.getX(), 0.0D, this.jumpTarget.z - this.getZ());
                    if (vec31.length() > 250) {
                        vec31 = vec3.normalize().scale(250);
                    }
                    if (vec31.lengthSqr() > 1.0E-7D) {
                        vec31 = vec31.scale(0.155F).add(vec3.scale(0.2D));
                    }
                    this.setDeltaMovement(vec31.x, (10 - Math.min(this.getAnimationTick() - 10, 10)) * 0.2F + (double) vec31.length() * 0.3F, vec31.z);
                } else {
                    if (this.onGround() && !prevOnGround) {
                        this.hurtEntitiesAround(this.position(), 10.0F, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 0.5F, 2.0F, false, false);
                    }
                    this.setDeltaMovement(this.getDeltaMovement().subtract(0, 0.2, 0));
                }
            }
            if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() >= 10 && this.getAnimationTick() < 55 && this.getAnimationTick() % 5 == 0 && this.isAlive()) {
                BlockPos tephraSpawnAt = this.blockPosition().offset(random.nextInt(20) - 10, 2, random.nextInt(20) - 10);
                while (tephraSpawnAt.getY() < Math.min(level().getMaxBuildHeight(), this.getBlockY() + 100) && !level().getBlockState(tephraSpawnAt).isSolid()) {
                    tephraSpawnAt = tephraSpawnAt.above();
                }
                tephraSpawnAt = tephraSpawnAt.below();
                TephraEntity tephra = new TephraEntity(level(), this);
                tephra.setPos(tephraSpawnAt.getCenter());
                tephra.setMaxScale(1F + 2F * level().random.nextFloat());
                Vec3 targetVec = new Vec3(level().random.nextFloat() - 0.5F, -1, level().random.nextFloat() - 0.5F).normalize().scale(level().random.nextInt(20) + 20);
                tephra.shoot(targetVec.x, targetVec.y, targetVec.z, 5 + level().random.nextFloat() * 2F, 1 + level().random.nextFloat() * 0.5F);
                level().addFreshEntity(tephra);
            }
            if (this.getAnimation() == ANIMATION_STOMP && this.getAnimationTick() == 30 && postStopTicks <= 0) {
                stompMakesFissures = this.isEnraged();
                postStopTicks = stompMakesFissures ? 15 : 50;
                this.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_STOMP.get(), 3.0F, 1.0F);
                lastStompPos = this.blockPosition();
                this.hurtEntitiesAround(this.position(), 10.0F, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 1.2F, 2.0F, false, false);
            }
            if (this.getAnimation() == ANIMATION_RIGHT_KICK && this.getAnimationTick() == 8) {
                Vec3 armPos = this.position().add(rotateOffsetVec(new Vec3(-2, 0, 2.5F), 0, this.yBodyRot));
                this.hurtEntitiesAround(armPos, 5.0F, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 0.8F, 2.0F, false, false);
            }
            if (this.getAnimation() == ANIMATION_LEFT_KICK && this.getAnimationTick() == 8) {
                Vec3 armPos = this.position().add(rotateOffsetVec(new Vec3(2, 0, 2.5F), 0, this.yBodyRot));
                this.hurtEntitiesAround(armPos, 5.0F, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE) * 0.8F, 2.0F, false, false);
            }
            if ((this.getAnimation() == ANIMATION_LEFT_WHIP || this.getAnimation() == ANIMATION_RIGHT_WHIP) && this.getAnimationTick() > 20 && this.getAnimationTick() < 30) {
                this.hurtEntitiesAround(this.tailPart2.position(), 12.0F, (float) this.getAttributeValue(Attributes.ATTACK_DAMAGE), 2.0F, this.isEnraged(), true);
            }
            if (this.getAnimation() == ANIMATION_SPEW_FLAMES && this.getAnimationTick() > 10 && this.getAnimationTick() < 70) {
                burnWithBreath(13);
            }
            if (postStopTicks > 0) {
                postStopTicks--;
                if (this.screenShakeAmount < 3.0F) {
                    this.screenShakeAmount = 3.0F;
                }
                tickStompAttack();
            }
            if (reducedDamageTicks > 0) {
                reducedDamageTicks--;
            }
            if (!this.isNoAi() && tickCount % 10 == 0) {
                LivingEntity target = this.getTarget();
                Player closestPlayer = level().getNearestPlayer(this, 150.0D);
                if (target != null && target.isAlive() && !(target instanceof Player) && closestPlayer == null) {
                    this.heal(6);
                }
            }
        }
        if (!this.isNoAi()) {
            if (tickCount % 60 == 0 && this.getAnimation() != ANIMATION_ROAR && this.isAlive()) {
                if (this.level().isClientSide) {
                    Vec3 headCenter = this.headPart.centeredPosition();
                    Vec3 nostilRightDelta = rotateOffsetVec(new Vec3(-0.25F, 0.5F, 0.75F), this.getXRot(), this.getYHeadRot());
                    Vec3 nostilRight = headCenter.add(nostilRightDelta);
                    Vec3 nostilLeftDelta = rotateOffsetVec(new Vec3(0.25F, 0.5F, 0.75F), this.getXRot(), this.getYHeadRot());
                    Vec3 nostilLeft = headCenter.add(nostilLeftDelta);
                    nostilRightDelta = nostilRightDelta.scale(0.1F);
                    nostilLeftDelta = nostilLeftDelta.scale(0.1F);
                    ParticleOptions types = ACParticleRegistry.TEPHRA_SMALL.get();
                    level().addParticle(types, nostilRight.x, nostilRight.y, nostilRight.z, nostilRightDelta.x, nostilRightDelta.y, nostilRightDelta.z);
                    level().addParticle(types, nostilLeft.x, nostilLeft.y, nostilLeft.z, nostilLeftDelta.x, nostilLeftDelta.y, nostilLeftDelta.z);
                }
                this.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_SNORT.get(), this.getSoundVolume(), this.getVoicePitch());
            }
            if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() > 10 && this.getAnimationTick() < 50) {
                if (!level().isClientSide) {
                    scareMobs();
                }
            }
        }
        if (this.getAnimation() == ANIMATION_SUMMON && this.getAnimationTick() > 5 && !this.hasEffect(MobEffects.INVISIBILITY)) {
            this.setInvisible(false);
            this.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_SUMMON.get(), 3.0F, 1.0F);
        }
        if (this.getAnimation() == ANIMATION_ROAR && this.getAnimationTick() == 2 && this.isAlive()) {
            this.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_ROAR.get(), 5.0F, this.getVoicePitch());
        }
        if (this.getAnimation() == ANIMATION_SPEW_FLAMES && this.getAnimationTick() == 10) {
            this.playSound(ACSoundRegistry.LUXTRUCTOSAURUS_BREATH.get(), 5.0F, this.getVoicePitch());
        }
        prevOnGround = this.onGround();
    }

@Override
    protected void registerGoals() {
        super.registerGoals();
        this.goalSelector.addGoal(0, new FloatGoal(this));
        this.goalSelector.addGoal(0, new EntityNaga.FlyOutOfWaterGoal(this));
        this.goalSelector.addGoal(5, new EntityNaga.WanderGoal());
        this.goalSelector.addGoal(4, new EntityNaga.AIFlyAroundTarget(this));
        this.goalSelector.addGoal(3, new EntityNaga.AIFlyTowardsTarget(this));
        this.goalSelector.addGoal(6, new RandomLookAroundGoal(this));
        this.goalSelector.addGoal(6, new LookAtPlayerGoal(this, Player.class, 8.0F));
        this.targetSelector.addGoal(1, new HurtByTargetGoal(this));
        this.targetSelector.addGoal(2, new NearestAttackableTargetGoal<Player>(this, Player.class, 0, true, true, target -> target.blockPosition().closerThan(getRestrictCenter(), getRestrictRadius())) {
            @Override
            public boolean canContinueToUse() {
                return super.canContinueToUse() && getTarget() != null && getTarget().blockPosition().closerThan(getRestrictCenter(), getRestrictRadius()) && getAnimation() == NO_ANIMATION;
            }
        });
        this.goalSelector.addGoal(2, new SimpleAnimationAI<EntityNaga>(this, FLAP_ANIMATION, false) {
            @Override
            public void start() {
                super.start();
                playSound(MMSounds.ENTITY_NAGA_FLAP_1.get(), 2, (float) (0.85 + random.nextFloat() * 0.2));
            }

            @Override
            public void tick() {
                super.tick();
                if (getAnimationTick() >= 4 && getAnimationTick() <= 9) {
                    setDeltaMovement(getDeltaMovement().add(0, 0.1, 0));
                }
            }
        });
        this.goalSelector.addGoal(2, new SimpleAnimationAI<EntityNaga>(this, DODGE_ANIMATION, false));
        this.goalSelector.addGoal(2, new AnimationProjectileAttackAI<EntityNaga>(this, SPIT_ANIMATION, 30, null) {
            @Override
            public void start() {
                super.start();
                playSound(MMSounds.ENTITY_NAGA_ACID_CHARGE.get(), 2, 1);
            }

            @Override
            public void tick() {
                super.tick();
                if (interrupted) return;
                //if (getAnimationTick() == 1) playSound(MMSounds.ENTITY_NAGA_ACID_CHARGE, 2, 1);
                if (getAnimationTick() < 9) setDeltaMovement(getDeltaMovement().add(0, 0.015, 0));
//                if (getAnimationTick() == 28) motionY -= 0.2;
            }
        });
        this.goalSelector.addGoal(2, new SimpleAnimationAI<EntityNaga>(this, SWOOP_ANIMATION, true) {
            @Override
            public void start() {
                super.start();
                playSound(MMSounds.ENTITY_NAGA_FLAP_1.get(), 2, 0.7f);
            }

            @Override
            public void tick() {
                super.tick();
                if (interrupted) return;

                Vec3 v = new Vec3(0, 0, 0);

                int phase1Length = 15;
                int phase2Length = 21;
                LivingEntity target = getTarget();
                if (getAnimationTick() < phase1Length) {
                    if (target != null) {
                        entity.lookAt(target, 100, 100);
                        entity.lookControl.setLookAt(target, 30F, 30F);
                    }
                }
                if (getAnimationTick() < 23 + phase2Length) {
                    if (getAnimationTick() >= 1 && getAnimationTick() < 1 + phase1Length) {
                        float frame = (getAnimationTick() - 1) / (float) phase1Length;
                        v = v.add(new Vec3(
                                1.9f * Math.sin(frame * Math.PI * 2) * frame,
                                -1.9f * Math.sin(frame * Math.PI * 2) * frame,
                                0.8f * Math.sin(frame * Math.PI * 2)
                        ));
                    } else if (getAnimationTick() >= 16) {
                        if (getAnimationTick() == 23) {
                            if (target != null) {
                                swoopTargetCorrectY = 0.09f * (float) Math.abs(getY() - target.getY());
                                swoopTargetCorrectX = 0.1f * (float) Math.sqrt((getX() - target.getX()) * (getX() - target.getX()) + (getZ() - target.getZ()) * (getZ() - target.getZ()));
                                if (swoopTargetCorrectX > 1.8f) swoopTargetCorrectX = 1.8f;
                                if (swoopTargetCorrectY > 2f) swoopTargetCorrectY = 2f;
                            }
                            else {
                                swoopTargetCorrectX = swoopTargetCorrectY = 1;
                            }
                        }
                        if (getAnimationTick() >= 23 && getAnimationTick() < 23 + phase2Length) {
                            float frame = (getAnimationTick() - 23) / (float) phase2Length;
                            v = v.add(new Vec3(
                                    swoopTargetCorrectX * 1.4 * (1 - Math.exp(2 * (frame - 1))),
                                    swoopTargetCorrectY * -1.5 * (Math.cos(frame * Math.PI) * (1 - Math.exp(7 * (frame - 1)))),
                                    0
                            ));

                            List<LivingEntity> entitiesHit = getEntityLivingBaseNearby(4, 4, 4, 4);
                            for (LivingEntity entityHit : entitiesHit) {
                                if (entityHit instanceof EntityNaga) continue;
                                doHurtTarget(entityHit);
                            }
                        }
                    }

                    v = v.yRot((float) Math.toRadians(-getYRot() - 90));
                    setDeltaMovement(v.x, v.y, v.z);
                }

                if (getAnimationTick() == 22) MMCommon.PROXY.playNagaSwoopSound(entity);

                if (getAnimationTick() == 7) playSound(MMSounds.ENTITY_NAGA_GRUNT_3.get(), 2, 1f);
                if (getAnimationTick() == 22) playSound(MMSounds.ENTITY_NAGA_ROAR_1.get(), 3, 1f);
            }
        });
        this.goalSelector.addGoal(2, new SimpleAnimationAI<EntityNaga>(this, HURT_TO_FALL_ANIMATION, true) {
            @Override
            public void tick() {
//                System.out.println("Hello");
            }
        });
        this.goalSelector.addGoal(2, new SimpleAnimationAI<EntityNaga>(this, LAND_ANIMATION, true) {
            @Override
            public void start() {
                super.start();
                playSound(MMSounds.MISC_GROUNDHIT_2.get(), 1.5f, 1);
            }
        });
        this.goalSelector.addGoal(1, new SimpleAnimationAI<EntityNaga>(this, GET_UP_ANIMATION, true) {
            @Override
            public void tick() {
                super.tick();
                if (getAnimationTick() == 13) playSound(MMSounds.ENTITY_NAGA_FLAP_1.get(), 2f, 1);

                if (getAnimationTick() == 15) {
                    setDeltaMovement(getDeltaMovement().add(0, 1.6, 0));
                }
            }
        });
        this.goalSelector.addGoal(2, new SimpleAnimationAI<EntityNaga>(this, TAIL_DEMO_ANIMATION, false));
    }

public void setupAnim(EntityBigCat big_cat, float limbSwing, float limbSwingAmount, float ageInTicks, float netHeadYaw, float headPitch) {
        this.resetToDefaultPose();
        animate(big_cat);
        float globalSpeed = 2.4f;
        float globalDegree = 1f;
        limbSwingAmount = Math.min(0.6F, limbSwingAmount * 2);
        limbSwing *= 0.5F;

        // Model Parameters
        float tail_scale = big_cat.hasFluffyTail() ? 2 : 1;
        for (AdvancedModelBox tail_part : bodyParts_tail) {
            tail_part.scaleX = tail_scale;
            tail_part.scaleY = tail_scale;
        }

        // Breathing Animation
        boolean isPurring = big_cat.getAnimation() == EntityBigCat.IDLE_STRETCH && big_cat.getAnimationTick() > 20;
        final double scaleX = Math.sin(ageInTicks * (isPurring ? 2 : 1 / 20F));
        final double scaleY = Math.sin(ageInTicks / (isPurring ? 8 : 16));
        this.body_main.setScale((float) (1F + scaleX * 0.08F), (float) (1F + scaleY * 0.06F), 1.0F);
        this.body_abdomen.setScale((float) (1F + scaleX * 0.06F), (float) (1F + scaleY * 0.06F), 1.0F);
        bob(body_main, 0.4F * globalSpeed, 0.03F, false, ageInTicks / 20, 2);
        bob(arm_right_upper, 0.4F * globalSpeed, 0.03F, false, -ageInTicks / 20, 2);
        bob(arm_left_upper, 0.4F * globalSpeed, 0.03F, false, -ageInTicks / 20, 2);
        bob(leg_right_upper, 0.4F * globalSpeed, 0.03F, false, -ageInTicks / 20, 2);
        bob(leg_left_upper, 0.4F * globalSpeed, 0.03F, false, -ageInTicks / 20, 2);
        if (!big_cat.isSleeping()) {
            chainFlap(bodyParts_tail, 0.3F * globalSpeed, 0.25F * globalDegree, 0.5F, ageInTicks / 6, 2);
        }

        // Blinking Animation
        if (!big_cat.shouldRenderEyes()) {
            this.eye_right.setRotationPoint(-2.5F, -2.0F, -4.5F);
            this.eye_right_1.setRotationPoint(2.5F, -2.0F, -4.5F);
        }

        // Head Tracking Animation
        if (!big_cat.isSleeping()) {
            this.faceTarget(netHeadYaw, headPitch, 3, head_neck);
            this.faceTarget(netHeadYaw, headPitch, 3, head_main);
        }

        // Pitch/Yaw handler
        if (big_cat.isInWater() && !big_cat.isOnGround()) {
            limbSwing = ageInTicks / 3;
            limbSwingAmount = 0.5f;
            this.body_main.rotationPointY += 4; // Model offset to make the Big Cat "sink" in water (while not drowning)
            this.setRotateAngle(head_neck, -0.18203784098300857F, 0.0F, 0.0F);
            float pitch = Mth.clamp(big_cat.getXRot() - 10, -25F, 25.0F);
            this.setRotateAngle(body_main, (float) (pitch * Math.PI / 180F), 0, 0);
        }

        // Movement Animation
        float newZ = Mth.lerp(0.4F, this.tailX, this.tail_1.defaultRotationX + (float)big_cat.getCurrentSpeed() * 2);
        this.tail_1.rotateAngleX = newZ;
        this.tailX = newZ;
        if (big_cat.canMove()) {
            if (big_cat.getCurrentSpeed() > 0.1f || big_cat.isAngry()) { // Running animation
                bob(body_main, 0.5F * globalSpeed, 0.5F, false, limbSwing, limbSwingAmount);
                walk(body_main, 0.5f * globalSpeed, 0.5f * globalDegree, true, 0.5F, 0f, limbSwing, limbSwingAmount);
                walk(head_neck, 0.5f * globalSpeed, -0.5f * globalDegree, true, 0.5F, 0f, limbSwing, limbSwingAmount);
                walk(body_abdomen, 0.5f * globalSpeed, 0.3f * globalDegree, false, 0.5F, 0f, limbSwing, limbSwingAmount);
                bob(arm_right_upper, 0.5F * globalSpeed, 0.8F, false, limbSwing, limbSwingAmount);
                walk(arm_right_upper, 0.5f * globalSpeed, globalDegree, true, 0F, 0f, limbSwing, limbSwingAmount);
                walk(arm_right_lower, 0.5f * globalSpeed, 0.6f * globalDegree, true, 0.2F, 0.2f, limbSwing, limbSwingAmount);
                walk(arm_right_paw, 0.5f * globalSpeed, 2f * globalDegree, false, 0.4F, 1.0f, limbSwing, limbSwingAmount);
                bob(arm_left_upper, 0.5F * globalSpeed, 0.8F, false, limbSwing, limbSwingAmount);
                walk(arm_left_upper, 0.5f * globalSpeed, globalDegree, true, 0.6F, 0f, limbSwing, limbSwingAmount);
                walk(arm_left_lower, 0.5f * globalSpeed, 0.6f * globalDegree, true, 0.8F, 0.2f, limbSwing, limbSwingAmount);
                walk(arm_left_paw, 0.5f * globalSpeed, 2f * globalDegree, false, 1F, 1.0f, limbSwing, limbSwingAmount);
                bob(leg_right_upper, 0.5F * globalSpeed, 0.8F, false, limbSwing, limbSwingAmount);
                walk(leg_right_upper, 0.5f * globalSpeed, globalDegree, true, 1.4F, 0f, limbSwing, limbSwingAmount);
                walk(leg_right_lower, 0.5f * globalSpeed, 0.6f * globalDegree, true, 1.6F, 0.2f, limbSwing, limbSwingAmount);
                walk(leg_right_paw, 0.5f * globalSpeed, 0.8f * globalDegree, false, 1.8F, 0.0f, limbSwing, limbSwingAmount);
                bob(leg_left_upper, 0.5F * globalSpeed, 0.8F, false, limbSwing, limbSwingAmount);
                walk(leg_left_upper, 0.5f * globalSpeed, globalDegree, true, 2F, 0f, limbSwing, limbSwingAmount);
                walk(leg_left_lower, 0.5f * globalSpeed, 0.6f * globalDegree, true, 2.2F, 0.2f, limbSwing, limbSwingAmount);
                walk(leg_left_paw, 0.5f * globalSpeed, 0.8f * globalDegree, false, 2.4F, 0.0f, limbSwing, limbSwingAmount);
            } else { // Walking Animation
                bob(arm_right_upper, 0.5F * globalSpeed, 0.8F, false, limbSwing, limbSwingAmount);
                walk(arm_right_upper, 0.5f * globalSpeed, globalDegree, true, 0F, 0f, limbSwing, limbSwingAmount);
                walk(arm_right_lower, 0.5f * globalSpeed, 0.6f * globalDegree, true, 0.2F, 0.2f, limbSwing, limbSwingAmount);
                walk(arm_right_paw, 0.5f * globalSpeed, 2f * globalDegree, false, 0.4F, 1.0f, limbSwing, limbSwingAmount);
