@Override
	public float getPlaySpeed(LivingEntityPatch<?> entitypatch, DynamicAnimation animation) {
        Phase phase = this.getPhaseByTime(entitypatch.getAnimator().getPlayerFor(this.getAccessor()).getElapsedTime());
        float speedFactor = this.getProperty(AttackAnimationProperty.ATTACK_SPEED_FACTOR).orElse(1.0F);
        Optional<Float> property = this.getProperty(AttackAnimationProperty.BASIS_ATTACK_SPEED);
        InteractionHand effective = phase.effectiveHand(entitypatch);
        float correctedSpeed = property.map((value) -> entitypatch.getAttackSpeed(effective) / value).orElse(this.getTotalTime() * entitypatch.getAttackSpeed(effective));
        correctedSpeed = Math.round(correctedSpeed * 1000.0F) / 1000.0F;

        return 1.0F + (correctedSpeed - 1.0F) * speedFactor;
	}

public boolean startSkillHolding(HoldableSkill holdableSkill) {
		Optional<SkillContainer> containerOptional = this.getSkillContainerFor(holdableSkill.asSkill());

		if (containerOptional.isEmpty()) {
			return false;
		} else {
			holdableSkill.startHolding(containerOptional.get());
			this.lastChargingTick = this.original.tickCount;
			this.holdingSkill = holdableSkill;
			return true;
		}
	}

public static void handle(MountedEntityKeyMessage message, Supplier<NetworkEvent.Context> context) {
        context.get().enqueueWork(() -> {
            Player playerSided = context.get().getSender();
            if (context.get().getDirection().getReceptionSide() == LogicalSide.CLIENT) {
                playerSided = AlexsCaves.PROXY.getClientSidePlayer();
            }
            Entity parent = playerSided.level().getEntity(message.mountId);
            Entity keyPresser = playerSided.level().getEntity(message.playerId);
            if (keyPresser != null && parent instanceof KeybindUsingMount mount && keyPresser instanceof Player && keyPresser.isPassengerOfSameVehicle(parent)) {
                mount.onKeyPacket(keyPresser, message.type);
            }
        });
        context.get().setPacketHandled(true);
    }

public List<Entity> getCollidingEntities(LivingEntityPatch<?> entitypatch, AttackAnimation animation, float prevElapsedTime, float elapsedTime, float attackSpeed) {
			Set<Entity> entities = Sets.newHashSet();

			for (Pair<Joint, Collider> colliderInfo : this.colliders) {
				Collider collider = colliderInfo.getSecond();

				if (collider == null) {
					collider = entitypatch.getColliderMatching(this.hand);
				}

				entities.addAll(collider.updateAndSelectCollideEntity(entitypatch, animation, prevElapsedTime, elapsedTime, colliderInfo.getFirst(), attackSpeed));
			}

			return new ArrayList<>(entities);
		}

@Override
    public void tick(LivingEntityPatch<?> entitypatch) {
        this.getProperty(StaticAnimationProperty.NO_PHYSICS).ifPresent((val) -> {
            if (val) {
                entitypatch.getOriginal().noPhysics = true;
            }
        });

        this.getProperty(StaticAnimationProperty.TICK_EVENTS).ifPresent((events) -> {
            entitypatch.getAnimator().getPlayer(this.getAccessor()).ifPresent(player -> {
                for (AnimationEvent<?, ?> event : events) {
                    float prevElapsed = player.getPrevElapsedTime();
                    float elapsed = player.getElapsedTime();

                    event.execute(entitypatch, this.getAccessor(), prevElapsed, elapsed);
                }
            });
        });
    }

private void handleAnimationPayload(SPAnimatorControl payload) {
        if (this.isLogicalClient()) {
            throw new IllegalStateException("Cannot send animation sync payload in client side.");
        }

        switch (payload.action()) {
        case SOFT_PAUSE, HARD_PAUSE -> {
            throw new UnsupportedOperationException("Only PLAY, PLAY_INSTANTLY, STOP and RESERVE are allowed");
        }
        default -> {
        }
        }

        if (payload.action().syncVariables()) {
            payload.animationVariables().addAll(this.getAnimator().getVariables().createPendingVariablesPayloads(payload.animation()));
        }

        this.sendToAllPlayersTrackingMe(payload);
    }

@Override @ClientOnly
	public void renderDebugging(PoseStack poseStack, MultiBufferSource buffer, LivingEntityPatch<?> entitypatch, float playbackTime, float partialTicks) {
        AnimationPlayer animPlayer = entitypatch.getAnimator().getPlayerFor(this.getAccessor());
        if (animPlayer == null) {
            return;
        }

		float prevElapsedTime = animPlayer.getPrevElapsedTime();
		float elapsedTime = animPlayer.getElapsedTime();
		Phase phase = this.getPhaseByTime(playbackTime);

		for (Pair<Joint, Collider> colliderInfo : phase.colliders) {
			Collider collider = colliderInfo.getSecond();

			if (collider == null) {
				collider = entitypatch.getColliderMatching(phase.hand);
			}

			collider.draw(poseStack, buffer, entitypatch, this, colliderInfo.getFirst(), prevElapsedTime, elapsedTime, partialTicks, this.getPlaySpeed(entitypatch, this));
		}
	}

@Override
	protected void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, @Nullable Orientation orientation, boolean movedByPiston) {
		if (level.isClientSide()) {
			return;
		}

		TowerDeviceVariant variant = state.getValue(STATE);

		if (variant == TowerDeviceVariant.BUILDER_INACTIVE && level.hasNeighborSignal(pos)) {
			level.setBlockAndUpdate(pos, state.setValue(STATE, TowerDeviceVariant.BUILDER_ACTIVE));
			level.playSound(null, pos, TFSounds.BUILDER_ON.get(), SoundSource.BLOCKS, 0.3F, 0.6F);
			level.scheduleTick(pos, this, 4);
		}

		if (variant == TowerDeviceVariant.BUILDER_ACTIVE && !level.hasNeighborSignal(pos)) {
			level.setBlockAndUpdate(pos, state.setValue(STATE, TowerDeviceVariant.BUILDER_INACTIVE));
			level.playSound(null, pos, TFSounds.BUILDER_OFF.get(), SoundSource.BLOCKS, 0.3F, 0.6F);
			level.scheduleTick(pos, this, 4);
		}

		if (variant == TowerDeviceVariant.BUILDER_TIMEOUT && !level.hasNeighborSignal(pos)) {
			level.setBlockAndUpdate(pos, state.setValue(STATE, TowerDeviceVariant.BUILDER_INACTIVE));
		}
	}

public EpicFightDamageSource getEpicFightDamageSource(DamageSource originalSource, LivingEntityPatch<?> entitypatch, Entity target, Phase phase) {
		if (phase == null) {
			phase = this.getPhaseByTime(entitypatch.getAnimator().getPlayerFor(this.getAccessor()).getElapsedTime());
		}

		EpicFightDamageSource epicfightSource;

		if (originalSource instanceof EpicFightDamageSource epicfightDamageSource) {
			epicfightSource = epicfightDamageSource;
		} else {
			epicfightSource = EpicFightDamageSources.fromVanillaDamageSource(originalSource).setAnimation(this.getAccessor());
		}

		phase.getProperty(AttackPhaseProperty.DAMAGE_MODIFIER).ifPresent(epicfightSource::attachDamageModifier);

		phase.getProperty(AttackPhaseProperty.ARMOR_NEGATION_MODIFIER).ifPresent(epicfightSource::attachArmorNegationModifier);

		phase.getProperty(AttackPhaseProperty.IMPACT_MODIFIER).ifPresent(epicfightSource::attachImpactModifier);

		phase.getProperty(AttackPhaseProperty.STUN_TYPE).ifPresent(epicfightSource::setStunType);

		phase.getProperty(AttackPhaseProperty.SOURCE_TAG).ifPresent(opt -> opt.forEach(epicfightSource::addRuntimeTag));

		phase.getProperty(AttackPhaseProperty.EXTRA_DAMAGE).ifPresent(opt -> opt.forEach(epicfightSource::addExtraDamage));

		phase.getProperty(AttackPhaseProperty.SOURCE_LOCATION_PROVIDER).ifPresentOrElse(
            opt -> epicfightSource.setInitialPosition(opt.apply(entitypatch)),
            () -> epicfightSource.setInitialPosition(entitypatch.getOriginal().position()))
        ;

		return epicfightSource;
	}

public static Pair<Boolean, Boolean> dealMixedDamage(LivingEntity target, DamageSource source1, float amount1, DamageSource source2, float amount2) {
        if (target.level().isClientSide()) return Pair.of(false, false);
        boolean flag1 = source1.getEntity() != null && target.isAlliedTo(source1.getEntity());
        boolean flag2 = source2.getEntity() != null && target.isAlliedTo(source2.getEntity());
        if(flag1 || flag2) return Pair.of(false, false);
        LivingData data = DataHandler.getData(target, DataHandler.LIVING_DATA);
        data.setLastDamage(-1);
        float damageSoFar = 0;
        float origLastDamage = target.lastHurt;
        boolean hit1 = target.hurt(source1, amount1);
        boolean hit1Registered = hit1;
        if (data.getLastDamage() != -1) {
            hit1Registered = true;
        }
        if (data.getLastDamage() != 0) {
            damageSoFar += amount1;
        }
        target.lastHurt = Math.max(target.lastHurt - amount1, 0);
        data.setLastDamage(-1);
        boolean hit2 = target.hurt(source2, amount2);
        if (data.getLastDamage() != 0) {
            damageSoFar += amount2;
        }
        target.lastHurt = origLastDamage;
        if (damageSoFar > target.lastHurt) target.lastHurt = damageSoFar;

        if (hit2 && hit1Registered) {
            onHit2(target, source2);
            if (target instanceof Player) {
                SoundEvent sound = SoundEvents.PLAYER_HURT;
                if (source2.is(DamageTypeTags.IS_FIRE)) sound = SoundEvents.PLAYER_HURT_ON_FIRE;
                else if (source2.is(DamageTypeTags.IS_DROWNING)) sound = SoundEvents.PLAYER_HURT_DROWN;
                target.playSound(sound, 1F, getSoundPitch(target));
            }
        }
        return Pair.of(hit1, hit2);
    }

@Override
	public void updateHeldItem(CapabilityItem fromCap, CapabilityItem toCap, ItemStack from, ItemStack to, InteractionHand hand) {
		if (this.isHoldingAny()) {
			this.getSkillContainerFor(this.holdingSkill.asSkill()).ifPresent((container) -> {
				container.getSkill().cancelOnServer(container, null);
				EpicFightNetworkManager.sendToPlayer(SPSkillFeedback.expired(container.getSlot()), this.original);
			});

			this.resetHolding();
		}

		// Drive innate-skill registration from the cap that's actually the active combat weapon.
		// In offhand-only mirror mode the mainhand is bare/fist and has no innate, so without
		// this the WEAPON_INNATE skill slot stays empty -- the long-press would never fire
		// Liechtenauer/Battojutsu/etc. for an offhand-only weapon. Use the post-update value of
		// each slot when computing primary so the cap reflects what the player will be holding
		// after this updateHeldItem call returns.
		ItemStack postMainItem = (hand == InteractionHand.MAIN_HAND) ? to : this.original.getMainHandItem();
		ItemStack postOffItem = (hand == InteractionHand.OFF_HAND) ? to : this.original.getOffhandItem();
		CapabilityItem postMainCap = (hand == InteractionHand.MAIN_HAND) ? toCap : this.getHoldingItemCapability(InteractionHand.MAIN_HAND);
		CapabilityItem postOffCap = (hand == InteractionHand.OFF_HAND) ? toCap : this.getHoldingItemCapability(InteractionHand.OFF_HAND);
		boolean mainBareAfter = postMainCap.isEmpty()
				|| postMainCap.getWeaponCategory() == CapabilityItem.WeaponCategories.FIST;
		// Keep parity with {@link LivingEntityPatch#isMirrorMode}: shields don't trigger mirror mode.
		boolean offhandRealAfter = !postOffCap.isEmpty()
				&& postOffCap.getWeaponCategory() != CapabilityItem.WeaponCategories.FIST
				&& postOffCap.getWeaponCategory() != CapabilityItem.WeaponCategories.SHIELD;
		boolean willMirror = mainBareAfter && offhandRealAfter;
		CapabilityItem innateCap = willMirror ? postOffCap : postMainCap;
		ItemStack innateItem = willMirror ? postOffItem : postMainItem;
		innateCap.changeWeaponInnateSkill(this, innateItem);
        EpicFightEventHooks.Player.CHANGE_INNATE_SKILL.postWithListener(new ChangeInnateSkillEvent(this, from, fromCap, to, toCap, hand), this.getEventListener());

		if (hand == InteractionHand.OFF_HAND) {
			if (!from.isEmpty()) {
				from.getAttributeModifiers().forEach(EquipmentSlot.MAINHAND, (attribute, modifier) -> {
					if (Attributes.ATTACK_SPEED.equals(attribute)) {
						this.original.getAttribute(EpicFightAttributes.OFFHAND_ATTACK_SPEED).removeModifier(modifier);
					}
				});
			}

			if (!fromCap.isEmpty()) {
				Multimap<Holder<Attribute>, AttributeModifier> modifiers = fromCap.getAllAttributeModifiers();
				modifiers.get(EpicFightAttributes.ARMOR_NEGATION).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_ARMOR_NEGATION)::removeModifier);
				modifiers.get(EpicFightAttributes.IMPACT).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_IMPACT)::removeModifier);
				modifiers.get(EpicFightAttributes.MAX_STRIKES).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_MAX_STRIKES)::removeModifier);
				modifiers.get(Attributes.ATTACK_SPEED).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_ATTACK_SPEED)::removeModifier);
			}

			if (!to.isEmpty()) {
				to.getAttributeModifiers().forEach(EquipmentSlot.MAINHAND, (attribute, modifier) -> {
					if (Attributes.ATTACK_SPEED.equals(attribute)) {
						this.original.getAttribute(EpicFightAttributes.OFFHAND_ATTACK_SPEED).addTransientModifier(modifier);
					}
				});
			}

			if (!toCap.isEmpty()) {
				Multimap<Holder<Attribute>, AttributeModifier> modifiers = toCap.getAttributeModifiers(this);
				modifiers.get(EpicFightAttributes.ARMOR_NEGATION).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_ARMOR_NEGATION)::addTransientModifier);
				modifiers.get(EpicFightAttributes.IMPACT).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_IMPACT)::addTransientModifier);
				modifiers.get(EpicFightAttributes.MAX_STRIKES).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_MAX_STRIKES)::addTransientModifier);
				modifiers.get(Attributes.ATTACK_SPEED).forEach(this.original.getAttribute(EpicFightAttributes.OFFHAND_ATTACK_SPEED)::addTransientModifier);
			}
		}

		this.modifyLivingMotionByCurrentItem(true);

		super.updateHeldItem(fromCap, toCap, from, to, hand);
	}

public static void build(AnimationBuilder builder) {
        BIPED_IDLE = builder.nextAccessor("biped/living/idle", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_WALK = builder.nextAccessor("biped/living/walk", (accessor) -> new MovementAnimation(true, accessor, Armatures.BIPED));
        BIPED_FLYING = builder.nextAccessor("biped/living/fly", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_CREATIVE_IDLE = builder.nextAccessor("biped/living/creative_idle", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_CREATIVE_FLYING = builder.nextAccessor("biped/living/creative_fly", (accessor) ->
            new SelectiveAnimation((entitypatch) -> {
                    Vec3 view = entitypatch.getOriginal().getViewVector(1.0F);
                    Vec3 move = entitypatch.getOriginal().getDeltaMovement();

                    double dot = view.dot(move);

                    return dot < 0.0D ? 1 : 0;
                },
                accessor,
                new DirectStaticAnimation(EpicFightSharedConstants.GENERAL_ANIMATION_TRANSITION_TIME, true, EpicFightMod.identifier("biped/living/creative_fly_forward"), Armatures.BIPED)
                    .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.FLYING_CORRECTION),
                new DirectStaticAnimation(EpicFightSharedConstants.GENERAL_ANIMATION_TRANSITION_TIME, true, EpicFightMod.identifier("biped/living/creative_fly_backward"), Armatures.BIPED)
                    .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.FLYING_CORRECTION2)
            )
        );

        BIPED_HOLD_CROSSBOW = builder.nextAccessor("biped/living/hold_crossbow", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_HOLD_MAP_TWOHAND = builder.nextAccessor("biped/living/hold_map_twohand", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.MAP_ARMS_CORRECTION)
        );
        BIPED_HOLD_MAP_OFFHAND = builder.nextAccessor("biped/living/hold_map_offhand", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.MAP_ARMS_CORRECTION)
        );
        BIPED_HOLD_MAP_MAINHAND = builder.nextAccessor("biped/living/hold_map_mainhand", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.MAP_ARMS_CORRECTION)
        );
        BIPED_HOLD_MAP_TWOHAND_MOVE = builder.nextAccessor("biped/living/hold_map_twohand_move", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.MAP_ARMS_CORRECTION)
        );
        BIPED_HOLD_MAP_OFFHAND_MOVE = builder.nextAccessor("biped/living/hold_map_offhand_move", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.MAP_ARMS_CORRECTION)
        );
        BIPED_HOLD_MAP_MAINHAND_MOVE = builder.nextAccessor("biped/living/hold_map_mainhand_move", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.POSE_MODIFIER, Animations.ReusableSources.MAP_ARMS_CORRECTION)
        );

        BIPED_RUN = builder.nextAccessor("biped/living/run", (accessor) -> new MovementAnimation(true, accessor, Armatures.BIPED));
        BIPED_SNEAK = builder.nextAccessor("biped/living/sneak", (accessor) -> new MovementAnimation(true, accessor, Armatures.BIPED));
        BIPED_SWIM = builder.nextAccessor("biped/living/swim", (accessor) -> new MovementAnimation(true, accessor, Armatures.BIPED));
        BIPED_FLOAT = builder.nextAccessor("biped/living/float", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_KNEEL = builder.nextAccessor("biped/living/kneel", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_FALL = builder.nextAccessor("biped/living/fall", (accessor) -> new StaticAnimation(true, accessor, Armatures.BIPED));
        BIPED_MOUNT = builder.nextAccessor("biped/living/mount", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.FIXED_HEAD_ROTATION, true)
                .addProperty(StaticAnimationProperty.ON_ITEM_CHANGE_EVENT, SimpleEvent.create(Animations.ReusableSources.SET_TOOLS_BACK_WHEN_MOUNT_AND_ITEM_CHANGED, Side.CLIENT))
                .addEvents(StaticAnimationProperty.ON_BEGIN_EVENTS, SimpleEvent.create(Animations.ReusableSources.SET_TOOLS_BACK_WHEN_MOUNT, Side.CLIENT))
                .addEvents(StaticAnimationProperty.ON_END_EVENTS, SimpleEvent.create(Animations.ReusableSources.REVERT_TO_HANDS, Side.CLIENT))
        );

        BIPED_SIT = builder.nextAccessor("biped/living/sit", (accessor) ->
            new StaticAnimation(true, accessor, Armatures.BIPED)
                .addProperty(StaticAnimationProperty.FIXED_HEAD_ROTATION, true)
        );

        BIPED_DIG = builder.nextAccessor("biped/living/dig", (accessor) ->
            new SelectiveAnimation(
                (entitypatch) -> entitypatch.getOriginal().swingingArm == InteractionHand.OFF_HAND ? 1 : 0,
                accessor,
                new DirectStaticAnimation(0.1F, true, EpicFightMod.identifier("biped/living/dig_mainhand"), Armatures.BIPED),
                new DirectStaticAnimation(0.1F, true, EpicFightMod.identifier("biped/living/dig_offhand"), Armatures.BIPED)
            )
        );

        // Equip flourish: short upper-body clip played when an item arrives in a held slot.
        // The mainhand variants sit on COMPOSITE_LAYER/HIGH with a "right_arms" mask; the offhand
        // variants sit on COMPOSITE_LAYER/HIGHEST with a "left_arms" mask and apply pose mirroring
        // at runtime via MirroredAnimation. Putting them above MIDDLE means hold_uchigatana etc.
        // (which live on MIDDLE/LOWEST) keep ticking on the layers underneath, so when the
        // flourish finishes those clips just resume rather than needing a re-trigger.
        BIPED_EQUIP_ITEM = builder.nextAccessor("biped/living/equip_item", (accessor) ->
            new StaticAnimation(0.1F, false, accessor, Armatures.BIPED)
        );

        BIPED_UNEQUIP_ITEM = builder.nextAccessor("biped/living/unequip_item", (accessor) ->
            new ReversedAnimation(0.1F, false, accessor, BIPED_EQUIP_ITEM, Armatures.BIPED)
        );

        BIPED_EQUIP_ITEM_OFFHAND = builder.nextAccessor("biped/living/equip_item_offhand", (accessor) ->
            new MirroredAnimation(0.1F, false, accessor, BIPED_EQUIP_ITEM, Armatures.BIPED)
        );

        BIPED_UNEQUIP_ITEM_OFFHAND = builder.nextAccessor("biped/living/unequip_item_offhand", (accessor) ->
            new MirroredAnimation(0.1F, false, accessor, BIPED_UNEQUIP_ITEM, Armatures.BIPED)
        );

        BIPED_BOW_AIM = builder.nextAccessor("biped/combat/bow_aim", (accessor) -> new AimAnimation(true, accessor, "biped/combat/bow_aim_mid", "biped/combat/bow_aim_up", "biped/combat/bow_aim_down", "biped/combat/bow_aim_lying", Armatures.BIPED));
