@Override
    public void outgoingDamageEvent(LivingDamageEvent.Pre event, LivingEntity attacker, LivingEntity target, ItemStack stack) {
        if (attacker.level() instanceof ServerLevel level) {
            var source = event.getSource();
            var heldItem = attacker.getMainHandItem();
            if (source.is(net.minecraft.world.damagesource.DamageTypes.PLAYER_ATTACK) || source.is(MalumDamageTypes.TYRVING)) {
                if (!heldItem.isEmpty()) {
                    event.setNewDamage(event.getNewDamage() * 0.1f);
                    if (heldItem.isDamageableItem()) {
                        heldItem.hurtAndBreak(10, attacker, MAINHAND);
                    }
                }
                return;
            }
            if (source.is(MalumTags.DamageTypes.TRIGGERS_SCYTHE_COMBO)) {
                MalumScytheItem.ScytheDamage damage = MalumScytheItem.getScytheDamage(source, attacker);
                float physicalDamage = damage.physicalDamage();
                float magicDamage = damage.magicDamage();
                float damageScalar = 0.1f;
                float chance = 0.3f;
                int extraHits = 2;
                if (damage.isBoomerang()) {
                    chance *= 2;
                }
                float average = (physicalDamage + magicDamage) / 2;
                physicalDamage *= physicalDamage / average * damageScalar;
                magicDamage *= magicDamage / average * damageScalar;
                if (MalumScytheItem.isEnhanced(attacker)) {
                    extraHits++;
                    chance += 0.1f;
                }
                if (attacker.getRandom().nextFloat() < chance) {
                    for (int i = 0; i < extraHits; i++) {
                        int delay = 4 + i * 3;
                        WorldEventHandler.addWorldEvent(level,
                                new DelayedDamageWorldEvent(target)
                                        .setAttacker(attacker, source.getDirectEntity())
                                        .setDamageData(physicalDamage, magicDamage, delay)
                                        .setPhysicalDamageType(MalumDamageTypes.SCYTHE_COMBO)
                                        .setSound(MalumSoundEvents.REAPER_CUT, 0.9f, 1.1f, 1));
                    }
                }
            }
        }
    }

public static void shieldPlayer(LivingIncomingDamageEvent event) {
        var entity = event.getEntity();
        if (entity.level().isClientSide()) {
            return;
        }
        var source = event.getSource();
        if (source.is(MalumTags.DamageTypes.BYPASSES_MALIGNANT_AEGIS)) {
            return;
        }
        if (!(event.getOriginalAmount() >= 2f)) {
            return;
        }
        var optional = MalignantInfluenceData.getMalignantAegisData(entity);
        if (optional.isEmpty()) {
            return;
        }
        var data = optional.get();
        int aegis = data.getMalignantAegis();
        if (aegis <= 0) {
            return;
        }
        data.reduceAegis(1);
        var container = event.getContainer();
        int invulnerabilityTicks = Math.min(container.getPostAttackInvulnerabilityTicks() * 2, 40);
        container.setPostAttackInvulnerabilityTicks(invulnerabilityTicks);
        entity.syncData(MalumAttachmentTypes.MALIGNANT_INFLUENCE);

        if (data.getMalignantAegis() == 0) {
            SoundPlayer.create(MalumSoundEvents.MALIGNANT_AEGIS_DEPLETE).play(entity);
        }
        else {
            SoundPlayer.create(MalumSoundEvents.MALIGNANT_AEGIS_HIT).volume(0.25f).play(entity);
        }
        event.setCanceled(true);
    }

@Override
    public void tick() {
        if (!level.isClientSide) {
            if (tickCount % delay == 0) {
                //do volley
                int arrows = arrowsPerRow;
                float speed = .85f;
                Vec3 motion = Vec3.directionFromRotation(getXRot() - tickCount / 5f * 7, this.getYRot()).normalize().scale(speed);
                Vec3 orth = new Vec3(-Mth.cos(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI), 0, Mth.sin(-this.getYRot() * Mth.DEG_TO_RAD - (float) Math.PI));
                for (int i = 0; i < arrows; i++) {
                    float distance = (i - arrows * .5f) * .7f;
                    SmallMagicArrow arrow = new SmallMagicArrow(this.level, this.getOwner());
                    arrow.setDamage(this.getDamage());
                    var spawn = this.position().add(orth.scale(distance));
                    arrow.setPos(spawn);
                    arrow.shoot(motion.add(Utils.getRandomVec3(.04f)));
                    arrow.setOwner(this.getOwner());
                    level.addFreshEntity(arrow);
                    MagicManager.spawnParticles(level, ParticleTypes.FIREWORK, spawn.x, spawn.y, spawn.z, 2, .1, .1, .1, .05, false);
                }
                level.playSound(null, position().x, position().y, position().z, SoundEvents.FIREWORK_ROCKET_LAUNCH, SoundSource.NEUTRAL, 3.0f, 1.1f + Utils.random.nextFloat() * .3f);
                level.playSound(null, position().x, position().y, position().z, SoundRegistry.BOW_SHOOT.get(), SoundSource.NEUTRAL, 2, Utils.random.nextIntBetweenInclusive(16, 20) * .1f);
            } else if (tickCount > rows * delay) {
                discard();
            }
        }
    }

@Override
    public void tick() {
        super.tick();
        // swirling line towards destination during delay
        if (startPos != null && !level.isClientSide && tickCount < getDelay()) {
            float f = tickCount / (float) getDelay();
            Vec3 forward = position().subtract(startPos).multiply(1, 0, 1).normalize();
            Vec3 right = new Vec3(-forward.z, 0, forward.x);
            Vec3 spawn = startPos.lerp(position(), f);
            float phase = tickCount * 0.5f;
            float threshold = 3;
            float distance = (float) position().subtract(spawn).horizontalDistance();
            float strength = distance > threshold ? 1 : distance / threshold;
            Vec3 oscillation = right.scale(Mth.sin(phase) * 2 * strength);
            spawn = Utils.moveToRelativeGroundLevel(level, spawn.add(oscillation), 6);
            float yrot = Utils.getAngle(startPos.x, startPos.z, getX(), getZ());
            if (!level.getBlockState(BlockPos.containing(spawn).below()).isAir()) {
                ExtendedEvokerFang fang = new ExtendedEvokerFang(level, spawn.x, spawn.y, spawn.z, yrot, 0, this.getOwner() instanceof LivingEntity e ? e : null, this.getDamage());
                level.addFreshEntity(fang);
            }
        }
    }

@Override
    public void tick() {
        if (!isSpawnDagger() && age++ < delay) {
            var owner = getOwner();
            float strength = .5f;
            if (owner != null && isTrackingOwner()) {
                //use client delta motion instead of jittery server information
                Vec3 ownerMotion = owner.position().subtract(owner.xOld, owner.yOld, owner.zOld);
                setPos(this.position().add(ownerMotion));
            }
            var target = getTargetEntity();
            if (target != null) {
                var targetPos = target.getBoundingBox().getCenter();
                Vec3 targetMotion = targetPos.subtract(this.position()).normalize().scale(this.getSpeed());
                Vec3 currentMotion = getDeltaMovement();
                deltaMovementOld = currentMotion;
                this.setDeltaMovement(currentMotion.add(targetMotion.subtract(currentMotion).scale(strength)));
                // prevent first-tick flicker due to deltaMoveOld being "uninitialized" on our first tick
                if (tickCount == 1) {
                    deltaMovementOld = getDeltaMovement();
                }
            }
            if (age == delay) {
                if (isGrounded) {
                    if (Utils.random.nextFloat() < 0.25f) {
                        playSound(SoundRegistry.FIERY_DAGGER_THROW.get(), 0.75f, Utils.random.nextIntBetweenInclusive(90, 110) * .01f);
                    }
                } else {
                    playSound(SoundRegistry.FIERY_DAGGER_THROW.get(), 2f, Utils.random.nextIntBetweenInclusive(90, 110) * .01f);
                }
                // do an initial near-collision check since we cannot organically hit things if we originate inside their hitbox (such as if they are standing on a dagger)
                var hits = level.getEntities(this, this.getBoundingBox().inflate(0.4f), this::canHitEntity);
                EntityHitResult hitResult = hits.isEmpty() ? null : new EntityHitResult(hits.getFirst());
                if (hitResult != null) {
                    onHit(hitResult);
                }
            }
            if (level.isClientSide) {
                level.addParticle(ParticleHelper.EMBERS, getX(), getY() + getBbHeight() * .5f, getZ(), 0, 0, 0);
            }
        } else {
            super.tick();
        }
    }

@Override
    public void tick() {
        if (!level.isClientSide) {
            if (age > 300) {
                //IronsSpellbooks.LOGGER.debug("Discarding void Tentacle (age:{})", age);
                this.discard();
            } else {
                if (age < 280 && (age) % 20 == 0) {
                    level.getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(0.5)).forEach(this::dealDamage);
                    if (Utils.random.nextFloat() < .15f) {
                        playSound(SoundRegistry.VOID_TENTACLES_AMBIENT.get(), 1.5f, .5f + Utils.random.nextFloat() * .65f);
                    }
                }
            }
            if (age == 260 && Utils.random.nextFloat() < .3f) {
                playSound(SoundRegistry.VOID_TENTACLES_LEAVE.get(), 2, 1);
            }
        } else {
            if (age < 280) {
                if (Utils.random.nextFloat() < .15f) {
                    level.addParticle(ParticleHelper.VOID_TENTACLE_FOG, getX() + Utils.getRandomScaled(.5f), getY() + Utils.getRandomScaled(.5f) + .2f, getZ() + Utils.getRandomScaled(.5f), Utils.getRandomScaled(2f), -random.nextFloat() * .5f, Utils.getRandomScaled(2f));
                }
            }
        }
        age++;
    }

@Override
